INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-1', 'en', 'Bài 1: Giáo dục & Trường học (1) - CEFR C1', 'CEFR C1', 'C1 · Giáo dục', '24 từ vựng Tiếng Anh CEFR C1 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5001, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prospectus', 'en-c1-1', 'prospectus', '/prəˈspektəs/', 'C1', 'sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng); bản cáo bạch; tài liệu giới thiệu đầu tư (giải thích về cơ hội đầu tư hoặc kinh doanh)', 'n.', NULL, NULL, 'Trong bối cảnh giáo dục thường chỉ sách giới thiệu tuyển sinh, trong tài chính có thể chỉ bản cáo bạch.', 'I checked the college prospectus for photography courses.', NULL, 'Tôi đã xem cẩm nang tuyển sinh của trường cao đẳng để tìm các khóa học nhiếp ảnh.', '{"wordId":"prospectus","ukIpa":"/prəˈspektəs/","usIpa":"/prəˈspektəs/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"a document describing a school or university for potential students","vi":"sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng)"},{"pos":"n.","en":"a document explaining an investment or business opportunity","vi":"bản cáo bạch; tài liệu giới thiệu đầu tư (giải thích về cơ hội đầu tư hoặc kinh doanh)"}],"examples":[{"en":"I checked the college prospectus for photography courses.","vi":"Tôi đã xem cẩm nang tuyển sinh của trường cao đẳng để tìm các khóa học nhiếp ảnh.","audioKind":"ex"},{"en":"A university prospectus should provide accurate information about tuition fees, course content, and available student support.","vi":"Sách hướng dẫn tuyển sinh của trường đại học nên cung cấp thông tin chính xác về học phí, nội dung khóa học và các dịch vụ hỗ trợ sinh viên có sẵn.","audioKind":"ex2"}],"collocations":[{"en":"university prospectus","vi":"tài liệu tuyển sinh đại học"},{"en":"request a prospectus","vi":"yêu cầu cung cấp tài liệu tuyển sinh"},{"en":"issue a prospectus","vi":"phát hành bản cáo bạch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong bối cảnh giáo dục thường chỉ sách giới thiệu tuyển sinh, trong tài chính có thể chỉ bản cáo bạch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coeducation', 'en-c1-1', 'coeducation', '/ˌkoʊedʒəˈkeɪʃən/', 'C1', 'giáo dục nam nữ chung trường; nền giáo dục hỗn hợp nam nữ (việc giáo dục nam và nữ cùng nhau trong một cơ sở giáo dục)', 'n.', 'coeducational (adj.)', 'Đồng nghĩa: mixed education · Trái nghĩa: single-sex education', 'Là danh từ không đếm được; tính từ là coeducational.', 'My grandparents first experienced coeducation at their village school.', NULL, 'Ông bà tôi lần đầu tiên trải nghiệm việc học chung nam nữ tại ngôi trường ở làng của họ.', '{"wordId":"coeducation","ukIpa":"/ˌkəʊedʒʊˈkeɪʃən/","usIpa":"/ˌkoʊedʒəˈkeɪʃən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"The education of boys and girls together in the same institution.","vi":"giáo dục nam nữ chung trường; nền giáo dục hỗn hợp nam nữ (việc giáo dục nam và nữ cùng nhau trong một cơ sở giáo dục)"}],"examples":[{"en":"My grandparents first experienced coeducation at their village school.","vi":"Ông bà tôi lần đầu tiên trải nghiệm việc học chung nam nữ tại ngôi trường ở làng của họ.","audioKind":"ex"},{"en":"Supporters of coeducation argue that learning together helps boys and girls develop mutual respect.","vi":"Những người ủng hộ giáo dục nam nữ chung trường lập luận rằng việc cùng nhau học tập giúp nam và nữ phát triển sự tôn trọng lẫn nhau.","audioKind":"ex2"}],"collocations":[{"en":"benefits of coeducation","vi":"lợi ích của giáo dục nam nữ chung trường"},{"en":"support coeducation","vi":"ủng hộ giáo dục nam nữ chung trường"},{"en":"introduce coeducation","vi":"thực hiện giáo dục nam nữ chung trường"}],"wordFamily":["coeducational (adj.)"],"synonyms":["mixed education"],"antonyms":["single-sex education"],"tipVi":"Là danh từ không đếm được; tính từ là coeducational.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instructive', 'en-c1-1', 'instructive', '/ɪnˈstrʌktɪv/', 'C1', 'có tính giáo dục; mang lại nhiều bài học bổ ích', 'adj.', 'instruct (v.), instruction (n.), instructor (n.)', 'Đồng nghĩa: educational, informative', 'Nhấn mạnh việc mang lại kiến thức hoặc giúp hiểu vấn đề, không có nghĩa là ra lệnh hay chỉ đạo.', 'Watching my grandfather repair the clock was surprisingly instructive.', NULL, 'Ngồi xem ông tôi sửa chiếc đồng hồ hóa ra lại là một trải nghiệm mang tính hướng dẫn và học hỏi bất ngờ.', '{"wordId":"instructive","ukIpa":"/ɪnˈstrʌktɪv/","usIpa":"/ɪnˈstrʌktɪv/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"providing useful knowledge or helping someone understand something","vi":"có tính giáo dục; mang lại nhiều bài học bổ ích"}],"examples":[{"en":"Watching my grandfather repair the clock was surprisingly instructive.","vi":"Ngồi xem ông tôi sửa chiếc đồng hồ hóa ra lại là một trải nghiệm mang tính hướng dẫn và học hỏi bất ngờ.","audioKind":"ex"},{"en":"Comparing different countries'' recycling systems can be instructive for policymakers seeking to reduce household waste.","vi":"Việc so sánh hệ thống tái chế của các quốc gia khác nhau có thể mang lại nhiều bài học hữu ích cho các nhà hoạch định chính sách đang muốn giảm thiểu rác thải sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"an instructive example","vi":"một ví dụ mang tính minh họa cao"},{"en":"an instructive experience","vi":"một trải nghiệm đầy bài học"},{"en":"find something instructive","vi":"thấy điều gì đó rất bổ ích"}],"wordFamily":["instruct (v.)","instruction (n.)","instructor (n.)"],"synonyms":["educational","informative"],"antonyms":[],"tipVi":"Nhấn mạnh việc mang lại kiến thức hoặc giúp hiểu vấn đề, không có nghĩa là ra lệnh hay chỉ đạo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_asterisk', 'en-c1-1', 'asterisk', '/ˈæstərɪsk/', 'C1', 'dấu hoa thị; dấu sao', 'n.', NULL, NULL, 'Từ này tận cùng bằng -risk, hãy chú ý phát âm chuẩn để không đọc nhầm thành -riks.', 'An asterisk beside the price points to extra delivery charges.', NULL, 'Dấu hoa thị bên cạnh mức giá dùng để chỉ các khoản phí giao hàng phát sinh thêm.', '{"wordId":"asterisk","ukIpa":"/ˈæstərɪsk/","usIpa":"/ˈæstərɪsk/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"A star-shaped symbol used to indicate a note or omission","vi":"dấu hoa thị; dấu sao"}],"examples":[{"en":"An asterisk beside the price points to extra delivery charges.","vi":"Dấu hoa thị bên cạnh mức giá dùng để chỉ các khoản phí giao hàng phát sinh thêm.","audioKind":"ex"},{"en":"Researchers often use an asterisk in tables to indicate results that meet a particular statistical threshold.","vi":"Các nhà nghiên cứu thường sử dụng dấu sao trong các bảng biểu để đánh dấu những kết quả đạt được mức ngưỡng thống kê nhất định.","audioKind":"ex2"}],"collocations":[{"en":"mark with an asterisk","vi":"đánh dấu bằng dấu sao"},{"en":"an asterisk beside","vi":"dấu hoa thị ở bên cạnh"},{"en":"add an asterisk","vi":"thêm dấu hoa thị"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ này tận cùng bằng -risk, hãy chú ý phát âm chuẩn để không đọc nhầm thành -riks.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_illiteracy', 'en-c1-1', 'illiteracy', '/ɪˈlɪtərəsi/', 'C1', 'nạn mù chữ; tình trạng không biết đọc biết viết; sự thiếu hiểu biết cơ bản', 'n.', 'illiterate (adj.), literate (adj.), literacy (n.)', 'Trái nghĩa: literacy', 'Illiteracy chỉ trạng thái không biết chữ; khi muốn chỉ người mù chữ, nên dùng các cấu trúc diễn đạt tính chất mô tả.', 'Evening classes helped my grandfather overcome illiteracy and read independently.', NULL, 'Các lớp học buổi tối đã giúp ông tôi xóa nạn mù chữ và có thể tự đọc sách một cách độc lập.', '{"wordId":"illiteracy","ukIpa":"/ɪˈlɪtərəsi/","usIpa":"/ɪˈlɪtərəsi/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"The inability to read and write.","vi":"nạn mù chữ; tình trạng không biết đọc biết viết"},{"pos":"n.","en":"A lack of basic knowledge in a particular subject.","vi":"sự thiếu hiểu biết cơ bản"}],"examples":[{"en":"Evening classes helped my grandfather overcome illiteracy and read independently.","vi":"Các lớp học buổi tối đã giúp ông tôi xóa nạn mù chữ và có thể tự đọc sách một cách độc lập.","audioKind":"ex"},{"en":"Reducing adult illiteracy can improve employment opportunities and enable more people to participate fully in society.","vi":"Việc giảm thiểu tình trạng mù chữ ở người lớn có thể cải thiện cơ hội việc làm và tạo điều kiện cho nhiều người tham gia đầy đủ hơn vào đời sống xã hội.","audioKind":"ex2"}],"collocations":[{"en":"adult illiteracy","vi":"tình trạng mù chữ ở người lớn"},{"en":"illiteracy rate","vi":"tỷ lệ mù chữ"},{"en":"combat illiteracy","vi":"xóa nạn mù chữ"},{"en":"financial illiteracy","vi":"sự thiếu hụt kiến thức tài chính"}],"wordFamily":["illiterate (adj.)","literate (adj.)","literacy (n.)"],"synonyms":[],"antonyms":["literacy"],"tipVi":"Illiteracy chỉ trạng thái không biết chữ; khi muốn chỉ người mù chữ, nên dùng các cấu trúc diễn đạt tính chất mô tả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adverbial', 'en-c1-1', 'adverbial', '/ədˈvɝːbiəl/', 'C1', 'thuộc về trạng ngữ; có chức năng như trạng ngữ; trạng ngữ', 'adj.', 'adverb (n.), adverbially (adv.)', NULL, 'adverb là từ loại; adverbial có thể chỉ chức năng trạng ngữ của từ, cụm từ hoặc mệnh đề.', 'Our teacher explained adverbial phrases using simple everyday examples.', NULL, 'Giáo viên của chúng tôi đã giải thích các cụm trạng ngữ bằng những ví dụ thường ngày đơn giản.', '{"wordId":"adverbial","ukIpa":"/ədˈvɜːbiəl/","usIpa":"/ədˈvɝːbiəl/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"functioning as an adverb or relating to adverbs","vi":"thuộc về trạng ngữ; có chức năng như trạng ngữ"},{"pos":"n.","en":"a word or group expressing when, where, how, or why","vi":"trạng ngữ"}],"examples":[{"en":"Our teacher explained adverbial phrases using simple everyday examples.","vi":"Giáo viên của chúng tôi đã giải thích các cụm trạng ngữ bằng những ví dụ thường ngày đơn giản.","audioKind":"ex"},{"en":"Understanding adverbial clauses helps language learners express relationships between events more precisely in academic writing.","vi":"Hiểu rõ các mệnh đề trạng ngữ giúp người học ngôn ngữ diễn đạt mối quan hệ giữa các sự việc chính xác hơn trong văn viết học thuật.","audioKind":"ex2"}],"collocations":[{"en":"adverbial phrase","vi":"cụm trạng ngữ"},{"en":"adverbial clause","vi":"mệnh đề trạng ngữ"},{"en":"adverbial modifier","vi":"từ bổ nghĩa trạng ngữ"}],"wordFamily":["adverb (n.)","adverbially (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"adverb là từ loại; adverbial có thể chỉ chức năng trạng ngữ của từ, cụm từ hoặc mệnh đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_textual', 'en-c1-1', 'textual', '/ˈtekstʃuəl/', 'C1', 'thuộc văn bản; thuộc về từ ngữ trong văn bản', 'adj.', 'text (n.), textually (adv.)', NULL, 'textual chỉ nội dung văn bản; textile chỉ hàng dệt may, tránh nhầm lẫn.', 'The editor made several textual changes to my story.', NULL, 'Biên tập viên đã thực hiện một số chỉnh sửa câu chữ đối với câu chuyện của tôi.', '{"wordId":"textual","ukIpa":"/ˈtekstʃuəl/","usIpa":"/ˈtekstʃuəl/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"relating to written words or the wording of a document","vi":"thuộc văn bản; thuộc về từ ngữ trong văn bản"}],"examples":[{"en":"The editor made several textual changes to my story.","vi":"Biên tập viên đã thực hiện một số chỉnh sửa câu chữ đối với câu chuyện của tôi.","audioKind":"ex"},{"en":"Students should support their interpretations with textual evidence rather than rely solely on personal reactions to a novel.","vi":"Học sinh nên củng cố cách hiểu của mình bằng các dẫn chứng trong văn bản thay vì chỉ dựa vào cảm nhận cá nhân đối với một cuốn tiểu thuyết.","audioKind":"ex2"}],"collocations":[{"en":"textual analysis","vi":"phân tích văn bản"},{"en":"textual evidence","vi":"dẫn chứng văn bản"},{"en":"textual criticism","vi":"nghiên cứu văn bản"},{"en":"textual changes","vi":"sửa đổi chữ viết"}],"wordFamily":["text (n.)","textually (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"textual chỉ nội dung văn bản; textile chỉ hàng dệt may, tránh nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_literate', 'en-c1-1', 'literate', '/ˈlɪtərət/', 'C1', 'biết đọc và biết viết; biết chữ; có kiến thức thực tế hoặc hiểu biết về một lĩnh vực hoặc công nghệ cụ thể', 'adj.', 'literacy (n.), illiterate (adj.), illiteracy (n.)', 'Trái nghĩa: illiterate', 'Thường đóng vai trò là tính từ; danh từ tương ứng là literacy dùng để chỉ khả năng đọc viết.', 'She became literate after attending evening classes for adults.', NULL, 'Cô ấy đã biết chữ sau khi tham gia các lớp học buổi tối dành cho người lớn.', '{"wordId":"literate","ukIpa":"/ˈlɪtərət/","usIpa":"/ˈlɪtərət/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Able to read and write.","vi":"biết đọc và biết viết; biết chữ"},{"pos":"adj.","en":"Having practical knowledge of a particular subject or technology.","vi":"có kiến thức thực tế hoặc hiểu biết về một lĩnh vực hoặc công nghệ cụ thể"}],"examples":[{"en":"She became literate after attending evening classes for adults.","vi":"Cô ấy đã biết chữ sau khi tham gia các lớp học buổi tối dành cho người lớn.","audioKind":"ex"},{"en":"Schools should ensure that students are digitally literate so they can evaluate online information critically.","vi":"Các trường học nên đảm bảo học sinh có năng lực số để các em có thể đánh giá thông tin trực tuyến một cách phản biện.","audioKind":"ex2"}],"collocations":[{"en":"fully literate","vi":"biết đọc viết đầy đủ"},{"en":"computer literate","vi":"thạo máy tính"},{"en":"digitally literate","vi":"có năng lực số"},{"en":"financially literate","vi":"có kiến thức tài chính cơ bản"}],"wordFamily":["literacy (n.)","illiterate (adj.)","illiteracy (n.)"],"synonyms":[],"antonyms":["illiterate"],"tipVi":"Thường đóng vai trò là tính từ; danh từ tương ứng là literacy dùng để chỉ khả năng đọc viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proofreading', 'en-c1-1', 'proofreading', '/ˈpruːfriːdɪŋ/', 'C1', 'việc hiệu đính; việc rà soát lỗi; hành động hiệu đính và sửa lỗi văn bản', 'n.', 'proofread (v.), proofreader (n.)', NULL, 'Hiệu đính tập trung vào lỗi chính tả, dấu câu và không đồng nghĩa với việc viết lại.', 'I am proofreading my sister''s essay at the kitchen table.', NULL, 'Tôi đang ngồi bên bàn bếp để hiệu đính bài luận cho chị gái mình.', '{"wordId":"proofreading","ukIpa":"/ˈpruːfriːdɪŋ/","usIpa":"/ˈpruːfriːdɪŋ/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"checking written material for errors before its final version","vi":"việc hiệu đính; việc rà soát lỗi"},{"pos":"v.","en":"checking written material and correcting errors","vi":"hành động hiệu đính và sửa lỗi văn bản"}],"examples":[{"en":"I am proofreading my sister''s essay at the kitchen table.","vi":"Tôi đang ngồi bên bàn bếp để hiệu đính bài luận cho chị gái mình.","audioKind":"ex"},{"en":"Careful proofreading helps students remove spelling errors and present their research more professionally.","vi":"Việc hiệu đính cẩn thận giúp học sinh loại bỏ lỗi chính tả và trình bày bài nghiên cứu của mình một cách chuyên nghiệp hơn.","audioKind":"ex2"}],"collocations":[{"en":"careful proofreading","vi":"hiệu đính cẩn thận"},{"en":"proofreading skills","vi":"kỹ năng hiệu đính"},{"en":"proofreading software","vi":"phần mềm hiệu đính"}],"wordFamily":["proofread (v.)","proofreader (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Hiệu đính tập trung vào lỗi chính tả, dấu câu và không đồng nghĩa với việc viết lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_communicative', 'en-c1-1', 'communicative', '/kəˈmjuːnɪkətɪv/', 'C1', 'cởi mở; hay nói; thích giao tiếp; thuộc về giao tiếp; dùng để giao tiếp', 'adj.', 'communicate (v.), communication (n.), uncommunicative (adj.)', 'Đồng nghĩa: talkative · Trái nghĩa: uncommunicative', 'Khi dùng cho người thì chỉ tính cách thích giao tiếp; khi dùng cho giáo dục thì nhấn mạnh vào kỹ năng tương tác.', 'My brother becomes more communicative during our evening walks.', NULL, 'Anh trai tôi trở nên cởi mở và hay nói hơn trong những buổi đi dạo buổi tối của chúng tôi.', '{"wordId":"communicative","ukIpa":"/kəˈmjuːnɪkətɪv/","usIpa":"/kəˈmjuːnɪkətɪv/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Willing to talk and share thoughts or information.","vi":"cởi mở; hay nói; thích giao tiếp"},{"pos":"adj.","en":"Relating to sharing information or expressing meaning.","vi":"thuộc về giao tiếp; dùng để giao tiếp"}],"examples":[{"en":"My brother becomes more communicative during our evening walks.","vi":"Anh trai tôi trở nên cởi mở và hay nói hơn trong những buổi đi dạo buổi tối của chúng tôi.","audioKind":"ex"},{"en":"Communicative activities in language classrooms help learners develop confidence and use new vocabulary in meaningful contexts.","vi":"Các hoạt động giao tiếp trong lớp học ngôn ngữ giúp người học xây dựng sự tự tin và sử dụng từ vựng mới trong các ngữ cảnh ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"communicative skills","vi":"kỹ năng giao tiếp"},{"en":"communicative competence","vi":"năng lực giao tiếp"},{"en":"communicative approach","vi":"phương pháp giao tiếp"}],"wordFamily":["communicate (v.)","communication (n.)","uncommunicative (adj.)"],"synonyms":["talkative"],"antonyms":["uncommunicative"],"tipVi":"Khi dùng cho người thì chỉ tính cách thích giao tiếp; khi dùng cho giáo dục thì nhấn mạnh vào kỹ năng tương tác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tertiary', 'en-c1-1', 'tertiary', '/ˈtɝːʃieri/', 'C1', 'thuộc bậc đại học; thuộc giáo dục đại học; thứ ba; ở mức độ hoặc giai đoạn thứ ba', 'adj.', NULL, NULL, 'Tertiary education dùng để chỉ giáo dục bậc cao sau bậc trung học phổ thông.', 'My sister hopes to enter tertiary education next year.', NULL, 'Chị tôi hy vọng sẽ bước vào bậc giáo dục đại học vào năm tới.', '{"wordId":"tertiary","ukIpa":"/ˈtɜːʃəri/","usIpa":"/ˈtɝːʃieri/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Relating to education at college or university level.","vi":"thuộc bậc đại học; thuộc giáo dục đại học"},{"pos":"adj.","en":"Third in order, level, or stage.","vi":"thứ ba; ở mức độ hoặc giai đoạn thứ ba"}],"examples":[{"en":"My sister hopes to enter tertiary education next year.","vi":"Chị tôi hy vọng sẽ bước vào bậc giáo dục đại học vào năm tới.","audioKind":"ex"},{"en":"Affordable tertiary education can improve social mobility by giving disadvantaged students access to professional qualifications.","vi":"Giáo dục đại học vừa túi tiền có thể cải thiện tính di động xã hội bằng cách giúp học sinh sinh viên có hoàn cảnh khó khăn tiếp cận được với các chứng chỉ chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"tertiary education","vi":"giáo dục đại học"},{"en":"tertiary sector","vi":"khu vực kinh tế thứ ba (dịch vụ)"},{"en":"tertiary care","vi":"dịch vụ y tế tuyến ba"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tertiary education dùng để chỉ giáo dục bậc cao sau bậc trung học phổ thông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thesis', 'en-c1-1', 'thesis', '/ˈθiːsɪs/', 'C1', 'luận văn; luận án tốt nghiệp; luận điểm; chủ đề nghiên cứu', 'n.', NULL, NULL, 'Dạng số nhiều là "theses"; từ này vừa có nghĩa là bài luận văn học thuật, vừa có nghĩa là ý kiến/luận điểm trung tâm.', 'Leila spent the weekend checking references for her thesis.', NULL, 'Leila đã dành cả cuối tuần để kiểm tra các tài liệu tham khảo cho luận văn của mình.', '{"wordId":"thesis","ukIpa":"/ˈθiːsɪs/","usIpa":"/ˈθiːsɪs/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"A long research paper written for a university degree.","vi":"luận văn; luận án tốt nghiệp"},{"pos":"n.","en":"A central claim that someone presents and supports with evidence.","vi":"luận điểm; chủ đề nghiên cứu"}],"examples":[{"en":"Leila spent the weekend checking references for her thesis.","vi":"Leila đã dành cả cuối tuần để kiểm tra các tài liệu tham khảo cho luận văn của mình.","audioKind":"ex"},{"en":"His thesis examines how access to public transport influences employment opportunities in disadvantaged urban communities.","vi":"Luận văn của anh ấy khảo sát cách thức tiếp cận phương tiện giao thông công cộng tác động như thế nào đến cơ hội việc làm ở các cộng đồng đô thị còn nhiều thiệt thòi.","audioKind":"ex2"}],"collocations":[{"en":"doctoral thesis","vi":"luận án tiến sĩ"},{"en":"write a thesis","vi":"viết luận văn"},{"en":"submit a thesis","vi":"nộp luận văn"},{"en":"central thesis","vi":"luận điểm cốt lõi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là \"theses\"; từ này vừa có nghĩa là bài luận văn học thuật, vừa có nghĩa là ý kiến/luận điểm trung tâm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cram', 'en-c1-1', 'cram', '/kræm/', 'C1', 'nhồi nhét; nhét đầy vào không gian chật hẹp; học cấp tốc; ôn thi nước rút', 'v.', 'crammed (adj.), cramming (n.)', 'Đồng nghĩa: stuff, pack', 'Dạng quá khứ là crammed; ôn thi nước rút dùng cram for.', 'She crammed three sweaters into her tiny overnight bag.', NULL, 'Cô ấy nhét ba chiếc áo len vào chiếc túi du lịch nhỏ xíu qua đêm.', '{"wordId":"cram","ukIpa":"/kræm/","usIpa":"/kræm/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"To force many things or people into a small space.","vi":"nhồi nhét; nhét đầy vào không gian chật hẹp"},{"pos":"v.","en":"To study intensively shortly before an examination.","vi":"học cấp tốc; ôn thi nước rút"}],"examples":[{"en":"She crammed three sweaters into her tiny overnight bag.","vi":"Cô ấy nhét ba chiếc áo len vào chiếc túi du lịch nhỏ xíu qua đêm.","audioKind":"ex"},{"en":"Students who cram for examinations may remember facts briefly but struggle to develop a deeper understanding.","vi":"Học sinh học ôn cấp tốc cho kỳ thi có thể nhớ kiến thức trong thời gian ngắn nhưng lại gặp khó khăn trong việc phát triển sự hiểu biết sâu sắc hơn.","audioKind":"ex2"}],"collocations":[{"en":"cram into a bag","vi":"nhét vào túi"},{"en":"cram a room with people","vi":"nhồi nhét người chật kín phòng"},{"en":"cram for an exam","vi":"ôn thi cấp tốc"}],"wordFamily":["crammed (adj.)","cramming (n.)"],"synonyms":["stuff","pack"],"antonyms":[],"tipVi":"Dạng quá khứ là crammed; ôn thi nước rút dùng cram for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indent', 'en-c1-1', 'indent', '/ɪnˈdent/', 'C1', 'thụt lề; lùi đầu dòng; làm cho lõm xuống; tạo rãnh', 'v.', 'indentation (n.), indented (adj.)', NULL, 'Chỉ việc dịch chuyển phần đầu dòng hướng vào phía trong, không phải làm ngắn toàn bộ nội dung dòng.', 'Please indent the first line of each new paragraph.', NULL, 'Vui lòng thụt lề dòng đầu tiên của mỗi đoạn văn mới.', '{"wordId":"indent","ukIpa":"/ɪnˈdent/","usIpa":"/ɪnˈdent/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"to start a line further inward than the surrounding lines","vi":"thụt lề; lùi đầu dòng"},{"pos":"v.","en":"to make a hollow or notch in a surface","vi":"làm cho lõm xuống; tạo rãnh"}],"examples":[{"en":"Please indent the first line of each new paragraph.","vi":"Vui lòng thụt lề dòng đầu tiên của mỗi đoạn văn mới.","audioKind":"ex"},{"en":"Students should learn to indent paragraphs consistently when formatting formal reports for their university courses.","vi":"Sinh viên nên học cách lùi đầu dòng các đoạn văn một cách nhất quán khi trình bày các báo cáo chính thức cho các môn học đại học.","audioKind":"ex2"}],"collocations":[{"en":"indent a paragraph","vi":"thụt lề một đoạn văn"},{"en":"indent the first line","vi":"lùi đầu dòng đầu tiên"}],"wordFamily":["indentation (n.)","indented (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ việc dịch chuyển phần đầu dòng hướng vào phía trong, không phải làm ngắn toàn bộ nội dung dòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aptitude', 'en-c1-1', 'aptitude', '/ˈæptɪtuːd/', 'C1', 'năng lực tự nhiên; năng khiếu; thiên hướng', 'n.', 'apt (adj.)', 'Đồng nghĩa: talent, gift, ability', 'Thường dùng cấu trúc aptitude for, đi sau là danh từ hoặc danh động từ.', 'Leila showed an aptitude for music at school.', NULL, 'Leila đã sớm bộc lộ năng khiếu âm nhạc khi còn đi học.', '{"wordId":"aptitude","ukIpa":"/ˈæptɪtjuːd/","usIpa":"/ˈæptɪtuːd/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"A natural ability to learn or do something well","vi":"năng lực tự nhiên; năng khiếu; thiên hướng"}],"examples":[{"en":"Leila showed an aptitude for music at school.","vi":"Leila đã sớm bộc lộ năng khiếu âm nhạc khi còn đi học.","audioKind":"ex"},{"en":"Schools should recognise practical aptitude as well as academic achievement when advising students about careers.","vi":"Các trường học nên ghi nhận cả năng lực thực tế lẫn thành tích học tập khi đưa ra định hướng nghề nghiệp cho học sinh.","audioKind":"ex2"}],"collocations":[{"en":"an aptitude for languages","vi":"năng khiếu ngoại ngữ"},{"en":"aptitude test","vi":"bài kiểm tra năng lực"},{"en":"show an aptitude for","vi":"thể hiện năng khiếu về"}],"wordFamily":["apt (adj.)"],"synonyms":["talent","gift","ability"],"antonyms":[],"tipVi":"Thường dùng cấu trúc aptitude for, đi sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reinforcement', 'en-c1-1', 'reinforcement', '/ˌriːɪnˈfɔːrsmənt/', 'C1', 'sự củng cố; sự gia cố; sự củng cố hành vi; lực lượng viện binh; lực lượng tăng viện', 'n.', 'reinforce (v.), reinforced (adj.)', 'Đồng nghĩa: strengthening', 'Khi chỉ lực lượng viện binh hoặc quân tiếp viện, từ này thường ở dạng số nhiều là reinforcements.', 'The old garden wall needs reinforcement before winter arrives.', NULL, 'Bức tường rào cũ của khu vườn cần được gia cố trước khi mùa đông đến.', '{"wordId":"reinforcement","ukIpa":"/ˌriːɪnˈfɔːsmənt/","usIpa":"/ˌriːɪnˈfɔːrsmənt/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"The process of making something stronger or more effective.","vi":"sự củng cố; sự gia cố"},{"pos":"n.","en":"Encouragement that makes a behaviour more likely to happen again.","vi":"sự củng cố hành vi"},{"pos":"n.","en":"Extra people sent to support an existing group or force.","vi":"lực lượng viện binh; lực lượng tăng viện"}],"examples":[{"en":"The old garden wall needs reinforcement before winter arrives.","vi":"Bức tường rào cũ của khu vườn cần được gia cố trước khi mùa đông đến.","audioKind":"ex"},{"en":"Positive reinforcement can encourage children to develop healthy habits without relying on punishment.","vi":"Sự củng cố tích cực có thể khuyến khích trẻ em hình thành các thói quen lành mạnh mà không cần phải dựa vào hình phạt.","audioKind":"ex2"}],"collocations":[{"en":"positive reinforcement","vi":"sự củng cố tích cực"},{"en":"structural reinforcement","vi":"gia cố kết cấu"},{"en":"send reinforcements","vi":"cử viện binh"}],"wordFamily":["reinforce (v.)","reinforced (adj.)"],"synonyms":["strengthening"],"antonyms":[],"tipVi":"Khi chỉ lực lượng viện binh hoặc quân tiếp viện, từ này thường ở dạng số nhiều là reinforcements.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_idiomatic', 'en-c1-1', 'idiomatic', '/ˌɪdiəˈmætɪk/', 'C1', 'dự nhiên; đúng cách diễn đạt bản ngữ; mang tính thành ngữ; chứa thành ngữ', 'adj.', 'idiom (n.), idiomatically (adv.)', 'Trái nghĩa: unidiomatic', 'Dự nhiên không có nghĩa là lạm dụng thành ngữ; các cụm từ kết hợp tự nhiên cũng thể hiện tính idiomatic.', 'Your sentence is correct, but this version sounds more idiomatic.', NULL, 'Câu của bạn đúng ngữ pháp, nhưng cách diễn đạt này nghe tự nhiên hơn.', '{"wordId":"idiomatic","ukIpa":"/ˌɪdiəˈmætɪk/","usIpa":"/ˌɪdiəˈmætɪk/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"natural and typical of how fluent speakers use a language","vi":"dự nhiên; đúng cách diễn đạt bản ngữ"},{"pos":"adj.","en":"containing or relating to expressions with nonliteral meanings","vi":"mang tính thành ngữ; chứa thành ngữ"}],"examples":[{"en":"Your sentence is correct, but this version sounds more idiomatic.","vi":"Câu của bạn đúng ngữ pháp, nhưng cách diễn đạt này nghe tự nhiên hơn.","audioKind":"ex"},{"en":"Regular exposure to authentic conversations helps language learners develop more idiomatic speech and greater confidence.","vi":"Việc thường xuyên tiếp xúc với các đoạn hội thoại thực tế giúp người học ngôn ngữ nói tự nhiên hơn và tự tin hơn.","audioKind":"ex2"}],"collocations":[{"en":"idiomatic English","vi":"tiếng Anh chuẩn bản ngữ"},{"en":"an idiomatic expression","vi":"một biểu thức thành ngữ"},{"en":"idiomatic usage","vi":"cách dùng theo quán ngữ"}],"wordFamily":["idiom (n.)","idiomatically (adv.)"],"synonyms":[],"antonyms":["unidiomatic"],"tipVi":"Dự nhiên không có nghĩa là lạm dụng thành ngữ; các cụm từ kết hợp tự nhiên cũng thể hiện tính idiomatic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enrich', 'en-c1-1', 'enrich', '/ɪnˈrɪtʃ/', 'C1', 'làm giàu; làm phong phú; làm sâu sắc; làm cho ai đó giàu có hơn; làm tăng dinh dưỡng; làm màu mỡ', 'v.', 'rich (adj.), richness (n.), enrichment (n.)', 'Đồng nghĩa: enhance, improve · Trái nghĩa: impoverish', 'enrich là ngoại động từ, thường đi với life, experience hoặc soil.', 'These weekend painting classes really enrich my daily life.', NULL, 'Những lớp học vẽ vào cuối tuần này thực sự làm phong phú thêm đời sống hàng ngày của tôi.', '{"wordId":"enrich","ukIpa":"/ɪnˈrɪtʃ/","usIpa":"/ɪnˈrɪtʃ/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"To improve something by adding value, interest, or experience.","vi":"làm giàu; làm phong phú; làm sâu sắc"},{"pos":"v.","en":"To make someone wealthier.","vi":"làm cho ai đó giàu có hơn"},{"pos":"v.","en":"To improve food or soil by adding useful substances.","vi":"làm tăng dinh dưỡng; làm màu mỡ"}],"examples":[{"en":"These weekend painting classes really enrich my daily life.","vi":"Những lớp học vẽ vào cuối tuần này thực sự làm phong phú thêm đời sống hàng ngày của tôi.","audioKind":"ex"},{"en":"International exchange programmes can enrich students'' education by exposing them to different perspectives and teaching methods.","vi":"Các chương trình trao đổi quốc tế có thể làm phong phú thêm kiến thức của học sinh bằng cách cho các em tiếp cận với nhiều góc nhìn và phương pháp giảng dạy khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"enrich people''s lives","vi":"làm phong phú cuộc sống con người"},{"en":"enrich understanding","vi":"làm sâu sắc thêm sự hiểu biết"},{"en":"enrich the soil","vi":"làm màu mỡ đất đai"}],"wordFamily":["rich (adj.)","richness (n.)","enrichment (n.)"],"synonyms":["enhance","improve"],"antonyms":["impoverish"],"tipVi":"enrich là ngoại động từ, thường đi với life, experience hoặc soil.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aural', 'en-c1-1', 'aural', '/ˈɔːrəl/', 'C1', 'thuộc thính giác; thuộc về tai', 'adj.', 'aurally (adv.)', 'Đồng nghĩa: auditory', 'aural chỉ thính giác; oral chỉ khẩu ngữ hoặc liên quan đến miệng.', 'Our music teacher uses games to develop aural skills.', NULL, 'Giáo viên âm nhạc của chúng tôi sử dụng các trò chơi để phát triển kỹ năng nghe.', '{"wordId":"aural","ukIpa":"/ˈɔːrəl/","usIpa":"/ˈɔːrəl/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Relating to hearing or the sense of hearing","vi":"thuộc thính giác; thuộc về tai"}],"examples":[{"en":"Our music teacher uses games to develop aural skills.","vi":"Giáo viên âm nhạc của chúng tôi sử dụng các trò chơi để phát triển kỹ năng nghe.","audioKind":"ex"},{"en":"Language courses should include regular aural practice so that learners can understand different accents in everyday communication.","vi":"Các khóa học ngôn ngữ nên bao gồm thực hành nghe thường xuyên để học viên có thể hiểu được các giọng điệu khác nhau trong giao tiếp hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"aural skills","vi":"kỹ năng nghe"},{"en":"aural training","vi":"luyện tập thính giác"},{"en":"aural comprehension","vi":"khả năng hiểu qua nghe"},{"en":"aural test","vi":"bài kiểm tra nghe"}],"wordFamily":["aurally (adv.)"],"synonyms":["auditory"],"antonyms":[],"tipVi":"aural chỉ thính giác; oral chỉ khẩu ngữ hoặc liên quan đến miệng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consolidate', 'en-c1-1', 'consolidate', '/kənˈsɑːlɪdeɪt/', 'C1', 'củng cố; làm vững chắc; hợp nhất; kết hợp; hợp lực', 'v.', 'consolidation (n.)', 'Đồng nghĩa: strengthen, reinforce, combine · Trái nghĩa: weaken', 'Có thể dùng để chỉ việc củng cố các thành tựu sẵn có hoặc hợp nhất nhiều phần lại với nhau.', 'I review my notes each evening to consolidate my learning.', NULL, 'Tôi ôn lại ghi chép của mình mỗi tối để củng cố kiến thức đã học.', '{"wordId":"consolidate","ukIpa":"/kənˈsɒlɪdeɪt/","usIpa":"/kənˈsɑːlɪdeɪt/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"To make an achievement, position, or skill stronger.","vi":"củng cố; làm vững chắc"},{"pos":"v.","en":"To combine separate things into a single effective whole.","vi":"hợp nhất; kết hợp; hợp lực"}],"examples":[{"en":"I review my notes each evening to consolidate my learning.","vi":"Tôi ôn lại ghi chép của mình mỗi tối để củng cố kiến thức đã học.","audioKind":"ex"},{"en":"Regular practical exercises help students consolidate their knowledge and apply theoretical concepts to unfamiliar situations.","vi":"Các bài tập thực hành thường xuyên giúp học sinh củng cố kiến thức và vận dụng các khái niệm lý thuyết vào các tình huống chưa quen thuộc.","audioKind":"ex2"}],"collocations":[{"en":"consolidate knowledge","vi":"củng cố kiến thức"},{"en":"consolidate power","vi":"củng cố quyền lực"},{"en":"consolidate gains","vi":"củng cố thành quả"},{"en":"consolidate debts","vi":"gộp các khoản nợ"}],"wordFamily":["consolidation (n.)"],"synonyms":["strengthen","reinforce","combine"],"antonyms":["weaken"],"tipVi":"Có thể dùng để chỉ việc củng cố các thành tựu sẵn có hoặc hợp nhất nhiều phần lại với nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comprise', 'en-c1-1', 'comprise', '/kəmˈpraɪz/', 'C1', 'bao gồm; gồm có; cấu thành; tạo nên', 'v.', NULL, 'Đồng nghĩa: consist of, include, constitute', 'Cấu trúc chuẩn nhất là: toàn thể comprises các phần, không đi kèm of.', 'The gift set comprises soap, lotion, and a towel.', NULL, 'Bộ quà tặng bao gồm xà phòng, kem dưỡng da và một chiếc khăn tắm.', '{"wordId":"comprise","ukIpa":"/kəmˈpraɪz/","usIpa":"/kəmˈpraɪz/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"to have particular people or things as parts","vi":"bao gồm; gồm có"},{"pos":"v.","en":"to be the parts or members that form something","vi":"cấu thành; tạo nên"}],"examples":[{"en":"The gift set comprises soap, lotion, and a towel.","vi":"Bộ quà tặng bao gồm xà phòng, kem dưỡng da và một chiếc khăn tắm.","audioKind":"ex"},{"en":"The proposed transport network will comprise bus routes and cycle lanes connecting residential areas with employment centres.","vi":"Mạng lưới giao thông được đề xuất sẽ bao gồm các tuyến xe buýt và làn đường dành cho xe đạp kết nối các khu dân cư với các trung tâm việc làm.","audioKind":"ex2"}],"collocations":[{"en":"comprise several sections","vi":"bao gồm vài phần"},{"en":"comprise a range of services","vi":"bao gồm nhiều dịch vụ"},{"en":"comprise the majority","vi":"chiếm phần lớn"}],"wordFamily":[],"synonyms":["consist of","include","constitute"],"antonyms":[],"tipVi":"Cấu trúc chuẩn nhất là: toàn thể comprises các phần, không đi kèm of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_legible', 'en-c1-1', 'legible', '/ˈledʒəbəl/', 'C1', 'rõ ràng; dễ đọc; dễ nhận biết', 'adj.', 'legibly (adv.), legibility (n.), illegible (adj.)', 'Đồng nghĩa: readable · Trái nghĩa: illegible', 'Từ legible nhấn mạnh nét chữ rõ dễ nhận diện; trong khi readable có thể chỉ nội dung hấp dẫn, dễ đọc.', 'Your handwriting is much more legible with this pen.', NULL, 'Chữ viết tay của bạn rõ ràng hơn hẳn khi dùng chiếc bút này.', '{"wordId":"legible","ukIpa":"/ˈledʒəbəl/","usIpa":"/ˈledʒəbəl/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Clear enough for written or printed words to be read.","vi":"rõ ràng; dễ đọc; dễ nhận biết"}],"examples":[{"en":"Your handwriting is much more legible with this pen.","vi":"Chữ viết tay của bạn rõ ràng hơn hẳn khi dùng chiếc bút này.","audioKind":"ex"},{"en":"Public information should be presented in a legible format so that older residents can access essential services independently.","vi":"Thông tin công cộng nên được trình bày ở định dạng dễ đọc để người cao tuổi có thể tiếp cận các dịch vụ thiết yếu một cách độc lập.","audioKind":"ex2"}],"collocations":[{"en":"legible handwriting","vi":"chữ viết rõ ràng"},{"en":"clearly legible","vi":"đọc rất rõ"},{"en":"barely legible","vi":"hầu như không thể đọc được"}],"wordFamily":["legibly (adv.)","legibility (n.)","illegible (adj.)"],"synonyms":["readable"],"antonyms":["illegible"],"tipVi":"Từ legible nhấn mạnh nét chữ rõ dễ nhận diện; trong khi readable có thể chỉ nội dung hấp dẫn, dễ đọc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_explanatory', 'en-c1-1', 'explanatory', '/ɪkˈsplænətɔːri/', 'C1', 'mang tính giải thích; mang tính minh họa', 'adj.', 'explain (v.), explanation (n.), self-explanatory (adj.)', 'Đồng nghĩa: clarifying', 'Thường bổ nghĩa cho notes, material; self-explanatory có nghĩa là tự giải thích, dễ hiểu.', 'The recipe includes explanatory pictures for each tricky step.', NULL, 'Công thức nấu ăn này có kèm theo hình ảnh giải thích cho từng bước khó.', '{"wordId":"explanatory","ukIpa":"/ɪkˈsplænətri/","usIpa":"/ɪkˈsplænətɔːri/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Giving information that makes something easier to understand.","vi":"mang tính giải thích; mang tính minh họa"}],"examples":[{"en":"The recipe includes explanatory pictures for each tricky step.","vi":"Công thức nấu ăn này có kèm theo hình ảnh giải thích cho từng bước khó.","audioKind":"ex"},{"en":"Public health campaigns should provide explanatory materials that help people understand both the benefits and limitations of medical screening.","vi":"Các chiến dịch y tế công cộng nên cung cấp các tài liệu giải thích giúp mọi người hiểu rõ cả lợi ích lẫn hạn chế của việc sàng lọc y tế.","audioKind":"ex2"}],"collocations":[{"en":"explanatory notes","vi":"chú thích giải thích"},{"en":"explanatory material","vi":"tài liệu giải thích"},{"en":"explanatory power","vi":"năng lực giải thích"}],"wordFamily":["explain (v.)","explanation (n.)","self-explanatory (adj.)"],"synonyms":["clarifying"],"antonyms":[],"tipVi":"Thường bổ nghĩa cho notes, material; self-explanatory có nghĩa là tự giải thích, dễ hiểu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overlap', 'en-c1-1', 'overlap', '/ˌoʊvɚˈlæp/', 'C1', 'phủ lên nhau; chồng chéo lên nhau; có điểm chung; phần chồng chéo; điểm chung', 'v.', 'overlapping (adj.)', 'Đồng nghĩa: intersect', 'Trọng âm của động từ rơi vào âm tiết thứ hai, trong khi danh từ rơi vào âm tiết đầu tiên; dạng quá khứ là overlapped.', 'The curtains overlap slightly in the middle of the window.', NULL, 'Tấm rèm cửa hơi chồng chéo lên nhau ở chính giữa cửa sổ.', '{"wordId":"overlap","ukIpa":"/ˌəʊvəˈlæp/","usIpa":"/ˌoʊvɚˈlæp/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"to partly cover something or share features with it","vi":"phủ lên nhau; chồng chéo lên nhau; có điểm chung"},{"pos":"n.","en":"an area or feature shared by two things","vi":"phần chồng chéo; điểm chung"}],"examples":[{"en":"The curtains overlap slightly in the middle of the window.","vi":"Tấm rèm cửa hơi chồng chéo lên nhau ở chính giữa cửa sổ.","audioKind":"ex"},{"en":"University courses often overlap in content, allowing students to explore connections between different academic disciplines.","vi":"Các khóa học đại học thường có nội dung chồng chéo lên nhau, giúp sinh viên khám phá sự liên kết giữa các ngành học khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"overlap with","vi":"chồng chéo với..."},{"en":"a significant overlap","vi":"sự chồng chéo đáng kể"},{"en":"overlapping responsibilities","vi":"trách nhiệm chồng chéo"}],"wordFamily":["overlapping (adj.)"],"synonyms":["intersect"],"antonyms":[],"tipVi":"Trọng âm của động từ rơi vào âm tiết thứ hai, trong khi danh từ rơi vào âm tiết đầu tiên; dạng quá khứ là overlapped.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_1_1', 'en-c1-1', 'Cách dùng “thesis” (n.) — luận văn; luận án tốt nghiệp', 'doctoral thesis  ·  write a thesis  ·  submit a thesis', 'Dạng số nhiều là "theses"; từ này vừa có nghĩa là bài luận văn học thuật, vừa có nghĩa là ý kiến/luận điểm trung tâm.', NULL, '[{"hanzi":"Leila spent the weekend checking references for her thesis.","pinyin":"","meaning":"Leila đã dành cả cuối tuần để kiểm tra các tài liệu tham khảo cho luận văn của mình."},{"hanzi":"His thesis examines how access to public transport influences employment opportunities in disadvantaged urban communities.","pinyin":"","meaning":"Luận văn của anh ấy khảo sát cách thức tiếp cận phương tiện giao thông công cộng tác động như thế nào đến cơ hội việc làm ở các cộng đồng đô thị còn nhiều thiệt thòi."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_1_2', 'en-c1-1', 'Cách dùng “overlap” (v.) — phủ lên nhau; chồng chéo lên nhau; có điểm chung', 'overlap with  ·  a significant overlap  ·  overlapping responsibilities', 'Trọng âm của động từ rơi vào âm tiết thứ hai, trong khi danh từ rơi vào âm tiết đầu tiên; dạng quá khứ là overlapped.', 'Họ từ (Word Family): overlapping (adj.) | Đồng nghĩa: intersect', '[{"hanzi":"The curtains overlap slightly in the middle of the window.","pinyin":"","meaning":"Tấm rèm cửa hơi chồng chéo lên nhau ở chính giữa cửa sổ."},{"hanzi":"University courses often overlap in content, allowing students to explore connections between different academic disciplines.","pinyin":"","meaning":"Các khóa học đại học thường có nội dung chồng chéo lên nhau, giúp sinh viên khám phá sự liên kết giữa các ngành học khác nhau."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_1_3', 'en-c1-1', 'Cách dùng “illiteracy” (n.) — nạn mù chữ; tình trạng không biết đọc biết viết', 'adult illiteracy  ·  illiteracy rate  ·  combat illiteracy', 'Illiteracy chỉ trạng thái không biết chữ; khi muốn chỉ người mù chữ, nên dùng các cấu trúc diễn đạt tính chất mô tả.', 'Họ từ (Word Family): illiterate (adj.), literate (adj.), literacy (n.) | Trái nghĩa: literacy', '[{"hanzi":"Evening classes helped my grandfather overcome illiteracy and read independently.","pinyin":"","meaning":"Các lớp học buổi tối đã giúp ông tôi xóa nạn mù chữ và có thể tự đọc sách một cách độc lập."},{"hanzi":"Reducing adult illiteracy can improve employment opportunities and enable more people to participate fully in society.","pinyin":"","meaning":"Việc giảm thiểu tình trạng mù chữ ở người lớn có thể cải thiện cơ hội việc làm và tạo điều kiện cho nhiều người tham gia đầy đủ hơn vào đời sống xã hội."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_1_4', 'en-c1-1', 'Cách dùng “communicative” (adj.) — cởi mở; hay nói; thích giao tiếp', 'communicative skills  ·  communicative competence  ·  communicative approach', 'Khi dùng cho người thì chỉ tính cách thích giao tiếp; khi dùng cho giáo dục thì nhấn mạnh vào kỹ năng tương tác.', 'Họ từ (Word Family): communicate (v.), communication (n.), uncommunicative (adj.) | Đồng nghĩa: talkative · Trái nghĩa: uncommunicative', '[{"hanzi":"My brother becomes more communicative during our evening walks.","pinyin":"","meaning":"Anh trai tôi trở nên cởi mở và hay nói hơn trong những buổi đi dạo buổi tối của chúng tôi."},{"hanzi":"Communicative activities in language classrooms help learners develop confidence and use new vocabulary in meaningful contexts.","pinyin":"","meaning":"Các hoạt động giao tiếp trong lớp học ngôn ngữ giúp người học xây dựng sự tự tin và sử dụng từ vựng mới trong các ngữ cảnh ý nghĩa."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_1_1', 'en-c1-1', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_1_1', 'ten_c1_1_1', 'prospectus', 'I checked the college prospectus for photography courses.', 'I checked the college prospectus for photography courses.', '/prəˈspektəs/', 'Tôi đã xem cẩm nang tuyển sinh của trường cao đẳng để tìm các khóa học nhiếp ảnh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_1_2', 'ten_c1_1_1', 'coeducation', 'My grandparents first experienced coeducation at their village school.', 'My grandparents first experienced coeducation at their village school.', '/ˌkoʊedʒəˈkeɪʃən/', 'Ông bà tôi lần đầu tiên trải nghiệm việc học chung nam nữ tại ngôi trường ở làng của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_1_3', 'ten_c1_1_1', 'instructive', 'Watching my grandfather repair the clock was surprisingly instructive.', 'Watching my grandfather repair the clock was surprisingly instructive.', '/ɪnˈstrʌktɪv/', 'Ngồi xem ông tôi sửa chiếc đồng hồ hóa ra lại là một trải nghiệm mang tính hướng dẫn và học hỏi bất ngờ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_1_4', 'ten_c1_1_1', 'asterisk', 'An asterisk beside the price points to extra delivery charges.', 'An asterisk beside the price points to extra delivery charges.', '/ˈæstərɪsk/', 'Dấu hoa thị bên cạnh mức giá dùng để chỉ các khoản phí giao hàng phát sinh thêm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_1_5', 'ten_c1_1_1', 'illiteracy', 'Evening classes helped my grandfather overcome illiteracy and read independently.', 'Evening classes helped my grandfather overcome illiteracy and read independently.', '/ɪˈlɪtərəsi/', 'Các lớp học buổi tối đã giúp ông tôi xóa nạn mù chữ và có thể tự đọc sách một cách độc lập.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_1_6', 'ten_c1_1_1', 'adverbial', 'Our teacher explained adverbial phrases using simple everyday examples.', 'Our teacher explained adverbial phrases using simple everyday examples.', '/ədˈvɝːbiəl/', 'Giáo viên của chúng tôi đã giải thích các cụm trạng ngữ bằng những ví dụ thường ngày đơn giản.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_1_7', 'ten_c1_1_1', 'textual', 'The editor made several textual changes to my story.', 'The editor made several textual changes to my story.', '/ˈtekstʃuəl/', 'Biên tập viên đã thực hiện một số chỉnh sửa câu chữ đối với câu chuyện của tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_1_8', 'ten_c1_1_1', 'literate', 'She became literate after attending evening classes for adults.', 'She became literate after attending evening classes for adults.', '/ˈlɪtərət/', 'Cô ấy đã biết chữ sau khi tham gia các lớp học buổi tối dành cho người lớn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_1_1_1', 'en-c1-1', 'ten_c1_1_1', 'listening', 'listening', 'I checked the college prospectus for photography courses.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy nhét ba chiếc áo len vào chiếc túi du lịch nhỏ xíu qua đêm.","Cô ấy đã biết chữ sau khi tham gia các lớp học buổi tối dành cho người lớn.","Leila đã dành cả cuối tuần để kiểm tra các tài liệu tham khảo cho luận văn của mình.","Tôi đã xem cẩm nang tuyển sinh của trường cao đẳng để tìm các khóa học nhiếp ảnh."]'::jsonb, 3, 'I checked the college prospectus for photography courses. → Tôi đã xem cẩm nang tuyển sinh của trường cao đẳng để tìm các khóa học nhiếp ảnh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_1_1_2', 'en-c1-1', 'ten_c1_1_1', 'listening', 'listening', 'My grandparents first experienced coeducation at their village school.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ông bà tôi lần đầu tiên trải nghiệm việc học chung nam nữ tại ngôi trường ở làng của họ.","Chị tôi hy vọng sẽ bước vào bậc giáo dục đại học vào năm tới.","Vui lòng thụt lề dòng đầu tiên của mỗi đoạn văn mới.","Biên tập viên đã thực hiện một số chỉnh sửa câu chữ đối với câu chuyện của tôi."]'::jsonb, 0, 'My grandparents first experienced coeducation at their village school. → Ông bà tôi lần đầu tiên trải nghiệm việc học chung nam nữ tại ngôi trường ở làng của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_1_1_3', 'en-c1-1', 'ten_c1_1_1', 'listening', 'listening', 'Watching my grandfather repair the clock was surprisingly instructive.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bộ quà tặng bao gồm xà phòng, kem dưỡng da và một chiếc khăn tắm.","Ông bà tôi lần đầu tiên trải nghiệm việc học chung nam nữ tại ngôi trường ở làng của họ.","Ngồi xem ông tôi sửa chiếc đồng hồ hóa ra lại là một trải nghiệm mang tính hướng dẫn và học hỏi bất ngờ.","Các lớp học buổi tối đã giúp ông tôi xóa nạn mù chữ và có thể tự đọc sách một cách độc lập."]'::jsonb, 2, 'Watching my grandfather repair the clock was surprisingly instructive. → Ngồi xem ông tôi sửa chiếc đồng hồ hóa ra lại là một trải nghiệm mang tính hướng dẫn và học hỏi bất ngờ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_1_2', 'en-c1-1', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_2_1', 'ten_c1_1_2', 'prospectus', 'A university prospectus should provide accurate information about tuition fees, course content, and available student support.', 'A university prospectus should provide accurate information about tuition fees, course content, and available student support.', '/prəˈspektəs/', 'Sách hướng dẫn tuyển sinh của trường đại học nên cung cấp thông tin chính xác về học phí, nội dung khóa học và các dịch vụ hỗ trợ sinh viên có sẵn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_2_2', 'ten_c1_1_2', 'coeducation', 'Supporters of coeducation argue that learning together helps boys and girls develop mutual respect.', 'Supporters of coeducation argue that learning together helps boys and girls develop mutual respect.', '/ˌkoʊedʒəˈkeɪʃən/', 'Những người ủng hộ giáo dục nam nữ chung trường lập luận rằng việc cùng nhau học tập giúp nam và nữ phát triển sự tôn trọng lẫn nhau.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_2_3', 'ten_c1_1_2', 'instructive', 'Comparing different countries'' recycling systems can be instructive for policymakers seeking to reduce household waste.', 'Comparing different countries'' recycling systems can be instructive for policymakers seeking to reduce household waste.', '/ɪnˈstrʌktɪv/', 'Việc so sánh hệ thống tái chế của các quốc gia khác nhau có thể mang lại nhiều bài học hữu ích cho các nhà hoạch định chính sách đang muốn giảm thiểu rác thải sinh hoạt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_2_4', 'ten_c1_1_2', 'asterisk', 'Researchers often use an asterisk in tables to indicate results that meet a particular statistical threshold.', 'Researchers often use an asterisk in tables to indicate results that meet a particular statistical threshold.', '/ˈæstərɪsk/', 'Các nhà nghiên cứu thường sử dụng dấu sao trong các bảng biểu để đánh dấu những kết quả đạt được mức ngưỡng thống kê nhất định.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_2_5', 'ten_c1_1_2', 'illiteracy', 'Reducing adult illiteracy can improve employment opportunities and enable more people to participate fully in society.', 'Reducing adult illiteracy can improve employment opportunities and enable more people to participate fully in society.', '/ɪˈlɪtərəsi/', 'Việc giảm thiểu tình trạng mù chữ ở người lớn có thể cải thiện cơ hội việc làm và tạo điều kiện cho nhiều người tham gia đầy đủ hơn vào đời sống xã hội.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_1_2_6', 'ten_c1_1_2', 'adverbial', 'Understanding adverbial clauses helps language learners express relationships between events more precisely in academic writing.', 'Understanding adverbial clauses helps language learners express relationships between events more precisely in academic writing.', '/ədˈvɝːbiəl/', 'Hiểu rõ các mệnh đề trạng ngữ giúp người học ngôn ngữ diễn đạt mối quan hệ giữa các sự việc chính xác hơn trong văn viết học thuật.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_1_2_1', 'en-c1-1', 'ten_c1_1_2', 'listening', 'listening', 'A university prospectus should provide accurate information about tuition fees, course content, and available student support.', NULL, 'Trong câu vừa nghe, từ “prospectus” mang nghĩa nào sau đây?', '["sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng)","tính ưu việt; thế vượt trội","tăng vọt; vọt lên cao","khổ sở; khốn khổ; bất hạnh"]'::jsonb, 0, '“prospectus” (/prəˈspektəs/): sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng). Câu đầy đủ: A university prospectus should provide accurate information about tuition fees, course content, and available student support.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_1_2_2', 'en-c1-1', 'ten_c1_1_2', 'listening', 'listening', 'Supporters of coeducation argue that learning together helps boys and girls develop mutual respect.', NULL, 'Trong câu vừa nghe, từ “coeducation” mang nghĩa nào sau đây?', '["sỏi mịn; cát sạn","chất cặn; phần dư; thặng dư","giáo dục nam nữ chung trường; nền giáo dục hỗn hợp nam nữ (việc giáo dục nam và nữ cùng nhau trong một cơ sở giáo dục)","đạt được; giành được"]'::jsonb, 2, '“coeducation” (/ˌkoʊedʒəˈkeɪʃən/): giáo dục nam nữ chung trường; nền giáo dục hỗn hợp nam nữ (việc giáo dục nam và nữ cùng nhau trong một cơ sở giáo dục). Câu đầy đủ: Supporters of coeducation argue that learning together helps boys and girls develop mutual respect.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
