INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_vi_c1_1_1', 'en-c1-1', 'vi_to_en', 'Tôi đã xem cẩm nang tuyển sinh của trường cao đẳng để tìm các khóa học nhiếp ảnh.', NULL, NULL, 'I checked the college prospectus for photography courses.', NULL, 'prospectus', '[]'::jsonb, 'Từ khóa gợi ý: prospectus (n.)', 'Tôi đã xem cẩm nang tuyển sinh của trường cao đẳng để tìm các khóa học nhiếp ảnh. → I checked the college prospectus for photography courses.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
