INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_1_1', 'en-c1-1', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “prospectus” (/prəˈspektəs/) có nghĩa là gì?', '["luận văn; luận án tốt nghiệp","sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng)","nhồi nhét; nhét đầy vào không gian chật hẹp","giáo dục nam nữ chung trường; nền giáo dục hỗn hợp nam nữ (việc giáo dục nam và nữ cùng nhau trong một cơ sở giáo dục)"]'::jsonb, 1, '“prospectus” (n.): sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng); bản cáo bạch; tài liệu giới thiệu đầu tư (giải thích về cơ hội đầu tư hoặc kinh doanh).', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_1_2', 'en-c1-1', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “The education of boys and girls together in the same institution.”', '["coeducation","legible","asterisk","enrich"]'::jsonb, 0, '“coeducation” (/ˌkoʊedʒəˈkeɪʃən/) nghĩa là: giáo dục nam nữ chung trường; nền giáo dục hỗn hợp nam nữ (việc giáo dục nam và nữ cùng nhau trong một cơ sở giáo dục).', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
