INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_1_14', 'en-c1-1', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “to start a line further inward than the surrounding lines”', '["coeducation","reinforcement","communicative","indent"]'::jsonb, 3, '“indent” (/ɪnˈdent/) nghĩa là: thụt lề; lùi đầu dòng.', 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
