INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_1', 'en-c1-1', NULL, 'comprehensive_test', 'listening', 'prospectus', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự tàn phá quy mô lớn; thảm họa diệt chủng","sự hoàn tiền; khoản tiền bồi hoàn (cho số tiền đã chi tiêu)","thể hiện; hiện thân","sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng)"]'::jsonb, 3, 'prospectus (/prəˈspektəs/) → sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng); bản cáo bạch; tài liệu giới thiệu đầu tư (giải thích về cơ hội đầu tư hoặc kinh doanh)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_2', 'en-c1-1', NULL, 'comprehensive_test', 'listening', 'My grandparents first experienced coeducation at their village school.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông bà tôi lần đầu tiên trải nghiệm việc học chung nam nữ tại ngôi trường ở làng của họ.","Ngồi xem ông tôi sửa chiếc đồng hồ hóa ra lại là một trải nghiệm mang tính hướng dẫn và học hỏi bất ngờ.","Những lớp học vẽ vào cuối tuần này thực sự làm phong phú thêm đời sống hàng ngày của tôi.","Tôi đã xem cẩm nang tuyển sinh của trường cao đẳng để tìm các khóa học nhiếp ảnh."]'::jsonb, 0, 'My grandparents first experienced coeducation at their village school. → Ông bà tôi lần đầu tiên trải nghiệm việc học chung nam nữ tại ngôi trường ở làng của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_3', 'en-c1-1', NULL, 'comprehensive_test', 'listening', 'instructive', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có tính giáo dục; mang lại nhiều bài học bổ ích","ký sinh trùng; sinh vật ký sinh","làm mất hiệu lực pháp lý (hợp đồng, thỏa thuận, quyết định)","lỗ chân lông; lỗ nhỏ (trên bề mặt)"]'::jsonb, 0, 'instructive (/ɪnˈstrʌktɪv/) → có tính giáo dục; mang lại nhiều bài học bổ ích', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_4', 'en-c1-1', NULL, 'comprehensive_test', 'listening', 'An asterisk beside the price points to extra delivery charges.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu của bạn đúng ngữ pháp, nhưng cách diễn đạt này nghe tự nhiên hơn.","Tấm rèm cửa hơi chồng chéo lên nhau ở chính giữa cửa sổ.","Dấu hoa thị bên cạnh mức giá dùng để chỉ các khoản phí giao hàng phát sinh thêm.","Bộ quà tặng bao gồm xà phòng, kem dưỡng da và một chiếc khăn tắm."]'::jsonb, 2, 'An asterisk beside the price points to extra delivery charges. → Dấu hoa thị bên cạnh mức giá dùng để chỉ các khoản phí giao hàng phát sinh thêm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_5', 'en-c1-1', NULL, 'comprehensive_test', 'listening', 'illiteracy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phòng y tế hoặc bệnh xá cung cấp dịch vụ chăm sóc y tế trong một cơ quan, trường học","khuynh hướng bẩm sinh mắc bệnh; thể tạng dễ nhiễm bệnh","điều cấm kỵ; điều kiêng kỵ","nạn mù chữ; tình trạng không biết đọc biết viết"]'::jsonb, 3, 'illiteracy (/ɪˈlɪtərəsi/) → nạn mù chữ; tình trạng không biết đọc biết viết; sự thiếu hiểu biết cơ bản', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_6', 'en-c1-1', NULL, 'comprehensive_test', 'listening', 'Our teacher explained adverbial phrases using simple everyday examples.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu của bạn đúng ngữ pháp, nhưng cách diễn đạt này nghe tự nhiên hơn.","Anh trai tôi trở nên cởi mở và hay nói hơn trong những buổi đi dạo buổi tối của chúng tôi.","Giáo viên của chúng tôi đã giải thích các cụm trạng ngữ bằng những ví dụ thường ngày đơn giản.","Những lớp học vẽ vào cuối tuần này thực sự làm phong phú thêm đời sống hàng ngày của tôi."]'::jsonb, 2, 'Our teacher explained adverbial phrases using simple everyday examples. → Giáo viên của chúng tôi đã giải thích các cụm trạng ngữ bằng những ví dụ thường ngày đơn giản.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_7', 'en-c1-1', NULL, 'comprehensive_test', 'listening', 'textual', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cuộc tàn sát; vụ thảm sát","hai mặt; kép; song song","núp; ẩn nấp; trốn","thuộc văn bản; thuộc về từ ngữ trong văn bản"]'::jsonb, 3, 'textual (/ˈtekstʃuəl/) → thuộc văn bản; thuộc về từ ngữ trong văn bản', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_8', 'en-c1-1', NULL, 'comprehensive_test', 'listening', 'She became literate after attending evening classes for adults.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đã biết chữ sau khi tham gia các lớp học buổi tối dành cho người lớn.","Leila đã dành cả cuối tuần để kiểm tra các tài liệu tham khảo cho luận văn của mình.","Tôi đã xem cẩm nang tuyển sinh của trường cao đẳng để tìm các khóa học nhiếp ảnh.","Chị tôi hy vọng sẽ bước vào bậc giáo dục đại học vào năm tới."]'::jsonb, 0, 'She became literate after attending evening classes for adults. → Cô ấy đã biết chữ sau khi tham gia các lớp học buổi tối dành cho người lớn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_9', 'en-c1-1', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The inability to read and write.”?', '["illiteracy","aptitude","literate","explanatory"]'::jsonb, 0, 'illiteracy (/ɪˈlɪtərəsi/) → nạn mù chữ; tình trạng không biết đọc biết viết', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_10', 'en-c1-1', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “functioning as an adverb or relating to adverbs”?', '["consolidate","aptitude","thesis","adverbial"]'::jsonb, 3, 'adverbial (/ədˈvɝːbiəl/) → thuộc về trạng ngữ; có chức năng như trạng ngữ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
