INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_18', 'en-c1-1', NULL, 'comprehensive_test', 'reading', NULL, 'A university prospectus should provide accurate information about tuition fees, course content, and available student support.', 'Dựa vào câu trên, từ “prospectus” có nghĩa phù hợp nhất là gì?', '["người di cư ra nước ngoài; người rời bỏ đất nước mình để định cư ở một quốc gia khác","sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng)","sự tăng tốc; sự đẩy nhanh","thuộc bậc đại học; thuộc giáo dục đại học"]'::jsonb, 1, 'prospectus: sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng); bản cáo bạch; tài liệu giới thiệu đầu tư (giải thích về cơ hội đầu tư hoặc kinh doanh). Dịch cả câu: Sách hướng dẫn tuyển sinh của trường đại học nên cung cấp thông tin chính xác về học phí, nội dung khóa học và các dịch vụ hỗ trợ sinh viên có sẵn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_19', 'en-c1-1', NULL, 'comprehensive_test', 'reading', NULL, 'Supporters of coeducation argue that learning together helps boys and girls develop mutual respect.', 'Dựa vào câu trên, từ “coeducation” có nghĩa phù hợp nhất là gì?', '["giáo dục nam nữ chung trường; nền giáo dục hỗn hợp nam nữ (việc giáo dục nam và nữ cùng nhau trong một cơ sở giáo dục)","lạng choạng; đi lảo đảo như sắp ngã","chậm hơn; phát triển chậm hơn","chung chung; không cụ thể"]'::jsonb, 0, 'coeducation: giáo dục nam nữ chung trường; nền giáo dục hỗn hợp nam nữ (việc giáo dục nam và nữ cùng nhau trong một cơ sở giáo dục). Dịch cả câu: Những người ủng hộ giáo dục nam nữ chung trường lập luận rằng việc cùng nhau học tập giúp nam và nữ phát triển sự tôn trọng lẫn nhau.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_20', 'en-c1-1', NULL, 'comprehensive_test', 'reading', NULL, 'Comparing different countries'' recycling systems can be instructive for policymakers seeking to reduce household waste.', 'Dựa vào câu trên, từ “instructive” có nghĩa phù hợp nhất là gì?', '["thú mỏ vịt","có tính giáo dục; mang lại nhiều bài học bổ ích","kéo lên; nâng lên (bằng dây thừng hoặc máy móc)","sự kiên trì; tính kiên định; sự bền bỉ"]'::jsonb, 1, 'instructive: có tính giáo dục; mang lại nhiều bài học bổ ích. Dịch cả câu: Việc so sánh hệ thống tái chế của các quốc gia khác nhau có thể mang lại nhiều bài học hữu ích cho các nhà hoạch định chính sách đang muốn giảm thiểu rác thải sinh hoạt.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_21', 'en-c1-1', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers often use an asterisk in tables to indicate results that meet a particular statistical threshold.', 'Dựa vào câu trên, từ “asterisk” có nghĩa phù hợp nhất là gì?', '["quyền phủ quyết; sự phủ quyết","khuếch đại âm thanh hoặc tín hiệu điện","dấu hoa thị; dấu sao","thường; thông thường; ở điều kiện bình thường"]'::jsonb, 2, 'asterisk: dấu hoa thị; dấu sao. Dịch cả câu: Các nhà nghiên cứu thường sử dụng dấu sao trong các bảng biểu để đánh dấu những kết quả đạt được mức ngưỡng thống kê nhất định.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_22', 'en-c1-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “rõ ràng; dễ đọc; dễ nhận biết”', '["successor","legible","martial","grudge"]'::jsonb, 1, 'rõ ràng; dễ đọc; dễ nhận biết → legible (/ˈledʒəbəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_23', 'en-c1-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mang tính giải thích; mang tính minh họa”', '["vogue","displacement","metropolitan","explanatory"]'::jsonb, 3, 'mang tính giải thích; mang tính minh họa → explanatory (/ɪkˈsplænətɔːri/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_1_24', 'en-c1-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phủ lên nhau; chồng chéo lên nhau; có điểm chung”', '["gratify","uniformly","firmness","overlap"]'::jsonb, 3, 'phủ lên nhau; chồng chéo lên nhau; có điểm chung → overlap (/ˌoʊvɚˈlæp/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-2', 'en', 'Bài 2: Giáo dục & Trường học (2) - CEFR C1', 'CEFR C1', 'C1 · Giáo dục', '24 từ vựng Tiếng Anh CEFR C1 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5002, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impart', 'en-c1-2', 'impart', '/ɪmˈpɑːrt/', 'C1', 'truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng; ban tặng; đem lại một đặc tính nào đó cho cái gì', 'v.', NULL, 'Đồng nghĩa: convey, communicate', 'Thường dùng cấu trúc impart sth to sb, nghĩa là truyền đạt cái gì cho ai.', 'My grandmother loves to impart her gardening knowledge.', NULL, 'Bà tôi rất thích truyền lại những kiến thức làm vườn của mình.', '{"wordId":"impart","ukIpa":"/ɪmˈpɑːt/","usIpa":"/ɪmˈpɑːrt/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"To communicate knowledge, information, or skills to someone","vi":"truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng"},{"pos":"v.","en":"To give something a particular quality","vi":"ban tặng; đem lại một đặc tính nào đó cho cái gì"}],"examples":[{"en":"My grandmother loves to impart her gardening knowledge.","vi":"Bà tôi rất thích truyền lại những kiến thức làm vườn của mình.","audioKind":"ex"},{"en":"Schools should impart practical skills that enable young people to manage their finances independently.","vi":"Nhà trường nên truyền đạt các kỹ năng thực tế giúp người trẻ tự quản lý tài chính cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"impart knowledge","vi":"truyền đạt kiến thức"},{"en":"impart information","vi":"cung cấp thông tin"},{"en":"impart skills","vi":"truyền thụ kỹ năng"},{"en":"impart flavour","vi":"tạo hương vị"}],"wordFamily":[],"synonyms":["convey","communicate"],"antonyms":[],"tipVi":"Thường dùng cấu trúc impart sth to sb, nghĩa là truyền đạt cái gì cho ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coherence', 'en-c1-2', 'coherence', '/koʊˈhɪrəns/', 'C1', 'sự mạch lạc; tính liên kết; tính logic', 'n.', 'coherent (adj.), coherently (adv.), incoherent (adj.), incoherence (n.)', 'Đồng nghĩa: logical consistency · Trái nghĩa: incoherence', 'Nhấn mạnh sự liên kết về mặt ý tưởng, logic; trong khi "cohesion" nhấn mạnh liên kết về ngôn ngữ và hình thức.', 'Your story needs more coherence between its different parts.', NULL, 'Câu chuyện của bạn cần sự liên kết chặt chẽ hơn giữa các phần khác nhau.', '{"wordId":"coherence","ukIpa":"/kəʊˈhɪərəns/","usIpa":"/koʊˈhɪrəns/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"The quality of ideas fitting together clearly and logically.","vi":"sự mạch lạc; tính liên kết; tính logic"}],"examples":[{"en":"Your story needs more coherence between its different parts.","vi":"Câu chuyện của bạn cần sự liên kết chặt chẽ hơn giữa các phần khác nhau.","audioKind":"ex"},{"en":"Clear paragraph structure improves the coherence of an essay and helps readers follow complex arguments.","vi":"Cấu trúc đoạn văn rõ ràng giúp nâng cao tính mạch lạc của bài luận và giúp người đọc nắm bắt được các lập luận phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"logical coherence","vi":"tính logic mạch lạc"},{"en":"overall coherence","vi":"tính mạch lạc tổng thể"},{"en":"lack coherence","vi":"thiếu tính logic"},{"en":"improve coherence","vi":"cải thiện tính liên kết"}],"wordFamily":["coherent (adj.)","coherently (adv.)","incoherent (adj.)","incoherence (n.)"],"synonyms":["logical consistency"],"antonyms":["incoherence"],"tipVi":"Nhấn mạnh sự liên kết về mặt ý tưởng, logic; trong khi \"cohesion\" nhấn mạnh liên kết về ngôn ngữ và hình thức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enlighten', 'en-c1-2', 'enlighten', '/ɪnˈlaɪtən/', 'C1', 'khai sáng; làm cho ai đó hiểu rõ', 'v.', 'enlightenment (n.), enlightening (adj.), enlightened (adj.)', 'Đồng nghĩa: inform, educate', 'Thường dùng cấu trúc enlighten sb about/on sth, mang sắc thái trang trọng.', 'Could you enlighten me about how this camera works?', NULL, 'Bạn có thể giải thích cho tôi biết chiếc máy ảnh này hoạt động thế nào được không?', '{"wordId":"enlighten","ukIpa":"/ɪnˈlaɪtən/","usIpa":"/ɪnˈlaɪtən/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"to give someone information that helps them understand something","vi":"khai sáng; làm cho ai đó hiểu rõ"}],"examples":[{"en":"Could you enlighten me about how this camera works?","vi":"Bạn có thể giải thích cho tôi biết chiếc máy ảnh này hoạt động thế nào được không?","audioKind":"ex"},{"en":"Public health campaigns should enlighten citizens about the benefits of vaccination while addressing common concerns respectfully.","vi":"Các chiến dịch y tế công cộng nên giúp người dân hiểu rõ những lợi ích của việc tiêm chủng đồng thời giải đáp những lo lắng phổ biến một cách tôn trọng.","audioKind":"ex2"}],"collocations":[{"en":"enlighten someone about","vi":"làm cho ai đó hiểu rõ về"},{"en":"enlighten someone on","vi":"giải thích cho ai đó về"},{"en":"an enlightening discussion","vi":"một cuộc thảo luận mang tính mở mang kiến thức"}],"wordFamily":["enlightenment (n.)","enlightening (adj.)","enlightened (adj.)"],"synonyms":["inform","educate"],"antonyms":[],"tipVi":"Thường dùng cấu trúc enlighten sb about/on sth, mang sắc thái trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_orientation', 'en-c1-2', 'orientation', '/ˌɔːriənˈteɪʃən/', 'C1', 'buổi định hướng, tuần lễ sinh hoạt đầu khóa (giúp người mới thích nghi với môi trường mới); hướng, phương hướng (vị trí hướng về hoặc được đặt); khuynh hướng, định hướng (lợi ích, niềm tin hoặc sở thích cơ bản của cá nhân hoặc tổ chức)', 'n.', 'orient (v.), orientate (v.), oriented (adj.)', 'Đồng nghĩa: induction, alignment', 'Từ orientation thường dùng cho hoạt động hướng dẫn đầu vào; nghĩa chỉ phương hướng thường dùng cho kiến trúc.', 'During orientation, a student guide showed us the library.', NULL, 'Trong buổi định hướng, một hướng dẫn viên sinh viên đã dẫn chúng tôi đi tham quan thư viện.', '{"wordId":"orientation","ukIpa":"/ˌɔːriənˈteɪʃən/","usIpa":"/ˌɔːriənˈteɪʃən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"an introduction that helps people adjust to a new setting","vi":"buổi định hướng, tuần lễ sinh hoạt đầu khóa (giúp người mới thích nghi với môi trường mới)"},{"pos":"n.","en":"the direction in which something faces or is positioned","vi":"hướng, phương hướng (vị trí hướng về hoặc được đặt)"},{"pos":"n.","en":"a person''s or organisation''s basic interests, beliefs, or preferences","vi":"khuynh hướng, định hướng (lợi ích, niềm tin hoặc sở thích cơ bản của cá nhân hoặc tổ chức)"}],"examples":[{"en":"During orientation, a student guide showed us the library.","vi":"Trong buổi định hướng, một hướng dẫn viên sinh viên đã dẫn chúng tôi đi tham quan thư viện.","audioKind":"ex"},{"en":"A comprehensive orientation programme can help international students understand academic expectations and access essential support services.","vi":"Một chương trình định hướng toàn diện có thể giúp sinh viên quốc tế hiểu được các yêu cầu học tập và tiếp cận các dịch vụ hỗ trợ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"orientation programme","vi":"chương trình định hướng"},{"en":"orientation session","vi":"buổi định hướng"},{"en":"building orientation","vi":"hướng xây dựng"},{"en":"political orientation","vi":"khuynh hướng chính trị"}],"wordFamily":["orient (v.)","orientate (v.)","oriented (adj.)"],"synonyms":["induction","alignment"],"antonyms":[],"tipVi":"Từ orientation thường dùng cho hoạt động hướng dẫn đầu vào; nghĩa chỉ phương hướng thường dùng cho kiến trúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_symposium', 'en-c1-2', 'symposium', '/sɪmˈpoʊziəm/', 'C1', 'hội nghị chuyên đề; hội thảo', 'n.', NULL, NULL, 'Số nhiều có thể dùng symposia hoặc symposiums.', 'Leila met several researchers at a symposium yesterday.', NULL, 'Leila đã gặp gỡ một số nhà nghiên cứu tại một hội nghị chuyên đề ngày hôm qua.', '{"wordId":"symposium","ukIpa":"/sɪmˈpəʊziəm/","usIpa":"/sɪmˈpoʊziəm/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"a meeting where experts discuss a particular subject","vi":"hội nghị chuyên đề; hội thảo"}],"examples":[{"en":"Leila met several researchers at a symposium yesterday.","vi":"Leila đã gặp gỡ một số nhà nghiên cứu tại một hội nghị chuyên đề ngày hôm qua.","audioKind":"ex"},{"en":"The international symposium brought together scientists to discuss practical solutions to urban air pollution.","vi":"Hội nghị chuyên đề quốc tế đã quy tụ các nhà khoa học để thảo luận về các giải pháp thiết thực cho tình trạng ô nhiễm không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"attend a symposium","vi":"tham dự hội nghị chuyên đề"},{"en":"a symposium on climate change","vi":"hội nghị chuyên đề về biến đổi khí hậu"},{"en":"host a symposium","vi":"tổ chức hội nghị chuyên đề"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều có thể dùng symposia hoặc symposiums.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attentive', 'en-c1-2', 'attentive', '/əˈtentɪv/', 'C1', 'chăm chú; lắng nghe chăm chú; ân cần; chu đáo', 'adj.', 'attention (n.), attentively (adv.), attentiveness (n.), inattentive (adj.)', 'Đồng nghĩa: alert, considerate · Trái nghĩa: inattentive', 'attentive to đi với đối tượng mà mình quan tâm; từ này cũng dùng để chỉ thái độ phục vụ chu đáo.', 'The children were attentive as their grandmother explained the game.', NULL, 'Bọn trẻ chăm chú lắng nghe khi bà giải thích về trò chơi.', '{"wordId":"attentive","ukIpa":"/əˈtentɪv/","usIpa":"/əˈtentɪv/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"listening or watching carefully","vi":"chăm chú; lắng nghe chăm chú"},{"pos":"adj.","en":"taking care to notice and meet someone''s needs","vi":"ân cần; chu đáo"}],"examples":[{"en":"The children were attentive as their grandmother explained the game.","vi":"Bọn trẻ chăm chú lắng nghe khi bà giải thích về trò chơi.","audioKind":"ex"},{"en":"Teachers who are attentive to individual learning needs can help students participate more confidently in classroom discussions.","vi":"Những giáo viên quan tâm chu đáo đến nhu cầu học tập cá nhân có thể giúp học sinh tự tin tham gia thảo luận trên lớp hơn.","audioKind":"ex2"}],"collocations":[{"en":"an attentive audience","vi":"thính giả chăm chú"},{"en":"attentive to detail","vi":"chú ý đến từng chi tiết"},{"en":"attentive service","vi":"dịch vụ chu đáo"}],"wordFamily":["attention (n.)","attentively (adv.)","attentiveness (n.)","inattentive (adj.)"],"synonyms":["alert","considerate"],"antonyms":["inattentive"],"tipVi":"attentive to đi với đối tượng mà mình quan tâm; từ này cũng dùng để chỉ thái độ phục vụ chu đáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_equivalence', 'en-c1-2', 'equivalence', '/ɪˈkwɪvələns/', 'C1', 'sự tương đương; tính tương đương', 'n.', 'equivalent (adj.), equivalently (adv.)', 'Đồng nghĩa: equality · Trái nghĩa: inequality', 'Thường dùng cấu trúc equivalence between A and B để chỉ sự tương đương giữa hai bên.', 'The balanced scales showed the equivalence of the two weights.', NULL, 'Cái cân thăng bằng cho thấy trọng lượng của hai vật là tương đương nhau.', '{"wordId":"equivalence","ukIpa":"/ɪˈkwɪvələns/","usIpa":"/ɪˈkwɪvələns/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"the state of being equal in value, meaning, or function","vi":"sự tương đương; tính tương đương"}],"examples":[{"en":"The balanced scales showed the equivalence of the two weights.","vi":"Cái cân thăng bằng cho thấy trọng lượng của hai vật là tương đương nhau.","audioKind":"ex"},{"en":"Establishing equivalence between qualifications from different countries can make it easier for skilled workers to find employment abroad.","vi":"Việc thiết lập sự tương đương giữa các văn bằng chứng chỉ từ các quốc gia khác nhau có thể giúp lao động có tay nghề dễ dàng tìm kiếm việc làm ở nước ngoài hơn.","audioKind":"ex2"}],"collocations":[{"en":"equivalence between","vi":"sự tương đương giữa"},{"en":"establish equivalence","vi":"thiết lập tính tương đương"},{"en":"functional equivalence","vi":"sự tương đương về mặt chức năng"}],"wordFamily":["equivalent (adj.)","equivalently (adv.)"],"synonyms":["equality"],"antonyms":["inequality"],"tipVi":"Thường dùng cấu trúc equivalence between A and B để chỉ sự tương đương giữa hai bên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_truant', 'en-c1-2', 'truant', '/ˈtruːənt/', 'C1', 'học sinh trốn học; kẻ trốn học; trốn học', 'n.', 'truancy (n.)', NULL, 'Cụm play truant trong tiếng Anh-Anh nghĩa là trốn học, không phải là xin nghỉ phép thông thường.', 'The teacher found two truants hiding behind the playground.', NULL, 'Giáo viên phát hiện hai học sinh trốn học đang nấp sau khu vui chơi.', '{"wordId":"truant","ukIpa":"/ˈtruːənt/","usIpa":"/ˈtruːənt/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"A pupil who stays away from school without permission","vi":"học sinh trốn học; kẻ trốn học"},{"pos":"adj.","en":"Absent from school without permission","vi":"trốn học"}],"examples":[{"en":"The teacher found two truants hiding behind the playground.","vi":"Giáo viên phát hiện hai học sinh trốn học đang nấp sau khu vui chơi.","audioKind":"ex"},{"en":"Schools should support persistent truants by addressing bullying and family difficulties rather than relying solely on punishment.","vi":"Nhà trường nên hỗ trợ những học sinh thường xuyên trốn học bằng cách giải quyết tình trạng bắt nạt và khó khăn gia đình thay vì chỉ dựa vào hình phạt.","audioKind":"ex2"}],"collocations":[{"en":"play truant","vi":"trốn học"},{"en":"persistent truant","vi":"kẻ trốn học thường xuyên"},{"en":"truant pupils","vi":"học sinh trốn học"}],"wordFamily":["truancy (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm play truant trong tiếng Anh-Anh nghĩa là trốn học, không phải là xin nghỉ phép thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invigilate', 'en-c1-2', 'invigilate', '/ɪnˈvɪdʒɪleɪt/', 'C1', 'gác thi, giám thị', 'v.', 'invigilator (n.), invigilation (n.)', 'Đồng nghĩa: proctor', 'Chủ yếu dùng trong tiếng Anh - Anh; tiếng Anh - Mỹ thường dùng proctor.', 'Our teachers take turns to invigilate the final exams.', NULL, 'Các giáo viên của chúng tôi phiên nhau gác các kỳ thi cuối kỳ.', '{"wordId":"invigilate","ukIpa":"/ɪnˈvɪdʒɪleɪt/","usIpa":"/ɪnˈvɪdʒɪleɪt/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"to supervise people taking an examination","vi":"gác thi, giám thị"}],"examples":[{"en":"Our teachers take turns to invigilate the final exams.","vi":"Các giáo viên của chúng tôi phiên nhau gác các kỳ thi cuối kỳ.","audioKind":"ex"},{"en":"Universities must train staff to invigilate examinations fairly and respond appropriately to suspected cheating.","vi":"Các trường đại học phải đào tạo nhân viên để gác thi công bằng và xử lý thích đáng các trường hợp nghi ngờ gian lận.","audioKind":"ex2"}],"collocations":[{"en":"invigilate an exam","vi":"gác một kỳ thi"},{"en":"invigilate examinations","vi":"coi thi các kỳ thi"}],"wordFamily":["invigilator (n.)","invigilation (n.)"],"synonyms":["proctor"],"antonyms":[],"tipVi":"Chủ yếu dùng trong tiếng Anh - Anh; tiếng Anh - Mỹ thường dùng proctor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acquaint', 'en-c1-2', 'acquaint', '/əˈkweɪnt/', 'C1', 'làm quen; làm cho hiểu rõ; cung cấp thông tin', 'v.', 'acquaintance (n.), acquainted (adj.)', 'Đồng nghĩa: familiarise', 'Từ này mang văn phong trang trọng, thường dùng theo cấu trúc acquaint sb/oneself with sth.', 'Please acquaint yourself with the kitchen before you start cooking.', NULL, 'Xin vui lòng làm quen với khu bếp trước khi bạn bắt đầu nấu nướng.', '{"wordId":"acquaint","ukIpa":"/əˈkweɪnt/","usIpa":"/əˈkweɪnt/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"Give someone knowledge of or familiarity with something.","vi":"làm quen; làm cho hiểu rõ; cung cấp thông tin"}],"examples":[{"en":"Please acquaint yourself with the kitchen before you start cooking.","vi":"Xin vui lòng làm quen với khu bếp trước khi bạn bắt đầu nấu nướng.","audioKind":"ex"},{"en":"Universities should acquaint new students with available support services to help them adjust to campus life.","vi":"Các trường đại học nên giúp sinh viên mới làm quen với các dịch vụ hỗ trợ sẵn có để giúp họ thích nghi với đời sống khuôn viên trường.","audioKind":"ex2"}],"collocations":[{"en":"acquaint yourself with","vi":"tự làm quen với"},{"en":"acquaint someone with","vi":"làm cho ai đó quen với"},{"en":"be acquainted with","vi":"quen thuộc với"}],"wordFamily":["acquaintance (n.)","acquainted (adj.)"],"synonyms":["familiarise"],"antonyms":[],"tipVi":"Từ này mang văn phong trang trọng, thường dùng theo cấu trúc acquaint sb/oneself with sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_colloquial', 'en-c1-2', 'colloquial', '/kəˈloʊkwiəl/', 'C1', 'thuộc khẩu ngữ; dùng trong văn nói hàng ngày; không trang trọng', 'adj.', 'colloquially (adv.), colloquialism (n.)', 'Đồng nghĩa: informal, conversational · Trái nghĩa: formal', 'Chỉ các từ ngữ dùng trong giao tiếp thông thường, không đồng nhất với tiếng lóng (slang).', 'This podcast helps me learn colloquial expressions used by friends.', NULL, 'Podcast này giúp tôi học các cách diễn đạt thông dụng trong văn nói của bạn bè.', '{"wordId":"colloquial","ukIpa":"/kəˈləʊkwiəl/","usIpa":"/kəˈloʊkwiəl/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"used in informal conversation rather than formal writing","vi":"thuộc khẩu ngữ; dùng trong văn nói hàng ngày; không trang trọng"}],"examples":[{"en":"This podcast helps me learn colloquial expressions used by friends.","vi":"Podcast này giúp tôi học các cách diễn đạt thông dụng trong văn nói của bạn bè.","audioKind":"ex"},{"en":"Although colloquial language suits personal blogs, academic essays generally require a more formal style.","vi":"Mặc dù ngôn ngữ mang tính khẩu ngữ phù hợp với các blog cá nhân, các bài luận học thuật nhìn chung đòi hỏi phong cách trang trọng hơn.","audioKind":"ex2"}],"collocations":[{"en":"colloquial language","vi":"ngôn ngữ khẩu ngữ"},{"en":"colloquial expression","vi":"cách diễn đạt thông dụng trong văn nói"},{"en":"colloquial speech","vi":"lời ăn tiếng nói hàng ngày"}],"wordFamily":["colloquially (adv.)","colloquialism (n.)"],"synonyms":["informal","conversational"],"antonyms":["formal"],"tipVi":"Chỉ các từ ngữ dùng trong giao tiếp thông thường, không đồng nhất với tiếng lóng (slang).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exemplify', 'en-c1-2', 'exemplify', '/ɪɡˈzemplɪfaɪ/', 'C1', 'là ví dụ điển hình cho; minh họa bằng ví dụ; làm gương cho; nêu gương', 'v.', 'example (n.), exemplification (n.)', 'Đồng nghĩa: illustrate, demonstrate', 'Là ngoại động từ đi trực tiếp với danh từ; khi nêu gương hoặc làm ví dụ, cấu trúc bị động be exemplified by cũng hay được sử dụng.', 'Her handmade bowls exemplify the beauty of simple design.', NULL, 'Những chiếc bát thủ công của cô ấy là minh chứng tiêu biểu cho vẻ đẹp của thiết kế tối giản.', '{"wordId":"exemplify","ukIpa":"/ɪɡˈzemplɪfaɪ/","usIpa":"/ɪɡˈzemplɪfaɪ/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"to be a clear example of something","vi":"là ví dụ điển hình cho; minh họa bằng ví dụ"},{"pos":"v.","en":"to explain something by giving examples","vi":"làm gương cho; nêu gương"}],"examples":[{"en":"Her handmade bowls exemplify the beauty of simple design.","vi":"Những chiếc bát thủ công của cô ấy là minh chứng tiêu biểu cho vẻ đẹp của thiết kế tối giản.","audioKind":"ex"},{"en":"These community gardens exemplify how urban residents can improve local biodiversity while producing fresh food.","vi":"Những khu vườn cộng đồng này minh họa cách cư dân đô thị có thể cải thiện đa dạng sinh học địa phương trong khi vẫn sản xuất ra thực phẩm sạch.","audioKind":"ex2"}],"collocations":[{"en":"exemplify a trend","vi":"làm điển hình cho một xu hướng"},{"en":"exemplify a principle","vi":"làm rõ một nguyên tắc"},{"en":"exemplify the benefits of","vi":"thể hiện những lợi ích của"}],"wordFamily":["example (n.)","exemplification (n.)"],"synonyms":["illustrate","demonstrate"],"antonyms":[],"tipVi":"Là ngoại động từ đi trực tiếp với danh từ; khi nêu gương hoặc làm ví dụ, cấu trúc bị động be exemplified by cũng hay được sử dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attain', 'en-c1-2', 'attain', '/əˈteɪn/', 'C1', 'đạt được; giành được', 'v.', 'attainment (n.), attainable (adj.), unattainable (adj.)', 'Đồng nghĩa: achieve, reach', 'Động từ chỉ trạng thái mang tính trang trọng, theo sau trực tiếp là mục tiêu hoặc cấp độ mà không cần dùng giới từ to.', 'After months of practice, she attained her target swimming speed.', NULL, 'Sau nhiều tháng luyện tập, cô ấy đã đạt được tốc độ bơi mục tiêu của mình.', '{"wordId":"attain","ukIpa":"/əˈteɪn/","usIpa":"/əˈteɪn/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"To reach a goal or level, usually through effort.","vi":"đạt được; giành được"}],"examples":[{"en":"After months of practice, she attained her target swimming speed.","vi":"Sau nhiều tháng luyện tập, cô ấy đã đạt được tốc độ bơi mục tiêu của mình.","audioKind":"ex"},{"en":"Students from disadvantaged backgrounds may need additional support to attain the qualifications required for university entry.","vi":"Học sinh đến từ các hoàn cảnh khó khăn có thể cần thêm sự hỗ trợ để đạt được các chứng chỉ cần thiết cho việc vào đại học.","audioKind":"ex2"}],"collocations":[{"en":"attain a goal","vi":"đạt được mục tiêu"},{"en":"attain a high standard","vi":"đạt tiêu chuẩn cao"},{"en":"attain independence","vi":"giành được độc lập"}],"wordFamily":["attainment (n.)","attainable (adj.)","unattainable (adj.)"],"synonyms":["achieve","reach"],"antonyms":[],"tipVi":"Động từ chỉ trạng thái mang tính trang trọng, theo sau trực tiếp là mục tiêu hoặc cấp độ mà không cần dùng giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_schooling', 'en-c1-2', 'schooling', '/ˈskuːlɪŋ/', 'C1', 'giáo dục nhà học đường; việc học tập tại trường', 'n.', 'school (n.), school (v.)', 'Đồng nghĩa: school education', 'schooling thường là danh từ không đếm được, nhấn mạnh quá trình thụ giáo tại trường lớp.', 'My grandmother finished her schooling in a small village.', NULL, 'Bà tôi hoàn thành việc học phổ thông tại một ngôi làng nhỏ.', '{"wordId":"schooling","ukIpa":"/ˈskuːlɪŋ/","usIpa":"/ˈskuːlɪŋ/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"Education received at school.","vi":"giáo dục nhà học đường; việc học tập tại trường"}],"examples":[{"en":"My grandmother finished her schooling in a small village.","vi":"Bà tôi hoàn thành việc học phổ thông tại một ngôi làng nhỏ.","audioKind":"ex"},{"en":"Providing free schooling can reduce inequality by giving children from disadvantaged backgrounds better opportunities.","vi":"Việc cung cấp giáo dục miễn phí có thể thu hẹp khoảng cách bất bình đẳng bằng cách mang lại cơ hội tốt hơn cho trẻ em có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"formal schooling","vi":"giáo dục chính quy tại trường"},{"en":"compulsory schooling","vi":"giáo dục bắt buộc"},{"en":"years of schooling","vi":"số năm đến trường"},{"en":"complete one''s schooling","vi":"hoàn thành việc học"}],"wordFamily":["school (n.)","school (v.)"],"synonyms":["school education"],"antonyms":[],"tipVi":"schooling thường là danh từ không đếm được, nhấn mạnh quá trình thụ giáo tại trường lớp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wordy', 'en-c1-2', 'wordy', '/ˈwɝːdi/', 'C1', 'dài dòng; rườm rà; nhiều lời', 'adj.', 'word (n.), wordiness (n.)', 'Đồng nghĩa: verbose, long-winded · Trái nghĩa: concise, succinct', 'Thường mang nghĩa tiêu cực, chỉ việc dùng quá nhiều từ không cần thiết chứ không có nghĩa là vốn từ phong phú.', 'His wordy email made a simple request sound complicated.', NULL, 'Bức email dài dòng của anh ấy khiến cho một yêu cầu đơn giản trở nên phức tạp.', '{"wordId":"wordy","ukIpa":"/ˈwɜːdi/","usIpa":"/ˈwɝːdi/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Using more words than are needed to express something.","vi":"dài dòng; rườm rà; nhiều lời"}],"examples":[{"en":"His wordy email made a simple request sound complicated.","vi":"Bức email dài dòng của anh ấy khiến cho một yêu cầu đơn giản trở nên phức tạp.","audioKind":"ex"},{"en":"Public information should be clear, as wordy explanations can prevent readers from understanding essential advice.","vi":"Thông tin công cộng cần phải rõ ràng, bởi vì những lời giải thích dài dòng có thể cản trở độc giả hiểu được những lời khuyên cốt lõi.","audioKind":"ex2"}],"collocations":[{"en":"wordy explanation","vi":"lời giải thích dài dòng"},{"en":"wordy sentence","vi":"câu văn rườm rà"},{"en":"overly wordy","vi":"quá nhiều chữ"}],"wordFamily":["word (n.)","wordiness (n.)"],"synonyms":["verbose","long-winded"],"antonyms":["concise","succinct"],"tipVi":"Thường mang nghĩa tiêu cực, chỉ việc dùng quá nhiều từ không cần thiết chứ không có nghĩa là vốn từ phong phú.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assimilate', 'en-c1-2', 'assimilate', '/əˈsɪməleɪt/', 'C1', 'tiếp thu và lĩnh hội hoàn toàn thông tin hoặc ý tưởng mới; hòa nhập hoặc làm cho ai đó hòa nhập vào một cộng đồng văn hóa', 'v.', 'assimilation (n.)', 'Đồng nghĩa: absorb', 'Kiến thức có thể làm tân ngữ trực tiếp; để chỉ việc hòa nhập vào nhóm, ta thường dùng "into".', 'I need time to assimilate everything we learned today.', NULL, 'Tôi cần có thời gian để tiêu hóa và tiếp thu mọi thứ chúng ta đã học hôm nay.', '{"wordId":"assimilate","ukIpa":"/əˈsɪməleɪt/","usIpa":"/əˈsɪməleɪt/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"To take in and fully understand new information or ideas.","vi":"tiếp thu và lĩnh hội hoàn toàn thông tin hoặc ý tưởng mới"},{"pos":"v.","en":"To become, or make someone become, part of a cultural group.","vi":"hòa nhập hoặc làm cho ai đó hòa nhập vào một cộng đồng văn hóa"}],"examples":[{"en":"I need time to assimilate everything we learned today.","vi":"Tôi cần có thời gian để tiêu hóa và tiếp thu mọi thứ chúng ta đã học hôm nay.","audioKind":"ex"},{"en":"Students assimilate new information more effectively when teachers connect unfamiliar concepts with examples from everyday life.","vi":"Học sinh tiếp thu thông tin mới hiệu quả hơn khi giáo viên kết nối các khái niệm xa lạ với ví dụ từ đời sống hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"assimilate information","vi":"tiếp thu thông tin"},{"en":"assimilate new ideas","vi":"lĩnh hội tư tưởng mới"},{"en":"assimilate into society","vi":"hòa nhập vào xã hội"}],"wordFamily":["assimilation (n.)"],"synonyms":["absorb"],"antonyms":[],"tipVi":"Kiến thức có thể làm tân ngữ trực tiếp; để chỉ việc hòa nhập vào nhóm, ta thường dùng \"into\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plagiarize', 'en-c1-2', 'plagiarize', '/ˈpleɪdʒəraɪz/', 'C1', 'đạo văn; sao chép', 'v.', 'plagiarism (n.), plagiarist (n.)', NULL, 'Cách viết theo Anh-Anh là plagiarise; việc trích dẫn nội dung của người khác phải luôn ghi rõ nguồn gốc.', 'Our teacher explained why we must never plagiarize essays.', NULL, 'Giáo viên đã giải thích lý do tại sao chúng ta không bao giờ được đạo văn bài luận.', '{"wordId":"plagiarize","ukIpa":"/ˈpleɪdʒəraɪz/","usIpa":"/ˈpleɪdʒəraɪz/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"present another person''s words or ideas as your own","vi":"đạo văn; sao chép"}],"examples":[{"en":"Our teacher explained why we must never plagiarize essays.","vi":"Giáo viên đã giải thích lý do tại sao chúng ta không bao giờ được đạo văn bài luận.","audioKind":"ex"},{"en":"Students who plagiarize online material risk disciplinary action and miss opportunities to develop independent thinking.","vi":"Những học sinh đạo văn tài liệu trên mạng có nguy cơ đối mặt với kỷ luật và bỏ lỡ cơ hội phát triển tư duy độc lập.","audioKind":"ex2"}],"collocations":[{"en":"plagiarize an essay","vi":"đạo văn bài luận"},{"en":"plagiarize someone''s work","vi":"sao chép tác phẩm của ai đó"},{"en":"plagiarize from a source","vi":"lấy nguồn từ tài liệu có sẵn"}],"wordFamily":["plagiarism (n.)","plagiarist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết theo Anh-Anh là plagiarise; việc trích dẫn nội dung của người khác phải luôn ghi rõ nguồn gốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_utterance', 'en-c1-2', 'utterance', '/ˈʌtərəns/', 'C1', 'lời nói; phát ngôn; sự phát biểu; sự cất tiếng', 'n.', 'utter (v.)', 'Đồng nghĩa: remark, statement', 'Trong ngôn ngữ học, utterance chỉ một lần nói ra, không nhất thiết phải là một câu hoàn chỉnh.', 'The baby''s first clear utterance made everyone smile.', NULL, 'Tiếng nói rõ ràng đầu tiên của em bé khiến ai nấy đều mỉm cười.', '{"wordId":"utterance","ukIpa":"/ˈʌtərəns/","usIpa":"/ˈʌtərəns/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"Something spoken, such as a word, phrase, or sentence.","vi":"lời nói; phát ngôn"},{"pos":"n.","en":"The act of expressing something through speech.","vi":"sự phát biểu; sự cất tiếng"}],"examples":[{"en":"The baby''s first clear utterance made everyone smile.","vi":"Tiếng nói rõ ràng đầu tiên của em bé khiến ai nấy đều mỉm cười.","audioKind":"ex"},{"en":"Analysing each utterance in classroom discussions can reveal how teachers encourage students to express their ideas.","vi":"Phân tích từng phát ngôn trong các buổi thảo luận trên lớp có thể cho thấy giáo viên khích lệ học sinh bày tỏ ý kiến như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"a single utterance","vi":"một phát ngôn đơn lẻ"},{"en":"a spontaneous utterance","vi":"một lời nói tự phát"},{"en":"give utterance to","vi":"cất lời; bày tỏ"}],"wordFamily":["utter (v.)"],"synonyms":["remark","statement"],"antonyms":[],"tipVi":"Trong ngôn ngữ học, utterance chỉ một lần nói ra, không nhất thiết phải là một câu hoàn chỉnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fellowship', 'en-c1-2', 'fellowship', '/ˈfeloʊʃɪp/', 'C1', 'học bổng nghiên cứu; quỹ hỗ trợ nghiên cứu; chức vụ nghiên cứu sinh; tình bằng hữu; tình đồng nghiệp; sự gắn bó; hội; hiệp hội; đoàn thể', 'n.', 'fellow (n.)', NULL, 'Nghĩa học bổng/trợ cấp thường đếm được; nghĩa tình bằng hữu thường không đếm được.', 'My sister won a fellowship to study marine life.', NULL, 'Chị tôi đã giành được học bổng nghiên cứu về sinh vật biển.', '{"wordId":"fellowship","ukIpa":"/ˈfeləʊʃɪp/","usIpa":"/ˈfeloʊʃɪp/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"Funding or a position supporting advanced study or research.","vi":"học bổng nghiên cứu; quỹ hỗ trợ nghiên cứu; chức vụ nghiên cứu sinh"},{"pos":"n.","en":"Friendship and support among people with shared interests.","vi":"tình bằng hữu; tình đồng nghiệp; sự gắn bó"},{"pos":"n.","en":"A group united by shared interests or beliefs.","vi":"hội; hiệp hội; đoàn thể"}],"examples":[{"en":"My sister won a fellowship to study marine life.","vi":"Chị tôi đã giành được học bổng nghiên cứu về sinh vật biển.","audioKind":"ex"},{"en":"A research fellowship can enable early-career scientists to investigate environmental problems without facing immediate financial pressure.","vi":"Học bổng nghiên cứu có thể giúp các nhà khoa học ở giai đoạn đầu sự nghiệp nghiên cứu các vấn đề môi trường mà không phải đối mặt với áp lực tài chính ngay lập tức.","audioKind":"ex2"}],"collocations":[{"en":"research fellowship","vi":"học bổng nghiên cứu"},{"en":"award a fellowship","vi":"trao học bổng nghiên cứu"},{"en":"a sense of fellowship","vi":"tinh thần đồng đội"}],"wordFamily":["fellow (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa học bổng/trợ cấp thường đếm được; nghĩa tình bằng hữu thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preface', 'en-c1-2', 'preface', '/ˈprefəs/', 'C1', 'lời nói đầu; lời tựa; phần mở đầu; viết lời tựa; mở đầu bằng việc', 'n.', 'prefatory (adj.)', 'Đồng nghĩa: introduction', 'Phần preface của sách thường do chính tác giả viết; trong khi foreword thường do người khác viết.', 'The author explains her inspiration in the book''s preface.', NULL, 'Tác giả giải thích nguồn cảm hứng của mình trong phần lời nói đầu của cuốn sách.', '{"wordId":"preface","ukIpa":"/ˈprefəs/","usIpa":"/ˈprefəs/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"An introductory section explaining a book''s purpose or background.","vi":"lời nói đầu; lời tựa; phần mở đầu"},{"pos":"v.","en":"To introduce something by saying or writing something beforehand.","vi":"viết lời tựa; mở đầu bằng việc"}],"examples":[{"en":"The author explains her inspiration in the book''s preface.","vi":"Tác giả giải thích nguồn cảm hứng của mình trong phần lời nói đầu của cuốn sách.","audioKind":"ex"},{"en":"In the preface, the researchers explain how their personal experiences influenced the questions explored throughout the book.","vi":"Trong phần lời nói đầu, các nhà nghiên cứu giải thích cách các trải nghiệm cá nhân đã ảnh hưởng đến các vấn đề được khám phá xuyên suốt cuốn sách.","audioKind":"ex2"}],"collocations":[{"en":"in the preface","vi":"trong phần lời nói đầu"},{"en":"write a preface","vi":"viết lời tựa"},{"en":"preface remarks with","vi":"mở đầu bài phát biểu bằng"}],"wordFamily":["prefatory (adj.)"],"synonyms":["introduction"],"antonyms":[],"tipVi":"Phần preface của sách thường do chính tác giả viết; trong khi foreword thường do người khác viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_authoritative', 'en-c1-2', 'authoritative', '/əˈθɔːrəteɪtɪv/', 'C1', 'mang tính thẩm quyền; đáng tin cậy; chính thống; có uy quyền; ra lệnh; đầy uy phong', 'adj.', 'authority (n.), authoritatively (adv.), authoritativeness (n.)', 'Đồng nghĩa: reliable, commanding', 'Tránh nhầm lẫn với từ authoritarian: từ này có nghĩa là độc đoán, chuyên quyền.', 'This gardening guide offers authoritative advice on growing vegetables.', NULL, 'Cẩm nang làm vườn này cung cấp những lời khuyên có tính chuyên môn cao về việc trồng rau.', '{"wordId":"authoritative","ukIpa":"/ɔːˈθɒrɪtətɪv/","usIpa":"/əˈθɔːrəteɪtɪv/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Trusted as accurate because of expert knowledge.","vi":"mang tính thẩm quyền; đáng tin cậy; chính thống"},{"pos":"adj.","en":"Showing confidence and an ability to command respect.","vi":"có uy quyền; ra lệnh; đầy uy phong"}],"examples":[{"en":"This gardening guide offers authoritative advice on growing vegetables.","vi":"Cẩm nang làm vườn này cung cấp những lời khuyên có tính chuyên môn cao về việc trồng rau.","audioKind":"ex"},{"en":"Students should consult authoritative sources when evaluating health claims shared widely through social media platforms.","vi":"Học sinh nên tham khảo các nguồn thông tin chính thống khi đánh giá các nhận định về sức khỏe được chia sẻ rộng rãi trên các nền tảng mạng xã hội.","audioKind":"ex2"}],"collocations":[{"en":"an authoritative source","vi":"một nguồn tin cậy"},{"en":"authoritative advice","vi":"lời khuyên có thẩm quyền"},{"en":"an authoritative tone","vi":"giọng điệu uy quyền"},{"en":"an authoritative account","vi":"một tài liệu mang tính thẩm quyền"}],"wordFamily":["authority (n.)","authoritatively (adv.)","authoritativeness (n.)"],"synonyms":["reliable","commanding"],"antonyms":[],"tipVi":"Tránh nhầm lẫn với từ authoritarian: từ này có nghĩa là độc đoán, chuyên quyền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_humanities', 'en-c1-2', 'humanities', '/hjuːˈmænətiz/', 'C1', 'ngành nhân văn; nhân văn học', 'n.', 'humanity (n.)', NULL, 'Thuật ngữ chỉ lĩnh vực học thuật thường dùng the humanities, và được chia ở dạng số nhiều.', 'She chose humanities because she loves history and literature.', NULL, 'Cô ấy chọn học các môn nhân văn vì cô rất yêu thích lịch sử và văn học.', '{"wordId":"humanities","ukIpa":"/hjuːˈmænətiz/","usIpa":"/hjuːˈmænətiz/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"subjects studying human culture, such as history, literature, and philosophy","vi":"ngành nhân văn; nhân văn học"}],"examples":[{"en":"She chose humanities because she loves history and literature.","vi":"Cô ấy chọn học các môn nhân văn vì cô rất yêu thích lịch sử và văn học.","audioKind":"ex"},{"en":"Studying the humanities can develop critical thinking and help students understand perspectives shaped by different cultures.","vi":"Việc học các môn nhân văn có thể phát triển tư duy phản biện và giúp sinh viên thấu hiểu các quan điểm được định hình bởi những nền văn hóa khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"study the humanities","vi":"nghiên cứu các môn nhân văn"},{"en":"humanities subjects","vi":"các môn học nhân văn"},{"en":"arts and humanities","vi":"nghệ thuật và nhân văn"}],"wordFamily":["humanity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thuật ngữ chỉ lĩnh vực học thuật thường dùng the humanities, và được chia ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elicit', 'en-c1-2', 'elicit', '/ɪˈlɪsɪt/', 'C1', 'gợi ra; khai thác; dẫn dụ', 'v.', 'elicitation (n.)', 'Đồng nghĩa: evoke, draw out', 'Thường đi với các tân ngữ như response; tránh nhầm lẫn với từ illicit (trái pháp luật).', 'Her unexpected question elicited a smile from the normally quiet guide.', NULL, 'Câu hỏi bất ngờ của cô ấy đã khiến vị hướng dẫn viên vốn ít nói phải mỉm cười.', '{"wordId":"elicit","ukIpa":"/ɪˈlɪsɪt/","usIpa":"/ɪˈlɪsɪt/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"to cause someone to give information or show a reaction","vi":"gợi ra; khai thác; dẫn dụ"}],"examples":[{"en":"Her unexpected question elicited a smile from the normally quiet guide.","vi":"Câu hỏi bất ngờ của cô ấy đã khiến vị hướng dẫn viên vốn ít nói phải mỉm cười.","audioKind":"ex"},{"en":"Teachers can use open questions to elicit detailed responses and encourage independent thinking in the classroom.","vi":"Giáo viên có thể sử dụng các câu hỏi mở để gợi ra những câu trả lời chi tiết và khuyến khích tư duy độc lập trong lớp học.","audioKind":"ex2"}],"collocations":[{"en":"elicit a response","vi":"gợi ra phản hồi"},{"en":"elicit information","vi":"thu thập thông tin"},{"en":"elicit sympathy","vi":"khêu gợi sự đồng cảm"}],"wordFamily":["elicitation (n.)"],"synonyms":["evoke","draw out"],"antonyms":[],"tipVi":"Thường đi với các tân ngữ như response; tránh nhầm lẫn với từ illicit (trái pháp luật).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prospective', 'en-c1-2', 'prospective', '/prəˈspektɪv/', 'C1', 'tiềm năng; có triển vọng; sắp tới', 'adj.', 'prospect (n.)', 'Đồng nghĩa: potential', 'Thường đứng trước danh từ; tránh nhầm lẫn với từ perspective nghĩa là "góc nhìn".', 'The agent showed three prospective buyers around our flat.', NULL, 'Người môi giới đã dẫn ba vị khách mua nhà tiềm năng đi xem căn hộ của chúng tôi.', '{"wordId":"prospective","ukIpa":"/prəˈspektɪv/","usIpa":"/prəˈspektɪv/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Likely or hoping to become something in the future.","vi":"tiềm năng; có triển vọng; sắp tới"}],"examples":[{"en":"The agent showed three prospective buyers around our flat.","vi":"Người môi giới đã dẫn ba vị khách mua nhà tiềm năng đi xem căn hộ của chúng tôi.","audioKind":"ex"},{"en":"Universities should provide prospective students with clear information about tuition fees, course content, and career opportunities.","vi":"Các trường đại học nên cung cấp cho sinh viên tương lai thông tin rõ ràng về học phí, nội dung khóa học và cơ hội nghề nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"prospective students","vi":"sinh viên tương lai"},{"en":"prospective buyers","vi":"khách hàng tiềm năng"},{"en":"prospective employers","vi":"nhà tuyển dụng tiềm năng"}],"wordFamily":["prospect (n.)"],"synonyms":["potential"],"antonyms":[],"tipVi":"Thường đứng trước danh từ; tránh nhầm lẫn với từ perspective nghĩa là \"góc nhìn\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_2_1', 'en-c1-2', 'Cách dùng “exemplify” (v.) — là ví dụ điển hình cho; minh họa bằng ví dụ', 'exemplify a trend  ·  exemplify a principle  ·  exemplify the benefits of', 'Là ngoại động từ đi trực tiếp với danh từ; khi nêu gương hoặc làm ví dụ, cấu trúc bị động be exemplified by cũng hay được sử dụng.', 'Họ từ (Word Family): example (n.), exemplification (n.) | Đồng nghĩa: illustrate, demonstrate', '[{"hanzi":"Her handmade bowls exemplify the beauty of simple design.","pinyin":"","meaning":"Những chiếc bát thủ công của cô ấy là minh chứng tiêu biểu cho vẻ đẹp của thiết kế tối giản."},{"hanzi":"These community gardens exemplify how urban residents can improve local biodiversity while producing fresh food.","pinyin":"","meaning":"Những khu vườn cộng đồng này minh họa cách cư dân đô thị có thể cải thiện đa dạng sinh học địa phương trong khi vẫn sản xuất ra thực phẩm sạch."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_2_2', 'en-c1-2', 'Cách dùng “attain” (v.) — đạt được; giành được', 'attain a goal  ·  attain a high standard  ·  attain independence', 'Động từ chỉ trạng thái mang tính trang trọng, theo sau trực tiếp là mục tiêu hoặc cấp độ mà không cần dùng giới từ to.', 'Họ từ (Word Family): attainment (n.), attainable (adj.), unattainable (adj.) | Đồng nghĩa: achieve, reach', '[{"hanzi":"After months of practice, she attained her target swimming speed.","pinyin":"","meaning":"Sau nhiều tháng luyện tập, cô ấy đã đạt được tốc độ bơi mục tiêu của mình."},{"hanzi":"Students from disadvantaged backgrounds may need additional support to attain the qualifications required for university entry.","pinyin":"","meaning":"Học sinh đến từ các hoàn cảnh khó khăn có thể cần thêm sự hỗ trợ để đạt được các chứng chỉ cần thiết cho việc vào đại học."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_2_3', 'en-c1-2', 'Cách dùng “coherence” (n.) — sự mạch lạc; tính liên kết; tính logic', 'logical coherence  ·  overall coherence  ·  lack coherence', 'Nhấn mạnh sự liên kết về mặt ý tưởng, logic; trong khi "cohesion" nhấn mạnh liên kết về ngôn ngữ và hình thức.', 'Họ từ (Word Family): coherent (adj.), coherently (adv.), incoherent (adj.), incoherence (n.) | Đồng nghĩa: logical consistency · Trái nghĩa: incoherence', '[{"hanzi":"Your story needs more coherence between its different parts.","pinyin":"","meaning":"Câu chuyện của bạn cần sự liên kết chặt chẽ hơn giữa các phần khác nhau."},{"hanzi":"Clear paragraph structure improves the coherence of an essay and helps readers follow complex arguments.","pinyin":"","meaning":"Cấu trúc đoạn văn rõ ràng giúp nâng cao tính mạch lạc của bài luận và giúp người đọc nắm bắt được các lập luận phức tạp."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_2_4', 'en-c1-2', 'Cách dùng “wordy” (adj.) — dài dòng; rườm rà; nhiều lời', 'wordy explanation  ·  wordy sentence  ·  overly wordy', 'Thường mang nghĩa tiêu cực, chỉ việc dùng quá nhiều từ không cần thiết chứ không có nghĩa là vốn từ phong phú.', 'Họ từ (Word Family): word (n.), wordiness (n.) | Đồng nghĩa: verbose, long-winded · Trái nghĩa: concise, succinct', '[{"hanzi":"His wordy email made a simple request sound complicated.","pinyin":"","meaning":"Bức email dài dòng của anh ấy khiến cho một yêu cầu đơn giản trở nên phức tạp."},{"hanzi":"Public information should be clear, as wordy explanations can prevent readers from understanding essential advice.","pinyin":"","meaning":"Thông tin công cộng cần phải rõ ràng, bởi vì những lời giải thích dài dòng có thể cản trở độc giả hiểu được những lời khuyên cốt lõi."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_2_1', 'en-c1-2', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_1_1', 'ten_c1_2_1', 'impart', 'My grandmother loves to impart her gardening knowledge.', 'My grandmother loves to impart her gardening knowledge.', '/ɪmˈpɑːrt/', 'Bà tôi rất thích truyền lại những kiến thức làm vườn của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_1_2', 'ten_c1_2_1', 'coherence', 'Your story needs more coherence between its different parts.', 'Your story needs more coherence between its different parts.', '/koʊˈhɪrəns/', 'Câu chuyện của bạn cần sự liên kết chặt chẽ hơn giữa các phần khác nhau.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_1_3', 'ten_c1_2_1', 'enlighten', 'Could you enlighten me about how this camera works?', 'Could you enlighten me about how this camera works?', '/ɪnˈlaɪtən/', 'Bạn có thể giải thích cho tôi biết chiếc máy ảnh này hoạt động thế nào được không?', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_1_4', 'ten_c1_2_1', 'orientation', 'During orientation, a student guide showed us the library.', 'During orientation, a student guide showed us the library.', '/ˌɔːriənˈteɪʃən/', 'Trong buổi định hướng, một hướng dẫn viên sinh viên đã dẫn chúng tôi đi tham quan thư viện.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_1_5', 'ten_c1_2_1', 'symposium', 'Leila met several researchers at a symposium yesterday.', 'Leila met several researchers at a symposium yesterday.', '/sɪmˈpoʊziəm/', 'Leila đã gặp gỡ một số nhà nghiên cứu tại một hội nghị chuyên đề ngày hôm qua.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_1_6', 'ten_c1_2_1', 'attentive', 'The children were attentive as their grandmother explained the game.', 'The children were attentive as their grandmother explained the game.', '/əˈtentɪv/', 'Bọn trẻ chăm chú lắng nghe khi bà giải thích về trò chơi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_1_7', 'ten_c1_2_1', 'equivalence', 'The balanced scales showed the equivalence of the two weights.', 'The balanced scales showed the equivalence of the two weights.', '/ɪˈkwɪvələns/', 'Cái cân thăng bằng cho thấy trọng lượng của hai vật là tương đương nhau.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_1_8', 'ten_c1_2_1', 'truant', 'The teacher found two truants hiding behind the playground.', 'The teacher found two truants hiding behind the playground.', '/ˈtruːənt/', 'Giáo viên phát hiện hai học sinh trốn học đang nấp sau khu vui chơi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_2_1_1', 'en-c1-2', 'ten_c1_2_1', 'listening', 'listening', 'My grandmother loves to impart her gardening knowledge.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người môi giới đã dẫn ba vị khách mua nhà tiềm năng đi xem căn hộ của chúng tôi.","Podcast này giúp tôi học các cách diễn đạt thông dụng trong văn nói của bạn bè.","Bà tôi rất thích truyền lại những kiến thức làm vườn của mình.","Những chiếc bát thủ công của cô ấy là minh chứng tiêu biểu cho vẻ đẹp của thiết kế tối giản."]'::jsonb, 2, 'My grandmother loves to impart her gardening knowledge. → Bà tôi rất thích truyền lại những kiến thức làm vườn của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_2_1_2', 'en-c1-2', 'ten_c1_2_1', 'listening', 'listening', 'Your story needs more coherence between its different parts.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bà tôi hoàn thành việc học phổ thông tại một ngôi làng nhỏ.","Câu chuyện của bạn cần sự liên kết chặt chẽ hơn giữa các phần khác nhau.","Bạn có thể giải thích cho tôi biết chiếc máy ảnh này hoạt động thế nào được không?","Bức email dài dòng của anh ấy khiến cho một yêu cầu đơn giản trở nên phức tạp."]'::jsonb, 1, 'Your story needs more coherence between its different parts. → Câu chuyện của bạn cần sự liên kết chặt chẽ hơn giữa các phần khác nhau.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_2_1_3', 'en-c1-2', 'ten_c1_2_1', 'listening', 'listening', 'Could you enlighten me about how this camera works?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cẩm nang làm vườn này cung cấp những lời khuyên có tính chuyên môn cao về việc trồng rau.","Leila đã gặp gỡ một số nhà nghiên cứu tại một hội nghị chuyên đề ngày hôm qua.","Bạn có thể giải thích cho tôi biết chiếc máy ảnh này hoạt động thế nào được không?","Sau nhiều tháng luyện tập, cô ấy đã đạt được tốc độ bơi mục tiêu của mình."]'::jsonb, 2, 'Could you enlighten me about how this camera works? → Bạn có thể giải thích cho tôi biết chiếc máy ảnh này hoạt động thế nào được không?', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_2_2', 'en-c1-2', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_2_1', 'ten_c1_2_2', 'impart', 'Schools should impart practical skills that enable young people to manage their finances independently.', 'Schools should impart practical skills that enable young people to manage their finances independently.', '/ɪmˈpɑːrt/', 'Nhà trường nên truyền đạt các kỹ năng thực tế giúp người trẻ tự quản lý tài chính cá nhân.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_2_2', 'ten_c1_2_2', 'coherence', 'Clear paragraph structure improves the coherence of an essay and helps readers follow complex arguments.', 'Clear paragraph structure improves the coherence of an essay and helps readers follow complex arguments.', '/koʊˈhɪrəns/', 'Cấu trúc đoạn văn rõ ràng giúp nâng cao tính mạch lạc của bài luận và giúp người đọc nắm bắt được các lập luận phức tạp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_2_3', 'ten_c1_2_2', 'enlighten', 'Public health campaigns should enlighten citizens about the benefits of vaccination while addressing common concerns respectfully.', 'Public health campaigns should enlighten citizens about the benefits of vaccination while addressing common concerns respectfully.', '/ɪnˈlaɪtən/', 'Các chiến dịch y tế công cộng nên giúp người dân hiểu rõ những lợi ích của việc tiêm chủng đồng thời giải đáp những lo lắng phổ biến một cách tôn trọng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_2_4', 'ten_c1_2_2', 'orientation', 'A comprehensive orientation programme can help international students understand academic expectations and access essential support services.', 'A comprehensive orientation programme can help international students understand academic expectations and access essential support services.', '/ˌɔːriənˈteɪʃən/', 'Một chương trình định hướng toàn diện có thể giúp sinh viên quốc tế hiểu được các yêu cầu học tập và tiếp cận các dịch vụ hỗ trợ thiết yếu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_2_5', 'ten_c1_2_2', 'symposium', 'The international symposium brought together scientists to discuss practical solutions to urban air pollution.', 'The international symposium brought together scientists to discuss practical solutions to urban air pollution.', '/sɪmˈpoʊziəm/', 'Hội nghị chuyên đề quốc tế đã quy tụ các nhà khoa học để thảo luận về các giải pháp thiết thực cho tình trạng ô nhiễm không khí đô thị.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_2_2_6', 'ten_c1_2_2', 'attentive', 'Teachers who are attentive to individual learning needs can help students participate more confidently in classroom discussions.', 'Teachers who are attentive to individual learning needs can help students participate more confidently in classroom discussions.', '/əˈtentɪv/', 'Những giáo viên quan tâm chu đáo đến nhu cầu học tập cá nhân có thể giúp học sinh tự tin tham gia thảo luận trên lớp hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_2_2_1', 'en-c1-2', 'ten_c1_2_2', 'listening', 'listening', 'Schools should impart practical skills that enable young people to manage their finances independently.', NULL, 'Trong câu vừa nghe, từ “impart” mang nghĩa nào sau đây?', '["truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng","thuộc về triết học","làm cho thông thoáng; thông gió","sự lệch hướng, đổi hướng do va chạm hoặc lực tác động khác"]'::jsonb, 0, '“impart” (/ɪmˈpɑːrt/): truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng. Câu đầy đủ: Schools should impart practical skills that enable young people to manage their finances independently.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_2_2_2', 'en-c1-2', 'ten_c1_2_2', 'listening', 'listening', 'Clear paragraph structure improves the coherence of an essay and helps readers follow complex arguments.', NULL, 'Trong câu vừa nghe, từ “coherence” mang nghĩa nào sau đây?', '["sự cải tiến; sự tinh chỉnh nhỏ để hoàn thiện hơn","hệ thống điện báo; máy điện báo","cố tình tránh xa; xa lánh","sự mạch lạc; tính liên kết; tính logic"]'::jsonb, 3, '“coherence” (/koʊˈhɪrəns/): sự mạch lạc; tính liên kết; tính logic. Câu đầy đủ: Clear paragraph structure improves the coherence of an essay and helps readers follow complex arguments.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
