INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_2_1', 'en-c1-2', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “impart” (/ɪmˈpɑːrt/) có nghĩa là gì?', '["buổi định hướng, tuần lễ sinh hoạt đầu khóa (giúp người mới thích nghi với môi trường mới)","truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng","sự tương đương; tính tương đương","lời nói đầu; lời tựa; phần mở đầu"]'::jsonb, 1, '“impart” (v.): truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng; ban tặng; đem lại một đặc tính nào đó cho cái gì.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
