INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_2_4', 'en-c1-2', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “orientation” (/ˌɔːriənˈteɪʃən/) có nghĩa là gì?', '["hội nghị chuyên đề; hội thảo","làm quen; làm cho hiểu rõ; cung cấp thông tin","truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng","buổi định hướng, tuần lễ sinh hoạt đầu khóa (giúp người mới thích nghi với môi trường mới)"]'::jsonb, 3, '“orientation” (n.): buổi định hướng, tuần lễ sinh hoạt đầu khóa (giúp người mới thích nghi với môi trường mới); hướng, phương hướng (vị trí hướng về hoặc được đặt); khuynh hướng, định hướng (lợi ích, niềm tin hoặc sở thích cơ bản của cá nhân hoặc tổ chức).', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
