INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_1', 'en-c1-2', NULL, 'comprehensive_test', 'listening', 'impart', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mất dáng; không có hình thù rõ ràng; thùng thình","có khả năng chi trả; có khả năng thanh toán","biểu thị; có nghĩa là","truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng"]'::jsonb, 3, 'impart (/ɪmˈpɑːrt/) → truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng; ban tặng; đem lại một đặc tính nào đó cho cái gì', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_2', 'en-c1-2', NULL, 'comprehensive_test', 'listening', 'Your story needs more coherence between its different parts.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu chuyện của bạn cần sự liên kết chặt chẽ hơn giữa các phần khác nhau.","Bà tôi rất thích truyền lại những kiến thức làm vườn của mình.","Leila đã gặp gỡ một số nhà nghiên cứu tại một hội nghị chuyên đề ngày hôm qua.","Bạn có thể giải thích cho tôi biết chiếc máy ảnh này hoạt động thế nào được không?"]'::jsonb, 0, 'Your story needs more coherence between its different parts. → Câu chuyện của bạn cần sự liên kết chặt chẽ hơn giữa các phần khác nhau.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_3', 'en-c1-2', NULL, 'comprehensive_test', 'listening', 'enlighten', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chất đầy; mang nặng; trĩu","bờm (ngựa, sư tử, v.v.)","khai sáng; làm cho ai đó hiểu rõ","rác rưởi; chất dơ bẩn; vết nhơ"]'::jsonb, 2, 'enlighten (/ɪnˈlaɪtən/) → khai sáng; làm cho ai đó hiểu rõ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_4', 'en-c1-2', NULL, 'comprehensive_test', 'listening', 'During orientation, a student guide showed us the library.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trong buổi định hướng, một hướng dẫn viên sinh viên đã dẫn chúng tôi đi tham quan thư viện.","Tôi cần có thời gian để tiêu hóa và tiếp thu mọi thứ chúng ta đã học hôm nay.","Chị tôi đã giành được học bổng nghiên cứu về sinh vật biển.","Tiếng nói rõ ràng đầu tiên của em bé khiến ai nấy đều mỉm cười."]'::jsonb, 0, 'During orientation, a student guide showed us the library. → Trong buổi định hướng, một hướng dẫn viên sinh viên đã dẫn chúng tôi đi tham quan thư viện.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_5', 'en-c1-2', NULL, 'comprehensive_test', 'listening', 'symposium', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["định lượng; thuộc về số lượng","hội nghị chuyên đề; hội thảo","xoay sở, tìm cách làm được việc gì khó khăn hoặc bất ngờ","điều kiện bất lợi; trở ngại"]'::jsonb, 1, 'symposium (/sɪmˈpoʊziəm/) → hội nghị chuyên đề; hội thảo', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_6', 'en-c1-2', NULL, 'comprehensive_test', 'listening', 'The children were attentive as their grandmother explained the game.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bọn trẻ chăm chú lắng nghe khi bà giải thích về trò chơi.","Các giáo viên của chúng tôi phiên nhau gác các kỳ thi cuối kỳ.","Câu hỏi bất ngờ của cô ấy đã khiến vị hướng dẫn viên vốn ít nói phải mỉm cười.","Tác giả giải thích nguồn cảm hứng của mình trong phần lời nói đầu của cuốn sách."]'::jsonb, 0, 'The children were attentive as their grandmother explained the game. → Bọn trẻ chăm chú lắng nghe khi bà giải thích về trò chơi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_7', 'en-c1-2', NULL, 'comprehensive_test', 'listening', 'equivalence', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự tương đương; tính tương đương","khóc rống lên; kêu la thảm thiết","thông số; tham số","thuộc về sân khấu; kịch nghệ"]'::jsonb, 0, 'equivalence (/ɪˈkwɪvələns/) → sự tương đương; tính tương đương', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_8', 'en-c1-2', NULL, 'comprehensive_test', 'listening', 'The teacher found two truants hiding behind the playground.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiếng nói rõ ràng đầu tiên của em bé khiến ai nấy đều mỉm cười.","Người môi giới đã dẫn ba vị khách mua nhà tiềm năng đi xem căn hộ của chúng tôi.","Giáo viên phát hiện hai học sinh trốn học đang nấp sau khu vui chơi.","Cái cân thăng bằng cho thấy trọng lượng của hai vật là tương đương nhau."]'::jsonb, 2, 'The teacher found two truants hiding behind the playground. → Giáo viên phát hiện hai học sinh trốn học đang nấp sau khu vui chơi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
