INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_18', 'en-c1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should impart practical skills that enable young people to manage their finances independently.', 'Dựa vào câu trên, từ “impart” có nghĩa phù hợp nhất là gì?', '["truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng","hiền lành; rụt rè; dễ sai bảo; nhẫn nhục","nuôi dưỡng; cung cấp chất dinh dưỡng","thể hiện; hiện thân"]'::jsonb, 0, 'impart: truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng; ban tặng; đem lại một đặc tính nào đó cho cái gì. Dịch cả câu: Nhà trường nên truyền đạt các kỹ năng thực tế giúp người trẻ tự quản lý tài chính cá nhân.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_19', 'en-c1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Clear paragraph structure improves the coherence of an essay and helps readers follow complex arguments.', 'Dựa vào câu trên, từ “coherence” có nghĩa phù hợp nhất là gì?', '["thuộc về pháp y; thuộc về giám định tư pháp","sự mạch lạc; tính liên kết; tính logic","kinh tế vĩ mô","với mọi người; ở mọi nơi; khắp nơi"]'::jsonb, 1, 'coherence: sự mạch lạc; tính liên kết; tính logic. Dịch cả câu: Cấu trúc đoạn văn rõ ràng giúp nâng cao tính mạch lạc của bài luận và giúp người đọc nắm bắt được các lập luận phức tạp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_20', 'en-c1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Public health campaigns should enlighten citizens about the benefits of vaccination while addressing common concerns respectfully.', 'Dựa vào câu trên, từ “enlighten” có nghĩa phù hợp nhất là gì?', '["khai sáng; làm cho ai đó hiểu rõ","thích hợp; phải phép; xứng đáng","bao quanh; vây quanh","thuộc về tư pháp; thuộc tòa án hoặc việc thực thi công lý"]'::jsonb, 0, 'enlighten: khai sáng; làm cho ai đó hiểu rõ. Dịch cả câu: Các chiến dịch y tế công cộng nên giúp người dân hiểu rõ những lợi ích của việc tiêm chủng đồng thời giải đáp những lo lắng phổ biến một cách tôn trọng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_21', 'en-c1-2', NULL, 'comprehensive_test', 'reading', NULL, 'A comprehensive orientation programme can help international students understand academic expectations and access essential support services.', 'Dựa vào câu trên, từ “orientation” có nghĩa phù hợp nhất là gì?', '["sự giải thích chi tiết; sự bổ sung chi tiết","nhận ra; phân biệt","sự rõ ràng; dễ hiểu","buổi định hướng, tuần lễ sinh hoạt đầu khóa (giúp người mới thích nghi với môi trường mới)"]'::jsonb, 3, 'orientation: buổi định hướng, tuần lễ sinh hoạt đầu khóa (giúp người mới thích nghi với môi trường mới); hướng, phương hướng (vị trí hướng về hoặc được đặt); khuynh hướng, định hướng (lợi ích, niềm tin hoặc sở thích cơ bản của cá nhân hoặc tổ chức). Dịch cả câu: Một chương trình định hướng toàn diện có thể giúp sinh viên quốc tế hiểu được các yêu cầu học tập và tiếp cận các dịch vụ hỗ trợ thiết yếu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_22', 'en-c1-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngành nhân văn; nhân văn học”', '["mover","deceased","humanities","refined"]'::jsonb, 2, 'ngành nhân văn; nhân văn học → humanities (/hjuːˈmænətiz/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_23', 'en-c1-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gợi ra; khai thác; dẫn dụ”', '["elicit","stagger","tropic","authorize"]'::jsonb, 0, 'gợi ra; khai thác; dẫn dụ → elicit (/ɪˈlɪsɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_2_24', 'en-c1-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiềm năng; có triển vọng; sắp tới”', '["confine","stow","prospective","sovereignty"]'::jsonb, 2, 'tiềm năng; có triển vọng; sắp tới → prospective (/prəˈspektɪv/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-3', 'en', 'Bài 3: Giáo dục & Trường học (3) - CEFR C1', 'CEFR C1', 'C1 · Giáo dục', '24 từ vựng Tiếng Anh CEFR C1 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5003, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_phonetics', 'en-c1-3', 'phonetics', '/fəˈnetɪks/', 'C1', 'ngữ âm học', 'n.', 'phonetic (adj.), phonetically (adv.), phonetician (n.)', NULL, 'Mặc dù tận cùng bằng chữ -s, nhưng khi chỉ tên một môn học thì thường đi với động từ số ít.', 'We studied phonetics to understand how speech sounds are produced.', NULL, 'Chúng tôi đã học môn ngữ âm học để hiểu cách các âm thanh lời nói được tạo ra.', '{"wordId":"phonetics","ukIpa":"/fəˈnetɪks/","usIpa":"/fəˈnetɪks/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"The study of speech sounds and how people produce them.","vi":"ngữ âm học"}],"examples":[{"en":"We studied phonetics to understand how speech sounds are produced.","vi":"Chúng tôi đã học môn ngữ âm học để hiểu cách các âm thanh lời nói được tạo ra.","audioKind":"ex"},{"en":"Training in phonetics can help language teachers explain pronunciation differences that learners may struggle to hear.","vi":"Việc đào tạo về ngữ âm học có thể giúp giáo viên ngôn ngữ giải thích những khác biệt về phát âm mà người học có thể gặp khó khăn khi nghe.","audioKind":"ex2"}],"collocations":[{"en":"study phonetics","vi":"nghiên cứu ngữ âm học"},{"en":"articulatory phonetics","vi":"ngữ âm học cấu âm"},{"en":"acoustic phonetics","vi":"ngữ âm học âm học"}],"wordFamily":["phonetic (adj.)","phonetically (adv.)","phonetician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Mặc dù tận cùng bằng chữ -s, nhưng khi chỉ tên một môn học thì thường đi với động từ số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anthropology', 'en-c1-3', 'anthropology', '/ˌænθrəˈpɑːlədʒi/', 'C1', 'nhân học', 'n.', 'anthropologist (n.), anthropological (adj.)', NULL, 'Thường là danh từ không đếm được; nhà nghiên cứu lĩnh vực này gọi là anthropologist.', 'My cousin studies anthropology and collects stories about family traditions.', NULL, 'Anh họ của tôi học ngành nhân học và sưu tầm những câu chuyện về truyền thống gia đình.', '{"wordId":"anthropology","ukIpa":"/ˌænθrəˈpɒlədʒi/","usIpa":"/ˌænθrəˈpɑːlədʒi/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"the study of humans, their societies, cultures, and development","vi":"nhân học"}],"examples":[{"en":"My cousin studies anthropology and collects stories about family traditions.","vi":"Anh họ của tôi học ngành nhân học và sưu tầm những câu chuyện về truyền thống gia đình.","audioKind":"ex"},{"en":"Anthropology helps researchers understand how cultural traditions influence attitudes towards health, education, and family life.","vi":"Nhân học giúp các nhà nghiên cứu hiểu được các truyền thống văn hóa chi phối thái độ đối với sức khỏe, giáo dục và đời sống gia đình như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"cultural anthropology","vi":"nhân học văn hóa"},{"en":"social anthropology","vi":"nhân học xã hội"},{"en":"study anthropology","vi":"nghiên cứu nhân học"}],"wordFamily":["anthropologist (n.)","anthropological (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; nhà nghiên cứu lĩnh vực này gọi là anthropologist.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elaboration', 'en-c1-3', 'elaboration', '/ɪˌlæbəˈreɪʃən/', 'C1', 'sự giải thích chi tiết; sự bổ sung chi tiết', 'n.', 'elaborate (v.), elaborate (adj.), elaborately (adv.)', 'Đồng nghĩa: expansion, explanation', 'Dùng ''elaboration on'' khi muốn giải thích thêm về một điểm nào đó; động từ tương ứng là ''elaborate''.', 'Your plan sounds promising but needs a little elaboration.', NULL, 'Kế hoạch của bạn nghe rất khả quan nhưng vẫn cần thêm một chút chi tiết.', '{"wordId":"elaboration","ukIpa":"/ɪˌlæbəˈreɪʃən/","usIpa":"/ɪˌlæbəˈreɪʃən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"The addition of details to explain or develop something.","vi":"sự giải thích chi tiết; sự bổ sung chi tiết"}],"examples":[{"en":"Your plan sounds promising but needs a little elaboration.","vi":"Kế hoạch của bạn nghe rất khả quan nhưng vẫn cần thêm một chút chi tiết.","audioKind":"ex"},{"en":"Further elaboration on the proposed transport policy would help residents understand how their daily journeys might change.","vi":"Việc giải thích chi tiết hơn về chính sách giao thông được đề xuất sẽ giúp người dân hiểu rõ những thay đổi có thể diễn ra trong việc đi lại hàng ngày của họ.","audioKind":"ex2"}],"collocations":[{"en":"further elaboration","vi":"sự giải thích thêm"},{"en":"elaboration on a point","vi":"làm rõ một vấn đề"},{"en":"without elaboration","vi":"không có sự giải thích thêm"}],"wordFamily":["elaborate (v.)","elaborate (adj.)","elaborately (adv.)"],"synonyms":["expansion","explanation"],"antonyms":[],"tipVi":"Dùng ''elaboration on'' khi muốn giải thích thêm về một điểm nào đó; động từ tương ứng là ''elaborate''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_layman', 'en-c1-3', 'layman', '/ˈleɪmən/', 'C1', 'người ngoại đạo; người không chuyên môn; giáo dân (thành viên nam giới trong giáo hội không phải linh mục)', 'n.', 'lay (adj.), layperson (n.), laypeople (n.)', 'Đồng nghĩa: non-specialist · Trái nghĩa: expert, specialist', 'Khi chỉ chung người không chuyên, từ layperson mang tính bao quát giới tính hơn.', 'The mechanic explained the problem in layman''s terms.', NULL, 'Thợ máy đã giải thích sự cố bằng những thuật ngữ thông dụng mà người ngoài ngành cũng hiểu được.', '{"wordId":"layman","ukIpa":"/ˈleɪmən/","usIpa":"/ˈleɪmən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"someone without specialist knowledge of a particular subject","vi":"người ngoại đạo; người không chuyên môn"},{"pos":"n.","en":"a male religious member who is not a priest or minister","vi":"giáo dân (thành viên nam giới trong giáo hội không phải linh mục)"}],"examples":[{"en":"The mechanic explained the problem in layman''s terms.","vi":"Thợ máy đã giải thích sự cố bằng những thuật ngữ thông dụng mà người ngoài ngành cũng hiểu được.","audioKind":"ex"},{"en":"Scientific reports should include summaries that a layman can understand without specialist training.","vi":"Các báo cáo khoa học nên có phần tóm tắt mà một người không chuyên cũng có thể hiểu được mà không cần qua đào tạo chuyên sâu.","audioKind":"ex2"}],"collocations":[{"en":"in layman''s terms","vi":"bằng ngôn ngữ thông thường dễ hiểu"},{"en":"explain to a layman","vi":"giải thích cho người không chuyên"}],"wordFamily":["lay (adj.)","layperson (n.)","laypeople (n.)"],"synonyms":["non-specialist"],"antonyms":["expert","specialist"],"tipVi":"Khi chỉ chung người không chuyên, từ layperson mang tính bao quát giới tính hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_endow', 'en-c1-3', 'endow', '/ɪnˈdaʊ/', 'C1', 'quyên góp tiền lập quỹ; tài trợ lâu dài cho một tổ chức; trời phú cho; ban cho ai đó phẩm chất hoặc năng lực đặc biệt', 'v.', 'endowment (n.)', NULL, 'Cụm từ be endowed with thường chỉ việc bẩm sinh đã có năng lực hoặc phẩm chất nào đó.', 'Her family endowed a scholarship at the local college.', NULL, 'Gia đình cô ấy đã tài trợ thành lập một học bổng tại trường cao đẳng địa phương.', '{"wordId":"endow","ukIpa":"/ɪnˈdaʊ/","usIpa":"/ɪnˈdaʊ/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"give money to support an institution or position permanently","vi":"quyên góp tiền lập quỹ; tài trợ lâu dài cho một tổ chức"},{"pos":"v.","en":"give someone or something a particular quality or ability","vi":"trời phú cho; ban cho ai đó phẩm chất hoặc năng lực đặc biệt"}],"examples":[{"en":"Her family endowed a scholarship at the local college.","vi":"Gia đình cô ấy đã tài trợ thành lập một học bổng tại trường cao đẳng địa phương.","audioKind":"ex"},{"en":"Private donations can endow research centres that investigate long-term solutions to urgent public health problems.","vi":"Các khoản đóng góp tư nhân có thể tài trợ cho các trung tâm nghiên cứu nhằm tìm kiếm giải pháp dài hạn cho các vấn đề y tế công cộng cấp bách.","audioKind":"ex2"}],"collocations":[{"en":"endow a scholarship","vi":"trao học bổng"},{"en":"endow a chair","vi":"tài trợ ghế giáo sư"},{"en":"be endowed with","vi":"vốn có; được ban cho"}],"wordFamily":["endowment (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ be endowed with thường chỉ việc bẩm sinh đã có năng lực hoặc phẩm chất nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_immerse', 'en-c1-3', 'immerse', '/ɪˈmɝːs/', 'C1', 'làm cho đắm chìm; khiến cho mải mê vào hoạt động hoặc trải nghiệm nào đó; nhấn chìm hoàn toàn xuống dưới bề mặt chất lỏng', 'v.', 'immersion (n.), immersive (adj.)', 'Đồng nghĩa: absorb, submerge', 'Cụm từ "immerse yourself in" dùng để chỉ việc đắm chìm vào việc gì đó, chú ý sử dụng đúng đại từ phản thân.', 'On rainy afternoons, I immerse myself in a novel.', NULL, 'Vào những buổi chiều mưa, tôi thường đắm mình trong những trang tiểu thuyết.', '{"wordId":"immerse","ukIpa":"/ɪˈmɜːs/","usIpa":"/ɪˈmɝːs/","cefr":"C1","topic":"education","senses":[{"pos":"v.","en":"to involve someone deeply in an activity or experience","vi":"làm cho đắm chìm; khiến cho mải mê vào hoạt động hoặc trải nghiệm nào đó"},{"pos":"v.","en":"to put something completely beneath the surface of a liquid","vi":"nhấn chìm hoàn toàn xuống dưới bề mặt chất lỏng"}],"examples":[{"en":"On rainy afternoons, I immerse myself in a novel.","vi":"Vào những buổi chiều mưa, tôi thường đắm mình trong những trang tiểu thuyết.","audioKind":"ex"},{"en":"Exchange programmes allow students to immerse themselves in another culture and develop greater independence.","vi":"Các chương trình trao đổi giúp sinh viên đắm mình vào một nền văn hóa khác và phát triển tính tự lập cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"immerse yourself in","vi":"đắm mình vào"},{"en":"fully immersed in","vi":"hoàn toàn đắm chìm trong"},{"en":"immerse in water","vi":"nhúng vào nước"}],"wordFamily":["immersion (n.)","immersive (adj.)"],"synonyms":["absorb","submerge"],"antonyms":[],"tipVi":"Cụm từ \"immerse yourself in\" dùng để chỉ việc đắm chìm vào việc gì đó, chú ý sử dụng đúng đại từ phản thân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_numerate', 'en-c1-3', 'numerate', '/ˈnuːmərət/', 'C1', 'có khả năng tính toán; giỏi tính toán', 'adj.', 'numeracy (n.), innumerate (adj.), innumeracy (n.)', 'Trái nghĩa: innumerate', 'Hiện đại thường dùng làm tính từ, chỉ năng lực tính toán; danh từ tương ứng là numeracy.', 'The shop needs numerate staff who can calculate change.', NULL, 'Cửa hàng cần nhân viên có khả năng tính toán tốt để tính tiền thối lại.', '{"wordId":"numerate","ukIpa":"/ˈnjuːmərət/","usIpa":"/ˈnuːmərət/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"able to understand and work with numbers","vi":"có khả năng tính toán; giỏi tính toán"}],"examples":[{"en":"The shop needs numerate staff who can calculate change.","vi":"Cửa hàng cần nhân viên có khả năng tính toán tốt để tính tiền thối lại.","audioKind":"ex"},{"en":"Schools should ensure that all students become numerate enough to manage personal finances and interpret basic statistics.","vi":"Nhà trường nên đảm bảo rằng tất cả học sinh đều có đủ năng lực tính toán để quản lý tài chính cá nhân và hiểu các số liệu thống kê cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"numerate staff","vi":"nhân viên có khả năng tính toán"},{"en":"highly numerate","vi":"có năng lực tính toán rất cao"},{"en":"literate and numerate","vi":"vừa biết đọc viết vừa có khả năng tính toán"}],"wordFamily":["numeracy (n.)","innumerate (adj.)","innumeracy (n.)"],"synonyms":[],"antonyms":["innumerate"],"tipVi":"Hiện đại thường dùng làm tính từ, chỉ năng lực tính toán; danh từ tương ứng là numeracy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_synopsis', 'en-c1-3', 'synopsis', '/sɪˈnɑːpsɪs/', 'C1', 'bản tóm tắt; cốt truyện; đề cương', 'n.', 'synoptic (adj.)', 'Đồng nghĩa: summary, outline, overview', 'Dạng số nhiều là synopses; thường dùng cấu trúc a synopsis of để chỉ bản tóm tắt của một tác phẩm nào đó.', 'I read the synopsis before borrowing the novel.', NULL, 'Tôi đã đọc phần tóm tắt cốt truyện trước khi mượn cuốn tiểu thuyết đó.', '{"wordId":"synopsis","ukIpa":"/sɪˈnɒpsɪs/","usIpa":"/sɪˈnɑːpsɪs/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"A short account of the main points of a work.","vi":"bản tóm tắt; cốt truyện; đề cương"}],"examples":[{"en":"I read the synopsis before borrowing the novel.","vi":"Tôi đã đọc phần tóm tắt cốt truyện trước khi mượn cuốn tiểu thuyết đó.","audioKind":"ex"},{"en":"Students should provide a brief synopsis of their proposed research before discussing the methods they intend to use.","vi":"Học sinh nên cung cấp một bản tóm tắt ngắn gọn về đề tài nghiên cứu dự kiến trước khi thảo luận về các phương pháp các em dự định sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"a brief synopsis","vi":"một bản tóm tắt ngắn gọn"},{"en":"a plot synopsis","vi":"tóm tắt cốt truyện"},{"en":"a synopsis of the report","vi":"bản tóm tắt báo cáo"}],"wordFamily":["synoptic (adj.)"],"synonyms":["summary","outline","overview"],"antonyms":[],"tipVi":"Dạng số nhiều là synopses; thường dùng cấu trúc a synopsis of để chỉ bản tóm tắt của một tác phẩm nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_above-mentioned', 'en-c1-3', 'above-mentioned', '/əˌbʌv ˈmenʃənd/', 'C1', 'đã nêu trên; nhắc đến ở trên', 'adj.', 'mention (v.)', 'Đồng nghĩa: aforementioned', 'Đây là văn phong trang trọng chuyên dùng trong văn bản viết, thường đứng trước danh từ; cần tránh lạm dụng trong văn viết hàng ngày.', 'Please bring the above-mentioned documents to our next meeting.', NULL, 'Vui lòng mang các tài liệu đã nêu trên đến cuộc họp tiếp theo của chúng ta.', '{"wordId":"above-mentioned","ukIpa":"/əˌbʌv ˈmenʃənd/","usIpa":"/əˌbʌv ˈmenʃənd/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Already referred to earlier in a piece of writing.","vi":"đã nêu trên; nhắc đến ở trên"}],"examples":[{"en":"Please bring the above-mentioned documents to our next meeting.","vi":"Vui lòng mang các tài liệu đã nêu trên đến cuộc họp tiếp theo của chúng ta.","audioKind":"ex"},{"en":"The above-mentioned measures could reduce urban air pollution if local authorities provide sufficient funding and oversight.","vi":"Các biện pháp vừa nêu trên có thể giúp giảm ô nhiễm không khí đô thị nếu chính quyền địa phương cung cấp đủ nguồn vốn và công tác giám sát.","audioKind":"ex2"}],"collocations":[{"en":"above-mentioned documents","vi":"các tài liệu đã nêu trên"},{"en":"above-mentioned measures","vi":"các biện pháp kể trên"},{"en":"above-mentioned factors","vi":"các yếu tố nêu trên"}],"wordFamily":["mention (v.)"],"synonyms":["aforementioned"],"antonyms":[],"tipVi":"Đây là văn phong trang trọng chuyên dùng trong văn bản viết, thường đứng trước danh từ; cần tránh lạm dụng trong văn viết hàng ngày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_registrar', 'en-c1-3', 'registrar', '/ˈredʒɪstrɑːr/', 'C1', 'nhân viên đăng ký; thư ký quản lý hồ sơ; bác sĩ nội trú chuyên khoa (tại Anh)', 'n.', 'register (v.), registration (n.), registered (adj.)', NULL, 'Có thể chỉ cán bộ hộ tịch/đăng ký hoặc bác sĩ đang nhận đào tạo chuyên khoa ở Anh.', 'The registrar checked our documents before the wedding ceremony.', NULL, 'Nhân viên đăng ký đã kiểm tra giấy tờ của chúng tôi trước lễ cưới.', '{"wordId":"registrar","ukIpa":"/ˌredʒɪˈstrɑː/","usIpa":"/ˈredʒɪstrɑːr/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"An official responsible for keeping formal records.","vi":"nhân viên đăng ký; thư ký quản lý hồ sơ"},{"pos":"n.","en":"A hospital doctor receiving advanced specialist training in Britain.","vi":"bác sĩ nội trú chuyên khoa (tại Anh)"}],"examples":[{"en":"The registrar checked our documents before the wedding ceremony.","vi":"Nhân viên đăng ký đã kiểm tra giấy tờ của chúng tôi trước lễ cưới.","audioKind":"ex"},{"en":"The university registrar oversees student records and ensures that graduation requirements are consistently applied.","vi":"Trưởng phòng quản lý đào tạo đại học giám sát hồ sơ sinh viên và đảm bảo các yêu cầu tốt nghiệp được áp dụng đồng bộ.","audioKind":"ex2"}],"collocations":[{"en":"university registrar","vi":"cán bộ đăng ký đại học"},{"en":"registrar''s office","vi":"phòng đăng ký"},{"en":"specialist registrar","vi":"bác sĩ nội trú chuyên khoa"}],"wordFamily":["register (v.)","registration (n.)","registered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ cán bộ hộ tịch/đăng ký hoặc bác sĩ đang nhận đào tạo chuyên khoa ở Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_studious', 'en-c1-3', 'studious', '/ˈstuːdiəs/', 'C1', 'chăm chỉ học hành; hiếu học; cẩn trọng; hết sức chú tâm; có tính toán kỹ lưỡng', 'adj.', 'study (v.), study (n.), studiously (adv.), studiousness (n.)', 'Đồng nghĩa: diligent, scholarly', 'Khi dùng để chỉ con người, từ này có nghĩa là chăm học; cụm từ studious avoidance có nghĩa là sự cố ý hoặc chủ động tránh né điều gì đó.', 'My studious roommate spends most evenings in the library.', NULL, 'Bạn cùng phòng chăm chỉ của tôi dành phần lớn các buổi tối ở trong thư viện.', '{"wordId":"studious","ukIpa":"/ˈstjuːdiəs/","usIpa":"/ˈstuːdiəs/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Spending much time studying and enjoying learning.","vi":"chăm chỉ học hành; hiếu học"},{"pos":"adj.","en":"Done with deliberate care and close attention.","vi":"cẩn trọng; hết sức chú tâm; có tính toán kỹ lưỡng"}],"examples":[{"en":"My studious roommate spends most evenings in the library.","vi":"Bạn cùng phòng chăm chỉ của tôi dành phần lớn các buổi tối ở trong thư viện.","audioKind":"ex"},{"en":"Studious pupils benefit from quiet learning environments, but they also need opportunities for physical activity.","vi":"Những học sinh chăm chỉ học tập được hưởng lợi từ môi trường học tập yên tĩnh, nhưng các em cũng cần có cơ hội tham gia các hoạt động thể chất.","audioKind":"ex2"}],"collocations":[{"en":"a studious pupil","vi":"một học sinh chăm chỉ"},{"en":"studious attention","vi":"sự chú ý tỉ mỉ"},{"en":"studious avoidance","vi":"sự cố ý tránh né"}],"wordFamily":["study (v.)","study (n.)","studiously (adv.)","studiousness (n.)"],"synonyms":["diligent","scholarly"],"antonyms":[],"tipVi":"Khi dùng để chỉ con người, từ này có nghĩa là chăm học; cụm từ studious avoidance có nghĩa là sự cố ý hoặc chủ động tránh né điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_derivation', 'en-c1-3', 'derivation', '/ˌderəˈveɪʃən/', 'C1', 'nguồn gốc từ; từ nguyên; sự bắt nguồn; sự suy diễn; sự cấu tạo', 'n.', 'derive (v.), derivative (n.), derivational (adj.)', 'Đồng nghĩa: origin', 'Động từ đi kèm là derive A from B, mang ý nghĩa A bắt nguồn từ B.', 'Our teacher explained the derivation of this unusual word.', NULL, 'Giáo viên của chúng tôi đã giải thích nguồn gốc của từ lạ này.', '{"wordId":"derivation","ukIpa":"/ˌderɪˈveɪʃən/","usIpa":"/ˌderəˈveɪʃən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"the origin of something, especially a word","vi":"nguồn gốc từ; từ nguyên"},{"pos":"n.","en":"the process of forming something from an existing source","vi":"sự bắt nguồn; sự suy diễn; sự cấu tạo"}],"examples":[{"en":"Our teacher explained the derivation of this unusual word.","vi":"Giáo viên của chúng tôi đã giải thích nguồn gốc của từ lạ này.","audioKind":"ex"},{"en":"Understanding the derivation of scientific terms can help students recognise connections between concepts across different subjects.","vi":"Việc hiểu rõ nguồn gốc của các thuật ngữ khoa học có thể giúp học sinh nhận ra mối liên hệ giữa các khái niệm ở các môn học khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"the derivation of a word","vi":"nguồn gốc của một từ"},{"en":"word derivation","vi":"sự cấu tạo từ"},{"en":"the derivation of a formula","vi":"phép suy diễn công thức"}],"wordFamily":["derive (v.)","derivative (n.)","derivational (adj.)"],"synonyms":["origin"],"antonyms":[],"tipVi":"Động từ đi kèm là derive A from B, mang ý nghĩa A bắt nguồn từ B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recitation', 'en-c1-3', 'recitation', '/ˌresəˈteɪʃən/', 'C1', 'sự ngâm thơ; sự đọc thuộc lòng', 'n.', 'recite (v.)', NULL, 'Recitation chỉ hoạt động đọc thuộc lòng/ngâm thơ; động từ tương ứng là recite.', 'Her recitation of the poem moved everyone in the room.', NULL, 'Màn ngâm thơ của cô ấy đã làm rung động tất cả mọi người trong phòng.', '{"wordId":"recitation","ukIpa":"/ˌresɪˈteɪʃən/","usIpa":"/ˌresəˈteɪʃən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"The act of saying a poem or passage aloud from memory.","vi":"sự ngâm thơ; sự đọc thuộc lòng"}],"examples":[{"en":"Her recitation of the poem moved everyone in the room.","vi":"Màn ngâm thơ của cô ấy đã làm rung động tất cả mọi người trong phòng.","audioKind":"ex"},{"en":"Regular recitation can help language learners improve pronunciation, although it should be combined with spontaneous conversation.","vi":"Việc đọc thuộc lòng thường xuyên có thể giúp người học ngoại ngữ cải thiện phát âm, mặc dù nó nên được kết hợp với các bài tập hội thoại tự phát.","audioKind":"ex2"}],"collocations":[{"en":"poetry recitation","vi":"ngâm thơ"},{"en":"recitation from memory","vi":"đọc thuộc lòng không cần nhìn văn bản"},{"en":"give a recitation","vi":"biểu diễn ngâm thơ"}],"wordFamily":["recite (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Recitation chỉ hoạt động đọc thuộc lòng/ngâm thơ; động từ tương ứng là recite.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acquisition', 'en-c1-3', 'acquisition', '/ˌækwɪˈzɪʃən/', 'C1', 'sự thu được; sự tiếp thu; quá trình học được; sự thâu tóm doanh nghiệp; vật phẩm mới mua', 'n.', 'acquire (v.), acquired (adj.)', NULL, 'Quá trình tiếp thu thường không đếm được; giao dịch mua lại hoặc vật phẩm mua được có thể đếm được.', 'Daily conversations helped with her acquisition of new vocabulary.', NULL, 'Những cuộc trò chuyện hàng ngày đã giúp cô ấy tiếp thu vốn từ vựng mới.', '{"wordId":"acquisition","ukIpa":"/ˌækwɪˈzɪʃən/","usIpa":"/ˌækwɪˈzɪʃən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"the process of obtaining something or developing knowledge and skills","vi":"sự thu được; sự tiếp thu; quá trình học được"},{"pos":"n.","en":"the purchase of a business, or something that has been obtained","vi":"sự thâu tóm doanh nghiệp; vật phẩm mới mua"}],"examples":[{"en":"Daily conversations helped with her acquisition of new vocabulary.","vi":"Những cuộc trò chuyện hàng ngày đã giúp cô ấy tiếp thu vốn từ vựng mới.","audioKind":"ex"},{"en":"Early exposure to varied speech can support language acquisition and strengthen children''s ability to communicate effectively.","vi":"Việc tiếp xúc sớm với nhiều cách diễn đạt ngôn ngữ khác nhau có thể thúc đẩy quá trình thụ đắc ngôn ngữ và nâng cao khả năng giao tiếp hiệu quả của trẻ.","audioKind":"ex2"}],"collocations":[{"en":"language acquisition","vi":"thụ đắc ngôn ngữ"},{"en":"acquisition of skills","vi":"sự tích 1 lũy kỹ năng"},{"en":"mergers and acquisitions","vi":"mua bán và sáp nhập doanh nghiệp"},{"en":"make an acquisition","vi":"thực hiện một thương vụ thâu tóm"}],"wordFamily":["acquire (v.)","acquired (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá trình tiếp thu thường không đếm được; giao dịch mua lại hoặc vật phẩm mua được có thể đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expulsion', 'en-c1-3', 'expulsion', '/ɪkˈspʌlʃən/', 'C1', 'sự đuổi học; sự trục xuất; sự khai trừ; sự tống ra; sự bài xuất; sự đẩy ra', 'n.', 'expel (v.)', 'Đồng nghĩa: removal, ejection · Trái nghĩa: admission', 'Thường đi với giới từ expulsion from; động từ tương ứng là expel.', 'Repeated cheating led to his expulsion from the club.', NULL, 'Việc gian lận nhiều lần đã dẫn đến việc anh ấy bị đuổi khỏi câu lạc bộ.', '{"wordId":"expulsion","ukIpa":"/ɪkˈspʌlʃən/","usIpa":"/ɪkˈspʌlʃən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"The act of officially forcing someone to leave a place.","vi":"sự đuổi học; sự trục xuất; sự khai trừ"},{"pos":"n.","en":"The process of forcing something out of a space or body.","vi":"sự tống ra; sự bài xuất; sự đẩy ra"}],"examples":[{"en":"Repeated cheating led to his expulsion from the club.","vi":"Việc gian lận nhiều lần đã dẫn đến việc anh ấy bị đuổi khỏi câu lạc bộ.","audioKind":"ex"},{"en":"Schools should consider supportive interventions before expulsion, as exclusion can seriously damage a young person''s educational prospects.","vi":"Các trường học nên cân nhắc các biện pháp can thiệp hỗ trợ trước khi đưa ra quyết định kỷ luật đuổi học, bởi việc buộc thôi học có thể gây tổn hại nghiêm trọng đến triển vọng học tập của một người trẻ.","audioKind":"ex2"}],"collocations":[{"en":"expulsion from school","vi":"bị đuổi học"},{"en":"face expulsion","vi":"đối mặt với nguy cơ bị đuổi"},{"en":"expulsion of air","vi":"sự tống xuất không khí"}],"wordFamily":["expel (v.)"],"synonyms":["removal","ejection"],"antonyms":["admission"],"tipVi":"Thường đi với giới từ expulsion from; động từ tương ứng là expel.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discourse', 'en-c1-3', 'discourse', '/ˈdɪskɔːrs/', 'C1', 'bài luận; cuộc thảo luận trang trọng; bài thuyết trình; diễn ngôn; ngôn bản; lời nói trong ngữ cảnh xã hội', 'n.', 'discursive (adj.)', 'Đồng nghĩa: discussion', 'Văn phong trang trọng; trong ngôn ngữ học có nghĩa là diễn ngôn hoặc văn bản, không đồng nghĩa với bài báo nghiên cứu.', 'Her lecture encouraged thoughtful discourse about local history.', NULL, 'Bài giảng của cô ấy đã khuyến khích cuộc thảo luận sâu sắc về lịch sử địa phương.', '{"wordId":"discourse","ukIpa":"/ˈdɪskɔːs/","usIpa":"/ˈdɪskɔːrs/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"Serious spoken or written discussion of a particular subject.","vi":"bài luận; cuộc thảo luận trang trọng; bài thuyết trình"},{"pos":"n.","en":"Spoken or written language studied in its social context.","vi":"diễn ngôn; ngôn bản; lời nói trong ngữ cảnh xã hội"}],"examples":[{"en":"Her lecture encouraged thoughtful discourse about local history.","vi":"Bài giảng của cô ấy đã khuyến khích cuộc thảo luận sâu sắc về lịch sử địa phương.","audioKind":"ex"},{"en":"Public discourse on climate change increasingly focuses on practical solutions rather than distant predictions.","vi":"Cuộc thảo luận công khai về biến đổi khí hậu ngày càng tập trung vào các giải pháp thực tế thay vì những dự đoán xa vời.","audioKind":"ex2"}],"collocations":[{"en":"public discourse","vi":"thảo luận công khai"},{"en":"political discourse","vi":"diễn ngôn chính trị"},{"en":"discourse analysis","vi":"phân tích diễn ngôn"}],"wordFamily":["discursive (adj.)"],"synonyms":["discussion"],"antonyms":[],"tipVi":"Văn phong trang trọng; trong ngôn ngữ học có nghĩa là diễn ngôn hoặc văn bản, không đồng nghĩa với bài báo nghiên cứu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commencement', 'en-c1-3', 'commencement', '/kəˈmensmənt/', 'C1', 'sự khởi đầu; sự bắt đầu; lễ tốt nghiệp (Mỹ)', 'n.', 'commence (v.)', 'Đồng nghĩa: beginning, start · Trái nghĩa: conclusion', 'Diễn đạt ý "bắt đầu" một cách trang trọng; trong tiếng Anh-Mỹ còn có nghĩa là lễ tốt nghiệp.', 'We heard a whistle at the commencement of play.', NULL, 'Chúng tôi nghe tiếng còi cất lên ngay khi trận đấu bắt đầu.', '{"wordId":"commencement","ukIpa":"/kəˈmensmənt/","usIpa":"/kəˈmensmənt/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"The beginning of something, especially an official activity","vi":"sự khởi đầu; sự bắt đầu"},{"pos":"n.","en":"A ceremony celebrating students completing their studies in the United States","vi":"lễ tốt nghiệp (Mỹ)"}],"examples":[{"en":"We heard a whistle at the commencement of play.","vi":"Chúng tôi nghe tiếng còi cất lên ngay khi trận đấu bắt đầu.","audioKind":"ex"},{"en":"Environmental assessments should be completed before the commencement of construction to minimise potential damage to local ecosystems.","vi":"Các đánh giá tác động môi trường nên được hoàn thành trước khi khởi công xây dựng nhằm giảm thiểu tối đa tổn hại tiềm ẩn đối với hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"the commencement of work","vi":"sự khởi đầu của công việc"},{"en":"a commencement date","vi":"ngày bắt đầu"},{"en":"a commencement ceremony","vi":"lễ tốt nghiệp"}],"wordFamily":["commence (v.)"],"synonyms":["beginning","start"],"antonyms":["conclusion"],"tipVi":"Diễn đạt ý \"bắt đầu\" một cách trang trọng; trong tiếng Anh-Mỹ còn có nghĩa là lễ tốt nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transcript', 'en-c1-3', 'transcript', '/ˈtrænskrɪpt/', 'C1', 'bản ghi chép lời thoại; bản thảo; bảng điểm học tập', 'n.', 'transcribe (v.), transcription (n.)', NULL, 'Transcript có thể chỉ bản ghi âm chữ viết hoặc bảng điểm chính thức của học sinh, sinh viên.', 'I read the transcript while listening to the interview.', NULL, 'Tôi vừa đọc bản ghi chép vừa lắng nghe đoạn phỏng vấn.', '{"wordId":"transcript","ukIpa":"/ˈtrænskrɪpt/","usIpa":"/ˈtrænskrɪpt/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"a written record of words spoken in a conversation or recording","vi":"bản ghi chép lời thoại; bản thảo"},{"pos":"n.","en":"an official record of a student''s courses and grades","vi":"bảng điểm học tập"}],"examples":[{"en":"I read the transcript while listening to the interview.","vi":"Tôi vừa đọc bản ghi chép vừa lắng nghe đoạn phỏng vấn.","audioKind":"ex"},{"en":"Researchers checked each interview transcript carefully before analysing participants'' views on public transport services.","vi":"Các nhà nghiên cứu đã kiểm tra kỹ lưỡng từng bản ghi chép phỏng vấn trước khi phân tích quan điểm của người tham gia về dịch vụ giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"interview transcript","vi":"bản ghi chép phỏng vấn"},{"en":"academic transcript","vi":"bảng điểm đại học"},{"en":"a full transcript","vi":"bản ghi chép đầy đủ"}],"wordFamily":["transcribe (v.)","transcription (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Transcript có thể chỉ bản ghi âm chữ viết hoặc bảng điểm chính thức của học sinh, sinh viên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_self-access', 'en-c1-3', 'self-access', '/ˌself ˈækses/', 'C1', 'cho phép tự học; tự chọn tài liệu học tập; sự học tập tự lực qua các tài liệu do người học tự chọn', 'adj.', NULL, NULL, 'Chủ yếu dùng trong giáo dục, nhấn mạnh việc tự chủ chọn và sử dụng nguồn tài liệu học tập.', 'Our library has a quiet self-access learning area.', NULL, 'Thư viện trường chúng tôi có một khu vực tự học yên tĩnh.', '{"wordId":"self-access","ukIpa":"/ˌself ˈækses/","usIpa":"/ˌself ˈækses/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"allowing learners to choose and use materials independently","vi":"cho phép tự học; tự chọn tài liệu học tập"},{"pos":"n.","en":"independent learning using materials chosen by the learner","vi":"sự học tập tự lực qua các tài liệu do người học tự chọn"}],"examples":[{"en":"Our library has a quiet self-access learning area.","vi":"Thư viện trường chúng tôi có một khu vực tự học yên tĩnh.","audioKind":"ex"},{"en":"Self-access centres encourage students to take responsibility for their progress by selecting materials suited to their needs.","vi":"Trung tâm tự học khuyến khích sinh viên tự chịu trách nhiệm về tiến độ học tập của mình bằng cách chọn các tài liệu phù hợp với nhu cầu.","audioKind":"ex2"}],"collocations":[{"en":"self-access centre","vi":"trung tâm tự học"},{"en":"self-access materials","vi":"tài liệu tự học"},{"en":"self-access learning","vi":"việc tự học qua tài liệu tự chọn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu dùng trong giáo dục, nhấn mạnh việc tự chủ chọn và sử dụng nguồn tài liệu học tập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clarification', 'en-c1-3', 'clarification', '/ˌklærəfəˈkeɪʃən/', 'C1', 'sự làm rõ; lời giải thích thêm', 'n.', 'clarify (v.), clarity (n.), clear (adj.)', 'Đồng nghĩa: explanation', 'Thường dùng clarification of hoặc on; thường là danh từ không đếm được.', 'I asked for clarification before signing the rental agreement.', NULL, 'Tôi đã yêu cầu giải thích rõ hơn trước khi ký hợp đồng thuê nhà.', '{"wordId":"clarification","ukIpa":"/ˌklærɪfɪˈkeɪʃən/","usIpa":"/ˌklærəfəˈkeɪʃən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"an explanation that makes something clearer or easier to understand","vi":"sự làm rõ; lời giải thích thêm"}],"examples":[{"en":"I asked for clarification before signing the rental agreement.","vi":"Tôi đã yêu cầu giải thích rõ hơn trước khi ký hợp đồng thuê nhà.","audioKind":"ex"},{"en":"Students benefit from clarification of assessment criteria before they begin complex research assignments at university.","vi":"Sinh viên được hưởng lợi từ việc làm rõ các tiêu chí đánh giá trước khi bắt đầu các bài tập nghiên cứu phức tạp ở bậc đại học.","audioKind":"ex2"}],"collocations":[{"en":"ask for clarification","vi":"yêu cầu làm rõ"},{"en":"provide clarification","vi":"đưa ra lời giải thích"},{"en":"clarification of the rules","vi":"làm rõ các quy định"},{"en":"seek clarification on","vi":"tìm kiếm sự giải thích về"}],"wordFamily":["clarify (v.)","clarity (n.)","clear (adj.)"],"synonyms":["explanation"],"antonyms":[],"tipVi":"Thường dùng clarification of hoặc on; thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_illiterate', 'en-c1-3', 'illiterate', '/ɪˈlɪtərət/', 'C1', 'mù chữ; không biết đọc biết viết; kém hiểu biết; thiếu kiến thức cơ bản trong một lĩnh vực cụ thể', 'adj.', 'illiteracy (n.), literate (adj.), literacy (n.)', 'Trái nghĩa: literate', 'Dùng danh từ chỉ người mù chữ có thể mang sắc thái miệt thị, nên dùng tính từ để mô tả khách quan.', 'Her grandfather was illiterate but told wonderful bedtime stories.', NULL, 'Ông của cô ấy không biết chữ nhưng lại kể những câu chuyện trước khi đi ngủ tuyệt hay.', '{"wordId":"illiterate","ukIpa":"/ɪˈlɪtərət/","usIpa":"/ɪˈlɪtərət/","cefr":"C1","topic":"education","senses":[{"pos":"adj.","en":"Unable to read or write.","vi":"mù chữ; không biết đọc biết viết"},{"pos":"adj.","en":"Lacking basic knowledge or skills in a particular area.","vi":"kém hiểu biết; thiếu kiến thức cơ bản trong một lĩnh vực cụ thể"}],"examples":[{"en":"Her grandfather was illiterate but told wonderful bedtime stories.","vi":"Ông của cô ấy không biết chữ nhưng lại kể những câu chuyện trước khi đi ngủ tuyệt hay.","audioKind":"ex"},{"en":"Free adult education can help illiterate citizens develop essential skills and participate more fully in society.","vi":"Chương trình giáo dục người lớn miễn phí có thể giúp những công dân mù chữ phát triển các kỹ năng thiết yếu và tham gia xã hội một cách trọn vẹn hơn.","audioKind":"ex2"}],"collocations":[{"en":"illiterate adults","vi":"người lớn mù chữ"},{"en":"computer illiterate","vi":"mù tin thức/mù máy tính"},{"en":"financially illiterate","vi":"thiếu kiến thức tài chính"}],"wordFamily":["illiteracy (n.)","literate (adj.)","literacy (n.)"],"synonyms":[],"antonyms":["literate"],"tipVi":"Dùng danh từ chỉ người mù chữ có thể mang sắc thái miệt thị, nên dùng tính từ để mô tả khách quan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_negation', 'en-c1-3', 'negation', '/nɪˈɡeɪʃən/', 'C1', 'sự phủ định; sự phủ nhận; cấu trúc phủ định; biểu thức phủ định', 'n.', 'negate (v.), negative (adj.), negatively (adv.)', 'Đồng nghĩa: denial · Trái nghĩa: affirmation', 'Mang tính trang trọng; trong ngữ pháp dùng để chỉ sự phủ định, còn đời thường nói từ chối hay khước từ thường dùng refusal.', 'His firm headshake was a clear negation of my suggestion.', NULL, 'Cái lắc đầu quả quyết của anh ấy là lời từ chối rõ ràng cho đề xuất của tôi.', '{"wordId":"negation","ukIpa":"/nɪˈɡeɪʃən/","usIpa":"/nɪˈɡeɪʃən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"the act of denying something or stating its opposite","vi":"sự phủ định; sự phủ nhận"},{"pos":"n.","en":"the grammatical expression that something is not true or present","vi":"cấu trúc phủ định; biểu thức phủ định"}],"examples":[{"en":"His firm headshake was a clear negation of my suggestion.","vi":"Cái lắc đầu quả quyết của anh ấy là lời từ chối rõ ràng cho đề xuất của tôi.","audioKind":"ex"},{"en":"In language teaching, understanding negation helps learners distinguish between statements that affirm facts and those that deny them.","vi":"Trong giảng dạy ngôn ngữ, việc hiểu rõ các cấu trúc phủ định giúp người học phân biệt giữa câu khẳng định sự thật và câu phủ nhận sự thật đó.","audioKind":"ex2"}],"collocations":[{"en":"complete negation","vi":"sự phủ định hoàn toàn"},{"en":"negation of a claim","vi":"sự phủ nhận một tuyên bố"},{"en":"double negation","vi":"phủ định kép"}],"wordFamily":["negate (v.)","negative (adj.)","negatively (adv.)"],"synonyms":["denial"],"antonyms":["affirmation"],"tipVi":"Mang tính trang trọng; trong ngữ pháp dùng để chỉ sự phủ định, còn đời thường nói từ chối hay khước từ thường dùng refusal.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proficiency', 'en-c1-3', 'proficiency', '/prəˈfɪʃənsi/', 'C1', 'sự thành thạo; trình độ thành thạo', 'n.', 'proficient (adj.), proficiently (adv.)', 'Đồng nghĩa: competence, skill · Trái nghĩa: incompetence', 'Thường dùng cấu trúc proficiency in đi kèm với ngôn ngữ, môn học hoặc kỹ năng.', 'Her proficiency in French helped us order dinner easily.', NULL, 'Khả năng tiếng Pháp trôi chảy của cô ấy đã giúp chúng tôi gọi bữa tối một cách dễ dàng.', '{"wordId":"proficiency","ukIpa":"/prəˈfɪʃənsi/","usIpa":"/prəˈfɪʃənsi/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"A high level of skill or ability in something.","vi":"sự thành thạo; trình độ thành thạo"}],"examples":[{"en":"Her proficiency in French helped us order dinner easily.","vi":"Khả năng tiếng Pháp trôi chảy của cô ấy đã giúp chúng tôi gọi bữa tối một cách dễ dàng.","audioKind":"ex"},{"en":"Universities often require evidence of English proficiency to ensure students can participate fully in academic discussions.","vi":"Các trường đại học thường yêu cầu chứng chỉ năng lực tiếng Anh để đảm bảo sinh viên có thể tham gia đầy đủ vào các buổi thảo luận học thuật.","audioKind":"ex2"}],"collocations":[{"en":"proficiency in English","vi":"trình độ tiếng Anh"},{"en":"language proficiency","vi":"năng lực ngôn ngữ"},{"en":"proficiency test","vi":"bài kiểm tra năng lực"},{"en":"demonstrate proficiency","vi":"thể hiện sự thành thạo"}],"wordFamily":["proficient (adj.)","proficiently (adv.)"],"synonyms":["competence","skill"],"antonyms":["incompetence"],"tipVi":"Thường dùng cấu trúc proficiency in đi kèm với ngôn ngữ, môn học hoặc kỹ năng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dissertation', 'en-c1-3', 'dissertation', '/ˌdɪsɚˈteɪʃən/', 'C1', 'luận văn; luận án', 'n.', NULL, 'Đồng nghĩa: thesis', 'Chủ đề của bài viết thường được đi kèm với giới từ on; ở Mỹ thường ám chỉ luận án tiến sĩ, trong khi ở Anh phạm vi áp dụng rộng hơn cho nhiều bậc học.', 'My sister is writing her dissertation at the library.', NULL, 'Chị tôi đang viết luận văn tốt nghiệp tại thư viện.', '{"wordId":"dissertation","ukIpa":"/ˌdɪsəˈteɪʃən/","usIpa":"/ˌdɪsɚˈteɪʃən/","cefr":"C1","topic":"education","senses":[{"pos":"n.","en":"A long research paper written as part of a university degree","vi":"luận văn; luận án"}],"examples":[{"en":"My sister is writing her dissertation at the library.","vi":"Chị tôi đang viết luận văn tốt nghiệp tại thư viện.","audioKind":"ex"},{"en":"Writing a dissertation requires students to evaluate existing research and develop a clear argument supported by evidence.","vi":"Việc viết luận văn đòi hỏi sinh viên phải đánh giá các nghiên cứu hiện có và đưa ra một lập luận rõ ràng có dẫn chứng chứng minh.","audioKind":"ex2"}],"collocations":[{"en":"write a dissertation","vi":"viết luận văn"},{"en":"submit a dissertation","vi":"nộp luận văn"},{"en":"a doctoral dissertation","vi":"luận án tiến sĩ"},{"en":"a dissertation on education","vi":"luận văn về ngành giáo dục"}],"wordFamily":[],"synonyms":["thesis"],"antonyms":[],"tipVi":"Chủ đề của bài viết thường được đi kèm với giới từ on; ở Mỹ thường ám chỉ luận án tiến sĩ, trong khi ở Anh phạm vi áp dụng rộng hơn cho nhiều bậc học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_3_1', 'en-c1-3', 'Cách dùng “dissertation” (n.) — luận văn; luận án', 'write a dissertation  ·  submit a dissertation  ·  a doctoral dissertation', 'Chủ đề của bài viết thường được đi kèm với giới từ on; ở Mỹ thường ám chỉ luận án tiến sĩ, trong khi ở Anh phạm vi áp dụng rộng hơn cho nhiều bậc học.', 'Đồng nghĩa: thesis', '[{"hanzi":"My sister is writing her dissertation at the library.","pinyin":"","meaning":"Chị tôi đang viết luận văn tốt nghiệp tại thư viện."},{"hanzi":"Writing a dissertation requires students to evaluate existing research and develop a clear argument supported by evidence.","pinyin":"","meaning":"Việc viết luận văn đòi hỏi sinh viên phải đánh giá các nghiên cứu hiện có và đưa ra một lập luận rõ ràng có dẫn chứng chứng minh."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_3_2', 'en-c1-3', 'Cách dùng “studious” (adj.) — chăm chỉ học hành; hiếu học', 'a studious pupil  ·  studious attention  ·  studious avoidance', 'Khi dùng để chỉ con người, từ này có nghĩa là chăm học; cụm từ studious avoidance có nghĩa là sự cố ý hoặc chủ động tránh né điều gì đó.', 'Họ từ (Word Family): study (v.), study (n.), studiously (adv.), studiousness (n.) | Đồng nghĩa: diligent, scholarly', '[{"hanzi":"My studious roommate spends most evenings in the library.","pinyin":"","meaning":"Bạn cùng phòng chăm chỉ của tôi dành phần lớn các buổi tối ở trong thư viện."},{"hanzi":"Studious pupils benefit from quiet learning environments, but they also need opportunities for physical activity.","pinyin":"","meaning":"Những học sinh chăm chỉ học tập được hưởng lợi từ môi trường học tập yên tĩnh, nhưng các em cũng cần có cơ hội tham gia các hoạt động thể chất."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_3_3', 'en-c1-3', 'Cách dùng “above-mentioned” (adj.) — đã nêu trên; nhắc đến ở trên', 'above-mentioned documents  ·  above-mentioned measures  ·  above-mentioned factors', 'Đây là văn phong trang trọng chuyên dùng trong văn bản viết, thường đứng trước danh từ; cần tránh lạm dụng trong văn viết hàng ngày.', 'Họ từ (Word Family): mention (v.) | Đồng nghĩa: aforementioned', '[{"hanzi":"Please bring the above-mentioned documents to our next meeting.","pinyin":"","meaning":"Vui lòng mang các tài liệu đã nêu trên đến cuộc họp tiếp theo của chúng ta."},{"hanzi":"The above-mentioned measures could reduce urban air pollution if local authorities provide sufficient funding and oversight.","pinyin":"","meaning":"Các biện pháp vừa nêu trên có thể giúp giảm ô nhiễm không khí đô thị nếu chính quyền địa phương cung cấp đủ nguồn vốn và công tác giám sát."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_3_4', 'en-c1-3', 'Cách dùng “negation” (n.) — sự phủ định; sự phủ nhận', 'complete negation  ·  negation of a claim  ·  double negation', 'Mang tính trang trọng; trong ngữ pháp dùng để chỉ sự phủ định, còn đời thường nói từ chối hay khước từ thường dùng refusal.', 'Họ từ (Word Family): negate (v.), negative (adj.), negatively (adv.) | Đồng nghĩa: denial · Trái nghĩa: affirmation', '[{"hanzi":"His firm headshake was a clear negation of my suggestion.","pinyin":"","meaning":"Cái lắc đầu quả quyết của anh ấy là lời từ chối rõ ràng cho đề xuất của tôi."},{"hanzi":"In language teaching, understanding negation helps learners distinguish between statements that affirm facts and those that deny them.","pinyin":"","meaning":"Trong giảng dạy ngôn ngữ, việc hiểu rõ các cấu trúc phủ định giúp người học phân biệt giữa câu khẳng định sự thật và câu phủ nhận sự thật đó."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_3_1', 'en-c1-3', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_1_1', 'ten_c1_3_1', 'phonetics', 'We studied phonetics to understand how speech sounds are produced.', 'We studied phonetics to understand how speech sounds are produced.', '/fəˈnetɪks/', 'Chúng tôi đã học môn ngữ âm học để hiểu cách các âm thanh lời nói được tạo ra.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_1_2', 'ten_c1_3_1', 'anthropology', 'My cousin studies anthropology and collects stories about family traditions.', 'My cousin studies anthropology and collects stories about family traditions.', '/ˌænθrəˈpɑːlədʒi/', 'Anh họ của tôi học ngành nhân học và sưu tầm những câu chuyện về truyền thống gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_1_3', 'ten_c1_3_1', 'elaboration', 'Your plan sounds promising but needs a little elaboration.', 'Your plan sounds promising but needs a little elaboration.', '/ɪˌlæbəˈreɪʃən/', 'Kế hoạch của bạn nghe rất khả quan nhưng vẫn cần thêm một chút chi tiết.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_1_4', 'ten_c1_3_1', 'layman', 'The mechanic explained the problem in layman''s terms.', 'The mechanic explained the problem in layman''s terms.', '/ˈleɪmən/', 'Thợ máy đã giải thích sự cố bằng những thuật ngữ thông dụng mà người ngoài ngành cũng hiểu được.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_1_5', 'ten_c1_3_1', 'endow', 'Her family endowed a scholarship at the local college.', 'Her family endowed a scholarship at the local college.', '/ɪnˈdaʊ/', 'Gia đình cô ấy đã tài trợ thành lập một học bổng tại trường cao đẳng địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_1_6', 'ten_c1_3_1', 'immerse', 'On rainy afternoons, I immerse myself in a novel.', 'On rainy afternoons, I immerse myself in a novel.', '/ɪˈmɝːs/', 'Vào những buổi chiều mưa, tôi thường đắm mình trong những trang tiểu thuyết.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_1_7', 'ten_c1_3_1', 'numerate', 'The shop needs numerate staff who can calculate change.', 'The shop needs numerate staff who can calculate change.', '/ˈnuːmərət/', 'Cửa hàng cần nhân viên có khả năng tính toán tốt để tính tiền thối lại.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_1_8', 'ten_c1_3_1', 'synopsis', 'I read the synopsis before borrowing the novel.', 'I read the synopsis before borrowing the novel.', '/sɪˈnɑːpsɪs/', 'Tôi đã đọc phần tóm tắt cốt truyện trước khi mượn cuốn tiểu thuyết đó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_3_1_1', 'en-c1-3', 'ten_c1_3_1', 'listening', 'listening', 'We studied phonetics to understand how speech sounds are produced.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ông của cô ấy không biết chữ nhưng lại kể những câu chuyện trước khi đi ngủ tuyệt hay.","Thợ máy đã giải thích sự cố bằng những thuật ngữ thông dụng mà người ngoài ngành cũng hiểu được.","Tôi đã đọc phần tóm tắt cốt truyện trước khi mượn cuốn tiểu thuyết đó.","Chúng tôi đã học môn ngữ âm học để hiểu cách các âm thanh lời nói được tạo ra."]'::jsonb, 3, 'We studied phonetics to understand how speech sounds are produced. → Chúng tôi đã học môn ngữ âm học để hiểu cách các âm thanh lời nói được tạo ra.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_3_1_2', 'en-c1-3', 'ten_c1_3_1', 'listening', 'listening', 'My cousin studies anthropology and collects stories about family traditions.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh họ của tôi học ngành nhân học và sưu tầm những câu chuyện về truyền thống gia đình.","Gia đình cô ấy đã tài trợ thành lập một học bổng tại trường cao đẳng địa phương.","Nhân viên đăng ký đã kiểm tra giấy tờ của chúng tôi trước lễ cưới.","Bài giảng của cô ấy đã khuyến khích cuộc thảo luận sâu sắc về lịch sử địa phương."]'::jsonb, 0, 'My cousin studies anthropology and collects stories about family traditions. → Anh họ của tôi học ngành nhân học và sưu tầm những câu chuyện về truyền thống gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_3_1_3', 'en-c1-3', 'ten_c1_3_1', 'listening', 'listening', 'Your plan sounds promising but needs a little elaboration.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhân viên đăng ký đã kiểm tra giấy tờ của chúng tôi trước lễ cưới.","Anh họ của tôi học ngành nhân học và sưu tầm những câu chuyện về truyền thống gia đình.","Giáo viên của chúng tôi đã giải thích nguồn gốc của từ lạ này.","Kế hoạch của bạn nghe rất khả quan nhưng vẫn cần thêm một chút chi tiết."]'::jsonb, 3, 'Your plan sounds promising but needs a little elaboration. → Kế hoạch của bạn nghe rất khả quan nhưng vẫn cần thêm một chút chi tiết.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_3_2', 'en-c1-3', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_2_1', 'ten_c1_3_2', 'phonetics', 'Training in phonetics can help language teachers explain pronunciation differences that learners may struggle to hear.', 'Training in phonetics can help language teachers explain pronunciation differences that learners may struggle to hear.', '/fəˈnetɪks/', 'Việc đào tạo về ngữ âm học có thể giúp giáo viên ngôn ngữ giải thích những khác biệt về phát âm mà người học có thể gặp khó khăn khi nghe.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_2_2', 'ten_c1_3_2', 'anthropology', 'Anthropology helps researchers understand how cultural traditions influence attitudes towards health, education, and family life.', 'Anthropology helps researchers understand how cultural traditions influence attitudes towards health, education, and family life.', '/ˌænθrəˈpɑːlədʒi/', 'Nhân học giúp các nhà nghiên cứu hiểu được các truyền thống văn hóa chi phối thái độ đối với sức khỏe, giáo dục và đời sống gia đình như thế nào.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_2_3', 'ten_c1_3_2', 'elaboration', 'Further elaboration on the proposed transport policy would help residents understand how their daily journeys might change.', 'Further elaboration on the proposed transport policy would help residents understand how their daily journeys might change.', '/ɪˌlæbəˈreɪʃən/', 'Việc giải thích chi tiết hơn về chính sách giao thông được đề xuất sẽ giúp người dân hiểu rõ những thay đổi có thể diễn ra trong việc đi lại hàng ngày của họ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_2_4', 'ten_c1_3_2', 'layman', 'Scientific reports should include summaries that a layman can understand without specialist training.', 'Scientific reports should include summaries that a layman can understand without specialist training.', '/ˈleɪmən/', 'Các báo cáo khoa học nên có phần tóm tắt mà một người không chuyên cũng có thể hiểu được mà không cần qua đào tạo chuyên sâu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_2_5', 'ten_c1_3_2', 'endow', 'Private donations can endow research centres that investigate long-term solutions to urgent public health problems.', 'Private donations can endow research centres that investigate long-term solutions to urgent public health problems.', '/ɪnˈdaʊ/', 'Các khoản đóng góp tư nhân có thể tài trợ cho các trung tâm nghiên cứu nhằm tìm kiếm giải pháp dài hạn cho các vấn đề y tế công cộng cấp bách.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_3_2_6', 'ten_c1_3_2', 'immerse', 'Exchange programmes allow students to immerse themselves in another culture and develop greater independence.', 'Exchange programmes allow students to immerse themselves in another culture and develop greater independence.', '/ɪˈmɝːs/', 'Các chương trình trao đổi giúp sinh viên đắm mình vào một nền văn hóa khác và phát triển tính tự lập cao hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
