INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_1', 'en-c1-3', NULL, 'comprehensive_test', 'listening', 'phonetics', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự thanh tịnh; sự bình yên; sự thanh thản","có thể qua lại được; tàu bè qua lại được","sự trấn áp; sự đàn áp","ngữ âm học"]'::jsonb, 3, 'phonetics (/fəˈnetɪks/) → ngữ âm học', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_2', 'en-c1-3', NULL, 'comprehensive_test', 'listening', 'My cousin studies anthropology and collects stories about family traditions.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh họ của tôi học ngành nhân học và sưu tầm những câu chuyện về truyền thống gia đình.","Tôi vừa đọc bản ghi chép vừa lắng nghe đoạn phỏng vấn.","Chị tôi đang viết luận văn tốt nghiệp tại thư viện.","Ông của cô ấy không biết chữ nhưng lại kể những câu chuyện trước khi đi ngủ tuyệt hay."]'::jsonb, 0, 'My cousin studies anthropology and collects stories about family traditions. → Anh họ của tôi học ngành nhân học và sưu tầm những câu chuyện về truyền thống gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_3', 'en-c1-3', NULL, 'comprehensive_test', 'listening', 'elaboration', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sắp tới; sắp diễn ra","sự giải thích chi tiết; sự bổ sung chi tiết","cồng kềnh; to lớn vướng víu","thuộc về trạng ngữ; có chức năng như trạng ngữ"]'::jsonb, 1, 'elaboration (/ɪˌlæbəˈreɪʃən/) → sự giải thích chi tiết; sự bổ sung chi tiết', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_4', 'en-c1-3', NULL, 'comprehensive_test', 'listening', 'The mechanic explained the problem in layman''s terms.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Kế hoạch của bạn nghe rất khả quan nhưng vẫn cần thêm một chút chi tiết.","Chị tôi đang viết luận văn tốt nghiệp tại thư viện.","Bạn cùng phòng chăm chỉ của tôi dành phần lớn các buổi tối ở trong thư viện.","Thợ máy đã giải thích sự cố bằng những thuật ngữ thông dụng mà người ngoài ngành cũng hiểu được."]'::jsonb, 3, 'The mechanic explained the problem in layman''s terms. → Thợ máy đã giải thích sự cố bằng những thuật ngữ thông dụng mà người ngoài ngành cũng hiểu được.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_5', 'en-c1-3', NULL, 'comprehensive_test', 'listening', 'endow', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quyên góp tiền lập quỹ; tài trợ lâu dài cho một tổ chức","vô hại; không có hại; không xúc phạm ai","ca sĩ; giọng ca chính","theo thứ tự thời gian"]'::jsonb, 0, 'endow (/ɪnˈdaʊ/) → quyên góp tiền lập quỹ; tài trợ lâu dài cho một tổ chức; trời phú cho; ban cho ai đó phẩm chất hoặc năng lực đặc biệt', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_6', 'en-c1-3', NULL, 'comprehensive_test', 'listening', 'On rainy afternoons, I immerse myself in a novel.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giáo viên của chúng tôi đã giải thích nguồn gốc của từ lạ này.","Vào những buổi chiều mưa, tôi thường đắm mình trong những trang tiểu thuyết.","Những cuộc trò chuyện hàng ngày đã giúp cô ấy tiếp thu vốn từ vựng mới.","Kế hoạch của bạn nghe rất khả quan nhưng vẫn cần thêm một chút chi tiết."]'::jsonb, 1, 'On rainy afternoons, I immerse myself in a novel. → Vào những buổi chiều mưa, tôi thường đắm mình trong những trang tiểu thuyết.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_7', 'en-c1-3', NULL, 'comprehensive_test', 'listening', 'numerate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự thu được; sự tiếp thu; quá trình học được","điều trớ trêu; nghịch lý","có khả năng tính toán; giỏi tính toán","sự tưới tiêu; hệ thống tưới tiêu"]'::jsonb, 2, 'numerate (/ˈnuːmərət/) → có khả năng tính toán; giỏi tính toán', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_8', 'en-c1-3', NULL, 'comprehensive_test', 'listening', 'I read the synopsis before borrowing the novel.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã đọc phần tóm tắt cốt truyện trước khi mượn cuốn tiểu thuyết đó.","Bài giảng của cô ấy đã khuyến khích cuộc thảo luận sâu sắc về lịch sử địa phương.","Chúng tôi nghe tiếng còi cất lên ngay khi trận đấu bắt đầu.","Cửa hàng cần nhân viên có khả năng tính toán tốt để tính tiền thối lại."]'::jsonb, 0, 'I read the synopsis before borrowing the novel. → Tôi đã đọc phần tóm tắt cốt truyện trước khi mượn cuốn tiểu thuyết đó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
