INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_18', 'en-c1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Training in phonetics can help language teachers explain pronunciation differences that learners may struggle to hear.', 'Dựa vào câu trên, từ “phonetics” có nghĩa phù hợp nhất là gì?', '["ngữ âm học","hàn (nối các chi tiết kim loại bằng cách nung nóng cho đến khi chúng chảy dính vào nhau)","vô ích; không thành công","thực tế; thực dụng; chú trọng hiệu quả thực tế"]'::jsonb, 0, 'phonetics: ngữ âm học. Dịch cả câu: Việc đào tạo về ngữ âm học có thể giúp giáo viên ngôn ngữ giải thích những khác biệt về phát âm mà người học có thể gặp khó khăn khi nghe.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_19', 'en-c1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Anthropology helps researchers understand how cultural traditions influence attitudes towards health, education, and family life.', 'Dựa vào câu trên, từ “anthropology” có nghĩa phù hợp nhất là gì?', '["nhân học","xấu hổ; bẽn lẽn; ngượng ngùng do làm sai hoặc lỡ vụng về","sự cải tiến; sự tinh chỉnh nhỏ để hoàn thiện hơn","sự dối trá; hành vi lừa gạt"]'::jsonb, 0, 'anthropology: nhân học. Dịch cả câu: Nhân học giúp các nhà nghiên cứu hiểu được các truyền thống văn hóa chi phối thái độ đối với sức khỏe, giáo dục và đời sống gia đình như thế nào.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_20', 'en-c1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Further elaboration on the proposed transport policy would help residents understand how their daily journeys might change.', 'Dựa vào câu trên, từ “elaboration” có nghĩa phù hợp nhất là gì?', '["gây nguy hiểm; làm tổn hại","chói lọi; chói mắt","uy tín; danh vọng; tiếng tăm","sự giải thích chi tiết; sự bổ sung chi tiết"]'::jsonb, 3, 'elaboration: sự giải thích chi tiết; sự bổ sung chi tiết. Dịch cả câu: Việc giải thích chi tiết hơn về chính sách giao thông được đề xuất sẽ giúp người dân hiểu rõ những thay đổi có thể diễn ra trong việc đi lại hàng ngày của họ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_21', 'en-c1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Scientific reports should include summaries that a layman can understand without specialist training.', 'Dựa vào câu trên, từ “layman” có nghĩa phù hợp nhất là gì?', '["người ngoại đạo; người không chuyên môn","mức tiêu chuẩn; mức bình thường","niềm hoài niệm, sự nhớ tiếc quá khứ","sự tưới tiêu; hệ thống tưới tiêu"]'::jsonb, 0, 'layman: người ngoại đạo; người không chuyên môn; giáo dân (thành viên nam giới trong giáo hội không phải linh mục). Dịch cả câu: Các báo cáo khoa học nên có phần tóm tắt mà một người không chuyên cũng có thể hiểu được mà không cần qua đào tạo chuyên sâu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_22', 'en-c1-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự phủ định; sự phủ nhận”', '["relish","potluck","negation","resignation"]'::jsonb, 2, 'sự phủ định; sự phủ nhận → negation (/nɪˈɡeɪʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_23', 'en-c1-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự thành thạo; trình độ thành thạo”', '["literate","oscillate","proficiency","appraisal"]'::jsonb, 2, 'sự thành thạo; trình độ thành thạo → proficiency (/prəˈfɪʃənsi/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_3_24', 'en-c1-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “luận văn; luận án”', '["allude","delinquent","dissertation","manor"]'::jsonb, 2, 'luận văn; luận án → dissertation (/ˌdɪsɚˈteɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-4', 'en', 'Bài 4: Du lịch & Di chuyển (1) - CEFR C1', 'CEFR C1', 'C1 · Du lịch', '15 từ vựng Tiếng Anh CEFR C1 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5004, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hull', 'en-c1-4', 'hull', '/hʌl/', 'C1', 'thân tàu (phần vỏ chính bên ngoài của tàu thuyền); vỏ (lớp vỏ ngoài của hạt hoặc quả); bóc vỏ; cắt cuống (loại bỏ lớp vỏ ngoài hoặc phần cuống lá của thực phẩm)', 'n.', NULL, NULL, 'Thân tàu là hull; toàn bộ con tàu dùng ship hoặc boat.', 'We painted the boat''s hull blue before launching it.', NULL, 'Chúng tôi đã sơn phần thân tàu thành màu xanh trước khi hạ thủy.', '{"wordId":"hull","ukIpa":"/hʌl/","usIpa":"/hʌl/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"The main outer body of a ship or boat.","vi":"thân tàu (phần vỏ chính bên ngoài của tàu thuyền)"},{"pos":"n.","en":"The outer covering of a seed or fruit.","vi":"vỏ (lớp vỏ ngoài của hạt hoặc quả)"},{"pos":"v.","en":"To remove the outer covering or leafy top of food.","vi":"bóc vỏ; cắt cuống (loại bỏ lớp vỏ ngoài hoặc phần cuống lá của thực phẩm)"}],"examples":[{"en":"We painted the boat''s hull blue before launching it.","vi":"Chúng tôi đã sơn phần thân tàu thành màu xanh trước khi hạ thủy.","audioKind":"ex"},{"en":"Improved hull designs can reduce fuel consumption by allowing ships to move through water with less resistance.","vi":"Thiết kế thân tàu được cải tiến có thể làm giảm mức tiêu thụ nhiên liệu bằng cách cho phép tàu di chuyển qua nước với ít lực cản hơn.","audioKind":"ex2"}],"collocations":[{"en":"a ship''s hull","vi":"thân tàu"},{"en":"a steel hull","vi":"thân tàu bằng thép"},{"en":"rice hulls","vi":"vỏ trấu"},{"en":"hull strawberries","vi":"cắt cuống dâu tây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thân tàu là hull; toàn bộ con tàu dùng ship hoặc boat.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_laden', 'en-c1-4', 'laden', '/ˈleɪdn/', 'C1', 'chất đầy; mang nặng; trĩu; chứa đầy cảm xúc (đặc biệt là cảm xúc tiêu cực)', 'adj.', 'lade (v.), unladen (adj.)', 'Đồng nghĩa: loaded, burdened · Trái nghĩa: unladen', 'Thường đi kèm với từ laden with; cũng có thể tạo thành tính từ ghép như sugar-laden.', 'She arrived at the picnic laden with bags of food.', NULL, 'Cô ấy đến buổi dã ngoại với những túi đồ ăn trĩu nặng trên tay.', '{"wordId":"laden","ukIpa":"/ˈleɪdn/","usIpa":"/ˈleɪdn/","cefr":"C1","topic":"travel","senses":[{"pos":"adj.","en":"Carrying or holding a large amount of something.","vi":"chất đầy; mang nặng; trĩu"},{"pos":"adj.","en":"Full of a particular feeling, especially an unpleasant one.","vi":"chứa đầy cảm xúc (đặc biệt là cảm xúc tiêu cực)"}],"examples":[{"en":"She arrived at the picnic laden with bags of food.","vi":"Cô ấy đến buổi dã ngoại với những túi đồ ăn trĩu nặng trên tay.","audioKind":"ex"},{"en":"Trucks laden with construction materials contribute to congestion and increase road maintenance costs in rapidly expanding cities.","vi":"Những chiếc xe tải chở đầy vật liệu xây dựng làm gia tăng tình trạng ùn tắc và làm tăng chi phí bảo trì đường bộ ở các thành phố đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"laden with","vi":"chất đầy; mang nặng"},{"en":"heavily laden","vi":"chất đầy nặng nề"},{"en":"a laden truck","vi":"chiếc xe tải chở nặng"}],"wordFamily":["lade (v.)","unladen (adj.)"],"synonyms":["loaded","burdened"],"antonyms":["unladen"],"tipVi":"Thường đi kèm với từ laden with; cũng có thể tạo thành tính từ ghép như sugar-laden.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_orientate', 'en-c1-4', 'orientate', '/ˈɔːriənteɪt/', 'C1', 'xác định phương hướng; làm quen với môi trường xung quanh; làm cho hướng về; định hướng vào', 'v.', 'orient (v.), orientation (n.), disorientate (v.)', 'Đồng nghĩa: orient · Trái nghĩa: disorientate', 'Thường dùng trong tiếng Anh-Anh; phổ biến với cụm orientate oneself, không chỉ riêng hướng Đông.', 'I used the river to orientate myself in town.', NULL, 'Tôi đã dùng con sông để định hướng vị trí của mình trong thị trấn.', '{"wordId":"orientate","ukIpa":"/ˈɔːriənteɪt/","usIpa":"/ˈɔːriənteɪt/","cefr":"C1","topic":"travel","senses":[{"pos":"v.","en":"Find your position or become familiar with your surroundings.","vi":"xác định phương hướng; làm quen với môi trường xung quanh"},{"pos":"v.","en":"Position something towards a direction or focus it on something.","vi":"làm cho hướng về; định hướng vào"}],"examples":[{"en":"I used the river to orientate myself in town.","vi":"Tôi đã dùng con sông để định hướng vị trí của mình trong thị trấn.","audioKind":"ex"},{"en":"Universities should orientate their support services towards the needs of students adjusting to life away from home.","vi":"Các trường đại học nên định hướng các dịch vụ hỗ trợ của mình vào nhu cầu của sinh viên khi họ thích nghi với cuộc sống xa nhà.","audioKind":"ex2"}],"collocations":[{"en":"orientate yourself","vi":"xác định phương hướng của bản thân"},{"en":"orientate something towards","vi":"định hướng một cái gì đó vào"}],"wordFamily":["orient (v.)","orientation (n.)","disorientate (v.)"],"synonyms":["orient"],"antonyms":["disorientate"],"tipVi":"Thường dùng trong tiếng Anh-Anh; phổ biến với cụm orientate oneself, không chỉ riêng hướng Đông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transit', 'en-c1-4', 'transit', '/ˈtrænzɪt/', 'C1', 'sự vận chuyển; quá trình chuyên chở; hệ thống giao thông công cộng', 'n.', NULL, 'Đồng nghĩa: transportation', 'Cụm từ in transit mang nghĩa đang trên đường vận chuyển; từ public transit rất phổ biến trong tiếng Anh-Mỹ.', 'The glasses broke while they were in transit.', NULL, 'Những chiếc ly thủy tinh đã bị vỡ trong quá trình vận chuyển.', '{"wordId":"transit","ukIpa":"/ˈtrænzɪt/","usIpa":"/ˈtrænzɪt/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"the movement of people or goods between places","vi":"sự vận chuyển; quá trình chuyên chở"},{"pos":"n.","en":"a system of buses, trains, or other shared transport","vi":"hệ thống giao thông công cộng"}],"examples":[{"en":"The glasses broke while they were in transit.","vi":"Những chiếc ly thủy tinh đã bị vỡ trong quá trình vận chuyển.","audioKind":"ex"},{"en":"Investment in public transit can reduce traffic congestion and improve access to employment in growing cities.","vi":"Đầu tư vào hệ thống giao thông công cộng có thể làm giảm tình trạng ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm tại các thành phố đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"in transit","vi":"đang trên đường vận chuyển"},{"en":"public transit","vi":"giao thông công cộng"},{"en":"transit system","vi":"hệ thống trung chuyển"},{"en":"transit visa","vi":"thị thực quá cảnh"}],"wordFamily":[],"synonyms":["transportation"],"antonyms":[],"tipVi":"Cụm từ in transit mang nghĩa đang trên đường vận chuyển; từ public transit rất phổ biến trong tiếng Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_secluded', 'en-c1-4', 'secluded', '/sɪˈkluːdɪd/', 'C1', 'hẻo lánh; tách biệt; thanh vắng', 'adj.', 'seclude (v.), seclusion (n.)', 'Đồng nghĩa: isolated, hidden, private · Trái nghĩa: exposed', 'Thường mô tả địa điểm vắng vẻ, ẩn khuất, không đồng nghĩa với tính cách hướng nội của con người.', 'We found a secluded beach behind the cliffs.', NULL, 'Chúng tôi đã tìm thấy một bãi biển hoang sơ, vắng vẻ phía sau các vách đá.', '{"wordId":"secluded","ukIpa":"/sɪˈkluːdɪd/","usIpa":"/sɪˈkluːdɪd/","cefr":"C1","topic":"travel","senses":[{"pos":"adj.","en":"private and quiet, away from people and busy places","vi":"hẻo lánh; tách biệt; thanh vắng"}],"examples":[{"en":"We found a secluded beach behind the cliffs.","vi":"Chúng tôi đã tìm thấy một bãi biển hoang sơ, vắng vẻ phía sau các vách đá.","audioKind":"ex"},{"en":"Although secluded rural homes offer privacy, their residents may struggle to access healthcare and public transport.","vi":"Mặc dù những ngôi nhà ở vùng nông thôn hẻo lánh mang lại sự riêng tư, nhưng cư dân ở đó có thể gặp khó khăn trong việc tiếp cận dịch vụ y tế và giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"secluded beach","vi":"bãi biển vắng vẻ"},{"en":"secluded spot","vi":"địa điểm ẩn mình"},{"en":"secluded garden","vi":"Khu vườn u tịch"}],"wordFamily":["seclude (v.)","seclusion (n.)"],"synonyms":["isolated","hidden","private"],"antonyms":["exposed"],"tipVi":"Thường mô tả địa điểm vắng vẻ, ẩn khuất, không đồng nghĩa với tính cách hướng nội của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ply', 'en-c1-4', 'ply', '/plaɪ/', 'C1', 'chạy tuyến cố định; đi lại đều đặn; làm nghề; chuyên cần làm; lớp (vật liệu); sợi (chỉ)', 'v.', 'plywood (n.)', NULL, 'Cấu trúc ply someone with sth chỉ việc liên tục cung cấp hoặc ném thứ gì đó cho ai.', 'Small ferries ply between the island and the mainland.', NULL, 'Những chiếc phà nhỏ chạy tuyến đều đặn giữa hòn đảo và đất liền.', '{"wordId":"ply","ukIpa":"/plaɪ/","usIpa":"/plaɪ/","cefr":"C1","topic":"travel","senses":[{"pos":"v.","en":"To travel regularly along a route, especially by boat","vi":"chạy tuyến cố định; đi lại đều đặn"},{"pos":"v.","en":"To practise a trade or use a tool steadily","vi":"làm nghề; chuyên cần làm"},{"pos":"n.","en":"A single layer of material or strand of twisted yarn","vi":"lớp (vật liệu); sợi (chỉ)"}],"examples":[{"en":"Small ferries ply between the island and the mainland.","vi":"Những chiếc phà nhỏ chạy tuyến đều đặn giữa hòn đảo và đất liền.","audioKind":"ex"},{"en":"Buses that ply rural routes provide essential access to healthcare and education for isolated communities.","vi":"Xe buýt chạy định kỳ trên các tuyến đường nông thôn cung cấp quyền tiếp cận thiết yếu đối với dịch vụ y tế và giáo dục cho các cộng đồng bị cô lập.","audioKind":"ex2"}],"collocations":[{"en":"ply a route","vi":"chạy một tuyến đường cố định"},{"en":"ply one''s trade","vi":"làm nghề của mình"},{"en":"ply someone with questions","vi":"liên tục đặt câu hỏi cho ai đó"},{"en":"three-ply wood","vi":"ván ép ba lớp"}],"wordFamily":["plywood (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc ply someone with sth chỉ việc liên tục cung cấp hoặc ném thứ gì đó cho ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maiden', 'en-c1-4', 'maiden', '/ˈmeɪdən/', 'C1', 'đầu tiên; chuyến xuất phát đầu tiên; thiếu nữ; người con gái chưa chồng', 'adj.', NULL, NULL, 'Tính từ thường chỉ lần đầu tiên; khi dùng làm danh từ chỉ thiếu nữ thì mang phong cách văn chương hoặc cổ xưa.', 'The new ferry completed its maiden voyage this morning.', NULL, 'Chiếc phà mới đã hoàn thành chuyến hải trình đầu tiên vào sáng nay.', '{"wordId":"maiden","ukIpa":"/ˈmeɪdən/","usIpa":"/ˈmeɪdən/","cefr":"C1","topic":"travel","senses":[{"pos":"adj.","en":"being the first of its kind for someone or something","vi":"đầu tiên; chuyến xuất phát đầu tiên"},{"pos":"n.","en":"a young unmarried woman, especially in old stories","vi":"thiếu nữ; người con gái chưa chồng"}],"examples":[{"en":"The new ferry completed its maiden voyage this morning.","vi":"Chiếc phà mới đã hoàn thành chuyến hải trình đầu tiên vào sáng nay.","audioKind":"ex"},{"en":"The aircraft''s maiden flight marked an important step towards developing cleaner forms of regional transport.","vi":"Chuyến bay đầu tiên của chiếc máy bay này đánh dấu một bước tiến quan trọng trong việc phát triển các phương tiện giao thông khu vực thân thiện với môi trường hơn.","audioKind":"ex2"}],"collocations":[{"en":"maiden voyage","vi":"chuyến hải trình đầu tiên"},{"en":"maiden flight","vi":"chuyến bay đầu tiên"},{"en":"maiden speech","vi":"bài phát biểu đầu tiên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tính từ thường chỉ lần đầu tiên; khi dùng làm danh từ chỉ thiếu nữ thì mang phong cách văn chương hoặc cổ xưa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wharf', 'en-c1-4', 'wharf', '/wɔːrf/', 'C1', 'cầu cảng; bến tàu', 'n.', NULL, NULL, 'Dạng số nhiều có thể là wharves hoặc wharfs.', 'We watched fishermen unload their catch at the wharf.', NULL, 'Chúng tôi đứng xem ngư dân dỡ cá vừa đánh bắt được ở cầu cảng.', '{"wordId":"wharf","ukIpa":"/wɔːf/","usIpa":"/wɔːrf/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"A structure beside water where boats load and unload.","vi":"cầu cảng; bến tàu"}],"examples":[{"en":"We watched fishermen unload their catch at the wharf.","vi":"Chúng tôi đứng xem ngư dân dỡ cá vừa đánh bắt được ở cầu cảng.","audioKind":"ex"},{"en":"The old wharf has been converted into a public space, attracting visitors and supporting local businesses.","vi":"Cầu cảng cũ đã được cải tạo thành không gian công cộng, thu hút du khách và hỗ trợ các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"at the wharf","vi":"tại cầu cảng"},{"en":"a fishing wharf","vi":"cảng cá"},{"en":"moor at a wharf","vi":"neo đậu tại cầu cảng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều có thể là wharves hoặc wharfs.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stationary', 'en-c1-4', 'stationary', '/ˈsteɪʃəneri/', 'C1', 'đứng yên; tĩnh tại; không di chuyển', 'adj.', NULL, 'Đồng nghĩa: motionless, immobile · Trái nghĩa: moving', 'stationary chỉ sự đứng yên; còn stationery chỉ văn phòng phẩm, hai từ này phát âm giống nhau.', 'Our bus remained stationary while passengers climbed aboard.', NULL, 'Xe buýt của chúng tôi vẫn đứng yên trong lúc hành khách bước lên xe.', '{"wordId":"stationary","ukIpa":"/ˈsteɪʃənəri/","usIpa":"/ˈsteɪʃəneri/","cefr":"C1","topic":"travel","senses":[{"pos":"adj.","en":"Not moving or changing position.","vi":"đứng yên; tĩnh tại; không di chuyển"}],"examples":[{"en":"Our bus remained stationary while passengers climbed aboard.","vi":"Xe buýt của chúng tôi vẫn đứng yên trong lúc hành khách bước lên xe.","audioKind":"ex"},{"en":"Stationary vehicles with running engines contribute to urban air pollution without providing any transport benefit.","vi":"Những phương tiện đậu đỗ nhưng vẫn nổ máy góp phần gây ô nhiễm không khí đô thị mà chẳng mang lại lợi ích giao thông nào.","audioKind":"ex2"}],"collocations":[{"en":"remain stationary","vi":"giữ nguyên vị trí"},{"en":"a stationary vehicle","vi":"phương tiện đang dừng"},{"en":"a stationary bike","vi":"xe đạp tập thể dục"}],"wordFamily":[],"synonyms":["motionless","immobile"],"antonyms":["moving"],"tipVi":"stationary chỉ sự đứng yên; còn stationery chỉ văn phòng phẩm, hai từ này phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snowbound', 'en-c1-4', 'snowbound', '/ˈsnoʊbaʊnd/', 'C1', 'bị tuyết vây kín; bị tuyết cô lập', 'adj.', 'snow (n.), snowy (adj.), snowfall (n.)', NULL, 'Nhấn mạnh việc tuyết cản trở việc di chuyển, không chỉ đơn thuần là phủ đầy tuyết.', 'We stayed in a snowbound cabin for three days.', NULL, 'Chúng tôi ở lại trong một căn nhà gỗ bị tuyết vây kín suốt ba ngày.', '{"wordId":"snowbound","ukIpa":"/ˈsnəʊbaʊnd/","usIpa":"/ˈsnoʊbaʊnd/","cefr":"C1","topic":"travel","senses":[{"pos":"adj.","en":"Unable to travel or be reached because of heavy snow.","vi":"bị tuyết vây kín; bị tuyết cô lập"}],"examples":[{"en":"We stayed in a snowbound cabin for three days.","vi":"Chúng tôi ở lại trong một căn nhà gỗ bị tuyết vây kín suốt ba ngày.","audioKind":"ex"},{"en":"Emergency services delivered food and medicine to snowbound villages after unusually heavy winter storms.","vi":"Các cơ quan cứu hộ đã cung cấp thực phẩm và thuốc men cho các ngôi làng bị tuyết cô lập sau những trận bão mùa đông dữ dội bất thường.","audioKind":"ex2"}],"collocations":[{"en":"a snowbound village","vi":"ngôi làng bị tuyết vây kín"},{"en":"snowbound travellers","vi":"những lữ khách bị tuyết cô lập"},{"en":"remain snowbound","vi":"vẫn bị tuyết vây kín"}],"wordFamily":["snow (n.)","snowy (adj.)","snowfall (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh việc tuyết cản trở việc di chuyển, không chỉ đơn thuần là phủ đầy tuyết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_locomotive', 'en-c1-4', 'locomotive', '/ˌloʊkəˈmoʊtɪv/', 'C1', 'đầu máy xe lửa', 'n.', 'locomotion (n.)', 'Đồng nghĩa: railway engine', 'Chỉ phần đầu máy cung cấp lực kéo, không phải toàn bộ đoàn tàu gồm cả các toa.', 'A steam locomotive pulled the carriages slowly past our platform.', NULL, 'Một đầu máy xe lửa hơi nước đã kéo các toa tàu từ từ lướt qua sân ga của chúng tôi.', '{"wordId":"locomotive","ukIpa":"/ˌləʊkəˈməʊtɪv/","usIpa":"/ˌloʊkəˈmoʊtɪv/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"A railway engine that pulls or pushes a train.","vi":"đầu máy xe lửa"}],"examples":[{"en":"A steam locomotive pulled the carriages slowly past our platform.","vi":"Một đầu máy xe lửa hơi nước đã kéo các toa tàu từ từ lướt qua sân ga của chúng tôi.","audioKind":"ex"},{"en":"Replacing diesel locomotives with electric models can reduce local air pollution, especially along busy urban railway routes.","vi":"Việc thay thế đầu máy diesel bằng đầu máy điện có thể làm giảm ô nhiễm không khí tại địa phương, đặc biệt là dọc theo các tuyến đường sắt đô thị bận rộn.","audioKind":"ex2"}],"collocations":[{"en":"a steam locomotive","vi":"đầu máy hơi nước"},{"en":"a diesel locomotive","vi":"đầu máy diesel"},{"en":"an electric locomotive","vi":"đầu máy điện"}],"wordFamily":["locomotion (n.)"],"synonyms":["railway engine"],"antonyms":[],"tipVi":"Chỉ phần đầu máy cung cấp lực kéo, không phải toàn bộ đoàn tàu gồm cả các toa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cruiser', 'en-c1-4', 'cruiser', '/ˈkruːzər/', 'C1', 'du thuyền có khoang ngủ; tuần dương hạm; xe cảnh sát tuần tra (tiếng Anh-Mỹ)', 'n.', 'cruise (n.), cruise (v.), cruising (n.)', NULL, 'Tàu du lịch cỡ lớn thường gọi là "cruise ship", không gọi là "cruiser".', 'We spent the weekend aboard a small cabin cruiser.', NULL, 'Chúng tôi đã dành cả cuối tuần trên một chiếc du thuyền nhỏ có khoang ngủ.', '{"wordId":"cruiser","ukIpa":"/ˈkruːzə/","usIpa":"/ˈkruːzər/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"A powered leisure boat with space for sleeping.","vi":"du thuyền có khoang ngủ"},{"pos":"n.","en":"A large, fast military ship.","vi":"tuần dương hạm"},{"pos":"n.","en":"A police car used to patrol an area.","vi":"xe cảnh sát tuần tra (tiếng Anh-Mỹ)"}],"examples":[{"en":"We spent the weekend aboard a small cabin cruiser.","vi":"Chúng tôi đã dành cả cuối tuần trên một chiếc du thuyền nhỏ có khoang ngủ.","audioKind":"ex"},{"en":"The growing popularity of holidays aboard a cruiser has increased demand for moorings along inland waterways.","vi":"Sự phổ biến ngày càng tăng của những kỳ nghỉ trên du thuyền đã làm tăng nhu cầu về bến neo đậu dọc theo các tuyến đường thủy nội địa.","audioKind":"ex2"}],"collocations":[{"en":"a cabin cruiser","vi":"du thuyền có khoang ngủ"},{"en":"a police cruiser","vi":"xe cảnh sát tuần tra"},{"en":"a naval cruiser","vi":"tuần dương hạm hải quân"}],"wordFamily":["cruise (n.)","cruise (v.)","cruising (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tàu du lịch cỡ lớn thường gọi là \"cruise ship\", không gọi là \"cruiser\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consulate', 'en-c1-4', 'consulate', '/ˈkɑːnsələt/', 'C1', 'lãnh sự quán', 'n.', 'consul (n.), consular (adj.)', NULL, 'Consulate là lãnh sự quán; embassy là đại sứ quán, chức năng khác nhau.', 'She contacted the consulate after losing her passport abroad.', NULL, 'Cô ấy đã liên hệ với lãnh sự quán sau khi bị mất hộ chiếu ở nước ngoài.', '{"wordId":"consulate","ukIpa":"/ˈkɒnsjələt/","usIpa":"/ˈkɑːnsələt/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"an office representing a country and helping its citizens abroad","vi":"lãnh sự quán"}],"examples":[{"en":"She contacted the consulate after losing her passport abroad.","vi":"Cô ấy đã liên hệ với lãnh sự quán sau khi bị mất hộ chiếu ở nước ngoài.","audioKind":"ex"},{"en":"A consulate can provide essential assistance to citizens who encounter legal or administrative difficulties while travelling abroad.","vi":"Lãnh sự quán có thể cung cấp sự hỗ trợ thiết yếu cho công dân gặp khó khăn về pháp lý hoặc hành chính khi đi du lịch nước ngoài.","audioKind":"ex2"}],"collocations":[{"en":"contact the consulate","vi":"liên hệ với lãnh sự quán"},{"en":"consulate general","vi":"tổng lãnh sự quán"},{"en":"nearest consulate","vi":"lãnh sự quán gần nhất"}],"wordFamily":["consul (n.)","consular (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Consulate là lãnh sự quán; embassy là đại sứ quán, chức năng khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bypass', 'en-c1-4', 'bypass', '/ˈbaɪpæs/', 'C1', 'đi vòng qua cái gì đó hoặc né tránh một bước thông thường; đường tránh, đường vòng qua thị trấn thay vì đi xuyên qua nó; lối đi thay thế, hoặc ca phẫu thuật tạo ra lối đi như vậy cho dòng máu lưu thông', 'v.', NULL, NULL, 'Dùng như động từ trực tiếp nhận tân ngữ: bypass the town.', 'We took a narrow lane to bypass the village.', NULL, 'Chúng tôi đi vào một con đường nhỏ để tránh đi qua ngôi làng.', '{"wordId":"bypass","ukIpa":"/ˈbaɪpɑːs/","usIpa":"/ˈbaɪpæs/","cefr":"C1","topic":"travel","senses":[{"pos":"v.","en":"To go around something or avoid a usual step","vi":"đi vòng qua cái gì đó hoặc né tránh một bước thông thường"},{"pos":"n.","en":"A road carrying traffic around a town rather than through it","vi":"đường tránh, đường vòng qua thị trấn thay vì đi xuyên qua nó"},{"pos":"n.","en":"An alternative passage, or surgery creating one for blood flow","vi":"lối đi thay thế, hoặc ca phẫu thuật tạo ra lối đi như vậy cho dòng máu lưu thông"}],"examples":[{"en":"We took a narrow lane to bypass the village.","vi":"Chúng tôi đi vào một con đường nhỏ để tránh đi qua ngôi làng.","audioKind":"ex"},{"en":"A new bypass could reduce congestion in the town centre but might damage nearby wildlife habitats.","vi":"Một con đường tránh mới có thể làm giảm tình trạng ùn tắc ở trung tâm thị trấn nhưng có thể gây tổn hại đến môi trường sống của động vật hoang dã gần đó.","audioKind":"ex2"}],"collocations":[{"en":"bypass the town","vi":"né tránh thị trấn"},{"en":"bypass security checks","vi":"né tránh kiểm tra an ninh"},{"en":"build a bypass","vi":"xây dựng đường tránh"},{"en":"heart bypass surgery","vi":"phẫu thuật bắc cầu mạch vành"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng như động từ trực tiếp nhận tân ngữ: bypass the town.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inaccessible', 'en-c1-4', 'inaccessible', '/ˌɪnækˈsesəbl/', 'C1', 'khó hoặc không thể tiếp cận, tới gần hoặc bước vào; khó hoặc không thể có được, sử dụng hay lĩnh hội', 'adj.', 'accessible (adj.), accessibility (n.), inaccessibility (n.), access (n.)', 'Đồng nghĩa: unreachable · Trái nghĩa: accessible', 'Thường dùng cấu trúc inaccessible to sb, chỉ việc ai đó không thể tiếp cận hoặc sử dụng.', 'Heavy snow made the mountain cabin inaccessible all weekend.', NULL, 'Tuyết rơi dày đặc khiến căn nhà gỗ trên núi không thể tiếp cận được suốt cả cuối tuần.', '{"wordId":"inaccessible","ukIpa":"/ˌɪnækˈsesəbl/","usIpa":"/ˌɪnækˈsesəbl/","cefr":"C1","topic":"travel","senses":[{"pos":"adj.","en":"difficult or impossible to reach or enter","vi":"khó hoặc không thể tiếp cận, tới gần hoặc bước vào"},{"pos":"adj.","en":"difficult or impossible to obtain, use, or understand","vi":"khó hoặc không thể có được, sử dụng hay lĩnh hội"}],"examples":[{"en":"Heavy snow made the mountain cabin inaccessible all weekend.","vi":"Tuyết rơi dày đặc khiến căn nhà gỗ trên núi không thể tiếp cận được suốt cả cuối tuần.","audioKind":"ex"},{"en":"Public services remain inaccessible to many rural residents because reliable transport and internet connections are lacking.","vi":"Nhiều cư dân nông thôn vẫn không thể tiếp cận các dịch vụ công do thiếu hệ thống giao thông và kết nối internet đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"inaccessible to visitors","vi":"khách tham quan không thể tiếp cận"},{"en":"an inaccessible area","vi":"vùng sâu vùng xa khó tới"},{"en":"largely inaccessible","vi":"gần như không thể có được"}],"wordFamily":["accessible (adj.)","accessibility (n.)","inaccessibility (n.)","access (n.)"],"synonyms":["unreachable"],"antonyms":["accessible"],"tipVi":"Thường dùng cấu trúc inaccessible to sb, chỉ việc ai đó không thể tiếp cận hoặc sử dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_4_1', 'en-c1-4', 'Cách dùng “maiden” (adj.) — đầu tiên; chuyến xuất phát đầu tiên', 'maiden voyage  ·  maiden flight  ·  maiden speech', 'Tính từ thường chỉ lần đầu tiên; khi dùng làm danh từ chỉ thiếu nữ thì mang phong cách văn chương hoặc cổ xưa.', NULL, '[{"hanzi":"The new ferry completed its maiden voyage this morning.","pinyin":"","meaning":"Chiếc phà mới đã hoàn thành chuyến hải trình đầu tiên vào sáng nay."},{"hanzi":"The aircraft''s maiden flight marked an important step towards developing cleaner forms of regional transport.","pinyin":"","meaning":"Chuyến bay đầu tiên của chiếc máy bay này đánh dấu một bước tiến quan trọng trong việc phát triển các phương tiện giao thông khu vực thân thiện với môi trường hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_4_2', 'en-c1-4', 'Cách dùng “transit” (n.) — sự vận chuyển; quá trình chuyên chở', 'in transit  ·  public transit  ·  transit system', 'Cụm từ in transit mang nghĩa đang trên đường vận chuyển; từ public transit rất phổ biến trong tiếng Anh-Mỹ.', 'Đồng nghĩa: transportation', '[{"hanzi":"The glasses broke while they were in transit.","pinyin":"","meaning":"Những chiếc ly thủy tinh đã bị vỡ trong quá trình vận chuyển."},{"hanzi":"Investment in public transit can reduce traffic congestion and improve access to employment in growing cities.","pinyin":"","meaning":"Đầu tư vào hệ thống giao thông công cộng có thể làm giảm tình trạng ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm tại các thành phố đang phát triển."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_4_3', 'en-c1-4', 'Cách dùng “orientate” (v.) — xác định phương hướng; làm quen với môi trường xung quanh', 'orientate yourself  ·  orientate something towards', 'Thường dùng trong tiếng Anh-Anh; phổ biến với cụm orientate oneself, không chỉ riêng hướng Đông.', 'Họ từ (Word Family): orient (v.), orientation (n.), disorientate (v.) | Đồng nghĩa: orient · Trái nghĩa: disorientate', '[{"hanzi":"I used the river to orientate myself in town.","pinyin":"","meaning":"Tôi đã dùng con sông để định hướng vị trí của mình trong thị trấn."},{"hanzi":"Universities should orientate their support services towards the needs of students adjusting to life away from home.","pinyin":"","meaning":"Các trường đại học nên định hướng các dịch vụ hỗ trợ của mình vào nhu cầu của sinh viên khi họ thích nghi với cuộc sống xa nhà."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_4_4', 'en-c1-4', 'Cách dùng “secluded” (adj.) — hẻo lánh; tách biệt; thanh vắng', 'secluded beach  ·  secluded spot  ·  secluded garden', 'Thường mô tả địa điểm vắng vẻ, ẩn khuất, không đồng nghĩa với tính cách hướng nội của con người.', 'Họ từ (Word Family): seclude (v.), seclusion (n.) | Đồng nghĩa: isolated, hidden, private · Trái nghĩa: exposed', '[{"hanzi":"We found a secluded beach behind the cliffs.","pinyin":"","meaning":"Chúng tôi đã tìm thấy một bãi biển hoang sơ, vắng vẻ phía sau các vách đá."},{"hanzi":"Although secluded rural homes offer privacy, their residents may struggle to access healthcare and public transport.","pinyin":"","meaning":"Mặc dù những ngôi nhà ở vùng nông thôn hẻo lánh mang lại sự riêng tư, nhưng cư dân ở đó có thể gặp khó khăn trong việc tiếp cận dịch vụ y tế và giao thông công cộng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_4_1', 'en-c1-4', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_1_1', 'ten_c1_4_1', 'hull', 'We painted the boat''s hull blue before launching it.', 'We painted the boat''s hull blue before launching it.', '/hʌl/', 'Chúng tôi đã sơn phần thân tàu thành màu xanh trước khi hạ thủy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_1_2', 'ten_c1_4_1', 'laden', 'She arrived at the picnic laden with bags of food.', 'She arrived at the picnic laden with bags of food.', '/ˈleɪdn/', 'Cô ấy đến buổi dã ngoại với những túi đồ ăn trĩu nặng trên tay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_1_3', 'ten_c1_4_1', 'orientate', 'I used the river to orientate myself in town.', 'I used the river to orientate myself in town.', '/ˈɔːriənteɪt/', 'Tôi đã dùng con sông để định hướng vị trí của mình trong thị trấn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
