INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_1_5', 'ten_c1_4_1', 'secluded', 'We found a secluded beach behind the cliffs.', 'We found a secluded beach behind the cliffs.', '/sɪˈkluːdɪd/', 'Chúng tôi đã tìm thấy một bãi biển hoang sơ, vắng vẻ phía sau các vách đá.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_1_6', 'ten_c1_4_1', 'ply', 'Small ferries ply between the island and the mainland.', 'Small ferries ply between the island and the mainland.', '/plaɪ/', 'Những chiếc phà nhỏ chạy tuyến đều đặn giữa hòn đảo và đất liền.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_1_7', 'ten_c1_4_1', 'maiden', 'The new ferry completed its maiden voyage this morning.', 'The new ferry completed its maiden voyage this morning.', '/ˈmeɪdən/', 'Chiếc phà mới đã hoàn thành chuyến hải trình đầu tiên vào sáng nay.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_1_8', 'ten_c1_4_1', 'wharf', 'We watched fishermen unload their catch at the wharf.', 'We watched fishermen unload their catch at the wharf.', '/wɔːrf/', 'Chúng tôi đứng xem ngư dân dỡ cá vừa đánh bắt được ở cầu cảng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_4_1_1', 'en-c1-4', 'ten_c1_4_1', 'listening', 'listening', 'We painted the boat''s hull blue before launching it.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xe buýt của chúng tôi vẫn đứng yên trong lúc hành khách bước lên xe.","Chúng tôi đã tìm thấy một bãi biển hoang sơ, vắng vẻ phía sau các vách đá.","Chúng tôi đã sơn phần thân tàu thành màu xanh trước khi hạ thủy.","Chúng tôi đứng xem ngư dân dỡ cá vừa đánh bắt được ở cầu cảng."]'::jsonb, 2, 'We painted the boat''s hull blue before launching it. → Chúng tôi đã sơn phần thân tàu thành màu xanh trước khi hạ thủy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_4_1_2', 'en-c1-4', 'ten_c1_4_1', 'listening', 'listening', 'She arrived at the picnic laden with bags of food.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã sơn phần thân tàu thành màu xanh trước khi hạ thủy.","Những chiếc ly thủy tinh đã bị vỡ trong quá trình vận chuyển.","Cô ấy đến buổi dã ngoại với những túi đồ ăn trĩu nặng trên tay.","Tôi đã dùng con sông để định hướng vị trí của mình trong thị trấn."]'::jsonb, 2, 'She arrived at the picnic laden with bags of food. → Cô ấy đến buổi dã ngoại với những túi đồ ăn trĩu nặng trên tay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_4_1_3', 'en-c1-4', 'ten_c1_4_1', 'listening', 'listening', 'I used the river to orientate myself in town.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những chiếc phà nhỏ chạy tuyến đều đặn giữa hòn đảo và đất liền.","Chúng tôi đã tìm thấy một bãi biển hoang sơ, vắng vẻ phía sau các vách đá.","Chúng tôi đã dành cả cuối tuần trên một chiếc du thuyền nhỏ có khoang ngủ.","Tôi đã dùng con sông để định hướng vị trí của mình trong thị trấn."]'::jsonb, 3, 'I used the river to orientate myself in town. → Tôi đã dùng con sông để định hướng vị trí của mình trong thị trấn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_4_2', 'en-c1-4', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_2_1', 'ten_c1_4_2', 'hull', 'Improved hull designs can reduce fuel consumption by allowing ships to move through water with less resistance.', 'Improved hull designs can reduce fuel consumption by allowing ships to move through water with less resistance.', '/hʌl/', 'Thiết kế thân tàu được cải tiến có thể làm giảm mức tiêu thụ nhiên liệu bằng cách cho phép tàu di chuyển qua nước với ít lực cản hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_2_2', 'ten_c1_4_2', 'laden', 'Trucks laden with construction materials contribute to congestion and increase road maintenance costs in rapidly expanding cities.', 'Trucks laden with construction materials contribute to congestion and increase road maintenance costs in rapidly expanding cities.', '/ˈleɪdn/', 'Những chiếc xe tải chở đầy vật liệu xây dựng làm gia tăng tình trạng ùn tắc và làm tăng chi phí bảo trì đường bộ ở các thành phố đang phát triển nhanh chóng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_2_3', 'ten_c1_4_2', 'orientate', 'Universities should orientate their support services towards the needs of students adjusting to life away from home.', 'Universities should orientate their support services towards the needs of students adjusting to life away from home.', '/ˈɔːriənteɪt/', 'Các trường đại học nên định hướng các dịch vụ hỗ trợ của mình vào nhu cầu của sinh viên khi họ thích nghi với cuộc sống xa nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_2_4', 'ten_c1_4_2', 'transit', 'Investment in public transit can reduce traffic congestion and improve access to employment in growing cities.', 'Investment in public transit can reduce traffic congestion and improve access to employment in growing cities.', '/ˈtrænzɪt/', 'Đầu tư vào hệ thống giao thông công cộng có thể làm giảm tình trạng ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm tại các thành phố đang phát triển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_2_5', 'ten_c1_4_2', 'secluded', 'Although secluded rural homes offer privacy, their residents may struggle to access healthcare and public transport.', 'Although secluded rural homes offer privacy, their residents may struggle to access healthcare and public transport.', '/sɪˈkluːdɪd/', 'Mặc dù những ngôi nhà ở vùng nông thôn hẻo lánh mang lại sự riêng tư, nhưng cư dân ở đó có thể gặp khó khăn trong việc tiếp cận dịch vụ y tế và giao thông công cộng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_4_2_6', 'ten_c1_4_2', 'ply', 'Buses that ply rural routes provide essential access to healthcare and education for isolated communities.', 'Buses that ply rural routes provide essential access to healthcare and education for isolated communities.', '/plaɪ/', 'Xe buýt chạy định kỳ trên các tuyến đường nông thôn cung cấp quyền tiếp cận thiết yếu đối với dịch vụ y tế và giáo dục cho các cộng đồng bị cô lập.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_4_2_1', 'en-c1-4', 'ten_c1_4_2', 'listening', 'listening', 'Improved hull designs can reduce fuel consumption by allowing ships to move through water with less resistance.', NULL, 'Trong câu vừa nghe, từ “hull” mang nghĩa nào sau đây?', '["sự buộc phải rời khỏi nhà cửa; tình trạng ly hương, lưu vong","gây chết người, chí mạng","thân tàu (phần vỏ chính bên ngoài của tàu thuyền)","thực thể độc lập; tổ chức riêng biệt"]'::jsonb, 2, '“hull” (/hʌl/): thân tàu (phần vỏ chính bên ngoài của tàu thuyền). Câu đầy đủ: Improved hull designs can reduce fuel consumption by allowing ships to move through water with less resistance.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_4_2_2', 'en-c1-4', 'ten_c1_4_2', 'listening', 'listening', 'Trucks laden with construction materials contribute to congestion and increase road maintenance costs in rapidly expanding cities.', NULL, 'Trong câu vừa nghe, từ “laden” mang nghĩa nào sau đây?', '["chất đầy; mang nặng; trĩu","một cách đầy tiếc nuối, thể hiện sự buồn bã hoặc thất vọng về điều gì đó","nhanh nhẹn; khẩn trương","sự bồn chồn; sự lo âu; sự kích động"]'::jsonb, 0, '“laden” (/ˈleɪdn/): chất đầy; mang nặng; trĩu. Câu đầy đủ: Trucks laden with construction materials contribute to congestion and increase road maintenance costs in rapidly expanding cities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
