INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_4_1', 'en-c1-4', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “hull” (/hʌl/) có nghĩa là gì?', '["thân tàu (phần vỏ chính bên ngoài của tàu thuyền)","đầu tiên; chuyến xuất phát đầu tiên","du thuyền có khoang ngủ","khó hoặc không thể tiếp cận, tới gần hoặc bước vào"]'::jsonb, 0, '“hull” (n.): thân tàu (phần vỏ chính bên ngoài của tàu thuyền); vỏ (lớp vỏ ngoài của hạt hoặc quả); bóc vỏ; cắt cuống (loại bỏ lớp vỏ ngoài hoặc phần cuống lá của thực phẩm).', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
