INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_1', 'en-c1-4', NULL, 'comprehensive_test', 'listening', 'hull', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["định lượng; thuộc về số lượng","sự chế nhạo; lời mỉa mai","cơn co giật; cơn động kinh đột ngột","thân tàu (phần vỏ chính bên ngoài của tàu thuyền)"]'::jsonb, 3, 'hull (/hʌl/) → thân tàu (phần vỏ chính bên ngoài của tàu thuyền); vỏ (lớp vỏ ngoài của hạt hoặc quả); bóc vỏ; cắt cuống (loại bỏ lớp vỏ ngoài hoặc phần cuống lá của thực phẩm)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_2', 'en-c1-4', NULL, 'comprehensive_test', 'listening', 'She arrived at the picnic laden with bags of food.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đứng xem ngư dân dỡ cá vừa đánh bắt được ở cầu cảng.","Một đầu máy xe lửa hơi nước đã kéo các toa tàu từ từ lướt qua sân ga của chúng tôi.","Cô ấy đến buổi dã ngoại với những túi đồ ăn trĩu nặng trên tay.","Cô ấy đã liên hệ với lãnh sự quán sau khi bị mất hộ chiếu ở nước ngoài."]'::jsonb, 2, 'She arrived at the picnic laden with bags of food. → Cô ấy đến buổi dã ngoại với những túi đồ ăn trĩu nặng trên tay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_3', 'en-c1-4', NULL, 'comprehensive_test', 'listening', 'orientate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quân đoàn; binh chủng","sự nhàn rỗi; sự vô công rỗi nghề; tính lười biếng","xác định phương hướng; làm quen với môi trường xung quanh","chú ý; lắng nghe và làm theo"]'::jsonb, 2, 'orientate (/ˈɔːriənteɪt/) → xác định phương hướng; làm quen với môi trường xung quanh; làm cho hướng về; định hướng vào', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_4', 'en-c1-4', NULL, 'comprehensive_test', 'listening', 'The glasses broke while they were in transit.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã tìm thấy một bãi biển hoang sơ, vắng vẻ phía sau các vách đá.","Tôi đã dùng con sông để định hướng vị trí của mình trong thị trấn.","Những chiếc ly thủy tinh đã bị vỡ trong quá trình vận chuyển.","Chúng tôi ở lại trong một căn nhà gỗ bị tuyết vây kín suốt ba ngày."]'::jsonb, 2, 'The glasses broke while they were in transit. → Những chiếc ly thủy tinh đã bị vỡ trong quá trình vận chuyển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_5', 'en-c1-4', NULL, 'comprehensive_test', 'listening', 'secluded', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bao dung; mang tính hòa nhập","căm phẫn, bất bình do cho rằng mình bị đối xử bất công","dễ bị tổn thương; dễ bị ảnh hưởng tiêu cực","hẻo lánh; tách biệt; thanh vắng"]'::jsonb, 3, 'secluded (/sɪˈkluːdɪd/) → hẻo lánh; tách biệt; thanh vắng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_6', 'en-c1-4', NULL, 'comprehensive_test', 'listening', 'Small ferries ply between the island and the mainland.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đến buổi dã ngoại với những túi đồ ăn trĩu nặng trên tay.","Những chiếc phà nhỏ chạy tuyến đều đặn giữa hòn đảo và đất liền.","Một đầu máy xe lửa hơi nước đã kéo các toa tàu từ từ lướt qua sân ga của chúng tôi.","Chúng tôi đã sơn phần thân tàu thành màu xanh trước khi hạ thủy."]'::jsonb, 1, 'Small ferries ply between the island and the mainland. → Những chiếc phà nhỏ chạy tuyến đều đặn giữa hòn đảo và đất liền.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_7', 'en-c1-4', NULL, 'comprehensive_test', 'listening', 'maiden', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chịu đựng; chống lại; trụ vững","sự tích lũy; sự tích tụ; lượng tích tụ","cản trở; gây khó khăn","đầu tiên; chuyến xuất phát đầu tiên"]'::jsonb, 3, 'maiden (/ˈmeɪdən/) → đầu tiên; chuyến xuất phát đầu tiên; thiếu nữ; người con gái chưa chồng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_8', 'en-c1-4', NULL, 'comprehensive_test', 'listening', 'We watched fishermen unload their catch at the wharf.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi vào một con đường nhỏ để tránh đi qua ngôi làng.","Những chiếc ly thủy tinh đã bị vỡ trong quá trình vận chuyển.","Tôi đã dùng con sông để định hướng vị trí của mình trong thị trấn.","Chúng tôi đứng xem ngư dân dỡ cá vừa đánh bắt được ở cầu cảng."]'::jsonb, 3, 'We watched fishermen unload their catch at the wharf. → Chúng tôi đứng xem ngư dân dỡ cá vừa đánh bắt được ở cầu cảng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_9', 'en-c1-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “private and quiet, away from people and busy places”?', '["stationary","maiden","wharf","secluded"]'::jsonb, 3, 'secluded (/sɪˈkluːdɪd/) → hẻo lánh; tách biệt; thanh vắng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_10', 'en-c1-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To travel regularly along a route, especially by boat”?', '["maiden","ply","hull","secluded"]'::jsonb, 1, 'ply (/plaɪ/) → chạy tuyến cố định; đi lại đều đặn', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_11', 'en-c1-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “being the first of its kind for someone or something”?', '["orientate","bypass","hull","maiden"]'::jsonb, 3, 'maiden (/ˈmeɪdən/) → đầu tiên; chuyến xuất phát đầu tiên', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_12', 'en-c1-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A structure beside water where boats load and unload.”?', '["laden","wharf","consulate","inaccessible"]'::jsonb, 1, 'wharf (/wɔːrf/) → cầu cảng; bến tàu', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_13', 'en-c1-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Not moving or changing position.”?', '["cruiser","maiden","stationary","wharf"]'::jsonb, 2, 'stationary (/ˈsteɪʃəneri/) → đứng yên; tĩnh tại; không di chuyển', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
