INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_18', 'en-c1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Improved hull designs can reduce fuel consumption by allowing ships to move through water with less resistance.', 'Dựa vào câu trên, từ “hull” có nghĩa phù hợp nhất là gì?', '["nhập thêm hàng; bổ sung hàng hóa","sự cẩu thả, sự lơ đễnh, sự thiếu trách nhiệm, lỗi bất cẩn","thân tàu (phần vỏ chính bên ngoài của tàu thuyền)","lớp phủ; tầng phủ (tuyết, sương,...)"]'::jsonb, 2, 'hull: thân tàu (phần vỏ chính bên ngoài của tàu thuyền); vỏ (lớp vỏ ngoài của hạt hoặc quả); bóc vỏ; cắt cuống (loại bỏ lớp vỏ ngoài hoặc phần cuống lá của thực phẩm). Dịch cả câu: Thiết kế thân tàu được cải tiến có thể làm giảm mức tiêu thụ nhiên liệu bằng cách cho phép tàu di chuyển qua nước với ít lực cản hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_19', 'en-c1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Trucks laden with construction materials contribute to congestion and increase road maintenance costs in rapidly expanding cities.', 'Dựa vào câu trên, từ “laden” có nghĩa phù hợp nhất là gì?', '["chất đầy; mang nặng; trĩu","giếng (thang máy, thông gió); đường hầm thẳng đứng","thuộc về đế quốc; thuộc về hoàng gia","tinh xảo; phức tạp; công phu"]'::jsonb, 0, 'laden: chất đầy; mang nặng; trĩu; chứa đầy cảm xúc (đặc biệt là cảm xúc tiêu cực). Dịch cả câu: Những chiếc xe tải chở đầy vật liệu xây dựng làm gia tăng tình trạng ùn tắc và làm tăng chi phí bảo trì đường bộ ở các thành phố đang phát triển nhanh chóng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_20', 'en-c1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Universities should orientate their support services towards the needs of students adjusting to life away from home.', 'Dựa vào câu trên, từ “orientate” có nghĩa phù hợp nhất là gì?', '["xác định phương hướng; làm quen với môi trường xung quanh","hiện lên lờ mờ, xuất hiện với hình thù to lớn và có vẻ đe dọa","làm triệt tiêu; vô hiệu hóa","người đại diện; người ủy quyền"]'::jsonb, 0, 'orientate: xác định phương hướng; làm quen với môi trường xung quanh; làm cho hướng về; định hướng vào. Dịch cả câu: Các trường đại học nên định hướng các dịch vụ hỗ trợ của mình vào nhu cầu của sinh viên khi họ thích nghi với cuộc sống xa nhà.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_21', 'en-c1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in public transit can reduce traffic congestion and improve access to employment in growing cities.', 'Dựa vào câu trên, từ “transit” có nghĩa phù hợp nhất là gì?', '["sắp tới; sắp diễn ra","làm suy yếu dần; hủy hoại (lòng tin, quyền lực, hiệu quả)","sự vận chuyển; quá trình chuyên chở","lò luyện; lò công nghiệp"]'::jsonb, 2, 'transit: sự vận chuyển; quá trình chuyên chở; hệ thống giao thông công cộng. Dịch cả câu: Đầu tư vào hệ thống giao thông công cộng có thể làm giảm tình trạng ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm tại các thành phố đang phát triển.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_22', 'en-c1-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lãnh sự quán”', '["consulate","consolidate","tumour","spiral"]'::jsonb, 0, 'lãnh sự quán → consulate (/ˈkɑːnsələt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_23', 'en-c1-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đi vòng qua cái gì đó hoặc né tránh một bước thông thường”', '["tolerable","whereby","bypass","fellowship"]'::jsonb, 2, 'đi vòng qua cái gì đó hoặc né tránh một bước thông thường → bypass (/ˈbaɪpæs/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_4_24', 'en-c1-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khó hoặc không thể tiếp cận, tới gần hoặc bước vào”', '["rodent","scant","inference","inaccessible"]'::jsonb, 3, 'khó hoặc không thể tiếp cận, tới gần hoặc bước vào → inaccessible (/ˌɪnækˈsesəbl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-5', 'en', 'Bài 5: Du lịch & Di chuyển (2) - CEFR C1', 'CEFR C1', 'C1 · Du lịch', '15 từ vựng Tiếng Anh CEFR C1 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5005, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vessel', 'en-c1-5', 'vessel', '/ˈvesəl/', 'C1', 'thuyền lớn; tàu thủy; mạch máu; mạch dẫn; bình; lọ; chậu chứa chất lỏng', 'n.', NULL, NULL, 'vessel là từ mang tính trang trọng; blood vessel là "mạch máu", không phải là tàu thuyền.', 'A large fishing vessel sailed slowly into the harbour.', NULL, 'Một chiếc tàu cá lớn từ từ tiến vào vũng tàu.', '{"wordId":"vessel","ukIpa":"/ˈvesəl/","usIpa":"/ˈvesəl/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"A ship or large boat.","vi":"thuyền lớn; tàu thủy"},{"pos":"n.","en":"A tube carrying blood or other fluid through a living body.","vi":"mạch máu; mạch dẫn"},{"pos":"n.","en":"A container used to hold liquids.","vi":"bình; lọ; chậu chứa chất lỏng"}],"examples":[{"en":"A large fishing vessel sailed slowly into the harbour.","vi":"Một chiếc tàu cá lớn từ từ tiến vào vũng tàu.","audioKind":"ex"},{"en":"Commercial vessels can disturb marine ecosystems through underwater noise, fuel leaks, and the introduction of non-native species.","vi":"Các tàu thương mại có thể làm xáo trộn hệ sinh thái biển thông qua tiếng ồn dưới nước, rò rỉ nhiên liệu và sự xâm nhập của các loài ngoại lai.","audioKind":"ex2"}],"collocations":[{"en":"a fishing vessel","vi":"tàu đánh cá"},{"en":"a cargo vessel","vi":"tàu chở hàng"},{"en":"a blood vessel","vi":"mạch máu"},{"en":"a pressure vessel","vi":"bình chịu áp lực"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"vessel là từ mang tính trang trọng; blood vessel là \"mạch máu\", không phải là tàu thuyền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mast', 'en-c1-5', 'mast', '/mæst/', 'C1', 'cột buồm; cột ăng-ten; trụ phát sóng', 'n.', 'masted (adj.)', NULL, 'Nghĩa cốt lõi là cột đỡ buồm trên tàu thuyền, ngoài ra còn chỉ cột cao gắn thiết bị thu phát sóng.', 'A white sail fluttered high on the wooden mast.', NULL, 'Một cánh buồm trắng phấp phới ở tầm cao trên cột buồm bằng gỗ.', '{"wordId":"mast","ukIpa":"/mɑːst/","usIpa":"/mæst/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"A tall upright pole supporting sails on a boat","vi":"cột buồm"},{"pos":"n.","en":"A tall structure supporting equipment that sends or receives signals","vi":"cột ăng-ten; trụ phát sóng"}],"examples":[{"en":"A white sail fluttered high on the wooden mast.","vi":"Một cánh buồm trắng phấp phới ở tầm cao trên cột buồm bằng gỗ.","audioKind":"ex"},{"en":"Installing a new communications mast could improve mobile coverage in remote villages and support local businesses.","vi":"Việc lắp đặt một cột thông tin liên lạc mới có thể cải thiện độ phủ sóng di động ở các ngôi làng vùng sâu vùng xa và hỗ trợ các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"main mast","vi":"cột buồm chính"},{"en":"communications mast","vi":"cột phát sóng viễn thông"},{"en":"at half mast","vi":"treo cờ rủ"}],"wordFamily":["masted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa cốt lõi là cột đỡ buồm trên tàu thuyền, ngoài ra còn chỉ cột cao gắn thiết bị thu phát sóng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_roam', 'en-c1-5', 'roam', '/roʊm/', 'C1', 'lang thang; đi lang thang; thả bộ', 'v.', 'roaming (n.)', 'Đồng nghĩa: wander, rove', 'Có thể kết hợp trực tiếp với danh từ chỉ địa điểm, hoặc dùng với roam around hay through.', 'We roamed through the market until our feet hurt.', NULL, 'Chúng tôi đi lang thang qua khu chợ cho đến khi đau cả chân.', '{"wordId":"roam","ukIpa":"/rəʊm/","usIpa":"/roʊm/","cefr":"C1","topic":"travel","senses":[{"pos":"v.","en":"To move around freely without a fixed route or destination.","vi":"lang thang; đi lang thang; thả bộ"}],"examples":[{"en":"We roamed through the market until our feet hurt.","vi":"Chúng tôi đi lang thang qua khu chợ cho đến khi đau cả chân.","audioKind":"ex"},{"en":"Protected wildlife corridors allow large animals to roam freely between habitats without crossing busy roads.","vi":"Các hành lang động vật hoang dã được bảo vệ cho phép các loài thú lớn tự do di chuyển giữa các sinh cảnh mà không phải băng qua những con đường đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"roam freely","vi":"tự do đi lại"},{"en":"roam the streets","vi":"lang thang trên phố"},{"en":"roam around","vi":"đi lang thang đây đó"}],"wordFamily":["roaming (n.)"],"synonyms":["wander","rove"],"antonyms":[],"tipVi":"Có thể kết hợp trực tiếp với danh từ chỉ địa điểm, hoặc dùng với roam around hay through.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_barge', 'en-c1-5', 'barge', '/bɑːrdʒ/', 'C1', 'thuyền chở hàng đáy bằng; sà lan; xông vào; va quẹt thô bạo', 'n.', NULL, NULL, 'Động từ thường đi với in hoặc into, mang ý nghĩa xông vào một cách bất lịch sự.', 'A barge loaded with sand passed beneath the bridge.', NULL, 'Một chiếc sà lan chở đầy cát chạy qua dưới gầm cầu.', '{"wordId":"barge","ukIpa":"/bɑːdʒ/","usIpa":"/bɑːrdʒ/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"A flat-bottomed boat carrying goods on rivers or canals","vi":"thuyền chở hàng đáy bằng; sà lan"},{"pos":"v.","en":"To move roughly or rudely past people or into somewhere","vi":"xông vào; va quẹt thô bạo"}],"examples":[{"en":"A barge loaded with sand passed beneath the bridge.","vi":"Một chiếc sà lan chở đầy cát chạy qua dưới gầm cầu.","audioKind":"ex"},{"en":"Transporting construction materials by barge can reduce the number of heavy vehicles travelling through crowded urban areas.","vi":"Việc vận chuyển vật liệu xây dựng bằng sà lan có thể làm giảm số lượng xe tải hạng nặng di chuyển qua các khu đô thị đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"cargo barge","vi":"sà lan chở hàng"},{"en":"by barge","vi":"vận chuyển bằng sà lan"},{"en":"barge into a room","vi":"xông vào phòng"},{"en":"barge past someone","vi":"chen lấn vượt qua ai đó"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường đi với in hoặc into, mang ý nghĩa xông vào một cách bất lịch sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_traverse', 'en-c1-5', 'traverse', '/trəˈvɝːs/', 'C1', 'đi qua; vượt qua', 'v.', 'traversal (n.)', 'Đồng nghĩa: cross', 'Đây là từ dùng trong văn phong trang trọng, đi trực tiếp với tân ngữ chỉ địa điểm: traverse the desert.', 'We traversed the snowy valley before reaching the mountain hut.', NULL, 'Chúng tôi đã vượt qua thung lũng đầy tuyết trước khi đến được căn lều trên núi.', '{"wordId":"traverse","ukIpa":"/trəˈvɜːs/","usIpa":"/trəˈvɝːs/","cefr":"C1","topic":"travel","senses":[{"pos":"v.","en":"To travel across or through an area.","vi":"đi qua; vượt qua"}],"examples":[{"en":"We traversed the snowy valley before reaching the mountain hut.","vi":"Chúng tôi đã vượt qua thung lũng đầy tuyết trước khi đến được căn lều trên núi.","audioKind":"ex"},{"en":"New railway routes traverse remote regions, connecting isolated communities with essential services and larger markets.","vi":"Các tuyến đường sắt mới chạy xuyên qua các vùng5050xemlai_bien_tap_lai_cho_chuan_xac_hoac_dung_tieu_chuan_viet_sach. Các tuyến đường sắt mới xuyên qua các vùng xa xôi, kết nối các cộng đồng biệt lập với các dịch vụ thiết yếu và thị trường lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"traverse a valley","vi":"vượt qua thung lũng"},{"en":"traverse rough terrain","vi":"vượt qua địa hình hiểm trở"},{"en":"traverse a continent","vi":"băng qua một lục địa"}],"wordFamily":["traversal (n.)"],"synonyms":["cross"],"antonyms":[],"tipVi":"Đây là từ dùng trong văn phong trang trọng, đi trực tiếp với tân ngữ chỉ địa điểm: traverse the desert.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ascend', 'en-c1-5', 'ascend', '/əˈsend/', 'C1', 'đi lên; bay lên; nâng lên vị trí cao hơn; leo lên; đi lên những nơi như cầu thang hoặc ngọn núi', 'v.', 'ascent (n.), ascending (adj.)', 'Đồng nghĩa: rise, climb · Trái nghĩa: descend', 'Đây là từ mang tính trang trọng; khi dùng ''ascend the stairs'' thì không cần thêm ''up''.', 'We watched the balloon ascend slowly into the clear sky.', NULL, 'Chúng tôi ngắm nhìn quả khinh khí cầu từ từ bay lên bầu trời trong xanh.', '{"wordId":"ascend","ukIpa":"/əˈsend/","usIpa":"/əˈsend/","cefr":"C1","topic":"travel","senses":[{"pos":"v.","en":"to move upwards or rise to a higher position","vi":"đi lên; bay lên; nâng lên vị trí cao hơn"},{"pos":"v.","en":"to go up something such as stairs or a mountain","vi":"leo lên; đi lên những nơi như cầu thang hoặc ngọn núi"}],"examples":[{"en":"We watched the balloon ascend slowly into the clear sky.","vi":"Chúng tôi ngắm nhìn quả khinh khí cầu từ từ bay lên bầu trời trong xanh.","audioKind":"ex"},{"en":"As hikers ascend the mountain, they encounter distinct vegetation zones shaped by changing temperatures and moisture levels.","vi":"Khi những người leo núi tiến lên đỉnh, họ bắt gặp các vành đai thực vật khác nhau được định hình bởi sự thay đổi của nhiệt độ và độ ẩm.","audioKind":"ex2"}],"collocations":[{"en":"ascend the stairs","vi":"đi lên cầu thang"},{"en":"ascend a mountain","vi":"leo núi"},{"en":"ascend to the summit","vi":"leo lên đỉnh"},{"en":"ascend the throne","vi":"lên ngôi bàng"}],"wordFamily":["ascent (n.)","ascending (adj.)"],"synonyms":["rise","climb"],"antonyms":["descend"],"tipVi":"Đây là từ mang tính trang trọng; khi dùng ''ascend the stairs'' thì không cần thêm ''up''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bazaar', 'en-c1-5', 'bazaar', '/bəˈzɑːr/', 'C1', 'chợ; khu mua sắm (nhiều cửa hàng/quầy hàng nhỏ); phiên chợ từ thiện; hội chợ từ thiện', 'n.', NULL, 'Đồng nghĩa: market, marketplace', 'Thường chỉ khu chợ truyền thống gồm nhiều gian hàng, hoặc cũng có thể chỉ một sự kiện bán hàng gây quỹ từ thiện.', 'We bought fragrant spices at the crowded bazaar.', NULL, 'Chúng tôi đã mua những loại gia vị thơm nức mũi tại khu chợ đông đúc.', '{"wordId":"bazaar","ukIpa":"/bəˈzɑː/","usIpa":"/bəˈzɑːr/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"a market with many small shops or stalls","vi":"chợ; khu mua sắm (nhiều cửa hàng/quầy hàng nhỏ)"},{"pos":"n.","en":"an event where goods are sold to raise money for charity","vi":"phiên chợ từ thiện; hội chợ từ thiện"}],"examples":[{"en":"We bought fragrant spices at the crowded bazaar.","vi":"Chúng tôi đã mua những loại gia vị thơm nức mũi tại khu chợ đông đúc.","audioKind":"ex"},{"en":"Traditional bazaars can attract tourists while providing local craftspeople with opportunities to sell their products directly.","vi":"Các khu chợ truyền thống vừa có thể thu hút khách du lịch vừa tạo cơ hội cho các nghệ nhân địa phương trực tiếp bán sản phẩm của họ.","audioKind":"ex2"}],"collocations":[{"en":"a bustling bazaar","vi":"chợ tấp nập"},{"en":"a charity bazaar","vi":"chợ từ thiện"},{"en":"a covered bazaar","vi":"chợ có mái che"}],"wordFamily":[],"synonyms":["market","marketplace"],"antonyms":[],"tipVi":"Thường chỉ khu chợ truyền thống gồm nhiều gian hàng, hoặc cũng có thể chỉ một sự kiện bán hàng gây quỹ từ thiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nautical', 'en-c1-5', 'nautical', '/ˈnɔːtɪkəl/', 'C1', 'thuộc về hàng hải; thuộc về tàu thuyền', 'adj.', NULL, 'Đồng nghĩa: maritime', 'Nautical tập trung vào việc đi biển và tàu thuyền; naval chỉ chuyên về lực lượng hải quân.', 'My uncle collects old nautical maps and wooden boats.', NULL, 'Chú tôi sưu tập những tấm bản đồ hàng hải cổ và các mô hình thuyền gỗ.', '{"wordId":"nautical","ukIpa":"/ˈnɔːtɪkəl/","usIpa":"/ˈnɔːtɪkəl/","cefr":"C1","topic":"travel","senses":[{"pos":"adj.","en":"Relating to ships, sailing, or navigation at sea","vi":"thuộc về hàng hải; thuộc về tàu thuyền"}],"examples":[{"en":"My uncle collects old nautical maps and wooden boats.","vi":"Chú tôi sưu tập những tấm bản đồ hàng hải cổ và các mô hình thuyền gỗ.","audioKind":"ex"},{"en":"Modern nautical equipment helps crews navigate safely, but practical training remains essential for preventing accidents at sea.","vi":"Thiết bị hàng hải hiện đại giúp các thủy thủ đoàn điều hướng an toàn, nhưng việc huấn luyện thực tế vẫn đóng vai trò cốt lõi để ngăn ngừa tai nạn trên biển.","audioKind":"ex2"}],"collocations":[{"en":"nautical mile","vi":"hải lý"},{"en":"nautical chart","vi":"bản đồ hàng hải"},{"en":"nautical equipment","vi":"thiết bị hàng hải"},{"en":"nautical theme","vi":"chủ đề hàng hải"}],"wordFamily":[],"synonyms":["maritime"],"antonyms":[],"tipVi":"Nautical tập trung vào việc đi biển và tàu thuyền; naval chỉ chuyên về lực lượng hải quân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pilgrimage', 'en-c1-5', 'pilgrimage', '/ˈpɪlɡrɪmɪdʒ/', 'C1', 'chuyến đi hành hương; chuyến viếng thăm một địa điểm mang ý nghĩa tinh thần đặc biệt', 'n.', 'pilgrim (n.)', NULL, 'Thường dùng cấu trúc make a pilgrimage to để chỉ việc đến hành hương tại một nơi nào đó.', 'My grandparents made a pilgrimage to the mountain temple.', NULL, 'Ông bà tôi đã thực hiện một chuyến hành hương lên ngôi chùa trên núi.', '{"wordId":"pilgrimage","ukIpa":"/ˈpɪlɡrɪmɪdʒ/","usIpa":"/ˈpɪlɡrɪmɪdʒ/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"A journey to a place important to someone''s religion.","vi":"chuyến đi hành hương"},{"pos":"n.","en":"A visit to a place with special personal significance.","vi":"chuyến viếng thăm một địa điểm mang ý nghĩa tinh thần đặc biệt"}],"examples":[{"en":"My grandparents made a pilgrimage to the mountain temple.","vi":"Ông bà tôi đã thực hiện một chuyến hành hương lên ngôi chùa trên núi.","audioKind":"ex"},{"en":"Religious pilgrimage can support local economies, but large visitor numbers may place pressure on fragile historic sites.","vi":"Hoạt động hành hương tôn giáo có thể hỗ trợ nền kinh tế địa phương, nhưng lượng khách du lịch lớn có thể gây áp lực lên các di tích lịch sử mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"go on a pilgrimage","vi":"đi hành hương"},{"en":"a pilgrimage site","vi":"địa điểm hành hương"},{"en":"make a pilgrimage to","vi":"thực hiện chuyến hành hương tới"}],"wordFamily":["pilgrim (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc make a pilgrimage to để chỉ việc đến hành hương tại một nơi nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quay', 'en-c1-5', 'quay', '/kiː/', 'C1', 'bến tàu; cầu tàu', 'n.', 'quayside (n.)', 'Đồng nghĩa: wharf', 'Phát âm giống từ key; thường chỉ bến cấu trúc kiên cố nằm dọc theo mặt nước.', 'We watched the ferry arrive from the stone quay.', NULL, 'Chúng tôi đứng trên bến tàu bằng đá ngắm chiếc phà cập bến.', '{"wordId":"quay","ukIpa":"/kiː/","usIpa":"/kiː/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"A solid waterside platform where boats stop for loading or unloading","vi":"bến tàu; cầu tàu"}],"examples":[{"en":"We watched the ferry arrive from the stone quay.","vi":"Chúng tôi đứng trên bến tàu bằng đá ngắm chiếc phà cập bến.","audioKind":"ex"},{"en":"Converting an unused quay into a public promenade can reconnect urban residents with their waterfront.","vi":"Việc chuyển đổi một bến tàu bỏ hoang thành một lối đi dạo công cộng có thể giúp cư dân thành thị kết nối trở lại với không gian ven sông.","audioKind":"ex2"}],"collocations":[{"en":"along the quay","vi":"dọc theo bến tàu"},{"en":"moor at the quay","vi":"neo đậu tại bến tàu"},{"en":"quay wall","vi":"tường bến tàu"}],"wordFamily":["quayside (n.)"],"synonyms":["wharf"],"antonyms":[],"tipVi":"Phát âm giống từ key; thường chỉ bến cấu trúc kiên cố nằm dọc theo mặt nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_panoramic', 'en-c1-5', 'panoramic', '/ˌpænəˈræmɪk/', 'C1', 'toàn cảnh; bao quát', 'adj.', 'panorama (n.)', NULL, 'Thường bổ nghĩa cho từ view, nhấn mạnh khả năng quan sát không gian rộng lớn xung quanh.', 'Our balcony offers panoramic views of the harbour.', NULL, 'Ban công nhà chúng tôi có tầm nhìn bao quát toàn bộ khung cảnh bến cảng.', '{"wordId":"panoramic","ukIpa":"/ˌpænəˈræmɪk/","usIpa":"/ˌpænəˈræmɪk/","cefr":"C1","topic":"travel","senses":[{"pos":"adj.","en":"showing a wide view of a large surrounding area","vi":"toàn cảnh; bao quát"}],"examples":[{"en":"Our balcony offers panoramic views of the harbour.","vi":"Ban công nhà chúng tôi có tầm nhìn bao quát toàn bộ khung cảnh bến cảng.","audioKind":"ex"},{"en":"Hotels with panoramic coastal views can attract tourists while increasing pressure on sensitive marine environments.","vi":"Các khách sạn có tầm nhìn bao quát hướng biển có thể thu hút khách du lịch nhưng đồng thời cũng làm tăng áp lực lên các hệ sinh thái biển nhạy cảm.","audioKind":"ex2"}],"collocations":[{"en":"panoramic view","vi":"tầm nhìn toàn cảnh"},{"en":"panoramic photograph","vi":"bức ảnh toàn cảnh"},{"en":"panoramic windows","vi":"khung cửa sổ toàn cảnh"}],"wordFamily":["panorama (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường bổ nghĩa cho từ view, nhấn mạnh khả năng quan sát không gian rộng lớn xung quanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_navigable', 'en-c1-5', 'navigable', '/ˈnævɪɡəbəl/', 'C1', 'có thể qua lại được; tàu bè qua lại được; dễ định hướng; dễ điều hướng; dễ tra cứu', 'adj.', 'navigate (v.), navigation (n.), navigator (n.)', 'Trái nghĩa: unnavigable', 'Thường dùng để mô tả sông ngòi hoặc tuyến đường thủy; từ ''seaworthy'' được dùng cho tàu thuyền đủ điều kiện đi biển.', 'The river is only navigable during the rainy season.', NULL, 'Con sông này chỉ có thể cho tàu bè qua lại vào mùa mưa.', '{"wordId":"navigable","ukIpa":"/ˈnævɪɡəbəl/","usIpa":"/ˈnævɪɡəbəl/","cefr":"C1","topic":"travel","senses":[{"pos":"adj.","en":"Deep and wide enough for boats or ships to travel through.","vi":"có thể qua lại được; tàu bè qua lại được"},{"pos":"adj.","en":"Possible or easy to find your way through.","vi":"dễ định hướng; dễ điều hướng; dễ tra cứu"}],"examples":[{"en":"The river is only navigable during the rainy season.","vi":"Con sông này chỉ có thể cho tàu bè qua lại vào mùa mưa.","audioKind":"ex"},{"en":"A clearly organised and easily navigable website can improve access to essential public services.","vi":"Một trang web được tổ chức rõ ràng và dễ dàng tra cứu có thể giúp người dân tiếp cận tốt hơn với các dịch vụ công cộng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"navigable river","vi":"sông có thể thông thuyền"},{"en":"navigable waterways","vi":"đường thủy có thể lưu thông"},{"en":"easily navigable website","vi":"trang web dễ tra cứu"}],"wordFamily":["navigate (v.)","navigation (n.)","navigator (n.)"],"synonyms":[],"antonyms":["unnavigable"],"tipVi":"Thường dùng để mô tả sông ngòi hoặc tuyến đường thủy; từ ''seaworthy'' được dùng cho tàu thuyền đủ điều kiện đi biển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stow', 'en-c1-5', 'stow', '/stoʊ/', 'C1', 'cất giữ an toàn; thu dọn gọn gàng', 'v.', 'stowage (n.), stowaway (n.)', 'Đồng nghĩa: store, pack away', 'stow away có thể mang nghĩa cất gọn; khi dùng với chủ ngữ là người, nó cũng có thể chỉ hành động trốn vé hoặc lén lút đi nhờ.', 'Please stow your bag under the seat in front.', NULL, 'Xin vui lòng cất túi xách của bạn xuống dưới ghế phía trước.', '{"wordId":"stow","ukIpa":"/stəʊ/","usIpa":"/stoʊ/","cefr":"C1","topic":"travel","senses":[{"pos":"v.","en":"put something safely away, especially for a journey","vi":"cất giữ an toàn; thu dọn gọn gàng"}],"examples":[{"en":"Please stow your bag under the seat in front.","vi":"Xin vui lòng cất túi xách của bạn xuống dưới ghế phía trước.","audioKind":"ex"},{"en":"Passengers must stow their luggage securely so that loose items do not cause injuries during unexpected turbulence.","vi":"Hành khách phải cất giữ hành lý chắc chắn để các vật dụng rời không gây chấn thương trong các trường hợp bất ngờ bị xóc.","audioKind":"ex2"}],"collocations":[{"en":"stow luggage","vi":"cất giữ hành lý"},{"en":"stow something away","vi":"cất gọn vật gì đó"},{"en":"stow securely","vi":"cất giữ chắc chắn"}],"wordFamily":["stowage (n.)","stowaway (n.)"],"synonyms":["store","pack away"],"antonyms":[],"tipVi":"stow away có thể mang nghĩa cất gọn; khi dùng với chủ ngữ là người, nó cũng có thể chỉ hành động trốn vé hoặc lén lút đi nhờ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swerve', 'en-c1-5', 'swerve', '/swɝːv/', 'C1', 'đổi hướng đột ngột, bẻ lái gấp; cú bẻ lái đột ngột, sự đổi hướng gấp', 'v.', NULL, 'Đồng nghĩa: veer', 'Nhấn mạnh việc thay đổi hướng đi một cách bất ngờ; việc rẽ thông thường dùng turn.', 'The cyclist swerved to avoid a branch on the road.', NULL, 'Người đi xe đạp đã bẻ lái đột ngột để tránh một cành cây trên đường.', '{"wordId":"swerve","ukIpa":"/swɜːv/","usIpa":"/swɝːv/","cefr":"C1","topic":"travel","senses":[{"pos":"v.","en":"To change direction suddenly, especially to avoid hitting something.","vi":"đổi hướng đột ngột, bẻ lái gấp"},{"pos":"n.","en":"A sudden change of direction by a vehicle or person.","vi":"cú bẻ lái đột ngột, sự đổi hướng gấp"}],"examples":[{"en":"The cyclist swerved to avoid a branch on the road.","vi":"Người đi xe đạp đã bẻ lái đột ngột để tránh một cành cây trên đường.","audioKind":"ex"},{"en":"Poorly maintained roads may force drivers to swerve unexpectedly, increasing the risk of collisions with other vehicles.","vi":"Những con đường bảo trì kém có thể buộc tài xế phải đánh lái bất ngờ, làm tăng nguy cơ va chạm với các phương tiện khác.","audioKind":"ex2"}],"collocations":[{"en":"swerve to avoid something","vi":"bẻ lái để tránh vật gì"},{"en":"swerve off the road","vi":"chệch hướng khỏi đường"},{"en":"a sudden swerve","vi":"cú đổi hướng đột ngột"}],"wordFamily":[],"synonyms":["veer"],"antonyms":[],"tipVi":"Nhấn mạnh việc thay đổi hướng đi một cách bất ngờ; việc rẽ thông thường dùng turn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aviation', 'en-c1-5', 'aviation', '/ˌeɪviˈeɪʃən/', 'C1', 'hàng không; ngành hàng không', 'n.', 'aviator (n.)', NULL, 'Là danh từ không đếm được, thường chỉ các hoạt động bay hoặc toàn bộ ngành hàng không.', 'Her interest in aviation began with a flying lesson.', NULL, 'Niềm đam mê hàng không của cô ấy bắt đầu từ một bài học lái máy bay.', '{"wordId":"aviation","ukIpa":"/ˌeɪviˈeɪʃən/","usIpa":"/ˌeɪviˈeɪʃən/","cefr":"C1","topic":"travel","senses":[{"pos":"n.","en":"The activity or industry of flying and operating aircraft.","vi":"hàng không; ngành hàng không"}],"examples":[{"en":"Her interest in aviation began with a flying lesson.","vi":"Niềm đam mê hàng không của cô ấy bắt đầu từ một bài học lái máy bay.","audioKind":"ex"},{"en":"The aviation industry faces pressure to reduce emissions while meeting growing demand for international travel.","vi":"Ngành hàng không đang phải đối mặt với áp lực vừa phải giảm lượng khí thải vừa phải đáp ứng nhu cầu du lịch quốc tế ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"civil aviation","vi":"hàng không dân dụng"},{"en":"aviation industry","vi":"ngành hàng không"},{"en":"aviation safety","vi":"an toàn hàng không"}],"wordFamily":["aviator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được, thường chỉ các hoạt động bay hoặc toàn bộ ngành hàng không.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_5_1', 'en-c1-5', 'Cách dùng “stow” (v.) — cất giữ an toàn; thu dọn gọn gàng', 'stow luggage  ·  stow something away  ·  stow securely', 'stow away có thể mang nghĩa cất gọn; khi dùng với chủ ngữ là người, nó cũng có thể chỉ hành động trốn vé hoặc lén lút đi nhờ.', 'Họ từ (Word Family): stowage (n.), stowaway (n.) | Đồng nghĩa: store, pack away', '[{"hanzi":"Please stow your bag under the seat in front.","pinyin":"","meaning":"Xin vui lòng cất túi xách của bạn xuống dưới ghế phía trước."},{"hanzi":"Passengers must stow their luggage securely so that loose items do not cause injuries during unexpected turbulence.","pinyin":"","meaning":"Hành khách phải cất giữ hành lý chắc chắn để các vật dụng rời không gây chấn thương trong các trường hợp bất ngờ bị xóc."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_5_2', 'en-c1-5', 'Cách dùng “navigable” (adj.) — có thể qua lại được; tàu bè qua lại được', 'navigable river  ·  navigable waterways  ·  easily navigable website', 'Thường dùng để mô tả sông ngòi hoặc tuyến đường thủy; từ ''seaworthy'' được dùng cho tàu thuyền đủ điều kiện đi biển.', 'Họ từ (Word Family): navigate (v.), navigation (n.), navigator (n.) | Trái nghĩa: unnavigable', '[{"hanzi":"The river is only navigable during the rainy season.","pinyin":"","meaning":"Con sông này chỉ có thể cho tàu bè qua lại vào mùa mưa."},{"hanzi":"A clearly organised and easily navigable website can improve access to essential public services.","pinyin":"","meaning":"Một trang web được tổ chức rõ ràng và dễ dàng tra cứu có thể giúp người dân tiếp cận tốt hơn với các dịch vụ công cộng thiết yếu."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_5_3', 'en-c1-5', 'Cách dùng “bazaar” (n.) — chợ; khu mua sắm (nhiều cửa hàng/quầy hàng nhỏ)', 'a bustling bazaar  ·  a charity bazaar  ·  a covered bazaar', 'Thường chỉ khu chợ truyền thống gồm nhiều gian hàng, hoặc cũng có thể chỉ một sự kiện bán hàng gây quỹ từ thiện.', 'Đồng nghĩa: market, marketplace', '[{"hanzi":"We bought fragrant spices at the crowded bazaar.","pinyin":"","meaning":"Chúng tôi đã mua những loại gia vị thơm nức mũi tại khu chợ đông đúc."},{"hanzi":"Traditional bazaars can attract tourists while providing local craftspeople with opportunities to sell their products directly.","pinyin":"","meaning":"Các khu chợ truyền thống vừa có thể thu hút khách du lịch vừa tạo cơ hội cho các nghệ nhân địa phương trực tiếp bán sản phẩm của họ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_5_4', 'en-c1-5', 'Cách dùng “traverse” (v.) — đi qua; vượt qua', 'traverse a valley  ·  traverse rough terrain  ·  traverse a continent', 'Đây là từ dùng trong văn phong trang trọng, đi trực tiếp với tân ngữ chỉ địa điểm: traverse the desert.', 'Họ từ (Word Family): traversal (n.) | Đồng nghĩa: cross', '[{"hanzi":"We traversed the snowy valley before reaching the mountain hut.","pinyin":"","meaning":"Chúng tôi đã vượt qua thung lũng đầy tuyết trước khi đến được căn lều trên núi."},{"hanzi":"New railway routes traverse remote regions, connecting isolated communities with essential services and larger markets.","pinyin":"","meaning":"Các tuyến đường sắt mới chạy xuyên qua các vùng5050xemlai_bien_tap_lai_cho_chuan_xac_hoac_dung_tieu_chuan_viet_sach. Các tuyến đường sắt mới xuyên qua các vùng xa xôi, kết nối các cộng đồng biệt lập với các dịch vụ thiết yếu và thị trường lớn hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_5_1', 'en-c1-5', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
