INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_5_1_8', 'ten_c1_5_1', 'nautical', 'My uncle collects old nautical maps and wooden boats.', 'My uncle collects old nautical maps and wooden boats.', '/ˈnɔːtɪkəl/', 'Chú tôi sưu tập những tấm bản đồ hàng hải cổ và các mô hình thuyền gỗ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_5_1_1', 'en-c1-5', 'ten_c1_5_1', 'listening', 'listening', 'A large fishing vessel sailed slowly into the harbour.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đứng trên bến tàu bằng đá ngắm chiếc phà cập bến.","Chú tôi sưu tập những tấm bản đồ hàng hải cổ và các mô hình thuyền gỗ.","Một chiếc tàu cá lớn từ từ tiến vào vũng tàu.","Ông bà tôi đã thực hiện một chuyến hành hương lên ngôi chùa trên núi."]'::jsonb, 2, 'A large fishing vessel sailed slowly into the harbour. → Một chiếc tàu cá lớn từ từ tiến vào vũng tàu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_5_1_2', 'en-c1-5', 'ten_c1_5_1', 'listening', 'listening', 'A white sail fluttered high on the wooden mast.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã mua những loại gia vị thơm nức mũi tại khu chợ đông đúc.","Một cánh buồm trắng phấp phới ở tầm cao trên cột buồm bằng gỗ.","Một chiếc sà lan chở đầy cát chạy qua dưới gầm cầu.","Niềm đam mê hàng không của cô ấy bắt đầu từ một bài học lái máy bay."]'::jsonb, 1, 'A white sail fluttered high on the wooden mast. → Một cánh buồm trắng phấp phới ở tầm cao trên cột buồm bằng gỗ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_5_1_3', 'en-c1-5', 'ten_c1_5_1', 'listening', 'listening', 'We roamed through the market until our feet hurt.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi ngắm nhìn quả khinh khí cầu từ từ bay lên bầu trời trong xanh.","Ban công nhà chúng tôi có tầm nhìn bao quát toàn bộ khung cảnh bến cảng.","Chúng tôi đi lang thang qua khu chợ cho đến khi đau cả chân.","Một cánh buồm trắng phấp phới ở tầm cao trên cột buồm bằng gỗ."]'::jsonb, 2, 'We roamed through the market until our feet hurt. → Chúng tôi đi lang thang qua khu chợ cho đến khi đau cả chân.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_5_2', 'en-c1-5', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_5_2_1', 'ten_c1_5_2', 'vessel', 'Commercial vessels can disturb marine ecosystems through underwater noise, fuel leaks, and the introduction of non-native species.', 'Commercial vessels can disturb marine ecosystems through underwater noise, fuel leaks, and the introduction of non-native species.', '/ˈvesəl/', 'Các tàu thương mại có thể làm xáo trộn hệ sinh thái biển thông qua tiếng ồn dưới nước, rò rỉ nhiên liệu và sự xâm nhập của các loài ngoại lai.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_5_2_2', 'ten_c1_5_2', 'mast', 'Installing a new communications mast could improve mobile coverage in remote villages and support local businesses.', 'Installing a new communications mast could improve mobile coverage in remote villages and support local businesses.', '/mæst/', 'Việc lắp đặt một cột thông tin liên lạc mới có thể cải thiện độ phủ sóng di động ở các ngôi làng vùng sâu vùng xa và hỗ trợ các doanh nghiệp địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_5_2_3', 'ten_c1_5_2', 'roam', 'Protected wildlife corridors allow large animals to roam freely between habitats without crossing busy roads.', 'Protected wildlife corridors allow large animals to roam freely between habitats without crossing busy roads.', '/roʊm/', 'Các hành lang động vật hoang dã được bảo vệ cho phép các loài thú lớn tự do di chuyển giữa các sinh cảnh mà không phải băng qua những con đường đông đúc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_5_2_4', 'ten_c1_5_2', 'barge', 'Transporting construction materials by barge can reduce the number of heavy vehicles travelling through crowded urban areas.', 'Transporting construction materials by barge can reduce the number of heavy vehicles travelling through crowded urban areas.', '/bɑːrdʒ/', 'Việc vận chuyển vật liệu xây dựng bằng sà lan có thể làm giảm số lượng xe tải hạng nặng di chuyển qua các khu đô thị đông đúc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_5_2_5', 'ten_c1_5_2', 'traverse', 'New railway routes traverse remote regions, connecting isolated communities with essential services and larger markets.', 'New railway routes traverse remote regions, connecting isolated communities with essential services and larger markets.', '/trəˈvɝːs/', 'Các tuyến đường sắt mới chạy xuyên qua các vùng5050xemlai_bien_tap_lai_cho_chuan_xac_hoac_dung_tieu_chuan_viet_sach. Các tuyến đường sắt mới xuyên qua các vùng xa xôi, kết nối các cộng đồng biệt lập với các dịch vụ thiết yếu và thị trường lớn hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_5_2_6', 'ten_c1_5_2', 'ascend', 'As hikers ascend the mountain, they encounter distinct vegetation zones shaped by changing temperatures and moisture levels.', 'As hikers ascend the mountain, they encounter distinct vegetation zones shaped by changing temperatures and moisture levels.', '/əˈsend/', 'Khi những người leo núi tiến lên đỉnh, họ bắt gặp các vành đai thực vật khác nhau được định hình bởi sự thay đổi của nhiệt độ và độ ẩm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_5_2_1', 'en-c1-5', 'ten_c1_5_2', 'listening', 'listening', 'Commercial vessels can disturb marine ecosystems through underwater noise, fuel leaks, and the introduction of non-native species.', NULL, 'Trong câu vừa nghe, từ “vessel” mang nghĩa nào sau đây?', '["sự nổi bật; tầm quan trọng; sự nổi tiếng","thuyền lớn; tàu thủy","sự chiếm ưu thế; vị thế thống trị","mang tính di truyền"]'::jsonb, 1, '“vessel” (/ˈvesəl/): thuyền lớn; tàu thủy. Câu đầy đủ: Commercial vessels can disturb marine ecosystems through underwater noise, fuel leaks, and the introduction of non-native species.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_5_2_2', 'en-c1-5', 'ten_c1_5_2', 'listening', 'listening', 'Installing a new communications mast could improve mobile coverage in remote villages and support local businesses.', NULL, 'Trong câu vừa nghe, từ “mast” mang nghĩa nào sau đây?', '["cột buồm","người hòa giải; trọng tài; trung gian","tái xuất khẩu; chuyển khẩu","tính đều đặn; tính quy luật; sự định kỳ"]'::jsonb, 0, '“mast” (/mæst/): cột buồm. Câu đầy đủ: Installing a new communications mast could improve mobile coverage in remote villages and support local businesses.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
