INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_1', 'en-c1-5', NULL, 'comprehensive_test', 'listening', 'vessel', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuyền lớn; tàu thủy","lời nói đầu; lời tựa; phần mở đầu","cuộc khởi nghĩa; cuộc nổi dậy","thuộc về nguyên thủy; bản địa; thổ dân"]'::jsonb, 0, 'vessel (/ˈvesəl/) → thuyền lớn; tàu thủy; mạch máu; mạch dẫn; bình; lọ; chậu chứa chất lỏng', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_2', 'en-c1-5', NULL, 'comprehensive_test', 'listening', 'A white sail fluttered high on the wooden mast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đứng trên bến tàu bằng đá ngắm chiếc phà cập bến.","Người đi xe đạp đã bẻ lái đột ngột để tránh một cành cây trên đường.","Chúng tôi đã mua những loại gia vị thơm nức mũi tại khu chợ đông đúc.","Một cánh buồm trắng phấp phới ở tầm cao trên cột buồm bằng gỗ."]'::jsonb, 3, 'A white sail fluttered high on the wooden mast. → Một cánh buồm trắng phấp phới ở tầm cao trên cột buồm bằng gỗ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_3', 'en-c1-5', NULL, 'comprehensive_test', 'listening', 'roam', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự an ủi; niềm khuây khỏa","lang thang; đi lang thang; thả bộ","trở ngại bất ngờ; khó khăn nhỏ","có thể thương lượng; có thể thỏa thuận"]'::jsonb, 1, 'roam (/roʊm/) → lang thang; đi lang thang; thả bộ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_4', 'en-c1-5', NULL, 'comprehensive_test', 'listening', 'A barge loaded with sand passed beneath the bridge.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã mua những loại gia vị thơm nức mũi tại khu chợ đông đúc.","Một chiếc sà lan chở đầy cát chạy qua dưới gầm cầu.","Chúng tôi đã vượt qua thung lũng đầy tuyết trước khi đến được căn lều trên núi.","Chú tôi sưu tập những tấm bản đồ hàng hải cổ và các mô hình thuyền gỗ."]'::jsonb, 1, 'A barge loaded with sand passed beneath the bridge. → Một chiếc sà lan chở đầy cát chạy qua dưới gầm cầu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_5', 'en-c1-5', NULL, 'comprehensive_test', 'listening', 'traverse', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đi qua; vượt qua","tạm thời; chưa chính thức","làm cho ai đó không thể hiểu hoặc giải thích được điều gì; gây bối rối, làm khó","an-pe"]'::jsonb, 0, 'traverse (/trəˈvɝːs/) → đi qua; vượt qua', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_6', 'en-c1-5', NULL, 'comprehensive_test', 'listening', 'We watched the balloon ascend slowly into the clear sky.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ngắm nhìn quả khinh khí cầu từ từ bay lên bầu trời trong xanh.","Một chiếc tàu cá lớn từ từ tiến vào vũng tàu.","Niềm đam mê hàng không của cô ấy bắt đầu từ một bài học lái máy bay.","Một chiếc sà lan chở đầy cát chạy qua dưới gầm cầu."]'::jsonb, 0, 'We watched the balloon ascend slowly into the clear sky. → Chúng tôi ngắm nhìn quả khinh khí cầu từ từ bay lên bầu trời trong xanh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_7', 'en-c1-5', NULL, 'comprehensive_test', 'listening', 'bazaar', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quyền thuê nhà; thỏa thuận thuê tài sản","chợ; khu mua sắm (nhiều cửa hàng/quầy hàng nhỏ)","sự ca ngợi; tiếngvang","gắn chặt vào; làm chìm sâu vào"]'::jsonb, 1, 'bazaar (/bəˈzɑːr/) → chợ; khu mua sắm (nhiều cửa hàng/quầy hàng nhỏ); phiên chợ từ thiện; hội chợ từ thiện', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_8', 'en-c1-5', NULL, 'comprehensive_test', 'listening', 'My uncle collects old nautical maps and wooden boats.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chú tôi sưu tập những tấm bản đồ hàng hải cổ và các mô hình thuyền gỗ.","Một cánh buồm trắng phấp phới ở tầm cao trên cột buồm bằng gỗ.","Người đi xe đạp đã bẻ lái đột ngột để tránh một cành cây trên đường.","Con sông này chỉ có thể cho tàu bè qua lại vào mùa mưa."]'::jsonb, 0, 'My uncle collects old nautical maps and wooden boats. → Chú tôi sưu tập những tấm bản đồ hàng hải cổ và các mô hình thuyền gỗ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_9', 'en-c1-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To travel across or through an area.”?', '["traverse","navigable","pilgrimage","quay"]'::jsonb, 0, 'traverse (/trəˈvɝːs/) → đi qua; vượt qua', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_10', 'en-c1-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to move upwards or rise to a higher position”?', '["barge","ascend","navigable","swerve"]'::jsonb, 1, 'ascend (/əˈsend/) → đi lên; bay lên; nâng lên vị trí cao hơn', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_11', 'en-c1-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a market with many small shops or stalls”?', '["navigable","bazaar","roam","swerve"]'::jsonb, 1, 'bazaar (/bəˈzɑːr/) → chợ; khu mua sắm (nhiều cửa hàng/quầy hàng nhỏ)', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_12', 'en-c1-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Relating to ships, sailing, or navigation at sea”?', '["vessel","roam","nautical","navigable"]'::jsonb, 2, 'nautical (/ˈnɔːtɪkəl/) → thuộc về hàng hải; thuộc về tàu thuyền', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_13', 'en-c1-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A journey to a place important to someone''s religion.”?', '["mast","panoramic","quay","pilgrimage"]'::jsonb, 3, 'pilgrimage (/ˈpɪlɡrɪmɪdʒ/) → chuyến đi hành hương', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
