INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_18', 'en-c1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Commercial vessels can disturb marine ecosystems through underwater noise, fuel leaks, and the introduction of non-native species.', 'Dựa vào câu trên, từ “vessel” có nghĩa phù hợp nhất là gì?', '["áp dụng; thi hành","phương pháp nghiên cứu; hệ thống phương pháp","thuyền lớn; tàu thủy","thống nhất; hợp nhất; gắn kết"]'::jsonb, 2, 'vessel: thuyền lớn; tàu thủy; mạch máu; mạch dẫn; bình; lọ; chậu chứa chất lỏng. Dịch cả câu: Các tàu thương mại có thể làm xáo trộn hệ sinh thái biển thông qua tiếng ồn dưới nước, rò rỉ nhiên liệu và sự xâm nhập của các loài ngoại lai.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_19', 'en-c1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Installing a new communications mast could improve mobile coverage in remote villages and support local businesses.', 'Dựa vào câu trên, từ “mast” có nghĩa phù hợp nhất là gì?', '["cột buồm","ngụy biện; quan niệm sai lầm","mang tính cao trào; đạt đến đỉnh điểm","súng cầm tay; vũ khí hỏa khí"]'::jsonb, 0, 'mast: cột buồm; cột ăng-ten; trụ phát sóng. Dịch cả câu: Việc lắp đặt một cột thông tin liên lạc mới có thể cải thiện độ phủ sóng di động ở các ngôi làng vùng sâu vùng xa và hỗ trợ các doanh nghiệp địa phương.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_20', 'en-c1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Protected wildlife corridors allow large animals to roam freely between habitats without crossing busy roads.', 'Dựa vào câu trên, từ “roam” có nghĩa phù hợp nhất là gì?', '["lang thang; đi lang thang; thả bộ","sự ô nhục; sự mất thể diện; tiếng nhơ","mù chữ; không biết đọc biết viết","bao quanh; vây quanh"]'::jsonb, 0, 'roam: lang thang; đi lang thang; thả bộ. Dịch cả câu: Các hành lang động vật hoang dã được bảo vệ cho phép các loài thú lớn tự do di chuyển giữa các sinh cảnh mà không phải băng qua những con đường đông đúc.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_21', 'en-c1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Transporting construction materials by barge can reduce the number of heavy vehicles travelling through crowded urban areas.', 'Dựa vào câu trên, từ “barge” có nghĩa phù hợp nhất là gì?', '["thuyền chở hàng đáy bằng; sà lan","tuân thủ; tuân theo","sự đồng thuận; ý kiến chung","tinh tế; khó nhận thấy"]'::jsonb, 0, 'barge: thuyền chở hàng đáy bằng; sà lan; xông vào; va quẹt thô bạo. Dịch cả câu: Việc vận chuyển vật liệu xây dựng bằng sà lan có thể làm giảm số lượng xe tải hạng nặng di chuyển qua các khu đô thị đông đúc.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_22', 'en-c1-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cất giữ an toàn; thu dọn gọn gàng”', '["stow","competitiveness","embroider","dubious"]'::jsonb, 0, 'cất giữ an toàn; thu dọn gọn gàng → stow (/stoʊ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_23', 'en-c1-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đổi hướng đột ngột, bẻ lái gấp”', '["upkeep","gullible","swerve","amiable"]'::jsonb, 2, 'đổi hướng đột ngột, bẻ lái gấp → swerve (/swɝːv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_5_24', 'en-c1-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hàng không; ngành hàng không”', '["aviation","inflammable","lubricate","collaborate"]'::jsonb, 0, 'hàng không; ngành hàng không → aviation (/ˌeɪviˈeɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-6', 'en', 'Bài 6: Xã hội & Cộng đồng (1) - CEFR C1', 'CEFR C1', 'C1 · Xã hội', '28 từ vựng Tiếng Anh CEFR C1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5006, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cohesive', 'en-c1-6', 'cohesive', '/koʊˈhiːsɪv/', 'C1', 'có tính gắn kết chặt chẽ, đoàn kết', 'adj.', 'cohesion (n.), cohesiveness (n.), cohesively (adv.)', 'Đồng nghĩa: united, integrated · Trái nghĩa: fragmented, divided', 'cohesive nhấn mạnh sự liên kết chặt chẽ; coherent nhấn mạnh tính logic, rành mạch rõ ràng.', 'Regular practice helped us become a more cohesive team.', NULL, 'Việc luyện tập thường xuyên đã giúp chúng tôi trở thành một đội ngũ có tính gắn kết cao hơn.', '{"wordId":"cohesive","ukIpa":"/kəʊˈhiːsɪv/","usIpa":"/koʊˈhiːsɪv/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"united or closely connected as a whole","vi":"có tính gắn kết chặt chẽ, đoàn kết"}],"examples":[{"en":"Regular practice helped us become a more cohesive team.","vi":"Việc luyện tập thường xuyên đã giúp chúng tôi trở thành một đội ngũ có tính gắn kết cao hơn.","audioKind":"ex"},{"en":"Shared public spaces can help build cohesive communities by encouraging interaction among people from different backgrounds.","vi":"Không gian công cộng chung có thể giúp xây dựng các cộng đồng gắn kết bằng cách khuyến khích sự tương tác giữa những người có hoàn cảnh khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"cohesive team","vi":"đội ngũ gắn kết"},{"en":"cohesive society","vi":"xã hội đoàn kết"},{"en":"cohesive argument","vi":"lập luận chặt chẽ, mạch lạc"}],"wordFamily":["cohesion (n.)","cohesiveness (n.)","cohesively (adv.)"],"synonyms":["united","integrated"],"antonyms":["fragmented","divided"],"tipVi":"cohesive nhấn mạnh sự liên kết chặt chẽ; coherent nhấn mạnh tính logic, rành mạch rõ ràng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manipulation', 'en-c1-6', 'manipulation', '/məˌnɪpjəˈleɪʃən/', 'C1', 'sự thao túng; sự điều khiển (kiểm soát con người hoặc tình huống một cách không công bằng vì lợi ích cá nhân); sự vận dụng; sự thao tác (di chuyển hoặc điều chỉnh cái gì đó một cách cẩn thận, thường dùng tay hoặc công cụ)', 'n.', 'manipulate (v.), manipulative (adj.), manipulator (n.)', NULL, 'Khi dùng để chỉ việc thao túng con người thường mang nghĩa xấu; khi chỉ thao tác công cụ thì có tính trung lập.', 'She recognised his emotional manipulation and refused to feel guilty.', NULL, 'Cô ấy nhận ra thủ đoạn thao túng cảm xúc của anh ta và từ chối cảm thấy có lỗi.', '{"wordId":"manipulation","ukIpa":"/məˌnɪpjʊˈleɪʃən/","usIpa":"/məˌnɪpjəˈleɪʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Controlling people or situations unfairly for personal advantage.","vi":"sự thao túng; sự điều khiển (kiểm soát con người hoặc tình huống một cách không công bằng vì lợi ích cá nhân)"},{"pos":"n.","en":"Moving or adjusting something carefully, often using hands or tools.","vi":"sự vận dụng; sự thao tác (di chuyển hoặc điều chỉnh cái gì đó một cách cẩn thận, thường dùng tay hoặc công cụ)"}],"examples":[{"en":"She recognised his emotional manipulation and refused to feel guilty.","vi":"Cô ấy nhận ra thủ đoạn thao túng cảm xúc của anh ta và từ chối cảm thấy có lỗi.","audioKind":"ex"},{"en":"The manipulation of survey results can mislead policymakers and reduce public trust in scientific research.","vi":"Việc thao túng kết quả khảo sát có thể làm các nhà hoạch định chính sách hiểu sai và làm giảm lòng tin của công chúng vào nghiên cứu khoa học.","audioKind":"ex2"}],"collocations":[{"en":"emotional manipulation","vi":"thao túng cảm xúc"},{"en":"data manipulation","vi":"xử lý dữ liệu; thao túng dữ liệu"},{"en":"market manipulation","vi":"thao túng thị trường"}],"wordFamily":["manipulate (v.)","manipulative (adj.)","manipulator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng để chỉ việc thao túng con người thường mang nghĩa xấu; khi chỉ thao tác công cụ thì có tính trung lập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flatter', 'en-c1-6', 'flatter', '/ˈflætər/', 'C1', 'nịnh hót; nịnh bợ (ca ngợi ai đó, thường là không thành thật, để lấy lòng); làm cho hãnh diện; làm cho vinh hạnh (kém theo sự quan tâm hoặc lời khen khiến ai đó cảm thấy vui); làm cho tôn dáng; làm cho đẹp hơn (làm cho ai đó trông hấp dẫn hơn thực tế)', 'v.', 'flattery (n.), flattering (adj.), flattered (adj.), flatterer (n.)', NULL, 'Cụm be flattered thường chỉ cảm giác vinh hạnh, không nhất thiết mang nghĩa chê bai.', 'That blue jacket really flatters you in this light.', NULL, 'Chiếc áo khoác xanh đó thực sự rất tôn dáng bạn dưới ánh sáng này.', '{"wordId":"flatter","ukIpa":"/ˈflætə/","usIpa":"/ˈflætər/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"Praise someone, often insincerely, to gain their favour.","vi":"nịnh hót; nịnh bợ (ca ngợi ai đó, thường là không thành thật, để lấy lòng)"},{"pos":"v.","en":"Make someone feel pleased or honoured through attention or praise.","vi":"làm cho hãnh diện; làm cho vinh hạnh (kém theo sự quan tâm hoặc lời khen khiến ai đó cảm thấy vui)"},{"pos":"v.","en":"Make someone look more attractive than they otherwise would.","vi":"làm cho tôn dáng; làm cho đẹp hơn (làm cho ai đó trông hấp dẫn hơn thực tế)"}],"examples":[{"en":"That blue jacket really flatters you in this light.","vi":"Chiếc áo khoác xanh đó thực sự rất tôn dáng bạn dưới ánh sáng này.","audioKind":"ex"},{"en":"Advertisements often flatter consumers by suggesting that choosing a particular product demonstrates intelligence or good taste.","vi":"Quảng cáo thường nịnh bợ người tiêu dùng bằng cách gợi ý rằng việc chọn một sản phẩm cụ thể thể hiện sự thông minh hoặc gu thẩm mỹ tốt.","audioKind":"ex2"}],"collocations":[{"en":"flatter someone''s ego","vi":"thỏa mãn sự hư vinh của ai đó"},{"en":"feel flattered","vi":"cảm thấy vinh hạnh"},{"en":"flatter yourself","vi":"tự cao tự đại; tự mãn"}],"wordFamily":["flattery (n.)","flattering (adj.)","flattered (adj.)","flatterer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm be flattered thường chỉ cảm giác vinh hạnh, không nhất thiết mang nghĩa chê bai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meddle', 'en-c1-6', 'meddle', '/ˈmedəl/', 'C1', 'can thiệp; xen vào', 'v.', 'meddling (adj.), meddler (n.)', 'Đồng nghĩa: interfere', 'Thường đi với in khi chỉ việc can thiệp vào chuyện gì; đi với with khi chỉ việc tự ý táy máy đồ vật.', 'Please don''t meddle in how I arrange my room.', NULL, 'Xin đừng can thiệp vào cách tôi sắp xếp phòng của mình.', '{"wordId":"meddle","ukIpa":"/ˈmedəl/","usIpa":"/ˈmedəl/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"Interfere in other people''s affairs without being invited.","vi":"can thiệp; xen vào"}],"examples":[{"en":"Please don''t meddle in how I arrange my room.","vi":"Xin đừng can thiệp vào cách tôi sắp xếp phòng của mình.","audioKind":"ex"},{"en":"Parents who constantly meddle in their children''s decisions may prevent them from developing confidence and independence.","vi":"Các bậc phụ huynh thường xuyên can thiệp vào quyết định của con cái có thể khiến trẻ khó phát triển sự tự tin và tính độc lập.","audioKind":"ex2"}],"collocations":[{"en":"meddle in someone''s affairs","vi":"can thiệp vào chuyện riêng của ai đó"},{"en":"meddle with something","vi":"tự ý táy máy vào cái gì"}],"wordFamily":["meddling (adj.)","meddler (n.)"],"synonyms":["interfere"],"antonyms":[],"tipVi":"Thường đi với in khi chỉ việc can thiệp vào chuyện gì; đi với with khi chỉ việc tự ý táy máy đồ vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_constitute', 'en-c1-6', 'constitute', '/ˈkɑːnstɪtuːt/', 'C1', 'cấu thành; tạo thành; được coi là; tạo nên; thành lập; thiết lập', 'v.', 'constitution (n.), constituent (n.), constitutional (adj.)', 'Đồng nghĩa: compose, form', 'Khi mang nghĩa cấu thành/tạo nên, phần nhỏ thường đóng vai trò chủ ngữ và tổng thể là tân ngữ.', 'Vegetables constitute most of the food in our fridge.', NULL, 'Rau củ chiếm phần lớn lượng thực phẩm trong tủ lạnh nhà chúng tôi.', '{"wordId":"constitute","ukIpa":"/ˈkɒnstɪtjuːt/","usIpa":"/ˈkɑːnstɪtuːt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To be the parts that form a whole","vi":"cấu thành; tạo thành"},{"pos":"v.","en":"To be considered a particular thing","vi":"được coi là; tạo nên"},{"pos":"v.","en":"To formally establish an organisation or governing body","vi":"thành lập; thiết lập"}],"examples":[{"en":"Vegetables constitute most of the food in our fridge.","vi":"Rau củ chiếm phần lớn lượng thực phẩm trong tủ lạnh nhà chúng tôi.","audioKind":"ex"},{"en":"Rising housing costs constitute a major barrier to financial independence for young adults in large cities.","vi":"Chi phí nhà ở gia tăng tạo thành một rào cản lớn đối với sự độc lập tài chính của thanh thiếu niên ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"constitute a majority","vi":"chiếm đa số"},{"en":"constitute a threat","vi":"cấu thành mối đe dọa"},{"en":"constitute a breach","vi":"cấu thành hành vi vi phạm"},{"en":"constitute a committee","vi":"thành lập một ủy ban"}],"wordFamily":["constitution (n.)","constituent (n.)","constitutional (adj.)"],"synonyms":["compose","form"],"antonyms":[],"tipVi":"Khi mang nghĩa cấu thành/tạo nên, phần nhỏ thường đóng vai trò chủ ngữ và tổng thể là tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_phony', 'en-c1-6', 'phony', '/ˈfoʊni/', 'C1', 'giả mạo; giả tạo; kẻ giả mạo; kẻ lừa đảo', 'adj.', 'phoniness (n.)', 'Đồng nghĩa: fake, bogus, insincere · Trái nghĩa: genuine, authentic', 'Mang văn phong khẩu ngữ; trong tiếng Anh - Anh thường được viết là phoney.', 'His phony smile disappeared as soon as we left.', NULL, 'Nụ cười giả tạo của anh ta biến mất ngay khi chúng tôi rời đi.', '{"wordId":"phony","ukIpa":"/ˈfəʊni/","usIpa":"/ˈfoʊni/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Not genuine, or intended to deceive people","vi":"giả mạo; giả tạo"},{"pos":"n.","en":"Someone who pretends to be something they are not","vi":"kẻ giả mạo; kẻ lừa đảo"}],"examples":[{"en":"His phony smile disappeared as soon as we left.","vi":"Nụ cười giả tạo của anh ta biến mất ngay khi chúng tôi rời đi.","audioKind":"ex"},{"en":"Consumers should be cautious about phony online reviews that exaggerate the benefits of health products.","vi":"Người tiêu dùng nên cảnh giác với các đánh giá trực tuyến giả mạo phóng đại công dụng của các sản phẩm chăm sóc sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"phony smile","vi":"nụ cười giả tạo"},{"en":"phony excuse","vi":"lời ngụy biện giả dối"},{"en":"phony claims","vi":"tuyên bố giả mạo"}],"wordFamily":["phoniness (n.)"],"synonyms":["fake","bogus","insincere"],"antonyms":["genuine","authentic"],"tipVi":"Mang văn phong khẩu ngữ; trong tiếng Anh - Anh thường được viết là phoney.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_microcosm', 'en-c1-6', 'microcosm', '/ˈmaɪkroʊkɑːzəm/', 'C1', 'hình thu nhỏ; thế giới thu nhỏ', 'n.', 'microcosmic (adj.)', 'Trái nghĩa: macrocosm', 'Thường dùng cấu trúc a microcosm of, chỉ hình thu nhỏ, không chỉ dùng cho các sự vật nhỏ bé.', 'Our busy kitchen is a microcosm of family life.', NULL, 'Căn bếp bận rộn của chúng tôi là hình thu nhỏ của đời sống gia đình.', '{"wordId":"microcosm","ukIpa":"/ˈmaɪkrəʊkɒzəm/","usIpa":"/ˈmaɪkroʊkɑːzəm/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A small system showing the features of a larger one.","vi":"hình thu nhỏ; thế giới thu nhỏ"}],"examples":[{"en":"Our busy kitchen is a microcosm of family life.","vi":"Căn bếp bận rộn của chúng tôi là hình thu nhỏ của đời sống gia đình.","audioKind":"ex"},{"en":"A diverse urban neighbourhood can serve as a microcosm of the wider society''s opportunities and challenges.","vi":"Một khu989 vực đô thị đa dạng có thể đóng vai trò là hình thu nhỏ của các cơ hội và thách thức trong xã hội rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"a microcosm of society","vi":"hình thu nhỏ của xã hội"},{"en":"in microcosm","vi":"dưới dạng thu nhỏ"},{"en":"serve as a microcosm","vi":"đóng vai trò là hình thu nhỏ"}],"wordFamily":["microcosmic (adj.)"],"synonyms":[],"antonyms":["macrocosm"],"tipVi":"Thường dùng cấu trúc a microcosm of, chỉ hình thu nhỏ, không chỉ dùng cho các sự vật nhỏ bé.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forgery', 'en-c1-6', 'forgery', '/ˈfɔːrdʒəri/', 'C1', 'sự làm giả; tài liệu giả; vật giả mạo', 'n.', 'forge (v.), forger (n.)', 'Đồng nghĩa: counterfeit, fake', 'forgery là hành vi làm giả hoặc vật giả mạo; còn xưởng rèn/lò rèn là forge.', 'The painting in the shop was a forgery.', NULL, 'Bức tranh trong cửa hàng hóa ra là một món đồ giả mạo.', '{"wordId":"forgery","ukIpa":"/ˈfɔːdʒəri/","usIpa":"/ˈfɔːrdʒəri/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Making illegal copies of documents or artworks; such a copy.","vi":"sự làm giả; tài liệu giả; vật giả mạo"}],"examples":[{"en":"The painting in the shop was a forgery.","vi":"Bức tranh trong cửa hàng hóa ra là một món đồ giả mạo.","audioKind":"ex"},{"en":"Museums employ specialists to detect forgery and protect the public from misleading claims about historical objects.","vi":"Các bảo tàng thuê chuyên gia để phát hiện hàng giả và bảo vệ công chúng khỏi những tuyên bố sai lệch về các hiện vật lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"document forgery","vi":"việc làm giả tài liệu"},{"en":"art forgery","vi":"làm giả tác phẩm nghệ thuật"},{"en":"detect a forgery","vi":"phát hiện hàng giả"},{"en":"a convincing forgery","vi":"bản sao giả mạo tinh vi"}],"wordFamily":["forge (v.)","forger (n.)"],"synonyms":["counterfeit","fake"],"antonyms":[],"tipVi":"forgery là hành vi làm giả hoặc vật giả mạo; còn xưởng rèn/lò rèn là forge.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deceit', 'en-c1-6', 'deceit', '/dɪˈsiːt/', 'C1', 'sự dối trá; hành vi lừa gạt', 'n.', 'deceive (v.), deceitful (adj.), deceitfully (adv.), deception (n.)', 'Đồng nghĩa: deception, dishonesty · Trái nghĩa: honesty', 'deceit thường không đếm được; một lần lừa dối có thể dùng an act of deceit.', 'His deceit became clear when we opened the empty box.', NULL, 'Sự dối trá của anh ta đã phơi bày khi chúng tôi mở chiếc hộp trống rỗng ra.', '{"wordId":"deceit","ukIpa":"/dɪˈsiːt/","usIpa":"/dɪˈsiːt/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Dishonest behaviour intended to make someone believe something false.","vi":"sự dối trá; hành vi lừa gạt"}],"examples":[{"en":"His deceit became clear when we opened the empty box.","vi":"Sự dối trá của anh ta đã phơi bày khi chúng tôi mở chiếc hộp trống rỗng ra.","audioKind":"ex"},{"en":"Deceit in advertising can damage consumer trust and create unfair advantages for companies that misrepresent their products.","vi":"Hành vi gian dối trong quảng cáo có thể làm tổn hại lòng tin của người tiêu dùng và tạo ra lợi thế không công bằng cho những công ty xuyên tạc về sản phẩm của họ.","audioKind":"ex2"}],"collocations":[{"en":"deliberate deceit","vi":"hành vi cố tình lừa dối"},{"en":"an act of deceit","vi":"một hành vi lừa gạt"},{"en":"lies and deceit","vi":"những lời dối trá và lừa lọc"}],"wordFamily":["deceive (v.)","deceitful (adj.)","deceitfully (adv.)","deception (n.)"],"synonyms":["deception","dishonesty"],"antonyms":["honesty"],"tipVi":"deceit thường không đếm được; một lần lừa dối có thể dùng an act of deceit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instrumental', 'en-c1-6', 'instrumental', '/ˌɪnstrəˈmentəl/', 'C1', 'có vai trò quan trọng; góp phần quyết định; thuộc về nhạc cụ; bản nhạc không lời', 'adj.', 'instrument (n.)', NULL, 'Khi diễn tả ý nghĩa "đóng vai trò quan trọng", hãy dùng cấu trúc be instrumental in doing.', 'Your advice was instrumental in helping me find work.', NULL, 'Lời khuyên của bạn đã đóng vai trò quan trọng giúp tôi tìm được việc làm.', '{"wordId":"instrumental","ukIpa":"/ˌɪnstrəˈmentəl/","usIpa":"/ˌɪnstrəˈmentəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"playing an important part in making something happen","vi":"có vai trò quan trọng; góp phần quyết định"},{"pos":"adj.","en":"performed with musical instruments rather than voices","vi":"thuộc về nhạc cụ"},{"pos":"n.","en":"a piece of music performed without singing","vi":"bản nhạc không lời"}],"examples":[{"en":"Your advice was instrumental in helping me find work.","vi":"Lời khuyên của bạn đã đóng vai trò quan trọng giúp tôi tìm được việc làm.","audioKind":"ex"},{"en":"Investment in public transport has been instrumental in reducing traffic congestion in several major cities.","vi":"Việc đầu tư vào giao thông công cộng đã đóng vai trò then chốt trong việc giảm thiểu tình trạng ùn tắc giao thông ở nhiều thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"be instrumental in","vi":"góp phần quan trọng trong việc"},{"en":"instrumental music","vi":"nhạc cụ"},{"en":"instrumental version","vi":"phiên bản không lời"}],"wordFamily":["instrument (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi diễn tả ý nghĩa \"đóng vai trò quan trọng\", hãy dùng cấu trúc be instrumental in doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exploitation', 'en-c1-6', 'exploitation', '/ˌeksplɔɪˈteɪʃən/', 'C1', 'sự bóc lột; sự áp bức; sự khai thác; sự tận dụng', 'n.', 'exploit (v.), exploitative (adj.), exploiter (n.)', NULL, 'Dùng cho con người thường mang nghĩa bóc lột; dùng cho tài nguyên mang nghĩa khai thác, cần căn cứ vào ngữ cảnh cụ thể.', 'The workers demanded fair wages and protection from exploitation.', NULL, 'Những người lao động yêu cầu mức lương công bằng và sự bảo vệ khỏi nạn bóc lột.', '{"wordId":"exploitation","ukIpa":"/ˌeksplɔɪˈteɪʃən/","usIpa":"/ˌeksplɔɪˈteɪʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Unfair treatment of people to gain benefits from their work","vi":"sự bóc lột; sự áp bức"},{"pos":"n.","en":"Using resources or opportunities to gain an advantage","vi":"sự khai thác; sự tận dụng"}],"examples":[{"en":"The workers demanded fair wages and protection from exploitation.","vi":"Những người lao động yêu cầu mức lương công bằng và sự bảo vệ khỏi nạn bóc lột.","audioKind":"ex"},{"en":"The uncontrolled exploitation of natural resources can damage ecosystems and undermine the livelihoods of communities that depend on them.","vi":"Việc khai thác tài nguyên thiên nhiên bừa bãi có thể tàn phá hệ sinh thái và làm suy kiệt sinh kế của các cộng đồng phụ thuộc vào chúng.","audioKind":"ex2"}],"collocations":[{"en":"labour exploitation","vi":"sự bóc lột sức lao động"},{"en":"commercial exploitation","vi":"sự khai thác thương mại"},{"en":"exploitation of natural resources","vi":"sự khai thác tài nguyên thiên nhiên"}],"wordFamily":["exploit (v.)","exploitative (adj.)","exploiter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng cho con người thường mang nghĩa bóc lột; dùng cho tài nguyên mang nghĩa khai thác, cần căn cứ vào ngữ cảnh cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prevailing', 'en-c1-6', 'prevailing', '/prɪˈveɪlɪŋ/', 'C1', 'phổ biến; thịnh hành; chiếm ưu thế', 'adj.', 'prevail (v.)', 'Đồng nghĩa: dominant, predominant', 'Thường đứng trước danh từ; prevailing wind có nghĩa là gió thịnh hành.', 'The prevailing mood at dinner was one of relief.', NULL, 'Tâm trạng chung bao trùm bữa tối là sự nhẹ nhõm.', '{"wordId":"prevailing","ukIpa":"/prɪˈveɪlɪŋ/","usIpa":"/prɪˈveɪlɪŋ/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Most common or influential at a particular time or place.","vi":"phổ biến; thịnh hành; chiếm ưu thế"}],"examples":[{"en":"The prevailing mood at dinner was one of relief.","vi":"Tâm trạng chung bao trùm bữa tối là sự nhẹ nhõm.","audioKind":"ex"},{"en":"The prevailing view among urban planners is that reliable public transport can reduce dependence on private cars.","vi":"Quan điểm chủ đạo của các nhà quy hoạch đô thị là hệ thống giao thông công cộng đáng tin cậy có thể làm giảm sự phụ thuộc vào xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"prevailing view","vi":"quan điểm chủ đạo"},{"en":"prevailing conditions","vi":"tình hình hiện tại"},{"en":"prevailing wind","vi":"gió thịnh hành"},{"en":"prevailing attitude","vi":"thái độ phổ biến"}],"wordFamily":["prevail (v.)"],"synonyms":["dominant","predominant"],"antonyms":[],"tipVi":"Thường đứng trước danh từ; prevailing wind có nghĩa là gió thịnh hành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obnoxious', 'en-c1-6', 'obnoxious', '/əbˈnɑːkʃəs/', 'C1', 'vô cùng khó chịu; đáng ghét', 'adj.', 'obnoxiously (adv.), obnoxiousness (n.)', 'Đồng nghĩa: offensive, unpleasant · Trái nghĩa: pleasant, agreeable', 'Mức độ nghiêm trọng hơn annoying, thường dùng để miêu tả người hoặc hành vi vô lễ.', 'An obnoxious passenger played loud music throughout the journey.', NULL, 'Một hành khách vô cùng khó chịu đã bật nhạc to suốt chuyến đi.', '{"wordId":"obnoxious","ukIpa":"/əbˈnɒkʃəs/","usIpa":"/əbˈnɑːkʃəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"extremely unpleasant or offensive","vi":"vô cùng khó chịu; đáng ghét"}],"examples":[{"en":"An obnoxious passenger played loud music throughout the journey.","vi":"Một hành khách vô cùng khó chịu đã bật nhạc to suốt chuyến đi.","audioKind":"ex"},{"en":"Obnoxious behaviour on public transport can discourage commuters from using otherwise convenient and affordable services.","vi":"Hành vi đáng ghét trên phương tiện giao thông công cộng có thể khiến người đi làm từ chối sử dụng các dịch vụ vốn dĩ tiện lợi và có giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"obnoxious behaviour","vi":"hành vi đáng ghét"},{"en":"obnoxious remark","vi":"lời lẽ khiếm nhã"},{"en":"obnoxious person","vi":"kẻ đáng ghét"}],"wordFamily":["obnoxiously (adv.)","obnoxiousness (n.)"],"synonyms":["offensive","unpleasant"],"antonyms":["pleasant","agreeable"],"tipVi":"Mức độ nghiêm trọng hơn annoying, thường dùng để miêu tả người hoặc hành vi vô lễ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diminish', 'en-c1-6', 'diminish', '/dɪˈmɪnɪʃ/', 'C1', 'giảm bớt; làm suy yếu; thu nhỏ; làm giảm giá trị; hạ thấp', 'v.', 'diminished (adj.), diminishing (adj.), diminution (n.)', 'Đồng nghĩa: decrease, reduce, lessen · Trái nghĩa: increase, enhance', 'Có thể dùng cả ngoại động từ và nội động từ: niềm tin có thể diminish hoặc bị làm suy yếu.', 'The pain in my ankle gradually diminished overnight.', NULL, 'Cơn đau ở mắt cá chân của tôi đã giảm dần qua đêm.', '{"wordId":"diminish","ukIpa":"/dɪˈmɪnɪʃ/","usIpa":"/dɪˈmɪnɪʃ/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to become smaller or weaker, or make something so","vi":"giảm bớt; làm suy yếu; thu nhỏ"},{"pos":"v.","en":"to make someone or something seem less important or valuable","vi":"làm giảm giá trị; hạ thấp"}],"examples":[{"en":"The pain in my ankle gradually diminished overnight.","vi":"Cơn đau ở mắt cá chân của tôi đã giảm dần qua đêm.","audioKind":"ex"},{"en":"Investment in reliable public transport can diminish dependence on private cars and improve air quality in crowded cities.","vi":"Việc đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể làm giảm sự phụ thuộc vào xe hơi cá nhân và cải thiện chất lượng không khí ở các thành phố đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"diminish significantly","vi":"giảm đi đáng kể"},{"en":"diminish in importance","vi":"giảm tầm quan trọng"},{"en":"diminish the impact","vi":"giảm bớt tác động"},{"en":"diminishing returns","vi":"lợi ức giảm dần"}],"wordFamily":["diminished (adj.)","diminishing (adj.)","diminution (n.)"],"synonyms":["decrease","reduce","lessen"],"antonyms":["increase","enhance"],"tipVi":"Có thể dùng cả ngoại động từ và nội động từ: niềm tin có thể diminish hoặc bị làm suy yếu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mediator', 'en-c1-6', 'mediator', '/ˈmiːdieɪtər/', 'C1', 'người hòa giải; trọng tài; trung gian', 'n.', 'mediate (v.), mediation (n.)', 'Đồng nghĩa: go-between, intermediary', 'Người hòa giải giúp các bên đạt được thỏa thuận, thường không trực tiếp đưa ra phán quyết.', 'A mediator helped our neighbours settle their garden fence dispute.', NULL, 'Một người hòa giải đã giúp hàng xóm của chúng tôi giải quyết tranh chấp về hàng rào vườn.', '{"wordId":"mediator","ukIpa":"/ˈmiːdieɪtə/","usIpa":"/ˈmiːdieɪtər/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Someone who helps opposing sides reach an agreement","vi":"người hòa giải; trọng tài; trung gian"}],"examples":[{"en":"A mediator helped our neighbours settle their garden fence dispute.","vi":"Một người hòa giải đã giúp hàng xóm của chúng tôi giải quyết tranh chấp về hàng rào vườn.","audioKind":"ex"},{"en":"An independent mediator can help employers and workers negotiate fair conditions without resorting to lengthy legal proceedings.","vi":"Một người hòa giải độc lập có thể giúp người sử dụng lao động và người lao động đàm phán các điều kiện công bằng mà không cần phải nhờ đến các thủ tục pháp lý kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"independent mediator","vi":"người hòa giải độc lập"},{"en":"act as a mediator","vi":"đóng vai trò là người hòa giải"},{"en":"appoint a mediator","vi":"chỉ định một người hòa giải"}],"wordFamily":["mediate (v.)","mediation (n.)"],"synonyms":["go-between","intermediary"],"antonyms":[],"tipVi":"Người hòa giải giúp các bên đạt được thỏa thuận, thường không trực tiếp đưa ra phán quyết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sermon', 'en-c1-6', 'sermon', '/ˈsɝːmən/', 'C1', 'bài giảng đạo; bài thuyết giáo; lời giáo huấn; lời lên lớp dài dòng', 'n.', NULL, NULL, 'Nghĩa gốc là bài giảng tôn giáo; khi dùng theo nghĩa "lời giáo huấn" thì thường mang ý phàn nàn.', 'The sermon encouraged everyone to help their neighbours.', NULL, 'Bài giảng đạo khuyến khích mọi người giúp đỡ những người hàng xóm của họ.', '{"wordId":"sermon","ukIpa":"/ˈsɜːmən/","usIpa":"/ˈsɝːmən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a religious talk given during a service","vi":"bài giảng đạo; bài thuyết giáo"},{"pos":"n.","en":"a long talk telling someone how they should behave","vi":"lời giáo huấn; lời lên lớp dài dòng"}],"examples":[{"en":"The sermon encouraged everyone to help their neighbours.","vi":"Bài giảng đạo khuyến khích mọi người giúp đỡ những người hàng xóm của họ.","audioKind":"ex"},{"en":"A sermon can strengthen community ties by encouraging listeners to support vulnerable people and participate in local projects.","vi":"Một bài giảng đạo có thể thắt chặt tình đoàn kết cộng đồng bằng cách khuyến khích thính giả giúp đỡ những người dễ bị tổn thương và tham gia vào các dự án địa phương.","audioKind":"ex2"}],"collocations":[{"en":"deliver a sermon","vi":"thuyết giảng một bài"},{"en":"a sermon on kindness","vi":"bài giảng về lòng tốt"},{"en":"preach a sermon","vi":"giảng đạo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa gốc là bài giảng tôn giáo; khi dùng theo nghĩa \"lời giáo huấn\" thì thường mang ý phàn nàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delinquent', 'en-c1-6', 'delinquent', '/dɪˈlɪŋkwənt/', 'C1', 'phạm pháp; có hành vi lệch chuẩn xã hội; quá hạn thanh toán; chậm trả nợ; kẻ phạm pháp; thiếu niên phạm tội', 'adj.', 'delinquency (n.)', 'Trái nghĩa: law-abiding', 'Trong ngữ cảnh tài chính nghĩa là chậm thanh toán; trong đời sống thường chỉ thiếu niên phạm tội.', 'The youth centre helps teenagers change their delinquent behaviour.', NULL, 'Trung tâm thanh thiếu niên giúp đỡ các bạn trẻ cải thiện hành vi lệch chuẩn pháp luật của mình.', '{"wordId":"delinquent","ukIpa":"/dɪˈlɪŋkwənt/","usIpa":"/dɪˈlɪŋkwənt/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Behaving illegally or antisocially, especially while young.","vi":"phạm pháp; có hành vi lệch chuẩn xã hội"},{"pos":"adj.","en":"Not paid on time, or failing to pay on time.","vi":"quá hạn thanh toán; chậm trả nợ"},{"pos":"n.","en":"A person, usually young, who breaks the law.","vi":"kẻ phạm pháp; thiếu niên phạm tội"}],"examples":[{"en":"The youth centre helps teenagers change their delinquent behaviour.","vi":"Trung tâm thanh thiếu niên giúp đỡ các bạn trẻ cải thiện hành vi lệch chuẩn pháp luật của mình.","audioKind":"ex"},{"en":"Early support for vulnerable families may reduce delinquent behaviour more effectively than harsher punishments alone.","vi":"Sự hỗ trợ kịp thời cho các gia đình dễ bị tổn thương có thể làm giảm hành vi phạm pháp hiệu quả hơn so với việc chỉ áp dụng các hình phạt nặng nề.","audioKind":"ex2"}],"collocations":[{"en":"delinquent behaviour","vi":"hành vi phạm pháp"},{"en":"a juvenile delinquent","vi":"thiếu niên phạm tội"},{"en":"delinquent payments","vi":"các khoản thanh toán quá hạn"},{"en":"a delinquent borrower","vi":"người đi vay chậm trả nợ"}],"wordFamily":["delinquency (n.)"],"synonyms":[],"antonyms":["law-abiding"],"tipVi":"Trong ngữ cảnh tài chính nghĩa là chậm thanh toán; trong đời sống thường chỉ thiếu niên phạm tội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commune', 'en-c1-6', 'commune', '/ˈkɑːmjuːn/', 'C1', 'công cộng; cộng đồng; nhóm người cùng sinh sống, chia sẻ tài sản và trách nhiệm', 'n.', 'communal (adj.), communally (adv.)', NULL, 'Danh từ chỉ cộng đồng cùng sinh sống; cụm từ commune with mang nghĩa giao hòa tâm hồn.', 'They live in a commune and grow vegetables together.', NULL, 'Họ sống trong một cộng đồng chung và cùng nhau trồng rau.', '{"wordId":"commune","ukIpa":"/ˈkɒmjuːn/","usIpa":"/ˈkɑːmjuːn/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a group living together and sharing possessions and responsibilities","vi":"công cộng; cộng đồng; nhóm người cùng sinh sống, chia sẻ tài sản và trách nhiệm"}],"examples":[{"en":"They live in a commune and grow vegetables together.","vi":"Họ sống trong một cộng đồng chung và cùng nhau trồng rau.","audioKind":"ex"},{"en":"Living in a commune can reduce individual expenses, but shared decision-making requires patience and effective communication.","vi":"Sống trong một cộng đồng chung có thể giảm chi phí cá nhân, nhưng việc ra quyết định chung đòi hỏi sự kiên nhẫn và giao tiếp hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"live in a commune","vi":"sống trong một cộng đồng chung"},{"en":"farming commune","vi":"công xã nông nghiệp"},{"en":"establish a commune","vi":"thành lập một cộng đồng"}],"wordFamily":["communal (adj.)","communally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ cộng đồng cùng sinh sống; cụm từ commune with mang nghĩa giao hòa tâm hồn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stereotype', 'en-c1-6', 'stereotype', '/ˈsteriətaɪp/', 'C1', 'khuôn mẫu; định kiến; áp đặt định kiến; coi thường theo khuôn mẫu', 'n.', 'stereotypical (adj.), stereotypically (adv.), stereotyping (n.)', NULL, 'Thường chỉ cách nhìn nhận đơn giản hóa về một nhóm người, không phản ánh đúng thực tế.', 'My grandmother challenges the stereotype that older people dislike technology.', NULL, 'Bà tôi đã phá vỡ định kiến rằng người cao tuổi không thích công nghệ.', '{"wordId":"stereotype","ukIpa":"/ˈsteriətaɪp/","usIpa":"/ˈsteriətaɪp/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a fixed, oversimplified belief about a group of people","vi":"khuôn mẫu; định kiến"},{"pos":"v.","en":"to judge people using fixed beliefs about their group","vi":"áp đặt định kiến; coi thường theo khuôn mẫu"}],"examples":[{"en":"My grandmother challenges the stereotype that older people dislike technology.","vi":"Bà tôi đã phá vỡ định kiến rằng người cao tuổi không thích công nghệ.","audioKind":"ex"},{"en":"Schools should challenge gender stereotypes so that all students feel free to pursue their interests.","vi":"Các trường học nên thách thức các định kiến về giới để tất cả học sinh đều tự do theo đuổi sở thích của mình.","audioKind":"ex2"}],"collocations":[{"en":"gender stereotypes","vi":"định kiến giới"},{"en":"challenge a stereotype","vi":"phá bỏ định kiến"},{"en":"reinforce stereotypes","vi":"củng cố định kiến"}],"wordFamily":["stereotypical (adj.)","stereotypically (adv.)","stereotyping (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ cách nhìn nhận đơn giản hóa về một nhóm người, không phản ánh đúng thực tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_notoriety', 'en-c1-6', 'notoriety', '/ˌnoʊtəˈraɪəti/', 'C1', 'tiếng xấu; sự tai tiếng', 'n.', 'notorious (adj.), notoriously (adv.)', 'Đồng nghĩa: infamy', 'Thường không đếm được, mang nghĩa tiêu cực; "name" mang nghĩa trung tính dùng fame.', 'The restaurant gained notoriety for its dirty kitchen.', NULL, 'Nhà hàng đó đã mang tiếng xấu vì căn bếp bẩn thỉu.', '{"wordId":"notoriety","ukIpa":"/ˌnəʊtəˈraɪəti/","usIpa":"/ˌnoʊtəˈraɪəti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"the state of being widely known for something bad","vi":"tiếng xấu; sự tai tiếng"}],"examples":[{"en":"The restaurant gained notoriety for its dirty kitchen.","vi":"Nhà hàng đó đã mang tiếng xấu vì căn bếp bẩn thỉu.","audioKind":"ex"},{"en":"Some companies gain notoriety for environmental damage, making it harder for them to attract skilled workers.","vi":"Một số doanh nghiệp trở nên tai tiếng vì hành vi tàn phá môi trường, khiến họ khó thu hút lao động tay nghề cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"gain notoriety","vi":"rước lấy tiếng xấu"},{"en":"notoriety for corruption","vi":"tiếng xấu vì tham nhũng"},{"en":"achieve notoriety","vi":"trở nên tai tiếng"}],"wordFamily":["notorious (adj.)","notoriously (adv.)"],"synonyms":["infamy"],"antonyms":[],"tipVi":"Thường không đếm được, mang nghĩa tiêu cực; \"name\" mang nghĩa trung tính dùng fame.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reconcile', 'en-c1-6', 'reconcile', '/ˈrekənsaɪl/', 'C1', 'hài hòa hóa; làm cho tương thích; giải hòa; làm hòa; khiến ai đó chấp nhận (hoàn cảnh khó khăn)', 'v.', 'reconciliation (n.), reconcilable (adj.), irreconcilable (adj.)', NULL, 'hài hòa dùng với with; chấp nhận thực tế dùng reconcile oneself to.', 'We reconciled our different tastes by choosing a buffet.', NULL, 'Chúng tôi đã làm hài hòa sở thích khác nhau của mình bằng cách chọn một bữa tiệc buffet.', '{"wordId":"reconcile","ukIpa":"/ˈrekənsaɪl/","usIpa":"/ˈrekənsaɪl/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To make conflicting ideas, needs, or facts compatible","vi":"hài hòa hóa; làm cho tương thích"},{"pos":"v.","en":"To restore friendly relations after a disagreement","vi":"giải hòa; làm hòa"},{"pos":"v.","en":"To help someone accept an unpleasant situation","vi":"khiến ai đó chấp nhận (hoàn cảnh khó khăn)"}],"examples":[{"en":"We reconciled our different tastes by choosing a buffet.","vi":"Chúng tôi đã làm hài hòa sở thích khác nhau của mình bằng cách chọn một bữa tiệc buffet.","audioKind":"ex"},{"en":"Governments must reconcile the demand for affordable housing with the need to protect valuable green spaces.","vi":"Chính phủ phải dung hòa giữa nhu cầu nhà ở giá rẻ và yêu cầu bảo vệ các mảng xanh quý giá.","audioKind":"ex2"}],"collocations":[{"en":"reconcile A with B","vi":"hài hòa A với B"},{"en":"reconcile differences","vi":"hòa giải bất đồng"},{"en":"be reconciled with someone","vi":"làm hòa với ai đó"},{"en":"reconcile yourself to","vi":"tự thích nghi với"}],"wordFamily":["reconciliation (n.)","reconcilable (adj.)","irreconcilable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"hài hòa dùng với with; chấp nhận thực tế dùng reconcile oneself to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_establishment', 'en-c1-6', 'establishment', '/ɪˈstæblɪʃmənt/', 'C1', 'sự thành lập; sự thiết lập; tổ chức; cơ sở kinh doanh; giới cầm quyền; tầng lớp thống trị', 'n.', 'establish (v.), established (adj.)', NULL, 'Khi chỉ hành động thành lập thì từ này không đếm được; khi chỉ cơ sở hay tổ chức thì đếm được.', 'The establishment of our local club brought neighbours together.', NULL, 'Việc thành lập câu lạc bộ địa phương đã gắn kết những người hàng xóm lại với nhau.', '{"wordId":"establishment","ukIpa":"/ɪˈstæblɪʃmənt/","usIpa":"/ɪˈstæblɪʃmənt/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"the process of starting an organisation or system","vi":"sự thành lập; sự thiết lập"},{"pos":"n.","en":"an organisation or place where business or public activities happen","vi":"tổ chức; cơ sở kinh doanh"},{"pos":"n.","en":"the powerful people who control a society or profession","vi":"giới cầm quyền; tầng lớp thống trị"}],"examples":[{"en":"The establishment of our local club brought neighbours together.","vi":"Việc thành lập câu lạc bộ địa phương đã gắn kết những người hàng xóm lại với nhau.","audioKind":"ex"},{"en":"The establishment of protected marine areas can help restore fish populations and support coastal communities.","vi":"Việc thiết lập các khu bảo tồn biển có thể giúp khôi phục nguồn lợi thủy sản và hỗ trợ các cộng đồng ven biển.","audioKind":"ex2"}],"collocations":[{"en":"the establishment of","vi":"sự thành lập của"},{"en":"educational establishment","vi":"cơ sở giáo dục"},{"en":"business establishment","vi":"cơ sở kinh doanh"},{"en":"the political establishment","vi":"giới cầm quyền chính trị"}],"wordFamily":["establish (v.)","established (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ hành động thành lập thì từ này không đếm được; khi chỉ cơ sở hay tổ chức thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_esteem', 'en-c1-6', 'esteem', '/ɪˈstiːm/', 'C1', 'sự kính trọng; lòng ngưỡng mộ; kính trọng; đánh giá cao', 'n.', 'esteemed (adj.), self-esteem (n.)', 'Đồng nghĩa: respect, admiration · Trái nghĩa: contempt', 'Thường dùng cụm hold someone in high esteem để diễn tả sự kính trọng sâu sắc đối với ai đó.', 'Her neighbours hold her in esteem for her kindness.', NULL, 'Những người hàng xóm dành cho cô ấy sự kính trọng vì lòng tốt của cô ấy.', '{"wordId":"esteem","ukIpa":"/ɪˈstiːm/","usIpa":"/ɪˈstiːm/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Respect and admiration for someone.","vi":"sự kính trọng; lòng ngưỡng mộ"},{"pos":"v.","en":"To respect and admire someone highly.","vi":"kính trọng; đánh giá cao"}],"examples":[{"en":"Her neighbours hold her in esteem for her kindness.","vi":"Những người hàng xóm dành cho cô ấy sự kính trọng vì lòng tốt của cô ấy.","audioKind":"ex"},{"en":"Teachers who treat students fairly often earn the lasting esteem of their local communities.","vi":"Những giáo viên đối xử công bằng với học sinh thường chiếm được sự kính trọng lâu dài từ cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"hold someone in high esteem","vi":"vô cùng kính trọng ai đó"},{"en":"earn someone''s esteem","vi":"giành được sự kính trọng của ai đó"},{"en":"mutual esteem","vi":"sự tôn trọng lẫn nhau"}],"wordFamily":["esteemed (adj.)","self-esteem (n.)"],"synonyms":["respect","admiration"],"antonyms":["contempt"],"tipVi":"Thường dùng cụm hold someone in high esteem để diễn tả sự kính trọng sâu sắc đối với ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confine', 'en-c1-6', 'confine', '/kənˈfaɪn/', 'C1', 'hạn chế; giới hạn (trong một phạm vi nhất định); giam giữ; bắt ở một nơi không thể rời đi', 'v.', 'confinement (n.), confined (adj.)', 'Đồng nghĩa: restrict, limit · Trái nghĩa: release, free', 'Thường dùng cấu trúc confine A to B để diễn tả việc giới hạn A trong phạm vi B.', 'Please confine your muddy boots to the porch.', NULL, 'Xin hãy để những chiếc ủng dính bùn của bạn ở ngoài hiên.', '{"wordId":"confine","ukIpa":"/kənˈfaɪn/","usIpa":"/kənˈfaɪn/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To keep something within particular limits","vi":"hạn chế; giới hạn (trong một phạm vi nhất định)"},{"pos":"v.","en":"To keep someone in a place they cannot leave","vi":"giam giữ; bắt ở một nơi không thể rời đi"}],"examples":[{"en":"Please confine your muddy boots to the porch.","vi":"Xin hãy để những chiếc ủng dính bùn của bạn ở ngoài hiên.","audioKind":"ex"},{"en":"Researchers should not confine their investigation to wealthy neighbourhoods when studying access to public transport.","vi":"Các nhà nghiên cứu không nên giới hạn cuộc khảo sát của họ trong các khu vực giàu có khi nghiên cứu khả năng tiếp cận giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"confine something to","vi":"giới hạn cái gì trong"},{"en":"be confined to bed","vi":"phải nằm liệt giường"},{"en":"confine oneself to","vi":"tự giới hạn bản thân trong"}],"wordFamily":["confinement (n.)","confined (adj.)"],"synonyms":["restrict","limit"],"antonyms":["release","free"],"tipVi":"Thường dùng cấu trúc confine A to B để diễn tả việc giới hạn A trong phạm vi B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_calamity', 'en-c1-6', 'calamity', '/kəˈlæməti/', 'C1', 'thảm họa; tai họa lớn', 'n.', 'calamitous (adj.)', 'Đồng nghĩa: disaster, catastrophe', 'Nặng nề hơn rất nhiều so với một rắc rối thông thường, thường dùng để chỉ những sự kiện gây tổn thất nghiêm trọng.', 'The flood was a calamity for the whole village.', NULL, 'Trận lụt vừa qua là một thảm họa giáng xuống toàn bộ ngôi làng.', '{"wordId":"calamity","ukIpa":"/kəˈlæməti/","usIpa":"/kəˈlæməti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"An event causing severe damage, suffering, or distress.","vi":"thảm họa; tai họa lớn"}],"examples":[{"en":"The flood was a calamity for the whole village.","vi":"Trận lụt vừa qua là một thảm họa giáng xuống toàn bộ ngôi làng.","audioKind":"ex"},{"en":"Effective emergency planning can reduce the human and economic costs of a natural calamity.","vi":"Công tác quy hoạch ứng phó khẩn cấp hiệu quả có thể giảm thiểu tổn thất về người và chi phí kinh tế do một thảm họa tự nhiên gây ra.","audioKind":"ex2"}],"collocations":[{"en":"a natural calamity","vi":"một thảm họa thiên nhiên"},{"en":"avert a calamity","vi":"ngăn chặn thảm họa"},{"en":"calamity strikes","vi":"thảm họa ập đến"}],"wordFamily":["calamitous (adj.)"],"synonyms":["disaster","catastrophe"],"antonyms":[],"tipVi":"Nặng nề hơn rất nhiều so với một rắc rối thông thường, thường dùng để chỉ những sự kiện gây tổn thất nghiêm trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hinder', 'en-c1-6', 'hinder', '/ˈhɪndər/', 'C1', 'cản trở; gây khó khăn', 'v.', 'hindrance (n.)', 'Đồng nghĩa: hamper, impede, obstruct · Trái nghĩa: help, facilitate', 'hinder là làm cho sự việc trở nên khó khăn hơn, không nhất thiết mang nghĩa ngăn chặn hoàn toàn như prevent.', 'Heavy snow hindered our journey through the mountains.', NULL, 'Tuyết dày đã cản trở hành trình vượt núi của chúng tôi.', '{"wordId":"hinder","ukIpa":"/ˈhɪndə/","usIpa":"/ˈhɪndər/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To make progress or an activity more difficult.","vi":"cản trở; gây khó khăn"}],"examples":[{"en":"Heavy snow hindered our journey through the mountains.","vi":"Tuyết dày đã cản trở hành trình vượt núi của chúng tôi.","audioKind":"ex"},{"en":"Limited access to reliable internet can hinder educational progress among students living in remote rural communities.","vi":"Việc thiếu khả năng tiếp cận internet ổn định có thể cản trở tiến ức học tập của học sinh sống ở các cộng đồng vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"hinder progress","vi":"cản trở tiến độ"},{"en":"hinder development","vi":"cản trở sự phát triển"},{"en":"hinder efforts","vi":"cản trở các nỗ lực"}],"wordFamily":["hindrance (n.)"],"synonyms":["hamper","impede","obstruct"],"antonyms":["help","facilitate"],"tipVi":"hinder là làm cho sự việc trở nên khó khăn hơn, không nhất thiết mang nghĩa ngăn chặn hoàn toàn như prevent.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transformation', 'en-c1-6', 'transformation', '/ˌtrænsfɚˈmeɪʃən/', 'C1', 'sự thay đổi hoàn toàn; sự cải tạo; sự chuyển đổi', 'n.', 'transform (v.), transformative (adj.)', 'Đồng nghĩa: conversion, change', 'Thường dùng cấu trúc transformation from A into B để chỉ sự chuyển đổi từ A sang B.', 'The dusty attic underwent a transformation into a cosy bedroom.', NULL, 'Căn gác mái đầy bụi đã trải qua một cuộc cải tạo để trở thành phòng ngủ ấm cúng.', '{"wordId":"transformation","ukIpa":"/ˌtrænsfəˈmeɪʃən/","usIpa":"/ˌtrænsfɚˈmeɪʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a complete change in the appearance or nature of something","vi":"sự thay đổi hoàn toàn; sự cải tạo; sự chuyển đổi"}],"examples":[{"en":"The dusty attic underwent a transformation into a cosy bedroom.","vi":"Căn gác mái đầy bụi đã trải qua một cuộc cải tạo để trở thành phòng ngủ ấm cúng.","audioKind":"ex"},{"en":"Investment in renewable energy could accelerate the transformation of industrial regions into centres of sustainable production.","vi":"Việc đầu tư vào năng lượng tái tạo có thể đẩy nhanh quá trình chuyển đổi các khu vực công nghiệp thành trung tâm sản xuất bền vững.","audioKind":"ex2"}],"collocations":[{"en":"undergo a transformation","vi":"trải qua một cuộc chuyển đổi"},{"en":"a dramatic transformation","vi":"sự chuyển đổi ngoạn mục"},{"en":"digital transformation","vi":"chuyển đổi số"},{"en":"transformation into","vi":"sự biến đổi thành"}],"wordFamily":["transform (v.)","transformative (adj.)"],"synonyms":["conversion","change"],"antonyms":[],"tipVi":"Thường dùng cấu trúc transformation from A into B để chỉ sự chuyển đổi từ A sang B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vow', 'en-c1-6', 'vow', '/vaʊ/', 'C1', 'lời thề; lời hứa chắc chắn; thề; hứa quyết tâm thực hiện điều gì', 'n.', NULL, 'Đồng nghĩa: pledge, promise', 'Động từ thường đi với cấu trúc vow to do hoặc mệnh đề vow that.', 'She made a vow to visit her grandmother weekly.', NULL, 'Cô ấy đã đưa ra lời thề sẽ đến thăm bà hàng tuần.', '{"wordId":"vow","ukIpa":"/vaʊ/","usIpa":"/vaʊ/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A serious promise to do or not do something","vi":"lời thề; lời hứa chắc chắn"},{"pos":"v.","en":"To promise firmly that you will do something","vi":"thề; hứa quyết tâm thực hiện điều gì"}],"examples":[{"en":"She made a vow to visit her grandmother weekly.","vi":"Cô ấy đã đưa ra lời thề sẽ đến thăm bà hàng tuần.","audioKind":"ex"},{"en":"Local leaders vowed to protect public parks despite growing pressure to develop more housing.","vi":"Các nhà lãnh đạo địa phương đã cam kết bảo vệ các công viên công cộng bất chấp áp lực gia tăng về việc phát triển thêm nhà ở.","audioKind":"ex2"}],"collocations":[{"en":"make a vow","vi":"tuyên thệ"},{"en":"keep a vow","vi":"giữ lời thề"},{"en":"break a vow","vi":"phá vỡ lời thề"},{"en":"vow to do something","vi":"thề làm điều gì đó"}],"wordFamily":[],"synonyms":["pledge","promise"],"antonyms":[],"tipVi":"Động từ thường đi với cấu trúc vow to do hoặc mệnh đề vow that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_6_1', 'en-c1-6', 'Cách dùng “exploitation” (n.) — sự bóc lột; sự áp bức', 'labour exploitation  ·  commercial exploitation  ·  exploitation of natural resources', 'Dùng cho con người thường mang nghĩa bóc lột; dùng cho tài nguyên mang nghĩa khai thác, cần căn cứ vào ngữ cảnh cụ thể.', 'Họ từ (Word Family): exploit (v.), exploitative (adj.), exploiter (n.)', '[{"hanzi":"The workers demanded fair wages and protection from exploitation.","pinyin":"","meaning":"Những người lao động yêu cầu mức lương công bằng và sự bảo vệ khỏi nạn bóc lột."},{"hanzi":"The uncontrolled exploitation of natural resources can damage ecosystems and undermine the livelihoods of communities that depend on them.","pinyin":"","meaning":"Việc khai thác tài nguyên thiên nhiên bừa bãi có thể tàn phá hệ sinh thái và làm suy kiệt sinh kế của các cộng đồng phụ thuộc vào chúng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_6_2', 'en-c1-6', 'Cách dùng “calamity” (n.) — thảm họa; tai họa lớn', 'a natural calamity  ·  avert a calamity  ·  calamity strikes', 'Nặng nề hơn rất nhiều so với một rắc rối thông thường, thường dùng để chỉ những sự kiện gây tổn thất nghiêm trọng.', 'Họ từ (Word Family): calamitous (adj.) | Đồng nghĩa: disaster, catastrophe', '[{"hanzi":"The flood was a calamity for the whole village.","pinyin":"","meaning":"Trận lụt vừa qua là một thảm họa giáng xuống toàn bộ ngôi làng."},{"hanzi":"Effective emergency planning can reduce the human and economic costs of a natural calamity.","pinyin":"","meaning":"Công tác quy hoạch ứng phó khẩn cấp hiệu quả có thể giảm thiểu tổn thất về người và chi phí kinh tế do một thảm họa tự nhiên gây ra."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_6_3', 'en-c1-6', 'Cách dùng “manipulation” (n.) — sự thao túng; sự điều khiển (kiểm soát con người hoặc tình huống một cách không công bằng vì lợi ích cá nhân)', 'emotional manipulation  ·  data manipulation  ·  market manipulation', 'Khi dùng để chỉ việc thao túng con người thường mang nghĩa xấu; khi chỉ thao tác công cụ thì có tính trung lập.', 'Họ từ (Word Family): manipulate (v.), manipulative (adj.), manipulator (n.)', '[{"hanzi":"She recognised his emotional manipulation and refused to feel guilty.","pinyin":"","meaning":"Cô ấy nhận ra thủ đoạn thao túng cảm xúc của anh ta và từ chối cảm thấy có lỗi."},{"hanzi":"The manipulation of survey results can mislead policymakers and reduce public trust in scientific research.","pinyin":"","meaning":"Việc thao túng kết quả khảo sát có thể làm các nhà hoạch định chính sách hiểu sai và làm giảm lòng tin của công chúng vào nghiên cứu khoa học."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_6_4', 'en-c1-6', 'Cách dùng “hinder” (v.) — cản trở; gây khó khăn', 'hinder progress  ·  hinder development  ·  hinder efforts', 'hinder là làm cho sự việc trở nên khó khăn hơn, không nhất thiết mang nghĩa ngăn chặn hoàn toàn như prevent.', 'Họ từ (Word Family): hindrance (n.) | Đồng nghĩa: hamper, impede, obstruct · Trái nghĩa: help, facilitate', '[{"hanzi":"Heavy snow hindered our journey through the mountains.","pinyin":"","meaning":"Tuyết dày đã cản trở hành trình vượt núi của chúng tôi."},{"hanzi":"Limited access to reliable internet can hinder educational progress among students living in remote rural communities.","pinyin":"","meaning":"Việc thiếu khả năng tiếp cận internet ổn định có thể cản trở tiến ức học tập của học sinh sống ở các cộng đồng vùng sâu vùng xa."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_6_1', 'en-c1-6', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_1_1', 'ten_c1_6_1', 'cohesive', 'Regular practice helped us become a more cohesive team.', 'Regular practice helped us become a more cohesive team.', '/koʊˈhiːsɪv/', 'Việc luyện tập thường xuyên đã giúp chúng tôi trở thành một đội ngũ có tính gắn kết cao hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_1_2', 'ten_c1_6_1', 'manipulation', 'She recognised his emotional manipulation and refused to feel guilty.', 'She recognised his emotional manipulation and refused to feel guilty.', '/məˌnɪpjəˈleɪʃən/', 'Cô ấy nhận ra thủ đoạn thao túng cảm xúc của anh ta và từ chối cảm thấy có lỗi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_1_3', 'ten_c1_6_1', 'flatter', 'That blue jacket really flatters you in this light.', 'That blue jacket really flatters you in this light.', '/ˈflætər/', 'Chiếc áo khoác xanh đó thực sự rất tôn dáng bạn dưới ánh sáng này.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_1_4', 'ten_c1_6_1', 'meddle', 'Please don''t meddle in how I arrange my room.', 'Please don''t meddle in how I arrange my room.', '/ˈmedəl/', 'Xin đừng can thiệp vào cách tôi sắp xếp phòng của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_1_5', 'ten_c1_6_1', 'constitute', 'Vegetables constitute most of the food in our fridge.', 'Vegetables constitute most of the food in our fridge.', '/ˈkɑːnstɪtuːt/', 'Rau củ chiếm phần lớn lượng thực phẩm trong tủ lạnh nhà chúng tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_1_6', 'ten_c1_6_1', 'phony', 'His phony smile disappeared as soon as we left.', 'His phony smile disappeared as soon as we left.', '/ˈfoʊni/', 'Nụ cười giả tạo của anh ta biến mất ngay khi chúng tôi rời đi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_1_7', 'ten_c1_6_1', 'microcosm', 'Our busy kitchen is a microcosm of family life.', 'Our busy kitchen is a microcosm of family life.', '/ˈmaɪkroʊkɑːzəm/', 'Căn bếp bận rộn của chúng tôi là hình thu nhỏ của đời sống gia đình.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_1_8', 'ten_c1_6_1', 'forgery', 'The painting in the shop was a forgery.', 'The painting in the shop was a forgery.', '/ˈfɔːrdʒəri/', 'Bức tranh trong cửa hàng hóa ra là một món đồ giả mạo.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_6_1_1', 'en-c1-6', 'ten_c1_6_1', 'listening', 'listening', 'Regular practice helped us become a more cohesive team.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Trận lụt vừa qua là một thảm họa giáng xuống toàn bộ ngôi làng.","Việc luyện tập thường xuyên đã giúp chúng tôi trở thành một đội ngũ có tính gắn kết cao hơn.","Việc thành lập câu lạc bộ địa phương đã gắn kết những người hàng xóm lại với nhau.","Trung tâm thanh thiếu niên giúp đỡ các bạn trẻ cải thiện hành vi lệch chuẩn pháp luật của mình."]'::jsonb, 1, 'Regular practice helped us become a more cohesive team. → Việc luyện tập thường xuyên đã giúp chúng tôi trở thành một đội ngũ có tính gắn kết cao hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_6_1_2', 'en-c1-6', 'ten_c1_6_1', 'listening', 'listening', 'She recognised his emotional manipulation and refused to feel guilty.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Rau củ chiếm phần lớn lượng thực phẩm trong tủ lạnh nhà chúng tôi.","Cô ấy đã đưa ra lời thề sẽ đến thăm bà hàng tuần.","Cô ấy nhận ra thủ đoạn thao túng cảm xúc của anh ta và từ chối cảm thấy có lỗi.","Tâm trạng chung bao trùm bữa tối là sự nhẹ nhõm."]'::jsonb, 2, 'She recognised his emotional manipulation and refused to feel guilty. → Cô ấy nhận ra thủ đoạn thao túng cảm xúc của anh ta và từ chối cảm thấy có lỗi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_6_1_3', 'en-c1-6', 'ten_c1_6_1', 'listening', 'listening', 'That blue jacket really flatters you in this light.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy để những chiếc ủng dính bùn của bạn ở ngoài hiên.","Sự dối trá của anh ta đã phơi bày khi chúng tôi mở chiếc hộp trống rỗng ra.","Chiếc áo khoác xanh đó thực sự rất tôn dáng bạn dưới ánh sáng này.","Căn bếp bận rộn của chúng tôi là hình thu nhỏ của đời sống gia đình."]'::jsonb, 2, 'That blue jacket really flatters you in this light. → Chiếc áo khoác xanh đó thực sự rất tôn dáng bạn dưới ánh sáng này.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_6_2', 'en-c1-6', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_2_1', 'ten_c1_6_2', 'cohesive', 'Shared public spaces can help build cohesive communities by encouraging interaction among people from different backgrounds.', 'Shared public spaces can help build cohesive communities by encouraging interaction among people from different backgrounds.', '/koʊˈhiːsɪv/', 'Không gian công cộng chung có thể giúp xây dựng các cộng đồng gắn kết bằng cách khuyến khích sự tương tác giữa những người có hoàn cảnh khác nhau.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_2_2', 'ten_c1_6_2', 'manipulation', 'The manipulation of survey results can mislead policymakers and reduce public trust in scientific research.', 'The manipulation of survey results can mislead policymakers and reduce public trust in scientific research.', '/məˌnɪpjəˈleɪʃən/', 'Việc thao túng kết quả khảo sát có thể làm các nhà hoạch định chính sách hiểu sai và làm giảm lòng tin của công chúng vào nghiên cứu khoa học.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_2_3', 'ten_c1_6_2', 'flatter', 'Advertisements often flatter consumers by suggesting that choosing a particular product demonstrates intelligence or good taste.', 'Advertisements often flatter consumers by suggesting that choosing a particular product demonstrates intelligence or good taste.', '/ˈflætər/', 'Quảng cáo thường nịnh bợ người tiêu dùng bằng cách gợi ý rằng việc chọn một sản phẩm cụ thể thể hiện sự thông minh hoặc gu thẩm mỹ tốt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_2_4', 'ten_c1_6_2', 'meddle', 'Parents who constantly meddle in their children''s decisions may prevent them from developing confidence and independence.', 'Parents who constantly meddle in their children''s decisions may prevent them from developing confidence and independence.', '/ˈmedəl/', 'Các bậc phụ huynh thường xuyên can thiệp vào quyết định của con cái có thể khiến trẻ khó phát triển sự tự tin và tính độc lập.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_2_5', 'ten_c1_6_2', 'constitute', 'Rising housing costs constitute a major barrier to financial independence for young adults in large cities.', 'Rising housing costs constitute a major barrier to financial independence for young adults in large cities.', '/ˈkɑːnstɪtuːt/', 'Chi phí nhà ở gia tăng tạo thành một rào cản lớn đối với sự độc lập tài chính của thanh thiếu niên ở các thành phố lớn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_6_2_6', 'ten_c1_6_2', 'phony', 'Consumers should be cautious about phony online reviews that exaggerate the benefits of health products.', 'Consumers should be cautious about phony online reviews that exaggerate the benefits of health products.', '/ˈfoʊni/', 'Người tiêu dùng nên cảnh giác với các đánh giá trực tuyến giả mạo phóng đại công dụng của các sản phẩm chăm sóc sức khỏe.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_6_2_1', 'en-c1-6', 'ten_c1_6_2', 'listening', 'listening', 'Shared public spaces can help build cohesive communities by encouraging interaction among people from different backgrounds.', NULL, 'Trong câu vừa nghe, từ “cohesive” mang nghĩa nào sau đây?', '["sự chính trực; tính trung thực và tuân thủ các nguyên tắc đạo đức vững chắc","bè phái; phe phái; nhóm nhỏ đối lập","chỉ định; phân công","có tính gắn kết chặt chẽ, đoàn kết"]'::jsonb, 3, '“cohesive” (/koʊˈhiːsɪv/): có tính gắn kết chặt chẽ, đoàn kết. Câu đầy đủ: Shared public spaces can help build cohesive communities by encouraging interaction among people from different backgrounds.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_6_2_2', 'en-c1-6', 'ten_c1_6_2', 'listening', 'listening', 'The manipulation of survey results can mislead policymakers and reduce public trust in scientific research.', NULL, 'Trong câu vừa nghe, từ “manipulation” mang nghĩa nào sau đây?', '["chất cặn; phần dư; thặng dư","quyền thuê nhà; thỏa thuận thuê tài sản","sự thao túng; sự điều khiển (kiểm soát con người hoặc tình huống một cách không công bằng vì lợi ích cá nhân)","liên quan đến; gắn liền với; áp dụng cho"]'::jsonb, 2, '“manipulation” (/məˌnɪpjəˈleɪʃən/): sự thao túng; sự điều khiển (kiểm soát con người hoặc tình huống một cách không công bằng vì lợi ích cá nhân). Câu đầy đủ: The manipulation of survey results can mislead policymakers and reduce public trust in scientific research.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
