INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_6_3', 'en-c1-6', 'That blue jacket really flatters you in this light', 'Chiếc áo khoác xanh đó thực sự rất tôn dáng bạn dưới ánh sáng này.', 'flatter /ˈflætər/', '["That","in","blue","this","you","really","light","jacket","flatters"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_6_4', 'en-c1-6', 'Please don''t meddle in how I arrange my room', 'Xin đừng can thiệp vào cách tôi sắp xếp phòng của mình.', 'meddle /ˈmedəl/', '["I","how","Please","arrange","my","meddle","room","in","don''t"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
