INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_6_6', 'en-c1-6', 'His phony smile disappeared as soon as we left', 'Nụ cười giả tạo của anh ta biến mất ngay khi chúng tôi rời đi.', 'phony /ˈfoʊni/', '["as","as","left","phony","His","smile","soon","disappeared","we"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_6_7', 'en-c1-6', 'Our busy kitchen is a microcosm of family life', 'Căn bếp bận rộn của chúng tôi là hình thu nhỏ của đời sống gia đình.', 'microcosm /ˈmaɪkroʊkɑːzəm/', '["is","life","a","Our","of","microcosm","family","busy","kitchen"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
