INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_1', 'en-c1-6', NULL, 'comprehensive_test', 'listening', 'cohesive', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có tính gắn kết chặt chẽ, đoàn kết","người ngoại đạo; người không chuyên môn","vĩ độ","phân biệt; nhận biết sự khác nhau"]'::jsonb, 0, 'cohesive (/koʊˈhiːsɪv/) → có tính gắn kết chặt chẽ, đoàn kết', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_2', 'en-c1-6', NULL, 'comprehensive_test', 'listening', 'She recognised his emotional manipulation and refused to feel guilty.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tâm trạng chung bao trùm bữa tối là sự nhẹ nhõm.","Xin hãy để những chiếc ủng dính bùn của bạn ở ngoài hiên.","Cô ấy nhận ra thủ đoạn thao túng cảm xúc của anh ta và từ chối cảm thấy có lỗi.","Căn gác mái đầy bụi đã trải qua một cuộc cải tạo để trở thành phòng ngủ ấm cúng."]'::jsonb, 2, 'She recognised his emotional manipulation and refused to feel guilty. → Cô ấy nhận ra thủ đoạn thao túng cảm xúc của anh ta và từ chối cảm thấy có lỗi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_3', 'en-c1-6', NULL, 'comprehensive_test', 'listening', 'flatter', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự cẩu thả, sự lơ đễnh, sự thiếu trách nhiệm, lỗi bất cẩn","sức bền; sự chịu đựng; độ dẻo dai","nịnh hót; nịnh bợ (ca ngợi ai đó, thường là không thành thật, để lấy lòng)","rõ ràng; thẳng thắn; dứt khoát"]'::jsonb, 2, 'flatter (/ˈflætər/) → nịnh hót; nịnh bợ (ca ngợi ai đó, thường là không thành thật, để lấy lòng); làm cho hãnh diện; làm cho vinh hạnh (kém theo sự quan tâm hoặc lời khen khiến ai đó cảm thấy vui); làm cho tôn dáng; làm cho đẹp hơn (làm cho ai đó trông hấp dẫn hơn thực tế)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_4', 'en-c1-6', NULL, 'comprehensive_test', 'listening', 'Please don''t meddle in how I arrange my room.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy nhận ra thủ đoạn thao túng cảm xúc của anh ta và từ chối cảm thấy có lỗi.","Xin đừng can thiệp vào cách tôi sắp xếp phòng của mình.","Nhà hàng đó đã mang tiếng xấu vì căn bếp bẩn thỉu.","Họ sống trong một cộng đồng chung và cùng nhau trồng rau."]'::jsonb, 1, 'Please don''t meddle in how I arrange my room. → Xin đừng can thiệp vào cách tôi sắp xếp phòng của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_5', 'en-c1-6', NULL, 'comprehensive_test', 'listening', 'constitute', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cấu thành; tạo thành","giáp ranh; liền kề; nối liền","khoa tâm thần; ngành tâm thần học","khả năng thanh toán nợ"]'::jsonb, 0, 'constitute (/ˈkɑːnstɪtuːt/) → cấu thành; tạo thành; được coi là; tạo nên; thành lập; thiết lập', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_6', 'en-c1-6', NULL, 'comprehensive_test', 'listening', 'His phony smile disappeared as soon as we left.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự dối trá của anh ta đã phơi bày khi chúng tôi mở chiếc hộp trống rỗng ra.","Nụ cười giả tạo của anh ta biến mất ngay khi chúng tôi rời đi.","Xin đừng can thiệp vào cách tôi sắp xếp phòng của mình.","Tuyết dày đã cản trở hành trình vượt núi của chúng tôi."]'::jsonb, 1, 'His phony smile disappeared as soon as we left. → Nụ cười giả tạo của anh ta biến mất ngay khi chúng tôi rời đi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_7', 'en-c1-6', NULL, 'comprehensive_test', 'listening', 'microcosm', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["an ủi; vỗ về ai đó đang buồn bã hoặc thất vọng","cho là; đánh giá là; coi là","buổi biểu diễn độc tấu; buổi biểu diễn hòa nhạc nhỏ","hình thu nhỏ; thế giới thu nhỏ"]'::jsonb, 3, 'microcosm (/ˈmaɪkroʊkɑːzəm/) → hình thu nhỏ; thế giới thu nhỏ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_8', 'en-c1-6', NULL, 'comprehensive_test', 'listening', 'The painting in the shop was a forgery.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà hàng đó đã mang tiếng xấu vì căn bếp bẩn thỉu.","Nụ cười giả tạo của anh ta biến mất ngay khi chúng tôi rời đi.","Một người hòa giải đã giúp hàng xóm của chúng tôi giải quyết tranh chấp về hàng rào vườn.","Bức tranh trong cửa hàng hóa ra là một món đồ giả mạo."]'::jsonb, 3, 'The painting in the shop was a forgery. → Bức tranh trong cửa hàng hóa ra là một món đồ giả mạo.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_9', 'en-c1-6', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To be the parts that form a whole”?', '["constitute","calamity","notoriety","vow"]'::jsonb, 0, 'constitute (/ˈkɑːnstɪtuːt/) → cấu thành; tạo thành', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_10', 'en-c1-6', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Not genuine, or intended to deceive people”?', '["phony","commune","reconcile","obnoxious"]'::jsonb, 0, 'phony (/ˈfoʊni/) → giả mạo; giả tạo', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_11', 'en-c1-6', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A small system showing the features of a larger one.”?', '["forgery","microcosm","hinder","phony"]'::jsonb, 1, 'microcosm (/ˈmaɪkroʊkɑːzəm/) → hình thu nhỏ; thế giới thu nhỏ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_12', 'en-c1-6', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Making illegal copies of documents or artworks; such a copy.”?', '["phony","obnoxious","prevailing","forgery"]'::jsonb, 3, 'forgery (/ˈfɔːrdʒəri/) → sự làm giả; tài liệu giả; vật giả mạo', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_13', 'en-c1-6', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Dishonest behaviour intended to make someone believe something false.”?', '["microcosm","instrumental","deceit","constitute"]'::jsonb, 2, 'deceit (/dɪˈsiːt/) → sự dối trá; hành vi lừa gạt', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
