INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_18', 'en-c1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Shared public spaces can help build cohesive communities by encouraging interaction among people from different backgrounds.', 'Dựa vào câu trên, từ “cohesive” có nghĩa phù hợp nhất là gì?', '["giành chiến thắng; thắng lợi","chính trực; đúng đắn về mặt đạo đức","chuyển thể thành kịch","có tính gắn kết chặt chẽ, đoàn kết"]'::jsonb, 3, 'cohesive: có tính gắn kết chặt chẽ, đoàn kết. Dịch cả câu: Không gian công cộng chung có thể giúp xây dựng các cộng đồng gắn kết bằng cách khuyến khích sự tương tác giữa những người có hoàn cảnh khác nhau.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_19', 'en-c1-6', NULL, 'comprehensive_test', 'reading', NULL, 'The manipulation of survey results can mislead policymakers and reduce public trust in scientific research.', 'Dựa vào câu trên, từ “manipulation” có nghĩa phù hợp nhất là gì?', '["phát triển mạnh mẽ; phát đạt","khao khát; thèm thuồng","sự thao túng; sự điều khiển (kiểm soát con người hoặc tình huống một cách không công bằng vì lợi ích cá nhân)","nghiêm trọng; ảm đạm; ít mang lại hy vọng"]'::jsonb, 2, 'manipulation: sự thao túng; sự điều khiển (kiểm soát con người hoặc tình huống một cách không công bằng vì lợi ích cá nhân); sự vận dụng; sự thao tác (di chuyển hoặc điều chỉnh cái gì đó một cách cẩn thận, thường dùng tay hoặc công cụ). Dịch cả câu: Việc thao túng kết quả khảo sát có thể làm các nhà hoạch định chính sách hiểu sai và làm giảm lòng tin của công chúng vào nghiên cứu khoa học.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_20', 'en-c1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Advertisements often flatter consumers by suggesting that choosing a particular product demonstrates intelligence or good taste.', 'Dựa vào câu trên, từ “flatter” có nghĩa phù hợp nhất là gì?', '["nịnh hót; nịnh bợ (ca ngợi ai đó, thường là không thành thật, để lấy lòng)","phát triển mạnh; hưng thịnh","hướng vào trong; đi về phía trung tâm","râu (của động vật)"]'::jsonb, 0, 'flatter: nịnh hót; nịnh bợ (ca ngợi ai đó, thường là không thành thật, để lấy lòng); làm cho hãnh diện; làm cho vinh hạnh (kém theo sự quan tâm hoặc lời khen khiến ai đó cảm thấy vui); làm cho tôn dáng; làm cho đẹp hơn (làm cho ai đó trông hấp dẫn hơn thực tế). Dịch cả câu: Quảng cáo thường nịnh bợ người tiêu dùng bằng cách gợi ý rằng việc chọn một sản phẩm cụ thể thể hiện sự thông minh hoặc gu thẩm mỹ tốt.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_21', 'en-c1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Parents who constantly meddle in their children''s decisions may prevent them from developing confidence and independence.', 'Dựa vào câu trên, từ “meddle” có nghĩa phù hợp nhất là gì?', '["can thiệp; xen vào","sự chiếm ưu thế; vị thế thống trị","cấp bách, hết sức quan trọng, bắt buộc","khuôn mẫu; định kiến"]'::jsonb, 0, 'meddle: can thiệp; xen vào. Dịch cả câu: Các bậc phụ huynh thường xuyên can thiệp vào quyết định của con cái có thể khiến trẻ khó phát triển sự tự tin và tính độc lập.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_22', 'en-c1-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cản trở; gây khó khăn”', '["jingle","hinder","oasis","longing"]'::jsonb, 1, 'cản trở; gây khó khăn → hinder (/ˈhɪndər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_23', 'en-c1-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự thay đổi hoàn toàn; sự cải tạo; sự chuyển đổi”', '["hind","scalpel","safeguard","transformation"]'::jsonb, 3, 'sự thay đổi hoàn toàn; sự cải tạo; sự chuyển đổi → transformation (/ˌtrænsfɚˈmeɪʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_6_24', 'en-c1-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lời thề; lời hứa chắc chắn”', '["remnant","premier","vow","degrade"]'::jsonb, 2, 'lời thề; lời hứa chắc chắn → vow (/vaʊ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-7', 'en', 'Bài 7: Xã hội & Cộng đồng (2) - CEFR C1', 'CEFR C1', 'C1 · Xã hội', '28 từ vựng Tiếng Anh CEFR C1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5007, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amends', 'en-c1-7', 'amends', '/əˈmendz/', 'C1', 'sự đền bù; sự tạ lỗi', 'n.', 'amend (v.), amendment (n.)', 'Đồng nghĩa: reparation, compensation', 'Danh từ thường dùng trong cụm make amends; không dùng an amends.', 'I baked her a cake to make amends.', NULL, 'Tôi đã nướng cho cô ấy một cái bánh để tạ lỗi.', '{"wordId":"amends","ukIpa":"/əˈmendz/","usIpa":"/əˈmendz/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Something done to repair harm or show regret.","vi":"sự đền bù; sự tạ lỗi"}],"examples":[{"en":"I baked her a cake to make amends.","vi":"Tôi đã nướng cho cô ấy một cái bánh để tạ lỗi.","audioKind":"ex"},{"en":"Companies should make amends for environmental damage by restoring habitats and compensating affected communities.","vi":"Các doanh nghiệp nên đền bù những tổn hại về môi trường bằng cách phục hồi các môi trường sống và bồi thường cho các cộng đồng bị ảnh hưởng.","audioKind":"ex2"}],"collocations":[{"en":"make amends","vi":"đền bù; tạ lỗi"},{"en":"make amends for a mistake","vi":"chuộc lỗi lầm"},{"en":"make amends to someone","vi":"tạ lỗi với ai đó"}],"wordFamily":["amend (v.)","amendment (n.)"],"synonyms":["reparation","compensation"],"antonyms":[],"tipVi":"Danh từ thường dùng trong cụm make amends; không dùng an amends.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_converse', 'en-c1-7', 'converse', '/kənˈvɝːs/', 'C1', 'trò chuyện; đàm đạo', 'v.', 'conversation (n.), conversational (adj.), conversationalist (n.)', 'Đồng nghĩa: talk, chat', 'Trọng âm động từ rơi vào âm tiết sau; danh từ mang nghĩa ''chiều ngược lại'' có trọng âm rơi vào âm tiết đầu.', 'We conversed quietly while waiting for the train.', NULL, 'Chúng tôi trò chuyện khẽ với nhau trong lúc đợi tàu.', '{"wordId":"converse","ukIpa":"/kənˈvɜːs/","usIpa":"/kənˈvɝːs/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To talk with someone and exchange thoughts.","vi":"trò chuyện; đàm đạo"}],"examples":[{"en":"We conversed quietly while waiting for the train.","vi":"Chúng tôi trò chuyện khẽ với nhau trong lúc đợi tàu.","audioKind":"ex"},{"en":"Language exchange programmes allow students to converse with native speakers and develop confidence in unfamiliar social situations.","vi":"Các chương trình trao đổi ngôn ngữ cho phép học sinh trò chuyện với người bản xứ và phát triển sự tự tin trong các tình huống giao tiếp xã hội xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"converse with someone","vi":"trò chuyện với ai đó"},{"en":"converse in English","vi":"trò chuyện bằng tiếng Anh"},{"en":"converse about a topic","vi":"trò chuyện về một chủ đề"}],"wordFamily":["conversation (n.)","conversational (adj.)","conversationalist (n.)"],"synonyms":["talk","chat"],"antonyms":[],"tipVi":"Trọng âm động từ rơi vào âm tiết sau; danh từ mang nghĩa ''chiều ngược lại'' có trọng âm rơi vào âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brink', 'en-c1-7', 'brink', '/brɪŋk/', 'C1', 'bờ vực; nguy cơ cận kề; cạnh vách đá; bờ vực thẳm', 'n.', NULL, 'Đồng nghĩa: verge, edge', 'Cụm on the brink of thường đi kèm với danh từ hoặc danh động từ, hay dùng để chỉ tình trạng khủng hoảng.', 'Their little shop was on the brink of closing.', NULL, 'Cửa hàng nhỏ của họ suýt chút nữa là phải đóng cửa.', '{"wordId":"brink","ukIpa":"/brɪŋk/","usIpa":"/brɪŋk/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A point just before something happens, especially something bad.","vi":"bờ vực; nguy cơ cận kề"},{"pos":"n.","en":"The edge of a cliff or steep drop.","vi":"cạnh vách đá; bờ vực thẳm"}],"examples":[{"en":"Their little shop was on the brink of closing.","vi":"Cửa hàng nhỏ của họ suýt chút nữa là phải đóng cửa.","audioKind":"ex"},{"en":"Prolonged drought has pushed several rural communities to the brink of a severe food crisis.","vi":"Hạn hán kéo dài đã đẩy một số cộng đồng nông thôn đến bờ vực của một cuộc khủng hoảng lương thực nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"on the brink of collapse","vi":"bên bờ vực phá sản"},{"en":"bring back from the brink","vi":"kéo lại từ bờ vực thẳm"},{"en":"push to the brink","vi":"đẩy đến bờ vực hiểm nghèo"}],"wordFamily":[],"synonyms":["verge","edge"],"antonyms":[],"tipVi":"Cụm on the brink of thường đi kèm với danh từ hoặc danh động từ, hay dùng để chỉ tình trạng khủng hoảng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shun', 'en-c1-7', 'shun', '/ʃʌn/', 'C1', 'cố tình tránh xa; xa lánh', 'v.', NULL, 'Đồng nghĩa: avoid, eschew · Trái nghĩa: embrace', 'Là ngoại động từ, trực tiếp đi kèm tân ngữ; dạng quá khứ là shunned.', 'My neighbours shun crowded shops and buy food online.', NULL, 'Những người hàng xóm của tôi tránh các cửa hàng đông đúc và mua thực phẩm trực tuyến.', '{"wordId":"shun","ukIpa":"/ʃʌn/","usIpa":"/ʃʌn/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To deliberately avoid someone or something.","vi":"cố tình tránh xa; xa lánh"}],"examples":[{"en":"My neighbours shun crowded shops and buy food online.","vi":"Những người hàng xóm của tôi tránh các cửa hàng đông đúc và mua thực phẩm trực tuyến.","audioKind":"ex"},{"en":"Some graduates shun corporate careers because they value personal independence more than a high salary.","vi":"Một số sinh viên tốt nghiệp né tránh các công việc doanh nghiệp vì họ coi trọng sự độc lập cá nhân hơn là mức lương cao.","audioKind":"ex2"}],"collocations":[{"en":"shun publicity","vi":"tránh né sự chú ý của công chúng"},{"en":"shun responsibility","vi":"trốn tránh trách nhiệm"},{"en":"shun society","vi":"lánh đời"}],"wordFamily":[],"synonyms":["avoid","eschew"],"antonyms":["embrace"],"tipVi":"Là ngoại động từ, trực tiếp đi kèm tân ngữ; dạng quá khứ là shunned.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_molest', 'en-c1-7', 'molest', '/məˈlest/', 'C1', 'quấy rối tình dục; lạm dụng tình dục; quấy rầy; hành hung', 'v.', 'molestation (n.), molester (n.), unmolested (adj.)', NULL, 'Trong tiếng Anh hiện đại, từ này chủ yếu chỉ hành vi quấy rối tình dục, không dùng để chỉ việc làm phiền thông thường.', 'The club bans anyone who tries to molest guests.', NULL, 'Câu lạc bộ cấm cửa bất kỳ ai có hành vi cố gắng quấy rối khách tham quan.', '{"wordId":"molest","ukIpa":"/məˈlest/","usIpa":"/məˈlest/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To subject someone to unwanted sexual touching or behaviour.","vi":"quấy rối tình dục; lạm dụng tình dục"},{"pos":"v.","en":"To bother or attack someone, especially in older usage.","vi":"quấy rầy; hành hung"}],"examples":[{"en":"The club bans anyone who tries to molest guests.","vi":"Câu lạc bộ cấm cửa bất kỳ ai có hành vi cố gắng quấy rối khách tham quan.","audioKind":"ex"},{"en":"Public transport authorities should provide clear reporting procedures for passengers targeted by individuals who molest others.","vi":"Các cơ quan quản lý giao thông công cộng nên cung cấp các quy trình báo cáo rõ ràng cho những hành khách là mục tiêu của kẻ có hành vi quấy rối.","audioKind":"ex2"}],"collocations":[{"en":"molest someone","vi":"quấy rối ai đó"},{"en":"sexually molest","vi":"thực hiện hành vi quấy rối tình dục"}],"wordFamily":["molestation (n.)","molester (n.)","unmolested (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh hiện đại, từ này chủ yếu chỉ hành vi quấy rối tình dục, không dùng để chỉ việc làm phiền thông thường.","noteVi":"Từ nhạy cảm liên quan đến lạm dụng tình dục; không mang nghĩa ''làm phiền'' thông thường.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_miser', 'en-c1-7', 'miser', '/ˈmaɪzər/', 'C1', 'kẻ hà tiện; người keo kiệt', 'n.', 'miserly (adj.), miserliness (n.)', 'Đồng nghĩa: cheapskate', 'Mang sắc thái tiêu cực, chỉ người không đành lòng tiêu tiền, không đồng nghĩa với người tiết kiệm.', 'That miser refuses to replace his broken kitchen chair.', NULL, 'Tên hà tiện đó nhất định không chịu thay chiếc ghế bếp đã hỏng của mình.', '{"wordId":"miser","ukIpa":"/ˈmaɪzə/","usIpa":"/ˈmaɪzər/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Someone who hoards money and strongly dislikes spending it.","vi":"kẻ hà tiện; người keo kiệt"}],"examples":[{"en":"That miser refuses to replace his broken kitchen chair.","vi":"Tên hà tiện đó nhất định không chịu thay chiếc ghế bếp đã hỏng của mình.","audioKind":"ex"},{"en":"Literature often portrays the miser as someone whose attachment to wealth damages relationships and personal happiness.","vi":"Văn học thường khắc họa kẻ keo kiệt là một người có sự bám chấp vào tài sản làm tổn hại đến các mối quan hệ và hạnh phúc cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"a wealthy miser","vi":"một kẻ keo kiệt giàu có"},{"en":"an old miser","vi":"lão hà tiện"},{"en":"a notorious miser","vi":"kẻ keo kiệt khét tiếng"}],"wordFamily":["miserly (adj.)","miserliness (n.)"],"synonyms":["cheapskate"],"antonyms":[],"tipVi":"Mang sắc thái tiêu cực, chỉ người không đành lòng tiêu tiền, không đồng nghĩa với người tiết kiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fidelity', 'en-c1-7', 'fidelity', '/fɪˈdeləti/', 'C1', 'sự trung thành; lòng trung thực; độ chính xác; độ trung thực (âm thanh, hình ảnh)', 'n.', 'infidelity (n.)', 'Đồng nghĩa: loyalty, faithfulness · Trái nghĩa: infidelity', 'Sự trung thành với ai hoặc nguyên tắc dùng fidelity to; thường là danh từ không đếm được.', 'The couple promised lifelong fidelity during their wedding.', NULL, 'Cặp đôi đã hứa hẹn sự trung thủy trọn đời trong đám cưới của họ.', '{"wordId":"fidelity","ukIpa":"/fɪˈdeləti/","usIpa":"/fɪˈdeləti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"continued loyalty to a person, belief, or duty","vi":"sự trung thành; lòng trung thực"},{"pos":"n.","en":"the accuracy with which something reproduces an original","vi":"độ chính xác; độ trung thực (âm thanh, hình ảnh)"}],"examples":[{"en":"The couple promised lifelong fidelity during their wedding.","vi":"Cặp đôi đã hứa hẹn sự trung thủy trọn đời trong đám cưới của họ.","audioKind":"ex"},{"en":"Digital archives must maintain the fidelity of original recordings so that researchers can study them accurately.","vi":"Các kho lưu trữ kỹ thuật số phải duy trì độ trung thực của các bản ghi âm gốc để các nhà nghiên cứu có thể nghiên cứu chúng một cách chính xác.","audioKind":"ex2"}],"collocations":[{"en":"fidelity to principles","vi":"sự trung thành với nguyên tắc"},{"en":"marital fidelity","vi":"sự chung thủy trong hôn nhân"},{"en":"high fidelity","vi":"độ trung thực cao"},{"en":"fidelity to the original","vi":"sự trung thành với bản gốc"}],"wordFamily":["infidelity (n.)"],"synonyms":["loyalty","faithfulness"],"antonyms":["infidelity"],"tipVi":"Sự trung thành với ai hoặc nguyên tắc dùng fidelity to; thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mobilize', 'en-c1-7', 'mobilize', '/ˈmoʊbəlaɪz/', 'C1', 'huy động; điều động; động viên lực lượng; chuẩn bị chiến đấu', 'v.', 'mobilization (n.)', 'Đồng nghĩa: rally, organize · Trái nghĩa: demobilize', 'Trong tiếng Anh-Anh thường viết là mobilise; thường kết hợp với nguồn lực, lực lượng ủng hộ hoặc quân đội.', 'Our neighbours mobilized volunteers to clean the local beach.', NULL, 'Những người hàng xóm của chúng tôi đã huy động các tình nguyện viên để dọn dẹp bãi biển địa phương.', '{"wordId":"mobilize","ukIpa":"/ˈməʊbəlaɪz/","usIpa":"/ˈmoʊbəlaɪz/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To organize people or resources for a particular purpose","vi":"huy động; điều động"},{"pos":"v.","en":"To prepare troops for military action","vi":"động viên lực lượng; chuẩn bị chiến đấu"}],"examples":[{"en":"Our neighbours mobilized volunteers to clean the local beach.","vi":"Những người hàng xóm của chúng tôi đã huy động các tình nguyện viên để dọn dẹp bãi biển địa phương.","audioKind":"ex"},{"en":"Governments must mobilize financial resources and trained staff quickly when natural disasters threaten vulnerable communities.","vi":"Các chính phủ phải nhanh chóng huy động nguồn lực tài chính và nhân lực được đào tạo khi thiên tai đe dọa các cộng đồng dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"mobilize resources","vi":"huy động nguồn lực"},{"en":"mobilize support","vi":"động viên sự ủng hộ"},{"en":"mobilize volunteers","vi":"huy động tình nguyện viên"},{"en":"mobilize troops","vi":"động viên quân đội"}],"wordFamily":["mobilization (n.)"],"synonyms":["rally","organize"],"antonyms":["demobilize"],"tipVi":"Trong tiếng Anh-Anh thường viết là mobilise; thường kết hợp với nguồn lực, lực lượng ủng hộ hoặc quân đội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_superiority', 'en-c1-7', 'superiority', '/suːˌpɪriˈɔːrəti/', 'C1', 'tính ưu việt; thế vượt trội; thái độ trịch thượng; sự kiêu ngạo', 'n.', 'superior (adj.)', 'Trái nghĩa: inferiority', 'Khi diễn tả sự vượt trội hơn so với cái gì, dùng superiority over thay vì than.', 'The newer camera showed its superiority in low light.', NULL, 'Chiếc máy ảnh đời mới hơn đã thể hiện rõ ưu điểm của nó trong điều kiện ánh sáng yếu.', '{"wordId":"superiority","ukIpa":"/suːˌpɪəriˈɒrəti/","usIpa":"/suːˌpɪriˈɔːrəti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The state of being better or stronger than something else.","vi":"tính ưu việt; thế vượt trội"},{"pos":"n.","en":"An attitude of believing yourself better than other people.","vi":"thái độ trịch thượng; sự kiêu ngạo"}],"examples":[{"en":"The newer camera showed its superiority in low light.","vi":"Chiếc máy ảnh đời mới hơn đã thể hiện rõ ưu điểm của nó trong điều kiện ánh sáng yếu.","audioKind":"ex"},{"en":"The technological superiority of larger firms can make it difficult for small businesses to compete effectively.","vi":"Lợi thế công nghệ của các công ty lớn có thể khiến các doanh nghiệp nhỏ khó cạnh tranh hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"technological superiority","vi":"lợi thế công nghệ"},{"en":"superiority over","vi":"sự vượt trội hơn..."},{"en":"a sense of superiority","vi":"cảm giác tự mãn"}],"wordFamily":["superior (adj.)"],"synonyms":[],"antonyms":["inferiority"],"tipVi":"Khi diễn tả sự vượt trội hơn so với cái gì, dùng superiority over thay vì than.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ridicule', 'en-c1-7', 'ridicule', '/ˈrɪdɪkjuːl/', 'C1', 'sự chế nhạo; lời mỉa mai; chế giễu; nhạo báng', 'n.', 'ridiculous (adj.), ridiculously (adv.)', 'Đồng nghĩa: mockery, mock', 'Khi đóng vai trò là động từ, từ này là ngoại động từ nên đi thẳng với tân ngữ mà không cần giới từ at.', 'His unusual hat attracted ridicule from a few classmates.', NULL, 'Chiếc mũ kỳ lạ của anh ấy đã thu hút những lời chế giễu từ một vài bạn cùng lớp.', '{"wordId":"ridicule","ukIpa":"/ˈrɪdɪkjuːl/","usIpa":"/ˈrɪdɪkjuːl/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Unkind laughter or comments that make someone seem foolish.","vi":"sự chế nhạo; lời mỉa mai"},{"pos":"v.","en":"To laugh at someone or something in an unkind way.","vi":"chế giễu; nhạo báng"}],"examples":[{"en":"His unusual hat attracted ridicule from a few classmates.","vi":"Chiếc mũ kỳ lạ của anh ấy đã thu hút những lời chế giễu từ một vài bạn cùng lớp.","audioKind":"ex"},{"en":"Students may avoid asking important questions if they fear ridicule from their teachers or classmates.","vi":"Học sinh có thể tránh đặt những câu hỏi quan trọng nếu các em sợ bị giáo viên hoặc bạn bè chế giễu.","audioKind":"ex2"}],"collocations":[{"en":"public ridicule","vi":"sự chế giễu công khai"},{"en":"face ridicule","vi":"gánh chịu sự nhạo báng"},{"en":"subject someone to ridicule","vi":"làm cho ai đó trở thành trò cười"}],"wordFamily":["ridiculous (adj.)","ridiculously (adv.)"],"synonyms":["mockery","mock"],"antonyms":[],"tipVi":"Khi đóng vai trò là động từ, từ này là ngoại động từ nên đi thẳng với tân ngữ mà không cần giới từ at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bona-fide', 'en-c1-7', 'bona fide', '/ˌboʊnə ˈfaɪdi/', 'C1', 'thật; chân thực; đích thực; thành tâm; thiện chí', 'adj.', NULL, 'Đồng nghĩa: genuine, authentic · Trái nghĩa: fake, fraudulent', 'Từ này khá trang trọng, thường đứng trước danh từ để nhấn mạnh tính chân thực hoặc thiện chí.', 'An expert confirmed that the painting was bona fide.', NULL, 'Một chuyên gia đã xác nhận rằng bức tranh là tác phẩm thật.', '{"wordId":"bona-fide","ukIpa":"/ˌbəʊnə ˈfaɪdi/","usIpa":"/ˌboʊnə ˈfaɪdi/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Real or genuine, rather than false or pretended.","vi":"thật; chân thực; đích thực"},{"pos":"adj.","en":"Made or done honestly, without intending to deceive.","vi":"thành tâm; thiện chí"}],"examples":[{"en":"An expert confirmed that the painting was bona fide.","vi":"Một chuyên gia đã xác nhận rằng bức tranh là tác phẩm thật.","audioKind":"ex"},{"en":"Universities should ensure that financial support reaches bona fide students who genuinely need assistance.","vi":"Các trường đại học nên đảm bảo rằng hỗ trợ tài chính đến được với đúng sinh viên đích thực, những người thực sự cần giúp đỡ.","audioKind":"ex2"}],"collocations":[{"en":"a bona fide student","vi":"sinh viên có thật"},{"en":"a bona fide offer","vi":"một đề nghị thành tâm"},{"en":"a bona fide organisation","vi":"một tổ chức hợp pháp chân chính"}],"wordFamily":[],"synonyms":["genuine","authentic"],"antonyms":["fake","fraudulent"],"tipVi":"Từ này khá trang trọng, thường đứng trước danh từ để nhấn mạnh tính chân thực hoặc thiện chí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snobbish', 'en-c1-7', 'snobbish', '/ˈsnɑːbɪʃ/', 'C1', 'hách dịch; kẻ cả; mang tính coi thường người khác vì vị thế hay sự giàu có', 'adj.', 'snob (n.), snobbery (n.), snobbishly (adv.)', 'Đồng nghĩa: supercilious, elitist · Trái nghĩa: unpretentious', 'Tập trung vào việc nhìn xuống người khác do địa vị hoặc gu thẩm mỹ, không nhất thiết là sự nịnh bợ.', 'Her snobbish neighbour refused to visit our small flat.', NULL, 'Người hàng xóm hách dịch của cô ấy đã từ chối đến thăm căn hộ nhỏ của chúng tôi.', '{"wordId":"snobbish","ukIpa":"/ˈsnɒbɪʃ/","usIpa":"/ˈsnɑːbɪʃ/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Treating others as inferior because of status, wealth, or taste.","vi":"hách dịch; kẻ cả; mang tính coi thường người khác vì vị thế hay sự giàu có"}],"examples":[{"en":"Her snobbish neighbour refused to visit our small flat.","vi":"Người hàng xóm hách dịch của cô ấy đã từ chối đến thăm căn hộ nhỏ của chúng tôi.","audioKind":"ex"},{"en":"Snobbish attitudes towards vocational training can discourage young people from pursuing valuable practical careers.","vi":"Thái độ coi thường đào tạo nghề có thể khiến giới trẻ nản lòng không muốn theo đuổi các nghề nghiệp thực tế có giá trị.","audioKind":"ex2"}],"collocations":[{"en":"a snobbish attitude","vi":"thái độ hách dịch"},{"en":"snobbish about clothes","vi":"tỏ ra sang chảnh về trang phục"},{"en":"snobbish behaviour","vi":"hành vi kẻ cả"}],"wordFamily":["snob (n.)","snobbery (n.)","snobbishly (adv.)"],"synonyms":["supercilious","elitist"],"antonyms":["unpretentious"],"tipVi":"Tập trung vào việc nhìn xuống người khác do địa vị hoặc gu thẩm mỹ, không nhất thiết là sự nịnh bợ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_provocation', 'en-c1-7', 'provocation', '/ˌprɑːvəˈkeɪʃən/', 'C1', 'sự khiêu khích; sự chọc tức', 'n.', 'provoke (v.), provocative (adj.), provocatively (adv.)', 'Đồng nghĩa: incitement', 'Thường chỉ sự khiêu khích gây phẫn nộ, không nên dịch chung chung thành kích thích thông thường.', 'Despite the provocation, Amir stayed calm and walked away.', NULL, 'Mặc dù bị khiêu khích, Amir vẫn giữ bình tĩnh và bỏ đi.', '{"wordId":"provocation","ukIpa":"/ˌprɒvəˈkeɪʃən/","usIpa":"/ˌprɑːvəˈkeɪʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"behaviour intended or likely to cause anger or a reaction","vi":"sự khiêu khích; sự chọc tức"}],"examples":[{"en":"Despite the provocation, Amir stayed calm and walked away.","vi":"Mặc dù bị khiêu khích, Amir vẫn giữ bình tĩnh và bỏ đi.","audioKind":"ex"},{"en":"Teaching children to respond calmly to provocation can reduce conflict and promote a more supportive school environment.","vi":"Dạy trẻ em cách phản ứng bình tĩnh trước sự khiêu khích có thể làm giảm xung đột và thúc đẩy môi trường học đường hỗ trợ lẫn nhau hơn.","audioKind":"ex2"}],"collocations":[{"en":"without provocation","vi":"không có sự khiêu khích"},{"en":"deliberate provocation","vi":"sự khiêu khích có chủ ý"},{"en":"respond to provocation","vi":"đáp trả sự khiêu khích"}],"wordFamily":["provoke (v.)","provocative (adj.)","provocatively (adv.)"],"synonyms":["incitement"],"antonyms":[],"tipVi":"Thường chỉ sự khiêu khích gây phẫn nộ, không nên dịch chung chung thành kích thích thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dishonorable', 'en-c1-7', 'dishonorable', '/dɪsˈɑːnərəbl/', 'C1', 'đáng xấu hổ; không quang minh chính đại', 'adj.', 'dishonor (n.), dishonor (v.), dishonorably (adv.), honorable (adj.)', 'Đồng nghĩa: disgraceful, shameful · Trái nghĩa: honorable', 'Mỹ thức viết là dishonorable; Anh thức thường viết là dishonourable.', 'He felt that cheating at cards was dishonorable.', NULL, 'Anh ấy cảm thấy việc gian lận bài bạc là một hành động đáng xấu hổ.', '{"wordId":"dishonorable","ukIpa":"/dɪsˈɒnərəbl/","usIpa":"/dɪsˈɑːnərəbl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"deserving disapproval because of dishonest or unfair behaviour","vi":"đáng xấu hổ; không quang minh chính đại"}],"examples":[{"en":"He felt that cheating at cards was dishonorable.","vi":"Anh ấy cảm thấy việc gian lận bài bạc là một hành động đáng xấu hổ.","audioKind":"ex"},{"en":"Dishonorable conduct by public officials can weaken trust in institutions and discourage citizens from participating in politics.","vi":"Hành vi vô đạo đức của các quan chức công quyền có thể làm suy yếu niềm tin vào các thiết chế và làm nhụt chí công dân tham gia vào chính trị.","audioKind":"ex2"}],"collocations":[{"en":"dishonorable conduct","vi":"hành vi đáng xấu hổ"},{"en":"dishonorable intentions","vi":"ý đồ bất chính"},{"en":"dishonorable discharge","vi":"buộc xuất ngũ vì kỷ luật kém"}],"wordFamily":["dishonor (n.)","dishonor (v.)","dishonorably (adv.)","honorable (adj.)"],"synonyms":["disgraceful","shameful"],"antonyms":["honorable"],"tipVi":"Mỹ thức viết là dishonorable; Anh thức thường viết là dishonourable.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_liberal', 'en-c1-7', 'liberal', '/ˈlɪbərəl/', 'C1', 'cởi mở; khoáng đạt; tôn trọng sự khác biệt; thuộc chủ nghĩa tự do; rộng rãi; hào phóng; số lượng lớn', 'adj.', 'liberally (adv.), liberalism (n.), liberalise (v.), liberalisation (n.)', 'Đồng nghĩa: open-minded, tolerant · Trái nghĩa: illiberal', 'Ý nghĩa chính trị thay đổi theo quốc gia; cũng có thể biểu thị tư tưởng cởi mở hoặc số lượng dồi dào.', 'My parents are liberal about what clothes I wear.', NULL, 'Cha mẹ tôi rất cởi mở về trang phục mà tôi mặc.', '{"wordId":"liberal","ukIpa":"/ˈlɪbərəl/","usIpa":"/ˈlɪbərəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Accepting different opinions and supporting people''s freedom to choose.","vi":"cởi mở; khoáng đạt; tôn trọng sự khác biệt"},{"pos":"adj.","en":"Supporting political principles that protect individual rights and freedoms.","vi":"thuộc chủ nghĩa tự do"},{"pos":"adj.","en":"Given or used generously, often in large amounts.","vi":"rộng rãi; hào phóng; số lượng lớn"}],"examples":[{"en":"My parents are liberal about what clothes I wear.","vi":"Cha mẹ tôi rất cởi mở về trang phục mà tôi mặc.","audioKind":"ex"},{"en":"A liberal society should protect individual freedoms while encouraging citizens to respect the rights of others.","vi":"Một xã hội cởi mở và tự do nên bảo vệ các quyền tự do cá nhân đồng thời khuyến khích công dân tôn trọng quyền của người khác.","audioKind":"ex2"}],"collocations":[{"en":"liberal attitudes","vi":"thái độ cởi mở"},{"en":"liberal democracy","vi":"chế độ dân chủ tự do"},{"en":"a liberal amount of","vi":"một lượng lớn"}],"wordFamily":["liberally (adv.)","liberalism (n.)","liberalise (v.)","liberalisation (n.)"],"synonyms":["open-minded","tolerant"],"antonyms":["illiberal"],"tipVi":"Ý nghĩa chính trị thay đổi theo quốc gia; cũng có thể biểu thị tư tưởng cởi mở hoặc số lượng dồi dào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_predominance', 'en-c1-7', 'predominance', '/prɪˈdɑːmɪnəns/', 'C1', 'sự chiếm ưu thế; vị thế thống trị', 'n.', 'predominant (adj.), predominantly (adv.), predominate (v.)', 'Đồng nghĩa: dominance, preponderance', 'Nhấn mạnh sự áp đảo về số lượng, sức mạnh hoặc tầm ảnh hưởng, không đồng nghĩa với sự xuất sắc.', 'The predominance of blue gives this room a cool feel.', NULL, 'Sự bao trùm của sắc xanh mang lại cho căn phòng này cảm giác mát mẻ.', '{"wordId":"predominance","ukIpa":"/prɪˈdɒmɪnəns/","usIpa":"/prɪˈdɑːmɪnəns/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The state of being most numerous, powerful, or influential.","vi":"sự chiếm ưu thế; vị thế thống trị"}],"examples":[{"en":"The predominance of blue gives this room a cool feel.","vi":"Sự bao trùm của sắc xanh mang lại cho căn phòng này cảm giác mát mẻ.","audioKind":"ex"},{"en":"The predominance of private cars in urban transport creates challenges for efforts to reduce air pollution.","vi":"Việc xe hơi cá nhân chiếm ưu thế trong giao thông đô thị đã tạo ra nhiều thách thức cho các nỗ lực giảm thiểu ô nhiễm không khí.","audioKind":"ex2"}],"collocations":[{"en":"a predominance of","vi":"sự chiếm đa số của"},{"en":"economic predominance","vi":"vị thế thống trị về kinh tế"},{"en":"predominance over","vi":"sự vượt trội hơn so với"}],"wordFamily":["predominant (adj.)","predominantly (adv.)","predominate (v.)"],"synonyms":["dominance","preponderance"],"antonyms":[],"tipVi":"Nhấn mạnh sự áp đảo về số lượng, sức mạnh hoặc tầm ảnh hưởng, không đồng nghĩa với sự xuất sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_permissive', 'en-c1-7', 'permissive', '/pɚˈmɪsɪv/', 'C1', 'dễ dãi; buông lỏng; phóng khoáng', 'adj.', 'permit (v.), permission (n.), permissiveness (n.), permissible (adj.)', 'Đồng nghĩa: lenient, indulgent · Trái nghĩa: strict, restrictive', 'Từ "permissive" mang nghĩa dễ dãi/buông lỏng, trong khi "permissible" mới có nghĩa là được phép.', 'His permissive parents rarely object to late bedtimes.', NULL, 'Cha mẹ dễ dãi của cậu ấy hiếm khi phản đối việc cậu đi ngủ muộn.', '{"wordId":"permissive","ukIpa":"/pəˈmɪsɪv/","usIpa":"/pɚˈmɪsɪv/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Allowing considerable freedom rather than enforcing strict rules.","vi":"dễ dãi; buông lỏng; phóng khoáng"}],"examples":[{"en":"His permissive parents rarely object to late bedtimes.","vi":"Cha mẹ dễ dãi của cậu ấy hiếm khi phản đối việc cậu đi ngủ muộn.","audioKind":"ex"},{"en":"A permissive approach to parenting may encourage independence, but children still need clear boundaries.","vi":"Phương pháp giáo dục con cái theo hướng dễ dãi có thể khuyến khích sự độc lập, nhưng trẻ em vẫn cần những ranh giới rõ ràng.","audioKind":"ex2"}],"collocations":[{"en":"permissive parenting","vi":"phương pháp nuôi dạy con cái dễ dãi"},{"en":"permissive society","vi":"xã hội có lối sống phóng khoáng"},{"en":"permissive attitude","vi":"thái độ buông lỏng"}],"wordFamily":["permit (v.)","permission (n.)","permissiveness (n.)","permissible (adj.)"],"synonyms":["lenient","indulgent"],"antonyms":["strict","restrictive"],"tipVi":"Từ \"permissive\" mang nghĩa dễ dãi/buông lỏng, trong khi \"permissible\" mới có nghĩa là được phép.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_petty', 'en-c1-7', 'petty', '/ˈpeti/', 'C1', 'vặt vãnh; nhỏ nhặt; hẹp hòi; hay chấp vặt; nhỏ; nhẹ (tội phạm ít nghiêm trọng)', 'adj.', 'pettiness (n.)', 'Đồng nghĩa: trivial, minor · Trái nghĩa: important', 'Khi dùng để mô tả con người, từ này mang sắc thái chê bai, chỉ tính cách hẹp hòi.', 'We wasted the afternoon arguing over petty details.', NULL, 'Chúng tôi đã lãng phí cả buổi chiều để cãi nhau về những chi tiết vụn vặt.', '{"wordId":"petty","ukIpa":"/ˈpeti/","usIpa":"/ˈpeti/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Too small or unimportant to deserve much attention.","vi":"vặt vãnh; nhỏ nhặt"},{"pos":"adj.","en":"Unkindly concerned with small, unimportant matters.","vi":"hẹp hòi; hay chấp vặt"},{"pos":"adj.","en":"Relatively minor or small in scale, especially concerning crime.","vi":"nhỏ; nhẹ (tội phạm ít nghiêm trọng)"}],"examples":[{"en":"We wasted the afternoon arguing over petty details.","vi":"Chúng tôi đã lãng phí cả buổi chiều để cãi nhau về những chi tiết vụn vặt.","audioKind":"ex"},{"en":"Investment in youth services may help reduce petty crime by providing constructive activities and support.","vi":"Việc đầu tư vào các dịch vụ dành cho thanh thiếu niên có thể giúp giảm thiểu tội phạm vặt bằng cách cung cấp các hoạt động mang tính xây dựng và hỗ trợ kịp thời.","audioKind":"ex2"}],"collocations":[{"en":"petty crime","vi":"tội phạm vặt"},{"en":"petty theft","vi":"trộm cắp vặt"},{"en":"petty arguments","vi":"cuộc cãi vã vô bổ"},{"en":"petty cash","vi":"tiền quỹ vặt; quỹ tiền mặt nhỏ"}],"wordFamily":["pettiness (n.)"],"synonyms":["trivial","minor"],"antonyms":["important"],"tipVi":"Khi dùng để mô tả con người, từ này mang sắc thái chê bai, chỉ tính cách hẹp hòi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vulnerable', 'en-c1-7', 'vulnerable', '/ˈvʌlnərəbl/', 'C1', 'dễ bị tổn thương; dễ bị ảnh hưởng tiêu cực', 'adj.', 'vulnerability (n.)', 'Đồng nghĩa: unprotected, defenceless · Trái nghĩa: invulnerable', 'Thường đi với giới từ vulnerable to, theo sau to là danh từ.', 'Young plants are vulnerable to frost on cold nights.', NULL, 'Cây non rất dễ bị sương giá tàn phá vào những đêm lạnh.', '{"wordId":"vulnerable","ukIpa":"/ˈvʌlnərəbl/","usIpa":"/ˈvʌlnərəbl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Easily harmed, attacked, or negatively affected.","vi":"dễ bị tổn thương; dễ bị ảnh hưởng tiêu cực"}],"examples":[{"en":"Young plants are vulnerable to frost on cold nights.","vi":"Cây non rất dễ bị sương giá tàn phá vào những đêm lạnh.","audioKind":"ex"},{"en":"Local authorities should provide additional support for vulnerable residents during periods of extreme heat.","vi":"Chính quyền địa phương nên cung cấp thêm hỗ trợ cho những cư dân dễ bị tổn thương trong các đợt nắng nóng cực đoan.","audioKind":"ex2"}],"collocations":[{"en":"vulnerable to disease","vi":"dễ mắc bệnh"},{"en":"vulnerable groups","vi":"các nhóm dễ bị tổn thương"},{"en":"feel vulnerable","vi":"cảm thấy dễ bị tổn thương"}],"wordFamily":["vulnerability (n.)"],"synonyms":["unprotected","defenceless"],"antonyms":["invulnerable"],"tipVi":"Thường đi với giới từ vulnerable to, theo sau to là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_notorious', 'en-c1-7', 'notorious', '/noʊˈtɔːriəs/', 'C1', 'khét tiếng, mang tiếng xấu, nổi danh về điều tiêu cực', 'adj.', 'notoriously (adv.), notoriety (n.)', 'Đồng nghĩa: infamous', 'Thường mang nghĩa tiêu cực; nổi tiếng nhưng không xấu thì dùng famous, không nên dùng notorious.', 'That road is notorious for its deep potholes.', NULL, 'Con đường đó nổi tiếng là có nhiều ổ gà sâu.', '{"wordId":"notorious","ukIpa":"/nəʊˈtɔːriəs/","usIpa":"/noʊˈtɔːriəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"widely known for something bad or undesirable","vi":"khét tiếng, mang tiếng xấu, nổi danh về điều tiêu cực"}],"examples":[{"en":"That road is notorious for its deep potholes.","vi":"Con đường đó nổi tiếng là có nhiều ổ gà sâu.","audioKind":"ex"},{"en":"Cities notorious for severe air pollution often struggle to attract skilled workers and develop sustainable tourism.","vi":"Những thành phố khét tiếng vì ô nhiễm không khí nghiêm trọng thường gặp khó khăn trong việc thu hút lao động lành nghề và phát triển du lịch bền vững.","audioKind":"ex2"}],"collocations":[{"en":"notorious for","vi":"khét tiếng vì điều gì"},{"en":"notorious as","vi":"mang tiếng xấu như là"},{"en":"a notorious reputation","vi":"tiếng tăm xấu"}],"wordFamily":["notoriously (adv.)","notoriety (n.)"],"synonyms":["infamous"],"antonyms":[],"tipVi":"Thường mang nghĩa tiêu cực; nổi tiếng nhưng không xấu thì dùng famous, không nên dùng notorious.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impede', 'en-c1-7', 'impede', '/ɪmˈpiːd/', 'C1', 'cản trở, gây khó khăn cho sự di chuyển hoặc tiến độ', 'v.', 'impediment (n.)', 'Đồng nghĩa: hinder, hamper, obstruct · Trái nghĩa: facilitate', 'Nhấn mạnh việc làm cho tiến trình trở nên khó khăn hoặc chậm lại, chứ không nhất thiết là ngăn chặn hoàn toàn.', 'Fallen branches impeded our progress along the narrow path.', NULL, 'Những cành cây đổ cản trở hành trình của chúng tôi dọc theo lối đi hẹp.', '{"wordId":"impede","ukIpa":"/ɪmˈpiːd/","usIpa":"/ɪmˈpiːd/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To make movement or progress slower or more difficult.","vi":"cản trở, gây khó khăn cho sự di chuyển hoặc tiến độ"}],"examples":[{"en":"Fallen branches impeded our progress along the narrow path.","vi":"Những cành cây đổ cản trở hành trình của chúng tôi dọc theo lối đi hẹp.","audioKind":"ex"},{"en":"Limited access to reliable internet services can impede educational progress in rural communities and widen existing inequalities.","vi":"Việc khó tiếp cận dịch vụ internet ổn định có thể cản trở tiến trình giáo dục ở các cộng đồng nông thôn và làm nới rộng khoảng cách bất bình đẳng hiện hữu.","audioKind":"ex2"}],"collocations":[{"en":"impede progress","vi":"cản trở tiến độ"},{"en":"impede development","vi":"kìm hãm sự phát triển"},{"en":"impede movement","vi":"cản trở chuyển động"}],"wordFamily":["impediment (n.)"],"synonyms":["hinder","hamper","obstruct"],"antonyms":["facilitate"],"tipVi":"Nhấn mạnh việc làm cho tiến trình trở nên khó khăn hoặc chậm lại, chứ không nhất thiết là ngăn chặn hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pompous', 'en-c1-7', 'pompous', '/ˈpɑːmpəs/', 'C1', 'tự phụ; tự mãn; khoa trương', 'adj.', 'pomposity (n.), pompously (adv.)', 'Đồng nghĩa: self-important, pretentious · Trái nghĩa: humble, modest', 'Mang sắc thái chê bai, tập trung vào sự kiêu ngạo, tự phụ chứ không chỉ đơn thuần là vẻ bề ngoài hoành tráng.', 'His pompous speech made a simple dinner feel painfully formal.', NULL, 'Bài phát biểu khoa trương của ông ấy đã biến một bữa tối giản dị thành một buổi tiệc trang trọng đến ngột ngạt.', '{"wordId":"pompous","ukIpa":"/ˈpɒmpəs/","usIpa":"/ˈpɑːmpəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"acting or speaking as though more important than others","vi":"tự phụ; tự mãn; khoa trương"}],"examples":[{"en":"His pompous speech made a simple dinner feel painfully formal.","vi":"Bài phát biểu khoa trương của ông ấy đã biến một bữa tối giản dị thành một buổi tiệc trang trọng đến ngột ngạt.","audioKind":"ex"},{"en":"Public officials who use pompous language may alienate citizens rather than communicate important policies clearly and effectively.","vi":"Các quan chức sử dụng ngôn từ khoa trương có thể đẩy người dân ra xa thay vì truyền đạt các chính sách quan trọng một cách rõ ràng và hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"pompous speech","vi":"bài phát biểu khoa trương"},{"en":"pompous manner","vi":"tác phong tự phụ"},{"en":"sound pompous","vi":"nghe có vẻ tự cao tự đại"}],"wordFamily":["pomposity (n.)","pompously (adv.)"],"synonyms":["self-important","pretentious"],"antonyms":["humble","modest"],"tipVi":"Mang sắc thái chê bai, tập trung vào sự kiêu ngạo, tự phụ chứ không chỉ đơn thuần là vẻ bề ngoài hoành tráng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uncalled-for', 'en-c1-7', 'uncalled-for', '/ʌnˈkɔːld fɔːr/', 'C1', 'vô lý; không cần thiết; bất lịch sự', 'adj.', NULL, 'Đồng nghĩa: unwarranted, unjustified · Trái nghĩa: justified', 'Thường dùng để mô tả những lời chỉ trích hoặc phát ngôn bất lịch sự, không đúng mực chứ không chỉ đơn thuần là thừa thãi.', 'Your uncalled-for remark upset everyone at the table.', NULL, 'Lời nhận xét vô lý của bạn đã làm mọi người có mặt hôm đó khó chịu.', '{"wordId":"uncalled-for","ukIpa":"/ʌnˈkɔːld fɔː/","usIpa":"/ʌnˈkɔːld fɔːr/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Unfair, unnecessary, or inappropriate in a particular situation.","vi":"vô lý; không cần thiết; bất lịch sự"}],"examples":[{"en":"Your uncalled-for remark upset everyone at the table.","vi":"Lời nhận xét vô lý của bạn đã làm mọi người có mặt hôm đó khó chịu.","audioKind":"ex"},{"en":"Uncalled-for criticism from teachers can discourage students from participating actively in classroom discussions.","vi":"Những lời chỉ trích vô cớ từ giáo viên có thể làm giảm động lực tham gia tích cực vào thảo luận lớp học của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"uncalled-for remark","vi":"lời chê bai vô lý"},{"en":"uncalled-for criticism","vi":"sự chỉ trích vô cớ"},{"en":"uncalled-for interference","vi":"sự can thiệp không cần thiết"}],"wordFamily":[],"synonyms":["unwarranted","unjustified"],"antonyms":["justified"],"tipVi":"Thường dùng để mô tả những lời chỉ trích hoặc phát ngôn bất lịch sự, không đúng mực chứ không chỉ đơn thuần là thừa thãi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vouch', 'en-c1-7', 'vouch', '/vaʊtʃ/', 'C1', 'bảo đảm; bảo lãnh; xác nhận', 'v.', NULL, 'Đồng nghĩa: guarantee, attest', 'Thường đi với giới từ vouch for, không trực tiếp nối với người hoặc vật được bảo đảm.', 'I can vouch for her excellent cooking skills.', NULL, 'Tôi có thể bảo đảm cho kỹ năng nấu nướng tuyệt vời của cô ấy.', '{"wordId":"vouch","ukIpa":"/vaʊtʃ/","usIpa":"/vaʊtʃ/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to confirm someone is reliable or something is true","vi":"bảo đảm; bảo lãnh; xác nhận"}],"examples":[{"en":"I can vouch for her excellent cooking skills.","vi":"Tôi có thể bảo đảm cho kỹ năng nấu nướng tuyệt vời của cô ấy.","audioKind":"ex"},{"en":"Independent experts should examine the research methods before they vouch for the accuracy of the findings.","vi":"Các chuyên gia độc lập nên kiểm tra các phương pháp nghiên cứu trước khi họ bảo đảm cho tính chính xác của các phát hiện.","audioKind":"ex2"}],"collocations":[{"en":"vouch for someone","vi":"bảo lãnh cho ai đó"},{"en":"vouch for the accuracy of","vi":"bảo đảm tính chính xác của"},{"en":"vouch for the quality of","vi":"bảo đảm chất lượng của"}],"wordFamily":[],"synonyms":["guarantee","attest"],"antonyms":[],"tipVi":"Thường đi với giới từ vouch for, không trực tiếp nối với người hoặc vật được bảo đảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unify', 'en-c1-7', 'unify', '/ˈjuːnɪfaɪ/', 'C1', 'thống nhất; hợp nhất; gắn kết', 'v.', 'unification (n.), unity (n.), unified (adj.)', 'Đồng nghĩa: unite, integrate · Trái nghĩa: divide, separate', 'Nhấn mạnh việc kết hợp các phần rời rạc thành một thể thống nhất, áp dụng được cho cả hệ thống lẫn cộng đồng người.', 'The neighbourhood festival helped unify our divided community.', NULL, 'Lễ hội khu phố đã giúp gắn kết cộng đồng vốn đang có nhiều chia rẽ của chúng tôi.', '{"wordId":"unify","ukIpa":"/ˈjuːnɪfaɪ/","usIpa":"/ˈjuːnɪfaɪ/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To bring separate parts or groups together as one.","vi":"thống nhất; hợp nhất; gắn kết"}],"examples":[{"en":"The neighbourhood festival helped unify our divided community.","vi":"Lễ hội khu phố đã giúp gắn kết cộng đồng vốn đang có nhiều chia rẽ của chúng tôi.","audioKind":"ex"},{"en":"A shared public transport network could unify the region while improving access to employment.","vi":"Một mạng lưới giao thông công cộng chung có thể hợp nhất khu vực này đồng thời cải thiện khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"unify a country","vi":"thống nhất đất nước"},{"en":"unify different groups","vi":"gắn kết các nhóm khác nhau"},{"en":"a unifying force","vi":"một lực lượng gắn kết"}],"wordFamily":["unification (n.)","unity (n.)","unified (adj.)"],"synonyms":["unite","integrate"],"antonyms":["divide","separate"],"tipVi":"Nhấn mạnh việc kết hợp các phần rời rạc thành một thể thống nhất, áp dụng được cho cả hệ thống lẫn cộng đồng người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commonplace', 'en-c1-7', 'commonplace', '/ˈkɑːmənpleɪs/', 'C1', 'phổ biến; thông thường; quen thuộc; điều tầm thường; chuyện thường ngày; lời sáo rỗng', 'adj.', NULL, 'Đồng nghĩa: ordinary, common, unremarkable · Trái nghĩa: unusual, exceptional', 'Thường chỉ sự việc phổ biến đến mức bình thường, không nhất thiết mang sắc thái chê bai.', 'Electric bikes are commonplace in our neighbourhood now.', NULL, 'Xe đạp điện giờ đây đã trở nên phổ biến ở khu phố chúng tôi.', '{"wordId":"commonplace","ukIpa":"/ˈkɒmənpleɪs/","usIpa":"/ˈkɑːmənpleɪs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Happening or found often enough to seem ordinary.","vi":"phổ biến; thông thường; quen thuộc"},{"pos":"n.","en":"Something ordinary, or a familiar statement lacking originality.","vi":"điều tầm thường; chuyện thường ngày; lời sáo rỗng"}],"examples":[{"en":"Electric bikes are commonplace in our neighbourhood now.","vi":"Xe đạp điện giờ đây đã trở nên phổ biến ở khu phố chúng tôi.","audioKind":"ex"},{"en":"Remote working has become commonplace in many industries, changing how companies organise their offices.","vi":"Làm việc từ xa đã trở thành xu hướng phổ biến ở nhiều ngành nghề, làm thay đổi cách các công ty sắp xếp không gian văn phòng.","audioKind":"ex2"}],"collocations":[{"en":"become commonplace","vi":"trở nên phổ biến"},{"en":"increasingly commonplace","vi":"ngày càng phổ biến"},{"en":"a commonplace occurrence","vi":"một hiện tượng phổ biến"}],"wordFamily":[],"synonyms":["ordinary","common","unremarkable"],"antonyms":["unusual","exceptional"],"tipVi":"Thường chỉ sự việc phổ biến đến mức bình thường, không nhất thiết mang sắc thái chê bai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_merciful', 'en-c1-7', 'merciful', '/ˈmɝːsɪfəl/', 'C1', 'khoan dung; nhân từ; độ lượng; giải thoát; đỡ đau đớn', 'adj.', 'mercy (n.), mercifully (adv.), merciless (adj.), mercilessly (adv.)', 'Đồng nghĩa: compassionate, lenient · Trái nghĩa: merciless, cruel', 'Dùng cấu trúc be merciful to someone để chỉ lòng nhân từ đối với ai đó.', 'The merciful coach forgave my mistake during practice.', NULL, 'Vị huấn luyện viên nhân từ đã tha thứ cho sai lầm của tôi trong buổi tập.', '{"wordId":"merciful","ukIpa":"/ˈmɜːsɪfəl/","usIpa":"/ˈmɝːsɪfəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Showing kindness by choosing not to punish or hurt someone.","vi":"khoan dung; nhân từ; độ lượng"},{"pos":"adj.","en":"Providing welcome relief from suffering or discomfort.","vi":"giải thoát; đỡ đau đớn"}],"examples":[{"en":"The merciful coach forgave my mistake during practice.","vi":"Vị huấn luyện viên nhân từ đã tha thứ cho sai lầm của tôi trong buổi tập.","audioKind":"ex"},{"en":"A merciful justice system should offer young offenders opportunities for rehabilitation rather than relying solely on punishment.","vi":"Một hệ thống tư pháp nhân từ nên trao cơ hội hoàn lương cho những người lầm lỡ trẻ tuổi thay vì chỉ dựa vào trừng phạt.","audioKind":"ex2"}],"collocations":[{"en":"be merciful to someone","vi":"tỏ lòng nhân từ với ai"},{"en":"a merciful judge","vi":"một vị thẩm phán khoan dung"},{"en":"a merciful release","vi":"sự giải thoát nhẹ nhõm"}],"wordFamily":["mercy (n.)","mercifully (adv.)","merciless (adj.)","mercilessly (adv.)"],"synonyms":["compassionate","lenient"],"antonyms":["merciless","cruel"],"tipVi":"Dùng cấu trúc be merciful to someone để chỉ lòng nhân từ đối với ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_orthodox', 'en-c1-7', 'Orthodox', '/ˈɔːrθədɑːks/', 'C1', 'thuộc Giáo hội Chính thống giáo Đông phương; tuân thủ luật lệ và thực hành tôn giáo truyền thống của người Do Thái', 'adj.', 'orthodoxy (n.), unorthodox (adj.)', NULL, 'Viết hoa thường chỉ giáo phái tôn giáo; viết thường orthodox có nghĩa là chính thống, theo truyền thống.', 'We visited an Orthodox church with beautiful painted icons.', NULL, 'Chúng tôi đã thăm một nhà thờ Chính thống giáo với những bức tranh thánh vẽ tuyệt đẹp.', '{"wordId":"orthodox","ukIpa":"/ˈɔːθədɒks/","usIpa":"/ˈɔːrθədɑːks/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"relating to the Eastern Orthodox Christian churches","vi":"thuộc Giáo hội Chính thống giáo Đông phương"},{"pos":"adj.","en":"following traditional Jewish religious laws and practices","vi":"tuân thủ luật lệ và thực hành tôn giáo truyền thống của người Do Thái"}],"examples":[{"en":"We visited an Orthodox church with beautiful painted icons.","vi":"Chúng tôi đã thăm một nhà thờ Chính thống giáo với những bức tranh thánh vẽ tuyệt đẹp.","audioKind":"ex"},{"en":"Preserving Orthodox churches can protect architectural heritage while helping visitors understand the religious traditions of local communities.","vi":"Bảo tồn các nhà thờ Chính thống giáo vừa giúp gìn giữ di sản kiến trúc vừa giúp du khách hiểu thêm về truyền thống tôn giáo của cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"Orthodox Church","vi":"Giáo hội Chính thống giáo"},{"en":"Orthodox Christianity","vi":"Cơ Đốc giáo Chính thống"},{"en":"Orthodox Judaism","vi":"Do Thái giáo Chính thống"}],"wordFamily":["orthodoxy (n.)","unorthodox (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa thường chỉ giáo phái tôn giáo; viết thường orthodox có nghĩa là chính thống, theo truyền thống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_7_1', 'en-c1-7', 'Cách dùng “uncalled-for” (adj.) — vô lý; không cần thiết; bất lịch sự', 'uncalled-for remark  ·  uncalled-for criticism  ·  uncalled-for interference', 'Thường dùng để mô tả những lời chỉ trích hoặc phát ngôn bất lịch sự, không đúng mực chứ không chỉ đơn thuần là thừa thãi.', 'Đồng nghĩa: unwarranted, unjustified · Trái nghĩa: justified', '[{"hanzi":"Your uncalled-for remark upset everyone at the table.","pinyin":"","meaning":"Lời nhận xét vô lý của bạn đã làm mọi người có mặt hôm đó khó chịu."},{"hanzi":"Uncalled-for criticism from teachers can discourage students from participating actively in classroom discussions.","pinyin":"","meaning":"Những lời chỉ trích vô cớ từ giáo viên có thể làm giảm động lực tham gia tích cực vào thảo luận lớp học của học sinh."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_7_2', 'en-c1-7', 'Cách dùng “molest” (v.) — quấy rối tình dục; lạm dụng tình dục', 'molest someone  ·  sexually molest', 'Trong tiếng Anh hiện đại, từ này chủ yếu chỉ hành vi quấy rối tình dục, không dùng để chỉ việc làm phiền thông thường.', 'Họ từ (Word Family): molestation (n.), molester (n.), unmolested (adj.)', '[{"hanzi":"The club bans anyone who tries to molest guests.","pinyin":"","meaning":"Câu lạc bộ cấm cửa bất kỳ ai có hành vi cố gắng quấy rối khách tham quan."},{"hanzi":"Public transport authorities should provide clear reporting procedures for passengers targeted by individuals who molest others.","pinyin":"","meaning":"Các cơ quan quản lý giao thông công cộng nên cung cấp các quy trình báo cáo rõ ràng cho những hành khách là mục tiêu của kẻ có hành vi quấy rối."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_7_3', 'en-c1-7', 'Cách dùng “unify” (v.) — thống nhất; hợp nhất; gắn kết', 'unify a country  ·  unify different groups  ·  a unifying force', 'Nhấn mạnh việc kết hợp các phần rời rạc thành một thể thống nhất, áp dụng được cho cả hệ thống lẫn cộng đồng người.', 'Họ từ (Word Family): unification (n.), unity (n.), unified (adj.) | Đồng nghĩa: unite, integrate · Trái nghĩa: divide, separate', '[{"hanzi":"The neighbourhood festival helped unify our divided community.","pinyin":"","meaning":"Lễ hội khu phố đã giúp gắn kết cộng đồng vốn đang có nhiều chia rẽ của chúng tôi."},{"hanzi":"A shared public transport network could unify the region while improving access to employment.","pinyin":"","meaning":"Một mạng lưới giao thông công cộng chung có thể hợp nhất khu vực này đồng thời cải thiện khả năng tiếp cận việc làm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_7_4', 'en-c1-7', 'Cách dùng “impede” (v.) — cản trở, gây khó khăn cho sự di chuyển hoặc tiến độ', 'impede progress  ·  impede development  ·  impede movement', 'Nhấn mạnh việc làm cho tiến trình trở nên khó khăn hoặc chậm lại, chứ không nhất thiết là ngăn chặn hoàn toàn.', 'Họ từ (Word Family): impediment (n.) | Đồng nghĩa: hinder, hamper, obstruct · Trái nghĩa: facilitate', '[{"hanzi":"Fallen branches impeded our progress along the narrow path.","pinyin":"","meaning":"Những cành cây đổ cản trở hành trình của chúng tôi dọc theo lối đi hẹp."},{"hanzi":"Limited access to reliable internet services can impede educational progress in rural communities and widen existing inequalities.","pinyin":"","meaning":"Việc khó tiếp cận dịch vụ internet ổn định có thể cản trở tiến trình giáo dục ở các cộng đồng nông thôn và làm nới rộng khoảng cách bất bình đẳng hiện hữu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_7_1', 'en-c1-7', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_1_1', 'ten_c1_7_1', 'amends', 'I baked her a cake to make amends.', 'I baked her a cake to make amends.', '/əˈmendz/', 'Tôi đã nướng cho cô ấy một cái bánh để tạ lỗi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_1_2', 'ten_c1_7_1', 'converse', 'We conversed quietly while waiting for the train.', 'We conversed quietly while waiting for the train.', '/kənˈvɝːs/', 'Chúng tôi trò chuyện khẽ với nhau trong lúc đợi tàu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_1_3', 'ten_c1_7_1', 'brink', 'Their little shop was on the brink of closing.', 'Their little shop was on the brink of closing.', '/brɪŋk/', 'Cửa hàng nhỏ của họ suýt chút nữa là phải đóng cửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_1_4', 'ten_c1_7_1', 'shun', 'My neighbours shun crowded shops and buy food online.', 'My neighbours shun crowded shops and buy food online.', '/ʃʌn/', 'Những người hàng xóm của tôi tránh các cửa hàng đông đúc và mua thực phẩm trực tuyến.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_1_5', 'ten_c1_7_1', 'molest', 'The club bans anyone who tries to molest guests.', 'The club bans anyone who tries to molest guests.', '/məˈlest/', 'Câu lạc bộ cấm cửa bất kỳ ai có hành vi cố gắng quấy rối khách tham quan.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_1_6', 'ten_c1_7_1', 'miser', 'That miser refuses to replace his broken kitchen chair.', 'That miser refuses to replace his broken kitchen chair.', '/ˈmaɪzər/', 'Tên hà tiện đó nhất định không chịu thay chiếc ghế bếp đã hỏng của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_1_7', 'ten_c1_7_1', 'fidelity', 'The couple promised lifelong fidelity during their wedding.', 'The couple promised lifelong fidelity during their wedding.', '/fɪˈdeləti/', 'Cặp đôi đã hứa hẹn sự trung thủy trọn đời trong đám cưới của họ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_1_8', 'ten_c1_7_1', 'mobilize', 'Our neighbours mobilized volunteers to clean the local beach.', 'Our neighbours mobilized volunteers to clean the local beach.', '/ˈmoʊbəlaɪz/', 'Những người hàng xóm của chúng tôi đã huy động các tình nguyện viên để dọn dẹp bãi biển địa phương.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_7_1_1', 'en-c1-7', 'ten_c1_7_1', 'listening', 'listening', 'I baked her a cake to make amends.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những người hàng xóm của tôi tránh các cửa hàng đông đúc và mua thực phẩm trực tuyến.","Cặp đôi đã hứa hẹn sự trung thủy trọn đời trong đám cưới của họ.","Tôi đã nướng cho cô ấy một cái bánh để tạ lỗi.","Bài phát biểu khoa trương của ông ấy đã biến một bữa tối giản dị thành một buổi tiệc trang trọng đến ngột ngạt."]'::jsonb, 2, 'I baked her a cake to make amends. → Tôi đã nướng cho cô ấy một cái bánh để tạ lỗi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_7_1_2', 'en-c1-7', 'ten_c1_7_1', 'listening', 'listening', 'We conversed quietly while waiting for the train.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vị huấn luyện viên nhân từ đã tha thứ cho sai lầm của tôi trong buổi tập.","Tên hà tiện đó nhất định không chịu thay chiếc ghế bếp đã hỏng của mình.","Chúng tôi trò chuyện khẽ với nhau trong lúc đợi tàu.","Sự bao trùm của sắc xanh mang lại cho căn phòng này cảm giác mát mẻ."]'::jsonb, 2, 'We conversed quietly while waiting for the train. → Chúng tôi trò chuyện khẽ với nhau trong lúc đợi tàu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_7_1_3', 'en-c1-7', 'ten_c1_7_1', 'listening', 'listening', 'Their little shop was on the brink of closing.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy cảm thấy việc gian lận bài bạc là một hành động đáng xấu hổ.","Cửa hàng nhỏ của họ suýt chút nữa là phải đóng cửa.","Những người hàng xóm của tôi tránh các cửa hàng đông đúc và mua thực phẩm trực tuyến.","Lời nhận xét vô lý của bạn đã làm mọi người có mặt hôm đó khó chịu."]'::jsonb, 1, 'Their little shop was on the brink of closing. → Cửa hàng nhỏ của họ suýt chút nữa là phải đóng cửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_7_2', 'en-c1-7', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_2_1', 'ten_c1_7_2', 'amends', 'Companies should make amends for environmental damage by restoring habitats and compensating affected communities.', 'Companies should make amends for environmental damage by restoring habitats and compensating affected communities.', '/əˈmendz/', 'Các doanh nghiệp nên đền bù những tổn hại về môi trường bằng cách phục hồi các môi trường sống và bồi thường cho các cộng đồng bị ảnh hưởng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_2_2', 'ten_c1_7_2', 'converse', 'Language exchange programmes allow students to converse with native speakers and develop confidence in unfamiliar social situations.', 'Language exchange programmes allow students to converse with native speakers and develop confidence in unfamiliar social situations.', '/kənˈvɝːs/', 'Các chương trình trao đổi ngôn ngữ cho phép học sinh trò chuyện với người bản xứ và phát triển sự tự tin trong các tình huống giao tiếp xã hội xa lạ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_2_3', 'ten_c1_7_2', 'brink', 'Prolonged drought has pushed several rural communities to the brink of a severe food crisis.', 'Prolonged drought has pushed several rural communities to the brink of a severe food crisis.', '/brɪŋk/', 'Hạn hán kéo dài đã đẩy một số cộng đồng nông thôn đến bờ vực của một cuộc khủng hoảng lương thực nghiêm trọng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_2_4', 'ten_c1_7_2', 'shun', 'Some graduates shun corporate careers because they value personal independence more than a high salary.', 'Some graduates shun corporate careers because they value personal independence more than a high salary.', '/ʃʌn/', 'Một số sinh viên tốt nghiệp né tránh các công việc doanh nghiệp vì họ coi trọng sự độc lập cá nhân hơn là mức lương cao.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_2_5', 'ten_c1_7_2', 'molest', 'Public transport authorities should provide clear reporting procedures for passengers targeted by individuals who molest others.', 'Public transport authorities should provide clear reporting procedures for passengers targeted by individuals who molest others.', '/məˈlest/', 'Các cơ quan quản lý giao thông công cộng nên cung cấp các quy trình báo cáo rõ ràng cho những hành khách là mục tiêu của kẻ có hành vi quấy rối.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_7_2_6', 'ten_c1_7_2', 'miser', 'Literature often portrays the miser as someone whose attachment to wealth damages relationships and personal happiness.', 'Literature often portrays the miser as someone whose attachment to wealth damages relationships and personal happiness.', '/ˈmaɪzər/', 'Văn học thường khắc họa kẻ keo kiệt là một người có sự bám chấp vào tài sản làm tổn hại đến các mối quan hệ và hạnh phúc cá nhân.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_7_2_1', 'en-c1-7', 'ten_c1_7_2', 'listening', 'listening', 'Companies should make amends for environmental damage by restoring habitats and compensating affected communities.', NULL, 'Trong câu vừa nghe, từ “amends” mang nghĩa nào sau đây?', '["bấp bênh; dễ đổ","lò ốt; lò đốt rác","sự khái quát; lời nhận định chung chung","sự đền bù; sự tạ lỗi"]'::jsonb, 3, '“amends” (/əˈmendz/): sự đền bù; sự tạ lỗi. Câu đầy đủ: Companies should make amends for environmental damage by restoring habitats and compensating affected communities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_7_2_2', 'en-c1-7', 'ten_c1_7_2', 'listening', 'listening', 'Language exchange programmes allow students to converse with native speakers and develop confidence in unfamiliar social situations.', NULL, 'Trong câu vừa nghe, từ “converse” mang nghĩa nào sau đây?', '["đòi hỏi; kéo theo; bao hàm","sự khởi đầu; sự bắt đầu (thường là điều không dễ chịu)","hấp dẫn không thể cưỡng lại; vô cùng quyến rũ","trò chuyện; đàm đạo"]'::jsonb, 3, '“converse” (/kənˈvɝːs/): trò chuyện; đàm đạo. Câu đầy đủ: Language exchange programmes allow students to converse with native speakers and develop confidence in unfamiliar social situations.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
