INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_1', 'en-c1-7', NULL, 'comprehensive_test', 'listening', 'amends', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự trầm ngâm; sự suy ngẫm","sự cân bằng; trạng thái cân bằng","sự đền bù; sự tạ lỗi","bờm (ngựa, sư tử, v.v.)"]'::jsonb, 2, 'amends (/əˈmendz/) → sự đền bù; sự tạ lỗi', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_2', 'en-c1-7', NULL, 'comprehensive_test', 'listening', 'We conversed quietly while waiting for the train.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mặc dù bị khiêu khích, Amir vẫn giữ bình tĩnh và bỏ đi.","Chúng tôi trò chuyện khẽ với nhau trong lúc đợi tàu.","Những cành cây đổ cản trở hành trình của chúng tôi dọc theo lối đi hẹp.","Những người hàng xóm của chúng tôi đã huy động các tình nguyện viên để dọn dẹp bãi biển địa phương."]'::jsonb, 1, 'We conversed quietly while waiting for the train. → Chúng tôi trò chuyện khẽ với nhau trong lúc đợi tàu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_3', 'en-c1-7', NULL, 'comprehensive_test', 'listening', 'brink', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thích hợp cho việc trồng trọt; có thể canh tác","thâm hụt; mức thâm hụt (chi tiêu vượt quá thu nhập)","hợp kim","bờ vực; nguy cơ cận kề"]'::jsonb, 3, 'brink (/brɪŋk/) → bờ vực; nguy cơ cận kề; cạnh vách đá; bờ vực thẳm', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_4', 'en-c1-7', NULL, 'comprehensive_test', 'listening', 'My neighbours shun crowded shops and buy food online.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những cành cây đổ cản trở hành trình của chúng tôi dọc theo lối đi hẹp.","Con đường đó nổi tiếng là có nhiều ổ gà sâu.","Những người hàng xóm của tôi tránh các cửa hàng đông đúc và mua thực phẩm trực tuyến.","Anh ấy cảm thấy việc gian lận bài bạc là một hành động đáng xấu hổ."]'::jsonb, 2, 'My neighbours shun crowded shops and buy food online. → Những người hàng xóm của tôi tránh các cửa hàng đông đúc và mua thực phẩm trực tuyến.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_5', 'en-c1-7', NULL, 'comprehensive_test', 'listening', 'molest', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quấy rối tình dục; lạm dụng tình dục","thực thể độc lập; tổ chức riêng biệt","xa hoa; phung phí; đắt đỏ","dấu ấn; nét đặc trưng; đặc điểm tiêu biểu"]'::jsonb, 0, 'molest (/məˈlest/) → quấy rối tình dục; lạm dụng tình dục; quấy rầy; hành hung', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_6', 'en-c1-7', NULL, 'comprehensive_test', 'listening', 'That miser refuses to replace his broken kitchen chair.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người hàng xóm hách dịch của cô ấy đã từ chối đến thăm căn hộ nhỏ của chúng tôi.","Tên hà tiện đó nhất định không chịu thay chiếc ghế bếp đã hỏng của mình.","Chúng tôi đã lãng phí cả buổi chiều để cãi nhau về những chi tiết vụn vặt.","Bài phát biểu khoa trương của ông ấy đã biến một bữa tối giản dị thành một buổi tiệc trang trọng đến ngột ngạt."]'::jsonb, 1, 'That miser refuses to replace his broken kitchen chair. → Tên hà tiện đó nhất định không chịu thay chiếc ghế bếp đã hỏng của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
