INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_8', 'en-c1-7', NULL, 'comprehensive_test', 'listening', 'Our neighbours mobilized volunteers to clean the local beach.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những người hàng xóm của chúng tôi đã huy động các tình nguyện viên để dọn dẹp bãi biển địa phương.","Bài phát biểu khoa trương của ông ấy đã biến một bữa tối giản dị thành một buổi tiệc trang trọng đến ngột ngạt.","Những cành cây đổ cản trở hành trình của chúng tôi dọc theo lối đi hẹp.","Tôi có thể bảo đảm cho kỹ năng nấu nướng tuyệt vời của cô ấy."]'::jsonb, 0, 'Our neighbours mobilized volunteers to clean the local beach. → Những người hàng xóm của chúng tôi đã huy động các tình nguyện viên để dọn dẹp bãi biển địa phương.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
