INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_18', 'en-c1-7', NULL, 'comprehensive_test', 'reading', NULL, 'Companies should make amends for environmental damage by restoring habitats and compensating affected communities.', 'Dựa vào câu trên, từ “amends” có nghĩa phù hợp nhất là gì?', '["dựa dẫm; phụ thuộc; nhờ vào","sự tích lũy; sự tích tụ; lượng tích tụ","sự đền bù; sự tạ lỗi","kìm chế; tránh"]'::jsonb, 2, 'amends: sự đền bù; sự tạ lỗi. Dịch cả câu: Các doanh nghiệp nên đền bù những tổn hại về môi trường bằng cách phục hồi các môi trường sống và bồi thường cho các cộng đồng bị ảnh hưởng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_19', 'en-c1-7', NULL, 'comprehensive_test', 'reading', NULL, 'Language exchange programmes allow students to converse with native speakers and develop confidence in unfamiliar social situations.', 'Dựa vào câu trên, từ “converse” có nghĩa phù hợp nhất là gì?', '["sự tăng tốc; sự đẩy nhanh","trò chuyện; đàm đạo","giải phóng; trả tự do cho con người hoặc vùng đất khỏi sự kiểm soát hoặc giam cầm","có lợi; thuận lợi; hữu ích"]'::jsonb, 1, 'converse: trò chuyện; đàm đạo. Dịch cả câu: Các chương trình trao đổi ngôn ngữ cho phép học sinh trò chuyện với người bản xứ và phát triển sự tự tin trong các tình huống giao tiếp xã hội xa lạ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_20', 'en-c1-7', NULL, 'comprehensive_test', 'reading', NULL, 'Prolonged drought has pushed several rural communities to the brink of a severe food crisis.', 'Dựa vào câu trên, từ “brink” có nghĩa phù hợp nhất là gì?', '["bờ vực; nguy cơ cận kề","âm ấm; hơi ấm","cuộn vi phim; phim thu nhỏ","sự mãn nguyện; cảm giác thỏa mãn"]'::jsonb, 0, 'brink: bờ vực; nguy cơ cận kề; cạnh vách đá; bờ vực thẳm. Dịch cả câu: Hạn hán kéo dài đã đẩy một số cộng đồng nông thôn đến bờ vực của một cuộc khủng hoảng lương thực nghiêm trọng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_21', 'en-c1-7', NULL, 'comprehensive_test', 'reading', NULL, 'Some graduates shun corporate careers because they value personal independence more than a high salary.', 'Dựa vào câu trên, từ “shun” có nghĩa phù hợp nhất là gì?', '["cố tình tránh xa; xa lánh","thu thập và tổng hợp thông tin từ nhiều nguồn khác nhau; biên soạn","ném mạnh; quăng quật","sự thao túng; sự điều khiển (kiểm soát con người hoặc tình huống một cách không công bằng vì lợi ích cá nhân)"]'::jsonb, 0, 'shun: cố tình tránh xa; xa lánh. Dịch cả câu: Một số sinh viên tốt nghiệp né tránh các công việc doanh nghiệp vì họ coi trọng sự độc lập cá nhân hơn là mức lương cao.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_22', 'en-c1-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phổ biến; thông thường; quen thuộc”', '["commonplace","aerosol","recur","pretext"]'::jsonb, 0, 'phổ biến; thông thường; quen thuộc → commonplace (/ˈkɑːmənpleɪs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_23', 'en-c1-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khoan dung; nhân từ; độ lượng”', '["merciful","potluck","feud","restrain"]'::jsonb, 0, 'khoan dung; nhân từ; độ lượng → merciful (/ˈmɝːsɪfəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_7_24', 'en-c1-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc Giáo hội Chính thống giáo Đông phương”', '["lunar","eradication","Orthodox","accompaniment"]'::jsonb, 2, 'thuộc Giáo hội Chính thống giáo Đông phương → Orthodox (/ˈɔːrθədɑːks/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-8', 'en', 'Bài 8: Xã hội & Cộng đồng (3) - CEFR C1', 'CEFR C1', 'C1 · Xã hội', '28 từ vựng Tiếng Anh CEFR C1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5008, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preacher', 'en-c1-8', 'preacher', '/ˈpriːtʃər/', 'C1', 'người giảng đạo; nhà truyền giáo; người nhiệt thành truyền bá một tư tưởng hay hành vi nào đó', 'n.', 'preach (v.), preaching (n.)', NULL, 'preacher nhấn mạnh việc giảng đạo, còn missionary nhấn mạnh việc truyền bá tôn giáo.', 'The preacher welcomed everyone before beginning his Sunday talk.', NULL, 'Vị mục sư đã chào đón tất cả mọi người trước khi bắt đầu bài giảng ngày Chủ nhật.', '{"wordId":"preacher","ukIpa":"/ˈpriːtʃə/","usIpa":"/ˈpriːtʃər/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"someone who gives public talks about religious beliefs","vi":"người giảng đạo; nhà truyền giáo"},{"pos":"n.","en":"someone who strongly promotes particular beliefs or behaviour","vi":"người nhiệt thành truyền bá một tư tưởng hay hành vi nào đó"}],"examples":[{"en":"The preacher welcomed everyone before beginning his Sunday talk.","vi":"Vị mục sư đã chào đón tất cả mọi người trước khi bắt đầu bài giảng ngày Chủ nhật.","audioKind":"ex"},{"en":"A local preacher encouraged residents to support families affected by unemployment through practical community projects.","vi":"Một nhà truyền giáo địa phương đã khuyến khích cư dân chung tay hỗ trợ các gia đình bị ảnh hưởng bởi nạn thất nghiệp thông qua các dự án cộng đồng thiết thực.","audioKind":"ex2"}],"collocations":[{"en":"a local preacher","vi":"một nhà truyền giáo địa phương"},{"en":"a street preacher","vi":"người rao giảng trên đường phố"},{"en":"a preacher of peace","vi":"người kêu gọi hòa bình"}],"wordFamily":["preach (v.)","preaching (n.)"],"synonyms":[],"antonyms":[],"tipVi":"preacher nhấn mạnh việc giảng đạo, còn missionary nhấn mạnh việc truyền bá tôn giáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ideology', 'en-c1-8', 'ideology', '/ˌaɪdiˈɑːlədʒi/', 'C1', 'hệ tư tưởng; ý thức hệ', 'n.', 'ideological (adj.), ideologically (adv.), ideologue (n.)', NULL, 'Chỉ một hệ thống quan điểm xã hội hoặc chính trị có tổ chức, không phải là một ý tưởng đơn lẻ.', 'Their political ideology shapes how they discuss everyday problems.', NULL, 'Hệ tư tưởng chính trị của họ định hình cách họ thảo luận về các vấn đề thường ngày.', '{"wordId":"ideology","ukIpa":"/ˌaɪdiˈɒlədʒi/","usIpa":"/ˌaɪdiˈɑːlədʒi/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a system of beliefs shaping political or social views","vi":"hệ tư tưởng; ý thức hệ"}],"examples":[{"en":"Their political ideology shapes how they discuss everyday problems.","vi":"Hệ tư tưởng chính trị của họ định hình cách họ thảo luận về các vấn đề thường ngày.","audioKind":"ex"},{"en":"Educational policies often reflect the ideology of those in power rather than the needs of learners.","vi":"Các chính sách giáo dục thường phản ánh hệ tư tưởng của những người nắm quyền hơn là nhu cầu thực tế của người học.","audioKind":"ex2"}],"collocations":[{"en":"political ideology","vi":"ý thức hệ chính trị"},{"en":"dominant ideology","vi":"hệ tư tưởng thống trị"},{"en":"share an ideology","vi":"có chung hệ tư tưởng"}],"wordFamily":["ideological (adj.)","ideologically (adv.)","ideologue (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ một hệ thống quan điểm xã hội hoặc chính trị có tổ chức, không phải là một ý tưởng đơn lẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_taboo', 'en-c1-8', 'taboo', '/təˈbuː/', 'C1', 'điều cấm kỵ; điều kiêng kỵ; bị cấm kỵ; bị kiêng kỵ', 'n.', NULL, NULL, 'Đóng vai trò danh từ là điều cấm kỵ; đóng vai trò tính từ có thể dùng cụm a taboo subject.', 'Discussing salaries remains a taboo in our office.', NULL, 'Việc thảo luận về tiền lương vẫn là điều cấm kỵ ở văn phòng chúng tôi.', '{"wordId":"taboo","ukIpa":"/təˈbuː/","usIpa":"/təˈbuː/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a social rule against discussing or doing something","vi":"điều cấm kỵ; điều kiêng kỵ"},{"pos":"adj.","en":"considered unacceptable to discuss or do within a particular group","vi":"bị cấm kỵ; bị kiêng kỵ"}],"examples":[{"en":"Discussing salaries remains a taboo in our office.","vi":"Việc thảo luận về tiền lương vẫn là điều cấm kỵ ở văn phòng chúng tôi.","audioKind":"ex"},{"en":"Public education can challenge the taboo surrounding mental illness and encourage more people to seek support.","vi":"Giáo dục công cộng có thể phá bỏ những định kiến và điều cấm kỵ xung quanh bệnh tâm thần, đồng thời khuyến khích nhiều người tìm kiếm sự hỗ trợ hơn.","audioKind":"ex2"}],"collocations":[{"en":"break a taboo","vi":"phá vỡ điều cấm kỵ"},{"en":"a taboo subject","vi":"một chủ đề kiêng kỵ"},{"en":"a taboo against","vi":"sự cấm kỵ đối với"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đóng vai trò danh từ là điều cấm kỵ; đóng vai trò tính từ có thể dùng cụm a taboo subject.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advocate', 'en-c1-8', 'advocate', '/ˈædvəkeɪt/', 'C1', 'tán thành; ủng hộ; chủ trương; người ủng hộ; người tán thành; luật sư bào chữa', 'v.', 'advocacy (n.)', 'Đồng nghĩa: support, champion · Trái nghĩa: oppose', 'Danh từ có phần cuối phát âm là /kət/; động từ có thể đi với danh động từ (doing), không đi với to do.', 'Our neighbours advocate planting more trees along the street.', NULL, 'Những người hàng xóm của chúng tôi chủ trương trồng thêm nhiều cây xanh dọc theo con phố.', '{"wordId":"advocate","ukIpa":"/ˈædvəkeɪt/","usIpa":"/ˈædvəkeɪt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To publicly support a policy, idea, or course of action.","vi":"tán thành; ủng hộ; chủ trương"},{"pos":"n.","en":"Someone who publicly supports a cause or policy.","vi":"người ủng hộ; người tán thành; luật sư bào chữa"}],"examples":[{"en":"Our neighbours advocate planting more trees along the street.","vi":"Những người hàng xóm của chúng tôi chủ trương trồng thêm nhiều cây xanh dọc theo con phố.","audioKind":"ex"},{"en":"Many health professionals advocate regular physical activity as an affordable way to prevent chronic disease.","vi":"Nhiều chuyên gia y tế ủng hộ việc rèn luyện thể chất thường xuyên như một phương pháp tiết kiệm để phòng ngừa bệnh mạn tính.","audioKind":"ex2"}],"collocations":[{"en":"advocate reform","vi":"chủ trương cải cách"},{"en":"advocate doing something","vi":"ủng hộ việc làm gì đó"},{"en":"a strong advocate of","vi":"người ủng hộ nhiệt thành của"}],"wordFamily":["advocacy (n.)"],"synonyms":["support","champion"],"antonyms":["oppose"],"tipVi":"Danh từ có phần cuối phát âm là /kət/; động từ có thể đi với danh động từ (doing), không đi với to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_righteous', 'en-c1-8', 'righteous', '/ˈraɪtʃəs/', 'C1', 'chính trực; đúng đắn về mặt đạo đức; đầy lòng chính nghĩa; tự cho là đúng', 'adj.', 'righteously (adv.), righteousness (n.), unrighteous (adj.)', 'Đồng nghĩa: virtuous, upright · Trái nghĩa: unrighteous, immoral', 'Mang sắc thái trang trọng; từ self-righteous dùng để chỉ thái độ tự cho mình là đúng đắn.', 'She believed returning the wallet was the righteous choice.', NULL, 'Cô ấy tin rằng việc trả lại chiếc ví là sự lựa chọn chính trực.', '{"wordId":"righteous","ukIpa":"/ˈraɪtʃəs/","usIpa":"/ˈraɪtʃəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"morally right or acting according to strong moral principles","vi":"chính trực; đúng đắn về mặt đạo đức"},{"pos":"adj.","en":"arising from a belief that you are morally right","vi":"đầy lòng chính nghĩa; tự cho là đúng"}],"examples":[{"en":"She believed returning the wallet was the righteous choice.","vi":"Cô ấy tin rằng việc trả lại chiếc ví là sự lựa chọn chính trực.","audioKind":"ex"},{"en":"Righteous anger at social injustice can encourage citizens to demand meaningful changes in public policy.","vi":"Sự phẫn nộ chính đáng trước sự bất công xã hội có thể khích lệ người dân đòi hỏi những thay đổi có ý nghĩa trong chính sách công.","audioKind":"ex2"}],"collocations":[{"en":"righteous anger","vi":"sự phẫn nộ chính đáng"},{"en":"righteous indignation","vi":"cơn giận chính nghĩa"},{"en":"a righteous cause","vi":"một sự nghiệp chính nghĩa"}],"wordFamily":["righteously (adv.)","righteousness (n.)","unrighteous (adj.)"],"synonyms":["virtuous","upright"],"antonyms":["unrighteous","immoral"],"tipVi":"Mang sắc thái trang trọng; từ self-righteous dùng để chỉ thái độ tự cho mình là đúng đắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jeopardise', 'en-c1-8', 'jeopardise', '/ˈdʒepərdaɪz/', 'C1', 'gây nguy hiểm; làm tổn hại', 'v.', 'jeopardy (n.)', 'Đồng nghĩa: endanger, imperil · Trái nghĩa: safeguard', 'Động từ ngoại động từ, đi kèm trực tiếp với tân ngữ; tiếng Mỹ thường viết là jeopardize.', 'Skipping practice could jeopardise your place on the team.', NULL, 'Việc bỏ tập luyện có thể gây nguy hiểm cho vị trí của bạn trong đội.', '{"wordId":"jeopardise","ukIpa":"/ˈdʒepədaɪz/","usIpa":"/ˈdʒepərdaɪz/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To put something at risk of harm, loss, or failure.","vi":"gây nguy hiểm; làm tổn hại"}],"examples":[{"en":"Skipping practice could jeopardise your place on the team.","vi":"Việc bỏ tập luyện có thể gây nguy hiểm cho vị trí của bạn trong đội.","audioKind":"ex"},{"en":"Reducing investment in public transport could jeopardise efforts to cut urban air pollution and traffic congestion.","vi":"Việc cắt giảm đầu tư vào giao thông công cộng có thể cản trở các nỗ lực cắt giảm ô nhiễm không khí đô thị và ùn tắc giao thông.","audioKind":"ex2"}],"collocations":[{"en":"jeopardise safety","vi":"gây nguy hiểm cho an toàn"},{"en":"jeopardise a career","vi":"làm tổn hại sự nghiệp"},{"en":"jeopardise chances","vi":"làm tổn hại cơ hội"}],"wordFamily":["jeopardy (n.)"],"synonyms":["endanger","imperil"],"antonyms":["safeguard"],"tipVi":"Động từ ngoại động từ, đi kèm trực tiếp với tân ngữ; tiếng Mỹ thường viết là jeopardize.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_observance', 'en-c1-8', 'observance', '/əbˈzɝːvəns/', 'C1', 'sự tuân thủ; việc chấp hành; nghi lễ tôn giáo hoặc truyền thống', 'n.', 'observe (v.), observant (adj.)', 'Đồng nghĩa: compliance, adherence · Trái nghĩa: non-compliance', 'Observance chỉ sự tuân thủ hoặc nghi lễ; observation chỉ sự quan sát.', 'Strict observance of kitchen hygiene keeps our food safe.', NULL, 'Việc tuân thủ nghiêm ngặt vệ sinh nhà bếp giúp đảm bảo an toàn thực phẩm của chúng ta.', '{"wordId":"observance","ukIpa":"/əbˈzɜːvəns/","usIpa":"/əbˈzɝːvəns/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The practice of following a rule, law, or custom","vi":"sự tuân thủ; việc chấp hành"},{"pos":"n.","en":"A ceremony performed as part of religion or tradition","vi":"nghi lễ tôn giáo hoặc truyền thống"}],"examples":[{"en":"Strict observance of kitchen hygiene keeps our food safe.","vi":"Việc tuân thủ nghiêm ngặt vệ sinh nhà bếp giúp đảm bảo an toàn thực phẩm của chúng ta.","audioKind":"ex"},{"en":"Consistent observance of workplace safety regulations can prevent accidents and improve employees'' confidence in their employers.","vi":"Việc luôn tuân thủ các quy định an toàn tại nơi làm việc có thể ngăn ngừa tai nạn và nâng cao lòng tin của nhân viên đối với người sử dụng lao động.","audioKind":"ex2"}],"collocations":[{"en":"observance of the law","vi":"tuân thủ pháp luật"},{"en":"strict observance","vi":"tuân thủ nghiêm ngặt"},{"en":"religious observances","vi":"nghi lễ tôn giáo"}],"wordFamily":["observe (v.)","observant (adj.)"],"synonyms":["compliance","adherence"],"antonyms":["non-compliance"],"tipVi":"Observance chỉ sự tuân thủ hoặc nghi lễ; observation chỉ sự quan sát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disperse', 'en-c1-8', 'disperse', '/dɪˈspɝːs/', 'C1', 'phân tán; giải tán', 'v.', 'dispersal (n.), dispersion (n.)', 'Đồng nghĩa: scatter, spread · Trái nghĩa: gather', 'Có thể dùng cả ngoại động từ và nội động từ: giải tán đám đông hoặc đám đông tản ra.', 'The crowd began to disperse when the rain started.', NULL, 'Đám đông bắt đầu giải tán khi trời bắt đầu đổ mưa.', '{"wordId":"disperse","ukIpa":"/dɪˈspɜːs/","usIpa":"/dɪˈspɝːs/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To spread out or make people or things spread out","vi":"phân tán; giải tán"}],"examples":[{"en":"The crowd began to disperse when the rain started.","vi":"Đám đông bắt đầu giải tán khi trời bắt đầu đổ mưa.","audioKind":"ex"},{"en":"Planting trees can help disperse strong winds and protect exposed farmland from soil erosion.","vi":"Trồng cây có thể giúp làm giảm sức gió mạnh và bảo vệ các vùng đất nông nghiệp trống trải khỏi bị xói mòn đất.","audioKind":"ex2"}],"collocations":[{"en":"disperse a crowd","vi":"giải tán đám đông"},{"en":"disperse seeds","vi":"phát tán hạt giống"},{"en":"disperse rapidly","vi":"phân tán nhanh chóng"}],"wordFamily":["dispersal (n.)","dispersion (n.)"],"synonyms":["scatter","spread"],"antonyms":["gather"],"tipVi":"Có thể dùng cả ngoại động từ và nội động từ: giải tán đám đông hoặc đám đông tản ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disreputable', 'en-c1-8', 'disreputable', '/dɪsˈrepjətəbəl/', 'C1', 'tai tiếng; mất uy tín; đáng ngờ; lôi thôi; rách rưới; xập xệ', 'adj.', 'reputable (adj.), disrepute (n.), repute (n.)', 'Đồng nghĩa: shady, dishonourable · Trái nghĩa: reputable, respectable', 'Thường chỉ danh tiếng hoặc hành vi xấu, không chỉ đơn thuần là vẻ bề ngoài rách rưới.', 'We avoided that disreputable garage after several neighbours complained.', NULL, 'Chúng tôi đã tránh xa tiệm sửa xe có tiếng tăm không tốt đó sau khi một vài người hàng xóm phàn nàn.', '{"wordId":"disreputable","ukIpa":"/dɪsˈrepjətəbəl/","usIpa":"/dɪsˈrepjətəbəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Having a bad reputation and not deserving trust or respect.","vi":"tai tiếng; mất uy tín; đáng ngờ"},{"pos":"adj.","en":"Looking untidy, worn, or unsuitable for respectable company.","vi":"lôi thôi; rách rưới; xập xệ"}],"examples":[{"en":"We avoided that disreputable garage after several neighbours complained.","vi":"Chúng tôi đã tránh xa tiệm sửa xe có tiếng tăm không tốt đó sau khi một vài người hàng xóm phàn nàn.","audioKind":"ex"},{"en":"Stronger consumer protection laws could prevent disreputable companies from exploiting customers who lack detailed financial knowledge.","vi":"Các luật bảo vệ người tiêu dùng chặt chẽ hơn có thể ngăn chặn những doanh nghiệp bất lương lợi dụng những khách hàng thiếu kiến thức tài chính chi tiết.","audioKind":"ex2"}],"collocations":[{"en":"disreputable company","vi":"công ty tai tiếng"},{"en":"disreputable behaviour","vi":"hành vi bất chính"},{"en":"disreputable character","vi":"nhân vật có tiếng tăm không tốt"}],"wordFamily":["reputable (adj.)","disrepute (n.)","repute (n.)"],"synonyms":["shady","dishonourable"],"antonyms":["reputable","respectable"],"tipVi":"Thường chỉ danh tiếng hoặc hành vi xấu, không chỉ đơn thuần là vẻ bề ngoài rách rưới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vicious', 'en-c1-8', 'vicious', '/ˈvɪʃəs/', 'C1', 'hung dữ; dữ tợn; độc ác; hiểm độc; ác ý', 'adj.', 'viciously (adv.), viciousness (n.)', 'Đồng nghĩa: cruel, brutal, savage · Trái nghĩa: gentle, kind', 'vicious circle chỉ "vòng luẩn quẩn" khi các vấn đề làm trầm trọng lẫn nhau.', 'A vicious dog growled behind the tall metal fence.', NULL, 'Một con chó dữ gầm gừ phía sau hàng rào kim loại cao.', '{"wordId":"vicious","ukIpa":"/ˈvɪʃəs/","usIpa":"/ˈvɪʃəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"likely to attack or cause serious harm","vi":"hung dữ; dữ tợn"},{"pos":"adj.","en":"deliberately cruel and intended to hurt someone","vi":"độc ác; hiểm độc; ác ý"}],"examples":[{"en":"A vicious dog growled behind the tall metal fence.","vi":"Một con chó dữ gầm gừ phía sau hàng rào kim loại cao.","audioKind":"ex"},{"en":"Vicious comments on social media can damage young people''s confidence and discourage participation in online discussions.","vi":"Những lời bình luận ác ý trên mạng xã hội có thể làm tổn hại đến sự tự tin của giới trẻ và làm giảm mong muốn tham gia vào các cuộc thảo luận trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"vicious attack","vi":"cuộc tấn công tàn bạo"},{"en":"vicious circle","vi":"vòng luẩn quẩn"},{"en":"vicious rumour","vi":"tin đồn ác ý"},{"en":"vicious comments","vi":"lời bình luận ác ý"}],"wordFamily":["viciously (adv.)","viciousness (n.)"],"synonyms":["cruel","brutal","savage"],"antonyms":["gentle","kind"],"tipVi":"vicious circle chỉ \"vòng luẩn quẩn\" khi các vấn đề làm trầm trọng lẫn nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_harmonious', 'en-c1-8', 'harmonious', '/hɑːrˈmoʊniəs/', 'C1', 'hài hòa; hòa hợp; phối hợp nhịp nhàng; êm tai', 'adj.', 'harmony (n.), harmoniously (adv.), harmonise (v.)', 'Đồng nghĩa: peaceful, compatible · Trái nghĩa: discordant, conflicting', 'Vừa có thể dùng để chỉ quan hệ xã hội, vừa dùng để miêu tả màu sắc hoặc âm thanh ăn ý với nhau.', 'Sharing the chores helps keep our home harmonious.', NULL, 'Cùng nhau chia sẻ việc nhà giúp giữ cho gia đình chúng tôi luôn hòa thuận.', '{"wordId":"harmonious","ukIpa":"/hɑːˈməʊniəs/","usIpa":"/hɑːrˈmoʊniəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"friendly and peaceful, without conflict","vi":"hài hòa; hòa hợp"},{"pos":"adj.","en":"having parts that look or sound pleasing together","vi":"phối hợp nhịp nhàng; êm tai"}],"examples":[{"en":"Sharing the chores helps keep our home harmonious.","vi":"Cùng nhau chia sẻ việc nhà giúp giữ cho gia đình chúng tôi luôn hòa thuận.","audioKind":"ex"},{"en":"Schools can promote harmonious relationships by teaching students to resolve disagreements through respectful discussion.","vi":"Nhà trường có thể thúc đẩy các mối quan hệ hòa hợp bằng cách dạy học sinh giải quyết bất đồng thông qua thảo luận tôn trọng lẫn nhau.","audioKind":"ex2"}],"collocations":[{"en":"harmonious relationship","vi":"mối quan hệ hòa hợp"},{"en":"harmonious society","vi":"xã hội hài hòa"},{"en":"harmonious blend","vi":"sự hòa quyện nhịp nhàng"}],"wordFamily":["harmony (n.)","harmoniously (adv.)","harmonise (v.)"],"synonyms":["peaceful","compatible"],"antonyms":["discordant","conflicting"],"tipVi":"Vừa có thể dùng để chỉ quan hệ xã hội, vừa dùng để miêu tả màu sắc hoặc âm thanh ăn ý với nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mock', 'en-c1-8', 'mock', '/mɑːk/', 'C1', 'chế nhạo; chế giễu; giả định; mô phỏng; bài kiểm tra thử; kỳ thi thử', 'v.', 'mockery (n.), mocking (adj.), mockingly (adv.)', 'Đồng nghĩa: ridicule, imitate · Trái nghĩa: praise', 'mock khi làm động từ đi thẳng với tân ngữ, không cần thêm giới từ at.', 'Please don''t mock my dancing; I''m still learning.', NULL, 'Xin đừng chế giễu điệu nhảy của tôi; tôi vẫn đang học mà.', '{"wordId":"mock","ukIpa":"/mɒk/","usIpa":"/mɑːk/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To make someone seem foolish by laughing at or imitating them.","vi":"chế nhạo; chế giễu"},{"pos":"adj.","en":"Made to imitate something real, often for practice.","vi":"giả định; mô phỏng"},{"pos":"n.","en":"A practice examination taken before the real one.","vi":"bài kiểm tra thử; kỳ thi thử"}],"examples":[{"en":"Please don''t mock my dancing; I''m still learning.","vi":"Xin đừng chế giễu điệu nhảy của tôi; tôi vẫn đang học mà.","audioKind":"ex"},{"en":"Mock interviews allow students to practise explaining their skills before they apply for their first professional positions.","vi":"Các buổi phỏng vấn thử giúp học sinh thực hành cách trình bày các kỹ năng của mình trước khi ứng tuyển vào các vị trí công việc chính thức đầu tiên.","audioKind":"ex2"}],"collocations":[{"en":"mock someone''s accent","vi":"nhại lại giọng của ai đó"},{"en":"mock exam","vi":"kỳ thi thử"},{"en":"mock interview","vi":"phỏng vấn thử"}],"wordFamily":["mockery (n.)","mocking (adj.)","mockingly (adv.)"],"synonyms":["ridicule","imitate"],"antonyms":["praise"],"tipVi":"mock khi làm động từ đi thẳng với tân ngữ, không cần thêm giới từ at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_royalty', 'en-c1-8', 'royalty', '/ˈrɔɪəlti/', 'C1', 'thành viên hoàng gia; hoàng tộc; tiền bản quyền; phí sử dụng đặc quyền', 'n.', 'royal (adj.), royally (adv.)', NULL, 'Khi chỉ hoàng tộc thì không đếm được; khi chỉ thu nhập từ bản quyền thường dùng ở dạng số nhiều "royalties".', 'The palace once served as a home for royalty.', NULL, 'Cung điện này từng là nơi ở của hoàng gia.', '{"wordId":"royalty","ukIpa":"/ˈrɔɪəlti/","usIpa":"/ˈrɔɪəlti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"people who belong to a royal family","vi":"thành viên hoàng gia; hoàng tộc"},{"pos":"n.","en":"a payment for using someone''s work, invention, or property","vi":"tiền bản quyền; phí sử dụng đặc quyền"}],"examples":[{"en":"The palace once served as a home for royalty.","vi":"Cung điện này từng là nơi ở của hoàng gia.","audioKind":"ex"},{"en":"Authors often rely on royalties from book sales to support themselves while developing new creative projects.","vi":"Các tác giả thường dựa vào tiền bản quyền từ việc bán sách để trang trải cuộc sống trong khi phát triển các dự án sáng tạo mới.","audioKind":"ex2"}],"collocations":[{"en":"a member of royalty","vi":"một thành viên hoàng gia"},{"en":"pay royalties","vi":"trả tiền bản quyền"},{"en":"royalty payments","vi":"các khoản thanh toán tiền bản quyền"}],"wordFamily":["royal (adj.)","royally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ hoàng tộc thì không đếm được; khi chỉ thu nhập từ bản quyền thường dùng ở dạng số nhiều \"royalties\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vice', 'en-c1-8', 'vice', '/vaɪs/', 'C1', 'thói hư tật xấu; hành vi trái đạo đức; cái ê-tô (dụng cụ kẹp chặt vật)', 'n.', NULL, 'Trái nghĩa: virtue', 'Nghĩa cái ê-tô trong tiếng Anh-Mỹ được viết là "vise"; "vice-" trong từ phó chủ tịch (vice-president) là tiền tố.', 'Eating too much chocolate is my only vice.', NULL, 'Ăn quá nhiều sô-cô-la là thói quen xấu duy nhất của tôi.', '{"wordId":"vice","ukIpa":"/vaɪs/","usIpa":"/vaɪs/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a bad habit or morally wrong behaviour","vi":"thói hư tật xấu; hành vi trái đạo đức"},{"pos":"n.","en":"a tool that holds an object firmly between two jaws","vi":"cái ê-tô (dụng cụ kẹp chặt vật)"}],"examples":[{"en":"Eating too much chocolate is my only vice.","vi":"Ăn quá nhiều sô-cô-la là thói quen xấu duy nhất của tôi.","audioKind":"ex"},{"en":"Excessive consumption is sometimes viewed as a personal vice rather than a consequence of social pressures.","vi":"Tiêu dùng quá mức đôi khi bị coi là một thói xấu cá nhân hơn là hệ quả của các áp lực xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a minor vice","vi":"một thói xấu nhỏ"},{"en":"vice and virtue","vi":"cái xấu và cái tốt"},{"en":"a bench vice","vi":"cái ê-tô đặt trên bàn"}],"wordFamily":[],"synonyms":[],"antonyms":["virtue"],"tipVi":"Nghĩa cái ê-tô trong tiếng Anh-Mỹ được viết là \"vise\"; \"vice-\" trong từ phó chủ tịch (vice-president) là tiền tố.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compel', 'en-c1-8', 'compel', '/kəmˈpel/', 'C1', 'ép buộc; bắt buộc', 'v.', 'compelling (adj.), compulsion (n.), compulsory (adj.)', 'Đồng nghĩa: force, oblige', 'Thường dùng compel sb to do, mang sắc thái mạnh và trang trọng.', 'Heavy rain compelled us to cancel our picnic.', NULL, 'Cơn mưa lớn buộc chúng tôi phải hủy buổi dã ngoại.', '{"wordId":"compel","ukIpa":"/kəmˈpel/","usIpa":"/kəmˈpel/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to force someone to do something","vi":"ép buộc; bắt buộc"}],"examples":[{"en":"Heavy rain compelled us to cancel our picnic.","vi":"Cơn mưa lớn buộc chúng tôi phải hủy buổi dã ngoại.","audioKind":"ex"},{"en":"Stricter environmental laws could compel manufacturers to reduce waste and adopt cleaner production methods.","vi":"Các luật môi trường nghiêm ngặt hơn có thể ép buộc các nhà sản xuất giảm thiểu chất thải và áp dụng các phương pháp sản xuất sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"compel someone to act","vi":"ép buộc ai hành động"},{"en":"feel compelled to","vi":"cảm thấy buộc phải"},{"en":"be compelled by circumstances","vi":"bị hoàn cảnh xô đẩy"}],"wordFamily":["compelling (adj.)","compulsion (n.)","compulsory (adj.)"],"synonyms":["force","oblige"],"antonyms":[],"tipVi":"Thường dùng compel sb to do, mang sắc thái mạnh và trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_displace', 'en-c1-8', 'displace', '/dɪsˈpleɪs/', 'C1', 'làm mất nhà cửa; buộc phải rời khỏi nơi ở; thay thế; tiếm quyền; dời chỗ; chiếm chỗ', 'v.', 'displacement (n.), displaced (adj.)', NULL, 'displace thường chỉ việc bị ép phải di dời; cũng có thể chỉ việc cái mới thay thế cái cũ.', 'The flood displaced several families living near the river.', NULL, 'Trận lũ lụt đã khiến vài gia đình sống gần bờ sông phải rời bỏ nhà cửa.', '{"wordId":"displace","ukIpa":"/dɪsˈpleɪs/","usIpa":"/dɪsˈpleɪs/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"Force people to leave their homes or usual surroundings.","vi":"làm mất nhà cửa; buộc phải rời khỏi nơi ở"},{"pos":"v.","en":"Take the position or role previously held by something else.","vi":"thay thế; tiếm quyền"},{"pos":"v.","en":"Move something from its position, especially by occupying its space.","vi":"dời chỗ; chiếm chỗ"}],"examples":[{"en":"The flood displaced several families living near the river.","vi":"Trận lũ lụt đã khiến vài gia đình sống gần bờ sông phải rời bỏ nhà cửa.","audioKind":"ex"},{"en":"Although automation may displace some workers, investment in retraining can help them find alternative employment.","vi":"Mặc dù tự động hóa có thể thay thế một số công nhân, nhưng đầu tư vào việc đào tạo lại có thể giúp họ tìm được việc làm thay thế.","audioKind":"ex2"}],"collocations":[{"en":"displaced people","vi":"người mất nhà cửa"},{"en":"displace workers","vi":"thay thế công nhân"},{"en":"displace water","vi":"đẩy nước ra"}],"wordFamily":["displacement (n.)","displaced (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"displace thường chỉ việc bị ép phải di dời; cũng có thể chỉ việc cái mới thay thế cái cũ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lure', 'en-c1-8', 'lure', '/lʊr/', 'C1', 'dụ dỗ; lôi cuốn; nhử; sự cám dỗ; mồi nhử', 'v.', NULL, 'Đồng nghĩa: entice, tempt, attract · Trái nghĩa: repel', 'Thường dùng cấu trúc "lure sb into doing", thường hàm ý lừa gạt hoặc dụ dỗ.', 'We used some cheese to lure the mouse outside.', NULL, 'Chúng tôi đã dùng một ít phô mai để nhử con chuột ra ngoài.', '{"wordId":"lure","ukIpa":"/lʊə/","usIpa":"/lʊr/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To attract someone by offering something appealing, sometimes deceptively.","vi":"dụ dỗ; lôi cuốn; nhử"},{"pos":"n.","en":"An attraction or object used to draw someone or something closer.","vi":"sự cám dỗ; mồi nhử"}],"examples":[{"en":"We used some cheese to lure the mouse outside.","vi":"Chúng tôi đã dùng một ít phô mai để nhử con chuột ra ngoài.","audioKind":"ex"},{"en":"Large cities often lure young graduates with higher salaries, leaving rural communities with a shortage of skilled workers.","vi":"Các thành phố lớn thường thu hút sinh viên mới tốt nghiệp bằng mức lương cao hơn, khiến các cộng đồng nông thôn thiếu hụt lao động có tay nghề.","audioKind":"ex2"}],"collocations":[{"en":"lure someone into doing something","vi":"dụ dỗ ai đó làm gì"},{"en":"lure customers","vi":"thu hút khách hàng"},{"en":"the lure of wealth","vi":"sức hấp dẫn của sự giàu có"},{"en":"a fishing lure","vi":"mồi câu cá"}],"wordFamily":[],"synonyms":["entice","tempt","attract"],"antonyms":["repel"],"tipVi":"Thường dùng cấu trúc \"lure sb into doing\", thường hàm ý lừa gạt hoặc dụ dỗ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_doctrine', 'en-c1-8', 'doctrine', '/ˈdɑːktrɪn/', 'C1', 'học thuyết; giáo lý; tín điều', 'n.', 'doctrinal (adj.)', 'Đồng nghĩa: creed, teaching', 'Không nhất thiết mang hàm ý tiêu cực; có thể chỉ giáo lý tôn giáo hoặc các học thuyết chính trị, kinh tế.', 'The guide explained the doctrine behind the temple''s daily rituals.', NULL, 'Hướng dẫn viên giải thích giáo lý đằng sau các nghi lễ hàng ngày của ngôi đền.', '{"wordId":"doctrine","ukIpa":"/ˈdɒktrɪn/","usIpa":"/ˈdɑːktrɪn/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A belief or set of principles taught by a group.","vi":"học thuyết; giáo lý; tín điều"}],"examples":[{"en":"The guide explained the doctrine behind the temple''s daily rituals.","vi":"Hướng dẫn viên giải thích giáo lý đằng sau các nghi lễ hàng ngày của ngôi đền.","audioKind":"ex"},{"en":"Economic doctrine should be evaluated against practical evidence rather than accepted simply because it has influential supporters.","vi":"Các học thuyết kinh tế nên được đánh giá dựa trên các bằng chứng thực tiễn thay vì chỉ được chấp nhận đơn giản vì có những người ủng hộ có sức ảnh hưởng.","audioKind":"ex2"}],"collocations":[{"en":"religious doctrine","vi":"giáo lý tôn giáo"},{"en":"economic doctrine","vi":"học thuyết kinh tế"},{"en":"political doctrine","vi":"tín điều chính trị"}],"wordFamily":["doctrinal (adj.)"],"synonyms":["creed","teaching"],"antonyms":[],"tipVi":"Không nhất thiết mang hàm ý tiêu cực; có thể chỉ giáo lý tôn giáo hoặc các học thuyết chính trị, kinh tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marshal', 'en-c1-8', 'marshal', '/ˈmɑːrʃəl/', 'C1', 'tập hợp; điều động; sắp xếp; nhân viên trật tự; người hướng dẫn (tại sự kiện); thống chế', 'v.', NULL, NULL, 'Anh-Anh dùng quá khứ marshalled, Anh-Mỹ dùng marshaled; tránh nhầm lẫn với martial.', 'A volunteer marshalled the runners into a neat line.', NULL, 'Một tình nguyện viên đã sắp xếp những người chạy thành một hàng ngay ngắn.', '{"wordId":"marshal","ukIpa":"/ˈmɑːʃəl/","usIpa":"/ˈmɑːrʃəl/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to gather and arrange people, resources, or ideas effectively","vi":"tập hợp; điều động; sắp xếp"},{"pos":"n.","en":"someone who directs people and maintains order at an event","vi":"nhân viên trật tự; người hướng dẫn (tại sự kiện)"},{"pos":"n.","en":"a military officer holding a very high rank","vi":"thống chế"}],"examples":[{"en":"A volunteer marshalled the runners into a neat line.","vi":"Một tình nguyện viên đã sắp xếp những người chạy thành một hàng ngay ngắn.","audioKind":"ex"},{"en":"Governments must marshal resources effectively to provide emergency housing for communities affected by severe flooding.","vi":"Chính phủ phải điều động hiệu quả các nguồn lực để cung cấp nhà ở khẩn cấp cho các cộng đồng bị ảnh hưởng bởi lũ lụt nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"marshal resources","vi":"điều động nguồn lực"},{"en":"marshal the evidence","vi":"tổng hợp chứng cứ"},{"en":"race marshal","vi":"nhân viên trật tự đường đua"},{"en":"field marshal","vi":"lục quân thống chế"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Anh-Anh dùng quá khứ marshalled, Anh-Mỹ dùng marshaled; tránh nhầm lẫn với martial.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ceremonial', 'en-c1-8', 'ceremonial', '/ˌserəˈmoʊniəl/', 'C1', 'thuộc nghi lễ; mang tính hình thức, nghi thức', 'adj.', 'ceremony (n.), ceremonially (adv.)', 'Đồng nghĩa: ritual', 'ceremonial nhấn mạnh vào mục đích dùng trong nghi lễ; còn ceremonious mang nghĩa câu nệ lễ nghi rườm rà.', 'The mayor wore a ceremonial robe for the opening.', NULL, 'Thị trưởng mặc một chiếc áo choàng nghi lễ cho buổi lễ khai mạc.', '{"wordId":"ceremonial","ukIpa":"/ˌserɪˈməʊniəl/","usIpa":"/ˌserəˈmoʊniəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"used in or connected with a formal public ceremony","vi":"thuộc nghi lễ; mang tính hình thức, nghi thức"}],"examples":[{"en":"The mayor wore a ceremonial robe for the opening.","vi":"Thị trưởng mặc một chiếc áo choàng nghi lễ cho buổi lễ khai mạc.","audioKind":"ex"},{"en":"Traditional ceremonial clothing can strengthen cultural identity and connect younger generations with their community''s history.","vi":"Trang phục nghi lễ truyền thống có thể củng cố bản sắc văn hóa và kết nối thế hệ trẻ với lịch sử cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"ceremonial dress","vi":"trang phục nghi lễ"},{"en":"ceremonial role","vi":"vai trò mang tính hình thức"},{"en":"ceremonial occasion","vi":"dịp lễ nghi"}],"wordFamily":["ceremony (n.)","ceremonially (adv.)"],"synonyms":["ritual"],"antonyms":[],"tipVi":"ceremonial nhấn mạnh vào mục đích dùng trong nghi lễ; còn ceremonious mang nghĩa câu nệ lễ nghi rườm rà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nameless', 'en-c1-8', 'nameless', '/ˈneɪmləs/', 'C1', 'vô danh; ẩn danh; không thể gọi tên; không thể diễn tả', 'adj.', 'name (n.), name (v.), named (adj.)', 'Đồng nghĩa: unnamed, anonymous · Trái nghĩa: named', 'Cụm từ remain nameless mang nghĩa không tiết lộ tên, chứ không nhất thiết là không có tên.', 'A nameless donor left fresh flowers outside the shelter.', NULL, 'Một mạnh thường quân ẩn danh đã để lại những bông hoa tươi bên ngoài khu tạm trú.', '{"wordId":"nameless","ukIpa":"/ˈneɪmləs/","usIpa":"/ˈneɪmləs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Having no name, or having a name that remains unknown","vi":"vô danh; ẩn danh"},{"pos":"adj.","en":"Too difficult to identify or describe clearly","vi":"không thể gọi tên; không thể diễn tả"}],"examples":[{"en":"A nameless donor left fresh flowers outside the shelter.","vi":"Một mạnh thường quân ẩn danh đã để lại những bông hoa tươi bên ngoài khu tạm trú.","audioKind":"ex"},{"en":"Many nameless workers contributed to the construction of monuments that now attract tourists worldwide.","vi":"Nhiều công nhân vô danh đã góp phần xây dựng nên những công trình kiến trúc hiện thu hút du khách khắp nơi trên thế giới.","audioKind":"ex2"}],"collocations":[{"en":"remain nameless","vi":"giấu tên"},{"en":"nameless fear","vi":"nỗi sợ mơ hồ"},{"en":"nameless workers","vi":"những công nhân vô danh"}],"wordFamily":["name (n.)","name (v.)","named (adj.)"],"synonyms":["unnamed","anonymous"],"antonyms":["named"],"tipVi":"Cụm từ remain nameless mang nghĩa không tiết lộ tên, chứ không nhất thiết là không có tên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wreath', 'en-c1-8', 'wreath', '/riːθ/', 'C1', 'vòng hoa; vòng lá', 'n.', 'wreathe (v.)', NULL, 'Chữ w không phát âm; dạng số nhiều là wreaths; động từ tương ứng là wreathe.', 'She hung a wreath of leaves on the door.', NULL, 'Cô ấy treo một vòng lá trên cửa ra vào.', '{"wordId":"wreath","ukIpa":"/riːθ/","usIpa":"/riːθ/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a ring of flowers or leaves used decoratively or ceremonially","vi":"vòng hoa; vòng lá"}],"examples":[{"en":"She hung a wreath of leaves on the door.","vi":"Cô ấy treo một vòng lá trên cửa ra vào.","audioKind":"ex"},{"en":"Laying a wreath at a memorial allows communities to express shared grief and honour the past.","vi":"Việc đặt vòng hoa tại đài tưởng niệm giúp cộng đồng bày tỏ niềm tiếc thương chung và tưởng nhớ quá khứ.","audioKind":"ex2"}],"collocations":[{"en":"lay a wreath","vi":"đặt vòng hoa"},{"en":"a wreath of flowers","vi":"vòng hoa tươi"},{"en":"laurel wreath","vi":"vòng nguyệt quế"}],"wordFamily":["wreathe (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ w không phát âm; dạng số nhiều là wreaths; động từ tương ứng là wreathe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gracious', 'en-c1-8', 'gracious', '/ˈɡreɪʃəs/', 'C1', 'ân cần; hòa nhã; lịch thiệp; sang trọng; thoải mái', 'adj.', 'graciously (adv.), graciousness (n.)', 'Đồng nghĩa: courteous, kind · Trái nghĩa: rude, ungracious', 'Từ gracious nhấn mạnh sự đối xử lịch thiệp, ân cần; trong khi graceful nhấn mạnh dáng vẻ uyển chuyển, duyên dáng.', 'Our gracious host brought extra blankets for everyone.', NULL, 'Người chủ nhà niềm nở của chúng tôi đã chuẩn bị thêm chăn cho tất cả mọi người.', '{"wordId":"gracious","ukIpa":"/ˈɡreɪʃəs/","usIpa":"/ˈɡreɪʃəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"kind and polite, especially when treating others generously","vi":"ân cần; hòa nhã; lịch thiệp"},{"pos":"adj.","en":"elegant, comfortable, and associated with wealth","vi":"sang trọng; thoải mái"}],"examples":[{"en":"Our gracious host brought extra blankets for everyone.","vi":"Người chủ nhà niềm nở của chúng tôi đã chuẩn bị thêm chăn cho tất cả mọi người.","audioKind":"ex"},{"en":"Public figures who remain gracious towards their critics can encourage more respectful discussion within society.","vi":"Những nhân vật công chúng giữ được thái độ hòa nhã với những người chỉ trích có thể thúc đẩy các cuộc thảo luận tôn trọng lẫn nhau trong xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a gracious host","vi":"chủ nhà niềm nở"},{"en":"gracious in defeat","vi":"thái độ nhã nhặn khi thất bại"},{"en":"gracious living","vi":"cuộc sống sang trọng, thoải mái"}],"wordFamily":["graciously (adv.)","graciousness (n.)"],"synonyms":["courteous","kind"],"antonyms":["rude","ungracious"],"tipVi":"Từ gracious nhấn mạnh sự đối xử lịch thiệp, ân cần; trong khi graceful nhấn mạnh dáng vẻ uyển chuyển, duyên dáng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_morality', 'en-c1-8', 'morality', '/məˈræləti/', 'C1', 'đạo đức; chuẩn mực đạo đức; tính đạo đức; sự hợp đạo đức', 'n.', 'moral (adj.), morally (adv.), immoral (adj.), immorality (n.)', 'Đồng nghĩa: ethics · Trái nghĩa: immorality', 'moral là tính từ; morality là danh từ, thường là danh từ không đếm được.', 'Our family discussed morality after finding a lost wallet.', NULL, 'Gia đình chúng tôi đã bàn về vấn đề đạo đức sau khi nhặt được một chiếc ví bị mất.', '{"wordId":"morality","ukIpa":"/məˈræləti/","usIpa":"/məˈræləti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Beliefs and principles about what is right and wrong","vi":"đạo đức; chuẩn mực đạo đức"},{"pos":"n.","en":"The degree to which an action is right or wrong","vi":"tính đạo đức; sự hợp đạo đức"}],"examples":[{"en":"Our family discussed morality after finding a lost wallet.","vi":"Gia đình chúng tôi đã bàn về vấn đề đạo đức sau khi nhặt được một chiếc ví bị mất.","audioKind":"ex"},{"en":"The morality of animal testing remains controversial, particularly when potential medical benefits conflict with concerns about animal welfare.","vi":"Tính đạo đức của việc thử nghiệm trên động vật vẫn còn gây tranh cãi, đặc biệt khi các lợi ích y tế tiềm năng mâu thuẫn với các mối quan tâm về phúc lợi động vật.","audioKind":"ex2"}],"collocations":[{"en":"public morality","vi":"công cộng; đạo đức xã hội"},{"en":"personal morality","vi":"đạo đức cá nhân"},{"en":"the morality of an action","vi":"tính đạo đức của một hành động"}],"wordFamily":["moral (adj.)","morally (adv.)","immoral (adj.)","immorality (n.)"],"synonyms":["ethics"],"antonyms":["immorality"],"tipVi":"moral là tính từ; morality là danh từ, thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consensus', 'en-c1-8', 'consensus', '/kənˈsensəs/', 'C1', 'sự đồng thuận; ý kiến chung', 'n.', 'consensual (adj.)', 'Đồng nghĩa: agreement · Trái nghĩa: disagreement', 'Thường dùng cấu trúc reach a consensus on; sự đồng thuận không nhất thiết phải là sự đồng lòng tuyệt đối 100%.', 'We finally reached a consensus on where to eat.', NULL, 'Cuối cùng chúng tôi đã đạt được sự đồng thuận về việc sẽ ăn uống ở đâu.', '{"wordId":"consensus","ukIpa":"/kənˈsensəs/","usIpa":"/kənˈsensəs/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"General agreement among members of a group.","vi":"sự đồng thuận; ý kiến chung"}],"examples":[{"en":"We finally reached a consensus on where to eat.","vi":"Cuối cùng chúng tôi đã đạt được sự đồng thuận về việc sẽ ăn uống ở đâu.","audioKind":"ex"},{"en":"There is a broad consensus among researchers that early childhood education can improve children''s future learning outcomes.","vi":"Có một sự đồng thuận rộng rãi trong giới nghiên cứu rằng giáo dục mầm non có thể cải thiện kết quả học tập trong tương lai của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"reach a consensus","vi":"đạt được sự đồng thuận"},{"en":"broad consensus","vi":"sự đồng thuận rộng rãi"},{"en":"consensus on","vi":"sự đồng thuận về"},{"en":"build consensus","vi":"tạo dựng sự đồng thuận"}],"wordFamily":["consensual (adj.)"],"synonyms":["agreement"],"antonyms":["disagreement"],"tipVi":"Thường dùng cấu trúc reach a consensus on; sự đồng thuận không nhất thiết phải là sự đồng lòng tuyệt đối 100%.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mistress', 'en-c1-8', 'mistress', '/ˈmɪstrəs/', 'C1', 'phòng nhì; tình nhân (của người đã có gia đình); nữ chủ nhân; bà chủ (cách dùng cũ); nữ cao thủ; bậc thầy nữ', 'n.', NULL, NULL, 'Không được dùng chỉ vợ hoặc bạn gái bình thường; nghĩa nữ chủ nhân nay đã khá cũ.', 'In the novel, he buys his mistress a necklace.', NULL, 'Trong cuốn tiểu thuyết, anh ta mua tặng tình nhân của mình một chiếc vòng cổ.', '{"wordId":"mistress","ukIpa":"/ˈmɪstrəs/","usIpa":"/ˈmɪstrəs/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A woman having a relationship with someone married to another person.","vi":"phòng nhì; tình nhân (của người đã có gia đình)"},{"pos":"n.","en":"A woman who owns or controls a household, in older usage.","vi":"nữ chủ nhân; bà chủ (cách dùng cũ)"},{"pos":"n.","en":"A woman highly skilled in a particular activity.","vi":"nữ cao thủ; bậc thầy nữ"}],"examples":[{"en":"In the novel, he buys his mistress a necklace.","vi":"Trong cuốn tiểu thuyết, anh ta mua tặng tình nhân của mình một chiếc vòng cổ.","audioKind":"ex"},{"en":"Historical novels often portray a wealthy man''s mistress as financially dependent, reflecting unequal opportunities for women.","vi":"Các tiểu thuyết lịch sử thường miêu tả tình nhân của một người đàn ông giàu có ở thế bị phụ thuộc về tài chính, phản ánh sự bất bình đẳng về cơ hội cho phụ nữ.","audioKind":"ex2"}],"collocations":[{"en":"have a mistress","vi":"có tình nhân"},{"en":"mistress of the house","vi":"nữ chủ nhân của ngôi nhà"},{"en":"mistress of her craft","vi":"người phụ nữ tinh thông nghề nghiệp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Không được dùng chỉ vợ hoặc bạn gái bình thường; nghĩa nữ chủ nhân nay đã khá cũ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pretext', 'en-c1-8', 'pretext', '/ˈpriːtekst/', 'C1', 'cái cớ; lý do thoái thác', 'n.', NULL, 'Đồng nghĩa: excuse', 'Nhấn mạnh cái cớ nhằm che đậy mục đích thực sự; thường đi với for hoặc of.', 'He used a headache as a pretext to leave.', NULL, 'Anh ấy lấy cớ bị đau đầu để rời đi.', '{"wordId":"pretext","ukIpa":"/ˈpriːtekst/","usIpa":"/ˈpriːtekst/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A stated reason that hides someone''s real purpose.","vi":"cái cớ; lý do thoái thác"}],"examples":[{"en":"He used a headache as a pretext to leave.","vi":"Anh ấy lấy cớ bị đau đầu để rời đi.","audioKind":"ex"},{"en":"Companies should not use economic uncertainty as a pretext for abandoning their environmental commitments.","vi":"Các doanh nghiệp không nên lấy sự bất ổn kinh tế làm cái cớ để từ bỏ các cam kết bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"under the pretext of","vi":"với cái cớ là"},{"en":"a pretext for doing something","vi":"cái cớ để làm điều gì đó"},{"en":"on some pretext","vi":"với một lý do nào đó"}],"wordFamily":[],"synonyms":["excuse"],"antonyms":[],"tipVi":"Nhấn mạnh cái cớ nhằm che đậy mục đích thực sự; thường đi với for hoặc of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aboriginal', 'en-c1-8', 'aboriginal', '/ˌæbəˈrɪdʒənəl/', 'C1', 'thuộc về nguyên thủy; bản địa; thổ dân; thuộc về văn hóa, ngôn ngữ hoặc người thổ dân Úc', 'adj.', NULL, 'Đồng nghĩa: indigenous', 'Khi chỉ người thổ dân Úc thì viết hoa chữ cái đầu; tránh dùng đơn độc như một danh từ chỉ người mang hàm ý miệt thị.', 'The exhibition celebrates aboriginal cultures from several different regions.', NULL, 'Triển lãm tôn vinh nền văn hóa bản địa đến từ một vài vùng miền khác nhau.', '{"wordId":"aboriginal","ukIpa":"/ˌæbəˈrɪdʒənəl/","usIpa":"/ˌæbəˈrɪdʒənəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Relating to the earliest known inhabitants of a region","vi":"thuộc về nguyên thủy; bản địa; thổ dân"},{"pos":"adj.","en":"Relating to Australia''s Aboriginal peoples, cultures, or languages","vi":"thuộc về văn hóa, ngôn ngữ hoặc người thổ dân Úc"}],"examples":[{"en":"The exhibition celebrates aboriginal cultures from several different regions.","vi":"Triển lãm tôn vinh nền văn hóa bản địa đến từ một vài vùng miền khác nhau.","audioKind":"ex"},{"en":"Protecting aboriginal languages requires sustained funding and close cooperation with the communities that speak them.","vi":"Việc bảo tồn các ngôn ngữ thổ dân đòi hỏi nguồn kinh phí duy trì đều đặn và sự hợp tác chặt chẽ với các cộng đồng sử dụng chúng.","audioKind":"ex2"}],"collocations":[{"en":"aboriginal peoples","vi":"các dân tộc bản địa"},{"en":"Aboriginal culture","vi":"văn hóa thổ dân Úc"},{"en":"Aboriginal communities","vi":"các cộng đồng thổ dân Úc"}],"wordFamily":[],"synonyms":["indigenous"],"antonyms":[],"tipVi":"Khi chỉ người thổ dân Úc thì viết hoa chữ cái đầu; tránh dùng đơn độc như một danh từ chỉ người mang hàm ý miệt thị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_8_1', 'en-c1-8', 'Cách dùng “aboriginal” (adj.) — thuộc về nguyên thủy; bản địa; thổ dân', 'aboriginal peoples  ·  Aboriginal culture  ·  Aboriginal communities', 'Khi chỉ người thổ dân Úc thì viết hoa chữ cái đầu; tránh dùng đơn độc như một danh từ chỉ người mang hàm ý miệt thị.', 'Đồng nghĩa: indigenous', '[{"hanzi":"The exhibition celebrates aboriginal cultures from several different regions.","pinyin":"","meaning":"Triển lãm tôn vinh nền văn hóa bản địa đến từ một vài vùng miền khác nhau."},{"hanzi":"Protecting aboriginal languages requires sustained funding and close cooperation with the communities that speak them.","pinyin":"","meaning":"Việc bảo tồn các ngôn ngữ thổ dân đòi hỏi nguồn kinh phí duy trì đều đặn và sự hợp tác chặt chẽ với các cộng đồng sử dụng chúng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_8_2', 'en-c1-8', 'Cách dùng “vice” (n.) — thói hư tật xấu; hành vi trái đạo đức', 'a minor vice  ·  vice and virtue  ·  a bench vice', 'Nghĩa cái ê-tô trong tiếng Anh-Mỹ được viết là "vise"; "vice-" trong từ phó chủ tịch (vice-president) là tiền tố.', 'Trái nghĩa: virtue', '[{"hanzi":"Eating too much chocolate is my only vice.","pinyin":"","meaning":"Ăn quá nhiều sô-cô-la là thói quen xấu duy nhất của tôi."},{"hanzi":"Excessive consumption is sometimes viewed as a personal vice rather than a consequence of social pressures.","pinyin":"","meaning":"Tiêu dùng quá mức đôi khi bị coi là một thói xấu cá nhân hơn là hệ quả của các áp lực xã hội."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_8_3', 'en-c1-8', 'Cách dùng “gracious” (adj.) — ân cần; hòa nhã; lịch thiệp', 'a gracious host  ·  gracious in defeat  ·  gracious living', 'Từ gracious nhấn mạnh sự đối xử lịch thiệp, ân cần; trong khi graceful nhấn mạnh dáng vẻ uyển chuyển, duyên dáng.', 'Họ từ (Word Family): graciously (adv.), graciousness (n.) | Đồng nghĩa: courteous, kind · Trái nghĩa: rude, ungracious', '[{"hanzi":"Our gracious host brought extra blankets for everyone.","pinyin":"","meaning":"Người chủ nhà niềm nở của chúng tôi đã chuẩn bị thêm chăn cho tất cả mọi người."},{"hanzi":"Public figures who remain gracious towards their critics can encourage more respectful discussion within society.","pinyin":"","meaning":"Những nhân vật công chúng giữ được thái độ hòa nhã với những người chỉ trích có thể thúc đẩy các cuộc thảo luận tôn trọng lẫn nhau trong xã hội."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_8_4', 'en-c1-8', 'Cách dùng “consensus” (n.) — sự đồng thuận; ý kiến chung', 'reach a consensus  ·  broad consensus  ·  consensus on', 'Thường dùng cấu trúc reach a consensus on; sự đồng thuận không nhất thiết phải là sự đồng lòng tuyệt đối 100%.', 'Họ từ (Word Family): consensual (adj.) | Đồng nghĩa: agreement · Trái nghĩa: disagreement', '[{"hanzi":"We finally reached a consensus on where to eat.","pinyin":"","meaning":"Cuối cùng chúng tôi đã đạt được sự đồng thuận về việc sẽ ăn uống ở đâu."},{"hanzi":"There is a broad consensus among researchers that early childhood education can improve children''s future learning outcomes.","pinyin":"","meaning":"Có một sự đồng thuận rộng rãi trong giới nghiên cứu rằng giáo dục mầm non có thể cải thiện kết quả học tập trong tương lai của trẻ em."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_8_1', 'en-c1-8', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_1_1', 'ten_c1_8_1', 'preacher', 'The preacher welcomed everyone before beginning his Sunday talk.', 'The preacher welcomed everyone before beginning his Sunday talk.', '/ˈpriːtʃər/', 'Vị mục sư đã chào đón tất cả mọi người trước khi bắt đầu bài giảng ngày Chủ nhật.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_1_2', 'ten_c1_8_1', 'ideology', 'Their political ideology shapes how they discuss everyday problems.', 'Their political ideology shapes how they discuss everyday problems.', '/ˌaɪdiˈɑːlədʒi/', 'Hệ tư tưởng chính trị của họ định hình cách họ thảo luận về các vấn đề thường ngày.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_1_3', 'ten_c1_8_1', 'taboo', 'Discussing salaries remains a taboo in our office.', 'Discussing salaries remains a taboo in our office.', '/təˈbuː/', 'Việc thảo luận về tiền lương vẫn là điều cấm kỵ ở văn phòng chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_1_4', 'ten_c1_8_1', 'advocate', 'Our neighbours advocate planting more trees along the street.', 'Our neighbours advocate planting more trees along the street.', '/ˈædvəkeɪt/', 'Những người hàng xóm của chúng tôi chủ trương trồng thêm nhiều cây xanh dọc theo con phố.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_1_5', 'ten_c1_8_1', 'righteous', 'She believed returning the wallet was the righteous choice.', 'She believed returning the wallet was the righteous choice.', '/ˈraɪtʃəs/', 'Cô ấy tin rằng việc trả lại chiếc ví là sự lựa chọn chính trực.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_1_6', 'ten_c1_8_1', 'jeopardise', 'Skipping practice could jeopardise your place on the team.', 'Skipping practice could jeopardise your place on the team.', '/ˈdʒepərdaɪz/', 'Việc bỏ tập luyện có thể gây nguy hiểm cho vị trí của bạn trong đội.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_1_7', 'ten_c1_8_1', 'observance', 'Strict observance of kitchen hygiene keeps our food safe.', 'Strict observance of kitchen hygiene keeps our food safe.', '/əbˈzɝːvəns/', 'Việc tuân thủ nghiêm ngặt vệ sinh nhà bếp giúp đảm bảo an toàn thực phẩm của chúng ta.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_1_8', 'ten_c1_8_1', 'disperse', 'The crowd began to disperse when the rain started.', 'The crowd began to disperse when the rain started.', '/dɪˈspɝːs/', 'Đám đông bắt đầu giải tán khi trời bắt đầu đổ mưa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_8_1_1', 'en-c1-8', 'ten_c1_8_1', 'listening', 'listening', 'The preacher welcomed everyone before beginning his Sunday talk.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Gia đình chúng tôi đã bàn về vấn đề đạo đức sau khi nhặt được một chiếc ví bị mất.","Vị mục sư đã chào đón tất cả mọi người trước khi bắt đầu bài giảng ngày Chủ nhật.","Một con chó dữ gầm gừ phía sau hàng rào kim loại cao.","Cô ấy tin rằng việc trả lại chiếc ví là sự lựa chọn chính trực."]'::jsonb, 1, 'The preacher welcomed everyone before beginning his Sunday talk. → Vị mục sư đã chào đón tất cả mọi người trước khi bắt đầu bài giảng ngày Chủ nhật.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_8_1_2', 'en-c1-8', 'ten_c1_8_1', 'listening', 'listening', 'Their political ideology shapes how they discuss everyday problems.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vị mục sư đã chào đón tất cả mọi người trước khi bắt đầu bài giảng ngày Chủ nhật.","Hệ tư tưởng chính trị của họ định hình cách họ thảo luận về các vấn đề thường ngày.","Cung điện này từng là nơi ở của hoàng gia.","Việc bỏ tập luyện có thể gây nguy hiểm cho vị trí của bạn trong đội."]'::jsonb, 1, 'Their political ideology shapes how they discuss everyday problems. → Hệ tư tưởng chính trị của họ định hình cách họ thảo luận về các vấn đề thường ngày.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_8_1_3', 'en-c1-8', 'ten_c1_8_1', 'listening', 'listening', 'Discussing salaries remains a taboo in our office.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những người hàng xóm của chúng tôi chủ trương trồng thêm nhiều cây xanh dọc theo con phố.","Một con chó dữ gầm gừ phía sau hàng rào kim loại cao.","Cô ấy treo một vòng lá trên cửa ra vào.","Việc thảo luận về tiền lương vẫn là điều cấm kỵ ở văn phòng chúng tôi."]'::jsonb, 3, 'Discussing salaries remains a taboo in our office. → Việc thảo luận về tiền lương vẫn là điều cấm kỵ ở văn phòng chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_8_2', 'en-c1-8', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_2_1', 'ten_c1_8_2', 'preacher', 'A local preacher encouraged residents to support families affected by unemployment through practical community projects.', 'A local preacher encouraged residents to support families affected by unemployment through practical community projects.', '/ˈpriːtʃər/', 'Một nhà truyền giáo địa phương đã khuyến khích cư dân chung tay hỗ trợ các gia đình bị ảnh hưởng bởi nạn thất nghiệp thông qua các dự án cộng đồng thiết thực.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_2_2', 'ten_c1_8_2', 'ideology', 'Educational policies often reflect the ideology of those in power rather than the needs of learners.', 'Educational policies often reflect the ideology of those in power rather than the needs of learners.', '/ˌaɪdiˈɑːlədʒi/', 'Các chính sách giáo dục thường phản ánh hệ tư tưởng của những người nắm quyền hơn là nhu cầu thực tế của người học.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_2_3', 'ten_c1_8_2', 'taboo', 'Public education can challenge the taboo surrounding mental illness and encourage more people to seek support.', 'Public education can challenge the taboo surrounding mental illness and encourage more people to seek support.', '/təˈbuː/', 'Giáo dục công cộng có thể phá bỏ những định kiến và điều cấm kỵ xung quanh bệnh tâm thần, đồng thời khuyến khích nhiều người tìm kiếm sự hỗ trợ hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_2_4', 'ten_c1_8_2', 'advocate', 'Many health professionals advocate regular physical activity as an affordable way to prevent chronic disease.', 'Many health professionals advocate regular physical activity as an affordable way to prevent chronic disease.', '/ˈædvəkeɪt/', 'Nhiều chuyên gia y tế ủng hộ việc rèn luyện thể chất thường xuyên như một phương pháp tiết kiệm để phòng ngừa bệnh mạn tính.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_2_5', 'ten_c1_8_2', 'righteous', 'Righteous anger at social injustice can encourage citizens to demand meaningful changes in public policy.', 'Righteous anger at social injustice can encourage citizens to demand meaningful changes in public policy.', '/ˈraɪtʃəs/', 'Sự phẫn nộ chính đáng trước sự bất công xã hội có thể khích lệ người dân đòi hỏi những thay đổi có ý nghĩa trong chính sách công.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_8_2_6', 'ten_c1_8_2', 'jeopardise', 'Reducing investment in public transport could jeopardise efforts to cut urban air pollution and traffic congestion.', 'Reducing investment in public transport could jeopardise efforts to cut urban air pollution and traffic congestion.', '/ˈdʒepərdaɪz/', 'Việc cắt giảm đầu tư vào giao thông công cộng có thể cản trở các nỗ lực cắt giảm ô nhiễm không khí đô thị và ùn tắc giao thông.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_8_2_1', 'en-c1-8', 'ten_c1_8_2', 'listening', 'listening', 'A local preacher encouraged residents to support families affected by unemployment through practical community projects.', NULL, 'Trong câu vừa nghe, từ “preacher” mang nghĩa nào sau đây?', '["thuộc tia tử ngoại; cực tím","người giảng đạo; nhà truyền giáo","bài luận; cuộc thảo luận trang trọng; bài thuyết trình","hợp kim"]'::jsonb, 1, '“preacher” (/ˈpriːtʃər/): người giảng đạo; nhà truyền giáo. Câu đầy đủ: A local preacher encouraged residents to support families affected by unemployment through practical community projects.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_8_2_2', 'en-c1-8', 'ten_c1_8_2', 'listening', 'listening', 'Educational policies often reflect the ideology of those in power rather than the needs of learners.', NULL, 'Trong câu vừa nghe, từ “ideology” mang nghĩa nào sau đây?', '["đồng thời; xảy ra cùng một lúc","tính vĩnh cửu; tính lâu dài; sự ổn định lâu dài","hệ tư tưởng; ý thức hệ","thuộc nghi lễ; mang tính hình thức, nghi thức"]'::jsonb, 2, '“ideology” (/ˌaɪdiˈɑːlədʒi/): hệ tư tưởng; ý thức hệ. Câu đầy đủ: Educational policies often reflect the ideology of those in power rather than the needs of learners.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
