INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_1', 'en-c1-8', NULL, 'comprehensive_test', 'listening', 'preacher', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thư từ; sự trao đổi thư tín","người giảng đạo; nhà truyền giáo","sự rõ ràng; dễ hiểu","tiền đề; giả định"]'::jsonb, 1, 'preacher (/ˈpriːtʃər/) → người giảng đạo; nhà truyền giáo; người nhiệt thành truyền bá một tư tưởng hay hành vi nào đó', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_2', 'en-c1-8', NULL, 'comprehensive_test', 'listening', 'Their political ideology shapes how they discuss everyday problems.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hệ tư tưởng chính trị của họ định hình cách họ thảo luận về các vấn đề thường ngày.","Xin đừng chế giễu điệu nhảy của tôi; tôi vẫn đang học mà.","Trận lũ lụt đã khiến vài gia đình sống gần bờ sông phải rời bỏ nhà cửa.","Triển lãm tôn vinh nền văn hóa bản địa đến từ một vài vùng miền khác nhau."]'::jsonb, 0, 'Their political ideology shapes how they discuss everyday problems. → Hệ tư tưởng chính trị của họ định hình cách họ thảo luận về các vấn đề thường ngày.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_3', 'en-c1-8', NULL, 'comprehensive_test', 'listening', 'taboo', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chứng liệt; sự tê liệt (cơ thể)","dự án kinh doanh rủi ro; công ty liên doanh","điều cấm kỵ; điều kiêng kỵ","chết, thiệt mạng, diệt vong"]'::jsonb, 2, 'taboo (/təˈbuː/) → điều cấm kỵ; điều kiêng kỵ; bị cấm kỵ; bị kiêng kỵ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_4', 'en-c1-8', NULL, 'comprehensive_test', 'listening', 'Our neighbours advocate planting more trees along the street.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cơn mưa lớn buộc chúng tôi phải hủy buổi dã ngoại.","Việc thảo luận về tiền lương vẫn là điều cấm kỵ ở văn phòng chúng tôi.","Gia đình chúng tôi đã bàn về vấn đề đạo đức sau khi nhặt được một chiếc ví bị mất.","Những người hàng xóm của chúng tôi chủ trương trồng thêm nhiều cây xanh dọc theo con phố."]'::jsonb, 3, 'Our neighbours advocate planting more trees along the street. → Những người hàng xóm của chúng tôi chủ trương trồng thêm nhiều cây xanh dọc theo con phố.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_5', 'en-c1-8', NULL, 'comprehensive_test', 'listening', 'righteous', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự thiếu hụt; không đủ","chính trực; đúng đắn về mặt đạo đức","buổi biểu diễn độc tấu; buổi biểu diễn hòa nhạc nhỏ","khó đọc; không đọc được; không thể đọc nổi (do chữ viết không rõ)"]'::jsonb, 1, 'righteous (/ˈraɪtʃəs/) → chính trực; đúng đắn về mặt đạo đức; đầy lòng chính nghĩa; tự cho là đúng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_6', 'en-c1-8', NULL, 'comprehensive_test', 'listening', 'Skipping practice could jeopardise your place on the team.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin đừng chế giễu điệu nhảy của tôi; tôi vẫn đang học mà.","Gia đình chúng tôi đã bàn về vấn đề đạo đức sau khi nhặt được một chiếc ví bị mất.","Việc bỏ tập luyện có thể gây nguy hiểm cho vị trí của bạn trong đội.","Người chủ nhà niềm nở của chúng tôi đã chuẩn bị thêm chăn cho tất cả mọi người."]'::jsonb, 2, 'Skipping practice could jeopardise your place on the team. → Việc bỏ tập luyện có thể gây nguy hiểm cho vị trí của bạn trong đội.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_7', 'en-c1-8', NULL, 'comprehensive_test', 'listening', 'observance', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự chính trực; tính trung thực và tuân thủ các nguyên tắc đạo đức vững chắc","nhập thêm hàng; bổ sung hàng hóa","ngưỡng; mức giới hạn","sự tuân thủ; việc chấp hành"]'::jsonb, 3, 'observance (/əbˈzɝːvəns/) → sự tuân thủ; việc chấp hành; nghi lễ tôn giáo hoặc truyền thống', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_8', 'en-c1-8', NULL, 'comprehensive_test', 'listening', 'The crowd began to disperse when the rain started.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hướng dẫn viên giải thích giáo lý đằng sau các nghi lễ hàng ngày của ngôi đền.","Người chủ nhà niềm nở của chúng tôi đã chuẩn bị thêm chăn cho tất cả mọi người.","Đám đông bắt đầu giải tán khi trời bắt đầu đổ mưa.","Cuối cùng chúng tôi đã đạt được sự đồng thuận về việc sẽ ăn uống ở đâu."]'::jsonb, 2, 'The crowd began to disperse when the rain started. → Đám đông bắt đầu giải tán khi trời bắt đầu đổ mưa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
