INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_18', 'en-c1-8', NULL, 'comprehensive_test', 'reading', NULL, 'A local preacher encouraged residents to support families affected by unemployment through practical community projects.', 'Dựa vào câu trên, từ “preacher” có nghĩa phù hợp nhất là gì?', '["kìm chế; tránh","người giảng đạo; nhà truyền giáo","người nhận; bên tiếp nhận","sự mãn nguyện; cảm giác thỏa mãn"]'::jsonb, 1, 'preacher: người giảng đạo; nhà truyền giáo; người nhiệt thành truyền bá một tư tưởng hay hành vi nào đó. Dịch cả câu: Một nhà truyền giáo địa phương đã khuyến khích cư dân chung tay hỗ trợ các gia đình bị ảnh hưởng bởi nạn thất nghiệp thông qua các dự án cộng đồng thiết thực.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_19', 'en-c1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Educational policies often reflect the ideology of those in power rather than the needs of learners.', 'Dựa vào câu trên, từ “ideology” có nghĩa phù hợp nhất là gì?', '["hội chứng","đồng nhất; thuần nhất; đồng chất","tiết kiệm; giản dị","hệ tư tưởng; ý thức hệ"]'::jsonb, 3, 'ideology: hệ tư tưởng; ý thức hệ. Dịch cả câu: Các chính sách giáo dục thường phản ánh hệ tư tưởng của những người nắm quyền hơn là nhu cầu thực tế của người học.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_20', 'en-c1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Public education can challenge the taboo surrounding mental illness and encourage more people to seek support.', 'Dựa vào câu trên, từ “taboo” có nghĩa phù hợp nhất là gì?', '["trung úy (lục quân); đại úy (hải quân); sĩ quan cấp dưới","điều cấm kỵ; điều kiêng kỵ","sự mạch lạc; tính liên kết; tính logic","ở phía sau; phần sau"]'::jsonb, 1, 'taboo: điều cấm kỵ; điều kiêng kỵ; bị cấm kỵ; bị kiêng kỵ. Dịch cả câu: Giáo dục công cộng có thể phá bỏ những định kiến và điều cấm kỵ xung quanh bệnh tâm thần, đồng thời khuyến khích nhiều người tìm kiếm sự hỗ trợ hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_21', 'en-c1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Many health professionals advocate regular physical activity as an affordable way to prevent chronic disease.', 'Dựa vào câu trên, từ “advocate” có nghĩa phù hợp nhất là gì?', '["chủ quyền; quyền lực tối cao","ranh mãnh, quỷ quyệt, lén lút (thường nhằm vụ lợi)","gây nguy hiểm; làm tổn hại","tán thành; ủng hộ; chủ trương"]'::jsonb, 3, 'advocate: tán thành; ủng hộ; chủ trương; người ủng hộ; người tán thành; luật sư bào chữa. Dịch cả câu: Nhiều chuyên gia y tế ủng hộ việc rèn luyện thể chất thường xuyên như một phương pháp tiết kiệm để phòng ngừa bệnh mạn tính.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_22', 'en-c1-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phòng nhì; tình nhân (của người đã có gia đình)”', '["apologetic","erect","mistress","illiterate"]'::jsonb, 2, 'phòng nhì; tình nhân (của người đã có gia đình) → mistress (/ˈmɪstrəs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_23', 'en-c1-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cái cớ; lý do thoái thác”', '["pretext","thrust","dew","cellular"]'::jsonb, 0, 'cái cớ; lý do thoái thác → pretext (/ˈpriːtekst/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_8_24', 'en-c1-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về nguyên thủy; bản địa; thổ dân”', '["glide","aboriginal","vicious","carp"]'::jsonb, 1, 'thuộc về nguyên thủy; bản địa; thổ dân → aboriginal (/ˌæbəˈrɪdʒənəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-9', 'en', 'Bài 9: Xã hội & Cộng đồng (4) - CEFR C1', 'CEFR C1', 'C1 · Xã hội', '28 từ vựng Tiếng Anh CEFR C1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5009, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_truce', 'en-c1-9', 'truce', '/truːs/', 'C1', 'sự ngưng chiến; thỏa thuận tạm đình chiến', 'n.', NULL, 'Đồng nghĩa: ceasefire, armistice', 'Thường chỉ sự ngừng xung đột mang tính tạm thời, không đồng nghĩa với hòa bình vĩnh viễn.', 'After arguing all morning, the neighbours called a truce.', NULL, 'Sau khi cãi nhau suốt buổi sáng, những người hàng xóm đã tạm đình chiến.', '{"wordId":"truce","ukIpa":"/truːs/","usIpa":"/truːs/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"An agreement to stop fighting or arguing for a time","vi":"sự ngưng chiến; thỏa thuận tạm đình chiến"}],"examples":[{"en":"After arguing all morning, the neighbours called a truce.","vi":"Sau khi cãi nhau suốt buổi sáng, những người hàng xóm đã tạm đình chiến.","audioKind":"ex"},{"en":"A temporary truce can allow aid workers to deliver essential supplies to communities affected by conflict.","vi":"Một thỏa thuận tạm đình chiến có thể tạo điều kiện cho các nhân viên cứu trợ chuyển các vật tư thiết yếu đến các cộng đồng bị ảnh hưởng bởi xung đột.","audioKind":"ex2"}],"collocations":[{"en":"call a truce","vi":"tuyên bố đình chiến"},{"en":"agree to a truce","vi":"đồng ý đình chiến"},{"en":"a temporary truce","vi":"lệnh tạm đình chiến"},{"en":"break a truce","vi":"phá vỡ thỏa thuận đình chiến"}],"wordFamily":[],"synonyms":["ceasefire","armistice"],"antonyms":[],"tipVi":"Thường chỉ sự ngừng xung đột mang tính tạm thời, không đồng nghĩa với hòa bình vĩnh viễn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_handicap', 'en-c1-9', 'handicap', '/ˈhændikæp/', 'C1', 'điều kiện bất lợi; trở ngại; làm cho khó thành công hơn; gây bất lợi; hệ thống điểm chấp trong thể thao', 'n.', NULL, 'Đồng nghĩa: disadvantage, obstacle · Trái nghĩa: advantage', 'Cách dùng chỉ khuyết tật hoặc người khuyết tật hiện nay đã lỗi thời, nên dùng disability.', 'Without a car, the distance became a real handicap.', NULL, 'Không có xe ô tô, khoảng cách thực sự đã trở thành một trở ngại lớn.', '{"wordId":"handicap","ukIpa":"/ˈhændɪkæp/","usIpa":"/ˈhændikæp/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A disadvantage that makes success or progress more difficult.","vi":"điều kiện bất lợi; trở ngại"},{"pos":"v.","en":"To make it harder for someone to succeed.","vi":"làm cho khó thành công hơn; gây bất lợi"},{"pos":"n.","en":"A scoring adjustment allowing players of different abilities to compete fairly.","vi":"hệ thống điểm chấp trong thể thao"}],"examples":[{"en":"Without a car, the distance became a real handicap.","vi":"Không có xe ô tô, khoảng cách thực sự đã trở thành một trở ngại lớn.","audioKind":"ex"},{"en":"Limited access to reliable internet can be a serious handicap for students in remote communities.","vi":"Việc tiếp cận internet ổn định bị hạn chế có thể là một bất lợi nghiêm trọng đối với học sinh ở các cộng đồng vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"a serious handicap","vi":"một bất lợi lớn"},{"en":"a golf handicap","vi":"điểm chấp môn gôn"},{"en":"be handicapped by","vi":"bị cản trở bởi"}],"wordFamily":[],"synonyms":["disadvantage","obstacle"],"antonyms":["advantage"],"tipVi":"Cách dùng chỉ khuyết tật hoặc người khuyết tật hiện nay đã lỗi thời, nên dùng disability.","noteVi":"Dùng để chỉ khuyết tật hoặc người khuyết tật có thể gây cảm giác xúc phạm.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conformity', 'en-c1-9', 'conformity', '/kənˈfɔːrməti/', 'C1', 'sự tuân thủ; tính bầy đàn; sự làm theo quy chuẩn', 'n.', 'conform (v.), conformist (n.), nonconformity (n.)', 'Đồng nghĩa: compliance · Trái nghĩa: nonconformity', 'Cụm in conformity with dùng để chỉ việc phù hợp hoặc tuân theo một quy tắc nào đó.', 'Our art teacher encourages creativity rather than strict conformity.', NULL, 'Giáo viên mỹ thuật của chúng tôi khuyến khích sự sáng tạo hơn là việc rập khuôn theo lề lối nghiêm ngặt.', '{"wordId":"conformity","ukIpa":"/kənˈfɔːməti/","usIpa":"/kənˈfɔːrməti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Behaviour that follows accepted rules, standards, or group expectations.","vi":"sự tuân thủ; tính bầy đàn; sự làm theo quy chuẩn"}],"examples":[{"en":"Our art teacher encourages creativity rather than strict conformity.","vi":"Giáo viên mỹ thuật của chúng tôi khuyến khích sự sáng tạo hơn là việc rập khuôn theo lề lối nghiêm ngặt.","audioKind":"ex"},{"en":"Strong pressure for conformity in schools may discourage students from questioning established ideas and developing independent judgement.","vi":"Áp lực từ sự tuân thủ mạnh mẽ ở trường học có thể làm nhụt chí học sinh trong việc chất vấn các quan điểm đã có sẵn và phát triển năng lực phán đoán độc lập.","audioKind":"ex2"}],"collocations":[{"en":"social conformity","vi":"sự tuân theo xã hội"},{"en":"conformity to standards","vi":"sự tuân thủ tiêu chuẩn"},{"en":"in conformity with","vi":"phù hợp với; tuân theo"},{"en":"pressure for conformity","vi":"áp lực đòi hỏi sự đồng thuận"}],"wordFamily":["conform (v.)","conformist (n.)","nonconformity (n.)"],"synonyms":["compliance"],"antonyms":["nonconformity"],"tipVi":"Cụm in conformity with dùng để chỉ việc phù hợp hoặc tuân theo một quy tắc nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_formality', 'en-c1-9', 'formality', '/fɔːrˈmæləti/', 'C1', 'thủ tục hành chính; nghi thức rườm rà; sự câu nệ hình thức; tính trang trọng', 'n.', 'formal (adj.), formally (adv.), informal (adj.)', NULL, 'Thủ tục thường dùng ở số nhiều formalities; tính chất trang trọng, câu nệ là danh từ không đếm được.', 'Signing this final document is just a formality.', NULL, 'Việc ký kết tài liệu cuối cùng này chỉ mang tính chất thủ tục.', '{"wordId":"formality","ukIpa":"/fɔːˈmæləti/","usIpa":"/fɔːrˈmæləti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A required procedure, often unlikely to change the outcome.","vi":"thủ tục hành chính; nghi thức rườm rà"},{"pos":"n.","en":"The quality of following official rules or social conventions.","vi":"sự câu nệ hình thức; tính trang trọng"}],"examples":[{"en":"Signing this final document is just a formality.","vi":"Việc ký kết tài liệu cuối cùng này chỉ mang tính chất thủ tục.","audioKind":"ex"},{"en":"Excessive formality in classroom discussions may discourage students from expressing their opinions openly and confidently.","vi":"Sự câu nệ hình thức quá mức trong các buổi thảo luận trên lớp có thể khiến học sinh eại bày tỏ quan điểm một cách cởi mở và tự tin.","audioKind":"ex2"}],"collocations":[{"en":"a mere formality","vi":"một thủ tục thuần túy"},{"en":"complete the formalities","vi":"hoàn tất các thủ tục"},{"en":"legal formalities","vi":"thủ tục pháp lý"}],"wordFamily":["formal (adj.)","formally (adv.)","informal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thủ tục thường dùng ở số nhiều formalities; tính chất trang trọng, câu nệ là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feud', 'en-c1-9', 'feud', '/fjuːd/', 'C1', 'mối thù truyền kiếp; cuộc tranh chấp kéo dài, bất hòa lâu năm; gây hấn lâu dài; có mối thù không đội trời chung', 'n.', NULL, 'Đồng nghĩa: conflict, quarrel', 'Nhấn mạnh sự thù địch hoặc tranh chấp kéo dài lâu năm, không phải một cuộc cãi vã nhất thời.', 'The neighbours ended their feud over the garden fence.', NULL, 'Những người hàng xóm đã chấm dứt cuộc tranh chấp lâu năm quanh hàng rào khu vườn.', '{"wordId":"feud","ukIpa":"/fjuːd/","usIpa":"/fjuːd/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A bitter disagreement continuing for a long time.","vi":"mối thù truyền kiếp; cuộc tranh chấp kéo dài, bất hòa lâu năm"},{"pos":"v.","en":"To remain in a bitter, continuing conflict with someone.","vi":"gây hấn lâu dài; có mối thù không đội trời chung"}],"examples":[{"en":"The neighbours ended their feud over the garden fence.","vi":"Những người hàng xóm đã chấm dứt cuộc tranh chấp lâu năm quanh hàng rào khu vườn.","audioKind":"ex"},{"en":"A long-running feud between community leaders can prevent cooperation on projects that would benefit local residents.","vi":"Mối thù kéo dài giữa các nhà lãnh đạo cộng đồng có thể cản trở sự hợp tác trong các dự án mang lại lợi ích cho cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"family feud","vi":"mối thù gia đình"},{"en":"long-running feud","vi":"cuộc tranh chấp kéo dài"},{"en":"feud with someone","vi":"có mối thù với ai đó"}],"wordFamily":[],"synonyms":["conflict","quarrel"],"antonyms":[],"tipVi":"Nhấn mạnh sự thù địch hoặc tranh chấp kéo dài lâu năm, không phải một cuộc cãi vã nhất thời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sarcastic', 'en-c1-9', 'sarcastic', '/sɑːrˈkæstɪk/', 'C1', 'mỉa mai; châm biếm, cay độc', 'adj.', 'sarcasm (n.), sarcastically (adv.)', 'Đồng nghĩa: mocking, scornful · Trái nghĩa: sincere', 'Thường dùng lời lẽ ngược đời để mỉa mai; ironic không nhất thiết mang ý công kích hoặc chế nhạo.', 'His sarcastic comment about my cooking hurt my feelings.', NULL, 'Lời nhận xét mỉa mai của anh ấy về tài nấu ăn của tôi đã làm tổn thương cảm xúc của tôi.', '{"wordId":"sarcastic","ukIpa":"/sɑːˈkæstɪk/","usIpa":"/sɑːrˈkæstɪk/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"using mocking words, often meaning the opposite, to criticize","vi":"mỉa mai; châm biếm, cay độc"}],"examples":[{"en":"His sarcastic comment about my cooking hurt my feelings.","vi":"Lời nhận xét mỉa mai của anh ấy về tài nấu ăn của tôi đã làm tổn thương cảm xúc của tôi.","audioKind":"ex"},{"en":"Sarcastic remarks in online discussions can discourage participation and make constructive debate more difficult.","vi":"Những lời châm biếm trong các cuộc thảo luận trực tuyến có thể làm nản lòng sự tham gia và khiến cuộc tranh luận mang tính xây dựng trở nên khó khăn hơn.","audioKind":"ex2"}],"collocations":[{"en":"a sarcastic remark","vi":"lời châm biếm"},{"en":"a sarcastic tone","vi":"giọng điệu mỉa mai"},{"en":"a sarcastic comment","vi":"lời bình luận cay độc"}],"wordFamily":["sarcasm (n.)","sarcastically (adv.)"],"synonyms":["mocking","scornful"],"antonyms":["sincere"],"tipVi":"Thường dùng lời lẽ ngược đời để mỉa mai; ironic không nhất thiết mang ý công kích hoặc chế nhạo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_normalization', 'en-c1-9', 'normalization', '/ˌnɔːrmələˈzeɪʃən/', 'C1', 'sự bình thường hóa; sự khôi phục trạng thái bình thường; sự chuẩn hóa; sự quy chuẩn', 'n.', 'normal (adj.), normalize (v.), normally (adv.), normality (n.)', NULL, 'Có thể viết là normalisation trong tiếng Anh-Anh; trong ngữ cảnh dữ liệu thường chỉ sự quy chuẩn.', 'The normalization of bus services made commuting easier again.', NULL, 'Việc các tuyến xe buýt hoạt động trở lại bình thường giúp cho việc đi lại thuận tiện hơn.', '{"wordId":"normalization","ukIpa":"/ˌnɔːməlaɪˈzeɪʃən/","usIpa":"/ˌnɔːrmələˈzeɪʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The process of making conditions normal or usual.","vi":"sự bình thường hóa; sự khôi phục trạng thái bình thường"},{"pos":"n.","en":"Adjusting data or values to a common standard.","vi":"sự chuẩn hóa; sự quy chuẩn"}],"examples":[{"en":"The normalization of bus services made commuting easier again.","vi":"Việc các tuyến xe buýt hoạt động trở lại bình thường giúp cho việc đi lại thuận tiện hơn.","audioKind":"ex"},{"en":"The normalization of diplomatic relations can encourage trade and strengthen cooperation on shared environmental challenges.","vi":"Việc bình thường hóa quan hệ ngoại giao có thể thúc đẩy thương mại và tăng cường hợp tác trong việc giải quyết các thách thức chung về môi trường.","audioKind":"ex2"}],"collocations":[{"en":"normalization of relations","vi":"bình thường hóa quan hệ"},{"en":"data normalization","vi":"chuẩn hóa dữ liệu"},{"en":"normalization process","vi":"tiến trình bình thường hóa"}],"wordFamily":["normal (adj.)","normalize (v.)","normally (adv.)","normality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể viết là normalisation trong tiếng Anh-Anh; trong ngữ cảnh dữ liệu thường chỉ sự quy chuẩn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disadvantageous', 'en-c1-9', 'disadvantageous', '/ˌdɪsædvænˈteɪdʒəs/', 'C1', 'bất lợi; gây khó khăn', 'adj.', 'disadvantage (n.), advantage (n.), advantageous (adj.)', 'Đồng nghĩa: unfavourable, unhelpful · Trái nghĩa: advantageous, favourable', 'Thường dùng disadvantageous to sb để chỉ điều bất lợi cho ai đó.', 'The early start time is disadvantageous for commuters.', NULL, 'Giờ bắt đầu sớm tạo sự bất lợi cho những người đi làm xa.', '{"wordId":"disadvantageous","ukIpa":"/ˌdɪsædvɑːnˈteɪdʒəs/","usIpa":"/ˌdɪsædvænˈteɪdʒəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Making success harder or putting someone in a worse position.","vi":"bất lợi; gây khó khăn"}],"examples":[{"en":"The early start time is disadvantageous for commuters.","vi":"Giờ bắt đầu sớm tạo sự bất lợi cho những người đi làm xa.","audioKind":"ex"},{"en":"Limited access to affordable childcare can be particularly disadvantageous to parents seeking full-time employment.","vi":"Việc khó tiếp cận các dịch vụ chăm sóc trẻ giá cả phải chăng có thể đặc biệt bất lợi cho các bậc phụ huynh đang tìm kiếm việc làm toàn thời gian.","audioKind":"ex2"}],"collocations":[{"en":"disadvantageous to someone","vi":"bất lợi cho ai"},{"en":"disadvantageous position","vi":"vị thế bất lợi"},{"en":"disadvantageous conditions","vi":"điều kiện bất lợi"}],"wordFamily":["disadvantage (n.)","advantage (n.)","advantageous (adj.)"],"synonyms":["unfavourable","unhelpful"],"antonyms":["advantageous","favourable"],"tipVi":"Thường dùng disadvantageous to sb để chỉ điều bất lợi cho ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flaunt', 'en-c1-9', 'flaunt', '/flɔːnt/', 'C1', 'khoe khoang; phô trương', 'v.', NULL, 'Đồng nghĩa: show off', 'flaunt có nghĩa là khoe khoang, trong khi flout có nghĩa là phớt lờ quy tắc, tránh nhầm lẫn hai từ này.', 'He flaunted his new watch at dinner last night.', NULL, 'Tối qua anh ấy khoe chiếc đồng hồ mới tại bữa tối.', '{"wordId":"flaunt","ukIpa":"/flɔːnt/","usIpa":"/flɔːnt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To show something proudly to attract attention or admiration.","vi":"khoe khoang; phô trương"}],"examples":[{"en":"He flaunted his new watch at dinner last night.","vi":"Tối qua anh ấy khoe chiếc đồng hồ mới tại bữa tối.","audioKind":"ex"},{"en":"Social media encourages some users to flaunt their wealth, potentially increasing feelings of inadequacy among viewers.","vi":"Mạng xã hội khuyến khích một số người dùng khoe khoang sự giàu có, qua đó có thể làm gia tăng cảm giác kém cỏi ở người xem.","audioKind":"ex2"}],"collocations":[{"en":"flaunt wealth","vi":"khoe của"},{"en":"flaunt success","vi":"phô trương thành công"},{"en":"flaunt possessions","vi":"trưng diện tài sản"}],"wordFamily":[],"synonyms":["show off"],"antonyms":[],"tipVi":"flaunt có nghĩa là khoe khoang, trong khi flout có nghĩa là phớt lờ quy tắc, tránh nhầm lẫn hai từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tacit', 'en-c1-9', 'tacit', '/ˈtæsɪt/', 'C1', 'ngầm hiểu; ngầm đồng ý; tâm ý tương thông', 'adj.', 'tacitly (adv.)', 'Đồng nghĩa: implicit, unspoken · Trái nghĩa: explicit, express', 'tacit chỉ việc không nói ra nhưng đã được hiểu, không phải là sự đồng ý được diễn đạt rõ ràng.', 'Her smile gave me tacit permission to continue.', NULL, 'Nụ cười của cô ấy ngầm cho phép tôi tiếp tục.', '{"wordId":"tacit","ukIpa":"/ˈtæsɪt/","usIpa":"/ˈtæsɪt/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Understood or accepted without being directly stated.","vi":"ngầm hiểu; ngầm đồng ý; tâm ý tương thông"}],"examples":[{"en":"Her smile gave me tacit permission to continue.","vi":"Nụ cười của cô ấy ngầm cho phép tôi tiếp tục.","audioKind":"ex"},{"en":"Public silence should not be interpreted as tacit approval of policies that restrict access to essential services.","vi":"Sự im lặng của công luận không nên được hiểu là sự ngầm đồng tình với các chính sách hạn chế quyền tiếp cận các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"tacit approval","vi":"sự ngầm đồng ý"},{"en":"tacit agreement","vi":"thỏa thuận ngầm"},{"en":"tacit understanding","vi":"sự ngầm hiểu"},{"en":"tacit consent","vi":"sự ngầm chấp thuận"}],"wordFamily":["tacitly (adv.)"],"synonyms":["implicit","unspoken"],"antonyms":["explicit","express"],"tipVi":"tacit chỉ việc không nói ra nhưng đã được hiểu, không phải là sự đồng ý được diễn đạt rõ ràng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vocal', 'en-c1-9', 'vocal', '/ˈvoʊkəl/', 'C1', 'thẳng thắn bày tỏ quan điểm; công khai chỉ trích; thuộc về giọng nói; thuộc về ca hát', 'adj.', 'vocally (adv.), vocalist (n.), vocalise (v.)', 'Đồng nghĩa: outspoken', 'Cấu trúc be vocal about diễn tả thái độ công khai và mạnh mẽ bày tỏ quan điểm về một vấn đề nào đó.', 'Our neighbours were vocal about plans to close the pool.', NULL, 'Các hàng xóm của chúng tôi đã lên tiếng phản đối mạnh mẽ kế hoạch đóng cửa hồ bơi.', '{"wordId":"vocal","ukIpa":"/ˈvəʊkəl/","usIpa":"/ˈvoʊkəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Expressing opinions or complaints openly and strongly.","vi":"thẳng thắn bày tỏ quan điểm; công khai chỉ trích"},{"pos":"adj.","en":"Relating to the voice or to singing.","vi":"thuộc về giọng nói; thuộc về ca hát"}],"examples":[{"en":"Our neighbours were vocal about plans to close the pool.","vi":"Các hàng xóm của chúng tôi đã lên tiếng phản đối mạnh mẽ kế hoạch đóng cửa hồ bơi.","audioKind":"ex"},{"en":"Residents have become increasingly vocal in their opposition to developments that threaten local green spaces.","vi":"Cư dân ngày càng lên tiếng phản đối mạnh mẽ các dự án phát triển đe dọa không gian xanh địa phương.","audioKind":"ex2"}],"collocations":[{"en":"vocal opposition","vi":"sự phản đối mạnh mẽ công khai"},{"en":"vocal critic","vi":"nhà phê bình trực tính"},{"en":"vocal cords","vi":"dây thanh quản"},{"en":"vocal training","vi":"luyện thanh"}],"wordFamily":["vocally (adv.)","vocalist (n.)","vocalise (v.)"],"synonyms":["outspoken"],"antonyms":[],"tipVi":"Cấu trúc be vocal about diễn tả thái độ công khai và mạnh mẽ bày tỏ quan điểm về một vấn đề nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dishonour', 'en-c1-9', 'dishonour', '/dɪsˈɑːnər/', 'C1', 'sự ô nhục; sự mất thể diện; tiếng nhơ; làm cho mất mặt; làm nhục; làm ô danh; không giữ lời hứa; bội ước; không thực hiện thỏa thuận', 'n.', 'dishonourable (adj.), dishonourably (adv.), honour (n.)', 'Đồng nghĩa: disgrace, shame · Trái nghĩa: honour', 'Cách viết dishonour là theo chuẩn Anh-Anh, trong khi Anh-Mỹ viết là dishonor.', 'His cheating brought dishonour on the whole team.', NULL, 'Hành vi gian lận của anh ta đã mang lại tiếng nhơ cho toàn đội.', '{"wordId":"dishonour","ukIpa":"/dɪsˈɒnə/","usIpa":"/dɪsˈɑːnər/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Loss of respect caused by shameful or dishonest behaviour.","vi":"sự ô nhục; sự mất thể diện; tiếng nhơ"},{"pos":"v.","en":"To cause someone or something to lose respect.","vi":"làm cho mất mặt; làm nhục; làm ô danh"},{"pos":"v.","en":"To fail to keep a promise or fulfil an agreement.","vi":"không giữ lời hứa; bội ước; không thực hiện thỏa thuận"}],"examples":[{"en":"His cheating brought dishonour on the whole team.","vi":"Hành vi gian lận của anh ta đã mang lại tiếng nhơ cho toàn đội.","audioKind":"ex"},{"en":"Companies that dishonour their commitments to workers risk losing public trust and damaging their long-term commercial prospects.","vi":"Các công ty không giữ cam kết với người lao động có nguy cơ đánh mất lòng tin của công chúng và tổn hại đến triển vọng thương mại lâu dài của họ.","audioKind":"ex2"}],"collocations":[{"en":"bring dishonour on","vi":"làm nhục...; mang tiếng nhơ cho..."},{"en":"dishonour a promise","vi":"nuốt lời hứa"},{"en":"dishonour an agreement","vi":"không tuân thủ thỏa thuận"}],"wordFamily":["dishonourable (adj.)","dishonourably (adv.)","honour (n.)"],"synonyms":["disgrace","shame"],"antonyms":["honour"],"tipVi":"Cách viết dishonour là theo chuẩn Anh-Anh, trong khi Anh-Mỹ viết là dishonor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concede', 'en-c1-9', 'concede', '/kənˈsiːd/', 'C1', 'thừa nhận (thường là miễn cưỡng); nhượng bộ; giao lại; thừa nhận thất bại; chịu thua', 'v.', 'concession (n.)', 'Đồng nghĩa: admit, acknowledge · Trái nghĩa: deny', 'Thường mang hàm ý ban đầu phản đối nhưng sau đó buộc phải thừa nhận.', 'He finally conceded that my route was much quicker.', NULL, 'Cuối cùng anh ấy cũng thừa nhận rằng tuyến đường của tôi nhanh hơn nhiều.', '{"wordId":"concede","ukIpa":"/kənˈsiːd/","usIpa":"/kənˈsiːd/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To admit something is true, often unwillingly","vi":"thừa nhận (thường là miễn cưỡng)"},{"pos":"v.","en":"To give up something or allow it after resistance","vi":"nhượng bộ; giao lại"},{"pos":"v.","en":"To accept that you have lost a contest","vi":"thừa nhận thất bại; chịu thua"}],"examples":[{"en":"He finally conceded that my route was much quicker.","vi":"Cuối cùng anh ấy cũng thừa nhận rằng tuyến đường của tôi nhanh hơn nhiều.","audioKind":"ex"},{"en":"Although critics concede that tourism creates jobs, they argue that its environmental costs are often overlooked.","vi":"Mặc dù các nhà phê bình thừa nhận rằng du lịch tạo ra việc làm, họ vẫn cho rằng những tổn hại về môi trường thường bị phớt lờ.","audioKind":"ex2"}],"collocations":[{"en":"concede that","vi":"thừa nhận rằng"},{"en":"concede defeat","vi":"thừa nhận thất bại"},{"en":"concede a point","vi":"nhượng bộ một điểm"},{"en":"concede ground","vi":"nhượng bộ"}],"wordFamily":["concession (n.)"],"synonyms":["admit","acknowledge"],"antonyms":["deny"],"tipVi":"Thường mang hàm ý ban đầu phản đối nhưng sau đó buộc phải thừa nhận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_multitude', 'en-c1-9', 'multitude', '/ˈmʌltɪtuːd/', 'C1', 'số lượng rất lớn người hoặc vật; đông đảo quần chúng hoặc công chúng nói chung', 'n.', NULL, NULL, 'a multitude of đi kèm với danh từ số nhiều, thể hiện số lượng lớn.', 'A multitude of colourful birds gathered around the pond.', NULL, 'Một đàn chim đầy màu sắc tụ tập quanh ao.', '{"wordId":"multitude","ukIpa":"/ˈmʌltɪtjuːd/","usIpa":"/ˈmʌltɪtuːd/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A very large number of people or things","vi":"số lượng rất lớn người hoặc vật"},{"pos":"n.","en":"A large crowd or the ordinary public","vi":"đông đảo quần chúng hoặc công chúng nói chung"}],"examples":[{"en":"A multitude of colourful birds gathered around the pond.","vi":"Một đàn chim đầy màu sắc tụ tập quanh ao.","audioKind":"ex"},{"en":"Urban planners must consider a multitude of factors when designing affordable housing for growing populations.","vi":"Các nhà quy hoạch đô thị phải cân nhắc vô số yếu tố khi thiết kế nhà ở giá rẻ cho dân số ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"a multitude of factors","vi":"vô số yếu tố"},{"en":"a multitude of options","vi":"rất nhiều lựa chọn"},{"en":"a vast multitude","vi":"đông đảo quần chúng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"a multitude of đi kèm với danh từ số nhiều, thể hiện số lượng lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deceased', 'en-c1-9', 'deceased', '/dɪˈsiːst/', 'C1', 'đã qua đời, thường dùng trong ngữ cảnh trang trọng hoặc pháp lý; người hoặc những người đã qua đời', 'adj.', 'decease (n.)', 'Đồng nghĩa: dead, late · Trái nghĩa: living, alive', 'Từ vựng trang trọng; the deceased có thể chỉ một hoặc nhiều người đã qua đời.', 'She keeps a photograph of her deceased grandfather nearby.', NULL, 'Cô ấy giữ bức ảnh của người ông quá cố ngay bên cạnh.', '{"wordId":"deceased","ukIpa":"/dɪˈsiːst/","usIpa":"/dɪˈsiːst/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"No longer alive, especially in formal or legal contexts.","vi":"đã qua đời, thường dùng trong ngữ cảnh trang trọng hoặc pháp lý"},{"pos":"n.","en":"A person or people who have died.","vi":"người hoặc những người đã qua đời"}],"examples":[{"en":"She keeps a photograph of her deceased grandfather nearby.","vi":"Cô ấy giữ bức ảnh của người ông quá cố ngay bên cạnh.","audioKind":"ex"},{"en":"Museums sometimes display personal belongings of deceased artists to help visitors understand their lives and creative influences.","vi":"Các viện bảo tàng đôi khi trưng bày đồ dùng cá nhân của các nghệ sĩ đã qua đời để giúp khách tham quan hiểu về cuộc đời và sức ảnh hưởng sáng tạo của họ.","audioKind":"ex2"}],"collocations":[{"en":"a deceased relative","vi":"người thân đã khuất"},{"en":"the deceased","vi":"người đã khuất"},{"en":"the deceased''s estate","vi":"di sản của người đã khuất"}],"wordFamily":["decease (n.)"],"synonyms":["dead","late"],"antonyms":["living","alive"],"tipVi":"Từ vựng trang trọng; the deceased có thể chỉ một hoặc nhiều người đã qua đời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_radical', 'en-c1-9', 'radical', '/ˈrædɪkəl/', 'C1', 'mang tính căn bản, thay đổi sâu sắc bản chất cốt lõi của cái gì đó; ủng hộ những thay đổi lớn về chính trị hoặc xã hội vượt ra ngoài các quan điểm thông thường; người ủng hộ những thay đổi lớn về chính trị hoặc xã hội', 'adj.', 'radically (adv.), radicalism (n.)', 'Trái nghĩa: conservative', 'radical change chỉ sự thay đổi tận gốc, không nhất thiết liên quan đến chính trị.', 'Turning our garage into a kitchen was a radical change.', NULL, 'Việc biến nhà để xe thành nhà bếp là một sự thay đổi hoàn toàn triệt để.', '{"wordId":"radical","ukIpa":"/ˈrædɪkəl/","usIpa":"/ˈrædɪkəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Involving major changes to the basic nature of something.","vi":"mang tính căn bản, thay đổi sâu sắc bản chất cốt lõi của cái gì đó"},{"pos":"adj.","en":"Supporting major political or social changes beyond accepted views.","vi":"ủng hộ những thay đổi lớn về chính trị hoặc xã hội vượt ra ngoài các quan điểm thông thường"},{"pos":"n.","en":"A person who supports major political or social change.","vi":"người ủng hộ những thay đổi lớn về chính trị hoặc xã hội"}],"examples":[{"en":"Turning our garage into a kitchen was a radical change.","vi":"Việc biến nhà để xe thành nhà bếp là một sự thay đổi hoàn toàn triệt để.","audioKind":"ex"},{"en":"Reducing dependence on private cars requires radical changes to urban planning and public transport investment.","vi":"Giảm sự phụ thuộc vào ô tô cá nhân đòi hỏi những thay đổi mang tính căn bản đối với quy hoạch đô thị và đầu tư giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"radical change","vi":"thay đổi căn bản"},{"en":"radical reform","vi":"cải cách triệt để"},{"en":"radical ideas","vi":"tư tưởng cấp tiến"}],"wordFamily":["radically (adv.)","radicalism (n.)"],"synonyms":[],"antonyms":["conservative"],"tipVi":"radical change chỉ sự thay đổi tận gốc, không nhất thiết liên quan đến chính trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mediate', 'en-c1-9', 'mediate', '/ˈmiːdieɪt/', 'C1', 'hòa giải; làm trung gian', 'v.', 'mediation (n.), mediator (n.)', 'Đồng nghĩa: arbitrate', 'Mediate thiên về việc thúc đẩy đạt được thỏa thuận; arbitrate có thể chỉ việc đưa ra phán quyết trọng tài.', 'Our neighbour offered to mediate when we argued about parking.', NULL, 'Hàng xóm của chúng tôi đã đề nghị làm trung gian khi chúng tôi tranh cãi về chỗ đậu xe.', '{"wordId":"mediate","ukIpa":"/ˈmiːdieɪt/","usIpa":"/ˈmiːdieɪt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To help opposing sides reach an agreement.","vi":"hòa giải; làm trung gian"}],"examples":[{"en":"Our neighbour offered to mediate when we argued about parking.","vi":"Hàng xóm của chúng tôi đã đề nghị làm trung gian khi chúng tôi tranh cãi về chỗ đậu xe.","audioKind":"ex"},{"en":"Independent organisations can mediate between employers and workers to resolve disputes before they disrupt essential public services.","vi":"Các tổ chức độc lập có thể làm trung gian giữa người sử dụng lao động và người lao động để giải quyết các tranh chấp trước khi chúng làm gián đoạn các dịch vụ công thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"mediate between two sides","vi":"hòa giải giữa hai bên"},{"en":"mediate a dispute","vi":"giải quyết tranh chấp"},{"en":"mediate a settlement","vi":"làm trung gian đạt được thỏa thuận hòa giải"}],"wordFamily":["mediation (n.)","mediator (n.)"],"synonyms":["arbitrate"],"antonyms":[],"tipVi":"Mediate thiên về việc thúc đẩy đạt được thỏa thuận; arbitrate có thể chỉ việc đưa ra phán quyết trọng tài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conspiracy', 'en-c1-9', 'conspiracy', '/kənˈspɪrəsi/', 'C1', 'âm mưu; sự thông đồng', 'n.', 'conspire (v.), conspirator (n.), conspiratorial (adj.)', 'Đồng nghĩa: plot', 'conspiracy to do sth có nghĩa là mưu đồ làm việc gì đó.', 'Police uncovered a conspiracy to steal valuable paintings.', NULL, 'Cảnh sát đã phát hiện ra một âm mưu đánh cắp những bức tranh quý giá.', '{"wordId":"conspiracy","ukIpa":"/kənˈspɪrəsi/","usIpa":"/kənˈspɪrəsi/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A secret plan by several people to do something wrong.","vi":"âm mưu; sự thông đồng"}],"examples":[{"en":"Police uncovered a conspiracy to steal valuable paintings.","vi":"Cảnh sát đã phát hiện ra một âm mưu đánh cắp những bức tranh quý giá.","audioKind":"ex"},{"en":"False conspiracy theories can spread rapidly online, weakening public trust in scientific institutions.","vi":"Các thuyết âm mưu sai lệch có thể lan truyền nhanh chóng trên mạng, làm xói mòn lòng tin của công chúng đối với các viện nghiên cứu khoa học.","audioKind":"ex2"}],"collocations":[{"en":"conspiracy theory","vi":"thuyết âm mưu"},{"en":"uncover a conspiracy","vi":"vạch trần một âm mưu"},{"en":"conspiracy to commit fraud","vi":"âm mưu lừa đảo"}],"wordFamily":["conspire (v.)","conspirator (n.)","conspiratorial (adj.)"],"synonyms":["plot"],"antonyms":[],"tipVi":"conspiracy to do sth có nghĩa là mưu đồ làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reliance', 'en-c1-9', 'reliance', '/rɪˈlaɪəns/', 'C1', 'sự phụ thuộc; sự tín nhiệm', 'n.', 'rely (v.), reliant (adj.), reliable (adj.), reliability (n.)', 'Đồng nghĩa: dependence · Trái nghĩa: independence', 'reliance là danh từ không đếm được và thường đi kèm với giới từ on.', 'Cycling to work has reduced my reliance on buses.', NULL, 'Đạp xe đi làm đã giúp tôi giảm bớt sự phụ thuộc vào xe buýt.', '{"wordId":"reliance","ukIpa":"/rɪˈlaɪəns/","usIpa":"/rɪˈlaɪəns/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The state of depending on or trusting someone or something.","vi":"sự phụ thuộc; sự tín nhiệm"}],"examples":[{"en":"Cycling to work has reduced my reliance on buses.","vi":"Đạp xe đi làm đã giúp tôi giảm bớt sự phụ thuộc vào xe buýt.","audioKind":"ex"},{"en":"Reducing reliance on fossil fuels requires sustained investment in renewable energy and improvements to public transport infrastructure.","vi":"Việc giảm bớt sự phụ thuộc vào nhiên liệu hóa thạch đòi hỏi phải đầu tư bền vững vào năng lượng tái tạo và cải thiện cơ sở hạ tầng giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"reliance on","vi":"sự phụ thuộc vào"},{"en":"heavy reliance on","vi":"sự phụ thuộc nặng nề vào"},{"en":"reduce reliance on","vi":"giảm bớt sự phụ thuộc vào"},{"en":"self-reliance","vi":"sự tự lực"}],"wordFamily":["rely (v.)","reliant (adj.)","reliable (adj.)","reliability (n.)"],"synonyms":["dependence"],"antonyms":["independence"],"tipVi":"reliance là danh từ không đếm được và thường đi kèm với giới từ on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restraint', 'en-c1-9', 'restraint', '/rɪˈstreɪnt/', 'C1', 'sự kiềm chế; tính tự chủ; sự hạn chế; điều kiện ràng buộc; thiết bị ràng buộc; đai an toàn', 'n.', 'restrain (v.), restrained (adj.), unrestrained (adj.)', 'Đồng nghĩa: self-control', 'Nghĩa chỉ sự tự chủ thường không đếm được; nghĩa chỉ sự hạn chế thường dùng số nhiều restraints on.', 'She showed restraint and saved the last biscuit for me.', NULL, 'Cô ấy đã biết tự kiềm chế và để dành chiếc bánh quy cuối cùng cho tôi.', '{"wordId":"restraint","ukIpa":"/rɪˈstreɪnt/","usIpa":"/rɪˈstreɪnt/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"control over your feelings, behaviour, or desires","vi":"sự kiềm chế; tính tự chủ"},{"pos":"n.","en":"a rule or measure that limits actions or freedom","vi":"sự hạn chế; điều kiện ràng buộc"},{"pos":"n.","en":"a device that prevents someone or something from moving freely","vi":"thiết bị ràng buộc; đai an toàn"}],"examples":[{"en":"She showed restraint and saved the last biscuit for me.","vi":"Cô ấy đã biết tự kiềm chế và để dành chiếc bánh quy cuối cùng cho tôi.","audioKind":"ex"},{"en":"Governments should exercise restraint when introducing restrictions that could limit citizens'' access to reliable information.","vi":"Chính phủ nên tỏ ra kiềm chế khi đưa ra các quy định có thể hạn chế quyền tiếp cận thông tin đáng tin cậy của người dân.","audioKind":"ex2"}],"collocations":[{"en":"show restraint","vi":"thể hiện sự kiềm chế"},{"en":"exercise restraint","vi":"giữ sự kiềm chế"},{"en":"restraints on spending","vi":"các biện pháp hạn chế chi tiêu"},{"en":"child restraint","vi":"ghế an toàn cho trẻ em"}],"wordFamily":["restrain (v.)","restrained (adj.)","unrestrained (adj.)"],"synonyms":["self-control"],"antonyms":[],"tipVi":"Nghĩa chỉ sự tự chủ thường không đếm được; nghĩa chỉ sự hạn chế thường dùng số nhiều restraints on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obliging', 'en-c1-9', 'obliging', '/əˈblaɪdʒɪŋ/', 'C1', 'hay giúp đỡ; nhiệt tình; sẵn lòng giúp đỡ', 'adj.', 'oblige (v.), obligingly (adv.)', 'Đồng nghĩa: helpful, accommodating · Trái nghĩa: unhelpful, uncooperative', 'obliging chỉ sự sẵn lòng giúp đỡ; obliged thường biểu thị sự bắt buộc hoặc biết ơn.', 'An obliging neighbour watered our plants while we travelled.', NULL, 'Một người hàng xóm nhiệt tình đã tưới cây giúp chúng tôi trong suốt chuyến đi.', '{"wordId":"obliging","ukIpa":"/əˈblaɪdʒɪŋ/","usIpa":"/əˈblaɪdʒɪŋ/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"willing and happy to help other people","vi":"hay giúp đỡ; nhiệt tình; sẵn lòng giúp đỡ"}],"examples":[{"en":"An obliging neighbour watered our plants while we travelled.","vi":"Một người hàng xóm nhiệt tình đã tưới cây giúp chúng tôi trong suốt chuyến đi.","audioKind":"ex"},{"en":"Obliging staff can improve patients'' experiences by answering questions patiently and responding promptly to reasonable requests.","vi":"Nhân viên nhiệt tình có thể nâng cao trải nghiệm của bệnh nhân bằng cách kiên nhẫn giải đáp thắc mắc và phản hồi nhanh chóng trước những yêu cầu hợp lý.","audioKind":"ex2"}],"collocations":[{"en":"obliging staff","vi":"nhân viên nhiệt tình"},{"en":"an obliging neighbour","vi":"người hàng xóm hay giúp đỡ"},{"en":"friendly and obliging","vi":"thân thiện và nhiệt tình"}],"wordFamily":["oblige (v.)","obligingly (adv.)"],"synonyms":["helpful","accommodating"],"antonyms":["unhelpful","uncooperative"],"tipVi":"obliging chỉ sự sẵn lòng giúp đỡ; obliged thường biểu thị sự bắt buộc hoặc biết ơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heiress', 'en-c1-9', 'heiress', '/ˈeres/', 'C1', 'nữ thừa kế gia sản lớn', 'n.', 'heir (n.), inherit (v.), inheritance (n.)', NULL, 'Chữ h không phát âm; heir ngày nay cũng có thể dùng chung cho người thừa kế bất kể giới tính.', 'The young heiress turned her family mansion into a museum.', NULL, 'Nữ người thừa kế trẻ tuổi đã biến biệt thự của gia đình thành một bảoตàng.', '{"wordId":"heiress","ukIpa":"/ˈeəres/","usIpa":"/ˈeres/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A woman who inherits or expects to inherit substantial wealth.","vi":"nữ thừa kế gia sản lớn"}],"examples":[{"en":"The young heiress turned her family mansion into a museum.","vi":"Nữ người thừa kế trẻ tuổi đã biến biệt thự của gia đình thành một bảoตàng.","audioKind":"ex"},{"en":"The heiress funded scholarships for disadvantaged students, illustrating how inherited wealth can support wider educational opportunities.","vi":"Nữ thừa kế này đã tài trợ học bổng cho học sinh có hoàn cảnh khó khăn, minh chứng cho việc tài sản thừa kế có thể hỗ trợ mở rộng các cơ hội giáo dục ra sao.","audioKind":"ex2"}],"collocations":[{"en":"heiress to a fortune","vi":"người thừa kế khối tài sản kếch xù"},{"en":"a wealthy heiress","vi":"một nữ thừa kế giàu có"}],"wordFamily":["heir (n.)","inherit (v.)","inheritance (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ h không phát âm; heir ngày nay cũng có thể dùng chung cho người thừa kế bất kể giới tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intervene', 'en-c1-9', 'intervene', '/ˌɪntərˈviːn/', 'C1', 'can thiệp; can dự; chêm vào; ngắt lời; xảy ra xen vào', 'v.', 'intervention (n.), intervening (adj.)', 'Đồng nghĩa: intercede, step in', 'Là động từ không túc từ (nội động từ): intervene in sth; không được trực tiếp đi với tân ngữ.', 'The coach intervened before the argument became more heated.', NULL, 'Huấn luyện viên đã can thiệp trước khi cuộc tranh cãi trở nên căng thẳng hơn.', '{"wordId":"intervene","ukIpa":"/ˌɪntəˈviːn/","usIpa":"/ˌɪntərˈviːn/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to become involved in a situation to influence what happens","vi":"can thiệp; can dự"},{"pos":"v.","en":"to interrupt a conversation with a comment","vi":"chêm vào; ngắt lời"},{"pos":"v.","en":"to happen between events, sometimes preventing a planned action","vi":"xảy ra xen vào"}],"examples":[{"en":"The coach intervened before the argument became more heated.","vi":"Huấn luyện viên đã can thiệp trước khi cuộc tranh cãi trở nên căng thẳng hơn.","audioKind":"ex"},{"en":"Governments may need to intervene when market competition fails to provide affordable essential services.","vi":"Chính phủ có thể cần phải can thiệp khi cạnh tranh thị trường không thể cung cấp các dịch vụ thiết yếu với mức giá phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"intervene in a dispute","vi":"can thiệp vào một tranh chấp"},{"en":"intervene to prevent","vi":"can thiệp để ngăn chặn"},{"en":"government intervention","vi":"sự can thiệp của chính phủ"}],"wordFamily":["intervention (n.)","intervening (adj.)"],"synonyms":["intercede","step in"],"antonyms":[],"tipVi":"Là động từ không túc từ (nội động từ): intervene in sth; không được trực tiếp đi với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whitewash', 'en-c1-9', 'whitewash', '/ˈwaɪtwɑːʃ/', 'C1', 'che đậy; bao che; che giấu lỗi lầm; sự che đậy; sự bao che; vôi nước; nước vôi quét tường', 'v.', NULL, 'Đồng nghĩa: cover up · Trái nghĩa: expose', 'Nghĩa bóng mang sắc thái tiêu cực, dùng để chỉ việc che lấp vấn đề chứ không giải quyết tận gốc.', 'They tried to whitewash the mistake instead of apologising.', NULL, 'Họ đã cố gắng che đậy lỗi lầm thay vì xin lỗi.', '{"wordId":"whitewash","ukIpa":"/ˈwaɪtwɒʃ/","usIpa":"/ˈwaɪtwɑːʃ/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To hide faults or wrongdoing so something appears acceptable.","vi":"che đậy; bao che; che giấu lỗi lầm"},{"pos":"n.","en":"An attempt to hide faults or wrongdoing.","vi":"sự che đậy; sự bao che"},{"pos":"n.","en":"A white liquid mixture used to coat walls.","vi":"vôi nước; nước vôi quét tường"}],"examples":[{"en":"They tried to whitewash the mistake instead of apologising.","vi":"Họ đã cố gắng che đậy lỗi lầm thay vì xin lỗi.","audioKind":"ex"},{"en":"Independent investigations are essential to prevent organisations from attempting to whitewash serious failures in public safety.","vi":"Các cuộc điều tra độc lập đóng vai trò cốt lõi trong việc ngăn chặn các tổ chức cố gắng che đậy những sai sót nghiêm trọng về an toàn công cộng.","audioKind":"ex2"}],"collocations":[{"en":"whitewash a scandal","vi":"che đậy một vụ bê bối"},{"en":"an official whitewash","vi":"sự bao che chính thức"},{"en":"a coat of whitewash","vi":"một lớp vôi quét tường"}],"wordFamily":[],"synonyms":["cover up"],"antonyms":["expose"],"tipVi":"Nghĩa bóng mang sắc thái tiêu cực, dùng để chỉ việc che lấp vấn đề chứ không giải quyết tận gốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vogue', 'en-c1-9', 'vogue', '/voʊɡ/', 'C1', 'mốt; sự thịnh hành; phong trào', 'n.', 'voguish (adj.)', 'Đồng nghĩa: fashion, trend', 'Thường dùng cấu trúc in vogue để chỉ sự thịnh hành; không dùng như một danh từ chỉ vật thể đếm được thông thường.', 'Wide trousers are back in vogue this summer.', NULL, 'Quần ống rộng đang mốt trở lại vào mùa hè này.', '{"wordId":"vogue","ukIpa":"/vəʊɡ/","usIpa":"/voʊɡ/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a style or practice popular at a particular time","vi":"mốt; sự thịnh hành; phong trào"}],"examples":[{"en":"Wide trousers are back in vogue this summer.","vi":"Quần ống rộng đang mốt trở lại vào mùa hè này.","audioKind":"ex"},{"en":"The current vogue for repairing old furniture may help reduce household waste and encourage more sustainable consumption.","vi":"Trào lưu sửa chữa đồ nội thất cũ hiện nay có thể giúp giảm rác thải sinh hoạt và khuyến khích tiêu dùng bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"in vogue","vi":"đang thịnh hành"},{"en":"come into vogue","vi":"trở thành mốt"},{"en":"the vogue for","vi":"trào lưu về..."}],"wordFamily":["voguish (adj.)"],"synonyms":["fashion","trend"],"antonyms":[],"tipVi":"Thường dùng cấu trúc in vogue để chỉ sự thịnh hành; không dùng như một danh từ chỉ vật thể đếm được thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transcend', 'en-c1-9', 'transcend', '/trænˈsend/', 'C1', 'vượt qua; vượt ra ngoài giới hạn', 'v.', 'transcendence (n), transcendent (adj)', 'Đồng nghĩa: go beyond', 'Là ngoại động từ, đi thẳng với tân ngữ mà không cần thêm giới từ beyond.', 'Their friendship transcended the distance between their homes.', NULL, 'Tình bạn của họ đã vượt qua khoảng cách địa lý giữa hai gia đình.', '{"wordId":"transcend","ukIpa":"/trænˈsend/","usIpa":"/trænˈsend/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To go beyond ordinary limits, differences, or expectations.","vi":"vượt qua; vượt ra ngoài giới hạn"}],"examples":[{"en":"Their friendship transcended the distance between their homes.","vi":"Tình bạn của họ đã vượt qua khoảng cách địa lý giữa hai gia đình.","audioKind":"ex"},{"en":"International cooperation on climate change must transcend national interests to protect the planet for future generations.","vi":"Hợp tác quốc tế về biến đổi khí hậu phải vượt lên trên lợi ích quốc gia để bảo vệ hành tinh cho các thế hệ tương lai.","audioKind":"ex2"}],"collocations":[{"en":"transcend boundaries","vi":"vượt qua ranh giới"},{"en":"transcend cultural differences","vi":"vượt qua sự khác biệt văn hóa"},{"en":"transcend national interests","vi":"vượt lên trên lợi ích quốc gia"}],"wordFamily":["transcendence (n)","transcendent (adj)"],"synonyms":["go beyond"],"antonyms":[],"tipVi":"Là ngoại động từ, đi thẳng với tân ngữ mà không cần thêm giới từ beyond.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pry', 'en-c1-9', 'pry', '/praɪ/', 'C1', 'xọc mạch; tọc mạch; dòm ngó chuyện riêng tư; cạy; nạy; bẩy ra', 'v.', 'prying (adj.)', 'Đồng nghĩa: snoop', 'Dùng cấu trúc pry into khi chỉ hành động tọc mạch; khi chỉ hành động cạy/bẩy, tiếng Anh Anh thường dùng prise.', 'Please don''t pry into my sister''s private life.', NULL, 'Xin đừng tọc mạch vào đời tư của em gái tôi.', '{"wordId":"pry","ukIpa":"/praɪ/","usIpa":"/praɪ/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To seek private information about someone in an intrusive way.","vi":"xọc mạch; tọc mạch; dòm ngó chuyện riêng tư"},{"pos":"v.","en":"To force something open or loose using a tool.","vi":"cạy; nạy; bẩy ra"}],"examples":[{"en":"Please don''t pry into my sister''s private life.","vi":"Xin đừng tọc mạch vào đời tư của em gái tôi.","audioKind":"ex"},{"en":"Employers should respect personal boundaries rather than pry into matters unrelated to an employee''s professional responsibilities.","vi":"Người sử dụng lao động nên tôn trọng ranh giới cá nhân thay vì dòm ngó những vấn đề không liên quan đến trách nhiệm nghề nghiệp của nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"pry into someone''s affairs","vi":"tọc mạch vào chuyện của ai"},{"en":"pry open a lid","vi":"cạy nắp"},{"en":"prying eyes","vi":"ánh mắt dòm ngó"}],"wordFamily":["prying (adj.)"],"synonyms":["snoop"],"antonyms":[],"tipVi":"Dùng cấu trúc pry into khi chỉ hành động tọc mạch; khi chỉ hành động cạy/bẩy, tiếng Anh Anh thường dùng prise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discreet', 'en-c1-9', 'discreet', '/dɪˈskriːt/', 'C1', 'thận trọng; kín đáo; không phô trương', 'adj.', 'discreetly (adv.), discretion (n.)', 'Đồng nghĩa: tactful, unobtrusive · Trái nghĩa: indiscreet', 'Đừng nhầm lẫn với discrete (tách biệt); discreet nhấn mạnh sự cẩn trọng và kín đáo.', 'Please be discreet about the surprise party we''re planning.', NULL, 'Xin hãy giữ kín chuyện về bữa tiệc bất ngờ mà chúng ta đang lên kế hoạch nhé.', '{"wordId":"discreet","ukIpa":"/dɪˈskriːt/","usIpa":"/dɪˈskriːt/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Careful not to reveal secrets or cause embarrassment.","vi":"thận trọng; kín đáo"},{"pos":"adj.","en":"Designed or chosen to avoid attracting attention.","vi":"kín đáo; không phô trương"}],"examples":[{"en":"Please be discreet about the surprise party we''re planning.","vi":"Xin hãy giữ kín chuyện về bữa tiệc bất ngờ mà chúng ta đang lên kế hoạch nhé.","audioKind":"ex"},{"en":"Healthcare professionals must be discreet when discussing patients to protect their privacy and maintain public trust.","vi":"Các chuyên gia y tế phải thận trọng khi bàn luận về bệnh nhân để bảo vệ quyền riêng tư của họ và duy trì lòng tin của công chúng.","audioKind":"ex2"}],"collocations":[{"en":"a discreet enquiry","vi":"một cuộc dò hỏi kín đáo"},{"en":"a discreet manner","vi":"thái độ kín đáo"},{"en":"discreet about","vi":"kín tiếng về"},{"en":"a discreet entrance","vi":"lối vào không phô trương"}],"wordFamily":["discreetly (adv.)","discretion (n.)"],"synonyms":["tactful","unobtrusive"],"antonyms":["indiscreet"],"tipVi":"Đừng nhầm lẫn với discrete (tách biệt); discreet nhấn mạnh sự cẩn trọng và kín đáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_9_1', 'en-c1-9', 'Cách dùng “vogue” (n.) — mốt; sự thịnh hành; phong trào', 'in vogue  ·  come into vogue  ·  the vogue for', 'Thường dùng cấu trúc in vogue để chỉ sự thịnh hành; không dùng như một danh từ chỉ vật thể đếm được thông thường.', 'Họ từ (Word Family): voguish (adj.) | Đồng nghĩa: fashion, trend', '[{"hanzi":"Wide trousers are back in vogue this summer.","pinyin":"","meaning":"Quần ống rộng đang mốt trở lại vào mùa hè này."},{"hanzi":"The current vogue for repairing old furniture may help reduce household waste and encourage more sustainable consumption.","pinyin":"","meaning":"Trào lưu sửa chữa đồ nội thất cũ hiện nay có thể giúp giảm rác thải sinh hoạt và khuyến khích tiêu dùng bền vững hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_9_2', 'en-c1-9', 'Cách dùng “pry” (v.) — xọc mạch; tọc mạch; dòm ngó chuyện riêng tư', 'pry into someone''s affairs  ·  pry open a lid  ·  prying eyes', 'Dùng cấu trúc pry into khi chỉ hành động tọc mạch; khi chỉ hành động cạy/bẩy, tiếng Anh Anh thường dùng prise.', 'Họ từ (Word Family): prying (adj.) | Đồng nghĩa: snoop', '[{"hanzi":"Please don''t pry into my sister''s private life.","pinyin":"","meaning":"Xin đừng tọc mạch vào đời tư của em gái tôi."},{"hanzi":"Employers should respect personal boundaries rather than pry into matters unrelated to an employee''s professional responsibilities.","pinyin":"","meaning":"Người sử dụng lao động nên tôn trọng ranh giới cá nhân thay vì dòm ngó những vấn đề không liên quan đến trách nhiệm nghề nghiệp của nhân viên."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_9_3', 'en-c1-9', 'Cách dùng “mediate” (v.) — hòa giải; làm trung gian', 'mediate between two sides  ·  mediate a dispute  ·  mediate a settlement', 'Mediate thiên về việc thúc đẩy đạt được thỏa thuận; arbitrate có thể chỉ việc đưa ra phán quyết trọng tài.', 'Họ từ (Word Family): mediation (n.), mediator (n.) | Đồng nghĩa: arbitrate', '[{"hanzi":"Our neighbour offered to mediate when we argued about parking.","pinyin":"","meaning":"Hàng xóm của chúng tôi đã đề nghị làm trung gian khi chúng tôi tranh cãi về chỗ đậu xe."},{"hanzi":"Independent organisations can mediate between employers and workers to resolve disputes before they disrupt essential public services.","pinyin":"","meaning":"Các tổ chức độc lập có thể làm trung gian giữa người sử dụng lao động và người lao động để giải quyết các tranh chấp trước khi chúng làm gián đoạn các dịch vụ công thiết yếu."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_9_4', 'en-c1-9', 'Cách dùng “flaunt” (v.) — khoe khoang; phô trương', 'flaunt wealth  ·  flaunt success  ·  flaunt possessions', 'flaunt có nghĩa là khoe khoang, trong khi flout có nghĩa là phớt lờ quy tắc, tránh nhầm lẫn hai từ này.', 'Đồng nghĩa: show off', '[{"hanzi":"He flaunted his new watch at dinner last night.","pinyin":"","meaning":"Tối qua anh ấy khoe chiếc đồng hồ mới tại bữa tối."},{"hanzi":"Social media encourages some users to flaunt their wealth, potentially increasing feelings of inadequacy among viewers.","pinyin":"","meaning":"Mạng xã hội khuyến khích một số người dùng khoe khoang sự giàu có, qua đó có thể làm gia tăng cảm giác kém cỏi ở người xem."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_9_1', 'en-c1-9', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_1_1', 'ten_c1_9_1', 'truce', 'After arguing all morning, the neighbours called a truce.', 'After arguing all morning, the neighbours called a truce.', '/truːs/', 'Sau khi cãi nhau suốt buổi sáng, những người hàng xóm đã tạm đình chiến.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_1_2', 'ten_c1_9_1', 'handicap', 'Without a car, the distance became a real handicap.', 'Without a car, the distance became a real handicap.', '/ˈhændikæp/', 'Không có xe ô tô, khoảng cách thực sự đã trở thành một trở ngại lớn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_1_3', 'ten_c1_9_1', 'conformity', 'Our art teacher encourages creativity rather than strict conformity.', 'Our art teacher encourages creativity rather than strict conformity.', '/kənˈfɔːrməti/', 'Giáo viên mỹ thuật của chúng tôi khuyến khích sự sáng tạo hơn là việc rập khuôn theo lề lối nghiêm ngặt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_1_4', 'ten_c1_9_1', 'formality', 'Signing this final document is just a formality.', 'Signing this final document is just a formality.', '/fɔːrˈmæləti/', 'Việc ký kết tài liệu cuối cùng này chỉ mang tính chất thủ tục.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_1_5', 'ten_c1_9_1', 'feud', 'The neighbours ended their feud over the garden fence.', 'The neighbours ended their feud over the garden fence.', '/fjuːd/', 'Những người hàng xóm đã chấm dứt cuộc tranh chấp lâu năm quanh hàng rào khu vườn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_1_6', 'ten_c1_9_1', 'sarcastic', 'His sarcastic comment about my cooking hurt my feelings.', 'His sarcastic comment about my cooking hurt my feelings.', '/sɑːrˈkæstɪk/', 'Lời nhận xét mỉa mai của anh ấy về tài nấu ăn của tôi đã làm tổn thương cảm xúc của tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_1_7', 'ten_c1_9_1', 'normalization', 'The normalization of bus services made commuting easier again.', 'The normalization of bus services made commuting easier again.', '/ˌnɔːrmələˈzeɪʃən/', 'Việc các tuyến xe buýt hoạt động trở lại bình thường giúp cho việc đi lại thuận tiện hơn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_1_8', 'ten_c1_9_1', 'disadvantageous', 'The early start time is disadvantageous for commuters.', 'The early start time is disadvantageous for commuters.', '/ˌdɪsædvænˈteɪdʒəs/', 'Giờ bắt đầu sớm tạo sự bất lợi cho những người đi làm xa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_9_1_1', 'en-c1-9', 'ten_c1_9_1', 'listening', 'listening', 'After arguing all morning, the neighbours called a truce.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những người hàng xóm đã chấm dứt cuộc tranh chấp lâu năm quanh hàng rào khu vườn.","Nữ người thừa kế trẻ tuổi đã biến biệt thự của gia đình thành một bảoตàng.","Quần ống rộng đang mốt trở lại vào mùa hè này.","Sau khi cãi nhau suốt buổi sáng, những người hàng xóm đã tạm đình chiến."]'::jsonb, 3, 'After arguing all morning, the neighbours called a truce. → Sau khi cãi nhau suốt buổi sáng, những người hàng xóm đã tạm đình chiến.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_9_1_2', 'en-c1-9', 'ten_c1_9_1', 'listening', 'listening', 'Without a car, the distance became a real handicap.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy giữ kín chuyện về bữa tiệc bất ngờ mà chúng ta đang lên kế hoạch nhé.","Không có xe ô tô, khoảng cách thực sự đã trở thành một trở ngại lớn.","Cô ấy đã biết tự kiềm chế và để dành chiếc bánh quy cuối cùng cho tôi.","Việc ký kết tài liệu cuối cùng này chỉ mang tính chất thủ tục."]'::jsonb, 1, 'Without a car, the distance became a real handicap. → Không có xe ô tô, khoảng cách thực sự đã trở thành một trở ngại lớn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_9_1_3', 'en-c1-9', 'ten_c1_9_1', 'listening', 'listening', 'Our art teacher encourages creativity rather than strict conformity.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy giữ bức ảnh của người ông quá cố ngay bên cạnh.","Cô ấy đã biết tự kiềm chế và để dành chiếc bánh quy cuối cùng cho tôi.","Giáo viên mỹ thuật của chúng tôi khuyến khích sự sáng tạo hơn là việc rập khuôn theo lề lối nghiêm ngặt.","Các hàng xóm của chúng tôi đã lên tiếng phản đối mạnh mẽ kế hoạch đóng cửa hồ bơi."]'::jsonb, 2, 'Our art teacher encourages creativity rather than strict conformity. → Giáo viên mỹ thuật của chúng tôi khuyến khích sự sáng tạo hơn là việc rập khuôn theo lề lối nghiêm ngặt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_9_2', 'en-c1-9', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_2_1', 'ten_c1_9_2', 'truce', 'A temporary truce can allow aid workers to deliver essential supplies to communities affected by conflict.', 'A temporary truce can allow aid workers to deliver essential supplies to communities affected by conflict.', '/truːs/', 'Một thỏa thuận tạm đình chiến có thể tạo điều kiện cho các nhân viên cứu trợ chuyển các vật tư thiết yếu đến các cộng đồng bị ảnh hưởng bởi xung đột.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_2_2', 'ten_c1_9_2', 'handicap', 'Limited access to reliable internet can be a serious handicap for students in remote communities.', 'Limited access to reliable internet can be a serious handicap for students in remote communities.', '/ˈhændikæp/', 'Việc tiếp cận internet ổn định bị hạn chế có thể là một bất lợi nghiêm trọng đối với học sinh ở các cộng đồng vùng sâu vùng xa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_2_3', 'ten_c1_9_2', 'conformity', 'Strong pressure for conformity in schools may discourage students from questioning established ideas and developing independent judgement.', 'Strong pressure for conformity in schools may discourage students from questioning established ideas and developing independent judgement.', '/kənˈfɔːrməti/', 'Áp lực từ sự tuân thủ mạnh mẽ ở trường học có thể làm nhụt chí học sinh trong việc chất vấn các quan điểm đã có sẵn và phát triển năng lực phán đoán độc lập.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_2_4', 'ten_c1_9_2', 'formality', 'Excessive formality in classroom discussions may discourage students from expressing their opinions openly and confidently.', 'Excessive formality in classroom discussions may discourage students from expressing their opinions openly and confidently.', '/fɔːrˈmæləti/', 'Sự câu nệ hình thức quá mức trong các buổi thảo luận trên lớp có thể khiến học sinh eại bày tỏ quan điểm một cách cởi mở và tự tin.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_2_5', 'ten_c1_9_2', 'feud', 'A long-running feud between community leaders can prevent cooperation on projects that would benefit local residents.', 'A long-running feud between community leaders can prevent cooperation on projects that would benefit local residents.', '/fjuːd/', 'Mối thù kéo dài giữa các nhà lãnh đạo cộng đồng có thể cản trở sự hợp tác trong các dự án mang lại lợi ích cho cư dân địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_9_2_6', 'ten_c1_9_2', 'sarcastic', 'Sarcastic remarks in online discussions can discourage participation and make constructive debate more difficult.', 'Sarcastic remarks in online discussions can discourage participation and make constructive debate more difficult.', '/sɑːrˈkæstɪk/', 'Những lời châm biếm trong các cuộc thảo luận trực tuyến có thể làm nản lòng sự tham gia và khiến cuộc tranh luận mang tính xây dựng trở nên khó khăn hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_9_2_1', 'en-c1-9', 'ten_c1_9_2', 'listening', 'listening', 'A temporary truce can allow aid workers to deliver essential supplies to communities affected by conflict.', NULL, 'Trong câu vừa nghe, từ “truce” mang nghĩa nào sau đây?', '["làm say đắm; làm mê hoặc","sự ngưng chiến; thỏa thuận tạm đình chiến","có thể chịu đựng được","bịa đặt; ngụy tạo"]'::jsonb, 1, '“truce” (/truːs/): sự ngưng chiến; thỏa thuận tạm đình chiến. Câu đầy đủ: A temporary truce can allow aid workers to deliver essential supplies to communities affected by conflict.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_9_2_2', 'en-c1-9', 'ten_c1_9_2', 'listening', 'listening', 'Limited access to reliable internet can be a serious handicap for students in remote communities.', NULL, 'Trong câu vừa nghe, từ “handicap” mang nghĩa nào sau đây?', '["can thiệp; can dự","tối ưu; thuận lợi nhất","điều kiện bất lợi; trở ngại","thật thà; thẳng thắn; bộc trực"]'::jsonb, 2, '“handicap” (/ˈhændikæp/): điều kiện bất lợi; trở ngại. Câu đầy đủ: Limited access to reliable internet can be a serious handicap for students in remote communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
