INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_9_1', 'en-c1-9', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “truce” (/truːs/) có nghĩa là gì?', '["sự ngưng chiến; thỏa thuận tạm đình chiến","sự phụ thuộc; sự tín nhiệm","khoe khoang; phô trương","thủ tục hành chính; nghi thức rườm rà"]'::jsonb, 0, '“truce” (n.): sự ngưng chiến; thỏa thuận tạm đình chiến.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
