INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_1', 'en-c1-9', NULL, 'comprehensive_test', 'listening', 'truce', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phòng chứa thức ăn; tủ đựng thực phẩm","làm không hài lòng; làm thất vọng","đầy thù hận; ác ý","sự ngưng chiến; thỏa thuận tạm đình chiến"]'::jsonb, 3, 'truce (/truːs/) → sự ngưng chiến; thỏa thuận tạm đình chiến', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_2', 'en-c1-9', NULL, 'comprehensive_test', 'listening', 'Without a car, the distance became a real handicap.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đạp xe đi làm đã giúp tôi giảm bớt sự phụ thuộc vào xe buýt.","Không có xe ô tô, khoảng cách thực sự đã trở thành một trở ngại lớn.","Một người hàng xóm nhiệt tình đã tưới cây giúp chúng tôi trong suốt chuyến đi.","Hàng xóm của chúng tôi đã đề nghị làm trung gian khi chúng tôi tranh cãi về chỗ đậu xe."]'::jsonb, 1, 'Without a car, the distance became a real handicap. → Không có xe ô tô, khoảng cách thực sự đã trở thành một trở ngại lớn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_3', 'en-c1-9', NULL, 'comprehensive_test', 'listening', 'conformity', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự tuân thủ; tính bầy đàn; sự làm theo quy chuẩn","cộc lốc; ngắn ngủi và thô lỗ","ở phía sau; phần sau","làm dịu bớt; giảm nhẹ; làm giảm thiểu"]'::jsonb, 0, 'conformity (/kənˈfɔːrməti/) → sự tuân thủ; tính bầy đàn; sự làm theo quy chuẩn', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_4', 'en-c1-9', NULL, 'comprehensive_test', 'listening', 'Signing this final document is just a formality.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một người hàng xóm nhiệt tình đã tưới cây giúp chúng tôi trong suốt chuyến đi.","Hành vi gian lận của anh ta đã mang lại tiếng nhơ cho toàn đội.","Việc ký kết tài liệu cuối cùng này chỉ mang tính chất thủ tục.","Cô ấy đã biết tự kiềm chế và để dành chiếc bánh quy cuối cùng cho tôi."]'::jsonb, 2, 'Signing this final document is just a formality. → Việc ký kết tài liệu cuối cùng này chỉ mang tính chất thủ tục.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_5', 'en-c1-9', NULL, 'comprehensive_test', 'listening', 'feud', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["với mọi người; ở mọi nơi; khắp nơi","mối thù truyền kiếp; cuộc tranh chấp kéo dài, bất hòa lâu năm","sự thu được; sự tiếp thu; quá trình học được","tính nhút nhát; sự thiếu tự tin"]'::jsonb, 1, 'feud (/fjuːd/) → mối thù truyền kiếp; cuộc tranh chấp kéo dài, bất hòa lâu năm; gây hấn lâu dài; có mối thù không đội trời chung', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_6', 'en-c1-9', NULL, 'comprehensive_test', 'listening', 'His sarcastic comment about my cooking hurt my feelings.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Họ đã cố gắng che đậy lỗi lầm thay vì xin lỗi.","Các hàng xóm của chúng tôi đã lên tiếng phản đối mạnh mẽ kế hoạch đóng cửa hồ bơi.","Lời nhận xét mỉa mai của anh ấy về tài nấu ăn của tôi đã làm tổn thương cảm xúc của tôi.","Hành vi gian lận của anh ta đã mang lại tiếng nhơ cho toàn đội."]'::jsonb, 2, 'His sarcastic comment about my cooking hurt my feelings. → Lời nhận xét mỉa mai của anh ấy về tài nấu ăn của tôi đã làm tổn thương cảm xúc của tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_7', 'en-c1-9', NULL, 'comprehensive_test', 'listening', 'normalization', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tay nghề thủ công; kỹ năng chế tác tinh xảo","bệnh mất ngủ; chứng mất ngủ","sự bình thường hóa; sự khôi phục trạng thái bình thường","bóp méo; xuyên tạc"]'::jsonb, 2, 'normalization (/ˌnɔːrmələˈzeɪʃən/) → sự bình thường hóa; sự khôi phục trạng thái bình thường; sự chuẩn hóa; sự quy chuẩn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_8', 'en-c1-9', NULL, 'comprehensive_test', 'listening', 'The early start time is disadvantageous for commuters.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giờ bắt đầu sớm tạo sự bất lợi cho những người đi làm xa.","Một người hàng xóm nhiệt tình đã tưới cây giúp chúng tôi trong suốt chuyến đi.","Họ đã cố gắng che đậy lỗi lầm thay vì xin lỗi.","Việc ký kết tài liệu cuối cùng này chỉ mang tính chất thủ tục."]'::jsonb, 0, 'The early start time is disadvantageous for commuters. → Giờ bắt đầu sớm tạo sự bất lợi cho những người đi làm xa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_9', 'en-c1-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A bitter disagreement continuing for a long time.”?', '["feud","conspiracy","truce","transcend"]'::jsonb, 0, 'feud (/fjuːd/) → mối thù truyền kiếp; cuộc tranh chấp kéo dài, bất hòa lâu năm', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_10', 'en-c1-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “using mocking words, often meaning the opposite, to criticize”?', '["transcend","sarcastic","disadvantageous","vogue"]'::jsonb, 1, 'sarcastic (/sɑːrˈkæstɪk/) → mỉa mai; châm biếm, cay độc', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_11', 'en-c1-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The process of making conditions normal or usual.”?', '["vogue","normalization","tacit","mediate"]'::jsonb, 1, 'normalization (/ˌnɔːrmələˈzeɪʃən/) → sự bình thường hóa; sự khôi phục trạng thái bình thường', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_12', 'en-c1-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Making success harder or putting someone in a worse position.”?', '["dishonour","discreet","disadvantageous","vogue"]'::jsonb, 2, 'disadvantageous (/ˌdɪsædvænˈteɪdʒəs/) → bất lợi; gây khó khăn', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_13', 'en-c1-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To show something proudly to attract attention or admiration.”?', '["flaunt","conspiracy","restraint","formality"]'::jsonb, 0, 'flaunt (/flɔːnt/) → khoe khoang; phô trương', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
