INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_18', 'en-c1-9', NULL, 'comprehensive_test', 'reading', NULL, 'A temporary truce can allow aid workers to deliver essential supplies to communities affected by conflict.', 'Dựa vào câu trên, từ “truce” có nghĩa phù hợp nhất là gì?', '["sự ngưng chiến; thỏa thuận tạm đình chiến","cày cấy, trồng trọt","chiều chuộng; cưng nựng; nuông chiều","thật thà; thẳng thắn; bộc trực"]'::jsonb, 0, 'truce: sự ngưng chiến; thỏa thuận tạm đình chiến. Dịch cả câu: Một thỏa thuận tạm đình chiến có thể tạo điều kiện cho các nhân viên cứu trợ chuyển các vật tư thiết yếu đến các cộng đồng bị ảnh hưởng bởi xung đột.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_19', 'en-c1-9', NULL, 'comprehensive_test', 'reading', NULL, 'Limited access to reliable internet can be a serious handicap for students in remote communities.', 'Dựa vào câu trên, từ “handicap” có nghĩa phù hợp nhất là gì?', '["thuộc văn bản; thuộc về từ ngữ trong văn bản","tượng bán thân","tác phẩm cắt giấy; nghệ thuật cắt giấy","điều kiện bất lợi; trở ngại"]'::jsonb, 3, 'handicap: điều kiện bất lợi; trở ngại; làm cho khó thành công hơn; gây bất lợi; hệ thống điểm chấp trong thể thao. Dịch cả câu: Việc tiếp cận internet ổn định bị hạn chế có thể là một bất lợi nghiêm trọng đối với học sinh ở các cộng đồng vùng sâu vùng xa.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_20', 'en-c1-9', NULL, 'comprehensive_test', 'reading', NULL, 'Strong pressure for conformity in schools may discourage students from questioning established ideas and developing independent judgement.', 'Dựa vào câu trên, từ “conformity” có nghĩa phù hợp nhất là gì?', '["sự khiêu khích; sự chọc tức","sự tuân thủ; tính bầy đàn; sự làm theo quy chuẩn","thịnh hành; phổ biến","thuộc về thời gian; theo thứ tự thời gian"]'::jsonb, 1, 'conformity: sự tuân thủ; tính bầy đàn; sự làm theo quy chuẩn. Dịch cả câu: Áp lực từ sự tuân thủ mạnh mẽ ở trường học có thể làm nhụt chí học sinh trong việc chất vấn các quan điểm đã có sẵn và phát triển năng lực phán đoán độc lập.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_21', 'en-c1-9', NULL, 'comprehensive_test', 'reading', NULL, 'Excessive formality in classroom discussions may discourage students from expressing their opinions openly and confidently.', 'Dựa vào câu trên, từ “formality” có nghĩa phù hợp nhất là gì?', '["than van; tiếc nuối; thương tiếc","cản trở; gây khó khăn","quá mức kỹ tính; khó chiều; kén chọn","thủ tục hành chính; nghi thức rườm rà"]'::jsonb, 3, 'formality: thủ tục hành chính; nghi thức rườm rà; sự câu nệ hình thức; tính trang trọng. Dịch cả câu: Sự câu nệ hình thức quá mức trong các buổi thảo luận trên lớp có thể khiến học sinh eại bày tỏ quan điểm một cách cởi mở và tự tin.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_22', 'en-c1-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vượt qua; vượt ra ngoài giới hạn”', '["philosophical","franchise","counsel","transcend"]'::jsonb, 3, 'vượt qua; vượt ra ngoài giới hạn → transcend (/trænˈsend/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_23', 'en-c1-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “xọc mạch; tọc mạch; dòm ngó chuyện riêng tư”', '["pry","distil","commune","symposium"]'::jsonb, 0, 'xọc mạch; tọc mạch; dòm ngó chuyện riêng tư → pry (/praɪ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_9_24', 'en-c1-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thận trọng; kín đáo”', '["discreet","henceforth","plantation","oblong"]'::jsonb, 0, 'thận trọng; kín đáo → discreet (/dɪˈskriːt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-10', 'en', 'Bài 10: Xã hội & Cộng đồng (5) - CEFR C1', 'CEFR C1', 'C1 · Xã hội', '27 từ vựng Tiếng Anh CEFR C1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5010, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_representation', 'en-c1-10', 'representation', '/ˌreprɪzenˈteɪʃən/', 'C1', 'sự đại diện; quyền đại diện; sự miêu tả; sự thể hiện; cách trình bày', 'n.', 'represent (v.), representative (n.), representative (adj.), representational (adj.)', NULL, 'Từ này vừa có thể chỉ hành động thay mặt người khác lên tiếng, vừa chỉ cách một sự vật được thể hiện qua hình ảnh hoặc chữ viết.', 'Our club now has representation on the town committee.', NULL, 'Câu lạc bộ của chúng tôi giờ đây đã có người đại diện trong ủy ban thị trấn.', '{"wordId":"representation","ukIpa":"/ˌreprɪzenˈteɪʃən/","usIpa":"/ˌreprɪzenˈteɪʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The act of speaking or acting on behalf of others.","vi":"sự đại diện; quyền đại diện"},{"pos":"n.","en":"A picture, description, or model showing someone or something.","vi":"sự miêu tả; sự thể hiện; cách trình bày"}],"examples":[{"en":"Our club now has representation on the town committee.","vi":"Câu lạc bộ của chúng tôi giờ đây đã có người đại diện trong ủy ban thị trấn.","audioKind":"ex"},{"en":"Accurate representation of different communities in school textbooks can help students develop a more inclusive worldview.","vi":"Việc phản ánh chính xác các cộng đồng khác nhau trong sách giáo khoa nhà trường có thể giúp học sinh xây dựng một thế giới quan bao dung hơn.","audioKind":"ex2"}],"collocations":[{"en":"legal representation","vi":"đại diện pháp lý"},{"en":"political representation","vi":"quyền đại diện chính trị"},{"en":"accurate representation","vi":"sự thể hiện chính xác"},{"en":"visual representation","vi":"sự thể hiện bằng hình ảnh"}],"wordFamily":["represent (v.)","representative (n.)","representative (adj.)","representational (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này vừa có thể chỉ hành động thay mặt người khác lên tiếng, vừa chỉ cách một sự vật được thể hiện qua hình ảnh hoặc chữ viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evict', 'en-c1-10', 'evict', '/ɪˈvɪkt/', 'C1', 'trục xuất; đuổi ra khỏi nhà/đất (theo pháp luật)', 'v.', 'eviction (n.)', NULL, 'Thường dùng cấu trúc evict somebody from; đặc biệt dùng trong ngữ cảnh pháp lý khi buộc ai rời khỏi nhà cho thuê.', 'The landlord threatened to evict us over unpaid rent.', NULL, 'Chủ nhà đe dọa sẽ trục xuất chúng tôi vì nợ tiền thuê nhà.', '{"wordId":"evict","ukIpa":"/ɪˈvɪkt/","usIpa":"/ɪˈvɪkt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To legally force someone to leave a property","vi":"trục xuất; đuổi ra khỏi nhà/đất (theo pháp luật)"}],"examples":[{"en":"The landlord threatened to evict us over unpaid rent.","vi":"Chủ nhà đe dọa sẽ trục xuất chúng tôi vì nợ tiền thuê nhà.","audioKind":"ex"},{"en":"Stronger tenant protections could prevent landlords from evicting vulnerable families without adequate notice or legal justification.","vi":"Các biện pháp bảo vệ người thuê nhà vững chắc hơn có thể ngăn chặn việc chủ nhà trục xuất những hộ gia đình dễ bị tổn thương mà không có thông báo trước đầy đủ hoặc không có căn cứ pháp lý.","audioKind":"ex2"}],"collocations":[{"en":"evict a tenant","vi":"trục xuất người thuê nhà"},{"en":"evict someone from a property","vi":"đẩy ai đó ra khỏi chỗ ở"},{"en":"face eviction","vi":"đối mặt với nguy cơ bị trục xuất"}],"wordFamily":["eviction (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc evict somebody from; đặc biệt dùng trong ngữ cảnh pháp lý khi buộc ai rời khỏi nhà cho thuê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nomad', 'en-c1-10', 'nomad', '/ˈnoʊmæd/', 'C1', 'du mục; người lang thang đây đó', 'n.', 'nomadic (adj.)', NULL, 'Nomad thường đóng vai trò danh từ; tính từ của nó là nomadic.', 'The nomad packed his tent before moving his goats uphill.', NULL, 'Người du mục thu dọn lều bạt trước khi lùa đàn dê lên sườn đồi.', '{"wordId":"nomad","ukIpa":"/ˈnəʊmæd/","usIpa":"/ˈnoʊmæd/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Someone who moves between places rather than living permanently somewhere","vi":"du mục; người lang thang đây đó"}],"examples":[{"en":"The nomad packed his tent before moving his goats uphill.","vi":"Người du mục thu dọn lều bạt trước khi lùa đàn dê lên sườn đồi.","audioKind":"ex"},{"en":"For many nomads, access to seasonal grazing land is essential to maintaining their traditional way of life.","vi":"Đối với nhiều người du mục, việc tiếp cận các bãi chăn thả theo mùa là điều cốt yếu để duy trì lối sống truyền thống của họ.","audioKind":"ex2"}],"collocations":[{"en":"digital nomad","vi":"du mạn kỹ thuật số"},{"en":"desert nomad","vi":"du mục sa mạc"},{"en":"a nomad''s life","vi":"cuộc đời du mục"}],"wordFamily":["nomadic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nomad thường đóng vai trò danh từ; tính từ của nó là nomadic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_degenerate', 'en-c1-10', 'degenerate', '/dɪˈdʒenəreɪt/', 'C1', 'trở nên xấu đi; thoái hóa; suy đồi; suy đồi đạo đức; bị thoái hóa', 'v.', 'degeneration (n.), degenerative (adj.)', 'Đồng nghĩa: deteriorate, decline · Trái nghĩa: improve', 'Động từ phát âm đuôi /reɪt/, tính từ phát âm đuôi /rət/; thường đi với giới từ into.', 'Their friendly discussion soon degenerated into a noisy argument.', NULL, 'Cuộc thảo luận thân thiện của họ chẳng mấy chốc đã biến thành một cuộc cãi vã ồn ào.', '{"wordId":"degenerate","ukIpa":"/dɪˈdʒenəreɪt/","usIpa":"/dɪˈdʒenəreɪt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"Become worse in quality, condition, or behaviour.","vi":"trở nên xấu đi; thoái hóa; suy đồi"},{"pos":"adj.","en":"Having declined morally or lost normal structure or function.","vi":"suy đồi đạo đức; bị thoái hóa"}],"examples":[{"en":"Their friendly discussion soon degenerated into a noisy argument.","vi":"Cuộc thảo luận thân thiện của họ chẳng mấy chốc đã biến thành một cuộc cãi vã ồn ào.","audioKind":"ex"},{"en":"Without regular maintenance, public facilities can degenerate rapidly, reducing residents'' quality of life and increasing future repair costs.","vi":"Nếu thiếu bảo trì định kỳ, các công trình công cộng có thể nhanh chóng xuống cấp, làm giảm chất lượng cuộc sống của cư dân và tăng chi phí sửa chữa trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"degenerate into","vi":"rơi vào tình trạng; thoái hóa thành"},{"en":"degenerate rapidly","vi":"xuống cấp nhanh chóng"}],"wordFamily":["degeneration (n.)","degenerative (adj.)"],"synonyms":["deteriorate","decline"],"antonyms":["improve"],"tipVi":"Động từ phát âm đuôi /reɪt/, tính từ phát âm đuôi /rət/; thường đi với giới từ into.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marxist', 'en-c1-10', 'Marxist', '/ˈmɑːrksɪst/', 'C1', 'thuộc chủ nghĩa Mác; người theo chủ nghĩa Mác', 'adj.', 'Marxism (n.)', NULL, 'Chữ cái đầu tiên luôn được viết hoa; từ này có thể đóng vai trò là tính từ hoặc danh từ đếm được.', 'Our reading group discussed Marxist ideas at the library.', NULL, 'Nhóm đọc sách của chúng tôi đã thảo luận về các tư tưởng của chủ nghĩa Mác tại thư viện.', '{"wordId":"marxist","ukIpa":"/ˈmɑːksɪst/","usIpa":"/ˈmɑːrksɪst/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"relating to Marx''s theories about class, economics, and society","vi":"thuộc chủ nghĩa Mác"},{"pos":"n.","en":"a person who supports Marx''s social and economic theories","vi":"người theo chủ nghĩa Mác"}],"examples":[{"en":"Our reading group discussed Marxist ideas at the library.","vi":"Nhóm đọc sách của chúng tôi đã thảo luận về các tư tưởng của chủ nghĩa Mác tại thư viện.","audioKind":"ex"},{"en":"A Marxist analysis of housing examines how property ownership and class relations influence access to affordable homes.","vi":"Một bài phân tích theo quan điểm Mác-xít về nhà ở xem xét cách quyền sở hữu tài sản và quan hệ giai cấp chi phối khả năng tiếp cận nhà ở giá rẻ.","audioKind":"ex2"}],"collocations":[{"en":"Marxist theory","vi":"lý luận mác-xít"},{"en":"Marxist analysis","vi":"phân tích theo quan điểm mác-xít"},{"en":"a Marxist scholar","vi":"học giả theo chủ nghĩa Mác"}],"wordFamily":["Marxism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu tiên luôn được viết hoa; từ này có thể đóng vai trò là tính từ hoặc danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_renowned', 'en-c1-10', 'renowned', '/rɪˈnaʊnd/', 'C1', 'nổi tiếng và được ngưỡng mộ rộng rãi nhờ một phẩm chất hoặc thành tựu cụ thể', 'adj.', 'renown (n.)', 'Đồng nghĩa: famous, celebrated, distinguished · Trái nghĩa: unknown, obscure', 'Cấu trúc renowned for đi kèm với thành tựu hoặc đặc điểm; renowned as đi kèm với chức danh hoặc vai trò.', 'This small bakery is renowned for its fresh bread.', NULL, 'Tiệm bánh nhỏ này nổi tiếng với những chiếc bánh mì tươi ngon.', '{"wordId":"renowned","ukIpa":"/rɪˈnaʊnd/","usIpa":"/rɪˈnaʊnd/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Widely known and admired for a particular quality or achievement.","vi":"nổi tiếng và được ngưỡng mộ rộng rãi nhờ một phẩm chất hoặc thành tựu cụ thể"}],"examples":[{"en":"This small bakery is renowned for its fresh bread.","vi":"Tiệm bánh nhỏ này nổi tiếng với những chiếc bánh mì tươi ngon.","audioKind":"ex"},{"en":"Universities renowned for scientific research often attract international students and encourage cooperation across national borders.","vi":"Các trường đại học nổi tiếng về nghiên cứu khoa học thường thu hút sinh viên quốc tế và thúc đẩy hợp tác vượt qua biên giới các quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"renowned for","vi":"nổi tiếng vì"},{"en":"internationally renowned","vi":"nổi tiếng quốc tế"},{"en":"a renowned expert","vi":"chuyên gia lừng danh"}],"wordFamily":["renown (n.)"],"synonyms":["famous","celebrated","distinguished"],"antonyms":["unknown","obscure"],"tipVi":"Cấu trúc renowned for đi kèm với thành tựu hoặc đặc điểm; renowned as đi kèm với chức danh hoặc vai trò.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_condemn', 'en-c1-10', 'condemn', '/kənˈdem/', 'C1', 'lên án; chỉ trích mạnh mẽ ai đó hoặc cái gì; tuyên án phạt nặng một cách chính thức; tuyên bố chính thức một tòa nhà không an toàn để sử dụng', 'v.', 'condemnation (n.), condemned (adj.)', 'Đồng nghĩa: denounce · Trái nghĩa: praise, approve', 'Phụ âm cuối n không phát âm; tránh nhầm lẫn với từ condense có nghĩa là "ngưng tụ".', 'Our neighbours condemned the dumping of rubbish beside the river.', NULL, 'Những người hàng xóm của chúng tôi đã lên án hành vi xả rác bừa bãi bên bờ sông.', '{"wordId":"condemn","ukIpa":"/kənˈdem/","usIpa":"/kənˈdem/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To express strong disapproval of someone or something.","vi":"lên án; chỉ trích mạnh mẽ ai đó hoặc cái gì"},{"pos":"v.","en":"To officially give someone a severe punishment.","vi":"tuyên án phạt nặng một cách chính thức"},{"pos":"v.","en":"To officially declare a building unsafe to use.","vi":"tuyên bố chính thức một tòa nhà không an toàn để sử dụng"}],"examples":[{"en":"Our neighbours condemned the dumping of rubbish beside the river.","vi":"Những người hàng xóm của chúng tôi đã lên án hành vi xả rác bừa bãi bên bờ sông.","audioKind":"ex"},{"en":"Environmental organisations condemn illegal logging because it destroys wildlife habitats and threatens the livelihoods of local communities.","vi":"Các tổ chức bảo vệ môi trường lên án nạn chặt phá rừng trái phép vì nó phá hủy môi trường sống của động vật hoang dã và đe dọa sinh kế của người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"strongly condemn","vi":"kịch liệt lên án"},{"en":"condemn someone to prison","vi":"tuyên án phạt tù ai đó"},{"en":"condemn a building","vi":"tuyên bố tòa nhà không đủ điều kiện sử dụng"}],"wordFamily":["condemnation (n.)","condemned (adj.)"],"synonyms":["denounce"],"antonyms":["praise","approve"],"tipVi":"Phụ âm cuối n không phát âm; tránh nhầm lẫn với từ condense có nghĩa là \"ngưng tụ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_firearm', 'en-c1-10', 'firearm', '/ˈfaɪrɑːrm/', 'C1', 'súng cầm tay; vũ khí hỏa khí', 'n.', NULL, 'Đồng nghĩa: gun', 'Danh từ đếm được, thường dùng ở dạng số nhiều firearms, mang sắc thái trang trọng.', 'The antique firearm was displayed behind thick museum glass.', NULL, 'Khẩu súng cổ được trưng bày đằng sau lớp kính dày của viện bảo tàng.', '{"wordId":"firearm","ukIpa":"/ˈfaɪərɑːm/","usIpa":"/ˈfaɪrɑːrm/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A weapon that fires bullets using an explosive charge.","vi":"súng cầm tay; vũ khí hỏa khí"}],"examples":[{"en":"The antique firearm was displayed behind thick museum glass.","vi":"Khẩu súng cổ được trưng bày đằng sau lớp kính dày của viện bảo tàng.","audioKind":"ex"},{"en":"Strict firearm storage regulations can help prevent accidents and improve safety in homes and communities.","vi":"Các quy định nghiêm ngặt về việc bảo quản súng đạn có thể giúp ngăn ngừa tai nạn và nâng cao sự an toàn trong các gia đình cũng như cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"firearm safety","vi":"an toàn súng đạn"},{"en":"firearm ownership","vi":"sở hữu súng"},{"en":"firearm regulations","vi":"quy định quản lý súng"}],"wordFamily":[],"synonyms":["gun"],"antonyms":[],"tipVi":"Danh từ đếm được, thường dùng ở dạng số nhiều firearms, mang sắc thái trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suppress', 'en-c1-10', 'suppress', '/səˈpres/', 'C1', 'kìm nén; nén; ngăn chặn; trấn áp; dập tắt; đàn áp; che giấu; ém nhẹm; phong tỏa thông tin', 'v.', 'suppression (n.), suppressant (n.), suppressive (adj.)', 'Đồng nghĩa: restrain, stifle · Trái nghĩa: express, reveal', 'Là ngoại động từ, có thể đi trực tiếp với cảm xúc, phản ứng, hoạt động hoặc thông tin.', 'I tried to suppress a sneeze during the concert.', NULL, 'Tôi đã cố kìm nén một cái hắt hơi trong suốt buổi hòa nhạc.', '{"wordId":"suppress","ukIpa":"/səˈpres/","usIpa":"/səˈpres/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To prevent a feeling or physical reaction from being expressed.","vi":"kìm nén; nén; ngăn chặn"},{"pos":"v.","en":"To stop an activity or opposition, often using force.","vi":"trấn áp; dập tắt; đàn áp"},{"pos":"v.","en":"To prevent information from becoming known or being published.","vi":"che giấu; ém nhẹm; phong tỏa thông tin"}],"examples":[{"en":"I tried to suppress a sneeze during the concert.","vi":"Tôi đã cố kìm nén một cái hắt hơi trong suốt buổi hòa nhạc.","audioKind":"ex"},{"en":"Attempts to suppress scientific findings can undermine public trust and delay effective responses to environmental problems.","vi":"Những nỗ lực che giấu các phát hiện khoa học có thể làm suy giảm lòng tin của công chúng và làm chậm trễ các biện pháp ứng phó hiệu quả đối với các vấn đề môi trường.","audioKind":"ex2"}],"collocations":[{"en":"suppress a smile","vi":"nén nụ cười"},{"en":"suppress information","vi":"che giấu thông tin"},{"en":"suppress opposition","vi":"trấn áp phe đối lập"},{"en":"suppress appetite","vi":"kìm hãm sự thèm ăn"}],"wordFamily":["suppression (n.)","suppressant (n.)","suppressive (adj.)"],"synonyms":["restrain","stifle"],"antonyms":["express","reveal"],"tipVi":"Là ngoại động từ, có thể đi trực tiếp với cảm xúc, phản ứng, hoạt động hoặc thông tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_liberate', 'en-c1-10', 'liberate', '/ˈlɪbəreɪt/', 'C1', 'giải phóng; trả tự do cho con người hoặc vùng đất khỏi sự kiểm soát hoặc giam cầm; giải thoát ai đó khỏi những sự hạn chế kìm hãm cuộc sống của họ', 'v.', 'liberation (n.), liberator (n.), liberating (adj.), liberated (adj.)', 'Đồng nghĩa: free, release · Trái nghĩa: imprison, enslave', 'Là ngoại động từ; cấu trúc liberate A from B có nghĩa là làm cho A thoát khỏi B.', 'The rescued prisoners cheered when soldiers liberated the camp.', NULL, 'Những tù nhân được giải cứu đã reo hò khi binh lính giải phóng trại tập trung.', '{"wordId":"liberate","ukIpa":"/ˈlɪbəreɪt/","usIpa":"/ˈlɪbəreɪt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To free people or places from control or imprisonment.","vi":"giải phóng; trả tự do cho con người hoặc vùng đất khỏi sự kiểm soát hoặc giam cầm"},{"pos":"v.","en":"To release someone from restrictions that limit their life.","vi":"giải thoát ai đó khỏi những sự hạn chế kìm hãm cuộc sống của họ"}],"examples":[{"en":"The rescued prisoners cheered when soldiers liberated the camp.","vi":"Những tù nhân được giải cứu đã reo hò khi binh lính giải phóng trại tập trung.","audioKind":"ex"},{"en":"Accessible public transport can liberate older people from dependence on relatives and enable greater participation in community life.","vi":"Hệ thống giao thông công cộng dễ tiếp cận có thể giúp người cao tuổi thoát khỏi sự phụ thuộc vào người thân và tham gia nhiều hơn vào đời sống cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"liberate a country","vi":"giải phóng một quốc gia"},{"en":"liberate someone from","vi":"giải thoát ai đó khỏi"},{"en":"liberating experience","vi":"trải nghiệm mang lại sự tự do"}],"wordFamily":["liberation (n.)","liberator (n.)","liberating (adj.)","liberated (adj.)"],"synonyms":["free","release"],"antonyms":["imprison","enslave"],"tipVi":"Là ngoại động từ; cấu trúc liberate A from B có nghĩa là làm cho A thoát khỏi B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heroic', 'en-c1-10', 'heroic', '/hɪˈroʊɪk/', 'C1', 'anh dũng; mang tính anh hùng (thể hiện sự dũng cảm lớn, đặc biệt khi giúp đỡ người khác); hết sức nỗ lực; kiên quyết phi thường (cần nỗ lực hoặc quyết tâm cực lớn)', 'adj.', 'hero (n.), heroism (n.), heroically (adv.)', 'Đồng nghĩa: brave, courageous · Trái nghĩa: cowardly', 'heroic effort nhấn mạnh việc bỏ ra nỗ lực cực lớn, không nhất thiết phải liên quan đến nguy hiểm.', 'The firefighter made a heroic rescue from the flooded house.', NULL, 'Người lính cứu hỏa đã thực hiện một cuộc giải cứu anh dũng khỏi ngôi nhà bị ngập lụt.', '{"wordId":"heroic","ukIpa":"/hɪˈrəʊɪk/","usIpa":"/hɪˈroʊɪk/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Showing great courage, especially when helping others","vi":"anh dũng; mang tính anh hùng (thể hiện sự dũng cảm lớn, đặc biệt khi giúp đỡ người khác)"},{"pos":"adj.","en":"Involving extraordinary effort or determination","vi":"hết sức nỗ lực; kiên quyết phi thường (cần nỗ lực hoặc quyết tâm cực lớn)"}],"examples":[{"en":"The firefighter made a heroic rescue from the flooded house.","vi":"Người lính cứu hỏa đã thực hiện một cuộc giải cứu anh dũng khỏi ngôi nhà bị ngập lụt.","audioKind":"ex"},{"en":"Although heroic individuals deserve recognition, effective disaster management depends on well-trained teams and reliable infrastructure.","vi":"Mặc dù những cá nhân anh dũng rất đáng được ghi nhận, nhưng công tác quản lý thảm họa hiệu quả lại phụ thuộc vào các đội ngũ được đào tạo bài bản và cơ sở hạ tầng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"heroic act","vi":"hành động anh dũng"},{"en":"heroic rescue","vi":"cuộc giải cứu anh dũng"},{"en":"heroic effort","vi":"nỗ lực phi thường"}],"wordFamily":["hero (n.)","heroism (n.)","heroically (adv.)"],"synonyms":["brave","courageous"],"antonyms":["cowardly"],"tipVi":"heroic effort nhấn mạnh việc bỏ ra nỗ lực cực lớn, không nhất thiết phải liên quan đến nguy hiểm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sinful', 'en-c1-10', 'sinful', '/ˈsɪnfəl/', 'C1', 'có tội; trái đạo đức; phạm giới', 'adj.', 'sin (n.), sin (v.), sinner (n.), sinfully (adv.)', 'Đồng nghĩa: immoral, wicked · Trái nghĩa: virtuous', 'Thường mang sắc thái tôn giáo; từ ''illegal'' được dùng cho hành vi vi phạm pháp luật nói chung.', 'My grandfather believed that lying was a sinful act.', NULL, 'Ông tôi tin rằng nói dối là một hành vi có tội.', '{"wordId":"sinful","ukIpa":"/ˈsɪnfəl/","usIpa":"/ˈsɪnfəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Morally wrong, especially according to religious beliefs","vi":"có tội; trái đạo đức; phạm giới"}],"examples":[{"en":"My grandfather believed that lying was a sinful act.","vi":"Ông tôi tin rằng nói dối là một hành vi có tội.","audioKind":"ex"},{"en":"Ideas about sinful behaviour vary across religious traditions and may influence attitudes towards personal responsibility.","vi":"Các quan niệm về hành vi tội lỗi khác nhau giữa các truyền thống tôn giáo và có thể ảnh hưởng đến thái độ đối với trách nhiệm cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"sinful behaviour","vi":"hành vi tội lỗi"},{"en":"sinful act","vi":"hành động trái đạo đức"},{"en":"sinful thoughts","vi":"suy nghĩ tội lỗi"}],"wordFamily":["sin (n.)","sin (v.)","sinner (n.)","sinfully (adv.)"],"synonyms":["immoral","wicked"],"antonyms":["virtuous"],"tipVi":"Thường mang sắc thái tôn giáo; từ ''illegal'' được dùng cho hành vi vi phạm pháp luật nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discretion', 'en-c1-10', 'discretion', '/dɪˈskreʃən/', 'C1', 'sự thận trọng; sự cẩn trọng; quyền tự quyết; quyền tùy nghi', 'n.', 'discreet (adj.), discreetly (adv.), discretionary (adj.)', 'Đồng nghĩa: prudence, tact · Trái nghĩa: indiscretion', 'Cụm từ ''at someone''s discretion'' có nghĩa là ''do ai đó tự quyết định tùy theo tình hình''.', 'Please use discretion when discussing her private life.', NULL, 'Xin hãy cẩn trọng khi thảo luận về đời tư của cô ấy.', '{"wordId":"discretion","ukIpa":"/dɪˈskreʃən/","usIpa":"/dɪˈskreʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"care in speaking or acting to avoid embarrassment or harm","vi":"sự thận trọng; sự cẩn trọng"},{"pos":"n.","en":"the freedom to decide what should be done","vi":"quyền tự quyết; quyền tùy nghi"}],"examples":[{"en":"Please use discretion when discussing her private life.","vi":"Xin hãy cẩn trọng khi thảo luận về đời tư của cô ấy.","audioKind":"ex"},{"en":"Teachers need some discretion to adapt classroom activities to the needs of individual learners.","vi":"Giáo viên cần có một số quyền tự quyết nhất định để điều chỉnh các hoạt động trong lớp phù hợp với nhu cầu của từng học sinh.","audioKind":"ex2"}],"collocations":[{"en":"exercise discretion","vi":"hành xử thận trọng"},{"en":"at your discretion","vi":"tùy bạn định đoạt"},{"en":"professional discretion","vi":"sự thận trọng trong nghề nghiệp"}],"wordFamily":["discreet (adj.)","discreetly (adv.)","discretionary (adj.)"],"synonyms":["prudence","tact"],"antonyms":["indiscretion"],"tipVi":"Cụm từ ''at someone''s discretion'' có nghĩa là ''do ai đó tự quyết định tùy theo tình hình''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_undermine', 'en-c1-10', 'undermine', '/ˌʌndɚˈmaɪn/', 'C1', 'làm suy yếu dần; hủy hoại (lòng tin, quyền lực, hiệu quả); khoét chân móng; làm xói mòn phần dưới', 'v.', NULL, 'Đồng nghĩa: weaken, erode · Trái nghĩa: strengthen, reinforce', 'Thường đi kèm với các từ như confidence, trust, nhấn mạnh tiến trình làm suy yếu ngầm hoặc từ từ.', 'Constant criticism can undermine your confidence in the kitchen.', NULL, 'Những lời chỉ trích liên tục có thể làm suy giảm sự tự tin của bạn khi vào bếp.', '{"wordId":"undermine","ukIpa":"/ˌʌndəˈmaɪn/","usIpa":"/ˌʌndɚˈmaɪn/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To gradually weaken someone''s confidence, authority, or something''s effectiveness","vi":"làm suy yếu dần; hủy hoại (lòng tin, quyền lực, hiệu quả)"},{"pos":"v.","en":"To weaken a structure by removing material beneath it","vi":"khoét chân móng; làm xói mòn phần dưới"}],"examples":[{"en":"Constant criticism can undermine your confidence in the kitchen.","vi":"Những lời chỉ trích liên tục có thể làm suy giảm sự tự tin của bạn khi vào bếp.","audioKind":"ex"},{"en":"A lack of transparency can undermine public trust in institutions and reduce support for important policy changes.","vi":"Sự thiếu minh bạch có thể làm xói mòn lòng tin của công chúng vào các cơ quan và làm giảm sự ủng hộ đối với các thay đổi chính sách quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"undermine confidence","vi":"làm suy yếu sự tự tin"},{"en":"undermine authority","vi":"làm suy giảm uy quyền"},{"en":"undermine public trust","vi":"làm xói mòn lòng tin của công chúng"},{"en":"undermine efforts","vi":"làm tổn hại nỗ lực"}],"wordFamily":[],"synonyms":["weaken","erode"],"antonyms":["strengthen","reinforce"],"tipVi":"Thường đi kèm với các từ như confidence, trust, nhấn mạnh tiến trình làm suy yếu ngầm hoặc từ từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_courteous', 'en-c1-10', 'courteous', '/ˈkɝːtiəs/', 'C1', 'lịch sự; nhã nhặn; có phép tắc', 'adj.', 'courtesy (n.), courteously (adv.), discourteous (adj.)', 'Đồng nghĩa: polite, respectful, well-mannered · Trái nghĩa: rude, discourteous', 'Mang sắc thái trang trọng hơn polite; khi nói lịch sự với ai đó, ta dùng giới từ to.', 'The courteous driver waited while I found my ticket.', NULL, 'Người tài xế lịch sự đã kiên nhẫn đợi tôi tìm vé xe.', '{"wordId":"courteous","ukIpa":"/ˈkɜːtiəs/","usIpa":"/ˈkɝːtiəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Polite and respectful towards other people.","vi":"lịch sự; nhã nhặn; có phép tắc"}],"examples":[{"en":"The courteous driver waited while I found my ticket.","vi":"Người tài xế lịch sự đã kiên nhẫn đợi tôi tìm vé xe.","audioKind":"ex"},{"en":"Courteous communication between healthcare staff and patients can improve trust and make medical appointments less stressful.","vi":"Giao tiếp lịch sự giữa nhân viên y tế và bệnh nhân có thể cải thiện lòng tin và làm cho các buổi hẹn khám bệnh bớt căng thẳng hơn.","audioKind":"ex2"}],"collocations":[{"en":"courteous service","vi":"dịch vụ lịch sự chu đáo"},{"en":"courteous manner","vi":"thái độ nhã nhặn"},{"en":"courteous to customers","vi":"lịch sự với khách hàng"}],"wordFamily":["courtesy (n.)","courteously (adv.)","discourteous (adj.)"],"synonyms":["polite","respectful","well-mannered"],"antonyms":["rude","discourteous"],"tipVi":"Mang sắc thái trang trọng hơn polite; khi nói lịch sự với ai đó, ta dùng giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_defraud', 'en-c1-10', 'defraud', '/dɪˈfrɔːd/', 'C1', 'lừa đảo; chiếm đoạt tài sản', 'v.', 'fraud (n.), fraudulent (adj.), fraudulently (adv.), defrauder (n.)', 'Đồng nghĩa: swindle, cheat', 'Thường dùng cấu trúc defraud sb of sth, nghĩa là lừa gạt lấy đi tài sản của ai.', 'The caller tried to defraud her of her savings.', NULL, 'Kẻ gọi điện đã cố gắng lừa lấy tiền tiết kiệm của bà ấy.', '{"wordId":"defraud","ukIpa":"/dɪˈfrɔːd/","usIpa":"/dɪˈfrɔːd/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to obtain someone''s money or property through dishonest actions","vi":"lừa đảo; chiếm đoạt tài sản"}],"examples":[{"en":"The caller tried to defraud her of her savings.","vi":"Kẻ gọi điện đã cố gắng lừa lấy tiền tiết kiệm của bà ấy.","audioKind":"ex"},{"en":"Stronger consumer protection laws can prevent dishonest businesses from attempting to defraud vulnerable customers.","vi":"Các đạo luật bảo vệ người tiêu dùng chặt chẽ hơn có thể ngăn chặn các doanh nghiệp gian lận mưu đồ lừa gạt những khách hàng dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"defraud someone of money","vi":"lừa tiền của ai"},{"en":"defraud investors","vi":"lừa đảo nhà đầu tư"},{"en":"conspiracy to defraud","vi":"âm mưu lừa đảo"}],"wordFamily":["fraud (n.)","fraudulent (adj.)","fraudulently (adv.)","defrauder (n.)"],"synonyms":["swindle","cheat"],"antonyms":[],"tipVi":"Thường dùng cấu trúc defraud sb of sth, nghĩa là lừa gạt lấy đi tài sản của ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_affirm', 'en-c1-10', 'affirm', '/əˈfɝːm/', 'C1', 'khẳng định; quả quyết', 'v.', 'affirmation (n.), affirmative (adj.), reaffirm (v.)', 'Đồng nghĩa: assert, declare · Trái nghĩa: deny', 'Từ affirm có sắc thái trang trọng, nhấn mạnh sự khẳng định rõ ràng; có thể đi kèm với mệnh đề that.', 'Both parents affirmed their support for her career choice.', NULL, 'Cả hai bậc phụ huynh đều khẳng định sự ủng hộ của họ đối với lựa chọn nghề nghiệp của cô ấy.', '{"wordId":"affirm","ukIpa":"/əˈfɜːm/","usIpa":"/əˈfɝːm/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To state firmly that something is true or supported.","vi":"khẳng định; quả quyết"}],"examples":[{"en":"Both parents affirmed their support for her career choice.","vi":"Cả hai bậc phụ huynh đều khẳng định sự ủng hộ của họ đối với lựa chọn nghề nghiệp của cô ấy.","audioKind":"ex"},{"en":"Schools should affirm the value of cultural diversity by ensuring that teaching materials reflect different backgrounds and experiences.","vi":"Các trường học nên khẳng định giá trị của sự đa dạng văn hóa bằng cách đảm bảo rằng tài liệu giảng dạy phản ánh các hoàn cảnh và trải nghiệm khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"affirm a commitment","vi":"reaffirm a commitment"},{"en":"affirm support for","vi":"khẳng định sự ủng hộ"},{"en":"affirm that","vi":"khẳng định rằng"},{"en":"affirm the value of","vi":"khẳng định giá trị của"}],"wordFamily":["affirmation (n.)","affirmative (adj.)","reaffirm (v.)"],"synonyms":["assert","declare"],"antonyms":["deny"],"tipVi":"Từ affirm có sắc thái trang trọng, nhấn mạnh sự khẳng định rõ ràng; có thể đi kèm với mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manipulate', 'en-c1-10', 'manipulate', '/məˈnɪpjəleɪt/', 'C1', 'thao túng; lôi kéo trục lợi; vận hành khéo léo; xử lý khéo léo', 'v.', 'manipulation (n.), manipulative (adj.), manipulator (n.)', 'Đồng nghĩa: control, influence', 'Cấu trúc thao túng ai đó làm việc gì dùng manipulate sb into doing.', 'She tried to manipulate her brother into doing the dishes.', NULL, 'Cô ấy đã cố gắng thao túng anh trai để anh ấy phải rửa bát.', '{"wordId":"manipulate","ukIpa":"/məˈnɪpjʊleɪt/","usIpa":"/məˈnɪpjəleɪt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To control someone or something unfairly for your own benefit.","vi":"thao túng; lôi kéo trục lợi"},{"pos":"v.","en":"To handle or move something with skill.","vi":"vận hành khéo léo; xử lý khéo léo"}],"examples":[{"en":"She tried to manipulate her brother into doing the dishes.","vi":"Cô ấy đã cố gắng thao túng anh trai để anh ấy phải rửa bát.","audioKind":"ex"},{"en":"Online platforms can manipulate consumer choices by selectively displaying products and controlling access to information.","vi":"Các nền tảng trực tuyến có thể thao túng lựa chọn của người tiêu dùng bằng cách hiển thị có chọn lọc các sản phẩm và kiểm soát quyền tiếp cận thông tin.","audioKind":"ex2"}],"collocations":[{"en":"manipulate data","vi":"thao túng dữ liệu"},{"en":"manipulate public opinion","vi":"thao túng dư luận"},{"en":"manipulate someone into doing something","vi":"thao túng ai đó làm việc gì"}],"wordFamily":["manipulation (n.)","manipulative (adj.)","manipulator (n.)"],"synonyms":["control","influence"],"antonyms":[],"tipVi":"Cấu trúc thao túng ai đó làm việc gì dùng manipulate sb into doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_provision', 'en-c1-10', 'provision', '/prəˈvɪʒən/', 'C1', 'sự cung cấp; sự cấp phát; điều khoản; quy định; sự chuẩn bị; biện pháp dự phòng', 'n.', 'provide (v.), provider (n.)', NULL, 'Nghĩa "sự cung cấp" là không đếm được; nghĩa "điều khoản" là đếm được; provisions có thể chỉ lương thực.', 'The campsite fee includes the provision of clean water.', NULL, 'Phí cắm trại đã bao gồm việc cung cấp nước sạch.', '{"wordId":"provision","ukIpa":"/prəˈvɪʒən/","usIpa":"/prəˈvɪʒən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The act of supplying something needed.","vi":"sự cung cấp; sự cấp phát"},{"pos":"n.","en":"A condition or requirement in a law or agreement.","vi":"điều khoản; quy định"},{"pos":"n.","en":"Arrangements made to deal with future needs or events.","vi":"sự chuẩn bị; biện pháp dự phòng"}],"examples":[{"en":"The campsite fee includes the provision of clean water.","vi":"Phí cắm trại đã bao gồm việc cung cấp nước sạch.","audioKind":"ex"},{"en":"Improving the provision of affordable childcare can help more parents return to work and increase household income.","vi":"Việc cải thiện cung cấp dịch vụ chăm sóc trẻ em với chi phí phải chăng có thể giúp nhiều bậc phụ huynh quay trở lại làm việc và tăng thu nhập hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"provision of services","vi":"cung cấp dịch vụ"},{"en":"make provision for","vi":"chuẩn bị cho"},{"en":"a legal provision","vi":"điều khoản pháp lý"},{"en":"healthcare provision","vi":"cung cấp dịch vụ chăm sóc sức khỏe"}],"wordFamily":["provide (v.)","provider (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa \"sự cung cấp\" là không đếm được; nghĩa \"điều khoản\" là đếm được; provisions có thể chỉ lương thực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chant', 'en-c1-10', 'chant', '/tʃænt/', 'C1', 'khẩu hiệu hô vang; tiếng hô nhịp nhàng; hô vang; tụng niệm nhịp nhàng; bài thánh ca; khúc tụng kinh', 'n.', NULL, NULL, 'Không chỉ giới hạn ở thánh ca, mà còn chỉ đám đông hô khẩu hiệu có nhịp điệu lặp đi lặp lại.', 'The crowd repeated a chant as the runners approached.', NULL, 'Đám đông đồng thanh hô vang một khẩu hiệu khi các vận động viên chạy đến gần.', '{"wordId":"chant","ukIpa":"/tʃɑːnt/","usIpa":"/tʃænt/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"words or sounds repeated rhythmically, often by a group","vi":"khẩu hiệu hô vang; tiếng hô nhịp nhàng"},{"pos":"v.","en":"to repeat words rhythmically or sing on a few notes","vi":"hô vang; tụng niệm nhịp nhàng"},{"pos":"n.","en":"a religious song using a small range of notes","vi":"bài thánh ca; khúc tụng kinh"}],"examples":[{"en":"The crowd repeated a chant as the runners approached.","vi":"Đám đông đồng thanh hô vang một khẩu hiệu khi các vận động viên chạy đến gần.","audioKind":"ex"},{"en":"Supporters often chant together during sporting events, creating a sense of shared identity and belonging.","vi":"Những người ủng hộ thường hô vang khẩu hiệu cùng nhau trong các sự kiện thể thao, tạo ra ý thức chung về bản sắc và sự thuộc về.","audioKind":"ex2"}],"collocations":[{"en":"chant slogans","vi":"hô vang khẩu hiệu"},{"en":"a rhythmic chant","vi":"tiếng hô có nhịp điệu"},{"en":"a religious chant","vi":"bài thánh ca tôn giáo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Không chỉ giới hạn ở thánh ca, mà còn chỉ đám đông hô khẩu hiệu có nhịp điệu lặp đi lặp lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cosmopolitan', 'en-c1-10', 'cosmopolitan', '/ˌkɑːzməˈpɑːlɪtən/', 'C1', 'mang tính quốc tế, giao thoa văn hóa từ nhiều quốc gia khác nhau; hiểu biết rộng, quen thuộc và thoải mái với nhiều nền văn hóa khác nhau trên thế giới', 'adj.', 'cosmopolitanism (n.)', 'Đồng nghĩa: international, multicultural', 'Thường miêu tả thành phố hoặc con người, nhấn mạnh tính đa văn hóa chứ không chỉ mang nghĩa toàn cầu nói chung.', 'Our cosmopolitan neighbourhood has restaurants serving food from many countries.', NULL, 'Khu phố mang đậm tính quốc tế của chúng tôi có các nhà hàng phục vụ ẩm thực từ nhiều quốc gia.', '{"wordId":"cosmopolitan","ukIpa":"/ˌkɒzməˈpɒlɪtən/","usIpa":"/ˌkɑːzməˈpɑːlɪtən/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Including people and cultural influences from many different countries.","vi":"mang tính quốc tế, giao thoa văn hóa từ nhiều quốc gia khác nhau"},{"pos":"adj.","en":"Familiar with and comfortable in different countries and cultures.","vi":"hiểu biết rộng, quen thuộc và thoải mái với nhiều nền văn hóa khác nhau trên thế giới"}],"examples":[{"en":"Our cosmopolitan neighbourhood has restaurants serving food from many countries.","vi":"Khu phố mang đậm tính quốc tế của chúng tôi có các nhà hàng phục vụ ẩm thực từ nhiều quốc gia.","audioKind":"ex"},{"en":"Cosmopolitan cities can encourage cultural exchange by creating shared spaces where residents from different backgrounds regularly interact.","vi":"Các thành phố mang tầm vóc quốc tế có thể thúc đẩy giao lưu văn hóa bằng cách kiến tạo những không gian chung nơi cư dân từ các nền tảng khác nhau thường xuyên tương tác.","audioKind":"ex2"}],"collocations":[{"en":"cosmopolitan city","vi":"thành phố mang tính quốc tế"},{"en":"cosmopolitan population","vi":"cộng đồng dân cư đa quốc gia"},{"en":"cosmopolitan outlook","vi":"tầm nhìn toàn cầu"}],"wordFamily":["cosmopolitanism (n.)"],"synonyms":["international","multicultural"],"antonyms":[],"tipVi":"Thường miêu tả thành phố hoặc con người, nhấn mạnh tính đa văn hóa chứ không chỉ mang nghĩa toàn cầu nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_universally', 'en-c1-10', 'universally', '/ˌjuːnɪˈvɝːsəli/', 'C1', 'với mọi người; ở mọi nơi; khắp nơi', 'adv.', 'universal (adj.), universality (n.)', NULL, 'Cường độ mạnh hơn generally, thường nhấn mạnh mọi người hoặc mọi nơi đều như vậy.', 'Her homemade cakes are universally loved by our neighbours.', NULL, 'Những chiếc bánh cô ấy tự làm được tất cả hàng xóm yêu thích.', '{"wordId":"universally","ukIpa":"/ˌjuːnɪˈvɜːsəli/","usIpa":"/ˌjuːnɪˈvɝːsəli/","cefr":"C1","topic":"society","senses":[{"pos":"adv.","en":"by everyone or in every place or situation","vi":"với mọi người; ở mọi nơi; khắp nơi"}],"examples":[{"en":"Her homemade cakes are universally loved by our neighbours.","vi":"Những chiếc bánh cô ấy tự làm được tất cả hàng xóm yêu thích.","audioKind":"ex"},{"en":"Although education is universally recognised as valuable, access to quality schooling remains unequal across regions.","vi":"Mặc dù giáo dục được công nhận rộng rãi là có giá trị, quyền tiếp cận trường học chất lượng vẫn chưa đồng đều giữa các vùng.","audioKind":"ex2"}],"collocations":[{"en":"universally accepted","vi":"được chấp nhận rộng rãi"},{"en":"universally recognised","vi":"được công nhận rộng rãi"},{"en":"universally available","vi":"ai cũng có thể tiếp cận"}],"wordFamily":["universal (adj.)","universality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cường độ mạnh hơn generally, thường nhấn mạnh mọi người hoặc mọi nơi đều như vậy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reticent', 'en-c1-10', 'reticent', '/ˈretɪsənt/', 'C1', 'kín đáo; ít nói; không muốn bộc lộ', 'adj.', 'reticence (n.), reticently (adv.)', 'Đồng nghĩa: reserved, uncommunicative · Trái nghĩa: forthcoming, talkative', 'Nhấn mạnh sự không muốn mở lời hoặc tiết lộ thông tin, không đồng nghĩa với sự miễn cưỡng thông thường.', 'He was reticent about his plans for the weekend.', NULL, 'Anh ấy kín tiếng về những dự định cho dịp cuối tuần.', '{"wordId":"reticent","ukIpa":"/ˈretɪsənt/","usIpa":"/ˈretɪsənt/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"unwilling to talk openly about your thoughts or feelings","vi":"kín đáo; ít nói; không muốn bộc lộ"}],"examples":[{"en":"He was reticent about his plans for the weekend.","vi":"Anh ấy kín tiếng về những dự định cho dịp cuối tuần.","audioKind":"ex"},{"en":"Employees may remain reticent about workplace problems if they fear that speaking openly could damage their careers.","vi":"Nhân viên có thể giữ im lặng về các vấn đề nơi công sở nếu họ sợ rằng việc cất lên tiếng nói công khai có thể tổn hại đến sự nghiệp của mình.","audioKind":"ex2"}],"collocations":[{"en":"reticent about personal matters","vi":"kín tiếng về chuyện riêng tư"},{"en":"remain reticent","vi":"giữ im lặng"},{"en":"a reticent person","vi":"một người ít nói"}],"wordFamily":["reticence (n.)","reticently (adv.)"],"synonyms":["reserved","uncommunicative"],"antonyms":["forthcoming","talkative"],"tipVi":"Nhấn mạnh sự không muốn mở lời hoặc tiết lộ thông tin, không đồng nghĩa với sự miễn cưỡng thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_provoke', 'en-c1-10', 'provoke', '/prəˈvoʊk/', 'C1', 'gây ra; khơi mào; kích thích; chọc giận; khiêu khích', 'v.', 'provocation (n.), provocative (adj.), provocatively (adv.)', 'Đồng nghĩa: trigger, arouse', 'Provoke không chỉ có nghĩa là chọc giận, mà còn thường dùng để chỉ việc gây ra một cuộc thảo luận hoặc phản ứng.', 'The unexpected ending provoked a lively discussion after dinner.', NULL, 'Cái kết bất ngờ đã khơi mào một cuộc thảo luận sôi nổi sau bữa tối.', '{"wordId":"provoke","ukIpa":"/prəˈvəʊk/","usIpa":"/prəˈvoʊk/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To cause a reaction, feeling, or event.","vi":"gây ra; khơi mào; kích thích"},{"pos":"v.","en":"To deliberately make someone angry or likely to react.","vi":"chọc giận; khiêu khích"}],"examples":[{"en":"The unexpected ending provoked a lively discussion after dinner.","vi":"Cái kết bất ngờ đã khơi mào một cuộc thảo luận sôi nổi sau bữa tối.","audioKind":"ex"},{"en":"Proposals to increase public transport fares often provoke strong criticism from commuters who depend on affordable travel.","vi":"Đề xuất tăng giá vé phương tiện công cộng thường vấp phải sự chỉ trích gay gắt từ những người đi làm phụ thuộc vào chi phí đi lại phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"provoke debate","vi":"châm ngòi tranh luận"},{"en":"provoke a reaction","vi":"gây ra phản ứng"},{"en":"provoke criticism","vi":"rước lấy chỉ trích"},{"en":"provoke someone into doing something","vi":"khiêu khích ai đó làm gì"}],"wordFamily":["provocation (n.)","provocative (adj.)","provocatively (adv.)"],"synonyms":["trigger","arouse"],"antonyms":[],"tipVi":"Provoke không chỉ có nghĩa là chọc giận, mà còn thường dùng để chỉ việc gây ra một cuộc thảo luận hoặc phản ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conform', 'en-c1-10', 'conform', '/kənˈfɔːrm/', 'C1', 'tuân thủ; tuân theo; hòa nhập; sống theo số đông', 'v.', 'conformity (n.), conformist (n.), nonconformist (n.)', 'Đồng nghĩa: comply · Trái nghĩa: rebel', 'Thường đi với giới từ như conform to rules hoặc standards, không trực tiếp đi liền tân ngữ.', 'These new helmets conform to the latest safety standards.', NULL, 'Những chiếc mũ bảo hiểm mới này đáp ứng các tiêu chuẩn an toàn mới nhất.', '{"wordId":"conform","ukIpa":"/kənˈfɔːm/","usIpa":"/kənˈfɔːrm/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to follow rules or meet required standards","vi":"tuân thủ; tuân theo"},{"pos":"v.","en":"to behave as others in a group expect","vi":"hòa nhập; sống theo số đông"}],"examples":[{"en":"These new helmets conform to the latest safety standards.","vi":"Những chiếc mũ bảo hiểm mới này đáp ứng các tiêu chuẩn an toàn mới nhất.","audioKind":"ex"},{"en":"Pressure to conform can discourage young people from expressing original ideas or questioning established traditions.","vi":"Áp lực phải sống theo số đông có thể khiến giới trẻ ngần ngại thể hiện ý tưởng độc đáo hoặc dám đặt câu hỏi về các truyền thống lâu đời.","audioKind":"ex2"}],"collocations":[{"en":"conform to standards","vi":"tuân thủ tiêu chuẩn"},{"en":"conform to regulations","vi":"tuân thủ quy định"},{"en":"pressure to conform","vi":"áp lực phải hòa nhập theo số đông"}],"wordFamily":["conformity (n.)","conformist (n.)","nonconformist (n.)"],"synonyms":["comply"],"antonyms":["rebel"],"tipVi":"Thường đi với giới từ như conform to rules hoặc standards, không trực tiếp đi liền tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wane', 'en-c1-10', 'wane', '/weɪn/', 'C1', 'suy giảm; suy yếu dần; khuyết dần (mặt trăng); sự suy giảm dần', 'v.', NULL, 'Đồng nghĩa: decline, diminish · Trái nghĩa: increase, wax', 'Động từ thường không có tân ngữ đi kèm; cụm on the wane mang nghĩa đang suy tàn.', 'My enthusiasm waned after another hour in the queue.', NULL, 'Sự hào hứng của tôi đã vơi đi sau khi phải xếp hàng thêm một tiếng đồng hồ nữa.', '{"wordId":"wane","ukIpa":"/weɪn/","usIpa":"/weɪn/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"gradually become weaker, smaller, or less important","vi":"suy giảm; suy yếu dần"},{"pos":"v.","en":"show a progressively smaller illuminated part of the moon","vi":"khuyết dần (mặt trăng)"},{"pos":"n.","en":"a gradual decline, especially in the phrase on the wane","vi":"sự suy giảm dần"}],"examples":[{"en":"My enthusiasm waned after another hour in the queue.","vi":"Sự hào hứng của tôi đã vơi đi sau khi phải xếp hàng thêm một tiếng đồng hồ nữa.","audioKind":"ex"},{"en":"Public support for environmental policies may wane if their financial costs are distributed unfairly.","vi":"Sự ủng hộ của công chúng đối với các chính sách môi trường có thể suy giảm nếu gánh nặng tài chính của chúng được phân bổ không công bằng.","audioKind":"ex2"}],"collocations":[{"en":"waning interest","vi":"sự quan tâm phai nhạt"},{"en":"on the wane","vi":"đang trên đà suy thoái"},{"en":"a waning moon","vi":"trăng khuyết"}],"wordFamily":[],"synonyms":["decline","diminish"],"antonyms":["increase","wax"],"tipVi":"Động từ thường không có tân ngữ đi kèm; cụm on the wane mang nghĩa đang suy tàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_materialism', 'en-c1-10', 'materialism', '/məˈtɪriəlɪzəm/', 'C1', 'chủ nghĩa vật chất; lối sống thực dụng; thuyết duy vật', 'n.', 'material (n.), materialist (n.), materialistic (adj.)', 'Trái nghĩa: idealism', 'Trong chủ đề tiêu dùng, từ này thường chỉ lối sống chuộng vật chất; trong bối cảnh triết học, nó mang nghĩa thuyết duy vật.', 'She dislikes materialism and prefers experiences to expensive possessions.', NULL, 'Cô ấy không thích chủ nghĩa vật chất và thích những trải nghiệm hơn là những món đồ đắt tiền.', '{"wordId":"materialism","ukIpa":"/məˈtɪəriəlɪzəm/","usIpa":"/məˈtɪriəlɪzəm/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The belief that money and possessions matter most","vi":"chủ nghĩa vật chất; lối sống thực dụng"},{"pos":"n.","en":"The philosophical view that everything ultimately consists of matter","vi":"thuyết duy vật"}],"examples":[{"en":"She dislikes materialism and prefers experiences to expensive possessions.","vi":"Cô ấy không thích chủ nghĩa vật chất và thích những trải nghiệm hơn là những món đồ đắt tiền.","audioKind":"ex"},{"en":"Critics argue that advertising encourages materialism by linking personal happiness to the purchase of consumer goods.","vi":"Các nhà phê bình lập luận rằng quảng cáo thúc đẩy chủ nghĩa vật chất bằng cách liên kết hạnh phúc cá nhân với việc mua sắm hàng tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"consumer materialism","vi":"chủ nghĩa tiêu dùng vật chất"},{"en":"encourage materialism","vi":"thúc đẩy chủ nghĩa vật chất"},{"en":"philosophical materialism","vi":"thuyết duy vật triết học"},{"en":"historical materialism","vi":"chủ nghĩa duy vật lịch sử"}],"wordFamily":["material (n.)","materialist (n.)","materialistic (adj.)"],"synonyms":[],"antonyms":["idealism"],"tipVi":"Trong chủ đề tiêu dùng, từ này thường chỉ lối sống chuộng vật chất; trong bối cảnh triết học, nó mang nghĩa thuyết duy vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_10_1', 'en-c1-10', 'Cách dùng “representation” (n.) — sự đại diện; quyền đại diện', 'legal representation  ·  political representation  ·  accurate representation', 'Từ này vừa có thể chỉ hành động thay mặt người khác lên tiếng, vừa chỉ cách một sự vật được thể hiện qua hình ảnh hoặc chữ viết.', 'Họ từ (Word Family): represent (v.), representative (n.), representative (adj.), representational (adj.)', '[{"hanzi":"Our club now has representation on the town committee.","pinyin":"","meaning":"Câu lạc bộ của chúng tôi giờ đây đã có người đại diện trong ủy ban thị trấn."},{"hanzi":"Accurate representation of different communities in school textbooks can help students develop a more inclusive worldview.","pinyin":"","meaning":"Việc phản ánh chính xác các cộng đồng khác nhau trong sách giáo khoa nhà trường có thể giúp học sinh xây dựng một thế giới quan bao dung hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_10_2', 'en-c1-10', 'Cách dùng “materialism” (n.) — chủ nghĩa vật chất; lối sống thực dụng', 'consumer materialism  ·  encourage materialism  ·  philosophical materialism', 'Trong chủ đề tiêu dùng, từ này thường chỉ lối sống chuộng vật chất; trong bối cảnh triết học, nó mang nghĩa thuyết duy vật.', 'Họ từ (Word Family): material (n.), materialist (n.), materialistic (adj.) | Trái nghĩa: idealism', '[{"hanzi":"She dislikes materialism and prefers experiences to expensive possessions.","pinyin":"","meaning":"Cô ấy không thích chủ nghĩa vật chất và thích những trải nghiệm hơn là những món đồ đắt tiền."},{"hanzi":"Critics argue that advertising encourages materialism by linking personal happiness to the purchase of consumer goods.","pinyin":"","meaning":"Các nhà phê bình lập luận rằng quảng cáo thúc đẩy chủ nghĩa vật chất bằng cách liên kết hạnh phúc cá nhân với việc mua sắm hàng tiêu dùng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_10_3', 'en-c1-10', 'Cách dùng “evict” (v.) — trục xuất; đuổi ra khỏi nhà/đất (theo pháp luật)', 'evict a tenant  ·  evict someone from a property  ·  face eviction', 'Thường dùng cấu trúc evict somebody from; đặc biệt dùng trong ngữ cảnh pháp lý khi buộc ai rời khỏi nhà cho thuê.', 'Họ từ (Word Family): eviction (n.)', '[{"hanzi":"The landlord threatened to evict us over unpaid rent.","pinyin":"","meaning":"Chủ nhà đe dọa sẽ trục xuất chúng tôi vì nợ tiền thuê nhà."},{"hanzi":"Stronger tenant protections could prevent landlords from evicting vulnerable families without adequate notice or legal justification.","pinyin":"","meaning":"Các biện pháp bảo vệ người thuê nhà vững chắc hơn có thể ngăn chặn việc chủ nhà trục xuất những hộ gia đình dễ bị tổn thương mà không có thông báo trước đầy đủ hoặc không có căn cứ pháp lý."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_10_4', 'en-c1-10', 'Cách dùng “provoke” (v.) — gây ra; khơi mào; kích thích', 'provoke debate  ·  provoke a reaction  ·  provoke criticism', 'Provoke không chỉ có nghĩa là chọc giận, mà còn thường dùng để chỉ việc gây ra một cuộc thảo luận hoặc phản ứng.', 'Họ từ (Word Family): provocation (n.), provocative (adj.), provocatively (adv.) | Đồng nghĩa: trigger, arouse', '[{"hanzi":"The unexpected ending provoked a lively discussion after dinner.","pinyin":"","meaning":"Cái kết bất ngờ đã khơi mào một cuộc thảo luận sôi nổi sau bữa tối."},{"hanzi":"Proposals to increase public transport fares often provoke strong criticism from commuters who depend on affordable travel.","pinyin":"","meaning":"Đề xuất tăng giá vé phương tiện công cộng thường vấp phải sự chỉ trích gay gắt từ những người đi làm phụ thuộc vào chi phí đi lại phải chăng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
