INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_10_1_8', 'ten_c1_10_1', 'firearm', 'The antique firearm was displayed behind thick museum glass.', 'The antique firearm was displayed behind thick museum glass.', '/ˈfaɪrɑːrm/', 'Khẩu súng cổ được trưng bày đằng sau lớp kính dày của viện bảo tàng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_10_1_1', 'en-c1-10', 'ten_c1_10_1', 'listening', 'listening', 'Our club now has representation on the town committee.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy cẩn trọng khi thảo luận về đời tư của cô ấy.","Kẻ gọi điện đã cố gắng lừa lấy tiền tiết kiệm của bà ấy.","Người tài xế lịch sự đã kiên nhẫn đợi tôi tìm vé xe.","Câu lạc bộ của chúng tôi giờ đây đã có người đại diện trong ủy ban thị trấn."]'::jsonb, 3, 'Our club now has representation on the town committee. → Câu lạc bộ của chúng tôi giờ đây đã có người đại diện trong ủy ban thị trấn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_10_1_2', 'en-c1-10', 'ten_c1_10_1', 'listening', 'listening', 'The landlord threatened to evict us over unpaid rent.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chủ nhà đe dọa sẽ trục xuất chúng tôi vì nợ tiền thuê nhà.","Kẻ gọi điện đã cố gắng lừa lấy tiền tiết kiệm của bà ấy.","Nhóm đọc sách của chúng tôi đã thảo luận về các tư tưởng của chủ nghĩa Mác tại thư viện.","Cuộc thảo luận thân thiện của họ chẳng mấy chốc đã biến thành một cuộc cãi vã ồn ào."]'::jsonb, 0, 'The landlord threatened to evict us over unpaid rent. → Chủ nhà đe dọa sẽ trục xuất chúng tôi vì nợ tiền thuê nhà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_10_1_3', 'en-c1-10', 'ten_c1_10_1', 'listening', 'listening', 'The nomad packed his tent before moving his goats uphill.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người du mục thu dọn lều bạt trước khi lùa đàn dê lên sườn đồi.","Kẻ gọi điện đã cố gắng lừa lấy tiền tiết kiệm của bà ấy.","Người tài xế lịch sự đã kiên nhẫn đợi tôi tìm vé xe.","Chủ nhà đe dọa sẽ trục xuất chúng tôi vì nợ tiền thuê nhà."]'::jsonb, 0, 'The nomad packed his tent before moving his goats uphill. → Người du mục thu dọn lều bạt trước khi lùa đàn dê lên sườn đồi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_10_2', 'en-c1-10', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_10_2_1', 'ten_c1_10_2', 'representation', 'Accurate representation of different communities in school textbooks can help students develop a more inclusive worldview.', 'Accurate representation of different communities in school textbooks can help students develop a more inclusive worldview.', '/ˌreprɪzenˈteɪʃən/', 'Việc phản ánh chính xác các cộng đồng khác nhau trong sách giáo khoa nhà trường có thể giúp học sinh xây dựng một thế giới quan bao dung hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_10_2_2', 'ten_c1_10_2', 'evict', 'Stronger tenant protections could prevent landlords from evicting vulnerable families without adequate notice or legal justification.', 'Stronger tenant protections could prevent landlords from evicting vulnerable families without adequate notice or legal justification.', '/ɪˈvɪkt/', 'Các biện pháp bảo vệ người thuê nhà vững chắc hơn có thể ngăn chặn việc chủ nhà trục xuất những hộ gia đình dễ bị tổn thương mà không có thông báo trước đầy đủ hoặc không có căn cứ pháp lý.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_10_2_3', 'ten_c1_10_2', 'nomad', 'For many nomads, access to seasonal grazing land is essential to maintaining their traditional way of life.', 'For many nomads, access to seasonal grazing land is essential to maintaining their traditional way of life.', '/ˈnoʊmæd/', 'Đối với nhiều người du mục, việc tiếp cận các bãi chăn thả theo mùa là điều cốt yếu để duy trì lối sống truyền thống của họ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_10_2_4', 'ten_c1_10_2', 'degenerate', 'Without regular maintenance, public facilities can degenerate rapidly, reducing residents'' quality of life and increasing future repair costs.', 'Without regular maintenance, public facilities can degenerate rapidly, reducing residents'' quality of life and increasing future repair costs.', '/dɪˈdʒenəreɪt/', 'Nếu thiếu bảo trì định kỳ, các công trình công cộng có thể nhanh chóng xuống cấp, làm giảm chất lượng cuộc sống của cư dân và tăng chi phí sửa chữa trong tương lai.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_10_2_5', 'ten_c1_10_2', 'Marxist', 'A Marxist analysis of housing examines how property ownership and class relations influence access to affordable homes.', 'A Marxist analysis of housing examines how property ownership and class relations influence access to affordable homes.', '/ˈmɑːrksɪst/', 'Một bài phân tích theo quan điểm Mác-xít về nhà ở xem xét cách quyền sở hữu tài sản và quan hệ giai cấp chi phối khả năng tiếp cận nhà ở giá rẻ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_10_2_6', 'ten_c1_10_2', 'renowned', 'Universities renowned for scientific research often attract international students and encourage cooperation across national borders.', 'Universities renowned for scientific research often attract international students and encourage cooperation across national borders.', '/rɪˈnaʊnd/', 'Các trường đại học nổi tiếng về nghiên cứu khoa học thường thu hút sinh viên quốc tế và thúc đẩy hợp tác vượt qua biên giới các quốc gia.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_10_2_1', 'en-c1-10', 'ten_c1_10_2', 'listening', 'listening', 'Accurate representation of different communities in school textbooks can help students develop a more inclusive worldview.', NULL, 'Trong câu vừa nghe, từ “representation” mang nghĩa nào sau đây?', '["thuộc Giáo hội Chính thống giáo Đông phương","sự đại diện; quyền đại diện","sự cẩu thả, sự lơ đễnh, sự thiếu trách nhiệm, lỗi bất cẩn","buộc phải; bắt buộc"]'::jsonb, 1, '“representation” (/ˌreprɪzenˈteɪʃən/): sự đại diện; quyền đại diện. Câu đầy đủ: Accurate representation of different communities in school textbooks can help students develop a more inclusive worldview.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_10_2_2', 'en-c1-10', 'ten_c1_10_2', 'listening', 'listening', 'Stronger tenant protections could prevent landlords from evicting vulnerable families without adequate notice or legal justification.', NULL, 'Trong câu vừa nghe, từ “evict” mang nghĩa nào sau đây?', '["văn xuôi","trục xuất; đuổi ra khỏi nhà/đất (theo pháp luật)","khéo léo; tế nhị; lịch sự","bãi cỏ chăn gia súc; đồng cỏ"]'::jsonb, 1, '“evict” (/ɪˈvɪkt/): trục xuất; đuổi ra khỏi nhà/đất (theo pháp luật). Câu đầy đủ: Stronger tenant protections could prevent landlords from evicting vulnerable families without adequate notice or legal justification.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
