INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_1', 'en-c1-10', NULL, 'comprehensive_test', 'listening', 'representation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cúi xuống; khom lưng","sự đại diện; quyền đại diện","miệng (cốc, bát, hoặc vật chứa khác)","cản trở; gây khó khăn"]'::jsonb, 1, 'representation (/ˌreprɪzenˈteɪʃən/) → sự đại diện; quyền đại diện; sự miêu tả; sự thể hiện; cách trình bày', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_2', 'en-c1-10', NULL, 'comprehensive_test', 'listening', 'The landlord threatened to evict us over unpaid rent.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiệm bánh nhỏ này nổi tiếng với những chiếc bánh mì tươi ngon.","Cái kết bất ngờ đã khơi mào một cuộc thảo luận sôi nổi sau bữa tối.","Cô ấy không thích chủ nghĩa vật chất và thích những trải nghiệm hơn là những món đồ đắt tiền.","Chủ nhà đe dọa sẽ trục xuất chúng tôi vì nợ tiền thuê nhà."]'::jsonb, 3, 'The landlord threatened to evict us over unpaid rent. → Chủ nhà đe dọa sẽ trục xuất chúng tôi vì nợ tiền thuê nhà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_3', 'en-c1-10', NULL, 'comprehensive_test', 'listening', 'nomad', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hội chứng","du mục; người lang thang đây đó","cấu thành; tạo thành","gửi đi; phái đi"]'::jsonb, 1, 'nomad (/ˈnoʊmæd/) → du mục; người lang thang đây đó', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_4', 'en-c1-10', NULL, 'comprehensive_test', 'listening', 'Their friendly discussion soon degenerated into a noisy argument.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuộc thảo luận thân thiện của họ chẳng mấy chốc đã biến thành một cuộc cãi vã ồn ào.","Kẻ gọi điện đã cố gắng lừa lấy tiền tiết kiệm của bà ấy.","Nhóm đọc sách của chúng tôi đã thảo luận về các tư tưởng của chủ nghĩa Mác tại thư viện.","Khu phố mang đậm tính quốc tế của chúng tôi có các nhà hàng phục vụ ẩm thực từ nhiều quốc gia."]'::jsonb, 0, 'Their friendly discussion soon degenerated into a noisy argument. → Cuộc thảo luận thân thiện của họ chẳng mấy chốc đã biến thành một cuộc cãi vã ồn ào.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_5', 'en-c1-10', NULL, 'comprehensive_test', 'listening', 'Marxist', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phòng họp; hội trường; phòng chức năng (thường dùng cho mục đích chính thức)","thuộc chủ nghĩa Mác","đạo văn; sao chép","tế bào nhân; nhân tế bào"]'::jsonb, 1, 'Marxist (/ˈmɑːrksɪst/) → thuộc chủ nghĩa Mác; người theo chủ nghĩa Mác', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_6', 'en-c1-10', NULL, 'comprehensive_test', 'listening', 'This small bakery is renowned for its fresh bread.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông tôi tin rằng nói dối là một hành vi có tội.","Tiệm bánh nhỏ này nổi tiếng với những chiếc bánh mì tươi ngon.","Cái kết bất ngờ đã khơi mào một cuộc thảo luận sôi nổi sau bữa tối.","Xin hãy cẩn trọng khi thảo luận về đời tư của cô ấy."]'::jsonb, 1, 'This small bakery is renowned for its fresh bread. → Tiệm bánh nhỏ này nổi tiếng với những chiếc bánh mì tươi ngon.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_7', 'en-c1-10', NULL, 'comprehensive_test', 'listening', 'condemn', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thượng nghị sĩ","ngụy biện; quan niệm sai lầm","lên án; chỉ trích mạnh mẽ ai đó hoặc cái gì","tiếp thu và lĩnh hội hoàn toàn thông tin hoặc ý tưởng mới"]'::jsonb, 2, 'condemn (/kənˈdem/) → lên án; chỉ trích mạnh mẽ ai đó hoặc cái gì; tuyên án phạt nặng một cách chính thức; tuyên bố chính thức một tòa nhà không an toàn để sử dụng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_8', 'en-c1-10', NULL, 'comprehensive_test', 'listening', 'The antique firearm was displayed behind thick museum glass.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đã cố gắng thao túng anh trai để anh ấy phải rửa bát.","Khu phố mang đậm tính quốc tế của chúng tôi có các nhà hàng phục vụ ẩm thực từ nhiều quốc gia.","Khẩu súng cổ được trưng bày đằng sau lớp kính dày của viện bảo tàng.","Ông tôi tin rằng nói dối là một hành vi có tội."]'::jsonb, 2, 'The antique firearm was displayed behind thick museum glass. → Khẩu súng cổ được trưng bày đằng sau lớp kính dày của viện bảo tàng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_9', 'en-c1-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “relating to Marx''s theories about class, economics, and society”?', '["suppress","Marxist","provision","conform"]'::jsonb, 1, 'Marxist (/ˈmɑːrksɪst/) → thuộc chủ nghĩa Mác', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_10', 'en-c1-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Widely known and admired for a particular quality or achievement.”?', '["firearm","wane","affirm","renowned"]'::jsonb, 3, 'renowned (/rɪˈnaʊnd/) → nổi tiếng và được ngưỡng mộ rộng rãi nhờ một phẩm chất hoặc thành tựu cụ thể', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_11', 'en-c1-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To express strong disapproval of someone or something.”?', '["evict","condemn","suppress","reticent"]'::jsonb, 1, 'condemn (/kənˈdem/) → lên án; chỉ trích mạnh mẽ ai đó hoặc cái gì', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_12', 'en-c1-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A weapon that fires bullets using an explosive charge.”?', '["degenerate","Marxist","firearm","wane"]'::jsonb, 2, 'firearm (/ˈfaɪrɑːrm/) → súng cầm tay; vũ khí hỏa khí', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_13', 'en-c1-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To prevent a feeling or physical reaction from being expressed.”?', '["universally","condemn","suppress","discretion"]'::jsonb, 2, 'suppress (/səˈpres/) → kìm nén; nén; ngăn chặn', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
