INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_18', 'en-c1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Accurate representation of different communities in school textbooks can help students develop a more inclusive worldview.', 'Dựa vào câu trên, từ “representation” có nghĩa phù hợp nhất là gì?', '["chủ tàu; công ty sở hữu tàu thuyền","sự đại diện; quyền đại diện","thủy ngân","vô cùng khó chịu; đáng ghét"]'::jsonb, 1, 'representation: sự đại diện; quyền đại diện; sự miêu tả; sự thể hiện; cách trình bày. Dịch cả câu: Việc phản ánh chính xác các cộng đồng khác nhau trong sách giáo khoa nhà trường có thể giúp học sinh xây dựng một thế giới quan bao dung hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_19', 'en-c1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Stronger tenant protections could prevent landlords from evicting vulnerable families without adequate notice or legal justification.', 'Dựa vào câu trên, từ “evict” có nghĩa phù hợp nhất là gì?', '["mối thù truyền kiếp; cuộc tranh chấp kéo dài, bất hòa lâu năm","rãnh; đường xẻ","trục xuất; đuổi ra khỏi nhà/đất (theo pháp luật)","làm cạn kiệt; làm suy giảm (làm giảm mạnh số lượng sẵn có của cái gì đó)"]'::jsonb, 2, 'evict: trục xuất; đuổi ra khỏi nhà/đất (theo pháp luật). Dịch cả câu: Các biện pháp bảo vệ người thuê nhà vững chắc hơn có thể ngăn chặn việc chủ nhà trục xuất những hộ gia đình dễ bị tổn thương mà không có thông báo trước đầy đủ hoặc không có căn cứ pháp lý.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_20', 'en-c1-10', NULL, 'comprehensive_test', 'reading', NULL, 'For many nomads, access to seasonal grazing land is essential to maintaining their traditional way of life.', 'Dựa vào câu trên, từ “nomad” có nghĩa phù hợp nhất là gì?', '["du mục; người lang thang đây đó","khuynh hướng bẩm sinh mắc bệnh; thể tạng dễ nhiễm bệnh","xác thực; có tính quyết định; thuyết phục","tình trạng nợ nần; tổng số tiền đang nợ"]'::jsonb, 0, 'nomad: du mục; người lang thang đây đó. Dịch cả câu: Đối với nhiều người du mục, việc tiếp cận các bãi chăn thả theo mùa là điều cốt yếu để duy trì lối sống truyền thống của họ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_21', 'en-c1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Without regular maintenance, public facilities can degenerate rapidly, reducing residents'' quality of life and increasing future repair costs.', 'Dựa vào câu trên, từ “degenerate” có nghĩa phù hợp nhất là gì?', '["thường; thông thường; ở điều kiện bình thường","trở nên xấu đi; thoái hóa; suy đồi","sự việc; sự cố","suy ngẫm kỹ lưỡng về điều gì đó trong một khoảng thời gian dài"]'::jsonb, 1, 'degenerate: trở nên xấu đi; thoái hóa; suy đồi; suy đồi đạo đức; bị thoái hóa. Dịch cả câu: Nếu thiếu bảo trì định kỳ, các công trình công cộng có thể nhanh chóng xuống cấp, làm giảm chất lượng cuộc sống của cư dân và tăng chi phí sửa chữa trong tương lai.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_22', 'en-c1-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tuân thủ; tuân theo”', '["shipowner","conform","plague","commend"]'::jsonb, 1, 'tuân thủ; tuân theo → conform (/kənˈfɔːrm/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_23', 'en-c1-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “suy giảm; suy yếu dần”', '["wane","tolerable","missionary","encircle"]'::jsonb, 0, 'suy giảm; suy yếu dần → wane (/weɪn/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_10_24', 'en-c1-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chủ nghĩa vật chất; lối sống thực dụng”', '["bloc","ore","contempt","materialism"]'::jsonb, 3, 'chủ nghĩa vật chất; lối sống thực dụng → materialism (/məˈtɪriəlɪzəm/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-11', 'en', 'Bài 11: Xã hội & Cộng đồng (6) - CEFR C1', 'CEFR C1', 'C1 · Xã hội', '27 từ vựng Tiếng Anh CEFR C1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5011, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_orderly', 'en-c1-11', 'orderly', '/ˈɔːrdərli/', 'C1', 'có trật tự; ngăn nắp; có kỷ luật; nhân viên hộ lý bệnh viện; binh sĩ phục vụ cấp trên', 'adj.', 'order (n.), order (v.), disorderly (adj.), orderliness (n.)', 'Đồng nghĩa: organised, tidy · Trái nghĩa: disorderly, chaotic', 'Mặc dù tận cùng bằng -ly, từ này thường đóng vai trò là tính từ; khi làm danh từ, nó có thể chỉ nhân viên hộ lý trong bệnh viện.', 'The children formed an orderly queue outside the classroom.', NULL, 'Bọn trẻ xếp thành một hàng ngay ngắn bên ngoài lớp học.', '{"wordId":"orderly","ukIpa":"/ˈɔːdəli/","usIpa":"/ˈɔːrdərli/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"well arranged or behaving in a controlled, organised way","vi":"có trật tự; ngăn nắp; có kỷ luật"},{"pos":"n.","en":"a hospital worker doing practical tasks, or a soldier''s assistant","vi":"nhân viên hộ lý bệnh viện; binh sĩ phục vụ cấp trên"}],"examples":[{"en":"The children formed an orderly queue outside the classroom.","vi":"Bọn trẻ xếp thành một hàng ngay ngắn bên ngoài lớp học.","audioKind":"ex"},{"en":"Clear evacuation procedures help ensure an orderly departure from public buildings during emergencies, reducing the risk of injury.","vi":"Các quy trình sơ tán rõ ràng giúp đảm bảo mọi người rời khỏi các tòa nhà công cộng một cách trật tự trong các trường hợp khẩn cấp, từ đó làm giảm nguy cơ thương tích.","audioKind":"ex2"}],"collocations":[{"en":"orderly queue","vi":"hàng ngũ ngay ngắn"},{"en":"orderly manner","vi":"tác phong có trật tự"},{"en":"orderly evacuation","vi":"sơ tán có trật tự"},{"en":"hospital orderly","vi":"hộ lý bệnh viện"}],"wordFamily":["order (n.)","order (v.)","disorderly (adj.)","orderliness (n.)"],"synonyms":["organised","tidy"],"antonyms":["disorderly","chaotic"],"tipVi":"Mặc dù tận cùng bằng -ly, từ này thường đóng vai trò là tính từ; khi làm danh từ, nó có thể chỉ nhân viên hộ lý trong bệnh viện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cordial', 'en-c1-11', 'cordial', '/ˈkɔːrdʒəl/', 'C1', 'thân thiện; nồng hậu; chân tình; nước trái cây cô đặc', 'adj.', 'cordially (adv.), cordiality (n.)', 'Đồng nghĩa: friendly, warm · Trái nghĩa: hostile, unfriendly', 'Tính từ chỉ thái độ thân thiện mang tính trang trọng; ở Anh, danh từ này thường chỉ loại nước quả cô đặc.', 'Our new neighbours gave us a cordial welcome.', NULL, 'Những người hàng xóm mới đã chào đón chúng tôi một cách rất nồng hậu.', '{"wordId":"cordial","ukIpa":"/ˈkɔːdiəl/","usIpa":"/ˈkɔːrdʒəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Friendly and polite, often in a formal situation.","vi":"thân thiện; nồng hậu; chân tình"},{"pos":"n.","en":"A sweet concentrated fruit drink usually diluted with water.","vi":"nước trái cây cô đặc"}],"examples":[{"en":"Our new neighbours gave us a cordial welcome.","vi":"Những người hàng xóm mới đã chào đón chúng tôi một cách rất nồng hậu.","audioKind":"ex"},{"en":"Maintaining cordial relations between neighbouring countries can encourage cooperation on trade and environmental protection.","vi":"Việc duy trì quan hệ ngoại giao hữu nghị giữa các quốc gia láng giềng có thể thúc đẩy sự hợp tác về thương mại và bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"cordial welcome","vi":"sự đón tiếp nồng hậu"},{"en":"cordial relations","vi":"mối quan hệ hữu nghị"},{"en":"lime cordial","vi":"nước cốt chanh cô đặc"}],"wordFamily":["cordially (adv.)","cordiality (n.)"],"synonyms":["friendly","warm"],"antonyms":["hostile","unfriendly"],"tipVi":"Tính từ chỉ thái độ thân thiện mang tính trang trọng; ở Anh, danh từ này thường chỉ loại nước quả cô đặc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_revive', 'en-c1-11', 'revive', '/rɪˈvaɪv/', 'C1', 'làm sống lại; khôi phục lại; làm tỉnh lại; hồi sức', 'v.', 'revival (n.)', 'Đồng nghĩa: revitalize', 'Có thể là ngoại động từ hoặc nội động từ: revive a tradition; hopes revive.', 'Our neighbours hope to revive the annual street party.', NULL, 'Những người hàng xóm của chúng tôi hy vọng sẽ khôi phục lại lễ hội đường phố thường niên.', '{"wordId":"revive","ukIpa":"/rɪˈvaɪv/","usIpa":"/rɪˈvaɪv/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to become active or popular again, or make something so","vi":"làm sống lại; khôi phục lại"},{"pos":"v.","en":"to regain consciousness or energy, or help someone do so","vi":"làm tỉnh lại; hồi sức"}],"examples":[{"en":"Our neighbours hope to revive the annual street party.","vi":"Những người hàng xóm của chúng tôi hy vọng sẽ khôi phục lại lễ hội đường phố thường niên.","audioKind":"ex"},{"en":"Investment in public transport could revive declining town centres by making local businesses more accessible.","vi":"Việc đầu tư vào giao thông công cộng có thể vực dậy các trung tâm thị trấn đang mai một bằng cách giúp mọi người tiếp cận các doanh nghiệp địa phương dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"revive the economy","vi":"vực dậy nền kinh tế"},{"en":"revive interest in","vi":"khơi gợi lại sự quan tâm đến"},{"en":"revive a tradition","vi":"khôi phục một truyền thống"}],"wordFamily":["revival (n.)"],"synonyms":["revitalize"],"antonyms":[],"tipVi":"Có thể là ngoại động từ hoặc nội động từ: revive a tradition; hopes revive.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arrogantly', 'en-c1-11', 'arrogantly', '/ˈærəɡəntli/', 'C1', 'một cách ngạo mạn; kiêu ngạo', 'adv.', 'arrogant (adj.), arrogance (n.)', 'Đồng nghĩa: haughtily · Trái nghĩa: humbly, modestly', 'Mang sắc thái tiêu cực; nếu muốn diễn tả sự tự tin, hãy dùng từ ''confidently''.', 'He arrogantly dismissed my suggestion without even listening.', NULL, 'Anh ta ngạo mạn bác bỏ ý kiến của tôi mà thậm chí không thèm nghe.', '{"wordId":"arrogantly","ukIpa":"/ˈærəɡəntli/","usIpa":"/ˈærəɡəntli/","cefr":"C1","topic":"society","senses":[{"pos":"adv.","en":"In a way that suggests superiority to other people.","vi":"một cách ngạo mạn; kiêu ngạo"}],"examples":[{"en":"He arrogantly dismissed my suggestion without even listening.","vi":"Anh ta ngạo mạn bác bỏ ý kiến của tôi mà thậm chí không thèm nghe.","audioKind":"ex"},{"en":"Managers who behave arrogantly may discourage employees from sharing ideas that could improve workplace efficiency.","vi":"Những nhà quản lý có cách hành xử ngạo mạn có thể khiến nhân viên nản lòng, không muốn đóng góp những ý tưởng giúp nâng cao hiệu quả công việc.","audioKind":"ex2"}],"collocations":[{"en":"behave arrogantly","vi":"cư xử ngạo mạn"},{"en":"speak arrogantly","vi":"nói năng kiêu ngạo"},{"en":"arrogantly dismiss","vi":"ngạo mạn bác bỏ"}],"wordFamily":["arrogant (adj.)","arrogance (n.)"],"synonyms":["haughtily"],"antonyms":["humbly","modestly"],"tipVi":"Mang sắc thái tiêu cực; nếu muốn diễn tả sự tự tin, hãy dùng từ ''confidently''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parish', 'en-c1-11', 'parish', '/ˈpærɪʃ/', 'C1', 'xứ đạo; giáo xứ; giáo dân trong xứ đạo', 'n.', 'parishioner (n.), parochial (adj.)', NULL, 'Trong ngữ cảnh nhà thờ, từ này chỉ giáo xứ, nhỏ hơn giáo phận (diocese).', 'Our parish has a small church beside the river.', NULL, 'Giáo xứ của chúng tôi có một nhà thờ nhỏ nằm bên bờ sông.', '{"wordId":"parish","ukIpa":"/ˈpærɪʃ/","usIpa":"/ˈpærɪʃ/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A local church district, or a small administrative area.","vi":"xứ đạo; giáo xứ"},{"pos":"n.","en":"The people living in a particular church district.","vi":"giáo dân trong xứ đạo"}],"examples":[{"en":"Our parish has a small church beside the river.","vi":"Giáo xứ của chúng tôi có một nhà thờ nhỏ nằm bên bờ sông.","audioKind":"ex"},{"en":"Rural parish councils can help maintain public footpaths and protect green spaces for local residents.","vi":"Các hội đồng giáo xứ nông thôn có thể giúp duy trì các con đường đi bộ công cộng và bảo vệ không gian xanh cho người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"parish church","vi":"nhà thờ giáo xứ"},{"en":"parish priest","vi":"linh mục quản xứ"},{"en":"parish council","vi":"hội đồng giáo xứ"}],"wordFamily":["parishioner (n.)","parochial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh nhà thờ, từ này chỉ giáo xứ, nhỏ hơn giáo phận (diocese).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marxism', 'en-c1-11', 'Marxism', '/ˈmɑːrksɪzəm/', 'C1', 'chủ nghĩa Mác', 'n.', 'Marxist (n.), Marxist (adj.)', NULL, 'Viết hoa chữ cái đầu, thường là danh từ không đếm được; Marxist có thể dùng chỉ người theo chủ nghĩa Mác.', 'Our reading group discussed Marxism at the library yesterday.', NULL, 'Nhóm đọc sách của chúng tôi đã thảo luận về chủ nghĩa Mác tại thư viện ngày hôm qua.', '{"wordId":"marxism","ukIpa":"/ˈmɑːksɪzəm/","usIpa":"/ˈmɑːrksɪzəm/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Marx''s theories concerning class conflict, capitalism, and a classless society.","vi":"chủ nghĩa Mác"}],"examples":[{"en":"Our reading group discussed Marxism at the library yesterday.","vi":"Nhóm đọc sách của chúng tôi đã thảo luận về chủ nghĩa Mác tại thư viện ngày hôm qua.","audioKind":"ex"},{"en":"Marxism has influenced academic debates about economic inequality, ownership of resources, and the relationship between social classes.","vi":"Chủ nghĩa Mác đã ảnh hưởng đến các cuộc tranh luận học thuật về bất bình đẳng kinh tế, quyền sở hữu tài nguyên và mối quan hệ giữa các giai cấp xã hội.","audioKind":"ex2"}],"collocations":[{"en":"study Marxism","vi":"nghiên cứu chủ nghĩa Mác"},{"en":"classical Marxism","vi":"chủ nghĩa Mác cổ điển"},{"en":"Marxism and class struggle","vi":"chủ nghĩa Mác và đấu tranh giai cấp"}],"wordFamily":["Marxist (n.)","Marxist (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu, thường là danh từ không đếm được; Marxist có thể dùng chỉ người theo chủ nghĩa Mác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_downfall', 'en-c1-11', 'downfall', '/ˈdaʊnfɔːl/', 'C1', 'sự sụp đổ; sự suy sụp (về quyền lực, thành công hoặc địa vị xã hội); nguyên nhân thất bại; nguồn gốc sụp đổ', 'n.', NULL, 'Đồng nghĩa: ruin, collapse · Trái nghĩa: rise', 'Chỉ sự sụp đổ hoặc nguyên nhân thất bại; còn trận mưa lớn xối xả phải dùng downpour.', 'His refusal to listen eventually led to his downfall.', NULL, 'Việc anh ta cố chấp không chịu lắng nghe cuối cùng đã dẫn đến sự sụp đổ của chính mình.', '{"wordId":"downfall","ukIpa":"/ˈdaʊnfɔːl/","usIpa":"/ˈdaʊnfɔːl/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The loss of power, success, or social position.","vi":"sự sụp đổ; sự suy sụp (về quyền lực, thành công hoặc địa vị xã hội)"},{"pos":"n.","en":"Something that causes a person or organisation to fail.","vi":"nguyên nhân thất bại; nguồn gốc sụp đổ"}],"examples":[{"en":"His refusal to listen eventually led to his downfall.","vi":"Việc anh ta cố chấp không chịu lắng nghe cuối cùng đã dẫn đến sự sụp đổ của chính mình.","audioKind":"ex"},{"en":"Widespread corruption can trigger the downfall of a government by destroying public trust in its institutions.","vi":"Tình trạng tham nhũng lan rộng có thể châm ngòi cho sự sụp đổ của một chính phủ bằng cách phá hủy niềm tin của công chúng vào các cơ quan nhà nước.","audioKind":"ex2"}],"collocations":[{"en":"lead to someone''s downfall","vi":"dẫn đến sự sụp đổ của ai đó"},{"en":"bring about the downfall of","vi":"gây ra sự suy sụp của"},{"en":"prove to be someone''s downfall","vi":"cuối cùng trở thành nguyên nhân thất bại của ai đó"}],"wordFamily":[],"synonyms":["ruin","collapse"],"antonyms":["rise"],"tipVi":"Chỉ sự sụp đổ hoặc nguyên nhân thất bại; còn trận mưa lớn xối xả phải dùng downpour.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outrage', 'en-c1-11', 'outrage', '/ˈaʊtreɪdʒ/', 'C1', 'sự phẫn nộ; niềm căm phẫn sâu sắc; làm phẫn nộ; kích động sự tức giận dữ dội; hành vi trái đạo lý; hành vi tàn bạo', 'n.', 'outraged (adj.), outrageous (adj.), outrageously (adv.)', 'Đồng nghĩa: indignation, fury', 'Danh từ chỉ sự phẫn nộ thường không đếm được; cụm an outrage dùng để chỉ hành vi tàn bạo, sai trái.', 'Residents expressed outrage when workers cut down the ancient tree.', NULL, 'Người dân đã bày tỏ sự phẫn nộ tột cùng khi các công nhân đốn hạ cây cổ thụ đó.', '{"wordId":"outrage","ukIpa":"/ˈaʊtreɪdʒ/","usIpa":"/ˈaʊtreɪdʒ/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Intense anger caused by something deeply unfair or wrong","vi":"sự phẫn nộ; niềm căm phẫn sâu sắc"},{"pos":"v.","en":"To make someone extremely angry through unacceptable behaviour","vi":"làm phẫn nộ; kích động sự tức giận dữ dội"},{"pos":"n.","en":"An act that is shockingly wrong or unacceptable","vi":"hành vi trái đạo lý; hành vi tàn bạo; sự phẫn nộ"}],"examples":[{"en":"Residents expressed outrage when workers cut down the ancient tree.","vi":"Người dân đã bày tỏ sự phẫn nộ tột cùng khi các công nhân đốn hạ cây cổ thụ đó.","audioKind":"ex"},{"en":"Public outrage over river pollution prompted the government to introduce stricter controls on industrial waste.","vi":"Sự phẫn nộ của dư luận trước tình trạng ô nhiễm dòng sông đã thúc đẩy chính phủ ban hành các biện pháp kiểm soát chất thải công nghiệp ngặt nghèo hơn.","audioKind":"ex2"}],"collocations":[{"en":"public outrage","vi":"sự phẫn nộ của công chúng"},{"en":"spark outrage","vi":"châm ngòi sự phẫn nộ"},{"en":"express outrage","vi":"bày tỏ sự phẫn nộ"},{"en":"an outrage against humanity","vi":"hành vi chống lại loài người; tội ác chống nhân loại"}],"wordFamily":["outraged (adj.)","outrageous (adj.)","outrageously (adv.)"],"synonyms":["indignation","fury"],"antonyms":[],"tipVi":"Danh từ chỉ sự phẫn nộ thường không đếm được; cụm an outrage dùng để chỉ hành vi tàn bạo, sai trái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plea', 'en-c1-11', 'plea', '/pliː/', 'C1', 'lời khẩn cầu; lời thỉnh cầu thiết tha; lời khai; lời biện hộ (nhận tội hoặc không nhận tội trước tòa)', 'n.', 'plead (v.), pleading (adj.)', 'Đồng nghĩa: appeal, request', 'Theo sau plea for là điều được cầu xin; theo sau plea to là đối tượng nhận lời cầu xin.', 'They heard our plea for help and stopped immediately.', NULL, 'Họ đã nghe thấy tiếng kêu cứu tha thiết của chúng tôi và lập tức dừng lại.', '{"wordId":"plea","ukIpa":"/pliː/","usIpa":"/pliː/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"An urgent, emotional request for something.","vi":"lời khẩn cầu; lời thỉnh cầu thiết tha"},{"pos":"n.","en":"A formal statement admitting or denying guilt in court.","vi":"lời khai; lời biện hộ (nhận tội hoặc không nhận tội trước tòa)"}],"examples":[{"en":"They heard our plea for help and stopped immediately.","vi":"Họ đã nghe thấy tiếng kêu cứu tha thiết của chúng tôi và lập tức dừng lại.","audioKind":"ex"},{"en":"Residents made a plea for better flood protection after repeated storms damaged homes across the region.","vi":"Người dân đã đưa ra lời khẩn cầu tăng cường các biện pháp chống lũ sau khi những trận bão liên tiếp tàn phá nhà cửa trên khắp khu vực.","audioKind":"ex2"}],"collocations":[{"en":"a plea for help","vi":"lời cầu cứu"},{"en":"make a plea","vi":"đưa ra lời khẩn cầu"},{"en":"a guilty plea","vi":"lời nhận tội"},{"en":"enter a plea","vi":"đưa ra lời khai trước tòa"}],"wordFamily":["plead (v.)","pleading (adj.)"],"synonyms":["appeal","request"],"antonyms":[],"tipVi":"Theo sau plea for là điều được cầu xin; theo sau plea to là đối tượng nhận lời cầu xin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impartial', 'en-c1-11', 'impartial', '/ɪmˈpɑːrʃəl/', 'C1', 'công tâm; vô tư; không thiên vị', 'adj.', 'impartiality (n.), impartially (adv.), partial (adj.)', 'Đồng nghĩa: unbiased, neutral, fair · Trái nghĩa: biased, partial', 'Tính từ partial có nghĩa là có sự thiên vị; còn impartial có nghĩa là không thiên vị, công bằng.', 'We asked an impartial neighbour to settle our disagreement.', NULL, 'Chúng tôi đã nhờ một người hàng xóm công tâm đứng ra phân xử bất đồng giữa hai bên.', '{"wordId":"impartial","ukIpa":"/ɪmˈpɑːʃəl/","usIpa":"/ɪmˈpɑːrʃəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Treating all sides fairly without favouring anyone.","vi":"công tâm; vô tư; không thiên vị"}],"examples":[{"en":"We asked an impartial neighbour to settle our disagreement.","vi":"Chúng tôi đã nhờ một người hàng xóm công tâm đứng ra phân xử bất đồng giữa hai bên.","audioKind":"ex"},{"en":"An impartial judicial system is essential for protecting individual rights and maintaining public confidence in government institutions.","vi":"Một hệ thống tư pháp công minh là điều cốt yếu để bảo vệ quyền lợi cá nhân và duy trì niềm tin của công chúng vào các cơ quan nhà nước.","audioKind":"ex2"}],"collocations":[{"en":"impartial advice","vi":"lời khuyên khách quan"},{"en":"impartial judge","vi":"vị thẩm phán công tâm"},{"en":"remain impartial","vi":"giữ thái độ công bằng"}],"wordFamily":["impartiality (n.)","impartially (adv.)","partial (adj.)"],"synonyms":["unbiased","neutral","fair"],"antonyms":["biased","partial"],"tipVi":"Tính từ partial có nghĩa là có sự thiên vị; còn impartial có nghĩa là không thiên vị, công bằng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_candid', 'en-c1-11', 'candid', '/ˈkændɪd/', 'C1', 'thật thà; thẳng thắn; bộc trực; chụp tự nhiên; không sắp đặt', 'adj.', 'candidly (adv.), candour (n.)', 'Đồng nghĩa: frank, forthright · Trái nghĩa: evasive', 'Khi dùng cho người hoặc ý kiến, từ này có nghĩa là thẳng thắn; khi dùng cho ảnh, nó có nghĩa là ảnh chụp tự nhiên, không tạo dáng.', 'Please give me your candid opinion of my cooking.', NULL, 'Xin hãy cho tôi biết đánh giá thành thật của bạn về món ăn tôi nấu.', '{"wordId":"candid","ukIpa":"/ˈkændɪd/","usIpa":"/ˈkændɪd/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Honest and direct, even about uncomfortable subjects.","vi":"thật thà; thẳng thắn; bộc trực"},{"pos":"adj.","en":"Photographed naturally without being asked to pose.","vi":"chụp tự nhiên; không sắp đặt"}],"examples":[{"en":"Please give me your candid opinion of my cooking.","vi":"Xin hãy cho tôi biết đánh giá thành thật của bạn về món ăn tôi nấu.","audioKind":"ex"},{"en":"Candid discussions between teachers and parents can help identify problems before they affect academic progress.","vi":"Những cuộc thảo luận thẳng thắn giữa giáo viên và phụ huynh có thể giúp phát hiện các vấn đề trước khi chúng ảnh hưởng đến kết quả học tập.","audioKind":"ex2"}],"collocations":[{"en":"a candid assessment","vi":"một đánh giá thẳng thắn"},{"en":"be candid about","vi":"thẳng thắn về vấn đề gì"},{"en":"a candid photograph","vi":"một bức ảnh chụp tự nhiên"}],"wordFamily":["candidly (adv.)","candour (n.)"],"synonyms":["frank","forthright"],"antonyms":["evasive"],"tipVi":"Khi dùng cho người hoặc ý kiến, từ này có nghĩa là thẳng thắn; khi dùng cho ảnh, nó có nghĩa là ảnh chụp tự nhiên, không tạo dáng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deter', 'en-c1-11', 'deter', '/dɪˈtɝː/', 'C1', 'ngăn chặn; làm nản lòng', 'v.', 'deterrent (n.), deterrence (n.)', 'Đồng nghĩa: discourage, dissuade · Trái nghĩa: encourage', 'Dùng cấu trúc deter sb from doing; quá khứ là deterred.', 'The heavy rain did not deter our determined hikers.', NULL, 'Cơn mưa lớn không làm chùn bước những nhà leo núi quyết tâm của chúng tôi.', '{"wordId":"deter","ukIpa":"/dɪˈtɜː/","usIpa":"/dɪˈtɝː/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To discourage an action by making it seem difficult or risky.","vi":"ngăn chặn; làm nản lòng"}],"examples":[{"en":"The heavy rain did not deter our determined hikers.","vi":"Cơn mưa lớn không làm chùn bước những nhà leo núi quyết tâm của chúng tôi.","audioKind":"ex"},{"en":"Higher parking fees may deter commuters from driving into city centres during peak hours.","vi":"Việc tăng phí đỗ xe có thể làm người đi làm nản lòng không lái xe vào trung tâm thành phố trong giờ cao điểm.","audioKind":"ex2"}],"collocations":[{"en":"deter someone from doing something","vi":"ngăn cản ai làm việc gì"},{"en":"deter crime","vi":"ngăn chặn tội phạm"},{"en":"deter potential customers","vi":"làm khách hàng tiềm năng chùn bước"}],"wordFamily":["deterrent (n.)","deterrence (n.)"],"synonyms":["discourage","dissuade"],"antonyms":["encourage"],"tipVi":"Dùng cấu trúc deter sb from doing; quá khứ là deterred.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_precarious', 'en-c1-11', 'precarious', '/prɪˈkeriəs/', 'C1', 'bấp bênh; dễ đổ; không ổn định; bấp bênh nguy hiểm', 'adj.', 'precariously (adv.), precariousness (n.)', 'Đồng nghĩa: unstable, insecure, risky · Trái nghĩa: secure, stable', 'Không chỉ mang nghĩa không ổn định mà còn ngầm chỉ rủi ro gặp sự cố bất cứ lúc nào.', 'The ladder looked precarious on the wet, uneven ground.', NULL, 'Chiếc thang trông có vẻ chênh vênh trên nền đất ướt và gồ ghề.', '{"wordId":"precarious","ukIpa":"/prɪˈkeəriəs/","usIpa":"/prɪˈkeriəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"not securely positioned and likely to fall","vi":"bấp bênh; dễ đổ"},{"pos":"adj.","en":"uncertain and likely to become dangerous or unsuccessful","vi":"không ổn định; bấp bênh nguy hiểm"}],"examples":[{"en":"The ladder looked precarious on the wet, uneven ground.","vi":"Chiếc thang trông có vẻ chênh vênh trên nền đất ướt và gồ ghề.","audioKind":"ex"},{"en":"Workers on short-term contracts often face precarious financial circumstances, making it difficult to plan for the future.","vi":"Công nhân làm hợp đồng ngắn hạn thường phải đối mặt với hoàn cảnh tài chính bấp bênh, khiến việc lập kế hoạch cho tương lai trở nên khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"a precarious position","vi":"một vị trí bấp bênh"},{"en":"precarious employment","vi":"việc làm bấp bênh"},{"en":"a precarious balance","vi":"sự cân bằng mong manh"},{"en":"precarious finances","vi":"tình hình tài chính bấp bênh"}],"wordFamily":["precariously (adv.)","precariousness (n.)"],"synonyms":["unstable","insecure","risky"],"antonyms":["secure","stable"],"tipVi":"Không chỉ mang nghĩa không ổn định mà còn ngầm chỉ rủi ro gặp sự cố bất cứ lúc nào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exert', 'en-c1-11', 'exert', '/ɪɡˈzɝːt/', 'C1', 'áp dụng; thi hành; nỗ lực; ráng sức', 'v.', 'exertion (n.)', NULL, 'Thường đi với pressure, influence; exert oneself có nghĩa là cố gắng hết sức.', 'You must exert steady pressure to open this lid.', NULL, 'Bạn phải dùng lực đều tay để mở chiếc nắp này.', '{"wordId":"exert","ukIpa":"/ɪɡˈzɜːt/","usIpa":"/ɪɡˈzɝːt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To apply force, influence, or authority.","vi":"áp dụng; thi hành"},{"pos":"v.","en":"To make a strong physical or mental effort.","vi":"nỗ lực; ráng sức"}],"examples":[{"en":"You must exert steady pressure to open this lid.","vi":"Bạn phải dùng lực đều tay để mở chiếc nắp này.","audioKind":"ex"},{"en":"Parents can exert considerable influence on children''s eating habits by preparing balanced meals at home.","vi":"Cha mẹ có thể tạo ra ảnh hưởng đáng kể đến thói quen ăn uống của con cái bằng cách chuẩn bị các bữa ăn cân bằng dinh dưỡng tại nhà.","audioKind":"ex2"}],"collocations":[{"en":"exert pressure on","vi":"gây áp lực lên"},{"en":"exert influence over","vi":"gây ảnh hưởng đến"},{"en":"exert yourself","vi":"nỗ lực hết mình"}],"wordFamily":["exertion (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi với pressure, influence; exert oneself có nghĩa là cố gắng hết sức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_condolence', 'en-c1-11', 'condolence', '/kənˈdoʊləns/', 'C1', 'lời chia buồn; sự phân ưu', 'n.', 'condole (v.)', 'Đồng nghĩa: sympathy', 'Thường dùng ở số nhiều: offer condolences to someone.', 'Our neighbours sent a heartfelt message of condolence.', NULL, 'Những người hàng xóm của chúng tôi đã gửi một lời chia buồn chân thành.', '{"wordId":"condolence","ukIpa":"/kənˈdəʊləns/","usIpa":"/kənˈdoʊləns/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Sympathy expressed to someone whose relative or friend has died.","vi":"lời chia buồn; sự phân ưu"}],"examples":[{"en":"Our neighbours sent a heartfelt message of condolence.","vi":"Những người hàng xóm của chúng tôi đã gửi một lời chia buồn chân thành.","audioKind":"ex"},{"en":"Public expressions of condolence can help bereaved families feel supported by their wider community.","vi":"Những lời chia buồn được bày tỏ công khai có thể giúp các gia đình có tang cảm nhận được sự hỗ trợ từ cộng đồng xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"offer condolences","vi":"gửi lời chia buồn"},{"en":"a message of condolence","vi":"thông điệp chia buồn"},{"en":"sincere condolences","vi":"lời chia buồn chân thành"}],"wordFamily":["condole (v.)"],"synonyms":["sympathy"],"antonyms":[],"tipVi":"Thường dùng ở số nhiều: offer condolences to someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prevail', 'en-c1-11', 'prevail', '/prɪˈveɪl/', 'C1', 'thịnh hành; phổ biến; chiếm ưu thế; chiến thắng; thuyết phục', 'v.', 'prevailing (adj.)', NULL, 'Giành chiến thắng dùng prevail over; thuyết phục dùng prevail upon sb to do.', 'A relaxed atmosphere prevails in our kitchen on Sundays.', NULL, 'Bầu không khí thư thái luôn bao trùm căn bếp của chúng tôi vào mỗi Chủ nhật.', '{"wordId":"prevail","ukIpa":"/prɪˈveɪl/","usIpa":"/prɪˈveɪl/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to be common or widespread in a place or time","vi":"thịnh hành; phổ biến"},{"pos":"v.","en":"to win or become stronger than an opposing force","vi":"chiếm ưu thế; chiến thắng"},{"pos":"v.","en":"to persuade someone to do something","vi":"thuyết phục"}],"examples":[{"en":"A relaxed atmosphere prevails in our kitchen on Sundays.","vi":"Bầu không khí thư thái luôn bao trùm căn bếp của chúng tôi vào mỗi Chủ nhật.","audioKind":"ex"},{"en":"Where traditional attitudes prevail, public education campaigns may be needed to encourage more equal opportunities for women.","vi":"Nơi nào các quan niệm truyền thống còn thịnh hành, các chiến dịch giáo dục công cộng có thể cần thiết để thúc đẩy cơ hội bình đẳng hơn cho phụ nữ.","audioKind":"ex2"}],"collocations":[{"en":"prevailing conditions","vi":"các điều kiện phổ biến hiện tại"},{"en":"prevail over","vi":"chiếm ưu thế trước"},{"en":"prevail upon someone to do","vi":"thuyết phục ai đó làm gì"}],"wordFamily":["prevailing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Giành chiến thắng dùng prevail over; thuyết phục dùng prevail upon sb to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prestige', 'en-c1-11', 'prestige', '/preˈstiːʒ/', 'C1', 'uy tín; danh vọng; tiếng tăm', 'n.', 'prestigious (adj.)', 'Đồng nghĩa: status, standing', 'Prestige là danh từ không đếm được; tính từ tương ứng là prestigious.', 'Winning the award brought considerable prestige to her small bakery.', NULL, 'Việc giành giải thưởng đã mang lại uy tín đáng kể cho tiệm bánh nhỏ của cô ấy.', '{"wordId":"prestige","ukIpa":"/preˈstiːʒ/","usIpa":"/preˈstiːʒ/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Respect and admiration gained through achievement, quality, or high status.","vi":"uy tín; danh vọng; tiếng tăm"}],"examples":[{"en":"Winning the award brought considerable prestige to her small bakery.","vi":"Việc giành giải thưởng đã mang lại uy tín đáng kể cho tiệm bánh nhỏ của cô ấy.","audioKind":"ex"},{"en":"Some students choose universities for their international prestige rather than the suitability of individual courses.","vi":"Một số sinh viên chọn đại học vì uy tín quốc tế của trường thay vì tính phù hợp của từng khóa học.","audioKind":"ex2"}],"collocations":[{"en":"international prestige","vi":"uy tín quốc tế"},{"en":"gain prestige","vi":"tạo dựng uy tín"},{"en":"social prestige","vi":"uy tín xã hội"},{"en":"a matter of prestige","vi":"vấn đề thể hiện danh vọng"}],"wordFamily":["prestigious (adj.)"],"synonyms":["status","standing"],"antonyms":[],"tipVi":"Prestige là danh từ không đếm được; tính từ tương ứng là prestigious.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_salution', 'en-c1-11', 'salutation', '/ˌsæljuˈteɪʃən/', 'C1', 'lời chào hỏi; lời chào đầu thư; cử chỉ chào; hành động bày tỏ sự tôn kính', 'n.', 'salute (v.), salute (n.)', 'Đồng nghĩa: greeting', 'Thư an đầu thư Dear… là salutation; từ salute thường dùng cho động từ kính lễ.', 'He raised his hand in salutation as we approached.', NULL, 'Anh ấy giơ tay chào khi chúng tôi tiến lại gần.', '{"wordId":"salution","ukIpa":"/ˌsæljuˈteɪʃən/","usIpa":"/ˌsæljuˈteɪʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Words used to greet someone, especially at a letter''s beginning","vi":"lời chào hỏi; lời chào đầu thư"},{"pos":"n.","en":"A gesture or action expressing greeting or respect","vi":"cử chỉ chào; hành động bày tỏ sự tôn kính"}],"examples":[{"en":"He raised his hand in salutation as we approached.","vi":"Anh ấy giơ tay chào khi chúng tôi tiến lại gần.","audioKind":"ex"},{"en":"Choosing an appropriate salutation in formal correspondence helps establish a respectful relationship between the writer and the recipient.","vi":"Việc lựa chọn một lời chào hỏi phù hợp trong thư tín trang trọng giúp thiết lập mối quan hệ tôn trọng lẫn nhau giữa người viết và người nhận.","audioKind":"ex2"}],"collocations":[{"en":"formal salutation","vi":"lời chào trang trọng"},{"en":"opening salutation","vi":"lời chào mở đầu"},{"en":"in salutation","vi":"để tỏ lòng kính trọng"}],"wordFamily":["salute (v.)","salute (n.)"],"synonyms":["greeting"],"antonyms":[],"tipVi":"Thư an đầu thư Dear… là salutation; từ salute thường dùng cho động từ kính lễ.","noteVi":"Từ gốc salution có lỗi chính tả; đã được chuẩn hóa thành salutation.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prominence', 'en-c1-11', 'prominence', '/ˈprɑːmɪnəns/', 'C1', 'sự nổi bật; tầm quan trọng; sự nổi tiếng', 'n.', 'prominent (adj.), prominently (adv.)', 'Đồng nghĩa: importance, notability · Trái nghĩa: obscurity', 'Thường là danh từ không đếm được; cụm rise to prominence mang nghĩa vươn lên khẳng định tên tuổi.', 'The gallery gave her painting prominence near the entrance.', NULL, 'Phòng tranh đã trưng bày bức tranh của cô ấy ở vị trí trang trọng ngay gần lối vào.', '{"wordId":"prominence","ukIpa":"/ˈprɒmɪnəns/","usIpa":"/ˈprɑːmɪnəns/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The state of being noticeable, important, or widely known.","vi":"sự nổi bật; tầm quan trọng; sự nổi tiếng"}],"examples":[{"en":"The gallery gave her painting prominence near the entrance.","vi":"Phòng tranh đã trưng bày bức tranh của cô ấy ở vị trí trang trọng ngay gần lối vào.","audioKind":"ex"},{"en":"Environmental issues have gained prominence in public debate as communities experience more frequent extreme weather events.","vi":"Các vấn đề môi trường ngày càng thu hút sự chú ý trong các cuộc tranh luận công khai khi cộng đồng phải hứng chịu các hiện tượng thời tiết cực đoan thường xuyên hơn.","audioKind":"ex2"}],"collocations":[{"en":"gain prominence","vi":"ngày càng thu hút sự chú ý"},{"en":"rise to prominence","vi":"trở nên nổi bật; vươn lên vị trí hàng đầu"},{"en":"give prominence to","vi":"làm nổi bật; đề cao"}],"wordFamily":["prominent (adj.)","prominently (adv.)"],"synonyms":["importance","notability"],"antonyms":["obscurity"],"tipVi":"Thường là danh từ không đếm được; cụm rise to prominence mang nghĩa vươn lên khẳng định tên tuổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_placard', 'en-c1-11', 'placard', '/ˈplækɑːrd/', 'C1', 'tấm biển thông báo lớn; biểu ngữ (dùng trong các cuộc biểu tình, diễu hành)', 'n.', NULL, NULL, 'Thường chỉ các bảng thông báo lớn được trưng bày công cộng hoặc cầm trong các cuộc biểu tình.', 'She carried a handmade placard through the crowded square.', NULL, 'Cô ấy cầm một tấm biểu ngữ làm thủ công đi qua quảng trường đông đúc.', '{"wordId":"placard","ukIpa":"/ˈplækɑːd/","usIpa":"/ˈplækɑːrd/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a large notice displayed publicly or carried during a demonstration","vi":"tấm biển thông báo lớn; biểu ngữ (dùng trong các cuộc biểu tình, diễu hành)"}],"examples":[{"en":"She carried a handmade placard through the crowded square.","vi":"Cô ấy cầm một tấm biểu ngữ làm thủ công đi qua quảng trường đông đúc.","audioKind":"ex"},{"en":"Residents held placards outside the town hall to demand safer cycling routes in their neighbourhood.","vi":"Người dân đã giơ cao các tấm biểu ngữ bên ngoài tòa nhà thị chính để yêu cầu thiết lập các tuyến đường đạp xe an toàn hơn trong khu1 vực của họ.","audioKind":"ex2"}],"collocations":[{"en":"carry a placard","vi":"mang theo biểu ngữ"},{"en":"hold up a placard","vi":"giơ cao biểu ngữ"},{"en":"protest placard","vi":"biển hiệu biểu tình"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ các bảng thông báo lớn được trưng bày công cộng hoặc cầm trong các cuộc biểu tình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outright', 'en-c1-11', 'outright', '/ˌaʊtˈraɪt/', 'C1', 'hoàn toàn; thẳng thắn; dứt khoát; thanh toán một lần; mua đứt; rõ ràng; công khai', 'adv.', NULL, 'Đồng nghĩa: completely, directly · Trái nghĩa: partially', 'buy outright có nghĩa là mua trả tiền một lần; tính từ thường đứng trước danh từ.', 'My landlord rejected my request outright, without any discussion.', NULL, 'Chủ nhà đã từ chối thẳng thừng yêu cầu của tôi mà không cần bàn bạc gì thêm.', '{"wordId":"outright","ukIpa":"/ˌaʊtˈraɪt/","usIpa":"/ˌaʊtˈraɪt/","cefr":"C1","topic":"society","senses":[{"pos":"adv.","en":"Completely, immediately, or without hiding what you mean.","vi":"hoàn toàn; thẳng thắn; dứt khoát"},{"pos":"adv.","en":"With full payment or ownership, rather than borrowing or sharing.","vi":"thanh toán một lần; mua đứt"},{"pos":"adj.","en":"Complete or clear, with no attempt to hide it.","vi":"hoàn toàn; rõ ràng; công khai"}],"examples":[{"en":"My landlord rejected my request outright, without any discussion.","vi":"Chủ nhà đã từ chối thẳng thừng yêu cầu của tôi mà không cần bàn bạc gì thêm.","audioKind":"ex"},{"en":"Rather than banning private cars outright, cities could encourage residents to use reliable and affordable public transport.","vi":"Thay vì cấm hoàn toàn xe hơi cá nhân, các thành phố có thể khuyến khích cư dân sử dụng giao thông công cộng đáng tin cậy và giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"reject outright","vi":"từ chối thẳng thừng"},{"en":"buy outright","vi":"mua đứt"},{"en":"an outright ban","vi":"lệnh cấm toàn diện"},{"en":"an outright lie","vi":"một lời nói dối trắng trợn"}],"wordFamily":[],"synonyms":["completely","directly"],"antonyms":["partially"],"tipVi":"buy outright có nghĩa là mua trả tiền một lần; tính từ thường đứng trước danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trespass', 'en-c1-11', 'trespass', '/ˈtrespəs/', 'C1', 'xâm phạm; đột nhập trái phép vào đất (hoặc tài sản) của người khác; hành vi xâm phạm đất đai hoặc tài sản trái phép', 'v.', 'trespasser (n.)', NULL, 'Diễn đạt việc xâm phạm trái phép một nơi nào đó thường dùng trespass on, không chỉ lỗi vô ý thông thường.', 'Please don''t trespass on the farm to take photographs.', NULL, 'Xin vui lòng không đột nhập trái phép vào trang trại để chụp ảnh.', '{"wordId":"trespass","ukIpa":"/ˈtrespəs/","usIpa":"/ˈtrespəs/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to enter someone''s land or property without permission","vi":"xâm phạm; đột nhập trái phép vào đất (hoặc tài sản) của người khác"},{"pos":"n.","en":"the act of entering someone''s property without permission","vi":"hành vi xâm phạm đất đai hoặc tài sản trái phép"}],"examples":[{"en":"Please don''t trespass on the farm to take photographs.","vi":"Xin vui lòng không đột nhập trái phép vào trang trại để chụp ảnh.","audioKind":"ex"},{"en":"Clear boundaries around protected habitats can discourage trespass and reduce disturbance to nesting birds.","vi":"Việc vạch rõ ranh giới xung quanh các khu vực sinh sống được bảo vệ có thể ngăn chặn tình trạng xâm nhập trái phép và giảm thiểu sự quấy rầy đối với các loài chim làm tổ.","audioKind":"ex2"}],"collocations":[{"en":"trespass on private property","vi":"xâm phạm tư gia"},{"en":"trespass on someone''s land","vi":"đột nhập vào đất của người khác"}],"wordFamily":["trespasser (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt việc xâm phạm trái phép một nơi nào đó thường dùng trespass on, không chỉ lỗi vô ý thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assault', 'en-c1-11', 'assault', '/əˈsɔːlt/', 'C1', 'cuộc tấn công bạo lực; hành vi hành hung; tấn công; hành hung', 'n.', 'assailant (n.)', 'Đồng nghĩa: attack', 'Danh từ thường kết hợp với on; động từ đi trực tiếp với tân ngữ chỉ người mà không cần giới từ.', 'A witness reported the assault to a nearby police officer.', NULL, 'Một nhân chứng đã trình báo vụ tấn công cho một cảnh sát ở gần đó.', '{"wordId":"assault","ukIpa":"/əˈsɒlt/","usIpa":"/əˈsɔːlt/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a violent physical attack on someone","vi":"cuộc tấn công bạo lực; hành vi hành hung"},{"pos":"v.","en":"to attack someone physically","vi":"tấn công; hành hung"}],"examples":[{"en":"A witness reported the assault to a nearby police officer.","vi":"Một nhân chứng đã trình báo vụ tấn công cho một cảnh sát ở gần đó.","audioKind":"ex"},{"en":"Better street lighting may reduce the risk of assault and help residents feel safer after dark.","vi":"Hệ thống chiếu sáng đường phố tốt hơn có thể làm giảm nguy cơ bị hành hung và giúp cư dân cảm thấy an toàn hơn sau khi trời tối.","audioKind":"ex2"}],"collocations":[{"en":"physical assault","vi":"tấn công bạo lực"},{"en":"an assault on someone","vi":"cuộc tấn công nhằm vào ai đó"},{"en":"report an assault","vi":"báo cáo vụ tấn công"}],"wordFamily":["assailant (n.)"],"synonyms":["attack"],"antonyms":[],"tipVi":"Danh từ thường kết hợp với on; động từ đi trực tiếp với tân ngữ chỉ người mà không cần giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_smuggling', 'en-c1-11', 'smuggling', '/ˈsmʌɡlɪŋ/', 'C1', 'nạn buôn lậu; hành vi vận chuyển trái phép (hàng hóa hoặc người qua biên giới)', 'n.', 'smuggle (v.), smuggler (n.)', NULL, 'Thường là danh từ không đếm được; động từ đi kèm là smuggle goods into a country.', 'The documentary explained how smuggling puts rare animals at risk.', NULL, 'Bộ phim tài liệu đã giải thích nạn buôn lậu đang đẩy các loài động vật quý hiếm vào tình thế nguy hiểm như thế nào.', '{"wordId":"smuggling","ukIpa":"/ˈsmʌɡlɪŋ/","usIpa":"/ˈsmʌɡlɪŋ/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Illegally moving goods or people across borders or past controls.","vi":"nạn buôn lậu; hành vi vận chuyển trái phép (hàng hóa hoặc người qua biên giới)"}],"examples":[{"en":"The documentary explained how smuggling puts rare animals at risk.","vi":"Bộ phim tài liệu đã giải thích nạn buôn lậu đang đẩy các loài động vật quý hiếm vào tình thế nguy hiểm như thế nào.","audioKind":"ex"},{"en":"International cooperation is essential for tackling wildlife smuggling, which threatens biodiversity and undermines conservation efforts.","vi":"Hợp tác quốc tế là yếu tố cốt lõi để giải quyết nạn buôn lậu động vật hoang dã, vốn đang đe dọa sự đa dạng sinh học và phá hoại các nỗ lực bảo tồn.","audioKind":"ex2"}],"collocations":[{"en":"wildlife smuggling","vi":"buôn lậu động vật hoang dã"},{"en":"a smuggling ring","vi":"đường dây buôn lậu"},{"en":"combat smuggling","vi":"chống buôn lậu"}],"wordFamily":["smuggle (v.)","smuggler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; động từ đi kèm là smuggle goods into a country.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bi', 'en-c1-11', 'bi', '/baɪ/', 'C1', 'song tính; lưỡng tính', 'adj.', 'bisexual (adj.), bisexuality (n.)', 'Đồng nghĩa: bisexual', 'Bi là từ viết tắt thân mật của bisexual; không nhầm lẫn với tiền tố bi-.', 'My sister is bi, and our family supports her.', NULL, 'Chị tôi là người song tính, và gia đình chúng tôi luôn ủng hộ chị ấy.', '{"wordId":"bi","ukIpa":"/baɪ/","usIpa":"/baɪ/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"bisexual; romantically or sexually attracted to more than one gender","vi":"song tính; lưỡng tính"}],"examples":[{"en":"My sister is bi, and our family supports her.","vi":"Chị tôi là người song tính, và gia đình chúng tôi luôn ủng hộ chị ấy.","audioKind":"ex"},{"en":"Inclusive workplace policies can help bi employees feel respected and reduce discrimination based on sexual orientation.","vi":"Các chính sách làm việc hòa nhập có thể giúp nhân viên song tính cảm thấy được tôn trọng và giảm thiểu sự kỳ thị dựa trên xu hướng tính dục.","audioKind":"ex2"}],"collocations":[{"en":"bi people","vi":"người song tính"},{"en":"bi identity","vi":"bản dạng song tính"},{"en":"openly bi","vi":"công khai người song tính"}],"wordFamily":["bisexual (adj.)","bisexuality (n.)"],"synonyms":["bisexual"],"antonyms":[],"tipVi":"Bi là từ viết tắt thân mật của bisexual; không nhầm lẫn với tiền tố bi-.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cohesion', 'en-c1-11', 'cohesion', '/koʊˈhiːʒən/', 'C1', 'sức gắn kết; sự đoàn kết; sự liên kết văn bản', 'n.', 'cohesive (adj.), cohesively (adv.), cohere (v.)', 'Đồng nghĩa: unity, togetherness · Trái nghĩa: disunity', 'Trong kỹ năng viết, cohesion chỉ sự liên kết về mặt từ vựng/ngữ pháp, còn coherence chỉ sự mạch lạc về mặt logic.', 'Our weekly team lunches helped build cohesion at work.', NULL, 'Những buổi ăn trưa chung hàng tuần đã giúp xây dựng sự gắn kết trong công việc.', '{"wordId":"cohesion","ukIpa":"/kəʊˈhiːʒən/","usIpa":"/koʊˈhiːʒən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The strength of connection that keeps a group together","vi":"sức gắn kết; sự đoàn kết"},{"pos":"n.","en":"The way parts of a text connect through language","vi":"sự liên kết văn bản"}],"examples":[{"en":"Our weekly team lunches helped build cohesion at work.","vi":"Những buổi ăn trưa chung hàng tuần đã giúp xây dựng sự gắn kết trong công việc.","audioKind":"ex"},{"en":"Shared public spaces can strengthen social cohesion by encouraging regular interaction between residents from different backgrounds.","vi":"Không gian công cộng chung có thể tăng cường sự gắn kết xã hội bằng cách khuyến khích sự tương tác thường xuyên giữa cư dân từ các nền tảng khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"social cohesion","vi":"gắn kết xã hội"},{"en":"team cohesion","vi":"gắn kết đội ngũ"},{"en":"cohesion and coherence","vi":"tính liên kết và mạch lạc"}],"wordFamily":["cohesive (adj.)","cohesively (adv.)","cohere (v.)"],"synonyms":["unity","togetherness"],"antonyms":["disunity"],"tipVi":"Trong kỹ năng viết, cohesion chỉ sự liên kết về mặt từ vựng/ngữ pháp, còn coherence chỉ sự mạch lạc về mặt logic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rivalry', 'en-c1-11', 'rivalry', '/ˈraɪvəlri/', 'C1', 'sự cạnh tranh; sự ganh đua', 'n.', 'rival (n.), rival (v.)', 'Đồng nghĩa: competition · Trái nghĩa: cooperation', 'Nhấn mạnh mối quan hệ cạnh tranh mang tính duy trì, hai bên đối lập thường đi với giới từ between.', 'There is friendly rivalry between our two football teams.', NULL, 'Giữa hai đội bóng của chúng tôi tồn tại một sự cạnh tranh lành mạnh.', '{"wordId":"rivalry","ukIpa":"/ˈraɪvəlri/","usIpa":"/ˈraɪvəlri/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Competition between people or groups seeking the same success.","vi":"sự cạnh tranh; sự ganh đua"}],"examples":[{"en":"There is friendly rivalry between our two football teams.","vi":"Giữa hai đội bóng của chúng tôi tồn tại một sự cạnh tranh lành mạnh.","audioKind":"ex"},{"en":"Commercial rivalry can encourage innovation, although excessive competition may discourage companies from sharing valuable research findings.","vi":"Cạnh tranh thương mại có thể thúc đẩy đổi mới sáng tạo, mặc dù sự cạnh tranh quá mức có thể khiến các công ty ngần ngại chia sẻ những kết quả nghiên cứu giá trị.","audioKind":"ex2"}],"collocations":[{"en":"intense rivalry","vi":"cạnh tranh gay gắt"},{"en":"sibling rivalry","vi":"sự ganh đua giữa anh chị em trong nhà"},{"en":"rivalry between teams","vi":"sự cạnh tranh giữa các đội"}],"wordFamily":["rival (n.)","rival (v.)"],"synonyms":["competition"],"antonyms":["cooperation"],"tipVi":"Nhấn mạnh mối quan hệ cạnh tranh mang tính duy trì, hai bên đối lập thường đi với giới từ between.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_11_1', 'en-c1-11', 'Cách dùng “candid” (adj.) — thật thà; thẳng thắn; bộc trực', 'a candid assessment  ·  be candid about  ·  a candid photograph', 'Khi dùng cho người hoặc ý kiến, từ này có nghĩa là thẳng thắn; khi dùng cho ảnh, nó có nghĩa là ảnh chụp tự nhiên, không tạo dáng.', 'Họ từ (Word Family): candidly (adv.), candour (n.) | Đồng nghĩa: frank, forthright · Trái nghĩa: evasive', '[{"hanzi":"Please give me your candid opinion of my cooking.","pinyin":"","meaning":"Xin hãy cho tôi biết đánh giá thành thật của bạn về món ăn tôi nấu."},{"hanzi":"Candid discussions between teachers and parents can help identify problems before they affect academic progress.","pinyin":"","meaning":"Những cuộc thảo luận thẳng thắn giữa giáo viên và phụ huynh có thể giúp phát hiện các vấn đề trước khi chúng ảnh hưởng đến kết quả học tập."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_11_2', 'en-c1-11', 'Cách dùng “orderly” (adj.) — có trật tự; ngăn nắp; có kỷ luật', 'orderly queue  ·  orderly manner  ·  orderly evacuation', 'Mặc dù tận cùng bằng -ly, từ này thường đóng vai trò là tính từ; khi làm danh từ, nó có thể chỉ nhân viên hộ lý trong bệnh viện.', 'Họ từ (Word Family): order (n.), order (v.), disorderly (adj.), orderliness (n.) | Đồng nghĩa: organised, tidy · Trái nghĩa: disorderly, chaotic', '[{"hanzi":"The children formed an orderly queue outside the classroom.","pinyin":"","meaning":"Bọn trẻ xếp thành một hàng ngay ngắn bên ngoài lớp học."},{"hanzi":"Clear evacuation procedures help ensure an orderly departure from public buildings during emergencies, reducing the risk of injury.","pinyin":"","meaning":"Các quy trình sơ tán rõ ràng giúp đảm bảo mọi người rời khỏi các tòa nhà công cộng một cách trật tự trong các trường hợp khẩn cấp, từ đó làm giảm nguy cơ thương tích."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_11_3', 'en-c1-11', 'Cách dùng “cohesion” (n.) — sức gắn kết; sự đoàn kết', 'social cohesion  ·  team cohesion  ·  cohesion and coherence', 'Trong kỹ năng viết, cohesion chỉ sự liên kết về mặt từ vựng/ngữ pháp, còn coherence chỉ sự mạch lạc về mặt logic.', 'Họ từ (Word Family): cohesive (adj.), cohesively (adv.), cohere (v.) | Đồng nghĩa: unity, togetherness · Trái nghĩa: disunity', '[{"hanzi":"Our weekly team lunches helped build cohesion at work.","pinyin":"","meaning":"Những buổi ăn trưa chung hàng tuần đã giúp xây dựng sự gắn kết trong công việc."},{"hanzi":"Shared public spaces can strengthen social cohesion by encouraging regular interaction between residents from different backgrounds.","pinyin":"","meaning":"Không gian công cộng chung có thể tăng cường sự gắn kết xã hội bằng cách khuyến khích sự tương tác thường xuyên giữa cư dân từ các nền tảng khác nhau."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_11_4', 'en-c1-11', 'Cách dùng “cordial” (adj.) — thân thiện; nồng hậu; chân tình', 'cordial welcome  ·  cordial relations  ·  lime cordial', 'Tính từ chỉ thái độ thân thiện mang tính trang trọng; ở Anh, danh từ này thường chỉ loại nước quả cô đặc.', 'Họ từ (Word Family): cordially (adv.), cordiality (n.) | Đồng nghĩa: friendly, warm · Trái nghĩa: hostile, unfriendly', '[{"hanzi":"Our new neighbours gave us a cordial welcome.","pinyin":"","meaning":"Những người hàng xóm mới đã chào đón chúng tôi một cách rất nồng hậu."},{"hanzi":"Maintaining cordial relations between neighbouring countries can encourage cooperation on trade and environmental protection.","pinyin":"","meaning":"Việc duy trì quan hệ ngoại giao hữu nghị giữa các quốc gia láng giềng có thể thúc đẩy sự hợp tác về thương mại và bảo vệ môi trường."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_11_1', 'en-c1-11', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
