INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_1_2', 'ten_c1_11_1', 'cordial', 'Our new neighbours gave us a cordial welcome.', 'Our new neighbours gave us a cordial welcome.', '/ˈkɔːrdʒəl/', 'Những người hàng xóm mới đã chào đón chúng tôi một cách rất nồng hậu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_1_3', 'ten_c1_11_1', 'revive', 'Our neighbours hope to revive the annual street party.', 'Our neighbours hope to revive the annual street party.', '/rɪˈvaɪv/', 'Những người hàng xóm của chúng tôi hy vọng sẽ khôi phục lại lễ hội đường phố thường niên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_1_4', 'ten_c1_11_1', 'arrogantly', 'He arrogantly dismissed my suggestion without even listening.', 'He arrogantly dismissed my suggestion without even listening.', '/ˈærəɡəntli/', 'Anh ta ngạo mạn bác bỏ ý kiến của tôi mà thậm chí không thèm nghe.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_1_5', 'ten_c1_11_1', 'parish', 'Our parish has a small church beside the river.', 'Our parish has a small church beside the river.', '/ˈpærɪʃ/', 'Giáo xứ của chúng tôi có một nhà thờ nhỏ nằm bên bờ sông.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_1_6', 'ten_c1_11_1', 'Marxism', 'Our reading group discussed Marxism at the library yesterday.', 'Our reading group discussed Marxism at the library yesterday.', '/ˈmɑːrksɪzəm/', 'Nhóm đọc sách của chúng tôi đã thảo luận về chủ nghĩa Mác tại thư viện ngày hôm qua.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_1_7', 'ten_c1_11_1', 'downfall', 'His refusal to listen eventually led to his downfall.', 'His refusal to listen eventually led to his downfall.', '/ˈdaʊnfɔːl/', 'Việc anh ta cố chấp không chịu lắng nghe cuối cùng đã dẫn đến sự sụp đổ của chính mình.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_1_8', 'ten_c1_11_1', 'outrage', 'Residents expressed outrage when workers cut down the ancient tree.', 'Residents expressed outrage when workers cut down the ancient tree.', '/ˈaʊtreɪdʒ/', 'Người dân đã bày tỏ sự phẫn nộ tột cùng khi các công nhân đốn hạ cây cổ thụ đó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_11_1_1', 'en-c1-11', 'ten_c1_11_1', 'listening', 'listening', 'The children formed an orderly queue outside the classroom.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhóm đọc sách của chúng tôi đã thảo luận về chủ nghĩa Mác tại thư viện ngày hôm qua.","Những người hàng xóm của chúng tôi đã gửi một lời chia buồn chân thành.","Bọn trẻ xếp thành một hàng ngay ngắn bên ngoài lớp học.","Những người hàng xóm mới đã chào đón chúng tôi một cách rất nồng hậu."]'::jsonb, 2, 'The children formed an orderly queue outside the classroom. → Bọn trẻ xếp thành một hàng ngay ngắn bên ngoài lớp học.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_11_1_2', 'en-c1-11', 'ten_c1_11_1', 'listening', 'listening', 'Our new neighbours gave us a cordial welcome.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những người hàng xóm mới đã chào đón chúng tôi một cách rất nồng hậu.","Cô ấy cầm một tấm biểu ngữ làm thủ công đi qua quảng trường đông đúc.","Bạn phải dùng lực đều tay để mở chiếc nắp này.","Bọn trẻ xếp thành một hàng ngay ngắn bên ngoài lớp học."]'::jsonb, 0, 'Our new neighbours gave us a cordial welcome. → Những người hàng xóm mới đã chào đón chúng tôi một cách rất nồng hậu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_11_1_3', 'en-c1-11', 'ten_c1_11_1', 'listening', 'listening', 'Our neighbours hope to revive the annual street party.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc anh ta cố chấp không chịu lắng nghe cuối cùng đã dẫn đến sự sụp đổ của chính mình.","Những người hàng xóm của chúng tôi hy vọng sẽ khôi phục lại lễ hội đường phố thường niên.","Chúng tôi đã nhờ một người hàng xóm công tâm đứng ra phân xử bất đồng giữa hai bên.","Người dân đã bày tỏ sự phẫn nộ tột cùng khi các công nhân đốn hạ cây cổ thụ đó."]'::jsonb, 1, 'Our neighbours hope to revive the annual street party. → Những người hàng xóm của chúng tôi hy vọng sẽ khôi phục lại lễ hội đường phố thường niên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_11_2', 'en-c1-11', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_2_1', 'ten_c1_11_2', 'orderly', 'Clear evacuation procedures help ensure an orderly departure from public buildings during emergencies, reducing the risk of injury.', 'Clear evacuation procedures help ensure an orderly departure from public buildings during emergencies, reducing the risk of injury.', '/ˈɔːrdərli/', 'Các quy trình sơ tán rõ ràng giúp đảm bảo mọi người rời khỏi các tòa nhà công cộng một cách trật tự trong các trường hợp khẩn cấp, từ đó làm giảm nguy cơ thương tích.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_2_2', 'ten_c1_11_2', 'cordial', 'Maintaining cordial relations between neighbouring countries can encourage cooperation on trade and environmental protection.', 'Maintaining cordial relations between neighbouring countries can encourage cooperation on trade and environmental protection.', '/ˈkɔːrdʒəl/', 'Việc duy trì quan hệ ngoại giao hữu nghị giữa các quốc gia láng giềng có thể thúc đẩy sự hợp tác về thương mại và bảo vệ môi trường.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_2_3', 'ten_c1_11_2', 'revive', 'Investment in public transport could revive declining town centres by making local businesses more accessible.', 'Investment in public transport could revive declining town centres by making local businesses more accessible.', '/rɪˈvaɪv/', 'Việc đầu tư vào giao thông công cộng có thể vực dậy các trung tâm thị trấn đang mai một bằng cách giúp mọi người tiếp cận các doanh nghiệp địa phương dễ dàng hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_2_4', 'ten_c1_11_2', 'arrogantly', 'Managers who behave arrogantly may discourage employees from sharing ideas that could improve workplace efficiency.', 'Managers who behave arrogantly may discourage employees from sharing ideas that could improve workplace efficiency.', '/ˈærəɡəntli/', 'Những nhà quản lý có cách hành xử ngạo mạn có thể khiến nhân viên nản lòng, không muốn đóng góp những ý tưởng giúp nâng cao hiệu quả công việc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_2_5', 'ten_c1_11_2', 'parish', 'Rural parish councils can help maintain public footpaths and protect green spaces for local residents.', 'Rural parish councils can help maintain public footpaths and protect green spaces for local residents.', '/ˈpærɪʃ/', 'Các hội đồng giáo xứ nông thôn có thể giúp duy trì các con đường đi bộ công cộng và bảo vệ không gian xanh cho người dân địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_11_2_6', 'ten_c1_11_2', 'Marxism', 'Marxism has influenced academic debates about economic inequality, ownership of resources, and the relationship between social classes.', 'Marxism has influenced academic debates about economic inequality, ownership of resources, and the relationship between social classes.', '/ˈmɑːrksɪzəm/', 'Chủ nghĩa Mác đã ảnh hưởng đến các cuộc tranh luận học thuật về bất bình đẳng kinh tế, quyền sở hữu tài nguyên và mối quan hệ giữa các giai cấp xã hội.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_11_2_1', 'en-c1-11', 'ten_c1_11_2', 'listening', 'listening', 'Clear evacuation procedures help ensure an orderly departure from public buildings during emergencies, reducing the risk of injury.', NULL, 'Trong câu vừa nghe, từ “orderly” mang nghĩa nào sau đây?', '["có trật tự; ngăn nắp; có kỷ luật","bằng máy móc; theo phương thức cơ khí","tính toán","âm ấm; hơi ấm"]'::jsonb, 0, '“orderly” (/ˈɔːrdərli/): có trật tự; ngăn nắp; có kỷ luật. Câu đầy đủ: Clear evacuation procedures help ensure an orderly departure from public buildings during emergencies, reducing the risk of injury.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_11_2_2', 'en-c1-11', 'ten_c1_11_2', 'listening', 'listening', 'Maintaining cordial relations between neighbouring countries can encourage cooperation on trade and environmental protection.', NULL, 'Trong câu vừa nghe, từ “cordial” mang nghĩa nào sau đây?', '["gợi ra; khai thác; dẫn dụ","thân thiện; nồng hậu; chân tình","kẽm","sự ô nhục; sự mất thể diện; tiếng nhơ"]'::jsonb, 1, '“cordial” (/ˈkɔːrdʒəl/): thân thiện; nồng hậu; chân tình. Câu đầy đủ: Maintaining cordial relations between neighbouring countries can encourage cooperation on trade and environmental protection.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
