INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_11_4', 'en-c1-11', 'He arrogantly dismissed my suggestion without even listening', 'Anh ta ngạo mạn bác bỏ ý kiến của tôi mà thậm chí không thèm nghe.', 'arrogantly /ˈærəɡəntli/', '["without","my","dismissed","arrogantly","listening","suggestion","even","He"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
