INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_11_6', 'en-c1-11', 'Our reading group discussed Marxism at the library yesterday', 'Nhóm đọc sách của chúng tôi đã thảo luận về chủ nghĩa Mác tại thư viện ngày hôm qua.', 'Marxism /ˈmɑːrksɪzəm/', '["library","at","discussed","group","yesterday","Our","the","reading","Marxism"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_11_7', 'en-c1-11', 'His refusal to listen eventually led to his downfall', 'Việc anh ta cố chấp không chịu lắng nghe cuối cùng đã dẫn đến sự sụp đổ của chính mình.', 'downfall /ˈdaʊnfɔːl/', '["led","eventually","his","refusal","to","His","listen","downfall","to"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_11_8', 'en-c1-11', 'Residents expressed outrage when workers cut down the ancient tree', 'Người dân đã bày tỏ sự phẫn nộ tột cùng khi các công nhân đốn hạ cây cổ thụ đó.', 'outrage /ˈaʊtreɪdʒ/', '["ancient","Residents","expressed","the","when","cut","outrage","down","tree","workers"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_11_9', 'en-c1-11', 'They heard our plea for help and stopped immediately', 'Họ đã nghe thấy tiếng kêu cứu tha thiết của chúng tôi và lập tức dừng lại.', 'plea /pliː/', '["They","stopped","immediately","our","and","heard","for","plea","help"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
