INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_1', 'en-c1-11', NULL, 'comprehensive_test', 'listening', 'orderly', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có trật tự; ngăn nắp; có kỷ luật","mãn tính","công chứng viên","có xu hướng; dễ bị mắc phải"]'::jsonb, 0, 'orderly (/ˈɔːrdərli/) → có trật tự; ngăn nắp; có kỷ luật; nhân viên hộ lý bệnh viện; binh sĩ phục vụ cấp trên', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_2', 'en-c1-11', NULL, 'comprehensive_test', 'listening', 'Our new neighbours gave us a cordial welcome.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những người hàng xóm mới đã chào đón chúng tôi một cách rất nồng hậu.","Bộ phim tài liệu đã giải thích nạn buôn lậu đang đẩy các loài động vật quý hiếm vào tình thế nguy hiểm như thế nào.","Việc anh ta cố chấp không chịu lắng nghe cuối cùng đã dẫn đến sự sụp đổ của chính mình.","Giáo xứ của chúng tôi có một nhà thờ nhỏ nằm bên bờ sông."]'::jsonb, 0, 'Our new neighbours gave us a cordial welcome. → Những người hàng xóm mới đã chào đón chúng tôi một cách rất nồng hậu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_3', 'en-c1-11', NULL, 'comprehensive_test', 'listening', 'revive', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm sống lại; khôi phục lại","tương tự; có thể so sánh được","vẻ hùng vĩ; sự tráng lệ; sự uy nghiêm","miệng (cốc, bát, hoặc vật chứa khác)"]'::jsonb, 0, 'revive (/rɪˈvaɪv/) → làm sống lại; khôi phục lại; làm tỉnh lại; hồi sức', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_4', 'en-c1-11', NULL, 'comprehensive_test', 'listening', 'He arrogantly dismissed my suggestion without even listening.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cơn mưa lớn không làm chùn bước những nhà leo núi quyết tâm của chúng tôi.","Anh ta ngạo mạn bác bỏ ý kiến của tôi mà thậm chí không thèm nghe.","Giáo xứ của chúng tôi có một nhà thờ nhỏ nằm bên bờ sông.","Bạn phải dùng lực đều tay để mở chiếc nắp này."]'::jsonb, 1, 'He arrogantly dismissed my suggestion without even listening. → Anh ta ngạo mạn bác bỏ ý kiến của tôi mà thậm chí không thèm nghe.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_5', 'en-c1-11', NULL, 'comprehensive_test', 'listening', 'parish', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xứ đạo; giáo xứ","sự sửa đổi; điều khoản bổ sung; bản sửa đổi","cả tin; dễ bị lừa","làm mất hiệu lực; làm cho vô hiệu"]'::jsonb, 0, 'parish (/ˈpærɪʃ/) → xứ đạo; giáo xứ; giáo dân trong xứ đạo', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_6', 'en-c1-11', NULL, 'comprehensive_test', 'listening', 'Our reading group discussed Marxism at the library yesterday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người dân đã bày tỏ sự phẫn nộ tột cùng khi các công nhân đốn hạ cây cổ thụ đó.","Bạn phải dùng lực đều tay để mở chiếc nắp này.","Nhóm đọc sách của chúng tôi đã thảo luận về chủ nghĩa Mác tại thư viện ngày hôm qua.","Cô ấy cầm một tấm biểu ngữ làm thủ công đi qua quảng trường đông đúc."]'::jsonb, 2, 'Our reading group discussed Marxism at the library yesterday. → Nhóm đọc sách của chúng tôi đã thảo luận về chủ nghĩa Mác tại thư viện ngày hôm qua.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_7', 'en-c1-11', NULL, 'comprehensive_test', 'listening', 'downfall', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc chủ nghĩa Mác","thực vật; thảm thực vật","sự sụp đổ; sự suy sụp (về quyền lực, thành công hoặc địa vị xã hội)","bóp méo; xuyên tạc"]'::jsonb, 2, 'downfall (/ˈdaʊnfɔːl/) → sự sụp đổ; sự suy sụp (về quyền lực, thành công hoặc địa vị xã hội); nguyên nhân thất bại; nguồn gốc sụp đổ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_8', 'en-c1-11', NULL, 'comprehensive_test', 'listening', 'Residents expressed outrage when workers cut down the ancient tree.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc giành giải thưởng đã mang lại uy tín đáng kể cho tiệm bánh nhỏ của cô ấy.","Chiếc thang trông có vẻ chênh vênh trên nền đất ướt và gồ ghề.","Người dân đã bày tỏ sự phẫn nộ tột cùng khi các công nhân đốn hạ cây cổ thụ đó.","Chúng tôi đã nhờ một người hàng xóm công tâm đứng ra phân xử bất đồng giữa hai bên."]'::jsonb, 2, 'Residents expressed outrage when workers cut down the ancient tree. → Người dân đã bày tỏ sự phẫn nộ tột cùng khi các công nhân đốn hạ cây cổ thụ đó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_9', 'en-c1-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A local church district, or a small administrative area.”?', '["salutation","placard","parish","plea"]'::jsonb, 2, 'parish (/ˈpærɪʃ/) → xứ đạo; giáo xứ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_10', 'en-c1-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Marx''s theories concerning class conflict, capitalism, and a classless society.”?', '["cordial","Marxism","impartial","candid"]'::jsonb, 1, 'Marxism (/ˈmɑːrksɪzəm/) → chủ nghĩa Mác', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_11', 'en-c1-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The loss of power, success, or social position.”?', '["placard","downfall","impartial","salutation"]'::jsonb, 1, 'downfall (/ˈdaʊnfɔːl/) → sự sụp đổ; sự suy sụp (về quyền lực, thành công hoặc địa vị xã hội)', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
