INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_18', 'en-c1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Clear evacuation procedures help ensure an orderly departure from public buildings during emergencies, reducing the risk of injury.', 'Dựa vào câu trên, từ “orderly” có nghĩa phù hợp nhất là gì?', '["phần còn lại; di tích","là ví dụ điển hình cho; minh họa bằng ví dụ","cúi xuống; rủ xuống","có trật tự; ngăn nắp; có kỷ luật"]'::jsonb, 3, 'orderly: có trật tự; ngăn nắp; có kỷ luật; nhân viên hộ lý bệnh viện; binh sĩ phục vụ cấp trên. Dịch cả câu: Các quy trình sơ tán rõ ràng giúp đảm bảo mọi người rời khỏi các tòa nhà công cộng một cách trật tự trong các trường hợp khẩn cấp, từ đó làm giảm nguy cơ thương tích.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_19', 'en-c1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Maintaining cordial relations between neighbouring countries can encourage cooperation on trade and environmental protection.', 'Dựa vào câu trên, từ “cordial” có nghĩa phù hợp nhất là gì?', '["vô cực; vô tận","nhân (hạt); hạt (ngũ cốc)","tinh thần thể thao; tác phong thể thao","thân thiện; nồng hậu; chân tình"]'::jsonb, 3, 'cordial: thân thiện; nồng hậu; chân tình; nước trái cây cô đặc. Dịch cả câu: Việc duy trì quan hệ ngoại giao hữu nghị giữa các quốc gia láng giềng có thể thúc đẩy sự hợp tác về thương mại và bảo vệ môi trường.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_20', 'en-c1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in public transport could revive declining town centres by making local businesses more accessible.', 'Dựa vào câu trên, từ “revive” có nghĩa phù hợp nhất là gì?', '["lời mở đầu; khúc dạo đầu; bước đệm (sự việc xảy ra trước và dẫn dắt cho một sự kiện quan trọng hơn)","làm sống lại; khôi phục lại","hình dung; vạch ra; dự tính (một tình huống hoặc sự kiện có thể xảy ra trong tương lai)","giếng (thang máy, thông gió); đường hầm thẳng đứng"]'::jsonb, 1, 'revive: làm sống lại; khôi phục lại; làm tỉnh lại; hồi sức. Dịch cả câu: Việc đầu tư vào giao thông công cộng có thể vực dậy các trung tâm thị trấn đang mai một bằng cách giúp mọi người tiếp cận các doanh nghiệp địa phương dễ dàng hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_21', 'en-c1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Managers who behave arrogantly may discourage employees from sharing ideas that could improve workplace efficiency.', 'Dựa vào câu trên, từ “arrogantly” có nghĩa phù hợp nhất là gì?', '["hải quân; thủy thủ; hải đăng","một cách ngạo mạn; kiêu ngạo","mũi đất; hải vạn","làm liệt; làm bại liệt"]'::jsonb, 1, 'arrogantly: một cách ngạo mạn; kiêu ngạo. Dịch cả câu: Những nhà quản lý có cách hành xử ngạo mạn có thể khiến nhân viên nản lòng, không muốn đóng góp những ý tưởng giúp nâng cao hiệu quả công việc.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_22', 'en-c1-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “song tính; lưỡng tính”', '["disadvantageous","bi","grit","materialism"]'::jsonb, 1, 'song tính; lưỡng tính → bi (/baɪ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_23', 'en-c1-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sức gắn kết; sự đoàn kết”', '["defective","cohesion","domain","drunkard"]'::jsonb, 1, 'sức gắn kết; sự đoàn kết → cohesion (/koʊˈhiːʒən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_11_24', 'en-c1-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự cạnh tranh; sự ganh đua”', '["ore","solvent","subsidy","rivalry"]'::jsonb, 3, 'sự cạnh tranh; sự ganh đua → rivalry (/ˈraɪvəlri/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-12', 'en', 'Bài 12: Xã hội & Cộng đồng (7) - CEFR C1', 'CEFR C1', 'C1 · Xã hội', '27 từ vựng Tiếng Anh CEFR C1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5012, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_humanitarian', 'en-c1-12', 'humanitarian', '/hjuːˌmænɪˈteriən/', 'C1', 'mang tính nhân đạo; nhà nhân đạo chủ nghĩa', 'adj.', 'humanitarianism (n.), humanity (n.)', NULL, 'Nhấn mạnh việc xoa dịu nỗi đau của con người, không đồng nghĩa với sự hào phóng thông thường.', 'Volunteers packed blankets and medicine for the humanitarian mission.', NULL, 'Các tình nguyện viên đã đóng gói chăn màn và thuốc men cho sứ mệnh nhân đạo.', '{"wordId":"humanitarian","ukIpa":"/hjuːˌmænɪˈteəriən/","usIpa":"/hjuːˌmænɪˈteriən/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Concerned with reducing suffering and improving people''s lives.","vi":"mang tính nhân đạo"},{"pos":"n.","en":"Someone who works to reduce suffering and improve human welfare.","vi":"nhà nhân đạo chủ nghĩa"}],"examples":[{"en":"Volunteers packed blankets and medicine for the humanitarian mission.","vi":"Các tình nguyện viên đã đóng gói chăn màn và thuốc men cho sứ mệnh nhân đạo.","audioKind":"ex"},{"en":"International humanitarian organisations provide essential supplies to communities affected by natural disasters and armed conflict.","vi":"Các tổ chức nhân đạo quốc tế cung cấp các nhu yếu phẩm thiết yếu cho các cộng đồng bị ảnh hưởng bởi thiên tai và xung đột vũ trang.","audioKind":"ex2"}],"collocations":[{"en":"humanitarian aid","vi":"viện trợ nhân đạo"},{"en":"humanitarian crisis","vi":"khủng hoảng nhân đạo"},{"en":"humanitarian grounds","vi":"lý do nhân đạo"}],"wordFamily":["humanitarianism (n.)","humanity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh việc xoa dịu nỗi đau của con người, không đồng nghĩa với sự hào phóng thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conspicuous', 'en-c1-12', 'conspicuous', '/kənˈspɪkjuəs/', 'C1', 'dễ thấy; nổi bật; đập ngay vào mắt', 'adj.', 'conspicuously (adv.), inconspicuous (adj.)', 'Đồng nghĩa: noticeable, prominent, striking · Trái nghĩa: inconspicuous', 'Nhấn mạnh dễ được chú ý, không nhất thiết biểu thị tầm quan trọng.', 'Her yellow umbrella was conspicuous among the black ones.', NULL, 'Chiếc ô màu vàng của cô ấy rất nổi bật giữa những chiếc ô màu đen.', '{"wordId":"conspicuous","ukIpa":"/kənˈspɪkjuəs/","usIpa":"/kənˈspɪkjuəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"easy to notice because of being unusual or different","vi":"dễ thấy; nổi bật; đập ngay vào mắt"}],"examples":[{"en":"Her yellow umbrella was conspicuous among the black ones.","vi":"Chiếc ô màu vàng của cô ấy rất nổi bật giữa những chiếc ô màu đen.","audioKind":"ex"},{"en":"Conspicuous consumption can encourage unnecessary spending as people seek to display their wealth through expensive possessions.","vi":"Tiêu dùng phô trương có thể cổ súy cho những khoản chi tiêu không cần thiết khi mọi người tìm cách thể hiện sự giàu có thông qua các món đồ đắt tiền.","audioKind":"ex2"}],"collocations":[{"en":"conspicuous consumption","vi":"tiêu dùng phô trương"},{"en":"a conspicuous place","vi":"một vị trí dễ thấy"},{"en":"conspicuous by its absence","vi":"nổi bật vì vắng mặt"}],"wordFamily":["conspicuously (adv.)","inconspicuous (adj.)"],"synonyms":["noticeable","prominent","striking"],"antonyms":["inconspicuous"],"tipVi":"Nhấn mạnh dễ được chú ý, không nhất thiết biểu thị tầm quan trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hijack', 'en-c1-12', 'hijack', '/ˈhaɪdʒæk/', 'C1', 'khống chế; cướp (phương tiện giao thông); thao túng; chiếm đoạt (cho mục đích riêng)', 'v.', 'hijacker (n.), hijacking (n.)', NULL, 'Nghĩa gốc là cướp phương tiện; cũng có thể dùng theo nghĩa bóng để chỉ việc thao túng thảo luận hoặc chương trình nghị sự.', 'One guest hijacked the conversation to discuss his own problems.', NULL, 'Một vị khách đã lái chuyển hướng câu chuyện sang các vấn đề của riêng anh ta.', '{"wordId":"hijack","ukIpa":"/ˈhaɪdʒæk/","usIpa":"/ˈhaɪdʒæk/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to illegally seize control of a vehicle during a journey","vi":"khống chế; cướp (phương tiện giao thông)"},{"pos":"v.","en":"to take control of something for your own purposes","vi":"thao túng; chiếm đoạt (cho mục đích riêng)"}],"examples":[{"en":"One guest hijacked the conversation to discuss his own problems.","vi":"Một vị khách đã lái chuyển hướng câu chuyện sang các vấn đề của riêng anh ta.","audioKind":"ex"},{"en":"Powerful interest groups may hijack public debates, preventing communities from discussing their most urgent concerns.","vi":"Các nhóm lợi ích hùng mạnh có thể thao túng các cuộc tranh luận công khai, khiến các cộng đồng không thể thảo luận về các vấn đề cấp bách nhất của họ.","audioKind":"ex2"}],"collocations":[{"en":"hijack a plane","vi":"không chế một chiếc máy bay"},{"en":"hijack a debate","vi":"thao túng một cuộc tranh luận"},{"en":"hijack the conversation","vi":"chiếm đoạt cuộc trò chuyện"}],"wordFamily":["hijacker (n.)","hijacking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa gốc là cướp phương tiện; cũng có thể dùng theo nghĩa bóng để chỉ việc thao túng thảo luận hoặc chương trình nghị sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unprecedented', 'en-c1-12', 'unprecedented', '/ʌnˈpresɪdentɪd/', 'C1', 'chưa từng có; chưa từng tồn tại trước đây', 'adj.', 'precedent (n.), precedented (adj.)', 'Đồng nghĩa: unheard-of', 'Nhấn mạnh việc chưa từng xảy ra trước đây, không chỉ là mức độ lớn hoặc hiếm gặp.', 'The bakery received an unprecedented flood of orders today.', NULL, 'Tiệm bánh đã nhận được một lượng đơn hàng lớn chưa từng có vào ngày hôm nay.', '{"wordId":"unprecedented","ukIpa":"/ʌnˈpresɪdentɪd/","usIpa":"/ʌnˈpresɪdentɪd/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Never having happened or existed before.","vi":"chưa từng có; chưa từng tồn tại trước đây"}],"examples":[{"en":"The bakery received an unprecedented flood of orders today.","vi":"Tiệm bánh đã nhận được một lượng đơn hàng lớn chưa từng có vào ngày hôm nay.","audioKind":"ex"},{"en":"Many coastal communities face unprecedented challenges as rising sea levels threaten homes, infrastructure, and local livelihoods.","vi":"Nhiều cộng đồng ven biển phải đối mặt với những thách thức chưa từng có khi mực nước biển dâng cao đe dọa nhà ở, cơ sở hạ tầng và sinh kế của người dân.","audioKind":"ex2"}],"collocations":[{"en":"unprecedented growth","vi":"sự tăng trưởng chưa từng có"},{"en":"on an unprecedented scale","vi":"ở quy mô chưa từng có"},{"en":"unprecedented challenges","vi":"những thách thức chưa từng có"}],"wordFamily":["precedent (n.)","precedented (adj.)"],"synonyms":["unheard-of"],"antonyms":[],"tipVi":"Nhấn mạnh việc chưa từng xảy ra trước đây, không chỉ là mức độ lớn hoặc hiếm gặp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delinquency', 'en-c1-12', 'delinquency', '/dɪˈlɪŋkwənsi/', 'C1', 'hành vi vi phạm pháp luật hoặc không chuẩn mực, đặc biệt ở giới trẻ; việc chậm thanh toán khoản tiền bắt buộc', 'n.', 'delinquent (adj.), delinquent (n.)', NULL, 'Thường gặp trong cụm juvenile delinquency, không dùng để chỉ các lỗi lầm thông thường.', 'Our youth club helps teenagers stay away from delinquency.', NULL, 'Câu lạc bộ thanh thiếu niên của chúng tôi giúp các em tránh xa các hành vi phạm pháp.', '{"wordId":"delinquency","ukIpa":"/dɪˈlɪŋkwənsi/","usIpa":"/dɪˈlɪŋkwənsi/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"illegal or unacceptable behaviour, especially by young people","vi":"hành vi vi phạm pháp luật hoặc không chuẩn mực, đặc biệt ở giới trẻ"},{"pos":"n.","en":"failure to make a required payment on time","vi":"việc chậm thanh toán khoản tiền bắt buộc"}],"examples":[{"en":"Our youth club helps teenagers stay away from delinquency.","vi":"Câu lạc bộ thanh thiếu niên của chúng tôi giúp các em tránh xa các hành vi phạm pháp.","audioKind":"ex"},{"en":"Affordable recreational facilities and supportive mentoring programmes may help reduce juvenile delinquency in disadvantaged neighbourhoods.","vi":"Các cơ sở giải trí giá cả phải chăng và các chương trình cố vấn hỗ trợ có thể giúp giảm thiểu tình trạng phạm pháp vị thành niên ở các khu vực có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"juvenile delinquency","vi":"tội phạm vị thành niên"},{"en":"prevent delinquency","vi":"phòng ngừa hành vi vi phạm"},{"en":"loan delinquency","vi":"nợ quá hạn"}],"wordFamily":["delinquent (adj.)","delinquent (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường gặp trong cụm juvenile delinquency, không dùng để chỉ các lỗi lầm thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slaughter', 'en-c1-12', 'slaughter', '/ˈslɔːtər/', 'C1', 'giết mổ; làm thịt; việc giết mổ (động vật), cuộc thảm sát; tàn sát; thảm sát', 'v.', 'slaughterhouse (n.)', 'Đồng nghĩa: kill', 'Chỉ việc giết mổ động vật hoặc tàn sát dã man, sắc thái mạnh; không dùng cho cái chết thông thường.', 'The farmer explained why some animals are slaughtered for food.', NULL, 'Người nông dân giải thích lý do tại sao một số loài động vật bị giết mổ để lấy thịt.', '{"wordId":"slaughter","ukIpa":"/ˈslɔːtə/","usIpa":"/ˈslɔːtər/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To kill animals, usually for food","vi":"giết mổ; làm thịt"},{"pos":"n.","en":"The killing of animals for food, or many people cruelly","vi":"việc giết mổ (động vật), cuộc thảm sát"},{"pos":"v.","en":"To kill many people cruelly, especially those unable to defend themselves","vi":"tàn sát; thảm sát"}],"examples":[{"en":"The farmer explained why some animals are slaughtered for food.","vi":"Người nông dân giải thích lý do tại sao một số loài động vật bị giết mổ để lấy thịt.","audioKind":"ex"},{"en":"Strict regulations on how animals are slaughtered can improve welfare standards throughout the food production industry.","vi":"Các quy định nghiêm ngặt về cách thức giết mổ động vật có thể nâng cao tiêu chuẩn phúc lợi trong toàn ngành sản xuất thực phẩm.","audioKind":"ex2"}],"collocations":[{"en":"slaughter animals","vi":"giết mổ động vật"},{"en":"slaughter for food","vi":"giết mổ làm thực phẩm"},{"en":"mass slaughter","vi":"cuộc thảm sát lớn"}],"wordFamily":["slaughterhouse (n.)"],"synonyms":["kill"],"antonyms":[],"tipVi":"Chỉ việc giết mổ động vật hoặc tàn sát dã man, sắc thái mạnh; không dùng cho cái chết thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ration', 'en-c1-12', 'ration', '/ˈræʃən/', 'C1', 'phần định lượng; khẩu phần; cấp định lượng; phân phối theo định mức', 'n.', 'rationing (n.)', 'Đồng nghĩa: allocation, allotment', 'Khi dùng làm động từ, có thể dùng ration someone to để chỉ việc giới hạn định mức cho ai.', 'Each hiker packed a daily ration of nuts and dried fruit.', NULL, 'Mỗi người leo núi mang theo một phần hạt và trái cây sấy khô đủ dùng cho một ngày.', '{"wordId":"ration","ukIpa":"/ˈræʃən/","usIpa":"/ˈræʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A fixed amount of food or supplies allowed to someone.","vi":"phần định lượng; khẩu phần"},{"pos":"v.","en":"To limit how much of something each person can have.","vi":"cấp định lượng; phân phối theo định mức"}],"examples":[{"en":"Each hiker packed a daily ration of nuts and dried fruit.","vi":"Mỗi người leo núi mang theo một phần hạt và trái cây sấy khô đủ dùng cho một ngày.","audioKind":"ex"},{"en":"During prolonged droughts, local authorities may ration water to ensure that every household receives an adequate supply.","vi":"Trong thời kỳ hạn hán kéo dài, chính quyền địa phương có thể phân phối nước theo định mức để đảm bảo mọi hộ gia đình đều nhận đủ lượng nước cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"a daily ration","vi":"khẩu phần hằng ngày"},{"en":"food rations","vi":"khẩu phần lương thực"},{"en":"ration water","vi":"phân phối nước theo định mức"}],"wordFamily":["rationing (n.)"],"synonyms":["allocation","allotment"],"antonyms":[],"tipVi":"Khi dùng làm động từ, có thể dùng ration someone to để chỉ việc giới hạn định mức cho ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_virtue', 'en-c1-12', 'virtue', '/ˈvɝːtʃuː/', 'C1', 'hạnh kiểm; phẩm chất đạo đức tốt; ưu điểm; tính năng tốt', 'n.', 'virtuous (adj.), virtuously (adv.)', 'Đồng nghĩa: goodness, merit · Trái nghĩa: vice', 'by virtue of ý nghĩa là nhờ vào hoặc do, không liên quan đến nghĩa mỹ đức.', 'My grandfather always said that patience was a virtue.', NULL, 'Ông tôi vẫn thường nói rằng sự kiên nhẫn là một đức tính cao đẹp.', '{"wordId":"virtue","ukIpa":"/ˈvɜːtʃuː/","usIpa":"/ˈvɝːtʃuː/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A morally good quality or morally good behaviour.","vi":"hạnh kiểm; phẩm chất đạo đức tốt"},{"pos":"n.","en":"A useful or desirable quality of something.","vi":"ưu điểm; tính năng tốt"}],"examples":[{"en":"My grandfather always said that patience was a virtue.","vi":"Ông tôi vẫn thường nói rằng sự kiên nhẫn là một đức tính cao đẹp.","audioKind":"ex"},{"en":"One virtue of public transport is its ability to move large numbers of people using relatively little space.","vi":"Một ưu điểm của giao thông công cộng là khả năng vận chuyển lượng lớn hành khách mà tốn tương đối ít diện tích.","audioKind":"ex2"}],"collocations":[{"en":"moral virtue","vi":"đạo đức phẩm hạnh"},{"en":"the virtues of","vi":"ưu điểm của"},{"en":"by virtue of","vi":"bởi vì; nhờ có"}],"wordFamily":["virtuous (adj.)","virtuously (adv.)"],"synonyms":["goodness","merit"],"antonyms":["vice"],"tipVi":"by virtue of ý nghĩa là nhờ vào hoặc do, không liên quan đến nghĩa mỹ đức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deception', 'en-c1-12', 'deception', '/dɪˈsepʃən/', 'C1', 'hành vi lừa dối; thủ đoạn đánh lừa', 'n.', 'deceive (v.), deceptive (adj.), deceptively (adv.)', 'Đồng nghĩa: deceit, trickery · Trái nghĩa: honesty', 'Từ deception nhấn mạnh việc cố ý làm cho người khác tin là thật, không phải lỗi lầm thông thường.', 'Her cheerful smile hid her disappointment, a small deception.', NULL, 'Nụ cười tươi vui của cô ấy đã che giấu sự thất vọng, một sự che đậy nhỏ.', '{"wordId":"deception","ukIpa":"/dɪˈsepʃən/","usIpa":"/dɪˈsepʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"the act of deliberately making someone believe something false","vi":"hành vi lừa dối; thủ đoạn đánh lừa"}],"examples":[{"en":"Her cheerful smile hid her disappointment, a small deception.","vi":"Nụ cười tươi vui của cô ấy đã che giấu sự thất vọng, một sự che đậy nhỏ.","audioKind":"ex"},{"en":"Clear advertising regulations can protect consumers from deception and encourage greater trust in online markets.","vi":"Quy định quảng cáo rõ ràng có thể bảo vệ người tiêu dùng khỏi sự lừa dối và thúc đẩy niềm tin lớn hơn vào thị trường trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"deliberate deception","vi":"deliberate deception -> hành vi lừa dối có chủ đích"},{"en":"practise deception","vi":"practise deception -> thực hiện hành vi lừa dối"},{"en":"an act of deception","vi":"an act of deception -> hành vi lừa gạt"}],"wordFamily":["deceive (v.)","deceptive (adj.)","deceptively (adv.)"],"synonyms":["deceit","trickery"],"antonyms":["honesty"],"tipVi":"Từ deception nhấn mạnh việc cố ý làm cho người khác tin là thật, không phải lỗi lầm thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outcast', 'en-c1-12', 'outcast', '/ˈaʊtkæst/', 'C1', 'người bị xã hội hắt hủi; người bị gạt ra bên lề; bị ruồng bỏ; bị hắt hủi', 'n.', NULL, NULL, 'Chủ yếu dùng làm danh từ chỉ người bị xa lánh, không đồng nghĩa với người lang thang hay kẻ vô lại.', 'After the argument, he felt like an outcast.', NULL, 'Sau cuộc tranh cãi, anh ấy cảm thấy mình như một kẻ bị hắt hủi.', '{"wordId":"outcast","ukIpa":"/ˈaʊtkɑːst/","usIpa":"/ˈaʊtkæst/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Someone rejected and excluded by a group or society.","vi":"người bị xã hội hắt hủi; người bị gạt ra bên lề"},{"pos":"adj.","en":"Rejected and excluded by other people.","vi":"bị ruồng bỏ; bị hắt hủi"}],"examples":[{"en":"After the argument, he felt like an outcast.","vi":"Sau cuộc tranh cãi, anh ấy cảm thấy mình như một kẻ bị hắt hủi.","audioKind":"ex"},{"en":"Schools should ensure that no child becomes an outcast because of their background or appearance.","vi":"Các trường học nên đảm bảo rằng không có đứa trẻ nào bị biến thành kẻ ngoại lệ chỉ vì hoàn cảnh hoặc ngoại hình của chúng.","audioKind":"ex2"}],"collocations":[{"en":"a social outcast","vi":"kẻ bị xã hội ruồng bỏ"},{"en":"feel like an outcast","vi":"cảm thấy bị hắt hủi"},{"en":"treat someone as an outcast","vi":"đối xử với ai như kẻ ngoài lề"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu dùng làm danh từ chỉ người bị xa lánh, không đồng nghĩa với người lang thang hay kẻ vô lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_summon', 'en-c1-12', 'summon', '/ˈsʌmən/', 'C1', 'triệu tập; gọi đến; yêu cầu có mặt; gợi lên; củng cố; lấy hết (dũng khí, sức mạnh)', 'v.', NULL, 'Đồng nghĩa: call', 'summon sb to một địa điểm nào đó; summon up courage nghĩa là lấy hết can đảm.', 'The manager summoned everyone to her office after lunch.', NULL, 'Người quản lý đã triệu tập mọi người vào văn phòng của cô ấy sau bữa trưa.', '{"wordId":"summon","ukIpa":"/ˈsʌmən/","usIpa":"/ˈsʌmən/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To officially order someone to come or request their presence.","vi":"triệu tập; gọi đến; yêu cầu có mặt"},{"pos":"v.","en":"To gather the courage, strength, or energy needed for something.","vi":"gợi lên; củng cố; lấy hết (dũng khí, sức mạnh)"}],"examples":[{"en":"The manager summoned everyone to her office after lunch.","vi":"Người quản lý đã triệu tập mọi người vào văn phòng của cô ấy sau bữa trưa.","audioKind":"ex"},{"en":"Governments must summon the political will to address environmental problems despite opposition from powerful industries.","vi":"Các chính phủ phải huy động ý chí chính trị để giải quyết các vấn đề môi trường bất chấp sự phản đối từ các ngành công nghiệp hùng mạnh.","audioKind":"ex2"}],"collocations":[{"en":"summon someone to court","vi":"triệu tập ai ra tòa"},{"en":"summon help","vi":"gọi người đến giúp đỡ"},{"en":"summon up courage","vi":"lấy hết dũng khí"}],"wordFamily":[],"synonyms":["call"],"antonyms":[],"tipVi":"summon sb to một địa điểm nào đó; summon up courage nghĩa là lấy hết can đảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acknowledgment', 'en-c1-12', 'acknowledgment', '/əkˈnɑːlɪdʒmənt/', 'C1', 'sự công nhận; sự thừa nhận; lời cảm ơn; sự tri ân; thông báo đã nhận; giấy biên nhận', 'n.', 'acknowledge (v.), acknowledged (adj.)', 'Đồng nghĩa: recognition, admission, confirmation · Trái nghĩa: denial', 'Tiếng Anh Anh thường viết là "acknowledgement"; các nghĩa thường đi kèm với giới từ "of".', 'He nodded in acknowledgment of his sister''s helpful suggestion.', NULL, 'Anh ấy gật đầu để tỏ ý ghi nhận gợi ý hữu ích từ chị gái mình.', '{"wordId":"acknowledgment","ukIpa":"/əkˈnɒlɪdʒmənt/","usIpa":"/əkˈnɑːlɪdʒmənt/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Acceptance that something is true or that someone''s contribution matters.","vi":"sự công nhận; sự thừa nhận"},{"pos":"n.","en":"An expression of thanks for help or support.","vi":"lời cảm ơn; sự tri ân"},{"pos":"n.","en":"A message confirming that something has been received.","vi":"thông báo đã nhận; giấy biên nhận"}],"examples":[{"en":"He nodded in acknowledgment of his sister''s helpful suggestion.","vi":"Anh ấy gật đầu để tỏ ý ghi nhận gợi ý hữu ích từ chị gái mình.","audioKind":"ex"},{"en":"Public acknowledgment of past mistakes can help institutions rebuild trust and strengthen their relationships with local communities.","vi":"Việc công khai thừa nhận những sai lầm trong quá khứ có thể giúp các tổ chức xây dựng lại lòng tin và củng cố mối quan hệ với cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"in acknowledgment of","vi":"để ghi nhận; nhằm bày tỏ sự biết ơn"},{"en":"acknowledgment of receipt","vi":"xác nhận đã nhận"},{"en":"public acknowledgment","vi":"sự công nhận từ công chúng"},{"en":"an acknowledgment of support","vi":"lời cảm ơn sự hỗ trợ"}],"wordFamily":["acknowledge (v.)","acknowledged (adj.)"],"synonyms":["recognition","admission","confirmation"],"antonyms":["denial"],"tipVi":"Tiếng Anh Anh thường viết là \"acknowledgement\"; các nghĩa thường đi kèm với giới từ \"of\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_integrity', 'en-c1-12', 'integrity', '/ɪnˈteɡrəti/', 'C1', 'sự chính trực; tính trung thực và tuân thủ các nguyên tắc đạo đức vững chắc; tính nguyên vẹn; trạng thái toàn vẹn, không bị hư hại hoặc thay đổi', 'n.', NULL, 'Đồng nghĩa: honesty, uprightness · Trái nghĩa: dishonesty', 'Là danh từ không đếm được; vừa dùng để chỉ sự chính trực của con người, vừa chỉ tính nguyên vẹn của kết cấu vật chất.', 'She showed integrity by returning the money she found.', NULL, 'Cô ấy thể hiện phẩm chất chính trực bằng cách trả lại số tiền nhặt được.', '{"wordId":"integrity","ukIpa":"/ɪnˈteɡrəti/","usIpa":"/ɪnˈteɡrəti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"the quality of being honest and following strong moral principles","vi":"sự chính trực; tính trung thực và tuân thủ các nguyên tắc đạo đức vững chắc"},{"pos":"n.","en":"the condition of being whole, undamaged, or unchanged","vi":"tính nguyên vẹn; trạng thái toàn vẹn, không bị hư hại hoặc thay đổi"}],"examples":[{"en":"She showed integrity by returning the money she found.","vi":"Cô ấy thể hiện phẩm chất chính trực bằng cách trả lại số tiền nhặt được.","audioKind":"ex"},{"en":"Independent inspections help maintain the structural integrity of bridges and protect the public from preventable accidents.","vi":"Các cuộc kiểm tra độc lập giúp duy trì tính toàn vẹn kết cấu của cầu đường và bảo vệ công chúng khỏi những tai nạn có thể phòng ngừa.","audioKind":"ex2"}],"collocations":[{"en":"personal integrity","vi":"phẩm chất cá nhân"},{"en":"professional integrity","vi":"tính chuyên nghiệp"},{"en":"structural integrity","vi":"tính toàn vẹn kết cấu"}],"wordFamily":[],"synonyms":["honesty","uprightness"],"antonyms":["dishonesty"],"tipVi":"Là danh từ không đếm được; vừa dùng để chỉ sự chính trực của con người, vừa chỉ tính nguyên vẹn của kết cấu vật chất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_patriotism', 'en-c1-12', 'patriotism', '/ˈpeɪtriətɪzəm/', 'C1', 'lòng yêu nước; tinh thần ái quốc', 'n.', 'patriot (n.), patriotic (adj.), patriotically (adv.)', NULL, 'Nhấn mạnh tình cảm yêu nước, không nên đồng nhất hoàn toàn với "nationalism" (chủ nghĩa dân tộc).', 'Her patriotism shines through whenever she discusses her country''s achievements.', NULL, 'Lòng yêu nước của cô ấy tỏa sáng mỗi khi cô nhắc đến những thành tựu của đất nước mình.', '{"wordId":"patriotism","ukIpa":"/ˈpætriətɪzəm/","usIpa":"/ˈpeɪtriətɪzəm/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Love for and loyalty to your country.","vi":"lòng yêu nước; tinh thần ái quốc"}],"examples":[{"en":"Her patriotism shines through whenever she discusses her country''s achievements.","vi":"Lòng yêu nước của cô ấy tỏa sáng mỗi khi cô nhắc đến những thành tựu của đất nước mình.","audioKind":"ex"},{"en":"Schools can encourage patriotism while also teaching students to respect other nations and understand global responsibilities.","vi":"Các trường học có thể khơi dậy lòng yêu nước đồng thời dạy học sinh tôn trọng các quốc gia khác và thấu hiểu trách nhiệm toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"a sense of patriotism","vi":"tinh thần yêu nước"},{"en":"express patriotism","vi":"thể hiện lòng yêu nước"},{"en":"inspire patriotism","vi":"truyền cảm hứng yêu nước"}],"wordFamily":["patriot (n.)","patriotic (adj.)","patriotically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh tình cảm yêu nước, không nên đồng nhất hoàn toàn với \"nationalism\" (chủ nghĩa dân tộc).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preach', 'en-c1-12', 'preach', '/priːtʃ/', 'C1', 'giảng đạo; thuyết giáo; tuyên truyền; nhiệt tình ủng hộ hoặc vận động cho một tư tưởng; lên lớp; đưa ra những lời khuyên đạo đức sáo rỗng khó chịu', 'v.', 'preacher (n.), preaching (n.), preachy (adj.)', 'Đồng nghĩa: advocate, moralize', 'Cấu trúc "preach to someone" thường mang sắc thái chê bai là "lên lớp, dạy đời ai đó".', 'The minister preached about kindness at the morning service.', NULL, 'Mục sư đã giảng đạo về lòng nhân ái trong buổi lễ buổi sáng.', '{"wordId":"preach","ukIpa":"/priːtʃ/","usIpa":"/priːtʃ/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To deliver a religious talk to a group of people.","vi":"giảng đạo; thuyết giáo"},{"pos":"v.","en":"To strongly encourage others to accept an idea or behaviour.","vi":"tuyên truyền; nhiệt tình ủng hộ hoặc vận động cho một tư tưởng"},{"pos":"v.","en":"To give unwanted advice about how others should behave.","vi":"lên lớp; đưa ra những lời khuyên đạo đức sáo rỗng khó chịu"}],"examples":[{"en":"The minister preached about kindness at the morning service.","vi":"Mục sư đã giảng đạo về lòng nhân ái trong buổi lễ buổi sáng.","audioKind":"ex"},{"en":"Schools should demonstrate respect through everyday practices rather than simply preach the importance of good behaviour.","vi":"Nhà trường nên thể hiện sự tôn trọng thông qua các hành động thực tế hàng ngày thay vì chỉ ra rả lên lớp về tầm quan trọng của lối sống đẹp.","audioKind":"ex2"}],"collocations":[{"en":"preach a sermon","vi":"thuyết pháp bài giảng"},{"en":"preach tolerance","vi":"tuyên truyền sự khoan dung"},{"en":"preach to someone","vi":"giáo điều với ai đó"},{"en":"practise what you preach","vi":"nói được làm được"}],"wordFamily":["preacher (n.)","preaching (n.)","preachy (adj.)"],"synonyms":["advocate","moralize"],"antonyms":[],"tipVi":"Cấu trúc \"preach to someone\" thường mang sắc thái chê bai là \"lên lớp, dạy đời ai đó\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pretentious', 'en-c1-12', 'pretentious', '/prɪˈtenʃəs/', 'C1', 'ra vẻ ta đây; phô trương; khoe khoang; ra điều cao siêu', 'adj.', 'pretension (n.), pretentiously (adv.), unpretentious (adj.)', 'Đồng nghĩa: affected, pompous · Trái nghĩa: unpretentious, modest', 'Mang nghĩa tiêu cực: cố ý tỏ ra cao nhã hoặc quan trọng, không chỉ đơn thuần là có sự tự tin.', 'The café felt pretentious, with velvet chairs and tiny portions.', NULL, 'Quán cà phê mang lại cảm giác phô trương với những chiếc ghế bằng nhung và khẩu phần ăn vô cùng nhỏ.', '{"wordId":"pretentious","ukIpa":"/prɪˈtenʃəs/","usIpa":"/prɪˈtenʃəs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"trying to seem more important or impressive than is justified","vi":"ra vẻ ta đây; phô trương; khoe khoang; ra điều cao siêu"}],"examples":[{"en":"The café felt pretentious, with velvet chairs and tiny portions.","vi":"Quán cà phê mang lại cảm giác phô trương với những chiếc ghế bằng nhung và khẩu phần ăn vô cùng nhỏ.","audioKind":"ex"},{"en":"Public art may alienate local residents if its presentation seems pretentious rather than welcoming and accessible.","vi":"Nghệ thuật công cộng có thể làm xa lánh người dân địa phương nếu cách thể hiện của nó mang tính khoe khoang, ra điều cao siêu thay vì gần gũi và dễ tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"sound pretentious","vi":"nghe có vẻ ra điều cao siêu"},{"en":"pretentious language","vi":"ngôn từ phô trương"},{"en":"a pretentious attitude","vi":"thái độ ta đây"}],"wordFamily":["pretension (n.)","pretentiously (adv.)","unpretentious (adj.)"],"synonyms":["affected","pompous"],"antonyms":["unpretentious","modest"],"tipVi":"Mang nghĩa tiêu cực: cố ý tỏ ra cao nhã hoặc quan trọng, không chỉ đơn thuần là có sự tự tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alienation', 'en-c1-12', 'alienation', '/ˌeɪliəˈneɪʃən/', 'C1', 'cảm giác bị cô lập, sự xa cách (với người khác hoặc xã hội); sự tha hóa (tách rời khỏi công việc ý nghĩa, bản sắc cá nhân hoặc tiềm năng con người)', 'n.', 'alienate (v.), alienated (adj.), alienating (adj.)', 'Đồng nghĩa: estrangement, disconnection · Trái nghĩa: belonging', 'Trong đời sống hàng ngày thường mang nghĩa cảm giác lạc lõng, xa cách; trong triết học và xã hội học có thể mang nghĩa sự tha hóa.', 'Joining a local choir eased her sense of alienation.', NULL, 'Tham gia vào một dàn đồng ca địa phương đã giúp cô ấy xoa dịu cảm giác lạc lõng, xa cách.', '{"wordId":"alienation","ukIpa":"/ˌeɪliəˈneɪʃən/","usIpa":"/ˌeɪliəˈneɪʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The feeling of being disconnected from other people or society.","vi":"cảm giác bị cô lập, sự xa cách (với người khác hoặc xã hội)"},{"pos":"n.","en":"Separation from meaningful work, personal identity, or human potential.","vi":"sự tha hóa (tách rời khỏi công việc ý nghĩa, bản sắc cá nhân hoặc tiềm năng con người)"}],"examples":[{"en":"Joining a local choir eased her sense of alienation.","vi":"Tham gia vào một dàn đồng ca địa phương đã giúp cô ấy xoa dịu cảm giác lạc lõng, xa cách.","audioKind":"ex"},{"en":"Rapid urban development can deepen residents'' alienation when familiar neighbourhoods are replaced by anonymous apartment blocks.","vi":"Sự phát triển đô thị nhanh chóng có thể làm sâu sắc thêm cảm giác lạc lõng của cư dân khi các khu phố quen thuộc bị thay thế bởi những dãy chung cư vô tính.","audioKind":"ex2"}],"collocations":[{"en":"a sense of alienation","vi":"cảm giác xa cách; cảm giác lạc lõng"},{"en":"social alienation","vi":"sự xa lánh xã hội"},{"en":"alienation from society","vi":"sự tách rời khỏi xã hội"}],"wordFamily":["alienate (v.)","alienated (adj.)","alienating (adj.)"],"synonyms":["estrangement","disconnection"],"antonyms":["belonging"],"tipVi":"Trong đời sống hàng ngày thường mang nghĩa cảm giác lạc lõng, xa cách; trong triết học và xã hội học có thể mang nghĩa sự tha hóa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refrain', 'en-c1-12', 'refrain', '/rɪˈfreɪn/', 'C1', 'kìm chế; tránh; điệp khúc; lời lặp đi lặp lại', 'v.', NULL, 'Đồng nghĩa: abstain, desist', 'Động từ thường đi với refrain from doing, mang sắc thái trang trọng.', 'Please refrain from feeding the ducks near the bridge.', NULL, 'Xin vui lòng không cho vịt ăn ở khu vực gần cây cầu.', '{"wordId":"refrain","ukIpa":"/rɪˈfreɪn/","usIpa":"/rɪˈfreɪn/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To deliberately stop yourself from doing something.","vi":"kìm chế; tránh"},{"pos":"n.","en":"A repeated part of a song, poem, or speech.","vi":"điệp khúc; lời lặp đi lặp lại"}],"examples":[{"en":"Please refrain from feeding the ducks near the bridge.","vi":"Xin vui lòng không cho vịt ăn ở khu vực gần cây cầu.","audioKind":"ex"},{"en":"Visitors should refrain from touching fragile exhibits so that museums can preserve them for future generations.","vi":"Du khách nên tránh chạm vào các hiện vật dễ hỏng để các bảo tàng có thể gìn giữ chúng cho các thế hệ mai sau.","audioKind":"ex2"}],"collocations":[{"en":"refrain from doing something","vi":"tránh làm điều gì"},{"en":"refrain from comment","vi":"không bình luận"},{"en":"a familiar refrain","vi":"điệp khúc quen thuộc"}],"wordFamily":[],"synonyms":["abstain","desist"],"antonyms":[],"tipVi":"Động từ thường đi với refrain from doing, mang sắc thái trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adversity', 'en-c1-12', 'adversity', '/ədˈvɝːsəti/', 'C1', 'nghịch cảnh; hoàn cảnh khó khăn', 'n.', 'adverse (adj.), adversely (adv.)', 'Đồng nghĩa: hardship, misfortune · Trái nghĩa: prosperity', 'Thường là danh từ không đếm được, hay đi kèm với các từ face và overcome.', 'Her friends stood beside her throughout years of adversity.', NULL, 'Bạn bè luôn ở bên cô ấy xuyên suốt những năm tháng nghịch cảnh.', '{"wordId":"adversity","ukIpa":"/ədˈvɜːsəti/","usIpa":"/ədˈvɝːsəti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A difficult or unfortunate situation that causes hardship.","vi":"nghịch cảnh; hoàn cảnh khó khăn"}],"examples":[{"en":"Her friends stood beside her throughout years of adversity.","vi":"Bạn bè luôn ở bên cô ấy xuyên suốt những năm tháng nghịch cảnh.","audioKind":"ex"},{"en":"Strong community networks can help families cope with adversity during periods of economic uncertainty.","vi":"Các mối quan hệ cộng đồng vững chắc có thể giúp các gia đình đối phó với nghịch cảnh trong những thời kỳ kinh tế bất ổn.","audioKind":"ex2"}],"collocations":[{"en":"face adversity","vi":"đối mặt với nghịch cảnh"},{"en":"overcome adversity","vi":"vượt qua khó khăn"},{"en":"in the face of adversity","vi":"khi đối diện với nghịch cảnh"}],"wordFamily":["adverse (adj.)","adversely (adv.)"],"synonyms":["hardship","misfortune"],"antonyms":["prosperity"],"tipVi":"Thường là danh từ không đếm được, hay đi kèm với các từ face và overcome.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concession', 'en-c1-12', 'concession', '/kənˈseʃən/', 'C1', 'sự nhượng bộ; điều được chấp nhận hoặc từ bỏ để giúp đạt được thỏa thuận; sự ưu đãi; mức giá giảm dành riêng cho một nhóm đối tượng cụ thể; quyền hạn đặc biệt; giấy phép chính thức để kinh doanh hoặc khai thác tài nguyên', 'n.', 'concede (v.), concessionary (adj.)', NULL, 'Cụm từ "make concessions" có nghĩa là đưa ra các nhượng bộ; trong tiếng Anh-Anh, từ này còn chỉ mức giảm giá vé.', 'We made a concession and agreed to leave earlier.', NULL, 'Chúng tôi đã nhượng bộ và đồng ý rời đi sớm hơn.', '{"wordId":"concession","ukIpa":"/kənˈseʃən/","usIpa":"/kənˈseʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Something accepted or given up to help reach an agreement","vi":"sự nhượng bộ; điều được chấp nhận hoặc từ bỏ để giúp đạt được thỏa thuận"},{"pos":"n.","en":"A reduced price offered to a particular group of people","vi":"sự ưu đãi; mức giá giảm dành riêng cho một nhóm đối tượng cụ thể"},{"pos":"n.","en":"Official permission to operate a business or use particular resources","vi":"quyền hạn đặc biệt; giấy phép chính thức để kinh doanh hoặc khai thác tài nguyên"}],"examples":[{"en":"We made a concession and agreed to leave earlier.","vi":"Chúng tôi đã nhượng bộ và đồng ý rời đi sớm hơn.","audioKind":"ex"},{"en":"Offering concessions to students and older people can make public transport more affordable for these groups.","vi":"Việc cung cấp giá vé ưu đãi cho học sinh, sinh viên và người cao tuổi có thể giúp các nhóm đối tượng này dễ chi trả hơn cho chi phí giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"make a concession","vi":"đưa ra sự nhượng bộ"},{"en":"price concessions","vi":"ưu đãi về giá"},{"en":"a major concession","vi":"sự nhượng bộ lớn"},{"en":"mining concession","vi":"quyền khai mỏ"}],"wordFamily":["concede (v.)","concessionary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"make concessions\" có nghĩa là đưa ra các nhượng bộ; trong tiếng Anh-Anh, từ này còn chỉ mức giảm giá vé.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_displacement', 'en-c1-12', 'displacement', '/dɪsˈpleɪsmənt/', 'C1', 'sự buộc phải rời khỏi nhà cửa; tình trạng ly hương, lưu vong; sự thay thế; việc ai đó hoặc cái gì đó bị thay thế bởi người hoặc vật khác; sự dịch chuyển vị trí; hoặc lượng chất lỏng bị đẩy ra bởi một vật thể', 'n.', 'displace (v.), displaced (adj.)', NULL, 'Khi dịch cho con người, thường dùng "buộc phải chuyển cư"; trong vật lý, từ này chỉ độ dịch chuyển hoặc thể tích chất lỏng bị chiếm chỗ.', 'The flood caused displacement, forcing families into temporary shelters.', NULL, 'Trận lũ lụt gây ra tình trạng mất nhà cửa, buộc nhiều gia đình phải vào các nơi trú ẩn tạm thời.', '{"wordId":"displacement","ukIpa":"/dɪsˈpleɪsmənt/","usIpa":"/dɪsˈpleɪsmənt/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The forced movement of people away from their homes.","vi":"sự buộc phải rời khỏi nhà cửa; tình trạng ly hương, lưu vong"},{"pos":"n.","en":"The replacement of someone or something by another.","vi":"sự thay thế; việc ai đó hoặc cái gì đó bị thay thế bởi người hoặc vật khác"},{"pos":"n.","en":"Movement from a position, or fluid pushed aside by an object.","vi":"sự dịch chuyển vị trí; hoặc lượng chất lỏng bị đẩy ra bởi một vật thể"}],"examples":[{"en":"The flood caused displacement, forcing families into temporary shelters.","vi":"Trận lũ lụt gây ra tình trạng mất nhà cửa, buộc nhiều gia đình phải vào các nơi trú ẩn tạm thời.","audioKind":"ex"},{"en":"Coastal erosion may lead to widespread displacement unless governments invest in effective protection and planned relocation.","vi":"Sự xói mòn bờ biển có thể dẫn đến tình trạng di dời dân cư diện rộng trừ khi chính phủ đầu tư vào các biện pháp bảo vệ hiệu quả và tái định cư có kế hoạch.","audioKind":"ex2"}],"collocations":[{"en":"population displacement","vi":"sự di dời dân cư"},{"en":"forced displacement","vi":"sự buộc phải rời đi"},{"en":"job displacement","vi":"việc mất việc làm do bị thay thế"},{"en":"water displacement","vi":"lượng nước rẽ nước hoặc thể tích vật chiếm chỗ"}],"wordFamily":["displace (v.)","displaced (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dịch cho con người, thường dùng \"buộc phải chuyển cư\"; trong vật lý, từ này chỉ độ dịch chuyển hoặc thể tích chất lỏng bị chiếm chỗ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_emigrant', 'en-c1-12', 'emigrant', '/ˈemɪɡrənt/', 'C1', 'người di cư ra nước ngoài; người rời bỏ đất nước mình để định cư ở một quốc gia khác', 'n.', 'emigrate (v.), emigration (n.)', NULL, 'Nhìn từ góc độ quốc gia gốc thì là "emigrant", còn nhìn từ quốc gia đến thì là "immigrant".', 'As an emigrant, she missed her hometown''s busy markets.', NULL, 'Là một người di cư sang xứ người, cô ấy rất nhớ những khu chợ nhộn nhịp ở quê nhà.', '{"wordId":"emigrant","ukIpa":"/ˈemɪɡrənt/","usIpa":"/ˈemɪɡrənt/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"someone who leaves their country to settle in another","vi":"người di cư ra nước ngoài; người rời bỏ đất nước mình để định cư ở một quốc gia khác"}],"examples":[{"en":"As an emigrant, she missed her hometown''s busy markets.","vi":"Là một người di cư sang xứ người, cô ấy rất nhớ những khu chợ nhộn nhịp ở quê nhà.","audioKind":"ex"},{"en":"Emigrants often maintain strong connections with their countries of origin through family visits and financial support.","vi":"Những người di cư ra nước ngoài thường duy trì mối liên hệ mạnh mẽ với quê hương thông qua các chuyến thăm gia đình và hỗ trợ tài chính.","audioKind":"ex2"}],"collocations":[{"en":"emigrant workers","vi":"công nhân di cư"},{"en":"emigrant community","vi":"cộng đồng người di cư"},{"en":"emigrant families","vi":"các gia đình di cư"}],"wordFamily":["emigrate (v.)","emigration (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhìn từ góc độ quốc gia gốc thì là \"emigrant\", còn nhìn từ quốc gia đến thì là \"immigrant\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concerted', 'en-c1-12', 'concerted', '/kənˈsɝːtɪd/', 'C1', 'phối hợp nhịp nhàng; chung sức; quyết tâm cao độ; dốc toàn lực', 'adj.', 'concertedly (adv.)', 'Đồng nghĩa: coordinated, joint · Trái nghĩa: uncoordinated', 'Thường bổ nghĩa cho effort hoặc action, nhấn mạnh tính phối hợp hoặc tập trung toàn lực.', 'Our concerted efforts finally cleared the garden of rubbish.', NULL, 'Nỗ lực chung tay của chúng tôi cuối cùng đã dọn sạch rác trong khu vườn.', '{"wordId":"concerted","ukIpa":"/kənˈsɜːtɪd/","usIpa":"/kənˈsɝːtɪd/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Planned and carried out together to achieve a shared goal.","vi":"phối hợp nhịp nhàng; chung sức"},{"pos":"adj.","en":"Involving determined effort directed towards a particular goal.","vi":"quyết tâm cao độ; dốc toàn lực"}],"examples":[{"en":"Our concerted efforts finally cleared the garden of rubbish.","vi":"Nỗ lực chung tay của chúng tôi cuối cùng đã dọn sạch rác trong khu vườn.","audioKind":"ex"},{"en":"Reducing urban air pollution requires concerted action from local authorities, transport providers, businesses and residents.","vi":"Việc giảm ô nhiễm không khí đô thị đòi hỏi hành động phối hợp từ chính quyền địa phương, các đơn vị giao thông, doanh nghiệp và cư dân.","audioKind":"ex2"}],"collocations":[{"en":"concerted effort","vi":"nỗ lực chung; sự đồng tâm hiệp lực"},{"en":"concerted action","vi":"hành động phối hợp"},{"en":"concerted campaign","vi":"chiến dịch phối hợp"}],"wordFamily":["concertedly (adv.)"],"synonyms":["coordinated","joint"],"antonyms":["uncoordinated"],"tipVi":"Thường bổ nghĩa cho effort hoặc action, nhấn mạnh tính phối hợp hoặc tập trung toàn lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boycott', 'en-c1-12', 'boycott', '/ˈbɔɪkɑːt/', 'C1', 'tẩy chay; từ chối tham gia; cuộc tẩy chay; hành động tẩy chay', 'v.', NULL, NULL, 'Động từ sau trực tiếp tiếp nhận đối tượng tẩy chay; danh từ thường dùng a boycott of.', 'Local shoppers decided to boycott the store over unfair wages.', NULL, 'Người mua sắm địa phương quyết định tẩy chay cửa hàng này vì mức lương bất công.', '{"wordId":"boycott","ukIpa":"/ˈbɔɪkɒt/","usIpa":"/ˈbɔɪkɑːt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"Refuse to buy or participate in something as a protest.","vi":"tẩy chay; từ chối tham gia"},{"pos":"n.","en":"An organized refusal to buy or participate as a protest.","vi":"cuộc tẩy chay; hành động tẩy chay"}],"examples":[{"en":"Local shoppers decided to boycott the store over unfair wages.","vi":"Người mua sắm địa phương quyết định tẩy chay cửa hàng này vì mức lương bất công.","audioKind":"ex"},{"en":"A consumer boycott can pressure companies to improve working conditions throughout their international supply chains.","vi":"Việc người tiêu dùng tẩy chay có thể gây sức ép buộc các doanh nghiệp phải cải thiện điều kiện làm việc trong toàn bộ chuỗi cung ứng quốc tế của họ.","audioKind":"ex2"}],"collocations":[{"en":"boycott a product","vi":"tẩy chay một sản phẩm"},{"en":"consumer boycott","vi":"cuộc tẩy chay của người tiêu dùng"},{"en":"call for a boycott","vi":"kêu gọi tẩy chay"},{"en":"boycott an event","vi":"tẩy chay một sự kiện"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ sau trực tiếp tiếp nhận đối tượng tẩy chay; danh từ thường dùng a boycott of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_equitable', 'en-c1-12', 'equitable', '/ˈekwɪtəbl/', 'C1', 'công bằng; hợp lý; công tâm', 'adj.', 'equitably (adv.), equity (n.), inequitable (adj.)', 'Đồng nghĩa: fair, just · Trái nghĩa: inequitable, unfair', 'equitable nhấn mạnh sự công bằng dựa trên hoàn cảnh thực tế, không nhất thiết lúc nào cũng cào bằng bằng nhau.', 'We agreed on an equitable division of household chores.', NULL, 'Chúng tôi đã đồng ý về việc phân chia công việc nhà một cách công bằng và hợp lý.', '{"wordId":"equitable","ukIpa":"/ˈekwɪtəbl/","usIpa":"/ˈekwɪtəbl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"fair to everyone involved, taking their different circumstances into account","vi":"công bằng; hợp lý; công tâm"}],"examples":[{"en":"We agreed on an equitable division of household chores.","vi":"Chúng tôi đã đồng ý về việc phân chia công việc nhà một cách công bằng và hợp lý.","audioKind":"ex"},{"en":"An equitable funding system would direct more resources towards schools serving disadvantaged communities.","vi":"Hệ thống phân bổ nguồn lực công bằng sẽ hướng nhiều nguồn lực hơn đến các trường học phục vụ cho các cộng đồng có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"equitable distribution","vi":"phân phối công bằng"},{"en":"equitable access","vi":"quyền tiếp cận công bằng"},{"en":"equitable treatment","vi":"đối xử công bằng"}],"wordFamily":["equitably (adv.)","equity (n.)","inequitable (adj.)"],"synonyms":["fair","just"],"antonyms":["inequitable","unfair"],"tipVi":"equitable nhấn mạnh sự công bằng dựa trên hoàn cảnh thực tế, không nhất thiết lúc nào cũng cào bằng bằng nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_revival', 'en-c1-12', 'revival', '/rɪˈvaɪvəl/', 'C1', 'sự hồi phục; sự hồi sinh; sự thịnh hành trở lại; việc dàn dựng lại; việc trình diễn lại (vở kịch, tác phẩm cũ)', 'n.', 'revive (v.), revived (adj.)', 'Đồng nghĩa: resurgence, renewal · Trái nghĩa: decline', 'revival nhấn mạnh sự suy tàn hoặc trầm lắng sau đó trở lại hoạt động sôi nổi.', 'Our local market is enjoying a revival this spring.', NULL, 'Chợ địa phương của chúng tôi đang trở nên sầm uất trở lại vào mùa xuân này.', '{"wordId":"revival","ukIpa":"/rɪˈvaɪvəl/","usIpa":"/rɪˈvaɪvəl/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a return to activity, strength, or popularity","vi":"sự hồi phục; sự hồi sinh; sự thịnh hành trở lại"},{"pos":"n.","en":"a new production of a play or other older performance","vi":"việc dàn dựng lại; việc trình diễn lại (vở kịch, tác phẩm cũ)"}],"examples":[{"en":"Our local market is enjoying a revival this spring.","vi":"Chợ địa phương của chúng tôi đang trở nên sầm uất trở lại vào mùa xuân này.","audioKind":"ex"},{"en":"A revival of traditional crafts can create employment while preserving skills that might otherwise disappear.","vi":"Việc hồi sinh các nghề thủ công truyền thống vừa có thể tạo ra việc làm vừa bảo tồn được những kỹ năng có nguy cơ mai một.","audioKind":"ex2"}],"collocations":[{"en":"economic revival","vi":"sự phục hồi kinh tế"},{"en":"a revival of interest","vi":"sự quan tâm được khơi 3ig lại"},{"en":"stage a revival","vi":"dàn dựng một vở kịch cũ"}],"wordFamily":["revive (v.)","revived (adj.)"],"synonyms":["resurgence","renewal"],"antonyms":["decline"],"tipVi":"revival nhấn mạnh sự suy tàn hoặc trầm lắng sau đó trở lại hoạt động sôi nổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_destine', 'en-c1-12', 'destine', '/ˈdestɪn/', 'C1', 'dành sẵn; định sẵn cho tương lai', 'v.', 'destined (adj.), destiny (n.)', NULL, 'Thường dùng ở dạng bị động: be destined for hoặc to do.', 'Everyone thought the talented young dancer was destined for success.', NULL, 'Mọi người đều nghĩ rằng vũ công trẻ tài năng này chắc chắn sẽ thành công.', '{"wordId":"destine","ukIpa":"/ˈdestɪn/","usIpa":"/ˈdestɪn/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to determine someone''s future or something''s intended purpose","vi":"dành sẵn; định sẵn cho tương lai"}],"examples":[{"en":"Everyone thought the talented young dancer was destined for success.","vi":"Mọi người đều nghĩ rằng vũ công trẻ tài năng này chắc chắn sẽ thành công.","audioKind":"ex"},{"en":"Children from disadvantaged backgrounds are not destined to fail if they receive appropriate educational support and opportunities.","vi":"Trẻ em có hoàn cảnh khó khăn không hẳn đã bị định sẵn là thất bại nếu các em nhận được sự hỗ trợ và cơ hội giáo dục phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"be destined to do","vi":"được định sẵn để làm gì"},{"en":"be destined for success","vi":"được định sẵn để thành công"},{"en":"goods destined for export","vi":"hàng hóa dành riêng cho xuất khẩu"}],"wordFamily":["destined (adj.)","destiny (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng ở dạng bị động: be destined for hoặc to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_12_1', 'en-c1-12', 'Cách dùng “displacement” (n.) — sự buộc phải rời khỏi nhà cửa; tình trạng ly hương, lưu vong', 'population displacement  ·  forced displacement  ·  job displacement', 'Khi dịch cho con người, thường dùng "buộc phải chuyển cư"; trong vật lý, từ này chỉ độ dịch chuyển hoặc thể tích chất lỏng bị chiếm chỗ.', 'Họ từ (Word Family): displace (v.), displaced (adj.)', '[{"hanzi":"The flood caused displacement, forcing families into temporary shelters.","pinyin":"","meaning":"Trận lũ lụt gây ra tình trạng mất nhà cửa, buộc nhiều gia đình phải vào các nơi trú ẩn tạm thời."},{"hanzi":"Coastal erosion may lead to widespread displacement unless governments invest in effective protection and planned relocation.","pinyin":"","meaning":"Sự xói mòn bờ biển có thể dẫn đến tình trạng di dời dân cư diện rộng trừ khi chính phủ đầu tư vào các biện pháp bảo vệ hiệu quả và tái định cư có kế hoạch."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_12_2', 'en-c1-12', 'Cách dùng “alienation” (n.) — cảm giác bị cô lập, sự xa cách (với người khác hoặc xã hội)', 'a sense of alienation  ·  social alienation  ·  alienation from society', 'Trong đời sống hàng ngày thường mang nghĩa cảm giác lạc lõng, xa cách; trong triết học và xã hội học có thể mang nghĩa sự tha hóa.', 'Họ từ (Word Family): alienate (v.), alienated (adj.), alienating (adj.) | Đồng nghĩa: estrangement, disconnection · Trái nghĩa: belonging', '[{"hanzi":"Joining a local choir eased her sense of alienation.","pinyin":"","meaning":"Tham gia vào một dàn đồng ca địa phương đã giúp cô ấy xoa dịu cảm giác lạc lõng, xa cách."},{"hanzi":"Rapid urban development can deepen residents'' alienation when familiar neighbourhoods are replaced by anonymous apartment blocks.","pinyin":"","meaning":"Sự phát triển đô thị nhanh chóng có thể làm sâu sắc thêm cảm giác lạc lõng của cư dân khi các khu phố quen thuộc bị thay thế bởi những dãy chung cư vô tính."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_12_3', 'en-c1-12', 'Cách dùng “hijack” (v.) — khống chế; cướp (phương tiện giao thông)', 'hijack a plane  ·  hijack a debate  ·  hijack the conversation', 'Nghĩa gốc là cướp phương tiện; cũng có thể dùng theo nghĩa bóng để chỉ việc thao túng thảo luận hoặc chương trình nghị sự.', 'Họ từ (Word Family): hijacker (n.), hijacking (n.)', '[{"hanzi":"One guest hijacked the conversation to discuss his own problems.","pinyin":"","meaning":"Một vị khách đã lái chuyển hướng câu chuyện sang các vấn đề của riêng anh ta."},{"hanzi":"Powerful interest groups may hijack public debates, preventing communities from discussing their most urgent concerns.","pinyin":"","meaning":"Các nhóm lợi ích hùng mạnh có thể thao túng các cuộc tranh luận công khai, khiến các cộng đồng không thể thảo luận về các vấn đề cấp bách nhất của họ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_12_4', 'en-c1-12', 'Cách dùng “integrity” (n.) — sự chính trực; tính trung thực và tuân thủ các nguyên tắc đạo đức vững chắc', 'personal integrity  ·  professional integrity  ·  structural integrity', 'Là danh từ không đếm được; vừa dùng để chỉ sự chính trực của con người, vừa chỉ tính nguyên vẹn của kết cấu vật chất.', 'Đồng nghĩa: honesty, uprightness · Trái nghĩa: dishonesty', '[{"hanzi":"She showed integrity by returning the money she found.","pinyin":"","meaning":"Cô ấy thể hiện phẩm chất chính trực bằng cách trả lại số tiền nhặt được."},{"hanzi":"Independent inspections help maintain the structural integrity of bridges and protect the public from preventable accidents.","pinyin":"","meaning":"Các cuộc kiểm tra độc lập giúp duy trì tính toàn vẹn kết cấu của cầu đường và bảo vệ công chúng khỏi những tai nạn có thể phòng ngừa."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_12_1', 'en-c1-12', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_1_1', 'ten_c1_12_1', 'humanitarian', 'Volunteers packed blankets and medicine for the humanitarian mission.', 'Volunteers packed blankets and medicine for the humanitarian mission.', '/hjuːˌmænɪˈteriən/', 'Các tình nguyện viên đã đóng gói chăn màn và thuốc men cho sứ mệnh nhân đạo.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_1_2', 'ten_c1_12_1', 'conspicuous', 'Her yellow umbrella was conspicuous among the black ones.', 'Her yellow umbrella was conspicuous among the black ones.', '/kənˈspɪkjuəs/', 'Chiếc ô màu vàng của cô ấy rất nổi bật giữa những chiếc ô màu đen.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_1_3', 'ten_c1_12_1', 'hijack', 'One guest hijacked the conversation to discuss his own problems.', 'One guest hijacked the conversation to discuss his own problems.', '/ˈhaɪdʒæk/', 'Một vị khách đã lái chuyển hướng câu chuyện sang các vấn đề của riêng anh ta.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_1_4', 'ten_c1_12_1', 'unprecedented', 'The bakery received an unprecedented flood of orders today.', 'The bakery received an unprecedented flood of orders today.', '/ʌnˈpresɪdentɪd/', 'Tiệm bánh đã nhận được một lượng đơn hàng lớn chưa từng có vào ngày hôm nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_1_5', 'ten_c1_12_1', 'delinquency', 'Our youth club helps teenagers stay away from delinquency.', 'Our youth club helps teenagers stay away from delinquency.', '/dɪˈlɪŋkwənsi/', 'Câu lạc bộ thanh thiếu niên của chúng tôi giúp các em tránh xa các hành vi phạm pháp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_1_6', 'ten_c1_12_1', 'slaughter', 'The farmer explained why some animals are slaughtered for food.', 'The farmer explained why some animals are slaughtered for food.', '/ˈslɔːtər/', 'Người nông dân giải thích lý do tại sao một số loài động vật bị giết mổ để lấy thịt.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_1_7', 'ten_c1_12_1', 'ration', 'Each hiker packed a daily ration of nuts and dried fruit.', 'Each hiker packed a daily ration of nuts and dried fruit.', '/ˈræʃən/', 'Mỗi người leo núi mang theo một phần hạt và trái cây sấy khô đủ dùng cho một ngày.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_1_8', 'ten_c1_12_1', 'virtue', 'My grandfather always said that patience was a virtue.', 'My grandfather always said that patience was a virtue.', '/ˈvɝːtʃuː/', 'Ông tôi vẫn thường nói rằng sự kiên nhẫn là một đức tính cao đẹp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_12_1_1', 'en-c1-12', 'ten_c1_12_1', 'listening', 'listening', 'Volunteers packed blankets and medicine for the humanitarian mission.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chợ địa phương của chúng tôi đang trở nên sầm uất trở lại vào mùa xuân này.","Người mua sắm địa phương quyết định tẩy chay cửa hàng này vì mức lương bất công.","Các tình nguyện viên đã đóng gói chăn màn và thuốc men cho sứ mệnh nhân đạo.","Là một người di cư sang xứ người, cô ấy rất nhớ những khu chợ nhộn nhịp ở quê nhà."]'::jsonb, 2, 'Volunteers packed blankets and medicine for the humanitarian mission. → Các tình nguyện viên đã đóng gói chăn màn và thuốc men cho sứ mệnh nhân đạo.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_12_1_2', 'en-c1-12', 'ten_c1_12_1', 'listening', 'listening', 'Her yellow umbrella was conspicuous among the black ones.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sau cuộc tranh cãi, anh ấy cảm thấy mình như một kẻ bị hắt hủi.","Nụ cười tươi vui của cô ấy đã che giấu sự thất vọng, một sự che đậy nhỏ.","Mỗi người leo núi mang theo một phần hạt và trái cây sấy khô đủ dùng cho một ngày.","Chiếc ô màu vàng của cô ấy rất nổi bật giữa những chiếc ô màu đen."]'::jsonb, 3, 'Her yellow umbrella was conspicuous among the black ones. → Chiếc ô màu vàng của cô ấy rất nổi bật giữa những chiếc ô màu đen.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_12_1_3', 'en-c1-12', 'ten_c1_12_1', 'listening', 'listening', 'One guest hijacked the conversation to discuss his own problems.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một vị khách đã lái chuyển hướng câu chuyện sang các vấn đề của riêng anh ta.","Chúng tôi đã nhượng bộ và đồng ý rời đi sớm hơn.","Câu lạc bộ thanh thiếu niên của chúng tôi giúp các em tránh xa các hành vi phạm pháp.","Các tình nguyện viên đã đóng gói chăn màn và thuốc men cho sứ mệnh nhân đạo."]'::jsonb, 0, 'One guest hijacked the conversation to discuss his own problems. → Một vị khách đã lái chuyển hướng câu chuyện sang các vấn đề của riêng anh ta.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_12_2', 'en-c1-12', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_2_1', 'ten_c1_12_2', 'humanitarian', 'International humanitarian organisations provide essential supplies to communities affected by natural disasters and armed conflict.', 'International humanitarian organisations provide essential supplies to communities affected by natural disasters and armed conflict.', '/hjuːˌmænɪˈteriən/', 'Các tổ chức nhân đạo quốc tế cung cấp các nhu yếu phẩm thiết yếu cho các cộng đồng bị ảnh hưởng bởi thiên tai và xung đột vũ trang.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_2_2', 'ten_c1_12_2', 'conspicuous', 'Conspicuous consumption can encourage unnecessary spending as people seek to display their wealth through expensive possessions.', 'Conspicuous consumption can encourage unnecessary spending as people seek to display their wealth through expensive possessions.', '/kənˈspɪkjuəs/', 'Tiêu dùng phô trương có thể cổ súy cho những khoản chi tiêu không cần thiết khi mọi người tìm cách thể hiện sự giàu có thông qua các món đồ đắt tiền.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_2_3', 'ten_c1_12_2', 'hijack', 'Powerful interest groups may hijack public debates, preventing communities from discussing their most urgent concerns.', 'Powerful interest groups may hijack public debates, preventing communities from discussing their most urgent concerns.', '/ˈhaɪdʒæk/', 'Các nhóm lợi ích hùng mạnh có thể thao túng các cuộc tranh luận công khai, khiến các cộng đồng không thể thảo luận về các vấn đề cấp bách nhất của họ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_2_4', 'ten_c1_12_2', 'unprecedented', 'Many coastal communities face unprecedented challenges as rising sea levels threaten homes, infrastructure, and local livelihoods.', 'Many coastal communities face unprecedented challenges as rising sea levels threaten homes, infrastructure, and local livelihoods.', '/ʌnˈpresɪdentɪd/', 'Nhiều cộng đồng ven biển phải đối mặt với những thách thức chưa từng có khi mực nước biển dâng cao đe dọa nhà ở, cơ sở hạ tầng và sinh kế của người dân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_2_5', 'ten_c1_12_2', 'delinquency', 'Affordable recreational facilities and supportive mentoring programmes may help reduce juvenile delinquency in disadvantaged neighbourhoods.', 'Affordable recreational facilities and supportive mentoring programmes may help reduce juvenile delinquency in disadvantaged neighbourhoods.', '/dɪˈlɪŋkwənsi/', 'Các cơ sở giải trí giá cả phải chăng và các chương trình cố vấn hỗ trợ có thể giúp giảm thiểu tình trạng phạm pháp vị thành niên ở các khu vực có hoàn cảnh khó khăn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_12_2_6', 'ten_c1_12_2', 'slaughter', 'Strict regulations on how animals are slaughtered can improve welfare standards throughout the food production industry.', 'Strict regulations on how animals are slaughtered can improve welfare standards throughout the food production industry.', '/ˈslɔːtər/', 'Các quy định nghiêm ngặt về cách thức giết mổ động vật có thể nâng cao tiêu chuẩn phúc lợi trong toàn ngành sản xuất thực phẩm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_12_2_1', 'en-c1-12', 'ten_c1_12_2', 'listening', 'listening', 'International humanitarian organisations provide essential supplies to communities affected by natural disasters and armed conflict.', NULL, 'Trong câu vừa nghe, từ “humanitarian” mang nghĩa nào sau đây?', '["khả năng cạnh tranh","mang tính nhân đạo","vật cản, sự tắc nghẽn","một cách đầy tiếc nuối, thể hiện sự buồn bã hoặc thất vọng về điều gì đó"]'::jsonb, 1, '“humanitarian” (/hjuːˌmænɪˈteriən/): mang tính nhân đạo. Câu đầy đủ: International humanitarian organisations provide essential supplies to communities affected by natural disasters and armed conflict.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_12_2_2', 'en-c1-12', 'ten_c1_12_2', 'listening', 'listening', 'Conspicuous consumption can encourage unnecessary spending as people seek to display their wealth through expensive possessions.', NULL, 'Trong câu vừa nghe, từ “conspicuous” mang nghĩa nào sau đây?', '["bước đi dũng mãnh; sải bước","hung dữ; dữ tợn","tiền thân; người đi trước","dễ thấy; nổi bật; đập ngay vào mắt"]'::jsonb, 3, '“conspicuous” (/kənˈspɪkjuəs/): dễ thấy; nổi bật; đập ngay vào mắt. Câu đầy đủ: Conspicuous consumption can encourage unnecessary spending as people seek to display their wealth through expensive possessions.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
