INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_12_4', 'en-c1-12', 'en_to_vi', 'After the argument, he felt like an outcast.', 'After the argument, he felt like an outcast.', '/ˈaʊtkæst/', NULL, 'Sau cuộc tranh cãi, anh ấy cảm thấy mình như một kẻ bị hắt hủi.', NULL, '["sau","cuộc","tranh","cãi","anh","ấy","cảm","thấy"]'::jsonb, 'Từ trọng tâm: outcast (người bị xã hội hắt hủi; người bị gạt ra bên lề)', 'After the argument, he felt like an outcast. → Sau cuộc tranh cãi, anh ấy cảm thấy mình như một kẻ bị hắt hủi.', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_12_5', 'en-c1-12', 'en_to_vi', 'The manager summoned everyone to her office after lunch.', 'The manager summoned everyone to her office after lunch.', '/ˈsʌmən/', NULL, 'Người quản lý đã triệu tập mọi người vào văn phòng của cô ấy sau bữa trưa.', NULL, '["người","quản","lý","đã","triệu","tập","mọi","người"]'::jsonb, 'Từ trọng tâm: summon (triệu tập; gọi đến; yêu cầu có mặt)', 'The manager summoned everyone to her office after lunch. → Người quản lý đã triệu tập mọi người vào văn phòng của cô ấy sau bữa trưa.', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_12_6', 'en-c1-12', 'en_to_vi', 'He nodded in acknowledgment of his sister''s helpful suggestion.', 'He nodded in acknowledgment of his sister''s helpful suggestion.', '/əkˈnɑːlɪdʒmənt/', NULL, 'Anh ấy gật đầu để tỏ ý ghi nhận gợi ý hữu ích từ chị gái mình.', NULL, '["anh","ấy","gật","đầu","để","tỏ","ý","ghi"]'::jsonb, 'Từ trọng tâm: acknowledgment (sự công nhận; sự thừa nhận)', 'He nodded in acknowledgment of his sister''s helpful suggestion. → Anh ấy gật đầu để tỏ ý ghi nhận gợi ý hữu ích từ chị gái mình.', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
