INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_2', 'en-c1-12', NULL, 'comprehensive_test', 'listening', 'Her yellow umbrella was conspicuous among the black ones.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc ô màu vàng của cô ấy rất nổi bật giữa những chiếc ô màu đen.","Ông tôi vẫn thường nói rằng sự kiên nhẫn là một đức tính cao đẹp.","Quán cà phê mang lại cảm giác phô trương với những chiếc ghế bằng nhung và khẩu phần ăn vô cùng nhỏ.","Là một người di cư sang xứ người, cô ấy rất nhớ những khu chợ nhộn nhịp ở quê nhà."]'::jsonb, 0, 'Her yellow umbrella was conspicuous among the black ones. → Chiếc ô màu vàng của cô ấy rất nổi bật giữa những chiếc ô màu đen.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_3', 'en-c1-12', NULL, 'comprehensive_test', 'listening', 'hijack', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sẵn sàng và có thể hoạt động hoặc sử dụng được","khống chế; cướp (phương tiện giao thông)","dùng sai; lạm dụng","sự chinh phục; sự chiếm đóng"]'::jsonb, 1, 'hijack (/ˈhaɪdʒæk/) → khống chế; cướp (phương tiện giao thông); thao túng; chiếm đoạt (cho mục đích riêng)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_4', 'en-c1-12', NULL, 'comprehensive_test', 'listening', 'The bakery received an unprecedented flood of orders today.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc ô màu vàng của cô ấy rất nổi bật giữa những chiếc ô màu đen.","Người mua sắm địa phương quyết định tẩy chay cửa hàng này vì mức lương bất công.","Tiệm bánh đã nhận được một lượng đơn hàng lớn chưa từng có vào ngày hôm nay.","Lòng yêu nước của cô ấy tỏa sáng mỗi khi cô nhắc đến những thành tựu của đất nước mình."]'::jsonb, 2, 'The bakery received an unprecedented flood of orders today. → Tiệm bánh đã nhận được một lượng đơn hàng lớn chưa từng có vào ngày hôm nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_5', 'en-c1-12', NULL, 'comprehensive_test', 'listening', 'delinquency', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hành vi vi phạm pháp luật hoặc không chuẩn mực, đặc biệt ở giới trẻ","sự tàn phá quy mô lớn; thảm họa diệt chủng","sự việc; sự cố","đồng bảng Anh, đơn vị tiền tệ của Vương quốc Anh"]'::jsonb, 0, 'delinquency (/dɪˈlɪŋkwənsi/) → hành vi vi phạm pháp luật hoặc không chuẩn mực, đặc biệt ở giới trẻ; việc chậm thanh toán khoản tiền bắt buộc', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_6', 'en-c1-12', NULL, 'comprehensive_test', 'listening', 'The farmer explained why some animals are slaughtered for food.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người nông dân giải thích lý do tại sao một số loài động vật bị giết mổ để lấy thịt.","Nụ cười tươi vui của cô ấy đã che giấu sự thất vọng, một sự che đậy nhỏ.","Chúng tôi đã đồng ý về việc phân chia công việc nhà một cách công bằng và hợp lý.","Tham gia vào một dàn đồng ca địa phương đã giúp cô ấy xoa dịu cảm giác lạc lõng, xa cách."]'::jsonb, 0, 'The farmer explained why some animals are slaughtered for food. → Người nông dân giải thích lý do tại sao một số loài động vật bị giết mổ để lấy thịt.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_7', 'en-c1-12', NULL, 'comprehensive_test', 'listening', 'ration', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phần định lượng; khẩu phần","vật cản, sự tắc nghẽn","xứ đạo; giáo xứ","hợp kim"]'::jsonb, 0, 'ration (/ˈræʃən/) → phần định lượng; khẩu phần; cấp định lượng; phân phối theo định mức', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_8', 'en-c1-12', NULL, 'comprehensive_test', 'listening', 'My grandfather always said that patience was a virtue.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông tôi vẫn thường nói rằng sự kiên nhẫn là một đức tính cao đẹp.","Mọi người đều nghĩ rằng vũ công trẻ tài năng này chắc chắn sẽ thành công.","Chợ địa phương của chúng tôi đang trở nên sầm uất trở lại vào mùa xuân này.","Chúng tôi đã nhượng bộ và đồng ý rời đi sớm hơn."]'::jsonb, 0, 'My grandfather always said that patience was a virtue. → Ông tôi vẫn thường nói rằng sự kiên nhẫn là một đức tính cao đẹp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_9', 'en-c1-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “illegal or unacceptable behaviour, especially by young people”?', '["slaughter","summon","outcast","delinquency"]'::jsonb, 3, 'delinquency (/dɪˈlɪŋkwənsi/) → hành vi vi phạm pháp luật hoặc không chuẩn mực, đặc biệt ở giới trẻ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_10', 'en-c1-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To kill animals, usually for food”?', '["revival","ration","delinquency","slaughter"]'::jsonb, 3, 'slaughter (/ˈslɔːtər/) → giết mổ; làm thịt', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_11', 'en-c1-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A fixed amount of food or supplies allowed to someone.”?', '["concession","pretentious","ration","alienation"]'::jsonb, 2, 'ration (/ˈræʃən/) → phần định lượng; khẩu phần', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_12', 'en-c1-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A morally good quality or morally good behaviour.”?', '["unprecedented","deception","virtue","destine"]'::jsonb, 2, 'virtue (/ˈvɝːtʃuː/) → hạnh kiểm; phẩm chất đạo đức tốt', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_13', 'en-c1-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the act of deliberately making someone believe something false”?', '["deception","virtue","patriotism","concerted"]'::jsonb, 0, 'deception (/dɪˈsepʃən/) → hành vi lừa dối; thủ đoạn đánh lừa', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
