INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_18', 'en-c1-12', NULL, 'comprehensive_test', 'reading', NULL, 'International humanitarian organisations provide essential supplies to communities affected by natural disasters and armed conflict.', 'Dựa vào câu trên, từ “humanitarian” có nghĩa phù hợp nhất là gì?', '["không thể thiếu, vô cùng quan trọng, thiết yếu","tiếng la ó om sòm; tiếng ồn ào; đòi hỏi bức xúc của công chúng","cơn co giật; cơn động kinh đột ngột","mang tính nhân đạo"]'::jsonb, 3, 'humanitarian: mang tính nhân đạo; nhà nhân đạo chủ nghĩa. Dịch cả câu: Các tổ chức nhân đạo quốc tế cung cấp các nhu yếu phẩm thiết yếu cho các cộng đồng bị ảnh hưởng bởi thiên tai và xung đột vũ trang.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_19', 'en-c1-12', NULL, 'comprehensive_test', 'reading', NULL, 'Conspicuous consumption can encourage unnecessary spending as people seek to display their wealth through expensive possessions.', 'Dựa vào câu trên, từ “conspicuous” có nghĩa phù hợp nhất là gì?', '["sức bền; sự chịu đựng; độ dẻo dai","dễ thấy; nổi bật; đập ngay vào mắt","sự mãn nguyện; cảm giác thỏa mãn","tội phản quốc"]'::jsonb, 1, 'conspicuous: dễ thấy; nổi bật; đập ngay vào mắt. Dịch cả câu: Tiêu dùng phô trương có thể cổ súy cho những khoản chi tiêu không cần thiết khi mọi người tìm cách thể hiện sự giàu có thông qua các món đồ đắt tiền.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_20', 'en-c1-12', NULL, 'comprehensive_test', 'reading', NULL, 'Powerful interest groups may hijack public debates, preventing communities from discussing their most urgent concerns.', 'Dựa vào câu trên, từ “hijack” có nghĩa phù hợp nhất là gì?', '["nhập thêm hàng; bổ sung hàng hóa","cắt cụt; phẫu thuật cắt bỏ bộ phận cơ thể","khống chế; cướp (phương tiện giao thông)","phép loại suy; sự so sánh tương đương"]'::jsonb, 2, 'hijack: khống chế; cướp (phương tiện giao thông); thao túng; chiếm đoạt (cho mục đích riêng). Dịch cả câu: Các nhóm lợi ích hùng mạnh có thể thao túng các cuộc tranh luận công khai, khiến các cộng đồng không thể thảo luận về các vấn đề cấp bách nhất của họ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_21', 'en-c1-12', NULL, 'comprehensive_test', 'reading', NULL, 'Many coastal communities face unprecedented challenges as rising sea levels threaten homes, infrastructure, and local livelihoods.', 'Dựa vào câu trên, từ “unprecedented” có nghĩa phù hợp nhất là gì?', '["nằm hoặc ngồi duỗi dài chân tay","chưa từng có; chưa từng tồn tại trước đây","vi sinh vật","sự tối tăm; bóng tối mờ mịt"]'::jsonb, 1, 'unprecedented: chưa từng có; chưa từng tồn tại trước đây. Dịch cả câu: Nhiều cộng đồng ven biển phải đối mặt với những thách thức chưa từng có khi mực nước biển dâng cao đe dọa nhà ở, cơ sở hạ tầng và sinh kế của người dân.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_22', 'en-c1-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “công bằng; hợp lý; công tâm”', '["propeller","squeal","equitable","civic"]'::jsonb, 2, 'công bằng; hợp lý; công tâm → equitable (/ˈekwɪtəbl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_23', 'en-c1-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự hồi phục; sự hồi sinh; sự thịnh hành trở lại”', '["rigorous","Orthodox","assurance","revival"]'::jsonb, 3, 'sự hồi phục; sự hồi sinh; sự thịnh hành trở lại → revival (/rɪˈvaɪvəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_12_24', 'en-c1-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dành sẵn; định sẵn cho tương lai”', '["indent","divine","paralyse","destine"]'::jsonb, 3, 'dành sẵn; định sẵn cho tương lai → destine (/ˈdestɪn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-13', 'en', 'Bài 13: Xã hội & Cộng đồng (8) - CEFR C1', 'CEFR C1', 'C1 · Xã hội', '27 từ vựng Tiếng Anh CEFR C1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5013, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mount', 'en-c1-13', 'mount', '/maʊnt/', 'C1', 'tăng dần; dâng lên; leo lên; lắp đặt; gắn chặt lên bề mặt; tổ chức; phát động; tiến hành', 'v.', 'mounting (adj.)', NULL, 'mount có thể dùng để chỉ áp lực dâng cao; mount a campaign nghĩa là phát động một chiến dịch.', 'Dirty dishes mounted up while our dishwasher was broken.', NULL, 'Bát đĩa bẩn cứ chất đống lên trong lúc máy rửa bát của chúng tôi bị hỏng.', '{"wordId":"mount","ukIpa":"/maʊnt/","usIpa":"/maʊnt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To increase gradually in amount, strength, or seriousness.","vi":"tăng dần; dâng lên; leo lên"},{"pos":"v.","en":"To attach something firmly to a surface or support.","vi":"lắp đặt; gắn chặt lên bề mặt"},{"pos":"v.","en":"To organize and begin an activity, campaign, or event.","vi":"tổ chức; phát động; tiến hành"}],"examples":[{"en":"Dirty dishes mounted up while our dishwasher was broken.","vi":"Bát đĩa bẩn cứ chất đống lên trong lúc máy rửa bát của chúng tôi bị hỏng.","audioKind":"ex"},{"en":"As pressure mounts to reduce emissions, governments must expand renewable energy production and improve energy efficiency.","vi":"Khi áp lực giảm phát thải ngày càng gia tăng, các chính phủ phải mở rộng sản xuất năng lượng tái tạo và nâng cao hiệu quả sử dụng năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"mounting pressure","vi":"áp lực ngày càng tăng"},{"en":"mount a campaign","vi":"phát động một chiến dịch"},{"en":"mount on a wall","vi":"gắn lên tường"}],"wordFamily":["mounting (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"mount có thể dùng để chỉ áp lực dâng cao; mount a campaign nghĩa là phát động một chiến dịch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_queer', 'en-c1-13', 'queer', '/kwɪr/', 'C1', 'lạ lùng; kỳ quái; thuộc cộng đồng người đồng tính, song tính, chuyển giới và đa dạng tính dục (khác với dị tính)', 'adj.', 'queerness (n.)', NULL, 'Nghĩa "lạ lùng" thuộc về cách dùng cũ; nghĩa chỉ giới tính/bản dạng nên tôn trọng cách tự xưng của người trong cuộc.', 'There was a queer rattling sound inside the cupboard.', NULL, 'Có một âm thanh lách cách kỳ lạ phát ra từ bên trong tủ đựng đồ.', '{"wordId":"queer","ukIpa":"/kwɪə/","usIpa":"/kwɪr/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"strange or unusual, in an old-fashioned use","vi":"lạ lùng; kỳ quái"},{"pos":"adj.","en":"describing sexual or gender identities outside heterosexual or conventional categories","vi":"thuộc cộng đồng người đồng tính, song tính, chuyển giới và đa dạng tính dục (khác với dị tính)"}],"examples":[{"en":"There was a queer rattling sound inside the cupboard.","vi":"Có một âm thanh lách cách kỳ lạ phát ra từ bên trong tủ đựng đồ.","audioKind":"ex"},{"en":"Museums increasingly include queer perspectives to reflect a broader range of experiences in their exhibitions.","vi":"Các bảo tàng ngày càng đưa vào các góc nhìn của cộng đồng queer nhằm phản ánh đa dạng trải nghiệm hơn trong các triển lãm của họ.","audioKind":"ex2"}],"collocations":[{"en":"a queer feeling","vi":"cảm giác lạ lùng"},{"en":"a queer sound","vi":"âm thanh kỳ lạ"},{"en":"queer identity","vi":"nhận dạng giới tính queer"}],"wordFamily":["queerness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa \"lạ lùng\" thuộc về cách dùng cũ; nghĩa chỉ giới tính/bản dạng nên tôn trọng cách tự xưng của người trong cuộc.","noteVi":"Khi dùng để chỉ bản dạng tình dục hoặc giới tính, có người tự hào nhận là queer, nhưng cũng có người coi từ này mang ý xúc phạm.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disclose', 'en-c1-13', 'disclose', '/dɪsˈkloʊz/', 'C1', 'tiết lộ; vạch trần; công khai', 'v.', 'disclosure (n.), undisclosed (adj.)', 'Đồng nghĩa: reveal, divulge · Trái nghĩa: conceal, withhold', 'Dùng cấu trúc disclose sth to sb; ngoài ra có thể đi kèm mệnh đề that.', 'The hotel would not disclose any details about its guests.', NULL, 'Khách sạn từ chối tiết lộ bất kỳ chi tiết nào về các vị khách của họ.', '{"wordId":"disclose","ukIpa":"/dɪsˈkləʊz/","usIpa":"/dɪsˈkloʊz/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to make previously private or unknown information available","vi":"tiết lộ; vạch trần; công khai"}],"examples":[{"en":"The hotel would not disclose any details about its guests.","vi":"Khách sạn từ chối tiết lộ bất kỳ chi tiết nào về các vị khách của họ.","audioKind":"ex"},{"en":"Companies should disclose how they collect personal data so that consumers can make informed decisions.","vi":"Các doanh nghiệp nên công khai cách họ thu thập dữ liệu cá nhân để người tiêu dùng có thể đưa ra quyết định sáng suốt.","audioKind":"ex2"}],"collocations":[{"en":"disclose information","vi":"tiết lộ thông tin"},{"en":"disclose details","vi":"tiết lộ chi tiết"},{"en":"disclose something to someone","vi":"tiết lộ điều gì cho ai"}],"wordFamily":["disclosure (n.)","undisclosed (adj.)"],"synonyms":["reveal","divulge"],"antonyms":["conceal","withhold"],"tipVi":"Dùng cấu trúc disclose sth to sb; ngoài ra có thể đi kèm mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discord', 'en-c1-13', 'discord', '/ˈdɪskɔːrd/', 'C1', 'sự bất hòa; sự chia rẽ; mối bất đồng; âm thanh không hòa hợp; tiếng chói tai', 'n.', 'discordant (adj.)', 'Đồng nghĩa: conflict, disagreement, disharmony · Trái nghĩa: harmony, agreement', 'Khi mang nghĩa bất hòa, từ này thường là danh từ không đếm được và mang sắc thái trang trọng hơn từ disagreement.', 'Arguments about chores caused discord among the flatmates.', NULL, 'Những cuộc cãi vã về việc nhà đã gây ra sự bất hòa giữa các bạn cùng phòng.', '{"wordId":"discord","ukIpa":"/ˈdɪskɔːd/","usIpa":"/ˈdɪskɔːrd/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Disagreement or conflict between people or groups.","vi":"sự bất hòa; sự chia rẽ; mối bất đồng"},{"pos":"n.","en":"A combination of musical sounds that clash unpleasantly.","vi":"âm thanh không hòa hợp; tiếng chói tai"}],"examples":[{"en":"Arguments about chores caused discord among the flatmates.","vi":"Những cuộc cãi vã về việc nhà đã gây ra sự bất hòa giữa các bạn cùng phòng.","audioKind":"ex"},{"en":"Unequal access to resources can fuel social discord, particularly when communities feel excluded from political decisions.","vi":"Sự tiếp cận tài nguyên không công bằng có thể châm ngòi cho những bất ổn xã hội, đặc biệt khi các cộng đồng cảm thấy mình bị gạt ra ngoài lề các quyết định chính trị.","audioKind":"ex2"}],"collocations":[{"en":"social discord","vi":"sự bất hòa trong xã hội"},{"en":"sow discord","vi":"gieo rắc bất hòa"},{"en":"a source of discord","vi":"nguồn gốc của sự bất hòa"},{"en":"marital discord","vi":"sự lục đục trong hôn nhân"}],"wordFamily":["discordant (adj.)"],"synonyms":["conflict","disagreement","disharmony"],"antonyms":["harmony","agreement"],"tipVi":"Khi mang nghĩa bất hòa, từ này thường là danh từ không đếm được và mang sắc thái trang trọng hơn từ disagreement.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inclusive', 'en-c1-13', 'inclusive', '/ɪnˈkluːsɪv/', 'C1', 'bao dung; mang tính hòa nhập; bao gồm toàn bộ chi phí; bao gồm cả điểm đầu và điểm cuối', 'adj.', 'include (v.), inclusion (n.), inclusiveness (n.)', 'Trái nghĩa: exclusive', 'inclusive of dùng để chỉ "bao gồm"; khi đi sau các khoảng ngày tháng, nó ngụ ý bao gồm cả hai mốc đầu và cuối.', 'Our inclusive dance class welcomes people of all abilities.', NULL, 'Lớp học khiêu vũ hòa nhập của chúng tôi chào đón mọi người ở mọi khả năng.', '{"wordId":"inclusive","ukIpa":"/ɪnˈkluːsɪv/","usIpa":"/ɪnˈkluːsɪv/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"welcoming people of different backgrounds and abilities","vi":"bao dung; mang tính hòa nhập"},{"pos":"adj.","en":"including all relevant costs","vi":"bao gồm toàn bộ chi phí"},{"pos":"adj.","en":"including both the first and last points of a range","vi":"bao gồm cả điểm đầu và điểm cuối"}],"examples":[{"en":"Our inclusive dance class welcomes people of all abilities.","vi":"Lớp học khiêu vũ hòa nhập của chúng tôi chào đón mọi người ở mọi khả năng.","audioKind":"ex"},{"en":"Schools should create inclusive learning environments where students with different needs can participate fully in classroom activities.","vi":"Các trường học nên tạo ra môi trường học tập hòa nhập, nơi học sinh có nhu cầu khác nhau có thể tham gia đầy đủ vào các hoạt động trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"inclusive education","vi":"giáo dục hòa nhập"},{"en":"an inclusive society","vi":"một xã hội hòa nhập"},{"en":"inclusive of tax","vi":"đã bao gồm thuế"},{"en":"an inclusive price","vi":"mức giá trọn gói"}],"wordFamily":["include (v.)","inclusion (n.)","inclusiveness (n.)"],"synonyms":[],"antonyms":["exclusive"],"tipVi":"inclusive of dùng để chỉ \"bao gồm\"; khi đi sau các khoảng ngày tháng, nó ngụ ý bao gồm cả hai mốc đầu và cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tactful', 'en-c1-13', 'tactful', '/ˈtæktfəl/', 'C1', 'khéo léo; tế nhị; lịch sự', 'adj.', 'tact (n.), tactfully (adv.), tactless (adj.), tactfulness (n.)', 'Đồng nghĩa: diplomatic, considerate · Trái nghĩa: tactless, insensitive', 'Nhấn mạnh sự khéo léo, biết quan tâm đến cảm xúc người khác, không phải là sự nhanh nhẹn trong phản ứng.', 'Her tactful reply saved everyone from an awkward argument.', NULL, 'Câu trả lời khéo léo của cô ấy đã giúp tất cả mọi người tránh được một cuộc tranh cãi khó xử.', '{"wordId":"tactful","ukIpa":"/ˈtæktfəl/","usIpa":"/ˈtæktfəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Careful not to upset or offend people.","vi":"khéo léo; tế nhị; lịch sự"}],"examples":[{"en":"Her tactful reply saved everyone from an awkward argument.","vi":"Câu trả lời khéo léo của cô ấy đã giúp tất cả mọi người tránh được một cuộc tranh cãi khó xử.","audioKind":"ex"},{"en":"Managers who provide tactful feedback can address performance problems while maintaining employees'' confidence and motivation.","vi":"Các nhà quản lý đưa ra phản hồi một cách khéo léo có thể giải quyết các vấn đề hiệu suất công việc mà vẫn duy trì được sự tự tin và động lực của nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"tactful approach","vi":"cách tiếp cận tế nhị"},{"en":"tactful response","vi":"câu trả lời khéo léo"},{"en":"tactful criticism","vi":"lời phê bình uyển chuyển"}],"wordFamily":["tact (n.)","tactfully (adv.)","tactless (adj.)","tactfulness (n.)"],"synonyms":["diplomatic","considerate"],"antonyms":["tactless","insensitive"],"tipVi":"Nhấn mạnh sự khéo léo, biết quan tâm đến cảm xúc người khác, không phải là sự nhanh nhẹn trong phản ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refuge', 'en-c1-13', 'refuge', '/ˈrefjuːdʒ/', 'C1', 'sự ẩn náu; sự bảo vệ (khỏi nguy hiểm, rắc rối, thời tiết xấu); nơi trú ẩn; chốn dung thân', 'n.', 'refugee (n.)', 'Đồng nghĩa: shelter, sanctuary', 'Cụm từ take/seek refuge in có nghĩa là "trú ẩn tại..."; refuge thường đóng vai trò là danh từ.', 'We took refuge under a bridge during the storm.', NULL, 'Chúng tôi đã tìm chỗ ẩn náu dưới một cây cầu trong trận bão.', '{"wordId":"refuge","ukIpa":"/ˈrefjuːdʒ/","usIpa":"/ˈrefjuːdʒ/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"protection from danger, trouble, or bad weather","vi":"sự ẩn náu; sự bảo vệ (khỏi nguy hiểm, rắc rối, thời tiết xấu)"},{"pos":"n.","en":"a safe place offering protection from danger or difficulty","vi":"nơi trú ẩn; chốn dung thân"}],"examples":[{"en":"We took refuge under a bridge during the storm.","vi":"Chúng tôi đã tìm chỗ ẩn náu dưới một cây cầu trong trận bão.","audioKind":"ex"},{"en":"Urban parks provide a refuge for wildlife as expanding cities gradually replace natural habitats with buildings.","vi":"Các công viên đô thị cung cấp nơi trú ẩn cho động vật hoang dã khi các thành phố ngày càng mở rộng và dần thay thế môi trường sống tự nhiên bằng các tòa nhà.","audioKind":"ex2"}],"collocations":[{"en":"take refuge","vi":"tìm nơi ẩn náu"},{"en":"seek refuge","vi":"tìm sự bảo vệ"},{"en":"a refuge from","vi":"nơi tránh khỏi..."}],"wordFamily":["refugee (n.)"],"synonyms":["shelter","sanctuary"],"antonyms":[],"tipVi":"Cụm từ take/seek refuge in có nghĩa là \"trú ẩn tại...\"; refuge thường đóng vai trò là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resilient', 'en-c1-13', 'resilient', '/rɪˈzɪliənt/', 'C1', 'kiên cường; có khả năng phục hồi nhanh; có độ đàn hồi; dai', 'adj.', 'resilience (n.), resiliently (adv.)', 'Đồng nghĩa: tough, adaptable · Trái nghĩa: fragile', 'Có thể dùng để mô tả sự kiên cường của con người hoặc nền kinh tế, hoặc dùng để chỉ tính đàn hồi của vật liệu.', 'These resilient plants recovered quickly after the summer drought.', NULL, 'Những loài thực vật kiên cường này đã hồi phục nhanh chóng sau đợt hạn hán mùa hè.', '{"wordId":"resilient","ukIpa":"/rɪˈzɪliənt/","usIpa":"/rɪˈzɪliənt/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Able to recover quickly after difficulties or damage","vi":"kiên cường; có khả năng phục hồi nhanh"},{"pos":"adj.","en":"Able to return to its original shape after being bent","vi":"có độ đàn hồi; dai"}],"examples":[{"en":"These resilient plants recovered quickly after the summer drought.","vi":"Những loài thực vật kiên cường này đã hồi phục nhanh chóng sau đợt hạn hán mùa hè.","audioKind":"ex"},{"en":"Investing in local support networks can help communities become more resilient to economic and environmental shocks.","vi":"Đầu tư vào các mạng lưới hỗ trợ địa phương có thể giúp cộng đồng có khả năng chống chịu tốt hơn trước các cú sốc kinh tế và môi trường.","audioKind":"ex2"}],"collocations":[{"en":"resilient communities","vi":"cộng đồng có sức chống chịu cao"},{"en":"resilient economy","vi":"nền kinh tế có tính chống chịu"},{"en":"resilient to shocks","vi":"chống chịu được các cú sốc"},{"en":"resilient material","vi":"vật liệu có độ đàn hồi"}],"wordFamily":["resilience (n.)","resiliently (adv.)"],"synonyms":["tough","adaptable"],"antonyms":["fragile"],"tipVi":"Có thể dùng để mô tả sự kiên cường của con người hoặc nền kinh tế, hoặc dùng để chỉ tính đàn hồi của vật liệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_misuse', 'en-c1-13', 'misuse', '/ˌmɪsˈjuːz/', 'C1', 'dùng sai; lạm dụng; sự dùng sai; sự lạm dụng', 'v.', 'use (v.), useful (adj.), useless (adj.)', 'Đồng nghĩa: abuse', 'Động từ đọc đuôi / z /, danh từ đọc đuôi / s /.', 'You could damage that knife if you misuse it.', NULL, 'Bạn có thể làm hỏng con dao đó nếu dùng nó không đúng cách.', '{"wordId":"misuse","ukIpa":"/ˌmɪsˈjuːz/","usIpa":"/ˌmɪsˈjuːz/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To use something incorrectly or for a harmful purpose.","vi":"dùng sai; lạm dụng"},{"pos":"n.","en":"The incorrect or harmful use of something.","vi":"sự dùng sai; sự lạm dụng"}],"examples":[{"en":"You could damage that knife if you misuse it.","vi":"Bạn có thể làm hỏng con dao đó nếu dùng nó không đúng cách.","audioKind":"ex"},{"en":"Organisations that misuse personal data risk losing public trust and may face substantial legal penalties.","vi":"Các tổ chức lạm dụng dữ liệu cá nhân có nguy cơ mất đi lòng tin của công chúng và có thể phải đối mặt với các hình phạt pháp lý nặng nề.","audioKind":"ex2"}],"collocations":[{"en":"misuse personal data","vi":"lạm dụng dữ liệu cá nhân"},{"en":"misuse of power","vi":"lạm dụng quyền lực"},{"en":"misuse of resources","vi":"sử dụng tài nguyên trái phép"}],"wordFamily":["use (v.)","useful (adj.)","useless (adj.)"],"synonyms":["abuse"],"antonyms":[],"tipVi":"Động từ đọc đuôi / z /, danh từ đọc đuôi / s /.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_legitimate', 'en-c1-13', 'legitimate', '/lɪˈdʒɪtəmət/', 'C1', 'hợp pháp; hợp hiến; chính đáng; hợp lý', 'adj.', 'legitimacy (n.), legitimately (adv.), legitimize (v.), illegitimate (adj.)', 'Đồng nghĩa: lawful, valid · Trái nghĩa: illegitimate', 'Có thể dùng để chỉ việc được pháp luật cho phép, hoặc chỉ lý do, mối lo ngại là hợp lý.', 'Selling homemade bread is a legitimate business here.', NULL, 'Bán bánh mì tự làm là một hoạt động kinh doanh hợp pháp ở đây.', '{"wordId":"legitimate","ukIpa":"/lɪˈdʒɪtɪmət/","usIpa":"/lɪˈdʒɪtəmət/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Allowed by law or accepted rules.","vi":"hợp pháp; hợp hiến"},{"pos":"adj.","en":"Fair, reasonable, and supported by good reasons.","vi":"chính đáng; hợp lý"}],"examples":[{"en":"Selling homemade bread is a legitimate business here.","vi":"Bán bánh mì tự làm là một hoạt động kinh doanh hợp pháp ở đây.","audioKind":"ex"},{"en":"Residents have legitimate concerns about the impact of airport expansion on local air quality.","vi":"Cư dân có những lo ngại chính đáng về tác động của việc mở rộng sân bay đối với chất lượng không khí địa phương.","audioKind":"ex2"}],"collocations":[{"en":"legitimate business","vi":"việc kinh doanh hợp pháp"},{"en":"legitimate concerns","vi":"những lo ngại chính đáng"},{"en":"legitimate reason","vi":"lý do chính đáng"},{"en":"legitimate authority","vi":"thẩm quyền hợp pháp"}],"wordFamily":["legitimacy (n.)","legitimately (adv.)","legitimize (v.)","illegitimate (adj.)"],"synonyms":["lawful","valid"],"antonyms":["illegitimate"],"tipVi":"Có thể dùng để chỉ việc được pháp luật cho phép, hoặc chỉ lý do, mối lo ngại là hợp lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fanatic', 'en-c1-13', 'fanatic', '/fəˈnætɪk/', 'C1', 'người cuồng nhiệt; tín đồ (của một hoạt động, sở thích); kẻ cuồng tín; người cố chấp', 'n.', 'fanatical (adj.), fanatically (adv.), fanaticism (n.)', 'Đồng nghĩa: enthusiast, zealot', 'Trong ngữ cảnh sở thích có thể dùng thoải mái, thân thiện; nhưng trong ngữ cảnh tín ngưỡng, chính trị thường mang sắc thái tiêu cực (cuồng tín).', 'My cousin is a fitness fanatic who exercises daily.', NULL, 'Anh họ tôi là một người cuồng thể thao, tập thể dục mỗi ngày.', '{"wordId":"fanatic","ukIpa":"/fəˈnætɪk/","usIpa":"/fəˈnætɪk/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Someone who is extremely enthusiastic about an activity or interest.","vi":"người cuồng nhiệt; tín đồ (của một hoạt động, sở thích)"},{"pos":"n.","en":"Someone whose extreme beliefs make them reject other views.","vi":"kẻ cuồng tín; người cố chấp"}],"examples":[{"en":"My cousin is a fitness fanatic who exercises daily.","vi":"Anh họ tôi là một người cuồng thể thao, tập thể dục mỗi ngày.","audioKind":"ex"},{"en":"A political fanatic may reject reasonable debate, making it harder for communities to resolve disagreements peacefully.","vi":"Một kẻ cuồng tín chính trị có thể khước từ tranh luận lý trí, khiến cho các cộng đồng khó lòng giải quyết bất đồng một cách hòa bình hơn.","audioKind":"ex2"}],"collocations":[{"en":"fitness fanatic","vi":"tín đồ thể hình"},{"en":"football fanatic","vi":"người cuồng bóng đá"},{"en":"religious fanatic","vi":"kẻ cuồng tín tôn giáo"}],"wordFamily":["fanatical (adj.)","fanatically (adv.)","fanaticism (n.)"],"synonyms":["enthusiast","zealot"],"antonyms":[],"tipVi":"Trong ngữ cảnh sở thích có thể dùng thoải mái, thân thiện; nhưng trong ngữ cảnh tín ngưỡng, chính trị thường mang sắc thái tiêu cực (cuồng tín).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ultimatum', 'en-c1-13', 'ultimatum', '/ˌʌltɪˈmeɪtəm/', 'C1', 'tối hậu thư', 'n.', NULL, NULL, 'Thường dùng give someone an ultimatum; dạng số nhiều thường là ultimatums.', 'The coach gave us an ultimatum: attend practice or leave.', NULL, 'Huấn luyện viên đã đưa ra tối hậu thư cho chúng tôi: tham gia tập luyện hoặc rời đi.', '{"wordId":"ultimatum","ukIpa":"/ˌʌltɪˈmeɪtəm/","usIpa":"/ˌʌltɪˈmeɪtəm/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a final demand threatening consequences if it is not accepted","vi":"tối hậu thư"}],"examples":[{"en":"The coach gave us an ultimatum: attend practice or leave.","vi":"Huấn luyện viên đã đưa ra tối hậu thư cho chúng tôi: tham gia tập luyện hoặc rời đi.","audioKind":"ex"},{"en":"The council issued an ultimatum requiring the factory to improve waste treatment or face closure.","vi":"Hội đồng thành phố đã đưa ra tối hậu thư yêu cầu nhà máy cải thiện việc xử lý chất thải nếu không muốn đối mặt với nguy cơ đóng cửa.","audioKind":"ex2"}],"collocations":[{"en":"issue an ultimatum","vi":"đưa ra tối hậu thư"},{"en":"give someone an ultimatum","vi":"ra tối hậu thư cho ai đó"},{"en":"reject an ultimatum","vi":"từ chối tối hậu thư"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng give someone an ultimatum; dạng số nhiều thường là ultimatums.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oppression', 'en-c1-13', 'oppression', '/əˈpreʃən/', 'C1', 'sự áp bức; sự đàn áp', 'n.', 'oppress (v.), oppressive (adj.), oppressed (adj.), oppressor (n.)', 'Đồng nghĩa: tyranny · Trái nghĩa: liberation', 'Thường là danh từ không đếm được; động từ tương ứng là oppress.', 'Her grandparents told stories about life under oppression.', NULL, 'Ông bà cô ấy đã kể những câu chuyện về cuộc sống dưới ách áp bức.', '{"wordId":"oppression","ukIpa":"/əˈpreʃən/","usIpa":"/əˈpreʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Cruel or unfair control that denies people freedom and rights.","vi":"sự áp bức; sự đàn áp"}],"examples":[{"en":"Her grandparents told stories about life under oppression.","vi":"Ông bà cô ấy đã kể những câu chuyện về cuộc sống dưới ách áp bức.","audioKind":"ex"},{"en":"Independent courts play a vital role in protecting vulnerable groups from oppression and defending basic freedoms.","vi":"Các tòa án độc lập đóng vai trò quan trọng trong việc bảo vệ các nhóm dễ bị tổn thương khỏi sự áp bức và bảo vệ các quyền tự do cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"political oppression","vi":"sự áp bức chính trị"},{"en":"resist oppression","vi":"chống lại sự áp bức"},{"en":"freedom from oppression","vi":"tự do khỏi sự áp bức"}],"wordFamily":["oppress (v.)","oppressive (adj.)","oppressed (adj.)","oppressor (n.)"],"synonyms":["tyranny"],"antonyms":["liberation"],"tipVi":"Thường là danh từ không đếm được; động từ tương ứng là oppress.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proxy', 'en-c1-13', 'proxy', '/ˈprɑːksi/', 'C1', 'người đại diện; người ủy quyền; chỉ số thay thế; vật thay thế; máy chủ trung gian', 'n.', NULL, 'Đồng nghĩa: representative, substitute', 'by proxy chỉ thông qua người đại diện; a proxy for có thể chỉ chỉ số thay thế.', 'My sister acted as my proxy at the meeting.', NULL, 'Chị tôi đã làm đại diện cho tôi tại cuộc họp.', '{"wordId":"proxy","ukIpa":"/ˈprɒksi/","usIpa":"/ˈprɑːksi/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"someone authorised to act or vote for another person","vi":"người đại diện; người ủy quyền"},{"pos":"n.","en":"something used to represent or measure something else indirectly","vi":"chỉ số thay thế; vật thay thế"},{"pos":"n.","en":"a server that passes requests between users and other servers","vi":"máy chủ trung gian"}],"examples":[{"en":"My sister acted as my proxy at the meeting.","vi":"Chị tôi đã làm đại diện cho tôi tại cuộc họp.","audioKind":"ex"},{"en":"Researchers sometimes use household income as a proxy for living standards, although it provides an incomplete picture.","vi":"Các nhà nghiên cứu đôi khi sử dụng thu nhập hộ gia đình làm chỉ số thay thế cho mức sống, mặc dù nó cung cấp một bức tranh chưa đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"vote by proxy","vi":"bỏ phiếu ủy quyền"},{"en":"act as a proxy","vi":"đóng vai trò là người đại diện"},{"en":"a proxy for","vi":"chỉ số thay thế cho"},{"en":"proxy server","vi":"máy chủ trung gian"}],"wordFamily":[],"synonyms":["representative","substitute"],"antonyms":[],"tipVi":"by proxy chỉ thông qua người đại diện; a proxy for có thể chỉ chỉ số thay thế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restrain', 'en-c1-13', 'restrain', '/rɪˈstreɪn/', 'C1', 'kiểmز; kìm chế; kiềm chế; hạn chế', 'v.', 'restraint (n.), restrained (adj.), unrestrained (adj.)', 'Đồng nghĩa: control, hold back · Trái nghĩa: release', 'Thường dùng restrain sb from doing, thể hiện việc ngăn cản ai đó làm việc gì.', 'She gently restrained the dog from chasing a squirrel.', NULL, 'Cô ấy nhẹ nhàng giữ con chó lại để nó không đuổi theo con sóc.', '{"wordId":"restrain","ukIpa":"/rɪˈstreɪn/","usIpa":"/rɪˈstreɪn/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to prevent someone or something from moving or acting freely","vi":"kiểmز; kìm chế"},{"pos":"v.","en":"to control a feeling, reaction, or increase","vi":"kiềm chế; hạn chế"}],"examples":[{"en":"She gently restrained the dog from chasing a squirrel.","vi":"Cô ấy nhẹ nhàng giữ con chó lại để nó không đuổi theo con sóc.","audioKind":"ex"},{"en":"Governments may use tighter lending rules to restrain excessive borrowing and reduce risks in the housing market.","vi":"Chính phủ có thể áp dụng các quy định chovay chặt chẽ hơn để kiềm chế tình trạng vay mượn quá mức và giảm thiểu rủi ro trên thị trường nhà ở.","audioKind":"ex2"}],"collocations":[{"en":"restrain someone from doing something","vi":"ngăn cản ai đó làm điều gì"},{"en":"restrain anger","vi":"kiềm chế sự giận dữ"},{"en":"restrain spending","vi":"kiểm soát chi tiêu"}],"wordFamily":["restraint (n.)","restrained (adj.)","unrestrained (adj.)"],"synonyms":["control","hold back"],"antonyms":["release"],"tipVi":"Thường dùng restrain sb from doing, thể hiện việc ngăn cản ai đó làm việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mingle', 'en-c1-13', 'mingle', '/ˈmɪŋɡəl/', 'C1', 'hòa quyện; trộn lẫn; giao du; trò chuyện xã giao', 'v.', NULL, 'Đồng nghĩa: mix, socialize', 'Mingle with vừa có thể dùng khi chỉ sự hòa trộn giữa các vật, vừa dùng khi chỉ việc giao tiếp với con người.', 'The smell of fresh bread mingled with roasted coffee.', NULL, 'Hương thơm của bánh mì tươi hòa quyện cùng mùi cà phê rang.', '{"wordId":"mingle","ukIpa":"/ˈmɪŋɡəl/","usIpa":"/ˈmɪŋɡəl/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"mix together while remaining partly distinct","vi":"hòa quyện; trộn lẫn"},{"pos":"v.","en":"move around a group and talk to different people","vi":"giao du; trò chuyện xã giao"}],"examples":[{"en":"The smell of fresh bread mingled with roasted coffee.","vi":"Hương thơm của bánh mì tươi hòa quyện cùng mùi cà phê rang.","audioKind":"ex"},{"en":"Community festivals allow residents from different backgrounds to mingle, helping build trust and a stronger sense of belonging.","vi":"Các lễ hội cộng đồng tạo cơ hội cho cư dân từ những hoàn cảnh khác nhau giao lưu, giúp xây dựng lòng tin và củng cố ý thức thuộc về cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"mingle with","vi":"hòa quyện với; giao lưu với"},{"en":"mingle with guests","vi":"trò chuyện cùng khách mời"},{"en":"mingle freely","vi":"tự do giao tiếp"}],"wordFamily":[],"synonyms":["mix","socialize"],"antonyms":[],"tipVi":"Mingle with vừa có thể dùng khi chỉ sự hòa trộn giữa các vật, vừa dùng khi chỉ việc giao tiếp với con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reckless', 'en-c1-13', 'reckless', '/ˈrekləs/', 'C1', 'liều lĩnh; bất cẩn; không màng hậu quả', 'adj.', 'recklessly (adv.), recklessness (n.)', 'Đồng nghĩa: rash, heedless · Trái nghĩa: cautious, prudent', 'Mang sắc thái nghiêm trọng hơn careless, nhấn mạnh việc nhận thức được nguy hiểm nhưng vẫn cố tình phớt lờ hậu quả.', 'Cycling downhill without brakes was a reckless thing to do.', NULL, 'Đạp xe đổ dốc mà không có phanh là một hành động vô cùng liều lĩnh.', '{"wordId":"reckless","ukIpa":"/ˈrekləs/","usIpa":"/ˈrekləs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Ignoring danger or the possible harmful results of an action","vi":"liều lĩnh; bất cẩn; không màng hậu quả"}],"examples":[{"en":"Cycling downhill without brakes was a reckless thing to do.","vi":"Đạp xe đổ dốc mà không có phanh là một hành động vô cùng liều lĩnh.","audioKind":"ex"},{"en":"Reckless lending by financial institutions can expose households to debts they have little realistic chance of repaying.","vi":"Việc cho vay bất chấp rủi ro từ các tổ chức tài chính có thể đẩy nhiều hộ gia đình vào những khoản nợ mà họ gần như không có khả năng chi trả.","audioKind":"ex2"}],"collocations":[{"en":"reckless driving","vi":"lái xe liều lĩnh"},{"en":"reckless behaviour","vi":"hành vi liều lĩnh"},{"en":"reckless spending","vi":"tiêu xài hoang phí không nghĩ hậu quả"},{"en":"reckless disregard for safety","vi":"sự coi thường trắng trợn đối với an toàn"}],"wordFamily":["recklessly (adv.)","recklessness (n.)"],"synonyms":["rash","heedless"],"antonyms":["cautious","prudent"],"tipVi":"Mang sắc thái nghiêm trọng hơn careless, nhấn mạnh việc nhận thức được nguy hiểm nhưng vẫn cố tình phớt lờ hậu quả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_civilize', 'en-c1-13', 'civilize', '/ˈsɪvəlaɪz/', 'C1', 'làm cho có văn hóa; khai hóa; làm cho có giáo dưỡng', 'v.', 'civilization (n.), civilized (adj.), uncivilized (adj.)', NULL, 'Khi nói về các dân tộc, từ này dễ mang sắc thái ưu việt hoặc thực dân; ở Anh, từ này còn được viết là civilise.', 'My aunt jokes that dancing lessons will civilize me.', NULL, 'Cô tôi nói đùa rằng các lớp học nhảy sẽ giúp tôi trở nên có giáo dưỡng hơn.', '{"wordId":"civilize","ukIpa":"/ˈsɪvəlaɪz/","usIpa":"/ˈsɪvəlaɪz/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to make people behave more politely or develop organized societies","vi":"làm cho có văn hóa; khai hóa; làm cho có giáo dưỡng"}],"examples":[{"en":"My aunt jokes that dancing lessons will civilize me.","vi":"Cô tôi nói đùa rằng các lớp học nhảy sẽ giúp tôi trở nên có giáo dưỡng hơn.","audioKind":"ex"},{"en":"Historical claims that foreign rule would civilize local populations often concealed unequal power relations and cultural prejudice.","vi":"Các luận điệu lịch sử cho rằng sự cai trị của nước ngoài sẽ khai hóa người dân bản địa thường che giấu các mối quan hệ quyền lực bất bình đẳng và định kiến văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"civilize society","vi":"làm cho xã hội văn minh"},{"en":"attempt to civilize","vi":"cố gắng khai hóa"}],"wordFamily":["civilization (n.)","civilized (adj.)","uncivilized (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về các dân tộc, từ này dễ mang sắc thái ưu việt hoặc thực dân; ở Anh, từ này còn được viết là civilise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forfeit', 'en-c1-13', 'forfeit', '/ˈfɔːrfɪt/', 'C1', 'mất; bị tước quyền; tiền phạt; vật bị phạt; bị mất; bị tịch thu', 'v.', 'forfeiture (n.)', 'Đồng nghĩa: lose, surrender · Trái nghĩa: retain', 'Chủ ngữ thường là người mất tài sản, thay vì bên thực hiện việc tịch thu.', 'If you cancel now, you will forfeit your deposit.', NULL, 'Nếu bạn hủy ngay bây giờ, bạn sẽ bị mất tiền đặt cọc.', '{"wordId":"forfeit","ukIpa":"/ˈfɔːfɪt/","usIpa":"/ˈfɔːrfɪt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To lose something as a penalty for breaking a rule.","vi":"mất; bị tước quyền"},{"pos":"n.","en":"Something surrendered or done as a penalty, especially in games.","vi":"tiền phạt; vật bị phạt"},{"pos":"adj.","en":"Lost or required to be surrendered as a penalty.","vi":"bị mất; bị tịch thu"}],"examples":[{"en":"If you cancel now, you will forfeit your deposit.","vi":"Nếu bạn hủy ngay bây giờ, bạn sẽ bị mất tiền đặt cọc.","audioKind":"ex"},{"en":"Companies that repeatedly violate environmental regulations should forfeit their right to operate until they meet the required standards.","vi":"Các công ty nhiều lần vi phạm quy định môi trường nên bị tước quyền hoạt động cho đến khi đạt được các tiêu chuẩn yêu cầu.","audioKind":"ex2"}],"collocations":[{"en":"forfeit a deposit","vi":"mất tiền đặt cọc"},{"en":"forfeit the right to","vi":"mất quyền làm gì"},{"en":"pay a forfeit","vi":"nộp tiền phạt"},{"en":"forfeit a match","vi":"bị xử thua trận đấu"}],"wordFamily":["forfeiture (n.)"],"synonyms":["lose","surrender"],"antonyms":["retain"],"tipVi":"Chủ ngữ thường là người mất tài sản, thay vì bên thực hiện việc tịch thu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disloyalty', 'en-c1-13', 'disloyalty', '/dɪsˈlɔɪəlti/', 'C1', 'sự bất trung; sự phản bội', 'n.', 'disloyal (adj.), loyal (adj.), loyalty (n.)', 'Đồng nghĩa: unfaithfulness, betrayal · Trái nghĩa: loyalty, faithfulness', 'Đây là danh từ; tính từ tương ứng là disloyal, thường đi với giới từ to.', 'Sharing her friend''s private messages was an act of disloyalty.', NULL, 'Việc chia sẻ tin nhắn riêng tư của bạn mình là một hành động phản bội.', '{"wordId":"disloyalty","ukIpa":"/dɪsˈlɔɪəlti/","usIpa":"/dɪsˈlɔɪəlti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Failure to support someone or something you should remain faithful to","vi":"sự bất trung; sự phản bội"}],"examples":[{"en":"Sharing her friend''s private messages was an act of disloyalty.","vi":"Việc chia sẻ tin nhắn riêng tư của bạn mình là một hành động phản bội.","audioKind":"ex"},{"en":"Employees should be able to raise legitimate concerns without their managers accusing them of disloyalty.","vi":"Nhân viên nên có quyền nêu lên những lo ngại chính đáng mà không sợ bị quản lý buộc tội là bất trung.","audioKind":"ex2"}],"collocations":[{"en":"an act of disloyalty","vi":"hành động phản bội"},{"en":"disloyalty to someone","vi":"sự bất trung với ai đó"},{"en":"accuse someone of disloyalty","vi":"buộc tội ai đó không trung thành"}],"wordFamily":["disloyal (adj.)","loyal (adj.)","loyalty (n.)"],"synonyms":["unfaithfulness","betrayal"],"antonyms":["loyalty","faithfulness"],"tipVi":"Đây là danh từ; tính từ tương ứng là disloyal, thường đi với giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worthy', 'en-c1-13', 'worthy', '/ˈwɝːði/', 'C1', 'xứng đáng; đáng; đáng kính; đáng tôn trọng; có giá trị', 'adj.', 'worth (n.), worthiness (n.), unworthy (adj.)', 'Đồng nghĩa: deserving, admirable · Trái nghĩa: unworthy', 'Thường dùng cấu trúc worthy of; trong khi worth có thể đi thẳng với danh từ hoặc danh động từ.', 'Your thoughtful suggestion is worthy of serious consideration.', NULL, 'Gợi ý thấu đáo của bạn rất đáng để cân nhắc nghiêm túc.', '{"wordId":"worthy","ukIpa":"/ˈwɜːði/","usIpa":"/ˈwɝːði/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"deserving a particular response, reward, or treatment","vi":"xứng đáng; đáng"},{"pos":"adj.","en":"good and deserving respect or support","vi":"đáng kính; đáng tôn trọng; có giá trị"}],"examples":[{"en":"Your thoughtful suggestion is worthy of serious consideration.","vi":"Gợi ý thấu đáo của bạn rất đáng để cân nhắc nghiêm túc.","audioKind":"ex"},{"en":"Community projects that improve access to education are worthy of sustained public investment.","vi":"Các dự án cộng đồng giúp cải thiện khả năng tiếp cận giáo dục rất xứng đáng nhận được đầu tư công lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"worthy of attention","vi":"đáng chú ý"},{"en":"a worthy cause","vi":"một nghĩa cử cao đẹp"},{"en":"worthy of respect","vi":"đáng kính trọng"}],"wordFamily":["worth (n.)","worthiness (n.)","unworthy (adj.)"],"synonyms":["deserving","admirable"],"antonyms":["unworthy"],"tipVi":"Thường dùng cấu trúc worthy of; trong khi worth có thể đi thẳng với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recipient', 'en-c1-13', 'recipient', '/rɪˈsɪpiənt/', 'C1', 'người nhận; bên tiếp nhận', 'n.', 'receive (v.), receipt (n.)', 'Đồng nghĩa: receiver · Trái nghĩa: sender', 'Thường dùng recipient of sth; chỉ người hoặc tổ chức nhận, không dùng cho vật chứa.', 'The recipient smiled as she opened the unexpected gift.', NULL, 'Người nhận mỉm cười khi mở món quà bất ngờ.', '{"wordId":"recipient","ukIpa":"/rɪˈsɪpiənt/","usIpa":"/rɪˈsɪpiənt/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"a person or organisation that receives something","vi":"người nhận; bên tiếp nhận"}],"examples":[{"en":"The recipient smiled as she opened the unexpected gift.","vi":"Người nhận mỉm cười khi mở món quà bất ngờ.","audioKind":"ex"},{"en":"Scholarship recipients often gain access to educational opportunities that would otherwise be beyond their financial means.","vi":"Những người nhận học bổng thường có cơ hội tiếp cận giáo dục mà nếu không có thì vượt quá khả năng tài chính của họ.","audioKind":"ex2"}],"collocations":[{"en":"the intended recipient","vi":"người nhận dự kiến"},{"en":"scholarship recipient","vi":"người nhận học bổng"},{"en":"aid recipient","vi":"người nhận cứu trợ"},{"en":"recipient of an award","vi":"người nhận giải thưởng"}],"wordFamily":["receive (v.)","receipt (n.)"],"synonyms":["receiver"],"antonyms":["sender"],"tipVi":"Thường dùng recipient of sth; chỉ người hoặc tổ chức nhận, không dùng cho vật chứa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oblige', 'en-c1-13', 'oblige', '/əˈblaɪdʒ/', 'C1', 'bắt buộc; làm cho phải tuân theo; giúp đỡ; làm vừa lòng', 'v.', 'obligation (n.), obligatory (adj.), obliging (adj.)', 'Đồng nghĩa: compel, require', 'Cấu trúc be obliged to do diễn tả việc bị bắt buộc hoặc có nghĩa vụ phải làm gì đó.', 'The sudden storm obliged us to stay indoors.', NULL, 'Cơn bão bất chợt đã buộc chúng tôi phải ở trong nhà.', '{"wordId":"oblige","ukIpa":"/əˈblaɪdʒ/","usIpa":"/əˈblaɪdʒ/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"Require someone to act because of rules or circumstances","vi":"bắt buộc; làm cho phải tuân theo"},{"pos":"v.","en":"Help someone by doing what they ask","vi":"giúp đỡ; làm vừa lòng"}],"examples":[{"en":"The sudden storm obliged us to stay indoors.","vi":"Cơn bão bất chợt đã buộc chúng tôi phải ở trong nhà.","audioKind":"ex"},{"en":"Environmental regulations oblige manufacturers to reduce harmful emissions and report their progress to public authorities.","vi":"Các quy định về môi trường buộc các nhà sản xuất phải giảm thiểu khí thải độc hại và báo cáo tiến độ cho cơ quan chức năng.","audioKind":"ex2"}],"collocations":[{"en":"be obliged to do something","vi":"bắt buộc phải làm gì"},{"en":"happy to oblige","vi":"rất sẵn lòng giúp đỡ"},{"en":"much obliged","vi":"vô cùng biết ơn"}],"wordFamily":["obligation (n.)","obligatory (adj.)","obliging (adj.)"],"synonyms":["compel","require"],"antonyms":[],"tipVi":"Cấu trúc be obliged to do diễn tả việc bị bắt buộc hoặc có nghĩa vụ phải làm gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solidarity', 'en-c1-13', 'solidarity', '/ˌsɑːləˈdærəti/', 'C1', 'tình đoàn kết; sự gắn kết; sự ủng hộ lẫn nhau', 'n.', 'solidary (adj.)', 'Đồng nghĩa: unity, togetherness · Trái nghĩa: division', 'Thường đi với giới từ with, thể hiện sự đoàn kết với một cá nhân hoặc nhóm người.', 'Neighbours showed solidarity by repairing the damaged playground together.', NULL, 'Những người hàng xóm đã thể hiện tình đoàn kết bằng cách cùng nhau sửa chữa khu vui chơi bị hỏng.', '{"wordId":"solidarity","ukIpa":"/ˌsɒlɪˈdærəti/","usIpa":"/ˌsɑːləˈdærəti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Unity and mutual support among people with shared interests.","vi":"tình đoàn kết; sự gắn kết; sự ủng hộ lẫn nhau"}],"examples":[{"en":"Neighbours showed solidarity by repairing the damaged playground together.","vi":"Những người hàng xóm đã thể hiện tình đoàn kết bằng cách cùng nhau sửa chữa khu vui chơi bị hỏng.","audioKind":"ex"},{"en":"Community projects can strengthen social solidarity by bringing residents from different backgrounds together to solve shared problems.","vi":"Các dự án cộng đồng có thể củng cố sự đoàn kết xã hội bằng cách quy tụ cư dân từ các hoàn cảnh khác nhau để cùng giải quyết các vấn đề chung.","audioKind":"ex2"}],"collocations":[{"en":"show solidarity with","vi":"thể hiện tình đoàn kết với"},{"en":"in solidarity with","vi":"đoàn kết với"},{"en":"social solidarity","vi":"tình đoàn kết xã hội"}],"wordFamily":["solidary (adj.)"],"synonyms":["unity","togetherness"],"antonyms":["division"],"tipVi":"Thường đi với giới từ with, thể hiện sự đoàn kết với một cá nhân hoặc nhóm người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_defiant', 'en-c1-13', 'defiant', '/dɪˈfaɪ.ənt/', 'C1', 'có tính thách thức; công khai chống đối; không tuân lệnh', 'adj.', 'defy (v.), defiance (n.), defiantly (adv.)', 'Đồng nghĩa: rebellious, disobedient · Trái nghĩa: obedient, compliant', 'Nét nghĩa cốt lõi là sự bất tuân đối với quyền lực, không chỉ đơn thuần là ăn nói thô lỗ.', 'The defiant child folded her arms and refused to leave.', NULL, 'Đứa trẻ cứng đầu khoanh tay lại và kiên quyết không chịu rời đi.', '{"wordId":"defiant","ukIpa":"/dɪˈfaɪ.ənt/","usIpa":"/dɪˈfaɪ.ənt/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Openly refusing to obey someone or accept their authority","vi":"có tính thách thức; công khai chống đối; không tuân lệnh"}],"examples":[{"en":"The defiant child folded her arms and refused to leave.","vi":"Đứa trẻ cứng đầu khoanh tay lại và kiên quyết không chịu rời đi.","audioKind":"ex"},{"en":"Residents remained defiant when officials proposed closing the community centre, organising peaceful gatherings to oppose the decision.","vi":"Cư dân vẫn giữ thái độ chống đối khi các quan chức đề xuất đóng cửa trung tâm cộng đồng, tổ chức các cuộc tụ tập ôn hòa để phản đối quyết định này.","audioKind":"ex2"}],"collocations":[{"en":"a defiant attitude","vi":"thái độ chống đối"},{"en":"remain defiant","vi":"vẫn giữ thái độ không khuất phục"},{"en":"a defiant gesture","vi":"cử chỉ thách thức"}],"wordFamily":["defy (v.)","defiance (n.)","defiantly (adv.)"],"synonyms":["rebellious","disobedient"],"antonyms":["obedient","compliant"],"tipVi":"Nét nghĩa cốt lõi là sự bất tuân đối với quyền lực, không chỉ đơn thuần là ăn nói thô lỗ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_condemnation', 'en-c1-13', 'condemnation', '/ˌkɑːndemˈneɪʃən/', 'C1', 'sự lên án; sự chỉ trích mạnh mẽ; án phạt; lời tuyên án không an toàn', 'n.', 'condemn (v.), condemnable (adj.)', 'Đồng nghĩa: denunciation, censure · Trái nghĩa: approval, praise', 'Thường dùng cấu trúc condemnation of sth; mang sắc thái mạnh hơn từ criticism.', 'His cruel remarks drew condemnation from everyone at dinner.', NULL, 'Những lời nhận xét cay nghiệt của anh ấy đã vấp phải sự lên án từ tất cả mọi người trong bữa tối.', '{"wordId":"condemnation","ukIpa":"/ˌkɒndemˈneɪʃən/","usIpa":"/ˌkɑːndemˈneɪʃən/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"An expression of strong disapproval","vi":"sự lên án; sự chỉ trích mạnh mẽ"},{"pos":"n.","en":"An official judgment imposing punishment or declaring something unsafe","vi":"án phạt; lời tuyên án không an toàn"}],"examples":[{"en":"His cruel remarks drew condemnation from everyone at dinner.","vi":"Những lời nhận xét cay nghiệt của anh ấy đã vấp phải sự lên án từ tất cả mọi người trong bữa tối.","audioKind":"ex"},{"en":"The destruction of protected forests has attracted widespread condemnation from environmental groups and local communities.","vi":"Việc tàn phá các khu rừng được bảo vệ đã thu hút sự lên án rộng rãi từ các nhóm bảo vệ môi trường và cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"widespread condemnation","vi":"sự lên án rộng rãi"},{"en":"strong condemnation","vi":"sự chỉ trích gay gắt"},{"en":"draw condemnation","vi":"gây ra sự lên án"},{"en":"condemnation of violence","vi":"sự lên án hành vi bạo lực"}],"wordFamily":["condemn (v.)","condemnable (adj.)"],"synonyms":["denunciation","censure"],"antonyms":["approval","praise"],"tipVi":"Thường dùng cấu trúc condemnation of sth; mang sắc thái mạnh hơn từ criticism.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ensue', 'en-c1-13', 'ensue', '/ɪnˈsuː/', 'C1', 'xảy ra sau đó; tiếp theo', 'v.', 'ensuing (adj.)', 'Đồng nghĩa: follow, result', 'Là từ trang trọng, nội động từ; không mang nghĩa là "theo đuổi".', 'A lively discussion ensued after dinner at our house.', NULL, 'Một cuộc thảo luận sôi nổi đã diễn ra sau bữa tối tại nhà chúng tôi.', '{"wordId":"ensue","ukIpa":"/ɪnˈsjuː/","usIpa":"/ɪnˈsuː/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To happen after something, often as its result.","vi":"xảy ra sau đó; tiếp theo"}],"examples":[{"en":"A lively discussion ensued after dinner at our house.","vi":"Một cuộc thảo luận sôi nổi đã diễn ra sau bữa tối tại nhà chúng tôi.","audioKind":"ex"},{"en":"If public services fail to meet growing demand, widespread dissatisfaction may ensue among local residents.","vi":"Nếu các dịch vụ công không đáp ứng được nhu cầu ngày càng tăng, sự bất mãn lan rộng có thể sẽ xảy ra trong cộng đồng cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"chaos ensues","vi":"hỗn loạn xảy ra sau đó"},{"en":"a debate ensues","vi":"một cuộc tranh luận diễn ra tiếp theo"},{"en":"ensue from","vi":"bắt nguồn từ; xảy ra do"}],"wordFamily":["ensuing (adj.)"],"synonyms":["follow","result"],"antonyms":[],"tipVi":"Là từ trang trọng, nội động từ; không mang nghĩa là \"theo đuổi\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_13_1', 'en-c1-13', 'Cách dùng “fanatic” (n.) — người cuồng nhiệt; tín đồ (của một hoạt động, sở thích)', 'fitness fanatic  ·  football fanatic  ·  religious fanatic', 'Trong ngữ cảnh sở thích có thể dùng thoải mái, thân thiện; nhưng trong ngữ cảnh tín ngưỡng, chính trị thường mang sắc thái tiêu cực (cuồng tín).', 'Họ từ (Word Family): fanatical (adj.), fanatically (adv.), fanaticism (n.) | Đồng nghĩa: enthusiast, zealot', '[{"hanzi":"My cousin is a fitness fanatic who exercises daily.","pinyin":"","meaning":"Anh họ tôi là một người cuồng thể thao, tập thể dục mỗi ngày."},{"hanzi":"A political fanatic may reject reasonable debate, making it harder for communities to resolve disagreements peacefully.","pinyin":"","meaning":"Một kẻ cuồng tín chính trị có thể khước từ tranh luận lý trí, khiến cho các cộng đồng khó lòng giải quyết bất đồng một cách hòa bình hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_13_2', 'en-c1-13', 'Cách dùng “queer” (adj.) — lạ lùng; kỳ quái', 'a queer feeling  ·  a queer sound  ·  queer identity', 'Nghĩa "lạ lùng" thuộc về cách dùng cũ; nghĩa chỉ giới tính/bản dạng nên tôn trọng cách tự xưng của người trong cuộc.', 'Họ từ (Word Family): queerness (n.)', '[{"hanzi":"There was a queer rattling sound inside the cupboard.","pinyin":"","meaning":"Có một âm thanh lách cách kỳ lạ phát ra từ bên trong tủ đựng đồ."},{"hanzi":"Museums increasingly include queer perspectives to reflect a broader range of experiences in their exhibitions.","pinyin":"","meaning":"Các bảo tàng ngày càng đưa vào các góc nhìn của cộng đồng queer nhằm phản ánh đa dạng trải nghiệm hơn trong các triển lãm của họ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_13_3', 'en-c1-13', 'Cách dùng “reckless” (adj.) — liều lĩnh; bất cẩn; không màng hậu quả', 'reckless driving  ·  reckless behaviour  ·  reckless spending', 'Mang sắc thái nghiêm trọng hơn careless, nhấn mạnh việc nhận thức được nguy hiểm nhưng vẫn cố tình phớt lờ hậu quả.', 'Họ từ (Word Family): recklessly (adv.), recklessness (n.) | Đồng nghĩa: rash, heedless · Trái nghĩa: cautious, prudent', '[{"hanzi":"Cycling downhill without brakes was a reckless thing to do.","pinyin":"","meaning":"Đạp xe đổ dốc mà không có phanh là một hành động vô cùng liều lĩnh."},{"hanzi":"Reckless lending by financial institutions can expose households to debts they have little realistic chance of repaying.","pinyin":"","meaning":"Việc cho vay bất chấp rủi ro từ các tổ chức tài chính có thể đẩy nhiều hộ gia đình vào những khoản nợ mà họ gần như không có khả năng chi trả."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_13_4', 'en-c1-13', 'Cách dùng “discord” (n.) — sự bất hòa; sự chia rẽ; mối bất đồng', 'social discord  ·  sow discord  ·  a source of discord', 'Khi mang nghĩa bất hòa, từ này thường là danh từ không đếm được và mang sắc thái trang trọng hơn từ disagreement.', 'Họ từ (Word Family): discordant (adj.) | Đồng nghĩa: conflict, disagreement, disharmony · Trái nghĩa: harmony, agreement', '[{"hanzi":"Arguments about chores caused discord among the flatmates.","pinyin":"","meaning":"Những cuộc cãi vã về việc nhà đã gây ra sự bất hòa giữa các bạn cùng phòng."},{"hanzi":"Unequal access to resources can fuel social discord, particularly when communities feel excluded from political decisions.","pinyin":"","meaning":"Sự tiếp cận tài nguyên không công bằng có thể châm ngòi cho những bất ổn xã hội, đặc biệt khi các cộng đồng cảm thấy mình bị gạt ra ngoài lề các quyết định chính trị."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_13_1', 'en-c1-13', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
