INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_1_2', 'ten_c1_13_1', 'queer', 'There was a queer rattling sound inside the cupboard.', 'There was a queer rattling sound inside the cupboard.', '/kwɪr/', 'Có một âm thanh lách cách kỳ lạ phát ra từ bên trong tủ đựng đồ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_1_3', 'ten_c1_13_1', 'disclose', 'The hotel would not disclose any details about its guests.', 'The hotel would not disclose any details about its guests.', '/dɪsˈkloʊz/', 'Khách sạn từ chối tiết lộ bất kỳ chi tiết nào về các vị khách của họ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_1_4', 'ten_c1_13_1', 'discord', 'Arguments about chores caused discord among the flatmates.', 'Arguments about chores caused discord among the flatmates.', '/ˈdɪskɔːrd/', 'Những cuộc cãi vã về việc nhà đã gây ra sự bất hòa giữa các bạn cùng phòng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_1_5', 'ten_c1_13_1', 'inclusive', 'Our inclusive dance class welcomes people of all abilities.', 'Our inclusive dance class welcomes people of all abilities.', '/ɪnˈkluːsɪv/', 'Lớp học khiêu vũ hòa nhập của chúng tôi chào đón mọi người ở mọi khả năng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_1_6', 'ten_c1_13_1', 'tactful', 'Her tactful reply saved everyone from an awkward argument.', 'Her tactful reply saved everyone from an awkward argument.', '/ˈtæktfəl/', 'Câu trả lời khéo léo của cô ấy đã giúp tất cả mọi người tránh được một cuộc tranh cãi khó xử.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_1_7', 'ten_c1_13_1', 'refuge', 'We took refuge under a bridge during the storm.', 'We took refuge under a bridge during the storm.', '/ˈrefjuːdʒ/', 'Chúng tôi đã tìm chỗ ẩn náu dưới một cây cầu trong trận bão.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_1_8', 'ten_c1_13_1', 'resilient', 'These resilient plants recovered quickly after the summer drought.', 'These resilient plants recovered quickly after the summer drought.', '/rɪˈzɪliənt/', 'Những loài thực vật kiên cường này đã hồi phục nhanh chóng sau đợt hạn hán mùa hè.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_13_1_1', 'en-c1-13', 'ten_c1_13_1', 'listening', 'listening', 'Dirty dishes mounted up while our dishwasher was broken.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người nhận mỉm cười khi mở món quà bất ngờ.","Bát đĩa bẩn cứ chất đống lên trong lúc máy rửa bát của chúng tôi bị hỏng.","Những lời nhận xét cay nghiệt của anh ấy đã vấp phải sự lên án từ tất cả mọi người trong bữa tối.","Huấn luyện viên đã đưa ra tối hậu thư cho chúng tôi: tham gia tập luyện hoặc rời đi."]'::jsonb, 1, 'Dirty dishes mounted up while our dishwasher was broken. → Bát đĩa bẩn cứ chất đống lên trong lúc máy rửa bát của chúng tôi bị hỏng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_13_1_2', 'en-c1-13', 'ten_c1_13_1', 'listening', 'listening', 'There was a queer rattling sound inside the cupboard.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ông bà cô ấy đã kể những câu chuyện về cuộc sống dưới ách áp bức.","Cô ấy nhẹ nhàng giữ con chó lại để nó không đuổi theo con sóc.","Huấn luyện viên đã đưa ra tối hậu thư cho chúng tôi: tham gia tập luyện hoặc rời đi.","Có một âm thanh lách cách kỳ lạ phát ra từ bên trong tủ đựng đồ."]'::jsonb, 3, 'There was a queer rattling sound inside the cupboard. → Có một âm thanh lách cách kỳ lạ phát ra từ bên trong tủ đựng đồ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_13_1_3', 'en-c1-13', 'ten_c1_13_1', 'listening', 'listening', 'The hotel would not disclose any details about its guests.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một cuộc thảo luận sôi nổi đã diễn ra sau bữa tối tại nhà chúng tôi.","Anh họ tôi là một người cuồng thể thao, tập thể dục mỗi ngày.","Có một âm thanh lách cách kỳ lạ phát ra từ bên trong tủ đựng đồ.","Khách sạn từ chối tiết lộ bất kỳ chi tiết nào về các vị khách của họ."]'::jsonb, 3, 'The hotel would not disclose any details about its guests. → Khách sạn từ chối tiết lộ bất kỳ chi tiết nào về các vị khách của họ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_13_2', 'en-c1-13', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_2_1', 'ten_c1_13_2', 'mount', 'As pressure mounts to reduce emissions, governments must expand renewable energy production and improve energy efficiency.', 'As pressure mounts to reduce emissions, governments must expand renewable energy production and improve energy efficiency.', '/maʊnt/', 'Khi áp lực giảm phát thải ngày càng gia tăng, các chính phủ phải mở rộng sản xuất năng lượng tái tạo và nâng cao hiệu quả sử dụng năng lượng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_2_2', 'ten_c1_13_2', 'queer', 'Museums increasingly include queer perspectives to reflect a broader range of experiences in their exhibitions.', 'Museums increasingly include queer perspectives to reflect a broader range of experiences in their exhibitions.', '/kwɪr/', 'Các bảo tàng ngày càng đưa vào các góc nhìn của cộng đồng queer nhằm phản ánh đa dạng trải nghiệm hơn trong các triển lãm của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_2_3', 'ten_c1_13_2', 'disclose', 'Companies should disclose how they collect personal data so that consumers can make informed decisions.', 'Companies should disclose how they collect personal data so that consumers can make informed decisions.', '/dɪsˈkloʊz/', 'Các doanh nghiệp nên công khai cách họ thu thập dữ liệu cá nhân để người tiêu dùng có thể đưa ra quyết định sáng suốt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_2_4', 'ten_c1_13_2', 'discord', 'Unequal access to resources can fuel social discord, particularly when communities feel excluded from political decisions.', 'Unequal access to resources can fuel social discord, particularly when communities feel excluded from political decisions.', '/ˈdɪskɔːrd/', 'Sự tiếp cận tài nguyên không công bằng có thể châm ngòi cho những bất ổn xã hội, đặc biệt khi các cộng đồng cảm thấy mình bị gạt ra ngoài lề các quyết định chính trị.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_2_5', 'ten_c1_13_2', 'inclusive', 'Schools should create inclusive learning environments where students with different needs can participate fully in classroom activities.', 'Schools should create inclusive learning environments where students with different needs can participate fully in classroom activities.', '/ɪnˈkluːsɪv/', 'Các trường học nên tạo ra môi trường học tập hòa nhập, nơi học sinh có nhu cầu khác nhau có thể tham gia đầy đủ vào các hoạt động trên lớp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_13_2_6', 'ten_c1_13_2', 'tactful', 'Managers who provide tactful feedback can address performance problems while maintaining employees'' confidence and motivation.', 'Managers who provide tactful feedback can address performance problems while maintaining employees'' confidence and motivation.', '/ˈtæktfəl/', 'Các nhà quản lý đưa ra phản hồi một cách khéo léo có thể giải quyết các vấn đề hiệu suất công việc mà vẫn duy trì được sự tự tin và động lực của nhân viên.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_13_2_1', 'en-c1-13', 'ten_c1_13_2', 'listening', 'listening', 'As pressure mounts to reduce emissions, governments must expand renewable energy production and improve energy efficiency.', NULL, 'Trong câu vừa nghe, từ “mount” mang nghĩa nào sau đây?', '["tăng dần; dâng lên; leo lên","tối ưu; tốt nhất; thuận lợi nhất","sự phản bội; sự phụ bạc","khinh miệt; coi thường"]'::jsonb, 0, '“mount” (/maʊnt/): tăng dần; dâng lên; leo lên. Câu đầy đủ: As pressure mounts to reduce emissions, governments must expand renewable energy production and improve energy efficiency.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_13_2_2', 'en-c1-13', 'ten_c1_13_2', 'listening', 'listening', 'Museums increasingly include queer perspectives to reflect a broader range of experiences in their exhibitions.', NULL, 'Trong câu vừa nghe, từ “queer” mang nghĩa nào sau đây?', '["dựa dẫm; phụ thuộc; nhờ vào","gặt hái kết quả; nhận thành quả từ những hành động trước đó","lạ lùng; kỳ quái","yếu ớt; ốm yếu; mệt mỏi"]'::jsonb, 2, '“queer” (/kwɪr/): lạ lùng; kỳ quái. Câu đầy đủ: Museums increasingly include queer perspectives to reflect a broader range of experiences in their exhibitions.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
