INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_1', 'en-c1-13', NULL, 'comprehensive_test', 'listening', 'mount', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mang tính biểu tượng; có tính đại diện cao","tăng dần; dâng lên; leo lên","sự bôi trơn; chất bôi trơn","bằng kim loại; chứa kim loại"]'::jsonb, 1, 'mount (/maʊnt/) → tăng dần; dâng lên; leo lên; lắp đặt; gắn chặt lên bề mặt; tổ chức; phát động; tiến hành', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_2', 'en-c1-13', NULL, 'comprehensive_test', 'listening', 'There was a queer rattling sound inside the cupboard.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bán bánh mì tự làm là một hoạt động kinh doanh hợp pháp ở đây.","Những lời nhận xét cay nghiệt của anh ấy đã vấp phải sự lên án từ tất cả mọi người trong bữa tối.","Có một âm thanh lách cách kỳ lạ phát ra từ bên trong tủ đựng đồ.","Câu trả lời khéo léo của cô ấy đã giúp tất cả mọi người tránh được một cuộc tranh cãi khó xử."]'::jsonb, 2, 'There was a queer rattling sound inside the cupboard. → Có một âm thanh lách cách kỳ lạ phát ra từ bên trong tủ đựng đồ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_3', 'en-c1-13', NULL, 'comprehensive_test', 'listening', 'disclose', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đa năng; linh hoạt, nhiều công dụng","học bổng nghiên cứu; quỹ hỗ trợ nghiên cứu; chức vụ nghiên cứu sinh","đi qua; vượt qua","tiết lộ; vạch trần; công khai"]'::jsonb, 3, 'disclose (/dɪsˈkloʊz/) → tiết lộ; vạch trần; công khai', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_4', 'en-c1-13', NULL, 'comprehensive_test', 'listening', 'Arguments about chores caused discord among the flatmates.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những lời nhận xét cay nghiệt của anh ấy đã vấp phải sự lên án từ tất cả mọi người trong bữa tối.","Cô tôi nói đùa rằng các lớp học nhảy sẽ giúp tôi trở nên có giáo dưỡng hơn.","Người nhận mỉm cười khi mở món quà bất ngờ.","Những cuộc cãi vã về việc nhà đã gây ra sự bất hòa giữa các bạn cùng phòng."]'::jsonb, 3, 'Arguments about chores caused discord among the flatmates. → Những cuộc cãi vã về việc nhà đã gây ra sự bất hòa giữa các bạn cùng phòng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_5', 'en-c1-13', NULL, 'comprehensive_test', 'listening', 'inclusive', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nén lại; ép chặt","sự trung thành; lòng trung thực","bao dung; mang tính hòa nhập","kiên cường; có khả năng phục hồi nhanh"]'::jsonb, 2, 'inclusive (/ɪnˈkluːsɪv/) → bao dung; mang tính hòa nhập; bao gồm toàn bộ chi phí; bao gồm cả điểm đầu và điểm cuối', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_6', 'en-c1-13', NULL, 'comprehensive_test', 'listening', 'Her tactful reply saved everyone from an awkward argument.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu trả lời khéo léo của cô ấy đã giúp tất cả mọi người tránh được một cuộc tranh cãi khó xử.","Chị tôi đã làm đại diện cho tôi tại cuộc họp.","Huấn luyện viên đã đưa ra tối hậu thư cho chúng tôi: tham gia tập luyện hoặc rời đi.","Cô ấy nhẹ nhàng giữ con chó lại để nó không đuổi theo con sóc."]'::jsonb, 0, 'Her tactful reply saved everyone from an awkward argument. → Câu trả lời khéo léo của cô ấy đã giúp tất cả mọi người tránh được một cuộc tranh cãi khó xử.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_7', 'en-c1-13', NULL, 'comprehensive_test', 'listening', 'refuge', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự ẩn náu; sự bảo vệ (khỏi nguy hiểm, rắc rối, thời tiết xấu)","lỏng lẻo; thiếu nghiêm ngặt","thuộc khẩu ngữ; dùng trong văn nói hàng ngày; không trang trọng","kêu chít chít; thét lên; phát ra tiếng rít"]'::jsonb, 0, 'refuge (/ˈrefjuːdʒ/) → sự ẩn náu; sự bảo vệ (khỏi nguy hiểm, rắc rối, thời tiết xấu); nơi trú ẩn; chốn dung thân', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_8', 'en-c1-13', NULL, 'comprehensive_test', 'listening', 'These resilient plants recovered quickly after the summer drought.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông bà cô ấy đã kể những câu chuyện về cuộc sống dưới ách áp bức.","Chị tôi đã làm đại diện cho tôi tại cuộc họp.","Những loài thực vật kiên cường này đã hồi phục nhanh chóng sau đợt hạn hán mùa hè.","Gợi ý thấu đáo của bạn rất đáng để cân nhắc nghiêm túc."]'::jsonb, 2, 'These resilient plants recovered quickly after the summer drought. → Những loài thực vật kiên cường này đã hồi phục nhanh chóng sau đợt hạn hán mùa hè.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_9', 'en-c1-13', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “welcoming people of different backgrounds and abilities”?', '["mingle","ensue","inclusive","restrain"]'::jsonb, 2, 'inclusive (/ɪnˈkluːsɪv/) → bao dung; mang tính hòa nhập', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_10', 'en-c1-13', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Careful not to upset or offend people.”?', '["refuge","discord","tactful","oppression"]'::jsonb, 2, 'tactful (/ˈtæktfəl/) → khéo léo; tế nhị; lịch sự', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_11', 'en-c1-13', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “protection from danger, trouble, or bad weather”?', '["fanatic","defiant","condemnation","refuge"]'::jsonb, 3, 'refuge (/ˈrefjuːdʒ/) → sự ẩn náu; sự bảo vệ (khỏi nguy hiểm, rắc rối, thời tiết xấu)', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_12', 'en-c1-13', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Able to recover quickly after difficulties or damage”?', '["resilient","disclose","worthy","condemnation"]'::jsonb, 0, 'resilient (/rɪˈzɪliənt/) → kiên cường; có khả năng phục hồi nhanh', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_13', 'en-c1-13', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To use something incorrectly or for a harmful purpose.”?', '["refuge","misuse","oppression","mount"]'::jsonb, 1, 'misuse (/ˌmɪsˈjuːz/) → dùng sai; lạm dụng', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
