INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_18', 'en-c1-13', NULL, 'comprehensive_test', 'reading', NULL, 'As pressure mounts to reduce emissions, governments must expand renewable energy production and improve energy efficiency.', 'Dựa vào câu trên, từ “mount” có nghĩa phù hợp nhất là gì?', '["nghiêm khắc; khắt khe; cứng rắn","bất lợi; gây khó khăn","bản song ca; khúc hát/khúc nhạc đôi cho hai người biểu diễn","tăng dần; dâng lên; leo lên"]'::jsonb, 3, 'mount: tăng dần; dâng lên; leo lên; lắp đặt; gắn chặt lên bề mặt; tổ chức; phát động; tiến hành. Dịch cả câu: Khi áp lực giảm phát thải ngày càng gia tăng, các chính phủ phải mở rộng sản xuất năng lượng tái tạo và nâng cao hiệu quả sử dụng năng lượng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_19', 'en-c1-13', NULL, 'comprehensive_test', 'reading', NULL, 'Museums increasingly include queer perspectives to reflect a broader range of experiences in their exhibitions.', 'Dựa vào câu trên, từ “queer” có nghĩa phù hợp nhất là gì?', '["thuộc về thần thoại","thuộc về thần thánh; thiêng liêng","khuôn mẫu; định kiến","lạ lùng; kỳ quái"]'::jsonb, 3, 'queer: lạ lùng; kỳ quái; thuộc cộng đồng người đồng tính, song tính, chuyển giới và đa dạng tính dục (khác với dị tính). Dịch cả câu: Các bảo tàng ngày càng đưa vào các góc nhìn của cộng đồng queer nhằm phản ánh đa dạng trải nghiệm hơn trong các triển lãm của họ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_20', 'en-c1-13', NULL, 'comprehensive_test', 'reading', NULL, 'Companies should disclose how they collect personal data so that consumers can make informed decisions.', 'Dựa vào câu trên, từ “disclose” có nghĩa phù hợp nhất là gì?', '["tiết lộ; vạch trần; công khai","sự đổi hướng đường đi hoặc sự thay đổi mục đích sử dụng của cái gì đó","cô độc; đơn độc; thích sống một mình","thí sinh; người tham gia cuộc thi"]'::jsonb, 0, 'disclose: tiết lộ; vạch trần; công khai. Dịch cả câu: Các doanh nghiệp nên công khai cách họ thu thập dữ liệu cá nhân để người tiêu dùng có thể đưa ra quyết định sáng suốt.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_21', 'en-c1-13', NULL, 'comprehensive_test', 'reading', NULL, 'Unequal access to resources can fuel social discord, particularly when communities feel excluded from political decisions.', 'Dựa vào câu trên, từ “discord” có nghĩa phù hợp nhất là gì?', '["cằn cỗi; không màu mỡ","có tính gắn kết chặt chẽ, đoàn kết","sự bất hòa; sự chia rẽ; mối bất đồng","đối thủ, kẻ địch"]'::jsonb, 2, 'discord: sự bất hòa; sự chia rẽ; mối bất đồng; âm thanh không hòa hợp; tiếng chói tai. Dịch cả câu: Sự tiếp cận tài nguyên không công bằng có thể châm ngòi cho những bất ổn xã hội, đặc biệt khi các cộng đồng cảm thấy mình bị gạt ra ngoài lề các quyết định chính trị.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_22', 'en-c1-13', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có tính thách thức; công khai chống đối; không tuân lệnh”', '["refrain","dwarf","defiant","occupant"]'::jsonb, 2, 'có tính thách thức; công khai chống đối; không tuân lệnh → defiant (/dɪˈfaɪ.ənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_23', 'en-c1-13', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự lên án; sự chỉ trích mạnh mẽ”', '["inclusive","condemnation","flare","dwarf"]'::jsonb, 1, 'sự lên án; sự chỉ trích mạnh mẽ → condemnation (/ˌkɑːndemˈneɪʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_13_24', 'en-c1-13', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “xảy ra sau đó; tiếp theo”', '["refinement","nitrate","ensue","hereby"]'::jsonb, 2, 'xảy ra sau đó; tiếp theo → ensue (/ɪnˈsuː/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-14', 'en', 'Bài 14: Xã hội & Cộng đồng (9) - CEFR C1', 'CEFR C1', 'C1 · Xã hội', '27 từ vựng Tiếng Anh CEFR C1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5014, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ruthless', 'en-c1-14', 'ruthless', '/ˈruːθləs/', 'C1', 'nhẫn tâm; tàn nhẫn; quyết liệt (bất chấp gây tổn thương cho người khác)', 'adj.', 'ruthlessly (adv.), ruthlessness (n.)', 'Đồng nghĩa: merciless, pitiless, relentless · Trái nghĩa: compassionate, merciful', 'Mang ý nghĩa mạnh hơn strict, nhấn mạnh việc đạt được mục đích mà không màng tới cảm xúc hay lợi ích của người khác.', 'The ruthless landlord evicted the family without any warning.', NULL, 'Gã chủ nhà tàn nhẫn đã đuổi cả gia đình đi mà không có bất kỳ lời cảnh báo nào.', '{"wordId":"ruthless","ukIpa":"/ˈruːθləs/","usIpa":"/ˈruːθləs/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Determined to succeed without caring about harm caused to others.","vi":"nhẫn tâm; tàn nhẫn; quyết liệt (bất chấp gây tổn thương cho người khác)"}],"examples":[{"en":"The ruthless landlord evicted the family without any warning.","vi":"Gã chủ nhà tàn nhẫn đã đuổi cả gia đình đi mà không có bất kỳ lời cảnh báo nào.","audioKind":"ex"},{"en":"Ruthless competition may encourage companies to cut labour costs at the expense of employee welfare.","vi":"Cạnh tranh khốc liệt có thể thúc đẩy các doanh nghiệp cắt giảm chi phí nhân công bằng cách đánh đổi phúc lợi của nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"ruthless competition","vi":"cạnh tranh khốc liệt"},{"en":"ruthless ambition","vi":"dã tâm bất chấp thủ đoạn"},{"en":"a ruthless leader","vi":"lãnh đạo nhẫn tâm"}],"wordFamily":["ruthlessly (adv.)","ruthlessness (n.)"],"synonyms":["merciless","pitiless","relentless"],"antonyms":["compassionate","merciful"],"tipVi":"Mang ý nghĩa mạnh hơn strict, nhấn mạnh việc đạt được mục đích mà không màng tới cảm xúc hay lợi ích của người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arbitrary', 'en-c1-14', 'arbitrary', '/ˈɑːrbɪtreri/', 'C1', 'tùy tiện; ngẫu nhiên (không dựa trên lý do hay cơ sở rõ ràng); chuyên quyền; độc đoán; độc đoán độc đoán (dựa trên ý chí cá nhân thay vì quy tắc công bằng)', 'adj.', 'arbitrarily (adv.), arbitrariness (n.)', 'Đồng nghĩa: random, capricious · Trái nghĩa: reasoned', 'Điểm cốt lõi là thiếu căn cứ hợp lý, không chỉ đơn thuần là có thể tự do lựa chọn.', 'Her choice felt arbitrary: she picked without even looking.', NULL, 'Lựa chọn của cô ấy có vẻ tùy tiện: cô ấy chọn mà chẳng thèm nhìn lấy một cái.', '{"wordId":"arbitrary","ukIpa":"/ˈɑːbɪtrəri/","usIpa":"/ˈɑːrbɪtreri/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"based on chance or personal choice rather than clear reasons","vi":"tùy tiện; ngẫu nhiên (không dựa trên lý do hay cơ sở rõ ràng)"},{"pos":"adj.","en":"using power according to personal wishes rather than fair rules","vi":"chuyên quyền; độc đoán; độc đoán độc đoán (dựa trên ý chí cá nhân thay vì quy tắc công bằng)"}],"examples":[{"en":"Her choice felt arbitrary: she picked without even looking.","vi":"Lựa chọn của cô ấy có vẻ tùy tiện: cô ấy chọn mà chẳng thèm nhìn lấy một cái.","audioKind":"ex"},{"en":"Arbitrary restrictions on university admissions can prevent capable students from accessing education and may reinforce existing social inequalities.","vi":"Những hạn chế mang tính cảm tính đối với việc tuyển sinh đại học có thể ngăn cản những học sinh có năng lực tiếp cận giáo dục và làm trầm trọng thêm sự bất công xã hội hiện hữu.","audioKind":"ex2"}],"collocations":[{"en":"an arbitrary decision","vi":"quyết định cảm tính"},{"en":"an arbitrary limit","vi":"hạn chế tùy tiện"},{"en":"arbitrary power","vi":"quyền lực chuyên quyền"}],"wordFamily":["arbitrarily (adv.)","arbitrariness (n.)"],"synonyms":["random","capricious"],"antonyms":["reasoned"],"tipVi":"Điểm cốt lõi là thiếu căn cứ hợp lý, không chỉ đơn thuần là có thể tự do lựa chọn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_savage', 'en-c1-14', 'savage', '/ˈsævɪdʒ/', 'C1', 'hung dữ; tàn bạo; dữ dội; khốc liệt; cay nghiệt; tấn công tàn bạo; chỉ trích gay gắt', 'adj.', 'savagely (adv.), savagery (n.)', 'Đồng nghĩa: fierce, brutal · Trái nghĩa: gentle', 'Tránh dùng từ này làm danh từ để gọi các dân tộc/cộng đồng vì nó mang sắc thái miệt thị và xúc phạm.', 'The documentary showed a savage fight between two wolves.', NULL, 'Bộ phim tài liệu ghi lại cảnh chiến đấu dữ dội giữa hai con sói.', '{"wordId":"savage","ukIpa":"/ˈsævɪdʒ/","usIpa":"/ˈsævɪdʒ/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Extremely violent, fierce, or cruel.","vi":"hung dữ; tàn bạo; dữ dội"},{"pos":"adj.","en":"Extremely harsh or severe.","vi":"khốc liệt; dữ dội; cay nghiệt"},{"pos":"v.","en":"To attack violently or criticize someone very harshly.","vi":"tấn công tàn bạo; chỉ trích gay gắt"}],"examples":[{"en":"The documentary showed a savage fight between two wolves.","vi":"Bộ phim tài liệu ghi lại cảnh chiến đấu dữ dội giữa hai con sói.","audioKind":"ex"},{"en":"The proposed reduction in education funding attracted savage criticism from teachers and parents across the country.","vi":"Đề xuất cắt giảm ngân sách giáo dục đã vấp phải sự chỉ trích gay gắt từ giáo viên và phụ huynh trên cả nước.","audioKind":"ex2"}],"collocations":[{"en":"savage attack","vi":"cuộc tấn công tàn bạo"},{"en":"savage criticism","vi":"lời chỉ trích cay nghiệt"},{"en":"savage cuts","vi":"các biện pháp cắt giảm khốc liệt"}],"wordFamily":["savagely (adv.)","savagery (n.)"],"synonyms":["fierce","brutal"],"antonyms":["gentle"],"tipVi":"Tránh dùng từ này làm danh từ để gọi các dân tộc/cộng đồng vì nó mang sắc thái miệt thị và xúc phạm.","noteVi":"Sử dụng làm danh từ để chỉ con người, đặc biệt là các nhóm dân tộc, mang sắc thái xúc phạm.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maturity', 'en-c1-14', 'maturity', '/məˈtʃʊrəti/', 'C1', 'sự chín chắn; tính điềm tĩnh; sự trưởng thành; quá trình phát triển hoàn thiện; thời hạn đáo hạn', 'n.', 'mature (adj.), mature (v.), immature (adj.), immaturity (n.)', 'Trái nghĩa: immaturity', 'Thường là danh từ không đếm được; trong ngữ cảnh tài chính, at maturity có nghĩa là vào thời điểm đáo hạn.', 'Lena showed maturity by calmly admitting her mistake.', NULL, 'Lena thể hiện sự chín chắn bằng cách bình tĩnh thừa nhận lỗi lầm của mình.', '{"wordId":"maturity","ukIpa":"/məˈtʃʊərəti/","usIpa":"/məˈtʃʊrəti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The ability to behave responsibly and make sensible judgments.","vi":"sự chín chắn; tính điềm tĩnh"},{"pos":"n.","en":"The state of being fully grown or developed.","vi":"sự trưởng thành; quá trình phát triển hoàn thiện"},{"pos":"n.","en":"The time when an investment or debt becomes repayable.","vi":"thời hạn đáo hạn"}],"examples":[{"en":"Lena showed maturity by calmly admitting her mistake.","vi":"Lena thể hiện sự chín chắn bằng cách bình tĩnh thừa nhận lỗi lầm của mình.","audioKind":"ex"},{"en":"Schools can foster emotional maturity by encouraging students to resolve disagreements respectfully and consider different perspectives.","vi":"Các trường học có thể thúc đẩy sự trưởng thành về mặt cảm xúc bằng cách khuyến khích học sinh giải quyết bất đồng một cách tôn trọng và cân nhắc các góc nhìn khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"emotional maturity","vi":"sự trưởng thành về mặt cảm xúc"},{"en":"reach maturity","vi":"đạt đến độ trưởng thành"},{"en":"a maturity date","vi":"ngày đáo hạn"},{"en":"show maturity","vi":"thể hiện sự chín chắn"}],"wordFamily":["mature (adj.)","mature (v.)","immature (adj.)","immaturity (n.)"],"synonyms":[],"antonyms":["immaturity"],"tipVi":"Thường là danh từ không đếm được; trong ngữ cảnh tài chính, at maturity có nghĩa là vào thời điểm đáo hạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entity', 'en-c1-14', 'entity', '/ˈentəti/', 'C1', 'thực thể độc lập; tổ chức riêng biệt', 'n.', NULL, NULL, 'Nhấn mạnh vào một đơn vị tồn tại độc lập, thường được sử dụng trong các ngữ cảnh tổ chức, pháp lý hoặc thương mại.', 'Our small bakery now operates as a separate entity.', NULL, 'Tiệm bánh nhỏ của chúng tôi giờ đây hoạt động như một thực thể riêng biệt.', '{"wordId":"entity","ukIpa":"/ˈentəti/","usIpa":"/ˈentəti/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"something that exists independently, especially an organization","vi":"thực thể độc lập; tổ chức riêng biệt"}],"examples":[{"en":"Our small bakery now operates as a separate entity.","vi":"Tiệm bánh nhỏ của chúng tôi giờ đây hoạt động như một thực thể riêng biệt.","audioKind":"ex"},{"en":"Each university should remain an independent entity while cooperating with other institutions on important research projects.","vi":"Mỗi trường đại học nên duy trì là một thực thể độc lập trong khi vẫn hợp tác với các cơ quan khác trong các dự án nghiên cứu quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"a separate entity","vi":"một thực thể độc lập"},{"en":"a legal entity","vi":"một pháp nhân"},{"en":"a commercial entity","vi":"một thực thể thương mại"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh vào một đơn vị tồn tại độc lập, thường được sử dụng trong các ngữ cảnh tổ chức, pháp lý hoặc thương mại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_irrespective', 'en-c1-14', 'irrespective', '/ˌɪrɪˈspektɪv/', 'C1', 'bất kể; không kể; không màng đến', 'adv.', NULL, 'Đồng nghĩa: regardless', 'Thường đi kèm với giới từ of (irrespective of + danh từ) với nghĩa là "bất kể".', 'Everyone can join the walk, irrespective of their age.', NULL, 'Ai cũng có thể tham gia chuyến đi bộ này, bất kể độ tuổi của họ.', '{"wordId":"irrespective","ukIpa":"/ˌɪrɪˈspektɪv/","usIpa":"/ˌɪrɪˈspektɪv/","cefr":"C1","topic":"society","senses":[{"pos":"adv.","en":"Without considering or being affected by something, used with of.","vi":"bất kể; không kể; không màng đến"}],"examples":[{"en":"Everyone can join the walk, irrespective of their age.","vi":"Ai cũng có thể tham gia chuyến đi bộ này, bất kể độ tuổi của họ.","audioKind":"ex"},{"en":"Quality education should be available to all children, irrespective of their family income or social background.","vi":"Mọi trẻ em đều cần được tiếp cận nền giáo dục chất lượng cao, bất kể thu nhập gia đình hay hoàn cảnh xã hội ra sao.","audioKind":"ex2"}],"collocations":[{"en":"irrespective of age","vi":"bất kể tuổi tác"},{"en":"irrespective of income","vi":"bất kể thu nhập"},{"en":"irrespective of the outcome","vi":"bất kể kết quả ra sao"}],"wordFamily":[],"synonyms":["regardless"],"antonyms":[],"tipVi":"Thường đi kèm với giới từ of (irrespective of + danh từ) với nghĩa là \"bất kể\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reliant', 'en-c1-14', 'reliant', '/rɪˈlaɪənt/', 'C1', 'dựa dẫm; phụ thuộc; nhờ vào', 'adj.', 'rely (v.), reliance (n.), self-reliant (adj.)', 'Đồng nghĩa: dependent · Trái nghĩa: independent, self-reliant', 'Cấu trúc cố định reliant on; từ trái nghĩa ''tự lực'' là self-reliant.', 'Without a car, we are reliant on local buses.', NULL, 'Không có ô tô, chúng tôi hoàn toàn phụ thuộc vào xe buýt địa phương.', '{"wordId":"reliant","ukIpa":"/rɪˈlaɪənt/","usIpa":"/rɪˈlaɪənt/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"needing someone or something for support or success","vi":"dựa dẫm; phụ thuộc; nhờ vào"}],"examples":[{"en":"Without a car, we are reliant on local buses.","vi":"Không có ô tô, chúng tôi hoàn toàn phụ thuộc vào xe buýt địa phương.","audioKind":"ex"},{"en":"Countries heavily reliant on imported fuel are particularly vulnerable to sudden changes in global energy prices.","vi":"Các quốc gia phụ thuộc nhiều vào nhiên liệu nhập khẩu đặc biệt dễ bị tổn thương trước những biến động đột ngột của giá năng lượng toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"reliant on","vi":"phụ thuộc vào"},{"en":"heavily reliant on","vi":"phụ thuộc nặng nề vào"},{"en":"increasingly reliant on","vi":"ngày càng phụ thuộc vào"}],"wordFamily":["rely (v.)","reliance (n.)","self-reliant (adj.)"],"synonyms":["dependent"],"antonyms":["independent","self-reliant"],"tipVi":"Cấu trúc cố định reliant on; từ trái nghĩa ''tự lực'' là self-reliant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disregard', 'en-c1-14', 'disregard', '/ˌdɪsrɪˈɡɑːrd/', 'C1', 'phớt lờ; coi nhẹ; không màng tới; sự phớt lờ; sự thờ ơ; thái độ coi thường', 'v.', NULL, 'Đồng nghĩa: ignore, neglect · Trái nghĩa: heed', 'Động từ đi trực tiếp với tân ngữ; danh từ thường đi với giới từ disregard for.', 'Please disregard my earlier message; the picnic is still happening.', NULL, 'Hãy bỏ qua tin nhắn trước của tôi; buổi dã ngoại vẫn diễn ra như kế hoạch.', '{"wordId":"disregard","ukIpa":"/ˌdɪsrɪˈɡɑːd/","usIpa":"/ˌdɪsrɪˈɡɑːrd/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To ignore something or treat it as unimportant.","vi":"phớt lờ; coi nhẹ; không màng tới"},{"pos":"n.","en":"A lack of attention or respect for something.","vi":"sự phớt lờ; sự thờ ơ; thái độ coi thường"}],"examples":[{"en":"Please disregard my earlier message; the picnic is still happening.","vi":"Hãy bỏ qua tin nhắn trước của tôi; buổi dã ngoại vẫn diễn ra như kế hoạch.","audioKind":"ex"},{"en":"Companies that disregard environmental regulations may reduce short-term costs but create lasting damage to local ecosystems.","vi":"Các công ty phớt lờ các quy định môi trường có thể giảm chi phí ngắn hạn nhưng lại gây ra tổn hại lâu dài cho hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"disregard advice","vi":"bỏ qua lời khuyên"},{"en":"disregard the rules","vi":"phớt lờ quy tắc"},{"en":"complete disregard for","vi":"sự thờ ơ hoàn toàn đối với"},{"en":"disregard for safety","vi":"sự coi thường an toàn"}],"wordFamily":[],"synonyms":["ignore","neglect"],"antonyms":["heed"],"tipVi":"Động từ đi trực tiếp với tân ngữ; danh từ thường đi với giới từ disregard for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spouse', 'en-c1-14', 'spouse', '/spaʊs/', 'C1', 'vợ hoặc chồng; phối ngẫu', 'n.', 'spousal (adj.)', NULL, 'Từ trang trọng, chỉ chồng hoặc vợ, không phân biệt giới tính.', 'Each employee can bring their spouse to dinner.', NULL, 'Mỗi nhân viên có thể đưa vợ hoặc chồng của mình tham gia bữa tối.', '{"wordId":"spouse","ukIpa":"/spaʊs/","usIpa":"/spaʊs/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"The person someone is married to.","vi":"vợ hoặc chồng; phối ngẫu"}],"examples":[{"en":"Each employee can bring their spouse to dinner.","vi":"Mỗi nhân viên có thể đưa vợ hoặc chồng của mình tham gia bữa tối.","audioKind":"ex"},{"en":"Flexible working arrangements can help employees share childcare responsibilities more equally with their spouses.","vi":"Các thỏa thuận làm việc linh hoạt có thể giúp nhân viên chia sẻ trách nhiệm chăm sóc con cái với vợ/chồng một cách công bằng hơn.","audioKind":"ex2"}],"collocations":[{"en":"surviving spouse","vi":"vợ/chồng còn sống"},{"en":"accompanying spouse","vi":"vợ/chồng đi cùng"},{"en":"spouse''s income","vi":"thu nhập của vợ/chồng"}],"wordFamily":["spousal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ trang trọng, chỉ chồng hoặc vợ, không phân biệt giới tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rampant', 'en-c1-14', 'rampant', '/ˈræmpənt/', 'C1', 'lan tràn; hoành hành; không kiểm soát được (thường mang nghĩa tiêu cực); mọc lan nhanh; mọc um tùm', 'adj.', 'rampantly (adv.)', 'Đồng nghĩa: uncontrolled, unchecked · Trái nghĩa: controlled', 'Thường dùng để mô tả tệ nạn tham nhũng, dịch bệnh lan rộng; cụm ''run rampant'' có nghĩa là hoành hành, tung hoành.', 'Rampant weeds have taken over our vegetable patch.', NULL, 'Cỏ dại mọc um tùm đã chiếm hết khu vườn trồng rau của chúng tôi.', '{"wordId":"rampant","ukIpa":"/ˈræmpənt/","usIpa":"/ˈræmpənt/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Spreading widely and uncontrollably, especially when harmful.","vi":"lan tràn; hoành hành; không kiểm soát được (thường mang nghĩa tiêu cực)"},{"pos":"adj.","en":"Growing quickly and spreading without control.","vi":"mọc lan nhanh; mọc um tùm"}],"examples":[{"en":"Rampant weeds have taken over our vegetable patch.","vi":"Cỏ dại mọc um tùm đã chiếm hết khu vườn trồng rau của chúng tôi.","audioKind":"ex"},{"en":"Where oversight is weak, rampant corruption can undermine public trust and divert resources away from essential services.","vi":"Ở những nơi công tác giám sát lỏng lẻo, tình trạng tham nhũng lan tràn có thể xói mòn lòng tin của công chúng và làm chệch hướng nguồn lực khỏi các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"rampant corruption","vi":"tham nhũng hoành hành"},{"en":"run rampant","vi":"lan tràn không kiểm soát"},{"en":"rampant inflation","vi":"lạm phát phi mã"},{"en":"rampant growth","vi":"sự phát triển lan tràn"}],"wordFamily":["rampantly (adv.)"],"synonyms":["uncontrolled","unchecked"],"antonyms":["controlled"],"tipVi":"Thường dùng để mô tả tệ nạn tham nhũng, dịch bệnh lan rộng; cụm ''run rampant'' có nghĩa là hoành hành, tung hoành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_turbulent', 'en-c1-14', 'turbulent', '/ˈtɝːbjələnt/', 'C1', 'đầy biến động; hỗn loạn; dữ dội; cuồn cuộn', 'adj.', 'turbulence (n.)', 'Đồng nghĩa: unstable, unsettled · Trái nghĩa: calm, stable', 'Dùng để miêu tả cả tình hình xã hội biến động lẫn dòng nước hoặc luồng khí chuyển động hỗn loạn.', 'After a turbulent week, our family needed a quiet evening.', NULL, 'Sau một tuần đầy biến động, gia đình chúng tôi cần một buổi tối yên tĩnh.', '{"wordId":"turbulent","ukIpa":"/ˈtɜːbjələnt/","usIpa":"/ˈtɝːbjələnt/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Full of conflict, uncertainty, or sudden disruptive changes.","vi":"đầy biến động; hỗn loạn"},{"pos":"adj.","en":"Moving violently and irregularly, especially air or water.","vi":"dữ dội; cuồn cuộn"}],"examples":[{"en":"After a turbulent week, our family needed a quiet evening.","vi":"Sau một tuần đầy biến động, gia đình chúng tôi cần một buổi tối yên tĩnh.","audioKind":"ex"},{"en":"During turbulent economic periods, governments may increase public spending to protect jobs and support vulnerable households.","vi":"Trong những giai đoạn kinh tế biến động, chính phủ có thể tăng chi tiêu công để bảo vệ việc làm và hỗ trợ các hộ gia đình dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"turbulent times","vi":"thời kỳ biến động"},{"en":"turbulent waters","vi":"dòng nước xiết"},{"en":"turbulent airflow","vi":"luồng không khí nhiễu động"}],"wordFamily":["turbulence (n.)"],"synonyms":["unstable","unsettled"],"antonyms":["calm","stable"],"tipVi":"Dùng để miêu tả cả tình hình xã hội biến động lẫn dòng nước hoặc luồng khí chuyển động hỗn loạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maniac', 'en-c1-14', 'maniac', '/ˈmeɪniæk/', 'C1', 'kẻ cư xử điên rồ; kẻ hành động liều lĩnh; tên cuồng...; người cực kỳ cuồng nhiệt (với hoạt động nào đó)', 'n.', 'mania (n.), manic (adj.), maniacal (adj.)', NULL, 'Thuộc văn phong không trang trọng, có thể gây xúc phạm; không dùng làm từ chẩn đoán y khoa về tâm thần.', 'That driver is a maniac, speeding around every corner.', NULL, 'Tài xế đó chạy xe như điên, phóng bạt mạng qua mọi khúc cua.', '{"wordId":"maniac","ukIpa":"/ˈmeɪniæk/","usIpa":"/ˈmeɪniæk/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"someone behaving in an extremely wild or reckless way","vi":"kẻ cư xử điên rồ; kẻ hành động liều lĩnh"},{"pos":"n.","en":"someone extremely enthusiastic about a particular activity","vi":"tên cuồng...; người cực kỳ cuồng nhiệt (với hoạt động nào đó)"}],"examples":[{"en":"That driver is a maniac, speeding around every corner.","vi":"Tài xế đó chạy xe như điên, phóng bạt mạng qua mọi khúc cua.","audioKind":"ex"},{"en":"Calling a reckless driver a maniac expresses anger but does little to explain the causes of dangerous driving.","vi":"Việc gọi một tài xế liều lĩnh là kẻ điên rồ thể hiện sự tức giận nhưng chẳng giải thích được nguyên nhân của hành vi lái xe nguy hiểm.","audioKind":"ex2"}],"collocations":[{"en":"drive like a maniac","vi":"lái xe như kẻ điên"},{"en":"a fitness maniac","vi":"một kẻ cuồng tập thể hình"}],"wordFamily":["mania (n.)","manic (adj.)","maniacal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thuộc văn phong không trang trọng, có thể gây xúc phạm; không dùng làm từ chẩn đoán y khoa về tâm thần.","noteVi":"Cách gọi không trang trọng, có thể mang hàm ý miệt thị; không thích hợp dùng cho người mắc bệnh tâm thần.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_empower', 'en-c1-14', 'empower', '/ɪmˈpaʊər/', 'C1', 'trao quyền tự chủ; làm cho có năng lực tự lập; ủy quyền; cho phép làm gì', 'v.', 'empowerment (n.), empowered (adj.), empowering (adj.)', 'Đồng nghĩa: enable, authorize · Trái nghĩa: disempower', 'Thường dùng cấu trúc empower sb to do sth, diễn tả ý nghĩa trao quyền hoặc tạo năng lực hành động.', 'Learning to cook empowered him to live independently.', NULL, 'Học nấu ăn giúp anh ấy có khả năng tự lập trong cuộc sống.', '{"wordId":"empower","ukIpa":"/ɪmˈpaʊə/","usIpa":"/ɪmˈpaʊər/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"Give someone confidence or control over their own life.","vi":"trao quyền tự chủ; làm cho có năng lực tự lập"},{"pos":"v.","en":"Give someone official authority to take particular action.","vi":"ủy quyền; cho phép làm gì"}],"examples":[{"en":"Learning to cook empowered him to live independently.","vi":"Học nấu ăn giúp anh ấy có khả năng tự lập trong cuộc sống.","audioKind":"ex"},{"en":"Access to reliable information can empower citizens to make informed decisions about their health.","vi":"Việc tiếp cận thông tin đáng tin cậy có thể trao quyền cho công dân đưa ra những quyết định sáng suốt về sức khỏe của chính họ.","audioKind":"ex2"}],"collocations":[{"en":"empower women","vi":"trao quyền cho phụ nữ"},{"en":"empower communities","vi":"tăng cường năng lực tự chủ cho cộng đồng"},{"en":"empower someone to act","vi":"ủy quyền cho ai đó hành động"}],"wordFamily":["empowerment (n.)","empowered (adj.)","empowering (adj.)"],"synonyms":["enable","authorize"],"antonyms":["disempower"],"tipVi":"Thường dùng cấu trúc empower sb to do sth, diễn tả ý nghĩa trao quyền hoặc tạo năng lực hành động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clamor', 'en-c1-14', 'clamor', '/ˈklæmər/', 'C1', 'tiếng la ó om sòm; tiếng ồn ào; đòi hỏi bức xúc của công chúng; la hét đòi hỏi; lớn tiếng yêu cầu', 'n.', NULL, 'Đồng nghĩa: outcry, din', 'Cách viết theo kiểu Mỹ; tiếng Anh-Anh viết là clamour. Đòi hỏi cái gì dùng clamor for.', 'The children clamored for another story before bedtime.', NULL, 'Bọn trẻ nhao nhao đòi nghe thêm một câu chuyện nữa trước giờ đi ngủ.', '{"wordId":"clamor","ukIpa":"/ˈklæmə/","usIpa":"/ˈklæmər/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"Loud noise or strong public demands","vi":"tiếng la ó om sòm; tiếng ồn ào; đòi hỏi bức xúc của công chúng"},{"pos":"v.","en":"To demand something loudly or insistently","vi":"la hét đòi hỏi; lớn tiếng yêu cầu"}],"examples":[{"en":"The children clamored for another story before bedtime.","vi":"Bọn trẻ nhao nhao đòi nghe thêm một câu chuyện nữa trước giờ đi ngủ.","audioKind":"ex"},{"en":"Public clamor for cleaner air has encouraged local authorities to invest in more reliable public transport.","vi":"Tiếng kêu gọi tha thiết của công chúng đòi hỏi bầu không khí trong lành hơn đã khuyến khích chính quyền địa phương đầu tư vào hệ thống giao thông công cộng đáng tin cậy hơn.","audioKind":"ex2"}],"collocations":[{"en":"clamor for change","vi":"kêu gọi thay đổi quyết liệt"},{"en":"public clamor","vi":"tiếng lòng của công chúng"},{"en":"clamor to be heard","vi":"la ó đòi được lắng nghe"}],"wordFamily":[],"synonyms":["outcry","din"],"antonyms":[],"tipVi":"Cách viết theo kiểu Mỹ; tiếng Anh-Anh viết là clamour. Đòi hỏi cái gì dùng clamor for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amiable', 'en-c1-14', 'amiable', '/ˈeɪmiəbəl/', 'C1', 'thân thiện; hòa nhã; dễ gần', 'adj.', 'amiability (n.), amiably (adv.)', 'Đồng nghĩa: friendly, pleasant, good-natured · Trái nghĩa: unfriendly, hostile', 'amiable đa số dùng để mô tả người; amicable thường dùng để mô tả mối quan hệ hoặc thỏa thuận.', 'Our amiable neighbour always stops to chat by the gate.', NULL, 'Người hàng xóm thân thiện của chúng tôi luôn dừng lại trò chuyện bên cổng.', '{"wordId":"amiable","ukIpa":"/ˈeɪmiəbəl/","usIpa":"/ˈeɪmiəbəl/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Friendly, pleasant, and easy to get along with.","vi":"thân thiện; hòa nhã; dễ gần"}],"examples":[{"en":"Our amiable neighbour always stops to chat by the gate.","vi":"Người hàng xóm thân thiện của chúng tôi luôn dừng lại trò chuyện bên cổng.","audioKind":"ex"},{"en":"An amiable manner can help healthcare professionals build trust with patients from diverse cultural backgrounds.","vi":"Thái độ niềm nở có thể giúp nhân viên y tế xây dựng lòng tin với bệnh nhân đến từ các nền văn hóa đa dạng.","audioKind":"ex2"}],"collocations":[{"en":"amiable manner","vi":"thái độ niềm nở"},{"en":"amiable personality","vi":"tính cách hòa nhã"},{"en":"amiable smile","vi":"nụ cười thân thiện"}],"wordFamily":["amiability (n.)","amiably (adv.)"],"synonyms":["friendly","pleasant","good-natured"],"antonyms":["unfriendly","hostile"],"tipVi":"amiable đa số dùng để mô tả người; amicable thường dùng để mô tả mối quan hệ hoặc thỏa thuận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assurance', 'en-c1-14', 'assurance', '/əˈʃʊrəns/', 'C1', 'sự đảm bảo; lời cam đoan; sự tự tin; sự chắc chắn', 'n.', 'assure (v.), assured (adj.), reassurance (n.)', 'Đồng nghĩa: promise, confidence · Trái nghĩa: uncertainty', 'Khi chỉ lời hứa cụ thể thì là danh từ đếm được; khi chỉ sự tự tin thì thường là không đếm được.', 'She gave me her assurance that dinner was ready.', NULL, 'Cô ấy đã cam đoan với tôi rằng bữa tối đã được chuẩn bị xong.', '{"wordId":"assurance","ukIpa":"/əˈʃʊərəns/","usIpa":"/əˈʃʊrəns/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A promise intended to remove doubt or worry.","vi":"sự đảm bảo; lời cam đoan"},{"pos":"n.","en":"Confidence in your abilities or in what you believe.","vi":"sự tự tin; sự chắc chắn"}],"examples":[{"en":"She gave me her assurance that dinner was ready.","vi":"Cô ấy đã cam đoan với tôi rằng bữa tối đã được chuẩn bị xong.","audioKind":"ex"},{"en":"Residents sought an assurance from the council that the new development would not reduce access to public parks.","vi":"Cư dân đã yêu cầu hội đồng địa phương đưa ra đảm bảo rằng dự án phát triển mới sẽ không làm thu hẹp không gian tiếp cận các công viên công cộng.","audioKind":"ex2"}],"collocations":[{"en":"give an assurance","vi":"đưa ra lời đảm bảo"},{"en":"quality assurance","vi":"đảm bảo chất lượng"},{"en":"speak with assurance","vi":"nói năng tự tin"},{"en":"life assurance","vi":"bảo hiểm nhân thọ"}],"wordFamily":["assure (v.)","assured (adj.)","reassurance (n.)"],"synonyms":["promise","confidence"],"antonyms":["uncertainty"],"tipVi":"Khi chỉ lời hứa cụ thể thì là danh từ đếm được; khi chỉ sự tự tin thì thường là không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abide', 'en-c1-14', 'abide', '/əˈbaɪd/', 'C1', 'tuân theo một quy tắc, thỏa thuận hoặc quyết định; chịu đựng, dung thứ điều gì đó (thường dùng ở dạng phủ định cannot)', 'v.', NULL, NULL, 'Diễn đạt ý tuân theo dùng abide by; diễn đạt ý chịu đựng thường dùng cannot abide.', 'Everyone using the pool must abide by its rules.', NULL, 'Tất cả mọi người sử dụng hồ bơi đều phải tuân thủ các quy định của nó.', '{"wordId":"abide","ukIpa":"/əˈbaɪd/","usIpa":"/əˈbaɪd/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to follow a rule, agreement, or decision","vi":"tuân theo một quy tắc, thỏa thuận hoặc quyết định"},{"pos":"v.","en":"to tolerate something, usually used with cannot","vi":"chịu đựng, dung thứ điều gì đó (thường dùng ở dạng phủ định cannot)"}],"examples":[{"en":"Everyone using the pool must abide by its rules.","vi":"Tất cả mọi người sử dụng hồ bơi đều phải tuân thủ các quy định của nó.","audioKind":"ex"},{"en":"Companies should abide by environmental regulations even when doing so increases their production costs.","vi":"Các doanh nghiệp nên tuân thủ các quy định về môi trường ngay cả khi việc đó làm tăng chi phí sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"abide by the rules","vi":"tuân thủ quy định"},{"en":"abide by an agreement","vi":"tuân thủ thỏa thuận"},{"en":"cannot abide","vi":"không thể chịu đựng nổi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt ý tuân theo dùng abide by; diễn đạt ý chịu đựng thường dùng cannot abide.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foster', 'en-c1-14', 'foster', '/ˈfɑːstər/', 'C1', 'thúc đẩy; bồi dưỡng; nuôi dưỡng; nhận nuôi tạm thời; nuôi dưỡng (con người khác); nuôi dưỡng (tạm thời); nhận nuôi', 'v.', 'fostering (n.)', 'Đồng nghĩa: encourage, nurture, promote · Trái nghĩa: hinder', 'foster thường chỉ việc nhận nuôi tạm thời; adopt chỉ việc nhận con nuôi hợp pháp.', 'Shared meals foster closer friendships among our neighbours.', NULL, 'Những bữa ăn chung giúp thắt chặt tình bạn giữa hàng xóm với nhau.', '{"wordId":"foster","ukIpa":"/ˈfɒstə/","usIpa":"/ˈfɑːstər/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"to encourage something to develop or grow","vi":"thúc đẩy; bồi dưỡng; nuôi dưỡng"},{"pos":"v.","en":"to care for another person''s child, usually temporarily","vi":"nhận nuôi tạm thời; nuôi dưỡng (con người khác)"},{"pos":"adj.","en":"involving care for a child by someone other than their parents","vi":"nuôi dưỡng (tạm thời); nhận nuôi"}],"examples":[{"en":"Shared meals foster closer friendships among our neighbours.","vi":"Những bữa ăn chung giúp thắt chặt tình bạn giữa hàng xóm với nhau.","audioKind":"ex"},{"en":"Schools can foster creativity by allowing students to explore problems without prescribing a single solution.","vi":"Nhà trường có thể bồi dưỡng sự sáng tạo bằng cách cho phép học sinh tự khám phá vấn đề mà không áp đặt một lời giải duy nhất.","audioKind":"ex2"}],"collocations":[{"en":"foster creativity","vi":"bồi dưỡng sự sáng tạo"},{"en":"foster cooperation","vi":"thúc đẩy sự hợp tác"},{"en":"foster a child","vi":"nhận nuôi một đứa trẻ"},{"en":"foster parents","vi":"cha mẹ nuôi (tạm thời)"}],"wordFamily":["fostering (n.)"],"synonyms":["encourage","nurture","promote"],"antonyms":["hinder"],"tipVi":"foster thường chỉ việc nhận nuôi tạm thời; adopt chỉ việc nhận con nuôi hợp pháp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jeopardize', 'en-c1-14', 'jeopardize', '/ˈdʒepərdaɪz/', 'C1', 'gây nguy hiểm; làm tổn hại; đe dọa', 'v.', 'jeopardy (n.)', 'Đồng nghĩa: endanger, imperil · Trái nghĩa: safeguard, protect', 'Đi trực tiếp với tân ngữ; trong tiếng Anh-Anh cũng thường viết là jeopardise.', 'Skipping these safety checks could jeopardize the whole trip.', NULL, 'Việc bỏ qua những bước kiểm tra an toàn này có thể gây nguy hiểm cho cả chuyến đi.', '{"wordId":"jeopardize","ukIpa":"/ˈdʒepədaɪz/","usIpa":"/ˈdʒepərdaɪz/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To put something valuable at risk of harm or loss.","vi":"gây nguy hiểm; làm tổn hại; đe dọa"}],"examples":[{"en":"Skipping these safety checks could jeopardize the whole trip.","vi":"Việc bỏ qua những bước kiểm tra an toàn này có thể gây nguy hiểm cho cả chuyến đi.","audioKind":"ex"},{"en":"Excessive use of groundwater could jeopardize future food production in regions already affected by drought.","vi":"Việc khai thác nước ngầm quá mức có thể đe dọa sản xuất lương thực trong tương lai tại các khu vực vốn đã chịu ảnh hưởng bởi hạn hán.","audioKind":"ex2"}],"collocations":[{"en":"jeopardize safety","vi":"gây nguy hiểm cho sự an toàn"},{"en":"jeopardize prospects","vi":"làm tổn hại triển vọng"},{"en":"jeopardize a relationship","vi":"đe dọa một mối quan hệ"}],"wordFamily":["jeopardy (n.)"],"synonyms":["endanger","imperil"],"antonyms":["safeguard","protect"],"tipVi":"Đi trực tiếp với tân ngữ; trong tiếng Anh-Anh cũng thường viết là jeopardise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_successive', 'en-c1-14', 'successive', '/səkˈsesɪv/', 'C1', 'liên tiếp; nối tiếp nhau không ngừng', 'adj.', 'succession (n.), successively (adv.), successor (n.), succeed (v.)', 'Đồng nghĩa: consecutive', 'successive có nghĩa là liên tiếp; trong khi successful mới là thành công.', 'Heavy rain kept us indoors for three successive days.', NULL, 'Mưa lớn khiến chúng tôi phải ở trong nhà suốt ba ngày liên tiếp.', '{"wordId":"successive","ukIpa":"/səkˈsesɪv/","usIpa":"/səkˈsesɪv/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"following one after another without a break","vi":"liên tiếp; nối tiếp nhau không ngừng"}],"examples":[{"en":"Heavy rain kept us indoors for three successive days.","vi":"Mưa lớn khiến chúng tôi phải ở trong nhà suốt ba ngày liên tiếp.","audioKind":"ex"},{"en":"Successive governments have invested in public transport, but rural communities still lack reliable bus services.","vi":"Các thế hệ chính phủ liên tiếp đã đầu tư vào giao thông công cộng, nhưng các cộng đồng nông thôn vẫn thiếu dịch vụ xe buýt đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"successive generations","vi":"các thế hệ tiếp nối"},{"en":"successive governments","vi":"các đời chính phủ liên tiếp"},{"en":"successive years","vi":"nhiều năm liên tiếp"}],"wordFamily":["succession (n.)","successively (adv.)","successor (n.)","succeed (v.)"],"synonyms":["consecutive"],"antonyms":[],"tipVi":"successive có nghĩa là liên tiếp; trong khi successful mới là thành công.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_persecute', 'en-c1-14', 'persecute', '/ˈpɝːsɪkjuːt/', 'C1', 'bức xạ; đối xử tàn nhược do tín ngưỡng hoặc thân phận; quấy rầy; liên tục làm phiền hoặc đối xử bất công', 'v.', 'persecution (n.), persecutor (n.)', 'Đồng nghĩa: oppress, victimise', 'persecute mang nghĩa bức xạ; prosecute mang nghĩa truy tố trước pháp luật.', 'Her grandparents were persecuted because of their religious beliefs.', NULL, 'Ông bà của cô ấy từng bị bức xạ vì niềm tin tôn giáo của mình.', '{"wordId":"persecute","ukIpa":"/ˈpɜːsɪkjuːt/","usIpa":"/ˈpɝːsɪkjuːt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To treat people cruelly because of their beliefs or identity.","vi":"bức xạ; đối xử tàn nhược do tín ngưỡng hoặc thân phận"},{"pos":"v.","en":"To repeatedly trouble someone or treat them unfairly.","vi":"quấy rầy; liên tục làm phiền hoặc đối xử bất công"}],"examples":[{"en":"Her grandparents were persecuted because of their religious beliefs.","vi":"Ông bà của cô ấy từng bị bức xạ vì niềm tin tôn giáo của mình.","audioKind":"ex"},{"en":"Governments must protect minority communities and ensure that nobody is persecuted for peacefully expressing their beliefs.","vi":"Chính phủ phải bảo vệ các cộng đồng thiểu số và đảm bảo không ai bị bức xạ vì thể hiện niềm tin một cách hòa bình.","audioKind":"ex2"}],"collocations":[{"en":"religiously persecuted","vi":"bị bức xạ vì tôn giáo"},{"en":"persecute minorities","vi":"bức xạ các nhóm thiểu số"},{"en":"persecuted for their beliefs","vi":"bị bức xạ vì niềm tin"}],"wordFamily":["persecution (n.)","persecutor (n.)"],"synonyms":["oppress","victimise"],"antonyms":[],"tipVi":"persecute mang nghĩa bức xạ; prosecute mang nghĩa truy tố trước pháp luật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inmate', 'en-c1-14', 'inmate', '/ˈɪnmeɪt/', 'C1', 'tù nhân; người đang thụ án', 'n.', NULL, 'Đồng nghĩa: prisoner', 'Từ này hiện đại thường chỉ tù nhân, không dùng để chỉ bạn cùng phòng hay cư dân thông thường.', 'Each inmate can borrow books from the prison library.', NULL, 'Mỗi tù nhân đều có thể mượn sách từ thư viện của nhà trại.', '{"wordId":"inmate","ukIpa":"/ˈɪnmeɪt/","usIpa":"/ˈɪnmeɪt/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"A person who is kept in a prison.","vi":"tù nhân; người đang thụ án"}],"examples":[{"en":"Each inmate can borrow books from the prison library.","vi":"Mỗi tù nhân đều có thể mượn sách từ thư viện của nhà trại.","audioKind":"ex"},{"en":"Providing inmates with vocational training may improve their employment prospects and reduce the risk of reoffending.","vi":"Việc cung cấp đào tạo nghề cho các phạm nhân có thể cải thiện triển vọng việc làm của họ và làm giảm nguy cơ tái phạm.","audioKind":"ex2"}],"collocations":[{"en":"prison inmate","vi":"tù nhân trong trại giam"},{"en":"inmate rehabilitation","vi":"cải tạo phạm nhân"},{"en":"former inmate","vi":"người từng thụ án"}],"wordFamily":[],"synonyms":["prisoner"],"antonyms":[],"tipVi":"Từ này hiện đại thường chỉ tù nhân, không dùng để chỉ bạn cùng phòng hay cư dân thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_patriotic', 'en-c1-14', 'patriotic', '/ˌpeɪtriˈɑːtɪk/', 'C1', 'yêu nước; thể hiện lòng yêu nước', 'adj.', 'patriot (n.), patriotism (n.), patriotically (adv.)', 'Trái nghĩa: unpatriotic', 'patriotic nhấn mạnh lòng yêu nước, không nhất thiết mang nghĩa bài xích các quốc gia khác.', 'My grandfather enjoys singing patriotic songs during national celebrations.', NULL, 'Ông nội tôi thích hát các bài hát ca ngợi đất nước trong các dịp lễ lớn của quốc gia.', '{"wordId":"patriotic","ukIpa":"/ˌpætriˈɒtɪk/","usIpa":"/ˌpeɪtriˈɑːtɪk/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Showing love for and pride in your country.","vi":"yêu nước; thể hiện lòng yêu nước"}],"examples":[{"en":"My grandfather enjoys singing patriotic songs during national celebrations.","vi":"Ông nội tôi thích hát các bài hát ca ngợi đất nước trong các dịp lễ lớn của quốc gia.","audioKind":"ex"},{"en":"Patriotic feeling can encourage community service, but it should not prevent citizens from questioning government policies.","vi":"Tình thần yêu nước có thể thúc đẩy các hoạt động vì cộng đồng, nhưng nó không nên ngăn cản công dân đặt câu hỏi về các chính sách của chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"patriotic pride","vi":"lòng tự hào yêu nước"},{"en":"patriotic songs","vi":"các bài hát yêu nước"},{"en":"patriotic duty","vi":"trách nhiệm yêu nước"}],"wordFamily":["patriot (n.)","patriotism (n.)","patriotically (adv.)"],"synonyms":[],"antonyms":["unpatriotic"],"tipVi":"patriotic nhấn mạnh lòng yêu nước, không nhất thiết mang nghĩa bài xích các quốc gia khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vulgar', 'en-c1-14', 'vulgar', '/ˈvʌlɡɚ/', 'C1', 'thô tục; tục tĩu; kém văn minh; kém thẩm mỹ; phô trương kệch cỡm', 'adj.', 'vulgarity (n.), vulgarly (adv.)', 'Đồng nghĩa: crude, coarse, tasteless · Trái nghĩa: refined', 'Nghĩa hiện đại thường mang hàm ý chê bai, không dùng để chỉ sự "thông thường" hay "bình thường".', 'His vulgar joke made everyone at dinner uncomfortable.', NULL, 'Câu nói đùa thô tục của anh ta khiến mọi người trong bữa tối cảm thấy khó chịu.', '{"wordId":"vulgar","ukIpa":"/ˈvʌlɡə/","usIpa":"/ˈvʌlɡɚ/","cefr":"C1","topic":"society","senses":[{"pos":"adj.","en":"Rude or offensive, especially in language or behaviour.","vi":"thô tục; tục tĩu; kém văn minh"},{"pos":"adj.","en":"Lacking good taste, especially through excessive display.","vi":"kém thẩm mỹ; phô trương kệch cỡm"}],"examples":[{"en":"His vulgar joke made everyone at dinner uncomfortable.","vi":"Câu nói đùa thô tục của anh ta khiến mọi người trong bữa tối cảm thấy khó chịu.","audioKind":"ex"},{"en":"Some viewers argue that vulgar humour on television can encourage disrespectful behaviour among younger audiences.","vi":"Một số khán giả cho rằng sự hài hước thô tục trên truyền hình có thể khuyến khích hành vi thiếu tôn trọng ở đối tượng khán giả trẻ tuổi.","audioKind":"ex2"}],"collocations":[{"en":"vulgar language","vi":"ngôn từ thô tục"},{"en":"vulgar joke","vi":"câu đùa tục tĩu"},{"en":"vulgar display of wealth","vi":"hành vi khoe khoang giàu có kệch cỡm"}],"wordFamily":["vulgarity (n.)","vulgarly (adv.)"],"synonyms":["crude","coarse","tasteless"],"antonyms":["refined"],"tipVi":"Nghĩa hiện đại thường mang hàm ý chê bai, không dùng để chỉ sự \"thông thường\" hay \"bình thường\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alienate', 'en-c1-14', 'alienate', '/ˈeɪliəneɪt/', 'C1', 'làm xa lánh; khiến ai đó không muốn ủng hộ', 'v.', 'alienation (n.), alienated (adj.), alienating (adj.)', NULL, 'Thường chỉ làm người khác xa lánh hoặc mất đi sự ủng hộ, không mang nghĩa là chiếm dụng.', 'His constant complaints alienated even his closest friends.', NULL, 'Những lời phàn nàn liên miên của anh ấy đã làm xa lánh cả những người bạn thân thiết nhất.', '{"wordId":"alienate","ukIpa":"/ˈeɪliəneɪt/","usIpa":"/ˈeɪliəneɪt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"Make someone feel unwelcome or unwilling to support you","vi":"làm xa lánh; khiến ai đó không muốn ủng hộ"}],"examples":[{"en":"His constant complaints alienated even his closest friends.","vi":"Những lời phàn nàn liên miên của anh ấy đã làm xa lánh cả những người bạn thân thiết nhất.","audioKind":"ex"},{"en":"Public transport policies may alienate residents if local authorities fail to explain their benefits clearly.","vi":"Các chính sách giao thông công cộng có thể làm mất đi sự ủng hộ của cư dân nếu chính quyền địa phương không giải thích rõ ràng lợi ích của chúng.","audioKind":"ex2"}],"collocations":[{"en":"alienate voters","vi":"làm mất lòng cử tri"},{"en":"alienate customers","vi":"làm khách hàng xa lánh"},{"en":"alienate someone from","vi":"làm ai đó xa cách với"}],"wordFamily":["alienation (n.)","alienated (adj.)","alienating (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ làm người khác xa lánh hoặc mất đi sự ủng hộ, không mang nghĩa là chiếm dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_segregate', 'en-c1-14', 'segregate', '/ˈseɡrɪɡeɪt/', 'C1', 'phân biệt đối xử; thực hiện phân biệt chủng tộc; tách riêng; phân loại thành các nhóm hoặc khu vực khác nhau', 'v.', 'segregation (n.), segregated (adj.)', 'Đồng nghĩa: separate, isolate · Trái nghĩa: integrate', 'Cấu trúc segregate A from B dùng để chỉ việc tách rời A khỏi B.', 'The club refused to segregate children by family income.', NULL, 'Câu lạc bộ từ chối việc phân tách trẻ em dựa trên thu nhập gia đình.', '{"wordId":"segregate","ukIpa":"/ˈseɡrɪɡeɪt/","usIpa":"/ˈseɡrɪɡeɪt/","cefr":"C1","topic":"society","senses":[{"pos":"v.","en":"To keep people apart based on race or other characteristics.","vi":"phân biệt đối xử; thực hiện phân biệt chủng tộc"},{"pos":"v.","en":"To separate things into different groups or locations.","vi":"tách riêng; phân loại thành các nhóm hoặc khu vực khác nhau"}],"examples":[{"en":"The club refused to segregate children by family income.","vi":"Câu lạc bộ từ chối việc phân tách trẻ em dựa trên thu nhập gia đình.","audioKind":"ex"},{"en":"Schools that segregate pupils by social background may reinforce inequality rather than promote mutual understanding.","vi":"Các trường học phân loại học sinh theo hoàn cảnh xã hội có thể củng cố tình trạng bất công thay vì thúc đẩy sự thấu hiểu lẫn nhau.","audioKind":"ex2"}],"collocations":[{"en":"segregate by race","vi":"phân biệt theo chủng tộc"},{"en":"segregate waste","vi":"phân loại rác thải"},{"en":"racially segregated schools","vi":"các trường học bị chia rẽ theo chủng tộc"}],"wordFamily":["segregation (n.)","segregated (adj.)"],"synonyms":["separate","isolate"],"antonyms":["integrate"],"tipVi":"Cấu trúc segregate A from B dùng để chỉ việc tách rời A khỏi B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_craze', 'en-c1-14', 'craze', '/kreɪz/', 'C1', 'cơn sốt nhất thời; trào lưu thịnh hành ngắn ngủi', 'n.', 'crazed (adj.), crazy (adj.)', 'Đồng nghĩa: fad, mania', 'Nhấn mạnh sự thịnh hành trong thời gian ngắn; thường dùng cụm a craze for đi với danh từ.', 'The latest dance craze has everyone moving at parties.', NULL, 'Trào lưu khiêu vũ mới nhất khiến tất cả mọi người đều nhún nhảy trong các bữa tiệc.', '{"wordId":"craze","ukIpa":"/kreɪz/","usIpa":"/kreɪz/","cefr":"C1","topic":"society","senses":[{"pos":"n.","en":"an activity or fashion that becomes extremely popular briefly","vi":"cơn sốt nhất thời; trào lưu thịnh hành ngắn ngủi"}],"examples":[{"en":"The latest dance craze has everyone moving at parties.","vi":"Trào lưu khiêu vũ mới nhất khiến tất cả mọi người đều nhún nhảy trong các bữa tiệc.","audioKind":"ex"},{"en":"Social media can turn a local fashion into a global craze within a remarkably short period.","vi":"Mạng xã hội có thể biến một xu hướng địa phương thành cơn sốt toàn cầu chỉ trong một khoảng thời gian cực2 ngắn.","audioKind":"ex2"}],"collocations":[{"en":"the latest craze","vi":"trào lưu mới nhất"},{"en":"a craze for something","vi":"cơn sốt cuồng nhiệt đối với cái gì"},{"en":"a fitness craze","vi":"cơn sốt tập thể hình"}],"wordFamily":["crazed (adj.)","crazy (adj.)"],"synonyms":["fad","mania"],"antonyms":[],"tipVi":"Nhấn mạnh sự thịnh hành trong thời gian ngắn; thường dùng cụm a craze for đi với danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_14_1', 'en-c1-14', 'Cách dùng “ruthless” (adj.) — nhẫn tâm; tàn nhẫn; quyết liệt (bất chấp gây tổn thương cho người khác)', 'ruthless competition  ·  ruthless ambition  ·  a ruthless leader', 'Mang ý nghĩa mạnh hơn strict, nhấn mạnh việc đạt được mục đích mà không màng tới cảm xúc hay lợi ích của người khác.', 'Họ từ (Word Family): ruthlessly (adv.), ruthlessness (n.) | Đồng nghĩa: merciless, pitiless, relentless · Trái nghĩa: compassionate, merciful', '[{"hanzi":"The ruthless landlord evicted the family without any warning.","pinyin":"","meaning":"Gã chủ nhà tàn nhẫn đã đuổi cả gia đình đi mà không có bất kỳ lời cảnh báo nào."},{"hanzi":"Ruthless competition may encourage companies to cut labour costs at the expense of employee welfare.","pinyin":"","meaning":"Cạnh tranh khốc liệt có thể thúc đẩy các doanh nghiệp cắt giảm chi phí nhân công bằng cách đánh đổi phúc lợi của nhân viên."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_14_2', 'en-c1-14', 'Cách dùng “entity” (n.) — thực thể độc lập; tổ chức riêng biệt', 'a separate entity  ·  a legal entity  ·  a commercial entity', 'Nhấn mạnh vào một đơn vị tồn tại độc lập, thường được sử dụng trong các ngữ cảnh tổ chức, pháp lý hoặc thương mại.', NULL, '[{"hanzi":"Our small bakery now operates as a separate entity.","pinyin":"","meaning":"Tiệm bánh nhỏ của chúng tôi giờ đây hoạt động như một thực thể riêng biệt."},{"hanzi":"Each university should remain an independent entity while cooperating with other institutions on important research projects.","pinyin":"","meaning":"Mỗi trường đại học nên duy trì là một thực thể độc lập trong khi vẫn hợp tác với các cơ quan khác trong các dự án nghiên cứu quan trọng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_14_3', 'en-c1-14', 'Cách dùng “rampant” (adj.) — lan tràn; hoành hành; không kiểm soát được (thường mang nghĩa tiêu cực)', 'rampant corruption  ·  run rampant  ·  rampant inflation', 'Thường dùng để mô tả tệ nạn tham nhũng, dịch bệnh lan rộng; cụm ''run rampant'' có nghĩa là hoành hành, tung hoành.', 'Họ từ (Word Family): rampantly (adv.) | Đồng nghĩa: uncontrolled, unchecked · Trái nghĩa: controlled', '[{"hanzi":"Rampant weeds have taken over our vegetable patch.","pinyin":"","meaning":"Cỏ dại mọc um tùm đã chiếm hết khu vườn trồng rau của chúng tôi."},{"hanzi":"Where oversight is weak, rampant corruption can undermine public trust and divert resources away from essential services.","pinyin":"","meaning":"Ở những nơi công tác giám sát lỏng lẻo, tình trạng tham nhũng lan tràn có thể xói mòn lòng tin của công chúng và làm chệch hướng nguồn lực khỏi các dịch vụ thiết yếu."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_14_4', 'en-c1-14', 'Cách dùng “maturity” (n.) — sự chín chắn; tính điềm tĩnh', 'emotional maturity  ·  reach maturity  ·  a maturity date', 'Thường là danh từ không đếm được; trong ngữ cảnh tài chính, at maturity có nghĩa là vào thời điểm đáo hạn.', 'Họ từ (Word Family): mature (adj.), mature (v.), immature (adj.), immaturity (n.) | Trái nghĩa: immaturity', '[{"hanzi":"Lena showed maturity by calmly admitting her mistake.","pinyin":"","meaning":"Lena thể hiện sự chín chắn bằng cách bình tĩnh thừa nhận lỗi lầm của mình."},{"hanzi":"Schools can foster emotional maturity by encouraging students to resolve disagreements respectfully and consider different perspectives.","pinyin":"","meaning":"Các trường học có thể thúc đẩy sự trưởng thành về mặt cảm xúc bằng cách khuyến khích học sinh giải quyết bất đồng một cách tôn trọng và cân nhắc các góc nhìn khác nhau."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_14_1', 'en-c1-14', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_1_1', 'ten_c1_14_1', 'ruthless', 'The ruthless landlord evicted the family without any warning.', 'The ruthless landlord evicted the family without any warning.', '/ˈruːθləs/', 'Gã chủ nhà tàn nhẫn đã đuổi cả gia đình đi mà không có bất kỳ lời cảnh báo nào.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_1_2', 'ten_c1_14_1', 'arbitrary', 'Her choice felt arbitrary: she picked without even looking.', 'Her choice felt arbitrary: she picked without even looking.', '/ˈɑːrbɪtreri/', 'Lựa chọn của cô ấy có vẻ tùy tiện: cô ấy chọn mà chẳng thèm nhìn lấy một cái.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_1_3', 'ten_c1_14_1', 'savage', 'The documentary showed a savage fight between two wolves.', 'The documentary showed a savage fight between two wolves.', '/ˈsævɪdʒ/', 'Bộ phim tài liệu ghi lại cảnh chiến đấu dữ dội giữa hai con sói.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_1_4', 'ten_c1_14_1', 'maturity', 'Lena showed maturity by calmly admitting her mistake.', 'Lena showed maturity by calmly admitting her mistake.', '/məˈtʃʊrəti/', 'Lena thể hiện sự chín chắn bằng cách bình tĩnh thừa nhận lỗi lầm của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_1_5', 'ten_c1_14_1', 'entity', 'Our small bakery now operates as a separate entity.', 'Our small bakery now operates as a separate entity.', '/ˈentəti/', 'Tiệm bánh nhỏ của chúng tôi giờ đây hoạt động như một thực thể riêng biệt.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_1_6', 'ten_c1_14_1', 'irrespective', 'Everyone can join the walk, irrespective of their age.', 'Everyone can join the walk, irrespective of their age.', '/ˌɪrɪˈspektɪv/', 'Ai cũng có thể tham gia chuyến đi bộ này, bất kể độ tuổi của họ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_1_7', 'ten_c1_14_1', 'reliant', 'Without a car, we are reliant on local buses.', 'Without a car, we are reliant on local buses.', '/rɪˈlaɪənt/', 'Không có ô tô, chúng tôi hoàn toàn phụ thuộc vào xe buýt địa phương.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_1_8', 'ten_c1_14_1', 'disregard', 'Please disregard my earlier message; the picnic is still happening.', 'Please disregard my earlier message; the picnic is still happening.', '/ˌdɪsrɪˈɡɑːrd/', 'Hãy bỏ qua tin nhắn trước của tôi; buổi dã ngoại vẫn diễn ra như kế hoạch.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_14_1_1', 'en-c1-14', 'ten_c1_14_1', 'listening', 'listening', 'The ruthless landlord evicted the family without any warning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ông nội tôi thích hát các bài hát ca ngợi đất nước trong các dịp lễ lớn của quốc gia.","Tài xế đó chạy xe như điên, phóng bạt mạng qua mọi khúc cua.","Gã chủ nhà tàn nhẫn đã đuổi cả gia đình đi mà không có bất kỳ lời cảnh báo nào.","Ông bà của cô ấy từng bị bức xạ vì niềm tin tôn giáo của mình."]'::jsonb, 2, 'The ruthless landlord evicted the family without any warning. → Gã chủ nhà tàn nhẫn đã đuổi cả gia đình đi mà không có bất kỳ lời cảnh báo nào.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_14_1_2', 'en-c1-14', 'ten_c1_14_1', 'listening', 'listening', 'Her choice felt arbitrary: she picked without even looking.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người hàng xóm thân thiện của chúng tôi luôn dừng lại trò chuyện bên cổng.","Lựa chọn của cô ấy có vẻ tùy tiện: cô ấy chọn mà chẳng thèm nhìn lấy một cái.","Mưa lớn khiến chúng tôi phải ở trong nhà suốt ba ngày liên tiếp.","Ông nội tôi thích hát các bài hát ca ngợi đất nước trong các dịp lễ lớn của quốc gia."]'::jsonb, 1, 'Her choice felt arbitrary: she picked without even looking. → Lựa chọn của cô ấy có vẻ tùy tiện: cô ấy chọn mà chẳng thèm nhìn lấy một cái.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_14_1_3', 'en-c1-14', 'ten_c1_14_1', 'listening', 'listening', 'The documentary showed a savage fight between two wolves.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy bỏ qua tin nhắn trước của tôi; buổi dã ngoại vẫn diễn ra như kế hoạch.","Những lời phàn nàn liên miên của anh ấy đã làm xa lánh cả những người bạn thân thiết nhất.","Bộ phim tài liệu ghi lại cảnh chiến đấu dữ dội giữa hai con sói.","Học nấu ăn giúp anh ấy có khả năng tự lập trong cuộc sống."]'::jsonb, 2, 'The documentary showed a savage fight between two wolves. → Bộ phim tài liệu ghi lại cảnh chiến đấu dữ dội giữa hai con sói.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_14_2', 'en-c1-14', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_2_1', 'ten_c1_14_2', 'ruthless', 'Ruthless competition may encourage companies to cut labour costs at the expense of employee welfare.', 'Ruthless competition may encourage companies to cut labour costs at the expense of employee welfare.', '/ˈruːθləs/', 'Cạnh tranh khốc liệt có thể thúc đẩy các doanh nghiệp cắt giảm chi phí nhân công bằng cách đánh đổi phúc lợi của nhân viên.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_2_2', 'ten_c1_14_2', 'arbitrary', 'Arbitrary restrictions on university admissions can prevent capable students from accessing education and may reinforce existing social inequalities.', 'Arbitrary restrictions on university admissions can prevent capable students from accessing education and may reinforce existing social inequalities.', '/ˈɑːrbɪtreri/', 'Những hạn chế mang tính cảm tính đối với việc tuyển sinh đại học có thể ngăn cản những học sinh có năng lực tiếp cận giáo dục và làm trầm trọng thêm sự bất công xã hội hiện hữu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_2_3', 'ten_c1_14_2', 'savage', 'The proposed reduction in education funding attracted savage criticism from teachers and parents across the country.', 'The proposed reduction in education funding attracted savage criticism from teachers and parents across the country.', '/ˈsævɪdʒ/', 'Đề xuất cắt giảm ngân sách giáo dục đã vấp phải sự chỉ trích gay gắt từ giáo viên và phụ huynh trên cả nước.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_2_4', 'ten_c1_14_2', 'maturity', 'Schools can foster emotional maturity by encouraging students to resolve disagreements respectfully and consider different perspectives.', 'Schools can foster emotional maturity by encouraging students to resolve disagreements respectfully and consider different perspectives.', '/məˈtʃʊrəti/', 'Các trường học có thể thúc đẩy sự trưởng thành về mặt cảm xúc bằng cách khuyến khích học sinh giải quyết bất đồng một cách tôn trọng và cân nhắc các góc nhìn khác nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_2_5', 'ten_c1_14_2', 'entity', 'Each university should remain an independent entity while cooperating with other institutions on important research projects.', 'Each university should remain an independent entity while cooperating with other institutions on important research projects.', '/ˈentəti/', 'Mỗi trường đại học nên duy trì là một thực thể độc lập trong khi vẫn hợp tác với các cơ quan khác trong các dự án nghiên cứu quan trọng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_14_2_6', 'ten_c1_14_2', 'irrespective', 'Quality education should be available to all children, irrespective of their family income or social background.', 'Quality education should be available to all children, irrespective of their family income or social background.', '/ˌɪrɪˈspektɪv/', 'Mọi trẻ em đều cần được tiếp cận nền giáo dục chất lượng cao, bất kể thu nhập gia đình hay hoàn cảnh xã hội ra sao.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_14_2_1', 'en-c1-14', 'ten_c1_14_2', 'listening', 'listening', 'Ruthless competition may encourage companies to cut labour costs at the expense of employee welfare.', NULL, 'Trong câu vừa nghe, từ “ruthless” mang nghĩa nào sau đây?', '["sự cải tiến; sự tinh chỉnh nhỏ để hoàn thiện hơn","cần thiết, thiết yếu cho một mục đích cụ thể","truyền bá; tuyên truyền","nhẫn tâm; tàn nhẫn; quyết liệt (bất chấp gây tổn thương cho người khác)"]'::jsonb, 3, '“ruthless” (/ˈruːθləs/): nhẫn tâm; tàn nhẫn; quyết liệt (bất chấp gây tổn thương cho người khác). Câu đầy đủ: Ruthless competition may encourage companies to cut labour costs at the expense of employee welfare.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_14_2_2', 'en-c1-14', 'ten_c1_14_2', 'listening', 'listening', 'Arbitrary restrictions on university admissions can prevent capable students from accessing education and may reinforce existing social inequalities.', NULL, 'Trong câu vừa nghe, từ “arbitrary” mang nghĩa nào sau đây?', '["tùy tiện; ngẫu nhiên (không dựa trên lý do hay cơ sở rõ ràng)","cồng kềnh; to lớn vướng víu","sự sửa đổi; điều khoản bổ sung; bản sửa đổi","thuộc về sân khấu; kịch nghệ"]'::jsonb, 0, '“arbitrary” (/ˈɑːrbɪtreri/): tùy tiện; ngẫu nhiên (không dựa trên lý do hay cơ sở rõ ràng). Câu đầy đủ: Arbitrary restrictions on university admissions can prevent capable students from accessing education and may reinforce existing social inequalities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
