INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_1', 'en-c1-14', NULL, 'comprehensive_test', 'listening', 'ruthless', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhẫn tâm; tàn nhẫn; quyết liệt (bất chấp gây tổn thương cho người khác)","quân tốt (trong cờ vua)","thẳng thắn bày tỏ quan điểm; công khai chỉ trích","hùng mạnh; to lớn"]'::jsonb, 0, 'ruthless (/ˈruːθləs/) → nhẫn tâm; tàn nhẫn; quyết liệt (bất chấp gây tổn thương cho người khác)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_2', 'en-c1-14', NULL, 'comprehensive_test', 'listening', 'Her choice felt arbitrary: she picked without even looking.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bộ phim tài liệu ghi lại cảnh chiến đấu dữ dội giữa hai con sói.","Cỏ dại mọc um tùm đã chiếm hết khu vườn trồng rau của chúng tôi.","Ai cũng có thể tham gia chuyến đi bộ này, bất kể độ tuổi của họ.","Lựa chọn của cô ấy có vẻ tùy tiện: cô ấy chọn mà chẳng thèm nhìn lấy một cái."]'::jsonb, 3, 'Her choice felt arbitrary: she picked without even looking. → Lựa chọn của cô ấy có vẻ tùy tiện: cô ấy chọn mà chẳng thèm nhìn lấy một cái.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_3', 'en-c1-14', NULL, 'comprehensive_test', 'listening', 'savage', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự phẫn nộ; niềm căm phẫn sâu sắc","tối ưu; thuận lợi nhất","hung dữ; tàn bạo; dữ dội","huy động; điều động"]'::jsonb, 2, 'savage (/ˈsævɪdʒ/) → hung dữ; tàn bạo; dữ dội; khốc liệt; cay nghiệt; tấn công tàn bạo; chỉ trích gay gắt', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_4', 'en-c1-14', NULL, 'comprehensive_test', 'listening', 'Lena showed maturity by calmly admitting her mistake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đã cam đoan với tôi rằng bữa tối đã được chuẩn bị xong.","Ai cũng có thể tham gia chuyến đi bộ này, bất kể độ tuổi của họ.","Lena thể hiện sự chín chắn bằng cách bình tĩnh thừa nhận lỗi lầm của mình.","Việc bỏ qua những bước kiểm tra an toàn này có thể gây nguy hiểm cho cả chuyến đi."]'::jsonb, 2, 'Lena showed maturity by calmly admitting her mistake. → Lena thể hiện sự chín chắn bằng cách bình tĩnh thừa nhận lỗi lầm của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_5', 'en-c1-14', NULL, 'comprehensive_test', 'listening', 'entity', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hệ thống điện báo; máy điện báo","cuốn; xoáy tròn; làm xoáy","thực thể độc lập; tổ chức riêng biệt","có thể quy cho; do... gây ra"]'::jsonb, 2, 'entity (/ˈentəti/) → thực thể độc lập; tổ chức riêng biệt', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_6', 'en-c1-14', NULL, 'comprehensive_test', 'listening', 'Everyone can join the walk, irrespective of their age.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu lạc bộ từ chối việc phân tách trẻ em dựa trên thu nhập gia đình.","Trào lưu khiêu vũ mới nhất khiến tất cả mọi người đều nhún nhảy trong các bữa tiệc.","Bọn trẻ nhao nhao đòi nghe thêm một câu chuyện nữa trước giờ đi ngủ.","Ai cũng có thể tham gia chuyến đi bộ này, bất kể độ tuổi của họ."]'::jsonb, 3, 'Everyone can join the walk, irrespective of their age. → Ai cũng có thể tham gia chuyến đi bộ này, bất kể độ tuổi của họ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_7', 'en-c1-14', NULL, 'comprehensive_test', 'listening', 'reliant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dựa dẫm; phụ thuộc; nhờ vào","vật liệu bán dẫn","âm ấm; hơi ấm","lũng đoạn; độc quyền"]'::jsonb, 0, 'reliant (/rɪˈlaɪənt/) → dựa dẫm; phụ thuộc; nhờ vào', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_8', 'en-c1-14', NULL, 'comprehensive_test', 'listening', 'Please disregard my earlier message; the picnic is still happening.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những bữa ăn chung giúp thắt chặt tình bạn giữa hàng xóm với nhau.","Tài xế đó chạy xe như điên, phóng bạt mạng qua mọi khúc cua.","Học nấu ăn giúp anh ấy có khả năng tự lập trong cuộc sống.","Hãy bỏ qua tin nhắn trước của tôi; buổi dã ngoại vẫn diễn ra như kế hoạch."]'::jsonb, 3, 'Please disregard my earlier message; the picnic is still happening. → Hãy bỏ qua tin nhắn trước của tôi; buổi dã ngoại vẫn diễn ra như kế hoạch.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_9', 'en-c1-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “something that exists independently, especially an organization”?', '["patriotic","entity","persecute","assurance"]'::jsonb, 1, 'entity (/ˈentəti/) → thực thể độc lập; tổ chức riêng biệt', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_10', 'en-c1-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Without considering or being affected by something, used with of.”?', '["assurance","irrespective","persecute","patriotic"]'::jsonb, 1, 'irrespective (/ˌɪrɪˈspektɪv/) → bất kể; không kể; không màng đến', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_11', 'en-c1-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “needing someone or something for support or success”?', '["turbulent","reliant","segregate","vulgar"]'::jsonb, 1, 'reliant (/rɪˈlaɪənt/) → dựa dẫm; phụ thuộc; nhờ vào', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_12', 'en-c1-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To ignore something or treat it as unimportant.”?', '["craze","disregard","turbulent","alienate"]'::jsonb, 1, 'disregard (/ˌdɪsrɪˈɡɑːrd/) → phớt lờ; coi nhẹ; không màng tới', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_13', 'en-c1-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The person someone is married to.”?', '["maturity","craze","reliant","spouse"]'::jsonb, 3, 'spouse (/spaʊs/) → vợ hoặc chồng; phối ngẫu', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
