INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_18', 'en-c1-14', NULL, 'comprehensive_test', 'reading', NULL, 'Ruthless competition may encourage companies to cut labour costs at the expense of employee welfare.', 'Dựa vào câu trên, từ “ruthless” có nghĩa phù hợp nhất là gì?', '["củng cố; làm vững chắc","định lượng; thuộc về số lượng","cúi xuống; khom lưng","nhẫn tâm; tàn nhẫn; quyết liệt (bất chấp gây tổn thương cho người khác)"]'::jsonb, 3, 'ruthless: nhẫn tâm; tàn nhẫn; quyết liệt (bất chấp gây tổn thương cho người khác). Dịch cả câu: Cạnh tranh khốc liệt có thể thúc đẩy các doanh nghiệp cắt giảm chi phí nhân công bằng cách đánh đổi phúc lợi của nhân viên.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_19', 'en-c1-14', NULL, 'comprehensive_test', 'reading', NULL, 'Arbitrary restrictions on university admissions can prevent capable students from accessing education and may reinforce existing social inequalities.', 'Dựa vào câu trên, từ “arbitrary” có nghĩa phù hợp nhất là gì?', '["sẵn sàng và có thể hoạt động hoặc sử dụng được","có tính giáo dục; mang lại nhiều bài học bổ ích","tùy tiện; ngẫu nhiên (không dựa trên lý do hay cơ sở rõ ràng)","phân phối lại; bố trí lại"]'::jsonb, 2, 'arbitrary: tùy tiện; ngẫu nhiên (không dựa trên lý do hay cơ sở rõ ràng); chuyên quyền; độc đoán; độc đoán độc đoán (dựa trên ý chí cá nhân thay vì quy tắc công bằng). Dịch cả câu: Những hạn chế mang tính cảm tính đối với việc tuyển sinh đại học có thể ngăn cản những học sinh có năng lực tiếp cận giáo dục và làm trầm trọng thêm sự bất công xã hội hiện hữu.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_20', 'en-c1-14', NULL, 'comprehensive_test', 'reading', NULL, 'The proposed reduction in education funding attracted savage criticism from teachers and parents across the country.', 'Dựa vào câu trên, từ “savage” có nghĩa phù hợp nhất là gì?', '["tính tiết kiệm; sự chi tiêu tằn tiện","một bầy (gà con, chim non)","cuộn vi phim; phim thu nhỏ","hung dữ; tàn bạo; dữ dội"]'::jsonb, 3, 'savage: hung dữ; tàn bạo; dữ dội; khốc liệt; cay nghiệt; tấn công tàn bạo; chỉ trích gay gắt. Dịch cả câu: Đề xuất cắt giảm ngân sách giáo dục đã vấp phải sự chỉ trích gay gắt từ giáo viên và phụ huynh trên cả nước.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_21', 'en-c1-14', NULL, 'comprehensive_test', 'reading', NULL, 'Schools can foster emotional maturity by encouraging students to resolve disagreements respectfully and consider different perspectives.', 'Dựa vào câu trên, từ “maturity” có nghĩa phù hợp nhất là gì?', '["chính trực; đúng đắn về mặt đạo đức","ngay lập tức; không cần suy nghĩ; không tra cứu","sự chín chắn; tính điềm tĩnh","mỉa mai; châm biếm, cay độc"]'::jsonb, 2, 'maturity: sự chín chắn; tính điềm tĩnh; sự trưởng thành; quá trình phát triển hoàn thiện; thời hạn đáo hạn. Dịch cả câu: Các trường học có thể thúc đẩy sự trưởng thành về mặt cảm xúc bằng cách khuyến khích học sinh giải quyết bất đồng một cách tôn trọng và cân nhắc các góc nhìn khác nhau.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_22', 'en-c1-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “làm xa lánh; khiến ai đó không muốn ủng hộ”', '["midst","alienate","accustom","plank"]'::jsonb, 1, 'làm xa lánh; khiến ai đó không muốn ủng hộ → alienate (/ˈeɪliəneɪt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_23', 'en-c1-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phân biệt đối xử; thực hiện phân biệt chủng tộc”', '["segregate","instrumental","trespass","embed"]'::jsonb, 0, 'phân biệt đối xử; thực hiện phân biệt chủng tộc → segregate (/ˈseɡrɪɡeɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_14_24', 'en-c1-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cơn sốt nhất thời; trào lưu thịnh hành ngắn ngủi”', '["insulation","periodical","exempt","craze"]'::jsonb, 3, 'cơn sốt nhất thời; trào lưu thịnh hành ngắn ngủi → craze (/kreɪz/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-15', 'en', 'Bài 15: Thiên nhiên & Thời tiết (1) - CEFR C1', 'CEFR C1', 'C1 · Thiên nhiên', '25 từ vựng Tiếng Anh CEFR C1 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5015, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_droop', 'en-c1-15', 'droop', '/druːp/', 'C1', 'cúi xuống; rủ xuống', 'v.', 'droopy (adj.)', 'Đồng nghĩa: sag', 'Thường dùng để chỉ hoa lá, mí mắt hoặc vai rủ xuống do thiếu nước hoặc mệt mỏi.', 'The flowers began to droop in the afternoon heat.', NULL, 'Những bông hoa bắt đầu rủ xuống trong cái nắng buổi chiều.', '{"wordId":"droop","ukIpa":"/druːp/","usIpa":"/druːp/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"Hang or bend down, often from weakness or tiredness.","vi":"cúi xuống; rủ xuống"}],"examples":[{"en":"The flowers began to droop in the afternoon heat.","vi":"Những bông hoa bắt đầu rủ xuống trong cái nắng buổi chiều.","audioKind":"ex"},{"en":"During prolonged droughts, leaves often droop as plants lose water and struggle to maintain their structure.","vi":"Trong thời kỳ hạn hán kéo dài, lá cây thường rủ xuống do thực vật bị mất nước và gặp khó khăn trong việc duy trì cấu trúc.","audioKind":"ex2"}],"collocations":[{"en":"drooping eyelids","vi":"mi mắt sụp xuống"},{"en":"flowers droop","vi":"hoa rủ xuống"},{"en":"shoulders droop","vi":"vai trĩu xuống"}],"wordFamily":["droopy (adj.)"],"synonyms":["sag"],"antonyms":[],"tipVi":"Thường dùng để chỉ hoa lá, mí mắt hoặc vai rủ xuống do thiếu nước hoặc mệt mỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snout', 'en-c1-15', 'snout', '/snaʊt/', 'C1', 'mõm (động vật)', 'n.', NULL, NULL, 'Không chỉ dùng cho mõm lợn mà còn chỉ phần mũi và miệng nhô ra của các loài động vật khác.', 'The pig pushed its snout through the wooden fence.', NULL, 'Con lợn thò cái mõm của nó qua hàng rào gỗ.', '{"wordId":"snout","ukIpa":"/snaʊt/","usIpa":"/snaʊt/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"the projecting nose and mouth of an animal","vi":"mõm (động vật)"}],"examples":[{"en":"The pig pushed its snout through the wooden fence.","vi":"Con lợn thò cái mõm của nó qua hàng rào gỗ.","audioKind":"ex"},{"en":"A pig''s sensitive snout helps it locate food beneath the soil, supporting its natural foraging behaviour.","vi":"Cái mõm nhạy cảm của con lợn giúp nó tìm kiếm thức ăn dưới lòng đất, hỗ trợ cho tập tính kiếm ăn tự nhiên của nó.","audioKind":"ex2"}],"collocations":[{"en":"a pig''s snout","vi":"mõm lợn"},{"en":"a long snout","vi":"mõm dài"},{"en":"a pointed snout","vi":"mõm nhọn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Không chỉ dùng cho mõm lợn mà còn chỉ phần mũi và miệng nhô ra của các loài động vật khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alpine', 'en-c1-15', 'alpine', '/ˈælpaɪn/', 'C1', 'thuộc về vùng núi cao; thuộc dãy An-pơ', 'adj.', NULL, NULL, 'Viết thường khi chỉ chung môi trường núi cao; viết hoa khi chỉ riêng dãy Alps.', 'Tiny alpine flowers grew between rocks beside the trail.', NULL, 'Những bông hoa núi cao nhỏ bé mọc chen giữa các khe đá bên cạnh lối đi.', '{"wordId":"alpine","ukIpa":"/ˈælpaɪn/","usIpa":"/ˈælpaɪn/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"relating to high mountains, especially the Alps","vi":"thuộc về vùng núi cao; thuộc dãy An-pơ"}],"examples":[{"en":"Tiny alpine flowers grew between rocks beside the trail.","vi":"Những bông hoa núi cao nhỏ bé mọc chen giữa các khe đá bên cạnh lối đi.","audioKind":"ex"},{"en":"Rising temperatures threaten alpine ecosystems by reducing snow cover and forcing mountain species to move higher.","vi":"Nhiệt độ tăng cao đang đe dọa hệ sinh thái vùng núi cao bằng cách làm giảm lớp tuyết phủ và buộc các loài sinh vật trên núi phải di chuyển lên cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"alpine plants","vi":"thực vật vùng núi cao"},{"en":"alpine meadows","vi":"thảm cỏ núi cao"},{"en":"alpine skiing","vi":"trượt tuyết vùng núi cao"},{"en":"alpine ecosystem","vi":"hệ sinh thái vùng núi cao"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết thường khi chỉ chung môi trường núi cao; viết hoa khi chỉ riêng dãy Alps.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_primate', 'en-c1-15', 'primate', '/ˈpraɪmeɪt/', 'C1', 'động vật linh trưởng', 'n.', NULL, NULL, 'Bao gồm cả con người, vượn và khỉ; không chỉ giới hạn ở loài khỉ.', 'The guide pointed to a primate swinging between branches.', NULL, 'Hướng dẫn viên chỉ tay về phía một con động vật linh trưởng đangu đu đưa giữa các cành cây.', '{"wordId":"primate","ukIpa":"/ˈpraɪmeɪt/","usIpa":"/ˈpraɪmeɪt/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a mammal belonging to the group including humans, monkeys, and apes","vi":"động vật linh trưởng"}],"examples":[{"en":"The guide pointed to a primate swinging between branches.","vi":"Hướng dẫn viên chỉ tay về phía một con động vật linh trưởng đangu đu đưa giữa các cành cây.","audioKind":"ex"},{"en":"Protecting tropical forests is essential for the survival of many primate species threatened by habitat loss.","vi":"Bảo vệ các khu rừng nhiệt đới đóng vai trò cốt yếu đối với sự sinh còn của nhiều loài linh trưởng vốn đang bị đe dọa do mất môi trường sống.","audioKind":"ex2"}],"collocations":[{"en":"primate species","vi":"các loài linh trưởng"},{"en":"primate behaviour","vi":"hành vi của loài linh trưởng"},{"en":"non-human primates","vi":"động vật linh trưởng không phải con người"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Bao gồm cả con người, vượn và khỉ; không chỉ giới hạn ở loài khỉ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_citrus', 'en-c1-15', 'citrus', '/ˈsɪtrəs/', 'C1', 'cây có múi; quả có múi; thuộc về cây có múi', 'n.', NULL, NULL, 'citrus là thuật ngữ chung, bao gồm cam, chanh, bưởi, v.v.', 'We squeezed fresh citrus juice over the salad.', NULL, 'Chúng tôi vắt nước cốt chanh cam tươi lên đĩa rau trộn.', '{"wordId":"citrus","ukIpa":"/ˈsɪtrəs/","usIpa":"/ˈsɪtrəs/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"Trees producing fruits such as oranges and lemons, or their fruits.","vi":"cây có múi; quả có múi"},{"pos":"adj.","en":"Relating to fruits such as oranges, lemons, and grapefruit.","vi":"thuộc về cây có múi"}],"examples":[{"en":"We squeezed fresh citrus juice over the salad.","vi":"Chúng tôi vắt nước cốt chanh cam tươi lên đĩa rau trộn.","audioKind":"ex"},{"en":"Rising temperatures may affect citrus production by increasing water demand and exposing orchards to new pests.","vi":"Nhiệt độ tăng cao có thể ảnh hưởng đến sản lượng cây có múi bằng cách làm tăng nhu cầu nước tưới và khiến các vườn cây ăn quả đối mặt với sâu bệnh mới.","audioKind":"ex2"}],"collocations":[{"en":"citrus fruit","vi":"trái cây có múi"},{"en":"citrus trees","vi":"cây có múi"},{"en":"citrus peel","vi":"vỏ cam chanh"},{"en":"citrus juice","vi":"nước ép trái cây có múi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"citrus là thuật ngữ chung, bao gồm cam, chanh, bưởi, v.v.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glimmer', 'en-c1-15', 'glimmer', '/ˈɡlɪmər/', 'C1', 'ánh sáng mờ; ánh sáng yếu ớt; một chút; một tia (hy vọng, sự thấu hiểu); lóe sáng; tỏa sáng mờ nhạt', 'n.', 'glimmering (adj.)', 'Đồng nghĩa: gleam, flicker', 'a glimmer of hope là cách diễn đạt phổ biến mang nghĩa "một tia hy vọng".', 'A glimmer of candlelight escaped through the closed curtains.', NULL, 'Một chút ánh nến lọt qua khe cửa sổ đang kéo rèm.', '{"wordId":"glimmer","ukIpa":"/ˈɡlɪmə/","usIpa":"/ˈɡlɪmər/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A faint light, often shining unevenly","vi":"ánh sáng mờ; ánh sáng yếu ớt"},{"pos":"n.","en":"A small sign of something, especially hope or understanding","vi":"một chút; một tia (hy vọng, sự thấu hiểu)"},{"pos":"v.","en":"To shine faintly or with an unsteady light","vi":"lóe sáng; tỏa sáng mờ nhạt"}],"examples":[{"en":"A glimmer of candlelight escaped through the closed curtains.","vi":"Một chút ánh nến lọt qua khe cửa sổ đang kéo rèm.","audioKind":"ex"},{"en":"Recent improvements in water quality offer a glimmer of hope for communities affected by industrial pollution.","vi":"Những cải thiện gần đây về chất lượng nước mang đến một tia hy vọng cho các cộng đồng bị ảnh hưởng bởi ô nhiễm công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"a glimmer of light","vi":"một tia sáng mờ"},{"en":"a glimmer of hope","vi":"một tia hy vọng"},{"en":"a glimmer of understanding","vi":"một chút ít sự thấu hiểu"}],"wordFamily":["glimmering (adj.)"],"synonyms":["gleam","flicker"],"antonyms":[],"tipVi":"a glimmer of hope là cách diễn đạt phổ biến mang nghĩa \"một tia hy vọng\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scorch', 'en-c1-15', 'scorch', '/skɔːrtʃ/', 'C1', 'làm cháy xém; làm khô héo', 'v.', 'scorched (adj.), scorching (adj.)', 'Đồng nghĩa: singe, sear', 'Thường chỉ hiện tượng bề mặt bị cháy xém nhẹ chứ không nhất thiết bị thiêu rụi hoàn toàn; ánh nắng mặt trời gắt cũng có thể scorch thực vật.', 'The hot iron scorched my favourite cotton shirt.', NULL, 'Chiếc bàn ủi nóng rẫy đã làm cháy xém chiếc áo sơ mi cotton ưa thích của tôi.', '{"wordId":"scorch","ukIpa":"/skɔːtʃ/","usIpa":"/skɔːrtʃ/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To burn a surface slightly or damage it with heat","vi":"làm cháy xém; làm khô héo"}],"examples":[{"en":"The hot iron scorched my favourite cotton shirt.","vi":"Chiếc bàn ủi nóng rẫy đã làm cháy xém chiếc áo sơ mi cotton ưa thích của tôi.","audioKind":"ex"},{"en":"Prolonged heatwaves can scorch crops, reducing agricultural yields and threatening food supplies in vulnerable regions.","vi":"Các đợt nắng nóng kéo dài có thể làm khô héo mùa màng, làm giảm sản lượng nông nghiệp và đe dọa nguồn cung cấp lương thực tại các khu vực dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"scorch marks","vi":"vết cháy xém"},{"en":"scorch the grass","vi":"làm héo cỏ"},{"en":"scorching heat","vi":"sức nóng như thiêu đốt"}],"wordFamily":["scorched (adj.)","scorching (adj.)"],"synonyms":["singe","sear"],"antonyms":[],"tipVi":"Thường chỉ hiện tượng bề mặt bị cháy xém nhẹ chứ không nhất thiết bị thiêu rụi hoàn toàn; ánh nắng mặt trời gắt cũng có thể scorch thực vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glide', 'en-c1-15', 'glide', '/ɡlaɪd/', 'C1', 'lướt đi; trôi êm ái; di chuyển nhẹ nhàng; bay lượn; bay là là; lượn (không dùng động cơ)', 'v.', 'glider (n.), gliding (n.)', 'Đồng nghĩa: slide', 'Nhấn mạnh sự chuyển động mượt mà, nhẹ nhàng; glide cũng dùng cho việc lượn bay trên không.', 'The swan glided across the pond towards the reeds.', NULL, 'Con thiên nga lướt êm đềm qua mặt hồ hướng về phía bụi lau sậy.', '{"wordId":"glide","ukIpa":"/ɡlaɪd/","usIpa":"/ɡlaɪd/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To move smoothly and easily, often without much noise.","vi":"lướt đi; trôi êm ái; di chuyển nhẹ nhàng"},{"pos":"v.","en":"To fly without engine power or without moving the wings.","vi":"bay lượn; bay là là; lượn (không dùng động cơ)"}],"examples":[{"en":"The swan glided across the pond towards the reeds.","vi":"Con thiên nga lướt êm đềm qua mặt hồ hướng về phía bụi lau sậy.","audioKind":"ex"},{"en":"Large birds conserve energy by gliding on rising air currents rather than continuously flapping their wings.","vi":"Các loài chim lớn tiết kiệm năng lượng bằng cách tận dụng luồng khí bốc lên để lượn thay vì vỗ cánh liên tục.","audioKind":"ex2"}],"collocations":[{"en":"glide across","vi":"lướt qua"},{"en":"glide smoothly","vi":"trôi êm ái"},{"en":"glide through the air","vi":"lướt đi trong không trung"}],"wordFamily":["glider (n.)","gliding (n.)"],"synonyms":["slide"],"antonyms":[],"tipVi":"Nhấn mạnh sự chuyển động mượt mà, nhẹ nhàng; glide cũng dùng cho việc lượn bay trên không.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_platypus', 'en-c1-15', 'platypus', '/ˈplætɪpəs/', 'C1', 'thú mỏ vịt', 'n.', NULL, NULL, 'Mặc dù đẻ trứng, thú mỏ vịt vẫn thuộc lớp thú (động vật có vú).', 'We watched a platypus swimming quietly near the riverbank.', NULL, 'Chúng tôi quan sát một con thú mỏ vịt đang bơi lặng lẽ gần bờ sông.', '{"wordId":"platypus","ukIpa":"/ˈplætɪpəs/","usIpa":"/ˈplætɪpəs/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"An Australian egg-laying mammal with a flat bill and webbed feet.","vi":"thú mỏ vịt"}],"examples":[{"en":"We watched a platypus swimming quietly near the riverbank.","vi":"Chúng tôi quan sát một con thú mỏ vịt đang bơi lặng lẽ gần bờ sông.","audioKind":"ex"},{"en":"Protecting rivers from pollution is essential for the survival of the platypus and other freshwater animals.","vi":"Bảo vệ các dòng sông khỏi ô nhiễm là điều cốt yếu cho sự sinh tồn của thú mỏ vịt và các loài động vật nước ngọt khác.","audioKind":"ex2"}],"collocations":[{"en":"a duck-billed platypus","vi":"con thú mỏ vịt"},{"en":"platypus habitat","vi":"môi trường sống của thú mỏ vịt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Mặc dù đẻ trứng, thú mỏ vịt vẫn thuộc lớp thú (động vật có vú).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inlet', 'en-c1-15', 'inlet', '/ˈɪnlet/', 'C1', 'vũng; vũng nhỏ; lạch; lối vào; cửa vào (chất lỏng hoặc khí)', 'n.', NULL, 'Trái nghĩa: outlet', 'Trong địa lý có nghĩa là vũng/lạch biển; trong kỹ thuật dùng để chỉ nơi chất lưu đi vào, đối lập với outlet.', 'We paddled into a quiet inlet sheltered by cliffs.', NULL, 'Chúng tôi chèo thuyền vào một vũng nước yên tĩnh được che chắn bởi những vách đá.', '{"wordId":"inlet","ukIpa":"/ˈɪnlet/","usIpa":"/ˈɪnlet/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A narrow stretch of water reaching into the land.","vi":"vũng; vũng nhỏ; lạch"},{"pos":"n.","en":"An opening through which liquid or gas enters.","vi":"lối vào; cửa vào (chất lỏng hoặc khí)"}],"examples":[{"en":"We paddled into a quiet inlet sheltered by cliffs.","vi":"Chúng tôi chèo thuyền vào một vũng nước yên tĩnh được che chắn bởi những vách đá.","audioKind":"ex"},{"en":"Coastal inlets provide sheltered habitats for marine species, but pollution can seriously damage these fragile ecosystems.","vi":"Các vũng ven biển cung cấp môi trường sống được che chở cho các loài sinh vật biển, nhưng ô nhiễm có thể gây tổn hại nghiêm trọng đến các hệ sinh thái mỏng manh này.","audioKind":"ex2"}],"collocations":[{"en":"a sheltered inlet","vi":"vũng nhỏ kín gió"},{"en":"a narrow inlet","vi":"một lạch nước hẹp"},{"en":"air inlet","vi":"cửa nạp khí"},{"en":"water inlet","vi":"cửa cấp nước"}],"wordFamily":[],"synonyms":[],"antonyms":["outlet"],"tipVi":"Trong địa lý có nghĩa là vũng/lạch biển; trong kỹ thuật dùng để chỉ nơi chất lưu đi vào, đối lập với outlet.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flourish', 'en-c1-15', 'flourish', '/ˈflɜːrɪʃ/', 'C1', 'phát triển mạnh; hưng thịnh; khuơ; vung vẩy (để thu hút sự chú ý); động tác múa may; chi tiết trang trí hoa mỹ', 'v.', 'flourishing (adj.)', 'Đồng nghĩa: thrive, prosper · Trái nghĩa: decline, wither', 'Khi mang nghĩa phát triển hưng thịnh thì đây là nội động từ, không cộng trực tiếp với tân ngữ.', 'These herbs flourish on our warm, sunny kitchen windowsill.', NULL, 'Những loại rau thơm này phát triển rất tốt trên bệ cửa sổ nhà bếp ấm áp, ngập tràn ánh nắng của chúng tôi.', '{"wordId":"flourish","ukIpa":"/ˈflʌrɪʃ/","usIpa":"/ˈflɜːrɪʃ/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To grow strongly or develop successfully.","vi":"phát triển mạnh; hưng thịnh"},{"pos":"v.","en":"To wave something in a way that attracts attention.","vi":"khuơ; vung vẩy (để thu hút sự chú ý)"},{"pos":"n.","en":"A showy movement or decorative detail.","vi":"động tác múa may; chi tiết trang trí hoa mỹ"}],"examples":[{"en":"These herbs flourish on our warm, sunny kitchen windowsill.","vi":"Những loại rau thơm này phát triển rất tốt trên bệ cửa sổ nhà bếp ấm áp, ngập tràn ánh nắng của chúng tôi.","audioKind":"ex"},{"en":"Small businesses are more likely to flourish when local governments provide affordable premises and reliable public transport.","vi":"Các doanh nghiệp nhỏ có nhiều khả năng phát triển hưng thịnh hơn khi chính quyền địa phương cung cấp mặt bằng giá cả phải chăng và giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"flourish in","vi":"phát triển mạnh mẽ trong"},{"en":"a flourishing business","vi":"một doanh nghiệp đang làm ăn phát đạt"},{"en":"with a flourish","vi":"với một động tác vung tay điệu nghệ"}],"wordFamily":["flourishing (adj.)"],"synonyms":["thrive","prosper"],"antonyms":["decline","wither"],"tipVi":"Khi mang nghĩa phát triển hưng thịnh thì đây là nội động từ, không cộng trực tiếp với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cock', 'en-c1-15', 'cock', '/kɑːk/', 'C1', 'gà trống; con chim đực; vểnh lên; ngẩng lên; nghiêng sang một bên', 'n.', NULL, 'Đồng nghĩa: rooster', 'Từ chỉ gà trống còn có thể dùng rooster; từ cock đôi khi có nghĩa thô tục về tính dục.', 'A red cock crowed loudly beside the wooden gate.', NULL, 'Một con gà trống đỏ cất tiếng gáy vang bên cạnh chiếc cổng gỗ.', '{"wordId":"cock","ukIpa":"/kɒk/","usIpa":"/kɑːk/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"An adult male chicken or another male bird.","vi":"gà trống; con chim đực"},{"pos":"v.","en":"To raise or tilt a body part, especially the head.","vi":"vểnh lên; ngẩng lên; nghiêng sang một bên"}],"examples":[{"en":"A red cock crowed loudly beside the wooden gate.","vi":"Một con gà trống đỏ cất tiếng gáy vang bên cạnh chiếc cổng gỗ.","audioKind":"ex"},{"en":"Keeping a cock alongside hens allows small farms to breed chickens without purchasing new birds.","vi":"Việc nuôi một con gà trống cùng với gà mái giúp các trang trại quy mô nhỏ có thể tự nhân giống gà mà không cần mua thêm gà mới.","audioKind":"ex2"}],"collocations":[{"en":"a cock crows","vi":"gà trống gáy"},{"en":"cock your head","vi":"nghiêng đầu sang một bên"},{"en":"cock an eyebrow","vi":"nhướng mày"}],"wordFamily":[],"synonyms":["rooster"],"antonyms":[],"tipVi":"Từ chỉ gà trống còn có thể dùng rooster; từ cock đôi khi có nghĩa thô tục về tính dục.","noteVi":"Còn có nghĩa thô tục là bộ phận sinh dục nam, cần chú ý ngữ cảnh khi sử dụng.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_twilight', 'en-c1-15', 'twilight', '/ˈtwaɪlaɪt/', 'C1', 'chạng vạng; hoàng hôn; ánh sáng mờ lúc chiều tà hoặc sáng sớm; thời kỳ suy tàn; giai đoạn cuối đời', 'n.', NULL, NULL, 'Thường chỉ ánh sáng sau khi mặt trời lặn, cũng có thể chỉ ánh sáng mờ trước khi mặt trời mọc.', 'We walked home through the park in the twilight.', NULL, 'Chúng tôi đi bộ về nhà qua công viên trong ánh chiều tà.', '{"wordId":"twilight","ukIpa":"/ˈtwaɪlaɪt/","usIpa":"/ˈtwaɪlaɪt/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"The soft light just after sunset or before sunrise","vi":"chạng vạng; hoàng hôn; ánh sáng mờ lúc chiều tà hoặc sáng sớm"},{"pos":"n.","en":"The final stage of something as its strength or importance fades","vi":"thời kỳ suy tàn; giai đoạn cuối đời"}],"examples":[{"en":"We walked home through the park in the twilight.","vi":"Chúng tôi đi bộ về nhà qua công viên trong ánh chiều tà.","audioKind":"ex"},{"en":"In the twilight of their careers, experienced athletes can support younger competitors through coaching and mentoring.","vi":"Ở giai đoạn cuối của sự nghiệp, các vận động viên giàu kinh nghiệm có thể hỗ trợ các vận động viên trẻ hơn thông qua việc huấn luyện và kèm cặp.","audioKind":"ex2"}],"collocations":[{"en":"at twilight","vi":"vào lúc chạng vạng"},{"en":"in the twilight","vi":"trong ánh hoàng hôn"},{"en":"the twilight of a career","vi":"thời kỳ cuối của sự nghiệp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ ánh sáng sau khi mặt trời lặn, cũng có thể chỉ ánh sáng mờ trước khi mặt trời mọc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hound', 'en-c1-15', 'hound', '/haʊnd/', 'C1', 'chó săn; đeo bám; liên tục quấy rầy', 'n.', NULL, 'Đồng nghĩa: harass, pester', 'Khi dùng làm động từ, từ này nhấn mạnh việc quấy rầy liên tục chứ không chỉ đơn thuần là đuổi theo.', 'The hound followed a scent through the wet grass.', NULL, 'Con chó săn lần theo mùi hương xuyên qua bãi cỏ ướt.', '{"wordId":"hound","ukIpa":"/haʊnd/","usIpa":"/haʊnd/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A dog bred to hunt using smell or sight.","vi":"chó săn"},{"pos":"v.","en":"To repeatedly bother or pursue someone.","vi":"đeo bám; liên tục quấy rầy"}],"examples":[{"en":"The hound followed a scent through the wet grass.","vi":"Con chó săn lần theo mùi hương xuyên qua bãi cỏ ướt.","audioKind":"ex"},{"en":"Journalists should not hound people for interviews, particularly when those individuals have clearly requested privacy.","vi":"Phóng viên không nên đeo bám phỏng vấn người khác, đặc biệt là khi những cá nhân đó đã yêu cầu tôn trọng quyền riêng tư một cách rõ ràng.","audioKind":"ex2"}],"collocations":[{"en":"a pack of hounds","vi":"một bầy chó săn"},{"en":"hound someone for answers","vi":"bám riết ai để đòi câu trả lời"},{"en":"hound someone out of office","vi":"gây áp lực ép ai phải từ chức"}],"wordFamily":[],"synonyms":["harass","pester"],"antonyms":[],"tipVi":"Khi dùng làm động từ, từ này nhấn mạnh việc quấy rầy liên tục chứ không chỉ đơn thuần là đuổi theo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_innumerable', 'en-c1-15', 'innumerable', '/ɪˈnuːmərəbl/', 'C1', 'vô số; không thể đếm xuể', 'adj.', 'numerous (adj.), numerable (adj.)', 'Đồng nghĩa: countless, numberless', 'Thường đi kèm với danh từ đếm được số nhiều, mang sắc thái mạnh mẽ hơn từ "many" và có tính trang trọng hơn.', 'Innumerable stars filled the sky above our quiet campsite.', NULL, 'Vô số vì sao bao phủ bầu trời phía trên khu cắm trại yên tĩnh của chúng tôi.', '{"wordId":"innumerable","ukIpa":"/ɪˈnjuːmərəbl/","usIpa":"/ɪˈnuːmərəbl/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"Too many to count.","vi":"vô số; không thể đếm xuể"}],"examples":[{"en":"Innumerable stars filled the sky above our quiet campsite.","vi":"Vô số vì sao bao phủ bầu trời phía trên khu cắm trại yên tĩnh của chúng tôi.","audioKind":"ex"},{"en":"Coastal wetlands support innumerable organisms and provide essential protection against storms for nearby communities.","vi":"Các vùng đất ngập nước ven biển nuôi dưỡng vô số sinh vật và cung cấp lớp bảo vệ thiết yếu chống lại bão cho các cộng đồng gần đó.","audioKind":"ex2"}],"collocations":[{"en":"innumerable examples","vi":"vô số ví dụ"},{"en":"innumerable opportunities","vi":"vô số cơ hội"},{"en":"innumerable times","vi":"vô số lần"}],"wordFamily":["numerous (adj.)","numerable (adj.)"],"synonyms":["countless","numberless"],"antonyms":[],"tipVi":"Thường đi kèm với danh từ đếm được số nhiều, mang sắc thái mạnh mẽ hơn từ \"many\" và có tính trang trọng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brood', 'en-c1-15', 'brood', '/bruːd/', 'C1', 'một bầy (gà con, chim non); nghĩ ngợi vẩn vơ; trầm ngâm lo lắng; ấp trứng; ấp con', 'n.', 'brooding (adj.), broody (adj.)', NULL, 'Khi dùng với nghĩa suy nghĩ âu lo, từ này thường đi với giới từ over hoặc on.', 'The duck led her brood across the quiet pond.', NULL, 'Vịt mẹ dẫn đàn con bơi qua mặt hồ phẳng lặng.', '{"wordId":"brood","ukIpa":"/bruːd/","usIpa":"/bruːd/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A group of young birds born to the same mother.","vi":"một bầy (gà con, chim non)"},{"pos":"v.","en":"To keep thinking unhappily about something.","vi":"nghĩ ngợi vẩn vơ; trầm ngâm lo lắng"},{"pos":"v.","en":"To sit on eggs or young birds to keep them warm.","vi":"ấp trứng; ấp con"}],"examples":[{"en":"The duck led her brood across the quiet pond.","vi":"Vịt mẹ dẫn đàn con bơi qua mặt hồ phẳng lặng.","audioKind":"ex"},{"en":"Students who brood over minor setbacks may find it harder to maintain motivation during demanding courses.","vi":"Những học sinh cứ hoài niệm hoặc dằn vặt về những thất bại nhỏ có thể khó duy trì được động lực hơn trong các khóa học đòi hỏi cao.","audioKind":"ex2"}],"collocations":[{"en":"a brood of chicks","vi":"một bầy chim non"},{"en":"brood over a mistake","vi":"dằn vặt về một sai lầm"},{"en":"brood on the past","vi":"nghĩ ngợi về quá khứ"}],"wordFamily":["brooding (adj.)","broody (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng với nghĩa suy nghĩ âu lo, từ này thường đi với giới từ over hoặc on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_limestone', 'en-c1-15', 'limestone', '/ˈlaɪmstoʊn/', 'C1', 'đá vôi', 'n.', NULL, NULL, 'Danh từ limestone thường không đếm được; từ lime còn có nghĩa là vôi hoặc quả chanh xanh.', 'The old cottage was built from pale local limestone.', NULL, 'Ngôi nhà tranh cũ được xây bằng đá vôi màu nhạt ở địa phương.', '{"wordId":"limestone","ukIpa":"/ˈlaɪmstəʊn/","usIpa":"/ˈlaɪmstoʊn/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A rock mainly composed of calcium carbonate, often from marine remains.","vi":"đá vôi"}],"examples":[{"en":"The old cottage was built from pale local limestone.","vi":"Ngôi nhà tranh cũ được xây bằng đá vôi màu nhạt ở địa phương.","audioKind":"ex"},{"en":"Limestone formations attract tourists, but heavy visitor traffic can damage delicate cave environments over time.","vi":"Các cảnh quan đá vôi thu hút khách du lịch, nhưng lượng khách ghé thăm quá lớn có thể tàn phá môi trường hang động mỏng manh theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"limestone cliffs","vi":"vách đá vôi"},{"en":"limestone cave","vi":"hang động đá vôi"},{"en":"limestone quarry","vi":"mỏ đá vôi"},{"en":"limestone formations","vi":"địa mạo đá vôi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ limestone thường không đếm được; từ lime còn có nghĩa là vôi hoặc quả chanh xanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hemisphere', 'en-c1-15', 'hemisphere', '/ˈhemɪsfɪr/', 'C1', 'bán cầu (địa lý); bán cầu não', 'n.', 'hemispheric (adj.), hemispherical (adj.)', NULL, 'Trong địa lý, từ này chỉ một nửa của Trái Đất, và cũng có thể chỉ bán cầu não.', 'Australia lies in the southern hemisphere, far from Europe.', NULL, 'Úc nằm ở bán cầu nam, cách xa châu Âu.', '{"wordId":"hemisphere","ukIpa":"/ˈhemɪsfɪə/","usIpa":"/ˈhemɪsfɪr/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"one half of the Earth","vi":"bán cầu (địa lý)"},{"pos":"n.","en":"either of the two halves of the brain","vi":"bán cầu não"}],"examples":[{"en":"Australia lies in the southern hemisphere, far from Europe.","vi":"Úc nằm ở bán cầu nam, cách xa châu Âu.","audioKind":"ex"},{"en":"Seasonal differences between the northern and southern hemispheres influence global tourism patterns throughout the year.","vi":"Sự khác biệt về mùa giữa bán cầu bắc và bán cầu nam ảnh hưởng đến các mô hình du lịch toàn cầu quanh năm.","audioKind":"ex2"}],"collocations":[{"en":"northern hemisphere","vi":"bán cầu bắc"},{"en":"southern hemisphere","vi":"bán cầu nam"},{"en":"left hemisphere","vi":"bán cầu trái"}],"wordFamily":["hemispheric (adj.)","hemispherical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong địa lý, từ này chỉ một nửa của Trái Đất, và cũng có thể chỉ bán cầu não.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tigress', 'en-c1-15', 'tigress', '/ˈtaɪɡrəs/', 'C1', 'hổ cái; con cọp cái', 'n.', 'tiger (n.)', NULL, 'tigress chỉ riêng con cái; tiger có thể dùng chung cho loài hổ nói chung, không phân biệt đực cái.', 'The tigress rested beside her cubs in the shade.', NULL, 'Con hổ cái nằm nghỉ ngơi bên cạnh những chú con trong bóng râm.', '{"wordId":"tigress","ukIpa":"/ˈtaɪɡrəs/","usIpa":"/ˈtaɪɡrəs/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"An adult female tiger.","vi":"hổ cái; con cọp cái"}],"examples":[{"en":"The tigress rested beside her cubs in the shade.","vi":"Con hổ cái nằm nghỉ ngơi bên cạnh những chú con trong bóng râm.","audioKind":"ex"},{"en":"Protecting the habitat of a tigress and her cubs can help maintain a healthy tiger population.","vi":"Bảo vệ môi trường sống của hổ cái và các con của nó giúp duy trì một quần thể hổ khỏe mạnh.","audioKind":"ex2"}],"collocations":[{"en":"a tigress and her cubs","vi":"hổ cái và bầy con"},{"en":"a wild tigress","vi":"con hổ cái hoang dã"}],"wordFamily":["tiger (n.)"],"synonyms":[],"antonyms":[],"tipVi":"tigress chỉ riêng con cái; tiger có thể dùng chung cho loài hổ nói chung, không phân biệt đực cái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amphibian', 'en-c1-15', 'amphibian', '/æmˈfɪbiən/', 'C1', 'động vật lưỡng cư; phương tiện lội nước', 'n.', 'amphibious (adj.)', NULL, 'Dùng từ amphibian để chỉ danh từ con vật; tính từ ''lưỡng cư'' dùng amphibis.', 'We spotted a small amphibian beside the garden pond.', NULL, 'Chúng tôi phát hiện một con động vật lưỡng cư nhỏ ngay bên cạnh cái ao trong vườn.', '{"wordId":"amphibian","ukIpa":"/æmˈfɪbiən/","usIpa":"/æmˈfɪbiən/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"an animal, such as a frog, living in water and on land","vi":"động vật lưỡng cư"},{"pos":"n.","en":"a vehicle or aircraft able to operate on land and water","vi":"phương tiện lội nước"}],"examples":[{"en":"We spotted a small amphibian beside the garden pond.","vi":"Chúng tôi phát hiện một con động vật lưỡng cư nhỏ ngay bên cạnh cái ao trong vườn.","audioKind":"ex"},{"en":"Declining amphibian populations may indicate changes in water quality and wider damage to freshwater ecosystems.","vi":"Số lượng động vật lưỡng cư sụt giảm có thể là dấu hiệu cho thấy chất lượng nguồn nước thay đổi và hệ sinh thái nước ngọt đang bị tổn hại nặng nề hơn.","audioKind":"ex2"}],"collocations":[{"en":"amphibian species","vi":"loài lưỡng cư"},{"en":"amphibian populations","vi":"quần thể lưỡng cư"},{"en":"amphibian conservation","vi":"bảo tồn loài lưỡng cư"}],"wordFamily":["amphibious (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng từ amphibian để chỉ danh từ con vật; tính từ ''lưỡng cư'' dùng amphibis.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fungus', 'en-c1-15', 'fungus', '/ˈfʌŋɡəs/', 'C1', 'nấm', 'n.', 'fungal (adj.)', NULL, 'Dạng số nhiều thường là fungi; nấm không thuộc về giới thực vật.', 'A strange orange fungus was growing on the fallen tree.', NULL, 'Một loại nấm màu cam lạ đang mọc trên cây bị đổ.', '{"wordId":"fungus","ukIpa":"/ˈfʌŋɡəs/","usIpa":"/ˈfʌŋɡəs/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"an organism such as a mushroom, mould, or yeast","vi":"nấm"}],"examples":[{"en":"A strange orange fungus was growing on the fallen tree.","vi":"Một loại nấm màu cam lạ đang mọc trên cây bị đổ.","audioKind":"ex"},{"en":"Some types of fungus help maintain healthy forests by breaking down dead wood and recycling nutrients.","vi":"Một số loại nấm giúp duy trì rừng khỏe mạnh bằng cách phân hủy gỗ mục và tái chế chất dinh dưỡng.","audioKind":"ex2"}],"collocations":[{"en":"soil fungus","vi":"nấm đất"},{"en":"fungus growth","vi":"sự phát triển của nấm"},{"en":"edible fungi","vi":"nấm ăn được"}],"wordFamily":["fungal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều thường là fungi; nấm không thuộc về giới thực vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perish', 'en-c1-15', 'perish', '/ˈperɪʃ/', 'C1', 'chết, thiệt mạng, diệt vong; mục nát, lão hóa, mất đi độ bền (theo thời gian)', 'v.', 'perishable (adj.), imperishable (adj.)', 'Đồng nghĩa: die, decay · Trái nghĩa: survive', 'Thường là nội động từ; trong tiếng Anh - Anh từ này còn dùng để chỉ vật liệu như cao su bị mục, lão hóa.', 'These delicate plants will perish if left outside tonight.', NULL, 'Những chậu cây mỏng manh này sẽ chết úa nếu để ngoài trời vào tối nay.', '{"wordId":"perish","ukIpa":"/ˈperɪʃ/","usIpa":"/ˈperɪʃ/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To die or be destroyed, especially in harsh conditions.","vi":"chết, thiệt mạng, diệt vong"},{"pos":"v.","en":"To decay or lose strength and flexibility over time.","vi":"mục nát, lão hóa, mất đi độ bền (theo thời gian)"}],"examples":[{"en":"These delicate plants will perish if left outside tonight.","vi":"Những chậu cây mỏng manh này sẽ chết úa nếu để ngoài trời vào tối nay.","audioKind":"ex"},{"en":"Without effective habitat protection, many vulnerable species may perish as temperatures rise and food sources disappear.","vi":"Nếu không có biện pháp bảo vệ môi trường sống hiệu quả, nhiều loài dễ bị tổn thương có thể diệt vong khi nhiệt độ tăng lên và nguồn thức ăn cạn kiệt.","audioKind":"ex2"}],"collocations":[{"en":"perish from cold","vi":"chết rét, chết cóng"},{"en":"perish in a fire","vi":"thiệt mạng trong vụ hỏa hoạn"},{"en":"rubber perishes","vi":"cao su bị lão hóa"}],"wordFamily":["perishable (adj.)","imperishable (adj.)"],"synonyms":["die","decay"],"antonyms":["survive"],"tipVi":"Thường là nội động từ; trong tiếng Anh - Anh từ này còn dùng để chỉ vật liệu như cao su bị mục, lão hóa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tranquil', 'en-c1-15', 'tranquil', '/ˈtræŋkwɪl/', 'C1', 'thanh bình; yên ả', 'adj.', 'tranquillity (n.), tranquilly (adv.)', 'Đồng nghĩa: peaceful, calm, serene · Trái nghĩa: noisy, turbulent', 'Thường miêu tả khung cảnh hoặc mặt nước, mang tính nhấn mạnh sự an bình cao hơn từ quiet.', 'We enjoyed a tranquil morning beside the still lake.', NULL, 'Chúng tôi tận hưởng buổi sáng thanh bình bên hồ nước tĩnh lặng.', '{"wordId":"tranquil","ukIpa":"/ˈtræŋkwɪl/","usIpa":"/ˈtræŋkwɪl/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"calm and peaceful, without noise or disturbance","vi":"thanh bình; yên ả"}],"examples":[{"en":"We enjoyed a tranquil morning beside the still lake.","vi":"Chúng tôi tận hưởng buổi sáng thanh bình bên hồ nước tĩnh lặng.","audioKind":"ex"},{"en":"Urban parks offer tranquil spaces where residents can escape traffic noise and recover from daily stress.","vi":"Các công viên trong thành phố mang đến không gian yên bình để cư dân trốn khỏi tiếng ồn giao thông và hồi phục sau những căng thẳng thường nhật.","audioKind":"ex2"}],"collocations":[{"en":"a tranquil setting","vi":"khung cảnh thanh bình"},{"en":"tranquil waters","vi":"mặt nước phẳng lặng"},{"en":"a tranquil atmosphere","vi":"bầu không khí yên ả"}],"wordFamily":["tranquillity (n.)","tranquilly (adv.)"],"synonyms":["peaceful","calm","serene"],"antonyms":["noisy","turbulent"],"tipVi":"Thường miêu tả khung cảnh hoặc mặt nước, mang tính nhấn mạnh sự an bình cao hơn từ quiet.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thrive', 'en-c1-15', 'thrive', '/θraɪv/', 'C1', 'phát triển mạnh mẽ; phát đạt', 'v.', 'thriving (adj.)', 'Đồng nghĩa: flourish, prosper · Trái nghĩa: decline', 'Nội động từ; thrive on diễn tả việc tận hưởng hoặc trở nên sung sức hơn nhờ vào điều gì đó.', 'These herbs thrive on our sunny kitchen windowsill.', NULL, 'Những loại thảo mộc này phát triển rất tốt trên bệ cửa sổ đầy nắng trong bếp nhà chúng tôi.', '{"wordId":"thrive","ukIpa":"/θraɪv/","usIpa":"/θraɪv/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To grow strongly or become successful.","vi":"phát triển mạnh mẽ; phát đạt"}],"examples":[{"en":"These herbs thrive on our sunny kitchen windowsill.","vi":"Những loại thảo mộc này phát triển rất tốt trên bệ cửa sổ đầy nắng trong bếp nhà chúng tôi.","audioKind":"ex"},{"en":"Small businesses are more likely to thrive when local governments provide reliable infrastructure and accessible financial support.","vi":"Các doanh nghiệp nhỏ có nhiều khả năng phát triển mạnh khi chính quyền địa phương cung cấp cơ sở hạ tầng đáng tin cậy và hỗ trợ tài chính dễ tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"thrive in warm conditions","vi":"phát triển mạnh trong điều kiện ấm áp"},{"en":"thrive on challenges","vi":"càng hào hứng hơn khi đối mặt với thử thách"},{"en":"a thriving business","vi":"một doanh nghiệp làm ăn phát đạt"}],"wordFamily":["thriving (adj.)"],"synonyms":["flourish","prosper"],"antonyms":["decline"],"tipVi":"Nội động từ; thrive on diễn tả việc tận hưởng hoặc trở nên sung sức hơn nhờ vào điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mantle', 'en-c1-15', 'mantle', '/ˈmæntl/', 'C1', 'lớp phủ; tầng phủ (tuyết, sương,...); tầng mantin (lớp vỏ giữa vỏ Trái Đất và lõi); trách nhiệm; vai trò lớn được truyền lại', 'n.', NULL, 'Đồng nghĩa: covering, layer', 'mantle còn có nghĩa là áo choàng; kệ lò sưởi thường được viết là mantel.', 'A mantle of snow covered the garden overnight.', NULL, 'Một lớp tuyết dày phủ kín khu vườn qua một đêm.', '{"wordId":"mantle","ukIpa":"/ˈmæntl/","usIpa":"/ˈmæntl/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A layer that covers a surface or area","vi":"lớp phủ; tầng phủ (tuyết, sương,...)"},{"pos":"n.","en":"The thick layer of Earth between its crust and core","vi":"tầng mantin (lớp vỏ giữa vỏ Trái Đất và lõi)"},{"pos":"n.","en":"An important role or responsibility passed to someone","vi":"trách nhiệm; vai trò lớn được truyền lại"}],"examples":[{"en":"A mantle of snow covered the garden overnight.","vi":"Một lớp tuyết dày phủ kín khu vườn qua một đêm.","audioKind":"ex"},{"en":"Younger researchers must take on the mantle of leadership as experienced scientists retire from their positions.","vi":"Các nhà nghiên cứu trẻ tuổi phải gánh vác trách nhiệm lãnh đạo khi các nhà khoa học kỳ cựu nghỉ hưu.","audioKind":"ex2"}],"collocations":[{"en":"a mantle of snow","vi":"một lớp tuyết phủ"},{"en":"Earth''s mantle","vi":"tầng mantin của Trái Đất"},{"en":"assume the mantle of","vi":"gánh vác trách nhiệm"}],"wordFamily":[],"synonyms":["covering","layer"],"antonyms":[],"tipVi":"mantle còn có nghĩa là áo choàng; kệ lò sưởi thường được viết là mantel.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_15_1', 'en-c1-15', 'Cách dùng “scorch” (v.) — làm cháy xém; làm khô héo', 'scorch marks  ·  scorch the grass  ·  scorching heat', 'Thường chỉ hiện tượng bề mặt bị cháy xém nhẹ chứ không nhất thiết bị thiêu rụi hoàn toàn; ánh nắng mặt trời gắt cũng có thể scorch thực vật.', 'Họ từ (Word Family): scorched (adj.), scorching (adj.) | Đồng nghĩa: singe, sear', '[{"hanzi":"The hot iron scorched my favourite cotton shirt.","pinyin":"","meaning":"Chiếc bàn ủi nóng rẫy đã làm cháy xém chiếc áo sơ mi cotton ưa thích của tôi."},{"hanzi":"Prolonged heatwaves can scorch crops, reducing agricultural yields and threatening food supplies in vulnerable regions.","pinyin":"","meaning":"Các đợt nắng nóng kéo dài có thể làm khô héo mùa màng, làm giảm sản lượng nông nghiệp và đe dọa nguồn cung cấp lương thực tại các khu vực dễ bị tổn thương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_15_2', 'en-c1-15', 'Cách dùng “inlet” (n.) — vũng; vũng nhỏ; lạch', 'a sheltered inlet  ·  a narrow inlet  ·  air inlet', 'Trong địa lý có nghĩa là vũng/lạch biển; trong kỹ thuật dùng để chỉ nơi chất lưu đi vào, đối lập với outlet.', 'Trái nghĩa: outlet', '[{"hanzi":"We paddled into a quiet inlet sheltered by cliffs.","pinyin":"","meaning":"Chúng tôi chèo thuyền vào một vũng nước yên tĩnh được che chắn bởi những vách đá."},{"hanzi":"Coastal inlets provide sheltered habitats for marine species, but pollution can seriously damage these fragile ecosystems.","pinyin":"","meaning":"Các vũng ven biển cung cấp môi trường sống được che chở cho các loài sinh vật biển, nhưng ô nhiễm có thể gây tổn hại nghiêm trọng đến các hệ sinh thái mỏng manh này."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_15_3', 'en-c1-15', 'Cách dùng “innumerable” (adj.) — vô số; không thể đếm xuể', 'innumerable examples  ·  innumerable opportunities  ·  innumerable times', 'Thường đi kèm với danh từ đếm được số nhiều, mang sắc thái mạnh mẽ hơn từ "many" và có tính trang trọng hơn.', 'Họ từ (Word Family): numerous (adj.), numerable (adj.) | Đồng nghĩa: countless, numberless', '[{"hanzi":"Innumerable stars filled the sky above our quiet campsite.","pinyin":"","meaning":"Vô số vì sao bao phủ bầu trời phía trên khu cắm trại yên tĩnh của chúng tôi."},{"hanzi":"Coastal wetlands support innumerable organisms and provide essential protection against storms for nearby communities.","pinyin":"","meaning":"Các vùng đất ngập nước ven biển nuôi dưỡng vô số sinh vật và cung cấp lớp bảo vệ thiết yếu chống lại bão cho các cộng đồng gần đó."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_15_4', 'en-c1-15', 'Cách dùng “perish” (v.) — chết, thiệt mạng, diệt vong', 'perish from cold  ·  perish in a fire  ·  rubber perishes', 'Thường là nội động từ; trong tiếng Anh - Anh từ này còn dùng để chỉ vật liệu như cao su bị mục, lão hóa.', 'Họ từ (Word Family): perishable (adj.), imperishable (adj.) | Đồng nghĩa: die, decay · Trái nghĩa: survive', '[{"hanzi":"These delicate plants will perish if left outside tonight.","pinyin":"","meaning":"Những chậu cây mỏng manh này sẽ chết úa nếu để ngoài trời vào tối nay."},{"hanzi":"Without effective habitat protection, many vulnerable species may perish as temperatures rise and food sources disappear.","pinyin":"","meaning":"Nếu không có biện pháp bảo vệ môi trường sống hiệu quả, nhiều loài dễ bị tổn thương có thể diệt vong khi nhiệt độ tăng lên và nguồn thức ăn cạn kiệt."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_15_1', 'en-c1-15', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_1_1', 'ten_c1_15_1', 'droop', 'The flowers began to droop in the afternoon heat.', 'The flowers began to droop in the afternoon heat.', '/druːp/', 'Những bông hoa bắt đầu rủ xuống trong cái nắng buổi chiều.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_1_2', 'ten_c1_15_1', 'snout', 'The pig pushed its snout through the wooden fence.', 'The pig pushed its snout through the wooden fence.', '/snaʊt/', 'Con lợn thò cái mõm của nó qua hàng rào gỗ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_1_3', 'ten_c1_15_1', 'alpine', 'Tiny alpine flowers grew between rocks beside the trail.', 'Tiny alpine flowers grew between rocks beside the trail.', '/ˈælpaɪn/', 'Những bông hoa núi cao nhỏ bé mọc chen giữa các khe đá bên cạnh lối đi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_1_4', 'ten_c1_15_1', 'primate', 'The guide pointed to a primate swinging between branches.', 'The guide pointed to a primate swinging between branches.', '/ˈpraɪmeɪt/', 'Hướng dẫn viên chỉ tay về phía một con động vật linh trưởng đangu đu đưa giữa các cành cây.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_1_5', 'ten_c1_15_1', 'citrus', 'We squeezed fresh citrus juice over the salad.', 'We squeezed fresh citrus juice over the salad.', '/ˈsɪtrəs/', 'Chúng tôi vắt nước cốt chanh cam tươi lên đĩa rau trộn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_1_6', 'ten_c1_15_1', 'glimmer', 'A glimmer of candlelight escaped through the closed curtains.', 'A glimmer of candlelight escaped through the closed curtains.', '/ˈɡlɪmər/', 'Một chút ánh nến lọt qua khe cửa sổ đang kéo rèm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_1_7', 'ten_c1_15_1', 'scorch', 'The hot iron scorched my favourite cotton shirt.', 'The hot iron scorched my favourite cotton shirt.', '/skɔːrtʃ/', 'Chiếc bàn ủi nóng rẫy đã làm cháy xém chiếc áo sơ mi cotton ưa thích của tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_1_8', 'ten_c1_15_1', 'glide', 'The swan glided across the pond towards the reeds.', 'The swan glided across the pond towards the reeds.', '/ɡlaɪd/', 'Con thiên nga lướt êm đềm qua mặt hồ hướng về phía bụi lau sậy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_15_1_1', 'en-c1-15', 'ten_c1_15_1', 'listening', 'listening', 'The flowers began to droop in the afternoon heat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đi bộ về nhà qua công viên trong ánh chiều tà.","Những bông hoa bắt đầu rủ xuống trong cái nắng buổi chiều.","Hướng dẫn viên chỉ tay về phía một con động vật linh trưởng đangu đu đưa giữa các cành cây.","Ngôi nhà tranh cũ được xây bằng đá vôi màu nhạt ở địa phương."]'::jsonb, 1, 'The flowers began to droop in the afternoon heat. → Những bông hoa bắt đầu rủ xuống trong cái nắng buổi chiều.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_15_1_2', 'en-c1-15', 'ten_c1_15_1', 'listening', 'listening', 'The pig pushed its snout through the wooden fence.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con lợn thò cái mõm của nó qua hàng rào gỗ.","Những loại rau thơm này phát triển rất tốt trên bệ cửa sổ nhà bếp ấm áp, ngập tràn ánh nắng của chúng tôi.","Vịt mẹ dẫn đàn con bơi qua mặt hồ phẳng lặng.","Úc nằm ở bán cầu nam, cách xa châu Âu."]'::jsonb, 0, 'The pig pushed its snout through the wooden fence. → Con lợn thò cái mõm của nó qua hàng rào gỗ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_15_1_3', 'en-c1-15', 'ten_c1_15_1', 'listening', 'listening', 'Tiny alpine flowers grew between rocks beside the trail.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi tận hưởng buổi sáng thanh bình bên hồ nước tĩnh lặng.","Hướng dẫn viên chỉ tay về phía một con động vật linh trưởng đangu đu đưa giữa các cành cây.","Úc nằm ở bán cầu nam, cách xa châu Âu.","Những bông hoa núi cao nhỏ bé mọc chen giữa các khe đá bên cạnh lối đi."]'::jsonb, 3, 'Tiny alpine flowers grew between rocks beside the trail. → Những bông hoa núi cao nhỏ bé mọc chen giữa các khe đá bên cạnh lối đi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_15_2', 'en-c1-15', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_2_1', 'ten_c1_15_2', 'droop', 'During prolonged droughts, leaves often droop as plants lose water and struggle to maintain their structure.', 'During prolonged droughts, leaves often droop as plants lose water and struggle to maintain their structure.', '/druːp/', 'Trong thời kỳ hạn hán kéo dài, lá cây thường rủ xuống do thực vật bị mất nước và gặp khó khăn trong việc duy trì cấu trúc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_2_2', 'ten_c1_15_2', 'snout', 'A pig''s sensitive snout helps it locate food beneath the soil, supporting its natural foraging behaviour.', 'A pig''s sensitive snout helps it locate food beneath the soil, supporting its natural foraging behaviour.', '/snaʊt/', 'Cái mõm nhạy cảm của con lợn giúp nó tìm kiếm thức ăn dưới lòng đất, hỗ trợ cho tập tính kiếm ăn tự nhiên của nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_2_3', 'ten_c1_15_2', 'alpine', 'Rising temperatures threaten alpine ecosystems by reducing snow cover and forcing mountain species to move higher.', 'Rising temperatures threaten alpine ecosystems by reducing snow cover and forcing mountain species to move higher.', '/ˈælpaɪn/', 'Nhiệt độ tăng cao đang đe dọa hệ sinh thái vùng núi cao bằng cách làm giảm lớp tuyết phủ và buộc các loài sinh vật trên núi phải di chuyển lên cao hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_2_4', 'ten_c1_15_2', 'primate', 'Protecting tropical forests is essential for the survival of many primate species threatened by habitat loss.', 'Protecting tropical forests is essential for the survival of many primate species threatened by habitat loss.', '/ˈpraɪmeɪt/', 'Bảo vệ các khu rừng nhiệt đới đóng vai trò cốt yếu đối với sự sinh còn của nhiều loài linh trưởng vốn đang bị đe dọa do mất môi trường sống.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_2_5', 'ten_c1_15_2', 'citrus', 'Rising temperatures may affect citrus production by increasing water demand and exposing orchards to new pests.', 'Rising temperatures may affect citrus production by increasing water demand and exposing orchards to new pests.', '/ˈsɪtrəs/', 'Nhiệt độ tăng cao có thể ảnh hưởng đến sản lượng cây có múi bằng cách làm tăng nhu cầu nước tưới và khiến các vườn cây ăn quả đối mặt với sâu bệnh mới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_15_2_6', 'ten_c1_15_2', 'glimmer', 'Recent improvements in water quality offer a glimmer of hope for communities affected by industrial pollution.', 'Recent improvements in water quality offer a glimmer of hope for communities affected by industrial pollution.', '/ˈɡlɪmər/', 'Những cải thiện gần đây về chất lượng nước mang đến một tia hy vọng cho các cộng đồng bị ảnh hưởng bởi ô nhiễm công nghiệp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_15_2_1', 'en-c1-15', 'ten_c1_15_2', 'listening', 'listening', 'During prolonged droughts, leaves often droop as plants lose water and struggle to maintain their structure.', NULL, 'Trong câu vừa nghe, từ “droop” mang nghĩa nào sau đây?', '["học bổng nghiên cứu; quỹ hỗ trợ nghiên cứu; chức vụ nghiên cứu sinh","cúi xuống; rủ xuống","chiến tranh, chiến đấu, phương thức tác chiến","làm liệt; làm bại liệt"]'::jsonb, 1, '“droop” (/druːp/): cúi xuống; rủ xuống. Câu đầy đủ: During prolonged droughts, leaves often droop as plants lose water and struggle to maintain their structure.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_15_2_2', 'en-c1-15', 'ten_c1_15_2', 'listening', 'listening', 'A pig''s sensitive snout helps it locate food beneath the soil, supporting its natural foraging behaviour.', NULL, 'Trong câu vừa nghe, từ “snout” mang nghĩa nào sau đây?', '["tưới tiêu; cấp nước","có sinh có diệt; phải chết","mõm (động vật)","xây dựng; hoạch định"]'::jsonb, 2, '“snout” (/snaʊt/): mõm (động vật). Câu đầy đủ: A pig''s sensitive snout helps it locate food beneath the soil, supporting its natural foraging behaviour.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_15_1', 'en-c1-15', 'The flowers began to droop in the afternoon heat', 'Những bông hoa bắt đầu rủ xuống trong cái nắng buổi chiều.', 'droop /druːp/', '["afternoon","in","The","to","droop","began","the","heat","flowers"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_15_2', 'en-c1-15', 'The pig pushed its snout through the wooden fence', 'Con lợn thò cái mõm của nó qua hàng rào gỗ.', 'snout /snaʊt/', '["through","the","pushed","pig","The","its","snout","fence","wooden"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_15_3', 'en-c1-15', 'Tiny alpine flowers grew between rocks beside the trail', 'Những bông hoa núi cao nhỏ bé mọc chen giữa các khe đá bên cạnh lối đi.', 'alpine /ˈælpaɪn/', '["Tiny","alpine","trail","between","grew","rocks","the","beside","flowers"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_15_4', 'en-c1-15', 'The guide pointed to a primate swinging between branches', 'Hướng dẫn viên chỉ tay về phía một con động vật linh trưởng đangu đu đưa giữa các cành cây.', 'primate /ˈpraɪmeɪt/', '["guide","primate","pointed","between","The","to","swinging","a","branches"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_15_5', 'en-c1-15', 'We squeezed fresh citrus juice over the salad', 'Chúng tôi vắt nước cốt chanh cam tươi lên đĩa rau trộn.', 'citrus /ˈsɪtrəs/', '["salad","the","citrus","fresh","squeezed","juice","We","over"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_15_6', 'en-c1-15', 'A glimmer of candlelight escaped through the closed curtains', 'Một chút ánh nến lọt qua khe cửa sổ đang kéo rèm.', 'glimmer /ˈɡlɪmər/', '["escaped","curtains","A","candlelight","closed","glimmer","of","through","the"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_15_7', 'en-c1-15', 'The hot iron scorched my favourite cotton shirt', 'Chiếc bàn ủi nóng rẫy đã làm cháy xém chiếc áo sơ mi cotton ưa thích của tôi.', 'scorch /skɔːrtʃ/', '["favourite","hot","cotton","iron","shirt","scorched","my","The"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_15_8', 'en-c1-15', 'The swan glided across the pond towards the reeds', 'Con thiên nga lướt êm đềm qua mặt hồ hướng về phía bụi lau sậy.', 'glide /ɡlaɪd/', '["towards","glided","pond","reeds","The","across","the","the","swan"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_15_9', 'en-c1-15', 'We watched a platypus swimming quietly near the riverbank', 'Chúng tôi quan sát một con thú mỏ vịt đang bơi lặng lẽ gần bờ sông.', 'platypus /ˈplætɪpəs/', '["watched","riverbank","quietly","We","near","platypus","a","swimming","the"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_15_10', 'en-c1-15', 'We paddled into a quiet inlet sheltered by cliffs', 'Chúng tôi chèo thuyền vào một vũng nước yên tĩnh được che chắn bởi những vách đá.', 'inlet /ˈɪnlet/', '["We","by","into","paddled","inlet","quiet","cliffs","a","sheltered"]'::jsonb, NULL, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
