INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_1', 'en-c1-15', NULL, 'comprehensive_test', 'listening', 'droop', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cản trở; gây khó khăn","suy giảm; suy yếu dần","tỉ mỉ; một cách kỹ lưỡng","cúi xuống; rủ xuống"]'::jsonb, 3, 'droop (/druːp/) → cúi xuống; rủ xuống', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_2', 'en-c1-15', NULL, 'comprehensive_test', 'listening', 'The pig pushed its snout through the wooden fence.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi bộ về nhà qua công viên trong ánh chiều tà.","Những bông hoa núi cao nhỏ bé mọc chen giữa các khe đá bên cạnh lối đi.","Một loại nấm màu cam lạ đang mọc trên cây bị đổ.","Con lợn thò cái mõm của nó qua hàng rào gỗ."]'::jsonb, 3, 'The pig pushed its snout through the wooden fence. → Con lợn thò cái mõm của nó qua hàng rào gỗ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_3', 'en-c1-15', NULL, 'comprehensive_test', 'listening', 'alpine', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về vùng núi cao; thuộc dãy An-pơ","ánh sáng mờ; ánh sáng yếu ớt","ban hành lệnh cấm; tuyên bố là bất hợp pháp","bóp méo; xuyên tạc"]'::jsonb, 0, 'alpine (/ˈælpaɪn/) → thuộc về vùng núi cao; thuộc dãy An-pơ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_4', 'en-c1-15', NULL, 'comprehensive_test', 'listening', 'The guide pointed to a primate swinging between branches.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hướng dẫn viên chỉ tay về phía một con động vật linh trưởng đangu đu đưa giữa các cành cây.","Một chút ánh nến lọt qua khe cửa sổ đang kéo rèm.","Những chậu cây mỏng manh này sẽ chết úa nếu để ngoài trời vào tối nay.","Một con gà trống đỏ cất tiếng gáy vang bên cạnh chiếc cổng gỗ."]'::jsonb, 0, 'The guide pointed to a primate swinging between branches. → Hướng dẫn viên chỉ tay về phía một con động vật linh trưởng đangu đu đưa giữa các cành cây.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_5', 'en-c1-15', NULL, 'comprehensive_test', 'listening', 'citrus', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hàng hóa; vận chuyển hàng hóa","hình xoắn ốc; đường xoắn ốc","cây có múi; quả có múi","nghiệp vụ ngoại giao; hoạt động ngoại giao"]'::jsonb, 2, 'citrus (/ˈsɪtrəs/) → cây có múi; quả có múi; thuộc về cây có múi', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_6', 'en-c1-15', NULL, 'comprehensive_test', 'listening', 'A glimmer of candlelight escaped through the closed curtains.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một lớp tuyết dày phủ kín khu vườn qua một đêm.","Con thiên nga lướt êm đềm qua mặt hồ hướng về phía bụi lau sậy.","Chúng tôi vắt nước cốt chanh cam tươi lên đĩa rau trộn.","Một chút ánh nến lọt qua khe cửa sổ đang kéo rèm."]'::jsonb, 3, 'A glimmer of candlelight escaped through the closed curtains. → Một chút ánh nến lọt qua khe cửa sổ đang kéo rèm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_7', 'en-c1-15', NULL, 'comprehensive_test', 'listening', 'scorch', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["kéo dài; dây dưa; kéo dài lâu hơn dự kiến","giếng (thang máy, thông gió); đường hầm thẳng đứng","sự đuổi học; sự trục xuất; sự khai trừ","làm cháy xém; làm khô héo"]'::jsonb, 3, 'scorch (/skɔːrtʃ/) → làm cháy xém; làm khô héo', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_8', 'en-c1-15', NULL, 'comprehensive_test', 'listening', 'The swan glided across the pond towards the reeds.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một lớp tuyết dày phủ kín khu vườn qua một đêm.","Vô số vì sao bao phủ bầu trời phía trên khu cắm trại yên tĩnh của chúng tôi.","Những chậu cây mỏng manh này sẽ chết úa nếu để ngoài trời vào tối nay.","Con thiên nga lướt êm đềm qua mặt hồ hướng về phía bụi lau sậy."]'::jsonb, 3, 'The swan glided across the pond towards the reeds. → Con thiên nga lướt êm đềm qua mặt hồ hướng về phía bụi lau sậy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_9', 'en-c1-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Trees producing fruits such as oranges and lemons, or their fruits.”?', '["primate","citrus","cock","flourish"]'::jsonb, 1, 'citrus (/ˈsɪtrəs/) → cây có múi; quả có múi', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_10', 'en-c1-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A faint light, often shining unevenly”?', '["glimmer","platypus","amphibian","tigress"]'::jsonb, 0, 'glimmer (/ˈɡlɪmər/) → ánh sáng mờ; ánh sáng yếu ớt', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_11', 'en-c1-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To burn a surface slightly or damage it with heat”?', '["scorch","mantle","tigress","hound"]'::jsonb, 0, 'scorch (/skɔːrtʃ/) → làm cháy xém; làm khô héo', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_12', 'en-c1-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To move smoothly and easily, often without much noise.”?', '["snout","innumerable","glide","mantle"]'::jsonb, 2, 'glide (/ɡlaɪd/) → lướt đi; trôi êm ái; di chuyển nhẹ nhàng', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_13', 'en-c1-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An Australian egg-laying mammal with a flat bill and webbed feet.”?', '["hound","platypus","droop","innumerable"]'::jsonb, 1, 'platypus (/ˈplætɪpəs/) → thú mỏ vịt', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
