INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_18', 'en-c1-15', NULL, 'comprehensive_test', 'reading', NULL, 'During prolonged droughts, leaves often droop as plants lose water and struggle to maintain their structure.', 'Dựa vào câu trên, từ “droop” có nghĩa phù hợp nhất là gì?', '["chủ tàu; công ty sở hữu tàu thuyền","cúi xuống; rủ xuống","chung chung; không cụ thể","khét tiếng, mang tiếng xấu, nổi danh về điều tiêu cực"]'::jsonb, 1, 'droop: cúi xuống; rủ xuống. Dịch cả câu: Trong thời kỳ hạn hán kéo dài, lá cây thường rủ xuống do thực vật bị mất nước và gặp khó khăn trong việc duy trì cấu trúc.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_19', 'en-c1-15', NULL, 'comprehensive_test', 'reading', NULL, 'A pig''s sensitive snout helps it locate food beneath the soil, supporting its natural foraging behaviour.', 'Dựa vào câu trên, từ “snout” có nghĩa phù hợp nhất là gì?', '["nhen nhóm ngọn lửa hoặc bắt đầu cháy","cảm giác bị cô lập, sự xa cách (với người khác hoặc xã hội)","mõm (động vật)","bóp méo; xuyên tạc"]'::jsonb, 2, 'snout: mõm (động vật). Dịch cả câu: Cái mõm nhạy cảm của con lợn giúp nó tìm kiếm thức ăn dưới lòng đất, hỗ trợ cho tập tính kiếm ăn tự nhiên của nó.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_20', 'en-c1-15', NULL, 'comprehensive_test', 'reading', NULL, 'Rising temperatures threaten alpine ecosystems by reducing snow cover and forcing mountain species to move higher.', 'Dựa vào câu trên, từ “alpine” có nghĩa phù hợp nhất là gì?', '["ký sinh trùng; sinh vật ký sinh","thuộc về vùng núi cao; thuộc dãy An-pơ","phòng chứa thức ăn; tủ đựng thực phẩm","nhân viên đăng ký; thư ký quản lý hồ sơ"]'::jsonb, 1, 'alpine: thuộc về vùng núi cao; thuộc dãy An-pơ. Dịch cả câu: Nhiệt độ tăng cao đang đe dọa hệ sinh thái vùng núi cao bằng cách làm giảm lớp tuyết phủ và buộc các loài sinh vật trên núi phải di chuyển lên cao hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_21', 'en-c1-15', NULL, 'comprehensive_test', 'reading', NULL, 'Protecting tropical forests is essential for the survival of many primate species threatened by habitat loss.', 'Dựa vào câu trên, từ “primate” có nghĩa phù hợp nhất là gì?', '["sự khinh miệt; sự coi thường","hung dữ; tàn bạo; dữ dội","động vật linh trưởng","cố tình tránh xa; xa lánh"]'::jsonb, 2, 'primate: động vật linh trưởng. Dịch cả câu: Bảo vệ các khu rừng nhiệt đới đóng vai trò cốt yếu đối với sự sinh còn của nhiều loài linh trưởng vốn đang bị đe dọa do mất môi trường sống.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_22', 'en-c1-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thanh bình; yên ả”', '["tranquil","census","aero","devastate"]'::jsonb, 0, 'thanh bình; yên ả → tranquil (/ˈtræŋkwɪl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_23', 'en-c1-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phát triển mạnh mẽ; phát đạt”', '["thrive","slender","asylum","patriotism"]'::jsonb, 0, 'phát triển mạnh mẽ; phát đạt → thrive (/θraɪv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_15_24', 'en-c1-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lớp phủ; tầng phủ (tuyết, sương,...)”', '["indebtedness","mantle","gloom","ingenious"]'::jsonb, 1, 'lớp phủ; tầng phủ (tuyết, sương,...) → mantle (/ˈmæntl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-16', 'en', 'Bài 16: Thiên nhiên & Thời tiết (2) - CEFR C1', 'CEFR C1', 'C1 · Thiên nhiên', '25 từ vựng Tiếng Anh CEFR C1 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5016, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pounce', 'en-c1-16', 'pounce', '/paʊns/', 'C1', 'vồ lấy; chồm tới; chớp lấy cơ hội; chỉ trích ngay lập tức; cú vồ; cú chồm', 'v.', NULL, NULL, 'Thường đi với on, có thể dùng để chỉ hành động vồ mồi hoặc chớp lấy thời cơ/lỗi sai.', 'Our kitten pounced on a leaf blowing across the garden.', NULL, 'Chú mèo con của chúng tôi đã vồ lấy một chiếc lá đang bay qua khu vườn.', '{"wordId":"pounce","ukIpa":"/paʊns/","usIpa":"/paʊns/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To jump suddenly towards something to catch or attack it.","vi":"vồ lấy; chồm tới"},{"pos":"v.","en":"To seize an opportunity or criticise a mistake immediately.","vi":"chớp lấy cơ hội; chỉ trích ngay lập tức"},{"pos":"n.","en":"A sudden jump towards something to catch or attack it.","vi":"cú vồ; cú chồm"}],"examples":[{"en":"Our kitten pounced on a leaf blowing across the garden.","vi":"Chú mèo con của chúng tôi đã vồ lấy một chiếc lá đang bay qua khu vườn.","audioKind":"ex"},{"en":"News outlets often pounce on minor errors, distracting audiences from more important policy debates.","vi":"Các hãng tin thường chớp lấy những lỗi nhỏ để soi mói, làm xao lãng sự chú ý của công chúng khỏi các cuộc tranh luận chính sách quan trọng hơn.","audioKind":"ex2"}],"collocations":[{"en":"pounce on prey","vi":"vồ mồi"},{"en":"pounce on an opportunity","vi":"chớp lấy cơ hội"},{"en":"pounce on a mistake","vi":"bắt bẻ lỗi sai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường đi với on, có thể dùng để chỉ hành động vồ mồi hoặc chớp lấy thời cơ/lỗi sai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_desolate', 'en-c1-16', 'desolate', '/ˈdesələt/', 'C1', 'hoang vắng; hiu quạnh, không có dấu hiệu sự sống; cô độc; đau buồn tột cùng, cô đơn', 'adj.', 'desolation (n.)', 'Đồng nghĩa: bleak, deserted · Trái nghĩa: inhabited', 'Mô tả địa điểm thì mang nghĩa hoang vu, mô tả con người thì mang nghĩa cô đơn, đau khổ.', 'We crossed a desolate valley before reaching the village.', NULL, 'Chúng tôi đã băng qua một thung lũng hoang vu trước khi đến được ngôi làng.', '{"wordId":"desolate","ukIpa":"/ˈdesələt/","usIpa":"/ˈdesələt/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"Empty of people and lacking signs of life","vi":"hoang vắng; hiu quạnh, không có dấu hiệu sự sống"},{"pos":"adj.","en":"Feeling completely alone and deeply unhappy","vi":"cô độc; đau buồn tột cùng, cô đơn"}],"examples":[{"en":"We crossed a desolate valley before reaching the village.","vi":"Chúng tôi đã băng qua một thung lũng hoang vu trước khi đến được ngôi làng.","audioKind":"ex"},{"en":"Former industrial sites often remain desolate until public investment brings new housing and green spaces.","vi":"Các khu công nghiệp cũ thường vẫn bị bỏ hoang cho đến khi vốn đầu tư công mang lại những khu nhà ở và không gian xanh mới.","audioKind":"ex2"}],"collocations":[{"en":"a desolate landscape","vi":"cảnh quan hoang vu"},{"en":"a desolate village","vi":"ngôi làng hoang vắng"},{"en":"feel desolate","vi":"cảm thấy cô độc"}],"wordFamily":["desolation (n.)"],"synonyms":["bleak","deserted"],"antonyms":["inhabited"],"tipVi":"Mô tả địa điểm thì mang nghĩa hoang vu, mô tả con người thì mang nghĩa cô đơn, đau khổ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rodent', 'en-c1-16', 'rodent', '/ˈroʊdənt/', 'C1', 'loài gặm nhấm', 'n.', NULL, NULL, 'Chuột, sóc và hải ly đều thuộc loài gặm nhấm.', 'A small rodent was nibbling seeds beside the shed.', NULL, 'Một con thú gặm nhấm nhỏ đang gặm hạt giống cạnh nhà kho.', '{"wordId":"rodent","ukIpa":"/ˈrəʊdənt/","usIpa":"/ˈroʊdənt/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a mammal with strong front teeth that grow continuously","vi":"loài gặm nhấm"}],"examples":[{"en":"A small rodent was nibbling seeds beside the shed.","vi":"Một con thú gặm nhấm nhỏ đang gặm hạt giống cạnh nhà kho.","audioKind":"ex"},{"en":"Improved food storage can reduce rodent populations without introducing harmful chemicals into the local environment.","vi":"Việc cải thiện bảo quản thực phẩm có thể làm giảm số lượng động vật gặm nhấm mà không đưa các hóa chất độc hại vào môi trường địa phương.","audioKind":"ex2"}],"collocations":[{"en":"rodent population","vi":"quần thể động vật gặm nhấm"},{"en":"rodent control","vi":"kiểm soát loài gặm nhấm"},{"en":"rodent infestation","vi":"nạn chuột phá hoại"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chuột, sóc và hải ly đều thuộc loài gặm nhấm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_twinkle', 'en-c1-16', 'twinkle', '/ˈtwɪŋkəl/', 'C1', 'nhấp nháy; lấp lánh; ánh sáng lấp lánh; ánh sáng vui tươi trong mắt ai đó', 'v.', 'twinkling (adj.)', 'Đồng nghĩa: sparkle, glimmer', 'Khi là động từ thường không có tân ngữ, cũng có thể miêu tả đôi mắt ánh lên nét vui cười.', 'Tiny lights twinkled around the window as we ate.', NULL, 'Những ngọn đèn nhỏ lấp lánh xung quanh cửa sổ trong lúc chúng tôi dùng bữa.', '{"wordId":"twinkle","ukIpa":"/ˈtwɪŋkəl/","usIpa":"/ˈtwɪŋkəl/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To shine with small, quick changes in brightness.","vi":"nhấp nháy; lấp lánh"},{"pos":"n.","en":"A small flashing light, or a lively expression in someone''s eyes.","vi":"ánh sáng lấp lánh; ánh sáng vui tươi trong mắt ai đó"}],"examples":[{"en":"Tiny lights twinkled around the window as we ate.","vi":"Những ngọn đèn nhỏ lấp lánh xung quanh cửa sổ trong lúc chúng tôi dùng bữa.","audioKind":"ex"},{"en":"Although stars twinkle beautifully, atmospheric disturbances that cause this effect can limit the accuracy of astronomical observations.","vi":"Mặc dù các vì sao lấp lánh rất đẹp, nhưng sự xáo trộn của khí quyển gây ra hiện tượng này có thể làm giảm độ chính xác của các quan sát thiên văn.","audioKind":"ex2"}],"collocations":[{"en":"stars twinkle","vi":"các vì sao lấp lánh"},{"en":"twinkling lights","vi":"ánh đèn lấp lánh"},{"en":"a twinkle in someone''s eye","vi":"ánh mắt lấp lánh nụ cười"}],"wordFamily":["twinkling (adj.)"],"synonyms":["sparkle","glimmer"],"antonyms":[],"tipVi":"Khi là động từ thường không có tân ngữ, cũng có thể miêu tả đôi mắt ánh lên nét vui cười.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swarm', 'en-c1-16', 'swarm', '/swɔːrm/', 'C1', 'đàn (côn trùng); bầy; tụ tập đông đúc; kéo đến tấp nập', 'n.', NULL, NULL, 'Cụm "be swarming with" diễn tả nơi nào đó đông nghẹt người hoặc côn trùng.', 'A swarm of bees gathered on the apple tree.', NULL, 'Một đàn ong đã tập trung trên cây táo.', '{"wordId":"swarm","ukIpa":"/swɔːm/","usIpa":"/swɔːrm/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A large group of insects moving or gathering together.","vi":"đàn (côn trùng); bầy"},{"pos":"v.","en":"Move or gather somewhere in large numbers.","vi":"tụ tập đông đúc; kéo đến tấp nập"}],"examples":[{"en":"A swarm of bees gathered on the apple tree.","vi":"Một đàn ong đã tập trung trên cây táo.","audioKind":"ex"},{"en":"Visitors swarm into coastal towns during summer, increasing demand for public transport and waste collection services.","vi":"Du khách kéo đến nườm nượp tại các thị trấn ven biển vào mùa hè, làm gia tăng nhu cầu về giao thông công cộng và dịch vụ thu gom rác thải.","audioKind":"ex2"}],"collocations":[{"en":"a swarm of bees","vi":"một bầy ong"},{"en":"swarm into","vi":"ùa vào; kéo vào"},{"en":"swarm with tourists","vi":"đông nghịt khách du lịch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm \"be swarming with\" diễn tả nơi nào đó đông nghẹt người hoặc côn trùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toad', 'en-c1-16', 'toad', '/toʊd/', 'C1', 'con cóc', 'n.', NULL, NULL, 'toad chỉ con cóc; trong khi frog thường chỉ con ếch.', 'A small toad was hiding beneath the garden pot.', NULL, 'Một con cóc nhỏ đang ẩn nấp bên dưới chậu cây trong vườn.', '{"wordId":"toad","ukIpa":"/təʊd/","usIpa":"/toʊd/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A frog-like animal with rough skin that usually lives on land.","vi":"con cóc"}],"examples":[{"en":"A small toad was hiding beneath the garden pot.","vi":"Một con cóc nhỏ đang ẩn nấp bên dưới chậu cây trong vườn.","audioKind":"ex"},{"en":"Protecting ponds and nearby woodland helps toads survive as urban development reduces their natural habitats.","vi":"Việc bảo vệ các ao hồ và vùng rừng lân cận giúp loài cóc sinh tồn khi các dự án đô thị hóa làm thu hẹp môi trường sống tự nhiên của chúng.","audioKind":"ex2"}],"collocations":[{"en":"common toad","vi":"cóc thường"},{"en":"cane toad","vi":"cóc mía"},{"en":"toad spawn","vi":"trứng cóc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"toad chỉ con cóc; trong khi frog thường chỉ con ếch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pasture', 'en-c1-16', 'pasture', '/ˈpæstʃər/', 'C1', 'bãi cỏ chăn gia súc; đồng cỏ; thả gia súc ra đồng cỏ ăn', 'n.', NULL, 'Đồng nghĩa: grassland, grazing land', 'Pasture nhấn mạnh đất dùng để chăn thả gia súc, không phải bãi cỏ thông thường.', 'The cows wandered across the green pasture after sunrise.', NULL, 'Đàn bò đi lang thang khắp bãi cỏ xanh sau khi mặt trời mọc.', '{"wordId":"pasture","ukIpa":"/ˈpɑːstʃə/","usIpa":"/ˈpæstʃər/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"Land covered with grass where farm animals feed.","vi":"bãi cỏ chăn gia súc; đồng cỏ"},{"pos":"v.","en":"To put animals on grassland so they can feed.","vi":"thả gia súc ra đồng cỏ ăn"}],"examples":[{"en":"The cows wandered across the green pasture after sunrise.","vi":"Đàn bò đi lang thang khắp bãi cỏ xanh sau khi mặt trời mọc.","audioKind":"ex"},{"en":"Converting forests into pasture can reduce biodiversity and increase greenhouse gas emissions from land use.","vi":"Việc chuyển đổi rừng thành đất chăn nuôi gia súc có thể làm giảm đa dạng sinh học và tăng phát thải khí nhà kính từ việc sử dụng đất.","audioKind":"ex2"}],"collocations":[{"en":"rich pasture","vi":"bãi cỏ tươi tốt"},{"en":"pasture land","vi":"đất chăn thả"},{"en":"put cattle out to pasture","vi":"lùa gia súc ra đồng cỏ"}],"wordFamily":[],"synonyms":["grassland","grazing land"],"antonyms":[],"tipVi":"Pasture nhấn mạnh đất dùng để chăn thả gia súc, không phải bãi cỏ thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fodder', 'en-c1-16', 'fodder', '/ˈfɑːdər/', 'C1', 'thức ăn cho gia súc; cỏ khô; nguồn tư liệu; tài liệu tham khảo; chuyện tầm phào', 'n.', NULL, 'Đồng nghĩa: feed', 'Thường là danh từ không đếm được; fodder for còn mang nghĩa ẩn dụ chỉ nguyên liệu, tư liệu để khai thác.', 'We stored extra fodder in the barn before winter.', NULL, 'Chúng tôi đã dự trữ thêm thức ăn gia súc trong chuồng trước khi mùa đông tới.', '{"wordId":"fodder","ukIpa":"/ˈfɒdə/","usIpa":"/ˈfɑːdər/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"Food such as hay or straw given to farm animals.","vi":"thức ăn cho gia súc; cỏ khô"},{"pos":"n.","en":"Material that can be used for a particular purpose.","vi":"nguồn tư liệu; tài liệu tham khảo; chuyện tầm phào"}],"examples":[{"en":"We stored extra fodder in the barn before winter.","vi":"Chúng tôi đã dự trữ thêm thức ăn gia súc trong chuồng trước khi mùa đông tới.","audioKind":"ex"},{"en":"Celebrity lifestyles often provide fodder for media coverage, diverting public attention from more significant social issues.","vi":"Lối sống của những người nổi tiếng thường cung cấp chất liệu cho các phương tiện truyền thông đưa tin, khiến công chúng xao nhãng khỏi các vấn đề xã hội quan trọng hơn.","audioKind":"ex2"}],"collocations":[{"en":"winter fodder","vi":"thức ăn mùa đông"},{"en":"fodder crops","vi":"cây trồng làm thức ăn chăn nuôi"},{"en":"fodder for gossip","vi":"chuyện làm quà tám chuyện"}],"wordFamily":[],"synonyms":["feed"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; fodder for còn mang nghĩa ẩn dụ chỉ nguyên liệu, tư liệu để khai thác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lark', 'en-c1-16', 'lark', '/lɑːrk/', 'C1', 'chim sơn ca; chimềnmện; trò đùa vui; cuộc vui chơi', 'n.', NULL, NULL, 'for a lark ý là "để cho vui", thường dùng trong tiếng Anh-Anh.', 'We heard a lark singing above the quiet fields.', NULL, 'Chúng tôi nghe thấy tiếng chim sơn ca hót lảnh lót trên những cánh đồng yên tĩnh.', '{"wordId":"lark","ukIpa":"/lɑːk/","usIpa":"/lɑːrk/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a small bird known for singing while flying","vi":"chim sơn ca; chimềnmện"},{"pos":"n.","en":"something done for fun rather than for a serious purpose","vi":"trò đùa vui; cuộc vui chơi"}],"examples":[{"en":"We heard a lark singing above the quiet fields.","vi":"Chúng tôi nghe thấy tiếng chim sơn ca hót lảnh lót trên những cánh đồng yên tĩnh.","audioKind":"ex"},{"en":"Protecting grassland habitats benefits the lark and other birds threatened by increasingly intensive agricultural practices.","vi":"Việc bảo vệ môi trường sống đồng cỏ mang lại lợi ích cho chim sơn ca cùng các loài chim khác đang bị đe dọa bởi các hoạt động canh tác nông nghiệp ngày càng thâm canh.","audioKind":"ex2"}],"collocations":[{"en":"a lark singing","vi":"chim sơn ca hót"},{"en":"for a lark","vi":"để cho vui"},{"en":"have a lark","vi":"vui đùa thỏa thích"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"for a lark ý là \"để cho vui\", thường dùng trong tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flora', 'en-c1-16', 'flora', '/ˈflɔːrə/', 'C1', 'thực vật; hệ thực vật', 'n.', 'floral (adj.)', 'Đồng nghĩa: plant life, vegetation', 'Flora chỉ hệ thực vật, trong khi fauna chỉ hệ động vật.', 'Our guide pointed out the island''s unusual flora.', NULL, 'Hướng dẫn viên đã chỉ cho chúng tôi xem hệ thực vật độc đáo của hòn đảo.', '{"wordId":"flora","ukIpa":"/ˈflɔːrə/","usIpa":"/ˈflɔːrə/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"All the plants naturally growing in a particular area.","vi":"thực vật; hệ thực vật"}],"examples":[{"en":"Our guide pointed out the island''s unusual flora.","vi":"Hướng dẫn viên đã chỉ cho chúng tôi xem hệ thực vật độc đáo của hòn đảo.","audioKind":"ex"},{"en":"Protecting native flora helps maintain biodiversity and supports the insects that pollinate local crops.","vi":"Việc bảo vệ hệ thực vật bản địa giúp duy trì đa dạng sinh học và hỗ trợ các loài côn trùng thụ phấn cho cây trồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"native flora","vi":"thực vật bản địa"},{"en":"local flora","vi":"thực vật địa phương"},{"en":"flora and fauna","vi":"hệ động thực vật"}],"wordFamily":["floral (adj.)"],"synonyms":["plant life","vegetation"],"antonyms":[],"tipVi":"Flora chỉ hệ thực vật, trong khi fauna chỉ hệ động vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hawk', 'en-c1-16', 'hawk', '/hɔːk/', 'C1', 'diều hâu; chim ưng; phe diều hâu; phái chủ chiến; bán dạo; rao bán', 'n.', 'hawkish (adj.), hawker (n.)', NULL, 'Phe diều hâu (hawk) đối lập với phe bồ câu (dove) chủ trương hòa bình.', 'A hawk circled slowly above the open field.', NULL, 'Một con diều hâu bay lượn chậm rãi trên khoảng đất trống.', '{"wordId":"hawk","ukIpa":"/hɔːk/","usIpa":"/hɔːk/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a hunting bird with sharp claws and a curved beak","vi":"diều hâu; chim ưng"},{"pos":"n.","en":"someone who supports forceful policies, especially military action","vi":"phe diều hâu; phái chủ chiến"},{"pos":"v.","en":"to sell goods by offering them in public places","vi":"bán dạo; rao bán"}],"examples":[{"en":"A hawk circled slowly above the open field.","vi":"Một con diều hâu bay lượn chậm rãi trên khoảng đất trống.","audioKind":"ex"},{"en":"Protecting woodland habitats helps maintain hawk populations, which play an important role in controlling small mammals.","vi":"Việc bảo vệ các môi trường sống ở rừng giúp duy trì quần thể diều hâu, loài đóng vai trò quan trọng trong việc kiểm soát động vật có vú nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"watch someone like a hawk","vi":"giám sát ai đó chằm chằm"},{"en":"a foreign-policy hawk","vi":"nhà chính sách đối ngoại theo đường lối cứng rắn"},{"en":"hawk goods","vi":"bán hàng rong"}],"wordFamily":["hawkish (adj.)","hawker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Phe diều hâu (hawk) đối lập với phe bồ câu (dove) chủ trương hòa bình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mirage', 'en-c1-16', 'mirage', '/məˈrɑːʒ/', 'C1', 'ảo ảnh; hiện tượng ảo ảnh quang học; ảo tưởng; viển vông', 'n.', NULL, 'Đồng nghĩa: illusion', 'Chỉ hiện tượng ảo ảnh quang học hoặc niềm hy vọng hão huyền, không dùng để chỉ sương mù thông thường.', 'The distant pool was only a mirage in the desert.', NULL, 'Vũng nước ở đằng xa chỉ là một ảo ảnh giữa sa mạc.', '{"wordId":"mirage","ukIpa":"/ˈmɪrɑːʒ/","usIpa":"/məˈrɑːʒ/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"an optical illusion caused by light bending through unevenly heated air","vi":"ảo ảnh; hiện tượng ảo ảnh quang học"},{"pos":"n.","en":"something attractive that seems real or achievable but is not","vi":"ảo tưởng; viển vông"}],"examples":[{"en":"The distant pool was only a mirage in the desert.","vi":"Vũng nước ở đằng xa chỉ là một ảo ảnh giữa sa mạc.","audioKind":"ex"},{"en":"For many young workers, affordable home ownership remains a mirage as property prices rise faster than wages.","vi":"Đối với nhiều lao động trẻ, giấc mơ sở hữu nhà ở vừa túi tiền vẫn chỉ là một ảo ảnh khi giá nhà tăng nhanh hơn tiền lương.","audioKind":"ex2"}],"collocations":[{"en":"desert mirage","vi":"ảo ảnh sa mạc"},{"en":"a shimmering mirage","vi":"cảnh ảo ảnh lung linh"},{"en":"a mirage of prosperity","vi":"ảo ảnh thịnh vượng"}],"wordFamily":[],"synonyms":["illusion"],"antonyms":[],"tipVi":"Chỉ hiện tượng ảo ảnh quang học hoặc niềm hy vọng hão huyền, không dùng để chỉ sương mù thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carnivore', 'en-c1-16', 'carnivore', '/ˈkɑːrnɪvɔːr/', 'C1', 'động vật ăn thịt', 'n.', 'carnivorous (adj.)', 'Trái nghĩa: herbivore', 'Carnivore là danh từ; carnivorous là tính từ.', 'A tiger is a carnivore with powerful jaws.', NULL, 'Hổ là một loài động vật ăn thịt với hàm răng cực kỳ khỏe.', '{"wordId":"carnivore","ukIpa":"/ˈkɑːnɪvɔː/","usIpa":"/ˈkɑːrnɪvɔːr/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"an animal that eats other animals","vi":"động vật ăn thịt"}],"examples":[{"en":"A tiger is a carnivore with powerful jaws.","vi":"Hổ là một loài động vật ăn thịt với hàm răng cực kỳ khỏe.","audioKind":"ex"},{"en":"Protecting large carnivores can help maintain balanced ecosystems by preventing excessive growth in prey populations.","vi":"Bảo vệ các loài ăn thịt lớn có thể giúp duy trì sự cân bằng của hệ sinh thái bằng cách ngăn chặn sự bùng nổ quá mức của các loài con mồi.","audioKind":"ex2"}],"collocations":[{"en":"large carnivore","vi":"động vật ăn thịt lớn"},{"en":"marine carnivore","vi":"động vật ăn thịt biển"},{"en":"carnivore population","vi":"quần thể loài ăn thịt"}],"wordFamily":["carnivorous (adj.)"],"synonyms":[],"antonyms":["herbivore"],"tipVi":"Carnivore là danh từ; carnivorous là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_highland', 'en-c1-16', 'highland', '/ˈhaɪlənd/', 'C1', 'vùng cao, cao nguyên (vùng đất nằm cao hơn mực nước biển); thuộc vùng cao, thuộc cao nguyên', 'n.', NULL, 'Đồng nghĩa: upland · Trái nghĩa: lowland', 'Danh từ thường dùng dạng số nhiều là highlands; dạng số ít thường đóng vai trò là tính từ.', 'We explored the highlands on foot during our holiday.', NULL, 'Chúng tôi đã đi bộ khám phá các vùng cao nguyên trong kỳ nghỉ của mình.', '{"wordId":"highland","ukIpa":"/ˈhaɪlənd/","usIpa":"/ˈhaɪlənd/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"An area of land that lies high above sea level.","vi":"vùng cao, cao nguyên (vùng đất nằm cao hơn mực nước biển)"},{"pos":"adj.","en":"Relating to land high above sea level.","vi":"thuộc vùng cao, thuộc cao nguyên"}],"examples":[{"en":"We explored the highlands on foot during our holiday.","vi":"Chúng tôi đã đi bộ khám phá các vùng cao nguyên trong kỳ nghỉ của mình.","audioKind":"ex"},{"en":"Highland communities often face transport difficulties because steep terrain makes road construction expensive and challenging.","vi":"Các cộng đồng vùng cao thường gặp khó khăn về giao thông vì địa hình dốc khiến việc làm đường tốn kém và nhiều thách thức.","audioKind":"ex2"}],"collocations":[{"en":"highland region","vi":"vùng cao nguyên"},{"en":"highland communities","vi":"cộng đồng vùng cao"},{"en":"the highlands","vi":"vùng cao"}],"wordFamily":[],"synonyms":["upland"],"antonyms":["lowland"],"tipVi":"Danh từ thường dùng dạng số nhiều là highlands; dạng số ít thường đóng vai trò là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chasm', 'en-c1-16', 'chasm', '/ˈkæzəm/', 'C1', 'vực sâu; hẻm vực; khoảng cách lớn; sự chia rẽ sâu sắc', 'n.', NULL, 'Đồng nghĩa: gulf', 'Chữ ch phát âm là /k/; khi dùng theo nghĩa bóng chỉ khoảng cách lớn, thường dùng cấu trúc chasm between.', 'We crossed the deep chasm on a narrow bridge.', NULL, 'Chúng tôi băng qua vực sâu thăm thẳm trên một chiếc cầu hẹp.', '{"wordId":"chasm","ukIpa":"/ˈkæzəm/","usIpa":"/ˈkæzəm/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A deep, wide opening in rock or the ground.","vi":"vực sâu; hẻm vực"},{"pos":"n.","en":"A major difference separating people, ideas, or situations.","vi":"khoảng cách lớn; sự chia rẽ sâu sắc"}],"examples":[{"en":"We crossed the deep chasm on a narrow bridge.","vi":"Chúng tôi băng qua vực sâu thăm thẳm trên một chiếc cầu hẹp.","audioKind":"ex"},{"en":"Unequal access to digital technology has widened the chasm between wealthy and disadvantaged communities.","vi":"Sự tiếp cận không đồng đều với công nghệ số đã nới rộng khoảng cách giữa các cộng đồng giàu có và kém may mắn.","audioKind":"ex2"}],"collocations":[{"en":"a deep chasm","vi":"vực sâu thăm thẳm"},{"en":"a widening chasm","vi":"khoảng cách ngày càng nới rộng"},{"en":"bridge the chasm","vi":"thu hẹp khoảng cách lớn"}],"wordFamily":[],"synonyms":["gulf"],"antonyms":[],"tipVi":"Chữ ch phát âm là /k/; khi dùng theo nghĩa bóng chỉ khoảng cách lớn, thường dùng cấu trúc chasm between.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leafy', 'en-c1-16', 'leafy', '/ˈliːfi/', 'C1', 'rậm rạp lá; xanh tươi bóng mát; nhiều lá; thuộc dạng rau ăn lá', 'adj.', 'leaf (n.), leafless (adj.)', 'Trái nghĩa: leafless', 'Cụm leafy streets chỉ những con đường rợp bóng cây xanh, không có nghĩa là đường đầy lá rụng.', 'We ate our sandwiches beneath a large leafy tree.', NULL, 'Chúng tôi ngồi ăn bánh mì bên dưới một tán cây lớn rợp bóng lá.', '{"wordId":"leafy","ukIpa":"/ˈliːfi/","usIpa":"/ˈliːfi/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"Having many leaves or many trees with abundant leaves.","vi":"rậm rạp lá; xanh tươi bóng mát"},{"pos":"adj.","en":"Having leaves as the main edible part of a vegetable.","vi":"nhiều lá; thuộc dạng rau ăn lá"}],"examples":[{"en":"We ate our sandwiches beneath a large leafy tree.","vi":"Chúng tôi ngồi ăn bánh mì bên dưới một tán cây lớn rợp bóng lá.","audioKind":"ex"},{"en":"Leafy neighbourhoods can improve residents'' wellbeing by providing shade, reducing heat, and encouraging outdoor activity.","vi":"Những khu123 phố nhiều cây xanh có thể nâng cao sức khỏe tinh thần của cư dân bằng cách cung cấp bóng mát, giảm nhiệt độ và khuyến khích các hoạt động ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"leafy suburb","vi":"ngoại ô nhiều cây xanh"},{"en":"leafy tree","vi":"cây cối rậm rạp lá"},{"en":"leafy vegetables","vi":"các loại rau ăn lá"}],"wordFamily":["leaf (n.)","leafless (adj.)"],"synonyms":[],"antonyms":["leafless"],"tipVi":"Cụm leafy streets chỉ những con đường rợp bóng cây xanh, không có nghĩa là đường đầy lá rụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hail', 'en-c1-16', 'hail', '/heɪl/', 'C1', 'mưa đá (những hạt băng nhỏ rơi từ mây xuống); rơi xuống thành những hạt băng nhỏ (mưa đá); tán dương công khai; gọi lớn để thu hút sự chú ý', 'n.', 'hailstone (n.)', NULL, 'Khi nói trời mưa đá, dùng cấu trúc it hails; cụm hail A as B có nghĩa là ca ngợi A là B.', 'Hail rattled against the windows during the storm.', NULL, 'Mưa đá đập lộp bộp vào cửa sổ trong suốt trận giông bão.', '{"wordId":"hail","ukIpa":"/heɪl/","usIpa":"/heɪl/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"small balls of ice that fall from clouds","vi":"mưa đá (những hạt băng nhỏ rơi từ mây xuống)"},{"pos":"v.","en":"to fall from the sky as small balls of ice","vi":"rơi xuống thành những hạt băng nhỏ (mưa đá)"},{"pos":"v.","en":"to praise someone publicly or call to attract attention","vi":"tán dương công khai; gọi lớn để thu hút sự chú ý"}],"examples":[{"en":"Hail rattled against the windows during the storm.","vi":"Mưa đá đập lộp bộp vào cửa sổ trong suốt trận giông bão.","audioKind":"ex"},{"en":"Scientists hailed the new irrigation system as a breakthrough that could help farmers conserve water during droughts.","vi":"Các nhà khoa học ca ngợi hệ thống tưới tiêu mới là một bước đột phá có thể giúp nông dân tiết kiệm nước trong thời kỳ hạn hán.","audioKind":"ex2"}],"collocations":[{"en":"heavy hail","vi":"mưa đá dữ dội"},{"en":"hail a taxi","vi":"vẫy gọi xe taxi"},{"en":"be hailed as a breakthrough","vi":"được ca ngợi như một bước đột phá"}],"wordFamily":["hailstone (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói trời mưa đá, dùng cấu trúc it hails; cụm hail A as B có nghĩa là ca ngợi A là B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dew', 'en-c1-16', 'dew', '/duː/', 'C1', 'sương; giọt sương', 'n.', 'dewy (adj.)', NULL, 'dew thường là danh từ không đếm được; nếu muốn nói một giọt sương, dùng cụm a drop of dew.', 'Morning dew soaked my shoes as I crossed the lawn.', NULL, 'Sương sớm đã làm ướt sũng đôi giày của tôi khi tôi đi qua bãi cỏ.', '{"wordId":"dew","ukIpa":"/djuː/","usIpa":"/duː/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"Small water drops forming on cool surfaces, especially overnight","vi":"sương; giọt sương"}],"examples":[{"en":"Morning dew soaked my shoes as I crossed the lawn.","vi":"Sương sớm đã làm ướt sũng đôi giày của tôi khi tôi đi qua bãi cỏ.","audioKind":"ex"},{"en":"In some dry environments, plants collect dew on their leaves to supplement the limited water available in soil.","vi":"Ở một số môi trường khô hạn, thực vật đọng sương trên lá để bổ sung lượng nước khan hiếm trong đất.","audioKind":"ex2"}],"collocations":[{"en":"morning dew","vi":"sương sớm"},{"en":"heavy dew","vi":"sương dày"},{"en":"covered in dew","vi":"phủ đầy sương"}],"wordFamily":["dewy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"dew thường là danh từ không đếm được; nếu muốn nói một giọt sương, dùng cụm a drop of dew.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grove', 'en-c1-16', 'grove', '/ɡroʊv/', 'C1', 'vườn cây nhỏ; một khu rừng nhỏ thường được trồng tập trung', 'n.', NULL, 'Đồng nghĩa: copse', 'grove chỉ một khoảnh rừng hoặc vườn nhỏ, thường dùng cho cây ô-liu, cam quýt.', 'We spread our picnic blanket in a shady grove.', NULL, 'Chúng tôi trải thảm dã ngoại dưới một lùm cây râm mát.', '{"wordId":"grove","ukIpa":"/ɡrəʊv/","usIpa":"/ɡroʊv/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a small group of trees, often planted together","vi":"vườn cây nhỏ; một khu rừng nhỏ thường được trồng tập trung"}],"examples":[{"en":"We spread our picnic blanket in a shady grove.","vi":"Chúng tôi trải thảm dã ngoại dưới một lùm cây râm mát.","audioKind":"ex"},{"en":"Traditional olive groves support rural livelihoods while providing valuable habitats for birds and other wildlife.","vi":"Các vườn ô-liu truyền thống vừa duy trì sinh kế cho người dân nông thôn vừa tạo môi trường sống có giá trị cho các loài chim và động vật hoang dã khác.","audioKind":"ex2"}],"collocations":[{"en":"olive grove","vi":"rừng ô-liu"},{"en":"orange grove","vi":"vườn cam"},{"en":"a grove of trees","vi":"một lùm cây"}],"wordFamily":[],"synonyms":["copse"],"antonyms":[],"tipVi":"grove chỉ một khoảnh rừng hoặc vườn nhỏ, thường dùng cho cây ô-liu, cam quýt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wither', 'en-c1-16', 'wither', '/ˈwɪðər/', 'C1', 'héo; làm héo úa; suy yếu dần; lụi tàn; phai nhạt', 'v.', 'withered (adj.), withering (adj.)', 'Đồng nghĩa: shrivel, fade · Trái nghĩa: flourish, thrive', 'Có thể dùng cho cả thực vật bị héo hoặc sự nghiệp, phong trào bị suy thoái, thường đi kèm với từ away.', 'The flowers withered after a week without water.', NULL, 'Những bông hoa đã héo úa sau một tuần không có nước.', '{"wordId":"wither","ukIpa":"/ˈwɪðə/","usIpa":"/ˈwɪðər/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To become dry and weak, or cause plants to do so.","vi":"héo; làm héo úa"},{"pos":"v.","en":"To gradually lose strength, importance, or effectiveness.","vi":"suy yếu dần; lụi tàn; phai nhạt"}],"examples":[{"en":"The flowers withered after a week without water.","vi":"Những bông hoa đã héo úa sau một tuần không có nước.","audioKind":"ex"},{"en":"Without sustained investment, local industries may wither, leaving young people with few employment opportunities.","vi":"Nếu thiếu sự đầu tư bền vững, các ngành công nghiệp địa phương có thể lụi tàn, khiến giới trẻ có rất ít cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"wither away","vi":"lụi tàn dần"},{"en":"wither in the heat","vi":"héo úa trong cái nóng"},{"en":"wither and die","vi":"héo khô và chết đi"}],"wordFamily":["withered (adj.)","withering (adj.)"],"synonyms":["shrivel","fade"],"antonyms":["flourish","thrive"],"tipVi":"Có thể dùng cho cả thực vật bị héo hoặc sự nghiệp, phong trào bị suy thoái, thường đi kèm với từ away.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cape', 'en-c1-16', 'cape', '/keɪp/', 'C1', 'mũi đất; hải vạn; áo choàng không tay', 'n.', NULL, 'Đồng nghĩa: headland', 'Cape có thể chỉ địa hình mũi đất nhô ra biển hoặc chiếc áo choàng không tay.', 'We walked around the cape before the tide rose.', NULL, 'Chúng tôi đi dạo vòng quanh mũi đất trước khi thủy triều lên.', '{"wordId":"cape","ukIpa":"/keɪp/","usIpa":"/keɪp/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a piece of land extending into the sea","vi":"mũi đất; hải vạn"},{"pos":"n.","en":"a sleeveless outer garment hanging loosely from the shoulders","vi":"áo choàng không tay"}],"examples":[{"en":"We walked around the cape before the tide rose.","vi":"Chúng tôi đi dạo vòng quanh mũi đất trước khi thủy triều lên.","audioKind":"ex"},{"en":"The construction of a lighthouse on the cape improved safety for ships approaching the harbour.","vi":"Việc xây dựng ngọn hải đăng ở mũi đất đã giúp tăng cường độ an toàn cho các tàu thuyền khi tiến vào cảng.","audioKind":"ex2"}],"collocations":[{"en":"a rocky cape","vi":"một mũi đá gồ ghề"},{"en":"round the cape","vi":"vòng qua mũi đất"},{"en":"a woollen cape","vi":"một chiếc áo choàng len"}],"wordFamily":[],"synonyms":["headland"],"antonyms":[],"tipVi":"Cape có thể chỉ địa hình mũi đất nhô ra biển hoặc chiếc áo choàng không tay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tentacle', 'en-c1-16', 'tentacle', '/ˈtentəkl/', 'C1', 'cái xúc tu; râu (động vật)', 'n.', NULL, NULL, 'Xúc tu của bạch tuộc, sứa dùng tentacle; râu của côn trùng dùng antenna.', 'The octopus wrapped a tentacle around a small shell.', NULL, 'Con bạch tuộc quấn một chiếc xúc tu quanh chiếc vỏ sò nhỏ.', '{"wordId":"tentacle","ukIpa":"/ˈtentəkl/","usIpa":"/ˈtentəkl/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a long flexible animal part used for touching or grasping","vi":"cái xúc tu; râu (động vật)"}],"examples":[{"en":"The octopus wrapped a tentacle around a small shell.","vi":"Con bạch tuộc quấn một chiếc xúc tu quanh chiếc vỏ sò nhỏ.","audioKind":"ex"},{"en":"Each tentacle helps the octopus explore its surroundings and capture food in complex marine habitats.","vi":"Mỗi chiếc xúc tu giúp con bạch tuộc khám phá môi trường xung quanh và bắt mồi trong các sinh cảnh biển phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"a long tentacle","vi":"xúc tu dài"},{"en":"octopus tentacles","vi":"xúc tu bạch tuộc"},{"en":"extend a tentacle","vi":"vươn xúc tu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Xúc tu của bạch tuộc, sứa dùng tentacle; râu của côn trùng dùng antenna.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oasis', 'en-c1-16', 'oasis', '/oʊˈeɪsɪs/', 'C1', 'ốc đảo; chốn bình yên, chốn thư thái', 'n.', NULL, NULL, 'Danh từ số nhiều là oases; cũng có thể dùng theo nghĩa bóng chỉ chốn bình yên giữa chốn ồn ào.', 'After hours of walking, we reached a small oasis.', NULL, 'Sau nhiều giờ đi bộ, chúng tôi đã đến được một ốc đảo nhỏ.', '{"wordId":"oasis","ukIpa":"/əʊˈeɪsɪs/","usIpa":"/oʊˈeɪsɪs/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A place in a desert where water and plants are found.","vi":"ốc đảo"},{"pos":"n.","en":"A peaceful, pleasant place surrounded by something difficult or unpleasant.","vi":"chốn bình yên, chốn thư thái"}],"examples":[{"en":"After hours of walking, we reached a small oasis.","vi":"Sau nhiều giờ đi bộ, chúng tôi đã đến được một ốc đảo nhỏ.","audioKind":"ex"},{"en":"Public gardens provide an oasis of calm for residents living in densely populated urban areas.","vi":"Các khu vườn công cộng mang đến một chốn bình yên cho cư dân sống ở những khu vực đô thị đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"desert oasis","vi":"ốc đảo sa mạc"},{"en":"an oasis of calm","vi":"chốn bình yên thư thái"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ số nhiều là oases; cũng có thể dùng theo nghĩa bóng chỉ chốn bình yên giữa chốn ồn ào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_captive', 'en-c1-16', 'captive', '/ˈkæptɪv/', 'C1', 'bị giam cầm; bị nhốt; tù nhân; người bị bắt giữ; bị ép buộc ở lại; không thể lựa chọn khác', 'adj.', 'captivity (n.), capture (v.)', 'Đồng nghĩa: imprisoned, confined · Trái nghĩa: free', 'Cụm captive audience chỉ những thính giả/khán giả không thể tự ý rời đi, chứ không có nghĩa là người bị mê hoặc.', 'The captive bird spread its wings inside the cage.', NULL, 'Con chim bị nhốt vẫy đôi cánh của nó bên trong chiếc lồng.', '{"wordId":"captive","ukIpa":"/ˈkæptɪv/","usIpa":"/ˈkæptɪv/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"kept somewhere and not allowed to leave","vi":"bị giam cầm; bị nhốt"},{"pos":"n.","en":"a person held prisoner","vi":"tù nhân; người bị bắt giữ"},{"pos":"adj.","en":"unable to leave or choose an alternative","vi":"bị ép buộc ở lại; không thể lựa chọn khác"}],"examples":[{"en":"The captive bird spread its wings inside the cage.","vi":"Con chim bị nhốt vẫy đôi cánh của nó bên trong chiếc lồng.","audioKind":"ex"},{"en":"Breeding captive animals can support conservation, but protecting their natural habitats remains essential for long-term survival.","vi":"Việc nhân giống động vật nuôi nhốt có thể hỗ trợ công tác bảo tồn, nhưng việc bảo vệ môi trường sống tự nhiên của chúng vẫn là điều cốt yếu để đảm bảo sự sinh tồn lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"hold someone captive","vi":"giam giữ ai đó"},{"en":"captive animals","vi":"động vật nuôi nhốt"},{"en":"a captive audience","vi":"khán giả không thể bỏ về"},{"en":"captive breeding","vi":"nhân giống trong nuôi nhốt"}],"wordFamily":["captivity (n.)","capture (v.)"],"synonyms":["imprisoned","confined"],"antonyms":["free"],"tipVi":"Cụm captive audience chỉ những thính giả/khán giả không thể tự ý rời đi, chứ không có nghĩa là người bị mê hoặc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cavern', 'en-c1-16', 'cavern', '/ˈkævərn/', 'C1', 'hang động lớn; động lớn tự nhiên', 'n.', 'cavernous (adj.)', 'Đồng nghĩa: cave', 'cavern là hang động lớn; tavern là quán rượu.', 'Our torches revealed a deep pool inside the cavern.', NULL, 'Đèn pin của chúng tôi đã rọi thấy một vũng nước sâu bên trong hang động lớn.', '{"wordId":"cavern","ukIpa":"/ˈkævən/","usIpa":"/ˈkævərn/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A large natural underground cave.","vi":"hang động lớn; động lớn tự nhiên"}],"examples":[{"en":"Our torches revealed a deep pool inside the cavern.","vi":"Đèn pin của chúng tôi đã rọi thấy một vũng nước sâu bên trong hang động lớn.","audioKind":"ex"},{"en":"Tourism within a limestone cavern must be carefully managed to protect fragile formations and underground habitats.","vi":"Hoạt động du lịch bên trong một hang động đá vôi phải được quản lý cẩn thận để bảo vệ các cấu trúc thạch nhũ mỏng manh và môi trường sống dưới lòng đất.","audioKind":"ex2"}],"collocations":[{"en":"a limestone cavern","vi":"hang động đá vôi"},{"en":"an underground cavern","vi":"hang động lớn dưới lòng đất"},{"en":"explore a cavern","vi":"khám phá hang động"}],"wordFamily":["cavernous (adj.)"],"synonyms":["cave"],"antonyms":[],"tipVi":"cavern là hang động lớn; tavern là quán rượu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_16_1', 'en-c1-16', 'Cách dùng “captive” (adj.) — bị giam cầm; bị nhốt', 'hold someone captive  ·  captive animals  ·  a captive audience', 'Cụm captive audience chỉ những thính giả/khán giả không thể tự ý rời đi, chứ không có nghĩa là người bị mê hoặc.', 'Họ từ (Word Family): captivity (n.), capture (v.) | Đồng nghĩa: imprisoned, confined · Trái nghĩa: free', '[{"hanzi":"The captive bird spread its wings inside the cage.","pinyin":"","meaning":"Con chim bị nhốt vẫy đôi cánh của nó bên trong chiếc lồng."},{"hanzi":"Breeding captive animals can support conservation, but protecting their natural habitats remains essential for long-term survival.","pinyin":"","meaning":"Việc nhân giống động vật nuôi nhốt có thể hỗ trợ công tác bảo tồn, nhưng việc bảo vệ môi trường sống tự nhiên của chúng vẫn là điều cốt yếu để đảm bảo sự sinh tồn lâu dài."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_16_2', 'en-c1-16', 'Cách dùng “fodder” (n.) — thức ăn cho gia súc; cỏ khô', 'winter fodder  ·  fodder crops  ·  fodder for gossip', 'Thường là danh từ không đếm được; fodder for còn mang nghĩa ẩn dụ chỉ nguyên liệu, tư liệu để khai thác.', 'Đồng nghĩa: feed', '[{"hanzi":"We stored extra fodder in the barn before winter.","pinyin":"","meaning":"Chúng tôi đã dự trữ thêm thức ăn gia súc trong chuồng trước khi mùa đông tới."},{"hanzi":"Celebrity lifestyles often provide fodder for media coverage, diverting public attention from more significant social issues.","pinyin":"","meaning":"Lối sống của những người nổi tiếng thường cung cấp chất liệu cho các phương tiện truyền thông đưa tin, khiến công chúng xao nhãng khỏi các vấn đề xã hội quan trọng hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_16_3', 'en-c1-16', 'Cách dùng “chasm” (n.) — vực sâu; hẻm vực', 'a deep chasm  ·  a widening chasm  ·  bridge the chasm', 'Chữ ch phát âm là /k/; khi dùng theo nghĩa bóng chỉ khoảng cách lớn, thường dùng cấu trúc chasm between.', 'Đồng nghĩa: gulf', '[{"hanzi":"We crossed the deep chasm on a narrow bridge.","pinyin":"","meaning":"Chúng tôi băng qua vực sâu thăm thẳm trên một chiếc cầu hẹp."},{"hanzi":"Unequal access to digital technology has widened the chasm between wealthy and disadvantaged communities.","pinyin":"","meaning":"Sự tiếp cận không đồng đều với công nghệ số đã nới rộng khoảng cách giữa các cộng đồng giàu có và kém may mắn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_16_4', 'en-c1-16', 'Cách dùng “wither” (v.) — héo; làm héo úa', 'wither away  ·  wither in the heat  ·  wither and die', 'Có thể dùng cho cả thực vật bị héo hoặc sự nghiệp, phong trào bị suy thoái, thường đi kèm với từ away.', 'Họ từ (Word Family): withered (adj.), withering (adj.) | Đồng nghĩa: shrivel, fade · Trái nghĩa: flourish, thrive', '[{"hanzi":"The flowers withered after a week without water.","pinyin":"","meaning":"Những bông hoa đã héo úa sau một tuần không có nước."},{"hanzi":"Without sustained investment, local industries may wither, leaving young people with few employment opportunities.","pinyin":"","meaning":"Nếu thiếu sự đầu tư bền vững, các ngành công nghiệp địa phương có thể lụi tàn, khiến giới trẻ có rất ít cơ hội việc làm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_16_1', 'en-c1-16', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
