INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_1_2', 'ten_c1_16_1', 'desolate', 'We crossed a desolate valley before reaching the village.', 'We crossed a desolate valley before reaching the village.', '/ˈdesələt/', 'Chúng tôi đã băng qua một thung lũng hoang vu trước khi đến được ngôi làng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_1_3', 'ten_c1_16_1', 'rodent', 'A small rodent was nibbling seeds beside the shed.', 'A small rodent was nibbling seeds beside the shed.', '/ˈroʊdənt/', 'Một con thú gặm nhấm nhỏ đang gặm hạt giống cạnh nhà kho.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_1_4', 'ten_c1_16_1', 'twinkle', 'Tiny lights twinkled around the window as we ate.', 'Tiny lights twinkled around the window as we ate.', '/ˈtwɪŋkəl/', 'Những ngọn đèn nhỏ lấp lánh xung quanh cửa sổ trong lúc chúng tôi dùng bữa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_1_5', 'ten_c1_16_1', 'swarm', 'A swarm of bees gathered on the apple tree.', 'A swarm of bees gathered on the apple tree.', '/swɔːrm/', 'Một đàn ong đã tập trung trên cây táo.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_1_6', 'ten_c1_16_1', 'toad', 'A small toad was hiding beneath the garden pot.', 'A small toad was hiding beneath the garden pot.', '/toʊd/', 'Một con cóc nhỏ đang ẩn nấp bên dưới chậu cây trong vườn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_1_7', 'ten_c1_16_1', 'pasture', 'The cows wandered across the green pasture after sunrise.', 'The cows wandered across the green pasture after sunrise.', '/ˈpæstʃər/', 'Đàn bò đi lang thang khắp bãi cỏ xanh sau khi mặt trời mọc.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_1_8', 'ten_c1_16_1', 'fodder', 'We stored extra fodder in the barn before winter.', 'We stored extra fodder in the barn before winter.', '/ˈfɑːdər/', 'Chúng tôi đã dự trữ thêm thức ăn gia súc trong chuồng trước khi mùa đông tới.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_16_1_1', 'en-c1-16', 'ten_c1_16_1', 'listening', 'listening', 'Our kitten pounced on a leaf blowing across the garden.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những bông hoa đã héo úa sau một tuần không có nước.","Vũng nước ở đằng xa chỉ là một ảo ảnh giữa sa mạc.","Con bạch tuộc quấn một chiếc xúc tu quanh chiếc vỏ sò nhỏ.","Chú mèo con của chúng tôi đã vồ lấy một chiếc lá đang bay qua khu vườn."]'::jsonb, 3, 'Our kitten pounced on a leaf blowing across the garden. → Chú mèo con của chúng tôi đã vồ lấy một chiếc lá đang bay qua khu vườn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_16_1_2', 'en-c1-16', 'ten_c1_16_1', 'listening', 'listening', 'We crossed a desolate valley before reaching the village.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con chim bị nhốt vẫy đôi cánh của nó bên trong chiếc lồng.","Chúng tôi đã băng qua một thung lũng hoang vu trước khi đến được ngôi làng.","Một con cóc nhỏ đang ẩn nấp bên dưới chậu cây trong vườn.","Chúng tôi băng qua vực sâu thăm thẳm trên một chiếc cầu hẹp."]'::jsonb, 1, 'We crossed a desolate valley before reaching the village. → Chúng tôi đã băng qua một thung lũng hoang vu trước khi đến được ngôi làng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_16_1_3', 'en-c1-16', 'ten_c1_16_1', 'listening', 'listening', 'A small rodent was nibbling seeds beside the shed.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã dự trữ thêm thức ăn gia súc trong chuồng trước khi mùa đông tới.","Chúng tôi đã băng qua một thung lũng hoang vu trước khi đến được ngôi làng.","Một đàn ong đã tập trung trên cây táo.","Một con thú gặm nhấm nhỏ đang gặm hạt giống cạnh nhà kho."]'::jsonb, 3, 'A small rodent was nibbling seeds beside the shed. → Một con thú gặm nhấm nhỏ đang gặm hạt giống cạnh nhà kho.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_16_2', 'en-c1-16', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_2_1', 'ten_c1_16_2', 'pounce', 'News outlets often pounce on minor errors, distracting audiences from more important policy debates.', 'News outlets often pounce on minor errors, distracting audiences from more important policy debates.', '/paʊns/', 'Các hãng tin thường chớp lấy những lỗi nhỏ để soi mói, làm xao lãng sự chú ý của công chúng khỏi các cuộc tranh luận chính sách quan trọng hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_2_2', 'ten_c1_16_2', 'desolate', 'Former industrial sites often remain desolate until public investment brings new housing and green spaces.', 'Former industrial sites often remain desolate until public investment brings new housing and green spaces.', '/ˈdesələt/', 'Các khu công nghiệp cũ thường vẫn bị bỏ hoang cho đến khi vốn đầu tư công mang lại những khu nhà ở và không gian xanh mới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_2_3', 'ten_c1_16_2', 'rodent', 'Improved food storage can reduce rodent populations without introducing harmful chemicals into the local environment.', 'Improved food storage can reduce rodent populations without introducing harmful chemicals into the local environment.', '/ˈroʊdənt/', 'Việc cải thiện bảo quản thực phẩm có thể làm giảm số lượng động vật gặm nhấm mà không đưa các hóa chất độc hại vào môi trường địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_2_4', 'ten_c1_16_2', 'twinkle', 'Although stars twinkle beautifully, atmospheric disturbances that cause this effect can limit the accuracy of astronomical observations.', 'Although stars twinkle beautifully, atmospheric disturbances that cause this effect can limit the accuracy of astronomical observations.', '/ˈtwɪŋkəl/', 'Mặc dù các vì sao lấp lánh rất đẹp, nhưng sự xáo trộn của khí quyển gây ra hiện tượng này có thể làm giảm độ chính xác của các quan sát thiên văn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_2_5', 'ten_c1_16_2', 'swarm', 'Visitors swarm into coastal towns during summer, increasing demand for public transport and waste collection services.', 'Visitors swarm into coastal towns during summer, increasing demand for public transport and waste collection services.', '/swɔːrm/', 'Du khách kéo đến nườm nượp tại các thị trấn ven biển vào mùa hè, làm gia tăng nhu cầu về giao thông công cộng và dịch vụ thu gom rác thải.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_16_2_6', 'ten_c1_16_2', 'toad', 'Protecting ponds and nearby woodland helps toads survive as urban development reduces their natural habitats.', 'Protecting ponds and nearby woodland helps toads survive as urban development reduces their natural habitats.', '/toʊd/', 'Việc bảo vệ các ao hồ và vùng rừng lân cận giúp loài cóc sinh tồn khi các dự án đô thị hóa làm thu hẹp môi trường sống tự nhiên của chúng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_16_2_1', 'en-c1-16', 'ten_c1_16_2', 'listening', 'listening', 'News outlets often pounce on minor errors, distracting audiences from more important policy debates.', NULL, 'Trong câu vừa nghe, từ “pounce” mang nghĩa nào sau đây?', '["nhiều đá; lắm sỏi","vồ lấy; chồm tới","dây cương ngựa","xa hoa, hào phóng; thịnh soạn, đắt đỏ"]'::jsonb, 1, '“pounce” (/paʊns/): vồ lấy; chồm tới. Câu đầy đủ: News outlets often pounce on minor errors, distracting audiences from more important policy debates.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_16_2_2', 'en-c1-16', 'ten_c1_16_2', 'listening', 'listening', 'Former industrial sites often remain desolate until public investment brings new housing and green spaces.', NULL, 'Trong câu vừa nghe, từ “desolate” mang nghĩa nào sau đây?', '["hoang vắng; hiu quạnh, không có dấu hiệu sự sống","hoài nghi; không dễ tin","quyền kinh doanh nhượng quyền; cửa hàng nhượng quyền","cơn địa chấn nhẹ; sự rung lắc"]'::jsonb, 0, '“desolate” (/ˈdesələt/): hoang vắng; hiu quạnh, không có dấu hiệu sự sống. Câu đầy đủ: Former industrial sites often remain desolate until public investment brings new housing and green spaces.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
