INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_2', 'en-c1-16', NULL, 'comprehensive_test', 'listening', 'We crossed a desolate valley before reaching the village.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sương sớm đã làm ướt sũng đôi giày của tôi khi tôi đi qua bãi cỏ.","Chúng tôi đã băng qua một thung lũng hoang vu trước khi đến được ngôi làng.","Một con thú gặm nhấm nhỏ đang gặm hạt giống cạnh nhà kho.","Chúng tôi ngồi ăn bánh mì bên dưới một tán cây lớn rợp bóng lá."]'::jsonb, 1, 'We crossed a desolate valley before reaching the village. → Chúng tôi đã băng qua một thung lũng hoang vu trước khi đến được ngôi làng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
