INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_4', 'en-c1-16', NULL, 'comprehensive_test', 'listening', 'Tiny lights twinkled around the window as we ate.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ngồi ăn bánh mì bên dưới một tán cây lớn rợp bóng lá.","Vũng nước ở đằng xa chỉ là một ảo ảnh giữa sa mạc.","Những ngọn đèn nhỏ lấp lánh xung quanh cửa sổ trong lúc chúng tôi dùng bữa.","Chúng tôi đã dự trữ thêm thức ăn gia súc trong chuồng trước khi mùa đông tới."]'::jsonb, 2, 'Tiny lights twinkled around the window as we ate. → Những ngọn đèn nhỏ lấp lánh xung quanh cửa sổ trong lúc chúng tôi dùng bữa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_5', 'en-c1-16', NULL, 'comprehensive_test', 'listening', 'swarm', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mũi đất; hải vạn","đi vòng qua cái gì đó hoặc né tránh một bước thông thường","đàn (côn trùng); bầy","gợi lên; gợi nhớ; đánh thức"]'::jsonb, 2, 'swarm (/swɔːrm/) → đàn (côn trùng); bầy; tụ tập đông đúc; kéo đến tấp nập', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_6', 'en-c1-16', NULL, 'comprehensive_test', 'listening', 'A small toad was hiding beneath the garden pot.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con chim bị nhốt vẫy đôi cánh của nó bên trong chiếc lồng.","Chúng tôi đã dự trữ thêm thức ăn gia súc trong chuồng trước khi mùa đông tới.","Đèn pin của chúng tôi đã rọi thấy một vũng nước sâu bên trong hang động lớn.","Một con cóc nhỏ đang ẩn nấp bên dưới chậu cây trong vườn."]'::jsonb, 3, 'A small toad was hiding beneath the garden pot. → Một con cóc nhỏ đang ẩn nấp bên dưới chậu cây trong vườn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_7', 'en-c1-16', NULL, 'comprehensive_test', 'listening', 'pasture', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giảm bớt; làm suy yếu; thu nhỏ","bãi cỏ chăn gia súc; đồng cỏ","sự xa hoa; sự phung phí; tính vung tay quá trán","tiết lộ; vạch trần; công khai"]'::jsonb, 1, 'pasture (/ˈpæstʃər/) → bãi cỏ chăn gia súc; đồng cỏ; thả gia súc ra đồng cỏ ăn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_8', 'en-c1-16', NULL, 'comprehensive_test', 'listening', 'We stored extra fodder in the barn before winter.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một con diều hâu bay lượn chậm rãi trên khoảng đất trống.","Chúng tôi đã đi bộ khám phá các vùng cao nguyên trong kỳ nghỉ của mình.","Chúng tôi đã dự trữ thêm thức ăn gia súc trong chuồng trước khi mùa đông tới.","Hổ là một loài động vật ăn thịt với hàm răng cực kỳ khỏe."]'::jsonb, 2, 'We stored extra fodder in the barn before winter. → Chúng tôi đã dự trữ thêm thức ăn gia súc trong chuồng trước khi mùa đông tới.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_9', 'en-c1-16', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A large group of insects moving or gathering together.”?', '["carnivore","swarm","highland","oasis"]'::jsonb, 1, 'swarm (/swɔːrm/) → đàn (côn trùng); bầy', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_10', 'en-c1-16', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A frog-like animal with rough skin that usually lives on land.”?', '["toad","tentacle","carnivore","fodder"]'::jsonb, 0, 'toad (/toʊd/) → con cóc', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_11', 'en-c1-16', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Land covered with grass where farm animals feed.”?', '["pasture","fodder","toad","oasis"]'::jsonb, 0, 'pasture (/ˈpæstʃər/) → bãi cỏ chăn gia súc; đồng cỏ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_12', 'en-c1-16', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Food such as hay or straw given to farm animals.”?', '["leafy","pasture","fodder","desolate"]'::jsonb, 2, 'fodder (/ˈfɑːdər/) → thức ăn cho gia súc; cỏ khô', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_13', 'en-c1-16', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a small bird known for singing while flying”?', '["twinkle","lark","wither","swarm"]'::jsonb, 1, 'lark (/lɑːrk/) → chim sơn ca; chimềnmện', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
