INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_18', 'en-c1-16', NULL, 'comprehensive_test', 'reading', NULL, 'News outlets often pounce on minor errors, distracting audiences from more important policy debates.', 'Dựa vào câu trên, từ “pounce” có nghĩa phù hợp nhất là gì?', '["nhang; trầm hương; hương","màu đỏ tươi; màu đỏ chói","nằm hoặc ngồi duỗi dài chân tay","vồ lấy; chồm tới"]'::jsonb, 3, 'pounce: vồ lấy; chồm tới; chớp lấy cơ hội; chỉ trích ngay lập tức; cú vồ; cú chồm. Dịch cả câu: Các hãng tin thường chớp lấy những lỗi nhỏ để soi mói, làm xao lãng sự chú ý của công chúng khỏi các cuộc tranh luận chính sách quan trọng hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_19', 'en-c1-16', NULL, 'comprehensive_test', 'reading', NULL, 'Former industrial sites often remain desolate until public investment brings new housing and green spaces.', 'Dựa vào câu trên, từ “desolate” có nghĩa phù hợp nhất là gì?', '["lò luyện; lò công nghiệp","mạch máu nhỏ; ống mao dẫn","hoang vắng; hiu quạnh, không có dấu hiệu sự sống","sự hồi phục; sự hồi sinh; sự thịnh hành trở lại"]'::jsonb, 2, 'desolate: hoang vắng; hiu quạnh, không có dấu hiệu sự sống; cô độc; đau buồn tột cùng, cô đơn. Dịch cả câu: Các khu công nghiệp cũ thường vẫn bị bỏ hoang cho đến khi vốn đầu tư công mang lại những khu nhà ở và không gian xanh mới.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_20', 'en-c1-16', NULL, 'comprehensive_test', 'reading', NULL, 'Improved food storage can reduce rodent populations without introducing harmful chemicals into the local environment.', 'Dựa vào câu trên, từ “rodent” có nghĩa phù hợp nhất là gì?', '["tính nhút nhát; sự thiếu tự tin","loài gặm nhấm","nguồn gốc từ; từ nguyên","sự lưu vong, sự bị đày ải khỏi quê hương, thường vì lý do chính trị"]'::jsonb, 1, 'rodent: loài gặm nhấm. Dịch cả câu: Việc cải thiện bảo quản thực phẩm có thể làm giảm số lượng động vật gặm nhấm mà không đưa các hóa chất độc hại vào môi trường địa phương.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_21', 'en-c1-16', NULL, 'comprehensive_test', 'reading', NULL, 'Although stars twinkle beautifully, atmospheric disturbances that cause this effect can limit the accuracy of astronomical observations.', 'Dựa vào câu trên, từ “twinkle” có nghĩa phù hợp nhất là gì?', '["ức chế; cản trở","nhấp nháy; lấp lánh","tầm vóc; quy mô lớn; tầm quan trọng","giảng đạo; thuyết giáo"]'::jsonb, 1, 'twinkle: nhấp nháy; lấp lánh; ánh sáng lấp lánh; ánh sáng vui tươi trong mắt ai đó. Dịch cả câu: Mặc dù các vì sao lấp lánh rất đẹp, nhưng sự xáo trộn của khí quyển gây ra hiện tượng này có thể làm giảm độ chính xác của các quan sát thiên văn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_22', 'en-c1-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ốc đảo”', '["recipient","genocide","oasis","reticent"]'::jsonb, 2, 'ốc đảo → oasis (/oʊˈeɪsɪs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
