INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_16_24', 'en-c1-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hang động lớn; động lớn tự nhiên”', '["terminate","macroeconomics","subsidize","cavern"]'::jsonb, 3, 'hang động lớn; động lớn tự nhiên → cavern (/ˈkævərn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-17', 'en', 'Bài 17: Thiên nhiên & Thời tiết (3) - CEFR C1', 'CEFR C1', 'C1 · Thiên nhiên', '25 từ vựng Tiếng Anh CEFR C1 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5017, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ascent', 'en-c1-17', 'ascent', '/əˈsent/', 'C1', 'sự leo trèo, sự đi lên phía trên; sự thăng tiến, sự vươn lên vị trí hoặc cấp bậc cao hơn; con đường dốc, đoạn đường đi lên', 'n.', 'ascend (v.), ascending (adj.)', 'Đồng nghĩa: climb, rise · Trái nghĩa: descent', 'ascent chỉ sự đi lên; từ đồng âm assent mang nghĩa là sự đồng ý.', 'We began our ascent just as the sun rose.', NULL, 'Chúng tôi bắt đầu cuộc hành trình leo núi ngay khi mặt trời vừa ló rạng.', '{"wordId":"ascent","ukIpa":"/əˈsent/","usIpa":"/əˈsent/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"the act of climbing or moving upwards","vi":"sự leo trèo, sự đi lên phía trên"},{"pos":"n.","en":"a rise to a higher position, rank, or level","vi":"sự thăng tiến, sự vươn lên vị trí hoặc cấp bậc cao hơn"},{"pos":"n.","en":"a path or slope that leads upwards","vi":"con đường dốc, đoạn đường đi lên"}],"examples":[{"en":"We began our ascent just as the sun rose.","vi":"Chúng tôi bắt đầu cuộc hành trình leo núi ngay khi mặt trời vừa ló rạng.","audioKind":"ex"},{"en":"The rapid ascent of renewable energy reflects both technological progress and stronger public support for environmental protection.","vi":"Sự trỗi dậy nhanh chóng của năng lượng tái tạo vừa phản ánh tiến bộ công nghệ vừa cho thấy sự hậu thuẫn mạnh mẽ hơn từ công chúng đối với công tác bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"a steep ascent","vi":"đường dốc đứng"},{"en":"make an ascent","vi":"thực hiện cuộc leo núi"},{"en":"ascent to power","vi":"con đường bước lên đỉnh cao quyền lực"}],"wordFamily":["ascend (v.)","ascending (adj.)"],"synonyms":["climb","rise"],"antonyms":["descent"],"tipVi":"ascent chỉ sự đi lên; từ đồng âm assent mang nghĩa là sự đồng ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_estuary', 'en-c1-17', 'estuary', '/ˈestʃueri/', 'C1', 'cửa sông; cửa sông đổ ra biển', 'n.', 'estuarine (adj.)', 'Đồng nghĩa: river mouth', 'Nhấn mạnh vùng cửa sông chịu ảnh hưởng của thủy triều, không đồng nghĩa với delta (vùng đồng bằng châu thổ).', 'We watched birds feeding beside the estuary at sunset.', NULL, 'Chúng tôi ngắm nhìn những chú chim kiếm ăn bên cửa sông vào lúc hoàng hôn.', '{"wordId":"estuary","ukIpa":"/ˈestʃuəri/","usIpa":"/ˈestʃueri/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"The wide tidal mouth of a river meeting the sea.","vi":"cửa sông; cửa sông đổ ra biển"}],"examples":[{"en":"We watched birds feeding beside the estuary at sunset.","vi":"Chúng tôi ngắm nhìn những chú chim kiếm ăn bên cửa sông vào lúc hoàng hôn.","audioKind":"ex"},{"en":"Protecting an estuary preserves important feeding grounds for migratory birds and supports the livelihoods of local fishing communities.","vi":"Việc bảo vệ cửa sông giúp duy trì các bãi kiếm ăn quan trọng cho chim di cư và hỗ trợ sinh kế của cộng đồng ngư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a river estuary","vi":"một con sông đổ ra cửa sông"},{"en":"estuary wildlife","vi":"động vật hoang dã vùng cửa sông"},{"en":"a tidal estuary","vi":"cửa sông chịu ảnh hưởng thủy triều"}],"wordFamily":["estuarine (adj.)"],"synonyms":["river mouth"],"antonyms":[],"tipVi":"Nhấn mạnh vùng cửa sông chịu ảnh hưởng của thủy triều, không đồng nghĩa với delta (vùng đồng bằng châu thổ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_offspring', 'en-c1-17', 'offspring', '/ˈɔːfsprɪŋ/', 'C1', 'con cái; hậu quả; con non', 'n.', NULL, 'Đồng nghĩa: progeny, young', 'Danh từ có dạng số ít và số nhiều giống nhau; khi nói về con cái của con người thì mang tính trang trọng hơn từ children.', 'The mother duck led her offspring safely across the path.', NULL, 'Vịt mẹ dẫn bầy con qua đường an toàn.', '{"wordId":"offspring","ukIpa":"/ˈɒfsprɪŋ/","usIpa":"/ˈɔːfsprɪŋ/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"The children or young of a person, animal, or plant.","vi":"con cái; hậu quả; con non"}],"examples":[{"en":"The mother duck led her offspring safely across the path.","vi":"Vịt mẹ dẫn bầy con qua đường an toàn.","audioKind":"ex"},{"en":"Many species invest considerable energy in protecting their offspring, which increases the young animals'' chances of survival.","vi":"Nhiều loài dành nhiều năng lượng để bảo vệ con non, qua đó làm tăng cơ hội sống sót của chúng.","audioKind":"ex2"}],"collocations":[{"en":"produce offspring","vi":"sinh sản; nhân giống"},{"en":"protect their offspring","vi":"bảo vệ con non"},{"en":"healthy offspring","vi":"hậu khỏe mạnh"}],"wordFamily":[],"synonyms":["progeny","young"],"antonyms":[],"tipVi":"Danh từ có dạng số ít và số nhiều giống nhau; khi nói về con cái của con người thì mang tính trang trọng hơn từ children.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swirl', 'en-c1-17', 'swirl', '/swɜːrl/', 'C1', 'cuốn; xoáy tròn; làm xoáy; vũng xoáy; hình xoắn ốc', 'v.', 'swirling (adj.), swirly (adj.)', 'Đồng nghĩa: whirl, spin', 'Có thể dùng làm động từ tha động hoặc bất tha động, nhấn mạnh chuyển động xoay tròn theo dòng chảy.', 'Dry leaves swirled around my feet in the wind.', NULL, 'Những chiếc lá khô bay xoòng xoọc quanh chân tôi trong gió.', '{"wordId":"swirl","ukIpa":"/swɜːl/","usIpa":"/swɜːrl/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To move, or make something move, in flowing circles.","vi":"cuốn; xoáy tròn; làm xoáy"},{"pos":"n.","en":"A circular movement or a shape that curves around itself.","vi":"vũng xoáy; hình xoắn ốc"}],"examples":[{"en":"Dry leaves swirled around my feet in the wind.","vi":"Những chiếc lá khô bay xoòng xoọc quanh chân tôi trong gió.","audioKind":"ex"},{"en":"Dust can swirl through urban streets during construction, reducing air quality and causing discomfort for nearby residents.","vi":"Bụi có thể cuốn mù mịt qua các con phố đô thị trong quá trình thi công, làm giảm chất lượng không khí và gây khó chịu cho cư dân lân cận.","audioKind":"ex2"}],"collocations":[{"en":"swirl around","vi":"xoáy quanh"},{"en":"swirl a liquid","vi":"khuấy đảo chất lỏng"},{"en":"a swirl of smoke","vi":"một làn khói xoáy"}],"wordFamily":["swirling (adj.)","swirly (adj.)"],"synonyms":["whirl","spin"],"antonyms":[],"tipVi":"Có thể dùng làm động từ tha động hoặc bất tha động, nhấn mạnh chuyển động xoay tròn theo dòng chảy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_panther', 'en-c1-17', 'panther', '/ˈpænθɚ/', 'C1', 'con báo đen; sư tử núi', 'n.', NULL, NULL, 'Báo đen thường là con báo hoa mai hoặc báo đốm có bộ lông đen, chứ không phải là một loài sinh học độc lập.', 'The black panther rested quietly on a thick branch.', NULL, 'Con báo đen đang nằm nghỉ ngơi yên tĩnh trên một cành cây lớn.', '{"wordId":"panther","ukIpa":"/ˈpænθə/","usIpa":"/ˈpænθɚ/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A leopard or jaguar with a black coat.","vi":"con báo đen"},{"pos":"n.","en":"A cougar, especially in North American usage.","vi":"sư tử núi"}],"examples":[{"en":"The black panther rested quietly on a thick branch.","vi":"Con báo đen đang nằm nghỉ ngơi yên tĩnh trên một cành cây lớn.","audioKind":"ex"},{"en":"Protecting forest corridors allows animals such as the panther to move safely between fragmented habitats.","vi":"Việc bảo vệ các hành lang rừng giúp các loài động vật như báo đen di chuyển an toàn giữa các sinh cảnh bị chia cắt.","audioKind":"ex2"}],"collocations":[{"en":"black panther","vi":"báo đen"},{"en":"Florida panther","vi":"báo sư tử Florida"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Báo đen thường là con báo hoa mai hoặc báo đốm có bộ lông đen, chứ không phải là một loài sinh học độc lập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enclosure', 'en-c1-17', 'enclosure', '/ɪnˈkloʊʒər/', 'C1', 'vùng rào chắn; khu vực có rào bao quanh; tài liệu đính kèm (trong thư); việc rào đất; sự quây đất', 'n.', 'enclose (v.), enclosed (adj.)', NULL, 'Tài liệu đính kèm thư tín dùng enclosure; còn tệp đính kèm email dùng attachment.', 'The goats rested in their enclosure beside the barn.', NULL, 'Đàn dê nghỉ ngơi trong bãi rào chắn ngay cạnh chuồng.', '{"wordId":"enclosure","ukIpa":"/ɪnˈkləʊʒə/","usIpa":"/ɪnˈkloʊʒər/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"An area surrounded by a fence, wall, or other barrier.","vi":"vùng rào chắn; khu vực có rào bao quanh"},{"pos":"n.","en":"Something placed inside an envelope together with a letter.","vi":"tài liệu đính kèm (trong thư)"},{"pos":"n.","en":"The act of surrounding land with a boundary.","vi":"việc rào đất; sự quây đất"}],"examples":[{"en":"The goats rested in their enclosure beside the barn.","vi":"Đàn dê nghỉ ngơi trong bãi rào chắn ngay cạnh chuồng.","audioKind":"ex"},{"en":"Wildlife parks should provide each enclosure with enough space for animals to display natural behaviour.","vi":"Các công viên động vật hoang dã nên cung cấp cho mỗi khu vực nuôi nhốt đủ không gian để các loài động vật thể hiện tập tính tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"an animal enclosure","vi":"chuồng động vật"},{"en":"a secure enclosure","vi":"khu vực rào chắn kiên cố"},{"en":"the enclosure of land","vi":"việc rào đất công cộng"}],"wordFamily":["enclose (v.)","enclosed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tài liệu đính kèm thư tín dùng enclosure; còn tệp đính kèm email dùng attachment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carp', 'en-c1-17', 'carp', '/kɑːrp/', 'C1', 'cá chép; bới móc; phàn nàn vặt; bắt bẻ', 'n.', 'carping (adj.)', NULL, 'Dạng số nhiều của tên loài cá này thường giữ nguyên là carp; khi là động từ mang nghĩa phàn nàn, nó thường đi với giới từ at.', 'We watched a large carp swimming beneath the bridge.', NULL, 'Chúng tôi ngắm nhìn một con cá chép lớn bơi lội dưới gầm cầu.', '{"wordId":"carp","ukIpa":"/kɑːp/","usIpa":"/kɑːrp/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A freshwater fish with large scales, often kept in ponds.","vi":"cá chép"},{"pos":"v.","en":"To complain repeatedly about small or unimportant faults.","vi":"bới móc; phàn nàn vặt; bắt bẻ"}],"examples":[{"en":"We watched a large carp swimming beneath the bridge.","vi":"Chúng tôi ngắm nhìn một con cá chép lớn bơi lội dưới gầm cầu.","audioKind":"ex"},{"en":"Introducing carp into new habitats can disturb aquatic ecosystems by increasing sediment and reducing water clarity.","vi":"Việc thả cá chép vào các môi trường sống mới có thể làm xáo trộn hệ sinh thái dưới nước do làm tăng lượng trầm tích và làm giảm độ trong của nước.","audioKind":"ex2"}],"collocations":[{"en":"common carp","vi":"cá chép thường"},{"en":"carp pond","vi":"ao nuôi cá chép"},{"en":"carp at minor faults","vi":"bắt bẻ những lỗi nhỏ"}],"wordFamily":["carping (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều của tên loài cá này thường giữ nguyên là carp; khi là động từ mang nghĩa phàn nàn, nó thường đi với giới từ at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drench', 'en-c1-17', 'drench', '/drentʃ/', 'C1', 'làm ướt sũng; làm đẫm nước', 'v.', 'drenched (adj.), drenching (n.)', 'Đồng nghĩa: soak, saturate · Trái nghĩa: dry', 'Nhấn mạnh trạng thái ướt hoàn toàn; thường dùng ở thể bị động be drenched.', 'A sudden downpour drenched us on the way home.', NULL, 'Cơn mưa rào bất chợt đã làm chúng tôi ướt sũng trên đường về nhà.', '{"wordId":"drench","ukIpa":"/drentʃ/","usIpa":"/drentʃ/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To make someone or something completely wet","vi":"làm ướt sũng; làm đẫm nước"}],"examples":[{"en":"A sudden downpour drenched us on the way home.","vi":"Cơn mưa rào bất chợt đã làm chúng tôi ướt sũng trên đường về nhà.","audioKind":"ex"},{"en":"Intense storms can drench farmland within minutes, increasing surface runoff and carrying valuable topsoil into nearby rivers.","vi":"Những trận bão dữ dội có thể làm ngập sũng đất nông nghiệp trong vài phút, làm tăng dòng chảy bề mặt và cuốn trôi lớp đất mặt quý giá xuống các con sông gần đó.","audioKind":"ex2"}],"collocations":[{"en":"get drenched","vi":"bị ướt sũng"},{"en":"drenched in sweat","vi":"ướt đẫm mồ hôi"},{"en":"drench someone with water","vi":"dội nước làm ướt ai"}],"wordFamily":["drenched (adj.)","drenching (n.)"],"synonyms":["soak","saturate"],"antonyms":["dry"],"tipVi":"Nhấn mạnh trạng thái ướt hoàn toàn; thường dùng ở thể bị động be drenched.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fir', 'en-c1-17', 'fir', '/fɝː/', 'C1', 'cây thông (lạnh); gỗ thông', 'n.', NULL, NULL, 'fir là cây linh sam; fur mới là lông thú, hai từ này phát âm giống nhau.', 'A tall fir shaded the path behind our cottage.', NULL, 'Một cây linh sam cao lớn che bóng mát cho lối đi phía sau ngôi nhà tranh của chúng tôi.', '{"wordId":"fir","ukIpa":"/fɜː/","usIpa":"/fɝː/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"An evergreen tree with needle-shaped leaves, or its wood.","vi":"cây thông (lạnh); gỗ thông"}],"examples":[{"en":"A tall fir shaded the path behind our cottage.","vi":"Một cây linh sam cao lớn che bóng mát cho lối đi phía sau ngôi nhà tranh của chúng tôi.","audioKind":"ex"},{"en":"Fir forests provide habitats for wildlife and help protect mountain slopes from erosion during heavy rainfall.","vi":"Rừng linh sam cung cấp môi trường sống cho động vật hoang dã và giúp bảo vệ sườn núi khỏi xói mòn trong những trận mưa lớn.","audioKind":"ex2"}],"collocations":[{"en":"a fir tree","vi":"một cây linh sam"},{"en":"a fir forest","vi":"rừng linh sam"},{"en":"fir needles","vi":"lá kim linh sam"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"fir là cây linh sam; fur mới là lông thú, hai từ này phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stony', 'en-c1-17', 'stony', '/ˈstoʊni/', 'C1', 'nhiều đá; lắm sỏi; lạnh lùng; vô cảm', 'adj.', 'stone (n.), stonily (adv.)', 'Đồng nghĩa: rocky, expressionless', '''Stony silence'' diễn tả sự im lặng lạnh lùng hoặc khó chịu, chứ không phải sự yên tĩnh thông thường.', 'We followed a stony path down to the beach.', NULL, 'Chúng tôi đi theo con đường mòn đầy đá để xuống bãi biển.', '{"wordId":"stony","ukIpa":"/ˈstəʊni/","usIpa":"/ˈstoʊni/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"covered with or containing many stones","vi":"nhiều đá; lắm sỏi"},{"pos":"adj.","en":"showing no warmth, sympathy, or emotion","vi":"lạnh lùng; vô cảm"}],"examples":[{"en":"We followed a stony path down to the beach.","vi":"Chúng tôi đi theo con đường mòn đầy đá để xuống bãi biển.","audioKind":"ex"},{"en":"Farmers working on stony ground often face higher costs when preparing land for cultivation.","vi":"Những người nông dân canh tác trên đất nhiều đá thường phải chịu chi phí cao hơn khi làm đất chuẩn bị gieo trồng.","audioKind":"ex2"}],"collocations":[{"en":"stony ground","vi":"đất nhiều đá"},{"en":"a stony path","vi":"con đường đầy đá sỏi"},{"en":"stony silence","vi":"sự im lặng lạnh lùng"},{"en":"a stony expression","vi":"vẻ mặt lạnh lùng"}],"wordFamily":["stone (n.)","stonily (adv.)"],"synonyms":["rocky","expressionless"],"antonyms":[],"tipVi":"''Stony silence'' diễn tả sự im lặng lạnh lùng hoặc khó chịu, chứ không phải sự yên tĩnh thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infest', 'en-c1-17', 'infest', '/ɪnˈfest/', 'C1', 'hoành hành; xâm chiếm phá hoại', 'v.', 'infestation (n.), infested (adj.)', 'Đồng nghĩa: overrun', 'Thường dùng be infested with, chủ ngữ là nơi bị sâu bọ tấn công.', 'Tiny insects have infested the flour in our cupboard.', NULL, 'Những con côn trùng nhỏ đã xuất hiện đầy trong bịch bột mì ở tủ bếp nhà chúng tôi.', '{"wordId":"infest","ukIpa":"/ɪnˈfest/","usIpa":"/ɪnˈfest/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To live in a place in large, harmful or unwanted groups.","vi":"hoành hành; xâm chiếm phá hoại"}],"examples":[{"en":"Tiny insects have infested the flour in our cupboard.","vi":"Những con côn trùng nhỏ đã xuất hiện đầy trong bịch bột mì ở tủ bếp nhà chúng tôi.","audioKind":"ex"},{"en":"Rats can infest poorly maintained housing, creating serious health risks for residents in densely populated areas.","vi":"Chuột có thể hoành hành trong các khu nhà ở kém chất lượng, gây ra rủi ro sức khỏe nghiêm trọng cho cư dân ở các khu vực đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"be infested with rats","vi":"bị chuột hoành hành"},{"en":"infest crops","vi":"phá hoại mùa màng"},{"en":"insect-infested buildings","vi":"các tòa nhà bị sâu bọ tàn phá"}],"wordFamily":["infestation (n.)","infested (adj.)"],"synonyms":["overrun"],"antonyms":[],"tipVi":"Thường dùng be infested with, chủ ngữ là nơi bị sâu bọ tấn công.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dormant', 'en-c1-17', 'dormant', '/ˈdɔːrmənt/', 'C1', 'ngủ đông; tạm ngưng hoạt động; tiềm ẩn', 'adj.', 'dormancy (n.)', 'Đồng nghĩa: inactive, latent · Trái nghĩa: active', 'Chỉ trạng thái tạm không hoạt động nhưng có thể phục hồi; núi lửa ngủ đông không có nghĩa là núi lửa đã chết.', 'These plants stay dormant until the weather becomes warmer.', NULL, 'Những loài thực vật này giữ trạng thái ngủ đông cho đến khi thời tiết ấm lên.', '{"wordId":"dormant","ukIpa":"/ˈdɔːmənt/","usIpa":"/ˈdɔːrmənt/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"temporarily inactive but able to become active again","vi":"ngủ đông; tạm ngưng hoạt động; tiềm ẩn"}],"examples":[{"en":"These plants stay dormant until the weather becomes warmer.","vi":"Những loài thực vật này giữ trạng thái ngủ đông cho đến khi thời tiết ấm lên.","audioKind":"ex"},{"en":"Although the volcano has remained dormant for centuries, scientists continue to monitor it for signs of renewed activity.","vi":"Mặc dù ngọn núi lửa đã ngủ đông trong nhiều thế kỷ, các nhà khoa học vẫn tiếp tục theo dõi nó để tìm dấu hiệu hoạt động trở lại.","audioKind":"ex2"}],"collocations":[{"en":"dormant volcano","vi":"núi lửa ngủ đông"},{"en":"lie dormant","vi":"ở trạng thái ngủ đông"},{"en":"dormant seeds","vi":"hạt giống ngủ đông"},{"en":"dormant account","vi":"tài khoản lâu ngày không giao dịch"}],"wordFamily":["dormancy (n.)"],"synonyms":["inactive","latent"],"antonyms":["active"],"tipVi":"Chỉ trạng thái tạm không hoạt động nhưng có thể phục hồi; núi lửa ngủ đông không có nghĩa là núi lửa đã chết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_breeding', 'en-c1-17', 'breeding', '/ˈbriːdɪŋ/', 'C1', 'sự sinh sản; sự nhân giống; giáo dục; phép tắc ứng xử', 'n.', 'breed (v.), breeder (n.)', NULL, 'breeding nhấn mạnh việc sinh sản hoặc nhân giống nhân tạo; breed đóng vai trò danh từ chỉ giống loài.', 'We avoid disturbing the birds during the breeding season.', NULL, 'Chúng tôi tránh làm phiền các loài chim trong mùa sinh sản.', '{"wordId":"breeding","ukIpa":"/ˈbriːdɪŋ/","usIpa":"/ˈbriːdɪŋ/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"Animal reproduction, or controlled reproduction of animals and plants.","vi":"sự sinh sản; sự nhân giống"},{"pos":"n.","en":"Polite behaviour learned through someone''s upbringing.","vi":"giáo dục; phép tắc ứng xử"}],"examples":[{"en":"We avoid disturbing the birds during the breeding season.","vi":"Chúng tôi tránh làm phiền các loài chim trong mùa sinh sản.","audioKind":"ex"},{"en":"Selective breeding can improve crop yields, but it may also reduce genetic diversity within agricultural systems.","vi":"Chọn giống có thể nâng cao năng suất cây trồng, nhưng nó cũng có thể làm giảm sự đa dạng di truyền trong các hệ thống nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"breeding season","vi":"mùa sinh sản"},{"en":"selective breeding","vi":"chọn giống"},{"en":"captive breeding","vi":"nhân giống nuôi nhốt"},{"en":"breeding programme","vi":"chương trình nhân giống"}],"wordFamily":["breed (v.)","breeder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"breeding nhấn mạnh việc sinh sản hoặc nhân giống nhân tạo; breed đóng vai trò danh từ chỉ giống loài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hoof', 'en-c1-17', 'hoof', '/huːf/', 'C1', 'móng (của ngựa hoặc động vật tương tự)', 'n.', 'hooved (adj.)', NULL, 'Cả hai dạng số nhiều hooves và hoofs đều đúng, trong đó hooves phổ biến hơn.', 'The farmer gently lifted the horse''s hoof for inspection.', NULL, 'Người nông dân nhẹ nhàng nhấc móng con ngựa lên để kiểm tra.', '{"wordId":"hoof","ukIpa":"/huːf/","usIpa":"/huːf/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"the hard covering of a horse''s or similar animal''s foot","vi":"móng (của ngựa hoặc động vật tương tự)"}],"examples":[{"en":"The farmer gently lifted the horse''s hoof for inspection.","vi":"Người nông dân nhẹ nhàng nhấc móng con ngựa lên để kiểm tra.","audioKind":"ex"},{"en":"Regular hoof care is essential for preventing pain and maintaining the health of working horses.","vi":"Việc chăm sóc móng định kỳ là điều cần thiết để ngăn ngừa đau đớn và duy trì sức khỏe cho ngựa làm việc.","audioKind":"ex2"}],"collocations":[{"en":"hoof care","vi":"chăm sóc móng"},{"en":"hoof print","vi":"dấu vết móng"},{"en":"a horse''s hoof","vi":"móng ngựa"}],"wordFamily":["hooved (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cả hai dạng số nhiều hooves và hoofs đều đúng, trong đó hooves phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whisker', 'en-c1-17', 'whisker', '/ˈwɪskər/', 'C1', 'râu (của động vật); râu quai nón; râu cằm', 'n.', 'whiskered (adj.)', NULL, 'Thường dùng ở số nhiều whiskers; by a whisker diễn tả chỉ chênh lệch hoặc suýt soát trong gang tấc.', 'A tiny drop of milk hung from one whisker.', NULL, 'Một giọt sữa nhỏ đọng lại trên một sợi râu.', '{"wordId":"whisker","ukIpa":"/ˈwɪskə/","usIpa":"/ˈwɪskər/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a long, stiff hair growing near an animal''s mouth","vi":"râu (của động vật)"},{"pos":"n.","en":"a hair growing on a man''s cheeks or chin","vi":"râu quai nón; râu cằm"}],"examples":[{"en":"A tiny drop of milk hung from one whisker.","vi":"Một giọt sữa nhỏ đọng lại trên một sợi râu.","audioKind":"ex"},{"en":"Each whisker provides sensory information that helps some mammals navigate confined spaces and detect changes in their surroundings.","vi":"Mỗi sợi râu cung cấp thông tin cảm giác giúp một số loài động vật có vú di chuyển trong không gian chật hẹp và phát hiện sự thay đổi trong môi trường xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"a cat''s whiskers","vi":"râu mèo"},{"en":"twitch its whiskers","vi":"cử động râu"},{"en":"by a whisker","vi":"trong gang tấc; suýt nữa thì"}],"wordFamily":["whiskered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng ở số nhiều whiskers; by a whisker diễn tả chỉ chênh lệch hoặc suýt soát trong gang tấc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ripple', 'en-c1-17', 'ripple', '/ˈrɪpəl/', 'C1', 'gợn sóng; sóng lăn tăn; làm lăn tăn; hiệu ứng lan tỏa; phản ứng dây chuyền', 'n.', NULL, NULL, 'Ripple nhỏ hơn wave; ripple effect chỉ hiệu ứng dây chuyền.', 'A falling leaf sent ripples across the pond.', NULL, 'Một chiếc lá rơi tạo ra những gợn sóng lăn tăn trên mặt ao.', '{"wordId":"ripple","ukIpa":"/ˈrɪpəl/","usIpa":"/ˈrɪpəl/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A small wave on the surface of water.","vi":"gợn sóng; sóng lăn tăn"},{"pos":"v.","en":"To move in small waves or make something do so.","vi":"gợn sóng; làm lăn tăn"},{"pos":"n.","en":"A reaction or effect that spreads through people or places.","vi":"hiệu ứng lan tỏa; phản ứng dây chuyền"}],"examples":[{"en":"A falling leaf sent ripples across the pond.","vi":"Một chiếc lá rơi tạo ra những gợn sóng lăn tăn trên mặt ao.","audioKind":"ex"},{"en":"The closure of a major factory can have a ripple effect throughout the local economy.","vi":"Việc đóng cửa một nhà máy lớn có thể gây ra hiệu ứng lan tỏa trong toàn bộ nền kinh tế địa phương.","audioKind":"ex2"}],"collocations":[{"en":"ripple effect","vi":"hiệu ứng lan tỏa"},{"en":"ripples on the water","vi":"gợn sóng trên mặt nước"},{"en":"a ripple of laughter","vi":"một tràng tiếng cười lan tỏa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ripple nhỏ hơn wave; ripple effect chỉ hiệu ứng dây chuyền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strait', 'en-c1-17', 'strait', '/streɪt/', 'C1', 'hải cảng; eo biển; cảnh ngộ khó khăn; tình thế ngặt nghèo', 'n.', NULL, NULL, 'Chỉ sự khó khăn thường dùng dạng số nhiều straits, như in dire straits.', 'Our ferry crossed the narrow strait before sunset.', NULL, 'Chiếc phà của chúng tôi đã vượt qua eo biển hẹp trước khi hoàng hôn buông xuống.', '{"wordId":"strait","ukIpa":"/streɪt/","usIpa":"/streɪt/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a narrow stretch of sea connecting two larger areas","vi":"hải cảng; eo biển"},{"pos":"n.","en":"a situation involving serious difficulty, especially lack of money","vi":"cảnh ngộ khó khăn; tình thế ngặt nghèo"}],"examples":[{"en":"Our ferry crossed the narrow strait before sunset.","vi":"Chiếc phà của chúng tôi đã vượt qua eo biển hẹp trước khi hoàng hôn buông xuống.","audioKind":"ex"},{"en":"Restrictions on shipping through a major strait can disrupt international trade and increase transport costs.","vi":"Việc hạn chế tàu thuyền qua lại qua một eo biển lớn có thể làm gián đoạn thương mại quốc tế và tăng chi phí vận chuyển.","audioKind":"ex2"}],"collocations":[{"en":"a narrow strait","vi":"một eo biển hẹp"},{"en":"cross a strait","vi":"vượt qua eo biển"},{"en":"in dire straits","vi":"lâm vào hoàn cảnh khốn đốn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ sự khó khăn thường dùng dạng số nhiều straits, như in dire straits.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plateau', 'en-c1-17', 'plateau', '/plæˈtoʊ/', 'C1', 'cao nguyên; giai đoạn bình ổn; thời kỳ không thay đổi; chững lại; đạt đến mức bình ổn', 'n.', NULL, NULL, 'Giai đoạn bình ổn nghĩa là chững lại sau khi tăng trưởng, không có nghĩa là mức độ bắt đầu giảm xuống.', 'We camped on a grassy plateau above the valley.', NULL, 'Chúng tôi cắm trại trên một cao nguyên cỏ xanh mướt phía trên thung lũng.', '{"wordId":"plateau","ukIpa":"/ˈplætəʊ/","usIpa":"/plæˈtoʊ/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A large area of flat land higher than surrounding land.","vi":"cao nguyên"},{"pos":"n.","en":"A period when growth or progress stops after an increase.","vi":"giai đoạn bình ổn; thời kỳ không thay đổi"},{"pos":"v.","en":"To stop increasing or improving and remain at a steady level.","vi":"chững lại; đạt đến mức bình ổn"}],"examples":[{"en":"We camped on a grassy plateau above the valley.","vi":"Chúng tôi cắm trại trên một cao nguyên cỏ xanh mướt phía trên thung lũng.","audioKind":"ex"},{"en":"Language learners often reach a plateau and may need different study methods to make further progress.","vi":"Người học ngôn ngữ thường trải qua giai đoạn chững lại và có thể cần các phương pháp học tập khác nhau để đạt tiến ộ xa hơn.","audioKind":"ex2"}],"collocations":[{"en":"a high plateau","vi":"vùng cao nguyên rộng lớn"},{"en":"reach a plateau","vi":"đạt đến giai đoạn bình ổn"},{"en":"a learning plateau","vi":"thời kỳ chững lại trong học tập"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Giai đoạn bình ổn nghĩa là chững lại sau khi tăng trưởng, không có nghĩa là mức độ bắt đầu giảm xuống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deluge', 'en-c1-17', 'deluge', '/ˈdeljuːdʒ/', 'C1', 'cơn mưa xối xả; trận lụt lớn; sự ồ ạt; lượng lớn dồn dập; làm ngập; làm ngập lụt, làm quá tải', 'n.', NULL, 'Đồng nghĩa: flood, downpour', 'Biểu đạt lượng lớn dồn dập dùng "a deluge of"; động từ thường dùng dạng bị động "be deluged with".', 'We sheltered in a café until the deluge stopped.', NULL, 'Chúng tôi tránh mưa ở một quán cà phê cho đến khi cơn mưa xối xả tạnh hẳn.', '{"wordId":"deluge","ukIpa":"/ˈdeljuːdʒ/","usIpa":"/ˈdeljuːdʒ/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"An extremely heavy fall of rain or a severe flood.","vi":"cơn mưa xối xả; trận lụt lớn"},{"pos":"n.","en":"An overwhelming quantity of things arriving at once.","vi":"sự ồ ạt; lượng lớn dồn dập"},{"pos":"v.","en":"Overwhelm someone or something with water or excessive quantities.","vi":"làm ngập; làm ngập lụt, làm quá tải"}],"examples":[{"en":"We sheltered in a café until the deluge stopped.","vi":"Chúng tôi tránh mưa ở một quán cà phê cho đến khi cơn mưa xối xả tạnh hẳn.","audioKind":"ex"},{"en":"After the new housing policy was announced, local officials were deluged with questions from concerned residents.","vi":"Sau khi chính sách nhà ở mới được công bố, các quan chức địa phương đã nhận được hàng loạt câu hỏi từ các cư dân quan tâm, khiến họ làm việc không xuể.","audioKind":"ex2"}],"collocations":[{"en":"a deluge of complaints","vi":"lượng lớn lời phàn nàn dồn dập"},{"en":"be deluged with requests","vi":"bị ngập trong các yêu cầu"},{"en":"a sudden deluge","vi":"một trận mưa xối xả bất ngờ"}],"wordFamily":[],"synonyms":["flood","downpour"],"antonyms":[],"tipVi":"Biểu đạt lượng lớn dồn dập dùng \"a deluge of\"; động từ thường dùng dạng bị động \"be deluged with\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stranding', 'en-c1-17', 'stranding', '/ˈstrændɪŋ/', 'C1', 'sự cạn nước mắc cạn; vụ tai nạn mắc cạn; làm cho mắc kẹt; bỏ lại ai đó ở nơi hoang vắng', 'n.', 'strand (v.), stranded (adj.)', NULL, 'Có thể đóng vai trò là danh từ, hoặc phân từ hiện tại của "strand"; trạng thái bị mắc kẹt dùng "stranded".', 'Volunteers rushed to help after a whale stranding.', NULL, 'Các tình nguyện viên đã vội vã chạy đến hỗ trợ sau vụ một con cá voi bị mắc cạn.', '{"wordId":"stranding","ukIpa":"/ˈstrændɪŋ/","usIpa":"/ˈstrændɪŋ/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"an event in which a boat or sea animal becomes stuck","vi":"sự cạn nước mắc cạn; vụ tai nạn mắc cạn"},{"pos":"v.","en":"leaving someone unable to travel or something stuck on shore","vi":"làm cho mắc kẹt; bỏ lại ai đó ở nơi hoang vắng"}],"examples":[{"en":"Volunteers rushed to help after a whale stranding.","vi":"Các tình nguyện viên đã vội vã chạy đến hỗ trợ sau vụ một con cá voi bị mắc cạn.","audioKind":"ex"},{"en":"Researchers investigate each mass stranding to understand why marine mammals sometimes become trapped in shallow coastal waters.","vi":"Các nhà nghiên cứu điều tra từng vụ cá thể mắc cạn hàng loạt để tìm hiểu lý do tại sao động vật có vú ở biển đôi khi bị kẹt ở vùng nước ven bờ nông.","audioKind":"ex2"}],"collocations":[{"en":"a whale stranding","vi":"vụ cá voi mắc cạn"},{"en":"a mass stranding","vi":"vụ mắc cạn hàng loạt"},{"en":"a stranding event","vi":"một sự cố mắc cạn"}],"wordFamily":["strand (v.)","stranded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể đóng vai trò là danh từ, hoặc phân từ hiện tại của \"strand\"; trạng thái bị mắc kẹt dùng \"stranded\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terrestrial', 'en-c1-17', 'terrestrial', '/təˈrestriəl/', 'C1', 'sống trên cạn, ở mặt đất (thay vì dưới nước); thuộc về Trái Đất (thay vì các hành tinh khác); thuộc phát thanh/truyền hình mặt đất (sử dụng thiết bị trên Trái Đất thay vì vệ tinh)', 'adj.', 'extraterrestrial (adj.)', 'Trái nghĩa: aquatic', 'Nghĩa sinh sống trên cạn đối lập với aquatic (sống dưới nước).', 'Unlike fish, terrestrial animals spend their lives on land.', NULL, 'Khác với loài cá, các loài động vật trên cạn dành toàn bộ đời sống của chúng trên đất liền.', '{"wordId":"terrestrial","ukIpa":"/təˈrestriəl/","usIpa":"/təˈrestriəl/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"living on or relating to land rather than water","vi":"sống trên cạn, ở mặt đất (thay vì dưới nước)"},{"pos":"adj.","en":"relating to Earth rather than other planets","vi":"thuộc về Trái Đất (thay vì các hành tinh khác)"},{"pos":"adj.","en":"broadcast using equipment on Earth rather than satellites","vi":"thuộc phát thanh/truyền hình mặt đất (sử dụng thiết bị trên Trái Đất thay vì vệ tinh)"}],"examples":[{"en":"Unlike fish, terrestrial animals spend their lives on land.","vi":"Khác với loài cá, các loài động vật trên cạn dành toàn bộ đời sống của chúng trên đất liền.","audioKind":"ex"},{"en":"Protecting terrestrial habitats is essential because many species cannot survive outside their original ecosystems.","vi":"Việc bảo vệ các môi trường sống trên cạn là vô cùng thiết yếu bởi vì nhiều loài sinh vật không thể sống sót nếu tách khỏi hệ sinh thái ban đầu của chúng.","audioKind":"ex2"}],"collocations":[{"en":"terrestrial animals","vi":"động vật trên cạn"},{"en":"terrestrial ecosystems","vi":"hệ sinh thái trên cạn"},{"en":"terrestrial television","vi":"truyền hình mặt đất"}],"wordFamily":["extraterrestrial (adj.)"],"synonyms":[],"antonyms":["aquatic"],"tipVi":"Nghĩa sinh sống trên cạn đối lập với aquatic (sống dưới nước).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wallaby', 'en-c1-17', 'wallaby', '/ˈwɑːləbi/', 'C1', 'chuột túi vằn; wallaby (loài thú có túi giống kangaroo nhưng nhỏ hơn)', 'n.', NULL, NULL, 'Wallaby không phải là kangaroo con; kangaroo con được gọi là joey.', 'A wallaby hopped across the path ahead of us.', NULL, 'Một con chuột túi vằn đã nhảy qua lối đi ngay trước mặt chúng tôi.', '{"wordId":"wallaby","ukIpa":"/ˈwɒləbi/","usIpa":"/ˈwɑːləbi/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"An animal resembling a kangaroo but generally smaller.","vi":"chuột túi vằn; wallaby (loài thú có túi giống kangaroo nhưng nhỏ hơn)"}],"examples":[{"en":"A wallaby hopped across the path ahead of us.","vi":"Một con chuột túi vằn đã nhảy qua lối đi ngay trước mặt chúng tôi.","audioKind":"ex"},{"en":"Protecting native vegetation helps wallaby populations survive as farming and urban development reduce their natural habitat.","vi":"Việc bảo vệ thảm thực vật bản địa giúp các quần thể chuột túi vằn sinh tồn khi hoạt động nông nghiệp và phát triển đô thị làm thu hẹp môi trường sống tự nhiên của chúng.","audioKind":"ex2"}],"collocations":[{"en":"a wallaby population","vi":"quần thể chuột túi vằn"},{"en":"wallaby habitat","vi":"môi trường sống của chuột túi vằn"},{"en":"a rock wallaby","vi":"chuột túi đá"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Wallaby không phải là kangaroo con; kangaroo con được gọi là joey.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dart', 'en-c1-17', 'dart', '/dɑrt/', 'C1', 'lao đi; phóng vụt qua; phi tiêu; mũi tên nhỏ', 'v.', NULL, 'Đồng nghĩa: dash', 'Trò chơi phi tiêu dùng darts; khi làm chủ ngữ, động từ theo sau chia số ít.', 'A squirrel darted across the path ahead of us.', NULL, 'Một con sóc phóng vụt qua con đường mòn phía trước chúng tôi.', '{"wordId":"dart","ukIpa":"/dɑːt/","usIpa":"/dɑrt/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To move suddenly and quickly in a particular direction.","vi":"lao đi; phóng vụt qua"},{"pos":"n.","en":"A small pointed object thrown at a target.","vi":"phi tiêu; mũi tên nhỏ"}],"examples":[{"en":"A squirrel darted across the path ahead of us.","vi":"Một con sóc phóng vụt qua con đường mòn phía trước chúng tôi.","audioKind":"ex"},{"en":"When animals dart across busy roads, wildlife crossings can provide safer routes and help protect local populations.","vi":"Khi động vật lao nhanh qua những con đường đông đúc, các cầu vượt dành cho động vật hoang dã có thể cung cấp các tuyến đường an toàn hơn và giúp bảo vệ các quần thể động vật địa phương.","audioKind":"ex2"}],"collocations":[{"en":"dart across the road","vi":"lao nhanh qua đường"},{"en":"dart a glance at","vi":"nhìn nhanh qua"},{"en":"throw a dart","vi":"ném phi tiêu"},{"en":"play darts","vi":"chơi phi tiêu"}],"wordFamily":[],"synonyms":["dash"],"antonyms":[],"tipVi":"Trò chơi phi tiêu dùng darts; khi làm chủ ngữ, động từ theo sau chia số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gorge', 'en-c1-17', 'gorge', '/ɡɔːrdʒ/', 'C1', 'hẻm núi sâu và hẹp; ăn ngấu nghiến; ăn uống thỏa thích', 'n.', NULL, 'Đồng nghĩa: ravine, canyon', 'Nghĩa danh từ hiện đại phổ biến là "hẻm núi"; động từ thường đi với giới từ on.', 'We watched the river rushing through the rocky gorge.', NULL, 'Chúng tôi ngắm nhìn dòng sông cuồn cuộn chảy qua hẻm núi đá.', '{"wordId":"gorge","ukIpa":"/ɡɔːdʒ/","usIpa":"/ɡɔːrdʒ/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a deep, narrow valley with steep sides","vi":"hẻm núi sâu và hẹp"},{"pos":"v.","en":"to eat a very large amount of food","vi":"ăn ngấu nghiến; ăn uống thỏa thích"}],"examples":[{"en":"We watched the river rushing through the rocky gorge.","vi":"Chúng tôi ngắm nhìn dòng sông cuồn cuộn chảy qua hẻm núi đá.","audioKind":"ex"},{"en":"Building roads through a gorge can damage fragile habitats and increase the risk of landslides.","vi":"Việc xây dựng đường xá băng qua hẻm núi có thể làm tổn hại đến các sinh cảnh mỏng manh và làm tăng nguy cơ lở đất.","audioKind":"ex2"}],"collocations":[{"en":"a deep gorge","vi":"một hẻm núi sâu"},{"en":"a narrow gorge","vi":"một hẻm núi hẹp"},{"en":"gorge on food","vi":"ăn uống ngấu nghiến"}],"wordFamily":[],"synonyms":["ravine","canyon"],"antonyms":[],"tipVi":"Nghĩa danh từ hiện đại phổ biến là \"hẻm núi\"; động từ thường đi với giới từ on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prairie', 'en-c1-17', 'prairie', '/ˈpreri/', 'C1', 'thảo nguyên Bắc Mỹ', 'n.', NULL, 'Đồng nghĩa: grassland', 'Thường chỉ riêng thảo nguyên Bắc Mỹ; nếu muốn chỉ chung các đồng cỏ thì dùng grassland.', 'We watched tall grass ripple across the open prairie.', NULL, 'Chúng tôi ngắm nhìn những thảm cỏ cao gợn sóng trải dài trên đồng cỏ lộng gió.', '{"wordId":"prairie","ukIpa":"/ˈpreəri/","usIpa":"/ˈpreri/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A broad, mostly treeless grassland in North America","vi":"thảo nguyên Bắc Mỹ"}],"examples":[{"en":"We watched tall grass ripple across the open prairie.","vi":"Chúng tôi ngắm nhìn những thảm cỏ cao gợn sóng trải dài trên đồng cỏ lộng gió.","audioKind":"ex"},{"en":"Protecting native prairie habitats helps preserve biodiversity and maintains grassland ecosystems that store substantial amounts of carbon.","vi":"Việc bảo vệ các môi trường sống thảo nguyên bản địa giúp duy trì đa dạng sinh học và gìn giữ các hệ sinh thái đồng cỏ có khả năng lưu trữ lượng lớn carbon.","audioKind":"ex2"}],"collocations":[{"en":"prairie grass","vi":"cỏ thảo nguyên"},{"en":"native prairie","vi":"thảo nguyên bản địa"},{"en":"prairie conservation","vi":"bảo tồn thảo nguyên"}],"wordFamily":[],"synonyms":["grassland"],"antonyms":[],"tipVi":"Thường chỉ riêng thảo nguyên Bắc Mỹ; nếu muốn chỉ chung các đồng cỏ thì dùng grassland.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_17_1', 'en-c1-17', 'Cách dùng “carp” (n.) — cá chép', 'common carp  ·  carp pond  ·  carp at minor faults', 'Dạng số nhiều của tên loài cá này thường giữ nguyên là carp; khi là động từ mang nghĩa phàn nàn, nó thường đi với giới từ at.', 'Họ từ (Word Family): carping (adj.)', '[{"hanzi":"We watched a large carp swimming beneath the bridge.","pinyin":"","meaning":"Chúng tôi ngắm nhìn một con cá chép lớn bơi lội dưới gầm cầu."},{"hanzi":"Introducing carp into new habitats can disturb aquatic ecosystems by increasing sediment and reducing water clarity.","pinyin":"","meaning":"Việc thả cá chép vào các môi trường sống mới có thể làm xáo trộn hệ sinh thái dưới nước do làm tăng lượng trầm tích và làm giảm độ trong của nước."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_17_2', 'en-c1-17', 'Cách dùng “offspring” (n.) — con cái; hậu quả; con non', 'produce offspring  ·  protect their offspring  ·  healthy offspring', 'Danh từ có dạng số ít và số nhiều giống nhau; khi nói về con cái của con người thì mang tính trang trọng hơn từ children.', 'Đồng nghĩa: progeny, young', '[{"hanzi":"The mother duck led her offspring safely across the path.","pinyin":"","meaning":"Vịt mẹ dẫn bầy con qua đường an toàn."},{"hanzi":"Many species invest considerable energy in protecting their offspring, which increases the young animals'' chances of survival.","pinyin":"","meaning":"Nhiều loài dành nhiều năng lượng để bảo vệ con non, qua đó làm tăng cơ hội sống sót của chúng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_17_3', 'en-c1-17', 'Cách dùng “dormant” (adj.) — ngủ đông; tạm ngưng hoạt động; tiềm ẩn', 'dormant volcano  ·  lie dormant  ·  dormant seeds', 'Chỉ trạng thái tạm không hoạt động nhưng có thể phục hồi; núi lửa ngủ đông không có nghĩa là núi lửa đã chết.', 'Họ từ (Word Family): dormancy (n.) | Đồng nghĩa: inactive, latent · Trái nghĩa: active', '[{"hanzi":"These plants stay dormant until the weather becomes warmer.","pinyin":"","meaning":"Những loài thực vật này giữ trạng thái ngủ đông cho đến khi thời tiết ấm lên."},{"hanzi":"Although the volcano has remained dormant for centuries, scientists continue to monitor it for signs of renewed activity.","pinyin":"","meaning":"Mặc dù ngọn núi lửa đã ngủ đông trong nhiều thế kỷ, các nhà khoa học vẫn tiếp tục theo dõi nó để tìm dấu hiệu hoạt động trở lại."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_17_4', 'en-c1-17', 'Cách dùng “estuary” (n.) — cửa sông; cửa sông đổ ra biển', 'a river estuary  ·  estuary wildlife  ·  a tidal estuary', 'Nhấn mạnh vùng cửa sông chịu ảnh hưởng của thủy triều, không đồng nghĩa với delta (vùng đồng bằng châu thổ).', 'Họ từ (Word Family): estuarine (adj.) | Đồng nghĩa: river mouth', '[{"hanzi":"We watched birds feeding beside the estuary at sunset.","pinyin":"","meaning":"Chúng tôi ngắm nhìn những chú chim kiếm ăn bên cửa sông vào lúc hoàng hôn."},{"hanzi":"Protecting an estuary preserves important feeding grounds for migratory birds and supports the livelihoods of local fishing communities.","pinyin":"","meaning":"Việc bảo vệ cửa sông giúp duy trì các bãi kiếm ăn quan trọng cho chim di cư và hỗ trợ sinh kế của cộng đồng ngư dân địa phương."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_17_1', 'en-c1-17', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_1_1', 'ten_c1_17_1', 'ascent', 'We began our ascent just as the sun rose.', 'We began our ascent just as the sun rose.', '/əˈsent/', 'Chúng tôi bắt đầu cuộc hành trình leo núi ngay khi mặt trời vừa ló rạng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_1_2', 'ten_c1_17_1', 'estuary', 'We watched birds feeding beside the estuary at sunset.', 'We watched birds feeding beside the estuary at sunset.', '/ˈestʃueri/', 'Chúng tôi ngắm nhìn những chú chim kiếm ăn bên cửa sông vào lúc hoàng hôn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_1_3', 'ten_c1_17_1', 'offspring', 'The mother duck led her offspring safely across the path.', 'The mother duck led her offspring safely across the path.', '/ˈɔːfsprɪŋ/', 'Vịt mẹ dẫn bầy con qua đường an toàn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_1_4', 'ten_c1_17_1', 'swirl', 'Dry leaves swirled around my feet in the wind.', 'Dry leaves swirled around my feet in the wind.', '/swɜːrl/', 'Những chiếc lá khô bay xoòng xoọc quanh chân tôi trong gió.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
