INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_1_6', 'ten_c1_17_1', 'enclosure', 'The goats rested in their enclosure beside the barn.', 'The goats rested in their enclosure beside the barn.', '/ɪnˈkloʊʒər/', 'Đàn dê nghỉ ngơi trong bãi rào chắn ngay cạnh chuồng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_1_7', 'ten_c1_17_1', 'carp', 'We watched a large carp swimming beneath the bridge.', 'We watched a large carp swimming beneath the bridge.', '/kɑːrp/', 'Chúng tôi ngắm nhìn một con cá chép lớn bơi lội dưới gầm cầu.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_1_8', 'ten_c1_17_1', 'drench', 'A sudden downpour drenched us on the way home.', 'A sudden downpour drenched us on the way home.', '/drentʃ/', 'Cơn mưa rào bất chợt đã làm chúng tôi ướt sũng trên đường về nhà.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_17_1_1', 'en-c1-17', 'ten_c1_17_1', 'listening', 'listening', 'We began our ascent just as the sun rose.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những chiếc lá khô bay xoòng xoọc quanh chân tôi trong gió.","Chúng tôi bắt đầu cuộc hành trình leo núi ngay khi mặt trời vừa ló rạng.","Khác với loài cá, các loài động vật trên cạn dành toàn bộ đời sống của chúng trên đất liền.","Chúng tôi cắm trại trên một cao nguyên cỏ xanh mướt phía trên thung lũng."]'::jsonb, 1, 'We began our ascent just as the sun rose. → Chúng tôi bắt đầu cuộc hành trình leo núi ngay khi mặt trời vừa ló rạng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_17_1_2', 'en-c1-17', 'ten_c1_17_1', 'listening', 'listening', 'We watched birds feeding beside the estuary at sunset.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những chiếc lá khô bay xoòng xoọc quanh chân tôi trong gió.","Chiếc phà của chúng tôi đã vượt qua eo biển hẹp trước khi hoàng hôn buông xuống.","Chúng tôi ngắm nhìn những chú chim kiếm ăn bên cửa sông vào lúc hoàng hôn.","Một con chuột túi vằn đã nhảy qua lối đi ngay trước mặt chúng tôi."]'::jsonb, 2, 'We watched birds feeding beside the estuary at sunset. → Chúng tôi ngắm nhìn những chú chim kiếm ăn bên cửa sông vào lúc hoàng hôn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_17_1_3', 'en-c1-17', 'ten_c1_17_1', 'listening', 'listening', 'The mother duck led her offspring safely across the path.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi ngắm nhìn dòng sông cuồn cuộn chảy qua hẻm núi đá.","Chúng tôi tránh làm phiền các loài chim trong mùa sinh sản.","Một giọt sữa nhỏ đọng lại trên một sợi râu.","Vịt mẹ dẫn bầy con qua đường an toàn."]'::jsonb, 3, 'The mother duck led her offspring safely across the path. → Vịt mẹ dẫn bầy con qua đường an toàn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_17_2', 'en-c1-17', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_2_1', 'ten_c1_17_2', 'ascent', 'The rapid ascent of renewable energy reflects both technological progress and stronger public support for environmental protection.', 'The rapid ascent of renewable energy reflects both technological progress and stronger public support for environmental protection.', '/əˈsent/', 'Sự trỗi dậy nhanh chóng của năng lượng tái tạo vừa phản ánh tiến bộ công nghệ vừa cho thấy sự hậu thuẫn mạnh mẽ hơn từ công chúng đối với công tác bảo vệ môi trường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_2_2', 'ten_c1_17_2', 'estuary', 'Protecting an estuary preserves important feeding grounds for migratory birds and supports the livelihoods of local fishing communities.', 'Protecting an estuary preserves important feeding grounds for migratory birds and supports the livelihoods of local fishing communities.', '/ˈestʃueri/', 'Việc bảo vệ cửa sông giúp duy trì các bãi kiếm ăn quan trọng cho chim di cư và hỗ trợ sinh kế của cộng đồng ngư dân địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_2_3', 'ten_c1_17_2', 'offspring', 'Many species invest considerable energy in protecting their offspring, which increases the young animals'' chances of survival.', 'Many species invest considerable energy in protecting their offspring, which increases the young animals'' chances of survival.', '/ˈɔːfsprɪŋ/', 'Nhiều loài dành nhiều năng lượng để bảo vệ con non, qua đó làm tăng cơ hội sống sót của chúng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_2_4', 'ten_c1_17_2', 'swirl', 'Dust can swirl through urban streets during construction, reducing air quality and causing discomfort for nearby residents.', 'Dust can swirl through urban streets during construction, reducing air quality and causing discomfort for nearby residents.', '/swɜːrl/', 'Bụi có thể cuốn mù mịt qua các con phố đô thị trong quá trình thi công, làm giảm chất lượng không khí và gây khó chịu cho cư dân lân cận.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_2_5', 'ten_c1_17_2', 'panther', 'Protecting forest corridors allows animals such as the panther to move safely between fragmented habitats.', 'Protecting forest corridors allows animals such as the panther to move safely between fragmented habitats.', '/ˈpænθɚ/', 'Việc bảo vệ các hành lang rừng giúp các loài động vật như báo đen di chuyển an toàn giữa các sinh cảnh bị chia cắt.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_17_2_6', 'ten_c1_17_2', 'enclosure', 'Wildlife parks should provide each enclosure with enough space for animals to display natural behaviour.', 'Wildlife parks should provide each enclosure with enough space for animals to display natural behaviour.', '/ɪnˈkloʊʒər/', 'Các công viên động vật hoang dã nên cung cấp cho mỗi khu vực nuôi nhốt đủ không gian để các loài động vật thể hiện tập tính tự nhiên.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_17_2_1', 'en-c1-17', 'ten_c1_17_2', 'listening', 'listening', 'The rapid ascent of renewable energy reflects both technological progress and stronger public support for environmental protection.', NULL, 'Trong câu vừa nghe, từ “ascent” mang nghĩa nào sau đây?', '["cực kỳ căm ghét; vô cùng ghê tởm","đổi mới; sáng tạo","sự leo trèo, sự đi lên phía trên","có ý hối lỗi; tỏm vẻ xin lỗi; ân hận"]'::jsonb, 2, '“ascent” (/əˈsent/): sự leo trèo, sự đi lên phía trên. Câu đầy đủ: The rapid ascent of renewable energy reflects both technological progress and stronger public support for environmental protection.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_17_2_2', 'en-c1-17', 'ten_c1_17_2', 'listening', 'listening', 'Protecting an estuary preserves important feeding grounds for migratory birds and supports the livelihoods of local fishing communities.', NULL, 'Trong câu vừa nghe, từ “estuary” mang nghĩa nào sau đây?', '["cửa sông; cửa sông đổ ra biển","cay độc; sắc bén; làm tổn thương","củng cố; làm vững chắc","ám chỉ; nói bóng gió; nhắc đến một cách gián tiếp"]'::jsonb, 0, '“estuary” (/ˈestʃueri/): cửa sông; cửa sông đổ ra biển. Câu đầy đủ: Protecting an estuary preserves important feeding grounds for migratory birds and supports the livelihoods of local fishing communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
