INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_1', 'en-c1-17', NULL, 'comprehensive_test', 'listening', 'ascent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mỏ đá; công trường khai thác đá","sự leo trèo, sự đi lên phía trên","sự tích lũy; sự tích tụ; lượng tích tụ","hậu duệ; con cháu"]'::jsonb, 1, 'ascent (/əˈsent/) → sự leo trèo, sự đi lên phía trên; sự thăng tiến, sự vươn lên vị trí hoặc cấp bậc cao hơn; con đường dốc, đoạn đường đi lên', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_2', 'en-c1-17', NULL, 'comprehensive_test', 'listening', 'We watched birds feeding beside the estuary at sunset.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ngắm nhìn những chú chim kiếm ăn bên cửa sông vào lúc hoàng hôn.","Các tình nguyện viên đã vội vã chạy đến hỗ trợ sau vụ một con cá voi bị mắc cạn.","Một con sóc phóng vụt qua con đường mòn phía trước chúng tôi.","Chúng tôi ngắm nhìn dòng sông cuồn cuộn chảy qua hẻm núi đá."]'::jsonb, 0, 'We watched birds feeding beside the estuary at sunset. → Chúng tôi ngắm nhìn những chú chim kiếm ăn bên cửa sông vào lúc hoàng hôn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_3', 'en-c1-17', NULL, 'comprehensive_test', 'listening', 'offspring', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự mệt mỏi; sự kiệt sức","bắt đầu; dấn thân vào","con cái; hậu quả; con non","đi vòng qua cái gì đó hoặc né tránh một bước thông thường"]'::jsonb, 2, 'offspring (/ˈɔːfsprɪŋ/) → con cái; hậu quả; con non', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_4', 'en-c1-17', NULL, 'comprehensive_test', 'listening', 'Dry leaves swirled around my feet in the wind.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những chiếc lá khô bay xoòng xoọc quanh chân tôi trong gió.","Vịt mẹ dẫn bầy con qua đường an toàn.","Chúng tôi tránh mưa ở một quán cà phê cho đến khi cơn mưa xối xả tạnh hẳn.","Chúng tôi ngắm nhìn những thảm cỏ cao gợn sóng trải dài trên đồng cỏ lộng gió."]'::jsonb, 0, 'Dry leaves swirled around my feet in the wind. → Những chiếc lá khô bay xoòng xoọc quanh chân tôi trong gió.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_5', 'en-c1-17', NULL, 'comprehensive_test', 'listening', 'panther', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thực thể độc lập; tổ chức riêng biệt","con báo đen","thuộc về thể chế cộng hòa, theo chủ nghĩa cộng hòa","độ rộng lớn; sự phong phú về phạm vi"]'::jsonb, 1, 'panther (/ˈpænθɚ/) → con báo đen; sư tử núi', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_6', 'en-c1-17', NULL, 'comprehensive_test', 'listening', 'The goats rested in their enclosure beside the barn.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc phà của chúng tôi đã vượt qua eo biển hẹp trước khi hoàng hôn buông xuống.","Đàn dê nghỉ ngơi trong bãi rào chắn ngay cạnh chuồng.","Chúng tôi ngắm nhìn những thảm cỏ cao gợn sóng trải dài trên đồng cỏ lộng gió.","Con báo đen đang nằm nghỉ ngơi yên tĩnh trên một cành cây lớn."]'::jsonb, 1, 'The goats rested in their enclosure beside the barn. → Đàn dê nghỉ ngơi trong bãi rào chắn ngay cạnh chuồng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_7', 'en-c1-17', NULL, 'comprehensive_test', 'listening', 'carp', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phân phối lại; bố trí lại","nạn đói; tình trạng chết đói","vách ngăn; tấm bình phong","cá chép"]'::jsonb, 3, 'carp (/kɑːrp/) → cá chép; bới móc; phàn nàn vặt; bắt bẻ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_8', 'en-c1-17', NULL, 'comprehensive_test', 'listening', 'A sudden downpour drenched us on the way home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một con chuột túi vằn đã nhảy qua lối đi ngay trước mặt chúng tôi.","Người nông dân nhẹ nhàng nhấc móng con ngựa lên để kiểm tra.","Chúng tôi tránh mưa ở một quán cà phê cho đến khi cơn mưa xối xả tạnh hẳn.","Cơn mưa rào bất chợt đã làm chúng tôi ướt sũng trên đường về nhà."]'::jsonb, 3, 'A sudden downpour drenched us on the way home. → Cơn mưa rào bất chợt đã làm chúng tôi ướt sũng trên đường về nhà.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
