INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_17', 'en-c1-17', NULL, 'comprehensive_test', 'fill_blank', NULL, NULL, 'Điền từ thích hợp vào chỗ trống:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_18', 'en-c1-17', NULL, 'comprehensive_test', 'reading', NULL, 'The rapid ascent of renewable energy reflects both technological progress and stronger public support for environmental protection.', 'Dựa vào câu trên, từ “ascent” có nghĩa phù hợp nhất là gì?', '["sự cạnh tranh; sự ganh đua","nhật thực; nguyệt thực","sự leo trèo, sự đi lên phía trên","kéo dài; dây dưa; kéo dài lâu hơn dự kiến"]'::jsonb, 2, 'ascent: sự leo trèo, sự đi lên phía trên; sự thăng tiến, sự vươn lên vị trí hoặc cấp bậc cao hơn; con đường dốc, đoạn đường đi lên. Dịch cả câu: Sự trỗi dậy nhanh chóng của năng lượng tái tạo vừa phản ánh tiến bộ công nghệ vừa cho thấy sự hậu thuẫn mạnh mẽ hơn từ công chúng đối với công tác bảo vệ môi trường.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_19', 'en-c1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Protecting an estuary preserves important feeding grounds for migratory birds and supports the livelihoods of local fishing communities.', 'Dựa vào câu trên, từ “estuary” có nghĩa phù hợp nhất là gì?', '["cửa sông; cửa sông đổ ra biển","thay thế; thế chỗ","tơ; lông tơ; xơ vải","bản ghi chép lời thoại; bản thảo"]'::jsonb, 0, 'estuary: cửa sông; cửa sông đổ ra biển. Dịch cả câu: Việc bảo vệ cửa sông giúp duy trì các bãi kiếm ăn quan trọng cho chim di cư và hỗ trợ sinh kế của cộng đồng ngư dân địa phương.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_20', 'en-c1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Many species invest considerable energy in protecting their offspring, which increases the young animals'' chances of survival.', 'Dựa vào câu trên, từ “offspring” có nghĩa phù hợp nhất là gì?', '["chủ nghĩa thực dân; chế độ thực dân","bùng lên; bùng phát (cháy sáng đột ngột hoặc trở nên dữ dội hơn ngay lập tức)","héc-ta; công-ta (đơn vị diện tích bằng 10.000 mét vuông)","con cái; hậu quả; con non"]'::jsonb, 3, 'offspring: con cái; hậu quả; con non. Dịch cả câu: Nhiều loài dành nhiều năng lượng để bảo vệ con non, qua đó làm tăng cơ hội sống sót của chúng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_21', 'en-c1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Dust can swirl through urban streets during construction, reducing air quality and causing discomfort for nearby residents.', 'Dựa vào câu trên, từ “swirl” có nghĩa phù hợp nhất là gì?', '["mang tính nhân đạo","lên án; chỉ trích mạnh mẽ ai đó hoặc cái gì","cuốn; xoáy tròn; làm xoáy","vô hiệu lực; không có giá trị pháp lý"]'::jsonb, 2, 'swirl: cuốn; xoáy tròn; làm xoáy; vũng xoáy; hình xoắn ốc. Dịch cả câu: Bụi có thể cuốn mù mịt qua các con phố đô thị trong quá trình thi công, làm giảm chất lượng không khí và gây khó chịu cho cư dân lân cận.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_22', 'en-c1-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lao đi; phóng vụt qua”', '["dart","conscientiously","consecutive","colonial"]'::jsonb, 0, 'lao đi; phóng vụt qua → dart (/dɑrt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_23', 'en-c1-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hẻm núi sâu và hẹp”', '["gorge","living quarters","agitation","coeducation"]'::jsonb, 0, 'hẻm núi sâu và hẹp → gorge (/ɡɔːrdʒ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_17_24', 'en-c1-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thảo nguyên Bắc Mỹ”', '["pledge","payable","absurdity","prairie"]'::jsonb, 3, 'thảo nguyên Bắc Mỹ → prairie (/ˈpreri/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-18', 'en', 'Bài 18: Thiên nhiên & Thời tiết (4) - CEFR C1', 'CEFR C1', 'C1 · Thiên nhiên', '25 từ vựng Tiếng Anh CEFR C1 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5018, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mighty', 'en-c1-18', 'mighty', '/ˈmaɪti/', 'C1', 'hùng mạnh; to lớn; rất; cực kỳ', 'adj.', 'might (n.), mightily (adv.)', 'Đồng nghĩa: powerful, strong · Trái nghĩa: weak', 'Tính từ thường mang sắc thái văn học; nghĩa phó từ "rất" mang tính thân mật, đời thường hơn.', 'A mighty oak stood in the middle of the field.', NULL, 'Một cây sồi khổng lồ sừng sững ở giữa cánh đồng.', '{"wordId":"mighty","ukIpa":"/ˈmaɪti/","usIpa":"/ˈmaɪti/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"Very strong, powerful, or large.","vi":"hùng mạnh; to lớn"},{"pos":"adv.","en":"Very; used informally to make a description stronger.","vi":"rất; cực kỳ"}],"examples":[{"en":"A mighty oak stood in the middle of the field.","vi":"Một cây sồi khổng lồ sừng sững ở giữa cánh đồng.","audioKind":"ex"},{"en":"Although mighty rivers provide valuable renewable energy, building large dams can seriously disrupt surrounding ecosystems.","vi":"Mặc dù những dòng sông lớn cung cấp năng lượng tái tạo quý giá, việc xây dựng các con đập lớn có thể phá vỡ nghiêm trọng hệ sinh thái xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"mighty river","vi":"dòng sông lớn"},{"en":"mighty empire","vi":"đế chế hùng mạnh"},{"en":"mighty effort","vi":"nỗ lực cực lớn"}],"wordFamily":["might (n.)","mightily (adv.)"],"synonyms":["powerful","strong"],"antonyms":["weak"],"tipVi":"Tính từ thường mang sắc thái văn học; nghĩa phó từ \"rất\" mang tính thân mật, đời thường hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_falcon', 'en-c1-18', 'falcon', '/ˈfælkən/', 'C1', 'con chim ưng; con ưng', 'n.', 'falconry (n.), falconer (n.)', NULL, 'Falcon chỉ chim ưng, không nên đồng nhất hoàn toàn với hawk vốn chỉ chung các loài diều hâu.', 'A falcon circled above the cliffs this morning.', NULL, 'Sáng nay một con chim ưng bay lượn vòng phía trên các vách đá.', '{"wordId":"falcon","ukIpa":"/ˈfɔːlkən/","usIpa":"/ˈfælkən/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a hunting bird with pointed wings and a curved beak","vi":"con chim ưng; con ưng"}],"examples":[{"en":"A falcon circled above the cliffs this morning.","vi":"Sáng nay một con chim ưng bay lượn vòng phía trên các vách đá.","audioKind":"ex"},{"en":"Protecting cliff habitats can help falcon populations recover in regions where suitable nesting sites have disappeared.","vi":"Bảo vệ môi trường sống trên vách đá có thể giúp phục hồi các quần thể chim ưng ở những khu vực mà các vị trí làm tổ thích hợp đã biến mất.","audioKind":"ex2"}],"collocations":[{"en":"peregrine falcon","vi":"chim ưng peregrine"},{"en":"falcon nest","vi":"tổ chim ưng"},{"en":"falcon population","vi":"quần thể chim ưng"}],"wordFamily":["falconry (n.)","falconer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Falcon chỉ chim ưng, không nên đồng nhất hoàn toàn với hawk vốn chỉ chung các loài diều hâu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kernel', 'en-c1-18', 'kernel', '/ˈkɝːnəl/', 'C1', 'nhân (hạt); hạt (ngũ cốc); cốt lõi; phần quan trọng nhất của cái gì đó; nhân hệ điều hành', 'n.', NULL, NULL, 'kernel chỉ phần nhân bên trong lớp vỏ cứng của hạt hoặc quả hạch, khác với hạch cứng của quả mọng nước.', 'She cracked the walnut and carefully removed the kernel.', NULL, 'Cô ấy đập vỡ quả óc chó và cẩn thận lấy phần nhân bên trong ra.', '{"wordId":"kernel","ukIpa":"/ˈkɜːnəl/","usIpa":"/ˈkɝːnəl/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"The edible inner part of a nut, or a grain seed.","vi":"nhân (hạt); hạt (ngũ cốc)"},{"pos":"n.","en":"The central or most important part of something.","vi":"cốt lõi; phần quan trọng nhất của cái gì đó"},{"pos":"n.","en":"The central software component that manages a computer''s basic operations.","vi":"nhân hệ điều hành"}],"examples":[{"en":"She cracked the walnut and carefully removed the kernel.","vi":"Cô ấy đập vỡ quả óc chó và cẩn thận lấy phần nhân bên trong ra.","audioKind":"ex"},{"en":"Even exaggerated media reports may contain a kernel of truth that deserves further investigation by independent researchers.","vi":"Ngay cả những bản tin bị thổi phồng cũng có thể chứa một chút sự thật đáng để các nhà nghiên cứu độc lập điều tra thêm.","audioKind":"ex2"}],"collocations":[{"en":"corn kernel","vi":"hạt ngô"},{"en":"walnut kernel","vi":"nhân quả óc chó"},{"en":"a kernel of truth","vi":"một chút sự thật"},{"en":"operating system kernel","vi":"nhân hệ điều hành"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"kernel chỉ phần nhân bên trong lớp vỏ cứng của hạt hoặc quả hạch, khác với hạch cứng của quả mọng nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abound', 'en-c1-18', 'abound', '/əˈbaʊnd/', 'C1', 'có rất nhiều; phong phú; ngập tràn', 'v.', NULL, 'Đồng nghĩa: proliferate', 'Đây là nội động từ; nơi nào có nhiều thứ gì thì dùng abound in/with.', 'Wildflowers abound in the fields behind our house each spring.', NULL, 'Hoa dại mọc đầy trên các cánh đồng phía sau ngôi nhà của chúng tôi vào mỗi mùa xuân.', '{"wordId":"abound","ukIpa":"/əˈbaʊnd/","usIpa":"/əˈbaʊnd/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To exist in large quantities or be very common","vi":"có rất nhiều; phong phú; ngập tràn"}],"examples":[{"en":"Wildflowers abound in the fields behind our house each spring.","vi":"Hoa dại mọc đầy trên các cánh đồng phía sau ngôi nhà của chúng tôi vào mỗi mùa xuân.","audioKind":"ex"},{"en":"Opportunities for renewable energy development abound in regions with consistent sunshine and strong coastal winds.","vi":"Cơ hội phát triển năng lượng tái tạo rất phong phú ở những vùng có ánh nắng ổn định và gió ven biển mạnh.","audioKind":"ex2"}],"collocations":[{"en":"opportunities abound","vi":"cơ hội vô kể"},{"en":"rumours abound","vi":"tin đồn lan truyền khắp nơi"},{"en":"abound in wildlife","vi":"động vật hoang dã phong phú"}],"wordFamily":[],"synonyms":["proliferate"],"antonyms":[],"tipVi":"Đây là nội động từ; nơi nào có nhiều thứ gì thì dùng abound in/with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meadow', 'en-c1-18', 'meadow', '/ˈmedoʊ/', 'C1', 'bãi cỏ, đồng cỏ (thường có hoa dại)', 'n.', NULL, 'Đồng nghĩa: grassland', 'meadow thường chỉ đồng cỏ tự nhiên ở vùng nông thôn, không phải là thảm cỏ cắt tỉa gọn gàng như lawn.', 'We spread our picnic blanket in a sunny meadow.', NULL, 'Chúng tôi trải thảm dã ngoại trên một bãi cỏ ngập tràn ánh nắng.', '{"wordId":"meadow","ukIpa":"/ˈmedəʊ/","usIpa":"/ˈmedoʊ/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a field of grass, often containing wildflowers","vi":"bãi cỏ, đồng cỏ (thường có hoa dại)"}],"examples":[{"en":"We spread our picnic blanket in a sunny meadow.","vi":"Chúng tôi trải thảm dã ngoại trên một bãi cỏ ngập tràn ánh nắng.","audioKind":"ex"},{"en":"Protecting wildflower meadows helps maintain biodiversity by providing food and shelter for insects and birds.","vi":"Bảo vệ các đồng cỏ hoa dại giúp duy trì sự đa dạng sinh học bằng cách cung cấp thức ăn và nơi trú ẩn cho côn trùng và loài chim.","audioKind":"ex2"}],"collocations":[{"en":"wildflower meadow","vi":"đồng cỏ hoa dại"},{"en":"hay meadow","vi":"đồng cỏ làm cỏ khô"},{"en":"alpine meadow","vi":"đồng cỏ trên núi cao"}],"wordFamily":[],"synonyms":["grassland"],"antonyms":[],"tipVi":"meadow thường chỉ đồng cỏ tự nhiên ở vùng nông thôn, không phải là thảm cỏ cắt tỉa gọn gàng như lawn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lash', 'en-c1-18', 'lash', '/læʃ/', 'C1', 'quất; đánh mạnh; buộc chặt; cột chặt; lông mi; đòn roi', 'v.', NULL, NULL, 'lash out at có thể chỉ sự tấn công bất ngờ hoặc chỉ trích gay gắt.', 'Heavy rain lashed the windows throughout the night.', NULL, 'Cơn mưa lớn quất xối xả vào các ô cửa sổ suốt cả đêm.', '{"wordId":"lash","ukIpa":"/læʃ/","usIpa":"/læʃ/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To strike forcefully, especially with a whip or like one.","vi":"quất; đánh mạnh"},{"pos":"v.","en":"To fasten things tightly together using rope or cord.","vi":"buộc chặt; cột chặt"},{"pos":"n.","en":"An eyelash, or a stroke delivered with a whip.","vi":"lông mi; đòn roi"}],"examples":[{"en":"Heavy rain lashed the windows throughout the night.","vi":"Cơn mưa lớn quất xối xả vào các ô cửa sổ suốt cả đêm.","audioKind":"ex"},{"en":"As storms lash coastal communities, stronger sea defences become increasingly important for protecting homes and essential infrastructure.","vi":"Khi bão quất mạnh vào các cộng đồng ven biển, các hệ thống phòng thủ biển kiên cố hơn ngày càng trở nên quan trọng trong việc bảo vệ nhà cửa và cơ sở hạ tầng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"lash against the windows","vi":"quất vào cửa sổ"},{"en":"lash together","vi":"buộc chặt vào nhau"},{"en":"lash out at","vi":"chỉ trích gay gắt; tấn công dữ dội"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"lash out at có thể chỉ sự tấn công bất ngờ hoặc chỉ trích gay gắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indigenous', 'en-c1-18', 'indigenous', '/ɪnˈdɪdʒənəs/', 'C1', 'bản địa; thuộc về người bản xứ', 'adj.', NULL, 'Đồng nghĩa: native · Trái nghĩa: non-native', 'Thường đi với giới từ indigenous to; khi dùng để chỉ cộng đồng người, chữ cái đầu tiên thường được viết hoa.', 'These flowers are indigenous to the valley near our village.', NULL, 'Những loài hoa này mọc hoang dã và có nguồn gốc từ thung lũng gần làng chúng tôi.', '{"wordId":"indigenous","ukIpa":"/ɪnˈdɪdʒənəs/","usIpa":"/ɪnˈdɪdʒənəs/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"Originating or living naturally in a place, rather than arriving later.","vi":"bản địa; thuộc về người bản xứ"}],"examples":[{"en":"These flowers are indigenous to the valley near our village.","vi":"Những loài hoa này mọc hoang dã và có nguồn gốc từ thung lũng gần làng chúng tôi.","audioKind":"ex"},{"en":"Protecting indigenous languages helps preserve cultural knowledge that has been passed down through many generations.","vi":"Việc bảo vệ các ngôn ngữ bản địa góp phần gìn giữ những tri thức văn hóa đã được lưu truyền qua nhiều thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"indigenous peoples","vi":"các dân tộc bản địa"},{"en":"indigenous languages","vi":"ngôn ngữ bản địa"},{"en":"indigenous species","vi":"loài bản địa"},{"en":"indigenous to an area","vi":"bản địa tại một vùng"}],"wordFamily":[],"synonyms":["native"],"antonyms":["non-native"],"tipVi":"Thường đi với giới từ indigenous to; khi dùng để chỉ cộng đồng người, chữ cái đầu tiên thường được viết hoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cluster', 'en-c1-18', 'cluster', '/ˈklʌstər/', 'C1', 'búi; cụm; đám; nhóm; tụ tập; quây quần; nhóm lại', 'n.', 'clustered (adj.), clustering (n.)', 'Đồng nghĩa: group, bunch', 'Nhấn mạnh sự tập trung gắn kết; cụm từ a cluster of thường đi kèm với danh từ số nhiều ở phía sau.', 'A cluster of purple flowers grew beside the gate.', NULL, 'Một cụm hoa màu tím mọc ở bên cạnh cổng.', '{"wordId":"cluster","ukIpa":"/ˈklʌstə/","usIpa":"/ˈklʌstər/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a group of similar things positioned or occurring close together","vi":"búi; cụm; đám; nhóm"},{"pos":"v.","en":"to gather closely together or make things gather together","vi":"tụ tập; quây quần; nhóm lại"}],"examples":[{"en":"A cluster of purple flowers grew beside the gate.","vi":"Một cụm hoa màu tím mọc ở bên cạnh cổng.","audioKind":"ex"},{"en":"Technology companies often cluster near universities, where they can recruit skilled graduates and collaborate with researchers.","vi":"Các công ty công nghệ thường tập trung gần các trường đại học, nơi họ có thể tuyển dụng các cử nhân lành nghề và hợp tác với các nhà nghiên cứu.","audioKind":"ex2"}],"collocations":[{"en":"a cluster of","vi":"một cụm; một nhóm"},{"en":"cluster together","vi":"tụ tập lại với nhau"},{"en":"cluster around","vi":"quây quần xung quanh"},{"en":"industrial cluster","vi":"cụm công nghiệp"}],"wordFamily":["clustered (adj.)","clustering (n.)"],"synonyms":["group","bunch"],"antonyms":[],"tipVi":"Nhấn mạnh sự tập trung gắn kết; cụm từ a cluster of thường đi kèm với danh từ số nhiều ở phía sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_avalanche', 'en-c1-18', 'avalanche', '/ˈævəlæntʃ/', 'C1', 'tuyết lở; sự dồn dập; lượng lớn dồn dập', 'n.', NULL, NULL, 'Cụm từ an avalanche of đi với danh từ đếm được số nhiều hoặc không đếm được, diễn tả lượng lớn dồn dập.', 'The mountain road was closed after an avalanche overnight.', NULL, 'Con đường núi đã bị phong tỏa sau một trận tuyết lở qua đêm.', '{"wordId":"avalanche","ukIpa":"/ˈævəlɑːnʃ/","usIpa":"/ˈævəlæntʃ/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A large mass of snow falling rapidly down a mountain.","vi":"tuyết lở"},{"pos":"n.","en":"A sudden arrival of an overwhelming amount of something.","vi":"sự dồn dập; lượng lớn dồn dập"}],"examples":[{"en":"The mountain road was closed after an avalanche overnight.","vi":"Con đường núi đã bị phong tỏa sau một trận tuyết lở qua đêm.","audioKind":"ex"},{"en":"Mountain communities need reliable warning systems to reduce the risks that avalanches pose to residents and visitors.","vi":"Các cộng đồng miền núi cần hệ thống cảnh báo đáng tin cậy để giảm thiểu rủi ro mà tuyết lở gây ra cho cư dân và du khách.","audioKind":"ex2"}],"collocations":[{"en":"trigger an avalanche","vi":"gây ra tuyết lở"},{"en":"avalanche risk","vi":"rủi ro tuyết lở"},{"en":"an avalanche of complaints","vi":"hàng loạt khiếu nại dồn dập"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ an avalanche of đi với danh từ đếm được số nhiều hoặc không đếm được, diễn tả lượng lớn dồn dập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_migratory', 'en-c1-18', 'migratory', '/ˈmaɪɡrətɔːri/', 'C1', 'có tính chất di cư; thích di trú', 'adj.', 'migrate (v.), migration (n.), migrant (n.)', NULL, 'Thường dùng để mô tả sự di chuyển theo mùa của các loài chim, không giống với việc lang thang không mục đích.', 'Migratory birds gather by the lake every spring.', NULL, 'Chim di cư tụ tập bên hồ vào mỗi mùa xuân.', '{"wordId":"migratory","ukIpa":"/maɪˈɡreɪtəri/","usIpa":"/ˈmaɪɡrətɔːri/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"Moving between regions regularly, often with the seasons.","vi":"có tính chất di cư; thích di trú"}],"examples":[{"en":"Migratory birds gather by the lake every spring.","vi":"Chim di cư tụ tập bên hồ vào mỗi mùa xuân.","audioKind":"ex"},{"en":"Protecting wetlands along migratory routes is essential because many bird species depend on these habitats for food and rest.","vi":"Việc bảo vệ các vùng đất ngập nước dọc theo các tuyến đường di cư là rất quan trọng vì nhiều loài chim phụ thuộc vào các sinh cảnh này để kiếm ăn và nghỉ ngơi.","audioKind":"ex2"}],"collocations":[{"en":"migratory birds","vi":"chim di cư"},{"en":"migratory species","vi":"các loài động vật di cư"},{"en":"migratory routes","vi":"tuyến đường di cư"},{"en":"migratory patterns","vi":"tập quán di cư"}],"wordFamily":["migrate (v.)","migration (n.)","migrant (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng để mô tả sự di chuyển theo mùa của các loài chim, không giống với việc lang thang không mục đích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mane', 'en-c1-18', 'mane', '/meɪn/', 'C1', 'bờm (ngựa, sư tử, v.v.); mái tóc dày và dài của con người', 'n.', NULL, NULL, 'Mane phát âm giống từ main; từ này chỉ bờm thú hoặc mái tóc dày.', 'She gently brushed the pony''s mane before their ride.', NULL, 'Cô ấy nhẹ nhàng chải bờm cho chú ngựa pony trước khi cưỡi.', '{"wordId":"mane","ukIpa":"/meɪn/","usIpa":"/meɪn/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"long thick hair around an animal''s neck or head","vi":"bờm (ngựa, sư tử, v.v.)"},{"pos":"n.","en":"a person''s long thick hair","vi":"mái tóc dày và dài của con người"}],"examples":[{"en":"She gently brushed the pony''s mane before their ride.","vi":"Cô ấy nhẹ nhàng chải bờm cho chú ngựa pony trước khi cưỡi.","audioKind":"ex"},{"en":"A male lion''s mane can provide researchers with clues about its health and physical condition.","vi":"Bờm của một con sư tử đực có thể cung cấp cho các nhà nghiên cứu manh mối về sức khỏe và thể trạng của nó.","audioKind":"ex2"}],"collocations":[{"en":"a lion''s mane","vi":"bờm sư tử"},{"en":"a horse''s mane","vi":"bờm ngựa"},{"en":"a thick mane","vi":"bờm dày"},{"en":"a mane of hair","vi":"mái tóc dày dài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Mane phát âm giống từ main; từ này chỉ bờm thú hoặc mái tóc dày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_majesty', 'en-c1-18', 'majesty', '/ˈmædʒəsti/', 'C1', 'vẻ hùng vĩ; sự tráng lệ; sự uy nghiêm; bệ hạ', 'n.', 'majestic (adj.), majestically (adv.)', 'Đồng nghĩa: grandeur, splendour', 'Khi dùng để chỉ tước hiệu "bệ hạ", chữ cái đầu tiên phải viết hoa: Majesty.', 'We stood silently, amazed by the majesty of the mountains.', NULL, 'Chúng tôi đứng lặng im, ngỡ ngàng trước vẻ hùng vĩ của những ngọn núi.', '{"wordId":"majesty","ukIpa":"/ˈmædʒəsti/","usIpa":"/ˈmædʒəsti/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"Impressive beauty, grandeur, or dignity that inspires admiration.","vi":"vẻ hùng vĩ; sự tráng lệ; sự uy nghiêm"},{"pos":"n.","en":"A title used when addressing or referring to a monarch.","vi":"bệ hạ"}],"examples":[{"en":"We stood silently, amazed by the majesty of the mountains.","vi":"Chúng tôi đứng lặng im, ngỡ ngàng trước vẻ hùng vĩ của những ngọn núi.","audioKind":"ex"},{"en":"Visitors drawn by the majesty of ancient temples can generate income for local conservation projects.","vi":"Du khách bị thu hút bởi sự uy nghiêm và tráng lệ của các ngôi đền cổ có thể tạo ra nguồn thu cho các dự án bảo tồn địa phương.","audioKind":"ex2"}],"collocations":[{"en":"the majesty of nature","vi":"vẻ hùng vĩ của thiên nhiên"},{"en":"Your Majesty","vi":"Tâu Bệ hạ"},{"en":"His Majesty","vi":"Đức Vua Bệ hạ"}],"wordFamily":["majestic (adj.)","majestically (adv.)"],"synonyms":["grandeur","splendour"],"antonyms":[],"tipVi":"Khi dùng để chỉ tước hiệu \"bệ hạ\", chữ cái đầu tiên phải viết hoa: Majesty.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ore', 'en-c1-18', 'ore', '/ɔːr/', 'C1', 'quặng (đá chứa kim loại hoặc các chất có giá trị có thể khai thác)', 'n.', NULL, NULL, 'ore là khoáng sản chứa chất có thể tách ra, không đồng nhất với metal.', 'The truck carried iron ore down the dusty road.', NULL, 'Chiếc xe tải chở quặng sắt chạy dọc con đường bụi bặm.', '{"wordId":"ore","ukIpa":"/ɔː/","usIpa":"/ɔːr/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"rock containing metal or other valuable substances that can be extracted","vi":"quặng (đá chứa kim loại hoặc các chất có giá trị có thể khai thác)"}],"examples":[{"en":"The truck carried iron ore down the dusty road.","vi":"Chiếc xe tải chở quặng sắt chạy dọc con đường bụi bặm.","audioKind":"ex"},{"en":"Extracting metals from ore requires substantial energy and can cause serious damage to surrounding ecosystems.","vi":"Việc chiết xuất kim loại từ quặng đòi hỏi lượng năng lượng lớn và có thể gây tổn hại nghiêm trọng đến hệ sinh thái xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"iron ore","vi":"quặng sắt"},{"en":"copper ore","vi":"quặng đồng"},{"en":"ore deposits","vi":"mỏ quặng"},{"en":"extract metal from ore","vi":"khai thác kim loại từ quặng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"ore là khoáng sản chứa chất có thể tách ra, không đồng nhất với metal.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_encircle', 'en-c1-18', 'encircle', '/ɪnˈsɝːkl/', 'C1', 'bao quanh; vây quanh', 'v.', 'encirclement (n.)', 'Đồng nghĩa: surround, enclose', 'Động từ ngoại động từ; bị bao quanh thường dùng be encircled by.', 'Tall trees encircle the small pond behind our house.', NULL, 'Những hàng cây cao vây quanh cái ao nhỏ phía sau nhà chúng tôi.', '{"wordId":"encircle","ukIpa":"/ɪnˈsɜːkl/","usIpa":"/ɪnˈsɝːkl/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"To form a circle around someone or something.","vi":"bao quanh; vây quanh"}],"examples":[{"en":"Tall trees encircle the small pond behind our house.","vi":"Những hàng cây cao vây quanh cái ao nhỏ phía sau nhà chúng tôi.","audioKind":"ex"},{"en":"Green belts that encircle urban areas can protect wildlife habitats and limit uncontrolled development.","vi":"Các vành đai xanh bao quanh khu vực đô thị có thể bảo vệ môi trường sống của động vật hoang dã và hạn chế tình trạng phát triển tự phát.","audioKind":"ex2"}],"collocations":[{"en":"be encircled by mountains","vi":"bị núi bao quanh"},{"en":"encircle the city","vi":"bao quanh thành phố"},{"en":"encircle with a fence","vi":"rào quanh bằng hàng rào"}],"wordFamily":["encirclement (n.)"],"synonyms":["surround","enclose"],"antonyms":[],"tipVi":"Động từ ngoại động từ; bị bao quanh thường dùng be encircled by.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tropic', 'en-c1-18', 'tropic', '/ˈtrɑːpɪk/', 'C1', 'vòng chí tuyến; vùng nhiệt đới', 'n.', 'tropical (adj.), subtropical (adj.)', NULL, 'Từ chỉ đường chí tuyến dùng số ít; trong khi đó vùng nhiệt đới luôn dùng dạng số nhiều the tropics.', 'Our guide pointed to the northern tropic on a globe.', NULL, 'Hướng dẫn viên chỉ vào đường chí tuyến Bắc trên quả địa cầu.', '{"wordId":"tropic","ukIpa":"/ˈtrɒpɪk/","usIpa":"/ˈtrɑːpɪk/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"Either of two imaginary circles marking Earth''s tropical boundaries.","vi":"vòng chí tuyến"},{"pos":"n.","en":"The hot region between these circles, called the tropics.","vi":"vùng nhiệt đới"}],"examples":[{"en":"Our guide pointed to the northern tropic on a globe.","vi":"Hướng dẫn viên chỉ vào đường chí tuyến Bắc trên quả địa cầu.","audioKind":"ex"},{"en":"Communities in the tropics often depend on seasonal rainfall to sustain agriculture and maintain reliable freshwater supplies.","vi":"Các cộng đồng ở vùng nhiệt đới thường phụ thuộc vào lượng mưa theo mùa để duy trì sản xuất nông nghiệp và đảm bảo nguồn cung cấp nước ngọt ổn định.","audioKind":"ex2"}],"collocations":[{"en":"Tropic of Cancer","vi":"Bắc Chí Tuyến"},{"en":"Tropic of Capricorn","vi":"Nam Chí Tuyến"},{"en":"in the tropics","vi":"ở vùng nhiệt đới"}],"wordFamily":["tropical (adj.)","subtropical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ chỉ đường chí tuyến dùng số ít; trong khi đó vùng nhiệt đới luôn dùng dạng số nhiều the tropics.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plume', 'en-c1-18', 'plume', '/pluːm/', 'C1', 'lông vũ lớn; lông trang trí; cột (khói, bụi, nước) bốc lên', 'n.', 'plumed (adj.)', NULL, 'Vừa chỉ chiếc lông lớn, vừa chỉ cột khói, cột nước có hình dạng giống lông vũ.', 'A bright plume decorated the dancer''s tall hat.', NULL, 'Một chiếc lông vũ rực rỡ trang trí trên chiếc mũ cao của vũ công.', '{"wordId":"plume","ukIpa":"/pluːm/","usIpa":"/pluːm/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a large feather, especially one used for decoration","vi":"lông vũ lớn; lông trang trí"},{"pos":"n.","en":"a rising mass of smoke, water, or dust","vi":"cột (khói, bụi, nước) bốc lên"}],"examples":[{"en":"A bright plume decorated the dancer''s tall hat.","vi":"Một chiếc lông vũ rực rỡ trang trí trên chiếc mũ cao của vũ công.","audioKind":"ex"},{"en":"A thick plume of smoke rose above the factory, raising concerns about local air quality.","vi":"Một cột khói dày bốc lên trên nhà máy, dấy lên lo ngại về chất lượng không khí địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a plume of smoke","vi":"một cột khói"},{"en":"a plume of feathers","vi":"một chùm lông vũ"},{"en":"a volcanic plume","vi":"cột khói núi lửa"}],"wordFamily":["plumed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa chỉ chiếc lông lớn, vừa chỉ cột khói, cột nước có hình dạng giống lông vũ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abundance', 'en-c1-18', 'abundance', '/əˈbʌndəns/', 'C1', 'sự phong phú; sự dồi dào', 'n.', 'abundant (adj.), abundantly (adv.)', 'Đồng nghĩa: plenty, profusion · Trái nghĩa: scarcity, shortage', 'Thường dùng an abundance of cộng với danh từ, hoặc in abundance.', 'Our garden produces an abundance of tomatoes every summer.', NULL, 'Khu vườn của chúng tôi cho ra lượng cà chua dồi dào vào mỗi mùa hè.', '{"wordId":"abundance","ukIpa":"/əˈbʌndəns/","usIpa":"/əˈbʌndəns/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a very large quantity of something","vi":"sự phong phú; sự dồi dào"}],"examples":[{"en":"Our garden produces an abundance of tomatoes every summer.","vi":"Khu vườn của chúng tôi cho ra lượng cà chua dồi dào vào mỗi mùa hè.","audioKind":"ex"},{"en":"An abundance of natural resources does not necessarily guarantee sustainable economic growth or improved living standards.","vi":"Sự phong phú về tài nguyên thiên nhiên không nhất thiết đảm bảo tăng trưởng kinh tế bền vững hoặc nâng cao mức sống.","audioKind":"ex2"}],"collocations":[{"en":"an abundance of","vi":"rất nhiều; sự dồi dào của"},{"en":"in abundance","vi":"dồi dào; thừa thãi"},{"en":"an abundance of wildlife","vi":"sự phong phú của động vật hoang dã"}],"wordFamily":["abundant (adj.)","abundantly (adv.)"],"synonyms":["plenty","profusion"],"antonyms":["scarcity","shortage"],"tipVi":"Thường dùng an abundance of cộng với danh từ, hoặc in abundance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hind', 'en-c1-18', 'hind', '/haɪnd/', 'C1', 'ở phía sau; phần sau; hươu cái; nai cái trưởng thành', 'adj.', 'hindquarters (n.)', 'Đồng nghĩa: rear · Trái nghĩa: front', 'Khi là tính từ, từ này chủ yếu bổ nghĩa cho phần chân hoặc chi của động vật, không dùng để chỉ chung các sự vật phía sau.', 'The rabbit pushed off with its powerful hind legs.', NULL, 'Con thỏ dùng đôi chân sau đầy sức mạnh để bật nhảy đi.', '{"wordId":"hind","ukIpa":"/haɪnd/","usIpa":"/haɪnd/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"At the back of an animal''s body, especially its legs.","vi":"ở phía sau; phần sau"},{"pos":"n.","en":"An adult female deer, especially a red deer.","vi":"hươu cái; nai cái trưởng thành"}],"examples":[{"en":"The rabbit pushed off with its powerful hind legs.","vi":"Con thỏ dùng đôi chân sau đầy sức mạnh để bật nhảy đi.","audioKind":"ex"},{"en":"Kangaroos rely on their strong hind legs to travel efficiently across large areas in search of food.","vi":"Loài chuột túi dựa vào đôi chân sau khỏe mạnh để di chuyển hiệu quả trên những khoảng đất rộng lớn nhằm tìm kiếm thức ăn.","audioKind":"ex2"}],"collocations":[{"en":"hind legs","vi":"chân sau"},{"en":"hind feet","vi":"bàn chân sau"},{"en":"hind limbs","vi":"chi sau"}],"wordFamily":["hindquarters (n.)"],"synonyms":["rear"],"antonyms":["front"],"tipVi":"Khi là tính từ, từ này chủ yếu bổ nghĩa cho phần chân hoặc chi của động vật, không dùng để chỉ chung các sự vật phía sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_earthworm', 'en-c1-18', 'earthworm', '/ˈɝːθwɝːm/', 'C1', 'con giun đất', 'n.', NULL, NULL, 'Là danh từ đếm được; từ earth ở đây dùng để chỉ đất.', 'An earthworm wriggled out of the wet garden soil.', NULL, 'Một con giun đất quằn quại bò ra khỏi lớp đất vườn ẩm ướt.', '{"wordId":"earthworm","ukIpa":"/ˈɜːθwɜːm/","usIpa":"/ˈɝːθwɝːm/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"a long, soft worm that lives in soil","vi":"con giun đất"}],"examples":[{"en":"An earthworm wriggled out of the wet garden soil.","vi":"Một con giun đất quằn quại bò ra khỏi lớp đất vườn ẩm ướt.","audioKind":"ex"},{"en":"Earthworms improve soil structure by creating tunnels that allow air and water to move more freely.","vi":"Giun đất cải thiện cấu trúc đất bằng cách tạo ra các đường hầm giúp không khí và nước lưu thông tự do hơn.","audioKind":"ex2"}],"collocations":[{"en":"earthworm populations","vi":"quần thể giun đất"},{"en":"earthworm activity","vi":"hoạt động của giun đất"},{"en":"earthworm castings","vi":"phân giun đất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; từ earth ở đây dùng để chỉ đất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ferocious', 'en-c1-18', 'ferocious', '/fəˈroʊʃəs/', 'C1', 'hung dữ; dữ tợn; mãnh liệt; dữ dội; khốc liệt', 'adj.', 'ferociously (adv.), ferocity (n.)', 'Đồng nghĩa: fierce, savage · Trái nghĩa: gentle', 'Có thể dùng để miêu tả động vật hung dữ hoặc dùng cho cạnh tranh, bão tố dữ dội.', 'The ferocious dog growled from behind the locked gate.', NULL, 'Con chó dữ gầm gừ phía sau cánh cổng đã khóa.', '{"wordId":"ferocious","ukIpa":"/fəˈrəʊʃəs/","usIpa":"/fəˈroʊʃəs/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"very fierce, violent, or aggressive","vi":"hung dữ; dữ tợn"},{"pos":"adj.","en":"extremely strong or intense","vi":"mãnh liệt; dữ dội; khốc liệt"}],"examples":[{"en":"The ferocious dog growled from behind the locked gate.","vi":"Con chó dữ gầm gừ phía sau cánh cổng đã khóa.","audioKind":"ex"},{"en":"Ferocious competition in the technology sector can encourage innovation but also threaten the survival of smaller firms.","vi":"Sự cạnh tranh khốc liệt trong ngành công nghệ có thể thúc đẩy đổi mới nhưng đồng thời cũng đe dọa sự sống còn của các doanh nghiệp nhỏ hơn.","audioKind":"ex2"}],"collocations":[{"en":"a ferocious animal","vi":"động vật hung dữ"},{"en":"ferocious competition","vi":"sự cạnh tranh khốc liệt"},{"en":"a ferocious storm","vi":"cơn bão dữ dội"}],"wordFamily":["ferociously (adv.)","ferocity (n.)"],"synonyms":["fierce","savage"],"antonyms":["gentle"],"tipVi":"Có thể dùng để miêu tả động vật hung dữ hoặc dùng cho cạnh tranh, bão tố dữ dội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clam', 'en-c1-18', 'clam', '/klæm/', 'C1', 'con ngêu; con sò; con trai', 'n.', 'clamming (n.)', NULL, 'Clam là con ngêu/sò; cần tránh nhầm lẫn với từ calm có nghĩa là bình tĩnh.', 'We found a clam buried in the wet sand.', NULL, 'Chúng tôi tìm thấy một con ngêu vùi sâu dưới lớp cát ẩm.', '{"wordId":"clam","ukIpa":"/klæm/","usIpa":"/klæm/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A shellfish with two joined shells, often living buried in sand.","vi":"con ngêu; con sò; con trai"}],"examples":[{"en":"We found a clam buried in the wet sand.","vi":"Chúng tôi tìm thấy một con ngêu vùi sâu dưới lớp cát ẩm.","audioKind":"ex"},{"en":"Clam farming can support coastal economies, but poor water quality may threaten both shellfish and consumers.","vi":"Nghề nuôi ngêu có thể hỗ trợ nền kinh tế vùng ven biển, nhưng chất lượng nước kém có thể đe dọa đến cả loài nhuyễn thể lẫn người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"clam shell","vi":"vỏ ngêu"},{"en":"clam chowder","vi":"súp kem ngêu"},{"en":"clam farming","vi":"nghề nuôi ngêu"}],"wordFamily":["clamming (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Clam là con ngêu/sò; cần tránh nhầm lẫn với từ calm có nghĩa là bình tĩnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_herbivorous', 'en-c1-18', 'herbivorous', '/hɝːˈbɪvərəs/', 'C1', 'ăn thực vật; ăn cỏ', 'adj.', 'herbivore (n.), herbivory (n.)', 'Đồng nghĩa: plant-eating · Trái nghĩa: carnivorous', 'không chỉ ăn cỏ mà còn bao gồm việc ăn lá cây, quả và các loại thực vật khác.', 'These herbivorous lizards enjoy fresh leaves from our garden.', NULL, 'Những con thằn lằn ăn cỏ này rất thích những chiếc lá tươi từKhu vườn của chúng tôi.', '{"wordId":"herbivorous","ukIpa":"/hɜːˈbɪvərəs/","usIpa":"/hɝːˈbɪvərəs/","cefr":"C1","topic":"nature","senses":[{"pos":"adj.","en":"feeding on plants rather than other animals","vi":"ăn thực vật; ăn cỏ"}],"examples":[{"en":"These herbivorous lizards enjoy fresh leaves from our garden.","vi":"Những con thằn lằn ăn cỏ này rất thích những chiếc lá tươi từKhu vườn của chúng tôi.","audioKind":"ex"},{"en":"Herbivorous animals influence forest growth by consuming young plants and spreading seeds through their droppings.","vi":"Động vật ăn cỏ ảnh hưởng đến sự phát triển của rừng bằng cách ăn các chồi cây non và phát tán hạt giống qua phân của chúng.","audioKind":"ex2"}],"collocations":[{"en":"herbivorous animals","vi":"động vật ăn cỏ"},{"en":"herbivorous mammals","vi":"thú ăn cỏ"},{"en":"herbivorous species","vi":"các loài ăn cỏ"}],"wordFamily":["herbivore (n.)","herbivory (n.)"],"synonyms":["plant-eating"],"antonyms":["carnivorous"],"tipVi":"không chỉ ăn cỏ mà còn bao gồm việc ăn lá cây, quả và các loại thực vật khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reed', 'en-c1-18', 'reed', '/riːd/', 'C1', 'loài cỏ mọc ở vùng nước có thân cứng; cây sậy, ống sậy; một tấm mỏng dao động để tạo ra âm thanh ở một số nhạc cụ; lưỡi gà', 'n.', 'reedy (adj.)', NULL, 'Phát âm giống hệt từ read dạng nguyên thể; cũng dùng để chỉ bộ phận rung tạo âm thanh trong nhạc cụ.', 'A small bird balanced on a reed beside the pond.', NULL, 'Một chú chim nhỏ đậu vững vàng trên một cành sậy bên cạnh ao.', '{"wordId":"reed","ukIpa":"/riːd/","usIpa":"/riːd/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A tall grass with stiff stems growing near water","vi":"loài cỏ mọc ở vùng nước có thân cứng; cây sậy, ống sậy"},{"pos":"n.","en":"A thin strip that vibrates to produce sound in certain instruments","vi":"một tấm mỏng dao động để tạo ra âm thanh ở một số nhạc cụ; lưỡi gà"}],"examples":[{"en":"A small bird balanced on a reed beside the pond.","vi":"Một chú chim nhỏ đậu vững vàng trên một cành sậy bên cạnh ao.","audioKind":"ex"},{"en":"Reed beds provide shelter for wetland wildlife and can help remove pollutants from water flowing through them.","vi":"Các bãi sậy cung cấp nơi trú ẩn cho động vật hoang dã vùng đất ngập nước và có thể giúp loại bỏ các chất ô nhiễm khỏi nguồn nước chảy qua chúng.","audioKind":"ex2"}],"collocations":[{"en":"reed bed","vi":"bãi sậy"},{"en":"reed warbler","vi":"chim sậy"},{"en":"clarinet reed","vi":"lưỡi gà kèn clarinet"}],"wordFamily":["reedy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Phát âm giống hệt từ read dạng nguyên thể; cũng dùng để chỉ bộ phận rung tạo âm thanh trong nhạc cụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tremor', 'en-c1-18', 'tremor', '/ˈtremər/', 'C1', 'cơn địa chấn nhẹ; sự rung lắc; sự run rẩy; cơn rùng mình', 'n.', 'tremulous (adj.), tremulously (adv.)', 'Đồng nghĩa: shaking, quiver', 'Thường dùng làm danh từ; sự run rẩy trong giọng nói dùng a tremor in the voice.', 'A slight tremor made the cups rattle on their hooks.', NULL, 'Một cơn rung nhẹ làm những chiếc cốc trên móc va vào nhau lách cách.', '{"wordId":"tremor","ukIpa":"/ˈtremə/","usIpa":"/ˈtremər/","cefr":"C1","topic":"nature","senses":[{"pos":"n.","en":"A small earthquake or a brief shaking movement.","vi":"cơn địa chấn nhẹ; sự rung lắc"},{"pos":"n.","en":"An involuntary shaking of the body or voice.","vi":"sự run rẩy; cơn rùng mình"}],"examples":[{"en":"A slight tremor made the cups rattle on their hooks.","vi":"Một cơn rung nhẹ làm những chiếc cốc trên móc va vào nhau lách cách.","audioKind":"ex"},{"en":"Sensitive monitoring equipment can detect a minor tremor that people living nearby may not notice.","vi":"Thiết bị giám sát nhạy bén có thể phát hiện ra một cơn địa chấn nhỏ mà người dân sống gần đó có thể không nhận thấy.","audioKind":"ex2"}],"collocations":[{"en":"earth tremor","vi":"cơn địa chấn nhẹ"},{"en":"hand tremor","vi":"chứng run tay"},{"en":"a tremor in her voice","vi":"giọng nói run rẩy của cô ấy"}],"wordFamily":["tremulous (adj.)","tremulously (adv.)"],"synonyms":["shaking","quiver"],"antonyms":[],"tipVi":"Thường dùng làm danh từ; sự run rẩy trong giọng nói dùng a tremor in the voice.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flutter', 'en-c1-18', 'flutter', '/ˈflʌtər/', 'C1', 'bay phấp phới; vỗ cánh; rung rinh; chập chờn; sự chuyển động nhẹ nhàng; sự hồi hộp; nhịp đập nhanh bất thường', 'v.', NULL, 'Đồng nghĩa: flap, quiver', 'Nhấn mạnh chuyển động lặp đi lặp lại nhẹ nhàng và nhanh chóng, có thể dùng cho cánh, vải vóc hoặc nhịp đập của tim.', 'The curtains fluttered gently beside the open kitchen window.', NULL, 'Những chiếc rèm cửa bay phấp phới nhẹ nhàng bên cửa sổ nhà bếp đang mở.', '{"wordId":"flutter","ukIpa":"/ˈflʌtə/","usIpa":"/ˈflʌtər/","cefr":"C1","topic":"nature","senses":[{"pos":"v.","en":"Move with quick, light movements, especially through air","vi":"bay phấp phới; vỗ cánh; rung rinh; chập chờn"},{"pos":"n.","en":"A quick, light movement or brief uneven heartbeat","vi":"sự chuyển động nhẹ nhàng; sự hồi hộp; nhịp đập nhanh bất thường"}],"examples":[{"en":"The curtains fluttered gently beside the open kitchen window.","vi":"Những chiếc rèm cửa bay phấp phới nhẹ nhàng bên cửa sổ nhà bếp đang mở.","audioKind":"ex"},{"en":"Butterflies flutter among native flowers in urban gardens, demonstrating how small green spaces can support biodiversity.","vi":"Những chú bướm bay lượn giữa các loài hoa bản địa trong các khu vườn đô thị, minh chứng cho việc các mảng xanh nhỏ có thể hỗ trợ sự đa dạng sinh học ra sao.","audioKind":"ex2"}],"collocations":[{"en":"flutter in the breeze","vi":"bay phấp phới trong gió nhẹ"},{"en":"flutter its wings","vi":"vỗ cánh"},{"en":"a flutter of excitement","vi":"một thoáng hào hứng"}],"wordFamily":[],"synonyms":["flap","quiver"],"antonyms":[],"tipVi":"Nhấn mạnh chuyển động lặp đi lặp lại nhẹ nhàng và nhanh chóng, có thể dùng cho cánh, vải vóc hoặc nhịp đập của tim.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_18_1', 'en-c1-18', 'Cách dùng “hind” (adj.) — ở phía sau; phần sau', 'hind legs  ·  hind feet  ·  hind limbs', 'Khi là tính từ, từ này chủ yếu bổ nghĩa cho phần chân hoặc chi của động vật, không dùng để chỉ chung các sự vật phía sau.', 'Họ từ (Word Family): hindquarters (n.) | Đồng nghĩa: rear · Trái nghĩa: front', '[{"hanzi":"The rabbit pushed off with its powerful hind legs.","pinyin":"","meaning":"Con thỏ dùng đôi chân sau đầy sức mạnh để bật nhảy đi."},{"hanzi":"Kangaroos rely on their strong hind legs to travel efficiently across large areas in search of food.","pinyin":"","meaning":"Loài chuột túi dựa vào đôi chân sau khỏe mạnh để di chuyển hiệu quả trên những khoảng đất rộng lớn nhằm tìm kiếm thức ăn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_18_2', 'en-c1-18', 'Cách dùng “flutter” (v.) — bay phấp phới; vỗ cánh; rung rinh; chập chờn', 'flutter in the breeze  ·  flutter its wings  ·  a flutter of excitement', 'Nhấn mạnh chuyển động lặp đi lặp lại nhẹ nhàng và nhanh chóng, có thể dùng cho cánh, vải vóc hoặc nhịp đập của tim.', 'Đồng nghĩa: flap, quiver', '[{"hanzi":"The curtains fluttered gently beside the open kitchen window.","pinyin":"","meaning":"Những chiếc rèm cửa bay phấp phới nhẹ nhàng bên cửa sổ nhà bếp đang mở."},{"hanzi":"Butterflies flutter among native flowers in urban gardens, demonstrating how small green spaces can support biodiversity.","pinyin":"","meaning":"Những chú bướm bay lượn giữa các loài hoa bản địa trong các khu vườn đô thị, minh chứng cho việc các mảng xanh nhỏ có thể hỗ trợ sự đa dạng sinh học ra sao."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_18_3', 'en-c1-18', 'Cách dùng “migratory” (adj.) — có tính chất di cư; thích di trú', 'migratory birds  ·  migratory species  ·  migratory routes', 'Thường dùng để mô tả sự di chuyển theo mùa của các loài chim, không giống với việc lang thang không mục đích.', 'Họ từ (Word Family): migrate (v.), migration (n.), migrant (n.)', '[{"hanzi":"Migratory birds gather by the lake every spring.","pinyin":"","meaning":"Chim di cư tụ tập bên hồ vào mỗi mùa xuân."},{"hanzi":"Protecting wetlands along migratory routes is essential because many bird species depend on these habitats for food and rest.","pinyin":"","meaning":"Việc bảo vệ các vùng đất ngập nước dọc theo các tuyến đường di cư là rất quan trọng vì nhiều loài chim phụ thuộc vào các sinh cảnh này để kiếm ăn và nghỉ ngơi."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_18_4', 'en-c1-18', 'Cách dùng “indigenous” (adj.) — bản địa; thuộc về người bản xứ', 'indigenous peoples  ·  indigenous languages  ·  indigenous species', 'Thường đi với giới từ indigenous to; khi dùng để chỉ cộng đồng người, chữ cái đầu tiên thường được viết hoa.', 'Đồng nghĩa: native · Trái nghĩa: non-native', '[{"hanzi":"These flowers are indigenous to the valley near our village.","pinyin":"","meaning":"Những loài hoa này mọc hoang dã và có nguồn gốc từ thung lũng gần làng chúng tôi."},{"hanzi":"Protecting indigenous languages helps preserve cultural knowledge that has been passed down through many generations.","pinyin":"","meaning":"Việc bảo vệ các ngôn ngữ bản địa góp phần gìn giữ những tri thức văn hóa đã được lưu truyền qua nhiều thế hệ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_18_1', 'en-c1-18', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_1_1', 'ten_c1_18_1', 'mighty', 'A mighty oak stood in the middle of the field.', 'A mighty oak stood in the middle of the field.', '/ˈmaɪti/', 'Một cây sồi khổng lồ sừng sững ở giữa cánh đồng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_1_2', 'ten_c1_18_1', 'falcon', 'A falcon circled above the cliffs this morning.', 'A falcon circled above the cliffs this morning.', '/ˈfælkən/', 'Sáng nay một con chim ưng bay lượn vòng phía trên các vách đá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_1_3', 'ten_c1_18_1', 'kernel', 'She cracked the walnut and carefully removed the kernel.', 'She cracked the walnut and carefully removed the kernel.', '/ˈkɝːnəl/', 'Cô ấy đập vỡ quả óc chó và cẩn thận lấy phần nhân bên trong ra.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_1_4', 'ten_c1_18_1', 'abound', 'Wildflowers abound in the fields behind our house each spring.', 'Wildflowers abound in the fields behind our house each spring.', '/əˈbaʊnd/', 'Hoa dại mọc đầy trên các cánh đồng phía sau ngôi nhà của chúng tôi vào mỗi mùa xuân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_1_5', 'ten_c1_18_1', 'meadow', 'We spread our picnic blanket in a sunny meadow.', 'We spread our picnic blanket in a sunny meadow.', '/ˈmedoʊ/', 'Chúng tôi trải thảm dã ngoại trên một bãi cỏ ngập tràn ánh nắng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_1_6', 'ten_c1_18_1', 'lash', 'Heavy rain lashed the windows throughout the night.', 'Heavy rain lashed the windows throughout the night.', '/læʃ/', 'Cơn mưa lớn quất xối xả vào các ô cửa sổ suốt cả đêm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_1_7', 'ten_c1_18_1', 'indigenous', 'These flowers are indigenous to the valley near our village.', 'These flowers are indigenous to the valley near our village.', '/ɪnˈdɪdʒənəs/', 'Những loài hoa này mọc hoang dã và có nguồn gốc từ thung lũng gần làng chúng tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_1_8', 'ten_c1_18_1', 'cluster', 'A cluster of purple flowers grew beside the gate.', 'A cluster of purple flowers grew beside the gate.', '/ˈklʌstər/', 'Một cụm hoa màu tím mọc ở bên cạnh cổng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_18_1_1', 'en-c1-18', 'ten_c1_18_1', 'listening', 'listening', 'A mighty oak stood in the middle of the field.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một chú chim nhỏ đậu vững vàng trên một cành sậy bên cạnh ao.","Hoa dại mọc đầy trên các cánh đồng phía sau ngôi nhà của chúng tôi vào mỗi mùa xuân.","Con thỏ dùng đôi chân sau đầy sức mạnh để bật nhảy đi.","Một cây sồi khổng lồ sừng sững ở giữa cánh đồng."]'::jsonb, 3, 'A mighty oak stood in the middle of the field. → Một cây sồi khổng lồ sừng sững ở giữa cánh đồng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_18_1_2', 'en-c1-18', 'ten_c1_18_1', 'listening', 'listening', 'A falcon circled above the cliffs this morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sáng nay một con chim ưng bay lượn vòng phía trên các vách đá.","Những loài hoa này mọc hoang dã và có nguồn gốc từ thung lũng gần làng chúng tôi.","Một cơn rung nhẹ làm những chiếc cốc trên móc va vào nhau lách cách.","Con thỏ dùng đôi chân sau đầy sức mạnh để bật nhảy đi."]'::jsonb, 0, 'A falcon circled above the cliffs this morning. → Sáng nay một con chim ưng bay lượn vòng phía trên các vách đá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_18_1_3', 'en-c1-18', 'ten_c1_18_1', 'listening', 'listening', 'She cracked the walnut and carefully removed the kernel.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy nhẹ nhàng chải bờm cho chú ngựa pony trước khi cưỡi.","Một chú chim nhỏ đậu vững vàng trên một cành sậy bên cạnh ao.","Chúng tôi đứng lặng im, ngỡ ngàng trước vẻ hùng vĩ của những ngọn núi.","Cô ấy đập vỡ quả óc chó và cẩn thận lấy phần nhân bên trong ra."]'::jsonb, 3, 'She cracked the walnut and carefully removed the kernel. → Cô ấy đập vỡ quả óc chó và cẩn thận lấy phần nhân bên trong ra.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_18_2', 'en-c1-18', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_2_1', 'ten_c1_18_2', 'mighty', 'Although mighty rivers provide valuable renewable energy, building large dams can seriously disrupt surrounding ecosystems.', 'Although mighty rivers provide valuable renewable energy, building large dams can seriously disrupt surrounding ecosystems.', '/ˈmaɪti/', 'Mặc dù những dòng sông lớn cung cấp năng lượng tái tạo quý giá, việc xây dựng các con đập lớn có thể phá vỡ nghiêm trọng hệ sinh thái xung quanh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_2_2', 'ten_c1_18_2', 'falcon', 'Protecting cliff habitats can help falcon populations recover in regions where suitable nesting sites have disappeared.', 'Protecting cliff habitats can help falcon populations recover in regions where suitable nesting sites have disappeared.', '/ˈfælkən/', 'Bảo vệ môi trường sống trên vách đá có thể giúp phục hồi các quần thể chim ưng ở những khu vực mà các vị trí làm tổ thích hợp đã biến mất.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_2_3', 'ten_c1_18_2', 'kernel', 'Even exaggerated media reports may contain a kernel of truth that deserves further investigation by independent researchers.', 'Even exaggerated media reports may contain a kernel of truth that deserves further investigation by independent researchers.', '/ˈkɝːnəl/', 'Ngay cả những bản tin bị thổi phồng cũng có thể chứa một chút sự thật đáng để các nhà nghiên cứu độc lập điều tra thêm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_2_4', 'ten_c1_18_2', 'abound', 'Opportunities for renewable energy development abound in regions with consistent sunshine and strong coastal winds.', 'Opportunities for renewable energy development abound in regions with consistent sunshine and strong coastal winds.', '/əˈbaʊnd/', 'Cơ hội phát triển năng lượng tái tạo rất phong phú ở những vùng có ánh nắng ổn định và gió ven biển mạnh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_2_5', 'ten_c1_18_2', 'meadow', 'Protecting wildflower meadows helps maintain biodiversity by providing food and shelter for insects and birds.', 'Protecting wildflower meadows helps maintain biodiversity by providing food and shelter for insects and birds.', '/ˈmedoʊ/', 'Bảo vệ các đồng cỏ hoa dại giúp duy trì sự đa dạng sinh học bằng cách cung cấp thức ăn và nơi trú ẩn cho côn trùng và loài chim.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_18_2_6', 'ten_c1_18_2', 'lash', 'As storms lash coastal communities, stronger sea defences become increasingly important for protecting homes and essential infrastructure.', 'As storms lash coastal communities, stronger sea defences become increasingly important for protecting homes and essential infrastructure.', '/læʃ/', 'Khi bão quất mạnh vào các cộng đồng ven biển, các hệ thống phòng thủ biển kiên cố hơn ngày càng trở nên quan trọng trong việc bảo vệ nhà cửa và cơ sở hạ tầng thiết yếu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_18_2_1', 'en-c1-18', 'ten_c1_18_2', 'listening', 'listening', 'Although mighty rivers provide valuable renewable energy, building large dams can seriously disrupt surrounding ecosystems.', NULL, 'Trong câu vừa nghe, từ “mighty” mang nghĩa nào sau đây?', '["hùng mạnh; to lớn","hệ thống thuế; việc thu thuế; thuế khóa","dầu hỏa; dầu hôi","hiệp định; hiệp ước"]'::jsonb, 0, '“mighty” (/ˈmaɪti/): hùng mạnh; to lớn. Câu đầy đủ: Although mighty rivers provide valuable renewable energy, building large dams can seriously disrupt surrounding ecosystems.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_18_2_2', 'en-c1-18', 'ten_c1_18_2', 'listening', 'listening', 'Protecting cliff habitats can help falcon populations recover in regions where suitable nesting sites have disappeared.', NULL, 'Trong câu vừa nghe, từ “falcon” mang nghĩa nào sau đây?', '["vết màu phớt; chút ít (màu sắc, cảm xúc)","lịch sự; nhã nhặn; có phép tắc","rõ ràng; dễ đọc; dễ nhận biết","con chim ưng; con ưng"]'::jsonb, 3, '“falcon” (/ˈfælkən/): con chim ưng; con ưng. Câu đầy đủ: Protecting cliff habitats can help falcon populations recover in regions where suitable nesting sites have disappeared.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
