INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_2', 'en-c1-18', NULL, 'comprehensive_test', 'listening', 'A falcon circled above the cliffs this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con chó dữ gầm gừ phía sau cánh cổng đã khóa.","Sáng nay một con chim ưng bay lượn vòng phía trên các vách đá.","Những hàng cây cao vây quanh cái ao nhỏ phía sau nhà chúng tôi.","Một cơn rung nhẹ làm những chiếc cốc trên móc va vào nhau lách cách."]'::jsonb, 1, 'A falcon circled above the cliffs this morning. → Sáng nay một con chim ưng bay lượn vòng phía trên các vách đá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
