INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_4', 'en-c1-18', NULL, 'comprehensive_test', 'listening', 'Wildflowers abound in the fields behind our house each spring.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hoa dại mọc đầy trên các cánh đồng phía sau ngôi nhà của chúng tôi vào mỗi mùa xuân.","Một cụm hoa màu tím mọc ở bên cạnh cổng.","Những con thằn lằn ăn cỏ này rất thích những chiếc lá tươi từKhu vườn của chúng tôi.","Chúng tôi trải thảm dã ngoại trên một bãi cỏ ngập tràn ánh nắng."]'::jsonb, 0, 'Wildflowers abound in the fields behind our house each spring. → Hoa dại mọc đầy trên các cánh đồng phía sau ngôi nhà của chúng tôi vào mỗi mùa xuân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_5', 'en-c1-18', NULL, 'comprehensive_test', 'listening', 'meadow', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bãi cỏ, đồng cỏ (thường có hoa dại)","chất polymer; hợp chất cao phân tử","sách giới thiệu tuyển sinh; tài liệu tuyển sinh (mô tả về trường học hoặc đại học dành cho học sinh, sinh viên tiềm năng)","thuộc về lợi nhuận cuối cùng; liên quan đến kết quả tài chính cốt lõi"]'::jsonb, 0, 'meadow (/ˈmedoʊ/) → bãi cỏ, đồng cỏ (thường có hoa dại)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_6', 'en-c1-18', NULL, 'comprehensive_test', 'listening', 'Heavy rain lashed the windows throughout the night.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi tìm thấy một con ngêu vùi sâu dưới lớp cát ẩm.","Chiếc xe tải chở quặng sắt chạy dọc con đường bụi bặm.","Cơn mưa lớn quất xối xả vào các ô cửa sổ suốt cả đêm.","Sáng nay một con chim ưng bay lượn vòng phía trên các vách đá."]'::jsonb, 2, 'Heavy rain lashed the windows throughout the night. → Cơn mưa lớn quất xối xả vào các ô cửa sổ suốt cả đêm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_7', 'en-c1-18', NULL, 'comprehensive_test', 'listening', 'indigenous', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cái cớ; lý do thoái thác","phân tán; giải tán","chủ nghĩa đế quốc; chính sách bành trướng đế quốc","bản địa; thuộc về người bản xứ"]'::jsonb, 3, 'indigenous (/ɪnˈdɪdʒənəs/) → bản địa; thuộc về người bản xứ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_8', 'en-c1-18', NULL, 'comprehensive_test', 'listening', 'A cluster of purple flowers grew beside the gate.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một cụm hoa màu tím mọc ở bên cạnh cổng.","Một chú chim nhỏ đậu vững vàng trên một cành sậy bên cạnh ao.","Chúng tôi trải thảm dã ngoại trên một bãi cỏ ngập tràn ánh nắng.","Chiếc xe tải chở quặng sắt chạy dọc con đường bụi bặm."]'::jsonb, 0, 'A cluster of purple flowers grew beside the gate. → Một cụm hoa màu tím mọc ở bên cạnh cổng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_9', 'en-c1-18', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a field of grass, often containing wildflowers”?', '["flutter","meadow","hind","abundance"]'::jsonb, 1, 'meadow (/ˈmedoʊ/) → bãi cỏ, đồng cỏ (thường có hoa dại)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_10', 'en-c1-18', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To strike forcefully, especially with a whip or like one.”?', '["lash","avalanche","indigenous","encircle"]'::jsonb, 0, 'lash (/læʃ/) → quất; đánh mạnh', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_11', 'en-c1-18', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Originating or living naturally in a place, rather than arriving later.”?', '["mane","indigenous","earthworm","clam"]'::jsonb, 1, 'indigenous (/ɪnˈdɪdʒənəs/) → bản địa; thuộc về người bản xứ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_12', 'en-c1-18', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a group of similar things positioned or occurring close together”?', '["ore","falcon","cluster","majesty"]'::jsonb, 2, 'cluster (/ˈklʌstər/) → búi; cụm; đám; nhóm', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
