INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_18', 'en-c1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Although mighty rivers provide valuable renewable energy, building large dams can seriously disrupt surrounding ecosystems.', 'Dựa vào câu trên, từ “mighty” có nghĩa phù hợp nhất là gì?', '["hùng mạnh; to lớn","khu phố đi bộ mua sắm","là đặc điểm của; tiêu biểu cho","thiếu thốn; không đủ (những thứ cần thiết)"]'::jsonb, 0, 'mighty: hùng mạnh; to lớn; rất; cực kỳ. Dịch cả câu: Mặc dù những dòng sông lớn cung cấp năng lượng tái tạo quý giá, việc xây dựng các con đập lớn có thể phá vỡ nghiêm trọng hệ sinh thái xung quanh.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_19', 'en-c1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Protecting cliff habitats can help falcon populations recover in regions where suitable nesting sites have disappeared.', 'Dựa vào câu trên, từ “falcon” có nghĩa phù hợp nhất là gì?', '["né tránh; lảng tránh (để không bị va chạm)","con chim ưng; con ưng","nhấp nháy; lấp lánh","bán trong suốt; cho ánh sáng xuyên qua nhưng không nhìn rõ vật bên trong"]'::jsonb, 1, 'falcon: con chim ưng; con ưng. Dịch cả câu: Bảo vệ môi trường sống trên vách đá có thể giúp phục hồi các quần thể chim ưng ở những khu vực mà các vị trí làm tổ thích hợp đã biến mất.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_20', 'en-c1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Even exaggerated media reports may contain a kernel of truth that deserves further investigation by independent researchers.', 'Dựa vào câu trên, từ “kernel” có nghĩa phù hợp nhất là gì?', '["ký sinh trùng; sinh vật ký sinh","nhấp nháy; lấp lánh","là ví dụ điển hình cho; minh họa bằng ví dụ","nhân (hạt); hạt (ngũ cốc)"]'::jsonb, 3, 'kernel: nhân (hạt); hạt (ngũ cốc); cốt lõi; phần quan trọng nhất của cái gì đó; nhân hệ điều hành. Dịch cả câu: Ngay cả những bản tin bị thổi phồng cũng có thể chứa một chút sự thật đáng để các nhà nghiên cứu độc lập điều tra thêm.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_21', 'en-c1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Opportunities for renewable energy development abound in regions with consistent sunshine and strong coastal winds.', 'Dựa vào câu trên, từ “abound” có nghĩa phù hợp nhất là gì?', '["có rất nhiều; phong phú; ngập tràn","có thể chuyển nhượng; có thể chuyển giao","người ngoại đạo; người không chuyên môn","rượu mạnh branti; rượu brandy"]'::jsonb, 0, 'abound: có rất nhiều; phong phú; ngập tràn. Dịch cả câu: Cơ hội phát triển năng lượng tái tạo rất phong phú ở những vùng có ánh nắng ổn định và gió ven biển mạnh.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_22', 'en-c1-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “loài cỏ mọc ở vùng nước có thân cứng; cây sậy, ống sậy”', '["navigable","hierarchy","reed","municipal"]'::jsonb, 2, 'loài cỏ mọc ở vùng nước có thân cứng; cây sậy, ống sậy → reed (/riːd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_23', 'en-c1-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cơn địa chấn nhẹ; sự rung lắc”', '["sly","proficiency","tremor","savage"]'::jsonb, 2, 'cơn địa chấn nhẹ; sự rung lắc → tremor (/ˈtremər/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_18_24', 'en-c1-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bay phấp phới; vỗ cánh; rung rinh; chập chờn”', '["flutter","cynical","dub","profound"]'::jsonb, 0, 'bay phấp phới; vỗ cánh; rung rinh; chập chờn → flutter (/ˈflʌtər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-19', 'en', 'Bài 19: Môi trường & Sinh thái (1) - CEFR C1', 'CEFR C1', 'C1 · Môi trường', '25 từ vựng Tiếng Anh CEFR C1 chủ đề môi trường & sinh thái kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5019, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_irrigation', 'en-c1-19', 'irrigation', '/ˌɪrɪˈɡeɪʃən/', 'C1', 'sự tưới tiêu; hệ thống tưới tiêu', 'n.', 'irrigate (v.), irrigated (adj.)', NULL, 'Thường là danh từ không đếm được; động từ tương ứng là irrigate.', 'The farm''s irrigation system keeps these vegetables growing.', NULL, 'Hệ thống tưới tiêu của trang trại giúp duy trì sự phát triển của những luống rau này.', '{"wordId":"irrigation","ukIpa":"/ˌɪrɪˈɡeɪʃən/","usIpa":"/ˌɪrɪˈɡeɪʃən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"The supply of water to land so crops can grow.","vi":"sự tưới tiêu; hệ thống tưới tiêu"}],"examples":[{"en":"The farm''s irrigation system keeps these vegetables growing.","vi":"Hệ thống tưới tiêu của trang trại giúp duy trì sự phát triển của những luống rau này.","audioKind":"ex"},{"en":"Efficient irrigation can increase crop yields while reducing water consumption in regions affected by drought.","vi":"Hệ thống tưới tiêu hiệu quả có thể làm tăng năng suất cây trồng đồng thời giảm lượng nước tiêu thụ ở các khu vực chịu ảnh hưởng bởi hạn hán.","audioKind":"ex2"}],"collocations":[{"en":"irrigation system","vi":"hệ thống tưới tiêu"},{"en":"drip irrigation","vi":"tưới nhỏ giọt"},{"en":"irrigation canal","vi":"mương dẫn nước"},{"en":"irrigation water","vi":"nước tưới tiêu"}],"wordFamily":["irrigate (v.)","irrigated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; động từ tương ứng là irrigate.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hydroelectric', 'en-c1-19', 'hydroelectric', '/ˌhaɪdroʊɪˈlektrɪk/', 'C1', 'thuộc về thủy điện; liên quan đến thủy điện', 'adj.', 'hydroelectricity (n.)', NULL, 'Thường bổ nghĩa cho power hoặc power station; danh từ của nó là hydroelectricity.', 'We visited a hydroelectric dam during our mountain holiday.', NULL, 'Chúng tôi đã tham quan một đập thủy điện trong chuyến nghỉ mát trên núi.', '{"wordId":"hydroelectric","ukIpa":"/ˌhaɪdrəʊɪˈlektrɪk/","usIpa":"/ˌhaɪdroʊɪˈlektrɪk/","cefr":"C1","topic":"environment","senses":[{"pos":"adj.","en":"Relating to electricity produced by the movement of water.","vi":"thuộc về thủy điện; liên quan đến thủy điện"}],"examples":[{"en":"We visited a hydroelectric dam during our mountain holiday.","vi":"Chúng tôi đã tham quan một đập thủy điện trong chuyến nghỉ mát trên núi.","audioKind":"ex"},{"en":"Hydroelectric power can reduce dependence on fossil fuels, although large dams may disrupt river ecosystems.","vi":"Năng lượng thủy điện có thể làm giảm sự phụ thuộc vào nhiên liệu hóa thạch, mặc dù các con đập lớn có thể phá vỡ hệ sinh thái sông ngòi.","audioKind":"ex2"}],"collocations":[{"en":"hydroelectric power","vi":"năng lượng thủy điện"},{"en":"hydroelectric dam","vi":"đập thủy điện"},{"en":"hydroelectric power station","vi":"trạm phát điện thủy điện"}],"wordFamily":["hydroelectricity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường bổ nghĩa cho power hoặc power station; danh từ của nó là hydroelectricity.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reclaim', 'en-c1-19', 'reclaim', '/rɪˈkleɪm/', 'C1', 'lấy lại; đòi lại; thu hồi; khai khẩn; cải tạo (đất bị hỏng hoặc ngập nước để sử dụng); tái chế; thu hồi nguyên vật liệu từ rác thải', 'v.', 'reclamation (n.), reclaimed (adj.)', NULL, 'Động từ reclaim nhấn mạnh ý nghĩa lấy lại hoặc khôi phục để sử dụng, không đơn thuần chỉ là thu gom.', 'I returned to the station to reclaim my suitcase.', NULL, 'Tôi đã quay lại nhà ga để nhận lại chiếc vali của mình.', '{"wordId":"reclaim","ukIpa":"/rɪˈkleɪm/","usIpa":"/rɪˈkleɪm/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"Get back something that belongs or previously belonged to you","vi":"lấy lại; đòi lại; thu hồi"},{"pos":"v.","en":"Make damaged or submerged land suitable for use","vi":"khai khẩn; cải tạo (đất bị hỏng hoặc ngập nước để sử dụng)"},{"pos":"v.","en":"Recover useful materials from waste for reuse","vi":"tái chế; thu hồi nguyên vật liệu từ rác thải"}],"examples":[{"en":"I returned to the station to reclaim my suitcase.","vi":"Tôi đã quay lại nhà ga để nhận lại chiếc vali của mình.","audioKind":"ex"},{"en":"Coastal cities sometimes reclaim land from the sea to create space for housing and transport.","vi":"Các thành phố ven biển đôi khi tiến hành lấn biển để tạo ra quỹ đất cho nhà ở và giao thông.","audioKind":"ex2"}],"collocations":[{"en":"reclaim lost property","vi":"nhận lại tài sản thất lạc"},{"en":"reclaim land","vi":"khai khẩn đất hoang; lấn biển"},{"en":"reclaim materials","vi":"tái chế vật liệu"}],"wordFamily":["reclamation (n.)","reclaimed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ reclaim nhấn mạnh ý nghĩa lấy lại hoặc khôi phục để sử dụng, không đơn thuần chỉ là thu gom.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vulnerability', 'en-c1-19', 'vulnerability', '/ˌvʌlnərəˈbɪləti/', 'C1', 'tính dễ bị tổn thương; tính dễ bị tác động; điểm yếu; lỗ hổng bảo mật', 'n.', 'vulnerable (adj.), invulnerable (adj.), invulnerability (n.)', 'Đồng nghĩa: susceptibility, weakness · Trái nghĩa: invulnerability', 'Không đếm được khi chỉ tính chất dễ bị tổn thương nói chung; đếm được khi chỉ các điểm yếu hoặc lỗ hổng cụ thể.', 'The storm exposed the vulnerability of our old roof.', NULL, 'Cơn bão đã phơi bày sự xuống cấp và dễ tổn thương của mái nhà cũ chúng tôi.', '{"wordId":"vulnerability","ukIpa":"/ˌvʌlnərəˈbɪləti/","usIpa":"/ˌvʌlnərəˈbɪləti/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"The state of being easily harmed, affected, or attacked.","vi":"tính dễ bị tổn thương; tính dễ bị tác động"},{"pos":"n.","en":"A weakness that allows damage or an attack.","vi":"điểm yếu; lỗ hổng bảo mật"}],"examples":[{"en":"The storm exposed the vulnerability of our old roof.","vi":"Cơn bão đã phơi bày sự xuống cấp và dễ tổn thương của mái nhà cũ chúng tôi.","audioKind":"ex"},{"en":"Investing in flood defences can reduce the vulnerability of coastal communities to increasingly severe storms.","vi":"Đầu tư vào các công trình phòng chống lũ lụt có thể làm giảm tính dễ bị tổn thương của các cộng đồng ven biển trước những cơn bão ngày càng tàn khốc.","audioKind":"ex2"}],"collocations":[{"en":"vulnerability to flooding","vi":"tính dễ bị ngập lụt"},{"en":"security vulnerability","vi":"lỗ hổng bảo mật"},{"en":"reduce vulnerability","vi":"giảm thiểu tính dễ bị tổn thương"}],"wordFamily":["vulnerable (adj.)","invulnerable (adj.)","invulnerability (n.)"],"synonyms":["susceptibility","weakness"],"antonyms":["invulnerability"],"tipVi":"Không đếm được khi chỉ tính chất dễ bị tổn thương nói chung; đếm được khi chỉ các điểm yếu hoặc lỗ hổng cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contaminate', 'en-c1-19', 'contaminate', '/kənˈtæmɪneɪt/', 'C1', 'làm ô nhiễm; làm bẩn', 'v.', 'contamination (n.), contaminant (n.), contaminated (adj.)', 'Đồng nghĩa: pollute · Trái nghĩa: purify', 'Thường dùng cấu trúc be contaminated with để chỉ việc bị nhiễm một chất gì đó.', 'Dirty hands can contaminate food while you cook.', NULL, 'Tay bẩn có thể làm ô nhiễm thức ăn trong lúc bạn nấu nướng.', '{"wordId":"contaminate","ukIpa":"/kənˈtæmɪneɪt/","usIpa":"/kənˈtæmɪneɪt/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"make something dirty or unsafe by adding harmful substances","vi":"làm ô nhiễm; làm bẩn"}],"examples":[{"en":"Dirty hands can contaminate food while you cook.","vi":"Tay bẩn có thể làm ô nhiễm thức ăn trong lúc bạn nấu nướng.","audioKind":"ex"},{"en":"Industrial chemicals can contaminate groundwater, threatening both agricultural production and the health of nearby communities.","vi":"Hóa chất công nghiệp có thể làm ô nhiễm nguồn nước ngầm, đe dọa cả sản xuất nông nghiệp lẫn sức khỏe của các cộng đồng dân cư xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"contaminate drinking water","vi":"làm ô nhiễm nước uống"},{"en":"contaminated food","vi":"thực phẩm bị ô nhiễm"},{"en":"contaminated with chemicals","vi":"bị ô nhiễm hóa chất"}],"wordFamily":["contamination (n.)","contaminant (n.)","contaminated (adj.)"],"synonyms":["pollute"],"antonyms":["purify"],"tipVi":"Thường dùng cấu trúc be contaminated with để chỉ việc bị nhiễm một chất gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hectare', 'en-c1-19', 'hectare', '/ˈhekter/', 'C1', 'héc-ta; công-ta (đơn vị diện tích bằng 10.000 mét vuông)', 'n.', NULL, NULL, 'Hectare là đơn vị đo diện tích; một héc-ta tương đương mười nghìn mét vuông.', 'Their vegetable farm covers just over a hectare.', NULL, 'Trang trại rau của họ rộng hơn một héc-ta một chút.', '{"wordId":"hectare","ukIpa":"/ˈhekteə/","usIpa":"/ˈhekter/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"a unit of land area equal to ten thousand square metres","vi":"héc-ta; công-ta (đơn vị diện tích bằng 10.000 mét vuông)"}],"examples":[{"en":"Their vegetable farm covers just over a hectare.","vi":"Trang trại rau của họ rộng hơn một héc-ta một chút.","audioKind":"ex"},{"en":"Restoring each hectare of wetland can provide valuable habitats and reduce the risk of local flooding.","vi":"Việc khôi phục mỗi héc-ta đất ngập nước có thể mang lại các sinh cảnh quý giá và giảm nguy cơ lũ lụt ở địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a hectare of land","vi":"một héc-ta đất"},{"en":"per hectare","vi":"mỗi héc-ta"},{"en":"cover several hectares","vi":"rộng vài héc-ta"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Hectare là đơn vị đo diện tích; một héc-ta tương đương mười nghìn mét vuông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incinerator', 'en-c1-19', 'incinerator', '/ɪnˈsɪnəreɪtər/', 'C1', 'lò ốt; lò đốt rác', 'n.', 'incinerate (v.), incineration (n.)', NULL, 'Thường chỉ lò đốt rác; còn lò hỏa táng dùng từ crematorium.', 'The hospital sends certain waste to a special incinerator.', NULL, 'Bệnh viện gửi một số loại rác thải đến lò đốt chuyên dụng.', '{"wordId":"incinerator","ukIpa":"/ɪnˈsɪnəreɪtə/","usIpa":"/ɪnˈsɪnəreɪtər/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"A machine or structure that burns waste at high temperatures","vi":"lò ốt; lò đốt rác"}],"examples":[{"en":"The hospital sends certain waste to a special incinerator.","vi":"Bệnh viện gửi một số loại rác thải đến lò đốt chuyên dụng.","audioKind":"ex"},{"en":"Modern incinerators can generate electricity from waste, but their emissions require strict monitoring to protect public health.","vi":"Các lò đốt rác hiện đại có thể tận dụng rác thải để phát điện, nhưng lượng khí thải của chúng đòi hỏi phải được giám sát nghiêm ngặt để bảo vệ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"waste incinerator","vi":"lò đốt rác thải"},{"en":"industrial incinerator","vi":"lò đốt công nghiệp"},{"en":"incinerator emissions","vi":"khí thải lò đốt"}],"wordFamily":["incinerate (v.)","incineration (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ lò đốt rác; còn lò hỏa táng dùng từ crematorium.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manure', 'en-c1-19', 'manure', '/məˈnʊr/', 'C1', 'phân chuồng; phân bón hữu cơ; bón phân chuồng; rải phân', 'n.', NULL, NULL, 'Danh từ thường không đếm được; fertilizer dùng để chỉ phân bón nói chung với phạm vi rộng hơn.', 'The farmer spread manure around the young apple trees.', NULL, 'Người nông dân rải phân chuồng xung quanh những gốc cây táo non.', '{"wordId":"manure","ukIpa":"/məˈnjʊə/","usIpa":"/məˈnʊr/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"Animal waste used to improve soil and help plants grow.","vi":"phân chuồng; phân bón hữu cơ"},{"pos":"v.","en":"To spread animal waste on land as fertilizer.","vi":"bón phân chuồng; rải phân"}],"examples":[{"en":"The farmer spread manure around the young apple trees.","vi":"Người nông dân rải phân chuồng xung quanh những gốc cây táo non.","audioKind":"ex"},{"en":"Using manure can improve soil fertility, but excessive application may pollute nearby rivers and groundwater.","vi":"Việc sử dụng phân chuồng có thể cải thiện độ phì nhiêu của đất, nhưng bón quá nhiều có thể gây ô nhiễm các dòng sông và nguồn nước ngầm lân cận.","audioKind":"ex2"}],"collocations":[{"en":"animal manure","vi":"phân động vật"},{"en":"spread manure","vi":"rải phân chuồng"},{"en":"well-rotted manure","vi":"phân chuồng hoai mục"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ thường không đếm được; fertilizer dùng để chỉ phân bón nói chung với phạm vi rộng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accumulation', 'en-c1-19', 'accumulation', '/əˌkjuːmjəˈleɪʃən/', 'C1', 'sự tích lũy; sự tích tụ; lượng tích tụ', 'n.', 'accumulate (v.), accumulative (adj.), cumulative (adj.)', 'Đồng nghĩa: buildup', 'Thường đi kèm với giới từ "of", nhấn mạnh sự gia tăng dần theo thời gian.', 'An accumulation of dust covered the old wooden shelves.', NULL, 'Một lớp bụi tích tụ phủ kín những chiếc kệ gỗ cũ.', '{"wordId":"accumulation","ukIpa":"/əˌkjuːmjəˈleɪʃən/","usIpa":"/əˌkjuːmjəˈleɪʃən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"The gradual gathering of something, or the amount gathered.","vi":"sự tích lũy; sự tích tụ; lượng tích tụ"}],"examples":[{"en":"An accumulation of dust covered the old wooden shelves.","vi":"Một lớp bụi tích tụ phủ kín những chiếc kệ gỗ cũ.","audioKind":"ex"},{"en":"The accumulation of plastic waste in oceans threatens marine wildlife and creates lasting challenges for coastal communities.","vi":"Sự tích tụ rác thải nhựa trong đại dương đe dọa động vật hoang dã biển và tạo ra những thách thức lâu dài cho các cộng đồng ven biển.","audioKind":"ex2"}],"collocations":[{"en":"accumulation of wealth","vi":"sự tích lũy tài sản"},{"en":"accumulation of waste","vi":"sự tích tụ rác thải"},{"en":"gradual accumulation","vi":"sự tích lũy dần dần"},{"en":"capital accumulation","vi":"tích lũy tư bản"}],"wordFamily":["accumulate (v.)","accumulative (adj.)","cumulative (adj.)"],"synonyms":["buildup"],"antonyms":[],"tipVi":"Thường đi kèm với giới từ \"of\", nhấn mạnh sự gia tăng dần theo thời gian.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_catastrophe', 'en-c1-19', 'catastrophe', '/kəˈtæstrəfi/', 'C1', 'thảm họa; tai họa', 'n.', 'catastrophic (adj.), catastrophically (adv.)', 'Đồng nghĩa: disaster, calamity', 'Nặng nề hơn từ problem thông thường, thường dùng để chỉ những sự kiện gây thiệt hại nghiêm trọng.', 'The flood was a catastrophe for our small village.', NULL, 'Trận lụt là một thảm họa đối với ngôi làng nhỏ của chúng tôi.', '{"wordId":"catastrophe","ukIpa":"/kəˈtæstrəfi/","usIpa":"/kəˈtæstrəfi/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"an event causing extremely serious damage or suffering","vi":"thảm họa; tai họa"}],"examples":[{"en":"The flood was a catastrophe for our small village.","vi":"Trận lụt là một thảm họa đối với ngôi làng nhỏ của chúng tôi.","audioKind":"ex"},{"en":"Investing in stronger coastal defences could prevent a natural hazard from becoming a humanitarian catastrophe.","vi":"Việc đầu tư vào các công trình phòng thủ bờ biển kiên cố hơn có thể ngăn chặn một hiểm họa thiên nhiên biến thành thảm họa nhân đạo.","audioKind":"ex2"}],"collocations":[{"en":"environmental catastrophe","vi":"thảm họa môi trường"},{"en":"humanitarian catastrophe","vi":"thảm họa nhân đạo"},{"en":"avert a catastrophe","vi":"ngăn chặn thảm họa"}],"wordFamily":["catastrophic (adj.)","catastrophically (adv.)"],"synonyms":["disaster","calamity"],"antonyms":[],"tipVi":"Nặng nề hơn từ problem thông thường, thường dùng để chỉ những sự kiện gây thiệt hại nghiêm trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_offset', 'en-c1-19', 'offset', '/ˌɔːfˈset/', 'C1', 'bù đắp; đền bù; làm giảm nhẹ', 'v.', NULL, 'Đồng nghĩa: counterbalance, counteract', 'Dạng quá khứ và quá khứ phân từ vẫn giữ nguyên là offset; dạng phân từ hiện đại là offsetting.', 'My shorter commute offsets the higher rent here.', NULL, 'Quãng đường đi lại ngắn hơn giúp tôi bù đắp lại tiền thuê nhà đắt đỏ ở đây.', '{"wordId":"offset","ukIpa":"/ˌɒfˈset/","usIpa":"/ˌɔːfˈset/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"to balance or reduce the effect of something","vi":"bù đắp; đền bù; làm giảm nhẹ"}],"examples":[{"en":"My shorter commute offsets the higher rent here.","vi":"Quãng đường đi lại ngắn hơn giúp tôi bù đắp lại tiền thuê nhà đắt đỏ ở đây.","audioKind":"ex"},{"en":"Planting trees can offset some carbon emissions, but reducing fossil fuel consumption remains essential.","vi":"Việc trồng cây xanh có thể bù đắp một phần lượng khí thải carbon, nhưng việc giảm thiểu tiêu thụ nhiên liệu hóa thạch vẫn đóng vai trò cốt lõi.","audioKind":"ex2"}],"collocations":[{"en":"offset the cost","vi":"bù đắp chi phí"},{"en":"offset carbon emissions","vi":"bù đắp lượng khí thải carbon"},{"en":"offset the impact","vi":"giảm thiểu tác động"}],"wordFamily":[],"synonyms":["counterbalance","counteract"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ vẫn giữ nguyên là offset; dạng phân từ hiện đại là offsetting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arable', 'en-c1-19', 'arable', '/ˈærəbəl/', 'C1', 'thích hợp cho việc trồng trọt; có thể canh tác', 'adj.', NULL, 'Đồng nghĩa: cultivable · Trái nghĩa: uncultivable', 'Thường bổ nghĩa cho land; nhấn mạnh đất có thể trồng trọt, không dùng cho đất chăn thả thuần túy.', 'The family grows potatoes on a small arable field.', NULL, 'Gia đình trồng khoai tây trên một mảnh đất trồng trọt nhỏ.', '{"wordId":"arable","ukIpa":"/ˈærəbəl/","usIpa":"/ˈærəbəl/","cefr":"C1","topic":"environment","senses":[{"pos":"adj.","en":"Suitable for or used for growing crops.","vi":"thích hợp cho việc trồng trọt; có thể canh tác"}],"examples":[{"en":"The family grows potatoes on a small arable field.","vi":"Gia đình trồng khoai tây trên một mảnh đất trồng trọt nhỏ.","audioKind":"ex"},{"en":"Rapid urban expansion is reducing the amount of arable land available for food production in many regions.","vi":"Sự bành trướng đô thị nhanh chóng đang làm giảm lượng đất canh tác có sẵn cho sản xuất lương thực ở nhiều khu vực.","audioKind":"ex2"}],"collocations":[{"en":"arable land","vi":"đất canh tác"},{"en":"arable farming","vi":"ngành trồng trọt"},{"en":"arable crops","vi":"cây trồng hàng năm"}],"wordFamily":[],"synonyms":["cultivable"],"antonyms":["uncultivable"],"tipVi":"Thường bổ nghĩa cho land; nhấn mạnh đất có thể trồng trọt, không dùng cho đất chăn thả thuần túy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_devastating', 'en-c1-19', 'devastating', '/ˈdevəsteɪtɪŋ/', 'C1', 'mang tính hủy diệt; tàn phá nặng nề; gây đau thương tột cùng; làm suy sụp tinh thần', 'adj.', 'devastate (v.), devastation (n.), devastated (adj.), devastatingly (adv.)', 'Đồng nghĩa: disastrous, destructive', 'Sự việc gây đau lòng dùng devastating; người cảm thấy đau lòng dùng devastated.', 'A devastating storm tore the roof off our garage.', NULL, 'Một trận cuồng phong tàn khốc đã thổi bay mái nhà để xe của chúng tôi.', '{"wordId":"devastating","ukIpa":"/ˈdevəsteɪtɪŋ/","usIpa":"/ˈdevəsteɪtɪŋ/","cefr":"C1","topic":"environment","senses":[{"pos":"adj.","en":"Causing extremely serious damage or destruction.","vi":"mang tính hủy diệt; tàn phá nặng nề"},{"pos":"adj.","en":"Causing overwhelming sadness or emotional shock.","vi":"gây đau thương tột cùng; làm suy sụp tinh thần"}],"examples":[{"en":"A devastating storm tore the roof off our garage.","vi":"Một trận cuồng phong tàn khốc đã thổi bay mái nhà để xe của chúng tôi.","audioKind":"ex"},{"en":"Prolonged drought can have devastating effects on agriculture, threatening food supplies and the livelihoods of rural communities.","vi":"Hạn hán kéo dài có thể gây ra hậu quả tàn khốc đối với nông nghiệp, đe dọa nguồn cung lương thực và sinh kế của cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"devastating consequences","vi":"hậu quả tai hại"},{"en":"devastating impact","vi":"tác động tàn phá"},{"en":"devastating news","vi":"tin buồn chấn động"},{"en":"devastating earthquake","vi":"trận động đất tàn khốc"}],"wordFamily":["devastate (v.)","devastation (n.)","devastated (adj.)","devastatingly (adv.)"],"synonyms":["disastrous","destructive"],"antonyms":[],"tipVi":"Sự việc gây đau lòng dùng devastating; người cảm thấy đau lòng dùng devastated.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_erosion', 'en-c1-19', 'erosion', '/ɪˈroʊʒən/', 'C1', 'sự xói mòn; sự bào mòn; sự suy yếu dần; sự hao mòn', 'n.', 'erode (v.), erosive (adj.)', NULL, 'Thường là danh từ không đếm được; cũng có thể dùng theo nghĩa bóng để chỉ sự sụt giảm của lòng tin, quyền lực,...', 'Heavy rain caused erosion along the muddy river bank.', NULL, 'Mưa lớn gây xói mòn dọc theo bờ sông lầy lội.', '{"wordId":"erosion","ukIpa":"/ɪˈrəʊʒən/","usIpa":"/ɪˈroʊʒən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"The gradual removal of soil or rock by natural forces.","vi":"sự xói mòn; sự bào mòn"},{"pos":"n.","en":"The gradual loss of strength, value, or confidence.","vi":"sự suy yếu dần; sự hao mòn"}],"examples":[{"en":"Heavy rain caused erosion along the muddy river bank.","vi":"Mưa lớn gây xói mòn dọc theo bờ sông lầy lội.","audioKind":"ex"},{"en":"Planting trees can reduce soil erosion because their roots help hold the ground together during heavy rainfall.","vi":"Trồng cây có thể làm giảm xói mòn đất vì rễ của chúng giúp giữ chặt đất lại với nhau trong những trận mưa lớn.","audioKind":"ex2"}],"collocations":[{"en":"soil erosion","vi":"xói mòn đất"},{"en":"coastal erosion","vi":"xói mòn bờ biển"},{"en":"prevent erosion","vi":"ngăn chặn xói mòn"},{"en":"erosion of trust","vi":"sự xói mòn lòng tin"}],"wordFamily":["erode (v.)","erosive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; cũng có thể dùng theo nghĩa bóng để chỉ sự sụt giảm của lòng tin, quyền lực,...","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decompose', 'en-c1-19', 'decompose', '/ˌdiːkəmˈpoʊz/', 'C1', 'phân hủy; mục nát; thối rữa; tách thành các phần đơn giản hơn', 'v.', 'decomposition (n.), decomposer (n.)', 'Đồng nghĩa: decay, rot', 'Có thể dùng cả nội động từ lẫn ngoại động từ; đi với giới từ into khi chỉ quá trình phân rã thành cái gì.', 'Fallen leaves decompose slowly in the damp garden soil.', NULL, 'Lá rụng phân hủy chậm trong đất vườn ẩm ướt.', '{"wordId":"decompose","ukIpa":"/ˌdiːkəmˈpəʊz/","usIpa":"/ˌdiːkəmˈpoʊz/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"to decay naturally into simpler substances","vi":"phân hủy; mục nát; thối rữa"},{"pos":"v.","en":"to separate, or cause something to separate, into simpler parts","vi":"tách thành các phần đơn giản hơn"}],"examples":[{"en":"Fallen leaves decompose slowly in the damp garden soil.","vi":"Lá rụng phân hủy chậm trong đất vườn ẩm ướt.","audioKind":"ex"},{"en":"Organic waste can decompose into valuable nutrients, reducing the need for artificial fertilisers in agriculture.","vi":"Chất thải hữu cơ có thể phân hủy thành các chất dinh dưỡng quý giá, giúp giảm bớt nhu cầu sử dụng phân bón hóa học trong nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"decompose naturally","vi":"phân hủy tự nhiên"},{"en":"decompose into","vi":"phân hủy thành"},{"en":"decompose organic matter","vi":"phân hủy chất hữu cơ"}],"wordFamily":["decomposition (n.)","decomposer (n.)"],"synonyms":["decay","rot"],"antonyms":[],"tipVi":"Có thể dùng cả nội động từ lẫn ngoại động từ; đi với giới từ into khi chỉ quá trình phân rã thành cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inflict', 'en-c1-19', 'inflict', '/ɪnˈflɪkt/', 'C1', 'gây ra (tổn hại, đau đớn)', 'v.', 'infliction (n.)', NULL, 'Cấu trúc thường dùng là inflict [tổn hại] on [đối tượng], không dùng cấu trúc inflict sb.', 'The storm inflicted serious damage on our garden fence.', NULL, 'Cơn bão đã gây ra những tổn thất nghiêm trọng cho hàng rào khu vườn của chúng tôi.', '{"wordId":"inflict","ukIpa":"/ɪnˈflɪkt/","usIpa":"/ɪnˈflɪkt/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"to cause someone or something to suffer harm","vi":"gây ra (tổn hại, đau đớn)"}],"examples":[{"en":"The storm inflicted serious damage on our garden fence.","vi":"Cơn bão đã gây ra những tổn thất nghiêm trọng cho hàng rào khu vườn của chúng tôi.","audioKind":"ex"},{"en":"Unregulated industrial activity can inflict lasting damage on ecosystems and threaten the livelihoods of nearby communities.","vi":"Hoạt động công nghiệp thiếu sự quản lý có thể gây ra những tổn hại lâu dài cho hệ sinh thái và đe dọa sinh kế của các cộng đồng dân cư gần đó.","audioKind":"ex2"}],"collocations":[{"en":"inflict damage on","vi":"gây tổn hại cho"},{"en":"inflict pain on","vi":"gây đau đớn cho"},{"en":"inflict suffering on","vi":"gây gánh nặng khổ sở cho"}],"wordFamily":["infliction (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc thường dùng là inflict [tổn hại] on [đối tượng], không dùng cấu trúc inflict sb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insulation', 'en-c1-19', 'insulation', '/ˌɪnsəˈleɪʃən/', 'C1', 'sự cách nhiệt; sự cách âm; sự cách điện; vật liệu cách nhiệt; vật liệu cách âm; vật liệu cách điện', 'n.', 'insulate (v.), insulated (adj.), insulator (n.)', NULL, 'Thường là danh từ không đếm được; có thể chỉ hành động cách ly hoặc chỉ chính vật liệu được sử dụng.', 'The new roof insulation keeps our bedroom warm.', NULL, 'Lớp cách nhiệt mái nhà mới giúp giữ ấm cho phòng ngủ của chúng tôi.', '{"wordId":"insulation","ukIpa":"/ˌɪnsjʊˈleɪʃən/","usIpa":"/ˌɪnsəˈleɪʃən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"protection that reduces the passage of heat, sound, or electricity","vi":"sự cách nhiệt; sự cách âm; sự cách điện"},{"pos":"n.","en":"material used to limit heat, sound, or electricity passing through","vi":"vật liệu cách nhiệt; vật liệu cách âm; vật liệu cách điện"}],"examples":[{"en":"The new roof insulation keeps our bedroom warm.","vi":"Lớp cách nhiệt mái nhà mới giúp giữ ấm cho phòng ngủ của chúng tôi.","audioKind":"ex"},{"en":"Improving insulation in older homes can reduce energy consumption and lower heating costs during winter.","vi":"Cải thiện lớp cách nhiệt ở những ngôi nhà cũ có thể làm giảm tiêu thụ năng lượng và hạ chi phí sưởi ấm trong mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"thermal insulation","vi":"cách nhiệt"},{"en":"sound insulation","vi":"cách âm"},{"en":"electrical insulation","vi":"cách điện"},{"en":"insulation material","vi":"vật liệu cách nhiệt"}],"wordFamily":["insulate (v.)","insulated (adj.)","insulator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; có thể chỉ hành động cách ly hoặc chỉ chính vật liệu được sử dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imminent', 'en-c1-19', 'imminent', '/ˈɪmɪnənt/', 'C1', 'sắp xảy ra; cận kề trong tương lai rất gần', 'adj.', 'imminence (n.), imminently (adv.)', 'Đồng nghĩa: impending, forthcoming · Trái nghĩa: distant', 'Nhấn mạnh tính chất sắp xảy ra, không đồng nghĩa với urgent (cần xử lý gấp).', 'The dark clouds made a heavy downpour seem imminent.', NULL, 'Những đám mây đen cho thấy một cơn mưa lớn sắp sửa đổ xuống.', '{"wordId":"imminent","ukIpa":"/ˈɪmɪnənt/","usIpa":"/ˈɪmɪnənt/","cefr":"C1","topic":"environment","senses":[{"pos":"adj.","en":"Expected to happen very soon.","vi":"sắp xảy ra; cận kề trong tương lai rất gần"}],"examples":[{"en":"The dark clouds made a heavy downpour seem imminent.","vi":"Những đám mây đen cho thấy một cơn mưa lớn sắp sửa đổ xuống.","audioKind":"ex"},{"en":"Coastal communities need reliable warning systems when severe flooding is imminent, allowing residents enough time to evacuate.","vi":"Các cộng đồng ven biển cần có hệ thống cảnh báo đáng tin cậy khi có nguy cơ lũ lụt nghiêm trọng cận kề, để cư dân có đủ thời gian sơ tán.","audioKind":"ex2"}],"collocations":[{"en":"imminent danger","vi":"nguy hiểm cận kề"},{"en":"an imminent threat","vi":"mối đe dọa sắp xảy ra"},{"en":"imminent collapse","vi":"sự sụp đổ nhãn tiền"}],"wordFamily":["imminence (n.)","imminently (adv.)"],"synonyms":["impending","forthcoming"],"antonyms":["distant"],"tipVi":"Nhấn mạnh tính chất sắp xảy ra, không đồng nghĩa với urgent (cần xử lý gấp).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plantation', 'en-c1-19', 'plantation', '/plænˈteɪʃən/', 'C1', 'đồn điền; trang trại lớn; rừng trồng; rừng nhân tạo', 'n.', 'plant (v.), planting (n.), planter (n.)', NULL, 'Thường chỉ các nông trại rộng lớn trồng một loại cây duy nhất, không phải khu vườn thông thường.', 'We walked past a tea plantation on the hillside.', NULL, 'Chúng tôi đi ngang qua một đồn điền chè trên sườn đồi.', '{"wordId":"plantation","ukIpa":"/plɑːnˈteɪʃən/","usIpa":"/plænˈteɪʃən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"A large farm growing crops such as tea, coffee, or cotton.","vi":"đồn điền; trang trại lớn"},{"pos":"n.","en":"An area where trees are planted together, often for timber.","vi":"rừng trồng; rừng nhân tạo"}],"examples":[{"en":"We walked past a tea plantation on the hillside.","vi":"Chúng tôi đi ngang qua một đồn điền chè trên sườn đồi.","audioKind":"ex"},{"en":"Expanding palm oil plantations can threaten biodiversity when natural forests are cleared to make room for crops.","vi":"Việc mở rộng các đồn điền trồng cọ dầu có thể đe dọa sự đa dạng sinh học khi các khu rừng tự nhiên bị phá quang để nhường chỗ cho cây trồng.","audioKind":"ex2"}],"collocations":[{"en":"tea plantation","vi":"đồn điền chè"},{"en":"coffee plantation","vi":"đồn điền cà phê"},{"en":"plantation workers","vi":"công nhân đồn điền"},{"en":"forest plantation","vi":"rừng trồng"}],"wordFamily":["plant (v.)","planting (n.)","planter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ các nông trại rộng lớn trồng một loại cây duy nhất, không phải khu vườn thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deplete', 'en-c1-19', 'deplete', '/dɪˈpliːt/', 'C1', 'làm cạn kiệt; làm suy giảm (làm giảm mạnh số lượng sẵn có của cái gì đó)', 'v.', 'depletion (n.), depleted (adj.)', 'Đồng nghĩa: exhaust, drain · Trái nghĩa: replenish', 'Nhấn mạnh trữ lượng giảm mạnh, không nhất thiết phải cạn sạch hoàn toàn.', 'Running several apps at once can deplete your battery.', NULL, 'Chạy nhiều ứng dụng cùng một lúc có thể làm cạn kiệt pin điện thoại của bạn.', '{"wordId":"deplete","ukIpa":"/dɪˈpliːt/","usIpa":"/dɪˈpliːt/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"to greatly reduce the amount of something available","vi":"làm cạn kiệt; làm suy giảm (làm giảm mạnh số lượng sẵn có của cái gì đó)"}],"examples":[{"en":"Running several apps at once can deplete your battery.","vi":"Chạy nhiều ứng dụng cùng một lúc có thể làm cạn kiệt pin điện thoại của bạn.","audioKind":"ex"},{"en":"Intensive farming can deplete soil nutrients, making future food production more difficult and expensive.","vi":"Canh tác thâm canh có thể làm cạn kiệt chất dinh dưỡng trong đất, khiến việc sản xuất lương thực trong tương lai trở nên khó khăn và tốn kém hơn.","audioKind":"ex2"}],"collocations":[{"en":"deplete resources","vi":"làm cạn kiệt tài nguyên"},{"en":"deplete energy reserves","vi":"làm suy kiệt dự trữ năng lượng"},{"en":"deplete stocks","vi":"làm cạn kiệt nguồn hàng"}],"wordFamily":["depletion (n.)","depleted (adj.)"],"synonyms":["exhaust","drain"],"antonyms":["replenish"],"tipVi":"Nhấn mạnh trữ lượng giảm mạnh, không nhất thiết phải cạn sạch hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tract', 'en-c1-19', 'tract', '/trækt/', 'C1', 'vùng đất rộng lớn; dải đất; đường ống cơ thể; hệ cơ quan; tờ rơi tôn giáo hoặc chính trị', 'n.', NULL, NULL, 'Nghĩa chỉ đất đai thường dùng cụm a tract of; không nhầm lẫn với track mang nghĩa "đường ray".', 'They bought a small cottage beside a vast tract of woodland.', NULL, 'Họ đã mua một ngôi nhà nhỏ nằm cạnh một khu rừng bạt ngàn.', '{"wordId":"tract","ukIpa":"/trækt/","usIpa":"/trækt/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"a large area of land","vi":"vùng đất rộng lớn; dải đất"},{"pos":"n.","en":"a connected system of organs or tissues with a shared function","vi":"đường ống cơ thể; hệ cơ quan"},{"pos":"n.","en":"a short publication expressing religious or political ideas","vi":"tờ rơi tôn giáo hoặc chính trị"}],"examples":[{"en":"They bought a small cottage beside a vast tract of woodland.","vi":"Họ đã mua một ngôi nhà nhỏ nằm cạnh một khu rừng bạt ngàn.","audioKind":"ex"},{"en":"Large tracts of forest must be protected to preserve biodiversity and regulate the global climate.","vi":"Những khu rừng rộng lớn phải được bảo vệ để duy trì đa dạng sinh học và điều hòa khí hậu toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"a tract of land","vi":"một mảnh đất lớn"},{"en":"vast tracts of forest","vi":"những khu rừng bạt ngàn"},{"en":"the digestive tract","vi":"đường tiêu hóa"},{"en":"the respiratory tract","vi":"đường hô hấp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chỉ đất đai thường dùng cụm a tract of; không nhầm lẫn với track mang nghĩa \"đường ray\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_irrigate', 'en-c1-19', 'irrigate', '/ˈɪrɪɡeɪt/', 'C1', 'tưới tiêu; cấp nước', 'v.', 'irrigation (n.), irrigated (adj.)', 'Đồng nghĩa: water', 'Thường đóng vai trò là ngoại động từ, tân ngữ chỉ đồng ruộng hoặc cây trồng, không phải là nước.', 'Farmers irrigate these fields with water from the river.', NULL, 'Nông dân dùng nước sông để tưới cho những cánh đồng này.', '{"wordId":"irrigate","ukIpa":"/ˈɪrɪɡeɪt/","usIpa":"/ˈɪrɪɡeɪt/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"to supply land or crops with water","vi":"tưới tiêu; cấp nước"}],"examples":[{"en":"Farmers irrigate these fields with water from the river.","vi":"Nông dân dùng nước sông để tưới cho những cánh đồng này.","audioKind":"ex"},{"en":"Using treated wastewater to irrigate crops can reduce pressure on freshwater supplies in dry regions.","vi":"Việc sử dụng nước thải đã qua xử lý để tưới tiêu cho cây trồng có thể làm giảm áp lực lên nguồn cung cấp nước ngọt ở các vùng khô hạn.","audioKind":"ex2"}],"collocations":[{"en":"irrigate crops","vi":"tưới tiêu cây trồng"},{"en":"irrigate farmland","vi":"tưới tiêu đất nông nghiệp"},{"en":"irrigation system","vi":"hệ thống tưới tiêu"}],"wordFamily":["irrigation (n.)","irrigated (adj.)"],"synonyms":["water"],"antonyms":[],"tipVi":"Thường đóng vai trò là ngoại động từ, tân ngữ chỉ đồng ruộng hoặc cây trồng, không phải là nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vegetation', 'en-c1-19', 'vegetation', '/ˌvedʒəˈteɪʃən/', 'C1', 'thực vật; thảm thực vật', 'n.', 'vegetative (adj.)', 'Đồng nghĩa: plant life', 'Là danh từ không đếm được, dùng để chỉ chung thực vật ở một khu vực nhất định, không có nghĩa là rau củ.', 'Thick vegetation hid the narrow path beside the river.', NULL, 'Thảm thực vật rậm rạp che khuất con đường mòn hẹp ven sông.', '{"wordId":"vegetation","ukIpa":"/ˌvedʒəˈteɪʃən/","usIpa":"/ˌvedʒəˈteɪʃən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"plants growing together in a particular area","vi":"thực vật; thảm thực vật"}],"examples":[{"en":"Thick vegetation hid the narrow path beside the river.","vi":"Thảm thực vật rậm rạp che khuất con đường mòn hẹp ven sông.","audioKind":"ex"},{"en":"Removing natural vegetation increases soil erosion and reduces the capacity of land to absorb heavy rainfall.","vi":"Việc phá bỏ thảm thực vật tự nhiên làm gia tăng tình trạng xói mòn đất và làm giảm khả năng hấp thụ lượng mưa lớn của đất đai.","audioKind":"ex2"}],"collocations":[{"en":"dense vegetation","vi":"thảm thực vật rậm rạp"},{"en":"native vegetation","vi":"thực vật bản địa"},{"en":"vegetation cover","vi":"độ che phủ thực vật"},{"en":"clear vegetation","vi":"dọn dẹp thực vật"}],"wordFamily":["vegetative (adj.)"],"synonyms":["plant life"],"antonyms":[],"tipVi":"Là danh từ không đếm được, dùng để chỉ chung thực vật ở một khu vực nhất định, không có nghĩa là rau củ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_devastate', 'en-c1-19', 'devastate', '/ˈdevəsteɪt/', 'C1', 'tàn phá; phá hủy nghiêm trọng; làm cho suy sụp; làm cho đau buồn tột cùng', 'v.', 'devastation (n.), devastating (adj.), devastated (adj.)', 'Đồng nghĩa: destroy, ravage', 'Mức độ nặng hơn damage; cũng có thể dùng khi tinh thần ai đó bị tổn thương sâu sắc.', 'The storm devastated the village, leaving many homes damaged.', NULL, 'Cơn bão đã tàn phá ngôi làng, khiến nhiều nhà cửa bị hư hại.', '{"wordId":"devastate","ukIpa":"/ˈdevəsteɪt/","usIpa":"/ˈdevəsteɪt/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"To cause very severe damage to a place or thing","vi":"tàn phá; phá hủy nghiêm trọng"},{"pos":"v.","en":"To make someone feel extremely upset or shocked","vi":"làm cho suy sụp; làm cho đau buồn tột cùng"}],"examples":[{"en":"The storm devastated the village, leaving many homes damaged.","vi":"Cơn bão đã tàn phá ngôi làng, khiến nhiều nhà cửa bị hư hại.","audioKind":"ex"},{"en":"Prolonged droughts can devastate agricultural communities by destroying crops and reducing the income available to farming households.","vi":"Các đợt hạn hán kéo dài có thể tàn phá các vùng nông nghiệp bằng cách hủy hoại hoa màu và làm giảm nguồn thu nhập của các hộ nông dân.","audioKind":"ex2"}],"collocations":[{"en":"devastate a region","vi":"tàn phá một vùng"},{"en":"devastate the economy","vi":"phá hoại nền kinh tế"},{"en":"feel devastated","vi":"cảm thấy suy sụp"},{"en":"devastating impact","vi":"tác động tàn phá"}],"wordFamily":["devastation (n.)","devastating (adj.)","devastated (adj.)"],"synonyms":["destroy","ravage"],"antonyms":[],"tipVi":"Mức độ nặng hơn damage; cũng có thể dùng khi tinh thần ai đó bị tổn thương sâu sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adverse', 'en-c1-19', 'adverse', '/ædˈvɝːs/', 'C1', 'bất lợi; có hại; khắc nghiệt', 'adj.', 'adversely (adv.), adversity (n.)', 'Đồng nghĩa: unfavourable, harmful, detrimental · Trái nghĩa: favourable, beneficial', 'Adverse mang nghĩa bất lợi, trong khi averse mang nghĩa phản aversion/phải lòng và thường đi với giới từ to.', 'Our ferry was cancelled because of adverse weather conditions.', NULL, 'Chuyến phà của chúng tôi đã bị hủy vì điều kiện thời tiết khắc nghiệt.', '{"wordId":"adverse","ukIpa":"/ˈædvɜːs/","usIpa":"/ædˈvɝːs/","cefr":"C1","topic":"environment","senses":[{"pos":"adj.","en":"Harmful or making success and progress more difficult.","vi":"bất lợi; có hại; khắc nghiệt"}],"examples":[{"en":"Our ferry was cancelled because of adverse weather conditions.","vi":"Chuyến phà của chúng tôi đã bị hủy vì điều kiện thời tiết khắc nghiệt.","audioKind":"ex"},{"en":"Prolonged exposure to traffic noise can have adverse effects on residents'' sleep and mental health.","vi":"Việc tiếp xúc kéo dài với tiếng ồn giao thông có thể gây ra những tác động bất lợi đến giấc ngủ và sức khỏe tinh thần của người dân.","audioKind":"ex2"}],"collocations":[{"en":"adverse effects","vi":"tác động bất lợi"},{"en":"adverse weather conditions","vi":"điều kiện thời tiết khắc nghiệt"},{"en":"an adverse reaction","vi":"phản ứng bất lợi"},{"en":"adverse circumstances","vi":"hoàn cảnh bất lợi"}],"wordFamily":["adversely (adv.)","adversity (n.)"],"synonyms":["unfavourable","harmful","detrimental"],"antonyms":["favourable","beneficial"],"tipVi":"Adverse mang nghĩa bất lợi, trong khi averse mang nghĩa phản aversion/phải lòng và thường đi với giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_19_1', 'en-c1-19', 'Cách dùng “erosion” (n.) — sự xói mòn; sự bào mòn', 'soil erosion  ·  coastal erosion  ·  prevent erosion', 'Thường là danh từ không đếm được; cũng có thể dùng theo nghĩa bóng để chỉ sự sụt giảm của lòng tin, quyền lực,...', 'Họ từ (Word Family): erode (v.), erosive (adj.)', '[{"hanzi":"Heavy rain caused erosion along the muddy river bank.","pinyin":"","meaning":"Mưa lớn gây xói mòn dọc theo bờ sông lầy lội."},{"hanzi":"Planting trees can reduce soil erosion because their roots help hold the ground together during heavy rainfall.","pinyin":"","meaning":"Trồng cây có thể làm giảm xói mòn đất vì rễ của chúng giúp giữ chặt đất lại với nhau trong những trận mưa lớn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_19_2', 'en-c1-19', 'Cách dùng “vulnerability” (n.) — tính dễ bị tổn thương; tính dễ bị tác động', 'vulnerability to flooding  ·  security vulnerability  ·  reduce vulnerability', 'Không đếm được khi chỉ tính chất dễ bị tổn thương nói chung; đếm được khi chỉ các điểm yếu hoặc lỗ hổng cụ thể.', 'Họ từ (Word Family): vulnerable (adj.), invulnerable (adj.), invulnerability (n.) | Đồng nghĩa: susceptibility, weakness · Trái nghĩa: invulnerability', '[{"hanzi":"The storm exposed the vulnerability of our old roof.","pinyin":"","meaning":"Cơn bão đã phơi bày sự xuống cấp và dễ tổn thương của mái nhà cũ chúng tôi."},{"hanzi":"Investing in flood defences can reduce the vulnerability of coastal communities to increasingly severe storms.","pinyin":"","meaning":"Đầu tư vào các công trình phòng chống lũ lụt có thể làm giảm tính dễ bị tổn thương của các cộng đồng ven biển trước những cơn bão ngày càng tàn khốc."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_19_3', 'en-c1-19', 'Cách dùng “adverse” (adj.) — bất lợi; có hại; khắc nghiệt', 'adverse effects  ·  adverse weather conditions  ·  an adverse reaction', 'Adverse mang nghĩa bất lợi, trong khi averse mang nghĩa phản aversion/phải lòng và thường đi với giới từ to.', 'Họ từ (Word Family): adversely (adv.), adversity (n.) | Đồng nghĩa: unfavourable, harmful, detrimental · Trái nghĩa: favourable, beneficial', '[{"hanzi":"Our ferry was cancelled because of adverse weather conditions.","pinyin":"","meaning":"Chuyến phà của chúng tôi đã bị hủy vì điều kiện thời tiết khắc nghiệt."},{"hanzi":"Prolonged exposure to traffic noise can have adverse effects on residents'' sleep and mental health.","pinyin":"","meaning":"Việc tiếp xúc kéo dài với tiếng ồn giao thông có thể gây ra những tác động bất lợi đến giấc ngủ và sức khỏe tinh thần của người dân."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_19_4', 'en-c1-19', 'Cách dùng “decompose” (v.) — phân hủy; mục nát; thối rữa', 'decompose naturally  ·  decompose into  ·  decompose organic matter', 'Có thể dùng cả nội động từ lẫn ngoại động từ; đi với giới từ into khi chỉ quá trình phân rã thành cái gì.', 'Họ từ (Word Family): decomposition (n.), decomposer (n.) | Đồng nghĩa: decay, rot', '[{"hanzi":"Fallen leaves decompose slowly in the damp garden soil.","pinyin":"","meaning":"Lá rụng phân hủy chậm trong đất vườn ẩm ướt."},{"hanzi":"Organic waste can decompose into valuable nutrients, reducing the need for artificial fertilisers in agriculture.","pinyin":"","meaning":"Chất thải hữu cơ có thể phân hủy thành các chất dinh dưỡng quý giá, giúp giảm bớt nhu cầu sử dụng phân bón hóa học trong nông nghiệp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_19_1', 'en-c1-19', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_1_1', 'ten_c1_19_1', 'irrigation', 'The farm''s irrigation system keeps these vegetables growing.', 'The farm''s irrigation system keeps these vegetables growing.', '/ˌɪrɪˈɡeɪʃən/', 'Hệ thống tưới tiêu của trang trại giúp duy trì sự phát triển của những luống rau này.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_1_2', 'ten_c1_19_1', 'hydroelectric', 'We visited a hydroelectric dam during our mountain holiday.', 'We visited a hydroelectric dam during our mountain holiday.', '/ˌhaɪdroʊɪˈlektrɪk/', 'Chúng tôi đã tham quan một đập thủy điện trong chuyến nghỉ mát trên núi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_1_3', 'ten_c1_19_1', 'reclaim', 'I returned to the station to reclaim my suitcase.', 'I returned to the station to reclaim my suitcase.', '/rɪˈkleɪm/', 'Tôi đã quay lại nhà ga để nhận lại chiếc vali của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_1_4', 'ten_c1_19_1', 'vulnerability', 'The storm exposed the vulnerability of our old roof.', 'The storm exposed the vulnerability of our old roof.', '/ˌvʌlnərəˈbɪləti/', 'Cơn bão đã phơi bày sự xuống cấp và dễ tổn thương của mái nhà cũ chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_1_5', 'ten_c1_19_1', 'contaminate', 'Dirty hands can contaminate food while you cook.', 'Dirty hands can contaminate food while you cook.', '/kənˈtæmɪneɪt/', 'Tay bẩn có thể làm ô nhiễm thức ăn trong lúc bạn nấu nướng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_1_6', 'ten_c1_19_1', 'hectare', 'Their vegetable farm covers just over a hectare.', 'Their vegetable farm covers just over a hectare.', '/ˈhekter/', 'Trang trại rau của họ rộng hơn một héc-ta một chút.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_1_7', 'ten_c1_19_1', 'incinerator', 'The hospital sends certain waste to a special incinerator.', 'The hospital sends certain waste to a special incinerator.', '/ɪnˈsɪnəreɪtər/', 'Bệnh viện gửi một số loại rác thải đến lò đốt chuyên dụng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_1_8', 'ten_c1_19_1', 'manure', 'The farmer spread manure around the young apple trees.', 'The farmer spread manure around the young apple trees.', '/məˈnʊr/', 'Người nông dân rải phân chuồng xung quanh những gốc cây táo non.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_19_1_1', 'en-c1-19', 'ten_c1_19_1', 'listening', 'listening', 'The farm''s irrigation system keeps these vegetables growing.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hệ thống tưới tiêu của trang trại giúp duy trì sự phát triển của những luống rau này.","Thảm thực vật rậm rạp che khuất con đường mòn hẹp ven sông.","Những đám mây đen cho thấy một cơn mưa lớn sắp sửa đổ xuống.","Gia đình trồng khoai tây trên một mảnh đất trồng trọt nhỏ."]'::jsonb, 0, 'The farm''s irrigation system keeps these vegetables growing. → Hệ thống tưới tiêu của trang trại giúp duy trì sự phát triển của những luống rau này.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_19_1_2', 'en-c1-19', 'ten_c1_19_1', 'listening', 'listening', 'We visited a hydroelectric dam during our mountain holiday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nông dân dùng nước sông để tưới cho những cánh đồng này.","Chúng tôi đã tham quan một đập thủy điện trong chuyến nghỉ mát trên núi.","Chúng tôi đi ngang qua một đồn điền chè trên sườn đồi.","Chuyến phà của chúng tôi đã bị hủy vì điều kiện thời tiết khắc nghiệt."]'::jsonb, 1, 'We visited a hydroelectric dam during our mountain holiday. → Chúng tôi đã tham quan một đập thủy điện trong chuyến nghỉ mát trên núi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_19_1_3', 'en-c1-19', 'ten_c1_19_1', 'listening', 'listening', 'I returned to the station to reclaim my suitcase.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cơn bão đã gây ra những tổn thất nghiêm trọng cho hàng rào khu vườn của chúng tôi.","Hệ thống tưới tiêu của trang trại giúp duy trì sự phát triển của những luống rau này.","Chúng tôi đi ngang qua một đồn điền chè trên sườn đồi.","Tôi đã quay lại nhà ga để nhận lại chiếc vali của mình."]'::jsonb, 3, 'I returned to the station to reclaim my suitcase. → Tôi đã quay lại nhà ga để nhận lại chiếc vali của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_19_2', 'en-c1-19', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_2_1', 'ten_c1_19_2', 'irrigation', 'Efficient irrigation can increase crop yields while reducing water consumption in regions affected by drought.', 'Efficient irrigation can increase crop yields while reducing water consumption in regions affected by drought.', '/ˌɪrɪˈɡeɪʃən/', 'Hệ thống tưới tiêu hiệu quả có thể làm tăng năng suất cây trồng đồng thời giảm lượng nước tiêu thụ ở các khu vực chịu ảnh hưởng bởi hạn hán.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_2_2', 'ten_c1_19_2', 'hydroelectric', 'Hydroelectric power can reduce dependence on fossil fuels, although large dams may disrupt river ecosystems.', 'Hydroelectric power can reduce dependence on fossil fuels, although large dams may disrupt river ecosystems.', '/ˌhaɪdroʊɪˈlektrɪk/', 'Năng lượng thủy điện có thể làm giảm sự phụ thuộc vào nhiên liệu hóa thạch, mặc dù các con đập lớn có thể phá vỡ hệ sinh thái sông ngòi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_2_3', 'ten_c1_19_2', 'reclaim', 'Coastal cities sometimes reclaim land from the sea to create space for housing and transport.', 'Coastal cities sometimes reclaim land from the sea to create space for housing and transport.', '/rɪˈkleɪm/', 'Các thành phố ven biển đôi khi tiến hành lấn biển để tạo ra quỹ đất cho nhà ở và giao thông.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_2_4', 'ten_c1_19_2', 'vulnerability', 'Investing in flood defences can reduce the vulnerability of coastal communities to increasingly severe storms.', 'Investing in flood defences can reduce the vulnerability of coastal communities to increasingly severe storms.', '/ˌvʌlnərəˈbɪləti/', 'Đầu tư vào các công trình phòng chống lũ lụt có thể làm giảm tính dễ bị tổn thương của các cộng đồng ven biển trước những cơn bão ngày càng tàn khốc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_2_5', 'ten_c1_19_2', 'contaminate', 'Industrial chemicals can contaminate groundwater, threatening both agricultural production and the health of nearby communities.', 'Industrial chemicals can contaminate groundwater, threatening both agricultural production and the health of nearby communities.', '/kənˈtæmɪneɪt/', 'Hóa chất công nghiệp có thể làm ô nhiễm nguồn nước ngầm, đe dọa cả sản xuất nông nghiệp lẫn sức khỏe của các cộng đồng dân cư xung quanh.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_19_2_6', 'ten_c1_19_2', 'hectare', 'Restoring each hectare of wetland can provide valuable habitats and reduce the risk of local flooding.', 'Restoring each hectare of wetland can provide valuable habitats and reduce the risk of local flooding.', '/ˈhekter/', 'Việc khôi phục mỗi héc-ta đất ngập nước có thể mang lại các sinh cảnh quý giá và giảm nguy cơ lũ lụt ở địa phương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_19_2_1', 'en-c1-19', 'ten_c1_19_2', 'listening', 'listening', 'Efficient irrigation can increase crop yields while reducing water consumption in regions affected by drought.', NULL, 'Trong câu vừa nghe, từ “irrigation” mang nghĩa nào sau đây?', '["thủ tục hành chính; nghi thức rườm rà","sự tưới tiêu; hệ thống tưới tiêu","ngủ đông; tạm ngưng hoạt động; tiềm ẩn","thợ thủ công; thợ lành nghề"]'::jsonb, 1, '“irrigation” (/ˌɪrɪˈɡeɪʃən/): sự tưới tiêu; hệ thống tưới tiêu. Câu đầy đủ: Efficient irrigation can increase crop yields while reducing water consumption in regions affected by drought.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_19_2_2', 'en-c1-19', 'ten_c1_19_2', 'listening', 'listening', 'Hydroelectric power can reduce dependence on fossil fuels, although large dams may disrupt river ecosystems.', NULL, 'Trong câu vừa nghe, từ “hydroelectric” mang nghĩa nào sau đây?', '["cơn mưa xối xả; trận lụt lớn","thuộc về thủy điện; liên quan đến thủy điện","sự xem xét kỹ lưỡng; sự kiểm tra chi tiết","không thể thiếu, vô cùng quan trọng, thiết yếu"]'::jsonb, 1, '“hydroelectric” (/ˌhaɪdroʊɪˈlektrɪk/): thuộc về thủy điện; liên quan đến thủy điện. Câu đầy đủ: Hydroelectric power can reduce dependence on fossil fuels, although large dams may disrupt river ecosystems.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
