INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_19_1', 'en-c1-19', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “irrigation” (/ˌɪrɪˈɡeɪʃən/) có nghĩa là gì?', '["thảm họa; tai họa","bất lợi; có hại; khắc nghiệt","phân hủy; mục nát; thối rữa","sự tưới tiêu; hệ thống tưới tiêu"]'::jsonb, 3, '“irrigation” (n.): sự tưới tiêu; hệ thống tưới tiêu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
