INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_1', 'en-c1-19', NULL, 'comprehensive_test', 'listening', 'irrigation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự tưới tiêu; hệ thống tưới tiêu","lật đổ; đánh đổ","kẻ theo chủ nghĩa đế quốc","thuộc về sân khấu; kịch nghệ"]'::jsonb, 0, 'irrigation (/ˌɪrɪˈɡeɪʃən/) → sự tưới tiêu; hệ thống tưới tiêu', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_2', 'en-c1-19', NULL, 'comprehensive_test', 'listening', 'We visited a hydroelectric dam during our mountain holiday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một trận cuồng phong tàn khốc đã thổi bay mái nhà để xe của chúng tôi.","Chúng tôi đi ngang qua một đồn điền chè trên sườn đồi.","Chúng tôi đã tham quan một đập thủy điện trong chuyến nghỉ mát trên núi.","Những đám mây đen cho thấy một cơn mưa lớn sắp sửa đổ xuống."]'::jsonb, 2, 'We visited a hydroelectric dam during our mountain holiday. → Chúng tôi đã tham quan một đập thủy điện trong chuyến nghỉ mát trên núi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_3', 'en-c1-19', NULL, 'comprehensive_test', 'listening', 'reclaim', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lấy lại; đòi lại; thu hồi","chứng liệt; sự tê liệt (cơ thể)","liên kết; sáp nhập; gia nhập vào tổ chức lớn","rậm rạp lá; xanh tươi bóng mát"]'::jsonb, 0, 'reclaim (/rɪˈkleɪm/) → lấy lại; đòi lại; thu hồi; khai khẩn; cải tạo (đất bị hỏng hoặc ngập nước để sử dụng); tái chế; thu hồi nguyên vật liệu từ rác thải', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_4', 'en-c1-19', NULL, 'comprehensive_test', 'listening', 'The storm exposed the vulnerability of our old roof.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lá rụng phân hủy chậm trong đất vườn ẩm ướt.","Cơn bão đã gây ra những tổn thất nghiêm trọng cho hàng rào khu vườn của chúng tôi.","Lớp cách nhiệt mái nhà mới giúp giữ ấm cho phòng ngủ của chúng tôi.","Cơn bão đã phơi bày sự xuống cấp và dễ tổn thương của mái nhà cũ chúng tôi."]'::jsonb, 3, 'The storm exposed the vulnerability of our old roof. → Cơn bão đã phơi bày sự xuống cấp và dễ tổn thương của mái nhà cũ chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_5', 'en-c1-19', NULL, 'comprehensive_test', 'listening', 'contaminate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm cứng lại; trở nên cứng đờ, kém linh hoạt","tính tiết kiệm; sự chi tiêu tằn tiện","làm ô nhiễm; làm bẩn","cân nhắc kỹ lưỡng; suy ngẫm; trầm ngâm"]'::jsonb, 2, 'contaminate (/kənˈtæmɪneɪt/) → làm ô nhiễm; làm bẩn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_6', 'en-c1-19', NULL, 'comprehensive_test', 'listening', 'Their vegetable farm covers just over a hectare.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã tham quan một đập thủy điện trong chuyến nghỉ mát trên núi.","Chúng tôi đi ngang qua một đồn điền chè trên sườn đồi.","Nông dân dùng nước sông để tưới cho những cánh đồng này.","Trang trại rau của họ rộng hơn một héc-ta một chút."]'::jsonb, 3, 'Their vegetable farm covers just over a hectare. → Trang trại rau của họ rộng hơn một héc-ta một chút.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_7', 'en-c1-19', NULL, 'comprehensive_test', 'listening', 'incinerator', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiền hoàn lại; tiền thoái lại; tiền hoàn thuế","hệ thống thuế; việc thu thuế; thuế khóa","thù lao; tiền công; chế độ đãi ngộ","lò ốt; lò đốt rác"]'::jsonb, 3, 'incinerator (/ɪnˈsɪnəreɪtər/) → lò ốt; lò đốt rác', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_8', 'en-c1-19', NULL, 'comprehensive_test', 'listening', 'The farmer spread manure around the young apple trees.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chạy nhiều ứng dụng cùng một lúc có thể làm cạn kiệt pin điện thoại của bạn.","Tôi đã quay lại nhà ga để nhận lại chiếc vali của mình.","Người nông dân rải phân chuồng xung quanh những gốc cây táo non.","Chúng tôi đã tham quan một đập thủy điện trong chuyến nghỉ mát trên núi."]'::jsonb, 2, 'The farmer spread manure around the young apple trees. → Người nông dân rải phân chuồng xung quanh những gốc cây táo non.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
