INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_18', 'en-c1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Efficient irrigation can increase crop yields while reducing water consumption in regions affected by drought.', 'Dựa vào câu trên, từ “irrigation” có nghĩa phù hợp nhất là gì?', '["người cư ngụ; người sử dụng; hành khách (trên xe)","làm ăn mòn; bị ăn mòn (hóa học)","sự tưới tiêu; hệ thống tưới tiêu","đường hô hấp; khí quản"]'::jsonb, 2, 'irrigation: sự tưới tiêu; hệ thống tưới tiêu. Dịch cả câu: Hệ thống tưới tiêu hiệu quả có thể làm tăng năng suất cây trồng đồng thời giảm lượng nước tiêu thụ ở các khu vực chịu ảnh hưởng bởi hạn hán.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_19', 'en-c1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Hydroelectric power can reduce dependence on fossil fuels, although large dams may disrupt river ecosystems.', 'Dựa vào câu trên, từ “hydroelectric” có nghĩa phù hợp nhất là gì?', '["ngữ âm học","tối ưu; tốt nhất; thuận lợi nhất","thuộc về thủy điện; liên quan đến thủy điện","xác thực; có tính quyết định; thuyết phục"]'::jsonb, 2, 'hydroelectric: thuộc về thủy điện; liên quan đến thủy điện. Dịch cả câu: Năng lượng thủy điện có thể làm giảm sự phụ thuộc vào nhiên liệu hóa thạch, mặc dù các con đập lớn có thể phá vỡ hệ sinh thái sông ngòi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_20', 'en-c1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Coastal cities sometimes reclaim land from the sea to create space for housing and transport.', 'Dựa vào câu trên, từ “reclaim” có nghĩa phù hợp nhất là gì?', '["viên nhỏ; hạt nén","hào; rãnh; chiến hào","lấy lại; đòi lại; thu hồi","thuyền lớn; tàu thủy"]'::jsonb, 2, 'reclaim: lấy lại; đòi lại; thu hồi; khai khẩn; cải tạo (đất bị hỏng hoặc ngập nước để sử dụng); tái chế; thu hồi nguyên vật liệu từ rác thải. Dịch cả câu: Các thành phố ven biển đôi khi tiến hành lấn biển để tạo ra quỹ đất cho nhà ở và giao thông.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_21', 'en-c1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Investing in flood defences can reduce the vulnerability of coastal communities to increasingly severe storms.', 'Dựa vào câu trên, từ “vulnerability” có nghĩa phù hợp nhất là gì?', '["đàn (côn trùng); bầy","tính dễ bị tổn thương; tính dễ bị tác động","người hoặc vật tương đương, có cùng vai trò ở một bối cảnh khác","ý định; mục đích"]'::jsonb, 1, 'vulnerability: tính dễ bị tổn thương; tính dễ bị tác động; điểm yếu; lỗ hổng bảo mật. Dịch cả câu: Đầu tư vào các công trình phòng chống lũ lụt có thể làm giảm tính dễ bị tổn thương của các cộng đồng ven biển trước những cơn bão ngày càng tàn khốc.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_22', 'en-c1-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thực vật; thảm thực vật”', '["vegetation","intermittent","trivial","deafen"]'::jsonb, 0, 'thực vật; thảm thực vật → vegetation (/ˌvedʒəˈteɪʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_23', 'en-c1-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tàn phá; phá hủy nghiêm trọng”', '["dissipate","devastate","proxy","innovate"]'::jsonb, 1, 'tàn phá; phá hủy nghiêm trọng → devastate (/ˈdevəsteɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_19_24', 'en-c1-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bất lợi; có hại; khắc nghiệt”', '["obliging","exceedingly","assassination","adverse"]'::jsonb, 3, 'bất lợi; có hại; khắc nghiệt → adverse (/ædˈvɝːs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-20', 'en', 'Bài 20: Môi trường & Sinh thái (2) - CEFR C1', 'CEFR C1', 'C1 · Môi trường', '24 từ vựng Tiếng Anh CEFR C1 chủ đề môi trường & sinh thái kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5020, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_degrade', 'en-c1-20', 'degrade', '/dɪˈɡreɪd/', 'C1', 'làm suy giảm; làm hư hỏng chất lượng; phân hủy; giảm phân; làm mất nhân phẩm; hạ nhục', 'v.', 'degradation (n.), degradable (adj.), degrading (adj.)', 'Đồng nghĩa: deteriorate, damage', 'Chỉ sự sụt giảm chất lượng có thể dùng ngoại động từ; sự phân hủy hóa học cũng có thể dùng nội động từ.', 'Strong sunlight can degrade the fabric of outdoor chairs.', NULL, 'Ánh nắng mạnh có thể làm hỏng chất liệu vải của ghế ngoài trời.', '{"wordId":"degrade","ukIpa":"/dɪˈɡreɪd/","usIpa":"/dɪˈɡreɪd/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"To reduce the quality or condition of something","vi":"làm suy giảm; làm hư hỏng chất lượng"},{"pos":"v.","en":"To break down chemically into simpler substances","vi":"phân hủy; giảm phân"},{"pos":"v.","en":"To treat someone as though they deserve no respect","vi":"làm mất nhân phẩm; hạ nhục"}],"examples":[{"en":"Strong sunlight can degrade the fabric of outdoor chairs.","vi":"Ánh nắng mạnh có thể làm hỏng chất liệu vải của ghế ngoài trời.","audioKind":"ex"},{"en":"Intensive farming can degrade soil quality, making it harder to grow healthy crops in the future.","vi":"Nông nghiệp thâm canh có thể làm giảm chất lượng đất, khiến cho việc trồng trọt các loại cây khỏe mạnh trong tương lai trở nên khó khăn hơn.","audioKind":"ex2"}],"collocations":[{"en":"degrade soil quality","vi":"làm giảm chất lượng đất"},{"en":"degrade the environment","vi":"làm suy thoái môi trường"},{"en":"degrade over time","vi":"phân hủy theo thời gian"}],"wordFamily":["degradation (n.)","degradable (adj.)","degrading (adj.)"],"synonyms":["deteriorate","damage"],"antonyms":[],"tipVi":"Chỉ sự sụt giảm chất lượng có thể dùng ngoại động từ; sự phân hủy hóa học cũng có thể dùng nội động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_submerge', 'en-c1-20', 'submerge', '/səbˈmɜːrdʒ/', 'C1', 'nhấn chìm; dìm xuống nước; ngập hẳn', 'v.', 'submersion (n.), submerged (adj.), submersible (adj.)', 'Đồng nghĩa: immerse', 'Có thể dùng như ngoại động từ hoặc nội động từ; nhấn mạnh hành động đi xuống dưới bề mặt nước hoặc chất lỏng.', 'Submerge the dirty jar in warm water before washing it.', NULL, 'Nhấn chìm cái lọ bẩn vào nước ấm trước khi cọ rửa nó.', '{"wordId":"submerge","ukIpa":"/səbˈmɜːdʒ/","usIpa":"/səbˈmɜːrdʒ/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"To go below a liquid''s surface or put something there","vi":"nhấn chìm; dìm xuống nước; ngập hẳn"}],"examples":[{"en":"Submerge the dirty jar in warm water before washing it.","vi":"Nhấn chìm cái lọ bẩn vào nước ấm trước khi cọ rửa nó.","audioKind":"ex"},{"en":"Rising sea levels could submerge low-lying coastal settlements, forcing residents to relocate and placing pressure on nearby cities.","vi":"Mực nước biển dâng cao có thể làm ngập các khu dân cư ven biển thấp trũng, buộc người dân phải di dời và gây áp lực cho các thành phố lân cận.","audioKind":"ex2"}],"collocations":[{"en":"fully submerge","vi":"nhấn chìm hoàn toàn"},{"en":"submerge in water","vi":"nhúng chìm trong nước"},{"en":"partially submerged","vi":"bị ngập một phần"}],"wordFamily":["submersion (n.)","submerged (adj.)","submersible (adj.)"],"synonyms":["immerse"],"antonyms":[],"tipVi":"Có thể dùng như ngoại động từ hoặc nội động từ; nhấn mạnh hành động đi xuống dưới bề mặt nước hoặc chất lỏng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_finite', 'en-c1-20', 'finite', '/ˈfaɪnaɪt/', 'C1', 'có hạn; có giới hạn; hữu hạn (chỉ dạng động từ bị giới hạn bởi ngôi và số)', 'adj.', 'infinite (adj.), finiteness (n.)', 'Đồng nghĩa: limited, bounded · Trái nghĩa: infinite, unlimited', 'Trọng âm rơi vào âm tiết đầu tiên; tránh đọc nhầm theo vần của từ finish.', 'Our holiday budget is finite, so choose carefully.', NULL, 'Ngân sách du lịch của chúng ta có hạn, nên hãy lựa chọn thật kỹ.', '{"wordId":"finite","ukIpa":"/ˈfaɪnaɪt/","usIpa":"/ˈfaɪnaɪt/","cefr":"C1","topic":"environment","senses":[{"pos":"adj.","en":"Having a limit in size, amount, or duration","vi":"có hạn; có giới hạn"},{"pos":"adj.","en":"Having tense and sometimes showing person or number","vi":"hữu hạn (chỉ dạng động từ bị giới hạn bởi ngôi và số)"}],"examples":[{"en":"Our holiday budget is finite, so choose carefully.","vi":"Ngân sách du lịch của chúng ta có hạn, nên hãy lựa chọn thật kỹ.","audioKind":"ex"},{"en":"Governments must recognise that natural resources are finite and encourage industries to reduce unnecessary consumption.","vi":"Chính phủ phải nhận thức rõ rằng tài nguyên thiên nhiên là có hạn và khuyến khích các ngành công nghiệp giảm thiểu mức tiêu thụ lãng phí.","audioKind":"ex2"}],"collocations":[{"en":"finite resources","vi":"tài nguyên hữu hạn"},{"en":"a finite amount","vi":"một lượng có hạn"},{"en":"a finite verb","vi":"động từ hữu hạn"}],"wordFamily":["infinite (adj.)","finiteness (n.)"],"synonyms":["limited","bounded"],"antonyms":["infinite","unlimited"],"tipVi":"Trọng âm rơi vào âm tiết đầu tiên; tránh đọc nhầm theo vần của từ finish.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cultivate', 'en-c1-20', 'cultivate', '/ˈkʌltɪveɪt/', 'C1', 'cày cấy, trồng trọt; bồi dưỡng, phát triển (kỹ năng, phẩm chất, sở thích hoặc mối quan hệ)', 'v.', 'cultivation (n.), cultivator (n.), cultivated (adj.)', 'Đồng nghĩa: grow, nurture', 'Có thể dùng để chỉ việc trồng cây hoặc chủ động bồi đắp sở thích, quan hệ.', 'My grandparents cultivate vegetables in a small garden behind their house.', NULL, 'Ông bà tôi trồng rau trong một mảnh vườn nhỏ phía sau nhà.', '{"wordId":"cultivate","ukIpa":"/ˈkʌltɪveɪt/","usIpa":"/ˈkʌltɪveɪt/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"To prepare land for crops or grow plants","vi":"cày cấy, trồng trọt"},{"pos":"v.","en":"To deliberately develop a skill, quality, interest, or relationship","vi":"bồi dưỡng, phát triển (kỹ năng, phẩm chất, sở thích hoặc mối quan hệ)"}],"examples":[{"en":"My grandparents cultivate vegetables in a small garden behind their house.","vi":"Ông bà tôi trồng rau trong một mảnh vườn nhỏ phía sau nhà.","audioKind":"ex"},{"en":"Schools should cultivate curiosity by encouraging students to ask questions and explore different solutions to practical problems.","vi":"Nhà trường nên khuyến khích học sinh đặt câu hỏi và khám phá các giải pháp khác nhau cho những vấn đề thực tế nhằm nuôi dưỡng trí tò mò.","audioKind":"ex2"}],"collocations":[{"en":"cultivate crops","vi":"trồng trọt hoa màu"},{"en":"cultivate the land","vi":"khẩn hoang đất đai"},{"en":"cultivate an interest in","vi":"nuôi dưỡng sở thích về"},{"en":"cultivate relationships","vi":"gìn giữ và phát triển mối quan hệ"}],"wordFamily":["cultivation (n.)","cultivator (n.)","cultivated (adj.)"],"synonyms":["grow","nurture"],"antonyms":[],"tipVi":"Có thể dùng để chỉ việc trồng cây hoặc chủ động bồi đắp sở thích, quan hệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_barren', 'en-c1-20', 'barren', '/ˈbærən/', 'C1', 'cằn cỗi; không màu mỡ; vô ích; không mang lại kết quả; thiếu thốn', 'adj.', 'barrenness (n.)', 'Đồng nghĩa: unproductive, infertile · Trái nghĩa: fertile, productive', 'barren nhấn mạnh việc không thể sinh trưởng hoặc không có sản lượng; bare nhấn mạnh sự trơ trọi, không che chắn.', 'Only a few bushes grew on the barren hillside.', NULL, 'Chỉ có vài bụi cây mọc trên sườn đồi cằn cỗi.', '{"wordId":"barren","ukIpa":"/ˈbærən/","usIpa":"/ˈbærən/","cefr":"C1","topic":"environment","senses":[{"pos":"adj.","en":"Unable to support much plant growth.","vi":"cằn cỗi; không màu mỡ"},{"pos":"adj.","en":"Producing nothing useful or lacking something important.","vi":"vô ích; không mang lại kết quả; thiếu thốn"}],"examples":[{"en":"Only a few bushes grew on the barren hillside.","vi":"Chỉ có vài bụi cây mọc trên sườn đồi cằn cỗi.","audioKind":"ex"},{"en":"Unsustainable farming can turn productive fields into barren land, threatening food security and forcing rural communities to relocate.","vi":"Canh tác không bền vững có thể biến những cánh đồng màu mỡ thành đất hoang, đe dọa an ninh lương thực và buộc các cộng đồng nông thôn phải di dời.","audioKind":"ex2"}],"collocations":[{"en":"barren land","vi":"đất hoang"},{"en":"barren landscape","vi":"cảnh quan hoang vu"},{"en":"barren of","vi":"thiếu vắng..."}],"wordFamily":["barrenness (n.)"],"synonyms":["unproductive","infertile"],"antonyms":["fertile","productive"],"tipVi":"barren nhấn mạnh việc không thể sinh trưởng hoặc không có sản lượng; bare nhấn mạnh sự trơ trọi, không che chắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_desertification', 'en-c1-20', 'desertification', '/dɪˌzɝːtɪfɪˈkeɪʃən/', 'C1', 'sa mạc hóa; hoang mạc hóa', 'n.', 'desert (n.)', NULL, 'Là danh từ không đếm được; nhấn mạnh quá trình đất đai dần suy thoái thành hoang mạc.', 'Desertification has left the fields around our village bare.', NULL, 'Quá trình sa mạc hóa đã khiến các cánh đồng xung quanh làng chúng tôi trở nên trơ trọi.', '{"wordId":"desertification","ukIpa":"/dɪˌzɜːtɪfɪˈkeɪʃən/","usIpa":"/dɪˌzɝːtɪfɪˈkeɪʃən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"the process by which productive land becomes desert","vi":"sa mạc hóa; hoang mạc hóa"}],"examples":[{"en":"Desertification has left the fields around our village bare.","vi":"Quá trình sa mạc hóa đã khiến các cánh đồng xung quanh làng chúng tôi trở nên trơ trọi.","audioKind":"ex"},{"en":"Sustainable farming practices can slow desertification by protecting soil and preserving vegetation in dry regions.","vi":"Các phương pháp canh tác bền vững có thể làm chậm quá trình sa mạc hóa bằng cách bảo vệ đất và duy trì thảm thực vật ở các vùng khô hạn.","audioKind":"ex2"}],"collocations":[{"en":"combat desertification","vi":"chống lại sa mạc hóa"},{"en":"prevent desertification","vi":"ngăn chặn sa mạc hóa"},{"en":"land degradation and desertification","vi":"suy thoái đất và sa mạc hóa"}],"wordFamily":["desert (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; nhấn mạnh quá trình đất đai dần suy thoái thành hoang mạc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_salvage', 'en-c1-20', 'salvage', '/ˈsælvɪdʒ/', 'C1', 'cứu hộ; trục vớt; thu hồi; cứu vãn; vớt vát; tài sản cứu được; vật liệu trục vớt', 'v.', 'salvageable (adj.)', 'Đồng nghĩa: recover, save', 'Thường chỉ việc cứu vãn tài sản; cứu người thường dùng rescue.', 'We managed to salvage some books after the flood.', NULL, 'Chúng tôi đã cố gắng cứu vãn một số cuốn sách sau trận lụt.', '{"wordId":"salvage","ukIpa":"/ˈsælvɪdʒ/","usIpa":"/ˈsælvɪdʒ/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"To save useful things from damage, loss, or destruction.","vi":"cứu hộ; trục vớt; thu hồi"},{"pos":"v.","en":"To prevent a situation or effort from failing completely.","vi":"cứu vãn; vớt vát"},{"pos":"n.","en":"The recovery of damaged property, or the property recovered.","vi":"tài sản cứu được; vật liệu trục vớt"}],"examples":[{"en":"We managed to salvage some books after the flood.","vi":"Chúng tôi đã cố gắng cứu vãn một số cuốn sách sau trận lụt.","audioKind":"ex"},{"en":"Construction companies can salvage valuable materials from old buildings, reducing waste and demand for new resources.","vi":"Các công ty xây dựng có thể thu hồi các vật liệu có giá trị từ những tòa nhà cũ, qua đó giảm thiểu rác thải và nhu cầu về tài nguyên mới.","audioKind":"ex2"}],"collocations":[{"en":"salvage materials","vi":"thu hồi vật liệu"},{"en":"salvage operation","vi":"hoạt động cứu hộ trục vớt"},{"en":"salvage a reputation","vi":"cứu vãn danh dự"}],"wordFamily":["salvageable (adj.)"],"synonyms":["recover","save"],"antonyms":[],"tipVi":"Thường chỉ việc cứu vãn tài sản; cứu người thường dùng rescue.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intensify', 'en-c1-20', 'intensify', '/ɪnˈtensɪfaɪ/', 'C1', 'trở nên mạnh hơn; gia tăng; làm cho gay gắt hơn', 'v.', 'intense (adj.), intensity (n.), intensification (n.), intensely (adv.)', 'Đồng nghĩa: strengthen, heighten · Trái nghĩa: weaken, ease', 'Có thể đi trực tiếp với tân ngữ hoặc dùng nội động từ: bản thân áp lực cũng có thể tự gia tăng.', 'The rain intensified as we hurried towards the station.', NULL, 'Cơn mưa càng lúc càng nặng hạt khi chúng tôi vội vã chạy về phía nhà ga.', '{"wordId":"intensify","ukIpa":"/ɪnˈtensɪfaɪ/","usIpa":"/ɪnˈtensɪfaɪ/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"become stronger or more extreme, or make something so","vi":"trở nên mạnh hơn; gia tăng; làm cho gay gắt hơn"}],"examples":[{"en":"The rain intensified as we hurried towards the station.","vi":"Cơn mưa càng lúc càng nặng hạt khi chúng tôi vội vã chạy về phía nhà ga.","audioKind":"ex"},{"en":"Rising temperatures may intensify water shortages in regions that already experience long periods of drought.","vi":"Nhiệt độ tăng cao có thể làm trầm trọng thêm tình trạng thiếu nước ở những khu vực vốn đã trải qua mùa hạn hán kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"intensify efforts","vi":"đẩy mạnh nỗ lực"},{"en":"intensify pressure","vi":"gia tăng áp lực"},{"en":"competition intensifies","vi":"cạnh tranh gay gắt"}],"wordFamily":["intense (adj.)","intensity (n.)","intensification (n.)","intensely (adv.)"],"synonyms":["strengthen","heighten"],"antonyms":["weaken","ease"],"tipVi":"Có thể đi trực tiếp với tân ngữ hoặc dùng nội động từ: bản thân áp lực cũng có thể tự gia tăng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blaze', 'en-c1-20', 'blaze', '/bleɪz/', 'C1', 'đám cháy lớn; ngọn lửa lớn; cháy dữ dội; chiếu sáng rực rỡ', 'n.', 'blazing (adj.)', 'Đồng nghĩa: fire, burn', 'blaze thường chỉ đám cháy lớn và dữ dội; flame chỉ ngọn lửa thông thường.', 'Firefighters rescued the family from the blaze last night.', NULL, 'Lực lượng cứu họa đã giải cứu gia đình khỏi vụ hỏa hoạn lớn vào tối qua.', '{"wordId":"blaze","ukIpa":"/bleɪz/","usIpa":"/bleɪz/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"a large, strong fire","vi":"đám cháy lớn; ngọn lửa lớn"},{"pos":"v.","en":"to burn fiercely or shine very brightly","vi":"cháy dữ dội; chiếu sáng rực rỡ"}],"examples":[{"en":"Firefighters rescued the family from the blaze last night.","vi":"Lực lượng cứu họa đã giải cứu gia đình khỏi vụ hỏa hoạn lớn vào tối qua.","audioKind":"ex"},{"en":"The forest blaze destroyed valuable habitats, highlighting the need for better fire prevention strategies.","vi":"Đám cháy rừng đã phá hủy các sinh cảnh quý giá, làm nổi bật sự cần thiết của các chiến lược phòng chống cháy tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"fight a blaze","vi":"chữa cháy; dập lửa lớn"},{"en":"a forest blaze","vi":"một đám cháy rừng"},{"en":"blaze a trail","vi":"mở đường; tiên phong khám phá"}],"wordFamily":["blazing (adj.)"],"synonyms":["fire","burn"],"antonyms":[],"tipVi":"blaze thường chỉ đám cháy lớn và dữ dội; flame chỉ ngọn lửa thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_haven', 'en-c1-20', 'haven', '/ˈheɪvən/', 'C1', 'nơi trú ẩn an toàn; chốn bình yên', 'n.', NULL, 'Đồng nghĩa: refuge, sanctuary', 'Thường dùng cấu trúc a haven for; cần chú ý phân biệt với heaven (thiên đường).', 'Our little garden is a haven from city noise.', NULL, 'Khu vườn nhỏ của chúng tôi là chốn bình yên tránh xa sự ồn ào của thành phố.', '{"wordId":"haven","ukIpa":"/ˈheɪvən/","usIpa":"/ˈheɪvən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"a safe or peaceful place away from danger or trouble","vi":"nơi trú ẩn an toàn; chốn bình yên"}],"examples":[{"en":"Our little garden is a haven from city noise.","vi":"Khu vườn nhỏ của chúng tôi là chốn bình yên tránh xa sự ồn ào của thành phố.","audioKind":"ex"},{"en":"Protected wetlands provide a safe haven for wildlife threatened by habitat loss and urban expansion.","vi":"Các vùng đất ngập nước được bảo vệ cung cấp nơi trú ẩn an toàn cho động vật hoang dã đang bị đe dọa bởi tình trạng mất môi trường sống và sự mở rộng đô thị.","audioKind":"ex2"}],"collocations":[{"en":"safe haven","vi":"nơi trú ẩn an toàn"},{"en":"haven for wildlife","vi":"nơi trú ẩn cho động vật hoang dã"},{"en":"haven of peace","vi":"chốn bình yên thanh thản"}],"wordFamily":[],"synonyms":["refuge","sanctuary"],"antonyms":[],"tipVi":"Thường dùng cấu trúc a haven for; cần chú ý phân biệt với heaven (thiên đường).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whaling', 'en-c1-20', 'whaling', '/ˈweɪlɪŋ/', 'C1', 'hoạt động săn bắt cá voi; ngành công nghiệp săn bắt cá voi', 'n.', 'whale (n.), whale (v.), whaler (n.)', NULL, 'Là danh từ không đếm được; khi nói về lệnh cấm săn bắt cá voi dùng "ban on whaling".', 'The harbour museum has an exhibition about whaling.', NULL, 'Viện bảo tàng bên cảng có một cuộc triển lãm về hoạt động săn bắt cá voi.', '{"wordId":"whaling","ukIpa":"/ˈweɪlɪŋ/","usIpa":"/ˈweɪlɪŋ/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"the activity or business of hunting whales","vi":"hoạt động săn bắt cá voi; ngành công nghiệp săn bắt cá voi"}],"examples":[{"en":"The harbour museum has an exhibition about whaling.","vi":"Viện bảo tàng bên cảng có một cuộc triển lãm về hoạt động săn bắt cá voi.","audioKind":"ex"},{"en":"Commercial whaling has contributed to declining whale populations, prompting international efforts to protect these marine mammals.","vi":"Ngành săn bắt cá voi thương mại đã góp phần làm sụt giảm số lượng cá voi, thúc đẩy các nỗ lực quốc tế nhằm bảo vệ những loài động vật có vú ở biển này.","audioKind":"ex2"}],"collocations":[{"en":"commercial whaling","vi":"săn bắt cá voi thương mại"},{"en":"whaling ship","vi":"tàu bắt cá voi"},{"en":"whaling industry","vi":"ngành công nghiệp săn bắt cá voi"},{"en":"ban on whaling","vi":"lệnh cấm săn bắt cá voi"}],"wordFamily":["whale (n.)","whale (v.)","whaler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; khi nói về lệnh cấm săn bắt cá voi dùng \"ban on whaling\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_engulf', 'en-c1-20', 'engulf', '/ɪnˈɡʌlf/', 'C1', 'nuốt chửng; bao trùm hoàn toàn; làm ngập chìm; áp đảo', 'v.', 'engulfment (n.)', 'Đồng nghĩa: envelop, swallow, overwhelm', 'Thường dùng ở dạng bị động be engulfed in/by để nhấn mạnh sự bao phủ hoàn toàn.', 'A sudden wave engulfed our sandcastle on the beach.', NULL, 'Một con sóng bất ngờ đã nuốt chửng lâu đài cát của chúng tôi trên bãi biển.', '{"wordId":"engulf","ukIpa":"/ɪnˈɡʌlf/","usIpa":"/ɪnˈɡʌlf/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"to surround or cover something completely","vi":"nuốt chửng; bao trùm hoàn toàn"},{"pos":"v.","en":"to overwhelm someone or something with a powerful situation","vi":"làm ngập chìm; áp đảo"}],"examples":[{"en":"A sudden wave engulfed our sandcastle on the beach.","vi":"Một con sóng bất ngờ đã nuốt chửng lâu đài cát của chúng tôi trên bãi biển.","audioKind":"ex"},{"en":"Rising sea levels could engulf low-lying coastal settlements unless governments invest in effective flood protection.","vi":"Mực nước biển dâng cao có thể nhấn chìm các khu dân cư ven biển thấp nếu các chính phủ không đầu tư vào các biện pháp phòng chống lũ lụt hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"be engulfed in flames","vi":"bị biển lửa nuốt chửng"},{"en":"be engulfed by floodwater","vi":"bị dòng nước lũ nhấn chìm"},{"en":"a crisis engulfs a country","vi":"một cuộc khủng hoảng bao trùm một quốc gia"}],"wordFamily":["engulfment (n.)"],"synonyms":["envelop","swallow","overwhelm"],"antonyms":[],"tipVi":"Thường dùng ở dạng bị động be engulfed in/by để nhấn mạnh sự bao phủ hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_degradation', 'en-c1-20', 'degradation', '/ˌdeɡrəˈdeɪʃən/', 'C1', 'sự suy thoái; sự xuống cấp; sự hư hại về chất lượng; sự phân hủy thành các chất đơn giản hơn; sự hạ nhục; tình trạng mất phẩm giá do đối xử lăng mạ', 'n.', 'degrade (v.), degradable (adj.), degrading (adj.)', 'Đồng nghĩa: deterioration · Trái nghĩa: improvement', 'Trong chủ đề môi trường, từ này thường chỉ sự suy thoái, còn trong ngữ cảnh hóa học hoặc sinh học có thể dịch là sự phân hủy/giáng hóa.', 'The farmer noticed soil degradation across his dry fields.', NULL, 'Người nông dân nhận thấy tình trạng suy thoái đất trên khắp những cánh đồng khô cằn của ông ấy.', '{"wordId":"degradation","ukIpa":"/ˌdeɡrəˈdeɪʃən/","usIpa":"/ˌdeɡrəˈdeɪʃən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"The process of becoming damaged or poorer in quality.","vi":"sự suy thoái; sự xuống cấp; sự hư hại về chất lượng"},{"pos":"n.","en":"The breakdown of a substance into simpler substances.","vi":"sự phân hủy thành các chất đơn giản hơn"},{"pos":"n.","en":"The loss of dignity caused by humiliating treatment.","vi":"sự hạ nhục; tình trạng mất phẩm giá do đối xử lăng mạ"}],"examples":[{"en":"The farmer noticed soil degradation across his dry fields.","vi":"Người nông dân nhận thấy tình trạng suy thoái đất trên khắp những cánh đồng khô cằn của ông ấy.","audioKind":"ex"},{"en":"Environmental degradation often affects poorer communities most severely because they depend directly on local natural resources.","vi":"Sự suy thoái môi trường thường tác động nặng nề nhất đến các cộng đồng nghèo hơn vì họ phụ thuộc trực tiếp vào tài nguyên thiên nhiên địa phương.","audioKind":"ex2"}],"collocations":[{"en":"environmental degradation","vi":"suy thoái môi trường"},{"en":"soil degradation","vi":"suy thoái đất"},{"en":"microbial degradation","vi":"phân hủy sinh học"}],"wordFamily":["degrade (v.)","degradable (adj.)","degrading (adj.)"],"synonyms":["deterioration"],"antonyms":["improvement"],"tipVi":"Trong chủ đề môi trường, từ này thường chỉ sự suy thoái, còn trong ngữ cảnh hóa học hoặc sinh học có thể dịch là sự phân hủy/giáng hóa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quarry', 'en-c1-20', 'quarry', '/ˈkwɔːri/', 'C1', 'mỏ đá; công trường khai thác đá; khai thác đá; con mồi; mục tiêu truy đuổi', 'n.', 'quarrying (n.)', NULL, 'Nghĩa mỏ đá là danh từ đếm được; nghĩa con mồi thường dùng dạng số ít.', 'Huge trucks carried pale stone out of the quarry.', NULL, 'Những chiếc xe tải khổng lồ chở những khối đá màu nhạt ra khỏi mỏ đá.', '{"wordId":"quarry","ukIpa":"/ˈkwɒri/","usIpa":"/ˈkwɔːri/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"A large open pit where stone is dug from the ground.","vi":"mỏ đá; công trường khai thác đá"},{"pos":"v.","en":"To dig stone out of the ground.","vi":"khai thác đá"},{"pos":"n.","en":"An animal or person being hunted or pursued.","vi":"con mồi; mục tiêu truy đuổi"}],"examples":[{"en":"Huge trucks carried pale stone out of the quarry.","vi":"Những chiếc xe tải khổng lồ chở những khối đá màu nhạt ra khỏi mỏ đá.","audioKind":"ex"},{"en":"Restoring an abandoned quarry can create valuable wildlife habitats while reducing risks to nearby communities.","vi":"Việc phục hồi một mỏ đá bị bỏ hoang có thể tạo ra môi trường sống có giá trị cho động vật hoang dã đồng thời giảm thiểu rủi ro cho các cộng đồng dân cư lân cận.","audioKind":"ex2"}],"collocations":[{"en":"stone quarry","vi":"mỏ đá"},{"en":"disused quarry","vi":"mỏ đá bị bỏ hoang"},{"en":"quarry limestone","vi":"khai thác đá vôi"}],"wordFamily":["quarrying (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa mỏ đá là danh từ đếm được; nghĩa con mồi thường dùng dạng số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dwindle', 'en-c1-20', 'dwindle', '/ˈdwɪndəl/', 'C1', 'giảm dần; thu hẹp dần', 'v.', NULL, 'Đồng nghĩa: decrease, diminish, shrink · Trái nghĩa: increase, grow', 'Là nội động từ, nhấn mạnh sự giảm dần theo thời gian, không trực tiếp đi kèm tân ngữ.', 'Our savings dwindled while we searched for new jobs.', NULL, 'Khoản tiết kiệm của chúng tôi giảm dần trong lúc chúng tôi tìm kiếm công việc mới.', '{"wordId":"dwindle","ukIpa":"/ˈdwɪndəl/","usIpa":"/ˈdwɪndəl/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"Gradually become smaller in amount, size, or number.","vi":"giảm dần; thu hẹp dần"}],"examples":[{"en":"Our savings dwindled while we searched for new jobs.","vi":"Khoản tiết kiệm của chúng tôi giảm dần trong lúc chúng tôi tìm kiếm công việc mới.","audioKind":"ex"},{"en":"As freshwater supplies dwindle, governments must invest in efficient irrigation and encourage households to reduce unnecessary consumption.","vi":"Khi nguồn cung cấp nước ngọt ngày càng cạn kiệt, chính phủ phải đầu tư vào hệ thống tưới tiêu hiệu quả và khuyến khích các hộ gia đình giảm mức tiêu thụ không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"dwindling resources","vi":"tài nguyên ngày càng cạn kiệt"},{"en":"dwindling numbers","vi":"số lượng giảm dần"},{"en":"dwindle to nothing","vi":"giảm dần về không"}],"wordFamily":[],"synonyms":["decrease","diminish","shrink"],"antonyms":["increase","grow"],"tipVi":"Là nội động từ, nhấn mạnh sự giảm dần theo thời gian, không trực tiếp đi kèm tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depletion', 'en-c1-20', 'depletion', '/dɪˈpliːʃən/', 'C1', 'sự cạn kiệt; sự suy giảm', 'n.', 'deplete (v.), depleted (adj.)', 'Trái nghĩa: replenishment', 'Thường đi với of, chỉ tài nguyên hoặc dự trữ bị giảm bớt, không nhất thiết đã cạn kiệt hoàn toàn.', 'The garden''s poor growth suggested depletion of soil nutrients.', NULL, 'Tình trạng còi cọc của khu vườn cho thấy chất dinh dưỡng trong đất đã bị suy giảm.', '{"wordId":"depletion","ukIpa":"/dɪˈpliːʃən/","usIpa":"/dɪˈpliːʃən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"A reduction in the amount of something available","vi":"sự cạn kiệt; sự suy giảm"}],"examples":[{"en":"The garden''s poor growth suggested depletion of soil nutrients.","vi":"Tình trạng còi cọc của khu vườn cho thấy chất dinh dưỡng trong đất đã bị suy giảm.","audioKind":"ex"},{"en":"Rapid depletion of groundwater threatens agricultural production in regions where rainfall is increasingly unpredictable.","vi":"Tình trạng cạn kiệt nhanh chóng của nguồn nước ngầm đang đe dọa sản xuất nông nghiệp ở những vùng có lượng mưa ngày càng khó đoán.","audioKind":"ex2"}],"collocations":[{"en":"resource depletion","vi":"sự cạn kiệt tài nguyên"},{"en":"ozone depletion","vi":"sự suy giảm tầng ô-dôn"},{"en":"depletion of reserves","vi":"sự cạn kiệt trữ lượng"}],"wordFamily":["deplete (v.)","depleted (adj.)"],"synonyms":[],"antonyms":["replenishment"],"tipVi":"Thường đi với of, chỉ tài nguyên hoặc dự trữ bị giảm bớt, không nhất thiết đã cạn kiệt hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incineration', 'en-c1-20', 'incineration', '/ɪnˌsɪnəˈreɪʃn/', 'C1', 'sự thiêu hủy; sự đốt rác', 'n.', 'incinerate (v.), incinerator (n.)', NULL, 'Thường là danh từ không đếm được, hay dùng trong chủ đề xử lý rác thải.', 'The hospital sends certain waste away for incineration.', NULL, 'Bệnh viện gửi một số loại rác thải đi để xử lý thiêu hủy.', '{"wordId":"incineration","ukIpa":"/ɪnˌsɪnəˈreɪʃn/","usIpa":"/ɪnˌsɪnəˈreɪʃn/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"The process of burning waste until it becomes ash.","vi":"sự thiêu hủy; sự đốt rác"}],"examples":[{"en":"The hospital sends certain waste away for incineration.","vi":"Bệnh viện gửi một số loại rác thải đi để xử lý thiêu hủy.","audioKind":"ex"},{"en":"Waste incineration can generate electricity, but strict controls are needed to limit harmful emissions.","vi":"Việc đốt rác thải có thể tạo ra điện, nhưng cần có các biện pháp kiểm soát nghiêm ngặt để hạn chế khí thải độc hại.","audioKind":"ex2"}],"collocations":[{"en":"waste incineration","vi":"đốt rác thải"},{"en":"incineration plant","vi":"nhà máy đốt rác"},{"en":"incineration process","vi":"quá trình thiêu hủy"}],"wordFamily":["incinerate (v.)","incinerator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được, hay dùng trong chủ đề xử lý rác thải.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mitigate', 'en-c1-20', 'mitigate', '/ˈmɪtɪɡeɪt/', 'C1', 'làm dịu bớt; giảm nhẹ; làm giảm thiểu', 'v.', 'mitigation (n.), mitigating (adj.)', 'Đồng nghĩa: alleviate, lessen, ease · Trái nghĩa: aggravate, exacerbate', 'Đây là từ mang tính trang trọng, thường kết hợp trực tiếp với rủi ro, tổn thất hoặc ảnh hưởng chứ không mang nghĩa xóa bỏ hoàn toàn.', 'Thick curtains helped mitigate the noise from the street.', NULL, 'Bộ rèm cửa dày giúp làm giảm tiếng ồn từ ngoài đường.', '{"wordId":"mitigate","ukIpa":"/ˈmɪtɪɡeɪt/","usIpa":"/ˈmɪtɪɡeɪt/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"To make something harmful, unpleasant, or serious less severe","vi":"làm dịu bớt; giảm nhẹ; làm giảm thiểu"}],"examples":[{"en":"Thick curtains helped mitigate the noise from the street.","vi":"Bộ rèm cửa dày giúp làm giảm tiếng ồn từ ngoài đường.","audioKind":"ex"},{"en":"Planting trees in urban areas can mitigate the effects of extreme heat and improve residents'' quality of life.","vi":"Việc trồng cây ở khu vực đô thị có thể làm giảm tác động của nắng nóng cực đoan và cải thiện chất lượng cuộc sống của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"mitigate the effects of","vi":"giảm thiểu ảnh hưởng của"},{"en":"mitigate risks","vi":"giảm thiểu rủi ro"},{"en":"mitigate climate change","vi":"làm giảm biến đổi khí hậu"},{"en":"mitigating circumstances","vi":"các tình tiết giảm nhẹ"}],"wordFamily":["mitigation (n.)","mitigating (adj.)"],"synonyms":["alleviate","lessen","ease"],"antonyms":["aggravate","exacerbate"],"tipVi":"Đây là từ mang tính trang trọng, thường kết hợp trực tiếp với rủi ro, tổn thất hoặc ảnh hưởng chứ không mang nghĩa xóa bỏ hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lumber', 'en-c1-20', 'lumber', '/ˈlʌmbɚ/', 'C1', 'gỗ xẻ; gỗ thành phẩm; di chuyển nặng nề, chậm chạp', 'n.', 'lumbering (adj.)', 'Đồng nghĩa: timber', 'Nghĩa gỗ (lumber) dùng nhiều trong tiếng Anh Mỹ, tiếng Anh Anh thường dùng timber.', 'We bought some lumber to build a garden bench.', NULL, 'Chúng tôi đã mua một ít gỗ xẻ để làm chiếc ghế dài trong vườn.', '{"wordId":"lumber","ukIpa":"/ˈlʌmbə/","usIpa":"/ˈlʌmbɚ/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"Wood cut into pieces for building, especially in American English.","vi":"gỗ xẻ; gỗ thành phẩm"},{"pos":"v.","en":"To move slowly and awkwardly because of weight or size.","vi":"di chuyển nặng nề, chậm chạp"}],"examples":[{"en":"We bought some lumber to build a garden bench.","vi":"Chúng tôi đã mua một ít gỗ xẻ để làm chiếc ghế dài trong vườn.","audioKind":"ex"},{"en":"Demand for sustainably sourced lumber can encourage forest owners to adopt more responsible management practices.","vi":"Nhu cầu về gỗ xẻ có nguồn gốc bền vững có thể khuyến khích các chủ rừng áp dụng các phương pháp quản lý có trách nhiệm hơn.","audioKind":"ex2"}],"collocations":[{"en":"a lumber yard","vi":"bãi tập kết gỗ"},{"en":"a stack of lumber","vi":"một chồng gỗ xẻ"},{"en":"lumber along","vi":"di chuyển nặng nề"}],"wordFamily":["lumbering (adj.)"],"synonyms":["timber"],"antonyms":[],"tipVi":"Nghĩa gỗ (lumber) dùng nhiều trong tiếng Anh Mỹ, tiếng Anh Anh thường dùng timber.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mangrove', 'en-c1-20', 'mangrove', '/ˈmæŋɡroʊv/', 'C1', 'cây đước; cây mắm; rừng ngập mặn', 'n.', NULL, NULL, 'Có thể chỉ một cây; rừng ngập mặn thường gọi là mangrove forest.', 'Small fish sheltered among the roots of a mangrove.', NULL, 'Những chú cá nhỏ trú ẩn giữa các rễ cây đước.', '{"wordId":"mangrove","ukIpa":"/ˈmæŋɡrəʊv/","usIpa":"/ˈmæŋɡroʊv/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"A tropical coastal tree with roots growing in salty water","vi":"cây đước; cây mắm; rừng ngập mặn"}],"examples":[{"en":"Small fish sheltered among the roots of a mangrove.","vi":"Những chú cá nhỏ trú ẩn giữa các rễ cây đước.","audioKind":"ex"},{"en":"Mangrove forests protect coastal communities from storms while providing essential habitats for numerous marine species.","vi":"Rừng ngập mặn bảo vệ các cộng đồng ven biển khỏi bão đồng thời cung cấp môi trường sống thiết yếu cho nhiều loài sinh vật biển.","audioKind":"ex2"}],"collocations":[{"en":"mangrove forest","vi":"rừng ngập mặn"},{"en":"mangrove roots","vi":"hệ thống rễ cây đước"},{"en":"mangrove conservation","vi":"bảo vệ rừng ngập mặn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ một cây; rừng ngập mặn thường gọi là mangrove forest.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peril', 'en-c1-20', 'peril', '/ˈperəl/', 'C1', 'hiểm họa; sự nguy hiểm nghiêm trọng', 'n.', 'perilous (adj.), perilously (adv.)', 'Đồng nghĩa: danger, hazard · Trái nghĩa: safety', 'Mang tính trang trọng hơn danger, thường dùng cụm in peril để chỉ việc đang lâm vào cảnh hiểm nghèo.', 'The sudden storm put the small boat in peril.', NULL, 'Cơn bão bất ngờ đẩy chiếc thuyền nhỏ vào tình thế hiểm nghèo.', '{"wordId":"peril","ukIpa":"/ˈperəl/","usIpa":"/ˈperəl/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"serious danger or a situation involving serious danger","vi":"hiểm họa; sự nguy hiểm nghiêm trọng"}],"examples":[{"en":"The sudden storm put the small boat in peril.","vi":"Cơn bão bất ngờ đẩy chiếc thuyền nhỏ vào tình thế hiểm nghèo.","audioKind":"ex"},{"en":"Coastal communities face increasing peril as rising sea levels threaten their homes and essential infrastructure.","vi":"Các cộng đồng ven biển phải đối mặt với nguy hiểm ngày càng gia tăng khi mực nước biển dâng cao đe dọa nhà cửa và cơ sở hạ tầng thiết yếu của họ.","audioKind":"ex2"}],"collocations":[{"en":"in peril","vi":"lâm vào cảnh hiểm nghèo"},{"en":"put someone in peril","vi":"đẩy ai vào tình thế nguy hiểm"},{"en":"the perils of","vi":"những mối nguy hiểm của"}],"wordFamily":["perilous (adj.)","perilously (adv.)"],"synonyms":["danger","hazard"],"antonyms":["safety"],"tipVi":"Mang tính trang trọng hơn danger, thường dùng cụm in peril để chỉ việc đang lâm vào cảnh hiểm nghèo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_encroach', 'en-c1-20', 'encroach', '/ɪnˈkroʊtʃ/', 'C1', 'xâm lấn dần; xâm phạm', 'v.', 'encroachment (n)', 'Đồng nghĩa: intrude', 'Là nội động từ, thường đi với giới từ on/upon, nhấn mạnh tính chất xâm lấn từ từ.', 'The neighbour''s bushes are beginning to encroach on our garden.', NULL, 'Mấy bụi cây của nhà hàng xóm đang bắt đầu lấn sang khu vườn nhà chúng tôi.', '{"wordId":"encroach","ukIpa":"/ɪnˈkrəʊtʃ/","usIpa":"/ɪnˈkroʊtʃ/","cefr":"C1","topic":"environment","senses":[{"pos":"v.","en":"To gradually take over another''s space, time, or rights.","vi":"xâm lấn dần; xâm phạm"}],"examples":[{"en":"The neighbour''s bushes are beginning to encroach on our garden.","vi":"Mấy bụi cây của nhà hàng xóm đang bắt đầu lấn sang khu vườn nhà chúng tôi.","audioKind":"ex"},{"en":"As new housing developments encroach on wetlands, local wildlife loses essential breeding grounds and sources of food.","vi":"Khi các dự án phát triển nhà ở mới dần xâm lấn vào các vùng đất ngập nước, động vật hoang dã địa phương sẽ mất đi các bãi sinh sản và nguồn thức ăn thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"encroach on land","vi":"xâm chiếm đất đai"},{"en":"encroach on privacy","vi":"xâm phạm quyền riêng tư"},{"en":"encroach on leisure time","vi":"lấn chiếm thời gian giải trí"}],"wordFamily":["encroachment (n)"],"synonyms":["intrude"],"antonyms":[],"tipVi":"Là nội động từ, thường đi với giới từ on/upon, nhấn mạnh tính chất xâm lấn từ từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_temperate', 'en-c1-20', 'temperate', '/ˈtempərət/', 'C1', 'ôn hòa (khí hậu); điềm đạm; chừng mực; ôn hòa', 'adj.', 'temperately (adv.), temperance (n.)', 'Đồng nghĩa: mild, moderate · Trái nghĩa: extreme', 'nghĩa về khí hậu chỉ thời tiết không quá lạnh cũng không quá nóng; không đồng nghĩa với nhiệt đới.', 'We enjoy walking outdoors in this temperate climate.', NULL, 'Chúng tôi rất thích đi dạo ngoài trời trong khí hậu ôn hòa này.', '{"wordId":"temperate","ukIpa":"/ˈtempərət/","usIpa":"/ˈtempərət/","cefr":"C1","topic":"environment","senses":[{"pos":"adj.","en":"Having weather that is neither very hot nor very cold","vi":"ôn hòa (khí hậu)"},{"pos":"adj.","en":"Showing restraint rather than extreme behaviour or feelings","vi":"điềm đạm; chừng mực; ôn hòa"}],"examples":[{"en":"We enjoy walking outdoors in this temperate climate.","vi":"Chúng tôi rất thích đi dạo ngoài trời trong khí hậu ôn hòa này.","audioKind":"ex"},{"en":"Temperate regions may experience significant changes in rainfall patterns as global temperatures continue to rise.","vi":"Các vùng ôn hòa có thể trải qua những thay đổi đáng kể về mô hình lượng mưa khi nhiệt độ toàn cầu tiếp tục tăng.","audioKind":"ex2"}],"collocations":[{"en":"temperate climate","vi":"khí hậu ôn hòa"},{"en":"temperate zone","vi":"vùng ôn hòa"},{"en":"temperate language","vi":"ngôn từ chừng mực"}],"wordFamily":["temperately (adv.)","temperance (n.)"],"synonyms":["mild","moderate"],"antonyms":["extreme"],"tipVi":"nghĩa về khí hậu chỉ thời tiết không quá lạnh cũng không quá nóng; không đồng nghĩa với nhiệt đới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elimination', 'en-c1-20', 'elimination', '/ɪˌlɪməˈneɪʃən/', 'C1', 'sự loại bỏ; sự tiêu diệt; sự loại trực tiếp; việc loại một đối thủ khỏi cuộc thi', 'n.', 'eliminate (v.)', 'Đồng nghĩa: removal', 'Động từ tương ứng là eliminate; cụm từ by elimination có nghĩa là "bằng phương pháp loại trừ".', 'Regular cleaning helps with the elimination of unpleasant kitchen smells.', NULL, 'Việc vệ sinh thường xuyên giúp loại bỏ mùi khó chịu trong nhà bếp.', '{"wordId":"elimination","ukIpa":"/ɪˌlɪmɪˈneɪʃən/","usIpa":"/ɪˌlɪməˈneɪʃən/","cefr":"C1","topic":"environment","senses":[{"pos":"n.","en":"the complete removal of something unwanted or unnecessary","vi":"sự loại bỏ; sự tiêu diệt"},{"pos":"n.","en":"the removal of a competitor from a competition","vi":"sự loại trực tiếp; việc loại một đối thủ khỏi cuộc thi"}],"examples":[{"en":"Regular cleaning helps with the elimination of unpleasant kitchen smells.","vi":"Việc vệ sinh thường xuyên giúp loại bỏ mùi khó chịu trong nhà bếp.","audioKind":"ex"},{"en":"The elimination of unnecessary packaging could significantly reduce household waste and lower the environmental impact of shopping.","vi":"Việc loại bỏ các bao bì không cần thiết có thể làm giảm đáng kể rác thải sinh hoạt và hạn chế tác động tiêu cực của việc mua sắm lên môi trường.","audioKind":"ex2"}],"collocations":[{"en":"elimination of waste","vi":"việc loại bỏ rác thải"},{"en":"process of elimination","vi":"phương pháp loại trừ"},{"en":"face elimination","vi":"đối mặt với việc bị loại"},{"en":"complete elimination","vi":"sự loại bỏ hoàn toàn"}],"wordFamily":["eliminate (v.)"],"synonyms":["removal"],"antonyms":[],"tipVi":"Động từ tương ứng là eliminate; cụm từ by elimination có nghĩa là \"bằng phương pháp loại trừ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_20_1', 'en-c1-20', 'Cách dùng “degradation” (n.) — sự suy thoái; sự xuống cấp; sự hư hại về chất lượng', 'environmental degradation  ·  soil degradation  ·  microbial degradation', 'Trong chủ đề môi trường, từ này thường chỉ sự suy thoái, còn trong ngữ cảnh hóa học hoặc sinh học có thể dịch là sự phân hủy/giáng hóa.', 'Họ từ (Word Family): degrade (v.), degradable (adj.), degrading (adj.) | Đồng nghĩa: deterioration · Trái nghĩa: improvement', '[{"hanzi":"The farmer noticed soil degradation across his dry fields.","pinyin":"","meaning":"Người nông dân nhận thấy tình trạng suy thoái đất trên khắp những cánh đồng khô cằn của ông ấy."},{"hanzi":"Environmental degradation often affects poorer communities most severely because they depend directly on local natural resources.","pinyin":"","meaning":"Sự suy thoái môi trường thường tác động nặng nề nhất đến các cộng đồng nghèo hơn vì họ phụ thuộc trực tiếp vào tài nguyên thiên nhiên địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_20_2', 'en-c1-20', 'Cách dùng “mitigate” (v.) — làm dịu bớt; giảm nhẹ; làm giảm thiểu', 'mitigate the effects of  ·  mitigate risks  ·  mitigate climate change', 'Đây là từ mang tính trang trọng, thường kết hợp trực tiếp với rủi ro, tổn thất hoặc ảnh hưởng chứ không mang nghĩa xóa bỏ hoàn toàn.', 'Họ từ (Word Family): mitigation (n.), mitigating (adj.) | Đồng nghĩa: alleviate, lessen, ease · Trái nghĩa: aggravate, exacerbate', '[{"hanzi":"Thick curtains helped mitigate the noise from the street.","pinyin":"","meaning":"Bộ rèm cửa dày giúp làm giảm tiếng ồn từ ngoài đường."},{"hanzi":"Planting trees in urban areas can mitigate the effects of extreme heat and improve residents'' quality of life.","pinyin":"","meaning":"Việc trồng cây ở khu vực đô thị có thể làm giảm tác động của nắng nóng cực đoan và cải thiện chất lượng cuộc sống của cư dân."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_20_3', 'en-c1-20', 'Cách dùng “barren” (adj.) — cằn cỗi; không màu mỡ', 'barren land  ·  barren landscape  ·  barren of', 'barren nhấn mạnh việc không thể sinh trưởng hoặc không có sản lượng; bare nhấn mạnh sự trơ trọi, không che chắn.', 'Họ từ (Word Family): barrenness (n.) | Đồng nghĩa: unproductive, infertile · Trái nghĩa: fertile, productive', '[{"hanzi":"Only a few bushes grew on the barren hillside.","pinyin":"","meaning":"Chỉ có vài bụi cây mọc trên sườn đồi cằn cỗi."},{"hanzi":"Unsustainable farming can turn productive fields into barren land, threatening food security and forcing rural communities to relocate.","pinyin":"","meaning":"Canh tác không bền vững có thể biến những cánh đồng màu mỡ thành đất hoang, đe dọa an ninh lương thực và buộc các cộng đồng nông thôn phải di dời."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_20_4', 'en-c1-20', 'Cách dùng “submerge” (v.) — nhấn chìm; dìm xuống nước; ngập hẳn', 'fully submerge  ·  submerge in water  ·  partially submerged', 'Có thể dùng như ngoại động từ hoặc nội động từ; nhấn mạnh hành động đi xuống dưới bề mặt nước hoặc chất lỏng.', 'Họ từ (Word Family): submersion (n.), submerged (adj.), submersible (adj.) | Đồng nghĩa: immerse', '[{"hanzi":"Submerge the dirty jar in warm water before washing it.","pinyin":"","meaning":"Nhấn chìm cái lọ bẩn vào nước ấm trước khi cọ rửa nó."},{"hanzi":"Rising sea levels could submerge low-lying coastal settlements, forcing residents to relocate and placing pressure on nearby cities.","pinyin":"","meaning":"Mực nước biển dâng cao có thể làm ngập các khu dân cư ven biển thấp trũng, buộc người dân phải di dời và gây áp lực cho các thành phố lân cận."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_20_1', 'en-c1-20', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
