INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_1_3', 'ten_c1_20_1', 'finite', 'Our holiday budget is finite, so choose carefully.', 'Our holiday budget is finite, so choose carefully.', '/ˈfaɪnaɪt/', 'Ngân sách du lịch của chúng ta có hạn, nên hãy lựa chọn thật kỹ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_1_4', 'ten_c1_20_1', 'cultivate', 'My grandparents cultivate vegetables in a small garden behind their house.', 'My grandparents cultivate vegetables in a small garden behind their house.', '/ˈkʌltɪveɪt/', 'Ông bà tôi trồng rau trong một mảnh vườn nhỏ phía sau nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_1_5', 'ten_c1_20_1', 'barren', 'Only a few bushes grew on the barren hillside.', 'Only a few bushes grew on the barren hillside.', '/ˈbærən/', 'Chỉ có vài bụi cây mọc trên sườn đồi cằn cỗi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_1_6', 'ten_c1_20_1', 'desertification', 'Desertification has left the fields around our village bare.', 'Desertification has left the fields around our village bare.', '/dɪˌzɝːtɪfɪˈkeɪʃən/', 'Quá trình sa mạc hóa đã khiến các cánh đồng xung quanh làng chúng tôi trở nên trơ trọi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_1_7', 'ten_c1_20_1', 'salvage', 'We managed to salvage some books after the flood.', 'We managed to salvage some books after the flood.', '/ˈsælvɪdʒ/', 'Chúng tôi đã cố gắng cứu vãn một số cuốn sách sau trận lụt.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_1_8', 'ten_c1_20_1', 'intensify', 'The rain intensified as we hurried towards the station.', 'The rain intensified as we hurried towards the station.', '/ɪnˈtensɪfaɪ/', 'Cơn mưa càng lúc càng nặng hạt khi chúng tôi vội vã chạy về phía nhà ga.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_20_1_1', 'en-c1-20', 'ten_c1_20_1', 'listening', 'listening', 'Strong sunlight can degrade the fabric of outdoor chairs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mấy bụi cây của nhà hàng xóm đang bắt đầu lấn sang khu vườn nhà chúng tôi.","Ánh nắng mạnh có thể làm hỏng chất liệu vải của ghế ngoài trời.","Quá trình sa mạc hóa đã khiến các cánh đồng xung quanh làng chúng tôi trở nên trơ trọi.","Một con sóng bất ngờ đã nuốt chửng lâu đài cát của chúng tôi trên bãi biển."]'::jsonb, 1, 'Strong sunlight can degrade the fabric of outdoor chairs. → Ánh nắng mạnh có thể làm hỏng chất liệu vải của ghế ngoài trời.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_20_1_2', 'en-c1-20', 'ten_c1_20_1', 'listening', 'listening', 'Submerge the dirty jar in warm water before washing it.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhấn chìm cái lọ bẩn vào nước ấm trước khi cọ rửa nó.","Lực lượng cứu họa đã giải cứu gia đình khỏi vụ hỏa hoạn lớn vào tối qua.","Ngân sách du lịch của chúng ta có hạn, nên hãy lựa chọn thật kỹ.","Cơn mưa càng lúc càng nặng hạt khi chúng tôi vội vã chạy về phía nhà ga."]'::jsonb, 0, 'Submerge the dirty jar in warm water before washing it. → Nhấn chìm cái lọ bẩn vào nước ấm trước khi cọ rửa nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_20_1_3', 'en-c1-20', 'ten_c1_20_1', 'listening', 'listening', 'Our holiday budget is finite, so choose carefully.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mấy bụi cây của nhà hàng xóm đang bắt đầu lấn sang khu vườn nhà chúng tôi.","Quá trình sa mạc hóa đã khiến các cánh đồng xung quanh làng chúng tôi trở nên trơ trọi.","Ánh nắng mạnh có thể làm hỏng chất liệu vải của ghế ngoài trời.","Ngân sách du lịch của chúng ta có hạn, nên hãy lựa chọn thật kỹ."]'::jsonb, 3, 'Our holiday budget is finite, so choose carefully. → Ngân sách du lịch của chúng ta có hạn, nên hãy lựa chọn thật kỹ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_20_2', 'en-c1-20', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_2_1', 'ten_c1_20_2', 'degrade', 'Intensive farming can degrade soil quality, making it harder to grow healthy crops in the future.', 'Intensive farming can degrade soil quality, making it harder to grow healthy crops in the future.', '/dɪˈɡreɪd/', 'Nông nghiệp thâm canh có thể làm giảm chất lượng đất, khiến cho việc trồng trọt các loại cây khỏe mạnh trong tương lai trở nên khó khăn hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_2_2', 'ten_c1_20_2', 'submerge', 'Rising sea levels could submerge low-lying coastal settlements, forcing residents to relocate and placing pressure on nearby cities.', 'Rising sea levels could submerge low-lying coastal settlements, forcing residents to relocate and placing pressure on nearby cities.', '/səbˈmɜːrdʒ/', 'Mực nước biển dâng cao có thể làm ngập các khu dân cư ven biển thấp trũng, buộc người dân phải di dời và gây áp lực cho các thành phố lân cận.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_2_3', 'ten_c1_20_2', 'finite', 'Governments must recognise that natural resources are finite and encourage industries to reduce unnecessary consumption.', 'Governments must recognise that natural resources are finite and encourage industries to reduce unnecessary consumption.', '/ˈfaɪnaɪt/', 'Chính phủ phải nhận thức rõ rằng tài nguyên thiên nhiên là có hạn và khuyến khích các ngành công nghiệp giảm thiểu mức tiêu thụ lãng phí.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_2_4', 'ten_c1_20_2', 'cultivate', 'Schools should cultivate curiosity by encouraging students to ask questions and explore different solutions to practical problems.', 'Schools should cultivate curiosity by encouraging students to ask questions and explore different solutions to practical problems.', '/ˈkʌltɪveɪt/', 'Nhà trường nên khuyến khích học sinh đặt câu hỏi và khám phá các giải pháp khác nhau cho những vấn đề thực tế nhằm nuôi dưỡng trí tò mò.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_2_5', 'ten_c1_20_2', 'barren', 'Unsustainable farming can turn productive fields into barren land, threatening food security and forcing rural communities to relocate.', 'Unsustainable farming can turn productive fields into barren land, threatening food security and forcing rural communities to relocate.', '/ˈbærən/', 'Canh tác không bền vững có thể biến những cánh đồng màu mỡ thành đất hoang, đe dọa an ninh lương thực và buộc các cộng đồng nông thôn phải di dời.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_20_2_6', 'ten_c1_20_2', 'desertification', 'Sustainable farming practices can slow desertification by protecting soil and preserving vegetation in dry regions.', 'Sustainable farming practices can slow desertification by protecting soil and preserving vegetation in dry regions.', '/dɪˌzɝːtɪfɪˈkeɪʃən/', 'Các phương pháp canh tác bền vững có thể làm chậm quá trình sa mạc hóa bằng cách bảo vệ đất và duy trì thảm thực vật ở các vùng khô hạn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_20_2_1', 'en-c1-20', 'ten_c1_20_2', 'listening', 'listening', 'Intensive farming can degrade soil quality, making it harder to grow healthy crops in the future.', NULL, 'Trong câu vừa nghe, từ “degrade” mang nghĩa nào sau đây?', '["làm suy giảm; làm hư hỏng chất lượng","vuông góc; tạo với một đường thẳng hoặc bề mặt khác một góc vuông","tiêu chí; chuẩn mực","liên tiếp; nối tiếp nhau không ngừng"]'::jsonb, 0, '“degrade” (/dɪˈɡreɪd/): làm suy giảm; làm hư hỏng chất lượng. Câu đầy đủ: Intensive farming can degrade soil quality, making it harder to grow healthy crops in the future.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_20_2_2', 'en-c1-20', 'ten_c1_20_2', 'listening', 'listening', 'Rising sea levels could submerge low-lying coastal settlements, forcing residents to relocate and placing pressure on nearby cities.', NULL, 'Trong câu vừa nghe, từ “submerge” mang nghĩa nào sau đây?', '["thi hành; thực thi; bắt tuân theo","nhấn chìm; dìm xuống nước; ngập hẳn","chạy tuyến cố định; đi lại đều đặn","vồ lấy; chồm tới"]'::jsonb, 1, '“submerge” (/səbˈmɜːrdʒ/): nhấn chìm; dìm xuống nước; ngập hẳn. Câu đầy đủ: Rising sea levels could submerge low-lying coastal settlements, forcing residents to relocate and placing pressure on nearby cities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
