INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_1', 'en-c1-20', NULL, 'comprehensive_test', 'listening', 'degrade', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khe hở; đường rạch hẹp","xử lý kém; giải quyết tồi","khám nghiệm tử thi; pháp y","làm suy giảm; làm hư hỏng chất lượng"]'::jsonb, 3, 'degrade (/dɪˈɡreɪd/) → làm suy giảm; làm hư hỏng chất lượng; phân hủy; giảm phân; làm mất nhân phẩm; hạ nhục', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_2', 'en-c1-20', NULL, 'comprehensive_test', 'listening', 'Submerge the dirty jar in warm water before washing it.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhấn chìm cái lọ bẩn vào nước ấm trước khi cọ rửa nó.","Quá trình sa mạc hóa đã khiến các cánh đồng xung quanh làng chúng tôi trở nên trơ trọi.","Cơn bão bất ngờ đẩy chiếc thuyền nhỏ vào tình thế hiểm nghèo.","Bộ rèm cửa dày giúp làm giảm tiếng ồn từ ngoài đường."]'::jsonb, 0, 'Submerge the dirty jar in warm water before washing it. → Nhấn chìm cái lọ bẩn vào nước ấm trước khi cọ rửa nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_3', 'en-c1-20', NULL, 'comprehensive_test', 'listening', 'finite', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["điều kiện bất lợi; trở ngại","mang tính nhân đạo","có hạn; có giới hạn","tình đoàn kết; sự gắn kết; sự ủng hộ lẫn nhau"]'::jsonb, 2, 'finite (/ˈfaɪnaɪt/) → có hạn; có giới hạn; hữu hạn (chỉ dạng động từ bị giới hạn bởi ngôi và số)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_4', 'en-c1-20', NULL, 'comprehensive_test', 'listening', 'My grandparents cultivate vegetables in a small garden behind their house.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ánh nắng mạnh có thể làm hỏng chất liệu vải của ghế ngoài trời.","Ông bà tôi trồng rau trong một mảnh vườn nhỏ phía sau nhà.","Bệnh viện gửi một số loại rác thải đi để xử lý thiêu hủy.","Bộ rèm cửa dày giúp làm giảm tiếng ồn từ ngoài đường."]'::jsonb, 1, 'My grandparents cultivate vegetables in a small garden behind their house. → Ông bà tôi trồng rau trong một mảnh vườn nhỏ phía sau nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_5', 'en-c1-20', NULL, 'comprehensive_test', 'listening', 'barren', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["búng; gạt nhanh; phủi nhanh","cằn cỗi; không màu mỡ","khuếch tán; lan tỏa; làm tán xạ","tuyết lở"]'::jsonb, 1, 'barren (/ˈbærən/) → cằn cỗi; không màu mỡ; vô ích; không mang lại kết quả; thiếu thốn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_6', 'en-c1-20', NULL, 'comprehensive_test', 'listening', 'Desertification has left the fields around our village bare.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Viện bảo tàng bên cảng có một cuộc triển lãm về hoạt động săn bắt cá voi.","Nhấn chìm cái lọ bẩn vào nước ấm trước khi cọ rửa nó.","Người nông dân nhận thấy tình trạng suy thoái đất trên khắp những cánh đồng khô cằn của ông ấy.","Quá trình sa mạc hóa đã khiến các cánh đồng xung quanh làng chúng tôi trở nên trơ trọi."]'::jsonb, 3, 'Desertification has left the fields around our village bare. → Quá trình sa mạc hóa đã khiến các cánh đồng xung quanh làng chúng tôi trở nên trơ trọi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_7', 'en-c1-20', NULL, 'comprehensive_test', 'listening', 'salvage', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phụ; dự phòng; bổ trợ","vĩnh viễn; liên tục","cứu hộ; trục vớt; thu hồi","vô lý; không cần thiết; bất lịch sự"]'::jsonb, 2, 'salvage (/ˈsælvɪdʒ/) → cứu hộ; trục vớt; thu hồi; cứu vãn; vớt vát; tài sản cứu được; vật liệu trục vớt', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_8', 'en-c1-20', NULL, 'comprehensive_test', 'listening', 'The rain intensified as we hurried towards the station.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bệnh viện gửi một số loại rác thải đi để xử lý thiêu hủy.","Ngân sách du lịch của chúng ta có hạn, nên hãy lựa chọn thật kỹ.","Bộ rèm cửa dày giúp làm giảm tiếng ồn từ ngoài đường.","Cơn mưa càng lúc càng nặng hạt khi chúng tôi vội vã chạy về phía nhà ga."]'::jsonb, 3, 'The rain intensified as we hurried towards the station. → Cơn mưa càng lúc càng nặng hạt khi chúng tôi vội vã chạy về phía nhà ga.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_9', 'en-c1-20', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Unable to support much plant growth.”?', '["elimination","degradation","barren","submerge"]'::jsonb, 2, 'barren (/ˈbærən/) → cằn cỗi; không màu mỡ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_10', 'en-c1-20', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the process by which productive land becomes desert”?', '["depletion","lumber","quarry","desertification"]'::jsonb, 3, 'desertification (/dɪˌzɝːtɪfɪˈkeɪʃən/) → sa mạc hóa; hoang mạc hóa', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_11', 'en-c1-20', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To save useful things from damage, loss, or destruction.”?', '["desertification","degradation","peril","salvage"]'::jsonb, 3, 'salvage (/ˈsælvɪdʒ/) → cứu hộ; trục vớt; thu hồi', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_12', 'en-c1-20', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “become stronger or more extreme, or make something so”?', '["temperate","whaling","lumber","intensify"]'::jsonb, 3, 'intensify (/ɪnˈtensɪfaɪ/) → trở nên mạnh hơn; gia tăng; làm cho gay gắt hơn', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_13', 'en-c1-20', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a large, strong fire”?', '["mangrove","salvage","barren","blaze"]'::jsonb, 3, 'blaze (/bleɪz/) → đám cháy lớn; ngọn lửa lớn', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
