INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_18', 'en-c1-20', NULL, 'comprehensive_test', 'reading', NULL, 'Intensive farming can degrade soil quality, making it harder to grow healthy crops in the future.', 'Dựa vào câu trên, từ “degrade” có nghĩa phù hợp nhất là gì?', '["phòng y tế hoặc bệnh xá cung cấp dịch vụ chăm sóc y tế trong một cơ quan, trường học","thuộc về hàng hải; thuộc về tàu thuyền","làm suy giảm; làm hư hỏng chất lượng","toàn bộ; tính toàn vẹn"]'::jsonb, 2, 'degrade: làm suy giảm; làm hư hỏng chất lượng; phân hủy; giảm phân; làm mất nhân phẩm; hạ nhục. Dịch cả câu: Nông nghiệp thâm canh có thể làm giảm chất lượng đất, khiến cho việc trồng trọt các loại cây khỏe mạnh trong tương lai trở nên khó khăn hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_19', 'en-c1-20', NULL, 'comprehensive_test', 'reading', NULL, 'Rising sea levels could submerge low-lying coastal settlements, forcing residents to relocate and placing pressure on nearby cities.', 'Dựa vào câu trên, từ “submerge” có nghĩa phù hợp nhất là gì?', '["nhấn chìm; dìm xuống nước; ngập hẳn","hầm ngục; nhà giam dưới lòng đất","làm ô nhiễm; làm bẩn","thuộc về thần thánh; thiêng liêng"]'::jsonb, 0, 'submerge: nhấn chìm; dìm xuống nước; ngập hẳn. Dịch cả câu: Mực nước biển dâng cao có thể làm ngập các khu dân cư ven biển thấp trũng, buộc người dân phải di dời và gây áp lực cho các thành phố lân cận.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_20', 'en-c1-20', NULL, 'comprehensive_test', 'reading', NULL, 'Governments must recognise that natural resources are finite and encourage industries to reduce unnecessary consumption.', 'Dựa vào câu trên, từ “finite” có nghĩa phù hợp nhất là gì?', '["có hạn; có giới hạn","sự cạn kiệt; sự suy giảm","lật đổ; đánh đổ","hải dương học"]'::jsonb, 0, 'finite: có hạn; có giới hạn; hữu hạn (chỉ dạng động từ bị giới hạn bởi ngôi và số). Dịch cả câu: Chính phủ phải nhận thức rõ rằng tài nguyên thiên nhiên là có hạn và khuyến khích các ngành công nghiệp giảm thiểu mức tiêu thụ lãng phí.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_21', 'en-c1-20', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should cultivate curiosity by encouraging students to ask questions and explore different solutions to practical problems.', 'Dựa vào câu trên, từ “cultivate” có nghĩa phù hợp nhất là gì?', '["cất giữ an toàn; thu dọn gọn gàng","rác rưởi; chất dơ bẩn; vết nhơ","cày cấy, trồng trọt","cột buồm"]'::jsonb, 2, 'cultivate: cày cấy, trồng trọt; bồi dưỡng, phát triển (kỹ năng, phẩm chất, sở thích hoặc mối quan hệ). Dịch cả câu: Nhà trường nên khuyến khích học sinh đặt câu hỏi và khám phá các giải pháp khác nhau cho những vấn đề thực tế nhằm nuôi dưỡng trí tò mò.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_22', 'en-c1-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “xâm lấn dần; xâm phạm”', '["preset","renaissance","encroach","prone"]'::jsonb, 2, 'xâm lấn dần; xâm phạm → encroach (/ɪnˈkroʊtʃ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_23', 'en-c1-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ôn hòa (khí hậu)”', '["cohesion","cram","commissioner","temperate"]'::jsonb, 3, 'ôn hòa (khí hậu) → temperate (/ˈtempərət/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_20_24', 'en-c1-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự loại bỏ; sự tiêu diệt”', '["hiss","elimination","oceanography","literate"]'::jsonb, 1, 'sự loại bỏ; sự tiêu diệt → elimination (/ɪˌlɪməˈneɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-21', 'en', 'Bài 21: Sức khỏe & Cơ thể (1) - CEFR C1', 'CEFR C1', 'C1 · Sức khỏe', '25 từ vựng Tiếng Anh CEFR C1 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5021, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preoperative', 'en-c1-21', 'preoperative', '/ˌpriːˈɑːpərətɪv/', 'C1', 'trước phẫu thuật; thuộc giai đoạn tiền phẫu', 'adj.', 'operative (adj.), postoperative (adj.), operation (n.)', 'Đồng nghĩa: presurgical · Trái nghĩa: postoperative', 'Tiền tố pre- có nghĩa là trước; trong khi postoperative dùng để chỉ giai đoạn sau phẫu thuật.', 'The nurse explained my preoperative checks before tomorrow''s surgery.', NULL, 'Y tá đã giải thích cho tôi về các xét nghiệm trước ca phẫu thuật vào ngày mai.', '{"wordId":"preoperative","ukIpa":"/ˌpriːˈɒpərətɪv/","usIpa":"/ˌpriːˈɑːpərətɪv/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"Happening or provided before a surgical operation.","vi":"trước phẫu thuật; thuộc giai đoạn tiền phẫu"}],"examples":[{"en":"The nurse explained my preoperative checks before tomorrow''s surgery.","vi":"Y tá đã giải thích cho tôi về các xét nghiệm trước ca phẫu thuật vào ngày mai.","audioKind":"ex"},{"en":"Thorough preoperative assessment helps medical teams identify potential risks and plan appropriate care for each patient.","vi":"Đánh giá tiền phẫu toàn diện giúp đội ngũ y tế xác định các rủi ro tiềm ẩn và lên kế hoạch chăm sóc phù hợp cho từng bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"preoperative assessment","vi":"đánh giá trước phẫu thuật"},{"en":"preoperative care","vi":"chăm sóc tiền phẫu"},{"en":"preoperative preparation","vi":"chuẩn bị trước phẫu thuật"}],"wordFamily":["operative (adj.)","postoperative (adj.)","operation (n.)"],"synonyms":["presurgical"],"antonyms":["postoperative"],"tipVi":"Tiền tố pre- có nghĩa là trước; trong khi postoperative dùng để chỉ giai đoạn sau phẫu thuật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acute', 'en-c1-21', 'acute', '/əˈkjuːt/', 'C1', 'trầm trọng; gay gắt; cấp tính; sắc bén; nhạy bén', 'adj.', 'acutely (adv.), acuteness (n.)', 'Đồng nghĩa: severe, intense, keen · Trái nghĩa: chronic', 'Trong y học, acute trái nghĩa với chronic (mãn tính).', 'The village faced an acute water shortage last summer.', NULL, 'Ngôi làng phải đối mặt với tình trạng thiếu nước trầm trọng vào mùa hè năm ngoái.', '{"wordId":"acute","ukIpa":"/əˈkjuːt/","usIpa":"/əˈkjuːt/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"Very serious or intense.","vi":"trầm trọng; gay gắt"},{"pos":"adj.","en":"Starting suddenly and lasting a short time, often severely.","vi":"cấp tính"},{"pos":"adj.","en":"Quick to notice or understand things.","vi":"sắc bén; nhạy bén"}],"examples":[{"en":"The village faced an acute water shortage last summer.","vi":"Ngôi làng phải đối mặt với tình trạng thiếu nước trầm trọng vào mùa hè năm ngoái.","audioKind":"ex"},{"en":"An acute shortage of affordable housing forces many young workers to live far from their workplaces.","vi":"Tình trạng thiếu hụt trầm trọng nhà ở giá rẻ buộc nhiều lao động trẻ phải sống xa nơi làm việc của họ.","audioKind":"ex2"}],"collocations":[{"en":"acute shortage","vi":"tình trạng thiếu hụt trầm trọng"},{"en":"acute pain","vi":"cơn đau dữ dội"},{"en":"acute illness","vi":"bệnh cấp tính"},{"en":"acute awareness","vi":"sự nhạy bén sâu sắc"}],"wordFamily":["acutely (adv.)","acuteness (n.)"],"synonyms":["severe","intense","keen"],"antonyms":["chronic"],"tipVi":"Trong y học, acute trái nghĩa với chronic (mãn tính).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ventilate', 'en-c1-21', 'ventilate', '/ˈventəleɪt/', 'C1', 'làm cho thông thoáng; thông gió; bộc lộ; bàn thảo công khai', 'v.', 'ventilation (n.), ventilator (n.), ventilated (adj.)', 'Đồng nghĩa: air', 'Nghĩa làm thông gió là nghĩa phổ biến; nghĩa thảo luận công khai mang sắc thái trang trọng hơn.', 'Open both windows to ventilate the kitchen after cooking.', NULL, 'Hãy mở cả hai cửa sổ để làm thoáng khí nhà bếp sau khi nấu ăn.', '{"wordId":"ventilate","ukIpa":"/ˈventɪleɪt/","usIpa":"/ˈventəleɪt/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"To allow fresh air to enter and circulate through somewhere.","vi":"làm cho thông thoáng; thông gió"},{"pos":"v.","en":"To express or discuss opinions and concerns openly.","vi":"bộc lộ; bàn thảo công khai"}],"examples":[{"en":"Open both windows to ventilate the kitchen after cooking.","vi":"Hãy mở cả hai cửa sổ để làm thoáng khí nhà bếp sau khi nấu ăn.","audioKind":"ex"},{"en":"Schools should ventilate classrooms regularly to improve indoor air quality and create healthier learning environments.","vi":"Các trường học nên thường xuyên thông gió cho phòng học nhằm cải thiện chất lượng không khí trong nhà và tạo môi trường học tập lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"ventilate a room","vi":"thông gió cho căn phòng"},{"en":"well-ventilated buildings","vi":"các tòa nhà được thông gió tốt"},{"en":"ventilate grievances","vi":"bày tỏ những bức xúc"}],"wordFamily":["ventilation (n.)","ventilator (n.)","ventilated (adj.)"],"synonyms":["air"],"antonyms":[],"tipVi":"Nghĩa làm thông gió là nghĩa phổ biến; nghĩa thảo luận công khai mang sắc thái trang trọng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recur', 'en-c1-21', 'recur', '/rɪˈkɝː/', 'C1', 'lại xảy ra; lặp lại; tái diễn', 'v.', 'recurrence (n.), recurrent (adj.), recurring (adj.)', 'Đồng nghĩa: repeat, reappear', 'Là nội động từ; dạng quá khứ là recurred, phân từ là recurring.', 'If these headaches recur, please speak to your doctor.', NULL, 'Nếu những cơn đau đầu này tái phát, xin vui lòng đến gặp bác sĩ để được tư vấn.', '{"wordId":"recur","ukIpa":"/rɪˈkɜː/","usIpa":"/rɪˈkɝː/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"to happen again, especially repeatedly or after an interval","vi":"lại xảy ra; lặp lại; tái diễn"}],"examples":[{"en":"If these headaches recur, please speak to your doctor.","vi":"Nếu những cơn đau đầu này tái phát, xin vui lòng đến gặp bác sĩ để được tư vấn.","audioKind":"ex"},{"en":"Traffic congestion will continue to recur unless cities address the underlying causes of excessive car use.","vi":"Tình trạng ùn tắc giao thông sẽ tiếp tục tái diễn trừ khi các thành phố giải quyết được nguyên nhân gốc rễ của việc lạm dụng xe hơi.","audioKind":"ex2"}],"collocations":[{"en":"a recurring problem","vi":"vấn đề lặp đi lặp lại"},{"en":"a recurring theme","vi":"chủ đề lặp lại xuyên suốt"},{"en":"symptoms recur","vi":"triệu chứng tái phát"}],"wordFamily":["recurrence (n.)","recurrent (adj.)","recurring (adj.)"],"synonyms":["repeat","reappear"],"antonyms":[],"tipVi":"Là nội động từ; dạng quá khứ là recurred, phân từ là recurring.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tranquilizer', 'en-c1-21', 'tranquilizer', '/ˈtræŋkwɪlaɪzər/', 'C1', 'thuốc an thần; thuốc trấn tĩnh', 'n.', 'tranquil (adj.), tranquilize (v.), tranquility (n.)', NULL, 'Tiếng Anh-Mỹ thường viết là tranquilizer, còn tiếng Anh-Anh thường viết là tranquilliser.', 'The vet gave the frightened horse a tranquilizer.', NULL, 'Bác sĩ thú y đã tiêm thuốc an thần cho con ngựa đang hoảng sợ.', '{"wordId":"tranquilizer","ukIpa":"/ˈtræŋkwɪlaɪzə/","usIpa":"/ˈtræŋkwɪlaɪzər/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A drug used to calm people or animals and reduce anxiety.","vi":"thuốc an thần; thuốc trấn tĩnh"}],"examples":[{"en":"The vet gave the frightened horse a tranquilizer.","vi":"Bác sĩ thú y đã tiêm thuốc an thần cho con ngựa đang hoảng sợ.","audioKind":"ex"},{"en":"Doctors should carefully assess the risks before prescribing a tranquilizer to a patient with persistent anxiety.","vi":"Các bác sĩ nên thận trọng đánh giá các rủi ro trước khi kê đơn thuốc an thần cho bệnh nhân mắc chứng lo âu kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"prescribe a tranquilizer","vi":"kê đơn thuốc an thần"},{"en":"take a tranquilizer","vi":"dùng thuốc an thần"},{"en":"tranquilizer dart","vi":"phi tiêu gây mê"}],"wordFamily":["tranquil (adj.)","tranquilize (v.)","tranquility (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Mỹ thường viết là tranquilizer, còn tiếng Anh-Anh thường viết là tranquilliser.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perspire', 'en-c1-21', 'perspire', '/pərˈspaɪr/', 'C1', 'đổ mồ hôi; ra mồ hôi', 'v.', 'perspiration (n.)', 'Đồng nghĩa: sweat', 'Mang tính trang trọng hơn sweat; thường đóng vai trò là nội động từ.', 'I began to perspire while carrying the heavy boxes.', NULL, 'Tôi bắt đầu đổ mồ hôi khi khiêng những chiếc thùng nặng.', '{"wordId":"perspire","ukIpa":"/pəˈspaɪə/","usIpa":"/pərˈspaɪr/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"to release sweat through your skin, especially when hot","vi":"đổ mồ hôi; ra mồ hôi"}],"examples":[{"en":"I began to perspire while carrying the heavy boxes.","vi":"Tôi bắt đầu đổ mồ hôi khi khiêng những chiếc thùng nặng.","audioKind":"ex"},{"en":"People perspire more during intense exercise because the body needs to release excess heat.","vi":"Con người đổ mồ hôi nhiều hơn khi tập luyện cường độ cao vì cơ thể cần giải phóng lượng nhiệt dư thừa.","audioKind":"ex2"}],"collocations":[{"en":"perspire heavily","vi":"đổ mồ hôi đầm đìa"},{"en":"perspire freely","vi":"vã mồ hôi hột"}],"wordFamily":["perspiration (n.)"],"synonyms":["sweat"],"antonyms":[],"tipVi":"Mang tính trang trọng hơn sweat; thường đóng vai trò là nội động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scalpel', 'en-c1-21', 'scalpel', '/ˈskælpəl/', 'C1', 'dao mổ; dao giải phẫu', 'n.', NULL, NULL, 'Danh từ đếm được, chỉ loại dao dùng để rạch chính xác trong phẫu thuật hoặc giải phẫu.', 'The surgeon placed the scalpel on a clean tray.', NULL, 'Bác sĩ phẫu thuật đặt con dao mổ lên một khay sạch.', '{"wordId":"scalpel","ukIpa":"/ˈskælpəl/","usIpa":"/ˈskælpəl/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A small, very sharp knife used in surgery or dissection.","vi":"dao mổ; dao giải phẫu"}],"examples":[{"en":"The surgeon placed the scalpel on a clean tray.","vi":"Bác sĩ phẫu thuật đặt con dao mổ lên một khay sạch.","audioKind":"ex"},{"en":"Medical students practise using a scalpel on artificial tissue before developing more advanced surgical skills.","vi":"Các sinh viên y khoa thực hành sử dụng dao mổ trên mô nhân tạo trước khi phát triển các kỹ năng phẫu thuật nâng cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"surgical scalpel","vi":"dao mổ ngoại khoa"},{"en":"scalpel blade","vi":"lưỡi dao mổ"},{"en":"disposable scalpel","vi":"dao mổ dùng một lần"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được, chỉ loại dao dùng để rạch chính xác trong phẫu thuật hoặc giải phẫu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deficiency', 'en-c1-21', 'deficiency', '/dɪˈfɪʃənsi/', 'C1', 'sự thiếu hụt; không đủ; sự thiếu sót; khiếm khuyết', 'n.', 'deficient (adj.)', 'Đồng nghĩa: shortage, lack, inadequacy · Trái nghĩa: sufficiency, excess', 'Thiếu cái gì dùng deficiency in; các khiếm khuyết cụ thể thường dùng ở dạng số nhiều.', 'A blood test revealed that I had an iron deficiency.', NULL, 'Kết quả xét nghiệm máu cho thấy tôi bị thiếu sắt.', '{"wordId":"deficiency","ukIpa":"/dɪˈfɪʃənsi/","usIpa":"/dɪˈfɪʃənsi/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A lack of enough of something necessary.","vi":"sự thiếu hụt; không đủ"},{"pos":"n.","en":"A weakness that prevents something from working well.","vi":"sự thiếu sót; khiếm khuyết"}],"examples":[{"en":"A blood test revealed that I had an iron deficiency.","vi":"Kết quả xét nghiệm máu cho thấy tôi bị thiếu sắt.","audioKind":"ex"},{"en":"Nutritional deficiency among children can affect physical growth and reduce their ability to concentrate at school.","vi":"Tình trạng thiếu hụt dinh dưỡng ở trẻ em có thể ảnh hưởng đến sự phát triển thể chất và làm giảm khả năng tập trung ở trường.","audioKind":"ex2"}],"collocations":[{"en":"iron deficiency","vi":"thiếu sắt"},{"en":"vitamin deficiency","vi":"thiếu vitamin"},{"en":"nutritional deficiency","vi":"thiếu hụt dinh dưỡng"},{"en":"remedy a deficiency","vi":"khắc phục sự thiếu sót"}],"wordFamily":["deficient (adj.)"],"synonyms":["shortage","lack","inadequacy"],"antonyms":["sufficiency","excess"],"tipVi":"Thiếu cái gì dùng deficiency in; các khiếm khuyết cụ thể thường dùng ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eradication', 'en-c1-21', 'eradication', '/ɪˌrædɪˈkeɪʃən/', 'C1', 'sự triệt phá; sự xóa sổ hoàn toàn', 'n.', 'eradicate (v.)', 'Đồng nghĩa: elimination', 'Nhấn mạnh việc loại bỏ hoàn toàn, thường đi với eradication of.', 'Complete eradication of these weeds will take patience.', NULL, 'Việc nhổ tận gốc đám cỏ dại này sẽ cần sự kiên nhẫn.', '{"wordId":"eradication","ukIpa":"/ɪˌrædɪˈkeɪʃən/","usIpa":"/ɪˌrædɪˈkeɪʃən/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"the complete removal or destruction of something harmful","vi":"sự triệt phá; sự xóa sổ hoàn toàn"}],"examples":[{"en":"Complete eradication of these weeds will take patience.","vi":"Việc nhổ tận gốc đám cỏ dại này sẽ cần sự kiên nhẫn.","audioKind":"ex"},{"en":"The eradication of infectious diseases requires sustained investment in vaccination programmes and public health infrastructure.","vi":"Việc xóa sổ các bệnh truyền nhiễm đòi hỏi nguồn đầu tư liên tục vào các chương trình tiêm chủng và cơ sở hạ tầng y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"disease eradication","vi":"tiêu diệt dịch bệnh"},{"en":"the eradication of poverty","vi":"xóa đói giảm nghèo"},{"en":"eradication programme","vi":"chương trình triệt phá"}],"wordFamily":["eradicate (v.)"],"synonyms":["elimination"],"antonyms":[],"tipVi":"Nhấn mạnh việc loại bỏ hoàn toàn, thường đi với eradication of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_syndrome', 'en-c1-21', 'syndrome', '/ˈsɪndroʊm/', 'C1', 'hội chứng', 'n.', NULL, NULL, 'Chỉ một tập hợp các triệu chứng xuất hiện cùng nhau, không đồng nghĩa với một triệu chứng đơn lẻ symptom.', 'The doctor explained how the syndrome affects sleep.', NULL, 'Bác sĩ giải thích hội chứng này ảnh hưởng đến giấc ngủ như thế nào.', '{"wordId":"syndrome","ukIpa":"/ˈsɪndrəʊm/","usIpa":"/ˈsɪndroʊm/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"a group of symptoms that occur together in a condition","vi":"hội chứng"}],"examples":[{"en":"The doctor explained how the syndrome affects sleep.","vi":"Bác sĩ giải thích hội chứng này ảnh hưởng đến giấc ngủ như thế nào.","audioKind":"ex"},{"en":"Early recognition of a syndrome can help healthcare professionals provide appropriate support and manage symptoms more effectively.","vi":"Việc nhận biết sớm một hội chứng có thể giúp các chuyên gia y tế cung cấp sự hỗ trợ phù hợp và kiểm soát các triệu chứng hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"chronic fatigue syndrome","vi":"hội chứng mệt mỏi mãn tính"},{"en":"irritable bowel syndrome","vi":"hội chứng ruột kích thích"},{"en":"metabolic syndrome","vi":"hội chứng chuyển hóa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ một tập hợp các triệu chứng xuất hiện cùng nhau, không đồng nghĩa với một triệu chứng đơn lẻ symptom.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alleviate', 'en-c1-21', 'alleviate', '/əˈliːvieɪt/', 'C1', 'làm giảm; xoa dịu; làm nhẹ bớt', 'v.', 'alleviation (n.)', 'Đồng nghĩa: ease, relieve · Trái nghĩa: aggravate, worsen', 'Trực tiếp đi với nỗi đau hoặc vấn đề; thể hiện việc làm giảm bớt chứ không nhất thiết là giải quyết triệt để.', 'A warm bath helped alleviate the ache in my shoulders.', NULL, 'Tắm nước ấm giúp làm dịu cơn đau mỏi ở vai của tôi.', '{"wordId":"alleviate","ukIpa":"/əˈliːvieɪt/","usIpa":"/əˈliːvieɪt/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"to make pain, suffering, or a problem less severe","vi":"làm giảm; xoa dịu; làm nhẹ bớt"}],"examples":[{"en":"A warm bath helped alleviate the ache in my shoulders.","vi":"Tắm nước ấm giúp làm dịu cơn đau mỏi ở vai của tôi.","audioKind":"ex"},{"en":"Expanding affordable housing could alleviate pressure on low-income families and reduce the risk of homelessness.","vi":"Việc mở rộng nhà ở giá rẻ có thể làm giảm áp lực cho các gia đình thu nhập thấp và giảm nguy cơ vô gia cư.","audioKind":"ex2"}],"collocations":[{"en":"alleviate pain","vi":"giảm đau"},{"en":"alleviate poverty","vi":"xóa đói giảm nghèo"},{"en":"alleviate pressure","vi":"giảm bớt áp lực"},{"en":"alleviate symptoms","vi":"làm giảm triệu chứng"}],"wordFamily":["alleviation (n.)"],"synonyms":["ease","relieve"],"antonyms":["aggravate","worsen"],"tipVi":"Trực tiếp đi với nỗi đau hoặc vấn đề; thể hiện việc làm giảm bớt chứ không nhất thiết là giải quyết triệt để.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deficient', 'en-c1-21', 'deficient', '/dɪˈfɪʃənt/', 'C1', 'thiếu thốn; không đủ (những thứ cần thiết); kém chất lượng; có khuyết điểm; không hoàn thiện', 'adj.', 'deficiency (n.)', 'Đồng nghĩa: lacking, inadequate · Trái nghĩa: sufficient, adequate', 'Diễn tả việc thiếu hụt thứ gì đó bằng cấu trúc be deficient in, thường gặp trong các mô tả về dinh dưỡng và năng lực.', 'The doctor said my diet was deficient in iron.', NULL, 'Bác sĩ nói rằng chế độ ăn của tôi đang bị thiếu sắt.', '{"wordId":"deficient","ukIpa":"/dɪˈfɪʃənt/","usIpa":"/dɪˈfɪʃənt/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"not having enough of something necessary","vi":"thiếu thốn; không đủ (những thứ cần thiết)"},{"pos":"adj.","en":"not good enough in quality or performance","vi":"kém chất lượng; có khuyết điểm; không hoàn thiện"}],"examples":[{"en":"The doctor said my diet was deficient in iron.","vi":"Bác sĩ nói rằng chế độ ăn của tôi đang bị thiếu sắt.","audioKind":"ex"},{"en":"Communities with deficient healthcare services often face greater difficulties in preventing disease and supporting older residents.","vi":"Các cộng đồng có dịch vụ y tế kém phát triển thường phải đối mặt với nhiều khó khăn lớn hơn trong việc phòng ngừa dịch bệnh và hỗ trợ cư dân cao tuổi.","audioKind":"ex2"}],"collocations":[{"en":"deficient in iron","vi":"thiếu chất sắt"},{"en":"nutritionally deficient","vi":"thiếu hụt dinh dưỡng"},{"en":"deficient in essential nutrients","vi":"thiếu các dưỡng chất thiết yếu"}],"wordFamily":["deficiency (n.)"],"synonyms":["lacking","inadequate"],"antonyms":["sufficient","adequate"],"tipVi":"Diễn tả việc thiếu hụt thứ gì đó bằng cấu trúc be deficient in, thường gặp trong các mô tả về dinh dưỡng và năng lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chronic', 'en-c1-21', 'chronic', '/ˈkrɑːnɪk/', 'C1', 'mãn tính; kinh niên; kéo dài lâu ngày', 'adj.', 'chronically (adv.)', 'Đồng nghĩa: persistent, long-standing · Trái nghĩa: acute', 'Trong ngữ cảnh y tế, chronic chỉ bệnh mãn tính, còn acute chỉ bệnh cấp tính.', 'Gentle swimming helps her manage her chronic back pain.', NULL, 'Việc bơi lội nhẹ nhàng giúp cô ấy kiểm soát cơn đau lưng mãn tính của mình.', '{"wordId":"chronic","ukIpa":"/ˈkrɒnɪk/","usIpa":"/ˈkrɑːnɪk/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"Continuing for a long time, especially a medical condition","vi":"mãn tính"},{"pos":"adj.","en":"Persisting or recurring over a long period","vi":"kinh niên; kéo dài lâu ngày"}],"examples":[{"en":"Gentle swimming helps her manage her chronic back pain.","vi":"Việc bơi lội nhẹ nhàng giúp cô ấy kiểm soát cơn đau lưng mãn tính của mình.","audioKind":"ex"},{"en":"Chronic staff shortages can reduce the quality of healthcare and increase pressure on existing medical workers.","vi":"Tình trạng thiếu hụt nhân sự kinh niên có thể làm giảm chất lượng chăm sóc sức khỏe và gia tăng áp lực lên các nhân viên y tế hiện tại.","audioKind":"ex2"}],"collocations":[{"en":"chronic disease","vi":"bệnh mãn tính"},{"en":"chronic pain","vi":"đau mãn tính"},{"en":"chronic shortage","vi":"tình trạng thiếu hụt trầm trọng"}],"wordFamily":["chronically (adv.)"],"synonyms":["persistent","long-standing"],"antonyms":["acute"],"tipVi":"Trong ngữ cảnh y tế, chronic chỉ bệnh mãn tính, còn acute chỉ bệnh cấp tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_afflict', 'en-c1-21', 'afflict', '/əˈflɪkt/', 'C1', 'làm đau đớn; gây phiền muộn; hành hạ', 'v.', 'affliction (n.), afflicted (adj.)', 'Đồng nghĩa: trouble, plague', 'Thường dùng ở thể bị động be afflicted with, đi kèm với bệnh tật hoặc hoàn cảnh khó khăn.', 'Seasonal allergies afflict my brother whenever the flowers bloom.', NULL, 'Căn bệnh dị ứng theo mùa cứ hành hạ anh trai tôi mỗi khi hoa nở.', '{"wordId":"afflict","ukIpa":"/əˈflɪkt/","usIpa":"/əˈflɪkt/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"Cause someone or something serious suffering or difficulty","vi":"làm đau đớn; gây phiền muộn; hành hạ"}],"examples":[{"en":"Seasonal allergies afflict my brother whenever the flowers bloom.","vi":"Căn bệnh dị ứng theo mùa cứ hành hạ anh trai tôi mỗi khi hoa nở.","audioKind":"ex"},{"en":"Water shortages continue to afflict rural communities, limiting agricultural production and increasing the burden on local families.","vi":"Tình trạng thiếu nước tiếp tục làm khổ các cộng đồng nông thôn, hạn chế sản xuất nông nghiệp và làm gia tăng gánh nặng cho các gia đình địa phương.","audioKind":"ex2"}],"collocations":[{"en":"be afflicted with","vi":"bị hành hạ bởi"},{"en":"afflict communities","vi":"gây khốnốn cho các cộng đồng"},{"en":"severely afflicted","vi":"bị ảnh hưởng nghiêm trọng"}],"wordFamily":["affliction (n.)","afflicted (adj.)"],"synonyms":["trouble","plague"],"antonyms":[],"tipVi":"Thường dùng ở thể bị động be afflicted with, đi kèm với bệnh tật hoặc hoàn cảnh khó khăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_posture', 'en-c1-21', 'posture', '/ˈpɑːstʃər/', 'C1', 'tư thế; dáng đi đứng; lập trường; thái độ; ra vẻ; làm dáng', 'n.', 'postural (adj.), posturing (n.)', 'Đồng nghĩa: stance', 'Danh từ thường chỉ dáng vẻ cơ thể; động từ mang sắc thái châm biếm là "làm hàng" hoặc "ra vẻ".', 'Adjusting your chair can improve your posture while working.', NULL, 'Điều chỉnh ghế ngồi có thể giúp cải thiện tư thế của bạn khi làm việc.', '{"wordId":"posture","ukIpa":"/ˈpɒstʃə/","usIpa":"/ˈpɑːstʃər/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"the way you hold your body when sitting or standing","vi":"tư thế; dáng đi đứng"},{"pos":"n.","en":"an attitude or position towards a particular issue","vi":"lập trường; thái độ"},{"pos":"v.","en":"to behave artificially in order to impress others","vi":"ra vẻ; làm dáng"}],"examples":[{"en":"Adjusting your chair can improve your posture while working.","vi":"Điều chỉnh ghế ngồi có thể giúp cải thiện tư thế của bạn khi làm việc.","audioKind":"ex"},{"en":"Schools should teach children how good posture and regular movement can reduce discomfort during prolonged study.","vi":"Nhà trường nên dạy cho học sinh biết tư thế đúng và vận động thường xuyên có thể giúp giảm thiểu tình trạng mỏi mệt khi học tập kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"good posture","vi":"tư thế chuẩn"},{"en":"improve your posture","vi":"cải thiện tư thế"},{"en":"adopt a defensive posture","vi":"giữ thái độ phòng thủ"}],"wordFamily":["postural (adj.)","posturing (n.)"],"synonyms":["stance"],"antonyms":[],"tipVi":"Danh từ thường chỉ dáng vẻ cơ thể; động từ mang sắc thái châm biếm là \"làm hàng\" hoặc \"ra vẻ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feeble', 'en-c1-21', 'feeble', '/ˈfiːbəl/', 'C1', 'yếu ớt; ốm yếu; mệt mỏi; kém thuyết phục; yếu kém; không hiệu quả', 'adj.', 'feebly (adv.), feebleness (n.)', 'Đồng nghĩa: weak, frail · Trái nghĩa: strong, vigorous', 'Có thể dùng để chỉ thể chất, giọng nói, hoặc dùng để chê bai những cái cớ và nỗ lực kém cỏi.', 'After the illness, he felt too feeble to cook.', NULL, 'Sau trận ốm, anh ấy cảm thấy quá yếu để có thể nấu ăn.', '{"wordId":"feeble","ukIpa":"/ˈfiːbəl/","usIpa":"/ˈfiːbəl/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"Lacking physical strength, energy, or intensity.","vi":"yếu ớt; ốm yếu; mệt mỏi"},{"pos":"adj.","en":"Too weak to convince people or achieve a useful result.","vi":"kém thuyết phục; yếu kém; không hiệu quả"}],"examples":[{"en":"After the illness, he felt too feeble to cook.","vi":"Sau trận ốm, anh ấy cảm thấy quá yếu để có thể nấu ăn.","audioKind":"ex"},{"en":"Feeble enforcement of environmental regulations allows some factories to continue polluting rivers without facing meaningful consequences.","vi":"Việc thực thi lỏng lẻo các quy định bảo vệ môi trường khiến một số nhà máy tiếp tục xả thải ra sông mà không phải đối mặt với hậu quả đáng kể nào.","audioKind":"ex2"}],"collocations":[{"en":"a feeble voice","vi":"giọng nói yếu ớt"},{"en":"a feeble excuse","vi":"cái cớ ngụy biện yếu ớt"},{"en":"a feeble attempt","vi":"một nỗ lực yếu ớt"}],"wordFamily":["feebly (adv.)","feebleness (n.)"],"synonyms":["weak","frail"],"antonyms":["strong","vigorous"],"tipVi":"Có thể dùng để chỉ thể chất, giọng nói, hoặc dùng để chê bai những cái cớ và nỗ lực kém cỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drunkard', 'en-c1-21', 'drunkard', '/ˈdrʌŋkərd/', 'C1', 'bợm nhậu; kẻ nát rượu', 'n.', 'drunk (adj.), drunken (adj.), drunkenness (n.)', NULL, 'Mang hàm ý miệt thị; cách dùng trung lập hơn là dùng person with alcohol dependence.', 'The novel portrays the lonely innkeeper as a drunkard.', NULL, 'Cuốn tiểu thuyết miêu tả người chủ quán trọ cô độc như một kẻ nát rượu.', '{"wordId":"drunkard","ukIpa":"/ˈdrʌŋkəd/","usIpa":"/ˈdrʌŋkərd/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"An insulting term for someone who is frequently drunk.","vi":"bợm nhậu; kẻ nát rượu"}],"examples":[{"en":"The novel portrays the lonely innkeeper as a drunkard.","vi":"Cuốn tiểu thuyết miêu tả người chủ quán trọ cô độc như một kẻ nát rượu.","audioKind":"ex"},{"en":"Calling someone a drunkard can reinforce stigma and discourage them from seeking professional help for alcohol dependence.","vi":"Gọi ai đó là bợm nhậu có thể làm gia tăng sự kỳ thị và cản trở họ tìm kiếm sự trợ giúp chuyên nghiệp cho chứng nghiện rượu.","audioKind":"ex2"}],"collocations":[{"en":"a habitual drunkard","vi":"bợm nhậu quen thói"},{"en":"call someone a drunkard","vi":"gọi ai là kẻ nát rượu"}],"wordFamily":["drunk (adj.)","drunken (adj.)","drunkenness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Mang hàm ý miệt thị; cách dùng trung lập hơn là dùng person with alcohol dependence.","noteVi":"Từ miêu tả mang tính xúc phạm, có thể làm tổn thương những người đang đối mặt với chứng nghiện rượu.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_onset', 'en-c1-21', 'onset', '/ˈɑːnset/', 'C1', 'sự khởi đầu; sự bắt đầu (thường là điều không dễ chịu)', 'n.', NULL, 'Đồng nghĩa: beginning, start', 'Thường đi với cụm "the onset of", chủ yếu dùng để chỉ sự khởi đầu của bệnh tật hoặc các tình huống bất lợi.', 'The sudden onset of rain sent us running indoors.', NULL, 'Những cơn mưa bắt đầu đột ngột khiến chúng tôi phải chạy vội vào nhà.', '{"wordId":"onset","ukIpa":"/ˈɒnset/","usIpa":"/ˈɑːnset/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"The beginning of something, especially something unpleasant.","vi":"sự khởi đầu; sự bắt đầu (thường là điều không dễ chịu)"}],"examples":[{"en":"The sudden onset of rain sent us running indoors.","vi":"Những cơn mưa bắt đầu đột ngột khiến chúng tôi phải chạy vội vào nhà.","audioKind":"ex"},{"en":"Regular physical activity may delay the onset of certain chronic diseases and improve overall wellbeing.","vi":"Việc tập thể dục đều đặn có thể làm chậm sự khởi phát của một số bệnh mãn tính và cải thiện sức khỏe tổng thể.","audioKind":"ex2"}],"collocations":[{"en":"the onset of symptoms","vi":"sự khởi phát của các triệu chứng"},{"en":"the onset of winter","vi":"sự bắt đầu của mùa đông"},{"en":"sudden onset","vi":"bắt đầu đột ngột"},{"en":"delay the onset","vi":"làm chậm sự khởi phát"}],"wordFamily":[],"synonyms":["beginning","start"],"antonyms":[],"tipVi":"Thường đi với cụm \"the onset of\", chủ yếu dùng để chỉ sự khởi đầu của bệnh tật hoặc các tình huống bất lợi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lethal', 'en-c1-21', 'lethal', '/ˈliːθəl/', 'C1', 'gây chết người, chí mạng', 'adj.', 'lethality (n.), lethally (adv.)', 'Đồng nghĩa: deadly, fatal · Trái nghĩa: harmless', 'Thường đóng vai trò tính từ; lethal nhấn mạnh khả năng tước đoạt sự sống.', 'Some wild mushrooms contain toxins that can be lethal.', NULL, 'Một số loại nấm dại chứa độc tố có thể gây chết người.', '{"wordId":"lethal","ukIpa":"/ˈliːθəl/","usIpa":"/ˈliːθəl/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"able to cause death","vi":"gây chết người, chí mạng"}],"examples":[{"en":"Some wild mushrooms contain toxins that can be lethal.","vi":"Một số loại nấm dại chứa độc tố có thể gây chết người.","audioKind":"ex"},{"en":"Exposure to lethal concentrations of air pollutants highlights the importance of strict industrial safety regulations.","vi":"Việc tiếp xúc với nồng độ chất ô nhiễm không khí gây chết người nhấn mạnh tầm quan trọng của các quy định an toàn công nghiệp nghiêm ngặt.","audioKind":"ex2"}],"collocations":[{"en":"lethal dose","vi":"liều gây chết"},{"en":"lethal weapon","vi":"vũ khí giết người"},{"en":"potentially lethal","vi":"có tiềm năng gây chết người"},{"en":"lethal concentration","vi":"nồng độ gây tử vong"}],"wordFamily":["lethality (n.)","lethally (adv.)"],"synonyms":["deadly","fatal"],"antonyms":["harmless"],"tipVi":"Thường đóng vai trò tính từ; lethal nhấn mạnh khả năng tước đoạt sự sống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fortify', 'en-c1-21', 'fortify', '/ˈfɔːrtɪfaɪ/', 'C1', 'củng cố; gia cố; tăng cường sức mạnh (thể chất hoặc tinh thần); tăng cường hàm lượng dinh dưỡng', 'v.', 'fortification (n.), fortified (adj.)', 'Đồng nghĩa: strengthen, reinforce · Trái nghĩa: weaken', 'Cấu trúc fortify A with B: dùng B để tăng cường cho A.', 'We used sandbags to fortify the wall before the storm.', NULL, 'Chúng tôi đã dùng bao cát để gia cố bức tường trước cơn bão.', '{"wordId":"fortify","ukIpa":"/ˈfɔːtɪfaɪ/","usIpa":"/ˈfɔːrtɪfaɪ/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"to strengthen a place or structure against attack or damage","vi":"củng cố; gia cố"},{"pos":"v.","en":"to make someone physically or mentally stronger","vi":"tăng cường sức mạnh (thể chất hoặc tinh thần)"},{"pos":"v.","en":"to add nutrients to food to improve its nutritional value","vi":"tăng cường hàm lượng dinh dưỡng"}],"examples":[{"en":"We used sandbags to fortify the wall before the storm.","vi":"Chúng tôi đã dùng bao cát để gia cố bức tường trước cơn bão.","audioKind":"ex"},{"en":"Manufacturers can fortify staple foods with essential vitamins to help prevent nutritional deficiencies in vulnerable populations.","vi":"Các nhà sản xuất có thể bổ sung các loại vitamin thiết yếu vào thực phẩm cơ bản để giúp ngăn ngừa tình trạng thiếu hụt dinh dưỡng ở các nhóm dân cư dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"fortify coastal defences","vi":"tăng cường phòng thủ bờ biển"},{"en":"fortify food with vitamins","vi":"bổ sung vitamin vào thực phẩm"},{"en":"fortify yourself against","vi":"tự trang bị sức mạnh để chống lại"}],"wordFamily":["fortification (n.)","fortified (adj.)"],"synonyms":["strengthen","reinforce"],"antonyms":["weaken"],"tipVi":"Cấu trúc fortify A with B: dùng B để tăng cường cho A.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_postmortem', 'en-c1-21', 'postmortem', '/ˌpoʊstˈmɔːrtəm/', 'C1', 'khám nghiệm tử thi; pháp y; sự đánh giá lại sự việc đã qua; cuộc họp rút kinh nghiệm; sự tổng kết; sau khi chết; xảy ra sau khi qua đời', 'n.', NULL, NULL, 'Trong tiếng Anh Anh thường viết là post-mortem; từ này cũng có thể dùng theo nghĩa ẩn dụ cho việc tổng kết sau một sự kiện hoặc dự án.', 'Our team held a postmortem after the disappointing match.', NULL, 'Đội của chúng tôi đã tổ chức một buổi họp rút kinh nghiệm sau trận đấu gây thất vọng đó.', '{"wordId":"postmortem","ukIpa":"/ˌpəʊstˈmɔːtəm/","usIpa":"/ˌpoʊstˈmɔːrtəm/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"a medical examination of a body to determine death''s cause","vi":"khám nghiệm tử thi; pháp y"},{"pos":"n.","en":"an examination of a completed event, especially an unsuccessful one","vi":"sự đánh giá lại sự việc đã qua; cuộc họp rút kinh nghiệm; sự tổng kết"},{"pos":"adj.","en":"happening or performed after death","vi":"sau khi chết; xảy ra sau khi qua đời"}],"examples":[{"en":"Our team held a postmortem after the disappointing match.","vi":"Đội của chúng tôi đã tổ chức một buổi họp rút kinh nghiệm sau trận đấu gây thất vọng đó.","audioKind":"ex"},{"en":"A postmortem can provide crucial evidence about the cause of death and help improve public health monitoring.","vi":"Việc khám nghiệm tử thi có thể cung cấp những bằng chứng quan trọng về nguyên nhân tử vong và giúp cải thiện công tác giám sát y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"conduct a postmortem","vi":"tiến hành khám nghiệm tử thi"},{"en":"postmortem examination","vi":"cuộc kiểm tra khám nghiệm tử thi"},{"en":"postmortem analysis","vi":"phân tích sự việc sau khi kết thúc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Anh thường viết là post-mortem; từ này cũng có thể dùng theo nghĩa ẩn dụ cho việc tổng kết sau một sự kiện hoặc dự án.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brisk', 'en-c1-21', 'brisk', '/brɪsk/', 'C1', 'nhanh nhẹn; khẩn trương; tấp nập; sôi động; mát mẻ; trong lành', 'adj.', 'briskly (adv.), briskness (n.)', NULL, 'brisk walk chỉ việc đi bộ nhanh nhẹn, không phải chạy.', 'A brisk walk before breakfast always wakes me up.', NULL, 'Đi bộ nhanh trước bữa sáng luôn giúp tôi tỉnh táo hẳn lên.', '{"wordId":"brisk","ukIpa":"/brɪsk/","usIpa":"/brɪsk/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"Quick and energetic.","vi":"nhanh nhẹn; khẩn trương"},{"pos":"adj.","en":"Involving a lot of buying and selling.","vi":"tấp nập; sôi động"},{"pos":"adj.","en":"Cold and fresh in a pleasant, energising way.","vi":"mát mẻ; trong lành"}],"examples":[{"en":"A brisk walk before breakfast always wakes me up.","vi":"Đi bộ nhanh trước bữa sáng luôn giúp tôi tỉnh táo hẳn lên.","audioKind":"ex"},{"en":"Regular brisk walking can improve cardiovascular health without requiring expensive equipment or access to specialist facilities.","vi":"Thường xuyên đi bộ nhanh có thể cải thiện sức khỏe tim mạch mà không cần thiết bị đắt tiền hay cơ sở vật chất chuyên dụng.","audioKind":"ex2"}],"collocations":[{"en":"a brisk walk","vi":"một buổi đi bộ nhanh"},{"en":"brisk trade","vi":"việc buôn bán tấp nập"},{"en":"a brisk breeze","vi":"một làn gió mát"}],"wordFamily":["briskly (adv.)","briskness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"brisk walk chỉ việc đi bộ nhanh nhẹn, không phải chạy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exertion', 'en-c1-21', 'exertion', '/ɪɡˈzɝːʃən/', 'C1', 'sự gắng sức; sự tiêu tốn sức lực hoặc trí lực', 'n.', 'exert (v.)', 'Đồng nghĩa: effort', 'Thường chỉ sự tiêu hao năng lượng thể chất hoặc tinh thần, không đồng nghĩa hoàn toàn với việc cố gắng chung chung try hard.', 'He was breathless from the exertion of climbing upstairs.', NULL, 'Anh ấy thở hổn hển vì gắng sức leo cầu thang.', '{"wordId":"exertion","ukIpa":"/ɪɡˈzɜːʃən/","usIpa":"/ɪɡˈzɝːʃən/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"Physical or mental effort, especially when it makes you tired.","vi":"sự gắng sức; sự tiêu tốn sức lực hoặc trí lực"}],"examples":[{"en":"He was breathless from the exertion of climbing upstairs.","vi":"Anh ấy thở hổn hển vì gắng sức leo cầu thang.","audioKind":"ex"},{"en":"Regular physical activity benefits health, but excessive exertion without adequate recovery can increase the risk of injury.","vi":"Hoạt động thể chất đều đặn mang lại lợi ích cho sức khỏe, nhưng việc gắng sức quá mức mà không có thời gian hồi phục hợp lý có thể làm tăng nguy cơ chấn thương.","audioKind":"ex2"}],"collocations":[{"en":"physical exertion","vi":"sự gắng sức về thể chất"},{"en":"mental exertion","vi":"sự vận động trí óc"},{"en":"strenuous exertion","vi":"sự gắng sức nặng nhọc"},{"en":"excessive exertion","vi":"sự gắng sức quá mức"}],"wordFamily":["exert (v.)"],"synonyms":["effort"],"antonyms":[],"tipVi":"Thường chỉ sự tiêu hao năng lượng thể chất hoặc tinh thần, không đồng nghĩa hoàn toàn với việc cố gắng chung chung try hard.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_airway', 'en-c1-21', 'airway', '/ˈerweɪ/', 'C1', 'đường hô hấp; khí quản; đường bay; tuyến hàng không', 'n.', NULL, NULL, 'Thường dùng để chỉ đường hô hấp; nghĩa tuyến bay mang tính chuyên ngành hơn, tránh nhầm lẫn với "airline".', 'The nurse checked that the patient''s airway was clear.', NULL, 'Y tá kiểm tra xem đường thở của bệnh nhân có thông thoáng không.', '{"wordId":"airway","ukIpa":"/ˈeəweɪ/","usIpa":"/ˈerweɪ/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"a passage through which air reaches the lungs","vi":"đường hô hấp; khí quản"},{"pos":"n.","en":"an established route used by aircraft","vi":"đường bay; tuyến hàng không"}],"examples":[{"en":"The nurse checked that the patient''s airway was clear.","vi":"Y tá kiểm tra xem đường thở của bệnh nhân có thông thoáng không.","audioKind":"ex"},{"en":"Heavy traffic along a major airway requires careful coordination to keep aircraft safely separated.","vi":"Lưu lượng giao thông dày đặc trên một tuyến bay chính đòi hỏi sự phối hợp cẩn thận để giữ khoảng cách an toàn cho máy bay.","audioKind":"ex2"}],"collocations":[{"en":"keep the airway clear","vi":"giữ đường thở thông thoáng"},{"en":"airway obstruction","vi":"tắc nghẽn đường hô hấp"},{"en":"upper airway","vi":"đường hô hấp trên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng để chỉ đường hô hấp; nghĩa tuyến bay mang tính chuyên ngành hơn, tránh nhầm lẫn với \"airline\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pharmaceutical', 'en-c1-21', 'pharmaceutical', '/ˌfɑːrməˈsuːtɪkəl/', 'C1', 'thuộc về dược phẩm; thuộc ngành chế tạo thuốc; dược phẩm; thuốc', 'adj.', 'pharmacy (n.), pharmacist (n.)', NULL, 'Dạng số nhiều pharmaceuticals thường dùng để chỉ chung các loại dược phẩm.', 'My sister works in a pharmaceutical research laboratory.', NULL, 'Chị tôi làm việc trong một phòng thí nghiệm nghiên cứu dược phẩm.', '{"wordId":"pharmaceutical","ukIpa":"/ˌfɑːməˈsuːtɪkəl/","usIpa":"/ˌfɑːrməˈsuːtɪkəl/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"relating to medicines or their production","vi":"thuộc về dược phẩm; thuộc ngành chế tạo thuốc"},{"pos":"n.","en":"a drug used as medicine","vi":"dược phẩm; thuốc"}],"examples":[{"en":"My sister works in a pharmaceutical research laboratory.","vi":"Chị tôi làm việc trong một phòng thí nghiệm nghiên cứu dược phẩm.","audioKind":"ex"},{"en":"Pharmaceutical companies should ensure that essential medicines remain affordable for patients in poorer communities.","vi":"Các công ty dược phẩm nên đảm bảo rằng các loại thuốc thiết yếu vẫn có giá cả phải chăng cho bệnh nhân ở các cộng đồng nghèo hơn.","audioKind":"ex2"}],"collocations":[{"en":"pharmaceutical industry","vi":"ngành công nghiệp dược phẩm"},{"en":"pharmaceutical company","vi":"công ty dược phẩm"},{"en":"pharmaceutical research","vi":"nghiên cứu dược phẩm"}],"wordFamily":["pharmacy (n.)","pharmacist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều pharmaceuticals thường dùng để chỉ chung các loại dược phẩm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_21_1', 'en-c1-21', 'Cách dùng “postmortem” (n.) — khám nghiệm tử thi; pháp y', 'conduct a postmortem  ·  postmortem examination  ·  postmortem analysis', 'Trong tiếng Anh Anh thường viết là post-mortem; từ này cũng có thể dùng theo nghĩa ẩn dụ cho việc tổng kết sau một sự kiện hoặc dự án.', NULL, '[{"hanzi":"Our team held a postmortem after the disappointing match.","pinyin":"","meaning":"Đội của chúng tôi đã tổ chức một buổi họp rút kinh nghiệm sau trận đấu gây thất vọng đó."},{"hanzi":"A postmortem can provide crucial evidence about the cause of death and help improve public health monitoring.","pinyin":"","meaning":"Việc khám nghiệm tử thi có thể cung cấp những bằng chứng quan trọng về nguyên nhân tử vong và giúp cải thiện công tác giám sát y tế công cộng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_21_2', 'en-c1-21', 'Cách dùng “exertion” (n.) — sự gắng sức; sự tiêu tốn sức lực hoặc trí lực', 'physical exertion  ·  mental exertion  ·  strenuous exertion', 'Thường chỉ sự tiêu hao năng lượng thể chất hoặc tinh thần, không đồng nghĩa hoàn toàn với việc cố gắng chung chung try hard.', 'Họ từ (Word Family): exert (v.) | Đồng nghĩa: effort', '[{"hanzi":"He was breathless from the exertion of climbing upstairs.","pinyin":"","meaning":"Anh ấy thở hổn hển vì gắng sức leo cầu thang."},{"hanzi":"Regular physical activity benefits health, but excessive exertion without adequate recovery can increase the risk of injury.","pinyin":"","meaning":"Hoạt động thể chất đều đặn mang lại lợi ích cho sức khỏe, nhưng việc gắng sức quá mức mà không có thời gian hồi phục hợp lý có thể làm tăng nguy cơ chấn thương."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_21_3', 'en-c1-21', 'Cách dùng “deficient” (adj.) — thiếu thốn; không đủ (những thứ cần thiết)', 'deficient in iron  ·  nutritionally deficient  ·  deficient in essential nutrients', 'Diễn tả việc thiếu hụt thứ gì đó bằng cấu trúc be deficient in, thường gặp trong các mô tả về dinh dưỡng và năng lực.', 'Họ từ (Word Family): deficiency (n.) | Đồng nghĩa: lacking, inadequate · Trái nghĩa: sufficient, adequate', '[{"hanzi":"The doctor said my diet was deficient in iron.","pinyin":"","meaning":"Bác sĩ nói rằng chế độ ăn của tôi đang bị thiếu sắt."},{"hanzi":"Communities with deficient healthcare services often face greater difficulties in preventing disease and supporting older residents.","pinyin":"","meaning":"Các cộng đồng có dịch vụ y tế kém phát triển thường phải đối mặt với nhiều khó khăn lớn hơn trong việc phòng ngừa dịch bệnh và hỗ trợ cư dân cao tuổi."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_21_4', 'en-c1-21', 'Cách dùng “alleviate” (v.) — làm giảm; xoa dịu; làm nhẹ bớt', 'alleviate pain  ·  alleviate poverty  ·  alleviate pressure', 'Trực tiếp đi với nỗi đau hoặc vấn đề; thể hiện việc làm giảm bớt chứ không nhất thiết là giải quyết triệt để.', 'Họ từ (Word Family): alleviation (n.) | Đồng nghĩa: ease, relieve · Trái nghĩa: aggravate, worsen', '[{"hanzi":"A warm bath helped alleviate the ache in my shoulders.","pinyin":"","meaning":"Tắm nước ấm giúp làm dịu cơn đau mỏi ở vai của tôi."},{"hanzi":"Expanding affordable housing could alleviate pressure on low-income families and reduce the risk of homelessness.","pinyin":"","meaning":"Việc mở rộng nhà ở giá rẻ có thể làm giảm áp lực cho các gia đình thu nhập thấp và giảm nguy cơ vô gia cư."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_21_1', 'en-c1-21', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_1_1', 'ten_c1_21_1', 'preoperative', 'The nurse explained my preoperative checks before tomorrow''s surgery.', 'The nurse explained my preoperative checks before tomorrow''s surgery.', '/ˌpriːˈɑːpərətɪv/', 'Y tá đã giải thích cho tôi về các xét nghiệm trước ca phẫu thuật vào ngày mai.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_1_2', 'ten_c1_21_1', 'acute', 'The village faced an acute water shortage last summer.', 'The village faced an acute water shortage last summer.', '/əˈkjuːt/', 'Ngôi làng phải đối mặt với tình trạng thiếu nước trầm trọng vào mùa hè năm ngoái.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_1_3', 'ten_c1_21_1', 'ventilate', 'Open both windows to ventilate the kitchen after cooking.', 'Open both windows to ventilate the kitchen after cooking.', '/ˈventəleɪt/', 'Hãy mở cả hai cửa sổ để làm thoáng khí nhà bếp sau khi nấu ăn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_1_4', 'ten_c1_21_1', 'recur', 'If these headaches recur, please speak to your doctor.', 'If these headaches recur, please speak to your doctor.', '/rɪˈkɝː/', 'Nếu những cơn đau đầu này tái phát, xin vui lòng đến gặp bác sĩ để được tư vấn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_1_5', 'ten_c1_21_1', 'tranquilizer', 'The vet gave the frightened horse a tranquilizer.', 'The vet gave the frightened horse a tranquilizer.', '/ˈtræŋkwɪlaɪzər/', 'Bác sĩ thú y đã tiêm thuốc an thần cho con ngựa đang hoảng sợ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_1_6', 'ten_c1_21_1', 'perspire', 'I began to perspire while carrying the heavy boxes.', 'I began to perspire while carrying the heavy boxes.', '/pərˈspaɪr/', 'Tôi bắt đầu đổ mồ hôi khi khiêng những chiếc thùng nặng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_1_7', 'ten_c1_21_1', 'scalpel', 'The surgeon placed the scalpel on a clean tray.', 'The surgeon placed the scalpel on a clean tray.', '/ˈskælpəl/', 'Bác sĩ phẫu thuật đặt con dao mổ lên một khay sạch.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_1_8', 'ten_c1_21_1', 'deficiency', 'A blood test revealed that I had an iron deficiency.', 'A blood test revealed that I had an iron deficiency.', '/dɪˈfɪʃənsi/', 'Kết quả xét nghiệm máu cho thấy tôi bị thiếu sắt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_21_1_1', 'en-c1-21', 'ten_c1_21_1', 'listening', 'listening', 'The nurse explained my preoperative checks before tomorrow''s surgery.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Y tá đã giải thích cho tôi về các xét nghiệm trước ca phẫu thuật vào ngày mai.","Những cơn mưa bắt đầu đột ngột khiến chúng tôi phải chạy vội vào nhà.","Tắm nước ấm giúp làm dịu cơn đau mỏi ở vai của tôi.","Đội của chúng tôi đã tổ chức một buổi họp rút kinh nghiệm sau trận đấu gây thất vọng đó."]'::jsonb, 0, 'The nurse explained my preoperative checks before tomorrow''s surgery. → Y tá đã giải thích cho tôi về các xét nghiệm trước ca phẫu thuật vào ngày mai.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_21_1_2', 'en-c1-21', 'ten_c1_21_1', 'listening', 'listening', 'The village faced an acute water shortage last summer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ngôi làng phải đối mặt với tình trạng thiếu nước trầm trọng vào mùa hè năm ngoái.","Anh ấy thở hổn hển vì gắng sức leo cầu thang.","Kết quả xét nghiệm máu cho thấy tôi bị thiếu sắt.","Đội của chúng tôi đã tổ chức một buổi họp rút kinh nghiệm sau trận đấu gây thất vọng đó."]'::jsonb, 0, 'The village faced an acute water shortage last summer. → Ngôi làng phải đối mặt với tình trạng thiếu nước trầm trọng vào mùa hè năm ngoái.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_21_1_3', 'en-c1-21', 'ten_c1_21_1', 'listening', 'listening', 'Open both windows to ventilate the kitchen after cooking.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy mở cả hai cửa sổ để làm thoáng khí nhà bếp sau khi nấu ăn.","Anh ấy thở hổn hển vì gắng sức leo cầu thang.","Bác sĩ nói rằng chế độ ăn của tôi đang bị thiếu sắt.","Nếu những cơn đau đầu này tái phát, xin vui lòng đến gặp bác sĩ để được tư vấn."]'::jsonb, 0, 'Open both windows to ventilate the kitchen after cooking. → Hãy mở cả hai cửa sổ để làm thoáng khí nhà bếp sau khi nấu ăn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_21_2', 'en-c1-21', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_2_1', 'ten_c1_21_2', 'preoperative', 'Thorough preoperative assessment helps medical teams identify potential risks and plan appropriate care for each patient.', 'Thorough preoperative assessment helps medical teams identify potential risks and plan appropriate care for each patient.', '/ˌpriːˈɑːpərətɪv/', 'Đánh giá tiền phẫu toàn diện giúp đội ngũ y tế xác định các rủi ro tiềm ẩn và lên kế hoạch chăm sóc phù hợp cho từng bệnh nhân.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_2_2', 'ten_c1_21_2', 'acute', 'An acute shortage of affordable housing forces many young workers to live far from their workplaces.', 'An acute shortage of affordable housing forces many young workers to live far from their workplaces.', '/əˈkjuːt/', 'Tình trạng thiếu hụt trầm trọng nhà ở giá rẻ buộc nhiều lao động trẻ phải sống xa nơi làm việc của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_2_3', 'ten_c1_21_2', 'ventilate', 'Schools should ventilate classrooms regularly to improve indoor air quality and create healthier learning environments.', 'Schools should ventilate classrooms regularly to improve indoor air quality and create healthier learning environments.', '/ˈventəleɪt/', 'Các trường học nên thường xuyên thông gió cho phòng học nhằm cải thiện chất lượng không khí trong nhà và tạo môi trường học tập lành mạnh hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_2_4', 'ten_c1_21_2', 'recur', 'Traffic congestion will continue to recur unless cities address the underlying causes of excessive car use.', 'Traffic congestion will continue to recur unless cities address the underlying causes of excessive car use.', '/rɪˈkɝː/', 'Tình trạng ùn tắc giao thông sẽ tiếp tục tái diễn trừ khi các thành phố giải quyết được nguyên nhân gốc rễ của việc lạm dụng xe hơi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_2_5', 'ten_c1_21_2', 'tranquilizer', 'Doctors should carefully assess the risks before prescribing a tranquilizer to a patient with persistent anxiety.', 'Doctors should carefully assess the risks before prescribing a tranquilizer to a patient with persistent anxiety.', '/ˈtræŋkwɪlaɪzər/', 'Các bác sĩ nên thận trọng đánh giá các rủi ro trước khi kê đơn thuốc an thần cho bệnh nhân mắc chứng lo âu kéo dài.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_21_2_6', 'ten_c1_21_2', 'perspire', 'People perspire more during intense exercise because the body needs to release excess heat.', 'People perspire more during intense exercise because the body needs to release excess heat.', '/pərˈspaɪr/', 'Con người đổ mồ hôi nhiều hơn khi tập luyện cường độ cao vì cơ thể cần giải phóng lượng nhiệt dư thừa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_21_2_1', 'en-c1-21', 'ten_c1_21_2', 'listening', 'listening', 'Thorough preoperative assessment helps medical teams identify potential risks and plan appropriate care for each patient.', NULL, 'Trong câu vừa nghe, từ “preoperative” mang nghĩa nào sau đây?', '["khoan dung; nhân nhượng; không quá nghiêm khắc","bao dung; mang tính hòa nhập","thuộc về thần thánh; thiêng liêng","trước phẫu thuật; thuộc giai đoạn tiền phẫu"]'::jsonb, 3, '“preoperative” (/ˌpriːˈɑːpərətɪv/): trước phẫu thuật; thuộc giai đoạn tiền phẫu. Câu đầy đủ: Thorough preoperative assessment helps medical teams identify potential risks and plan appropriate care for each patient.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_21_2_2', 'en-c1-21', 'ten_c1_21_2', 'listening', 'listening', 'An acute shortage of affordable housing forces many young workers to live far from their workplaces.', NULL, 'Trong câu vừa nghe, từ “acute” mang nghĩa nào sau đây?', '["chất polymer; hợp chất cao phân tử","thẳng thắn bày tỏ quan điểm; công khai chỉ trích","trầm trọng; gay gắt","bắt buộc; cưỡng chế theo luật"]'::jsonb, 2, '“acute” (/əˈkjuːt/): trầm trọng; gay gắt. Câu đầy đủ: An acute shortage of affordable housing forces many young workers to live far from their workplaces.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
