INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_2', 'en-c1-21', NULL, 'comprehensive_test', 'listening', 'The village faced an acute water shortage last summer.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ngôi làng phải đối mặt với tình trạng thiếu nước trầm trọng vào mùa hè năm ngoái.","Chị tôi làm việc trong một phòng thí nghiệm nghiên cứu dược phẩm.","Bác sĩ phẫu thuật đặt con dao mổ lên một khay sạch.","Bác sĩ nói rằng chế độ ăn của tôi đang bị thiếu sắt."]'::jsonb, 0, 'The village faced an acute water shortage last summer. → Ngôi làng phải đối mặt với tình trạng thiếu nước trầm trọng vào mùa hè năm ngoái.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_3', 'en-c1-21', NULL, 'comprehensive_test', 'listening', 'ventilate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sắc lệnh; nghị định; quyết định chính thức","làm cho thông thoáng; thông gió","sự thanh bình, yên ả, không có tiếng ồn, lo lắng hay quấy rầy","cơ quan; sở; ban; văn phòng"]'::jsonb, 1, 'ventilate (/ˈventəleɪt/) → làm cho thông thoáng; thông gió; bộc lộ; bàn thảo công khai', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_4', 'en-c1-21', NULL, 'comprehensive_test', 'listening', 'If these headaches recur, please speak to your doctor.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nếu những cơn đau đầu này tái phát, xin vui lòng đến gặp bác sĩ để được tư vấn.","Bác sĩ nói rằng chế độ ăn của tôi đang bị thiếu sắt.","Bác sĩ thú y đã tiêm thuốc an thần cho con ngựa đang hoảng sợ.","Ngôi làng phải đối mặt với tình trạng thiếu nước trầm trọng vào mùa hè năm ngoái."]'::jsonb, 0, 'If these headaches recur, please speak to your doctor. → Nếu những cơn đau đầu này tái phát, xin vui lòng đến gặp bác sĩ để được tư vấn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_5', 'en-c1-21', NULL, 'comprehensive_test', 'listening', 'tranquilizer', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ngừng; chấm dứt; dừng lại","lủng lẳng; treo lơ lửng","kìm chế; tránh","thuốc an thần; thuốc trấn tĩnh"]'::jsonb, 3, 'tranquilizer (/ˈtræŋkwɪlaɪzər/) → thuốc an thần; thuốc trấn tĩnh', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_6', 'en-c1-21', NULL, 'comprehensive_test', 'listening', 'I began to perspire while carrying the heavy boxes.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi bắt đầu đổ mồ hôi khi khiêng những chiếc thùng nặng.","Việc bơi lội nhẹ nhàng giúp cô ấy kiểm soát cơn đau lưng mãn tính của mình.","Căn bệnh dị ứng theo mùa cứ hành hạ anh trai tôi mỗi khi hoa nở.","Sau trận ốm, anh ấy cảm thấy quá yếu để có thể nấu ăn."]'::jsonb, 0, 'I began to perspire while carrying the heavy boxes. → Tôi bắt đầu đổ mồ hôi khi khiêng những chiếc thùng nặng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_7', 'en-c1-21', NULL, 'comprehensive_test', 'listening', 'scalpel', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tạm thời; lâm thời","chủ yếu; cốt lõi; quan trọng nhất","dao mổ; dao giải phẫu","sự lấy mẫu; việc rút mẫu để nghiên cứu tổng thể"]'::jsonb, 2, 'scalpel (/ˈskælpəl/) → dao mổ; dao giải phẫu', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_8', 'en-c1-21', NULL, 'comprehensive_test', 'listening', 'A blood test revealed that I had an iron deficiency.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã dùng bao cát để gia cố bức tường trước cơn bão.","Kết quả xét nghiệm máu cho thấy tôi bị thiếu sắt.","Bác sĩ nói rằng chế độ ăn của tôi đang bị thiếu sắt.","Sau trận ốm, anh ấy cảm thấy quá yếu để có thể nấu ăn."]'::jsonb, 1, 'A blood test revealed that I had an iron deficiency. → Kết quả xét nghiệm máu cho thấy tôi bị thiếu sắt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_9', 'en-c1-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A drug used to calm people or animals and reduce anxiety.”?', '["acute","alleviate","brisk","tranquilizer"]'::jsonb, 3, 'tranquilizer (/ˈtræŋkwɪlaɪzər/) → thuốc an thần; thuốc trấn tĩnh', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_10', 'en-c1-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to release sweat through your skin, especially when hot”?', '["chronic","acute","ventilate","perspire"]'::jsonb, 3, 'perspire (/pərˈspaɪr/) → đổ mồ hôi; ra mồ hôi', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_11', 'en-c1-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A small, very sharp knife used in surgery or dissection.”?', '["lethal","scalpel","ventilate","syndrome"]'::jsonb, 1, 'scalpel (/ˈskælpəl/) → dao mổ; dao giải phẫu', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_12', 'en-c1-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A lack of enough of something necessary.”?', '["exertion","alleviate","deficiency","chronic"]'::jsonb, 2, 'deficiency (/dɪˈfɪʃənsi/) → sự thiếu hụt; không đủ', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_13', 'en-c1-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the complete removal or destruction of something harmful”?', '["eradication","syndrome","drunkard","deficient"]'::jsonb, 0, 'eradication (/ɪˌrædɪˈkeɪʃən/) → sự triệt phá; sự xóa sổ hoàn toàn', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
