INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_18', 'en-c1-21', NULL, 'comprehensive_test', 'reading', NULL, 'Thorough preoperative assessment helps medical teams identify potential risks and plan appropriate care for each patient.', 'Dựa vào câu trên, từ “preoperative” có nghĩa phù hợp nhất là gì?', '["trước phẫu thuật; thuộc giai đoạn tiền phẫu","mạch lạc; rành mạch; chặt chẽ","làm tê liệt; tàn phá năng lực hoạt động","thuộc về vùng núi cao; thuộc dãy An-pơ"]'::jsonb, 0, 'preoperative: trước phẫu thuật; thuộc giai đoạn tiền phẫu. Dịch cả câu: Đánh giá tiền phẫu toàn diện giúp đội ngũ y tế xác định các rủi ro tiềm ẩn và lên kế hoạch chăm sóc phù hợp cho từng bệnh nhân.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_19', 'en-c1-21', NULL, 'comprehensive_test', 'reading', NULL, 'An acute shortage of affordable housing forces many young workers to live far from their workplaces.', 'Dựa vào câu trên, từ “acute” có nghĩa phù hợp nhất là gì?', '["truyền bá; tuyên truyền","đàn (côn trùng); bầy","thuộc tỉnh; cấp tỉnh","trầm trọng; gay gắt"]'::jsonb, 3, 'acute: trầm trọng; gay gắt; cấp tính; sắc bén; nhạy bén. Dịch cả câu: Tình trạng thiếu hụt trầm trọng nhà ở giá rẻ buộc nhiều lao động trẻ phải sống xa nơi làm việc của họ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_20', 'en-c1-21', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should ventilate classrooms regularly to improve indoor air quality and create healthier learning environments.', 'Dựa vào câu trên, từ “ventilate” có nghĩa phù hợp nhất là gì?', '["thạch anh","làm cho thông thoáng; thông gió","cực kỳ; vô cùng","sự đánh giá lại; sự xem xét lại"]'::jsonb, 1, 'ventilate: làm cho thông thoáng; thông gió; bộc lộ; bàn thảo công khai. Dịch cả câu: Các trường học nên thường xuyên thông gió cho phòng học nhằm cải thiện chất lượng không khí trong nhà và tạo môi trường học tập lành mạnh hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_21', 'en-c1-21', NULL, 'comprehensive_test', 'reading', NULL, 'Traffic congestion will continue to recur unless cities address the underlying causes of excessive car use.', 'Dựa vào câu trên, từ “recur” có nghĩa phù hợp nhất là gì?', '["cuộc tổng điều tra dân số; phép kiểm kê dân số","lại xảy ra; lặp lại; tái diễn","quả quyết, khẳng định, khẳng định chắc nịch rằng điều gì là đúng","cho là; đánh giá là; coi là"]'::jsonb, 1, 'recur: lại xảy ra; lặp lại; tái diễn. Dịch cả câu: Tình trạng ùn tắc giao thông sẽ tiếp tục tái diễn trừ khi các thành phố giải quyết được nguyên nhân gốc rễ của việc lạm dụng xe hơi.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_22', 'en-c1-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự gắng sức; sự tiêu tốn sức lực hoặc trí lực”', '["requisite","conception","intervene","exertion"]'::jsonb, 3, 'sự gắng sức; sự tiêu tốn sức lực hoặc trí lực → exertion (/ɪɡˈzɝːʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_23', 'en-c1-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đường hô hấp; khí quản”', '["financier","heighten","communicative","airway"]'::jsonb, 3, 'đường hô hấp; khí quản → airway (/ˈerweɪ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_21_24', 'en-c1-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về dược phẩm; thuộc ngành chế tạo thuốc”', '["instantaneous","exasperate","illegible","pharmaceutical"]'::jsonb, 3, 'thuộc về dược phẩm; thuộc ngành chế tạo thuốc → pharmaceutical (/ˌfɑːrməˈsuːtɪkəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-22', 'en', 'Bài 22: Sức khỏe & Cơ thể (2) - CEFR C1', 'CEFR C1', 'C1 · Sức khỏe', '25 từ vựng Tiếng Anh CEFR C1 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5022, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fatigue', 'en-c1-22', 'fatigue', '/fəˈtiːɡ/', 'C1', 'sự mệt mỏi; sự kiệt sức; sự mỏi vật liệu; hiện tượng mỏi', 'n.', 'fatigued (adj.), fatiguing (adj.)', 'Đồng nghĩa: exhaustion, tiredness', 'Thường là danh từ không đếm được, mang tính trang trọng hơn từ tiredness.', 'After the long hike, fatigue made my legs shake.', NULL, 'Sau chuyến đi bộ đường dài, sự mệt mỏi khiến chân tôi run rẩy.', '{"wordId":"fatigue","ukIpa":"/fəˈtiːɡ/","usIpa":"/fəˈtiːɡ/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"extreme tiredness caused by effort, stress, or illness","vi":"sự mệt mỏi; sự kiệt sức"},{"pos":"n.","en":"weakening of a material after repeated stress","vi":"sự mỏi vật liệu; hiện tượng mỏi"}],"examples":[{"en":"After the long hike, fatigue made my legs shake.","vi":"Sau chuyến đi bộ đường dài, sự mệt mỏi khiến chân tôi run rẩy.","audioKind":"ex"},{"en":"Persistent fatigue can reduce employees'' concentration and increase the likelihood of accidents in the workplace.","vi":"Sự mệt mỏi kéo dài có thể làm giảm khả năng tập trung của nhân viên và làm tăng nguy cơ xảy ra tai nạn tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"chronic fatigue","vi":"mệt mỏi mãn tính"},{"en":"mental fatigue","vi":"mệt mỏi tinh thần"},{"en":"muscle fatigue","vi":"mỏi cơ"},{"en":"metal fatigue","vi":"mỏi kim loại"}],"wordFamily":["fatigued (adj.)","fatiguing (adj.)"],"synonyms":["exhaustion","tiredness"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được, mang tính trang trọng hơn từ tiredness.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transplant', 'en-c1-22', 'transplant', '/trænsˈplænt/', 'C1', 'cấy ghép nội tạng; bứng cây; ca phẫu thuật cấy ghép; bộ phận cấy ghép', 'v.', 'transplantation (n.)', NULL, 'Động từ nhấn trọng âm ở âm tiết cuối, danh từ nhấn trọng âm ở âm tiết đầu; có thể dùng cho cả cơ quan cơ thể lẫn thực vật.', 'We transplant the seedlings once their roots are strong.', NULL, 'Chúng tôi tiến hành bứng cây con khi rễ của chúng đã khỏe mạnh.', '{"wordId":"transplant","ukIpa":"/trænsˈplɑːnt/","usIpa":"/trænsˈplænt/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"To move an organ or plant into a new location.","vi":"cấy ghép nội tạng; bứng cây"},{"pos":"n.","en":"An operation transferring an organ, or the organ transferred.","vi":"ca phẫu thuật cấy ghép; bộ phận cấy ghép"}],"examples":[{"en":"We transplant the seedlings once their roots are strong.","vi":"Chúng tôi tiến hành bứng cây con khi rễ của chúng đã khỏe mạnh.","audioKind":"ex"},{"en":"Advances in medicine have made it possible to transplant organs successfully and improve patients'' quality of life.","vi":"Những tiến bộ trong y học đã giúp cấy ghép nội tạng thành công và nâng cao chất lượng cuộc sống cho bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"transplant seedlings","vi":"trồng cấy cây con"},{"en":"a kidney transplant","vi":"ca ghép thận"},{"en":"an organ transplant","vi":"ca ghép tạng"},{"en":"transplant surgery","vi":"phẫu thuật cấy ghép"}],"wordFamily":["transplantation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ nhấn trọng âm ở âm tiết cuối, danh từ nhấn trọng âm ở âm tiết đầu; có thể dùng cho cả cơ quan cơ thể lẫn thực vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amputate', 'en-c1-22', 'amputate', '/ˈæmpjəteɪt/', 'C1', 'cắt cụt; phẫu thuật cắt bỏ bộ phận cơ thể', 'v.', 'amputation (n.), amputee (n.)', NULL, 'Chủ yếu dùng trong phẫu thuật cắt bỏ chi, không dùng chung cho tất cả các cơ quan.', 'The vet had to amputate the cat''s badly injured leg.', NULL, 'Bác sĩ thú y buộc phải cắt cụt cái chân bị thương nặng của con mèo.', '{"wordId":"amputate","ukIpa":"/ˈæmpjʊteɪt/","usIpa":"/ˈæmpjəteɪt/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"To surgically remove all or part of a limb.","vi":"cắt cụt; phẫu thuật cắt bỏ bộ phận cơ thể"}],"examples":[{"en":"The vet had to amputate the cat''s badly injured leg.","vi":"Bác sĩ thú y buộc phải cắt cụt cái chân bị thương nặng của con mèo.","audioKind":"ex"},{"en":"Early treatment of severe infections can reduce the need to amputate limbs and improve patients'' quality of life.","vi":"Việc điều trị sớm các trường hợp nhiễm trùng nặng có thể làm giảm nhu cầu cắt cụt chi và nâng cao chất lượng cuộc sống cho bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"amputate a limb","vi":"cắt cụt một chi"},{"en":"amputate a leg","vi":"cắt cụt một bên chân"},{"en":"amputate below the knee","vi":"cắt cụt từ đầu gối trở xuống"}],"wordFamily":["amputation (n.)","amputee (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu dùng trong phẫu thuật cắt bỏ chi, không dùng chung cho tất cả các cơ quan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_narcotic', 'en-c1-22', 'narcotic', '/nɑːrˈkɑːtɪk/', 'C1', 'thuốc giảm đau gây ngủ; chất gây nghiện; có tính gây ngủ; gây tê', 'n.', NULL, NULL, 'Trong y học thường chỉ thuốc giảm đau gây ngủ; trong ngữ cảnh pháp lý có thể hiểu chung là ma túy.', 'The doctor prescribed a narcotic for severe pain after surgery.', NULL, 'Bác sĩ đã kê đơn thuốc giảm đau gây ngủ cho cơn đau dữ dội sau phẫu thuật.', '{"wordId":"narcotic","ukIpa":"/nɑːˈkɒtɪk/","usIpa":"/nɑːrˈkɑːtɪk/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"a sleep-inducing painkiller; also an illegal drug","vi":"thuốc giảm đau gây ngủ; chất gây nghiện"},{"pos":"adj.","en":"causing sleep or reduced awareness","vi":"có tính gây ngủ; gây tê"}],"examples":[{"en":"The doctor prescribed a narcotic for severe pain after surgery.","vi":"Bác sĩ đã kê đơn thuốc giảm đau gây ngủ cho cơn đau dữ dội sau phẫu thuật.","audioKind":"ex"},{"en":"Strict controls on narcotic medicines should prevent misuse without limiting access for patients with severe pain.","vi":"Việc kiểm soát chặt chẽ các loại dược phẩm gây ngủ sẽ ngăn chặn tình trạng lạm dụng mà không hạn chế khả năng tiếp cận của những bệnh nhân bị đau đớn dữ dội.","audioKind":"ex2"}],"collocations":[{"en":"narcotic painkiller","vi":"thuốc giảm đau gây ngủ"},{"en":"narcotic drugs","vi":"chất gây nghiện; thuốc ma túy"},{"en":"narcotic effect","vi":"tác dụng gây ngủ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong y học thường chỉ thuốc giảm đau gây ngủ; trong ngữ cảnh pháp lý có thể hiểu chung là ma túy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ultrasound', 'en-c1-22', 'ultrasound', '/ˈʌltrəsaʊnd/', 'C1', 'siêu âm (tần số âm thanh quá cao mà con người không thể nghe thấy); siêu âm, phương pháp khám bệnh dùng sóng âm để hiển thị các cơ quan nội bên trong', 'n.', 'ultrasonic (adj.)', NULL, 'Chỉ siêu âm nói chung là danh từ không đếm được; chỉ một lần khám siêu âm cụ thể có thể dùng an ultrasound.', 'The doctor used ultrasound to examine my shoulder.', NULL, 'Bác sĩ đã dùng máy siêu âm để kiểm tra vai của tôi.', '{"wordId":"ultrasound","ukIpa":"/ˈʌltrəsaʊnd/","usIpa":"/ˈʌltrəsaʊnd/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"sound with frequencies too high for humans to hear","vi":"siêu âm (tần số âm thanh quá cao mà con người không thể nghe thấy)"},{"pos":"n.","en":"a medical examination using sound waves to show internal organs","vi":"siêu âm, phương pháp khám bệnh dùng sóng âm để hiển thị các cơ quan nội bên trong"}],"examples":[{"en":"The doctor used ultrasound to examine my shoulder.","vi":"Bác sĩ đã dùng máy siêu âm để kiểm tra vai của tôi.","audioKind":"ex"},{"en":"Ultrasound allows doctors to examine internal organs without exposing patients to the radiation used in conventional X-rays.","vi":"Phương pháp siêu âm giúp bác sĩ kiểm tra các cơ quan nội tạng mà không làm bệnh nhân tiếp xúc với bức xạ như trong chụp X-quang thông thường.","audioKind":"ex2"}],"collocations":[{"en":"ultrasound scan","vi":"chụp siêu âm"},{"en":"ultrasound imaging","vi":"hình ảnh siêu âm"},{"en":"ultrasound waves","vi":"sóng siêu âm"}],"wordFamily":["ultrasonic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ siêu âm nói chung là danh từ không đếm được; chỉ một lần khám siêu âm cụ thể có thể dùng an ultrasound.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nostril', 'en-c1-22', 'nostril', '/ˈnɑːstrəl/', 'C1', 'lỗ mũi', 'n.', NULL, NULL, 'Là danh từ đếm được; khi chỉ cả hai bên lỗ mũi thì dùng dạng số nhiều nostrils.', 'One nostril felt blocked when I woke this morning.', NULL, 'Một bên lỗ mũi của tôi cảm thấy bị nghẹt khi tôi thức dậy sáng nay.', '{"wordId":"nostril","ukIpa":"/ˈnɒstrəl/","usIpa":"/ˈnɑːstrəl/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"Either of the two openings at the bottom of the nose.","vi":"lỗ mũi"}],"examples":[{"en":"One nostril felt blocked when I woke this morning.","vi":"Một bên lỗ mũi của tôi cảm thấy bị nghẹt khi tôi thức dậy sáng nay.","audioKind":"ex"},{"en":"Air entering through each nostril is warmed and filtered before it reaches the lungs.","vi":"Không khí đi qua mỗi lỗ mũi sẽ được làm ấm và lọc sạch trước khi đến phổi.","audioKind":"ex2"}],"collocations":[{"en":"blocked nostril","vi":"lỗ mũi bị nghẹt"},{"en":"flared nostrils","vi":"lỗ mũi phập phồng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; khi chỉ cả hai bên lỗ mũi thì dùng dạng số nhiều nostrils.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paralysis', 'en-c1-22', 'paralysis', '/pəˈræləsɪs/', 'C1', 'chứng liệt; sự tê liệt (cơ thể); sự ngưng trệ, sự tê liệt (hoạt động hoặc tiến trình)', 'n.', 'paralyse (v.), paralysed (adj.), paralytic (adj.)', NULL, 'Vừa chỉ tình trạng liệt thể xác, vừa có thể dùng theo nghĩa ẩn dụ cho cơ quan hoặc quyết định bị đình trệ.', 'The injury caused temporary paralysis in his left leg.', NULL, 'Chấn thương đã gây ra tình trạng tê liệt tạm thời ở chân trái của anh ấy.', '{"wordId":"paralysis","ukIpa":"/pəˈræləsɪs/","usIpa":"/pəˈræləsɪs/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"loss of the ability to move part or all of the body","vi":"chứng liệt; sự tê liệt (cơ thể)"},{"pos":"n.","en":"a state in which action or progress becomes impossible","vi":"sự ngưng trệ, sự tê liệt (hoạt động hoặc tiến trình)"}],"examples":[{"en":"The injury caused temporary paralysis in his left leg.","vi":"Chấn thương đã gây ra tình trạng tê liệt tạm thời ở chân trái của anh ấy.","audioKind":"ex"},{"en":"Political disagreements can lead to administrative paralysis, delaying essential decisions on housing and public transport.","vi":"Bất đồng chính trị có thể dẫn đến tình trạng tê liệt hành chính, làm chậm trễ các quyết định thiết yếu về nhà ở và giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"temporary paralysis","vi":"tình trạng liệt tạm thời"},{"en":"partial paralysis","vi":"liệt một phần"},{"en":"political paralysis","vi":"sự tê liệt chính trị"},{"en":"sleep paralysis","vi":"chứng bóng đè (tê liệt khi ngủ)"}],"wordFamily":["paralyse (v.)","paralysed (adj.)","paralytic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa chỉ tình trạng liệt thể xác, vừa có thể dùng theo nghĩa ẩn dụ cho cơ quan hoặc quyết định bị đình trệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hepatitis', 'en-c1-22', 'hepatitis', '/ˌhepəˈtaɪtɪs/', 'C1', 'viêm gan', 'n.', 'hepatic (adj.)', NULL, 'Thường là danh từ không đếm được; không phải tất cả các loại viêm gan đều do vi-rút gây ra.', 'The nurse explained how vaccination can prevent some hepatitis infections.', NULL, 'Y tá giải thích cách việc tiêm chủng có thể phòng ngừa một số ca nhiễm viêm gan.', '{"wordId":"hepatitis","ukIpa":"/ˌhepəˈtaɪtɪs/","usIpa":"/ˌhepəˈtaɪtɪs/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"Inflammation of the liver, sometimes caused by a virus.","vi":"viêm gan"}],"examples":[{"en":"The nurse explained how vaccination can prevent some hepatitis infections.","vi":"Y tá giải thích cách việc tiêm chủng có thể phòng ngừa một số ca nhiễm viêm gan.","audioKind":"ex"},{"en":"Public health programmes can reduce hepatitis transmission through vaccination, screening, and improved access to safe medical care.","vi":"Các chương trình y tế công cộng có thể làm giảm sự lây truyền viêm gan thông qua tiêm chủng, sàng lọc và cải thiện khả năng tiếp cận dịch vụ chăm sóc y tế an toàn.","audioKind":"ex2"}],"collocations":[{"en":"viral hepatitis","vi":"viêm gan vi-rút"},{"en":"hepatitis B","vi":"viêm gan B"},{"en":"hepatitis screening","vi":"sàng lọc viêm gan"}],"wordFamily":["hepatic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; không phải tất cả các loại viêm gan đều do vi-rút gây ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sober', 'en-c1-22', 'sober', '/ˈsoʊbər/', 'C1', 'tỉnh táo; không say rượu; nghiêm túc; điềm tĩnh; nhã nhặn; làm tỉnh táo; trở nên tỉnh táo', 'adj.', 'sobriety (n.), soberly (adv.), sobering (adj.)', 'Trái nghĩa: drunk', 'Cụm từ sober up có nghĩa là tỉnh rượu; ngoài ra sober cũng có thể dùng để mô tả phán nhận điềm tĩnh, sáng suốt.', 'My uncle stayed sober and drove everyone home safely.', NULL, 'Chú tôi vẫn giữ được sự tỉnh táo và lái xe đưa mọi người về nhà an toàn.', '{"wordId":"sober","ukIpa":"/ˈsəʊbə/","usIpa":"/ˈsoʊbər/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"Not drunk or affected by alcohol.","vi":"tỉnh táo; không say rượu"},{"pos":"adj.","en":"Serious and sensible, or plain rather than bright.","vi":"nghiêm túc; điềm tĩnh; nhã nhặn"},{"pos":"v.","en":"To become or make someone less drunk or more serious.","vi":"làm tỉnh táo; trở nên tỉnh táo"}],"examples":[{"en":"My uncle stayed sober and drove everyone home safely.","vi":"Chú tôi vẫn giữ được sự tỉnh táo và lái xe đưa mọi người về nhà an toàn.","audioKind":"ex"},{"en":"A sober assessment of environmental risks is essential before governments approve major construction projects.","vi":"Việc đánh giá điềm tĩnh các rủi ro môi trường là điều cốt yếu trước khi chính phủ phê duyệt các dự án xây dựng lớn.","audioKind":"ex2"}],"collocations":[{"en":"stay sober","vi":"giữ sự tỉnh táo"},{"en":"sober assessment","vi":"đánh giá khách quan, điềm tĩnh"},{"en":"sober colours","vi":"màu sắc trang nhã, nhã nhặn"},{"en":"sober up","vi":"giải rượu, làm tỉnh táo lại"}],"wordFamily":["sobriety (n.)","soberly (adv.)","sobering (adj.)"],"synonyms":[],"antonyms":["drunk"],"tipVi":"Cụm từ sober up có nghĩa là tỉnh rượu; ngoài ra sober cũng có thể dùng để mô tả phán nhận điềm tĩnh, sáng suốt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_psychiatry', 'en-c1-22', 'psychiatry', '/saɪˈkaɪətri/', 'C1', 'khoa tâm thần; ngành tâm thần học', 'n.', 'psychiatrist (n.), psychiatric (adj.)', NULL, 'Chữ cái đầu p trong từ này là âm câm; bác sĩ chuyên khoa tâm thần thường phải có bằng cấp y khoa.', 'My sister chose psychiatry after finishing her medical degree.', NULL, 'Chị tôi đã chọn theo học ngành tâm thần học sau khi hoàn thành bằng y khoa.', '{"wordId":"psychiatry","ukIpa":"/saɪˈkaɪətri/","usIpa":"/saɪˈkaɪətri/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"the medical study and treatment of mental illnesses","vi":"khoa tâm thần; ngành tâm thần học"}],"examples":[{"en":"My sister chose psychiatry after finishing her medical degree.","vi":"Chị tôi đã chọn theo học ngành tâm thần học sau khi hoàn thành bằng y khoa.","audioKind":"ex"},{"en":"Greater investment in psychiatry could improve access to specialist care for people with severe mental illnesses.","vi":"Việc đầu tư mạnh mẽ hơn vào lĩnh vực tâm thần học có thể giúp những người mắc bệnh tâm thần nặng tiếp cận tốt hơn với các dịch vụ điều trị chuyên khoa.","audioKind":"ex2"}],"collocations":[{"en":"a career in psychiatry","vi":"sự nghiệp trong ngành tâm thần học"},{"en":"child psychiatry","vi":"khoa tâm thần nhi"},{"en":"clinical psychiatry","vi":"tâm thần học lâm sàng"}],"wordFamily":["psychiatrist (n.)","psychiatric (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu p trong từ này là âm câm; bác sĩ chuyên khoa tâm thần thường phải có bằng cấp y khoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_detriment', 'en-c1-22', 'detriment', '/ˈdetrɪmənt/', 'C1', 'tổn hại; bất lợi', 'n.', 'detrimental (adj.), detrimentally (adv.)', 'Đồng nghĩa: harm, damage · Trái nghĩa: benefit', 'Cụm từ này thường xuất hiện nhất trong cấu trúc to the detriment of, diễn tả việc đánh đổi hoặc làm tổn hại một yếu tố nào đó.', 'He works late, often to the detriment of his sleep.', NULL, 'Anh ấy làm việc muộn, và thường điều đó gây hại cho giấc ngủ của mình.', '{"wordId":"detriment","ukIpa":"/ˈdetrɪmənt/","usIpa":"/ˈdetrɪmənt/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"Harm or damage caused to someone or something.","vi":"tổn hại; bất lợi"}],"examples":[{"en":"He works late, often to the detriment of his sleep.","vi":"Anh ấy làm việc muộn, và thường điều đó gây hại cho giấc ngủ của mình.","audioKind":"ex"},{"en":"Prioritising short-term profits to the detriment of environmental protection can create substantial costs for future generations.","vi":"Việc ưu tiên lợi nhuận ngắn hạn nhưng lại làm tổn hại đến công tác bảo vệ môi trường có thể tạo ra những chi phí đáng kể cho các thế hệ tương lai.","audioKind":"ex2"}],"collocations":[{"en":"to the detriment of","vi":"có hại cho; gây tổn hại đến"},{"en":"without detriment to","vi":"không làm tổn hại đến"},{"en":"a detriment to health","vi":"mối nguy hại cho sức khỏe"}],"wordFamily":["detrimental (adj.)","detrimentally (adv.)"],"synonyms":["harm","damage"],"antonyms":["benefit"],"tipVi":"Cụm từ này thường xuất hiện nhất trong cấu trúc to the detriment of, diễn tả việc đánh đổi hoặc làm tổn hại một yếu tố nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_malpractice', 'en-c1-22', 'malpractice', '/ˌmælˈpræktɪs/', 'C1', 'sự tắc trách; hành vi sai trái trong nghề nghiệp', 'n.', NULL, 'Đồng nghĩa: professional misconduct, negligence', 'Thường chỉ hành vi thiếu trách nhiệm của chuyên gia, đặc biệt trong lĩnh vực y tế, chứ không phải lỗi lầm thông thường.', 'The family consulted a lawyer about possible medical malpractice.', NULL, 'Gia đình đã tham khảo ý kiến luật sư về khả năng xảy ra sai sót y khoa.', '{"wordId":"malpractice","ukIpa":"/ˌmælˈpræktɪs/","usIpa":"/ˌmælˈpræktɪs/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"careless, improper, or illegal professional conduct, especially in medicine","vi":"sự tắc trách; hành vi sai trái trong nghề nghiệp"}],"examples":[{"en":"The family consulted a lawyer about possible medical malpractice.","vi":"Gia đình đã tham khảo ý kiến luật sư về khả năng xảy ra sai sót y khoa.","audioKind":"ex"},{"en":"Independent oversight can help prevent malpractice in healthcare and strengthen public confidence in medical institutions.","vi":"Sự giám sát độc lập có thể giúp ngăn chặn tình trạng hành nghề sai trái trong y tế và củng cố niềm tin của công chúng vào các cơ quan y tế.","audioKind":"ex2"}],"collocations":[{"en":"medical malpractice","vi":"sai sót y khoa"},{"en":"professional malpractice","vi":"sai phạm nghề nghiệp"},{"en":"malpractice lawsuit","vi":"kiện tụng sai sót y khoa"}],"wordFamily":[],"synonyms":["professional misconduct","negligence"],"antonyms":[],"tipVi":"Thường chỉ hành vi thiếu trách nhiệm của chuyên gia, đặc biệt trong lĩnh vực y tế, chứ không phải lỗi lầm thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_malnutrition', 'en-c1-22', 'malnutrition', '/ˌmælnuːˈtrɪʃən/', 'C1', 'tình trạng sức khỏe kém do thiếu hụt hoặc mất cân bằng chất dinh dưỡng', 'n.', 'malnourished (adj.), nutrition (n.), nutritional (adj.)', NULL, 'Là danh từ không đếm được; không chỉ có nghĩa là ăn ít, mà còn bao gồm việc hấp thụ dinh dưỡng không cân đối.', 'The rescued kitten needed special food to treat malnutrition.', NULL, 'Chú mèo con được cứu cần có thức ăn đặc biệt để điều trị tình trạng suy dinh dưỡng.', '{"wordId":"malnutrition","ukIpa":"/ˌmælnjuːˈtrɪʃən/","usIpa":"/ˌmælnuːˈtrɪʃən/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"poor health caused by insufficient or unbalanced nutrients","vi":"tình trạng sức khỏe kém do thiếu hụt hoặc mất cân bằng chất dinh dưỡng"}],"examples":[{"en":"The rescued kitten needed special food to treat malnutrition.","vi":"Chú mèo con được cứu cần có thức ăn đặc biệt để điều trị tình trạng suy dinh dưỡng.","audioKind":"ex"},{"en":"School meal programmes can reduce childhood malnutrition by providing balanced diets to children from low-income households.","vi":"Các chương trình bữa ăn học đường có thể làm giảm tình trạng suy dinh dưỡng ở trẻ em bằng cách cung cấp chế độ ăn uống cân bằng cho trẻ đến từ các hộ gia đình có thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"suffer from malnutrition","vi":"mắc chứng suy dinh dưỡng"},{"en":"severe malnutrition","vi":"suy dinh dưỡng nặng"},{"en":"prevent malnutrition","vi":"phòng ngừa suy dinh dưỡng"}],"wordFamily":["malnourished (adj.)","nutrition (n.)","nutritional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; không chỉ có nghĩa là ăn ít, mà còn bao gồm việc hấp thụ dinh dưỡng không cân đối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infirmary', 'en-c1-22', 'infirmary', '/ɪnˈfɝːməri/', 'C1', 'phòng y tế hoặc bệnh xá cung cấp dịch vụ chăm sóc y tế trong một cơ quan, trường học', 'n.', 'infirm (adj.), infirmity (n.)', NULL, 'Thường chỉ phòng y tế bên trong các tổ chức; một số bệnh viện ở Anh cũng dùng tên gọi này.', 'The school nurse treated my ankle in the infirmary.', NULL, 'Y tá trường học đã băng bó mắt cá chân cho tôi ở phòng y tế.', '{"wordId":"infirmary","ukIpa":"/ɪnˈfɜːməri/","usIpa":"/ɪnˈfɝːməri/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A hospital or room providing medical care within an institution.","vi":"phòng y tế hoặc bệnh xá cung cấp dịch vụ chăm sóc y tế trong một cơ quan, trường học"}],"examples":[{"en":"The school nurse treated my ankle in the infirmary.","vi":"Y tá trường học đã băng bó mắt cá chân cho tôi ở phòng y tế.","audioKind":"ex"},{"en":"A well-equipped school infirmary allows minor injuries to be treated promptly without disrupting students'' education.","vi":"Một phòng y tế trường học được trang bị đầy đủ thiết bị cho phép xử lý kịp thời các chấn thương nhẹ mà không làm gián đoạn việc học tập của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"school infirmary","vi":"phòng y tế trường học"},{"en":"infirmary bed","vi":"giường bệnh xá"}],"wordFamily":["infirm (adj.)","infirmity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ phòng y tế bên trong các tổ chức; một số bệnh viện ở Anh cũng dùng tên gọi này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paranoia', 'en-c1-22', 'paranoia', '/ˌpærəˈnɔɪə/', 'C1', 'chứng hoang tưởng; sự đa nghi; cảm giác bị hại', 'n.', 'paranoid (adj.)', NULL, 'Thường là danh từ không đếm được; chỉ trạng thái tâm lý, không chỉ người mắc bệnh.', 'Her growing paranoia made ordinary conversations feel threatening.', NULL, 'Sự hoang tưởng ngày càng lớn của cô ấy khiến những cuộc trò chuyện bình thường cũng trở nên đáng sợ.', '{"wordId":"paranoia","ukIpa":"/ˌpærəˈnɔɪə/","usIpa":"/ˌpærəˈnɔɪə/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"An unfounded belief that others intend to harm you.","vi":"chứng hoang tưởng; sự đa nghi; cảm giác bị hại"}],"examples":[{"en":"Her growing paranoia made ordinary conversations feel threatening.","vi":"Sự hoang tưởng ngày càng lớn của cô ấy khiến những cuộc trò chuyện bình thường cũng trở nên đáng sợ.","audioKind":"ex"},{"en":"Mental health services should offer compassionate support to people experiencing paranoia rather than reinforcing harmful stereotypes.","vi":"Các dịch vụ sức khỏe tâm thần nên cung cấp sự hỗ trợ đầy lòng trắc ẩn cho những người đang trải qua chứng hoang tưởng thay vì củng cố những định kiến tai hại.","audioKind":"ex2"}],"collocations":[{"en":"experience paranoia","vi":"trải qua chứng hoang tưởng"},{"en":"feelings of paranoia","vi":"cảm giác hoang tưởng"},{"en":"paranoia about surveillance","vi":"sự hoang tưởng về việc bị theo dõi"}],"wordFamily":["paranoid (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; chỉ trạng thái tâm lý, không chỉ người mắc bệnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recurrence', 'en-c1-22', 'recurrence', '/rɪˈkɜːrəns/', 'C1', 'sự tái phát; sự lặp lại', 'n.', 'recur (v.), recurrent (adj.), recurring (adj.)', NULL, 'Thường đi với giới từ of; dùng được cho cả việc tái phát bệnh lẫn sự lặp lại của vấn đề.', 'Regular stretching may help prevent a recurrence of back pain.', NULL, 'Việc thường xuyên giãn cơ có thể giúp ngăn ngừa tình trạng đau lưng tái phát.', '{"wordId":"recurrence","ukIpa":"/rɪˈkʌrəns/","usIpa":"/rɪˈkɜːrəns/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"the return of an event, problem, or illness","vi":"sự tái phát; sự lặp lại"}],"examples":[{"en":"Regular stretching may help prevent a recurrence of back pain.","vi":"Việc thường xuyên giãn cơ có thể giúp ngăn ngừa tình trạng đau lưng tái phát.","audioKind":"ex"},{"en":"Improved drainage systems could reduce the risk of a recurrence of severe flooding in urban areas.","vi":"Hệ thống thoát nước được cải thiện có thể làm giảm nguy cơ tái diễn ngập lụt nghiêm trọng ở các khu1 vực đô thị.","audioKind":"ex2"}],"collocations":[{"en":"prevent a recurrence","vi":"ngăn chặn sự tái phát"},{"en":"risk of recurrence","vi":"nguy cơ tái phát"},{"en":"recurrence of symptoms","vi":"triệu chứng tái phát"}],"wordFamily":["recur (v.)","recurrent (adj.)","recurring (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi với giới từ of; dùng được cho cả việc tái phát bệnh lẫn sự lặp lại của vấn đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_physique', 'en-c1-22', 'physique', '/fɪˈziːk/', 'C1', 'thể hình; thể lực; vóc dáng', 'n.', NULL, 'Đồng nghĩa: build', 'Có thể dùng cho mọi giới tính, thường đi kèm với các tính từ miêu tả vóc dáng.', 'Regular swimming helped Lena develop a strong physique.', NULL, 'Việc bơi lội thường xuyên đã giúp Lena phát triển một thể hình lực lưỡng.', '{"wordId":"physique","ukIpa":"/fɪˈziːk/","usIpa":"/fɪˈziːk/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"The size, shape, and strength of a person''s body.","vi":"thể hình; thể lực; vóc dáng"}],"examples":[{"en":"Regular swimming helped Lena develop a strong physique.","vi":"Việc bơi lội thường xuyên đã giúp Lena phát triển một thể hình lực lưỡng.","audioKind":"ex"},{"en":"Although physique can influence athletic performance, consistent training and mental preparation are equally important.","vi":"Mặc dù thể hình có thể ảnh hưởng đến hiệu suất thể thao, nhưng việc tập luyện kiên trì và chuẩn bị tâm lý cũng quan trọng không kém.","audioKind":"ex2"}],"collocations":[{"en":"muscular physique","vi":"thể hình cơ bắp"},{"en":"slim physique","vi":"vóc dáng mảnh mai"},{"en":"powerful physique","vi":"thể hình cường tráng"}],"wordFamily":[],"synonyms":["build"],"antonyms":[],"tipVi":"Có thể dùng cho mọi giới tính, thường đi kèm với các tính từ miêu tả vóc dáng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deafen', 'en-c1-22', 'deafen', '/ˈdefən/', 'C1', 'làm điếc tai; làm ù tai; làm chói tai', 'v.', 'deaf (adj.), deafness (n.), deafening (adj.)', NULL, 'Chỉ dùng với nghĩa làm cho không nghe được âm thanh, không dùng với nghĩa cách âm cho căn phòng.', 'The sudden blast of the horn nearly deafened me.', NULL, 'Tiếng còi xe vang lên bất ngờ suýt làm tôi điếc tai.', '{"wordId":"deafen","ukIpa":"/ˈdefən/","usIpa":"/ˈdefən/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"To make someone unable to hear, temporarily or permanently.","vi":"làm điếc tai; làm ù tai; làm chói tai"}],"examples":[{"en":"The sudden blast of the horn nearly deafened me.","vi":"Tiếng còi xe vang lên bất ngờ suýt làm tôi điếc tai.","audioKind":"ex"},{"en":"Prolonged exposure to loud industrial machinery can deafen workers unless effective hearing protection is consistently provided.","vi":"Việc tiếp xúc kéo dài với tiếng ồn từ máy móc công nghiệp lớn có thể khiến công nhân bị điếc tai nếu không được trang bị các biện pháp bảo vệ thính giác hiệu quả và liên tục.","audioKind":"ex2"}],"collocations":[{"en":"be deafened by","vi":"bị làm điếc tai bởi"},{"en":"almost deafen someone","vi":"gần như làm ai đó điếc tai"},{"en":"deafening noise","vi":"tiếng ồn điếc tai"}],"wordFamily":["deaf (adj.)","deafness (n.)","deafening (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ dùng với nghĩa làm cho không nghe được âm thanh, không dùng với nghĩa cách âm cho căn phòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stimulation', 'en-c1-22', 'stimulation', '/ˌstɪmjuˈleɪʃən/', 'C1', 'sự kích thích; sự kích hoạt; sự thúc đẩy; sự khuyến khích', 'n.', 'stimulate (v.), stimulating (adj.), stimulus (n.)', NULL, 'Thường là danh từ không đếm được; stimulus dùng để chỉ nhân tố kích thích cụ thể.', 'Our dog needs daily walks and plenty of mental stimulation.', NULL, 'Con chó của chúng tôi cần đi dạo hàng ngày và có nhiều hoạt động kích thích trí tuệ.', '{"wordId":"stimulation","ukIpa":"/ˌstɪmjuˈleɪʃən/","usIpa":"/ˌstɪmjuˈleɪʃən/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"something that encourages mental, physical, or biological activity","vi":"sự kích thích; sự kích hoạt"},{"pos":"n.","en":"the process of encouraging growth or increased activity","vi":"sự thúc đẩy; sự khuyến khích"}],"examples":[{"en":"Our dog needs daily walks and plenty of mental stimulation.","vi":"Con chó của chúng tôi cần đi dạo hàng ngày và có nhiều hoạt động kích thích trí tuệ.","audioKind":"ex"},{"en":"Early childhood programmes should provide appropriate sensory stimulation to support healthy brain development and learning.","vi":"Các chương trình giáo dục mầm non nên cung cấp sự kích thích giác quan phù hợp để hỗ trợ sự phát triển não bộ khỏe mạnh và việc học tập.","audioKind":"ex2"}],"collocations":[{"en":"mental stimulation","vi":"kích thích tinh thần"},{"en":"sensory stimulation","vi":"kích thích giác quan"},{"en":"electrical stimulation","vi":"kích thích bằng điện"},{"en":"economic stimulation","vi":"kích thích kinh tế"}],"wordFamily":["stimulate (v.)","stimulating (adj.)","stimulus (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; stimulus dùng để chỉ nhân tố kích thích cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_premature', 'en-c1-22', 'premature', '/ˌpriːməˈtʃʊr/', 'C1', 'quá sớm; non vội; sinh non', 'adj.', 'prematurely (adv.), prematurity (n.)', 'Đồng nghĩa: early, untimely', 'Premature nhấn mạnh sự sớm hơn dự kiến; immature thường chỉ sự chưa trưởng thành.', 'Our celebration was premature; the match wasn''t over yet.', NULL, 'Buổi ăn mừng của chúng tôi hơi quá sớm; trận đấu vẫn chưa kết thúc.', '{"wordId":"premature","ukIpa":"/ˈpremətʃə/","usIpa":"/ˌpriːməˈtʃʊr/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"happening before the expected or appropriate time","vi":"quá sớm; non vội"},{"pos":"adj.","en":"born before the usual length of pregnancy is complete","vi":"sinh non"}],"examples":[{"en":"Our celebration was premature; the match wasn''t over yet.","vi":"Buổi ăn mừng của chúng tôi hơi quá sớm; trận đấu vẫn chưa kết thúc.","audioKind":"ex"},{"en":"It would be premature to conclude that the policy has succeeded without examining its long-term effects.","vi":"Sẽ là quá vội vàng khi kết luận rằng chính sách này đã thành công mà chưa xem xét các tác động lâu dài của nó.","audioKind":"ex2"}],"collocations":[{"en":"a premature baby","vi":"em bé sinh non"},{"en":"premature death","vi":"tử vong sớm"},{"en":"premature ageing","vi":"sự lão hóa sớm"},{"en":"premature to conclude","vi":"quá sớm để kết luận"}],"wordFamily":["prematurely (adv.)","prematurity (n.)"],"synonyms":["early","untimely"],"antonyms":[],"tipVi":"Premature nhấn mạnh sự sớm hơn dự kiến; immature thường chỉ sự chưa trưởng thành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bout', 'en-c1-22', 'bout', '/baʊt/', 'C1', 'cơn bệnh; đợt bùng phát; trận đấu (quyền anh hoặc đấu vật)', 'n.', NULL, 'Đồng nghĩa: spell, episode', 'Cụm từ a bout of dùng để chỉ một cơn bệnh hoặc đợt hoạt động dữ dội kéo dài ngắn; từ này cũng chỉ các trận thi đấu võ thuật.', 'A bout of flu kept me home all week.', NULL, 'Một cơn cảm cúm đã khiến tôi phải ở nhà suốt cả tuần.', '{"wordId":"bout","ukIpa":"/baʊt/","usIpa":"/baʊt/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A short period of illness or intense activity","vi":"cơn bệnh; đợt bùng phát"},{"pos":"n.","en":"A boxing or wrestling contest","vi":"trận đấu (quyền anh hoặc đấu vật)"}],"examples":[{"en":"A bout of flu kept me home all week.","vi":"Một cơn cảm cúm đã khiến tôi phải ở nhà suốt cả tuần.","audioKind":"ex"},{"en":"Regular exercise may help reduce bouts of anxiety and improve overall mental health among university students.","vi":"Tập thể dục đều đặn có thể giúp giảm bớt các đợt lo âu và cải thiện sức khỏe tinh thần tổng thể ở sinh viên đại học.","audioKind":"ex2"}],"collocations":[{"en":"a bout of flu","vi":"một trận cúm"},{"en":"a bout of coughing","vi":"một cơn ho"},{"en":"a boxing bout","vi":"một trận đấu quyền anh"}],"wordFamily":[],"synonyms":["spell","episode"],"antonyms":[],"tipVi":"Cụm từ a bout of dùng để chỉ một cơn bệnh hoặc đợt hoạt động dữ dội kéo dài ngắn; từ này cũng chỉ các trận thi đấu võ thuật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hereditary', 'en-c1-22', 'hereditary', '/həˈredɪteri/', 'C1', 'mang tính di truyền; mang tính thế tập; thế truyền', 'adj.', 'heredity (n.), inherit (v.), inheritance (n.)', 'Đồng nghĩa: inherited · Trái nghĩa: acquired', 'Có thể chỉ sự di truyền qua gen hoặc tước hiệu truyền từ đời này sang đời khác trong gia đình; di truyền không có nghĩa là truyền nhiễm.', 'The doctor asked whether the condition might be hereditary.', NULL, 'Bác sĩ đã hỏi liệu tình trạng bệnh này có khả năng mang tính di truyền hay không.', '{"wordId":"hereditary","ukIpa":"/həˈredɪtəri/","usIpa":"/həˈredɪteri/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"Passed from parents to children through genes.","vi":"mang tính di truyền"},{"pos":"adj.","en":"Passed within a family by established right or tradition.","vi":"mang tính thế tập; thế truyền"}],"examples":[{"en":"The doctor asked whether the condition might be hereditary.","vi":"Bác sĩ đã hỏi liệu tình trạng bệnh này có khả năng mang tính di truyền hay không.","audioKind":"ex"},{"en":"Genetic counselling can help families understand hereditary conditions and make informed decisions about their healthcare.","vi":"Tư vấn di truyền có thể giúp các gia đình hiểu rõ về các bệnh lý di truyền và đưa ra các quyết định sáng suốt về chăm sóc sức khỏe của họ.","audioKind":"ex2"}],"collocations":[{"en":"hereditary disease","vi":"bệnh di truyền"},{"en":"hereditary condition","vi":"tình trạng di truyền"},{"en":"hereditary title","vi":"tước hiệu thế tập"},{"en":"hereditary monarchy","vi":"chế độ quân chủ thế tập"}],"wordFamily":["heredity (n.)","inherit (v.)","inheritance (n.)"],"synonyms":["inherited"],"antonyms":["acquired"],"tipVi":"Có thể chỉ sự di truyền qua gen hoặc tước hiệu truyền từ đời này sang đời khác trong gia đình; di truyền không có nghĩa là truyền nhiễm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pneumonia', 'en-c1-22', 'pneumonia', '/nuːˈmoʊnjə/', 'C1', 'bệnh viêm phổi', 'n.', NULL, NULL, 'Âm đầu p câm; từ này thường là danh từ không đếm được, không dùng a pneumonia.', 'My grandfather stayed in hospital while recovering from pneumonia.', NULL, 'Ông tôi đã ở lại bệnh viện trong suốt thời gian hồi phục sau trận viêm phổi.', '{"wordId":"pneumonia","ukIpa":"/njuːˈməʊniə/","usIpa":"/nuːˈmoʊnjə/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"An infection that inflames the lungs and makes breathing difficult.","vi":"bệnh viêm phổi"}],"examples":[{"en":"My grandfather stayed in hospital while recovering from pneumonia.","vi":"Ông tôi đã ở lại bệnh viện trong suốt thời gian hồi phục sau trận viêm phổi.","audioKind":"ex"},{"en":"Improved access to vaccination and timely treatment can reduce deaths from pneumonia, particularly among young children.","vi":"Việc cải thiện khả năng tiếp cận tiêm chủng và điều trị kịp thời có thể làm giảm tỷ lệ tử vong do viêm phổi, đặc biệt là ở trẻ nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"develop pneumonia","vi":"mắc bệnh viêm phổi"},{"en":"recover from pneumonia","vi":"hồi phục sau bệnh viêm phổi"},{"en":"bacterial pneumonia","vi":"viêm phổi do vi khuẩn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Âm đầu p câm; từ này thường là danh từ không đếm được, không dùng a pneumonia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eradicate', 'en-c1-22', 'eradicate', '/ɪˈrædɪkeɪt/', 'C1', 'tiêu diệt; xóa bỏ hoàn toàn', 'v.', 'eradication (n.)', 'Đồng nghĩa: eliminate, wipe out', 'Nhấn mạnh sự loại bỏ hoàn toàn, sắc thái mạnh hơn reduce, thường dùng cho bệnh tật hoặc nghèo đói.', 'We removed every root to eradicate weeds from the garden.', NULL, 'Chúng tôi đã nhổ tận gốc mọi thứ để trừ sạch cỏ dại trong vườn.', '{"wordId":"eradicate","ukIpa":"/ɪˈrædɪkeɪt/","usIpa":"/ɪˈrædɪkeɪt/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"To completely remove or destroy something harmful.","vi":"tiêu diệt; xóa bỏ hoàn toàn"}],"examples":[{"en":"We removed every root to eradicate weeds from the garden.","vi":"Chúng tôi đã nhổ tận gốc mọi thứ để trừ sạch cỏ dại trong vườn.","audioKind":"ex"},{"en":"International vaccination programmes aim to eradicate infectious diseases by ensuring that vulnerable populations receive adequate protection.","vi":"Các chương trình tiêm chủng quốc tế nhằm mục đích xóa sổ các bệnh truyền nhiễm bằng cách đảm bảo các nhóm dân cư dễ bị tổn thương nhận được sự bảo vệ đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"eradicate disease","vi":"eradicating disease"},{"en":"eradicate poverty","vi":"xóa đói giảm nghèo"},{"en":"eradicate illiteracy","vi":"xóa nạn mù chữ"}],"wordFamily":["eradication (n.)"],"synonyms":["eliminate","wipe out"],"antonyms":[],"tipVi":"Nhấn mạnh sự loại bỏ hoàn toàn, sắc thái mạnh hơn reduce, thường dùng cho bệnh tật hoặc nghèo đói.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seizure', 'en-c1-22', 'seizure', '/ˈsiːʒɚ/', 'C1', 'cơn co giật; cơn động kinh đột ngột; sự tịch thu; sự sung công; sự chiếm đoạt', 'n.', 'seize (v.)', NULL, 'Nghĩa y học thường đi với động từ have; nghĩa tịch thu đi với seizure of.', 'When her brother had a seizure, she called an ambulance.', NULL, 'Khi anh trai cô ấy bị lên cơn co giật, cô đã gọi xe cứu thương.', '{"wordId":"seizure","ukIpa":"/ˈsiːʒə/","usIpa":"/ˈsiːʒɚ/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A sudden episode of abnormal electrical activity in the brain.","vi":"cơn co giật; cơn động kinh đột ngột"},{"pos":"n.","en":"The act of taking something by force or legal authority.","vi":"sự tịch thu; sự sung công; sự chiếm đoạt"}],"examples":[{"en":"When her brother had a seizure, she called an ambulance.","vi":"Khi anh trai cô ấy bị lên cơn co giật, cô đã gọi xe cứu thương.","audioKind":"ex"},{"en":"Public health campaigns can teach people how to respond safely when someone experiences a seizure.","vi":"Các chiến dịch y tế công cộng có thể hướng dẫn mọi người cách ứng phó an toàn khi ai đó bị lên cơn động kinh.","audioKind":"ex2"}],"collocations":[{"en":"have a seizure","vi":"bị lên cơn co giật"},{"en":"an epileptic seizure","vi":"một cơn động kinh"},{"en":"seizure of assets","vi":"tịch thu tài sản"},{"en":"seizure of power","vi":"soán ngôi; chiếm đoạt quyền lực"}],"wordFamily":["seize (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa y học thường đi với động từ have; nghĩa tịch thu đi với seizure of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_22_1', 'en-c1-22', 'Cách dùng “hereditary” (adj.) — mang tính di truyền', 'hereditary disease  ·  hereditary condition  ·  hereditary title', 'Có thể chỉ sự di truyền qua gen hoặc tước hiệu truyền từ đời này sang đời khác trong gia đình; di truyền không có nghĩa là truyền nhiễm.', 'Họ từ (Word Family): heredity (n.), inherit (v.), inheritance (n.) | Đồng nghĩa: inherited · Trái nghĩa: acquired', '[{"hanzi":"The doctor asked whether the condition might be hereditary.","pinyin":"","meaning":"Bác sĩ đã hỏi liệu tình trạng bệnh này có khả năng mang tính di truyền hay không."},{"hanzi":"Genetic counselling can help families understand hereditary conditions and make informed decisions about their healthcare.","pinyin":"","meaning":"Tư vấn di truyền có thể giúp các gia đình hiểu rõ về các bệnh lý di truyền và đưa ra các quyết định sáng suốt về chăm sóc sức khỏe của họ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_22_2', 'en-c1-22', 'Cách dùng “detriment” (n.) — tổn hại; bất lợi', 'to the detriment of  ·  without detriment to  ·  a detriment to health', 'Cụm từ này thường xuất hiện nhất trong cấu trúc to the detriment of, diễn tả việc đánh đổi hoặc làm tổn hại một yếu tố nào đó.', 'Họ từ (Word Family): detrimental (adj.), detrimentally (adv.) | Đồng nghĩa: harm, damage · Trái nghĩa: benefit', '[{"hanzi":"He works late, often to the detriment of his sleep.","pinyin":"","meaning":"Anh ấy làm việc muộn, và thường điều đó gây hại cho giấc ngủ của mình."},{"hanzi":"Prioritising short-term profits to the detriment of environmental protection can create substantial costs for future generations.","pinyin":"","meaning":"Việc ưu tiên lợi nhuận ngắn hạn nhưng lại làm tổn hại đến công tác bảo vệ môi trường có thể tạo ra những chi phí đáng kể cho các thế hệ tương lai."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_22_3', 'en-c1-22', 'Cách dùng “bout” (n.) — cơn bệnh; đợt bùng phát', 'a bout of flu  ·  a bout of coughing  ·  a boxing bout', 'Cụm từ a bout of dùng để chỉ một cơn bệnh hoặc đợt hoạt động dữ dội kéo dài ngắn; từ này cũng chỉ các trận thi đấu võ thuật.', 'Đồng nghĩa: spell, episode', '[{"hanzi":"A bout of flu kept me home all week.","pinyin":"","meaning":"Một cơn cảm cúm đã khiến tôi phải ở nhà suốt cả tuần."},{"hanzi":"Regular exercise may help reduce bouts of anxiety and improve overall mental health among university students.","pinyin":"","meaning":"Tập thể dục đều đặn có thể giúp giảm bớt các đợt lo âu và cải thiện sức khỏe tinh thần tổng thể ở sinh viên đại học."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_22_4', 'en-c1-22', 'Cách dùng “transplant” (v.) — cấy ghép nội tạng; bứng cây', 'transplant seedlings  ·  a kidney transplant  ·  an organ transplant', 'Động từ nhấn trọng âm ở âm tiết cuối, danh từ nhấn trọng âm ở âm tiết đầu; có thể dùng cho cả cơ quan cơ thể lẫn thực vật.', 'Họ từ (Word Family): transplantation (n.)', '[{"hanzi":"We transplant the seedlings once their roots are strong.","pinyin":"","meaning":"Chúng tôi tiến hành bứng cây con khi rễ của chúng đã khỏe mạnh."},{"hanzi":"Advances in medicine have made it possible to transplant organs successfully and improve patients'' quality of life.","pinyin":"","meaning":"Những tiến bộ trong y học đã giúp cấy ghép nội tạng thành công và nâng cao chất lượng cuộc sống cho bệnh nhân."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_22_1', 'en-c1-22', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_1_1', 'ten_c1_22_1', 'fatigue', 'After the long hike, fatigue made my legs shake.', 'After the long hike, fatigue made my legs shake.', '/fəˈtiːɡ/', 'Sau chuyến đi bộ đường dài, sự mệt mỏi khiến chân tôi run rẩy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_1_2', 'ten_c1_22_1', 'transplant', 'We transplant the seedlings once their roots are strong.', 'We transplant the seedlings once their roots are strong.', '/trænsˈplænt/', 'Chúng tôi tiến hành bứng cây con khi rễ của chúng đã khỏe mạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_1_3', 'ten_c1_22_1', 'amputate', 'The vet had to amputate the cat''s badly injured leg.', 'The vet had to amputate the cat''s badly injured leg.', '/ˈæmpjəteɪt/', 'Bác sĩ thú y buộc phải cắt cụt cái chân bị thương nặng của con mèo.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_1_4', 'ten_c1_22_1', 'narcotic', 'The doctor prescribed a narcotic for severe pain after surgery.', 'The doctor prescribed a narcotic for severe pain after surgery.', '/nɑːrˈkɑːtɪk/', 'Bác sĩ đã kê đơn thuốc giảm đau gây ngủ cho cơn đau dữ dội sau phẫu thuật.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_1_5', 'ten_c1_22_1', 'ultrasound', 'The doctor used ultrasound to examine my shoulder.', 'The doctor used ultrasound to examine my shoulder.', '/ˈʌltrəsaʊnd/', 'Bác sĩ đã dùng máy siêu âm để kiểm tra vai của tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_1_6', 'ten_c1_22_1', 'nostril', 'One nostril felt blocked when I woke this morning.', 'One nostril felt blocked when I woke this morning.', '/ˈnɑːstrəl/', 'Một bên lỗ mũi của tôi cảm thấy bị nghẹt khi tôi thức dậy sáng nay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_1_7', 'ten_c1_22_1', 'paralysis', 'The injury caused temporary paralysis in his left leg.', 'The injury caused temporary paralysis in his left leg.', '/pəˈræləsɪs/', 'Chấn thương đã gây ra tình trạng tê liệt tạm thời ở chân trái của anh ấy.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_1_8', 'ten_c1_22_1', 'hepatitis', 'The nurse explained how vaccination can prevent some hepatitis infections.', 'The nurse explained how vaccination can prevent some hepatitis infections.', '/ˌhepəˈtaɪtɪs/', 'Y tá giải thích cách việc tiêm chủng có thể phòng ngừa một số ca nhiễm viêm gan.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_22_1_1', 'en-c1-22', 'ten_c1_22_1', 'listening', 'listening', 'After the long hike, fatigue made my legs shake.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sau chuyến đi bộ đường dài, sự mệt mỏi khiến chân tôi run rẩy.","Chị tôi đã chọn theo học ngành tâm thần học sau khi hoàn thành bằng y khoa.","Buổi ăn mừng của chúng tôi hơi quá sớm; trận đấu vẫn chưa kết thúc.","Một bên lỗ mũi của tôi cảm thấy bị nghẹt khi tôi thức dậy sáng nay."]'::jsonb, 0, 'After the long hike, fatigue made my legs shake. → Sau chuyến đi bộ đường dài, sự mệt mỏi khiến chân tôi run rẩy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_22_1_2', 'en-c1-22', 'ten_c1_22_1', 'listening', 'listening', 'We transplant the seedlings once their roots are strong.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sau chuyến đi bộ đường dài, sự mệt mỏi khiến chân tôi run rẩy.","Bác sĩ đã hỏi liệu tình trạng bệnh này có khả năng mang tính di truyền hay không.","Bác sĩ thú y buộc phải cắt cụt cái chân bị thương nặng của con mèo.","Chúng tôi tiến hành bứng cây con khi rễ của chúng đã khỏe mạnh."]'::jsonb, 3, 'We transplant the seedlings once their roots are strong. → Chúng tôi tiến hành bứng cây con khi rễ của chúng đã khỏe mạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_22_1_3', 'en-c1-22', 'ten_c1_22_1', 'listening', 'listening', 'The vet had to amputate the cat''s badly injured leg.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bác sĩ thú y buộc phải cắt cụt cái chân bị thương nặng của con mèo.","Y tá giải thích cách việc tiêm chủng có thể phòng ngừa một số ca nhiễm viêm gan.","Chú tôi vẫn giữ được sự tỉnh táo và lái xe đưa mọi người về nhà an toàn.","Chấn thương đã gây ra tình trạng tê liệt tạm thời ở chân trái của anh ấy."]'::jsonb, 0, 'The vet had to amputate the cat''s badly injured leg. → Bác sĩ thú y buộc phải cắt cụt cái chân bị thương nặng của con mèo.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_22_2', 'en-c1-22', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_2_1', 'ten_c1_22_2', 'fatigue', 'Persistent fatigue can reduce employees'' concentration and increase the likelihood of accidents in the workplace.', 'Persistent fatigue can reduce employees'' concentration and increase the likelihood of accidents in the workplace.', '/fəˈtiːɡ/', 'Sự mệt mỏi kéo dài có thể làm giảm khả năng tập trung của nhân viên và làm tăng nguy cơ xảy ra tai nạn tại nơi làm việc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_2_2', 'ten_c1_22_2', 'transplant', 'Advances in medicine have made it possible to transplant organs successfully and improve patients'' quality of life.', 'Advances in medicine have made it possible to transplant organs successfully and improve patients'' quality of life.', '/trænsˈplænt/', 'Những tiến bộ trong y học đã giúp cấy ghép nội tạng thành công và nâng cao chất lượng cuộc sống cho bệnh nhân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_2_3', 'ten_c1_22_2', 'amputate', 'Early treatment of severe infections can reduce the need to amputate limbs and improve patients'' quality of life.', 'Early treatment of severe infections can reduce the need to amputate limbs and improve patients'' quality of life.', '/ˈæmpjəteɪt/', 'Việc điều trị sớm các trường hợp nhiễm trùng nặng có thể làm giảm nhu cầu cắt cụt chi và nâng cao chất lượng cuộc sống cho bệnh nhân.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_2_4', 'ten_c1_22_2', 'narcotic', 'Strict controls on narcotic medicines should prevent misuse without limiting access for patients with severe pain.', 'Strict controls on narcotic medicines should prevent misuse without limiting access for patients with severe pain.', '/nɑːrˈkɑːtɪk/', 'Việc kiểm soát chặt chẽ các loại dược phẩm gây ngủ sẽ ngăn chặn tình trạng lạm dụng mà không hạn chế khả năng tiếp cận của những bệnh nhân bị đau đớn dữ dội.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_2_5', 'ten_c1_22_2', 'ultrasound', 'Ultrasound allows doctors to examine internal organs without exposing patients to the radiation used in conventional X-rays.', 'Ultrasound allows doctors to examine internal organs without exposing patients to the radiation used in conventional X-rays.', '/ˈʌltrəsaʊnd/', 'Phương pháp siêu âm giúp bác sĩ kiểm tra các cơ quan nội tạng mà không làm bệnh nhân tiếp xúc với bức xạ như trong chụp X-quang thông thường.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_22_2_6', 'ten_c1_22_2', 'nostril', 'Air entering through each nostril is warmed and filtered before it reaches the lungs.', 'Air entering through each nostril is warmed and filtered before it reaches the lungs.', '/ˈnɑːstrəl/', 'Không khí đi qua mỗi lỗ mũi sẽ được làm ấm và lọc sạch trước khi đến phổi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_22_2_1', 'en-c1-22', 'ten_c1_22_2', 'listening', 'listening', 'Persistent fatigue can reduce employees'' concentration and increase the likelihood of accidents in the workplace.', NULL, 'Trong câu vừa nghe, từ “fatigue” mang nghĩa nào sau đây?', '["sự mệt mỏi; sự kiệt sức","bóp méo; xuyên tạc","chắc là; hầu như chắc chắn; có lẽ là","lời thề; lời tuyên thệ"]'::jsonb, 0, '“fatigue” (/fəˈtiːɡ/): sự mệt mỏi; sự kiệt sức. Câu đầy đủ: Persistent fatigue can reduce employees'' concentration and increase the likelihood of accidents in the workplace.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_22_2_2', 'en-c1-22', 'ten_c1_22_2', 'listening', 'listening', 'Advances in medicine have made it possible to transplant organs successfully and improve patients'' quality of life.', NULL, 'Trong câu vừa nghe, từ “transplant” mang nghĩa nào sau đây?', '["bác sĩ hành nghề; người hành nghề chuyên môn","hào hứng; sôi nổi; kích thích","cấy ghép nội tạng; bứng cây","cho phép tự học; tự chọn tài liệu học tập"]'::jsonb, 2, '“transplant” (/trænsˈplænt/): cấy ghép nội tạng; bứng cây. Câu đầy đủ: Advances in medicine have made it possible to transplant organs successfully and improve patients'' quality of life.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
