INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_22_1', 'en-c1-22', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “fatigue” (/fəˈtiːɡ/) có nghĩa là gì?', '["siêu âm (tần số âm thanh quá cao mà con người không thể nghe thấy)","phòng y tế hoặc bệnh xá cung cấp dịch vụ chăm sóc y tế trong một cơ quan, trường học","cơn bệnh; đợt bùng phát","sự mệt mỏi; sự kiệt sức"]'::jsonb, 3, '“fatigue” (n.): sự mệt mỏi; sự kiệt sức; sự mỏi vật liệu; hiện tượng mỏi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
