INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_1', 'en-c1-22', NULL, 'comprehensive_test', 'listening', 'fatigue', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hàng hóa; vận chuyển hàng hóa","sự mệt mỏi; sự kiệt sức","sự đối xứng; tính đối xứng","đánh giá; định giá chất lượng, tình trạng hoặc hiệu suất"]'::jsonb, 1, 'fatigue (/fəˈtiːɡ/) → sự mệt mỏi; sự kiệt sức; sự mỏi vật liệu; hiện tượng mỏi', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_2', 'en-c1-22', NULL, 'comprehensive_test', 'listening', 'We transplant the seedlings once their roots are strong.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi tiến hành bứng cây con khi rễ của chúng đã khỏe mạnh.","Con chó của chúng tôi cần đi dạo hàng ngày và có nhiều hoạt động kích thích trí tuệ.","Bác sĩ đã kê đơn thuốc giảm đau gây ngủ cho cơn đau dữ dội sau phẫu thuật.","Bác sĩ đã dùng máy siêu âm để kiểm tra vai của tôi."]'::jsonb, 0, 'We transplant the seedlings once their roots are strong. → Chúng tôi tiến hành bứng cây con khi rễ của chúng đã khỏe mạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_3', 'en-c1-22', NULL, 'comprehensive_test', 'listening', 'amputate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trợ cấp; tài trợ","thủ tục hành chính; nghi thức rườm rà","ranh mãnh, quỷ quyệt, lén lút (thường nhằm vụ lợi)","cắt cụt; phẫu thuật cắt bỏ bộ phận cơ thể"]'::jsonb, 3, 'amputate (/ˈæmpjəteɪt/) → cắt cụt; phẫu thuật cắt bỏ bộ phận cơ thể', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_4', 'en-c1-22', NULL, 'comprehensive_test', 'listening', 'The doctor prescribed a narcotic for severe pain after surgery.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bác sĩ đã kê đơn thuốc giảm đau gây ngủ cho cơn đau dữ dội sau phẫu thuật.","Sau chuyến đi bộ đường dài, sự mệt mỏi khiến chân tôi run rẩy.","Chú mèo con được cứu cần có thức ăn đặc biệt để điều trị tình trạng suy dinh dưỡng.","Gia đình đã tham khảo ý kiến luật sư về khả năng xảy ra sai sót y khoa."]'::jsonb, 0, 'The doctor prescribed a narcotic for severe pain after surgery. → Bác sĩ đã kê đơn thuốc giảm đau gây ngủ cho cơn đau dữ dội sau phẫu thuật.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_5', 'en-c1-22', NULL, 'comprehensive_test', 'listening', 'ultrasound', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cần thiết, thiết yếu cho một mục đích cụ thể","lời thề; lời tuyên thệ","vui mừng; hoan hỉ; ăn mừng","siêu âm (tần số âm thanh quá cao mà con người không thể nghe thấy)"]'::jsonb, 3, 'ultrasound (/ˈʌltrəsaʊnd/) → siêu âm (tần số âm thanh quá cao mà con người không thể nghe thấy); siêu âm, phương pháp khám bệnh dùng sóng âm để hiển thị các cơ quan nội bên trong', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_6', 'en-c1-22', NULL, 'comprehensive_test', 'listening', 'One nostril felt blocked when I woke this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông tôi đã ở lại bệnh viện trong suốt thời gian hồi phục sau trận viêm phổi.","Sau chuyến đi bộ đường dài, sự mệt mỏi khiến chân tôi run rẩy.","Một bên lỗ mũi của tôi cảm thấy bị nghẹt khi tôi thức dậy sáng nay.","Con chó của chúng tôi cần đi dạo hàng ngày và có nhiều hoạt động kích thích trí tuệ."]'::jsonb, 2, 'One nostril felt blocked when I woke this morning. → Một bên lỗ mũi của tôi cảm thấy bị nghẹt khi tôi thức dậy sáng nay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_7', 'en-c1-22', NULL, 'comprehensive_test', 'listening', 'paralysis', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sương; giọt sương","sứ mệnh; công việc phù hợp với tâm huyết bản thân","chứng liệt; sự tê liệt (cơ thể)","trôi qua (dùng cho thời gian)"]'::jsonb, 2, 'paralysis (/pəˈræləsɪs/) → chứng liệt; sự tê liệt (cơ thể); sự ngưng trệ, sự tê liệt (hoạt động hoặc tiến trình)', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_8', 'en-c1-22', NULL, 'comprehensive_test', 'listening', 'The nurse explained how vaccination can prevent some hepatitis infections.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Y tá giải thích cách việc tiêm chủng có thể phòng ngừa một số ca nhiễm viêm gan.","Một bên lỗ mũi của tôi cảm thấy bị nghẹt khi tôi thức dậy sáng nay.","Bác sĩ thú y buộc phải cắt cụt cái chân bị thương nặng của con mèo.","Việc bơi lội thường xuyên đã giúp Lena phát triển một thể hình lực lưỡng."]'::jsonb, 0, 'The nurse explained how vaccination can prevent some hepatitis infections. → Y tá giải thích cách việc tiêm chủng có thể phòng ngừa một số ca nhiễm viêm gan.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_9', 'en-c1-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “sound with frequencies too high for humans to hear”?', '["hereditary","premature","ultrasound","malpractice"]'::jsonb, 2, 'ultrasound (/ˈʌltrəsaʊnd/) → siêu âm (tần số âm thanh quá cao mà con người không thể nghe thấy)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_10', 'en-c1-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Either of the two openings at the bottom of the nose.”?', '["detriment","hereditary","nostril","malpractice"]'::jsonb, 2, 'nostril (/ˈnɑːstrəl/) → lỗ mũi', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_11', 'en-c1-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “loss of the ability to move part or all of the body”?', '["paranoia","paralysis","sober","narcotic"]'::jsonb, 1, 'paralysis (/pəˈræləsɪs/) → chứng liệt; sự tê liệt (cơ thể)', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_12', 'en-c1-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Inflammation of the liver, sometimes caused by a virus.”?', '["premature","hepatitis","pneumonia","paranoia"]'::jsonb, 1, 'hepatitis (/ˌhepəˈtaɪtɪs/) → viêm gan', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_13', 'en-c1-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Not drunk or affected by alcohol.”?', '["stimulation","bout","sober","deafen"]'::jsonb, 2, 'sober (/ˈsoʊbər/) → tỉnh táo; không say rượu', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
