INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_18', 'en-c1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Persistent fatigue can reduce employees'' concentration and increase the likelihood of accidents in the workplace.', 'Dựa vào câu trên, từ “fatigue” có nghĩa phù hợp nhất là gì?', '["đi dạo nhàn nhã; lang thang","từ bỏ; giao lại; nhường lại","đồn điền; trang trại lớn","sự mệt mỏi; sự kiệt sức"]'::jsonb, 3, 'fatigue: sự mệt mỏi; sự kiệt sức; sự mỏi vật liệu; hiện tượng mỏi. Dịch cả câu: Sự mệt mỏi kéo dài có thể làm giảm khả năng tập trung của nhân viên và làm tăng nguy cơ xảy ra tai nạn tại nơi làm việc.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_19', 'en-c1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Advances in medicine have made it possible to transplant organs successfully and improve patients'' quality of life.', 'Dựa vào câu trên, từ “transplant” có nghĩa phù hợp nhất là gì?', '["sự nhượng bộ; điều được chấp nhận hoặc từ bỏ để giúp đạt được thỏa thuận","cấy ghép nội tạng; bứng cây","lan tỏa; thấm đượm","sự xây dựng; quá trình hoạch định"]'::jsonb, 1, 'transplant: cấy ghép nội tạng; bứng cây; ca phẫu thuật cấy ghép; bộ phận cấy ghép. Dịch cả câu: Những tiến bộ trong y học đã giúp cấy ghép nội tạng thành công và nâng cao chất lượng cuộc sống cho bệnh nhân.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_20', 'en-c1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Early treatment of severe infections can reduce the need to amputate limbs and improve patients'' quality of life.', 'Dựa vào câu trên, từ “amputate” có nghĩa phù hợp nhất là gì?', '["thực thể độc lập; tổ chức riêng biệt","cắt cụt; phẫu thuật cắt bỏ bộ phận cơ thể","vùng ven sông hồ; khu vực giáp nước","chủ quyền; quyền lực tối cao"]'::jsonb, 1, 'amputate: cắt cụt; phẫu thuật cắt bỏ bộ phận cơ thể. Dịch cả câu: Việc điều trị sớm các trường hợp nhiễm trùng nặng có thể làm giảm nhu cầu cắt cụt chi và nâng cao chất lượng cuộc sống cho bệnh nhân.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_21', 'en-c1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Strict controls on narcotic medicines should prevent misuse without limiting access for patients with severe pain.', 'Dựa vào câu trên, từ “narcotic” có nghĩa phù hợp nhất là gì?', '["thuốc giảm đau gây ngủ; chất gây nghiện","sự bôi trơn; chất bôi trơn","nén lại; ép chặt","mù chữ; không biết đọc biết viết"]'::jsonb, 0, 'narcotic: thuốc giảm đau gây ngủ; chất gây nghiện; có tính gây ngủ; gây tê. Dịch cả câu: Việc kiểm soát chặt chẽ các loại dược phẩm gây ngủ sẽ ngăn chặn tình trạng lạm dụng mà không hạn chế khả năng tiếp cận của những bệnh nhân bị đau đớn dữ dội.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_22', 'en-c1-22', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bệnh viêm phổi”', '["liberal","ultrasound","bypass","pneumonia"]'::jsonb, 3, 'bệnh viêm phổi → pneumonia (/nuːˈmoʊnjə/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_23', 'en-c1-22', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiêu diệt; xóa bỏ hoàn toàn”', '["ceremonial","dodge","taxation","eradicate"]'::jsonb, 3, 'tiêu diệt; xóa bỏ hoàn toàn → eradicate (/ɪˈrædɪkeɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_22_24', 'en-c1-22', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cơn co giật; cơn động kinh đột ngột”', '["seizure","craftsmanship","taxation","innumerable"]'::jsonb, 0, 'cơn co giật; cơn động kinh đột ngột → seizure (/ˈsiːʒɚ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-23', 'en', 'Bài 23: Sức khỏe & Cơ thể (3) - CEFR C1', 'CEFR C1', 'C1 · Sức khỏe', '24 từ vựng Tiếng Anh CEFR C1 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5023, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paralyze', 'en-c1-23', 'paralyze', '/ˈpærəlaɪz/', 'C1', 'làm liệt; làm bại liệt; làm tê liệt; làm ngưng trệ', 'v.', 'paralysis (n.), paralytic (adj.), paralyzed (adj.)', 'Đồng nghĩa: immobilize', 'Mỹ thức viết là paralyze; Anh thức thường viết là paralyse.', 'Some spinal injuries can paralyze both of a person''s legs.', NULL, 'Một số chấn thương tủy sống có thể làm liệt cả hai chân của một người.', '{"wordId":"paralyze","ukIpa":"/ˈpærəlaɪz/","usIpa":"/ˈpærəlaɪz/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"Make someone unable to move all or part of their body.","vi":"làm liệt; làm bại liệt"},{"pos":"v.","en":"Prevent a system from functioning or a person from acting.","vi":"làm tê liệt; làm ngưng trệ"}],"examples":[{"en":"Some spinal injuries can paralyze both of a person''s legs.","vi":"Một số chấn thương tủy sống có thể làm liệt cả hai chân của một người.","audioKind":"ex"},{"en":"Severe flooding can paralyze urban transport networks, preventing workers from reaching essential services and workplaces.","vi":"Lũ lụt nghiêm trọng có thể làm tê liệt hệ thống giao thông đô thị, khiến người lao động không thể đến các cơ sở dịch vụ thiết yếu và nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"paralyze transport","vi":"làm tê liệt giao thông"},{"en":"paralyzed by fear","vi":"sợ đến mức cứng đờ người"},{"en":"partially paralyzed","vi":"bị liệt một phần"}],"wordFamily":["paralysis (n.)","paralytic (adj.)","paralyzed (adj.)"],"synonyms":["immobilize"],"antonyms":[],"tipVi":"Mỹ thức viết là paralyze; Anh thức thường viết là paralyse.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tumour', 'en-c1-23', 'tumour', '/ˈtuːmər/', 'C1', 'khối u', 'n.', NULL, NULL, 'tumour là cách viết theo tiếng Anh-Anh, còn tiếng Anh-Mỹ viết là tumor; khối u không nhất thiết lúc nào cũng là ung thư.', 'The doctor explained that the tumour was not cancerous.', NULL, 'Bác sĩ giải thích rằng khối u đó không phải là ung thư.', '{"wordId":"tumour","ukIpa":"/ˈtjuːmə/","usIpa":"/ˈtuːmər/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"an abnormal mass of cells growing in the body","vi":"khối u"}],"examples":[{"en":"The doctor explained that the tumour was not cancerous.","vi":"Bác sĩ giải thích rằng khối u đó không phải là ung thư.","audioKind":"ex"},{"en":"Early detection of a tumour can improve treatment options, although outcomes depend on its type and location.","vi":"Phát hiện sớm khối u có thể cải thiện các lựa chọn điều trị, mặc dù kết quả phụ thuộc vào loại và vị trí của nó.","audioKind":"ex2"}],"collocations":[{"en":"benign tumour","vi":"khối u lành tính"},{"en":"malignant tumour","vi":"khối u ác tính"},{"en":"remove a tumour","vi":"cắt bỏ khối u"},{"en":"tumour growth","vi":"sự phát triển của khối u"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"tumour là cách viết theo tiếng Anh-Anh, còn tiếng Anh-Mỹ viết là tumor; khối u không nhất thiết lúc nào cũng là ung thư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_artery', 'en-c1-23', 'artery', '/ˈɑːrtəri/', 'C1', 'động mạch; đường giao thông huyết mạch; tuyến đường chính', 'n.', 'arterial (adj.)', NULL, 'Động mạch đưa máu rời khỏi tim; tĩnh mạch là vein.', 'The doctor explained how blood flows through an artery.', NULL, 'Bác sĩ giải thích cách máu lưu thông qua động mạch.', '{"wordId":"artery","ukIpa":"/ˈɑːtəri/","usIpa":"/ˈɑːrtəri/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A blood vessel carrying blood away from the heart.","vi":"động mạch"},{"pos":"n.","en":"A main road or route carrying heavy traffic.","vi":"đường giao thông huyết mạch; tuyến đường chính"}],"examples":[{"en":"The doctor explained how blood flows through an artery.","vi":"Bác sĩ giải thích cách máu lưu thông qua động mạch.","audioKind":"ex"},{"en":"The new railway will become a major transport artery connecting rural communities with regional markets.","vi":"Tuyến đường sắt mới sẽ trở thành một huyết mạch giao thông quan trọng kết nối các cộng đồng nông thôn với các thị trường khu vực.","audioKind":"ex2"}],"collocations":[{"en":"coronary artery","vi":"động mạch vành"},{"en":"blocked artery","vi":"động mạch bị tắc nghẽn"},{"en":"major artery","vi":"tuyến đường huyết mạch"}],"wordFamily":["arterial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động mạch đưa máu rời khỏi tim; tĩnh mạch là vein.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cognitive', 'en-c1-23', 'cognitive', '/ˈkɑːɡnətɪv/', 'C1', 'thuộc về nhận thức', 'adj.', 'cognition (n.), cognitively (adv.)', NULL, 'Thường đi kèm với ability, development, tập trung vào tư duy và trí nhớ.', 'These puzzles help my grandmother keep her cognitive skills sharp.', NULL, 'Những câu đố này giúp bà tôi giữ cho kỹ năng nhận thức của mình luôn nhạy bén.', '{"wordId":"cognitive","ukIpa":"/ˈkɒɡnətɪv/","usIpa":"/ˈkɑːɡnətɪv/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"Related to mental processes such as learning, remembering, and understanding.","vi":"thuộc về nhận thức"}],"examples":[{"en":"These puzzles help my grandmother keep her cognitive skills sharp.","vi":"Những câu đố này giúp bà tôi giữ cho kỹ năng nhận thức của mình luôn nhạy bén.","audioKind":"ex"},{"en":"Regular physical activity may support cognitive development in children and help older adults maintain their memory.","vi":"Hoạt động thể chất đều đặn có thể hỗ trợ sự phát triển nhận thức ở trẻ em và giúp người lớn tuổi duy trì trí nhớ.","audioKind":"ex2"}],"collocations":[{"en":"cognitive development","vi":"sự phát triển nhận thức"},{"en":"cognitive ability","vi":"năng lực nhận thức"},{"en":"cognitive decline","vi":"sự suy giảm nhận thức"},{"en":"cognitive function","vi":"chức năng nhận thức"}],"wordFamily":["cognition (n.)","cognitively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi kèm với ability, development, tập trung vào tư duy và trí nhớ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insomnia', 'en-c1-23', 'insomnia', '/ɪnˈsɑːmniə/', 'C1', 'bệnh mất ngủ; chứng mất ngủ', 'n.', 'insomniac (n.)', 'Đồng nghĩa: sleeplessness', 'insomnia là danh từ không đếm được, thường đi kèm với cụm từ suffer from.', 'His insomnia left him awake long after midnight again.', NULL, 'Chứng mất ngủ lại khiến anh ấy trằn trọc tỉnh táo đến tận khuya.', '{"wordId":"insomnia","ukIpa":"/ɪnˈsɒmniə/","usIpa":"/ɪnˈsɑːmniə/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"a condition involving difficulty falling asleep or staying asleep","vi":"bệnh mất ngủ; chứng mất ngủ"}],"examples":[{"en":"His insomnia left him awake long after midnight again.","vi":"Chứng mất ngủ lại khiến anh ấy trằn trọc tỉnh táo đến tận khuya.","audioKind":"ex"},{"en":"Persistent insomnia can affect concentration at work and may require advice from a healthcare professional.","vi":"Chứng mất ngủ kéo dài có thể ảnh hưởng đến khả năng tập trung trong công việc và có lẽ cần sự tư vấn từ chuyên gia y tế.","audioKind":"ex2"}],"collocations":[{"en":"suffer from insomnia","vi":"bị mất ngủ"},{"en":"chronic insomnia","vi":"mất ngủ kinh niên"},{"en":"treat insomnia","vi":"chữa trị chứng mất ngủ"}],"wordFamily":["insomniac (n.)"],"synonyms":["sleeplessness"],"antonyms":[],"tipVi":"insomnia là danh từ không đếm được, thường đi kèm với cụm từ suffer from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_starvation', 'en-c1-23', 'starvation', '/stɑːrˈveɪʃən/', 'C1', 'nạn đói; tình trạng chết đói', 'n.', 'starve (v.), starving (adj.)', NULL, 'Nặng nề hơn từ hunger, dùng để chỉ tình trạng thiếu ăn trầm trọng hoặc tử vong do thiếu lương thực lâu ngày.', 'Volunteers brought food to animals at risk of starvation.', NULL, 'Các tình nguyện viên đã mang thức ăn đến cho những loài động vật có nguy cơ chết đói.', '{"wordId":"starvation","ukIpa":"/stɑːˈveɪʃən/","usIpa":"/stɑːrˈveɪʃən/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"Extreme suffering or death caused by a prolonged lack of food","vi":"nạn đói; tình trạng chết đói"}],"examples":[{"en":"Volunteers brought food to animals at risk of starvation.","vi":"Các tình nguyện viên đã mang thức ăn đến cho những loài động vật có nguy cơ chết đói.","audioKind":"ex"},{"en":"Prolonged drought can lead to widespread starvation when communities lack reliable food reserves and emergency support.","vi":"Hạn hán kéo dài có thể dẫn đến nạn đói diện rộng khi các cộng đồng thiếu dự trữ lương thực đáng tin cậy và sự hỗ trợ khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"face starvation","vi":"đối mặt với nạn đói"},{"en":"die of starvation","vi":"chết vì đói"},{"en":"mass starvation","vi":"nạn đói quy mô lớn"},{"en":"on the brink of starvation","vi":"bên bờ vực chết đói"}],"wordFamily":["starve (v.)","starving (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nặng nề hơn từ hunger, dùng để chỉ tình trạng thiếu ăn trầm trọng hoặc tử vong do thiếu lương thực lâu ngày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stiffen', 'en-c1-23', 'stiffen', '/ˈstɪfn/', 'C1', 'làm cứng lại; trở nên cứng đờ, kém linh hoạt; làm cho kiên quyết hơn; trở nên mạnh mẽ hoặc quyết tâm hơn', 'v.', 'stiff (adj.), stiffness (n.), stiffly (adv.)', 'Trái nghĩa: soften, relax', 'Có thể dùng cả ngoại động từ và nội động từ: "stiffen muscles" hoặc "muscles stiffen".', 'My legs stiffen after sitting on the bus for hours.', NULL, 'Chân tôi bị cứng đờ sau khi ngồi trên xe buýt suốt nhiều giờ.', '{"wordId":"stiffen","ukIpa":"/ˈstɪfn/","usIpa":"/ˈstɪfn/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"to become or make something rigid or less flexible","vi":"làm cứng lại; trở nên cứng đờ, kém linh hoạt"},{"pos":"v.","en":"to become or make something firmer, stronger, or more determined","vi":"làm cho kiên quyết hơn; trở nên mạnh mẽ hoặc quyết tâm hơn"}],"examples":[{"en":"My legs stiffen after sitting on the bus for hours.","vi":"Chân tôi bị cứng đờ sau khi ngồi trên xe buýt suốt nhiều giờ.","audioKind":"ex"},{"en":"Public opposition may stiffen if the government approves construction without consulting residents about environmental risks.","vi":"Sự phản đối của công chúng có thể trở nên quyết liệt hơn nếu chính phủ phê duyệt việc thi công mà không tham khảo ý kiến cư dân về các rủi ro môi trường.","audioKind":"ex2"}],"collocations":[{"en":"muscles stiffen","vi":"cơ bắp cứng đờ"},{"en":"stiffen with fear","vi":"cứng đờ vì sợ hãi"},{"en":"stiffen resistance","vi":"tăng cường sự kháng cự"}],"wordFamily":["stiff (adj.)","stiffness (n.)","stiffly (adv.)"],"synonyms":[],"antonyms":["soften","relax"],"tipVi":"Có thể dùng cả ngoại động từ và nội động từ: \"stiffen muscles\" hoặc \"muscles stiffen\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paralyse', 'en-c1-23', 'paralyse', '/ˈpærəlaɪz/', 'C1', 'làm tê liệt; làm mất khả năng vận động; làm cho ngưng trệ, không thể hoạt động', 'v.', 'paralysis (n.), paralysed (adj.), paralysing (adj.)', 'Đồng nghĩa: immobilise, incapacitate', 'Cách viết theo Anh-Anh là "paralyse", còn tiếng Anh-Mỹ là "paralyze".', 'The injury paralysed his legs, but his arms remained strong.', NULL, 'Vụ tai nạn khiến đôi chân anh ấy bị liệt, nhưng đôi tay vẫn còn rất khỏe.', '{"wordId":"paralyse","ukIpa":"/ˈpærəlaɪz/","usIpa":"/ˈpærəlaɪz/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"to cause someone to lose the ability to move","vi":"làm tê liệt; làm mất khả năng vận động"},{"pos":"v.","en":"to prevent someone or something from acting or functioning","vi":"làm tê liệt; làm cho ngưng trệ, không thể hoạt động"}],"examples":[{"en":"The injury paralysed his legs, but his arms remained strong.","vi":"Vụ tai nạn khiến đôi chân anh ấy bị liệt, nhưng đôi tay vẫn còn rất khỏe.","audioKind":"ex"},{"en":"Severe flooding can paralyse urban transport systems, preventing essential workers from reaching hospitals and other services.","vi":"Lũ lụt nghiêm trọng có thể làm tê liệt hệ thống giao thông đô thị, khiến những nhân viên thiết yếu không thể đến bệnh viện và các cơ sở dịch vụ khác.","audioKind":"ex2"}],"collocations":[{"en":"be paralysed by fear","vi":"đứng hình vì sợ hãi"},{"en":"paralyse transport","vi":"làm tê liệt giao thông"},{"en":"be partially paralysed","vi":"bị liệt một phần cơ thể"}],"wordFamily":["paralysis (n.)","paralysed (adj.)","paralysing (adj.)"],"synonyms":["immobilise","incapacitate"],"antonyms":[],"tipVi":"Cách viết theo Anh-Anh là \"paralyse\", còn tiếng Anh-Mỹ là \"paralyze\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deterioration', 'en-c1-23', 'deterioration', '/dɪˌtɪriəˈreɪʃən/', 'C1', 'sự suy giảm; sự xuống cấp; sự hư hỏng', 'n.', 'deteriorate (v.)', 'Đồng nghĩa: decline, worsening, degradation · Trái nghĩa: improvement, recovery', 'Thường kết hợp với a deterioration in để chỉ sự suy giảm trong một lĩnh vực cụ thể.', 'Cracks in the ceiling showed the building''s gradual deterioration.', NULL, 'Những vết nứt trên trần nhà cho thấy tình trạng xuống cấp dần dần của tòa nhà.', '{"wordId":"deterioration","ukIpa":"/dɪˌtɪəriəˈreɪʃən/","usIpa":"/dɪˌtɪriəˈreɪʃən/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"The process of becoming worse in condition or quality.","vi":"sự suy giảm; sự xuống cấp; sự hư hỏng"}],"examples":[{"en":"Cracks in the ceiling showed the building''s gradual deterioration.","vi":"Những vết nứt trên trần nhà cho thấy tình trạng xuống cấp dần dần của tòa nhà.","audioKind":"ex"},{"en":"A deterioration in urban air quality can increase respiratory illness and place additional pressure on healthcare services.","vi":"Sự suy giảm chất lượng không khí đô thị có thể làm gia tăng các bệnh về đường hô hấp và tạo thêm áp lực cho các dịch vụ y tế.","audioKind":"ex2"}],"collocations":[{"en":"a deterioration in health","vi":"sự suy giảm sức khỏe"},{"en":"gradual deterioration","vi":"sự xuống cấp từ từ"},{"en":"prevent further deterioration","vi":"ngăn chặn sự suy giảm thêm"}],"wordFamily":["deteriorate (v.)"],"synonyms":["decline","worsening","degradation"],"antonyms":["improvement","recovery"],"tipVi":"Thường kết hợp với a deterioration in để chỉ sự suy giảm trong một lĩnh vực cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_starch', 'en-c1-23', 'starch', '/stɑːrtʃ/', 'C1', 'tinh bột (chất có trong các loại thực phẩm như khoai tây, gạo và bánh mì); hồ (làm cứng quần áo bằng cách cho dung dịch tinh bột vào)', 'n.', 'starchy (adj.), starched (adj.)', NULL, 'Khi mang nghĩa "tinh bột", từ này thường không đếm được; starchy là tính từ chỉ sự giàu tinh bột.', 'Mix the corn starch with water before adding it.', NULL, 'Hãy hòa tan tinh bột ngô với nước trước khi cho nó vào.', '{"wordId":"starch","ukIpa":"/stɑːtʃ/","usIpa":"/stɑːrtʃ/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A carbohydrate found in foods such as potatoes, rice, and bread.","vi":"tinh bột (chất có trong các loại thực phẩm như khoai tây, gạo và bánh mì)"},{"pos":"v.","en":"To treat cloth with starch to make it stiff.","vi":"hồ (làm cứng quần áo bằng cách cho dung dịch tinh bột vào)"}],"examples":[{"en":"Mix the corn starch with water before adding it.","vi":"Hãy hòa tan tinh bột ngô với nước trước khi cho nó vào.","audioKind":"ex"},{"en":"Foods rich in starch provide energy, but their nutritional value also depends on fibre content and processing methods.","vi":"Các loại thực phẩm giàu tinh bột cung cấp năng lượng, nhưng giá trị dinh dưỡng của chúng cũng phụ thuộc vào hàm lượng chất xơ và phương pháp chế biến.","audioKind":"ex2"}],"collocations":[{"en":"rich in starch","vi":"giàu tinh bột"},{"en":"potato starch","vi":"tinh bột khoai tây"},{"en":"corn starch","vi":"tinh bột ngô"},{"en":"starch a shirt","vi":"hồ chiếc áo sơ mi"}],"wordFamily":["starchy (adj.)","starched (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa \"tinh bột\", từ này thường không đếm được; starchy là tính từ chỉ sự giàu tinh bột.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diaphragm', 'en-c1-23', 'diaphragm', '/ˈdaɪəfræm/', 'C1', 'cơ hoành; hoành cách màng; màng rung; màng mỏng; khẩu độ', 'n.', 'diaphragmatic (adj.)', NULL, 'Giải thích nghĩa giải phẫu còn gọi là cơ hoành; chú ý cụm ph phát âm là /f/, chữ g câm.', 'The singing teacher explained how the diaphragm supports breathing.', NULL, 'Giáo viên thanh nhạc giải thích cơ hoành hỗ trợ việc thở như thế nào.', '{"wordId":"diaphragm","ukIpa":"/ˈdaɪəfræm/","usIpa":"/ˈdaɪəfræm/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"the muscle below your lungs that helps you breathe","vi":"cơ hoành; hoành cách màng"},{"pos":"n.","en":"a thin flexible sheet that vibrates in sound equipment","vi":"màng rung; màng mỏng"},{"pos":"n.","en":"a camera part that controls how much light enters","vi":"khẩu độ"}],"examples":[{"en":"The singing teacher explained how the diaphragm supports breathing.","vi":"Giáo viên thanh nhạc giải thích cơ hoành hỗ trợ việc thở như thế nào.","audioKind":"ex"},{"en":"During inhalation, the diaphragm contracts and moves downward, allowing the lungs to expand as air enters.","vi":"Trong quá trình hít vào, cơ hoành co lại và di chuyển xuống dưới, cho phép phổi mở rộng khi không khí đi vào.","audioKind":"ex2"}],"collocations":[{"en":"diaphragm contraction","vi":"sự co cơ hoành"},{"en":"relax the diaphragm","vi":"thư giãn cơ hoành"},{"en":"camera diaphragm","vi":"khẩu độ máy ảnh"}],"wordFamily":["diaphragmatic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Giải thích nghĩa giải phẫu còn gọi là cơ hoành; chú ý cụm ph phát âm là /f/, chữ g câm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_predisposition', 'en-c1-23', 'predisposition', '/ˌpriːdɪspəˈzɪʃən/', 'C1', 'khuynh hướng bẩm sinh mắc bệnh; thể tạng dễ nhiễm bệnh; khuynh hướng tự nhiên; tính hay có sẵn', 'n.', 'predispose (v.), predisposed (adj.)', 'Đồng nghĩa: susceptibility, inclination', 'Thường đi với giới từ to; chỉ khả năng dễ xảy ra chứ không mang tính chắc chắn tuyệt đối.', 'My doctor explained that a predisposition does not guarantee illness.', NULL, 'Bác sĩ của tôi giải thích rằng có khuynh hướng bẩm sinh không có nghĩa là chắc chắn sẽ mắc bệnh.', '{"wordId":"predisposition","ukIpa":"/ˌpriːdɪspəˈzɪʃən/","usIpa":"/ˌpriːdɪspəˈzɪʃən/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A natural tendency to develop a particular illness or condition.","vi":"khuynh hướng bẩm sinh mắc bệnh; thể tạng dễ nhiễm bệnh"},{"pos":"n.","en":"A natural tendency to behave or think in a particular way.","vi":"khuynh hướng tự nhiên; tính hay có sẵn"}],"examples":[{"en":"My doctor explained that a predisposition does not guarantee illness.","vi":"Bác sĩ của tôi giải thích rằng có khuynh hướng bẩm sinh không có nghĩa là chắc chắn sẽ mắc bệnh.","audioKind":"ex"},{"en":"Although genetic predisposition influences the risk of diabetes, regular exercise and a balanced diet can offer protection.","vi":"Mặc dù khuynh hướng di truyền làm gia tăng nguy cơ mắc bệnh tiểu đường, việc tập thể dục đều đặn và chế độ ăn uống cân bằng có thể giúp phòng ngừa.","audioKind":"ex2"}],"collocations":[{"en":"genetic predisposition","vi":"khuynh hướng di truyền"},{"en":"a predisposition to diabetes","vi":"thể tạng dễ mắc bệnh tiểu đường"},{"en":"a predisposition towards anxiety","vi":"khuynh hướng dễ bị lo âu"}],"wordFamily":["predispose (v.)","predisposed (adj.)"],"synonyms":["susceptibility","inclination"],"antonyms":[],"tipVi":"Thường đi với giới từ to; chỉ khả năng dễ xảy ra chứ không mang tính chắc chắn tuyệt đối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resilience', 'en-c1-23', 'resilience', '/rɪˈzɪliəns/', 'C1', 'khả năng phục hồi, tính kiên cường, sức chống chịu; tính đàn hồi', 'n.', 'resilient (adj.), resiliently (adv.)', 'Đồng nghĩa: resiliency · Trái nghĩa: fragility', 'Thường không đếm được, nhấn mạnh năng lực hồi phục và thích ứng sau nghịch cảnh.', 'Her resilience helped her rebuild after the flood.', NULL, 'Khả năng phục hồi đã giúp cô ấy vực dậy cuộc sống sau trận lũ lụt.', '{"wordId":"resilience","ukIpa":"/rɪˈzɪliəns/","usIpa":"/rɪˈzɪliəns/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"The ability to recover or adapt after difficulties","vi":"khả năng phục hồi, tính kiên cường, sức chống chịu"},{"pos":"n.","en":"The ability of a material to regain its original shape","vi":"tính đàn hồi"}],"examples":[{"en":"Her resilience helped her rebuild after the flood.","vi":"Khả năng phục hồi đã giúp cô ấy vực dậy cuộc sống sau trận lũ lụt.","audioKind":"ex"},{"en":"Strong community networks can increase resilience by providing practical and emotional support during economic crises.","vi":"Mạng lưới cộng đồng vững chắc có thể gia tăng sức chống chịu bằng cách cung cấp hỗ trợ thiết thực và tinh thần trong các cuộc khủng hoảng kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"build resilience","vi":"xây dựng sức chống chịu"},{"en":"emotional resilience","vi":"khả năng phục hồi cảm xúc"},{"en":"community resilience","vi":"khả năng chống chịu của cộng đồng"},{"en":"show remarkable resilience","vi":"thể hiện khả năng phục hồi phi thường"}],"wordFamily":["resilient (adj.)","resiliently (adv.)"],"synonyms":["resiliency"],"antonyms":["fragility"],"tipVi":"Thường không đếm được, nhấn mạnh năng lực hồi phục và thích ứng sau nghịch cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mania', 'en-c1-23', 'mania', '/ˈmeɪniə/', 'C1', 'sự cuồng nhiệt; niềm đam mê lớn; cơn hưng cảm; trạng thái rối loạn tâm thần', 'n.', 'manic (adj.)', NULL, 'Trong đời thường có thể chỉ sự cuồng nhiệt; trạng thái hưng cảm trong y học không đồng nghĩa với sự phấn khích thông thường.', 'A mania for collecting toy trains swept our neighbourhood.', NULL, 'Cơn sốt sưu tầm tàu đồ chơi đã càn quét khu phố của chúng tôi.', '{"wordId":"mania","ukIpa":"/ˈmeɪniə/","usIpa":"/ˈmeɪniə/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"an unusually strong enthusiasm for an activity or object","vi":"sự cuồng nhiệt; niềm đam mê lớn"},{"pos":"n.","en":"a mental health state involving extreme energy and elevated mood","vi":"cơn hưng cảm; trạng thái rối loạn tâm thần"}],"examples":[{"en":"A mania for collecting toy trains swept our neighbourhood.","vi":"Cơn sốt sưu tầm tàu đồ chơi đã càn quét khu phố của chúng tôi.","audioKind":"ex"},{"en":"During episodes of mania, individuals may need professional support to manage sleep disruption and impulsive behaviour.","vi":"Trong các giai đoạn hưng cảm, các cá nhân có thể cần sự hỗ trợ chuyên nghiệp để quản lý tình trạng gián đoạn giấc ngủ và hành vi bốc đồng.","audioKind":"ex2"}],"collocations":[{"en":"a mania for","vi":"sự cuồng nhiệt đối với"},{"en":"an episode of mania","vi":"một cơn hưng cảm phát tác"},{"en":"acute mania","vi":"chứng hưng cảm cấp tính"}],"wordFamily":["manic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong đời thường có thể chỉ sự cuồng nhiệt; trạng thái hưng cảm trong y học không đồng nghĩa với sự phấn khích thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cartilage', 'en-c1-23', 'cartilage', '/ˈkɑːrtəlɪdʒ/', 'C1', 'sụn', 'n.', 'cartilaginous (adj.)', NULL, 'Thường là danh từ không đếm được; không phải là xương mà là mô có tính đàn hồi.', 'The doctor explained that cartilage cushions my knee joint.', NULL, 'Bác sĩ giải thích rằng sụn giúp đệm cho khớp gối của tôi.', '{"wordId":"cartilage","ukIpa":"/ˈkɑːtɪlɪdʒ/","usIpa":"/ˈkɑːrtəlɪdʒ/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"Strong, flexible tissue found in joints and other body parts.","vi":"sụn"}],"examples":[{"en":"The doctor explained that cartilage cushions my knee joint.","vi":"Bác sĩ giải thích rằng sụn giúp đệm cho khớp gối của tôi.","audioKind":"ex"},{"en":"Regular moderate exercise can support joint health, but damaged cartilage often takes a long time to heal.","vi":"Tập thể dục điều độ thường xuyên có thể hỗ trợ sức khỏe khớp, nhưng sụn bị tổn thương thường mất rất nhiều thời gian để chữa lành.","audioKind":"ex2"}],"collocations":[{"en":"damaged cartilage","vi":"sụn bị tổn thương"},{"en":"knee cartilage","vi":"sụn khớp gối"},{"en":"cartilage damage","vi":"tổn thương sụn"}],"wordFamily":["cartilaginous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; không phải là xương mà là mô có tính đàn hồi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plague', 'en-c1-23', 'plague', '/pleɪɡ/', 'C1', 'bệnh dịch hạch; dịch bệnh; làm khổ; không ngừng quấy rầy; tai họa; thảm họa lan rộng', 'n.', NULL, NULL, 'Động từ thường dùng cấu trúc be plagued by, diễn tả việc chịu đựng sự quấy rầy kéo dài, lặp đi lặp lại.', 'The museum has an exhibition about plague in medieval towns.', NULL, 'Viện bảo tàng đang trưng bày một triển lãm về dịch bệnh trong các thị trấn thời Trung cổ.', '{"wordId":"plague","ukIpa":"/pleɪɡ/","usIpa":"/pleɪɡ/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A serious infectious disease, especially one caused by plague bacteria.","vi":"bệnh dịch hạch; dịch bệnh"},{"pos":"v.","en":"To cause repeated trouble or suffering.","vi":"làm khổ; không ngừng quấy rầy"},{"pos":"n.","en":"A widespread problem or harmful invasion.","vi":"tai họa; thảm họa lan rộng"}],"examples":[{"en":"The museum has an exhibition about plague in medieval towns.","vi":"Viện bảo tàng đang trưng bày một triển lãm về dịch bệnh trong các thị trấn thời Trung cổ.","audioKind":"ex"},{"en":"Poor drainage continues to plague rapidly growing cities, increasing flood risks and threatening the health of local residents.","vi":"Hệ thống thoát nước kém vẫn tiếp tục gây khó khăn cho các đô thị đang phát triển nhanh chóng, làm gia tăng nguy cơ ngập lụt và đe dọa sức khỏe của người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"an outbreak of plague","vi":"sự bùng phát dịch bệnh"},{"en":"be plagued by problems","vi":"bị quấy rầy bởi các rắc rối"},{"en":"a plague of locusts","vi":"nạn châu chấu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường dùng cấu trúc be plagued by, diễn tả việc chịu đựng sự quấy rầy kéo dài, lặp đi lặp lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nourish', 'en-c1-23', 'nourish', '/ˈnɜːrɪʃ/', 'C1', 'nuôi dưỡng; cung cấp chất dinh dưỡng; ấp ủ', 'v.', 'nourishment (n.), nourishing (adj.), undernourished (adj.)', 'Đồng nghĩa: nurture, sustain', 'Có thể dùng theo nghĩa đen là cung cấp dinh dưỡng, hoặc nghĩa bóng là nuôi dưỡng hy vọng, sự tò mò.', 'These simple meals nourish us after long working days.', NULL, 'Những bữa ăn giản dị này bồi bổ cho chúng tôi sau những ngày làm việc dài mệt mỏi.', '{"wordId":"nourish","ukIpa":"/ˈnʌrɪʃ/","usIpa":"/ˈnɜːrɪʃ/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"to provide what a living thing needs to grow healthily","vi":"nuôi dưỡng; cung cấp chất dinh dưỡng"},{"pos":"v.","en":"to support the growth of a feeling or idea","vi":"nuôi dưỡng; ấp ủ"}],"examples":[{"en":"These simple meals nourish us after long working days.","vi":"Những bữa ăn giản dị này bồi bổ cho chúng tôi sau những ngày làm việc dài mệt mỏi.","audioKind":"ex"},{"en":"Schools can nourish children''s curiosity by encouraging questions and providing opportunities for independent exploration.","vi":"Nhà trường có thể nuôi dưỡng trí tò mò của trẻ em bằng cách khuyến khích đặt câu hỏi và tạo cơ hội cho việc tự khám phá.","audioKind":"ex2"}],"collocations":[{"en":"nourish the body","vi":"nuôi dưỡng cơ thể"},{"en":"nourish the skin","vi":"nuôi dưỡng làn da"},{"en":"nourish curiosity","vi":"nuôi dưỡng trí tò mò"}],"wordFamily":["nourishment (n.)","nourishing (adj.)","undernourished (adj.)"],"synonyms":["nurture","sustain"],"antonyms":[],"tipVi":"Có thể dùng theo nghĩa đen là cung cấp dinh dưỡng, hoặc nghĩa bóng là nuôi dưỡng hy vọng, sự tò mò.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ailment', 'en-c1-23', 'ailment', '/ˈeɪlmənt/', 'C1', 'căn bệnh nhẹ; sự khó chịu', 'n.', 'ail (v.), ailing (adj.)', 'Đồng nghĩa: illness, disorder', 'Là danh từ đếm được, thường chỉ các bệnh nhẹ, hay đi kèm với minor.', 'The pharmacist suggested a remedy for my stomach ailment.', NULL, 'Dược sĩ đã gợi ý một loại thuốc chữa chứng đau dạ dày của tôi.', '{"wordId":"ailment","ukIpa":"/ˈeɪlmənt/","usIpa":"/ˈeɪlmənt/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"An illness, especially one that is not serious.","vi":"căn bệnh nhẹ; sự khó chịu"}],"examples":[{"en":"The pharmacist suggested a remedy for my stomach ailment.","vi":"Dược sĩ đã gợi ý một loại thuốc chữa chứng đau dạ dày của tôi.","audioKind":"ex"},{"en":"Treating minor ailments at local clinics can reduce pressure on hospitals and improve access to healthcare.","vi":"Việc điều trị các bệnh nhẹ tại các phòng khám địa phương có thể làm giảm áp lực cho các bệnh viện và cải thiện khả năng tiếp cận dịch vụ chăm sóc sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"minor ailment","vi":"bệnh nhẹ"},{"en":"common ailments","vi":"các chứng bệnh thông thường"},{"en":"treat an ailment","vi":"chữa trị bệnh"}],"wordFamily":["ail (v.)","ailing (adj.)"],"synonyms":["illness","disorder"],"antonyms":[],"tipVi":"Là danh từ đếm được, thường chỉ các bệnh nhẹ, hay đi kèm với minor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tonic', 'en-c1-23', 'tonic', '/ˈtɑːnɪk/', 'C1', 'thuốc bổ; chất bổ; thứ làm cho sảng khoái; điều làm phấn chấn tinh thần; nước sô-đa có vị đắng (tonic water)', 'n.', NULL, NULL, 'Cách dùng ẩn dụ a tonic for rất phổ biến, chỉ thứ gì đó mang lại cảm giác phấn chấn.', 'The pharmacist suggested a tonic for my persistent tiredness.', NULL, 'Dược sĩ gợi ý tôi dùng một loại thuốc bổ để trị cơn mệt mỏi kéo dài.', '{"wordId":"tonic","ukIpa":"/ˈtɒnɪk/","usIpa":"/ˈtɑːnɪk/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A medicine intended to improve general health or energy","vi":"thuốc bổ; chất bổ"},{"pos":"n.","en":"Something that makes you feel happier or more energetic","vi":"thứ làm cho sảng khoái; điều làm phấn chấn tinh thần"},{"pos":"n.","en":"A fizzy drink with a bitter taste from quinine","vi":"nước sô-đa có vị đắng (tonic water)"}],"examples":[{"en":"The pharmacist suggested a tonic for my persistent tiredness.","vi":"Dược sĩ gợi ý tôi dùng một loại thuốc bổ để trị cơn mệt mỏi kéo dài.","audioKind":"ex"},{"en":"Regular access to green spaces can act as a tonic for residents facing the pressures of urban life.","vi":"Việc thường xuyên tiếp cận với không gian xanh có thể đóng vai trò như một liều thuốc tinh thần cho những cư dân đối mặt với áp lực cuộc sống đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a herbal tonic","vi":"thuốc bổ thảo dược"},{"en":"a tonic for the mind","vi":"liều thuốc tinh thần"},{"en":"tonic water","vi":"nước sô-đa vị đắng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cách dùng ẩn dụ a tonic for rất phổ biến, chỉ thứ gì đó mang lại cảm giác phấn chấn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_limp', 'en-c1-23', 'limp', '/lɪmp/', 'C1', 'đi khập khiễng; đi chân thấp chân cao; dáng đi khập khiễng; mềm oặt; nhũn ra; yếu ớt', 'v.', 'limply (adv.), limpness (n.)', 'Đồng nghĩa: hobble', 'Đóng vai trò động từ chỉ hành động đi khập khiễng; đóng vai trò tính từ chỉ trạng thái yếu ớt hoặc mềm nhũn.', 'I had to limp home after twisting my ankle.', NULL, 'Tôi đành phải đi khập khiễng về nhà sau khi bị trật khớp mắt cá chân.', '{"wordId":"limp","ukIpa":"/lɪmp/","usIpa":"/lɪmp/","cefr":"C1","topic":"health","senses":[{"pos":"v.","en":"To walk unevenly because one leg or foot is hurt","vi":"đi khập khiễng; đi chân thấp chân cao"},{"pos":"n.","en":"An uneven way of walking caused by an affected leg","vi":"dáng đi khập khiễng"},{"pos":"adj.","en":"Not firm or stiff; lacking strength or support","vi":"mềm oặt; nhũn ra; yếu ớt"}],"examples":[{"en":"I had to limp home after twisting my ankle.","vi":"Tôi đành phải đi khập khiễng về nhà sau khi bị trật khớp mắt cá chân.","audioKind":"ex"},{"en":"Athletes who continue to limp after an injury should receive professional assessment before returning to competitive sport.","vi":"Các vận động viên tiếp tục bị khập khiễng sau chấn thương nên nhận được đánh giá chuyên môn trước khi quay lại thi đấu thể thao.","audioKind":"ex2"}],"collocations":[{"en":"walk with a limp","vi":"đi khập khiễng"},{"en":"limp along","vi":"lết đi khó nhọc"},{"en":"go limp","vi":"trở nên mềm oặt"},{"en":"a limp handshake","vi":"cái bắt tay yếu ớt"}],"wordFamily":["limply (adv.)","limpness (n.)"],"synonyms":["hobble"],"antonyms":[],"tipVi":"Đóng vai trò động từ chỉ hành động đi khập khiễng; đóng vai trò tính từ chỉ trạng thái yếu ớt hoặc mềm nhũn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prone', 'en-c1-23', 'prone', '/proʊn/', 'C1', 'có xu hướng; dễ bị mắc phải; nằm sấp', 'adj.', 'proneness (n.)', 'Đồng nghĩa: susceptible, vulnerable', 'prone to đi sau là danh từ hoặc danh động từ, thường dùng để chỉ những tình huống bất lợi.', 'My skin is prone to dryness in cold weather.', NULL, 'Da của tôi rất dễ bị khô vào thời tiết lạnh.', '{"wordId":"prone","ukIpa":"/prəʊn/","usIpa":"/proʊn/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"Likely to experience something undesirable or behave a certain way","vi":"có xu hướng; dễ bị mắc phải"},{"pos":"adj.","en":"Lying flat with the face pointing downwards","vi":"nằm sấp"}],"examples":[{"en":"My skin is prone to dryness in cold weather.","vi":"Da của tôi rất dễ bị khô vào thời tiết lạnh.","audioKind":"ex"},{"en":"Coastal settlements are increasingly prone to flooding as sea levels rise and extreme storms become more frequent.","vi":"Các khu dân cư ven biển ngày càng dễ chịu ảnh hưởng bởi lũ lụt khi mực nước biển dâng cao và các trận bão cực đoan xuất hiện thường xuyên hơn.","audioKind":"ex2"}],"collocations":[{"en":"prone to injury","vi":"dễ bị chấn thương"},{"en":"prone to flooding","vi":"dễ bị ngập lụt"},{"en":"accident-prone","vi":"hay gặp tai nạn"},{"en":"lie prone","vi":"nằm sấp"}],"wordFamily":["proneness (n.)"],"synonyms":["susceptible","vulnerable"],"antonyms":[],"tipVi":"prone to đi sau là danh từ hoặc danh động từ, thường dùng để chỉ những tình huống bất lợi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_susceptible', 'en-c1-23', 'susceptible', '/səˈseptəbl/', 'C1', 'dễ bị ảnh hưởng, dễ bị tổn thương, dễ mắc bệnh', 'adj.', 'susceptibility (n.)', 'Đồng nghĩa: vulnerable, prone · Trái nghĩa: resistant, immune', 'Thường dùng cấu trúc susceptible to, theo sau to là một danh từ.', 'These young plants are particularly susceptible to frost damage.', NULL, 'Những cây non này đặc biệt dễ bị tổn thương bởi sương giá.', '{"wordId":"susceptible","ukIpa":"/səˈseptəbl/","usIpa":"/səˈseptəbl/","cefr":"C1","topic":"health","senses":[{"pos":"adj.","en":"easily affected or harmed by something","vi":"dễ bị ảnh hưởng, dễ bị tổn thương, dễ mắc bệnh"}],"examples":[{"en":"These young plants are particularly susceptible to frost damage.","vi":"Những cây non này đặc biệt dễ bị tổn thương bởi sương giá.","audioKind":"ex"},{"en":"Children may be more susceptible to online advertising because they lack experience in evaluating commercial claims.","vi":"Trẻ em có thể dễ bị ảnh hưởng bởi quảng cáo trực tuyến hơn vì thiếu kinh nghiệm đánh giá các thông tin thương mại.","audioKind":"ex2"}],"collocations":[{"en":"susceptible to infection","vi":"dễ bị nhiễm bệnh"},{"en":"susceptible to influence","vi":"dễ bị tác động"},{"en":"highly susceptible","vi":"rất dễ bị ảnh hưởng"}],"wordFamily":["susceptibility (n.)"],"synonyms":["vulnerable","prone"],"antonyms":["resistant","immune"],"tipVi":"Thường dùng cấu trúc susceptible to, theo sau to là một danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cocaine', 'en-c1-23', 'cocaine', '/koʊˈkeɪn/', 'C1', 'chất cô-cain; thuốc phiện cô-cain', 'n.', NULL, NULL, 'Thường là danh từ không đếm được, dùng để chỉ một loại chất kích thích gây nghiện mạnh.', 'The nurse explained why cocaine can seriously harm the heart.', NULL, 'Nữ điều dưỡng giải thích lý do vì sao chất cô-cain có thể gây tổn hại nghiêm trọng cho tim.', '{"wordId":"cocaine","ukIpa":"/kəʊˈkeɪn/","usIpa":"/koʊˈkeɪn/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A powerful, addictive stimulant drug derived from coca leaves.","vi":"chất cô-cain; thuốc phiện cô-cain"}],"examples":[{"en":"The nurse explained why cocaine can seriously harm the heart.","vi":"Nữ điều dưỡng giải thích lý do vì sao chất cô-cain có thể gây tổn hại nghiêm trọng cho tim.","audioKind":"ex"},{"en":"Public health programmes should combine education about cocaine with accessible treatment for people experiencing addiction.","vi":"Các chương trình y tế cộng đồng nên kết hợp giáo dục về tác hại của cô-cain với các dịch vụ điều trị dễ tiếp cận cho những người đang vật lộn với tình trạng nghiện ngập.","audioKind":"ex2"}],"collocations":[{"en":"cocaine addiction","vi":"chứng nghiện cô-cain"},{"en":"cocaine use","vi":"việc sử dụng cô-cain"},{"en":"cocaine dependence","vi":"sự lệ thuộc vào cô-cain"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được, dùng để chỉ một loại chất kích thích gây nghiện mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_physician', 'en-c1-23', 'physician', '/fɪˈzɪʃən/', 'C1', 'bác sĩ; bác sĩ nội khoa', 'n.', NULL, 'Đồng nghĩa: doctor', 'Trong tiếng Anh-Mỹ thường dùng để chỉ chung bác sĩ; trong tiếng Anh-Anh thường chỉ bác sĩ nội khoa.', 'The physician listened carefully as I described my symptoms.', NULL, 'Bác sĩ chăm chú lắng nghe khi tôi mô tả các triệu chứng của mình.', '{"wordId":"physician","ukIpa":"/fɪˈzɪʃən/","usIpa":"/fɪˈzɪʃən/","cefr":"C1","topic":"health","senses":[{"pos":"n.","en":"A medical doctor, especially one treating illness without surgery.","vi":"bác sĩ; bác sĩ nội khoa"}],"examples":[{"en":"The physician listened carefully as I described my symptoms.","vi":"Bác sĩ chăm chú lắng nghe khi tôi mô tả các triệu chứng của mình.","audioKind":"ex"},{"en":"Access to a qualified physician remains limited in remote areas, contributing to significant inequalities in healthcare.","vi":"Khả năng tiếp cận bác sĩ có trình độ chuyên môn vẫn còn hạn chế ở các vùng sâu vùng xa, góp phần gây ra sự bất bình đẳng đáng kể trong chăm sóc y tế.","audioKind":"ex2"}],"collocations":[{"en":"consult a physician","vi":"tham vấn bác sĩ"},{"en":"qualified physician","vi":"bác sĩ có chuyên môn"},{"en":"primary care physician","vi":"bác sĩ chăm sóc ban đầu"}],"wordFamily":[],"synonyms":["doctor"],"antonyms":[],"tipVi":"Trong tiếng Anh-Mỹ thường dùng để chỉ chung bác sĩ; trong tiếng Anh-Anh thường chỉ bác sĩ nội khoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_23_1', 'en-c1-23', 'Cách dùng “mania” (n.) — sự cuồng nhiệt; niềm đam mê lớn', 'a mania for  ·  an episode of mania  ·  acute mania', 'Trong đời thường có thể chỉ sự cuồng nhiệt; trạng thái hưng cảm trong y học không đồng nghĩa với sự phấn khích thông thường.', 'Họ từ (Word Family): manic (adj.)', '[{"hanzi":"A mania for collecting toy trains swept our neighbourhood.","pinyin":"","meaning":"Cơn sốt sưu tầm tàu đồ chơi đã càn quét khu phố của chúng tôi."},{"hanzi":"During episodes of mania, individuals may need professional support to manage sleep disruption and impulsive behaviour.","pinyin":"","meaning":"Trong các giai đoạn hưng cảm, các cá nhân có thể cần sự hỗ trợ chuyên nghiệp để quản lý tình trạng gián đoạn giấc ngủ và hành vi bốc đồng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_23_2', 'en-c1-23', 'Cách dùng “tumour” (n.) — khối u', 'benign tumour  ·  malignant tumour  ·  remove a tumour', 'tumour là cách viết theo tiếng Anh-Anh, còn tiếng Anh-Mỹ viết là tumor; khối u không nhất thiết lúc nào cũng là ung thư.', NULL, '[{"hanzi":"The doctor explained that the tumour was not cancerous.","pinyin":"","meaning":"Bác sĩ giải thích rằng khối u đó không phải là ung thư."},{"hanzi":"Early detection of a tumour can improve treatment options, although outcomes depend on its type and location.","pinyin":"","meaning":"Phát hiện sớm khối u có thể cải thiện các lựa chọn điều trị, mặc dù kết quả phụ thuộc vào loại và vị trí của nó."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_23_3', 'en-c1-23', 'Cách dùng “starvation” (n.) — nạn đói; tình trạng chết đói', 'face starvation  ·  die of starvation  ·  mass starvation', 'Nặng nề hơn từ hunger, dùng để chỉ tình trạng thiếu ăn trầm trọng hoặc tử vong do thiếu lương thực lâu ngày.', 'Họ từ (Word Family): starve (v.), starving (adj.)', '[{"hanzi":"Volunteers brought food to animals at risk of starvation.","pinyin":"","meaning":"Các tình nguyện viên đã mang thức ăn đến cho những loài động vật có nguy cơ chết đói."},{"hanzi":"Prolonged drought can lead to widespread starvation when communities lack reliable food reserves and emergency support.","pinyin":"","meaning":"Hạn hán kéo dài có thể dẫn đến nạn đói diện rộng khi các cộng đồng thiếu dự trữ lương thực đáng tin cậy và sự hỗ trợ khẩn cấp."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_23_4', 'en-c1-23', 'Cách dùng “limp” (v.) — đi khập khiễng; đi chân thấp chân cao', 'walk with a limp  ·  limp along  ·  go limp', 'Đóng vai trò động từ chỉ hành động đi khập khiễng; đóng vai trò tính từ chỉ trạng thái yếu ớt hoặc mềm nhũn.', 'Họ từ (Word Family): limply (adv.), limpness (n.) | Đồng nghĩa: hobble', '[{"hanzi":"I had to limp home after twisting my ankle.","pinyin":"","meaning":"Tôi đành phải đi khập khiễng về nhà sau khi bị trật khớp mắt cá chân."},{"hanzi":"Athletes who continue to limp after an injury should receive professional assessment before returning to competitive sport.","pinyin":"","meaning":"Các vận động viên tiếp tục bị khập khiễng sau chấn thương nên nhận được đánh giá chuyên môn trước khi quay lại thi đấu thể thao."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_23_1', 'en-c1-23', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_1_1', 'ten_c1_23_1', 'paralyze', 'Some spinal injuries can paralyze both of a person''s legs.', 'Some spinal injuries can paralyze both of a person''s legs.', '/ˈpærəlaɪz/', 'Một số chấn thương tủy sống có thể làm liệt cả hai chân của một người.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_1_2', 'ten_c1_23_1', 'tumour', 'The doctor explained that the tumour was not cancerous.', 'The doctor explained that the tumour was not cancerous.', '/ˈtuːmər/', 'Bác sĩ giải thích rằng khối u đó không phải là ung thư.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_1_3', 'ten_c1_23_1', 'artery', 'The doctor explained how blood flows through an artery.', 'The doctor explained how blood flows through an artery.', '/ˈɑːrtəri/', 'Bác sĩ giải thích cách máu lưu thông qua động mạch.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_1_4', 'ten_c1_23_1', 'cognitive', 'These puzzles help my grandmother keep her cognitive skills sharp.', 'These puzzles help my grandmother keep her cognitive skills sharp.', '/ˈkɑːɡnətɪv/', 'Những câu đố này giúp bà tôi giữ cho kỹ năng nhận thức của mình luôn nhạy bén.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_1_5', 'ten_c1_23_1', 'insomnia', 'His insomnia left him awake long after midnight again.', 'His insomnia left him awake long after midnight again.', '/ɪnˈsɑːmniə/', 'Chứng mất ngủ lại khiến anh ấy trằn trọc tỉnh táo đến tận khuya.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_1_6', 'ten_c1_23_1', 'starvation', 'Volunteers brought food to animals at risk of starvation.', 'Volunteers brought food to animals at risk of starvation.', '/stɑːrˈveɪʃən/', 'Các tình nguyện viên đã mang thức ăn đến cho những loài động vật có nguy cơ chết đói.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_1_7', 'ten_c1_23_1', 'stiffen', 'My legs stiffen after sitting on the bus for hours.', 'My legs stiffen after sitting on the bus for hours.', '/ˈstɪfn/', 'Chân tôi bị cứng đờ sau khi ngồi trên xe buýt suốt nhiều giờ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_1_8', 'ten_c1_23_1', 'paralyse', 'The injury paralysed his legs, but his arms remained strong.', 'The injury paralysed his legs, but his arms remained strong.', '/ˈpærəlaɪz/', 'Vụ tai nạn khiến đôi chân anh ấy bị liệt, nhưng đôi tay vẫn còn rất khỏe.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_23_1_1', 'en-c1-23', 'ten_c1_23_1', 'listening', 'listening', 'Some spinal injuries can paralyze both of a person''s legs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những câu đố này giúp bà tôi giữ cho kỹ năng nhận thức của mình luôn nhạy bén.","Nữ điều dưỡng giải thích lý do vì sao chất cô-cain có thể gây tổn hại nghiêm trọng cho tim.","Một số chấn thương tủy sống có thể làm liệt cả hai chân của một người.","Bác sĩ giải thích cách máu lưu thông qua động mạch."]'::jsonb, 2, 'Some spinal injuries can paralyze both of a person''s legs. → Một số chấn thương tủy sống có thể làm liệt cả hai chân của một người.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_23_1_2', 'en-c1-23', 'ten_c1_23_1', 'listening', 'listening', 'The doctor explained that the tumour was not cancerous.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vụ tai nạn khiến đôi chân anh ấy bị liệt, nhưng đôi tay vẫn còn rất khỏe.","Tôi đành phải đi khập khiễng về nhà sau khi bị trật khớp mắt cá chân.","Cơn sốt sưu tầm tàu đồ chơi đã càn quét khu phố của chúng tôi.","Bác sĩ giải thích rằng khối u đó không phải là ung thư."]'::jsonb, 3, 'The doctor explained that the tumour was not cancerous. → Bác sĩ giải thích rằng khối u đó không phải là ung thư.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_23_1_3', 'en-c1-23', 'ten_c1_23_1', 'listening', 'listening', 'The doctor explained how blood flows through an artery.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Viện bảo tàng đang trưng bày một triển lãm về dịch bệnh trong các thị trấn thời Trung cổ.","Giáo viên thanh nhạc giải thích cơ hoành hỗ trợ việc thở như thế nào.","Bác sĩ giải thích rằng sụn giúp đệm cho khớp gối của tôi.","Bác sĩ giải thích cách máu lưu thông qua động mạch."]'::jsonb, 3, 'The doctor explained how blood flows through an artery. → Bác sĩ giải thích cách máu lưu thông qua động mạch.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_23_2', 'en-c1-23', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_2_1', 'ten_c1_23_2', 'paralyze', 'Severe flooding can paralyze urban transport networks, preventing workers from reaching essential services and workplaces.', 'Severe flooding can paralyze urban transport networks, preventing workers from reaching essential services and workplaces.', '/ˈpærəlaɪz/', 'Lũ lụt nghiêm trọng có thể làm tê liệt hệ thống giao thông đô thị, khiến người lao động không thể đến các cơ sở dịch vụ thiết yếu và nơi làm việc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_2_2', 'ten_c1_23_2', 'tumour', 'Early detection of a tumour can improve treatment options, although outcomes depend on its type and location.', 'Early detection of a tumour can improve treatment options, although outcomes depend on its type and location.', '/ˈtuːmər/', 'Phát hiện sớm khối u có thể cải thiện các lựa chọn điều trị, mặc dù kết quả phụ thuộc vào loại và vị trí của nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_2_3', 'ten_c1_23_2', 'artery', 'The new railway will become a major transport artery connecting rural communities with regional markets.', 'The new railway will become a major transport artery connecting rural communities with regional markets.', '/ˈɑːrtəri/', 'Tuyến đường sắt mới sẽ trở thành một huyết mạch giao thông quan trọng kết nối các cộng đồng nông thôn với các thị trường khu vực.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_2_4', 'ten_c1_23_2', 'cognitive', 'Regular physical activity may support cognitive development in children and help older adults maintain their memory.', 'Regular physical activity may support cognitive development in children and help older adults maintain their memory.', '/ˈkɑːɡnətɪv/', 'Hoạt động thể chất đều đặn có thể hỗ trợ sự phát triển nhận thức ở trẻ em và giúp người lớn tuổi duy trì trí nhớ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_2_5', 'ten_c1_23_2', 'insomnia', 'Persistent insomnia can affect concentration at work and may require advice from a healthcare professional.', 'Persistent insomnia can affect concentration at work and may require advice from a healthcare professional.', '/ɪnˈsɑːmniə/', 'Chứng mất ngủ kéo dài có thể ảnh hưởng đến khả năng tập trung trong công việc và có lẽ cần sự tư vấn từ chuyên gia y tế.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_23_2_6', 'ten_c1_23_2', 'starvation', 'Prolonged drought can lead to widespread starvation when communities lack reliable food reserves and emergency support.', 'Prolonged drought can lead to widespread starvation when communities lack reliable food reserves and emergency support.', '/stɑːrˈveɪʃən/', 'Hạn hán kéo dài có thể dẫn đến nạn đói diện rộng khi các cộng đồng thiếu dự trữ lương thực đáng tin cậy và sự hỗ trợ khẩn cấp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_23_2_1', 'en-c1-23', 'ten_c1_23_2', 'listening', 'listening', 'Severe flooding can paralyze urban transport networks, preventing workers from reaching essential services and workplaces.', NULL, 'Trong câu vừa nghe, từ “paralyze” mang nghĩa nào sau đây?', '["tuân thủ; tôn trọng","tính tiết kiệm; sự chi tiêu tằn tiện","tập hồ sơ năng lực; tập các tác phẩm tiêu biểu","làm liệt; làm bại liệt"]'::jsonb, 3, '“paralyze” (/ˈpærəlaɪz/): làm liệt; làm bại liệt. Câu đầy đủ: Severe flooding can paralyze urban transport networks, preventing workers from reaching essential services and workplaces.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_23_2_2', 'en-c1-23', 'ten_c1_23_2', 'listening', 'listening', 'Early detection of a tumour can improve treatment options, although outcomes depend on its type and location.', NULL, 'Trong câu vừa nghe, từ “tumour” mang nghĩa nào sau đây?', '["khối u","vô hình; phi vật chất; khó đo lường","sự thận trọng; sự cẩn trọng","tận dụng; sử dụng hiệu quả"]'::jsonb, 0, '“tumour” (/ˈtuːmər/): khối u. Câu đầy đủ: Early detection of a tumour can improve treatment options, although outcomes depend on its type and location.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_23_1', 'en-c1-23', 'Some spinal injuries can paralyze both of a person''s legs', 'Một số chấn thương tủy sống có thể làm liệt cả hai chân của một người.', 'paralyze /ˈpærəlaɪz/', '["both","a","injuries","paralyze","legs","person''s","of","spinal","Some","can"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
