INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_23_4', 'en-c1-23', 'These puzzles help my grandmother keep her cognitive skills sharp', 'Những câu đố này giúp bà tôi giữ cho kỹ năng nhận thức của mình luôn nhạy bén.', 'cognitive /ˈkɑːɡnətɪv/', '["help","These","skills","cognitive","grandmother","sharp","her","keep","my","puzzles"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
