INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_23_8', 'en-c1-23', 'The injury paralysed his legs, but his arms remained strong', 'Vụ tai nạn khiến đôi chân anh ấy bị liệt, nhưng đôi tay vẫn còn rất khỏe.', 'paralyse /ˈpærəlaɪz/', '["remained","arms","paralysed","his","strong","injury","but","his","legs","The"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
