INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_23_2', 'en-c1-23', 'en_to_vi', 'The injury paralysed his legs, but his arms remained strong.', 'The injury paralysed his legs, but his arms remained strong.', '/ˈpærəlaɪz/', NULL, 'Vụ tai nạn khiến đôi chân anh ấy bị liệt, nhưng đôi tay vẫn còn rất khỏe.', NULL, '["vụ","tai","nạn","khiến","đôi","chân","anh","ấy"]'::jsonb, 'Từ trọng tâm: paralyse (làm tê liệt; làm mất khả năng vận động)', 'The injury paralysed his legs, but his arms remained strong. → Vụ tai nạn khiến đôi chân anh ấy bị liệt, nhưng đôi tay vẫn còn rất khỏe.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
