INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_1', 'en-c1-23', NULL, 'comprehensive_test', 'listening', 'paralyze', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["là ví dụ điển hình cho; minh họa bằng ví dụ","con báo đen","chủ yếu; cốt lõi; quan trọng nhất","làm liệt; làm bại liệt"]'::jsonb, 3, 'paralyze (/ˈpærəlaɪz/) → làm liệt; làm bại liệt; làm tê liệt; làm ngưng trệ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_2', 'en-c1-23', NULL, 'comprehensive_test', 'listening', 'The doctor explained that the tumour was not cancerous.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chân tôi bị cứng đờ sau khi ngồi trên xe buýt suốt nhiều giờ.","Các tình nguyện viên đã mang thức ăn đến cho những loài động vật có nguy cơ chết đói.","Bác sĩ giải thích rằng khối u đó không phải là ung thư.","Bác sĩ giải thích rằng sụn giúp đệm cho khớp gối của tôi."]'::jsonb, 2, 'The doctor explained that the tumour was not cancerous. → Bác sĩ giải thích rằng khối u đó không phải là ung thư.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_3', 'en-c1-23', NULL, 'comprehensive_test', 'listening', 'artery', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lĩnh vực; phạm vi","động mạch","phân chuồng; phân bón hữu cơ","liên tiếp; nối tiếp nhau không ngừng"]'::jsonb, 1, 'artery (/ˈɑːrtəri/) → động mạch; đường giao thông huyết mạch; tuyến đường chính', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_4', 'en-c1-23', NULL, 'comprehensive_test', 'listening', 'These puzzles help my grandmother keep her cognitive skills sharp.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những câu đố này giúp bà tôi giữ cho kỹ năng nhận thức của mình luôn nhạy bén.","Bác sĩ giải thích cách máu lưu thông qua động mạch.","Những cây non này đặc biệt dễ bị tổn thương bởi sương giá.","Bác sĩ chăm chú lắng nghe khi tôi mô tả các triệu chứng của mình."]'::jsonb, 0, 'These puzzles help my grandmother keep her cognitive skills sharp. → Những câu đố này giúp bà tôi giữ cho kỹ năng nhận thức của mình luôn nhạy bén.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_5', 'en-c1-23', NULL, 'comprehensive_test', 'listening', 'insomnia', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tương ứng; có tỉ lệ thuận","sự thiếu hụt; không đủ","bệnh mất ngủ; chứng mất ngủ","bắt đầu; dấn thân vào"]'::jsonb, 2, 'insomnia (/ɪnˈsɑːmniə/) → bệnh mất ngủ; chứng mất ngủ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_6', 'en-c1-23', NULL, 'comprehensive_test', 'listening', 'Volunteers brought food to animals at risk of starvation.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chứng mất ngủ lại khiến anh ấy trằn trọc tỉnh táo đến tận khuya.","Viện bảo tàng đang trưng bày một triển lãm về dịch bệnh trong các thị trấn thời Trung cổ.","Giáo viên thanh nhạc giải thích cơ hoành hỗ trợ việc thở như thế nào.","Các tình nguyện viên đã mang thức ăn đến cho những loài động vật có nguy cơ chết đói."]'::jsonb, 3, 'Volunteers brought food to animals at risk of starvation. → Các tình nguyện viên đã mang thức ăn đến cho những loài động vật có nguy cơ chết đói.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_7', 'en-c1-23', NULL, 'comprehensive_test', 'listening', 'stiffen', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm cứng lại; trở nên cứng đờ, kém linh hoạt","sự việc; sự cố","quặng (đá chứa kim loại hoặc các chất có giá trị có thể khai thác)","công việc tồn đọng; đơn hàng chờ xử lý"]'::jsonb, 0, 'stiffen (/ˈstɪfn/) → làm cứng lại; trở nên cứng đờ, kém linh hoạt; làm cho kiên quyết hơn; trở nên mạnh mẽ hoặc quyết tâm hơn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_8', 'en-c1-23', NULL, 'comprehensive_test', 'listening', 'The injury paralysed his legs, but his arms remained strong.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đành phải đi khập khiễng về nhà sau khi bị trật khớp mắt cá chân.","Vụ tai nạn khiến đôi chân anh ấy bị liệt, nhưng đôi tay vẫn còn rất khỏe.","Những bữa ăn giản dị này bồi bổ cho chúng tôi sau những ngày làm việc dài mệt mỏi.","Viện bảo tàng đang trưng bày một triển lãm về dịch bệnh trong các thị trấn thời Trung cổ."]'::jsonb, 1, 'The injury paralysed his legs, but his arms remained strong. → Vụ tai nạn khiến đôi chân anh ấy bị liệt, nhưng đôi tay vẫn còn rất khỏe.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_9', 'en-c1-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a condition involving difficulty falling asleep or staying asleep”?', '["plague","nourish","insomnia","limp"]'::jsonb, 2, 'insomnia (/ɪnˈsɑːmniə/) → bệnh mất ngủ; chứng mất ngủ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_10', 'en-c1-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Extreme suffering or death caused by a prolonged lack of food”?', '["paralyse","starvation","limp","stiffen"]'::jsonb, 1, 'starvation (/stɑːrˈveɪʃən/) → nạn đói; tình trạng chết đói', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_11', 'en-c1-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to become or make something rigid or less flexible”?', '["stiffen","limp","tumour","resilience"]'::jsonb, 0, 'stiffen (/ˈstɪfn/) → làm cứng lại; trở nên cứng đờ, kém linh hoạt', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_12', 'en-c1-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to cause someone to lose the ability to move”?', '["cocaine","paralyse","ailment","physician"]'::jsonb, 1, 'paralyse (/ˈpærəlaɪz/) → làm tê liệt; làm mất khả năng vận động', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_13', 'en-c1-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The process of becoming worse in condition or quality.”?', '["cartilage","starch","artery","deterioration"]'::jsonb, 3, 'deterioration (/dɪˌtɪriəˈreɪʃən/) → sự suy giảm; sự xuống cấp; sự hư hỏng', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
