INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_18', 'en-c1-23', NULL, 'comprehensive_test', 'reading', NULL, 'Severe flooding can paralyze urban transport networks, preventing workers from reaching essential services and workplaces.', 'Dựa vào câu trên, từ “paralyze” có nghĩa phù hợp nhất là gì?', '["thương tiếc; đau buồn; tưởng nhớ","làm liệt; làm bại liệt","giành chiến thắng; thắng lợi","một cách kiên quyết; kiên định"]'::jsonb, 1, 'paralyze: làm liệt; làm bại liệt; làm tê liệt; làm ngưng trệ. Dịch cả câu: Lũ lụt nghiêm trọng có thể làm tê liệt hệ thống giao thông đô thị, khiến người lao động không thể đến các cơ sở dịch vụ thiết yếu và nơi làm việc.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_19', 'en-c1-23', NULL, 'comprehensive_test', 'reading', NULL, 'Early detection of a tumour can improve treatment options, although outcomes depend on its type and location.', 'Dựa vào câu trên, từ “tumour” có nghĩa phù hợp nhất là gì?', '["khối u","khởi đầu; phát động; khởi xướng","sự thao túng; sự điều khiển (kiểm soát con người hoặc tình huống một cách không công bằng vì lợi ích cá nhân)","tinh chế; đã qua tinh lọc"]'::jsonb, 0, 'tumour: khối u. Dịch cả câu: Phát hiện sớm khối u có thể cải thiện các lựa chọn điều trị, mặc dù kết quả phụ thuộc vào loại và vị trí của nó.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_20', 'en-c1-23', NULL, 'comprehensive_test', 'reading', NULL, 'The new railway will become a major transport artery connecting rural communities with regional markets.', 'Dựa vào câu trên, từ “artery” có nghĩa phù hợp nhất là gì?', '["động mạch","sự biến động; sự dao động","cuốn; xoáy tròn; làm xoáy","tăng dần; dâng lên; leo lên"]'::jsonb, 0, 'artery: động mạch; đường giao thông huyết mạch; tuyến đường chính. Dịch cả câu: Tuyến đường sắt mới sẽ trở thành một huyết mạch giao thông quan trọng kết nối các cộng đồng nông thôn với các thị trường khu vực.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_21', 'en-c1-23', NULL, 'comprehensive_test', 'reading', NULL, 'Regular physical activity may support cognitive development in children and help older adults maintain their memory.', 'Dựa vào câu trên, từ “cognitive” có nghĩa phù hợp nhất là gì?', '["thượng viện","chung chung; không cụ thể","sửa đổi; điều chỉnh (tài liệu, quy tắc, kế hoạch)","thuộc về nhận thức"]'::jsonb, 3, 'cognitive: thuộc về nhận thức. Dịch cả câu: Hoạt động thể chất đều đặn có thể hỗ trợ sự phát triển nhận thức ở trẻ em và giúp người lớn tuổi duy trì trí nhớ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_22', 'en-c1-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dễ bị ảnh hưởng, dễ bị tổn thương, dễ mắc bệnh”', '["adverbial","susceptible","sophistication","sportsmanship"]'::jsonb, 1, 'dễ bị ảnh hưởng, dễ bị tổn thương, dễ mắc bệnh → susceptible (/səˈseptəbl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_23', 'en-c1-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chất cô-cain; thuốc phiện cô-cain”', '["exasperation","cocaine","exile","ammonia"]'::jsonb, 1, 'chất cô-cain; thuốc phiện cô-cain → cocaine (/koʊˈkeɪn/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_23_24', 'en-c1-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bác sĩ; bác sĩ nội khoa”', '["physician","unprecedented","subsidize","counterpart"]'::jsonb, 0, 'bác sĩ; bác sĩ nội khoa → physician (/fɪˈzɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-24', 'en', 'Bài 24: Nghệ thuật & Sáng tạo (1) - CEFR C1', 'CEFR C1', 'C1 · Nghệ thuật', '26 từ vựng Tiếng Anh CEFR C1 chủ đề nghệ thuật & sáng tạo kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5024, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sonnet', 'en-c1-24', 'sonnet', '/ˈsɑːnɪt/', 'C1', 'thơ mười bốn câu (thể thơ gồm 14 dòng tuân theo một vần điệu và nhịp điệu nhất định)', 'n.', NULL, NULL, 'Sonnet luôn có mười bốn dòng, nhưng cách gieo vần có thể khác nhau.', 'She read a sonnet aloud beside the open window.', NULL, 'Cô ấy đọc to một bài thơ mười bốn câu bên cạnh khung cửa sổ mở.', '{"wordId":"sonnet","ukIpa":"/ˈsɒnɪt/","usIpa":"/ˈsɑːnɪt/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"A fourteen-line poem following a particular rhyme and rhythm pattern.","vi":"thơ mười bốn câu (thể thơ gồm 14 dòng tuân theo một vần điệu và nhịp điệu nhất định)"}],"examples":[{"en":"She read a sonnet aloud beside the open window.","vi":"Cô ấy đọc to một bài thơ mười bốn câu bên cạnh khung cửa sổ mở.","audioKind":"ex"},{"en":"Studying a sonnet helps students understand how formal constraints can encourage creative expression in literature.","vi":"Việc nghiên cứu thơ mười bốn câu giúp học sinh hiểu cách các quy tắc hình thức có thể khuyến khích sự biểu đạt sáng tạo trong văn học.","audioKind":"ex2"}],"collocations":[{"en":"write a sonnet","vi":"viết một bài thơ mười bốn câu"},{"en":"sonnet sequence","vi":"chuỗi thơ mười bốn câu"},{"en":"sonnet form","vi":"thể thơ mười bốn câu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Sonnet luôn có mười bốn dòng, nhưng cách gieo vần có thể khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_craftsmanship', 'en-c1-24', 'craftsmanship', '/ˈkræftsmənʃɪp/', 'C1', 'tay nghề thủ công; kỹ năng chế tác tinh xảo', 'n.', 'craft (n.), craft (v.), craftsman (n.), craftswoman (n.)', 'Đồng nghĩa: artisanship', 'Danh từ không đếm được, nhấn mạnh kỹ năng chế tác hoặc trình độ nghệ thuật của thành phẩm.', 'The handmade chair shows beautiful craftsmanship in every joint.', NULL, 'Chiếc ghế làm thủ công cho thấy tay nghề chế tác tinh xảo trong từng mối nối.', '{"wordId":"craftsmanship","ukIpa":"/ˈkrɑːftsmənʃɪp/","usIpa":"/ˈkræftsmənʃɪp/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"Skill in making things, especially carefully by hand.","vi":"tay nghề thủ công; kỹ năng chế tác tinh xảo"}],"examples":[{"en":"The handmade chair shows beautiful craftsmanship in every joint.","vi":"Chiếc ghế làm thủ công cho thấy tay nghề chế tác tinh xảo trong từng mối nối.","audioKind":"ex"},{"en":"Preserving traditional craftsmanship can support local economies while protecting cultural knowledge passed down through generations.","vi":"Việc bảo tồn nghề thủ công truyền thống có thể hỗ trợ nền kinh tế địa phương đồng thời bảo vệ tri thức văn hóa được truyền qua các thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"fine craftsmanship","vi":"kỹ thuật thủ công tinh xảo"},{"en":"traditional craftsmanship","vi":"nghề thủ công truyền thống"},{"en":"quality craftsmanship","vi":"tay nghề chất lượng cao"}],"wordFamily":["craft (n.)","craft (v.)","craftsman (n.)","craftswoman (n.)"],"synonyms":["artisanship"],"antonyms":[],"tipVi":"Danh từ không đếm được, nhấn mạnh kỹ năng chế tác hoặc trình độ nghệ thuật của thành phẩm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chisel', 'en-c1-24', 'chisel', '/ˈtʃɪzəl/', 'C1', 'cái đục; đục; chạm trổ', 'n.', NULL, NULL, 'Thì quá khứ của động từ trong tiếng Anh-Anh thường viết là chiselled, tiếng Mỹ viết là chiseled.', 'She used a chisel to shape the wooden bowl.', NULL, 'Cô ấy dùng một chiếc đục để tạo hình cho cái bát gỗ.', '{"wordId":"chisel","ukIpa":"/ˈtʃɪzəl/","usIpa":"/ˈtʃɪzəl/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"A tool with a sharp edge for cutting wood or stone.","vi":"cái đục"},{"pos":"v.","en":"To cut or shape wood or stone with a chisel.","vi":"đục; chạm trổ"}],"examples":[{"en":"She used a chisel to shape the wooden bowl.","vi":"Cô ấy dùng một chiếc đục để tạo hình cho cái bát gỗ.","audioKind":"ex"},{"en":"Traditional craftspeople use a chisel to create detailed patterns that preserve local artistic traditions.","vi":"Các nghệ nhân truyền thống sử dụng đục để tạo ra các hoa văn chi tiết nhằm bảo tồn các truyền thống nghệ thuật địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a wood chisel","vi":"dụng cụ đục gỗ"},{"en":"a hammer and chisel","vi":"búa và đục"},{"en":"chisel away","vi":"đục dần"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thì quá khứ của động từ trong tiếng Anh-Anh thường viết là chiselled, tiếng Mỹ viết là chiseled.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_essayist', 'en-c1-24', 'essayist', '/ˈeseɪɪst/', 'C1', 'tác giả viết tản văn; nhà văn chuyên viết tiểu luận', 'n.', 'essay (n.)', NULL, 'Chỉ người sáng tác tản văn hoặc tiểu luận chuyên nghiệp, không dùng để chỉ học sinh viết bài văn.', 'The essayist described her childhood with warmth and humour.', NULL, 'Nhà văn viết tản văn đã miêu tả tuổi thơ của mình bằng sự ấm áp và hài hước.', '{"wordId":"essayist","ukIpa":"/ˈeseɪɪst/","usIpa":"/ˈeseɪɪst/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"a writer of short pieces exploring particular subjects","vi":"tác giả viết tản văn; nhà văn chuyên viết tiểu luận"}],"examples":[{"en":"The essayist described her childhood with warmth and humour.","vi":"Nhà văn viết tản văn đã miêu tả tuổi thơ của mình bằng sự ấm áp và hài hước.","audioKind":"ex"},{"en":"An influential essayist can encourage readers to question social assumptions through personal reflection and careful argument.","vi":"Một nhà tiểu luận có tầm ảnh hưởng có thể khuyến khích độc giả chất vấn các quan niệm xã hội thông qua sự suy ngẫm cá nhân và lập luận sắc sảo.","audioKind":"ex2"}],"collocations":[{"en":"a literary essayist","vi":"một nhà văn viết tản văn văn học"},{"en":"a celebrated essayist","vi":"một nhà tiểu luận nổi tiếng"},{"en":"a novelist and essayist","vi":"một tiểu thuyết gia kiêm nhà tản văn"}],"wordFamily":["essay (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ người sáng tác tản văn hoặc tiểu luận chuyên nghiệp, không dùng để chỉ học sinh viết bài văn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ovation', 'en-c1-24', 'ovation', '/oʊˈveɪʃən/', 'C1', 'tràng pháo tay nhiệt liệt; sự hoan hô', 'n.', NULL, 'Đồng nghĩa: applause, acclaim', 'Là danh từ đếm được; standing ovation chỉ hành động khán giả đứng dậy vỗ tay.', 'The young pianist received an ovation after her performance.', NULL, 'Nữ nghệ sĩ piano trẻ tuổi đã nhận được những tràng pháo tay nhiệt liệt sau màn trình diễn của cô ấy.', '{"wordId":"ovation","ukIpa":"/əʊˈveɪʃən/","usIpa":"/oʊˈveɪʃən/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"enthusiastic applause from an audience to show strong approval","vi":"tràng pháo tay nhiệt liệt; sự hoan hô"}],"examples":[{"en":"The young pianist received an ovation after her performance.","vi":"Nữ nghệ sĩ piano trẻ tuổi đã nhận được những tràng pháo tay nhiệt liệt sau màn trình diễn của cô ấy.","audioKind":"ex"},{"en":"The orchestra received a standing ovation, demonstrating how live performances can create a powerful sense of community.","vi":"Dàn nhạc đã nhận được tràng pháo tay đứng vang dội từ khán giả, minh chứng cho việc các buổi biểu diễn trực tiếp có thể tạo nên sự gắn kết cộng đồng mạnh mẽ ra sao.","audioKind":"ex2"}],"collocations":[{"en":"standing ovation","vi":"đứng dậy vỗ tay tán thưởng"},{"en":"receive an ovation","vi":"nhận được tràng pháo tay nhiệt liệt"},{"en":"thunderous ovation","vi":"tràng pháo tay như sấm dậy"}],"wordFamily":[],"synonyms":["applause","acclaim"],"antonyms":[],"tipVi":"Là danh từ đếm được; standing ovation chỉ hành động khán giả đứng dậy vỗ tay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prelude', 'en-c1-24', 'prelude', '/ˈpreljuːd/', 'C1', 'lời mở đầu; khúc dạo đầu; bước đệm (sự việc xảy ra trước và dẫn dắt cho một sự kiện quan trọng hơn); bản dạo đầu (đoạn nhạc ngắn mở đầu cho một tác phẩm dài hơn)', 'n.', NULL, 'Đồng nghĩa: introduction, opening', 'Thường dùng cấu trúc a prelude to, theo sau to là danh từ hoặc danh động từ.', 'Our short walk was a prelude to a lovely picnic.', NULL, 'Chuyến đi dạo ngắn của chúng tôi là sự mở đầu cho một buổi dã ngoại tuyệt vời.', '{"wordId":"prelude","ukIpa":"/ˈpreljuːd/","usIpa":"/ˈpreljuːd/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"Something that happens before and introduces a more important event.","vi":"lời mở đầu; khúc dạo đầu; bước đệm (sự việc xảy ra trước và dẫn dắt cho một sự kiện quan trọng hơn)"},{"pos":"n.","en":"A short musical piece, often introducing a longer work.","vi":"bản dạo đầu (đoạn nhạc ngắn mở đầu cho một tác phẩm dài hơn)"}],"examples":[{"en":"Our short walk was a prelude to a lovely picnic.","vi":"Chuyến đi dạo ngắn của chúng tôi là sự mở đầu cho một buổi dã ngoại tuyệt vời.","audioKind":"ex"},{"en":"Investment in reliable internet infrastructure is often a prelude to broader economic development in rural regions.","vi":"Việc đầu tư vào cơ sở hạ tầng internet đáng tin cậy thường là bước đệm cho sự phát triển kinh tế rộng lớn hơn ở các vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"a prelude to","vi":"bước đệm cho"},{"en":"a piano prelude","vi":"bản dạo đầu piano"},{"en":"a brief prelude","vi":"lời mở đầu ngắn gọn"}],"wordFamily":[],"synonyms":["introduction","opening"],"antonyms":[],"tipVi":"Thường dùng cấu trúc a prelude to, theo sau to là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mythical', 'en-c1-24', 'mythical', '/ˈmɪθɪkəl/', 'C1', 'thuộc về thần thoại; hư cấu; tưởng tượng; không có thật trong thực tế', 'adj.', 'myth (n.), mythology (n.), mythological (adj.)', 'Đồng nghĩa: legendary, fabled · Trái nghĩa: real', 'mythical chủ yếu mô tả các đối tượng trong thần thoại, hoặc mang nghĩa hoàn toàn không có thực.', 'The museum displayed a painting of a mythical dragon.', NULL, 'Viện bảo tàng trưng bày bức tranh vẽ một con rồng trong thần thoại.', '{"wordId":"mythical","ukIpa":"/ˈmɪθɪkəl/","usIpa":"/ˈmɪθɪkəl/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"existing in or relating to traditional myths","vi":"thuộc về thần thoại"},{"pos":"adj.","en":"imagined or widely believed in, but not actually real","vi":"hư cấu; tưởng tượng; không có thật trong thực tế"}],"examples":[{"en":"The museum displayed a painting of a mythical dragon.","vi":"Viện bảo tàng trưng bày bức tranh vẽ một con rồng trong thần thoại.","audioKind":"ex"},{"en":"Mythical creatures in traditional stories can reveal how earlier societies understood nature and human behaviour.","vi":"Các sinh vật thần thoại trong câu chuyện truyền thống có thể tiết lộ cách các xã hội thời kỳ đầu nhận thức về thiên nhiên và hành vi con người.","audioKind":"ex2"}],"collocations":[{"en":"mythical creature","vi":"sinh vật thần thoại"},{"en":"mythical hero","vi":"anh hùng thần thoại"},{"en":"mythical kingdom","vi":"vương quốc hư cấu"}],"wordFamily":["myth (n.)","mythology (n.)","mythological (adj.)"],"synonyms":["legendary","fabled"],"antonyms":["real"],"tipVi":"mythical chủ yếu mô tả các đối tượng trong thần thoại, hoặc mang nghĩa hoàn toàn không có thực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_witty', 'en-c1-24', 'witty', '/ˈwɪti/', 'C1', 'hóm hỉnh; sắc sảo', 'adj.', 'wit (n.), wittily (adv.), wittiness (n.)', 'Đồng nghĩa: humorous, clever · Trái nghĩa: humourless', 'witty nhấn mạnh sự thông minh, hóm hỉnh trong ngôn từ chứ không chỉ đơn thuần là gây cười.', 'Her witty reply made everyone at the table laugh.', NULL, 'Câu trả lời hóm hỉnh của cô ấy khiến tất cả mọi người ngồi cùng bàn đều bật cười.', '{"wordId":"witty","ukIpa":"/ˈwɪti/","usIpa":"/ˈwɪti/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"Using words in a clever and amusing way","vi":"hóm hỉnh; sắc sảo"}],"examples":[{"en":"Her witty reply made everyone at the table laugh.","vi":"Câu trả lời hóm hỉnh của cô ấy khiến tất cả mọi người ngồi cùng bàn đều bật cười.","audioKind":"ex"},{"en":"A witty presentation can engage students, provided that humour supports rather than distracts from the lesson.","vi":"Một bài thuyết trình hóm hỉnh có thể thu hút học sinh, miễn là sự hài hước hỗ trợ chứ không làm xao lãng bài học.","audioKind":"ex2"}],"collocations":[{"en":"witty remark","vi":"lời châm biếm hóm hỉnh"},{"en":"witty reply","vi":"câu trả lời thông minh"},{"en":"witty dialogue","vi":"đối thoại sắc sảo"}],"wordFamily":["wit (n.)","wittily (adv.)","wittiness (n.)"],"synonyms":["humorous","clever"],"antonyms":["humourless"],"tipVi":"witty nhấn mạnh sự thông minh, hóm hỉnh trong ngôn từ chứ không chỉ đơn thuần là gây cười.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bust', 'en-c1-24', 'bust', '/bʌst/', 'C1', 'tượng bán thân; vòng ngực; bộ ngực phụ nữ', 'n.', NULL, NULL, 'Khi chỉ tác phẩm điêu khắc, đây là danh từ đếm được, thường chỉ bao gồm phần đầu, vai và ngực trên.', 'A marble bust stood beside the museum entrance.', NULL, 'Một bức tượng bán thân bằng đá cẩm thạch đứng cạnh lối vào bảo trưng.', '{"wordId":"bust","ukIpa":"/bʌst/","usIpa":"/bʌst/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"a sculpture showing a person''s head, shoulders, and upper chest","vi":"tượng bán thân"},{"pos":"n.","en":"a woman''s chest, or its measurement","vi":"vòng ngực; bộ ngực phụ nữ"}],"examples":[{"en":"A marble bust stood beside the museum entrance.","vi":"Một bức tượng bán thân bằng đá cẩm thạch đứng cạnh lối vào bảo trưng.","audioKind":"ex"},{"en":"Displaying a bust of a local artist can help museums connect visitors with their community''s cultural history.","vi":"Việc trưng bày tượng bán thân của một nghệ sĩ địa phương có thể giúp bảo tàng kết nối khách tham quan với lịch sử văn hóa của cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"a marble bust","vi":"tượng bán thân bằng đá cẩm thạch"},{"en":"a bronze bust","vi":"tượng bán thân bằng đồng"},{"en":"bust measurement","vi":"số đo vòng ngực"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ tác phẩm điêu khắc, đây là danh từ đếm được, thường chỉ bao gồm phần đầu, vai và ngực trên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repertoire', 'en-c1-24', 'repertoire', '/ˈrepɚtwɑːr/', 'C1', 'toàn bộ các tiết mục, vở diễn mà một nghệ sĩ hoặc nhóm nhạc đã chuẩn bị sẵn sàng để biểu diễn; vốn kỹ năng hoặc phương pháp mà một người có thể sử dụng', 'n.', NULL, NULL, 'Không chỉ chỉ tiết mục biểu diễn, mà còn có thể chỉ toàn bộ kỹ năng mà ai đó nắm giữ.', 'The singer added three new songs to her repertoire.', NULL, 'Nữ ca sĩ đã bổ sung thêm ba bài hát mới vào danh sách biểu diễn của mình.', '{"wordId":"repertoire","ukIpa":"/ˈrepətwɑː/","usIpa":"/ˈrepɚtwɑːr/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"All the pieces a performer or group is prepared to perform.","vi":"toàn bộ các tiết mục, vở diễn mà một nghệ sĩ hoặc nhóm nhạc đã chuẩn bị sẵn sàng để biểu diễn"},{"pos":"n.","en":"The range of skills or methods someone can use.","vi":"vốn kỹ năng hoặc phương pháp mà một người có thể sử dụng"}],"examples":[{"en":"The singer added three new songs to her repertoire.","vi":"Nữ ca sĩ đã bổ sung thêm ba bài hát mới vào danh sách biểu diễn của mình.","audioKind":"ex"},{"en":"Teachers need a broad repertoire of strategies to meet the needs of students with different learning preferences.","vi":"Giáo viên cần trang bị một kho tàng chiến lược phong phú để đáp ứng nhu cầu của học sinh có sở thích học tập khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"expand your repertoire","vi":"mở rộng vốn tiết mục hoặc kỹ năng của bạn"},{"en":"a wide repertoire","vi":"kho tàng tiết mục phong phú"},{"en":"a repertoire of skills","vi":"một tập hợp các kỹ năng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Không chỉ chỉ tiết mục biểu diễn, mà còn có thể chỉ toàn bộ kỹ năng mà ai đó nắm giữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_climactic', 'en-c1-24', 'climactic', '/klaɪˈmæktɪk/', 'C1', 'mang tính cao trào; đạt đến đỉnh điểm', 'adj.', 'climax (n.), climax (v.), anticlimactic (adj.)', 'Trái nghĩa: anticlimactic', 'Tránh nhầm lẫn với từ climatic (thuộc về khí hậu).', 'Everyone held their breath during the film''s climactic scene.', NULL, 'Mọi người đều nín thở trong phân cảnh cao trào của bộ phim.', '{"wordId":"climactic","ukIpa":"/klaɪˈmæktɪk/","usIpa":"/klaɪˈmæktɪk/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"Forming the most exciting or important part of something.","vi":"mang tính cao trào; đạt đến đỉnh điểm"}],"examples":[{"en":"Everyone held their breath during the film''s climactic scene.","vi":"Mọi người đều nín thở trong phân cảnh cao trào của bộ phim.","audioKind":"ex"},{"en":"The novel''s climactic confrontation reveals how social expectations can shape personal decisions and family relationships.","vi":"Cuộc đối đầu đẩy lên cao trào trong tiểu thuyết cho thấy kỳ vọng của xã hội có thể định hình các quyết định cá nhân và mối quan hệ gia đình ra sao.","audioKind":"ex2"}],"collocations":[{"en":"climactic scene","vi":"cảnh cao trào"},{"en":"climactic moment","vi":"khoảnh khắc cao trào"},{"en":"climactic ending","vi":"cái kết cao trào"}],"wordFamily":["climax (n.)","climax (v.)","anticlimactic (adj.)"],"synonyms":[],"antonyms":["anticlimactic"],"tipVi":"Tránh nhầm lẫn với từ climatic (thuộc về khí hậu).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resonance', 'en-c1-24', 'resonance', '/ˈrezənəns/', 'C1', 'sự cộng hưởng (cảm xúc); sức gợi cảm; khả năng lay động; âm vang; độ vang (của âm thanh); sự cộng hưởng (vật lý)', 'n.', 'resonate (v.), resonant (adj.)', NULL, 'Nghĩa về cảm xúc thường đi với cấu trúc have resonance for; nghĩa vật lý chỉ hiện tượng cộng hưởng sóng.', 'That old song has special resonance for my grandparents.', NULL, 'Bản nhạc xưa ấy mang lại sự cộng hưởng cảm xúc đặc biệt cho ông bà tôi.', '{"wordId":"resonance","ukIpa":"/ˈrezənəns/","usIpa":"/ˈrezənəns/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"The power to evoke shared feelings, memories, or understanding.","vi":"sự cộng hưởng (cảm xúc); sức gợi cảm; khả năng lay động"},{"pos":"n.","en":"The deep, full quality of a sound.","vi":"âm vang; độ vang (của âm thanh)"},{"pos":"n.","en":"Stronger vibration caused by matching an object''s natural frequency.","vi":"sự cộng hưởng (vật lý)"}],"examples":[{"en":"That old song has special resonance for my grandparents.","vi":"Bản nhạc xưa ấy mang lại sự cộng hưởng cảm xúc đặc biệt cho ông bà tôi.","audioKind":"ex"},{"en":"Stories about migration often have emotional resonance for readers whose families have experienced similar journeys and challenges.","vi":"Những câu chuyện về di cư thường tạo được tiếng vang cảm xúc cho những độc giả có gia đình từng trải qua hành trình và thử thách tương tự.","audioKind":"ex2"}],"collocations":[{"en":"emotional resonance","vi":"sự cộng hưởng cảm xúc"},{"en":"cultural resonance","vi":"sức cộng hưởng văn hóa"},{"en":"magnetic resonance","vi":"cộng hưởng từ"}],"wordFamily":["resonate (v.)","resonant (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa về cảm xúc thường đi với cấu trúc have resonance for; nghĩa vật lý chỉ hiện tượng cộng hưởng sóng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embroider', 'en-c1-24', 'embroider', '/ɪmˈbrɔɪdər/', 'C1', 'thêu; thêu hoa văn; thêm mắm thêm muối; thêu dệt (câu chuyện)', 'v.', 'embroidery (n.), embroiderer (n.)', NULL, 'embroider là thêu hoa văn trên vải, không dùng cho việc đan len bằng kim (knit).', 'My aunt embroidered tiny flowers around the pillow''s edge.', NULL, 'Dì tôi đã thêu những bông hoa nhỏ xung quanh viền chiếc gối.', '{"wordId":"embroider","ukIpa":"/ɪmˈbrɔɪdə/","usIpa":"/ɪmˈbrɔɪdər/","cefr":"C1","topic":"arts","senses":[{"pos":"v.","en":"To decorate cloth by sewing patterns with thread.","vi":"thêu; thêu hoa văn"},{"pos":"v.","en":"To make a story more interesting by adding invented details.","vi":"thêm mắm thêm muối; thêu dệt (câu chuyện)"}],"examples":[{"en":"My aunt embroidered tiny flowers around the pillow''s edge.","vi":"Dì tôi đã thêu những bông hoa nhỏ xung quanh viền chiếc gối.","audioKind":"ex"},{"en":"Local artisans embroider traditional patterns on clothing, preserving cultural knowledge while creating products that appeal to visitors.","vi":"Các nghệ nhân địa phương thêu các họa tiết truyền thống lên trang phục, vừa bảo tồn tri thức văn hóa vừa tạo ra các sản phẩm thu hút du khách.","audioKind":"ex2"}],"collocations":[{"en":"embroider a pattern","vi":"thêu hoa văn"},{"en":"embroider flowers on cloth","vi":"thêu hoa lên vải"},{"en":"embroider with silk thread","vi":"thêu bằng chỉ lụa"},{"en":"embroider a story","vi":"thêu dệt câu chuyện; phóng đại câu chuyện"}],"wordFamily":["embroidery (n.)","embroiderer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"embroider là thêu hoa văn trên vải, không dùng cho việc đan len bằng kim (knit).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_papercut', 'en-c1-24', 'papercut', '/ˈpeɪpərkʌt/', 'C1', 'tác phẩm cắt giấy; nghệ thuật cắt giấy', 'n.', 'papercutting (n.)', NULL, 'Nghệ thuật cắt giấy thường dùng từ papercutting; trong khi vết thương do giấy cắt thường viết là paper cut.', 'She framed a delicate papercut of birds and flowers.', NULL, 'Cô ấy đã lồng khung một bức tranh cắt giấy hình chim hoa tinh xảo.', '{"wordId":"papercut","ukIpa":"/ˈpeɪpəkʌt/","usIpa":"/ˈpeɪpərkʌt/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"A decorative picture made by cutting shapes from paper","vi":"tác phẩm cắt giấy; nghệ thuật cắt giấy"}],"examples":[{"en":"She framed a delicate papercut of birds and flowers.","vi":"Cô ấy đã lồng khung một bức tranh cắt giấy hình chim hoa tinh xảo.","audioKind":"ex"},{"en":"Displaying traditional papercuts in community museums can help younger generations appreciate local craft skills and cultural heritage.","vi":"Việc trưng bày các tác phẩm cắt giấy truyền thống trong bảo tàng cộng đồng có thể giúp thế hệ trẻ trân trọng các kỹ năng thủ công và di sản văn hóa địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a traditional papercut","vi":"một tác phẩm cắt giấy truyền thống"},{"en":"an intricate papercut","vi":"một tác phẩm cắt giấy tinh xảo"},{"en":"papercut art","vi":"nghệ thuật cắt giấy"}],"wordFamily":["papercutting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghệ thuật cắt giấy thường dùng từ papercutting; trong khi vết thương do giấy cắt thường viết là paper cut.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inscribe', 'en-c1-24', 'inscribe', '/ɪnˈskraɪb/', 'C1', 'khắc chữ; đề chữ', 'v.', 'inscription (n.)', 'Đồng nghĩa: engrave, carve', 'Thường dùng cấu trúc inscribe A on B hoặc inscribe B with A, không dùng như việc ghi chép thông thường.', 'The jeweller inscribed our initials inside the silver ring.', NULL, 'Người thợ kim hoàn đã khắc chữ cái đầu tên chúng tôi vào mặt trong của chiếc nhẫn bạc.', '{"wordId":"inscribe","ukIpa":"/ɪnˈskraɪb/","usIpa":"/ɪnˈskraɪb/","cefr":"C1","topic":"arts","senses":[{"pos":"v.","en":"write or carve words on an object, often permanently","vi":"khắc chữ; đề chữ"}],"examples":[{"en":"The jeweller inscribed our initials inside the silver ring.","vi":"Người thợ kim hoàn đã khắc chữ cái đầu tên chúng tôi vào mặt trong của chiếc nhẫn bạc.","audioKind":"ex"},{"en":"Communities often inscribe memorial stones with personal stories to preserve local history for future generations.","vi":"Các cộng đồng thường khắc những câu chuyện cá nhân lên các tấm bia tưởng niệm để lưu giữ lịch sử địa phương cho các thế hệ mai sau.","audioKind":"ex2"}],"collocations":[{"en":"inscribe a name on","vi":"khắc tên lên"},{"en":"be inscribed with","vi":"được khắc chữ; được đề"},{"en":"inscribe a dedication","vi":"khắc lời đề tặng"}],"wordFamily":["inscription (n.)"],"synonyms":["engrave","carve"],"antonyms":[],"tipVi":"Thường dùng cấu trúc inscribe A on B hoặc inscribe B with A, không dùng như việc ghi chép thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_angular', 'en-c1-24', 'angular', '/ˈæŋɡjələr/', 'C1', 'có góc cạnh; góc vát rõ ràng; gầy gò; xương xẩu', 'adj.', 'angle (n.), angularity (n.)', 'Trái nghĩa: rounded', 'Dùng để miêu tả hình dáng có nhiều góc cạnh hoặc dùng để chỉ vóc dáng gầy gò của con người.', 'The angular table looked striking beside our curved sofa.', NULL, 'Chiếc bàn có các góc cạnh rõ ràng trông rất nổi bật khi đặt cạnh bộ sofa uốn lượn của chúng tôi.', '{"wordId":"angular","ukIpa":"/ˈæŋɡjələ/","usIpa":"/ˈæŋɡjələr/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"Having sharp corners or clearly defined angles.","vi":"có góc cạnh; góc vát rõ ràng"},{"pos":"adj.","en":"Thin, with bones and joints that appear prominent.","vi":"gầy gò; xương xẩu"}],"examples":[{"en":"The angular table looked striking beside our curved sofa.","vi":"Chiếc bàn có các góc cạnh rõ ràng trông rất nổi bật khi đặt cạnh bộ sofa uốn lượn của chúng tôi.","audioKind":"ex"},{"en":"The museum''s angular design contrasts sharply with the rounded forms commonly found in the surrounding landscape.","vi":"Thiết kế góc cạnh của bảo tàng tạo sự tương phản mạnh mẽ với các hình khối tròn trịa thường thấy ở cảnh quan xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"angular shape","vi":"hình dáng góc cạnh"},{"en":"angular features","vi":"đường nét góc cạnh"},{"en":"angular design","vi":"thiết kế góc cạnh"}],"wordFamily":["angle (n.)","angularity (n.)"],"synonyms":[],"antonyms":["rounded"],"tipVi":"Dùng để miêu tả hình dáng có nhiều góc cạnh hoặc dùng để chỉ vóc dáng gầy gò của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_potion', 'en-c1-24', 'potion', '/ˈpoʊʃən/', 'C1', 'thần dược; nước phép, thuốc pha', 'n.', NULL, 'Đồng nghĩa: elixir', 'Thường gặp trong các câu chuyện kỳ ảo; thuốc thông thường dùng dose.', 'In the story, a potion turns the prince invisible.', NULL, 'Trong câu chuyện, một loại nước phép đã biến hoàng tử thành kẻ tàng hình.', '{"wordId":"potion","ukIpa":"/ˈpəʊʃən/","usIpa":"/ˈpoʊʃən/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"A drink believed to have magical or medicinal effects.","vi":"thần dược; nước phép, thuốc pha"}],"examples":[{"en":"In the story, a potion turns the prince invisible.","vi":"Trong câu chuyện, một loại nước phép đã biến hoàng tử thành kẻ tàng hình.","audioKind":"ex"},{"en":"The magical potion remains a familiar device in children''s literature, allowing authors to explore transformation and identity.","vi":"Thần dược vẫn là một mô-típ quen thuộc trong văn học thiếu nhi, cho phép các tác giả khai thác chủ đề biến hóa và bản sắc.","audioKind":"ex2"}],"collocations":[{"en":"a magic potion","vi":"nước phép thần kỳ"},{"en":"a healing potion","vi":"thuốc tiên chữa bệnh"},{"en":"brew a potion","vi":"nấu nước phép"}],"wordFamily":[],"synonyms":["elixir"],"antonyms":[],"tipVi":"Thường gặp trong các câu chuyện kỳ ảo; thuốc thông thường dùng dose.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_theatrical', 'en-c1-24', 'theatrical', '/θiˈætrɪkəl/', 'C1', 'thuộc về sân khấu; kịch nghệ; cường điệu; làm quá để thu hút sự chú ý', 'adj.', 'theatre (n.), theatrically (adv.)', 'Đồng nghĩa: dramatic', 'Từ này vừa chỉ các vấn đề liên quan đến sân khấu, vừa có thể dùng để miêu tả lời nói hoặc hành động mang tính cường điệu, làm quá.', 'We watched a theatrical performance in the park yesterday.', NULL, 'Hôm qua chúng tôi đã xem một buổi biểu diễn kịch ở công viên.', '{"wordId":"theatrical","ukIpa":"/θiˈætrɪkəl/","usIpa":"/θiˈætrɪkəl/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"relating to theatre or the performance of plays","vi":"thuộc về sân khấu; kịch nghệ"},{"pos":"adj.","en":"exaggerated to attract attention or create a strong effect","vi":"cường điệu; làm quá để thu hút sự chú ý"}],"examples":[{"en":"We watched a theatrical performance in the park yesterday.","vi":"Hôm qua chúng tôi đã xem một buổi biểu diễn kịch ở công viên.","audioKind":"ex"},{"en":"Public funding for theatrical productions can make live performances accessible to communities with limited cultural resources.","vi":"Việc tài trợ công cho các sản phẩm sân khấu có thể giúp các buổi biểu diễn trực tiếp tiếp cận được với các cộng đồng có nguồn lực văn hóa hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"a theatrical production","vi":"một tác phẩm kịch"},{"en":"a theatrical performance","vi":"một buổi biểu diễn sân khấu"},{"en":"a theatrical gesture","vi":"một cử chỉ làm quá"}],"wordFamily":["theatre (n.)","theatrically (adv.)"],"synonyms":["dramatic"],"antonyms":[],"tipVi":"Từ này vừa chỉ các vấn đề liên quan đến sân khấu, vừa có thể dùng để miêu tả lời nói hoặc hành động mang tính cường điệu, làm quá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scarlet', 'en-c1-24', 'scarlet', '/ˈskɑːr.lət/', 'C1', 'màu đỏ tươi; màu đỏ chói; màu đỏ rực rỡ', 'adj.', NULL, NULL, 'Cụm từ turn scarlet thường diễn tả việc khuôn mặt đỏ bừng lên do xấu hổ hoặc tức giận.', 'She wore a scarlet scarf against her grey coat.', NULL, 'Cô ấy quàng chiếc khăn màu đỏ tươi nổi bật trên chiếc áo khoác màu xám.', '{"wordId":"scarlet","ukIpa":"/ˈskɑː.lət/","usIpa":"/ˈskɑːr.lət/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"Having a bright red colour","vi":"màu đỏ tươi; màu đỏ chói"},{"pos":"n.","en":"A bright red colour","vi":"màu đỏ rực rỡ"}],"examples":[{"en":"She wore a scarlet scarf against her grey coat.","vi":"Cô ấy quàng chiếc khăn màu đỏ tươi nổi bật trên chiếc áo khoác màu xám.","audioKind":"ex"},{"en":"In visual advertising, scarlet backgrounds can attract attention, although colour associations vary across cultures.","vi":"Trong quảng cáo thị giác, phông nền màu đỏ tươi có thể thu hút sự chú ý, dù ý nghĩa biểu tượng của màu sắc có sự khác biệt giữa các nền văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"a scarlet scarf","vi":"khăn quàng đỏ tươi"},{"en":"turn scarlet","vi":"đỏ bừng mặt"},{"en":"scarlet cheeks","vi":"má đỏ ửng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ turn scarlet thường diễn tả việc khuôn mặt đỏ bừng lên do xấu hổ hoặc tức giận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_irony', 'en-c1-24', 'irony', '/ˈaɪrəni/', 'C1', 'điều trớ trêu; nghịch lý; lời châm biếm; ý mỉa mai', 'n.', 'ironic (adj.), ironically (adv.)', NULL, 'Irony không chỉ là sự trùng hợp ngẫu nhiên, mà thường chỉ sự chênh lệch mỉa mai giữa kết quả và kỳ vọng.', 'The irony is that our swimming lesson was cancelled by rain.', NULL, 'Trớ trêu thay, buổi học bơi của chúng tôi lại bị hủy vì trời mưa.', '{"wordId":"irony","ukIpa":"/ˈaɪrəni/","usIpa":"/ˈaɪrəni/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"A situation that is strikingly opposite to what is expected.","vi":"điều trớ trêu; nghịch lý"},{"pos":"n.","en":"Using words opposite to your meaning, often for humorous effect.","vi":"lời châm biếm; ý mỉa mai"}],"examples":[{"en":"The irony is that our swimming lesson was cancelled by rain.","vi":"Trớ trêu thay, buổi học bơi của chúng tôi lại bị hủy vì trời mưa.","audioKind":"ex"},{"en":"There is considerable irony in promoting environmental awareness through disposable products that create additional waste.","vi":"Việc thúc đẩy nhận thức về môi trường thông qua các sản phẩm dùng một lần tạo ra thêm rác thải mang tính trớ trêu đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"the irony of the situation","vi":"tính chất trớ trêu của hoàn cảnh"},{"en":"a sense of irony","vi":"sự nhạy cảm với tính châm biếm"},{"en":"dramatic irony","vi":"sự mỉa mai kịch tính"}],"wordFamily":["ironic (adj.)","ironically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Irony không chỉ là sự trùng hợp ngẫu nhiên, mà thường chỉ sự chênh lệch mỉa mai giữa kết quả và kỳ vọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depict', 'en-c1-24', 'depict', '/dɪˈpɪkt/', 'C1', 'mô tả; khắc họa; miêu tả qua nghệ thuật, hình ảnh hoặc ngôn từ', 'v.', 'depiction (n.)', 'Đồng nghĩa: portray, represent', 'Cấu trúc depict A as B nghĩa là miêu tả A như là B.', 'This painting depicts children playing beside a quiet lake.', NULL, 'Bức tranh này khắc họa cảnh trẻ em đang chơi đùa bên một hồ nước yên tĩnh.', '{"wordId":"depict","ukIpa":"/dɪˈpɪkt/","usIpa":"/dɪˈpɪkt/","cefr":"C1","topic":"arts","senses":[{"pos":"v.","en":"to show or describe something in art, images, or words","vi":"mô tả; khắc họa; miêu tả qua nghệ thuật, hình ảnh hoặc ngôn từ"}],"examples":[{"en":"This painting depicts children playing beside a quiet lake.","vi":"Bức tranh này khắc họa cảnh trẻ em đang chơi đùa bên một hồ nước yên tĩnh.","audioKind":"ex"},{"en":"Films often depict urban life as exciting, overlooking the isolation that many residents experience in large cities.","vi":"Phim ảnh thường miêu tả cuộc sống thành thị rất sôi động, mà bỏ qua cảm giác cô lập mà nhiều cư dân phải trải qua ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"depict daily life","vi":"mô tả đời sống hàng ngày"},{"en":"depict someone as","vi":"miêu tả ai đó như là"},{"en":"accurately depict","vi":"mô tả chính xác"}],"wordFamily":["depiction (n.)"],"synonyms":["portray","represent"],"antonyms":[],"tipVi":"Cấu trúc depict A as B nghĩa là miêu tả A như là B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tempo', 'en-c1-24', 'tempo', '/ˈtempoʊ/', 'C1', 'nhịp độ âm nhạc; tiết tấu; tốc độ; nhịp độ (của hoạt động hoặc quá trình)', 'n.', NULL, 'Đồng nghĩa: pace, speed', 'Chỉ tốc độ nhanh chậm của âm nhạc, không đồng nghĩa hoàn toàn với nhịp điệu rhythm.', 'The drummer increased the tempo, and everyone danced faster.', NULL, 'Tay trống đẩy nhanh nhịp độ, và mọi người bắt đầu nhảy nhanh hơn.', '{"wordId":"tempo","ukIpa":"/ˈtempəʊ/","usIpa":"/ˈtempoʊ/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"The speed at which music is played.","vi":"nhịp độ âm nhạc; tiết tấu"},{"pos":"n.","en":"The pace at which an activity or process happens.","vi":"tốc độ; nhịp độ (của hoạt động hoặc quá trình)"}],"examples":[{"en":"The drummer increased the tempo, and everyone danced faster.","vi":"Tay trống đẩy nhanh nhịp độ, và mọi người bắt đầu nhảy nhanh hơn.","audioKind":"ex"},{"en":"The tempo of urban life has accelerated as digital services make daily tasks increasingly immediate.","vi":"Nhịp độ của đời sống đô thị đã tăng lên khi các dịch vụ số hóa giúp việc xử lý các công việc hàng ngày trở nên tức thì hơn.","audioKind":"ex2"}],"collocations":[{"en":"a fast tempo","vi":"nhịp độ nhanh"},{"en":"a slow tempo","vi":"nhịp độ chậm"},{"en":"increase the tempo","vi":"tăng nhịp độ"},{"en":"the tempo of life","vi":"nhịp sống"}],"wordFamily":[],"synonyms":["pace","speed"],"antonyms":[],"tipVi":"Chỉ tốc độ nhanh chậm của âm nhạc, không đồng nghĩa hoàn toàn với nhịp điệu rhythm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elaborate', 'en-c1-24', 'elaborate', '/ɪˈlæbərət/', 'C1', 'tinh xảo; phức tạp; công phu; giải thích tỉ mỉ; trình bày chi tiết', 'adj.', 'elaboration (n.), elaborately (adv.), elaborateness (n.)', 'Đồng nghĩa: intricate, detailed · Trái nghĩa: simple, plain', 'Khi là động từ, phần đuôi đọc là /eɪt/; cụm elaborate on có nghĩa là giải thích chi tiết.', 'The cake had elaborate flowers made entirely from icing.', NULL, 'Chiếc bánh có những bông hoa trang trí công phu được làm hoàn toàn từ kem đường.', '{"wordId":"elaborate","ukIpa":"/ɪˈlæbərət/","usIpa":"/ɪˈlæbərət/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"Containing many carefully arranged details or parts.","vi":"tinh xảo; phức tạp; công phu"},{"pos":"v.","en":"To explain something further by adding more details.","vi":"giải thích tỉ mỉ; trình bày chi tiết"}],"examples":[{"en":"The cake had elaborate flowers made entirely from icing.","vi":"Chiếc bánh có những bông hoa trang trí công phu được làm hoàn toàn từ kem đường.","audioKind":"ex"},{"en":"Governments sometimes develop elaborate plans for educational reform without consulting the teachers who will implement them.","vi":"Chính phủ đôi khi xây dựng các kế hoạch cải cách giáo dục rất công phu mà không tham khảo ý kiến của những giáo viên sẽ là người trực tiếp thực hiện chúng.","audioKind":"ex2"}],"collocations":[{"en":"an elaborate design","vi":"một thiết kế tinh xảo"},{"en":"an elaborate plan","vi":"một kế hoạch chu đáo và phức tạp"},{"en":"elaborate on a point","vi":"trình bày chi tiết về một vấn đề"}],"wordFamily":["elaboration (n.)","elaborately (adv.)","elaborateness (n.)"],"synonyms":["intricate","detailed"],"antonyms":["simple","plain"],"tipVi":"Khi là động từ, phần đuôi đọc là /eɪt/; cụm elaborate on có nghĩa là giải thích chi tiết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fiddle', 'en-c1-24', 'fiddle', '/ˈfɪdəl/', 'C1', 'đàn vi-ô-lông (đặc biệt khi dùng trong âm nhạc dân gian); táy máy; bứt rứt (li tục di chuyển hoặc chạm vào thứ gì đó mà không có mục đích rõ ràng); gian lận; giả mạo (thay đổi thông tin một cách bất hợp pháp để trục lợi)', 'n.', 'fiddler (n.), fiddling (adj.)', 'Đồng nghĩa: violin', 'Chỉ đàn vi-ô-lông khi dùng trong văn phong thông thường; fiddle with diễn tả hành động táy máy.', 'My uncle plays the fiddle at family gatherings.', NULL, 'Chú tôi chơi đàn vi-ô-lông trong các buổi họp mặt gia đình.', '{"wordId":"fiddle","ukIpa":"/ˈfɪdəl/","usIpa":"/ˈfɪdəl/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"a violin, especially when used for folk music","vi":"đàn vi-ô-lông (đặc biệt khi dùng trong âm nhạc dân gian)"},{"pos":"v.","en":"keep moving or touching something without a clear purpose","vi":"táy máy; bứt rứt (li tục di chuyển hoặc chạm vào thứ gì đó mà không có mục đích rõ ràng)"},{"pos":"v.","en":"dishonestly change information to gain an advantage","vi":"gian lận; giả mạo (thay đổi thông tin một cách bất hợp pháp để trục lợi)"}],"examples":[{"en":"My uncle plays the fiddle at family gatherings.","vi":"Chú tôi chơi đàn vi-ô-lông trong các buổi họp mặt gia đình.","audioKind":"ex"},{"en":"Traditional instruments such as the fiddle can help younger generations connect with their cultural heritage.","vi":"Các nhạc cụ truyền thống như đàn vi-ô-lông có thể giúp thế hệ trẻ kết nối với di sản văn hóa của họ.","audioKind":"ex2"}],"collocations":[{"en":"play the fiddle","vi":"chơi đàn vi-ô-lông"},{"en":"fiddle with a pen","vi":"táy máy cây bút"},{"en":"fiddle the accounts","vi":"gian lận sổ sách"}],"wordFamily":["fiddler (n.)","fiddling (adj.)"],"synonyms":["violin"],"antonyms":[],"tipVi":"Chỉ đàn vi-ô-lông khi dùng trong văn phong thông thường; fiddle with diễn tả hành động táy máy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rave', 'en-c1-24', 'rave', '/reɪv/', 'C1', 'ca ngợi hết lời; tán dương nhiệt liệt; nói nhảm; quát tháo ầm ĩ; bữa tiệc nhảy múa cuồng nhiệt với nhạc điện tử', 'v.', NULL, NULL, 'rave about chủ yếu mang nghĩa ca ngợi hết lời, không phải là chỉ trích hay gào thét.', 'My friends keep raving about that little noodle shop.', NULL, 'Bạn bè tôi cứ ca ngợi mãi về quán mì nhỏ đó.', '{"wordId":"rave","ukIpa":"/reɪv/","usIpa":"/reɪv/","cefr":"C1","topic":"arts","senses":[{"pos":"v.","en":"to speak with great enthusiasm about something","vi":"ca ngợi hết lời; tán dương nhiệt liệt"},{"pos":"v.","en":"to speak wildly or angrily in an uncontrolled way","vi":"nói nhảm; quát tháo ầm ĩ"},{"pos":"n.","en":"a large party where people dance to electronic music","vi":"bữa tiệc nhảy múa cuồng nhiệt với nhạc điện tử"}],"examples":[{"en":"My friends keep raving about that little noodle shop.","vi":"Bạn bè tôi cứ ca ngợi mãi về quán mì nhỏ đó.","audioKind":"ex"},{"en":"Although critics raved about the exhibition, some visitors questioned whether its high admission price was justified.","vi":"Mặc dù các nhà phê bình hết lời ca ngợi triển lãm, một số khách tham quan vẫn đặt câu hỏi liệu mức giá vé cao có thực sự hợp lý hay không.","audioKind":"ex2"}],"collocations":[{"en":"rave about","vi":"ca ngợi hết lời"},{"en":"rave reviews","vi":"những đánh giá nhiệt liệt"},{"en":"rant and rave","vi":"gào thét tức giận"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"rave about chủ yếu mang nghĩa ca ngợi hết lời, không phải là chỉ trích hay gào thét.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_noted', 'en-c1-24', 'noted', '/ˈnoʊtɪd/', 'C1', 'nổi tiếng; có tiếng', 'adj.', 'note (v.), notable (adj.), notably (adv.)', 'Đồng nghĩa: renowned, famous, distinguished · Trái nghĩa: unknown', 'be noted for đi kèm với lý do hoặc đặc điểm tạo nên tên tuổi.', 'A noted pianist performed at our local theatre yesterday.', NULL, 'Một nghệ sĩ piano nổi tiếng đã biểu diễn tại nhà hát địa phương của chúng tôi ngày hôm qua.', '{"wordId":"noted","ukIpa":"/ˈnəʊtɪd/","usIpa":"/ˈnoʊtɪd/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"well known and admired for a particular quality or achievement","vi":"nổi tiếng; có tiếng"}],"examples":[{"en":"A noted pianist performed at our local theatre yesterday.","vi":"Một nghệ sĩ piano nổi tiếng đã biểu diễn tại nhà hát địa phương của chúng tôi ngày hôm qua.","audioKind":"ex"},{"en":"The region is noted for its traditional crafts, which attract visitors and support the local economy.","vi":"Vùng này nổi tiếng với các nghề thủ công truyền thống, thu hút du khách và hỗ trợ kinh tế địa phương.","audioKind":"ex2"}],"collocations":[{"en":"be noted for","vi":"nổi tiếng vì"},{"en":"a noted scholar","vi":"một học giả có tiếng"},{"en":"a noted expert","vi":"một chuyên gia nổi tiếng"}],"wordFamily":["note (v.)","notable (adj.)","notably (adv.)"],"synonyms":["renowned","famous","distinguished"],"antonyms":["unknown"],"tipVi":"be noted for đi kèm với lý do hoặc đặc điểm tạo nên tên tuổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_24_1', 'en-c1-24', 'Cách dùng “theatrical” (adj.) — thuộc về sân khấu; kịch nghệ', 'a theatrical production  ·  a theatrical performance  ·  a theatrical gesture', 'Từ này vừa chỉ các vấn đề liên quan đến sân khấu, vừa có thể dùng để miêu tả lời nói hoặc hành động mang tính cường điệu, làm quá.', 'Họ từ (Word Family): theatre (n.), theatrically (adv.) | Đồng nghĩa: dramatic', '[{"hanzi":"We watched a theatrical performance in the park yesterday.","pinyin":"","meaning":"Hôm qua chúng tôi đã xem một buổi biểu diễn kịch ở công viên."},{"hanzi":"Public funding for theatrical productions can make live performances accessible to communities with limited cultural resources.","pinyin":"","meaning":"Việc tài trợ công cho các sản phẩm sân khấu có thể giúp các buổi biểu diễn trực tiếp tiếp cận được với các cộng đồng có nguồn lực văn hóa hạn chế."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_24_2', 'en-c1-24', 'Cách dùng “papercut” (n.) — tác phẩm cắt giấy; nghệ thuật cắt giấy', 'a traditional papercut  ·  an intricate papercut  ·  papercut art', 'Nghệ thuật cắt giấy thường dùng từ papercutting; trong khi vết thương do giấy cắt thường viết là paper cut.', 'Họ từ (Word Family): papercutting (n.)', '[{"hanzi":"She framed a delicate papercut of birds and flowers.","pinyin":"","meaning":"Cô ấy đã lồng khung một bức tranh cắt giấy hình chim hoa tinh xảo."},{"hanzi":"Displaying traditional papercuts in community museums can help younger generations appreciate local craft skills and cultural heritage.","pinyin":"","meaning":"Việc trưng bày các tác phẩm cắt giấy truyền thống trong bảo tàng cộng đồng có thể giúp thế hệ trẻ trân trọng các kỹ năng thủ công và di sản văn hóa địa phương."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_24_3', 'en-c1-24', 'Cách dùng “resonance” (n.) — sự cộng hưởng (cảm xúc); sức gợi cảm; khả năng lay động', 'emotional resonance  ·  cultural resonance  ·  magnetic resonance', 'Nghĩa về cảm xúc thường đi với cấu trúc have resonance for; nghĩa vật lý chỉ hiện tượng cộng hưởng sóng.', 'Họ từ (Word Family): resonate (v.), resonant (adj.)', '[{"hanzi":"That old song has special resonance for my grandparents.","pinyin":"","meaning":"Bản nhạc xưa ấy mang lại sự cộng hưởng cảm xúc đặc biệt cho ông bà tôi."},{"hanzi":"Stories about migration often have emotional resonance for readers whose families have experienced similar journeys and challenges.","pinyin":"","meaning":"Những câu chuyện về di cư thường tạo được tiếng vang cảm xúc cho những độc giả có gia đình từng trải qua hành trình và thử thách tương tự."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_24_4', 'en-c1-24', 'Cách dùng “irony” (n.) — điều trớ trêu; nghịch lý', 'the irony of the situation  ·  a sense of irony  ·  dramatic irony', 'Irony không chỉ là sự trùng hợp ngẫu nhiên, mà thường chỉ sự chênh lệch mỉa mai giữa kết quả và kỳ vọng.', 'Họ từ (Word Family): ironic (adj.), ironically (adv.)', '[{"hanzi":"The irony is that our swimming lesson was cancelled by rain.","pinyin":"","meaning":"Trớ trêu thay, buổi học bơi của chúng tôi lại bị hủy vì trời mưa."},{"hanzi":"There is considerable irony in promoting environmental awareness through disposable products that create additional waste.","pinyin":"","meaning":"Việc thúc đẩy nhận thức về môi trường thông qua các sản phẩm dùng một lần tạo ra thêm rác thải mang tính trớ trêu đáng kể."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_24_1', 'en-c1-24', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_1_1', 'ten_c1_24_1', 'sonnet', 'She read a sonnet aloud beside the open window.', 'She read a sonnet aloud beside the open window.', '/ˈsɑːnɪt/', 'Cô ấy đọc to một bài thơ mười bốn câu bên cạnh khung cửa sổ mở.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_1_2', 'ten_c1_24_1', 'craftsmanship', 'The handmade chair shows beautiful craftsmanship in every joint.', 'The handmade chair shows beautiful craftsmanship in every joint.', '/ˈkræftsmənʃɪp/', 'Chiếc ghế làm thủ công cho thấy tay nghề chế tác tinh xảo trong từng mối nối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_1_3', 'ten_c1_24_1', 'chisel', 'She used a chisel to shape the wooden bowl.', 'She used a chisel to shape the wooden bowl.', '/ˈtʃɪzəl/', 'Cô ấy dùng một chiếc đục để tạo hình cho cái bát gỗ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_1_4', 'ten_c1_24_1', 'essayist', 'The essayist described her childhood with warmth and humour.', 'The essayist described her childhood with warmth and humour.', '/ˈeseɪɪst/', 'Nhà văn viết tản văn đã miêu tả tuổi thơ của mình bằng sự ấm áp và hài hước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_1_5', 'ten_c1_24_1', 'ovation', 'The young pianist received an ovation after her performance.', 'The young pianist received an ovation after her performance.', '/oʊˈveɪʃən/', 'Nữ nghệ sĩ piano trẻ tuổi đã nhận được những tràng pháo tay nhiệt liệt sau màn trình diễn của cô ấy.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_1_6', 'ten_c1_24_1', 'prelude', 'Our short walk was a prelude to a lovely picnic.', 'Our short walk was a prelude to a lovely picnic.', '/ˈpreljuːd/', 'Chuyến đi dạo ngắn của chúng tôi là sự mở đầu cho một buổi dã ngoại tuyệt vời.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_1_7', 'ten_c1_24_1', 'mythical', 'The museum displayed a painting of a mythical dragon.', 'The museum displayed a painting of a mythical dragon.', '/ˈmɪθɪkəl/', 'Viện bảo tàng trưng bày bức tranh vẽ một con rồng trong thần thoại.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_1_8', 'ten_c1_24_1', 'witty', 'Her witty reply made everyone at the table laugh.', 'Her witty reply made everyone at the table laugh.', '/ˈwɪti/', 'Câu trả lời hóm hỉnh của cô ấy khiến tất cả mọi người ngồi cùng bàn đều bật cười.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_24_1_1', 'en-c1-24', 'ten_c1_24_1', 'listening', 'listening', 'She read a sonnet aloud beside the open window.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mọi người đều nín thở trong phân cảnh cao trào của bộ phim.","Dì tôi đã thêu những bông hoa nhỏ xung quanh viền chiếc gối.","Cô ấy đọc to một bài thơ mười bốn câu bên cạnh khung cửa sổ mở.","Chiếc ghế làm thủ công cho thấy tay nghề chế tác tinh xảo trong từng mối nối."]'::jsonb, 2, 'She read a sonnet aloud beside the open window. → Cô ấy đọc to một bài thơ mười bốn câu bên cạnh khung cửa sổ mở.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_24_1_2', 'en-c1-24', 'ten_c1_24_1', 'listening', 'listening', 'The handmade chair shows beautiful craftsmanship in every joint.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc ghế làm thủ công cho thấy tay nghề chế tác tinh xảo trong từng mối nối.","Bức tranh này khắc họa cảnh trẻ em đang chơi đùa bên một hồ nước yên tĩnh.","Một bức tượng bán thân bằng đá cẩm thạch đứng cạnh lối vào bảo trưng.","Chú tôi chơi đàn vi-ô-lông trong các buổi họp mặt gia đình."]'::jsonb, 0, 'The handmade chair shows beautiful craftsmanship in every joint. → Chiếc ghế làm thủ công cho thấy tay nghề chế tác tinh xảo trong từng mối nối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_24_1_3', 'en-c1-24', 'ten_c1_24_1', 'listening', 'listening', 'She used a chisel to shape the wooden bowl.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Viện bảo tàng trưng bày bức tranh vẽ một con rồng trong thần thoại.","Nhà văn viết tản văn đã miêu tả tuổi thơ của mình bằng sự ấm áp và hài hước.","Cô ấy dùng một chiếc đục để tạo hình cho cái bát gỗ.","Nữ ca sĩ đã bổ sung thêm ba bài hát mới vào danh sách biểu diễn của mình."]'::jsonb, 2, 'She used a chisel to shape the wooden bowl. → Cô ấy dùng một chiếc đục để tạo hình cho cái bát gỗ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_24_2', 'en-c1-24', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_2_1', 'ten_c1_24_2', 'sonnet', 'Studying a sonnet helps students understand how formal constraints can encourage creative expression in literature.', 'Studying a sonnet helps students understand how formal constraints can encourage creative expression in literature.', '/ˈsɑːnɪt/', 'Việc nghiên cứu thơ mười bốn câu giúp học sinh hiểu cách các quy tắc hình thức có thể khuyến khích sự biểu đạt sáng tạo trong văn học.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_2_2', 'ten_c1_24_2', 'craftsmanship', 'Preserving traditional craftsmanship can support local economies while protecting cultural knowledge passed down through generations.', 'Preserving traditional craftsmanship can support local economies while protecting cultural knowledge passed down through generations.', '/ˈkræftsmənʃɪp/', 'Việc bảo tồn nghề thủ công truyền thống có thể hỗ trợ nền kinh tế địa phương đồng thời bảo vệ tri thức văn hóa được truyền qua các thế hệ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_2_3', 'ten_c1_24_2', 'chisel', 'Traditional craftspeople use a chisel to create detailed patterns that preserve local artistic traditions.', 'Traditional craftspeople use a chisel to create detailed patterns that preserve local artistic traditions.', '/ˈtʃɪzəl/', 'Các nghệ nhân truyền thống sử dụng đục để tạo ra các hoa văn chi tiết nhằm bảo tồn các truyền thống nghệ thuật địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_2_4', 'ten_c1_24_2', 'essayist', 'An influential essayist can encourage readers to question social assumptions through personal reflection and careful argument.', 'An influential essayist can encourage readers to question social assumptions through personal reflection and careful argument.', '/ˈeseɪɪst/', 'Một nhà tiểu luận có tầm ảnh hưởng có thể khuyến khích độc giả chất vấn các quan niệm xã hội thông qua sự suy ngẫm cá nhân và lập luận sắc sảo.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_2_5', 'ten_c1_24_2', 'ovation', 'The orchestra received a standing ovation, demonstrating how live performances can create a powerful sense of community.', 'The orchestra received a standing ovation, demonstrating how live performances can create a powerful sense of community.', '/oʊˈveɪʃən/', 'Dàn nhạc đã nhận được tràng pháo tay đứng vang dội từ khán giả, minh chứng cho việc các buổi biểu diễn trực tiếp có thể tạo nên sự gắn kết cộng đồng mạnh mẽ ra sao.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_24_2_6', 'ten_c1_24_2', 'prelude', 'Investment in reliable internet infrastructure is often a prelude to broader economic development in rural regions.', 'Investment in reliable internet infrastructure is often a prelude to broader economic development in rural regions.', '/ˈpreljuːd/', 'Việc đầu tư vào cơ sở hạ tầng internet đáng tin cậy thường là bước đệm cho sự phát triển kinh tế rộng lớn hơn ở các vùng nông thôn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_24_2_1', 'en-c1-24', 'ten_c1_24_2', 'listening', 'listening', 'Studying a sonnet helps students understand how formal constraints can encourage creative expression in literature.', NULL, 'Trong câu vừa nghe, từ “sonnet” mang nghĩa nào sau đây?', '["đổi mới; sáng tạo","thơ mười bốn câu (thể thơ gồm 14 dòng tuân theo một vần điệu và nhịp điệu nhất định)","pít-tông; tr Pít-tông","vườn cây nhỏ; một khu rừng nhỏ thường được trồng tập trung"]'::jsonb, 1, '“sonnet” (/ˈsɑːnɪt/): thơ mười bốn câu (thể thơ gồm 14 dòng tuân theo một vần điệu và nhịp điệu nhất định). Câu đầy đủ: Studying a sonnet helps students understand how formal constraints can encourage creative expression in literature.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_24_2_2', 'en-c1-24', 'ten_c1_24_2', 'listening', 'listening', 'Preserving traditional craftsmanship can support local economies while protecting cultural knowledge passed down through generations.', NULL, 'Trong câu vừa nghe, từ “craftsmanship” mang nghĩa nào sau đây?', '["tay nghề thủ công; kỹ năng chế tác tinh xảo","hộp mực; ống mực (thay thế được cho máy móc)","vùng cao, cao nguyên (vùng đất nằm cao hơn mực nước biển)","chứa muối; có tính muối"]'::jsonb, 0, '“craftsmanship” (/ˈkræftsmənʃɪp/): tay nghề thủ công; kỹ năng chế tác tinh xảo. Câu đầy đủ: Preserving traditional craftsmanship can support local economies while protecting cultural knowledge passed down through generations.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
