INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_24_4', 'en-c1-24', 'The essayist described her childhood with warmth and humour', 'Nhà văn viết tản văn đã miêu tả tuổi thơ của mình bằng sự ấm áp và hài hước.', 'essayist /ˈeseɪɪst/', '["described","essayist","humour","childhood","The","warmth","and","her","with"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
