INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_24_15', 'en-c1-24', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “inscribe” (/ɪnˈskraɪb/) có nghĩa là gì?', '["hóm hỉnh; sắc sảo","khắc chữ; đề chữ","lời mở đầu; khúc dạo đầu; bước đệm (sự việc xảy ra trước và dẫn dắt cho một sự kiện quan trọng hơn)","cái đục"]'::jsonb, 1, '“inscribe” (v.): khắc chữ; đề chữ.', 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_1', 'en-c1-24', NULL, 'comprehensive_test', 'listening', 'sonnet', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đứng yên; tĩnh tại; không di chuyển","sự ngưng chiến; thỏa thuận tạm đình chiến","thơ mười bốn câu (thể thơ gồm 14 dòng tuân theo một vần điệu và nhịp điệu nhất định)","cái đục"]'::jsonb, 2, 'sonnet (/ˈsɑːnɪt/) → thơ mười bốn câu (thể thơ gồm 14 dòng tuân theo một vần điệu và nhịp điệu nhất định)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_2', 'en-c1-24', NULL, 'comprehensive_test', 'listening', 'The handmade chair shows beautiful craftsmanship in every joint.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dì tôi đã thêu những bông hoa nhỏ xung quanh viền chiếc gối.","Chiếc ghế làm thủ công cho thấy tay nghề chế tác tinh xảo trong từng mối nối.","Trong câu chuyện, một loại nước phép đã biến hoàng tử thành kẻ tàng hình.","Trớ trêu thay, buổi học bơi của chúng tôi lại bị hủy vì trời mưa."]'::jsonb, 1, 'The handmade chair shows beautiful craftsmanship in every joint. → Chiếc ghế làm thủ công cho thấy tay nghề chế tác tinh xảo trong từng mối nối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_3', 'en-c1-24', NULL, 'comprehensive_test', 'listening', 'chisel', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cái đục","phôi; phôi thai (ở giai đoạn phát triển rất sớm của động vật hoặc thực vật)","hòa quyện; trộn lẫn","không ngừng nghỉ; liên tục không giảm"]'::jsonb, 0, 'chisel (/ˈtʃɪzəl/) → cái đục; đục; chạm trổ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_4', 'en-c1-24', NULL, 'comprehensive_test', 'listening', 'The essayist described her childhood with warmth and humour.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy quàng chiếc khăn màu đỏ tươi nổi bật trên chiếc áo khoác màu xám.","Bạn bè tôi cứ ca ngợi mãi về quán mì nhỏ đó.","Nhà văn viết tản văn đã miêu tả tuổi thơ của mình bằng sự ấm áp và hài hước.","Người thợ kim hoàn đã khắc chữ cái đầu tên chúng tôi vào mặt trong của chiếc nhẫn bạc."]'::jsonb, 2, 'The essayist described her childhood with warmth and humour. → Nhà văn viết tản văn đã miêu tả tuổi thơ của mình bằng sự ấm áp và hài hước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_5', 'en-c1-24', NULL, 'comprehensive_test', 'listening', 'ovation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tràng pháo tay nhiệt liệt; sự hoan hô","dựa dẫm; phụ thuộc; nhờ vào","tù nhân; người đã bị kết án","dây cương ngựa"]'::jsonb, 0, 'ovation (/oʊˈveɪʃən/) → tràng pháo tay nhiệt liệt; sự hoan hô', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_6', 'en-c1-24', NULL, 'comprehensive_test', 'listening', 'Our short walk was a prelude to a lovely picnic.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mọi người đều nín thở trong phân cảnh cao trào của bộ phim.","Chú tôi chơi đàn vi-ô-lông trong các buổi họp mặt gia đình.","Trớ trêu thay, buổi học bơi của chúng tôi lại bị hủy vì trời mưa.","Chuyến đi dạo ngắn của chúng tôi là sự mở đầu cho một buổi dã ngoại tuyệt vời."]'::jsonb, 3, 'Our short walk was a prelude to a lovely picnic. → Chuyến đi dạo ngắn của chúng tôi là sự mở đầu cho một buổi dã ngoại tuyệt vời.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_7', 'en-c1-24', NULL, 'comprehensive_test', 'listening', 'mythical', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xa hoa; phung phí; đắt đỏ","biết ơn; mang ơn","thuộc về thần thoại","sứ mệnh; công việc phù hợp với tâm huyết bản thân"]'::jsonb, 2, 'mythical (/ˈmɪθɪkəl/) → thuộc về thần thoại; hư cấu; tưởng tượng; không có thật trong thực tế', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_8', 'en-c1-24', NULL, 'comprehensive_test', 'listening', 'Her witty reply made everyone at the table laugh.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nữ ca sĩ đã bổ sung thêm ba bài hát mới vào danh sách biểu diễn của mình.","Bản nhạc xưa ấy mang lại sự cộng hưởng cảm xúc đặc biệt cho ông bà tôi.","Bạn bè tôi cứ ca ngợi mãi về quán mì nhỏ đó.","Câu trả lời hóm hỉnh của cô ấy khiến tất cả mọi người ngồi cùng bàn đều bật cười."]'::jsonb, 3, 'Her witty reply made everyone at the table laugh. → Câu trả lời hóm hỉnh của cô ấy khiến tất cả mọi người ngồi cùng bàn đều bật cười.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_9', 'en-c1-24', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “enthusiastic applause from an audience to show strong approval”?', '["theatrical","ovation","climactic","papercut"]'::jsonb, 1, 'ovation (/oʊˈveɪʃən/) → tràng pháo tay nhiệt liệt; sự hoan hô', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_10', 'en-c1-24', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Something that happens before and introduces a more important event.”?', '["tempo","elaborate","sonnet","prelude"]'::jsonb, 3, 'prelude (/ˈpreljuːd/) → lời mở đầu; khúc dạo đầu; bước đệm (sự việc xảy ra trước và dẫn dắt cho một sự kiện quan trọng hơn)', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_11', 'en-c1-24', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “existing in or relating to traditional myths”?', '["mythical","embroider","ovation","essayist"]'::jsonb, 0, 'mythical (/ˈmɪθɪkəl/) → thuộc về thần thoại', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_12', 'en-c1-24', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Using words in a clever and amusing way”?', '["depict","fiddle","papercut","witty"]'::jsonb, 3, 'witty (/ˈwɪti/) → hóm hỉnh; sắc sảo', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_13', 'en-c1-24', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a sculpture showing a person''s head, shoulders, and upper chest”?', '["mythical","bust","climactic","irony"]'::jsonb, 1, 'bust (/bʌst/) → tượng bán thân', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
