INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_18', 'en-c1-24', NULL, 'comprehensive_test', 'reading', NULL, 'Studying a sonnet helps students understand how formal constraints can encourage creative expression in literature.', 'Dựa vào câu trên, từ “sonnet” có nghĩa phù hợp nhất là gì?', '["viên nhỏ; hạt nén","kêu lanh canh; làm kêu lanh canh","thơ mười bốn câu (thể thơ gồm 14 dòng tuân theo một vần điệu và nhịp điệu nhất định)","bắt buộc; làm cho phải tuân theo"]'::jsonb, 2, 'sonnet: thơ mười bốn câu (thể thơ gồm 14 dòng tuân theo một vần điệu và nhịp điệu nhất định). Dịch cả câu: Việc nghiên cứu thơ mười bốn câu giúp học sinh hiểu cách các quy tắc hình thức có thể khuyến khích sự biểu đạt sáng tạo trong văn học.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_19', 'en-c1-24', NULL, 'comprehensive_test', 'reading', NULL, 'Preserving traditional craftsmanship can support local economies while protecting cultural knowledge passed down through generations.', 'Dựa vào câu trên, từ “craftsmanship” có nghĩa phù hợp nhất là gì?', '["buổi biểu diễn độc tấu; buổi biểu diễn hòa nhạc nhỏ","đào, khoét, khai đào","thông thạo; am hiểu; quen thuộc","tay nghề thủ công; kỹ năng chế tác tinh xảo"]'::jsonb, 3, 'craftsmanship: tay nghề thủ công; kỹ năng chế tác tinh xảo. Dịch cả câu: Việc bảo tồn nghề thủ công truyền thống có thể hỗ trợ nền kinh tế địa phương đồng thời bảo vệ tri thức văn hóa được truyền qua các thế hệ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_20', 'en-c1-24', NULL, 'comprehensive_test', 'reading', NULL, 'Traditional craftspeople use a chisel to create detailed patterns that preserve local artistic traditions.', 'Dựa vào câu trên, từ “chisel” có nghĩa phù hợp nhất là gì?', '["cản trở; gây khó khăn","vô hình; phi vật chất; khó đo lường","lỗi lạc; kiệt xuất; đáng kính trọng","cái đục"]'::jsonb, 3, 'chisel: cái đục; đục; chạm trổ. Dịch cả câu: Các nghệ nhân truyền thống sử dụng đục để tạo ra các hoa văn chi tiết nhằm bảo tồn các truyền thống nghệ thuật địa phương.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_21', 'en-c1-24', NULL, 'comprehensive_test', 'reading', NULL, 'An influential essayist can encourage readers to question social assumptions through personal reflection and careful argument.', 'Dựa vào câu trên, từ “essayist” có nghĩa phù hợp nhất là gì?', '["tác giả viết tản văn; nhà văn chuyên viết tiểu luận","phủ lên nhau; chồng chéo lên nhau; có điểm chung","lướt đi; trôi êm ái; di chuyển nhẹ nhàng","sự chỉ định; sự bổ nhiệm; sự phân loại"]'::jsonb, 0, 'essayist: tác giả viết tản văn; nhà văn chuyên viết tiểu luận. Dịch cả câu: Một nhà tiểu luận có tầm ảnh hưởng có thể khuyến khích độc giả chất vấn các quan niệm xã hội thông qua sự suy ngẫm cá nhân và lập luận sắc sảo.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_22', 'en-c1-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đàn vi-ô-lông (đặc biệt khi dùng trong âm nhạc dân gian)”', '["fiddle","coherence","nucleus","physician"]'::jsonb, 0, 'đàn vi-ô-lông (đặc biệt khi dùng trong âm nhạc dân gian) → fiddle (/ˈfɪdəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_23', 'en-c1-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ca ngợi hết lời; tán dương nhiệt liệt”', '["hydraulic","swarm","prospectus","rave"]'::jsonb, 3, 'ca ngợi hết lời; tán dương nhiệt liệt → rave (/reɪv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_24_24', 'en-c1-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nổi tiếng; có tiếng”', '["refute","protracted","noted","null"]'::jsonb, 2, 'nổi tiếng; có tiếng → noted (/ˈnoʊtɪd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-25', 'en', 'Bài 25: Nghệ thuật & Sáng tạo (2) - CEFR C1', 'CEFR C1', 'C1 · Nghệ thuật', '25 từ vựng Tiếng Anh CEFR C1 chủ đề nghệ thuật & sáng tạo kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5025, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_duet', 'en-c1-25', 'duet', '/duˈet/', 'C1', 'bản song ca; khúc hát/khúc nhạc đôi cho hai người biểu diễn', 'n.', NULL, NULL, 'Duet chỉ tác phẩm hoặc phần trình diễn dành cho hai người hát hoặc chơi nhạc, không dùng để chỉ ban nhạc gồm hai thành viên.', 'The sisters sang a beautiful duet at the concert.', NULL, 'Hai chị em đã hát một bài song ca tuyệt đẹp tại buổi hòa nhạc.', '{"wordId":"duet","ukIpa":"/djuˈet/","usIpa":"/duˈet/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"A musical piece or performance for two singers or players.","vi":"bản song ca; khúc hát/khúc nhạc đôi cho hai người biểu diễn"}],"examples":[{"en":"The sisters sang a beautiful duet at the concert.","vi":"Hai chị em đã hát một bài song ca tuyệt đẹp tại buổi hòa nhạc.","audioKind":"ex"},{"en":"Performing a duet encourages music students to listen carefully and coordinate their timing with another musician.","vi":"Việc biểu diễn một bản song ca khuyến khích sinh viên âm nhạc lắng nghe cẩn thận và phối hợp nhịp nhàng với một nhạc sĩ khác.","audioKind":"ex2"}],"collocations":[{"en":"sing a duet","vi":"hát song ca"},{"en":"a piano duet","vi":"bản song tấu piano"},{"en":"perform a duet","vi":"biểu diễn tiết mục song ca"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Duet chỉ tác phẩm hoặc phần trình diễn dành cho hai người hát hoặc chơi nhạc, không dùng để chỉ ban nhạc gồm hai thành viên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embroidery', 'en-c1-25', 'embroidery', '/ɪmˈbrɔɪdəri/', 'C1', 'nghệ thuật thêu thùa; nghề thêu; hàng thêu; họa tiết thêu', 'n.', 'embroider (v.), embroidered (adj.), embroiderer (n.)', NULL, 'Embroidery thường là danh từ không đếm được; động từ tương ứng là embroider.', 'I practise embroidery by stitching flowers onto plain cushions.', NULL, 'Tôi tập thêu bằng cách thêu những bông hoa lên các chiếc gối trơn.', '{"wordId":"embroidery","ukIpa":"/ɪmˈbrɔɪdəri/","usIpa":"/ɪmˈbrɔɪdəri/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"The craft of decorating cloth with needle and thread.","vi":"nghệ thuật thêu thùa; nghề thêu"},{"pos":"n.","en":"Decorative patterns sewn onto cloth using coloured thread.","vi":"hàng thêu; họa tiết thêu"}],"examples":[{"en":"I practise embroidery by stitching flowers onto plain cushions.","vi":"Tôi tập thêu bằng cách thêu những bông hoa lên các chiếc gối trơn.","audioKind":"ex"},{"en":"Community embroidery workshops can preserve traditional skills while creating opportunities for different generations to learn together.","vi":"Các buổi workshop thêu thùa tại cộng đồng có thể gìn giữ các kỹ năng truyền thống đồng thời tạo cơ hội cho các thế hệ khác nhau cùng học hỏi.","audioKind":"ex2"}],"collocations":[{"en":"hand embroidery","vi":"thêu thủ công"},{"en":"embroidery thread","vi":"chỉ thêu"},{"en":"embroidery hoop","vi":"khung thêu"},{"en":"intricate embroidery","vi":"họa tiết thêu tinh xảo"}],"wordFamily":["embroider (v.)","embroidered (adj.)","embroiderer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Embroidery thường là danh từ không đếm được; động từ tương ứng là embroider.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_renaissance', 'en-c1-25', 'renaissance', '/ˈrenəsɑːns/', 'C1', 'sự hồi sinh; thời kỳ phục hưng; thời kỳ Văn hóa Phục hưng châu Âu', 'n.', NULL, 'Đồng nghĩa: revival, renewal · Trái nghĩa: decline', 'Khi chỉ thời kỳ lịch sử phong trào Phục hưng, từ này thường được viết hoa và đi kèm mạo từ the.', 'Our local theatre is enjoying a renaissance this summer.', NULL, 'Nhà hát địa phương của chúng tôi đang trải qua giai đoạn hồi sinh mạnh mẽ vào mùa hè này.', '{"wordId":"renaissance","ukIpa":"/rɪˈneɪsəns/","usIpa":"/ˈrenəsɑːns/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"a period of renewed interest, activity, or success","vi":"sự hồi sinh; thời kỳ phục hưng"},{"pos":"n.","en":"the European period of renewed classical learning and artistic development","vi":"thời kỳ Văn hóa Phục hưng châu Âu"}],"examples":[{"en":"Our local theatre is enjoying a renaissance this summer.","vi":"Nhà hát địa phương của chúng tôi đang trải qua giai đoạn hồi sinh mạnh mẽ vào mùa hè này.","audioKind":"ex"},{"en":"Investment in public galleries could encourage a cultural renaissance in cities affected by industrial decline.","vi":"Việc đầu tư vào các phòng trưng bày công cộng có thể thúc đẩy một cuộc Phục hưng văn hóa tại các thành phố chịu ảnh hưởng bởi suy thoái công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"a cultural renaissance","vi":"sự phục hưng văn hóa"},{"en":"enjoy a renaissance","vi":"trải qua thời kỳ hồi sinh"},{"en":"the Renaissance","vi":"thời kỳ Phục hưng"}],"wordFamily":[],"synonyms":["revival","renewal"],"antonyms":["decline"],"tipVi":"Khi chỉ thời kỳ lịch sử phong trào Phục hưng, từ này thường được viết hoa và đi kèm mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_asymmetric', 'en-c1-25', 'asymmetric', '/ˌeɪsɪˈmetrɪk/', 'C1', 'không đối xứng; không đồng đều; mất cân đối', 'adj.', 'asymmetry (n.), asymmetrical (adj.), asymmetrically (adv.), symmetric (adj.)', 'Đồng nghĩa: asymmetrical · Trái nghĩa: symmetric, symmetrical', 'Có thể chỉ hình dáng không đối xứng hoặc sự bất bình đẳng về thông tin và quyền lực.', 'The jacket has an asymmetric collar and deep pockets.', NULL, 'Chiếc áo khoác có phần cổ áo không đối xứng và các túi sâu.', '{"wordId":"asymmetric","ukIpa":"/ˌeɪsɪˈmetrɪk/","usIpa":"/ˌeɪsɪˈmetrɪk/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"having sides or parts that do not match","vi":"không đối xứng"},{"pos":"adj.","en":"unequal between people, groups, or sides","vi":"không đồng đều; mất cân đối"}],"examples":[{"en":"The jacket has an asymmetric collar and deep pockets.","vi":"Chiếc áo khoác có phần cổ áo không đối xứng và các túi sâu.","audioKind":"ex"},{"en":"Asymmetric access to market information can place small businesses at a disadvantage when negotiating with larger firms.","vi":"Việc tiếp cận thông tin thị trường không cân xứng có thể khiến các doanh nghiệp nhỏ gặp bất lợi khi đàm phán với các công ty lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"asymmetric design","vi":"thiết kế bất đối xứng"},{"en":"asymmetric information","vi":"thông tin bất đối xứng"},{"en":"asymmetric distribution","vi":"phân phối không đối xứng"}],"wordFamily":["asymmetry (n.)","asymmetrical (adj.)","asymmetrically (adv.)","symmetric (adj.)"],"synonyms":["asymmetrical"],"antonyms":["symmetric","symmetrical"],"tipVi":"Có thể chỉ hình dáng không đối xứng hoặc sự bất bình đẳng về thông tin và quyền lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cubism', 'en-c1-25', 'cubism', '/ˈkjuːbɪzəm/', 'C1', 'chủ nghĩa lập thể', 'n.', 'cubist (n.), cubist (adj.)', NULL, 'Thường là danh từ không đếm được; cubist có thể chỉ họa sĩ trường phái lập thể hoặc dùng như tính từ.', 'We explored cubism by painting faces with overlapping geometric shapes.', NULL, 'Chúng tôi đã tìm hiểu về chủ nghĩa lập thể bằng cách vẽ những khuôn mặt với các hình khối hình học chồng lên nhau.', '{"wordId":"cubism","ukIpa":"/ˈkjuːbɪzəm/","usIpa":"/ˈkjuːbɪzəm/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"An art style showing subjects through geometric shapes and multiple viewpoints.","vi":"chủ nghĩa lập thể"}],"examples":[{"en":"We explored cubism by painting faces with overlapping geometric shapes.","vi":"Chúng tôi đã tìm hiểu về chủ nghĩa lập thể bằng cách vẽ những khuôn mặt với các hình khối hình học chồng lên nhau.","audioKind":"ex"},{"en":"Cubism challenged traditional artistic representation by presenting multiple viewpoints within a single image rather than imitating natural appearances.","vi":"Chủ nghĩa lập thể thách thức cách thể hiện nghệ thuật truyền thống bằng cách trình bày nhiều góc nhìn trong một bức ảnh duy nhất thay vì bắt chước vẻ ngoài tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"the development of cubism","vi":"sự phát triển của chủ nghĩa lập thể"},{"en":"analytical cubism","vi":"chủ nghĩa lập thể phân tích"},{"en":"synthetic cubism","vi":"chủ nghĩa lập thể tổng hợp"}],"wordFamily":["cubist (n.)","cubist (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; cubist có thể chỉ họa sĩ trường phái lập thể hoặc dùng như tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glamour', 'en-c1-25', 'glamour', '/ˈɡlæmər/', 'C1', 'sức hút quyến rũ; vẻ hào nhoáng, lộng lẫy', 'n.', 'glamorous (adj.), glamorously (adv.), glamorise (v.)', 'Đồng nghĩa: allure', 'Thường không đếm được; tiếng Mỹ cũng viết là glamor.', 'Her sparkling earrings added glamour to a simple outfit.', NULL, 'Đôi bông tai lấp lánh của cô ấy đã tô điểm thêm vẻ lộng lẫy cho bộ trang phục giản dị.', '{"wordId":"glamour","ukIpa":"/ˈɡlæmə/","usIpa":"/ˈɡlæmər/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"An exciting attractiveness associated with beauty, wealth, or fame.","vi":"sức hút quyến rũ; vẻ hào nhoáng, lộng lẫy"}],"examples":[{"en":"Her sparkling earrings added glamour to a simple outfit.","vi":"Đôi bông tai lấp lánh của cô ấy đã tô điểm thêm vẻ lộng lẫy cho bộ trang phục giản dị.","audioKind":"ex"},{"en":"The apparent glamour of careers in entertainment can obscure the financial insecurity many performers experience.","vi":"Sự hào nhoáng bề ngoài của các nghề nghiệp trong ngành giải trí có thể lu mờ sự bất ổn về tài chính mà nhiều nghệ sĩ phải trải qua.","audioKind":"ex2"}],"collocations":[{"en":"add glamour to","vi":"tăng thêm vẻ quyến rũ cho"},{"en":"the glamour of fame","vi":"ánh hào quang của danh vọng"},{"en":"Hollywood glamour","vi":"sự hào nhoáng kiểu Hollywood"}],"wordFamily":["glamorous (adj.)","glamorously (adv.)","glamorise (v.)"],"synonyms":["allure"],"antonyms":[],"tipVi":"Thường không đếm được; tiếng Mỹ cũng viết là glamor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_patron', 'en-c1-25', 'patron', '/ˈpeɪtrən/', 'C1', 'nhà bảo trợ; người hỗ trợ tài chính; khách hàng; khách quen', 'n.', 'patronage (n.), patronise (v.)', 'Đồng nghĩa: supporter, sponsor, customer', 'patron vừa có nghĩa là nhà tài trợ, vừa là cách gọi trang trọng dành cho khách hàng của nhà hàng hoặc rạp hát.', 'A local patron paid for the young artist''s materials.', NULL, 'Một nhà bảo trợ địa phương đã chi trả tiền vật liệu cho người nghệ sĩ trẻ.', '{"wordId":"patron","ukIpa":"/ˈpeɪtrən/","usIpa":"/ˈpeɪtrən/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"Someone who supports an artist, organisation, or activity, often financially.","vi":"nhà bảo trợ; người hỗ trợ tài chính"},{"pos":"n.","en":"A customer of a restaurant, theatre, or similar place.","vi":"khách hàng; khách quen"}],"examples":[{"en":"A local patron paid for the young artist''s materials.","vi":"Một nhà bảo trợ địa phương đã chi trả tiền vật liệu cho người nghệ sĩ trẻ.","audioKind":"ex"},{"en":"Private patrons can fund experimental art that might otherwise struggle to attract public financial support.","vi":"Các nhà bảo trợ tư nhân có thể tài trợ cho nghệ thuật thử nghiệm vốn có thể gặp khó khăn trong việc thu hút sự hỗ trợ tài chính công.","audioKind":"ex2"}],"collocations":[{"en":"patron of the arts","vi":"nhà bảo trợ nghệ thuật"},{"en":"wealthy patron","vi":"mạnh thường quân giàu có"},{"en":"regular patron","vi":"khách quen"}],"wordFamily":["patronage (n.)","patronise (v.)"],"synonyms":["supporter","sponsor","customer"],"antonyms":[],"tipVi":"patron vừa có nghĩa là nhà tài trợ, vừa là cách gọi trang trọng dành cho khách hàng của nhà hàng hoặc rạp hát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_antagonist', 'en-c1-25', 'antagonist', '/ænˈtæɡənɪst/', 'C1', 'đối thủ, kẻ địch; nhân vật phản diện, tuyến đối đầu (trong tác phẩm văn học, nghệ thuật)', 'n.', 'antagonism (n.), antagonistic (adj.), antagonise (v.)', 'Đồng nghĩa: opponent, adversary · Trái nghĩa: ally', 'Nhân vật đối đầu (antagonist) trong cốt truyện đứng ở phía đối lập với nhân vật chính, không nhất thiết phải là kẻ xấu.', 'The detective finally faced her antagonist in the empty theatre.', NULL, 'Nữ thám tử cuối cùng cũng đối mặt với kẻ đối đầu của mình trong nhà hát trống trải.', '{"wordId":"antagonist","ukIpa":"/ænˈtæɡənɪst/","usIpa":"/ænˈtæɡənɪst/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"Someone who strongly opposes another person.","vi":"đối thủ, kẻ địch"},{"pos":"n.","en":"A character who opposes the main character in a story.","vi":"nhân vật phản diện, tuyến đối đầu (trong tác phẩm văn học, nghệ thuật)"}],"examples":[{"en":"The detective finally faced her antagonist in the empty theatre.","vi":"Nữ thám tử cuối cùng cũng đối mặt với kẻ đối đầu của mình trong nhà hát trống trải.","audioKind":"ex"},{"en":"In many novels, the antagonist challenges the central character''s values rather than simply threatening their physical safety.","vi":"Trong nhiều tiểu thuyết, nhân vật phản diện thách thức các giá trị của nhân vật chính thay vì chỉ đơn thuần đe dọa sự an toàn thể xác của họ.","audioKind":"ex2"}],"collocations":[{"en":"a formidable antagonist","vi":"một đối thủ đáng gờm"},{"en":"the main antagonist","vi":"nhân vật phản diện chính"},{"en":"a political antagonist","vi":"đối thủ chính trị"}],"wordFamily":["antagonism (n.)","antagonistic (adj.)","antagonise (v.)"],"synonyms":["opponent","adversary"],"antonyms":["ally"],"tipVi":"Nhân vật đối đầu (antagonist) trong cốt truyện đứng ở phía đối lập với nhân vật chính, không nhất thiết phải là kẻ xấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_animate', 'en-c1-25', 'animate', '/ˈænɪmeɪt/', 'C1', 'làm cho sinh động; làm cho sôi nổi; làm hoạt hình; tạo hình động', 'v.', 'animation (n.), animated (adj.), animator (n.)', 'Đồng nghĩa: enliven, energise', 'Động từ tận cùng đọc là /meɪt/; tính từ tận cùng đọc là /mət/.', 'Her funny stories always animate our family dinners.', NULL, 'Những câu chuyện hài hước của cô ấy luôn làm cho bữa ăn gia đình chúng tôi thêm phần sôi nổi.', '{"wordId":"animate","ukIpa":"/ˈænɪmeɪt/","usIpa":"/ˈænɪmeɪt/","cefr":"C1","topic":"arts","senses":[{"pos":"v.","en":"To make someone or something more lively or engaging","vi":"làm cho sinh động; làm cho sôi nổi"},{"pos":"v.","en":"To make drawings or models appear to move","vi":"làm hoạt hình; tạo hình động"}],"examples":[{"en":"Her funny stories always animate our family dinners.","vi":"Những câu chuyện hài hước của cô ấy luôn làm cho bữa ăn gia đình chúng tôi thêm phần sôi nổi.","audioKind":"ex"},{"en":"Teachers can animate classroom discussions by encouraging students to share experiences from their own communities.","vi":"Giáo viên có thể làm cho các buổi thảo luận trên lớp thêm phần sôi nổi bằng cách khuyến khích học sinh chia sẻ trải nghiệm từ chính cộng đồng của các em.","audioKind":"ex2"}],"collocations":[{"en":"animate a discussion","vi":"làm cho cuộc thảo luận sôi nổi"},{"en":"animate a character","vi":"làm hoạt hình cho một nhân vật"},{"en":"animated film","vi":"phim hoạt hình"}],"wordFamily":["animation (n.)","animated (adj.)","animator (n.)"],"synonyms":["enliven","energise"],"antonyms":[],"tipVi":"Động từ tận cùng đọc là /meɪt/; tính từ tận cùng đọc là /mət/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_esthetic', 'en-c1-25', 'esthetic', '/esˈθetɪk/', 'C1', 'thuộc về thẩm mỹ; mang tính mỹ học', 'adj.', 'esthetically (adv.), esthetics (n.)', 'Đồng nghĩa: aesthetic', 'Esthetic là biến thể chính tả của Mỹ; trong IELTS, từ aesthetic phổ biến hơn.', 'The curved wooden handle gives the kettle esthetic appeal.', NULL, 'Tay cầm bằng gỗ cong uốn lượn mang lại giá trị thẩm mỹ cho chiếc ấm đun nước.', '{"wordId":"esthetic","ukIpa":"/iːsˈθetɪk/","usIpa":"/esˈθetɪk/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"Relating to beauty or the appreciation of beautiful things.","vi":"thuộc về thẩm mỹ; mang tính mỹ học"}],"examples":[{"en":"The curved wooden handle gives the kettle esthetic appeal.","vi":"Tay cầm bằng gỗ cong uốn lượn mang lại giá trị thẩm mỹ cho chiếc ấm đun nước.","audioKind":"ex"},{"en":"Urban planners should balance the esthetic qualities of public spaces with accessibility and environmental sustainability.","vi":"Các nhà quy hoạch đô thị nên cân bằng giữa các đặc điểm thẩm mỹ của không gian công cộng với tính dễ tiếp cận và sự bền vững về môi trường.","audioKind":"ex2"}],"collocations":[{"en":"esthetic appeal","vi":"sức hút thẩm mỹ"},{"en":"esthetic value","vi":"giá trị thẩm mỹ"},{"en":"esthetic qualities","vi":"đặc tính thẩm mỹ"}],"wordFamily":["esthetically (adv.)","esthetics (n.)"],"synonyms":["aesthetic"],"antonyms":[],"tipVi":"Esthetic là biến thể chính tả của Mỹ; trong IELTS, từ aesthetic phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dramatize', 'en-c1-25', 'dramatize', '/ˈdræmətaɪz/', 'C1', 'chuyển thể thành kịch; làm cho kịch tính hóa; phóng đại', 'v.', 'drama (n.), dramatic (adj.), dramatization (n.), dramatically (adv.)', 'Trái nghĩa: downplay', 'Trong tiếng Anh Anh thường viết là dramatise; có thể mang nghĩa chuyển thể hoặc phóng đại vấn đề.', 'Our class will dramatize a short story next week.', NULL, 'Lớp chúng tôi sẽ chuyển thể một câu chuyện ngắn thành kịch vào tuần tới.', '{"wordId":"dramatize","ukIpa":"/ˈdræmətaɪz/","usIpa":"/ˈdræmətaɪz/","cefr":"C1","topic":"arts","senses":[{"pos":"v.","en":"to adapt a story or event for performance","vi":"chuyển thể thành kịch"},{"pos":"v.","en":"to present something as more exciting or serious than it is","vi":"làm cho kịch tính hóa; phóng đại"}],"examples":[{"en":"Our class will dramatize a short story next week.","vi":"Lớp chúng tôi sẽ chuyển thể một câu chuyện ngắn thành kịch vào tuần tới.","audioKind":"ex"},{"en":"Television producers often dramatize historical events to attract viewers, but this can blur the distinction between fact and fiction.","vi":"Các nhà sản xuất truyền hình thường kịch tính hóa các sự kiện lịch sử để thu hút người xem, nhưng điều này có thể làm mờ ranh giới giữa sự thật và hư cấu.","audioKind":"ex2"}],"collocations":[{"en":"dramatize a novel","vi":"dramatize a novel -> chuyển thể tiểu thuyết thành kịch"},{"en":"dramatize historical events","vi":"dramatize historical events -> tái hiện sự kiện lịch sử dưới dạng kịch"},{"en":"dramatize a situation","vi":"dramatize a situation -> phóng đại tình hình"}],"wordFamily":["drama (n.)","dramatic (adj.)","dramatization (n.)","dramatically (adv.)"],"synonyms":[],"antonyms":["downplay"],"tipVi":"Trong tiếng Anh Anh thường viết là dramatise; có thể mang nghĩa chuyển thể hoặc phóng đại vấn đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_auditorium', 'en-c1-25', 'auditorium', '/ˌɑːdɪˈtɔːriəm/', 'C1', 'thính phòng; hội trường lớn; khu vực khán giả ngồi trong nhà hát', 'n.', NULL, NULL, 'Có thể chỉ toàn bộ tòa nhà hội trường hoặc chỉ khu vực ghế ngồi của khán giả trong rạp.', 'Families filled the auditorium for the school concert.', NULL, 'Các gia đình đã lấp đầy hội trường để tham gia buổi hòa nhạc của trường.', '{"wordId":"auditorium","ukIpa":"/ˌɔːdɪˈtɔːriəm/","usIpa":"/ˌɑːdɪˈtɔːriəm/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"a large room or building for an audience","vi":"thính phòng; hội trường lớn"},{"pos":"n.","en":"the part of a theatre where the audience sits","vi":"khu vực khán giả ngồi trong nhà hát"}],"examples":[{"en":"Families filled the auditorium for the school concert.","vi":"Các gia đình đã lấp đầy hội trường để tham gia buổi hòa nhạc của trường.","audioKind":"ex"},{"en":"A modern auditorium allows the university to host public lectures and strengthen links with the local community.","vi":"Một hội trường hiện đại giúp trường đại học có thể tổ chức các buổi thuyết trình công khai và thắt chặt mối liên kết với cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"school auditorium","vi":"hội trường trường học"},{"en":"main auditorium","vi":"hội trường chính"},{"en":"packed auditorium","vi":"hội trường chật kín khán giả"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ toàn bộ tòa nhà hội trường hoặc chỉ khu vực ghế ngồi của khán giả trong rạp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monologue', 'en-c1-25', 'monologue', '/ˈmɑːnəlɔːɡ/', 'C1', 'độc thoại; bài độc thoại dài dòng; lời nói một chiều', 'n.', NULL, 'Đồng nghĩa: soliloquy · Trái nghĩa: dialogue', 'Bài độc thoại có thể hướng về phía khán giả, không nhất thiết là nhân vật tự nói một mình.', 'The actor practised her monologue alone in the kitchen.', NULL, 'Nữ diễn viên tự tập phần độc thoại một mình trong nhà bếp.', '{"wordId":"monologue","ukIpa":"/ˈmɒnəlɒɡ/","usIpa":"/ˈmɑːnəlɔːɡ/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"A long speech delivered by one character in a performance.","vi":"độc thoại"},{"pos":"n.","en":"A long speech by someone who gives others little chance to speak.","vi":"bài độc thoại dài dòng; lời nói một chiều"}],"examples":[{"en":"The actor practised her monologue alone in the kitchen.","vi":"Nữ diễn viên tự tập phần độc thoại một mình trong nhà bếp.","audioKind":"ex"},{"en":"A dramatic monologue can reveal a character''s inner conflicts more directly than dialogue between several speakers.","vi":"Một bài độc thoại kịch tính có thể bộc lộ nội tâm nhân vật trực tiếp hơn so với đoạn hội thoại giữa nhiều người nói.","audioKind":"ex2"}],"collocations":[{"en":"deliver a monologue","vi":"thể hiện một bài độc thoại"},{"en":"a dramatic monologue","vi":"bài độc thoại kịch"},{"en":"an interior monologue","vi":"độc thoại nội tâm"}],"wordFamily":[],"synonyms":["soliloquy"],"antonyms":["dialogue"],"tipVi":"Bài độc thoại có thể hướng về phía khán giả, không nhất thiết là nhân vật tự nói một mình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accompaniment', 'en-c1-25', 'accompaniment', '/əˈkʌmpənimənt/', 'C1', 'nhạc đệm; món ăn kèm; vật đi kèm', 'n.', 'accompany (v.), accompanist (n.)', NULL, 'Chỉ phần đệm nhạc hoặc vật đi kèm; "bạn đồng hành" phải dùng companion.', 'My sister sang while I played the piano accompaniment.', NULL, 'Chị tôi hát trong khi tôi đệm đàn piano.', '{"wordId":"accompaniment","ukIpa":"/əˈkʌmpənimənt/","usIpa":"/əˈkʌmpənimənt/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"Music played to support a singer or main instrument.","vi":"nhạc đệm"},{"pos":"n.","en":"Something served or provided together with something else.","vi":"món ăn kèm; vật đi kèm"}],"examples":[{"en":"My sister sang while I played the piano accompaniment.","vi":"Chị tôi hát trong khi tôi đệm đàn piano.","audioKind":"ex"},{"en":"Learning to provide musical accompaniment can help students develop listening skills and cooperate more effectively with others.","vi":"Học cách đệm đàn có thể giúp học sinh phát triển kỹ năng lắng nghe và hợp tác hiệu quả hơn với người khác.","audioKind":"ex2"}],"collocations":[{"en":"piano accompaniment","vi":"tiếng đàn piano đệm"},{"en":"musical accompaniment","vi":"nhạc đệm"},{"en":"an accompaniment to","vi":"vật đi kèm với"}],"wordFamily":["accompany (v.)","accompanist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ phần đệm nhạc hoặc vật đi kèm; \"bạn đồng hành\" phải dùng companion.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_iconic', 'en-c1-25', 'iconic', '/aɪˈkɑːnɪk/', 'C1', 'mang tính biểu tượng; có tính đại diện cao', 'adj.', 'icon (n.)', 'Đồng nghĩa: emblematic', 'Không chỉ đơn thuần là "nổi tiếng", từ này còn nhấn mạnh tính đại diện rõ nét và dễ nhận biết.', 'We stopped to photograph the city''s iconic stone bridge.', NULL, 'Chúng tôi dừng chân để chụp ảnh cây cầu đá mang tính biểu tượng của thành phố.', '{"wordId":"iconic","ukIpa":"/aɪˈkɒnɪk/","usIpa":"/aɪˈkɑːnɪk/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"widely recognised as representing a place, style, or idea","vi":"mang tính biểu tượng; có tính đại diện cao"}],"examples":[{"en":"We stopped to photograph the city''s iconic stone bridge.","vi":"Chúng tôi dừng chân để chụp ảnh cây cầu đá mang tính biểu tượng của thành phố.","audioKind":"ex"},{"en":"Preserving iconic buildings can strengthen cultural identity, although maintenance costs may place pressure on public budgets.","vi":"Việc bảo tồn các công trình mang tính biểu tượng có thể củng cố bản sắc văn hóa, mặc dù chi phí bảo trì có thể gây áp lực lên ngân sách công.","audioKind":"ex2"}],"collocations":[{"en":"iconic landmark","vi":"địa điểm mang tính biểu tượng"},{"en":"iconic design","vi":"thiết kế kinh điển"},{"en":"iconic image","vi":"hình ảnh mang tính biểu tượng"}],"wordFamily":["icon (n.)"],"synonyms":["emblematic"],"antonyms":[],"tipVi":"Không chỉ đơn thuần là \"nổi tiếng\", từ này còn nhấn mạnh tính đại diện rõ nét và dễ nhận biết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exquisite', 'en-c1-25', 'exquisite', '/ɪkˈskwɪzɪt/', 'C1', 'tinh xảo; tuyệt mỹ; cực kỳ mãnh liệt; cực kỳ nhạy bén', 'adj.', 'exquisitely (adv.), exquisiteness (n.)', 'Đồng nghĩa: beautiful, delicate', 'Thường dùng để mô tả nghệ thuật thủ công tinh xảo; khi đi với pain, nó diễn tả cảm giác đau đớn vô cùng mãnh liệt.', 'She keeps an exquisite porcelain bowl on the shelf.', NULL, 'Cô ấy đặt một chiếc bát sứ tinh xảo trên kệ.', '{"wordId":"exquisite","ukIpa":"/ɪkˈskwɪzɪt/","usIpa":"/ɪkˈskwɪzɪt/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"Extremely beautiful and carefully made.","vi":"tinh xảo; tuyệt mỹ"},{"pos":"adj.","en":"Describing a feeling or sensitivity of unusual intensity.","vi":"cực kỳ mãnh liệt; cực kỳ nhạy bén"}],"examples":[{"en":"She keeps an exquisite porcelain bowl on the shelf.","vi":"Cô ấy đặt một chiếc bát sứ tinh xảo trên kệ.","audioKind":"ex"},{"en":"Museums preserve exquisite examples of traditional craftsmanship, allowing future generations to appreciate their cultural and artistic value.","vi":"Các bảo tàng bảo tồn những tác phẩm thủ công truyền thống tinh xảo, giúp thế hệ mai sau trân trọng giá trị văn hóa và nghệ thuật của chúng.","audioKind":"ex2"}],"collocations":[{"en":"exquisite craftsmanship","vi":"tay nghề thủ công tinh xảo"},{"en":"exquisite beauty","vi":"vẻ đẹp tuyệt mỹ"},{"en":"exquisite detail","vi":"chi tiết tinh xảo"},{"en":"exquisite pain","vi":"cảm giác đau đớn dữ dội"}],"wordFamily":["exquisitely (adv.)","exquisiteness (n.)"],"synonyms":["beautiful","delicate"],"antonyms":[],"tipVi":"Thường dùng để mô tả nghệ thuật thủ công tinh xảo; khi đi với pain, nó diễn tả cảm giác đau đớn vô cùng mãnh liệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prose', 'en-c1-25', 'prose', '/proʊz/', 'C1', 'văn xuôi', 'n.', NULL, 'Trái nghĩa: verse', 'Không đếm được; không giới hạn ở văn học mà còn bao gồm tiểu thuyết và các dạng văn bản không phải thơ ca khác.', 'Her clear prose makes this book easy to enjoy.', NULL, 'Văn phong trong trẻo của cô ấy làm cho cuốn sách này trở nên dễ đọc và thú vị.', '{"wordId":"prose","ukIpa":"/prəʊz/","usIpa":"/proʊz/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"Ordinary written language, rather than poetry","vi":"văn xuôi"}],"examples":[{"en":"Her clear prose makes this book easy to enjoy.","vi":"Văn phong trong trẻo của cô ấy làm cho cuốn sách này trở nên dễ đọc và thú vị.","audioKind":"ex"},{"en":"Reading well-crafted prose can help students develop a wider vocabulary and express complex ideas more clearly.","vi":"Đọc các tác phẩm văn xuôi được trau chuốt kỹ lưỡng có thể giúp học sinh phát triển vốn từ vựng phong phú hơn và diễn đạt các ý tưởng phức tạp một cách rõ ràng hơn.","audioKind":"ex2"}],"collocations":[{"en":"in prose","vi":"bằng văn xuôi"},{"en":"clear prose","vi":"văn phong mạch lạc"},{"en":"prose fiction","vi":"tiểu thuyết văn xuôi"},{"en":"a prose poem","vi":"thơ văn xuôi"}],"wordFamily":[],"synonyms":[],"antonyms":["verse"],"tipVi":"Không đếm được; không giới hạn ở văn học mà còn bao gồm tiểu thuyết và các dạng văn bản không phải thơ ca khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gaudy', 'en-c1-25', 'gaudy', '/ˈɡɔːdi/', 'C1', 'sặc sỡ; lòe loẹt; diêm dúa', 'adj.', 'gaudily (adv.), gaudiness (n.)', 'Đồng nghĩa: garish, showy · Trái nghĩa: understated, tasteful', 'Mang ý nghĩa tiêu cực, chỉ màu sắc hoặc đồ trang trí quá lố, chứ không chỉ đơn thuần là tươi sáng.', 'He wore a gaudy jacket covered in shiny sequins.', NULL, 'Anh ấy mặc một chiếc áo khoác sặc sỡ đính đầy kim sa lấp lánh.', '{"wordId":"gaudy","ukIpa":"/ˈɡɔːdi/","usIpa":"/ˈɡɔːdi/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"Too brightly coloured or heavily decorated to look attractive.","vi":"sặc sỡ; lòe loẹt; diêm dúa"}],"examples":[{"en":"He wore a gaudy jacket covered in shiny sequins.","vi":"Anh ấy mặc một chiếc áo khoác sặc sỡ đính đầy kim sa lấp lánh.","audioKind":"ex"},{"en":"Some residents argue that gaudy decorations in historic districts undermine the visual character of traditional buildings.","vi":"Một số cư dân lập luận rằng những trang trí lòe loẹt trong các khu phố cổ làm suy giảm phong cách trực quan của các kiến trúc truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"gaudy colours","vi":"màu sắc sặc sỡ"},{"en":"gaudy decorations","vi":"trang trí lòe loẹt"},{"en":"gaudy jewellery","vi":"trang sức diêm dúa"}],"wordFamily":["gaudily (adv.)","gaudiness (n.)"],"synonyms":["garish","showy"],"antonyms":["understated","tasteful"],"tipVi":"Mang ý nghĩa tiêu cực, chỉ màu sắc hoặc đồ trang trí quá lố, chứ không chỉ đơn thuần là tươi sáng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prolific', 'en-c1-25', 'prolific', '/prəˈlɪfɪk/', 'C1', 'sản xuất ra nhiều tác phẩm, kết quả hoặc thành tựu; đa sản, sung mãn; sinh sản nhiều; sai hoa, nhiều quả', 'adj.', 'prolifically (adv.)', 'Đồng nghĩa: productive · Trái nghĩa: unproductive', 'Nhấn mạnh sản lượng lớn, không có nghĩa là chất lượng tác phẩm lúc nào cũng cao.', 'My aunt is a prolific painter with two studios.', NULL, 'Cô tôi là một họa sĩ đa sản với hai phòng tranh.', '{"wordId":"prolific","ukIpa":"/prəˈlɪfɪk/","usIpa":"/prəˈlɪfɪk/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"Producing many works, results or achievements.","vi":"sản xuất ra nhiều tác phẩm, kết quả hoặc thành tựu; đa sản, sung mãn"},{"pos":"adj.","en":"Producing many young, flowers, fruits or seeds.","vi":"sinh sản nhiều; sai hoa, nhiều quả"}],"examples":[{"en":"My aunt is a prolific painter with two studios.","vi":"Cô tôi là một họa sĩ đa sản với hai phòng tranh.","audioKind":"ex"},{"en":"Prolific researchers can contribute substantially to scientific progress, but publication quantity should not outweigh quality.","vi":"Những nhà nghiên cứu có năng suất cao có thể đóng góp đáng kể cho sự tiến bộ khoa học, nhưng số lượng công bố không nên lấn át chất lượng.","audioKind":"ex2"}],"collocations":[{"en":"a prolific writer","vi":"nhà văn đa sản"},{"en":"a prolific artist","vi":"nghệ sĩ đa sản"},{"en":"a prolific goalscorer","vi":"cầu thủ ghi bàn hiệu suất cao"},{"en":"a prolific breeder","vi":"động vật có khả năng sinh sản cao"}],"wordFamily":["prolifically (adv.)"],"synonyms":["productive"],"antonyms":["unproductive"],"tipVi":"Nhấn mạnh sản lượng lớn, không có nghĩa là chất lượng tác phẩm lúc nào cũng cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acclaim', 'en-c1-25', 'acclaim', '/əˈkleɪm/', 'C1', 'sự ca ngợi; tiếngvang; ca ngợi; tán dương', 'n.', 'acclaimed (adj.), acclamation (n.)', 'Đồng nghĩa: praise, applause · Trái nghĩa: criticism', 'Danh từ thường không đếm được; động từ thường dùng be acclaimed as được ca ngợi là.', 'Her first film won acclaim at the local festival.', NULL, 'Bộ phim đầu tay của cô ấy đã giành được nhiều lời ca ngợi tại liên hoan phim địa phương.', '{"wordId":"acclaim","ukIpa":"/əˈkleɪm/","usIpa":"/əˈkleɪm/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"strong public praise for someone or something","vi":"sự ca ngợi; tiếngvang"},{"pos":"v.","en":"to praise someone or something publicly and enthusiastically","vi":"ca ngợi; tán dương"}],"examples":[{"en":"Her first film won acclaim at the local festival.","vi":"Bộ phim đầu tay của cô ấy đã giành được nhiều lời ca ngợi tại liên hoan phim địa phương.","audioKind":"ex"},{"en":"The new public library has received widespread acclaim for its accessible design and sustainable construction.","vi":"Thư viện công cộng mới đã nhận được sự ca ngợi rộng rãi nhờ thiết kế dễ tiếp cận và cấu trúc bền vững.","audioKind":"ex2"}],"collocations":[{"en":"critical acclaim","vi":"được giới phê bình ca ngợi"},{"en":"widespread acclaim","vi":"sự ca ngợi rộng rãi"},{"en":"receive acclaim","vi":"nhận được sự ca ngợi"},{"en":"be acclaimed as","vi":"được ca ngợi là"}],"wordFamily":["acclaimed (adj.)","acclamation (n.)"],"synonyms":["praise","applause"],"antonyms":["criticism"],"tipVi":"Danh từ thường không đếm được; động từ thường dùng be acclaimed as được ca ngợi là.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adorn', 'en-c1-25', 'adorn', '/əˈdɔːrn/', 'C1', 'trang trí; làm cho đẹp thêm', 'v.', 'adornment (n.), adorned (adj.), unadorned (adj.)', 'Đồng nghĩa: decorate, embellish', 'Dùng adorn A with B để chỉ "dùng B để trang trí A".', 'Fresh flowers adorned every table at the family celebration.', NULL, 'Những bông hoa tươi tô điểm cho mọi chiếc bàn trong buổi lễ kỷ niệm của gia đình.', '{"wordId":"adorn","ukIpa":"/əˈdɔːn/","usIpa":"/əˈdɔːrn/","cefr":"C1","topic":"arts","senses":[{"pos":"v.","en":"To make something more attractive by decorating it.","vi":"trang trí; làm cho đẹp thêm"}],"examples":[{"en":"Fresh flowers adorned every table at the family celebration.","vi":"Những bông hoa tươi tô điểm cho mọi chiếc bàn trong buổi lễ kỷ niệm của gia đình.","audioKind":"ex"},{"en":"Public artworks adorn many urban spaces, making neighbourhoods more attractive and encouraging residents to explore their surroundings.","vi":"Các tác phẩm nghệ thuật công cộng trang hoàng cho nhiều không gian đô thị, làm cho các khu2 phố trở nên hấp dẫn hơn và khuyến khích cư dân khám phá môi trường xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"adorn something with flowers","vi":"trang trí cái gì bằng hoa"},{"en":"be adorned with","vi":"được trang trí bằng"},{"en":"adorn the walls","vi":"trang trí các bức tường"}],"wordFamily":["adornment (n.)","adorned (adj.)","unadorned (adj.)"],"synonyms":["decorate","embellish"],"antonyms":[],"tipVi":"Dùng adorn A with B để chỉ \"dùng B để trang trí A\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adornment', 'en-c1-25', 'adornment', '/əˈdɔːrnmənt/', 'C1', 'vật trang trí; đồ trang sức; sự trang trí; sự làm đẹp', 'n.', 'adorn (v.), adorned (adj.)', 'Đồng nghĩa: decoration, ornament', 'Chỉ dùng hình thức đếm được khi chỉ vật trang trí cụ thể; dùng hình thức không đếm được khi chỉ hành động trang trí hoặc tổng thể việc trang trí.', 'A silver brooch was her dress''s only adornment.', NULL, 'Một chiếc trâm bạc là vật trang trí duy nhất trên chiếc váy của cô ấy.', '{"wordId":"adornment","ukIpa":"/əˈdɔːnmənt/","usIpa":"/əˈdɔːrnmənt/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"something worn or added to make something more attractive","vi":"vật trang trí; đồ trang sức"},{"pos":"n.","en":"the act or practice of making something more attractive","vi":"sự trang trí; sự làm đẹp"}],"examples":[{"en":"A silver brooch was her dress''s only adornment.","vi":"Một chiếc trâm bạc là vật trang trí duy nhất trên chiếc váy của cô ấy.","audioKind":"ex"},{"en":"Traditional jewellery often serves as personal adornment while also expressing cultural identity and social belonging.","vi":"Trang sức truyền thống thường vừa dùng làm đồ trang trí cá nhân vừa thể hiện bản sắc văn hóa và sự thuộc về cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"personal adornment","vi":"đồ trang sức cá nhân"},{"en":"simple adornment","vi":"vật trang trí đơn giản"},{"en":"without adornment","vi":"không có đồ trang trí"}],"wordFamily":["adorn (v.)","adorned (adj.)"],"synonyms":["decoration","ornament"],"antonyms":[],"tipVi":"Chỉ dùng hình thức đếm được khi chỉ vật trang trí cụ thể; dùng hình thức không đếm được khi chỉ hành động trang trí hoặc tổng thể việc trang trí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recital', 'en-c1-25', 'recital', '/rɪˈsaɪtəl/', 'C1', 'buổi biểu diễn độc tấu; buổi biểu diễn hòa nhạc nhỏ; bài tường thuật chi tiết; sự kể lại tỉ mỉ', 'n.', 'recite (v.), recitation (n.)', NULL, 'Trong ngữ cảnh âm nhạc, từ này thường chỉ biểu diễn độc tấu hoặc đơn ca, không đồng nghĩa với đại nhạc hội.', 'Her first piano recital drew a small but enthusiastic audience.', NULL, 'Buổi độc tấu piano đầu tiên của cô ấy đã thu hút được một lượng khán giả không lớn nhưng vô cùng hào hứng.', '{"wordId":"recital","ukIpa":"/rɪˈsaɪtəl/","usIpa":"/rɪˈsaɪtəl/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"A musical performance given by one person or a small group.","vi":"buổi biểu diễn độc tấu; buổi biểu diễn hòa nhạc nhỏ"},{"pos":"n.","en":"A spoken account describing a series of facts or events.","vi":"bài tường thuật chi tiết; sự kể lại tỉ mỉ"}],"examples":[{"en":"Her first piano recital drew a small but enthusiastic audience.","vi":"Buổi độc tấu piano đầu tiên của cô ấy đã thu hút được một lượng khán giả không lớn nhưng vô cùng hào hứng.","audioKind":"ex"},{"en":"Regular opportunities to give a recital can help music students develop confidence and improve their performance skills.","vi":"Những cơ hội thường xuyên được biểu diễn độc tấu có thể giúp sinh viên âm nhạc xây dựng sự tự tin và nâng cao kỹ năng trình diễn của họ.","audioKind":"ex2"}],"collocations":[{"en":"a piano recital","vi":"buổi biểu diễn piano độc tấu"},{"en":"give a recital","vi":"tổ chức một buổi độc tấu"},{"en":"a recital of facts","vi":"sự liệt kê các sự thật"}],"wordFamily":["recite (v.)","recitation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh âm nhạc, từ này thường chỉ biểu diễn độc tấu hoặc đơn ca, không đồng nghĩa với đại nhạc hội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vocalist', 'en-c1-25', 'vocalist', '/ˈvoʊkəlɪst/', 'C1', 'ca sĩ; giọng ca chính', 'n.', 'vocal (adj.), vocals (n.), vocalise (v.)', 'Đồng nghĩa: singer', 'Thường chỉ ca sĩ trong một ban nhạc; lead vocalist có nghĩa là giọng ca chính.', 'The band''s vocalist sang softly while the guitarist played.', NULL, 'Ca sĩ của ban nhạc hát nhẹ nhàng trong khi nghệ sĩ guitar biểu diễn.', '{"wordId":"vocalist","ukIpa":"/ˈvəʊkəlɪst/","usIpa":"/ˈvoʊkəlɪst/","cefr":"C1","topic":"arts","senses":[{"pos":"n.","en":"A singer, especially one performing with a musical group.","vi":"ca sĩ; giọng ca chính"}],"examples":[{"en":"The band''s vocalist sang softly while the guitarist played.","vi":"Ca sĩ của ban nhạc hát nhẹ nhàng trong khi nghệ sĩ guitar biểu diễn.","audioKind":"ex"},{"en":"A skilled vocalist can help traditional music reach younger audiences without losing its distinctive cultural character.","vi":"Một ca sĩ giàu kỹ thuật có thể giúp âm nhạc truyền thống tiếp cận khán giả trẻ tuổi mà vẫn không làm mất đi nét đặc trưng văn hóa riêng biệt.","audioKind":"ex2"}],"collocations":[{"en":"lead vocalist","vi":"ca sĩ hát chính"},{"en":"backing vocalist","vi":"ca sĩ hát bè"},{"en":"jazz vocalist","vi":"ca sĩ nhạc jazz"}],"wordFamily":["vocal (adj.)","vocals (n.)","vocalise (v.)"],"synonyms":["singer"],"antonyms":[],"tipVi":"Thường chỉ ca sĩ trong một ban nhạc; lead vocalist có nghĩa là giọng ca chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aesthetic', 'en-c1-25', 'aesthetic', '/esˈθetɪk/', 'C1', 'thuộc về thẩm mỹ; có tính thẩm mỹ; phong cách thẩm mỹ; quan điểm thẩm mỹ', 'adj.', 'aesthetics (n.), aesthetically (adv.)', NULL, 'aesthetic là tính từ chỉ tính thẩm mỹ; aesthetics thường chỉ danh từ môn mỹ học hoặc hệ thống thẩm mỹ.', 'The wooden shelves give this room greater aesthetic appeal.', NULL, 'Những chiếc kệ bằng gỗ mang lại sức hút thẩm mỹ lớn hơn cho căn phòng này.', '{"wordId":"aesthetic","ukIpa":"/iːsˈθetɪk/","usIpa":"/esˈθetɪk/","cefr":"C1","topic":"arts","senses":[{"pos":"adj.","en":"Relating to beauty or the appreciation of beautiful things.","vi":"thuộc về thẩm mỹ; có tính thẩm mỹ"},{"pos":"n.","en":"A particular style or set of ideas about beauty.","vi":"phong cách thẩm mỹ; quan điểm thẩm mỹ"}],"examples":[{"en":"The wooden shelves give this room greater aesthetic appeal.","vi":"Những chiếc kệ bằng gỗ mang lại sức hút thẩm mỹ lớn hơn cho căn phòng này.","audioKind":"ex"},{"en":"Urban planners should consider both the practical function and aesthetic quality of public spaces.","vi":"Các nhà quy hoạch đô thị nên cân nhắc cả chức năng thực tế lẫn chất lượng thẩm mỹ của các không gian công cộng.","audioKind":"ex2"}],"collocations":[{"en":"aesthetic appeal","vi":"sức hút thẩm mỹ"},{"en":"aesthetic value","vi":"giá trị thẩm mỹ"},{"en":"aesthetic considerations","vi":"các cân nhắc về mặt thẩm mỹ"}],"wordFamily":["aesthetics (n.)","aesthetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"aesthetic là tính từ chỉ tính thẩm mỹ; aesthetics thường chỉ danh từ môn mỹ học hoặc hệ thống thẩm mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_25_1', 'en-c1-25', 'Cách dùng “adornment” (n.) — vật trang trí; đồ trang sức', 'personal adornment  ·  simple adornment  ·  without adornment', 'Chỉ dùng hình thức đếm được khi chỉ vật trang trí cụ thể; dùng hình thức không đếm được khi chỉ hành động trang trí hoặc tổng thể việc trang trí.', 'Họ từ (Word Family): adorn (v.), adorned (adj.) | Đồng nghĩa: decoration, ornament', '[{"hanzi":"A silver brooch was her dress''s only adornment.","pinyin":"","meaning":"Một chiếc trâm bạc là vật trang trí duy nhất trên chiếc váy của cô ấy."},{"hanzi":"Traditional jewellery often serves as personal adornment while also expressing cultural identity and social belonging.","pinyin":"","meaning":"Trang sức truyền thống thường vừa dùng làm đồ trang trí cá nhân vừa thể hiện bản sắc văn hóa và sự thuộc về cộng đồng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_25_2', 'en-c1-25', 'Cách dùng “duet” (n.) — bản song ca; khúc hát/khúc nhạc đôi cho hai người biểu diễn', 'sing a duet  ·  a piano duet  ·  perform a duet', 'Duet chỉ tác phẩm hoặc phần trình diễn dành cho hai người hát hoặc chơi nhạc, không dùng để chỉ ban nhạc gồm hai thành viên.', NULL, '[{"hanzi":"The sisters sang a beautiful duet at the concert.","pinyin":"","meaning":"Hai chị em đã hát một bài song ca tuyệt đẹp tại buổi hòa nhạc."},{"hanzi":"Performing a duet encourages music students to listen carefully and coordinate their timing with another musician.","pinyin":"","meaning":"Việc biểu diễn một bản song ca khuyến khích sinh viên âm nhạc lắng nghe cẩn thận và phối hợp nhịp nhàng với một nhạc sĩ khác."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_25_3', 'en-c1-25', 'Cách dùng “antagonist” (n.) — đối thủ, kẻ địch', 'a formidable antagonist  ·  the main antagonist  ·  a political antagonist', 'Nhân vật đối đầu (antagonist) trong cốt truyện đứng ở phía đối lập với nhân vật chính, không nhất thiết phải là kẻ xấu.', 'Họ từ (Word Family): antagonism (n.), antagonistic (adj.), antagonise (v.) | Đồng nghĩa: opponent, adversary · Trái nghĩa: ally', '[{"hanzi":"The detective finally faced her antagonist in the empty theatre.","pinyin":"","meaning":"Nữ thám tử cuối cùng cũng đối mặt với kẻ đối đầu của mình trong nhà hát trống trải."},{"hanzi":"In many novels, the antagonist challenges the central character''s values rather than simply threatening their physical safety.","pinyin":"","meaning":"Trong nhiều tiểu thuyết, nhân vật phản diện thách thức các giá trị của nhân vật chính thay vì chỉ đơn thuần đe dọa sự an toàn thể xác của họ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_25_4', 'en-c1-25', 'Cách dùng “exquisite” (adj.) — tinh xảo; tuyệt mỹ', 'exquisite craftsmanship  ·  exquisite beauty  ·  exquisite detail', 'Thường dùng để mô tả nghệ thuật thủ công tinh xảo; khi đi với pain, nó diễn tả cảm giác đau đớn vô cùng mãnh liệt.', 'Họ từ (Word Family): exquisitely (adv.), exquisiteness (n.) | Đồng nghĩa: beautiful, delicate', '[{"hanzi":"She keeps an exquisite porcelain bowl on the shelf.","pinyin":"","meaning":"Cô ấy đặt một chiếc bát sứ tinh xảo trên kệ."},{"hanzi":"Museums preserve exquisite examples of traditional craftsmanship, allowing future generations to appreciate their cultural and artistic value.","pinyin":"","meaning":"Các bảo tàng bảo tồn những tác phẩm thủ công truyền thống tinh xảo, giúp thế hệ mai sau trân trọng giá trị văn hóa và nghệ thuật của chúng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_25_1', 'en-c1-25', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
