INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_1_2', 'ten_c1_25_1', 'embroidery', 'I practise embroidery by stitching flowers onto plain cushions.', 'I practise embroidery by stitching flowers onto plain cushions.', '/ɪmˈbrɔɪdəri/', 'Tôi tập thêu bằng cách thêu những bông hoa lên các chiếc gối trơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_1_3', 'ten_c1_25_1', 'renaissance', 'Our local theatre is enjoying a renaissance this summer.', 'Our local theatre is enjoying a renaissance this summer.', '/ˈrenəsɑːns/', 'Nhà hát địa phương của chúng tôi đang trải qua giai đoạn hồi sinh mạnh mẽ vào mùa hè này.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_1_4', 'ten_c1_25_1', 'asymmetric', 'The jacket has an asymmetric collar and deep pockets.', 'The jacket has an asymmetric collar and deep pockets.', '/ˌeɪsɪˈmetrɪk/', 'Chiếc áo khoác có phần cổ áo không đối xứng và các túi sâu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_1_5', 'ten_c1_25_1', 'cubism', 'We explored cubism by painting faces with overlapping geometric shapes.', 'We explored cubism by painting faces with overlapping geometric shapes.', '/ˈkjuːbɪzəm/', 'Chúng tôi đã tìm hiểu về chủ nghĩa lập thể bằng cách vẽ những khuôn mặt với các hình khối hình học chồng lên nhau.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_1_6', 'ten_c1_25_1', 'glamour', 'Her sparkling earrings added glamour to a simple outfit.', 'Her sparkling earrings added glamour to a simple outfit.', '/ˈɡlæmər/', 'Đôi bông tai lấp lánh của cô ấy đã tô điểm thêm vẻ lộng lẫy cho bộ trang phục giản dị.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_1_7', 'ten_c1_25_1', 'patron', 'A local patron paid for the young artist''s materials.', 'A local patron paid for the young artist''s materials.', '/ˈpeɪtrən/', 'Một nhà bảo trợ địa phương đã chi trả tiền vật liệu cho người nghệ sĩ trẻ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_1_8', 'ten_c1_25_1', 'antagonist', 'The detective finally faced her antagonist in the empty theatre.', 'The detective finally faced her antagonist in the empty theatre.', '/ænˈtæɡənɪst/', 'Nữ thám tử cuối cùng cũng đối mặt với kẻ đối đầu của mình trong nhà hát trống trải.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_25_1_1', 'en-c1-25', 'ten_c1_25_1', 'listening', 'listening', 'The sisters sang a beautiful duet at the concert.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những chiếc kệ bằng gỗ mang lại sức hút thẩm mỹ lớn hơn cho căn phòng này.","Hai chị em đã hát một bài song ca tuyệt đẹp tại buổi hòa nhạc.","Ca sĩ của ban nhạc hát nhẹ nhàng trong khi nghệ sĩ guitar biểu diễn.","Chúng tôi đã tìm hiểu về chủ nghĩa lập thể bằng cách vẽ những khuôn mặt với các hình khối hình học chồng lên nhau."]'::jsonb, 1, 'The sisters sang a beautiful duet at the concert. → Hai chị em đã hát một bài song ca tuyệt đẹp tại buổi hòa nhạc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_25_1_2', 'en-c1-25', 'ten_c1_25_1', 'listening', 'listening', 'I practise embroidery by stitching flowers onto plain cushions.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhà hát địa phương của chúng tôi đang trải qua giai đoạn hồi sinh mạnh mẽ vào mùa hè này.","Tôi tập thêu bằng cách thêu những bông hoa lên các chiếc gối trơn.","Một chiếc trâm bạc là vật trang trí duy nhất trên chiếc váy của cô ấy.","Một nhà bảo trợ địa phương đã chi trả tiền vật liệu cho người nghệ sĩ trẻ."]'::jsonb, 1, 'I practise embroidery by stitching flowers onto plain cushions. → Tôi tập thêu bằng cách thêu những bông hoa lên các chiếc gối trơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_25_1_3', 'en-c1-25', 'ten_c1_25_1', 'listening', 'listening', 'Our local theatre is enjoying a renaissance this summer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những chiếc kệ bằng gỗ mang lại sức hút thẩm mỹ lớn hơn cho căn phòng này.","Nhà hát địa phương của chúng tôi đang trải qua giai đoạn hồi sinh mạnh mẽ vào mùa hè này.","Tay cầm bằng gỗ cong uốn lượn mang lại giá trị thẩm mỹ cho chiếc ấm đun nước.","Văn phong trong trẻo của cô ấy làm cho cuốn sách này trở nên dễ đọc và thú vị."]'::jsonb, 1, 'Our local theatre is enjoying a renaissance this summer. → Nhà hát địa phương của chúng tôi đang trải qua giai đoạn hồi sinh mạnh mẽ vào mùa hè này.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_25_2', 'en-c1-25', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_2_1', 'ten_c1_25_2', 'duet', 'Performing a duet encourages music students to listen carefully and coordinate their timing with another musician.', 'Performing a duet encourages music students to listen carefully and coordinate their timing with another musician.', '/duˈet/', 'Việc biểu diễn một bản song ca khuyến khích sinh viên âm nhạc lắng nghe cẩn thận và phối hợp nhịp nhàng với một nhạc sĩ khác.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_2_2', 'ten_c1_25_2', 'embroidery', 'Community embroidery workshops can preserve traditional skills while creating opportunities for different generations to learn together.', 'Community embroidery workshops can preserve traditional skills while creating opportunities for different generations to learn together.', '/ɪmˈbrɔɪdəri/', 'Các buổi workshop thêu thùa tại cộng đồng có thể gìn giữ các kỹ năng truyền thống đồng thời tạo cơ hội cho các thế hệ khác nhau cùng học hỏi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_2_3', 'ten_c1_25_2', 'renaissance', 'Investment in public galleries could encourage a cultural renaissance in cities affected by industrial decline.', 'Investment in public galleries could encourage a cultural renaissance in cities affected by industrial decline.', '/ˈrenəsɑːns/', 'Việc đầu tư vào các phòng trưng bày công cộng có thể thúc đẩy một cuộc Phục hưng văn hóa tại các thành phố chịu ảnh hưởng bởi suy thoái công nghiệp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_2_4', 'ten_c1_25_2', 'asymmetric', 'Asymmetric access to market information can place small businesses at a disadvantage when negotiating with larger firms.', 'Asymmetric access to market information can place small businesses at a disadvantage when negotiating with larger firms.', '/ˌeɪsɪˈmetrɪk/', 'Việc tiếp cận thông tin thị trường không cân xứng có thể khiến các doanh nghiệp nhỏ gặp bất lợi khi đàm phán với các công ty lớn hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_2_5', 'ten_c1_25_2', 'cubism', 'Cubism challenged traditional artistic representation by presenting multiple viewpoints within a single image rather than imitating natural appearances.', 'Cubism challenged traditional artistic representation by presenting multiple viewpoints within a single image rather than imitating natural appearances.', '/ˈkjuːbɪzəm/', 'Chủ nghĩa lập thể thách thức cách thể hiện nghệ thuật truyền thống bằng cách trình bày nhiều góc nhìn trong một bức ảnh duy nhất thay vì bắt chước vẻ ngoài tự nhiên.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_25_2_6', 'ten_c1_25_2', 'glamour', 'The apparent glamour of careers in entertainment can obscure the financial insecurity many performers experience.', 'The apparent glamour of careers in entertainment can obscure the financial insecurity many performers experience.', '/ˈɡlæmər/', 'Sự hào nhoáng bề ngoài của các nghề nghiệp trong ngành giải trí có thể lu mờ sự bất ổn về tài chính mà nhiều nghệ sĩ phải trải qua.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
