INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_25_2_2', 'en-c1-25', 'ten_c1_25_2', 'listening', 'listening', 'Community embroidery workshops can preserve traditional skills while creating opportunities for different generations to learn together.', NULL, 'Trong câu vừa nghe, từ “embroidery” mang nghĩa nào sau đây?', '["nghệ thuật thêu thùa; nghề thêu","thuộc về hàng hải; thuộc về tàu thuyền","cơ bản; tiềm ẩn; ngầm","sự cung cấp; sự cấp phát"]'::jsonb, 0, '“embroidery” (/ɪmˈbrɔɪdəri/): nghệ thuật thêu thùa; nghề thêu. Câu đầy đủ: Community embroidery workshops can preserve traditional skills while creating opportunities for different generations to learn together.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_25_1', 'en-c1-25', 'The sisters sang a beautiful duet at the concert', 'Hai chị em đã hát một bài song ca tuyệt đẹp tại buổi hòa nhạc.', 'duet /duˈet/', '["sisters","the","at","The","duet","beautiful","a","sang","concert"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_25_2', 'en-c1-25', 'I practise embroidery by stitching flowers onto plain cushions', 'Tôi tập thêu bằng cách thêu những bông hoa lên các chiếc gối trơn.', 'embroidery /ɪmˈbrɔɪdəri/', '["cushions","I","plain","embroidery","stitching","practise","by","onto","flowers"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_25_3', 'en-c1-25', 'Our local theatre is enjoying a renaissance this summer', 'Nhà hát địa phương của chúng tôi đang trải qua giai đoạn hồi sinh mạnh mẽ vào mùa hè này.', 'renaissance /ˈrenəsɑːns/', '["a","summer","theatre","local","this","enjoying","is","renaissance","Our"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_25_4', 'en-c1-25', 'The jacket has an asymmetric collar and deep pockets', 'Chiếc áo khoác có phần cổ áo không đối xứng và các túi sâu.', 'asymmetric /ˌeɪsɪˈmetrɪk/', '["collar","jacket","pockets","deep","asymmetric","The","an","and","has"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_25_5', 'en-c1-25', 'We explored cubism by painting faces with overlapping geometric shapes', 'Chúng tôi đã tìm hiểu về chủ nghĩa lập thể bằng cách vẽ những khuôn mặt với các hình khối hình học chồng lên nhau.', 'cubism /ˈkjuːbɪzəm/', '["geometric","by","shapes","faces","explored","cubism","We","painting","overlapping","with"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_25_6', 'en-c1-25', 'Her sparkling earrings added glamour to a simple outfit', 'Đôi bông tai lấp lánh của cô ấy đã tô điểm thêm vẻ lộng lẫy cho bộ trang phục giản dị.', 'glamour /ˈɡlæmər/', '["outfit","a","Her","added","glamour","earrings","sparkling","simple","to"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_25_7', 'en-c1-25', 'A local patron paid for the young artist''s materials', 'Một nhà bảo trợ địa phương đã chi trả tiền vật liệu cho người nghệ sĩ trẻ.', 'patron /ˈpeɪtrən/', '["young","for","the","artist''s","paid","patron","local","materials","A"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_25_8', 'en-c1-25', 'The detective finally faced her antagonist in the empty theatre', 'Nữ thám tử cuối cùng cũng đối mặt với kẻ đối đầu của mình trong nhà hát trống trải.', 'antagonist /ænˈtæɡənɪst/', '["detective","in","faced","theatre","finally","The","the","empty","her","antagonist"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_25_9', 'en-c1-25', 'Her funny stories always animate our family dinners', 'Những câu chuyện hài hước của cô ấy luôn làm cho bữa ăn gia đình chúng tôi thêm phần sôi nổi.', 'animate /ˈænɪmeɪt/', '["animate","always","Her","our","stories","family","dinners","funny"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
