INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_1', 'en-c1-25', NULL, 'comprehensive_test', 'listening', 'duet', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bản song ca; khúc hát/khúc nhạc đôi cho hai người biểu diễn","siêu thanh, vượt tốc độ âm thanh","chưa quyết định; đang chờ giải quyết","thức giấc; đánh thức"]'::jsonb, 0, 'duet (/duˈet/) → bản song ca; khúc hát/khúc nhạc đôi cho hai người biểu diễn', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_2', 'en-c1-25', NULL, 'comprehensive_test', 'listening', 'I practise embroidery by stitching flowers onto plain cushions.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc áo khoác có phần cổ áo không đối xứng và các túi sâu.","Tôi tập thêu bằng cách thêu những bông hoa lên các chiếc gối trơn.","Nhà hát địa phương của chúng tôi đang trải qua giai đoạn hồi sinh mạnh mẽ vào mùa hè này.","Văn phong trong trẻo của cô ấy làm cho cuốn sách này trở nên dễ đọc và thú vị."]'::jsonb, 1, 'I practise embroidery by stitching flowers onto plain cushions. → Tôi tập thêu bằng cách thêu những bông hoa lên các chiếc gối trơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_3', 'en-c1-25', NULL, 'comprehensive_test', 'listening', 'renaissance', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đào, khoét, khai đào","sự bảo dưỡng; việc duy trì; chi phí bảo trì","sự hồi sinh; thời kỳ phục hưng","lủng lẳng; treo lơ lửng"]'::jsonb, 2, 'renaissance (/ˈrenəsɑːns/) → sự hồi sinh; thời kỳ phục hưng; thời kỳ Văn hóa Phục hưng châu Âu', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_4', 'en-c1-25', NULL, 'comprehensive_test', 'listening', 'The jacket has an asymmetric collar and deep pockets.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ca sĩ của ban nhạc hát nhẹ nhàng trong khi nghệ sĩ guitar biểu diễn.","Bộ phim đầu tay của cô ấy đã giành được nhiều lời ca ngợi tại liên hoan phim địa phương.","Hai chị em đã hát một bài song ca tuyệt đẹp tại buổi hòa nhạc.","Chiếc áo khoác có phần cổ áo không đối xứng và các túi sâu."]'::jsonb, 3, 'The jacket has an asymmetric collar and deep pockets. → Chiếc áo khoác có phần cổ áo không đối xứng và các túi sâu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_5', 'en-c1-25', NULL, 'comprehensive_test', 'listening', 'cubism', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quân đoàn; binh chủng","nấm","chủ nghĩa lập thể","làm cho phổ biến; truyền bá; phổ biến"]'::jsonb, 2, 'cubism (/ˈkjuːbɪzəm/) → chủ nghĩa lập thể', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_6', 'en-c1-25', NULL, 'comprehensive_test', 'listening', 'Her sparkling earrings added glamour to a simple outfit.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chị tôi hát trong khi tôi đệm đàn piano.","Đôi bông tai lấp lánh của cô ấy đã tô điểm thêm vẻ lộng lẫy cho bộ trang phục giản dị.","Nữ thám tử cuối cùng cũng đối mặt với kẻ đối đầu của mình trong nhà hát trống trải.","Hai chị em đã hát một bài song ca tuyệt đẹp tại buổi hòa nhạc."]'::jsonb, 1, 'Her sparkling earrings added glamour to a simple outfit. → Đôi bông tai lấp lánh của cô ấy đã tô điểm thêm vẻ lộng lẫy cho bộ trang phục giản dị.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_7', 'en-c1-25', NULL, 'comprehensive_test', 'listening', 'patron', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà bảo trợ; người hỗ trợ tài chính","khéo léo; nhanh nhẹn và chuẩn xác","khoe khoang; phô trương","toàn bộ; tính toàn vẹn"]'::jsonb, 0, 'patron (/ˈpeɪtrən/) → nhà bảo trợ; người hỗ trợ tài chính; khách hàng; khách quen', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_8', 'en-c1-25', NULL, 'comprehensive_test', 'listening', 'The detective finally faced her antagonist in the empty theatre.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một chiếc trâm bạc là vật trang trí duy nhất trên chiếc váy của cô ấy.","Nữ thám tử cuối cùng cũng đối mặt với kẻ đối đầu của mình trong nhà hát trống trải.","Những câu chuyện hài hước của cô ấy luôn làm cho bữa ăn gia đình chúng tôi thêm phần sôi nổi.","Cô tôi là một họa sĩ đa sản với hai phòng tranh."]'::jsonb, 1, 'The detective finally faced her antagonist in the empty theatre. → Nữ thám tử cuối cùng cũng đối mặt với kẻ đối đầu của mình trong nhà hát trống trải.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_9', 'en-c1-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An art style showing subjects through geometric shapes and multiple viewpoints.”?', '["adornment","patron","cubism","gaudy"]'::jsonb, 2, 'cubism (/ˈkjuːbɪzəm/) → chủ nghĩa lập thể', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_10', 'en-c1-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An exciting attractiveness associated with beauty, wealth, or fame.”?', '["glamour","embroidery","esthetic","monologue"]'::jsonb, 0, 'glamour (/ˈɡlæmər/) → sức hút quyến rũ; vẻ hào nhoáng, lộng lẫy', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_11', 'en-c1-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Someone who supports an artist, organisation, or activity, often financially.”?', '["accompaniment","embroidery","vocalist","patron"]'::jsonb, 3, 'patron (/ˈpeɪtrən/) → nhà bảo trợ; người hỗ trợ tài chính', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_12', 'en-c1-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Someone who strongly opposes another person.”?', '["monologue","antagonist","acclaim","exquisite"]'::jsonb, 1, 'antagonist (/ænˈtæɡənɪst/) → đối thủ, kẻ địch', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_13', 'en-c1-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To make someone or something more lively or engaging”?', '["cubism","gaudy","animate","exquisite"]'::jsonb, 2, 'animate (/ˈænɪmeɪt/) → làm cho sinh động; làm cho sôi nổi', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
