INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_18', 'en-c1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Performing a duet encourages music students to listen carefully and coordinate their timing with another musician.', 'Dựa vào câu trên, từ “duet” có nghĩa phù hợp nhất là gì?', '["tối ưu; tốt nhất; thuận lợi nhất","bản song ca; khúc hát/khúc nhạc đôi cho hai người biểu diễn","sự cạnh tranh; sự ganh đua","vô lý; không cần thiết; bất lịch sự"]'::jsonb, 1, 'duet: bản song ca; khúc hát/khúc nhạc đôi cho hai người biểu diễn. Dịch cả câu: Việc biểu diễn một bản song ca khuyến khích sinh viên âm nhạc lắng nghe cẩn thận và phối hợp nhịp nhàng với một nhạc sĩ khác.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_19', 'en-c1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Community embroidery workshops can preserve traditional skills while creating opportunities for different generations to learn together.', 'Dựa vào câu trên, từ “embroidery” có nghĩa phù hợp nhất là gì?', '["thích hợp; phải phép; xứng đáng","phạm vi; chuỗi (ý tưởng, phẩm chất, khả năng)","sự mạch lạc; tính liên kết; tính logic","nghệ thuật thêu thùa; nghề thêu"]'::jsonb, 3, 'embroidery: nghệ thuật thêu thùa; nghề thêu; hàng thêu; họa tiết thêu. Dịch cả câu: Các buổi workshop thêu thùa tại cộng đồng có thể gìn giữ các kỹ năng truyền thống đồng thời tạo cơ hội cho các thế hệ khác nhau cùng học hỏi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_20', 'en-c1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in public galleries could encourage a cultural renaissance in cities affected by industrial decline.', 'Dựa vào câu trên, từ “renaissance” có nghĩa phù hợp nhất là gì?', '["cõng; sự cõng trên lưng","sự hồi sinh; thời kỳ phục hưng","đồng thời; song song (xảy ra hoặc tồn tại cùng một lúc)","xứng đáng; đáng"]'::jsonb, 1, 'renaissance: sự hồi sinh; thời kỳ phục hưng; thời kỳ Văn hóa Phục hưng châu Âu. Dịch cả câu: Việc đầu tư vào các phòng trưng bày công cộng có thể thúc đẩy một cuộc Phục hưng văn hóa tại các thành phố chịu ảnh hưởng bởi suy thoái công nghiệp.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_21', 'en-c1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Asymmetric access to market information can place small businesses at a disadvantage when negotiating with larger firms.', 'Dựa vào câu trên, từ “asymmetric” có nghĩa phù hợp nhất là gì?', '["sự sắp thẳng hàng; sự căn chỉnh đúng vị trí","không đối xứng","huyết tương","tiền thân; người đi trước"]'::jsonb, 1, 'asymmetric: không đối xứng; không đồng đều; mất cân đối. Dịch cả câu: Việc tiếp cận thông tin thị trường không cân xứng có thể khiến các doanh nghiệp nhỏ gặp bất lợi khi đàm phán với các công ty lớn hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_22', 'en-c1-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “buổi biểu diễn độc tấu; buổi biểu diễn hòa nhạc nhỏ”', '["astronomical","recital","exquisite","fanatic"]'::jsonb, 1, 'buổi biểu diễn độc tấu; buổi biểu diễn hòa nhạc nhỏ → recital (/rɪˈsaɪtəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_23', 'en-c1-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ca sĩ; giọng ca chính”', '["versatile","provoke","pore","vocalist"]'::jsonb, 3, 'ca sĩ; giọng ca chính → vocalist (/ˈvoʊkəlɪst/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_25_24', 'en-c1-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về thẩm mỹ; có tính thẩm mỹ”', '["mirage","calamity","gunpowder","aesthetic"]'::jsonb, 3, 'thuộc về thẩm mỹ; có tính thẩm mỹ → aesthetic (/esˈθetɪk/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-26', 'en', 'Bài 26: Tư duy & Nhận thức (1) - CEFR C1', 'CEFR C1', 'C1 · Tư duy', '26 từ vựng Tiếng Anh CEFR C1 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5026, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contemplation', 'en-c1-26', 'contemplation', '/ˌkɑːntəmˈpleɪʃən/', 'C1', 'sự trầm ngâm; sự suy ngẫm; sự cân nhắc; sự trăn trở', 'n.', 'contemplate (v.), contemplative (adj.)', 'Đồng nghĩa: reflection, meditation', 'Thường là danh từ không đếm được; nhấn mạnh sự suy nghĩ yên bình, không nhất thiết là sự dằn vặt hay đau khổ.', 'He sat by the lake in quiet contemplation.', NULL, 'Anh ấy ngồi bên hồ trong trạng thái tĩnh lặng suy ngẫm.', '{"wordId":"contemplation","ukIpa":"/ˌkɒntəmˈpleɪʃən/","usIpa":"/ˌkɑːntəmˈpleɪʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"the act of thinking deeply and quietly about something","vi":"sự trầm ngâm; sự suy ngẫm"},{"pos":"n.","en":"the act of considering a possible future action","vi":"sự cân nhắc; sự trăn trở"}],"examples":[{"en":"He sat by the lake in quiet contemplation.","vi":"Anh ấy ngồi bên hồ trong trạng thái tĩnh lặng suy ngẫm.","audioKind":"ex"},{"en":"Public gardens offer urban residents valuable opportunities for quiet contemplation away from the pressures of daily life.","vi":"Các khu vườn công cộng mang lại cho cư dân thành phố những cơ hội quý giá để tĩnh tâm suy ngẫm, tránh xa áp lực của cuộc sống thường nhật.","audioKind":"ex2"}],"collocations":[{"en":"quiet contemplation","vi":"trầm tư tĩnh lặng"},{"en":"deep contemplation","vi":"suy ngẫm sâu sắc"},{"en":"in contemplation","vi":"trong lúc trầm tư"}],"wordFamily":["contemplate (v.)","contemplative (adj.)"],"synonyms":["reflection","meditation"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; nhấn mạnh sự suy nghĩ yên bình, không nhất thiết là sự dằn vặt hay đau khổ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inherent', 'en-c1-26', 'inherent', '/ɪnˈhɪrənt/', 'C1', 'vốn có; bản chất; nội tại', 'adj.', 'inherently (adv.)', 'Đồng nghĩa: intrinsic, built-in · Trái nghĩa: extrinsic', 'Thường đi với giới từ in; nhấn mạnh bản chất sẵn có chứ không phải do trau dồi hay đạt được về sau.', 'Even simple home repairs come with some inherent risks.', NULL, 'Ngay cả những việc sửa chữa nhà cửa đơn giản cũng đi kèm với một số rủi ro vốn có.', '{"wordId":"inherent","ukIpa":"/ɪnˈhɪərənt/","usIpa":"/ɪnˈhɪrənt/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Existing as a natural or essential part of something.","vi":"vốn có; bản chất; nội tại"}],"examples":[{"en":"Even simple home repairs come with some inherent risks.","vi":"Ngay cả những việc sửa chữa nhà cửa đơn giản cũng đi kèm với một số rủi ro vốn có.","audioKind":"ex"},{"en":"Policymakers must recognise the inherent limitations of economic growth as a measure of social progress and wellbeing.","vi":"Các nhà hoạch định chính sách phải nhận thức rõ những hạn chế vốn có của việc sử dụng tăng trưởng kinh tế làm thước đo cho tiến bộ xã hội và hạnh phúc.","audioKind":"ex2"}],"collocations":[{"en":"inherent risks","vi":"rủi ro vốn có"},{"en":"inherent limitations","vi":"hạn chế vốn có"},{"en":"inherent in","vi":"vốn có trong"},{"en":"inherent value","vi":"giá trị nội tại"}],"wordFamily":["inherently (adv.)"],"synonyms":["intrinsic","built-in"],"antonyms":["extrinsic"],"tipVi":"Thường đi với giới từ in; nhấn mạnh bản chất sẵn có chứ không phải do trau dồi hay đạt được về sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_retrospect', 'en-c1-26', 'retrospect', '/ˈretrəspekt/', 'C1', 'sự nhìn lại quá khứ; hồi tưởng', 'n.', 'retrospective (adj.), retrospectively (adv.)', 'Đồng nghĩa: hindsight', 'Thường được dùng trong cụm từ cố định in retrospect, biểu thị việc suy ngẫm lại sự việc sau khi nó đã xảy ra.', 'In retrospect, packing extra socks was a brilliant idea.', NULL, 'Nhìn lại thì việc mang theo đôi tất thừa là một ý tưởng tuyệt vời.', '{"wordId":"retrospect","ukIpa":"/ˈretrəspekt/","usIpa":"/ˈretrəspekt/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"Consideration of past events, often with a changed understanding.","vi":"sự nhìn lại quá khứ; hồi tưởng"}],"examples":[{"en":"In retrospect, packing extra socks was a brilliant idea.","vi":"Nhìn lại thì việc mang theo đôi tất thừa là một ý tưởng tuyệt vời.","audioKind":"ex"},{"en":"In retrospect, investing earlier in public transport could have prevented many of the city''s current traffic problems.","vi":"Nhìn lại quãng thời gian trước đây, việc đầu tư sớm hơn vào giao thông công cộng đã có thể ngăn chặn nhiều vấn đề ùn tắc hiện tại của thành phố.","audioKind":"ex2"}],"collocations":[{"en":"in retrospect","vi":"nhìn lại thì"},{"en":"only in retrospect","vi":"chỉ khi nhìn lại mới thấy"}],"wordFamily":["retrospective (adj.)","retrospectively (adv.)"],"synonyms":["hindsight"],"antonyms":[],"tipVi":"Thường được dùng trong cụm từ cố định in retrospect, biểu thị việc suy ngẫm lại sự việc sau khi nó đã xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_implicit', 'en-c1-26', 'implicit', '/ɪmˈplɪsɪt/', 'C1', 'ngầm; ẩn ý; không nói ra; tiềm ẩn; gắn liền; hoàn toàn; tuyệt đối (thường dùng để chỉ sự tin tưởng)', 'adj.', 'implicitly (adv.)', 'Đồng nghĩa: unstated, implied · Trái nghĩa: explicit', 'implicit chỉ điều không nói rõ; còn explicit chỉ rõ ràng, rành mạch.', 'Her welcoming smile was an implicit invitation to join.', NULL, 'Nụ cười chào đón của cô ấy là lời mời gọi ngầm để chúng tôi cùng tham gia.', '{"wordId":"implicit","ukIpa":"/ɪmˈplɪsɪt/","usIpa":"/ɪmˈplɪsɪt/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Suggested or understood without being directly stated.","vi":"ngầm; ẩn ý; không nói ra"},{"pos":"adj.","en":"Present as a necessary part of something.","vi":"tiềm ẩn; gắn liền"},{"pos":"adj.","en":"Complete and without doubt, especially describing trust or confidence.","vi":"hoàn toàn; tuyệt đối (thường dùng để chỉ sự tin tưởng)"}],"examples":[{"en":"Her welcoming smile was an implicit invitation to join.","vi":"Nụ cười chào đón của cô ấy là lời mời gọi ngầm để chúng tôi cùng tham gia.","audioKind":"ex"},{"en":"Many workplaces have implicit expectations about overtime, which can make employees reluctant to leave on time.","vi":"Nhiều nơi làm việc có những kỳ vọng ngầm về việc làm thêm giờ, điều này có thể khiến nhân viên thấy miễn cưỡng khi rời đi đúng giờ.","audioKind":"ex2"}],"collocations":[{"en":"implicit agreement","vi":"sự đồng thuận ngầm"},{"en":"implicit in","vi":"tiềm ẩn trong..."},{"en":"implicit trust","vi":"sự tin tưởng tuyệt đối"},{"en":"implicit assumption","vi":"giả định ẩn"}],"wordFamily":["implicitly (adv.)"],"synonyms":["unstated","implied"],"antonyms":["explicit"],"tipVi":"implicit chỉ điều không nói rõ; còn explicit chỉ rõ ràng, rành mạch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_persistence', 'en-c1-26', 'persistence', '/pɚˈsɪstəns/', 'C1', 'sự kiên trì; tính kiên định; sự bền bỉ; sự tiếp diễn; sự kéo dài', 'n.', 'persist (v.), persistent (adj.), persistently (adv.)', 'Đồng nghĩa: perseverance, continuance', 'Có thể chỉ ý chí kiên định của con người hoặc sự tồn tại kéo dài của vấn đề, hiện tượng.', 'After weeks of practice, his persistence finally paid off.', NULL, 'Sau nhiều tuần tập luyện, sự kiên trì của anh ấy cuối cùng cũng được đền đáp.', '{"wordId":"persistence","ukIpa":"/pəˈsɪstəns/","usIpa":"/pɚˈsɪstəns/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"continued effort despite difficulties or delays","vi":"sự kiên trì; tính kiên định; sự bền bỉ"},{"pos":"n.","en":"the fact of continuing to exist over time","vi":"sự tiếp diễn; sự kéo dài"}],"examples":[{"en":"After weeks of practice, his persistence finally paid off.","vi":"Sau nhiều tuần tập luyện, sự kiên trì của anh ấy cuối cùng cũng được đền đáp.","audioKind":"ex"},{"en":"The persistence of poverty suggests that economic growth alone cannot guarantee better living conditions for every household.","vi":"Sự kéo dài của tình trạng nghèo đói cho thấy rằng chỉ riêng sự tăng trưởng kinh tế không thể đảm bảo điều kiện sống tốt hơn cho mọi hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"show persistence","vi":"thể hiện sự kiên trì"},{"en":"persistence pays off","vi":"kiên trì cuối cùng sẽ được đền đáp"},{"en":"the persistence of poverty","vi":"sự tiếp diễn của nghèo đói"}],"wordFamily":["persist (v.)","persistent (adj.)","persistently (adv.)"],"synonyms":["perseverance","continuance"],"antonyms":[],"tipVi":"Có thể chỉ ý chí kiên định của con người hoặc sự tồn tại kéo dài của vấn đề, hiện tượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pertinent', 'en-c1-26', 'pertinent', '/ˈpɝːtənənt/', 'C1', 'thích đáng; liên quan; sát với vấn đề', 'adj.', 'pertinence (n.), pertinently (adv.)', 'Đồng nghĩa: relevant, apposite · Trái nghĩa: irrelevant', 'Thường dùng pertinent to để chỉ sự liên quan đến vấn đề gì đó, mang văn phong trang trọng.', 'Lena asked a pertinent question about the repair costs.', NULL, 'Lena đã đặt một câu hỏi rất sát thực tế về chi phí sửa chữa.', '{"wordId":"pertinent","ukIpa":"/ˈpɜːtɪnənt/","usIpa":"/ˈpɝːtənənt/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"directly related to the matter being discussed","vi":"thích đáng; liên quan; sát với vấn đề"}],"examples":[{"en":"Lena asked a pertinent question about the repair costs.","vi":"Lena đã đặt một câu hỏi rất sát thực tế về chi phí sửa chữa.","audioKind":"ex"},{"en":"Evidence about local air quality is particularly pertinent to discussions of expanding public transport networks.","vi":"Bằng chứng về chất lượng không khí địa phương đặc biệt liên quan đến các cuộc thảo luận về việc mở rộng mạng lưới giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"pertinent question","vi":"câu hỏi sát vấn đề"},{"en":"pertinent information","vi":"thông tin liên quan"},{"en":"pertinent to","vi":"liên quan đến"}],"wordFamily":["pertinence (n.)","pertinently (adv.)"],"synonyms":["relevant","apposite"],"antonyms":["irrelevant"],"tipVi":"Thường dùng pertinent to để chỉ sự liên quan đến vấn đề gì đó, mang văn phong trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gullible', 'en-c1-26', 'gullible', '/ˈɡʌləbl/', 'C1', 'cả tin; dễ bị lừa', 'adj.', 'gullibility (n.)', 'Đồng nghĩa: credulous, naive · Trái nghĩa: sceptical', 'Mang sắc thái chê bai, nhấn mạnh việc dễ tin lời dối trá, không đồng nghĩa với tốt bụng.', 'I was gullible enough to believe his ridiculous story.', NULL, 'Tôi đã quá cả tin khi tin vào câu chuyện nực cười của anh ta.', '{"wordId":"gullible","ukIpa":"/ˈɡʌləbl/","usIpa":"/ˈɡʌləbl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Too willing to believe what others say, even when untrue","vi":"cả tin; dễ bị lừa"}],"examples":[{"en":"I was gullible enough to believe his ridiculous story.","vi":"Tôi đã quá cả tin khi tin vào câu chuyện nực cười của anh ta.","audioKind":"ex"},{"en":"Teaching media literacy can help gullible consumers recognise misleading advertisements and make better informed purchasing decisions.","vi":"Việc giáo dục kỹ năng đọc hiểu truyền thông có thể giúp người tiêu dùng dễ bị lừa nhận biết các quảng cáo gây hiểu lầm và đưa ra quyết định mua sắm sáng suốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"gullible consumers","vi":"người tiêu dùng dễ bị lừa"},{"en":"gullible enough to believe","vi":"cả tin đến mức tin rằng"},{"en":"seem gullible","vi":"tỏ ra cả tin"}],"wordFamily":["gullibility (n.)"],"synonyms":["credulous","naive"],"antonyms":["sceptical"],"tipVi":"Mang sắc thái chê bai, nhấn mạnh việc dễ tin lời dối trá, không đồng nghĩa với tốt bụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whereby', 'en-c1-26', 'whereby', '/werˈbaɪ/', 'C1', 'nhờ đó; theo đó', 'adv.', NULL, NULL, 'Trạng từ quan hệ trang trọng, thường đứng sau các từ như system, tương đương với by which.', 'We have an arrangement whereby we share the cooking.', NULL, 'Chúng tôi có một thỏa thuận theo đó chúng tôi chia sẻ việc nấu nướng.', '{"wordId":"whereby","ukIpa":"/weəˈbaɪ/","usIpa":"/werˈbaɪ/","cefr":"C1","topic":"thinking","senses":[{"pos":"adv.","en":"By which a particular result is achieved.","vi":"nhờ đó; theo đó"}],"examples":[{"en":"We have an arrangement whereby we share the cooking.","vi":"Chúng tôi có một thỏa thuận theo đó chúng tôi chia sẻ việc nấu nướng.","audioKind":"ex"},{"en":"Schools could introduce a system whereby older students provide academic support to younger pupils after lessons.","vi":"Các trường học có thể áp dụng một hệ thống trong đó học sinh lớn tuổi hỗ trợ học tập cho học sinh nhỏ tuổi hơn sau giờ học.","audioKind":"ex2"}],"collocations":[{"en":"a system whereby","vi":"một hệ thống nhờ đó"},{"en":"a process whereby","vi":"một quy trình theo đó"},{"en":"an arrangement whereby","vi":"một sự sắp xếp theo đó"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trạng từ quan hệ trang trọng, thường đứng sau các từ như system, tương đương với by which.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infer', 'en-c1-26', 'infer', '/ɪnˈfɝː/', 'C1', 'suy ra; luận ra', 'v.', 'inference (n.), inferential (adj.)', 'Đồng nghĩa: deduce, conclude', 'infer là việc người nghe/người đọc tự suy luận, còn imply là việc người nói/người viết ám chỉ.', 'From her muddy shoes, I inferred she had been gardening.', NULL, 'Từ đôi giày dính đầy bùn của cô ấy, tôi suy ra rằng cô ấy vừa làm vườn.', '{"wordId":"infer","ukIpa":"/ɪnˈfɜː/","usIpa":"/ɪnˈfɝː/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to reach a conclusion using evidence rather than direct statements","vi":"suy ra; luận ra"}],"examples":[{"en":"From her muddy shoes, I inferred she had been gardening.","vi":"Từ đôi giày dính đầy bùn của cô ấy, tôi suy ra rằng cô ấy vừa làm vườn.","audioKind":"ex"},{"en":"Researchers cannot infer that smaller classes improve learning without examining other factors affecting student performance.","vi":"Các nhà nghiên cứu không thể suy luận rằng quy mô lớp học nhỏ hơn giúp cải thiện kết quả học tập nếu không xem xét các yếu tố khác ảnh hưởng đến năng lực của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"infer from evidence","vi":"suy ra từ bằng chứng"},{"en":"infer that","vi":"suy luận rằng"},{"en":"reasonably infer","vi":"suy luận hợp lý"}],"wordFamily":["inference (n.)","inferential (adj.)"],"synonyms":["deduce","conclude"],"antonyms":[],"tipVi":"infer là việc người nghe/người đọc tự suy luận, còn imply là việc người nói/người viết ám chỉ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reminiscent', 'en-c1-26', 'reminiscent', '/ˌremɪˈnɪsənt/', 'C1', 'làm gợi nhớ đến; gợi lại', 'adj.', 'reminisce (v.), reminiscence (n.)', 'Đồng nghĩa: evocative', 'Đi kèm cấu trúc cố định be reminiscent of, giới từ đi theo không phải là about.', 'The soup''s flavour was reminiscent of my grandmother''s cooking.', NULL, 'Hương vị của món súp làm tôi nhớ đến bữa cơm do bà tôi nấu.', '{"wordId":"reminiscent","ukIpa":"/ˌremɪˈnɪsənt/","usIpa":"/ˌremɪˈnɪsənt/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Reminding you of something because of a similarity.","vi":"làm gợi nhớ đến; gợi lại"}],"examples":[{"en":"The soup''s flavour was reminiscent of my grandmother''s cooking.","vi":"Hương vị của món súp làm tôi nhớ đến bữa cơm do bà tôi nấu.","audioKind":"ex"},{"en":"The proposed station design is reminiscent of traditional architecture, helping the building blend into its historic surroundings.","vi":"Thiết kế nhà ga được đề xuất mang hơi hướng gợi nhớ đến kiến trúc truyền thống, giúp công trình hòa hợp với cảnh quan lịch sử xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"reminiscent of childhood","vi":"gợi nhớ về tuổi thơ"},{"en":"strongly reminiscent of","vi":"gợi liên tưởng mạnh mẽ đến"},{"en":"vaguely reminiscent of","vi":"thoáng gợi nhớ đến"}],"wordFamily":["reminisce (v.)","reminiscence (n.)"],"synonyms":["evocative"],"antonyms":[],"tipVi":"Đi kèm cấu trúc cố định be reminiscent of, giới từ đi theo không phải là about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_profound', 'en-c1-26', 'profound', '/prəˈfaʊnd/', 'C1', 'sâu sắc; sâu xa; lớn lao; uyên bác; sâu sắc (về tư duy, hiểu biết)', 'adj.', 'profoundly (adv.), profundity (n.)', 'Đồng nghĩa: deep · Trái nghĩa: superficial', 'Thường bổ nghĩa cho impact, change, understanding, không dùng để chỉ độ sâu vật lý.', 'Meeting my childhood teacher filled me with profound gratitude.', NULL, 'Cuộc gặp gỡ với người giáo viên thời tiểu học đã đọng lại trong tôi lòng biết ơn sâu sắc.', '{"wordId":"profound","ukIpa":"/prəˈfaʊnd/","usIpa":"/prəˈfaʊnd/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Very great in effect, degree, or intensity.","vi":"sâu sắc; sâu xa; lớn lao"},{"pos":"adj.","en":"Showing deep thought, understanding, or insight.","vi":"uyên bác; sâu sắc (về tư duy, hiểu biết)"}],"examples":[{"en":"Meeting my childhood teacher filled me with profound gratitude.","vi":"Cuộc gặp gỡ với người giáo viên thời tiểu học đã đọng lại trong tôi lòng biết ơn sâu sắc.","audioKind":"ex"},{"en":"Access to reliable internet has had a profound impact on educational opportunities in remote communities.","vi":"Việc tiếp cận internet ổn định đã tạo ra tác động sâu sắc đến cơ hội giáo dục ở các cộng đồng vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"a profound impact","vi":"tác động sâu sắc"},{"en":"profound changes","vi":"những thay đổi sâu sắc"},{"en":"profound understanding","vi":"sự thấu hiểu sâu sắc"},{"en":"profound sadness","vi":"nỗi buồn sâu sắc"}],"wordFamily":["profoundly (adv.)","profundity (n.)"],"synonyms":["deep"],"antonyms":["superficial"],"tipVi":"Thường bổ nghĩa cho impact, change, understanding, không dùng để chỉ độ sâu vật lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_utmost', 'en-c1-26', 'utmost', '/ˈʌtmoʊst/', 'C1', 'cực kỳ; lớn nhất; tối đa; sự nỗ lực tối đa; giới hạn cao nhất', 'adj.', NULL, 'Đồng nghĩa: maximum, greatest · Trái nghĩa: minimum', 'Cụm từ do one''s utmost có nghĩa là cố gắng hết sức, thường đi với to do.', 'Please handle this delicate glass bowl with utmost care.', NULL, 'Xin vui lòng cầm nắm chiếc bát thủy tinh dễ vỡ này với sự cẩn trọng cao độ.', '{"wordId":"utmost","ukIpa":"/ˈʌtməʊst/","usIpa":"/ˈʌtmoʊst/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"greatest in degree, amount, or intensity","vi":"cực kỳ; lớn nhất; tối đa"},{"pos":"n.","en":"the greatest effort or amount someone can achieve","vi":"sự nỗ lực tối đa; giới hạn cao nhất"}],"examples":[{"en":"Please handle this delicate glass bowl with utmost care.","vi":"Xin vui lòng cầm nắm chiếc bát thủy tinh dễ vỡ này với sự cẩn trọng cao độ.","audioKind":"ex"},{"en":"Protecting patient privacy is of the utmost importance when hospitals introduce digital systems for storing medical records.","vi":"Việc bảo vệ quyền riêng tư của bệnh nhân là vô cùng quan trọng khi các bệnh viện giới thiệu hệ thống kỹ thuật số để lưu trữ hồ sơ bệnh án.","audioKind":"ex2"}],"collocations":[{"en":"of the utmost importance","vi":"vô cùng quan trọng"},{"en":"with utmost care","vi":"với sự cẩn trọng tối đa"},{"en":"do your utmost","vi":"làm hết sức mình"},{"en":"utmost respect","vi":"sự kính trọng cao nhất"}],"wordFamily":[],"synonyms":["maximum","greatest"],"antonyms":["minimum"],"tipVi":"Cụm từ do one''s utmost có nghĩa là cố gắng hết sức, thường đi với to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contend', 'en-c1-26', 'contend', '/kənˈtend/', 'C1', 'cho rằng; quả quyết; chủ trương; đương đầu; chống chọi với; cạnh tranh; tranh giành', 'v.', 'contender (n.), contention (n.), contentious (adj.)', 'Đồng nghĩa: argue, maintain', 'contend that dùng để bày tỏ quan điểm; đi với giới từ with khi chỉ khó khăn; đi với for khi chỉ mục tiêu cạnh tranh.', 'I contend that our kitchen needs a bigger table.', NULL, 'Tôi cho rằng nhà bếp của chúng ta cần một cái bàn lớn hơn.', '{"wordId":"contend","ukIpa":"/kənˈtend/","usIpa":"/kənˈtend/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To argue that something is true.","vi":"cho rằng; quả quyết; chủ trương"},{"pos":"v.","en":"To struggle with a difficulty or challenging situation.","vi":"đương đầu; chống chọi với"},{"pos":"v.","en":"To compete for something against other people.","vi":"cạnh tranh; tranh giành"}],"examples":[{"en":"I contend that our kitchen needs a bigger table.","vi":"Tôi cho rằng nhà bếp của chúng ta cần một cái bàn lớn hơn.","audioKind":"ex"},{"en":"Some researchers contend that affordable public transport is more effective than road expansion in reducing urban congestion.","vi":"Một số nhà nghiên cứu cho rằng giao thông công cộng giá cả phải chăng có hiệu quả hơn việc mở rộng đường sá trong việc giảm thiểu tình trạng tắc nghẽn đô thị.","audioKind":"ex2"}],"collocations":[{"en":"contend that","vi":"cho rằng"},{"en":"contend with difficulties","vi":"đối mặt với khó khăn"},{"en":"contend for the title","vi":"tranh giành danh hiệu"}],"wordFamily":["contender (n.)","contention (n.)","contentious (adj.)"],"synonyms":["argue","maintain"],"antonyms":[],"tipVi":"contend that dùng để bày tỏ quan điểm; đi với giới từ with khi chỉ khó khăn; đi với for khi chỉ mục tiêu cạnh tranh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subtle', 'en-c1-26', 'subtle', '/ˈsʌtəl/', 'C1', 'tinh tế; khó nhận thấy; khéo léo; tế nhị; ẩn ý', 'adj.', 'subtly (adv.), subtlety (n.)', 'Đồng nghĩa: slight, understated · Trái nghĩa: obvious, blatant', 'Âm b là âm câm; thường dùng để chỉ những khác biệt hoặc ảnh hưởng khó nhận biết.', 'The soup has a subtle hint of lemon.', NULL, 'Món súp thoảng một vị chanh nhẹ nhàng.', '{"wordId":"subtle","ukIpa":"/ˈsʌtəl/","usIpa":"/ˈsʌtəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Small or delicate enough to be difficult to notice","vi":"tinh tế; khó nhận thấy"},{"pos":"adj.","en":"Expressed or achieved indirectly and skilfully","vi":"khéo léo; tế nhị; ẩn ý"}],"examples":[{"en":"The soup has a subtle hint of lemon.","vi":"Món súp thoảng một vị chanh nhẹ nhàng.","audioKind":"ex"},{"en":"Advertising can exert a subtle influence on consumers by associating products with desirable lifestyles.","vi":"Quảng cáo có thể tạo ra ảnh hưởng ngầm đối với người tiêu dùng bằng cách liên kết sản phẩm với lối sống mong muốn.","audioKind":"ex2"}],"collocations":[{"en":"a subtle difference","vi":"sự khác biệt nhỏ"},{"en":"a subtle hint","vi":"một gợi ý tế nhị"},{"en":"subtle influence","vi":"sức ảnh hưởng ngầm"},{"en":"a subtle flavour","vi":"hương vị thanh nhã"}],"wordFamily":["subtly (adv.)","subtlety (n.)"],"synonyms":["slight","understated"],"antonyms":["obvious","blatant"],"tipVi":"Âm b là âm câm; thường dùng để chỉ những khác biệt hoặc ảnh hưởng khó nhận biết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contradict', 'en-c1-26', 'contradict', '/ˌkɑːntrəˈdɪkt/', 'C1', 'mâu thuẫn với; trái ngược với; phủ nhận; cãi lại', 'v.', 'contradiction (n.), contradictory (adj.)', 'Đồng nghĩa: conflict with, dispute · Trái nghĩa: confirm, support', 'Là ngoại động từ nên đi thẳng với tân ngữ là người hoặc phát ngôn, không cần thêm giới từ with.', 'Your muddy shoes contradict your claim about staying indoors.', NULL, 'Đôi giày dính bùn của cậu mâu thuẫn hoàn toàn với lời khẳng định là cậu chỉ ở trong nhà.', '{"wordId":"contradict","ukIpa":"/ˌkɒntrəˈdɪkt/","usIpa":"/ˌkɑːntrəˈdɪkt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To be inconsistent with another statement, fact, or piece of evidence.","vi":"mâu thuẫn với; trái ngược với"},{"pos":"v.","en":"To say that someone else''s statement is wrong.","vi":"phủ nhận; cãi lại"}],"examples":[{"en":"Your muddy shoes contradict your claim about staying indoors.","vi":"Đôi giày dính bùn của cậu mâu thuẫn hoàn toàn với lời khẳng định là cậu chỉ ở trong nhà.","audioKind":"ex"},{"en":"Recent findings contradict the assumption that longer working hours necessarily lead to higher levels of productivity.","vi":"Các kết quả nghiên cứu gần đây đi ngược lại giả định cho rằng thời gian làm việc dài hơn chắc chắn sẽ mang lại năng suất cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"contradict a claim","vi":"mâu thuẫn với một tuyên bố"},{"en":"contradict the evidence","vi":"trái với bằng chứng"},{"en":"contradict yourself","vi":"tự mâu thuẫn chính mình"}],"wordFamily":["contradiction (n.)","contradictory (adj.)"],"synonyms":["conflict with","dispute"],"antonyms":["confirm","support"],"tipVi":"Là ngoại động từ nên đi thẳng với tân ngữ là người hoặc phát ngôn, không cần thêm giới từ with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_envisage', 'en-c1-26', 'envisage', '/ɪnˈvɪzɪdʒ/', 'C1', 'hình dung; vạch ra; dự tính (một tình huống hoặc sự kiện có thể xảy ra trong tương lai)', 'v.', NULL, 'Đồng nghĩa: imagine, envision', 'Theo sau là danh từ, danh động từ hoặc mệnh đề that, không đi kèm to do.', 'I envisage turning this spare room into a studio.', NULL, 'Tôi hình dung việc biến phòng trống này thành một phòng thu.', '{"wordId":"envisage","ukIpa":"/ɪnˈvɪzɪdʒ/","usIpa":"/ɪnˈvɪzɪdʒ/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To imagine a possible future situation or event.","vi":"hình dung; vạch ra; dự tính (một tình huống hoặc sự kiện có thể xảy ra trong tương lai)"}],"examples":[{"en":"I envisage turning this spare room into a studio.","vi":"Tôi hình dung việc biến phòng trống này thành một phòng thu.","audioKind":"ex"},{"en":"Urban planners envisage a future in which most residents can reach essential services on foot.","vi":"Các nhà quy hoạch đô thị hình dung một tương lai mà trong đó hầu hết cư dân có thể tiếp cận các dịch vụ thiết yếu bằng cách đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"envisage a future","vi":"dự tính tương lai"},{"en":"envisage doing something","vi":"dự tính làm điều gì đó"},{"en":"as originally envisaged","vi":"như đã dự tính ban đầu"}],"wordFamily":[],"synonyms":["imagine","envision"],"antonyms":[],"tipVi":"Theo sau là danh từ, danh động từ hoặc mệnh đề that, không đi kèm to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perplex', 'en-c1-26', 'perplex', '/pɚˈpleks/', 'C1', 'làm cho bối rối; làm cho hoang mang; làm cho khó hiểu', 'v.', 'perplexed (adj.), perplexing (adj.), perplexity (n.)', 'Đồng nghĩa: puzzle, confuse, bewilder · Trái nghĩa: enlighten', 'Là ngoại động từ; dùng perplexed cho người cảm thấy bối rối và perplexing cho sự việc gây hoang mang.', 'The washing machine''s strange noises continue to perplex me.', NULL, 'Những tiếng động lạ phát ra từ chiếc máy giặt vẫn khiến tôi thấy đau đầu.', '{"wordId":"perplex","ukIpa":"/pəˈpleks/","usIpa":"/pɚˈpleks/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To confuse someone because something is difficult to understand.","vi":"làm cho bối rối; làm cho hoang mang; làm cho khó hiểu"}],"examples":[{"en":"The washing machine''s strange noises continue to perplex me.","vi":"Những tiếng động lạ phát ra từ chiếc máy giặt vẫn khiến tôi thấy đau đầu.","audioKind":"ex"},{"en":"Conflicting dietary advice can perplex consumers who are trying to make healthier food choices.","vi":"Những lời khuyên về dinh dưỡng mâu thuẫn lẫn nhau có thể làm người tiêu dùng cảm thấy bối rối khi họ đang cố gắng lựa chọn thực phẩm lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"perplex researchers","vi":"làm các nhà nghiên cứu bối rối"},{"en":"be perplexed by","vi":"cảm thấy bối rối bởi"},{"en":"a perplexing problem","vi":"vấn đề nan giải"}],"wordFamily":["perplexed (adj.)","perplexing (adj.)","perplexity (n.)"],"synonyms":["puzzle","confuse","bewilder"],"antonyms":["enlighten"],"tipVi":"Là ngoại động từ; dùng perplexed cho người cảm thấy bối rối và perplexing cho sự việc gây hoang mang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quest', 'en-c1-26', 'quest', '/kwest/', 'C1', 'sự truy tìm; cuộc tìm kiếm; tìm kiếm; truy lùng', 'n.', NULL, 'Đồng nghĩa: search, pursuit', 'Thường dùng cấu trúc danh từ a quest for; cách dùng động từ mang tính văn chương hơn.', 'Our quest for fresh bread led us across town.', NULL, 'Cuộc tìm kiếm bánh mì tươi đã đưa chúng tôi đi khắp thị trấn.', '{"wordId":"quest","ukIpa":"/kwest/","usIpa":"/kwest/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"a long, determined search for something valuable or important","vi":"sự truy tìm; cuộc tìm kiếm"},{"pos":"v.","en":"search persistently for something difficult to find","vi":"tìm kiếm; truy lùng"}],"examples":[{"en":"Our quest for fresh bread led us across town.","vi":"Cuộc tìm kiếm bánh mì tươi đã đưa chúng tôi đi khắp thị trấn.","audioKind":"ex"},{"en":"The quest for cleaner energy has encouraged governments to invest heavily in new storage technologies.","vi":"Công cuộc tìm kiếm năng lượng sạch hơn đã khuyến khích các chính phủ đầu tư mạnh mẽ vào công nghệ lưu trữ mới.","audioKind":"ex2"}],"collocations":[{"en":"a quest for knowledge","vi":"tìm kiếm kiến thức"},{"en":"in quest of","vi":"trên con đường tìm kiếm"},{"en":"embark on a quest","vi":"bắt đầu một cuộc tìm kiếm"}],"wordFamily":[],"synonyms":["search","pursuit"],"antonyms":[],"tipVi":"Thường dùng cấu trúc danh từ a quest for; cách dùng động từ mang tính văn chương hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_doubtless', 'en-c1-26', 'doubtless', '/ˈdaʊtləs/', 'C1', 'chắc là; hầu như chắc chắn; có lẽ là', 'adv.', 'doubt (n., v.), doubtful (adj.), doubtfully (adv.)', 'Đồng nghĩa: presumably, probably', 'Thường biểu thị suy đoán có cơ sở chắc chắn, không nhất thiết là tuyệt đối chắc chắn.', 'You''ll doubtless feel hungry after such a long walk.', NULL, 'Bạn chắc chắn sẽ cảm thấy đói sau một chặng đường đi bộ dài như vậy.', '{"wordId":"doubtless","ukIpa":"/ˈdaʊtləs/","usIpa":"/ˈdaʊtləs/","cefr":"C1","topic":"thinking","senses":[{"pos":"adv.","en":"Almost certainly, or as one confidently expects.","vi":"chắc là; hầu như chắc chắn; có lẽ là"}],"examples":[{"en":"You''ll doubtless feel hungry after such a long walk.","vi":"Bạn chắc chắn sẽ cảm thấy đói sau một chặng đường đi bộ dài như vậy.","audioKind":"ex"},{"en":"Improved public transport will doubtless benefit commuters, although its construction may cause temporary disruption.","vi":"Việc cải thiện giao thông công cộng chắc chắn sẽ mang lại lợi ích cho những người đi lại, mặc dù việc thi công có thể gây ra sự gián đoạn tạm thời.","audioKind":"ex2"}],"collocations":[{"en":"will doubtless","vi":"chắc chắn sẽ"},{"en":"would doubtless","vi":"có lẽ sẽ"},{"en":"doubtless be aware","vi":"chắc chắn biết"}],"wordFamily":["doubt (n., v.)","doubtful (adj.)","doubtfully (adv.)"],"synonyms":["presumably","probably"],"antonyms":[],"tipVi":"Thường biểu thị suy đoán có cơ sở chắc chắn, không nhất thiết là tuyệt đối chắc chắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inference', 'en-c1-26', 'inference', '/ˈɪnfərəns/', 'C1', 'sự suy luận; điều suy ra từ bằng chứng', 'n.', 'infer (v.), inferential (adj.)', 'Đồng nghĩa: deduction, conclusion', 'Thường dùng cấu trúc draw an inference from, chỉ việc suy luận dựa trên bằng chứng.', 'Her muddy boots supported my inference about her morning walk.', NULL, 'Đôi giày dính đầy bùn của cô ấy đã củng cố cho phỏng đoán của tôi về buổi đi bộ buổi sáng của cô ấy.', '{"wordId":"inference","ukIpa":"/ˈɪnfərəns/","usIpa":"/ˈɪnfərəns/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A conclusion reached from evidence rather than direct statements.","vi":"sự suy luận; điều suy ra từ bằng chứng"}],"examples":[{"en":"Her muddy boots supported my inference about her morning walk.","vi":"Đôi giày dính đầy bùn của cô ấy đã củng cố cho phỏng đoán của tôi về buổi đi bộ buổi sáng của cô ấy.","audioKind":"ex"},{"en":"Researchers should avoid drawing a firm inference from a small sample without considering alternative explanations.","vi":"Các nhà nghiên cứu nên tránh đưa ra kết luận chắc chắn từ một mẫu nhỏ mà không xem xét các cách giải thích thay thế.","audioKind":"ex2"}],"collocations":[{"en":"draw an inference","vi":"rút ra kết luận"},{"en":"reasonable inference","vi":"suy luận hợp lý"},{"en":"inference from evidence","vi":"suy luận từ bằng chứng"}],"wordFamily":["infer (v.)","inferential (adj.)"],"synonyms":["deduction","conclusion"],"antonyms":[],"tipVi":"Thường dùng cấu trúc draw an inference from, chỉ việc suy luận dựa trên bằng chứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indicative', 'en-c1-26', 'indicative', '/ɪnˈdɪkətɪv/', 'C1', 'biểu lộ; ám chỉ; cho thấy điều gì; thuộc thức trần thuật', 'adj.', 'indicate (v.), indication (n.), indicator (n.)', 'Đồng nghĩa: suggestive, revealing', 'Thường dùng cấu trúc be indicative of, nghĩa là "là dấu hiệu cho thấy...".', 'These dark clouds are indicative of an approaching storm.', NULL, 'Những đám mây đen này là dấu hiệu cho thấy một cơn bão sắp đến.', '{"wordId":"indicative","ukIpa":"/ɪnˈdɪkətɪv/","usIpa":"/ɪnˈdɪkətɪv/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Showing that something exists or is likely to be true.","vi":"biểu lộ; ám chỉ; cho thấy điều gì"},{"pos":"adj.","en":"Describing verb forms used for statements of fact or questions.","vi":"thuộc thức trần thuật"}],"examples":[{"en":"These dark clouds are indicative of an approaching storm.","vi":"Những đám mây đen này là dấu hiệu cho thấy một cơn bão sắp đến.","audioKind":"ex"},{"en":"Rising demand for public transport may be indicative of changing attitudes towards car ownership in urban areas.","vi":"Nhu cầu giao thông công cộng tăng cao có thể cho thấy thái độ đối với việc sở hữu ô tô ở khu vực đô thị đang thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"indicative of","vi":"biểu thị cho"},{"en":"indicative figures","vi":"số liệu tham khảo"},{"en":"indicative mood","vi":"thức trần thuật"}],"wordFamily":["indicate (v.)","indication (n.)","indicator (n.)"],"synonyms":["suggestive","revealing"],"antonyms":[],"tipVi":"Thường dùng cấu trúc be indicative of, nghĩa là \"là dấu hiệu cho thấy...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prudent', 'en-c1-26', 'prudent', '/ˈpruːdənt/', 'C1', 'thận trọng; khôn ngoan', 'adj.', 'prudence (n.), prudently (adv.), imprudent (adj.)', 'Đồng nghĩa: sensible, cautious · Trái nghĩa: reckless, imprudent', 'Nhấn mạnh việc cân nhắc rủi ro và hậu quả, không chỉ đơn thuần là sự rụt rè hay tiết kiệm.', 'Taking an extra jacket seemed prudent before our mountain walk.', NULL, 'Mặc thêm một chiếc áo khoác có vẻ là sự lựa chọn khôn ngoan trước khi chúng tôi đi leo núi.', '{"wordId":"prudent","ukIpa":"/ˈpruːdənt/","usIpa":"/ˈpruːdənt/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Careful and sensible about risks and future consequences.","vi":"thận trọng; khôn ngoan"}],"examples":[{"en":"Taking an extra jacket seemed prudent before our mountain walk.","vi":"Mặc thêm một chiếc áo khoác có vẻ là sự lựa chọn khôn ngoan trước khi chúng tôi đi leo núi.","audioKind":"ex"},{"en":"Prudent financial planning can help households cope with unexpected expenses during periods of economic uncertainty.","vi":"Việc lập kế hoạch tài chính thận trọng có thể giúp các hộ gia đình đối phó với những khoản chi phí bất ngờ trong thời kỳ kinh tế bất ổn.","audioKind":"ex2"}],"collocations":[{"en":"prudent decision","vi":"quyết định thận trọng"},{"en":"prudent financial management","vi":"quản lý tài chính thận trọng"},{"en":"prudent to do something","vi":"khôn ngoan khi làm gì đó"}],"wordFamily":["prudence (n.)","prudently (adv.)","imprudent (adj.)"],"synonyms":["sensible","cautious"],"antonyms":["reckless","imprudent"],"tipVi":"Nhấn mạnh việc cân nhắc rủi ro và hậu quả, không chỉ đơn thuần là sự rụt rè hay tiết kiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cunning', 'en-c1-26', 'cunning', '/ˈkʌnɪŋ/', 'C1', 'xảo quyệt; gian xảo; khéo léo; tinh vi; sự xảo quyệt; mưu mẹo', 'adj.', 'cunningly (adv.)', 'Đồng nghĩa: crafty, sly · Trái nghĩa: guileless', 'Khi dùng để miêu tả con người thường mang nghĩa tiêu cực, không đồng nghĩa với sự thông minh thông thường.', 'The cunning fox waited until the dog fell asleep.', NULL, 'Con cáo xảo quyệt đã đợi cho đến khi con chó ngủ thiếp đi.', '{"wordId":"cunning","ukIpa":"/ˈkʌnɪŋ/","usIpa":"/ˈkʌnɪŋ/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Clever at getting what you want by deceiving others.","vi":"xảo quyệt; gian xảo"},{"pos":"adj.","en":"Cleverly planned or designed to achieve a purpose.","vi":"khéo léo; tinh vi"},{"pos":"n.","en":"Skill in achieving goals through clever deception.","vi":"sự xảo quyệt; mưu mẹo"}],"examples":[{"en":"The cunning fox waited until the dog fell asleep.","vi":"Con cáo xảo quyệt đã đợi cho đến khi con chó ngủ thiếp đi.","audioKind":"ex"},{"en":"Cunning advertising tactics can persuade consumers to purchase products they neither need nor can afford.","vi":"Các thủ thuật quảng cáo tinh vi có thể thuyết phục người tiêu dùng mua những sản phẩm mà họ không cần cũng không đủ khả năng chi trả.","audioKind":"ex2"}],"collocations":[{"en":"a cunning plan","vi":"một kế hoạch tinh vi"},{"en":"a cunning trick","vi":"một mánh khóe xảo quyệt"},{"en":"cunning tactics","vi":"chiến thuật gian xảo"}],"wordFamily":["cunningly (adv.)"],"synonyms":["crafty","sly"],"antonyms":["guileless"],"tipVi":"Khi dùng để miêu tả con người thường mang nghĩa tiêu cực, không đồng nghĩa với sự thông minh thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solely', 'en-c1-26', 'solely', '/ˈsoʊlli/', 'C1', 'chỉ; hoàn toàn chỉ', 'adv.', 'sole (adj.)', 'Đồng nghĩa: only, exclusively', 'solely nhấn mạnh chỉ hạn chế ở một người hoặc một việc cụ thể, không đồng nghĩa với ''độc lập'' (alone).', 'This cupboard is used solely for cleaning supplies.', NULL, 'Cái tủ này chỉ dùng để chứa các dụng cụ vệ sinh.', '{"wordId":"solely","ukIpa":"/ˈsəʊlli/","usIpa":"/ˈsoʊlli/","cefr":"C1","topic":"thinking","senses":[{"pos":"adv.","en":"Only, with nothing or nobody else involved.","vi":"chỉ; hoàn toàn chỉ"}],"examples":[{"en":"This cupboard is used solely for cleaning supplies.","vi":"Cái tủ này chỉ dùng để chứa các dụng cụ vệ sinh.","audioKind":"ex"},{"en":"Schools should not judge students solely on examination results, since practical skills also matter.","vi":"Nhà trường không nên đánh giá học sinh chỉ dựa vào kết quả thi cử, vì các kỹ năng thực tế cũng rất quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"solely responsible","vi":"chịu trách nhiệm hoàn toàn"},{"en":"solely based on","vi":"chỉ dựa trên"},{"en":"rely solely on","vi":"hoàn toàn phụ thuộc vào"}],"wordFamily":["sole (adj.)"],"synonyms":["only","exclusively"],"antonyms":[],"tipVi":"solely nhấn mạnh chỉ hạn chế ở một người hoặc một việc cụ thể, không đồng nghĩa với ''độc lập'' (alone).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insofar', 'en-c1-26', 'insofar', '/ˌɪnsoʊˈfɑːr/', 'C1', 'trong chừng mực mà; theo như', 'adv.', NULL, NULL, 'Thường được dùng trong cấu trúc trang trọng insofar as, đi kèm theo một mệnh đề phía sau.', 'I''ll help insofar as my busy schedule allows.', NULL, 'Tôi sẽ giúp đỡ trong chừng mực lịch trình bận rộn của mình cho phép.', '{"wordId":"insofar","ukIpa":"/ˌɪnsəʊˈfɑː/","usIpa":"/ˌɪnsoʊˈfɑːr/","cefr":"C1","topic":"thinking","senses":[{"pos":"adv.","en":"To the extent that something is true or possible.","vi":"trong chừng mực mà; theo như"}],"examples":[{"en":"I''ll help insofar as my busy schedule allows.","vi":"Tôi sẽ giúp đỡ trong chừng mực lịch trình bận rộn của mình cho phép.","audioKind":"ex"},{"en":"Online learning is effective insofar as students have reliable internet access and receive adequate support from teachers.","vi":"Học trực tuyến mang lại hiệu quả trong điều kiện học sinh có kết nối internet ổn định và nhận được sự hỗ trợ đầy đủ từ giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"insofar as possible","vi":"trong khả năng có thể"},{"en":"insofar as it affects","vi":"trong chừng mực nó ảnh hưởng"},{"en":"insofar as we know","vi":"theo như chúng ta biết"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường được dùng trong cấu trúc trang trọng insofar as, đi kèm theo một mệnh đề phía sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subdivide', 'en-c1-26', 'subdivide', '/ˌsʌbdɪˈvaɪd/', 'C1', 'chia nhỏ; phân nhỏ', 'v.', 'subdivision (n.), divide (v.), division (n.)', 'Đồng nghĩa: partition, divide · Trái nghĩa: combine, merge', 'Thường dùng cấu trúc subdivide A into B, biểu thị việc chia nhỏ A thành các phần B.', 'We subdivided the drawer with small wooden dividers.', NULL, 'Chúng tôi đã chia nhỏ ngăn kéo bằng các tấm gỗ ngăn nhỏ.', '{"wordId":"subdivide","ukIpa":"/ˌsʌbdɪˈvaɪd/","usIpa":"/ˌsʌbdɪˈvaɪd/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to divide something into smaller parts or groups","vi":"chia nhỏ; phân nhỏ"}],"examples":[{"en":"We subdivided the drawer with small wooden dividers.","vi":"Chúng tôi đã chia nhỏ ngăn kéo bằng các tấm gỗ ngăn nhỏ.","audioKind":"ex"},{"en":"Researchers often subdivide survey participants into age groups to identify differences in attitudes towards public transport.","vi":"Các nhà nghiên cứu thường phân chia người tham gia khảo sát thành các nhóm tuổi để xác định sự khác biệt trong thái độ đối với giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"subdivide into groups","vi":"chia thành các nhóm nhỏ"},{"en":"subdivide land","vi":"chia nhỏ đất đai"},{"en":"subdivide a category","vi":"chia nhỏ danh mục"}],"wordFamily":["subdivision (n.)","divide (v.)","division (n.)"],"synonyms":["partition","divide"],"antonyms":["combine","merge"],"tipVi":"Thường dùng cấu trúc subdivide A into B, biểu thị việc chia nhỏ A thành các phần B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_26_1', 'en-c1-26', 'Cách dùng “contend” (v.) — cho rằng; quả quyết; chủ trương', 'contend that  ·  contend with difficulties  ·  contend for the title', 'contend that dùng để bày tỏ quan điểm; đi với giới từ with khi chỉ khó khăn; đi với for khi chỉ mục tiêu cạnh tranh.', 'Họ từ (Word Family): contender (n.), contention (n.), contentious (adj.) | Đồng nghĩa: argue, maintain', '[{"hanzi":"I contend that our kitchen needs a bigger table.","pinyin":"","meaning":"Tôi cho rằng nhà bếp của chúng ta cần một cái bàn lớn hơn."},{"hanzi":"Some researchers contend that affordable public transport is more effective than road expansion in reducing urban congestion.","pinyin":"","meaning":"Một số nhà nghiên cứu cho rằng giao thông công cộng giá cả phải chăng có hiệu quả hơn việc mở rộng đường sá trong việc giảm thiểu tình trạng tắc nghẽn đô thị."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_26_2', 'en-c1-26', 'Cách dùng “contemplation” (n.) — sự trầm ngâm; sự suy ngẫm', 'quiet contemplation  ·  deep contemplation  ·  in contemplation', 'Thường là danh từ không đếm được; nhấn mạnh sự suy nghĩ yên bình, không nhất thiết là sự dằn vặt hay đau khổ.', 'Họ từ (Word Family): contemplate (v.), contemplative (adj.) | Đồng nghĩa: reflection, meditation', '[{"hanzi":"He sat by the lake in quiet contemplation.","pinyin":"","meaning":"Anh ấy ngồi bên hồ trong trạng thái tĩnh lặng suy ngẫm."},{"hanzi":"Public gardens offer urban residents valuable opportunities for quiet contemplation away from the pressures of daily life.","pinyin":"","meaning":"Các khu vườn công cộng mang lại cho cư dân thành phố những cơ hội quý giá để tĩnh tâm suy ngẫm, tránh xa áp lực của cuộc sống thường nhật."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_26_3', 'en-c1-26', 'Cách dùng “retrospect” (n.) — sự nhìn lại quá khứ; hồi tưởng', 'in retrospect  ·  only in retrospect', 'Thường được dùng trong cụm từ cố định in retrospect, biểu thị việc suy ngẫm lại sự việc sau khi nó đã xảy ra.', 'Họ từ (Word Family): retrospective (adj.), retrospectively (adv.) | Đồng nghĩa: hindsight', '[{"hanzi":"In retrospect, packing extra socks was a brilliant idea.","pinyin":"","meaning":"Nhìn lại thì việc mang theo đôi tất thừa là một ý tưởng tuyệt vời."},{"hanzi":"In retrospect, investing earlier in public transport could have prevented many of the city''s current traffic problems.","pinyin":"","meaning":"Nhìn lại quãng thời gian trước đây, việc đầu tư sớm hơn vào giao thông công cộng đã có thể ngăn chặn nhiều vấn đề ùn tắc hiện tại của thành phố."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_26_4', 'en-c1-26', 'Cách dùng “cunning” (adj.) — xảo quyệt; gian xảo', 'a cunning plan  ·  a cunning trick  ·  cunning tactics', 'Khi dùng để miêu tả con người thường mang nghĩa tiêu cực, không đồng nghĩa với sự thông minh thông thường.', 'Họ từ (Word Family): cunningly (adv.) | Đồng nghĩa: crafty, sly · Trái nghĩa: guileless', '[{"hanzi":"The cunning fox waited until the dog fell asleep.","pinyin":"","meaning":"Con cáo xảo quyệt đã đợi cho đến khi con chó ngủ thiếp đi."},{"hanzi":"Cunning advertising tactics can persuade consumers to purchase products they neither need nor can afford.","pinyin":"","meaning":"Các thủ thuật quảng cáo tinh vi có thể thuyết phục người tiêu dùng mua những sản phẩm mà họ không cần cũng không đủ khả năng chi trả."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_26_1', 'en-c1-26', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
