INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_1_2', 'ten_c1_26_1', 'inherent', 'Even simple home repairs come with some inherent risks.', 'Even simple home repairs come with some inherent risks.', '/ɪnˈhɪrənt/', 'Ngay cả những việc sửa chữa nhà cửa đơn giản cũng đi kèm với một số rủi ro vốn có.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_1_3', 'ten_c1_26_1', 'retrospect', 'In retrospect, packing extra socks was a brilliant idea.', 'In retrospect, packing extra socks was a brilliant idea.', '/ˈretrəspekt/', 'Nhìn lại thì việc mang theo đôi tất thừa là một ý tưởng tuyệt vời.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_1_4', 'ten_c1_26_1', 'implicit', 'Her welcoming smile was an implicit invitation to join.', 'Her welcoming smile was an implicit invitation to join.', '/ɪmˈplɪsɪt/', 'Nụ cười chào đón của cô ấy là lời mời gọi ngầm để chúng tôi cùng tham gia.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_1_5', 'ten_c1_26_1', 'persistence', 'After weeks of practice, his persistence finally paid off.', 'After weeks of practice, his persistence finally paid off.', '/pɚˈsɪstəns/', 'Sau nhiều tuần tập luyện, sự kiên trì của anh ấy cuối cùng cũng được đền đáp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_1_6', 'ten_c1_26_1', 'pertinent', 'Lena asked a pertinent question about the repair costs.', 'Lena asked a pertinent question about the repair costs.', '/ˈpɝːtənənt/', 'Lena đã đặt một câu hỏi rất sát thực tế về chi phí sửa chữa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_1_7', 'ten_c1_26_1', 'gullible', 'I was gullible enough to believe his ridiculous story.', 'I was gullible enough to believe his ridiculous story.', '/ˈɡʌləbl/', 'Tôi đã quá cả tin khi tin vào câu chuyện nực cười của anh ta.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_1_8', 'ten_c1_26_1', 'whereby', 'We have an arrangement whereby we share the cooking.', 'We have an arrangement whereby we share the cooking.', '/werˈbaɪ/', 'Chúng tôi có một thỏa thuận theo đó chúng tôi chia sẻ việc nấu nướng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_26_1_1', 'en-c1-26', 'ten_c1_26_1', 'listening', 'listening', 'He sat by the lake in quiet contemplation.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những đám mây đen này là dấu hiệu cho thấy một cơn bão sắp đến.","Cuộc tìm kiếm bánh mì tươi đã đưa chúng tôi đi khắp thị trấn.","Những tiếng động lạ phát ra từ chiếc máy giặt vẫn khiến tôi thấy đau đầu.","Anh ấy ngồi bên hồ trong trạng thái tĩnh lặng suy ngẫm."]'::jsonb, 3, 'He sat by the lake in quiet contemplation. → Anh ấy ngồi bên hồ trong trạng thái tĩnh lặng suy ngẫm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_26_1_2', 'en-c1-26', 'ten_c1_26_1', 'listening', 'listening', 'Even simple home repairs come with some inherent risks.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ngay cả những việc sửa chữa nhà cửa đơn giản cũng đi kèm với một số rủi ro vốn có.","Hương vị của món súp làm tôi nhớ đến bữa cơm do bà tôi nấu.","Tôi đã quá cả tin khi tin vào câu chuyện nực cười của anh ta.","Chúng tôi đã chia nhỏ ngăn kéo bằng các tấm gỗ ngăn nhỏ."]'::jsonb, 0, 'Even simple home repairs come with some inherent risks. → Ngay cả những việc sửa chữa nhà cửa đơn giản cũng đi kèm với một số rủi ro vốn có.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_26_1_3', 'en-c1-26', 'ten_c1_26_1', 'listening', 'listening', 'In retrospect, packing extra socks was a brilliant idea.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn chắc chắn sẽ cảm thấy đói sau một chặng đường đi bộ dài như vậy.","Tôi hình dung việc biến phòng trống này thành một phòng thu.","Đôi giày dính đầy bùn của cô ấy đã củng cố cho phỏng đoán của tôi về buổi đi bộ buổi sáng của cô ấy.","Nhìn lại thì việc mang theo đôi tất thừa là một ý tưởng tuyệt vời."]'::jsonb, 3, 'In retrospect, packing extra socks was a brilliant idea. → Nhìn lại thì việc mang theo đôi tất thừa là một ý tưởng tuyệt vời.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_26_2', 'en-c1-26', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_2_1', 'ten_c1_26_2', 'contemplation', 'Public gardens offer urban residents valuable opportunities for quiet contemplation away from the pressures of daily life.', 'Public gardens offer urban residents valuable opportunities for quiet contemplation away from the pressures of daily life.', '/ˌkɑːntəmˈpleɪʃən/', 'Các khu vườn công cộng mang lại cho cư dân thành phố những cơ hội quý giá để tĩnh tâm suy ngẫm, tránh xa áp lực của cuộc sống thường nhật.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_2_2', 'ten_c1_26_2', 'inherent', 'Policymakers must recognise the inherent limitations of economic growth as a measure of social progress and wellbeing.', 'Policymakers must recognise the inherent limitations of economic growth as a measure of social progress and wellbeing.', '/ɪnˈhɪrənt/', 'Các nhà hoạch định chính sách phải nhận thức rõ những hạn chế vốn có của việc sử dụng tăng trưởng kinh tế làm thước đo cho tiến bộ xã hội và hạnh phúc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_2_3', 'ten_c1_26_2', 'retrospect', 'In retrospect, investing earlier in public transport could have prevented many of the city''s current traffic problems.', 'In retrospect, investing earlier in public transport could have prevented many of the city''s current traffic problems.', '/ˈretrəspekt/', 'Nhìn lại quãng thời gian trước đây, việc đầu tư sớm hơn vào giao thông công cộng đã có thể ngăn chặn nhiều vấn đề ùn tắc hiện tại của thành phố.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_2_4', 'ten_c1_26_2', 'implicit', 'Many workplaces have implicit expectations about overtime, which can make employees reluctant to leave on time.', 'Many workplaces have implicit expectations about overtime, which can make employees reluctant to leave on time.', '/ɪmˈplɪsɪt/', 'Nhiều nơi làm việc có những kỳ vọng ngầm về việc làm thêm giờ, điều này có thể khiến nhân viên thấy miễn cưỡng khi rời đi đúng giờ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_2_5', 'ten_c1_26_2', 'persistence', 'The persistence of poverty suggests that economic growth alone cannot guarantee better living conditions for every household.', 'The persistence of poverty suggests that economic growth alone cannot guarantee better living conditions for every household.', '/pɚˈsɪstəns/', 'Sự kéo dài của tình trạng nghèo đói cho thấy rằng chỉ riêng sự tăng trưởng kinh tế không thể đảm bảo điều kiện sống tốt hơn cho mọi hộ gia đình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_26_2_6', 'ten_c1_26_2', 'pertinent', 'Evidence about local air quality is particularly pertinent to discussions of expanding public transport networks.', 'Evidence about local air quality is particularly pertinent to discussions of expanding public transport networks.', '/ˈpɝːtənənt/', 'Bằng chứng về chất lượng không khí địa phương đặc biệt liên quan đến các cuộc thảo luận về việc mở rộng mạng lưới giao thông công cộng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_26_2_1', 'en-c1-26', 'ten_c1_26_2', 'listening', 'listening', 'Public gardens offer urban residents valuable opportunities for quiet contemplation away from the pressures of daily life.', NULL, 'Trong câu vừa nghe, từ “contemplation” mang nghĩa nào sau đây?', '["gỡ rối; tháo gỡ","quay; chuyển động theo vòng tròn; chạy bằng cơ chế quay","sự trầm ngâm; sự suy ngẫm","nhen nhóm ngọn lửa hoặc bắt đầu cháy"]'::jsonb, 2, '“contemplation” (/ˌkɑːntəmˈpleɪʃən/): sự trầm ngâm; sự suy ngẫm. Câu đầy đủ: Public gardens offer urban residents valuable opportunities for quiet contemplation away from the pressures of daily life.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_26_2_2', 'en-c1-26', 'ten_c1_26_2', 'listening', 'listening', 'Policymakers must recognise the inherent limitations of economic growth as a measure of social progress and wellbeing.', NULL, 'Trong câu vừa nghe, từ “inherent” mang nghĩa nào sau đây?', '["vốn có; bản chất; nội tại","tầm vóc; quy mô lớn; tầm quan trọng","dự nhiên; đúng cách diễn đạt bản ngữ","làm việc chăm chỉ và cẩn thận trong một khoảng thời gian dài; cần cù, chăm chỉ"]'::jsonb, 0, '“inherent” (/ɪnˈhɪrənt/): vốn có; bản chất; nội tại. Câu đầy đủ: Policymakers must recognise the inherent limitations of economic growth as a measure of social progress and wellbeing.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_26_1', 'en-c1-26', 'He sat by the lake in quiet contemplation', 'Anh ấy ngồi bên hồ trong trạng thái tĩnh lặng suy ngẫm.', 'contemplation /ˌkɑːntəmˈpleɪʃən/', '["He","sat","in","lake","contemplation","by","the","quiet"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_26_2', 'en-c1-26', 'Even simple home repairs come with some inherent risks', 'Ngay cả những việc sửa chữa nhà cửa đơn giản cũng đi kèm với một số rủi ro vốn có.', 'inherent /ɪnˈhɪrənt/', '["inherent","simple","some","come","with","Even","risks","home","repairs"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_26_3', 'en-c1-26', 'In retrospect, packing extra socks was a brilliant idea', 'Nhìn lại thì việc mang theo đôi tất thừa là một ý tưởng tuyệt vời.', 'retrospect /ˈretrəspekt/', '["In","brilliant","extra","idea","a","retrospect","socks","packing","was"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_26_4', 'en-c1-26', 'Her welcoming smile was an implicit invitation to join', 'Nụ cười chào đón của cô ấy là lời mời gọi ngầm để chúng tôi cùng tham gia.', 'implicit /ɪmˈplɪsɪt/', '["invitation","Her","was","an","smile","join","implicit","to","welcoming"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_26_5', 'en-c1-26', 'After weeks of practice, his persistence finally paid off', 'Sau nhiều tuần tập luyện, sự kiên trì của anh ấy cuối cùng cũng được đền đáp.', 'persistence /pɚˈsɪstəns/', '["paid","weeks","persistence","After","practice","off","his","finally","of"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_26_6', 'en-c1-26', 'Lena asked a pertinent question about the repair costs', 'Lena đã đặt một câu hỏi rất sát thực tế về chi phí sửa chữa.', 'pertinent /ˈpɝːtənənt/', '["question","pertinent","Lena","repair","a","asked","about","the","costs"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_26_7', 'en-c1-26', 'I was gullible enough to believe his ridiculous story', 'Tôi đã quá cả tin khi tin vào câu chuyện nực cười của anh ta.', 'gullible /ˈɡʌləbl/', '["gullible","his","enough","I","was","story","to","ridiculous","believe"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_26_8', 'en-c1-26', 'We have an arrangement whereby we share the cooking', 'Chúng tôi có một thỏa thuận theo đó chúng tôi chia sẻ việc nấu nướng.', 'whereby /werˈbaɪ/', '["share","an","cooking","arrangement","have","whereby","We","the","we"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_26_9', 'en-c1-26', 'From her muddy shoes, I inferred she had been gardening', 'Từ đôi giày dính đầy bùn của cô ấy, tôi suy ra rằng cô ấy vừa làm vườn.', 'infer /ɪnˈfɝː/', '["been","From","shoes","gardening","muddy","her","had","I","she","inferred"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
