INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_1', 'en-c1-26', NULL, 'comprehensive_test', 'listening', 'contemplation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự trầm ngâm; sự suy ngẫm","đám cháy lớn; ngọn lửa lớn","thời đại; kỷ nguyên","hùng biện; có sức thuyết phục cao"]'::jsonb, 0, 'contemplation (/ˌkɑːntəmˈpleɪʃən/) → sự trầm ngâm; sự suy ngẫm; sự cân nhắc; sự trăn trở', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_2', 'en-c1-26', NULL, 'comprehensive_test', 'listening', 'Even simple home repairs come with some inherent risks.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mặc thêm một chiếc áo khoác có vẻ là sự lựa chọn khôn ngoan trước khi chúng tôi đi leo núi.","Đôi giày dính bùn của cậu mâu thuẫn hoàn toàn với lời khẳng định là cậu chỉ ở trong nhà.","Con cáo xảo quyệt đã đợi cho đến khi con chó ngủ thiếp đi.","Ngay cả những việc sửa chữa nhà cửa đơn giản cũng đi kèm với một số rủi ro vốn có."]'::jsonb, 3, 'Even simple home repairs come with some inherent risks. → Ngay cả những việc sửa chữa nhà cửa đơn giản cũng đi kèm với một số rủi ro vốn có.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_3', 'en-c1-26', NULL, 'comprehensive_test', 'listening', 'retrospect', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự nhìn lại quá khứ; hồi tưởng","hung dữ; dữ tợn","chắc là; hầu như chắc chắn; có lẽ là","đồng thời; song song (xảy ra hoặc tồn tại cùng một lúc)"]'::jsonb, 0, 'retrospect (/ˈretrəspekt/) → sự nhìn lại quá khứ; hồi tưởng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_4', 'en-c1-26', NULL, 'comprehensive_test', 'listening', 'Her welcoming smile was an implicit invitation to join.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi sẽ giúp đỡ trong chừng mực lịch trình bận rộn của mình cho phép.","Nụ cười chào đón của cô ấy là lời mời gọi ngầm để chúng tôi cùng tham gia.","Từ đôi giày dính đầy bùn của cô ấy, tôi suy ra rằng cô ấy vừa làm vườn.","Hương vị của món súp làm tôi nhớ đến bữa cơm do bà tôi nấu."]'::jsonb, 1, 'Her welcoming smile was an implicit invitation to join. → Nụ cười chào đón của cô ấy là lời mời gọi ngầm để chúng tôi cùng tham gia.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_5', 'en-c1-26', NULL, 'comprehensive_test', 'listening', 'persistence', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự kiên trì; tính kiên định; sự bền bỉ","cho phép tự học; tự chọn tài liệu học tập","lô hàng; chuyến hàng","sự cạn nước mắc cạn; vụ tai nạn mắc cạn"]'::jsonb, 0, 'persistence (/pɚˈsɪstəns/) → sự kiên trì; tính kiên định; sự bền bỉ; sự tiếp diễn; sự kéo dài', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_6', 'en-c1-26', NULL, 'comprehensive_test', 'listening', 'Lena asked a pertinent question about the repair costs.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi có một thỏa thuận theo đó chúng tôi chia sẻ việc nấu nướng.","Đôi giày dính đầy bùn của cô ấy đã củng cố cho phỏng đoán của tôi về buổi đi bộ buổi sáng của cô ấy.","Cuộc tìm kiếm bánh mì tươi đã đưa chúng tôi đi khắp thị trấn.","Lena đã đặt một câu hỏi rất sát thực tế về chi phí sửa chữa."]'::jsonb, 3, 'Lena asked a pertinent question about the repair costs. → Lena đã đặt một câu hỏi rất sát thực tế về chi phí sửa chữa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_7', 'en-c1-26', NULL, 'comprehensive_test', 'listening', 'gullible', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bợm nhậu; kẻ nát rượu","bác bỏ; chứng minh là sai","kiểm soát; kìm chế","cả tin; dễ bị lừa"]'::jsonb, 3, 'gullible (/ˈɡʌləbl/) → cả tin; dễ bị lừa', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_8', 'en-c1-26', NULL, 'comprehensive_test', 'listening', 'We have an arrangement whereby we share the cooking.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hương vị của món súp làm tôi nhớ đến bữa cơm do bà tôi nấu.","Xin vui lòng cầm nắm chiếc bát thủy tinh dễ vỡ này với sự cẩn trọng cao độ.","Chúng tôi có một thỏa thuận theo đó chúng tôi chia sẻ việc nấu nướng.","Những tiếng động lạ phát ra từ chiếc máy giặt vẫn khiến tôi thấy đau đầu."]'::jsonb, 2, 'We have an arrangement whereby we share the cooking. → Chúng tôi có một thỏa thuận theo đó chúng tôi chia sẻ việc nấu nướng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_9', 'en-c1-26', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “continued effort despite difficulties or delays”?', '["persistence","retrospect","insofar","inference"]'::jsonb, 0, 'persistence (/pɚˈsɪstəns/) → sự kiên trì; tính kiên định; sự bền bỉ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_10', 'en-c1-26', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “directly related to the matter being discussed”?', '["pertinent","inference","persistence","solely"]'::jsonb, 0, 'pertinent (/ˈpɝːtənənt/) → thích đáng; liên quan; sát với vấn đề', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_11', 'en-c1-26', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Too willing to believe what others say, even when untrue”?', '["subtle","infer","gullible","indicative"]'::jsonb, 2, 'gullible (/ˈɡʌləbl/) → cả tin; dễ bị lừa', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_12', 'en-c1-26', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “By which a particular result is achieved.”?', '["contradict","whereby","indicative","insofar"]'::jsonb, 1, 'whereby (/werˈbaɪ/) → nhờ đó; theo đó', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_13', 'en-c1-26', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to reach a conclusion using evidence rather than direct statements”?', '["gullible","envisage","infer","solely"]'::jsonb, 2, 'infer (/ɪnˈfɝː/) → suy ra; luận ra', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
