INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_18', 'en-c1-26', NULL, 'comprehensive_test', 'reading', NULL, 'Public gardens offer urban residents valuable opportunities for quiet contemplation away from the pressures of daily life.', 'Dựa vào câu trên, từ “contemplation” có nghĩa phù hợp nhất là gì?', '["tác giả viết tản văn; nhà văn chuyên viết tiểu luận","xâm lấn dần; xâm phạm","chủ nghĩa bảo hộ mậu dịch; chính sách bảo hộ","sự trầm ngâm; sự suy ngẫm"]'::jsonb, 3, 'contemplation: sự trầm ngâm; sự suy ngẫm; sự cân nhắc; sự trăn trở. Dịch cả câu: Các khu vườn công cộng mang lại cho cư dân thành phố những cơ hội quý giá để tĩnh tâm suy ngẫm, tránh xa áp lực của cuộc sống thường nhật.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_19', 'en-c1-26', NULL, 'comprehensive_test', 'reading', NULL, 'Policymakers must recognise the inherent limitations of economic growth as a measure of social progress and wellbeing.', 'Dựa vào câu trên, từ “inherent” có nghĩa phù hợp nhất là gì?', '["huyết tương","bản ghi chép lời thoại; bản thảo","vốn có; bản chất; nội tại","hạn chế; giới hạn (trong một phạm vi nhất định)"]'::jsonb, 2, 'inherent: vốn có; bản chất; nội tại. Dịch cả câu: Các nhà hoạch định chính sách phải nhận thức rõ những hạn chế vốn có của việc sử dụng tăng trưởng kinh tế làm thước đo cho tiến bộ xã hội và hạnh phúc.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_20', 'en-c1-26', NULL, 'comprehensive_test', 'reading', NULL, 'In retrospect, investing earlier in public transport could have prevented many of the city''s current traffic problems.', 'Dựa vào câu trên, từ “retrospect” có nghĩa phù hợp nhất là gì?', '["sự nhìn lại quá khứ; hồi tưởng","đo lường hoặc biểu thị số lượng của cái gì; định lượng","hiệp định; hiệp ước","hệ thống thuế; việc thu thuế; thuế khóa"]'::jsonb, 0, 'retrospect: sự nhìn lại quá khứ; hồi tưởng. Dịch cả câu: Nhìn lại quãng thời gian trước đây, việc đầu tư sớm hơn vào giao thông công cộng đã có thể ngăn chặn nhiều vấn đề ùn tắc hiện tại của thành phố.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_21', 'en-c1-26', NULL, 'comprehensive_test', 'reading', NULL, 'Many workplaces have implicit expectations about overtime, which can make employees reluctant to leave on time.', 'Dựa vào câu trên, từ “implicit” có nghĩa phù hợp nhất là gì?', '["lan tràn; hoành hành; không kiểm soát được (thường mang nghĩa tiêu cực)","liều lĩnh; bất cẩn; không màng hậu quả","ngầm; ẩn ý; không nói ra","âm mưu; sự thông đồng"]'::jsonb, 2, 'implicit: ngầm; ẩn ý; không nói ra; tiềm ẩn; gắn liền; hoàn toàn; tuyệt đối (thường dùng để chỉ sự tin tưởng). Dịch cả câu: Nhiều nơi làm việc có những kỳ vọng ngầm về việc làm thêm giờ, điều này có thể khiến nhân viên thấy miễn cưỡng khi rời đi đúng giờ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_22', 'en-c1-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chỉ; hoàn toàn chỉ”', '["solely","iconic","palatable","lark"]'::jsonb, 0, 'chỉ; hoàn toàn chỉ → solely (/ˈsoʊlli/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_23', 'en-c1-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trong chừng mực mà; theo như”', '["insofar","precedence","ramification","chamber"]'::jsonb, 0, 'trong chừng mực mà; theo như → insofar (/ˌɪnsoʊˈfɑːr/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_26_24', 'en-c1-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chia nhỏ; phân nhỏ”', '["snobbish","deplete","mover","subdivide"]'::jsonb, 3, 'chia nhỏ; phân nhỏ → subdivide (/ˌsʌbdɪˈvaɪd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-27', 'en', 'Bài 27: Tư duy & Nhận thức (2) - CEFR C1', 'CEFR C1', 'C1 · Tư duy', '26 từ vựng Tiếng Anh CEFR C1 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5027, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disentangle', 'en-c1-27', 'disentangle', '/ˌdɪsɪnˈtæŋɡəl/', 'C1', 'gỡ rối; tháo gỡ; làm sáng tỏ; tách bạch', 'v.', 'disentanglement (n.), entangle (v.), entanglement (n.)', 'Đồng nghĩa: untangle, unravel · Trái nghĩa: entangle', 'Thường dùng cấu trúc disentangle A from B, diễn tả hành động tách rời hoặc gỡ ra.', 'I carefully disentangled the necklace from my headphones.', NULL, 'Tôi cẩn thận gỡ sợi dây chuyền ra khỏi dây tai nghe của mình.', '{"wordId":"disentangle","ukIpa":"/ˌdɪsɪnˈtæŋɡəl/","usIpa":"/ˌdɪsɪnˈtæŋɡəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To separate things that have become twisted or caught together.","vi":"gỡ rối; tháo gỡ"},{"pos":"v.","en":"To separate complicated issues or free someone from a difficult situation.","vi":"làm sáng tỏ; tách bạch"}],"examples":[{"en":"I carefully disentangled the necklace from my headphones.","vi":"Tôi cẩn thận gỡ sợi dây chuyền ra khỏi dây tai nghe của mình.","audioKind":"ex"},{"en":"Researchers must disentangle the effects of income and education when examining differences in public health.","vi":"Các nhà nghiên cứu phải tách bạch các tác động của thu nhập và giáo dục khi xem xét sự khác biệt về sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"disentangle cables","vi":"gỡ rối dây cáp"},{"en":"disentangle the effects of","vi":"làm sáng tỏ các ảnh hưởng của"},{"en":"disentangle yourself from","vi":"tự thoát khỏi"}],"wordFamily":["disentanglement (n.)","entangle (v.)","entanglement (n.)"],"synonyms":["untangle","unravel"],"antonyms":["entangle"],"tipVi":"Thường dùng cấu trúc disentangle A from B, diễn tả hành động tách rời hoặc gỡ ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deduction', 'en-c1-27', 'deduction', '/dɪˈdʌkʃən/', 'C1', 'sự suy luận; kết luận suy ra; khoản khấu trừ; sự khấu trừ', 'n.', 'deduce (v.), deduct (v.), deductive (adj.), deductible (adj.)', NULL, 'Từ suy luận tương ứng với động từ deduce; khoản khấu trừ tương ứng với động từ deduct.', 'Her deduction was simple: muddy shoes meant someone had visited.', NULL, 'Kết luận suy luận của cô ấy rất đơn giản: giày dính bùn có nghĩa là có ai đó đã ghé qua.', '{"wordId":"deduction","ukIpa":"/dɪˈdʌkʃən/","usIpa":"/dɪˈdʌkʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A conclusion reached through reasoning, or the reasoning process itself.","vi":"sự suy luận; kết luận suy ra"},{"pos":"n.","en":"An amount taken away from a total, or its removal.","vi":"khoản khấu trừ; sự khấu trừ"}],"examples":[{"en":"Her deduction was simple: muddy shoes meant someone had visited.","vi":"Kết luận suy luận của cô ấy rất đơn giản: giày dính bùn có nghĩa là có ai đó đã ghé qua.","audioKind":"ex"},{"en":"Employees should check each deduction from their salary to ensure that their final payment is accurate.","vi":"Nhân viên nên kiểm tra từng khoản khấu trừ trong tiền lương để đảm bảo rằng số tiền thực nhận cuối cùng là chính xác.","audioKind":"ex2"}],"collocations":[{"en":"logical deduction","vi":"suy luận logic"},{"en":"tax deduction","vi":"khoản khấu trừ thuế"},{"en":"deduction from pay","vi":"khoản khấu trừ từ tiền lương"}],"wordFamily":["deduce (v.)","deduct (v.)","deductive (adj.)","deductible (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ suy luận tương ứng với động từ deduce; khoản khấu trừ tương ứng với động từ deduct.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_integral', 'en-c1-27', 'integral', '/ˈɪntɪɡrəl/', 'C1', 'cần thiết để một sự việc được hoàn chỉnh hoặc hoạt động trơn tru; không thể thiếu; được tích hợp sẵn vào một cấu trúc thay vì được thêm vào một cách riêng lẻ; đại lượng toán học được tính bằng phép tích phân', 'adj.', 'integrate (v.), integration (n.), integrated (adj.)', 'Đồng nghĩa: essential, indispensable · Trái nghĩa: inessential', 'Thường đi kèm trong các cụm từ an integral part of hoặc be integral to.', 'Music is an integral part of our family celebrations.', NULL, 'Âm nhạc là một phần không thể thiếu trong các buổi lễ kỷ niệm của gia đình chúng tôi.', '{"wordId":"integral","ukIpa":"/ˈɪntɪɡrəl/","usIpa":"/ˈɪntɪɡrəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Necessary for something to be complete or work properly.","vi":"cần thiết để một sự việc được hoàn chỉnh hoặc hoạt động trơn tru; không thể thiếu"},{"pos":"adj.","en":"Built into something rather than added separately.","vi":"được tích hợp sẵn vào một cấu trúc thay vì được thêm vào một cách riêng lẻ"},{"pos":"n.","en":"A mathematical quantity calculated by integration.","vi":"đại lượng toán học được tính bằng phép tích phân"}],"examples":[{"en":"Music is an integral part of our family celebrations.","vi":"Âm nhạc là một phần không thể thiếu trong các buổi lễ kỷ niệm của gia đình chúng tôi.","audioKind":"ex"},{"en":"Reliable public transport is integral to sustainable urban development because it reduces dependence on private cars.","vi":"Hệ thống giao thông công cộng đáng tin cậy là yếu tố cốt lõi đối với sự phát triển đô thị bền vững vì nó làm giảm sự phụ thuộc vào xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"an integral part of","vi":"một phần không thể thiếu của"},{"en":"integral to success","vi":"tối quan trọng đối với sự thành công"},{"en":"an integral component","vi":"một thành phần cấu thành thiết yếu"}],"wordFamily":["integrate (v.)","integration (n.)","integrated (adj.)"],"synonyms":["essential","indispensable"],"antonyms":["inessential"],"tipVi":"Thường đi kèm trong các cụm từ an integral part of hoặc be integral to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contemplate', 'en-c1-27', 'contemplate', '/ˈkɑːntəmpleɪt/', 'C1', 'suy ngẫm kỹ lưỡng về điều gì đó trong một khoảng thời gian dài; cân nhắc việc làm gì đó trong tương lai; nhìn cái gì đó một cách lặng lẽ và trầm ngâm', 'v.', 'contemplation (n.), contemplative (adj.)', 'Đồng nghĩa: consider, ponder', 'Theo sau bởi danh từ hoặc danh động từ (V-ing), không đi kèm với to do.', 'She sat beside the lake, contemplating her next move.', NULL, 'Cô ấy ngồi bên bờ hồ, trầm ngâm suy nghĩ về bước đi tiếp theo của mình.', '{"wordId":"contemplate","ukIpa":"/ˈkɒntəmpleɪt/","usIpa":"/ˈkɑːntəmpleɪt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to think carefully about something for a long time","vi":"suy ngẫm kỹ lưỡng về điều gì đó trong một khoảng thời gian dài"},{"pos":"v.","en":"to consider doing something in the future","vi":"cân nhắc việc làm gì đó trong tương lai"},{"pos":"v.","en":"to look at something quietly and thoughtfully","vi":"nhìn cái gì đó một cách lặng lẽ và trầm ngâm"}],"examples":[{"en":"She sat beside the lake, contemplating her next move.","vi":"Cô ấy ngồi bên bờ hồ, trầm ngâm suy nghĩ về bước đi tiếp theo của mình.","audioKind":"ex"},{"en":"Before expanding public transport, planners should contemplate how proposed routes will affect existing communities.","vi":"Trước khi mở rộng hệ thống giao thông công cộng, các nhà quy hoạch nên cân nhắc kỹ lưỡng cách mà các tuyến đường được đề xuất sẽ ảnh hưởng đến các cộng đồng hiện hữu.","audioKind":"ex2"}],"collocations":[{"en":"contemplate doing something","vi":"cân nhắc làm việc gì đó"},{"en":"contemplate the future","vi":"suy ngẫm về tương lai"},{"en":"contemplate a change","vi":"cân nhắc thay đổi"}],"wordFamily":["contemplation (n.)","contemplative (adj.)"],"synonyms":["consider","ponder"],"antonyms":[],"tipVi":"Theo sau bởi danh từ hoặc danh động từ (V-ing), không đi kèm với to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_baffle', 'en-c1-27', 'baffle', '/ˈbæfəl/', 'C1', 'làm cho ai đó không thể hiểu hoặc giải thích được điều gì; gây bối rối, làm khó; vật cản dùng để kiểm soát dòng chảy của âm thanh, ánh sáng hoặc chất lỏng', 'v.', 'baffled (adj.), baffling (adj.)', 'Đồng nghĩa: puzzle, perplex · Trái nghĩa: enlighten', 'Mang sắc thái mạnh hơn confuse, nhấn mạnh việc hoàn toàn không thể thấu hiểu; thường dùng cấu trúc be baffled by.', 'This puzzle baffled me, so I asked for help.', NULL, 'Câu đố này làm tôi thấy khó hiểu quá, nên tôi đã phải nhờ giúp đỡ.', '{"wordId":"baffle","ukIpa":"/ˈbæfəl/","usIpa":"/ˈbæfəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To make someone unable to understand or explain something","vi":"làm cho ai đó không thể hiểu hoặc giải thích được điều gì; gây bối rối, làm khó"},{"pos":"n.","en":"A barrier controlling the flow of sound, light, or fluid","vi":"vật cản dùng để kiểm soát dòng chảy của âm thanh, ánh sáng hoặc chất lỏng"}],"examples":[{"en":"This puzzle baffled me, so I asked for help.","vi":"Câu đố này làm tôi thấy khó hiểu quá, nên tôi đã phải nhờ giúp đỡ.","audioKind":"ex"},{"en":"Unexpected changes in animal migration continue to baffle scientists despite improvements in tracking technology and data collection.","vi":"Những thay đổi bất ngờ trong tập tính di cư của động vật vẫn khiến các nhà khoa học đau đầu bất chấp những tiến bộ trong công nghệ theo dõi và thu thập dữ liệu.","audioKind":"ex2"}],"collocations":[{"en":"baffle scientists","vi":"làm các nhà khoa học bối rối"},{"en":"completely baffled","vi":"hoàn toàn bối rối, hoàn toàn không hiểu nổi"},{"en":"a baffling mystery","vi":"một bí ẩn khó hiểu"},{"en":"a baffle plate","vi":"tấm chắn, vách ngăn"}],"wordFamily":["baffled (adj.)","baffling (adj.)"],"synonyms":["puzzle","perplex"],"antonyms":["enlighten"],"tipVi":"Mang sắc thái mạnh hơn confuse, nhấn mạnh việc hoàn toàn không thể thấu hiểu; thường dùng cấu trúc be baffled by.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_envision', 'en-c1-27', 'envision', '/ɪnˈvɪʒən/', 'C1', 'hình dung; tưởng tượng; mường tượng', 'v.', NULL, 'Đồng nghĩa: envisage, imagine, foresee', 'Theo sau là danh từ hoặc danh động từ (V-ing), không đi với to do.', 'I envision a small garden behind our new house.', NULL, 'Tôi hình dung có một khu vườn nhỏ phía sau ngôi nhà mới của chúng tôi.', '{"wordId":"envision","ukIpa":"/ɪnˈvɪʒən/","usIpa":"/ɪnˈvɪʒən/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to imagine a future situation or possibility","vi":"hình dung; tưởng tượng; mường tượng"}],"examples":[{"en":"I envision a small garden behind our new house.","vi":"Tôi hình dung có một khu vườn nhỏ phía sau ngôi nhà mới của chúng tôi.","audioKind":"ex"},{"en":"Urban planners envision a future in which most residents can reach essential services on foot.","vi":"Các nhà quy hoạch đô thị đang mường tượng về một tương lai nơi phần lớn cư dân có thể tiếp cận các dịch vụ thiết yếu bằng cách đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"envision a future","vi":"vẽ ra viễn cảnh tương lai"},{"en":"envision doing something","vi":"hình dung làm việc gì"},{"en":"envision a world","vi":"mường tượng ra một thế giới"}],"wordFamily":[],"synonyms":["envisage","imagine","foresee"],"antonyms":[],"tipVi":"Theo sau là danh từ hoặc danh động từ (V-ing), không đi với to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foretell', 'en-c1-27', 'foretell', '/fɔːrˈtel/', 'C1', 'tiên đoán; báo trước', 'v.', NULL, 'Đồng nghĩa: predict, prophesy', 'Quá khứ và phân từ quá khứ đều là foretold; mang tính văn chương hơn predict.', 'Nobody could foretell how quickly the village would change.', NULL, 'Không ai có thể tiên đoán được ngôi làng sẽ thay đổi nhanh chóng đến nhường nào.', '{"wordId":"foretell","ukIpa":"/fɔːˈtel/","usIpa":"/fɔːrˈtel/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to say or indicate what will happen in the future","vi":"tiên đoán; báo trước"}],"examples":[{"en":"Nobody could foretell how quickly the village would change.","vi":"Không ai có thể tiên đoán được ngôi làng sẽ thay đổi nhanh chóng đến nhường nào.","audioKind":"ex"},{"en":"Although historical patterns offer useful insights, they cannot reliably foretell the outcomes of future economic policies.","vi":"Mặc dù các quy luật lịch sử cung cấp những góc nhìn hữu ích, chúng không thể dự báo một cách đáng tin cậy kết quả của các chính sách kinh tế trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"foretell the future","vi":"tiên đoán tương lai"},{"en":"foretell disaster","vi":"báo trước thảm họa"}],"wordFamily":[],"synonyms":["predict","prophesy"],"antonyms":[],"tipVi":"Quá khứ và phân từ quá khứ đều là foretold; mang tính văn chương hơn predict.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_notwithstanding', 'en-c1-27', 'notwithstanding', '/ˌnɑːtwɪðˈstændɪŋ/', 'C1', 'mặc dù; dẫu cho; tuy nhiên; dẫu thế', 'prep.', NULL, 'Đồng nghĩa: despite, nevertheless', 'Là từ mang phong cách trang trọng; khi đóng vai trò giới thiệu có thể đặt trước hoặc sau danh từ, ví dụ như the rain notwithstanding.', 'Notwithstanding the rain, we enjoyed our walk by the river.', NULL, 'Mặc dù trời mưa, chúng tôi vẫn tận hưởng buổi đi dạo bên bờ sông.', '{"wordId":"notwithstanding","ukIpa":"/ˌnɒtwɪðˈstændɪŋ/","usIpa":"/ˌnɑːtwɪðˈstændɪŋ/","cefr":"C1","topic":"thinking","senses":[{"pos":"prep.","en":"despite something that might prevent or contradict something else","vi":"mặc dù; dẫu cho"},{"pos":"adv.","en":"despite what has just been mentioned","vi":"tuy nhiên; dẫu thế"}],"examples":[{"en":"Notwithstanding the rain, we enjoyed our walk by the river.","vi":"Mặc dù trời mưa, chúng tôi vẫn tận hưởng buổi đi dạo bên bờ sông.","audioKind":"ex"},{"en":"Notwithstanding its initial costs, investment in renewable energy can provide substantial economic and environmental benefits over time.","vi":"Mặc dù chi phí ban đầu cao, việc đầu tư vào năng lượng tái tạo có thể mang lại lợi ích kinh tế và môi trường đáng kể về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"notwithstanding the fact that","vi":"mặc dù thực tế là"},{"en":"notwithstanding these difficulties","vi":"bất chấp những khó khăn này"},{"en":"these concerns notwithstanding","vi":"dù có những lo ngại đó"}],"wordFamily":[],"synonyms":["despite","nevertheless"],"antonyms":[],"tipVi":"Là từ mang phong cách trang trọng; khi đóng vai trò giới thiệu có thể đặt trước hoặc sau danh từ, ví dụ như the rain notwithstanding.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concur', 'en-c1-27', 'concur', '/kənˈkɝː/', 'C1', 'đồng tình; tán thành; có cùng ý kiến', 'v.', 'concurrence (n.)', 'Đồng nghĩa: agree · Trái nghĩa: disagree, dissent', 'Là từ mang phong cách trang trọng, thường dùng cấu trúc concur with ai đó hoặc concur that theo sau mệnh đề.', 'I concur with your suggestion to leave before lunch.', NULL, 'Tôi đồng ý với đề xuất của bạn về việc xuất phát trước bữa trưa.', '{"wordId":"concur","ukIpa":"/kənˈkɜː/","usIpa":"/kənˈkɝː/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to agree with someone or share the same opinion","vi":"đồng tình; tán thành; có cùng ý kiến"}],"examples":[{"en":"I concur with your suggestion to leave before lunch.","vi":"Tôi đồng ý với đề xuất của bạn về việc xuất phát trước bữa trưa.","audioKind":"ex"},{"en":"Most researchers concur that investment in early childhood education brings substantial benefits to society.","vi":"Hầu hết các nhà nghiên cứu đều thống nhất rằng việc đầu tư vào giáo dục mầm non mang lại những lợi ích to lớn cho xã hội.","audioKind":"ex2"}],"collocations":[{"en":"concur with someone","vi":"đồng tình với ai đó"},{"en":"concur that","vi":"đồng ý rằng"},{"en":"concur in a decision","vi":"tán thành một quyết định"}],"wordFamily":["concurrence (n.)"],"synonyms":["agree"],"antonyms":["disagree","dissent"],"tipVi":"Là từ mang phong cách trang trọng, thường dùng cấu trúc concur with ai đó hoặc concur that theo sau mệnh đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cardinal', 'en-c1-27', 'cardinal', '/ˈkɑːrdɪnəl/', 'C1', 'chủ yếu; cốt lõi; quan trọng nhất; hồng y giáo chủ; chim hồng tước Bắc Mỹ', 'adj.', NULL, 'Đồng nghĩa: fundamental, principal, essential · Trái nghĩa: minor, secondary', 'cardinal number là số đếm, ordinal number là số thứ tự.', 'Our cardinal rule is to leave nobody behind.', NULL, 'Quy tắc tối quan trọng của chúng tôi là không bỏ lại bất kỳ ai.', '{"wordId":"cardinal","ukIpa":"/ˈkɑːdɪnəl/","usIpa":"/ˈkɑːrdɪnəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Of central importance to a system, belief, or activity.","vi":"chủ yếu; cốt lõi; quan trọng nhất"},{"pos":"n.","en":"A senior Catholic official who helps elect the pope.","vi":"hồng y giáo chủ"},{"pos":"n.","en":"A North American bird whose male has bright red feathers.","vi":"chim hồng tước Bắc Mỹ"}],"examples":[{"en":"Our cardinal rule is to leave nobody behind.","vi":"Quy tắc tối quan trọng của chúng tôi là không bỏ lại bất kỳ ai.","audioKind":"ex"},{"en":"Protecting patient privacy should remain a cardinal principle when hospitals introduce new digital record systems.","vi":"Việc bảo vệ quyền riêng tư của bệnh nhân phải luôn là nguyên tắc cơ bản khi các bệnh viện giới thiệu hệ thống hồ sơ kỹ thuật số mới.","audioKind":"ex2"}],"collocations":[{"en":"cardinal rule","vi":"quy tắc tối quan trọng"},{"en":"cardinal principle","vi":"nguyên tắc cơ bản"},{"en":"cardinal error","vi":"sai lầm chí mạng"},{"en":"cardinal number","vi":"số đếm"}],"wordFamily":[],"synonyms":["fundamental","principal","essential"],"antonyms":["minor","secondary"],"tipVi":"cardinal number là số đếm, ordinal number là số thứ tự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fallacy', 'en-c1-27', 'fallacy', '/ˈfæləsi/', 'C1', 'ngụy biện; quan niệm sai lầm; lỗi suy luận', 'n.', 'fallacious (adj.), fallaciously (adv.)', 'Đồng nghĩa: misconception, misbelief', 'Không chỉ là lỗi sai về thực tế, mà còn thường chỉ lỗi logic trong lập luận.', 'It is a fallacy that expensive shoes always last longer.', NULL, 'Quan niệm cho rằng giày đắt tiền luôn bền hơn là một điều sai lầm.', '{"wordId":"fallacy","ukIpa":"/ˈfæləsi/","usIpa":"/ˈfæləsi/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A belief that is commonly accepted but actually false.","vi":"ngụy biện; quan niệm sai lầm"},{"pos":"n.","en":"An error in reasoning that makes an argument unreliable.","vi":"lỗi suy luận"}],"examples":[{"en":"It is a fallacy that expensive shoes always last longer.","vi":"Quan niệm cho rằng giày đắt tiền luôn bền hơn là một điều sai lầm.","audioKind":"ex"},{"en":"The claim that economic growth automatically benefits every citizen rests on a fallacy about how wealth is distributed.","vi":"Lập luận cho rằng tăng trưởng kinh tế tự động mang lại lợi ích cho mọi công dân dựa trên một ngụy biện về cách phân phối của cải.","audioKind":"ex2"}],"collocations":[{"en":"a common fallacy","vi":"quan niệm sai lầm phổ biến"},{"en":"a logical fallacy","vi":"lỗi ngụy biện logic"},{"en":"expose a fallacy","vi":"vạch trần một ngụy biện"}],"wordFamily":["fallacious (adj.)","fallaciously (adv.)"],"synonyms":["misconception","misbelief"],"antonyms":[],"tipVi":"Không chỉ là lỗi sai về thực tế, mà còn thường chỉ lỗi logic trong lập luận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conceive', 'en-c1-27', 'conceive', '/kənˈsiːv/', 'C1', 'hình thành ý tưởng; tưởng tượng; thụ thai; mang thai', 'v.', 'conception (n.), conceivable (adj.), conceivably (adv.), inconceivable (adj.)', 'Đồng nghĩa: imagine, devise', 'conceive an idea chỉ việc hình thành ý tưởng; conceive of chỉ việc tưởng tượng hoặc suy nghĩ về cái gì.', 'She conceived the idea while walking through the park.', NULL, 'Cô ấy nảy ra ý tưởng đó trong lúc đi dạo qua công viên.', '{"wordId":"conceive","ukIpa":"/kənˈsiːv/","usIpa":"/kənˈsiːv/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to form an idea or imagine something","vi":"hình thành ý tưởng; tưởng tượng"},{"pos":"v.","en":"to become pregnant or cause a baby to begin developing","vi":"thụ thai; mang thai"}],"examples":[{"en":"She conceived the idea while walking through the park.","vi":"Cô ấy nảy ra ý tưởng đó trong lúc đi dạo qua công viên.","audioKind":"ex"},{"en":"Urban planners must conceive new ways of accommodating population growth without sacrificing green spaces or affordable housing.","vi":"Các nhà quy hoạch đô thị phải nghĩ ra những phương thức mới để đáp ứng sự bùng nổ dân số mà không làm mất đi không gian xanh hoặc nhà ở giá rẻ.","audioKind":"ex2"}],"collocations":[{"en":"conceive an idea","vi":"nảy ra một ý tưởng"},{"en":"conceive of","vi":"tưởng tượng; hình dung"},{"en":"conceive a child","vi":"thụ thai một đứa con"}],"wordFamily":["conception (n.)","conceivable (adj.)","conceivably (adv.)","inconceivable (adj.)"],"synonyms":["imagine","devise"],"antonyms":[],"tipVi":"conceive an idea chỉ việc hình thành ý tưởng; conceive of chỉ việc tưởng tượng hoặc suy nghĩ về cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clarity', 'en-c1-27', 'clarity', '/ˈklærəti/', 'C1', 'sự rõ ràng; dễ hiểu; sự trong trẻo; độ rõ nét', 'n.', 'clear (adj.), clearly (adv.), clarify (v.), clarification (n.)', 'Đồng nghĩa: clearness, lucidity · Trái nghĩa: ambiguity, vagueness', 'Đây là danh từ không đếm được; clarify là động từ có nghĩa là làm sáng tỏ.', 'I appreciate the clarity of your instructions for this game.', NULL, 'Tôi đánh giá cao sự rõ ràng trong hướng dẫn trò chơi này của bạn.', '{"wordId":"clarity","ukIpa":"/ˈklærəti/","usIpa":"/ˈklærəti/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"The quality of being clear and easy to understand.","vi":"sự rõ ràng; dễ hiểu"},{"pos":"n.","en":"The quality of being easy to see or hear through.","vi":"sự trong trẻo; độ rõ nét"}],"examples":[{"en":"I appreciate the clarity of your instructions for this game.","vi":"Tôi đánh giá cao sự rõ ràng trong hướng dẫn trò chơi này của bạn.","audioKind":"ex"},{"en":"Greater clarity in public health advice can help people make informed decisions about their daily habits.","vi":"Sự rõ ràng hơn trong các khuyến nghị y tế cộng đồng có thể giúp mọi người đưa ra những quyết định sáng suốt về thói quen sinh hoạt hằng ngày.","audioKind":"ex2"}],"collocations":[{"en":"clarity of thought","vi":"tư duy minh mẫn"},{"en":"for clarity","vi":"để làm rõ vấn đề"},{"en":"lack of clarity","vi":"sự thiếu rõ ràng"},{"en":"crystal clarity","vi":"độ trong suốt tuyệt đối"}],"wordFamily":["clear (adj.)","clearly (adv.)","clarify (v.)","clarification (n.)"],"synonyms":["clearness","lucidity"],"antonyms":["ambiguity","vagueness"],"tipVi":"Đây là danh từ không đếm được; clarify là động từ có nghĩa là làm sáng tỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_formulation', 'en-c1-27', 'formulation', '/ˌfɔːrmjəˈleɪʃən/', 'C1', 'sự xây dựng; quá trình hoạch định; cách diễn đạt; công thức diễn đạt; công thức; chế phẩm', 'n.', 'formulate (v.), reformulate (v.), reformulation (n.)', NULL, 'Thường đi với cụm the formulation of để chỉ việc thiết lập một kế hoạch hay lý thuyết.', 'The whole team contributed to the formulation of our plan.', NULL, 'Toàn bộ đội ngũ đã đóng góp vào quá trình hoạch định kế hoạch của chúng tôi.', '{"wordId":"formulation","ukIpa":"/ˌfɔːmjuˈleɪʃən/","usIpa":"/ˌfɔːrmjəˈleɪʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"The process of developing a plan, policy, or theory.","vi":"sự xây dựng; quá trình hoạch định"},{"pos":"n.","en":"A particular way of expressing an idea precisely.","vi":"cách diễn đạt; công thức diễn đạt"},{"pos":"n.","en":"A mixture prepared for a particular purpose.","vi":"công thức; chế phẩm"}],"examples":[{"en":"The whole team contributed to the formulation of our plan.","vi":"Toàn bộ đội ngũ đã đóng góp vào quá trình hoạch định kế hoạch của chúng tôi.","audioKind":"ex"},{"en":"Effective policy formulation requires reliable evidence and meaningful consultation with the communities most likely to be affected.","vi":"Quá trình hoạch định chính sách hiệu quả đòi hỏi các bằng chứng đáng tin cậy và sự tham vấn ý nghĩa với những cộng đồng có nhiều khả năng bị ảnh hưởng nhất.","audioKind":"ex2"}],"collocations":[{"en":"policy formulation","vi":"hoạch định chính sách"},{"en":"the formulation of a theory","vi":"sự xây dựng một lý thuyết"},{"en":"a precise formulation","vi":"cách diễn đạt chính xác"},{"en":"a new formulation","vi":"công thức mới"}],"wordFamily":["formulate (v.)","reformulate (v.)","reformulation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi với cụm the formulation of để chỉ việc thiết lập một kế hoạch hay lý thuyết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perpetual', 'en-c1-27', 'perpetual', '/pərˈpetʃuəl/', 'C1', 'vĩnh viễn; liên tục; lặp đi lặp lại; phiền toái', 'adj.', 'perpetually (adv.)', 'Đồng nghĩa: constant, ceaseless · Trái nghĩa: temporary', 'Có thể chỉ sự việc kéo dài mãi mãi, hoặc dùng theo nghĩa phóng đại để chỉ điều gì cứ lặp đi lặp lại gây khó chịu.', 'The dripping tap is a source of perpetual irritation.', NULL, 'Vòi nước rò rỉ liên tục là nguyên nhân gây phiền toái mãi không dứt.', '{"wordId":"perpetual","ukIpa":"/pəˈpetʃuəl/","usIpa":"/pərˈpetʃuəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"continuing all the time or lasting forever","vi":"vĩnh viễn; liên tục"},{"pos":"adj.","en":"happening repeatedly, often in an annoying way","vi":"lặp đi lặp lại; phiền toái"}],"examples":[{"en":"The dripping tap is a source of perpetual irritation.","vi":"Vòi nước rò rỉ liên tục là nguyên nhân gây phiền toái mãi không dứt.","audioKind":"ex"},{"en":"The pursuit of perpetual economic growth raises questions about how societies can protect limited natural resources.","vi":"Việc theo đuổi tăng trưởng kinh tế liên tục đặt ra nhiều câu hỏi về cách các xã hội bảo vệ các nguồn tài nguyên thiên nhiên hạn hẹp.","audioKind":"ex2"}],"collocations":[{"en":"perpetual motion","vi":"chuyển động vĩnh cửu"},{"en":"perpetual change","vi":"sự thay đổi không ngừng"},{"en":"perpetual conflict","vi":"xung đột kéo dài"}],"wordFamily":["perpetually (adv.)"],"synonyms":["constant","ceaseless"],"antonyms":["temporary"],"tipVi":"Có thể chỉ sự việc kéo dài mãi mãi, hoặc dùng theo nghĩa phóng đại để chỉ điều gì cứ lặp đi lặp lại gây khó chịu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refute', 'en-c1-27', 'refute', '/rɪˈfjuːt/', 'C1', 'bác bỏ; chứng minh là sai', 'v.', 'refutation (n.), refutable (adj.)', 'Đồng nghĩa: disprove, rebut · Trái nghĩa: confirm, substantiate', 'Nhấn mạnh dùng bằng chứng để chứng minh điều gì là sai, không chỉ đơn thuần là bày tỏ sự không đồng tình.', 'These photos refute the claim that our gate was broken.', NULL, 'Những bức ảnh này bác bỏ tuyên bố cho rằng cổng của chúng tôi đã bị hỏng.', '{"wordId":"refute","ukIpa":"/rɪˈfjuːt/","usIpa":"/rɪˈfjuːt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to prove that a statement or argument is wrong","vi":"bác bỏ; chứng minh là sai"}],"examples":[{"en":"These photos refute the claim that our gate was broken.","vi":"Những bức ảnh này bác bỏ tuyên bố cho rằng cổng của chúng tôi đã bị hỏng.","audioKind":"ex"},{"en":"Reliable scientific evidence can refute misleading claims about nutrition and help consumers make informed dietary choices.","vi":"Bằng chứng khoa học đáng tin cậy có thể bác bỏ những tuyên bố sai lệch về dinh dưỡng và giúp người tiêu dùng đưa ra lựa chọn ăn uống sáng suốt.","audioKind":"ex2"}],"collocations":[{"en":"refute a claim","vi":"bác bỏ một tuyên bố"},{"en":"refute an argument","vi":"bác bỏ một luận điểm"},{"en":"refute an allegation","vi":"bác bỏ một cáo buộc"}],"wordFamily":["refutation (n.)","refutable (adj.)"],"synonyms":["disprove","rebut"],"antonyms":["confirm","substantiate"],"tipVi":"Nhấn mạnh dùng bằng chứng để chứng minh điều gì là sai, không chỉ đơn thuần là bày tỏ sự không đồng tình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_justification', 'en-c1-27', 'justification', '/ˌdʒʌstəfɪˈkeɪʃən/', 'C1', 'sự biện minh; lý do chính đáng; căn cứ hợp lý', 'n.', 'justify (v.), justifiable (adj.), justifiably (adv.), justified (adj.)', 'Đồng nghĩa: grounds, rationale', 'Thường đi với giới từ for theo sau bởi danh từ hoặc danh động từ để giải thích lý do.', 'There is no justification for leaving this mess behind.', NULL, 'Chẳng có lý do gì để bỏ lại bãi chiến tàn này mà không dọn dẹp cả.', '{"wordId":"justification","ukIpa":"/ˌdʒʌstɪfɪˈkeɪʃən/","usIpa":"/ˌdʒʌstəfɪˈkeɪʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A good reason explaining why something is acceptable or necessary.","vi":"sự biện minh; lý do chính đáng; căn cứ hợp lý"}],"examples":[{"en":"There is no justification for leaving this mess behind.","vi":"Chẳng có lý do gì để bỏ lại bãi chiến tàn này mà không dọn dẹp cả.","audioKind":"ex"},{"en":"Governments must provide clear justification for policies that restrict individual freedom in the interests of public safety.","vi":"Chính phủ phải đưa ra lý do chính đáng và rõ ràng cho các chính sách hạn chế quyền tự do cá nhân vì lợi ích an toàn công cộng.","audioKind":"ex2"}],"collocations":[{"en":"justification for","vi":"lý do chính đáng cho"},{"en":"provide justification","vi":"cung cấp căn cứ hợp lý"},{"en":"little justification","vi":"hầu như không có lý do xác đáng"},{"en":"economic justification","vi":"cơ sở kinh tế hợp lý"}],"wordFamily":["justify (v.)","justifiable (adj.)","justifiably (adv.)","justified (adj.)"],"synonyms":["grounds","rationale"],"antonyms":[],"tipVi":"Thường đi với giới từ for theo sau bởi danh từ hoặc danh động từ để giải thích lý do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lofty', 'en-c1-27', 'lofty', '/ˈlɔːfti/', 'C1', 'cao cả; đầy hoài bão lớn lao; cao vút; sừng sững; kiêu ngạo; trịch thượng', 'adj.', 'loftiness (n.), loftily (adv.)', 'Đồng nghĩa: elevated, noble, towering · Trái nghĩa: lowly', 'Khi bổ nghĩa cho lý tưởng, từ này có thể mang ý nghĩa ngợi khen, nhưng đôi khi cũng ngầm chỉ mục tiêu quá cao, thiếu thực tế.', 'She has lofty ambitions but works hard every day.', NULL, 'Cô ấy có những hoài bão lớn lao nhưng vẫn làm việc chăm chỉ mỗi ngày.', '{"wordId":"lofty","ukIpa":"/ˈlɒfti/","usIpa":"/ˈlɔːfti/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Aiming for morally admirable or very ambitious achievements.","vi":"cao cả; đầy hoài bão lớn lao"},{"pos":"adj.","en":"Rising to a great height.","vi":"cao vút; sừng sững"},{"pos":"adj.","en":"Showing a belief that you are better than others.","vi":"kiêu ngạo; trịch thượng"}],"examples":[{"en":"She has lofty ambitions but works hard every day.","vi":"Cô ấy có những hoài bão lớn lao nhưng vẫn làm việc chăm chỉ mỗi ngày.","audioKind":"ex"},{"en":"Governments often announce lofty goals for reducing inequality, but meaningful progress requires sustained investment and practical policies.","vi":"Các chính phủ thường công bố những mục tiêu cao cả nhằm giảm bạo lực bất bình đẳng, nhưng tiến bộ thực chất đòi hỏi sự đầu tư bền vững và các chính sách thiết thực.","audioKind":"ex2"}],"collocations":[{"en":"lofty ideals","vi":"lý tưởng cao cả"},{"en":"lofty ambitions","vi":"hoài bão lớn lao"},{"en":"lofty goals","vi":"mục tiêu to lớn"},{"en":"lofty ceiling","vi":"trần nhà cao vút"}],"wordFamily":["loftiness (n.)","loftily (adv.)"],"synonyms":["elevated","noble","towering"],"antonyms":["lowly"],"tipVi":"Khi bổ nghĩa cho lý tưởng, từ này có thể mang ý nghĩa ngợi khen, nhưng đôi khi cũng ngầm chỉ mục tiêu quá cao, thiếu thực tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proposition', 'en-c1-27', 'proposition', '/ˌprɑːpəˈzɪʃən/', 'C1', 'ý kiến đề xuất; ý kiến bàn; mệnh đề; quan điểm', 'n.', 'propose (v.), proposal (n.)', 'Đồng nghĩa: proposal, suggestion', 'Khi mang nghĩa "mệnh đề/chủ trương", từ này có thể đi với mệnh đề that; đối với "đề xuất", thường dùng proposal.', 'Your proposition sounds sensible, but we need more time.', NULL, 'Đề xuất của bạn nghe có vẻ hợp lý, nhưng chúng tôi cần thêm thời gian.', '{"wordId":"proposition","ukIpa":"/ˌprɒpəˈzɪʃən/","usIpa":"/ˌprɑːpəˈzɪʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"An idea or plan offered for consideration","vi":"ý kiến đề xuất; ý kiến bàn"},{"pos":"n.","en":"A statement that can be examined as true or false","vi":"mệnh đề; quan điểm"}],"examples":[{"en":"Your proposition sounds sensible, but we need more time.","vi":"Đề xuất của bạn nghe có vẻ hợp lý, nhưng chúng tôi cần thêm thời gian.","audioKind":"ex"},{"en":"The proposition that smaller classes always improve learning outcomes requires careful evaluation across different educational contexts.","vi":"Quan điểm cho rằng quy mô lớp học nhỏ hơn luôn cải thiện kết quả học tập đòi hỏi phải được đánh giá cẩn thận trong các bối cảnh giáo dục khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a business proposition","vi":"đề xuất kinh doanh"},{"en":"an attractive proposition","vi":"một đề xuất hấp dẫn"},{"en":"support a proposition","vi":"ủng hộ một quan điểm"}],"wordFamily":["propose (v.)","proposal (n.)"],"synonyms":["proposal","suggestion"],"antonyms":[],"tipVi":"Khi mang nghĩa \"mệnh đề/chủ trương\", từ này có thể đi với mệnh đề that; đối với \"đề xuất\", thường dùng proposal.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preoccupy', 'en-c1-27', 'preoccupy', '/priˈɑːkjupaɪ/', 'C1', 'chiếm lĩnh tâm trí; làm bận tâm; chi phối suy nghĩ', 'v.', 'preoccupied (adj.), preoccupation (n.)', 'Đồng nghĩa: absorb, engross', 'Thường dùng cấu trúc be preoccupied with để chỉ việc tâm trí bị chi phối bởi một vấn đề nào đó.', 'Thoughts of tomorrow''s interview preoccupied her throughout dinner.', NULL, 'Những suy nghĩ về buổi phỏng vấn ngày mai đã chiếm trọn tâm trí cô ấy suốt bữa tối.', '{"wordId":"preoccupy","ukIpa":"/priˈɒkjupaɪ/","usIpa":"/priˈɑːkjupaɪ/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to fill someone''s thoughts, leaving little attention for other things","vi":"chiếm lĩnh tâm trí; làm bận tâm; chi phối suy nghĩ"}],"examples":[{"en":"Thoughts of tomorrow''s interview preoccupied her throughout dinner.","vi":"Những suy nghĩ về buổi phỏng vấn ngày mai đã chiếm trọn tâm trí cô ấy suốt bữa tối.","audioKind":"ex"},{"en":"Concerns about housing costs increasingly preoccupy young adults, influencing their career choices and family plans.","vi":"Những lo lắng về chi phí nhà ở ngày càng chi phối suy nghĩ của giới trẻ, ảnh hưởng đến lựa chọn nghề nghiệp và kế hoạch gia đình của họ.","audioKind":"ex2"}],"collocations":[{"en":"be preoccupied with work","vi":"bận tâm với công việc"},{"en":"preoccupy someone''s mind","vi":"chiếm trọn tâm trí ai đó"}],"wordFamily":["preoccupied (adj.)","preoccupation (n.)"],"synonyms":["absorb","engross"],"antonyms":[],"tipVi":"Thường dùng cấu trúc be preoccupied with để chỉ việc tâm trí bị chi phối bởi một vấn đề nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inclined', 'en-c1-27', 'inclined', '/ɪnˈklaɪnd/', 'C1', 'có xu hướng; có ý muốn; nghiêng về; dốc; nghiêng', 'adj.', 'incline (v.), inclination (n.)', 'Đồng nghĩa: disposed, willing · Trái nghĩa: disinclined', 'Cấu trúc be inclined to đi với động từ nguyên thể, diễn tả sự nghiêng về một phía hoặc có ý muốn làm gì.', 'I''m inclined to stay home and cook tonight.', NULL, 'Tôi có ý định ở nhà tự nấu ăn tối nay.', '{"wordId":"inclined","ukIpa":"/ɪnˈklaɪnd/","usIpa":"/ɪnˈklaɪnd/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Likely or willing to think or act a certain way.","vi":"có xu hướng; có ý muốn; nghiêng về"},{"pos":"adj.","en":"Sloping rather than horizontal or vertical.","vi":"dốc; nghiêng"}],"examples":[{"en":"I''m inclined to stay home and cook tonight.","vi":"Tôi có ý định ở nhà tự nấu ăn tối nay.","audioKind":"ex"},{"en":"Consumers may be more inclined to repair appliances when affordable local repair services are readily available.","vi":"Người tiêu dùng có thể sẽ có xu hướng muốn sửa chữa thiết bị hơn khi có sẵn dịch vụ sửa chữa địa phương giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"be inclined to agree","vi":"có xu hướng đồng tình"},{"en":"feel inclined to","vi":"có hứng thú muốn làm gì"},{"en":"an inclined plane","vi":"mặt phẳng nghiêng"}],"wordFamily":["incline (v.)","inclination (n.)"],"synonyms":["disposed","willing"],"antonyms":["disinclined"],"tipVi":"Cấu trúc be inclined to đi với động từ nguyên thể, diễn tả sự nghiêng về một phía hoặc có ý muốn làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_analytic', 'en-c1-27', 'analytic', '/ˌænəˈlɪtɪk/', 'C1', 'mang tính phân tích; có tư duy phân tích', 'adj.', 'analyse (v.), analysis (n.), analytical (adj.), analytically (adv.)', 'Đồng nghĩa: analytical', 'Có nghĩa gần giống với analytical; tuy nhiên trong giao tiếp hàng ngày khi mô tả năng lực phân tích thì từ analytical được dùng phổ biến hơn.', 'Her analytic approach helped us understand our monthly spending.', NULL, 'Phương pháp phân tích của cô ấy đã giúp chúng tôi hiểu rõ các khoản chi tiêu hàng tháng của mình.', '{"wordId":"analytic","ukIpa":"/ˌænəˈlɪtɪk/","usIpa":"/ˌænəˈlɪtɪk/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"using careful examination of details to understand something","vi":"mang tính phân tích; có tư duy phân tích"}],"examples":[{"en":"Her analytic approach helped us understand our monthly spending.","vi":"Phương pháp phân tích của cô ấy đã giúp chúng tôi hiểu rõ các khoản chi tiêu hàng tháng của mình.","audioKind":"ex"},{"en":"Schools should develop students'' analytic skills so they can evaluate evidence and recognise weaknesses in public arguments.","vi":"Các trường học nên phát triển các kỹ năng phân tích của học sinh để các em có thể đánh giá bằng chứng và nhận ra những điểm yếu trong các tranh luận công khai.","audioKind":"ex2"}],"collocations":[{"en":"analytic approach","vi":"phương pháp phân tích"},{"en":"analytic skills","vi":"kỹ năng phân tích"},{"en":"analytic framework","vi":"khung phân tích"}],"wordFamily":["analyse (v.)","analysis (n.)","analytical (adj.)","analytically (adv.)"],"synonyms":["analytical"],"antonyms":[],"tipVi":"Có nghĩa gần giống với analytical; tuy nhiên trong giao tiếp hàng ngày khi mô tả năng lực phân tích thì từ analytical được dùng phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discrepancy', 'en-c1-27', 'discrepancy', '/dɪˈskrepənsi/', 'C1', 'sự sai lệch; sự không nhất quán; sự khác biệt', 'n.', NULL, 'Đồng nghĩa: inconsistency, mismatch · Trái nghĩa: agreement, consistency', 'Thường chỉ những điểm vốn phải khớp nhau nhưng lại không trùng khớp, đi với giới từ between hoặc in.', 'We noticed a discrepancy between the two shopping receipts.', NULL, 'Chúng tôi nhận thấy có sự khác biệt giữa hai hóa đơn mua sắm.', '{"wordId":"discrepancy","ukIpa":"/dɪˈskrepənsi/","usIpa":"/dɪˈskrepənsi/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A difference between things that should match.","vi":"sự sai lệch; sự không nhất quán; sự khác biệt"}],"examples":[{"en":"We noticed a discrepancy between the two shopping receipts.","vi":"Chúng tôi nhận thấy có sự khác biệt giữa hai hóa đơn mua sắm.","audioKind":"ex"},{"en":"The discrepancy between official figures and survey results raises concerns about the accuracy of employment statistics.","vi":"Sự chênh lệch giữa số liệu chính thức và kết quả khảo sát làm dấy lên lo ngại về độ chính xác của thống kê việc làm.","audioKind":"ex2"}],"collocations":[{"en":"a discrepancy between","vi":"sự khác biệt giữa"},{"en":"a significant discrepancy","vi":"sự sai lệch đáng kể"},{"en":"explain a discrepancy","vi":"giải thích sự khác biệt"}],"wordFamily":[],"synonyms":["inconsistency","mismatch"],"antonyms":["agreement","consistency"],"tipVi":"Thường chỉ những điểm vốn phải khớp nhau nhưng lại không trùng khớp, đi với giới từ between hoặc in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_premise', 'en-c1-27', 'premise', '/ˈpremɪs/', 'C1', 'tiền đề; giả định; cơ ngơi; nhà cửa và đất đai', 'n.', NULL, 'Đồng nghĩa: assumption', 'Biểu thị nhà cửa và khuôn viên khi dùng số nhiều premises.', 'Your plan rests on the premise that everyone agrees.', NULL, 'Kế hoạch của bạn dựa trên tiền đề rằng mọi người đều đồng ý.', '{"wordId":"premise","ukIpa":"/ˈpremɪs/","usIpa":"/ˈpremɪs/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"an idea accepted as the basis for reasoning or action","vi":"tiền đề; giả định"},{"pos":"n.","en":"the buildings and land used by a business or organization","vi":"cơ ngơi; nhà cửa và đất đai"}],"examples":[{"en":"Your plan rests on the premise that everyone agrees.","vi":"Kế hoạch của bạn dựa trên tiền đề rằng mọi người đều đồng ý.","audioKind":"ex"},{"en":"The policy is based on the premise that affordable education improves both individual prospects and national productivity.","vi":"Chính sách này dựa trên tiền đề rằng giáo dục vừa túi tiền giúp cải thiện triển vọng cá nhân và nâng cao năng suất quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"basic premise","vi":"tiền đề cơ bản"},{"en":"on the premise that","vi":"với tiền đề rằng"},{"en":"business premises","vi":"trụ sở kinh doanh"},{"en":"on the premises","vi":"tại khuôn viên; trong cơ ngơi"}],"wordFamily":[],"synonyms":["assumption"],"antonyms":[],"tipVi":"Biểu thị nhà cửa và khuôn viên khi dùng số nhiều premises.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fallible', 'en-c1-27', 'fallible', '/ˈfæləbəl/', 'C1', 'có thể sai lầm; dễ mắc lỗi', 'adj.', 'fallibility (n.), infallible (adj.), infallibility (n.)', 'Đồng nghĩa: imperfect, error-prone · Trái nghĩa: infallible', 'Nhấn mạnh khả năng mắc lỗi, không phải lúc nào cũng chắc chắn sai; từ trái nghĩa là infallible.', 'Even experienced drivers are fallible, so please stay alert.', NULL, 'Ngay cả những tài xế lâu năm cũng có thể mắc sai lầm, vì vậy xin hãy luôn cảnh giác.', '{"wordId":"fallible","ukIpa":"/ˈfælɪbəl/","usIpa":"/ˈfæləbəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Capable of making mistakes or being wrong","vi":"có thể sai lầm; dễ mắc lỗi"}],"examples":[{"en":"Even experienced drivers are fallible, so please stay alert.","vi":"Ngay cả những tài xế lâu năm cũng có thể mắc sai lầm, vì vậy xin hãy luôn cảnh giác.","audioKind":"ex"},{"en":"Human memory is fallible, which raises concerns about relying solely on eyewitness accounts in court.","vi":"Trí nhớ con người vốn có thể sai sót, điều này dấy lên những lo ngại về việc chỉ dựa hoàn toàn vào lời kể của nhân chứng tại tòa.","audioKind":"ex2"}],"collocations":[{"en":"fallible human judgement","vi":"phán đoán mang tính chủ quan của con người"},{"en":"a fallible system","vi":"một hệ thống dễ xảy ra sai sót"}],"wordFamily":["fallibility (n.)","infallible (adj.)","infallibility (n.)"],"synonyms":["imperfect","error-prone"],"antonyms":["infallible"],"tipVi":"Nhấn mạnh khả năng mắc lỗi, không phải lúc nào cũng chắc chắn sai; từ trái nghĩa là infallible.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supposition', 'en-c1-27', 'supposition', '/ˌsʌpəˈzɪʃən/', 'C1', 'sự giả định; sự phỏng đoán; điều giả định', 'n.', 'suppose (v.), supposed (adj.), supposedly (adv.)', 'Đồng nghĩa: assumption, conjecture · Trái nghĩa: fact', 'Có thể chỉ một giả thiết, hoặc mang nghĩa chung là sự phỏng đoán; không đồng nghĩa với thực tế đã được chứng minh.', 'Your supposition about the missing keys turned out wrong.', NULL, 'Phỏng đoán của bạn về chùm chìa khóa bị mất hóa ra lại sai.', '{"wordId":"supposition","ukIpa":"/ˌsʌpəˈzɪʃən/","usIpa":"/ˌsʌpəˈzɪʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"an idea accepted as true without enough evidence","vi":"sự giả định; sự phỏng đoán; điều giả định"}],"examples":[{"en":"Your supposition about the missing keys turned out wrong.","vi":"Phỏng đoán của bạn về chùm chìa khóa bị mất hóa ra lại sai.","audioKind":"ex"},{"en":"Education policies should be based on reliable evidence rather than supposition about how children learn.","vi":"Các chính sách giáo dục nên dựa trên bằng chứng đáng tin cậy thay vì những phỏng đoán về cách trẻ em học tập.","audioKind":"ex2"}],"collocations":[{"en":"on the supposition that","vi":"với giả định rằng"},{"en":"mere supposition","vi":"thuần túy là phỏng đoán"},{"en":"based on supposition","vi":"dựa trên sự phỏng đoán"}],"wordFamily":["suppose (v.)","supposed (adj.)","supposedly (adv.)"],"synonyms":["assumption","conjecture"],"antonyms":["fact"],"tipVi":"Có thể chỉ một giả thiết, hoặc mang nghĩa chung là sự phỏng đoán; không đồng nghĩa với thực tế đã được chứng minh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_27_1', 'en-c1-27', 'Cách dùng “analytic” (adj.) — mang tính phân tích; có tư duy phân tích', 'analytic approach  ·  analytic skills  ·  analytic framework', 'Có nghĩa gần giống với analytical; tuy nhiên trong giao tiếp hàng ngày khi mô tả năng lực phân tích thì từ analytical được dùng phổ biến hơn.', 'Họ từ (Word Family): analyse (v.), analysis (n.), analytical (adj.), analytically (adv.) | Đồng nghĩa: analytical', '[{"hanzi":"Her analytic approach helped us understand our monthly spending.","pinyin":"","meaning":"Phương pháp phân tích của cô ấy đã giúp chúng tôi hiểu rõ các khoản chi tiêu hàng tháng của mình."},{"hanzi":"Schools should develop students'' analytic skills so they can evaluate evidence and recognise weaknesses in public arguments.","pinyin":"","meaning":"Các trường học nên phát triển các kỹ năng phân tích của học sinh để các em có thể đánh giá bằng chứng và nhận ra những điểm yếu trong các tranh luận công khai."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_27_2', 'en-c1-27', 'Cách dùng “notwithstanding” (prep.) — mặc dù; dẫu cho', 'notwithstanding the fact that  ·  notwithstanding these difficulties  ·  these concerns notwithstanding', 'Là từ mang phong cách trang trọng; khi đóng vai trò giới thiệu có thể đặt trước hoặc sau danh từ, ví dụ như the rain notwithstanding.', 'Đồng nghĩa: despite, nevertheless', '[{"hanzi":"Notwithstanding the rain, we enjoyed our walk by the river.","pinyin":"","meaning":"Mặc dù trời mưa, chúng tôi vẫn tận hưởng buổi đi dạo bên bờ sông."},{"hanzi":"Notwithstanding its initial costs, investment in renewable energy can provide substantial economic and environmental benefits over time.","pinyin":"","meaning":"Mặc dù chi phí ban đầu cao, việc đầu tư vào năng lượng tái tạo có thể mang lại lợi ích kinh tế và môi trường đáng kể về lâu dài."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_27_3', 'en-c1-27', 'Cách dùng “lofty” (adj.) — cao cả; đầy hoài bão lớn lao', 'lofty ideals  ·  lofty ambitions  ·  lofty goals', 'Khi bổ nghĩa cho lý tưởng, từ này có thể mang ý nghĩa ngợi khen, nhưng đôi khi cũng ngầm chỉ mục tiêu quá cao, thiếu thực tế.', 'Họ từ (Word Family): loftiness (n.), loftily (adv.) | Đồng nghĩa: elevated, noble, towering · Trái nghĩa: lowly', '[{"hanzi":"She has lofty ambitions but works hard every day.","pinyin":"","meaning":"Cô ấy có những hoài bão lớn lao nhưng vẫn làm việc chăm chỉ mỗi ngày."},{"hanzi":"Governments often announce lofty goals for reducing inequality, but meaningful progress requires sustained investment and practical policies.","pinyin":"","meaning":"Các chính phủ thường công bố những mục tiêu cao cả nhằm giảm bạo lực bất bình đẳng, nhưng tiến bộ thực chất đòi hỏi sự đầu tư bền vững và các chính sách thiết thực."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_27_4', 'en-c1-27', 'Cách dùng “supposition” (n.) — sự giả định; sự phỏng đoán; điều giả định', 'on the supposition that  ·  mere supposition  ·  based on supposition', 'Có thể chỉ một giả thiết, hoặc mang nghĩa chung là sự phỏng đoán; không đồng nghĩa với thực tế đã được chứng minh.', 'Họ từ (Word Family): suppose (v.), supposed (adj.), supposedly (adv.) | Đồng nghĩa: assumption, conjecture · Trái nghĩa: fact', '[{"hanzi":"Your supposition about the missing keys turned out wrong.","pinyin":"","meaning":"Phỏng đoán của bạn về chùm chìa khóa bị mất hóa ra lại sai."},{"hanzi":"Education policies should be based on reliable evidence rather than supposition about how children learn.","pinyin":"","meaning":"Các chính sách giáo dục nên dựa trên bằng chứng đáng tin cậy thay vì những phỏng đoán về cách trẻ em học tập."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_27_1', 'en-c1-27', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_1_1', 'ten_c1_27_1', 'disentangle', 'I carefully disentangled the necklace from my headphones.', 'I carefully disentangled the necklace from my headphones.', '/ˌdɪsɪnˈtæŋɡəl/', 'Tôi cẩn thận gỡ sợi dây chuyền ra khỏi dây tai nghe của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_1_2', 'ten_c1_27_1', 'deduction', 'Her deduction was simple: muddy shoes meant someone had visited.', 'Her deduction was simple: muddy shoes meant someone had visited.', '/dɪˈdʌkʃən/', 'Kết luận suy luận của cô ấy rất đơn giản: giày dính bùn có nghĩa là có ai đó đã ghé qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_1_3', 'ten_c1_27_1', 'integral', 'Music is an integral part of our family celebrations.', 'Music is an integral part of our family celebrations.', '/ˈɪntɪɡrəl/', 'Âm nhạc là một phần không thể thiếu trong các buổi lễ kỷ niệm của gia đình chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_1_4', 'ten_c1_27_1', 'contemplate', 'She sat beside the lake, contemplating her next move.', 'She sat beside the lake, contemplating her next move.', '/ˈkɑːntəmpleɪt/', 'Cô ấy ngồi bên bờ hồ, trầm ngâm suy nghĩ về bước đi tiếp theo của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_1_5', 'ten_c1_27_1', 'baffle', 'This puzzle baffled me, so I asked for help.', 'This puzzle baffled me, so I asked for help.', '/ˈbæfəl/', 'Câu đố này làm tôi thấy khó hiểu quá, nên tôi đã phải nhờ giúp đỡ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_1_6', 'ten_c1_27_1', 'envision', 'I envision a small garden behind our new house.', 'I envision a small garden behind our new house.', '/ɪnˈvɪʒən/', 'Tôi hình dung có một khu vườn nhỏ phía sau ngôi nhà mới của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_1_7', 'ten_c1_27_1', 'foretell', 'Nobody could foretell how quickly the village would change.', 'Nobody could foretell how quickly the village would change.', '/fɔːrˈtel/', 'Không ai có thể tiên đoán được ngôi làng sẽ thay đổi nhanh chóng đến nhường nào.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_1_8', 'ten_c1_27_1', 'notwithstanding', 'Notwithstanding the rain, we enjoyed our walk by the river.', 'Notwithstanding the rain, we enjoyed our walk by the river.', '/ˌnɑːtwɪðˈstændɪŋ/', 'Mặc dù trời mưa, chúng tôi vẫn tận hưởng buổi đi dạo bên bờ sông.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_27_1_1', 'en-c1-27', 'ten_c1_27_1', 'listening', 'listening', 'I carefully disentangled the necklace from my headphones.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những bức ảnh này bác bỏ tuyên bố cho rằng cổng của chúng tôi đã bị hỏng.","Âm nhạc là một phần không thể thiếu trong các buổi lễ kỷ niệm của gia đình chúng tôi.","Chẳng có lý do gì để bỏ lại bãi chiến tàn này mà không dọn dẹp cả.","Tôi cẩn thận gỡ sợi dây chuyền ra khỏi dây tai nghe của mình."]'::jsonb, 3, 'I carefully disentangled the necklace from my headphones. → Tôi cẩn thận gỡ sợi dây chuyền ra khỏi dây tai nghe của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_27_1_2', 'en-c1-27', 'ten_c1_27_1', 'listening', 'listening', 'Her deduction was simple: muddy shoes meant someone had visited.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chẳng có lý do gì để bỏ lại bãi chiến tàn này mà không dọn dẹp cả.","Những bức ảnh này bác bỏ tuyên bố cho rằng cổng của chúng tôi đã bị hỏng.","Kế hoạch của bạn dựa trên tiền đề rằng mọi người đều đồng ý.","Kết luận suy luận của cô ấy rất đơn giản: giày dính bùn có nghĩa là có ai đó đã ghé qua."]'::jsonb, 3, 'Her deduction was simple: muddy shoes meant someone had visited. → Kết luận suy luận của cô ấy rất đơn giản: giày dính bùn có nghĩa là có ai đó đã ghé qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_27_1_3', 'en-c1-27', 'ten_c1_27_1', 'listening', 'listening', 'Music is an integral part of our family celebrations.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mặc dù trời mưa, chúng tôi vẫn tận hưởng buổi đi dạo bên bờ sông.","Tôi đồng ý với đề xuất của bạn về việc xuất phát trước bữa trưa.","Phỏng đoán của bạn về chùm chìa khóa bị mất hóa ra lại sai.","Âm nhạc là một phần không thể thiếu trong các buổi lễ kỷ niệm của gia đình chúng tôi."]'::jsonb, 3, 'Music is an integral part of our family celebrations. → Âm nhạc là một phần không thể thiếu trong các buổi lễ kỷ niệm của gia đình chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_27_2', 'en-c1-27', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_2_1', 'ten_c1_27_2', 'disentangle', 'Researchers must disentangle the effects of income and education when examining differences in public health.', 'Researchers must disentangle the effects of income and education when examining differences in public health.', '/ˌdɪsɪnˈtæŋɡəl/', 'Các nhà nghiên cứu phải tách bạch các tác động của thu nhập và giáo dục khi xem xét sự khác biệt về sức khỏe cộng đồng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_2_2', 'ten_c1_27_2', 'deduction', 'Employees should check each deduction from their salary to ensure that their final payment is accurate.', 'Employees should check each deduction from their salary to ensure that their final payment is accurate.', '/dɪˈdʌkʃən/', 'Nhân viên nên kiểm tra từng khoản khấu trừ trong tiền lương để đảm bảo rằng số tiền thực nhận cuối cùng là chính xác.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_2_3', 'ten_c1_27_2', 'integral', 'Reliable public transport is integral to sustainable urban development because it reduces dependence on private cars.', 'Reliable public transport is integral to sustainable urban development because it reduces dependence on private cars.', '/ˈɪntɪɡrəl/', 'Hệ thống giao thông công cộng đáng tin cậy là yếu tố cốt lõi đối với sự phát triển đô thị bền vững vì nó làm giảm sự phụ thuộc vào xe cá nhân.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_2_4', 'ten_c1_27_2', 'contemplate', 'Before expanding public transport, planners should contemplate how proposed routes will affect existing communities.', 'Before expanding public transport, planners should contemplate how proposed routes will affect existing communities.', '/ˈkɑːntəmpleɪt/', 'Trước khi mở rộng hệ thống giao thông công cộng, các nhà quy hoạch nên cân nhắc kỹ lưỡng cách mà các tuyến đường được đề xuất sẽ ảnh hưởng đến các cộng đồng hiện hữu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_2_5', 'ten_c1_27_2', 'baffle', 'Unexpected changes in animal migration continue to baffle scientists despite improvements in tracking technology and data collection.', 'Unexpected changes in animal migration continue to baffle scientists despite improvements in tracking technology and data collection.', '/ˈbæfəl/', 'Những thay đổi bất ngờ trong tập tính di cư của động vật vẫn khiến các nhà khoa học đau đầu bất chấp những tiến bộ trong công nghệ theo dõi và thu thập dữ liệu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_27_2_6', 'ten_c1_27_2', 'envision', 'Urban planners envision a future in which most residents can reach essential services on foot.', 'Urban planners envision a future in which most residents can reach essential services on foot.', '/ɪnˈvɪʒən/', 'Các nhà quy hoạch đô thị đang mường tượng về một tương lai nơi phần lớn cư dân có thể tiếp cận các dịch vụ thiết yếu bằng cách đi bộ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_27_2_1', 'en-c1-27', 'ten_c1_27_2', 'listening', 'listening', 'Researchers must disentangle the effects of income and education when examining differences in public health.', NULL, 'Trong câu vừa nghe, từ “disentangle” mang nghĩa nào sau đây?', '["hệ thống thuế; việc thu thuế; thuế khóa","tạm thời; lâm thời","gỡ rối; tháo gỡ","chủ quyền; quyền lực tối cao"]'::jsonb, 2, '“disentangle” (/ˌdɪsɪnˈtæŋɡəl/): gỡ rối; tháo gỡ. Câu đầy đủ: Researchers must disentangle the effects of income and education when examining differences in public health.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_27_2_2', 'en-c1-27', 'ten_c1_27_2', 'listening', 'listening', 'Employees should check each deduction from their salary to ensure that their final payment is accurate.', NULL, 'Trong câu vừa nghe, từ “deduction” mang nghĩa nào sau đây?', '["vật tương tự; vật đối ứng","mang tính chiến lược (liên quan đến các kế hoạch nhằm đạt được mục tiêu dài hạn quan trọng)","hào hứng; sôi nổi; kích thích","sự suy luận; kết luận suy ra"]'::jsonb, 3, '“deduction” (/dɪˈdʌkʃən/): sự suy luận; kết luận suy ra. Câu đầy đủ: Employees should check each deduction from their salary to ensure that their final payment is accurate.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
