INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_27_5', 'en-c1-27', 'This puzzle baffled me, so I asked for help', 'Câu đố này làm tôi thấy khó hiểu quá, nên tôi đã phải nhờ giúp đỡ.', 'baffle /ˈbæfəl/', '["This","help","so","for","I","asked","puzzle","baffled","me"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
