INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_27_7', 'en-c1-27', 'Nobody could foretell how quickly the village would change', 'Không ai có thể tiên đoán được ngôi làng sẽ thay đổi nhanh chóng đến nhường nào.', 'foretell /fɔːrˈtel/', '["Nobody","how","change","the","quickly","village","foretell","could","would"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_27_8', 'en-c1-27', 'Notwithstanding the rain, we enjoyed our walk by the river', 'Mặc dù trời mưa, chúng tôi vẫn tận hưởng buổi đi dạo bên bờ sông.', 'notwithstanding /ˌnɑːtwɪðˈstændɪŋ/', '["the","we","Notwithstanding","enjoyed","river","rain","walk","the","our","by"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
