INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_27_10', 'en-c1-27', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “cardinal” (/ˈkɑːrdɪnəl/) có nghĩa là gì?', '["có thể sai lầm; dễ mắc lỗi","có xu hướng; có ý muốn; nghiêng về","sự rõ ràng; dễ hiểu","chủ yếu; cốt lõi; quan trọng nhất"]'::jsonb, 3, '“cardinal” (adj.): chủ yếu; cốt lõi; quan trọng nhất; hồng y giáo chủ; chim hồng tước Bắc Mỹ.', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_27_11', 'en-c1-27', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “A belief that is commonly accepted but actually false.”', '["premise","perpetual","fallacy","lofty"]'::jsonb, 2, '“fallacy” (/ˈfæləsi/) nghĩa là: ngụy biện; quan niệm sai lầm.', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_27_12', 'en-c1-27', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “conceive” (/kənˈsiːv/) có nghĩa là gì?', '["có xu hướng; có ý muốn; nghiêng về","chiếm lĩnh tâm trí; làm bận tâm; chi phối suy nghĩ","hình thành ý tưởng; tưởng tượng","làm cho ai đó không thể hiểu hoặc giải thích được điều gì; gây bối rối, làm khó"]'::jsonb, 2, '“conceive” (v.): hình thành ý tưởng; tưởng tượng; thụ thai; mang thai.', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_27_13', 'en-c1-27', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “clarity” (/ˈklærəti/) có nghĩa là gì?', '["sự rõ ràng; dễ hiểu","ý kiến đề xuất; ý kiến bàn","làm cho ai đó không thể hiểu hoặc giải thích được điều gì; gây bối rối, làm khó","cần thiết để một sự việc được hoàn chỉnh hoặc hoạt động trơn tru; không thể thiếu"]'::jsonb, 0, '“clarity” (n.): sự rõ ràng; dễ hiểu; sự trong trẻo; độ rõ nét.', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_27_14', 'en-c1-27', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “The process of developing a plan, policy, or theory.”', '["notwithstanding","formulation","baffle","supposition"]'::jsonb, 1, '“formulation” (/ˌfɔːrmjəˈleɪʃən/) nghĩa là: sự xây dựng; quá trình hoạch định.', 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
