INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_1', 'en-c1-27', NULL, 'comprehensive_test', 'listening', 'disentangle', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lời khẩn cầu; lời thỉnh cầu thiết tha","đau buồn; thương tiếc; chịu tang","gỡ rối; tháo gỡ","con ngêu; con sò; con trai"]'::jsonb, 2, 'disentangle (/ˌdɪsɪnˈtæŋɡəl/) → gỡ rối; tháo gỡ; làm sáng tỏ; tách bạch', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_2', 'en-c1-27', NULL, 'comprehensive_test', 'listening', 'Her deduction was simple: muddy shoes meant someone had visited.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Kế hoạch của bạn dựa trên tiền đề rằng mọi người đều đồng ý.","Chúng tôi nhận thấy có sự khác biệt giữa hai hóa đơn mua sắm.","Cô ấy nảy ra ý tưởng đó trong lúc đi dạo qua công viên.","Kết luận suy luận của cô ấy rất đơn giản: giày dính bùn có nghĩa là có ai đó đã ghé qua."]'::jsonb, 3, 'Her deduction was simple: muddy shoes meant someone had visited. → Kết luận suy luận của cô ấy rất đơn giản: giày dính bùn có nghĩa là có ai đó đã ghé qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_3', 'en-c1-27', NULL, 'comprehensive_test', 'listening', 'integral', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cần thiết để một sự việc được hoàn chỉnh hoặc hoạt động trơn tru; không thể thiếu","phòng y tế hoặc bệnh xá cung cấp dịch vụ chăm sóc y tế trong một cơ quan, trường học","vòng chí tuyến","khoan dung; nhân nhượng; không quá nghiêm khắc"]'::jsonb, 0, 'integral (/ˈɪntɪɡrəl/) → cần thiết để một sự việc được hoàn chỉnh hoặc hoạt động trơn tru; không thể thiếu; được tích hợp sẵn vào một cấu trúc thay vì được thêm vào một cách riêng lẻ; đại lượng toán học được tính bằng phép tích phân', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_4', 'en-c1-27', NULL, 'comprehensive_test', 'listening', 'She sat beside the lake, contemplating her next move.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mặc dù trời mưa, chúng tôi vẫn tận hưởng buổi đi dạo bên bờ sông.","Cô ấy ngồi bên bờ hồ, trầm ngâm suy nghĩ về bước đi tiếp theo của mình.","Những suy nghĩ về buổi phỏng vấn ngày mai đã chiếm trọn tâm trí cô ấy suốt bữa tối.","Câu đố này làm tôi thấy khó hiểu quá, nên tôi đã phải nhờ giúp đỡ."]'::jsonb, 1, 'She sat beside the lake, contemplating her next move. → Cô ấy ngồi bên bờ hồ, trầm ngâm suy nghĩ về bước đi tiếp theo của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_5', 'en-c1-27', NULL, 'comprehensive_test', 'listening', 'baffle', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm cho ai đó không thể hiểu hoặc giải thích được điều gì; gây bối rối, làm khó","thuộc bậc đại học; thuộc giáo dục đại học","súng cầm tay; vũ khí hỏa khí","phòng trọ kiêm phòng ngủ và phòng khách"]'::jsonb, 0, 'baffle (/ˈbæfəl/) → làm cho ai đó không thể hiểu hoặc giải thích được điều gì; gây bối rối, làm khó; vật cản dùng để kiểm soát dòng chảy của âm thanh, ánh sáng hoặc chất lỏng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_6', 'en-c1-27', NULL, 'comprehensive_test', 'listening', 'I envision a small garden behind our new house.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy nảy ra ý tưởng đó trong lúc đi dạo qua công viên.","Vòi nước rò rỉ liên tục là nguyên nhân gây phiền toái mãi không dứt.","Tôi hình dung có một khu vườn nhỏ phía sau ngôi nhà mới của chúng tôi.","Tôi có ý định ở nhà tự nấu ăn tối nay."]'::jsonb, 2, 'I envision a small garden behind our new house. → Tôi hình dung có một khu vườn nhỏ phía sau ngôi nhà mới của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_7', 'en-c1-27', NULL, 'comprehensive_test', 'listening', 'foretell', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiên đoán; báo trước","siết chặt; mím chặt","nhiều sự kiện; đầy biến động; nhiều chuyện","nhân viên đăng ký; thư ký quản lý hồ sơ"]'::jsonb, 0, 'foretell (/fɔːrˈtel/) → tiên đoán; báo trước', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_8', 'en-c1-27', NULL, 'comprehensive_test', 'listening', 'Notwithstanding the rain, we enjoyed our walk by the river.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy ngồi bên bờ hồ, trầm ngâm suy nghĩ về bước đi tiếp theo của mình.","Câu đố này làm tôi thấy khó hiểu quá, nên tôi đã phải nhờ giúp đỡ.","Tôi cẩn thận gỡ sợi dây chuyền ra khỏi dây tai nghe của mình.","Mặc dù trời mưa, chúng tôi vẫn tận hưởng buổi đi dạo bên bờ sông."]'::jsonb, 3, 'Notwithstanding the rain, we enjoyed our walk by the river. → Mặc dù trời mưa, chúng tôi vẫn tận hưởng buổi đi dạo bên bờ sông.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_9', 'en-c1-27', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To make someone unable to understand or explain something”?', '["discrepancy","foretell","disentangle","baffle"]'::jsonb, 3, 'baffle (/ˈbæfəl/) → làm cho ai đó không thể hiểu hoặc giải thích được điều gì; gây bối rối, làm khó', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_10', 'en-c1-27', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to imagine a future situation or possibility”?', '["deduction","envision","disentangle","preoccupy"]'::jsonb, 1, 'envision (/ɪnˈvɪʒən/) → hình dung; tưởng tượng; mường tượng', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_11', 'en-c1-27', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to say or indicate what will happen in the future”?', '["baffle","clarity","premise","foretell"]'::jsonb, 3, 'foretell (/fɔːrˈtel/) → tiên đoán; báo trước', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_12', 'en-c1-27', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “despite something that might prevent or contradict something else”?', '["contemplate","notwithstanding","preoccupy","justification"]'::jsonb, 1, 'notwithstanding (/ˌnɑːtwɪðˈstændɪŋ/) → mặc dù; dẫu cho', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
