INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_17', 'en-c1-27', NULL, 'comprehensive_test', 'fill_blank', NULL, NULL, 'Điền từ thích hợp vào chỗ trống:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_18', 'en-c1-27', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers must disentangle the effects of income and education when examining differences in public health.', 'Dựa vào câu trên, từ “disentangle” có nghĩa phù hợp nhất là gì?', '["gỡ rối; tháo gỡ","ở phía sau; phần sau","không thể tưởng tượng nổi; không thể chấp nhận được","thợ chuyển nhà; công ty chuyển đồ"]'::jsonb, 0, 'disentangle: gỡ rối; tháo gỡ; làm sáng tỏ; tách bạch. Dịch cả câu: Các nhà nghiên cứu phải tách bạch các tác động của thu nhập và giáo dục khi xem xét sự khác biệt về sức khỏe cộng đồng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_19', 'en-c1-27', NULL, 'comprehensive_test', 'reading', NULL, 'Employees should check each deduction from their salary to ensure that their final payment is accurate.', 'Dựa vào câu trên, từ “deduction” có nghĩa phù hợp nhất là gì?', '["lên án; chỉ trích mạnh mẽ ai đó hoặc cái gì","có tính thách thức; công khai chống đối; không tuân lệnh","sự suy luận; kết luận suy ra","có khả năng xảy ra, dễ bị (đặc biệt là điều bất lợi)"]'::jsonb, 2, 'deduction: sự suy luận; kết luận suy ra; khoản khấu trừ; sự khấu trừ. Dịch cả câu: Nhân viên nên kiểm tra từng khoản khấu trừ trong tiền lương để đảm bảo rằng số tiền thực nhận cuối cùng là chính xác.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_20', 'en-c1-27', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable public transport is integral to sustainable urban development because it reduces dependence on private cars.', 'Dựa vào câu trên, từ “integral” có nghĩa phù hợp nhất là gì?', '["tính đều đặn; tính quy luật; sự định kỳ","sự kính trọng; lòng ngưỡng mộ","cần thiết để một sự việc được hoàn chỉnh hoặc hoạt động trơn tru; không thể thiếu","suy ra; luận ra"]'::jsonb, 2, 'integral: cần thiết để một sự việc được hoàn chỉnh hoặc hoạt động trơn tru; không thể thiếu; được tích hợp sẵn vào một cấu trúc thay vì được thêm vào một cách riêng lẻ; đại lượng toán học được tính bằng phép tích phân. Dịch cả câu: Hệ thống giao thông công cộng đáng tin cậy là yếu tố cốt lõi đối với sự phát triển đô thị bền vững vì nó làm giảm sự phụ thuộc vào xe cá nhân.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_21', 'en-c1-27', NULL, 'comprehensive_test', 'reading', NULL, 'Before expanding public transport, planners should contemplate how proposed routes will affect existing communities.', 'Dựa vào câu trên, từ “contemplate” có nghĩa phù hợp nhất là gì?', '["nhà viết tiểu sử","suy ngẫm kỹ lưỡng về điều gì đó trong một khoảng thời gian dài","đầy thù hận; ác ý","có hạn; có giới hạn"]'::jsonb, 1, 'contemplate: suy ngẫm kỹ lưỡng về điều gì đó trong một khoảng thời gian dài; cân nhắc việc làm gì đó trong tương lai; nhìn cái gì đó một cách lặng lẽ và trầm ngâm. Dịch cả câu: Trước khi mở rộng hệ thống giao thông công cộng, các nhà quy hoạch nên cân nhắc kỹ lưỡng cách mà các tuyến đường được đề xuất sẽ ảnh hưởng đến các cộng đồng hiện hữu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_22', 'en-c1-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiền đề; giả định”', '["stipulate","painstaking","cavern","premise"]'::jsonb, 3, 'tiền đề; giả định → premise (/ˈpremɪs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_23', 'en-c1-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có thể sai lầm; dễ mắc lỗi”', '["fallible","console","aspire","blaze"]'::jsonb, 0, 'có thể sai lầm; dễ mắc lỗi → fallible (/ˈfæləbəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_27_24', 'en-c1-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự giả định; sự phỏng đoán; điều giả định”', '["holding","whitewash","supposition","intimidate"]'::jsonb, 2, 'sự giả định; sự phỏng đoán; điều giả định → supposition (/ˌsʌpəˈzɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-28', 'en', 'Bài 28: Tư duy & Nhận thức (3) - CEFR C1', 'CEFR C1', 'C1 · Tư duy', '26 từ vựng Tiếng Anh CEFR C1 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5028, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_differentiate', 'en-c1-28', 'differentiate', '/ˌdɪfəˈrenʃieɪt/', 'C1', 'phân biệt; nhận biết sự khác nhau; làm cho khác biệt; tạo sự khác biệt', 'v.', 'differentiation (n.), different (adj.), difference (n.), differ (v.)', 'Đồng nghĩa: distinguish', 'Thường dùng cấu trúc differentiate between A and B.', 'Can you differentiate these two birds by their songs?', NULL, 'Bạn có thể phân biệt hai loài chim này dựa trên tiếng hót của chúng không?', '{"wordId":"differentiate","ukIpa":"/ˌdɪfəˈrenʃieɪt/","usIpa":"/ˌdɪfəˈrenʃieɪt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To recognize or explain the differences between things","vi":"phân biệt; nhận biết sự khác nhau"},{"pos":"v.","en":"To make something different from other similar things","vi":"làm cho khác biệt; tạo sự khác biệt"}],"examples":[{"en":"Can you differentiate these two birds by their songs?","vi":"Bạn có thể phân biệt hai loài chim này dựa trên tiếng hót của chúng không?","audioKind":"ex"},{"en":"Schools should teach students to differentiate between reliable evidence and unsupported claims in online media.","vi":"Nhà trường nên dạy học sinh cách phân biệt giữa bằng chứng đáng tin cậy và những tuyên bố thiếu căn cứ trên truyền thông trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"differentiate between","vi":"phân biệt giữa"},{"en":"differentiate A from B","vi":"phân biệt A với B"},{"en":"differentiate products","vi":"tạo sự khác biệt cho sản phẩm"}],"wordFamily":["differentiation (n.)","different (adj.)","difference (n.)","differ (v.)"],"synonyms":["distinguish"],"antonyms":[],"tipVi":"Thường dùng cấu trúc differentiate between A and B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conception', 'en-c1-28', 'conception', '/kənˈsepʃən/', 'C1', 'khái niệm; quan niệm; sự hiểu biết; sự thụ thai; sự phác thảo; sự hình thành (ý tưởng, kế hoạch)', 'n.', 'conceive (v.), conceivable (adj.), inconceivable (adj.)', 'Đồng nghĩa: notion, idea', 'Cụm "conception of" chỉ sự nhận thức về sự vật; từ này cũng có thể chỉ quá trình thụ thai.', 'His conception of a perfect holiday involves no phones.', NULL, 'Trong quan niệm của anh ấy về một kỳ nghỉ hoàn hảo thì không có sự xuất hiện của điện thoại.', '{"wordId":"conception","ukIpa":"/kənˈsepʃən/","usIpa":"/kənˈsepʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"an idea or understanding of what something is like","vi":"khái niệm; quan niệm; sự hiểu biết"},{"pos":"n.","en":"the process in which an egg is fertilised, beginning pregnancy","vi":"sự thụ thai"},{"pos":"n.","en":"the formation of a plan or idea","vi":"sự phác thảo; sự hình thành (ý tưởng, kế hoạch)"}],"examples":[{"en":"His conception of a perfect holiday involves no phones.","vi":"Trong quan niệm của anh ấy về một kỳ nghỉ hoàn hảo thì không có sự xuất hiện của điện thoại.","audioKind":"ex"},{"en":"Access to green spaces can broaden children''s conception of nature beyond what they learn in classrooms.","vi":"Việc tiếp cận không gian xanh có thể mở rộng nhận thức của trẻ em về tự nhiên vượt ra ngoài những gì chúng học được trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"conception of","vi":"quan niệm về"},{"en":"from conception to completion","vi":"từ lúc lên ý tưởng đến khi hoàn thành"},{"en":"a broad conception","vi":"một quan niệm rộng rãi"},{"en":"the moment of conception","vi":"thời điểm thụ thai"}],"wordFamily":["conceive (v.)","conceivable (adj.)","inconceivable (adj.)"],"synonyms":["notion","idea"],"antonyms":[],"tipVi":"Cụm \"conception of\" chỉ sự nhận thức về sự vật; từ này cũng có thể chỉ quá trình thụ thai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_generalization', 'en-c1-28', 'generalization', '/ˌdʒenrələˈzeɪʃən/', 'C1', 'sự khái quát; lời nhận định chung chung; quá trình quy nạp kết luận chung', 'n.', 'general (adj.), generalize (v.), generally (adv.)', NULL, 'Lối viết Anh-Anh cũng có thể là generalisation; các kết luận khái quát không phải lúc nào cũng đáng tin cậy.', 'Calling all teenagers lazy is an unfair generalization.', NULL, 'Gắn mác tất cả thanh thiếu niên là lười biếng là một lời nhận định chung chung không công bằng.', '{"wordId":"generalization","ukIpa":"/ˌdʒenrəlaɪˈzeɪʃən/","usIpa":"/ˌdʒenrələˈzeɪʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A broad statement based on particular cases, sometimes without enough evidence.","vi":"sự khái quát; lời nhận định chung chung"},{"pos":"n.","en":"The process of forming general conclusions from particular examples.","vi":"quá trình quy nạp kết luận chung"}],"examples":[{"en":"Calling all teenagers lazy is an unfair generalization.","vi":"Gắn mác tất cả thanh thiếu niên là lười biếng là một lời nhận định chung chung không công bằng.","audioKind":"ex"},{"en":"Researchers should avoid making a generalization about an entire population from a small, unrepresentative sample.","vi":"Các nhà nghiên cứu nên tránh đưa ra những kết luận khái quát về toàn bộ dân số chỉ từ một mẫu nhỏ và thiếu tính đại diện.","audioKind":"ex2"}],"collocations":[{"en":"make a generalization","vi":"đưa ra sự khái quát"},{"en":"sweeping generalization","vi":"sự quy vơ đũa cả nắm"},{"en":"broad generalization","vi":"sự khái quát rộng"},{"en":"hasty generalization","vi":"sự khái quát vội vàng"}],"wordFamily":["general (adj.)","generalize (v.)","generally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Lối viết Anh-Anh cũng có thể là generalisation; các kết luận khái quát không phải lúc nào cũng đáng tin cậy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vainly', 'en-c1-28', 'vainly', '/ˈveɪnli/', 'C1', 'một cách vô ích; hoài công', 'adv.', 'vain (adj.), vanity (n.)', 'Đồng nghĩa: unsuccessfully, fruitlessly · Trái nghĩa: successfully', 'Vainly nhấn mạnh nỗ lực không đạt kết quả, thường có thể thay bằng in vain.', 'I searched vainly for my keys under the sofa.', NULL, 'Tôi lục tìm chìa khóa dưới ghế sofa nhưng công cốc.', '{"wordId":"vainly","ukIpa":"/ˈveɪnli/","usIpa":"/ˈveɪnli/","cefr":"C1","topic":"thinking","senses":[{"pos":"adv.","en":"Without achieving the desired result despite effort","vi":"một cách vô ích; hoài công"}],"examples":[{"en":"I searched vainly for my keys under the sofa.","vi":"Tôi lục tìm chìa khóa dưới ghế sofa nhưng công cốc.","audioKind":"ex"},{"en":"Residents have vainly requested better bus services for years, leaving many dependent on private cars.","vi":"Nhiều năm qua, cư dân đã yêu cầu cải thiện dịch vụ xe buýt nhưng không có kết quả, khiến nhiều người vẫn phải phụ thuộc vào xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"try vainly to do something","vi":"cố gắng làm gì đó trong vô vọng"},{"en":"search vainly for","vi":"tìm kiếm trong vô vọng"},{"en":"struggle vainly","vi":"vùng vẫy trong vô vọng"}],"wordFamily":["vain (adj.)","vanity (n.)"],"synonyms":["unsuccessfully","fruitlessly"],"antonyms":["successfully"],"tipVi":"Vainly nhấn mạnh nỗ lực không đạt kết quả, thường có thể thay bằng in vain.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feasible', 'en-c1-28', 'feasible', '/ˈfiːzəbəl/', 'C1', 'khả thi; có thể thực hiện được', 'adj.', 'feasibility (n.), infeasible (adj.)', 'Đồng nghĩa: practical, viable · Trái nghĩa: infeasible, impractical', 'Chỉ điều kiện cho phép, thực tế thực hiện được, không đồng nghĩa với "có thể tin được".', 'Cycling to work is feasible now that I live nearby.', NULL, 'Đạp xe đi làm giờ đã khả thi vì tôi sống gần đây.', '{"wordId":"feasible","ukIpa":"/ˈfiːzəbəl/","usIpa":"/ˈfiːzəbəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"possible and practical to achieve with available resources","vi":"khả thi; có thể thực hiện được"}],"examples":[{"en":"Cycling to work is feasible now that I live nearby.","vi":"Đạp xe đi làm giờ đã khả thi vì tôi sống gần đây.","audioKind":"ex"},{"en":"Solar power becomes more economically feasible when installation costs fall and reliable energy storage is available.","vi":"Năng lượng mặt trời trở nên khả thi hơn về mặt kinh tế khi chi phí lắp đặt giảm và có sẵn hệ thống lưu trữ năng lượng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"a feasible solution","vi":"một giải pháp khả thi"},{"en":"economically feasible","vi":"khả thi về mặt kinh tế"},{"en":"technically feasible","vi":"khả thi về mặt kỹ thuật"},{"en":"a feasible alternative","vi":"một phương án thay thế khả thi"}],"wordFamily":["feasibility (n.)","infeasible (adj.)"],"synonyms":["practical","viable"],"antonyms":["infeasible","impractical"],"tipVi":"Chỉ điều kiện cho phép, thực tế thực hiện được, không đồng nghĩa với \"có thể tin được\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pertain', 'en-c1-28', 'pertain', '/pərˈteɪn/', 'C1', 'liên quan đến; gắn liền với; áp dụng cho', 'v.', NULL, 'Đồng nghĩa: relate, concern', 'Là từ trang trọng, thường đi với to; cấu trúc phổ biến là pertaining to.', 'These rules pertain to everyone who uses the kitchen.', NULL, 'Những quy định này áp dụng cho bất kỳ ai sử dụng nhà bếp.', '{"wordId":"pertain","ukIpa":"/pəˈteɪn/","usIpa":"/pərˈteɪn/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To relate to or apply to a particular subject.","vi":"liên quan đến; gắn liền với; áp dụng cho"}],"examples":[{"en":"These rules pertain to everyone who uses the kitchen.","vi":"Những quy định này áp dụng cho bất kỳ ai sử dụng nhà bếp.","audioKind":"ex"},{"en":"The committee reviewed documents pertaining to water quality before recommending stricter controls on industrial waste.","vi":"Ủy ban đã xem xét các tài liệu liên quan đến chất lượng nước trước khi kiến nghị siết chặt việc kiểm soát chất thải công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"pertain to","vi":"liên quan đến; áp dụng cho"},{"en":"matters pertaining to","vi":"các vấn đề liên quan đến"}],"wordFamily":[],"synonyms":["relate","concern"],"antonyms":[],"tipVi":"Là từ trang trọng, thường đi với to; cấu trúc phổ biến là pertaining to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_realm', 'en-c1-28', 'realm', '/relm/', 'C1', 'lĩnh vực; phạm vi; vương quốc', 'n.', NULL, 'Đồng nghĩa: domain, sphere', 'Thường dùng "the realm of"; khi chỉ lĩnh vực thì mang tính trang trọng hơn so với "area".', 'Robots have moved beyond the realm of science fiction.', NULL, 'Robot đã vượt ra khỏi lĩnh vực khoa học viễn tưởng.', '{"wordId":"realm","ukIpa":"/relm/","usIpa":"/relm/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"An area of knowledge, activity, or experience.","vi":"lĩnh vực; phạm vi"},{"pos":"n.","en":"A country ruled by a king or queen.","vi":"vương quốc"}],"examples":[{"en":"Robots have moved beyond the realm of science fiction.","vi":"Robot đã vượt ra khỏi lĩnh vực khoa học viễn tưởng.","audioKind":"ex"},{"en":"Advances in artificial intelligence are transforming the realm of education by enabling more personalised learning experiences.","vi":"Sự tiến bộ của trí tuệ nhân tạo đang làm thay đổi lĩnh vực giáo dục bằng cách tạo ra các trải nghiệm học tập mang tính cá nhân hóa cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"the realm of science","vi":"lĩnh vực khoa học"},{"en":"within the realm of possibility","vi":"trong khả năng có thể"},{"en":"beyond the realm of","vi":"vượt ra ngoài phạm vi của"}],"wordFamily":[],"synonyms":["domain","sphere"],"antonyms":[],"tipVi":"Thường dùng \"the realm of\"; khi chỉ lĩnh vực thì mang tính trang trọng hơn so với \"area\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conversely', 'en-c1-28', 'conversely', '/ˈkɑːnvɜːrsli/', 'C1', 'ngược lại; trái lại', 'adv.', 'converse (adj.)', 'Đồng nghĩa: in contrast', 'Dùng để nêu ra một tình huống trái ngược, không phải là phép bổ sung thông thường.', 'I love busy cities; conversely, my sister prefers quiet villages.', NULL, 'Tôi thích những thành phố nhộn nhịp; ngược lại, chị tôi lại thích những ngôi làng yên tĩnh.', '{"wordId":"conversely","ukIpa":"/ˈkɒnvɜːsli/","usIpa":"/ˈkɑːnvɜːrsli/","cefr":"C1","topic":"thinking","senses":[{"pos":"adv.","en":"used to introduce an opposite situation or relationship","vi":"ngược lại; trái lại"}],"examples":[{"en":"I love busy cities; conversely, my sister prefers quiet villages.","vi":"Tôi thích những thành phố nhộn nhịp; ngược lại, chị tôi lại thích những ngôi làng yên tĩnh.","audioKind":"ex"},{"en":"Reliable public transport can reduce car use; conversely, poor services may encourage greater dependence on private vehicles.","vi":"Hệ thống giao thông công cộng đáng tin cậy có thể làm giảm việc sử dụng ô tô cá nhân; ngược lại, chất lượng dịch vụ kém có thể khiến người dân phụ thuộc nhiều hơn vào phương tiện cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"and conversely","vi":"và ngược lại"},{"en":"conversely, however","vi":"tuy nhiên, ngược lại"}],"wordFamily":["converse (adj.)"],"synonyms":["in contrast"],"antonyms":[],"tipVi":"Dùng để nêu ra một tình huống trái ngược, không phải là phép bổ sung thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reappraisal', 'en-c1-28', 'reappraisal', '/ˌriːəˈpreɪzəl/', 'C1', 'sự đánh giá lại; sự xem xét lại', 'n.', 'reappraise (v.), appraise (v.), appraisal (n.)', 'Đồng nghĩa: reassessment, reevaluation', 'Thường dùng cấu trúc a reappraisal of, để chỉ việc đánh giá lại một vấn đề gì đó.', 'The unexpected repair bill prompted a reappraisal of our budget.', NULL, 'Hóa đơn sửa chữa bất ngờ đã thúc đẩy việc chúng tôi phải xem xét lại ngân sách.', '{"wordId":"reappraisal","ukIpa":"/ˌriːəˈpreɪzəl/","usIpa":"/ˌriːəˈpreɪzəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A fresh assessment of something, often leading to changed views.","vi":"sự đánh giá lại; sự xem xét lại"}],"examples":[{"en":"The unexpected repair bill prompted a reappraisal of our budget.","vi":"Hóa đơn sửa chữa bất ngờ đã thúc đẩy việc chúng tôi phải xem xét lại ngân sách.","audioKind":"ex"},{"en":"New evidence has led to a reappraisal of the environmental benefits associated with this farming method.","vi":"Những bằng chứng mới đã dẫn đến việc đánh giá lại các lợi ích môi trường gắn liền với phương pháp canh tác này.","audioKind":"ex2"}],"collocations":[{"en":"a thorough reappraisal","vi":"một cuộc đánh giá toàn diện"},{"en":"prompt a reappraisal","vi":"thúc đẩy việc đánh giá lại"},{"en":"a reappraisal of priorities","vi":"việc xem xét lại các ưu tiên"}],"wordFamily":["reappraise (v.)","appraise (v.)","appraisal (n.)"],"synonyms":["reassessment","reevaluation"],"antonyms":[],"tipVi":"Thường dùng cấu trúc a reappraisal of, để chỉ việc đánh giá lại một vấn đề gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incline', 'en-c1-28', 'incline', '/ɪnˈklaɪn/', 'C1', 'có khuynh hướng; thiên về; cúi xuống; làm nghiêng; độ dốc; dốc', 'v.', 'inclination (n.), inclined (adj.)', NULL, 'Động từ có trọng âm rơi vào âm tiết sau; danh từ phát âm là /ˈɪnklaɪn/.', 'I incline towards the cheaper option for our holiday.', NULL, 'Tôi nghiêng về phương án rẻ hơn cho kỳ nghỉ của chúng tôi.', '{"wordId":"incline","ukIpa":"/ɪnˈklaɪn/","usIpa":"/ɪnˈklaɪn/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To tend towards a particular opinion or course of action","vi":"có khuynh hướng; thiên về"},{"pos":"v.","en":"To lean or move something towards a sloping position","vi":"cúi xuống; làm nghiêng"},{"pos":"n.","en":"A surface that slopes upwards or downwards","vi":"độ dốc; dốc"}],"examples":[{"en":"I incline towards the cheaper option for our holiday.","vi":"Tôi nghiêng về phương án rẻ hơn cho kỳ nghỉ của chúng tôi.","audioKind":"ex"},{"en":"Rising housing costs may incline young adults to remain in their parents'' homes longer.","vi":"Chi phí nhà ở gia tăng có thể khiến những người trẻ tuổi có xu hướng ở lại nhà cha mẹ lâu hơn.","audioKind":"ex2"}],"collocations":[{"en":"incline towards a view","vi":"có xu hướng nghiêng về một quan điểm"},{"en":"be inclined to agree","vi":"có khuynh hướng đồng tình"},{"en":"a steep incline","vi":"một con dốc đứng"}],"wordFamily":["inclination (n.)","inclined (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ có trọng âm rơi vào âm tiết sau; danh từ phát âm là /ˈɪnklaɪn/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_analogous', 'en-c1-28', 'analogous', '/əˈnæləɡəs/', 'C1', 'tương tự; có thể so sánh được', 'adj.', 'analogy (n.), analogously (adv.)', 'Đồng nghĩa: comparable, similar · Trái nghĩa: dissimilar', 'Thường dùng be analogous to, nhấn mạnh sự tương đồng có thể đặt lên bàn cân so sánh.', 'Our shared kitchen is analogous to a busy workshop.', NULL, 'Căn bếp chung của chúng tôi giống như một xưởng làm việc bận rộn.', '{"wordId":"analogous","ukIpa":"/əˈnæləɡəs/","usIpa":"/əˈnæləɡəs/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Similar in a way that allows a useful comparison.","vi":"tương tự; có thể so sánh được"}],"examples":[{"en":"Our shared kitchen is analogous to a busy workshop.","vi":"Căn bếp chung của chúng tôi giống như một xưởng làm việc bận rộn.","audioKind":"ex"},{"en":"The role of public libraries is analogous to that of schools in supporting lifelong learning within communities.","vi":"Vai trò của các thư viện công cộng tương tự như vai trò của các trường học trong việc hỗ trợ học tập suốt đời trong cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"analogous to","vi":"tương tự với"},{"en":"an analogous situation","vi":"một tình huống tương tự"},{"en":"an analogous process","vi":"một quá trình tương tự"}],"wordFamily":["analogy (n.)","analogously (adv.)"],"synonyms":["comparable","similar"],"antonyms":["dissimilar"],"tipVi":"Thường dùng be analogous to, nhấn mạnh sự tương đồng có thể đặt lên bàn cân so sánh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assertion', 'en-c1-28', 'assertion', '/əˈsɝːʃən/', 'C1', 'sự khẳng định; lời quả quyết; nhận định chắc nịch; sự bảo vệ; sự khẳng định quyền lợi, quyền lực hoặc tính tự chủ', 'n.', 'assert (v.), assertive (adj.), assertively (adv.), assertiveness (n.)', 'Đồng nghĩa: claim, statement', 'Thường dùng cấu trúc the assertion that...; một lời khẳng định chưa chắc đã đi kèm sẵn bằng chứng xác thực.', 'Her assertion that the shop was closed proved wrong.', NULL, 'Lời quả quyết của cô ấy rằng cửa hàng đã đóng cửa hóa ra lại sai.', '{"wordId":"assertion","ukIpa":"/əˈsɜːʃən/","usIpa":"/əˈsɝːʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"a confident statement that something is true","vi":"sự khẳng định; lời quả quyết; nhận định chắc nịch"},{"pos":"n.","en":"the act of firmly expressing rights, authority, or independence","vi":"sự bảo vệ; sự khẳng định quyền lợi, quyền lực hoặc tính tự chủ"}],"examples":[{"en":"Her assertion that the shop was closed proved wrong.","vi":"Lời quả quyết của cô ấy rằng cửa hàng đã đóng cửa hóa ra lại sai.","audioKind":"ex"},{"en":"The assertion that economic growth always improves wellbeing requires careful examination of social and environmental evidence.","vi":"Nhận định cho rằng tăng trưởng kinh tế luôn cải thiện phúc lợi đòi hỏi phải xem xét kỹ lưỡng các bằng chứng về xã hội và môi trường.","audioKind":"ex2"}],"collocations":[{"en":"make an assertion","vi":"đưa ra khẳng định"},{"en":"unsupported assertion","vi":"khẳng định thiếu căn cứ"},{"en":"challenge an assertion","vi":"thách thức một nhận định"},{"en":"assertion of rights","vi":"sự bảo vệ quyền lợi"}],"wordFamily":["assert (v.)","assertive (adj.)","assertively (adv.)","assertiveness (n.)"],"synonyms":["claim","statement"],"antonyms":[],"tipVi":"Thường dùng cấu trúc the assertion that...; một lời khẳng định chưa chắc đã đi kèm sẵn bằng chứng xác thực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assert', 'en-c1-28', 'assert', '/əˈsɝːt/', 'C1', 'quả quyết, khẳng định, khẳng định chắc nịch rằng điều gì là đúng; khẳng định, xác nhận, bảo vệ một quyền lợi, quyền lực hoặc vị thế một cách kiên quyết', 'v.', 'assertion (n.), assertive (adj.), assertively (adv.), assertiveness (n.)', 'Đồng nghĩa: declare, maintain · Trái nghĩa: deny', 'Assert nhấn mạnh thái độ cương quyết khi bày tỏ quan điểm, không đồng nghĩa với việc đã đưa ra bằng chứng xác thực.', 'He asserted that he had already paid for lunch.', NULL, 'Anh ấy khẳng định rằng mình đã trả tiền bữa trưa rồi.', '{"wordId":"assert","ukIpa":"/əˈsɜːt/","usIpa":"/əˈsɝːt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To state firmly that something is true.","vi":"quả quyết, khẳng định, khẳng định chắc nịch rằng điều gì là đúng"},{"pos":"v.","en":"To firmly exercise or defend a right, power, or position.","vi":"khẳng định, xác nhận, bảo vệ một quyền lợi, quyền lực hoặc vị thế một cách kiên quyết"}],"examples":[{"en":"He asserted that he had already paid for lunch.","vi":"Anh ấy khẳng định rằng mình đã trả tiền bữa trưa rồi.","audioKind":"ex"},{"en":"Some educators assert that regular feedback improves student motivation more effectively than frequent formal examinations.","vi":"Một số nhà giáo dục khẳng định rằng phản hồi thường xuyên giúp nâng cao động lực học tập của học sinh hiệu quả hơn là các bài kiểm tra chính thức diễn ra thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"assert that","vi":"khẳng định rằng"},{"en":"assert your rights","vi":"bảo vệ quyền lợi của bạn"},{"en":"assert authority","vi":"thể hiện uy quyền"},{"en":"assert yourself","vi":"khẳng định bản thân"}],"wordFamily":["assertion (n.)","assertive (adj.)","assertively (adv.)","assertiveness (n.)"],"synonyms":["declare","maintain"],"antonyms":["deny"],"tipVi":"Assert nhấn mạnh thái độ cương quyết khi bày tỏ quan điểm, không đồng nghĩa với việc đã đưa ra bằng chứng xác thực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sceptical', 'en-c1-28', 'sceptical', '/ˈskeptɪkəl/', 'C1', 'hoài nghi; không dễ tin', 'adj.', 'sceptic (n.), scepticism (n.), sceptically (adv.)', 'Đồng nghĩa: doubtful, unconvinced · Trái nghĩa: convinced, credulous', 'Cách viết theo Anh-Anh là sceptical, trong khi tiếng Anh-Mỹ thường viết là skeptical.', 'I''m sceptical about this cream''s promise of instant results.', NULL, 'Tôi hoài nghi về lời hứa mang lại hiệu quả tức thì của loại kem này.', '{"wordId":"sceptical","ukIpa":"/ˈskeptɪkəl/","usIpa":"/ˈskeptɪkəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Doubtful that a claim or idea is true or useful.","vi":"hoài nghi; không dễ tin"}],"examples":[{"en":"I''m sceptical about this cream''s promise of instant results.","vi":"Tôi hoài nghi về lời hứa mang lại hiệu quả tức thì của loại kem này.","audioKind":"ex"},{"en":"Many consumers remain sceptical about environmental claims made by companies that provide little evidence of sustainable practices.","vi":"Nhiều người tiêu dùng vẫn hoài nghi về các tuyên bố bảo vệ môi trường từ những công ty hầu như không đưa ra bằng chứng nào về hoạt động phát triển bền vững.","audioKind":"ex2"}],"collocations":[{"en":"sceptical about","vi":"hoài nghi về"},{"en":"sceptical of claims","vi":"hoài nghi các tuyên bố"},{"en":"remain sceptical","vi":"vẫn hoài nghi"}],"wordFamily":["sceptic (n.)","scepticism (n.)","sceptically (adv.)"],"synonyms":["doubtful","unconvinced"],"antonyms":["convinced","credulous"],"tipVi":"Cách viết theo Anh-Anh là sceptical, trong khi tiếng Anh-Mỹ thường viết là skeptical.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_construe', 'en-c1-28', 'construe', '/kənˈstruː/', 'C1', 'hiểu; giải thích; suy diễn', 'v.', 'misconstrue (v.)', 'Đồng nghĩa: interpret, understand', 'Thường dùng cấu trúc construe A as B, mang nghĩa "hiểu A là B".', 'Please don''t construe my silence as a lack of interest.', NULL, 'Xin đừng hiểu sự im lặng của tôi là thiếu sự quan tâm.', '{"wordId":"construe","ukIpa":"/kənˈstruː/","usIpa":"/kənˈstruː/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To understand a statement or action in a particular way.","vi":"hiểu; giải thích; suy diễn"}],"examples":[{"en":"Please don''t construe my silence as a lack of interest.","vi":"Xin đừng hiểu sự im lặng của tôi là thiếu sự quan tâm.","audioKind":"ex"},{"en":"A failure to consult local residents may be construed as disregard for their concerns about urban development.","vi":"Việc không tham khảo ý kiến cư dân địa phương có thể bị xem là sự coi thường các mối quan tâm của họ về vấn đề phát triển đô thị.","audioKind":"ex2"}],"collocations":[{"en":"construe something as","vi":"hiểu cái gì như là"},{"en":"be construed as criticism","vi":"bị coi là lời chỉ trích"},{"en":"construe narrowly","vi":"giải thích theo nghĩa hẹp"}],"wordFamily":["misconstrue (v.)"],"synonyms":["interpret","understand"],"antonyms":[],"tipVi":"Thường dùng cấu trúc construe A as B, mang nghĩa \"hiểu A là B\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paramount', 'en-c1-28', 'paramount', '/ˈpærəmaʊnt/', 'C1', 'quan trọng hàng đầu; tối quan trọng; cao nhất', 'adj.', NULL, 'Đồng nghĩa: supreme, overriding', 'Thường xuất hiện trong các cấu trúc như be paramount hoặc of paramount importance.', 'Safety is paramount when we take children swimming.', NULL, 'Sự an toàn là điều quan trọng hàng đầu khi chúng tôi đưa trẻ em đi bơi.', '{"wordId":"paramount","ukIpa":"/ˈpærəmaʊnt/","usIpa":"/ˈpærəmaʊnt/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"more important than anything else","vi":"quan trọng hàng đầu; tối quan trọng; cao nhất"}],"examples":[{"en":"Safety is paramount when we take children swimming.","vi":"Sự an toàn là điều quan trọng hàng đầu khi chúng tôi đưa trẻ em đi bơi.","audioKind":"ex"},{"en":"Protecting patient privacy should be paramount when healthcare providers introduce digital systems for storing medical records.","vi":"Việc bảo vệ quyền riêng tư của bệnh nhân phải được đặt lên hàng đầu khi các cơ sở y tế áp dụng hệ thống kỹ thuật số để lưu trữ hồ sơ bệnh án.","audioKind":"ex2"}],"collocations":[{"en":"of paramount importance","vi":"có tầm quan trọng tối quan trọng"},{"en":"paramount concern","vi":"mối quan tâm hàng đầu"},{"en":"paramount consideration","vi":"yếu tố được ưu tiên hàng đầu"}],"wordFamily":[],"synonyms":["supreme","overriding"],"antonyms":[],"tipVi":"Thường xuất hiện trong các cấu trúc như be paramount hoặc of paramount importance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_permanence', 'en-c1-28', 'permanence', '/ˈpɝːmənəns/', 'C1', 'tính vĩnh cửu; tính lâu dài; sự ổn định lâu dài', 'n.', 'permanent (adj.), permanently (adv.), impermanence (n.)', 'Đồng nghĩa: lastingness · Trái nghĩa: impermanence', 'Đây là danh từ không đếm được; tính từ tương ứng của nó là permanent.', 'Planting a tree gave our new home a sense of permanence.', NULL, 'Việc trồng một cây xanh mang lại cho ngôi nhà mới của chúng tôi cảm giác gắn kết lâu dài.', '{"wordId":"permanence","ukIpa":"/ˈpɜːmənəns/","usIpa":"/ˈpɝːmənəns/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"the quality of lasting indefinitely without significant change","vi":"tính vĩnh cửu; tính lâu dài; sự ổn định lâu dài"}],"examples":[{"en":"Planting a tree gave our new home a sense of permanence.","vi":"Việc trồng một cây xanh mang lại cho ngôi nhà mới của chúng tôi cảm giác gắn kết lâu dài.","audioKind":"ex"},{"en":"The apparent permanence of digital records raises important questions about privacy and the right to be forgotten.","vi":"Tính vĩnh cửu rõ rệt của các dữ liệu số đang đặt ra những câu hỏi quan trọng về quyền riêng tư và quyền được lãng quên.","audioKind":"ex2"}],"collocations":[{"en":"a sense of permanence","vi":"cảm giác ổn định lâu dài"},{"en":"apparent permanence","vi":"tính vĩnh cửu mang tính bề ngoài"},{"en":"ensure permanence","vi":"đảm bảo sự lưu giữ lâu dài"}],"wordFamily":["permanent (adj.)","permanently (adv.)","impermanence (n.)"],"synonyms":["lastingness"],"antonyms":["impermanence"],"tipVi":"Đây là danh từ không đếm được; tính từ tương ứng của nó là permanent.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_practicable', 'en-c1-28', 'practicable', '/ˈpræktɪkəbl/', 'C1', 'khả thi; thực hiện được', 'adj.', 'practicability (n.), impracticable (adj.)', 'Đồng nghĩa: feasible, workable · Trái nghĩa: impracticable, unworkable', 'Practicable nhấn mạnh tính khả thi để thực hiện; practical còn có thể mang nghĩa là thực tế.', 'Taking the bus is practicable now the road has reopened.', NULL, 'Đi xe buýt bây giờ đã khả thi vì con đường đã mở cửa trở lại.', '{"wordId":"practicable","ukIpa":"/ˈpræktɪkəbl/","usIpa":"/ˈpræktɪkəbl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"able to be done successfully in the circumstances","vi":"khả thi; thực hiện được"}],"examples":[{"en":"Taking the bus is practicable now the road has reopened.","vi":"Đi xe buýt bây giờ đã khả thi vì con đường đã mở cửa trở lại.","audioKind":"ex"},{"en":"Local authorities must assess whether expanding public transport is financially practicable before approving new infrastructure projects.","vi":"Chính quyền địa phương phải đánh giá xem việc mở rộng giao thông công cộng có khả thi về mặt tài chính hay không trước khi phê duyệt các dự án cơ sở hạ tầng mới.","audioKind":"ex2"}],"collocations":[{"en":"practicable solution","vi":"giải pháp khả thi"},{"en":"reasonably practicable","vi":"khả thi một cách hợp lý"},{"en":"as soon as practicable","vi":"càng sớm càng tốt"}],"wordFamily":["practicability (n.)","impracticable (adj.)"],"synonyms":["feasible","workable"],"antonyms":["impracticable","unworkable"],"tipVi":"Practicable nhấn mạnh tính khả thi để thực hiện; practical còn có thể mang nghĩa là thực tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thereby', 'en-c1-28', 'thereby', '/ˌðerˈbaɪ/', 'C1', 'nhờ đó; vì thế; do đó', 'adv.', NULL, 'Đồng nghĩa: thus, consequently', 'Thường dùng cấu trúc dấu phẩy kết hợp thereby doing để diễn tả hệ quả của hành động vừa nêu.', 'She sealed the jar tightly, thereby keeping the biscuits fresh.', NULL, 'Cô ấy đậy kín hũ lọ, nhờ đó giữ cho bánh quy luôn giòn ngon.', '{"wordId":"thereby","ukIpa":"/ˌðeəˈbaɪ/","usIpa":"/ˌðerˈbaɪ/","cefr":"C1","topic":"thinking","senses":[{"pos":"adv.","en":"as a result of the action just mentioned","vi":"nhờ đó; vì thế; do đó"}],"examples":[{"en":"She sealed the jar tightly, thereby keeping the biscuits fresh.","vi":"Cô ấy đậy kín hũ lọ, nhờ đó giữ cho bánh quy luôn giòn ngon.","audioKind":"ex"},{"en":"Cities can expand public transport networks, thereby reducing traffic congestion and improving air quality for residents.","vi":"Các thành phố có thể mở rộng mạng lưới giao thông công cộng, nhờ đó giảm thiểu tình trạng ùn tắc giao thông và cải thiện chất lượng không khí cho người dân.","audioKind":"ex2"}],"collocations":[{"en":"thereby reducing costs","vi":"nhờ đó giảm chi phí"},{"en":"thereby improving efficiency","vi":"nhờ đó nâng cao hiệu quả"},{"en":"thereby enabling","vi":"nhờ đó tạo điều kiện cho..."}],"wordFamily":[],"synonyms":["thus","consequently"],"antonyms":[],"tipVi":"Thường dùng cấu trúc dấu phẩy kết hợp thereby doing để diễn tả hệ quả của hành động vừa nêu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inertia', 'en-c1-28', 'inertia', '/ɪˈnɝːʃə/', 'C1', 'sự trì trệ; tính ì; thiếu động lực; quán tính', 'n.', 'inert (adj.), inertial (adj.)', NULL, 'Đây là danh từ không đếm được, dùng để chỉ cả quán tính trong vật lý lẫn sự lười nhác, ngại thay đổi trong tâm lý và tổ chức.', 'After weeks of inertia, I finally cleaned the garage.', NULL, 'Sau nhiều tuần chần chừ và trì trệ, cuối cùng tôi cũng dọn dẹp xong nhà để xe.', '{"wordId":"inertia","ukIpa":"/ɪˈnɜːʃə/","usIpa":"/ɪˈnɝːʃə/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A tendency to remain inactive or resist change.","vi":"sự trì trệ; tính ì; thiếu động lực"},{"pos":"n.","en":"Matter''s tendency to resist changes in its speed or direction.","vi":"quán tính"}],"examples":[{"en":"After weeks of inertia, I finally cleaned the garage.","vi":"Sau nhiều tuần chần chừ và trì trệ, cuối cùng tôi cũng dọn dẹp xong nhà để xe.","audioKind":"ex"},{"en":"Institutional inertia can prevent schools from adopting teaching methods that better meet students'' needs.","vi":"Sự trì trệ mang tính hệ thống có thể ngăn cản các trường học áp dụng những phương pháp giảng dạy đáp ứng tốt hơn nhu cầu của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"institutional inertia","vi":"tính ì mang tính hệ thống"},{"en":"overcome inertia","vi":"vượt qua sự trì trệ"},{"en":"the inertia of an object","vi":"quán tính của một vật"}],"wordFamily":["inert (adj.)","inertial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đây là danh từ không đếm được, dùng để chỉ cả quán tính trong vật lý lẫn sự lười nhác, ngại thay đổi trong tâm lý và tổ chức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ploy', 'en-c1-28', 'ploy', '/plɔɪ/', 'C1', 'mưu kế; thủ đoạn; chiêu trò (nhằm đạt lợi thế)', 'n.', NULL, 'Đồng nghĩa: tactic, stratagem', 'Thường hàm ý chơi chữ hoặc dùng thủ đoạn, mang tính toán nhiều hơn so với kế hoạch thông thường.', 'Offering free snacks was a ploy to attract customers.', NULL, 'Việc cung cấp đồ ăn vặt miễn phí là một thủ đoạn để thu hút khách hàng.', '{"wordId":"ploy","ukIpa":"/plɔɪ/","usIpa":"/plɔɪ/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A clever action intended to gain an advantage.","vi":"mưu kế; thủ đoạn; chiêu trò (nhằm đạt lợi thế)"}],"examples":[{"en":"Offering free snacks was a ploy to attract customers.","vi":"Việc cung cấp đồ ăn vặt miễn phí là một thủ đoạn để thu hút khách hàng.","audioKind":"ex"},{"en":"Critics described the sudden price reduction as a marketing ploy rather than a genuine commitment to affordability.","vi":"Các nhà phê bình mô tả việc giảm giá đột ngột là một chiêu trò marketing hơn là một cam kết thực sự về giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"marketing ploy","vi":"chiêu trò marketing"},{"en":"a clever ploy","vi":"mưu kế khôn ngoan"},{"en":"a tactical ploy","vi":"thủ đoạn chiến thuật"}],"wordFamily":[],"synonyms":["tactic","stratagem"],"antonyms":[],"tipVi":"Thường hàm ý chơi chữ hoặc dùng thủ đoạn, mang tính toán nhiều hơn so với kế hoạch thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unwarranted', 'en-c1-28', 'unwarranted', '/ʌnˈwɔːrəntɪd/', 'C1', 'không có cơ sở chính đáng; không có lý do hợp lý; vô cớ', 'adj.', 'warrant (v.), warranted (adj.)', 'Đồng nghĩa: unjustified, groundless · Trái nghĩa: justified, warranted', 'Nhấn mạnh việc thiếu căn cứ hoặc lý do chính đáng, không chỉ đơn thuần mang nghĩa là "không cần thiết".', 'His unwarranted criticism upset everyone who had worked hard.', NULL, 'Những lời chỉ trích vô cớ của anh ấy đã làm tổn thương tất cả những ai đã làm việc chăm chỉ.', '{"wordId":"unwarranted","ukIpa":"/ʌnˈwɒrəntɪd/","usIpa":"/ʌnˈwɔːrəntɪd/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"not justified by the facts or circumstances","vi":"không có cơ sở chính đáng; không có lý do hợp lý; vô cớ"}],"examples":[{"en":"His unwarranted criticism upset everyone who had worked hard.","vi":"Những lời chỉ trích vô cớ của anh ấy đã làm tổn thương tất cả những ai đã làm việc chăm chỉ.","audioKind":"ex"},{"en":"Unwarranted restrictions on public access to information can weaken trust in government and limit informed debate.","vi":"Việc áp đặt các hạn chế vô lý đối với quyền tiếp cận thông tin của công chúng có thể làm suy giảm niềm tin vào chính phủ và cản trở các cuộc tranh luận dựa trên thông tin đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"unwarranted criticism","vi":"lời chỉ trích vô cớ"},{"en":"unwarranted assumptions","vi":"giả định vô căn cứ"},{"en":"unwarranted interference","vi":"sự can thiệp vô lý"}],"wordFamily":["warrant (v.)","warranted (adj.)"],"synonyms":["unjustified","groundless"],"antonyms":["justified","warranted"],"tipVi":"Nhấn mạnh việc thiếu căn cứ hoặc lý do chính đáng, không chỉ đơn thuần mang nghĩa là \"không cần thiết\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contradiction', 'en-c1-28', 'contradiction', '/ˌkɑːntrəˈdɪkʃən/', 'C1', 'sự mâu thuẫn; sự trái ngược; sự phủ nhận; sự cãi lại', 'n.', 'contradict (v.), contradictory (adj.)', 'Đồng nghĩa: inconsistency · Trái nghĩa: consistency', 'Thường dùng cấu trúc a contradiction between A and B.', 'I noticed a contradiction between his two explanations.', NULL, 'Tôi nhận thấy có sự mâu thuẫn giữa hai lời giải thích của anh ấy.', '{"wordId":"contradiction","ukIpa":"/ˌkɒntrəˈdɪkʃən/","usIpa":"/ˌkɑːntrəˈdɪkʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A difference between statements or facts that cannot both be true","vi":"sự mâu thuẫn; sự trái ngược"},{"pos":"n.","en":"The act of saying that a statement is wrong","vi":"sự phủ nhận; sự cãi lại"}],"examples":[{"en":"I noticed a contradiction between his two explanations.","vi":"Tôi nhận thấy có sự mâu thuẫn giữa hai lời giải thích của anh ấy.","audioKind":"ex"},{"en":"There is a clear contradiction between promoting sustainable transport and reducing investment in local bus services.","vi":"Có sự mâu thuẫn rõ ràng giữa việc thúc đẩy giao thông bền vững và việc cắt giảm đầu tư vào các dịch vụ xe buýt địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a contradiction between","vi":"sự mâu thuẫn giữa"},{"en":"in contradiction to","vi":"trái ngược với"},{"en":"a contradiction in terms","vi":"sự mâu thuẫn trong cách dùng từ"}],"wordFamily":["contradict (v.)","contradictory (adj.)"],"synonyms":["inconsistency"],"antonyms":["consistency"],"tipVi":"Thường dùng cấu trúc a contradiction between A and B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_signify', 'en-c1-28', 'signify', '/ˈsɪɡnɪfaɪ/', 'C1', 'biểu thị; có nghĩa là; ra hiệu; bày tỏ', 'v.', 'significance (n.), significant (adj.), significantly (adv.)', 'Đồng nghĩa: indicate, mean, signal', 'Signify mang sắc thái trang trọng, thường đi với danh từ hoặc mệnh đề that.', 'These dark clouds usually signify that rain is coming.', NULL, 'Những đám mây đen kịt ấy thường báo hiệu trời sắp mưa.', '{"wordId":"signify","ukIpa":"/ˈsɪɡnɪfaɪ/","usIpa":"/ˈsɪɡnɪfaɪ/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to mean something or be a sign of it","vi":"biểu thị; có nghĩa là"},{"pos":"v.","en":"to make a feeling or intention known through an action","vi":"ra hiệu; bày tỏ"}],"examples":[{"en":"These dark clouds usually signify that rain is coming.","vi":"Những đám mây đen kịt ấy thường báo hiệu trời sắp mưa.","audioKind":"ex"},{"en":"Rising literacy rates may signify improvements in educational access, especially among previously disadvantaged communities.","vi":"Tỷ lệ biết chữ tăng cao có thể cho thấy sự cải thiện về cơ hội tiếp cận giáo dục, đặc biệt là ở các cộng đồng từng chịu nhiều thiệt thòi.","audioKind":"ex2"}],"collocations":[{"en":"signify a change","vi":"báo hiệu một sự thay đổi"},{"en":"signify approval","vi":"tỏ ý tán thành"},{"en":"signify that","vi":"có nghĩa là"}],"wordFamily":["significance (n.)","significant (adj.)","significantly (adv.)"],"synonyms":["indicate","mean","signal"],"antonyms":[],"tipVi":"Signify mang sắc thái trang trọng, thường đi với danh từ hoặc mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deem', 'en-c1-28', 'deem', '/diːm/', 'C1', 'cho là; đánh giá là; coi là', 'v.', NULL, 'Đồng nghĩa: consider, judge, regard', 'Từ dùng trong văn phong trang trọng, thường có cấu trúc deem＋túc từ＋tính từ, hay gặp ở thể bị động.', 'The inspector deemed our old boiler unsafe to use.', NULL, 'Thanh tra viên đã coi chiếc lò hơi cũ của chúng tôi không an toàn để sử dụng.', '{"wordId":"deem","ukIpa":"/diːm/","usIpa":"/diːm/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To judge or consider someone or something in a particular way.","vi":"cho là; đánh giá là; coi là"}],"examples":[{"en":"The inspector deemed our old boiler unsafe to use.","vi":"Thanh tra viên đã coi chiếc lò hơi cũ của chúng tôi không an toàn để sử dụng.","audioKind":"ex"},{"en":"Public transport should be deemed an essential service rather than merely a source of profit.","vi":"Giao thông công cộng nên được coi là một dịch vụ thiết yếu thay vì chỉ đơn thuần là một nguồn sinh lời.","audioKind":"ex2"}],"collocations":[{"en":"deem necessary","vi":"thấy cần thiết"},{"en":"deem appropriate","vi":"thấy thích hợp"},{"en":"be deemed unsafe","vi":"bị coi là không an toàn"}],"wordFamily":[],"synonyms":["consider","judge","regard"],"antonyms":[],"tipVi":"Từ dùng trong văn phong trang trọng, thường có cấu trúc deem＋túc từ＋tính từ, hay gặp ở thể bị động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deviate', 'en-c1-28', 'deviate', '/ˈdiːvieɪt/', 'C1', 'sai lệch; đi chệch; chệch hướng', 'v.', 'deviation (n.)', 'Đồng nghĩa: diverge, stray · Trái nghĩa: conform', 'Thường đóng vai trò là nội động từ, kết hợp với giới từ deviate from để diễn tả ý nghĩa đi chệch.', 'We deviated from our usual route to avoid traffic.', NULL, 'Chúng tôi đã đi chệch khỏi tuyến đường thường lệ để tránh tắc đường.', '{"wordId":"deviate","ukIpa":"/ˈdiːvieɪt/","usIpa":"/ˈdiːvieɪt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to move away from an expected route, standard, or plan","vi":"sai lệch; đi chệch; chệch hướng"}],"examples":[{"en":"We deviated from our usual route to avoid traffic.","vi":"Chúng tôi đã đi chệch khỏi tuyến đường thường lệ để tránh tắc đường.","audioKind":"ex"},{"en":"Researchers must explain why they deviate from agreed procedures, as unexpected changes may affect the reliability of results.","vi":"Các nhà nghiên cứu phải giải thích lý do tại sao họ đi chệch khỏi các quy trình đã thỏa thuận, vì những thay đổi bất ngờ có thể ảnh hưởng đến độ tin cậy của kết quả.","audioKind":"ex2"}],"collocations":[{"en":"deviate from a plan","vi":"đi chệch kế hoạch"},{"en":"deviate from the norm","vi":"khác biệt so với tiêu chuẩn thông thường"},{"en":"deviate from a route","vi":"đi chệch khỏi lộ trình"}],"wordFamily":["deviation (n.)"],"synonyms":["diverge","stray"],"antonyms":["conform"],"tipVi":"Thường đóng vai trò là nội động từ, kết hợp với giới từ deviate from để diễn tả ý nghĩa đi chệch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_28_1', 'en-c1-28', 'Cách dùng “inertia” (n.) — sự trì trệ; tính ì; thiếu động lực', 'institutional inertia  ·  overcome inertia  ·  the inertia of an object', 'Đây là danh từ không đếm được, dùng để chỉ cả quán tính trong vật lý lẫn sự lười nhác, ngại thay đổi trong tâm lý và tổ chức.', 'Họ từ (Word Family): inert (adj.), inertial (adj.)', '[{"hanzi":"After weeks of inertia, I finally cleaned the garage.","pinyin":"","meaning":"Sau nhiều tuần chần chừ và trì trệ, cuối cùng tôi cũng dọn dẹp xong nhà để xe."},{"hanzi":"Institutional inertia can prevent schools from adopting teaching methods that better meet students'' needs.","pinyin":"","meaning":"Sự trì trệ mang tính hệ thống có thể ngăn cản các trường học áp dụng những phương pháp giảng dạy đáp ứng tốt hơn nhu cầu của học sinh."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_28_2', 'en-c1-28', 'Cách dùng “assert” (v.) — quả quyết, khẳng định, khẳng định chắc nịch rằng điều gì là đúng', 'assert that  ·  assert your rights  ·  assert authority', 'Assert nhấn mạnh thái độ cương quyết khi bày tỏ quan điểm, không đồng nghĩa với việc đã đưa ra bằng chứng xác thực.', 'Họ từ (Word Family): assertion (n.), assertive (adj.), assertively (adv.), assertiveness (n.) | Đồng nghĩa: declare, maintain · Trái nghĩa: deny', '[{"hanzi":"He asserted that he had already paid for lunch.","pinyin":"","meaning":"Anh ấy khẳng định rằng mình đã trả tiền bữa trưa rồi."},{"hanzi":"Some educators assert that regular feedback improves student motivation more effectively than frequent formal examinations.","pinyin":"","meaning":"Một số nhà giáo dục khẳng định rằng phản hồi thường xuyên giúp nâng cao động lực học tập của học sinh hiệu quả hơn là các bài kiểm tra chính thức diễn ra thường xuyên."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_28_3', 'en-c1-28', 'Cách dùng “generalization” (n.) — sự khái quát; lời nhận định chung chung', 'make a generalization  ·  sweeping generalization  ·  broad generalization', 'Lối viết Anh-Anh cũng có thể là generalisation; các kết luận khái quát không phải lúc nào cũng đáng tin cậy.', 'Họ từ (Word Family): general (adj.), generalize (v.), generally (adv.)', '[{"hanzi":"Calling all teenagers lazy is an unfair generalization.","pinyin":"","meaning":"Gắn mác tất cả thanh thiếu niên là lười biếng là một lời nhận định chung chung không công bằng."},{"hanzi":"Researchers should avoid making a generalization about an entire population from a small, unrepresentative sample.","pinyin":"","meaning":"Các nhà nghiên cứu nên tránh đưa ra những kết luận khái quát về toàn bộ dân số chỉ từ một mẫu nhỏ và thiếu tính đại diện."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_28_4', 'en-c1-28', 'Cách dùng “assertion” (n.) — sự khẳng định; lời quả quyết; nhận định chắc nịch', 'make an assertion  ·  unsupported assertion  ·  challenge an assertion', 'Thường dùng cấu trúc the assertion that...; một lời khẳng định chưa chắc đã đi kèm sẵn bằng chứng xác thực.', 'Họ từ (Word Family): assert (v.), assertive (adj.), assertively (adv.), assertiveness (n.) | Đồng nghĩa: claim, statement', '[{"hanzi":"Her assertion that the shop was closed proved wrong.","pinyin":"","meaning":"Lời quả quyết của cô ấy rằng cửa hàng đã đóng cửa hóa ra lại sai."},{"hanzi":"The assertion that economic growth always improves wellbeing requires careful examination of social and environmental evidence.","pinyin":"","meaning":"Nhận định cho rằng tăng trưởng kinh tế luôn cải thiện phúc lợi đòi hỏi phải xem xét kỹ lưỡng các bằng chứng về xã hội và môi trường."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_28_1', 'en-c1-28', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_1_1', 'ten_c1_28_1', 'differentiate', 'Can you differentiate these two birds by their songs?', 'Can you differentiate these two birds by their songs?', '/ˌdɪfəˈrenʃieɪt/', 'Bạn có thể phân biệt hai loài chim này dựa trên tiếng hót của chúng không?', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_1_2', 'ten_c1_28_1', 'conception', 'His conception of a perfect holiday involves no phones.', 'His conception of a perfect holiday involves no phones.', '/kənˈsepʃən/', 'Trong quan niệm của anh ấy về một kỳ nghỉ hoàn hảo thì không có sự xuất hiện của điện thoại.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_1_3', 'ten_c1_28_1', 'generalization', 'Calling all teenagers lazy is an unfair generalization.', 'Calling all teenagers lazy is an unfair generalization.', '/ˌdʒenrələˈzeɪʃən/', 'Gắn mác tất cả thanh thiếu niên là lười biếng là một lời nhận định chung chung không công bằng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_1_4', 'ten_c1_28_1', 'vainly', 'I searched vainly for my keys under the sofa.', 'I searched vainly for my keys under the sofa.', '/ˈveɪnli/', 'Tôi lục tìm chìa khóa dưới ghế sofa nhưng công cốc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_1_5', 'ten_c1_28_1', 'feasible', 'Cycling to work is feasible now that I live nearby.', 'Cycling to work is feasible now that I live nearby.', '/ˈfiːzəbəl/', 'Đạp xe đi làm giờ đã khả thi vì tôi sống gần đây.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_1_6', 'ten_c1_28_1', 'pertain', 'These rules pertain to everyone who uses the kitchen.', 'These rules pertain to everyone who uses the kitchen.', '/pərˈteɪn/', 'Những quy định này áp dụng cho bất kỳ ai sử dụng nhà bếp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_1_7', 'ten_c1_28_1', 'realm', 'Robots have moved beyond the realm of science fiction.', 'Robots have moved beyond the realm of science fiction.', '/relm/', 'Robot đã vượt ra khỏi lĩnh vực khoa học viễn tưởng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_1_8', 'ten_c1_28_1', 'conversely', 'I love busy cities; conversely, my sister prefers quiet villages.', 'I love busy cities; conversely, my sister prefers quiet villages.', '/ˈkɑːnvɜːrsli/', 'Tôi thích những thành phố nhộn nhịp; ngược lại, chị tôi lại thích những ngôi làng yên tĩnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_28_1_1', 'en-c1-28', 'ten_c1_28_1', 'listening', 'listening', 'Can you differentiate these two birds by their songs?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hóa đơn sửa chữa bất ngờ đã thúc đẩy việc chúng tôi phải xem xét lại ngân sách.","Xin đừng hiểu sự im lặng của tôi là thiếu sự quan tâm.","Bạn có thể phân biệt hai loài chim này dựa trên tiếng hót của chúng không?","Tôi nghiêng về phương án rẻ hơn cho kỳ nghỉ của chúng tôi."]'::jsonb, 2, 'Can you differentiate these two birds by their songs? → Bạn có thể phân biệt hai loài chim này dựa trên tiếng hót của chúng không?', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_28_1_2', 'en-c1-28', 'ten_c1_28_1', 'listening', 'listening', 'His conception of a perfect holiday involves no phones.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đạp xe đi làm giờ đã khả thi vì tôi sống gần đây.","Trong quan niệm của anh ấy về một kỳ nghỉ hoàn hảo thì không có sự xuất hiện của điện thoại.","Việc cung cấp đồ ăn vặt miễn phí là một thủ đoạn để thu hút khách hàng.","Việc trồng một cây xanh mang lại cho ngôi nhà mới của chúng tôi cảm giác gắn kết lâu dài."]'::jsonb, 1, 'His conception of a perfect holiday involves no phones. → Trong quan niệm của anh ấy về một kỳ nghỉ hoàn hảo thì không có sự xuất hiện của điện thoại.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_28_1_3', 'en-c1-28', 'ten_c1_28_1', 'listening', 'listening', 'Calling all teenagers lazy is an unfair generalization.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Gắn mác tất cả thanh thiếu niên là lười biếng là một lời nhận định chung chung không công bằng.","Robot đã vượt ra khỏi lĩnh vực khoa học viễn tưởng.","Hóa đơn sửa chữa bất ngờ đã thúc đẩy việc chúng tôi phải xem xét lại ngân sách.","Cô ấy đậy kín hũ lọ, nhờ đó giữ cho bánh quy luôn giòn ngon."]'::jsonb, 0, 'Calling all teenagers lazy is an unfair generalization. → Gắn mác tất cả thanh thiếu niên là lười biếng là một lời nhận định chung chung không công bằng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_28_2', 'en-c1-28', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_2_1', 'ten_c1_28_2', 'differentiate', 'Schools should teach students to differentiate between reliable evidence and unsupported claims in online media.', 'Schools should teach students to differentiate between reliable evidence and unsupported claims in online media.', '/ˌdɪfəˈrenʃieɪt/', 'Nhà trường nên dạy học sinh cách phân biệt giữa bằng chứng đáng tin cậy và những tuyên bố thiếu căn cứ trên truyền thông trực tuyến.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_2_2', 'ten_c1_28_2', 'conception', 'Access to green spaces can broaden children''s conception of nature beyond what they learn in classrooms.', 'Access to green spaces can broaden children''s conception of nature beyond what they learn in classrooms.', '/kənˈsepʃən/', 'Việc tiếp cận không gian xanh có thể mở rộng nhận thức của trẻ em về tự nhiên vượt ra ngoài những gì chúng học được trên lớp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_2_3', 'ten_c1_28_2', 'generalization', 'Researchers should avoid making a generalization about an entire population from a small, unrepresentative sample.', 'Researchers should avoid making a generalization about an entire population from a small, unrepresentative sample.', '/ˌdʒenrələˈzeɪʃən/', 'Các nhà nghiên cứu nên tránh đưa ra những kết luận khái quát về toàn bộ dân số chỉ từ một mẫu nhỏ và thiếu tính đại diện.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_2_4', 'ten_c1_28_2', 'vainly', 'Residents have vainly requested better bus services for years, leaving many dependent on private cars.', 'Residents have vainly requested better bus services for years, leaving many dependent on private cars.', '/ˈveɪnli/', 'Nhiều năm qua, cư dân đã yêu cầu cải thiện dịch vụ xe buýt nhưng không có kết quả, khiến nhiều người vẫn phải phụ thuộc vào xe cá nhân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_2_5', 'ten_c1_28_2', 'feasible', 'Solar power becomes more economically feasible when installation costs fall and reliable energy storage is available.', 'Solar power becomes more economically feasible when installation costs fall and reliable energy storage is available.', '/ˈfiːzəbəl/', 'Năng lượng mặt trời trở nên khả thi hơn về mặt kinh tế khi chi phí lắp đặt giảm và có sẵn hệ thống lưu trữ năng lượng đáng tin cậy.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_28_2_6', 'ten_c1_28_2', 'pertain', 'The committee reviewed documents pertaining to water quality before recommending stricter controls on industrial waste.', 'The committee reviewed documents pertaining to water quality before recommending stricter controls on industrial waste.', '/pərˈteɪn/', 'Ủy ban đã xem xét các tài liệu liên quan đến chất lượng nước trước khi kiến nghị siết chặt việc kiểm soát chất thải công nghiệp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_28_2_1', 'en-c1-28', 'ten_c1_28_2', 'listening', 'listening', 'Schools should teach students to differentiate between reliable evidence and unsupported claims in online media.', NULL, 'Trong câu vừa nghe, từ “differentiate” mang nghĩa nào sau đây?', '["phần định lượng; khẩu phần","phân biệt; nhận biết sự khác nhau","sự phụ thuộc; sự tín nhiệm","chất cặn; phần dư; thặng dư"]'::jsonb, 1, '“differentiate” (/ˌdɪfəˈrenʃieɪt/): phân biệt; nhận biết sự khác nhau. Câu đầy đủ: Schools should teach students to differentiate between reliable evidence and unsupported claims in online media.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_28_2_2', 'en-c1-28', 'ten_c1_28_2', 'listening', 'listening', 'Access to green spaces can broaden children''s conception of nature beyond what they learn in classrooms.', NULL, 'Trong câu vừa nghe, từ “conception” mang nghĩa nào sau đây?', '["hợp kim","hình cầu; quả cầu","sự ngưng chiến; thỏa thuận tạm đình chiến","khái niệm; quan niệm; sự hiểu biết"]'::jsonb, 3, '“conception” (/kənˈsepʃən/): khái niệm; quan niệm; sự hiểu biết. Câu đầy đủ: Access to green spaces can broaden children''s conception of nature beyond what they learn in classrooms.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
