INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_28_13', 'en-c1-28', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “assert” (/əˈsɝːt/) có nghĩa là gì?', '["quả quyết, khẳng định, khẳng định chắc nịch rằng điều gì là đúng","nhờ đó; vì thế; do đó","liên quan đến; gắn liền với; áp dụng cho","sự đánh giá lại; sự xem xét lại"]'::jsonb, 0, '“assert” (v.): quả quyết, khẳng định, khẳng định chắc nịch rằng điều gì là đúng; khẳng định, xác nhận, bảo vệ một quyền lợi, quyền lực hoặc vị thế một cách kiên quyết.', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_28_14', 'en-c1-28', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “Doubtful that a claim or idea is true or useful.”', '["sceptical","reappraisal","ploy","differentiate"]'::jsonb, 0, '“sceptical” (/ˈskeptɪkəl/) nghĩa là: hoài nghi; không dễ tin.', 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_28_15', 'en-c1-28', NULL, 'expanded_quiz', 'cloze', NULL, NULL, 'Chọn từ thích hợp điền vào chỗ trống:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_1', 'en-c1-28', NULL, 'comprehensive_test', 'listening', 'differentiate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thờ ơ; lạnh nhạt","phân biệt; nhận biết sự khác nhau","sự thành lập; sự thiết lập","vuông góc; tạo với một đường thẳng hoặc bề mặt khác một góc vuông"]'::jsonb, 1, 'differentiate (/ˌdɪfəˈrenʃieɪt/) → phân biệt; nhận biết sự khác nhau; làm cho khác biệt; tạo sự khác biệt', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_2', 'en-c1-28', NULL, 'comprehensive_test', 'listening', 'His conception of a perfect holiday involves no phones.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Gắn mác tất cả thanh thiếu niên là lười biếng là một lời nhận định chung chung không công bằng.","Tôi thích những thành phố nhộn nhịp; ngược lại, chị tôi lại thích những ngôi làng yên tĩnh.","Trong quan niệm của anh ấy về một kỳ nghỉ hoàn hảo thì không có sự xuất hiện của điện thoại.","Tôi nghiêng về phương án rẻ hơn cho kỳ nghỉ của chúng tôi."]'::jsonb, 2, 'His conception of a perfect holiday involves no phones. → Trong quan niệm của anh ấy về một kỳ nghỉ hoàn hảo thì không có sự xuất hiện của điện thoại.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_3', 'en-c1-28', NULL, 'comprehensive_test', 'listening', 'generalization', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tận dụng; sử dụng hiệu quả","làm ướt sũng; làm đẫm nước","nhỏ hơn, ít hơn, kém quan trọng hơn","sự khái quát; lời nhận định chung chung"]'::jsonb, 3, 'generalization (/ˌdʒenrələˈzeɪʃən/) → sự khái quát; lời nhận định chung chung; quá trình quy nạp kết luận chung', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_4', 'en-c1-28', NULL, 'comprehensive_test', 'listening', 'I searched vainly for my keys under the sofa.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những quy định này áp dụng cho bất kỳ ai sử dụng nhà bếp.","Tôi lục tìm chìa khóa dưới ghế sofa nhưng công cốc.","Lời quả quyết của cô ấy rằng cửa hàng đã đóng cửa hóa ra lại sai.","Những đám mây đen kịt ấy thường báo hiệu trời sắp mưa."]'::jsonb, 1, 'I searched vainly for my keys under the sofa. → Tôi lục tìm chìa khóa dưới ghế sofa nhưng công cốc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_5', 'en-c1-28', NULL, 'comprehensive_test', 'listening', 'feasible', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đứng yên; tĩnh tại; không di chuyển","khả thi; có thể thực hiện được","xây dựng; dựng lên","phòng trọ kiêm phòng ngủ và phòng khách"]'::jsonb, 1, 'feasible (/ˈfiːzəbəl/) → khả thi; có thể thực hiện được', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_6', 'en-c1-28', NULL, 'comprehensive_test', 'listening', 'These rules pertain to everyone who uses the kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự an toàn là điều quan trọng hàng đầu khi chúng tôi đưa trẻ em đi bơi.","Anh ấy khẳng định rằng mình đã trả tiền bữa trưa rồi.","Những quy định này áp dụng cho bất kỳ ai sử dụng nhà bếp.","Tôi lục tìm chìa khóa dưới ghế sofa nhưng công cốc."]'::jsonb, 2, 'These rules pertain to everyone who uses the kitchen. → Những quy định này áp dụng cho bất kỳ ai sử dụng nhà bếp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_7', 'en-c1-28', NULL, 'comprehensive_test', 'listening', 'realm', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự chín chắn; tính điềm tĩnh","liệt kê; kể ra; nêu rõ từng mục","lĩnh vực; phạm vi","chủ nghĩa Mác"]'::jsonb, 2, 'realm (/relm/) → lĩnh vực; phạm vi; vương quốc', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_8', 'en-c1-28', NULL, 'comprehensive_test', 'listening', 'I love busy cities; conversely, my sister prefers quiet villages.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những đám mây đen kịt ấy thường báo hiệu trời sắp mưa.","Tôi nhận thấy có sự mâu thuẫn giữa hai lời giải thích của anh ấy.","Bạn có thể phân biệt hai loài chim này dựa trên tiếng hót của chúng không?","Tôi thích những thành phố nhộn nhịp; ngược lại, chị tôi lại thích những ngôi làng yên tĩnh."]'::jsonb, 3, 'I love busy cities; conversely, my sister prefers quiet villages. → Tôi thích những thành phố nhộn nhịp; ngược lại, chị tôi lại thích những ngôi làng yên tĩnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_9', 'en-c1-28', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “possible and practical to achieve with available resources”?', '["feasible","signify","realm","incline"]'::jsonb, 0, 'feasible (/ˈfiːzəbəl/) → khả thi; có thể thực hiện được', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_10', 'en-c1-28', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To relate to or apply to a particular subject.”?', '["practicable","pertain","generalization","conception"]'::jsonb, 1, 'pertain (/pərˈteɪn/) → liên quan đến; gắn liền với; áp dụng cho', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_11', 'en-c1-28', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An area of knowledge, activity, or experience.”?', '["differentiate","realm","unwarranted","thereby"]'::jsonb, 1, 'realm (/relm/) → lĩnh vực; phạm vi', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_12', 'en-c1-28', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “used to introduce an opposite situation or relationship”?', '["conversely","practicable","assert","ploy"]'::jsonb, 0, 'conversely (/ˈkɑːnvɜːrsli/) → ngược lại; trái lại', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_13', 'en-c1-28', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A fresh assessment of something, often leading to changed views.”?', '["incline","ploy","reappraisal","signify"]'::jsonb, 2, 'reappraisal (/ˌriːəˈpreɪzəl/) → sự đánh giá lại; sự xem xét lại', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
