INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_18', 'en-c1-28', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should teach students to differentiate between reliable evidence and unsupported claims in online media.', 'Dựa vào câu trên, từ “differentiate” có nghĩa phù hợp nhất là gì?', '["phân biệt; nhận biết sự khác nhau","khả năng cạnh tranh","vẻ hùng vĩ; sự tráng lệ; sự uy nghiêm","trang trí; làm cho đẹp thêm"]'::jsonb, 0, 'differentiate: phân biệt; nhận biết sự khác nhau; làm cho khác biệt; tạo sự khác biệt. Dịch cả câu: Nhà trường nên dạy học sinh cách phân biệt giữa bằng chứng đáng tin cậy và những tuyên bố thiếu căn cứ trên truyền thông trực tuyến.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_19', 'en-c1-28', NULL, 'comprehensive_test', 'reading', NULL, 'Access to green spaces can broaden children''s conception of nature beyond what they learn in classrooms.', 'Dựa vào câu trên, từ “conception” có nghĩa phù hợp nhất là gì?', '["khái niệm; quan niệm; sự hiểu biết","bố trí theo hình nan hoa; tỏa ra từ tâm","ám ảnh; bận tâm quá mức; khó dứt ra được","nhiều sự kiện; đầy biến động; nhiều chuyện"]'::jsonb, 0, 'conception: khái niệm; quan niệm; sự hiểu biết; sự thụ thai; sự phác thảo; sự hình thành (ý tưởng, kế hoạch). Dịch cả câu: Việc tiếp cận không gian xanh có thể mở rộng nhận thức của trẻ em về tự nhiên vượt ra ngoài những gì chúng học được trên lớp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_20', 'en-c1-28', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers should avoid making a generalization about an entire population from a small, unrepresentative sample.', 'Dựa vào câu trên, từ “generalization” có nghĩa phù hợp nhất là gì?', '["phủ lên nhau; chồng chéo lên nhau; có điểm chung","sự khái quát; lời nhận định chung chung","làm xa lánh; khiến ai đó không muốn ủng hộ","phụ; dự phòng; bổ trợ"]'::jsonb, 1, 'generalization: sự khái quát; lời nhận định chung chung; quá trình quy nạp kết luận chung. Dịch cả câu: Các nhà nghiên cứu nên tránh đưa ra những kết luận khái quát về toàn bộ dân số chỉ từ một mẫu nhỏ và thiếu tính đại diện.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_21', 'en-c1-28', NULL, 'comprehensive_test', 'reading', NULL, 'Residents have vainly requested better bus services for years, leaving many dependent on private cars.', 'Dựa vào câu trên, từ “vainly” có nghĩa phù hợp nhất là gì?', '["một cách vô ích; hoài công","giảm dần; thu hẹp dần","chuyển thể thành kịch","nhang; trầm hương; hương"]'::jsonb, 0, 'vainly: một cách vô ích; hoài công. Dịch cả câu: Nhiều năm qua, cư dân đã yêu cầu cải thiện dịch vụ xe buýt nhưng không có kết quả, khiến nhiều người vẫn phải phụ thuộc vào xe cá nhân.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_22', 'en-c1-28', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “biểu thị; có nghĩa là”', '["vocal","signify","youthful","secluded"]'::jsonb, 1, 'biểu thị; có nghĩa là → signify (/ˈsɪɡnɪfaɪ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_23', 'en-c1-28', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cho là; đánh giá là; coi là”', '["zeal","offspring","deem","mercury"]'::jsonb, 2, 'cho là; đánh giá là; coi là → deem (/diːm/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_28_24', 'en-c1-28', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sai lệch; đi chệch; chệch hướng”', '["hull","tinge","studious","deviate"]'::jsonb, 3, 'sai lệch; đi chệch; chệch hướng → deviate (/ˈdiːvieɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-29', 'en', 'Bài 29: Tư duy & Nhận thức (4) - CEFR C1', 'CEFR C1', 'C1 · Tư duy', '25 từ vựng Tiếng Anh CEFR C1 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5029, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conceivable', 'en-c1-29', 'conceivable', '/kənˈsiːvəbl/', 'C1', 'có thể tưởng tượng được; có thể hiểu được', 'adj.', 'conceive (v.), conceivably (adv.), inconceivable (adj.)', 'Đồng nghĩa: imaginable, possible · Trái nghĩa: inconceivable, unimaginable', 'Biểu thị khả năng có thể hình dung hoặc có thể xảy ra, không đồng nghĩa với việc rất có khả năng xảy ra.', 'We searched every conceivable place for the missing keys.', NULL, 'Chúng tôi đã lục tung mọi ngóc ngách có thể nghĩ ra để tìm những chiếc chìa khóa bị mất.', '{"wordId":"conceivable","ukIpa":"/kənˈsiːvəbl/","usIpa":"/kənˈsiːvəbl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Possible to imagine or believe.","vi":"có thể tưởng tượng được; có thể hiểu được"}],"examples":[{"en":"We searched every conceivable place for the missing keys.","vi":"Chúng tôi đã lục tung mọi ngóc ngách có thể nghĩ ra để tìm những chiếc chìa khóa bị mất.","audioKind":"ex"},{"en":"It is conceivable that advances in renewable energy could significantly reduce global dependence on fossil fuels.","vi":"Có thể hình dung rằng những tiến bộ trong năng lượng tái tạo sẽ làm giảm đáng kể sự phụ thuộc của toàn cầu vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"every conceivable way","vi":"mọi cách có thể nghĩ ra"},{"en":"every conceivable option","vi":"mọi lựa chọn có thể"},{"en":"it is conceivable that","vi":"có thể là"}],"wordFamily":["conceive (v.)","conceivably (adv.)","inconceivable (adj.)"],"synonyms":["imaginable","possible"],"antonyms":["inconceivable","unimaginable"],"tipVi":"Biểu thị khả năng có thể hình dung hoặc có thể xảy ra, không đồng nghĩa với việc rất có khả năng xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_analogy', 'en-c1-29', 'analogy', '/əˈnælədʒi/', 'C1', 'phép loại suy; sự so sánh tương đương', 'n.', 'analogous (adj.), analogously (adv.)', 'Đồng nghĩa: comparison', 'Thường dùng cấu trúc draw an analogy between A and B.', 'Her analogy compared our busy kitchen to a train station.', NULL, 'Cô ấy đã ví nhà bếp bận rộn của chúng tôi như một nhà ga xe lửa.', '{"wordId":"analogy","ukIpa":"/əˈnælədʒi/","usIpa":"/əˈnælədʒi/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A comparison used to explain something through a similar example","vi":"phép loại suy; sự so sánh tương đương"}],"examples":[{"en":"Her analogy compared our busy kitchen to a train station.","vi":"Cô ấy đã ví nhà bếp bận rộn của chúng tôi như một nhà ga xe lửa.","audioKind":"ex"},{"en":"Teachers often draw an analogy between electrical circuits and flowing water to explain unfamiliar scientific concepts.","vi":"Giáo viên thường dùng phép so sánh giữa mạch điện và dòng nước chảy để giải thích các khái niệm khoa học xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"draw an analogy","vi":"lập phép loại suy"},{"en":"an analogy between","vi":"phép so sánh giữa"},{"en":"a useful analogy","vi":"một phép loại suy hữu ích"}],"wordFamily":["analogous (adj.)","analogously (adv.)"],"synonyms":["comparison"],"antonyms":[],"tipVi":"Thường dùng cấu trúc draw an analogy between A and B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attributable', 'en-c1-29', 'attributable', '/əˈtrɪbjətəbl/', 'C1', 'có thể quy cho; do... gây ra', 'adj.', 'attribute (v.), attribution (n.)', NULL, 'Thường đi trong cấu trúc cố định be attributable to, theo sau to là nguyên nhân.', 'The damp patch is attributable to a leaking pipe.', NULL, 'Vết ẩm mốc đó là do ống nước bị rò rỉ gây ra.', '{"wordId":"attributable","ukIpa":"/əˈtrɪbjətəbl/","usIpa":"/əˈtrɪbjətəbl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"caused by or explainable as the result of something","vi":"có thể quy cho; do... gây ra"}],"examples":[{"en":"The damp patch is attributable to a leaking pipe.","vi":"Vết ẩm mốc đó là do ống nước bị rò rỉ gây ra.","audioKind":"ex"},{"en":"Much of the improvement in public health is attributable to cleaner drinking water and better sanitation.","vi":"Phần lớn sự cải thiện về sức khỏe cộng đồng là nhờ vào nguồn nước uống sạch hơn và hệ thống vệ sinh tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"attributable to","vi":"có thể quy cho"},{"en":"directly attributable to","vi":"bắt nguồn trực tiếp từ"},{"en":"largely attributable to","vi":"phần lớn là do"}],"wordFamily":["attribute (v.)","attribution (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi trong cấu trúc cố định be attributable to, theo sau to là nguyên nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_formulate', 'en-c1-29', 'formulate', '/ˈfɔːrmjəleɪt/', 'C1', 'xây dựng; hoạch định; phát biểu rõ ràng; diễn đạt chính xác', 'v.', 'formulation (n.), reformulate (v.)', 'Đồng nghĩa: devise, develop', 'Mang tính trang trọng hơn từ make, thường kết hợp với plan, policy, hypothesis.', 'We need to formulate a plan before moving house.', NULL, 'Chúng ta cần lên kế hoạch trước khi chuyển nhà.', '{"wordId":"formulate","ukIpa":"/ˈfɔːmjəleɪt/","usIpa":"/ˈfɔːrmjəleɪt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to develop a plan, policy, or idea carefully","vi":"xây dựng; hoạch định"},{"pos":"v.","en":"to express an idea clearly and precisely","vi":"phát biểu rõ ràng; diễn đạt chính xác"}],"examples":[{"en":"We need to formulate a plan before moving house.","vi":"Chúng ta cần lên kế hoạch trước khi chuyển nhà.","audioKind":"ex"},{"en":"Governments should formulate transport policies that reduce congestion while ensuring affordable access for all residents.","vi":"Chính phủ nên hoạch định các chính sách giao thông nhằm giảm thiểu tình trạng ùn tắc đồng thời đảm bảo khả năng chi trả cho tất cả người dân.","audioKind":"ex2"}],"collocations":[{"en":"formulate a plan","vi":"lên kế hoạch"},{"en":"formulate a policy","vi":"hoạch định chính sách"},{"en":"formulate a hypothesis","vi":"đưa ra giả thuyết"},{"en":"formulate a response","vi":"chuẩn bị một câu trả lời"}],"wordFamily":["formulation (n.)","reformulate (v.)"],"synonyms":["devise","develop"],"antonyms":[],"tipVi":"Mang tính trang trọng hơn từ make, thường kết hợp với plan, policy, hypothesis.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_verify', 'en-c1-29', 'verify', '/ˈverɪfaɪ/', 'C1', 'xác minh; kiểm chứng; tra lại cho chính xác', 'v.', 'verification (n.), verifiable (adj.)', 'Đồng nghĩa: confirm, check', 'Verify nhấn mạnh việc xác minh tính chân thực hoặc độ chính xác, đi sau là danh từ hoặc mệnh đề.', 'Please verify your address before we send the parcel.', NULL, 'Vui lòng xác minh địa chỉ của bạn trước khi chúng tôi gửi bưu kiện.', '{"wordId":"verify","ukIpa":"/ˈverɪfaɪ/","usIpa":"/ˈverɪfaɪ/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to check that something is true, accurate, or genuine","vi":"xác minh; kiểm chứng; tra lại cho chính xác"}],"examples":[{"en":"Please verify your address before we send the parcel.","vi":"Vui lòng xác minh địa chỉ của bạn trước khi chúng tôi gửi bưu kiện.","audioKind":"ex"},{"en":"Researchers must verify their findings through repeated experiments before presenting them to the wider scientific community.","vi":"Các nhà nghiên cứu phải xác minh các phát hiện của họ thông qua các thí nghiệm lặp lại trước khi trình bày chúng trước cộng đồng khoa học rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"verify information","vi":"xác minh thông tin"},{"en":"verify someone''s identity","vi":"xác minh danh tính của ai đó"},{"en":"verify the accuracy of","vi":"xác minh tính chính xác của"}],"wordFamily":["verification (n.)","verifiable (adj.)"],"synonyms":["confirm","check"],"antonyms":[],"tipVi":"Verify nhấn mạnh việc xác minh tính chân thực hoặc độ chính xác, đi sau là danh từ hoặc mệnh đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enumerate', 'en-c1-29', 'enumerate', '/ɪˈnuːməreɪt/', 'C1', 'liệt kê; kể ra; nêu rõ từng mục', 'v.', 'enumeration (n.), enumerator (n.)', 'Đồng nghĩa: list, itemise', 'Là từ mang tính trang trọng, nhấn mạnh việc liệt kê từng mục một; trong giao tiếp hàng ngày thường dùng list.', 'She enumerated the repairs needed before we could move in.', NULL, 'Cô ấy đã liệt kê các mục cần sửa chữa trước khi chúng tôi có thể chuyển vào ở.', '{"wordId":"enumerate","ukIpa":"/ɪˈnjuːməreɪt/","usIpa":"/ɪˈnuːməreɪt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To name things separately, one after another.","vi":"liệt kê; kể ra; nêu rõ từng mục"}],"examples":[{"en":"She enumerated the repairs needed before we could move in.","vi":"Cô ấy đã liệt kê các mục cần sửa chữa trước khi chúng tôi có thể chuyển vào ở.","audioKind":"ex"},{"en":"The report enumerates several barriers to higher education, including tuition costs and limited access to reliable transport.","vi":"Báo cáo này liệt kê một số rào cản đối với giáo dục đại học, bao gồm chi phí học phí và khả năng tiếp cận phương tiện giao thông đáng tin cậy còn hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"enumerate the reasons","vi":"liệt kê các lý do"},{"en":"enumerate the benefits","vi":"liệt kê các lợi ích"},{"en":"enumerate the main points","vi":"liệt kê các điểm chính"}],"wordFamily":["enumeration (n.)","enumerator (n.)"],"synonyms":["list","itemise"],"antonyms":[],"tipVi":"Là từ mang tính trang trọng, nhấn mạnh việc liệt kê từng mục một; trong giao tiếp hàng ngày thường dùng list.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lapse', 'en-c1-29', 'lapse', '/læps/', 'C1', 'sự lơ đễnh; sai sót nhỏ; khoảng thời gian; hết hạn; mất hiệu lực', 'n.', NULL, 'Đồng nghĩa: oversight, slip', 'Lỗi lãng quên dùng a lapse in; khoảng thời gian dùng a lapse of.', 'A brief lapse in concentration made me miss my stop.', NULL, 'Một phút mất tập trung chớp nhoáng đã khiến tôi đi quá trạm dừng.', '{"wordId":"lapse","ukIpa":"/læps/","usIpa":"/læps/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"a brief failure of attention, judgment, or memory","vi":"sự lơ đễnh; sai sót nhỏ"},{"pos":"n.","en":"a period of time between two events","vi":"khoảng thời gian"},{"pos":"v.","en":"to end because something has not been renewed or maintained","vi":"hết hạn; mất hiệu lực"}],"examples":[{"en":"A brief lapse in concentration made me miss my stop.","vi":"Một phút mất tập trung chớp nhoáng đã khiến tôi đi quá trạm dừng.","audioKind":"ex"},{"en":"Even a minor lapse in judgment can undermine public confidence in the management of essential services.","vi":"Ngay cả một sai sót nhỏ trong phán quyết cũng có thể làm xói mòn niềm tin của công chúng vào công tác quản lý các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"a lapse in concentration","vi":"sự mất tập trung chớp nhoáng"},{"en":"a lapse of judgment","vi":"sai sót trong phán quyết"},{"en":"a time lapse","vi":"khoảng thời gian trôi qua"},{"en":"let a policy lapse","vi":"để hợp đồng hết hiệu lực"}],"wordFamily":[],"synonyms":["oversight","slip"],"antonyms":[],"tipVi":"Lỗi lãng quên dùng a lapse in; khoảng thời gian dùng a lapse of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ascribe', 'en-c1-29', 'ascribe', '/əˈskraɪb/', 'C1', 'quy cho; quy nguyên nhân; cho là; quy công cho', 'v.', 'ascription (n.)', 'Đồng nghĩa: attribute', 'Cấu trúc cố định ascribe A to B: quy A cho B hoặc cho rằng A là do B gây ra.', 'I ascribe my better sleep to regular evening walks.', NULL, 'Tôi cho rằng việc giấc ngủ của mình tốt hơn là nhờ thói quen đi dạo đều đặn vào buổi tối.', '{"wordId":"ascribe","ukIpa":"/əˈskraɪb/","usIpa":"/əˈskraɪb/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To consider something to be caused by a particular factor","vi":"quy cho; quy nguyên nhân"},{"pos":"v.","en":"To assign a quality, work, or statement to someone","vi":"cho là; quy công cho"}],"examples":[{"en":"I ascribe my better sleep to regular evening walks.","vi":"Tôi cho rằng việc giấc ngủ của mình tốt hơn là nhờ thói quen đi dạo đều đặn vào buổi tối.","audioKind":"ex"},{"en":"Researchers should not ascribe differences in academic performance solely to individual effort without considering social circumstances.","vi":"Các nhà nghiên cứu không nên quy những khác biệt về thành tích học tập hoàn toàn cho nỗ lực cá nhân mà không xem xét các yếu tố hoàn cảnh xã hội.","audioKind":"ex2"}],"collocations":[{"en":"ascribe success to","vi":"quy thành công cho"},{"en":"ascribe importance to","vi":"đánh giá cao; cho là quan trọng"},{"en":"ascribe a work to","vi":"quy tác phẩm cho ai"}],"wordFamily":["ascription (n.)"],"synonyms":["attribute"],"antonyms":[],"tipVi":"Cấu trúc cố định ascribe A to B: quy A cho B hoặc cho rằng A là do B gây ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contrive', 'en-c1-29', 'contrive', '/kənˈtraɪv/', 'C1', 'xoay sở, tìm cách làm được việc gì khó khăn hoặc bất ngờ; vận dụng mưu trí để lên kế hoạch, sắp đặt hoặc thiết kế cái gì', 'v.', 'contrivance (n.), contrived (adj.)', 'Đồng nghĩa: manage, devise', 'contrive to do diễn tả ý xoay sở làm gì; contrived thường dùng để chỉ sự gượng gạo, thiếu tự nhiên.', 'We contrived to fit every suitcase into the tiny car.', NULL, 'Chúng tôi đã xoay sở nhét vừa vặn từng chiếc va-li vào chiếc xe ô tô chật chội.', '{"wordId":"contrive","ukIpa":"/kənˈtraɪv/","usIpa":"/kənˈtraɪv/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to manage to do something difficult or unexpected","vi":"xoay sở, tìm cách làm được việc gì khó khăn hoặc bất ngờ"},{"pos":"v.","en":"to create or arrange something through clever planning","vi":"vận dụng mưu trí để lên kế hoạch, sắp đặt hoặc thiết kế cái gì"}],"examples":[{"en":"We contrived to fit every suitcase into the tiny car.","vi":"Chúng tôi đã xoay sở nhét vừa vặn từng chiếc va-li vào chiếc xe ô tô chật chội.","audioKind":"ex"},{"en":"Despite limited funding, the research team contrived to develop an affordable device for monitoring water quality.","vi":"Mặc dù nguồn kinh phí eo hẹp, đội ngũ nghiên cứu vẫn khéo léo thiết kế thành công một thiết bị giá rẻ chuyên dụng để giám sát chất lượng nguồn nước.","audioKind":"ex2"}],"collocations":[{"en":"contrive to do something","vi":"xoay sở để làm điều gì đó"},{"en":"contrive a way","vi":"nghĩ ra cách"},{"en":"contrive a plan","vi":"lên kế hoạch mưu trí"}],"wordFamily":["contrivance (n.)","contrived (adj.)"],"synonyms":["manage","devise"],"antonyms":[],"tipVi":"contrive to do diễn tả ý xoay sở làm gì; contrived thường dùng để chỉ sự gượng gạo, thiếu tự nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_approximation', 'en-c1-29', 'approximation', '/əˌprɑːksɪˈmeɪʃən/', 'C1', 'sự ước tính; giá trị gần đúng; vật tương tự; sự giống nhau', 'n.', 'approximate (v.), approximate (adj.), approximately (adv.)', 'Đồng nghĩa: estimate', 'Thường dùng cụm an approximation of; nhấn mạnh sự gần đúng nhưng chưa hoàn toàn chính xác.', 'My budget is only a rough approximation of the cost.', NULL, 'Ngân sách của tôi chỉ là một ước tính sơ lược về chi phí.', '{"wordId":"approximation","ukIpa":"/əˌprɒksɪˈmeɪʃən/","usIpa":"/əˌprɑːksɪˈmeɪʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"An estimate that is close to the exact value.","vi":"sự ước tính; giá trị gần đúng"},{"pos":"n.","en":"Something similar to another thing but not exactly the same.","vi":"vật tương tự; sự giống nhau"}],"examples":[{"en":"My budget is only a rough approximation of the cost.","vi":"Ngân sách của tôi chỉ là một ước tính sơ lược về chi phí.","audioKind":"ex"},{"en":"Computer models provide an approximation of future climate conditions rather than a precise prediction of every change.","vi":"Các mô hình máy tính cung cấp sự ước tính về điều kiện khí hậu trong tương lai thay vì dự đoán chính xác cho mọi thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"a rough approximation","vi":"một ước tính sơ lược"},{"en":"a close approximation","vi":"một sự mô phỏng rất gần sát"},{"en":"a reasonable approximation","vi":"một mức ước tính hợp lý"}],"wordFamily":["approximate (v.)","approximate (adj.)","approximately (adv.)"],"synonyms":["estimate"],"antonyms":[],"tipVi":"Thường dùng cụm an approximation of; nhấn mạnh sự gần đúng nhưng chưa hoàn toàn chính xác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decipher', 'en-c1-29', 'decipher', '/dɪˈsaɪfər/', 'C1', 'giải mã; nhận diện; đọc hiểu', 'v.', 'decipherable (adj.), indecipherable (adj.), decipherment (n.)', 'Đồng nghĩa: decode, interpret · Trái nghĩa: encode', 'Chỉ đóng vai trò là động từ; có thể dùng cho việc giải mã mật mã hoặc nhận dạng chữ viết tay khó đọc.', 'Can you decipher the handwriting on this old postcard?', NULL, 'Bạn có thể đọc được chữ viết tay trên tấm bưu điện cũ này không?', '{"wordId":"decipher","ukIpa":"/dɪˈsaɪfə/","usIpa":"/dɪˈsaɪfər/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"work out the meaning of unclear writing or coded information","vi":"giải mã; nhận diện; đọc hiểu"}],"examples":[{"en":"Can you decipher the handwriting on this old postcard?","vi":"Bạn có thể đọc được chữ viết tay trên tấm bưu điện cũ này không?","audioKind":"ex"},{"en":"Researchers used advanced imaging techniques to decipher damaged manuscripts and gain insights into ancient societies.","vi":"Các nhà nghiên cứu đã sử dụng các kỹ thuật hình ảnh tiên tiến để giải mã những bản thảo bị hư hỏng và có thêm hiểu biết về các xã hội cổ đại.","audioKind":"ex2"}],"collocations":[{"en":"decipher a code","vi":"giải mã mật mã"},{"en":"decipher handwriting","vi":"đọc chữ viết tay"},{"en":"decipher a message","vi":"giải mã thông điệp"}],"wordFamily":["decipherable (adj.)","indecipherable (adj.)","decipherment (n.)"],"synonyms":["decode","interpret"],"antonyms":["encode"],"tipVi":"Chỉ đóng vai trò là động từ; có thể dùng cho việc giải mã mật mã hoặc nhận dạng chữ viết tay khó đọc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intellect', 'en-c1-29', 'intellect', '/ˈɪntəlekt/', 'C1', 'trí tuệ; năng lực tư duy; bậc trí thức; người có tài năng xuất chúng', 'n.', 'intellectual (adj.), intellectual (n.), intellectually (adv.)', 'Đồng nghĩa: intelligence, reason', 'intellect nhấn mạnh khả năng thấu hiểu và suy luận, không đồng nghĩa với lượng kiến thức.', 'Her sharp intellect makes difficult puzzles seem surprisingly easy.', NULL, 'Trí tuệ sắc bén của cô ấy khiến những câu đố hóc búa trở nên dễ dàng đến ngạc nhiên.', '{"wordId":"intellect","ukIpa":"/ˈɪntəlekt/","usIpa":"/ˈɪntəlekt/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"The ability to understand ideas, think logically, and solve problems.","vi":"trí tuệ; năng lực tư duy"},{"pos":"n.","en":"A person with exceptional intelligence and reasoning ability.","vi":"bậc trí thức; người có tài năng xuất chúng"}],"examples":[{"en":"Her sharp intellect makes difficult puzzles seem surprisingly easy.","vi":"Trí tuệ sắc bén của cô ấy khiến những câu đố hóc búa trở nên dễ dàng đến ngạc nhiên.","audioKind":"ex"},{"en":"Education should develop students'' intellect while also nurturing creativity, emotional awareness, and the ability to collaborate.","vi":"Giáo dục nên phát triển trí tuệ của học sinh đồng thời nuôi dưỡng sự sáng tạo, nhận thức cảm xúc và khả năng hợp tác.","audioKind":"ex2"}],"collocations":[{"en":"a sharp intellect","vi":"trí tuệ sắc sảo"},{"en":"a formidable intellect","vi":"tư duy uyên bác"},{"en":"develop the intellect","vi":"phát triển trí tuệ"}],"wordFamily":["intellectual (adj.)","intellectual (n.)","intellectually (adv.)"],"synonyms":["intelligence","reason"],"antonyms":[],"tipVi":"intellect nhấn mạnh khả năng thấu hiểu và suy luận, không đồng nghĩa với lượng kiến thức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_underlying', 'en-c1-29', 'underlying', '/ˌʌndərˈlaɪɪŋ/', 'C1', 'cơ bản; tiềm ẩn; ngầm; nằm ở bên dưới bề mặt', 'adj.', 'underlie (v.)', 'Đồng nghĩa: fundamental, basic', 'Thường đứng trước danh từ, nhấn mạnh nguyên nhân hoặc nền tảng ẩn giấu đằng sau hiện tượng bề ngoài.', 'The mechanic found the underlying cause of the noise.', NULL, 'Thợ máy đã tìm ra nguyên nhân sâu xa gây ra tiếng ồn.', '{"wordId":"underlying","ukIpa":"/ˌʌndəˈlaɪɪŋ/","usIpa":"/ˌʌndərˈlaɪɪŋ/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"causing or influencing something without being immediately obvious","vi":"cơ bản; tiềm ẩn; ngầm"},{"pos":"adj.","en":"lying beneath the surface of something","vi":"nằm ở bên dưới bề mặt"}],"examples":[{"en":"The mechanic found the underlying cause of the noise.","vi":"Thợ máy đã tìm ra nguyên nhân sâu xa gây ra tiếng ồn.","audioKind":"ex"},{"en":"Addressing the underlying causes of poverty requires sustained investment in education, healthcare, and secure employment.","vi":"Việc giải quyết các nguyên nhân sâu xa của đói nghèo đòi hỏi phải đầu tư liên tục vào giáo dục, y tế và việc làm ổn định.","audioKind":"ex2"}],"collocations":[{"en":"underlying cause","vi":"nguyên nhân gốc rễ"},{"en":"underlying problem","vi":"vấn đề tiềm ẩn"},{"en":"underlying assumption","vi":"giả định nền tảng"},{"en":"underlying health condition","vi":"bệnh nền"}],"wordFamily":["underlie (v.)"],"synonyms":["fundamental","basic"],"antonyms":[],"tipVi":"Thường đứng trước danh từ, nhấn mạnh nguyên nhân hoặc nền tảng ẩn giấu đằng sau hiện tượng bề ngoài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_domain', 'en-c1-29', 'domain', '/doʊˈmeɪn/', 'C1', 'lĩnh vực; phạm vi; lãnh địa; quyền hạn; tên miền', 'n.', NULL, 'Đồng nghĩa: field, sphere, territory', 'Lĩnh vực có nét nghĩa gần với field; cụm từ in the public domain có nghĩa là thuộc về công chúng, ai cũng có thể sử dụng.', 'Electrical repairs are my brother''s domain, not mine.', NULL, 'Sửa chữa điện đóm là sở trường của anh trai tôi chứ không phải của tôi.', '{"wordId":"domain","ukIpa":"/dəˈmeɪn/","usIpa":"/doʊˈmeɪn/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"a particular area of knowledge, activity, or responsibility","vi":"lĩnh vực; phạm vi"},{"pos":"n.","en":"an area controlled by a particular ruler or authority","vi":"lãnh địa; quyền hạn"},{"pos":"n.","en":"an internet area identified by a shared name","vi":"tên miền"}],"examples":[{"en":"Electrical repairs are my brother''s domain, not mine.","vi":"Sửa chữa điện đóm là sở trường của anh trai tôi chứ không phải của tôi.","audioKind":"ex"},{"en":"Environmental protection should not be regarded as the exclusive domain of scientists, since public participation is essential.","vi":"Bảo vệ môi trường không nên được coi là lĩnh vực độc quyền của các nhà khoa học, vì sự tham gia của công chúng là vô cùng quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"the domain of science","vi":"lĩnh vực khoa học"},{"en":"public domain","vi":"phạm vi công cộng"},{"en":"domain name","vi":"tên miền"},{"en":"exclusive domain","vi":"lĩnh vực độc quyền"}],"wordFamily":[],"synonyms":["field","sphere","territory"],"antonyms":[],"tipVi":"Lĩnh vực có nét nghĩa gần với field; cụm từ in the public domain có nghĩa là thuộc về công chúng, ai cũng có thể sử dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_idealism', 'en-c1-29', 'idealism', '/aɪˈdiːəlɪzəm/', 'C1', 'chủ nghĩa lý tưởng; chủ nghĩa duy tâm', 'n.', 'ideal (n.), idealist (n.), idealistic (adj.), idealistically (adv.)', 'Trái nghĩa: realism', 'Thường là danh từ không đếm được; trong bối cảnh triết học được dịch là "chủ nghĩa duy tâm".', 'Her idealism inspired us to clean the riverbank.', NULL, 'Chủ nghĩa lý tưởng của cô ấy đã truyền cảm hứng cho chúng tôi dọn dẹp bờ sông.', '{"wordId":"idealism","ukIpa":"/aɪˈdɪəlɪzəm/","usIpa":"/aɪˈdiːəlɪzəm/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"belief in pursuing perfect standards, even when impractical","vi":"chủ nghĩa lý tưởng"},{"pos":"n.","en":"the philosophical view that reality depends on mind or consciousness","vi":"chủ nghĩa duy tâm"}],"examples":[{"en":"Her idealism inspired us to clean the riverbank.","vi":"Chủ nghĩa lý tưởng của cô ấy đã truyền cảm hứng cho chúng tôi dọn dẹp bờ sông.","audioKind":"ex"},{"en":"Youthful idealism can encourage social change, but effective policies also require practical planning and reliable funding.","vi":"Chủ nghĩa lý tưởng của tuổi trẻ có thể thúc đẩy sự thay đổi xã hội, nhưng các chính sách hiệu quả cũng đòi hỏi sự lập kế hoạch thiết thực và nguồn tài chính đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"youthful idealism","vi":"chủ nghĩa lý tưởng tuổi trẻ"},{"en":"political idealism","vi":"chủ nghĩa lý tưởng chính trị"},{"en":"a sense of idealism","vi":"tinh thần lý tưởng"}],"wordFamily":["ideal (n.)","idealist (n.)","idealistic (adj.)","idealistically (adv.)"],"synonyms":[],"antonyms":["realism"],"tipVi":"Thường là danh từ không đếm được; trong bối cảnh triết học được dịch là \"chủ nghĩa duy tâm\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paradox', 'en-c1-29', 'paradox', '/ˈpærədɑːks/', 'C1', 'nghịch lý; điều ngược đời nhưng đúng', 'n.', 'paradoxical (adj.), paradoxically (adv.)', NULL, 'Nhấn mạnh vào tình huống có vẻ mâu thuẫn nhưng thực ra lại đúng, không phải là một lỗi sai thông thường.', 'It seems a paradox that resting helps me accomplish more.', NULL, 'Việc nghỉ ngơi lại giúp tôi hoàn thành nhiều việc hơn dường như là một nghịch lý.', '{"wordId":"paradox","ukIpa":"/ˈpærədɒks/","usIpa":"/ˈpærədɑːks/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A statement or situation that seems contradictory but may be true.","vi":"nghịch lý; điều ngược đời nhưng đúng"}],"examples":[{"en":"It seems a paradox that resting helps me accomplish more.","vi":"Việc nghỉ ngơi lại giúp tôi hoàn thành nhiều việc hơn dường như là một nghịch lý.","audioKind":"ex"},{"en":"Modern technology creates a paradox: people can communicate instantly yet still experience deep social isolation.","vi":"Công nghệ hiện đại tạo ra một nghịch lý: con người có thể giao tiếp tức thì nhưng vẫn trải qua sự cô lập xã hội sâu sắc.","audioKind":"ex2"}],"collocations":[{"en":"apparent paradox","vi":"nghịch lý rõ mười mươi"},{"en":"resolve a paradox","vi":"giải quyết một nghịch lý"},{"en":"present a paradox","vi":"đặt ra một nghịch lý"}],"wordFamily":["paradoxical (adj.)","paradoxically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh vào tình huống có vẻ mâu thuẫn nhưng thực ra lại đúng, không phải là một lỗi sai thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discern', 'en-c1-29', 'discern', '/dɪˈsɝːn/', 'C1', 'nhận ra; phân biệt', 'v.', 'discernible (adj.), discernment (n.), discerning (adj.)', 'Đồng nghĩa: detect, perceive, distinguish', 'Từ mang tính trang trọng, nhấn mạnh việc cố gắng nhìn hoặc nhận biết những thứ không dễ phát hiện.', 'Through the fog, I could barely discern the distant bridge.', NULL, 'Xuyên qua lớp sương mù, tôi suýt không nhìn rõ cây cầu ở đằng xa.', '{"wordId":"discern","ukIpa":"/dɪˈsɜːn/","usIpa":"/dɪˈsɝːn/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To notice or recognise something that is difficult to detect.","vi":"nhận ra; phân biệt"}],"examples":[{"en":"Through the fog, I could barely discern the distant bridge.","vi":"Xuyên qua lớp sương mù, tôi suýt không nhìn rõ cây cầu ở đằng xa.","audioKind":"ex"},{"en":"Without reliable evidence, consumers may find it difficult to discern whether environmental claims are genuinely credible.","vi":"Khi thiếu các bằng chứng đáng tin cậy, người tiêu dùng có thể gặp khó khăn trong việc phân định liệu các tuyên bố về môi trường có thực sự đáng tin cậy hay không.","audioKind":"ex2"}],"collocations":[{"en":"discern a pattern","vi":"nhận ra một quy luật"},{"en":"discern a difference","vi":"phân biệt sự khác nhau"},{"en":"barely discern","vi":"nhìn ra mờ ảo"}],"wordFamily":["discernible (adj.)","discernment (n.)","discerning (adj.)"],"synonyms":["detect","perceive","distinguish"],"antonyms":[],"tipVi":"Từ mang tính trang trọng, nhấn mạnh việc cố gắng nhìn hoặc nhận biết những thứ không dễ phát hiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_standpoint', 'en-c1-29', 'standpoint', '/ˈstændpɔɪnt/', 'C1', 'quan điểm; lập trường', 'n.', NULL, 'Đồng nghĩa: perspective, viewpoint', 'Thường dùng cụm from a... standpoint để diễn đạt ý "từ góc độ / quan điểm...".', 'From my standpoint, the smaller flat is more practical.', NULL, 'Theo quan điểm của tôi, căn hộ nhỏ hơn thì thực tế hơn.', '{"wordId":"standpoint","ukIpa":"/ˈstændpɔɪnt/","usIpa":"/ˈstændpɔɪnt/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"a position from which someone considers or judges something","vi":"quan điểm; lập trường"}],"examples":[{"en":"From my standpoint, the smaller flat is more practical.","vi":"Theo quan điểm của tôi, căn hộ nhỏ hơn thì thực tế hơn.","audioKind":"ex"},{"en":"From an environmental standpoint, investing in public transport is preferable to building more roads for private vehicles.","vi":"Từ góc độ môi trường, việc đầu tư vào giao thông công cộng sẽ đáng ưu tiên hơn là xây thêm đường cho xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"from a practical standpoint","vi":"từ góc độ thực tế"},{"en":"from an economic standpoint","vi":"từ góc độ kinh tế"},{"en":"from someone''s standpoint","vi":"từ lập trường của ai đó"}],"wordFamily":[],"synonyms":["perspective","viewpoint"],"antonyms":[],"tipVi":"Thường dùng cụm from a... standpoint để diễn đạt ý \"từ góc độ / quan điểm...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_divergence', 'en-c1-29', 'divergence', '/daɪˈvɝːdʒəns/', 'C1', 'sự khác biệt; sự bất đồng (về quan điểm, phương pháp hoặc xu hướng phát triển); sự phân kỳ; sự rẽ nhánh đi theo các hướng khác nhau từ một điểm chung', 'n.', 'diverge (v.), divergent (adj.)', 'Đồng nghĩa: difference, disparity · Trái nghĩa: convergence', 'Thường dùng giới từ between để nối hai đối tượng có sự khác biệt; động từ tương ứng là diverge.', 'Our discussion revealed a clear divergence in our priorities.', NULL, 'Cuộc thảo luận của chúng tôi cho thấy rõ sự khác biệt trong thứ tự ưu tiên của mỗi bên.', '{"wordId":"divergence","ukIpa":"/daɪˈvɜːdʒəns/","usIpa":"/daɪˈvɝːdʒəns/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A difference between opinions, approaches, or developments.","vi":"sự khác biệt; sự bất đồng (về quan điểm, phương pháp hoặc xu hướng phát triển)"},{"pos":"n.","en":"Movement apart in different directions from a common point.","vi":"sự phân kỳ; sự rẽ nhánh đi theo các hướng khác nhau từ một điểm chung"}],"examples":[{"en":"Our discussion revealed a clear divergence in our priorities.","vi":"Cuộc thảo luận của chúng tôi cho thấy rõ sự khác biệt trong thứ tự ưu tiên của mỗi bên.","audioKind":"ex"},{"en":"The growing divergence between urban and rural incomes may require more targeted regional development policies.","vi":"Khoảng cách thu nhập ngày càng nới rộng giữa thành thị và nông thôn có thể đòi hỏi các chính sách phát triển vùng mang tính định hướng mục tiêu cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"divergence of opinion","vi":"sự bất đồng quan điểm"},{"en":"divergence between","vi":"sự khác biệt giữa"},{"en":"growing divergence","vi":"khoảng cách ngày càng doãng ra"}],"wordFamily":["diverge (v.)","divergent (adj.)"],"synonyms":["difference","disparity"],"antonyms":["convergence"],"tipVi":"Thường dùng giới từ between để nối hai đối tượng có sự khác biệt; động từ tương ứng là diverge.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deliberation', 'en-c1-29', 'deliberation', '/dɪˌlɪbəˈreɪʃən/', 'C1', 'sự cân nhắc kỹ lưỡng; sự thảo luận; sự cẩn trọng; tính từ tốn, chậm rãi', 'n.', 'deliberate (v.), deliberate (adj.), deliberately (adv.)', 'Đồng nghĩa: consideration, reflection', 'Nghĩa thảo luận bàn bạc có thể dùng dạng số nhiều deliberations; không nên dịch cứng nhắc thành sự cố ý.', 'After much deliberation, we chose the smaller apartment.', NULL, 'Sau nhiều lần cân nhắc kỹ lưỡng, chúng tôi đã chọn căn hộ nhỏ hơn.', '{"wordId":"deliberation","ukIpa":"/dɪˌlɪbəˈreɪʃən/","usIpa":"/dɪˌlɪbəˈreɪʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"Careful thought or discussion before making a decision.","vi":"sự cân nhắc kỹ lưỡng; sự thảo luận"},{"pos":"n.","en":"A slow, careful, and intentional way of doing something.","vi":"sự cẩn trọng; tính từ tốn, chậm rãi"}],"examples":[{"en":"After much deliberation, we chose the smaller apartment.","vi":"Sau nhiều lần cân nhắc kỹ lưỡng, chúng tôi đã chọn căn hộ nhỏ hơn.","audioKind":"ex"},{"en":"Decisions about major transport projects require careful deliberation because their effects can last for decades.","vi":"Các quyết định về các dự án giao thông lớn đòi hỏi phải cân nhắc cẩn trọng vì tác động của chúng có thể kéo dài hàng thập kỷ.","audioKind":"ex2"}],"collocations":[{"en":"after much deliberation","vi":"sau khi cân nhắc kỹ lưỡng"},{"en":"careful deliberation","vi":"sự cân nhắc cẩn trọng"},{"en":"with deliberation","vi":"một cách cẩn trọng, từ tốn"}],"wordFamily":["deliberate (v.)","deliberate (adj.)","deliberately (adv.)"],"synonyms":["consideration","reflection"],"antonyms":[],"tipVi":"Nghĩa thảo luận bàn bạc có thể dùng dạng số nhiều deliberations; không nên dịch cứng nhắc thành sự cố ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_characterize', 'en-c1-29', 'characterize', '/ˈkærəktəraɪz/', 'C1', 'là đặc điểm của; tiêu biểu cho; miêu tả đặc điểm', 'v.', 'character (n.), characteristic (adj.), characterization (n.)', 'Đồng nghĩa: distinguish, describe', 'Tiếng Anh-Anh cũng viết là characterise; thể bị động thường đi với by.', 'Bright colours and bold patterns characterize her handmade bags.', NULL, 'Màu sắc tươi sáng và họa tiết táo bạo là đặc điểm nổi bật của những chiếc túi handmade của cô ấy.', '{"wordId":"characterize","ukIpa":"/ˈkærəktəraɪz/","usIpa":"/ˈkærəktəraɪz/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To be a typical or distinguishing feature of something.","vi":"là đặc điểm của; tiêu biểu cho"},{"pos":"v.","en":"To describe the main qualities of someone or something.","vi":"miêu tả đặc điểm"}],"examples":[{"en":"Bright colours and bold patterns characterize her handmade bags.","vi":"Màu sắc tươi sáng và họa tiết táo bạo là đặc điểm nổi bật của những chiếc túi handmade của cô ấy.","audioKind":"ex"},{"en":"High housing costs and limited public space characterize many large cities, affecting residents'' quality of life.","vi":"Chi phí nhà ở cao và không gian công cộng hạn chế là đặc điểm của nhiều thành phố lớn, ảnh hưởng đến chất lượng cuộc sống của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"be characterized by","vi":"được đặc trưng bởi"},{"en":"characterize something as","vi":"mô tả cái gì là"}],"wordFamily":["character (n.)","characteristic (adj.)","characterization (n.)"],"synonyms":["distinguish","describe"],"antonyms":[],"tipVi":"Tiếng Anh-Anh cũng viết là characterise; thể bị động thường đi với by.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recollect', 'en-c1-29', 'recollect', '/ˌrekəˈlekt/', 'C1', 'hồi tưởng; nhớ lại', 'v.', 'recollection (n.)', 'Đồng nghĩa: remember, recall · Trái nghĩa: forget', 'Trang trọng hơn remember; dùng recollect doing, không dùng to do.', 'I clearly recollect meeting her outside the village bakery.', NULL, 'Tôi nhớ rất rõ là đã gặp cô ấy ở bên ngoài tiệm bánh mì của làng.', '{"wordId":"recollect","ukIpa":"/ˌrekəˈlekt/","usIpa":"/ˌrekəˈlekt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"remember something from the past, sometimes with effort","vi":"hồi tưởng; nhớ lại"}],"examples":[{"en":"I clearly recollect meeting her outside the village bakery.","vi":"Tôi nhớ rất rõ là đã gặp cô ấy ở bên ngoài tiệm bánh mì của làng.","audioKind":"ex"},{"en":"Older residents often recollect a time when public spaces played a greater role in community life.","vi":"Những cư dân lớn tuổi thường hồi tưởng lại thời điểm mà các không gian công cộng đóng vai trò lớn hơn trong đời sống cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"clearly recollect","vi":"nhớ rõ"},{"en":"recollect doing something","vi":"nhớ lại việc làm gì"},{"en":"as far as I recollect","vi":"theo như tôi nhớ"}],"wordFamily":["recollection (n.)"],"synonyms":["remember","recall"],"antonyms":["forget"],"tipVi":"Trang trọng hơn remember; dùng recollect doing, không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cynical', 'en-c1-29', 'cynical', '/ˈsɪnɪkəl/', 'C1', 'hoài nghi (động cơ của người khác); yếm thế; ích kỷ, bất chấp đạo lý (lợi dụng người khác)', 'adj.', 'cynic (n.), cynicism (n.), cynically (adv.)', 'Trái nghĩa: idealistic, trusting', 'Thường đi kèm với "about", nhấn mạnh sự hoài nghi về lòng tốt, không đơn thuần là bi quan.', 'Leah is cynical about shops offering supposedly free gifts.', NULL, 'Leah hoài nghi về những cửa hàng quảng cáo tặng quà miễn phí.', '{"wordId":"cynical","ukIpa":"/ˈsɪnɪkəl/","usIpa":"/ˈsɪnɪkəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"believing people act selfishly rather than honestly or generously","vi":"hoài nghi (động cơ của người khác); yếm thế"},{"pos":"adj.","en":"using others selfishly without concern for fairness or honesty","vi":"ích kỷ, bất chấp đạo lý (lợi dụng người khác)"}],"examples":[{"en":"Leah is cynical about shops offering supposedly free gifts.","vi":"Leah hoài nghi về những cửa hàng quảng cáo tặng quà miễn phí.","audioKind":"ex"},{"en":"Repeatedly broken promises can make citizens cynical about whether political leaders genuinely intend to improve public services.","vi":"Việc liên tục thất hứa có thể khiến người dân hoài nghi liệu các nhà lãnh đạo chính trị có thực sự muốn cải thiện dịch vụ công hay không.","audioKind":"ex2"}],"collocations":[{"en":"cynical about","vi":"hoài nghi về"},{"en":"a cynical attitude","vi":"thái độ yếm thế"},{"en":"a cynical attempt","vi":"nỗ lực bất chấp đạo lý"}],"wordFamily":["cynic (n.)","cynicism (n.)","cynically (adv.)"],"synonyms":[],"antonyms":["idealistic","trusting"],"tipVi":"Thường đi kèm với \"about\", nhấn mạnh sự hoài nghi về lòng tốt, không đơn thuần là bi quan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_explicit', 'en-c1-29', 'explicit', '/ɪkˈsplɪsɪt/', 'C1', 'rõ ràng; tường minh; dứt khoát', 'adj.', 'explicitly (adv.), explicitness (n.)', 'Đồng nghĩa: clear, unambiguous, unequivocal · Trái nghĩa: implicit, vague', 'Explicit chỉ điều được diễn đạt rạch ròi; trái ngược với implicit ngầm hiểu.', 'Please give me explicit instructions for assembling this wooden shelf.', NULL, 'Xin hãy cho tôi hướng dẫn rõ ràng để lắp ráp chiếc kệ gỗ này.', '{"wordId":"explicit","ukIpa":"/ɪkˈsplɪsɪt/","usIpa":"/ɪkˈsplɪsɪt/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"expressed clearly and directly, leaving no doubt about the meaning","vi":"rõ ràng; tường minh; dứt khoát"}],"examples":[{"en":"Please give me explicit instructions for assembling this wooden shelf.","vi":"Xin hãy cho tôi hướng dẫn rõ ràng để lắp ráp chiếc kệ gỗ này.","audioKind":"ex"},{"en":"Schools should establish explicit rules about online behaviour to help students use digital platforms responsibly.","vi":"Các trường học nên thiết lập các quy tắc rõ ràng về hành vi ứng xử trên mạng để giúp học sinh sử dụng nền tảng số một cách có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"explicit instructions","vi":"chỉ dẫn rõ ràng"},{"en":"explicit consent","vi":"sự đồng thuận rõ ràng"},{"en":"explicit reference","vi":"sự nhắc đến tường minh"},{"en":"make explicit","vi":"làm cho rõ ràng"}],"wordFamily":["explicitly (adv.)","explicitness (n.)"],"synonyms":["clear","unambiguous","unequivocal"],"antonyms":["implicit","vague"],"tipVi":"Explicit chỉ điều được diễn đạt rạch ròi; trái ngược với implicit ngầm hiểu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unthinkable', 'en-c1-29', 'unthinkable', '/ʌnˈθɪŋkəbl/', 'C1', 'không thể tưởng tượng nổi; không thể chấp nhận được', 'adj.', 'think (v.), thinkable (adj.), unthinkably (adv.)', 'Đồng nghĩa: unimaginable, inconceivable · Trái nghĩa: conceivable, thinkable', 'Mang sắc thái mạnh hơn unlikely, thường hàm ý "hoàn toàn không thể chấp nhận được".', 'Leaving our dog behind during the move was unthinkable.', NULL, 'Việc bỏ lại chú chó của chúng tôi trong lúc chuyển nhà là điều không thể tưởng tượng nổi.', '{"wordId":"unthinkable","ukIpa":"/ʌnˈθɪŋkəbl/","usIpa":"/ʌnˈθɪŋkəbl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"too unlikely or unacceptable to imagine or consider seriously","vi":"không thể tưởng tượng nổi; không thể chấp nhận được"}],"examples":[{"en":"Leaving our dog behind during the move was unthinkable.","vi":"Việc bỏ lại chú chó của chúng tôi trong lúc chuyển nhà là điều không thể tưởng tượng nổi.","audioKind":"ex"},{"en":"For many communities, closing the only local hospital would be unthinkable because residents depend on its services.","vi":"Đối với nhiều cộng đồng, việc đóng cửa bệnh viện địa phương duy nhất là điều không thể chấp nhận vì cư dân phụ thuộc vào các dịch vụ của nơi này.","audioKind":"ex2"}],"collocations":[{"en":"an unthinkable idea","vi":"một ý tưởng không thể tưởng tượng nổi"},{"en":"previously unthinkable","vi":"chưa từng có trước đây; trước đây không thể tưởng tượng"},{"en":"unthinkable consequences","vi":"hậu quả khôn lường"}],"wordFamily":["think (v.)","thinkable (adj.)","unthinkably (adv.)"],"synonyms":["unimaginable","inconceivable"],"antonyms":["conceivable","thinkable"],"tipVi":"Mang sắc thái mạnh hơn unlikely, thường hàm ý \"hoàn toàn không thể chấp nhận được\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_29_1', 'en-c1-29', 'Cách dùng “domain” (n.) — lĩnh vực; phạm vi', 'the domain of science  ·  public domain  ·  domain name', 'Lĩnh vực có nét nghĩa gần với field; cụm từ in the public domain có nghĩa là thuộc về công chúng, ai cũng có thể sử dụng.', 'Đồng nghĩa: field, sphere, territory', '[{"hanzi":"Electrical repairs are my brother''s domain, not mine.","pinyin":"","meaning":"Sửa chữa điện đóm là sở trường của anh trai tôi chứ không phải của tôi."},{"hanzi":"Environmental protection should not be regarded as the exclusive domain of scientists, since public participation is essential.","pinyin":"","meaning":"Bảo vệ môi trường không nên được coi là lĩnh vực độc quyền của các nhà khoa học, vì sự tham gia của công chúng là vô cùng quan trọng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_29_2', 'en-c1-29', 'Cách dùng “enumerate” (v.) — liệt kê; kể ra; nêu rõ từng mục', 'enumerate the reasons  ·  enumerate the benefits  ·  enumerate the main points', 'Là từ mang tính trang trọng, nhấn mạnh việc liệt kê từng mục một; trong giao tiếp hàng ngày thường dùng list.', 'Họ từ (Word Family): enumeration (n.), enumerator (n.) | Đồng nghĩa: list, itemise', '[{"hanzi":"She enumerated the repairs needed before we could move in.","pinyin":"","meaning":"Cô ấy đã liệt kê các mục cần sửa chữa trước khi chúng tôi có thể chuyển vào ở."},{"hanzi":"The report enumerates several barriers to higher education, including tuition costs and limited access to reliable transport.","pinyin":"","meaning":"Báo cáo này liệt kê một số rào cản đối với giáo dục đại học, bao gồm chi phí học phí và khả năng tiếp cận phương tiện giao thông đáng tin cậy còn hạn chế."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_29_3', 'en-c1-29', 'Cách dùng “conceivable” (adj.) — có thể tưởng tượng được; có thể hiểu được', 'every conceivable way  ·  every conceivable option  ·  it is conceivable that', 'Biểu thị khả năng có thể hình dung hoặc có thể xảy ra, không đồng nghĩa với việc rất có khả năng xảy ra.', 'Họ từ (Word Family): conceive (v.), conceivably (adv.), inconceivable (adj.) | Đồng nghĩa: imaginable, possible · Trái nghĩa: inconceivable, unimaginable', '[{"hanzi":"We searched every conceivable place for the missing keys.","pinyin":"","meaning":"Chúng tôi đã lục tung mọi ngóc ngách có thể nghĩ ra để tìm những chiếc chìa khóa bị mất."},{"hanzi":"It is conceivable that advances in renewable energy could significantly reduce global dependence on fossil fuels.","pinyin":"","meaning":"Có thể hình dung rằng những tiến bộ trong năng lượng tái tạo sẽ làm giảm đáng kể sự phụ thuộc của toàn cầu vào nhiên liệu hóa thạch."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_29_4', 'en-c1-29', 'Cách dùng “paradox” (n.) — nghịch lý; điều ngược đời nhưng đúng', 'apparent paradox  ·  resolve a paradox  ·  present a paradox', 'Nhấn mạnh vào tình huống có vẻ mâu thuẫn nhưng thực ra lại đúng, không phải là một lỗi sai thông thường.', 'Họ từ (Word Family): paradoxical (adj.), paradoxically (adv.)', '[{"hanzi":"It seems a paradox that resting helps me accomplish more.","pinyin":"","meaning":"Việc nghỉ ngơi lại giúp tôi hoàn thành nhiều việc hơn dường như là một nghịch lý."},{"hanzi":"Modern technology creates a paradox: people can communicate instantly yet still experience deep social isolation.","pinyin":"","meaning":"Công nghệ hiện đại tạo ra một nghịch lý: con người có thể giao tiếp tức thì nhưng vẫn trải qua sự cô lập xã hội sâu sắc."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_29_1', 'en-c1-29', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_1_1', 'ten_c1_29_1', 'conceivable', 'We searched every conceivable place for the missing keys.', 'We searched every conceivable place for the missing keys.', '/kənˈsiːvəbl/', 'Chúng tôi đã lục tung mọi ngóc ngách có thể nghĩ ra để tìm những chiếc chìa khóa bị mất.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_1_2', 'ten_c1_29_1', 'analogy', 'Her analogy compared our busy kitchen to a train station.', 'Her analogy compared our busy kitchen to a train station.', '/əˈnælədʒi/', 'Cô ấy đã ví nhà bếp bận rộn của chúng tôi như một nhà ga xe lửa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_1_3', 'ten_c1_29_1', 'attributable', 'The damp patch is attributable to a leaking pipe.', 'The damp patch is attributable to a leaking pipe.', '/əˈtrɪbjətəbl/', 'Vết ẩm mốc đó là do ống nước bị rò rỉ gây ra.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_1_4', 'ten_c1_29_1', 'formulate', 'We need to formulate a plan before moving house.', 'We need to formulate a plan before moving house.', '/ˈfɔːrmjəleɪt/', 'Chúng ta cần lên kế hoạch trước khi chuyển nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_1_5', 'ten_c1_29_1', 'verify', 'Please verify your address before we send the parcel.', 'Please verify your address before we send the parcel.', '/ˈverɪfaɪ/', 'Vui lòng xác minh địa chỉ của bạn trước khi chúng tôi gửi bưu kiện.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_1_6', 'ten_c1_29_1', 'enumerate', 'She enumerated the repairs needed before we could move in.', 'She enumerated the repairs needed before we could move in.', '/ɪˈnuːməreɪt/', 'Cô ấy đã liệt kê các mục cần sửa chữa trước khi chúng tôi có thể chuyển vào ở.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_1_7', 'ten_c1_29_1', 'lapse', 'A brief lapse in concentration made me miss my stop.', 'A brief lapse in concentration made me miss my stop.', '/læps/', 'Một phút mất tập trung chớp nhoáng đã khiến tôi đi quá trạm dừng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_1_8', 'ten_c1_29_1', 'ascribe', 'I ascribe my better sleep to regular evening walks.', 'I ascribe my better sleep to regular evening walks.', '/əˈskraɪb/', 'Tôi cho rằng việc giấc ngủ của mình tốt hơn là nhờ thói quen đi dạo đều đặn vào buổi tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_29_1_1', 'en-c1-29', 'ten_c1_29_1', 'listening', 'listening', 'We searched every conceivable place for the missing keys.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cuộc thảo luận của chúng tôi cho thấy rõ sự khác biệt trong thứ tự ưu tiên của mỗi bên.","Một phút mất tập trung chớp nhoáng đã khiến tôi đi quá trạm dừng.","Tôi cho rằng việc giấc ngủ của mình tốt hơn là nhờ thói quen đi dạo đều đặn vào buổi tối.","Chúng tôi đã lục tung mọi ngóc ngách có thể nghĩ ra để tìm những chiếc chìa khóa bị mất."]'::jsonb, 3, 'We searched every conceivable place for the missing keys. → Chúng tôi đã lục tung mọi ngóc ngách có thể nghĩ ra để tìm những chiếc chìa khóa bị mất.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_29_1_2', 'en-c1-29', 'ten_c1_29_1', 'listening', 'listening', 'Her analogy compared our busy kitchen to a train station.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ngân sách của tôi chỉ là một ước tính sơ lược về chi phí.","Vết ẩm mốc đó là do ống nước bị rò rỉ gây ra.","Thợ máy đã tìm ra nguyên nhân sâu xa gây ra tiếng ồn.","Cô ấy đã ví nhà bếp bận rộn của chúng tôi như một nhà ga xe lửa."]'::jsonb, 3, 'Her analogy compared our busy kitchen to a train station. → Cô ấy đã ví nhà bếp bận rộn của chúng tôi như một nhà ga xe lửa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_29_1_3', 'en-c1-29', 'ten_c1_29_1', 'listening', 'listening', 'The damp patch is attributable to a leaking pipe.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn có thể đọc được chữ viết tay trên tấm bưu điện cũ này không?","Việc nghỉ ngơi lại giúp tôi hoàn thành nhiều việc hơn dường như là một nghịch lý.","Cuộc thảo luận của chúng tôi cho thấy rõ sự khác biệt trong thứ tự ưu tiên của mỗi bên.","Vết ẩm mốc đó là do ống nước bị rò rỉ gây ra."]'::jsonb, 3, 'The damp patch is attributable to a leaking pipe. → Vết ẩm mốc đó là do ống nước bị rò rỉ gây ra.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_29_2', 'en-c1-29', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_2_1', 'ten_c1_29_2', 'conceivable', 'It is conceivable that advances in renewable energy could significantly reduce global dependence on fossil fuels.', 'It is conceivable that advances in renewable energy could significantly reduce global dependence on fossil fuels.', '/kənˈsiːvəbl/', 'Có thể hình dung rằng những tiến bộ trong năng lượng tái tạo sẽ làm giảm đáng kể sự phụ thuộc của toàn cầu vào nhiên liệu hóa thạch.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_2_2', 'ten_c1_29_2', 'analogy', 'Teachers often draw an analogy between electrical circuits and flowing water to explain unfamiliar scientific concepts.', 'Teachers often draw an analogy between electrical circuits and flowing water to explain unfamiliar scientific concepts.', '/əˈnælədʒi/', 'Giáo viên thường dùng phép so sánh giữa mạch điện và dòng nước chảy để giải thích các khái niệm khoa học xa lạ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_2_3', 'ten_c1_29_2', 'attributable', 'Much of the improvement in public health is attributable to cleaner drinking water and better sanitation.', 'Much of the improvement in public health is attributable to cleaner drinking water and better sanitation.', '/əˈtrɪbjətəbl/', 'Phần lớn sự cải thiện về sức khỏe cộng đồng là nhờ vào nguồn nước uống sạch hơn và hệ thống vệ sinh tốt hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_2_4', 'ten_c1_29_2', 'formulate', 'Governments should formulate transport policies that reduce congestion while ensuring affordable access for all residents.', 'Governments should formulate transport policies that reduce congestion while ensuring affordable access for all residents.', '/ˈfɔːrmjəleɪt/', 'Chính phủ nên hoạch định các chính sách giao thông nhằm giảm thiểu tình trạng ùn tắc đồng thời đảm bảo khả năng chi trả cho tất cả người dân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_2_5', 'ten_c1_29_2', 'verify', 'Researchers must verify their findings through repeated experiments before presenting them to the wider scientific community.', 'Researchers must verify their findings through repeated experiments before presenting them to the wider scientific community.', '/ˈverɪfaɪ/', 'Các nhà nghiên cứu phải xác minh các phát hiện của họ thông qua các thí nghiệm lặp lại trước khi trình bày chúng trước cộng đồng khoa học rộng lớn hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_29_2_6', 'ten_c1_29_2', 'enumerate', 'The report enumerates several barriers to higher education, including tuition costs and limited access to reliable transport.', 'The report enumerates several barriers to higher education, including tuition costs and limited access to reliable transport.', '/ɪˈnuːməreɪt/', 'Báo cáo này liệt kê một số rào cản đối với giáo dục đại học, bao gồm chi phí học phí và khả năng tiếp cận phương tiện giao thông đáng tin cậy còn hạn chế.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_29_2_1', 'en-c1-29', 'ten_c1_29_2', 'listening', 'listening', 'It is conceivable that advances in renewable energy could significantly reduce global dependence on fossil fuels.', NULL, 'Trong câu vừa nghe, từ “conceivable” mang nghĩa nào sau đây?', '["bản chất; nội tại; vốn có","tính tiết kiệm; sự chi tiêu tằn tiện","phòng chứa thức ăn; tủ đựng thực phẩm","có thể tưởng tượng được; có thể hiểu được"]'::jsonb, 3, '“conceivable” (/kənˈsiːvəbl/): có thể tưởng tượng được; có thể hiểu được. Câu đầy đủ: It is conceivable that advances in renewable energy could significantly reduce global dependence on fossil fuels.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_29_2_2', 'en-c1-29', 'ten_c1_29_2', 'listening', 'listening', 'Teachers often draw an analogy between electrical circuits and flowing water to explain unfamiliar scientific concepts.', NULL, 'Trong câu vừa nghe, từ “analogy” mang nghĩa nào sau đây?', '["phép loại suy; sự so sánh tương đương","sự không ⿓i lòng; sự miễn cưỡng","sự tương đương; tính tương đương","thuộc về nguyên thủy; bản địa; thổ dân"]'::jsonb, 0, '“analogy” (/əˈnælədʒi/): phép loại suy; sự so sánh tương đương. Câu đầy đủ: Teachers often draw an analogy between electrical circuits and flowing water to explain unfamiliar scientific concepts.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
