INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_2', 'en-c1-29', NULL, 'comprehensive_test', 'listening', 'Her analogy compared our busy kitchen to a train station.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đã ví nhà bếp bận rộn của chúng tôi như một nhà ga xe lửa.","Chúng tôi đã xoay sở nhét vừa vặn từng chiếc va-li vào chiếc xe ô tô chật chội.","Sửa chữa điện đóm là sở trường của anh trai tôi chứ không phải của tôi.","Bạn có thể đọc được chữ viết tay trên tấm bưu điện cũ này không?"]'::jsonb, 0, 'Her analogy compared our busy kitchen to a train station. → Cô ấy đã ví nhà bếp bận rộn của chúng tôi như một nhà ga xe lửa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_3', 'en-c1-29', NULL, 'comprehensive_test', 'listening', 'attributable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cuốn; xoáy tròn; làm xoáy","sự bảo dưỡng; việc duy trì; chi phí bảo trì","có thể quy cho; do... gây ra","làm mất nhà cửa; buộc phải rời khỏi nơi ở"]'::jsonb, 2, 'attributable (/əˈtrɪbjətəbl/) → có thể quy cho; do... gây ra', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_4', 'en-c1-29', NULL, 'comprehensive_test', 'listening', 'We need to formulate a plan before moving house.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng ta cần lên kế hoạch trước khi chuyển nhà.","Việc bỏ lại chú chó của chúng tôi trong lúc chuyển nhà là điều không thể tưởng tượng nổi.","Tôi nhớ rất rõ là đã gặp cô ấy ở bên ngoài tiệm bánh mì của làng.","Chúng tôi đã xoay sở nhét vừa vặn từng chiếc va-li vào chiếc xe ô tô chật chội."]'::jsonb, 0, 'We need to formulate a plan before moving house. → Chúng ta cần lên kế hoạch trước khi chuyển nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_5', 'en-c1-29', NULL, 'comprehensive_test', 'listening', 'verify', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xác minh; kiểm chứng; tra lại cho chính xác","làm điếc tai; làm ù tai; làm chói tai","người kế nhiệm; người tiếp quản","hẻo lánh; tách biệt; thanh vắng"]'::jsonb, 0, 'verify (/ˈverɪfaɪ/) → xác minh; kiểm chứng; tra lại cho chính xác', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_6', 'en-c1-29', NULL, 'comprehensive_test', 'listening', 'She enumerated the repairs needed before we could move in.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trí tuệ sắc bén của cô ấy khiến những câu đố hóc búa trở nên dễ dàng đến ngạc nhiên.","Cô ấy đã liệt kê các mục cần sửa chữa trước khi chúng tôi có thể chuyển vào ở.","Bạn có thể đọc được chữ viết tay trên tấm bưu điện cũ này không?","Sau nhiều lần cân nhắc kỹ lưỡng, chúng tôi đã chọn căn hộ nhỏ hơn."]'::jsonb, 1, 'She enumerated the repairs needed before we could move in. → Cô ấy đã liệt kê các mục cần sửa chữa trước khi chúng tôi có thể chuyển vào ở.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_7', 'en-c1-29', NULL, 'comprehensive_test', 'listening', 'lapse', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quân tốt (trong cờ vua)","sự lơ đễnh; sai sót nhỏ","làm tăng lên; gia tăng; mở rộng","khả năng thanh toán nợ"]'::jsonb, 1, 'lapse (/læps/) → sự lơ đễnh; sai sót nhỏ; khoảng thời gian; hết hạn; mất hiệu lực', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_8', 'en-c1-29', NULL, 'comprehensive_test', 'listening', 'I ascribe my better sleep to regular evening walks.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vui lòng xác minh địa chỉ của bạn trước khi chúng tôi gửi bưu kiện.","Bạn có thể đọc được chữ viết tay trên tấm bưu điện cũ này không?","Ngân sách của tôi chỉ là một ước tính sơ lược về chi phí.","Tôi cho rằng việc giấc ngủ của mình tốt hơn là nhờ thói quen đi dạo đều đặn vào buổi tối."]'::jsonb, 3, 'I ascribe my better sleep to regular evening walks. → Tôi cho rằng việc giấc ngủ của mình tốt hơn là nhờ thói quen đi dạo đều đặn vào buổi tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_9', 'en-c1-29', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to check that something is true, accurate, or genuine”?', '["cynical","verify","standpoint","characterize"]'::jsonb, 1, 'verify (/ˈverɪfaɪ/) → xác minh; kiểm chứng; tra lại cho chính xác', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_10', 'en-c1-29', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To name things separately, one after another.”?', '["explicit","contrive","recollect","enumerate"]'::jsonb, 3, 'enumerate (/ɪˈnuːməreɪt/) → liệt kê; kể ra; nêu rõ từng mục', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_11', 'en-c1-29', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a brief failure of attention, judgment, or memory”?', '["formulate","lapse","attributable","enumerate"]'::jsonb, 1, 'lapse (/læps/) → sự lơ đễnh; sai sót nhỏ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_12', 'en-c1-29', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To consider something to be caused by a particular factor”?', '["unthinkable","cynical","formulate","ascribe"]'::jsonb, 3, 'ascribe (/əˈskraɪb/) → quy cho; quy nguyên nhân', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_13', 'en-c1-29', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to manage to do something difficult or unexpected”?', '["conceivable","ascribe","explicit","contrive"]'::jsonb, 3, 'contrive (/kənˈtraɪv/) → xoay sở, tìm cách làm được việc gì khó khăn hoặc bất ngờ', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
