INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_18', 'en-c1-29', NULL, 'comprehensive_test', 'reading', NULL, 'It is conceivable that advances in renewable energy could significantly reduce global dependence on fossil fuels.', 'Dựa vào câu trên, từ “conceivable” có nghĩa phù hợp nhất là gì?', '["có thể chuyển nhượng; có thể chuyển giao","hội nghị chuyên đề; hội thảo","có thể tưởng tượng được; có thể hiểu được","kín đáo; ít nói; không muốn bộc lộ"]'::jsonb, 2, 'conceivable: có thể tưởng tượng được; có thể hiểu được. Dịch cả câu: Có thể hình dung rằng những tiến bộ trong năng lượng tái tạo sẽ làm giảm đáng kể sự phụ thuộc của toàn cầu vào nhiên liệu hóa thạch.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_19', 'en-c1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Teachers often draw an analogy between electrical circuits and flowing water to explain unfamiliar scientific concepts.', 'Dựa vào câu trên, từ “analogy” có nghĩa phù hợp nhất là gì?', '["tay nghề; chất lượng gia công","chủ nghĩa bảo hộ mậu dịch; chính sách bảo hộ","thờ ơ; lạnh nhạt","phép loại suy; sự so sánh tương đương"]'::jsonb, 3, 'analogy: phép loại suy; sự so sánh tương đương. Dịch cả câu: Giáo viên thường dùng phép so sánh giữa mạch điện và dòng nước chảy để giải thích các khái niệm khoa học xa lạ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_20', 'en-c1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Much of the improvement in public health is attributable to cleaner drinking water and better sanitation.', 'Dựa vào câu trên, từ “attributable” có nghĩa phù hợp nhất là gì?', '["có thể quy cho; do... gây ra","giải phẫu học","nhấp nháy; lấp lánh","chính khách lão luyện; nhà lãnh đạo chính trị có tầm nhìn"]'::jsonb, 0, 'attributable: có thể quy cho; do... gây ra. Dịch cả câu: Phần lớn sự cải thiện về sức khỏe cộng đồng là nhờ vào nguồn nước uống sạch hơn và hệ thống vệ sinh tốt hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_21', 'en-c1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should formulate transport policies that reduce congestion while ensuring affordable access for all residents.', 'Dựa vào câu trên, từ “formulate” có nghĩa phù hợp nhất là gì?', '["dấu ấn; nét đặc trưng; đặc điểm tiêu biểu","xây dựng; hoạch định","làm xa lánh; khiến ai đó không muốn ủng hộ","nịnh hót; nịnh bợ (ca ngợi ai đó, thường là không thành thật, để lấy lòng)"]'::jsonb, 1, 'formulate: xây dựng; hoạch định; phát biểu rõ ràng; diễn đạt chính xác. Dịch cả câu: Chính phủ nên hoạch định các chính sách giao thông nhằm giảm thiểu tình trạng ùn tắc đồng thời đảm bảo khả năng chi trả cho tất cả người dân.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_22', 'en-c1-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hoài nghi (động cơ của người khác); yếm thế”', '["cynical","inattention","absurdity","depict"]'::jsonb, 0, 'hoài nghi (động cơ của người khác); yếm thế → cynical (/ˈsɪnɪkəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_23', 'en-c1-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “rõ ràng; tường minh; dứt khoát”', '["explicit","phony","consecutive","empower"]'::jsonb, 0, 'rõ ràng; tường minh; dứt khoát → explicit (/ɪkˈsplɪsɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_29_24', 'en-c1-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “không thể tưởng tượng nổi; không thể chấp nhận được”', '["metallic","civic","unthinkable","quirk"]'::jsonb, 2, 'không thể tưởng tượng nổi; không thể chấp nhận được → unthinkable (/ʌnˈθɪŋkəbl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-30', 'en', 'Bài 30: Tư duy & Nhận thức (5) - CEFR C1', 'CEFR C1', 'C1 · Tư duy', '25 từ vựng Tiếng Anh CEFR C1 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5030, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_viable', 'en-c1-30', 'viable', '/ˈvaɪəbl/', 'C1', 'thực thi được; khả thi; có thể sống được; phát triển được', 'adj.', 'viability (n.)', 'Đồng nghĩa: feasible, workable · Trái nghĩa: unviable, impractical', 'Chủ yếu chỉ phương án khả thi; trong sinh học chỉ khả năng sống hoặc phát triển.', 'Sharing a flat seems like a viable option.', NULL, 'Thuê chung một căn hộ có vẻ là một lựa chọn khả thi.', '{"wordId":"viable","ukIpa":"/ˈvaɪəbl/","usIpa":"/ˈvaɪəbl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Able to work successfully in practice.","vi":"thực thi được; khả thi"},{"pos":"adj.","en":"Able to survive or develop into a living organism.","vi":"có thể sống được; phát triển được"}],"examples":[{"en":"Sharing a flat seems like a viable option.","vi":"Thuê chung một căn hộ có vẻ là một lựa chọn khả thi.","audioKind":"ex"},{"en":"Public transport must be affordable and reliable to become a viable alternative to private cars.","vi":"Giao thông công cộng phải có giá cả phải chăng và đáng tin cậy để có thể trở thành sự thay thế khả thi cho xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"viable option","vi":"lựa chọn khả thi"},{"en":"economically viable","vi":"khả thi về mặt kinh tế"},{"en":"viable solution","vi":"giải pháp khả thi"},{"en":"viable seeds","vi":"hạt giống có khả năng nảy mầm"}],"wordFamily":["viability (n.)"],"synonyms":["feasible","workable"],"antonyms":["unviable","impractical"],"tipVi":"Chủ yếu chỉ phương án khả thi; trong sinh học chỉ khả năng sống hoặc phát triển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tentative', 'en-c1-30', 'tentative', '/ˈtentətɪv/', 'C1', 'tạm thời; chưa chính thức; dè dặt; mang tính thử nghiệm; do dự', 'adj.', 'tentatively (adv.), tentativeness (n.)', 'Đồng nghĩa: provisional, uncertain · Trái nghĩa: definite, confirmed', 'Có thể dùng để chỉ kế hoạch mang tính "tạm thời" hoặc hành động mang tính "thử nghiệm, dè dặt".', 'We made tentative plans to visit the coast next weekend.', NULL, 'Chúng tôi đã lên kế hoạch tạm thời sẽ đi chơi biển vào cuối tuần tới.', '{"wordId":"tentative","ukIpa":"/ˈtentətɪv/","usIpa":"/ˈtentətɪv/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Not yet definite and possibly subject to change.","vi":"tạm thời; chưa chính thức"},{"pos":"adj.","en":"Showing uncertainty or a lack of confidence.","vi":"dè dặt; mang tính thử nghiệm; do dự"}],"examples":[{"en":"We made tentative plans to visit the coast next weekend.","vi":"Chúng tôi đã lên kế hoạch tạm thời sẽ đi chơi biển vào cuối tuần tới.","audioKind":"ex"},{"en":"Researchers have drawn tentative conclusions, but further studies are needed before the treatment can be widely recommended.","vi":"Các nhà nghiên cứu đã đưa ra những kết luận ban đầu, nhưng cần phải có thêm nhiều nghiên cứu trước khi phương pháp điều trị này có thể được khuyến khích rộng rãi.","audioKind":"ex2"}],"collocations":[{"en":"tentative plans","vi":"kế hoạch tạm thời"},{"en":"a tentative conclusion","vi":"kết luận ban đầu"},{"en":"a tentative agreement","vi":"thỏa thuận sơ bộ"},{"en":"a tentative smile","vi":"nụ cười dè dặt"}],"wordFamily":["tentatively (adv.)","tentativeness (n.)"],"synonyms":["provisional","uncertain"],"antonyms":["definite","confirmed"],"tipVi":"Có thể dùng để chỉ kế hoạch mang tính \"tạm thời\" hoặc hành động mang tính \"thử nghiệm, dè dặt\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nuance', 'en-c1-30', 'nuance', '/ˈnuːɑːns/', 'C1', 'sắc thái; điểm tinh tế (trong ý nghĩa, cảm xúc, âm thanh hoặc diện mạo)', 'n.', 'nuanced (adj.)', 'Đồng nghĩa: subtlety', 'Thường dùng ở dạng số nhiều nuances, chỉ những nét tinh tế trong ý nghĩa hoặc giọng điệu.', 'Her smile added a playful nuance to the apology.', NULL, 'Nụ cười của cô ấy mang lại một chút sắc thái tinh nghịch cho lời xin lỗi.', '{"wordId":"nuance","ukIpa":"/ˈnjuːɑːns/","usIpa":"/ˈnuːɑːns/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"a small difference in meaning, feeling, sound, or appearance","vi":"sắc thái; điểm tinh tế (trong ý nghĩa, cảm xúc, âm thanh hoặc diện mạo)"}],"examples":[{"en":"Her smile added a playful nuance to the apology.","vi":"Nụ cười của cô ấy mang lại một chút sắc thái tinh nghịch cho lời xin lỗi.","audioKind":"ex"},{"en":"Language learners need cultural knowledge to recognise nuances that dictionaries may not fully explain.","vi":"Người học ngoại ngữ cần có kiến thức văn hóa để nhận biết những sắc thái tinh tế mà từ điển có thể không giải thích hết được.","audioKind":"ex2"}],"collocations":[{"en":"subtle nuance","vi":"sắc thái tế nhị"},{"en":"nuances of meaning","vi":"sắc thái ý nghĩa"},{"en":"capture the nuances","vi":"nắm bắt các sắc thái"}],"wordFamily":["nuanced (adj.)"],"synonyms":["subtlety"],"antonyms":[],"tipVi":"Thường dùng ở dạng số nhiều nuances, chỉ những nét tinh tế trong ý nghĩa hoặc giọng điệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_daze', 'en-c1-30', 'daze', '/deɪz/', 'C1', 'làm choáng váng; làm mơ màng; trạng thái bần thần; trạng thái mơ màng', 'v.', 'dazed (adj.)', 'Đồng nghĩa: stun, bewilder', 'in a daze chỉ trạng thái bần thần; để chỉ ánh sáng chói lóa thông thường dùng dazzle.', 'The sudden crash dazed me for a moment.', NULL, 'Cú va chạm bất ngờ khiến tôi choáng váng trong giây lát.', '{"wordId":"daze","ukIpa":"/deɪz/","usIpa":"/deɪz/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To leave someone confused and unable to think clearly.","vi":"làm choáng váng; làm mơ màng"},{"pos":"n.","en":"A state of confusion or reduced awareness.","vi":"trạng thái bần thần; trạng thái mơ màng"}],"examples":[{"en":"The sudden crash dazed me for a moment.","vi":"Cú va chạm bất ngờ khiến tôi choáng váng trong giây lát.","audioKind":"ex"},{"en":"After several nights of poor sleep, employees may work in a daze and make avoidable mistakes.","vi":"Sau vài đêm ngủ không đủ giấc, nhân viên có thể làm việc trong trạng thái bần thần và vướng phải những lỗi lầm có thể tránh được.","audioKind":"ex2"}],"collocations":[{"en":"in a daze","vi":"ở trạng thái bần thần"},{"en":"leave someone dazed","vi":"làm ai đó choáng váng"},{"en":"look dazed","vi":"trông có vẻ ngơ ngác"}],"wordFamily":["dazed (adj.)"],"synonyms":["stun","bewilder"],"antonyms":[],"tipVi":"in a daze chỉ trạng thái bần thần; để chỉ ánh sáng chói lóa thông thường dùng dazzle.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_criterion', 'en-c1-30', 'criterion', '/kraɪˈtɪriən/', 'C1', 'tiêu chí; chuẩn mực', 'n.', NULL, 'Đồng nghĩa: standard, benchmark', 'Dạng số ít là criterion, số nhiều là criteria; không dùng a criteria.', 'Price was my main criterion when choosing a bicycle.', NULL, 'Giá cả là tiêu chí chính của tôi khi chọn mua xe đạp.', '{"wordId":"criterion","ukIpa":"/kraɪˈtɪəriən/","usIpa":"/kraɪˈtɪriən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A standard used to judge something or make a decision.","vi":"tiêu chí; chuẩn mực"}],"examples":[{"en":"Price was my main criterion when choosing a bicycle.","vi":"Giá cả là tiêu chí chính của tôi khi chọn mua xe đạp.","audioKind":"ex"},{"en":"Environmental impact should be a key criterion when governments assess proposals for new transport infrastructure.","vi":"Tác động môi trường nên là một tiêu chí quan trọng khi chính phủ thẩm định các đề xuất về cơ sở hạ tầng giao thông mới.","audioKind":"ex2"}],"collocations":[{"en":"meet a criterion","vi":"đạt tiêu chí"},{"en":"selection criteria","vi":"tiêu chí tuyển chọn"},{"en":"assessment criteria","vi":"tiêu chí đánh giá"}],"wordFamily":[],"synonyms":["standard","benchmark"],"antonyms":[],"tipVi":"Dạng số ít là criterion, số nhiều là criteria; không dùng a criteria.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obscure', 'en-c1-30', 'obscure', '/əbˈskjʊr/', 'C1', 'ít tên tuổi; ít người biết đến; mơ hồ; khó hiểu; làm mờ; che khuất', 'adj.', 'obscurity (n.), obscurely (adv.)', 'Đồng nghĩa: little-known, unclear, conceal · Trái nghĩa: famous, clear', 'Khi là tính từ, từ này chỉ sự vô danh hoặc khó hiểu; khi là động từ, nó chỉ sự che khuất hoặc che đậy.', 'We found an obscure little museum behind the station.', NULL, 'Chúng tôi đã tìm thấy một bảo tàng nhỏ ít ai biết đến nằm ở phía sau nhà ga.', '{"wordId":"obscure","ukIpa":"/əbˈskjʊə/","usIpa":"/əbˈskjʊr/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Not known by many people","vi":"ít tên tuổi; ít người biết đến"},{"pos":"adj.","en":"Difficult to understand or not clearly expressed","vi":"mơ hồ; khó hiểu"},{"pos":"v.","en":"Prevent something from being seen or understood clearly","vi":"làm mờ; che khuất"}],"examples":[{"en":"We found an obscure little museum behind the station.","vi":"Chúng tôi đã tìm thấy một bảo tàng nhỏ ít ai biết đến nằm ở phía sau nhà ga.","audioKind":"ex"},{"en":"Overly technical language can obscure important findings, making scientific research less accessible to the public.","vi":"Ngôn ngữ mang tính chuyên môn quá mức có thể làm mờ đi các phát hiện quan trọng, khiến công chúng khó tiếp cận các nghiên cứu khoa học hơn.","audioKind":"ex2"}],"collocations":[{"en":"an obscure writer","vi":"an obscure writer -> một nhà văn ít tên tuổi"},{"en":"an obscure reference","vi":"an obscure reference -> điển tích khó hiểu"},{"en":"obscure the view","vi":"obscure the view -> che khuất tầm nhìn"},{"en":"obscure the truth","vi":"obscure the truth -> che đậy sự thật"}],"wordFamily":["obscurity (n.)","obscurely (adv.)"],"synonyms":["little-known","unclear","conceal"],"antonyms":["famous","clear"],"tipVi":"Khi là tính từ, từ này chỉ sự vô danh hoặc khó hiểu; khi là động từ, nó chỉ sự che khuất hoặc che đậy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inconsistency', 'en-c1-30', 'inconsistency', '/ˌɪnkənˈsɪstənsi/', 'C1', 'sự mâu thuẫn; sự bất nhất; sự bất ổn; tính thất thường', 'n.', 'inconsistent (adj.), inconsistently (adv.), consistent (adj.), consistency (n.)', 'Đồng nghĩa: discrepancy, contradiction · Trái nghĩa: consistency', 'Khi là danh từ đếm được, nó chỉ một điểm mâu thuẫn cụ thể; khi không đếm được, nó chỉ trạng thái thiếu nhất quán.', 'I noticed an inconsistency between your story and hers.', NULL, 'Tôi nhận thấy có một điểm mâu thuẫn giữa câu chuyện của bạn và câu chuyện của cô ấy.', '{"wordId":"inconsistency","ukIpa":"/ˌɪnkənˈsɪstənsi/","usIpa":"/ˌɪnkənˈsɪstənsi/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"a lack of agreement between facts, statements, or actions","vi":"sự mâu thuẫn; sự bất nhất"},{"pos":"n.","en":"the quality of varying unpredictably in standard or performance","vi":"sự bất ổn; tính thất thường"}],"examples":[{"en":"I noticed an inconsistency between your story and hers.","vi":"Tôi nhận thấy có một điểm mâu thuẫn giữa câu chuyện của bạn và câu chuyện của cô ấy.","audioKind":"ex"},{"en":"Inconsistency in the enforcement of regulations can undermine public trust and create unfair advantages for some businesses.","vi":"Sự bất nhất trong việc thực thi các quy định có thể làm suy yếu lòng tin của công chúng và tạo ra lợi thế không công bằng cho một số doanh nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"inconsistency between accounts","vi":"sự mâu thuẫn giữa các bản khai"},{"en":"internal inconsistency","vi":"mâu thuẫn nội tại"},{"en":"inconsistency in performance","vi":"sự thất thường trong hiệu suất"}],"wordFamily":["inconsistent (adj.)","inconsistently (adv.)","consistent (adj.)","consistency (n.)"],"synonyms":["discrepancy","contradiction"],"antonyms":["consistency"],"tipVi":"Khi là danh từ đếm được, nó chỉ một điểm mâu thuẫn cụ thể; khi không đếm được, nó chỉ trạng thái thiếu nhất quán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_articulate', 'en-c1-30', 'articulate', '/ɑːrˈtɪkjələt/', 'C1', 'lưu loát; ăn nói rõ ràng; diễn đạt rõ ràng; trình bày gãy gọn', 'adj.', 'articulation (n.), articulately (adv.), inarticulate (adj.)', 'Đồng nghĩa: eloquent, express · Trái nghĩa: inarticulate', 'Tính từ có đuôi phát âm là /lət/, trong khi động từ có đuôi phát âm là /leɪt/.', 'Our articulate neighbour explained the problem clearly at dinner.', NULL, 'Người hàng xóm ăn nói lưu loát của chúng tôi đã giải thích vấn đề rất rõ ràng vào bữa tối.', '{"wordId":"articulate","ukIpa":"/ɑːˈtɪkjələt/","usIpa":"/ɑːrˈtɪkjələt/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"able to express ideas clearly and effectively","vi":"lưu loát; ăn nói rõ ràng"},{"pos":"v.","en":"to express thoughts or feelings clearly in words","vi":"diễn đạt rõ ràng; trình bày gãy gọn"}],"examples":[{"en":"Our articulate neighbour explained the problem clearly at dinner.","vi":"Người hàng xóm ăn nói lưu loát của chúng tôi đã giải thích vấn đề rất rõ ràng vào bữa tối.","audioKind":"ex"},{"en":"Schools should help students articulate their opinions clearly while encouraging them to consider alternative perspectives.","vi":"Nhà trường nên giúp học sinh diễn đạt rõ ràng quan điểm của mình, đồng thời khuyến khích các em xem xét các góc nhìn khác.","audioKind":"ex2"}],"collocations":[{"en":"an articulate speaker","vi":"một diễn giả ăn nói lưu loát"},{"en":"articulate ideas","vi":"diễn đạt ý tưởng"},{"en":"articulate concerns","vi":"bày tỏ sự quan tâm"}],"wordFamily":["articulation (n.)","articulately (adv.)","inarticulate (adj.)"],"synonyms":["eloquent","express"],"antonyms":["inarticulate"],"tipVi":"Tính từ có đuôi phát âm là /lət/, trong khi động từ có đuôi phát âm là /leɪt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pragmatic', 'en-c1-30', 'pragmatic', '/præɡˈmætɪk/', 'C1', 'thực tế; thực dụng; chú trọng hiệu quả thực tế', 'adj.', 'pragmatically (adv.), pragmatism (n.), pragmatist (n.)', 'Đồng nghĩa: practical, realistic · Trái nghĩa: idealistic', 'Nhấn mạnh tính khả thi và hiệu quả trong thực tế, thay vì chỉ dựa vào lý thuyết hay lý tưởng.', 'We took a pragmatic approach and repaired the old sofa.', NULL, 'Chúng tôi đã áp dụng cách tiếp cận thực tế và sửa chữa chiếc ghế sofa cũ.', '{"wordId":"pragmatic","ukIpa":"/præɡˈmætɪk/","usIpa":"/præɡˈmætɪk/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Choosing what works in practice rather than following ideals.","vi":"thực tế; thực dụng; chú trọng hiệu quả thực tế"}],"examples":[{"en":"We took a pragmatic approach and repaired the old sofa.","vi":"Chúng tôi đã áp dụng cách tiếp cận thực tế và sửa chữa chiếc ghế sofa cũ.","audioKind":"ex"},{"en":"A pragmatic housing policy should balance environmental goals with the immediate needs of local residents.","vi":"Một chính sách nhà ở thực tế nên cân bằng giữa các mục tiêu môi trường và nhu cầu cấp thiết của người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"pragmatic approach","vi":"phương pháp thực tế"},{"en":"pragmatic solution","vi":"giải pháp thiết thực"},{"en":"pragmatic decision","vi":"quyết định thực tế"}],"wordFamily":["pragmatically (adv.)","pragmatism (n.)","pragmatist (n.)"],"synonyms":["practical","realistic"],"antonyms":["idealistic"],"tipVi":"Nhấn mạnh tính khả thi và hiệu quả trong thực tế, thay vì chỉ dựa vào lý thuyết hay lý tưởng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_materialize', 'en-c1-30', 'materialize', '/məˈtɪriəlaɪz/', 'C1', 'thành hiện thực; xảy ra; thành công; xuất hiện đột ngột', 'v.', 'materialization (n.)', 'Đồng nghĩa: happen, appear · Trái nghĩa: vanish', 'Thường đóng vai trò là nội động từ, chỉ kế hoạch trở thành hiện thực; tiếng Anh-Anh cũng viết là materialise.', 'Our weekend trip never materialized because everyone was too busy.', NULL, 'Chuyến đi cuối tuần của chúng tôi rốt cuộc đã không thành hiện thực vì ai nấy đều quá bận rộn.', '{"wordId":"materialize","ukIpa":"/məˈtɪəriəlaɪz/","usIpa":"/məˈtɪriəlaɪz/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To happen or become real after being expected or planned.","vi":"thành hiện thực; xảy ra; thành công"},{"pos":"v.","en":"To appear suddenly or unexpectedly.","vi":"xuất hiện đột ngột"}],"examples":[{"en":"Our weekend trip never materialized because everyone was too busy.","vi":"Chuyến đi cuối tuần của chúng tôi rốt cuộc đã không thành hiện thực vì ai nấy đều quá bận rộn.","audioKind":"ex"},{"en":"The promised economic benefits may not materialize unless governments also invest in education and transport.","vi":"Lợi ích kinh tế đã được hứa hẹn có thể sẽ không thành hiện thực trừ khi chính phủ cũng đầu tư vào giáo dục và giao thông.","audioKind":"ex2"}],"collocations":[{"en":"fail to materialize","vi":"không thành hiện thực"},{"en":"never materialize","vi":"hoàn toàn không thành hiện thực"},{"en":"benefits materialize","vi":"lợi ích hiện rõ"}],"wordFamily":["materialization (n.)"],"synonyms":["happen","appear"],"antonyms":["vanish"],"tipVi":"Thường đóng vai trò là nội động từ, chỉ kế hoạch trở thành hiện thực; tiếng Anh-Anh cũng viết là materialise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inattention', 'en-c1-30', 'inattention', '/ˌɪnəˈtenʃən/', 'C1', 'sự thiếu chú ý; sự lơ đễnh; sự mất tập trung', 'n.', 'attention (n.), inattentive (adj.), inattentively (adv.)', 'Đồng nghĩa: heedlessness · Trái nghĩa: attention, attentiveness', 'Là danh từ không đếm được; cấu trúc inattention to dùng để chỉ thái độ không để tâm đến việc gì.', 'A moment of inattention left the toast badly burnt.', NULL, 'Chỉ một phút lơ đễnh đã khiến bánh mì nướng bị cháy đen.', '{"wordId":"inattention","ukIpa":"/ˌɪnəˈtenʃən/","usIpa":"/ˌɪnəˈtenʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"failure to give enough attention to someone or something","vi":"sự thiếu chú ý; sự lơ đễnh; sự mất tập trung"}],"examples":[{"en":"A moment of inattention left the toast badly burnt.","vi":"Chỉ một phút lơ đễnh đã khiến bánh mì nướng bị cháy đen.","audioKind":"ex"},{"en":"Driver inattention remains a major road safety concern, particularly as mobile devices become increasingly common.","vi":"Tình trạng tài xế mất tập trung vẫn là một mối lo ngại lớn về an toàn giao thông, đặc biệt khi các thiết bị di động ngày càng trở nên phổ biến.","audioKind":"ex2"}],"collocations":[{"en":"a moment of inattention","vi":"một phút lơ đễnh"},{"en":"driver inattention","vi":"tài xế không tập trung"},{"en":"inattention to detail","vi":"sự thiếu chú ý đến chi tiết"}],"wordFamily":["attention (n.)","inattentive (adj.)","inattentively (adv.)"],"synonyms":["heedlessness"],"antonyms":["attention","attentiveness"],"tipVi":"Là danh từ không đếm được; cấu trúc inattention to dùng để chỉ thái độ không để tâm đến việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perceptible', 'en-c1-30', 'perceptible', '/pɚˈseptəbl/', 'C1', 'có thể nhận thức được; có thể cảm nhận rõ; có thể thấy rõ', 'adj.', 'perceive (v.), perception (n.), perceptibly (adv.), imperceptible (adj.)', 'Đồng nghĩa: noticeable, detectable · Trái nghĩa: imperceptible', 'Chỉ mức độ có thể nhận biết, không nhất thiết là quá lớn; thường đi kèm với barely.', 'There was a barely perceptible tremble in his voice.', NULL, 'Giọng nói của anh ấy có một chút run rẩy gần như không thể nhận ra.', '{"wordId":"perceptible","ukIpa":"/pəˈseptəbl/","usIpa":"/pɚˈseptəbl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Noticeable through the senses or the mind.","vi":"có thể nhận thức được; có thể cảm nhận rõ; có thể thấy rõ"}],"examples":[{"en":"There was a barely perceptible tremble in his voice.","vi":"Giọng nói của anh ấy có một chút run rẩy gần như không thể nhận ra.","audioKind":"ex"},{"en":"Cleaner transport policies have produced a perceptible improvement in air quality across several densely populated districts.","vi":"Các chính sách giao thông xanh hơn đã tạo ra một sự cải thiện rõ rệt về chất lượng không khí ở một số khu vực đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"barely perceptible","vi":"hầu như không thể nhận thấy"},{"en":"perceptible change","vi":"sự thay đổi có thể nhận thấy"},{"en":"perceptible difference","vi":"sự khác biệt rõ rệt"}],"wordFamily":["perceive (v.)","perception (n.)","perceptibly (adv.)","imperceptible (adj.)"],"synonyms":["noticeable","detectable"],"antonyms":["imperceptible"],"tipVi":"Chỉ mức độ có thể nhận biết, không nhất thiết là quá lớn; thường đi kèm với barely.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peripheral', 'en-c1-30', 'peripheral', '/pəˈrɪfərəl/', 'C1', 'thứ yếu; không quan trọng bằng vấn đề chính; ở vùng ngoài; ngoại biên; thiết bị ngoại vi', 'adj.', 'periphery (n.), peripherally (adv.)', 'Đồng nghĩa: marginal, secondary · Trái nghĩa: central', 'peripheral to mang ý nghĩa là thứ yếu hoặc không cốt lõi đối với cái gì.', 'The paint colour is peripheral to our kitchen repairs.', NULL, 'Màu sơn chỉ là vấn đề phụ trong việc sửa chữa nhà bếp của chúng ta.', '{"wordId":"peripheral","ukIpa":"/pəˈrɪfərəl/","usIpa":"/pəˈrɪfərəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Not central to the main issue or activity.","vi":"thứ yếu; không quan trọng bằng vấn đề chính"},{"pos":"adj.","en":"Situated away from the centre, towards the outer edge.","vi":"ở vùng ngoài; ngoại biên"},{"pos":"n.","en":"A device connected to a computer for additional functions.","vi":"thiết bị ngoại vi"}],"examples":[{"en":"The paint colour is peripheral to our kitchen repairs.","vi":"Màu sơn chỉ là vấn đề phụ trong việc sửa chữa nhà bếp của chúng ta.","audioKind":"ex"},{"en":"Funding debates should not allow peripheral issues to distract attention from the central goal of improving education.","vi":"Các cuộc tranh luận về kinh phí không nên để những vấn đề thứ yếu làm chệch hướng sự chú ý khỏi mục tiêu cốt lõi là nâng cao chất lượng giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"peripheral issue","vi":"vấn đề thứ yếu"},{"en":"peripheral vision","vi":"tầm nhìn ngoại vi"},{"en":"peripheral nerves","vi":"dây thần kinh ngoại biên"},{"en":"peripheral device","vi":"thiết bị ngoại vi"}],"wordFamily":["periphery (n.)","peripherally (adv.)"],"synonyms":["marginal","secondary"],"antonyms":["central"],"tipVi":"peripheral to mang ý nghĩa là thứ yếu hoặc không cốt lõi đối với cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_situational', 'en-c1-30', 'situational', '/ˌsɪtʃuˈeɪʃənəl/', 'C1', 'mang tính tình huống, phụ thuộc vào hoàn cảnh, do hoàn cảnh cụ thể tạo ra', 'adj.', 'situation (n.), situationally (adv.)', NULL, 'Nhấn mạnh sự chi phối của một hoàn cảnh cụ thể, không đồng nghĩa hoàn toàn với tính chất tạm thời.', 'My anxiety is situational, appearing only in crowded lifts.', NULL, 'Chứng lo âu của tôi chỉ mang tính tình huống, nó chỉ xuất hiện khi tôi ở trong những chiếc thang máy đông đúc.', '{"wordId":"situational","ukIpa":"/ˌsɪtʃuˈeɪʃənəl/","usIpa":"/ˌsɪtʃuˈeɪʃənəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Related to or caused by the circumstances of a particular situation.","vi":"mang tính tình huống, phụ thuộc vào hoàn cảnh, do hoàn cảnh cụ thể tạo ra"}],"examples":[{"en":"My anxiety is situational, appearing only in crowded lifts.","vi":"Chứng lo âu của tôi chỉ mang tính tình huống, nó chỉ xuất hiện khi tôi ở trong những chiếc thang máy đông đúc.","audioKind":"ex"},{"en":"Teachers should consider situational factors, such as classroom noise, before attributing poor performance to a lack of ability.","vi":"Giáo viên nên cân nhắc các yếu tố tình huống, chẳng hạn như tiếng ồn trong lớp học, trước khi quy kết việc học kém là do thiếu năng lực.","audioKind":"ex2"}],"collocations":[{"en":"situational factors","vi":"các yếu tố tình huống"},{"en":"situational awareness","vi":"sự nhận thức tình huống"},{"en":"situational anxiety","vi":"sự lo âu theo tình huống"}],"wordFamily":["situation (n.)","situationally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh sự chi phối của một hoàn cảnh cụ thể, không đồng nghĩa hoàn toàn với tính chất tạm thời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_detract', 'en-c1-30', 'detract', '/dɪˈtrækt/', 'C1', 'làm giảm giá trị; làm lu mờ; hạ thấp', 'v.', 'detractor (n.), detraction (n.)', 'Đồng nghĩa: diminish, lessen · Trái nghĩa: enhance', 'Thường đi kèm với giới từ detract from và không cộng trực tiếp với tân ngữ.', 'The noisy road detracts from our garden''s peaceful atmosphere.', NULL, 'Tiếng ồn từ con đường lớn làm mất đi bầu không khí yên bình của khu vườn nhà chúng tôi.', '{"wordId":"detract","ukIpa":"/dɪˈtrækt/","usIpa":"/dɪˈtrækt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To make something seem less valuable, attractive, or impressive.","vi":"làm giảm giá trị; làm lu mờ; hạ thấp"}],"examples":[{"en":"The noisy road detracts from our garden''s peaceful atmosphere.","vi":"Tiếng ồn từ con đường lớn làm mất đi bầu không khí yên bình của khu vườn nhà chúng tôi.","audioKind":"ex"},{"en":"Poor public transport can detract from a city''s appeal, even when its cultural attractions are exceptional.","vi":"Hệ thống giao thông công cộng kém chất lượng có thể làm giảm sức hút của một thành phố, ngay cả khi các điểm tham quan văn hóa của nơi đó vô cùng xuất sắc.","audioKind":"ex2"}],"collocations":[{"en":"detract from the appeal","vi":"làm giảm sức hút"},{"en":"detract from the value","vi":"làm giảm giá trị"},{"en":"detract from the achievement","vi":"làm lu mờ thành tựu"}],"wordFamily":["detractor (n.)","detraction (n.)"],"synonyms":["diminish","lessen"],"antonyms":["enhance"],"tipVi":"Thường đi kèm với giới từ detract from và không cộng trực tiếp với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ponder', 'en-c1-30', 'ponder', '/ˈpɑːndər/', 'C1', 'cân nhắc kỹ lưỡng; suy ngẫm; trầm ngâm', 'v.', NULL, 'Đồng nghĩa: consider, contemplate, reflect', 'Có thể trực tiếp đi với tân ngữ hoặc dùng với giới từ ponder on/over.', 'She pondered the menu before ordering vegetable soup.', NULL, 'Cô ấy đắn đo suy nghĩ một lúc trước khi gọi món súp rau củ.', '{"wordId":"ponder","ukIpa":"/ˈpɒndə/","usIpa":"/ˈpɑːndər/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to think carefully about something for some time","vi":"cân nhắc kỹ lưỡng; suy ngẫm; trầm ngâm"}],"examples":[{"en":"She pondered the menu before ordering vegetable soup.","vi":"Cô ấy đắn đo suy nghĩ một lúc trước khi gọi món súp rau củ.","audioKind":"ex"},{"en":"Policymakers must ponder the long-term consequences of replacing public transport services with privately operated alternatives.","vi":"Các nhà hoạch định chính sách phải cân nhắc kỹ lưỡng các hậu quả lâu dài của việc thay thế dịch vụ giao thông công cộng bằng các lựa chọn tư nhân.","audioKind":"ex2"}],"collocations":[{"en":"ponder a question","vi":"suy ngẫm một vấn đề"},{"en":"ponder the implications","vi":"cân nhắc kỹ các tác động"},{"en":"ponder over something","vi":"trầm ngâm suy nghĩ về điều gì"}],"wordFamily":[],"synonyms":["consider","contemplate","reflect"],"antonyms":[],"tipVi":"Có thể trực tiếp đi với tân ngữ hoặc dùng với giới từ ponder on/over.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coherent', 'en-c1-30', 'coherent', '/koʊˈhɪrənt/', 'C1', 'mạch lạc; rành mạch; chặt chẽ', 'adj.', 'coherence (n.), coherently (adv.), incoherent (adj.)', 'Đồng nghĩa: logical, consistent · Trái nghĩa: incoherent', 'Nhấn mạnh vào tính logic và sự liên kết rõ ràng của nội dung; trong khi cohesive nhấn mạnh hơn vào sự gắn kết chặt chẽ giữa các phần.', 'After some practice, he gave a clear, coherent explanation.', NULL, 'Sau một hồi luyện tập, anh ấy đã đưa ra một lời giải thích rõ ràng và mạch lạc.', '{"wordId":"coherent","ukIpa":"/kəʊˈhɪərənt/","usIpa":"/koʊˈhɪrənt/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Logical and clear, with parts that fit together well.","vi":"mạch lạc; rành mạch; chặt chẽ"}],"examples":[{"en":"After some practice, he gave a clear, coherent explanation.","vi":"Sau một hồi luyện tập, anh ấy đã đưa ra một lời giải thích rõ ràng và mạch lạc.","audioKind":"ex"},{"en":"A coherent transport policy should connect investment in public services with long-term environmental and economic goals.","vi":"Một chính sách giao thông nhất quán cần phải gắn kết nguồn đầu tư vào các dịch vụ công với các mục tiêu môi trường và kinh tế dài hạn.","audioKind":"ex2"}],"collocations":[{"en":"a coherent argument","vi":"một lập luận logic chặt chẽ"},{"en":"a coherent explanation","vi":"một lời giải thích mạch lạc"},{"en":"a coherent strategy","vi":"một chiến lược đồng bộ"}],"wordFamily":["coherence (n.)","coherently (adv.)","incoherent (adj.)"],"synonyms":["logical","consistent"],"antonyms":["incoherent"],"tipVi":"Nhấn mạnh vào tính logic và sự liên kết rõ ràng của nội dung; trong khi cohesive nhấn mạnh hơn vào sự gắn kết chặt chẽ giữa các phần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_facet', 'en-c1-30', 'facet', '/ˈfæsɪt/', 'C1', 'khía cạnh; mặt; mặt cắt (của đá quý)', 'n.', 'faceted (adj.), multifaceted (adj.)', 'Đồng nghĩa: aspect, dimension', 'Thường dùng cụm a facet of để chỉ một phần hoặc khía cạnh của một vấn đề phức tạp.', 'Cooking together revealed a new facet of her personality.', NULL, 'Việc cùng nhau nấu ăn đã hé lộ một khía cạnh mới trong tính cách của cô ấy.', '{"wordId":"facet","ukIpa":"/ˈfæsɪt/","usIpa":"/ˈfæsɪt/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"One part or aspect of a complex subject.","vi":"khía cạnh; mặt"},{"pos":"n.","en":"A small flat surface on a cut stone.","vi":"mặt cắt (của đá quý)"}],"examples":[{"en":"Cooking together revealed a new facet of her personality.","vi":"Việc cùng nhau nấu ăn đã hé lộ một khía cạnh mới trong tính cách của cô ấy.","audioKind":"ex"},{"en":"Public transport affects almost every facet of urban life, from employment opportunities to air quality.","vi":"Giao thông công cộng ảnh hưởng đến hầu như mọi khía cạnh của đời sống đô thị, từ cơ hội việc làm cho đến chất lượng không khí.","audioKind":"ex2"}],"collocations":[{"en":"a facet of life","vi":"một khía cạnh của cuộc sống"},{"en":"every facet","vi":"mọi khía cạnh"},{"en":"a different facet","vi":"một khía cạnh khác"}],"wordFamily":["faceted (adj.)","multifaceted (adj.)"],"synonyms":["aspect","dimension"],"antonyms":[],"tipVi":"Thường dùng cụm a facet of để chỉ một phần hoặc khía cạnh của một vấn đề phức tạp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intrinsic', 'en-c1-30', 'intrinsic', '/ɪnˈtrɪnzɪk/', 'C1', 'bản chất; nội tại; vốn có', 'adj.', 'intrinsically (adv.)', 'Đồng nghĩa: inherent, inbuilt · Trái nghĩa: extrinsic', 'Cấu trúc intrinsic to diễn đạt ý nghĩa "vốn có đối với/của..."', 'She values the intrinsic beauty of untreated wood.', NULL, 'Cô ấy trân trọng vẻ đẹp vốn có của những thớ gỗ chưa qua xử lý.', '{"wordId":"intrinsic","ukIpa":"/ɪnˈtrɪnzɪk/","usIpa":"/ɪnˈtrɪnzɪk/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Belonging naturally to something, rather than coming from outside","vi":"bản chất; nội tại; vốn có"}],"examples":[{"en":"She values the intrinsic beauty of untreated wood.","vi":"Cô ấy trân trọng vẻ đẹp vốn có của những thớ gỗ chưa qua xử lý.","audioKind":"ex"},{"en":"Schools should encourage intrinsic motivation by helping students enjoy learning rather than focusing solely on external rewards.","vi":"Các trường học nên khuyến khích động lực nội tại bằng cách giúp học sinh tận hưởng việc học thay vì chỉ tập trung hoàn toàn vào phần thưởng bên ngoài.","audioKind":"ex2"}],"collocations":[{"en":"intrinsic value","vi":"giá trị nội tại"},{"en":"intrinsic motivation","vi":"động lực nội tại"},{"en":"intrinsic to","vi":"vốn có đối với"}],"wordFamily":["intrinsically (adv.)"],"synonyms":["inherent","inbuilt"],"antonyms":["extrinsic"],"tipVi":"Cấu trúc intrinsic to diễn đạt ý nghĩa \"vốn có đối với/của...\"","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mortal', 'en-c1-30', 'mortal', '/ˈmɔːrtəl/', 'C1', 'có sinh có diệt; phải chết; chí mạng; gây chết người; phàm nhân; người trần mắt thịt', 'adj.', 'mortality (n.), mortally (adv.), immortal (adj.), immortality (n.)', 'Trái nghĩa: immortal', 'Từ "mortal" chỉ con người phàm trần; trong khi tỷ lệ tử vong dùng từ "mortality", không dùng "mortal".', 'Even the strongest heroes in this story are mortal.', NULL, 'Ngay cả những người anh hùng mạnh mẽ nhất trong câu chuyện này cũng có lúc phải chết.', '{"wordId":"mortal","ukIpa":"/ˈmɔːtəl/","usIpa":"/ˈmɔːrtəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"unable to live forever","vi":"có sinh có diệt; phải chết"},{"pos":"adj.","en":"causing or likely to cause death","vi":"chí mạng; gây chết người"},{"pos":"n.","en":"a human being who cannot live forever","vi":"phàm nhân; người trần mắt thịt"}],"examples":[{"en":"Even the strongest heroes in this story are mortal.","vi":"Ngay cả những người anh hùng mạnh mẽ nhất trong câu chuyện này cũng có lúc phải chết.","audioKind":"ex"},{"en":"Recognising that we are mortal can encourage healthier habits and a greater appreciation of everyday life.","vi":"Việc nhận thức rõ bản thân là những sinh hữu hạn có thể thúc đẩy các thói quen lành mạnh hơn và giúp chúng ta trân trọng cuộc sống hằng ngày nhiều hơn.","audioKind":"ex2"}],"collocations":[{"en":"mortal wound","vi":"vết thương chí mạng"},{"en":"mortal danger","vi":"nguy hiểm chết người"},{"en":"mere mortals","vi":"những phàm nhân bình thường"}],"wordFamily":["mortality (n.)","mortally (adv.)","immortal (adj.)","immortality (n.)"],"synonyms":[],"antonyms":["immortal"],"tipVi":"Từ \"mortal\" chỉ con người phàm trần; trong khi tỷ lệ tử vong dùng từ \"mortality\", không dùng \"mortal\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loom', 'en-c1-30', 'loom', '/luːm/', 'C1', 'hiện lên lờ mờ, xuất hiện với hình thù to lớn và có vẻ đe dọa; chỉ (sự việc không hay) sắp xảy ra, đang đến gần gây lo âu; khung cửi, máy dệt', 'v.', 'looming (adj.)', NULL, 'Động từ thường mang sắc thái áp lực hoặc lo lắng; loom large chỉ vấn đề trở nên nổi cộm.', 'A huge ship loomed out of the morning fog.', NULL, 'Một con tàu khổng lồ hiện ra lờ mờ từ làn sương sớm.', '{"wordId":"loom","ukIpa":"/luːm/","usIpa":"/luːm/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"Appear as a large, often threatening or unclear shape.","vi":"hiện lên lờ mờ, xuất hiện với hình thù to lớn và có vẻ đe dọa"},{"pos":"v.","en":"Seem likely to happen soon, causing worry.","vi":"chỉ (sự việc không hay) sắp xảy ra, đang đến gần gây lo âu"},{"pos":"n.","en":"A machine or frame used to weave cloth.","vi":"khung cửi, máy dệt"}],"examples":[{"en":"A huge ship loomed out of the morning fog.","vi":"Một con tàu khổng lồ hiện ra lờ mờ từ làn sương sớm.","audioKind":"ex"},{"en":"As water shortages loom, governments must invest in efficient irrigation and encourage households to reduce unnecessary consumption.","vi":"Khi tình trạng thiếu nước sắp xảy ra, chính phủ phải đầu tư vào hệ thống tưới tiêu hiệu quả và khuyến khích các hộ gia đình giảm mức tiêu thụ không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"loom over","vi":"hiện lên ở phía trên"},{"en":"loom large","vi":"nổi cộm và gây lo ngại"},{"en":"weaving loom","vi":"khung cửi dệt"}],"wordFamily":["looming (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường mang sắc thái áp lực hoặc lo lắng; loom large chỉ vấn đề trở nên nổi cộm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_philosophical', 'en-c1-30', 'philosophical', '/ˌfɪləˈsɑːfɪkəl/', 'C1', 'thuộc về triết học; điềm tĩnh, thản nhiên chấp nhận khó khăn như một phần tất yếu của cuộc sống; thông thái, khoáng đạt', 'adj.', 'philosophy (n.), philosopher (n.), philosophically (adv.)', NULL, 'Cấu trúc be philosophical about dùng để chỉ thái độ nghĩ thoáng và chấp nhận những điều không như ý.', 'Our conversation became philosophical as we discussed life''s purpose.', NULL, 'Cuộc trò chuyện của chúng tôi trở nên mang tính triết lý khi chúng tôi bàn về mục đích của cuộc sống.', '{"wordId":"philosophical","ukIpa":"/ˌfɪləˈsɒfɪkəl/","usIpa":"/ˌfɪləˈsɑːfɪkəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"relating to the study of knowledge, existence, and values","vi":"thuộc về triết học"},{"pos":"adj.","en":"accepting difficulties calmly as a natural part of life","vi":"điềm tĩnh, thản nhiên chấp nhận khó khăn như một phần tất yếu của cuộc sống; thông thái, khoáng đạt"}],"examples":[{"en":"Our conversation became philosophical as we discussed life''s purpose.","vi":"Cuộc trò chuyện của chúng tôi trở nên mang tính triết lý khi chúng tôi bàn về mục đích của cuộc sống.","audioKind":"ex"},{"en":"Debates about artificial intelligence raise philosophical questions concerning responsibility, human identity, and the meaning of creativity.","vi":"Các cuộc tranh luận về trí tuệ nhân tạo đặt ra những câu hỏi mang tính triết học liên quan đến trách nhiệm, bản sắc con người và ý nghĩa của sự sáng tạo.","audioKind":"ex2"}],"collocations":[{"en":"philosophical question","vi":"câu hỏi triết học"},{"en":"philosophical debate","vi":"cuộc tranh luận triết học"},{"en":"philosophical about setbacks","vi":"thái độ thản nhiên trước những thăng trầm"}],"wordFamily":["philosophy (n.)","philosopher (n.)","philosophically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc be philosophical about dùng để chỉ thái độ nghĩ thoáng và chấp nhận những điều không như ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ramification', 'en-c1-30', 'ramification', '/ˌræmɪfɪˈkeɪʃən/', 'C1', 'hệ quả phụ, hệ lụy, tác động nhánh (thường là phức tạp hoặc bất ngờ phát sinh từ một hành động hay quyết định)', 'n.', 'ramify (v.)', 'Đồng nghĩa: consequence, repercussion', 'Thường dùng ở số nhiều ramifications, chỉ những hệ quả rắc rối hoặc nằm ngoài dự tính.', 'We hadn''t considered every ramification of moving so far away.', NULL, 'Chúng tôi đã không lường trước được mọi hệ lụy của việc chuyển nhà đi quá xa.', '{"wordId":"ramification","ukIpa":"/ˌræmɪfɪˈkeɪʃən/","usIpa":"/ˌræmɪfɪˈkeɪʃən/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"An additional, often unexpected consequence of an action or decision.","vi":"hệ quả phụ, hệ lụy, tác động nhánh (thường là phức tạp hoặc bất ngờ phát sinh từ một hành động hay quyết định)"}],"examples":[{"en":"We hadn''t considered every ramification of moving so far away.","vi":"Chúng tôi đã không lường trước được mọi hệ lụy của việc chuyển nhà đi quá xa.","audioKind":"ex"},{"en":"Policymakers must consider the long-term ramifications of replacing public transport routes with privately operated services.","vi":"Các nhà hoạch định chính sách phải cân nhắc các hệ lụy lâu dài của việc thay thế các tuyến giao thông công cộng bằng dịch vụ do tư nhân vận hành.","audioKind":"ex2"}],"collocations":[{"en":"have ramifications for","vi":"gây ra hệ lụy cho"},{"en":"far-reaching ramifications","vi":"hệ quả sâu xa"},{"en":"legal ramifications","vi":"hậu quả pháp lý"}],"wordFamily":["ramify (v.)"],"synonyms":["consequence","repercussion"],"antonyms":[],"tipVi":"Thường dùng ở số nhiều ramifications, chỉ những hệ quả rắc rối hoặc nằm ngoài dự tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intrigue', 'en-c1-30', 'intrigue', '/ɪnˈtriːɡ/', 'C1', 'khơi gợi sự tò mò; làm thích thú; mưu đồ; sự cấu kết bí mật', 'v.', 'intriguing (adj.), intrigued (adj.)', 'Đồng nghĩa: fascinate, interest · Trái nghĩa: bore', 'Khi mang nghĩa khơi gợi sự tò mò, đây là ngoại động từ; thường dùng cấu trúc be intrigued by.', 'The locked wooden box intrigued everyone in the room.', NULL, 'Chiếc hộp gỗ có khóa đã làm tất cả mọi người trong phòng tò mò.', '{"wordId":"intrigue","ukIpa":"/ɪnˈtriːɡ/","usIpa":"/ɪnˈtriːɡ/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To make someone curious and eager to learn more.","vi":"khơi gợi sự tò mò; làm thích thú"},{"pos":"n.","en":"Secret planning intended to gain power or an advantage.","vi":"mưu đồ; sự cấu kết bí mật"}],"examples":[{"en":"The locked wooden box intrigued everyone in the room.","vi":"Chiếc hộp gỗ có khóa đã làm tất cả mọi người trong phòng tò mò.","audioKind":"ex"},{"en":"Unexplained archaeological discoveries continue to intrigue researchers and encourage further investigation into the lives of ancient communities.","vi":"Những phát hiện khảo cổ chưa có lời giải tiếp tục thu hút sự quan tâm của các nhà nghiên cứu và thúc đẩy việc đào sâu hơn vào đời sống của các cộng đồng cổ đại.","audioKind":"ex2"}],"collocations":[{"en":"be intrigued by","vi":"cảm thấy tò mò bởi"},{"en":"political intrigue","vi":"mưu đồ chính trị"},{"en":"a web of intrigue","vi":"một mạng lưới âm mưu phức tạp"}],"wordFamily":["intriguing (adj.)","intrigued (adj.)"],"synonyms":["fascinate","interest"],"antonyms":["bore"],"tipVi":"Khi mang nghĩa khơi gợi sự tò mò, đây là ngoại động từ; thường dùng cấu trúc be intrigued by.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_essence', 'en-c1-30', 'essence', '/ˈesəns/', 'C1', 'bản chất; cốt lõi; tinh hoa; tinh dầu; hương liệu cô đặc', 'n.', 'essential (adj.), essentially (adv.)', 'Đồng nghĩa: core', 'Cụm từ in essence mang nghĩa là "về bản chất", được dùng khi tóm tắt ý chính.', 'For me, the essence of friendship is being there.', NULL, 'Đối với tôi, bản chất của tình bạn chính là sự hiện diện và sẻ chia.', '{"wordId":"essence","ukIpa":"/ˈesəns/","usIpa":"/ˈesəns/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"the most important quality that makes something what it is","vi":"bản chất; cốt lõi; tinh hoa"},{"pos":"n.","en":"a concentrated liquid containing a particular flavour or scent","vi":"tinh dầu; hương liệu cô đặc"}],"examples":[{"en":"For me, the essence of friendship is being there.","vi":"Đối với tôi, bản chất của tình bạn chính là sự hiện diện và sẻ chia.","audioKind":"ex"},{"en":"The essence of sustainable development is meeting present needs without limiting opportunities for future generations.","vi":"Bản chất của phát triển bền vững là đáp ứng nhu cầu hiện tại mà không làm hạn chế cơ hội của các thế hệ tương lai.","audioKind":"ex2"}],"collocations":[{"en":"the essence of","vi":"bản chất của"},{"en":"in essence","vi":"về bản chất"},{"en":"vanilla essence","vi":"tinh chất vani"},{"en":"capture the essence","vi":"nắm bắt tinh hoa"}],"wordFamily":["essential (adj.)","essentially (adv.)"],"synonyms":["core"],"antonyms":[],"tipVi":"Cụm từ in essence mang nghĩa là \"về bản chất\", được dùng khi tóm tắt ý chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_30_1', 'en-c1-30', 'Cách dùng “coherent” (adj.) — mạch lạc; rành mạch; chặt chẽ', 'a coherent argument  ·  a coherent explanation  ·  a coherent strategy', 'Nhấn mạnh vào tính logic và sự liên kết rõ ràng của nội dung; trong khi cohesive nhấn mạnh hơn vào sự gắn kết chặt chẽ giữa các phần.', 'Họ từ (Word Family): coherence (n.), coherently (adv.), incoherent (adj.) | Đồng nghĩa: logical, consistent · Trái nghĩa: incoherent', '[{"hanzi":"After some practice, he gave a clear, coherent explanation.","pinyin":"","meaning":"Sau một hồi luyện tập, anh ấy đã đưa ra một lời giải thích rõ ràng và mạch lạc."},{"hanzi":"A coherent transport policy should connect investment in public services with long-term environmental and economic goals.","pinyin":"","meaning":"Một chính sách giao thông nhất quán cần phải gắn kết nguồn đầu tư vào các dịch vụ công với các mục tiêu môi trường và kinh tế dài hạn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_30_2', 'en-c1-30', 'Cách dùng “inconsistency” (n.) — sự mâu thuẫn; sự bất nhất', 'inconsistency between accounts  ·  internal inconsistency  ·  inconsistency in performance', 'Khi là danh từ đếm được, nó chỉ một điểm mâu thuẫn cụ thể; khi không đếm được, nó chỉ trạng thái thiếu nhất quán.', 'Họ từ (Word Family): inconsistent (adj.), inconsistently (adv.), consistent (adj.), consistency (n.) | Đồng nghĩa: discrepancy, contradiction · Trái nghĩa: consistency', '[{"hanzi":"I noticed an inconsistency between your story and hers.","pinyin":"","meaning":"Tôi nhận thấy có một điểm mâu thuẫn giữa câu chuyện của bạn và câu chuyện của cô ấy."},{"hanzi":"Inconsistency in the enforcement of regulations can undermine public trust and create unfair advantages for some businesses.","pinyin":"","meaning":"Sự bất nhất trong việc thực thi các quy định có thể làm suy yếu lòng tin của công chúng và tạo ra lợi thế không công bằng cho một số doanh nghiệp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_30_3', 'en-c1-30', 'Cách dùng “materialize” (v.) — thành hiện thực; xảy ra; thành công', 'fail to materialize  ·  never materialize  ·  benefits materialize', 'Thường đóng vai trò là nội động từ, chỉ kế hoạch trở thành hiện thực; tiếng Anh-Anh cũng viết là materialise.', 'Họ từ (Word Family): materialization (n.) | Đồng nghĩa: happen, appear · Trái nghĩa: vanish', '[{"hanzi":"Our weekend trip never materialized because everyone was too busy.","pinyin":"","meaning":"Chuyến đi cuối tuần của chúng tôi rốt cuộc đã không thành hiện thực vì ai nấy đều quá bận rộn."},{"hanzi":"The promised economic benefits may not materialize unless governments also invest in education and transport.","pinyin":"","meaning":"Lợi ích kinh tế đã được hứa hẹn có thể sẽ không thành hiện thực trừ khi chính phủ cũng đầu tư vào giáo dục và giao thông."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_30_4', 'en-c1-30', 'Cách dùng “obscure” (adj.) — ít tên tuổi; ít người biết đến', 'an obscure writer  ·  an obscure reference  ·  obscure the view', 'Khi là tính từ, từ này chỉ sự vô danh hoặc khó hiểu; khi là động từ, nó chỉ sự che khuất hoặc che đậy.', 'Họ từ (Word Family): obscurity (n.), obscurely (adv.) | Đồng nghĩa: little-known, unclear, conceal · Trái nghĩa: famous, clear', '[{"hanzi":"We found an obscure little museum behind the station.","pinyin":"","meaning":"Chúng tôi đã tìm thấy một bảo tàng nhỏ ít ai biết đến nằm ở phía sau nhà ga."},{"hanzi":"Overly technical language can obscure important findings, making scientific research less accessible to the public.","pinyin":"","meaning":"Ngôn ngữ mang tính chuyên môn quá mức có thể làm mờ đi các phát hiện quan trọng, khiến công chúng khó tiếp cận các nghiên cứu khoa học hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_30_1', 'en-c1-30', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
