INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_1_2', 'ten_c1_30_1', 'tentative', 'We made tentative plans to visit the coast next weekend.', 'We made tentative plans to visit the coast next weekend.', '/ˈtentətɪv/', 'Chúng tôi đã lên kế hoạch tạm thời sẽ đi chơi biển vào cuối tuần tới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_1_3', 'ten_c1_30_1', 'nuance', 'Her smile added a playful nuance to the apology.', 'Her smile added a playful nuance to the apology.', '/ˈnuːɑːns/', 'Nụ cười của cô ấy mang lại một chút sắc thái tinh nghịch cho lời xin lỗi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_1_4', 'ten_c1_30_1', 'daze', 'The sudden crash dazed me for a moment.', 'The sudden crash dazed me for a moment.', '/deɪz/', 'Cú va chạm bất ngờ khiến tôi choáng váng trong giây lát.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_1_5', 'ten_c1_30_1', 'criterion', 'Price was my main criterion when choosing a bicycle.', 'Price was my main criterion when choosing a bicycle.', '/kraɪˈtɪriən/', 'Giá cả là tiêu chí chính của tôi khi chọn mua xe đạp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_1_6', 'ten_c1_30_1', 'obscure', 'We found an obscure little museum behind the station.', 'We found an obscure little museum behind the station.', '/əbˈskjʊr/', 'Chúng tôi đã tìm thấy một bảo tàng nhỏ ít ai biết đến nằm ở phía sau nhà ga.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_1_7', 'ten_c1_30_1', 'inconsistency', 'I noticed an inconsistency between your story and hers.', 'I noticed an inconsistency between your story and hers.', '/ˌɪnkənˈsɪstənsi/', 'Tôi nhận thấy có một điểm mâu thuẫn giữa câu chuyện của bạn và câu chuyện của cô ấy.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_1_8', 'ten_c1_30_1', 'articulate', 'Our articulate neighbour explained the problem clearly at dinner.', 'Our articulate neighbour explained the problem clearly at dinner.', '/ɑːrˈtɪkjələt/', 'Người hàng xóm ăn nói lưu loát của chúng tôi đã giải thích vấn đề rất rõ ràng vào bữa tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_30_1_1', 'en-c1-30', 'ten_c1_30_1', 'listening', 'listening', 'Sharing a flat seems like a viable option.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thuê chung một căn hộ có vẻ là một lựa chọn khả thi.","Tôi nhận thấy có một điểm mâu thuẫn giữa câu chuyện của bạn và câu chuyện của cô ấy.","Chỉ một phút lơ đễnh đã khiến bánh mì nướng bị cháy đen.","Tiếng ồn từ con đường lớn làm mất đi bầu không khí yên bình của khu vườn nhà chúng tôi."]'::jsonb, 0, 'Sharing a flat seems like a viable option. → Thuê chung một căn hộ có vẻ là một lựa chọn khả thi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_30_1_2', 'en-c1-30', 'ten_c1_30_1', 'listening', 'listening', 'We made tentative plans to visit the coast next weekend.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đối với tôi, bản chất của tình bạn chính là sự hiện diện và sẻ chia.","Chúng tôi đã lên kế hoạch tạm thời sẽ đi chơi biển vào cuối tuần tới.","Sau một hồi luyện tập, anh ấy đã đưa ra một lời giải thích rõ ràng và mạch lạc.","Giá cả là tiêu chí chính của tôi khi chọn mua xe đạp."]'::jsonb, 1, 'We made tentative plans to visit the coast next weekend. → Chúng tôi đã lên kế hoạch tạm thời sẽ đi chơi biển vào cuối tuần tới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_30_1_3', 'en-c1-30', 'ten_c1_30_1', 'listening', 'listening', 'Her smile added a playful nuance to the apology.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nụ cười của cô ấy mang lại một chút sắc thái tinh nghịch cho lời xin lỗi.","Chứng lo âu của tôi chỉ mang tính tình huống, nó chỉ xuất hiện khi tôi ở trong những chiếc thang máy đông đúc.","Chiếc hộp gỗ có khóa đã làm tất cả mọi người trong phòng tò mò.","Thuê chung một căn hộ có vẻ là một lựa chọn khả thi."]'::jsonb, 0, 'Her smile added a playful nuance to the apology. → Nụ cười của cô ấy mang lại một chút sắc thái tinh nghịch cho lời xin lỗi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_30_2', 'en-c1-30', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_2_1', 'ten_c1_30_2', 'viable', 'Public transport must be affordable and reliable to become a viable alternative to private cars.', 'Public transport must be affordable and reliable to become a viable alternative to private cars.', '/ˈvaɪəbl/', 'Giao thông công cộng phải có giá cả phải chăng và đáng tin cậy để có thể trở thành sự thay thế khả thi cho xe hơi cá nhân.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_2_2', 'ten_c1_30_2', 'tentative', 'Researchers have drawn tentative conclusions, but further studies are needed before the treatment can be widely recommended.', 'Researchers have drawn tentative conclusions, but further studies are needed before the treatment can be widely recommended.', '/ˈtentətɪv/', 'Các nhà nghiên cứu đã đưa ra những kết luận ban đầu, nhưng cần phải có thêm nhiều nghiên cứu trước khi phương pháp điều trị này có thể được khuyến khích rộng rãi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_2_3', 'ten_c1_30_2', 'nuance', 'Language learners need cultural knowledge to recognise nuances that dictionaries may not fully explain.', 'Language learners need cultural knowledge to recognise nuances that dictionaries may not fully explain.', '/ˈnuːɑːns/', 'Người học ngoại ngữ cần có kiến thức văn hóa để nhận biết những sắc thái tinh tế mà từ điển có thể không giải thích hết được.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_2_4', 'ten_c1_30_2', 'daze', 'After several nights of poor sleep, employees may work in a daze and make avoidable mistakes.', 'After several nights of poor sleep, employees may work in a daze and make avoidable mistakes.', '/deɪz/', 'Sau vài đêm ngủ không đủ giấc, nhân viên có thể làm việc trong trạng thái bần thần và vướng phải những lỗi lầm có thể tránh được.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_2_5', 'ten_c1_30_2', 'criterion', 'Environmental impact should be a key criterion when governments assess proposals for new transport infrastructure.', 'Environmental impact should be a key criterion when governments assess proposals for new transport infrastructure.', '/kraɪˈtɪriən/', 'Tác động môi trường nên là một tiêu chí quan trọng khi chính phủ thẩm định các đề xuất về cơ sở hạ tầng giao thông mới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_30_2_6', 'ten_c1_30_2', 'obscure', 'Overly technical language can obscure important findings, making scientific research less accessible to the public.', 'Overly technical language can obscure important findings, making scientific research less accessible to the public.', '/əbˈskjʊr/', 'Ngôn ngữ mang tính chuyên môn quá mức có thể làm mờ đi các phát hiện quan trọng, khiến công chúng khó tiếp cận các nghiên cứu khoa học hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_30_2_1', 'en-c1-30', 'ten_c1_30_2', 'listening', 'listening', 'Public transport must be affordable and reliable to become a viable alternative to private cars.', NULL, 'Trong câu vừa nghe, từ “viable” mang nghĩa nào sau đây?', '["thực thi được; khả thi","nhắc lại; nhấn mạnh lại; tái khẳng định","lớp phủ; tầng phủ (tuyết, sương,...)","quân đoàn; binh chủng"]'::jsonb, 0, '“viable” (/ˈvaɪəbl/): thực thi được; khả thi. Câu đầy đủ: Public transport must be affordable and reliable to become a viable alternative to private cars.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_30_2_2', 'en-c1-30', 'ten_c1_30_2', 'listening', 'listening', 'Researchers have drawn tentative conclusions, but further studies are needed before the treatment can be widely recommended.', NULL, 'Trong câu vừa nghe, từ “tentative” mang nghĩa nào sau đây?', '["bất lợi; gây khó khăn","mỏ đá; công trường khai thác đá","ngữ âm học","tạm thời; chưa chính thức"]'::jsonb, 3, '“tentative” (/ˈtentətɪv/): tạm thời; chưa chính thức. Câu đầy đủ: Researchers have drawn tentative conclusions, but further studies are needed before the treatment can be widely recommended.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
