INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_30_3', 'en-c1-30', 'en_to_vi', 'We took a pragmatic approach and repaired the old sofa.', 'We took a pragmatic approach and repaired the old sofa.', '/præɡˈmætɪk/', NULL, 'Chúng tôi đã áp dụng cách tiếp cận thực tế và sửa chữa chiếc ghế sofa cũ.', NULL, '["chúng","tôi","đã","áp","dụng","cách","tiếp","cận"]'::jsonb, 'Từ trọng tâm: pragmatic (thực tế; thực dụng; chú trọng hiệu quả thực tế)', 'We took a pragmatic approach and repaired the old sofa. → Chúng tôi đã áp dụng cách tiếp cận thực tế và sửa chữa chiếc ghế sofa cũ.', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_30_4', 'en-c1-30', 'en_to_vi', 'Our weekend trip never materialized because everyone was too busy.', 'Our weekend trip never materialized because everyone was too busy.', '/məˈtɪriəlaɪz/', NULL, 'Chuyến đi cuối tuần của chúng tôi rốt cuộc đã không thành hiện thực vì ai nấy đều quá bận rộn.', NULL, '["chuyến","đi","cuối","tuần","của","chúng","tôi","rốt"]'::jsonb, 'Từ trọng tâm: materialize (thành hiện thực; xảy ra; thành công)', 'Our weekend trip never materialized because everyone was too busy. → Chuyến đi cuối tuần của chúng tôi rốt cuộc đã không thành hiện thực vì ai nấy đều quá bận rộn.', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_30_5', 'en-c1-30', 'en_to_vi', 'A moment of inattention left the toast badly burnt.', 'A moment of inattention left the toast badly burnt.', '/ˌɪnəˈtenʃən/', NULL, 'Chỉ một phút lơ đễnh đã khiến bánh mì nướng bị cháy đen.', NULL, '["chỉ","một","phút","lơ","đễnh","đã","khiến","bánh"]'::jsonb, 'Từ trọng tâm: inattention (sự thiếu chú ý; sự lơ đễnh; sự mất tập trung)', 'A moment of inattention left the toast badly burnt. → Chỉ một phút lơ đễnh đã khiến bánh mì nướng bị cháy đen.', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
