INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_1', 'en-c1-30', NULL, 'comprehensive_test', 'listening', 'viable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mặc quần áo cho ai; cung cấp quần áo","thực thi được; khả thi","tận tâm; chu đáo; có ý thức trách nhiệm","nỗ lực; phấn đấu; cố gắng hết sức"]'::jsonb, 1, 'viable (/ˈvaɪəbl/) → thực thi được; khả thi; có thể sống được; phát triển được', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_2', 'en-c1-30', NULL, 'comprehensive_test', 'listening', 'We made tentative plans to visit the coast next weekend.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuộc trò chuyện của chúng tôi trở nên mang tính triết lý khi chúng tôi bàn về mục đích của cuộc sống.","Màu sơn chỉ là vấn đề phụ trong việc sửa chữa nhà bếp của chúng ta.","Chúng tôi đã lên kế hoạch tạm thời sẽ đi chơi biển vào cuối tuần tới.","Chúng tôi đã không lường trước được mọi hệ lụy của việc chuyển nhà đi quá xa."]'::jsonb, 2, 'We made tentative plans to visit the coast next weekend. → Chúng tôi đã lên kế hoạch tạm thời sẽ đi chơi biển vào cuối tuần tới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_3', 'en-c1-30', NULL, 'comprehensive_test', 'listening', 'nuance', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự đánh giá lại; sự xem xét lại","chính trực; đúng đắn về mặt đạo đức","tính thiết thực; công dụng","sắc thái; điểm tinh tế (trong ý nghĩa, cảm xúc, âm thanh hoặc diện mạo)"]'::jsonb, 3, 'nuance (/ˈnuːɑːns/) → sắc thái; điểm tinh tế (trong ý nghĩa, cảm xúc, âm thanh hoặc diện mạo)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_4', 'en-c1-30', NULL, 'comprehensive_test', 'listening', 'The sudden crash dazed me for a moment.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã áp dụng cách tiếp cận thực tế và sửa chữa chiếc ghế sofa cũ.","Cú va chạm bất ngờ khiến tôi choáng váng trong giây lát.","Thuê chung một căn hộ có vẻ là một lựa chọn khả thi.","Việc cùng nhau nấu ăn đã hé lộ một khía cạnh mới trong tính cách của cô ấy."]'::jsonb, 1, 'The sudden crash dazed me for a moment. → Cú va chạm bất ngờ khiến tôi choáng váng trong giây lát.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_5', 'en-c1-30', NULL, 'comprehensive_test', 'listening', 'criterion', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["một cách ngạo mạn; kiêu ngạo","cuộn lại; xoắn lại thành vòng","dễ tự ái; nhạy cảm","tiêu chí; chuẩn mực"]'::jsonb, 3, 'criterion (/kraɪˈtɪriən/) → tiêu chí; chuẩn mực', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_6', 'en-c1-30', NULL, 'comprehensive_test', 'listening', 'We found an obscure little museum behind the station.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã áp dụng cách tiếp cận thực tế và sửa chữa chiếc ghế sofa cũ.","Chúng tôi đã lên kế hoạch tạm thời sẽ đi chơi biển vào cuối tuần tới.","Chúng tôi đã tìm thấy một bảo tàng nhỏ ít ai biết đến nằm ở phía sau nhà ga.","Sau một hồi luyện tập, anh ấy đã đưa ra một lời giải thích rõ ràng và mạch lạc."]'::jsonb, 2, 'We found an obscure little museum behind the station. → Chúng tôi đã tìm thấy một bảo tàng nhỏ ít ai biết đến nằm ở phía sau nhà ga.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_7', 'en-c1-30', NULL, 'comprehensive_test', 'listening', 'inconsistency', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xâm phạm; đột nhập trái phép vào đất (hoặc tài sản) của người khác","bảo vệ; bảo đảm","đa năng; linh hoạt, nhiều công dụng","sự mâu thuẫn; sự bất nhất"]'::jsonb, 3, 'inconsistency (/ˌɪnkənˈsɪstənsi/) → sự mâu thuẫn; sự bất nhất; sự bất ổn; tính thất thường', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_8', 'en-c1-30', NULL, 'comprehensive_test', 'listening', 'Our articulate neighbour explained the problem clearly at dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chỉ một phút lơ đễnh đã khiến bánh mì nướng bị cháy đen.","Cô ấy đắn đo suy nghĩ một lúc trước khi gọi món súp rau củ.","Người hàng xóm ăn nói lưu loát của chúng tôi đã giải thích vấn đề rất rõ ràng vào bữa tối.","Giọng nói của anh ấy có một chút run rẩy gần như không thể nhận ra."]'::jsonb, 2, 'Our articulate neighbour explained the problem clearly at dinner. → Người hàng xóm ăn nói lưu loát của chúng tôi đã giải thích vấn đề rất rõ ràng vào bữa tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_9', 'en-c1-30', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A standard used to judge something or make a decision.”?', '["criterion","coherent","nuance","viable"]'::jsonb, 0, 'criterion (/kraɪˈtɪriən/) → tiêu chí; chuẩn mực', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_10', 'en-c1-30', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Not known by many people”?', '["essence","detract","peripheral","obscure"]'::jsonb, 3, 'obscure (/əbˈskjʊr/) → ít tên tuổi; ít người biết đến', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_11', 'en-c1-30', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a lack of agreement between facts, statements, or actions”?', '["inconsistency","situational","essence","facet"]'::jsonb, 0, 'inconsistency (/ˌɪnkənˈsɪstənsi/) → sự mâu thuẫn; sự bất nhất', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_12', 'en-c1-30', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “able to express ideas clearly and effectively”?', '["articulate","loom","daze","detract"]'::jsonb, 0, 'articulate (/ɑːrˈtɪkjələt/) → lưu loát; ăn nói rõ ràng', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_13', 'en-c1-30', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Choosing what works in practice rather than following ideals.”?', '["essence","ramification","pragmatic","intrigue"]'::jsonb, 2, 'pragmatic (/præɡˈmætɪk/) → thực tế; thực dụng; chú trọng hiệu quả thực tế', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
