INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_18', 'en-c1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Public transport must be affordable and reliable to become a viable alternative to private cars.', 'Dựa vào câu trên, từ “viable” có nghĩa phù hợp nhất là gì?', '["sự khởi đầu; sự bắt đầu","thực thi được; khả thi","sự khinh miệt; sự coi thường","gợi lên; gợi nhớ; đánh thức"]'::jsonb, 1, 'viable: thực thi được; khả thi; có thể sống được; phát triển được. Dịch cả câu: Giao thông công cộng phải có giá cả phải chăng và đáng tin cậy để có thể trở thành sự thay thế khả thi cho xe hơi cá nhân.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_19', 'en-c1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers have drawn tentative conclusions, but further studies are needed before the treatment can be widely recommended.', 'Dựa vào câu trên, từ “tentative” có nghĩa phù hợp nhất là gì?', '["hệ quả phụ, hệ lụy, tác động nhánh (thường là phức tạp hoặc bất ngờ phát sinh từ một hành động hay quyết định)","tạm thời; chưa chính thức","kẻ hà tiện; người keo kiệt","vua hoặc nữ hoàng đóng vai trò là nguyên thủ quốc gia"]'::jsonb, 1, 'tentative: tạm thời; chưa chính thức; dè dặt; mang tính thử nghiệm; do dự. Dịch cả câu: Các nhà nghiên cứu đã đưa ra những kết luận ban đầu, nhưng cần phải có thêm nhiều nghiên cứu trước khi phương pháp điều trị này có thể được khuyến khích rộng rãi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_20', 'en-c1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Language learners need cultural knowledge to recognise nuances that dictionaries may not fully explain.', 'Dựa vào câu trên, từ “nuance” có nghĩa phù hợp nhất là gì?', '["bản sao; bản phụ","sắc thái; điểm tinh tế (trong ý nghĩa, cảm xúc, âm thanh hoặc diện mạo)","không thấm nước; chống nước; kín nước","cải tiến; trau chuốt; hoàn thiện"]'::jsonb, 1, 'nuance: sắc thái; điểm tinh tế (trong ý nghĩa, cảm xúc, âm thanh hoặc diện mạo). Dịch cả câu: Người học ngoại ngữ cần có kiến thức văn hóa để nhận biết những sắc thái tinh tế mà từ điển có thể không giải thích hết được.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_21', 'en-c1-30', NULL, 'comprehensive_test', 'reading', NULL, 'After several nights of poor sleep, employees may work in a daze and make avoidable mistakes.', 'Dựa vào câu trên, từ “daze” có nghĩa phù hợp nhất là gì?', '["sự phủ định; sự phủ nhận","thuộc về thành phố; thuộc về đô thị; cấp thành phố","làm choáng váng; làm mơ màng","một thói quen hoặc đặc điểm khác thường; tật nhỏ, nét kỳ quặc"]'::jsonb, 2, 'daze: làm choáng váng; làm mơ màng; trạng thái bần thần; trạng thái mơ màng. Dịch cả câu: Sau vài đêm ngủ không đủ giấc, nhân viên có thể làm việc trong trạng thái bần thần và vướng phải những lỗi lầm có thể tránh được.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_22', 'en-c1-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hệ quả phụ, hệ lụy, tác động nhánh (thường là phức tạp hoặc bất ngờ phát sinh từ một hành động hay quyết định)”', '["indifferent","obsess","gratify","ramification"]'::jsonb, 3, 'hệ quả phụ, hệ lụy, tác động nhánh (thường là phức tạp hoặc bất ngờ phát sinh từ một hành động hay quyết định) → ramification (/ˌræmɪfɪˈkeɪʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_23', 'en-c1-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khơi gợi sự tò mò; làm thích thú”', '["know-how","intrigue","shelve","discrepancy"]'::jsonb, 1, 'khơi gợi sự tò mò; làm thích thú → intrigue (/ɪnˈtriːɡ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_30_24', 'en-c1-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bản chất; cốt lõi; tinh hoa”', '["chisel","essence","commonsense","ailment"]'::jsonb, 1, 'bản chất; cốt lõi; tinh hoa → essence (/ˈesəns/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-31', 'en', 'Bài 31: Tư duy & Nhận thức (6) - CEFR C1', 'CEFR C1', 'C1 · Tư duy', '25 từ vựng Tiếng Anh CEFR C1 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5031, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commonsense', 'en-c1-31', 'commonsense', '/ˌkɑːmənˈsens/', 'C1', 'phù hợp với lẽ phải thông thường; thực tế và hợp lý', 'adj.', 'common sense (n.)', 'Đồng nghĩa: sensible, practical · Trái nghĩa: impractical', 'Tính từ này đôi khi cũng được viết là common-sense; trong khi danh từ common sense được viết tách thành hai từ.', 'Taking an umbrella was a commonsense decision in this weather.', NULL, 'Mang theo ô là một quyết định rất hợp lý trong kiểu thời tiết này.', '{"wordId":"commonsense","ukIpa":"/ˌkɒmənˈsens/","usIpa":"/ˌkɑːmənˈsens/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Showing practical judgment based on ordinary experience.","vi":"phù hợp với lẽ phải thông thường; thực tế và hợp lý"}],"examples":[{"en":"Taking an umbrella was a commonsense decision in this weather.","vi":"Mang theo ô là một quyết định rất hợp lý trong kiểu thời tiết này.","audioKind":"ex"},{"en":"Simple commonsense measures, such as improving street lighting, can make residential areas safer for pedestrians.","vi":"Các biện pháp thực tế đơn giản, chẳng hạn như cải thiện hệ thống đèn đường, có thể giúp khu dân cư trở nên an toàn hơn cho người đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"a commonsense approach","vi":"một phương pháp tiếp cận thực tế"},{"en":"commonsense advice","vi":"lời khuyên hợp tình hợp lý"},{"en":"commonsense precautions","vi":"các biện pháp phòng ngừa theo lẽ thông thường"}],"wordFamily":["common sense (n.)"],"synonyms":["sensible","practical"],"antonyms":["impractical"],"tipVi":"Tính từ này đôi khi cũng được viết là common-sense; trong khi danh từ common sense được viết tách thành hai từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heed', 'en-c1-31', 'heed', '/hiːd/', 'C1', 'chú ý; lắng nghe và làm theo; sự chú ý; sự lưu tâm', 'v.', 'heedful (adj.), heedless (adj.)', 'Trái nghĩa: ignore, disregard', 'Động từ trực tiếp nhận tân ngữ; danh từ thường dùng trong cấu trúc pay heed to.', 'We heeded the guide''s warning and left the beach.', NULL, 'Chúng tôi đã nghe theo cảnh báo của hướng dẫn viên và rời khỏi bãi biển.', '{"wordId":"heed","ukIpa":"/hiːd/","usIpa":"/hiːd/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To pay careful attention to advice or a warning.","vi":"chú ý; lắng nghe và làm theo"},{"pos":"n.","en":"Careful attention given to something, especially advice or warnings.","vi":"sự chú ý; sự lưu tâm"}],"examples":[{"en":"We heeded the guide''s warning and left the beach.","vi":"Chúng tôi đã nghe theo cảnh báo của hướng dẫn viên và rời khỏi bãi biển.","audioKind":"ex"},{"en":"Governments must heed scientific advice when developing policies to protect communities from extreme weather.","vi":"Các chính phủ phải chú ý đến các khuyến nghị khoa học khi xây dựng chính sách nhằm bảo vệ cộng đồng trước các hiện tượng thời tiết cực đoan.","audioKind":"ex2"}],"collocations":[{"en":"heed a warning","vi":"lắng nghe cảnh báo"},{"en":"heed advice","vi":"lắng nghe lời khuyên"},{"en":"pay heed to","vi":"chú ý đến"},{"en":"take heed of","vi":"lưu tâm đến"}],"wordFamily":["heedful (adj.)","heedless (adj.)"],"synonyms":[],"antonyms":["ignore","disregard"],"tipVi":"Động từ trực tiếp nhận tân ngữ; danh từ thường dùng trong cấu trúc pay heed to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hallmark', 'en-c1-31', 'hallmark', '/ˈhɔːlmɑːrk/', 'C1', 'dấu ấn; nét đặc trưng; đặc điểm tiêu biểu; dấu kiểm định (vàng bạc, kim loại quý)', 'n.', NULL, 'Đồng nghĩa: characteristic, feature', 'Thường dùng cấu trúc a hallmark of để chỉ nét đặc trưng của cái gì.', 'Fresh ingredients are the hallmark of my grandmother''s cooking.', NULL, 'Nguyên liệu tươi ngon là nét đặc trưng trong cách nấu ăn của bà tôi.', '{"wordId":"hallmark","ukIpa":"/ˈhɔːlmɑːk/","usIpa":"/ˈhɔːlmɑːrk/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A distinctive quality that characterises someone or something","vi":"dấu ấn; nét đặc trưng; đặc điểm tiêu biểu"},{"pos":"n.","en":"An official mark showing the purity of a precious metal","vi":"dấu kiểm định (vàng bạc, kim loại quý)"}],"examples":[{"en":"Fresh ingredients are the hallmark of my grandmother''s cooking.","vi":"Nguyên liệu tươi ngon là nét đặc trưng trong cách nấu ăn của bà tôi.","audioKind":"ex"},{"en":"Transparent decision-making is a hallmark of effective governance because it allows citizens to hold public officials accountable.","vi":"Quyết định minh bạch là dấu ấn của một nền quản trị hiệu quả vì nó cho phép người dân quy trách nhiệm cho các quan chức công quyền.","audioKind":"ex2"}],"collocations":[{"en":"a hallmark of quality","vi":"dấu hiệu của chất lượng"},{"en":"bear the hallmarks of","vi":"mang dấu ấn của"},{"en":"a distinctive hallmark","vi":"một đặc điểm riêng biệt"}],"wordFamily":[],"synonyms":["characteristic","feature"],"antonyms":[],"tipVi":"Thường dùng cấu trúc a hallmark of để chỉ nét đặc trưng của cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decided', 'en-c1-31', 'decided', '/dɪˈsaɪdɪd/', 'C1', 'rõ ràng, dứt khoát, dễ nhận thấy', 'adj.', 'decide (v.), decision (n.), decidedly (adv.), decisive (adj.)', 'Đồng nghĩa: definite, clear, distinct · Trái nghĩa: uncertain', 'Tính từ thường chỉ "rõ ràng"; từ "quả quyết" thường dùng decisive.', 'There is a decided chill in the air tonight.', NULL, 'Đêm nay không khí có một cái lạnh rõ rệt.', '{"wordId":"decided","ukIpa":"/dɪˈsaɪdɪd/","usIpa":"/dɪˈsaɪdɪd/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"clear, definite, and easy to notice","vi":"rõ ràng, dứt khoát, dễ nhận thấy"}],"examples":[{"en":"There is a decided chill in the air tonight.","vi":"Đêm nay không khí có một cái lạnh rõ rệt.","audioKind":"ex"},{"en":"Reliable internet access gives rural businesses a decided advantage when competing for customers beyond their local area.","vi":"Truy cập Internet đáng tin cậy mang lại cho các doanh nghiệp nông thôn một lợi thế rõ rệt khi cạnh tranh giành khách hàng ngoài khu vực địa phương của họ.","audioKind":"ex2"}],"collocations":[{"en":"a decided advantage","vi":"lợi thế rõ rệt"},{"en":"a decided improvement","vi":"sự cải thiện rõ rệt"},{"en":"a decided preference","vi":"sự ưu tiên rõ ràng"}],"wordFamily":["decide (v.)","decision (n.)","decidedly (adv.)","decisive (adj.)"],"synonyms":["definite","clear","distinct"],"antonyms":["uncertain"],"tipVi":"Tính từ thường chỉ \"rõ ràng\"; từ \"quả quyết\" thường dùng decisive.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_visualize', 'en-c1-31', 'visualize', '/ˈvɪʒuəlaɪz/', 'C1', 'hình dung; tưởng tượng; trực quan hóa', 'v.', 'visualization (n.), visual (adj.), visually (adv.)', 'Đồng nghĩa: envision, picture, imagine', 'Cách viết tiếng Anh-Anh là visualise; có thể đi với danh từ hoặc danh động từ.', 'Close your eyes and visualize a quiet sandy beach.', NULL, 'Hãy nhắm mắt lại và hình dung một bãi biển cát yên tĩnh.', '{"wordId":"visualize","ukIpa":"/ˈvɪʒuəlaɪz/","usIpa":"/ˈvɪʒuəlaɪz/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To form a clear picture of something in your mind.","vi":"hình dung; tưởng tượng"},{"pos":"v.","en":"To represent information using images, charts, or diagrams.","vi":"trực quan hóa"}],"examples":[{"en":"Close your eyes and visualize a quiet sandy beach.","vi":"Hãy nhắm mắt lại và hình dung một bãi biển cát yên tĩnh.","audioKind":"ex"},{"en":"Digital models help residents visualize how proposed buildings will change the appearance of their neighbourhood.","vi":"Các mô hình kỹ thuật số giúp cư dân hình dung cách các tòa nhà được đề xuất sẽ thay đổi diện mạo khu phố của họ.","audioKind":"ex2"}],"collocations":[{"en":"visualize a scene","vi":"hình dung một khung cảnh"},{"en":"visualize data","vi":"trực quan hóa dữ liệu"},{"en":"visualize the outcome","vi":"hình dung kết quả"}],"wordFamily":["visualization (n.)","visual (adj.)","visually (adv.)"],"synonyms":["envision","picture","imagine"],"antonyms":[],"tipVi":"Cách viết tiếng Anh-Anh là visualise; có thể đi với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embody', 'en-c1-31', 'embody', '/ɪmˈbɑːdi/', 'C1', 'thể hiện; hiện thân; bao gồm; tích hợp', 'v.', 'embodiment (n.)', 'Đồng nghĩa: represent, incorporate', 'embody là ngoại động từ, đi thẳng đến phẩm chất hoặc ý tưởng được thể hiện.', 'These handmade bowls embody my grandmother''s patience and care.', NULL, 'Những chiếc bát thủ công này thể hiện sự kiên nhẫn và tận tâm của bà tôi.', '{"wordId":"embody","ukIpa":"/ɪmˈbɒdi/","usIpa":"/ɪmˈbɑːdi/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To clearly represent an idea, quality, or feeling.","vi":"thể hiện; hiện thân"},{"pos":"v.","en":"To include something as part of a larger whole.","vi":"bao gồm; tích hợp"}],"examples":[{"en":"These handmade bowls embody my grandmother''s patience and care.","vi":"Những chiếc bát thủ công này thể hiện sự kiên nhẫn và tận tâm của bà tôi.","audioKind":"ex"},{"en":"Public buildings should embody the values of inclusion by providing accessible spaces for people with different needs.","vi":"Các công trình công cộng nên thể hiện các giá trị hòa nhập bằng cách cung cấp không gian dễ tiếp cận cho những người có nhu cầu khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"embody an ideal","vi":"thể hiện một lý tưởng"},{"en":"embody the spirit of","vi":"thể hiện tinh thần của"},{"en":"embody core values","vi":"thể hiện các giá trị cốt lõi"}],"wordFamily":["embodiment (n.)"],"synonyms":["represent","incorporate"],"antonyms":[],"tipVi":"embody là ngoại động từ, đi thẳng đến phẩm chất hoặc ý tưởng được thể hiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entirety', 'en-c1-31', 'entirety', '/ɪnˈtaɪrəti/', 'C1', 'toàn bộ; tính toàn vẹn', 'n.', 'entire (adj.), entirely (adv.)', 'Đồng nghĩa: whole, totality', 'Thường dùng in its entirety, biểu thị ý nghĩa trọn vẹn, không bỏ sót phần nào.', 'We watched the long film in its entirety.', NULL, 'Chúng tôi đã xem toàn bộ bộ phim dài tập đó.', '{"wordId":"entirety","ukIpa":"/ɪnˈtaɪərəti/","usIpa":"/ɪnˈtaɪrəti/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"the whole of something, with no part left out","vi":"toàn bộ; tính toàn vẹn"}],"examples":[{"en":"We watched the long film in its entirety.","vi":"Chúng tôi đã xem toàn bộ bộ phim dài tập đó.","audioKind":"ex"},{"en":"Researchers should examine the report in its entirety before drawing conclusions about the effectiveness of the programme.","vi":"Các nhà nghiên cứu nên xem xét kỹ lưỡng toàn bộ báo cáo trước khi đưa ra kết luận về hiệu quả của chương trình.","audioKind":"ex2"}],"collocations":[{"en":"in its entirety","vi":"toàn vẹn; đầy đủ"},{"en":"the entirety of","vi":"toàn bộ của"}],"wordFamily":["entire (adj.)","entirely (adv.)"],"synonyms":["whole","totality"],"antonyms":[],"tipVi":"Thường dùng in its entirety, biểu thị ý nghĩa trọn vẹn, không bỏ sót phần nào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shrewd', 'en-c1-31', 'shrewd', '/ʃruːd/', 'C1', 'sáng suốt; tinh ranh; sắc sảo', 'adj.', 'shrewdly (adv.), shrewdness (n.)', 'Đồng nghĩa: astute, perceptive · Trái nghĩa: naive', 'Nhấn mạnh sự phán đoán sắc sảo, khôn ngoan để mưu lợi, không đồng nghĩa với sự thông minh đơn thuần.', 'That shrewd purchase saved us money on heating.', NULL, 'Quyết định mua sắm sáng suốt đó đã giúp chúng tôi tiết kiệm được tiền sưởi ấm.', '{"wordId":"shrewd","ukIpa":"/ʃruːd/","usIpa":"/ʃruːd/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"good at judging situations and making decisions that bring advantages","vi":"sáng suốt; tinh ranh; sắc sảo"}],"examples":[{"en":"That shrewd purchase saved us money on heating.","vi":"Quyết định mua sắm sáng suốt đó đã giúp chúng tôi tiết kiệm được tiền sưởi ấm.","audioKind":"ex"},{"en":"Shrewd investment in renewable energy can help governments reduce future costs while improving national energy security.","vi":"Việc đầu tư khôn ngoan vào năng lượng tái tạo có thể giúp chính phủ giảm chi phí trong tương lai đồng thời nâng cao an ninh năng lượng quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"a shrewd investor","vi":"nhà đầu tư tinh ranh"},{"en":"a shrewd judgement","vi":"nhận định sắc sảo"},{"en":"a shrewd investment","vi":"khoản đầu tư sáng suốt"}],"wordFamily":["shrewdly (adv.)","shrewdness (n.)"],"synonyms":["astute","perceptive"],"antonyms":["naive"],"tipVi":"Nhấn mạnh sự phán đoán sắc sảo, khôn ngoan để mưu lợi, không đồng nghĩa với sự thông minh đơn thuần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plausible', 'en-c1-31', 'plausible', '/ˈplɔːzəbl/', 'C1', 'hợp lý; có vẻ hợp lý', 'adj.', 'plausibility (n.), plausibly (adv.), implausible (adj.)', 'Đồng nghĩa: believable, credible · Trái nghĩa: implausible, unbelievable', 'Diễn tả việc nghe có vẻ hợp lý, không đảm bảo là đúng sự thật, cũng không nhất thiết ngụ ý là giả dối.', 'His explanation sounded plausible, but I still checked.', NULL, 'Lời giải thích của anh ấy nghe có vẻ hợp lý, nhưng tôi vẫn kiểm tra lại.', '{"wordId":"plausible","ukIpa":"/ˈplɔːzəbl/","usIpa":"/ˈplɔːzəbl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Seeming reasonable or likely to be true","vi":"hợp lý; có vẻ hợp lý"}],"examples":[{"en":"His explanation sounded plausible, but I still checked.","vi":"Lời giải thích của anh ấy nghe có vẻ hợp lý, nhưng tôi vẫn kiểm tra lại.","audioKind":"ex"},{"en":"Although remote working offers a plausible solution to congestion, its long-term effects require further investigation.","vi":"Mặc dù làm việc từ xa mang lại một giải pháp hợp lý cho tình trạng tắc nghẽn, nhưng các tác động lâu dài của nó vẫn cần được nghiên cứu thêm.","audioKind":"ex2"}],"collocations":[{"en":"plausible explanation","vi":"lời giải thích hợp lý"},{"en":"plausible excuse","vi":"cái cớ nghe có vẻ hợp lý"},{"en":"plausible solution","vi":"giải pháp có vẻ khả thi"}],"wordFamily":["plausibility (n.)","plausibly (adv.)","implausible (adj.)"],"synonyms":["believable","credible"],"antonyms":["implausible","unbelievable"],"tipVi":"Diễn tả việc nghe có vẻ hợp lý, không đảm bảo là đúng sự thật, cũng không nhất thiết ngụ ý là giả dối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ingenuity', 'en-c1-31', 'ingenuity', '/ˌɪndʒəˈnuːəti/', 'C1', 'tài khéo léo; sự sáng tạo; sự tinh tế', 'n.', 'ingenious (adj.), ingeniously (adv.)', 'Đồng nghĩa: inventiveness, resourcefulness', 'Tương ứng với tính từ ingenious; đừng nhầm lẫn với từ ingenuous có nghĩa là ngây thơ, chân thật.', 'With some ingenuity, Lina turned old crates into shelves.', NULL, 'Với một chút khéo léo, Lina đã biến những chiếc thùng gỗ cũ thành các giá sách.', '{"wordId":"ingenuity","ukIpa":"/ˌɪndʒəˈnjuːəti/","usIpa":"/ˌɪndʒəˈnuːəti/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"the ability to solve problems in clever, original ways","vi":"tài khéo léo; sự sáng tạo; sự tinh tế"}],"examples":[{"en":"With some ingenuity, Lina turned old crates into shelves.","vi":"Với một chút khéo léo, Lina đã biến những chiếc thùng gỗ cũ thành các giá sách.","audioKind":"ex"},{"en":"Human ingenuity can help communities develop affordable solutions to water shortages using locally available materials.","vi":"Sự sáng tạo của con người có thể giúp các cộng đồng phát triển các giải pháp chi phí hợp lý để đối phó với tình trạng thiếu nước bằng cách sử dụng các vật liệu sẵn có tại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"human ingenuity","vi":"sự sáng tạo của con người"},{"en":"show ingenuity","vi":"thể hiện sự khéo léo"},{"en":"a feat of ingenuity","vi":"một kỳ tích đầy sáng tạo"}],"wordFamily":["ingenious (adj.)","ingeniously (adv.)"],"synonyms":["inventiveness","resourcefulness"],"antonyms":[],"tipVi":"Tương ứng với tính từ ingenious; đừng nhầm lẫn với từ ingenuous có nghĩa là ngây thơ, chân thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intent', 'en-c1-31', 'intent', '/ɪnˈtent/', 'C1', 'ý định; mục đích; chăm chú; tập trung cao độ; quyết tâm; kiên quyết làm gì', 'n.', 'intend (v.), intention (n.), intentional (adj.), intently (adv.)', 'Đồng nghĩa: purpose, intention', 'intent on đi với danh từ hoặc danh động từ, biểu thị sự tập trung hoặc quyết tâm cao độ.', 'My intent was to help, not to interrupt you.', NULL, 'Ý định của tôi là giúp đỡ chứ không phải làm phiền bạn.', '{"wordId":"intent","ukIpa":"/ɪnˈtent/","usIpa":"/ɪnˈtent/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"What someone plans or means to do.","vi":"ý định; mục đích"},{"pos":"adj.","en":"Giving all your attention to something.","vi":"chăm chú; tập trung cao độ"},{"pos":"adj.","en":"Firmly determined to do or achieve something.","vi":"quyết tâm; kiên quyết làm gì"}],"examples":[{"en":"My intent was to help, not to interrupt you.","vi":"Ý định của tôi là giúp đỡ chứ không phải làm phiền bạn.","audioKind":"ex"},{"en":"Many governments are intent on reducing traffic congestion through investment in reliable public transport.","vi":"Nhiều chính phủ đang quyết tâm giảm thiểu tình trạng ùn tắc giao thông thông qua việc đầu tư vào hệ thống giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"with the intent of","vi":"với mục đích"},{"en":"intent on doing something","vi":"quyết tâm làm gì"},{"en":"an intent gaze","vi":"cái nhìn chăm chú"},{"en":"a statement of intent","vi":"tuyên ngôn ý định"}],"wordFamily":["intend (v.)","intention (n.)","intentional (adj.)","intently (adv.)"],"synonyms":["purpose","intention"],"antonyms":[],"tipVi":"intent on đi với danh từ hoặc danh động từ, biểu thị sự tập trung hoặc quyết tâm cao độ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delude', 'en-c1-31', 'delude', '/dɪˈluːd/', 'C1', 'đánh lừa; lừa dối; khiến ai đó ảo tưởng', 'v.', 'delusion (n.), deluded (adj.), delusional (adj.)', 'Đồng nghĩa: deceive, mislead', 'Thường dùng cấu trúc delude oneself into doing với ý nghĩa tự lừa mình dối người làm việc gì đó.', 'Don''t delude yourself into thinking the work is finished.', NULL, 'Đừng tự lừa dối bản thân rằng công việc đã hoàn thành.', '{"wordId":"delude","ukIpa":"/dɪˈluːd/","usIpa":"/dɪˈluːd/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"Make someone believe something that is not true.","vi":"đánh lừa; lừa dối; khiến ai đó ảo tưởng"}],"examples":[{"en":"Don''t delude yourself into thinking the work is finished.","vi":"Đừng tự lừa dối bản thân rằng công việc đã hoàn thành.","audioKind":"ex"},{"en":"Policymakers should not delude themselves into believing that economic growth alone will eliminate poverty and social inequality.","vi":"Các nhà hoạch định chính sách không nên tự lừa dối mình khi cho rằng chỉ riêng tăng trưởng kinh tế có thể xóa bỏ đói nghèo và bất công xã hội.","audioKind":"ex2"}],"collocations":[{"en":"delude yourself","vi":"tự lừa dối bản thân"},{"en":"delude someone into believing","vi":"lừa phỉnh ai đó tin điều gì"}],"wordFamily":["delusion (n.)","deluded (adj.)","delusional (adj.)"],"synonyms":["deceive","mislead"],"antonyms":[],"tipVi":"Thường dùng cấu trúc delude oneself into doing với ý nghĩa tự lừa mình dối người làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dubious', 'en-c1-31', 'dubious', '/ˈduːbiəs/', 'C1', 'hoài nghi; ngờ vực; phân vân; mờ ám; đáng ngờ; không đáng tin cậy', 'adj.', 'dubiously (adv.), dubiousness (n.)', 'Đồng nghĩa: doubtful, sceptical, questionable · Trái nghĩa: certain', 'Cảm giác hoài nghi dùng dubious about; sự việc có tính đáng ngờ cũng dùng dubious.', 'I felt dubious about buying a bicycle without brakes.', NULL, 'Tôi cảm thấy hoài nghi về việc mua một chiếc xe đạp không có phanh.', '{"wordId":"dubious","ukIpa":"/ˈdjuːbiəs/","usIpa":"/ˈduːbiəs/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"feeling uncertain or doubtful about something","vi":"hoài nghi; ngờ vực; phân vân"},{"pos":"adj.","en":"probably dishonest, unsafe, or not worth trusting","vi":"mờ ám; đáng ngờ; không đáng tin cậy"}],"examples":[{"en":"I felt dubious about buying a bicycle without brakes.","vi":"Tôi cảm thấy hoài nghi về việc mua một chiếc xe đạp không có phanh.","audioKind":"ex"},{"en":"Consumers should remain dubious about health claims that are not supported by reliable scientific evidence.","vi":"Người tiêu dùng nên duy trì sự hoài nghi đối với các tuyên bố về sức khỏe không được hỗ trợ bởi bằng chứng khoa học đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"dubious about","vi":"hoài nghi về"},{"en":"dubious claims","vi":"những tuyên bố đáng ngờ"},{"en":"of dubious value","vi":"giá trị đáng ngờ"},{"en":"dubious practices","vi":"những việc làm mờ ám"}],"wordFamily":["dubiously (adv.)","dubiousness (n.)"],"synonyms":["doubtful","sceptical","questionable"],"antonyms":["certain"],"tipVi":"Cảm giác hoài nghi dùng dubious about; sự việc có tính đáng ngờ cũng dùng dubious.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_variance', 'en-c1-31', 'variance', '/ˈveriəns/', 'C1', 'sự khác biệt; sự mâu thuẫn; sự bất đồng; phương sai', 'n.', 'vary (v.), variation (n.), variable (adj.), varied (adj.)', 'Đồng nghĩa: difference, discrepancy', 'Cụm at variance with diễn tả sự bất nhất, mâu thuẫn; trong thống kê dùng chỉ phương sai.', 'His cheerful smile was at variance with his complaints.', NULL, 'Nụ cười rạng rỡ của anh ấy hoàn toàn mâu thuẫn với những lời phàn nàn của anh ấy.', '{"wordId":"variance","ukIpa":"/ˈveəriəns/","usIpa":"/ˈveriəns/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"A difference or disagreement between things.","vi":"sự khác biệt; sự mâu thuẫn; sự bất đồng"},{"pos":"n.","en":"A statistical measure of how widely values differ from their mean.","vi":"phương sai"}],"examples":[{"en":"His cheerful smile was at variance with his complaints.","vi":"Nụ cười rạng rỡ của anh ấy hoàn toàn mâu thuẫn với những lời phàn nàn của anh ấy.","audioKind":"ex"},{"en":"The proposed housing policy is at variance with the government''s commitment to protecting green spaces.","vi":"Chính sách nhà ở được đề xuất mâu thuẫn với cam kết bảo vệ không gian xanh của chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"at variance with","vi":"mâu thuẫn với"},{"en":"variance between groups","vi":"sự khác biệt giữa các nhóm"},{"en":"population variance","vi":"phương sai tổng thể"}],"wordFamily":["vary (v.)","variation (n.)","variable (adj.)","varied (adj.)"],"synonyms":["difference","discrepancy"],"antonyms":[],"tipVi":"Cụm at variance with diễn tả sự bất nhất, mâu thuẫn; trong thống kê dùng chỉ phương sai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accordingly', 'en-c1-31', 'accordingly', '/əˈkɔːrdɪŋli/', 'C1', 'tương ứng; phù hợp với hoàn cảnh; do đó; vì vậy; theo đó', 'adv.', 'accord (v.), accordance (n.)', NULL, 'Mang nghĩa "tương ứng" thường đứng cuối câu; mang nghĩa "do đó" có văn phong trang trọng hơn.', 'The forecast predicted rain, so we dressed accordingly.', NULL, 'Dự báo thời tiết có mưa nên chúng tôi đã ăn mặc phù hợp.', '{"wordId":"accordingly","ukIpa":"/əˈkɔːdɪŋli/","usIpa":"/əˈkɔːrdɪŋli/","cefr":"C1","topic":"thinking","senses":[{"pos":"adv.","en":"in a way that suits the particular situation","vi":"tương ứng; phù hợp với hoàn cảnh"},{"pos":"adv.","en":"as a result of something","vi":"do đó; vì vậy; theo đó"}],"examples":[{"en":"The forecast predicted rain, so we dressed accordingly.","vi":"Dự báo thời tiết có mưa nên chúng tôi đã ăn mặc phù hợp.","audioKind":"ex"},{"en":"Schools should identify individual learning needs and adjust their teaching methods accordingly to support every student.","vi":"Các trường học nên xác định nhu cầu học tập cá nhân và điều chỉnh phương pháp giảng dạy tương ứng để hỗ trợ mọi học sinh.","audioKind":"ex2"}],"collocations":[{"en":"adjust accordingly","vi":"điều chỉnh phù hợp"},{"en":"act accordingly","vi":"hành động theo đó"},{"en":"plan accordingly","vi":"lên kế hoạch phù hợp"}],"wordFamily":["accord (v.)","accordance (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Mang nghĩa \"tương ứng\" thường đứng cuối câu; mang nghĩa \"do đó\" có văn phong trang trọng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lesser', 'en-c1-31', 'lesser', '/ˈlesər/', 'C1', 'nhỏ hơn, ít hơn, kém quan trọng hơn', 'adj.', 'less (adv.), less (det.)', 'Đồng nghĩa: smaller, minor · Trái nghĩa: greater', 'Thường đứng trước danh từ; không dùng để chỉ kích thước vật lý nhỏ hơn.', 'We chose the lesser expense of repairing our sofa.', NULL, 'Chúng tôi đã chọn phương án sửa chữa chiếc ghế sofa với chi phí thấp hơn.', '{"wordId":"lesser","ukIpa":"/ˈlesə/","usIpa":"/ˈlesər/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Smaller in amount, degree, or importance","vi":"nhỏ hơn, ít hơn, kém quan trọng hơn"}],"examples":[{"en":"We chose the lesser expense of repairing our sofa.","vi":"Chúng tôi đã chọn phương án sửa chữa chiếc ghế sofa với chi phí thấp hơn.","audioKind":"ex"},{"en":"Although funding matters, class size also influences educational outcomes, but usually to a lesser degree.","vi":"Mặc dù nguồn tài chính rất quan trọng, quy mô lớp học cũng ảnh hưởng đến kết quả giáo dục, nhưng thường ở mức độ nhỏ hơn.","audioKind":"ex2"}],"collocations":[{"en":"to a lesser extent","vi":"ở mức độ ít hơn"},{"en":"of lesser importance","vi":"kém quan trọng hơn"},{"en":"the lesser of two evils","vi":"cái ít tệ hơn trong hai điều tệ"}],"wordFamily":["less (adv.)","less (det.)"],"synonyms":["smaller","minor"],"antonyms":["greater"],"tipVi":"Thường đứng trước danh từ; không dùng để chỉ kích thước vật lý nhỏ hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_err', 'en-c1-31', 'err', '/ɝː/', 'C1', 'phạm lỗi, sai lầm, phán đoán sai', 'v.', 'error (n.), erroneous (adj.), erroneously (adv.)', 'Đồng nghĩa: make a mistake, misjudge', 'Là động từ nội động từ mang tính trang trọng; thường dùng cụm err on the side of caution.', 'I erred by leaving the cake in too long.', NULL, 'Tôi đã sai lầm khi để chiếc bánh trong lò quá lâu.', '{"wordId":"err","ukIpa":"/ɜː/","usIpa":"/ɝː/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"To make a mistake or an incorrect judgement.","vi":"phạm lỗi, sai lầm, phán đoán sai"}],"examples":[{"en":"I erred by leaving the cake in too long.","vi":"Tôi đã sai lầm khi để chiếc bánh trong lò quá lâu.","audioKind":"ex"},{"en":"Policymakers may err when they assume that economic growth automatically improves everyone''s quality of life.","vi":"Các nhà hoạch định chính sách có thể phán đoán sai khi cho rằng tăng trưởng kinh tế sẽ tự động cải thiện chất lượng cuộc sống của mọi người.","audioKind":"ex2"}],"collocations":[{"en":"err in judgement","vi":"phán đoán sai lầm"},{"en":"err on the side of caution","vi":"thận trọng vẫn hơn"},{"en":"err in assuming","vi":"sai lầm khi cho rằng"}],"wordFamily":["error (n.)","erroneous (adj.)","erroneously (adv.)"],"synonyms":["make a mistake","misjudge"],"antonyms":[],"tipVi":"Là động từ nội động từ mang tính trang trọng; thường dùng cụm err on the side of caution.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obsess', 'en-c1-31', 'obsess', '/əbˈses/', 'C1', 'ám ảnh; làm cho bận tâm lo nghĩ; nghĩ hoài không thôi; quá bận tâm; quá câu nệ', 'v.', 'obsession (n.), obsessive (adj.), obsessively (adv.), obsessed (adj.)', NULL, 'Thường dùng cấu trúc ''be obsessed with''; dạng chủ động thường đi với giới từ ''over'' hoặc ''about''.', 'Don''t obsess over every tiny mark on your shoes.', NULL, 'Đừng quá bận tâm đến từng vết bẩn nhỏ trên giày của bạn.', '{"wordId":"obsess","ukIpa":"/əbˈses/","usIpa":"/əbˈses/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"to fill someone''s mind so they cannot think of anything else","vi":"ám ảnh; làm cho bận tâm lo nghĩ"},{"pos":"v.","en":"to think about something constantly and excessively","vi":"nghĩ hoài không thôi; quá bận tâm; quá câu nệ"}],"examples":[{"en":"Don''t obsess over every tiny mark on your shoes.","vi":"Đừng quá bận tâm đến từng vết bẩn nhỏ trên giày của bạn.","audioKind":"ex"},{"en":"Some students obsess over examination results, neglecting the broader skills that education should develop.","vi":"Một số học sinh quá mức ám ảnh về kết quả thi cử mà bỏ qua những kỹ năng rộng lớn hơn mà giáo dục nên mang lại.","audioKind":"ex2"}],"collocations":[{"en":"obsess over details","vi":"quá câu nệ tiểu tiết"},{"en":"be obsessed with success","vi":"ám ảnh với sự thành công"},{"en":"obsess about appearance","vi":"quá bận tâm đến ngoại hình"}],"wordFamily":["obsession (n.)","obsessive (adj.)","obsessively (adv.)","obsessed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc ''be obsessed with''; dạng chủ động thường đi với giới từ ''over'' hoặc ''about''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_negate', 'en-c1-31', 'negate', '/nɪˈɡeɪt/', 'C1', 'làm triệt tiêu; vô hiệu hóa; phủ nhận; bác bỏ', 'v.', 'negation (n.)', 'Đồng nghĩa: cancel out, nullify', 'Từ mang tính trang trọng; thường dùng để chỉ việc triệt tiêu hiệu quả, không chỉ mang nghĩa phủ nhận bằng lời nói.', 'The delivery fee negated the savings on our groceries.', NULL, 'Phí giao hàng đã triệt tiêu khoản tiền tiết kiệm khi mua thực phẩm của chúng tôi.', '{"wordId":"negate","ukIpa":"/nɪˈɡeɪt/","usIpa":"/nɪˈɡeɪt/","cefr":"C1","topic":"thinking","senses":[{"pos":"v.","en":"Cancel the effect or value of something.","vi":"làm triệt tiêu; vô hiệu hóa"},{"pos":"v.","en":"State or show that something is not true.","vi":"phủ nhận; bác bỏ"}],"examples":[{"en":"The delivery fee negated the savings on our groceries.","vi":"Phí giao hàng đã triệt tiêu khoản tiền tiết kiệm khi mua thực phẩm của chúng tôi.","audioKind":"ex"},{"en":"Increased energy consumption may negate the environmental benefits of replacing older appliances with more efficient models.","vi":"Việc tiêu thụ năng lượng gia tăng có thể làm triệt tiêu các lợi ích môi trường khi thay thế các thiết bị cũ bằng những dòng máy hiệu suất cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"negate the benefits","vi":"triệt tiêu lợi ích"},{"en":"negate the effects","vi":"làm mất tác dụng"},{"en":"negate an argument","vi":"bác bỏ một lập luận"}],"wordFamily":["negation (n.)"],"synonyms":["cancel out","nullify"],"antonyms":[],"tipVi":"Từ mang tính trang trọng; thường dùng để chỉ việc triệt tiêu hiệu quả, không chỉ mang nghĩa phủ nhận bằng lời nói.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attribution', 'en-c1-31', 'attribution', '/ˌætrɪˈbjuːʃn/', 'C1', 'sự quy nguyên nhân; sự quy kết trách nhiệm; sự ghi rõ tác giả; sự ghi nguồn', 'n.', 'attribute (v.), attributable (adj.)', NULL, 'Không phải nghĩa sở hữu thông thường; thường dùng để chỉ việc xác định rõ nguyên nhân, tác giả hoặc nguồn gốc.', 'Please include an attribution when you share my photograph.', NULL, 'Vui lòng đính kèm thông tin tác giả khi bạn chia sẻ bức ảnh của tôi.', '{"wordId":"attribution","ukIpa":"/ˌætrɪˈbjuːʃn/","usIpa":"/ˌætrɪˈbjuːʃn/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"the act of identifying something''s cause, creator, or source","vi":"sự quy nguyên nhân; sự quy kết trách nhiệm"},{"pos":"n.","en":"acknowledgement of the person who created or supplied something","vi":"sự ghi rõ tác giả; sự ghi nguồn"}],"examples":[{"en":"Please include an attribution when you share my photograph.","vi":"Vui lòng đính kèm thông tin tác giả khi bạn chia sẻ bức ảnh của tôi.","audioKind":"ex"},{"en":"Accurate attribution of environmental damage to specific industries is essential for developing fair and effective regulations.","vi":"Việc quy kết chính xác tổn thất môi trường cho các ngành công nghiệp cụ thể đóng vai trò cốt lõi trong việc xây dựng các quy định công bằng và hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"attribution of responsibility","vi":"xác định trách nhiệm"},{"en":"causal attribution","vi":"quy kết nguyên nhân"},{"en":"source attribution","vi":"ghi rõ nguồn gốc"}],"wordFamily":["attribute (v.)","attributable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Không phải nghĩa sở hữu thông thường; thường dùng để chỉ việc xác định rõ nguyên nhân, tác giả hoặc nguồn gốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_absurdity', 'en-c1-31', 'absurdity', '/əbˈsɜːrdəti/', 'C1', 'sự vô lý; sự lố bịch; tính chất hoang đường; điều vô lý; chuyện lố bịch', 'n.', 'absurd (adj.), absurdly (adv.)', 'Đồng nghĩa: ridiculousness · Trái nghĩa: reasonableness', 'dùng ở dạng không đếm được khi chỉ tính chất vô lý; dùng dạng đếm được khi chỉ sự việc hoang đường cụ thể.', 'We laughed at the absurdity of wearing coats indoors.', NULL, 'Chúng tôi đã cười trước sự vô lý của việc mặc áo khoác ở trong nhà.', '{"wordId":"absurdity","ukIpa":"/əbˈsɜːdəti/","usIpa":"/əbˈsɜːrdəti/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"the quality of being unreasonable, ridiculous, or illogical","vi":"sự vô lý; sự lố bịch; tính chất hoang đường"},{"pos":"n.","en":"an action, situation, or statement that makes no sense","vi":"điều vô lý; chuyện lố bịch"}],"examples":[{"en":"We laughed at the absurdity of wearing coats indoors.","vi":"Chúng tôi đã cười trước sự vô lý của việc mặc áo khoác ở trong nhà.","audioKind":"ex"},{"en":"Critics highlighted the absurdity of building more roads while claiming to reduce dependence on private cars.","vi":"Các nhà phê bình đã chỉ ra sự vô lý của việc xây dựng thêm nhiều con đường trong khi lại tuyên bố giảm sự phụ thuộc vào xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"the absurdity of","vi":"sự vô lý của"},{"en":"sheer absurdity","vi":"sự hoang đường hoàn toàn"},{"en":"expose an absurdity","vi":"vạch trần một điều vô lý"}],"wordFamily":["absurd (adj.)","absurdly (adv.)"],"synonyms":["ridiculousness"],"antonyms":["reasonableness"],"tipVi":"dùng ở dạng không đếm được khi chỉ tính chất vô lý; dùng dạng đếm được khi chỉ sự việc hoang đường cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trivial', 'en-c1-31', 'trivial', '/ˈtrɪviəl/', 'C1', 'phù phiếm; tầm thường; không quan trọng', 'adj.', 'trivially (adv.), triviality (n.), trivialise (v.)', 'Đồng nghĩa: unimportant, insignificant, minor · Trái nghĩa: important, significant', 'Diễn tả mức độ quan trọng thấp chứ không có nghĩa là dễ dàng; trivial matters dùng để chỉ việc cỏn con.', 'We wasted the afternoon arguing over a trivial detail.', NULL, 'Chúng tôi đã hoài phí cả buổi chiều chỉ để tranh cãi về một chi tiết vụn vặt.', '{"wordId":"trivial","ukIpa":"/ˈtrɪviəl/","usIpa":"/ˈtrɪviəl/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"having little importance or seriousness","vi":"phù phiếm; tầm thường; không quan trọng"}],"examples":[{"en":"We wasted the afternoon arguing over a trivial detail.","vi":"Chúng tôi đã hoài phí cả buổi chiều chỉ để tranh cãi về một chi tiết vụn vặt.","audioKind":"ex"},{"en":"Public debates sometimes focus on trivial disagreements rather than the urgent environmental problems affecting future generations.","vi":"Các cuộc tranh luận công khai đôi khi tập trung vào những bất đồng nhỏ nhặt thay vì các vấn đề môi trường cấp bách đang tác động đến các thế hệ tương lai.","audioKind":"ex2"}],"collocations":[{"en":"trivial matter","vi":"chuyện vặt; việc cỏn con"},{"en":"trivial detail","vi":"chi tiết vụn vặt"},{"en":"trivial complaint","vi":"lời phàn nàn về chuyện nhỏ nhặt"}],"wordFamily":["trivially (adv.)","triviality (n.)","trivialise (v.)"],"synonyms":["unimportant","insignificant","minor"],"antonyms":["important","significant"],"tipVi":"Diễn tả mức độ quan trọng thấp chứ không có nghĩa là dễ dàng; trivial matters dùng để chỉ việc cỏn con.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ambiguous', 'en-c1-31', 'ambiguous', '/æmˈbɪɡjuəs/', 'C1', 'có nhiều hơn một cách hiểu hoặc cách giải thích; mơ hồ, có ẩn ý, lập lờ', 'adj.', 'ambiguity (n.), ambiguously (adv.), unambiguous (adj.)', 'Đồng nghĩa: unclear, equivocal · Trái nghĩa: unambiguous, clear', 'Cụm từ ambiguous mang ý nghĩa có thể diễn giải theo nhiều hướng khác nhau; trong khi vague nhấn mạnh việc thiếu chi tiết, không rõ ràng.', 'His ambiguous reply left us unsure whether to come.', NULL, 'Câu trả lời lập lờ của anh ấy khiến chúng tôi không chắc có nên đến hay không.', '{"wordId":"ambiguous","ukIpa":"/æmˈbɪɡjuəs/","usIpa":"/æmˈbɪɡjuəs/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Having more than one possible meaning or interpretation","vi":"có nhiều hơn một cách hiểu hoặc cách giải thích; mơ hồ, có ẩn ý, lập lờ"}],"examples":[{"en":"His ambiguous reply left us unsure whether to come.","vi":"Câu trả lời lập lờ của anh ấy khiến chúng tôi không chắc có nên đến hay không.","audioKind":"ex"},{"en":"Ambiguous wording in public health advice can confuse readers and reduce their confidence in official guidance.","vi":"Lời lẽ mơ hồ trong các khuyến nghị y tế công cộng có thể làm người đọc bối rối và làm giảm lòng tin của họ đối với hướng dẫn chính thức.","audioKind":"ex2"}],"collocations":[{"en":"ambiguous wording","vi":"câu chữ mơ hồ"},{"en":"ambiguous statement","vi":"tuyên bố có ý nghĩa lập lờ"},{"en":"remain ambiguous","vi":"vẫn còn mơ hồ"}],"wordFamily":["ambiguity (n.)","ambiguously (adv.)","unambiguous (adj.)"],"synonyms":["unclear","equivocal"],"antonyms":["unambiguous","clear"],"tipVi":"Cụm từ ambiguous mang ý nghĩa có thể diễn giải theo nhiều hướng khác nhau; trong khi vague nhấn mạnh việc thiếu chi tiết, không rõ ràng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_breadth', 'en-c1-31', 'breadth', '/bredθ/', 'C1', 'độ rộng lớn; sự phong phú về phạm vi; chiều rộng; khoảng cách từ bên này sang bên kia', 'n.', 'broad (adj.), broaden (v.), broadly (adv.)', 'Đồng nghĩa: width, range', 'breadth nhấn mạnh chiều rộng/phạm vi; depth nhấn mạnh chiều sâu, cả hai thường được dùng sóng đôi.', 'The breadth of her interests always surprises her friends.', NULL, 'Sự phong phú trong sở thích của cô ấy luôn khiến bạn bè ngạc nhiên.', '{"wordId":"breadth","ukIpa":"/bredθ/","usIpa":"/bredθ/","cefr":"C1","topic":"thinking","senses":[{"pos":"n.","en":"The wide range of things something includes.","vi":"độ rộng lớn; sự phong phú về phạm vi"},{"pos":"n.","en":"The distance from one side of something to the other.","vi":"chiều rộng; khoảng cách từ bên này sang bên kia"}],"examples":[{"en":"The breadth of her interests always surprises her friends.","vi":"Sự phong phú trong sở thích của cô ấy luôn khiến bạn bè ngạc nhiên.","audioKind":"ex"},{"en":"Universities should balance breadth of knowledge with opportunities for students to develop expertise in a chosen field.","vi":"Các trường đại học nên cân bằng giữa độ rộng của kiến thức và cơ hội để sinh viên phát triển chuyên môn trong lĩnh vực đã chọn.","audioKind":"ex2"}],"collocations":[{"en":"breadth of knowledge","vi":"tầm vóc kiến thức"},{"en":"breadth of experience","vi":"độ phong phú của kinh nghiệm"},{"en":"breadth and depth","vi":"chiều rộng và chiều sâu"}],"wordFamily":["broad (adj.)","broaden (v.)","broadly (adv.)"],"synonyms":["width","range"],"antonyms":[],"tipVi":"breadth nhấn mạnh chiều rộng/phạm vi; depth nhấn mạnh chiều sâu, cả hai thường được dùng sóng đôi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obsessive', 'en-c1-31', 'obsessive', '/əbˈsesɪv/', 'C1', 'ám ảnh; bận tâm quá mức; khó dứt ra được', 'adj.', 'obsess (v.), obsession (n.), obsessively (adv.)', NULL, 'Mạnh hơn nhiều so với việc chỉ "quan tâm" hay "thích thú", thường mang hàm ý quá đà và khó kiểm soát.', 'His obsessive checking of the weather delayed our picnic.', NULL, 'Việc anh ấy cứ chăm chăm kiểm tra thời tiết đã làm lỡ chuyến đi dã ngoại của chúng tôi.', '{"wordId":"obsessive","ukIpa":"/əbˈsesɪv/","usIpa":"/əbˈsesɪv/","cefr":"C1","topic":"thinking","senses":[{"pos":"adj.","en":"Thinking about something constantly and finding it difficult to stop.","vi":"ám ảnh; bận tâm quá mức; khó dứt ra được"}],"examples":[{"en":"His obsessive checking of the weather delayed our picnic.","vi":"Việc anh ấy cứ chăm chăm kiểm tra thời tiết đã làm lỡ chuyến đi dã ngoại của chúng tôi.","audioKind":"ex"},{"en":"Obsessive concern about academic performance can prevent students from maintaining healthy friendships and enjoying leisure activities.","vi":"Sự quan tâm thái quá đến thành tích học tập có thể ngăn cản học sinh duy trì các mối quan hệ bạn bè lành mạnh và tận hưởng các hoạt động giải trí.","audioKind":"ex2"}],"collocations":[{"en":"obsessive behaviour","vi":"hành vi mang tính ám ảnh"},{"en":"obsessive concern","vi":"sự quan tâm thái quá"},{"en":"obsessive about details","vi":"bị ám ảnh về các chi tiết nhỏ"}],"wordFamily":["obsess (v.)","obsession (n.)","obsessively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Mạnh hơn nhiều so với việc chỉ \"quan tâm\" hay \"thích thú\", thường mang hàm ý quá đà và khó kiểm soát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_31_1', 'en-c1-31', 'Cách dùng “ambiguous” (adj.) — có nhiều hơn một cách hiểu hoặc cách giải thích; mơ hồ, có ẩn ý, lập lờ', 'ambiguous wording  ·  ambiguous statement  ·  remain ambiguous', 'Cụm từ ambiguous mang ý nghĩa có thể diễn giải theo nhiều hướng khác nhau; trong khi vague nhấn mạnh việc thiếu chi tiết, không rõ ràng.', 'Họ từ (Word Family): ambiguity (n.), ambiguously (adv.), unambiguous (adj.) | Đồng nghĩa: unclear, equivocal · Trái nghĩa: unambiguous, clear', '[{"hanzi":"His ambiguous reply left us unsure whether to come.","pinyin":"","meaning":"Câu trả lời lập lờ của anh ấy khiến chúng tôi không chắc có nên đến hay không."},{"hanzi":"Ambiguous wording in public health advice can confuse readers and reduce their confidence in official guidance.","pinyin":"","meaning":"Lời lẽ mơ hồ trong các khuyến nghị y tế công cộng có thể làm người đọc bối rối và làm giảm lòng tin của họ đối với hướng dẫn chính thức."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_31_2', 'en-c1-31', 'Cách dùng “negate” (v.) — làm triệt tiêu; vô hiệu hóa', 'negate the benefits  ·  negate the effects  ·  negate an argument', 'Từ mang tính trang trọng; thường dùng để chỉ việc triệt tiêu hiệu quả, không chỉ mang nghĩa phủ nhận bằng lời nói.', 'Họ từ (Word Family): negation (n.) | Đồng nghĩa: cancel out, nullify', '[{"hanzi":"The delivery fee negated the savings on our groceries.","pinyin":"","meaning":"Phí giao hàng đã triệt tiêu khoản tiền tiết kiệm khi mua thực phẩm của chúng tôi."},{"hanzi":"Increased energy consumption may negate the environmental benefits of replacing older appliances with more efficient models.","pinyin":"","meaning":"Việc tiêu thụ năng lượng gia tăng có thể làm triệt tiêu các lợi ích môi trường khi thay thế các thiết bị cũ bằng những dòng máy hiệu suất cao hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_31_3', 'en-c1-31', 'Cách dùng “commonsense” (adj.) — phù hợp với lẽ phải thông thường; thực tế và hợp lý', 'a commonsense approach  ·  commonsense advice  ·  commonsense precautions', 'Tính từ này đôi khi cũng được viết là common-sense; trong khi danh từ common sense được viết tách thành hai từ.', 'Họ từ (Word Family): common sense (n.) | Đồng nghĩa: sensible, practical · Trái nghĩa: impractical', '[{"hanzi":"Taking an umbrella was a commonsense decision in this weather.","pinyin":"","meaning":"Mang theo ô là một quyết định rất hợp lý trong kiểu thời tiết này."},{"hanzi":"Simple commonsense measures, such as improving street lighting, can make residential areas safer for pedestrians.","pinyin":"","meaning":"Các biện pháp thực tế đơn giản, chẳng hạn như cải thiện hệ thống đèn đường, có thể giúp khu dân cư trở nên an toàn hơn cho người đi bộ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_31_4', 'en-c1-31', 'Cách dùng “attribution” (n.) — sự quy nguyên nhân; sự quy kết trách nhiệm', 'attribution of responsibility  ·  causal attribution  ·  source attribution', 'Không phải nghĩa sở hữu thông thường; thường dùng để chỉ việc xác định rõ nguyên nhân, tác giả hoặc nguồn gốc.', 'Họ từ (Word Family): attribute (v.), attributable (adj.)', '[{"hanzi":"Please include an attribution when you share my photograph.","pinyin":"","meaning":"Vui lòng đính kèm thông tin tác giả khi bạn chia sẻ bức ảnh của tôi."},{"hanzi":"Accurate attribution of environmental damage to specific industries is essential for developing fair and effective regulations.","pinyin":"","meaning":"Việc quy kết chính xác tổn thất môi trường cho các ngành công nghiệp cụ thể đóng vai trò cốt lõi trong việc xây dựng các quy định công bằng và hiệu quả."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_31_1', 'en-c1-31', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_1_1', 'ten_c1_31_1', 'commonsense', 'Taking an umbrella was a commonsense decision in this weather.', 'Taking an umbrella was a commonsense decision in this weather.', '/ˌkɑːmənˈsens/', 'Mang theo ô là một quyết định rất hợp lý trong kiểu thời tiết này.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_1_2', 'ten_c1_31_1', 'heed', 'We heeded the guide''s warning and left the beach.', 'We heeded the guide''s warning and left the beach.', '/hiːd/', 'Chúng tôi đã nghe theo cảnh báo của hướng dẫn viên và rời khỏi bãi biển.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_1_3', 'ten_c1_31_1', 'hallmark', 'Fresh ingredients are the hallmark of my grandmother''s cooking.', 'Fresh ingredients are the hallmark of my grandmother''s cooking.', '/ˈhɔːlmɑːrk/', 'Nguyên liệu tươi ngon là nét đặc trưng trong cách nấu ăn của bà tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_1_4', 'ten_c1_31_1', 'decided', 'There is a decided chill in the air tonight.', 'There is a decided chill in the air tonight.', '/dɪˈsaɪdɪd/', 'Đêm nay không khí có một cái lạnh rõ rệt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_1_5', 'ten_c1_31_1', 'visualize', 'Close your eyes and visualize a quiet sandy beach.', 'Close your eyes and visualize a quiet sandy beach.', '/ˈvɪʒuəlaɪz/', 'Hãy nhắm mắt lại và hình dung một bãi biển cát yên tĩnh.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_1_6', 'ten_c1_31_1', 'embody', 'These handmade bowls embody my grandmother''s patience and care.', 'These handmade bowls embody my grandmother''s patience and care.', '/ɪmˈbɑːdi/', 'Những chiếc bát thủ công này thể hiện sự kiên nhẫn và tận tâm của bà tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_1_7', 'ten_c1_31_1', 'entirety', 'We watched the long film in its entirety.', 'We watched the long film in its entirety.', '/ɪnˈtaɪrəti/', 'Chúng tôi đã xem toàn bộ bộ phim dài tập đó.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_1_8', 'ten_c1_31_1', 'shrewd', 'That shrewd purchase saved us money on heating.', 'That shrewd purchase saved us money on heating.', '/ʃruːd/', 'Quyết định mua sắm sáng suốt đó đã giúp chúng tôi tiết kiệm được tiền sưởi ấm.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_31_1_1', 'en-c1-31', 'ten_c1_31_1', 'listening', 'listening', 'Taking an umbrella was a commonsense decision in this weather.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Câu trả lời lập lờ của anh ấy khiến chúng tôi không chắc có nên đến hay không.","Đêm nay không khí có một cái lạnh rõ rệt.","Mang theo ô là một quyết định rất hợp lý trong kiểu thời tiết này.","Phí giao hàng đã triệt tiêu khoản tiền tiết kiệm khi mua thực phẩm của chúng tôi."]'::jsonb, 2, 'Taking an umbrella was a commonsense decision in this weather. → Mang theo ô là một quyết định rất hợp lý trong kiểu thời tiết này.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_31_1_2', 'en-c1-31', 'ten_c1_31_1', 'listening', 'listening', 'We heeded the guide''s warning and left the beach.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã nghe theo cảnh báo của hướng dẫn viên và rời khỏi bãi biển.","Với một chút khéo léo, Lina đã biến những chiếc thùng gỗ cũ thành các giá sách.","Lời giải thích của anh ấy nghe có vẻ hợp lý, nhưng tôi vẫn kiểm tra lại.","Chúng tôi đã cười trước sự vô lý của việc mặc áo khoác ở trong nhà."]'::jsonb, 0, 'We heeded the guide''s warning and left the beach. → Chúng tôi đã nghe theo cảnh báo của hướng dẫn viên và rời khỏi bãi biển.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_31_1_3', 'en-c1-31', 'ten_c1_31_1', 'listening', 'listening', 'Fresh ingredients are the hallmark of my grandmother''s cooking.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Với một chút khéo léo, Lina đã biến những chiếc thùng gỗ cũ thành các giá sách.","Lời giải thích của anh ấy nghe có vẻ hợp lý, nhưng tôi vẫn kiểm tra lại.","Chúng tôi đã xem toàn bộ bộ phim dài tập đó.","Nguyên liệu tươi ngon là nét đặc trưng trong cách nấu ăn của bà tôi."]'::jsonb, 3, 'Fresh ingredients are the hallmark of my grandmother''s cooking. → Nguyên liệu tươi ngon là nét đặc trưng trong cách nấu ăn của bà tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_31_2', 'en-c1-31', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_2_1', 'ten_c1_31_2', 'commonsense', 'Simple commonsense measures, such as improving street lighting, can make residential areas safer for pedestrians.', 'Simple commonsense measures, such as improving street lighting, can make residential areas safer for pedestrians.', '/ˌkɑːmənˈsens/', 'Các biện pháp thực tế đơn giản, chẳng hạn như cải thiện hệ thống đèn đường, có thể giúp khu dân cư trở nên an toàn hơn cho người đi bộ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_2_2', 'ten_c1_31_2', 'heed', 'Governments must heed scientific advice when developing policies to protect communities from extreme weather.', 'Governments must heed scientific advice when developing policies to protect communities from extreme weather.', '/hiːd/', 'Các chính phủ phải chú ý đến các khuyến nghị khoa học khi xây dựng chính sách nhằm bảo vệ cộng đồng trước các hiện tượng thời tiết cực đoan.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_2_3', 'ten_c1_31_2', 'hallmark', 'Transparent decision-making is a hallmark of effective governance because it allows citizens to hold public officials accountable.', 'Transparent decision-making is a hallmark of effective governance because it allows citizens to hold public officials accountable.', '/ˈhɔːlmɑːrk/', 'Quyết định minh bạch là dấu ấn của một nền quản trị hiệu quả vì nó cho phép người dân quy trách nhiệm cho các quan chức công quyền.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_2_4', 'ten_c1_31_2', 'decided', 'Reliable internet access gives rural businesses a decided advantage when competing for customers beyond their local area.', 'Reliable internet access gives rural businesses a decided advantage when competing for customers beyond their local area.', '/dɪˈsaɪdɪd/', 'Truy cập Internet đáng tin cậy mang lại cho các doanh nghiệp nông thôn một lợi thế rõ rệt khi cạnh tranh giành khách hàng ngoài khu vực địa phương của họ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_2_5', 'ten_c1_31_2', 'visualize', 'Digital models help residents visualize how proposed buildings will change the appearance of their neighbourhood.', 'Digital models help residents visualize how proposed buildings will change the appearance of their neighbourhood.', '/ˈvɪʒuəlaɪz/', 'Các mô hình kỹ thuật số giúp cư dân hình dung cách các tòa nhà được đề xuất sẽ thay đổi diện mạo khu phố của họ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_31_2_6', 'ten_c1_31_2', 'embody', 'Public buildings should embody the values of inclusion by providing accessible spaces for people with different needs.', 'Public buildings should embody the values of inclusion by providing accessible spaces for people with different needs.', '/ɪmˈbɑːdi/', 'Các công trình công cộng nên thể hiện các giá trị hòa nhập bằng cách cung cấp không gian dễ tiếp cận cho những người có nhu cầu khác nhau.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_31_2_1', 'en-c1-31', 'ten_c1_31_2', 'listening', 'listening', 'Simple commonsense measures, such as improving street lighting, can make residential areas safer for pedestrians.', NULL, 'Trong câu vừa nghe, từ “commonsense” mang nghĩa nào sau đây?', '["phù hợp với lẽ phải thông thường; thực tế và hợp lý","có thể chuyển nhượng; có thể chuyển giao","cực kỳ; lớn nhất; tối đa","cố tình tránh xa; xa lánh"]'::jsonb, 0, '“commonsense” (/ˌkɑːmənˈsens/): phù hợp với lẽ phải thông thường; thực tế và hợp lý. Câu đầy đủ: Simple commonsense measures, such as improving street lighting, can make residential areas safer for pedestrians.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_31_2_2', 'en-c1-31', 'ten_c1_31_2', 'listening', 'listening', 'Governments must heed scientific advice when developing policies to protect communities from extreme weather.', NULL, 'Trong câu vừa nghe, từ “heed” mang nghĩa nào sau đây?', '["chú ý; lắng nghe và làm theo","bảo đảm; bảo lãnh; xác nhận","tiềm ẩn; ẩn giấu; tiềm tàng","sự thành lập; sự thiết lập"]'::jsonb, 0, '“heed” (/hiːd/): chú ý; lắng nghe và làm theo. Câu đầy đủ: Governments must heed scientific advice when developing policies to protect communities from extreme weather.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
