INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_31_4', 'en-c1-31', 'en_to_vi', 'With some ingenuity, Lina turned old crates into shelves.', 'With some ingenuity, Lina turned old crates into shelves.', '/ˌɪndʒəˈnuːəti/', NULL, 'Với một chút khéo léo, Lina đã biến những chiếc thùng gỗ cũ thành các giá sách.', NULL, '["với","một","chút","khéo","léo","lina","đã","biến"]'::jsonb, 'Từ trọng tâm: ingenuity (tài khéo léo; sự sáng tạo; sự tinh tế)', 'With some ingenuity, Lina turned old crates into shelves. → Với một chút khéo léo, Lina đã biến những chiếc thùng gỗ cũ thành các giá sách.', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_31_5', 'en-c1-31', 'en_to_vi', 'My intent was to help, not to interrupt you.', 'My intent was to help, not to interrupt you.', '/ɪnˈtent/', NULL, 'Ý định của tôi là giúp đỡ chứ không phải làm phiền bạn.', NULL, '["ý","định","của","tôi","là","giúp","đỡ","chứ"]'::jsonb, 'Từ trọng tâm: intent (ý định; mục đích)', 'My intent was to help, not to interrupt you. → Ý định của tôi là giúp đỡ chứ không phải làm phiền bạn.', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
