INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_1', 'en-c1-31', NULL, 'comprehensive_test', 'listening', 'commonsense', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đột ngột; bất ngờ","sứ mệnh; công việc phù hợp với tâm huyết bản thân","phù hợp với lẽ phải thông thường; thực tế và hợp lý","lĩnh vực; phạm vi"]'::jsonb, 2, 'commonsense (/ˌkɑːmənˈsens/) → phù hợp với lẽ phải thông thường; thực tế và hợp lý', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_2', 'en-c1-31', NULL, 'comprehensive_test', 'listening', 'We heeded the guide''s warning and left the beach.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ý định của tôi là giúp đỡ chứ không phải làm phiền bạn.","Phí giao hàng đã triệt tiêu khoản tiền tiết kiệm khi mua thực phẩm của chúng tôi.","Nụ cười rạng rỡ của anh ấy hoàn toàn mâu thuẫn với những lời phàn nàn của anh ấy.","Chúng tôi đã nghe theo cảnh báo của hướng dẫn viên và rời khỏi bãi biển."]'::jsonb, 3, 'We heeded the guide''s warning and left the beach. → Chúng tôi đã nghe theo cảnh báo của hướng dẫn viên và rời khỏi bãi biển.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_3', 'en-c1-31', NULL, 'comprehensive_test', 'listening', 'hallmark', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nghịch cảnh; hoàn cảnh khó khăn","chất đầy; mang nặng; trĩu","thật thà; thẳng thắn; bộc trực","dấu ấn; nét đặc trưng; đặc điểm tiêu biểu"]'::jsonb, 3, 'hallmark (/ˈhɔːlmɑːrk/) → dấu ấn; nét đặc trưng; đặc điểm tiêu biểu; dấu kiểm định (vàng bạc, kim loại quý)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_4', 'en-c1-31', NULL, 'comprehensive_test', 'listening', 'There is a decided chill in the air tonight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lời giải thích của anh ấy nghe có vẻ hợp lý, nhưng tôi vẫn kiểm tra lại.","Đêm nay không khí có một cái lạnh rõ rệt.","Mang theo ô là một quyết định rất hợp lý trong kiểu thời tiết này.","Phí giao hàng đã triệt tiêu khoản tiền tiết kiệm khi mua thực phẩm của chúng tôi."]'::jsonb, 1, 'There is a decided chill in the air tonight. → Đêm nay không khí có một cái lạnh rõ rệt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_5', 'en-c1-31', NULL, 'comprehensive_test', 'listening', 'visualize', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cuốn; xoáy tròn; làm xoáy","hình dung; tưởng tượng","người cư ngụ; người sử dụng; hành khách (trên xe)","vặt vãnh; nhỏ nhặt"]'::jsonb, 1, 'visualize (/ˈvɪʒuəlaɪz/) → hình dung; tưởng tượng; trực quan hóa', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_6', 'en-c1-31', NULL, 'comprehensive_test', 'listening', 'These handmade bowls embody my grandmother''s patience and care.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những chiếc bát thủ công này thể hiện sự kiên nhẫn và tận tâm của bà tôi.","Tôi cảm thấy hoài nghi về việc mua một chiếc xe đạp không có phanh.","Đêm nay không khí có một cái lạnh rõ rệt.","Đừng tự lừa dối bản thân rằng công việc đã hoàn thành."]'::jsonb, 0, 'These handmade bowls embody my grandmother''s patience and care. → Những chiếc bát thủ công này thể hiện sự kiên nhẫn và tận tâm của bà tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_7', 'en-c1-31', NULL, 'comprehensive_test', 'listening', 'entirety', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["toàn bộ; tính toàn vẹn","dễ thấy; nổi bật; đập ngay vào mắt","hầm ngục; nhà giam dưới lòng đất","làm cho ai đó không thể hiểu hoặc giải thích được điều gì; gây bối rối, làm khó"]'::jsonb, 0, 'entirety (/ɪnˈtaɪrəti/) → toàn bộ; tính toàn vẹn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_8', 'en-c1-31', NULL, 'comprehensive_test', 'listening', 'That shrewd purchase saved us money on heating.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã xem toàn bộ bộ phim dài tập đó.","Mang theo ô là một quyết định rất hợp lý trong kiểu thời tiết này.","Nụ cười rạng rỡ của anh ấy hoàn toàn mâu thuẫn với những lời phàn nàn của anh ấy.","Quyết định mua sắm sáng suốt đó đã giúp chúng tôi tiết kiệm được tiền sưởi ấm."]'::jsonb, 3, 'That shrewd purchase saved us money on heating. → Quyết định mua sắm sáng suốt đó đã giúp chúng tôi tiết kiệm được tiền sưởi ấm.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_9', 'en-c1-31', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To form a clear picture of something in your mind.”?', '["visualize","obsessive","commonsense","delude"]'::jsonb, 0, 'visualize (/ˈvɪʒuəlaɪz/) → hình dung; tưởng tượng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_10', 'en-c1-31', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To clearly represent an idea, quality, or feeling.”?', '["shrewd","hallmark","variance","embody"]'::jsonb, 3, 'embody (/ɪmˈbɑːdi/) → thể hiện; hiện thân', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_11', 'en-c1-31', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the whole of something, with no part left out”?', '["dubious","entirety","trivial","embody"]'::jsonb, 1, 'entirety (/ɪnˈtaɪrəti/) → toàn bộ; tính toàn vẹn', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_12', 'en-c1-31', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “good at judging situations and making decisions that bring advantages”?', '["variance","absurdity","shrewd","breadth"]'::jsonb, 2, 'shrewd (/ʃruːd/) → sáng suốt; tinh ranh; sắc sảo', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_13', 'en-c1-31', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Seeming reasonable or likely to be true”?', '["plausible","err","heed","visualize"]'::jsonb, 0, 'plausible (/ˈplɔːzəbl/) → hợp lý; có vẻ hợp lý', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
