INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_18', 'en-c1-31', NULL, 'comprehensive_test', 'reading', NULL, 'Simple commonsense measures, such as improving street lighting, can make residential areas safer for pedestrians.', 'Dựa vào câu trên, từ “commonsense” có nghĩa phù hợp nhất là gì?', '["búi; cụm; đám; nhóm","phù hợp với lẽ phải thông thường; thực tế và hợp lý","rõ ràng, dứt khoát, dễ nhận thấy","chứa muối; có tính muối"]'::jsonb, 1, 'commonsense: phù hợp với lẽ phải thông thường; thực tế và hợp lý. Dịch cả câu: Các biện pháp thực tế đơn giản, chẳng hạn như cải thiện hệ thống đèn đường, có thể giúp khu dân cư trở nên an toàn hơn cho người đi bộ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_19', 'en-c1-31', NULL, 'comprehensive_test', 'reading', NULL, 'Governments must heed scientific advice when developing policies to protect communities from extreme weather.', 'Dựa vào câu trên, từ “heed” có nghĩa phù hợp nhất là gì?', '["miệng (cốc, bát, hoặc vật chứa khác)","chú ý; lắng nghe và làm theo","khai sáng; làm cho ai đó hiểu rõ","một sai lầm nghiêm trọng do bất cẩn hoặc thiếu phán đoán chuẩn xác"]'::jsonb, 1, 'heed: chú ý; lắng nghe và làm theo; sự chú ý; sự lưu tâm. Dịch cả câu: Các chính phủ phải chú ý đến các khuyến nghị khoa học khi xây dựng chính sách nhằm bảo vệ cộng đồng trước các hiện tượng thời tiết cực đoan.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_20', 'en-c1-31', NULL, 'comprehensive_test', 'reading', NULL, 'Transparent decision-making is a hallmark of effective governance because it allows citizens to hold public officials accountable.', 'Dựa vào câu trên, từ “hallmark” có nghĩa phù hợp nhất là gì?', '["tráng kiện; vững chắc; khỏe mạnh","dấu ấn; nét đặc trưng; đặc điểm tiêu biểu","thuộc về thành phố; thuộc về đô thị; cấp thành phố","tinh tế; khó nhận thấy"]'::jsonb, 1, 'hallmark: dấu ấn; nét đặc trưng; đặc điểm tiêu biểu; dấu kiểm định (vàng bạc, kim loại quý). Dịch cả câu: Quyết định minh bạch là dấu ấn của một nền quản trị hiệu quả vì nó cho phép người dân quy trách nhiệm cho các quan chức công quyền.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_21', 'en-c1-31', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable internet access gives rural businesses a decided advantage when competing for customers beyond their local area.', 'Dựa vào câu trên, từ “decided” có nghĩa phù hợp nhất là gì?', '["sự đề cử; sự giới thiệu","vò đầu bứt tai; băn khoăn lo lắng; trăn trở khổ sở","rõ ràng, dứt khoát, dễ nhận thấy","sự hòa quyện; sự kết hợp thành một thể thống nhất"]'::jsonb, 2, 'decided: rõ ràng, dứt khoát, dễ nhận thấy. Dịch cả câu: Truy cập Internet đáng tin cậy mang lại cho các doanh nghiệp nông thôn một lợi thế rõ rệt khi cạnh tranh giành khách hàng ngoài khu vực địa phương của họ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_22', 'en-c1-31', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có nhiều hơn một cách hiểu hoặc cách giải thích; mơ hồ, có ẩn ý, lập lờ”', '["ambiguous","ramble","instructive","transcend"]'::jsonb, 0, 'có nhiều hơn một cách hiểu hoặc cách giải thích; mơ hồ, có ẩn ý, lập lờ → ambiguous (/æmˈbɪɡjuəs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_23', 'en-c1-31', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “độ rộng lớn; sự phong phú về phạm vi”', '["holocaust","breadth","arouse","provoke"]'::jsonb, 1, 'độ rộng lớn; sự phong phú về phạm vi → breadth (/bredθ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_31_24', 'en-c1-31', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ám ảnh; bận tâm quá mức; khó dứt ra được”', '["utterance","obsessive","exertion","snobbish"]'::jsonb, 1, 'ám ảnh; bận tâm quá mức; khó dứt ra được → obsessive (/əbˈsesɪv/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-32', 'en', 'Bài 32: Cảm xúc & Tính cách (1) - CEFR C1', 'CEFR C1', 'C1 · Cảm xúc', '23 từ vựng Tiếng Anh CEFR C1 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5032, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_malice', 'en-c1-32', 'malice', '/ˈmælɪs/', 'C1', 'ác ý; tâm địa hiểm độc, ý định gây tổn thương', 'n.', 'malicious (adj.), maliciously (adv.)', 'Đồng nghĩa: ill will, spite · Trái nghĩa: goodwill', 'Thường là danh từ không đếm được; "with malice" có nghĩa là "mang theo ác ý".', 'There was no malice in his teasing smile.', NULL, 'Không có chút ác ý nào trong nụ cười đùa cợt của cô ấy.', '{"wordId":"malice","ukIpa":"/ˈmælɪs/","usIpa":"/ˈmælɪs/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"a desire to hurt someone or cause them trouble","vi":"ác ý; tâm địa hiểm độc, ý định gây tổn thương"}],"examples":[{"en":"There was no malice in his teasing smile.","vi":"Không có chút ác ý nào trong nụ cười đùa cợt của cô ấy.","audioKind":"ex"},{"en":"Schools should distinguish between careless remarks and comments made with malice when addressing conflicts among students.","vi":"Nhà trường nên phân biệt giữa những lời nói vô tình và những bình luận mang tính ác ý khi giải quyết các mâu thuẫn giữa học sinh.","audioKind":"ex2"}],"collocations":[{"en":"with malice","vi":"mang ác ý"},{"en":"bear no malice","vi":"không ôm lòng thù hận"},{"en":"out of malice","vi":"vì ác ý; do lòng đố kỵ"}],"wordFamily":["malicious (adj.)","maliciously (adv.)"],"synonyms":["ill will","spite"],"antonyms":["goodwill"],"tipVi":"Thường là danh từ không đếm được; \"with malice\" có nghĩa là \"mang theo ác ý\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elated', 'en-c1-32', 'elated', '/ɪˈleɪtɪd/', 'C1', 'phấn khởi; vui sướng tột độ', 'adj.', 'elate (v.), elation (n.)', 'Đồng nghĩa: overjoyed, delighted, thrilled · Trái nghĩa: dejected, miserable', 'Mang sắc thái mạnh hơn từ happy, thường dùng sau khi đạt được thành công hoặc nhận tin vui.', 'Lina was elated when she finally passed her driving test.', NULL, 'Lina vô cùng phấn khởi khi cuối cùng cô ấy cũng vượt qua kỳ thi sát hạch lái xe.', '{"wordId":"elated","ukIpa":"/ɪˈleɪtɪd/","usIpa":"/ɪˈleɪtɪd/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Extremely happy and excited, especially after success or good news.","vi":"phấn khởi; vui sướng tột độ"}],"examples":[{"en":"Lina was elated when she finally passed her driving test.","vi":"Lina vô cùng phấn khởi khi cuối cùng cô ấy cũng vượt qua kỳ thi sát hạch lái xe.","audioKind":"ex"},{"en":"Graduates may feel elated after securing their first job, although adjusting to workplace expectations can be challenging.","vi":"Các cử nhân có thể cảm thấy vô cùng phấn khởi sau khi tìm được công việc đầu tiên, mặc dù việc thích nghi với các kỳ vọng tại nơi làm việc có thể là một thử thách.","audioKind":"ex2"}],"collocations":[{"en":"feel elated","vi":"cảm thấy vô cùng phấn khởi"},{"en":"elated at the news","vi":"vui sướng tột độ trước tin tức"},{"en":"elated by success","vi":"hân hoan vì thành công"}],"wordFamily":["elate (v.)","elation (n.)"],"synonyms":["overjoyed","delighted","thrilled"],"antonyms":["dejected","miserable"],"tipVi":"Mang sắc thái mạnh hơn từ happy, thường dùng sau khi đạt được thành công hoặc nhận tin vui.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fume', 'en-c1-32', 'fume', '/fjuːm/', 'C1', 'nổi giận đùng đùng; bực tức; khói độc; khí thải; hơi cay (thường dùng số nhiều)', 'v.', 'fuming (adj.)', NULL, 'Chỉ khói/khí thường dùng ở dạng số nhiều fumes; động từ thường diễn tả sự tức giận mạnh mẽ.', 'He fumed when muddy shoes stained his clean carpet.', NULL, 'Anh ấy nổi giận khi đôi giày dính bùn làm bẩn tấm thảm sạch của mình.', '{"wordId":"fume","ukIpa":"/fjuːm/","usIpa":"/fjuːm/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To feel or express strong anger.","vi":"nổi giận đùng đùng; bực tức"},{"pos":"n.","en":"Strong, unpleasant or harmful gas or smoke, usually plural.","vi":"khói độc; khí thải; hơi cay (thường dùng số nhiều)"}],"examples":[{"en":"He fumed when muddy shoes stained his clean carpet.","vi":"Anh ấy nổi giận khi đôi giày dính bùn làm bẩn tấm thảm sạch của mình.","audioKind":"ex"},{"en":"Exposure to exhaust fumes can worsen respiratory conditions, particularly among children living near busy roads.","vi":"Việc tiếp xúc với khí thải có thể làm trầm trọng thêm các bệnh về đường hô hấp, đặc biệt là ở trẻ em sống gần các tuyến đường đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"fume over something","vi":"bực tức về điều gì"},{"en":"exhaust fumes","vi":"khí thải động cơ"},{"en":"toxic fumes","vi":"khói độc"}],"wordFamily":["fuming (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ khói/khí thường dùng ở dạng số nhiều fumes; động từ thường diễn tả sự tức giận mạnh mẽ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relish', 'en-c1-32', 'relish', '/ˈrelɪʃ/', 'C1', 'tận hưởng; háo hức mong đợi; niềm vui; sự thích thú; nước sốt rau củ hoặc trái cây ăn kèm', 'v.', NULL, 'Đồng nghĩa: enjoy, savour · Trái nghĩa: dread', 'Động từ theo sau bởi danh từ hoặc danh động từ, không dùng to do.', 'I relish quiet mornings with tea and a book.', NULL, 'Tôi rất tận hưởng những buổi sáng yên bình bên tách trà và cuốn sách.', '{"wordId":"relish","ukIpa":"/ˈrelɪʃ/","usIpa":"/ˈrelɪʃ/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To enjoy something greatly or eagerly anticipate doing it.","vi":"tận hưởng; háo hức mong đợi"},{"pos":"n.","en":"Great enjoyment or enthusiasm when doing something.","vi":"niềm vui; sự thích thú"},{"pos":"n.","en":"A sauce of chopped vegetables or fruit eaten with food.","vi":"nước sốt rau củ hoặc trái cây ăn kèm"}],"examples":[{"en":"I relish quiet mornings with tea and a book.","vi":"Tôi rất tận hưởng những buổi sáng yên bình bên tách trà và cuốn sách.","audioKind":"ex"},{"en":"Many students relish the opportunity to study abroad because it exposes them to different cultures and perspectives.","vi":"Nhiều sinh viên rất trân trọng cơ hội đi du học vì nó giúp họ tiếp 13c với các nền văn hóa và góc nhìn khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"relish a challenge","vi":"hào hứng đón nhận thử thách"},{"en":"relish the opportunity","vi":"tận hưởng cơ hội"},{"en":"with relish","vi":"một cách hào hứng; đầy thích thú"},{"en":"tomato relish","vi":"sốt cà chua"}],"wordFamily":[],"synonyms":["enjoy","savour"],"antonyms":["dread"],"tipVi":"Động từ theo sau bởi danh từ hoặc danh động từ, không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indifference', 'en-c1-32', 'indifference', '/ɪnˈdɪfərəns/', 'C1', 'sự thờ ơ; tính lãnh đạm; sự không quan tâm', 'n.', 'indifferent (adj.), indifferently (adv.)', 'Đồng nghĩa: apathy, unconcern · Trái nghĩa: concern, interest', 'Thường là danh từ không đếm được; đi với giới từ to khi chỉ sự lạnh nhạt đối với việc gì.', 'Her indifference surprised me when I shared my exciting news.', NULL, 'Sự lãnh đạm của cô ấy khiến tôi vô cùng ngạc nhiên khi tôi chia sẻ tin vui của mình.', '{"wordId":"indifference","ukIpa":"/ɪnˈdɪfərəns/","usIpa":"/ɪnˈdɪfərəns/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"A lack of interest, concern, or emotional response.","vi":"sự thờ ơ; tính lãnh đạm; sự không quan tâm"}],"examples":[{"en":"Her indifference surprised me when I shared my exciting news.","vi":"Sự lãnh đạm của cô ấy khiến tôi vô cùng ngạc nhiên khi tôi chia sẻ tin vui của mình.","audioKind":"ex"},{"en":"Public indifference to local elections can weaken accountability and reduce the quality of democratic representation.","vi":"Sự thờ ơ của công chúng đối với các cuộc bầu cử địa phương có thể làm suy yếu cơ chế giải trình và làm giảm chất lượng đại diện dân chủ.","audioKind":"ex2"}],"collocations":[{"en":"indifference to suffering","vi":"sự thờ ơ trước nỗi đau"},{"en":"public indifference","vi":"sự thờ ơ của công chúng"},{"en":"show indifference","vi":"thái độ thờ ơ"}],"wordFamily":["indifferent (adj.)","indifferently (adv.)"],"synonyms":["apathy","unconcern"],"antonyms":["concern","interest"],"tipVi":"Thường là danh từ không đếm được; đi với giới từ to khi chỉ sự lạnh nhạt đối với việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sheepish', 'en-c1-32', 'sheepish', '/ˈʃiːpɪʃ/', 'C1', 'xấu hổ; bẽn lẽn; ngượng ngùng do làm sai hoặc lỡ vụng về', 'adj.', 'sheepishly (adv.), sheepishness (n.)', 'Đồng nghĩa: embarrassed, abashed', 'Thường dùng khi cảm thấy xấu hổ do sơ suất, không đơn thuần mang nghĩa nhút nhát hay sợ sệt.', 'He gave a sheepish smile after spilling his juice.', NULL, 'Cậu ấy nở một nụ cười ngượng ngùng sau khi làm đổ nước ép.', '{"wordId":"sheepish","ukIpa":"/ˈʃiːpɪʃ/","usIpa":"/ˈʃiːpɪʃ/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Embarrassed because you have done something silly or wrong","vi":"xấu hổ; bẽn lẽn; ngượng ngùng do làm sai hoặc lỡ vụng về"}],"examples":[{"en":"He gave a sheepish smile after spilling his juice.","vi":"Cậu ấy nở một nụ cười ngượng ngùng sau khi làm đổ nước ép.","audioKind":"ex"},{"en":"Students may look sheepish after giving an incorrect answer, so teachers should respond with patience.","vi":"Học sinh có thể tỏ ra bẽn lẽn sau khi đưa ra câu trả lời sai, vì vậy giáo viên nên kiên nhẫn đáp lại.","audioKind":"ex2"}],"collocations":[{"en":"a sheepish smile","vi":"nụ cười ngượng ngùng"},{"en":"a sheepish grin","vi":"điệu cười bẽn lẽn"},{"en":"look sheepish","vi":"tỏ ra ngượng ngùng"}],"wordFamily":["sheepishly (adv.)","sheepishness (n.)"],"synonyms":["embarrassed","abashed"],"antonyms":[],"tipVi":"Thường dùng khi cảm thấy xấu hổ do sơ suất, không đơn thuần mang nghĩa nhút nhát hay sợ sệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indifferent', 'en-c1-32', 'indifferent', '/ɪnˈdɪfrənt/', 'C1', 'thờ ơ; lạnh nhạt; tầm thường; không có gì nổi bật', 'adj.', 'indifference (n.), indifferently (adv.)', 'Đồng nghĩa: unconcerned, apathetic · Trái nghĩa: concerned, interested', 'Thường dùng be indifferent to; trong đó to là giới từ.', 'Our cat remained indifferent to its expensive new toy.', NULL, 'Con mèo nhà chúng tôi vẫn tỏ ra thờ ơ với món đồ chơi đắt tiền mới mua của nó.', '{"wordId":"indifferent","ukIpa":"/ɪnˈdɪfrənt/","usIpa":"/ɪnˈdɪfrənt/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"showing little interest or concern","vi":"thờ ơ; lạnh nhạt"},{"pos":"adj.","en":"not particularly good in quality","vi":"tầm thường; không có gì nổi bật"}],"examples":[{"en":"Our cat remained indifferent to its expensive new toy.","vi":"Con mèo nhà chúng tôi vẫn tỏ ra thờ ơ với món đồ chơi đắt tiền mới mua của nó.","audioKind":"ex"},{"en":"People may appear indifferent to environmental problems when they believe their individual actions cannot make a difference.","vi":"Mọi người có thể tỏ ra thờ ơ với các vấn đề môi trường khi họ cho rằng hành động cá nhân của mình không thể tạo ra sự thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"indifferent to","vi":"thờ ơ với"},{"en":"remain indifferent","vi":"vẫn dửng dưng"},{"en":"indifferent performance","vi":"màn trình diễn tầm thường"}],"wordFamily":["indifference (n.)","indifferently (adv.)"],"synonyms":["unconcerned","apathetic"],"antonyms":["concerned","interested"],"tipVi":"Thường dùng be indifferent to; trong đó to là giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_temperament', 'en-c1-32', 'temperament', '/ˈtemprəmənt/', 'C1', 'tính tình, khí chất, bản tính', 'n.', 'temperamental (adj.), temperamentally (adv.)', 'Đồng nghĩa: disposition, nature', 'temperament chỉ tính cách, bản tính lâu dài; temper thường chỉ tính khí, đặc biệt là cơn thịnh nộ.', 'Our new puppy has a gentle temperament and rarely barks.', NULL, 'Chú cún mới của chúng tôi có tính tình hiền lành và rất ít khi sủa.', '{"wordId":"temperament","ukIpa":"/ˈtemprəmənt/","usIpa":"/ˈtemprəmənt/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"a person''s usual emotional nature and way of reacting","vi":"tính tình, khí chất, bản tính"}],"examples":[{"en":"Our new puppy has a gentle temperament and rarely barks.","vi":"Chú cún mới của chúng tôi có tính tình hiền lành và rất ít khi sủa.","audioKind":"ex"},{"en":"A calm temperament helps healthcare professionals communicate effectively with patients during stressful situations in busy hospitals.","vi":"Bản tính điềm tĩnh giúp các nhân viên y tế giao tiếp hiệu quả với bệnh nhân trong những tình huống căng thẳng tại các bệnh viện bận rộn.","audioKind":"ex2"}],"collocations":[{"en":"a calm temperament","vi":"tính cách điềm tĩnh"},{"en":"an artistic temperament","vi":"khí chất nghệ sĩ"},{"en":"by temperament","vi":"về mặt bản tính, theo thiên hướng"}],"wordFamily":["temperamental (adj.)","temperamentally (adv.)"],"synonyms":["disposition","nature"],"antonyms":[],"tipVi":"temperament chỉ tính cách, bản tính lâu dài; temper thường chỉ tính khí, đặc biệt là cơn thịnh nộ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wail', 'en-c1-32', 'wail', '/weɪl/', 'C1', 'khóc rống lên; kêu la thảm thiết; tiếng khóc thảm thiết; tiếng hú, tiếng kêu dài và cao', 'v.', 'wailing (n.)', 'Đồng nghĩa: howl', 'Nhấn mạnh tiếng khóc kéo dài và sắc nhọn, cũng có thể dùng để miêu tả tiếng còi hú.', 'The baby began to wail when her toy fell.', NULL, 'Em bé bắt đầu khóc thảm thiết khi đồ chơi của bé bị rơi.', '{"wordId":"wail","ukIpa":"/weɪl/","usIpa":"/weɪl/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"to cry loudly in pain, sadness, or distress","vi":"khóc rống lên; kêu la thảm thiết"},{"pos":"n.","en":"a long, high cry or sound expressing distress","vi":"tiếng khóc thảm thiết; tiếng hú, tiếng kêu dài và cao"}],"examples":[{"en":"The baby began to wail when her toy fell.","vi":"Em bé bắt đầu khóc thảm thiết khi đồ chơi của bé bị rơi.","audioKind":"ex"},{"en":"Residents heard sirens wailing throughout the night as emergency teams responded to the severe flooding.","vi":"Cư dân nghe thấy tiếng còi hú suốt đêm khi các đội ứng phó khẩn cấp xử lý trận lụt nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"wail in pain","vi":"khóc thảm thiết vì đau đớn"},{"en":"a piercing wail","vi":"tiếng khóc thét xé lòng"},{"en":"the wail of sirens","vi":"tiếng còi hú"}],"wordFamily":["wailing (n.)"],"synonyms":["howl"],"antonyms":[],"tipVi":"Nhấn mạnh tiếng khóc kéo dài và sắc nhọn, cũng có thể dùng để miêu tả tiếng còi hú.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indignant', 'en-c1-32', 'indignant', '/ɪnˈdɪɡnənt/', 'C1', 'căm phẫn; phẫn nộ (do cảm thấy bất công hoặc bị xúc phạm)', 'adj.', 'indignantly (adv.), indignation (n.)', 'Đồng nghĩa: outraged, resentful', 'Nhấn mạnh sự tức giận do bất công hoặc bị xúc phạm, không dùng để chỉ sự giận dữ chung chung.', 'She was indignant when someone pushed ahead in the queue.', NULL, 'Cô ấy vô cùng căm phẫn khi có kẻ chen ngang vào hàng người đang xếp.', '{"wordId":"indignant","ukIpa":"/ɪnˈdɪɡnənt/","usIpa":"/ɪnˈdɪɡnənt/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Angry because something seems unfair or insulting.","vi":"căm phẫn; phẫn nộ (do cảm thấy bất công hoặc bị xúc phạm)"}],"examples":[{"en":"She was indignant when someone pushed ahead in the queue.","vi":"Cô ấy vô cùng căm phẫn khi có kẻ chen ngang vào hàng người đang xếp.","audioKind":"ex"},{"en":"Residents were indignant about the council''s decision to close their only public swimming pool.","vi":"Người dân vô cùng phẫn nộ trước quyết định đóng cửa hồ bơi công cộng duy nhất của hội đồng thành phố.","audioKind":"ex2"}],"collocations":[{"en":"indignant about something","vi":"căm phẫn về điều gì"},{"en":"an indignant response","vi":"một phản ứng đầy phẫn nộ"},{"en":"indignant at the suggestion","vi":"căm phẫn trước lời đề nghị đó"}],"wordFamily":["indignantly (adv.)","indignation (n.)"],"synonyms":["outraged","resentful"],"antonyms":[],"tipVi":"Nhấn mạnh sự tức giận do bất công hoặc bị xúc phạm, không dùng để chỉ sự giận dữ chung chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rouse', 'en-c1-32', 'rouse', '/raʊz/', 'C1', 'đánh thức; làm tỉnh giấc; khuấy động; kích thích', 'v.', 'rousing (adj.)', 'Đồng nghĩa: awaken, stir · Trái nghĩa: soothe', 'Cụm rouse sb from sleep dùng để chỉ việc đánh thức; rouse interest dùng để chỉ việc khơi gợi hứng thú.', 'The smell of breakfast finally roused him from sleep.', NULL, 'Mùi thơm của bữa sáng cuối cùng đã đánh thức anh ấy khỏi giấc ngủ.', '{"wordId":"rouse","ukIpa":"/raʊz/","usIpa":"/raʊz/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"Wake someone or make them more alert.","vi":"đánh thức; làm tỉnh giấc"},{"pos":"v.","en":"Make someone feel a strong emotion or take action.","vi":"khuấy động; kích thích"}],"examples":[{"en":"The smell of breakfast finally roused him from sleep.","vi":"Mùi thơm của bữa sáng cuối cùng đã đánh thức anh ấy khỏi giấc ngủ.","audioKind":"ex"},{"en":"Powerful images of polluted rivers can rouse public concern and encourage stronger support for environmental protection.","vi":"Những hình ảnh ấn tượng về các dòng sông ô nhiễm có thể khuấy động sự quan tâm của công chúng và thúc đẩy sự ủng hộ mạnh mẽ hơn đối với công tác bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"rouse someone from sleep","vi":"đánh thức ai dậy khỏi giấc ngủ"},{"en":"rouse interest","vi":"khơi gợi sự quan tâm"},{"en":"rouse someone to action","vi":"thúc đẩy ai hành động"}],"wordFamily":["rousing (adj.)"],"synonyms":["awaken","stir"],"antonyms":["soothe"],"tipVi":"Cụm rouse sb from sleep dùng để chỉ việc đánh thức; rouse interest dùng để chỉ việc khơi gợi hứng thú.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dissatisfy', 'en-c1-32', 'dissatisfy', '/dɪsˈsætɪsfaɪ/', 'C1', 'làm không hài lòng; làm thất vọng', 'v.', 'dissatisfied (adj.), dissatisfaction (n.), satisfy (v.), satisfactory (adj.)', 'Đồng nghĩa: displease · Trái nghĩa: satisfy, please', 'Động từ ngoại động từ; trong văn phong hàng ngày thường dùng be dissatisfied with.', 'The small portions and slow service dissatisfied several guests.', NULL, 'Phần ăn ít và dịch vụ chậm chạp đã làm vài vị khách không hài lòng.', '{"wordId":"dissatisfy","ukIpa":"/dɪsˈsætɪsfaɪ/","usIpa":"/dɪsˈsætɪsfaɪ/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To leave someone feeling that something is not good enough.","vi":"làm không hài lòng; làm thất vọng"}],"examples":[{"en":"The small portions and slow service dissatisfied several guests.","vi":"Phần ăn ít và dịch vụ chậm chạp đã làm vài vị khách không hài lòng.","audioKind":"ex"},{"en":"Public transport services that repeatedly fail to meet basic standards are likely to dissatisfy regular commuters.","vi":"Dịch vụ giao thông công cộng liên tục không đáp ứng được các tiêu chuẩn cơ bản có khả năng làm những người đi làm thường xuyên cảm thấy bất mãn.","audioKind":"ex2"}],"collocations":[{"en":"dissatisfy customers","vi":"làm khách hàng không hài lòng"},{"en":"dissatisfy users","vi":"làm người dùng không hài lòng"}],"wordFamily":["dissatisfied (adj.)","dissatisfaction (n.)","satisfy (v.)","satisfactory (adj.)"],"synonyms":["displease"],"antonyms":["satisfy","please"],"tipVi":"Động từ ngoại động từ; trong văn phong hàng ngày thường dùng be dissatisfied with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curt', 'en-c1-32', 'curt', '/kɝːt/', 'C1', 'cộc lốc; ngắn ngủi và thô lỗ', 'adj.', 'curtly (adv.), curtness (n.)', 'Đồng nghĩa: abrupt, brusque · Trái nghĩa: courteous', 'Không chỉ mang nghĩa ngắn gọn mà còn thể hiện thái độ bất lịch sự; trong khi brief thường mang nghĩa trung lập.', 'His curt reply made me hesitate to ask again.', NULL, 'Câu trả lời cộc lốc của anh ấy khiến tôi ngần ngại không dám hỏi lại.', '{"wordId":"curt","ukIpa":"/kɜːt/","usIpa":"/kɝːt/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Using very few words in a way that seems rude.","vi":"cộc lốc; ngắn ngủi và thô lỗ"}],"examples":[{"en":"His curt reply made me hesitate to ask again.","vi":"Câu trả lời cộc lốc của anh ấy khiến tôi ngần ngại không dám hỏi lại.","audioKind":"ex"},{"en":"Curt responses from public service staff may discourage residents from seeking information about essential community support.","vi":"Những phản hồi cộc lốc từ nhân viên dịch vụ công có thể khiến cư dân nản lòng trong việc tìm kiếm thông tin về các khoản hỗ trợ cộng đồng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"a curt reply","vi":"câu trả lời cộc lốc"},{"en":"a curt nod","vi":"cái gật đầu lạnh lùng"},{"en":"a curt tone","vi":"giọng điệu cụt lủn"}],"wordFamily":["curtly (adv.)","curtness (n.)"],"synonyms":["abrupt","brusque"],"antonyms":["courteous"],"tipVi":"Không chỉ mang nghĩa ngắn gọn mà còn thể hiện thái độ bất lịch sự; trong khi brief thường mang nghĩa trung lập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_longing', 'en-c1-32', 'longing', '/ˈlɔːŋɪŋ/', 'C1', 'niềm khao khát; nỗi nhớ; thể hiện sự khao khát; mang nét mặt ngóng trông', 'n.', 'long (v.), longingly (adv.)', 'Đồng nghĩa: yearning, desire', 'Danh từ thường đi với giới từ for; để thể hiện mong muốn làm gì, có thể dùng cấu trúc to do.', 'She felt a sudden longing for her childhood home.', NULL, 'Cô ấy bất chợt cảm thấy nhớ nhà thời thơ ấu da diết.', '{"wordId":"longing","ukIpa":"/ˈlɒŋɪŋ/","usIpa":"/ˈlɔːŋɪŋ/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"A strong desire for someone or something","vi":"niềm khao khát; nỗi nhớ"},{"pos":"adj.","en":"Showing a strong desire for someone or something","vi":"thể hiện sự khao khát; mang nét mặt ngóng trông"}],"examples":[{"en":"She felt a sudden longing for her childhood home.","vi":"Cô ấy bất chợt cảm thấy nhớ nhà thời thơ ấu da diết.","audioKind":"ex"},{"en":"For many migrants, longing for familiar surroundings can make adaptation to a new culture more difficult.","vi":"Đối với nhiều người nhập cư, nỗi nhớ khung cảnh quen thuộc có thể khiến việc thích nghi với một nền văn hóa mới trở nên khó khăn hơn.","audioKind":"ex2"}],"collocations":[{"en":"a longing for home","vi":"nỗi nhớ nhà"},{"en":"a deep longing","vi":"khao khát mãnh liệt"},{"en":"a longing look","vi":"ánh mắt khao khát"}],"wordFamily":["long (v.)","longingly (adv.)"],"synonyms":["yearning","desire"],"antonyms":[],"tipVi":"Danh từ thường đi với giới từ for; để thể hiện mong muốn làm gì, có thể dùng cấu trúc to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gloom', 'en-c1-32', 'gloom', '/ɡluːm/', 'C1', 'sự tối tăm; bóng tối mờ mịt; nỗi buồn rầu; bầu không khí ảm đạm', 'n.', 'gloomy (adj.), gloomily (adv.), gloominess (n.)', 'Đồng nghĩa: dimness, despondency · Trái nghĩa: brightness, cheerfulness', 'Có thể chỉ ánh sáng lờ mờ hoặc tâm trạng, viễn cảnh tối tăm.', 'A tiny candle flickered in the gloom of the cellar.', NULL, 'Một ngọn nến nhỏ lدấp lóe trong bóng tối mờ mịt của tầng hầm.', '{"wordId":"gloom","ukIpa":"/ɡluːm/","usIpa":"/ɡluːm/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"Darkness or weak light that makes things difficult to see","vi":"sự tối tăm; bóng tối mờ mịt"},{"pos":"n.","en":"A feeling of sadness or lack of hope","vi":"nỗi buồn rầu; bầu không khí ảm đạm"}],"examples":[{"en":"A tiny candle flickered in the gloom of the cellar.","vi":"Một ngọn nến nhỏ lدấp lóe trong bóng tối mờ mịt của tầng hầm.","audioKind":"ex"},{"en":"Despite widespread economic gloom, investment in renewable energy continues to create opportunities for skilled workers.","vi":"Bất chấp bầu không khí ảm đạm của nền kinh tế nói chung, đầu tư vào năng lượng tái tạo vẫn tiếp tục tạo ra cơ hội cho lao động có tay nghề.","audioKind":"ex2"}],"collocations":[{"en":"in the gloom","vi":"trong bóng tối mờ mịt"},{"en":"economic gloom","vi":"sự ảm đạm kinh tế"},{"en":"a sense of gloom","vi":"cảm giác u sầu"},{"en":"doom and gloom","vi":"sự bi quan tuyệt vọng"}],"wordFamily":["gloomy (adj.)","gloomily (adv.)","gloominess (n.)"],"synonyms":["dimness","despondency"],"antonyms":["brightness","cheerfulness"],"tipVi":"Có thể chỉ ánh sáng lờ mờ hoặc tâm trạng, viễn cảnh tối tăm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_displeasure', 'en-c1-32', 'displeasure', '/dɪsˈpleʒər/', 'C1', 'sự không hài lòng; sự bất bình', 'n.', 'displease (v.), displeased (adj.), pleasure (n.)', 'Đồng nghĩa: dissatisfaction, annoyance · Trái nghĩa: pleasure, satisfaction', 'Thường là danh từ không đếm được, mang sắc thái trang trọng; hay đi với giới từ at hoặc with.', 'His frown showed his displeasure at the long delay.', NULL, 'Vết nhăn trán của ông ấy thể hiện sự không hài lòng trước việc chậm trễ kéo dài.', '{"wordId":"displeasure","ukIpa":"/dɪsˈpleʒə/","usIpa":"/dɪsˈpleʒər/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"a feeling of annoyance or dissatisfaction","vi":"sự không hài lòng; sự bất bình"}],"examples":[{"en":"His frown showed his displeasure at the long delay.","vi":"Vết nhăn trán của ông ấy thể hiện sự không hài lòng trước việc chậm trễ kéo dài.","audioKind":"ex"},{"en":"Residents expressed their displeasure at the council''s decision to reduce funding for local libraries.","vi":"Người dân đã bày tỏ sự bất bình trước quyết định cắt giảm ngân sách cho các thư viện địa phương của hội đồng thành phố.","audioKind":"ex2"}],"collocations":[{"en":"express displeasure","vi":"bày tỏ sự không hài lòng"},{"en":"show displeasure","vi":"thể hiện sự bất bình"},{"en":"displeasure at something","vi":"sự bất mãn đối với điều gì"}],"wordFamily":["displease (v.)","displeased (adj.)","pleasure (n.)"],"synonyms":["dissatisfaction","annoyance"],"antonyms":["pleasure","satisfaction"],"tipVi":"Thường là danh từ không đếm được, mang sắc thái trang trọng; hay đi với giới từ at hoặc with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fulfillment', 'en-c1-32', 'fulfillment', '/fʊlˈfɪlmənt/', 'C1', 'sự mãn nguyện; cảm giác thỏa mãn; sự hoàn thành; sự thực hiện', 'n.', 'fulfill (v.), fulfilled (adj.), fulfilling (adj.)', 'Đồng nghĩa: satisfaction · Trái nghĩa: dissatisfaction', 'Đây là cách viết Mỹ; tiếng Anh thường viết là fulfilment.', 'She finds fulfillment in teaching children to swim.', NULL, 'Cô ấy tìm thấy sự thỏa mãn trong việc dạy trẻ em bơi lội.', '{"wordId":"fulfillment","ukIpa":"/fʊlˈfɪlmənt/","usIpa":"/fʊlˈfɪlmənt/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"A feeling of satisfaction from doing something meaningful","vi":"sự mãn nguyện; cảm giác thỏa mãn"},{"pos":"n.","en":"The act of meeting a requirement or achieving something desired","vi":"sự hoàn thành; sự thực hiện"}],"examples":[{"en":"She finds fulfillment in teaching children to swim.","vi":"Cô ấy tìm thấy sự thỏa mãn trong việc dạy trẻ em bơi lội.","audioKind":"ex"},{"en":"For many employees, personal fulfillment matters as much as financial security when choosing a career.","vi":"Đối với nhiều nhân viên, sự thỏa mãn cá nhân cũng quan trọng không kém sự đảm bảo về tài chính khi lựa chọn nghề nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"personal fulfillment","vi":"sự thỏa mãn cá nhân"},{"en":"a sense of fulfillment","vi":"cảm giác thành tựu"},{"en":"fulfillment of obligations","vi":"việc thực hiện nghĩa vụ"},{"en":"order fulfillment","vi":"việc hoàn thành đơn hàng"}],"wordFamily":["fulfill (v.)","fulfilled (adj.)","fulfilling (adj.)"],"synonyms":["satisfaction"],"antonyms":["dissatisfaction"],"tipVi":"Đây là cách viết Mỹ; tiếng Anh thường viết là fulfilment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cutting', 'en-c1-32', 'cutting', '/ˈkʌtɪŋ/', 'C1', 'cay độc; sắc bén; làm tổn thương; bài báo cắt ra; mẩu tin cắt dán; đoạn đường đào; rãnh cắt qua đồi', 'adj.', 'cut (v.), cuttingly (adv.), cutter (n.)', NULL, 'Từ cutting được dùng ở Anh để chỉ bài báo cắt ra, trong khi Mỹ thường dùng clipping.', 'His cutting remark about her cooking spoiled the meal.', NULL, 'Nhận xét cay độc của anh ấy về món ăn cô nấu đã làm hỏng bữa ăn.', '{"wordId":"cutting","ukIpa":"/ˈkʌtɪŋ/","usIpa":"/ˈkʌtɪŋ/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Intended to hurt someone through harsh criticism or unkind remarks.","vi":"cay độc; sắc bén; làm tổn thương"},{"pos":"n.","en":"An article or picture cut out of a newspaper.","vi":"bài báo cắt ra; mẩu tin cắt dán"},{"pos":"n.","en":"A deep passage dug through land for a road or railway.","vi":"đoạn đường đào; rãnh cắt qua đồi"}],"examples":[{"en":"His cutting remark about her cooking spoiled the meal.","vi":"Nhận xét cay độc của anh ấy về món ăn cô nấu đã làm hỏng bữa ăn.","audioKind":"ex"},{"en":"Cutting comments from teachers can discourage students from asking questions and participating actively in class.","vi":"Những lời chê bai cay nghiệt từ giáo viên có thể khiến học sinh nản lòng, không dám đặt câu hỏi và tích cực tham gia xây dựng bài.","audioKind":"ex2"}],"collocations":[{"en":"cutting remark","vi":"lời nhận xét cay độc"},{"en":"newspaper cutting","vi":"mẩu tin cắt từ báo"},{"en":"railway cutting","vi":"đoạn đường sắt đào qua đồi"}],"wordFamily":["cut (v.)","cuttingly (adv.)","cutter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ cutting được dùng ở Anh để chỉ bài báo cắt ra, trong khi Mỹ thường dùng clipping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indebted', 'en-c1-32', 'indebted', '/ɪnˈdetɪd/', 'C1', 'biết ơn; mang ơn; mắc nợ; nợ nần', 'adj.', 'debt (n.), indebtedness (n.)', 'Đồng nghĩa: grateful, thankful · Trái nghĩa: ungrateful', 'Cấu trúc be indebted to sb for sth diễn tả lòng biết ơn đối với ai vì điều gì.', 'I am deeply indebted to you for your kindness.', NULL, 'Tôi vô cùng biết ơn sự tử tế của bạn.', '{"wordId":"indebted","ukIpa":"/ɪnˈdetɪd/","usIpa":"/ɪnˈdetɪd/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Grateful to someone for help or support.","vi":"biết ơn; mang ơn"},{"pos":"adj.","en":"Owing money to a person or organisation.","vi":"mắc nợ; nợ nần"}],"examples":[{"en":"I am deeply indebted to you for your kindness.","vi":"Tôi vô cùng biết ơn sự tử tế của bạn.","audioKind":"ex"},{"en":"Heavily indebted countries may struggle to invest adequately in public healthcare and education.","vi":"Các quốc gia đang gánh nợ ngập đầu có thể gặp khó khăn trong việc đầu tư thỏa đáng cho y tế và giáo dục công cộng.","audioKind":"ex2"}],"collocations":[{"en":"deeply indebted to","vi":"vô cùng biết ơn ai"},{"en":"indebted to someone for","vi":"mang ơn ai vì điều gì"},{"en":"heavily indebted","vi":"mắc nợ đầm đìa"}],"wordFamily":["debt (n.)","indebtedness (n.)"],"synonyms":["grateful","thankful"],"antonyms":["ungrateful"],"tipVi":"Cấu trúc be indebted to sb for sth diễn tả lòng biết ơn đối với ai vì điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regretful', 'en-c1-32', 'regretful', '/rɪˈɡretfəl/', 'C1', 'cảm thấy hối hận; cảm thấy tiếc nuối', 'adj.', 'regret (v.), regret (n.), regretfully (adv.), regrettable (adj.)', 'Đồng nghĩa: sorry, remorseful', 'regretful dùng để chỉ cảm giác hối hận/tiếc nuối của con người; regrettable dùng để chỉ sự việc gây ra sự đáng tiếc.', 'He looked regretful after speaking sharply to his sister.', NULL, 'Anh ấy tỏ ra hối hận sau khi nói năng gay gắt với em gái mình.', '{"wordId":"regretful","ukIpa":"/rɪˈɡretfəl/","usIpa":"/rɪˈɡretfəl/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling sorry about something that happened or something you did.","vi":"cảm thấy hối hận; cảm thấy tiếc nuối"}],"examples":[{"en":"He looked regretful after speaking sharply to his sister.","vi":"Anh ấy tỏ ra hối hận sau khi nói năng gay gắt với em gái mình.","audioKind":"ex"},{"en":"Some graduates feel regretful about choosing a degree solely for its expected financial rewards.","vi":"Một số sinh viên cảm thấy hối hận vì đã chọn một tấm bằng chỉ vì kỳ vọng về lợi ích tài chính.","audioKind":"ex2"}],"collocations":[{"en":"feel regretful","vi":"cảm thấy hối hận"},{"en":"a regretful smile","vi":"nụ cười mang nét tiếc nuối"},{"en":"regretful about a decision","vi":"hối hận về một quyết định"}],"wordFamily":["regret (v.)","regret (n.)","regretfully (adv.)","regrettable (adj.)"],"synonyms":["sorry","remorseful"],"antonyms":[],"tipVi":"regretful dùng để chỉ cảm giác hối hận/tiếc nuối của con người; regrettable dùng để chỉ sự việc gây ra sự đáng tiếc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quiver', 'en-c1-32', 'quiver', '/ˈkwɪv.ɚ/', 'C1', 'run rẩy; rung lên; sự run nhẹ; cái rung; ống đựng tên; bao tên', 'v.', NULL, 'Đồng nghĩa: tremble, shake', 'Thường chỉ những chuyển động rung nhanh và nhẹ; âm thanh giọng nói cũng có thể dùng quiver.', 'The puppy''s legs quivered as it crossed the slippery floor.', NULL, 'Đôi chân của chú chó con run lên khi nó bước qua sàn nhà trơn trượt.', '{"wordId":"quiver","ukIpa":"/ˈkwɪv.ə(r)/","usIpa":"/ˈkwɪv.ɚ/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"shake slightly with quick, small movements","vi":"run rẩy; rung lên"},{"pos":"n.","en":"a small, quick shaking movement","vi":"sự run nhẹ; cái rung"},{"pos":"n.","en":"a container used for carrying arrows","vi":"ống đựng tên; bao tên"}],"examples":[{"en":"The puppy''s legs quivered as it crossed the slippery floor.","vi":"Đôi chân của chú chó con run lên khi nó bước qua sàn nhà trơn trượt.","audioKind":"ex"},{"en":"A speaker''s voice may quiver under pressure, even when they have prepared thoroughly for a public presentation.","vi":"Giọng nói của người diễn thuyết có thể run lên dưới áp lực, ngay cả khi họ đã chuẩn bị rất kỹ lưỡng cho phần thuyết trình trước công chúng.","audioKind":"ex2"}],"collocations":[{"en":"quiver with fear","vi":"run lẩy bẩy vì sợ"},{"en":"a quivering voice","vi":"giọng nói run run"},{"en":"a quiver of excitement","vi":"cảm giác phấn khích rộn lên"}],"wordFamily":[],"synonyms":["tremble","shake"],"antonyms":[],"tipVi":"Thường chỉ những chuyển động rung nhanh và nhẹ; âm thanh giọng nói cũng có thể dùng quiver.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rejoice', 'en-c1-32', 'rejoice', '/rɪˈdʒɔɪs/', 'C1', 'vui mừng; hoan hỉ; ăn mừng', 'v.', 'rejoicing (n.)', 'Đồng nghĩa: celebrate, delight · Trái nghĩa: mourn', 'Đây là từ mang tính trang trọng; thường đi với cấu trúc "rejoice at/in" hoặc theo sau bởi mệnh đề "that".', 'We rejoiced when our missing cat finally came home.', NULL, 'Chúng tôi vô cùng vui mừng khi chú mèo mất tích cuối cùng đã trở về nhà.', '{"wordId":"rejoice","ukIpa":"/rɪˈdʒɔɪs/","usIpa":"/rɪˈdʒɔɪs/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"Feel or show great happiness about something.","vi":"vui mừng; hoan hỉ; ăn mừng"}],"examples":[{"en":"We rejoiced when our missing cat finally came home.","vi":"Chúng tôi vô cùng vui mừng khi chú mèo mất tích cuối cùng đã trở về nhà.","audioKind":"ex"},{"en":"Residents rejoiced at the reopening of their local library, which provides valuable educational resources.","vi":"Cư dân địa phương vô cùng vui mừng trước việc thư viện địa phương mở cửa trở lại, nơi cung cấp các nguồn tài nguyên giáo dục vô giá.","audioKind":"ex2"}],"collocations":[{"en":"rejoice at the news","vi":"vui mừng trước tin tức"},{"en":"rejoice in someone''s success","vi":"vui mừng trước thành công của ai đó"},{"en":"rejoice that","vi":"vui mừng vì..."}],"wordFamily":["rejoicing (n.)"],"synonyms":["celebrate","delight"],"antonyms":["mourn"],"tipVi":"Đây là từ mang tính trang trọng; thường đi với cấu trúc \"rejoice at/in\" hoặc theo sau bởi mệnh đề \"that\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_muster', 'en-c1-32', 'muster', '/ˈmʌstər/', 'C1', 'gắng sức; lấy hết (can đảm, sức mạnh); tập hợp; triệu tập; sự tập hợp; buổi điểm binh', 'v.', NULL, 'Đồng nghĩa: gather, summon', 'Cụm muster courage nghĩa là lấy hết can đảm; pass muster nghĩa là đạt yêu cầu.', 'I finally mustered the courage to ask for help.', NULL, 'Cuối cùng tôi cũng lấy hết can đảm để nhờ giúp đỡ.', '{"wordId":"muster","ukIpa":"/ˈmʌstə/","usIpa":"/ˈmʌstər/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"Gather the courage, strength, or support needed to do something.","vi":"gắng sức; lấy hết (can đảm, sức mạnh)"},{"pos":"v.","en":"Bring people together, especially for military duties.","vi":"tập hợp; triệu tập"},{"pos":"n.","en":"A gathering of people, especially soldiers, for inspection or duty.","vi":"sự tập hợp; buổi điểm binh"}],"examples":[{"en":"I finally mustered the courage to ask for help.","vi":"Cuối cùng tôi cũng lấy hết can đảm để nhờ giúp đỡ.","audioKind":"ex"},{"en":"Local authorities must muster sufficient public support before introducing major changes to urban transport systems.","vi":"Chính quyền địa phương phải tập hợp đủ sự ủng hộ từ công chúng trước khi đưa ra các thay đổi lớn đối với hệ thống giao thông đô thị.","audioKind":"ex2"}],"collocations":[{"en":"muster the courage","vi":"lấy hết can đảm"},{"en":"muster support","vi":"tập hợp sự ủng hộ"},{"en":"muster strength","vi":"tích tụ sức mạnh"},{"en":"pass muster","vi":"đạt tiêu chuẩn; đủ điều kiện"}],"wordFamily":[],"synonyms":["gather","summon"],"antonyms":[],"tipVi":"Cụm muster courage nghĩa là lấy hết can đảm; pass muster nghĩa là đạt yêu cầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_32_1', 'en-c1-32', 'Cách dùng “regretful” (adj.) — cảm thấy hối hận; cảm thấy tiếc nuối', 'feel regretful  ·  a regretful smile  ·  regretful about a decision', 'regretful dùng để chỉ cảm giác hối hận/tiếc nuối của con người; regrettable dùng để chỉ sự việc gây ra sự đáng tiếc.', 'Họ từ (Word Family): regret (v.), regret (n.), regretfully (adv.), regrettable (adj.) | Đồng nghĩa: sorry, remorseful', '[{"hanzi":"He looked regretful after speaking sharply to his sister.","pinyin":"","meaning":"Anh ấy tỏ ra hối hận sau khi nói năng gay gắt với em gái mình."},{"hanzi":"Some graduates feel regretful about choosing a degree solely for its expected financial rewards.","pinyin":"","meaning":"Một số sinh viên cảm thấy hối hận vì đã chọn một tấm bằng chỉ vì kỳ vọng về lợi ích tài chính."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_32_2', 'en-c1-32', 'Cách dùng “curt” (adj.) — cộc lốc; ngắn ngủi và thô lỗ', 'a curt reply  ·  a curt nod  ·  a curt tone', 'Không chỉ mang nghĩa ngắn gọn mà còn thể hiện thái độ bất lịch sự; trong khi brief thường mang nghĩa trung lập.', 'Họ từ (Word Family): curtly (adv.), curtness (n.) | Đồng nghĩa: abrupt, brusque · Trái nghĩa: courteous', '[{"hanzi":"His curt reply made me hesitate to ask again.","pinyin":"","meaning":"Câu trả lời cộc lốc của anh ấy khiến tôi ngần ngại không dám hỏi lại."},{"hanzi":"Curt responses from public service staff may discourage residents from seeking information about essential community support.","pinyin":"","meaning":"Những phản hồi cộc lốc từ nhân viên dịch vụ công có thể khiến cư dân nản lòng trong việc tìm kiếm thông tin về các khoản hỗ trợ cộng đồng thiết yếu."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_32_3', 'en-c1-32', 'Cách dùng “rejoice” (v.) — vui mừng; hoan hỉ; ăn mừng', 'rejoice at the news  ·  rejoice in someone''s success  ·  rejoice that', 'Đây là từ mang tính trang trọng; thường đi với cấu trúc "rejoice at/in" hoặc theo sau bởi mệnh đề "that".', 'Họ từ (Word Family): rejoicing (n.) | Đồng nghĩa: celebrate, delight · Trái nghĩa: mourn', '[{"hanzi":"We rejoiced when our missing cat finally came home.","pinyin":"","meaning":"Chúng tôi vô cùng vui mừng khi chú mèo mất tích cuối cùng đã trở về nhà."},{"hanzi":"Residents rejoiced at the reopening of their local library, which provides valuable educational resources.","pinyin":"","meaning":"Cư dân địa phương vô cùng vui mừng trước việc thư viện địa phương mở cửa trở lại, nơi cung cấp các nguồn tài nguyên giáo dục vô giá."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_32_4', 'en-c1-32', 'Cách dùng “rouse” (v.) — đánh thức; làm tỉnh giấc', 'rouse someone from sleep  ·  rouse interest  ·  rouse someone to action', 'Cụm rouse sb from sleep dùng để chỉ việc đánh thức; rouse interest dùng để chỉ việc khơi gợi hứng thú.', 'Họ từ (Word Family): rousing (adj.) | Đồng nghĩa: awaken, stir · Trái nghĩa: soothe', '[{"hanzi":"The smell of breakfast finally roused him from sleep.","pinyin":"","meaning":"Mùi thơm của bữa sáng cuối cùng đã đánh thức anh ấy khỏi giấc ngủ."},{"hanzi":"Powerful images of polluted rivers can rouse public concern and encourage stronger support for environmental protection.","pinyin":"","meaning":"Những hình ảnh ấn tượng về các dòng sông ô nhiễm có thể khuấy động sự quan tâm của công chúng và thúc đẩy sự ủng hộ mạnh mẽ hơn đối với công tác bảo vệ môi trường."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_32_1', 'en-c1-32', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_1_1', 'ten_c1_32_1', 'malice', 'There was no malice in his teasing smile.', 'There was no malice in his teasing smile.', '/ˈmælɪs/', 'Không có chút ác ý nào trong nụ cười đùa cợt của cô ấy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_1_2', 'ten_c1_32_1', 'elated', 'Lina was elated when she finally passed her driving test.', 'Lina was elated when she finally passed her driving test.', '/ɪˈleɪtɪd/', 'Lina vô cùng phấn khởi khi cuối cùng cô ấy cũng vượt qua kỳ thi sát hạch lái xe.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_1_3', 'ten_c1_32_1', 'fume', 'He fumed when muddy shoes stained his clean carpet.', 'He fumed when muddy shoes stained his clean carpet.', '/fjuːm/', 'Anh ấy nổi giận khi đôi giày dính bùn làm bẩn tấm thảm sạch của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_1_4', 'ten_c1_32_1', 'relish', 'I relish quiet mornings with tea and a book.', 'I relish quiet mornings with tea and a book.', '/ˈrelɪʃ/', 'Tôi rất tận hưởng những buổi sáng yên bình bên tách trà và cuốn sách.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_1_5', 'ten_c1_32_1', 'indifference', 'Her indifference surprised me when I shared my exciting news.', 'Her indifference surprised me when I shared my exciting news.', '/ɪnˈdɪfərəns/', 'Sự lãnh đạm của cô ấy khiến tôi vô cùng ngạc nhiên khi tôi chia sẻ tin vui của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_1_6', 'ten_c1_32_1', 'sheepish', 'He gave a sheepish smile after spilling his juice.', 'He gave a sheepish smile after spilling his juice.', '/ˈʃiːpɪʃ/', 'Cậu ấy nở một nụ cười ngượng ngùng sau khi làm đổ nước ép.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_1_7', 'ten_c1_32_1', 'indifferent', 'Our cat remained indifferent to its expensive new toy.', 'Our cat remained indifferent to its expensive new toy.', '/ɪnˈdɪfrənt/', 'Con mèo nhà chúng tôi vẫn tỏ ra thờ ơ với món đồ chơi đắt tiền mới mua của nó.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_1_8', 'ten_c1_32_1', 'temperament', 'Our new puppy has a gentle temperament and rarely barks.', 'Our new puppy has a gentle temperament and rarely barks.', '/ˈtemprəmənt/', 'Chú cún mới của chúng tôi có tính tình hiền lành và rất ít khi sủa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_32_1_1', 'en-c1-32', 'ten_c1_32_1', 'listening', 'listening', 'There was no malice in his teasing smile.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con mèo nhà chúng tôi vẫn tỏ ra thờ ơ với món đồ chơi đắt tiền mới mua của nó.","Chúng tôi vô cùng vui mừng khi chú mèo mất tích cuối cùng đã trở về nhà.","Anh ấy nổi giận khi đôi giày dính bùn làm bẩn tấm thảm sạch của mình.","Không có chút ác ý nào trong nụ cười đùa cợt của cô ấy."]'::jsonb, 3, 'There was no malice in his teasing smile. → Không có chút ác ý nào trong nụ cười đùa cợt của cô ấy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_32_1_2', 'en-c1-32', 'ten_c1_32_1', 'listening', 'listening', 'Lina was elated when she finally passed her driving test.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mùi thơm của bữa sáng cuối cùng đã đánh thức anh ấy khỏi giấc ngủ.","Anh ấy tỏ ra hối hận sau khi nói năng gay gắt với em gái mình.","Phần ăn ít và dịch vụ chậm chạp đã làm vài vị khách không hài lòng.","Lina vô cùng phấn khởi khi cuối cùng cô ấy cũng vượt qua kỳ thi sát hạch lái xe."]'::jsonb, 3, 'Lina was elated when she finally passed her driving test. → Lina vô cùng phấn khởi khi cuối cùng cô ấy cũng vượt qua kỳ thi sát hạch lái xe.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_32_1_3', 'en-c1-32', 'ten_c1_32_1', 'listening', 'listening', 'He fumed when muddy shoes stained his clean carpet.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi rất tận hưởng những buổi sáng yên bình bên tách trà và cuốn sách.","Anh ấy nổi giận khi đôi giày dính bùn làm bẩn tấm thảm sạch của mình.","Chú cún mới của chúng tôi có tính tình hiền lành và rất ít khi sủa.","Anh ấy tỏ ra hối hận sau khi nói năng gay gắt với em gái mình."]'::jsonb, 1, 'He fumed when muddy shoes stained his clean carpet. → Anh ấy nổi giận khi đôi giày dính bùn làm bẩn tấm thảm sạch của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_32_2', 'en-c1-32', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_2_1', 'ten_c1_32_2', 'malice', 'Schools should distinguish between careless remarks and comments made with malice when addressing conflicts among students.', 'Schools should distinguish between careless remarks and comments made with malice when addressing conflicts among students.', '/ˈmælɪs/', 'Nhà trường nên phân biệt giữa những lời nói vô tình và những bình luận mang tính ác ý khi giải quyết các mâu thuẫn giữa học sinh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_2_2', 'ten_c1_32_2', 'elated', 'Graduates may feel elated after securing their first job, although adjusting to workplace expectations can be challenging.', 'Graduates may feel elated after securing their first job, although adjusting to workplace expectations can be challenging.', '/ɪˈleɪtɪd/', 'Các cử nhân có thể cảm thấy vô cùng phấn khởi sau khi tìm được công việc đầu tiên, mặc dù việc thích nghi với các kỳ vọng tại nơi làm việc có thể là một thử thách.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_2_3', 'ten_c1_32_2', 'fume', 'Exposure to exhaust fumes can worsen respiratory conditions, particularly among children living near busy roads.', 'Exposure to exhaust fumes can worsen respiratory conditions, particularly among children living near busy roads.', '/fjuːm/', 'Việc tiếp xúc với khí thải có thể làm trầm trọng thêm các bệnh về đường hô hấp, đặc biệt là ở trẻ em sống gần các tuyến đường đông đúc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_2_4', 'ten_c1_32_2', 'relish', 'Many students relish the opportunity to study abroad because it exposes them to different cultures and perspectives.', 'Many students relish the opportunity to study abroad because it exposes them to different cultures and perspectives.', '/ˈrelɪʃ/', 'Nhiều sinh viên rất trân trọng cơ hội đi du học vì nó giúp họ tiếp 13c với các nền văn hóa và góc nhìn khác nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_2_5', 'ten_c1_32_2', 'indifference', 'Public indifference to local elections can weaken accountability and reduce the quality of democratic representation.', 'Public indifference to local elections can weaken accountability and reduce the quality of democratic representation.', '/ɪnˈdɪfərəns/', 'Sự thờ ơ của công chúng đối với các cuộc bầu cử địa phương có thể làm suy yếu cơ chế giải trình và làm giảm chất lượng đại diện dân chủ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_32_2_6', 'ten_c1_32_2', 'sheepish', 'Students may look sheepish after giving an incorrect answer, so teachers should respond with patience.', 'Students may look sheepish after giving an incorrect answer, so teachers should respond with patience.', '/ˈʃiːpɪʃ/', 'Học sinh có thể tỏ ra bẽn lẽn sau khi đưa ra câu trả lời sai, vì vậy giáo viên nên kiên nhẫn đáp lại.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_32_2_1', 'en-c1-32', 'ten_c1_32_2', 'listening', 'listening', 'Schools should distinguish between careless remarks and comments made with malice when addressing conflicts among students.', NULL, 'Trong câu vừa nghe, từ “malice” mang nghĩa nào sau đây?', '["bản thông số kỹ thuật; quy cách kỹ thuật","ác ý; tâm địa hiểm độc, ý định gây tổn thương","củng cố; gia cố","điều cấm kỵ; điều kiêng kỵ"]'::jsonb, 1, '“malice” (/ˈmælɪs/): ác ý; tâm địa hiểm độc, ý định gây tổn thương. Câu đầy đủ: Schools should distinguish between careless remarks and comments made with malice when addressing conflicts among students.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_32_2_2', 'en-c1-32', 'ten_c1_32_2', 'listening', 'listening', 'Graduates may feel elated after securing their first job, although adjusting to workplace expectations can be challenging.', NULL, 'Trong câu vừa nghe, từ “elated” mang nghĩa nào sau đây?', '["cực kỳ lớn; khổng lồ; mang tính chất thiên văn (giá cả, chi phí)","phấn khởi; vui sướng tột độ","lỗi lạc; kiệt xuất; đáng kính trọng","gặt hái kết quả; nhận thành quả từ những hành động trước đó"]'::jsonb, 1, '“elated” (/ɪˈleɪtɪd/): phấn khởi; vui sướng tột độ. Câu đầy đủ: Graduates may feel elated after securing their first job, although adjusting to workplace expectations can be challenging.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
