INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_1', 'en-c1-32', NULL, 'comprehensive_test', 'listening', 'malice', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ác ý; tâm địa hiểm độc, ý định gây tổn thương","bắt buộc; làm cho phải tuân theo","chuột túi vằn; wallaby (loài thú có túi giống kangaroo nhưng nhỏ hơn)","thuộc về phong kiến"]'::jsonb, 0, 'malice (/ˈmælɪs/) → ác ý; tâm địa hiểm độc, ý định gây tổn thương', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_2', 'en-c1-32', NULL, 'comprehensive_test', 'listening', 'Lina was elated when she finally passed her driving test.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cậu ấy nở một nụ cười ngượng ngùng sau khi làm đổ nước ép.","Lina vô cùng phấn khởi khi cuối cùng cô ấy cũng vượt qua kỳ thi sát hạch lái xe.","Chú cún mới của chúng tôi có tính tình hiền lành và rất ít khi sủa.","Chúng tôi vô cùng vui mừng khi chú mèo mất tích cuối cùng đã trở về nhà."]'::jsonb, 1, 'Lina was elated when she finally passed her driving test. → Lina vô cùng phấn khởi khi cuối cùng cô ấy cũng vượt qua kỳ thi sát hạch lái xe.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_3', 'en-c1-32', NULL, 'comprehensive_test', 'listening', 'fume', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mô tả; khắc họa; miêu tả qua nghệ thuật, hình ảnh hoặc ngôn từ","nổi giận đùng đùng; bực tức","chống chịu; kháng (không dễ bị hư hại hoặc tác động)","chất cặn; phần dư; thặng dư"]'::jsonb, 1, 'fume (/fjuːm/) → nổi giận đùng đùng; bực tức; khói độc; khí thải; hơi cay (thường dùng số nhiều)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_4', 'en-c1-32', NULL, 'comprehensive_test', 'listening', 'I relish quiet mornings with tea and a book.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi rất tận hưởng những buổi sáng yên bình bên tách trà và cuốn sách.","Anh ấy nổi giận khi đôi giày dính bùn làm bẩn tấm thảm sạch của mình.","Chúng tôi vô cùng vui mừng khi chú mèo mất tích cuối cùng đã trở về nhà.","Cuối cùng tôi cũng lấy hết can đảm để nhờ giúp đỡ."]'::jsonb, 0, 'I relish quiet mornings with tea and a book. → Tôi rất tận hưởng những buổi sáng yên bình bên tách trà và cuốn sách.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_5', 'en-c1-32', NULL, 'comprehensive_test', 'listening', 'indifference', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hình dung; vạch ra; dự tính (một tình huống hoặc sự kiện có thể xảy ra trong tương lai)","nhà tù","sức gắn kết; sự đoàn kết","sự thờ ơ; tính lãnh đạm; sự không quan tâm"]'::jsonb, 3, 'indifference (/ɪnˈdɪfərəns/) → sự thờ ơ; tính lãnh đạm; sự không quan tâm', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_6', 'en-c1-32', NULL, 'comprehensive_test', 'listening', 'He gave a sheepish smile after spilling his juice.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cậu ấy nở một nụ cười ngượng ngùng sau khi làm đổ nước ép.","Không có chút ác ý nào trong nụ cười đùa cợt của cô ấy.","Lina vô cùng phấn khởi khi cuối cùng cô ấy cũng vượt qua kỳ thi sát hạch lái xe.","Một ngọn nến nhỏ lدấp lóe trong bóng tối mờ mịt của tầng hầm."]'::jsonb, 0, 'He gave a sheepish smile after spilling his juice. → Cậu ấy nở một nụ cười ngượng ngùng sau khi làm đổ nước ép.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_7', 'en-c1-32', NULL, 'comprehensive_test', 'listening', 'indifferent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiếp thu và lĩnh hội hoàn toàn thông tin hoặc ý tưởng mới","phấn khởi; vui sướng tột độ","thờ ơ; lạnh nhạt","tàn phá; phá hủy nghiêm trọng"]'::jsonb, 2, 'indifferent (/ɪnˈdɪfrənt/) → thờ ơ; lạnh nhạt; tầm thường; không có gì nổi bật', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_8', 'en-c1-32', NULL, 'comprehensive_test', 'listening', 'Our new puppy has a gentle temperament and rarely barks.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chú cún mới của chúng tôi có tính tình hiền lành và rất ít khi sủa.","Lina vô cùng phấn khởi khi cuối cùng cô ấy cũng vượt qua kỳ thi sát hạch lái xe.","Anh ấy nổi giận khi đôi giày dính bùn làm bẩn tấm thảm sạch của mình.","Sự lãnh đạm của cô ấy khiến tôi vô cùng ngạc nhiên khi tôi chia sẻ tin vui của mình."]'::jsonb, 0, 'Our new puppy has a gentle temperament and rarely barks. → Chú cún mới của chúng tôi có tính tình hiền lành và rất ít khi sủa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
