INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_10', 'en-c1-32', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Embarrassed because you have done something silly or wrong”?', '["sheepish","relish","elated","rejoice"]'::jsonb, 0, 'sheepish (/ˈʃiːpɪʃ/) → xấu hổ; bẽn lẽn; ngượng ngùng do làm sai hoặc lỡ vụng về', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
