INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_18', 'en-c1-32', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should distinguish between careless remarks and comments made with malice when addressing conflicts among students.', 'Dựa vào câu trên, từ “malice” có nghĩa phù hợp nhất là gì?', '["kẽm","ác ý; tâm địa hiểm độc, ý định gây tổn thương","cúi xuống; rủ xuống","liều lĩnh; bất cẩn; không màng hậu quả"]'::jsonb, 1, 'malice: ác ý; tâm địa hiểm độc, ý định gây tổn thương. Dịch cả câu: Nhà trường nên phân biệt giữa những lời nói vô tình và những bình luận mang tính ác ý khi giải quyết các mâu thuẫn giữa học sinh.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_19', 'en-c1-32', NULL, 'comprehensive_test', 'reading', NULL, 'Graduates may feel elated after securing their first job, although adjusting to workplace expectations can be challenging.', 'Dựa vào câu trên, từ “elated” có nghĩa phù hợp nhất là gì?', '["sự xói mòn; sự bào mòn","che đậy; bao che; che giấu lỗi lầm","phấn khởi; vui sướng tột độ","cao cả; đầy hoài bão lớn lao"]'::jsonb, 2, 'elated: phấn khởi; vui sướng tột độ. Dịch cả câu: Các cử nhân có thể cảm thấy vô cùng phấn khởi sau khi tìm được công việc đầu tiên, mặc dù việc thích nghi với các kỳ vọng tại nơi làm việc có thể là một thử thách.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_20', 'en-c1-32', NULL, 'comprehensive_test', 'reading', NULL, 'Exposure to exhaust fumes can worsen respiratory conditions, particularly among children living near busy roads.', 'Dựa vào câu trên, từ “fume” có nghĩa phù hợp nhất là gì?', '["nổi giận đùng đùng; bực tức","xa hoa, hào phóng; thịnh soạn, đắt đỏ","làm cho thông thoáng; thông gió","biểu thị; có nghĩa là"]'::jsonb, 0, 'fume: nổi giận đùng đùng; bực tức; khói độc; khí thải; hơi cay (thường dùng số nhiều). Dịch cả câu: Việc tiếp xúc với khí thải có thể làm trầm trọng thêm các bệnh về đường hô hấp, đặc biệt là ở trẻ em sống gần các tuyến đường đông đúc.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_21', 'en-c1-32', NULL, 'comprehensive_test', 'reading', NULL, 'Many students relish the opportunity to study abroad because it exposes them to different cultures and perspectives.', 'Dựa vào câu trên, từ “relish” có nghĩa phù hợp nhất là gì?', '["cú đánh bóng trước khi chạm đất; cú volley","phụ; dự phòng; bổ trợ","tuân theo một quy tắc, thỏa thuận hoặc quyết định","tận hưởng; háo hức mong đợi"]'::jsonb, 3, 'relish: tận hưởng; háo hức mong đợi; niềm vui; sự thích thú; nước sốt rau củ hoặc trái cây ăn kèm. Dịch cả câu: Nhiều sinh viên rất trân trọng cơ hội đi du học vì nó giúp họ tiếp 13c với các nền văn hóa và góc nhìn khác nhau.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_22', 'en-c1-32', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “run rẩy; rung lên”', '["transistor","scalpel","quarry","quiver"]'::jsonb, 3, 'run rẩy; rung lên → quiver (/ˈkwɪv.ɚ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_23', 'en-c1-32', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vui mừng; hoan hỉ; ăn mừng”', '["rejoice","grove","restraint","intact"]'::jsonb, 0, 'vui mừng; hoan hỉ; ăn mừng → rejoice (/rɪˈdʒɔɪs/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_32_24', 'en-c1-32', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gắng sức; lấy hết (can đảm, sức mạnh)”', '["plume","muster","redundant","pharmaceutical"]'::jsonb, 1, 'gắng sức; lấy hết (can đảm, sức mạnh) → muster (/ˈmʌstər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-33', 'en', 'Bài 33: Cảm xúc & Tính cách (2) - CEFR C1', 'CEFR C1', 'C1 · Cảm xúc', '23 từ vựng Tiếng Anh CEFR C1 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5033, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boldness', 'en-c1-33', 'boldness', '/ˈboʊldnəs/', 'C1', 'sự dũng cảm; sự táo bạo; sự gan dạ; tính chất nổi bật; sự rực rỡ (về thị giác)', 'n.', 'bold (adj.), boldly (adv.)', 'Đồng nghĩa: courage, daring · Trái nghĩa: timidity', 'Có thể chỉ hành động táo bạo, hoặc cũng có thể chỉ thiết kế, màu sắc bắt mắt, nổi bật.', 'Her boldness impressed everyone when she volunteered to lead.', NULL, 'Sự dũng cảm của cô ấy đã gây ấn tượng với mọi người khi cô tình nguyện làm người dẫn dắt.', '{"wordId":"boldness","ukIpa":"/ˈbəʊldnəs/","usIpa":"/ˈboʊldnəs/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"confidence and willingness to take risks or challenge expectations","vi":"sự dũng cảm; sự táo bạo; sự gan dạ"},{"pos":"n.","en":"the quality of being visually strong and noticeable","vi":"tính chất nổi bật; sự rực rỡ (về thị giác)"}],"examples":[{"en":"Her boldness impressed everyone when she volunteered to lead.","vi":"Sự dũng cảm của cô ấy đã gây ấn tượng với mọi người khi cô tình nguyện làm người dẫn dắt.","audioKind":"ex"},{"en":"Addressing climate change requires political boldness, particularly when necessary reforms may initially attract limited public support.","vi":"Việc giải quyết biến đổi khí hậu đòi hỏi sự can đảm chính trị, đặc biệt là khi các cải cách cần thiết ban đầu có thể nhận được ít sự ủng hộ từ công chúng.","audioKind":"ex2"}],"collocations":[{"en":"show boldness","vi":"thể hiện sự dũng cảm"},{"en":"political boldness","vi":"lòng dũng cảm trong chính trị"},{"en":"the boldness of the colours","vi":"sự rực rỡ của màu sắc"}],"wordFamily":["bold (adj.)","boldly (adv.)"],"synonyms":["courage","daring"],"antonyms":["timidity"],"tipVi":"Có thể chỉ hành động táo bạo, hoặc cũng có thể chỉ thiết kế, màu sắc bắt mắt, nổi bật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apologetic', 'en-c1-33', 'apologetic', '/əˌpɑːləˈdʒetɪk/', 'C1', 'có ý hối lỗi; tỏm vẻ xin lỗi; ân hận', 'adj.', 'apology (n.), apologise (v.), apologetically (adv.)', 'Đồng nghĩa: sorry, regretful · Trái nghĩa: unapologetic', 'Thường đi kèm với giới từ about hoặc for để giải thích lý do vì sao cảm thấy có lỗi.', 'She gave an apologetic smile after spilling my tea.', NULL, 'Cô ấy nở một nụ cười hối lỗi sau khi làm đổ ly trà của tôi.', '{"wordId":"apologetic","ukIpa":"/əˌpɒləˈdʒetɪk/","usIpa":"/əˌpɑːləˈdʒetɪk/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Showing that you are sorry for something.","vi":"có ý hối lỗi; tỏm vẻ xin lỗi; ân hận"}],"examples":[{"en":"She gave an apologetic smile after spilling my tea.","vi":"Cô ấy nở một nụ cười hối lỗi sau khi làm đổ ly trà của tôi.","audioKind":"ex"},{"en":"An apologetic response to customer complaints is helpful, but companies must also address the underlying problems.","vi":"Phản hồi mang tính xin lỗi đối với các phàn nàn của khách hàng rất hữu ích, nhưng các công ty cũng phải giải quyết các vấn đề cốt lõi.","audioKind":"ex2"}],"collocations":[{"en":"an apologetic smile","vi":"nụ cười mang ý xin lỗi"},{"en":"an apologetic tone","vi":"giọng điệu xin lỗi"},{"en":"apologetic about","vi":"cảm thấy hối lỗi về"}],"wordFamily":["apology (n.)","apologise (v.)","apologetically (adv.)"],"synonyms":["sorry","regretful"],"antonyms":["unapologetic"],"tipVi":"Thường đi kèm với giới từ about hoặc for để giải thích lý do vì sao cảm thấy có lỗi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heighten', 'en-c1-33', 'heighten', '/ˈhaɪtən/', 'C1', 'làm tăng thêm; làm mạnh lên; gia tăng', 'v.', 'height (n.), high (adj.), heightened (adj.)', 'Đồng nghĩa: intensify, increase · Trái nghĩa: reduce, lessen', 'Thường dùng cho cảm xúc, nhận thức hoặc hiệu ứng được gia tăng, không dùng cho việc tăng chiều cao cơ thể.', 'The sudden silence only heightened my curiosity about the surprise.', NULL, 'Sự im lặng bất chợt càng làm cho sự tò mò của tôi về điều bất ngờ trở nên mạnh mẽ hơn.', '{"wordId":"heighten","ukIpa":"/ˈhaɪtən/","usIpa":"/ˈhaɪtən/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"to become stronger or make a feeling or effect stronger","vi":"làm tăng thêm; làm mạnh lên; gia tăng"}],"examples":[{"en":"The sudden silence only heightened my curiosity about the surprise.","vi":"Sự im lặng bất chợt càng làm cho sự tò mò của tôi về điều bất ngờ trở nên mạnh mẽ hơn.","audioKind":"ex"},{"en":"Repeated droughts may heighten public concern about water shortages and encourage governments to invest in conservation.","vi":"Các đợt hạn hán lặp đi lặp lại có thể làm gia tăng mối lo ngại của công chúng về tình trạng thiếu nước và khuyến khích các chính phủ đầu tư vào công tác bảo tồn.","audioKind":"ex2"}],"collocations":[{"en":"heighten awareness","vi":"nâng cao nhận thức"},{"en":"heighten tension","vi":"làm căng thẳng thêm"},{"en":"heighten concern","vi":"làm gia tăng mối lo ngại"}],"wordFamily":["height (n.)","high (adj.)","heightened (adj.)"],"synonyms":["intensify","increase"],"antonyms":["reduce","lessen"],"tipVi":"Thường dùng cho cảm xúc, nhận thức hoặc hiệu ứng được gia tăng, không dùng cho việc tăng chiều cao cơ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_humiliate', 'en-c1-33', 'humiliate', '/hjuːˈmɪlieɪt/', 'C1', 'làm nhục; làm bẽ mặt; sỉ nhục', 'v.', 'humiliation (n.), humiliating (adj.), humiliated (adj.)', 'Đồng nghĩa: shame, embarrass', 'Có mức độ nặng hơn từ embarrass, nhấn mạnh việc bị tổn thương lòng tự trọng và sự bẽ mặt.', 'Please don''t humiliate me in front of my friends.', NULL, 'Làm ơn đừng làm tôi bẽ mặt trước mặt bạn bè của tôi.', '{"wordId":"humiliate","ukIpa":"/hjuːˈmɪlieɪt/","usIpa":"/hjuːˈmɪlieɪt/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"to make someone feel deeply ashamed or foolish","vi":"làm nhục; làm bẽ mặt; sỉ nhục"}],"examples":[{"en":"Please don''t humiliate me in front of my friends.","vi":"Làm ơn đừng làm tôi bẽ mặt trước mặt bạn bè của tôi.","audioKind":"ex"},{"en":"Teachers should correct mistakes constructively rather than humiliate students who struggle with difficult tasks.","vi":"Giáo viên nên sửa lỗi mang tính xây dựng thay vì làm nhục những học sinh gặp khó khăn với các bài tập phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"humiliate someone publicly","vi":"làm bẽ mặt ai trước công chúng"},{"en":"feel humiliated","vi":"cảm thấy bị xúc phạm; cảm thấy bẽ mặt"},{"en":"deeply humiliating","vi":"vô cùng nhục nhã"}],"wordFamily":["humiliation (n.)","humiliating (adj.)","humiliated (adj.)"],"synonyms":["shame","embarrass"],"antonyms":[],"tipVi":"Có mức độ nặng hơn từ embarrass, nhấn mạnh việc bị tổn thương lòng tự trọng và sự bẽ mặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sorrowful', 'en-c1-33', 'sorrowful', '/ˈsɑːroʊfəl/', 'C1', 'buồn bã; đau buồn; đầy vẻ đau thương', 'adj.', 'sorrow (n.), sorrowfully (adv.)', 'Đồng nghĩa: sad, unhappy, mournful · Trái nghĩa: joyful, cheerful', 'Mang tính trang trọng hơn từ sad, thường dùng để miêu tả biểu cảm, giọng điệu hoặc lời tạm biệt.', 'She gave a sorrowful smile as the train departed.', NULL, 'Cô ấy nở một nụ cười đượm buồn khi chuyến tàu lăn bánh rời đi.', '{"wordId":"sorrowful","ukIpa":"/ˈsɒrəʊfəl/","usIpa":"/ˈsɑːroʊfəl/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling, showing, or causing deep sadness.","vi":"buồn bã; đau buồn; đầy vẻ đau thương"}],"examples":[{"en":"She gave a sorrowful smile as the train departed.","vi":"Cô ấy nở một nụ cười đượm buồn khi chuyến tàu lăn bánh rời đi.","audioKind":"ex"},{"en":"The film presents a sorrowful portrait of families separated by migration and economic hardship.","vi":"Bộ phim khắc họa một bức tranh đượm buồn về những gia đình phải chia lìa vì di cư và khó khăn kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"sorrowful expression","vi":"vẻ mặt buồn bã"},{"en":"sorrowful voice","vi":"giọng nói buồn rầu"},{"en":"sorrowful farewell","vi":"lời chia tay đượm buồn"}],"wordFamily":["sorrow (n.)","sorrowfully (adv.)"],"synonyms":["sad","unhappy","mournful"],"antonyms":["joyful","cheerful"],"tipVi":"Mang tính trang trọng hơn từ sad, thường dùng để miêu tả biểu cảm, giọng điệu hoặc lời tạm biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_agonize', 'en-c1-33', 'agonize', '/ˈæɡənaɪz/', 'C1', 'vò đầu bứt tai; băn khoăn lo lắng; trăn trở khổ sở', 'v.', 'agony (n.), agonizing (adj.), agonizingly (adv.)', 'Đồng nghĩa: worry, fret', 'Thường dùng cấu trúc agonize over hoặc agonize about; tiếng Anh-Anh cũng có thể viết là agonise.', 'I agonized over which course to choose all weekend.', NULL, 'Cả cuối tuần, tôi cứ trăn trở mãi không biết nên chọn môn học nào.', '{"wordId":"agonize","ukIpa":"/ˈæɡənaɪz/","usIpa":"/ˈæɡənaɪz/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"Worry intensely while trying to make a difficult decision","vi":"vò đầu bứt tai; băn khoăn lo lắng; trăn trở khổ sở"}],"examples":[{"en":"I agonized over which course to choose all weekend.","vi":"Cả cuối tuần, tôi cứ trăn trở mãi không biết nên chọn môn học nào.","audioKind":"ex"},{"en":"Many graduates agonize over whether to pursue further education or enter an increasingly competitive job market.","vi":"Nhiều sinh viên tốt nghiệp phải trăn trở rất nhiều về việc nên tiếp tục học lên cao hay bước vào thị trường lao động đang cạnh tranh ngày càng khốc liệt.","audioKind":"ex2"}],"collocations":[{"en":"agonize over a decision","vi":"trăn trở về một quyết định"},{"en":"agonize about the future","vi":"lo lắng về tương lai"}],"wordFamily":["agony (n.)","agonizing (adj.)","agonizingly (adv.)"],"synonyms":["worry","fret"],"antonyms":[],"tipVi":"Thường dùng cấu trúc agonize over hoặc agonize about; tiếng Anh-Anh cũng có thể viết là agonise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resolutely', 'en-c1-33', 'resolutely', '/ˈrezəluːtli/', 'C1', 'một cách kiên quyết; kiên định', 'adv.', 'resolute (adj.), resolution (n.), resolve (v.)', 'Đồng nghĩa: firmly, determinedly · Trái nghĩa: hesitantly', 'Đây là trạng từ; dạng tính từ tương ứng là resolute.', 'Despite the rain, she walked resolutely towards the shelter.', NULL, 'Bất chấp trời mưa, cô ấy vẫn kiên quyết bước về phía mái hiên.', '{"wordId":"resolutely","ukIpa":"/ˈrezəluːtli/","usIpa":"/ˈrezəluːtli/","cefr":"C1","topic":"emotion","senses":[{"pos":"adv.","en":"In a determined way, without giving up or changing course","vi":"một cách kiên quyết; kiên định"}],"examples":[{"en":"Despite the rain, she walked resolutely towards the shelter.","vi":"Bất chấp trời mưa, cô ấy vẫn kiên quyết bước về phía mái hiên.","audioKind":"ex"},{"en":"Governments must act resolutely to protect endangered habitats, even when conservation measures face strong opposition.","vi":"Chính phủ phải hành động một cách kiên quyết để bảo vệ các sinh cảnh đang gặp nguy hiểm, ngay cả khi các biện pháp bảo tồn vấp phải sự phản đối mạnh mẽ.","audioKind":"ex2"}],"collocations":[{"en":"act resolutely","vi":"hành động kiên quyết"},{"en":"resolutely oppose","vi":"kiên quyết phản đối"},{"en":"resolutely refuse","vi":"kiên quyết từ chối"}],"wordFamily":["resolute (adj.)","resolution (n.)","resolve (v.)"],"synonyms":["firmly","determinedly"],"antonyms":["hesitantly"],"tipVi":"Đây là trạng từ; dạng tính từ tương ứng là resolute.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_haunt', 'en-c1-33', 'haunt', '/hɔːnt/', 'C1', 'ám ảnh; làm vương vất trong tâm trí; ma ám; nơi hay lui tới', 'v.', 'haunted (adj.), haunting (adj.)', NULL, 'Đóng vai trò là động từ đi thẳng với tân ngữ; be haunted by nghĩa là chịu sự ám ảnh.', 'That embarrassing mistake still haunts me before every presentation.', NULL, 'Sai lầm đáng xấu hổ đó vẫn cứ ám ảnh tôi trước mỗi buổi thuyết trình.', '{"wordId":"haunt","ukIpa":"/hɔːnt/","usIpa":"/hɔːnt/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"to keep returning to someone''s mind and causing distress","vi":"ám ảnh; làm vương vất trong tâm trí"},{"pos":"v.","en":"for a ghost to appear repeatedly in a place","vi":"ma ám"},{"pos":"n.","en":"a place someone visits frequently","vi":"nơi hay lui tới"}],"examples":[{"en":"That embarrassing mistake still haunts me before every presentation.","vi":"Sai lầm đáng xấu hổ đó vẫn cứ ám ảnh tôi trước mỗi buổi thuyết trình.","audioKind":"ex"},{"en":"The consequences of poor urban planning can haunt communities long after the original decisions are made.","vi":"Hậu quả của việc quy hoạch đô thị kém có thể tiếp tục ám ảnh các cộng đồng lâu dài sau khi các quyết định ban đầu được đưa ra.","audioKind":"ex2"}],"collocations":[{"en":"be haunted by memories","vi":"bị ký ức ám ảnh"},{"en":"haunt an old house","vi":"ám ảnh một ngôi nhà cổ"},{"en":"a favourite haunt","vi":"nơi yêu thích hay lui tới"}],"wordFamily":["haunted (adj.)","haunting (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đóng vai trò là động từ đi thẳng với tân ngữ; be haunted by nghĩa là chịu sự ám ảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_touchy', 'en-c1-33', 'touchy', '/ˈtʌtʃi/', 'C1', 'dễ tự ái; nhạy cảm; khó giải quyết', 'adj.', 'touchiness (n.)', 'Đồng nghĩa: sensitive, irritable · Trái nghĩa: easy-going', 'Touchy chỉ tính hay cáu giận; touched chỉ trạng thái xúc động.', 'My brother gets touchy when anyone criticises his cooking.', NULL, 'Anh trai tôi rất hay nổi giận khi có ai đó chê bai món ăn anh ấy nấu.', '{"wordId":"touchy","ukIpa":"/ˈtʌtʃi/","usIpa":"/ˈtʌtʃi/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Easily upset or offended, especially by criticism.","vi":"dễ tự ái; nhạy cảm"},{"pos":"adj.","en":"Likely to cause upset or disagreement unless handled carefully.","vi":"nhạy cảm; khó giải quyết"}],"examples":[{"en":"My brother gets touchy when anyone criticises his cooking.","vi":"Anh trai tôi rất hay nổi giận khi có ai đó chê bai món ăn anh ấy nấu.","audioKind":"ex"},{"en":"Pay differences remain a touchy subject in many workplaces, making open discussions about fairness particularly difficult.","vi":"Sự chênh lệch tiền lương vẫn là một chủ đề nhạy cảm ở nhiều nơi làm việc, khiến việc bàn bạc cởi mở về tính công bằng trở nên vô cùng khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"touchy about criticism","vi":"nhạy cảm với những lời chỉ trích"},{"en":"a touchy subject","vi":"một chủ đề nhạy cảm"},{"en":"a touchy issue","vi":"một vấn đề gai góc nhạy cảm"}],"wordFamily":["touchiness (n.)"],"synonyms":["sensitive","irritable"],"antonyms":["easy-going"],"tipVi":"Touchy chỉ tính hay cáu giận; touched chỉ trạng thái xúc động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bleak', 'en-c1-33', 'bleak', '/bliːk/', 'C1', 'u ám; ảm đạm; không có hy vọng; hoang vắng; lạnh lẽo; trơ trọi', 'adj.', 'bleakness (n.), bleakly (adv.)', 'Đồng nghĩa: gloomy, unpromising · Trái nghĩa: promising, hopeful', 'Có thể dùng để miêu tả cả khung cảnh thiên nhiên hoang sơ lạnh lẽo lẫn viễn cảnh tương lai mịt mờ.', 'Without enough rain, the farm faces a bleak future.', NULL, 'Không có đủ mưa, trang trại đang đối mặt với một tương lai ảm đạm.', '{"wordId":"bleak","ukIpa":"/bliːk/","usIpa":"/bliːk/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"offering little hope of improvement or success","vi":"u ám; ảm đạm; không có hy vọng"},{"pos":"adj.","en":"cold, bare, and unwelcoming","vi":"hoang vắng; lạnh lẽo; trơ trọi"}],"examples":[{"en":"Without enough rain, the farm faces a bleak future.","vi":"Không có đủ mưa, trang trại đang đối mặt với một tương lai ảm đạm.","audioKind":"ex"},{"en":"Employment prospects remain bleak in rural areas where traditional industries have declined and investment is limited.","vi":"Triển vọng việc làm vẫn ảm đạm ở các vùng nông thôn nơi các ngành công nghiệp truyền thống suy giảm và đầu tư hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"bleak future","vi":"tương lai ảm đạm"},{"en":"bleak outlook","vi":"triển vọng bi quan"},{"en":"bleak landscape","vi":"cảnh quan hoang vắng"}],"wordFamily":["bleakness (n.)","bleakly (adv.)"],"synonyms":["gloomy","unpromising"],"antonyms":["promising","hopeful"],"tipVi":"Có thể dùng để miêu tả cả khung cảnh thiên nhiên hoang sơ lạnh lẽo lẫn viễn cảnh tương lai mịt mờ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weary', 'en-c1-33', 'weary', '/ˈwɪri/', 'C1', 'mệt mỏi; kiệt sức; chán ngấy; mệt mỏi vì điều gì kéo dài; làm cho mệt mỏi; khiến chán nản', 'adj.', 'weariness (n.), wearily (adv.), wearisome (adj.)', 'Đồng nghĩa: tired, exhausted · Trái nghĩa: refreshed, energetic', 'weary có nghĩa là mệt mỏi; cần phân biệt với wary có nghĩa là cảnh giác, hãy chú ý chính tả.', 'The weary hikers rested beside a stream before sunset.', NULL, 'Những người đi bộ đường dài mệt mỏi đã nghỉ ngơi bên dòng suối trước khi hoàng hôn buông xuống.', '{"wordId":"weary","ukIpa":"/ˈwɪəri/","usIpa":"/ˈwɪri/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Very tired, especially after prolonged effort","vi":"mệt mỏi; kiệt sức"},{"pos":"adj.","en":"No longer interested in something because it continues too long","vi":"chán ngấy; mệt mỏi vì điều gì kéo dài"},{"pos":"v.","en":"To make someone tired or become tired of something","vi":"làm cho mệt mỏi; khiến chán nản"}],"examples":[{"en":"The weary hikers rested beside a stream before sunset.","vi":"Những người đi bộ đường dài mệt mỏi đã nghỉ ngơi bên dòng suối trước khi hoàng hôn buông xuống.","audioKind":"ex"},{"en":"Commuters who endure long journeys often arrive home too weary to exercise or spend quality time with family.","vi":"Những người đi làm phải chịu đựng hành trình dài thường trở về nhà trong trạng thái kiệt sức, không còn sức tập thể dục hay dành thời gian chất lượng cho gia đình.","audioKind":"ex2"}],"collocations":[{"en":"weary travellers","vi":"lữ khách mệt mỏi"},{"en":"weary of","vi":"chán ngấy với"},{"en":"grow weary","vi":"ngày càng mệt mỏi"}],"wordFamily":["weariness (n.)","wearily (adv.)","wearisome (adj.)"],"synonyms":["tired","exhausted"],"antonyms":["refreshed","energetic"],"tipVi":"weary có nghĩa là mệt mỏi; cần phân biệt với wary có nghĩa là cảnh giác, hãy chú ý chính tả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exuberant', 'en-c1-33', 'exuberant', '/ɪɡˈzuːbərənt/', 'C1', 'tràn đầy năng lượng, phấn khởi và vui vẻ; nhiệt huyết; mọc tươi tốt; trang trí lộng lẫy và giàu trí tưởng tượng', 'adj.', 'exuberance (n.), exuberantly (adv.)', 'Đồng nghĩa: ebullient, high-spirited · Trái nghĩa: subdued', 'Nét nghĩa cốt lõi là mức độ năng lượng hoặc sự phong phú cao, không mang nghĩa ''hoa hòe hoa sói''.', 'The exuberant puppy bounced around the garden all morning.', NULL, 'Chú chó con tràn đầy năng lượng cứ nhảy quanh khu vườn suốt cả buổi sáng.', '{"wordId":"exuberant","ukIpa":"/ɪɡˈzjuːbərənt/","usIpa":"/ɪɡˈzuːbərənt/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"full of energy, excitement, and happiness","vi":"tràn đầy năng lượng, phấn khởi và vui vẻ; nhiệt huyết"},{"pos":"adj.","en":"growing abundantly or richly decorated and imaginative","vi":"mọc tươi tốt; trang trí lộng lẫy và giàu trí tưởng tượng"}],"examples":[{"en":"The exuberant puppy bounced around the garden all morning.","vi":"Chú chó con tràn đầy năng lượng cứ nhảy quanh khu vườn suốt cả buổi sáng.","audioKind":"ex"},{"en":"Exuberant celebrations at international sporting events can create a powerful sense of shared identity among spectators.","vi":"Các hoạt động kỷ niệm sôi nổi tại các sự kiện thể thao quốc tế có thể tạo ra ý thức gắn kết mạnh mẽ giữa các khán giả.","audioKind":"ex2"}],"collocations":[{"en":"exuberant enthusiasm","vi":"sự nhiệt tình cao độ"},{"en":"an exuberant personality","vi":"tính cách sôi nổi, nhiệt huyết"},{"en":"exuberant growth","vi":"sự sinh trưởng tươi tốt"}],"wordFamily":["exuberance (n.)","exuberantly (adv.)"],"synonyms":["ebullient","high-spirited"],"antonyms":["subdued"],"tipVi":"Nét nghĩa cốt lõi là mức độ năng lượng hoặc sự phong phú cao, không mang nghĩa ''hoa hòe hoa sói''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scornful', 'en-c1-33', 'scornful', '/ˈskɔːrnfəl/', 'C1', 'khinh miệt; coi thường', 'adj.', 'scorn (n.), scorn (v.), scornfully (adv.)', 'Đồng nghĩa: contemptuous, disdainful · Trái nghĩa: respectful, admiring', 'Thường dùng scornful of, thể hiện thái độ không coi trọng ai hoặc điều gì.', 'He gave my handmade kite a scornful look.', NULL, 'Anh ấy nhìn cái diều tôi tự làm với ánh mắt khinh miệt.', '{"wordId":"scornful","ukIpa":"/ˈskɔːnfəl/","usIpa":"/ˈskɔːrnfəl/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"showing that you think someone or something deserves no respect","vi":"khinh miệt; coi thường"}],"examples":[{"en":"He gave my handmade kite a scornful look.","vi":"Anh ấy nhìn cái diều tôi tự làm với ánh mắt khinh miệt.","audioKind":"ex"},{"en":"Scornful responses from teachers can discourage students from asking questions and reduce their confidence in class.","vi":"Những phản ứng khinh miệt từ giáo viên có thể khiến học sinh nhụt chí không dám đặt câu hỏi và làm giảm tự tin của các em trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"a scornful look","vi":"ánh mắt khinh miệt"},{"en":"scornful of advice","vi":"coi thường lời khuyên"},{"en":"a scornful laugh","vi":"tiếng cười khinh miệt"}],"wordFamily":["scorn (n.)","scorn (v.)","scornfully (adv.)"],"synonyms":["contemptuous","disdainful"],"antonyms":["respectful","admiring"],"tipVi":"Thường dùng scornful of, thể hiện thái độ không coi trọng ai hoặc điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crave', 'en-c1-33', 'crave', '/kreɪv/', 'C1', 'khao khát; thèm thuồng', 'v.', 'craving (n.)', 'Đồng nghĩa: desire, long for, yearn for', 'Kết hợp trực tiếp với tân ngữ: crave something, không dùng giới từ for.', 'After the long walk, I craved a warm meal.', NULL, 'Sau chuyến đi bộ dài, tôi rất thèm một bữa ăn nóng hổi.', '{"wordId":"crave","ukIpa":"/kreɪv/","usIpa":"/kreɪv/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To want something very strongly.","vi":"khao khát; thèm thuồng"}],"examples":[{"en":"After the long walk, I craved a warm meal.","vi":"Sau chuyến đi bộ dài, tôi rất thèm một bữa ăn nóng hổi.","audioKind":"ex"},{"en":"Many urban residents crave contact with nature, highlighting the importance of accessible parks and green spaces.","vi":"Nhiều cư dân thành thị khao khát được kết nối với thiên nhiên, điều này nhấn mạnh tầm quan trọng của các công viên và không gian xanh dễ tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"crave attention","vi":"khao khát sự chú ý"},{"en":"crave approval","vi":"khao khát sự công nhận"},{"en":"crave sweet foods","vi":"rất thèm đồ ngọt"}],"wordFamily":["craving (n.)"],"synonyms":["desire","long for","yearn for"],"antonyms":[],"tipVi":"Kết hợp trực tiếp với tân ngữ: crave something, không dùng giới từ for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shriek', 'en-c1-33', 'shriek', '/ʃriːk/', 'C1', 'thét lên; kêu rít lên; tiếng thét; tiếng kêu rít', 'v.', NULL, 'Đồng nghĩa: scream, squeal', 'shriek nhấn mạnh âm thanh sắc và cao, có thể do sợ hãi hoặc phấn khích.', 'The children shrieked with delight as the sprinkler started.', NULL, 'Lũ trẻ hét lên vui sướng khi hệ thống phun nước khởi động.', '{"wordId":"shriek","ukIpa":"/ʃriːk/","usIpa":"/ʃriːk/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To make a sudden, loud, high sound with your voice.","vi":"thét lên; kêu rít lên"},{"pos":"n.","en":"A sudden, loud, high sound made by a person.","vi":"tiếng thét; tiếng kêu rít"}],"examples":[{"en":"The children shrieked with delight as the sprinkler started.","vi":"Lũ trẻ hét lên vui sướng khi hệ thống phun nước khởi động.","audioKind":"ex"},{"en":"Visitors'' sudden shrieks can disturb sensitive wildlife, so guides should encourage quiet behaviour in protected natural areas.","vi":"Tiếng thét bất ngờ của du khách có thể làm hoảng sợ động vật hoang dã, vì vậy hướng dẫn viên nên khuyến khích giữ trật tự trong các khu bảo tồn thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"shriek with delight","vi":"hét lên vì vui sướng"},{"en":"let out a shriek","vi":"bật ra một tiếng thét"},{"en":"a piercing shriek","vi":"tiếng thét chói tai"}],"wordFamily":[],"synonyms":["scream","squeal"],"antonyms":[],"tipVi":"shriek nhấn mạnh âm thanh sắc và cao, có thể do sợ hãi hoặc phấn khích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_everlasting', 'en-c1-33', 'everlasting', '/ˌevərˈlæstɪŋ/', 'C1', 'vĩnh cửu; đời đời; kéo dài mãi mãi', 'adj.', 'everlastingly (adv.)', 'Đồng nghĩa: eternal, endless · Trái nghĩa: temporary, fleeting', 'Sắc thái mạnh hơn long-lasting, thường dùng cho các khái niệm trừu tượng như tình yêu hay tình bạn.', 'They promised each other everlasting friendship beneath the old tree.', NULL, 'Họ hứa hẹn với nhau về một tình bạn vĩnh cửu dưới tán cây cổ thụ.', '{"wordId":"everlasting","ukIpa":"/ˌevəˈlɑːstɪŋ/","usIpa":"/ˌevərˈlæstɪŋ/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Lasting forever or seeming never to end.","vi":"vĩnh cửu; đời đời; kéo dài mãi mãi"}],"examples":[{"en":"They promised each other everlasting friendship beneath the old tree.","vi":"Họ hứa hẹn với nhau về một tình bạn vĩnh cửu dưới tán cây cổ thụ.","audioKind":"ex"},{"en":"Although digital storage appears to offer everlasting access, files can become unreadable as technology changes.","vi":"Mặc dù kho lưu trữ kỹ thuật số có vẻ mang lại khả năng truy cập vĩnh viễn, nhưng các tệp tin vẫn có thể trở nên không đọc được khi công nghệ thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"everlasting love","vi":"tình yêu vĩnh cửu"},{"en":"everlasting friendship","vi":"tình bạn bền vững muôn thuở"},{"en":"everlasting life","vi":"sự sống vĩnh hằng"}],"wordFamily":["everlastingly (adv.)"],"synonyms":["eternal","endless"],"antonyms":["temporary","fleeting"],"tipVi":"Sắc thái mạnh hơn long-lasting, thường dùng cho các khái niệm trừu tượng như tình yêu hay tình bạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_agitation', 'en-c1-33', 'agitation', '/ˌædʒɪˈteɪʃən/', 'C1', 'sự bồn chồn; sự lo âu; sự kích động; sự vận động; sự biểu tình đòi thay đổi chính trị hoặc xã hội; sự khuấy động; sự lắc đều một chất', 'n.', 'agitate (v.), agitated (adj.), agitator (n.)', NULL, 'Thường là danh từ không đếm được; có thể dùng để chỉ trạng thái cảm xúc bất an hoặc hành động khuấy lắc.', 'Her agitation grew as she searched for her missing keys.', NULL, 'Cô ấy ngày càng trở nên bồn chồn khi tìm kiếm chìa khóa bị thất lạc của mình.', '{"wordId":"agitation","ukIpa":"/ˌædʒɪˈteɪʃən/","usIpa":"/ˌædʒɪˈteɪʃən/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"A state of worry or excitement that prevents calm behaviour.","vi":"sự bồn chồn; sự lo âu; sự kích động"},{"pos":"n.","en":"Organised efforts to persuade people to demand political or social change.","vi":"sự vận động; sự biểu tình đòi thay đổi chính trị hoặc xã hội"},{"pos":"n.","en":"The action of shaking or stirring a substance.","vi":"sự khuấy động; sự lắc đều một chất"}],"examples":[{"en":"Her agitation grew as she searched for her missing keys.","vi":"Cô ấy ngày càng trở nên bồn chồn khi tìm kiếm chìa khóa bị thất lạc của mình.","audioKind":"ex"},{"en":"Prolonged exposure to traffic noise may increase agitation and reduce residents'' ability to concentrate at home.","vi":"Việc tiếp xúc lâu dài với tiếng ồn giao thông có thể làm gia tăng sự bồn chồn và làm giảm khả năng tập trung ở nhà của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"in a state of agitation","vi":"trong trạng thái bồn chồn"},{"en":"political agitation","vi":"sự vận động chính trị"},{"en":"gentle agitation","vi":"sự khuấy nhẹ"}],"wordFamily":["agitate (v.)","agitated (adj.)","agitator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; có thể dùng để chỉ trạng thái cảm xúc bất an hoặc hành động khuấy lắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ominous', 'en-c1-33', 'ominous', '/ˈɑːmɪnəs/', 'C1', 'gitu điềm gở; báo hiệu điều chẳng lành; đe dọa', 'adj.', 'ominously (adv.), omen (n.)', 'Đồng nghĩa: foreboding, threatening · Trái nghĩa: promising', 'Nhấn mạnh việc dự báo điều tồi tệ sắp xảy ra, chứ không phải sự việc đó đã xảy ra rồi.', 'Ominous clouds gathered as we hurried back home.', NULL, 'Những đám mây đen vần vũ đầy đe dọa khi chúng tôi vội vã chạy về nhà.', '{"wordId":"ominous","ukIpa":"/ˈɒmɪnəs/","usIpa":"/ˈɑːmɪnəs/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"suggesting that something bad or unpleasant may happen","vi":"gitu điềm gở; báo hiệu điều chẳng lành; đe dọa"}],"examples":[{"en":"Ominous clouds gathered as we hurried back home.","vi":"Những đám mây đen vần vũ đầy đe dọa khi chúng tôi vội vã chạy về nhà.","audioKind":"ex"},{"en":"The rapid decline in insect populations is an ominous sign for ecosystems that depend on pollination.","vi":"Sự sụt giảm nhanh chóng về số lượng côn trùng là một dấu hiệu báo trước điềm gở cho các hệ sinh thái phụ thuộc vào việc thụ phấn.","audioKind":"ex2"}],"collocations":[{"en":"an ominous sign","vi":"một điềm báo chẳng lành"},{"en":"ominous clouds","vi":"những đám mây đen báo hiệu bão"},{"en":"an ominous silence","vi":"sự im lặng đáng sợ"}],"wordFamily":["ominously (adv.)","omen (n.)"],"synonyms":["foreboding","threatening"],"antonyms":["promising"],"tipVi":"Nhấn mạnh việc dự báo điều tồi tệ sắp xảy ra, chứ không phải sự việc đó đã xảy ra rồi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yearn', 'en-c1-33', 'yearn', '/jɝːn/', 'C1', 'khao khát; mong mỏi; nhớ thương', 'v.', 'yearning (n.)', 'Đồng nghĩa: long, crave', 'Dùng "yearn for sth" hoặc "yearn to do" để diễn tả mong ước mãnh liệt.', 'After months abroad, she yearned for her mother''s cooking.', NULL, 'Sau nhiều tháng ở nước ngoài, cô ấy rất thèm món ăn do mẹ nấu.', '{"wordId":"yearn","ukIpa":"/jɜːn/","usIpa":"/jɝːn/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To want something deeply, especially something difficult to obtain","vi":"khao khát; mong mỏi; nhớ thương"}],"examples":[{"en":"After months abroad, she yearned for her mother''s cooking.","vi":"Sau nhiều tháng ở nước ngoài, cô ấy rất thèm món ăn do mẹ nấu.","audioKind":"ex"},{"en":"Many urban residents yearn for quieter surroundings, which may explain the growing appeal of rural tourism.","vi":"Nhiều cư dân thành thị khao khát một không gian sống yên tĩnh hơn, điều này có thể lý giải sức hút ngày càng tăng của du lịch nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"yearn for freedom","vi":"khao khát tự do"},{"en":"yearn to return","vi":"khát khao trở về"},{"en":"yearn for home","vi":"nhớ nhà"}],"wordFamily":["yearning (n.)"],"synonyms":["long","crave"],"antonyms":[],"tipVi":"Dùng \"yearn for sth\" hoặc \"yearn to do\" để diễn tả mong ước mãnh liệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resentful', 'en-c1-33', 'resentful', '/rɪˈzentfəl/', 'C1', 'căm phẫn, bất bình do cho rằng mình bị đối xử bất công', 'adj.', 'resent (v.), resentment (n.), resentfully (adv.)', 'Đồng nghĩa: bitter, aggrieved', 'Nhấn mạnh cảm giác bất mãn vì tự thấy bị đối xử không công bằng, không đơn thuần là tức giận.', 'He felt resentful when his brother took all the credit.', NULL, 'Cậu ấy cảm thấy ấm ức khi anh trai ôm trọn mọi công trạng.', '{"wordId":"resentful","ukIpa":"/rɪˈzentfəl/","usIpa":"/rɪˈzentfəl/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"angry because you believe you have been treated unfairly","vi":"căm phẫn, bất bình do cho rằng mình bị đối xử bất công"}],"examples":[{"en":"He felt resentful when his brother took all the credit.","vi":"Cậu ấy cảm thấy ấm ức khi anh trai ôm trọn mọi công trạng.","audioKind":"ex"},{"en":"Employees may become resentful if promotion decisions appear to favour personal connections rather than professional ability.","vi":"Nhân viên có thể tỏ ra bất mãn nếu các quyết định thăng tiến có vẻ thiên vị quan hệ cá nhân hơn là năng lực chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"feel resentful","vi":"cảm thấy bất bình"},{"en":"resentful of someone","vi":"om sòm oán giận ai đó"},{"en":"resentful towards someone","vi":"bất mãn với ai đó"}],"wordFamily":["resent (v.)","resentment (n.)","resentfully (adv.)"],"synonyms":["bitter","aggrieved"],"antonyms":[],"tipVi":"Nhấn mạnh cảm giác bất mãn vì tự thấy bị đối xử không công bằng, không đơn thuần là tức giận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_awkwardness', 'en-c1-33', 'awkwardness', '/ˈɔːkwərdnəs/', 'C1', 'sự vụng về; sự lóng ngóng; sự ngượng ngùng; sự bẽn lẽn', 'n.', 'awkward (adj.), awkwardly (adv.)', 'Đồng nghĩa: clumsiness, unease · Trái nghĩa: grace, ease', 'Thường là danh từ không đếm được; có thể dùng để chỉ sự vụng về trong vận động hoặc sự ngượng ngùng trong giao tiếp xã hội.', 'His awkwardness on skates made every turn a challenge.', NULL, 'Sự vụng về của anh ấy trên giày trượt patin khiến mỗi lần đổi hướng đều trở thành một thử thách.', '{"wordId":"awkwardness","ukIpa":"/ˈɔːkwədnəs/","usIpa":"/ˈɔːkwərdnəs/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"A lack of ease or control in physical movement.","vi":"sự vụng về; sự lóng ngóng"},{"pos":"n.","en":"Discomfort or embarrassment in a social situation.","vi":"sự ngượng ngùng; sự bẽn lẽn"}],"examples":[{"en":"His awkwardness on skates made every turn a challenge.","vi":"Sự vụng về của anh ấy trên giày trượt patin khiến mỗi lần đổi hướng đều trở thành một thử thách.","audioKind":"ex"},{"en":"Group activities can reduce the initial awkwardness students experience when interacting with classmates from different cultural backgrounds.","vi":"Các hoạt động nhóm có thể làm giảm bớt cảm giác ngượng ngùng ban đầu khi học sinh giao tiếp với các bạn học đến từ những nền văn hóa khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"physical awkwardness","vi":"sự vụng về thể chất"},{"en":"social awkwardness","vi":"sự ngượng ngùng trong giao tiếp"},{"en":"initial awkwardness","vi":"sự lúng túng ban đầu"},{"en":"a sense of awkwardness","vi":"cảm giác ngượng ngùng"}],"wordFamily":["awkward (adj.)","awkwardly (adv.)"],"synonyms":["clumsiness","unease"],"antonyms":["grace","ease"],"tipVi":"Thường là danh từ không đếm được; có thể dùng để chỉ sự vụng về trong vận động hoặc sự ngượng ngùng trong giao tiếp xã hội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fervent', 'en-c1-33', 'fervent', '/ˈfɝːvənt/', 'C1', 'nhiệt thành; tha thiết; cuồng nhiệt', 'adj.', 'fervently (adv.), fervour (n.)', 'Đồng nghĩa: passionate, ardent · Trái nghĩa: apathetic', 'Từ này có sắc thái trang trọng, thường dùng để bổ nghĩa cho supporter, belief hoặc hope.', 'She is a fervent supporter of our local football team.', NULL, 'Cô ấy là một người ủng hộ nhiệt thành của đội bóng đá địa phương chúng tôi.', '{"wordId":"fervent","ukIpa":"/ˈfɜːvənt/","usIpa":"/ˈfɝːvənt/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"showing very strong and sincere feelings or beliefs","vi":"nhiệt thành; tha thiết; cuồng nhiệt"}],"examples":[{"en":"She is a fervent supporter of our local football team.","vi":"Cô ấy là một người ủng hộ nhiệt thành của đội bóng đá địa phương chúng tôi.","audioKind":"ex"},{"en":"Fervent supporters of wildlife conservation argue that protecting natural habitats should take priority over commercial development.","vi":"Những người ủng hộ nhiệt thành của phong trào bảo tồn động vật hoang dã lập luận rằng việc bảo vệ các sinh cảnh tự nhiên nên được ưu tiên hơn so với phát triển thương mại.","audioKind":"ex2"}],"collocations":[{"en":"a fervent supporter","vi":"người ủng hộ nhiệt thành"},{"en":"a fervent believer","vi":"tín đồ kiên định"},{"en":"a fervent hope","vi":"hy vọng tha thiết"}],"wordFamily":["fervently (adv.)","fervour (n.)"],"synonyms":["passionate","ardent"],"antonyms":["apathetic"],"tipVi":"Từ này có sắc thái trang trọng, thường dùng để bổ nghĩa cho supporter, belief hoặc hope.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reluctance', 'en-c1-33', 'reluctance', '/rɪˈlʌktəns/', 'C1', 'sự không ⿓i lòng; sự miễn cưỡng', 'n.', 'reluctant (adj.), reluctantly (adv.)', 'Đồng nghĩa: unwillingness, hesitation · Trái nghĩa: willingness, eagerness', 'Thường là danh từ không đếm được, hay đi với giới từ to do để chỉ sự không muốn làm việc gì.', 'With obvious reluctance, Leo handed his favourite toy back.', NULL, 'Với vẻ miễn cưỡng thấy rõ, Leo trả lại món đồ chơi yêu thích của mình.', '{"wordId":"reluctance","ukIpa":"/rɪˈlʌktəns/","usIpa":"/rɪˈlʌktəns/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"Unwillingness or hesitation to do something.","vi":"sự không ⿓i lòng; sự miễn cưỡng"}],"examples":[{"en":"With obvious reluctance, Leo handed his favourite toy back.","vi":"Với vẻ miễn cưỡng thấy rõ, Leo trả lại món đồ chơi yêu thích của mình.","audioKind":"ex"},{"en":"Some commuters show reluctance to use public transport because services are infrequent and unreliable.","vi":"Một số người đi làm tỏ ra miễn cưỡng sử dụng phương tiện giao thông công cộng vì dịch vụ thưa thớt và kém tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"reluctance to change","vi":"sự không muốn thay đổi"},{"en":"with reluctance","vi":"một cách miễn cưỡng"},{"en":"overcome one''s reluctance","vi":"vượt qua sự ngần ngại"}],"wordFamily":["reluctant (adj.)","reluctantly (adv.)"],"synonyms":["unwillingness","hesitation"],"antonyms":["willingness","eagerness"],"tipVi":"Thường là danh từ không đếm được, hay đi với giới từ to do để chỉ sự không muốn làm việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_33_1', 'en-c1-33', 'Cách dùng “awkwardness” (n.) — sự vụng về; sự lóng ngóng', 'physical awkwardness  ·  social awkwardness  ·  initial awkwardness', 'Thường là danh từ không đếm được; có thể dùng để chỉ sự vụng về trong vận động hoặc sự ngượng ngùng trong giao tiếp xã hội.', 'Họ từ (Word Family): awkward (adj.), awkwardly (adv.) | Đồng nghĩa: clumsiness, unease · Trái nghĩa: grace, ease', '[{"hanzi":"His awkwardness on skates made every turn a challenge.","pinyin":"","meaning":"Sự vụng về của anh ấy trên giày trượt patin khiến mỗi lần đổi hướng đều trở thành một thử thách."},{"hanzi":"Group activities can reduce the initial awkwardness students experience when interacting with classmates from different cultural backgrounds.","pinyin":"","meaning":"Các hoạt động nhóm có thể làm giảm bớt cảm giác ngượng ngùng ban đầu khi học sinh giao tiếp với các bạn học đến từ những nền văn hóa khác nhau."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_33_2', 'en-c1-33', 'Cách dùng “heighten” (v.) — làm tăng thêm; làm mạnh lên; gia tăng', 'heighten awareness  ·  heighten tension  ·  heighten concern', 'Thường dùng cho cảm xúc, nhận thức hoặc hiệu ứng được gia tăng, không dùng cho việc tăng chiều cao cơ thể.', 'Họ từ (Word Family): height (n.), high (adj.), heightened (adj.) | Đồng nghĩa: intensify, increase · Trái nghĩa: reduce, lessen', '[{"hanzi":"The sudden silence only heightened my curiosity about the surprise.","pinyin":"","meaning":"Sự im lặng bất chợt càng làm cho sự tò mò của tôi về điều bất ngờ trở nên mạnh mẽ hơn."},{"hanzi":"Repeated droughts may heighten public concern about water shortages and encourage governments to invest in conservation.","pinyin":"","meaning":"Các đợt hạn hán lặp đi lặp lại có thể làm gia tăng mối lo ngại của công chúng về tình trạng thiếu nước và khuyến khích các chính phủ đầu tư vào công tác bảo tồn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_33_3', 'en-c1-33', 'Cách dùng “agitation” (n.) — sự bồn chồn; sự lo âu; sự kích động', 'in a state of agitation  ·  political agitation  ·  gentle agitation', 'Thường là danh từ không đếm được; có thể dùng để chỉ trạng thái cảm xúc bất an hoặc hành động khuấy lắc.', 'Họ từ (Word Family): agitate (v.), agitated (adj.), agitator (n.)', '[{"hanzi":"Her agitation grew as she searched for her missing keys.","pinyin":"","meaning":"Cô ấy ngày càng trở nên bồn chồn khi tìm kiếm chìa khóa bị thất lạc của mình."},{"hanzi":"Prolonged exposure to traffic noise may increase agitation and reduce residents'' ability to concentrate at home.","pinyin":"","meaning":"Việc tiếp xúc lâu dài với tiếng ồn giao thông có thể làm gia tăng sự bồn chồn và làm giảm khả năng tập trung ở nhà của cư dân."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_33_4', 'en-c1-33', 'Cách dùng “everlasting” (adj.) — vĩnh cửu; đời đời; kéo dài mãi mãi', 'everlasting love  ·  everlasting friendship  ·  everlasting life', 'Sắc thái mạnh hơn long-lasting, thường dùng cho các khái niệm trừu tượng như tình yêu hay tình bạn.', 'Họ từ (Word Family): everlastingly (adv.) | Đồng nghĩa: eternal, endless · Trái nghĩa: temporary, fleeting', '[{"hanzi":"They promised each other everlasting friendship beneath the old tree.","pinyin":"","meaning":"Họ hứa hẹn với nhau về một tình bạn vĩnh cửu dưới tán cây cổ thụ."},{"hanzi":"Although digital storage appears to offer everlasting access, files can become unreadable as technology changes.","pinyin":"","meaning":"Mặc dù kho lưu trữ kỹ thuật số có vẻ mang lại khả năng truy cập vĩnh viễn, nhưng các tệp tin vẫn có thể trở nên không đọc được khi công nghệ thay đổi."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_33_1', 'en-c1-33', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_1_1', 'ten_c1_33_1', 'boldness', 'Her boldness impressed everyone when she volunteered to lead.', 'Her boldness impressed everyone when she volunteered to lead.', '/ˈboʊldnəs/', 'Sự dũng cảm của cô ấy đã gây ấn tượng với mọi người khi cô tình nguyện làm người dẫn dắt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_1_2', 'ten_c1_33_1', 'apologetic', 'She gave an apologetic smile after spilling my tea.', 'She gave an apologetic smile after spilling my tea.', '/əˌpɑːləˈdʒetɪk/', 'Cô ấy nở một nụ cười hối lỗi sau khi làm đổ ly trà của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
