INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_1_4', 'ten_c1_33_1', 'humiliate', 'Please don''t humiliate me in front of my friends.', 'Please don''t humiliate me in front of my friends.', '/hjuːˈmɪlieɪt/', 'Làm ơn đừng làm tôi bẽ mặt trước mặt bạn bè của tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_1_5', 'ten_c1_33_1', 'sorrowful', 'She gave a sorrowful smile as the train departed.', 'She gave a sorrowful smile as the train departed.', '/ˈsɑːroʊfəl/', 'Cô ấy nở một nụ cười đượm buồn khi chuyến tàu lăn bánh rời đi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_1_6', 'ten_c1_33_1', 'agonize', 'I agonized over which course to choose all weekend.', 'I agonized over which course to choose all weekend.', '/ˈæɡənaɪz/', 'Cả cuối tuần, tôi cứ trăn trở mãi không biết nên chọn môn học nào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_1_7', 'ten_c1_33_1', 'resolutely', 'Despite the rain, she walked resolutely towards the shelter.', 'Despite the rain, she walked resolutely towards the shelter.', '/ˈrezəluːtli/', 'Bất chấp trời mưa, cô ấy vẫn kiên quyết bước về phía mái hiên.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_1_8', 'ten_c1_33_1', 'haunt', 'That embarrassing mistake still haunts me before every presentation.', 'That embarrassing mistake still haunts me before every presentation.', '/hɔːnt/', 'Sai lầm đáng xấu hổ đó vẫn cứ ám ảnh tôi trước mỗi buổi thuyết trình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_33_1_1', 'en-c1-33', 'ten_c1_33_1', 'listening', 'listening', 'Her boldness impressed everyone when she volunteered to lead.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cậu ấy cảm thấy ấm ức khi anh trai ôm trọn mọi công trạng.","Cô ấy nở một nụ cười hối lỗi sau khi làm đổ ly trà của tôi.","Sau chuyến đi bộ dài, tôi rất thèm một bữa ăn nóng hổi.","Sự dũng cảm của cô ấy đã gây ấn tượng với mọi người khi cô tình nguyện làm người dẫn dắt."]'::jsonb, 3, 'Her boldness impressed everyone when she volunteered to lead. → Sự dũng cảm của cô ấy đã gây ấn tượng với mọi người khi cô tình nguyện làm người dẫn dắt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_33_1_2', 'en-c1-33', 'ten_c1_33_1', 'listening', 'listening', 'She gave an apologetic smile after spilling my tea.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy nở một nụ cười hối lỗi sau khi làm đổ ly trà của tôi.","Cô ấy là một người ủng hộ nhiệt thành của đội bóng đá địa phương chúng tôi.","Làm ơn đừng làm tôi bẽ mặt trước mặt bạn bè của tôi.","Lũ trẻ hét lên vui sướng khi hệ thống phun nước khởi động."]'::jsonb, 0, 'She gave an apologetic smile after spilling my tea. → Cô ấy nở một nụ cười hối lỗi sau khi làm đổ ly trà của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_33_1_3', 'en-c1-33', 'ten_c1_33_1', 'listening', 'listening', 'The sudden silence only heightened my curiosity about the surprise.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sự im lặng bất chợt càng làm cho sự tò mò của tôi về điều bất ngờ trở nên mạnh mẽ hơn.","Sai lầm đáng xấu hổ đó vẫn cứ ám ảnh tôi trước mỗi buổi thuyết trình.","Sau chuyến đi bộ dài, tôi rất thèm một bữa ăn nóng hổi.","Sự dũng cảm của cô ấy đã gây ấn tượng với mọi người khi cô tình nguyện làm người dẫn dắt."]'::jsonb, 0, 'The sudden silence only heightened my curiosity about the surprise. → Sự im lặng bất chợt càng làm cho sự tò mò của tôi về điều bất ngờ trở nên mạnh mẽ hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_33_2', 'en-c1-33', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_2_1', 'ten_c1_33_2', 'boldness', 'Addressing climate change requires political boldness, particularly when necessary reforms may initially attract limited public support.', 'Addressing climate change requires political boldness, particularly when necessary reforms may initially attract limited public support.', '/ˈboʊldnəs/', 'Việc giải quyết biến đổi khí hậu đòi hỏi sự can đảm chính trị, đặc biệt là khi các cải cách cần thiết ban đầu có thể nhận được ít sự ủng hộ từ công chúng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_2_2', 'ten_c1_33_2', 'apologetic', 'An apologetic response to customer complaints is helpful, but companies must also address the underlying problems.', 'An apologetic response to customer complaints is helpful, but companies must also address the underlying problems.', '/əˌpɑːləˈdʒetɪk/', 'Phản hồi mang tính xin lỗi đối với các phàn nàn của khách hàng rất hữu ích, nhưng các công ty cũng phải giải quyết các vấn đề cốt lõi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_2_3', 'ten_c1_33_2', 'heighten', 'Repeated droughts may heighten public concern about water shortages and encourage governments to invest in conservation.', 'Repeated droughts may heighten public concern about water shortages and encourage governments to invest in conservation.', '/ˈhaɪtən/', 'Các đợt hạn hán lặp đi lặp lại có thể làm gia tăng mối lo ngại của công chúng về tình trạng thiếu nước và khuyến khích các chính phủ đầu tư vào công tác bảo tồn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_2_4', 'ten_c1_33_2', 'humiliate', 'Teachers should correct mistakes constructively rather than humiliate students who struggle with difficult tasks.', 'Teachers should correct mistakes constructively rather than humiliate students who struggle with difficult tasks.', '/hjuːˈmɪlieɪt/', 'Giáo viên nên sửa lỗi mang tính xây dựng thay vì làm nhục những học sinh gặp khó khăn với các bài tập phức tạp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_2_5', 'ten_c1_33_2', 'sorrowful', 'The film presents a sorrowful portrait of families separated by migration and economic hardship.', 'The film presents a sorrowful portrait of families separated by migration and economic hardship.', '/ˈsɑːroʊfəl/', 'Bộ phim khắc họa một bức tranh đượm buồn về những gia đình phải chia lìa vì di cư và khó khăn kinh tế.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_33_2_6', 'ten_c1_33_2', 'agonize', 'Many graduates agonize over whether to pursue further education or enter an increasingly competitive job market.', 'Many graduates agonize over whether to pursue further education or enter an increasingly competitive job market.', '/ˈæɡənaɪz/', 'Nhiều sinh viên tốt nghiệp phải trăn trở rất nhiều về việc nên tiếp tục học lên cao hay bước vào thị trường lao động đang cạnh tranh ngày càng khốc liệt.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_33_2_1', 'en-c1-33', 'ten_c1_33_2', 'listening', 'listening', 'Addressing climate change requires political boldness, particularly when necessary reforms may initially attract limited public support.', NULL, 'Trong câu vừa nghe, từ “boldness” mang nghĩa nào sau đây?', '["thù lao; tiền công; chế độ đãi ngộ","mưu kế; thủ đoạn; chiêu trò (nhằm đạt lợi thế)","sự dũng cảm; sự táo bạo; sự gan dạ","hóm hỉnh; sắc sảo"]'::jsonb, 2, '“boldness” (/ˈboʊldnəs/): sự dũng cảm; sự táo bạo; sự gan dạ. Câu đầy đủ: Addressing climate change requires political boldness, particularly when necessary reforms may initially attract limited public support.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_33_2_2', 'en-c1-33', 'ten_c1_33_2', 'listening', 'listening', 'An apologetic response to customer complaints is helpful, but companies must also address the underlying problems.', NULL, 'Trong câu vừa nghe, từ “apologetic” mang nghĩa nào sau đây?', '["có ý hối lỗi; tỏm vẻ xin lỗi; ân hận","bóp méo; xuyên tạc; mô tả sai lệch","gửi đi; phái đi","người đại diện; người ủy quyền"]'::jsonb, 0, '“apologetic” (/əˌpɑːləˈdʒetɪk/): có ý hối lỗi; tỏm vẻ xin lỗi; ân hận. Câu đầy đủ: An apologetic response to customer complaints is helpful, but companies must also address the underlying problems.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_33_1', 'en-c1-33', 'Her boldness impressed everyone when she volunteered to lead', 'Sự dũng cảm của cô ấy đã gây ấn tượng với mọi người khi cô tình nguyện làm người dẫn dắt.', 'boldness /ˈboʊldnəs/', '["she","boldness","Her","lead","volunteered","when","everyone","impressed","to"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
