INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_1', 'en-c1-33', NULL, 'comprehensive_test', 'listening', 'boldness', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự dũng cảm; sự táo bạo; sự gan dạ","chó săn","gây gánh nặng; phiền hà; nặng nề","bằng kim loại; chứa kim loại"]'::jsonb, 0, 'boldness (/ˈboʊldnəs/) → sự dũng cảm; sự táo bạo; sự gan dạ; tính chất nổi bật; sự rực rỡ (về thị giác)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_2', 'en-c1-33', NULL, 'comprehensive_test', 'listening', 'She gave an apologetic smile after spilling my tea.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Họ hứa hẹn với nhau về một tình bạn vĩnh cửu dưới tán cây cổ thụ.","Chú chó con tràn đầy năng lượng cứ nhảy quanh khu vườn suốt cả buổi sáng.","Cô ấy nở một nụ cười hối lỗi sau khi làm đổ ly trà của tôi.","Anh ấy nhìn cái diều tôi tự làm với ánh mắt khinh miệt."]'::jsonb, 2, 'She gave an apologetic smile after spilling my tea. → Cô ấy nở một nụ cười hối lỗi sau khi làm đổ ly trà của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_3', 'en-c1-33', NULL, 'comprehensive_test', 'listening', 'heighten', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chú ý; lắng nghe và làm theo","tuabin; máy phát điện chạy bằng sức gió/nước/hơi nước","rách rưới, tả tơi; mặc quần áo rách rưới","làm tăng thêm; làm mạnh lên; gia tăng"]'::jsonb, 3, 'heighten (/ˈhaɪtən/) → làm tăng thêm; làm mạnh lên; gia tăng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_4', 'en-c1-33', NULL, 'comprehensive_test', 'listening', 'Please don''t humiliate me in front of my friends.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm ơn đừng làm tôi bẽ mặt trước mặt bạn bè của tôi.","Lũ trẻ hét lên vui sướng khi hệ thống phun nước khởi động.","Cô ấy nở một nụ cười đượm buồn khi chuyến tàu lăn bánh rời đi.","Sai lầm đáng xấu hổ đó vẫn cứ ám ảnh tôi trước mỗi buổi thuyết trình."]'::jsonb, 0, 'Please don''t humiliate me in front of my friends. → Làm ơn đừng làm tôi bẽ mặt trước mặt bạn bè của tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_5', 'en-c1-33', NULL, 'comprehensive_test', 'listening', 'sorrowful', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xâm lấn dần; xâm phạm","cởi mở; khoáng đạt; tôn trọng sự khác biệt","buồn bã; đau buồn; đầy vẻ đau thương","không thể tưởng tượng nổi; không thể chấp nhận được"]'::jsonb, 2, 'sorrowful (/ˈsɑːroʊfəl/) → buồn bã; đau buồn; đầy vẻ đau thương', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_6', 'en-c1-33', NULL, 'comprehensive_test', 'listening', 'I agonized over which course to choose all weekend.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cả cuối tuần, tôi cứ trăn trở mãi không biết nên chọn môn học nào.","Sai lầm đáng xấu hổ đó vẫn cứ ám ảnh tôi trước mỗi buổi thuyết trình.","Lũ trẻ hét lên vui sướng khi hệ thống phun nước khởi động.","Làm ơn đừng làm tôi bẽ mặt trước mặt bạn bè của tôi."]'::jsonb, 0, 'I agonized over which course to choose all weekend. → Cả cuối tuần, tôi cứ trăn trở mãi không biết nên chọn môn học nào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_7', 'en-c1-33', NULL, 'comprehensive_test', 'listening', 'resolutely', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tấm ván dày","một cách kiên quyết; kiên định","tùy tiện; ngẫu nhiên (không dựa trên lý do hay cơ sở rõ ràng)","sự không hài lòng; sự bất bình"]'::jsonb, 1, 'resolutely (/ˈrezəluːtli/) → một cách kiên quyết; kiên định', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_8', 'en-c1-33', NULL, 'comprehensive_test', 'listening', 'That embarrassing mistake still haunts me before every presentation.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những người đi bộ đường dài mệt mỏi đã nghỉ ngơi bên dòng suối trước khi hoàng hôn buông xuống.","Sự dũng cảm của cô ấy đã gây ấn tượng với mọi người khi cô tình nguyện làm người dẫn dắt.","Sai lầm đáng xấu hổ đó vẫn cứ ám ảnh tôi trước mỗi buổi thuyết trình.","Cô ấy ngày càng trở nên bồn chồn khi tìm kiếm chìa khóa bị thất lạc của mình."]'::jsonb, 2, 'That embarrassing mistake still haunts me before every presentation. → Sai lầm đáng xấu hổ đó vẫn cứ ám ảnh tôi trước mỗi buổi thuyết trình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_9', 'en-c1-33', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Feeling, showing, or causing deep sadness.”?', '["weary","sorrowful","awkwardness","agitation"]'::jsonb, 1, 'sorrowful (/ˈsɑːroʊfəl/) → buồn bã; đau buồn; đầy vẻ đau thương', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_10', 'en-c1-33', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Worry intensely while trying to make a difficult decision”?', '["touchy","fervent","agonize","scornful"]'::jsonb, 2, 'agonize (/ˈæɡənaɪz/) → vò đầu bứt tai; băn khoăn lo lắng; trăn trở khổ sở', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_11', 'en-c1-33', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “In a determined way, without giving up or changing course”?', '["boldness","resolutely","agonize","bleak"]'::jsonb, 1, 'resolutely (/ˈrezəluːtli/) → một cách kiên quyết; kiên định', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_12', 'en-c1-33', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to keep returning to someone''s mind and causing distress”?', '["humiliate","bleak","haunt","agonize"]'::jsonb, 2, 'haunt (/hɔːnt/) → ám ảnh; làm vương vất trong tâm trí', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_13', 'en-c1-33', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Easily upset or offended, especially by criticism.”?', '["touchy","exuberant","bleak","haunt"]'::jsonb, 0, 'touchy (/ˈtʌtʃi/) → dễ tự ái; nhạy cảm', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
