INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_18', 'en-c1-33', NULL, 'comprehensive_test', 'reading', NULL, 'Addressing climate change requires political boldness, particularly when necessary reforms may initially attract limited public support.', 'Dựa vào câu trên, từ “boldness” có nghĩa phù hợp nhất là gì?', '["đầu tiên; chuyến xuất phát đầu tiên","gác lại; tạm hoãn","sự cân nhắc kỹ lưỡng; sự thảo luận","sự dũng cảm; sự táo bạo; sự gan dạ"]'::jsonb, 3, 'boldness: sự dũng cảm; sự táo bạo; sự gan dạ; tính chất nổi bật; sự rực rỡ (về thị giác). Dịch cả câu: Việc giải quyết biến đổi khí hậu đòi hỏi sự can đảm chính trị, đặc biệt là khi các cải cách cần thiết ban đầu có thể nhận được ít sự ủng hộ từ công chúng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_19', 'en-c1-33', NULL, 'comprehensive_test', 'reading', NULL, 'An apologetic response to customer complaints is helpful, but companies must also address the underlying problems.', 'Dựa vào câu trên, từ “apologetic” có nghĩa phù hợp nhất là gì?', '["lịch sự; nhã nhặn; có phép tắc","bác sĩ; bác sĩ nội khoa","hung dữ; dữ tợn","có ý hối lỗi; tỏm vẻ xin lỗi; ân hận"]'::jsonb, 3, 'apologetic: có ý hối lỗi; tỏm vẻ xin lỗi; ân hận. Dịch cả câu: Phản hồi mang tính xin lỗi đối với các phàn nàn của khách hàng rất hữu ích, nhưng các công ty cũng phải giải quyết các vấn đề cốt lõi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_20', 'en-c1-33', NULL, 'comprehensive_test', 'reading', NULL, 'Repeated droughts may heighten public concern about water shortages and encourage governments to invest in conservation.', 'Dựa vào câu trên, từ “heighten” có nghĩa phù hợp nhất là gì?', '["làm cho có văn hóa; khai hóa; làm cho có giáo dưỡng","sa mạc hóa; hoang mạc hóa","làm tăng thêm; làm mạnh lên; gia tăng","cài đặt sẵn; thiết lập trước"]'::jsonb, 2, 'heighten: làm tăng thêm; làm mạnh lên; gia tăng. Dịch cả câu: Các đợt hạn hán lặp đi lặp lại có thể làm gia tăng mối lo ngại của công chúng về tình trạng thiếu nước và khuyến khích các chính phủ đầu tư vào công tác bảo tồn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_21', 'en-c1-33', NULL, 'comprehensive_test', 'reading', NULL, 'Teachers should correct mistakes constructively rather than humiliate students who struggle with difficult tasks.', 'Dựa vào câu trên, từ “humiliate” có nghĩa phù hợp nhất là gì?', '["thành hiện thực; xảy ra; thành công","làm nhục; làm bẽ mặt; sỉ nhục","sự sai lệch; sự không nhất quán; sự khác biệt","thuộc về pháp y; thuộc về giám định tư pháp"]'::jsonb, 1, 'humiliate: làm nhục; làm bẽ mặt; sỉ nhục. Dịch cả câu: Giáo viên nên sửa lỗi mang tính xây dựng thay vì làm nhục những học sinh gặp khó khăn với các bài tập phức tạp.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_22', 'en-c1-33', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự vụng về; sự lóng ngóng”', '["grove","awkwardness","nameless","gramophone"]'::jsonb, 1, 'sự vụng về; sự lóng ngóng → awkwardness (/ˈɔːkwərdnəs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_23', 'en-c1-33', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhiệt thành; tha thiết; cuồng nhiệt”', '["uprising","wither","fervent","attentive"]'::jsonb, 2, 'nhiệt thành; tha thiết; cuồng nhiệt → fervent (/ˈfɝːvənt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_33_24', 'en-c1-33', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự không ⿓i lòng; sự miễn cưỡng”', '["reluctance","eclipse","idleness","tactful"]'::jsonb, 0, 'sự không ⿓i lòng; sự miễn cưỡng → reluctance (/rɪˈlʌktəns/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-34', 'en', 'Bài 34: Cảm xúc & Tính cách (3) - CEFR C1', 'CEFR C1', 'C1 · Cảm xúc', '22 từ vựng Tiếng Anh CEFR C1 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5034, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grudge', 'en-c1-34', 'grudge', '/ɡrʌdʒ/', 'C1', 'mối hận thù; sự oán giận; miễn cưỡng cho; tiếc rẻ', 'n.', 'grudging (adj.), grudgingly (adv.)', 'Đồng nghĩa: resentment', 'Cụm hold a grudge against sb có nghĩa là nuôi lòng oán hận đối với ai đó.', 'She still holds a grudge over the broken vase.', NULL, 'Cô ấy vẫn ôm hận chuyện cái bình hoa bị vỡ.', '{"wordId":"grudge","ukIpa":"/ɡrʌdʒ/","usIpa":"/ɡrʌdʒ/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"Lasting anger towards someone because of an earlier wrong","vi":"mối hận thù; sự oán giận"},{"pos":"v.","en":"To feel unwilling to give or allow something","vi":"miễn cưỡng cho; tiếc rẻ"}],"examples":[{"en":"She still holds a grudge over the broken vase.","vi":"Cô ấy vẫn ôm hận chuyện cái bình hoa bị vỡ.","audioKind":"ex"},{"en":"Unresolved workplace conflicts can lead employees to hold grudges, reducing cooperation and damaging team morale.","vi":"Những mâu thuẫn chốn công sở chưa được giải quyết có thể khiến nhân viên nuôi lòng oán giận, làm giảm sự hợp tác và tổn hại tinh thần đồng đội.","audioKind":"ex2"}],"collocations":[{"en":"hold a grudge","vi":"ôm hận trong lòng"},{"en":"bear a grudge against someone","vi":"mang lòng oán giận ai đó"},{"en":"a long-standing grudge","vi":"mối thù lâu năm"}],"wordFamily":["grudging (adj.)","grudgingly (adv.)"],"synonyms":["resentment"],"antonyms":[],"tipVi":"Cụm hold a grudge against sb có nghĩa là nuôi lòng oán hận đối với ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clench', 'en-c1-34', 'clench', '/klentʃ/', 'C1', 'siết chặt; mím chặt', 'v.', NULL, 'Trái nghĩa: unclench', 'clench dùng cho hành động siết chặt tay hoặc hàm; trong khi clinch mới dùng cho việc giành chiến thắng hoặc chốt hạ thỏa thuận.', 'Arun clenched his fists as the cold wind blew.', NULL, 'Arun siết chặt hai tay lại khi cơn gió lạnh thổi qua.', '{"wordId":"clench","ukIpa":"/klentʃ/","usIpa":"/klentʃ/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To close your hands or press your teeth together tightly.","vi":"siết chặt; mím chặt"}],"examples":[{"en":"Arun clenched his fists as the cold wind blew.","vi":"Arun siết chặt hai tay lại khi cơn gió lạnh thổi qua.","audioKind":"ex"},{"en":"People under prolonged stress may clench their teeth during sleep, potentially causing pain in the jaw.","vi":"Những người chịu áp lực kéo dài có thể nghiến chặt răng khi ngủ, có thể gây ra đau ở phần hàm.","audioKind":"ex2"}],"collocations":[{"en":"clench your fists","vi":"nắm chặt tay"},{"en":"clench your teeth","vi":"nghiến chặt răng"},{"en":"clench your jaw","vi":"bặm chặt hàm"}],"wordFamily":[],"synonyms":[],"antonyms":["unclench"],"tipVi":"clench dùng cho hành động siết chặt tay hoặc hàm; trong khi clinch mới dùng cho việc giành chiến thắng hoặc chốt hạ thỏa thuận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_serenity', 'en-c1-34', 'serenity', '/səˈrenəti/', 'C1', 'sự thanh tịnh; sự bình yên; sự thanh thản', 'n.', 'serene (adj.), serenely (adv.)', 'Đồng nghĩa: calmness, tranquillity, peacefulness · Trái nghĩa: agitation', 'Thường là danh từ không đếm được, dùng để chỉ cả cảnh quan yên bình lẫn tâm trạng thanh thản.', 'I love the serenity of the garden at dawn.', NULL, 'Tôi rất thích sự thanh bình của khu vườn vào lúc bình minh.', '{"wordId":"serenity","ukIpa":"/səˈrenəti/","usIpa":"/səˈrenəti/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"a state of being calm, peaceful, and untroubled","vi":"sự thanh tịnh; sự bình yên; sự thanh thản"}],"examples":[{"en":"I love the serenity of the garden at dawn.","vi":"Tôi rất thích sự thanh bình của khu vườn vào lúc bình minh.","audioKind":"ex"},{"en":"Access to quiet green spaces can offer urban residents a sense of serenity amid daily pressures.","vi":"Việc tiếp cận các không gian xanh yên tĩnh có thể mang lại cho cư dân đô thị cảm giác thanh thản giữa những áp lực thường ngày.","audioKind":"ex2"}],"collocations":[{"en":"a sense of serenity","vi":"cảm giác bình yên"},{"en":"inner serenity","vi":"sự tĩnh lặng nội tâm"},{"en":"an atmosphere of serenity","vi":"không khí thanh tịnh"}],"wordFamily":["serene (adj.)","serenely (adv.)"],"synonyms":["calmness","tranquillity","peacefulness"],"antonyms":["agitation"],"tipVi":"Thường là danh từ không đếm được, dùng để chỉ cả cảnh quan yên bình lẫn tâm trạng thanh thản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hateful', 'en-c1-34', 'hateful', '/ˈheɪtfəl/', 'C1', 'đầy thù hận; ác ý; căm thù; đáng ghét; cực kỳ khó chịu', 'adj.', 'hate (v.), hatred (n.), hatefully (adv.)', 'Đồng nghĩa: malicious, odious · Trái nghĩa: loving', 'Có thể diễn tả lời nói hành động đầy căm hù, hoặc chỉ những sự vật sự việc cực kỳ đáng ghét.', 'His hateful remarks upset everyone sitting around the table.', NULL, 'Những lời cay nghiệt đầy ác ý của anh ấy làm phiền lòng tất cả mọi người ngồi quanh bàn.', '{"wordId":"hateful","ukIpa":"/ˈheɪtfəl/","usIpa":"/ˈheɪtfəl/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"expressing strong hatred or a wish to hurt others","vi":"đầy thù hận; ác ý"},{"pos":"adj.","en":"extremely unpleasant and deserving strong dislike","vi":"căm thù; đáng ghét; cực kỳ khó chịu"}],"examples":[{"en":"His hateful remarks upset everyone sitting around the table.","vi":"Những lời cay nghiệt đầy ác ý của anh ấy làm phiền lòng tất cả mọi người ngồi quanh bàn.","audioKind":"ex"},{"en":"Schools should address hateful behaviour early to ensure that all students feel safe and respected.","vi":"Nhà trường nên xử lý sớm các hành vi đầy thù hận để đảm bảo rằng tất cả học sinh đều cảm thấy an toàn và được tôn trọng.","audioKind":"ex2"}],"collocations":[{"en":"hateful remarks","vi":"lời lẽ cay nghiệt"},{"en":"hateful behaviour","vi":"hành vi thù hận"},{"en":"hateful speech","vi":"phát ngôn thù hận"}],"wordFamily":["hate (v.)","hatred (n.)","hatefully (adv.)"],"synonyms":["malicious","odious"],"antonyms":["loving"],"tipVi":"Có thể diễn tả lời nói hành động đầy căm hù, hoặc chỉ những sự vật sự việc cực kỳ đáng ghét.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frantic', 'en-c1-34', 'frantic', '/ˈfræntɪk/', 'C1', 'quá lo lắng; hoảng loạn; không thể giữ được bình tĩnh; được thực hiện rất nhanh với hoạt động cường độ cao, thường không kiểm soát', 'adj.', 'frantically (adv.)', 'Đồng nghĩa: panicked, frenzied · Trái nghĩa: calm', 'Nhấn mạnh sự lo lắng mất kiểm soát hoặc bấn loạn, không đồng nghĩa với việc mất trí.', 'I grew frantic when I couldn''t find my passport.', NULL, 'Tôi phát hoảng lên khi không tìm thấy hộ chiếu của mình.', '{"wordId":"frantic","ukIpa":"/ˈfræntɪk/","usIpa":"/ˈfræntɪk/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Extremely worried or frightened and unable to stay calm","vi":"quá lo lắng; hoảng loạn; không thể giữ được bình tĩnh"},{"pos":"adj.","en":"Done very quickly with intense, often uncontrolled activity","vi":"được thực hiện rất nhanh với hoạt động cường độ cao, thường không kiểm soát"}],"examples":[{"en":"I grew frantic when I couldn''t find my passport.","vi":"Tôi phát hoảng lên khi không tìm thấy hộ chiếu của mình.","audioKind":"ex"},{"en":"The frantic pace of urban life can increase stress and leave residents with little time for relaxation.","vi":"Nhịp sống hối hả và căng thẳng của cuộc sống đô thị có thể làm gia tăng áp lực và khiến cư dân có rất ít thời gian để thư giãn.","audioKind":"ex2"}],"collocations":[{"en":"a frantic search","vi":"cuộc tìm kiếm khẩn trương"},{"en":"frantic efforts","vi":"những nỗ lực cuồng nhiệt"},{"en":"a frantic pace","vi":"nhịp độ tất bật"},{"en":"frantic with worry","vi":"lo lắng đến phát cuồng"}],"wordFamily":["frantically (adv.)"],"synonyms":["panicked","frenzied"],"antonyms":["calm"],"tipVi":"Nhấn mạnh sự lo lắng mất kiểm soát hoặc bấn loạn, không đồng nghĩa với việc mất trí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kindle', 'en-c1-34', 'kindle', '/ˈkɪndl/', 'C1', 'nhen nhóm ngọn lửa hoặc bắt đầu cháy; làm nảy sinh, khơi gợi cảm xúc hoặc sự hứng thú', 'v.', 'kindling (n.), rekindle (v.)', 'Đồng nghĩa: ignite, arouse · Trái nghĩa: extinguish', 'Mang tính trang trọng hoặc văn chương; có thể dùng cho việc đốt lửa lẫn khơi dậy cảm xúc.', 'We used dry twigs to kindle a small fire.', NULL, 'Chúng tôi dùng cành cây khô để nhóm một đống lửa nhỏ.', '{"wordId":"kindle","ukIpa":"/ˈkɪndl/","usIpa":"/ˈkɪndl/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To start a fire or begin to burn.","vi":"nhen nhóm ngọn lửa hoặc bắt đầu cháy"},{"pos":"v.","en":"To cause a feeling or interest to develop.","vi":"làm nảy sinh, khơi gợi cảm xúc hoặc sự hứng thú"}],"examples":[{"en":"We used dry twigs to kindle a small fire.","vi":"Chúng tôi dùng cành cây khô để nhóm một đống lửa nhỏ.","audioKind":"ex"},{"en":"Visits to science museums can kindle children''s curiosity and encourage them to explore unfamiliar scientific ideas.","vi":"Những chuyến tham quan bảo tàng khoa học có thể khơi gợi trí tò mò của trẻ em và khuyến khích các em khám phá những ý tưởng khoa học mới lạ.","audioKind":"ex2"}],"collocations":[{"en":"kindle a fire","vi":"nhóm lửa"},{"en":"kindle interest","vi":"khơi gợi hứng thú"},{"en":"kindle hope","vi":"thắp lên hy vọng"}],"wordFamily":["kindling (n.)","rekindle (v.)"],"synonyms":["ignite","arouse"],"antonyms":["extinguish"],"tipVi":"Mang tính trang trọng hoặc văn chương; có thể dùng cho việc đốt lửa lẫn khơi dậy cảm xúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regretfully', 'en-c1-34', 'regretfully', '/rɪˈɡretfəli/', 'C1', 'một cách đầy tiếc nuối, thể hiện sự buồn bã hoặc thất vọng về điều gì đó', 'adv.', 'regret (v.), regretful (adj.), regrettable (adj.), regrettably (adv.)', 'Đồng nghĩa: ruefully', '"regretfully" nhấn mạnh sự tiếc nuối của con người; "regrettably" dùng để đánh giá sự việc là đáng tiếc.', 'I regretfully declined the invitation because I was working.', NULL, 'Tôi đành ngậm ngùi từ chối lời mời vì bận làm việc.', '{"wordId":"regretfully","ukIpa":"/rɪˈɡretfəli/","usIpa":"/rɪˈɡretfəli/","cefr":"C1","topic":"emotion","senses":[{"pos":"adv.","en":"In a way that expresses sadness or disappointment about something.","vi":"một cách đầy tiếc nuối, thể hiện sự buồn bã hoặc thất vọng về điều gì đó"}],"examples":[{"en":"I regretfully declined the invitation because I was working.","vi":"Tôi đành ngậm ngùi từ chối lời mời vì bận làm việc.","audioKind":"ex"},{"en":"The council regretfully announced that budget constraints would delay the construction of a new community centre.","vi":"Hội đồng thành phố ngậm ngùi thông báo rằng những hạn chế về ngân sách sẽ làm chậm tiến độ xây dựng một trung tâm cộng đồng mới.","audioKind":"ex2"}],"collocations":[{"en":"regretfully decline","vi":"tiếc nuối từ chối"},{"en":"regretfully admit","vi":"tiếc nuối thừa nhận"},{"en":"regretfully announce","vi":"tiếc nuối thông báo"}],"wordFamily":["regret (v.)","regretful (adj.)","regrettable (adj.)","regrettably (adv.)"],"synonyms":["ruefully"],"antonyms":[],"tipVi":"\"regretfully\" nhấn mạnh sự tiếc nuối của con người; \"regrettably\" dùng để đánh giá sự việc là đáng tiếc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tranquility', 'en-c1-34', 'tranquility', '/træŋˈkwɪləti/', 'C1', 'sự thanh bình, yên ả, không có tiếng ồn, lo lắng hay quấy rầy', 'n.', 'tranquil (adj.), tranquilly (adv.)', 'Đồng nghĩa: calm, peace, serenity · Trái nghĩa: turmoil', 'Tiếng Anh Mỹ thường viết là "tranquility", trong khi tiếng Anh - Anh thường viết là "tranquillity".', 'We enjoyed the tranquility of the garden at dawn.', NULL, 'Chúng tôi tận hưởng vẻ yên bình của khu vườn vào lúc bình minh.', '{"wordId":"tranquility","ukIpa":"/træŋˈkwɪləti/","usIpa":"/træŋˈkwɪləti/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"a peaceful state without noise, worry, or disturbance","vi":"sự thanh bình, yên ả, không có tiếng ồn, lo lắng hay quấy rầy"}],"examples":[{"en":"We enjoyed the tranquility of the garden at dawn.","vi":"Chúng tôi tận hưởng vẻ yên bình của khu vườn vào lúc bình minh.","audioKind":"ex"},{"en":"Urban parks offer residents a sense of tranquility that can help reduce everyday stress.","vi":"Các công viên trong thành phố mang lại cho cư dân cảm giác thanh bình, giúp xoa dịu áp lực thường ngày.","audioKind":"ex2"}],"collocations":[{"en":"a sense of tranquility","vi":"cảm giác yên bình"},{"en":"peace and tranquility","vi":"sự yên tĩnh và thanh bình"},{"en":"enjoy the tranquility","vi":"tận hưởng sự tĩnh lặng"}],"wordFamily":["tranquil (adj.)","tranquilly (adv.)"],"synonyms":["calm","peace","serenity"],"antonyms":["turmoil"],"tipVi":"Tiếng Anh Mỹ thường viết là \"tranquility\", trong khi tiếng Anh - Anh thường viết là \"tranquillity\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mourning', 'en-c1-34', 'mourning', '/ˈmɔːrnɪŋ/', 'C1', 'sự đau buồn; sự tang tóc; thời gian tang lễ', 'n.', 'mourn (v.), mourner (n.), mournful (adj.)', 'Đồng nghĩa: grief', 'Phát âm giống từ morning; cụm từ in mourning diễn tả trạng thái đang chịu tang.', 'Neighbours brought warm meals to the family in mourning.', NULL, 'Những người hàng xóm đã mang những bữa ăn ấm áp đến cho gia đình đang có tang.', '{"wordId":"mourning","ukIpa":"/ˈmɔːnɪŋ/","usIpa":"/ˈmɔːrnɪŋ/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"sadness expressed after someone''s death","vi":"sự đau buồn; sự tang tóc; thời gian tang lễ"}],"examples":[{"en":"Neighbours brought warm meals to the family in mourning.","vi":"Những người hàng xóm đã mang những bữa ăn ấm áp đến cho gia đình đang có tang.","audioKind":"ex"},{"en":"Public ceremonies can provide shared spaces for mourning and help communities support those affected by loss.","vi":"Các buổi lễ công cộng có thể cung cấp không gian chung để tưởng niệm và giúp cộng đồng hỗ trợ những người chịu ảnh hưởng bởi sự mất mát.","audioKind":"ex2"}],"collocations":[{"en":"in mourning","vi":"đang chịu tang"},{"en":"a period of mourning","vi":"một khoảng thời gian để tang"},{"en":"national mourning","vi":"ngày quốc tang"}],"wordFamily":["mourn (v.)","mourner (n.)","mournful (adj.)"],"synonyms":["grief"],"antonyms":[],"tipVi":"Phát âm giống từ morning; cụm từ in mourning diễn tả trạng thái đang chịu tang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reproach', 'en-c1-34', 'reproach', '/rɪˈproʊtʃ/', 'C1', 'trách mắng; chỉ trích; lời trách mắng; sự chỉ trích', 'v.', 'reproachful (adj.), reproachfully (adv.)', 'Đồng nghĩa: criticize, rebuke · Trái nghĩa: praise', 'Cấu trúc trách mắng ai làm gì: reproach sb for doing sth.', 'She reproached her brother for leaving the gate open.', NULL, 'Cô ấy trách mắng anh trai vì đã để cửa mở.', '{"wordId":"reproach","ukIpa":"/rɪˈprəʊtʃ/","usIpa":"/rɪˈproʊtʃ/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"Express disappointment or criticism about someone''s actions","vi":"trách mắng; chỉ trích"},{"pos":"n.","en":"An expression of disappointment or criticism","vi":"lời trách mắng; sự chỉ trích"}],"examples":[{"en":"She reproached her brother for leaving the gate open.","vi":"Cô ấy trách mắng anh trai vì đã để cửa mở.","audioKind":"ex"},{"en":"Teachers should offer constructive guidance rather than reproach students for mistakes made during the learning process.","vi":"Giáo viên nên đưa ra sự hướng dẫn mang tính xây dựng thay vì trách mắng học sinh vì những lỗi lầm mắc phải trong quá trình học tập.","audioKind":"ex2"}],"collocations":[{"en":"reproach someone for","vi":"trách mắng ai vì điều gì"},{"en":"beyond reproach","vi":"hoàn toàn vô tội; không có gì để chê trách"},{"en":"a look of reproach","vi":"ánh mắt trách móc"}],"wordFamily":["reproachful (adj.)","reproachfully (adv.)"],"synonyms":["criticize","rebuke"],"antonyms":["praise"],"tipVi":"Cấu trúc trách mắng ai làm gì: reproach sb for doing sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vain', 'en-c1-34', 'vain', '/veɪn/', 'C1', 'vô ích; không thành công; tự phụ; hão huyền; hư vinh', 'adj.', 'vainly (adv.), vanity (n.)', 'Đồng nghĩa: futile, conceited · Trái nghĩa: effective, modest', 'Cụm in vain làm trạng ngữ chỉ sự vô ích; vain cũng có nghĩa là tính toán thiệt hơn hoặc kiêu ngạo.', 'We made a vain attempt to repair the umbrella.', NULL, 'Chúng tôi đã cố gắng sửa chiếc ô một cách vô ích.', '{"wordId":"vain","ukIpa":"/veɪn/","usIpa":"/veɪn/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"failing to achieve the intended result","vi":"vô ích; không thành công"},{"pos":"adj.","en":"too proud of your appearance or achievements","vi":"tự phụ; hão huyền; hư vinh"}],"examples":[{"en":"We made a vain attempt to repair the umbrella.","vi":"Chúng tôi đã cố gắng sửa chiếc ô một cách vô ích.","audioKind":"ex"},{"en":"Without affordable public transport, campaigns to reduce private car use may prove to be vain efforts.","vi":"Nếu thiếu các phương tiện giao thông công cộng có giá cả phải chăng, các chiến dịch giảm thiểu việc sử dụng xe cá nhân có thể chỉ là những nỗ lực dã tràng xe cát.","audioKind":"ex2"}],"collocations":[{"en":"a vain attempt","vi":"một nỗ lực vô ích"},{"en":"in vain","vi":"công cốc; hoài công"},{"en":"a vain hope","vi":"một niềm hy vọng mong manh"}],"wordFamily":["vainly (adv.)","vanity (n.)"],"synonyms":["futile","conceited"],"antonyms":["effective","modest"],"tipVi":"Cụm in vain làm trạng ngữ chỉ sự vô ích; vain cũng có nghĩa là tính toán thiệt hơn hoặc kiêu ngạo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_timidity', 'en-c1-34', 'timidity', '/tɪˈmɪdəti/', 'C1', 'tính nhút nhát; sự thiếu tự tin', 'n.', 'timid (adj.), timidly (adv.)', 'Đồng nghĩa: shyness, diffidence · Trái nghĩa: confidence, boldness', 'Đây là danh từ không đếm được; tính từ tương ứng là timid, dùng để chỉ sự rụt rè, thiếu tự tin.', 'Her timidity made asking for help difficult at first.', NULL, 'Sự nhút nhát khiến cô ấy ban đầu gặp khó khăn khi muốn nhờ giúp đỡ.', '{"wordId":"timidity","ukIpa":"/tɪˈmɪdəti/","usIpa":"/tɪˈmɪdəti/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"A lack of courage or confidence in facing people or situations.","vi":"tính nhút nhát; sự thiếu tự tin"}],"examples":[{"en":"Her timidity made asking for help difficult at first.","vi":"Sự nhút nhát khiến cô ấy ban đầu gặp khó khăn khi muốn nhờ giúp đỡ.","audioKind":"ex"},{"en":"Supportive classroom environments can reduce students'' timidity and encourage them to participate more actively in discussions.","vi":"Môi trường lớp học mang tính hỗ trợ có thể làm giảm bớt sự nhút nhát của học sinh và khuyến khích các em tham gia tích cực hơn vào các cuộc thảo luận.","audioKind":"ex2"}],"collocations":[{"en":"overcome timidity","vi":"vượt qua sự nhút nhát"},{"en":"natural timidity","vi":"tính nhút nhát tự nhiên"},{"en":"timidity and hesitation","vi":"sự nhút nhát và do dự"}],"wordFamily":["timid (adj.)","timidly (adv.)"],"synonyms":["shyness","diffidence"],"antonyms":["confidence","boldness"],"tipVi":"Đây là danh từ không đếm được; tính từ tương ứng là timid, dùng để chỉ sự rụt rè, thiếu tự tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intimidate', 'en-c1-34', 'intimidate', '/ɪnˈtɪmɪdeɪt/', 'C1', 'đe dọa; khủng bố tinh thần; làm cho sợ hãi; làm cho mất tự tin', 'v.', 'intimidation (n.), intimidating (adj.), intimidated (adj.)', 'Đồng nghĩa: frighten, overawe · Trái nghĩa: reassure', 'Cấu trúc intimidate sb into doing sth có nghĩa là đe dọa hoặc ép buộc ai đó làm việc gì.', 'The large audience intimidated her before her first performance.', NULL, 'Khán giả quá đông đã khiến cô ấy cảm thấy hơi rụt rè trước buổi biểu diễn đầu tiên.', '{"wordId":"intimidate","ukIpa":"/ɪnˈtɪmɪdeɪt/","usIpa":"/ɪnˈtɪmɪdeɪt/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To frighten someone, often to make them obey","vi":"đe dọa; khủng bố tinh thần"},{"pos":"v.","en":"To make someone feel nervous or less confident","vi":"làm cho sợ hãi; làm cho mất tự tin"}],"examples":[{"en":"The large audience intimidated her before her first performance.","vi":"Khán giả quá đông đã khiến cô ấy cảm thấy hơi rụt rè trước buổi biểu diễn đầu tiên.","audioKind":"ex"},{"en":"Employers should never intimidate workers into accepting unsafe conditions or giving up their legal rights.","vi":"Người sử dụng lao động không bao giờ nên ép buộc công nhân chấp nhận các điều kiện không an toàn hoặc từ bỏ quyền lợi hợp pháp của họ.","audioKind":"ex2"}],"collocations":[{"en":"intimidate someone into doing something","vi":"đe dọa ai đó làm việc gì"},{"en":"feel intimidated","vi":"cảm thấy bị đe dọa hoặc sợ hãi"},{"en":"intimidate witnesses","vi":"đe dọa nhân chứng"}],"wordFamily":["intimidation (n.)","intimidating (adj.)","intimidated (adj.)"],"synonyms":["frighten","overawe"],"antonyms":["reassure"],"tipVi":"Cấu trúc intimidate sb into doing sth có nghĩa là đe dọa hoặc ép buộc ai đó làm việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dismay', 'en-c1-34', 'dismay', '/dɪsˈmeɪ/', 'C1', 'sự kinh ngạc; sự thất vọng; làm kinh ngạc; làm thất vọng', 'n.', 'dismayed (adj.), dismaying (adj.)', 'Đồng nghĩa: consternation, distress · Trái nghĩa: delight', 'Danh từ thường không đếm được; cụm từ to one''s dismay có nghĩa là điều làm ai đó cảm thấy thất vọng.', 'To my dismay, the cake collapsed in the oven.', NULL, 'Điều làm tôi thất vọng là chiếc bánh ngọt đã bị xẹp trong lò nướng.', '{"wordId":"dismay","ukIpa":"/dɪsˈmeɪ/","usIpa":"/dɪsˈmeɪ/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"Shock and disappointment caused by something unexpected and unpleasant.","vi":"sự kinh ngạc; sự thất vọng"},{"pos":"v.","en":"To make someone feel shocked and disappointed.","vi":"làm kinh ngạc; làm thất vọng"}],"examples":[{"en":"To my dismay, the cake collapsed in the oven.","vi":"Điều làm tôi thất vọng là chiếc bánh ngọt đã bị xẹp trong lò nướng.","audioKind":"ex"},{"en":"Residents expressed dismay at plans to replace their local park with a large commercial development.","vi":"Cư dân đã bày tỏ sự thất vọng và bàng hoàng trước các kế hoạch thay thế công viên địa phương bằng một khu phức hợp thương mại lớn.","audioKind":"ex2"}],"collocations":[{"en":"to someone''s dismay","vi":"làm ai đó thất vọng/kinh ngạc"},{"en":"express dismay","vi":"bày tỏ sự thất vọng"},{"en":"be dismayed at","vi":"cảm thấy kinh ngạc/thất vọng về"}],"wordFamily":["dismayed (adj.)","dismaying (adj.)"],"synonyms":["consternation","distress"],"antonyms":["delight"],"tipVi":"Danh từ thường không đếm được; cụm từ to one''s dismay có nghĩa là điều làm ai đó cảm thấy thất vọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exasperate', 'en-c1-34', 'exasperate', '/ɪɡˈzæspəreɪt/', 'C1', 'làm cho phát bực; chọc tức; làm bực mình', 'v.', 'exasperation (n.), exasperated (adj.), exasperating (adj.)', 'Đồng nghĩa: infuriate, irritate, annoy · Trái nghĩa: soothe', 'Tránh nhầm lẫn với exacerbate: từ đó có nghĩa là làm cho vấn đề trở nên tồi tệ hơn.', 'The printer''s constant paper jams exasperate everyone in our office.', NULL, 'Tình trạng kẹt giấy liên tục của máy in khiến tất cả mọi người trong văn phòng chúng tôi phát điên.', '{"wordId":"exasperate","ukIpa":"/ɪɡˈzɑːspəreɪt/","usIpa":"/ɪɡˈzæspəreɪt/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To make someone extremely annoyed or frustrated.","vi":"làm cho phát bực; chọc tức; làm bực mình"}],"examples":[{"en":"The printer''s constant paper jams exasperate everyone in our office.","vi":"Tình trạng kẹt giấy liên tục của máy in khiến tất cả mọi người trong văn phòng chúng tôi phát điên.","audioKind":"ex"},{"en":"Repeated delays in public transport can exasperate commuters and reduce their willingness to leave cars at home.","vi":"Tình trạng chậm chuyến liên tục của phương tiện công cộng có thể làm hành khách phát bực và giảm bớt ý muốn bỏ xe ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"exasperate commuters","vi":"làm hành khách phát bực"},{"en":"exasperate customers","vi":"làm khách hàng phiền lòng"},{"en":"feel exasperated","vi":"cảm thấy bực bội"}],"wordFamily":["exasperation (n.)","exasperated (adj.)","exasperating (adj.)"],"synonyms":["infuriate","irritate","annoy"],"antonyms":["soothe"],"tipVi":"Tránh nhầm lẫn với exacerbate: từ đó có nghĩa là làm cho vấn đề trở nên tồi tệ hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ordeal', 'en-c1-34', 'ordeal', '/ɔːrˈdiːl/', 'C1', 'thử thách khắc nghiệt; trải nghiệm đau thương', 'n.', NULL, 'Đồng nghĩa: trial', 'Chỉ những trải nghiệm gây đau đớn hoặc sợ hãi, không dùng cho những rắc rối nhỏ thông thường.', 'Getting home through the storm was a real ordeal.', NULL, 'Việc vượt qua cơn bão để về nhà thực sự là một trải nghiệm kinh hoàng.', '{"wordId":"ordeal","ukIpa":"/ɔːˈdiːl/","usIpa":"/ɔːrˈdiːl/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"A difficult or frightening experience that lasts for some time.","vi":"thử thách khắc nghiệt; trải nghiệm đau thương"}],"examples":[{"en":"Getting home through the storm was a real ordeal.","vi":"Việc vượt qua cơn bão để về nhà thực sự là một trải nghiệm kinh hoàng.","audioKind":"ex"},{"en":"For displaced families, finding secure housing can become a prolonged ordeal without adequate public support.","vi":"Đối với các gia đình phải di dời, việc tìm kiếm nhà ở an toàn có thể trở thành một chuỗi ngày gian khổ kéo dài nếu thiếu sự hỗ trợ đầy đủ từ cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"go through an ordeal","vi":"trải qua hoạn nạn"},{"en":"a traumatic ordeal","vi":"trải nghiệm gây sang chấn tâm lý"},{"en":"a prolonged ordeal","vi":"khoảng thời gian gian khổ kéo dài"}],"wordFamily":[],"synonyms":["trial"],"antonyms":[],"tipVi":"Chỉ những trải nghiệm gây đau đớn hoặc sợ hãi, không dùng cho những rắc rối nhỏ thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apprehension', 'en-c1-34', 'apprehension', '/ˌæprɪˈhenʃən/', 'C1', 'sự lo lắng; sự e sợ; sự bắt giữ; sự tóm gọn', 'n.', 'apprehensive (adj.), apprehensively (adv.), apprehend (v.)', 'Đồng nghĩa: anxiety, unease · Trái nghĩa: confidence', 'Thường chỉ sự lo lắng cho tương lai, hay đi với about; nghĩa bắt giữ mang tính trang trọng hơn.', 'She felt some apprehension before her first driving lesson.', NULL, 'Cô ấy cảm thấy có chút lo lắng trước buổi học lái xe đầu tiên.', '{"wordId":"apprehension","ukIpa":"/ˌæprɪˈhenʃən/","usIpa":"/ˌæprɪˈhenʃən/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"Worry that something unpleasant may happen.","vi":"sự lo lắng; sự e sợ"},{"pos":"n.","en":"The act of catching and arresting someone suspected of a crime.","vi":"sự bắt giữ; sự tóm gọn"}],"examples":[{"en":"She felt some apprehension before her first driving lesson.","vi":"Cô ấy cảm thấy có chút lo lắng trước buổi học lái xe đầu tiên.","audioKind":"ex"},{"en":"Public apprehension about new technologies may decrease when governments explain potential risks and introduce clear safety standards.","vi":"Sự lo lắng của công chúng về các công nghệ mới có thể giảm bớt khi chính phủ giải thích các rủi ro tiềm ẩn và đưa ra các tiêu chuẩn an toàn rõ ràng.","audioKind":"ex2"}],"collocations":[{"en":"apprehension about","vi":"sự lo lắng về"},{"en":"a sense of apprehension","vi":"cảm giác lo âu"},{"en":"with apprehension","vi":"với vẻ lo sợ"}],"wordFamily":["apprehensive (adj.)","apprehensively (adv.)","apprehend (v.)"],"synonyms":["anxiety","unease"],"antonyms":["confidence"],"tipVi":"Thường chỉ sự lo lắng cho tương lai, hay đi với about; nghĩa bắt giữ mang tính trang trọng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grieve', 'en-c1-34', 'grieve', '/ɡriːv/', 'C1', 'đau buồn; thương tiếc; chịu tang; gây đau buồn sâu sắc', 'v.', 'grief (n.), grieving (adj.)', 'Đồng nghĩa: mourn', 'grieve for thường đi với người đã khuất; grieve over thường đi với sự mất mát hoặc bất hạnh.', 'We still grieve for our cat, who died last spring.', NULL, 'Chúng tôi vẫn vô cùng thương tiếc con mèo đã qua đời vào mùa xuân năm ngoái của gia đình.', '{"wordId":"grieve","ukIpa":"/ɡriːv/","usIpa":"/ɡriːv/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To feel deep sadness, especially after someone''s death","vi":"đau buồn; thương tiếc; chịu tang"},{"pos":"v.","en":"To cause someone deep sadness","vi":"gây đau buồn sâu sắc"}],"examples":[{"en":"We still grieve for our cat, who died last spring.","vi":"Chúng tôi vẫn vô cùng thương tiếc con mèo đã qua đời vào mùa xuân năm ngoái của gia đình.","audioKind":"ex"},{"en":"Employers should offer compassionate leave so that workers have time to grieve after losing a family member.","vi":"Các nhà tuyển dụng nên cung cấp chế độ nghỉ có lương khi có tang để nhân viên có thời gian nguôi ngoai sau khi mất đi người thân.","audioKind":"ex2"}],"collocations":[{"en":"grieve for someone","vi":"thương tiếc ai đó"},{"en":"grieve over a loss","vi":"đau buồn vì sự mất mát"},{"en":"time to grieve","vi":"thời gian để chịu tang"}],"wordFamily":["grief (n.)","grieving (adj.)"],"synonyms":["mourn"],"antonyms":[],"tipVi":"grieve for thường đi với người đã khuất; grieve over thường đi với sự mất mát hoặc bất hạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evoke', 'en-c1-34', 'evoke', '/ɪˈvoʊk/', 'C1', 'gợi lên; gợi nhớ; đánh thức', 'v.', 'evocation (n.), evocative (adj.)', 'Đồng nghĩa: arouse, elicit', 'Có thể kết hợp trực tiếp với các tân ngữ chỉ cảm xúc, kỷ niệm mà không cần dùng giới từ như of.', 'The smell of fresh bread evokes memories of home.', NULL, 'Mùi hương của bánh mì mới nướng gợi lại những kỷ niệm về mái ấm gia đình.', '{"wordId":"evoke","ukIpa":"/ɪˈvəʊk/","usIpa":"/ɪˈvoʊk/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"to bring a feeling, memory or image into someone''s mind","vi":"gợi lên; gợi nhớ; đánh thức"}],"examples":[{"en":"The smell of fresh bread evokes memories of home.","vi":"Mùi hương của bánh mì mới nướng gợi lại những kỷ niệm về mái ấm gia đình.","audioKind":"ex"},{"en":"Traditional music can evoke a strong sense of belonging among people living far from their homeland.","vi":"Âm nhạc truyền thống có thể khơi gợi cảm giác thân thuộc mạnh mẽ ở những người sống xa quê hương.","audioKind":"ex2"}],"collocations":[{"en":"evoke memories","vi":"gợi nhắc ký ức"},{"en":"evoke emotions","vi":"khơi gợi cảm xúc"},{"en":"evoke an image","vi":"gợi lên hình ảnh"},{"en":"evoke sympathy","vi":"gây ra sự đồng cảm"}],"wordFamily":["evocation (n.)","evocative (adj.)"],"synonyms":["arouse","elicit"],"antonyms":[],"tipVi":"Có thể kết hợp trực tiếp với các tân ngữ chỉ cảm xúc, kỷ niệm mà không cần dùng giới từ như of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dogged', 'en-c1-34', 'dogged', '/ˈdɔːɡɪd/', 'C1', 'bền bỉ; kiên cường; kiên trì không lùi bước', 'adj.', 'doggedly (adv.), doggedness (n.)', 'Đồng nghĩa: determined, persistent, tenacious · Trái nghĩa: half-hearted', 'Khi là tính từ, từ này có hai âm tiết và thường nhấn mạnh thái độ không dễ dàng từ bỏ.', 'His dogged efforts finally brought the old garden back.', NULL, 'Những nỗ lực bền bỉ của ông ấy cuối cùng đã khôi phục lại khu vườn cũ.', '{"wordId":"dogged","ukIpa":"/ˈdɒɡɪd/","usIpa":"/ˈdɔːɡɪd/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Continuing with determination despite difficulties or setbacks.","vi":"bền bỉ; kiên cường; kiên trì không lùi bước"}],"examples":[{"en":"His dogged efforts finally brought the old garden back.","vi":"Những nỗ lực bền bỉ của ông ấy cuối cùng đã khôi phục lại khu vườn cũ.","audioKind":"ex"},{"en":"Dogged determination enables many researchers to continue investigating important questions despite repeated failures and limited funding.","vi":"Sự quyết tâm bền bỉ giúp nhiều nhà nghiên cứu tiếp tục theo đuổi các vấn đề quan trọng mặc dù gặp thất bại lặp đi lặp lại và nguồn kinh phí hạn hẹp.","audioKind":"ex2"}],"collocations":[{"en":"dogged determination","vi":"quyết tâm bền bỉ"},{"en":"dogged persistence","vi":"sự kiên trì bền bỉ"},{"en":"dogged pursuit","vi":"sự theo đuổi kiên trì"}],"wordFamily":["doggedly (adv.)","doggedness (n.)"],"synonyms":["determined","persistent","tenacious"],"antonyms":["half-hearted"],"tipVi":"Khi là tính từ, từ này có hai âm tiết và thường nhấn mạnh thái độ không dễ dàng từ bỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arouse', 'en-c1-34', 'arouse', '/əˈraʊz/', 'C1', 'khơi dậy; gây ra; kích thích; đánh thức', 'v.', 'arousal (n.)', 'Đồng nghĩa: provoke, awaken', 'arouse sau đó phải đi với tân ngữ; còn arise có nghĩa là xuất hiện và không cần tân ngữ.', 'The locked wooden box aroused my curiosity immediately.', NULL, 'Cái hộp gỗ có khóa ngay lập tức khơi gợi sự tò mò của tôi.', '{"wordId":"arouse","ukIpa":"/əˈraʊz/","usIpa":"/əˈraʊz/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To cause a feeling, interest, or reaction.","vi":"khơi dậy; gây ra; kích thích"},{"pos":"v.","en":"To wake someone from sleep.","vi":"đánh thức"}],"examples":[{"en":"The locked wooden box aroused my curiosity immediately.","vi":"Cái hộp gỗ có khóa ngay lập tức khơi gợi sự tò mò của tôi.","audioKind":"ex"},{"en":"Proposals to replace public parks with commercial buildings are likely to arouse strong opposition among local residents.","vi":"Các đề xuất thay thế công viên công cộng bằng các tòa nhà thương mại có khả năng vấp phải sự phản đối mạnh mẽ từ cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"arouse curiosity","vi":"khơi gợi sự tò mò"},{"en":"arouse suspicion","vi":"gây ra sự nghi ngờ"},{"en":"arouse interest","vi":"khơi dậy sự quan tâm"},{"en":"arouse opposition","vi":"khơi mào sự phản đối"}],"wordFamily":["arousal (n.)"],"synonyms":["provoke","awaken"],"antonyms":[],"tipVi":"arouse sau đó phải đi với tân ngữ; còn arise có nghĩa là xuất hiện và không cần tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nostalgia', 'en-c1-34', 'nostalgia', '/nɑːˈstældʒə/', 'C1', 'niềm hoài niệm, sự nhớ tiếc quá khứ', 'n.', 'nostalgic (adj.), nostalgically (adv.)', NULL, 'Thường là danh từ không đếm được; theo sau bởi ''nostalgia for'' để chỉ khoảng thời gian hoặc sự việc được hoài niệm.', 'That old song fills me with nostalgia for school.', NULL, 'Bài hát cũ đó gợi lại trong tôi biết bao nỗi niềm hoài niệm về thời đi học.', '{"wordId":"nostalgia","ukIpa":"/nɒˈstældʒə/","usIpa":"/nɑːˈstældʒə/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"warm, sometimes sad feelings about happy times in the past","vi":"niềm hoài niệm, sự nhớ tiếc quá khứ"}],"examples":[{"en":"That old song fills me with nostalgia for school.","vi":"Bài hát cũ đó gợi lại trong tôi biết bao nỗi niềm hoài niệm về thời đi học.","audioKind":"ex"},{"en":"Nostalgia can encourage communities to preserve historic buildings, even when modern developments promise greater convenience.","vi":"Sự hoài niệm có thể thúc đẩy cộng đồng gìn giữ các tòa nhà lịch sử, ngay cả khi các dự án phát triển hiện đại hứa hẹn mang lại nhiều sự tiện nghi hơn.","audioKind":"ex2"}],"collocations":[{"en":"nostalgia for the past","vi":"nỗi hoài niệm về quá khứ"},{"en":"a wave of nostalgia","vi":"một làn sóng hoài niệm"},{"en":"evoke nostalgia","vi":"gợi lại niềm hoài niệm"}],"wordFamily":["nostalgic (adj.)","nostalgically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; theo sau bởi ''nostalgia for'' để chỉ khoảng thời gian hoặc sự việc được hoài niệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_34_1', 'en-c1-34', 'Cách dùng “clench” (v.) — siết chặt; mím chặt', 'clench your fists  ·  clench your teeth  ·  clench your jaw', 'clench dùng cho hành động siết chặt tay hoặc hàm; trong khi clinch mới dùng cho việc giành chiến thắng hoặc chốt hạ thỏa thuận.', 'Trái nghĩa: unclench', '[{"hanzi":"Arun clenched his fists as the cold wind blew.","pinyin":"","meaning":"Arun siết chặt hai tay lại khi cơn gió lạnh thổi qua."},{"hanzi":"People under prolonged stress may clench their teeth during sleep, potentially causing pain in the jaw.","pinyin":"","meaning":"Những người chịu áp lực kéo dài có thể nghiến chặt răng khi ngủ, có thể gây ra đau ở phần hàm."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_34_2', 'en-c1-34', 'Cách dùng “nostalgia” (n.) — niềm hoài niệm, sự nhớ tiếc quá khứ', 'nostalgia for the past  ·  a wave of nostalgia  ·  evoke nostalgia', 'Thường là danh từ không đếm được; theo sau bởi ''nostalgia for'' để chỉ khoảng thời gian hoặc sự việc được hoài niệm.', 'Họ từ (Word Family): nostalgic (adj.), nostalgically (adv.)', '[{"hanzi":"That old song fills me with nostalgia for school.","pinyin":"","meaning":"Bài hát cũ đó gợi lại trong tôi biết bao nỗi niềm hoài niệm về thời đi học."},{"hanzi":"Nostalgia can encourage communities to preserve historic buildings, even when modern developments promise greater convenience.","pinyin":"","meaning":"Sự hoài niệm có thể thúc đẩy cộng đồng gìn giữ các tòa nhà lịch sử, ngay cả khi các dự án phát triển hiện đại hứa hẹn mang lại nhiều sự tiện nghi hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_34_3', 'en-c1-34', 'Cách dùng “regretfully” (adv.) — một cách đầy tiếc nuối, thể hiện sự buồn bã hoặc thất vọng về điều gì đó', 'regretfully decline  ·  regretfully admit  ·  regretfully announce', '"regretfully" nhấn mạnh sự tiếc nuối của con người; "regrettably" dùng để đánh giá sự việc là đáng tiếc.', 'Họ từ (Word Family): regret (v.), regretful (adj.), regrettable (adj.), regrettably (adv.) | Đồng nghĩa: ruefully', '[{"hanzi":"I regretfully declined the invitation because I was working.","pinyin":"","meaning":"Tôi đành ngậm ngùi từ chối lời mời vì bận làm việc."},{"hanzi":"The council regretfully announced that budget constraints would delay the construction of a new community centre.","pinyin":"","meaning":"Hội đồng thành phố ngậm ngùi thông báo rằng những hạn chế về ngân sách sẽ làm chậm tiến độ xây dựng một trung tâm cộng đồng mới."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_34_4', 'en-c1-34', 'Cách dùng “dismay” (n.) — sự kinh ngạc; sự thất vọng', 'to someone''s dismay  ·  express dismay  ·  be dismayed at', 'Danh từ thường không đếm được; cụm từ to one''s dismay có nghĩa là điều làm ai đó cảm thấy thất vọng.', 'Họ từ (Word Family): dismayed (adj.), dismaying (adj.) | Đồng nghĩa: consternation, distress · Trái nghĩa: delight', '[{"hanzi":"To my dismay, the cake collapsed in the oven.","pinyin":"","meaning":"Điều làm tôi thất vọng là chiếc bánh ngọt đã bị xẹp trong lò nướng."},{"hanzi":"Residents expressed dismay at plans to replace their local park with a large commercial development.","pinyin":"","meaning":"Cư dân đã bày tỏ sự thất vọng và bàng hoàng trước các kế hoạch thay thế công viên địa phương bằng một khu phức hợp thương mại lớn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_34_1', 'en-c1-34', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_1_1', 'ten_c1_34_1', 'grudge', 'She still holds a grudge over the broken vase.', 'She still holds a grudge over the broken vase.', '/ɡrʌdʒ/', 'Cô ấy vẫn ôm hận chuyện cái bình hoa bị vỡ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_1_2', 'ten_c1_34_1', 'clench', 'Arun clenched his fists as the cold wind blew.', 'Arun clenched his fists as the cold wind blew.', '/klentʃ/', 'Arun siết chặt hai tay lại khi cơn gió lạnh thổi qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_1_3', 'ten_c1_34_1', 'serenity', 'I love the serenity of the garden at dawn.', 'I love the serenity of the garden at dawn.', '/səˈrenəti/', 'Tôi rất thích sự thanh bình của khu vườn vào lúc bình minh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_1_4', 'ten_c1_34_1', 'hateful', 'His hateful remarks upset everyone sitting around the table.', 'His hateful remarks upset everyone sitting around the table.', '/ˈheɪtfəl/', 'Những lời cay nghiệt đầy ác ý của anh ấy làm phiền lòng tất cả mọi người ngồi quanh bàn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_1_5', 'ten_c1_34_1', 'frantic', 'I grew frantic when I couldn''t find my passport.', 'I grew frantic when I couldn''t find my passport.', '/ˈfræntɪk/', 'Tôi phát hoảng lên khi không tìm thấy hộ chiếu của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_1_6', 'ten_c1_34_1', 'kindle', 'We used dry twigs to kindle a small fire.', 'We used dry twigs to kindle a small fire.', '/ˈkɪndl/', 'Chúng tôi dùng cành cây khô để nhóm một đống lửa nhỏ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_1_7', 'ten_c1_34_1', 'regretfully', 'I regretfully declined the invitation because I was working.', 'I regretfully declined the invitation because I was working.', '/rɪˈɡretfəli/', 'Tôi đành ngậm ngùi từ chối lời mời vì bận làm việc.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_1_8', 'ten_c1_34_1', 'tranquility', 'We enjoyed the tranquility of the garden at dawn.', 'We enjoyed the tranquility of the garden at dawn.', '/træŋˈkwɪləti/', 'Chúng tôi tận hưởng vẻ yên bình của khu vườn vào lúc bình minh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_34_1_1', 'en-c1-34', 'ten_c1_34_1', 'listening', 'listening', 'She still holds a grudge over the broken vase.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy cảm thấy có chút lo lắng trước buổi học lái xe đầu tiên.","Chúng tôi dùng cành cây khô để nhóm một đống lửa nhỏ.","Cô ấy vẫn ôm hận chuyện cái bình hoa bị vỡ.","Cái hộp gỗ có khóa ngay lập tức khơi gợi sự tò mò của tôi."]'::jsonb, 2, 'She still holds a grudge over the broken vase. → Cô ấy vẫn ôm hận chuyện cái bình hoa bị vỡ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_34_1_2', 'en-c1-34', 'ten_c1_34_1', 'listening', 'listening', 'Arun clenched his fists as the cold wind blew.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy trách mắng anh trai vì đã để cửa mở.","Chúng tôi vẫn vô cùng thương tiếc con mèo đã qua đời vào mùa xuân năm ngoái của gia đình.","Chúng tôi dùng cành cây khô để nhóm một đống lửa nhỏ.","Arun siết chặt hai tay lại khi cơn gió lạnh thổi qua."]'::jsonb, 3, 'Arun clenched his fists as the cold wind blew. → Arun siết chặt hai tay lại khi cơn gió lạnh thổi qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_34_1_3', 'en-c1-34', 'ten_c1_34_1', 'listening', 'listening', 'I love the serenity of the garden at dawn.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi rất thích sự thanh bình của khu vườn vào lúc bình minh.","Tình trạng kẹt giấy liên tục của máy in khiến tất cả mọi người trong văn phòng chúng tôi phát điên.","Những nỗ lực bền bỉ của ông ấy cuối cùng đã khôi phục lại khu vườn cũ.","Khán giả quá đông đã khiến cô ấy cảm thấy hơi rụt rè trước buổi biểu diễn đầu tiên."]'::jsonb, 0, 'I love the serenity of the garden at dawn. → Tôi rất thích sự thanh bình của khu vườn vào lúc bình minh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_34_2', 'en-c1-34', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_2_1', 'ten_c1_34_2', 'grudge', 'Unresolved workplace conflicts can lead employees to hold grudges, reducing cooperation and damaging team morale.', 'Unresolved workplace conflicts can lead employees to hold grudges, reducing cooperation and damaging team morale.', '/ɡrʌdʒ/', 'Những mâu thuẫn chốn công sở chưa được giải quyết có thể khiến nhân viên nuôi lòng oán giận, làm giảm sự hợp tác và tổn hại tinh thần đồng đội.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_2_2', 'ten_c1_34_2', 'clench', 'People under prolonged stress may clench their teeth during sleep, potentially causing pain in the jaw.', 'People under prolonged stress may clench their teeth during sleep, potentially causing pain in the jaw.', '/klentʃ/', 'Những người chịu áp lực kéo dài có thể nghiến chặt răng khi ngủ, có thể gây ra đau ở phần hàm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_2_3', 'ten_c1_34_2', 'serenity', 'Access to quiet green spaces can offer urban residents a sense of serenity amid daily pressures.', 'Access to quiet green spaces can offer urban residents a sense of serenity amid daily pressures.', '/səˈrenəti/', 'Việc tiếp cận các không gian xanh yên tĩnh có thể mang lại cho cư dân đô thị cảm giác thanh thản giữa những áp lực thường ngày.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_2_4', 'ten_c1_34_2', 'hateful', 'Schools should address hateful behaviour early to ensure that all students feel safe and respected.', 'Schools should address hateful behaviour early to ensure that all students feel safe and respected.', '/ˈheɪtfəl/', 'Nhà trường nên xử lý sớm các hành vi đầy thù hận để đảm bảo rằng tất cả học sinh đều cảm thấy an toàn và được tôn trọng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_2_5', 'ten_c1_34_2', 'frantic', 'The frantic pace of urban life can increase stress and leave residents with little time for relaxation.', 'The frantic pace of urban life can increase stress and leave residents with little time for relaxation.', '/ˈfræntɪk/', 'Nhịp sống hối hả và căng thẳng của cuộc sống đô thị có thể làm gia tăng áp lực và khiến cư dân có rất ít thời gian để thư giãn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_34_2_6', 'ten_c1_34_2', 'kindle', 'Visits to science museums can kindle children''s curiosity and encourage them to explore unfamiliar scientific ideas.', 'Visits to science museums can kindle children''s curiosity and encourage them to explore unfamiliar scientific ideas.', '/ˈkɪndl/', 'Những chuyến tham quan bảo tàng khoa học có thể khơi gợi trí tò mò của trẻ em và khuyến khích các em khám phá những ý tưởng khoa học mới lạ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_34_2_1', 'en-c1-34', 'ten_c1_34_2', 'listening', 'listening', 'Unresolved workplace conflicts can lead employees to hold grudges, reducing cooperation and damaging team morale.', NULL, 'Trong câu vừa nghe, từ “grudge” mang nghĩa nào sau đây?', '["không ngừng nghỉ; liên tục không giảm","phân tán; giải tán","được miễn; được miễn trừ","mối hận thù; sự oán giận"]'::jsonb, 3, '“grudge” (/ɡrʌdʒ/): mối hận thù; sự oán giận. Câu đầy đủ: Unresolved workplace conflicts can lead employees to hold grudges, reducing cooperation and damaging team morale.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_34_2_2', 'en-c1-34', 'ten_c1_34_2', 'listening', 'listening', 'People under prolonged stress may clench their teeth during sleep, potentially causing pain in the jaw.', NULL, 'Trong câu vừa nghe, từ “clench” mang nghĩa nào sau đây?', '["người nhận; bên tiếp nhận","siết chặt; mím chặt","tấm ván dày","ngầm; ẩn ý; không nói ra"]'::jsonb, 1, '“clench” (/klentʃ/): siết chặt; mím chặt. Câu đầy đủ: People under prolonged stress may clench their teeth during sleep, potentially causing pain in the jaw.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
