INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_34_5', 'en-c1-34', 'I grew frantic when I couldn''t find my passport', 'Tôi phát hoảng lên khi không tìm thấy hộ chiếu của mình.', 'frantic /ˈfræntɪk/', '["passport","frantic","find","I","I","my","grew","when","couldn''t"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
