INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_34_10', 'en-c1-34', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “reproach” (/rɪˈproʊtʃ/) có nghĩa là gì?', '["sự thanh bình, yên ả, không có tiếng ồn, lo lắng hay quấy rầy","tính nhút nhát; sự thiếu tự tin","trách mắng; chỉ trích","sự thanh tịnh; sự bình yên; sự thanh thản"]'::jsonb, 2, '“reproach” (v.): trách mắng; chỉ trích; lời trách mắng; sự chỉ trích.', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
