INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_34_13', 'en-c1-34', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “intimidate” (/ɪnˈtɪmɪdeɪt/) có nghĩa là gì?', '["sự đau buồn; sự tang tóc; thời gian tang lễ","đe dọa; khủng bố tinh thần","sự kinh ngạc; sự thất vọng","sự thanh tịnh; sự bình yên; sự thanh thản"]'::jsonb, 1, '“intimidate” (v.): đe dọa; khủng bố tinh thần; làm cho sợ hãi; làm cho mất tự tin.', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_34_14', 'en-c1-34', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “Shock and disappointment caused by something unexpected and unpleasant.”', '["exasperate","tranquility","dismay","ordeal"]'::jsonb, 2, '“dismay” (/dɪsˈmeɪ/) nghĩa là: sự kinh ngạc; sự thất vọng.', 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
