INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_1', 'en-c1-34', NULL, 'comprehensive_test', 'listening', 'grudge', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mối hận thù; sự oán giận","luận văn; luận án","hải cảng; eo biển","sự chiết xuất; sự khai thác; sự nhổ (răng)"]'::jsonb, 0, 'grudge (/ɡrʌdʒ/) → mối hận thù; sự oán giận; miễn cưỡng cho; tiếc rẻ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_2', 'en-c1-34', NULL, 'comprehensive_test', 'listening', 'Arun clenched his fists as the cold wind blew.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi phát hoảng lên khi không tìm thấy hộ chiếu của mình.","Cái hộp gỗ có khóa ngay lập tức khơi gợi sự tò mò của tôi.","Arun siết chặt hai tay lại khi cơn gió lạnh thổi qua.","Những người hàng xóm đã mang những bữa ăn ấm áp đến cho gia đình đang có tang."]'::jsonb, 2, 'Arun clenched his fists as the cold wind blew. → Arun siết chặt hai tay lại khi cơn gió lạnh thổi qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_3', 'en-c1-34', NULL, 'comprehensive_test', 'listening', 'serenity', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc khẩu ngữ; dùng trong văn nói hàng ngày; không trang trọng","sự cộng hưởng (cảm xúc); sức gợi cảm; khả năng lay động","giáp ranh; liền kề; nối liền","sự thanh tịnh; sự bình yên; sự thanh thản"]'::jsonb, 3, 'serenity (/səˈrenəti/) → sự thanh tịnh; sự bình yên; sự thanh thản', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_4', 'en-c1-34', NULL, 'comprehensive_test', 'listening', 'His hateful remarks upset everyone sitting around the table.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Điều làm tôi thất vọng là chiếc bánh ngọt đã bị xẹp trong lò nướng.","Những lời cay nghiệt đầy ác ý của anh ấy làm phiền lòng tất cả mọi người ngồi quanh bàn.","Khán giả quá đông đã khiến cô ấy cảm thấy hơi rụt rè trước buổi biểu diễn đầu tiên.","Tôi phát hoảng lên khi không tìm thấy hộ chiếu của mình."]'::jsonb, 1, 'His hateful remarks upset everyone sitting around the table. → Những lời cay nghiệt đầy ác ý của anh ấy làm phiền lòng tất cả mọi người ngồi quanh bàn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_5', 'en-c1-34', NULL, 'comprehensive_test', 'listening', 'frantic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dễ tự ái; nhạy cảm","trao quyền tự chủ; làm cho có năng lực tự lập","quá lo lắng; hoảng loạn; không thể giữ được bình tĩnh","khoe khoang; phô trương"]'::jsonb, 2, 'frantic (/ˈfræntɪk/) → quá lo lắng; hoảng loạn; không thể giữ được bình tĩnh; được thực hiện rất nhanh với hoạt động cường độ cao, thường không kiểm soát', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_6', 'en-c1-34', NULL, 'comprehensive_test', 'listening', 'We used dry twigs to kindle a small fire.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy vẫn ôm hận chuyện cái bình hoa bị vỡ.","Chúng tôi dùng cành cây khô để nhóm một đống lửa nhỏ.","Arun siết chặt hai tay lại khi cơn gió lạnh thổi qua.","Những lời cay nghiệt đầy ác ý của anh ấy làm phiền lòng tất cả mọi người ngồi quanh bàn."]'::jsonb, 1, 'We used dry twigs to kindle a small fire. → Chúng tôi dùng cành cây khô để nhóm một đống lửa nhỏ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_7', 'en-c1-34', NULL, 'comprehensive_test', 'listening', 'regretfully', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dễ bị tổn thương; dễ bị ảnh hưởng tiêu cực","sự xúi giục; động lực khuyến khích","một cách đầy tiếc nuối, thể hiện sự buồn bã hoặc thất vọng về điều gì đó","gắng sức; lấy hết (can đảm, sức mạnh)"]'::jsonb, 2, 'regretfully (/rɪˈɡretfəli/) → một cách đầy tiếc nuối, thể hiện sự buồn bã hoặc thất vọng về điều gì đó', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_8', 'en-c1-34', NULL, 'comprehensive_test', 'listening', 'We enjoyed the tranquility of the garden at dawn.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Arun siết chặt hai tay lại khi cơn gió lạnh thổi qua.","Chúng tôi tận hưởng vẻ yên bình của khu vườn vào lúc bình minh.","Những nỗ lực bền bỉ của ông ấy cuối cùng đã khôi phục lại khu vườn cũ.","Tôi phát hoảng lên khi không tìm thấy hộ chiếu của mình."]'::jsonb, 1, 'We enjoyed the tranquility of the garden at dawn. → Chúng tôi tận hưởng vẻ yên bình của khu vườn vào lúc bình minh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_9', 'en-c1-34', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Extremely worried or frightened and unable to stay calm”?', '["grudge","clench","apprehension","frantic"]'::jsonb, 3, 'frantic (/ˈfræntɪk/) → quá lo lắng; hoảng loạn; không thể giữ được bình tĩnh', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_10', 'en-c1-34', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To start a fire or begin to burn.”?', '["kindle","mourning","evoke","serenity"]'::jsonb, 0, 'kindle (/ˈkɪndl/) → nhen nhóm ngọn lửa hoặc bắt đầu cháy', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_11', 'en-c1-34', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “In a way that expresses sadness or disappointment about something.”?', '["evoke","regretfully","arouse","ordeal"]'::jsonb, 1, 'regretfully (/rɪˈɡretfəli/) → một cách đầy tiếc nuối, thể hiện sự buồn bã hoặc thất vọng về điều gì đó', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_12', 'en-c1-34', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a peaceful state without noise, worry, or disturbance”?', '["tranquility","evoke","kindle","reproach"]'::jsonb, 0, 'tranquility (/træŋˈkwɪləti/) → sự thanh bình, yên ả, không có tiếng ồn, lo lắng hay quấy rầy', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_13', 'en-c1-34', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “sadness expressed after someone''s death”?', '["dogged","tranquility","hateful","mourning"]'::jsonb, 3, 'mourning (/ˈmɔːrnɪŋ/) → sự đau buồn; sự tang tóc; thời gian tang lễ', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
