INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_17', 'en-c1-34', NULL, 'comprehensive_test', 'fill_blank', NULL, NULL, 'Điền từ thích hợp vào chỗ trống:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_18', 'en-c1-34', NULL, 'comprehensive_test', 'reading', NULL, 'Unresolved workplace conflicts can lead employees to hold grudges, reducing cooperation and damaging team morale.', 'Dựa vào câu trên, từ “grudge” có nghĩa phù hợp nhất là gì?', '["sự trì trệ; tính ì; thiếu động lực","mối hận thù; sự oán giận","nghiêm khắc; khắt khe; cứng rắn","cuốn; xoáy tròn; làm xoáy"]'::jsonb, 1, 'grudge: mối hận thù; sự oán giận; miễn cưỡng cho; tiếc rẻ. Dịch cả câu: Những mâu thuẫn chốn công sở chưa được giải quyết có thể khiến nhân viên nuôi lòng oán giận, làm giảm sự hợp tác và tổn hại tinh thần đồng đội.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_19', 'en-c1-34', NULL, 'comprehensive_test', 'reading', NULL, 'People under prolonged stress may clench their teeth during sleep, potentially causing pain in the jaw.', 'Dựa vào câu trên, từ “clench” có nghĩa phù hợp nhất là gì?', '["hợp tác; cộng tác","cửa sông; cửa sông đổ ra biển","bản chất; cốt lõi; tinh hoa","siết chặt; mím chặt"]'::jsonb, 3, 'clench: siết chặt; mím chặt. Dịch cả câu: Những người chịu áp lực kéo dài có thể nghiến chặt răng khi ngủ, có thể gây ra đau ở phần hàm.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_20', 'en-c1-34', NULL, 'comprehensive_test', 'reading', NULL, 'Access to quiet green spaces can offer urban residents a sense of serenity amid daily pressures.', 'Dựa vào câu trên, từ “serenity” có nghĩa phù hợp nhất là gì?', '["sự thanh tịnh; sự bình yên; sự thanh thản","xứ đạo; giáo xứ","thuộc về lợi nhuận cuối cùng; liên quan đến kết quả tài chính cốt lõi","sự đánh giá lại; sự xem xét lại"]'::jsonb, 0, 'serenity: sự thanh tịnh; sự bình yên; sự thanh thản. Dịch cả câu: Việc tiếp cận các không gian xanh yên tĩnh có thể mang lại cho cư dân đô thị cảm giác thanh thản giữa những áp lực thường ngày.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_21', 'en-c1-34', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should address hateful behaviour early to ensure that all students feel safe and respected.', 'Dựa vào câu trên, từ “hateful” có nghĩa phù hợp nhất là gì?', '["đầy thù hận; ác ý","sự sơ suất; sự sai sót do sơ suất","phát huỳnh quang; huỳnh quang","lũng đoạn; độc quyền"]'::jsonb, 0, 'hateful: đầy thù hận; ác ý; căm thù; đáng ghét; cực kỳ khó chịu. Dịch cả câu: Nhà trường nên xử lý sớm các hành vi đầy thù hận để đảm bảo rằng tất cả học sinh đều cảm thấy an toàn và được tôn trọng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_22', 'en-c1-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bền bỉ; kiên cường; kiên trì không lùi bước”', '["embroider","practitioner","dogged","heartfelt"]'::jsonb, 2, 'bền bỉ; kiên cường; kiên trì không lùi bước → dogged (/ˈdɔːɡɪd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_23', 'en-c1-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khơi dậy; gây ra; kích thích”', '["deceased","potent","arouse","repertoire"]'::jsonb, 2, 'khơi dậy; gây ra; kích thích → arouse (/əˈraʊz/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_34_24', 'en-c1-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “niềm hoài niệm, sự nhớ tiếc quá khứ”', '["variant","cocaine","nostalgia","merciful"]'::jsonb, 2, 'niềm hoài niệm, sự nhớ tiếc quá khứ → nostalgia (/nɑːˈstældʒə/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-35', 'en', 'Bài 35: Cảm xúc & Tính cách (4) - CEFR C1', 'CEFR C1', 'C1 · Cảm xúc', '22 từ vựng Tiếng Anh CEFR C1 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5035, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bitterness', 'en-c1-35', 'bitterness', '/ˈbɪtərnəs/', 'C1', 'sự cay đắng; nỗi căm hờn; sự ấm ức; vị đắng (như cà phê không đường)', 'n.', 'bitter (adj.), bitterly (adv.)', 'Đồng nghĩa: resentment', 'Thường là danh từ không đếm được; vừa chỉ vị giác cay đắng, vừa chỉ sự oán giận trong lòng.', 'She still feels bitterness about losing her job unfairly.', NULL, 'Cô ấy vẫn cảm thấy ấm ức vì bị sa thải một cách bất công.', '{"wordId":"bitterness","ukIpa":"/ˈbɪtənəs/","usIpa":"/ˈbɪtərnəs/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"Anger and resentment caused by unfair treatment or disappointment.","vi":"sự cay đắng; nỗi căm hờn; sự ấm ức"},{"pos":"n.","en":"A sharp, unpleasant taste like unsweetened coffee.","vi":"vị đắng (như cà phê không đường)"}],"examples":[{"en":"She still feels bitterness about losing her job unfairly.","vi":"Cô ấy vẫn cảm thấy ấm ức vì bị sa thải một cách bất công.","audioKind":"ex"},{"en":"Perceived unfairness in promotion decisions can create lasting bitterness among employees and weaken cooperation within organisations.","vi":"Cảm giác bất công trong các quyết định thăng chức có thể tạo ra sự oán giận kéo dài giữa các nhân viên và làm suy yếu sự hợp tác trong nội bộ tổ chức.","audioKind":"ex2"}],"collocations":[{"en":"feel bitterness","vi":"cảm thấy căm hờn"},{"en":"lasting bitterness","vi":"nỗi hận thù kéo dài"},{"en":"the bitterness of coffee","vi":"vị đắng của cà phê"}],"wordFamily":["bitter (adj.)","bitterly (adv.)"],"synonyms":["resentment"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; vừa chỉ vị giác cay đắng, vừa chỉ sự oán giận trong lòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meek', 'en-c1-35', 'meek', '/miːk/', 'C1', 'hiền lành; rụt rè; dễ sai bảo; nhẫn nhục', 'adj.', 'meekly (adv.), meekness (n.)', 'Đồng nghĩa: submissive, timid · Trái nghĩa: assertive, defiant', 'Thường hàm ý không dám phản kháng, không đồng nghĩa với từ mang nghĩa tích cực là humble.', 'He gave a meek nod and stepped aside.', NULL, 'Cậu ấy gật đầu ngoan ngoãn rồi bước sang một bên.', '{"wordId":"meek","ukIpa":"/miːk/","usIpa":"/miːk/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Quiet and unwilling to argue or resist others.","vi":"hiền lành; rụt rè; dễ sai bảo; nhẫn nhục"}],"examples":[{"en":"He gave a meek nod and stepped aside.","vi":"Cậu ấy gật đầu ngoan ngoãn rồi bước sang một bên.","audioKind":"ex"},{"en":"Students who seem meek in class may express strong opinions when given a supportive discussion environment.","vi":"Những học sinh có vẻ rụt rè trên lớp có thể đưa ra những ý kiến mạnh mẽ khi được đặt trong môi trường thảo luận mang tính hỗ trợ.","audioKind":"ex2"}],"collocations":[{"en":"meek voice","vi":"giọng nói rụt rè"},{"en":"meek acceptance","vi":"sự chấp nhận nhẫn nhục"},{"en":"meek and mild","vi":"hiền lành và ôn hòa"}],"wordFamily":["meekly (adv.)","meekness (n.)"],"synonyms":["submissive","timid"],"antonyms":["assertive","defiant"],"tipVi":"Thường hàm ý không dám phản kháng, không đồng nghĩa với từ mang nghĩa tích cực là humble.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wretched', 'en-c1-35', 'wretched', '/ˈretʃɪd/', 'C1', 'khổ sở; khốn khổ; bất hạnh; tệ hại; tồi tàn; kém chất lượng', 'adj.', 'wretchedly (adv.), wretchedness (n.)', 'Đồng nghĩa: miserable, pitiful · Trái nghĩa: happy', 'Âm w ở đầu không phát âm; âm đuôi -ed ở đây được đọc là /ɪd/.', 'I felt wretched after spending the night coughing.', NULL, 'Tôi cảm thấy vô cùng khó chịu sau một đêm ho sù sụ.', '{"wordId":"wretched","ukIpa":"/ˈretʃɪd/","usIpa":"/ˈretʃɪd/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Very unhappy, uncomfortable, or unfortunate.","vi":"khổ sở; khốn khổ; bất hạnh"},{"pos":"adj.","en":"Extremely bad in quality or condition.","vi":"tệ hại; tồi tàn; kém chất lượng"}],"examples":[{"en":"I felt wretched after spending the night coughing.","vi":"Tôi cảm thấy vô cùng khó chịu sau một đêm ho sù sụ.","audioKind":"ex"},{"en":"Families living in wretched housing conditions face greater risks of respiratory illness and other health problems.","vi":"Các gia đình sống trong điều kiện nhà ở tồi tàn phải đối mặt với nguy cơ mắc bệnh đường hô hấp và các vấn đề sức khỏe khác cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"feel wretched","vi":"cảm thấy khó chịu"},{"en":"wretched conditions","vi":"điều kiện tồi tàn"},{"en":"wretched existence","vi":"cuộc sống khốn khổ"}],"wordFamily":["wretchedly (adv.)","wretchedness (n.)"],"synonyms":["miserable","pitiful"],"antonyms":["happy"],"tipVi":"Âm w ở đầu không phát âm; âm đuôi -ed ở đây được đọc là /ɪd/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exasperation', 'en-c1-35', 'exasperation', '/ɪɡˌzæspəˈreɪʃən/', 'C1', 'sự bực bội; sự cáu giận; sự ngán ngẩm', 'n.', 'exasperate (v.), exasperated (adj.), exasperating (adj.)', 'Đồng nghĩa: frustration, irritation', 'Thể hiện sự khó chịu tột độ đến mức mất kiên nhẫn; không nhầm lẫn với việc gia tăng.', 'She sighed in exasperation when the printer jammed again.', NULL, 'Cô ấy thở dài đầy bực bội khi chiếc máy in lại bị kẹt giấy.', '{"wordId":"exasperation","ukIpa":"/ɪɡˌzɑːspəˈreɪʃən/","usIpa":"/ɪɡˌzæspəˈreɪʃən/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"strong annoyance caused by repeated problems or irritating behaviour","vi":"sự bực bội; sự cáu giận; sự ngán ngẩm"}],"examples":[{"en":"She sighed in exasperation when the printer jammed again.","vi":"Cô ấy thở dài đầy bực bội khi chiếc máy in lại bị kẹt giấy.","audioKind":"ex"},{"en":"Repeated delays in public transport can cause widespread exasperation and reduce confidence in local authorities.","vi":"Tình trạng phương tiện giao thông công cộng chậm trễ liên miên có thể gây ra sự bực bội lan rộng và làm giảm niềm tin vào chính quyền địa phương.","audioKind":"ex2"}],"collocations":[{"en":"in exasperation","vi":"trong cơn bực bội"},{"en":"a sigh of exasperation","vi":"tiếng thở dài ngao ngán"},{"en":"growing exasperation","vi":"sự tức giận ngày càng tăng"}],"wordFamily":["exasperate (v.)","exasperated (adj.)","exasperating (adj.)"],"synonyms":["frustration","irritation"],"antonyms":[],"tipVi":"Thể hiện sự khó chịu tột độ đến mức mất kiên nhẫn; không nhầm lẫn với việc gia tăng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_triumphant', 'en-c1-35', 'triumphant', '/traɪˈʌmfənt/', 'C1', 'chiến thắng; kiêu hãnh', 'adj.', 'triumph (n.), triumph (v.), triumphantly (adv.)', 'Đồng nghĩa: victorious · Trái nghĩa: defeated', 'Có thể dùng để chỉ việc đạt được chiến thắng, hoặc diễn tả vẻ mặt đắc thắng sau khi chiến thắng.', 'The triumphant captain lifted the trophy above her head.', NULL, 'Vị đội trưởng chiến thắng giơ cao chiếc cúp lên đầu.', '{"wordId":"triumphant","ukIpa":"/traɪˈʌmfənt/","usIpa":"/traɪˈʌmfənt/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"successful or showing great happiness after winning","vi":"chiến thắng; kiêu hãnh"}],"examples":[{"en":"The triumphant captain lifted the trophy above her head.","vi":"Vị đội trưởng chiến thắng giơ cao chiếc cúp lên đầu.","audioKind":"ex"},{"en":"After years of campaigning, residents were triumphant when the council agreed to protect their local woodland.","vi":"Sau nhiều năm vận động tranh cử, cư dân đã vô cùng phấn khởi khi hội đồng đồng ý bảo vệ khu rừng địa phương của họ.","audioKind":"ex2"}],"collocations":[{"en":"triumphant smile","vi":"nụ cười chiến thắng"},{"en":"triumphant return","vi":"chuyến khải hoàn"},{"en":"triumphant victory","vi":"chiến thắng vẻ vang"}],"wordFamily":["triumph (n.)","triumph (v.)","triumphantly (adv.)"],"synonyms":["victorious"],"antonyms":["defeated"],"tipVi":"Có thể dùng để chỉ việc đạt được chiến thắng, hoặc diễn tả vẻ mặt đắc thắng sau khi chiến thắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lament', 'en-c1-35', 'lament', '/ləˈment/', 'C1', 'than van; tiếc nuối; thương tiếc; lời than khóc; bài ca ai oán', 'v.', 'lamentation (n.), lamentable (adj.), lamentably (adv.)', 'Đồng nghĩa: mourn, bemoan', 'Mang văn phong trang trọng hơn; động từ có thể đi trực tiếp với tân ngữ hoặc mệnh đề that.', 'My grandparents often lament the loss of local shops.', NULL, 'Ông bà tôi thường than thở về việc các cửa hàng nhỏ ở địa phương dần biến mất.', '{"wordId":"lament","ukIpa":"/ləˈment/","usIpa":"/ləˈment/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To express sadness or regret about something.","vi":"than van; tiếc nuối; thương tiếc"},{"pos":"n.","en":"An expression of grief, sometimes through a song or poem.","vi":"lời than khóc; bài ca ai oán"}],"examples":[{"en":"My grandparents often lament the loss of local shops.","vi":"Ông bà tôi thường than thở về việc các cửa hàng nhỏ ở địa phương dần biến mất.","audioKind":"ex"},{"en":"Many residents lament the destruction of historic buildings, arguing that redevelopment weakens the city''s cultural identity.","vi":"Nhiều cư dân bày tỏ sự tiếc nuối trước việc các tòa án lịch sử bị phá bỏ, cho rằng việc tái phát triển làm suy giảm bản sắc văn hóa của thành phố.","audioKind":"ex2"}],"collocations":[{"en":"lament the loss of","vi":"tiếc nuối sự mất mát của"},{"en":"deeply lament","vi":"vô cùng tiếc nuối"},{"en":"a lament for","vi":"lời ai oán cho"}],"wordFamily":["lamentation (n.)","lamentable (adj.)","lamentably (adv.)"],"synonyms":["mourn","bemoan"],"antonyms":[],"tipVi":"Mang văn phong trang trọng hơn; động từ có thể đi trực tiếp với tân ngữ hoặc mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enchant', 'en-c1-35', 'enchant', '/ɪnˈtʃænt/', 'C1', 'làm say đắm; làm mê hoặc; bỏ bùa; yểm bùa', 'v.', 'enchantment (n.), enchanting (adj.), enchanted (adj.)', 'Đồng nghĩa: captivate, delight', 'Thường dùng cấu trúc bị động be enchanted by, chỉ sự thu hút sâu sắc.', 'The tiny garden enchanted us with its colourful butterflies.', NULL, 'Khu vườn nhỏ với những chú bướm rực rỡ sắc màu đã làm chúng tôi mê mẩn.', '{"wordId":"enchant","ukIpa":"/ɪnˈtʃɑːnt/","usIpa":"/ɪnˈtʃænt/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To delight someone greatly and hold their attention.","vi":"làm say đắm; làm mê hoặc"},{"pos":"v.","en":"To put someone or something under a magic spell.","vi":"bỏ bùa; yểm bùa"}],"examples":[{"en":"The tiny garden enchanted us with its colourful butterflies.","vi":"Khu vườn nhỏ với những chú bướm rực rỡ sắc màu đã làm chúng tôi mê mẩn.","audioKind":"ex"},{"en":"Traditional storytelling can enchant young audiences while introducing them to the cultural heritage of their communities.","vi":"Nghệ thuật kể chuyện truyền thống vừa có thể thu hút khán giả trẻ vừa giúp họ tiếp cận di sản văn hóa của cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"enchant an audience","vi":"làm say đắm khán giả"},{"en":"be enchanted by","vi":"bị mê hoặc bởi"}],"wordFamily":["enchantment (n.)","enchanting (adj.)","enchanted (adj.)"],"synonyms":["captivate","delight"],"antonyms":[],"tipVi":"Thường dùng cấu trúc bị động be enchanted by, chỉ sự thu hút sâu sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consolation', 'en-c1-35', 'consolation', '/ˌkɑːnsəˈleɪʃən/', 'C1', 'sự an ủi; niềm khuây khỏa; người an ủi; vật an ủi', 'n.', 'console (v.), consoling (adj.), inconsolable (adj.)', 'Đồng nghĩa: comfort, solace', 'Sự an ủi mang nghĩa trừu tượng là không đếm được; trường hợp chỉ sự việc cụ thể mang lại sự an ủi thì dùng a consolation.', 'After losing the match, she found consolation in music.', NULL, 'Sau khi thua trận đấu, cô ấy tìm thấy niềm khuây khỏa trong âm nhạc.', '{"wordId":"consolation","ukIpa":"/ˌkɒnsəˈleɪʃən/","usIpa":"/ˌkɑːnsəˈleɪʃən/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"comfort received when you feel sad or disappointed","vi":"sự an ủi; niềm khuây khỏa"},{"pos":"n.","en":"someone or something that makes disappointment easier to bear","vi":"người an ủi; vật an ủi"}],"examples":[{"en":"After losing the match, she found consolation in music.","vi":"Sau khi thua trận đấu, cô ấy tìm thấy niềm khuây khỏa trong âm nhạc.","audioKind":"ex"},{"en":"For workers facing unemployment, emotional support offers some consolation, but practical assistance remains essential for long-term recovery.","vi":"Đối với những người lao động đối mặt với tình trạng thất nghiệp, hỗ trợ tinh thần mang lại chút an ủi, nhưng sự hỗ trợ thiết thực vẫn là điều thiết yếu để phục hồi lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"find consolation in","vi":"tìm thấy sự an ủi trong"},{"en":"a consolation prize","vi":"giải khuyến khích"},{"en":"little consolation","vi":"chút ít an ủi"},{"en":"some consolation","vi":"vài niềm khuây khỏa"}],"wordFamily":["console (v.)","consoling (adj.)","inconsolable (adj.)"],"synonyms":["comfort","solace"],"antonyms":[],"tipVi":"Sự an ủi mang nghĩa trừu tượng là không đếm được; trường hợp chỉ sự việc cụ thể mang lại sự an ủi thì dùng a consolation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stirring', 'en-c1-35', 'stirring', '/ˈstɝːɪŋ/', 'C1', 'hào hứng; sôi nổi; kích thích; sự nhen nhóm; sự khởi đầu', 'adj.', 'stir (v.), stirred (adj.)', 'Đồng nghĩa: rousing, inspiring · Trái nghĩa: uninspiring', 'Danh từ chỉ sự nhen nhóm thường dùng ở dạng số nhiều, như stirrings of hope.', 'The orchestra ended the concert with a stirring march.', NULL, 'Dàn nhạc khép lại buổi hòa nhạc bằng một khúc quân hành vô cùng hào hứng.', '{"wordId":"stirring","ukIpa":"/ˈstɜːrɪŋ/","usIpa":"/ˈstɝːɪŋ/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Causing strong feelings, especially excitement, courage, or admiration.","vi":"hào hứng; sôi nổi; kích thích"},{"pos":"n.","en":"An early sign of a feeling, idea, or activity.","vi":"sự nhen nhóm; sự khởi đầu"}],"examples":[{"en":"The orchestra ended the concert with a stirring march.","vi":"Dàn nhạc khép lại buổi hòa nhạc bằng một khúc quân hành vô cùng hào hứng.","audioKind":"ex"},{"en":"A stirring speech can inspire community action, but lasting change also requires practical support and adequate funding.","vi":"Một bài phát biểu đầy cảm hứng có thể thúc đẩy hành động cộng đồng, nhưng sự thay đổi lâu dài cũng đòi hỏi sự hỗ trợ thiết thực và nguồn vốn đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"a stirring speech","vi":"một bài phát biểu truyền cảm hứng"},{"en":"a stirring performance","vi":"một màn trình diễn đầy cảm xúc"},{"en":"the first stirrings of hope","vi":"những tia hy vọng đầu tiên"}],"wordFamily":["stir (v.)","stirred (adj.)"],"synonyms":["rousing","inspiring"],"antonyms":["uninspiring"],"tipVi":"Danh từ chỉ sự nhen nhóm thường dùng ở dạng số nhiều, như stirrings of hope.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_console', 'en-c1-35', 'console', '/kənˈsoʊl/', 'C1', 'an ủi; vỗ về ai đó đang buồn bã hoặc thất vọng; bảng điều khiển thiết bị; máy chơi điện tử', 'v.', 'consolation (n.), consoling (adj.), inconsolable (adj.)', 'Đồng nghĩa: comfort, soothe', 'Động từ trọng âm ở âm tiết sau; danh từ trọng âm ở âm tiết trước.', 'Lena tried to console her brother after his team lost.', NULL, 'Lena đã cố gắng an ủi em trai sau khi đội bóng của cậu bé thua trận.', '{"wordId":"console","ukIpa":"/kənˈsəʊl/","usIpa":"/kənˈsoʊl/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To comfort someone who feels sad or disappointed.","vi":"an ủi; vỗ về ai đó đang buồn bã hoặc thất vọng"},{"pos":"n.","en":"A control unit for equipment, or a machine for video games.","vi":"bảng điều khiển thiết bị; máy chơi điện tử"}],"examples":[{"en":"Lena tried to console her brother after his team lost.","vi":"Lena đã cố gắng an ủi em trai sau khi đội bóng của cậu bé thua trận.","audioKind":"ex"},{"en":"Teachers should console disappointed students while helping them develop practical strategies for improving their academic performance.","vi":"Giáo viên nên an ủi những học sinh thất vọng đồng thời giúp các em vạch ra chiến lược thiết thực để cải thiện kết quả học tập.","audioKind":"ex2"}],"collocations":[{"en":"console someone","vi":"an ủi ai đó"},{"en":"console yourself with","vi":"tự an ủi bản thân với"},{"en":"games console","vi":"máy chơi game"},{"en":"control console","vi":"bảng điều khiển"}],"wordFamily":["consolation (n.)","consoling (adj.)","inconsolable (adj.)"],"synonyms":["comfort","soothe"],"antonyms":[],"tipVi":"Động từ trọng âm ở âm tiết sau; danh từ trọng âm ở âm tiết trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gratify', 'en-c1-35', 'gratify', '/ˈɡrætɪfaɪ/', 'C1', 'làm hài lòng; làm thỏa mãn; thỏa mãn một ham muốn hoặc nhu cầu', 'v.', 'gratification (n.), gratifying (adj.), gratified (adj.)', 'Đồng nghĩa: please, satisfy · Trái nghĩa: displease, dissatisfy', 'Từ khá trang trọng; thường dùng be gratified by để diễn tả việc cảm thấy vui mừng, hài lòng vì điều gì.', 'Your kind words will gratify everyone who helped today.', NULL, 'Những lời tốt đẹp của bạn sẽ làm cho tất cả những ai đã giúp đỡ hôm nay cảm thấy ấm lòng.', '{"wordId":"gratify","ukIpa":"/ˈɡrætɪfaɪ/","usIpa":"/ˈɡrætɪfaɪ/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"to give someone pleasure or satisfaction","vi":"làm hài lòng; làm thỏa mãn"},{"pos":"v.","en":"to satisfy a desire or need","vi":"thỏa mãn một ham muốn hoặc nhu cầu"}],"examples":[{"en":"Your kind words will gratify everyone who helped today.","vi":"Những lời tốt đẹp của bạn sẽ làm cho tất cả những ai đã giúp đỡ hôm nay cảm thấy ấm lòng.","audioKind":"ex"},{"en":"Policies that gratify immediate consumer desires may conflict with the need to protect resources for future generations.","vi":"Các chính sách làm thỏa mãn nhu cầu trước mắt của người tiêu dùng có thể mâu thuẫn với yêu cầu bảo vệ tài nguyên cho các thế hệ tương lai.","audioKind":"ex2"}],"collocations":[{"en":"gratify a desire","vi":"thỏa mãn một mong muốn"},{"en":"gratify curiosity","vi":"thỏa mãn sự tò mò"},{"en":"be gratified by","vi":"cảm thấy hài lòng bởi"}],"wordFamily":["gratification (n.)","gratifying (adj.)","gratified (adj.)"],"synonyms":["please","satisfy"],"antonyms":["displease","dissatisfy"],"tipVi":"Từ khá trang trọng; thường dùng be gratified by để diễn tả việc cảm thấy vui mừng, hài lòng vì điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ambivalent', 'en-c1-35', 'ambivalent', '/æmˈbɪvələnt/', 'C1', 'mang cảm xúc trái chiều; mâu thuẫn; lưỡng lự', 'adj.', 'ambivalence (n.), ambivalently (adv.)', 'Đồng nghĩa: conflicted, undecided', 'Thường đi với giới từ about; chỉ trạng thái tồn tại cả cảm xúc tốt lẫn xấu cùng lúc, chứ không phải là sự thờ ơ, không quan tâm.', 'I feel ambivalent about moving away from my family.', NULL, 'Tôi cảm thấy rất mâu thuẫn và lưu luyến khi phải chuyển đi xa gia đình.', '{"wordId":"ambivalent","ukIpa":"/æmˈbɪvələnt/","usIpa":"/æmˈbɪvələnt/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"having conflicting feelings about someone or something","vi":"mang cảm xúc trái chiều; mâu thuẫn; lưỡng lự"}],"examples":[{"en":"I feel ambivalent about moving away from my family.","vi":"Tôi cảm thấy rất mâu thuẫn và lưu luyến khi phải chuyển đi xa gia đình.","audioKind":"ex"},{"en":"Many consumers remain ambivalent about online shopping because convenience must be balanced against concerns about privacy.","vi":"Nhiều người tiêu dùng vẫn tỏ ra lưỡng lự đối với việc mua sắm trực tuyến vì sự tiện lợi phải được cân nhắc cùng với những lo ngại về quyền riêng tư.","audioKind":"ex2"}],"collocations":[{"en":"feel ambivalent about","vi":"cảm thấy mâu thuẫn về"},{"en":"ambivalent attitude","vi":"thái độ lưỡng lự"},{"en":"remain ambivalent","vi":"vẫn giữ thái độ phân vân"}],"wordFamily":["ambivalence (n.)","ambivalently (adv.)"],"synonyms":["conflicted","undecided"],"antonyms":[],"tipVi":"Thường đi với giới từ about; chỉ trạng thái tồn tại cả cảm xúc tốt lẫn xấu cùng lúc, chứ không phải là sự thờ ơ, không quan tâm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heartfelt', 'en-c1-35', 'heartfelt', '/ˈhɑːrtfelt/', 'C1', 'thành tâm, chân thành, thật lòng', 'adj.', NULL, 'Đồng nghĩa: sincere, genuine, deep · Trái nghĩa: insincere', 'Thường bổ nghĩa cho các từ như thanks, apology, sympathy, nhấn mạnh cảm xúc xuất phát từ đáy lòng.', 'She gave her neighbour a heartfelt hug before leaving.', NULL, 'Cô ấy ôm người hàng xóm một cách chân thành trước khi rời đi.', '{"wordId":"heartfelt","ukIpa":"/ˈhɑːtfelt/","usIpa":"/ˈhɑːrtfelt/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Deeply and sincerely felt.","vi":"thành tâm, chân thành, thật lòng"}],"examples":[{"en":"She gave her neighbour a heartfelt hug before leaving.","vi":"Cô ấy ôm người hàng xóm một cách chân thành trước khi rời đi.","audioKind":"ex"},{"en":"A heartfelt apology can help restore public trust, but institutions must also demonstrate a genuine commitment to change.","vi":"Một lời xin lỗi chân thành có thể giúp khôi phục lòng tin của công chúng, nhưng các tổ chức cũng phải thể hiện cam kết thực sự đối với sự thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"heartfelt thanks","vi":"sự cảm ơn chân thành"},{"en":"a heartfelt apology","vi":"lời xin lỗi chân thành"},{"en":"heartfelt sympathy","vi":"sự đồng cảm sâu sắc"}],"wordFamily":[],"synonyms":["sincere","genuine","deep"],"antonyms":["insincere"],"tipVi":"Thường bổ nghĩa cho các từ như thanks, apology, sympathy, nhấn mạnh cảm xúc xuất phát từ đáy lòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_torment', 'en-c1-35', 'torment', '/ˈtɔːrment/', 'C1', 'nỗi đau đớn dữ dội; sự hành hạ, sự dằn vặt; làm cho đau đớn; hành hạ, quấy rầy', 'n.', 'tormentor (n.), tormented (adj.)', 'Đồng nghĩa: anguish, torture', 'Danh từ trọng âm ở âm tiết đầu; động từ trọng âm ở âm tiết thứ hai.', 'The constant itching was a torment all night.', NULL, 'Cảm giác ngứa ngáy liên tục đã hành hạ tôi suốt cả đêm.', '{"wordId":"torment","ukIpa":"/ˈtɔːment/","usIpa":"/ˈtɔːrment/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"severe physical pain or mental suffering","vi":"nỗi đau đớn dữ dội; sự hành hạ, sự dằn vặt"},{"pos":"v.","en":"to cause someone severe suffering or repeated distress","vi":"làm cho đau đớn; hành hạ, quấy rầy"}],"examples":[{"en":"The constant itching was a torment all night.","vi":"Cảm giác ngứa ngáy liên tục đã hành hạ tôi suốt cả đêm.","audioKind":"ex"},{"en":"Persistent uncertainty about employment can torment workers and undermine their mental health over time.","vi":"Sự bất định kéo dài về việc làm có thể làm dằn vặt người lao động và dần dần hủy hoại sức khỏe tâm thần của họ.","audioKind":"ex2"}],"collocations":[{"en":"mental torment","vi":"nỗi dằn vặt tinh thần"},{"en":"in torment","vi":"trong tình trạng đau khổ tột cùng"},{"en":"tormented by guilt","vi":"bị dằn vặt bởi sự tội lỗi"}],"wordFamily":["tormentor (n.)","tormented (adj.)"],"synonyms":["anguish","torture"],"antonyms":[],"tipVi":"Danh từ trọng âm ở âm tiết đầu; động từ trọng âm ở âm tiết thứ hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_zeal', 'en-c1-35', 'zeal', '/ziːl/', 'C1', 'lòng nhiệt huyết; sự hăng hái', 'n.', 'zealous (adj.), zealously (adv.)', 'Đồng nghĩa: enthusiasm, passion · Trái nghĩa: apathy', 'Danh từ không đếm được; thường dùng zeal for để chỉ lòng nhiệt huyết đối với việc gì.', 'She tackled the garden cleanup with remarkable zeal.', NULL, 'Cô ấy bắt tay vào dọn dẹp khu vườn với một sự hăng hái đáng kinh ngạc.', '{"wordId":"zeal","ukIpa":"/ziːl/","usIpa":"/ziːl/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"great energy and enthusiasm for an activity or cause","vi":"lòng nhiệt huyết; sự hăng hái"}],"examples":[{"en":"She tackled the garden cleanup with remarkable zeal.","vi":"Cô ấy bắt tay vào dọn dẹp khu vườn với một sự hăng hái đáng kinh ngạc.","audioKind":"ex"},{"en":"Volunteers'' zeal can strengthen community projects, but sustained progress also requires reliable funding and professional support.","vi":"Lòng nhiệt huyết của các tình nguyện viên có thể củng cố các dự án cộng đồng, nhưng sự phát triển bền vững cũng đòi hỏi nguồn tài trợ ổn định và sự hỗ trợ chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"zeal for learning","vi":"niềm đam mê học tập"},{"en":"with great zeal","vi":"với tất cả nhiệt huyết"},{"en":"missionary zeal","vi":"lòng nhiệt thành như nhà truyền giáo"}],"wordFamily":["zealous (adj.)","zealously (adv.)"],"synonyms":["enthusiasm","passion"],"antonyms":["apathy"],"tipVi":"Danh từ không đếm được; thường dùng zeal for để chỉ lòng nhiệt huyết đối với việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_radiant', 'en-c1-35', 'radiant', '/ˈreɪdiənt/', 'C1', 'rạng rỡ; dung mạo ngời ngời hạnh phúc; chiếu sáng rực rỡ; tỏa sáng; thuộc bức xạ; truyền qua dạng sóng (như nhiệt hoặc ánh sáng)', 'adj.', 'radiance (n.), radiantly (adv.), radiate (v.), radiation (n.)', 'Đồng nghĩa: beaming, glowing', 'Dùng cho người thường mang ý nghĩa hạnh phúc, rạng ngời; radiant heat chỉ nhiệt bức xạ.', 'She looked radiant as she held her newborn baby.', NULL, 'Cô ấy trông thật rạng rỡ khi ôm đứa con mới sinh trên tay.', '{"wordId":"radiant","ukIpa":"/ˈreɪdiənt/","usIpa":"/ˈreɪdiənt/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"Showing great happiness through your face or appearance.","vi":"rạng rỡ; dung mạo ngời ngời hạnh phúc"},{"pos":"adj.","en":"Shining brightly with light.","vi":"chiếu sáng rực rỡ; tỏa sáng"},{"pos":"adj.","en":"Transmitted as waves, especially heat or light.","vi":"thuộc bức xạ; truyền qua dạng sóng (như nhiệt hoặc ánh sáng)"}],"examples":[{"en":"She looked radiant as she held her newborn baby.","vi":"Cô ấy trông thật rạng rỡ khi ôm đứa con mới sinh trên tay.","audioKind":"ex"},{"en":"Buildings can use radiant heating systems to maintain comfortable indoor temperatures during the winter months.","vi":"Các tòa nhà có thể sử dụng hệ thống sưởi bức xạ để duy trì nhiệt độ trong nhà thoải mái trong những tháng mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"a radiant smile","vi":"nụ cười rạng rỡ"},{"en":"radiant heat","vi":"nhiệt bức xạ"},{"en":"radiant energy","vi":"năng lượng bức xạ"}],"wordFamily":["radiance (n.)","radiantly (adv.)","radiate (v.)","radiation (n.)"],"synonyms":["beaming","glowing"],"antonyms":[],"tipVi":"Dùng cho người thường mang ý nghĩa hạnh phúc, rạng ngời; radiant heat chỉ nhiệt bức xạ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contempt', 'en-c1-35', 'contempt', '/kənˈtempt/', 'C1', 'sự khinh miệt; sự coi thường; tội khinh nhờn tòa án; hành vi coi thường pháp luật', 'n.', 'contemptuous (adj.), contemptuously (adv.), contemptible (adj.)', 'Đồng nghĩa: scorn, disdain · Trái nghĩa: respect, admiration', '"contempt for" chỉ sự khinh miệt ai đó hoặc điều gì đó; thường là danh từ không đếm được.', 'He showed contempt for my suggestion by laughing.', NULL, 'Anh ta tỏ thái độ khinh miệt đối với đề xuất của tôi bằng cách cười nhạo.', '{"wordId":"contempt","ukIpa":"/kənˈtempt/","usIpa":"/kənˈtempt/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"A strong feeling that someone or something deserves no respect","vi":"sự khinh miệt; sự coi thường"},{"pos":"n.","en":"Behaviour that disobeys a court or disrespects its authority","vi":"tội khinh nhờn tòa án; hành vi coi thường pháp luật"}],"examples":[{"en":"He showed contempt for my suggestion by laughing.","vi":"Anh ta tỏ thái độ khinh miệt đối với đề xuất của tôi bằng cách cười nhạo.","audioKind":"ex"},{"en":"When officials treat public concerns with contempt, trust in democratic institutions can decline significantly.","vi":"Khi các quan chức coi thường mối quan tâm của công chúng, niềm tin vào các thể chế dân chủ có thể suy giảm đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"contempt for","vi":"sự khinh miệt đối với"},{"en":"treat someone with contempt","vi":"đối xử với ai đó một cách khinh miệt"},{"en":"contempt of court","vi":"tội khinh nhờn tòa án"}],"wordFamily":["contemptuous (adj.)","contemptuously (adv.)","contemptible (adj.)"],"synonyms":["scorn","disdain"],"antonyms":["respect","admiration"],"tipVi":"\"contempt for\" chỉ sự khinh miệt ai đó hoặc điều gì đó; thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_irresistible', 'en-c1-35', 'irresistible', '/ˌɪrɪˈzɪstəbl/', 'C1', 'hấp dẫn không thể cưỡng lại; vô cùng quyến rũ; mãnh liệt không thể chống lại', 'adj.', 'resist (v.), resistance (n.), irresistibly (adv.)', 'Đồng nghĩa: compelling, alluring · Trái nghĩa: resistible', 'Thường dùng để mô tả sự quyến rũ, cám dỗ hoặc sự thôi thúc mạnh mẽ đến mức khó lòng từ chối.', 'The smell of freshly baked bread was irresistible.', NULL, 'Mùi thơm của chiếc bánh mì mới nướng thật khó mà cưỡng lại được.', '{"wordId":"irresistible","ukIpa":"/ˌɪrɪˈzɪstəbl/","usIpa":"/ˌɪrɪˈzɪstəbl/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"so attractive that you cannot refuse or avoid it","vi":"hấp dẫn không thể cưỡng lại; vô cùng quyến rũ"},{"pos":"adj.","en":"too strong or powerful to resist","vi":"mãnh liệt không thể chống lại"}],"examples":[{"en":"The smell of freshly baked bread was irresistible.","vi":"Mùi thơm của chiếc bánh mì mới nướng thật khó mà cưỡng lại được.","audioKind":"ex"},{"en":"Online retailers use personalised recommendations to make certain products seem irresistible to potential customers.","vi":"Các nhà bán lẻ trực tuyến sử dụng các đề xuất mang tính cá nhân hóa để khiến một số sản phẩm trở nên vô cùng hấp dẫn đối với khách hàng tiềm năng.","audioKind":"ex2"}],"collocations":[{"en":"irresistible temptation","vi":"sự cám dỗ không thể cưỡng lại"},{"en":"irresistible urge","vi":"thôi thúc không thể kìm nén"},{"en":"irresistible charm","vi":"sức hút khó cưỡng"}],"wordFamily":["resist (v.)","resistance (n.)","irresistibly (adv.)"],"synonyms":["compelling","alluring"],"antonyms":["resistible"],"tipVi":"Thường dùng để mô tả sự quyến rũ, cám dỗ hoặc sự thôi thúc mạnh mẽ đến mức khó lòng từ chối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_detest', 'en-c1-35', 'detest', '/dɪˈtest/', 'C1', 'cực kỳ căm ghét; vô cùng ghê tởm', 'v.', 'detestable (adj.), detestation (n.)', 'Đồng nghĩa: loathe, hate, abhor · Trái nghĩa: love, adore', 'Theo sau là danh từ hoặc danh động từ: detest doing, không dùng to do.', 'I detest waiting outside in the freezing rain.', NULL, 'Tôi vô cùng ghét việc phải đứng đợi ở ngoài trời trong cơn mưa lạnh cóng.', '{"wordId":"detest","ukIpa":"/dɪˈtest/","usIpa":"/dɪˈtest/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"to dislike someone or something very strongly","vi":"cực kỳ căm ghét; vô cùng ghê tởm"}],"examples":[{"en":"I detest waiting outside in the freezing rain.","vi":"Tôi vô cùng ghét việc phải đứng đợi ở ngoài trời trong cơn mưa lạnh cóng.","audioKind":"ex"},{"en":"Many commuters detest overcrowded trains, yet they have few affordable alternatives for travelling to work.","vi":"Nhiều người đi làm bằng phương tiện công cộng cực kỳ chán ghét những chuyến tàu đông đúc, nhưng họ lại có rất ít sự lựa chọn thay thế với chi phí phải chăng để đi làm.","audioKind":"ex2"}],"collocations":[{"en":"detest doing something","vi":"căm ghét làm việc gì"},{"en":"detest violence","vi":"căm ghét bạo lực"},{"en":"absolutely detest","vi":"cực kỳ căm ghét"}],"wordFamily":["detestable (adj.)","detestation (n.)"],"synonyms":["loathe","hate","abhor"],"antonyms":["love","adore"],"tipVi":"Theo sau là danh từ hoặc danh động từ: detest doing, không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_betrayal', 'en-c1-35', 'betrayal', '/bɪˈtreɪəl/', 'C1', 'sự phản bội; sự phụ bạc', 'n.', 'betray (v.), betrayer (n.)', 'Đồng nghĩa: disloyalty, treachery · Trái nghĩa: loyalty, faithfulness', 'Thường ám chỉ việc làm tổn hại lòng tin; không mang nghĩa thông thường của việc "vạch trần" hay "bị lộ".', 'Sharing my private diary felt like a terrible betrayal.', NULL, 'Việc đem cuốn nhật ký riêng tư của tôi chia sẻ với người khác giống như một sự phản bội tồi tệ.', '{"wordId":"betrayal","ukIpa":"/bɪˈtreɪəl/","usIpa":"/bɪˈtreɪəl/","cefr":"C1","topic":"emotion","senses":[{"pos":"n.","en":"An act that breaks someone''s trust or loyalty.","vi":"sự phản bội; sự phụ bạc"}],"examples":[{"en":"Sharing my private diary felt like a terrible betrayal.","vi":"Việc đem cuốn nhật ký riêng tư của tôi chia sẻ với người khác giống như một sự phản bội tồi tệ.","audioKind":"ex"},{"en":"Many voters regard broken election promises as a betrayal of the trust they place in political leaders.","vi":"Nhiều cử tri coi việc thất hứa trong chiến dịch tranh cử là sự phụ bạc lại lòng tin mà họ đã đặt vào các nhà lãnh đạo chính trị.","audioKind":"ex2"}],"collocations":[{"en":"a betrayal of trust","vi":"sự phụ bạc lòng tin"},{"en":"a sense of betrayal","vi":"cảm giác bị phản bội"},{"en":"an act of betrayal","vi":"hành vi phản bội"}],"wordFamily":["betray (v.)","betrayer (n.)"],"synonyms":["disloyalty","treachery"],"antonyms":["loyalty","faithfulness"],"tipVi":"Thường ám chỉ việc làm tổn hại lòng tin; không mang nghĩa thông thường của việc \"vạch trần\" hay \"bị lộ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grim', 'en-c1-35', 'grim', '/ɡrɪm/', 'C1', 'nghiêm trọng; ảm đạm; ít mang lại hy vọng; trầm ngâm; nghiêm nghị; kiên quyết; khó chịu; tồi tệ; ảm đạm u ám', 'adj.', 'grimly (adv.), grimness (n.)', 'Đồng nghĩa: bleak, gloomy · Trái nghĩa: hopeful, cheerful', 'Thường dùng để mô tả triển vọng, thực tế hoặc nét mặt, nhấn mạnh sự nặng nề, nghiêm trọng chứ không chỉ đơn thuần là sự khó chịu thông thường.', 'The flood left a grim scene outside our house.', NULL, 'Trận lũ lụt để lại một khung cảnh tiêu điều, ảm đạm bên ngoài ngôi nhà của chúng tôi.', '{"wordId":"grim","ukIpa":"/ɡrɪm/","usIpa":"/ɡrɪm/","cefr":"C1","topic":"emotion","senses":[{"pos":"adj.","en":"very serious and giving little reason for hope","vi":"nghiêm trọng; ảm đạm; ít mang lại hy vọng"},{"pos":"adj.","en":"looking very serious, worried, or determined","vi":"trầm ngâm; nghiêm nghị; kiên quyết"},{"pos":"adj.","en":"unpleasant, depressing, or uncomfortable","vi":"khó chịu; tồi tệ; ảm đạm u ám"}],"examples":[{"en":"The flood left a grim scene outside our house.","vi":"Trận lũ lụt để lại một khung cảnh tiêu điều, ảm đạm bên ngoài ngôi nhà của chúng tôi.","audioKind":"ex"},{"en":"Without urgent investment in water infrastructure, the outlook for communities facing prolonged drought remains grim.","vi":"Nếu không có sự đầu tư khẩn cấp vào cơ sở hạ tầng cấp nước, triển vọng đối với các cộng đồng đang đối mặt với hạn hán kéo dài vẫn vô cùng u ám.","audioKind":"ex2"}],"collocations":[{"en":"a grim outlook","vi":"triển vọng ảm đạm"},{"en":"a grim reality","vi":"thực tế phũ phàng"},{"en":"a grim expression","vi":"vẻ mặt lạnh lùng nghiêm nghị"},{"en":"a grim reminder","vi":"lời nhắc nhở đầy ám ảnh"}],"wordFamily":["grimly (adv.)","grimness (n.)"],"synonyms":["bleak","gloomy"],"antonyms":["hopeful","cheerful"],"tipVi":"Thường dùng để mô tả triển vọng, thực tế hoặc nét mặt, nhấn mạnh sự nặng nề, nghiêm trọng chứ không chỉ đơn thuần là sự khó chịu thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mourn', 'en-c1-35', 'mourn', '/mɔːrn/', 'C1', 'thương tiếc; đau buồn; tưởng nhớ', 'v.', 'mourning (n.), mourner (n.), mournful (adj.), mournfully (adv.)', 'Đồng nghĩa: grieve', 'Có thể trực tiếp kết hợp với người đã khuất hoặc sự mất mát, cũng có thể dùng với mourn for sb.', 'Neighbours gathered quietly to mourn their much-loved friend.', NULL, 'Những người hàng xóm lặng lẽ tụ tập để tưởng nhớ người bạn vô cùng yêu quý của họ.', '{"wordId":"mourn","ukIpa":"/mɔːn/","usIpa":"/mɔːrn/","cefr":"C1","topic":"emotion","senses":[{"pos":"v.","en":"To feel or express deep sadness after a death or loss.","vi":"thương tiếc; đau buồn; tưởng nhớ"}],"examples":[{"en":"Neighbours gathered quietly to mourn their much-loved friend.","vi":"Những người hàng xóm lặng lẽ tụ tập để tưởng nhớ người bạn vô cùng yêu quý của họ.","audioKind":"ex"},{"en":"Public memorials provide spaces where communities can mourn those they have lost and reflect on shared history.","vi":"Các đài tưởng niệm công cộng tạo không gian để cộng đồng có thể tưởng nhớ những người đã khuất và suy ngẫm về lịch sử chung.","audioKind":"ex2"}],"collocations":[{"en":"mourn someone''s death","vi":"thương tiếc sự ra đi của ai đó"},{"en":"mourn the loss of","vi":"đau buồn vì sự mất mát của"},{"en":"mourn for someone","vi":"tưởng nhớ ai đó"}],"wordFamily":["mourning (n.)","mourner (n.)","mournful (adj.)","mournfully (adv.)"],"synonyms":["grieve"],"antonyms":[],"tipVi":"Có thể trực tiếp kết hợp với người đã khuất hoặc sự mất mát, cũng có thể dùng với mourn for sb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_35_1', 'en-c1-35', 'Cách dùng “grim” (adj.) — nghiêm trọng; ảm đạm; ít mang lại hy vọng', 'a grim outlook  ·  a grim reality  ·  a grim expression', 'Thường dùng để mô tả triển vọng, thực tế hoặc nét mặt, nhấn mạnh sự nặng nề, nghiêm trọng chứ không chỉ đơn thuần là sự khó chịu thông thường.', 'Họ từ (Word Family): grimly (adv.), grimness (n.) | Đồng nghĩa: bleak, gloomy · Trái nghĩa: hopeful, cheerful', '[{"hanzi":"The flood left a grim scene outside our house.","pinyin":"","meaning":"Trận lũ lụt để lại một khung cảnh tiêu điều, ảm đạm bên ngoài ngôi nhà của chúng tôi."},{"hanzi":"Without urgent investment in water infrastructure, the outlook for communities facing prolonged drought remains grim.","pinyin":"","meaning":"Nếu không có sự đầu tư khẩn cấp vào cơ sở hạ tầng cấp nước, triển vọng đối với các cộng đồng đang đối mặt với hạn hán kéo dài vẫn vô cùng u ám."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_35_2', 'en-c1-35', 'Cách dùng “ambivalent” (adj.) — mang cảm xúc trái chiều; mâu thuẫn; lưỡng lự', 'feel ambivalent about  ·  ambivalent attitude  ·  remain ambivalent', 'Thường đi với giới từ about; chỉ trạng thái tồn tại cả cảm xúc tốt lẫn xấu cùng lúc, chứ không phải là sự thờ ơ, không quan tâm.', 'Họ từ (Word Family): ambivalence (n.), ambivalently (adv.) | Đồng nghĩa: conflicted, undecided', '[{"hanzi":"I feel ambivalent about moving away from my family.","pinyin":"","meaning":"Tôi cảm thấy rất mâu thuẫn và lưu luyến khi phải chuyển đi xa gia đình."},{"hanzi":"Many consumers remain ambivalent about online shopping because convenience must be balanced against concerns about privacy.","pinyin":"","meaning":"Nhiều người tiêu dùng vẫn tỏ ra lưỡng lự đối với việc mua sắm trực tuyến vì sự tiện lợi phải được cân nhắc cùng với những lo ngại về quyền riêng tư."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_35_3', 'en-c1-35', 'Cách dùng “consolation” (n.) — sự an ủi; niềm khuây khỏa', 'find consolation in  ·  a consolation prize  ·  little consolation', 'Sự an ủi mang nghĩa trừu tượng là không đếm được; trường hợp chỉ sự việc cụ thể mang lại sự an ủi thì dùng a consolation.', 'Họ từ (Word Family): console (v.), consoling (adj.), inconsolable (adj.) | Đồng nghĩa: comfort, solace', '[{"hanzi":"After losing the match, she found consolation in music.","pinyin":"","meaning":"Sau khi thua trận đấu, cô ấy tìm thấy niềm khuây khỏa trong âm nhạc."},{"hanzi":"For workers facing unemployment, emotional support offers some consolation, but practical assistance remains essential for long-term recovery.","pinyin":"","meaning":"Đối với những người lao động đối mặt với tình trạng thất nghiệp, hỗ trợ tinh thần mang lại chút an ủi, nhưng sự hỗ trợ thiết thực vẫn là điều thiết yếu để phục hồi lâu dài."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_35_4', 'en-c1-35', 'Cách dùng “betrayal” (n.) — sự phản bội; sự phụ bạc', 'a betrayal of trust  ·  a sense of betrayal  ·  an act of betrayal', 'Thường ám chỉ việc làm tổn hại lòng tin; không mang nghĩa thông thường của việc "vạch trần" hay "bị lộ".', 'Họ từ (Word Family): betray (v.), betrayer (n.) | Đồng nghĩa: disloyalty, treachery · Trái nghĩa: loyalty, faithfulness', '[{"hanzi":"Sharing my private diary felt like a terrible betrayal.","pinyin":"","meaning":"Việc đem cuốn nhật ký riêng tư của tôi chia sẻ với người khác giống như một sự phản bội tồi tệ."},{"hanzi":"Many voters regard broken election promises as a betrayal of the trust they place in political leaders.","pinyin":"","meaning":"Nhiều cử tri coi việc thất hứa trong chiến dịch tranh cử là sự phụ bạc lại lòng tin mà họ đã đặt vào các nhà lãnh đạo chính trị."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_35_1', 'en-c1-35', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_1_1', 'ten_c1_35_1', 'bitterness', 'She still feels bitterness about losing her job unfairly.', 'She still feels bitterness about losing her job unfairly.', '/ˈbɪtərnəs/', 'Cô ấy vẫn cảm thấy ấm ức vì bị sa thải một cách bất công.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_1_2', 'ten_c1_35_1', 'meek', 'He gave a meek nod and stepped aside.', 'He gave a meek nod and stepped aside.', '/miːk/', 'Cậu ấy gật đầu ngoan ngoãn rồi bước sang một bên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_1_3', 'ten_c1_35_1', 'wretched', 'I felt wretched after spending the night coughing.', 'I felt wretched after spending the night coughing.', '/ˈretʃɪd/', 'Tôi cảm thấy vô cùng khó chịu sau một đêm ho sù sụ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_1_4', 'ten_c1_35_1', 'exasperation', 'She sighed in exasperation when the printer jammed again.', 'She sighed in exasperation when the printer jammed again.', '/ɪɡˌzæspəˈreɪʃən/', 'Cô ấy thở dài đầy bực bội khi chiếc máy in lại bị kẹt giấy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_1_5', 'ten_c1_35_1', 'triumphant', 'The triumphant captain lifted the trophy above her head.', 'The triumphant captain lifted the trophy above her head.', '/traɪˈʌmfənt/', 'Vị đội trưởng chiến thắng giơ cao chiếc cúp lên đầu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_1_6', 'ten_c1_35_1', 'lament', 'My grandparents often lament the loss of local shops.', 'My grandparents often lament the loss of local shops.', '/ləˈment/', 'Ông bà tôi thường than thở về việc các cửa hàng nhỏ ở địa phương dần biến mất.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_1_7', 'ten_c1_35_1', 'enchant', 'The tiny garden enchanted us with its colourful butterflies.', 'The tiny garden enchanted us with its colourful butterflies.', '/ɪnˈtʃænt/', 'Khu vườn nhỏ với những chú bướm rực rỡ sắc màu đã làm chúng tôi mê mẩn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_1_8', 'ten_c1_35_1', 'consolation', 'After losing the match, she found consolation in music.', 'After losing the match, she found consolation in music.', '/ˌkɑːnsəˈleɪʃən/', 'Sau khi thua trận đấu, cô ấy tìm thấy niềm khuây khỏa trong âm nhạc.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_35_1_1', 'en-c1-35', 'ten_c1_35_1', 'listening', 'listening', 'She still feels bitterness about losing her job unfairly.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy vẫn cảm thấy ấm ức vì bị sa thải một cách bất công.","Cảm giác ngứa ngáy liên tục đã hành hạ tôi suốt cả đêm.","Cô ấy bắt tay vào dọn dẹp khu vườn với một sự hăng hái đáng kinh ngạc.","Dàn nhạc khép lại buổi hòa nhạc bằng một khúc quân hành vô cùng hào hứng."]'::jsonb, 0, 'She still feels bitterness about losing her job unfairly. → Cô ấy vẫn cảm thấy ấm ức vì bị sa thải một cách bất công.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_35_1_2', 'en-c1-35', 'ten_c1_35_1', 'listening', 'listening', 'He gave a meek nod and stepped aside.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những lời tốt đẹp của bạn sẽ làm cho tất cả những ai đã giúp đỡ hôm nay cảm thấy ấm lòng.","Cậu ấy gật đầu ngoan ngoãn rồi bước sang một bên.","Tôi vô cùng ghét việc phải đứng đợi ở ngoài trời trong cơn mưa lạnh cóng.","Ông bà tôi thường than thở về việc các cửa hàng nhỏ ở địa phương dần biến mất."]'::jsonb, 1, 'He gave a meek nod and stepped aside. → Cậu ấy gật đầu ngoan ngoãn rồi bước sang một bên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_35_1_3', 'en-c1-35', 'ten_c1_35_1', 'listening', 'listening', 'I felt wretched after spending the night coughing.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi cảm thấy vô cùng khó chịu sau một đêm ho sù sụ.","Cô ấy vẫn cảm thấy ấm ức vì bị sa thải một cách bất công.","Sau khi thua trận đấu, cô ấy tìm thấy niềm khuây khỏa trong âm nhạc.","Cảm giác ngứa ngáy liên tục đã hành hạ tôi suốt cả đêm."]'::jsonb, 0, 'I felt wretched after spending the night coughing. → Tôi cảm thấy vô cùng khó chịu sau một đêm ho sù sụ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_35_2', 'en-c1-35', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_2_1', 'ten_c1_35_2', 'bitterness', 'Perceived unfairness in promotion decisions can create lasting bitterness among employees and weaken cooperation within organisations.', 'Perceived unfairness in promotion decisions can create lasting bitterness among employees and weaken cooperation within organisations.', '/ˈbɪtərnəs/', 'Cảm giác bất công trong các quyết định thăng chức có thể tạo ra sự oán giận kéo dài giữa các nhân viên và làm suy yếu sự hợp tác trong nội bộ tổ chức.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_2_2', 'ten_c1_35_2', 'meek', 'Students who seem meek in class may express strong opinions when given a supportive discussion environment.', 'Students who seem meek in class may express strong opinions when given a supportive discussion environment.', '/miːk/', 'Những học sinh có vẻ rụt rè trên lớp có thể đưa ra những ý kiến mạnh mẽ khi được đặt trong môi trường thảo luận mang tính hỗ trợ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_2_3', 'ten_c1_35_2', 'wretched', 'Families living in wretched housing conditions face greater risks of respiratory illness and other health problems.', 'Families living in wretched housing conditions face greater risks of respiratory illness and other health problems.', '/ˈretʃɪd/', 'Các gia đình sống trong điều kiện nhà ở tồi tàn phải đối mặt với nguy cơ mắc bệnh đường hô hấp và các vấn đề sức khỏe khác cao hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_2_4', 'ten_c1_35_2', 'exasperation', 'Repeated delays in public transport can cause widespread exasperation and reduce confidence in local authorities.', 'Repeated delays in public transport can cause widespread exasperation and reduce confidence in local authorities.', '/ɪɡˌzæspəˈreɪʃən/', 'Tình trạng phương tiện giao thông công cộng chậm trễ liên miên có thể gây ra sự bực bội lan rộng và làm giảm niềm tin vào chính quyền địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_2_5', 'ten_c1_35_2', 'triumphant', 'After years of campaigning, residents were triumphant when the council agreed to protect their local woodland.', 'After years of campaigning, residents were triumphant when the council agreed to protect their local woodland.', '/traɪˈʌmfənt/', 'Sau nhiều năm vận động tranh cử, cư dân đã vô cùng phấn khởi khi hội đồng đồng ý bảo vệ khu rừng địa phương của họ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_35_2_6', 'ten_c1_35_2', 'lament', 'Many residents lament the destruction of historic buildings, arguing that redevelopment weakens the city''s cultural identity.', 'Many residents lament the destruction of historic buildings, arguing that redevelopment weakens the city''s cultural identity.', '/ləˈment/', 'Nhiều cư dân bày tỏ sự tiếc nuối trước việc các tòa án lịch sử bị phá bỏ, cho rằng việc tái phát triển làm suy giảm bản sắc văn hóa của thành phố.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_35_2_1', 'en-c1-35', 'ten_c1_35_2', 'listening', 'listening', 'Perceived unfairness in promotion decisions can create lasting bitterness among employees and weaken cooperation within organisations.', NULL, 'Trong câu vừa nghe, từ “bitterness” mang nghĩa nào sau đây?', '["cải tiến; trau chuốt; hoàn thiện","lò luyện; lò công nghiệp","sự cay đắng; nỗi căm hờn; sự ấm ức","khắc chữ; đề chữ"]'::jsonb, 2, '“bitterness” (/ˈbɪtərnəs/): sự cay đắng; nỗi căm hờn; sự ấm ức. Câu đầy đủ: Perceived unfairness in promotion decisions can create lasting bitterness among employees and weaken cooperation within organisations.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_35_2_2', 'en-c1-35', 'ten_c1_35_2', 'listening', 'listening', 'Students who seem meek in class may express strong opinions when given a supportive discussion environment.', NULL, 'Trong câu vừa nghe, từ “meek” mang nghĩa nào sau đây?', '["hiền lành; rụt rè; dễ sai bảo; nhẫn nhục","tinh thần chiến đấu; sĩ khí và sự nhiệt huyết của một tập thể","nhỏ; không đáng kể; không quan trọng","kẻ hà tiện; người keo kiệt"]'::jsonb, 0, '“meek” (/miːk/): hiền lành; rụt rè; dễ sai bảo; nhẫn nhục. Câu đầy đủ: Students who seem meek in class may express strong opinions when given a supportive discussion environment.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
