INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_35_3', 'en-c1-35', 'en_to_vi', 'The orchestra ended the concert with a stirring march.', 'The orchestra ended the concert with a stirring march.', '/ˈstɝːɪŋ/', NULL, 'Dàn nhạc khép lại buổi hòa nhạc bằng một khúc quân hành vô cùng hào hứng.', NULL, '["dàn","nhạc","khép","lại","buổi","hòa","nhạc","bằng"]'::jsonb, 'Từ trọng tâm: stirring (hào hứng; sôi nổi; kích thích)', 'The orchestra ended the concert with a stirring march. → Dàn nhạc khép lại buổi hòa nhạc bằng một khúc quân hành vô cùng hào hứng.', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_35_4', 'en-c1-35', 'en_to_vi', 'Lena tried to console her brother after his team lost.', 'Lena tried to console her brother after his team lost.', '/kənˈsoʊl/', NULL, 'Lena đã cố gắng an ủi em trai sau khi đội bóng của cậu bé thua trận.', NULL, '["lena","đã","cố","gắng","an","ủi","em","trai"]'::jsonb, 'Từ trọng tâm: console (an ủi; vỗ về ai đó đang buồn bã hoặc thất vọng)', 'Lena tried to console her brother after his team lost. → Lena đã cố gắng an ủi em trai sau khi đội bóng của cậu bé thua trận.', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
