INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_1', 'en-c1-35', NULL, 'comprehensive_test', 'listening', 'bitterness', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["kẻ chinh phục; nhà chinh phạt","sự cay đắng; nỗi căm hờn; sự ấm ức","chứng minh; củng cố bằng chứng; làm sáng tỏ","nhen nhóm ngọn lửa hoặc bắt đầu cháy"]'::jsonb, 1, 'bitterness (/ˈbɪtərnəs/) → sự cay đắng; nỗi căm hờn; sự ấm ức; vị đắng (như cà phê không đường)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_2', 'en-c1-35', NULL, 'comprehensive_test', 'listening', 'He gave a meek nod and stepped aside.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cảm thấy rất mâu thuẫn và lưu luyến khi phải chuyển đi xa gia đình.","Cậu ấy gật đầu ngoan ngoãn rồi bước sang một bên.","Mùi thơm của chiếc bánh mì mới nướng thật khó mà cưỡng lại được.","Sau khi thua trận đấu, cô ấy tìm thấy niềm khuây khỏa trong âm nhạc."]'::jsonb, 1, 'He gave a meek nod and stepped aside. → Cậu ấy gật đầu ngoan ngoãn rồi bước sang một bên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_3', 'en-c1-35', NULL, 'comprehensive_test', 'listening', 'wretched', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khoan dung; nhân từ; độ lượng","khổ sở; khốn khổ; bất hạnh","có hình chữ nhật (với các cạnh kề không bằng nhau)","liên quan đến; gắn liền với; áp dụng cho"]'::jsonb, 1, 'wretched (/ˈretʃɪd/) → khổ sở; khốn khổ; bất hạnh; tệ hại; tồi tàn; kém chất lượng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_4', 'en-c1-35', NULL, 'comprehensive_test', 'listening', 'She sighed in exasperation when the printer jammed again.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cảm thấy rất mâu thuẫn và lưu luyến khi phải chuyển đi xa gia đình.","Cô ấy thở dài đầy bực bội khi chiếc máy in lại bị kẹt giấy.","Mùi thơm của chiếc bánh mì mới nướng thật khó mà cưỡng lại được.","Khu vườn nhỏ với những chú bướm rực rỡ sắc màu đã làm chúng tôi mê mẩn."]'::jsonb, 1, 'She sighed in exasperation when the printer jammed again. → Cô ấy thở dài đầy bực bội khi chiếc máy in lại bị kẹt giấy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_5', 'en-c1-35', NULL, 'comprehensive_test', 'listening', 'triumphant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phân hủy; mục nát; thối rữa","tính đều đặn; tính quy luật; sự định kỳ","chiến thắng; kiêu hãnh","gây ra; khơi mào; kích thích"]'::jsonb, 2, 'triumphant (/traɪˈʌmfənt/) → chiến thắng; kiêu hãnh', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_6', 'en-c1-35', NULL, 'comprehensive_test', 'listening', 'My grandparents often lament the loss of local shops.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông bà tôi thường than thở về việc các cửa hàng nhỏ ở địa phương dần biến mất.","Vị đội trưởng chiến thắng giơ cao chiếc cúp lên đầu.","Anh ta tỏ thái độ khinh miệt đối với đề xuất của tôi bằng cách cười nhạo.","Mùi thơm của chiếc bánh mì mới nướng thật khó mà cưỡng lại được."]'::jsonb, 0, 'My grandparents often lament the loss of local shops. → Ông bà tôi thường than thở về việc các cửa hàng nhỏ ở địa phương dần biến mất.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_7', 'en-c1-35', NULL, 'comprehensive_test', 'listening', 'enchant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chứng nhận; cấp giấy chứng nhận; xác nhận chính thức","chất cô-cain; thuốc phiện cô-cain","bất lợi; gây khó khăn","làm say đắm; làm mê hoặc"]'::jsonb, 3, 'enchant (/ɪnˈtʃænt/) → làm say đắm; làm mê hoặc; bỏ bùa; yểm bùa', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_8', 'en-c1-35', NULL, 'comprehensive_test', 'listening', 'After losing the match, she found consolation in music.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cảm giác ngứa ngáy liên tục đã hành hạ tôi suốt cả đêm.","Sau khi thua trận đấu, cô ấy tìm thấy niềm khuây khỏa trong âm nhạc.","Mùi thơm của chiếc bánh mì mới nướng thật khó mà cưỡng lại được.","Trận lũ lụt để lại một khung cảnh tiêu điều, ảm đạm bên ngoài ngôi nhà của chúng tôi."]'::jsonb, 1, 'After losing the match, she found consolation in music. → Sau khi thua trận đấu, cô ấy tìm thấy niềm khuây khỏa trong âm nhạc.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_9', 'en-c1-35', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “successful or showing great happiness after winning”?', '["triumphant","torment","detest","betrayal"]'::jsonb, 0, 'triumphant (/traɪˈʌmfənt/) → chiến thắng; kiêu hãnh', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_10', 'en-c1-35', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To express sadness or regret about something.”?', '["mourn","gratify","irresistible","lament"]'::jsonb, 3, 'lament (/ləˈment/) → than van; tiếc nuối; thương tiếc', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_11', 'en-c1-35', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To delight someone greatly and hold their attention.”?', '["ambivalent","zeal","gratify","enchant"]'::jsonb, 3, 'enchant (/ɪnˈtʃænt/) → làm say đắm; làm mê hoặc', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_12', 'en-c1-35', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “comfort received when you feel sad or disappointed”?', '["contempt","radiant","consolation","irresistible"]'::jsonb, 2, 'consolation (/ˌkɑːnsəˈleɪʃən/) → sự an ủi; niềm khuây khỏa', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_13', 'en-c1-35', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Causing strong feelings, especially excitement, courage, or admiration.”?', '["ambivalent","gratify","meek","stirring"]'::jsonb, 3, 'stirring (/ˈstɝːɪŋ/) → hào hứng; sôi nổi; kích thích', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
