INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_18', 'en-c1-35', NULL, 'comprehensive_test', 'reading', NULL, 'Perceived unfairness in promotion decisions can create lasting bitterness among employees and weaken cooperation within organisations.', 'Dựa vào câu trên, từ “bitterness” có nghĩa phù hợp nhất là gì?', '["trụ cột gia đình; người kiếm tiền nuôi gia đình","ít ỏi; thiếu thốn","sự cay đắng; nỗi căm hờn; sự ấm ức","giao phó; phó thác"]'::jsonb, 2, 'bitterness: sự cay đắng; nỗi căm hờn; sự ấm ức; vị đắng (như cà phê không đường). Dịch cả câu: Cảm giác bất công trong các quyết định thăng chức có thể tạo ra sự oán giận kéo dài giữa các nhân viên và làm suy yếu sự hợp tác trong nội bộ tổ chức.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_19', 'en-c1-35', NULL, 'comprehensive_test', 'reading', NULL, 'Students who seem meek in class may express strong opinions when given a supportive discussion environment.', 'Dựa vào câu trên, từ “meek” có nghĩa phù hợp nhất là gì?', '["cứu hộ; trục vớt; thu hồi","thuộc về đế quốc; thuộc về hoàng gia","hiền lành; rụt rè; dễ sai bảo; nhẫn nhục","sự cung cấp; sự cấp phát"]'::jsonb, 2, 'meek: hiền lành; rụt rè; dễ sai bảo; nhẫn nhục. Dịch cả câu: Những học sinh có vẻ rụt rè trên lớp có thể đưa ra những ý kiến mạnh mẽ khi được đặt trong môi trường thảo luận mang tính hỗ trợ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_20', 'en-c1-35', NULL, 'comprehensive_test', 'reading', NULL, 'Families living in wretched housing conditions face greater risks of respiratory illness and other health problems.', 'Dựa vào câu trên, từ “wretched” có nghĩa phù hợp nhất là gì?', '["khổ sở; khốn khổ; bất hạnh","ngữ âm học","đứng yên; tĩnh tại; không di chuyển","truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng"]'::jsonb, 0, 'wretched: khổ sở; khốn khổ; bất hạnh; tệ hại; tồi tàn; kém chất lượng. Dịch cả câu: Các gia đình sống trong điều kiện nhà ở tồi tàn phải đối mặt với nguy cơ mắc bệnh đường hô hấp và các vấn đề sức khỏe khác cao hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_21', 'en-c1-35', NULL, 'comprehensive_test', 'reading', NULL, 'Repeated delays in public transport can cause widespread exasperation and reduce confidence in local authorities.', 'Dựa vào câu trên, từ “exasperation” có nghĩa phù hợp nhất là gì?', '["sự bực bội; sự cáu giận; sự ngán ngẩm","biến thể; biến chủng","thi hành; thực thi; bắt tuân theo","lỗi thời; cổ lỗ sĩ; cũ kỹ"]'::jsonb, 0, 'exasperation: sự bực bội; sự cáu giận; sự ngán ngẩm. Dịch cả câu: Tình trạng phương tiện giao thông công cộng chậm trễ liên miên có thể gây ra sự bực bội lan rộng và làm giảm niềm tin vào chính quyền địa phương.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_22', 'en-c1-35', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự phản bội; sự phụ bạc”', '["betrayal","diffuse","acclaim","migratory"]'::jsonb, 0, 'sự phản bội; sự phụ bạc → betrayal (/bɪˈtreɪəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_23', 'en-c1-35', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nghiêm trọng; ảm đạm; ít mang lại hy vọng”', '["predecessor","fallacy","exclusivity","grim"]'::jsonb, 3, 'nghiêm trọng; ảm đạm; ít mang lại hy vọng → grim (/ɡrɪm/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_35_24', 'en-c1-35', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thương tiếc; đau buồn; tưởng nhớ”', '["expenditure","mourn","pneumonia","facilitate"]'::jsonb, 1, 'thương tiếc; đau buồn; tưởng nhớ → mourn (/mɔːrn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-36', 'en', 'Bài 36: Công việc & Nghề nghiệp (1) - CEFR C1', 'CEFR C1', 'C1 · Công việc', '25 từ vựng Tiếng Anh CEFR C1 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5036, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concurrent', 'en-c1-36', 'concurrent', '/kənˈkɜːrənt/', 'C1', 'đồng thời; song song (xảy ra hoặc tồn tại cùng một lúc)', 'adj.', 'concurrently (adv.), concurrency (n.)', 'Đồng nghĩa: simultaneous · Trái nghĩa: sequential', 'Nhấn mạnh sự trùng lặp về thời gian; diễn đạt "đồng thời với" dùng concurrent with.', 'Two concurrent meetings meant I had to choose one.', NULL, 'Hai cuộc họp diễn ra đồng thời có nghĩa là tôi phải chọn một cái.', '{"wordId":"concurrent","ukIpa":"/kənˈkʌrənt/","usIpa":"/kənˈkɜːrənt/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Happening or existing at the same time","vi":"đồng thời; song song (xảy ra hoặc tồn tại cùng một lúc)"}],"examples":[{"en":"Two concurrent meetings meant I had to choose one.","vi":"Hai cuộc họp diễn ra đồng thời có nghĩa là tôi phải chọn một cái.","audioKind":"ex"},{"en":"Concurrent improvements in housing and public transport can make urban development more inclusive and sustainable.","vi":"Việc đồng thời cải thiện nhà ở và giao thông công cộng có thể làm cho sự phát triển đô thị mang tính bao trùm và bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"concurrent events","vi":"các sự kiện đồng thời"},{"en":"concurrent sessions","vi":"các phiên họp song song"},{"en":"concurrent with","vi":"đồng thời với"}],"wordFamily":["concurrently (adv.)","concurrency (n.)"],"synonyms":["simultaneous"],"antonyms":["sequential"],"tipVi":"Nhấn mạnh sự trùng lặp về thời gian; diễn đạt \"đồng thời với\" dùng concurrent with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meticulously', 'en-c1-36', 'meticulously', '/məˈtɪkjələsli/', 'C1', 'tỉ mỉ; một cách kỹ lưỡng', 'adv.', 'meticulous (adj.), meticulousness (n.)', 'Đồng nghĩa: carefully, thoroughly · Trái nghĩa: carelessly', 'Nhấn mạnh sự chú ý đến từng chi tiết, không mang nghĩa là rụt rè hay sợ sệt.', 'She meticulously cleaned each tiny part of the watch.', NULL, 'Cô ấy đã lau chùi tỉ mỉ từng chi tiết nhỏ của chiếc đồng hồ.', '{"wordId":"meticulously","ukIpa":"/məˈtɪkjələsli/","usIpa":"/məˈtɪkjələsli/","cefr":"C1","topic":"work","senses":[{"pos":"adv.","en":"with great care and attention to every detail","vi":"tỉ mỉ; một cách kỹ lưỡng"}],"examples":[{"en":"She meticulously cleaned each tiny part of the watch.","vi":"Cô ấy đã lau chùi tỉ mỉ từng chi tiết nhỏ của chiếc đồng hồ.","audioKind":"ex"},{"en":"Researchers must meticulously record their procedures so that other teams can reproduce and verify the results.","vi":"Các nhà nghiên cứu phải ghi chép lại các quy trình một cách tỉ mỉ để các nhóm khác có thể tái hiện và kiểm chứng kết quả.","audioKind":"ex2"}],"collocations":[{"en":"meticulously planned","vi":"được lên kế hoạch tỉ mỉ"},{"en":"meticulously documented","vi":"được tài liệu hóa tỉ mỉ"},{"en":"meticulously examine","vi":"kiểm tra kỹ lưỡng"}],"wordFamily":["meticulous (adj.)","meticulousness (n.)"],"synonyms":["carefully","thoroughly"],"antonyms":["carelessly"],"tipVi":"Nhấn mạnh sự chú ý đến từng chi tiết, không mang nghĩa là rụt rè hay sợ sệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_facilitate', 'en-c1-36', 'facilitate', '/fəˈsɪlɪteɪt/', 'C1', 'làm cho thuận lợi; thúc đẩy; hỗ trợ', 'v.', 'facilitation (n.), facilitator (n.)', 'Đồng nghĩa: ease, assist · Trái nghĩa: hinder, impede', 'Đi sau bởi danh từ hoặc danh động từ, không dùng cấu trúc facilitate somebody to do.', 'These sliding doors facilitate access for people using wheelchairs.', NULL, 'Những cánh cửa trượt này giúp cho người dùng xe lăn ra vào thuận lợi hơn.', '{"wordId":"facilitate","ukIpa":"/fəˈsɪlɪteɪt/","usIpa":"/fəˈsɪlɪteɪt/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"make an action or process easier","vi":"làm cho thuận lợi; thúc đẩy; hỗ trợ"}],"examples":[{"en":"These sliding doors facilitate access for people using wheelchairs.","vi":"Những cánh cửa trượt này giúp cho người dùng xe lăn ra vào thuận lợi hơn.","audioKind":"ex"},{"en":"Digital platforms can facilitate collaboration between students in different countries, allowing them to exchange ideas more easily.","vi":"Các nền tảng kỹ thuật số có thể thúc đẩy sự hợp tác giữa học sinh sinh viên ở các quốc gia khác nhau, giúp họ trao đổi ý tưởng dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"facilitate communication","vi":"thúc đẩy giao tiếp"},{"en":"facilitate learning","vi":"hỗ trợ việc học tập"},{"en":"facilitate access","vi":"tạo thuận lợi cho việc tiếp cận"}],"wordFamily":["facilitation (n.)","facilitator (n.)"],"synonyms":["ease","assist"],"antonyms":["hinder","impede"],"tipVi":"Đi sau bởi danh từ hoặc danh động từ, không dùng cấu trúc facilitate somebody to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dispatch', 'en-c1-36', 'dispatch', '/dɪˈspætʃ/', 'C1', 'gửi, phái (ai hoặc cái gì đi đến một địa điểm cụ thể); sự gửi đi, sự phái đi (hàng hóa, tin nhắn hoặc con người); bản tin chính thức; bài tường thuật của phóng viên', 'v.', 'dispatcher (n.)', 'Đồng nghĩa: send', '"Despatch" cũng là một cách viết đúng, nhưng "dispatch" phổ biến hơn.', 'The shop dispatched my new shoes this morning.', NULL, 'Cửa hàng đã gửi đôi giày mới của tôi đi vào sáng nay.', '{"wordId":"dispatch","ukIpa":"/dɪˈspætʃ/","usIpa":"/dɪˈspætʃ/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To send someone or something to a particular destination.","vi":"gửi, phái (ai hoặc cái gì đi đến một địa điểm cụ thể)"},{"pos":"n.","en":"The act of sending goods, messages, or people somewhere.","vi":"sự gửi đi, sự phái đi (hàng hóa, tin nhắn hoặc con người)"},{"pos":"n.","en":"An official message or a report sent by a journalist.","vi":"bản tin chính thức; bài tường thuật của phóng viên"}],"examples":[{"en":"The shop dispatched my new shoes this morning.","vi":"Cửa hàng đã gửi đôi giày mới của tôi đi vào sáng nay.","audioKind":"ex"},{"en":"Local authorities should dispatch emergency teams quickly when severe flooding threatens homes and essential infrastructure.","vi":"Chính quyền địa phương nên nhanh chóng phái các đội ứng phó khẩn cấp khi lũ lụt nghiêm trọng đe dọa nhà cửa và cơ sở hạ tầng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"dispatch goods","vi":"gửi hàng hóa"},{"en":"dispatch a team","vi":"cử một đội"},{"en":"ready for dispatch","vi":"sẵn sàng để gửi đi"},{"en":"a news dispatch","vi":"một bản tin thời sự"}],"wordFamily":["dispatcher (n.)"],"synonyms":["send"],"antonyms":[],"tipVi":"\"Despatch\" cũng là một cách viết đúng, nhưng \"dispatch\" phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_certification', 'en-c1-36', 'certification', '/ˌsɝːtɪfɪˈkeɪʃən/', 'C1', 'sự cấp giấy chứng nhận; chứng chỉ, văn bằng công nhận', 'n.', 'certify (v.), certificate (n.), certified (adj.)', NULL, '"Certification" nhấn mạnh quá trình cấp chứng nhận; "certificate" thường chỉ bản thân tấm văn bằng/chứng chỉ.', 'The swimming instructor proudly showed us her new certification.', NULL, 'Nữ huấn luyện viên bơi lội tự hào khoe với chúng tôi chứng chỉ mới của cô ấy.', '{"wordId":"certification","ukIpa":"/ˌsɜːtɪfɪˈkeɪʃən/","usIpa":"/ˌsɝːtɪfɪˈkeɪʃən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Official confirmation that someone or something meets required standards.","vi":"sự cấp giấy chứng nhận; chứng chỉ, văn bằng công nhận"}],"examples":[{"en":"The swimming instructor proudly showed us her new certification.","vi":"Nữ huấn luyện viên bơi lội tự hào khoe với chúng tôi chứng chỉ mới của cô ấy.","audioKind":"ex"},{"en":"Independent certification helps consumers identify products that meet recognised environmental standards throughout the production process.","vi":"Chứng nhận độc lập giúp người tiêu dùng nhận diện các sản phẩm đáp ứng các tiêu chuẩn môi trường được công nhận trong suốt quá trình sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"professional certification","vi":"chứng nhận chuyên môn"},{"en":"obtain certification","vi":"đạt được chứng nhận"},{"en":"certification body","vi":"tổ chức chứng nhận"},{"en":"certification process","vi":"quy trình chứng nhận"}],"wordFamily":["certify (v.)","certificate (n.)","certified (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"Certification\" nhấn mạnh quá trình cấp chứng nhận; \"certificate\" thường chỉ bản thân tấm văn bằng/chứng chỉ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_requisite', 'en-c1-36', 'requisite', '/ˈrekwɪzɪt/', 'C1', 'cần thiết, thiết yếu cho một mục đích cụ thể; vật phẩm thiết yếu; điều kiện cần', 'adj.', NULL, 'Đồng nghĩa: necessary, required, essential · Trái nghĩa: unnecessary', 'Từ mang tính trang trọng; "requisite" chỉ sự cần thiết, trong khi "prerequisite" nhấn mạnh tính chất điều kiện tiên quyết.', 'She has the requisite skills to repair this bicycle.', NULL, 'Cô ấy có các kỹ năng cần thiết để sửa chiếc xe đạp này.', '{"wordId":"requisite","ukIpa":"/ˈrekwɪzɪt/","usIpa":"/ˈrekwɪzɪt/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"needed for a particular purpose","vi":"cần thiết, thiết yếu cho một mục đích cụ thể"},{"pos":"n.","en":"something necessary for a particular purpose","vi":"vật phẩm thiết yếu; điều kiện cần"}],"examples":[{"en":"She has the requisite skills to repair this bicycle.","vi":"Cô ấy có các kỹ năng cần thiết để sửa chiếc xe đạp này.","audioKind":"ex"},{"en":"Applicants without the requisite qualifications may benefit from training programmes designed to improve access to skilled employment.","vi":"Những ứng viên thiếu trình độ chuyên môn cần thiết có thể hưởng lợi từ các chương trình đào tạo được thiết kế để giúp họ tiếp cận việc làm tay nghề cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"requisite skills","vi":"kỹ năng thiết yếu"},{"en":"requisite qualifications","vi":"trình độ chuyên môn cần thiết"},{"en":"a requisite for success","vi":"điều kiện tiên quyết để thành công"}],"wordFamily":[],"synonyms":["necessary","required","essential"],"antonyms":["unnecessary"],"tipVi":"Từ mang tính trang trọng; \"requisite\" chỉ sự cần thiết, trong khi \"prerequisite\" nhấn mạnh tính chất điều kiện tiên quyết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_custodian', 'en-c1-36', 'custodian', '/kʌˈstoʊdiən/', 'C1', 'người bảo quản; người quản lý; nhân viên vệ sinh; người bảo trì tòa nhà', 'n.', 'custody (n.), custodial (adj.)', 'Đồng nghĩa: guardian, caretaker', 'custodian of thường đi kèm với đối tượng được bảo quản hoặc bảo vệ.', 'The custodian carefully locked the cabinet containing ancient coins.', NULL, 'Người bảo quản cẩn thận khóa chiếc tủ đựng tiền xu cổ lại.', '{"wordId":"custodian","ukIpa":"/kʌˈstəʊdiən/","usIpa":"/kʌˈstoʊdiən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A person or organisation responsible for protecting or managing something.","vi":"người bảo quản; người quản lý"},{"pos":"n.","en":"Someone employed to clean and maintain a building, especially in America.","vi":"nhân viên vệ sinh; người bảo trì tòa nhà"}],"examples":[{"en":"The custodian carefully locked the cabinet containing ancient coins.","vi":"Người bảo quản cẩn thận khóa chiếc tủ đựng tiền xu cổ lại.","audioKind":"ex"},{"en":"Museums act as custodians of cultural heritage, preserving valuable objects for research and future generations.","vi":"Các bảo tàng đóng vai trò là những người bảo tồn di sản văn hóa, gìn giữ các hiện vật quý giá cho công tác nghiên cứu và các thế hệ mai sau.","audioKind":"ex2"}],"collocations":[{"en":"custodian of cultural heritage","vi":"người bảo tồn di sản văn hóa"},{"en":"school custodian","vi":"nhân viên vệ sinh trường học"},{"en":"legal custodian","vi":"người giám hộ hợp pháp"}],"wordFamily":["custody (n.)","custodial (adj.)"],"synonyms":["guardian","caretaker"],"antonyms":[],"tipVi":"custodian of thường đi kèm với đối tượng được bảo quản hoặc bảo vệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_merge', 'en-c1-36', 'merge', '/mɝːdʒ/', 'C1', 'hợp nhất; hòa nhập', 'v.', 'merger (n.)', 'Đồng nghĩa: combine, unite · Trái nghĩa: separate, split', 'merge with biểu thị với...; merge into biểu thị nhập vào.', 'The two narrow paths merge just beyond the bridge.', NULL, 'Hai con đường nhỏ hợp nhất lại ngay phía bên kia cây cầu.', '{"wordId":"merge","ukIpa":"/mɜːdʒ/","usIpa":"/mɝːdʒ/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"Combine or join together to form a single whole.","vi":"hợp nhất; hòa nhập"}],"examples":[{"en":"The two narrow paths merge just beyond the bridge.","vi":"Hai con đường nhỏ hợp nhất lại ngay phía bên kia cây cầu.","audioKind":"ex"},{"en":"Small businesses may merge to reduce operating costs and compete more effectively with larger companies.","vi":"Các doanh nghiệp nhỏ có thể hợp nhất để giảm chi phí vận hành và cạnh tranh hiệu quả hơn với các công ty lớn.","audioKind":"ex2"}],"collocations":[{"en":"merge with another company","vi":"sáp nhập với công ty khác"},{"en":"merge into one","vi":"hợp nhất thành một"},{"en":"merge two departments","vi":"hợp nhất hai phòng ban"}],"wordFamily":["merger (n.)"],"synonyms":["combine","unite"],"antonyms":["separate","split"],"tipVi":"merge with biểu thị với...; merge into biểu thị nhập vào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_memorandum', 'en-c1-36', 'memorandum', '/ˌmeməˈrændəm/', 'C1', 'bản ghi nhớ; thông cáo nội bộ; bản ghi nhớ thỏa thuận chính thức', 'n.', 'memo (n.)', 'Đồng nghĩa: memo', 'Thường được viết tắt là memo; dạng số nhiều có thể là memoranda hoặc memorandums.', 'The manager sent a memorandum about our new working hours.', NULL, 'Người quản lý đã gửi một bản thông cáo nội bộ về giờ làm việc mới của chúng ta.', '{"wordId":"memorandum","ukIpa":"/ˌmeməˈrændəm/","usIpa":"/ˌmeməˈrændəm/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A written message sharing information within an organisation","vi":"bản ghi nhớ; thông cáo nội bộ"},{"pos":"n.","en":"A formal document recording an agreement or shared intentions","vi":"bản ghi nhớ thỏa thuận chính thức"}],"examples":[{"en":"The manager sent a memorandum about our new working hours.","vi":"Người quản lý đã gửi một bản thông cáo nội bộ về giờ làm việc mới của chúng ta.","audioKind":"ex"},{"en":"The two universities signed a memorandum of understanding to support joint research into renewable energy.","vi":"Hai trường đại học đã ký kết biên bản ghi nhớ nhằm hỗ trợ nghiên cứu chung về năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"an internal memorandum","vi":"bản ghi nhớ nội bộ"},{"en":"issue a memorandum","vi":"ban hành bản ghi nhớ"},{"en":"memorandum of understanding","vi":"biên bản ghi nhớ"}],"wordFamily":["memo (n.)"],"synonyms":["memo"],"antonyms":[],"tipVi":"Thường được viết tắt là memo; dạng số nhiều có thể là memoranda hoặc memorandums.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contractual', 'en-c1-36', 'contractual', '/kənˈtræktʃuəl/', 'C1', 'theo hợp đồng; thuộc về khế ước', 'adj.', 'contract (n.), contract (v.), contractually (adv.)', NULL, 'Nhấn mạnh các quyền hoặc nghĩa vụ được quy định trong hợp đồng, thường đứng trước danh từ.', 'Fixing the heating is the landlord''s contractual responsibility.', NULL, 'Sửa chữa hệ thống sưởi là trách nhiệm theo hợp đồng của chủ nhà.', '{"wordId":"contractual","ukIpa":"/kənˈtræktʃuəl/","usIpa":"/kənˈtræktʃuəl/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Relating to or required by a legal agreement.","vi":"theo hợp đồng; thuộc về khế ước"}],"examples":[{"en":"Fixing the heating is the landlord''s contractual responsibility.","vi":"Sửa chữa hệ thống sưởi là trách nhiệm theo hợp đồng của chủ nhà.","audioKind":"ex"},{"en":"Employers should explain contractual obligations clearly so that workers understand their rights before accepting a position.","vi":"Người sử dụng lao động nên giải thích rõ ràng các nghĩa vụ hợp đồng để người lao động hiểu rõ quyền lợi của mình trước khi nhận việc.","audioKind":"ex2"}],"collocations":[{"en":"contractual obligations","vi":"nghĩa vụ hợp đồng"},{"en":"contractual rights","vi":"quyền lợi theo hợp đồng"},{"en":"contractual terms","vi":"điều khoản hợp đồng"},{"en":"contractual agreement","vi":"thỏa thuận hợp đồng"}],"wordFamily":["contract (n.)","contract (v.)","contractually (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh các quyền hoặc nghĩa vụ được quy định trong hợp đồng, thường đứng trước danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commend', 'en-c1-36', 'commend', '/kəˈmend/', 'C1', 'tuyên dương; khen ngợi; giới thiệu; tán thành', 'v.', 'commendation (n.), commendable (adj.), commendably (adv.)', 'Đồng nghĩa: praise, applaud · Trái nghĩa: criticize', 'Commend có nghĩa là khen ngợi, trong khi command có nghĩa là ra lệnh; cần chú ý kỹ chính tả.', 'The coach commended Lina for helping her teammates.', NULL, 'Huấn luyện viên đã biểu dương Lina vì đã giúp đỡ các đồng đội.', '{"wordId":"commend","ukIpa":"/kəˈmend/","usIpa":"/kəˈmend/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to praise someone or something, often publicly","vi":"tuyên dương; khen ngợi"},{"pos":"v.","en":"to recommend someone or something as worthy of consideration","vi":"giới thiệu; tán thành"}],"examples":[{"en":"The coach commended Lina for helping her teammates.","vi":"Huấn luyện viên đã biểu dương Lina vì đã giúp đỡ các đồng đội.","audioKind":"ex"},{"en":"Inspectors commended the school for providing additional support to students with different learning needs.","vi":"Các thanh tra viên đã khen ngợi nhà trường vì đã cung cấp sự hỗ trợ thêm cho học sinh có các nhu cầu học tập khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"commend someone for something","vi":"khen ngợi ai vì điều gì"},{"en":"highly commended","vi":"được đánh giá rất cao; được khen ngợi nhiệt liệt"},{"en":"commend something to someone","vi":"giới thiệu cái gì cho ai"}],"wordFamily":["commendation (n.)","commendable (adj.)","commendably (adv.)"],"synonyms":["praise","applaud"],"antonyms":["criticize"],"tipVi":"Commend có nghĩa là khen ngợi, trong khi command có nghĩa là ra lệnh; cần chú ý kỹ chính tả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reimbursement', 'en-c1-36', 'reimbursement', '/ˌriːɪmˈbɝːsmənt/', 'C1', 'sự hoàn tiền; khoản tiền bồi hoàn (cho số tiền đã chi tiêu)', 'n.', 'reimburse (v.), reimbursable (adj.)', 'Đồng nghĩa: repayment', 'Thường chỉ việc thanh toán lại các chi phí đã bỏ ra, không dùng cho việc trả nợ chung chung.', 'Keep your train ticket to claim reimbursement from work.', NULL, 'Hãy giữ lại vé tàu của bạn để làm thủ tục thanh toán lại tiền từ công ty.', '{"wordId":"reimbursement","ukIpa":"/ˌriːɪmˈbɜːsmənt/","usIpa":"/ˌriːɪmˈbɝːsmənt/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"payment given back for money someone has spent","vi":"sự hoàn tiền; khoản tiền bồi hoàn (cho số tiền đã chi tiêu)"}],"examples":[{"en":"Keep your train ticket to claim reimbursement from work.","vi":"Hãy giữ lại vé tàu của bạn để làm thủ tục thanh toán lại tiền từ công ty.","audioKind":"ex"},{"en":"Providing reimbursement for travel expenses can make professional training more accessible to employees from low-income households.","vi":"Việc hỗ trợ hoàn trả chi phí đi lại có thể giúp nhân viên từ các hộ gia đình thu nhập thấp dễ dàng tiếp cận các cơ hội đào tạo nghề hơn.","audioKind":"ex2"}],"collocations":[{"en":"claim reimbursement","vi":"yêu cầu hoàn tiền"},{"en":"reimbursement of expenses","vi":"bồi hoàn chi phí"},{"en":"full reimbursement","vi":"hoàn tiền toàn bộ"}],"wordFamily":["reimburse (v.)","reimbursable (adj.)"],"synonyms":["repayment"],"antonyms":[],"tipVi":"Thường chỉ việc thanh toán lại các chi phí đã bỏ ra, không dùng cho việc trả nợ chung chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_execution', 'en-c1-36', 'execution', '/ˌeksɪˈkjuːʃən/', 'C1', 'sự thực thi; sự thi hành; sự hành quyết; việc thi hành án tử hình; cách thực hiện; kỹ thuật biểu diễn', 'n.', 'execute (v.), executable (adj.)', 'Đồng nghĩa: implementation', 'Có thể chỉ việc thực hiện kế hoạch hoặc việc thi hành án tử hình, cần dựa vào ngữ cảnh.', 'The picnic plan was simple, but its execution proved tricky.', NULL, 'Kế hoạch đi dã ngoại rất đơn giản, nhưng việc thực hiện lại tỏ ra phức tạp.', '{"wordId":"execution","ukIpa":"/ˌeksɪˈkjuːʃən/","usIpa":"/ˌeksɪˈkjuːʃən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"the act of carrying out a plan, order, or task","vi":"sự thực thi; sự thi hành"},{"pos":"n.","en":"the act of killing someone as a legal punishment","vi":"sự hành quyết; việc thi hành án tử hình"},{"pos":"n.","en":"the way a skilled action or performance is carried out","vi":"cách thực hiện; kỹ thuật biểu diễn"}],"examples":[{"en":"The picnic plan was simple, but its execution proved tricky.","vi":"Kế hoạch đi dã ngoại rất đơn giản, nhưng việc thực hiện lại tỏ ra phức tạp.","audioKind":"ex"},{"en":"Successful execution of environmental policies requires adequate funding, clear responsibilities, and consistent monitoring by public authorities.","vi":"Việc thực thi thành công các chính sách môi trường đòi hỏi nguồn vốn đầy đủ, trách nhiệm rõ ràng và sự giám sát nhất quán từ các cơ quan công quyền.","audioKind":"ex2"}],"collocations":[{"en":"execution of a plan","vi":"việc thực thi kế hoạch"},{"en":"flawless execution","vi":"màn thể hiện hoàn hảo"},{"en":"stay of execution","vi":"lệnh tạm hoãn thi hành án tử hình"}],"wordFamily":["execute (v.)","executable (adj.)"],"synonyms":["implementation"],"antonyms":[],"tipVi":"Có thể chỉ việc thực hiện kế hoạch hoặc việc thi hành án tử hình, cần dựa vào ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_endeavor', 'en-c1-36', 'endeavor', '/ɪnˈdevər/', 'C1', 'nỗ lực; cố gắng; sự nỗ lực; sự cố gắng', 'v.', NULL, 'Đồng nghĩa: strive, attempt', 'Cách viết theo tiếng Mỹ; tiếng Anh-Anh là endeavour, động từ thường đi với to do.', 'We endeavor to answer every message before dinner.', NULL, 'Chúng tôi cố gắng trả lời mọi tin nhắn trước bữa tối.', '{"wordId":"endeavor","ukIpa":"/ɪnˈdevə/","usIpa":"/ɪnˈdevər/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To try hard to achieve something","vi":"nỗ lực; cố gắng"},{"pos":"n.","en":"A serious effort to achieve a goal","vi":"sự nỗ lực; sự cố gắng"}],"examples":[{"en":"We endeavor to answer every message before dinner.","vi":"Chúng tôi cố gắng trả lời mọi tin nhắn trước bữa tối.","audioKind":"ex"},{"en":"Universities should endeavor to make higher education accessible to students from a wider range of backgrounds.","vi":"Các trường đại học nên nỗ lực giúp sinh viên từ nhiều hoàn cảnh khác nhau có thể tiếp cận giáo dục bậc cao.","audioKind":"ex2"}],"collocations":[{"en":"endeavor to do something","vi":"nỗ lực làm điều gì đó"},{"en":"a joint endeavor","vi":"sự nỗ lực chung"},{"en":"scientific endeavor","vi":"nỗ lực nghiên cứu khoa học"}],"wordFamily":[],"synonyms":["strive","attempt"],"antonyms":[],"tipVi":"Cách viết theo tiếng Mỹ; tiếng Anh-Anh là endeavour, động từ thường đi với to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meticulous', 'en-c1-36', 'meticulous', '/məˈtɪkjələs/', 'C1', 'tỉ mỉ; cẩn trọng đến từng chi tiết nhỏ', 'adj.', 'meticulously (adv.), meticulousness (n.)', 'Đồng nghĩa: thorough, painstaking, careful · Trái nghĩa: careless, sloppy', 'Thường mang nghĩa tích cực, nhấn mạnh sự chú ý cẩn thận đến mọi chi tiết.', 'He made meticulous notes while repairing the old clock.', NULL, 'Anh ấy đã ghi chép rất tỉ mỉ trong lúc sửa chiếc đồng hồ cổ.', '{"wordId":"meticulous","ukIpa":"/məˈtɪkjələs/","usIpa":"/məˈtɪkjələs/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Extremely careful and attentive to every small detail.","vi":"tỉ mỉ; cẩn trọng đến từng chi tiết nhỏ"}],"examples":[{"en":"He made meticulous notes while repairing the old clock.","vi":"Anh ấy đã ghi chép rất tỉ mỉ trong lúc sửa chiếc đồng hồ cổ.","audioKind":"ex"},{"en":"Meticulous planning is essential when researchers conduct experiments involving complex equipment and sensitive environmental measurements.","vi":"Việc lập kế hoạch tỉ mỉ là điều cốt yếu khi các nhà nghiên cứu tiến hành các thí nghiệm liên quan đến thiết bị phức tạp và các phép đo môi trường nhạy cảm.","audioKind":"ex2"}],"collocations":[{"en":"meticulous attention to detail","vi":"sự chú ý tỉ mỉ đến từng chi tiết"},{"en":"meticulous planning","vi":"kế hoạch chu đáo"},{"en":"meticulous records","vi":"ghi chép chi tiết chính xác"}],"wordFamily":["meticulously (adv.)","meticulousness (n.)"],"synonyms":["thorough","painstaking","careful"],"antonyms":["careless","sloppy"],"tipVi":"Thường mang nghĩa tích cực, nhấn mạnh sự chú ý cẩn thận đến mọi chi tiết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_protracted', 'en-c1-36', 'protracted', '/prəˈtræktɪd/', 'C1', 'kéo dài; dây dưa; kéo dài lâu hơn dự kiến', 'adj.', 'protract (v.), protraction (n.)', 'Đồng nghĩa: prolonged, drawn-out, lengthy · Trái nghĩa: brief', 'Mang tính nhấn mạnh việc kéo dài lâu hơn so với từ long thông thường, thường mang sắc thái tiêu cực.', 'After a protracted discussion, we finally chose a sofa.', NULL, 'Sau một cuộc thảo luận kéo dài, cuối cùng chúng tôi đã chọn được một chiếc ghế sofa.', '{"wordId":"protracted","ukIpa":"/prəˈtræktɪd/","usIpa":"/prəˈtræktɪd/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Lasting longer than expected or desired.","vi":"kéo dài; dây dưa; kéo dài lâu hơn dự kiến"}],"examples":[{"en":"After a protracted discussion, we finally chose a sofa.","vi":"Sau một cuộc thảo luận kéo dài, cuối cùng chúng tôi đã chọn được một chiếc ghế sofa.","audioKind":"ex"},{"en":"Protracted negotiations over funding can delay essential infrastructure projects and increase their overall cost considerably.","vi":"Các cuộc đàm phán kéo dài về vấn đề tài chính có thể làm trì hoãn các dự án cơ sở hạ tầng thiết yếu và làm tăng đáng kể tổng chi phí của chúng.","audioKind":"ex2"}],"collocations":[{"en":"protracted negotiations","vi":"các cuộc đàm phán kéo dài"},{"en":"protracted dispute","vi":"tranh chấp lâu ngày"},{"en":"protracted delay","vi":"sự trì hoãn kéo dài"},{"en":"protracted illness","vi":"căn bệnh mãn tính kéo dài"}],"wordFamily":["protract (v.)","protraction (n.)"],"synonyms":["prolonged","drawn-out","lengthy"],"antonyms":["brief"],"tipVi":"Mang tính nhấn mạnh việc kéo dài lâu hơn so với từ long thông thường, thường mang sắc thái tiêu cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stationer', 'en-c1-36', 'stationer', '/ˈsteɪʃənər/', 'C1', 'nhà kinh doanh văn phòng phẩm; cửa hàng văn phòng phẩm', 'n.', 'stationery (n.)', NULL, 'Cửa hàng văn phòng phẩm thường dùng stationer''s; stationery là văn phòng phẩm, đừng nhầm với stationary.', 'The stationer helped me choose a notebook for school.', NULL, 'Người bán văn phòng phẩm đã giúp tôi chọn một cuốn vở cho trường học.', '{"wordId":"stationer","ukIpa":"/ˈsteɪʃənə/","usIpa":"/ˈsteɪʃənər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A person or business that sells writing and office supplies.","vi":"nhà kinh doanh văn phòng phẩm; cửa hàng văn phòng phẩm"}],"examples":[{"en":"The stationer helped me choose a notebook for school.","vi":"Người bán văn phòng phẩm đã giúp tôi chọn một cuốn vở cho trường học.","audioKind":"ex"},{"en":"A local stationer may struggle to compete with online retailers offering cheaper office supplies.","vi":"Một cửa hàng văn phòng phẩm địa phương có thể gặp khó khăn trong việc cạnh tranh với các nhà bán lẻ trực tuyến cung cấp đồ dùng văn phòng giá rẻ hơn.","audioKind":"ex2"}],"collocations":[{"en":"a local stationer","vi":"cửa hàng văn phòng phẩm địa phương"},{"en":"a high-street stationer","vi":"cửa hàng văn phòng phẩm trên phố lớn"},{"en":"at the stationer''s","vi":"tại cửa hàng văn phòng phẩm"}],"wordFamily":["stationery (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cửa hàng văn phòng phẩm thường dùng stationer''s; stationery là văn phòng phẩm, đừng nhầm với stationary.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entrant', 'en-c1-36', 'entrant', '/ˈentrənt/', 'C1', 'thí sinh; người tham gia cuộc thi; thành viên mới; người mới gia nhập lĩnh vực', 'n.', 'enter (v.), entry (n.), entrance (n.)', 'Đồng nghĩa: participant, competitor', 'Người mới gia nhập lĩnh vực nào dùng entrant to; không đồng nghĩa với lối vào entrance.', 'Each entrant brought a homemade cake to the competition.', NULL, 'Mỗi thí sinh mang theo một chiếc bánh tự làm đến cuộc thi.', '{"wordId":"entrant","ukIpa":"/ˈentrənt/","usIpa":"/ˈentrənt/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"a person who takes part in a competition","vi":"thí sinh; người tham gia cuộc thi"},{"pos":"n.","en":"a person or organisation newly joining an activity or field","vi":"thành viên mới; người mới gia nhập lĩnh vực"}],"examples":[{"en":"Each entrant brought a homemade cake to the competition.","vi":"Mỗi thí sinh mang theo một chiếc bánh tự làm đến cuộc thi.","audioKind":"ex"},{"en":"New entrants to the renewable energy market often struggle to compete with established companies for investment.","vi":"Những người mới gia nhập thị trường năng lượng tái tạo thường gặp khó khăn trong việc cạnh tranh thu hút đầu tư với các công ty lâu năm.","audioKind":"ex2"}],"collocations":[{"en":"competition entrant","vi":"thí sinh dự thi"},{"en":"new entrant","vi":"thành viên mới"},{"en":"market entrant","vi":"doanh nghiệp mới gia nhập thị trường"}],"wordFamily":["enter (v.)","entry (n.)","entrance (n.)"],"synonyms":["participant","competitor"],"antonyms":[],"tipVi":"Người mới gia nhập lĩnh vực nào dùng entrant to; không đồng nghĩa với lối vào entrance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_procure', 'en-c1-36', 'procure', '/prəˈkjʊr/', 'C1', 'kiếm được; thu được; mua sắm', 'v.', 'procurement (n.)', 'Đồng nghĩa: obtain, acquire, secure', 'Đây là một ngoại động từ trang trọng, đi trực tiếp với đối tượng hoặc tài nguyên thu được.', 'We finally procured a spare part for the oven.', NULL, 'Cuối cùng chúng tôi cũng tìm mua được một linh kiện dự phòng cho chiếc lò nướng.', '{"wordId":"procure","ukIpa":"/prəˈkjʊə/","usIpa":"/prəˈkjʊr/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to obtain something, especially through effort or careful arrangements","vi":"kiếm được; thu được; mua sắm"}],"examples":[{"en":"We finally procured a spare part for the oven.","vi":"Cuối cùng chúng tôi cũng tìm mua được một linh kiện dự phòng cho chiếc lò nướng.","audioKind":"ex"},{"en":"Local authorities must procure reliable equipment to ensure that drinking water remains safe during emergencies.","vi":"Các cơ quan địa phương phải mua sắm trang thiết bị đáng tin cậy để đảm bảo nước uống vẫn an toàn trong các tình huống khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"procure equipment","vi":"mua sắm thiết bị"},{"en":"procure supplies","vi":"thu mua vật tư"},{"en":"procure funding","vi":"huy động vốn"}],"wordFamily":["procurement (n.)"],"synonyms":["obtain","acquire","secure"],"antonyms":[],"tipVi":"Đây là một ngoại động từ trang trọng, đi trực tiếp với đối tượng hoặc tài nguyên thu được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deadlock', 'en-c1-36', 'deadlock', '/ˈdedlɑːk/', 'C1', 'tình trạng bế tắc; sự đình trệ', 'n.', 'deadlocked (adj.)', 'Đồng nghĩa: stalemate, impasse', 'Thường đi với các động từ reach hoặc break, nhấn mạnh việc bất đồng ý kiến làm tiến trình bị đình trệ.', 'Our discussion reached a deadlock over who should pay.', NULL, 'Cuộc thảo luận của chúng tôi rơi vào bế tắc vì không ai chịu nhường nhau chuyện ai là người phải trả tiền.', '{"wordId":"deadlock","ukIpa":"/ˈdedlɒk/","usIpa":"/ˈdedlɑːk/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A situation where disagreement prevents any further progress.","vi":"tình trạng bế tắc; sự đình trệ"}],"examples":[{"en":"Our discussion reached a deadlock over who should pay.","vi":"Cuộc thảo luận của chúng tôi rơi vào bế tắc vì không ai chịu nhường nhau chuyện ai là người phải trả tiền.","audioKind":"ex"},{"en":"An independent mediator may help break the deadlock when negotiations between employers and workers fail.","vi":"Một nhà trung gian độc lập có thể giúp phá vỡ thế bế tắc khi các cuộc đàm phán giữa chủ lao động và người lao động đổ vỡ.","audioKind":"ex2"}],"collocations":[{"en":"reach a deadlock","vi":"rơi vào bế tắc"},{"en":"break the deadlock","vi":"phá vỡ thế bế tắc"},{"en":"end in deadlock","vi":"kết thúc trong bế tắc"}],"wordFamily":["deadlocked (adj.)"],"synonyms":["stalemate","impasse"],"antonyms":[],"tipVi":"Thường đi với các động từ reach hoặc break, nhấn mạnh việc bất đồng ý kiến làm tiến trình bị đình trệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_laborious', 'en-c1-36', 'laborious', '/ləˈbɔːriəs/', 'C1', 'gian khổ; tốn nhiều thời gian và công sức', 'adj.', 'laboriously (adv.), labour (n.), labour (v.)', 'Đồng nghĩa: arduous, painstaking · Trái nghĩa: effortless, easy', 'Thường dùng để mô tả nhiệm vụ hoặc quá trình; để chỉ người chăm chỉ, hãy dùng industrious.', 'Removing the old wallpaper was a slow, laborious job.', NULL, 'Gỡ bỏ lớp giấy dán tường cũ là một công việc chậm chạp và tốn nhiều công sức.', '{"wordId":"laborious","ukIpa":"/ləˈbɔːriəs/","usIpa":"/ləˈbɔːriəs/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"requiring a lot of time and hard work","vi":"gian khổ; tốn nhiều thời gian và công sức"}],"examples":[{"en":"Removing the old wallpaper was a slow, laborious job.","vi":"Gỡ bỏ lớp giấy dán tường cũ là một công việc chậm chạp và tốn nhiều công sức.","audioKind":"ex"},{"en":"Digitising historical records is a laborious process, but it greatly improves public access to valuable research materials.","vi":"Số hóa các tài liệu lịch sử là một quá trình tốn nhiều công sức, nhưng nó giúp công chúng tiếp cận các tài liệu nghiên cứu có giá trị dễ dàng hơn rất nhiều.","audioKind":"ex2"}],"collocations":[{"en":"laborious process","vi":"quá trình tốn nhiều công sức"},{"en":"laborious task","vi":"nhiệm vụ gian khổ"},{"en":"laborious work","vi":"công việc nặng nhọc"}],"wordFamily":["laboriously (adv.)","labour (n.)","labour (v.)"],"synonyms":["arduous","painstaking"],"antonyms":["effortless","easy"],"tipVi":"Thường dùng để mô tả nhiệm vụ hoặc quá trình; để chỉ người chăm chỉ, hãy dùng industrious.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_retention', 'en-c1-36', 'retention', '/rɪˈtenʃən/', 'C1', 'sự giữ chân; việc duy trì; khả năng ghi nhớ; sự lưu giữ thông tin; sự ứ đọng; sự giữ lại chất dịch trong cơ thể', 'n.', 'retain (v.), retentive (adj.)', NULL, 'Thường là danh từ không đếm được; động từ tương ứng là retain.', 'Our manager improved staff retention by offering flexible hours.', NULL, 'Người quản lý của chúng tôi đã nâng cao tỷ lệ giữ chân nhân viên bằng cách cung cấp thời gian làm việc linh hoạt.', '{"wordId":"retention","ukIpa":"/rɪˈtenʃən/","usIpa":"/rɪˈtenʃən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"the act of keeping something or preventing someone from leaving","vi":"sự giữ chân; việc duy trì"},{"pos":"n.","en":"the ability to keep information in your memory","vi":"khả năng ghi nhớ; sự lưu giữ thông tin"},{"pos":"n.","en":"the accumulation of fluid that the body does not release","vi":"sự ứ đọng; sự giữ lại chất dịch trong cơ thể"}],"examples":[{"en":"Our manager improved staff retention by offering flexible hours.","vi":"Người quản lý của chúng tôi đã nâng cao tỷ lệ giữ chân nhân viên bằng cách cung cấp thời gian làm việc linh hoạt.","audioKind":"ex"},{"en":"Regular revision and adequate sleep can improve the retention of information among students preparing for examinations.","vi":"Việc ôn tập đều đặn và ngủ đủ giấc có thể cải thiện khả năng ghi nhớ thông tin của học sinh chuẩn bị cho kỳ thi.","audioKind":"ex2"}],"collocations":[{"en":"staff retention","vi":"tỷ lệ giữ chân nhân viên"},{"en":"customer retention","vi":"sự duy trì khách hàng"},{"en":"knowledge retention","vi":"khả năng ghi nhớ kiến thức"},{"en":"water retention","vi":"sự giữ nước trong cơ thể"}],"wordFamily":["retain (v.)","retentive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; động từ tương ứng là retain.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drudgery', 'en-c1-36', 'drudgery', '/ˈdrʌdʒəri/', 'C1', 'công việc vất vả, nhàm chán và lặp đi lặp lại', 'n.', 'drudge (n.), drudge (v.)', 'Đồng nghĩa: toil', 'Là danh từ không đếm được, nhấn mạnh công việc vừa nặng nhọc vừa đơn điệu chứ không chỉ đơn thuần là khó khăn.', 'A dishwasher takes much of the drudgery out of cleaning.', NULL, 'Máy rửa bát giúp giảm bớt rất nhiều sự vất vả và nhàm chán của việc dọn dẹp.', '{"wordId":"drudgery","ukIpa":"/ˈdrʌdʒəri/","usIpa":"/ˈdrʌdʒəri/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Hard, boring work that must be repeated regularly.","vi":"công việc vất vả, nhàm chán và lặp đi lặp lại"}],"examples":[{"en":"A dishwasher takes much of the drudgery out of cleaning.","vi":"Máy rửa bát giúp giảm bớt rất nhiều sự vất vả và nhàm chán của việc dọn dẹp.","audioKind":"ex"},{"en":"Automation can reduce the drudgery of repetitive tasks, allowing workers to focus on more creative activities.","vi":"Tự động hóa có thể làm giảm bớt sự nhọc nhằn của các công việc lặp đi lặp lại, cho phép nhân viên tập trung vào các hoạt động sáng tạo hơn.","audioKind":"ex2"}],"collocations":[{"en":"daily drudgery","vi":"công việc vất vả hàng ngày"},{"en":"domestic drudgery","vi":"việc nhà nặng nhọc, nhàm chán"},{"en":"the drudgery of repetitive work","vi":"sự nhàm chán của công việc lặp đi lặp lại"}],"wordFamily":["drudge (n.)","drudge (v.)"],"synonyms":["toil"],"antonyms":[],"tipVi":"Là danh từ không đếm được, nhấn mạnh công việc vừa nặng nhọc vừa đơn điệu chứ không chỉ đơn thuần là khó khăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_venture', 'en-c1-36', 'venture', '/ˈventʃər/', 'C1', 'dự án kinh doanh rủi ro; công ty liên doanh; liều lĩnh đi đến đâu hoặc làm gì; mạo muội nêu lên ý kiến', 'n.', 'venturesome (adj.)', NULL, 'venture tự thân không có nghĩa là vốn đầu tư rủi ro; vốn mạo hiểm là venture capital.', 'Their latest business venture is a small bakery.', NULL, 'Dự án kinh doanh mới nhất của họ là một tiệm bánh nhỏ.', '{"wordId":"venture","ukIpa":"/ˈventʃə/","usIpa":"/ˈventʃər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"a new activity or business involving risk","vi":"dự án kinh doanh rủi ro; công ty liên doanh"},{"pos":"v.","en":"to go somewhere or do something despite possible risks","vi":"liều lĩnh đi đến đâu hoặc làm gì"},{"pos":"v.","en":"to express an opinion despite uncertainty about the response","vi":"mạo muội nêu lên ý kiến"}],"examples":[{"en":"Their latest business venture is a small bakery.","vi":"Dự án kinh doanh mới nhất của họ là một tiệm bánh nhỏ.","audioKind":"ex"},{"en":"Public funding can help young entrepreneurs launch ventures that address environmental problems in their communities.","vi":"Nguồn vốn công có thể giúp các nhà khởi nghiệp trẻ triển khai các dự án kinh doanh nhằm giải quyết các vấn đề môi trường tại cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"joint venture","vi":"công ty liên doanh"},{"en":"venture capital","vi":"vốn đầu tư mạo hiểm"},{"en":"venture into","vi":"mạo hiểm bước vào"},{"en":"venture an opinion","vi":"mạo muội đưa ra ý kiến"}],"wordFamily":["venturesome (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"venture tự thân không có nghĩa là vốn đầu tư rủi ro; vốn mạo hiểm là venture capital.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_counterpart', 'en-c1-36', 'counterpart', '/ˈkaʊntərpɑːrt/', 'C1', 'người hoặc vật tương đương, có cùng vai trò ở một bối cảnh khác', 'n.', NULL, 'Đồng nghĩa: equivalent', 'Nhấn mạnh vai trò tương đương ở khu vực hoặc tổ chức khác, không phải là đối thủ cạnh tranh.', 'Our team leader met her counterpart from another branch.', NULL, 'Trưởng nhóm của chúng tôi đã gặp gỡ người đồng cấp đến từ một chi nhánh khác.', '{"wordId":"counterpart","ukIpa":"/ˈkaʊntəpɑːt/","usIpa":"/ˈkaʊntərpɑːrt/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Someone or something with a similar role in another setting.","vi":"người hoặc vật tương đương, có cùng vai trò ở một bối cảnh khác"}],"examples":[{"en":"Our team leader met her counterpart from another branch.","vi":"Trưởng nhóm của chúng tôi đã gặp gỡ người đồng cấp đến từ một chi nhánh khác.","audioKind":"ex"},{"en":"Urban schools often have better access to specialist teachers than their rural counterparts, reinforcing educational inequality.","vi":"Các trường học ở thành phố thường có điều kiện tiếp cận giáo viên chuyên môn tốt hơn so với các trường học tương đương ở nông thôn, củng cố thêm tình trạng bất bình đẳng giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"a foreign counterpart","vi":"đồng nghiệp nước ngoài"},{"en":"a rural counterpart","vi":"đối trọng ở nông thôn"},{"en":"a digital counterpart","vi":"bản sao kỹ thuật số"}],"wordFamily":[],"synonyms":["equivalent"],"antonyms":[],"tipVi":"Nhấn mạnh vai trò tương đương ở khu vực hoặc tổ chức khác, không phải là đối thủ cạnh tranh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_36_1', 'en-c1-36', 'Cách dùng “requisite” (adj.) — cần thiết, thiết yếu cho một mục đích cụ thể', 'requisite skills  ·  requisite qualifications  ·  a requisite for success', 'Từ mang tính trang trọng; "requisite" chỉ sự cần thiết, trong khi "prerequisite" nhấn mạnh tính chất điều kiện tiên quyết.', 'Đồng nghĩa: necessary, required, essential · Trái nghĩa: unnecessary', '[{"hanzi":"She has the requisite skills to repair this bicycle.","pinyin":"","meaning":"Cô ấy có các kỹ năng cần thiết để sửa chiếc xe đạp này."},{"hanzi":"Applicants without the requisite qualifications may benefit from training programmes designed to improve access to skilled employment.","pinyin":"","meaning":"Những ứng viên thiếu trình độ chuyên môn cần thiết có thể hưởng lợi từ các chương trình đào tạo được thiết kế để giúp họ tiếp cận việc làm tay nghề cao hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_36_2', 'en-c1-36', 'Cách dùng “drudgery” (n.) — công việc vất vả, nhàm chán và lặp đi lặp lại', 'daily drudgery  ·  domestic drudgery  ·  the drudgery of repetitive work', 'Là danh từ không đếm được, nhấn mạnh công việc vừa nặng nhọc vừa đơn điệu chứ không chỉ đơn thuần là khó khăn.', 'Họ từ (Word Family): drudge (n.), drudge (v.) | Đồng nghĩa: toil', '[{"hanzi":"A dishwasher takes much of the drudgery out of cleaning.","pinyin":"","meaning":"Máy rửa bát giúp giảm bớt rất nhiều sự vất vả và nhàm chán của việc dọn dẹp."},{"hanzi":"Automation can reduce the drudgery of repetitive tasks, allowing workers to focus on more creative activities.","pinyin":"","meaning":"Tự động hóa có thể làm giảm bớt sự nhọc nhằn của các công việc lặp đi lặp lại, cho phép nhân viên tập trung vào các hoạt động sáng tạo hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_36_3', 'en-c1-36', 'Cách dùng “certification” (n.) — sự cấp giấy chứng nhận; chứng chỉ, văn bằng công nhận', 'professional certification  ·  obtain certification  ·  certification body', '"Certification" nhấn mạnh quá trình cấp chứng nhận; "certificate" thường chỉ bản thân tấm văn bằng/chứng chỉ.', 'Họ từ (Word Family): certify (v.), certificate (n.), certified (adj.)', '[{"hanzi":"The swimming instructor proudly showed us her new certification.","pinyin":"","meaning":"Nữ huấn luyện viên bơi lội tự hào khoe với chúng tôi chứng chỉ mới của cô ấy."},{"hanzi":"Independent certification helps consumers identify products that meet recognised environmental standards throughout the production process.","pinyin":"","meaning":"Chứng nhận độc lập giúp người tiêu dùng nhận diện các sản phẩm đáp ứng các tiêu chuẩn môi trường được công nhận trong suốt quá trình sản xuất."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_36_4', 'en-c1-36', 'Cách dùng “stationer” (n.) — nhà kinh doanh văn phòng phẩm; cửa hàng văn phòng phẩm', 'a local stationer  ·  a high-street stationer  ·  at the stationer''s', 'Cửa hàng văn phòng phẩm thường dùng stationer''s; stationery là văn phòng phẩm, đừng nhầm với stationary.', 'Họ từ (Word Family): stationery (n.)', '[{"hanzi":"The stationer helped me choose a notebook for school.","pinyin":"","meaning":"Người bán văn phòng phẩm đã giúp tôi chọn một cuốn vở cho trường học."},{"hanzi":"A local stationer may struggle to compete with online retailers offering cheaper office supplies.","pinyin":"","meaning":"Một cửa hàng văn phòng phẩm địa phương có thể gặp khó khăn trong việc cạnh tranh với các nhà bán lẻ trực tuyến cung cấp đồ dùng văn phòng giá rẻ hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_36_1', 'en-c1-36', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
