INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_1_2', 'ten_c1_36_1', 'meticulously', 'She meticulously cleaned each tiny part of the watch.', 'She meticulously cleaned each tiny part of the watch.', '/məˈtɪkjələsli/', 'Cô ấy đã lau chùi tỉ mỉ từng chi tiết nhỏ của chiếc đồng hồ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_1_3', 'ten_c1_36_1', 'facilitate', 'These sliding doors facilitate access for people using wheelchairs.', 'These sliding doors facilitate access for people using wheelchairs.', '/fəˈsɪlɪteɪt/', 'Những cánh cửa trượt này giúp cho người dùng xe lăn ra vào thuận lợi hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_1_4', 'ten_c1_36_1', 'dispatch', 'The shop dispatched my new shoes this morning.', 'The shop dispatched my new shoes this morning.', '/dɪˈspætʃ/', 'Cửa hàng đã gửi đôi giày mới của tôi đi vào sáng nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_1_5', 'ten_c1_36_1', 'certification', 'The swimming instructor proudly showed us her new certification.', 'The swimming instructor proudly showed us her new certification.', '/ˌsɝːtɪfɪˈkeɪʃən/', 'Nữ huấn luyện viên bơi lội tự hào khoe với chúng tôi chứng chỉ mới của cô ấy.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_1_6', 'ten_c1_36_1', 'requisite', 'She has the requisite skills to repair this bicycle.', 'She has the requisite skills to repair this bicycle.', '/ˈrekwɪzɪt/', 'Cô ấy có các kỹ năng cần thiết để sửa chiếc xe đạp này.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_1_7', 'ten_c1_36_1', 'custodian', 'The custodian carefully locked the cabinet containing ancient coins.', 'The custodian carefully locked the cabinet containing ancient coins.', '/kʌˈstoʊdiən/', 'Người bảo quản cẩn thận khóa chiếc tủ đựng tiền xu cổ lại.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_1_8', 'ten_c1_36_1', 'merge', 'The two narrow paths merge just beyond the bridge.', 'The two narrow paths merge just beyond the bridge.', '/mɝːdʒ/', 'Hai con đường nhỏ hợp nhất lại ngay phía bên kia cây cầu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_36_1_1', 'en-c1-36', 'ten_c1_36_1', 'listening', 'listening', 'Two concurrent meetings meant I had to choose one.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hai cuộc họp diễn ra đồng thời có nghĩa là tôi phải chọn một cái.","Cuối cùng chúng tôi cũng tìm mua được một linh kiện dự phòng cho chiếc lò nướng.","Anh ấy đã ghi chép rất tỉ mỉ trong lúc sửa chiếc đồng hồ cổ.","Máy rửa bát giúp giảm bớt rất nhiều sự vất vả và nhàm chán của việc dọn dẹp."]'::jsonb, 0, 'Two concurrent meetings meant I had to choose one. → Hai cuộc họp diễn ra đồng thời có nghĩa là tôi phải chọn một cái.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_36_1_2', 'en-c1-36', 'ten_c1_36_1', 'listening', 'listening', 'She meticulously cleaned each tiny part of the watch.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cuộc thảo luận của chúng tôi rơi vào bế tắc vì không ai chịu nhường nhau chuyện ai là người phải trả tiền.","Cô ấy đã lau chùi tỉ mỉ từng chi tiết nhỏ của chiếc đồng hồ.","Gỡ bỏ lớp giấy dán tường cũ là một công việc chậm chạp và tốn nhiều công sức.","Trưởng nhóm của chúng tôi đã gặp gỡ người đồng cấp đến từ một chi nhánh khác."]'::jsonb, 1, 'She meticulously cleaned each tiny part of the watch. → Cô ấy đã lau chùi tỉ mỉ từng chi tiết nhỏ của chiếc đồng hồ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_36_1_3', 'en-c1-36', 'ten_c1_36_1', 'listening', 'listening', 'These sliding doors facilitate access for people using wheelchairs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cửa hàng đã gửi đôi giày mới của tôi đi vào sáng nay.","Những cánh cửa trượt này giúp cho người dùng xe lăn ra vào thuận lợi hơn.","Máy rửa bát giúp giảm bớt rất nhiều sự vất vả và nhàm chán của việc dọn dẹp.","Cô ấy đã lau chùi tỉ mỉ từng chi tiết nhỏ của chiếc đồng hồ."]'::jsonb, 1, 'These sliding doors facilitate access for people using wheelchairs. → Những cánh cửa trượt này giúp cho người dùng xe lăn ra vào thuận lợi hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_36_2', 'en-c1-36', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_2_1', 'ten_c1_36_2', 'concurrent', 'Concurrent improvements in housing and public transport can make urban development more inclusive and sustainable.', 'Concurrent improvements in housing and public transport can make urban development more inclusive and sustainable.', '/kənˈkɜːrənt/', 'Việc đồng thời cải thiện nhà ở và giao thông công cộng có thể làm cho sự phát triển đô thị mang tính bao trùm và bền vững hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_2_2', 'ten_c1_36_2', 'meticulously', 'Researchers must meticulously record their procedures so that other teams can reproduce and verify the results.', 'Researchers must meticulously record their procedures so that other teams can reproduce and verify the results.', '/məˈtɪkjələsli/', 'Các nhà nghiên cứu phải ghi chép lại các quy trình một cách tỉ mỉ để các nhóm khác có thể tái hiện và kiểm chứng kết quả.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_2_3', 'ten_c1_36_2', 'facilitate', 'Digital platforms can facilitate collaboration between students in different countries, allowing them to exchange ideas more easily.', 'Digital platforms can facilitate collaboration between students in different countries, allowing them to exchange ideas more easily.', '/fəˈsɪlɪteɪt/', 'Các nền tảng kỹ thuật số có thể thúc đẩy sự hợp tác giữa học sinh sinh viên ở các quốc gia khác nhau, giúp họ trao đổi ý tưởng dễ dàng hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_2_4', 'ten_c1_36_2', 'dispatch', 'Local authorities should dispatch emergency teams quickly when severe flooding threatens homes and essential infrastructure.', 'Local authorities should dispatch emergency teams quickly when severe flooding threatens homes and essential infrastructure.', '/dɪˈspætʃ/', 'Chính quyền địa phương nên nhanh chóng phái các đội ứng phó khẩn cấp khi lũ lụt nghiêm trọng đe dọa nhà cửa và cơ sở hạ tầng thiết yếu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_2_5', 'ten_c1_36_2', 'certification', 'Independent certification helps consumers identify products that meet recognised environmental standards throughout the production process.', 'Independent certification helps consumers identify products that meet recognised environmental standards throughout the production process.', '/ˌsɝːtɪfɪˈkeɪʃən/', 'Chứng nhận độc lập giúp người tiêu dùng nhận diện các sản phẩm đáp ứng các tiêu chuẩn môi trường được công nhận trong suốt quá trình sản xuất.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_36_2_6', 'ten_c1_36_2', 'requisite', 'Applicants without the requisite qualifications may benefit from training programmes designed to improve access to skilled employment.', 'Applicants without the requisite qualifications may benefit from training programmes designed to improve access to skilled employment.', '/ˈrekwɪzɪt/', 'Những ứng viên thiếu trình độ chuyên môn cần thiết có thể hưởng lợi từ các chương trình đào tạo được thiết kế để giúp họ tiếp cận việc làm tay nghề cao hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_36_2_1', 'en-c1-36', 'ten_c1_36_2', 'listening', 'listening', 'Concurrent improvements in housing and public transport can make urban development more inclusive and sustainable.', NULL, 'Trong câu vừa nghe, từ “concurrent” mang nghĩa nào sau đây?', '["có tội; trái đạo đức; phạm giới","phủ lên nhau; chồng chéo lên nhau; có điểm chung","đồng thời; song song (xảy ra hoặc tồn tại cùng một lúc)","dầu hỏa; dầu hôi"]'::jsonb, 2, '“concurrent” (/kənˈkɜːrənt/): đồng thời; song song (xảy ra hoặc tồn tại cùng một lúc). Câu đầy đủ: Concurrent improvements in housing and public transport can make urban development more inclusive and sustainable.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_36_2_2', 'en-c1-36', 'ten_c1_36_2', 'listening', 'listening', 'Researchers must meticulously record their procedures so that other teams can reproduce and verify the results.', NULL, 'Trong câu vừa nghe, từ “meticulously” mang nghĩa nào sau đây?', '["tỉ mỉ; một cách kỹ lưỡng","chợ; khu mua sắm (nhiều cửa hàng/quầy hàng nhỏ)","sự loại bỏ; sự tiêu diệt","vòng hoa; vòng lá"]'::jsonb, 0, '“meticulously” (/məˈtɪkjələsli/): tỉ mỉ; một cách kỹ lưỡng. Câu đầy đủ: Researchers must meticulously record their procedures so that other teams can reproduce and verify the results.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
