INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_2', 'en-c1-36', NULL, 'comprehensive_test', 'listening', 'She meticulously cleaned each tiny part of the watch.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Kế hoạch đi dã ngoại rất đơn giản, nhưng việc thực hiện lại tỏ ra phức tạp.","Cô ấy đã lau chùi tỉ mỉ từng chi tiết nhỏ của chiếc đồng hồ.","Chúng tôi cố gắng trả lời mọi tin nhắn trước bữa tối.","Gỡ bỏ lớp giấy dán tường cũ là một công việc chậm chạp và tốn nhiều công sức."]'::jsonb, 1, 'She meticulously cleaned each tiny part of the watch. → Cô ấy đã lau chùi tỉ mỉ từng chi tiết nhỏ của chiếc đồng hồ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_3', 'en-c1-36', NULL, 'comprehensive_test', 'listening', 'facilitate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự cạn nước mắc cạn; vụ tai nạn mắc cạn","liên quan đến; gắn liền với; áp dụng cho","âm ấm; hơi ấm","làm cho thuận lợi; thúc đẩy; hỗ trợ"]'::jsonb, 3, 'facilitate (/fəˈsɪlɪteɪt/) → làm cho thuận lợi; thúc đẩy; hỗ trợ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_4', 'en-c1-36', NULL, 'comprehensive_test', 'listening', 'The shop dispatched my new shoes this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đã lau chùi tỉ mỉ từng chi tiết nhỏ của chiếc đồng hồ.","Người bảo quản cẩn thận khóa chiếc tủ đựng tiền xu cổ lại.","Cửa hàng đã gửi đôi giày mới của tôi đi vào sáng nay.","Mỗi thí sinh mang theo một chiếc bánh tự làm đến cuộc thi."]'::jsonb, 2, 'The shop dispatched my new shoes this morning. → Cửa hàng đã gửi đôi giày mới của tôi đi vào sáng nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_5', 'en-c1-36', NULL, 'comprehensive_test', 'listening', 'certification', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["không có mục đích, kế hoạch hoặc phương hướng rõ ràng","sự cấp giấy chứng nhận; chứng chỉ, văn bằng công nhận","được miễn; được miễn trừ","bức xạ; đối xử tàn nhược do tín ngưỡng hoặc thân phận"]'::jsonb, 1, 'certification (/ˌsɝːtɪfɪˈkeɪʃən/) → sự cấp giấy chứng nhận; chứng chỉ, văn bằng công nhận', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_6', 'en-c1-36', NULL, 'comprehensive_test', 'listening', 'She has the requisite skills to repair this bicycle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đã lau chùi tỉ mỉ từng chi tiết nhỏ của chiếc đồng hồ.","Hai con đường nhỏ hợp nhất lại ngay phía bên kia cây cầu.","Người bán văn phòng phẩm đã giúp tôi chọn một cuốn vở cho trường học.","Cô ấy có các kỹ năng cần thiết để sửa chiếc xe đạp này."]'::jsonb, 3, 'She has the requisite skills to repair this bicycle. → Cô ấy có các kỹ năng cần thiết để sửa chiếc xe đạp này.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_7', 'en-c1-36', NULL, 'comprehensive_test', 'listening', 'custodian', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["một bầy (gà con, chim non)","người bảo quản; người quản lý","công cộng; cộng đồng; nhóm người cùng sinh sống, chia sẻ tài sản và trách nhiệm","giếng (thang máy, thông gió); đường hầm thẳng đứng"]'::jsonb, 1, 'custodian (/kʌˈstoʊdiən/) → người bảo quản; người quản lý; nhân viên vệ sinh; người bảo trì tòa nhà', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_8', 'en-c1-36', NULL, 'comprehensive_test', 'listening', 'The two narrow paths merge just beyond the bridge.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người bán văn phòng phẩm đã giúp tôi chọn một cuốn vở cho trường học.","Người quản lý của chúng tôi đã nâng cao tỷ lệ giữ chân nhân viên bằng cách cung cấp thời gian làm việc linh hoạt.","Những cánh cửa trượt này giúp cho người dùng xe lăn ra vào thuận lợi hơn.","Hai con đường nhỏ hợp nhất lại ngay phía bên kia cây cầu."]'::jsonb, 3, 'The two narrow paths merge just beyond the bridge. → Hai con đường nhỏ hợp nhất lại ngay phía bên kia cây cầu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_9', 'en-c1-36', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Official confirmation that someone or something meets required standards.”?', '["certification","execution","counterpart","dispatch"]'::jsonb, 0, 'certification (/ˌsɝːtɪfɪˈkeɪʃən/) → sự cấp giấy chứng nhận; chứng chỉ, văn bằng công nhận', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_10', 'en-c1-36', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “needed for a particular purpose”?', '["execution","procure","requisite","retention"]'::jsonb, 2, 'requisite (/ˈrekwɪzɪt/) → cần thiết, thiết yếu cho một mục đích cụ thể', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_11', 'en-c1-36', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A person or organisation responsible for protecting or managing something.”?', '["counterpart","contractual","custodian","entrant"]'::jsonb, 2, 'custodian (/kʌˈstoʊdiən/) → người bảo quản; người quản lý', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_12', 'en-c1-36', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Combine or join together to form a single whole.”?', '["dispatch","merge","deadlock","custodian"]'::jsonb, 1, 'merge (/mɝːdʒ/) → hợp nhất; hòa nhập', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_13', 'en-c1-36', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A written message sharing information within an organisation”?', '["custodian","memorandum","stationer","contractual"]'::jsonb, 1, 'memorandum (/ˌmeməˈrændəm/) → bản ghi nhớ; thông cáo nội bộ', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
