INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_18', 'en-c1-36', NULL, 'comprehensive_test', 'reading', NULL, 'Concurrent improvements in housing and public transport can make urban development more inclusive and sustainable.', 'Dựa vào câu trên, từ “concurrent” có nghĩa phù hợp nhất là gì?', '["chăm chú; lắng nghe chăm chú","mang tính giải thích; mang tính minh họa","đồng thời; song song (xảy ra hoặc tồn tại cùng một lúc)","gây nguy hiểm; làm tổn hại; đe dọa"]'::jsonb, 2, 'concurrent: đồng thời; song song (xảy ra hoặc tồn tại cùng một lúc). Dịch cả câu: Việc đồng thời cải thiện nhà ở và giao thông công cộng có thể làm cho sự phát triển đô thị mang tính bao trùm và bền vững hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_19', 'en-c1-36', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers must meticulously record their procedures so that other teams can reproduce and verify the results.', 'Dựa vào câu trên, từ “meticulously” có nghĩa phù hợp nhất là gì?', '["tỉ mỉ; một cách kỹ lưỡng","hải cảng; eo biển","quan trọng hàng đầu; tối quan trọng; cao nhất","xác định phương hướng; làm quen với môi trường xung quanh"]'::jsonb, 0, 'meticulously: tỉ mỉ; một cách kỹ lưỡng. Dịch cả câu: Các nhà nghiên cứu phải ghi chép lại các quy trình một cách tỉ mỉ để các nhóm khác có thể tái hiện và kiểm chứng kết quả.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_20', 'en-c1-36', NULL, 'comprehensive_test', 'reading', NULL, 'Digital platforms can facilitate collaboration between students in different countries, allowing them to exchange ideas more easily.', 'Dựa vào câu trên, từ “facilitate” có nghĩa phù hợp nhất là gì?', '["làm cho thuận lợi; thúc đẩy; hỗ trợ","chấm dứt; kết thúc","sợi mảnh; cấu trúc dạng sợi","gợn sóng; sóng lăn tăn"]'::jsonb, 0, 'facilitate: làm cho thuận lợi; thúc đẩy; hỗ trợ. Dịch cả câu: Các nền tảng kỹ thuật số có thể thúc đẩy sự hợp tác giữa học sinh sinh viên ở các quốc gia khác nhau, giúp họ trao đổi ý tưởng dễ dàng hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_21', 'en-c1-36', NULL, 'comprehensive_test', 'reading', NULL, 'Local authorities should dispatch emergency teams quickly when severe flooding threatens homes and essential infrastructure.', 'Dựa vào câu trên, từ “dispatch” có nghĩa phù hợp nhất là gì?', '["quay; chuyển động theo vòng tròn; chạy bằng cơ chế quay","gửi, phái (ai hoặc cái gì đi đến một địa điểm cụ thể)","có hiệu lực mạnh; có sức ảnh hưởng lớn","giải mã; nhận diện; đọc hiểu"]'::jsonb, 1, 'dispatch: gửi, phái (ai hoặc cái gì đi đến một địa điểm cụ thể); sự gửi đi, sự phái đi (hàng hóa, tin nhắn hoặc con người); bản tin chính thức; bài tường thuật của phóng viên. Dịch cả câu: Chính quyền địa phương nên nhanh chóng phái các đội ứng phó khẩn cấp khi lũ lụt nghiêm trọng đe dọa nhà cửa và cơ sở hạ tầng thiết yếu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_22', 'en-c1-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “công việc vất vả, nhàm chán và lặp đi lặp lại”', '["recitation","drudgery","pulp","artery"]'::jsonb, 1, 'công việc vất vả, nhàm chán và lặp đi lặp lại → drudgery (/ˈdrʌdʒəri/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_23', 'en-c1-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dự án kinh doanh rủi ro; công ty liên doanh”', '["Orthodox","designation","venture","thereafter"]'::jsonb, 2, 'dự án kinh doanh rủi ro; công ty liên doanh → venture (/ˈventʃər/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_36_24', 'en-c1-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “người hoặc vật tương đương, có cùng vai trò ở một bối cảnh khác”', '["counterpart","legitimate","incline","spherical"]'::jsonb, 0, 'người hoặc vật tương đương, có cùng vai trò ở một bối cảnh khác → counterpart (/ˈkaʊntərpɑːrt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-37', 'en', 'Bài 37: Công việc & Nghề nghiệp (2) - CEFR C1', 'CEFR C1', 'C1 · Công việc', '25 từ vựng Tiếng Anh CEFR C1 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5037, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advantageous', 'en-c1-37', 'advantageous', '/ˌædvənˈteɪdʒəs/', 'C1', 'có lợi; thuận lợi; hữu ích', 'adj.', 'advantage (n.), disadvantage (n.), disadvantageous (adj.)', 'Đồng nghĩa: beneficial, favourable · Trái nghĩa: disadvantageous, unfavourable', 'Thường dùng cấu trúc be advantageous to sb để chỉ điều gì có lợi cho ai.', 'Booking early was advantageous because we got cheaper tickets.', NULL, 'Đặt vé sớm rất có lợi vì chúng tôi mua được vé rẻ hơn.', '{"wordId":"advantageous","ukIpa":"/ˌædvənˈteɪdʒəs/","usIpa":"/ˌædvənˈteɪdʒəs/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Giving benefits or improving the chances of success","vi":"có lợi; thuận lợi; hữu ích"}],"examples":[{"en":"Booking early was advantageous because we got cheaper tickets.","vi":"Đặt vé sớm rất có lợi vì chúng tôi mua được vé rẻ hơn.","audioKind":"ex"},{"en":"Flexible working arrangements can be advantageous to employers by improving staff satisfaction and reducing employee turnover.","vi":"Các thỏa thuận làm việc linh hoạt có thể mang lại lợi ích cho người sử dụng lao động bằng cách nâng cao sự hài lòng của nhân viên và giảm tỷ lệ nghỉ việc.","audioKind":"ex2"}],"collocations":[{"en":"advantageous to someone","vi":"có lợi cho ai đó"},{"en":"mutually advantageous","vi":"cùng có lợi; đôi bên cùng có lợi"},{"en":"advantageous position","vi":"vị thế thuận lợi"}],"wordFamily":["advantage (n.)","disadvantage (n.)","disadvantageous (adj.)"],"synonyms":["beneficial","favourable"],"antonyms":["disadvantageous","unfavourable"],"tipVi":"Thường dùng cấu trúc be advantageous to sb để chỉ điều gì có lợi cho ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_certify', 'en-c1-37', 'certify', '/ˈsɝːtɪfaɪ/', 'C1', 'chứng nhận; cấp giấy chứng nhận; xác nhận chính thức', 'v.', 'certificate (n.), certification (n.), certified (adj.)', 'Đồng nghĩa: verify, confirm', 'Nhấn mạnh tính chính thức hoặc thẩm quyền xác thực, thường đi với mệnh đề certify that.', 'An engineer certified that our new boiler was safe.', NULL, 'Một kỹ sư đã xác nhận rằng chiếc lò hơi mới của chúng tôi hoàn toàn an toàn.', '{"wordId":"certify","ukIpa":"/ˈsɜːtɪfaɪ/","usIpa":"/ˈsɝːtɪfaɪ/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to confirm officially that something is true or meets standards","vi":"chứng nhận; cấp giấy chứng nhận; xác nhận chính thức"}],"examples":[{"en":"An engineer certified that our new boiler was safe.","vi":"Một kỹ sư đã xác nhận rằng chiếc lò hơi mới của chúng tôi hoàn toàn an toàn.","audioKind":"ex"},{"en":"Independent organisations certify that certain products meet environmental standards, helping consumers make more informed purchasing decisions.","vi":"Các tổ chức độc lập chứng nhận rằng một số sản phẩm đáp ứng tiêu chuẩn môi trường, giúp người tiêu dùng đưa ra quyết định mua sắm có hiểu biết hơn.","audioKind":"ex2"}],"collocations":[{"en":"certify that","vi":"chứng nhận rằng"},{"en":"certify as safe","vi":"chứng nhận là an toàn"},{"en":"certified organic","vi":"được chứng nhận hữu ích/hữu cơ"}],"wordFamily":["certificate (n.)","certification (n.)","certified (adj.)"],"synonyms":["verify","confirm"],"antonyms":[],"tipVi":"Nhấn mạnh tính chính thức hoặc thẩm quyền xác thực, thường đi với mệnh đề certify that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overextend', 'en-c1-37', 'overextend', '/ˌoʊvərɪkˈstend/', 'C1', 'làm cho quá sức; vươn quá tầm; dùng quá mức', 'v.', 'overextension (n.), extend (v.), extension (n.)', 'Đồng nghĩa: overburden, overstretch', 'Thường đi với đại từ phản thân thành overextend oneself, chỉ việc nhận lấy nhiệm vụ hoặc chi tiêu vượt quá năng lực.', 'Don''t overextend yourself by joining every club at school.', NULL, 'Đừng tự làm mình quá sức bằng cách tham gia mọi câu lạc bộ ở trường.', '{"wordId":"overextend","ukIpa":"/ˌəʊvərɪkˈstend/","usIpa":"/ˌoʊvərɪkˈstend/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to commit more money or effort than can be managed","vi":"làm cho quá sức; vươn quá tầm; dùng quá mức"}],"examples":[{"en":"Don''t overextend yourself by joining every club at school.","vi":"Đừng tự làm mình quá sức bằng cách tham gia mọi câu lạc bộ ở trường.","audioKind":"ex"},{"en":"Small businesses may overextend themselves financially when they expand rapidly without assessing future demand.","vi":"Các doanh nghiệp nhỏ có thể tự đặt mình vào thế tài chính quá sức khi mở rộng quy mô quá nhanh mà không đánh giá trước nhu cầu tương lai.","audioKind":"ex2"}],"collocations":[{"en":"overextend yourself","vi":"tự làm quá sức"},{"en":"overextend financially","vi":"vượt quá khả năng tài chính"},{"en":"overextend resources","vi":"sử dụng nguồn lực quá mức"}],"wordFamily":["overextension (n.)","extend (v.)","extension (n.)"],"synonyms":["overburden","overstretch"],"antonyms":[],"tipVi":"Thường đi với đại từ phản thân thành overextend oneself, chỉ việc nhận lấy nhiệm vụ hoặc chi tiêu vượt quá năng lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oversight', 'en-c1-37', 'oversight', '/ˈoʊvərsaɪt/', 'C1', 'sự sơ suất; sự sai sót do sơ suất; sự giám sát; sự quản lý', 'n.', 'oversee (v.), overseer (n.)', NULL, 'Nghĩa là "sơ suất" thường đếm được; nghĩa là "giám sát" thường không đếm được.', 'Through an oversight, I left your lunch at home.', NULL, 'Do sơ suất, tôi đã để quên bữa trưa của bạn ở nhà.', '{"wordId":"oversight","ukIpa":"/ˈəʊvəsaɪt/","usIpa":"/ˈoʊvərsaɪt/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A mistake caused by failing to notice or consider something.","vi":"sự sơ suất; sự sai sót do sơ suất"},{"pos":"n.","en":"Responsibility for checking that activities are managed correctly.","vi":"sự giám sát; sự quản lý"}],"examples":[{"en":"Through an oversight, I left your lunch at home.","vi":"Do sơ suất, tôi đã để quên bữa trưa của bạn ở nhà.","audioKind":"ex"},{"en":"Independent oversight of public spending can reduce corruption and strengthen citizens'' confidence in government institutions.","vi":"Sự giám sát độc lập đối với chi tiêu công có thể làm giảm tham nhũng và củng cố niềm tin của người dân vào các cơ quan chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"an unfortunate oversight","vi":"một sự sơ suất đáng tiếc"},{"en":"by an oversight","vi":"do sơ suất"},{"en":"independent oversight","vi":"sự giám sát độc lập"},{"en":"regulatory oversight","vi":"sự quản lý quy định"}],"wordFamily":["oversee (v.)","overseer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa là \"sơ suất\" thường đếm được; nghĩa là \"giám sát\" thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_redundant', 'en-c1-37', 'redundant', '/rɪˈdʌndənt/', 'C1', 'thừa thãi; không cần thiết; dư thừa; bị sa thải (do mất việc hoặc cắt giảm biên chế)', 'adj.', 'redundancy (n.)', 'Đồng nghĩa: unnecessary, superfluous · Trái nghĩa: necessary, essential', 'Trong tiếng Anh Anh, cụm be made redundant chỉ việc bị mất việc do vị trí công tác bị cắt giảm.', 'This spare cable is redundant now we use wireless speakers.', NULL, 'Cọng cáp dự phòng này nay đã thừa thãi vì chúng ta dùng loa không dây.', '{"wordId":"redundant","ukIpa":"/rɪˈdʌndənt/","usIpa":"/rɪˈdʌndənt/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"unnecessary because it is no longer needed or repeats something","vi":"thừa thãi; không cần thiết; dư thừa"},{"pos":"adj.","en":"having lost a job because the employer no longer needs it","vi":"bị sa thải (do mất việc hoặc cắt giảm biên chế)"}],"examples":[{"en":"This spare cable is redundant now we use wireless speakers.","vi":"Cọng cáp dự phòng này nay đã thừa thãi vì chúng ta dùng loa không dây.","audioKind":"ex"},{"en":"Factory workers may be made redundant when automated systems take over tasks previously performed by people.","vi":"Công nhân nhà máy có thể bị sa thải khi các hệ thống tự động tiếp quản các công việc trước đây do con người thực hiện.","audioKind":"ex2"}],"collocations":[{"en":"make someone redundant","vi":"sa thải ai đó"},{"en":"redundant information","vi":"thông tin dư thừa"},{"en":"become redundant","vi":"trở nên không cần thiết"}],"wordFamily":["redundancy (n.)"],"synonyms":["unnecessary","superfluous"],"antonyms":["necessary","essential"],"tipVi":"Trong tiếng Anh Anh, cụm be made redundant chỉ việc bị mất việc do vị trí công tác bị cắt giảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_know-how', 'en-c1-37', 'know-how', '/ˈnoʊ haʊ/', 'C1', 'bí quyết kỹ thuật; kỹ năng thực tế', 'n.', NULL, 'Đồng nghĩa: expertise', 'Danh từ không đếm được, nhấn mạnh năng lực thực hành, cách viết có gạch nối.', 'My uncle has the know-how to repair old bicycles.', NULL, 'Chú tôi có kỹ thuật để sửa những chiếc xe đạp cũ.', '{"wordId":"know-how","ukIpa":"/ˈnəʊ haʊ/","usIpa":"/ˈnoʊ haʊ/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Practical knowledge and skills needed to do something successfully","vi":"bí quyết kỹ thuật; kỹ năng thực tế"}],"examples":[{"en":"My uncle has the know-how to repair old bicycles.","vi":"Chú tôi có kỹ thuật để sửa những chiếc xe đạp cũ.","audioKind":"ex"},{"en":"Sharing technical know-how can help small businesses adopt cleaner production methods without relying entirely on outside consultants.","vi":"Chia sẻ bí quyết kỹ thuật có thể giúp các doanh nghiệp nhỏ áp dụng phương pháp sản xuất sạch hơn mà không phải hoàn toàn phụ thuộc vào chuyên gia tư vấn bên ngoài.","audioKind":"ex2"}],"collocations":[{"en":"technical know-how","vi":"bí quyết kỹ thuật"},{"en":"practical know-how","vi":"kỹ năng thực tế"},{"en":"transfer know-how","vi":"chuyển giao công nghệ"}],"wordFamily":[],"synonyms":["expertise"],"antonyms":[],"tipVi":"Danh từ không đếm được, nhấn mạnh năng lực thực hành, cách viết có gạch nối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transferable', 'en-c1-37', 'transferable', '/trænsˈfɝːəbəl/', 'C1', 'có thể chuyển nhượng; có thể chuyển giao; có thể áp dụng vào nhiều công việc hoặc tình huống khác nhau', 'adj.', 'transfer (v.), transfer (n.), non-transferable (adj.)', 'Trái nghĩa: non-transferable', '"transferable skills" chỉ những kỹ năng vẫn áp dụng được khi chuyển đổi vị trí công việc hoặc ngành nghề.', 'These tickets are transferable, so your sister can use mine.', NULL, 'Những tấm vé này có thể chuyển nhượng được, vì vậy chị gái bạn có thể dùng vé của tôi.', '{"wordId":"transferable","ukIpa":"/trænsˈfɜːrəbəl/","usIpa":"/trænsˈfɝːəbəl/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"able to be moved or passed to another person or place","vi":"có thể chuyển nhượng; có thể chuyển giao"},{"pos":"adj.","en":"useful in different jobs or situations","vi":"có thể áp dụng vào nhiều công việc hoặc tình huống khác nhau"}],"examples":[{"en":"These tickets are transferable, so your sister can use mine.","vi":"Những tấm vé này có thể chuyển nhượng được, vì vậy chị gái bạn có thể dùng vé của tôi.","audioKind":"ex"},{"en":"Universities should help students develop transferable skills that remain valuable across different industries and careers.","vi":"Các trường đại học nên giúp sinh viên phát triển những kỹ năng có thể chuyển đổi, vốn luôn có giá trị trong nhiều ngành nghề và sự nghiệp khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"transferable skills","vi":"kỹ năng có thể chuyển đổi"},{"en":"transferable ticket","vi":"vé có thể chuyển nhượng"},{"en":"transferable knowledge","vi":"kiến thức có thể áp dụng rộng rãi"}],"wordFamily":["transfer (v.)","transfer (n.)","non-transferable (adj.)"],"synonyms":[],"antonyms":["non-transferable"],"tipVi":"\"transferable skills\" chỉ những kỹ năng vẫn áp dụng được khi chuyển đổi vị trí công việc hoặc ngành nghề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lieutenant', 'en-c1-37', 'lieutenant', '/luːˈtenənt/', 'C1', 'trung úy (lục quân); đại úy (hải quân); sĩ quan cấp dưới; phó tá; trợ lý đắc lực', 'n.', NULL, NULL, 'Tiếng Anh-Anh đọc âm đầu là /lef/, tiếng Anh-Mỹ đọc là /luː/; tên gọi quân hàm thay đổi tùy theo quân chủng.', 'The lieutenant helped the new soldiers organise their equipment.', NULL, 'Vị trung úy đã giúp các tân binh sắp xếp trang thiết bị của họ.', '{"wordId":"lieutenant","ukIpa":"/lefˈtenənt/","usIpa":"/luːˈtenənt/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"An officer holding a junior rank in the armed forces","vi":"trung úy (lục quân); đại úy (hải quân); sĩ quan cấp dưới"},{"pos":"n.","en":"A trusted assistant who helps a leader manage important work","vi":"phó tá; trợ lý đắc lực"}],"examples":[{"en":"The lieutenant helped the new soldiers organise their equipment.","vi":"Vị trung úy đã giúp các tân binh sắp xếp trang thiết bị của họ.","audioKind":"ex"},{"en":"During disaster relief operations, a lieutenant may coordinate military teams delivering essential supplies to isolated communities.","vi":"Trong các chiến dịch cứu trợ thiên tai, một trung úy có thể điều phối các đội quân sự vận chuyển nhu yếu phẩm đến những cộng đồng bị cô lập.","audioKind":"ex2"}],"collocations":[{"en":"army lieutenant","vi":"trung úy lục quân"},{"en":"naval lieutenant","vi":"đại úy hải quân"},{"en":"trusted lieutenant","vi":"trợ lý đáng tin cậy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh đọc âm đầu là /lef/, tiếng Anh-Mỹ đọc là /luː/; tên gọi quân hàm thay đổi tùy theo quân chủng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_workmanship', 'en-c1-37', 'workmanship', '/ˈwɝːkmənʃɪp/', 'C1', 'tay nghề; chất lượng gia công', 'n.', NULL, 'Đồng nghĩa: craftsmanship', 'Danh từ không đếm được, nhấn mạnh chất lượng hoàn thiện của thành phẩm chứ không phải thái độ làm việc.', 'The smooth wooden joints reveal the chair''s excellent workmanship.', NULL, 'Các mối nối gỗ mượt mà cho thấy tay nghề tinh xảo của chiếc ghế.', '{"wordId":"workmanship","ukIpa":"/ˈwɜːkmənʃɪp/","usIpa":"/ˈwɝːkmənʃɪp/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"The skill and quality shown in making something.","vi":"tay nghề; chất lượng gia công"}],"examples":[{"en":"The smooth wooden joints reveal the chair''s excellent workmanship.","vi":"Các mối nối gỗ mượt mà cho thấy tay nghề tinh xảo của chiếc ghế.","audioKind":"ex"},{"en":"Consumers may accept higher prices when products demonstrate superior workmanship and offer a longer useful life.","vi":"Người tiêu dùng có thể chấp nhận mức giá cao hơn khi sản phẩm thể hiện chất lượng chế tác vượt trội và có độ bền cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"fine workmanship","vi":"tay nghề tinh xảo"},{"en":"poor workmanship","vi":"chất lượng làm kém"},{"en":"quality workmanship","vi":"kỹ thuật chế tác chất lượng cao"}],"wordFamily":[],"synonyms":["craftsmanship"],"antonyms":[],"tipVi":"Danh từ không đếm được, nhấn mạnh chất lượng hoàn thiện của thành phẩm chứ không phải thái độ làm việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_administer', 'en-c1-37', 'administer', '/ədˈmɪnɪstər/', 'C1', 'quản lý; điều hành; thi hành; cấp phát (thuốc); thực hiện việc điều trị y tế', 'v.', 'administration (n.), administrator (n.), administrative (adj.)', 'Đồng nghĩa: manage', 'Cấu trúc cho thuốc ai đó có thể dùng administer medicine to someone.', 'The nurse administered the medicine before I went home.', NULL, 'Y tá đã cho tôi uống thuốc trước khi tôi về nhà.', '{"wordId":"administer","ukIpa":"/ədˈmɪnɪstə/","usIpa":"/ədˈmɪnɪstər/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to manage an organization or put a system into operation","vi":"quản lý; điều hành; thi hành"},{"pos":"v.","en":"to give someone medicine or medical treatment","vi":"cấp phát (thuốc); thực hiện việc điều trị y tế"}],"examples":[{"en":"The nurse administered the medicine before I went home.","vi":"Y tá đã cho tôi uống thuốc trước khi tôi về nhà.","audioKind":"ex"},{"en":"Local authorities administer housing programmes designed to provide affordable accommodation for families on low incomes.","vi":"Chính quyền địa phương quản lý các chương trình nhà ở nhằm cung cấp chỗ ở vừa túi tiền cho các hộ gia đình thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"administer a programme","vi":"quản lý một chương trình"},{"en":"administer medication","vi":"cấp phát thuốc"},{"en":"administer first aid","vi":"sơ cứu"},{"en":"administer a test","vi":"tổ chức một bài kiểm tra"}],"wordFamily":["administration (n.)","administrator (n.)","administrative (adj.)"],"synonyms":["manage"],"antonyms":[],"tipVi":"Cấu trúc cho thuốc ai đó có thể dùng administer medicine to someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seaman', 'en-c1-37', 'seaman', '/ˈsiːmən/', 'C1', 'hải quân; thủy thủ; hải đăng', 'n.', 'seamanship (n.)', 'Đồng nghĩa: sailor, seafarer', 'Dạng số nhiều là seamen; seafarer là từ trung lập về giới tính thường được dùng phổ biến hơn.', 'The experienced seaman checked the ropes before the ship departed.', NULL, 'Người thủy thủ giàu kinh nghiệm đã kiểm tra các dây thừng trước khi con tàu khởi hành.', '{"wordId":"seaman","ukIpa":"/ˈsiːmən/","usIpa":"/ˈsiːmən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A person who works on a ship at sea.","vi":"hải quân; thủy thủ; hải đăng"}],"examples":[{"en":"The experienced seaman checked the ropes before the ship departed.","vi":"Người thủy thủ giàu kinh nghiệm đã kiểm tra các dây thừng trước khi con tàu khởi hành.","audioKind":"ex"},{"en":"Every seaman should receive practical safety training before joining a crew on an international shipping route.","vi":"Mỗi thủy thủ cần phải được đào tạo an toàn thực tế trước khi gia nhập đội ngũ thủy thủ đoàn trên tuyến hàng hải quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"an experienced seaman","vi":"thủy thủ giàu kinh nghiệm"},{"en":"a merchant seaman","vi":"thủy thủ tàu buôn"},{"en":"an able seaman","vi":"thủy thủ thành thạo"}],"wordFamily":["seamanship (n.)"],"synonyms":["sailor","seafarer"],"antonyms":[],"tipVi":"Dạng số nhiều là seamen; seafarer là từ trung lập về giới tính thường được dùng phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arduous', 'en-c1-37', 'arduous', '/ˈɑːrdʒuəs/', 'C1', 'gian khổ; gian nan; đòi hỏi nhiều nỗ lực', 'adj.', 'arduously (adv.), arduousness (n.)', 'Đồng nghĩa: demanding, strenuous, grueling · Trái nghĩa: easy, effortless', 'Nhấn mạnh sự tốn kém công sức trong thời gian dài, thường đi kèm với các danh từ như task, journey, process.', 'The arduous climb left us exhausted but deeply satisfied.', NULL, 'Chuyến leo núi gian khổ khiến chúng tôi kiệt sức nhưng vô cùng mãn nguyện.', '{"wordId":"arduous","ukIpa":"/ˈɑːdjuəs/","usIpa":"/ˈɑːrdʒuəs/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"requiring considerable effort and sustained hard work","vi":"gian khổ; gian nan; đòi hỏi nhiều nỗ lực"}],"examples":[{"en":"The arduous climb left us exhausted but deeply satisfied.","vi":"Chuyến leo núi gian khổ khiến chúng tôi kiệt sức nhưng vô cùng mãn nguyện.","audioKind":"ex"},{"en":"Restoring damaged ecosystems is an arduous process that requires sustained investment and cooperation between scientists and local communities.","vi":"Việc phục hồi các hệ sinh thái bị tổn hại là một quá trình gian nan đòi hỏi nguồn đầu tư bền bỉ và sự hợp tác giữa các nhà khoa học và cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"an arduous task","vi":"nhiệm vụ gian khổ"},{"en":"an arduous journey","vi":"hành trình gian nan"},{"en":"an arduous process","vi":"quá trình đầy thử thách"}],"wordFamily":["arduously (adv.)","arduousness (n.)"],"synonyms":["demanding","strenuous","grueling"],"antonyms":["easy","effortless"],"tipVi":"Nhấn mạnh sự tốn kém công sức trong thời gian dài, thường đi kèm với các danh từ như task, journey, process.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commence', 'en-c1-37', 'commence', '/kəˈmens/', 'C1', 'bắt đầu; khởi đầu', 'v.', 'commencement (n.)', 'Đồng nghĩa: begin, start · Trái nghĩa: finish, end', 'Trang trọng hơn start; có thể đi với danh từ hoặc danh động từ.', 'The evening concert will commence after a short welcome.', NULL, 'Buổi hòa nhạc buổi tối sẽ bắt đầu sau một lời chào ngắn gọn.', '{"wordId":"commence","ukIpa":"/kəˈmens/","usIpa":"/kəˈmens/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to begin something or start happening","vi":"bắt đầu; khởi đầu"}],"examples":[{"en":"The evening concert will commence after a short welcome.","vi":"Buổi hòa nhạc buổi tối sẽ bắt đầu sau một lời chào ngắn gọn.","audioKind":"ex"},{"en":"Construction of the new railway will commence once the environmental assessment has been completed.","vi":"Việc xây dựng tuyến đường sắt mới sẽ được khởi công ngay khi quá trình đánh giá môi trường hoàn tất.","audioKind":"ex2"}],"collocations":[{"en":"commence work","vi":"bắt đầu công việc"},{"en":"commence proceedings","vi":"tiến hành thủ tục tố tụng"},{"en":"commence with","vi":"bắt đầu với"}],"wordFamily":["commencement (n.)"],"synonyms":["begin","start"],"antonyms":["finish","end"],"tipVi":"Trang trọng hơn start; có thể đi với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_undertaking', 'en-c1-37', 'undertaking', '/ˌʌndərˈteɪkɪŋ/', 'C1', 'nhiệm vụ lớn; công việc lớn; dự án lớn; lời hứa chính thức; cam kết', 'n.', 'undertake (v.)', 'Đồng nghĩa: enterprise, project, pledge', 'Khi mang nghĩa "cam kết", thường dùng cấu trúc "give an undertaking to do".', 'Renovating this old house is a much bigger undertaking.', NULL, 'Việc tân trang lại ngôi nhà cũ này là một công việc lớn hơn nhiều.', '{"wordId":"undertaking","ukIpa":"/ˌʌndəˈteɪkɪŋ/","usIpa":"/ˌʌndərˈteɪkɪŋ/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A task or project, especially one requiring considerable effort.","vi":"nhiệm vụ lớn; công việc lớn; dự án lớn"},{"pos":"n.","en":"A formal promise to do something.","vi":"lời hứa chính thức; cam kết"}],"examples":[{"en":"Renovating this old house is a much bigger undertaking.","vi":"Việc tân trang lại ngôi nhà cũ này là một công việc lớn hơn nhiều.","audioKind":"ex"},{"en":"Building a nationwide railway network is a major undertaking that requires sustained investment and careful planning.","vi":"Xây dựng mạng lưới đường sắt toàn quốc là một dự án lớn đòi hỏi nguồn đầu tư liên tục và kế hoạch chu đáo.","audioKind":"ex2"}],"collocations":[{"en":"a major undertaking","vi":"một nhiệm vụ lớn"},{"en":"a joint undertaking","vi":"một dự án chung"},{"en":"give an undertaking","vi":"đưa ra cam kết"}],"wordFamily":["undertake (v.)"],"synonyms":["enterprise","project","pledge"],"antonyms":[],"tipVi":"Khi mang nghĩa \"cam kết\", thường dùng cấu trúc \"give an undertaking to do\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aspiration', 'en-c1-37', 'aspiration', '/ˌæspəˈreɪʃən/', 'C1', 'khát vọng; hoài bão; nguyện vọng; sự phát âm có hơi gió', 'n.', 'aspire (v.), aspiring (adj.), aspirational (adj.)', 'Đồng nghĩa: ambition, goal', 'Nghĩa khát vọng thường dùng ở dạng số nhiều; cụm "aspiration to do" dùng để chỉ mong ước làm việc gì.', 'Her greatest aspiration is to open a small bakery.', NULL, 'Khát vọng lớn nhất của cô ấy là mở một tiệm bánh nhỏ.', '{"wordId":"aspiration","ukIpa":"/ˌæspəˈreɪʃən/","usIpa":"/ˌæspəˈreɪʃən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A strong hope or ambition to achieve something.","vi":"khát vọng; hoài bão; nguyện vọng"},{"pos":"n.","en":"A breath of air released when pronouncing certain speech sounds.","vi":"sự phát âm có hơi gió"}],"examples":[{"en":"Her greatest aspiration is to open a small bakery.","vi":"Khát vọng lớn nhất của cô ấy là mở một tiệm bánh nhỏ.","audioKind":"ex"},{"en":"Access to affordable higher education can help young people fulfil their aspirations, regardless of their family income.","vi":"Việc tiếp cận giáo dục đại học với mức học phí phải chăng có thể giúp người trẻ hiện thực hóa hoài bão của mình, bất kể thu nhập gia đình ra sao.","audioKind":"ex2"}],"collocations":[{"en":"career aspirations","vi":"hoài bão nghề nghiệp"},{"en":"fulfil an aspiration","vi":"hiện thực hóa khát vọng"},{"en":"aspiration to succeed","vi":"khát vọng vươn lên thành công"}],"wordFamily":["aspire (v.)","aspiring (adj.)","aspirational (adj.)"],"synonyms":["ambition","goal"],"antonyms":[],"tipVi":"Nghĩa khát vọng thường dùng ở dạng số nhiều; cụm \"aspiration to do\" dùng để chỉ mong ước làm việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conscientiously', 'en-c1-37', 'conscientiously', '/ˌkɑːnʃiˈenʃəsli/', 'C1', 'chu đáo; tận tâm; có trách nhiệm', 'adv.', 'conscientious (adj.), conscientiousness (n.), conscience (n.)', 'Đồng nghĩa: diligently, meticulously · Trái nghĩa: carelessly, negligently', 'Nhấn mạnh tinh thần trách nhiệm và sự cẩn trọng cao độ, không chỉ là hành động làm việc từ tốn.', 'The nurse conscientiously checked every item in the kit.', NULL, 'Cô y tá đã kiểm tra cẩn thận từng món đồ trong bộ dụng cụ.', '{"wordId":"conscientiously","ukIpa":"/ˌkɒnʃiˈenʃəsli/","usIpa":"/ˌkɑːnʃiˈenʃəsli/","cefr":"C1","topic":"work","senses":[{"pos":"adv.","en":"With care and a strong sense of responsibility.","vi":"chu đáo; tận tâm; có trách nhiệm"}],"examples":[{"en":"The nurse conscientiously checked every item in the kit.","vi":"Cô y tá đã kiểm tra cẩn thận từng món đồ trong bộ dụng cụ.","audioKind":"ex"},{"en":"Teachers who conscientiously review individual progress can identify learning difficulties before students fall significantly behind.","vi":"Những giáo viên tận tâm đánh giá sát sao tiến bộ của từng học sinh có thể phát hiện ra khó khăn học tập trước khi các em bị tụt lại phía sau quá xa.","audioKind":"ex2"}],"collocations":[{"en":"work conscientiously","vi":"làm việc tận tụy"},{"en":"conscientiously carry out duties","vi":"thực hiện trách nhiệm một cách chu đáo"}],"wordFamily":["conscientious (adj.)","conscientiousness (n.)","conscience (n.)"],"synonyms":["diligently","meticulously"],"antonyms":["carelessly","negligently"],"tipVi":"Nhấn mạnh tinh thần trách nhiệm và sự cẩn trọng cao độ, không chỉ là hành động làm việc từ tốn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tedious', 'en-c1-37', 'tedious', '/ˈtiːdiəs/', 'C1', 'nhàm chán; tẻ nhạt; đơn điệu', 'adj.', 'tedium (n.), tediously (adv.), tediousness (n.)', 'Đồng nghĩa: boring, monotonous, wearisome · Trái nghĩa: engaging, stimulating', 'Thường dùng để mô tả những công việc gây chán nản vì kéo dài quá lâu hoặc lặp đi lặp lại.', 'Sorting all these old receipts is a tedious job.', NULL, 'Phân loại tất cả mấy cái hóa đơn cũ này là một công việc thật tẻ nhạt.', '{"wordId":"tedious","ukIpa":"/ˈtiːdiəs/","usIpa":"/ˈtiːdiəs/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"boring because it continues too long or involves repeated actions","vi":"nhàm chán; tẻ nhạt; đơn điệu"}],"examples":[{"en":"Sorting all these old receipts is a tedious job.","vi":"Phân loại tất cả mấy cái hóa đơn cũ này là một công việc thật tẻ nhạt.","audioKind":"ex"},{"en":"Automation can free employees from tedious tasks, allowing them to focus on more creative and rewarding work.","vi":"Tự động hóa có thể giúp nhân viên thoát khỏi những công việc nhàm chán, cho phép họ tập trung vào những nhiệm vụ sáng tạo và mang lại nhiều giá trị hơn.","audioKind":"ex2"}],"collocations":[{"en":"tedious task","vi":"công việc tẻ nhạt"},{"en":"tedious process","vi":"quá trình dài dòng mệt mỏi"},{"en":"tedious paperwork","vi":"công việc giấy tờ rườm rà"}],"wordFamily":["tedium (n.)","tediously (adv.)","tediousness (n.)"],"synonyms":["boring","monotonous","wearisome"],"antonyms":["engaging","stimulating"],"tipVi":"Thường dùng để mô tả những công việc gây chán nản vì kéo dài quá lâu hoặc lặp đi lặp lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appraise', 'en-c1-37', 'appraise', '/əˈpreɪz/', 'C1', 'đánh giá; định giá chất lượng, tình trạng hoặc hiệu suất; thẩm định; ước tính giá trị tiền bạc', 'v.', 'appraisal (n.), appraiser (n.)', 'Đồng nghĩa: assess, evaluate', 'appraise là đánh giá; đừng nhầm lẫn với apprise (thông báo).', 'The coach appraised my technique and suggested some changes.', NULL, 'Huấn luyện viên đã đánh giá kỹ thuật của tôi và đưa ra một số gợi ý thay đổi.', '{"wordId":"appraise","ukIpa":"/əˈpreɪz/","usIpa":"/əˈpreɪz/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to judge the quality, condition, or performance of something","vi":"đánh giá; định giá chất lượng, tình trạng hoặc hiệu suất"},{"pos":"v.","en":"to estimate how much money something is worth","vi":"thẩm định; ước tính giá trị tiền bạc"}],"examples":[{"en":"The coach appraised my technique and suggested some changes.","vi":"Huấn luyện viên đã đánh giá kỹ thuật của tôi và đưa ra một số gợi ý thay đổi.","audioKind":"ex"},{"en":"Local authorities must appraise the environmental impact of major construction projects before granting planning permission.","vi":"Các cơ quan địa phương phải đánh giá tác động môi trường của các dự án xây dựng lớn trước khi cấp phép quy hoạch.","audioKind":"ex2"}],"collocations":[{"en":"appraise performance","vi":"đánh giá hiệu suất"},{"en":"appraise a property","vi":"thẩm định tài sản"},{"en":"critically appraise","vi":"đánh giá phản biện"}],"wordFamily":["appraisal (n.)","appraiser (n.)"],"synonyms":["assess","evaluate"],"antonyms":[],"tipVi":"appraise là đánh giá; đừng nhầm lẫn với apprise (thông báo).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strive', 'en-c1-37', 'strive', '/straɪv/', 'C1', 'nỗ lực; phấn đấu; cố gắng hết sức', 'v.', 'striving (n.)', 'Đồng nghĩa: endeavour', 'Thường dùng "strive to do" hoặc "strive for"; dạng quá khứ thường là "strove".', 'I strive to practise the piano every day.', NULL, 'Tôi cố gắng tập piano mỗi ngày.', '{"wordId":"strive","ukIpa":"/straɪv/","usIpa":"/straɪv/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To try very hard to achieve something.","vi":"nỗ lực; phấn đấu; cố gắng hết sức"}],"examples":[{"en":"I strive to practise the piano every day.","vi":"Tôi cố gắng tập piano mỗi ngày.","audioKind":"ex"},{"en":"Governments should strive to provide affordable housing without reducing the quality of public services.","vi":"Chính phủ nên nỗ lực cung cấp nhà ở giá rẻ mà không làm giảm chất lượng các dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"strive to improve","vi":"nỗ lực cải thiện"},{"en":"strive for excellence","vi":"phấn đấu vì sự xuất sắc"},{"en":"strive towards a goal","vi":"phấn đấu vươn tới một mục tiêu"}],"wordFamily":["striving (n.)"],"synonyms":["endeavour"],"antonyms":[],"tipVi":"Thường dùng \"strive to do\" hoặc \"strive for\"; dạng quá khứ thường là \"strove\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_duplicate', 'en-c1-37', 'duplicate', '/ˈduːplɪkət/', 'C1', 'bản sao; bản phụ; sao chép; làm lặp lại không cần thiết; trùng lặp', 'n.', 'duplication (n.), duplicator (n.)', 'Đồng nghĩa: copy, replica · Trái nghĩa: original', 'Danh từ và tính từ có đuôi đọc là /kət/; động từ đọc là /keɪt/.', 'I keep a duplicate of the key at home.', NULL, 'Tôi giữ một bản sao của chiếc chìa khóa ở nhà.', '{"wordId":"duplicate","ukIpa":"/ˈdjuːplɪkət/","usIpa":"/ˈduːplɪkət/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"An exact copy of something","vi":"bản sao; bản phụ"},{"pos":"v.","en":"To make an exact copy or repeat something unnecessarily","vi":"sao chép; làm lặp lại không cần thiết"},{"pos":"adj.","en":"Exactly matching another item","vi":"bản sao; trùng lặp"}],"examples":[{"en":"I keep a duplicate of the key at home.","vi":"Tôi giữ một bản sao của chiếc chìa khóa ở nhà.","audioKind":"ex"},{"en":"Research teams should share their findings to avoid duplicating work and wasting limited public funding.","vi":"Các nhóm nghiên cứu nên chia sẻ kết quả của mình để tránh lãng phí thời gian làm việc trùng lặp và lãng phí nguồn ngân sách công hạn hẹp.","audioKind":"ex2"}],"collocations":[{"en":"a duplicate key","vi":"một chiếc chìa khóa phụ"},{"en":"duplicate records","vi":"các hồ sơ trùng lặp"},{"en":"duplicate efforts","vi":"làm việc trùng lặp công sức"},{"en":"in duplicate","vi":"làm thành hai bản"}],"wordFamily":["duplication (n.)","duplicator (n.)"],"synonyms":["copy","replica"],"antonyms":["original"],"tipVi":"Danh từ và tính từ có đuôi đọc là /kət/; động từ đọc là /keɪt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_farmhand', 'en-c1-37', 'farmhand', '/ˈfɑːrmhænd/', 'C1', 'người làm thuê trong trang trại; tá điền', 'n.', 'farm (n.), farm (v.), farmer (n.), farming (n.)', 'Đồng nghĩa: farmworker', 'Hậu tố hand có thể chỉ người làm công việc chân tay; farmhand là người làm thuê chứ không phải chủ trang trại.', 'A farmhand carried fresh hay into the barn this morning.', NULL, 'Sáng nay, một người làm thuê trong trang trại đã chở cỏ khô tươi vào kho chứa.', '{"wordId":"farmhand","ukIpa":"/ˈfɑːmhænd/","usIpa":"/ˈfɑːrmhænd/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A person employed to do practical work on a farm","vi":"người làm thuê trong trang trại; tá điền"}],"examples":[{"en":"A farmhand carried fresh hay into the barn this morning.","vi":"Sáng nay, một người làm thuê trong trang trại đã chở cỏ khô tươi vào kho chứa.","audioKind":"ex"},{"en":"Seasonal farmhands play an important role in harvesting crops where agricultural machinery cannot easily be used.","vi":"Những người làm thuê thời vụ trong trang trại đóng vai trò quan trọng trong việc thu hoạch mùa màng ở những nơi máy móc nông nghiệp khó có thể hoạt động.","audioKind":"ex2"}],"collocations":[{"en":"work as a farmhand","vi":"làm công nhân nông trại"},{"en":"hire a farmhand","vi":"thuê người làm trang trại"},{"en":"seasonal farmhand","vi":"người làm thuê nông trại thời vụ"}],"wordFamily":["farm (n.)","farm (v.)","farmer (n.)","farming (n.)"],"synonyms":["farmworker"],"antonyms":[],"tipVi":"Hậu tố hand có thể chỉ người làm công việc chân tay; farmhand là người làm thuê chứ không phải chủ trang trại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_portfolio', 'en-c1-37', 'portfolio', '/pɔːrtˈfoʊlioʊ/', 'C1', 'tập hồ sơ năng lực; tập các tác phẩm tiêu biểu; danh mục đầu tư; chức vụ bộ trưởng; lĩnh vực phụ trách của bộ trưởng', 'n.', NULL, NULL, 'Trong bối cảnh tìm việc, portfolio thường chỉ tập hồ sơ tác phẩm; trong tài chính, nó chỉ danh mục đầu tư.', 'She brought her photography portfolio to the interview.', NULL, 'Cô ấy mang theo tập hồ sơ các tác phẩm nhiếp ảnh của mình đến buổi phỏng vấn.', '{"wordId":"portfolio","ukIpa":"/pɔːtˈfəʊliəʊ/","usIpa":"/pɔːrtˈfoʊlioʊ/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"a collection of work showing someone''s skills and experience","vi":"tập hồ sơ năng lực; tập các tác phẩm tiêu biểu"},{"pos":"n.","en":"a collection of investments owned by a person or organization","vi":"danh mục đầu tư"},{"pos":"n.","en":"a minister''s position or area of government responsibility","vi":"chức vụ bộ trưởng; lĩnh vực phụ trách của bộ trưởng"}],"examples":[{"en":"She brought her photography portfolio to the interview.","vi":"Cô ấy mang theo tập hồ sơ các tác phẩm nhiếp ảnh của mình đến buổi phỏng vấn.","audioKind":"ex"},{"en":"A diversified investment portfolio can reduce financial risk, although it cannot guarantee steady returns.","vi":"Một danh mục đầu tư đa dạng hóa có thể giảm thiểu rủi ro tài chính, dù nó không thể đảm bảo mức lợi nhuận ổn định.","audioKind":"ex2"}],"collocations":[{"en":"a portfolio of work","vi":"một bộ hồ sơ tác phẩm"},{"en":"investment portfolio","vi":"danh mục đầu tư tài chính"},{"en":"hold a portfolio","vi":"giữ chức vụ bộ trưởng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong bối cảnh tìm việc, portfolio thường chỉ tập hồ sơ tác phẩm; trong tài chính, nó chỉ danh mục đầu tư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warden', 'en-c1-37', 'warden', '/ˈwɔːrdən/', 'C1', 'người quản lý, người giám sát hoặc bảo vệ một khu vực; quản tù, giám thị nhà tù (đặc biệt ở Mỹ)', 'n.', NULL, NULL, 'Trong tiếng Anh Mỹ, prison warden chỉ giám thị/quản tù trưởng, không phải là nhân viên canh ngục thông thường.', 'The park warden helped us find the campsite.', NULL, 'Người quản lý công viên đã giúp chúng tôi tìm thấy bãi cắm trại.', '{"wordId":"warden","ukIpa":"/ˈwɔːdən/","usIpa":"/ˈwɔːrdən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"someone responsible for supervising or protecting a place","vi":"người quản lý, người giám sát hoặc bảo vệ một khu vực"},{"pos":"n.","en":"the person in charge of a prison, especially in America","vi":"quản tù, giám thị nhà tù (đặc biệt ở Mỹ)"}],"examples":[{"en":"The park warden helped us find the campsite.","vi":"Người quản lý công viên đã giúp chúng tôi tìm thấy bãi cắm trại.","audioKind":"ex"},{"en":"A wildlife warden can help protect endangered species by monitoring habitats and guiding visitors away from sensitive areas.","vi":"Một nhân viên bảo vệ động vật hoang dã có thể giúp bảo vệ các loài nguy cấp bằng cách theo dõi môi trường sống và hướng dẫn du khách tránh xa các khu vực nhạy cảm.","audioKind":"ex2"}],"collocations":[{"en":"park warden","vi":"người quản lý công viên"},{"en":"prison warden","vi":"quản tù"},{"en":"traffic warden","vi":"cảnh sát giao thông"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Mỹ, prison warden chỉ giám thị/quản tù trưởng, không phải là nhân viên canh ngục thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_versatile', 'en-c1-37', 'versatile', '/ˈvɝːsətəl/', 'C1', 'đa năng; linh hoạt, nhiều công dụng', 'adj.', 'versatility (n.)', 'Đồng nghĩa: adaptable, multifunctional', 'Có thể dùng để miêu tả người có nhiều tài năng hoặc vật dụng có nhiều công dụng khác nhau.', 'This versatile pan works well for soups and stir-fries.', NULL, 'Chiếc chảo đa năng này dùng rất tốt cho các món súp và món xào.', '{"wordId":"versatile","ukIpa":"/ˈvɜːsətaɪl/","usIpa":"/ˈvɝːsətəl/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Able to do many things or serve many different purposes.","vi":"đa năng; linh hoạt, nhiều công dụng"}],"examples":[{"en":"This versatile pan works well for soups and stir-fries.","vi":"Chiếc chảo đa năng này dùng rất tốt cho các món súp và món xào.","audioKind":"ex"},{"en":"Employers increasingly value versatile graduates who can adapt to different roles and learn new skills.","vi":"Các nhà tuyển dụng ngày càng đánh giá cao những cử nhân đa năng, những người có thể thích nghi với các vai trò khác nhau và học hỏi các kỹ năng mới.","audioKind":"ex2"}],"collocations":[{"en":"a versatile performer","vi":"nghệ sĩ đa tài"},{"en":"a versatile tool","vi":"dụng cụ đa năng"},{"en":"highly versatile","vi":"có tính đa năng cao"}],"wordFamily":["versatility (n.)"],"synonyms":["adaptable","multifunctional"],"antonyms":[],"tipVi":"Có thể dùng để miêu tả người có nhiều tài năng hoặc vật dụng có nhiều công dụng khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preside', 'en-c1-37', 'preside', '/prɪˈzaɪd/', 'C1', 'chủ trì; làm chủ tọa', 'v.', 'presiding (adj.)', 'Đồng nghĩa: chair', 'Không đi thẳng với tân ngữ là cuộc họp mà thường dùng preside over.', 'Our club elected Nina to preside over the next meeting.', NULL, 'Câu lạc bộ của chúng tôi đã bầu Nina làm chủ trì cuộc họp tiếp theo.', '{"wordId":"preside","ukIpa":"/prɪˈzaɪd/","usIpa":"/prɪˈzaɪd/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To lead a formal meeting, ceremony, or other official event","vi":"chủ trì; làm chủ tọa"}],"examples":[{"en":"Our club elected Nina to preside over the next meeting.","vi":"Câu lạc bộ của chúng tôi đã bầu Nina làm chủ trì cuộc họp tiếp theo.","audioKind":"ex"},{"en":"An independent expert should preside over the public hearing to ensure that all participants receive fair treatment.","vi":"Một chuyên gia độc lập nên chủ trì phiên điều trần công khai để đảm bảo rằng tất cả những người tham gia đều được đối xử công bằng.","audioKind":"ex2"}],"collocations":[{"en":"preside over a meeting","vi":"chủ trì một cuộc họp"},{"en":"preside at a ceremony","vi":"chủ trì một buổi lễ"},{"en":"presiding judge","vi":"thẩm phán chủ tọa"}],"wordFamily":["presiding (adj.)"],"synonyms":["chair"],"antonyms":[],"tipVi":"Không đi thẳng với tân ngữ là cuộc họp mà thường dùng preside over.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_37_1', 'en-c1-37', 'Cách dùng “overextend” (v.) — làm cho quá sức; vươn quá tầm; dùng quá mức', 'overextend yourself  ·  overextend financially  ·  overextend resources', 'Thường đi với đại từ phản thân thành overextend oneself, chỉ việc nhận lấy nhiệm vụ hoặc chi tiêu vượt quá năng lực.', 'Họ từ (Word Family): overextension (n.), extend (v.), extension (n.) | Đồng nghĩa: overburden, overstretch', '[{"hanzi":"Don''t overextend yourself by joining every club at school.","pinyin":"","meaning":"Đừng tự làm mình quá sức bằng cách tham gia mọi câu lạc bộ ở trường."},{"hanzi":"Small businesses may overextend themselves financially when they expand rapidly without assessing future demand.","pinyin":"","meaning":"Các doanh nghiệp nhỏ có thể tự đặt mình vào thế tài chính quá sức khi mở rộng quy mô quá nhanh mà không đánh giá trước nhu cầu tương lai."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_37_2', 'en-c1-37', 'Cách dùng “farmhand” (n.) — người làm thuê trong trang trại; tá điền', 'work as a farmhand  ·  hire a farmhand  ·  seasonal farmhand', 'Hậu tố hand có thể chỉ người làm công việc chân tay; farmhand là người làm thuê chứ không phải chủ trang trại.', 'Họ từ (Word Family): farm (n.), farm (v.), farmer (n.), farming (n.) | Đồng nghĩa: farmworker', '[{"hanzi":"A farmhand carried fresh hay into the barn this morning.","pinyin":"","meaning":"Sáng nay, một người làm thuê trong trang trại đã chở cỏ khô tươi vào kho chứa."},{"hanzi":"Seasonal farmhands play an important role in harvesting crops where agricultural machinery cannot easily be used.","pinyin":"","meaning":"Những người làm thuê thời vụ trong trang trại đóng vai trò quan trọng trong việc thu hoạch mùa màng ở những nơi máy móc nông nghiệp khó có thể hoạt động."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_37_3', 'en-c1-37', 'Cách dùng “warden” (n.) — người quản lý, người giám sát hoặc bảo vệ một khu vực', 'park warden  ·  prison warden  ·  traffic warden', 'Trong tiếng Anh Mỹ, prison warden chỉ giám thị/quản tù trưởng, không phải là nhân viên canh ngục thông thường.', NULL, '[{"hanzi":"The park warden helped us find the campsite.","pinyin":"","meaning":"Người quản lý công viên đã giúp chúng tôi tìm thấy bãi cắm trại."},{"hanzi":"A wildlife warden can help protect endangered species by monitoring habitats and guiding visitors away from sensitive areas.","pinyin":"","meaning":"Một nhân viên bảo vệ động vật hoang dã có thể giúp bảo vệ các loài nguy cấp bằng cách theo dõi môi trường sống và hướng dẫn du khách tránh xa các khu vực nhạy cảm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_37_4', 'en-c1-37', 'Cách dùng “lieutenant” (n.) — trung úy (lục quân); đại úy (hải quân); sĩ quan cấp dưới', 'army lieutenant  ·  naval lieutenant  ·  trusted lieutenant', 'Tiếng Anh-Anh đọc âm đầu là /lef/, tiếng Anh-Mỹ đọc là /luː/; tên gọi quân hàm thay đổi tùy theo quân chủng.', NULL, '[{"hanzi":"The lieutenant helped the new soldiers organise their equipment.","pinyin":"","meaning":"Vị trung úy đã giúp các tân binh sắp xếp trang thiết bị của họ."},{"hanzi":"During disaster relief operations, a lieutenant may coordinate military teams delivering essential supplies to isolated communities.","pinyin":"","meaning":"Trong các chiến dịch cứu trợ thiên tai, một trung úy có thể điều phối các đội quân sự vận chuyển nhu yếu phẩm đến những cộng đồng bị cô lập."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_37_1', 'en-c1-37', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_1_1', 'ten_c1_37_1', 'advantageous', 'Booking early was advantageous because we got cheaper tickets.', 'Booking early was advantageous because we got cheaper tickets.', '/ˌædvənˈteɪdʒəs/', 'Đặt vé sớm rất có lợi vì chúng tôi mua được vé rẻ hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_1_2', 'ten_c1_37_1', 'certify', 'An engineer certified that our new boiler was safe.', 'An engineer certified that our new boiler was safe.', '/ˈsɝːtɪfaɪ/', 'Một kỹ sư đã xác nhận rằng chiếc lò hơi mới của chúng tôi hoàn toàn an toàn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
