INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_1_4', 'ten_c1_37_1', 'oversight', 'Through an oversight, I left your lunch at home.', 'Through an oversight, I left your lunch at home.', '/ˈoʊvərsaɪt/', 'Do sơ suất, tôi đã để quên bữa trưa của bạn ở nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_1_5', 'ten_c1_37_1', 'redundant', 'This spare cable is redundant now we use wireless speakers.', 'This spare cable is redundant now we use wireless speakers.', '/rɪˈdʌndənt/', 'Cọng cáp dự phòng này nay đã thừa thãi vì chúng ta dùng loa không dây.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_1_6', 'ten_c1_37_1', 'know-how', 'My uncle has the know-how to repair old bicycles.', 'My uncle has the know-how to repair old bicycles.', '/ˈnoʊ haʊ/', 'Chú tôi có kỹ thuật để sửa những chiếc xe đạp cũ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_1_7', 'ten_c1_37_1', 'transferable', 'These tickets are transferable, so your sister can use mine.', 'These tickets are transferable, so your sister can use mine.', '/trænsˈfɝːəbəl/', 'Những tấm vé này có thể chuyển nhượng được, vì vậy chị gái bạn có thể dùng vé của tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_1_8', 'ten_c1_37_1', 'lieutenant', 'The lieutenant helped the new soldiers organise their equipment.', 'The lieutenant helped the new soldiers organise their equipment.', '/luːˈtenənt/', 'Vị trung úy đã giúp các tân binh sắp xếp trang thiết bị của họ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_37_1_1', 'en-c1-37', 'ten_c1_37_1', 'listening', 'listening', 'Booking early was advantageous because we got cheaper tickets.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Phân loại tất cả mấy cái hóa đơn cũ này là một công việc thật tẻ nhạt.","Buổi hòa nhạc buổi tối sẽ bắt đầu sau một lời chào ngắn gọn.","Người thủy thủ giàu kinh nghiệm đã kiểm tra các dây thừng trước khi con tàu khởi hành.","Đặt vé sớm rất có lợi vì chúng tôi mua được vé rẻ hơn."]'::jsonb, 3, 'Booking early was advantageous because we got cheaper tickets. → Đặt vé sớm rất có lợi vì chúng tôi mua được vé rẻ hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_37_1_2', 'en-c1-37', 'ten_c1_37_1', 'listening', 'listening', 'An engineer certified that our new boiler was safe.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người quản lý công viên đã giúp chúng tôi tìm thấy bãi cắm trại.","Do sơ suất, tôi đã để quên bữa trưa của bạn ở nhà.","Chú tôi có kỹ thuật để sửa những chiếc xe đạp cũ.","Một kỹ sư đã xác nhận rằng chiếc lò hơi mới của chúng tôi hoàn toàn an toàn."]'::jsonb, 3, 'An engineer certified that our new boiler was safe. → Một kỹ sư đã xác nhận rằng chiếc lò hơi mới của chúng tôi hoàn toàn an toàn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_37_1_3', 'en-c1-37', 'ten_c1_37_1', 'listening', 'listening', 'Don''t overextend yourself by joining every club at school.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những tấm vé này có thể chuyển nhượng được, vì vậy chị gái bạn có thể dùng vé của tôi.","Y tá đã cho tôi uống thuốc trước khi tôi về nhà.","Đừng tự làm mình quá sức bằng cách tham gia mọi câu lạc bộ ở trường.","Cô y tá đã kiểm tra cẩn thận từng món đồ trong bộ dụng cụ."]'::jsonb, 2, 'Don''t overextend yourself by joining every club at school. → Đừng tự làm mình quá sức bằng cách tham gia mọi câu lạc bộ ở trường.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_37_2', 'en-c1-37', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_2_1', 'ten_c1_37_2', 'advantageous', 'Flexible working arrangements can be advantageous to employers by improving staff satisfaction and reducing employee turnover.', 'Flexible working arrangements can be advantageous to employers by improving staff satisfaction and reducing employee turnover.', '/ˌædvənˈteɪdʒəs/', 'Các thỏa thuận làm việc linh hoạt có thể mang lại lợi ích cho người sử dụng lao động bằng cách nâng cao sự hài lòng của nhân viên và giảm tỷ lệ nghỉ việc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_2_2', 'ten_c1_37_2', 'certify', 'Independent organisations certify that certain products meet environmental standards, helping consumers make more informed purchasing decisions.', 'Independent organisations certify that certain products meet environmental standards, helping consumers make more informed purchasing decisions.', '/ˈsɝːtɪfaɪ/', 'Các tổ chức độc lập chứng nhận rằng một số sản phẩm đáp ứng tiêu chuẩn môi trường, giúp người tiêu dùng đưa ra quyết định mua sắm có hiểu biết hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_2_3', 'ten_c1_37_2', 'overextend', 'Small businesses may overextend themselves financially when they expand rapidly without assessing future demand.', 'Small businesses may overextend themselves financially when they expand rapidly without assessing future demand.', '/ˌoʊvərɪkˈstend/', 'Các doanh nghiệp nhỏ có thể tự đặt mình vào thế tài chính quá sức khi mở rộng quy mô quá nhanh mà không đánh giá trước nhu cầu tương lai.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_2_4', 'ten_c1_37_2', 'oversight', 'Independent oversight of public spending can reduce corruption and strengthen citizens'' confidence in government institutions.', 'Independent oversight of public spending can reduce corruption and strengthen citizens'' confidence in government institutions.', '/ˈoʊvərsaɪt/', 'Sự giám sát độc lập đối với chi tiêu công có thể làm giảm tham nhũng và củng cố niềm tin của người dân vào các cơ quan chính phủ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_2_5', 'ten_c1_37_2', 'redundant', 'Factory workers may be made redundant when automated systems take over tasks previously performed by people.', 'Factory workers may be made redundant when automated systems take over tasks previously performed by people.', '/rɪˈdʌndənt/', 'Công nhân nhà máy có thể bị sa thải khi các hệ thống tự động tiếp quản các công việc trước đây do con người thực hiện.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_37_2_6', 'ten_c1_37_2', 'know-how', 'Sharing technical know-how can help small businesses adopt cleaner production methods without relying entirely on outside consultants.', 'Sharing technical know-how can help small businesses adopt cleaner production methods without relying entirely on outside consultants.', '/ˈnoʊ haʊ/', 'Chia sẻ bí quyết kỹ thuật có thể giúp các doanh nghiệp nhỏ áp dụng phương pháp sản xuất sạch hơn mà không phải hoàn toàn phụ thuộc vào chuyên gia tư vấn bên ngoài.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_37_2_1', 'en-c1-37', 'ten_c1_37_2', 'listening', 'listening', 'Flexible working arrangements can be advantageous to employers by improving staff satisfaction and reducing employee turnover.', NULL, 'Trong câu vừa nghe, từ “advantageous” mang nghĩa nào sau đây?', '["nhà máy bia","hậu duệ; con cháu","có lợi; thuận lợi; hữu ích","sản xuất ra nhiều tác phẩm, kết quả hoặc thành tựu; đa sản, sung mãn"]'::jsonb, 2, '“advantageous” (/ˌædvənˈteɪdʒəs/): có lợi; thuận lợi; hữu ích. Câu đầy đủ: Flexible working arrangements can be advantageous to employers by improving staff satisfaction and reducing employee turnover.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_37_2_2', 'en-c1-37', 'ten_c1_37_2', 'listening', 'listening', 'Independent organisations certify that certain products meet environmental standards, helping consumers make more informed purchasing decisions.', NULL, 'Trong câu vừa nghe, từ “certify” mang nghĩa nào sau đây?', '["vô hại; không có hại; không xúc phạm ai","sự ô nhục; sự mất thể diện; tiếng nhơ","chứng nhận; cấp giấy chứng nhận; xác nhận chính thức","quấy rối tình dục; lạm dụng tình dục"]'::jsonb, 2, '“certify” (/ˈsɝːtɪfaɪ/): chứng nhận; cấp giấy chứng nhận; xác nhận chính thức. Câu đầy đủ: Independent organisations certify that certain products meet environmental standards, helping consumers make more informed purchasing decisions.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
