INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_37_5', 'en-c1-37', 'en_to_vi', 'The experienced seaman checked the ropes before the ship departed.', 'The experienced seaman checked the ropes before the ship departed.', '/ˈsiːmən/', NULL, 'Người thủy thủ giàu kinh nghiệm đã kiểm tra các dây thừng trước khi con tàu khởi hành.', NULL, '["người","thủy","thủ","giàu","kinh","nghiệm","đã","kiểm"]'::jsonb, 'Từ trọng tâm: seaman (hải quân; thủy thủ; hải đăng)', 'The experienced seaman checked the ropes before the ship departed. → Người thủy thủ giàu kinh nghiệm đã kiểm tra các dây thừng trước khi con tàu khởi hành.', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_37_6', 'en-c1-37', 'en_to_vi', 'The arduous climb left us exhausted but deeply satisfied.', 'The arduous climb left us exhausted but deeply satisfied.', '/ˈɑːrdʒuəs/', NULL, 'Chuyến leo núi gian khổ khiến chúng tôi kiệt sức nhưng vô cùng mãn nguyện.', NULL, '["chuyến","leo","núi","gian","khổ","khiến","chúng","tôi"]'::jsonb, 'Từ trọng tâm: arduous (gian khổ; gian nan; đòi hỏi nhiều nỗ lực)', 'The arduous climb left us exhausted but deeply satisfied. → Chuyến leo núi gian khổ khiến chúng tôi kiệt sức nhưng vô cùng mãn nguyện.', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
