INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_2', 'en-c1-37', NULL, 'comprehensive_test', 'listening', 'An engineer certified that our new boiler was safe.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô y tá đã kiểm tra cẩn thận từng món đồ trong bộ dụng cụ.","Cô ấy mang theo tập hồ sơ các tác phẩm nhiếp ảnh của mình đến buổi phỏng vấn.","Vị trung úy đã giúp các tân binh sắp xếp trang thiết bị của họ.","Một kỹ sư đã xác nhận rằng chiếc lò hơi mới của chúng tôi hoàn toàn an toàn."]'::jsonb, 3, 'An engineer certified that our new boiler was safe. → Một kỹ sư đã xác nhận rằng chiếc lò hơi mới của chúng tôi hoàn toàn an toàn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_3', 'en-c1-37', NULL, 'comprehensive_test', 'listening', 'overextend', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người ngoại đạo; người không chuyên môn","xảo quyệt; gian xảo","công tố viên; kiểm sát viên","làm cho quá sức; vươn quá tầm; dùng quá mức"]'::jsonb, 3, 'overextend (/ˌoʊvərɪkˈstend/) → làm cho quá sức; vươn quá tầm; dùng quá mức', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_4', 'en-c1-37', NULL, 'comprehensive_test', 'listening', 'Through an oversight, I left your lunch at home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Huấn luyện viên đã đánh giá kỹ thuật của tôi và đưa ra một số gợi ý thay đổi.","Cọng cáp dự phòng này nay đã thừa thãi vì chúng ta dùng loa không dây.","Đừng tự làm mình quá sức bằng cách tham gia mọi câu lạc bộ ở trường.","Do sơ suất, tôi đã để quên bữa trưa của bạn ở nhà."]'::jsonb, 3, 'Through an oversight, I left your lunch at home. → Do sơ suất, tôi đã để quên bữa trưa của bạn ở nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_5', 'en-c1-37', NULL, 'comprehensive_test', 'listening', 'redundant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["gây phiền toái; mệt mỏi; nhàm chán","gây nguy hiểm; làm tổn hại","thừa thãi; không cần thiết; dư thừa","vật tương tự; vật đối ứng"]'::jsonb, 2, 'redundant (/rɪˈdʌndənt/) → thừa thãi; không cần thiết; dư thừa; bị sa thải (do mất việc hoặc cắt giảm biên chế)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_6', 'en-c1-37', NULL, 'comprehensive_test', 'listening', 'My uncle has the know-how to repair old bicycles.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cọng cáp dự phòng này nay đã thừa thãi vì chúng ta dùng loa không dây.","Chú tôi có kỹ thuật để sửa những chiếc xe đạp cũ.","Chiếc chảo đa năng này dùng rất tốt cho các món súp và món xào.","Một kỹ sư đã xác nhận rằng chiếc lò hơi mới của chúng tôi hoàn toàn an toàn."]'::jsonb, 1, 'My uncle has the know-how to repair old bicycles. → Chú tôi có kỹ thuật để sửa những chiếc xe đạp cũ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_7', 'en-c1-37', NULL, 'comprehensive_test', 'listening', 'transferable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm tăng thêm; làm mạnh lên; gia tăng","huyết dược; thuốc súng","có thể chuyển nhượng; có thể chuyển giao","động vật lưỡng cư"]'::jsonb, 2, 'transferable (/trænsˈfɝːəbəl/) → có thể chuyển nhượng; có thể chuyển giao; có thể áp dụng vào nhiều công việc hoặc tình huống khác nhau', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_8', 'en-c1-37', NULL, 'comprehensive_test', 'listening', 'The lieutenant helped the new soldiers organise their equipment.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc tân trang lại ngôi nhà cũ này là một công việc lớn hơn nhiều.","Y tá đã cho tôi uống thuốc trước khi tôi về nhà.","Những tấm vé này có thể chuyển nhượng được, vì vậy chị gái bạn có thể dùng vé của tôi.","Vị trung úy đã giúp các tân binh sắp xếp trang thiết bị của họ."]'::jsonb, 3, 'The lieutenant helped the new soldiers organise their equipment. → Vị trung úy đã giúp các tân binh sắp xếp trang thiết bị của họ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_9', 'en-c1-37', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “unnecessary because it is no longer needed or repeats something”?', '["certify","redundant","appraise","transferable"]'::jsonb, 1, 'redundant (/rɪˈdʌndənt/) → thừa thãi; không cần thiết; dư thừa', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_10', 'en-c1-37', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Practical knowledge and skills needed to do something successfully”?', '["farmhand","commence","know-how","oversight"]'::jsonb, 2, 'know-how (/ˈnoʊ haʊ/) → bí quyết kỹ thuật; kỹ năng thực tế', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_11', 'en-c1-37', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “able to be moved or passed to another person or place”?', '["seaman","lieutenant","overextend","transferable"]'::jsonb, 3, 'transferable (/trænsˈfɝːəbəl/) → có thể chuyển nhượng; có thể chuyển giao', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_12', 'en-c1-37', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An officer holding a junior rank in the armed forces”?', '["undertaking","commence","lieutenant","overextend"]'::jsonb, 2, 'lieutenant (/luːˈtenənt/) → trung úy (lục quân); đại úy (hải quân); sĩ quan cấp dưới', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_13', 'en-c1-37', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The skill and quality shown in making something.”?', '["administer","overextend","advantageous","workmanship"]'::jsonb, 3, 'workmanship (/ˈwɝːkmənʃɪp/) → tay nghề; chất lượng gia công', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
