INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_18', 'en-c1-37', NULL, 'comprehensive_test', 'reading', NULL, 'Flexible working arrangements can be advantageous to employers by improving staff satisfaction and reducing employee turnover.', 'Dựa vào câu trên, từ “advantageous” có nghĩa phù hợp nhất là gì?', '["có lợi; thuận lợi; hữu ích","sự chỉ định; sự bổ nhiệm; sự phân loại","bãi cỏ chăn gia súc; đồng cỏ","thực thi được; khả thi"]'::jsonb, 0, 'advantageous: có lợi; thuận lợi; hữu ích. Dịch cả câu: Các thỏa thuận làm việc linh hoạt có thể mang lại lợi ích cho người sử dụng lao động bằng cách nâng cao sự hài lòng của nhân viên và giảm tỷ lệ nghỉ việc.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_19', 'en-c1-37', NULL, 'comprehensive_test', 'reading', NULL, 'Independent organisations certify that certain products meet environmental standards, helping consumers make more informed purchasing decisions.', 'Dựa vào câu trên, từ “certify” có nghĩa phù hợp nhất là gì?', '["cởi mở; hay nói; thích giao tiếp","tấm biển thông báo lớn; biểu ngữ (dùng trong các cuộc biểu tình, diễu hành)","cơ học","chứng nhận; cấp giấy chứng nhận; xác nhận chính thức"]'::jsonb, 3, 'certify: chứng nhận; cấp giấy chứng nhận; xác nhận chính thức. Dịch cả câu: Các tổ chức độc lập chứng nhận rằng một số sản phẩm đáp ứng tiêu chuẩn môi trường, giúp người tiêu dùng đưa ra quyết định mua sắm có hiểu biết hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_20', 'en-c1-37', NULL, 'comprehensive_test', 'reading', NULL, 'Small businesses may overextend themselves financially when they expand rapidly without assessing future demand.', 'Dựa vào câu trên, từ “overextend” có nghĩa phù hợp nhất là gì?', '["động vật lưỡng cư","gitu điềm gở; báo hiệu điều chẳng lành; đe dọa","biểu thị; chỉ rõ","làm cho quá sức; vươn quá tầm; dùng quá mức"]'::jsonb, 3, 'overextend: làm cho quá sức; vươn quá tầm; dùng quá mức. Dịch cả câu: Các doanh nghiệp nhỏ có thể tự đặt mình vào thế tài chính quá sức khi mở rộng quy mô quá nhanh mà không đánh giá trước nhu cầu tương lai.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_21', 'en-c1-37', NULL, 'comprehensive_test', 'reading', NULL, 'Independent oversight of public spending can reduce corruption and strengthen citizens'' confidence in government institutions.', 'Dựa vào câu trên, từ “oversight” có nghĩa phù hợp nhất là gì?', '["sự sơ suất; sự sai sót do sơ suất","cản trở; gây khó khăn","vuông góc; tạo với một đường thẳng hoặc bề mặt khác một góc vuông","hất cẳng; lật đổ; truất ngôi"]'::jsonb, 0, 'oversight: sự sơ suất; sự sai sót do sơ suất; sự giám sát; sự quản lý. Dịch cả câu: Sự giám sát độc lập đối với chi tiêu công có thể làm giảm tham nhũng và củng cố niềm tin của người dân vào các cơ quan chính phủ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_22', 'en-c1-37', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “người quản lý, người giám sát hoặc bảo vệ một khu vực”', '["haunt","indicative","commotion","warden"]'::jsonb, 3, 'người quản lý, người giám sát hoặc bảo vệ một khu vực → warden (/ˈwɔːrdən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_23', 'en-c1-37', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đa năng; linh hoạt, nhiều công dụng”', '["analogous","petite","versatile","microcosm"]'::jsonb, 2, 'đa năng; linh hoạt, nhiều công dụng → versatile (/ˈvɝːsətəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_37_24', 'en-c1-37', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chủ trì; làm chủ tọa”', '["gush","preside","lull","mane"]'::jsonb, 1, 'chủ trì; làm chủ tọa → preside (/prɪˈzaɪd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-38', 'en', 'Bài 38: Công việc & Nghề nghiệp (3) - CEFR C1', 'CEFR C1', 'C1 · Công việc', '25 từ vựng Tiếng Anh CEFR C1 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5038, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bread-earner', 'en-c1-38', 'bread-earner', '/ˈbred ˌɜːrnər/', 'C1', 'trụ cột gia đình; người kiếm tiền nuôi gia đình', 'n.', 'earn (v.), earner (n.), earnings (n.)', 'Đồng nghĩa: breadwinner', 'Ít phổ biến hơn; trong văn phong hàng ngày và văn viết học thuật thường dùng breadwinner.', 'My mother was the main bread-earner in our family.', NULL, 'Mẹ tôi từng là trụ cột chính trong gia đình chúng tôi.', '{"wordId":"bread-earner","ukIpa":"/ˈbred ˌɜːnə/","usIpa":"/ˈbred ˌɜːrnər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Someone who earns money to support a family.","vi":"trụ cột gia đình; người kiếm tiền nuôi gia đình"}],"examples":[{"en":"My mother was the main bread-earner in our family.","vi":"Mẹ tôi từng là trụ cột chính trong gia đình chúng tôi.","audioKind":"ex"},{"en":"Affordable childcare can help a family''s sole bread-earner remain employed while ensuring that children receive appropriate care.","vi":"Dịch vụ chăm sóc trẻ với chi phí phải chăng có thể giúp người kiếm tiền duy nhất trong gia đình tiếp tục làm việc đồng thời đảm bảo con cái được chăm sóc chu đáo.","audioKind":"ex2"}],"collocations":[{"en":"main bread-earner","vi":"trụ cột chính trong gia đình"},{"en":"sole bread-earner","vi":"người kiếm tiền duy nhất trong nhà"}],"wordFamily":["earn (v.)","earner (n.)","earnings (n.)"],"synonyms":["breadwinner"],"antonyms":[],"tipVi":"Ít phổ biến hơn; trong văn phong hàng ngày và văn viết học thuật thường dùng breadwinner.","noteVi":"Cách diễn đạt ít phổ biến hơn, thông thường hay dùng breadwinner.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conscientious', 'en-c1-38', 'conscientious', '/ˌkɑːnʃiˈenʃəs/', 'C1', 'tận tâm; chu đáo; có ý thức trách nhiệm', 'adj.', 'conscientiously (adv.), conscientiousness (n.), conscience (n.)', 'Đồng nghĩa: diligent, careful, thorough · Trái nghĩa: careless, negligent', 'Conscientious là tận tâm trách nhiệm; conscious là có ý thức/tỉnh táo.', 'Our conscientious neighbour checks our plants every morning.', NULL, 'Người hàng xóm tận tâm của chúng tôi kiểm tra các chậu cây mỗi buổi sáng.', '{"wordId":"conscientious","ukIpa":"/ˌkɒnʃiˈenʃəs/","usIpa":"/ˌkɑːnʃiˈenʃəs/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Careful to do duties thoroughly and correctly","vi":"tận tâm; chu đáo; có ý thức trách nhiệm"}],"examples":[{"en":"Our conscientious neighbour checks our plants every morning.","vi":"Người hàng xóm tận tâm của chúng tôi kiểm tra các chậu cây mỗi buổi sáng.","audioKind":"ex"},{"en":"Conscientious employees contribute to workplace safety by following procedures carefully and reporting potential hazards promptly.","vi":"Những nhân viên tận tâm góp phần đảm bảo an toàn nơi làm việc bằng cách tuân thủ cẩn thận các quy trình và kịp thời báo cáo các mối nguy hiểm tiềm ẩn.","audioKind":"ex2"}],"collocations":[{"en":"a conscientious worker","vi":"một nhân viên tận tâm"},{"en":"a conscientious student","vi":"một học sinh chăm chỉ"},{"en":"conscientious about your work","vi":"tận tâm với công việc"}],"wordFamily":["conscientiously (adv.)","conscientiousness (n.)","conscience (n.)"],"synonyms":["diligent","careful","thorough"],"antonyms":["careless","negligent"],"tipVi":"Conscientious là tận tâm trách nhiệm; conscious là có ý thức/tỉnh táo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_endeavour', 'en-c1-38', 'endeavour', '/ɪnˈdevər/', 'C1', 'nỗ lực; sự cố gắng; cố gắng', 'n.', NULL, 'Đồng nghĩa: effort, attempt, strive', 'Đây là cách viết theo tiếng Anh-Anh; tiếng Mỹ viết là endeavor; động từ đi kèm với to do.', 'Growing vegetables together became our family''s latest endeavour.', NULL, 'Cùng nhau trồng rau đã trở thành nỗ lực mới nhất của gia đình chúng tôi.', '{"wordId":"endeavour","ukIpa":"/ɪnˈdevə/","usIpa":"/ɪnˈdevər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A serious effort to achieve something.","vi":"nỗ lực; sự cố gắng"},{"pos":"v.","en":"To try hard to achieve a goal.","vi":"cố gắng; nỗ lực"}],"examples":[{"en":"Growing vegetables together became our family''s latest endeavour.","vi":"Cùng nhau trồng rau đã trở thành nỗ lực mới nhất của gia đình chúng tôi.","audioKind":"ex"},{"en":"Governments should endeavour to make reliable public transport accessible to people in remote communities.","vi":"Chính phủ nên nỗ lực cung cấp phương tiện giao thông công cộng đáng tin cậy cho người dân ở các cộng đồng vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"endeavour to do something","vi":"nỗ lực làm điều gì đó"},{"en":"make every endeavour","vi":"tận lực"},{"en":"a joint endeavour","vi":"nỗ lực chung"},{"en":"scientific endeavour","vi":"nỗ lực nghiên cứu khoa học"}],"wordFamily":[],"synonyms":["effort","attempt","strive"],"antonyms":[],"tipVi":"Đây là cách viết theo tiếng Anh-Anh; tiếng Mỹ viết là endeavor; động từ đi kèm với to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weld', 'en-c1-38', 'weld', '/weld/', 'C1', 'hàn (nối các chi tiết kim loại bằng cách nung nóng cho đến khi chúng chảy dính vào nhau); mối hàn; chỗ hàn', 'v.', 'welder (n.), welding (n.)', 'Đồng nghĩa: fuse, join', 'Cấu trúc weld A to B dùng để chỉ hành động hàn gắn phần A vào phần B.', 'Wearing a protective mask, she welded the metal frame.', NULL, 'Đeo mặt nạ bảo hộ, cô ấy tiến hành hàn khung kim loại.', '{"wordId":"weld","ukIpa":"/weld/","usIpa":"/weld/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To join metal parts by heating their edges until they fuse.","vi":"hàn (nối các chi tiết kim loại bằng cách nung nóng cho đến khi chúng chảy dính vào nhau)"},{"pos":"n.","en":"The joint formed when metal parts are welded together.","vi":"mối hàn; chỗ hàn"}],"examples":[{"en":"Wearing a protective mask, she welded the metal frame.","vi":"Đeo mặt nạ bảo hộ, cô ấy tiến hành hàn khung kim loại.","audioKind":"ex"},{"en":"Workers who weld steel structures need proper training and protective equipment to reduce workplace injuries.","vi":"Những công nhân làm công việc hàn kết cấu thép cần được đào tạo bài bản và trang bị thiết bị bảo hộ để giảm thiểu tai nạn lao động.","audioKind":"ex2"}],"collocations":[{"en":"weld metal","vi":"hàn kim loại"},{"en":"weld together","vi":"hàn dính vào nhau"},{"en":"a strong weld","vi":"mối hàn chắc chắn"}],"wordFamily":["welder (n.)","welding (n.)"],"synonyms":["fuse","join"],"antonyms":[],"tipVi":"Cấu trúc weld A to B dùng để chỉ hành động hàn gắn phần A vào phần B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outset', 'en-c1-38', 'outset', '/ˈaʊtset/', 'C1', 'sự bắt đầu; khởi đầu', 'n.', NULL, 'Đồng nghĩa: beginning, start · Trái nghĩa: end', 'Thường đi trong các cụm từ at/from the outset, không dùng cấu trúc set outset.', 'We agreed on a budget at the outset.', NULL, 'Chúng tôi đã thống nhất về ngân sách ngay từ lúc bắt đầu.', '{"wordId":"outset","ukIpa":"/ˈaʊtset/","usIpa":"/ˈaʊtset/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"The beginning of an activity, process, or period.","vi":"sự bắt đầu; khởi đầu"}],"examples":[{"en":"We agreed on a budget at the outset.","vi":"Chúng tôi đã thống nhất về ngân sách ngay từ lúc bắt đầu.","audioKind":"ex"},{"en":"Community members should be involved from the outset when local authorities plan major housing developments.","vi":"Các thành viên cộng đồng nên được tham gia ngay từ đầu khi cơ quan chức năng lên kế hoạch cho các dự án phát triển nhà ở quy mô lớn.","audioKind":"ex2"}],"collocations":[{"en":"at the outset","vi":"vào lúc khởi đầu"},{"en":"from the outset","vi":"ngay từ đầu"},{"en":"at the outset of","vi":"vào lúc bắt đầu của"}],"wordFamily":[],"synonyms":["beginning","start"],"antonyms":["end"],"tipVi":"Thường đi trong các cụm từ at/from the outset, không dùng cấu trúc set outset.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confer', 'en-c1-38', 'confer', '/kənˈfɜːr/', 'C1', 'bàn bạc; hội ý; thảo luận; ban tặng; trao (danh hiệu, quyền lợi)', 'v.', 'conference (n.), conferment (n.)', 'Đồng nghĩa: consult, bestow', 'Dùng cấu trúc confer with khi bàn bạc với ai, và confer sth on sb khi trao tặng danh hiệu hoặc quyền lợi cho ai.', 'The coaches conferred quietly before choosing the final team.', NULL, 'Các huấn luyện viên đã hội ý nhanh trước khi chốt đội hình thi đấu cuối cùng.', '{"wordId":"confer","ukIpa":"/kənˈfɜː/","usIpa":"/kənˈfɜːr/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"Discuss something with others before making a decision.","vi":"bàn bạc; hội ý; thảo luận"},{"pos":"v.","en":"Officially give someone an honour, right, or benefit.","vi":"ban tặng; trao (danh hiệu, quyền lợi)"}],"examples":[{"en":"The coaches conferred quietly before choosing the final team.","vi":"Các huấn luyện viên đã hội ý nhanh trước khi chốt đội hình thi đấu cuối cùng.","audioKind":"ex"},{"en":"Universities often confer honorary degrees on individuals who have made outstanding contributions to science or public service.","vi":"Các trường đại học thường trao học vị danh dự cho những cá nhân có đóng góp xuất sắc cho khoa học hoặc công ích.","audioKind":"ex2"}],"collocations":[{"en":"confer with colleagues","vi":"thảo luận với đồng nghiệp"},{"en":"confer a degree on someone","vi":"trao bằng cấp cho ai đó"},{"en":"confer benefits on","vi":"mang lại lợi ích cho"}],"wordFamily":["conference (n.)","conferment (n.)"],"synonyms":["consult","bestow"],"antonyms":[],"tipVi":"Dùng cấu trúc confer with khi bàn bạc với ai, và confer sth on sb khi trao tặng danh hiệu hoặc quyền lợi cho ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shipowner', 'en-c1-38', 'shipowner', '/ˈʃɪpˌoʊnər/', 'C1', 'chủ tàu; công ty sở hữu tàu thuyền', 'n.', 'ship (n.), ownership (n.)', NULL, 'Chỉ người hoặc công ty sở hữu tàu, không đồng nghĩa với thuyền trưởng điều khiển tàu.', 'The shipowner paid for repairs before the next voyage.', NULL, 'Chủ tàu đã chi trả chi phí sửa chữa trước chuyến hải trình tiếp theo.', '{"wordId":"shipowner","ukIpa":"/ˈʃɪpˌəʊnə/","usIpa":"/ˈʃɪpˌoʊnər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A person or company that owns ships.","vi":"chủ tàu; công ty sở hữu tàu thuyền"}],"examples":[{"en":"The shipowner paid for repairs before the next voyage.","vi":"Chủ tàu đã chi trả chi phí sửa chữa trước chuyến hải trình tiếp theo.","audioKind":"ex"},{"en":"Stricter environmental regulations require shipowners to invest in cleaner fuels and more efficient engines.","vi":"Các quy định môi trường ngặt nghèo hơn đòi hỏi các chủ tàu phải đầu tư vào nhiên liệu sạch hơn và động cơ hiệu suất cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"private shipowner","vi":"chủ tàu tư nhân"},{"en":"shipowner liability","vi":"trách nhiệm dân sự của chủ tàu"},{"en":"shipowners'' association","vi":"hiệp hội chủ tàu"}],"wordFamily":["ship (n.)","ownership (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ người hoặc công ty sở hữu tàu, không đồng nghĩa với thuyền trưởng điều khiển tàu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remuneration', 'en-c1-38', 'remuneration', '/rɪˌmjuːnəˈreɪʃən/', 'C1', 'thù lao; tiền công; chế độ đãi ngộ', 'n.', 'remunerate (v.), remunerative (adj.)', 'Đồng nghĩa: pay, payment, compensation', 'Thuật ngữ mang tính trang trọng, thường là danh từ không đếm được, chỉ tiền công lao động chứ không dùng cho bồi thường thiệt hại.', 'The job offers flexible hours but modest remuneration.', NULL, 'Công việc này có giờ giấc linh hoạt nhưng thù lao lại khá khiêm tốn.', '{"wordId":"remuneration","ukIpa":"/rɪˌmjuːnəˈreɪʃən/","usIpa":"/rɪˌmjuːnəˈreɪʃən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"payment received for work or services","vi":"thù lao; tiền công; chế độ đãi ngộ"}],"examples":[{"en":"The job offers flexible hours but modest remuneration.","vi":"Công việc này có giờ giấc linh hoạt nhưng thù lao lại khá khiêm tốn.","audioKind":"ex"},{"en":"Fair remuneration can help public hospitals attract qualified nurses and retain experienced staff over time.","vi":"Mức thù lao thỏa đáng có thể giúp các bệnh viện công thu hút điều dưỡng có chuyên môn và giữ chân nhân viên giàu kinh nghiệm lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"fair remuneration","vi":"thù lao công bằng"},{"en":"remuneration package","vi":"gói đãi ngộ"},{"en":"remuneration for services","vi":"tiền thù lao dịch vụ"}],"wordFamily":["remunerate (v.)","remunerative (adj.)"],"synonyms":["pay","payment","compensation"],"antonyms":[],"tipVi":"Thuật ngữ mang tính trang trọng, thường là danh từ không đếm được, chỉ tiền công lao động chứ không dùng cho bồi thường thiệt hại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_morale', 'en-c1-38', 'morale', '/məˈræl/', 'C1', 'tinh thần chiến đấu; sĩ khí và sự nhiệt huyết của một tập thể', 'n.', NULL, 'Đồng nghĩa: spirits', 'Là danh từ không đếm được; morale chỉ sĩ khí, còn moral chỉ đạo đức.', 'Our coach''s cheerful speech lifted morale before the match.', NULL, 'Bài phát biểu đầy hứng khởi của huấn luyện viên đã vực dậy tinh thần toàn đội trước trận đấu.', '{"wordId":"morale","ukIpa":"/məˈrɑːl/","usIpa":"/məˈræl/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"the confidence and enthusiasm of a group","vi":"tinh thần chiến đấu; sĩ khí và sự nhiệt huyết của một tập thể"}],"examples":[{"en":"Our coach''s cheerful speech lifted morale before the match.","vi":"Bài phát biểu đầy hứng khởi của huấn luyện viên đã vực dậy tinh thần toàn đội trước trận đấu.","audioKind":"ex"},{"en":"Recognising employees'' achievements can improve workplace morale and encourage greater cooperation across different departments.","vi":"Việc công nhận thành tích của nhân viên có thể nâng cao tinh thần làm việc tại nơi công sở và thúc đẩy sự hợp tác chặt chẽ hơn giữa các phòng ban.","audioKind":"ex2"}],"collocations":[{"en":"boost morale","vi":"vực dậy sĩ khí"},{"en":"low morale","vi":"tinh thần sa sút"},{"en":"staff morale","vi":"tinh thần làm việc của nhân viên"}],"wordFamily":[],"synonyms":["spirits"],"antonyms":[],"tipVi":"Là danh từ không đếm được; morale chỉ sĩ khí, còn moral chỉ đạo đức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diligent', 'en-c1-38', 'diligent', '/ˈdɪlɪdʒənt/', 'C1', 'siêng năng; cần cù; chăm chỉ', 'adj.', 'diligence (n.), diligently (adv.)', 'Đồng nghĩa: hard-working, industrious · Trái nghĩa: lazy, careless', 'Không chỉ chỉ sự nỗ lực, từ này còn nhấn mạnh tính cẩn trọng, tỉ mỉ và sự đầu tư bền bỉ.', 'Our diligent neighbour checks her vegetable plants every morning.', NULL, 'Người hàng xóm chăm chỉ của chúng tôi kiểm tra các luống rau của cô ấy mỗi buổi sáng.', '{"wordId":"diligent","ukIpa":"/ˈdɪlɪdʒənt/","usIpa":"/ˈdɪlɪdʒənt/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Working carefully and consistently with strong effort","vi":"siêng năng; cần cù; chăm chỉ"}],"examples":[{"en":"Our diligent neighbour checks her vegetable plants every morning.","vi":"Người hàng xóm chăm chỉ của chúng tôi kiểm tra các luống rau của cô ấy mỗi buổi sáng.","audioKind":"ex"},{"en":"Diligent research helps students develop stronger arguments and avoid relying on inaccurate information in academic essays.","vi":"Nghiên cứu công phu và cẩn thận giúp học sinh phát triển các lập luận thuyết phục hơn và tránh phụ thuộc vào thông tin không chính xác trong các bài tiểu luận học thuật.","audioKind":"ex2"}],"collocations":[{"en":"diligent student","vi":"học sinh chăm chỉ"},{"en":"diligent research","vi":"nghiên cứu cẩn thận; nghiên cứu công phu"},{"en":"diligent in one''s work","vi":"làm việc tận tụy; tận tâm trong công việc"}],"wordFamily":["diligence (n.)","diligently (adv.)"],"synonyms":["hard-working","industrious"],"antonyms":["lazy","careless"],"tipVi":"Không chỉ chỉ sự nỗ lực, từ này còn nhấn mạnh tính cẩn trọng, tỉ mỉ và sự đầu tư bền bỉ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disciplinary', 'en-c1-38', 'disciplinary', '/ˈdɪsəpləneri/', 'C1', 'thuộc kỷ luật; mang tính trừng phạt; thuộc lĩnh vực học thuật; thuộc chuyên ngành', 'adj.', 'discipline (n.), discipline (v.), disciplined (adj.), interdisciplinary (adj.)', NULL, 'Thường gặp trong cụm disciplinary action, chỉ các hình thức xử lý kỷ luật.', 'The coach took disciplinary action after repeated rule violations.', NULL, 'Huấn luyện viên đã đưa ra các biện pháp kỷ luật sau nhiều lần vi phạm nội quy.', '{"wordId":"disciplinary","ukIpa":"/ˈdɪsəplɪnəri/","usIpa":"/ˈdɪsəpləneri/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"relating to punishment for breaking rules","vi":"thuộc kỷ luật; mang tính trừng phạt"},{"pos":"adj.","en":"relating to a particular field of academic study","vi":"thuộc lĩnh vực học thuật; thuộc chuyên ngành"}],"examples":[{"en":"The coach took disciplinary action after repeated rule violations.","vi":"Huấn luyện viên đã đưa ra các biện pháp kỷ luật sau nhiều lần vi phạm nội quy.","audioKind":"ex"},{"en":"Schools should ensure that disciplinary procedures are fair and give students an opportunity to explain their behaviour.","vi":"Các trường học nên đảm bảo rằng các thủ tục kỷ luật diễn ra công bằng và tạo cơ hội cho học sinh giải thích hành vi của mình.","audioKind":"ex2"}],"collocations":[{"en":"disciplinary action","vi":"biện pháp kỷ luật"},{"en":"disciplinary hearing","vi":"phiên điều trần kỷ luật"},{"en":"disciplinary procedures","vi":"quy trình kỷ luật"},{"en":"disciplinary boundaries","vi":"ranh giới giữa các ngành học"}],"wordFamily":["discipline (n.)","discipline (v.)","disciplined (adj.)","interdisciplinary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường gặp trong cụm disciplinary action, chỉ các hình thức xử lý kỷ luật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tradesman', 'en-c1-38', 'tradesman', '/ˈtreɪdzmən/', 'C1', 'thợ thủ công; thợ lành nghề; thương nhân; chủ cửa hàng', 'n.', 'trade (n.), tradesperson (n.), tradeswoman (n.)', 'Đồng nghĩa: craftsman', 'Dạng số nhiều là tradesmen; từ thay thế trung lập về giới tính là tradesperson.', 'A local tradesman repaired the broken window before lunch.', NULL, 'Một thợ kỹ thuật địa phương đã sửa chiếc cửa sổ bị vỡ trước bữa trưa.', '{"wordId":"tradesman","ukIpa":"/ˈtreɪdzmən/","usIpa":"/ˈtreɪdzmən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A man skilled in practical work such as plumbing or carpentry.","vi":"thợ thủ công; thợ lành nghề"},{"pos":"n.","en":"A man who buys and sells goods, especially a shopkeeper.","vi":"thương nhân; chủ cửa hàng"}],"examples":[{"en":"A local tradesman repaired the broken window before lunch.","vi":"Một thợ kỹ thuật địa phương đã sửa chiếc cửa sổ bị vỡ trước bữa trưa.","audioKind":"ex"},{"en":"Employing a qualified tradesman for electrical repairs can reduce safety risks and prevent costly damage to property.","vi":"Thuê một thợ lành nghề có chuyên môn để sửa chữa hệ thống điện có thể giảm thiểu rủi ro an toàn và tránh những thiệt hại tốn kém cho tài sản.","audioKind":"ex2"}],"collocations":[{"en":"a skilled tradesman","vi":"thợ cả lành nghề"},{"en":"a qualified tradesman","vi":"thợ có chuyên môn"},{"en":"a local tradesman","vi":"thợ thủ công địa phương"}],"wordFamily":["trade (n.)","tradesperson (n.)","tradeswoman (n.)"],"synonyms":["craftsman"],"antonyms":[],"tipVi":"Dạng số nhiều là tradesmen; từ thay thế trung lập về giới tính là tradesperson.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_utilise', 'en-c1-38', 'utilise', '/ˈjuːtəlaɪz/', 'C1', 'tận dụng; sử dụng (dùng cái gì đó hiệu quả cho một mục đích cụ thể)', 'v.', 'utilisation (n.), utilisable (adj.)', 'Đồng nghĩa: use, employ', 'Cách viết theo Anh-Anh, cũng có thể viết là utilize; trong văn phong hàng ngày thường dùng từ use.', 'We utilise the spare room as a small office.', NULL, 'Chúng tôi tận dụng căn phòng trống làm văn phòng nhỏ.', '{"wordId":"utilise","ukIpa":"/ˈjuːtəlaɪz/","usIpa":"/ˈjuːtəlaɪz/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to use something effectively for a particular purpose","vi":"tận dụng; sử dụng (dùng cái gì đó hiệu quả cho một mục đích cụ thể)"}],"examples":[{"en":"We utilise the spare room as a small office.","vi":"Chúng tôi tận dụng căn phòng trống làm văn phòng nhỏ.","audioKind":"ex"},{"en":"Cities can utilise empty buildings to provide affordable housing and reduce pressure on surrounding farmland.","vi":"Các thành phố có thể tận dụng các tòa nhà bỏ hoang để cung cấp nhà ở giá rẻ và giảm áp lực lên đất nông nghiệp xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"utilise resources","vi":"tận dụng tài nguyên"},{"en":"fully utilise","vi":"tận dụng triệt để"},{"en":"utilise technology","vi":"ứng dụng công nghệ"}],"wordFamily":["utilisation (n.)","utilisable (adj.)"],"synonyms":["use","employ"],"antonyms":[],"tipVi":"Cách viết theo Anh-Anh, cũng có thể viết là utilize; trong văn phong hàng ngày thường dùng từ use.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strategic', 'en-c1-38', 'strategic', '/strəˈtiːdʒɪk/', 'C1', 'mang tính chiến lược (liên quan đến các kế hoạch nhằm đạt được mục tiêu dài hạn quan trọng); có ý nghĩa chiến lược (đặc biệt hữu ích để giành lợi thế)', 'adj.', 'strategy (n.), strategically (adv.), strategist (n.)', NULL, 'strategic thiên về hoạch định tổng thể dài hạn, trong khi tactical nhấn mạnh tính chiến thuật cụ thể.', 'We made a strategic decision to save before moving.', NULL, 'Chúng tôi đã đưa ra quyết định mang tính chiến lược là tiết kiệm tiền trước khi chuyển đi.', '{"wordId":"strategic","ukIpa":"/strəˈtiːdʒɪk/","usIpa":"/strəˈtiːdʒɪk/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"relating to plans for achieving important long-term goals","vi":"mang tính chiến lược (liên quan đến các kế hoạch nhằm đạt được mục tiêu dài hạn quan trọng)"},{"pos":"adj.","en":"especially useful for gaining an advantage","vi":"có ý nghĩa chiến lược (đặc biệt hữu ích để giành lợi thế)"}],"examples":[{"en":"We made a strategic decision to save before moving.","vi":"Chúng tôi đã đưa ra quyết định mang tính chiến lược là tiết kiệm tiền trước khi chuyển đi.","audioKind":"ex"},{"en":"Strategic investment in public transport can reduce congestion and support economic growth over the long term.","vi":"Đầu tư chiến lược vào giao thông công cộng có thể làm giảm tình trạng tắc nghẽn và hỗ trợ tăng trưởng kinh tế trong dài hạn.","audioKind":"ex2"}],"collocations":[{"en":"strategic planning","vi":"lập kế hoạch chiến lược"},{"en":"strategic decision","vi":"quyết định mang tính chiến lược"},{"en":"strategic location","vi":"vị trí chiến lược"},{"en":"strategic investment","vi":"đầu tư chiến lược"}],"wordFamily":["strategy (n.)","strategically (adv.)","strategist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"strategic thiên về hoạch định tổng thể dài hạn, trong khi tactical nhấn mạnh tính chiến thuật cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proprietor', 'en-c1-38', 'proprietor', '/prəˈpraɪətər/', 'C1', 'chủ doanh nghiệp; chủ tiệm (chủ sở hữu của một cơ sở kinh doanh như cửa hàng hoặc khách sạn)', 'n.', 'proprietorship (n.), proprietary (adj.)', 'Đồng nghĩa: owner', 'Từ trang trọng, thường chỉ người sở hữu các cơ sở kinh doanh như cửa hàng, khách sạn.', 'The bakery''s proprietor greeted every customer with a smile.', NULL, 'Chủ tiệm bánh mì mỉm cười chào đón mọi khách hàng.', '{"wordId":"proprietor","ukIpa":"/prəˈpraɪətə/","usIpa":"/prəˈpraɪətər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"The owner of a business, such as a shop or hotel.","vi":"chủ doanh nghiệp; chủ tiệm (chủ sở hữu của một cơ sở kinh doanh như cửa hàng hoặc khách sạn)"}],"examples":[{"en":"The bakery''s proprietor greeted every customer with a smile.","vi":"Chủ tiệm bánh mì mỉm cười chào đón mọi khách hàng.","audioKind":"ex"},{"en":"An independent shop proprietor may struggle to compete with larger retailers that can negotiate lower wholesale prices.","vi":"Chủ một cửa hàng độc lập có thể gặp khó khăn khi cạnh tranh với các nhà bán lẻ lớn hơn, những bên có khả năng đàm phán mức giá bán sỉ thấp hơn.","audioKind":"ex2"}],"collocations":[{"en":"sole proprietor","vi":"chủ doanh nghiệp tư nhân"},{"en":"shop proprietor","vi":"chủ cửa hàng"},{"en":"hotel proprietor","vi":"chủ khách sạn"}],"wordFamily":["proprietorship (n.)","proprietary (adj.)"],"synonyms":["owner"],"antonyms":[],"tipVi":"Từ trang trọng, thường chỉ người sở hữu các cơ sở kinh doanh như cửa hàng, khách sạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mishandle', 'en-c1-38', 'mishandle', '/ˌmɪsˈhændəl/', 'C1', 'xử lý kém; giải quyết tồi; thao tác cẩu thả; bốc vác bất cẩn', 'v.', 'mishandling (n.), handle (v.)', 'Đồng nghĩa: mismanage', 'Có thể dùng cho cả việc xử lý tình huống hoặc công việc kém, lẫn việc cầm nắm, di chuyển đồ vật bất cẩn.', 'The hotel mishandled our booking and gave away our room.', NULL, 'Khách sạn đã xử lý sai sót việc đặt phòng của chúng tôi và đem nhượng phòng cho người khác.', '{"wordId":"mishandle","ukIpa":"/ˌmɪsˈhændəl/","usIpa":"/ˌmɪsˈhændəl/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to deal with a situation or responsibility badly","vi":"xử lý kém; giải quyết tồi"},{"pos":"v.","en":"to handle an object carelessly or incorrectly","vi":"thao tác cẩu thả; bốc vác bất cẩn"}],"examples":[{"en":"The hotel mishandled our booking and gave away our room.","vi":"Khách sạn đã xử lý sai sót việc đặt phòng của chúng tôi và đem nhượng phòng cho người khác.","audioKind":"ex"},{"en":"When authorities mishandle public complaints, citizens may lose confidence in local institutions and become less willing to cooperate.","vi":"Khi cơ quan chức năng không xử lý thỏa đáng các khiếu nại của công chúng, người dân có thể mất lòng tin vào các tổ chức địa phương và ít sẵn lòng hợp tác hơn.","audioKind":"ex2"}],"collocations":[{"en":"mishandle a complaint","vi":"xử lý khiếu nại kém"},{"en":"mishandle a crisis","vi":"xử lý khủng hoảng kém"},{"en":"mishandle luggage","vi":"bốc vác hành lý bất cẩn"}],"wordFamily":["mishandling (n.)","handle (v.)"],"synonyms":["mismanage"],"antonyms":[],"tipVi":"Có thể dùng cho cả việc xử lý tình huống hoặc công việc kém, lẫn việc cầm nắm, di chuyển đồ vật bất cẩn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_turnover', 'en-c1-38', 'turnover', '/ˈtɝːnoʊvər/', 'C1', 'doanh thu; tổng doanh số; tỷ lệ nhân viên nghỉ việc', 'n.', NULL, NULL, 'Doanh thu không đồng nghĩa với lợi nhuận; trong tiếng Anh-Mỹ nghĩa này thường dùng từ revenue.', 'Our bakery''s turnover rose after we started selling sandwiches.', NULL, 'Doanh thu của tiệm bánh chúng tôi đã tăng sau khi chúng tôi bắt đầu bán bánh mì kẹp.', '{"wordId":"turnover","ukIpa":"/ˈtɜːnəʊvə/","usIpa":"/ˈtɝːnoʊvər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"the total value of a business''s sales during a period","vi":"doanh thu; tổng doanh số"},{"pos":"n.","en":"the rate at which employees leave and are replaced","vi":"tỷ lệ nhân viên nghỉ việc"}],"examples":[{"en":"Our bakery''s turnover rose after we started selling sandwiches.","vi":"Doanh thu của tiệm bánh chúng tôi đã tăng sau khi chúng tôi bắt đầu bán bánh mì kẹp.","audioKind":"ex"},{"en":"High staff turnover can increase recruitment costs and make it difficult for companies to maintain consistent service.","vi":"Tỷ lệ nhân viên nghỉ việc cao có thể làm tăng chi phí tuyển dụng và khiến các công ty khó duy trì chất lượng dịch vụ ổn định.","audioKind":"ex2"}],"collocations":[{"en":"annual turnover","vi":"doanh thu hàng năm"},{"en":"staff turnover","vi":"tỷ lệ nhân viên nghỉ việc"},{"en":"high turnover","vi":"tỷ lệ luân chuyển cao; doanh thu cao"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Doanh thu không đồng nghĩa với lợi nhuận; trong tiếng Anh-Mỹ nghĩa này thường dùng từ revenue.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_predecessor', 'en-c1-38', 'predecessor', '/ˈpredəsesər/', 'C1', 'người tiền nhiệm; người giữ chức vụ trước; tiền thân; thế hệ trước (của một vật)', 'n.', NULL, 'Đồng nghĩa: forerunner · Trái nghĩa: successor', 'Chỉ dùng cho người tiền nhiệm trong công việc hoặc vật tiền thân, không dùng cho mọi loại tiền bối.', 'My predecessor left some helpful notes in the desk.', NULL, 'Người tiền nhiệm của tôi đã để lại một vài ghi chú hữu ích trong ngăn bàn.', '{"wordId":"predecessor","ukIpa":"/ˈpriːdɪsesə/","usIpa":"/ˈpredəsesər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Someone who held a particular position before another person.","vi":"người tiền nhiệm; người giữ chức vụ trước"},{"pos":"n.","en":"Something that existed before and was replaced by something similar.","vi":"tiền thân; thế hệ trước (của một vật)"}],"examples":[{"en":"My predecessor left some helpful notes in the desk.","vi":"Người tiền nhiệm của tôi đã để lại một vài ghi chú hữu ích trong ngăn bàn.","audioKind":"ex"},{"en":"The new transport system uses less energy than its predecessor while carrying substantially more passengers.","vi":"Hệ thống vận tải mới tiêu thụ ít năng lượng hơn so với thế hệ tiền thân nhưng lại vận chuyển được lượng hành khách lớn hơn đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"an immediate predecessor","vi":"người tiền nhiệm trực tiếp"},{"en":"a predecessor in office","vi":"người tiền nhiệm trong chức vụ"},{"en":"replace its predecessor","vi":"thay thế tiền thân của nó"}],"wordFamily":[],"synonyms":["forerunner"],"antonyms":["successor"],"tipVi":"Chỉ dùng cho người tiền nhiệm trong công việc hoặc vật tiền thân, không dùng cho mọi loại tiền bối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_counter-offer', 'en-c1-38', 'counter-offer', '/ˈkaʊntərˌɔːfər/', 'C1', 'đề nghị ngược lại; giá trả lại; sự phản đề xuất', 'n.', 'offer (n.), offer (v.)', NULL, 'Có thể viết là counteroffer; không chỉ có nghĩa trả giá mà còn dùng khi sửa đổi các điều kiện thỏa thuận.', 'The seller rejected our price and made a counter-offer.', NULL, 'Người bán từ chối mức giá của chúng tôi và đưa ra một lời đề nghị khác.', '{"wordId":"counter-offer","ukIpa":"/ˈkaʊntərˌɒfə/","usIpa":"/ˈkaʊntərˌɔːfər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A different offer made in response to an earlier offer.","vi":"đề nghị ngược lại; giá trả lại; sự phản đề xuất"}],"examples":[{"en":"The seller rejected our price and made a counter-offer.","vi":"Người bán từ chối mức giá của chúng tôi và đưa ra một lời đề nghị khác.","audioKind":"ex"},{"en":"Employers may make a counter-offer when skilled employees announce plans to accept a position elsewhere.","vi":"Các nhà tuyển dụng có thể đưa ra mức đãi ngộ mới khi những nhân viên lành nghề thông báo ý định nhận công việc ở nơi khác.","audioKind":"ex2"}],"collocations":[{"en":"make a counter-offer","vi":"đưa ra giá trả lại"},{"en":"accept a counter-offer","vi":"chấp nhận đề nghị ngược lại"},{"en":"reject a counter-offer","vi":"từ chối lời đề nghị khác"}],"wordFamily":["offer (n.)","offer (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể viết là counteroffer; không chỉ có nghĩa trả giá mà còn dùng khi sửa đổi các điều kiện thỏa thuận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_redundancy', 'en-c1-38', 'redundancy', '/rɪˈdʌndənsi/', 'C1', 'sự sa thải; việc mất việc do nhà tuyển dụng cắt giảm vị trí; sự dư thừa; sự lặp lại không cần thiết; phần tử dự phòng; hệ thống dự phòng', 'n.', 'redundant (adj.)', NULL, 'Trong tiếng Anh-Anh thường chỉ việc sa thải nhân sự; trong bối cảnh kỹ thuật có thể chỉ các cấu hình dự phòng đảm bảo hệ thống vận hành.', 'After the factory closed, Elena faced redundancy and financial uncertainty.', NULL, 'Sau khi nhà máy đóng cửa, Elena phải đối mặt với tình trạng mất việc làm và sự bất ổn về tài chính.', '{"wordId":"redundancy","ukIpa":"/rɪˈdʌndənsi/","usIpa":"/rɪˈdʌndənsi/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Job loss because an employer no longer needs the position.","vi":"sự sa thải; việc mất việc do nhà tuyển dụng cắt giảm vị trí"},{"pos":"n.","en":"Unnecessary repetition or the presence of something not needed.","vi":"sự dư thừa; sự lặp lại không cần thiết"},{"pos":"n.","en":"Extra components that keep a system working if others fail.","vi":"phần tử dự phòng; hệ thống dự phòng"}],"examples":[{"en":"After the factory closed, Elena faced redundancy and financial uncertainty.","vi":"Sau khi nhà máy đóng cửa, Elena phải đối mặt với tình trạng mất việc làm và sự bất ổn về tài chính.","audioKind":"ex"},{"en":"Automation may increase productivity, but employers should offer retraining to workers at risk of redundancy.","vi":"Tự động hóa có thể nâng cao năng suất, nhưng các nhà tuyển dụng nên cung cấp chương trình đào tạo lại cho những người lao động đối mặt với nguy cơ bị sa thải.","audioKind":"ex2"}],"collocations":[{"en":"redundancy pay","vi":"tiền trợ cấp mất việc"},{"en":"compulsory redundancy","vi":"sa thải bắt buộc"},{"en":"voluntary redundancy","vi":"thôi việc tự nguyện"},{"en":"built-in redundancy","vi":"hệ thống dự phòng tích hợp"}],"wordFamily":["redundant (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh thường chỉ việc sa thải nhân sự; trong bối cảnh kỹ thuật có thể chỉ các cấu hình dự phòng đảm bảo hệ thống vận hành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_despatch', 'en-c1-38', 'despatch', '/dɪˈspætʃ/', 'C1', 'gửi đi; phái đi; sự gửi; sự phái đi; bản tin; công văn', 'v.', 'despatcher (n.)', 'Đồng nghĩa: dispatch, send', 'Despatch là cách viết biến thể theo kiểu Anh của từ dispatch, trong đó từ sau phổ biến hơn.', 'The shop will despatch your parcel tomorrow morning.', NULL, 'Cửa hàng sẽ gửi bưu kiện của bạn vào sáng mai.', '{"wordId":"despatch","ukIpa":"/dɪˈspætʃ/","usIpa":"/dɪˈspætʃ/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to send someone or something to a destination","vi":"gửi đi; phái đi"},{"pos":"n.","en":"the act of sending people or goods somewhere","vi":"sự gửi; sự phái đi"},{"pos":"n.","en":"a report sent by a journalist or official","vi":"bản tin; công văn"}],"examples":[{"en":"The shop will despatch your parcel tomorrow morning.","vi":"Cửa hàng sẽ gửi bưu kiện của bạn vào sáng mai.","audioKind":"ex"},{"en":"Emergency services must despatch rescue teams quickly when severe flooding isolates communities from essential supplies.","vi":"Các cơ quan ứng phó khẩn cấp phải nhanh chóng cử các đội cứu trợ đến khi lũ lụt nghiêm trọng cô lập các cộng đồng khỏi nguồn cung cấp thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"despatch goods","vi":"gửi hàng hóa"},{"en":"despatch a rescue team","vi":"cử đội cứu hộ"},{"en":"ready for despatch","vi":"sẵn sàng gửi đi"}],"wordFamily":["despatcher (n.)"],"synonyms":["dispatch","send"],"antonyms":[],"tipVi":"Despatch là cách viết biến thể theo kiểu Anh của từ dispatch, trong đó từ sau phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hoist', 'en-c1-38', 'hoist', '/hɔɪst/', 'C1', 'kéo lên; nâng lên (bằng dây thừng hoặc máy móc); thiết bị nâng; tời', 'v.', NULL, 'Đồng nghĩa: lift, raise · Trái nghĩa: lower', 'Nhấn mạnh việc nâng nhấc mất sức hoặc phải nhờ đến dây thừng, máy móc.', 'We hoisted the heavy suitcase onto the luggage rack.', NULL, 'Chúng tôi đã nâng chiếc vali nặng lên giá để hành lý.', '{"wordId":"hoist","ukIpa":"/hɔɪst/","usIpa":"/hɔɪst/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"lift something heavy, often using ropes or machinery","vi":"kéo lên; nâng lên (bằng dây thừng hoặc máy móc)"},{"pos":"n.","en":"a device used for lifting heavy objects","vi":"thiết bị nâng; tời"}],"examples":[{"en":"We hoisted the heavy suitcase onto the luggage rack.","vi":"Chúng tôi đã nâng chiếc vali nặng lên giá để hành lý.","audioKind":"ex"},{"en":"Construction workers use specialised equipment to hoist heavy materials safely, reducing physical strain and workplace injuries.","vi":"Công nhân xây dựng sử dụng thiết bị chuyên dụng để cẩu các vật liệu nặng một cách an toàn, giúp giảm bớt gánh nặng thể xác và chấn thương tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"hoist a flag","vi":"kéo cờ lên"},{"en":"hoist a sail","vi":"giương buồm"},{"en":"hoist into position","vi":"cẩu lên vị trí"},{"en":"electric hoist","vi":"thiết bị tời điện"}],"wordFamily":[],"synonyms":["lift","raise"],"antonyms":["lower"],"tipVi":"Nhấn mạnh việc nâng nhấc mất sức hoặc phải nhờ đến dây thừng, máy móc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adhere', 'en-c1-38', 'adhere', '/ədˈhɪr/', 'C1', 'tuân thủ; tôn trọng; bám chặt; dính vào', 'v.', 'adherence (n.), adhesion (n.), adhesive (adj.), adherent (n.)', 'Đồng nghĩa: comply, stick', 'Cả hai nghĩa phổ biến đều đi với giới từ ''to'' (adhere to); từ ''to'' ở đây đóng vai trò là giới từ.', 'Everyone must adhere to the rules in this pool.', NULL, 'Mọi người đều phải tuân thủ các quy định tại khu vực hồ bơi này.', '{"wordId":"adhere","ukIpa":"/ədˈhɪə/","usIpa":"/ədˈhɪr/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To follow a rule, belief, or agreement closely.","vi":"tuân thủ; tôn trọng"},{"pos":"v.","en":"To stick firmly to a surface.","vi":"bám chặt; dính vào"}],"examples":[{"en":"Everyone must adhere to the rules in this pool.","vi":"Mọi người đều phải tuân thủ các quy định tại khu vực hồ bơi này.","audioKind":"ex"},{"en":"Researchers must adhere to strict ethical standards when collecting personal information from participants in health studies.","vi":"Các nhà nghiên cứu phải tuân thủ nghiêm ngặt các tiêu chuẩn đạo đức khi thu thập thông tin cá nhân từ những người tham gia nghiên cứu y tế.","audioKind":"ex2"}],"collocations":[{"en":"adhere to guidelines","vi":"tuân thủ hướng dẫn"},{"en":"adhere to principles","vi":"tuân thủ nguyên tắc"},{"en":"adhere to a surface","vi":"bám dính vào bề mặt"}],"wordFamily":["adherence (n.)","adhesion (n.)","adhesive (adj.)","adherent (n.)"],"synonyms":["comply","stick"],"antonyms":[],"tipVi":"Cả hai nghĩa phổ biến đều đi với giới từ ''to'' (adhere to); từ ''to'' ở đây đóng vai trò là giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mover', 'en-c1-38', 'mover', '/ˈmuːvɚ/', 'C1', 'thợ chuyển nhà; công ty chuyển đồ; người thúc đẩy; nhân vật có sức ảnh hưởng', 'n.', 'move (v.), movement (n.), movable (adj.)', NULL, 'Nghĩa thợ chuyển nhà thường phổ biến trong tiếng Mỹ; prime mover dùng để chỉ động lực chính hoặc người dẫn dắt chính.', 'The movers carefully carried our sofa down the stairs.', NULL, 'Những người thợ chuyển nhà đã cẩn thận khiêng chiếc ghế sofa của chúng tôi xuống cầu thang.', '{"wordId":"mover","ukIpa":"/ˈmuːvə/","usIpa":"/ˈmuːvɚ/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A person or company paid to move furniture and belongings.","vi":"thợ chuyển nhà; công ty chuyển đồ"},{"pos":"n.","en":"Someone who actively helps make a change or project happen.","vi":"người thúc đẩy; nhân vật có sức ảnh hưởng"}],"examples":[{"en":"The movers carefully carried our sofa down the stairs.","vi":"Những người thợ chuyển nhà đã cẩn thận khiêng chiếc ghế sofa của chúng tôi xuống cầu thang.","audioKind":"ex"},{"en":"Local businesses were prime movers in the campaign to improve public spaces and attract visitors.","vi":"Các doanh nghiệp địa phương đóng vai trò là những người tiên phong trong chiến dịch cải thiện không gian công cộng và thu hút khách du lịch.","audioKind":"ex2"}],"collocations":[{"en":"hire movers","vi":"thuê thợ chuyển nhà"},{"en":"a prime mover","vi":"nhân tố chủ chốt"},{"en":"movers and shakers","vi":"những nhân vật có thế lực và tầm ảnh hưởng"}],"wordFamily":["move (v.)","movement (n.)","movable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa thợ chuyển nhà thường phổ biến trong tiếng Mỹ; prime mover dùng để chỉ động lực chính hoặc người dẫn dắt chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conversant', 'en-c1-38', 'conversant', '/kənˈvɝːsənt/', 'C1', 'thông thạo; am hiểu; quen thuộc', 'adj.', NULL, 'Đồng nghĩa: familiar, knowledgeable · Trái nghĩa: unfamiliar', 'Thường dùng be conversant with, biểu thị sự am hiểu một lĩnh vực, không mang nghĩa có quan hệ thân thiết.', 'Our new guide is conversant with the area''s history.', NULL, 'Hướng dẫn viên mới của chúng tôi rất am hiểu về lịch sử của khu vực này.', '{"wordId":"conversant","ukIpa":"/kənˈvɜːsənt/","usIpa":"/kənˈvɝːsənt/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Familiar with a subject and able to discuss it","vi":"thông thạo; am hiểu; quen thuộc"}],"examples":[{"en":"Our new guide is conversant with the area''s history.","vi":"Hướng dẫn viên mới của chúng tôi rất am hiểu về lịch sử của khu vực này.","audioKind":"ex"},{"en":"Graduates entering the technology sector should be conversant with current debates about privacy and data protection.","vi":"Sinh viên tốt nghiệp bước vào lĩnh vực công nghệ nên am hiểu về các cuộc tranh luận hiện nay liên quan đến quyền riêng tư và bảo vệ dữ liệu.","audioKind":"ex2"}],"collocations":[{"en":"conversant with","vi":"am hiểu về"},{"en":"fully conversant with","vi":"hoàn toàn am hiểu về"},{"en":"conversant with procedures","vi":"am hiểu các thủ tục"}],"wordFamily":[],"synonyms":["familiar","knowledgeable"],"antonyms":["unfamiliar"],"tipVi":"Thường dùng be conversant with, biểu thị sự am hiểu một lĩnh vực, không mang nghĩa có quan hệ thân thiết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_38_1', 'en-c1-38', 'Cách dùng “redundancy” (n.) — sự sa thải; việc mất việc do nhà tuyển dụng cắt giảm vị trí', 'redundancy pay  ·  compulsory redundancy  ·  voluntary redundancy', 'Trong tiếng Anh-Anh thường chỉ việc sa thải nhân sự; trong bối cảnh kỹ thuật có thể chỉ các cấu hình dự phòng đảm bảo hệ thống vận hành.', 'Họ từ (Word Family): redundant (adj.)', '[{"hanzi":"After the factory closed, Elena faced redundancy and financial uncertainty.","pinyin":"","meaning":"Sau khi nhà máy đóng cửa, Elena phải đối mặt với tình trạng mất việc làm và sự bất ổn về tài chính."},{"hanzi":"Automation may increase productivity, but employers should offer retraining to workers at risk of redundancy.","pinyin":"","meaning":"Tự động hóa có thể nâng cao năng suất, nhưng các nhà tuyển dụng nên cung cấp chương trình đào tạo lại cho những người lao động đối mặt với nguy cơ bị sa thải."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_38_2', 'en-c1-38', 'Cách dùng “remuneration” (n.) — thù lao; tiền công; chế độ đãi ngộ', 'fair remuneration  ·  remuneration package  ·  remuneration for services', 'Thuật ngữ mang tính trang trọng, thường là danh từ không đếm được, chỉ tiền công lao động chứ không dùng cho bồi thường thiệt hại.', 'Họ từ (Word Family): remunerate (v.), remunerative (adj.) | Đồng nghĩa: pay, payment, compensation', '[{"hanzi":"The job offers flexible hours but modest remuneration.","pinyin":"","meaning":"Công việc này có giờ giấc linh hoạt nhưng thù lao lại khá khiêm tốn."},{"hanzi":"Fair remuneration can help public hospitals attract qualified nurses and retain experienced staff over time.","pinyin":"","meaning":"Mức thù lao thỏa đáng có thể giúp các bệnh viện công thu hút điều dưỡng có chuyên môn và giữ chân nhân viên giàu kinh nghiệm lâu dài."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_38_3', 'en-c1-38', 'Cách dùng “mover” (n.) — thợ chuyển nhà; công ty chuyển đồ', 'hire movers  ·  a prime mover  ·  movers and shakers', 'Nghĩa thợ chuyển nhà thường phổ biến trong tiếng Mỹ; prime mover dùng để chỉ động lực chính hoặc người dẫn dắt chính.', 'Họ từ (Word Family): move (v.), movement (n.), movable (adj.)', '[{"hanzi":"The movers carefully carried our sofa down the stairs.","pinyin":"","meaning":"Những người thợ chuyển nhà đã cẩn thận khiêng chiếc ghế sofa của chúng tôi xuống cầu thang."},{"hanzi":"Local businesses were prime movers in the campaign to improve public spaces and attract visitors.","pinyin":"","meaning":"Các doanh nghiệp địa phương đóng vai trò là những người tiên phong trong chiến dịch cải thiện không gian công cộng và thu hút khách du lịch."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_38_4', 'en-c1-38', 'Cách dùng “confer” (v.) — bàn bạc; hội ý; thảo luận', 'confer with colleagues  ·  confer a degree on someone  ·  confer benefits on', 'Dùng cấu trúc confer with khi bàn bạc với ai, và confer sth on sb khi trao tặng danh hiệu hoặc quyền lợi cho ai.', 'Họ từ (Word Family): conference (n.), conferment (n.) | Đồng nghĩa: consult, bestow', '[{"hanzi":"The coaches conferred quietly before choosing the final team.","pinyin":"","meaning":"Các huấn luyện viên đã hội ý nhanh trước khi chốt đội hình thi đấu cuối cùng."},{"hanzi":"Universities often confer honorary degrees on individuals who have made outstanding contributions to science or public service.","pinyin":"","meaning":"Các trường đại học thường trao học vị danh dự cho những cá nhân có đóng góp xuất sắc cho khoa học hoặc công ích."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_38_1', 'en-c1-38', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
