INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_1_2', 'ten_c1_38_1', 'conscientious', 'Our conscientious neighbour checks our plants every morning.', 'Our conscientious neighbour checks our plants every morning.', '/ˌkɑːnʃiˈenʃəs/', 'Người hàng xóm tận tâm của chúng tôi kiểm tra các chậu cây mỗi buổi sáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_1_3', 'ten_c1_38_1', 'endeavour', 'Growing vegetables together became our family''s latest endeavour.', 'Growing vegetables together became our family''s latest endeavour.', '/ɪnˈdevər/', 'Cùng nhau trồng rau đã trở thành nỗ lực mới nhất của gia đình chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_1_4', 'ten_c1_38_1', 'weld', 'Wearing a protective mask, she welded the metal frame.', 'Wearing a protective mask, she welded the metal frame.', '/weld/', 'Đeo mặt nạ bảo hộ, cô ấy tiến hành hàn khung kim loại.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_1_5', 'ten_c1_38_1', 'outset', 'We agreed on a budget at the outset.', 'We agreed on a budget at the outset.', '/ˈaʊtset/', 'Chúng tôi đã thống nhất về ngân sách ngay từ lúc bắt đầu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_1_6', 'ten_c1_38_1', 'confer', 'The coaches conferred quietly before choosing the final team.', 'The coaches conferred quietly before choosing the final team.', '/kənˈfɜːr/', 'Các huấn luyện viên đã hội ý nhanh trước khi chốt đội hình thi đấu cuối cùng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_1_7', 'ten_c1_38_1', 'shipowner', 'The shipowner paid for repairs before the next voyage.', 'The shipowner paid for repairs before the next voyage.', '/ˈʃɪpˌoʊnər/', 'Chủ tàu đã chi trả chi phí sửa chữa trước chuyến hải trình tiếp theo.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_1_8', 'ten_c1_38_1', 'remuneration', 'The job offers flexible hours but modest remuneration.', 'The job offers flexible hours but modest remuneration.', '/rɪˌmjuːnəˈreɪʃən/', 'Công việc này có giờ giấc linh hoạt nhưng thù lao lại khá khiêm tốn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_38_1_1', 'en-c1-38', 'ten_c1_38_1', 'listening', 'listening', 'My mother was the main bread-earner in our family.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đeo mặt nạ bảo hộ, cô ấy tiến hành hàn khung kim loại.","Mẹ tôi từng là trụ cột chính trong gia đình chúng tôi.","Mọi người đều phải tuân thủ các quy định tại khu vực hồ bơi này.","Chúng tôi tận dụng căn phòng trống làm văn phòng nhỏ."]'::jsonb, 1, 'My mother was the main bread-earner in our family. → Mẹ tôi từng là trụ cột chính trong gia đình chúng tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_38_1_2', 'en-c1-38', 'ten_c1_38_1', 'listening', 'listening', 'Our conscientious neighbour checks our plants every morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người hàng xóm tận tâm của chúng tôi kiểm tra các chậu cây mỗi buổi sáng.","Người tiền nhiệm của tôi đã để lại một vài ghi chú hữu ích trong ngăn bàn.","Chúng tôi đã nâng chiếc vali nặng lên giá để hành lý.","Hướng dẫn viên mới của chúng tôi rất am hiểu về lịch sử của khu vực này."]'::jsonb, 0, 'Our conscientious neighbour checks our plants every morning. → Người hàng xóm tận tâm của chúng tôi kiểm tra các chậu cây mỗi buổi sáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_38_1_3', 'en-c1-38', 'ten_c1_38_1', 'listening', 'listening', 'Growing vegetables together became our family''s latest endeavour.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cùng nhau trồng rau đã trở thành nỗ lực mới nhất của gia đình chúng tôi.","Chúng tôi đã thống nhất về ngân sách ngay từ lúc bắt đầu.","Người hàng xóm tận tâm của chúng tôi kiểm tra các chậu cây mỗi buổi sáng.","Một thợ kỹ thuật địa phương đã sửa chiếc cửa sổ bị vỡ trước bữa trưa."]'::jsonb, 0, 'Growing vegetables together became our family''s latest endeavour. → Cùng nhau trồng rau đã trở thành nỗ lực mới nhất của gia đình chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_38_2', 'en-c1-38', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_2_1', 'ten_c1_38_2', 'bread-earner', 'Affordable childcare can help a family''s sole bread-earner remain employed while ensuring that children receive appropriate care.', 'Affordable childcare can help a family''s sole bread-earner remain employed while ensuring that children receive appropriate care.', '/ˈbred ˌɜːrnər/', 'Dịch vụ chăm sóc trẻ với chi phí phải chăng có thể giúp người kiếm tiền duy nhất trong gia đình tiếp tục làm việc đồng thời đảm bảo con cái được chăm sóc chu đáo.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_2_2', 'ten_c1_38_2', 'conscientious', 'Conscientious employees contribute to workplace safety by following procedures carefully and reporting potential hazards promptly.', 'Conscientious employees contribute to workplace safety by following procedures carefully and reporting potential hazards promptly.', '/ˌkɑːnʃiˈenʃəs/', 'Những nhân viên tận tâm góp phần đảm bảo an toàn nơi làm việc bằng cách tuân thủ cẩn thận các quy trình và kịp thời báo cáo các mối nguy hiểm tiềm ẩn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_2_3', 'ten_c1_38_2', 'endeavour', 'Governments should endeavour to make reliable public transport accessible to people in remote communities.', 'Governments should endeavour to make reliable public transport accessible to people in remote communities.', '/ɪnˈdevər/', 'Chính phủ nên nỗ lực cung cấp phương tiện giao thông công cộng đáng tin cậy cho người dân ở các cộng đồng vùng sâu vùng xa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_2_4', 'ten_c1_38_2', 'weld', 'Workers who weld steel structures need proper training and protective equipment to reduce workplace injuries.', 'Workers who weld steel structures need proper training and protective equipment to reduce workplace injuries.', '/weld/', 'Những công nhân làm công việc hàn kết cấu thép cần được đào tạo bài bản và trang bị thiết bị bảo hộ để giảm thiểu tai nạn lao động.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_2_5', 'ten_c1_38_2', 'outset', 'Community members should be involved from the outset when local authorities plan major housing developments.', 'Community members should be involved from the outset when local authorities plan major housing developments.', '/ˈaʊtset/', 'Các thành viên cộng đồng nên được tham gia ngay từ đầu khi cơ quan chức năng lên kế hoạch cho các dự án phát triển nhà ở quy mô lớn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_38_2_6', 'ten_c1_38_2', 'confer', 'Universities often confer honorary degrees on individuals who have made outstanding contributions to science or public service.', 'Universities often confer honorary degrees on individuals who have made outstanding contributions to science or public service.', '/kənˈfɜːr/', 'Các trường đại học thường trao học vị danh dự cho những cá nhân có đóng góp xuất sắc cho khoa học hoặc công ích.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_38_2_1', 'en-c1-38', 'ten_c1_38_2', 'listening', 'listening', 'Affordable childcare can help a family''s sole bread-earner remain employed while ensuring that children receive appropriate care.', NULL, 'Trong câu vừa nghe, từ “bread-earner” mang nghĩa nào sau đây?', '["phát ra tiếng kêu rít; khì khì","xa hoa, hào phóng; thịnh soạn, đắt đỏ","trụ cột gia đình; người kiếm tiền nuôi gia đình","bằng kim loại; chứa kim loại"]'::jsonb, 2, '“bread-earner” (/ˈbred ˌɜːrnər/): trụ cột gia đình; người kiếm tiền nuôi gia đình. Câu đầy đủ: Affordable childcare can help a family''s sole bread-earner remain employed while ensuring that children receive appropriate care.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_38_2_2', 'en-c1-38', 'ten_c1_38_2', 'listening', 'listening', 'Conscientious employees contribute to workplace safety by following procedures carefully and reporting potential hazards promptly.', NULL, 'Trong câu vừa nghe, từ “conscientious” mang nghĩa nào sau đây?', '["tận tâm; chu đáo; có ý thức trách nhiệm","vặt vãnh; nhỏ nhặt","làm triệt tiêu; vô hiệu hóa","công việc vất vả, nhàm chán và lặp đi lặp lại"]'::jsonb, 0, '“conscientious” (/ˌkɑːnʃiˈenʃəs/): tận tâm; chu đáo; có ý thức trách nhiệm. Câu đầy đủ: Conscientious employees contribute to workplace safety by following procedures carefully and reporting potential hazards promptly.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
