INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_1', 'en-c1-38', NULL, 'comprehensive_test', 'listening', 'bread-earner', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mốt; sự thịnh hành; phong trào","dây cương ngựa","trụ cột gia đình; người kiếm tiền nuôi gia đình","cho là; đánh giá là; coi là"]'::jsonb, 2, 'bread-earner (/ˈbred ˌɜːrnər/) → trụ cột gia đình; người kiếm tiền nuôi gia đình', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_2', 'en-c1-38', NULL, 'comprehensive_test', 'listening', 'Our conscientious neighbour checks our plants every morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Huấn luyện viên đã đưa ra các biện pháp kỷ luật sau nhiều lần vi phạm nội quy.","Cùng nhau trồng rau đã trở thành nỗ lực mới nhất của gia đình chúng tôi.","Người hàng xóm tận tâm của chúng tôi kiểm tra các chậu cây mỗi buổi sáng.","Mọi người đều phải tuân thủ các quy định tại khu vực hồ bơi này."]'::jsonb, 2, 'Our conscientious neighbour checks our plants every morning. → Người hàng xóm tận tâm của chúng tôi kiểm tra các chậu cây mỗi buổi sáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_3', 'en-c1-38', NULL, 'comprehensive_test', 'listening', 'endeavour', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chứng hoang tưởng; sự đa nghi; cảm giác bị hại","nỗ lực; sự cố gắng","gợi lên; gợi nhớ; đánh thức","tấm ván dày"]'::jsonb, 1, 'endeavour (/ɪnˈdevər/) → nỗ lực; sự cố gắng; cố gắng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_4', 'en-c1-38', NULL, 'comprehensive_test', 'listening', 'Wearing a protective mask, she welded the metal frame.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những người thợ chuyển nhà đã cẩn thận khiêng chiếc ghế sofa của chúng tôi xuống cầu thang.","Người hàng xóm chăm chỉ của chúng tôi kiểm tra các luống rau của cô ấy mỗi buổi sáng.","Đeo mặt nạ bảo hộ, cô ấy tiến hành hàn khung kim loại.","Người hàng xóm tận tâm của chúng tôi kiểm tra các chậu cây mỗi buổi sáng."]'::jsonb, 2, 'Wearing a protective mask, she welded the metal frame. → Đeo mặt nạ bảo hộ, cô ấy tiến hành hàn khung kim loại.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_5', 'en-c1-38', NULL, 'comprehensive_test', 'listening', 'outset', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hết sức cẩn trọng; tỉ mỉ; công phu","sự sai lệch; sự không nhất quán; sự khác biệt","có rất nhiều; phong phú; ngập tràn","sự bắt đầu; khởi đầu"]'::jsonb, 3, 'outset (/ˈaʊtset/) → sự bắt đầu; khởi đầu', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_6', 'en-c1-38', NULL, 'comprehensive_test', 'listening', 'The coaches conferred quietly before choosing the final team.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bài phát biểu đầy hứng khởi của huấn luyện viên đã vực dậy tinh thần toàn đội trước trận đấu.","Chúng tôi tận dụng căn phòng trống làm văn phòng nhỏ.","Một thợ kỹ thuật địa phương đã sửa chiếc cửa sổ bị vỡ trước bữa trưa.","Các huấn luyện viên đã hội ý nhanh trước khi chốt đội hình thi đấu cuối cùng."]'::jsonb, 3, 'The coaches conferred quietly before choosing the final team. → Các huấn luyện viên đã hội ý nhanh trước khi chốt đội hình thi đấu cuối cùng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_7', 'en-c1-38', NULL, 'comprehensive_test', 'listening', 'shipowner', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thô; nhám; thô ráp","chủ tàu; công ty sở hữu tàu thuyền","làm nhanh hơn; đẩy nhanh; thúc đẩy","rây (bột, cát); sàng"]'::jsonb, 1, 'shipowner (/ˈʃɪpˌoʊnər/) → chủ tàu; công ty sở hữu tàu thuyền', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_8', 'en-c1-38', NULL, 'comprehensive_test', 'listening', 'The job offers flexible hours but modest remuneration.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Công việc này có giờ giấc linh hoạt nhưng thù lao lại khá khiêm tốn.","Cửa hàng sẽ gửi bưu kiện của bạn vào sáng mai.","Những người thợ chuyển nhà đã cẩn thận khiêng chiếc ghế sofa của chúng tôi xuống cầu thang.","Khách sạn đã xử lý sai sót việc đặt phòng của chúng tôi và đem nhượng phòng cho người khác."]'::jsonb, 0, 'The job offers flexible hours but modest remuneration. → Công việc này có giờ giấc linh hoạt nhưng thù lao lại khá khiêm tốn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_9', 'en-c1-38', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The beginning of an activity, process, or period.”?', '["proprietor","conscientious","outset","shipowner"]'::jsonb, 2, 'outset (/ˈaʊtset/) → sự bắt đầu; khởi đầu', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_10', 'en-c1-38', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Discuss something with others before making a decision.”?', '["confer","utilise","weld","shipowner"]'::jsonb, 0, 'confer (/kənˈfɜːr/) → bàn bạc; hội ý; thảo luận', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_11', 'en-c1-38', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A person or company that owns ships.”?', '["confer","shipowner","mishandle","diligent"]'::jsonb, 1, 'shipowner (/ˈʃɪpˌoʊnər/) → chủ tàu; công ty sở hữu tàu thuyền', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_12', 'en-c1-38', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “payment received for work or services”?', '["weld","mishandle","conversant","remuneration"]'::jsonb, 3, 'remuneration (/rɪˌmjuːnəˈreɪʃən/) → thù lao; tiền công; chế độ đãi ngộ', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_13', 'en-c1-38', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the confidence and enthusiasm of a group”?', '["morale","counter-offer","weld","redundancy"]'::jsonb, 0, 'morale (/məˈræl/) → tinh thần chiến đấu; sĩ khí và sự nhiệt huyết của một tập thể', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
