INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_18', 'en-c1-38', NULL, 'comprehensive_test', 'reading', NULL, 'Affordable childcare can help a family''s sole bread-earner remain employed while ensuring that children receive appropriate care.', 'Dựa vào câu trên, từ “bread-earner” có nghĩa phù hợp nhất là gì?', '["trụ cột gia đình; người kiếm tiền nuôi gia đình","nhanh nhẹn; khẩn trương","phụ; dự phòng; bổ trợ","nổi tiếng và được ngưỡng mộ rộng rãi nhờ một phẩm chất hoặc thành tựu cụ thể"]'::jsonb, 0, 'bread-earner: trụ cột gia đình; người kiếm tiền nuôi gia đình. Dịch cả câu: Dịch vụ chăm sóc trẻ với chi phí phải chăng có thể giúp người kiếm tiền duy nhất trong gia đình tiếp tục làm việc đồng thời đảm bảo con cái được chăm sóc chu đáo.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_19', 'en-c1-38', NULL, 'comprehensive_test', 'reading', NULL, 'Conscientious employees contribute to workplace safety by following procedures carefully and reporting potential hazards promptly.', 'Dựa vào câu trên, từ “conscientious” có nghĩa phù hợp nhất là gì?', '["sự máy tính hóa; sự tin học hóa","có nhiều hơn một cách hiểu hoặc cách giải thích; mơ hồ, có ẩn ý, lập lờ","quyền độc quyền; quyền phân phối hoặc sử dụng độc quyền","tận tâm; chu đáo; có ý thức trách nhiệm"]'::jsonb, 3, 'conscientious: tận tâm; chu đáo; có ý thức trách nhiệm. Dịch cả câu: Những nhân viên tận tâm góp phần đảm bảo an toàn nơi làm việc bằng cách tuân thủ cẩn thận các quy trình và kịp thời báo cáo các mối nguy hiểm tiềm ẩn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_20', 'en-c1-38', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should endeavour to make reliable public transport accessible to people in remote communities.', 'Dựa vào câu trên, từ “endeavour” có nghĩa phù hợp nhất là gì?', '["sự sa thải; việc mất việc do nhà tuyển dụng cắt giảm vị trí","tư thế; dáng đi đứng","xứng đáng; đáng","nỗ lực; sự cố gắng"]'::jsonb, 3, 'endeavour: nỗ lực; sự cố gắng; cố gắng. Dịch cả câu: Chính phủ nên nỗ lực cung cấp phương tiện giao thông công cộng đáng tin cậy cho người dân ở các cộng đồng vùng sâu vùng xa.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_21', 'en-c1-38', NULL, 'comprehensive_test', 'reading', NULL, 'Workers who weld steel structures need proper training and protective equipment to reduce workplace injuries.', 'Dựa vào câu trên, từ “weld” có nghĩa phù hợp nhất là gì?', '["tiếp thu và lĩnh hội hoàn toàn thông tin hoặc ý tưởng mới","oxi hóa","đồng xu giả định; thẻ cào; phiếu quà tặng","hàn (nối các chi tiết kim loại bằng cách nung nóng cho đến khi chúng chảy dính vào nhau)"]'::jsonb, 3, 'weld: hàn (nối các chi tiết kim loại bằng cách nung nóng cho đến khi chúng chảy dính vào nhau); mối hàn; chỗ hàn. Dịch cả câu: Những công nhân làm công việc hàn kết cấu thép cần được đào tạo bài bản và trang bị thiết bị bảo hộ để giảm thiểu tai nạn lao động.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_22', 'en-c1-38', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tuân thủ; tôn trọng”', '["invalidate","differentiate","adhere","pretext"]'::jsonb, 2, 'tuân thủ; tôn trọng → adhere (/ədˈhɪr/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_23', 'en-c1-38', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thợ chuyển nhà; công ty chuyển đồ”', '["theatrical","baffle","mover","dazzling"]'::jsonb, 2, 'thợ chuyển nhà; công ty chuyển đồ → mover (/ˈmuːvɚ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_38_24', 'en-c1-38', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thông thạo; am hiểu; quen thuộc”', '["persistence","perplex","conversant","eclipse"]'::jsonb, 2, 'thông thạo; am hiểu; quen thuộc → conversant (/kənˈvɝːsənt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-39', 'en', 'Bài 39: Công việc & Nghề nghiệp (4) - CEFR C1', 'CEFR C1', 'C1 · Công việc', '24 từ vựng Tiếng Anh CEFR C1 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5039, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shelve', 'en-c1-39', 'shelve', '/ʃelv/', 'C1', 'gác lại; tạm hoãn; đặt lên kệ', 'v.', 'shelf (n.), shelving (n.)', 'Đồng nghĩa: postpone, defer', 'Shelve là động từ; shelf là danh từ, số nhiều là shelves.', 'We shelved our holiday plans when the car broke down.', NULL, 'Chúng tôi đã gác lại kế hoạch nghỉ mát khi chiếc xe bị hỏng.', '{"wordId":"shelve","ukIpa":"/ʃelv/","usIpa":"/ʃelv/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to stop considering or working on something for now","vi":"gác lại; tạm hoãn"},{"pos":"v.","en":"to put something on a shelf","vi":"đặt lên kệ"}],"examples":[{"en":"We shelved our holiday plans when the car broke down.","vi":"Chúng tôi đã gác lại kế hoạch nghỉ mát khi chiếc xe bị hỏng.","audioKind":"ex"},{"en":"The council decided to shelve the road expansion project because of concerns about air pollution.","vi":"Hội đồng quyết định tạm hoãn dự án mở rộng đường vì lo ngại về ô nhiễm không khí.","audioKind":"ex2"}],"collocations":[{"en":"shelve a plan","vi":"gác lại một kế hoạch"},{"en":"shelve a proposal","vi":"tạm hoãn một đề xuất"},{"en":"shelve books","vi":"xếp sách lên kệ"}],"wordFamily":["shelf (n.)","shelving (n.)"],"synonyms":["postpone","defer"],"antonyms":[],"tipVi":"Shelve là động từ; shelf là danh từ, số nhiều là shelves.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vocation', 'en-c1-39', 'vocation', '/voʊˈkeɪʃən/', 'C1', 'sứ mệnh; công việc phù hợp với tâm huyết bản thân; nghề nghiệp; công việc chuyên môn', 'n.', 'vocational (adj.), vocationally (adv.)', 'Đồng nghĩa: calling, occupation', 'Thường mang nghĩa sứ mệnh hoặc tiếng gọi tâm linh; tránh nhầm lẫn với vacation (kỳ nghỉ).', 'Caring for injured animals became her vocation early in life.', NULL, 'Việc chăm sóc những loài động vật bị thương đã trở thành sứ mệnh cuộc đời cô ấy từ khi còn trẻ.', '{"wordId":"vocation","ukIpa":"/vəʊˈkeɪʃən/","usIpa":"/voʊˈkeɪʃən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"work you feel strongly suited or called to do","vi":"sứ mệnh; công việc phù hợp với tâm huyết bản thân"},{"pos":"n.","en":"a particular occupation, especially one requiring training","vi":"nghề nghiệp; công việc chuyên môn"}],"examples":[{"en":"Caring for injured animals became her vocation early in life.","vi":"Việc chăm sóc những loài động vật bị thương đã trở thành sứ mệnh cuộc đời cô ấy từ khi còn trẻ.","audioKind":"ex"},{"en":"Career guidance should help young people discover a vocation that matches their abilities and values.","vi":"Tư vấn hướng nghiệp nên giúp giới trẻ khám phá ra một định hướng sự nghiệp phù hợp với năng lực và giá trị của bản thân.","audioKind":"ex2"}],"collocations":[{"en":"find one''s vocation","vi":"tìm ra sứ mệnh của cuộc đời mình"},{"en":"a sense of vocation","vi":"cảm giác có thiên hướng nghề nghiệp"},{"en":"a vocation for teaching","vi":"năng khiếu và đam mê giảng dạy"}],"wordFamily":["vocational (adj.)","vocationally (adv.)"],"synonyms":["calling","occupation"],"antonyms":[],"tipVi":"Thường mang nghĩa sứ mệnh hoặc tiếng gọi tâm linh; tránh nhầm lẫn với vacation (kỳ nghỉ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_affiliate', 'en-c1-39', 'affiliate', '/əˈfɪlieɪt/', 'C1', 'liên kết; sáp nhập; gia nhập vào tổ chức lớn; chi nhánh; tổ chức liên kết trực thuộc', 'v.', 'affiliation (n.), affiliated (adj.)', NULL, 'Khi đóng vai trò danh từ, âm cuối đọc là /ət/; khi là động từ, âm cuối đọc là /eɪt/.', 'Our local cycling club is affiliated with a national organisation.', NULL, 'Câu lạc bộ xe đạp địa phương của chúng tôi trực thuộc một tổ chức cấp quốc gia.', '{"wordId":"affiliate","ukIpa":"/əˈfɪlieɪt/","usIpa":"/əˈfɪlieɪt/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To officially connect a person or group with an organisation.","vi":"liên kết; sáp nhập; gia nhập vào tổ chức lớn"},{"pos":"n.","en":"An organisation officially connected with a larger organisation.","vi":"chi nhánh; tổ chức liên kết trực thuộc"}],"examples":[{"en":"Our local cycling club is affiliated with a national organisation.","vi":"Câu lạc bộ xe đạp địa phương của chúng tôi trực thuộc một tổ chức cấp quốc gia.","audioKind":"ex"},{"en":"Small research institutes often affiliate with universities to gain access to specialist equipment and academic expertise.","vi":"Các viện nghiên cứu nhỏ thường liên kết với các trường đại học để tiếp cận thiết bị chuyên dụng và chuyên môn học thuật.","audioKind":"ex2"}],"collocations":[{"en":"affiliate with","vi":"liên kết với"},{"en":"be affiliated with","vi":"trực thuộc với..."},{"en":"a local affiliate","vi":"một chi nhánh địa phương"}],"wordFamily":["affiliation (n.)","affiliated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi đóng vai trò danh từ, âm cuối đọc là /ət/; khi là động từ, âm cuối đọc là /eɪt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_painstaking', 'en-c1-39', 'painstaking', '/ˈpeɪnzteɪkɪŋ/', 'C1', 'hết sức cẩn trọng; tỉ mỉ; công phu', 'adj.', 'painstakingly (adv.)', 'Đồng nghĩa: meticulous, thorough, careful · Trái nghĩa: careless, slapdash', 'Là tính từ, nhấn mạnh sự tốn công sức và cực kỳ tỉ mỉ chứ không chỉ đơn thuần là vất vả.', 'She made painstaking repairs to her grandmother''s old quilt.', NULL, 'Cô ấy đã tỉ mỉ vá lại chiếc chăn cũ của người bà.', '{"wordId":"painstaking","ukIpa":"/ˈpeɪnzteɪkɪŋ/","usIpa":"/ˈpeɪnzteɪkɪŋ/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Done with great care, effort, and attention to detail.","vi":"hết sức cẩn trọng; tỉ mỉ; công phu"}],"examples":[{"en":"She made painstaking repairs to her grandmother''s old quilt.","vi":"Cô ấy đã tỉ mỉ vá lại chiếc chăn cũ của người bà.","audioKind":"ex"},{"en":"The preservation of historic buildings requires painstaking research into original materials and traditional construction methods.","vi":"Việc bảo tồn các công trình kiến trúc lịch sử đòi hỏi quá trình nghiên cứu công phu về vật liệu nguyên bản và phương pháp xây dựng truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"painstaking research","vi":"nghiên cứu công phu"},{"en":"painstaking attention to detail","vi":"sự chú ý tỉ mỉ đến từng chi tiết"},{"en":"painstaking work","vi":"công việc đòi hỏi sự tỉ mỉ"}],"wordFamily":["painstakingly (adv.)"],"synonyms":["meticulous","thorough","careful"],"antonyms":["careless","slapdash"],"tipVi":"Là tính từ, nhấn mạnh sự tốn công sức và cực kỳ tỉ mỉ chứ không chỉ đơn thuần là vất vả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interim', 'en-c1-39', 'interim', '/ˈɪntərɪm/', 'C1', 'tạm thời; lâm thời; thời gian tạm thời; giai đoạn chuyển tiếp', 'adj.', NULL, 'Đồng nghĩa: temporary, provisional · Trái nghĩa: permanent', 'Tính từ thường đứng trước danh từ; in the interim có nghĩa là trong thời gian này.', 'Our interim manager will stay until we find a replacement.', NULL, 'Giám đốc tạm thời của chúng tôi sẽ ở lại cho đến khi chúng tôi tìm được người thay thế.', '{"wordId":"interim","ukIpa":"/ˈɪntərɪm/","usIpa":"/ˈɪntərɪm/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Intended to last until a permanent arrangement is made.","vi":"tạm thời; lâm thời"},{"pos":"n.","en":"The period before a later event or permanent arrangement.","vi":"thời gian tạm thời; giai đoạn chuyển tiếp"}],"examples":[{"en":"Our interim manager will stay until we find a replacement.","vi":"Giám đốc tạm thời của chúng tôi sẽ ở lại cho đến khi chúng tôi tìm được người thay thế.","audioKind":"ex"},{"en":"The council introduced interim housing measures while permanent accommodation was being built for families displaced by flooding.","vi":"Hội đồng đã áp dụng các biện pháp nhà ở tạm thời trong khi nhà ở vĩnh viễn đang được xây dựng cho các gia đình phải di dời do lũ lụt.","audioKind":"ex2"}],"collocations":[{"en":"interim report","vi":"báo cáo giai đoạn"},{"en":"interim measures","vi":"biện pháp tạm thời"},{"en":"interim manager","vi":"giám đốc tạm thời"},{"en":"in the interim","vi":"trong thời gian này"}],"wordFamily":[],"synonyms":["temporary","provisional"],"antonyms":["permanent"],"tipVi":"Tính từ thường đứng trước danh từ; in the interim có nghĩa là trong thời gian này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embark', 'en-c1-39', 'embark', '/ɪmˈbɑːrk/', 'C1', 'bắt đầu; dấn thân vào; lên tàu; lên máy bay', 'v.', 'embarkation (n.), disembark (v.)', 'Đồng nghĩa: begin, commence', 'Khi diễn tả ý bắt đầu làm việc gì, dùng embark on hoặc upon.', 'We are ready to embark on our kitchen renovation.', NULL, 'Chúng tôi đã sẵn sàng bắt tay vào việc cải tạo nhà bếp của mình.', '{"wordId":"embark","ukIpa":"/ɪmˈbɑːk/","usIpa":"/ɪmˈbɑːrk/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To begin a project, activity, or course of action","vi":"bắt đầu; dấn thân vào"},{"pos":"v.","en":"To board a ship or aircraft for a journey","vi":"lên tàu; lên máy bay"}],"examples":[{"en":"We are ready to embark on our kitchen renovation.","vi":"Chúng tôi đã sẵn sàng bắt tay vào việc cải tạo nhà bếp của mình.","audioKind":"ex"},{"en":"Before students embark on professional training, they should consider both their interests and future employment opportunities.","vi":"Trước khi bắt đầu quá trình đào tạo chuyên nghiệp, học sinh nên cân nhắc cả sở thích cá nhân lẫn cơ hội việc làm trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"embark on a project","vi":"bắt tay vào dự án"},{"en":"embark on a career","vi":"bắt đầu sự nghiệp"},{"en":"embark on a journey","vi":"bắt đầu một hành trình"}],"wordFamily":["embarkation (n.)","disembark (v.)"],"synonyms":["begin","commence"],"antonyms":[],"tipVi":"Khi diễn tả ý bắt đầu làm việc gì, dùng embark on hoặc upon.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eminent', 'en-c1-39', 'eminent', '/ˈemɪnənt/', 'C1', 'lỗi lạc; kiệt xuất; đáng kính trọng', 'adj.', 'eminence (n.), eminently (adv.)', 'Đồng nghĩa: distinguished, renowned · Trái nghĩa: unknown', 'eminent nghĩa là lỗi lạc, kiệt xuất; còn imminent nghĩa là sắp xảy ra.', 'An eminent surgeon visited our local hospital yesterday.', NULL, 'Một bác sĩ phẫu thuật lỗi lạc đã đến thăm bệnh viện địa phương của chúng tôi ngày hôm qua.', '{"wordId":"eminent","ukIpa":"/ˈemɪnənt/","usIpa":"/ˈemɪnənt/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Famous and respected for achievements in a particular field.","vi":"lỗi lạc; kiệt xuất; đáng kính trọng"}],"examples":[{"en":"An eminent surgeon visited our local hospital yesterday.","vi":"Một bác sĩ phẫu thuật lỗi lạc đã đến thăm bệnh viện địa phương của chúng tôi ngày hôm qua.","audioKind":"ex"},{"en":"Universities often invite eminent researchers to share their findings and inspire students to pursue academic careers.","vi":"Các trường đại học thường mời những nhà nghiên cứu tên tuổi đến chia sẻ phát hiện và truyền cảm hứng cho sinh viên theo đuổi con đường học thuật.","audioKind":"ex2"}],"collocations":[{"en":"eminent scholar","vi":"học giả lỗi lạc"},{"en":"eminent scientist","vi":"nhà khoa học nổi tiếng"},{"en":"internationally eminent","vi":"nổi tiếng quốc tế"}],"wordFamily":["eminence (n.)","eminently (adv.)"],"synonyms":["distinguished","renowned"],"antonyms":["unknown"],"tipVi":"eminent nghĩa là lỗi lạc, kiệt xuất; còn imminent nghĩa là sắp xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insider', 'en-c1-39', 'insider', '/ɪnˈsaɪdər/', 'C1', 'người trong cuộc; người nội bộ', 'n.', 'inside (adv)', 'Trái nghĩa: outsider', 'Chỉ những người nắm giữ thông tin nội bộ nhờ ở bên trong tổ chức.', 'An insider told us the restaurant would reopen next week.', NULL, 'Một người trong cuộc đã cho chúng tôi biết rằng nhà hàng sẽ mở cửa trở lại vào tuần tới.', '{"wordId":"insider","ukIpa":"/ɪnˈsaɪdə/","usIpa":"/ɪnˈsaɪdər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Someone within a group who has access to private information.","vi":"người trong cuộc; người nội bộ"}],"examples":[{"en":"An insider told us the restaurant would reopen next week.","vi":"Một người trong cuộc đã cho chúng tôi biết rằng nhà hàng sẽ mở cửa trở lại vào tuần tới.","audioKind":"ex"},{"en":"Industry insiders suggest that smaller firms may struggle to meet the costs of stricter environmental regulations.","vi":"Những người trong ngành gợi ý rằng các doanh nghiệp nhỏ hơn có thể sẽ chật vật để đáp ứng chi phí cho các quy định môi trường ngặt nghèo hơn.","audioKind":"ex2"}],"collocations":[{"en":"industry insider","vi":"industry insider -> người trong ngành"},{"en":"political insider","vi":"political insider -> nhân vật nội bộ chính giới"},{"en":"insider knowledge","vi":"insider knowledge -> thông tin nội bộ"},{"en":"insider trading","vi":"insider trading -> giao dịch nội gián"}],"wordFamily":["inside (adv)"],"synonyms":[],"antonyms":["outsider"],"tipVi":"Chỉ những người nắm giữ thông tin nội bộ nhờ ở bên trong tổ chức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_negotiable', 'en-c1-39', 'negotiable', '/nɪˈɡoʊʃiəbəl/', 'C1', 'có thể thương lượng; có thể thỏa thuận; có thể chuyển nhượng', 'adj.', 'negotiate (v.), negotiation (n.), negotiator (n.), non-negotiable (adj.)', 'Trái nghĩa: non-negotiable', 'Giá cả hoặc điều kiện có thể thương lượng dùng negotiable; từ trái nghĩa là non-negotiable.', 'The price is negotiable if you collect the sofa yourself.', NULL, 'Giá cả có thể thương lượng nếu bạn tự đến chở chiếc ghế sofa.', '{"wordId":"negotiable","ukIpa":"/nɪˈɡəʊʃiəbəl/","usIpa":"/nɪˈɡoʊʃiəbəl/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"able to be changed through discussion and agreement","vi":"có thể thương lượng; có thể thỏa thuận"},{"pos":"adj.","en":"legally transferable to another person in exchange for money","vi":"có thể chuyển nhượng"}],"examples":[{"en":"The price is negotiable if you collect the sofa yourself.","vi":"Giá cả có thể thương lượng nếu bạn tự đến chở chiếc ghế sofa.","audioKind":"ex"},{"en":"Flexible employment contracts may include negotiable working hours, allowing staff to accommodate childcare and other responsibilities.","vi":"Hợp đồng lao động linh hoạt có thể bao gồm thời gian làm việc có thể thương lượng, cho phép nhân viên cân bằng giữa việc chăm sóc con cái và các trách nhiệm khác.","audioKind":"ex2"}],"collocations":[{"en":"a negotiable price","vi":"mức giá có thể thương lượng"},{"en":"negotiable terms","vi":"các điều khoản có thể thỏa thuận"},{"en":"a negotiable salary","vi":"mức lương có thể thương lượng"},{"en":"a negotiable instrument","vi":"giấy tờ có thể chuyển nhượng"}],"wordFamily":["negotiate (v.)","negotiation (n.)","negotiator (n.)","non-negotiable (adj.)"],"synonyms":[],"antonyms":["non-negotiable"],"tipVi":"Giá cả hoặc điều kiện có thể thương lượng dùng negotiable; từ trái nghĩa là non-negotiable.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proficient', 'en-c1-39', 'proficient', '/prəˈfɪʃənt/', 'C1', 'thành thạo; giỏi; tinh thông', 'adj.', 'proficiency (n.), proficiently (adv.)', 'Đồng nghĩa: skilled, competent, adept · Trái nghĩa: unskilled, incompetent', 'Thường dùng proficient in một lĩnh vực nào đó hoặc at một hoạt động nào đó.', 'After months of practice, she became proficient at sewing.', NULL, 'Sau nhiều tháng luyện tập, cô ấy đã trở nên thành thạo việc may vá.', '{"wordId":"proficient","ukIpa":"/prəˈfɪʃənt/","usIpa":"/prəˈfɪʃənt/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Able to do something well through training and practice.","vi":"thành thạo; giỏi; tinh thông"}],"examples":[{"en":"After months of practice, she became proficient at sewing.","vi":"Sau nhiều tháng luyện tập, cô ấy đã trở nên thành thạo việc may vá.","audioKind":"ex"},{"en":"Graduates who are proficient in a second language may have better access to international employment opportunities.","vi":"Những sinh viên tốt nghiệp thành thạo ngoại ngữ thứ hai có thể tiếp cận tốt hơn với các cơ hội việc làm quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"proficient in English","vi":"thành thạo tiếng Anh"},{"en":"proficient at using software","vi":"giỏi sử dụng phần mềm"},{"en":"highly proficient","vi":"rất thành thạo"}],"wordFamily":["proficiency (n.)","proficiently (adv.)"],"synonyms":["skilled","competent","adept"],"antonyms":["unskilled","incompetent"],"tipVi":"Thường dùng proficient in một lĩnh vực nào đó hoặc at một hoạt động nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entrust', 'en-c1-39', 'entrust', '/ɪnˈtrʌst/', 'C1', 'giao phó; phó thác', 'v.', 'trust (v.), trustworthy (adj.)', NULL, 'Cấu trúc: entrust ai đó với cái gì; entrust cái gì cho ai đó.', 'I entrusted my neighbour with the spare house key.', NULL, 'Tôi đã giao chìa khóa phụ của ngôi nhà cho người hàng xóm.', '{"wordId":"entrust","ukIpa":"/ɪnˈtrʌst/","usIpa":"/ɪnˈtrʌst/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To give someone responsibility for something or someone valuable.","vi":"giao phó; phó thác"}],"examples":[{"en":"I entrusted my neighbour with the spare house key.","vi":"Tôi đã giao chìa khóa phụ của ngôi nhà cho người hàng xóm.","audioKind":"ex"},{"en":"Parents entrust schools with their children''s education and expect teachers to provide a safe learning environment.","vi":"Cha mẹ giao phó việc học tập của con cái cho nhà trường và mong đợi các giáo viên cung cấp một môi trường học tập an toàn.","audioKind":"ex2"}],"collocations":[{"en":"entrust someone with a task","vi":"ủy thác nhiệm vụ cho ai"},{"en":"entrust something to someone","vi":"giao phó vật gì cho ai"},{"en":"entrust someone with responsibility","vi":"giao trọng trách cho ai"}],"wordFamily":["trust (v.)","trustworthy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc: entrust ai đó với cái gì; entrust cái gì cho ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seniority', 'en-c1-39', 'seniority', '/ˌsiːniˈɔːrəti/', 'C1', 'thâm niên; niên hạn phục vụ; cấp bậc cao hơn; địa vị cao hơn', 'n.', 'senior (adj.)', 'Trái nghĩa: juniority', 'Là danh từ không đếm được; chủ yếu chỉ thời gian công tác hoặc chức vụ, không chỉ đơn thuần là tuổi tác.', 'Her seniority gives her first choice of holiday dates.', NULL, 'Thâm niên giúp cô ấy được ưu tiên chọn ngày nghỉ trước.', '{"wordId":"seniority","ukIpa":"/ˌsiːniˈɒrəti/","usIpa":"/ˌsiːniˈɔːrəti/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"The advantage or status gained from longer service.","vi":"thâm niên; niên hạn phục vụ"},{"pos":"n.","en":"The state of holding a higher rank than others.","vi":"cấp bậc cao hơn; địa vị cao hơn"}],"examples":[{"en":"Her seniority gives her first choice of holiday dates.","vi":"Thâm niên giúp cô ấy được ưu tiên chọn ngày nghỉ trước.","audioKind":"ex"},{"en":"Promotion based solely on seniority may discourage younger employees who consistently demonstrate exceptional skills and commitment.","vi":"Việc thăng chức chỉ dựa hoàn toàn vào thâm niên có thể làm nản lòng những nhân viên trẻ tuổi luôn thể hiện năng lực và sự tận tâm xuất sắc.","audioKind":"ex2"}],"collocations":[{"en":"based on seniority","vi":"dựa trên thâm niên"},{"en":"years of seniority","vi":"số năm thâm niên"},{"en":"seniority system","vi":"hệ thống thâm niên"}],"wordFamily":["senior (adj.)"],"synonyms":[],"antonyms":["juniority"],"tipVi":"Là danh từ không đếm được; chủ yếu chỉ thời gian công tác hoặc chức vụ, không chỉ đơn thuần là tuổi tác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hamper', 'en-c1-39', 'hamper', '/ˈhæmpər/', 'C1', 'cản trở; gây khó khăn cho tiến trình hoặc hoạt động; giỏ có nắp lớn; thường dùng để đựng thực phẩm hoặc quần áo giặt', 'v.', NULL, 'Đồng nghĩa: hinder, obstruct, impede · Trái nghĩa: facilitate', 'Động từ đi thẳng với tân ngữ phía sau; danh từ còn có thể chỉ giỏ đựng quà thực phẩm hoặc giỏ đựng đồ giặt.', 'Heavy rain hampered our efforts to repair the fence.', NULL, 'Cơn mưa lớn đã cản trở nỗ lực sửa chữa hàng rào của chúng tôi.', '{"wordId":"hamper","ukIpa":"/ˈhæmpə/","usIpa":"/ˈhæmpər/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to make progress or an activity more difficult","vi":"cản trở; gây khó khăn cho tiến trình hoặc hoạt động"},{"pos":"n.","en":"a large basket, often holding food or laundry","vi":"giỏ có nắp lớn; thường dùng để đựng thực phẩm hoặc quần áo giặt"}],"examples":[{"en":"Heavy rain hampered our efforts to repair the fence.","vi":"Cơn mưa lớn đã cản trở nỗ lực sửa chữa hàng rào của chúng tôi.","audioKind":"ex"},{"en":"Limited access to reliable internet services can hamper economic development in remote rural communities.","vi":"Việc hạn chế tiếp cận các dịch vụ internet ổn định có thể cản trở sự phát triển kinh tế ở các vùng nông thôn hẻo lánh.","audioKind":"ex2"}],"collocations":[{"en":"hamper progress","vi":"cản trở tiến độ"},{"en":"hamper efforts","vi":"cản trở nỗ lực"},{"en":"a picnic hamper","vi":"giỏ đựng đồ đi dã ngoại"},{"en":"a laundry hamper","vi":"giỏ đựng quần áo bẩn"}],"wordFamily":[],"synonyms":["hinder","obstruct","impede"],"antonyms":["facilitate"],"tipVi":"Động từ đi thẳng với tân ngữ phía sau; danh từ còn có thể chỉ giỏ đựng quà thực phẩm hoặc giỏ đựng đồ giặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_logistics', 'en-c1-39', 'logistics', '/ləˈdʒɪstɪks/', 'C1', 'hậu cần; công tác vận chuyển và tổ chức', 'n.', 'logistical (adj.), logistically (adv.)', NULL, 'Mặc dù tận cùng bằng -s nhưng không có nghĩa số nhiều; có thể chỉ công tác hậu cần của một hoạt động.', 'My brother handles the logistics of our camping trips.', NULL, 'Anh trai tôi lo phần hậu cần cho các chuyến đi cắm trại của chúng tôi.', '{"wordId":"logistics","ukIpa":"/ləˈdʒɪstɪks/","usIpa":"/ləˈdʒɪstɪks/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"The organization of transporting goods, equipment, or people where needed.","vi":"hậu cần; công tác vận chuyển và tổ chức"}],"examples":[{"en":"My brother handles the logistics of our camping trips.","vi":"Anh trai tôi lo phần hậu cần cho các chuyến đi cắm trại của chúng tôi.","audioKind":"ex"},{"en":"Efficient logistics can reduce food waste by ensuring fresh produce reaches urban markets quickly.","vi":"Hệ thống hậu cần hiệu quả có thể giúp giảm thiểu lãng phí thực phẩm bằng cách đảm bảo nông sản tươi sống được đưa đến các chợ đô thị một cách nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"logistics management","vi":"quản lý hậu cần"},{"en":"handle the logistics","vi":"lo liệu khâu hậu cần"},{"en":"transport logistics","vi":"hậu cần vận tải"}],"wordFamily":["logistical (adj.)","logistically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Mặc dù tận cùng bằng -s nhưng không có nghĩa số nhiều; có thể chỉ công tác hậu cần của một hoạt động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adept', 'en-c1-39', 'adept', '/əˈdept/', 'C1', 'thành thạo; giỏi; khéo léo; bậc thầy; tay cừ khôi', 'adj.', 'adeptly (adv.), adeptness (n.)', 'Đồng nghĩa: skilled, proficient, accomplished · Trái nghĩa: inept, unskilled', 'Thường dùng cấu trúc be adept at doing, thể hiện sự thành thạo khi làm việc gì đó.', 'My sister is adept at fixing old bicycles.', NULL, 'Chị gái tôi rất giỏi trong việc sửa những chiếc xe đạp cũ.', '{"wordId":"adept","ukIpa":"/əˈdept/","usIpa":"/əˈdept/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Very skilled at doing something.","vi":"thành thạo; giỏi; khéo léo"},{"pos":"n.","en":"Someone who is highly skilled in a particular activity.","vi":"bậc thầy; tay cừ khôi"}],"examples":[{"en":"My sister is adept at fixing old bicycles.","vi":"Chị gái tôi rất giỏi trong việc sửa những chiếc xe đạp cũ.","audioKind":"ex"},{"en":"Teachers who are adept at using digital tools can adapt lessons to meet a wider range of learning needs.","vi":"Những giáo viên thành thạo việc sử dụng các công cụ kỹ thuật số có thể điều chỉnh bài giảng để đáp ứng nhu cầu học tập đa dạng hơn.","audioKind":"ex2"}],"collocations":[{"en":"adept at solving problems","vi":"giỏi giải quyết vấn đề"},{"en":"adept at handling","vi":"thành thạo trong việc xử lý"},{"en":"technically adept","vi":"giỏi về kỹ thuật"}],"wordFamily":["adeptly (adv.)","adeptness (n.)"],"synonyms":["skilled","proficient","accomplished"],"antonyms":["inept","unskilled"],"tipVi":"Thường dùng cấu trúc be adept at doing, thể hiện sự thành thạo khi làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_negligence', 'en-c1-39', 'negligence', '/ˈneɡlɪdʒəns/', 'C1', 'sự cẩu thả, sự lơ đễnh, sự thiếu trách nhiệm, lỗi bất cẩn', 'n.', 'negligent (adj.), negligently (adv.)', 'Đồng nghĩa: carelessness, neglect · Trái nghĩa: diligence', 'Là danh từ không đếm được, thường chỉ việc không làm tròn nghĩa vụ cẩn trọng thông thường.', 'The leaking roof resulted from years of negligence.', NULL, 'Mái nhà bị dột là hậu quả của nhiều năm lơ đễnh, thiếu chăm sóc.', '{"wordId":"negligence","ukIpa":"/ˈneɡlɪdʒəns/","usIpa":"/ˈneɡlɪdʒəns/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Failure to take proper care or fulfil a responsibility","vi":"sự cẩu thả, sự lơ đễnh, sự thiếu trách nhiệm, lỗi bất cẩn"}],"examples":[{"en":"The leaking roof resulted from years of negligence.","vi":"Mái nhà bị dột là hậu quả của nhiều năm lơ đễnh, thiếu chăm sóc.","audioKind":"ex"},{"en":"Stronger workplace inspections can help prevent accidents caused by employer negligence and inadequate safety training.","vi":"Việc tăng cường thanh tra nơi làm việc có thể giúp ngăn ngừa các tai nạn do sự tắc trách của người sử dụng lao động và việc đào tạo an toàn chưa thỏa đáng.","audioKind":"ex2"}],"collocations":[{"en":"professional negligence","vi":"sự thiếu trách nhiệm trong nghề nghiệp"},{"en":"medical negligence","vi":"sự tắc trách trong y tế"},{"en":"gross negligence","vi":"lỗi bất cẩn nghiêm trọng"},{"en":"negligence claims","vi":"yêu cầu bồi thường do sơ suất"}],"wordFamily":["negligent (adj.)","negligently (adv.)"],"synonyms":["carelessness","neglect"],"antonyms":["diligence"],"tipVi":"Là danh từ không đếm được, thường chỉ việc không làm tròn nghĩa vụ cẩn trọng thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_veteran', 'en-c1-39', 'veteran', '/ˈvetərən/', 'C1', 'người có bề dày kinh nghiệm; lão luyện trong một hoạt động hoặc nghề nghiệp nào đó; cựu chiến binh; người đã từng phục vụ trong lực lượng vũ trang, đặc biệt là trong thời chiến', 'n.', NULL, 'Trái nghĩa: novice', 'Cấu trúc "a veteran of" theo sau là lĩnh vực hoặc kinh nghiệm; cũng có thể đứng trước để bổ nghĩa cho danh từ chỉ nghề nghiệp.', 'Ask Priya; she''s a veteran of long camping trips.', NULL, 'Hãy hỏi Priya nhé; cô ấy là một người có bề dày kinh nghiệm trong các chuyến cắm trại dài ngày.', '{"wordId":"veteran","ukIpa":"/ˈvetərən/","usIpa":"/ˈvetərən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Someone with extensive experience in a particular activity or profession.","vi":"người có bề dày kinh nghiệm; lão luyện trong một hoạt động hoặc nghề nghiệp nào đó"},{"pos":"n.","en":"Someone who has served in the armed forces, especially during war.","vi":"cựu chiến binh; người đã từng phục vụ trong lực lượng vũ trang, đặc biệt là trong thời chiến"}],"examples":[{"en":"Ask Priya; she''s a veteran of long camping trips.","vi":"Hãy hỏi Priya nhé; cô ấy là một người có bề dày kinh nghiệm trong các chuyến cắm trại dài ngày.","audioKind":"ex"},{"en":"A veteran of the teaching profession can offer valuable guidance to colleagues entering challenging classroom environments.","vi":"Một giáo viên kỳ cựu có thể đưa ra những định hướng quý giá cho các đồng nghiệp mới bước chân vào môi trường lớp học đầy thử thách.","audioKind":"ex2"}],"collocations":[{"en":"a veteran of","vi":"người có nhiều kinh nghiệm trong"},{"en":"a war veteran","vi":"cựu chiến binh"},{"en":"a veteran journalist","vi":"nhà báo kỳ cựu"}],"wordFamily":[],"synonyms":[],"antonyms":["novice"],"tipVi":"Cấu trúc \"a veteran of\" theo sau là lĩnh vực hoặc kinh nghiệm; cũng có thể đứng trước để bổ nghĩa cho danh từ chỉ nghề nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_utilize', 'en-c1-39', 'utilize', '/ˈjuːtəlaɪz/', 'C1', 'tận dụng; sử dụng hiệu quả', 'v.', 'utilization (n.), utilizable (adj.)', 'Đồng nghĩa: use, employ', 'Mang tính trang trọng hơn từ use; tiếng Anh-Anh thường viết là utilise.', 'We utilize the space under our stairs for storage.', NULL, 'Chúng tôi tận dụng không gian dưới cầu thang để làm chỗ chứa đồ.', '{"wordId":"utilize","ukIpa":"/ˈjuːtəlaɪz/","usIpa":"/ˈjuːtəlaɪz/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To use something effectively for a particular purpose.","vi":"tận dụng; sử dụng hiệu quả"}],"examples":[{"en":"We utilize the space under our stairs for storage.","vi":"Chúng tôi tận dụng không gian dưới cầu thang để làm chỗ chứa đồ.","audioKind":"ex"},{"en":"Schools can utilize existing buildings more efficiently by sharing facilities with local communities after lessons.","vi":"Các trường học có thể tận dụng các tòa nhà hiện có hiệu quả hơn bằng cách chia sẻ cơ sở vật chất với cộng đồng địa phương sau giờ học.","audioKind":"ex2"}],"collocations":[{"en":"utilize resources","vi":"tận dụng tài nguyên"},{"en":"fully utilize","vi":"tận dụng tối đa"},{"en":"utilize available space","vi":"tận dụng không gian sẵn có"}],"wordFamily":["utilization (n.)","utilizable (adj.)"],"synonyms":["use","employ"],"antonyms":[],"tipVi":"Mang tính trang trọng hơn từ use; tiếng Anh-Anh thường viết là utilise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rectify', 'en-c1-39', 'rectify', '/ˈrektɪfaɪ/', 'C1', 'sửa chữa; khắc phục; chỉnh đốn', 'v.', 'rectification (n.)', 'Đồng nghĩa: correct, remedy, put right', 'Đây là từ mang sắc thái trang trọng, thường đi với các từ như error, mistake hoặc situation.', 'The shop quickly rectified the mistake and refunded me.', NULL, 'Cửa hàng đã nhanh chóng khắc phục sai sót và hoàn tiền cho tôi.', '{"wordId":"rectify","ukIpa":"/ˈrektɪfaɪ/","usIpa":"/ˈrektɪfaɪ/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"Correct something that is wrong or unsatisfactory.","vi":"sửa chữa; khắc phục; chỉnh đốn"}],"examples":[{"en":"The shop quickly rectified the mistake and refunded me.","vi":"Cửa hàng đã nhanh chóng khắc phục sai sót và hoàn tiền cho tôi.","audioKind":"ex"},{"en":"Local authorities must rectify weaknesses in drainage systems before increasingly heavy rainfall causes further damage.","vi":"Các cơ quan chức năng địa phương phải khắc phục những điểm yếu trong hệ thống thoát nước trước khi những trận mưa lớn ngày càng dữ dội gây ra thêm tổn thất.","audioKind":"ex2"}],"collocations":[{"en":"rectify an error","vi":"sửa chữa sai lầm"},{"en":"rectify a problem","vi":"khắc phục vấn đề"},{"en":"rectify the situation","vi":"chỉnh đốn tình hình"}],"wordFamily":["rectification (n.)"],"synonyms":["correct","remedy","put right"],"antonyms":[],"tipVi":"Đây là từ mang sắc thái trang trọng, thường đi với các từ như error, mistake hoặc situation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_streamline', 'en-c1-39', 'streamline', '/ˈstriːmlaɪn/', 'C1', 'tinh giản; tối ưu hóa; làm thành hình khí động học; làm thành hình thuôn', 'v.', 'streamlined (adj.), streamlining (n.)', 'Đồng nghĩa: simplify', 'Thường dùng làm động từ; tính từ "streamlined" có nghĩa là "có hình thuôn/được tối ưu".', 'We streamlined our morning routine to leave home earlier.', NULL, 'Chúng tôi đã tối ưu hóa các công việc buổi sáng để có thể rời nhà sớm hơn.', '{"wordId":"streamline","ukIpa":"/ˈstriːmlaɪn/","usIpa":"/ˈstriːmlaɪn/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to make a process simpler and more efficient","vi":"tinh giản; tối ưu hóa"},{"pos":"v.","en":"to shape something to move easily through air or water","vi":"làm thành hình khí động học; làm thành hình thuôn"}],"examples":[{"en":"We streamlined our morning routine to leave home earlier.","vi":"Chúng tôi đã tối ưu hóa các công việc buổi sáng để có thể rời nhà sớm hơn.","audioKind":"ex"},{"en":"Hospitals can streamline appointment systems to reduce waiting times and improve access to essential care.","vi":"Các bệnh viện có thể tinh giản hệ thống đặt lịch hẹn để giảm thời gian chờ đợi và cải thiện khả năng tiếp cận dịch vụ chăm sóc y tế thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"streamline operations","vi":"tinh giản hoạt động"},{"en":"streamline a process","vi":"tinh giản quy trình"},{"en":"streamline administration","vi":"tinh giản quản0 lý hành chính"}],"wordFamily":["streamlined (adj.)","streamlining (n.)"],"synonyms":["simplify"],"antonyms":[],"tipVi":"Thường dùng làm động từ; tính từ \"streamlined\" có nghĩa là \"có hình thuôn/được tối ưu\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resignation', 'en-c1-39', 'resignation', '/ˌrezɪɡˈneɪʃən/', 'C1', 'sự từ chức; đơn từ chức; sự nhẫn nhịn; sự đành chịu', 'n.', 'resign (v.), resigned (adj.), resignedly (adv.)', NULL, 'Resignation dùng cho việc xin nghỉ việc; nghĩa thứ hai chỉ sự chấp nhận trong bất đắc dĩ, không phải sự chống cự.', 'She handed in her resignation after finding another job.', NULL, 'Cô ấy đã nộp đơn từ chức sau khi tìm được công việc mới.', '{"wordId":"resignation","ukIpa":"/ˌrezɪɡˈneɪʃən/","usIpa":"/ˌrezɪɡˈneɪʃən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"The act or written notice of leaving a job voluntarily.","vi":"sự từ chức; đơn từ chức"},{"pos":"n.","en":"Calm acceptance of something unpleasant that seems impossible to change.","vi":"sự nhẫn nhịn; sự đành chịu"}],"examples":[{"en":"She handed in her resignation after finding another job.","vi":"Cô ấy đã nộp đơn từ chức sau khi tìm được công việc mới.","audioKind":"ex"},{"en":"The resignation of experienced nurses can place additional pressure on hospitals already struggling with staff shortages.","vi":"Việc các y tá có kinh nghiệm từ chức có thể tạo thêm áp lực lớn cho các bệnh viện vốn đang chật vật với tình trạng thiếu nhân sự.","audioKind":"ex2"}],"collocations":[{"en":"hand in your resignation","vi":"nộp đơn từ chức"},{"en":"a letter of resignation","vi":"lá thư từ chức"},{"en":"accept a resignation","vi":"chấp thuận đơn từ chức"},{"en":"with resignation","vi":"với vẻ phó mặc, nhẫn nhịn"}],"wordFamily":["resign (v.)","resigned (adj.)","resignedly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Resignation dùng cho việc xin nghỉ việc; nghĩa thứ hai chỉ sự chấp nhận trong bất đắc dĩ, không phải sự chống cự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_successor', 'en-c1-39', 'successor', '/səkˈsesər/', 'C1', 'người kế nhiệm; người tiếp quản; vật kế thừa; sản phẩm thay thế', 'n.', 'succeed (v.), succession (n.), successive (adj.)', 'Đồng nghĩa: replacement · Trái nghĩa: predecessor', 'Dùng cấu trúc successor to; không chuyên chỉ người thừa kế tài sản.', 'The retiring coach introduced her successor to the team.', NULL, 'Vị huấn luyện viên sắp nghỉ hưu đã giới thiệu người kế nhiệm của mình với toàn đội.', '{"wordId":"successor","ukIpa":"/səkˈsesə/","usIpa":"/səkˈsesər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Someone who takes over another person''s job or position.","vi":"người kế nhiệm; người tiếp quản"},{"pos":"n.","en":"Something that replaces an earlier thing of the same kind.","vi":"vật kế thừa; sản phẩm thay thế"}],"examples":[{"en":"The retiring coach introduced her successor to the team.","vi":"Vị huấn luyện viên sắp nghỉ hưu đã giới thiệu người kế nhiệm của mình với toàn đội.","audioKind":"ex"},{"en":"A new leader should give their successor enough guidance to ensure that essential public services continue smoothly.","vi":"Một nhà lãnh đạo mới nên cung cấp cho người kế nhiệm của họ đủ sự hướng dẫn để đảm bảo các dịch vụ công thiết yếu tiếp tục diễn ra suôn sẻ.","audioKind":"ex2"}],"collocations":[{"en":"successor to","vi":"người kế nhiệm của..."},{"en":"appoint a successor","vi":"bổ nhiệm người kế nhiệm"},{"en":"choose a successor","vi":"chọn người kế nhiệm"},{"en":"likely successor","vi":"người kế nhiệm tiềm năng"}],"wordFamily":["succeed (v.)","succession (n.)","successive (adj.)"],"synonyms":["replacement"],"antonyms":["predecessor"],"tipVi":"Dùng cấu trúc successor to; không chuyên chỉ người thừa kế tài sản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_collaborate', 'en-c1-39', 'collaborate', '/kəˈlæbəreɪt/', 'C1', 'hợp tác; cộng tác; cấu kết với kẻ địch', 'v.', 'collaboration (n.), collaborative (adj.), collaboratively (adv.), collaborator (n.)', 'Đồng nghĩa: cooperate', 'Hợp tác với ai dùng with; hợp tác làm dự án dùng on.', 'We collaborate on recipes for our weekend cooking club.', NULL, 'Chúng tôi cùng hợp tác nghĩ ra các công thức cho câu lạc bộ nấu ăn cuối tuần của mình.', '{"wordId":"collaborate","ukIpa":"/kəˈlæbəreɪt/","usIpa":"/kəˈlæbəreɪt/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"work with others to create or achieve something","vi":"hợp tác; cộng tác"},{"pos":"v.","en":"help an enemy controlling your country","vi":"cấu kết với kẻ địch"}],"examples":[{"en":"We collaborate on recipes for our weekend cooking club.","vi":"Chúng tôi cùng hợp tác nghĩ ra các công thức cho câu lạc bộ nấu ăn cuối tuần của mình.","audioKind":"ex"},{"en":"Universities should collaborate with local businesses to develop practical solutions to regional environmental problems.","vi":"Các trường đại học nên hợp tác với các doanh nghiệp địa phương để phát triển các giải pháp thiết thực cho các vấn đề môi trường trong vùng.","audioKind":"ex2"}],"collocations":[{"en":"collaborate with colleagues","vi":"hợp tác với đồng nghiệp"},{"en":"collaborate on a project","vi":"hợp tác thực hiện một dự án"},{"en":"collaborate closely","vi":"hợp tác chặt chẽ"}],"wordFamily":["collaboration (n.)","collaborative (adj.)","collaboratively (adv.)","collaborator (n.)"],"synonyms":["cooperate"],"antonyms":[],"tipVi":"Hợp tác với ai dùng with; hợp tác làm dự án dùng on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entail', 'en-c1-39', 'entail', '/ɪnˈteɪl/', 'C1', 'đòi hỏi; kéo theo; bao hàm', 'v.', 'entailment (n.)', 'Đồng nghĩa: involve, require', 'Theo sau là danh từ hoặc danh động từ: entail doing, không dùng to do.', 'This new job entails working some evenings and weekends.', NULL, 'Công việc mới này đòi hỏi phải làm việc vào một số buổi tối và ngày cuối tuần.', '{"wordId":"entail","ukIpa":"/ɪnˈteɪl/","usIpa":"/ɪnˈteɪl/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To necessarily involve or require something","vi":"đòi hỏi; kéo theo; bao hàm"}],"examples":[{"en":"This new job entails working some evenings and weekends.","vi":"Công việc mới này đòi hỏi phải làm việc vào một số buổi tối và ngày cuối tuần.","audioKind":"ex"},{"en":"Expanding public transport will entail substantial initial costs, although the environmental and social benefits may justify this investment.","vi":"Việc mở rộng giao thông công cộng sẽ đòi hỏi chi phí ban đầu đáng kể, mặc dù các lợi ích về môi trường và xã hội có thể bù đắp cho khoản đầu tư này.","audioKind":"ex2"}],"collocations":[{"en":"entail costs","vi":"kéo theo chi phí"},{"en":"entail risks","vi":"mang lại rủi ro"},{"en":"entail doing something","vi":"đòi hỏi phải làm gì"}],"wordFamily":["entailment (n.)"],"synonyms":["involve","require"],"antonyms":[],"tipVi":"Theo sau là danh từ hoặc danh động từ: entail doing, không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_39_1', 'en-c1-39', 'Cách dùng “veteran” (n.) — người có bề dày kinh nghiệm; lão luyện trong một hoạt động hoặc nghề nghiệp nào đó', 'a veteran of  ·  a war veteran  ·  a veteran journalist', 'Cấu trúc "a veteran of" theo sau là lĩnh vực hoặc kinh nghiệm; cũng có thể đứng trước để bổ nghĩa cho danh từ chỉ nghề nghiệp.', 'Trái nghĩa: novice', '[{"hanzi":"Ask Priya; she''s a veteran of long camping trips.","pinyin":"","meaning":"Hãy hỏi Priya nhé; cô ấy là một người có bề dày kinh nghiệm trong các chuyến cắm trại dài ngày."},{"hanzi":"A veteran of the teaching profession can offer valuable guidance to colleagues entering challenging classroom environments.","pinyin":"","meaning":"Một giáo viên kỳ cựu có thể đưa ra những định hướng quý giá cho các đồng nghiệp mới bước chân vào môi trường lớp học đầy thử thách."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_39_2', 'en-c1-39', 'Cách dùng “resignation” (n.) — sự từ chức; đơn từ chức', 'hand in your resignation  ·  a letter of resignation  ·  accept a resignation', 'Resignation dùng cho việc xin nghỉ việc; nghĩa thứ hai chỉ sự chấp nhận trong bất đắc dĩ, không phải sự chống cự.', 'Họ từ (Word Family): resign (v.), resigned (adj.), resignedly (adv.)', '[{"hanzi":"She handed in her resignation after finding another job.","pinyin":"","meaning":"Cô ấy đã nộp đơn từ chức sau khi tìm được công việc mới."},{"hanzi":"The resignation of experienced nurses can place additional pressure on hospitals already struggling with staff shortages.","pinyin":"","meaning":"Việc các y tá có kinh nghiệm từ chức có thể tạo thêm áp lực lớn cho các bệnh viện vốn đang chật vật với tình trạng thiếu nhân sự."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_39_3', 'en-c1-39', 'Cách dùng “hamper” (v.) — cản trở; gây khó khăn cho tiến trình hoặc hoạt động', 'hamper progress  ·  hamper efforts  ·  a picnic hamper', 'Động từ đi thẳng với tân ngữ phía sau; danh từ còn có thể chỉ giỏ đựng quà thực phẩm hoặc giỏ đựng đồ giặt.', 'Đồng nghĩa: hinder, obstruct, impede · Trái nghĩa: facilitate', '[{"hanzi":"Heavy rain hampered our efforts to repair the fence.","pinyin":"","meaning":"Cơn mưa lớn đã cản trở nỗ lực sửa chữa hàng rào của chúng tôi."},{"hanzi":"Limited access to reliable internet services can hamper economic development in remote rural communities.","pinyin":"","meaning":"Việc hạn chế tiếp cận các dịch vụ internet ổn định có thể cản trở sự phát triển kinh tế ở các vùng nông thôn hẻo lánh."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_39_4', 'en-c1-39', 'Cách dùng “seniority” (n.) — thâm niên; niên hạn phục vụ', 'based on seniority  ·  years of seniority  ·  seniority system', 'Là danh từ không đếm được; chủ yếu chỉ thời gian công tác hoặc chức vụ, không chỉ đơn thuần là tuổi tác.', 'Họ từ (Word Family): senior (adj.) | Trái nghĩa: juniority', '[{"hanzi":"Her seniority gives her first choice of holiday dates.","pinyin":"","meaning":"Thâm niên giúp cô ấy được ưu tiên chọn ngày nghỉ trước."},{"hanzi":"Promotion based solely on seniority may discourage younger employees who consistently demonstrate exceptional skills and commitment.","pinyin":"","meaning":"Việc thăng chức chỉ dựa hoàn toàn vào thâm niên có thể làm nản lòng những nhân viên trẻ tuổi luôn thể hiện năng lực và sự tận tâm xuất sắc."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_39_1', 'en-c1-39', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_1_1', 'ten_c1_39_1', 'shelve', 'We shelved our holiday plans when the car broke down.', 'We shelved our holiday plans when the car broke down.', '/ʃelv/', 'Chúng tôi đã gác lại kế hoạch nghỉ mát khi chiếc xe bị hỏng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_1_2', 'ten_c1_39_1', 'vocation', 'Caring for injured animals became her vocation early in life.', 'Caring for injured animals became her vocation early in life.', '/voʊˈkeɪʃən/', 'Việc chăm sóc những loài động vật bị thương đã trở thành sứ mệnh cuộc đời cô ấy từ khi còn trẻ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_1_3', 'ten_c1_39_1', 'affiliate', 'Our local cycling club is affiliated with a national organisation.', 'Our local cycling club is affiliated with a national organisation.', '/əˈfɪlieɪt/', 'Câu lạc bộ xe đạp địa phương của chúng tôi trực thuộc một tổ chức cấp quốc gia.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_1_4', 'ten_c1_39_1', 'painstaking', 'She made painstaking repairs to her grandmother''s old quilt.', 'She made painstaking repairs to her grandmother''s old quilt.', '/ˈpeɪnzteɪkɪŋ/', 'Cô ấy đã tỉ mỉ vá lại chiếc chăn cũ của người bà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_1_5', 'ten_c1_39_1', 'interim', 'Our interim manager will stay until we find a replacement.', 'Our interim manager will stay until we find a replacement.', '/ˈɪntərɪm/', 'Giám đốc tạm thời của chúng tôi sẽ ở lại cho đến khi chúng tôi tìm được người thay thế.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_1_6', 'ten_c1_39_1', 'embark', 'We are ready to embark on our kitchen renovation.', 'We are ready to embark on our kitchen renovation.', '/ɪmˈbɑːrk/', 'Chúng tôi đã sẵn sàng bắt tay vào việc cải tạo nhà bếp của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_1_7', 'ten_c1_39_1', 'eminent', 'An eminent surgeon visited our local hospital yesterday.', 'An eminent surgeon visited our local hospital yesterday.', '/ˈemɪnənt/', 'Một bác sĩ phẫu thuật lỗi lạc đã đến thăm bệnh viện địa phương của chúng tôi ngày hôm qua.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_1_8', 'ten_c1_39_1', 'insider', 'An insider told us the restaurant would reopen next week.', 'An insider told us the restaurant would reopen next week.', '/ɪnˈsaɪdər/', 'Một người trong cuộc đã cho chúng tôi biết rằng nhà hàng sẽ mở cửa trở lại vào tuần tới.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_39_1_1', 'en-c1-39', 'ten_c1_39_1', 'listening', 'listening', 'We shelved our holiday plans when the car broke down.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã gác lại kế hoạch nghỉ mát khi chiếc xe bị hỏng.","Chị gái tôi rất giỏi trong việc sửa những chiếc xe đạp cũ.","Một người trong cuộc đã cho chúng tôi biết rằng nhà hàng sẽ mở cửa trở lại vào tuần tới.","Cô ấy đã tỉ mỉ vá lại chiếc chăn cũ của người bà."]'::jsonb, 0, 'We shelved our holiday plans when the car broke down. → Chúng tôi đã gác lại kế hoạch nghỉ mát khi chiếc xe bị hỏng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_39_1_2', 'en-c1-39', 'ten_c1_39_1', 'listening', 'listening', 'Caring for injured animals became her vocation early in life.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc chăm sóc những loài động vật bị thương đã trở thành sứ mệnh cuộc đời cô ấy từ khi còn trẻ.","Cô ấy đã nộp đơn từ chức sau khi tìm được công việc mới.","Tôi đã giao chìa khóa phụ của ngôi nhà cho người hàng xóm.","Cô ấy đã tỉ mỉ vá lại chiếc chăn cũ của người bà."]'::jsonb, 0, 'Caring for injured animals became her vocation early in life. → Việc chăm sóc những loài động vật bị thương đã trở thành sứ mệnh cuộc đời cô ấy từ khi còn trẻ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_39_1_3', 'en-c1-39', 'ten_c1_39_1', 'listening', 'listening', 'Our local cycling club is affiliated with a national organisation.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã sẵn sàng bắt tay vào việc cải tạo nhà bếp của mình.","Một người trong cuộc đã cho chúng tôi biết rằng nhà hàng sẽ mở cửa trở lại vào tuần tới.","Câu lạc bộ xe đạp địa phương của chúng tôi trực thuộc một tổ chức cấp quốc gia.","Giám đốc tạm thời của chúng tôi sẽ ở lại cho đến khi chúng tôi tìm được người thay thế."]'::jsonb, 2, 'Our local cycling club is affiliated with a national organisation. → Câu lạc bộ xe đạp địa phương của chúng tôi trực thuộc một tổ chức cấp quốc gia.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_39_2', 'en-c1-39', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_2_1', 'ten_c1_39_2', 'shelve', 'The council decided to shelve the road expansion project because of concerns about air pollution.', 'The council decided to shelve the road expansion project because of concerns about air pollution.', '/ʃelv/', 'Hội đồng quyết định tạm hoãn dự án mở rộng đường vì lo ngại về ô nhiễm không khí.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_2_2', 'ten_c1_39_2', 'vocation', 'Career guidance should help young people discover a vocation that matches their abilities and values.', 'Career guidance should help young people discover a vocation that matches their abilities and values.', '/voʊˈkeɪʃən/', 'Tư vấn hướng nghiệp nên giúp giới trẻ khám phá ra một định hướng sự nghiệp phù hợp với năng lực và giá trị của bản thân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_2_3', 'ten_c1_39_2', 'affiliate', 'Small research institutes often affiliate with universities to gain access to specialist equipment and academic expertise.', 'Small research institutes often affiliate with universities to gain access to specialist equipment and academic expertise.', '/əˈfɪlieɪt/', 'Các viện nghiên cứu nhỏ thường liên kết với các trường đại học để tiếp cận thiết bị chuyên dụng và chuyên môn học thuật.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_2_4', 'ten_c1_39_2', 'painstaking', 'The preservation of historic buildings requires painstaking research into original materials and traditional construction methods.', 'The preservation of historic buildings requires painstaking research into original materials and traditional construction methods.', '/ˈpeɪnzteɪkɪŋ/', 'Việc bảo tồn các công trình kiến trúc lịch sử đòi hỏi quá trình nghiên cứu công phu về vật liệu nguyên bản và phương pháp xây dựng truyền thống.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_2_5', 'ten_c1_39_2', 'interim', 'The council introduced interim housing measures while permanent accommodation was being built for families displaced by flooding.', 'The council introduced interim housing measures while permanent accommodation was being built for families displaced by flooding.', '/ˈɪntərɪm/', 'Hội đồng đã áp dụng các biện pháp nhà ở tạm thời trong khi nhà ở vĩnh viễn đang được xây dựng cho các gia đình phải di dời do lũ lụt.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_39_2_6', 'ten_c1_39_2', 'embark', 'Before students embark on professional training, they should consider both their interests and future employment opportunities.', 'Before students embark on professional training, they should consider both their interests and future employment opportunities.', '/ɪmˈbɑːrk/', 'Trước khi bắt đầu quá trình đào tạo chuyên nghiệp, học sinh nên cân nhắc cả sở thích cá nhân lẫn cơ hội việc làm trong tương lai.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_39_2_1', 'en-c1-39', 'ten_c1_39_2', 'listening', 'listening', 'The council decided to shelve the road expansion project because of concerns about air pollution.', NULL, 'Trong câu vừa nghe, từ “shelve” mang nghĩa nào sau đây?', '["thợ thủ công; thợ lành nghề","gác lại; tạm hoãn","người cuồng nhiệt; tín đồ (của một hoạt động, sở thích)","làm triệt tiêu; vô hiệu hóa"]'::jsonb, 1, '“shelve” (/ʃelv/): gác lại; tạm hoãn. Câu đầy đủ: The council decided to shelve the road expansion project because of concerns about air pollution.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_39_2_2', 'en-c1-39', 'ten_c1_39_2', 'listening', 'listening', 'Career guidance should help young people discover a vocation that matches their abilities and values.', NULL, 'Trong câu vừa nghe, từ “vocation” mang nghĩa nào sau đây?', '["sứ mệnh; công việc phù hợp với tâm huyết bản thân","trùng; xảy ra đồng thời","mũi đất; hải vạn","sự trừng phạt; biện pháp trừng phạt"]'::jsonb, 0, '“vocation” (/voʊˈkeɪʃən/): sứ mệnh; công việc phù hợp với tâm huyết bản thân. Câu đầy đủ: Career guidance should help young people discover a vocation that matches their abilities and values.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
