INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_1', 'en-c1-39', NULL, 'comprehensive_test', 'listening', 'shelve', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bắt đầu; khởi đầu","quá lo lắng; hoảng loạn; không thể giữ được bình tĩnh","gỗ xẻ; gỗ thành phẩm","gác lại; tạm hoãn"]'::jsonb, 3, 'shelve (/ʃelv/) → gác lại; tạm hoãn; đặt lên kệ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_2', 'en-c1-39', NULL, 'comprehensive_test', 'listening', 'Caring for injured animals became her vocation early in life.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đã tỉ mỉ vá lại chiếc chăn cũ của người bà.","Chúng tôi đã gác lại kế hoạch nghỉ mát khi chiếc xe bị hỏng.","Việc chăm sóc những loài động vật bị thương đã trở thành sứ mệnh cuộc đời cô ấy từ khi còn trẻ.","Mái nhà bị dột là hậu quả của nhiều năm lơ đễnh, thiếu chăm sóc."]'::jsonb, 2, 'Caring for injured animals became her vocation early in life. → Việc chăm sóc những loài động vật bị thương đã trở thành sứ mệnh cuộc đời cô ấy từ khi còn trẻ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_3', 'en-c1-39', NULL, 'comprehensive_test', 'listening', 'affiliate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["liên kết; sáp nhập; gia nhập vào tổ chức lớn","không đối xứng","luôn luôn; lúc nào cũng","đồng thời; song song (xảy ra hoặc tồn tại cùng một lúc)"]'::jsonb, 0, 'affiliate (/əˈfɪlieɪt/) → liên kết; sáp nhập; gia nhập vào tổ chức lớn; chi nhánh; tổ chức liên kết trực thuộc', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_4', 'en-c1-39', NULL, 'comprehensive_test', 'listening', 'She made painstaking repairs to her grandmother''s old quilt.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thâm niên giúp cô ấy được ưu tiên chọn ngày nghỉ trước.","Cô ấy đã nộp đơn từ chức sau khi tìm được công việc mới.","Cô ấy đã tỉ mỉ vá lại chiếc chăn cũ của người bà.","Công việc mới này đòi hỏi phải làm việc vào một số buổi tối và ngày cuối tuần."]'::jsonb, 2, 'She made painstaking repairs to her grandmother''s old quilt. → Cô ấy đã tỉ mỉ vá lại chiếc chăn cũ của người bà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_5', 'en-c1-39', NULL, 'comprehensive_test', 'listening', 'interim', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lan tràn; hoành hành; không kiểm soát được (thường mang nghĩa tiêu cực)","đạo đức; chuẩn mực đạo đức","tạm thời; lâm thời","mất dáng; không có hình thù rõ ràng; thùng thình"]'::jsonb, 2, 'interim (/ˈɪntərɪm/) → tạm thời; lâm thời; thời gian tạm thời; giai đoạn chuyển tiếp', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_6', 'en-c1-39', NULL, 'comprehensive_test', 'listening', 'We are ready to embark on our kitchen renovation.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giá cả có thể thương lượng nếu bạn tự đến chở chiếc ghế sofa.","Chúng tôi tận dụng không gian dưới cầu thang để làm chỗ chứa đồ.","Chúng tôi cùng hợp tác nghĩ ra các công thức cho câu lạc bộ nấu ăn cuối tuần của mình.","Chúng tôi đã sẵn sàng bắt tay vào việc cải tạo nhà bếp của mình."]'::jsonb, 3, 'We are ready to embark on our kitchen renovation. → Chúng tôi đã sẵn sàng bắt tay vào việc cải tạo nhà bếp của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_7', 'en-c1-39', NULL, 'comprehensive_test', 'listening', 'eminent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lỗi lạc; kiệt xuất; đáng kính trọng","giả thuyết; giả định","sự phụ thuộc; sự tín nhiệm","chủ nghĩa bảo hộ mậu dịch; chính sách bảo hộ"]'::jsonb, 0, 'eminent (/ˈemɪnənt/) → lỗi lạc; kiệt xuất; đáng kính trọng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_8', 'en-c1-39', NULL, 'comprehensive_test', 'listening', 'An insider told us the restaurant would reopen next week.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã tối ưu hóa các công việc buổi sáng để có thể rời nhà sớm hơn.","Câu lạc bộ xe đạp địa phương của chúng tôi trực thuộc một tổ chức cấp quốc gia.","Công việc mới này đòi hỏi phải làm việc vào một số buổi tối và ngày cuối tuần.","Một người trong cuộc đã cho chúng tôi biết rằng nhà hàng sẽ mở cửa trở lại vào tuần tới."]'::jsonb, 3, 'An insider told us the restaurant would reopen next week. → Một người trong cuộc đã cho chúng tôi biết rằng nhà hàng sẽ mở cửa trở lại vào tuần tới.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_9', 'en-c1-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Intended to last until a permanent arrangement is made.”?', '["proficient","logistics","vocation","interim"]'::jsonb, 3, 'interim (/ˈɪntərɪm/) → tạm thời; lâm thời', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_10', 'en-c1-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To begin a project, activity, or course of action”?', '["negotiable","proficient","negligence","embark"]'::jsonb, 3, 'embark (/ɪmˈbɑːrk/) → bắt đầu; dấn thân vào', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_11', 'en-c1-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Famous and respected for achievements in a particular field.”?', '["rectify","insider","eminent","negotiable"]'::jsonb, 2, 'eminent (/ˈemɪnənt/) → lỗi lạc; kiệt xuất; đáng kính trọng', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_12', 'en-c1-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Someone within a group who has access to private information.”?', '["insider","collaborate","shelve","embark"]'::jsonb, 0, 'insider (/ɪnˈsaɪdər/) → người trong cuộc; người nội bộ', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_13', 'en-c1-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “able to be changed through discussion and agreement”?', '["veteran","logistics","insider","negotiable"]'::jsonb, 3, 'negotiable (/nɪˈɡoʊʃiəbəl/) → có thể thương lượng; có thể thỏa thuận', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
