INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_18', 'en-c1-39', NULL, 'comprehensive_test', 'reading', NULL, 'The council decided to shelve the road expansion project because of concerns about air pollution.', 'Dựa vào câu trên, từ “shelve” có nghĩa phù hợp nhất là gì?', '["ngược lại; trái ngược; tỉ lệ nghịch","bán trong suốt; cho ánh sáng xuyên qua nhưng không nhìn rõ vật bên trong","được tích lũy theo thời gian (đặc biệt là về mặt tài chính); dồn tích","gác lại; tạm hoãn"]'::jsonb, 3, 'shelve: gác lại; tạm hoãn; đặt lên kệ. Dịch cả câu: Hội đồng quyết định tạm hoãn dự án mở rộng đường vì lo ngại về ô nhiễm không khí.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_19', 'en-c1-39', NULL, 'comprehensive_test', 'reading', NULL, 'Career guidance should help young people discover a vocation that matches their abilities and values.', 'Dựa vào câu trên, từ “vocation” có nghĩa phù hợp nhất là gì?', '["gây gánh nặng; phiền hà; nặng nề","sứ mệnh; công việc phù hợp với tâm huyết bản thân","có thể sai lầm; dễ mắc lỗi","hết sức cẩn trọng; tỉ mỉ; công phu"]'::jsonb, 1, 'vocation: sứ mệnh; công việc phù hợp với tâm huyết bản thân; nghề nghiệp; công việc chuyên môn. Dịch cả câu: Tư vấn hướng nghiệp nên giúp giới trẻ khám phá ra một định hướng sự nghiệp phù hợp với năng lực và giá trị của bản thân.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_20', 'en-c1-39', NULL, 'comprehensive_test', 'reading', NULL, 'Small research institutes often affiliate with universities to gain access to specialist equipment and academic expertise.', 'Dựa vào câu trên, từ “affiliate” có nghĩa phù hợp nhất là gì?', '["chủ nghĩa tư bản","tương ứng; có tỉ lệ thuận","hòa quyện; trộn lẫn","liên kết; sáp nhập; gia nhập vào tổ chức lớn"]'::jsonb, 3, 'affiliate: liên kết; sáp nhập; gia nhập vào tổ chức lớn; chi nhánh; tổ chức liên kết trực thuộc. Dịch cả câu: Các viện nghiên cứu nhỏ thường liên kết với các trường đại học để tiếp cận thiết bị chuyên dụng và chuyên môn học thuật.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_21', 'en-c1-39', NULL, 'comprehensive_test', 'reading', NULL, 'The preservation of historic buildings requires painstaking research into original materials and traditional construction methods.', 'Dựa vào câu trên, từ “painstaking” có nghĩa phù hợp nhất là gì?', '["khối u","tập san; tạp chí định kỳ","làm ăn mòn; bị ăn mòn (hóa học)","hết sức cẩn trọng; tỉ mỉ; công phu"]'::jsonb, 3, 'painstaking: hết sức cẩn trọng; tỉ mỉ; công phu. Dịch cả câu: Việc bảo tồn các công trình kiến trúc lịch sử đòi hỏi quá trình nghiên cứu công phu về vật liệu nguyên bản và phương pháp xây dựng truyền thống.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_22', 'en-c1-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “người kế nhiệm; người tiếp quản”', '["contractual","ponder","insomnia","successor"]'::jsonb, 3, 'người kế nhiệm; người tiếp quản → successor (/səkˈsesər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_23', 'en-c1-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hợp tác; cộng tác”', '["collaborate","catalyst","instantaneous","prosecution"]'::jsonb, 0, 'hợp tác; cộng tác → collaborate (/kəˈlæbəreɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_39_24', 'en-c1-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đòi hỏi; kéo theo; bao hàm”', '["workmanship","entail","manipulate","humiliate"]'::jsonb, 1, 'đòi hỏi; kéo theo; bao hàm → entail (/ɪnˈteɪl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-40', 'en', 'Bài 40: Công việc & Nghề nghiệp (5) - CEFR C1', 'CEFR C1', 'C1 · Công việc', '24 từ vựng Tiếng Anh CEFR C1 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5040, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aspire', 'en-c1-40', 'aspire', '/əˈspaɪr/', 'C1', 'khao khát; hoài bão; chí hướng', 'v.', 'aspiration (n.), aspiring (adj.), aspirant (n.)', 'Đồng nghĩa: aim', 'Aspire to do dùng để chỉ việc ấp ủ hoài bão làm gì; ngoài ra aspire to cũng có thể theo sau bởi một danh từ.', 'My younger sister aspires to become a wildlife photographer.', NULL, 'Em gái tôi có ước mơ trở thành một nhiếp ảnh gia động vật hoang dã.', '{"wordId":"aspire","ukIpa":"/əˈspaɪə/","usIpa":"/əˈspaɪr/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To strongly want to achieve something important.","vi":"khao khát; hoài bão; chí hướng"}],"examples":[{"en":"My younger sister aspires to become a wildlife photographer.","vi":"Em gái tôi có ước mơ trở thành một nhiếp ảnh gia động vật hoang dã.","audioKind":"ex"},{"en":"Many young people aspire to careers that offer both financial security and opportunities to contribute to society.","vi":"Nhiều người trẻ tuổi khát khao theo đuổi những nghề nghiệp vừa mang lại sự ổn định tài chính vừa có cơ hội đóng góp cho xã hội.","audioKind":"ex2"}],"collocations":[{"en":"aspire to do something","vi":"khát khao làm điều gì đó"},{"en":"aspire to greatness","vi":"vươn tới sự vĩ đại"},{"en":"aspire to a career in medicine","vi":"nuôi dưỡng hoài bão theo đuổi ngành y"}],"wordFamily":["aspiration (n.)","aspiring (adj.)","aspirant (n.)"],"synonyms":["aim"],"antonyms":[],"tipVi":"Aspire to do dùng để chỉ việc ấp ủ hoài bão làm gì; ngoài ra aspire to cũng có thể theo sau bởi một danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reap', 'en-c1-40', 'reap', '/riːp/', 'C1', 'gặt hái kết quả; nhận thành quả từ những hành động trước đó; thu hoạch mùa màng', 'v.', 'reaper (n.)', 'Đồng nghĩa: gain, harvest', 'Nghĩa trừu tượng thường đi với benefits hoặc rewards, nhấn mạnh sự đền đáp sau nỗ lực.', 'After months of practice, she finally reaped the rewards.', NULL, 'Sau nhiều tháng luyện tập, cuối cùng cô ấy đã gặt hái được những thành quả xứng đáng.', '{"wordId":"reap","ukIpa":"/riːp/","usIpa":"/riːp/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to receive results or rewards from previous actions","vi":"gặt hái kết quả; nhận thành quả từ những hành động trước đó"},{"pos":"v.","en":"to cut and gather a crop when it is ready","vi":"thu hoạch mùa màng"}],"examples":[{"en":"After months of practice, she finally reaped the rewards.","vi":"Sau nhiều tháng luyện tập, cuối cùng cô ấy đã gặt hái được những thành quả xứng đáng.","audioKind":"ex"},{"en":"Countries that invest consistently in early education often reap long-term economic and social benefits.","vi":"Những quốc gia đầu tư liên tục vào giáo dục mầm non thường thu về những lợi ích kinh tế và xã hội lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"reap the benefits","vi":"gặt hái lợi ích"},{"en":"reap the rewards","vi":"nhận thành quả"},{"en":"reap a harvest","vi":"thu hoạch mùa màng"}],"wordFamily":["reaper (n.)"],"synonyms":["gain","harvest"],"antonyms":[],"tipVi":"Nghĩa trừu tượng thường đi với benefits hoặc rewards, nhấn mạnh sự đền đáp sau nỗ lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pending', 'en-c1-40', 'pending', '/ˈpendɪŋ/', 'C1', 'chưa quyết định; đang chờ giải quyết; trong thời gian chờ đợi; cho đến khi', 'adj.', NULL, 'Đồng nghĩa: unresolved, undecided · Trái nghĩa: resolved, settled', 'Nghĩa chính là chưa được quyết định hay hoàn tất, không nhầm lẫn với urgent.', 'Our application is still pending, so we cannot book flights.', NULL, 'Hồ sơ của chúng tôi vẫn đang chờ xét duyệt nên chúng tôi chưa thể đặt vé máy bay.', '{"wordId":"pending","ukIpa":"/ˈpendɪŋ/","usIpa":"/ˈpendɪŋ/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Waiting for a decision or for something to happen","vi":"chưa quyết định; đang chờ giải quyết"},{"pos":"prep.","en":"Until something happens or while waiting for it","vi":"trong thời gian chờ đợi; cho đến khi"}],"examples":[{"en":"Our application is still pending, so we cannot book flights.","vi":"Hồ sơ của chúng tôi vẫn đang chờ xét duyệt nên chúng tôi chưa thể đặt vé máy bay.","audioKind":"ex"},{"en":"Construction should remain suspended pending a thorough assessment of its potential impact on the surrounding environment.","vi":"Công trình xây dựng nên tiếp tục tạm dừng trong lúc chờ đánh giá kỹ lưỡng về tác động tiềm tàng của nó đối với môi trường xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"pending approval","vi":"chờ phê duyệt"},{"en":"a pending application","vi":"hồ sơ đang chờ xử lý"},{"en":"pending investigation","vi":"chờ điều tra"}],"wordFamily":[],"synonyms":["unresolved","undecided"],"antonyms":["resolved","settled"],"tipVi":"Nghĩa chính là chưa được quyết định hay hoàn tất, không nhầm lẫn với urgent.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terminate', 'en-c1-40', 'terminate', '/ˈtɝːməneɪt/', 'C1', 'chấm dứt; kết thúc; chạy đến bến cuối (đối với phương tiện giao thông)', 'v.', 'termination (n.), terminal (adj.)', 'Đồng nghĩa: end, discontinue · Trái nghĩa: begin, continue', 'Từ mang văn phong trang trọng; có thể dùng ngoại động từ hoặc nội động từ, phương tiện kết thúc hành trình dùng at.', 'We decided to terminate our gym membership last month.', NULL, 'Chúng tôi đã quyết định chấm dứt hợp đồng tập gym vào tháng trước.', '{"wordId":"terminate","ukIpa":"/ˈtɜːmɪneɪt/","usIpa":"/ˈtɝːməneɪt/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To end something, or to come to an end.","vi":"chấm dứt; kết thúc"},{"pos":"v.","en":"For a transport service, to reach its final stop.","vi":"chạy đến bến cuối (đối với phương tiện giao thông)"}],"examples":[{"en":"We decided to terminate our gym membership last month.","vi":"Chúng tôi đã quyết định chấm dứt hợp đồng tập gym vào tháng trước.","audioKind":"ex"},{"en":"Employers should not terminate contracts without providing clear reasons and allowing workers sufficient time to respond.","vi":"Người sử dụng lao động không nên đơn phương chấm dứt hợp đồng mà không đưa ra lý do rõ ràng và cho nhân viên đủ thời gian phản hồi.","audioKind":"ex2"}],"collocations":[{"en":"terminate a contract","vi":"chấm dứt hợp đồng"},{"en":"terminate employment","vi":"chấm dứt quan hệ lao động"},{"en":"terminate at a station","vi":"kết thúc hành trình tại một nhà ga"}],"wordFamily":["termination (n.)","terminal (adj.)"],"synonyms":["end","discontinue"],"antonyms":["begin","continue"],"tipVi":"Từ mang văn phong trang trọng; có thể dùng ngoại động từ hoặc nội động từ, phương tiện kết thúc hành trình dùng at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invaluable', 'en-c1-40', 'invaluable', '/ɪnˈvæljuəbl/', 'C1', 'vô giá; cực kỳ quý giá; vô cùng hữu ích', 'adj.', 'value (n.), value (v.), valuable (adj.), valuation (n.)', 'Đồng nghĩa: precious, priceless · Trái nghĩa: worthless', 'Từ invaluable mang nghĩa vô cùng quý giá, hoàn toàn không có nghĩa là không có giá trị.', 'Your advice was invaluable when I bought my first bicycle.', NULL, 'Lời khuyên của bạn thực sự vô giá khi tôi mua chiếc xe đạp đầu tiên.', '{"wordId":"invaluable","ukIpa":"/ɪnˈvæljuəbl/","usIpa":"/ɪnˈvæljuəbl/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Extremely useful or valuable.","vi":"vô giá; cực kỳ quý giá; vô cùng hữu ích"}],"examples":[{"en":"Your advice was invaluable when I bought my first bicycle.","vi":"Lời khuyên của bạn thực sự vô giá khi tôi mua chiếc xe đạp đầu tiên.","audioKind":"ex"},{"en":"Practical work experience provides students with invaluable insights into the skills employers expect from new graduates.","vi":"Kinh nghiệm làm việc thực tế mang lại cho sinh viên những góc nhìn cực kỳ quý giá về các kỹ năng mà nhà tuyển dụng kỳ vọng ở các cử nhân mới ra trường.","audioKind":"ex2"}],"collocations":[{"en":"invaluable advice","vi":"lời khuyên quý giá"},{"en":"an invaluable resource","vi":"nguồn tài nguyên vô giá"},{"en":"prove invaluable","vi":"chứng tỏ vô cùng hữu ích"}],"wordFamily":["value (n.)","value (v.)","valuable (adj.)","valuation (n.)"],"synonyms":["precious","priceless"],"antonyms":["worthless"],"tipVi":"Từ invaluable mang nghĩa vô cùng quý giá, hoàn toàn không có nghĩa là không có giá trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cease', 'en-c1-40', 'cease', '/siːs/', 'C1', 'ngừng; chấm dứt; dừng lại', 'v.', 'cessation (n.), ceaseless (adj.), ceaselessly (adv.)', 'Đồng nghĩa: stop, discontinue · Trái nghĩa: continue, begin', 'Đây là từ mang văn phong trang trọng; sau nó có thể đi với danh động từ hoặc động từ nguyên thể có to với nghĩa dừng lại.', 'The bells finally ceased ringing just before midnight.', NULL, 'Tiếng chuông cuối cùng cũng ngừng reo ngay trước thời điểm nửa đêm.', '{"wordId":"cease","ukIpa":"/siːs/","usIpa":"/siːs/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"to stop happening or doing something","vi":"ngừng; chấm dứt; dừng lại"}],"examples":[{"en":"The bells finally ceased ringing just before midnight.","vi":"Tiếng chuông cuối cùng cũng ngừng reo ngay trước thời điểm nửa đêm.","audioKind":"ex"},{"en":"Factories should cease discharging untreated wastewater into rivers to protect aquatic ecosystems and safeguard public health.","vi":"Các nhà máy nên chấm dứt việc xả nước thải chưa qua xử lý ra sông ngòi để bảo vệ hệ sinh thái thủy sinh và gìn giữ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"cease operations","vi":"dừng hoạt động"},{"en":"cease to exist","vi":"không còn tồn tại"},{"en":"cease production","vi":"ngừng sản xuất"},{"en":"cease trading","vi":"dừng giao dịch"}],"wordFamily":["cessation (n.)","ceaseless (adj.)","ceaselessly (adv.)"],"synonyms":["stop","discontinue"],"antonyms":["continue","begin"],"tipVi":"Đây là từ mang văn phong trang trọng; sau nó có thể đi với danh động từ hoặc động từ nguyên thể có to với nghĩa dừng lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monotony', 'en-c1-40', 'monotony', '/məˈnɑːtəni/', 'C1', 'sự đơn điệu; sự nhàm chán; sự tẻ nhạt', 'n.', 'monotonous (adj.), monotonously (adv.)', 'Đồng nghĩa: sameness, tedium · Trái nghĩa: variety', 'Thường là danh từ không đếm được, nhấn mạnh sự thiếu thay đổi gây ra cảm giác chán ngắt.', 'A short walk broke the monotony of my afternoon.', NULL, 'Một buổi đi dạo ngắn đã phá vỡ sự tẻ nhạt vào buổi chiều của tôi.', '{"wordId":"monotony","ukIpa":"/məˈnɒtəni/","usIpa":"/məˈnɑːtəni/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"boring sameness caused by a lack of variety or change","vi":"sự đơn điệu; sự nhàm chán; sự tẻ nhạt"}],"examples":[{"en":"A short walk broke the monotony of my afternoon.","vi":"Một buổi đi dạo ngắn đã phá vỡ sự tẻ nhạt vào buổi chiều của tôi.","audioKind":"ex"},{"en":"Rotating tasks can reduce the monotony of factory work while helping employees develop a wider range of skills.","vi":"Việc luân chuyển công việc có thể làm giảm bớt sự nhàm chán của công việc nhà máy đồng thời giúp nhân viên phát triển nhiều kỹ năng hơn.","audioKind":"ex2"}],"collocations":[{"en":"break the monotony","vi":"phá vỡ sự đơn điệu"},{"en":"the monotony of daily life","vi":"sự tẻ nhạt của cuộc sống hàng ngày"},{"en":"relieve the monotony","vi":"giải tỏa sự nhàm chán"}],"wordFamily":["monotonous (adj.)","monotonously (adv.)"],"synonyms":["sameness","tedium"],"antonyms":["variety"],"tipVi":"Thường là danh từ không đếm được, nhấn mạnh sự thiếu thay đổi gây ra cảm giác chán ngắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_counsel', 'en-c1-40', 'counsel', '/ˈkaʊnsəl/', 'C1', 'lời khuyên; sự tư vấn; tư vấn; khuyên bảo; luật sư; cố vấn pháp lý', 'n.', 'counsellor (n.), counselling (n.)', NULL, 'counsel có nghĩa là lời khuyên hoặc luật sư; council có nghĩa là hội đồng.', 'I sought my aunt''s counsel before accepting the job.', NULL, 'Tôi đã xin lời khuyên của gì trước khi nhận công việc đó.', '{"wordId":"counsel","ukIpa":"/ˈkaʊnsəl/","usIpa":"/ˈkaʊnsəl/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"advice, especially from someone experienced or knowledgeable","vi":"lời khuyên; sự tư vấn"},{"pos":"v.","en":"to give someone advice or professional support","vi":"tư vấn; khuyên bảo"},{"pos":"n.","en":"a lawyer or lawyers representing someone in a legal case","vi":"luật sư; cố vấn pháp lý"}],"examples":[{"en":"I sought my aunt''s counsel before accepting the job.","vi":"Tôi đã xin lời khuyên của gì trước khi nhận công việc đó.","audioKind":"ex"},{"en":"Schools should employ trained professionals to counsel students who experience anxiety about examinations or future careers.","vi":"Các trường học nên thuê các chuyên gia được đào tạo bài bản để tư vấn cho những học sinh gặp lo lắng về kỳ thi hoặc nghề nghiệp tương lai.","audioKind":"ex2"}],"collocations":[{"en":"seek counsel","vi":"xin lời khuyên"},{"en":"legal counsel","vi":"cố vấn pháp lý"},{"en":"counsel someone against something","vi":"khuyên ai đó không nên làm gì"},{"en":"wise counsel","vi":"lời khuyên sáng suốt"}],"wordFamily":["counsellor (n.)","counselling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"counsel có nghĩa là lời khuyên hoặc luật sư; council có nghĩa là hội đồng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_induction', 'en-c1-40', 'induction', '/ɪnˈdʌkʃən/', 'C1', 'buổi hướng dẫn hội nhập; lễ nhậm chức; phép quy nạp; suy luận quy nạp; hiện tượng cảm ứng điện từ', 'n.', 'induct (v.), inductive (adj.), induce (v.)', NULL, 'induction thường dùng cho việc gia nhập tổ chức; quy nạp đối lập với deduction là diễn dịch.', 'Our induction included a tour of the whole office.', NULL, 'Buổi hướng dẫn hội nhập của chúng tôi bao gồm việc tham quan toàn bộ văn phòng.', '{"wordId":"induction","ukIpa":"/ɪnˈdʌkʃən/","usIpa":"/ɪnˈdʌkʃən/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"training or formal introduction when someone joins an organisation","vi":"buổi hướng dẫn hội nhập; lễ nhậm chức"},{"pos":"n.","en":"forming general conclusions from particular observations","vi":"phép quy nạp; suy luận quy nạp"},{"pos":"n.","en":"production of electrical effects by a changing magnetic field","vi":"hiện tượng cảm ứng điện từ"}],"examples":[{"en":"Our induction included a tour of the whole office.","vi":"Buổi hướng dẫn hội nhập của chúng tôi bao gồm việc tham quan toàn bộ văn phòng.","audioKind":"ex"},{"en":"A structured induction programme can help new employees understand workplace expectations and adapt to their roles.","vi":"Một chương trình hội nhập được tổ chức bài bản có thể giúp nhân viên mới hiểu rõ các kỳ vọng tại nơi làm việc và thích nghi với vai trò của họ.","audioKind":"ex2"}],"collocations":[{"en":"induction programme","vi":"chương trình hội nhập nhân sự"},{"en":"induction into office","vi":"lễ nhậm chức"},{"en":"electromagnetic induction","vi":"hiện tượng cảm ứng điện từ"},{"en":"inductive reasoning","vi":"lập luận quy nạp"}],"wordFamily":["induct (v.)","inductive (adj.)","induce (v.)"],"synonyms":[],"antonyms":[],"tipVi":"induction thường dùng cho việc gia nhập tổ chức; quy nạp đối lập với deduction là diễn dịch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_burdensome', 'en-c1-40', 'burdensome', '/ˈbɜːrdənsəm/', 'C1', 'gây gánh nặng; phiền hà; nặng nề', 'adj.', 'burden (n.), burden (v.), burdened (adj.)', 'Đồng nghĩa: onerous, troublesome', 'Thường dùng để chỉ nhiệm vụ, chi phí hoặc quy định, không dùng để chỉ trọng lượng vật lý của đồ vật.', 'The extra paperwork became burdensome during our busiest week.', NULL, 'Lượng thủ tục giấy tờ phát sinh đã trở nên nặng nề trong tuần bận rộn nhất của chúng tôi.', '{"wordId":"burdensome","ukIpa":"/ˈbɜːdənsəm/","usIpa":"/ˈbɜːrdənsəm/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"causing difficulty through excessive work, worry, or expense","vi":"gây gánh nặng; phiền hà; nặng nề"}],"examples":[{"en":"The extra paperwork became burdensome during our busiest week.","vi":"Lượng thủ tục giấy tờ phát sinh đã trở nên nặng nề trong tuần bận rộn nhất của chúng tôi.","audioKind":"ex"},{"en":"Overly burdensome regulations may discourage small businesses from expanding, even when demand for their products is strong.","vi":"Các quy định quá mức phiền hà có thể làm nản lòng các doanh nghiệp nhỏ trong việc mở rộng quy mô, ngay cả khi nhu cầu về sản phẩm của họ đang rất mạnh.","audioKind":"ex2"}],"collocations":[{"en":"burdensome regulations","vi":"quy định nặng nề"},{"en":"burdensome task","vi":"nhiệm vụ nặng nhọc"},{"en":"financially burdensome","vi":"gây gánh nặng tài chính"}],"wordFamily":["burden (n.)","burden (v.)","burdened (adj.)"],"synonyms":["onerous","troublesome"],"antonyms":[],"tipVi":"Thường dùng để chỉ nhiệm vụ, chi phí hoặc quy định, không dùng để chỉ trọng lượng vật lý của đồ vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pinnacle', 'en-c1-40', 'pinnacle', '/ˈpɪnəkəl/', 'C1', 'đỉnh cao; đỉnh vinh quang; tột đỉnh; đỉnh nhọn; chóp nhọn', 'n.', NULL, 'Đồng nghĩa: peak, apex, zenith · Trái nghĩa: nadir', 'Nghĩa ẩn dụ thường dùng the pinnacle of để chỉ đỉnh cao của thành tựu.', 'Winning the tournament was the pinnacle of her career.', NULL, 'Chiến thắng giải đấu là đỉnh cao trong sự nghiệp của cô ấy.', '{"wordId":"pinnacle","ukIpa":"/ˈpɪnəkəl/","usIpa":"/ˈpɪnəkəl/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"The highest level of success, achievement or development.","vi":"đỉnh cao; đỉnh vinh quang; tột đỉnh"},{"pos":"n.","en":"A tall pointed rock or pointed structure on a building.","vi":"đỉnh nhọn; chóp nhọn"}],"examples":[{"en":"Winning the tournament was the pinnacle of her career.","vi":"Chiến thắng giải đấu là đỉnh cao trong sự nghiệp của cô ấy.","audioKind":"ex"},{"en":"For many researchers, international recognition represents the pinnacle of a career devoted to scientific discovery.","vi":"Đối với nhiều nhà nghiên cứu, sự công nhận quốc tế tượng trưng cho đỉnh cao của sự nghiệp cống hiến cho khám phá khoa học.","audioKind":"ex2"}],"collocations":[{"en":"the pinnacle of success","vi":"đỉnh cao của sự thành công"},{"en":"reach the pinnacle","vi":"đạt tới đỉnh cao"},{"en":"a rocky pinnacle","vi":"một chóp đá nhọn"}],"wordFamily":[],"synonyms":["peak","apex","zenith"],"antonyms":["nadir"],"tipVi":"Nghĩa ẩn dụ thường dùng the pinnacle of để chỉ đỉnh cao của thành tựu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_first-rate', 'en-c1-40', 'first-rate', '/ˌfɜːrst ˈreɪt/', 'C1', 'hạng nhất; chất lượng cao; tuyệt vời', 'adj.', NULL, 'Đồng nghĩa: excellent, outstanding, superb · Trái nghĩa: second-rate, inferior', 'first-rate chỉ chất lượng xuất sắc, hàng đầu chứ không có nghĩa là "đánh giá lần đầu tiên".', 'The small restaurant serves first-rate food at reasonable prices.', NULL, 'Nhà hàng nhỏ này phục vụ những món ăn thượng hạng với mức giá hợp lý.', '{"wordId":"first-rate","ukIpa":"/ˌfɜːst ˈreɪt/","usIpa":"/ˌfɜːrst ˈreɪt/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Of excellent quality or exceptionally high ability.","vi":"hạng nhất; chất lượng cao; tuyệt vời"}],"examples":[{"en":"The small restaurant serves first-rate food at reasonable prices.","vi":"Nhà hàng nhỏ này phục vụ những món ăn thượng hạng với mức giá hợp lý.","audioKind":"ex"},{"en":"Access to first-rate training enables young workers to develop skills that employers increasingly value.","vi":"Việc tiếp cận các khóa đào tạo chất lượng cao giúp lao động trẻ phát triển những kỹ năng ngày càng được các nhà tuyển dụng coi trọng.","audioKind":"ex2"}],"collocations":[{"en":"first-rate service","vi":"dịch vụ hạng nhất"},{"en":"a first-rate education","vi":"nền giáo dục hàng đầu"},{"en":"a first-rate performance","vi":"màn trình diễn xuất sắc"}],"wordFamily":[],"synonyms":["excellent","outstanding","superb"],"antonyms":["second-rate","inferior"],"tipVi":"first-rate chỉ chất lượng xuất sắc, hàng đầu chứ không có nghĩa là \"đánh giá lần đầu tiên\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subordinate', 'en-c1-40', 'subordinate', '/səˈbɔːrdɪnət/', 'C1', 'cấp dưới, phụ, thứ yếu; cấp dưới, người dưới quyền', 'adj.', 'subordination (n.)', 'Đồng nghĩa: junior · Trái nghĩa: superior', 'Diễn đạt ý "trực thuộc, phụ thuộc" dùng subordinate to, không dùng than.', 'She accepted a subordinate role on the project.', NULL, 'Cô ấy nhận một vai trò hỗ trợ trong dự án này.', '{"wordId":"subordinate","ukIpa":"/səˈbɔːdɪnət/","usIpa":"/səˈbɔːrdɪnət/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"Lower in rank, authority, or importance.","vi":"cấp dưới, phụ, thứ yếu"},{"pos":"n.","en":"Someone with a lower position under another person''s authority.","vi":"cấp dưới, người dưới quyền"}],"examples":[{"en":"She accepted a subordinate role on the project.","vi":"Cô ấy nhận một vai trò hỗ trợ trong dự án này.","audioKind":"ex"},{"en":"In effective organisations, subordinate staff should feel comfortable raising concerns with senior managers without fear.","vi":"Trong các tổ chức hiệu quả, nhân viên cấp dưới nên cảm thấy thoải mái khi trình bày các mối bận tâm với quản lý cấp cao mà không phải sợ hãi.","audioKind":"ex2"}],"collocations":[{"en":"subordinate to","vi":"thuộc về, kém quan trọng hơn"},{"en":"a subordinate role","vi":"vai trò phụ"},{"en":"subordinate staff","vi":"nhân viên cấp dưới"},{"en":"a subordinate clause","vi":"mệnh đề phụ"}],"wordFamily":["subordination (n.)"],"synonyms":["junior"],"antonyms":["superior"],"tipVi":"Diễn đạt ý \"trực thuộc, phụ thuộc\" dùng subordinate to, không dùng than.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appraisal', 'en-c1-40', 'appraisal', '/əˈpreɪzəl/', 'C1', 'sự đánh giá; sự thẩm định; sự định giá', 'n.', 'appraise (v.), appraiser (n.)', 'Đồng nghĩa: assessment, evaluation', 'Appraisal là sự đánh giá; tránh nhầm lẫn với approval (sự phê duyệt).', 'My manager praised my progress during today''s performance appraisal.', NULL, 'Quản lý của tôi đã ca ngợi sự tiến bộ của tôi trong buổi đánh giá năng lực làm việc hôm nay.', '{"wordId":"appraisal","ukIpa":"/əˈpreɪzəl/","usIpa":"/əˈpreɪzəl/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"a careful judgment of quality, performance, or a situation","vi":"sự đánh giá; sự thẩm định"},{"pos":"n.","en":"an expert estimate of how much something is worth","vi":"sự định giá"}],"examples":[{"en":"My manager praised my progress during today''s performance appraisal.","vi":"Quản lý của tôi đã ca ngợi sự tiến bộ của tôi trong buổi đánh giá năng lực làm việc hôm nay.","audioKind":"ex"},{"en":"A thorough appraisal of environmental risks should take place before any major construction project begins.","vi":"Việc đánh giá toàn diện các rủi ro môi trường cần được tiến hành trước khi bất kỳ dự án xây dựng lớn nào khởi động.","audioKind":"ex2"}],"collocations":[{"en":"performance appraisal","vi":"đánh giá năng lực công việc"},{"en":"critical appraisal","vi":"đánh giá phản biện"},{"en":"property appraisal","vi":"định giá bất động sản"},{"en":"appraisal process","vi":"quy trình đánh giá"}],"wordFamily":["appraise (v.)","appraiser (n.)"],"synonyms":["assessment","evaluation"],"antonyms":[],"tipVi":"Appraisal là sự đánh giá; tránh nhầm lẫn với approval (sự phê duyệt).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inventory', 'en-c1-40', 'inventory', '/ˈɪnvəntɔːri/', 'C1', 'bảng kiểm kê tài sản; danh mục hàng hóa; hàng tồn kho; lượng hàng dự trữ; kiểm kê; lập danh mục', 'n.', NULL, NULL, 'Nghĩa chỉ hàng tồn kho xuất hiện phổ biến trong tiếng Anh-Mỹ, trong khi tiếng Anh-Anh thường dùng stock.', 'We made an inventory of everything in the garage.', NULL, 'Chúng tôi đã lập danh mục kiểm kê cho mọi thứ trong nhà để xe.', '{"wordId":"inventory","ukIpa":"/ˈɪnvəntri/","usIpa":"/ˈɪnvəntɔːri/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A detailed list of items owned or stored somewhere.","vi":"bảng kiểm kê tài sản; danh mục hàng hóa"},{"pos":"n.","en":"The goods a business keeps available for sale.","vi":"hàng tồn kho; lượng hàng dự trữ"},{"pos":"v.","en":"To make a detailed list of items.","vi":"kiểm kê; lập danh mục"}],"examples":[{"en":"We made an inventory of everything in the garage.","vi":"Chúng tôi đã lập danh mục kiểm kê cho mọi thứ trong nhà để xe.","audioKind":"ex"},{"en":"Digital systems help retailers manage inventory more efficiently, reducing waste and preventing shortages of essential products.","vi":"Các hệ thống kỹ thuật số giúp nhà bán lẻ quản lý hàng tồn kho hiệu quả hơn, giảm thiểu lãng phí và ngăn chặn tình trạng thiếu hụt sản phẩm thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"make an inventory","vi":"lập bảng kiểm kê"},{"en":"inventory management","vi":"quản lý hàng tồn kho"},{"en":"inventory levels","vi":"mức độ hàng tồn kho"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chỉ hàng tồn kho xuất hiện phổ biến trong tiếng Anh-Mỹ, trong khi tiếng Anh-Anh thường dùng stock.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_practitioner', 'en-c1-40', 'practitioner', '/prækˈtɪʃənər/', 'C1', 'bác sĩ hành nghề; người hành nghề chuyên môn; người thực hành (một kỹ năng hoặc phương pháp nào đó)', 'n.', 'practice (n.), practise (v.), practical (adj.)', NULL, 'Cụm ''general practitioner'' chỉ bác sĩ đa khoa, thường được viết tắt là GP.', 'The nurse suggested speaking to a qualified medical practitioner.', NULL, 'Nữ hộ sinh gợi ý nên trao đổi với một y bác sĩ có chuyên môn.', '{"wordId":"practitioner","ukIpa":"/prækˈtɪʃənə/","usIpa":"/prækˈtɪʃənər/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"someone who works in a profession, especially medicine","vi":"bác sĩ hành nghề; người hành nghề chuyên môn"},{"pos":"n.","en":"someone who regularly uses a particular skill or method","vi":"người thực hành (một kỹ năng hoặc phương pháp nào đó)"}],"examples":[{"en":"The nurse suggested speaking to a qualified medical practitioner.","vi":"Nữ hộ sinh gợi ý nên trao đổi với một y bác sĩ có chuyên môn.","audioKind":"ex"},{"en":"Experienced practitioners should help design training programmes so that graduates develop skills relevant to their profession.","vi":"Những người hành nghề có kinh nghiệm nên tham gia thiết kế chương trình đào tạo để sinh viên tốt nghiệp có được các kỹ năng phù hợp với nghề nghiệp của họ.","audioKind":"ex2"}],"collocations":[{"en":"general practitioner","vi":"bác sĩ đa khoa"},{"en":"medical practitioner","vi":"bác sĩ y khoa"},{"en":"experienced practitioner","vi":"người hành nghề có kinh nghiệm"}],"wordFamily":["practice (n.)","practise (v.)","practical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm ''general practitioner'' chỉ bác sĩ đa khoa, thường được viết tắt là GP.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_idleness', 'en-c1-40', 'idleness', '/ˈaɪdəlnəs/', 'C1', 'sự nhàn rỗi; sự vô công rỗi nghề; tính lười biếng', 'n.', 'idle (adj.), idle (v.), idly (adv.)', 'Đồng nghĩa: inactivity, laziness · Trái nghĩa: activity, industry', 'danh từ không đếm được; có thể chỉ sự lười biếng hoặc tình trạng phải rảnh rỗi không có việc làm.', 'After weeks of idleness, I finally cleaned the garage.', NULL, 'Sau nhiều tuần nhàn rỗi, cuối cùng tôi cũng dọn dẹp xong nhà để xe.', '{"wordId":"idleness","ukIpa":"/ˈaɪdəlnəs/","usIpa":"/ˈaɪdəlnəs/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"The state of not working or doing anything.","vi":"sự nhàn rỗi; sự vô công rỗi nghề; tính lười biếng"}],"examples":[{"en":"After weeks of idleness, I finally cleaned the garage.","vi":"Sau nhiều tuần nhàn rỗi, cuối cùng tôi cũng dọn dẹp xong nhà để xe.","audioKind":"ex"},{"en":"Long periods of enforced idleness during unemployment can damage confidence and make returning to work more difficult.","vi":"Khoảng thời gian dài buộc phải nhàn rỗi trong lúc thất nghiệp có thể làm tổn hại lòng tự tin và khiến việc quay trở lại làm việc trở nên khó khăn hơn.","audioKind":"ex2"}],"collocations":[{"en":"enforced idleness","vi":"sự buộc phải nhàn rỗi"},{"en":"a life of idleness","vi":"cuộc sống nhàn rỗi"},{"en":"sheer idleness","vi":"sự lười biếng thuần túy"}],"wordFamily":["idle (adj.)","idle (v.)","idly (adv.)"],"synonyms":["inactivity","laziness"],"antonyms":["activity","industry"],"tipVi":"danh từ không đếm được; có thể chỉ sự lười biếng hoặc tình trạng phải rảnh rỗi không có việc làm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_industrious', 'en-c1-40', 'industrious', '/ɪnˈdʌstriəs/', 'C1', 'làm việc chăm chỉ và cẩn thận trong một khoảng thời gian dài; cần cù, chăm chỉ', 'adj.', 'industriously (adv.), industriousness (n.)', 'Đồng nghĩa: hard-working, diligent · Trái nghĩa: lazy, idle', 'Industrious nghĩa là chăm chỉ; industrial nghĩa là thuộc về công nghiệp.', 'My industrious neighbour grows vegetables and repairs furniture every weekend.', NULL, 'Người hàng xóm cần cù của tôi trồng rau và sửa đồ đạc vào mỗi cuối tuần.', '{"wordId":"industrious","ukIpa":"/ɪnˈdʌstriəs/","usIpa":"/ɪnˈdʌstriəs/","cefr":"C1","topic":"work","senses":[{"pos":"adj.","en":"working hard and carefully over a sustained period","vi":"làm việc chăm chỉ và cẩn thận trong một khoảng thời gian dài; cần cù, chăm chỉ"}],"examples":[{"en":"My industrious neighbour grows vegetables and repairs furniture every weekend.","vi":"Người hàng xóm cần cù của tôi trồng rau và sửa đồ đạc vào mỗi cuối tuần.","audioKind":"ex"},{"en":"Although industrious employees contribute greatly to productivity, employers must also provide adequate training and reasonable working conditions.","vi":"Mặc dù những nhân viên chăm chỉ đóng góp lớn vào năng suất, các nhà tuyển dụng cũng phải cung cấp đầy đủ đào tạo và điều kiện làm việc hợp lý.","audioKind":"ex2"}],"collocations":[{"en":"an industrious worker","vi":"một công nhân cần cù"},{"en":"an industrious student","vi":"một học sinh chăm chỉ"}],"wordFamily":["industriously (adv.)","industriousness (n.)"],"synonyms":["hard-working","diligent"],"antonyms":["lazy","idle"],"tipVi":"Industrious nghĩa là chăm chỉ; industrial nghĩa là thuộc về công nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inefficiency', 'en-c1-40', 'inefficiency', '/ˌɪnɪˈfɪʃənsi/', 'C1', 'sự kém hiệu quả; tính kém năng suất', 'n.', 'inefficient (adj.), inefficiently (adv.), efficiency (n.), efficient (adj.)', 'Trái nghĩa: efficiency', 'Chỉ sự lãng phí thời gian hoặc nguồn lực, không đồng nghĩa với việc cá nhân hoàn toàn bất tài.', 'The kitchen''s inefficiency left everyone waiting for dinner.', NULL, 'Sự thiếu hiệu quả trong căn bếp đã khiến tất cả mọi người phải chờ bữa tối.', '{"wordId":"inefficiency","ukIpa":"/ˌɪnɪˈfɪʃənsi/","usIpa":"/ˌɪnɪˈfɪʃənsi/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"failure to use time, money, or resources well","vi":"sự kém hiệu quả; tính kém năng suất"}],"examples":[{"en":"The kitchen''s inefficiency left everyone waiting for dinner.","vi":"Sự thiếu hiệu quả trong căn bếp đã khiến tất cả mọi người phải chờ bữa tối.","audioKind":"ex"},{"en":"Investment in modern equipment can reduce inefficiency and improve productivity across the manufacturing sector.","vi":"Việc đầu tư vào các thiết bị hiện đại có thể làm giảm tình trạng kém hiệu quả và nâng cao năng suất trong toàn ngành sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"operational inefficiency","vi":"sự kém hiệu quả trong vận hành"},{"en":"reduce inefficiency","vi":"giảm thiểu sự kém hiệu quả"},{"en":"administrative inefficiency","vi":"sự kém hiệu quả trong quản lý hành chính"}],"wordFamily":["inefficient (adj.)","inefficiently (adv.)","efficiency (n.)","efficient (adj.)"],"synonyms":[],"antonyms":["efficiency"],"tipVi":"Chỉ sự lãng phí thời gian hoặc nguồn lực, không đồng nghĩa với việc cá nhân hoàn toàn bất tài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_correspondence', 'en-c1-40', 'correspondence', '/ˌkɔːrəˈspɑːndəns/', 'C1', 'thư từ; sự trao đổi thư tín; sự tương ứng; nét tương đồng', 'n.', 'correspond (v.), correspondent (n.), corresponding (adj.)', NULL, 'Khi chỉ thư từ trao đổi, đây là danh từ không đếm được; đi với giới từ with khi nói về việc liên lạc với ai.', 'She keeps her correspondence with her cousin in a drawer.', NULL, 'Cô ấy cất giữ những bức thư từ qua lại với người anh họ trong một chiếc ngăn kéo.', '{"wordId":"correspondence","ukIpa":"/ˌkɒrəˈspɒndəns/","usIpa":"/ˌkɔːrəˈspɑːndəns/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"Written communication between people, or the messages they exchange.","vi":"thư từ; sự trao đổi thư tín"},{"pos":"n.","en":"A close similarity or connection between two things.","vi":"sự tương ứng; nét tương đồng"}],"examples":[{"en":"She keeps her correspondence with her cousin in a drawer.","vi":"Cô ấy cất giữ những bức thư từ qua lại với người anh họ trong một chiếc ngăn kéo.","audioKind":"ex"},{"en":"Historical correspondence can reveal how ordinary families experienced social changes that official records describe only briefly.","vi":"Những tư liệu thư từ lịch sử có thể tiết lộ cách các gia đình bình dân trải qua những biến động xã hội mà các tài liệu chính thống chỉ nhắc đến vắn tắt.","audioKind":"ex2"}],"collocations":[{"en":"correspondence with someone","vi":"thư từ qua lại với ai đó"},{"en":"business correspondence","vi":"thư tín thương mại"},{"en":"correspondence between","vi":"sự tương ứng giữa"}],"wordFamily":["correspond (v.)","correspondent (n.)","corresponding (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ thư từ trao đổi, đây là danh từ không đếm được; đi với giới từ with khi nói về việc liên lạc với ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brewery', 'en-c1-40', 'brewery', '/ˈbruːəri/', 'C1', 'nhà máy bia', 'n.', 'brew (v.), brewer (n.), brewing (n.)', NULL, 'Thường chỉ nhà máy sản xuất bia; nhà máy sản xuất rượu vang gọi là winery.', 'The old brewery has become a popular local museum.', NULL, 'Nhà máy bia cũ nay đã trở thành một bảo tàng địa phương nổi tiếng.', '{"wordId":"brewery","ukIpa":"/ˈbruːəri/","usIpa":"/ˈbruːəri/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A place where beer is produced commercially.","vi":"nhà máy bia"}],"examples":[{"en":"The old brewery has become a popular local museum.","vi":"Nhà máy bia cũ nay đã trở thành một bảo tàng địa phương nổi tiếng.","audioKind":"ex"},{"en":"Converting a historic brewery into a cultural centre can preserve industrial heritage while creating new employment opportunities.","vi":"Việc chuyển đổi một nhà máy bia lịch sử thành trung tâm văn hóa vừa giúp bảo tồn di sản công nghiệp vừa tạo ra cơ hội việc làm mới.","audioKind":"ex2"}],"collocations":[{"en":"local brewery","vi":"nhà máy bia địa phương"},{"en":"craft brewery","vi":"xưởng nấu bia thủ công"},{"en":"brewery tour","vi":"tour tham quan nhà máy bia"}],"wordFamily":["brew (v.)","brewer (n.)","brewing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ nhà máy sản xuất bia; nhà máy sản xuất rượu vang gọi là winery.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_initiate', 'en-c1-40', 'initiate', '/ɪˈnɪʃieɪt/', 'C1', 'khởi đầu; phát động; khởi xướng; dẫn dắt nhập môn; kết nạp vào hội', 'v.', 'initiation (n.), initiator (n.), initiative (n.)', 'Đồng nghĩa: begin, launch · Trái nghĩa: terminate', 'Động từ mang sắc thái trang trọng; cấu trúc initiate sb into dùng khi chỉ việc dẫn dắt ai vào một lĩnh vực hoặc hội nhóm.', 'Someone needs to initiate a conversation about the noise.', NULL, 'Cần phải có ai đó khơi mào cuộc thảo luận về vấn đề tiếng ồn này.', '{"wordId":"initiate","ukIpa":"/ɪˈnɪʃieɪt/","usIpa":"/ɪˈnɪʃieɪt/","cefr":"C1","topic":"work","senses":[{"pos":"v.","en":"To cause a process or activity to begin.","vi":"khởi đầu; phát động; khởi xướng"},{"pos":"v.","en":"To introduce someone to an activity or admit them to a group.","vi":"dẫn dắt nhập môn; kết nạp vào hội"}],"examples":[{"en":"Someone needs to initiate a conversation about the noise.","vi":"Cần phải có ai đó khơi mào cuộc thảo luận về vấn đề tiếng ồn này.","audioKind":"ex"},{"en":"Local authorities should initiate programmes that encourage residents to recycle household waste more effectively.","vi":"Chính quyền địa phương nên khởi động các chương trình khuyến khích cư dân tái chế rác thải sinh hoạt hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"initiate negotiations","vi":"mở cuộc đàm phán"},{"en":"initiate a project","vi":"bắt đầu một dự án"},{"en":"initiate someone into","vi":"dẫn dắt ai đó nhập môn"}],"wordFamily":["initiation (n.)","initiator (n.)","initiative (n.)"],"synonyms":["begin","launch"],"antonyms":["terminate"],"tipVi":"Động từ mang sắc thái trang trọng; cấu trúc initiate sb into dùng khi chỉ việc dẫn dắt ai vào một lĩnh vực hoặc hội nhóm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hierarchy', 'en-c1-40', 'hierarchy', '/ˈhaɪərɑːrki/', 'C1', 'hệ thống phân cấp; thứ bậc; tầng lớp lãnh đạo; cấp trên', 'n.', 'hierarchical (adj.), hierarchically (adv.)', 'Đồng nghĩa: ranking', 'Có thể dùng để chỉ cấu trúc cấp bậc hoặc tầng lớp lãnh đạo cấp cao nhất trong một tổ chức.', 'There is a clear hierarchy among the restaurant staff.', NULL, 'Có một hệ thống thứ bậc rõ ràng giữa các nhân viên nhà hàng.', '{"wordId":"hierarchy","ukIpa":"/ˈhaɪərɑːki/","usIpa":"/ˈhaɪərɑːrki/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"A system arranging people or things by rank or importance","vi":"hệ thống phân cấp; thứ bậc"},{"pos":"n.","en":"The people holding the highest positions in an organisation","vi":"tầng lớp lãnh đạo; cấp trên"}],"examples":[{"en":"There is a clear hierarchy among the restaurant staff.","vi":"Có một hệ thống thứ bậc rõ ràng giữa các nhân viên nhà hàng.","audioKind":"ex"},{"en":"A rigid workplace hierarchy may discourage junior employees from sharing ideas that could improve organisational performance.","vi":"Hệ thống phân cấp cứng nhắc nơi công sở có thể khiến nhân viên cấp dưới ngần ngại chia sẻ những ý tưởng có thể cải thiện hiệu suất của tổ chức.","audioKind":"ex2"}],"collocations":[{"en":"a rigid hierarchy","vi":"hệ thống phân cấp cứng nhắc"},{"en":"organisational hierarchy","vi":"cấu trúc phân cấp tổ chức"},{"en":"a hierarchy of needs","vi":"tháp nhu cầu"},{"en":"the top of the hierarchy","vi":"đỉnh của hệ thống phân cấp"}],"wordFamily":["hierarchical (adj.)","hierarchically (adv.)"],"synonyms":["ranking"],"antonyms":[],"tipVi":"Có thể dùng để chỉ cấu trúc cấp bậc hoặc tầng lớp lãnh đạo cấp cao nhất trong một tổ chức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_backlog', 'en-c1-40', 'backlog', '/ˈbæklɔːɡ/', 'C1', 'công việc tồn đọng; đơn hàng chờ xử lý', 'n.', NULL, NULL, 'Thường đi với cấu trúc a backlog of, chỉ những công việc lẽ ra phải được giải quyết nhưng bị ùn lại.', 'I stayed late to clear a backlog of emails.', NULL, 'Tôi ở lại muộn để xử lý xong đống email đang bị tồn đọng.', '{"wordId":"backlog","ukIpa":"/ˈbæklɒɡ/","usIpa":"/ˈbæklɔːɡ/","cefr":"C1","topic":"work","senses":[{"pos":"n.","en":"work or orders waiting to be dealt with","vi":"công việc tồn đọng; đơn hàng chờ xử lý"}],"examples":[{"en":"I stayed late to clear a backlog of emails.","vi":"Tôi ở lại muộn để xử lý xong đống email đang bị tồn đọng.","audioKind":"ex"},{"en":"Hiring additional staff could help hospitals reduce the backlog of patients waiting for routine operations.","vi":"Việc tuyển dụng thêm nhân sự có thể giúp các bệnh viện giảm bớt số lượng bệnh nhân đang chờ đợi các ca phẫu thuật thông thường.","audioKind":"ex2"}],"collocations":[{"en":"clear a backlog","vi":"giải quyết công việc tồn đọng"},{"en":"a backlog of orders","vi":"lượng đơn hàng tồn đọng"},{"en":"reduce the backlog","vi":"giảm bớt sự tồn đọng"},{"en":"a growing backlog","vi":"tình trạng tồn đọng ngày càng tăng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường đi với cấu trúc a backlog of, chỉ những công việc lẽ ra phải được giải quyết nhưng bị ùn lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_40_1', 'en-c1-40', 'Cách dùng “cease” (v.) — ngừng; chấm dứt; dừng lại', 'cease operations  ·  cease to exist  ·  cease production', 'Đây là từ mang văn phong trang trọng; sau nó có thể đi với danh động từ hoặc động từ nguyên thể có to với nghĩa dừng lại.', 'Họ từ (Word Family): cessation (n.), ceaseless (adj.), ceaselessly (adv.) | Đồng nghĩa: stop, discontinue · Trái nghĩa: continue, begin', '[{"hanzi":"The bells finally ceased ringing just before midnight.","pinyin":"","meaning":"Tiếng chuông cuối cùng cũng ngừng reo ngay trước thời điểm nửa đêm."},{"hanzi":"Factories should cease discharging untreated wastewater into rivers to protect aquatic ecosystems and safeguard public health.","pinyin":"","meaning":"Các nhà máy nên chấm dứt việc xả nước thải chưa qua xử lý ra sông ngòi để bảo vệ hệ sinh thái thủy sinh và gìn giữ sức khỏe cộng đồng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_40_2', 'en-c1-40', 'Cách dùng “initiate” (v.) — khởi đầu; phát động; khởi xướng', 'initiate negotiations  ·  initiate a project  ·  initiate someone into', 'Động từ mang sắc thái trang trọng; cấu trúc initiate sb into dùng khi chỉ việc dẫn dắt ai vào một lĩnh vực hoặc hội nhóm.', 'Họ từ (Word Family): initiation (n.), initiator (n.), initiative (n.) | Đồng nghĩa: begin, launch · Trái nghĩa: terminate', '[{"hanzi":"Someone needs to initiate a conversation about the noise.","pinyin":"","meaning":"Cần phải có ai đó khơi mào cuộc thảo luận về vấn đề tiếng ồn này."},{"hanzi":"Local authorities should initiate programmes that encourage residents to recycle household waste more effectively.","pinyin":"","meaning":"Chính quyền địa phương nên khởi động các chương trình khuyến khích cư dân tái chế rác thải sinh hoạt hiệu quả hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_40_3', 'en-c1-40', 'Cách dùng “terminate” (v.) — chấm dứt; kết thúc', 'terminate a contract  ·  terminate employment  ·  terminate at a station', 'Từ mang văn phong trang trọng; có thể dùng ngoại động từ hoặc nội động từ, phương tiện kết thúc hành trình dùng at.', 'Họ từ (Word Family): termination (n.), terminal (adj.) | Đồng nghĩa: end, discontinue · Trái nghĩa: begin, continue', '[{"hanzi":"We decided to terminate our gym membership last month.","pinyin":"","meaning":"Chúng tôi đã quyết định chấm dứt hợp đồng tập gym vào tháng trước."},{"hanzi":"Employers should not terminate contracts without providing clear reasons and allowing workers sufficient time to respond.","pinyin":"","meaning":"Người sử dụng lao động không nên đơn phương chấm dứt hợp đồng mà không đưa ra lý do rõ ràng và cho nhân viên đủ thời gian phản hồi."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_40_4', 'en-c1-40', 'Cách dùng “aspire” (v.) — khao khát; hoài bão; chí hướng', 'aspire to do something  ·  aspire to greatness  ·  aspire to a career in medicine', 'Aspire to do dùng để chỉ việc ấp ủ hoài bão làm gì; ngoài ra aspire to cũng có thể theo sau bởi một danh từ.', 'Họ từ (Word Family): aspiration (n.), aspiring (adj.), aspirant (n.) | Đồng nghĩa: aim', '[{"hanzi":"My younger sister aspires to become a wildlife photographer.","pinyin":"","meaning":"Em gái tôi có ước mơ trở thành một nhiếp ảnh gia động vật hoang dã."},{"hanzi":"Many young people aspire to careers that offer both financial security and opportunities to contribute to society.","pinyin":"","meaning":"Nhiều người trẻ tuổi khát khao theo đuổi những nghề nghiệp vừa mang lại sự ổn định tài chính vừa có cơ hội đóng góp cho xã hội."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_40_1', 'en-c1-40', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_1_1', 'ten_c1_40_1', 'aspire', 'My younger sister aspires to become a wildlife photographer.', 'My younger sister aspires to become a wildlife photographer.', '/əˈspaɪr/', 'Em gái tôi có ước mơ trở thành một nhiếp ảnh gia động vật hoang dã.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_1_2', 'ten_c1_40_1', 'reap', 'After months of practice, she finally reaped the rewards.', 'After months of practice, she finally reaped the rewards.', '/riːp/', 'Sau nhiều tháng luyện tập, cuối cùng cô ấy đã gặt hái được những thành quả xứng đáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_1_3', 'ten_c1_40_1', 'pending', 'Our application is still pending, so we cannot book flights.', 'Our application is still pending, so we cannot book flights.', '/ˈpendɪŋ/', 'Hồ sơ của chúng tôi vẫn đang chờ xét duyệt nên chúng tôi chưa thể đặt vé máy bay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_1_4', 'ten_c1_40_1', 'terminate', 'We decided to terminate our gym membership last month.', 'We decided to terminate our gym membership last month.', '/ˈtɝːməneɪt/', 'Chúng tôi đã quyết định chấm dứt hợp đồng tập gym vào tháng trước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_1_5', 'ten_c1_40_1', 'invaluable', 'Your advice was invaluable when I bought my first bicycle.', 'Your advice was invaluable when I bought my first bicycle.', '/ɪnˈvæljuəbl/', 'Lời khuyên của bạn thực sự vô giá khi tôi mua chiếc xe đạp đầu tiên.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_1_6', 'ten_c1_40_1', 'cease', 'The bells finally ceased ringing just before midnight.', 'The bells finally ceased ringing just before midnight.', '/siːs/', 'Tiếng chuông cuối cùng cũng ngừng reo ngay trước thời điểm nửa đêm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_1_7', 'ten_c1_40_1', 'monotony', 'A short walk broke the monotony of my afternoon.', 'A short walk broke the monotony of my afternoon.', '/məˈnɑːtəni/', 'Một buổi đi dạo ngắn đã phá vỡ sự tẻ nhạt vào buổi chiều của tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_1_8', 'ten_c1_40_1', 'counsel', 'I sought my aunt''s counsel before accepting the job.', 'I sought my aunt''s counsel before accepting the job.', '/ˈkaʊnsəl/', 'Tôi đã xin lời khuyên của gì trước khi nhận công việc đó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_40_1_1', 'en-c1-40', 'ten_c1_40_1', 'listening', 'listening', 'My younger sister aspires to become a wildlife photographer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhà hàng nhỏ này phục vụ những món ăn thượng hạng với mức giá hợp lý.","Tôi ở lại muộn để xử lý xong đống email đang bị tồn đọng.","Em gái tôi có ước mơ trở thành một nhiếp ảnh gia động vật hoang dã.","Nhà máy bia cũ nay đã trở thành một bảo tàng địa phương nổi tiếng."]'::jsonb, 2, 'My younger sister aspires to become a wildlife photographer. → Em gái tôi có ước mơ trở thành một nhiếp ảnh gia động vật hoang dã.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_40_1_2', 'en-c1-40', 'ten_c1_40_1', 'listening', 'listening', 'After months of practice, she finally reaped the rewards.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Quản lý của tôi đã ca ngợi sự tiến bộ của tôi trong buổi đánh giá năng lực làm việc hôm nay.","Cần phải có ai đó khơi mào cuộc thảo luận về vấn đề tiếng ồn này.","Sau nhiều tháng luyện tập, cuối cùng cô ấy đã gặt hái được những thành quả xứng đáng.","Nữ hộ sinh gợi ý nên trao đổi với một y bác sĩ có chuyên môn."]'::jsonb, 2, 'After months of practice, she finally reaped the rewards. → Sau nhiều tháng luyện tập, cuối cùng cô ấy đã gặt hái được những thành quả xứng đáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_40_1_3', 'en-c1-40', 'ten_c1_40_1', 'listening', 'listening', 'Our application is still pending, so we cannot book flights.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hồ sơ của chúng tôi vẫn đang chờ xét duyệt nên chúng tôi chưa thể đặt vé máy bay.","Chiến thắng giải đấu là đỉnh cao trong sự nghiệp của cô ấy.","Sau nhiều tháng luyện tập, cuối cùng cô ấy đã gặt hái được những thành quả xứng đáng.","Quản lý của tôi đã ca ngợi sự tiến bộ của tôi trong buổi đánh giá năng lực làm việc hôm nay."]'::jsonb, 0, 'Our application is still pending, so we cannot book flights. → Hồ sơ của chúng tôi vẫn đang chờ xét duyệt nên chúng tôi chưa thể đặt vé máy bay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_40_2', 'en-c1-40', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_2_1', 'ten_c1_40_2', 'aspire', 'Many young people aspire to careers that offer both financial security and opportunities to contribute to society.', 'Many young people aspire to careers that offer both financial security and opportunities to contribute to society.', '/əˈspaɪr/', 'Nhiều người trẻ tuổi khát khao theo đuổi những nghề nghiệp vừa mang lại sự ổn định tài chính vừa có cơ hội đóng góp cho xã hội.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_2_2', 'ten_c1_40_2', 'reap', 'Countries that invest consistently in early education often reap long-term economic and social benefits.', 'Countries that invest consistently in early education often reap long-term economic and social benefits.', '/riːp/', 'Những quốc gia đầu tư liên tục vào giáo dục mầm non thường thu về những lợi ích kinh tế và xã hội lâu dài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_2_3', 'ten_c1_40_2', 'pending', 'Construction should remain suspended pending a thorough assessment of its potential impact on the surrounding environment.', 'Construction should remain suspended pending a thorough assessment of its potential impact on the surrounding environment.', '/ˈpendɪŋ/', 'Công trình xây dựng nên tiếp tục tạm dừng trong lúc chờ đánh giá kỹ lưỡng về tác động tiềm tàng của nó đối với môi trường xung quanh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_2_4', 'ten_c1_40_2', 'terminate', 'Employers should not terminate contracts without providing clear reasons and allowing workers sufficient time to respond.', 'Employers should not terminate contracts without providing clear reasons and allowing workers sufficient time to respond.', '/ˈtɝːməneɪt/', 'Người sử dụng lao động không nên đơn phương chấm dứt hợp đồng mà không đưa ra lý do rõ ràng và cho nhân viên đủ thời gian phản hồi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_2_5', 'ten_c1_40_2', 'invaluable', 'Practical work experience provides students with invaluable insights into the skills employers expect from new graduates.', 'Practical work experience provides students with invaluable insights into the skills employers expect from new graduates.', '/ɪnˈvæljuəbl/', 'Kinh nghiệm làm việc thực tế mang lại cho sinh viên những góc nhìn cực kỳ quý giá về các kỹ năng mà nhà tuyển dụng kỳ vọng ở các cử nhân mới ra trường.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_40_2_6', 'ten_c1_40_2', 'cease', 'Factories should cease discharging untreated wastewater into rivers to protect aquatic ecosystems and safeguard public health.', 'Factories should cease discharging untreated wastewater into rivers to protect aquatic ecosystems and safeguard public health.', '/siːs/', 'Các nhà máy nên chấm dứt việc xả nước thải chưa qua xử lý ra sông ngòi để bảo vệ hệ sinh thái thủy sinh và gìn giữ sức khỏe cộng đồng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_40_2_1', 'en-c1-40', 'ten_c1_40_2', 'listening', 'listening', 'Many young people aspire to careers that offer both financial security and opportunities to contribute to society.', NULL, 'Trong câu vừa nghe, từ “aspire” mang nghĩa nào sau đây?', '["vòng chí tuyến","thuộc về thẩm mỹ; mang tính mỹ học","bữa ăn chung mỗi người góp một món","khao khát; hoài bão; chí hướng"]'::jsonb, 3, '“aspire” (/əˈspaɪr/): khao khát; hoài bão; chí hướng. Câu đầy đủ: Many young people aspire to careers that offer both financial security and opportunities to contribute to society.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_40_2_2', 'en-c1-40', 'ten_c1_40_2', 'listening', 'listening', 'Countries that invest consistently in early education often reap long-term economic and social benefits.', NULL, 'Trong câu vừa nghe, từ “reap” mang nghĩa nào sau đây?', '["sự mâu thuẫn; sự bất nhất","gặt hái kết quả; nhận thành quả từ những hành động trước đó","học bổng nghiên cứu; quỹ hỗ trợ nghiên cứu; chức vụ nghiên cứu sinh","biết ơn; mang ơn"]'::jsonb, 1, '“reap” (/riːp/): gặt hái kết quả; nhận thành quả từ những hành động trước đó. Câu đầy đủ: Countries that invest consistently in early education often reap long-term economic and social benefits.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
