INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_1', 'en-c1-40', NULL, 'comprehensive_test', 'listening', 'aspire', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chủ nghĩa lý tưởng","sự trung thành; lòng trung thực","đột ngột; bất ngờ","khao khát; hoài bão; chí hướng"]'::jsonb, 3, 'aspire (/əˈspaɪr/) → khao khát; hoài bão; chí hướng', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_2', 'en-c1-40', NULL, 'comprehensive_test', 'listening', 'After months of practice, she finally reaped the rewards.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiếng chuông cuối cùng cũng ngừng reo ngay trước thời điểm nửa đêm.","Sau nhiều tháng luyện tập, cuối cùng cô ấy đã gặt hái được những thành quả xứng đáng.","Chúng tôi đã quyết định chấm dứt hợp đồng tập gym vào tháng trước.","Chiến thắng giải đấu là đỉnh cao trong sự nghiệp của cô ấy."]'::jsonb, 1, 'After months of practice, she finally reaped the rewards. → Sau nhiều tháng luyện tập, cuối cùng cô ấy đã gặt hái được những thành quả xứng đáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_3', 'en-c1-40', NULL, 'comprehensive_test', 'listening', 'pending', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trách mắng; chỉ trích","chưa quyết định; đang chờ giải quyết","sự bảo dưỡng; việc duy trì; chi phí bảo trì","làm cứng lại; trở nên cứng đờ, kém linh hoạt"]'::jsonb, 1, 'pending (/ˈpendɪŋ/) → chưa quyết định; đang chờ giải quyết; trong thời gian chờ đợi; cho đến khi', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_4', 'en-c1-40', NULL, 'comprehensive_test', 'listening', 'We decided to terminate our gym membership last month.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà hàng nhỏ này phục vụ những món ăn thượng hạng với mức giá hợp lý.","Chúng tôi đã quyết định chấm dứt hợp đồng tập gym vào tháng trước.","Cô ấy cất giữ những bức thư từ qua lại với người anh họ trong một chiếc ngăn kéo.","Chiến thắng giải đấu là đỉnh cao trong sự nghiệp của cô ấy."]'::jsonb, 1, 'We decided to terminate our gym membership last month. → Chúng tôi đã quyết định chấm dứt hợp đồng tập gym vào tháng trước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_5', 'en-c1-40', NULL, 'comprehensive_test', 'listening', 'invaluable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vô giá; cực kỳ quý giá; vô cùng hữu ích","làm cho xảy ra đột ngột; thúc đẩy","hợp đồng tương lai; giao dịch kỳ hạn","có thể qua lại được; tàu bè qua lại được"]'::jsonb, 0, 'invaluable (/ɪnˈvæljuəbl/) → vô giá; cực kỳ quý giá; vô cùng hữu ích', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_6', 'en-c1-40', NULL, 'comprehensive_test', 'listening', 'The bells finally ceased ringing just before midnight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà máy bia cũ nay đã trở thành một bảo tàng địa phương nổi tiếng.","Em gái tôi có ước mơ trở thành một nhiếp ảnh gia động vật hoang dã.","Tiếng chuông cuối cùng cũng ngừng reo ngay trước thời điểm nửa đêm.","Cô ấy nhận một vai trò hỗ trợ trong dự án này."]'::jsonb, 2, 'The bells finally ceased ringing just before midnight. → Tiếng chuông cuối cùng cũng ngừng reo ngay trước thời điểm nửa đêm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_7', 'en-c1-40', NULL, 'comprehensive_test', 'listening', 'monotony', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bóp méo; xuyên tạc","đã qua đời, thường dùng trong ngữ cảnh trang trọng hoặc pháp lý","sự đơn điệu; sự nhàm chán; sự tẻ nhạt","lủng lẳng; treo lơ lửng"]'::jsonb, 2, 'monotony (/məˈnɑːtəni/) → sự đơn điệu; sự nhàm chán; sự tẻ nhạt', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_8', 'en-c1-40', NULL, 'comprehensive_test', 'listening', 'I sought my aunt''s counsel before accepting the job.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Quản lý của tôi đã ca ngợi sự tiến bộ của tôi trong buổi đánh giá năng lực làm việc hôm nay.","Nhà hàng nhỏ này phục vụ những món ăn thượng hạng với mức giá hợp lý.","Nhà máy bia cũ nay đã trở thành một bảo tàng địa phương nổi tiếng.","Tôi đã xin lời khuyên của gì trước khi nhận công việc đó."]'::jsonb, 3, 'I sought my aunt''s counsel before accepting the job. → Tôi đã xin lời khuyên của gì trước khi nhận công việc đó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
