INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_18', 'en-c1-40', NULL, 'comprehensive_test', 'reading', NULL, 'Many young people aspire to careers that offer both financial security and opportunities to contribute to society.', 'Dựa vào câu trên, từ “aspire” có nghĩa phù hợp nhất là gì?', '["sự khinh miệt; sự coi thường","khao khát; hoài bão; chí hướng","vùng ven sông hồ; khu vực giáp nước","phụ; dự phòng; bổ trợ"]'::jsonb, 1, 'aspire: khao khát; hoài bão; chí hướng. Dịch cả câu: Nhiều người trẻ tuổi khát khao theo đuổi những nghề nghiệp vừa mang lại sự ổn định tài chính vừa có cơ hội đóng góp cho xã hội.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_19', 'en-c1-40', NULL, 'comprehensive_test', 'reading', NULL, 'Countries that invest consistently in early education often reap long-term economic and social benefits.', 'Dựa vào câu trên, từ “reap” có nghĩa phù hợp nhất là gì?', '["buồn bã; đau buồn; đầy vẻ đau thương","nữ thừa kế gia sản lớn","gặt hái kết quả; nhận thành quả từ những hành động trước đó","hội nghị chuyên đề; hội thảo"]'::jsonb, 2, 'reap: gặt hái kết quả; nhận thành quả từ những hành động trước đó; thu hoạch mùa màng. Dịch cả câu: Những quốc gia đầu tư liên tục vào giáo dục mầm non thường thu về những lợi ích kinh tế và xã hội lâu dài.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_20', 'en-c1-40', NULL, 'comprehensive_test', 'reading', NULL, 'Construction should remain suspended pending a thorough assessment of its potential impact on the surrounding environment.', 'Dựa vào câu trên, từ “pending” có nghĩa phù hợp nhất là gì?', '["sự thành lập; sự thiết lập","sự sai lệch; sự đi chệch","người giảng đạo; nhà truyền giáo","chưa quyết định; đang chờ giải quyết"]'::jsonb, 3, 'pending: chưa quyết định; đang chờ giải quyết; trong thời gian chờ đợi; cho đến khi. Dịch cả câu: Công trình xây dựng nên tiếp tục tạm dừng trong lúc chờ đánh giá kỹ lưỡng về tác động tiềm tàng của nó đối với môi trường xung quanh.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_21', 'en-c1-40', NULL, 'comprehensive_test', 'reading', NULL, 'Employers should not terminate contracts without providing clear reasons and allowing workers sufficient time to respond.', 'Dựa vào câu trên, từ “terminate” có nghĩa phù hợp nhất là gì?', '["chấm dứt; kết thúc","thợ thủ công; thợ lành nghề","vô cực; vô tận","dập tắt; làm tắt"]'::jsonb, 0, 'terminate: chấm dứt; kết thúc; chạy đến bến cuối (đối với phương tiện giao thông). Dịch cả câu: Người sử dụng lao động không nên đơn phương chấm dứt hợp đồng mà không đưa ra lý do rõ ràng và cho nhân viên đủ thời gian phản hồi.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_22', 'en-c1-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khởi đầu; phát động; khởi xướng”', '["methodology","asylum","sewer","initiate"]'::jsonb, 3, 'khởi đầu; phát động; khởi xướng → initiate (/ɪˈnɪʃieɪt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_23', 'en-c1-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hệ thống phân cấp; thứ bậc”', '["ruthless","symposium","hierarchy","trespass"]'::jsonb, 2, 'hệ thống phân cấp; thứ bậc → hierarchy (/ˈhaɪərɑːrki/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_40_24', 'en-c1-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “công việc tồn đọng; đơn hàng chờ xử lý”', '["backlog","provision","discretion","offset"]'::jsonb, 0, 'công việc tồn đọng; đơn hàng chờ xử lý → backlog (/ˈbæklɔːɡ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-41', 'en', 'Bài 41: Kinh tế & Tài chính (1) - CEFR C1', 'CEFR C1', 'C1 · Kinh tế', '26 từ vựng Tiếng Anh CEFR C1 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5041, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_redistribute', 'en-c1-41', 'redistribute', '/ˌriːdɪˈstrɪbjuːt/', 'C1', 'phân phối lại; bố trí lại', 'v.', 'distribute (v.), distribution (n.), redistribution (n.), redistributive (adj.)', 'Đồng nghĩa: reallocate', 'Nhấn mạnh việc thay đổi cách phân phối ban đầu, không nhất thiết mang ý nghĩa chia đều.', 'We redistributed the blankets so everyone had one.', NULL, 'Chúng tôi đã phân phối lại những chiếc chăn để ai cũng có một cái.', '{"wordId":"redistribute","ukIpa":"/ˌriːdɪˈstrɪbjuːt/","usIpa":"/ˌriːdɪˈstrɪbjuːt/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"To share out or spread something again in a different way.","vi":"phân phối lại; bố trí lại"}],"examples":[{"en":"We redistributed the blankets so everyone had one.","vi":"Chúng tôi đã phân phối lại những chiếc chăn để ai cũng có một cái.","audioKind":"ex"},{"en":"Progressive taxation can redistribute wealth and help governments fund essential services for disadvantaged communities.","vi":"Hệ thống thuế lũy tiến có thể phân phối lại tài sản và giúp chính phủ tài trợ cho các dịch vụ thiết yếu phục vụ cho các cộng đồng có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"redistribute wealth","vi":"phân phối lại tài sản"},{"en":"redistribute income","vi":"phân phối lại thu nhập"},{"en":"redistribute resources","vi":"phân phối lại nguồn lực"}],"wordFamily":["distribute (v.)","distribution (n.)","redistribution (n.)","redistributive (adj.)"],"synonyms":["reallocate"],"antonyms":[],"tipVi":"Nhấn mạnh việc thay đổi cách phân phối ban đầu, không nhất thiết mang ý nghĩa chia đều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_middleman', 'en-c1-41', 'middleman', '/ˈmɪdlmæn/', 'C1', 'người trung gian; thương lái; bên môi giới', 'n.', NULL, 'Đồng nghĩa: intermediary, go-between', 'Số nhiều là middlemen; có thể dùng từ trung lập là intermediary.', 'We bought directly from the farmer, avoiding the middleman.', NULL, 'Chúng tôi mua trực tiếp từ người nông dân, bỏ qua khâu trung gian.', '{"wordId":"middleman","ukIpa":"/ˈmɪdlmæn/","usIpa":"/ˈmɪdlmæn/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Someone arranging deals or buying goods to sell to others.","vi":"người trung gian; thương lái; bên môi giới"}],"examples":[{"en":"We bought directly from the farmer, avoiding the middleman.","vi":"Chúng tôi mua trực tiếp từ người nông dân, bỏ qua khâu trung gian.","audioKind":"ex"},{"en":"Online platforms allow small producers to reach consumers directly, reducing their dependence on a traditional middleman.","vi":"Các nền tảng trực tuyến cho phép các nhà sản xuất nhỏ tiếp cận trực tiếp với người tiêu dùng, làm giảm sự phụ thuộc vào các bên trung gian truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"cut out the middleman","vi":"bỏ qua khâu trung gian"},{"en":"act as a middleman","vi":"đóng vai trò là người trung gian"}],"wordFamily":[],"synonyms":["intermediary","go-between"],"antonyms":[],"tipVi":"Số nhiều là middlemen; có thể dùng từ trung lập là intermediary.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solvency', 'en-c1-41', 'solvency', '/ˈsɑːlvənsi/', 'C1', 'khả năng thanh toán nợ', 'n.', 'solvent (adj.), insolvent (adj.), insolvency (n.)', 'Trái nghĩa: insolvency', 'solvency chỉ khả năng trả nợ, không đồng nghĩa với khả năng sinh lời.', 'The accountant checked the firm''s solvency before approving the purchase.', NULL, 'Kế toán đã kiểm tra khả năng thanh toán của công ty trước khi phê duyệt giao dịch mua hàng.', '{"wordId":"solvency","ukIpa":"/ˈsɒlvənsi/","usIpa":"/ˈsɑːlvənsi/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"The ability to pay all the debts you owe.","vi":"khả năng thanh toán nợ"}],"examples":[{"en":"The accountant checked the firm''s solvency before approving the purchase.","vi":"Kế toán đã kiểm tra khả năng thanh toán của công ty trước khi phê duyệt giao dịch mua hàng.","audioKind":"ex"},{"en":"Stricter financial regulation can protect bank solvency and reduce the risk of a wider economic crisis.","vi":"Các quy định tài chính ngặt nghèo hơn có thể bảo vệ khả năng thanh toán của ngân hàng và giảm thiểu nguy cơ xảy ra một cuộc khủng hoảng kinh tế quy mô lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"maintain solvency","vi":"duy trì khả năng thanh toán"},{"en":"financial solvency","vi":"khả năng thanh toán tài chính"},{"en":"solvency requirements","vi":"yêu cầu về khả năng thanh toán"}],"wordFamily":["solvent (adj.)","insolvent (adj.)","insolvency (n.)"],"synonyms":[],"antonyms":["insolvency"],"tipVi":"solvency chỉ khả năng trả nợ, không đồng nghĩa với khả năng sinh lời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consignment', 'en-c1-41', 'consignment', '/kənˈsaɪnmənt/', 'C1', 'lô hàng; chuyến hàng; hàng gửi bán; hình thức ký gửi', 'n.', 'consign (v.), consignee (n.), consignor (n.)', 'Đồng nghĩa: shipment', 'on consignment nghĩa là ký gửi, chỉ thanh toán cho nhà cung cấp sau khi hàng đã được bán.', 'A consignment of fresh oranges arrived at the shop.', NULL, 'Một lô cam tươi vừa được chuyển đến cửa hàng.', '{"wordId":"consignment","ukIpa":"/kənˈsaɪnmənt/","usIpa":"/kənˈsaɪnmənt/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"A batch of goods sent to a person or place.","vi":"lô hàng; chuyến hàng"},{"pos":"n.","en":"An arrangement where sellers pay suppliers only after goods sell.","vi":"hàng gửi bán; hình thức ký gửi"}],"examples":[{"en":"A consignment of fresh oranges arrived at the shop.","vi":"Một lô cam tươi vừa được chuyển đến cửa hàng.","audioKind":"ex"},{"en":"Delays in inspecting a consignment of medical equipment can disrupt essential services in remote communities.","vi":"Việc chậm trễ trong khâu kiểm định một lô thiết bị y tế có thể làm gián đoạn các dịch vụ thiết yếu tại những cộng đồng vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"a consignment of goods","vi":"một lô hàng"},{"en":"receive a consignment","vi":"nhận một lô hàng"},{"en":"on consignment","vi":"theo hình thức ký gửi"}],"wordFamily":["consign (v.)","consignee (n.)","consignor (n.)"],"synonyms":["shipment"],"antonyms":[],"tipVi":"on consignment nghĩa là ký gửi, chỉ thanh toán cho nhà cung cấp sau khi hàng đã được bán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exclusivity', 'en-c1-41', 'exclusivity', '/ˌekskluːˈsɪvəti/', 'C1', 'quyền độc quyền; quyền phân phối hoặc sử dụng độc quyền; tính độc quyền; đặc quyền dành riêng cho một nhóm người', 'n.', 'exclusive (adj.), exclusively (adv.), exclude (v.), exclusion (n.)', NULL, 'Có thể dùng để chỉ quyền độc quyền trong kinh doanh hoặc tính chất độc quyền chỉ dành riêng cho một nhóm người.', 'The bakery secured exclusivity to sell bread at the festival.', NULL, 'Tiệm bánh đã giành được quyền độc quyền bán bánh mì tại lễ hội.', '{"wordId":"exclusivity","ukIpa":"/ˌekskluːˈsɪvəti/","usIpa":"/ˌekskluːˈsɪvəti/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"the right to provide or use something without competitors","vi":"quyền độc quyền; quyền phân phối hoặc sử dụng độc quyền"},{"pos":"n.","en":"the quality of being available only to a select group","vi":"tính độc quyền; đặc quyền dành riêng cho một nhóm người"}],"examples":[{"en":"The bakery secured exclusivity to sell bread at the festival.","vi":"Tiệm bánh đã giành được quyền độc quyền bán bánh mì tại lễ hội.","audioKind":"ex"},{"en":"Although exclusivity agreements can encourage investment, they may also limit competition and raise prices for consumers.","vi":"Mặc dù các thỏa thuận độc quyền có thể thúc đẩy đầu tư, chúng cũng có thể hạn chế cạnh tranh và làm tăng giá đối với người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"an exclusivity agreement","vi":"thỏa thuận độc quyền"},{"en":"grant exclusivity","vi":"cấp quyền độc quyền"},{"en":"a sense of exclusivity","vi":"cảm giác độc quyền; cảm giác được đặc quyền"}],"wordFamily":["exclusive (adj.)","exclusively (adv.)","exclude (v.)","exclusion (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng để chỉ quyền độc quyền trong kinh doanh hoặc tính chất độc quyền chỉ dành riêng cho một nhóm người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plummet', 'en-c1-41', 'plummet', '/ˈplʌmɪt/', 'C1', 'lao dốc; sụt giảm mạnh; rơi thẳng xuống; sụt nhanh từ trên cao', 'v.', NULL, 'Đồng nghĩa: plunge, tumble · Trái nghĩa: soar, rocket', 'Thường dùng làm nội động từ; to dùng cho mức đến, by dùng cho mức giảm.', 'Temperatures plummeted overnight, leaving ice on the garden pond.', NULL, 'Nhiệt độ đã giảm đột ngột trong đêm, khiến mặt hồ trong vườn bị đóng băng.', '{"wordId":"plummet","ukIpa":"/ˈplʌmɪt/","usIpa":"/ˈplʌmɪt/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"To decrease very quickly and sharply.","vi":"lao dốc; sụt giảm mạnh"},{"pos":"v.","en":"To fall suddenly and quickly from a high position.","vi":"rơi thẳng xuống; sụt nhanh từ trên cao"}],"examples":[{"en":"Temperatures plummeted overnight, leaving ice on the garden pond.","vi":"Nhiệt độ đã giảm đột ngột trong đêm, khiến mặt hồ trong vườn bị đóng băng.","audioKind":"ex"},{"en":"Demand for private cars could plummet if cities offered reliable, affordable public transport throughout the day.","vi":"Nhu cầu về xe hơi cá nhân có thể sụt giảm mạnh nếu các thành phố cung cấp phương tiện giao thông công cộng đáng tin cậy và giá cả phải chăng suốt cả ngày.","audioKind":"ex2"}],"collocations":[{"en":"prices plummet","vi":"giá cả lao dốc"},{"en":"temperatures plummet","vi":"nhiệt độ giảm sâu"},{"en":"plummet to a record low","vi":"rơi xuống mức thấp kỷ lục"}],"wordFamily":[],"synonyms":["plunge","tumble"],"antonyms":["soar","rocket"],"tipVi":"Thường dùng làm nội động từ; to dùng cho mức đến, by dùng cho mức giảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skyrocket', 'en-c1-41', 'skyrocket', '/ˈskaɪrɑːkɪt/', 'C1', 'tăng vọt; vọt lên cao', 'v.', NULL, 'Đồng nghĩa: soar, surge · Trái nghĩa: plummet, plunge', 'Thường dùng làm nội động từ, chủ ngữ thường là giá cả, chi phí hoặc nhu cầu.', 'Our heating bills skyrocketed during the unusually cold winter.', NULL, 'Hóa đơn tiền sưởi của chúng tôi đã tăng vọt trong mùa đông lạnh giá bất thường đó.', '{"wordId":"skyrocket","ukIpa":"/ˈskaɪrɒkɪt/","usIpa":"/ˈskaɪrɑːkɪt/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"To increase extremely quickly to a very high level.","vi":"tăng vọt; vọt lên cao"}],"examples":[{"en":"Our heating bills skyrocketed during the unusually cold winter.","vi":"Hóa đơn tiền sưởi của chúng tôi đã tăng vọt trong mùa đông lạnh giá bất thường đó.","audioKind":"ex"},{"en":"Housing costs can skyrocket when population growth outpaces construction, making affordable accommodation increasingly difficult to find.","vi":"Chi phí nhà ở có thể tăng vọt khi dân số tăng nhanh hơn tốc độ xây dựng, khiến việc tìm kiếm chỗ ở vừa túi tiền ngày càng khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"prices skyrocket","vi":"giá cả tăng vọt"},{"en":"demand skyrockets","vi":"nhu cầu tăng vọt"},{"en":"skyrocketing costs","vi":"chi phí tăng phi mã"}],"wordFamily":[],"synonyms":["soar","surge"],"antonyms":["plummet","plunge"],"tipVi":"Thường dùng làm nội động từ, chủ ngữ thường là giá cả, chi phí hoặc nhu cầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tonnage', 'en-c1-41', 'tonnage', '/ˈtʌnɪdʒ/', 'C1', 'trọng tải; tổng số tấn (tính bằng tấn); dung tích đăng ký (thước đo kích thước hoặc sức chở của tàu thuyền)', 'n.', 'ton (n.)', NULL, 'Dung tích đăng ký của tàu thuyền dùng để đo thể tích chứ không phải trọng lượng thực tế của tàu.', 'The driver checked the truck''s tonnage before crossing.', NULL, 'Tài xế đã kiểm tra trọng tải của chiếc xe tải trước khi qua cầu.', '{"wordId":"tonnage","ukIpa":"/ˈtʌnɪdʒ/","usIpa":"/ˈtʌnɪdʒ/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"The total weight of something expressed in tons.","vi":"trọng tải; tổng số tấn (tính bằng tấn)"},{"pos":"n.","en":"A measure of a ship''s size or carrying capacity.","vi":"dung tích đăng ký (thước đo kích thước hoặc sức chở của tàu thuyền)"}],"examples":[{"en":"The driver checked the truck''s tonnage before crossing.","vi":"Tài xế đã kiểm tra trọng tải của chiếc xe tải trước khi qua cầu.","audioKind":"ex"},{"en":"The total tonnage of waste sent to landfill has declined since the city introduced recycling programmes.","vi":"Tổng trọng lượng rác thải đưa đến các bãi chôn lấp đã giảm kể từ khi thành phố triển khai các chương trình tái chế.","audioKind":"ex2"}],"collocations":[{"en":"total tonnage","vi":"tổng trọng tải"},{"en":"cargo tonnage","vi":"trọng tải hàng hóa"},{"en":"gross tonnage","vi":"tổng dung tích đăng ký"},{"en":"shipping tonnage","vi":"tổng dung tích vận tải"}],"wordFamily":["ton (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dung tích đăng ký của tàu thuyền dùng để đo thể tích chứ không phải trọng lượng thực tế của tàu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_treble', 'en-c1-41', 'treble', '/ˈtrebəl/', 'C1', 'tăng gấp ba; gấp ba; giọng cao; âm cao', 'v.', 'trebling (n.)', 'Đồng nghĩa: triple', 'treble biểu thị việc tăng lên thành ba lần, tức là cộng thêm hai lần; rất phổ biến trong tiếng Anh-Anh.', 'Our heating bills treble when the weather turns cold.', NULL, 'Hóa đơn tiền sưởi của chúng tôi tăng gấp ba khi thời tiết trở lạnh.', '{"wordId":"treble","ukIpa":"/ˈtrebl/","usIpa":"/ˈtrebəl/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"To become three times as much, or cause this increase.","vi":"tăng gấp ba"},{"pos":"adj.","en":"Three times as much, or consisting of three parts.","vi":"gấp ba"},{"pos":"n.","en":"The high sounds in music or a sound system.","vi":"giọng cao; âm cao"}],"examples":[{"en":"Our heating bills treble when the weather turns cold.","vi":"Hóa đơn tiền sưởi của chúng tôi tăng gấp ba khi thời tiết trở lạnh.","audioKind":"ex"},{"en":"Investment in renewable energy could treble over the next decade if governments introduce stronger financial incentives.","vi":"Khoản đầu tư vào năng lượng tái tạo có thể tăng gấp ba trong thập kỷ tới nếu các chính phủ đưa ra các biện pháp khuyến khích tài chính mạnh mẽ hơn.","audioKind":"ex2"}],"collocations":[{"en":"treble in size","vi":"tăng gấp ba về kích thước"},{"en":"treble the cost","vi":"làm tăng chi phí lên gấp ba"},{"en":"treble clef","vi":"khóa Sol (trong âm nhạc)"},{"en":"treble and bass","vi":"âm cao và âm trầm"}],"wordFamily":["trebling (n.)"],"synonyms":["triple"],"antonyms":[],"tipVi":"treble biểu thị việc tăng lên thành ba lần, tức là cộng thêm hai lần; rất phổ biến trong tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subsidize', 'en-c1-41', 'subsidize', '/ˈsʌbsɪdaɪz/', 'C1', 'trợ cấp; tài trợ', 'v.', 'subsidy (n.), subsidization (n.)', 'Đồng nghĩa: support, fund', 'Anh-Anh cũng viết là subsidise; trợ cấp thường chỉ chi trả một phần chi phí.', 'My employer subsidizes lunch at the office cafeteria.', NULL, 'Công ty của tôi trợ cấp tiền ăn trưa tại căn tin văn phòng.', '{"wordId":"subsidize","ukIpa":"/ˈsʌbsɪdaɪz/","usIpa":"/ˈsʌbsɪdaɪz/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"Pay part of the cost of an activity or service","vi":"trợ cấp; tài trợ"}],"examples":[{"en":"My employer subsidizes lunch at the office cafeteria.","vi":"Công ty của tôi trợ cấp tiền ăn trưa tại căn tin văn phòng.","audioKind":"ex"},{"en":"Governments could subsidize public transport to make commuting more affordable and reduce urban traffic.","vi":"Chính phủ có thể trợ cấp cho giao thông công cộng để giúp chi phí đi lại dễ chi trả hơn và giảm ùn tắc giao thông đô thị.","audioKind":"ex2"}],"collocations":[{"en":"subsidize public transport","vi":"trợ cấp giao thông công cộng"},{"en":"heavily subsidized","vi":"được trợ cấp lớn"},{"en":"subsidize the cost of","vi":"trợ cấp chi phí của"}],"wordFamily":["subsidy (n.)","subsidization (n.)"],"synonyms":["support","fund"],"antonyms":[],"tipVi":"Anh-Anh cũng viết là subsidise; trợ cấp thường chỉ chi trả một phần chi phí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_devaluation', 'en-c1-41', 'devaluation', '/ˌdiːvæljuˈeɪʃn/', 'C1', 'việc chính thức hạ thấp giá trị của một đồng tiền so với các đồng tiền khác; sự làm giảm giá trị hoặc tầm quan trọng của một cái gì đó', 'n.', 'devalue (v.), value (n.), revaluation (n.)', 'Trái nghĩa: revaluation', 'Trong kinh tế học thường chỉ việc chính phủ hạ tỷ giá; sự suy giảm giá trị nói chung thường dùng depreciation.', 'After the devaluation, imported coffee became much more expensive.', NULL, 'Sau đợt phá giá tiền tệ, cà phê nhập khẩu trở nên đắt hơn rất nhiều.', '{"wordId":"devaluation","ukIpa":"/ˌdiːvæljuˈeɪʃn/","usIpa":"/ˌdiːvæljuˈeɪʃn/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"An official reduction in a currency''s value relative to other currencies.","vi":"việc chính thức hạ thấp giá trị của một đồng tiền so với các đồng tiền khác"},{"pos":"n.","en":"A reduction in the worth or importance given to something.","vi":"sự làm giảm giá trị hoặc tầm quan trọng của một cái gì đó"}],"examples":[{"en":"After the devaluation, imported coffee became much more expensive.","vi":"Sau đợt phá giá tiền tệ, cà phê nhập khẩu trở nên đắt hơn rất nhiều.","audioKind":"ex"},{"en":"Currency devaluation can make exports more competitive, but it also raises the cost of imported goods.","vi":"Việc phá giá đồng tiền có thể làm tăng sức cạnh tranh của hàng xuất khẩu, nhưng đồng thời cũng làm tăng chi phí hàng hóa nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"currency devaluation","vi":"sự phá giá tiền tệ"},{"en":"sharp devaluation","vi":"sự sụt giảm giá trị mạnh"},{"en":"devaluation of care work","vi":"sự coi nhẹ công việc chăm sóc"}],"wordFamily":["devalue (v.)","value (n.)","revaluation (n.)"],"synonyms":[],"antonyms":["revaluation"],"tipVi":"Trong kinh tế học thường chỉ việc chính phủ hạ tỷ giá; sự suy giảm giá trị nói chung thường dùng depreciation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drop-off', 'en-c1-41', 'drop-off', '/ˈdrɑːp ɔːf/', 'C1', 'sự sụt giảm; mức giảm; việc trả khách; dịch vụ thả hàng; đoạn dốc đứng; vực thẳm', 'n.', 'drop (v.)', 'Đồng nghĩa: decline, decrease · Trái nghĩa: increase', 'Danh từ được viết có dấu gạch ngang; cụm động từ tương ứng là drop off.', 'The café noticed a drop-off in customers after summer.', NULL, 'Quán cà phê nhận thấy lượng khách hàng giảm sút sau mùa hè.', '{"wordId":"drop-off","ukIpa":"/ˈdrɒp ɒf/","usIpa":"/ˈdrɑːp ɔːf/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"A decrease in an amount, level, or activity.","vi":"sự sụt giảm; mức giảm"},{"pos":"n.","en":"The act of leaving someone or something at a place.","vi":"việc trả khách; dịch vụ thả hàng"},{"pos":"n.","en":"A place where the ground suddenly becomes much lower.","vi":"đoạn dốc đứng; vực thẳm"}],"examples":[{"en":"The café noticed a drop-off in customers after summer.","vi":"Quán cà phê nhận thấy lượng khách hàng giảm sút sau mùa hè.","audioKind":"ex"},{"en":"A sharp drop-off in bus use may indicate that services no longer meet residents'' needs.","vi":"Sự sụt giảm mạnh trong việc sử dụng xe buýt có thể cho thấy dịch vụ không còn đáp ứng nhu cầu của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"a sharp drop-off","vi":"sự sụt giảm mạnh"},{"en":"a drop-off in demand","vi":"sự sụt giảm nhu cầu"},{"en":"drop-off point","vi":"điểm trả khách"}],"wordFamily":["drop (v.)"],"synonyms":["decline","decrease"],"antonyms":["increase"],"tipVi":"Danh từ được viết có dấu gạch ngang; cụm động từ tương ứng là drop off.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depreciation', 'en-c1-41', 'depreciation', '/dɪˌpriːʃiˈeɪʃən/', 'C1', 'sự khấu hao; sự sụt giảm giá trị; sự mất giá tiền tệ', 'n.', 'depreciate (v.), depreciable (adj.)', 'Trái nghĩa: appreciation', 'Dùng được cho cả khấu hao tài sản và mất giá tiền tệ; từ trái nghĩa là appreciation.', 'Depreciation means our car is worth less each year.', NULL, 'Sự khấu hao đồng nghĩa với việc chiếc xe của chúng tôi bị giảm giá trị qua mỗi năm.', '{"wordId":"depreciation","ukIpa":"/dɪˌpriːʃiˈeɪʃən/","usIpa":"/dɪˌpriːʃiˈeɪʃən/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"A reduction in an asset''s value over time.","vi":"sự khấu hao; sự sụt giảm giá trị"},{"pos":"n.","en":"A fall in a currency''s value relative to other currencies.","vi":"sự mất giá tiền tệ"}],"examples":[{"en":"Depreciation means our car is worth less each year.","vi":"Sự khấu hao đồng nghĩa với việc chiếc xe của chúng tôi bị giảm giá trị qua mỗi năm.","audioKind":"ex"},{"en":"Rapid currency depreciation can increase import costs, placing additional pressure on businesses that depend on foreign supplies.","vi":"Sự sụt giảm giá trị tiền tệ nhanh chóng có thể làm tăng chi phí nhập khẩu, tạo thêm áp lực cho các doanh nghiệp phụ thuộc vào nguồn cung ứng nước ngoài.","audioKind":"ex2"}],"collocations":[{"en":"annual depreciation","vi":"khấu hao hàng năm"},{"en":"currency depreciation","vi":"sự mất giá của đồng tiền"},{"en":"depreciation rate","vi":"tỷ lệ khấu hao"},{"en":"allow for depreciation","vi":"tính đến chi phí khấu hao"}],"wordFamily":["depreciate (v.)","depreciable (adj.)"],"synonyms":[],"antonyms":["appreciation"],"tipVi":"Dùng được cho cả khấu hao tài sản và mất giá tiền tệ; từ trái nghĩa là appreciation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_financier', 'en-c1-41', 'financier', '/ˌfɪnənˈsɪr/', 'C1', 'nhà tài chính; nhà đầu tư lớn', 'n.', 'finance (n.), finance (v.), financial (adj.), financially (adv.)', NULL, 'Chỉ người quản lý hoặc cung cấp số vốn đầu tư lớn, khác với nhân viên ngân hàng thông thường.', 'A local financier helped fund the new theatre.', NULL, 'Một nhà tài chính địa phương đã giúp quyên góp vốn cho nhà hát mới.', '{"wordId":"financier","ukIpa":"/faɪˈnænsiə/","usIpa":"/ˌfɪnənˈsɪr/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Someone who manages or provides large amounts of investment money","vi":"nhà tài chính; nhà đầu tư lớn"}],"examples":[{"en":"A local financier helped fund the new theatre.","vi":"Một nhà tài chính địa phương đã giúp quyên góp vốn cho nhà hát mới.","audioKind":"ex"},{"en":"Financiers can accelerate the transition to clean energy by directing investment towards innovative renewable technologies.","vi":"Các nhà tài chính có thể đẩy nhanh quá trình chuyển đổi sang năng lượng sạch bằng cách định hướng dòng vốn đầu tư vào các công nghệ năng lượng tái tạo đổi mới.","audioKind":"ex2"}],"collocations":[{"en":"international financier","vi":"nhà tài chính quốc tế"},{"en":"wealthy financier","vi":"nhà tài chính giàu có"},{"en":"leading financier","vi":"nhà tài chính hàng đầu"}],"wordFamily":["finance (n.)","finance (v.)","financial (adj.)","financially (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ người quản lý hoặc cung cấp số vốn đầu tư lớn, khác với nhân viên ngân hàng thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stagnation', 'en-c1-41', 'stagnation', '/stæɡˈneɪʃən/', 'C1', 'sự đình trệ; sự không phát triển; sự tù đọng (của nước hoặc không khí)', 'n.', 'stagnate (v.), stagnant (adj.)', 'Trái nghĩa: growth, progress', 'Thường là danh từ không đếm được, hay dùng trong bối cảnh kinh tế hoặc sự phát triển bị ngưng trệ.', 'After years of stagnation, our shop finally attracted new customers.', NULL, 'Sau nhiều năm kinh doanh ế ẩm, cửa hàng của chúng tôi cuối cùng cũng thu hút được khách hàng mới.', '{"wordId":"stagnation","ukIpa":"/stæɡˈneɪʃən/","usIpa":"/stæɡˈneɪʃən/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"a state in which growth, activity, or development stops","vi":"sự đình trệ; sự không phát triển"},{"pos":"n.","en":"the condition of water or air remaining still","vi":"sự tù đọng (của nước hoặc không khí)"}],"examples":[{"en":"After years of stagnation, our shop finally attracted new customers.","vi":"Sau nhiều năm kinh doanh ế ẩm, cửa hàng của chúng tôi cuối cùng cũng thu hút được khách hàng mới.","audioKind":"ex"},{"en":"Prolonged economic stagnation can reduce employment opportunities and discourage investment in essential public services.","vi":"Tình trạng đình trệ kinh tế kéo dài có thể làm giảm cơ hội việc làm và kìm hãm đầu tư vào các dịch vụ công thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"economic stagnation","vi":"sự đình trệ kinh tế"},{"en":"a period of stagnation","vi":"một thời kỳ trì trệ"},{"en":"prolonged stagnation","vi":"sự đình trệ kéo dài"}],"wordFamily":["stagnate (v.)","stagnant (adj.)"],"synonyms":[],"antonyms":["growth","progress"],"tipVi":"Thường là danh từ không đếm được, hay dùng trong bối cảnh kinh tế hoặc sự phát triển bị ngưng trệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expenditure', 'en-c1-41', 'expenditure', '/ɪkˈspendɪtʃər/', 'C1', 'khoản chi tiêu; chi phí; sự tiêu tốn; sự hao phí (thời gian, năng lượng)', 'n.', 'expend (v.)', 'Đồng nghĩa: spending, outlay', 'Thường là danh từ không đếm được; expenditure on dùng để chỉ khoản chi cho việc gì.', 'We track our monthly expenditure in a small notebook.', NULL, 'Chúng tôi ghi chép các khoản chi tiêu hàng tháng vào một cuốn sổ nhỏ.', '{"wordId":"expenditure","ukIpa":"/ɪkˈspendɪtʃə/","usIpa":"/ɪkˈspendɪtʃər/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"money spent on something","vi":"khoản chi tiêu; chi phí"},{"pos":"n.","en":"the use of time, energy, or effort","vi":"sự tiêu tốn; sự hao phí (thời gian, năng lượng)"}],"examples":[{"en":"We track our monthly expenditure in a small notebook.","vi":"Chúng tôi ghi chép các khoản chi tiêu hàng tháng vào một cuốn sổ nhỏ.","audioKind":"ex"},{"en":"Higher public expenditure on preventive healthcare could reduce the long-term cost of treating chronic diseases.","vi":"Việc tăng chi tiêu công cho y tế dự phòng có thể làm giảm chi phí điều trị các bệnh mãn tính trong dài hạn.","audioKind":"ex2"}],"collocations":[{"en":"public expenditure","vi":"chi tiêu công"},{"en":"capital expenditure","vi":"chi phí vốn"},{"en":"energy expenditure","vi":"sự tiêu hao năng lượng"}],"wordFamily":["expend (v.)"],"synonyms":["spending","outlay"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; expenditure on dùng để chỉ khoản chi cho việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_holding', 'en-c1-41', 'holding', '/ˈhoʊldɪŋ/', 'C1', 'tài sản nắm giữ; cổ phần; đất canh tác; nông trại', 'n.', 'hold (v.), holder (n.)', NULL, 'Tài sản sở hữu thường dùng ở số nhiều holdings; holding company có nghĩa là công ty mẹ (công ty cổ phần).', 'She sold her holding in the family business yesterday.', NULL, 'Cô ấy đã bán số cổ phần của mình trong công ty gia đình vào ngày hôm qua.', '{"wordId":"holding","ukIpa":"/ˈhəʊldɪŋ/","usIpa":"/ˈhoʊldɪŋ/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Property, shares, or other assets owned by someone.","vi":"tài sản nắm giữ; cổ phần"},{"pos":"n.","en":"An area of land owned or rented for farming.","vi":"đất canh tác; nông trại"}],"examples":[{"en":"She sold her holding in the family business yesterday.","vi":"Cô ấy đã bán số cổ phần của mình trong công ty gia đình vào ngày hôm qua.","audioKind":"ex"},{"en":"Large investment funds can influence corporate decisions through their substantial holdings in major companies across different sectors.","vi":"Các quỹ đầu tư lớn có thể tác động đến các quyết định doanh nghiệp thông qua lượng cổ phần lớn mà họ nắm giữ ở các công ty chủ chốt thuộc nhiều lĩnh vực khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a share holding","vi":"phần vốn cổ phần nắm giữ"},{"en":"property holdings","vi":"bất động sản sở hữu"},{"en":"an agricultural holding","vi":"khu đất nông nghiệp"}],"wordFamily":["hold (v.)","holder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tài sản sở hữu thường dùng ở số nhiều holdings; holding company có nghĩa là công ty mẹ (công ty cổ phần).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_capitalism', 'en-c1-41', 'capitalism', '/ˈkæpɪtəlɪzəm/', 'C1', 'chủ nghĩa tư bản', 'n.', 'capital (n.), capitalist (n.), capitalist (adj.)', NULL, 'Là danh từ không đếm được; từ capitalist có thể chỉ nhà tư bản hoặc dùng làm tính từ.', 'We discussed capitalism over coffee after our economics class.', NULL, 'Chúng tôi đã thảo luận về chủ nghĩa tư bản bên ly cà phê sau giờ học kinh tế.', '{"wordId":"capitalism","ukIpa":"/ˈkæpɪtəlɪzəm/","usIpa":"/ˈkæpɪtəlɪzəm/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"an economic system based on private ownership and profit","vi":"chủ nghĩa tư bản"}],"examples":[{"en":"We discussed capitalism over coffee after our economics class.","vi":"Chúng tôi đã thảo luận về chủ nghĩa tư bản bên ly cà phê sau giờ học kinh tế.","audioKind":"ex"},{"en":"Critics of capitalism argue that governments should regulate markets to limit inequality and protect vulnerable workers.","vi":"Những người chỉ trích chủ nghĩa tư bản lập luận rằng chính phủ nên quản lý thị trường để hạn chế bất bình đẳng và bảo vệ những người lao động dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"free-market capitalism","vi":"chủ nghĩa tư bản thị trường tự do"},{"en":"global capitalism","vi":"chủ nghĩa tư bản toàn cầu"},{"en":"the rise of capitalism","vi":"sự trỗi dậy của chủ nghĩa tư bản"}],"wordFamily":["capital (n.)","capitalist (n.)","capitalist (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; từ capitalist có thể chỉ nhà tư bản hoặc dùng làm tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thrift', 'en-c1-41', 'thrift', '/θrɪft/', 'C1', 'tính tiết kiệm; sự chi tiêu tằn tiện', 'n.', 'thrifty (adj.), thriftily (adv.), thriftiness (n.)', 'Đồng nghĩa: frugality · Trái nghĩa: extravagance', 'Thrift là danh từ; tính từ mang nghĩa "tiết kiệm" là thrifty.', 'Her thrift helped her save enough for a bicycle.', NULL, 'Đức tính tiết kiệm đã giúp cô ấy tích cóp đủ tiền mua một chiếc xe đạp.', '{"wordId":"thrift","ukIpa":"/θrɪft/","usIpa":"/θrɪft/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"careful use of money and resources to avoid waste","vi":"tính tiết kiệm; sự chi tiêu tằn tiện"}],"examples":[{"en":"Her thrift helped her save enough for a bicycle.","vi":"Đức tính tiết kiệm đã giúp cô ấy tích cóp đủ tiền mua một chiếc xe đạp.","audioKind":"ex"},{"en":"Teaching thrift in schools can help young people manage limited incomes and avoid unnecessary debt.","vi":"Việc giáo dục tính tiết kiệm ở trường học có thể giúp giới trẻ quản lý nguồn thu nhập hạn hẹp và tránh những khoản nợ không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"practise thrift","vi":"thực hành tiết kiệm"},{"en":"thrift shop","vi":"cửa hàng đồ cũ từ thiện"},{"en":"habits of thrift","vi":"thói quen tiết kiệm"}],"wordFamily":["thrifty (adj.)","thriftily (adv.)","thriftiness (n.)"],"synonyms":["frugality"],"antonyms":["extravagance"],"tipVi":"Thrift là danh từ; tính từ mang nghĩa \"tiết kiệm\" là thrifty.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fluctuate', 'en-c1-41', 'fluctuate', '/ˈflʌktʃueɪt/', 'C1', 'biến động; dao động', 'v.', 'fluctuation (n.)', 'Đồng nghĩa: vary', 'Thường là động từ nội động từ; dùng between khi nói về việc dao động giữa hai giá trị.', 'Vegetable prices fluctuate sharply at our local market.', NULL, 'Giá rau củ biến động mạnh ở chợ địa phương của chúng tôi.', '{"wordId":"fluctuate","ukIpa":"/ˈflʌktʃueɪt/","usIpa":"/ˈflʌktʃueɪt/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"Rise and fall irregularly in level, amount, or value.","vi":"biến động; dao động"}],"examples":[{"en":"Vegetable prices fluctuate sharply at our local market.","vi":"Giá rau củ biến động mạnh ở chợ địa phương của chúng tôi.","audioKind":"ex"},{"en":"Demand for electricity tends to fluctuate throughout the day, creating challenges for energy suppliers.","vi":"Nhu cầu điện năng có xu hướng dao động trong suốt cả ngày, gây ra nhiều thách thức cho các nhà cung cấp năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"fluctuate widely","vi":"biến động mạnh"},{"en":"fluctuate between","vi":"dao động trong khoảng"},{"en":"fluctuate with demand","vi":"biến động theo nhu cầu"}],"wordFamily":["fluctuation (n.)"],"synonyms":["vary"],"antonyms":[],"tipVi":"Thường là động từ nội động từ; dùng between khi nói về việc dao động giữa hai giá trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_astronomical', 'en-c1-41', 'astronomical', '/ˌæstrəˈnɑːmɪkəl/', 'C1', 'cực kỳ lớn; khổng lồ; mang tính chất thiên văn (giá cả, chi phí); thuộc về thiên văn học', 'adj.', 'astronomy (n.), astronomer (n.), astronomically (adv.)', NULL, 'Khi nói về chi phí thường diễn tả mức giá cao ngất ngưởng; ngoài ra cũng có nghĩa là thuộc về thiên văn học.', 'The hotel charged an astronomical price for one night.', NULL, 'Khách sạn đó tính mức giá cao đến ngỡ ngàng chỉ cho một đêm nghỉ.', '{"wordId":"astronomical","ukIpa":"/ˌæstrəˈnɒmɪkəl/","usIpa":"/ˌæstrəˈnɑːmɪkəl/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"Extremely large, especially when describing prices, costs, or amounts.","vi":"cực kỳ lớn; khổng lồ; mang tính chất thiên văn (giá cả, chi phí)"},{"pos":"adj.","en":"Relating to the scientific study of stars, planets, and space.","vi":"thuộc về thiên văn học"}],"examples":[{"en":"The hotel charged an astronomical price for one night.","vi":"Khách sạn đó tính mức giá cao đến ngỡ ngàng chỉ cho một đêm nghỉ.","audioKind":"ex"},{"en":"The astronomical cost of housing in major cities can prevent young adults from achieving financial independence.","vi":"Chi phí nhà ở đắt đỏ đến mức chóng mặt tại các thành phố lớn có thể cản trở những người trẻ tuổi đạt được sự độc lập về tài chính.","audioKind":"ex2"}],"collocations":[{"en":"astronomical costs","vi":"chi phí khổng lồ"},{"en":"astronomical sums","vi":"khoản tiền khổng lồ như con số thiên văn"},{"en":"astronomical observations","vi":"các quan sát thiên văn"}],"wordFamily":["astronomy (n.)","astronomer (n.)","astronomically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về chi phí thường diễn tả mức giá cao ngất ngưởng; ngoài ra cũng có nghĩa là thuộc về thiên văn học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transact', 'en-c1-41', 'transact', '/trænˈzækt/', 'C1', 'giao dịch; tiến hành kinh doanh; giải quyết công việc', 'v.', 'transaction (n.), transactional (adj.)', NULL, 'Từ trang trọng, thường dùng transact business để chỉ việc tiến hành hoạt động kinh doanh.', 'We transact most of our business through the bank.', NULL, 'Chúng tôi thực hiện phần lớn các giao dịch kinh doanh thông qua ngân hàng.', '{"wordId":"transact","ukIpa":"/trænˈzækt/","usIpa":"/trænˈzækt/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"to conduct business or carry out a business deal","vi":"giao dịch; tiến hành kinh doanh; giải quyết công việc"}],"examples":[{"en":"We transact most of our business through the bank.","vi":"Chúng tôi thực hiện phần lớn các giao dịch kinh doanh thông qua ngân hàng.","audioKind":"ex"},{"en":"Digital platforms allow small companies to transact business internationally without maintaining expensive offices in foreign markets.","vi":"Các nền tảng kỹ thuật số cho phép các doanh nghiệp nhỏ tiến hành giao dịch quốc tế mà không cần duy trì các văn phòng đắt đỏ tại thị trường nước ngoài.","audioKind":"ex2"}],"collocations":[{"en":"transact business","vi":"tiến hành kinh doanh"},{"en":"transact business with","vi":"giao dịch với"},{"en":"transact online","vi":"giao dịch trực tuyến"}],"wordFamily":["transaction (n.)","transactional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ trang trọng, thường dùng transact business để chỉ việc tiến hành hoạt động kinh doanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stimulus', 'en-c1-41', 'stimulus', '/ˈstɪmjələs/', 'C1', 'sự kích thích; nhân tố thúc đẩy; tác nhân kích thích', 'n.', 'stimulate (v.), stimulation (n.), stimulating (adj.)', 'Đồng nghĩa: incentive, impetus', 'Dạng số nhiều là stimuli; giới từ đi sau stimulus thường là to.', 'The prize provided a stimulus for her daily practice.', NULL, 'Giải thưởng đã tạo động lực cho cô ấy luyện tập mỗi ngày.', '{"wordId":"stimulus","ukIpa":"/ˈstɪmjələs/","usIpa":"/ˈstɪmjələs/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Something that encourages activity, growth, or change.","vi":"sự kích thích; nhân tố thúc đẩy"},{"pos":"n.","en":"Something that causes a physical or mental response.","vi":"tác nhân kích thích"}],"examples":[{"en":"The prize provided a stimulus for her daily practice.","vi":"Giải thưởng đã tạo động lực cho cô ấy luyện tập mỗi ngày.","audioKind":"ex"},{"en":"Investment in renewable energy can provide a powerful stimulus to economic growth while reducing emissions.","vi":"Đầu tư vào năng lượng tái tạo có thể tạo ra động lực mạnh mẽ cho tăng trưởng kinh tế đồng thời giảm lượng khí thải.","audioKind":"ex2"}],"collocations":[{"en":"a stimulus to growth","vi":"động lực thúc đẩy tăng trưởng"},{"en":"economic stimulus","vi":"gói kích thích kinh tế"},{"en":"respond to a stimulus","vi":"phản ứng lại một kích thích"}],"wordFamily":["stimulate (v.)","stimulation (n.)","stimulating (adj.)"],"synonyms":["incentive","impetus"],"antonyms":[],"tipVi":"Dạng số nhiều là stimuli; giới từ đi sau stimulus thường là to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outlay', 'en-c1-41', 'outlay', '/ˈaʊtleɪ/', 'C1', 'chi phí; khoản chi; vốn đầu tư ban đầu', 'n.', NULL, 'Đồng nghĩa: expenditure, expense', 'Thường chỉ chi phí khi bắt đầu một dự án, hay đi kèm với initial hoặc capital.', 'Our initial outlay included tools and a sturdy workbench.', NULL, 'Khoản đầu tư ban đầu của chúng tôi bao gồm các dụng cụ và một chiếc bàn làm việc chắc chắn.', '{"wordId":"outlay","ukIpa":"/ˈaʊtleɪ/","usIpa":"/ˈaʊtleɪ/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Money spent on a particular purpose, especially when starting something.","vi":"chi phí; khoản chi; vốn đầu tư ban đầu"}],"examples":[{"en":"Our initial outlay included tools and a sturdy workbench.","vi":"Khoản đầu tư ban đầu của chúng tôi bao gồm các dụng cụ và một chiếc bàn làm việc chắc chắn.","audioKind":"ex"},{"en":"Although solar panels require a substantial initial outlay, they can reduce household energy costs over time.","vi":"Mặc dù các tấm pin mặt trời đòi hỏi khoản chi phí ban đầu khá lớn, nhưng về lâu dài chúng có thể làm giảm hóa đơn tiền điện cho gia đình.","audioKind":"ex2"}],"collocations":[{"en":"initial outlay","vi":"chi phí ban đầu"},{"en":"capital outlay","vi":"chi phí vốn"},{"en":"a substantial outlay","vi":"khoản chi lớn"}],"wordFamily":[],"synonyms":["expenditure","expense"],"antonyms":[],"tipVi":"Thường chỉ chi phí khi bắt đầu một dự án, hay đi kèm với initial hoặc capital.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restock', 'en-c1-41', 'restock', '/ˌriːˈstɑːk/', 'C1', 'nhập thêm hàng; bổ sung hàng hóa', 'v.', 'stock (n.), stock (v.), restocking (n.)', 'Đồng nghĩa: replenish', 'Cấu trúc phổ biến là restock A with B, mang nghĩa dùng B để bổ sung hàng cho A.', 'We need to restock the fridge before our guests arrive.', NULL, 'Chúng ta cần phải mua thêm đồ bỏ vào tủ lạnh trước khi khách đến.', '{"wordId":"restock","ukIpa":"/ˌriːˈstɒk/","usIpa":"/ˌriːˈstɑːk/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"To replace goods that have been sold or used.","vi":"nhập thêm hàng; bổ sung hàng hóa"}],"examples":[{"en":"We need to restock the fridge before our guests arrive.","vi":"Chúng ta cần phải mua thêm đồ bỏ vào tủ lạnh trước khi khách đến.","audioKind":"ex"},{"en":"Retailers increasingly use digital systems to predict demand and restock shelves before products sell out.","vi":"Các nhà bán lẻ ngày càng sử dụng nhiều hệ thống kỹ thuật số để dự báo nhu cầu và bổ sung hàng lên kệ trước khi sản phẩm bị bán hết.","audioKind":"ex2"}],"collocations":[{"en":"restock shelves","vi":"bổ sung hàng lên kệ"},{"en":"restock the fridge","vi":"làm đầy lại tủ lạnh"},{"en":"restock with fresh supplies","vi":"bổ sung nguồn hàng tươi sống"}],"wordFamily":["stock (n.)","stock (v.)","restocking (n.)"],"synonyms":["replenish"],"antonyms":[],"tipVi":"Cấu trúc phổ biến là restock A with B, mang nghĩa dùng B để bổ sung hàng cho A.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tariff', 'en-c1-41', 'tariff', '/ˈterɪf/', 'C1', 'thuế quan; thuế xuất nhập khẩu hàng hóa; biểu giá; mức phí dịch vụ', 'n.', NULL, NULL, 'Thuế quan dùng tariff on goods; số nhiều tariffs thường chỉ nhiều loại thuế.', 'The new tariff made imported cheese much more expensive.', NULL, 'Mức thuế quan mới đã làm cho phô mai nhập khẩu đắt hơn rất nhiều.', '{"wordId":"tariff","ukIpa":"/ˈtærɪf/","usIpa":"/ˈterɪf/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"a tax charged on goods entering or leaving a country","vi":"thuế quan; thuế xuất nhập khẩu hàng hóa"},{"pos":"n.","en":"a set of charges for a service","vi":"biểu giá; mức phí dịch vụ"}],"examples":[{"en":"The new tariff made imported cheese much more expensive.","vi":"Mức thuế quan mới đã làm cho phô mai nhập khẩu đắt hơn rất nhiều.","audioKind":"ex"},{"en":"Although tariffs may protect domestic manufacturers, they can also raise consumer prices and provoke trade disputes.","vi":"Mặc dù thuế quan có thể bảo vệ các nhà sản xuất trong nước, chúng cũng có thể làm tăng giá tiêu dùng và gây ra tranh chấp thương mại.","audioKind":"ex2"}],"collocations":[{"en":"impose tariffs on","vi":"áp thuế lên"},{"en":"import tariff","vi":"thuế nhập khẩu"},{"en":"reduce tariffs","vi":"giảm thuế quan"},{"en":"electricity tariff","vi":"biểu giá điện"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thuế quan dùng tariff on goods; số nhiều tariffs thường chỉ nhiều loại thuế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_41_1', 'en-c1-41', 'Cách dùng “exclusivity” (n.) — quyền độc quyền; quyền phân phối hoặc sử dụng độc quyền', 'an exclusivity agreement  ·  grant exclusivity  ·  a sense of exclusivity', 'Có thể dùng để chỉ quyền độc quyền trong kinh doanh hoặc tính chất độc quyền chỉ dành riêng cho một nhóm người.', 'Họ từ (Word Family): exclusive (adj.), exclusively (adv.), exclude (v.), exclusion (n.)', '[{"hanzi":"The bakery secured exclusivity to sell bread at the festival.","pinyin":"","meaning":"Tiệm bánh đã giành được quyền độc quyền bán bánh mì tại lễ hội."},{"hanzi":"Although exclusivity agreements can encourage investment, they may also limit competition and raise prices for consumers.","pinyin":"","meaning":"Mặc dù các thỏa thuận độc quyền có thể thúc đẩy đầu tư, chúng cũng có thể hạn chế cạnh tranh và làm tăng giá đối với người tiêu dùng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_41_2', 'en-c1-41', 'Cách dùng “devaluation” (n.) — việc chính thức hạ thấp giá trị của một đồng tiền so với các đồng tiền khác', 'currency devaluation  ·  sharp devaluation  ·  devaluation of care work', 'Trong kinh tế học thường chỉ việc chính phủ hạ tỷ giá; sự suy giảm giá trị nói chung thường dùng depreciation.', 'Họ từ (Word Family): devalue (v.), value (n.), revaluation (n.) | Trái nghĩa: revaluation', '[{"hanzi":"After the devaluation, imported coffee became much more expensive.","pinyin":"","meaning":"Sau đợt phá giá tiền tệ, cà phê nhập khẩu trở nên đắt hơn rất nhiều."},{"hanzi":"Currency devaluation can make exports more competitive, but it also raises the cost of imported goods.","pinyin":"","meaning":"Việc phá giá đồng tiền có thể làm tăng sức cạnh tranh của hàng xuất khẩu, nhưng đồng thời cũng làm tăng chi phí hàng hóa nhập khẩu."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_41_3', 'en-c1-41', 'Cách dùng “astronomical” (adj.) — cực kỳ lớn; khổng lồ; mang tính chất thiên văn (giá cả, chi phí)', 'astronomical costs  ·  astronomical sums  ·  astronomical observations', 'Khi nói về chi phí thường diễn tả mức giá cao ngất ngưởng; ngoài ra cũng có nghĩa là thuộc về thiên văn học.', 'Họ từ (Word Family): astronomy (n.), astronomer (n.), astronomically (adv.)', '[{"hanzi":"The hotel charged an astronomical price for one night.","pinyin":"","meaning":"Khách sạn đó tính mức giá cao đến ngỡ ngàng chỉ cho một đêm nghỉ."},{"hanzi":"The astronomical cost of housing in major cities can prevent young adults from achieving financial independence.","pinyin":"","meaning":"Chi phí nhà ở đắt đỏ đến mức chóng mặt tại các thành phố lớn có thể cản trở những người trẻ tuổi đạt được sự độc lập về tài chính."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_41_4', 'en-c1-41', 'Cách dùng “holding” (n.) — tài sản nắm giữ; cổ phần', 'a share holding  ·  property holdings  ·  an agricultural holding', 'Tài sản sở hữu thường dùng ở số nhiều holdings; holding company có nghĩa là công ty mẹ (công ty cổ phần).', 'Họ từ (Word Family): hold (v.), holder (n.)', '[{"hanzi":"She sold her holding in the family business yesterday.","pinyin":"","meaning":"Cô ấy đã bán số cổ phần của mình trong công ty gia đình vào ngày hôm qua."},{"hanzi":"Large investment funds can influence corporate decisions through their substantial holdings in major companies across different sectors.","pinyin":"","meaning":"Các quỹ đầu tư lớn có thể tác động đến các quyết định doanh nghiệp thông qua lượng cổ phần lớn mà họ nắm giữ ở các công ty chủ chốt thuộc nhiều lĩnh vực khác nhau."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_41_1', 'en-c1-41', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_1_1', 'ten_c1_41_1', 'redistribute', 'We redistributed the blankets so everyone had one.', 'We redistributed the blankets so everyone had one.', '/ˌriːdɪˈstrɪbjuːt/', 'Chúng tôi đã phân phối lại những chiếc chăn để ai cũng có một cái.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_1_2', 'ten_c1_41_1', 'middleman', 'We bought directly from the farmer, avoiding the middleman.', 'We bought directly from the farmer, avoiding the middleman.', '/ˈmɪdlmæn/', 'Chúng tôi mua trực tiếp từ người nông dân, bỏ qua khâu trung gian.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_1_3', 'ten_c1_41_1', 'solvency', 'The accountant checked the firm''s solvency before approving the purchase.', 'The accountant checked the firm''s solvency before approving the purchase.', '/ˈsɑːlvənsi/', 'Kế toán đã kiểm tra khả năng thanh toán của công ty trước khi phê duyệt giao dịch mua hàng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_1_4', 'ten_c1_41_1', 'consignment', 'A consignment of fresh oranges arrived at the shop.', 'A consignment of fresh oranges arrived at the shop.', '/kənˈsaɪnmənt/', 'Một lô cam tươi vừa được chuyển đến cửa hàng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_1_5', 'ten_c1_41_1', 'exclusivity', 'The bakery secured exclusivity to sell bread at the festival.', 'The bakery secured exclusivity to sell bread at the festival.', '/ˌekskluːˈsɪvəti/', 'Tiệm bánh đã giành được quyền độc quyền bán bánh mì tại lễ hội.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_1_6', 'ten_c1_41_1', 'plummet', 'Temperatures plummeted overnight, leaving ice on the garden pond.', 'Temperatures plummeted overnight, leaving ice on the garden pond.', '/ˈplʌmɪt/', 'Nhiệt độ đã giảm đột ngột trong đêm, khiến mặt hồ trong vườn bị đóng băng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_1_7', 'ten_c1_41_1', 'skyrocket', 'Our heating bills skyrocketed during the unusually cold winter.', 'Our heating bills skyrocketed during the unusually cold winter.', '/ˈskaɪrɑːkɪt/', 'Hóa đơn tiền sưởi của chúng tôi đã tăng vọt trong mùa đông lạnh giá bất thường đó.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_1_8', 'ten_c1_41_1', 'tonnage', 'The driver checked the truck''s tonnage before crossing.', 'The driver checked the truck''s tonnage before crossing.', '/ˈtʌnɪdʒ/', 'Tài xế đã kiểm tra trọng tải của chiếc xe tải trước khi qua cầu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_41_1_1', 'en-c1-41', 'ten_c1_41_1', 'listening', 'listening', 'We redistributed the blankets so everyone had one.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã thảo luận về chủ nghĩa tư bản bên ly cà phê sau giờ học kinh tế.","Một lô cam tươi vừa được chuyển đến cửa hàng.","Chúng tôi mua trực tiếp từ người nông dân, bỏ qua khâu trung gian.","Chúng tôi đã phân phối lại những chiếc chăn để ai cũng có một cái."]'::jsonb, 3, 'We redistributed the blankets so everyone had one. → Chúng tôi đã phân phối lại những chiếc chăn để ai cũng có một cái.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_41_1_2', 'en-c1-41', 'ten_c1_41_1', 'listening', 'listening', 'We bought directly from the farmer, avoiding the middleman.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một nhà tài chính địa phương đã giúp quyên góp vốn cho nhà hát mới.","Chúng tôi mua trực tiếp từ người nông dân, bỏ qua khâu trung gian.","Giải thưởng đã tạo động lực cho cô ấy luyện tập mỗi ngày.","Tài xế đã kiểm tra trọng tải của chiếc xe tải trước khi qua cầu."]'::jsonb, 1, 'We bought directly from the farmer, avoiding the middleman. → Chúng tôi mua trực tiếp từ người nông dân, bỏ qua khâu trung gian.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_41_1_3', 'en-c1-41', 'ten_c1_41_1', 'listening', 'listening', 'The accountant checked the firm''s solvency before approving the purchase.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Kế toán đã kiểm tra khả năng thanh toán của công ty trước khi phê duyệt giao dịch mua hàng.","Chúng tôi mua trực tiếp từ người nông dân, bỏ qua khâu trung gian.","Chúng tôi đã phân phối lại những chiếc chăn để ai cũng có một cái.","Đức tính tiết kiệm đã giúp cô ấy tích cóp đủ tiền mua một chiếc xe đạp."]'::jsonb, 0, 'The accountant checked the firm''s solvency before approving the purchase. → Kế toán đã kiểm tra khả năng thanh toán của công ty trước khi phê duyệt giao dịch mua hàng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_41_2', 'en-c1-41', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_2_1', 'ten_c1_41_2', 'redistribute', 'Progressive taxation can redistribute wealth and help governments fund essential services for disadvantaged communities.', 'Progressive taxation can redistribute wealth and help governments fund essential services for disadvantaged communities.', '/ˌriːdɪˈstrɪbjuːt/', 'Hệ thống thuế lũy tiến có thể phân phối lại tài sản và giúp chính phủ tài trợ cho các dịch vụ thiết yếu phục vụ cho các cộng đồng có hoàn cảnh khó khăn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_2_2', 'ten_c1_41_2', 'middleman', 'Online platforms allow small producers to reach consumers directly, reducing their dependence on a traditional middleman.', 'Online platforms allow small producers to reach consumers directly, reducing their dependence on a traditional middleman.', '/ˈmɪdlmæn/', 'Các nền tảng trực tuyến cho phép các nhà sản xuất nhỏ tiếp cận trực tiếp với người tiêu dùng, làm giảm sự phụ thuộc vào các bên trung gian truyền thống.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_2_3', 'ten_c1_41_2', 'solvency', 'Stricter financial regulation can protect bank solvency and reduce the risk of a wider economic crisis.', 'Stricter financial regulation can protect bank solvency and reduce the risk of a wider economic crisis.', '/ˈsɑːlvənsi/', 'Các quy định tài chính ngặt nghèo hơn có thể bảo vệ khả năng thanh toán của ngân hàng và giảm thiểu nguy cơ xảy ra một cuộc khủng hoảng kinh tế quy mô lớn hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_2_4', 'ten_c1_41_2', 'consignment', 'Delays in inspecting a consignment of medical equipment can disrupt essential services in remote communities.', 'Delays in inspecting a consignment of medical equipment can disrupt essential services in remote communities.', '/kənˈsaɪnmənt/', 'Việc chậm trễ trong khâu kiểm định một lô thiết bị y tế có thể làm gián đoạn các dịch vụ thiết yếu tại những cộng đồng vùng sâu vùng xa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_2_5', 'ten_c1_41_2', 'exclusivity', 'Although exclusivity agreements can encourage investment, they may also limit competition and raise prices for consumers.', 'Although exclusivity agreements can encourage investment, they may also limit competition and raise prices for consumers.', '/ˌekskluːˈsɪvəti/', 'Mặc dù các thỏa thuận độc quyền có thể thúc đẩy đầu tư, chúng cũng có thể hạn chế cạnh tranh và làm tăng giá đối với người tiêu dùng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_41_2_6', 'ten_c1_41_2', 'plummet', 'Demand for private cars could plummet if cities offered reliable, affordable public transport throughout the day.', 'Demand for private cars could plummet if cities offered reliable, affordable public transport throughout the day.', '/ˈplʌmɪt/', 'Nhu cầu về xe hơi cá nhân có thể sụt giảm mạnh nếu các thành phố cung cấp phương tiện giao thông công cộng đáng tin cậy và giá cả phải chăng suốt cả ngày.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_41_2_1', 'en-c1-41', 'ten_c1_41_2', 'listening', 'listening', 'Progressive taxation can redistribute wealth and help governments fund essential services for disadvantaged communities.', NULL, 'Trong câu vừa nghe, từ “redistribute” mang nghĩa nào sau đây?', '["vật tương tự; vật đối ứng","phân phối lại; bố trí lại","thượng nghị sĩ","quân đoàn; binh chủng"]'::jsonb, 1, '“redistribute” (/ˌriːdɪˈstrɪbjuːt/): phân phối lại; bố trí lại. Câu đầy đủ: Progressive taxation can redistribute wealth and help governments fund essential services for disadvantaged communities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_41_2_2', 'en-c1-41', 'ten_c1_41_2', 'listening', 'listening', 'Online platforms allow small producers to reach consumers directly, reducing their dependence on a traditional middleman.', NULL, 'Trong câu vừa nghe, từ “middleman” mang nghĩa nào sau đây?', '["phức hợp; tổng hợp","sự xúi giục; động lực khuyến khích","phủ lên nhau; chồng chéo lên nhau; có điểm chung","người trung gian; thương lái; bên môi giới"]'::jsonb, 3, '“middleman” (/ˈmɪdlmæn/): người trung gian; thương lái; bên môi giới. Câu đầy đủ: Online platforms allow small producers to reach consumers directly, reducing their dependence on a traditional middleman.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
