INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_2', 'en-c1-41', NULL, 'comprehensive_test', 'listening', 'We bought directly from the farmer, avoiding the middleman.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi mua trực tiếp từ người nông dân, bỏ qua khâu trung gian.","Chúng tôi đã phân phối lại những chiếc chăn để ai cũng có một cái.","Công ty của tôi trợ cấp tiền ăn trưa tại căn tin văn phòng.","Khoản đầu tư ban đầu của chúng tôi bao gồm các dụng cụ và một chiếc bàn làm việc chắc chắn."]'::jsonb, 0, 'We bought directly from the farmer, avoiding the middleman. → Chúng tôi mua trực tiếp từ người nông dân, bỏ qua khâu trung gian.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_3', 'en-c1-41', NULL, 'comprehensive_test', 'listening', 'solvency', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khả năng thanh toán nợ","bằng máy móc; theo phương thức cơ khí","thuộc về tế bào (của sinh vật sống)","trách mắng; chỉ trích"]'::jsonb, 0, 'solvency (/ˈsɑːlvənsi/) → khả năng thanh toán nợ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_4', 'en-c1-41', NULL, 'comprehensive_test', 'listening', 'A consignment of fresh oranges arrived at the shop.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiệm bánh đã giành được quyền độc quyền bán bánh mì tại lễ hội.","Tài xế đã kiểm tra trọng tải của chiếc xe tải trước khi qua cầu.","Một lô cam tươi vừa được chuyển đến cửa hàng.","Công ty của tôi trợ cấp tiền ăn trưa tại căn tin văn phòng."]'::jsonb, 2, 'A consignment of fresh oranges arrived at the shop. → Một lô cam tươi vừa được chuyển đến cửa hàng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_5', 'en-c1-41', NULL, 'comprehensive_test', 'listening', 'exclusivity', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quyền độc quyền; quyền phân phối hoặc sử dụng độc quyền","hàn (nối các chi tiết kim loại bằng cách nung nóng cho đến khi chúng chảy dính vào nhau)","sự sơ suất; sự sai sót do sơ suất","huyết tương"]'::jsonb, 0, 'exclusivity (/ˌekskluːˈsɪvəti/) → quyền độc quyền; quyền phân phối hoặc sử dụng độc quyền; tính độc quyền; đặc quyền dành riêng cho một nhóm người', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_6', 'en-c1-41', NULL, 'comprehensive_test', 'listening', 'Temperatures plummeted overnight, leaving ice on the garden pond.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giải thưởng đã tạo động lực cho cô ấy luyện tập mỗi ngày.","Chúng ta cần phải mua thêm đồ bỏ vào tủ lạnh trước khi khách đến.","Nhiệt độ đã giảm đột ngột trong đêm, khiến mặt hồ trong vườn bị đóng băng.","Tài xế đã kiểm tra trọng tải của chiếc xe tải trước khi qua cầu."]'::jsonb, 2, 'Temperatures plummeted overnight, leaving ice on the garden pond. → Nhiệt độ đã giảm đột ngột trong đêm, khiến mặt hồ trong vườn bị đóng băng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_7', 'en-c1-41', NULL, 'comprehensive_test', 'listening', 'skyrocket', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tăng vọt; vọt lên cao","nén lại; ép chặt","tập hồ sơ năng lực; tập các tác phẩm tiêu biểu","biết ơn; mang ơn"]'::jsonb, 0, 'skyrocket (/ˈskaɪrɑːkɪt/) → tăng vọt; vọt lên cao', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_8', 'en-c1-41', NULL, 'comprehensive_test', 'listening', 'The driver checked the truck''s tonnage before crossing.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tài xế đã kiểm tra trọng tải của chiếc xe tải trước khi qua cầu.","Chúng tôi ghi chép các khoản chi tiêu hàng tháng vào một cuốn sổ nhỏ.","Giá rau củ biến động mạnh ở chợ địa phương của chúng tôi.","Khách sạn đó tính mức giá cao đến ngỡ ngàng chỉ cho một đêm nghỉ."]'::jsonb, 0, 'The driver checked the truck''s tonnage before crossing. → Tài xế đã kiểm tra trọng tải của chiếc xe tải trước khi qua cầu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_9', 'en-c1-41', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the right to provide or use something without competitors”?', '["tonnage","financier","exclusivity","treble"]'::jsonb, 2, 'exclusivity (/ˌekskluːˈsɪvəti/) → quyền độc quyền; quyền phân phối hoặc sử dụng độc quyền', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_10', 'en-c1-41', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To decrease very quickly and sharply.”?', '["plummet","skyrocket","capitalism","transact"]'::jsonb, 0, 'plummet (/ˈplʌmɪt/) → lao dốc; sụt giảm mạnh', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
