INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_18', 'en-c1-41', NULL, 'comprehensive_test', 'reading', NULL, 'Progressive taxation can redistribute wealth and help governments fund essential services for disadvantaged communities.', 'Dựa vào câu trên, từ “redistribute” có nghĩa phù hợp nhất là gì?', '["phân phối lại; bố trí lại","đổi hướng đột ngột, bẻ lái gấp","bằng máy móc; theo phương thức cơ khí","vượt qua; vượt ra ngoài giới hạn"]'::jsonb, 0, 'redistribute: phân phối lại; bố trí lại. Dịch cả câu: Hệ thống thuế lũy tiến có thể phân phối lại tài sản và giúp chính phủ tài trợ cho các dịch vụ thiết yếu phục vụ cho các cộng đồng có hoàn cảnh khó khăn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_19', 'en-c1-41', NULL, 'comprehensive_test', 'reading', NULL, 'Online platforms allow small producers to reach consumers directly, reducing their dependence on a traditional middleman.', 'Dựa vào câu trên, từ “middleman” có nghĩa phù hợp nhất là gì?', '["ám ảnh; làm vương vất trong tâm trí","thuộc bậc đại học; thuộc giáo dục đại học","gắn chặt vào; làm chìm sâu vào","người trung gian; thương lái; bên môi giới"]'::jsonb, 3, 'middleman: người trung gian; thương lái; bên môi giới. Dịch cả câu: Các nền tảng trực tuyến cho phép các nhà sản xuất nhỏ tiếp cận trực tiếp với người tiêu dùng, làm giảm sự phụ thuộc vào các bên trung gian truyền thống.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_20', 'en-c1-41', NULL, 'comprehensive_test', 'reading', NULL, 'Stricter financial regulation can protect bank solvency and reduce the risk of a wider economic crisis.', 'Dựa vào câu trên, từ “solvency” có nghĩa phù hợp nhất là gì?', '["tinh thần thể thao; tác phong thể thao","khả năng thanh toán nợ","thợ thủ công; thợ lành nghề","tiếng la ó om sòm; tiếng ồn ào; đòi hỏi bức xúc của công chúng"]'::jsonb, 1, 'solvency: khả năng thanh toán nợ. Dịch cả câu: Các quy định tài chính ngặt nghèo hơn có thể bảo vệ khả năng thanh toán của ngân hàng và giảm thiểu nguy cơ xảy ra một cuộc khủng hoảng kinh tế quy mô lớn hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_21', 'en-c1-41', NULL, 'comprehensive_test', 'reading', NULL, 'Delays in inspecting a consignment of medical equipment can disrupt essential services in remote communities.', 'Dựa vào câu trên, từ “consignment” có nghĩa phù hợp nhất là gì?', '["lô hàng; chuyến hàng","khả thi; thực hiện được","chậm hơn; phát triển chậm hơn","cấy ghép nội tạng; bứng cây"]'::jsonb, 0, 'consignment: lô hàng; chuyến hàng; hàng gửi bán; hình thức ký gửi. Dịch cả câu: Việc chậm trễ trong khâu kiểm định một lô thiết bị y tế có thể làm gián đoạn các dịch vụ thiết yếu tại những cộng đồng vùng sâu vùng xa.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_22', 'en-c1-41', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chi phí; khoản chi; vốn đầu tư ban đầu”', '["dwelling","uncap","contradict","outlay"]'::jsonb, 3, 'chi phí; khoản chi; vốn đầu tư ban đầu → outlay (/ˈaʊtleɪ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_23', 'en-c1-41', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhập thêm hàng; bổ sung hàng hóa”', '["restock","hawk","reproach","cordial"]'::jsonb, 0, 'nhập thêm hàng; bổ sung hàng hóa → restock (/ˌriːˈstɑːk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_41_24', 'en-c1-41', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuế quan; thuế xuất nhập khẩu hàng hóa”', '["tariff","nostril","ascent","procure"]'::jsonb, 0, 'thuế quan; thuế xuất nhập khẩu hàng hóa → tariff (/ˈterɪf/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-42', 'en', 'Bài 42: Kinh tế & Tài chính (2) - CEFR C1', 'CEFR C1', 'C1 · Kinh tế', '25 từ vựng Tiếng Anh CEFR C1 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5042, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cripple', 'en-c1-42', 'cripple', '/ˈkrɪpəl/', 'C1', 'làm tê liệt; tàn phá năng lực hoạt động; làm thương tật nghiêm trọng; làm tàn phế', 'v.', 'crippling (adj.)', 'Đồng nghĩa: disable, paralyse', 'Dùng làm danh từ chỉ người có thể mang tính xúc phạm; động từ thường chỉ kinh tế hoặc hệ thống bị trọng thương.', 'The power cut crippled our heating system all evening.', NULL, 'Việc cắt điện đã làm tê liệt hệ thống sưởi của chúng tôi suốt cả buổi tối.', '{"wordId":"cripple","ukIpa":"/ˈkrɪpəl/","usIpa":"/ˈkrɪpəl/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"To severely damage something''s ability to function","vi":"làm tê liệt; tàn phá năng lực hoạt động"},{"pos":"v.","en":"To cause a serious injury that limits someone''s movement","vi":"làm thương tật nghiêm trọng; làm tàn phế"}],"examples":[{"en":"The power cut crippled our heating system all evening.","vi":"Việc cắt điện đã làm tê liệt hệ thống sưởi của chúng tôi suốt cả buổi tối.","audioKind":"ex"},{"en":"A prolonged drought can cripple agricultural production, reducing rural incomes and increasing food prices across the country.","vi":"Hạn hán kéo dài có thể giáng đòn nặng nề vào sản xuất nông nghiệp, làm giảm thu nhập ở nông thôn và đẩy giá thực phẩm tăng cao trên toàn quốc.","audioKind":"ex2"}],"collocations":[{"en":"cripple the economy","vi":"làm tê liệt nền kinh tế"},{"en":"cripple production","vi":"làm ngưng trệ sản xuất"},{"en":"crippling costs","vi":"chi phí đắt đỏ đến mức gánh nặng"}],"wordFamily":["crippling (adj.)"],"synonyms":["disable","paralyse"],"antonyms":[],"tipVi":"Dùng làm danh từ chỉ người có thể mang tính xúc phạm; động từ thường chỉ kinh tế hoặc hệ thống bị trọng thương.","noteVi":"Dùng làm danh từ chỉ người khuyết tật có thể gây xúc phạm, nên tránh sử dụng.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accrued', 'en-c1-42', 'accrued', '/əˈkruːd/', 'C1', 'được tích lũy theo thời gian (đặc biệt là về mặt tài chính); dồn tích', 'adj.', 'accrue (v.), accrual (n.)', 'Đồng nghĩa: accumulated', 'Đây cũng là phân từ quá khứ của động từ accrue; ''accrued'' mang nghĩa dồn tích chứ chưa chắc đã được thanh toán.', 'My bank statement shows the accrued interest on my savings.', NULL, 'Sao kê ngân hàng của tôi hiển thị khoản tiền lãi đã tích lũy trong tài khoản tiết kiệm.', '{"wordId":"accrued","ukIpa":"/əˈkruːd/","usIpa":"/əˈkruːd/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"built up over time, especially financially, but not necessarily paid","vi":"được tích lũy theo thời gian (đặc biệt là về mặt tài chính); dồn tích"}],"examples":[{"en":"My bank statement shows the accrued interest on my savings.","vi":"Sao kê ngân hàng của tôi hiển thị khoản tiền lãi đã tích lũy trong tài khoản tiết kiệm.","audioKind":"ex"},{"en":"Companies must account for accrued expenses to provide an accurate picture of their financial position at year end.","vi":"Các công ty phải hạch toán các khoản chi phí dồn tích để phản ánh chính xác tình hình tài chính của họ vào cuối năm.","audioKind":"ex2"}],"collocations":[{"en":"accrued interest","vi":"lãi dồn tích"},{"en":"accrued expenses","vi":"chi phí phải trả"},{"en":"accrued income","vi":"thu nhập tích lũy"},{"en":"accrued benefits","vi":"lợi ích tích lũy"}],"wordFamily":["accrue (v.)","accrual (n.)"],"synonyms":["accumulated"],"antonyms":[],"tipVi":"Đây cũng là phân từ quá khứ của động từ accrue; ''accrued'' mang nghĩa dồn tích chứ chưa chắc đã được thanh toán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_volatile', 'en-c1-42', 'volatile', '/ˈvɑːlətəl/', 'C1', 'thay đổi thất thường; dễ biến động; dễ nổi giận; dễ thay đổi cảm xúc; dễ bay hơi', 'adj.', 'volatility (n.)', 'Đồng nghĩa: unstable, unpredictable · Trái nghĩa: stable', 'Có thể mô tả thị trường biến động, chỉ cảm xúc dễ thay đổi hoặc chất dễ bay hơi.', 'Fuel prices have been unusually volatile this month.', NULL, 'Giá nhiên liệu tháng này biến động bất thường.', '{"wordId":"volatile","ukIpa":"/ˈvɒlətaɪl/","usIpa":"/ˈvɑːlətəl/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"Likely to change suddenly and unpredictably.","vi":"thay đổi thất thường; dễ biến động"},{"pos":"adj.","en":"Having emotions that change suddenly, especially towards anger.","vi":"dễ nổi giận; dễ thay đổi cảm xúc"},{"pos":"adj.","en":"Changing easily from a liquid into a gas.","vi":"dễ bay hơi"}],"examples":[{"en":"Fuel prices have been unusually volatile this month.","vi":"Giá nhiên liệu tháng này biến động bất thường.","audioKind":"ex"},{"en":"Volatile food prices make it difficult for low-income households to plan their spending and maintain a balanced diet.","vi":"Giá thực phẩm biến động thất thường khiến các hộ gia đình thu nhập thấp khó lập kế hoạch chi tiêu và duy trì chế độ ăn uống cân bằng.","audioKind":"ex2"}],"collocations":[{"en":"volatile market","vi":"thị trường biến động mạnh"},{"en":"volatile prices","vi":"giá cả bấp bênh"},{"en":"volatile temper","vi":"tính tình dễ nổi nóng"},{"en":"volatile substance","vi":"chất dễ bay hơi"}],"wordFamily":["volatility (n.)"],"synonyms":["unstable","unpredictable"],"antonyms":["stable"],"tipVi":"Có thể mô tả thị trường biến động, chỉ cảm xúc dễ thay đổi hoặc chất dễ bay hơi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depreciate', 'en-c1-42', 'depreciate', '/dɪˈpriːʃieɪt/', 'C1', 'mất giá; giảm giá trị; khấu hao tài sản', 'v.', 'depreciation (n.)', 'Đồng nghĩa: devalue · Trái nghĩa: appreciate', 'Thường chỉ tiền tệ hoặc tài sản bị giảm giá trị; từ trái nghĩa là appreciate có thể chỉ sự tăng giá.', 'New cars often depreciate quickly during their first year.', NULL, 'Ô tô mới thường mất giá nhanh chóng trong năm đầu tiên sử dụng.', '{"wordId":"depreciate","ukIpa":"/dɪˈpriːʃieɪt/","usIpa":"/dɪˈpriːʃieɪt/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"To lose value, or reduce an asset''s recorded value.","vi":"mất giá; giảm giá trị; khấu hao tài sản"}],"examples":[{"en":"New cars often depreciate quickly during their first year.","vi":"Ô tô mới thường mất giá nhanh chóng trong năm đầu tiên sử dụng.","audioKind":"ex"},{"en":"When a country''s currency depreciates, imported goods become more expensive, potentially increasing the cost of living.","vi":"Khi đồng tiền của một quốc gia mất giá, hàng hóa nhập khẩu trở nên đắt đỏ hơn, có khả năng làm tăng chi phí sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"depreciate in value","vi":"giảm sút giá trị"},{"en":"depreciate rapidly","vi":"mất giá nhanh chóng"},{"en":"depreciate assets","vi":"khấu hao tài sản"}],"wordFamily":["depreciation (n.)"],"synonyms":["devalue"],"antonyms":["appreciate"],"tipVi":"Thường chỉ tiền tệ hoặc tài sản bị giảm giá trị; từ trái nghĩa là appreciate có thể chỉ sự tăng giá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_globalize', 'en-c1-42', 'globalize', '/ˈɡloʊbəlaɪz/', 'C1', 'toản cầu hóa; làm cho mang tính toàn cầu', 'v.', 'global (adj.), globally (adv.), globalization (n.)', NULL, 'Anh–Anh cũng thường viết là globalise.', 'Online shops help small businesses globalize without opening stores abroad.', NULL, 'Cửa hàng trực tuyến giúp các doanh nghiệp nhỏ toàn cầu hóa mà không cần mở cửa hàng ở nước ngoài.', '{"wordId":"globalize","ukIpa":"/ˈɡləʊbəlaɪz/","usIpa":"/ˈɡloʊbəlaɪz/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"to make something operate or spread across the world","vi":"toản cầu hóa; làm cho mang tính toàn cầu"}],"examples":[{"en":"Online shops help small businesses globalize without opening stores abroad.","vi":"Cửa hàng trực tuyến giúp các doanh nghiệp nhỏ toàn cầu hóa mà không cần mở cửa hàng ở nước ngoài.","audioKind":"ex"},{"en":"As companies globalize their operations, governments must cooperate to protect workers and maintain fair competition.","vi":"Khi các doanh nghiệp toàn cầu hóa hoạt động của mình, chính phủ các nước phải hợp tác để bảo vệ người lao động và duy trì cạnh tranh công bằng.","audioKind":"ex2"}],"collocations":[{"en":"globalize operations","vi":"toàn cầu hóa hoạt động"},{"en":"globalize production","vi":"toàn cầu hóa sản xuất"},{"en":"globalize markets","vi":"toàn cầu hóa thị trường"}],"wordFamily":["global (adj.)","globally (adv.)","globalization (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Anh–Anh cũng thường viết là globalise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prosperity', 'en-c1-42', 'prosperity', '/prɑːˈsperəti/', 'C1', 'sự thịnh vượng; sự phát đạt, sự giàu có', 'n.', 'prosper (v.), prosperous (adj.)', 'Đồng nghĩa: affluence, wealth · Trái nghĩa: poverty', 'Không đếm được danh từ; tính từ dùng prosperous.', 'The busy harbour brought prosperity to our town.', NULL, 'Cảng biển tấp nập đã mang lại sự thịnh vượng cho thị trấn của chúng tôi.', '{"wordId":"prosperity","ukIpa":"/prɒˈsperəti/","usIpa":"/prɑːˈsperəti/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"The state of being economically successful and financially secure.","vi":"sự thịnh vượng; sự phát đạt, sự giàu có"}],"examples":[{"en":"The busy harbour brought prosperity to our town.","vi":"Cảng biển tấp nập đã mang lại sự thịnh vượng cho thị trấn của chúng tôi.","audioKind":"ex"},{"en":"Investment in education can support long-term prosperity by giving workers the skills needed in a changing economy.","vi":"Đầu tư vào giáo dục có thể hỗ trợ sự thịnh vượng lâu dài bằng cách cung cấp cho người lao động các kỹ năng cần thiết trong một nền kinh tế đang thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"economic prosperity","vi":"sự thịnh vượng kinh tế"},{"en":"shared prosperity","vi":"sự thịnh vượng chung"},{"en":"long-term prosperity","vi":"sự thịnh vượng lâu dài"}],"wordFamily":["prosper (v.)","prosperous (adj.)"],"synonyms":["affluence","wealth"],"antonyms":["poverty"],"tipVi":"Không đếm được danh từ; tính từ dùng prosperous.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exorbitant', 'en-c1-42', 'exorbitant', '/ɪɡˈzɔːrbɪtənt/', 'C1', 'cắt cổ, đắt cắt cổ; quá mức, cao vô lý', 'adj.', 'exorbitantly (adv.)', 'Đồng nghĩa: excessive, extortionate · Trái nghĩa: reasonable', 'Mang sắc thái mạnh hơn expensive, ngụ ý mức giá bất hợp lý và quá cao.', 'The hotel charged an exorbitant amount for breakfast.', NULL, 'Khách sạn đó tính giá bữa sáng cao đến mức vô lý.', '{"wordId":"exorbitant","ukIpa":"/ɪɡˈzɔːbɪtənt/","usIpa":"/ɪɡˈzɔːrbɪtənt/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"Much higher in price or cost than is reasonable.","vi":"cắt cổ, đắt cắt cổ; quá mức, cao vô lý"}],"examples":[{"en":"The hotel charged an exorbitant amount for breakfast.","vi":"Khách sạn đó tính giá bữa sáng cao đến mức vô lý.","audioKind":"ex"},{"en":"Exorbitant rents in major cities can force essential workers to live far from their places of employment.","vi":"Giá thuê nhà đắt cắt cổ ở các thành phố lớn có thể buộc những người lao động thiết yếu phải sống xa nơi làm việc của họ.","audioKind":"ex2"}],"collocations":[{"en":"exorbitant prices","vi":"giá cả đắt cắt cổ"},{"en":"exorbitant fees","vi":"chi phí quá mức"},{"en":"exorbitant rents","vi":"tiền thuê nhà đắt đỏ"}],"wordFamily":["exorbitantly (adv.)"],"synonyms":["excessive","extortionate"],"antonyms":["reasonable"],"tipVi":"Mang sắc thái mạnh hơn expensive, ngụ ý mức giá bất hợp lý và quá cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extravagant', 'en-c1-42', 'extravagant', '/ɪkˈstrævəɡənt/', 'C1', 'xa hoa; phung phí; đắt đỏ; quá mức; quá đà; phóng đại', 'adj.', 'extravagance (n.), extravagantly (adv.)', 'Đồng nghĩa: lavish, excessive · Trái nghĩa: frugal, restrained', 'Vừa có thể chỉ việc tiêu tiền vô độ, vừa có thể chỉ lời lẽ hoặc yêu cầu quá mức.', 'Buying another silk coat seemed extravagant on her budget.', NULL, 'Việc mua thêm một chiếc áo khoác lụa có vẻ vượt quá ngân sách và quá xa hoa đối với cô ấy.', '{"wordId":"extravagant","ukIpa":"/ɪkˈstrævəɡənt/","usIpa":"/ɪkˈstrævəɡənt/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"Spending or costing much more money than necessary.","vi":"xa hoa; phung phí; đắt đỏ"},{"pos":"adj.","en":"Going beyond what is reasonable or believable.","vi":"quá mức; quá đà; phóng đại"}],"examples":[{"en":"Buying another silk coat seemed extravagant on her budget.","vi":"Việc mua thêm một chiếc áo khoác lụa có vẻ vượt quá ngân sách và quá xa hoa đối với cô ấy.","audioKind":"ex"},{"en":"Extravagant spending on international events can divert public funds from essential healthcare and education services.","vi":"Việc chi tiêu hoang phí cho các sự kiện quốc tế có thể làm chệch hướng nguồn quỹ công vốn dành cho các dịch vụ chăm sóc sức khỏe và giáo dục thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"extravagant spending","vi":"chi tiêu hoang phí"},{"en":"extravagant lifestyle","vi":"lối sống xa hoa"},{"en":"extravagant claims","vi":"tuyên bố phóng đại"}],"wordFamily":["extravagance (n.)","extravagantly (adv.)"],"synonyms":["lavish","excessive"],"antonyms":["frugal","restrained"],"tipVi":"Vừa có thể chỉ việc tiêu tiền vô độ, vừa có thể chỉ lời lẽ hoặc yêu cầu quá mức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_protectionism', 'en-c1-42', 'protectionism', '/prəˈtekʃənɪzəm/', 'C1', 'chủ nghĩa bảo hộ mậu dịch; chính sách bảo hộ', 'n.', 'protectionist (adj.), protection (n.), protect (v.)', 'Trái nghĩa: free trade', 'Đây là danh từ không đếm được, dùng chuyên biệt cho chính sách kinh tế/thương mại chứ không chỉ sự bảo vệ chung chung.', 'We discussed protectionism after imported shoes became more expensive.', NULL, 'Chúng tôi đã thảo luận về chủ nghĩa bảo hộ thương mại sau khi giá giày nhập khẩu trở nên đắt đỏ hơn.', '{"wordId":"protectionism","ukIpa":"/prəˈtekʃənɪzəm/","usIpa":"/prəˈtekʃənɪzəm/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Government policies restricting imports to protect domestic businesses from foreign competition.","vi":"chủ nghĩa bảo hộ mậu dịch; chính sách bảo hộ"}],"examples":[{"en":"We discussed protectionism after imported shoes became more expensive.","vi":"Chúng tôi đã thảo luận về chủ nghĩa bảo hộ thương mại sau khi giá giày nhập khẩu trở nên đắt đỏ hơn.","audioKind":"ex"},{"en":"Although protectionism may support domestic industries temporarily, it can raise consumer prices and provoke disputes with trading partners.","vi":"Mặc dù chủ nghĩa bảo hộ có thể hỗ trợ các ngành công nghiệp trong nước trong ngắn hạn, nhưng nó có thể làm tăng giá tiêu dùng và gây ra các tranh chấp với các đối tác thương mại.","audioKind":"ex2"}],"collocations":[{"en":"trade protectionism","vi":"chủ nghĩa bảo hộ thương mại"},{"en":"rising protectionism","vi":"chủ nghĩa bảo hộ đang trỗi dậy"},{"en":"resort to protectionism","vi":"sử dụng biện pháp bảo hộ thương mại"}],"wordFamily":["protectionist (adj.)","protection (n.)","protect (v.)"],"synonyms":[],"antonyms":["free trade"],"tipVi":"Đây là danh từ không đếm được, dùng chuyên biệt cho chính sách kinh tế/thương mại chứ không chỉ sự bảo vệ chung chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ware', 'en-c1-42', 'ware', '/wer/', 'C1', 'đồ vật được làm từ một vật liệu cụ thể hoặc dùng cho một mục đích cụ thể; đồ gốm; hàng hóa đem ra bán (thường dùng số nhiều là wares)', 'n.', 'earthenware (n.), glassware (n.), tableware (n.)', 'Đồng nghĩa: goods, merchandise', 'Chỉ hàng hóa đem bán thường dùng dạng số nhiều wares; ware thường xuất hiện trong các từ ghép.', 'The potter displayed her glazed ware on wooden shelves.', NULL, 'Người thợ gốm trưng bày các sản phẩm đồ gốm tráng men của cô ấy trên các kệ gỗ.', '{"wordId":"ware","ukIpa":"/weə/","usIpa":"/wer/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Objects made from a particular material or for a particular use.","vi":"đồ vật được làm từ một vật liệu cụ thể hoặc dùng cho một mục đích cụ thể; đồ gốm"},{"pos":"n.","en":"Goods offered for sale, usually called wares.","vi":"hàng hóa đem ra bán (thường dùng số nhiều là wares)"}],"examples":[{"en":"The potter displayed her glazed ware on wooden shelves.","vi":"Người thợ gốm trưng bày các sản phẩm đồ gốm tráng men của cô ấy trên các kệ gỗ.","audioKind":"ex"},{"en":"Local markets allow craftspeople to sell their wares directly, supporting traditional skills and small businesses.","vi":"Các khu chợ địa phương cho phép nghệ nhân trực tiếp bày bán sản phẩm của họ, qua đó hỗ trợ các kỹ năng truyền thống và doanh nghiệp nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"ceramic ware","vi":"đồ gốm sứ"},{"en":"glazed ware","vi":"đồ gốm tráng men"},{"en":"sell one''s wares","vi":"bán hàng hóa của mình"}],"wordFamily":["earthenware (n.)","glassware (n.)","tableware (n.)"],"synonyms":["goods","merchandise"],"antonyms":[],"tipVi":"Chỉ hàng hóa đem bán thường dùng dạng số nhiều wares; ware thường xuất hiện trong các từ ghép.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dumping', 'en-c1-42', 'dumping', '/ˈdʌmpɪŋ/', 'C1', 'bán phá giá; hành vi bán phá giá; sự xả thải; sự đổ rác bừa bãi', 'n.', 'dump (v.), dump (n.)', NULL, 'Trong thương mại, từ này chỉ hoạt động xuất khẩu với giá thấp hơn giá trị thực tế, không dùng cho các đợt giảm giá thông thường.', 'Local farmers say cheap imports are evidence of dumping.', NULL, 'Nông dân địa phương cho biết hàng nhập khẩu giá rẻ chính là bằng chứng của hành vi bán phá giá.', '{"wordId":"dumping","ukIpa":"/ˈdʌmpɪŋ/","usIpa":"/ˈdʌmpɪŋ/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Selling goods abroad below normal value, often harming local producers","vi":"bán phá giá; hành vi bán phá giá"},{"pos":"n.","en":"Leaving unwanted material somewhere, often illegally or carelessly","vi":"sự xả thải; sự đổ rác bừa bãi"}],"examples":[{"en":"Local farmers say cheap imports are evidence of dumping.","vi":"Nông dân địa phương cho biết hàng nhập khẩu giá rẻ chính là bằng chứng của hành vi bán phá giá.","audioKind":"ex"},{"en":"Governments may impose tariffs to counter dumping, although such measures can raise prices for domestic consumers.","vi":"Chính phủ có thể áp thuế để chống bán phá giá, dù các biện pháp như vậy có thể làm tăng giá đối với người tiêu dùng trong nước.","audioKind":"ex2"}],"collocations":[{"en":"anti-dumping measures","vi":"biện pháp chống bán phá giá"},{"en":"dumping allegations","vi":"cáo buộc bán phá giá"},{"en":"illegal dumping","vi":"xả thải trái phép"},{"en":"waste dumping","vi":"đổ rác thải"}],"wordFamily":["dump (v.)","dump (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong thương mại, từ này chỉ hoạt động xuất khẩu với giá thấp hơn giá trị thực tế, không dùng cho các đợt giảm giá thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_payable', 'en-c1-42', 'payable', '/ˈpeɪəbl/', 'C1', 'phải được thanh toán vào một thời điểm cụ thể đã định; dự định chi trả cho một cá nhân hoặc tổ chức nhất định', 'adj.', 'pay (v.), payment (n.), payer (n.), unpaid (adj.)', 'Đồng nghĩa: due', 'payable to đi kèm người nhận tiền; payable in đi kèm phương thức hoặc đơn vị tiền tệ.', 'The full rent is payable before you move in.', NULL, 'Toàn bộ tiền thuê nhà phải được thanh toán trước khi bạn chuyển đến ở.', '{"wordId":"payable","ukIpa":"/ˈpeɪəbl/","usIpa":"/ˈpeɪəbl/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"Required to be paid at a specified time","vi":"phải được thanh toán vào một thời điểm cụ thể đã định"},{"pos":"adj.","en":"Intended to be paid to a particular person or organisation","vi":"dự định chi trả cho một cá nhân hoặc tổ chức nhất định"}],"examples":[{"en":"The full rent is payable before you move in.","vi":"Toàn bộ tiền thuê nhà phải được thanh toán trước khi bạn chuyển đến ở.","audioKind":"ex"},{"en":"University tuition fees are often payable in instalments, allowing students to spread their costs throughout the academic year.","vi":"Học phí đại học thường có thể trả góp, giúp sinh viên phân bổ chi phí trong suốt năm học.","audioKind":"ex2"}],"collocations":[{"en":"payable in advance","vi":"thanh toán trước"},{"en":"payable on demand","vi":"thanh toán ngay khi xuất trình"},{"en":"payable to","vi":"trả cho ai"},{"en":"payable in instalments","vi":"được trả góp"}],"wordFamily":["pay (v.)","payment (n.)","payer (n.)","unpaid (adj.)"],"synonyms":["due"],"antonyms":[],"tipVi":"payable to đi kèm người nhận tiền; payable in đi kèm phương thức hoặc đơn vị tiền tệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sterling', 'en-c1-42', 'sterling', '/ˈstɝːlɪŋ/', 'C1', 'đồng bảng Anh, đơn vị tiền tệ của Vương quốc Anh; có chất lượng tuyệt vời, rất đáng ngưỡng mộ; được làm bằng bạc có độ nguyên chất ít nhất 92,5 phần trăm', 'n.', NULL, NULL, '"sterling silver" thường chứa 92.5% bạc, không phải là bạc nguyên chất 100%.', 'We exchanged our remaining foreign currency for sterling yesterday.', NULL, 'Hôm qua chúng tôi đã đổi số ngoại tệ còn lại sang đồng bảng Anh.', '{"wordId":"sterling","ukIpa":"/ˈstɜːlɪŋ/","usIpa":"/ˈstɝːlɪŋ/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"the currency of the United Kingdom","vi":"đồng bảng Anh, đơn vị tiền tệ của Vương quốc Anh"},{"pos":"adj.","en":"excellent in quality and deserving admiration","vi":"có chất lượng tuyệt vời, rất đáng ngưỡng mộ"},{"pos":"adj.","en":"made of silver containing at least 92.5 percent pure silver","vi":"được làm bằng bạc có độ nguyên chất ít nhất 92,5 phần trăm"}],"examples":[{"en":"We exchanged our remaining foreign currency for sterling yesterday.","vi":"Hôm qua chúng tôi đã đổi số ngoại tệ còn lại sang đồng bảng Anh.","audioKind":"ex"},{"en":"A fall in sterling may attract international tourists by making accommodation and local services more affordable.","vi":"Sự sụt giảm của đồng bảng Anh có thể thu hút khách du lịch quốc tế bằng cách làm cho chi phí lưu trú và dịch vụ địa phương trở nên phải chăng hơn.","audioKind":"ex2"}],"collocations":[{"en":"pounds sterling","vi":"đồng bảng Anh"},{"en":"sterling silver","vi":"bạc tiêu chuẩn"},{"en":"sterling work","vi":"công việc xuất sắc"},{"en":"sterling qualities","vi":"phẩm chất cao quý"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"sterling silver\" thường chứa 92.5% bạc, không phải là bạc nguyên chất 100%.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subsidy', 'en-c1-42', 'subsidy', '/ˈsʌbsədi/', 'C1', 'tiền trợ cấp; khoản hỗ trợ tài chính', 'n.', 'subsidise (v.), subsidised (adj.), subsidisation (n.)', 'Đồng nghĩa: grant', 'Là danh từ đếm được, số nhiều là ''subsidies''; thường đi kèm với giới từ ''for''.', 'A government subsidy helped us install solar panels at home.', NULL, 'Khoản trợ cấp từ chính phủ đã giúp chúng tôi lắp đặt các tấm pin mặt trời tại nhà.', '{"wordId":"subsidy","ukIpa":"/ˈsʌbsədi/","usIpa":"/ˈsʌbsədi/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Money provided to support activities or keep prices lower.","vi":"tiền trợ cấp; khoản hỗ trợ tài chính"}],"examples":[{"en":"A government subsidy helped us install solar panels at home.","vi":"Khoản trợ cấp từ chính phủ đã giúp chúng tôi lắp đặt các tấm pin mặt trời tại nhà.","audioKind":"ex"},{"en":"Targeted subsidies for public transport can make commuting more affordable while encouraging people to use their cars less.","vi":"Các khoản trợ cấp nhắm đúng mục tiêu cho giao thông công cộng có thể giúp giảm chi phí đi lại đồng thời khuyến khích người dân hạn chế sử dụng ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"government subsidy","vi":"trợ cấp chính phủ"},{"en":"agricultural subsidies","vi":"trợ cấp nông nghiệp"},{"en":"receive a subsidy","vi":"nhận trợ cấp"},{"en":"subsidy scheme","vi":"chương trình trợ cấp"}],"wordFamily":["subsidise (v.)","subsidised (adj.)","subsidisation (n.)"],"synonyms":["grant"],"antonyms":[],"tipVi":"Là danh từ đếm được, số nhiều là ''subsidies''; thường đi kèm với giới từ ''for''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lag', 'en-c1-42', 'lag', '/læɡ/', 'C1', 'chậm hơn; phát triển chậm hơn; sự chậm trễ; khoảng thời gian chờ', 'v.', NULL, NULL, 'Thường dùng cấu trúc lag behind để diễn tả việc bị tụt lại phía sau; dạng quá khứ là lagged.', 'I always lag behind my sister on steep hills.', NULL, 'Tôi luôn bị tụt lại phía sau chị tôi trên những con dốc đứng.', '{"wordId":"lag","ukIpa":"/læɡ/","usIpa":"/læɡ/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"Move or develop more slowly than others","vi":"chậm hơn; phát triển chậm hơn"},{"pos":"n.","en":"A delay between related actions, events, or changes","vi":"sự chậm trễ; khoảng thời gian chờ"}],"examples":[{"en":"I always lag behind my sister on steep hills.","vi":"Tôi luôn bị tụt lại phía sau chị tôi trên những con dốc đứng.","audioKind":"ex"},{"en":"Investment in rural transport often lags behind urban development, limiting access to jobs and essential services.","vi":"Đầu tư vào giao thông nông thôn thường tụt hậu so với sự phát triển đô thị, làm hạn chế khả năng tiếp cận việc làm và các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"lag behind","vi":"tụt lại phía sau"},{"en":"time lag","vi":"khoảng thời gian chậm trễ"},{"en":"a lag in development","vi":"sự phát triển chậm trễ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc lag behind để diễn tả việc bị tụt lại phía sau; dạng quá khứ là lagged.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_franchise', 'en-c1-42', 'franchise', '/ˈfræntʃaɪz/', 'C1', 'quyền kinh doanh nhượng quyền; cửa hàng nhượng quyền; quyền bầu cử; cấp quyền kinh doanh nhượng quyền', 'n.', 'franchisee (n.), franchisor (n.), franchising (n.)', NULL, 'Trong ngữ cảnh kinh doanh nghĩa là nhượng quyền; the franchise cũng chỉ quyền bầu cử.', 'My aunt bought a franchise and opened a bakery.', NULL, 'Dì của tôi đã mua quyền nhượng quyền thương mại và mở một tiệm bánh.', '{"wordId":"franchise","ukIpa":"/ˈfræntʃaɪz/","usIpa":"/ˈfræntʃaɪz/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"permission to trade under another company''s name, or that business","vi":"quyền kinh doanh nhượng quyền; cửa hàng nhượng quyền"},{"pos":"n.","en":"the legal right to vote in elections","vi":"quyền bầu cử"},{"pos":"v.","en":"to let others operate businesses using your company''s name","vi":"cấp quyền kinh doanh nhượng quyền"}],"examples":[{"en":"My aunt bought a franchise and opened a bakery.","vi":"Dì của tôi đã mua quyền nhượng quyền thương mại và mở một tiệm bánh.","audioKind":"ex"},{"en":"Operating a franchise allows entrepreneurs to use an established business model, but often limits their independence.","vi":"Việc vận hành một cơ sở nhượng quyền cho phép các nhà khởi nghiệp tận dụng mô hình kinh doanh đã có sẵn, nhưng thường làm hạn chế tính độc lập của họ.","audioKind":"ex2"}],"collocations":[{"en":"buy a franchise","vi":"mua quyền nhượng quyền"},{"en":"franchise agreement","vi":"hợp đồng nhượng quyền"},{"en":"franchise fee","vi":"phí nhượng quyền"},{"en":"extend the franchise","vi":"mở rộng quyền bầu cử"}],"wordFamily":["franchisee (n.)","franchisor (n.)","franchising (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh kinh doanh nghĩa là nhượng quyền; the franchise cũng chỉ quyền bầu cử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_utility', 'en-c1-42', 'utility', '/juːˈtɪləti/', 'C1', 'tính thiết thực; công dụng; dịch vụ công ích; tiện ích công cộng; chương trình tiện ích', 'n.', 'utilise (v.), utilisation (n.), utilitarian (adj.)', 'Đồng nghĩa: usefulness · Trái nghĩa: uselessness', 'Nghĩa "hiệu quả/ích lợi" thường không đếm được; dịch vụ điện nước thường dùng số nhiều utilities.', 'This folding table offers real utility in our tiny kitchen.', NULL, 'Chiếc bàn gấp này mang lại tính thiết thực thực sự trong căn bếp nhỏ của chúng tôi.', '{"wordId":"utility","ukIpa":"/juːˈtɪləti/","usIpa":"/juːˈtɪləti/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"the usefulness of something for a particular purpose","vi":"tính thiết thực; công dụng"},{"pos":"n.","en":"an essential service such as water, gas, or electricity","vi":"dịch vụ công ích; tiện ích công cộng"},{"pos":"n.","en":"a computer program that performs a specific practical task","vi":"chương trình tiện ích"}],"examples":[{"en":"This folding table offers real utility in our tiny kitchen.","vi":"Chiếc bàn gấp này mang lại tính thiết thực thực sự trong căn bếp nhỏ của chúng tôi.","audioKind":"ex"},{"en":"Reliable access to basic utilities is essential for improving public health and supporting economic development in rural communities.","vi":"Việc tiếp cận đáng tin cậy các dịch vụ công ích cơ bản đóng vai trò cốt lõi trong việc nâng cao sức khỏe cộng đồng và hỗ trợ phát triển kinh tế ở các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"practical utility","vi":"công dụng thực tế"},{"en":"public utilities","vi":"tiện ích công cộng"},{"en":"utility bills","vi":"hóa đơn điện nước"},{"en":"utility company","vi":"công ty dịch vụ công ích"}],"wordFamily":["utilise (v.)","utilisation (n.)","utilitarian (adj.)"],"synonyms":["usefulness"],"antonyms":["uselessness"],"tipVi":"Nghĩa \"hiệu quả/ích lợi\" thường không đếm được; dịch vụ điện nước thường dùng số nhiều utilities.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marginal', 'en-c1-42', 'marginal', '/ˈmɑːrdʒɪnəl/', 'C1', 'nhỏ; không đáng kể; không quan trọng; ở ngoài lề; phụ; không phải cốt lõi; mức độ vừa đủ; suýt soát', 'adj.', 'marginally (adv.), marginalise (v.), marginalisation (n.)', 'Đồng nghĩa: slight, minor · Trái nghĩa: significant, substantial', 'Khi diễn tả sự thay đổi, từ này chỉ mức độ biến động rất nhỏ chứ không phải hoàn toàn không có thay đổi.', 'The new tyres made only a marginal difference.', NULL, 'Bộ lốp mới chỉ tạo ra sự khác biệt không đáng kể.', '{"wordId":"marginal","ukIpa":"/ˈmɑːdʒɪnəl/","usIpa":"/ˈmɑːrdʒɪnəl/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"very small in amount, effect, or importance","vi":"nhỏ; không đáng kể; không quan trọng"},{"pos":"adj.","en":"outside the main or central part of something","vi":"ở ngoài lề; phụ; không phải cốt lõi"},{"pos":"adj.","en":"only just good enough for a particular purpose","vi":"mức độ vừa đủ; suýt soát"}],"examples":[{"en":"The new tyres made only a marginal difference.","vi":"Bộ lốp mới chỉ tạo ra sự khác biệt không đáng kể.","audioKind":"ex"},{"en":"Despite substantial investment, the programme produced only marginal improvements in public transport reliability across the city.","vi":"Mặc dù đã đầu tư đáng kể, chương trình này chỉ đem lại sự cải thiện vô cùng nhỏ đối với độ tin cậy của giao thông công cộng trên toàn thành phố.","audioKind":"ex2"}],"collocations":[{"en":"marginal improvement","vi":"sự cải thiện nhỏ"},{"en":"marginal difference","vi":"sự khác biệt không đáng kể"},{"en":"marginal role","vi":"vai trò thứ yếu"}],"wordFamily":["marginally (adv.)","marginalise (v.)","marginalisation (n.)"],"synonyms":["slight","minor"],"antonyms":["significant","substantial"],"tipVi":"Khi diễn tả sự thay đổi, từ này chỉ mức độ biến động rất nhỏ chứ không phải hoàn toàn không có thay đổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gratis', 'en-c1-42', 'gratis', '/ˈɡrætɪs/', 'C1', 'một cách miễn phí; miễn phí', 'adv.', NULL, 'Đồng nghĩa: free, free of charge', 'Có thể đóng vai trò là phó từ hoặc tính từ, mang sắc thái trang trọng hơn; trong văn phong hàng ngày thường dùng từ "free".', 'The hotel lent us two bicycles gratis for the afternoon.', NULL, 'Khách sạn đã cho chúng tôi mượn hai chiếc xe đạp miễn phí trong suốt buổi chiều.', '{"wordId":"gratis","ukIpa":"/ˈɡrætɪs/","usIpa":"/ˈɡrætɪs/","cefr":"C1","topic":"economy","senses":[{"pos":"adv.","en":"without any payment being required","vi":"một cách miễn phí"},{"pos":"adj.","en":"provided without requiring payment","vi":"miễn phí"}],"examples":[{"en":"The hotel lent us two bicycles gratis for the afternoon.","vi":"Khách sạn đã cho chúng tôi mượn hai chiếc xe đạp miễn phí trong suốt buổi chiều.","audioKind":"ex"},{"en":"Providing museum admission gratis can encourage wider public participation in cultural and educational activities.","vi":"Việc cung cấp vé vào cửa bảo tàng miễn phí có thể khuyến khích công chúng tham gia nhiều hơn vào các hoạt động văn hóa và giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"provided gratis","vi":"được cung cấp miễn phí"},{"en":"distributed gratis","vi":"được phân phát miễn phí"},{"en":"gratis admission","vi":"vào cửa miễn phí"}],"wordFamily":[],"synonyms":["free","free of charge"],"antonyms":[],"tipVi":"Có thể đóng vai trò là phó từ hoặc tính từ, mang sắc thái trang trọng hơn; trong văn phong hàng ngày thường dùng từ \"free\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slowdown', 'en-c1-42', 'slowdown', '/ˈsloʊdaʊn/', 'C1', 'sự giảm tốc; sự trì trệ; sự chậm lại', 'n.', 'slow (adj.), slow (v.), slowly (adv.)', 'Đồng nghĩa: deceleration · Trái nghĩa: acceleration', '"Slowdown" là danh từ; trong khi cụm từ chỉ hành động là động từ "slow down".', 'Road repairs caused a slowdown on my journey home.', NULL, 'Việc sửa chữa đường sá đã gây ra tình trạng giảm tốc độ trên hành trình về nhà của tôi.', '{"wordId":"slowdown","ukIpa":"/ˈsləʊdaʊn/","usIpa":"/ˈsloʊdaʊn/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"A reduction in the speed of activity or growth","vi":"sự giảm tốc; sự trì trệ; sự chậm lại"}],"examples":[{"en":"Road repairs caused a slowdown on my journey home.","vi":"Việc sửa chữa đường sá đã gây ra tình trạng giảm tốc độ trên hành trình về nhà của tôi.","audioKind":"ex"},{"en":"An economic slowdown can reduce job opportunities, particularly for young people entering the labour market.","vi":"Sự chậm lại của nền kinh tế có thể làm giảm cơ hội việc làm, đặc biệt đối với những người trẻ tuổi bước chân vào thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"an economic slowdown","vi":"sự suy thoái kinh tế"},{"en":"a slowdown in growth","vi":"sự tăng trưởng chậm lại"},{"en":"a sharp slowdown","vi":"sự giảm sút nghiêm trọng"}],"wordFamily":["slow (adj.)","slow (v.)","slowly (adv.)"],"synonyms":["deceleration"],"antonyms":["acceleration"],"tipVi":"\"Slowdown\" là danh từ; trong khi cụm từ chỉ hành động là động từ \"slow down\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reexport', 'en-c1-42', 'reexport', '/ˌriːɪkˈspɔːrt/', 'C1', 'tái xuất khẩu; chuyển khẩu', 'v.', 'export (v.), exporter (n.), reexportation (n.)', NULL, 'Cũng được viết là re-export, chỉ hành động xuất khẩu trở lại hàng hóa đã nhập trước đó.', 'They import tea, package it locally, and reexport it.', NULL, 'Họ nhập khẩu trà, đóng gói tại chỗ rồi tái xuất khẩu.', '{"wordId":"reexport","ukIpa":"/ˌriːɪkˈspɔːt/","usIpa":"/ˌriːɪkˈspɔːrt/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"to export goods that were previously imported","vi":"tái xuất khẩu; chuyển khẩu"}],"examples":[{"en":"They import tea, package it locally, and reexport it.","vi":"Họ nhập khẩu trà, đóng gói tại chỗ rồi tái xuất khẩu.","audioKind":"ex"},{"en":"Some ports reexport imported goods to neighbouring countries, creating jobs in storage, transport, and related services.","vi":"Một số cảng biển tái xuất khẩu hàng hóa đã nhập khẩu sang các nước láng giềng, tạo ra việc làm trong lĩnh vực lưu kho, vận tải và các dịch vụ liên quan.","audioKind":"ex2"}],"collocations":[{"en":"reexport goods","vi":"hàng tái xuất"},{"en":"reexport imported products","vi":"tái xuất sản phẩm đã nhập khẩu"},{"en":"reexport to neighbouring markets","vi":"tái xuất sang thị trường láng giềng"}],"wordFamily":["export (v.)","exporter (n.)","reexportation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cũng được viết là re-export, chỉ hành động xuất khẩu trở lại hàng hóa đã nhập trước đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_magnate', 'en-c1-42', 'magnate', '/ˈmæɡneɪt/', 'C1', 'ông trùm; nhà tài phiệt', 'n.', NULL, 'Đồng nghĩa: tycoon, mogul', 'Thường đi kèm với tên ngành nghề; chú ý không nhầm lẫn với từ magnet (nam châm).', 'The hotel magnate arrived in a surprisingly small car.', NULL, 'Ông trùm khách sạn đã đến trên một chiếc xe hơi nhỏ đến bất ngờ.', '{"wordId":"magnate","ukIpa":"/ˈmæɡneɪt/","usIpa":"/ˈmæɡneɪt/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"a wealthy and powerful person in a particular industry","vi":"ông trùm; nhà tài phiệt"}],"examples":[{"en":"The hotel magnate arrived in a surprisingly small car.","vi":"Ông trùm khách sạn đã đến trên một chiếc xe hơi nhỏ đến bất ngờ.","audioKind":"ex"},{"en":"A media magnate may influence public debate through ownership of several major news outlets.","vi":"Một ông trùm truyền thông có thể ảnh hưởng đến tranh luận công khai thông qua quyền sở hữu nhiều cơ quan tin tức lớn.","audioKind":"ex2"}],"collocations":[{"en":"a media magnate","vi":"ông trùm truyền thông"},{"en":"a shipping magnate","vi":"ông trùm ngành vận tải biển"},{"en":"a business magnate","vi":"đại gia kinh doanh"}],"wordFamily":[],"synonyms":["tycoon","mogul"],"antonyms":[],"tipVi":"Thường đi kèm với tên ngành nghề; chú ý không nhầm lẫn với từ magnet (nam châm).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accrue', 'en-c1-42', 'accrue', '/əˈkruː/', 'C1', 'tích lũy dần; thu về dần theo thời gian', 'v.', 'accrual (n.), accrued (adj.)', 'Đồng nghĩa: accumulate', 'Thường dùng cho lãi suất, lợi ích tích lũy dần; accrue to mang nghĩa thuộc về hoặc đem lại lợi ích cho ai.', 'Interest accrues monthly on the money in this account.', NULL, 'Tiền lãi trong tài khoản này được tích lũy hàng tháng.', '{"wordId":"accrue","ukIpa":"/əˈkruː/","usIpa":"/əˈkruː/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"To increase gradually, or receive benefits over time","vi":"tích lũy dần; thu về dần theo thời gian"}],"examples":[{"en":"Interest accrues monthly on the money in this account.","vi":"Tiền lãi trong tài khoản này được tích lũy hàng tháng.","audioKind":"ex"},{"en":"The benefits of early education accrue over many years, improving both individual opportunities and wider social outcomes.","vi":"Lợi ích của giáo dục sớm tích lũy qua nhiều năm, vừa nâng cao cơ hội cá nhân vừa mang lại kết quả xã hội rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"interest accrues","vi":"tiền lãi tích lũy"},{"en":"accrue benefits","vi":"thu được lợi ích"},{"en":"accrue to","vi":"thuộc về; mang lại cho"},{"en":"accrued income","vi":"thu nhập dồn tích"}],"wordFamily":["accrual (n.)","accrued (adj.)"],"synonyms":["accumulate"],"antonyms":[],"tipVi":"Thường dùng cho lãi suất, lợi ích tích lũy dần; accrue to mang nghĩa thuộc về hoặc đem lại lợi ích cho ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inducement', 'en-c1-42', 'inducement', '/ɪnˈduːsmənt/', 'C1', 'sự xúi giục; động lực khuyến khích', 'n.', 'induce (v.)', 'Đồng nghĩa: incentive, enticement · Trái nghĩa: deterrent', 'Thường chỉ phần thưởng hoặc lợi ích từ bên ngoài, theo sau có thể là to do.', 'Free delivery was enough inducement to order the sofa.', NULL, 'Miễn phí vận chuyển là động lực vừa đủ để tôi quyết định đặt mua chiếc ghế sofa đó.', '{"wordId":"inducement","ukIpa":"/ɪnˈdjuːsmənt/","usIpa":"/ɪnˈduːsmənt/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"something offered to persuade someone to take a particular action","vi":"sự xúi giục; động lực khuyến khích"}],"examples":[{"en":"Free delivery was enough inducement to order the sofa.","vi":"Miễn phí vận chuyển là động lực vừa đủ để tôi quyết định đặt mua chiếc ghế sofa đó.","audioKind":"ex"},{"en":"Financial inducements may encourage households to install solar panels, reducing their dependence on fossil fuels.","vi":"Các biện pháp khích lệ tài chính có thể thúc đẩy các hộ gia đình lắp đặt pin năng lượng mặt trời, qua đó giảm bớt sự phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"financial inducement","vi":"ưu đãi tài chính"},{"en":"offer an inducement","vi":"cung cấp động lực"},{"en":"inducement to invest","vi":"động lực đầu tư"}],"wordFamily":["induce (v.)"],"synonyms":["incentive","enticement"],"antonyms":["deterrent"],"tipVi":"Thường chỉ phần thưởng hoặc lợi ích từ bên ngoài, theo sau có thể là to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intangible', 'en-c1-42', 'intangible', '/ɪnˈtændʒəbl/', 'C1', 'vô hình; phi vật chất; khó đo lường', 'adj.', 'intangibility (n.), intangibly (adv.), tangible (adj.)', 'Đồng nghĩa: impalpable · Trái nghĩa: tangible', 'Không chỉ chỉ những thứ không sờ nắm được, mà còn chỉ giá trị khó lòng định lượng.', 'Her warm welcome gave the house an intangible charm.', NULL, 'Sự đón tiếp nồng hậu của cô ấy đã mang lại cho ngôi nhà một nét quyến rũ khó tả.', '{"wordId":"intangible","ukIpa":"/ɪnˈtændʒəbl/","usIpa":"/ɪnˈtændʒəbl/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"Not physically touchable or easily measured, but still real or valuable","vi":"vô hình; phi vật chất; khó đo lường"}],"examples":[{"en":"Her warm welcome gave the house an intangible charm.","vi":"Sự đón tiếp nồng hậu của cô ấy đã mang lại cho ngôi nhà một nét quyến rũ khó tả.","audioKind":"ex"},{"en":"Public parks offer intangible benefits, including a stronger sense of belonging and improved community relationships.","vi":"Các công viên công cộng mang lại những lợi ích vô hình, bao gồm ý thức thuộc về cộng đồng mạnh mẽ hơn và mối quan hệ xã hội được cải thiện.","audioKind":"ex2"}],"collocations":[{"en":"intangible benefits","vi":"lợi ích vô hình"},{"en":"intangible assets","vi":"tài sản vô hình"},{"en":"intangible cultural heritage","vi":"di sản văn hóa phi vật chất"}],"wordFamily":["intangibility (n.)","intangibly (adv.)","tangible (adj.)"],"synonyms":["impalpable"],"antonyms":["tangible"],"tipVi":"Không chỉ chỉ những thứ không sờ nắm được, mà còn chỉ giá trị khó lòng định lượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_42_1', 'en-c1-42', 'Cách dùng “dumping” (n.) — bán phá giá; hành vi bán phá giá', 'anti-dumping measures  ·  dumping allegations  ·  illegal dumping', 'Trong thương mại, từ này chỉ hoạt động xuất khẩu với giá thấp hơn giá trị thực tế, không dùng cho các đợt giảm giá thông thường.', 'Họ từ (Word Family): dump (v.), dump (n.)', '[{"hanzi":"Local farmers say cheap imports are evidence of dumping.","pinyin":"","meaning":"Nông dân địa phương cho biết hàng nhập khẩu giá rẻ chính là bằng chứng của hành vi bán phá giá."},{"hanzi":"Governments may impose tariffs to counter dumping, although such measures can raise prices for domestic consumers.","pinyin":"","meaning":"Chính phủ có thể áp thuế để chống bán phá giá, dù các biện pháp như vậy có thể làm tăng giá đối với người tiêu dùng trong nước."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_42_2', 'en-c1-42', 'Cách dùng “gratis” (adv.) — một cách miễn phí', 'provided gratis  ·  distributed gratis  ·  gratis admission', 'Có thể đóng vai trò là phó từ hoặc tính từ, mang sắc thái trang trọng hơn; trong văn phong hàng ngày thường dùng từ "free".', 'Đồng nghĩa: free, free of charge', '[{"hanzi":"The hotel lent us two bicycles gratis for the afternoon.","pinyin":"","meaning":"Khách sạn đã cho chúng tôi mượn hai chiếc xe đạp miễn phí trong suốt buổi chiều."},{"hanzi":"Providing museum admission gratis can encourage wider public participation in cultural and educational activities.","pinyin":"","meaning":"Việc cung cấp vé vào cửa bảo tàng miễn phí có thể khuyến khích công chúng tham gia nhiều hơn vào các hoạt động văn hóa và giáo dục."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_42_3', 'en-c1-42', 'Cách dùng “protectionism” (n.) — chủ nghĩa bảo hộ mậu dịch; chính sách bảo hộ', 'trade protectionism  ·  rising protectionism  ·  resort to protectionism', 'Đây là danh từ không đếm được, dùng chuyên biệt cho chính sách kinh tế/thương mại chứ không chỉ sự bảo vệ chung chung.', 'Họ từ (Word Family): protectionist (adj.), protection (n.), protect (v.) | Trái nghĩa: free trade', '[{"hanzi":"We discussed protectionism after imported shoes became more expensive.","pinyin":"","meaning":"Chúng tôi đã thảo luận về chủ nghĩa bảo hộ thương mại sau khi giá giày nhập khẩu trở nên đắt đỏ hơn."},{"hanzi":"Although protectionism may support domestic industries temporarily, it can raise consumer prices and provoke disputes with trading partners.","pinyin":"","meaning":"Mặc dù chủ nghĩa bảo hộ có thể hỗ trợ các ngành công nghiệp trong nước trong ngắn hạn, nhưng nó có thể làm tăng giá tiêu dùng và gây ra các tranh chấp với các đối tác thương mại."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_42_4', 'en-c1-42', 'Cách dùng “cripple” (v.) — làm tê liệt; tàn phá năng lực hoạt động', 'cripple the economy  ·  cripple production  ·  crippling costs', 'Dùng làm danh từ chỉ người có thể mang tính xúc phạm; động từ thường chỉ kinh tế hoặc hệ thống bị trọng thương.', 'Họ từ (Word Family): crippling (adj.) | Đồng nghĩa: disable, paralyse', '[{"hanzi":"The power cut crippled our heating system all evening.","pinyin":"","meaning":"Việc cắt điện đã làm tê liệt hệ thống sưởi của chúng tôi suốt cả buổi tối."},{"hanzi":"A prolonged drought can cripple agricultural production, reducing rural incomes and increasing food prices across the country.","pinyin":"","meaning":"Hạn hán kéo dài có thể giáng đòn nặng nề vào sản xuất nông nghiệp, làm giảm thu nhập ở nông thôn và đẩy giá thực phẩm tăng cao trên toàn quốc."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_42_1', 'en-c1-42', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_1_1', 'ten_c1_42_1', 'cripple', 'The power cut crippled our heating system all evening.', 'The power cut crippled our heating system all evening.', '/ˈkrɪpəl/', 'Việc cắt điện đã làm tê liệt hệ thống sưởi của chúng tôi suốt cả buổi tối.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_1_2', 'ten_c1_42_1', 'accrued', 'My bank statement shows the accrued interest on my savings.', 'My bank statement shows the accrued interest on my savings.', '/əˈkruːd/', 'Sao kê ngân hàng của tôi hiển thị khoản tiền lãi đã tích lũy trong tài khoản tiết kiệm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_1_3', 'ten_c1_42_1', 'volatile', 'Fuel prices have been unusually volatile this month.', 'Fuel prices have been unusually volatile this month.', '/ˈvɑːlətəl/', 'Giá nhiên liệu tháng này biến động bất thường.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_1_4', 'ten_c1_42_1', 'depreciate', 'New cars often depreciate quickly during their first year.', 'New cars often depreciate quickly during their first year.', '/dɪˈpriːʃieɪt/', 'Ô tô mới thường mất giá nhanh chóng trong năm đầu tiên sử dụng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_1_5', 'ten_c1_42_1', 'globalize', 'Online shops help small businesses globalize without opening stores abroad.', 'Online shops help small businesses globalize without opening stores abroad.', '/ˈɡloʊbəlaɪz/', 'Cửa hàng trực tuyến giúp các doanh nghiệp nhỏ toàn cầu hóa mà không cần mở cửa hàng ở nước ngoài.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_1_6', 'ten_c1_42_1', 'prosperity', 'The busy harbour brought prosperity to our town.', 'The busy harbour brought prosperity to our town.', '/prɑːˈsperəti/', 'Cảng biển tấp nập đã mang lại sự thịnh vượng cho thị trấn của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_1_7', 'ten_c1_42_1', 'exorbitant', 'The hotel charged an exorbitant amount for breakfast.', 'The hotel charged an exorbitant amount for breakfast.', '/ɪɡˈzɔːrbɪtənt/', 'Khách sạn đó tính giá bữa sáng cao đến mức vô lý.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_1_8', 'ten_c1_42_1', 'extravagant', 'Buying another silk coat seemed extravagant on her budget.', 'Buying another silk coat seemed extravagant on her budget.', '/ɪkˈstrævəɡənt/', 'Việc mua thêm một chiếc áo khoác lụa có vẻ vượt quá ngân sách và quá xa hoa đối với cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_42_1_1', 'en-c1-42', 'ten_c1_42_1', 'listening', 'listening', 'The power cut crippled our heating system all evening.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Khách sạn đó tính giá bữa sáng cao đến mức vô lý.","Việc cắt điện đã làm tê liệt hệ thống sưởi của chúng tôi suốt cả buổi tối.","Cảng biển tấp nập đã mang lại sự thịnh vượng cho thị trấn của chúng tôi.","Tôi luôn bị tụt lại phía sau chị tôi trên những con dốc đứng."]'::jsonb, 1, 'The power cut crippled our heating system all evening. → Việc cắt điện đã làm tê liệt hệ thống sưởi của chúng tôi suốt cả buổi tối.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_42_1_2', 'en-c1-42', 'ten_c1_42_1', 'listening', 'listening', 'My bank statement shows the accrued interest on my savings.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cảng biển tấp nập đã mang lại sự thịnh vượng cho thị trấn của chúng tôi.","Người thợ gốm trưng bày các sản phẩm đồ gốm tráng men của cô ấy trên các kệ gỗ.","Miễn phí vận chuyển là động lực vừa đủ để tôi quyết định đặt mua chiếc ghế sofa đó.","Sao kê ngân hàng của tôi hiển thị khoản tiền lãi đã tích lũy trong tài khoản tiết kiệm."]'::jsonb, 3, 'My bank statement shows the accrued interest on my savings. → Sao kê ngân hàng của tôi hiển thị khoản tiền lãi đã tích lũy trong tài khoản tiết kiệm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_42_1_3', 'en-c1-42', 'ten_c1_42_1', 'listening', 'listening', 'Fuel prices have been unusually volatile this month.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sự đón tiếp nồng hậu của cô ấy đã mang lại cho ngôi nhà một nét quyến rũ khó tả.","Tôi luôn bị tụt lại phía sau chị tôi trên những con dốc đứng.","Giá nhiên liệu tháng này biến động bất thường.","Người thợ gốm trưng bày các sản phẩm đồ gốm tráng men của cô ấy trên các kệ gỗ."]'::jsonb, 2, 'Fuel prices have been unusually volatile this month. → Giá nhiên liệu tháng này biến động bất thường.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_42_2', 'en-c1-42', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_2_1', 'ten_c1_42_2', 'cripple', 'A prolonged drought can cripple agricultural production, reducing rural incomes and increasing food prices across the country.', 'A prolonged drought can cripple agricultural production, reducing rural incomes and increasing food prices across the country.', '/ˈkrɪpəl/', 'Hạn hán kéo dài có thể giáng đòn nặng nề vào sản xuất nông nghiệp, làm giảm thu nhập ở nông thôn và đẩy giá thực phẩm tăng cao trên toàn quốc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_2_2', 'ten_c1_42_2', 'accrued', 'Companies must account for accrued expenses to provide an accurate picture of their financial position at year end.', 'Companies must account for accrued expenses to provide an accurate picture of their financial position at year end.', '/əˈkruːd/', 'Các công ty phải hạch toán các khoản chi phí dồn tích để phản ánh chính xác tình hình tài chính của họ vào cuối năm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_2_3', 'ten_c1_42_2', 'volatile', 'Volatile food prices make it difficult for low-income households to plan their spending and maintain a balanced diet.', 'Volatile food prices make it difficult for low-income households to plan their spending and maintain a balanced diet.', '/ˈvɑːlətəl/', 'Giá thực phẩm biến động thất thường khiến các hộ gia đình thu nhập thấp khó lập kế hoạch chi tiêu và duy trì chế độ ăn uống cân bằng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_2_4', 'ten_c1_42_2', 'depreciate', 'When a country''s currency depreciates, imported goods become more expensive, potentially increasing the cost of living.', 'When a country''s currency depreciates, imported goods become more expensive, potentially increasing the cost of living.', '/dɪˈpriːʃieɪt/', 'Khi đồng tiền của một quốc gia mất giá, hàng hóa nhập khẩu trở nên đắt đỏ hơn, có khả năng làm tăng chi phí sinh hoạt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_2_5', 'ten_c1_42_2', 'globalize', 'As companies globalize their operations, governments must cooperate to protect workers and maintain fair competition.', 'As companies globalize their operations, governments must cooperate to protect workers and maintain fair competition.', '/ˈɡloʊbəlaɪz/', 'Khi các doanh nghiệp toàn cầu hóa hoạt động của mình, chính phủ các nước phải hợp tác để bảo vệ người lao động và duy trì cạnh tranh công bằng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_42_2_6', 'ten_c1_42_2', 'prosperity', 'Investment in education can support long-term prosperity by giving workers the skills needed in a changing economy.', 'Investment in education can support long-term prosperity by giving workers the skills needed in a changing economy.', '/prɑːˈsperəti/', 'Đầu tư vào giáo dục có thể hỗ trợ sự thịnh vượng lâu dài bằng cách cung cấp cho người lao động các kỹ năng cần thiết trong một nền kinh tế đang thay đổi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_42_2_1', 'en-c1-42', 'ten_c1_42_2', 'listening', 'listening', 'A prolonged drought can cripple agricultural production, reducing rural incomes and increasing food prices across the country.', NULL, 'Trong câu vừa nghe, từ “cripple” mang nghĩa nào sau đây?', '["biến thể; biến chủng","làm tê liệt; tàn phá năng lực hoạt động","lỗi lạc; kiệt xuất; đáng kính trọng","chăm chú; lắng nghe chăm chú"]'::jsonb, 1, '“cripple” (/ˈkrɪpəl/): làm tê liệt; tàn phá năng lực hoạt động. Câu đầy đủ: A prolonged drought can cripple agricultural production, reducing rural incomes and increasing food prices across the country.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_42_2_2', 'en-c1-42', 'ten_c1_42_2', 'listening', 'listening', 'Companies must account for accrued expenses to provide an accurate picture of their financial position at year end.', NULL, 'Trong câu vừa nghe, từ “accrued” mang nghĩa nào sau đây?', '["tích lũy dần; thu về dần theo thời gian","được tích lũy theo thời gian (đặc biệt là về mặt tài chính); dồn tích","nhập thêm hàng; bổ sung hàng hóa","lơ lửng trên không; bay treo"]'::jsonb, 1, '“accrued” (/əˈkruːd/): được tích lũy theo thời gian (đặc biệt là về mặt tài chính); dồn tích. Câu đầy đủ: Companies must account for accrued expenses to provide an accurate picture of their financial position at year end.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_42_1', 'en-c1-42', 'The power cut crippled our heating system all evening', 'Việc cắt điện đã làm tê liệt hệ thống sưởi của chúng tôi suốt cả buổi tối.', 'cripple /ˈkrɪpəl/', '["heating","power","cut","The","crippled","evening","system","all","our"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_42_2', 'en-c1-42', 'My bank statement shows the accrued interest on my savings', 'Sao kê ngân hàng của tôi hiển thị khoản tiền lãi đã tích lũy trong tài khoản tiết kiệm.', 'accrued /əˈkruːd/', '["on","the","My","bank","statement","accrued","interest","my","savings","shows"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_42_3', 'en-c1-42', 'Fuel prices have been unusually volatile this month', 'Giá nhiên liệu tháng này biến động bất thường.', 'volatile /ˈvɑːlətəl/', '["Fuel","prices","this","have","month","been","unusually","volatile"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_42_4', 'en-c1-42', 'New cars often depreciate quickly during their first year', 'Ô tô mới thường mất giá nhanh chóng trong năm đầu tiên sử dụng.', 'depreciate /dɪˈpriːʃieɪt/', '["cars","their","quickly","often","during","first","depreciate","New","year"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_42_5', 'en-c1-42', 'Online shops help small businesses globalize without opening stores abroad', 'Cửa hàng trực tuyến giúp các doanh nghiệp nhỏ toàn cầu hóa mà không cần mở cửa hàng ở nước ngoài.', 'globalize /ˈɡloʊbəlaɪz/', '["shops","opening","small","without","stores","businesses","Online","globalize","abroad","help"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_42_6', 'en-c1-42', 'The busy harbour brought prosperity to our town', 'Cảng biển tấp nập đã mang lại sự thịnh vượng cho thị trấn của chúng tôi.', 'prosperity /prɑːˈsperəti/', '["The","town","our","prosperity","harbour","brought","busy","to"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_42_7', 'en-c1-42', 'The hotel charged an exorbitant amount for breakfast', 'Khách sạn đó tính giá bữa sáng cao đến mức vô lý.', 'exorbitant /ɪɡˈzɔːrbɪtənt/', '["breakfast","for","charged","The","an","hotel","amount","exorbitant"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_42_8', 'en-c1-42', 'Buying another silk coat seemed extravagant on her budget', 'Việc mua thêm một chiếc áo khoác lụa có vẻ vượt quá ngân sách và quá xa hoa đối với cô ấy.', 'extravagant /ɪkˈstrævəɡənt/', '["Buying","her","coat","seemed","extravagant","another","silk","on","budget"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_42_9', 'en-c1-42', 'We discussed protectionism after imported shoes became more expensive', 'Chúng tôi đã thảo luận về chủ nghĩa bảo hộ thương mại sau khi giá giày nhập khẩu trở nên đắt đỏ hơn.', 'protectionism /prəˈtekʃənɪzəm/', '["expensive","shoes","after","We","protectionism","more","imported","became","discussed"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_42_10', 'en-c1-42', 'The potter displayed her glazed ware on wooden shelves', 'Người thợ gốm trưng bày các sản phẩm đồ gốm tráng men của cô ấy trên các kệ gỗ.', 'ware /wer/', '["displayed","The","on","wooden","shelves","glazed","her","potter","ware"]'::jsonb, NULL, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
