INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_vi_c1_42_5', 'en-c1-42', 'vi_to_en', 'Cửa hàng trực tuyến giúp các doanh nghiệp nhỏ toàn cầu hóa mà không cần mở cửa hàng ở nước ngoài.', NULL, NULL, 'Online shops help small businesses globalize without opening stores abroad.', NULL, 'globalize', '[]'::jsonb, 'Từ khóa gợi ý: globalize (v.)', 'Cửa hàng trực tuyến giúp các doanh nghiệp nhỏ toàn cầu hóa mà không cần mở cửa hàng ở nước ngoài. → Online shops help small businesses globalize without opening stores abroad.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
