INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_42_1', 'en-c1-42', 'en_to_vi', 'The hotel charged an exorbitant amount for breakfast.', 'The hotel charged an exorbitant amount for breakfast.', '/ɪɡˈzɔːrbɪtənt/', NULL, 'Khách sạn đó tính giá bữa sáng cao đến mức vô lý.', NULL, '["khách","sạn","đó","tính","giá","bữa","sáng","cao"]'::jsonb, 'Từ trọng tâm: exorbitant (cắt cổ, đắt cắt cổ; quá mức, cao vô lý)', 'The hotel charged an exorbitant amount for breakfast. → Khách sạn đó tính giá bữa sáng cao đến mức vô lý.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_42_2', 'en-c1-42', 'en_to_vi', 'Buying another silk coat seemed extravagant on her budget.', 'Buying another silk coat seemed extravagant on her budget.', '/ɪkˈstrævəɡənt/', NULL, 'Việc mua thêm một chiếc áo khoác lụa có vẻ vượt quá ngân sách và quá xa hoa đối với cô ấy.', NULL, '["việc","mua","thêm","một","chiếc","áo","khoác","lụa"]'::jsonb, 'Từ trọng tâm: extravagant (xa hoa; phung phí; đắt đỏ)', 'Buying another silk coat seemed extravagant on her budget. → Việc mua thêm một chiếc áo khoác lụa có vẻ vượt quá ngân sách và quá xa hoa đối với cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_42_3', 'en-c1-42', 'en_to_vi', 'We discussed protectionism after imported shoes became more expensive.', 'We discussed protectionism after imported shoes became more expensive.', '/prəˈtekʃənɪzəm/', NULL, 'Chúng tôi đã thảo luận về chủ nghĩa bảo hộ thương mại sau khi giá giày nhập khẩu trở nên đắt đỏ hơn.', NULL, '["chúng","tôi","đã","thảo","luận","về","chủ","nghĩa"]'::jsonb, 'Từ trọng tâm: protectionism (chủ nghĩa bảo hộ mậu dịch; chính sách bảo hộ)', 'We discussed protectionism after imported shoes became more expensive. → Chúng tôi đã thảo luận về chủ nghĩa bảo hộ thương mại sau khi giá giày nhập khẩu trở nên đắt đỏ hơn.', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO translation_exercises (id, lesson_id, direction, prompt_text, audio_text, pinyin, expected_chinese, expected_meaning, accepted_pinyin, accepted_keywords, hint, explanation, sort_order, is_deleted, deleted_at) VALUES ('tren_en_c1_42_4', 'en-c1-42', 'en_to_vi', 'The potter displayed her glazed ware on wooden shelves.', 'The potter displayed her glazed ware on wooden shelves.', '/wer/', NULL, 'Người thợ gốm trưng bày các sản phẩm đồ gốm tráng men của cô ấy trên các kệ gỗ.', NULL, '["người","thợ","gốm","trưng","bày","các","sản","phẩm"]'::jsonb, 'Từ trọng tâm: ware (đồ vật được làm từ một vật liệu cụ thể hoặc dùng cho một mục đích cụ thể; đồ gốm)', 'The potter displayed her glazed ware on wooden shelves. → Người thợ gốm trưng bày các sản phẩm đồ gốm tráng men của cô ấy trên các kệ gỗ.', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, direction = EXCLUDED.direction, prompt_text = EXCLUDED.prompt_text, audio_text = EXCLUDED.audio_text, pinyin = EXCLUDED.pinyin, expected_chinese = EXCLUDED.expected_chinese, expected_meaning = EXCLUDED.expected_meaning, accepted_pinyin = EXCLUDED.accepted_pinyin, accepted_keywords = EXCLUDED.accepted_keywords, hint = EXCLUDED.hint, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
