INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_42_13', 'en-c1-42', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “sterling” (/ˈstɝːlɪŋ/) có nghĩa là gì?', '["tiền trợ cấp; khoản hỗ trợ tài chính","đồ vật được làm từ một vật liệu cụ thể hoặc dùng cho một mục đích cụ thể; đồ gốm","tích lũy dần; thu về dần theo thời gian","đồng bảng Anh, đơn vị tiền tệ của Vương quốc Anh"]'::jsonb, 3, '“sterling” (n.): đồng bảng Anh, đơn vị tiền tệ của Vương quốc Anh; có chất lượng tuyệt vời, rất đáng ngưỡng mộ; được làm bằng bạc có độ nguyên chất ít nhất 92,5 phần trăm.', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_42_14', 'en-c1-42', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “Money provided to support activities or keep prices lower.”', '["payable","subsidy","sterling","accrue"]'::jsonb, 1, '“subsidy” (/ˈsʌbsədi/) nghĩa là: tiền trợ cấp; khoản hỗ trợ tài chính.', 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
