INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_1', 'en-c1-42', NULL, 'comprehensive_test', 'listening', 'cripple', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["than van; tiếc nuối; thương tiếc","thuộc về kích thước; thuộc chiều không gian","làm tê liệt; tàn phá năng lực hoạt động","lướt đi; trôi êm ái; di chuyển nhẹ nhàng"]'::jsonb, 2, 'cripple (/ˈkrɪpəl/) → làm tê liệt; tàn phá năng lực hoạt động; làm thương tật nghiêm trọng; làm tàn phế', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_2', 'en-c1-42', NULL, 'comprehensive_test', 'listening', 'My bank statement shows the accrued interest on my savings.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sao kê ngân hàng của tôi hiển thị khoản tiền lãi đã tích lũy trong tài khoản tiết kiệm.","Khoản trợ cấp từ chính phủ đã giúp chúng tôi lắp đặt các tấm pin mặt trời tại nhà.","Hôm qua chúng tôi đã đổi số ngoại tệ còn lại sang đồng bảng Anh.","Khách sạn đó tính giá bữa sáng cao đến mức vô lý."]'::jsonb, 0, 'My bank statement shows the accrued interest on my savings. → Sao kê ngân hàng của tôi hiển thị khoản tiền lãi đã tích lũy trong tài khoản tiết kiệm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_3', 'en-c1-42', NULL, 'comprehensive_test', 'listening', 'volatile', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["huyết tương","chủ nghĩa tư bản","thay đổi thất thường; dễ biến động","lò phản ứng hạt nhân"]'::jsonb, 2, 'volatile (/ˈvɑːlətəl/) → thay đổi thất thường; dễ biến động; dễ nổi giận; dễ thay đổi cảm xúc; dễ bay hơi', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_4', 'en-c1-42', NULL, 'comprehensive_test', 'listening', 'New cars often depreciate quickly during their first year.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Khách sạn đã cho chúng tôi mượn hai chiếc xe đạp miễn phí trong suốt buổi chiều.","Việc sửa chữa đường sá đã gây ra tình trạng giảm tốc độ trên hành trình về nhà của tôi.","Ô tô mới thường mất giá nhanh chóng trong năm đầu tiên sử dụng.","Tiền lãi trong tài khoản này được tích lũy hàng tháng."]'::jsonb, 2, 'New cars often depreciate quickly during their first year. → Ô tô mới thường mất giá nhanh chóng trong năm đầu tiên sử dụng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_5', 'en-c1-42', NULL, 'comprehensive_test', 'listening', 'globalize', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có thể sai lầm; dễ mắc lỗi","toản cầu hóa; làm cho mang tính toàn cầu","tương thích; có thể dùng chung","động vật linh trưởng"]'::jsonb, 1, 'globalize (/ˈɡloʊbəlaɪz/) → toản cầu hóa; làm cho mang tính toàn cầu', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_6', 'en-c1-42', NULL, 'comprehensive_test', 'listening', 'The busy harbour brought prosperity to our town.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Toàn bộ tiền thuê nhà phải được thanh toán trước khi bạn chuyển đến ở.","Cảng biển tấp nập đã mang lại sự thịnh vượng cho thị trấn của chúng tôi.","Sự đón tiếp nồng hậu của cô ấy đã mang lại cho ngôi nhà một nét quyến rũ khó tả.","Chúng tôi đã thảo luận về chủ nghĩa bảo hộ thương mại sau khi giá giày nhập khẩu trở nên đắt đỏ hơn."]'::jsonb, 1, 'The busy harbour brought prosperity to our town. → Cảng biển tấp nập đã mang lại sự thịnh vượng cho thị trấn của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_7', 'en-c1-42', NULL, 'comprehensive_test', 'listening', 'exorbitant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dò tìm; khảo sát; điều tra sâu","cắt cổ, đắt cắt cổ; quá mức, cao vô lý","phân biệt; nhận biết sự khác nhau","sự khấu hao; sự sụt giảm giá trị"]'::jsonb, 1, 'exorbitant (/ɪɡˈzɔːrbɪtənt/) → cắt cổ, đắt cắt cổ; quá mức, cao vô lý', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_8', 'en-c1-42', NULL, 'comprehensive_test', 'listening', 'Buying another silk coat seemed extravagant on her budget.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc mua thêm một chiếc áo khoác lụa có vẻ vượt quá ngân sách và quá xa hoa đối với cô ấy.","Nông dân địa phương cho biết hàng nhập khẩu giá rẻ chính là bằng chứng của hành vi bán phá giá.","Miễn phí vận chuyển là động lực vừa đủ để tôi quyết định đặt mua chiếc ghế sofa đó.","Cảng biển tấp nập đã mang lại sự thịnh vượng cho thị trấn của chúng tôi."]'::jsonb, 0, 'Buying another silk coat seemed extravagant on her budget. → Việc mua thêm một chiếc áo khoác lụa có vẻ vượt quá ngân sách và quá xa hoa đối với cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_9', 'en-c1-42', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to make something operate or spread across the world”?', '["globalize","inducement","protectionism","sterling"]'::jsonb, 0, 'globalize (/ˈɡloʊbəlaɪz/) → toản cầu hóa; làm cho mang tính toàn cầu', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_10', 'en-c1-42', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The state of being economically successful and financially secure.”?', '["prosperity","reexport","franchise","utility"]'::jsonb, 0, 'prosperity (/prɑːˈsperəti/) → sự thịnh vượng; sự phát đạt, sự giàu có', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_11', 'en-c1-42', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Much higher in price or cost than is reasonable.”?', '["exorbitant","lag","subsidy","protectionism"]'::jsonb, 0, 'exorbitant (/ɪɡˈzɔːrbɪtənt/) → cắt cổ, đắt cắt cổ; quá mức, cao vô lý', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_12', 'en-c1-42', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Spending or costing much more money than necessary.”?', '["dumping","sterling","subsidy","extravagant"]'::jsonb, 3, 'extravagant (/ɪkˈstrævəɡənt/) → xa hoa; phung phí; đắt đỏ', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_13', 'en-c1-42', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Government policies restricting imports to protect domestic businesses from foreign competition.”?', '["protectionism","globalize","prosperity","slowdown"]'::jsonb, 0, 'protectionism (/prəˈtekʃənɪzəm/) → chủ nghĩa bảo hộ mậu dịch; chính sách bảo hộ', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
