INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_18', 'en-c1-42', NULL, 'comprehensive_test', 'reading', NULL, 'A prolonged drought can cripple agricultural production, reducing rural incomes and increasing food prices across the country.', 'Dựa vào câu trên, từ “cripple” có nghĩa phù hợp nhất là gì?', '["vận tốc; tốc độ","làm tê liệt; tàn phá năng lực hoạt động","đào, khoét, khai đào","hiểu; giải thích; suy diễn"]'::jsonb, 1, 'cripple: làm tê liệt; tàn phá năng lực hoạt động; làm thương tật nghiêm trọng; làm tàn phế. Dịch cả câu: Hạn hán kéo dài có thể giáng đòn nặng nề vào sản xuất nông nghiệp, làm giảm thu nhập ở nông thôn và đẩy giá thực phẩm tăng cao trên toàn quốc.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_19', 'en-c1-42', NULL, 'comprehensive_test', 'reading', NULL, 'Companies must account for accrued expenses to provide an accurate picture of their financial position at year end.', 'Dựa vào câu trên, từ “accrued” có nghĩa phù hợp nhất là gì?', '["được tích lũy theo thời gian (đặc biệt là về mặt tài chính); dồn tích","sự bất trung; sự phản bội","thuộc bậc đại học; thuộc giáo dục đại học","vết màu phớt; chút ít (màu sắc, cảm xúc)"]'::jsonb, 0, 'accrued: được tích lũy theo thời gian (đặc biệt là về mặt tài chính); dồn tích. Dịch cả câu: Các công ty phải hạch toán các khoản chi phí dồn tích để phản ánh chính xác tình hình tài chính của họ vào cuối năm.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_20', 'en-c1-42', NULL, 'comprehensive_test', 'reading', NULL, 'Volatile food prices make it difficult for low-income households to plan their spending and maintain a balanced diet.', 'Dựa vào câu trên, từ “volatile” có nghĩa phù hợp nhất là gì?', '["cơ hoành; hoành cách màng","thay đổi thất thường; dễ biến động","tác giả viết tản văn; nhà văn chuyên viết tiểu luận","than van; tiếc nuối; thương tiếc"]'::jsonb, 1, 'volatile: thay đổi thất thường; dễ biến động; dễ nổi giận; dễ thay đổi cảm xúc; dễ bay hơi. Dịch cả câu: Giá thực phẩm biến động thất thường khiến các hộ gia đình thu nhập thấp khó lập kế hoạch chi tiêu và duy trì chế độ ăn uống cân bằng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_21', 'en-c1-42', NULL, 'comprehensive_test', 'reading', NULL, 'When a country''s currency depreciates, imported goods become more expensive, potentially increasing the cost of living.', 'Dựa vào câu trên, từ “depreciate” có nghĩa phù hợp nhất là gì?', '["mức tiêu chuẩn; mức bình thường","làm cho sinh động; làm cho sôi nổi","mất giá; giảm giá trị; khấu hao tài sản","thành thạo; giỏi; khéo léo"]'::jsonb, 2, 'depreciate: mất giá; giảm giá trị; khấu hao tài sản. Dịch cả câu: Khi đồng tiền của một quốc gia mất giá, hàng hóa nhập khẩu trở nên đắt đỏ hơn, có khả năng làm tăng chi phí sinh hoạt.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_22', 'en-c1-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tích lũy dần; thu về dần theo thời gian”', '["frantic","accrue","patron","tumour"]'::jsonb, 1, 'tích lũy dần; thu về dần theo thời gian → accrue (/əˈkruː/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_23', 'en-c1-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự xúi giục; động lực khuyến khích”', '["encircle","spatial","acquisition","inducement"]'::jsonb, 3, 'sự xúi giục; động lực khuyến khích → inducement (/ɪnˈduːsmənt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_42_24', 'en-c1-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vô hình; phi vật chất; khó đo lường”', '["stagger","intangible","permanence","brandy"]'::jsonb, 1, 'vô hình; phi vật chất; khó đo lường → intangible (/ɪnˈtændʒəbl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-43', 'en', 'Bài 43: Kinh tế & Tài chính (3) - CEFR C1', 'CEFR C1', 'C1 · Kinh tế', '25 từ vựng Tiếng Anh CEFR C1 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5043, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_constraint', 'en-c1-43', 'constraint', '/kənˈstreɪnt/', 'C1', 'sự hạn chế; yếu tố hạn chế; sự gò bó; sự kiềm chế', 'n.', 'constrain (v.), constrained (adj.), unconstrained (adj.)', 'Đồng nghĩa: restriction, limitation', 'Thường dùng ở số hạng số nhiều constraints; từ đi kèm chỉ sự hạn chế đối với cái gì dùng giới từ on.', 'Our main constraint is the size of the kitchen.', NULL, 'Hạn chế lớn nhất của chúng tôi là kích thước của nhà bếp.', '{"wordId":"constraint","ukIpa":"/kənˈstreɪnt/","usIpa":"/kənˈstreɪnt/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Something that limits what you can do.","vi":"sự hạn chế; yếu tố hạn chế"},{"pos":"n.","en":"Control that prevents free or natural behaviour.","vi":"sự gò bó; sự kiềm chế"}],"examples":[{"en":"Our main constraint is the size of the kitchen.","vi":"Hạn chế lớn nhất của chúng tôi là kích thước của nhà bếp.","audioKind":"ex"},{"en":"Financial constraints prevent many local authorities from investing adequately in reliable public transport.","vi":"Những ràng buộc tài chính khiến nhiều nhà chức trách địa phương không thể đầu tư thỏa đáng vào hệ thống giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"time constraints","vi":"thời gian hạn hẹp"},{"en":"financial constraints","vi":"hạn chế về tài chính"},{"en":"a constraint on growth","vi":"rào cản đối với sự tăng trưởng"},{"en":"within budget constraints","vi":"trong giới hạn ngân sách"}],"wordFamily":["constrain (v.)","constrained (adj.)","unconstrained (adj.)"],"synonyms":["restriction","limitation"],"antonyms":[],"tipVi":"Thường dùng ở số hạng số nhiều constraints; từ đi kèm chỉ sự hạn chế đối với cái gì dùng giới từ on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quota', 'en-c1-43', 'quota', '/ˈkwoʊtə/', 'C1', 'hạn ngạch; chỉ tiêu; định mức', 'n.', NULL, NULL, 'Cả hạn ngạch (được phép tối đa) và chỉ tiêu (cần phải đạt được) đều dùng từ quota.', 'Our team reached its monthly sales quota yesterday afternoon.', NULL, 'Đội của chúng tôi đã hoàn thành chỉ tiêu doanh số bán hàng trong tháng vào chiều hôm qua.', '{"wordId":"quota","ukIpa":"/ˈkwəʊtə/","usIpa":"/ˈkwoʊtə/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"an officially fixed amount allowed, required, or assigned","vi":"hạn ngạch; chỉ tiêu; định mức"}],"examples":[{"en":"Our team reached its monthly sales quota yesterday afternoon.","vi":"Đội của chúng tôi đã hoàn thành chỉ tiêu doanh số bán hàng trong tháng vào chiều hôm qua.","audioKind":"ex"},{"en":"Fishing quotas can protect marine populations, provided that governments monitor catches and enforce the limits consistently.","vi":"Hạn ngạch đánh bắt có thể bảo vệ các quần thể sinh vật biển, miễn là chính phủ theo dõi sản lượng đánh bắt và thực thi nghiêm ngặt các giới hạn.","audioKind":"ex2"}],"collocations":[{"en":"an import quota","vi":"hạn ngạch nhập khẩu"},{"en":"a fishing quota","vi":"hạn ngạch đánh bắt cá"},{"en":"meet a quota","vi":"hoàn thành chỉ tiêu"},{"en":"impose a quota","vi":"áp đặt hạn ngạch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cả hạn ngạch (được phép tối đa) và chỉ tiêu (cần phải đạt được) đều dùng từ quota.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solvent', 'en-c1-43', 'solvent', '/ˈsɑːlvənt/', 'C1', 'có khả năng chi trả; có khả năng thanh toán; chất hòa tan; dung môi', 'adj.', 'solvency (n.), insolvent (adj.), insolvency (n.)', 'Trái nghĩa: insolvent', 'Tính từ solvent chỉ khả năng trả nợ, không đồng nghĩa với việc có lãi; danh từ chỉ dung môi hóa học.', 'Careful budgeting kept our small shop solvent this year.', NULL, 'Việc lập ngân sách cẩn thận đã giúp cửa hàng nhỏ của chúng tôi duy trì khả năng thanh toán trong năm nay.', '{"wordId":"solvent","ukIpa":"/ˈsɒlvənt/","usIpa":"/ˈsɑːlvənt/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"Able to pay all the money that is owed.","vi":"có khả năng chi trả; có khả năng thanh toán"},{"pos":"n.","en":"A substance, usually liquid, that dissolves another substance.","vi":"chất hòa tan; dung môi"}],"examples":[{"en":"Careful budgeting kept our small shop solvent this year.","vi":"Việc lập ngân sách cẩn thận đã giúp cửa hàng nhỏ của chúng tôi duy trì khả năng thanh toán trong năm nay.","audioKind":"ex"},{"en":"Businesses must remain solvent during economic downturns while continuing to meet their obligations to employees and suppliers.","vi":"Các doanh nghiệp phải duy trì khả năng thanh toán trong thời kỳ suy thoái kinh tế đồng thời tiếp tục thực hiện nghĩa vụ đối với nhân viên và nhà cung cấp.","audioKind":"ex2"}],"collocations":[{"en":"remain solvent","vi":"duy trì khả năng thanh toán"},{"en":"a solvent company","vi":"một công ty có khả năng thanh toán"},{"en":"an organic solvent","vi":"dung môi hữu cơ"},{"en":"a powerful solvent","vi":"dung môi mạnh"}],"wordFamily":["solvency (n.)","insolvent (adj.)","insolvency (n.)"],"synonyms":[],"antonyms":["insolvent"],"tipVi":"Tính từ solvent chỉ khả năng trả nợ, không đồng nghĩa với việc có lãi; danh từ chỉ dung môi hóa học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fluctuation', 'en-c1-43', 'fluctuation', '/ˌflʌktʃuˈeɪʃən/', 'C1', 'sự biến động; sự dao động', 'n.', 'fluctuate (v.)', 'Đồng nghĩa: variation · Trái nghĩa: stability', 'Thường dùng cấu trúc fluctuations in kết hợp với các chỉ số thay đổi như prices.', 'A sudden temperature fluctuation made the shower briefly cold.', NULL, 'Sự biến động nhiệt độ đột ngột làm cho nước vòi hoa sen ấm lạnh thất thường trong giây lát.', '{"wordId":"fluctuation","ukIpa":"/ˌflʌktʃuˈeɪʃən/","usIpa":"/ˌflʌktʃuˈeɪʃən/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"A change in level or amount, especially up and down.","vi":"sự biến động; sự dao động"}],"examples":[{"en":"A sudden temperature fluctuation made the shower briefly cold.","vi":"Sự biến động nhiệt độ đột ngột làm cho nước vòi hoa sen ấm lạnh thất thường trong giây lát.","audioKind":"ex"},{"en":"Frequent fluctuations in food prices make it difficult for low-income households to plan their monthly spending.","vi":"Giá thực phẩm biến động thường xuyên khiến các hộ gia đình thu nhập thấp khó lập kế hoạch chi tiêu hàng tháng.","audioKind":"ex2"}],"collocations":[{"en":"price fluctuations","vi":"price fluctuations -> biến động giá cả"},{"en":"seasonal fluctuations","vi":"seasonal fluctuations -> biến động theo mùa"},{"en":"fluctuations in demand","vi":"fluctuations in demand -> biến động nhu cầu"},{"en":"temperature fluctuations","vi":"temperature fluctuations -> biến động nhiệt độ"}],"wordFamily":["fluctuate (v.)"],"synonyms":["variation"],"antonyms":["stability"],"tipVi":"Thường dùng cấu trúc fluctuations in kết hợp với các chỉ số thay đổi như prices.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_macroeconomics', 'en-c1-43', 'macroeconomics', '/ˌmækroʊˌiːkəˈnɑːmɪks/', 'C1', 'kinh tế vĩ mô', 'n.', 'macroeconomic (adj.), macroeconomist (n.), economics (n.), economist (n.)', NULL, 'Mặc dù tận cùng bằng chữ s, khi chỉ một môn học thì dùng động từ số ít; cần phân biệt với kinh tế vi mô.', 'My sister studies macroeconomics at college every Tuesday.', NULL, 'Chị gái tôi học môn kinh tế vĩ mô ở trường đại học vào mỗi thứ Ba.', '{"wordId":"macroeconomics","ukIpa":"/ˌmækrəʊˌiːkəˈnɒmɪks/","usIpa":"/ˌmækroʊˌiːkəˈnɑːmɪks/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"The study of whole economies, including growth, inflation, and unemployment.","vi":"kinh tế vĩ mô"}],"examples":[{"en":"My sister studies macroeconomics at college every Tuesday.","vi":"Chị gái tôi học môn kinh tế vĩ mô ở trường đại học vào mỗi thứ Ba.","audioKind":"ex"},{"en":"An understanding of macroeconomics helps policymakers assess how interest rate changes might affect national employment.","vi":"Hiկ biết về kinh tế vĩ mô giúp các nhà hoạch định chính sách đánh giá sự thay đổi của lãi suất có thể tác động như thế nào đến việc làm trong nước.","audioKind":"ex2"}],"collocations":[{"en":"study macroeconomics","vi":"nghiên cứu kinh tế vĩ mô"},{"en":"macroeconomics course","vi":"khóa học kinh tế vĩ mô"},{"en":"principles of macroeconomics","vi":"nguyên lý kinh tế vĩ mô"}],"wordFamily":["macroeconomic (adj.)","macroeconomist (n.)","economics (n.)","economist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Mặc dù tận cùng bằng chữ s, khi chỉ một môn học thì dùng động từ số ít; cần phân biệt với kinh tế vi mô.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_freight', 'en-c1-43', 'freight', '/freɪt/', 'C1', 'hàng hóa; vận chuyển hàng hóa; cước phí vận chuyển; chở hàng', 'n.', NULL, 'Đồng nghĩa: cargo', 'Danh từ thường không đếm được; cargo chủ yếu chỉ hàng hóa chứ không bao gồm dịch vụ vận chuyển.', 'The train carried freight through the valley overnight.', NULL, 'Con tàu chở hàng chạy qua thung lũng suốt đêm.', '{"wordId":"freight","ukIpa":"/freɪt/","usIpa":"/freɪt/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"goods transported in bulk, or the transport of such goods","vi":"hàng hóa; vận chuyển hàng hóa"},{"pos":"n.","en":"the money charged for transporting goods","vi":"cước phí vận chuyển"},{"pos":"v.","en":"to transport goods by ship, aircraft, train, or truck","vi":"chở hàng; vận chuyển hàng hóa"}],"examples":[{"en":"The train carried freight through the valley overnight.","vi":"Con tàu chở hàng chạy qua thung lũng suốt đêm.","audioKind":"ex"},{"en":"Moving more freight by rail could reduce road congestion and lower emissions from heavy vehicles.","vi":"Việc chuyển nhiều hàng hóa hơn bằng đường sắt có thể làm giảm tình trạng ùn tắc giao thông đường bộ và cắt giảm lượng khí thải từ các phương tiện hạng nặng.","audioKind":"ex2"}],"collocations":[{"en":"air freight","vi":"vận chuyển hàng không"},{"en":"freight train","vi":"tàu chở hàng"},{"en":"freight charges","vi":"phí vận chuyển hàng hóa"},{"en":"rail freight","vi":"vận tải đường sắt"}],"wordFamily":[],"synonyms":["cargo"],"antonyms":[],"tipVi":"Danh từ thường không đếm được; cargo chủ yếu chỉ hàng hóa chứ không bao gồm dịch vụ vận chuyển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bonded', 'en-c1-43', 'bonded', '/ˈbɑːndɪd/', 'C1', 'được lưu kho bảo thuế; được giữ dưới sự kiểm soát hải quan cho đến khi đóng thuế nhập khẩu; gắn kết chặt chẽ về mặt cảm xúc hoặc được kết nối vững chắc với nhau', 'adj.', 'bond (n.), bond (v.), bonding (n.)', NULL, 'Thuật ngữ bảo thuế ở đây là hoãn nộp thuế nhập khẩu chứ không phải miễn thuế vĩnh viễn.', 'The imported coffee stays in a bonded warehouse nearby.', NULL, 'Cà phê nhập khẩu được lưu trữ tại một kho bảo thuế gần đó.', '{"wordId":"bonded","ukIpa":"/ˈbɒndɪd/","usIpa":"/ˈbɑːndɪd/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"Stored under customs control until import duties are paid","vi":"được lưu kho bảo thuế; được giữ dưới sự kiểm soát hải quan cho đến khi đóng thuế nhập khẩu"},{"pos":"adj.","en":"Closely connected emotionally or firmly joined together","vi":"gắn kết chặt chẽ về mặt cảm xúc hoặc được kết nối vững chắc với nhau"}],"examples":[{"en":"The imported coffee stays in a bonded warehouse nearby.","vi":"Cà phê nhập khẩu được lưu trữ tại một kho bảo thuế gần đó.","audioKind":"ex"},{"en":"Bonded warehouses allow importers to delay paying duties until goods enter the domestic market.","vi":"Các kho bảo thuế cho phép nhà nhập khẩu hoãn nộp thuế cho đến khi hàng hóa chính thức bước vào thị trường nội địa.","audioKind":"ex2"}],"collocations":[{"en":"bonded warehouse","vi":"kho bảo thuế"},{"en":"bonded goods","vi":"hàng hóa bảo thuế"},{"en":"bonded labour","vi":"lao động gạt nợ"}],"wordFamily":["bond (n.)","bond (v.)","bonding (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thuật ngữ bảo thuế ở đây là hoãn nộp thuế nhập khẩu chứ không phải miễn thuế vĩnh viễn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_industrialize', 'en-c1-43', 'industrialize', '/ɪnˈdʌstriəlaɪz/', 'C1', 'công nghiệp hóa; phát triển nền công nghiệp', 'v.', 'industry (n.), industrial (adj.), industrialization (n.)', 'Trái nghĩa: deindustrialize', 'Có thể dùng như ngoại động từ hoặc nội động từ; tiếng Anh-Anh còn viết là industrialise.', 'The town industrialized rapidly after the railway opened.', NULL, 'Thị trấn đã công nghiệp hóa một cách nhanh chóng sau khi tuyến đường sắt đi vào hoạt động.', '{"wordId":"industrialize","ukIpa":"/ɪnˈdʌstriəlaɪz/","usIpa":"/ɪnˈdʌstriəlaɪz/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"Develop industries and factories in a country or region","vi":"công nghiệp hóa; phát triển nền công nghiệp"}],"examples":[{"en":"The town industrialized rapidly after the railway opened.","vi":"Thị trấn đã công nghiệp hóa một cách nhanh chóng sau khi tuyến đường sắt đi vào hoạt động.","audioKind":"ex"},{"en":"As countries industrialize, governments must balance economic growth with environmental protection and workers'' welfare.","vi":"Khi các quốc gia tiến hành công nghiệp hóa, chính phủ phải cân bằng giữa tăng trưởng kinh tế với bảo vệ môi trường và phúc lợi của người lao động.","audioKind":"ex2"}],"collocations":[{"en":"industrialize rapidly","vi":"công nghiệp hóa nhanh chóng"},{"en":"a highly industrialized country","vi":"quốc gia có nền công nghiệp phát triển cao"},{"en":"newly industrialized economies","vi":"các nền kinh tế mới nổi về công nghiệp"}],"wordFamily":["industry (n.)","industrial (adj.)","industrialization (n.)"],"synonyms":[],"antonyms":["deindustrialize"],"tipVi":"Có thể dùng như ngoại động từ hoặc nội động từ; tiếng Anh-Anh còn viết là industrialise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monopoly', 'en-c1-43', 'monopoly', '/məˈnɑːpəli/', 'C1', 'sự độc quyền (chiếm giữ toàn bộ thị trường hoặc sở hữu độc quyền cái gì đó); doanh nghiệp độc quyền (công ty độc quyền cung cấp một sản phẩm hoặc dịch vụ)', 'n.', 'monopolise (v.), monopolist (n.), monopolistic (adj.)', 'Trái nghĩa: competition', 'Khi diễn tả việc nắm độc quyền trong một lĩnh vực nào đó, thường đi với cấu trúc monopoly on.', 'One company has a monopoly on our island''s ferry services.', NULL, 'Một công ty đang nắm độc quyền dịch vụ phà trên hòn đảo của chúng tôi.', '{"wordId":"monopoly","ukIpa":"/məˈnɒpəli/","usIpa":"/məˈnɑːpəli/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"complete control of a market or exclusive possession of something","vi":"sự độc quyền (chiếm giữ toàn bộ thị trường hoặc sở hữu độc quyền cái gì đó)"},{"pos":"n.","en":"a business that exclusively supplies a product or service","vi":"doanh nghiệp độc quyền (công ty độc quyền cung cấp một sản phẩm hoặc dịch vụ)"}],"examples":[{"en":"One company has a monopoly on our island''s ferry services.","vi":"Một công ty đang nắm độc quyền dịch vụ phà trên hòn đảo của chúng tôi.","audioKind":"ex"},{"en":"Without effective regulation, a monopoly can raise prices and leave consumers with few alternatives.","vi":"Nếu thiếu sự quản lý hiệu quả, một doanh nghiệp độc quyền có thể đẩy giá lên cao và khiến người tiêu dùng có rất ít sự lựa chọn thay thế.","audioKind":"ex2"}],"collocations":[{"en":"have a monopoly on","vi":"nắm độc quyền về"},{"en":"break a monopoly","vi":"phá vỡ thế độc quyền"},{"en":"state monopoly","vi":"sự độc quyền nhà nước"}],"wordFamily":["monopolise (v.)","monopolist (n.)","monopolistic (adj.)"],"synonyms":[],"antonyms":["competition"],"tipVi":"Khi diễn tả việc nắm độc quyền trong một lĩnh vực nào đó, thường đi với cấu trúc monopoly on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indebtedness', 'en-c1-43', 'indebtedness', '/ɪnˈdetɪdnəs/', 'C1', 'tình trạng nợ nần; tổng số tiền đang nợ; lòng biết ơn; sự mang ơn', 'n.', 'indebted (adj.), debt (n.), debtor (n.)', NULL, 'Có thể chỉ cả nghĩa nợ tiền hoặc lòng biết ơn; chữ b trong từ này không phát âm.', 'Their growing indebtedness forced them to sell the car.', NULL, 'Gánh nặng nợ nần ngày càng tăng buộc họ phải bán chiếc ô tô đi.', '{"wordId":"indebtedness","ukIpa":"/ɪnˈdetɪdnəs/","usIpa":"/ɪnˈdetɪdnəs/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"The state of owing money, or the amount owed.","vi":"tình trạng nợ nần; tổng số tiền đang nợ"},{"pos":"n.","en":"A feeling of gratitude for help received.","vi":"lòng biết ơn; sự mang ơn"}],"examples":[{"en":"Their growing indebtedness forced them to sell the car.","vi":"Gánh nặng nợ nần ngày càng tăng buộc họ phải bán chiếc ô tô đi.","audioKind":"ex"},{"en":"High household indebtedness can reduce consumer spending and make an economy more vulnerable to financial shocks.","vi":"Mức độ nợ nần cao của các hộ gia đình có thể làm giảm chi tiêu tiêu dùng và khiến nền kinh tế dễ bị tổn thương hơn trước các cú sốc tài chính.","audioKind":"ex2"}],"collocations":[{"en":"household indebtedness","vi":"nợ nần hộ gia đình"},{"en":"a sense of indebtedness","vi":"lòng biết ơn"},{"en":"indebtedness to someone","vi":"sự mang ơn đối với ai đó"}],"wordFamily":["indebted (adj.)","debt (n.)","debtor (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ cả nghĩa nợ tiền hoặc lòng biết ơn; chữ b trong từ này không phát âm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surpass', 'en-c1-43', 'surpass', '/sɚˈpæs/', 'C1', 'vượt qua; trội hơn; lớn hơn', 'v.', NULL, 'Đồng nghĩa: exceed, outdo', 'Là ngoại động từ, đi thẳng với tân ngữ, không dùng kèm với than.', 'Your homemade cakes surpass anything sold at our local bakery.', NULL, 'Những chiếc bánh tự làm của bạn vượt trội hơn bất kỳ loại nào được bán ở tiệm bánh địa phương của chúng tôi.', '{"wordId":"surpass","ukIpa":"/səˈpɑːs/","usIpa":"/sɚˈpæs/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"to be greater or better than someone or something","vi":"vượt qua; trội hơn; lớn hơn"}],"examples":[{"en":"Your homemade cakes surpass anything sold at our local bakery.","vi":"Những chiếc bánh tự làm của bạn vượt trội hơn bất kỳ loại nào được bán ở tiệm bánh địa phương của chúng tôi.","audioKind":"ex"},{"en":"Demand for renewable energy may surpass current forecasts as governments introduce stronger measures to reduce carbon emissions.","vi":"Nhu cầu về năng lượng tái tạo có thể vượt qua các dự báo hiện tại khi các chính phủ áp dụng các biện pháp mạnh mẽ hơn để giảm phát thải carbon.","audioKind":"ex2"}],"collocations":[{"en":"surpass expectations","vi":"vượt quá mong đợi"},{"en":"surpass a record","vi":"phá vỡ kỷ lục"},{"en":"surpass previous levels","vi":"vượt qua mức trước đây"}],"wordFamily":[],"synonyms":["exceed","outdo"],"antonyms":[],"tipVi":"Là ngoại động từ, đi thẳng với tân ngữ, không dùng kèm với than.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monopolize', 'en-c1-43', 'monopolize', '/məˈnɑːpəlaɪz/', 'C1', 'lũng đoạn; độc quyền; chiếm trọn; độc chiếm', 'v.', 'monopoly (n.), monopolist (n.), monopolistic (adj.), monopolization (n.)', 'Đồng nghĩa: dominate', 'Trong tiếng Anh Anh thường viết là monopolise; có thể dùng cho cả thị trường kinh tế lẫn sự chú ý.', 'Please don''t monopolize the conversation throughout dinner tonight.', NULL, 'Làm ơn đừng có chiếm hết phần trò chuyện trong suốt buổi tối nay.', '{"wordId":"monopolize","ukIpa":"/məˈnɒpəlaɪz/","usIpa":"/məˈnɑːpəlaɪz/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"to control an entire market or supply of something","vi":"lũng đoạn; độc quyền"},{"pos":"v.","en":"to use something so much that others cannot share it","vi":"chiếm trọn; độc chiếm"}],"examples":[{"en":"Please don''t monopolize the conversation throughout dinner tonight.","vi":"Làm ơn đừng có chiếm hết phần trò chuyện trong suốt buổi tối nay.","audioKind":"ex"},{"en":"When a few large firms monopolize essential services, consumers may face higher prices and fewer choices.","vi":"Khi một vài công ty lớn độc quyền các dịch vụ thiết yếu, người tiêu dùng có thể phải đối mặt với mức giá cao hơn và ít sự lựa chọn hơn.","audioKind":"ex2"}],"collocations":[{"en":"monopolize the market","vi":"độc quyền thị trường"},{"en":"monopolize the conversation","vi":"chiếm trọn cuộc trò chuyện"},{"en":"monopolize someone''s attention","vi":"thu hút toàn bộ sự chú ý của ai đó"}],"wordFamily":["monopoly (n.)","monopolist (n.)","monopolistic (adj.)","monopolization (n.)"],"synonyms":["dominate"],"antonyms":[],"tipVi":"Trong tiếng Anh Anh thường viết là monopolise; có thể dùng cho cả thị trường kinh tế lẫn sự chú ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_liability', 'en-c1-43', 'liability', '/ˌlaɪəˈbɪləti/', 'C1', 'trách nhiệm pháp lý (đặc biệt đối với thiệt hại hoặc tổn thất); khoản nợ, công nợ phải trả; gánh nặng, điều gây bất lợi, người gây phiền toái', 'n.', 'liable (adj.)', NULL, 'Nghĩa trách nhiệm thường không đếm được; nghĩa nợ phải trả thường dùng dạng số nhiều liabilities.', 'Our insurance covers liability for damage to neighbouring homes.', NULL, 'Bảo hiểm của chúng tôi chi trả trách nhiệm bồi thường thiệt hại cho nhà của hàng xóm.', '{"wordId":"liability","ukIpa":"/ˌlaɪəˈbɪləti/","usIpa":"/ˌlaɪəˈbɪləti/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Legal responsibility for something, especially damage or loss.","vi":"trách nhiệm pháp lý (đặc biệt đối với thiệt hại hoặc tổn thất)"},{"pos":"n.","en":"Money owed by a person or organisation.","vi":"khoản nợ, công nợ phải trả"},{"pos":"n.","en":"Someone or something that creates problems or disadvantages.","vi":"gánh nặng, điều gây bất lợi, người gây phiền toái"}],"examples":[{"en":"Our insurance covers liability for damage to neighbouring homes.","vi":"Bảo hiểm của chúng tôi chi trả trách nhiệm bồi thường thiệt hại cho nhà của hàng xóm.","audioKind":"ex"},{"en":"Clear rules on legal liability encourage companies to take greater responsibility for the safety of their products.","vi":"Các quy định rõ ràng về trách nhiệm pháp lý khuyến khích các công ty nâng cao trách nhiệm đối với sự an toàn của sản phẩm họ làm ra.","audioKind":"ex2"}],"collocations":[{"en":"legal liability","vi":"trách nhiệm pháp lý"},{"en":"accept liability","vi":"nhận trách nhiệm"},{"en":"limited liability","vi":"trách nhiệm hữu hạn"},{"en":"assets and liabilities","vi":"tài sản và nợ phải trả"}],"wordFamily":["liable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa trách nhiệm thường không đếm được; nghĩa nợ phải trả thường dùng dạng số nhiều liabilities.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_augment', 'en-c1-43', 'augment', '/ɔːɡˈment/', 'C1', 'làm tăng lên; gia tăng; mở rộng', 'v.', 'augmentation (n.), augmented (adj.)', 'Đồng nghĩa: increase, expand, supplement · Trái nghĩa: reduce, diminish', 'Từ trang trọng, thường đóng vai trò là ngoại động từ, nhấn mạnh việc tăng lên thông qua việc bổ sung thêm.', 'She sells homemade jam to augment her income.', NULL, 'Cô ấy bán mứt tự làm để tăng thêm thu nhập.', '{"wordId":"augment","ukIpa":"/ɔːɡˈment/","usIpa":"/ɔːɡˈment/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"To increase something by adding to it.","vi":"làm tăng lên; gia tăng; mở rộng"}],"examples":[{"en":"She sells homemade jam to augment her income.","vi":"Cô ấy bán mứt tự làm để tăng thêm thu nhập.","audioKind":"ex"},{"en":"Digital resources can augment classroom teaching, but they should not replace meaningful interaction between teachers and students.","vi":"Các nguồn tài nguyên kỹ thuật số có thể tăng cường hiệu quả giảng dạy trên lớp, nhưng chúng không nên thay thế sự tương tác có ý nghĩa giữa giáo viên và học sinh.","audioKind":"ex2"}],"collocations":[{"en":"augment income","vi":"tăng thu nhập"},{"en":"augment existing resources","vi":"bổ sung các nguồn lực hiện có"},{"en":"augment capacity","vi":"nâng cao năng lực"}],"wordFamily":["augmentation (n.)","augmented (adj.)"],"synonyms":["increase","expand","supplement"],"antonyms":["reduce","diminish"],"tipVi":"Từ trang trọng, thường đóng vai trò là ngoại động từ, nhấn mạnh việc tăng lên thông qua việc bổ sung thêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bottom-line', 'en-c1-43', 'bottom-line', '/ˌbɑːtəm ˈlaɪn/', 'C1', 'thuộc về lợi nhuận cuối cùng; liên quan đến kết quả tài chính cốt lõi', 'adj.', NULL, NULL, 'Dạng có dấu gạch nối thường làm định ngữ; danh từ viết là bottom line.', 'The owner discussed bottom-line results with her accountant.', NULL, 'Chủ cửa hàng đã thảo luận về kết quả lợi nhuận ròng với kế toán của mình.', '{"wordId":"bottom-line","ukIpa":"/ˌbɒtəm ˈlaɪn/","usIpa":"/ˌbɑːtəm ˈlaɪn/","cefr":"C1","topic":"economy","senses":[{"pos":"adj.","en":"Relating to the final profit or financial outcome.","vi":"thuộc về lợi nhuận cuối cùng; liên quan đến kết quả tài chính cốt lõi"}],"examples":[{"en":"The owner discussed bottom-line results with her accountant.","vi":"Chủ cửa hàng đã thảo luận về kết quả lợi nhuận ròng với kế toán của mình.","audioKind":"ex"},{"en":"An excessive focus on bottom-line performance may discourage companies from investing in employee development.","vi":"Việc quá chú trọng vào hiệu quả lợi nhuận cuối cùng có thể khiến các công ty ngần ngại đầu tư vào việc phát triển nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"bottom-line results","vi":"kết quả lợi nhuận cuối cùng"},{"en":"bottom-line performance","vi":"hiệu quả tài chính cốt lõi"},{"en":"bottom-line impact","vi":"tác động đến lợi nhuận cuối cùng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng có dấu gạch nối thường làm định ngữ; danh từ viết là bottom line.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deficit', 'en-c1-43', 'deficit', '/ˈdefɪsɪt/', 'C1', 'thâm hụt; mức thâm hụt (chi tiêu vượt quá thu nhập); sự thiếu hụt; khoản thiếu hụt', 'n.', NULL, 'Đồng nghĩa: shortfall · Trái nghĩa: surplus', 'Dùng deficit cho thâm hụt/thiếu hụt tài chính, còn debt dùng cho nợ, hai từ này khác nhau.', 'Our club faces a deficit after buying new equipment.', NULL, 'Câu lạc bộ của chúng tôi đối mặt với tình trạng thâm hụt sau khi mua sắm trang thiết bị mới.', '{"wordId":"deficit","ukIpa":"/ˈdefɪsɪt/","usIpa":"/ˈdefɪsɪt/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"the amount by which spending exceeds income","vi":"thâm hụt; mức thâm hụt (chi tiêu vượt quá thu nhập)"},{"pos":"n.","en":"a shortage of something needed","vi":"sự thiếu hụt; khoản thiếu hụt"}],"examples":[{"en":"Our club faces a deficit after buying new equipment.","vi":"Câu lạc bộ của chúng tôi đối mặt với tình trạng thâm hụt sau khi mua sắm trang thiết bị mới.","audioKind":"ex"},{"en":"Governments may reduce a budget deficit by raising taxes, but this can slow economic growth.","vi":"Chính phủ có thể cắt giảm thâm hụt ngân sách bằng cách tăng thuế, nhưng điều này có thể làm chậm tăng trưởng kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"budget deficit","vi":"thâm hụt ngân sách"},{"en":"trade deficit","vi":"thâm hụt thương mại"},{"en":"reduce the deficit","vi":"giảm thâm hụt"}],"wordFamily":[],"synonyms":["shortfall"],"antonyms":["surplus"],"tipVi":"Dùng deficit cho thâm hụt/thiếu hụt tài chính, còn debt dùng cho nợ, hai từ này khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_importation', 'en-c1-43', 'importation', '/ˌɪmpɔːrˈteɪʃən/', 'C1', 'sự nhập khẩu; việc đưa hàng hóa từ nước ngoài vào trong nước', 'n.', 'import (v.), importer (n.), imported (adj.)', 'Trái nghĩa: exportation', 'Là từ mang tính trang trọng, thường là danh từ không đếm được và hay đi với cụm the importation of.', 'The importation of fresh fruit requires careful temperature control.', NULL, 'Việc nhập khẩu trái cây tươi đòi hỏi phải kiểm soát nhiệt độ nghiêm ngặt.', '{"wordId":"importation","ukIpa":"/ˌɪmpɔːˈteɪʃən/","usIpa":"/ˌɪmpɔːrˈteɪʃən/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"the process of bringing goods into a country from abroad","vi":"sự nhập khẩu; việc đưa hàng hóa từ nước ngoài vào trong nước"}],"examples":[{"en":"The importation of fresh fruit requires careful temperature control.","vi":"Việc nhập khẩu trái cây tươi đòi hỏi phải kiểm soát nhiệt độ nghiêm ngặt.","audioKind":"ex"},{"en":"Restrictions on the importation of agricultural products may protect local farmers but increase food prices for consumers.","vi":"Những hạn chế đối với việc nhập khẩu nông sản có thể bảo vệ nông dân nội địa nhưng lại làm tăng giá thực phẩm đối với người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"importation of goods","vi":"nhập khẩu hàng hóa"},{"en":"restrict importation","vi":"hạn chế nhập khẩu"},{"en":"illegal importation","vi":"nhập khẩu trái phép"}],"wordFamily":["import (v.)","importer (n.)","imported (adj.)"],"synonyms":[],"antonyms":["exportation"],"tipVi":"Là từ mang tính trang trọng, thường là danh từ không đếm được và hay đi với cụm the importation of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extravagance', 'en-c1-43', 'extravagance', '/ɪkˈstrævəɡəns/', 'C1', 'sự xa hoa; sự phung phí; tính vung tay quá trán; món đồ xa xỉ; hành động tiêu xỉu tốn kém', 'n.', 'extravagant (adj.), extravagantly (adv.)', 'Đồng nghĩa: lavishness · Trái nghĩa: frugality, thrift', 'Khi chỉ hành vi phung phí, từ này thường không đếm được; khi chỉ một món đồ hay sự hưởng thụ đắt đỏ, nó có thể đếm được.', 'Buying fresh flowers every week is my only extravagance.', NULL, 'Việc mua hoa tươi mỗi tuần là sự hưởng thụ xa hoa duy nhất của tôi.', '{"wordId":"extravagance","ukIpa":"/ɪkˈstrævəɡəns/","usIpa":"/ɪkˈstrævəɡəns/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Spending more money than is necessary or sensible.","vi":"sự xa hoa; sự phung phí; tính vung tay quá trán"},{"pos":"n.","en":"Something expensive bought or done for pleasure rather than necessity.","vi":"món đồ xa xỉ; hành động tiêu xỉu tốn kém"}],"examples":[{"en":"Buying fresh flowers every week is my only extravagance.","vi":"Việc mua hoa tươi mỗi tuần là sự hưởng thụ xa hoa duy nhất của tôi.","audioKind":"ex"},{"en":"Public criticism of government extravagance often increases when essential services face severe budget cuts.","vi":"Những lời chỉ trích công khai đối với sự lãng phí của chính phủ thường gia tăng khi các dịch vụ thiết yếu đối mặt với việc cắt giảm ngân sách nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"personal extravagance","vi":"sự tiêu xỉu cá nhân"},{"en":"an unnecessary extravagance","vi":"một sự xa xỉ không cần thiết"},{"en":"a taste for extravagance","vi":"sự ưa chuộng lối sống xa hoa"}],"wordFamily":["extravagant (adj.)","extravagantly (adv.)"],"synonyms":["lavishness"],"antonyms":["frugality","thrift"],"tipVi":"Khi chỉ hành vi phung phí, từ này thường không đếm được; khi chỉ một món đồ hay sự hưởng thụ đắt đỏ, nó có thể đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_par', 'en-c1-43', 'par', '/pɑːr/', 'C1', 'mức tiêu chuẩn; mức bình thường; mệnh giá; điểm chuẩn (trong môn đánh gôn)', 'n.', NULL, NULL, 'Cụm on a par with có nghĩa là ngang ngửa, không thua kém; below par dùng để chỉ tình trạng sức khỏe hoặc phong độ kém.', 'I''m feeling below par, so I''ll stay home tonight.', NULL, 'Tôi cảm thấy sức khỏe không được tốt lắm, nên tối nay tôi sẽ ở nhà.', '{"wordId":"par","ukIpa":"/pɑː/","usIpa":"/pɑːr/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"The usual or expected standard of quality or performance.","vi":"mức tiêu chuẩn; mức bình thường"},{"pos":"n.","en":"The stated value of a share or bond.","vi":"mệnh giá"},{"pos":"n.","en":"The expected strokes needed for a golf hole or course.","vi":"điểm chuẩn (trong môn đánh gôn)"}],"examples":[{"en":"I''m feeling below par, so I''ll stay home tonight.","vi":"Tôi cảm thấy sức khỏe không được tốt lắm, nên tối nay tôi sẽ ở nhà.","audioKind":"ex"},{"en":"Investment in teacher training could bring educational outcomes in disadvantaged areas up to par with wealthier districts.","vi":"Việc đầu tư vào đào tạo giáo viên có thể nâng cao chất lượng giáo dục ở các vùng khó khăn lên mức tương đương với các quận giàu có hơn.","audioKind":"ex2"}],"collocations":[{"en":"below par","vi":"dưới mức bình thường"},{"en":"on a par with","vi":"ngang ngửa với; không thua kém"},{"en":"at par","vi":"theo mệnh giá"},{"en":"par value","vi":"mệnh giá"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm on a par with có nghĩa là ngang ngửa, không thua kém; below par dùng để chỉ tình trạng sức khỏe hoặc phong độ kém.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incur', 'en-c1-43', 'incur', '/ɪnˈkɝː/', 'C1', 'gánh chịu; phát sinh (chi phí, tổn thất, nợ nần)', 'v.', NULL, NULL, 'Các dạng quá khứ và phân từ của từ này là incurred và incurring, đều được viết nhân đôi chữ cái r.', 'Late returns may incur an extra charge at this library.', NULL, 'Việc trả sách muộn có thể phát sinh thêm một khoản phí tại thư viện này.', '{"wordId":"incur","ukIpa":"/ɪnˈkɜː/","usIpa":"/ɪnˈkɝː/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"to experience costs or something unpleasant because of your actions","vi":"gánh chịu; phát sinh (chi phí, tổn thất, nợ nần)"}],"examples":[{"en":"Late returns may incur an extra charge at this library.","vi":"Việc trả sách muộn có thể phát sinh thêm một khoản phí tại thư viện này.","audioKind":"ex"},{"en":"Businesses may incur substantial costs when replacing outdated equipment, but modern technology can improve productivity over time.","vi":"Các doanh nghiệp có thể phải gánh chịu những chi phí đáng kể khi thay thế các thiết bị lỗi thời, nhưng công nghệ hiện đại có thể cải thiện năng suất theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"incur costs","vi":"phát sinh chi phí"},{"en":"incur losses","vi":"gánh chịu tổn thất"},{"en":"incur debt","vi":"mắc nợ"},{"en":"incur a penalty","vi":"gánh chịu hình phạt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Các dạng quá khứ và phân từ của từ này là incurred và incurring, đều được viết nhân đôi chữ cái r.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_competitiveness', 'en-c1-43', 'competitiveness', '/kəmˈpetətɪvnəs/', 'C1', 'khả năng cạnh tranh; tính hiếu thắng, sự cạnh tranh', 'n.', 'compete (v.), competitive (adj.), competition (n.), competitor (n.)', NULL, 'Danh từ không đếm được; có thể chỉ khả năng cạnh tranh trên thị trường hoặc tính hiếu thắng cá nhân.', 'Fresh ingredients help our bakery maintain its competitiveness locally.', NULL, 'Nguyên liệu tươi ngon giúp tiệm bánh của chúng tôi duy trì khả năng cạnh tranh tại địa phương.', '{"wordId":"competitiveness","ukIpa":"/kəmˈpetɪtɪvnəs/","usIpa":"/kəmˈpetətɪvnəs/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"The ability to succeed against others in a market or activity.","vi":"khả năng cạnh tranh"},{"pos":"n.","en":"A strong desire to win or outperform others.","vi":"tính hiếu thắng, sự cạnh tranh"}],"examples":[{"en":"Fresh ingredients help our bakery maintain its competitiveness locally.","vi":"Nguyên liệu tươi ngon giúp tiệm bánh của chúng tôi duy trì khả năng cạnh tranh tại địa phương.","audioKind":"ex"},{"en":"Investment in workforce training can improve national competitiveness by increasing productivity and encouraging innovation across industries.","vi":"Việc đầu tư đào tạo lực lượng lao động có thể nâng cao năng lực cạnh tranh quốc gia thông qua việc gia tăng năng suất và thúc đẩy đổi mới sáng tạo trên các ngành công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"international competitiveness","vi":"năng lực cạnh tranh quốc tế"},{"en":"enhance competitiveness","vi":"nâng cao năng lực cạnh tranh"},{"en":"price competitiveness","vi":"khả năng cạnh tranh về giá"},{"en":"economic competitiveness","vi":"năng lực cạnh tranh kinh tế"}],"wordFamily":["compete (v.)","competitive (adj.)","competition (n.)","competitor (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ không đếm được; có thể chỉ khả năng cạnh tranh trên thị trường hoặc tính hiếu thắng cá nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spur', 'en-c1-43', 'spur', '/spɝ/', 'C1', 'thúc đẩy; khích lệ; kích thích; sự khích lệ; động lực thúc đẩy; cái cựa ngựa', 'v.', NULL, 'Đồng nghĩa: stimulate, motivate, impetus · Trái nghĩa: discourage, hinder', 'Thường dùng cấu trúc spur sb to do; dạng quá khứ viết là spurred với hai chữ r.', 'Her friend''s encouragement spurred her to finish the race.', NULL, 'Sự cổ vũ từ người bạn đã thúc đẩy cô ấy hoàn thành cuộc đua.', '{"wordId":"spur","ukIpa":"/spɜː/","usIpa":"/spɝ/","cefr":"C1","topic":"economy","senses":[{"pos":"v.","en":"To encourage action or cause something to develop faster","vi":"thúc đẩy; khích lệ; kích thích"},{"pos":"n.","en":"Something that encourages action or further progress","vi":"sự khích lệ; động lực thúc đẩy"},{"pos":"n.","en":"A metal device on a rider''s boot for urging a horse","vi":"cái cựa ngựa"}],"examples":[{"en":"Her friend''s encouragement spurred her to finish the race.","vi":"Sự cổ vũ từ người bạn đã thúc đẩy cô ấy hoàn thành cuộc đua.","audioKind":"ex"},{"en":"Investment in reliable public transport can spur economic growth by connecting workers with a wider range of jobs.","vi":"Việc đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể thúc đẩy tăng trưởng kinh tế bằng cách kết nối người lao động với nhiều cơ hội việc làm hơn.","audioKind":"ex2"}],"collocations":[{"en":"spur economic growth","vi":"thúc đẩy tăng trưởng kinh tế"},{"en":"spur someone into action","vi":"thúc giục ai đó hành động"},{"en":"a spur to innovation","vi":"động lực cho sự đổi mới"},{"en":"on the spur of the moment","vi":"bất chợt; ngẫu hứng"}],"wordFamily":[],"synonyms":["stimulate","motivate","impetus"],"antonyms":["discourage","hinder"],"tipVi":"Thường dùng cấu trúc spur sb to do; dạng quá khứ viết là spurred với hai chữ r.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_futures', 'en-c1-43', 'futures', '/ˈfjuːtʃərz/', 'C1', 'hợp đồng tương lai; giao dịch kỳ hạn', 'n.', 'future (n.), future (adj.)', NULL, 'Nghĩa tài chính dùng ở dạng số nhiều; futures contract chỉ hợp đồng tương lai.', 'My cousin trades wheat futures from her home office.', NULL, 'Chị họ tôi giao dịch hợp đồng tương lai lúa mì từ văn phòng tại nhà của chị ấy.', '{"wordId":"futures","ukIpa":"/ˈfjuːtʃəz/","usIpa":"/ˈfjuːtʃərz/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Contracts to trade assets later at prices agreed now.","vi":"hợp đồng tương lai; giao dịch kỳ hạn"}],"examples":[{"en":"My cousin trades wheat futures from her home office.","vi":"Chị họ tôi giao dịch hợp đồng tương lai lúa mì từ văn phòng tại nhà của chị ấy.","audioKind":"ex"},{"en":"Farmers can use futures to protect themselves against falling crop prices, although these contracts also involve financial risks.","vi":"Nông dân có thể sử dụng hợp đồng tương lai để tự bảo vệ mình trước tình trạng giá nông sản sụt giảm, mặc dù các hợp đồng này cũng tiềm ẩn rủi ro tài chính.","audioKind":"ex2"}],"collocations":[{"en":"futures market","vi":"thị trường hợp đồng tương lai"},{"en":"futures contract","vi":"hợp đồng tương lai"},{"en":"trade futures","vi":"giao dịch hợp đồng tương lai"},{"en":"oil futures","vi":"hợp đồng tương lai dầu mỏ"}],"wordFamily":["future (n.)","future (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa tài chính dùng ở dạng số nhiều; futures contract chỉ hợp đồng tương lai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overpayment', 'en-c1-43', 'overpayment', '/ˌoʊvɚˈpeɪmənt/', 'C1', 'tiền trả thừa; sự trả quá mức', 'n.', 'overpay (v.), payment (n.), pay (v.)', 'Trái nghĩa: underpayment', 'Khoản tiền dùng giới từ of để dẫn dắt: an overpayment of wages.', 'The cashier returned my overpayment before I left.', NULL, 'Nhân viên thu ngân đã trả lại số tiền tôi đưa thừa trước khi tôi rời đi.', '{"wordId":"overpayment","ukIpa":"/ˌəʊvəˈpeɪmənt/","usIpa":"/ˌoʊvɚˈpeɪmənt/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Money paid beyond the amount owed, or paying too much","vi":"tiền trả thừa; sự trả quá mức"}],"examples":[{"en":"The cashier returned my overpayment before I left.","vi":"Nhân viên thu ngân đã trả lại số tiền tôi đưa thừa trước khi tôi rời đi.","audioKind":"ex"},{"en":"Clear payroll procedures can prevent accidental overpayment and reduce disputes between employers and their staff.","vi":"Quy trình trả lương minh bạch có thể ngăn ngừa tình trạng chi trả thừa do nhầm lẫn và giảm thiểu tranh chấp giữa người sử dụng lao động và nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"an overpayment of wages","vi":"số tiền lương trả thừa"},{"en":"recover an overpayment","vi":"thu hồi khoản tiền trả thừa"},{"en":"refund an overpayment","vi":"hoàn lại khoản tiền trả thừa"}],"wordFamily":["overpay (v.)","payment (n.)","pay (v.)"],"synonyms":[],"antonyms":["underpayment"],"tipVi":"Khoản tiền dùng giới từ of để dẫn dắt: an overpayment of wages.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rebate', 'en-c1-43', 'rebate', '/ˈriːbeɪt/', 'C1', 'tiền hoàn lại; tiền thoái lại; tiền hoàn thuế', 'n.', NULL, 'Đồng nghĩa: refund', 'rebate thường là tiền trả lại sau khi thanh toán, trong khi discount thường là giảm giá ngay tại thời điểm thanh toán.', 'We received a rebate after buying our new fridge.', NULL, 'Chúng tôi đã nhận được một khoản tiền hoàn lại sau khi mua chiếc tủ lạnh mới.', '{"wordId":"rebate","ukIpa":"/ˈriːbeɪt/","usIpa":"/ˈriːbeɪt/","cefr":"C1","topic":"economy","senses":[{"pos":"n.","en":"Money returned after you pay for something or pay tax","vi":"tiền hoàn lại; tiền thoái lại; tiền hoàn thuế"}],"examples":[{"en":"We received a rebate after buying our new fridge.","vi":"Chúng tôi đã nhận được một khoản tiền hoàn lại sau khi mua chiếc tủ lạnh mới.","audioKind":"ex"},{"en":"Governments can offer a tax rebate to encourage households to install insulation and reduce energy consumption.","vi":"Chính phủ có thể cung cấp các khoản hoàn thuế để khuyến khích các hộ gia đình lắp đặt vật liệu cách nhiệt và giảm mức tiêu thụ năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"a tax rebate","vi":"một khoản hoàn thuế"},{"en":"claim a rebate","vi":"yêu cầu hoàn tiền"},{"en":"receive a rebate","vi":"nhận tiền hoàn lại"},{"en":"offer a rebate","vi":"cung cấp ưu đãi hoàn tiền"}],"wordFamily":[],"synonyms":["refund"],"antonyms":[],"tipVi":"rebate thường là tiền trả lại sau khi thanh toán, trong khi discount thường là giảm giá ngay tại thời điểm thanh toán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_43_1', 'en-c1-43', 'Cách dùng “extravagance” (n.) — sự xa hoa; sự phung phí; tính vung tay quá trán', 'personal extravagance  ·  an unnecessary extravagance  ·  a taste for extravagance', 'Khi chỉ hành vi phung phí, từ này thường không đếm được; khi chỉ một món đồ hay sự hưởng thụ đắt đỏ, nó có thể đếm được.', 'Họ từ (Word Family): extravagant (adj.), extravagantly (adv.) | Đồng nghĩa: lavishness · Trái nghĩa: frugality, thrift', '[{"hanzi":"Buying fresh flowers every week is my only extravagance.","pinyin":"","meaning":"Việc mua hoa tươi mỗi tuần là sự hưởng thụ xa hoa duy nhất của tôi."},{"hanzi":"Public criticism of government extravagance often increases when essential services face severe budget cuts.","pinyin":"","meaning":"Những lời chỉ trích công khai đối với sự lãng phí của chính phủ thường gia tăng khi các dịch vụ thiết yếu đối mặt với việc cắt giảm ngân sách nghiêm trọng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_43_2', 'en-c1-43', 'Cách dùng “par” (n.) — mức tiêu chuẩn; mức bình thường', 'below par  ·  on a par with  ·  at par', 'Cụm on a par with có nghĩa là ngang ngửa, không thua kém; below par dùng để chỉ tình trạng sức khỏe hoặc phong độ kém.', NULL, '[{"hanzi":"I''m feeling below par, so I''ll stay home tonight.","pinyin":"","meaning":"Tôi cảm thấy sức khỏe không được tốt lắm, nên tối nay tôi sẽ ở nhà."},{"hanzi":"Investment in teacher training could bring educational outcomes in disadvantaged areas up to par with wealthier districts.","pinyin":"","meaning":"Việc đầu tư vào đào tạo giáo viên có thể nâng cao chất lượng giáo dục ở các vùng khó khăn lên mức tương đương với các quận giàu có hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_43_3', 'en-c1-43', 'Cách dùng “rebate” (n.) — tiền hoàn lại; tiền thoái lại; tiền hoàn thuế', 'a tax rebate  ·  claim a rebate  ·  receive a rebate', 'rebate thường là tiền trả lại sau khi thanh toán, trong khi discount thường là giảm giá ngay tại thời điểm thanh toán.', 'Đồng nghĩa: refund', '[{"hanzi":"We received a rebate after buying our new fridge.","pinyin":"","meaning":"Chúng tôi đã nhận được một khoản tiền hoàn lại sau khi mua chiếc tủ lạnh mới."},{"hanzi":"Governments can offer a tax rebate to encourage households to install insulation and reduce energy consumption.","pinyin":"","meaning":"Chính phủ có thể cung cấp các khoản hoàn thuế để khuyến khích các hộ gia đình lắp đặt vật liệu cách nhiệt và giảm mức tiêu thụ năng lượng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_43_4', 'en-c1-43', 'Cách dùng “augment” (v.) — làm tăng lên; gia tăng; mở rộng', 'augment income  ·  augment existing resources  ·  augment capacity', 'Từ trang trọng, thường đóng vai trò là ngoại động từ, nhấn mạnh việc tăng lên thông qua việc bổ sung thêm.', 'Họ từ (Word Family): augmentation (n.), augmented (adj.) | Đồng nghĩa: increase, expand, supplement · Trái nghĩa: reduce, diminish', '[{"hanzi":"She sells homemade jam to augment her income.","pinyin":"","meaning":"Cô ấy bán mứt tự làm để tăng thêm thu nhập."},{"hanzi":"Digital resources can augment classroom teaching, but they should not replace meaningful interaction between teachers and students.","pinyin":"","meaning":"Các nguồn tài nguyên kỹ thuật số có thể tăng cường hiệu quả giảng dạy trên lớp, nhưng chúng không nên thay thế sự tương tác có ý nghĩa giữa giáo viên và học sinh."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_43_1', 'en-c1-43', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_1_1', 'ten_c1_43_1', 'constraint', 'Our main constraint is the size of the kitchen.', 'Our main constraint is the size of the kitchen.', '/kənˈstreɪnt/', 'Hạn chế lớn nhất của chúng tôi là kích thước của nhà bếp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_1_2', 'ten_c1_43_1', 'quota', 'Our team reached its monthly sales quota yesterday afternoon.', 'Our team reached its monthly sales quota yesterday afternoon.', '/ˈkwoʊtə/', 'Đội của chúng tôi đã hoàn thành chỉ tiêu doanh số bán hàng trong tháng vào chiều hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_1_3', 'ten_c1_43_1', 'solvent', 'Careful budgeting kept our small shop solvent this year.', 'Careful budgeting kept our small shop solvent this year.', '/ˈsɑːlvənt/', 'Việc lập ngân sách cẩn thận đã giúp cửa hàng nhỏ của chúng tôi duy trì khả năng thanh toán trong năm nay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_1_4', 'ten_c1_43_1', 'fluctuation', 'A sudden temperature fluctuation made the shower briefly cold.', 'A sudden temperature fluctuation made the shower briefly cold.', '/ˌflʌktʃuˈeɪʃən/', 'Sự biến động nhiệt độ đột ngột làm cho nước vòi hoa sen ấm lạnh thất thường trong giây lát.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_1_5', 'ten_c1_43_1', 'macroeconomics', 'My sister studies macroeconomics at college every Tuesday.', 'My sister studies macroeconomics at college every Tuesday.', '/ˌmækroʊˌiːkəˈnɑːmɪks/', 'Chị gái tôi học môn kinh tế vĩ mô ở trường đại học vào mỗi thứ Ba.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_1_6', 'ten_c1_43_1', 'freight', 'The train carried freight through the valley overnight.', 'The train carried freight through the valley overnight.', '/freɪt/', 'Con tàu chở hàng chạy qua thung lũng suốt đêm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_1_7', 'ten_c1_43_1', 'bonded', 'The imported coffee stays in a bonded warehouse nearby.', 'The imported coffee stays in a bonded warehouse nearby.', '/ˈbɑːndɪd/', 'Cà phê nhập khẩu được lưu trữ tại một kho bảo thuế gần đó.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_1_8', 'ten_c1_43_1', 'industrialize', 'The town industrialized rapidly after the railway opened.', 'The town industrialized rapidly after the railway opened.', '/ɪnˈdʌstriəlaɪz/', 'Thị trấn đã công nghiệp hóa một cách nhanh chóng sau khi tuyến đường sắt đi vào hoạt động.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_43_1_1', 'en-c1-43', 'ten_c1_43_1', 'listening', 'listening', 'Our main constraint is the size of the kitchen.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cà phê nhập khẩu được lưu trữ tại một kho bảo thuế gần đó.","Hạn chế lớn nhất của chúng tôi là kích thước của nhà bếp.","Đội của chúng tôi đã hoàn thành chỉ tiêu doanh số bán hàng trong tháng vào chiều hôm qua.","Nhân viên thu ngân đã trả lại số tiền tôi đưa thừa trước khi tôi rời đi."]'::jsonb, 1, 'Our main constraint is the size of the kitchen. → Hạn chế lớn nhất của chúng tôi là kích thước của nhà bếp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_43_1_2', 'en-c1-43', 'ten_c1_43_1', 'listening', 'listening', 'Our team reached its monthly sales quota yesterday afternoon.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy bán mứt tự làm để tăng thêm thu nhập.","Sự biến động nhiệt độ đột ngột làm cho nước vòi hoa sen ấm lạnh thất thường trong giây lát.","Đội của chúng tôi đã hoàn thành chỉ tiêu doanh số bán hàng trong tháng vào chiều hôm qua.","Hạn chế lớn nhất của chúng tôi là kích thước của nhà bếp."]'::jsonb, 2, 'Our team reached its monthly sales quota yesterday afternoon. → Đội của chúng tôi đã hoàn thành chỉ tiêu doanh số bán hàng trong tháng vào chiều hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_43_1_3', 'en-c1-43', 'ten_c1_43_1', 'listening', 'listening', 'Careful budgeting kept our small shop solvent this year.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sự biến động nhiệt độ đột ngột làm cho nước vòi hoa sen ấm lạnh thất thường trong giây lát.","Chị họ tôi giao dịch hợp đồng tương lai lúa mì từ văn phòng tại nhà của chị ấy.","Việc mua hoa tươi mỗi tuần là sự hưởng thụ xa hoa duy nhất của tôi.","Việc lập ngân sách cẩn thận đã giúp cửa hàng nhỏ của chúng tôi duy trì khả năng thanh toán trong năm nay."]'::jsonb, 3, 'Careful budgeting kept our small shop solvent this year. → Việc lập ngân sách cẩn thận đã giúp cửa hàng nhỏ của chúng tôi duy trì khả năng thanh toán trong năm nay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_43_2', 'en-c1-43', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_2_1', 'ten_c1_43_2', 'constraint', 'Financial constraints prevent many local authorities from investing adequately in reliable public transport.', 'Financial constraints prevent many local authorities from investing adequately in reliable public transport.', '/kənˈstreɪnt/', 'Những ràng buộc tài chính khiến nhiều nhà chức trách địa phương không thể đầu tư thỏa đáng vào hệ thống giao thông công cộng đáng tin cậy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_2_2', 'ten_c1_43_2', 'quota', 'Fishing quotas can protect marine populations, provided that governments monitor catches and enforce the limits consistently.', 'Fishing quotas can protect marine populations, provided that governments monitor catches and enforce the limits consistently.', '/ˈkwoʊtə/', 'Hạn ngạch đánh bắt có thể bảo vệ các quần thể sinh vật biển, miễn là chính phủ theo dõi sản lượng đánh bắt và thực thi nghiêm ngặt các giới hạn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_2_3', 'ten_c1_43_2', 'solvent', 'Businesses must remain solvent during economic downturns while continuing to meet their obligations to employees and suppliers.', 'Businesses must remain solvent during economic downturns while continuing to meet their obligations to employees and suppliers.', '/ˈsɑːlvənt/', 'Các doanh nghiệp phải duy trì khả năng thanh toán trong thời kỳ suy thoái kinh tế đồng thời tiếp tục thực hiện nghĩa vụ đối với nhân viên và nhà cung cấp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_2_4', 'ten_c1_43_2', 'fluctuation', 'Frequent fluctuations in food prices make it difficult for low-income households to plan their monthly spending.', 'Frequent fluctuations in food prices make it difficult for low-income households to plan their monthly spending.', '/ˌflʌktʃuˈeɪʃən/', 'Giá thực phẩm biến động thường xuyên khiến các hộ gia đình thu nhập thấp khó lập kế hoạch chi tiêu hàng tháng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_2_5', 'ten_c1_43_2', 'macroeconomics', 'An understanding of macroeconomics helps policymakers assess how interest rate changes might affect national employment.', 'An understanding of macroeconomics helps policymakers assess how interest rate changes might affect national employment.', '/ˌmækroʊˌiːkəˈnɑːmɪks/', 'Hiկ biết về kinh tế vĩ mô giúp các nhà hoạch định chính sách đánh giá sự thay đổi của lãi suất có thể tác động như thế nào đến việc làm trong nước.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_43_2_6', 'ten_c1_43_2', 'freight', 'Moving more freight by rail could reduce road congestion and lower emissions from heavy vehicles.', 'Moving more freight by rail could reduce road congestion and lower emissions from heavy vehicles.', '/freɪt/', 'Việc chuyển nhiều hàng hóa hơn bằng đường sắt có thể làm giảm tình trạng ùn tắc giao thông đường bộ và cắt giảm lượng khí thải từ các phương tiện hạng nặng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_43_2_1', 'en-c1-43', 'ten_c1_43_2', 'listening', 'listening', 'Financial constraints prevent many local authorities from investing adequately in reliable public transport.', NULL, 'Trong câu vừa nghe, từ “constraint” mang nghĩa nào sau đây?', '["ân cần; hòa nhã; lịch thiệp","sự hạn chế; yếu tố hạn chế","phạm pháp; có hành vi lệch chuẩn xã hội","bờ vực; nguy cơ cận kề"]'::jsonb, 1, '“constraint” (/kənˈstreɪnt/): sự hạn chế; yếu tố hạn chế. Câu đầy đủ: Financial constraints prevent many local authorities from investing adequately in reliable public transport.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_43_2_2', 'en-c1-43', 'ten_c1_43_2', 'listening', 'listening', 'Fishing quotas can protect marine populations, provided that governments monitor catches and enforce the limits consistently.', NULL, 'Trong câu vừa nghe, từ “quota” mang nghĩa nào sau đây?', '["thân thiện; hòa nhã; dễ gần","hạn ngạch; chỉ tiêu; định mức","quân tốt (trong cờ vua)","sức gắn kết; sự đoàn kết"]'::jsonb, 1, '“quota” (/ˈkwoʊtə/): hạn ngạch; chỉ tiêu; định mức. Câu đầy đủ: Fishing quotas can protect marine populations, provided that governments monitor catches and enforce the limits consistently.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
