INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_1', 'en-c1-43', NULL, 'comprehensive_test', 'listening', 'constraint', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["loài cỏ mọc ở vùng nước có thân cứng; cây sậy, ống sậy","sự hạn chế; yếu tố hạn chế","thuộc về nguyên thủy; bản địa; thổ dân","ám ảnh; làm cho bận tâm lo nghĩ"]'::jsonb, 1, 'constraint (/kənˈstreɪnt/) → sự hạn chế; yếu tố hạn chế; sự gò bó; sự kiềm chế', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_2', 'en-c1-43', NULL, 'comprehensive_test', 'listening', 'Our team reached its monthly sales quota yesterday afternoon.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đội của chúng tôi đã hoàn thành chỉ tiêu doanh số bán hàng trong tháng vào chiều hôm qua.","Việc trả sách muộn có thể phát sinh thêm một khoản phí tại thư viện này.","Thị trấn đã công nghiệp hóa một cách nhanh chóng sau khi tuyến đường sắt đi vào hoạt động.","Con tàu chở hàng chạy qua thung lũng suốt đêm."]'::jsonb, 0, 'Our team reached its monthly sales quota yesterday afternoon. → Đội của chúng tôi đã hoàn thành chỉ tiêu doanh số bán hàng trong tháng vào chiều hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_3', 'en-c1-43', NULL, 'comprehensive_test', 'listening', 'solvent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chất polymer; hợp chất cao phân tử","quấy rầy; làm phiền; đeo bám","sự gắng sức; sự tiêu tốn sức lực hoặc trí lực","có khả năng chi trả; có khả năng thanh toán"]'::jsonb, 3, 'solvent (/ˈsɑːlvənt/) → có khả năng chi trả; có khả năng thanh toán; chất hòa tan; dung môi', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_4', 'en-c1-43', NULL, 'comprehensive_test', 'listening', 'A sudden temperature fluctuation made the shower briefly cold.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự biến động nhiệt độ đột ngột làm cho nước vòi hoa sen ấm lạnh thất thường trong giây lát.","Đội của chúng tôi đã hoàn thành chỉ tiêu doanh số bán hàng trong tháng vào chiều hôm qua.","Những chiếc bánh tự làm của bạn vượt trội hơn bất kỳ loại nào được bán ở tiệm bánh địa phương của chúng tôi.","Một công ty đang nắm độc quyền dịch vụ phà trên hòn đảo của chúng tôi."]'::jsonb, 0, 'A sudden temperature fluctuation made the shower briefly cold. → Sự biến động nhiệt độ đột ngột làm cho nước vòi hoa sen ấm lạnh thất thường trong giây lát.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_5', 'en-c1-43', NULL, 'comprehensive_test', 'listening', 'macroeconomics', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tù nhân; người đã bị kết án","sự suy thoái; sự xuống cấp; sự hư hại về chất lượng","kinh tế vĩ mô","tự phụ; tự mãn; khoa trương"]'::jsonb, 2, 'macroeconomics (/ˌmækroʊˌiːkəˈnɑːmɪks/) → kinh tế vĩ mô', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_6', 'en-c1-43', NULL, 'comprehensive_test', 'listening', 'The train carried freight through the valley overnight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con tàu chở hàng chạy qua thung lũng suốt đêm.","Những chiếc bánh tự làm của bạn vượt trội hơn bất kỳ loại nào được bán ở tiệm bánh địa phương của chúng tôi.","Gánh nặng nợ nần ngày càng tăng buộc họ phải bán chiếc ô tô đi.","Chị gái tôi học môn kinh tế vĩ mô ở trường đại học vào mỗi thứ Ba."]'::jsonb, 0, 'The train carried freight through the valley overnight. → Con tàu chở hàng chạy qua thung lũng suốt đêm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_7', 'en-c1-43', NULL, 'comprehensive_test', 'listening', 'bonded', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đánh lừa; lừa dối; khiến ai đó ảo tưởng","sự tổng hợp; sự gom lại","lang thang; đi lang thang; thả bộ","được lưu kho bảo thuế; được giữ dưới sự kiểm soát hải quan cho đến khi đóng thuế nhập khẩu"]'::jsonb, 3, 'bonded (/ˈbɑːndɪd/) → được lưu kho bảo thuế; được giữ dưới sự kiểm soát hải quan cho đến khi đóng thuế nhập khẩu; gắn kết chặt chẽ về mặt cảm xúc hoặc được kết nối vững chắc với nhau', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_8', 'en-c1-43', NULL, 'comprehensive_test', 'listening', 'The town industrialized rapidly after the railway opened.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đội của chúng tôi đã hoàn thành chỉ tiêu doanh số bán hàng trong tháng vào chiều hôm qua.","Sự cổ vũ từ người bạn đã thúc đẩy cô ấy hoàn thành cuộc đua.","Thị trấn đã công nghiệp hóa một cách nhanh chóng sau khi tuyến đường sắt đi vào hoạt động.","Việc mua hoa tươi mỗi tuần là sự hưởng thụ xa hoa duy nhất của tôi."]'::jsonb, 2, 'The town industrialized rapidly after the railway opened. → Thị trấn đã công nghiệp hóa một cách nhanh chóng sau khi tuyến đường sắt đi vào hoạt động.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
