INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_18', 'en-c1-43', NULL, 'comprehensive_test', 'reading', NULL, 'Financial constraints prevent many local authorities from investing adequately in reliable public transport.', 'Dựa vào câu trên, từ “constraint” có nghĩa phù hợp nhất là gì?', '["an-pe","sự hạn chế; yếu tố hạn chế","lật đổ; đánh đổ","sự tái phát; sự lặp lại"]'::jsonb, 1, 'constraint: sự hạn chế; yếu tố hạn chế; sự gò bó; sự kiềm chế. Dịch cả câu: Những ràng buộc tài chính khiến nhiều nhà chức trách địa phương không thể đầu tư thỏa đáng vào hệ thống giao thông công cộng đáng tin cậy.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_19', 'en-c1-43', NULL, 'comprehensive_test', 'reading', NULL, 'Fishing quotas can protect marine populations, provided that governments monitor catches and enforce the limits consistently.', 'Dựa vào câu trên, từ “quota” có nghĩa phù hợp nhất là gì?', '["tập hồ sơ năng lực; tập các tác phẩm tiêu biểu","hạn ngạch; chỉ tiêu; định mức","cay độc; sắc bén; làm tổn thương","nông dân nghèo; tá điền"]'::jsonb, 1, 'quota: hạn ngạch; chỉ tiêu; định mức. Dịch cả câu: Hạn ngạch đánh bắt có thể bảo vệ các quần thể sinh vật biển, miễn là chính phủ theo dõi sản lượng đánh bắt và thực thi nghiêm ngặt các giới hạn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_20', 'en-c1-43', NULL, 'comprehensive_test', 'reading', NULL, 'Businesses must remain solvent during economic downturns while continuing to meet their obligations to employees and suppliers.', 'Dựa vào câu trên, từ “solvent” có nghĩa phù hợp nhất là gì?', '["cái nêm; vật hình nêm","tiếp thu và lĩnh hội hoàn toàn thông tin hoặc ý tưởng mới","có khả năng chi trả; có khả năng thanh toán","nhà máy bia"]'::jsonb, 2, 'solvent: có khả năng chi trả; có khả năng thanh toán; chất hòa tan; dung môi. Dịch cả câu: Các doanh nghiệp phải duy trì khả năng thanh toán trong thời kỳ suy thoái kinh tế đồng thời tiếp tục thực hiện nghĩa vụ đối với nhân viên và nhà cung cấp.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_21', 'en-c1-43', NULL, 'comprehensive_test', 'reading', NULL, 'Frequent fluctuations in food prices make it difficult for low-income households to plan their monthly spending.', 'Dựa vào câu trên, từ “fluctuation” có nghĩa phù hợp nhất là gì?', '["sự biến động; sự dao động","cộc lốc; ngắn ngủi và thô lỗ","bán phá giá; hành vi bán phá giá","tài khéo léo; sự sáng tạo; sự tinh tế"]'::jsonb, 0, 'fluctuation: sự biến động; sự dao động. Dịch cả câu: Giá thực phẩm biến động thường xuyên khiến các hộ gia đình thu nhập thấp khó lập kế hoạch chi tiêu hàng tháng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_22', 'en-c1-43', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hợp đồng tương lai; giao dịch kỳ hạn”', '["futures","computation","saline","operational"]'::jsonb, 0, 'hợp đồng tương lai; giao dịch kỳ hạn → futures (/ˈfjuːtʃərz/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_23', 'en-c1-43', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiền trả thừa; sự trả quá mức”', '["overpayment","subsidize","intangible","exempt"]'::jsonb, 0, 'tiền trả thừa; sự trả quá mức → overpayment (/ˌoʊvɚˈpeɪmənt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_43_24', 'en-c1-43', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiền hoàn lại; tiền thoái lại; tiền hoàn thuế”', '["oxidize","inherent","rebate","haunt"]'::jsonb, 2, 'tiền hoàn lại; tiền thoái lại; tiền hoàn thuế → rebate (/ˈriːbeɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-44', 'en', 'Bài 44: Chính phủ & Pháp luật (1) - CEFR C1', 'CEFR C1', 'C1 · Chính phủ & Pháp luật', '24 từ vựng Tiếng Anh CEFR C1 chủ đề chính phủ & pháp luật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5044, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consul', 'en-c1-44', 'consul', '/ˈkɑːnsəl/', 'C1', 'lãnh sự (một quan chức ngoại giao ở nước ngoài giúp đỡ công dân và đại diện cho lợi ích quốc gia)', 'n.', 'consular (adj.), consulate (n.)', NULL, 'Consul là lãnh sự; consulate là lãnh sự quán, tránh nhầm lẫn.', 'The consul helped us after we lost our passports.', NULL, 'Viên lãnh sự đã giúp đỡ chúng tôi sau khi chúng tôi bị mất hộ chiếu.', '{"wordId":"consul","ukIpa":"/ˈkɒnsəl/","usIpa":"/ˈkɑːnsəl/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"An official abroad who assists citizens and represents national interests","vi":"lãnh sự (một quan chức ngoại giao ở nước ngoài giúp đỡ công dân và đại diện cho lợi ích quốc gia)"}],"examples":[{"en":"The consul helped us after we lost our passports.","vi":"Viên lãnh sự đã giúp đỡ chúng tôi sau khi chúng tôi bị mất hộ chiếu.","audioKind":"ex"},{"en":"A consul may support citizens facing difficulties overseas and help strengthen commercial links between countries.","vi":"Một lãnh sự có thể hỗ trợ công dân gặp khó khăn ở nước ngoài và giúp tăng cường mối quan hệ thương mại giữa các quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"consul general","vi":"tổng lãnh sự"},{"en":"honorary consul","vi":"lãnh sự danh dự"},{"en":"vice consul","vi":"phó lãnh sự"}],"wordFamily":["consular (adj.)","consulate (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Consul là lãnh sự; consulate là lãnh sự quán, tránh nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compliance', 'en-c1-44', 'compliance', '/kəmˈplaɪəns/', 'C1', 'sự tuân thủ; sự tuân theo', 'n.', 'comply (v.), compliant (adj.), non-compliance (n.)', 'Đồng nghĩa: adherence, conformity · Trái nghĩa: non-compliance', 'Thường là danh từ không đếm được; khi diễn đạt ý tuân thủ quy định nào đó, dùng compliance with.', 'The inspector checked our kitchen for compliance with hygiene rules.', NULL, 'Nhân viên thanh tra đã kiểm tra nhà bếp của chúng tôi để đảm bảo tuân thủ các quy định về vệ sinh.', '{"wordId":"compliance","ukIpa":"/kəmˈplaɪəns/","usIpa":"/kəmˈplaɪəns/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"the act of following a rule, law, or request","vi":"sự tuân thủ; sự tuân theo"}],"examples":[{"en":"The inspector checked our kitchen for compliance with hygiene rules.","vi":"Nhân viên thanh tra đã kiểm tra nhà bếp của chúng tôi để đảm bảo tuân thủ các quy định về vệ sinh.","audioKind":"ex"},{"en":"Regular inspections can improve compliance with environmental regulations and reduce pollution from industrial facilities.","vi":"Việc thanh tra thường xuyên có thể nâng cao mức độ tuân thủ các quy định về môi trường và giảm thiểu ô nhiễm từ các cơ sở công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"compliance with regulations","vi":"tuân thủ các quy định"},{"en":"ensure compliance","vi":"đảm bảo tuân thủ"},{"en":"in compliance with","vi":"tuân theo; chiếu theo"}],"wordFamily":["comply (v.)","compliant (adj.)","non-compliance (n.)"],"synonyms":["adherence","conformity"],"antonyms":["non-compliance"],"tipVi":"Thường là danh từ không đếm được; khi diễn đạt ý tuân thủ quy định nào đó, dùng compliance with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overthrow', 'en-c1-44', 'overthrow', '/ˌoʊvərˈθroʊ/', 'C1', 'lật đổ; đánh đổ; sự lật đổ; sự sụp đổ của chính quyền', 'v.', NULL, 'Đồng nghĩa: topple, oust', 'Dạng quá khứ là overthrew, phân từ hai là overthrown.', 'The film follows citizens who overthrow an unfair ruler.', NULL, 'Bộ phim xoay quanh những người dân đứng lên lật đổ một nhà cầm quyền bất công.', '{"wordId":"overthrow","ukIpa":"/ˌəʊvəˈθrəʊ/","usIpa":"/ˌoʊvərˈθroʊ/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"to remove a ruler or government from power","vi":"lật đổ; đánh đổ"},{"pos":"n.","en":"the removal of a ruler or government from power","vi":"sự lật đổ; sự sụp đổ của chính quyền"}],"examples":[{"en":"The film follows citizens who overthrow an unfair ruler.","vi":"Bộ phim xoay quanh những người dân đứng lên lật đổ một nhà cầm quyền bất công.","audioKind":"ex"},{"en":"Economic hardship can weaken public support for a government and encourage attempts to overthrow it.","vi":"Khó khăn kinh tế có thể làm suy yếu sự ủng hộ của công chúng đối với chính phủ và kích thích các nỗ lực lật đổ chính quyền đó.","audioKind":"ex2"}],"collocations":[{"en":"overthrow a government","vi":"lật đổ một chính phủ"},{"en":"overthrow a regime","vi":"lật đổ một chế độ"},{"en":"the overthrow of a ruler","vi":"sự lật đổ một nhà cầm quyền"}],"wordFamily":[],"synonyms":["topple","oust"],"antonyms":[],"tipVi":"Dạng quá khứ là overthrew, phân từ hai là overthrown.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_liable', 'en-c1-44', 'liable', '/ˈlaɪəbl/', 'C1', 'có khả năng xảy ra, dễ bị (đặc biệt là điều bất lợi); chịu trách nhiệm pháp lý (đặc biệt là về bồi thường thiệt hại hoặc thanh toán)', 'adj.', 'liability (n.)', NULL, '“Liable to” theo sau là động từ chỉ khả năng xảy ra; “liable for” chỉ trách nhiệm.', 'These old pipes are liable to burst in winter.', NULL, 'Những đường ống cũ này rất dễ bị vỡ vào mùa đông.', '{"wordId":"liable","ukIpa":"/ˈlaɪəbl/","usIpa":"/ˈlaɪəbl/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"Likely to experience something, especially something unpleasant.","vi":"có khả năng xảy ra, dễ bị (đặc biệt là điều bất lợi)"},{"pos":"adj.","en":"Legally responsible for something, especially damage or payment.","vi":"chịu trách nhiệm pháp lý (đặc biệt là về bồi thường thiệt hại hoặc thanh toán)"}],"examples":[{"en":"These old pipes are liable to burst in winter.","vi":"Những đường ống cũ này rất dễ bị vỡ vào mùa đông.","audioKind":"ex"},{"en":"Employers may be held liable for injuries caused by unsafe conditions in the workplace.","vi":"Người sử dụng lao động có thể phải chịu trách nhiệm pháp lý đối với các thương tích do điều kiện không an toàn tại nơi làm việc gây ra.","audioKind":"ex2"}],"collocations":[{"en":"liable to do something","vi":"có nguy cơ làm gì"},{"en":"liable for damages","vi":"chịu trách nhiệm bồi thường thiệt hại"},{"en":"be held liable","vi":"bị quy trách nhiệm pháp lý"}],"wordFamily":["liability (n.)"],"synonyms":[],"antonyms":[],"tipVi":"“Liable to” theo sau là động từ chỉ khả năng xảy ra; “liable for” chỉ trách nhiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_democrat', 'en-c1-44', 'democrat', '/ˈdeməkræt/', 'C1', 'người theo chủ nghĩa dân chủ; đảng viên hoặc người ủng hộ Đảng Dân chủ ở Mỹ', 'n.', 'democracy (n.), democratic (adj.), democratically (adv.), democratise (v.)', 'Trái nghĩa: autocrat', 'Chỉ người theo chủ nghĩa dân chủ nói chung dùng chữ thường; chỉ đảng viên Đảng Dân chủ Mỹ viết hoa chữ "Democrat".', 'As a democrat, she wants everyone to have a vote.', NULL, 'Là một người theo chủ nghĩa dân chủ, cô ấy muốn mọi người đều có quyền bỏ phiếu.', '{"wordId":"democrat","ukIpa":"/ˈdeməkræt/","usIpa":"/ˈdeməkræt/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"Someone who supports government based on the people''s choices","vi":"người theo chủ nghĩa dân chủ"},{"pos":"n.","en":"A member or supporter of the Democratic Party in America","vi":"đảng viên hoặc người ủng hộ Đảng Dân chủ ở Mỹ"}],"examples":[{"en":"As a democrat, she wants everyone to have a vote.","vi":"Là một người theo chủ nghĩa dân chủ, cô ấy muốn mọi người đều có quyền bỏ phiếu.","audioKind":"ex"},{"en":"A committed democrat should defend fair elections even when the results favour a competing political party.","vi":"Một người theo chủ nghĩa dân chủ tận tụy nên bảo vệ các cuộc bầu cử công bằng ngay cả khi kết quả nghiêng về một đảng phái chính trị đối lập.","audioKind":"ex2"}],"collocations":[{"en":"committed democrat","vi":"người theo chủ nghĩa dân chủ tận tụy"},{"en":"lifelong democrat","vi":"người ủng hộ Đảng Dân chủ lâu năm"},{"en":"liberal democrat","vi":"đảng viên Dân chủ tự do"}],"wordFamily":["democracy (n.)","democratic (adj.)","democratically (adv.)","democratise (v.)"],"synonyms":[],"antonyms":["autocrat"],"tipVi":"Chỉ người theo chủ nghĩa dân chủ nói chung dùng chữ thường; chỉ đảng viên Đảng Dân chủ Mỹ viết hoa chữ \"Democrat\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_designate', 'en-c1-44', 'designate', '/ˈdezɪɡneɪt/', 'C1', 'chỉ định; phân công; chỉ rõ; đặt tên', 'v.', 'designation (n.), designated (adj.)', 'Đồng nghĩa: appoint, assign', 'Cấu trúc designate A as B có nghĩa là chỉ định hoặc công nhận A là B.', 'We designated one cupboard for all our cleaning supplies.', NULL, 'Chúng tôi đã chọn một chiếc tủ để chuyên đựng các dụng cụ vệ sinh.', '{"wordId":"designate","ukIpa":"/ˈdezɪɡneɪt/","usIpa":"/ˈdezɪɡneɪt/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To officially choose someone or something for a particular purpose.","vi":"chỉ định; phân công"},{"pos":"v.","en":"To give something an official name or identifying description.","vi":"chỉ rõ; đặt tên"}],"examples":[{"en":"We designated one cupboard for all our cleaning supplies.","vi":"Chúng tôi đã chọn một chiếc tủ để chuyên đựng các dụng cụ vệ sinh.","audioKind":"ex"},{"en":"Local authorities should designate more urban land as protected green space to improve residents'' quality of life.","vi":"Chính quyền địa phương nên quy hoạch nhiều đất đô thị hơn thành không gian xanh được bảo vệ để cải thiện chất lượng cuộc sống của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"designate someone as","vi":"chỉ định ai làm gì"},{"en":"designate an area for","vi":"quy hoạch một khu vực cho"},{"en":"designated parking spaces","vi":"chỗ đậu xe được phân chia sẵn"}],"wordFamily":["designation (n.)","designated (adj.)"],"synonyms":["appoint","assign"],"antonyms":[],"tipVi":"Cấu trúc designate A as B có nghĩa là chỉ định hoặc công nhận A là B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enforce', 'en-c1-44', 'enforce', '/ɪnˈfɔːrs/', 'C1', 'thi hành; thực thi; bắt tuân theo', 'v.', 'enforcement (n.), enforceable (adj.), enforcer (n.)', 'Đồng nghĩa: implement', 'enforce đi sau với luật pháp hoặc quy định; còn buộc ai đó làm gì thì dùng force.', 'The pool staff enforce strict rules about running indoors.', NULL, 'Nhân viên hồ bơi thực thi nghiêm ngặt các quy định về việc không chạy nhảy trong nhà.', '{"wordId":"enforce","ukIpa":"/ɪnˈfɔːs/","usIpa":"/ɪnˈfɔːrs/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"Make sure that people obey a law or rule.","vi":"thi hành; thực thi; bắt tuân theo"}],"examples":[{"en":"The pool staff enforce strict rules about running indoors.","vi":"Nhân viên hồ bơi thực thi nghiêm ngặt các quy định về việc không chạy nhảy trong nhà.","audioKind":"ex"},{"en":"Governments must enforce environmental regulations consistently if they want industries to reduce pollution and protect public health.","vi":"Chính phủ phải thực thi nhất quán các quy định về môi trường nếu họ muốn các ngành công nghiệp giảm thiểu ô nhiễm và bảo vệ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"enforce the law","vi":"thực thi pháp luật"},{"en":"enforce regulations","vi":"thực thi các quy định"},{"en":"strictly enforce","vi":"thực thi nghiêm ngặt"}],"wordFamily":["enforcement (n.)","enforceable (adj.)","enforcer (n.)"],"synonyms":["implement"],"antonyms":[],"tipVi":"enforce đi sau với luật pháp hoặc quy định; còn buộc ai đó làm gì thì dùng force.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sanction', 'en-c1-44', 'sanction', '/ˈsæŋkʃən/', 'C1', 'sự trừng phạt; biện pháp trừng phạt; phê chuẩn; cho phép; áp dụng hình thức trừng phạt', 'n.', NULL, NULL, 'Có thể mang nghĩa là "trừng phạt" hoặc "phê chuẩn", mang nghĩa trái ngược nhau nên cần xem xét ngữ cảnh.', 'The club imposed a sanction for breaking its rules.', NULL, 'Câu lạc bộ đã đưa ra án phạt vì vi phạm quy định của họ.', '{"wordId":"sanction","ukIpa":"/ˈsæŋkʃən/","usIpa":"/ˈsæŋkʃən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"An official penalty intended to enforce rules or change behaviour.","vi":"sự trừng phạt; biện pháp trừng phạt"},{"pos":"v.","en":"To officially approve or permit an action.","vi":"phê chuẩn; cho phép"},{"pos":"v.","en":"To impose an official penalty on someone or something.","vi":"áp dụng hình thức trừng phạt"}],"examples":[{"en":"The club imposed a sanction for breaking its rules.","vi":"Câu lạc bộ đã đưa ra án phạt vì vi phạm quy định của họ.","audioKind":"ex"},{"en":"Economic sanctions may influence government policy, but they can also create hardship for ordinary citizens.","vi":"Các biện pháp trừng phạt kinh tế có thể ảnh hưởng đến chính sách của chính phủ, nhưng chúng cũng có thể gây ra khó khăn cho những người dân bình thường.","audioKind":"ex2"}],"collocations":[{"en":"impose sanctions on","vi":"áp đặt trừng phạt đối với"},{"en":"lift sanctions","vi":"dỡ bỏ lệnh trừng phạt"},{"en":"economic sanctions","vi":"trừng phạt kinh tế"},{"en":"sanction a proposal","vi":"phê chuẩn một đề xuất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể mang nghĩa là \"trừng phạt\" hoặc \"phê chuẩn\", mang nghĩa trái ngược nhau nên cần xem xét ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curb', 'en-c1-44', 'curb', '/kɝːb/', 'C1', 'kiểm soát; kìm chế; sự hạn chế; sự kiểm soát; lề đường (tiếng Mỹ)', 'v.', NULL, 'Đồng nghĩa: restrain, limit', 'Làm động từ có nghĩa là kiềm chế; từ "lề đường" trong tiếng Anh-Anh được viết là kerb.', 'I try to curb my spending by cooking at home.', NULL, 'Tôi cố gắng kiểm soát chi tiêu của mình bằng cách nấu ăn ở nhà.', '{"wordId":"curb","ukIpa":"/kɜːb/","usIpa":"/kɝːb/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"to limit or control something unwanted","vi":"kiểm soát; kìm chế"},{"pos":"n.","en":"a limit on an activity or behaviour","vi":"sự hạn chế; sự kiểm soát"},{"pos":"n.","en":"the raised edge between a road and pavement","vi":"lề đường (tiếng Mỹ)"}],"examples":[{"en":"I try to curb my spending by cooking at home.","vi":"Tôi cố gắng kiểm soát chi tiêu của mình bằng cách nấu ăn ở nhà.","audioKind":"ex"},{"en":"Cities can curb air pollution by improving public transport and encouraging residents to cycle.","vi":"Các thành phố có thể kìm chế ô nhiễm không khí bằng cách cải thiện giao thông công cộng và khuyến khích người dân đi xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"curb spending","vi":"kiểm soát chi tiêu"},{"en":"curb inflation","vi":"kiềm chế lạm phát"},{"en":"a curb on emissions","vi":"biện pháp hạn chế phát thải"}],"wordFamily":[],"synonyms":["restrain","limit"],"antonyms":[],"tipVi":"Làm động từ có nghĩa là kiềm chế; từ \"lề đường\" trong tiếng Anh-Anh được viết là kerb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commonwealth', 'en-c1-44', 'commonwealth', '/ˈkɑːmənwelθ/', 'C1', 'nhà nước cộng hòa; cộng đồng chính trị; Khối thịnh vượng chung (Anh)', 'n.', NULL, NULL, 'Viết hoa chữ cái đầu khi chỉ Khối thịnh vượng chung và thường đi kèm với mạo từ the.', 'The islanders established a commonwealth with an elected council.', NULL, 'Người dân trên đảo đã thiết lập một cộng đồng chính trị có hội đồng do bầu cử.', '{"wordId":"commonwealth","ukIpa":"/ˈkɒmənwelθ/","usIpa":"/ˈkɑːmənwelθ/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A politically organised community, especially one governed for public benefit.","vi":"nhà nước cộng hòa; cộng đồng chính trị"},{"pos":"n.","en":"An association of independent countries, mostly formerly under British rule.","vi":"Khối thịnh vượng chung (Anh)"}],"examples":[{"en":"The islanders established a commonwealth with an elected council.","vi":"Người dân trên đảo đã thiết lập một cộng đồng chính trị có hội đồng do bầu cử.","audioKind":"ex"},{"en":"Members of the Commonwealth cooperate on education and development while maintaining their own independent governments.","vi":"Các quốc gia thành viên của Khối thịnh vượng chung hợp tác về giáo dục và phát triển trong khi vẫn duy trì chính phủ độc lập của riêng họ.","audioKind":"ex2"}],"collocations":[{"en":"the Commonwealth","vi":"Khối thịnh vượng chung"},{"en":"Commonwealth countries","vi":"các nước thuộc Khối thịnh vượng chung"},{"en":"Commonwealth membership","vi":"tư cách thành viên Khối thịnh vượng chung"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu khi chỉ Khối thịnh vượng chung và thường đi kèm với mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commissioner', 'en-c1-44', 'commissioner', '/kəˈmɪʃənər/', 'C1', 'ủy viên; thanh tra cấp cao; ủy ban viên', 'n.', 'commission (n.), commission (v.)', NULL, 'Thường chỉ quan chức gánh vác trách nhiệm công cộng cụ thể, không dùng chung cho tất cả các thành viên ủy ban.', 'The commissioner visited our neighbourhood to discuss road safety.', NULL, 'Vị ủy viên đã đến thăm khu phố của chúng tôi để thảo luận về vấn đề an toàn giao thông.', '{"wordId":"commissioner","ukIpa":"/kəˈmɪʃənə/","usIpa":"/kəˈmɪʃənər/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"an official responsible for a public service or commission","vi":"ủy viên; thanh tra cấp cao; ủy ban viên"}],"examples":[{"en":"The commissioner visited our neighbourhood to discuss road safety.","vi":"Vị ủy viên đã đến thăm khu phố của chúng tôi để thảo luận về vấn đề an toàn giao thông.","audioKind":"ex"},{"en":"An independent commissioner should investigate public complaints and ensure that government agencies treat citizens fairly.","vi":"Một ủy viên độc lập nên tiến hành điều tra các khiếu nại của công chúng và bảo đảm rằng các cơ quan chính phủ đối xử công bằng với người dân.","audioKind":"ex2"}],"collocations":[{"en":"police commissioner","vi":"cảnh sát trưởng; ủy viên cảnh sát"},{"en":"high commissioner","vi":"cao ủy"},{"en":"appoint a commissioner","vi":"bổ nhiệm một ủy viên"}],"wordFamily":["commission (n.)","commission (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ quan chức gánh vác trách nhiệm công cộng cụ thể, không dùng chung cho tất cả các thành viên ủy ban.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inauguration', 'en-c1-44', 'inauguration', '/ɪˌnɔːɡjəˈreɪʃən/', 'C1', 'lễ nhậm chức; lễ khánh thành; lễ khai trương', 'n.', 'inaugurate (v.), inaugural (adj.)', NULL, 'Có thể dùng để chỉ nhà lãnh đạo nhậm chức hoặc cơ sở vật chất chính thức đi vào hoạt động.', 'We gathered outside to watch the new president''s inauguration.', NULL, 'Chúng tôi tập trung bên ngoài để theo dõi lễ nhậm chức của vị tổng thống mới.', '{"wordId":"inauguration","ukIpa":"/ɪˌnɔːɡjʊˈreɪʃən/","usIpa":"/ɪˌnɔːɡjəˈreɪʃən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A ceremony formally marking someone''s start in an important public office.","vi":"lễ nhậm chức"},{"pos":"n.","en":"The formal opening or beginning of a facility or activity.","vi":"lễ khánh thành; lễ khai trương"}],"examples":[{"en":"We gathered outside to watch the new president''s inauguration.","vi":"Chúng tôi tập trung bên ngoài để theo dõi lễ nhậm chức của vị tổng thống mới.","audioKind":"ex"},{"en":"The inauguration of the new railway marked a major step towards improving transport links between rural communities.","vi":"Lễ khánh thành tuyến đường sắt mới đánh dấu một bước tiến lớn trong việc cải thiện kết nối giao thông giữa các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"a presidential inauguration","vi":"lễ nhậm chức tổng thống"},{"en":"an inauguration ceremony","vi":"lễ nhậm chức hoặc khánh thành"},{"en":"the inauguration of a new museum","vi":"lễ khánh thành một bảo tàng mới"}],"wordFamily":["inaugurate (v.)","inaugural (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng để chỉ nhà lãnh đạo nhậm chức hoặc cơ sở vật chất chính thức đi vào hoạt động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bureaucracy', 'en-c1-44', 'bureaucracy', '/bjʊˈrɑːkrəsi/', 'C1', 'bộ máy quan liêu; hệ thống hành chính; thủ tục rườm rà; tệ quan liêu', 'n.', 'bureaucrat (n.), bureaucratic (adj.), bureaucratically (adv.)', NULL, 'bureaucracy chỉ hệ thống hoặc thủ tục rườm rà; cá nhân quan liêu là bureaucrat.', 'My aunt works within the city''s large bureaucracy.', NULL, 'Dì của tôi làm việc trong bộ máy hành chính cồng kềnh của thành phố.', '{"wordId":"bureaucracy","ukIpa":"/bjʊəˈrɒkrəsi/","usIpa":"/bjʊˈrɑːkrəsi/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"an administrative system run by officials following established rules","vi":"bộ máy quan liêu; hệ thống hành chính"},{"pos":"n.","en":"complicated official procedures that make tasks unnecessarily difficult","vi":"thủ tục rườm rà; tệ quan liêu"}],"examples":[{"en":"My aunt works within the city''s large bureaucracy.","vi":"Dì của tôi làm việc trong bộ máy hành chính cồng kềnh của thành phố.","audioKind":"ex"},{"en":"Reducing unnecessary bureaucracy could help small businesses obtain permits more quickly without weakening essential safety standards.","vi":"Việc cắt giảm các thủ tục hành chính rườm rà không cần thiết có thể giúp các doanh nghiệp nhỏ nhận giấy phép nhanh hơn mà không làm suy giảm các tiêu chuẩn an toàn thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"government bureaucracy","vi":"hệ thống hành chính nhà nước"},{"en":"reduce bureaucracy","vi":"cắt giảm thủ tục rườm rà"},{"en":"excessive bureaucracy","vi":"thủ tục hành chính quá mức"}],"wordFamily":["bureaucrat (n.)","bureaucratic (adj.)","bureaucratically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"bureaucracy chỉ hệ thống hoặc thủ tục rườm rà; cá nhân quan liêu là bureaucrat.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_provincial', 'en-c1-44', 'provincial', '/prəˈvɪnʃəl/', 'C1', 'thuộc tỉnh; cấp tỉnh; ngoại tỉnh; thuộc địa phương; thiển cận; bảo thủ', 'adj.', 'province (n.), provincialism (n.)', NULL, 'Khi chỉ đơn thuần mang nghĩa thuộc về tỉnh, từ này mang sắc thái trung tính; khi dùng để mô tả tư duy con người, nó có thể mang hàm ý chê bai, bảo thủ.', 'She works at the provincial hospital near our home.', NULL, 'Cô ấy làm việc tại bệnh viện tuyến tỉnh nằm gần nhà chúng tôi.', '{"wordId":"provincial","ukIpa":"/prəˈvɪnʃəl/","usIpa":"/prəˈvɪnʃəl/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"relating to a province or its administration","vi":"thuộc tỉnh; cấp tỉnh"},{"pos":"adj.","en":"relating to areas outside a country''s capital","vi":"ngoại tỉnh; thuộc địa phương"},{"pos":"adj.","en":"showing limited experience and unwillingness to accept different ideas","vi":"thiển cận; bảo thủ"}],"examples":[{"en":"She works at the provincial hospital near our home.","vi":"Cô ấy làm việc tại bệnh viện tuyến tỉnh nằm gần nhà chúng tôi.","audioKind":"ex"},{"en":"Provincial governments can adapt national education policies to meet the specific needs of local communities.","vi":"Chính quyền cấp tỉnh có thể điều chỉnh các chính sách giáo dục quốc gia để đáp ứng nhu cầu cụ thể của cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"provincial government","vi":"chính quyền cấp tỉnh"},{"en":"provincial capital","vi":"thủ phủ tỉnh"},{"en":"provincial town","vi":"thị trấn tỉnh lỵ"}],"wordFamily":["province (n.)","provincialism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ đơn thuần mang nghĩa thuộc về tỉnh, từ này mang sắc thái trung tính; khi dùng để mô tả tư duy con người, nó có thể mang hàm ý chê bai, bảo thủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_judicial', 'en-c1-44', 'judicial', '/dʒuːˈdɪʃəl/', 'C1', 'thuộc về tư pháp; thuộc tòa án hoặc việc thực thi công lý', 'adj.', 'judicially (adv.), judiciary (n.)', NULL, 'judicial chỉ vấn đề tư pháp; judicious chỉ tính sáng suốt, khôn ngoan.', 'The lawyer explained the judicial process to our family.', NULL, 'Vị luật sư đã giải thích quy trình tư pháp cho gia đình chúng tôi.', '{"wordId":"judicial","ukIpa":"/dʒuːˈdɪʃəl/","usIpa":"/dʒuːˈdɪʃəl/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"relating to courts, judges, or the administration of justice","vi":"thuộc về tư pháp; thuộc tòa án hoặc việc thực thi công lý"}],"examples":[{"en":"The lawyer explained the judicial process to our family.","vi":"Vị luật sư đã giải thích quy trình tư pháp cho gia đình chúng tôi.","audioKind":"ex"},{"en":"An independent judicial system helps protect individual rights and ensures that governments remain accountable.","vi":"Một hệ thống tư pháp độc lập giúp bảo vệ quyền lợi cá nhân và đảm bảo chính phủ phải chịu trách nhiệm giải trình.","audioKind":"ex2"}],"collocations":[{"en":"judicial system","vi":"hệ thống tư pháp"},{"en":"judicial review","vi":"xem xét tư pháp"},{"en":"judicial independence","vi":"tính độc lập của tư pháp"}],"wordFamily":["judicially (adv.)","judiciary (n.)"],"synonyms":[],"antonyms":[],"tipVi":"judicial chỉ vấn đề tư pháp; judicious chỉ tính sáng suốt, khôn ngoan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diplomacy', 'en-c1-44', 'diplomacy', '/dɪˈploʊməsi/', 'C1', 'nghiệp vụ ngoại giao; hoạt động ngoại giao; sự khéo léo ứng xử; nghệ thuật giao tiếp', 'n.', 'diplomat (n.), diplomatic (adj.), diplomatically (adv.)', NULL, 'Vừa mang nghĩa chính trị quốc tế, vừa chỉ kỹ năng ứng xử khéo léo nhằm tránh làm mất lòng người khác trong đời sống.', 'The two countries solved their disagreement through diplomacy.', NULL, 'Hai quốc gia đã giải quyết những bất đồng thông qua con đường ngoại giao.', '{"wordId":"diplomacy","ukIpa":"/dɪˈpləʊməsi/","usIpa":"/dɪˈploʊməsi/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"Managing relations between countries through discussion and negotiation.","vi":"nghiệp vụ ngoại giao; hoạt động ngoại giao"},{"pos":"n.","en":"Skill in dealing with people without upsetting them.","vi":"sự khéo léo ứng xử; nghệ thuật giao tiếp"}],"examples":[{"en":"The two countries solved their disagreement through diplomacy.","vi":"Hai quốc gia đã giải quyết những bất đồng thông qua con đường ngoại giao.","audioKind":"ex"},{"en":"Effective diplomacy can help neighbouring countries manage shared water resources without resorting to conflict.","vi":"Công tác ngoại giao hiệu quả có thể giúp các quốc gia láng giềng quản lý nguồn nước chung mà không cần phải viện đến xung đột.","audioKind":"ex2"}],"collocations":[{"en":"international diplomacy","vi":"ngoại giao quốc tế"},{"en":"quiet diplomacy","vi":"ngoại giao thầm lặng"},{"en":"use diplomacy","vi":"vận dụng sự khéo léo trong ứng xử"}],"wordFamily":["diplomat (n.)","diplomatic (adj.)","diplomatically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa mang nghĩa chính trị quốc tế, vừa chỉ kỹ năng ứng xử khéo léo nhằm tránh làm mất lòng người khác trong đời sống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_veto', 'en-c1-44', 'veto', '/ˈviːtoʊ/', 'C1', 'quyền phủ quyết; sự phủ quyết; phủ quyết; bác bỏ', 'n.', NULL, 'Đồng nghĩa: reject, block · Trái nghĩa: approve', 'Danh từ số nhiều là vetoes; dạng quá khứ của động từ là vetoed.', 'The club president used her veto to stop the purchase.', NULL, 'Chủ tịch câu lạc bộ đã dùng quyền phủ quyết của mình để ngăn chặn việc mua sắm.', '{"wordId":"veto","ukIpa":"/ˈviːtəʊ/","usIpa":"/ˈviːtoʊ/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"Official power to reject a decision, or its use.","vi":"quyền phủ quyết; sự phủ quyết"},{"pos":"v.","en":"Officially reject a proposed decision or action.","vi":"phủ quyết; bác bỏ"}],"examples":[{"en":"The club president used her veto to stop the purchase.","vi":"Chủ tịch câu lạc bộ đã dùng quyền phủ quyết của mình để ngăn chặn việc mua sắm.","audioKind":"ex"},{"en":"Giving every member a veto can protect minority interests but may also delay urgent collective decisions.","vi":"Trao cho mọi thành viên quyền phủ quyết có thể bảo vệ lợi ích của nhóm thiểu số nhưng cũng có thể làm chậm trễ các quyết định tập thể khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"veto power","vi":"quyền phủ quyết"},{"en":"exercise a veto","vi":"thực thi quyền phủ quyết"},{"en":"veto a proposal","vi":"phủ quyết một đề xuất"},{"en":"override a veto","vi":"bác bỏ quyền phủ quyết"}],"wordFamily":[],"synonyms":["reject","block"],"antonyms":["approve"],"tipVi":"Danh từ số nhiều là vetoes; dạng quá khứ của động từ là vetoed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_authorize', 'en-c1-44', 'authorize', '/ˈɔːθəraɪz/', 'C1', 'ủy quyền; cho phép; phê chuẩn', 'v.', 'authorization (n.), authorized (adj.), unauthorized (adj.)', 'Đồng nghĩa: permit, approve · Trái nghĩa: forbid', 'Thường dùng authorize sb to do; tiếng Anh - Anh cũng có thể viết là authorise.', 'Only the manager can authorize a refund this large.', NULL, 'Chỉ có quản lý mới có thể phê duyệt khoản hoàn tiền lớn như thế này.', '{"wordId":"authorize","ukIpa":"/ˈɔːθəraɪz/","usIpa":"/ˈɔːθəraɪz/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To give official permission for someone to do something.","vi":"ủy quyền; cho phép; phê chuẩn"}],"examples":[{"en":"Only the manager can authorize a refund this large.","vi":"Chỉ có quản lý mới có thể phê duyệt khoản hoàn tiền lớn như thế này.","audioKind":"ex"},{"en":"Local authorities may authorize new housing developments only after assessing their likely effects on traffic and public services.","vi":"Chính quyền địa phương có thể chỉ cho phép các dự án phát triển nhà ở mới sau khi đánh giá tác động dự kiến của chúng đối với giao thông và dịch vụ công cộng.","audioKind":"ex2"}],"collocations":[{"en":"authorize a payment","vi":"phê duyệt thanh toán"},{"en":"authorize someone to act","vi":"ủy quyền cho ai hành động"},{"en":"authorize access","vi":"cho phép truy cập"}],"wordFamily":["authorization (n.)","authorized (adj.)","unauthorized (adj.)"],"synonyms":["permit","approve"],"antonyms":["forbid"],"tipVi":"Thường dùng authorize sb to do; tiếng Anh - Anh cũng có thể viết là authorise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nomination', 'en-c1-44', 'nomination', '/ˌnɑːmɪˈneɪʃən/', 'C1', 'sự đề cử; sự giới thiệu', 'n.', 'nominate (v.), nominee (n.)', NULL, 'Dùng nomination cho việc đề cử; việc bổ nhiệm chính thức thường dùng appointment.', 'Her nomination for the teaching award surprised everyone.', NULL, 'Việc cô ấy nhận được đề cử cho giải thưởng giảng dạy đã khiến tất cả mọi người ngạc nhiên.', '{"wordId":"nomination","ukIpa":"/ˌnɒmɪˈneɪʃən/","usIpa":"/ˌnɑːmɪˈneɪʃən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"The act of formally proposing someone for a position or award.","vi":"sự đề cử; sự giới thiệu"}],"examples":[{"en":"Her nomination for the teaching award surprised everyone.","vi":"Việc cô ấy nhận được đề cử cho giải thưởng giảng dạy đã khiến tất cả mọi người ngạc nhiên.","audioKind":"ex"},{"en":"A transparent nomination process can help ensure that leadership candidates represent the interests of the wider community.","vi":"Quy trình đề cử minh bạch có thể giúp đảm bảo rằng các ứng viên lãnh đạo đại diện cho lợi ích của cộng đồng rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"receive a nomination","vi":"nhận được đề cử"},{"en":"nomination for an award","vi":"đề cử cho một giải thưởng"},{"en":"nomination process","vi":"quy trình đề cử"},{"en":"submit a nomination","vi":"nộp đơn đề cử"}],"wordFamily":["nominate (v.)","nominee (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng nomination cho việc đề cử; việc bổ nhiệm chính thức thường dùng appointment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obligate', 'en-c1-44', 'obligate', '/ˈɑːbləɡeɪt/', 'C1', 'buộc phải; bắt buộc; thuộc sinh vật phải sống ký sinh', 'v.', 'obligation (n.), obligatory (adj.), obligated (adj.), oblige (v.)', 'Đồng nghĩa: bind, compel', 'Tính từ dùng trong sinh học, phần đuôi phát âm là /ɡət/; nghĩa có trách nhiệm, nghĩa vụ dùng obligated.', 'Does this agreement obligate me to pay every month?', NULL, 'Thỏa thuận này có bắt buộc tôi phải thanh toán tiền hàng tháng không?', '{"wordId":"obligate","ukIpa":"/ˈɒblɪɡeɪt/","usIpa":"/ˈɑːbləɡeɪt/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To require someone to do something legally or morally.","vi":"buộc phải; bắt buộc"},{"pos":"adj.","en":"Needing particular conditions or resources to survive.","vi":"thuộc sinh vật phải sống ký sinh"}],"examples":[{"en":"Does this agreement obligate me to pay every month?","vi":"Thỏa thuận này có bắt buộc tôi phải thanh toán tiền hàng tháng không?","audioKind":"ex"},{"en":"Environmental regulations obligate manufacturers to dispose of hazardous waste safely rather than transfer responsibility to local communities.","vi":"Các quy định về môi trường buộc nhà sản xuất phải xử lý chất thải nguy hại một cách an toàn thay vì chuyển trách nhiệm cho cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"obligate someone to do something","vi":"buộc ai đó phải làm điều gì"},{"en":"legally obligated","vi":"bị ràng buộc về mặt pháp lý"},{"en":"obligate parasite","vi":"sinh vật ký sinh bắt buộc"}],"wordFamily":["obligation (n.)","obligatory (adj.)","obligated (adj.)","oblige (v.)"],"synonyms":["bind","compel"],"antonyms":[],"tipVi":"Tính từ dùng trong sinh học, phần đuôi phát âm là /ɡət/; nghĩa có trách nhiệm, nghĩa vụ dùng obligated.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oath', 'en-c1-44', 'oath', '/oʊθ/', 'C1', 'lời thề; lời tuyên thệ', 'n.', NULL, 'Đồng nghĩa: vow, pledge', 'Cụm under oath nghĩa là đã tuyên thệ nói sự thật, thường dùng trong ngữ cảnh pháp lý.', 'The witness took an oath before answering any questions.', NULL, 'Người làm chứng đã tuyên thệ trước khi trả lời bất kỳ câu hỏi nào.', '{"wordId":"oath","ukIpa":"/əʊθ/","usIpa":"/oʊθ/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A formal promise to tell the truth or fulfil a duty.","vi":"lời thề; lời tuyên thệ"}],"examples":[{"en":"The witness took an oath before answering any questions.","vi":"Người làm chứng đã tuyên thệ trước khi trả lời bất kỳ câu hỏi nào.","audioKind":"ex"},{"en":"Public officials who swear an oath to serve society should remain accountable for their decisions and conduct.","vi":"Các quan chức công quyền tuyên thệ phục vụ xã hội phải chịu trách nhiệm về các quyết định và hành vi của mình.","audioKind":"ex2"}],"collocations":[{"en":"take an oath","vi":"tuyên thệ"},{"en":"swear an oath","vi":"lập lời thề"},{"en":"under oath","vi":"đang chịu lời tuyên thệ ràng buộc"},{"en":"break an oath","vi":"phá vỡ lời thề"}],"wordFamily":[],"synonyms":["vow","pledge"],"antonyms":[],"tipVi":"Cụm under oath nghĩa là đã tuyên thệ nói sự thật, thường dùng trong ngữ cảnh pháp lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_testify', 'en-c1-44', 'testify', '/ˈtestɪfaɪ/', 'C1', 'làm chứng; cung cấp lời khai; chứng tỏ; minh chứng', 'v.', 'testimony (n.)', 'Đồng nghĩa: attest', 'testify that đi với mệnh đề; testify to đi với danh từ hoặc danh động từ.', 'She agreed to testify about the accident she witnessed.', NULL, 'Cô ấy đồng ý làm chứng về vụ tai nạn mà cô ấy đã tận mắt chứng kiến.', '{"wordId":"testify","ukIpa":"/ˈtestɪfaɪ/","usIpa":"/ˈtestɪfaɪ/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To give evidence in court about what you know","vi":"làm chứng; cung cấp lời khai"},{"pos":"v.","en":"To provide evidence that something is true or exists","vi":"chứng tỏ; minh chứng"}],"examples":[{"en":"She agreed to testify about the accident she witnessed.","vi":"Cô ấy đồng ý làm chứng về vụ tai nạn mà cô ấy đã tận mắt chứng kiến.","audioKind":"ex"},{"en":"Residents were invited to testify in court about the effects of industrial pollution on their health.","vi":"Người dân được mời ra tòa để làm chứng về ảnh hưởng của ô nhiễm công nghiệp đối với sức khỏe của họ.","audioKind":"ex2"}],"collocations":[{"en":"testify in court","vi":"làm chứng trước tòa"},{"en":"testify against someone","vi":"làm chứng chống lại ai đó"},{"en":"testify to something","vi":"làm chứng cho điều gì"}],"wordFamily":["testimony (n.)"],"synonyms":["attest"],"antonyms":[],"tipVi":"testify that đi với mệnh đề; testify to đi với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_null', 'en-c1-44', 'null', '/nʌl/', 'C1', 'vô hiệu lực; không có giá trị pháp lý; có giá trị bằng không; không có dữ liệu lưu trữ', 'adj.', 'nullify (v.), nullification (n.), nullity (n.)', 'Đồng nghĩa: invalid · Trái nghĩa: valid', 'Trong pháp lý thường dùng null and void; giá trị rỗng trong lập trình không nhất thiết bằng số không.', 'The court declared their rental agreement null and void.', NULL, 'Tòa án đã tuyên bố thỏa thuận thuê nhà của họ là vô hiệu.', '{"wordId":"null","ukIpa":"/nʌl/","usIpa":"/nʌl/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"Having no legal force or effect.","vi":"vô hiệu lực; không có giá trị pháp lý"},{"pos":"adj.","en":"Having a zero value or representing no stored value.","vi":"có giá trị bằng không; không có dữ liệu lưu trữ"}],"examples":[{"en":"The court declared their rental agreement null and void.","vi":"Tòa án đã tuyên bố thỏa thuận thuê nhà của họ là vô hiệu.","audioKind":"ex"},{"en":"A contract may be declared null if one party was forced to accept its terms.","vi":"Một hợp đồng có thể bị tuyên bố vô hiệu nếu một bên bị ép buộc phải chấp nhận các điều khoản của nó.","audioKind":"ex2"}],"collocations":[{"en":"null and void","vi":"vô hiệu lực"},{"en":"null value","vi":"giá trị rỗng"},{"en":"null hypothesis","vi":"giả thuyết không"}],"wordFamily":["nullify (v.)","nullification (n.)","nullity (n.)"],"synonyms":["invalid"],"antonyms":["valid"],"tipVi":"Trong pháp lý thường dùng null and void; giá trị rỗng trong lập trình không nhất thiết bằng số không.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lawful', 'en-c1-44', 'lawful', '/ˈlɔːfl/', 'C1', 'hợp pháp; đúng pháp luật', 'adj.', 'law (n.), lawfully (adv.), unlawful (adj.), lawfulness (n.)', 'Đồng nghĩa: legal, legitimate · Trái nghĩa: unlawful, illegal', 'lawful chỉ luật pháp cho phép; legal còn có thể mang nghĩa "có liên quan đến pháp luật".', 'The lost bicycle was returned to its lawful owner.', NULL, 'Chiếc xe đạp bị mất đã được trả lại cho người chủ hợp pháp của nó.', '{"wordId":"lawful","ukIpa":"/ˈlɔːfl/","usIpa":"/ˈlɔːfl/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"allowed or recognised by law","vi":"hợp pháp; đúng pháp luật"}],"examples":[{"en":"The lost bicycle was returned to its lawful owner.","vi":"Chiếc xe đạp bị mất đã được trả lại cho người chủ hợp pháp của nó.","audioKind":"ex"},{"en":"Governments should ensure that personal information is collected only for lawful purposes and protected against misuse.","vi":"Các chính phủ nên đảm bảo rằng thông tin cá nhân chỉ được thu thập cho các mục đích hợp pháp và được bảo vệ khỏi việc lạm dụng.","audioKind":"ex2"}],"collocations":[{"en":"lawful owner","vi":"chủ sở hữu hợp pháp"},{"en":"lawful authority","vi":"thẩm quyền hợp pháp"},{"en":"lawful means","vi":"biện pháp hợp pháp"},{"en":"lawful purpose","vi":"mục đích hợp pháp"}],"wordFamily":["law (n.)","lawfully (adv.)","unlawful (adj.)","lawfulness (n.)"],"synonyms":["legal","legitimate"],"antonyms":["unlawful","illegal"],"tipVi":"lawful chỉ luật pháp cho phép; legal còn có thể mang nghĩa \"có liên quan đến pháp luật\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_44_1', 'en-c1-44', 'Cách dùng “provincial” (adj.) — thuộc tỉnh; cấp tỉnh', 'provincial government  ·  provincial capital  ·  provincial town', 'Khi chỉ đơn thuần mang nghĩa thuộc về tỉnh, từ này mang sắc thái trung tính; khi dùng để mô tả tư duy con người, nó có thể mang hàm ý chê bai, bảo thủ.', 'Họ từ (Word Family): province (n.), provincialism (n.)', '[{"hanzi":"She works at the provincial hospital near our home.","pinyin":"","meaning":"Cô ấy làm việc tại bệnh viện tuyến tỉnh nằm gần nhà chúng tôi."},{"hanzi":"Provincial governments can adapt national education policies to meet the specific needs of local communities.","pinyin":"","meaning":"Chính quyền cấp tỉnh có thể điều chỉnh các chính sách giáo dục quốc gia để đáp ứng nhu cầu cụ thể của cộng đồng địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_44_2', 'en-c1-44', 'Cách dùng “diplomacy” (n.) — nghiệp vụ ngoại giao; hoạt động ngoại giao', 'international diplomacy  ·  quiet diplomacy  ·  use diplomacy', 'Vừa mang nghĩa chính trị quốc tế, vừa chỉ kỹ năng ứng xử khéo léo nhằm tránh làm mất lòng người khác trong đời sống.', 'Họ từ (Word Family): diplomat (n.), diplomatic (adj.), diplomatically (adv.)', '[{"hanzi":"The two countries solved their disagreement through diplomacy.","pinyin":"","meaning":"Hai quốc gia đã giải quyết những bất đồng thông qua con đường ngoại giao."},{"hanzi":"Effective diplomacy can help neighbouring countries manage shared water resources without resorting to conflict.","pinyin":"","meaning":"Công tác ngoại giao hiệu quả có thể giúp các quốc gia láng giềng quản lý nguồn nước chung mà không cần phải viện đến xung đột."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_44_3', 'en-c1-44', 'Cách dùng “democrat” (n.) — người theo chủ nghĩa dân chủ', 'committed democrat  ·  lifelong democrat  ·  liberal democrat', 'Chỉ người theo chủ nghĩa dân chủ nói chung dùng chữ thường; chỉ đảng viên Đảng Dân chủ Mỹ viết hoa chữ "Democrat".', 'Họ từ (Word Family): democracy (n.), democratic (adj.), democratically (adv.), democratise (v.) | Trái nghĩa: autocrat', '[{"hanzi":"As a democrat, she wants everyone to have a vote.","pinyin":"","meaning":"Là một người theo chủ nghĩa dân chủ, cô ấy muốn mọi người đều có quyền bỏ phiếu."},{"hanzi":"A committed democrat should defend fair elections even when the results favour a competing political party.","pinyin":"","meaning":"Một người theo chủ nghĩa dân chủ tận tụy nên bảo vệ các cuộc bầu cử công bằng ngay cả khi kết quả nghiêng về một đảng phái chính trị đối lập."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_44_4', 'en-c1-44', 'Cách dùng “commissioner” (n.) — ủy viên; thanh tra cấp cao; ủy ban viên', 'police commissioner  ·  high commissioner  ·  appoint a commissioner', 'Thường chỉ quan chức gánh vác trách nhiệm công cộng cụ thể, không dùng chung cho tất cả các thành viên ủy ban.', 'Họ từ (Word Family): commission (n.), commission (v.)', '[{"hanzi":"The commissioner visited our neighbourhood to discuss road safety.","pinyin":"","meaning":"Vị ủy viên đã đến thăm khu phố của chúng tôi để thảo luận về vấn đề an toàn giao thông."},{"hanzi":"An independent commissioner should investigate public complaints and ensure that government agencies treat citizens fairly.","pinyin":"","meaning":"Một ủy viên độc lập nên tiến hành điều tra các khiếu nại của công chúng và bảo đảm rằng các cơ quan chính phủ đối xử công bằng với người dân."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_44_1', 'en-c1-44', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_1_1', 'ten_c1_44_1', 'consul', 'The consul helped us after we lost our passports.', 'The consul helped us after we lost our passports.', '/ˈkɑːnsəl/', 'Viên lãnh sự đã giúp đỡ chúng tôi sau khi chúng tôi bị mất hộ chiếu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_1_2', 'ten_c1_44_1', 'compliance', 'The inspector checked our kitchen for compliance with hygiene rules.', 'The inspector checked our kitchen for compliance with hygiene rules.', '/kəmˈplaɪəns/', 'Nhân viên thanh tra đã kiểm tra nhà bếp của chúng tôi để đảm bảo tuân thủ các quy định về vệ sinh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_1_3', 'ten_c1_44_1', 'overthrow', 'The film follows citizens who overthrow an unfair ruler.', 'The film follows citizens who overthrow an unfair ruler.', '/ˌoʊvərˈθroʊ/', 'Bộ phim xoay quanh những người dân đứng lên lật đổ một nhà cầm quyền bất công.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_1_4', 'ten_c1_44_1', 'liable', 'These old pipes are liable to burst in winter.', 'These old pipes are liable to burst in winter.', '/ˈlaɪəbl/', 'Những đường ống cũ này rất dễ bị vỡ vào mùa đông.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_1_5', 'ten_c1_44_1', 'democrat', 'As a democrat, she wants everyone to have a vote.', 'As a democrat, she wants everyone to have a vote.', '/ˈdeməkræt/', 'Là một người theo chủ nghĩa dân chủ, cô ấy muốn mọi người đều có quyền bỏ phiếu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_1_6', 'ten_c1_44_1', 'designate', 'We designated one cupboard for all our cleaning supplies.', 'We designated one cupboard for all our cleaning supplies.', '/ˈdezɪɡneɪt/', 'Chúng tôi đã chọn một chiếc tủ để chuyên đựng các dụng cụ vệ sinh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_1_7', 'ten_c1_44_1', 'enforce', 'The pool staff enforce strict rules about running indoors.', 'The pool staff enforce strict rules about running indoors.', '/ɪnˈfɔːrs/', 'Nhân viên hồ bơi thực thi nghiêm ngặt các quy định về việc không chạy nhảy trong nhà.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_1_8', 'ten_c1_44_1', 'sanction', 'The club imposed a sanction for breaking its rules.', 'The club imposed a sanction for breaking its rules.', '/ˈsæŋkʃən/', 'Câu lạc bộ đã đưa ra án phạt vì vi phạm quy định của họ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_44_1_1', 'en-c1-44', 'ten_c1_44_1', 'listening', 'listening', 'The consul helped us after we lost our passports.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người làm chứng đã tuyên thệ trước khi trả lời bất kỳ câu hỏi nào.","Vị ủy viên đã đến thăm khu phố của chúng tôi để thảo luận về vấn đề an toàn giao thông.","Viên lãnh sự đã giúp đỡ chúng tôi sau khi chúng tôi bị mất hộ chiếu.","Chiếc xe đạp bị mất đã được trả lại cho người chủ hợp pháp của nó."]'::jsonb, 2, 'The consul helped us after we lost our passports. → Viên lãnh sự đã giúp đỡ chúng tôi sau khi chúng tôi bị mất hộ chiếu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_44_1_2', 'en-c1-44', 'ten_c1_44_1', 'listening', 'listening', 'The inspector checked our kitchen for compliance with hygiene rules.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhân viên thanh tra đã kiểm tra nhà bếp của chúng tôi để đảm bảo tuân thủ các quy định về vệ sinh.","Vị luật sư đã giải thích quy trình tư pháp cho gia đình chúng tôi.","Chúng tôi tập trung bên ngoài để theo dõi lễ nhậm chức của vị tổng thống mới.","Viên lãnh sự đã giúp đỡ chúng tôi sau khi chúng tôi bị mất hộ chiếu."]'::jsonb, 0, 'The inspector checked our kitchen for compliance with hygiene rules. → Nhân viên thanh tra đã kiểm tra nhà bếp của chúng tôi để đảm bảo tuân thủ các quy định về vệ sinh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_44_1_3', 'en-c1-44', 'ten_c1_44_1', 'listening', 'listening', 'The film follows citizens who overthrow an unfair ruler.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bộ phim xoay quanh những người dân đứng lên lật đổ một nhà cầm quyền bất công.","Người làm chứng đã tuyên thệ trước khi trả lời bất kỳ câu hỏi nào.","Tôi cố gắng kiểm soát chi tiêu của mình bằng cách nấu ăn ở nhà.","Chúng tôi đã chọn một chiếc tủ để chuyên đựng các dụng cụ vệ sinh."]'::jsonb, 0, 'The film follows citizens who overthrow an unfair ruler. → Bộ phim xoay quanh những người dân đứng lên lật đổ một nhà cầm quyền bất công.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_44_2', 'en-c1-44', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_2_1', 'ten_c1_44_2', 'consul', 'A consul may support citizens facing difficulties overseas and help strengthen commercial links between countries.', 'A consul may support citizens facing difficulties overseas and help strengthen commercial links between countries.', '/ˈkɑːnsəl/', 'Một lãnh sự có thể hỗ trợ công dân gặp khó khăn ở nước ngoài và giúp tăng cường mối quan hệ thương mại giữa các quốc gia.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_2_2', 'ten_c1_44_2', 'compliance', 'Regular inspections can improve compliance with environmental regulations and reduce pollution from industrial facilities.', 'Regular inspections can improve compliance with environmental regulations and reduce pollution from industrial facilities.', '/kəmˈplaɪəns/', 'Việc thanh tra thường xuyên có thể nâng cao mức độ tuân thủ các quy định về môi trường và giảm thiểu ô nhiễm từ các cơ sở công nghiệp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_2_3', 'ten_c1_44_2', 'overthrow', 'Economic hardship can weaken public support for a government and encourage attempts to overthrow it.', 'Economic hardship can weaken public support for a government and encourage attempts to overthrow it.', '/ˌoʊvərˈθroʊ/', 'Khó khăn kinh tế có thể làm suy yếu sự ủng hộ của công chúng đối với chính phủ và kích thích các nỗ lực lật đổ chính quyền đó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_2_4', 'ten_c1_44_2', 'liable', 'Employers may be held liable for injuries caused by unsafe conditions in the workplace.', 'Employers may be held liable for injuries caused by unsafe conditions in the workplace.', '/ˈlaɪəbl/', 'Người sử dụng lao động có thể phải chịu trách nhiệm pháp lý đối với các thương tích do điều kiện không an toàn tại nơi làm việc gây ra.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_2_5', 'ten_c1_44_2', 'democrat', 'A committed democrat should defend fair elections even when the results favour a competing political party.', 'A committed democrat should defend fair elections even when the results favour a competing political party.', '/ˈdeməkræt/', 'Một người theo chủ nghĩa dân chủ tận tụy nên bảo vệ các cuộc bầu cử công bằng ngay cả khi kết quả nghiêng về một đảng phái chính trị đối lập.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_44_2_6', 'ten_c1_44_2', 'designate', 'Local authorities should designate more urban land as protected green space to improve residents'' quality of life.', 'Local authorities should designate more urban land as protected green space to improve residents'' quality of life.', '/ˈdezɪɡneɪt/', 'Chính quyền địa phương nên quy hoạch nhiều đất đô thị hơn thành không gian xanh được bảo vệ để cải thiện chất lượng cuộc sống của cư dân.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_44_2_1', 'en-c1-44', 'ten_c1_44_2', 'listening', 'listening', 'A consul may support citizens facing difficulties overseas and help strengthen commercial links between countries.', NULL, 'Trong câu vừa nghe, từ “consul” mang nghĩa nào sau đây?', '["cơn mưa xối xả; trận lụt lớn","lãnh sự (một quan chức ngoại giao ở nước ngoài giúp đỡ công dân và đại diện cho lợi ích quốc gia)","lời thề; lời tuyên thệ","bản địa; thuộc về người bản xứ"]'::jsonb, 1, '“consul” (/ˈkɑːnsəl/): lãnh sự (một quan chức ngoại giao ở nước ngoài giúp đỡ công dân và đại diện cho lợi ích quốc gia). Câu đầy đủ: A consul may support citizens facing difficulties overseas and help strengthen commercial links between countries.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_44_2_2', 'en-c1-44', 'ten_c1_44_2', 'listening', 'listening', 'Regular inspections can improve compliance with environmental regulations and reduce pollution from industrial facilities.', NULL, 'Trong câu vừa nghe, từ “compliance” mang nghĩa nào sau đây?', '["sự tuân thủ; sự tuân theo","hàng không; ngành hàng không","tính dễ bị tổn thương; tính dễ bị tác động","uy tín; danh vọng; tiếng tăm"]'::jsonb, 0, '“compliance” (/kəmˈplaɪəns/): sự tuân thủ; sự tuân theo. Câu đầy đủ: Regular inspections can improve compliance with environmental regulations and reduce pollution from industrial facilities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
