INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_1', 'en-c1-44', NULL, 'comprehensive_test', 'listening', 'consul', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bệnh viêm phổi","sự kinh ngạc; sự thất vọng","lãnh sự (một quan chức ngoại giao ở nước ngoài giúp đỡ công dân và đại diện cho lợi ích quốc gia)","vũng; vũng nhỏ; lạch"]'::jsonb, 2, 'consul (/ˈkɑːnsəl/) → lãnh sự (một quan chức ngoại giao ở nước ngoài giúp đỡ công dân và đại diện cho lợi ích quốc gia)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_2', 'en-c1-44', NULL, 'comprehensive_test', 'listening', 'The inspector checked our kitchen for compliance with hygiene rules.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đồng ý làm chứng về vụ tai nạn mà cô ấy đã tận mắt chứng kiến.","Chủ tịch câu lạc bộ đã dùng quyền phủ quyết của mình để ngăn chặn việc mua sắm.","Nhân viên thanh tra đã kiểm tra nhà bếp của chúng tôi để đảm bảo tuân thủ các quy định về vệ sinh.","Tòa án đã tuyên bố thỏa thuận thuê nhà của họ là vô hiệu."]'::jsonb, 2, 'The inspector checked our kitchen for compliance with hygiene rules. → Nhân viên thanh tra đã kiểm tra nhà bếp của chúng tôi để đảm bảo tuân thủ các quy định về vệ sinh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_3', 'en-c1-44', NULL, 'comprehensive_test', 'listening', 'overthrow', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự đền bù; sự tạ lỗi","mãn tính","tính ưu việt; thế vượt trội","lật đổ; đánh đổ"]'::jsonb, 3, 'overthrow (/ˌoʊvərˈθroʊ/) → lật đổ; đánh đổ; sự lật đổ; sự sụp đổ của chính quyền', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_4', 'en-c1-44', NULL, 'comprehensive_test', 'listening', 'These old pipes are liable to burst in winter.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những đường ống cũ này rất dễ bị vỡ vào mùa đông.","Chiếc xe đạp bị mất đã được trả lại cho người chủ hợp pháp của nó.","Nhân viên hồ bơi thực thi nghiêm ngặt các quy định về việc không chạy nhảy trong nhà.","Là một người theo chủ nghĩa dân chủ, cô ấy muốn mọi người đều có quyền bỏ phiếu."]'::jsonb, 0, 'These old pipes are liable to burst in winter. → Những đường ống cũ này rất dễ bị vỡ vào mùa đông.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_5', 'en-c1-44', NULL, 'comprehensive_test', 'listening', 'democrat', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người theo chủ nghĩa dân chủ","bao quanh; vây quanh","thực thể độc lập; tổ chức riêng biệt","thuộc về không gian"]'::jsonb, 0, 'democrat (/ˈdeməkræt/) → người theo chủ nghĩa dân chủ; đảng viên hoặc người ủng hộ Đảng Dân chủ ở Mỹ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_6', 'en-c1-44', NULL, 'comprehensive_test', 'listening', 'We designated one cupboard for all our cleaning supplies.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc xe đạp bị mất đã được trả lại cho người chủ hợp pháp của nó.","Cô ấy làm việc tại bệnh viện tuyến tỉnh nằm gần nhà chúng tôi.","Việc cô ấy nhận được đề cử cho giải thưởng giảng dạy đã khiến tất cả mọi người ngạc nhiên.","Chúng tôi đã chọn một chiếc tủ để chuyên đựng các dụng cụ vệ sinh."]'::jsonb, 3, 'We designated one cupboard for all our cleaning supplies. → Chúng tôi đã chọn một chiếc tủ để chuyên đựng các dụng cụ vệ sinh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_7', 'en-c1-44', NULL, 'comprehensive_test', 'listening', 'enforce', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["pít-tông; tr Pít-tông","làm cho ai/cái gì rơi vào trạng thái nào đó","thi hành; thực thi; bắt tuân theo","lời chào hỏi; lời chào đầu thư"]'::jsonb, 2, 'enforce (/ɪnˈfɔːrs/) → thi hành; thực thi; bắt tuân theo', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_8', 'en-c1-44', NULL, 'comprehensive_test', 'listening', 'The club imposed a sanction for breaking its rules.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhân viên thanh tra đã kiểm tra nhà bếp của chúng tôi để đảm bảo tuân thủ các quy định về vệ sinh.","Chúng tôi đã chọn một chiếc tủ để chuyên đựng các dụng cụ vệ sinh.","Việc cô ấy nhận được đề cử cho giải thưởng giảng dạy đã khiến tất cả mọi người ngạc nhiên.","Câu lạc bộ đã đưa ra án phạt vì vi phạm quy định của họ."]'::jsonb, 3, 'The club imposed a sanction for breaking its rules. → Câu lạc bộ đã đưa ra án phạt vì vi phạm quy định của họ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_9', 'en-c1-44', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Someone who supports government based on the people''s choices”?', '["consul","diplomacy","democrat","enforce"]'::jsonb, 2, 'democrat (/ˈdeməkræt/) → người theo chủ nghĩa dân chủ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_10', 'en-c1-44', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To officially choose someone or something for a particular purpose.”?', '["compliance","testify","designate","commissioner"]'::jsonb, 2, 'designate (/ˈdezɪɡneɪt/) → chỉ định; phân công', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_11', 'en-c1-44', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Make sure that people obey a law or rule.”?', '["compliance","commissioner","enforce","commonwealth"]'::jsonb, 2, 'enforce (/ɪnˈfɔːrs/) → thi hành; thực thi; bắt tuân theo', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_12', 'en-c1-44', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An official penalty intended to enforce rules or change behaviour.”?', '["authorize","liable","sanction","consul"]'::jsonb, 2, 'sanction (/ˈsæŋkʃən/) → sự trừng phạt; biện pháp trừng phạt', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_13', 'en-c1-44', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to limit or control something unwanted”?', '["democrat","null","curb","inauguration"]'::jsonb, 2, 'curb (/kɝːb/) → kiểm soát; kìm chế', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
