INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_18', 'en-c1-44', NULL, 'comprehensive_test', 'reading', NULL, 'A consul may support citizens facing difficulties overseas and help strengthen commercial links between countries.', 'Dựa vào câu trên, từ “consul” có nghĩa phù hợp nhất là gì?', '["lãnh sự (một quan chức ngoại giao ở nước ngoài giúp đỡ công dân và đại diện cho lợi ích quốc gia)","luôn luôn; lúc nào cũng","sự ca ngợi; tiếngvang","có thể chịu đựng được"]'::jsonb, 0, 'consul: lãnh sự (một quan chức ngoại giao ở nước ngoài giúp đỡ công dân và đại diện cho lợi ích quốc gia). Dịch cả câu: Một lãnh sự có thể hỗ trợ công dân gặp khó khăn ở nước ngoài và giúp tăng cường mối quan hệ thương mại giữa các quốc gia.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_19', 'en-c1-44', NULL, 'comprehensive_test', 'reading', NULL, 'Regular inspections can improve compliance with environmental regulations and reduce pollution from industrial facilities.', 'Dựa vào câu trên, từ “compliance” có nghĩa phù hợp nhất là gì?', '["xảy ra trước; tồn tại trước một sự việc hoặc vật khác","sự tuân thủ; sự tuân theo","kỳ tích, chiến công, hành động đòi hỏi kỹ năng, sức mạnh hoặc sự dũng cảm phi thường","thủ tục hành chính; nghi thức rườm rà"]'::jsonb, 1, 'compliance: sự tuân thủ; sự tuân theo. Dịch cả câu: Việc thanh tra thường xuyên có thể nâng cao mức độ tuân thủ các quy định về môi trường và giảm thiểu ô nhiễm từ các cơ sở công nghiệp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_20', 'en-c1-44', NULL, 'comprehensive_test', 'reading', NULL, 'Economic hardship can weaken public support for a government and encourage attempts to overthrow it.', 'Dựa vào câu trên, từ “overthrow” có nghĩa phù hợp nhất là gì?', '["hệ thống điện báo; máy điện báo","lật đổ; đánh đổ","sâu sắc; sâu xa; lớn lao","người cư ngụ; người sử dụng; hành khách (trên xe)"]'::jsonb, 1, 'overthrow: lật đổ; đánh đổ; sự lật đổ; sự sụp đổ của chính quyền. Dịch cả câu: Khó khăn kinh tế có thể làm suy yếu sự ủng hộ của công chúng đối với chính phủ và kích thích các nỗ lực lật đổ chính quyền đó.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_21', 'en-c1-44', NULL, 'comprehensive_test', 'reading', NULL, 'Employers may be held liable for injuries caused by unsafe conditions in the workplace.', 'Dựa vào câu trên, từ “liable” có nghĩa phù hợp nhất là gì?', '["tàn phá; phá hủy nghiêm trọng","có khả năng xảy ra, dễ bị (đặc biệt là điều bất lợi)","né tránh; lảng tránh (để không bị va chạm)","sự leo trèo, sự đi lên phía trên"]'::jsonb, 1, 'liable: có khả năng xảy ra, dễ bị (đặc biệt là điều bất lợi); chịu trách nhiệm pháp lý (đặc biệt là về bồi thường thiệt hại hoặc thanh toán). Dịch cả câu: Người sử dụng lao động có thể phải chịu trách nhiệm pháp lý đối với các thương tích do điều kiện không an toàn tại nơi làm việc gây ra.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_22', 'en-c1-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “làm chứng; cung cấp lời khai”', '["mirage","perspire","harmonious","testify"]'::jsonb, 3, 'làm chứng; cung cấp lời khai → testify (/ˈtestɪfaɪ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_23', 'en-c1-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vô hiệu lực; không có giá trị pháp lý”', '["tremor","syndrome","frugal","null"]'::jsonb, 3, 'vô hiệu lực; không có giá trị pháp lý → null (/nʌl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_44_24', 'en-c1-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hợp pháp; đúng pháp luật”', '["constraint","lawful","longing","nickel"]'::jsonb, 1, 'hợp pháp; đúng pháp luật → lawful (/ˈlɔːfl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-45', 'en', 'Bài 45: Chính phủ & Pháp luật (2) - CEFR C1', 'CEFR C1', 'C1 · Chính phủ & Pháp luật', '24 từ vựng Tiếng Anh CEFR C1 chủ đề chính phủ & pháp luật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5045, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prosecution', 'en-c1-45', 'prosecution', '/ˌprɑːsɪˈkjuːʃən/', 'C1', 'sự truy tố; quá trình khởi tố hình sự; bên nguyên tố; phía khởi xướng tố tụng', 'n.', 'prosecute (v.), prosecutor (n.)', 'Trái nghĩa: defence', 'the prosecution chỉ bên nguyên cáo trong vụ án hình sự, không phải nguyên đơn dân sự.', 'The shop owner faced prosecution for selling stolen bicycles.', NULL, 'Chủ cửa hàng phải đối mặt với việc bị truy tố vì bán xe đạp trộm cắp.', '{"wordId":"prosecution","ukIpa":"/ˌprɒsɪˈkjuːʃən/","usIpa":"/ˌprɑːsɪˈkjuːʃən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"The legal process of charging and trying someone for a crime.","vi":"sự truy tố; quá trình khởi tố hình sự"},{"pos":"n.","en":"The lawyers trying to prove an accused person committed a crime.","vi":"bên nguyên tố; phía khởi xướng tố tụng"}],"examples":[{"en":"The shop owner faced prosecution for selling stolen bicycles.","vi":"Chủ cửa hàng phải đối mặt với việc bị truy tố vì bán xe đạp trộm cắp.","audioKind":"ex"},{"en":"Effective prosecution of environmental offences requires reliable evidence and sufficient resources for specialist legal teams.","vi":"Quá trình truy tố hiệu quả các tội danh về môi trường đòi hỏi phải có bằng chứng đáng tin cậy và nguồn lực đầy đủ cho các đội ngũ pháp lý chuyên trách.","audioKind":"ex2"}],"collocations":[{"en":"face prosecution","vi":"đối mặt với việc truy tố"},{"en":"criminal prosecution","vi":"truy tố hình sự"},{"en":"the prosecution case","vi":"lập luận của bên nguyên"},{"en":"prosecution witness","vi":"nhân chứng của bên nguyên"}],"wordFamily":["prosecute (v.)","prosecutor (n.)"],"synonyms":[],"antonyms":["defence"],"tipVi":"the prosecution chỉ bên nguyên cáo trong vụ án hình sự, không phải nguyên đơn dân sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prosecutor', 'en-c1-45', 'prosecutor', '/ˈprɑːsɪkjuːtər/', 'C1', 'công tố viên; kiểm sát viên', 'n.', 'prosecute (v.), prosecution (n.)', NULL, 'Đại diện cho bên nguyên đơn để đưa ra cáo buộc; không có thẩm quyền đưa ra phán quyết.', 'The prosecutor asked the witness about the missing bicycle.', NULL, 'Công tố viên đã hỏi nhân chứng về chiếc xe đạp bị mất tích.', '{"wordId":"prosecutor","ukIpa":"/ˈprɒsɪkjuːtə/","usIpa":"/ˈprɑːsɪkjuːtər/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A lawyer who presents a criminal case against an accused person.","vi":"công tố viên; kiểm sát viên"}],"examples":[{"en":"The prosecutor asked the witness about the missing bicycle.","vi":"Công tố viên đã hỏi nhân chứng về chiếc xe đạp bị mất tích.","audioKind":"ex"},{"en":"An independent prosecutor can help ensure that criminal cases are handled fairly without inappropriate political interference.","vi":"Một công tố viên độc lập có thể giúp đảm bảo các vụ án hình sự được xử lý công bằng mà không vấp phải sự can thiệp chính trị không phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"public prosecutor","vi":"công tố viên nhà nước"},{"en":"chief prosecutor","vi":"viện kiểm sát trưởng"},{"en":"lead prosecutor","vi":"công tố viên chính"}],"wordFamily":["prosecute (v.)","prosecution (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Đại diện cho bên nguyên đơn để đưa ra cáo buộc; không có thẩm quyền đưa ra phán quyết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_convict', 'en-c1-45', 'convict', '/ˈkɑːnvɪkt/', 'C1', 'tù nhân; người đã bị kết án; kết án; tuyên bố có tội', 'n.', 'conviction (n), convicted (adj)', 'Đồng nghĩa: prisoner · Trái nghĩa: acquit', 'Danh từ được nhấn trọng âm ở âm tiết đầu, động từ được nhấn ở âm tiết thứ hai; khi kết án tội gì dùng giới từ of.', 'The former convict now works at a local bakery.', NULL, 'Cựu tù nhân này hiện đang làm việc tại một tiệm bánh địa phương.', '{"wordId":"convict","ukIpa":"/ˈkɒnvɪkt/","usIpa":"/ˈkɑːnvɪkt/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"Someone found guilty of a crime, especially someone in prison.","vi":"tù nhân; người đã bị kết án"},{"pos":"v.","en":"To officially find someone guilty of a crime in court.","vi":"kết án; tuyên bố có tội"}],"examples":[{"en":"The former convict now works at a local bakery.","vi":"Cựu tù nhân này hiện đang làm việc tại một tiệm bánh địa phương.","audioKind":"ex"},{"en":"Education programmes can help a convict develop practical skills and prepare for employment after release from prison.","vi":"Các chương trình giáo dục có thể giúp người chấp hành án phát triển các kỹ năng thực tế và chuẩn bị cho việc làm sau khi mãn hạn tù.","audioKind":"ex2"}],"collocations":[{"en":"a convicted offender","vi":"kẻ phạm tội đã bị kết án"},{"en":"convict someone of theft","vi":"kết án tù nhân vì tội trộm cắp"},{"en":"a former convict","vi":"một cựu tù nhân"}],"wordFamily":["conviction (n)","convicted (adj)"],"synonyms":["prisoner"],"antonyms":["acquit"],"tipVi":"Danh từ được nhấn trọng âm ở âm tiết đầu, động từ được nhấn ở âm tiết thứ hai; khi kết án tội gì dùng giới từ of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relinquish', 'en-c1-45', 'relinquish', '/rɪˈlɪŋkwɪʃ/', 'C1', 'từ bỏ; giao lại; nhường lại', 'v.', 'relinquishment (n.)', 'Đồng nghĩa: give up, surrender · Trái nghĩa: retain', 'Đây là ngoại động từ mang tính trang trọng, thường đi trực tiếp với control, power, rights.', 'She reluctantly relinquished her seat beside the window.', NULL, 'Cô ấy miễn cưỡng nhường lại chỗ ngồi cạnh cửa sổ của mình.', '{"wordId":"relinquish","ukIpa":"/rɪˈlɪŋkwɪʃ/","usIpa":"/rɪˈlɪŋkwɪʃ/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"Give up control, possession or a right to something.","vi":"từ bỏ; giao lại; nhường lại"}],"examples":[{"en":"She reluctantly relinquished her seat beside the window.","vi":"Cô ấy miễn cưỡng nhường lại chỗ ngồi cạnh cửa sổ của mình.","audioKind":"ex"},{"en":"National governments may be reluctant to relinquish control over energy policy to international organisations.","vi":"Các chính phủ quốc gia có thể miễn cưỡng từ bỏ quyền kiểm soát chính sách năng lượng đối với các tổ chức quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"relinquish control","vi":"từ bỏ quyền kiểm soát"},{"en":"relinquish power","vi":"giao nộp quyền lực"},{"en":"relinquish a claim","vi":"từ bỏ quyền đòi hỏi"}],"wordFamily":["relinquishment (n.)"],"synonyms":["give up","surrender"],"antonyms":["retain"],"tipVi":"Đây là ngoại động từ mang tính trang trọng, thường đi trực tiếp với control, power, rights.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sovereignty', 'en-c1-45', 'sovereignty', '/ˈsɑːvrənti/', 'C1', 'chủ quyền; quyền lực tối cao', 'n.', 'sovereign (adj.), sovereign (n.)', NULL, 'Thường không đếm được; nói về chủ quyền đối với một vùng lãnh thổ nào đó thì dùng giới từ over.', 'We discussed national sovereignty in our history class today.', NULL, 'Chúng tôi đã thảo luận về chủ quyền quốc gia trong tiết học lịch sử hôm nay.', '{"wordId":"sovereignty","ukIpa":"/ˈsɒvrənti/","usIpa":"/ˈsɑːvrənti/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A country''s independent authority to govern itself.","vi":"chủ quyền; quyền lực tối cao"}],"examples":[{"en":"We discussed national sovereignty in our history class today.","vi":"Chúng tôi đã thảo luận về chủ quyền quốc gia trong tiết học lịch sử hôm nay.","audioKind":"ex"},{"en":"International agreements can promote cooperation while respecting the sovereignty of each country involved.","vi":"Các hiệp ước quốc tế có thể thúc đẩy sự hợp tác đồng thời tôn trọng chủ quyền của mỗi quốc gia tham gia.","audioKind":"ex2"}],"collocations":[{"en":"national sovereignty","vi":"chủ quyền quốc gia"},{"en":"territorial sovereignty","vi":"chủ quyền lãnh thổ"},{"en":"respect sovereignty","vi":"tôn trọng chủ quyền"},{"en":"exercise sovereignty","vi":"thực thi chủ quyền"}],"wordFamily":["sovereign (adj.)","sovereign (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường không đếm được; nói về chủ quyền đối với một vùng lãnh thổ nào đó thì dùng giới từ over.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supreme', 'en-c1-45', 'supreme', '/suːˈpriːm/', 'C1', 'tối cao; cao nhất về cấp bậc, quyền hạn hoặc tầm quan trọng; cực độ; lớn nhất có thể', 'adj.', 'supremely (adv.), supremacy (n.)', 'Đồng nghĩa: highest, ultimate', 'Bản thân từ này đã mang nghĩa "tối cao", nên thường không dùng ở dạng so sánh hơn hoặc so sánh nhất.', 'The council has supreme authority over the island.', NULL, 'Hội đồng nắm giữ quyền lực tối cao đối với hòn đảo.', '{"wordId":"supreme","ukIpa":"/suːˈpriːm/","usIpa":"/suːˈpriːm/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"highest in rank, authority, or importance","vi":"tối cao; cao nhất về cấp bậc, quyền hạn hoặc tầm quan trọng"},{"pos":"adj.","en":"of the greatest possible degree","vi":"cực độ; lớn nhất có thể"}],"examples":[{"en":"The council has supreme authority over the island.","vi":"Hội đồng nắm giữ quyền lực tối cao đối với hòn đảo.","audioKind":"ex"},{"en":"In many countries, the supreme court can review whether new legislation complies with the constitution.","vi":"Ở nhiều quốc gia, tòa án tối cao có quyền xem xét liệu các đạo luật mới có tuân thủ hiến pháp hay không.","audioKind":"ex2"}],"collocations":[{"en":"supreme court","vi":"tòa án tối cao"},{"en":"supreme authority","vi":"quyền lực tối cao"},{"en":"supreme confidence","vi":"sự tự tin tuyệt đối"}],"wordFamily":["supremely (adv.)","supremacy (n.)"],"synonyms":["highest","ultimate"],"antonyms":[],"tipVi":"Bản thân từ này đã mang nghĩa \"tối cao\", nên thường không dùng ở dạng so sánh hơn hoặc so sánh nhất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_precedence', 'en-c1-45', 'precedence', '/ˈpresɪdəns/', 'C1', 'quyền ưu tiên; sự ưu tiên; vị trí cao hơn', 'n.', NULL, 'Đồng nghĩa: priority', 'Thường dùng cấu trúc take precedence over để chỉ việc được ưu tiên hơn cái gì đó.', 'At home, homework takes precedence over video games.', NULL, 'Ở nhà, việc làm bài tập được ưu tiên hơn chơi trò chơi điện tử.', '{"wordId":"precedence","ukIpa":"/ˈpresɪdəns/","usIpa":"/ˈpresɪdəns/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"Greater importance that gives someone or something priority over others.","vi":"quyền ưu tiên; sự ưu tiên; vị trí cao hơn"}],"examples":[{"en":"At home, homework takes precedence over video games.","vi":"Ở nhà, việc làm bài tập được ưu tiên hơn chơi trò chơi điện tử.","audioKind":"ex"},{"en":"Public safety should take precedence over commercial interests when governments develop regulations for new transport technologies.","vi":"An toàn công cộng nên được đặt lên trên lợi ích thương mại khi chính phủ xây dựng các quy định cho công nghệ giao thông mới.","audioKind":"ex2"}],"collocations":[{"en":"take precedence over","vi":"ưu tiên hơn; đặt lên trên"},{"en":"give precedence to","vi":"ưu tiên cho"},{"en":"have precedence over","vi":"có quyền ưu tiên hơn"}],"wordFamily":[],"synonyms":["priority"],"antonyms":[],"tipVi":"Thường dùng cấu trúc take precedence over để chỉ việc được ưu tiên hơn cái gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scrutiny', 'en-c1-45', 'scrutiny', '/ˈskruːtəni/', 'C1', 'sự xem xét kỹ lưỡng; sự kiểm tra chi tiết', 'n.', 'scrutinise (v.)', 'Đồng nghĩa: examination, inspection', 'Là danh từ không đếm được; cụm từ under scrutiny có nghĩa là đang chịu sự giám sát nghiêm ngặt.', 'The jeweller examined the ring with intense scrutiny.', NULL, 'Người thợ kim hoàn đã kiểm tra chiếc nhẫn một cách cực kỳ kỹ lưỡng.', '{"wordId":"scrutiny","ukIpa":"/ˈskruːtɪni/","usIpa":"/ˈskruːtəni/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"Careful examination of something, especially to find faults or problems.","vi":"sự xem xét kỹ lưỡng; sự kiểm tra chi tiết"}],"examples":[{"en":"The jeweller examined the ring with intense scrutiny.","vi":"Người thợ kim hoàn đã kiểm tra chiếc nhẫn một cách cực kỳ kỹ lưỡng.","audioKind":"ex"},{"en":"Public spending should be subject to independent scrutiny to ensure that resources are used efficiently and fairly.","vi":"Chi tiêu công nên chịu sự giám sát độc lập để đảm bảo các nguồn lực được sử dụng hiệu quả và công bằng.","audioKind":"ex2"}],"collocations":[{"en":"under scrutiny","vi":"chịu sự giám sát"},{"en":"close scrutiny","vi":"xem xét kỹ lưỡng"},{"en":"public scrutiny","vi":"sự giám sát của công chúng"},{"en":"subject to scrutiny","vi":"chịu sự kiểm tra"}],"wordFamily":["scrutinise (v.)"],"synonyms":["examination","inspection"],"antonyms":[],"tipVi":"Là danh từ không đếm được; cụm từ under scrutiny có nghĩa là đang chịu sự giám sát nghiêm ngặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lenient', 'en-c1-45', 'lenient', '/ˈliːniənt/', 'C1', 'khoan dung; nhân nhượng; không quá nghiêm khắc', 'adj.', 'leniency (n.), leniently (adv.)', 'Đồng nghĩa: tolerant, permissive · Trái nghĩa: strict, harsh', 'Dùng cấu trúc lenient with khi nói về thái độ khoan dung với ai; thường liên quan đến quy tắc hoặc hình phạt.', 'Our teacher was lenient when I submitted homework late.', NULL, 'Giáo viên đã rất khoan dung khi tôi nộp bài tập muộn.', '{"wordId":"lenient","ukIpa":"/ˈliːniənt/","usIpa":"/ˈliːniənt/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"less strict or severe when enforcing rules or giving punishment","vi":"khoan dung; nhân nhượng; không quá nghiêm khắc"}],"examples":[{"en":"Our teacher was lenient when I submitted homework late.","vi":"Giáo viên đã rất khoan dung khi tôi nộp bài tập muộn.","audioKind":"ex"},{"en":"Some argue that lenient penalties for illegal dumping fail to discourage companies from damaging the environment.","vi":"Một số người lập luận rằng các hình phạt khoan dung đối với hành vi xả rác trái phép không đủ sức răn đe các công ty tàn phá môi trường.","audioKind":"ex2"}],"collocations":[{"en":"lenient with someone","vi":"khoan dung với ai đó"},{"en":"a lenient sentence","vi":"một bản án khoan hồng"},{"en":"lenient treatment","vi":"sự đối xử khoan dung"}],"wordFamily":["leniency (n.)","leniently (adv.)"],"synonyms":["tolerant","permissive"],"antonyms":["strict","harsh"],"tipVi":"Dùng cấu trúc lenient with khi nói về thái độ khoan dung với ai; thường liên quan đến quy tắc hoặc hình phạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_autonomy', 'en-c1-45', 'autonomy', '/ɔːˈtɑːnəmi/', 'C1', 'quyền tự chủ; quyền tự trị', 'n.', 'autonomous (adj.), autonomously (adv.)', 'Đồng nghĩa: independence, self-government · Trái nghĩa: dependence', 'Thường là danh từ không đếm được; dùng cho cả tự trị vùng miền lẫn tự chủ cá nhân hoặc tổ chức.', 'My new manager gives me more autonomy at work.', NULL, 'Người quản lý mới cho tôi nhiều quyền tự chủ hơn trong công việc.', '{"wordId":"autonomy","ukIpa":"/ɔːˈtɒnəmi/","usIpa":"/ɔːˈtɑːnəmi/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"The freedom or right to make decisions independently.","vi":"quyền tự chủ; quyền tự trị"}],"examples":[{"en":"My new manager gives me more autonomy at work.","vi":"Người quản lý mới cho tôi nhiều quyền tự chủ hơn trong công việc.","audioKind":"ex"},{"en":"Giving schools greater autonomy may help teachers adapt their lessons to the specific needs of local communities.","vi":"Việc trao quyền tự chủ lớn hơn cho các trường học có thể giúp giáo viên điều chỉnh bài giảng phù hợp với nhu cầu cụ thể của cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"greater autonomy","vi":"quyền tự chủ lớn hơn"},{"en":"regional autonomy","vi":"quyền tự trị khu vực"},{"en":"individual autonomy","vi":"quyền tự chủ cá nhân"},{"en":"grant autonomy","vi":"cấp quyền tự chủ"}],"wordFamily":["autonomous (adj.)","autonomously (adv.)"],"synonyms":["independence","self-government"],"antonyms":["dependence"],"tipVi":"Thường là danh từ không đếm được; dùng cho cả tự trị vùng miền lẫn tự chủ cá nhân hoặc tổ chức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_census', 'en-c1-45', 'census', '/ˈsensəs/', 'C1', 'cuộc tổng điều tra dân số; phép kiểm kê dân số', 'n.', NULL, NULL, 'census điều tra toàn bộ dân số, trong khi sample survey chỉ mang tính chất khảo sát mẫu.', 'We completed the census form at our kitchen table.', NULL, 'Chúng tôi đã hoàn thành tờ khai tổng điều tra dân số ngay tại bàn ăn trong bếp.', '{"wordId":"census","ukIpa":"/ˈsensəs/","usIpa":"/ˈsensəs/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"an official count of people that collects information about them","vi":"cuộc tổng điều tra dân số; phép kiểm kê dân số"}],"examples":[{"en":"We completed the census form at our kitchen table.","vi":"Chúng tôi đã hoàn thành tờ khai tổng điều tra dân số ngay tại bàn ăn trong bếp.","audioKind":"ex"},{"en":"Census data help governments plan housing, schools and healthcare services according to changing population needs.","vi":"Dữ liệu tổng điều tra dân số giúp chính phủ lập kế hoạch về nhà ở, trường học và dịch vụ y tế phù hợp với nhu cầu thay đổi của dân cư.","audioKind":"ex2"}],"collocations":[{"en":"conduct a census","vi":"tiến hành tổng điều tra dân số"},{"en":"census data","vi":"dữ liệu tổng điều tra dân số"},{"en":"a national census","vi":"cuộc tổng điều tra dân số quốc gia"},{"en":"a census form","vi":"tờ khai tổng điều tra dân số"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"census điều tra toàn bộ dân số, trong khi sample survey chỉ mang tính chất khảo sát mẫu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infringement', 'en-c1-45', 'infringement', '/ɪnˈfrɪndʒmənt/', 'C1', 'sự vi phạm; sự xâm phạm', 'n.', 'infringe (v.)', 'Đồng nghĩa: violation, breach', 'Thường đi với giới từ of; infringement of rights có nghĩa là xâm phạm quyền lợi.', 'Copying that photograph without permission could be copyright infringement.', NULL, 'Việc sao chép bức ảnh đó mà không có sự cho phép có thể cấu thành tội xâm phạm bản quyền.', '{"wordId":"infringement","ukIpa":"/ɪnˈfrɪndʒmənt/","usIpa":"/ɪnˈfrɪndʒmənt/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"An action that breaks a law or violates someone''s rights.","vi":"sự vi phạm; sự xâm phạm"}],"examples":[{"en":"Copying that photograph without permission could be copyright infringement.","vi":"Việc sao chép bức ảnh đó mà không có sự cho phép có thể cấu thành tội xâm phạm bản quyền.","audioKind":"ex"},{"en":"Governments should protect creative workers by imposing appropriate penalties for the infringement of intellectual property rights.","vi":"Chính phủ nên bảo vệ những người làm sáng tạo bằng cách áp dụng các hình phạt thích đáng đối với hành vi xâm phạm quyền sở hữu trí tuệ.","audioKind":"ex2"}],"collocations":[{"en":"copyright infringement","vi":"sự xâm phạm bản quyền"},{"en":"patent infringement","vi":"sự vi phạm bằng sáng chế"},{"en":"infringement of rights","vi":"sự xâm phạm quyền lợi"}],"wordFamily":["infringe (v.)"],"synonyms":["violation","breach"],"antonyms":[],"tipVi":"Thường đi với giới từ of; infringement of rights có nghĩa là xâm phạm quyền lợi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expressly', 'en-c1-45', 'expressly', '/ɪkˈspresli/', 'C1', 'rõ ràng; thẳng thắn; dứt khoát; đặc biệt; chuyên biệt', 'adv.', 'express (v.), expression (n.)', 'Đồng nghĩa: explicitly, specifically · Trái nghĩa: implicitly', 'Đừng nhầm lẫn với expressively, từ này có nghĩa là giàu biểu cảm.', 'I expressly asked for a room away from the lift.', NULL, 'Tôi đã dứt khoát yêu cầu một phòng ở xa thang máy.', '{"wordId":"expressly","ukIpa":"/ɪkˈspresli/","usIpa":"/ɪkˈspresli/","cefr":"C1","topic":"government","senses":[{"pos":"adv.","en":"in a clear and direct way that leaves no doubt","vi":"rõ ràng; thẳng thắn; dứt khoát"},{"pos":"adv.","en":"for a particular purpose","vi":"đặc biệt; chuyên biệt"}],"examples":[{"en":"I expressly asked for a room away from the lift.","vi":"Tôi đã dứt khoát yêu cầu một phòng ở xa thang máy.","audioKind":"ex"},{"en":"Public funds allocated expressly for environmental protection should not be diverted to projects that increase industrial pollution.","vi":"Các quỹ công cộng được phân bổ chuyên biệt cho việc bảo vệ môi trường không nên bị chuyển hướng sang các dự án làm gia tăng ô nhiễm công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"expressly prohibit","vi":"cấm ngặt; cấm tuyệt đối"},{"en":"expressly state","vi":"tuyên bố rõ ràng"},{"en":"expressly for","vi":"đặc biệt dành cho"}],"wordFamily":["express (v.)","expression (n.)"],"synonyms":["explicitly","specifically"],"antonyms":["implicitly"],"tipVi":"Đừng nhầm lẫn với expressively, từ này có nghĩa là giàu biểu cảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_allegiance', 'en-c1-45', 'allegiance', '/əˈliːdʒəns/', 'C1', 'sự trung thành; lòng trung thành; sự quy thuận', 'n.', NULL, 'Đồng nghĩa: loyalty, devotion · Trái nghĩa: disloyalty', 'Đối tượng trung thành được đi kèm với giới từ to: allegiance to a country.', 'Despite moving abroad, he kept his allegiance to his hometown club.', NULL, 'Mặc dù chuyển ra nước ngoài sinh sống, anh ấy vẫn giữ lòng trung thành với câu lạc bộ quê hương.', '{"wordId":"allegiance","ukIpa":"/əˈliːdʒəns/","usIpa":"/əˈliːdʒəns/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"Loyalty and support given to a country, group, or leader.","vi":"sự trung thành; lòng trung thành; sự quy thuận"}],"examples":[{"en":"Despite moving abroad, he kept his allegiance to his hometown club.","vi":"Mặc dù chuyển ra nước ngoài sinh sống, anh ấy vẫn giữ lòng trung thành với câu lạc bộ quê hương.","audioKind":"ex"},{"en":"Political allegiance can influence how voters interpret economic policies and assess the performance of elected officials.","vi":"Lòng trung thành chính trị có thể ảnh hưởng đến cách cử tri diễn giải các chính sách kinh tế và đánh giá năng lực của các quan chức đắc cử.","audioKind":"ex2"}],"collocations":[{"en":"pledge allegiance to","vi":"tuyên thệ trung thành với"},{"en":"political allegiance","vi":"lòng trung thành chính trị"},{"en":"switch allegiance","vi":"quay sang phò tá/trung thành với bên khác"}],"wordFamily":[],"synonyms":["loyalty","devotion"],"antonyms":["disloyalty"],"tipVi":"Đối tượng trung thành được đi kèm với giới từ to: allegiance to a country.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_faction', 'en-c1-45', 'faction', '/ˈfækʃən/', 'C1', 'bè phái; phe phái; nhóm nhỏ đối lập', 'n.', 'factional (adj.), factionalism (n.)', 'Đồng nghĩa: camp, splinter group', 'Thường chỉ những nhóm nhỏ có quan điểm mâu thuẫn với phần còn lại trong một tập thể lớn, hay dùng trong chính trị.', 'One faction of our club wants a new leader.', NULL, 'Một phe phái trong câu lạc bộ của chúng ta muốn đổi một người lãnh đạo mới.', '{"wordId":"faction","ukIpa":"/ˈfækʃən/","usIpa":"/ˈfækʃən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A subgroup whose views conflict with others in a larger group.","vi":"bè phái; phe phái; nhóm nhỏ đối lập"}],"examples":[{"en":"One faction of our club wants a new leader.","vi":"Một phe phái trong câu lạc bộ của chúng ta muốn đổi một người lãnh đạo mới.","audioKind":"ex"},{"en":"A powerful faction within the ruling party opposed the proposed reforms to the national education system.","vi":"Một bè phái có thế lực trong đảng cầm quyền đã phản đối các cải tổ được đề xuất đối với hệ thống giáo dục quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"rival factions","vi":"các phe phái đối địch"},{"en":"political faction","vi":"phe phái chính trị"},{"en":"a faction within the party","vi":"một bè phái trong nội bộ đảng"}],"wordFamily":["factional (adj.)","factionalism (n.)"],"synonyms":["camp","splinter group"],"antonyms":[],"tipVi":"Thường chỉ những nhóm nhỏ có quan điểm mâu thuẫn với phần còn lại trong một tập thể lớn, hay dùng trong chính trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uphold', 'en-c1-45', 'uphold', '/ʌpˈhoʊld/', 'C1', 'ủng hộ; bảo vệ; duy trì; giữ nguyên; xác nhận', 'v.', NULL, 'Đồng nghĩa: maintain, defend · Trái nghĩa: overturn', 'Quá khứ và quá khứ phân từ đều là upheld; thường kết hợp với quyền lợi hoặc phán quyết.', 'Our coach always tries to uphold fair play.', NULL, 'Huấn luyện viên của chúng tôi luôn cố gắng duy trì tinh thần chơi đẹp.', '{"wordId":"uphold","ukIpa":"/ʌpˈhəʊld/","usIpa":"/ʌpˈhoʊld/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To support and maintain a principle, right, or standard","vi":"ủng hộ; bảo vệ; duy trì"},{"pos":"v.","en":"To confirm that an earlier decision remains valid","vi":"giữ nguyên; xác nhận"}],"examples":[{"en":"Our coach always tries to uphold fair play.","vi":"Huấn luyện viên của chúng tôi luôn cố gắng duy trì tinh thần chơi đẹp.","audioKind":"ex"},{"en":"Independent courts help uphold citizens'' rights by ensuring that public authorities act within the law.","vi":"Các tòa án độc lập giúp bảo vệ quyền lợi của công dân bằng cách đảm bảo các cơ quan công quyền hoạt động trong khuôn khổ pháp luật.","audioKind":"ex2"}],"collocations":[{"en":"uphold the law","vi":"thượng tôn pháp luật"},{"en":"uphold human rights","vi":"bảo vệ nhân quyền"},{"en":"uphold a decision","vi":"giữ nguyên quyết định"},{"en":"uphold standards","vi":"duy trì tiêu chuẩn"}],"wordFamily":[],"synonyms":["maintain","defend"],"antonyms":["overturn"],"tipVi":"Quá khứ và quá khứ phân từ đều là upheld; thường kết hợp với quyền lợi hoặc phán quyết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_asylum', 'en-c1-45', 'asylum', '/əˈsaɪləm/', 'C1', 'sự tị nạn; quyền tị nạn chính trị; trại tâm thần (cách gọi cũ)', 'n.', NULL, 'Đồng nghĩa: refuge, protection', 'Khi chỉ sự bảo vệ, tị nạn là danh từ không đếm được; dùng chỉ bệnh viện tâm thần là cách nói lỗi thời.', 'Her family sought asylum after fleeing their home country.', NULL, 'Gia đình cô ấy đã xin tị nạn sau khi trốn chạy khỏi quê hương.', '{"wordId":"asylum","ukIpa":"/əˈsaɪləm/","usIpa":"/əˈsaɪləm/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"Protection a country gives people escaping danger in another country.","vi":"sự tị nạn; quyền tị nạn chính trị"},{"pos":"n.","en":"An old term for a hospital for people with mental illnesses.","vi":"trại tâm thần (cách gọi cũ)"}],"examples":[{"en":"Her family sought asylum after fleeing their home country.","vi":"Gia đình cô ấy đã xin tị nạn sau khi trốn chạy khỏi quê hương.","audioKind":"ex"},{"en":"Governments should assess asylum applications fairly while ensuring that vulnerable applicants have access to legal advice.","vi":"Chính phủ nên đánh giá các đơn xin tị nạn một cách công bằng đồng thời đảm bảo những người xin tị nạn dễ bị tổn thương có thể tiếp cận sự tư vấn pháp lý.","audioKind":"ex2"}],"collocations":[{"en":"seek asylum","vi":"xin tị nạn"},{"en":"grant asylum","vi":"cấp quyền tị nạn"},{"en":"asylum seeker","vi":"người tìm kiếm quyền tị nạn"},{"en":"political asylum","vi":"tị nạn chính trị"}],"wordFamily":[],"synonyms":["refuge","protection"],"antonyms":[],"tipVi":"Khi chỉ sự bảo vệ, tị nạn là danh từ không đếm được; dùng chỉ bệnh viện tâm thần là cách nói lỗi thời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hereby', 'en-c1-45', 'hereby', '/ˌhɪrˈbaɪ/', 'C1', 'bằng văn bản này; theo đây', 'adv.', NULL, NULL, 'Dùng cho văn bản hoặc thông báo mang tính chính thức, thường được đặt ngay sau chủ ngữ và trước động từ chính.', 'I hereby give you permission to use my photographs.', NULL, 'Tôi xin phép trao cho bạn quyền sử dụng các bức ảnh của tôi.', '{"wordId":"hereby","ukIpa":"/ˌhɪəˈbaɪ/","usIpa":"/ˌhɪrˈbaɪ/","cefr":"C1","topic":"government","senses":[{"pos":"adv.","en":"By means of this statement or official action.","vi":"bằng văn bản này; theo đây"}],"examples":[{"en":"I hereby give you permission to use my photographs.","vi":"Tôi xin phép trao cho bạn quyền sử dụng các bức ảnh của tôi.","audioKind":"ex"},{"en":"The council hereby authorises the conversion of unused public buildings into affordable housing for local residents.","vi":"Hội đồng xin chính thức phê chuẩn việc chuyển đổi các tòa nhà công cộng chưa sử dụng thành nhà ở xã hội cho cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"hereby declare","vi":"trợt tuyên bố"},{"en":"hereby authorise","vi":"xin chính thức ủy quyền"},{"en":"hereby agree","vi":"xin đồng ý"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng cho văn bản hoặc thông báo mang tính chính thức, thường được đặt ngay sau chủ ngữ và trước động từ chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monarch', 'en-c1-45', 'monarch', '/ˈmɑːnərk/', 'C1', 'vua hoặc nữ hoàng đóng vai trò là nguyên thủ quốc gia', 'n.', 'monarchy (n.), monarchical (adj.), monarchist (n.)', 'Đồng nghĩa: sovereign', 'Có thể chỉ vua hoặc nữ hoàng, không hạn chế giới tính; chế độ gọi là monarchy.', 'The monarch waved to the crowd from the palace balcony.', NULL, 'Nhà vua vẫy tay chào đám đông từ ban công cung điện.', '{"wordId":"monarch","ukIpa":"/ˈmɒnək/","usIpa":"/ˈmɑːnərk/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A king or queen who serves as head of state","vi":"vua hoặc nữ hoàng đóng vai trò là nguyên thủ quốc gia"}],"examples":[{"en":"The monarch waved to the crowd from the palace balcony.","vi":"Nhà vua vẫy tay chào đám đông từ ban công cung điện.","audioKind":"ex"},{"en":"In a constitutional monarchy, the monarch usually performs ceremonial duties while elected representatives exercise political power.","vi":"Trong chế độ quân chủ lập hiến, nhà vua thường thực hiện các nhiệm vụ nghi lễ trong khi các đại biểu dân cử nắm giữ quyền lực chính trị.","audioKind":"ex2"}],"collocations":[{"en":"constitutional monarch","vi":"quân chủ lập hiến"},{"en":"reigning monarch","vi":"quân chủ tại vị"},{"en":"absolute monarch","vi":"quân chủ chuyên chế"}],"wordFamily":["monarchy (n.)","monarchical (adj.)","monarchist (n.)"],"synonyms":["sovereign"],"antonyms":[],"tipVi":"Có thể chỉ vua hoặc nữ hoàng, không hạn chế giới tính; chế độ gọi là monarchy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amendment', 'en-c1-45', 'amendment', '/əˈmendmənt/', 'C1', 'sự sửa đổi; điều khoản bổ sung; bản sửa đổi', 'n.', 'amend (v.), amended (adj.)', 'Đồng nghĩa: revision, modification', 'Khi chỉ việc sửa đổi một tài liệu nào đó, hãy dùng amendment to.', 'We agreed on one small amendment to the contract.', NULL, 'Chúng tôi đã thống nhất về một sửa đổi nhỏ trong hợp đồng.', '{"wordId":"amendment","ukIpa":"/əˈmendmənt/","usIpa":"/əˈmendmənt/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A change made to a law, document, or proposal.","vi":"sự sửa đổi; điều khoản bổ sung; bản sửa đổi"}],"examples":[{"en":"We agreed on one small amendment to the contract.","vi":"Chúng tôi đã thống nhất về một sửa đổi nhỏ trong hợp đồng.","audioKind":"ex"},{"en":"The proposed amendment would require employers to provide safer working conditions for temporary staff.","vi":"Bản sửa đổi được đề xuất sẽ yêu cầu các chủ lao động cung cấp điều kiện làm việc an toàn hơn cho nhân viên thời vụ.","audioKind":"ex2"}],"collocations":[{"en":"make an amendment","vi":"thực hiện sửa đổi"},{"en":"propose an amendment","vi":"đề xuất bản sửa đổi"},{"en":"constitutional amendment","vi":"tu chính án hiến pháp"},{"en":"amendment to a law","vi":"sửa đổi luật"}],"wordFamily":["amend (v.)","amended (adj.)"],"synonyms":["revision","modification"],"antonyms":[],"tipVi":"Khi chỉ việc sửa đổi một tài liệu nào đó, hãy dùng amendment to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_canvass', 'en-c1-45', 'canvass', '/ˈkænvəs/', 'C1', 'vận động bầu cử; đi vận động lá phiếu; thăm dò ý kiến; khảo sát ý kiến', 'v.', 'canvasser (n.), canvassing (n.)', 'Đồng nghĩa: solicit, poll', 'canvass là vận động tranh cử hoặc thăm dò ý kiến; canvas chỉ vải bạt.', 'Volunteers canvassed the neighbourhood before the local election.', NULL, 'Các tình nguyện viên đã đi đến từng khu1 xóm để vận động tranh cử trước cuộc bầu cử địa phương.', '{"wordId":"canvass","ukIpa":"/ˈkænvəs/","usIpa":"/ˈkænvəs/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To approach people and ask for their votes or support.","vi":"vận động bầu cử; đi vận động lá phiếu"},{"pos":"v.","en":"To ask people about their opinions on a particular issue.","vi":"thăm dò ý kiến; khảo sát ý kiến"}],"examples":[{"en":"Volunteers canvassed the neighbourhood before the local election.","vi":"Các tình nguyện viên đã đi đến từng khu1 xóm để vận động tranh cử trước cuộc bầu cử địa phương.","audioKind":"ex"},{"en":"Local authorities should canvass residents'' views before introducing major changes to public transport routes and schedules.","vi":"Chính quyền địa phương nên thăm dò ý kiến cư dân trước khi đưa ra những thay đổi lớn về tuyến đường và lịch trình giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"canvass for votes","vi":"vận động bầu cử"},{"en":"canvass support","vi":"vận động sự ủng hộ"},{"en":"canvass opinions","vi":"thăm dò ý kiến"}],"wordFamily":["canvasser (n.)","canvassing (n.)"],"synonyms":["solicit","poll"],"antonyms":[],"tipVi":"canvass là vận động tranh cử hoặc thăm dò ý kiến; canvas chỉ vải bạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manifesto', 'en-c1-45', 'manifesto', '/ˌmænɪˈfestoʊ/', 'C1', 'bản tuyên ngôn; cương lĩnh', 'n.', NULL, NULL, 'Dạng số nhiều của từ này có thể viết là manifestos hoặc manifestoes.', 'Our club published a manifesto calling for cleaner parks.', NULL, 'Câu lạc bộ của chúng tôi đã công bố một bản tuyên ngôn kêu gọi giữ cho các công viên sạch sẽ hơn.', '{"wordId":"manifesto","ukIpa":"/ˌmænɪˈfestəʊ/","usIpa":"/ˌmænɪˈfestoʊ/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A public statement of a group''s beliefs, aims, and planned actions.","vi":"bản tuyên ngôn; cương lĩnh"}],"examples":[{"en":"Our club published a manifesto calling for cleaner parks.","vi":"Câu lạc bộ của chúng tôi đã công bố một bản tuyên ngôn kêu gọi giữ cho các công viên sạch sẽ hơn.","audioKind":"ex"},{"en":"The party''s manifesto promises greater investment in public transport to reduce congestion in major cities.","vi":"Cương lĩnh tranh cử của đảng cam kết đầu tư mạnh mẽ hơn vào giao thông công cộng nhằm giảm ùn tắc ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"publish a manifesto","vi":"công bố bản tuyên ngôn"},{"en":"election manifesto","vi":"cương lĩnh bầu cử"},{"en":"party manifesto","vi":"cương lĩnh chính đảng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều của từ này có thể viết là manifestos hoặc manifestoes.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_treason', 'en-c1-45', 'treason', '/ˈtriːzən/', 'C1', 'tội phản quốc', 'n.', 'treasonous (adj.)', NULL, 'Thường là danh từ không đếm được, chỉ hành vi phản bội đất nước nghiêm trọng.', 'The museum guide explained why the official faced treason charges.', NULL, 'Hướng dẫn viên bảo tàng giải thích lý do tại sao vị quan chức đó phải đối mặt với các cáo buộc phản quốc.', '{"wordId":"treason","ukIpa":"/ˈtriːzən/","usIpa":"/ˈtriːzən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"The crime of betraying your country, especially by helping its enemies.","vi":"tội phản quốc"}],"examples":[{"en":"The museum guide explained why the official faced treason charges.","vi":"Hướng dẫn viên bảo tàng giải thích lý do tại sao vị quan chức đó phải đối mặt với các cáo buộc phản quốc.","audioKind":"ex"},{"en":"Historical trials for treason reveal how governments have defined loyalty and responded to perceived threats.","vi":"Các phiên tòa lịch sử xét xử tội phản quốc cho thấy cách các chính phủ định nghĩa lòng trung thành và phản ứng trước những mối đe dọa được cho là nguy hiểm.","audioKind":"ex2"}],"collocations":[{"en":"commit treason","vi":"phạm tội phản quốc"},{"en":"charged with treason","vi":"bị buộc tội phản quốc"},{"en":"high treason","vi":"tội phản quốc đặc biệt nghiêm trọng"}],"wordFamily":["treasonous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được, chỉ hành vi phản bội đất nước nghiêm trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exempt', 'en-c1-45', 'exempt', '/ɪɡˈzempt/', 'C1', 'được miễn; được miễn trừ; miễn; miễn trừ', 'adj.', 'exemption (n.)', 'Đồng nghĩa: excused · Trái nghĩa: liable', 'Cụm từ cố định: be exempt from; exempt sb from.', 'Children under five are exempt from the entrance fee.', NULL, 'Trẻ em dưới năm tuổi được miễn tiền vé vào cửa.', '{"wordId":"exempt","ukIpa":"/ɪɡˈzempt/","usIpa":"/ɪɡˈzempt/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"Not required to follow a rule or fulfil an obligation.","vi":"được miễn; được miễn trừ"},{"pos":"v.","en":"To release someone from a rule, payment, or obligation.","vi":"miễn; miễn trừ"}],"examples":[{"en":"Children under five are exempt from the entrance fee.","vi":"Trẻ em dưới năm tuổi được miễn tiền vé vào cửa.","audioKind":"ex"},{"en":"Governments could exempt small businesses from certain taxes to encourage investment and support local employment.","vi":"Chính phủ có thể miễn một số loại thuế cho các doanh nghiệp nhỏ nhằm khuyến khích đầu tư và hỗ trợ việc làm địa phương.","audioKind":"ex2"}],"collocations":[{"en":"exempt from tax","vi":"được miễn thuế"},{"en":"exempt someone from","vi":"miễn cho ai khỏi..."},{"en":"tax-exempt status","vi":"tư cách miễn thuế"}],"wordFamily":["exemption (n.)"],"synonyms":["excused"],"antonyms":["liable"],"tipVi":"Cụm từ cố định: be exempt from; exempt sb from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_45_1', 'en-c1-45', 'Cách dùng “faction” (n.) — bè phái; phe phái; nhóm nhỏ đối lập', 'rival factions  ·  political faction  ·  a faction within the party', 'Thường chỉ những nhóm nhỏ có quan điểm mâu thuẫn với phần còn lại trong một tập thể lớn, hay dùng trong chính trị.', 'Họ từ (Word Family): factional (adj.), factionalism (n.) | Đồng nghĩa: camp, splinter group', '[{"hanzi":"One faction of our club wants a new leader.","pinyin":"","meaning":"Một phe phái trong câu lạc bộ của chúng ta muốn đổi một người lãnh đạo mới."},{"hanzi":"A powerful faction within the ruling party opposed the proposed reforms to the national education system.","pinyin":"","meaning":"Một bè phái có thế lực trong đảng cầm quyền đã phản đối các cải tổ được đề xuất đối với hệ thống giáo dục quốc gia."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_45_2', 'en-c1-45', 'Cách dùng “convict” (n.) — tù nhân; người đã bị kết án', 'a convicted offender  ·  convict someone of theft  ·  a former convict', 'Danh từ được nhấn trọng âm ở âm tiết đầu, động từ được nhấn ở âm tiết thứ hai; khi kết án tội gì dùng giới từ of.', 'Họ từ (Word Family): conviction (n), convicted (adj) | Đồng nghĩa: prisoner · Trái nghĩa: acquit', '[{"hanzi":"The former convict now works at a local bakery.","pinyin":"","meaning":"Cựu tù nhân này hiện đang làm việc tại một tiệm bánh địa phương."},{"hanzi":"Education programmes can help a convict develop practical skills and prepare for employment after release from prison.","pinyin":"","meaning":"Các chương trình giáo dục có thể giúp người chấp hành án phát triển các kỹ năng thực tế và chuẩn bị cho việc làm sau khi mãn hạn tù."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_45_3', 'en-c1-45', 'Cách dùng “hereby” (adv.) — bằng văn bản này; theo đây', 'hereby declare  ·  hereby authorise  ·  hereby agree', 'Dùng cho văn bản hoặc thông báo mang tính chính thức, thường được đặt ngay sau chủ ngữ và trước động từ chính.', NULL, '[{"hanzi":"I hereby give you permission to use my photographs.","pinyin":"","meaning":"Tôi xin phép trao cho bạn quyền sử dụng các bức ảnh của tôi."},{"hanzi":"The council hereby authorises the conversion of unused public buildings into affordable housing for local residents.","pinyin":"","meaning":"Hội đồng xin chính thức phê chuẩn việc chuyển đổi các tòa nhà công cộng chưa sử dụng thành nhà ở xã hội cho cư dân địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_45_4', 'en-c1-45', 'Cách dùng “lenient” (adj.) — khoan dung; nhân nhượng; không quá nghiêm khắc', 'lenient with someone  ·  a lenient sentence  ·  lenient treatment', 'Dùng cấu trúc lenient with khi nói về thái độ khoan dung với ai; thường liên quan đến quy tắc hoặc hình phạt.', 'Họ từ (Word Family): leniency (n.), leniently (adv.) | Đồng nghĩa: tolerant, permissive · Trái nghĩa: strict, harsh', '[{"hanzi":"Our teacher was lenient when I submitted homework late.","pinyin":"","meaning":"Giáo viên đã rất khoan dung khi tôi nộp bài tập muộn."},{"hanzi":"Some argue that lenient penalties for illegal dumping fail to discourage companies from damaging the environment.","pinyin":"","meaning":"Một số người lập luận rằng các hình phạt khoan dung đối với hành vi xả rác trái phép không đủ sức răn đe các công ty tàn phá môi trường."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_45_1', 'en-c1-45', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_1_1', 'ten_c1_45_1', 'prosecution', 'The shop owner faced prosecution for selling stolen bicycles.', 'The shop owner faced prosecution for selling stolen bicycles.', '/ˌprɑːsɪˈkjuːʃən/', 'Chủ cửa hàng phải đối mặt với việc bị truy tố vì bán xe đạp trộm cắp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_1_2', 'ten_c1_45_1', 'prosecutor', 'The prosecutor asked the witness about the missing bicycle.', 'The prosecutor asked the witness about the missing bicycle.', '/ˈprɑːsɪkjuːtər/', 'Công tố viên đã hỏi nhân chứng về chiếc xe đạp bị mất tích.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_1_3', 'ten_c1_45_1', 'convict', 'The former convict now works at a local bakery.', 'The former convict now works at a local bakery.', '/ˈkɑːnvɪkt/', 'Cựu tù nhân này hiện đang làm việc tại một tiệm bánh địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_1_4', 'ten_c1_45_1', 'relinquish', 'She reluctantly relinquished her seat beside the window.', 'She reluctantly relinquished her seat beside the window.', '/rɪˈlɪŋkwɪʃ/', 'Cô ấy miễn cưỡng nhường lại chỗ ngồi cạnh cửa sổ của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
