INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_1_7', 'ten_c1_45_1', 'precedence', 'At home, homework takes precedence over video games.', 'At home, homework takes precedence over video games.', '/ˈpresɪdəns/', 'Ở nhà, việc làm bài tập được ưu tiên hơn chơi trò chơi điện tử.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_1_8', 'ten_c1_45_1', 'scrutiny', 'The jeweller examined the ring with intense scrutiny.', 'The jeweller examined the ring with intense scrutiny.', '/ˈskruːtəni/', 'Người thợ kim hoàn đã kiểm tra chiếc nhẫn một cách cực kỳ kỹ lưỡng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_45_1_1', 'en-c1-45', 'ten_c1_45_1', 'listening', 'listening', 'The shop owner faced prosecution for selling stolen bicycles.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi xin phép trao cho bạn quyền sử dụng các bức ảnh của tôi.","Nhà vua vẫy tay chào đám đông từ ban công cung điện.","Hội đồng nắm giữ quyền lực tối cao đối với hòn đảo.","Chủ cửa hàng phải đối mặt với việc bị truy tố vì bán xe đạp trộm cắp."]'::jsonb, 3, 'The shop owner faced prosecution for selling stolen bicycles. → Chủ cửa hàng phải đối mặt với việc bị truy tố vì bán xe đạp trộm cắp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_45_1_2', 'en-c1-45', 'ten_c1_45_1', 'listening', 'listening', 'The prosecutor asked the witness about the missing bicycle.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Công tố viên đã hỏi nhân chứng về chiếc xe đạp bị mất tích.","Tôi xin phép trao cho bạn quyền sử dụng các bức ảnh của tôi.","Cựu tù nhân này hiện đang làm việc tại một tiệm bánh địa phương.","Cô ấy miễn cưỡng nhường lại chỗ ngồi cạnh cửa sổ của mình."]'::jsonb, 0, 'The prosecutor asked the witness about the missing bicycle. → Công tố viên đã hỏi nhân chứng về chiếc xe đạp bị mất tích.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_45_1_3', 'en-c1-45', 'ten_c1_45_1', 'listening', 'listening', 'The former convict now works at a local bakery.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã dứt khoát yêu cầu một phòng ở xa thang máy.","Nhà vua vẫy tay chào đám đông từ ban công cung điện.","Cựu tù nhân này hiện đang làm việc tại một tiệm bánh địa phương.","Câu lạc bộ của chúng tôi đã công bố một bản tuyên ngôn kêu gọi giữ cho các công viên sạch sẽ hơn."]'::jsonb, 2, 'The former convict now works at a local bakery. → Cựu tù nhân này hiện đang làm việc tại một tiệm bánh địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_45_2', 'en-c1-45', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_2_1', 'ten_c1_45_2', 'prosecution', 'Effective prosecution of environmental offences requires reliable evidence and sufficient resources for specialist legal teams.', 'Effective prosecution of environmental offences requires reliable evidence and sufficient resources for specialist legal teams.', '/ˌprɑːsɪˈkjuːʃən/', 'Quá trình truy tố hiệu quả các tội danh về môi trường đòi hỏi phải có bằng chứng đáng tin cậy và nguồn lực đầy đủ cho các đội ngũ pháp lý chuyên trách.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_2_2', 'ten_c1_45_2', 'prosecutor', 'An independent prosecutor can help ensure that criminal cases are handled fairly without inappropriate political interference.', 'An independent prosecutor can help ensure that criminal cases are handled fairly without inappropriate political interference.', '/ˈprɑːsɪkjuːtər/', 'Một công tố viên độc lập có thể giúp đảm bảo các vụ án hình sự được xử lý công bằng mà không vấp phải sự can thiệp chính trị không phù hợp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_2_3', 'ten_c1_45_2', 'convict', 'Education programmes can help a convict develop practical skills and prepare for employment after release from prison.', 'Education programmes can help a convict develop practical skills and prepare for employment after release from prison.', '/ˈkɑːnvɪkt/', 'Các chương trình giáo dục có thể giúp người chấp hành án phát triển các kỹ năng thực tế và chuẩn bị cho việc làm sau khi mãn hạn tù.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_2_4', 'ten_c1_45_2', 'relinquish', 'National governments may be reluctant to relinquish control over energy policy to international organisations.', 'National governments may be reluctant to relinquish control over energy policy to international organisations.', '/rɪˈlɪŋkwɪʃ/', 'Các chính phủ quốc gia có thể miễn cưỡng từ bỏ quyền kiểm soát chính sách năng lượng đối với các tổ chức quốc tế.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_2_5', 'ten_c1_45_2', 'sovereignty', 'International agreements can promote cooperation while respecting the sovereignty of each country involved.', 'International agreements can promote cooperation while respecting the sovereignty of each country involved.', '/ˈsɑːvrənti/', 'Các hiệp ước quốc tế có thể thúc đẩy sự hợp tác đồng thời tôn trọng chủ quyền của mỗi quốc gia tham gia.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_45_2_6', 'ten_c1_45_2', 'supreme', 'In many countries, the supreme court can review whether new legislation complies with the constitution.', 'In many countries, the supreme court can review whether new legislation complies with the constitution.', '/suːˈpriːm/', 'Ở nhiều quốc gia, tòa án tối cao có quyền xem xét liệu các đạo luật mới có tuân thủ hiến pháp hay không.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_45_2_1', 'en-c1-45', 'ten_c1_45_2', 'listening', 'listening', 'Effective prosecution of environmental offences requires reliable evidence and sufficient resources for specialist legal teams.', NULL, 'Trong câu vừa nghe, từ “prosecution” mang nghĩa nào sau đây?', '["nhờ đó; theo đó","giải phẫu học","một sai lầm nghiêm trọng do bất cẩn hoặc thiếu phán đoán chuẩn xác","sự truy tố; quá trình khởi tố hình sự"]'::jsonb, 3, '“prosecution” (/ˌprɑːsɪˈkjuːʃən/): sự truy tố; quá trình khởi tố hình sự. Câu đầy đủ: Effective prosecution of environmental offences requires reliable evidence and sufficient resources for specialist legal teams.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_45_2_2', 'en-c1-45', 'ten_c1_45_2', 'listening', 'listening', 'An independent prosecutor can help ensure that criminal cases are handled fairly without inappropriate political interference.', NULL, 'Trong câu vừa nghe, từ “prosecutor” mang nghĩa nào sau đây?', '["kể lại; thuật lại","công tố viên; kiểm sát viên","rõ ràng; thẳng thắn; dứt khoát","quá mức kỹ tính; khó chiều; kén chọn"]'::jsonb, 1, '“prosecutor” (/ˈprɑːsɪkjuːtər/): công tố viên; kiểm sát viên. Câu đầy đủ: An independent prosecutor can help ensure that criminal cases are handled fairly without inappropriate political interference.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
