INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_1', 'en-c1-45', NULL, 'comprehensive_test', 'listening', 'prosecution', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bơm; xịt; phun","luận văn; luận án","sự truy tố; quá trình khởi tố hình sự","đường hô hấp; khí quản"]'::jsonb, 2, 'prosecution (/ˌprɑːsɪˈkjuːʃən/) → sự truy tố; quá trình khởi tố hình sự; bên nguyên tố; phía khởi xướng tố tụng', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_2', 'en-c1-45', NULL, 'comprehensive_test', 'listening', 'The prosecutor asked the witness about the missing bicycle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Các tình nguyện viên đã đi đến từng khu1 xóm để vận động tranh cử trước cuộc bầu cử địa phương.","Công tố viên đã hỏi nhân chứng về chiếc xe đạp bị mất tích.","Giáo viên đã rất khoan dung khi tôi nộp bài tập muộn.","Chúng tôi đã thống nhất về một sửa đổi nhỏ trong hợp đồng."]'::jsonb, 1, 'The prosecutor asked the witness about the missing bicycle. → Công tố viên đã hỏi nhân chứng về chiếc xe đạp bị mất tích.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_3', 'en-c1-45', NULL, 'comprehensive_test', 'listening', 'convict', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đào, khoét, khai đào","tù nhân; người đã bị kết án","tích lũy dần; thu về dần theo thời gian","nhỏ hơn, ít hơn, kém quan trọng hơn"]'::jsonb, 1, 'convict (/ˈkɑːnvɪkt/) → tù nhân; người đã bị kết án; kết án; tuyên bố có tội', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_4', 'en-c1-45', NULL, 'comprehensive_test', 'listening', 'She reluctantly relinquished her seat beside the window.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy miễn cưỡng nhường lại chỗ ngồi cạnh cửa sổ của mình.","Ở nhà, việc làm bài tập được ưu tiên hơn chơi trò chơi điện tử.","Giáo viên đã rất khoan dung khi tôi nộp bài tập muộn.","Người thợ kim hoàn đã kiểm tra chiếc nhẫn một cách cực kỳ kỹ lưỡng."]'::jsonb, 0, 'She reluctantly relinquished her seat beside the window. → Cô ấy miễn cưỡng nhường lại chỗ ngồi cạnh cửa sổ của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_5', 'en-c1-45', NULL, 'comprehensive_test', 'listening', 'sovereignty', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiếng ồn ào; tiếng náo động kéo dài khó chịu","chủ quyền; quyền lực tối cao","xọc mạch; tọc mạch; dòm ngó chuyện riêng tư","thợ chuyển nhà; công ty chuyển đồ"]'::jsonb, 1, 'sovereignty (/ˈsɑːvrənti/) → chủ quyền; quyền lực tối cao', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_6', 'en-c1-45', NULL, 'comprehensive_test', 'listening', 'The council has supreme authority over the island.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chủ cửa hàng phải đối mặt với việc bị truy tố vì bán xe đạp trộm cắp.","Người thợ kim hoàn đã kiểm tra chiếc nhẫn một cách cực kỳ kỹ lưỡng.","Huấn luyện viên của chúng tôi luôn cố gắng duy trì tinh thần chơi đẹp.","Hội đồng nắm giữ quyền lực tối cao đối với hòn đảo."]'::jsonb, 3, 'The council has supreme authority over the island. → Hội đồng nắm giữ quyền lực tối cao đối với hòn đảo.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_7', 'en-c1-45', NULL, 'comprehensive_test', 'listening', 'precedence', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chú ý; lắng nghe và làm theo","quyền ưu tiên; sự ưu tiên; vị trí cao hơn","tuyết lở","nỗi đau đớn dữ dội; sự hành hạ, sự dằn vặt"]'::jsonb, 1, 'precedence (/ˈpresɪdəns/) → quyền ưu tiên; sự ưu tiên; vị trí cao hơn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_8', 'en-c1-45', NULL, 'comprehensive_test', 'listening', 'The jeweller examined the ring with intense scrutiny.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người thợ kim hoàn đã kiểm tra chiếc nhẫn một cách cực kỳ kỹ lưỡng.","Mặc dù chuyển ra nước ngoài sinh sống, anh ấy vẫn giữ lòng trung thành với câu lạc bộ quê hương.","Công tố viên đã hỏi nhân chứng về chiếc xe đạp bị mất tích.","Chúng tôi đã hoàn thành tờ khai tổng điều tra dân số ngay tại bàn ăn trong bếp."]'::jsonb, 0, 'The jeweller examined the ring with intense scrutiny. → Người thợ kim hoàn đã kiểm tra chiếc nhẫn một cách cực kỳ kỹ lưỡng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
