INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_18', 'en-c1-45', NULL, 'comprehensive_test', 'reading', NULL, 'Effective prosecution of environmental offences requires reliable evidence and sufficient resources for specialist legal teams.', 'Dựa vào câu trên, từ “prosecution” có nghĩa phù hợp nhất là gì?', '["báo hiệu; báo trước","tiếng la ó om sòm; tiếng ồn ào; đòi hỏi bức xúc của công chúng","là đặc điểm của; tiêu biểu cho","sự truy tố; quá trình khởi tố hình sự"]'::jsonb, 3, 'prosecution: sự truy tố; quá trình khởi tố hình sự; bên nguyên tố; phía khởi xướng tố tụng. Dịch cả câu: Quá trình truy tố hiệu quả các tội danh về môi trường đòi hỏi phải có bằng chứng đáng tin cậy và nguồn lực đầy đủ cho các đội ngũ pháp lý chuyên trách.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_19', 'en-c1-45', NULL, 'comprehensive_test', 'reading', NULL, 'An independent prosecutor can help ensure that criminal cases are handled fairly without inappropriate political interference.', 'Dựa vào câu trên, từ “prosecutor” có nghĩa phù hợp nhất là gì?', '["tăng dần; dâng lên; leo lên","công tố viên; kiểm sát viên","sức bền; sự chịu đựng; độ dẻo dai","sự xuyên qua; sự thâm nhập"]'::jsonb, 1, 'prosecutor: công tố viên; kiểm sát viên. Dịch cả câu: Một công tố viên độc lập có thể giúp đảm bảo các vụ án hình sự được xử lý công bằng mà không vấp phải sự can thiệp chính trị không phù hợp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_20', 'en-c1-45', NULL, 'comprehensive_test', 'reading', NULL, 'Education programmes can help a convict develop practical skills and prepare for employment after release from prison.', 'Dựa vào câu trên, từ “convict” có nghĩa phù hợp nhất là gì?', '["tù nhân; người đã bị kết án","hất cẳng; lật đổ; truất ngôi","thuốc an thần; thuốc trấn tĩnh","xa hoa; phung phí; đắt đỏ"]'::jsonb, 0, 'convict: tù nhân; người đã bị kết án; kết án; tuyên bố có tội. Dịch cả câu: Các chương trình giáo dục có thể giúp người chấp hành án phát triển các kỹ năng thực tế và chuẩn bị cho việc làm sau khi mãn hạn tù.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_21', 'en-c1-45', NULL, 'comprehensive_test', 'reading', NULL, 'National governments may be reluctant to relinquish control over energy policy to international organisations.', 'Dựa vào câu trên, từ “relinquish” có nghĩa phù hợp nhất là gì?', '["từ bỏ; giao lại; nhường lại","thông số; tham số","đàn (côn trùng); bầy","sự khác biệt; sự mâu thuẫn; sự bất đồng"]'::jsonb, 0, 'relinquish: từ bỏ; giao lại; nhường lại. Dịch cả câu: Các chính phủ quốc gia có thể miễn cưỡng từ bỏ quyền kiểm soát chính sách năng lượng đối với các tổ chức quốc tế.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_22', 'en-c1-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bản tuyên ngôn; cương lĩnh”', '["arable","dilute","exempt","manifesto"]'::jsonb, 3, 'bản tuyên ngôn; cương lĩnh → manifesto (/ˌmænɪˈfestoʊ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_23', 'en-c1-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tội phản quốc”', '["specification","treason","assault","computation"]'::jsonb, 1, 'tội phản quốc → treason (/ˈtriːzən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_45_24', 'en-c1-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “được miễn; được miễn trừ”', '["exempt","renaissance","radial","lesser"]'::jsonb, 0, 'được miễn; được miễn trừ → exempt (/ɪɡˈzempt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-46', 'en', 'Bài 46: Chính phủ & Pháp luật (3) - CEFR C1', 'CEFR C1', 'C1 · Chính phủ & Pháp luật', '23 từ vựng Tiếng Anh CEFR C1 chủ đề chính phủ & pháp luật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5046, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chamber', 'en-c1-46', 'chamber', '/ˈtʃeɪmbər/', 'C1', 'phòng họp; hội trường; phòng chức năng (thường dùng cho mục đích chính thức); buồng; khoang (không gian khép kín trong cơ thể, máy móc hoặc cấu trúc)', 'n.', NULL, NULL, 'Từ chamber thường chỉ các căn phòng chuyên dụng cho mục đích chính thức hoặc các khoang khép kín, không phải phòng ngủ thông thường.', 'We waited outside the chamber while the council met.', NULL, 'Chúng tôi đứng chờ bên ngoài phòng họp trong khi hội đồng đang họp.', '{"wordId":"chamber","ukIpa":"/ˈtʃeɪmbə/","usIpa":"/ˈtʃeɪmbər/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A room used for a particular, often official, purpose.","vi":"phòng họp; hội trường; phòng chức năng (thường dùng cho mục đích chính thức)"},{"pos":"n.","en":"An enclosed space inside a body, machine, or structure.","vi":"buồng; khoang (không gian khép kín trong cơ thể, máy móc hoặc cấu trúc)"}],"examples":[{"en":"We waited outside the chamber while the council met.","vi":"Chúng tôi đứng chờ bên ngoài phòng họp trong khi hội đồng đang họp.","audioKind":"ex"},{"en":"The upper chamber of parliament reviews proposed laws before they can receive final approval.","vi":"Thượng viện của quốc hội tiến hành xem xét các dự luật trước khi chúng được phê duyệt chính thức.","audioKind":"ex2"}],"collocations":[{"en":"council chamber","vi":"phòng họp hội đồng"},{"en":"heart chamber","vi":"buồng tim"},{"en":"chamber of commerce","vi":"phòng thương mại"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ chamber thường chỉ các căn phòng chuyên dụng cho mục đích chính thức hoặc các khoang khép kín, không phải phòng ngủ thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_allocate', 'en-c1-46', 'allocate', '/ˈæləkeɪt/', 'C1', 'phân bổ; cấp phát', 'v.', 'allocation (n.), reallocate (v.)', 'Đồng nghĩa: assign, allot', 'allocate sth to sb/sth biểu thị việc phân bổ vật gì cho ai hoặc cho một mục đích cụ thể.', 'We allocated one cupboard to all our baking equipment.', NULL, 'Chúng tôi đã dành riêng một chiếc tủ cho tất cả dụng cụ làm bánh của mình.', '{"wordId":"allocate","ukIpa":"/ˈæləkeɪt/","usIpa":"/ˈæləkeɪt/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To assign resources to particular people, activities, or purposes.","vi":"phân bổ; cấp phát"}],"examples":[{"en":"We allocated one cupboard to all our baking equipment.","vi":"Chúng tôi đã dành riêng một chiếc tủ cho tất cả dụng cụ làm bánh của mình.","audioKind":"ex"},{"en":"Local authorities should allocate more funding to public transport in areas with limited access to essential services.","vi":"Chính quyền địa phương nên phân bổ nhiều kinh phí hơn cho giao thông công cộng ở những khu vực khó tiếp cận các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"allocate resources","vi":"phân bổ tài nguyên"},{"en":"allocate funds to","vi":"phân bổ quỹ cho"},{"en":"allocate time for","vi":"dành thời gian cho"}],"wordFamily":["allocation (n.)","reallocate (v.)"],"synonyms":["assign","allot"],"antonyms":[],"tipVi":"allocate sth to sb/sth biểu thị việc phân bổ vật gì cho ai hoặc cho một mục đích cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_premier', 'en-c1-46', 'premier', '/prɪˈmɪr/', 'C1', 'thủ tướng; thủ hiến; người đứng đầu chính phủ cấp vùng; hàng đầu; tối quan trọng; xuất sắc nhất', 'n.', NULL, NULL, 'Premier có thể chỉ người đứng đầu chính phủ; premiere dùng để chỉ buổi ra mắt hoặc công chiếu phim.', 'The premier visited our village after the river flooded.', NULL, 'Thủ tướng đã đến thăm làng chúng tôi sau trận lũ lụt.', '{"wordId":"premier","ukIpa":"/ˈpremiə/","usIpa":"/prɪˈmɪr/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"The head of a national or regional government.","vi":"thủ tướng; thủ hiến; người đứng đầu chính phủ cấp vùng"},{"pos":"adj.","en":"Considered the best or most important of its kind.","vi":"hàng đầu; tối quan trọng; xuất sắc nhất"}],"examples":[{"en":"The premier visited our village after the river flooded.","vi":"Thủ tướng đã đến thăm làng chúng tôi sau trận lũ lụt.","audioKind":"ex"},{"en":"The premier announced new measures to improve access to affordable housing in rapidly growing cities.","vi":"Thủ tướng đã công bố các biện pháp mới nhằm cải thiện khả năng tiếp cận nhà ở giá rẻ ở các thành phố đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"the newly elected premier","vi":"thủ tướng mới đắc cử"},{"en":"a provincial premier","vi":"thủ hiến cấp tỉnh"},{"en":"a premier research institution","vi":"viện nghiên cứu hàng đầu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Premier có thể chỉ người đứng đầu chính phủ; premiere dùng để chỉ buổi ra mắt hoặc công chiếu phim.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regime', 'en-c1-46', 'regime', '/reɪˈʒiːm/', 'C1', 'chế độ; chính quyền; hệ thống quản lý; chế độ sinh hoạt', 'n.', NULL, NULL, 'Khi chỉ chính quyền thường mang sắc thái tiêu cực hoặc chuyên quyền; cũng có thể chỉ hệ thống thuế khóa hoặc kế hoạch tập luyện.', 'The new regime promised to reopen the public library.', NULL, 'Chính quyền mới đã hứa mở cửa lại thư viện công cộng.', '{"wordId":"regime","ukIpa":"/reɪˈʒiːm/","usIpa":"/reɪˈʒiːm/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"a government or system of government, especially an authoritarian one","vi":"chế độ; chính quyền"},{"pos":"n.","en":"an organized system of rules or regular activities","vi":"hệ thống quản lý; chế độ sinh hoạt"}],"examples":[{"en":"The new regime promised to reopen the public library.","vi":"Chính quyền mới đã hứa mở cửa lại thư viện công cộng.","audioKind":"ex"},{"en":"An authoritarian regime may restrict public debate, making it harder for citizens to influence government decisions.","vi":"Một chính quyền độc tài có thể hạn chế tranh luận công khai, khiến công dân khó khăn hơn trong việc gây ảnh hưởng đến các quyết định của chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"authoritarian regime","vi":"chính quyền độc tài"},{"en":"tax regime","vi":"hệ thống thuế"},{"en":"exercise regime","vi":"chế độ tập luyện"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chính quyền thường mang sắc thái tiêu cực hoặc chuyên quyền; cũng có thể chỉ hệ thống thuế khóa hoặc kế hoạch tập luyện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_defendant', 'en-c1-46', 'defendant', '/dɪˈfendənt/', 'C1', 'bị cáo; bên bị đơn', 'n.', 'defend (v.), defence (n.), defensive (adj.), defender (n.)', 'Trái nghĩa: plaintiff', 'Bị cáo không đồng nghĩa với tội phạm; nguyên đơn plaintiff chủ yếu được dùng trong các vụ kiện dân sự.', 'The defendant sat quietly beside her lawyer in court.', NULL, 'Bị cáo ngồi lặng lẽ bên cạnh luật sư của mình tại tòa án.', '{"wordId":"defendant","ukIpa":"/dɪˈfendənt/","usIpa":"/dɪˈfendənt/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A person or organisation facing a legal claim or criminal charge.","vi":"bị cáo; bên bị đơn"}],"examples":[{"en":"The defendant sat quietly beside her lawyer in court.","vi":"Bị cáo ngồi lặng lẽ bên cạnh luật sư của mình tại tòa án.","audioKind":"ex"},{"en":"Every defendant should have access to legal advice, regardless of their income or social background.","vi":"Mỗi bị cáo đều nên được tiếp cận dịch vụ tư vấn pháp lý, bất kể thu nhập hay hoàn cảnh xã hội của họ ra sao.","audioKind":"ex2"}],"collocations":[{"en":"a criminal defendant","vi":"bị cáo trong vụ án hình sự"},{"en":"the defendant''s lawyer","vi":"luật sư của bị cáo"},{"en":"the rights of defendants","vi":"quyền của các bị cáo"}],"wordFamily":["defend (v.)","defence (n.)","defensive (adj.)","defender (n.)"],"synonyms":[],"antonyms":["plaintiff"],"tipVi":"Bị cáo không đồng nghĩa với tội phạm; nguyên đơn plaintiff chủ yếu được dùng trong các vụ kiện dân sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_verdict', 'en-c1-46', 'verdict', '/ˈvɝːdɪkt/', 'C1', 'lệnh tuyên án; phán quyết của tòa án; ý kiến; nhận định; đánh giá', 'n.', NULL, 'Đồng nghĩa: judgment, decision', 'verdict chỉ phán quyết; sentence dùng làm danh từ pháp lý chỉ hình phạt được tuyên.', 'What is your verdict on my homemade soup?', NULL, 'Bạn thấy món súp tôi tự nấu thế nào?', '{"wordId":"verdict","ukIpa":"/ˈvɜːdɪkt/","usIpa":"/ˈvɝːdɪkt/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"An official court decision about whether someone is guilty.","vi":"lệnh tuyên án; phán quyết của tòa án"},{"pos":"n.","en":"An opinion or judgment reached after considering something.","vi":"ý kiến; nhận định; đánh giá"}],"examples":[{"en":"What is your verdict on my homemade soup?","vi":"Bạn thấy món súp tôi tự nấu thế nào?","audioKind":"ex"},{"en":"A jury should reach its verdict solely on the evidence presented during the trial.","vi":"Bồi thẩm đoàn nên đưa ra phán quyết chỉ dựa trên các bằng chứng được trình bày trong phiên tòa.","audioKind":"ex2"}],"collocations":[{"en":"reach a verdict","vi":"đưa ra phán quyết"},{"en":"a guilty verdict","vi":"phán quyết có tội"},{"en":"return a verdict","vi":"tuyên bố phán quyết"},{"en":"a verdict on something","vi":"đánh giá về điều gì"}],"wordFamily":[],"synonyms":["judgment","decision"],"antonyms":[],"tipVi":"verdict chỉ phán quyết; sentence dùng làm danh từ pháp lý chỉ hình phạt được tuyên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_municipal', 'en-c1-46', 'municipal', '/mjuːˈnɪsɪpəl/', 'C1', 'thuộc về thành phố; thuộc về đô thị; cấp thành phố', 'adj.', 'municipality (n.)', NULL, 'Nhấn mạnh các vấn đề do chính quyền thị trấn hoặc thành phố quản lý, không dùng cho mọi khía cạnh đô thị.', 'The municipal swimming pool opens early on Saturdays.', NULL, 'Hồ bơi của thành phố mở cửa từ rất sớm vào các ngày thứ Bảy.', '{"wordId":"municipal","ukIpa":"/mjuːˈnɪsɪpəl/","usIpa":"/mjuːˈnɪsɪpəl/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"Relating to a town or city and its government.","vi":"thuộc về thành phố; thuộc về đô thị; cấp thành phố"}],"examples":[{"en":"The municipal swimming pool opens early on Saturdays.","vi":"Hồ bơi của thành phố mở cửa từ rất sớm vào các ngày thứ Bảy.","audioKind":"ex"},{"en":"Investment in municipal services can improve public health and reduce inequality in rapidly growing cities.","vi":"Việc đầu tư vào các dịch vụ đô thị có thể cải thiện sức khỏe cộng đồng và giảm bớt bất bình đẳng ở các thành phố đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"municipal government","vi":"chính quyền thành phố"},{"en":"municipal services","vi":"dịch vụ đô thị"},{"en":"municipal waste","vi":"rác thải thành phố"}],"wordFamily":["municipality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh các vấn đề do chính quyền thị trấn hoặc thành phố quản lý, không dùng cho mọi khía cạnh đô thị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_republican', 'en-c1-46', 'republican', '/rɪˈpʌblɪkən/', 'C1', 'thuộc về thể chế cộng hòa, theo chủ nghĩa cộng hòa; người theo chủ nghĩa cộng hòa, người ủng hộ chế độ cộng hòa', 'adj.', 'republic (n.), republicanism (n.)', 'Trái nghĩa: monarchist', 'Khi viết thường chỉ chủ nghĩa cộng hòa; khi viết hoa thường chỉ đảng phái chính trị cụ thể (Đảng Cộng hòa).', 'My uncle often discusses republican ideas over dinner.', NULL, 'Chú tôi thường bàn luận về các tư tưởng cộng hòa trong bữa tối.', '{"wordId":"republican","ukIpa":"/rɪˈpʌblɪkən/","usIpa":"/rɪˈpʌblɪkən/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"Supporting government without a monarch, usually through elected representatives","vi":"thuộc về thể chế cộng hòa, theo chủ nghĩa cộng hòa"},{"pos":"n.","en":"Someone who supports a republic rather than a monarchy","vi":"người theo chủ nghĩa cộng hòa, người ủng hộ chế độ cộng hòa"}],"examples":[{"en":"My uncle often discusses republican ideas over dinner.","vi":"Chú tôi thường bàn luận về các tư tưởng cộng hòa trong bữa tối.","audioKind":"ex"},{"en":"A republican constitution typically establishes a head of state whose position is not inherited through a royal family.","vi":"Một bản hiến pháp theo thể chế cộng hòa thường quy định nguyên thủ quốc gia không phải là chiếc ghế quyền lực được truyền ngôi qua các thế hệ hoàng tộc.","audioKind":"ex2"}],"collocations":[{"en":"republican government","vi":"chính phủ theo thể chế cộng hòa"},{"en":"republican ideals","vi":"lý tưởng cộng hòa"},{"en":"republican constitution","vi":"hiến pháp nước cộng hòa"}],"wordFamily":["republic (n.)","republicanism (n.)"],"synonyms":[],"antonyms":["monarchist"],"tipVi":"Khi viết thường chỉ chủ nghĩa cộng hòa; khi viết hoa thường chỉ đảng phái chính trị cụ thể (Đảng Cộng hòa).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_designation', 'en-c1-46', 'designation', '/ˌdezɪɡˈneɪʃən/', 'C1', 'sự chỉ định; sự bổ nhiệm; sự phân loại; tên gọi chính thức; chức danh', 'n.', 'designate (v.), designated (adj.)', 'Đồng nghĩa: appointment, title', 'Cấu trúc designation as đi kèm với thân phận hoặc chức vụ; cũng có thể chỉ danh xưng hoặc chức danh chính thức.', 'Her designation as team leader surprised nobody at work.', NULL, 'Việc cô ấy được bổ nhiệm làm trưởng nhóm không khiến ai ở nơi làm việc bất ngờ.', '{"wordId":"designation","ukIpa":"/ˌdezɪɡˈneɪʃən/","usIpa":"/ˌdezɪɡˈneɪʃən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"The act of officially choosing someone or something for a purpose.","vi":"sự chỉ định; sự bổ nhiệm; sự phân loại"},{"pos":"n.","en":"An official name or title given to someone or something.","vi":"tên gọi chính thức; chức danh"}],"examples":[{"en":"Her designation as team leader surprised nobody at work.","vi":"Việc cô ấy được bổ nhiệm làm trưởng nhóm không khiến ai ở nơi làm việc bất ngờ.","audioKind":"ex"},{"en":"The designation of coastal wetlands as protected areas can help preserve biodiversity and limit inappropriate development.","vi":"Việc công nhận các vùng đất ngập nước ven biển là khu vực bảo tồn có thể giúp gìn giữ sự đa dạng sinh học và hạn chế việc phát triển không phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"designation as","vi":"được bổ nhiệm làm"},{"en":"official designation","vi":"danh hiệu chính thức"},{"en":"job designation","vi":"chức danh công việc"}],"wordFamily":["designate (v.)","designated (adj.)"],"synonyms":["appointment","title"],"antonyms":[],"tipVi":"Cấu trúc designation as đi kèm với thân phận hoặc chức vụ; cũng có thể chỉ danh xưng hoặc chức danh chính thức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restrictive', 'en-c1-46', 'restrictive', '/rɪˈstrɪktɪv/', 'C1', 'có tính hạn chế; khắt khe', 'adj.', 'restrict (v.), restriction (n.), restricted (adj.)', 'Đồng nghĩa: limiting · Trái nghĩa: permissive', 'Là tính từ; restrictive nhấn mạnh việc áp đặt các giới hạn, quy củ.', 'The club''s restrictive rules prevent us from bringing guests.', NULL, 'Các quy định hạn chế của câu lạc bộ không cho phép chúng tôi dẫn theo khách.', '{"wordId":"restrictive","ukIpa":"/rɪˈstrɪktɪv/","usIpa":"/rɪˈstrɪktɪv/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"Limiting what people can do or what is allowed.","vi":"có tính hạn chế; khắt khe"}],"examples":[{"en":"The club''s restrictive rules prevent us from bringing guests.","vi":"Các quy định hạn chế của câu lạc bộ không cho phép chúng tôi dẫn theo khách.","audioKind":"ex"},{"en":"Overly restrictive planning regulations can discourage investment and delay the construction of affordable housing.","vi":"Các quy hoạch xây dựng quá khắt khe có thể làm nản lòng các nhà đầu tư và trì hoãn việc xây dựng nhà ở giá rẻ.","audioKind":"ex2"}],"collocations":[{"en":"restrictive regulations","vi":"quy định hạn chế"},{"en":"restrictive measures","vi":"biện pháp hạn chế"},{"en":"overly restrictive","vi":"quá mức hạn chế"}],"wordFamily":["restrict (v.)","restriction (n.)","restricted (adj.)"],"synonyms":["limiting"],"antonyms":["permissive"],"tipVi":"Là tính từ; restrictive nhấn mạnh việc áp đặt các giới hạn, quy củ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_secretariat', 'en-c1-46', 'secretariat', '/ˌsekrəˈteriət/', 'C1', 'ban thư ký; cơ quan hành chính', 'n.', 'secretary (n.), secretarial (adj.)', NULL, 'Chỉ cơ quan phụ trách công tác hành chính, không phải một thư ký cá nhân.', 'Please contact the secretariat to confirm your meeting time.', NULL, 'Vui lòng liên hệ với ban thư ký để xác nhận thời gian cuộc họp của bạn.', '{"wordId":"secretariat","ukIpa":"/ˌsekrəˈteəriət/","usIpa":"/ˌsekrəˈteriət/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"An office managing administrative work for a large organisation.","vi":"ban thư ký; cơ quan hành chính"}],"examples":[{"en":"Please contact the secretariat to confirm your meeting time.","vi":"Vui lòng liên hệ với ban thư ký để xác nhận thời gian cuộc họp của bạn.","audioKind":"ex"},{"en":"The secretariat coordinates international meetings and ensures that all member countries receive relevant information.","vi":"Ban thư ký điều phối các cuộc họp quốc tế và đảm bảo rằng tất cả các quốc gia thành viên nhận được thông tin liên quan.","audioKind":"ex2"}],"collocations":[{"en":"a permanent secretariat","vi":"một ban thư ký thường trực"},{"en":"the committee secretariat","vi":"ban thư ký ủy ban"},{"en":"establish a secretariat","vi":"thành lập một ban thư ký"}],"wordFamily":["secretary (n.)","secretarial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ cơ quan phụ trách công tác hành chính, không phải một thư ký cá nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_permissible', 'en-c1-46', 'permissible', '/pərˈmɪsəbl/', 'C1', 'được phép; hợp thức', 'adj.', 'permit (v.), permission (n.), permissibility (n.), impermissible (adj.)', 'Đồng nghĩa: allowable, allowed · Trái nghĩa: impermissible, forbidden', 'Cấu trúc thông dụng: It is permissible to do sth.', 'Is it permissible to take photographs inside this museum?', NULL, 'Có được phép chụp ảnh bên trong viện bảo tàng này không?', '{"wordId":"permissible","ukIpa":"/pəˈmɪsəbl/","usIpa":"/pərˈmɪsəbl/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"Allowed by a rule, law, or accepted standard","vi":"được phép; hợp thức"}],"examples":[{"en":"Is it permissible to take photographs inside this museum?","vi":"Có được phép chụp ảnh bên trong viện bảo tàng này không?","audioKind":"ex"},{"en":"Governments should establish clear limits on permissible emissions to protect public health in industrial areas.","vi":"Chính phủ nên thiết lập các giới hạn rõ ràng về mức độ phát thải cho phép để bảo vệ sức khỏe công cộng tại các khuindustrial areas.","audioKind":"ex2"}],"collocations":[{"en":"permissible limits","vi":"giới hạn cho phép"},{"en":"legally permissible","vi":"được pháp luật cho phép"},{"en":"permissible levels","vi":"mức độ cho phép"}],"wordFamily":["permit (v.)","permission (n.)","permissibility (n.)","impermissible (adj.)"],"synonyms":["allowable","allowed"],"antonyms":["impermissible","forbidden"],"tipVi":"Cấu trúc thông dụng: It is permissible to do sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_senator', 'en-c1-46', 'senator', '/ˈsenətər/', 'C1', 'thượng nghị sĩ', 'n.', 'senate (n.), senatorial (adj.)', NULL, 'senator là thượng nghị sĩ; senate là thượng viện.', 'The senator listened carefully to concerns at our community meeting.', NULL, 'Thượng nghị sĩ đã chăm chú lắng nghe các mối quan tâm tại buổi họp cộng đồng của chúng tôi.', '{"wordId":"senator","ukIpa":"/ˈsenətə/","usIpa":"/ˈsenətər/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A member of a senate, a lawmaking body","vi":"thượng nghị sĩ"}],"examples":[{"en":"The senator listened carefully to concerns at our community meeting.","vi":"Thượng nghị sĩ đã chăm chú lắng nghe các mối quan tâm tại buổi họp cộng đồng của chúng tôi.","audioKind":"ex"},{"en":"A senator may propose legislation to improve healthcare access, although approval requires support from other lawmakers.","vi":"Một thượng nghị sĩ có thể đề xuất dự luật cải thiện khả năng tiếp cận y tế, mặc dù việc phê duyệt cần có sự ủng hộ từ các nhà lập pháp khác.","audioKind":"ex2"}],"collocations":[{"en":"elect a senator","vi":"bầu thượng nghị sĩ"},{"en":"serve as a senator","vi":"làm thượng nghị sĩ"},{"en":"a senior senator","vi":"thượng nghị sĩ kỳ cựu"}],"wordFamily":["senate (n.)","senatorial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"senator là thượng nghị sĩ; senate là thượng viện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ballot', 'en-c1-46', 'ballot', '/ˈbælət/', 'C1', 'cuộc bỏ phiếu kín; sự biểu quyết; lá phiếu (giấy hoặc điện tử); tổ chức bỏ phiếu; tiến hành bầu cử', 'n.', NULL, 'Đồng nghĩa: vote', 'Danh từ ballot nhấn mạnh quy trình bỏ phiếu hoặc lá phiếu; cụm từ by secret ballot nghĩa là bỏ phiếu kín.', 'Our club chose its new chair by secret ballot.', NULL, 'Câu lạc bộ của chúng tôi đã chọn chủ tịch mới bằng hình thức bỏ phiếu kín.', '{"wordId":"ballot","ukIpa":"/ˈbælət/","usIpa":"/ˈbælət/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A process of voting, usually in secret.","vi":"cuộc bỏ phiếu kín; sự biểu quyết"},{"pos":"n.","en":"A paper or electronic form used to record a vote.","vi":"lá phiếu (giấy hoặc điện tử)"},{"pos":"v.","en":"To ask people to vote, or to vote yourself.","vi":"tổ chức bỏ phiếu; tiến hành bầu cử"}],"examples":[{"en":"Our club chose its new chair by secret ballot.","vi":"Câu lạc bộ của chúng tôi đã chọn chủ tịch mới bằng hình thức bỏ phiếu kín.","audioKind":"ex"},{"en":"A secret ballot allows citizens to express their political preferences without fear of pressure from others.","vi":"Cuộc bỏ phiếu kín cho phép công dân thể hiện quan điểm chính trị của mình mà không sợ bị người khác gây áp lực.","audioKind":"ex2"}],"collocations":[{"en":"secret ballot","vi":"bỏ phiếu kín"},{"en":"ballot paper","vi":"phiếu bầu"},{"en":"ballot box","vi":"hòm phiếu"},{"en":"hold a ballot","vi":"tổ chức bầu cử"}],"wordFamily":[],"synonyms":["vote"],"antonyms":[],"tipVi":"Danh từ ballot nhấn mạnh quy trình bỏ phiếu hoặc lá phiếu; cụm từ by secret ballot nghĩa là bỏ phiếu kín.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_safeguard', 'en-c1-46', 'safeguard', '/ˈseɪfɡɑːrd/', 'C1', 'bảo vệ; bảo đảm; biện pháp bảo vệ; điều khoản bảo đảm', 'v.', NULL, 'Đồng nghĩa: protect, defend · Trái nghĩa: endanger', 'Động từ thường đi với các tân ngữ chỉ quyền lợi; danh từ thường đi với against để chỉ đối tượng phòng ngừa.', 'These padded covers safeguard the furniture during the move.', NULL, 'Những chiếc vỏ bọc đệm lót này giúp bảo vệ đồ nội thất trong suốt quá trình chuyển nhà.', '{"wordId":"safeguard","ukIpa":"/ˈseɪfɡɑːd/","usIpa":"/ˈseɪfɡɑːrd/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To protect someone or something from harm or loss.","vi":"bảo vệ; bảo đảm"},{"pos":"n.","en":"A measure that prevents harm, loss, or unfair treatment.","vi":"biện pháp bảo vệ; điều khoản bảo đảm"}],"examples":[{"en":"These padded covers safeguard the furniture during the move.","vi":"Những chiếc vỏ bọc đệm lót này giúp bảo vệ đồ nội thất trong suốt quá trình chuyển nhà.","audioKind":"ex"},{"en":"Governments should introduce stronger regulations to safeguard personal information collected by online services and mobile applications.","vi":"Chính phủ nên ban hành các quy định chặt chẽ hơn để bảo vệ thông tin cá nhân do các dịch vụ trực tuyến và ứng dụng di động thu thập.","audioKind":"ex2"}],"collocations":[{"en":"safeguard rights","vi":"bảo vệ các quyền lợi"},{"en":"safeguard personal information","vi":"bảo vệ thông tin cá nhân"},{"en":"a safeguard against fraud","vi":"biện pháp phòng ngừa gian lận"}],"wordFamily":[],"synonyms":["protect","defend"],"antonyms":["endanger"],"tipVi":"Động từ thường đi với các tân ngữ chỉ quyền lợi; danh từ thường đi với against để chỉ đối tượng phòng ngừa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outlaw', 'en-c1-46', 'outlaw', '/ˈaʊtlɔː/', 'C1', 'ban hành lệnh cấm; tuyên bố là bất hợp pháp; kẻ ngoài vòng pháp luật; tội phạm truy nã; kẻ trốn chạy', 'v.', NULL, 'Đồng nghĩa: ban, prohibit · Trái nghĩa: legalise', 'Khi dùng như động từ, từ này đi thẳng tới hành động hoặc vật phẩm bị cấm.', 'The new rules outlaw dumping rubbish beside the river.', NULL, 'Quy định mới nghiêm cấm hành vi xả rác bừa bãi ven bờ sông.', '{"wordId":"outlaw","ukIpa":"/ˈaʊtlɔː/","usIpa":"/ˈaʊtlɔː/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"to make an activity illegal","vi":"ban hành lệnh cấm; tuyên bố là bất hợp pháp"},{"pos":"n.","en":"a criminal who lives outside the law","vi":"kẻ ngoài vòng pháp luật; tội phạm truy nã; kẻ trốn chạy"}],"examples":[{"en":"The new rules outlaw dumping rubbish beside the river.","vi":"Quy định mới nghiêm cấm hành vi xả rác bừa bãi ven bờ sông.","audioKind":"ex"},{"en":"Governments should outlaw the sale of products made from endangered species to discourage illegal hunting.","vi":"Chính phủ nên cấm buôn bán các sản phẩm làm từ động vật có nguy cơ tuyệt chủng để ngăn chặn tình trạng săn bắn trái phép.","audioKind":"ex2"}],"collocations":[{"en":"outlaw a practice","vi":"cấm một tập tục"},{"en":"outlaw discrimination","vi":"tuyên bố hành vi phân biệt đối xử là phi pháp"},{"en":"a notorious outlaw","vi":"một tên tội phạm khét tiếng"}],"wordFamily":[],"synonyms":["ban","prohibit"],"antonyms":["legalise"],"tipVi":"Khi dùng như động từ, từ này đi thẳng tới hành động hoặc vật phẩm bị cấm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_constituent', 'en-c1-46', 'constituent', '/kənˈstɪtʃuənt/', 'C1', 'cử tri; người dân trong khu vực bầu cử; thành phần; cấu phần; cấu tạo nên', 'n.', 'constituency (n.), constitute (v.)', NULL, 'Cử tri nghĩa có thể bao gồm cả những người chưa bỏ phiếu trong khu vực bầu cử; nghĩa thành phần gần với component.', 'A constituent asked her local representative about the closed library.', NULL, 'Một cử tri đã hỏi đại diện địa phương của cô ấy về việc đóng cửa thư viện.', '{"wordId":"constituent","ukIpa":"/kənˈstɪtʃuənt/","usIpa":"/kənˈstɪtʃuənt/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"a person living in an area represented by an elected official","vi":"cử tri; người dân trong khu vực bầu cử"},{"pos":"n.","en":"one of the parts or substances that form something","vi":"thành phần; cấu phần"},{"pos":"adj.","en":"forming part of a larger whole","vi":"thành phần; cấu tạo nên"}],"examples":[{"en":"A constituent asked her local representative about the closed library.","vi":"Một cử tri đã hỏi đại diện địa phương của cô ấy về việc đóng cửa thư viện.","audioKind":"ex"},{"en":"Elected representatives should consult their constituents before supporting policies that significantly affect local housing and public transport.","vi":"Các đại biểu dân cử nên tham khảo ý kiến cử tri của mình trước khi ủng hộ các chính sách ảnh hưởng đáng kể đến nhà ở địa phương và giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"local constituents","vi":"cử tri địa phương"},{"en":"constituent parts","vi":"các phần cấu thành"},{"en":"a major constituent","vi":"thành phần chính"}],"wordFamily":["constituency (n.)","constitute (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Cử tri nghĩa có thể bao gồm cả những người chưa bỏ phiếu trong khu vực bầu cử; nghĩa thành phần gần với component.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_violate', 'en-c1-46', 'violate', '/ˈvaɪəleɪt/', 'C1', 'vi phạm; làm trái; xâm phạm; xâm hại', 'v.', 'violation (n.), violator (n.)', 'Đồng nghĩa: breach, contravene · Trái nghĩa: respect', 'Là ngoại động từ, đi thẳng với các tân ngữ chỉ luật lệ, thỏa thuận, quyền lợi,...', 'Leaving your car here violates the building''s parking rules.', NULL, 'Việc để xe ở đây vi phạm quy định đỗ xe của tòa nhà.', '{"wordId":"violate","ukIpa":"/ˈvaɪəleɪt/","usIpa":"/ˈvaɪəleɪt/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To act against a law, rule, or agreement.","vi":"vi phạm; làm trái"},{"pos":"v.","en":"To fail to respect someone''s rights or privacy.","vi":"xâm phạm; xâm hại"}],"examples":[{"en":"Leaving your car here violates the building''s parking rules.","vi":"Việc để xe ở đây vi phạm quy định đỗ xe của tòa nhà.","audioKind":"ex"},{"en":"Collecting personal data without informed consent may violate citizens'' privacy and undermine public trust in digital services.","vi":"Việc thu thập dữ liệu cá nhân mà không có sự đồng ý được thông báo trước có thể vi phạm quyền riêng tư của công dân và làm suy yếu lòng tin của công chúng đối với các dịch vụ kỹ thuật số.","audioKind":"ex2"}],"collocations":[{"en":"violate the law","vi":"vi phạm pháp luật"},{"en":"violate an agreement","vi":"vi phạm thỏa thuận"},{"en":"violate human rights","vi":"vi phạm nhân quyền"},{"en":"violate someone''s privacy","vi":"xâm phạm quyền riêng tư của ai đó"}],"wordFamily":["violation (n.)","violator (n.)"],"synonyms":["breach","contravene"],"antonyms":["respect"],"tipVi":"Là ngoại động từ, đi thẳng với các tân ngữ chỉ luật lệ, thỏa thuận, quyền lợi,...","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nullify', 'en-c1-46', 'nullify', '/ˈnʌlɪfaɪ/', 'C1', 'làm mất hiệu lực pháp lý (hợp đồng, thỏa thuận, quyết định); làm vô hiệu hóa, triệt tiêu tác dụng hoặc giá trị của cái gì', 'v.', 'nullification (n.), null (adj.)', 'Đồng nghĩa: invalidate, cancel, negate · Trái nghĩa: validate', 'Có thể dùng trong ngữ cảnh pháp lý (hủy hợp đồng) hoặc chỉ việc tác dụng bị triệt tiêu.', 'This missing signature could nullify the entire rental agreement.', NULL, 'Việc thiếu chữ ký này có thể làm mất hiệu lực của toàn bộ hợp đồng thuê nhà.', '{"wordId":"nullify","ukIpa":"/ˈnʌlɪfaɪ/","usIpa":"/ˈnʌlɪfaɪ/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"to make an agreement or decision legally invalid","vi":"làm mất hiệu lực pháp lý (hợp đồng, thỏa thuận, quyết định)"},{"pos":"v.","en":"to remove the effect or value of something","vi":"làm vô hiệu hóa, triệt tiêu tác dụng hoặc giá trị của cái gì"}],"examples":[{"en":"This missing signature could nullify the entire rental agreement.","vi":"Việc thiếu chữ ký này có thể làm mất hiệu lực của toàn bộ hợp đồng thuê nhà.","audioKind":"ex"},{"en":"Rising energy consumption could nullify the environmental benefits achieved through improvements in industrial efficiency.","vi":"Mức tiêu thụ năng lượng gia tăng có thể triệt tiêu những lợi ích về môi trường đạt được nhờ việc cải thiện hiệu suất công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"nullify a contract","vi":"hủy bỏ hợp đồng"},{"en":"nullify a decision","vi":"vô hiệu hóa một quyết định"},{"en":"nullify the benefits","vi":"làm mất đi những lợi ích"}],"wordFamily":["nullification (n.)","null (adj.)"],"synonyms":["invalidate","cancel","negate"],"antonyms":["validate"],"tipVi":"Có thể dùng trong ngữ cảnh pháp lý (hủy hợp đồng) hoặc chỉ việc tác dụng bị triệt tiêu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_statesman', 'en-c1-46', 'statesman', '/ˈsteɪtsmən/', 'C1', 'chính khách lão luyện; nhà lãnh đạo chính trị có tầm nhìn', 'n.', 'stateswoman (n.), statesmanship (n.), statesmanlike (adj.)', NULL, 'Thường mang nghĩa tích cực, không nên dịch thành từ "politician" với sắc thái châm biếm; từ chỉ nữ là "stateswoman".', 'The retired statesman spoke calmly to the gathered crowd.', NULL, 'Vị chính khách đã nghỉ hưu điềm tĩnh phát biểu trước đám đông đang tụ tập.', '{"wordId":"statesman","ukIpa":"/ˈsteɪtsmən/","usIpa":"/ˈsteɪtsmən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"an experienced male political leader respected for wisdom and judgement","vi":"chính khách lão luyện; nhà lãnh đạo chính trị có tầm nhìn"}],"examples":[{"en":"The retired statesman spoke calmly to the gathered crowd.","vi":"Vị chính khách đã nghỉ hưu điềm tĩnh phát biểu trước đám đông đang tụ tập.","audioKind":"ex"},{"en":"A respected statesman can help resolve international disputes by encouraging dialogue and building trust between governments.","vi":"Một chính khách được kính trọng có thể giúp giải quyết các tranh chấp quốc tế bằng cách khuyến khích đối thoại và xây dựng lòng tin giữa các chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"elder statesman","vi":"chính khách lão thành"},{"en":"respected statesman","vi":"chính khách được kính trọng"},{"en":"distinguished statesman","vi":"chính khách xuất sắc"}],"wordFamily":["stateswoman (n.)","statesmanship (n.)","statesmanlike (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường mang nghĩa tích cực, không nên dịch thành từ \"politician\" với sắc thái châm biếm; từ chỉ nữ là \"stateswoman\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enact', 'en-c1-46', 'enact', '/ɪˈnækt/', 'C1', 'ban hành; thông qua luật; biểu diễn; diễn xuất', 'v.', 'enactment (n.), reenact (v.)', NULL, 'Enact chỉ việc ban hành hoặc thông qua luật; enforce chỉ việc thực thi pháp luật.', 'The children enacted a scene from their favourite story.', NULL, 'Bọn trẻ đã diễn lại một cảnh trong câu chuyện yêu thích của chúng.', '{"wordId":"enact","ukIpa":"/ɪˈnækt/","usIpa":"/ɪˈnækt/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To make a proposal officially become law.","vi":"ban hành; thông qua luật"},{"pos":"v.","en":"To perform a story or event through acting.","vi":"biểu diễn; diễn xuất"}],"examples":[{"en":"The children enacted a scene from their favourite story.","vi":"Bọn trẻ đã diễn lại một cảnh trong câu chuyện yêu thích của chúng.","audioKind":"ex"},{"en":"Governments should enact legislation that protects vulnerable workers without placing excessive financial burdens on small businesses.","vi":"Chính phủ nên ban hành luật bảo vệ người lao động dễ bị tổn thương mà không áp đặt gánh nặng tài chính quá mức lên các doanh nghiệp nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"enact legislation","vi":"ban hành luật pháp"},{"en":"enact a law","vi":"thông qua một đạo luật"},{"en":"enact a scene","vi":"biểu diễn một phân cảnh"}],"wordFamily":["enactment (n.)","reenact (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Enact chỉ việc ban hành hoặc thông qua luật; enforce chỉ việc thực thi pháp luật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pledge', 'en-c1-46', 'pledge', '/pledʒ/', 'C1', 'lời hứa danh dự; cam kết; hứa hẹn', 'n.', NULL, 'Đồng nghĩa: promise, commitment', 'Trang trọng hơn promise; động từ thường đi với to do.', 'We made a pledge to keep the beach clean.', NULL, 'Chúng tôi đã đưa ra cam kết giữ gìn bờ biển sạch sẽ.', '{"wordId":"pledge","ukIpa":"/pledʒ/","usIpa":"/pledʒ/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A serious promise to do or provide something","vi":"lời hứa danh dự; cam kết"},{"pos":"v.","en":"Formally promise to do or give something","vi":"cam kết; hứa hẹn"}],"examples":[{"en":"We made a pledge to keep the beach clean.","vi":"Chúng tôi đã đưa ra cam kết giữ gìn bờ biển sạch sẽ.","audioKind":"ex"},{"en":"Local authorities have pledged to improve public transport and reduce traffic congestion over the next decade.","vi":"Chính quyền địa phương đã cam kết cải thiện giao thông công cộng và giảm thiểu tình trạng ùn tắc giao thông trong thập kỷ tới.","audioKind":"ex2"}],"collocations":[{"en":"make a pledge","vi":"đưa ra cam kết"},{"en":"honour a pledge","vi":"giữ trọn lời hứa"},{"en":"pledge support","vi":"cam kết hỗ trợ"},{"en":"pledge to do something","vi":"cam kết làm điều gì đó"}],"wordFamily":[],"synonyms":["promise","commitment"],"antonyms":[],"tipVi":"Trang trọng hơn promise; động từ thường đi với to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_colonel', 'en-c1-46', 'colonel', '/ˈkɝːnəl/', 'C1', 'đại tá', 'n.', NULL, NULL, 'Phát âm giống kernel, chữ l trong từ này không phát âm thành /l/.', 'The colonel greeted the soldiers outside the camp.', NULL, 'Vị đại tá chào các binh sĩ ở bên ngoài doanh trại.', '{"wordId":"colonel","ukIpa":"/ˈkɜːnəl/","usIpa":"/ˈkɝːnəl/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"a senior army or air force officer","vi":"đại tá"}],"examples":[{"en":"The colonel greeted the soldiers outside the camp.","vi":"Vị đại tá chào các binh sĩ ở bên ngoài doanh trại.","audioKind":"ex"},{"en":"A colonel coordinated the military''s emergency response, ensuring that isolated communities received food and medical supplies.","vi":"Một viên đại tá đã điều phối phản ứng khẩn cấp của quân đội, đảm bảo rằng các cộng đồng bị cô lập nhận được lương thực và vật tư y tế.","audioKind":"ex2"}],"collocations":[{"en":"an army colonel","vi":"một đại tá lục quân"},{"en":"promoted to colonel","vi":"được thăng quân hàm đại tá"},{"en":"a retired colonel","vi":"một đại tá đã nghỉ hưu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Phát âm giống kernel, chữ l trong từ này không phát âm thành /l/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_46_1', 'en-c1-46', 'Cách dùng “chamber” (n.) — phòng họp; hội trường; phòng chức năng (thường dùng cho mục đích chính thức)', 'council chamber  ·  heart chamber  ·  chamber of commerce', 'Từ chamber thường chỉ các căn phòng chuyên dụng cho mục đích chính thức hoặc các khoang khép kín, không phải phòng ngủ thông thường.', NULL, '[{"hanzi":"We waited outside the chamber while the council met.","pinyin":"","meaning":"Chúng tôi đứng chờ bên ngoài phòng họp trong khi hội đồng đang họp."},{"hanzi":"The upper chamber of parliament reviews proposed laws before they can receive final approval.","pinyin":"","meaning":"Thượng viện của quốc hội tiến hành xem xét các dự luật trước khi chúng được phê duyệt chính thức."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_46_2', 'en-c1-46', 'Cách dùng “regime” (n.) — chế độ; chính quyền', 'authoritarian regime  ·  tax regime  ·  exercise regime', 'Khi chỉ chính quyền thường mang sắc thái tiêu cực hoặc chuyên quyền; cũng có thể chỉ hệ thống thuế khóa hoặc kế hoạch tập luyện.', NULL, '[{"hanzi":"The new regime promised to reopen the public library.","pinyin":"","meaning":"Chính quyền mới đã hứa mở cửa lại thư viện công cộng."},{"hanzi":"An authoritarian regime may restrict public debate, making it harder for citizens to influence government decisions.","pinyin":"","meaning":"Một chính quyền độc tài có thể hạn chế tranh luận công khai, khiến công dân khó khăn hơn trong việc gây ảnh hưởng đến các quyết định của chính phủ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_46_3', 'en-c1-46', 'Cách dùng “statesman” (n.) — chính khách lão luyện; nhà lãnh đạo chính trị có tầm nhìn', 'elder statesman  ·  respected statesman  ·  distinguished statesman', 'Thường mang nghĩa tích cực, không nên dịch thành từ "politician" với sắc thái châm biếm; từ chỉ nữ là "stateswoman".', 'Họ từ (Word Family): stateswoman (n.), statesmanship (n.), statesmanlike (adj.)', '[{"hanzi":"The retired statesman spoke calmly to the gathered crowd.","pinyin":"","meaning":"Vị chính khách đã nghỉ hưu điềm tĩnh phát biểu trước đám đông đang tụ tập."},{"hanzi":"A respected statesman can help resolve international disputes by encouraging dialogue and building trust between governments.","pinyin":"","meaning":"Một chính khách được kính trọng có thể giúp giải quyết các tranh chấp quốc tế bằng cách khuyến khích đối thoại và xây dựng lòng tin giữa các chính phủ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_46_4', 'en-c1-46', 'Cách dùng “constituent” (n.) — cử tri; người dân trong khu vực bầu cử', 'local constituents  ·  constituent parts  ·  a major constituent', 'Cử tri nghĩa có thể bao gồm cả những người chưa bỏ phiếu trong khu vực bầu cử; nghĩa thành phần gần với component.', 'Họ từ (Word Family): constituency (n.), constitute (v.)', '[{"hanzi":"A constituent asked her local representative about the closed library.","pinyin":"","meaning":"Một cử tri đã hỏi đại diện địa phương của cô ấy về việc đóng cửa thư viện."},{"hanzi":"Elected representatives should consult their constituents before supporting policies that significantly affect local housing and public transport.","pinyin":"","meaning":"Các đại biểu dân cử nên tham khảo ý kiến cử tri của mình trước khi ủng hộ các chính sách ảnh hưởng đáng kể đến nhà ở địa phương và giao thông công cộng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_46_1', 'en-c1-46', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
