INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_46_1_8', 'ten_c1_46_1', 'republican', 'My uncle often discusses republican ideas over dinner.', 'My uncle often discusses republican ideas over dinner.', '/rɪˈpʌblɪkən/', 'Chú tôi thường bàn luận về các tư tưởng cộng hòa trong bữa tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_46_1_1', 'en-c1-46', 'ten_c1_46_1', 'listening', 'listening', 'We waited outside the chamber while the council met.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Các quy định hạn chế của câu lạc bộ không cho phép chúng tôi dẫn theo khách.","Chú tôi thường bàn luận về các tư tưởng cộng hòa trong bữa tối.","Thủ tướng đã đến thăm làng chúng tôi sau trận lũ lụt.","Chúng tôi đứng chờ bên ngoài phòng họp trong khi hội đồng đang họp."]'::jsonb, 3, 'We waited outside the chamber while the council met. → Chúng tôi đứng chờ bên ngoài phòng họp trong khi hội đồng đang họp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_46_1_2', 'en-c1-46', 'ten_c1_46_1', 'listening', 'listening', 'We allocated one cupboard to all our baking equipment.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã dành riêng một chiếc tủ cho tất cả dụng cụ làm bánh của mình.","Thượng nghị sĩ đã chăm chú lắng nghe các mối quan tâm tại buổi họp cộng đồng của chúng tôi.","Thủ tướng đã đến thăm làng chúng tôi sau trận lũ lụt.","Chú tôi thường bàn luận về các tư tưởng cộng hòa trong bữa tối."]'::jsonb, 0, 'We allocated one cupboard to all our baking equipment. → Chúng tôi đã dành riêng một chiếc tủ cho tất cả dụng cụ làm bánh của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_46_1_3', 'en-c1-46', 'ten_c1_46_1', 'listening', 'listening', 'The premier visited our village after the river flooded.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc thiếu chữ ký này có thể làm mất hiệu lực của toàn bộ hợp đồng thuê nhà.","Bị cáo ngồi lặng lẽ bên cạnh luật sư của mình tại tòa án.","Việc để xe ở đây vi phạm quy định đỗ xe của tòa nhà.","Thủ tướng đã đến thăm làng chúng tôi sau trận lũ lụt."]'::jsonb, 3, 'The premier visited our village after the river flooded. → Thủ tướng đã đến thăm làng chúng tôi sau trận lũ lụt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_46_2', 'en-c1-46', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_46_2_1', 'ten_c1_46_2', 'chamber', 'The upper chamber of parliament reviews proposed laws before they can receive final approval.', 'The upper chamber of parliament reviews proposed laws before they can receive final approval.', '/ˈtʃeɪmbər/', 'Thượng viện của quốc hội tiến hành xem xét các dự luật trước khi chúng được phê duyệt chính thức.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_46_2_2', 'ten_c1_46_2', 'allocate', 'Local authorities should allocate more funding to public transport in areas with limited access to essential services.', 'Local authorities should allocate more funding to public transport in areas with limited access to essential services.', '/ˈæləkeɪt/', 'Chính quyền địa phương nên phân bổ nhiều kinh phí hơn cho giao thông công cộng ở những khu vực khó tiếp cận các dịch vụ thiết yếu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_46_2_3', 'ten_c1_46_2', 'premier', 'The premier announced new measures to improve access to affordable housing in rapidly growing cities.', 'The premier announced new measures to improve access to affordable housing in rapidly growing cities.', '/prɪˈmɪr/', 'Thủ tướng đã công bố các biện pháp mới nhằm cải thiện khả năng tiếp cận nhà ở giá rẻ ở các thành phố đang phát triển nhanh chóng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_46_2_4', 'ten_c1_46_2', 'regime', 'An authoritarian regime may restrict public debate, making it harder for citizens to influence government decisions.', 'An authoritarian regime may restrict public debate, making it harder for citizens to influence government decisions.', '/reɪˈʒiːm/', 'Một chính quyền độc tài có thể hạn chế tranh luận công khai, khiến công dân khó khăn hơn trong việc gây ảnh hưởng đến các quyết định của chính phủ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_46_2_5', 'ten_c1_46_2', 'defendant', 'Every defendant should have access to legal advice, regardless of their income or social background.', 'Every defendant should have access to legal advice, regardless of their income or social background.', '/dɪˈfendənt/', 'Mỗi bị cáo đều nên được tiếp cận dịch vụ tư vấn pháp lý, bất kể thu nhập hay hoàn cảnh xã hội của họ ra sao.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_46_2_6', 'ten_c1_46_2', 'verdict', 'A jury should reach its verdict solely on the evidence presented during the trial.', 'A jury should reach its verdict solely on the evidence presented during the trial.', '/ˈvɝːdɪkt/', 'Bồi thẩm đoàn nên đưa ra phán quyết chỉ dựa trên các bằng chứng được trình bày trong phiên tòa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_46_2_1', 'en-c1-46', 'ten_c1_46_2', 'listening', 'listening', 'The upper chamber of parliament reviews proposed laws before they can receive final approval.', NULL, 'Trong câu vừa nghe, từ “chamber” mang nghĩa nào sau đây?', '["làm điếc tai; làm ù tai; làm chói tai","phòng họp; hội trường; phòng chức năng (thường dùng cho mục đích chính thức)","khó đọc; không đọc được; không thể đọc nổi (do chữ viết không rõ)","an ủi; vỗ về ai đó đang buồn bã hoặc thất vọng"]'::jsonb, 1, '“chamber” (/ˈtʃeɪmbər/): phòng họp; hội trường; phòng chức năng (thường dùng cho mục đích chính thức). Câu đầy đủ: The upper chamber of parliament reviews proposed laws before they can receive final approval.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_46_2_2', 'en-c1-46', 'ten_c1_46_2', 'listening', 'listening', 'Local authorities should allocate more funding to public transport in areas with limited access to essential services.', NULL, 'Trong câu vừa nghe, từ “allocate” mang nghĩa nào sau đây?', '["tuabin; máy phát điện chạy bằng sức gió/nước/hơi nước","phân bổ; cấp phát","ngầm hiểu; ngầm đồng ý; tâm ý tương thông","công nghiệp hóa; phát triển nền công nghiệp"]'::jsonb, 1, '“allocate” (/ˈæləkeɪt/): phân bổ; cấp phát. Câu đầy đủ: Local authorities should allocate more funding to public transport in areas with limited access to essential services.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
