INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_1', 'en-c1-46', NULL, 'comprehensive_test', 'listening', 'chamber', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tạm thời; chưa chính thức","phòng họp; hội trường; phòng chức năng (thường dùng cho mục đích chính thức)","sự làm rõ; lời giải thích thêm","thích hợp cho việc trồng trọt; có thể canh tác"]'::jsonb, 1, 'chamber (/ˈtʃeɪmbər/) → phòng họp; hội trường; phòng chức năng (thường dùng cho mục đích chính thức); buồng; khoang (không gian khép kín trong cơ thể, máy móc hoặc cấu trúc)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_2', 'en-c1-46', NULL, 'comprehensive_test', 'listening', 'We allocated one cupboard to all our baking equipment.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Có được phép chụp ảnh bên trong viện bảo tàng này không?","Việc thiếu chữ ký này có thể làm mất hiệu lực của toàn bộ hợp đồng thuê nhà.","Vị chính khách đã nghỉ hưu điềm tĩnh phát biểu trước đám đông đang tụ tập.","Chúng tôi đã dành riêng một chiếc tủ cho tất cả dụng cụ làm bánh của mình."]'::jsonb, 3, 'We allocated one cupboard to all our baking equipment. → Chúng tôi đã dành riêng một chiếc tủ cho tất cả dụng cụ làm bánh của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_3', 'en-c1-46', NULL, 'comprehensive_test', 'listening', 'premier', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ám ảnh; làm cho bận tâm lo nghĩ","ngư lôi (vũ khí dưới nước tự hành)","thủ tướng; thủ hiến; người đứng đầu chính phủ cấp vùng","triệu tập; gọi đến; yêu cầu có mặt"]'::jsonb, 2, 'premier (/prɪˈmɪr/) → thủ tướng; thủ hiến; người đứng đầu chính phủ cấp vùng; hàng đầu; tối quan trọng; xuất sắc nhất', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_4', 'en-c1-46', NULL, 'comprehensive_test', 'listening', 'The new regime promised to reopen the public library.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc cô ấy được bổ nhiệm làm trưởng nhóm không khiến ai ở nơi làm việc bất ngờ.","Chú tôi thường bàn luận về các tư tưởng cộng hòa trong bữa tối.","Chính quyền mới đã hứa mở cửa lại thư viện công cộng.","Vui lòng liên hệ với ban thư ký để xác nhận thời gian cuộc họp của bạn."]'::jsonb, 2, 'The new regime promised to reopen the public library. → Chính quyền mới đã hứa mở cửa lại thư viện công cộng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_5', 'en-c1-46', NULL, 'comprehensive_test', 'listening', 'defendant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["liên kết; sáp nhập; gia nhập vào tổ chức lớn","nghiêm ngặt; kỹ lưỡng; chặt chẽ","bị cáo; bên bị đơn","sự thanh tịnh; sự bình yên; sự thanh thản"]'::jsonb, 2, 'defendant (/dɪˈfendənt/) → bị cáo; bên bị đơn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_6', 'en-c1-46', NULL, 'comprehensive_test', 'listening', 'What is your verdict on my homemade soup?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc để xe ở đây vi phạm quy định đỗ xe của tòa nhà.","Có được phép chụp ảnh bên trong viện bảo tàng này không?","Chú tôi thường bàn luận về các tư tưởng cộng hòa trong bữa tối.","Bạn thấy món súp tôi tự nấu thế nào?"]'::jsonb, 3, 'What is your verdict on my homemade soup? → Bạn thấy món súp tôi tự nấu thế nào?', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_7', 'en-c1-46', NULL, 'comprehensive_test', 'listening', 'municipal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mang tính cao trào; đạt đến đỉnh điểm","thuộc về thành phố; thuộc về đô thị; cấp thành phố","buổi định hướng, tuần lễ sinh hoạt đầu khóa (giúp người mới thích nghi với môi trường mới)","gửi, phái (ai hoặc cái gì đi đến một địa điểm cụ thể)"]'::jsonb, 1, 'municipal (/mjuːˈnɪsɪpəl/) → thuộc về thành phố; thuộc về đô thị; cấp thành phố', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_8', 'en-c1-46', NULL, 'comprehensive_test', 'listening', 'My uncle often discusses republican ideas over dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chú tôi thường bàn luận về các tư tưởng cộng hòa trong bữa tối.","Việc cô ấy được bổ nhiệm làm trưởng nhóm không khiến ai ở nơi làm việc bất ngờ.","Bị cáo ngồi lặng lẽ bên cạnh luật sư của mình tại tòa án.","Việc thiếu chữ ký này có thể làm mất hiệu lực của toàn bộ hợp đồng thuê nhà."]'::jsonb, 0, 'My uncle often discusses republican ideas over dinner. → Chú tôi thường bàn luận về các tư tưởng cộng hòa trong bữa tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_9', 'en-c1-46', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A person or organisation facing a legal claim or criminal charge.”?', '["republican","premier","secretariat","defendant"]'::jsonb, 3, 'defendant (/dɪˈfendənt/) → bị cáo; bên bị đơn', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_10', 'en-c1-46', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An official court decision about whether someone is guilty.”?', '["secretariat","permissible","chamber","verdict"]'::jsonb, 3, 'verdict (/ˈvɝːdɪkt/) → lệnh tuyên án; phán quyết của tòa án', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_11', 'en-c1-46', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Relating to a town or city and its government.”?', '["outlaw","republican","municipal","pledge"]'::jsonb, 2, 'municipal (/mjuːˈnɪsɪpəl/) → thuộc về thành phố; thuộc về đô thị; cấp thành phố', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_12', 'en-c1-46', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Supporting government without a monarch, usually through elected representatives”?', '["republican","outlaw","constituent","pledge"]'::jsonb, 0, 'republican (/rɪˈpʌblɪkən/) → thuộc về thể chế cộng hòa, theo chủ nghĩa cộng hòa', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_13', 'en-c1-46', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The act of officially choosing someone or something for a purpose.”?', '["colonel","defendant","municipal","designation"]'::jsonb, 3, 'designation (/ˌdezɪɡˈneɪʃən/) → sự chỉ định; sự bổ nhiệm; sự phân loại', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
