INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_18', 'en-c1-46', NULL, 'comprehensive_test', 'reading', NULL, 'The upper chamber of parliament reviews proposed laws before they can receive final approval.', 'Dựa vào câu trên, từ “chamber” có nghĩa phù hợp nhất là gì?', '["rõ ràng; thẳng thắn; dứt khoát","phòng họp; hội trường; phòng chức năng (thường dùng cho mục đích chính thức)","bệnh dịch hạch; dịch bệnh","hệ thống phân cấp; thứ bậc"]'::jsonb, 1, 'chamber: phòng họp; hội trường; phòng chức năng (thường dùng cho mục đích chính thức); buồng; khoang (không gian khép kín trong cơ thể, máy móc hoặc cấu trúc). Dịch cả câu: Thượng viện của quốc hội tiến hành xem xét các dự luật trước khi chúng được phê duyệt chính thức.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_19', 'en-c1-46', NULL, 'comprehensive_test', 'reading', NULL, 'Local authorities should allocate more funding to public transport in areas with limited access to essential services.', 'Dựa vào câu trên, từ “allocate” có nghĩa phù hợp nhất là gì?', '["cử tri; người dân trong khu vực bầu cử","phân bổ; cấp phát","trôi qua (dùng cho thời gian)","gắng sức; lấy hết (can đảm, sức mạnh)"]'::jsonb, 1, 'allocate: phân bổ; cấp phát. Dịch cả câu: Chính quyền địa phương nên phân bổ nhiều kinh phí hơn cho giao thông công cộng ở những khu vực khó tiếp cận các dịch vụ thiết yếu.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_20', 'en-c1-46', NULL, 'comprehensive_test', 'reading', NULL, 'The premier announced new measures to improve access to affordable housing in rapidly growing cities.', 'Dựa vào câu trên, từ “premier” có nghĩa phù hợp nhất là gì?', '["thủ tướng; thủ hiến; người đứng đầu chính phủ cấp vùng","bác bỏ; chứng minh là sai","cuộn vi phim; phim thu nhỏ","vui mừng; hoan hỉ; ăn mừng"]'::jsonb, 0, 'premier: thủ tướng; thủ hiến; người đứng đầu chính phủ cấp vùng; hàng đầu; tối quan trọng; xuất sắc nhất. Dịch cả câu: Thủ tướng đã công bố các biện pháp mới nhằm cải thiện khả năng tiếp cận nhà ở giá rẻ ở các thành phố đang phát triển nhanh chóng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_21', 'en-c1-46', NULL, 'comprehensive_test', 'reading', NULL, 'An authoritarian regime may restrict public debate, making it harder for citizens to influence government decisions.', 'Dựa vào câu trên, từ “regime” có nghĩa phù hợp nhất là gì?', '["chế độ; chính quyền","nhạc đệm","mạch lạc; rành mạch; chặt chẽ","lớp phủ; tầng phủ (tuyết, sương,...)"]'::jsonb, 0, 'regime: chế độ; chính quyền; hệ thống quản lý; chế độ sinh hoạt. Dịch cả câu: Một chính quyền độc tài có thể hạn chế tranh luận công khai, khiến công dân khó khăn hơn trong việc gây ảnh hưởng đến các quyết định của chính phủ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_22', 'en-c1-46', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ban hành; thông qua luật”', '["enact","enchant","reinforcement","ignite"]'::jsonb, 0, 'ban hành; thông qua luật → enact (/ɪˈnækt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_23', 'en-c1-46', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lời hứa danh dự; cam kết”', '["metallic","flourish","pledge","epoch"]'::jsonb, 2, 'lời hứa danh dự; cam kết → pledge (/pledʒ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_46_24', 'en-c1-46', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đại tá”', '["pertinent","petty","colonel","ordinarily"]'::jsonb, 2, 'đại tá → colonel (/ˈkɝːnəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-47', 'en', 'Bài 47: Chính phủ & Pháp luật (4) - CEFR C1', 'CEFR C1', 'C1 · Chính phủ & Pháp luật', '23 từ vựng Tiếng Anh CEFR C1 chủ đề chính phủ & pháp luật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5047, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accord', 'en-c1-47', 'accord', '/əˈkɔːrd/', 'C1', 'hiệp định; hiệp ước; sự hòa hợp; sự thống nhất; ban tặng; trao cho', 'n.', 'accordance (n.)', 'Đồng nghĩa: agreement, harmony · Trái nghĩa: disagreement', 'of your own accord có nghĩa là tự nguyện, không cần ai yêu cầu.', 'The two clubs reached an accord over sharing equipment.', NULL, 'Hai câu lạc bộ đã đạt được thỏa thuận về việc dùng chung thiết bị.', '{"wordId":"accord","ukIpa":"/əˈkɔːd/","usIpa":"/əˈkɔːrd/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A formal agreement between countries, groups, or organisations.","vi":"hiệp định; hiệp ước"},{"pos":"n.","en":"Agreement or harmony between people, ideas, or actions.","vi":"sự hòa hợp; sự thống nhất"},{"pos":"v.","en":"To give someone respect, rights, or special treatment.","vi":"ban tặng; trao cho"}],"examples":[{"en":"The two clubs reached an accord over sharing equipment.","vi":"Hai câu lạc bộ đã đạt được thỏa thuận về việc dùng chung thiết bị.","audioKind":"ex"},{"en":"An international accord on emissions could encourage countries to adopt cleaner technologies and protect vulnerable ecosystems.","vi":"Một hiệp định quốc tế về khí thải có thể khuyến khích các quốc gia áp dụng công nghệ sạch hơn và bảo vệ các hệ sinh thái mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"reach an accord","vi":"đạt được thỏa thuận"},{"en":"in accord with","vi":"phù hợp với"},{"en":"of your own accord","vi":"tự nguyện"},{"en":"accord equal rights","vi":"trao quyền bình đẳng"}],"wordFamily":["accordance (n.)"],"synonyms":["agreement","harmony"],"antonyms":["disagreement"],"tipVi":"of your own accord có nghĩa là tự nguyện, không cần ai yêu cầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invalidate', 'en-c1-47', 'invalidate', '/ɪnˈvælɪdeɪt/', 'C1', 'làm mất hiệu lực; làm cho vô hiệu; làm cho không còn đúng; bác bỏ', 'v.', 'invalid (adj.), invalidation (n.), valid (adj.), validate (v.)', 'Đồng nghĩa: nullify, void · Trái nghĩa: validate', 'Có thể dùng để chỉ hợp đồng chính thức mất hiệu lực, hoặc chứng cứ làm cho kết luận không còn hợp lý.', 'Opening the device yourself may invalidate its warranty.', NULL, 'Việc bạn tự mở thiết bị có thể làm mất hiệu lực bảo hành của nó.', '{"wordId":"invalidate","ukIpa":"/ɪnˈvælɪdeɪt/","usIpa":"/ɪnˈvælɪdeɪt/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"to make something no longer legally or officially acceptable","vi":"làm mất hiệu lực; làm cho vô hiệu"},{"pos":"v.","en":"to show that an argument or result is not sound","vi":"làm cho không còn đúng; bác bỏ"}],"examples":[{"en":"Opening the device yourself may invalidate its warranty.","vi":"Việc bạn tự mở thiết bị có thể làm mất hiệu lực bảo hành của nó.","audioKind":"ex"},{"en":"A sample that excludes older adults may invalidate conclusions about the health needs of the wider population.","vi":"Một mẫu nghiên cứu loại trừ người cao tuổi có thể làm mất giá trị các kết luận về nhu cầu chăm sóc sức khỏe của toàn bộ dân số rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"invalidate a warranty","vi":"invalidate a warranty -> làm mất hiệu lực bảo hành"},{"en":"invalidate a contract","vi":"invalidate a contract -> làm vô hiệu hóa hợp đồng"},{"en":"invalidate the results","vi":"invalidate the results -> làm mất hiệu lực kết quả"}],"wordFamily":["invalid (adj.)","invalidation (n.)","valid (adj.)","validate (v.)"],"synonyms":["nullify","void"],"antonyms":["validate"],"tipVi":"Có thể dùng để chỉ hợp đồng chính thức mất hiệu lực, hoặc chứng cứ làm cho kết luận không còn hợp lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tyranny', 'en-c1-47', 'tyranny', '/ˈtɪrəni/', 'C1', 'chế độ bạo ngược; nền chuyên chế; sự áp bức; sự kìm kẹp tàn bạo', 'n.', 'tyrant (n.), tyrannical (adj.), tyrannise (v.)', 'Đồng nghĩa: despotism, oppression · Trái nghĩa: freedom', 'Nhấn mạnh sự lạm dụng quyền lực tàn bạo, nghiêm trọng hơn so với việc quản lý nghiêm khắc thông thường.', 'The film follows a village struggling against a ruler''s tyranny.', NULL, 'Bộ phim kể về một ngôi làng đang đấu tranh chống lại ách bạo ngược của kẻ thống trị.', '{"wordId":"tyranny","ukIpa":"/ˈtɪrəni/","usIpa":"/ˈtɪrəni/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"cruel government that uses power without limits","vi":"chế độ bạo ngược; nền chuyên chế"},{"pos":"n.","en":"cruel or unreasonable control over other people","vi":"sự áp bức; sự kìm kẹp tàn bạo"}],"examples":[{"en":"The film follows a village struggling against a ruler''s tyranny.","vi":"Bộ phim kể về một ngôi làng đang đấu tranh chống lại ách bạo ngược của kẻ thống trị.","audioKind":"ex"},{"en":"Independent courts and a free press can help prevent tyranny by holding political leaders accountable.","vi":"Các tòa án độc lập và báo chí tự do có thể giúp ngăn chặn tình trạng chuyên chế bằng cách bắt các nhà lãnh đạo chính trị chịu trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"resist tyranny","vi":"chống lại bạo tyranny"},{"en":"political tyranny","vi":"nền chuyên chế chính trị"},{"en":"the tyranny of the majority","vi":"sự áp bức của số đông"}],"wordFamily":["tyrant (n.)","tyrannical (adj.)","tyrannise (v.)"],"synonyms":["despotism","oppression"],"antonyms":["freedom"],"tipVi":"Nhấn mạnh sự lạm dụng quyền lực tàn bạo, nghiêm trọng hơn so với việc quản lý nghiêm khắc thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_civic', 'en-c1-47', 'civic', '/ˈsɪvɪk/', 'C1', 'thuộc về thành phố; thuộc về đô thị hoặc hành chính đô thị; thuộc về công dân; liên quan đến trách nhiệm công dân trong cộng đồng', 'adj.', 'civics (n.)', NULL, 'civic nhấn mạnh vào các vấn đề đô thị hoặc công dân; civil ngoài ra còn có nghĩa là dân sự hoặc lịch sự.', 'The mayor welcomed visitors outside the new civic centre.', NULL, 'Thị trưởng đã chào đón khách tham quan bên ngoài trung tâm hành chính mới của thành phố.', '{"wordId":"civic","ukIpa":"/ˈsɪvɪk/","usIpa":"/ˈsɪvɪk/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"relating to a town or city and its administration","vi":"thuộc về thành phố; thuộc về đô thị hoặc hành chính đô thị"},{"pos":"adj.","en":"relating to citizens and their responsibilities within a community","vi":"thuộc về công dân; liên quan đến trách nhiệm công dân trong cộng đồng"}],"examples":[{"en":"The mayor welcomed visitors outside the new civic centre.","vi":"Thị trưởng đã chào đón khách tham quan bên ngoài trung tâm hành chính mới của thành phố.","audioKind":"ex"},{"en":"Schools can strengthen civic responsibility by encouraging students to participate in projects that benefit their local communities.","vi":"Các trường học có thể nâng cao trách nhiệm công dân bằng cách khuyến khích học sinh tham gia vào các dự án mang lại lợi ích cho cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"civic centre","vi":"trung tâm hành chính thành phố"},{"en":"civic responsibility","vi":"trách nhiệm công dân"},{"en":"civic pride","vi":"niềm tự hào công dân"},{"en":"civic engagement","vi":"sự tham gia của công dân"}],"wordFamily":["civics (n.)"],"synonyms":[],"antonyms":[],"tipVi":"civic nhấn mạnh vào các vấn đề đô thị hoặc công dân; civil ngoài ra còn có nghĩa là dân sự hoặc lịch sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stipulate', 'en-c1-47', 'stipulate', '/ˈstɪpjəleɪt/', 'C1', 'quy định rõ ràng; thỏa thuận cụ thể một điều kiện như một phần của hợp đồng', 'v.', 'stipulation (n.)', 'Đồng nghĩa: specify, require', 'Là từ mang tính trang trọng, thường dùng trong văn bản hợp đồng; có thể đi với danh từ hoặc mệnh đề that.', 'The rental rules stipulate that pets must stay downstairs.', NULL, 'Nội quy cho thuê nhà quy định rõ ràng rằng thú cưng phải ở dưới tầng trệt.', '{"wordId":"stipulate","ukIpa":"/ˈstɪpjəleɪt/","usIpa":"/ˈstɪpjəleɪt/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To state a requirement clearly as part of an agreement","vi":"quy định rõ ràng; thỏa thuận cụ thể một điều kiện như một phần của hợp đồng"}],"examples":[{"en":"The rental rules stipulate that pets must stay downstairs.","vi":"Nội quy cho thuê nhà quy định rõ ràng rằng thú cưng phải ở dưới tầng trệt.","audioKind":"ex"},{"en":"Employment contracts should stipulate working hours clearly to prevent disputes between employers and their staff.","vi":"Hợp đồng lao động nên quy định rõ thời gian làm việc để ngăn ngừa tranh chấp giữa người sử dụng lao động và nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"stipulate that","vi":"quy định rằng"},{"en":"stipulate conditions","vi":"quy định các điều kiện"},{"en":"stipulate a deadline","vi":"quy định thời hạn"}],"wordFamily":["stipulation (n.)"],"synonyms":["specify","require"],"antonyms":[],"tipVi":"Là từ mang tính trang trọng, thường dùng trong văn bản hợp đồng; có thể đi với danh từ hoặc mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suppression', 'en-c1-47', 'suppression', '/səˈpreʃən/', 'C1', 'sự trấn áp; sự đàn áp; sự che giấu; sự bưng bít thông tin; sự kìm nén; sự kiểm soát phản ứng', 'n.', 'suppress (v.), suppressive (adj.), suppressant (n.)', NULL, 'Thường là danh từ không đếm được; động từ tương ứng là suppress, cần lưu ý viết đôi chữ pp và ss.', 'His suppression of laughter failed when the puppy sneezed.', NULL, 'Anh ấy không thể kìm được tiếng cười khi chú cún con hắt xì.', '{"wordId":"suppression","ukIpa":"/səˈpreʃən/","usIpa":"/səˈpreʃən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"The forceful prevention of an activity or expression.","vi":"sự trấn áp; sự đàn áp"},{"pos":"n.","en":"The deliberate prevention of information from becoming known.","vi":"sự che giấu; sự bưng bít thông tin"},{"pos":"n.","en":"The reduction or control of a reaction or process.","vi":"sự kìm nén; sự kiểm soát phản ứng"}],"examples":[{"en":"His suppression of laughter failed when the puppy sneezed.","vi":"Anh ấy không thể kìm được tiếng cười khi chú cún con hắt xì.","audioKind":"ex"},{"en":"The suppression of public debate can weaken trust in institutions and prevent communities from addressing serious problems.","vi":"Việc bưng bít các cuộc tranh luận công khai có thể làm xói mòn lòng tin vào các tổ chức và ngăn cản cộng đồng giải quyết các vấn đề nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"suppression of dissent","vi":"đàn áp sự bất đồng chính kiến"},{"en":"suppression of evidence","vi":"che giấu bằng chứng"},{"en":"immune suppression","vi":"ức chế miễn dịch"}],"wordFamily":["suppress (v.)","suppressive (adj.)","suppressant (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; động từ tương ứng là suppress, cần lưu ý viết đôi chữ pp và ss.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_senate', 'en-c1-47', 'senate', '/ˈsenət/', 'C1', 'thượng viện; viện nguyên lão', 'n.', 'senator (n.), senatorial (adj.)', NULL, 'Khi chỉ thượng viện của một quốc gia cụ thể, thường được viết hoa thành the Senate.', 'Our class watched the senate debate on television today.', NULL, 'Lớp chúng tôi đã xem buổi tranh luận của thượng viện trên truyền hình hôm nay.', '{"wordId":"senate","ukIpa":"/ˈsenət/","usIpa":"/ˈsenət/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"The upper chamber of parliament in some countries","vi":"thượng viện"},{"pos":"n.","en":"The governing council of ancient Rome","vi":"viện nguyên lão"}],"examples":[{"en":"Our class watched the senate debate on television today.","vi":"Lớp chúng tôi đã xem buổi tranh luận của thượng viện trên truyền hình hôm nay.","audioKind":"ex"},{"en":"In some political systems, the senate reviews proposed laws and represents regional interests within the national government.","vi":"Trong một số hệ thống chính trị, thượng viện có nhiệm vụ xem xét các dự luật và đại diện cho lợi ích của các địa phương trong chính quyền quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"senate election","vi":"bầu cử thượng viện"},{"en":"senate committee","vi":"ủy ban thượng viện"},{"en":"senate debate","vi":"cuộc tranh luận tại thượng viện"},{"en":"a seat in the senate","vi":"một chiếc ghế trong thượng viện"}],"wordFamily":["senator (n.)","senatorial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ thượng viện của một quốc gia cụ thể, thường được viết hoa thành the Senate.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amend', 'en-c1-47', 'amend', '/əˈmend/', 'C1', 'sửa đổi; điều chỉnh (tài liệu, quy tắc, kế hoạch)', 'v.', 'amendment (n.), amended (adj.)', 'Đồng nghĩa: revise, modify', 'Thường chỉ sửa đổi tài liệu hoặc luật pháp; sửa chữa vật thể thực tế thường dùng mend.', 'Please amend the booking to include one extra guest.', NULL, 'Xin hãy sửa đổi lại phần đặt phòng để thêm một khách đi cùng.', '{"wordId":"amend","ukIpa":"/əˈmend/","usIpa":"/əˈmend/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To change a document, rule, or plan to improve it.","vi":"sửa đổi; điều chỉnh (tài liệu, quy tắc, kế hoạch)"}],"examples":[{"en":"Please amend the booking to include one extra guest.","vi":"Xin hãy sửa đổi lại phần đặt phòng để thêm một khách đi cùng.","audioKind":"ex"},{"en":"Parliament may amend existing legislation to ensure that remote workers receive the same protections as office employees.","vi":"Quốc hội có thể sửa đổi luật hiện hành để đảm bảo rằng người lao động từ xa nhận được các quyền lợi bảo vệ giống như nhân viên làm việc tại văn phòng.","audioKind":"ex2"}],"collocations":[{"en":"amend a law","vi":"sửa đổi luật"},{"en":"amend a proposal","vi":"sửa đổi đề xuất"},{"en":"amend a contract","vi":"sửa đổi hợp đồng"}],"wordFamily":["amendment (n.)","amended (adj.)"],"synonyms":["revise","modify"],"antonyms":[],"tipVi":"Thường chỉ sửa đổi tài liệu hoặc luật pháp; sửa chữa vật thể thực tế thường dùng mend.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mandatory', 'en-c1-47', 'mandatory', '/ˈmændətɔːri/', 'C1', 'bắt buộc; cưỡng chế theo luật', 'adj.', 'mandate (n.), mandate (v.)', 'Đồng nghĩa: compulsory, obligatory, required · Trái nghĩa: optional, voluntary', 'Thường dùng cho các quy định hoặc yêu cầu thể chế; từ trái nghĩa là optional.', 'Wearing a helmet is mandatory at this climbing centre.', NULL, 'Việc đội mũ bảo hiểm là bắt buộc tại trung tâm leo núi này.', '{"wordId":"mandatory","ukIpa":"/ˈmændətəri/","usIpa":"/ˈmændətɔːri/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"Required by a law or rule.","vi":"bắt buộc; cưỡng chế theo luật"}],"examples":[{"en":"Wearing a helmet is mandatory at this climbing centre.","vi":"Việc đội mũ bảo hiểm là bắt buộc tại trung tâm leo núi này.","audioKind":"ex"},{"en":"Mandatory safety training can reduce workplace accidents by ensuring that all employees understand potential risks.","vi":"Đào tạo an toàn bắt buộc có thể làm giảm tai nạn lao động bằng cách đảm bảo rằng tất cả nhân viên đều hiểu rõ các rủi ro tiềm ẩn.","audioKind":"ex2"}],"collocations":[{"en":"mandatory training","vi":"đào tạo bắt buộc"},{"en":"a mandatory requirement","vi":"yêu cầu bắt buộc"},{"en":"mandatory attendance","vi":"sự tham gia bắt buộc"}],"wordFamily":["mandate (n.)","mandate (v.)"],"synonyms":["compulsory","obligatory","required"],"antonyms":["optional","voluntary"],"tipVi":"Thường dùng cho các quy định hoặc yêu cầu thể chế; từ trái nghĩa là optional.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overrule', 'en-c1-47', 'overrule', '/ˌoʊvɚˈruːl/', 'C1', 'bác bỏ; bác khước; lật lại', 'v.', NULL, 'Đồng nghĩa: override, reverse · Trái nghĩa: uphold', 'Nhấn mạnh việc dùng quyền lực cao hơn để bác bỏ, không chỉ đơn thuần là bày tỏ sự không đồng tình.', 'The manager overruled my request to close the shop early.', NULL, 'Người quản lý đã bác bỏ yêu cầu đóng cửa hàng sớm của tôi.', '{"wordId":"overrule","ukIpa":"/ˌəʊvəˈruːl/","usIpa":"/ˌoʊvɚˈruːl/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To use authority to reject or reverse a decision or objection.","vi":"bác bỏ; bác khước; lật lại"}],"examples":[{"en":"The manager overruled my request to close the shop early.","vi":"Người quản lý đã bác bỏ yêu cầu đóng cửa hàng sớm của tôi.","audioKind":"ex"},{"en":"National authorities may overrule local planning decisions when major infrastructure projects serve the wider public interest.","vi":"Các cơ quan nhà nước có thể bác bỏ các quyết định quy hoạch địa phương khi các dự án cơ sở hạ tầng trọng điểm phục vụ lợi ích công cộng rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"overrule an objection","vi":"bác bỏ sự phản đối"},{"en":"overrule a decision","vi":"lật lại một quyết định"},{"en":"be overruled by","vi":"bị... bác bỏ"}],"wordFamily":[],"synonyms":["override","reverse"],"antonyms":["uphold"],"tipVi":"Nhấn mạnh việc dùng quyền lực cao hơn để bác bỏ, không chỉ đơn thuần là bày tỏ sự không đồng tình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imperative', 'en-c1-47', 'imperative', '/ɪmˈperətɪv/', 'C1', 'cấp bách, hết sức quan trọng, bắt buộc; việc bắt buộc phải làm, nhu cầu cấp thiết; thuộc thể mệnh lệnh (ngữ pháp)', 'adj.', 'imperatively (adv.)', 'Đồng nghĩa: essential, crucial, vital · Trái nghĩa: optional', 'Thường dùng cấu trúc It is imperative to do hoặc mệnh đề với that.', 'It is imperative to keep this medicine refrigerated.', NULL, 'Loại thuốc này bắt buộc phải được bảo quản lạnh.', '{"wordId":"imperative","ukIpa":"/ɪmˈperətɪv/","usIpa":"/ɪmˈperətɪv/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"Extremely important and needing to be done.","vi":"cấp bách, hết sức quan trọng, bắt buộc"},{"pos":"n.","en":"Something that must be done or given urgent attention.","vi":"việc bắt buộc phải làm, nhu cầu cấp thiết"},{"pos":"adj.","en":"Expressing a command or instruction in grammar.","vi":"thuộc thể mệnh lệnh (ngữ pháp)"}],"examples":[{"en":"It is imperative to keep this medicine refrigerated.","vi":"Loại thuốc này bắt buộc phải được bảo quản lạnh.","audioKind":"ex"},{"en":"As urban populations grow, it is imperative that governments invest in reliable and affordable public transport.","vi":"Khi dân số đô thị tăng lên, chính quyền bắt buộc phải đầu tư vào hệ thống giao thông công cộng đáng tin cậy và có giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"it is imperative that","vi":"điều tối quan trọng là"},{"en":"imperative to act","vi":"bắt buộc phải hành động"},{"en":"moral imperative","vi":"nhiệm vụ đạo đức"},{"en":"imperative mood","vi":"thể mệnh lệnh"}],"wordFamily":["imperatively (adv.)"],"synonyms":["essential","crucial","vital"],"antonyms":["optional"],"tipVi":"Thường dùng cấu trúc It is imperative to do hoặc mệnh đề với that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decree', 'en-c1-47', 'decree', '/dɪˈkriː/', 'C1', 'sắc lệnh; nghị định; quyết định chính thức; ra sắc lệnh; ban hành lệnh', 'n.', NULL, 'Đồng nghĩa: order, edict', 'Động từ có thể đi với mệnh đề that; danh từ chỉ một mệnh lệnh chính thức có thẩm quyền.', 'The new decree means our street stays closed tonight.', NULL, 'Sắc lệnh mới có nghĩa là con phố của chúng ta sẽ tiếp tục bị đóng cửa vào tối nay.', '{"wordId":"decree","ukIpa":"/dɪˈkriː/","usIpa":"/dɪˈkriː/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"An official order issued by a ruler, government, or court.","vi":"sắc lệnh; nghị định; quyết định chính thức"},{"pos":"v.","en":"To officially order or decide that something must happen.","vi":"ra sắc lệnh; ban hành lệnh"}],"examples":[{"en":"The new decree means our street stays closed tonight.","vi":"Sắc lệnh mới có nghĩa là con phố của chúng ta sẽ tiếp tục bị đóng cửa vào tối nay.","audioKind":"ex"},{"en":"The government issued a decree requiring factories to treat wastewater before releasing it into rivers.","vi":"Chính phủ đã ban hành sắc lệnh yêu cầu các nhà máy phải xử lý nước thải trước khi xả ra sông.","audioKind":"ex2"}],"collocations":[{"en":"issue a decree","vi":"ban hành sắc lệnh"},{"en":"by decree","vi":"bằng sắc lệnh"},{"en":"decree that","vi":"ra lệnh rằng"}],"wordFamily":[],"synonyms":["order","edict"],"antonyms":[],"tipVi":"Động từ có thể đi với mệnh đề that; danh từ chỉ một mệnh lệnh chính thức có thẩm quyền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bloc', 'en-c1-47', 'bloc', '/blɑːk/', 'C1', 'khối chính trị; liên minh', 'n.', NULL, 'Đồng nghĩa: alliance, coalition', 'Phát âm giống block; bloc chuyên dùng để chỉ các quốc gia hoặc nhóm người cùng hành động vì mục tiêu chung.', 'The councillors formed a bloc to protect local parks.', NULL, 'Các ủy viên hội đồng đã thành lập một liên minh để bảo vệ các công viên địa phương.', '{"wordId":"bloc","ukIpa":"/blɒk/","usIpa":"/blɑːk/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A group of countries or people acting together for shared aims.","vi":"khối chính trị; liên minh"}],"examples":[{"en":"The councillors formed a bloc to protect local parks.","vi":"Các ủy viên hội đồng đã thành lập một liên minh để bảo vệ các công viên địa phương.","audioKind":"ex"},{"en":"A regional trading bloc can strengthen members'' bargaining power while reducing barriers to trade between participating countries.","vi":"Một khối mậu dịch khu vực có thể củng cố năng lực đàm phán của các thành viên đồng thời giảm bớt các rào cản thương mại giữa các quốc gia tham gia.","audioKind":"ex2"}],"collocations":[{"en":"trading bloc","vi":"khối mậu dịch"},{"en":"political bloc","vi":"khối chính trị"},{"en":"regional bloc","vi":"khối khu vực"},{"en":"form a bloc","vi":"thành lập liên minh"}],"wordFamily":[],"synonyms":["alliance","coalition"],"antonyms":[],"tipVi":"Phát âm giống block; bloc chuyên dùng để chỉ các quốc gia hoặc nhóm người cùng hành động vì mục tiêu chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warrant', 'en-c1-47', 'warrant', '/ˈwɔːrənt/', 'C1', 'lệnh (khám xét, bắt giữ); làm cho có lý; khiến phải; đáng; lý do chính đáng; sự bảo đảm', 'n.', 'warranted (adj.), unwarranted (adj.)', NULL, 'Động từ thường chỉ sự xứng đáng hoặc cần thiết, ví dụ như warrant attention.', 'The officers obtained a warrant before searching the apartment.', NULL, 'Các cảnh sát đã lấy lệnh khám xét trước khi tiến hành lục soát căn hộ.', '{"wordId":"warrant","ukIpa":"/ˈwɒrənt/","usIpa":"/ˈwɔːrənt/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"An official document allowing police to take a particular action.","vi":"lệnh (khám xét, bắt giữ)"},{"pos":"v.","en":"To make a particular action necessary or reasonable.","vi":"làm cho có lý; khiến phải; đáng"},{"pos":"n.","en":"A good reason or justification for something.","vi":"lý do chính đáng; sự bảo đảm"}],"examples":[{"en":"The officers obtained a warrant before searching the apartment.","vi":"Các cảnh sát đã lấy lệnh khám xét trước khi tiến hành lục soát căn hộ.","audioKind":"ex"},{"en":"The potential environmental risks warrant further investigation before the government approves construction of the new industrial facility.","vi":"Những rủi ro môi trường tiềm ẩn đòi hỏi phải có sự điều tra kỹ lưỡng hơn trước khi chính phủ phê duyệt việc xây dựng cơ sở công nghiệp mới.","audioKind":"ex2"}],"collocations":[{"en":"a search warrant","vi":"lệnh khám xét"},{"en":"an arrest warrant","vi":"lệnh bắt giữ"},{"en":"warrant further investigation","vi":"đáng để điều tra thêm"},{"en":"without warrant","vi":"không có lý do chính đáng"}],"wordFamily":["warranted (adj.)","unwarranted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường chỉ sự xứng đáng hoặc cần thiết, ví dụ như warrant attention.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_taxation', 'en-c1-47', 'taxation', '/tækˈseɪʃən/', 'C1', 'hệ thống thuế; việc thu thuế; thuế khóa', 'n.', 'tax (n.), tax (v.), taxable (adj.), taxpayer (n.)', NULL, 'taxation thường là danh từ không đếm được, tập trung vào cơ chế hoặc quá trình thu thuế.', 'Taxation helps pay for our local schools and roads.', NULL, 'Tiền thuế giúp chi trả cho các trường học và con đường ở địa phương chúng ta.', '{"wordId":"taxation","ukIpa":"/tækˈseɪʃən/","usIpa":"/tækˈseɪʃən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"The system or process of collecting money through taxes.","vi":"hệ thống thuế; việc thu thuế; thuế khóa"}],"examples":[{"en":"Taxation helps pay for our local schools and roads.","vi":"Tiền thuế giúp chi trả cho các trường học và con đường ở địa phương chúng ta.","audioKind":"ex"},{"en":"Progressive taxation can reduce income inequality by requiring wealthier citizens to contribute a larger proportion of their earnings.","vi":"Hệ thống thuế lũy tiến có thể giúp giảm bất bình đẳng thu nhập bằng cách yêu cầu những công dân giàu có hơn đóng góp tỷ lệ lớn hơn từ thu nhập của họ.","audioKind":"ex2"}],"collocations":[{"en":"progressive taxation","vi":"hệ thống thuế lũy tiến"},{"en":"direct taxation","vi":"thuế trực thu"},{"en":"double taxation","vi":"đánh thuế trùng"},{"en":"taxation policy","vi":"chính sách thuế"}],"wordFamily":["tax (n.)","tax (v.)","taxable (adj.)","taxpayer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"taxation thường là danh từ không đếm được, tập trung vào cơ chế hoặc quá trình thu thuế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_militia', 'en-c1-47', 'militia', '/mɪˈlɪʃə/', 'C1', 'lực lượng dân quân; tổ chức dân quân', 'n.', NULL, NULL, 'Chỉ tập thể tổ chức; khi nói về một cá nhân thành viên dùng a militia member.', 'The museum displayed uniforms once worn by the local militia.', NULL, 'Bảo tàng trưng bày những bộ quân phục từng được mặc bởi lực lượng dân quân địa phương.', '{"wordId":"militia","ukIpa":"/mɪˈlɪʃə/","usIpa":"/mɪˈlɪʃə/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A military group whose members are not full-time professional soldiers.","vi":"lực lượng dân quân; tổ chức dân quân"}],"examples":[{"en":"The museum displayed uniforms once worn by the local militia.","vi":"Bảo tàng trưng bày những bộ quân phục từng được mặc bởi lực lượng dân quân địa phương.","audioKind":"ex"},{"en":"Historical records show that the militia consisted mainly of farmers who trained alongside their regular work.","vi":"Các tài liệu lịch sử cho thấy lực lượng dân quân chủ yếu bao gồm những người nông dân tham gia huấn luyện bên cạnh công việc đồng áng thường ngày.","audioKind":"ex2"}],"collocations":[{"en":"a local militia","vi":"lực lượng dân quân địa phương"},{"en":"form a militia","vi":"thành lập lực lượng dân quân"},{"en":"militia members","vi":"thành viên dân quân"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ tập thể tổ chức; khi nói về một cá nhân thành viên dùng a militia member.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lax', 'en-c1-47', 'lax', '/læks/', 'C1', 'lỏng lẻo; thiếu nghiêm ngặt; chùng; không săn chắc', 'adj.', 'laxity (n.), laxness (n.), laxly (adv.)', 'Đồng nghĩa: lenient, slack · Trái nghĩa: strict, rigorous', 'Thường dùng để chỉ quy định hoặc việc thực thi thiếu nghiêm ngặt; không dùng từ này để chỉ bệnh tiêu chảy thông thường.', 'The club is lax about checking membership cards.', NULL, 'Câu lạc bộ khá lỏng lẻo trong việc kiểm tra thẻ thành viên.', '{"wordId":"lax","ukIpa":"/læks/","usIpa":"/læks/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"Not strict or careful enough about rules or responsibilities.","vi":"lỏng lẻo; thiếu nghiêm ngặt"},{"pos":"adj.","en":"Not firm, tight, or tense.","vi":"chùng; không săn chắc"}],"examples":[{"en":"The club is lax about checking membership cards.","vi":"Câu lạc bộ khá lỏng lẻo trong việc kiểm tra thẻ thành viên.","audioKind":"ex"},{"en":"Lax enforcement of environmental regulations allows some factories to discharge untreated waste into nearby rivers.","vi":"Việc thực thi các quy định về môi trường lỏng lẻo tạo điều kiện cho một số nhà máy xả thải chưa qua xử lý ra các con sông gần đó.","audioKind":"ex2"}],"collocations":[{"en":"lax security","vi":"an ninh lỏng lẻo"},{"en":"lax enforcement","vi":"thực thi lỏng lẻo"},{"en":"lax standards","vi":"tiêu chuẩn lỏng lẻo"},{"en":"lax about rules","vi":"quản lý quy tắc lỏng lẻo"}],"wordFamily":["laxity (n.)","laxness (n.)","laxly (adv.)"],"synonyms":["lenient","slack"],"antonyms":["strict","rigorous"],"tipVi":"Thường dùng để chỉ quy định hoặc việc thực thi thiếu nghiêm ngặt; không dùng từ này để chỉ bệnh tiêu chảy thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oust', 'en-c1-47', 'oust', '/aʊst/', 'C1', 'hất cẳng; lật đổ; truất ngôi', 'v.', 'ouster (n.)', 'Đồng nghĩa: remove, expel · Trái nghĩa: appoint, install', 'Thường dùng cấu trúc oust someone from office, nhấn mạnh việc bị ép buộc rời khỏi vị trí.', 'Club members voted to oust their unpopular chair.', NULL, 'Các thành viên câu lạc bộ đã bỏ phiếu phế truất vị chủ tịch kém được lòng người.', '{"wordId":"oust","ukIpa":"/aʊst/","usIpa":"/aʊst/","cefr":"C1","topic":"government","senses":[{"pos":"v.","en":"To force someone out of a position or place.","vi":"hất cẳng; lật đổ; truất ngôi"}],"examples":[{"en":"Club members voted to oust their unpopular chair.","vi":"Các thành viên câu lạc bộ đã bỏ phiếu phế truất vị chủ tịch kém được lòng người.","audioKind":"ex"},{"en":"Shareholders may seek to oust company directors who repeatedly fail to meet environmental commitments or financial targets.","vi":"Các cổ đông có thể tìm cách bãi nhiệm những thành viên hội đồng quản trị công ty liên tục không hoàn thành cam kết về môi trường hoặc chỉ tiêu tài chính.","audioKind":"ex2"}],"collocations":[{"en":"oust a leader","vi":"lật đổ một nhà lãnh đạo"},{"en":"oust someone from office","vi":"hất cẳng ai đó khỏi chức vụ"},{"en":"be ousted as chair","vi":"bị bãi nhiệm chức vụ chủ tịch"}],"wordFamily":["ouster (n.)"],"synonyms":["remove","expel"],"antonyms":["appoint","install"],"tipVi":"Thường dùng cấu trúc oust someone from office, nhấn mạnh việc bị ép buộc rời khỏi vị trí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unanimous', 'en-c1-47', 'unanimous', '/juˈnænɪməs/', 'C1', 'nhất trí; đồng lòng', 'adj.', 'unanimously (adv.), unanimity (n.)', 'Trái nghĩa: divided', 'Nhấn mạnh tất cả mọi người đều đồng ý, không chỉ đơn thuần là đa số tán thành.', 'Our family was unanimous about adopting the little cat.', NULL, 'Gia đình chúng tôi đã nhất trí về việc nhận nuôi chú mèo nhỏ.', '{"wordId":"unanimous","ukIpa":"/juˈnænɪməs/","usIpa":"/juˈnænɪməs/","cefr":"C1","topic":"government","senses":[{"pos":"adj.","en":"agreed on by every person in a group","vi":"nhất trí; đồng lòng"}],"examples":[{"en":"Our family was unanimous about adopting the little cat.","vi":"Gia đình chúng tôi đã nhất trí về việc nhận nuôi chú mèo nhỏ.","audioKind":"ex"},{"en":"The committee reached a unanimous decision to improve public transport rather than expand the existing road network.","vi":"Ủy ban đã đạt được quyết định nhất trí về việc cải thiện giao thông công cộng thay vì mở rộng mạng lưới đường xá hiện có.","audioKind":"ex2"}],"collocations":[{"en":"unanimous decision","vi":"quyết định nhất trí"},{"en":"unanimous support","vi":"sự ủng hộ hoàn toàn"},{"en":"unanimous agreement","vi":"sự đồng thuận tuyệt đối"},{"en":"unanimous vote","vi":"cuộc bỏ phiếu nhất trí"}],"wordFamily":["unanimously (adv.)","unanimity (n.)"],"synonyms":[],"antonyms":["divided"],"tipVi":"Nhấn mạnh tất cả mọi người đều đồng ý, không chỉ đơn thuần là đa số tán thành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_petition', 'en-c1-47', 'petition', '/pəˈtɪʃən/', 'C1', 'đơn thỉnh cầu; đơn kiến nghị; làm đơn thỉnh cầu; kiến nghị', 'n.', 'petitioner (n.)', NULL, 'Động từ thường dùng cấu trúc petition somebody to do something.', 'Our neighbours signed a petition to save the playground.', NULL, 'Những người hàng xóm của chúng tôi đã ký vào một bản kiến nghị để bảo vệ khu vui chơi.', '{"wordId":"petition","ukIpa":"/pəˈtɪʃən/","usIpa":"/pəˈtɪʃən/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"A formal written request, often supported by many people''s signatures.","vi":"đơn thỉnh cầu; đơn kiến nghị"},{"pos":"v.","en":"To formally ask an authority to do something.","vi":"làm đơn thỉnh cầu; kiến nghị"}],"examples":[{"en":"Our neighbours signed a petition to save the playground.","vi":"Những người hàng xóm của chúng tôi đã ký vào một bản kiến nghị để bảo vệ khu vui chơi.","audioKind":"ex"},{"en":"Residents submitted a petition asking the council to improve public transport in areas outside the city centre.","vi":"Cư dân đã nộp một bản kiến nghị yêu cầu hội đồng thành phố cải thiện giao thông công cộng ở các khu vực ngoài trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"sign a petition","vi":"ký vào đơn thỉnh cầu"},{"en":"submit a petition","vi":"nộp đơn thỉnh cầu"},{"en":"petition for reform","vi":"thỉnh cầu cải cách"}],"wordFamily":["petitioner (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường dùng cấu trúc petition somebody to do something.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_notary', 'en-c1-47', 'notary', '/ˈnoʊtəri/', 'C1', 'công chứng viên', 'n.', 'notarial (adj.), notarise (v.), notarisation (n.)', NULL, 'còn gọi là notary public; thẩm quyền cụ thể có thể khác nhau tùy theo quốc gia.', 'We signed the property documents in front of a notary.', NULL, 'Chúng tôi đã ký các giấy tờ nhà đất trước mặt một công chứng viên.', '{"wordId":"notary","ukIpa":"/ˈnəʊtəri/","usIpa":"/ˈnoʊtəri/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"An official authorised to witness signatures and certify documents.","vi":"công chứng viên"}],"examples":[{"en":"We signed the property documents in front of a notary.","vi":"Chúng tôi đã ký các giấy tờ nhà đất trước mặt một công chứng viên.","audioKind":"ex"},{"en":"A notary can verify signatures on legal documents, helping reduce the risk of fraud in property transactions.","vi":"Công chứng viên có thể xác thực chữ ký trên các văn bản pháp lý, giúp giảm thiểu rủi ro gian lận trong các giao dịch bất động sản.","audioKind":"ex2"}],"collocations":[{"en":"notary public","vi":"công chứng viên"},{"en":"consult a notary","vi":"tham khảo ý kiến công chứng viên"},{"en":"before a notary","vi":"trước mặt công chứng viên"}],"wordFamily":["notarial (adj.)","notarise (v.)","notarisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"còn gọi là notary public; thẩm quyền cụ thể có thể khác nhau tùy theo quốc gia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_corps', 'en-c1-47', 'corps', '/kɔːr/', 'C1', 'quân đoàn; binh chủng; đội ngũ; tập đoàn chuyên môn', 'n.', NULL, NULL, 'Hình thức số ít và số nhiều viết giống nhau; chữ s ở cuối không phát âm ở dạng số ít và phát âm thành /z/ ở dạng số nhiều.', 'My cousin joined the medical corps after finishing university.', NULL, 'Anh họ tôi gia nhập lực lượng quân y sau khi tốt nghiệp đại học.', '{"wordId":"corps","ukIpa":"/kɔː/","usIpa":"/kɔːr/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"a large military unit or branch with particular duties","vi":"quân đoàn; binh chủng"},{"pos":"n.","en":"an organized group of people doing the same specialized work","vi":"đội ngũ; tập đoàn chuyên môn"}],"examples":[{"en":"My cousin joined the medical corps after finishing university.","vi":"Anh họ tôi gia nhập lực lượng quân y sau khi tốt nghiệp đại học.","audioKind":"ex"},{"en":"The diplomatic corps can support international cooperation by maintaining communication between governments during periods of tension.","vi":"Đoàn ngoại giao có thể hỗ trợ hợp tác quốc tế bằng cách duy trì kênh liên lạc giữa các chính phủ trong những giai đoạn căng thẳng.","audioKind":"ex2"}],"collocations":[{"en":"medical corps","vi":"quân y"},{"en":"diplomatic corps","vi":"đoàn ngoại giao"},{"en":"press corps","vi":"hội nhà báo; đoàn phóng viên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Hình thức số ít và số nhiều viết giống nhau; chữ s ở cuối không phát âm ở dạng số ít và phát âm thành /z/ ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bureau', 'en-c1-47', 'bureau', '/ˈbjʊroʊ/', 'C1', 'cơ quan; sở; ban; văn phòng; bàn giấy có nắp gập; tủ có ngăn kéo', 'n.', NULL, 'Đồng nghĩa: office, agency', 'Dạng số nhiều có thể là bureaux hoặc bureaus; nghĩa chỉ đồ đạc có sự khác biệt giữa tiếng Anh-Anh và tiếng Anh-Mỹ.', 'The tourist bureau gave us a free city map.', NULL, 'Phòng thông tin du lịch đã tặng chúng tôi một bản đồ thành phố miễn phí.', '{"wordId":"bureau","ukIpa":"/ˈbjʊərəʊ/","usIpa":"/ˈbjʊroʊ/","cefr":"C1","topic":"government","senses":[{"pos":"n.","en":"an office or organisation providing information or managing particular activities","vi":"cơ quan; sở; ban; văn phòng"},{"pos":"n.","en":"a desk with a folding cover, or an American chest of drawers","vi":"bàn giấy có nắp gập; tủ có ngăn kéo"}],"examples":[{"en":"The tourist bureau gave us a free city map.","vi":"Phòng thông tin du lịch đã tặng chúng tôi một bản đồ thành phố miễn phí.","audioKind":"ex"},{"en":"A national statistics bureau collects reliable data that governments use to plan public services.","vi":"Cục thống kê quốc gia thu thập dữ liệu đáng tin cậy để chính phủ sử dụng trong việc lập kế hoạch các dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"tourist bureau","vi":"cơ quan du lịch"},{"en":"statistics bureau","vi":"cục thống kê"},{"en":"news bureau","vi":"phân xã tin tức"}],"wordFamily":[],"synonyms":["office","agency"],"antonyms":[],"tipVi":"Dạng số nhiều có thể là bureaux hoặc bureaus; nghĩa chỉ đồ đạc có sự khác biệt giữa tiếng Anh-Anh và tiếng Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_47_1', 'en-c1-47', 'Cách dùng “corps” (n.) — quân đoàn; binh chủng', 'medical corps  ·  diplomatic corps  ·  press corps', 'Hình thức số ít và số nhiều viết giống nhau; chữ s ở cuối không phát âm ở dạng số ít và phát âm thành /z/ ở dạng số nhiều.', NULL, '[{"hanzi":"My cousin joined the medical corps after finishing university.","pinyin":"","meaning":"Anh họ tôi gia nhập lực lượng quân y sau khi tốt nghiệp đại học."},{"hanzi":"The diplomatic corps can support international cooperation by maintaining communication between governments during periods of tension.","pinyin":"","meaning":"Đoàn ngoại giao có thể hỗ trợ hợp tác quốc tế bằng cách duy trì kênh liên lạc giữa các chính phủ trong những giai đoạn căng thẳng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_47_2', 'en-c1-47', 'Cách dùng “lax” (adj.) — lỏng lẻo; thiếu nghiêm ngặt', 'lax security  ·  lax enforcement  ·  lax standards', 'Thường dùng để chỉ quy định hoặc việc thực thi thiếu nghiêm ngặt; không dùng từ này để chỉ bệnh tiêu chảy thông thường.', 'Họ từ (Word Family): laxity (n.), laxness (n.), laxly (adv.) | Đồng nghĩa: lenient, slack · Trái nghĩa: strict, rigorous', '[{"hanzi":"The club is lax about checking membership cards.","pinyin":"","meaning":"Câu lạc bộ khá lỏng lẻo trong việc kiểm tra thẻ thành viên."},{"hanzi":"Lax enforcement of environmental regulations allows some factories to discharge untreated waste into nearby rivers.","pinyin":"","meaning":"Việc thực thi các quy định về môi trường lỏng lẻo tạo điều kiện cho một số nhà máy xả thải chưa qua xử lý ra các con sông gần đó."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_47_3', 'en-c1-47', 'Cách dùng “bureau” (n.) — cơ quan; sở; ban; văn phòng', 'tourist bureau  ·  statistics bureau  ·  news bureau', 'Dạng số nhiều có thể là bureaux hoặc bureaus; nghĩa chỉ đồ đạc có sự khác biệt giữa tiếng Anh-Anh và tiếng Anh-Mỹ.', 'Đồng nghĩa: office, agency', '[{"hanzi":"The tourist bureau gave us a free city map.","pinyin":"","meaning":"Phòng thông tin du lịch đã tặng chúng tôi một bản đồ thành phố miễn phí."},{"hanzi":"A national statistics bureau collects reliable data that governments use to plan public services.","pinyin":"","meaning":"Cục thống kê quốc gia thu thập dữ liệu đáng tin cậy để chính phủ sử dụng trong việc lập kế hoạch các dịch vụ công."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_47_4', 'en-c1-47', 'Cách dùng “bloc” (n.) — khối chính trị; liên minh', 'trading bloc  ·  political bloc  ·  regional bloc', 'Phát âm giống block; bloc chuyên dùng để chỉ các quốc gia hoặc nhóm người cùng hành động vì mục tiêu chung.', 'Đồng nghĩa: alliance, coalition', '[{"hanzi":"The councillors formed a bloc to protect local parks.","pinyin":"","meaning":"Các ủy viên hội đồng đã thành lập một liên minh để bảo vệ các công viên địa phương."},{"hanzi":"A regional trading bloc can strengthen members'' bargaining power while reducing barriers to trade between participating countries.","pinyin":"","meaning":"Một khối mậu dịch khu vực có thể củng cố năng lực đàm phán của các thành viên đồng thời giảm bớt các rào cản thương mại giữa các quốc gia tham gia."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_47_1', 'en-c1-47', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_1_1', 'ten_c1_47_1', 'accord', 'The two clubs reached an accord over sharing equipment.', 'The two clubs reached an accord over sharing equipment.', '/əˈkɔːrd/', 'Hai câu lạc bộ đã đạt được thỏa thuận về việc dùng chung thiết bị.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_1_2', 'ten_c1_47_1', 'invalidate', 'Opening the device yourself may invalidate its warranty.', 'Opening the device yourself may invalidate its warranty.', '/ɪnˈvælɪdeɪt/', 'Việc bạn tự mở thiết bị có thể làm mất hiệu lực bảo hành của nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_1_3', 'ten_c1_47_1', 'tyranny', 'The film follows a village struggling against a ruler''s tyranny.', 'The film follows a village struggling against a ruler''s tyranny.', '/ˈtɪrəni/', 'Bộ phim kể về một ngôi làng đang đấu tranh chống lại ách bạo ngược của kẻ thống trị.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_1_4', 'ten_c1_47_1', 'civic', 'The mayor welcomed visitors outside the new civic centre.', 'The mayor welcomed visitors outside the new civic centre.', '/ˈsɪvɪk/', 'Thị trưởng đã chào đón khách tham quan bên ngoài trung tâm hành chính mới của thành phố.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_1_5', 'ten_c1_47_1', 'stipulate', 'The rental rules stipulate that pets must stay downstairs.', 'The rental rules stipulate that pets must stay downstairs.', '/ˈstɪpjəleɪt/', 'Nội quy cho thuê nhà quy định rõ ràng rằng thú cưng phải ở dưới tầng trệt.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_1_6', 'ten_c1_47_1', 'suppression', 'His suppression of laughter failed when the puppy sneezed.', 'His suppression of laughter failed when the puppy sneezed.', '/səˈpreʃən/', 'Anh ấy không thể kìm được tiếng cười khi chú cún con hắt xì.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_1_7', 'ten_c1_47_1', 'senate', 'Our class watched the senate debate on television today.', 'Our class watched the senate debate on television today.', '/ˈsenət/', 'Lớp chúng tôi đã xem buổi tranh luận của thượng viện trên truyền hình hôm nay.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_1_8', 'ten_c1_47_1', 'amend', 'Please amend the booking to include one extra guest.', 'Please amend the booking to include one extra guest.', '/əˈmend/', 'Xin hãy sửa đổi lại phần đặt phòng để thêm một khách đi cùng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_47_1_1', 'en-c1-47', 'ten_c1_47_1', 'listening', 'listening', 'The two clubs reached an accord over sharing equipment.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc đội mũ bảo hiểm là bắt buộc tại trung tâm leo núi này.","Các ủy viên hội đồng đã thành lập một liên minh để bảo vệ các công viên địa phương.","Các thành viên câu lạc bộ đã bỏ phiếu phế truất vị chủ tịch kém được lòng người.","Hai câu lạc bộ đã đạt được thỏa thuận về việc dùng chung thiết bị."]'::jsonb, 3, 'The two clubs reached an accord over sharing equipment. → Hai câu lạc bộ đã đạt được thỏa thuận về việc dùng chung thiết bị.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_47_1_2', 'en-c1-47', 'ten_c1_47_1', 'listening', 'listening', 'Opening the device yourself may invalidate its warranty.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bảo tàng trưng bày những bộ quân phục từng được mặc bởi lực lượng dân quân địa phương.","Bộ phim kể về một ngôi làng đang đấu tranh chống lại ách bạo ngược của kẻ thống trị.","Anh họ tôi gia nhập lực lượng quân y sau khi tốt nghiệp đại học.","Việc bạn tự mở thiết bị có thể làm mất hiệu lực bảo hành của nó."]'::jsonb, 3, 'Opening the device yourself may invalidate its warranty. → Việc bạn tự mở thiết bị có thể làm mất hiệu lực bảo hành của nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_47_1_3', 'en-c1-47', 'ten_c1_47_1', 'listening', 'listening', 'The film follows a village struggling against a ruler''s tyranny.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bộ phim kể về một ngôi làng đang đấu tranh chống lại ách bạo ngược của kẻ thống trị.","Gia đình chúng tôi đã nhất trí về việc nhận nuôi chú mèo nhỏ.","Việc bạn tự mở thiết bị có thể làm mất hiệu lực bảo hành của nó.","Những người hàng xóm của chúng tôi đã ký vào một bản kiến nghị để bảo vệ khu vui chơi."]'::jsonb, 0, 'The film follows a village struggling against a ruler''s tyranny. → Bộ phim kể về một ngôi làng đang đấu tranh chống lại ách bạo ngược của kẻ thống trị.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_47_2', 'en-c1-47', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_2_1', 'ten_c1_47_2', 'accord', 'An international accord on emissions could encourage countries to adopt cleaner technologies and protect vulnerable ecosystems.', 'An international accord on emissions could encourage countries to adopt cleaner technologies and protect vulnerable ecosystems.', '/əˈkɔːrd/', 'Một hiệp định quốc tế về khí thải có thể khuyến khích các quốc gia áp dụng công nghệ sạch hơn và bảo vệ các hệ sinh thái mỏng manh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_2_2', 'ten_c1_47_2', 'invalidate', 'A sample that excludes older adults may invalidate conclusions about the health needs of the wider population.', 'A sample that excludes older adults may invalidate conclusions about the health needs of the wider population.', '/ɪnˈvælɪdeɪt/', 'Một mẫu nghiên cứu loại trừ người cao tuổi có thể làm mất giá trị các kết luận về nhu cầu chăm sóc sức khỏe của toàn bộ dân số rộng lớn hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_2_3', 'ten_c1_47_2', 'tyranny', 'Independent courts and a free press can help prevent tyranny by holding political leaders accountable.', 'Independent courts and a free press can help prevent tyranny by holding political leaders accountable.', '/ˈtɪrəni/', 'Các tòa án độc lập và báo chí tự do có thể giúp ngăn chặn tình trạng chuyên chế bằng cách bắt các nhà lãnh đạo chính trị chịu trách nhiệm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_2_4', 'ten_c1_47_2', 'civic', 'Schools can strengthen civic responsibility by encouraging students to participate in projects that benefit their local communities.', 'Schools can strengthen civic responsibility by encouraging students to participate in projects that benefit their local communities.', '/ˈsɪvɪk/', 'Các trường học có thể nâng cao trách nhiệm công dân bằng cách khuyến khích học sinh tham gia vào các dự án mang lại lợi ích cho cộng đồng địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_2_5', 'ten_c1_47_2', 'stipulate', 'Employment contracts should stipulate working hours clearly to prevent disputes between employers and their staff.', 'Employment contracts should stipulate working hours clearly to prevent disputes between employers and their staff.', '/ˈstɪpjəleɪt/', 'Hợp đồng lao động nên quy định rõ thời gian làm việc để ngăn ngừa tranh chấp giữa người sử dụng lao động và nhân viên.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_47_2_6', 'ten_c1_47_2', 'suppression', 'The suppression of public debate can weaken trust in institutions and prevent communities from addressing serious problems.', 'The suppression of public debate can weaken trust in institutions and prevent communities from addressing serious problems.', '/səˈpreʃən/', 'Việc bưng bít các cuộc tranh luận công khai có thể làm xói mòn lòng tin vào các tổ chức và ngăn cản cộng đồng giải quyết các vấn đề nghiêm trọng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_47_2_1', 'en-c1-47', 'ten_c1_47_2', 'listening', 'listening', 'An international accord on emissions could encourage countries to adopt cleaner technologies and protect vulnerable ecosystems.', NULL, 'Trong câu vừa nghe, từ “accord” mang nghĩa nào sau đây?', '["nạn đói; tình trạng chết đói","tăng gấp ba","có thể sai lầm; dễ mắc lỗi","hiệp định; hiệp ước"]'::jsonb, 3, '“accord” (/əˈkɔːrd/): hiệp định; hiệp ước. Câu đầy đủ: An international accord on emissions could encourage countries to adopt cleaner technologies and protect vulnerable ecosystems.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_47_2_2', 'en-c1-47', 'ten_c1_47_2', 'listening', 'listening', 'A sample that excludes older adults may invalidate conclusions about the health needs of the wider population.', NULL, 'Trong câu vừa nghe, từ “invalidate” mang nghĩa nào sau đây?', '["bệnh mất ngủ; chứng mất ngủ","bao gồm; gồm có","làm mất hiệu lực; làm cho vô hiệu","từ bỏ; giao lại; nhường lại"]'::jsonb, 2, '“invalidate” (/ɪnˈvælɪdeɪt/): làm mất hiệu lực; làm cho vô hiệu. Câu đầy đủ: A sample that excludes older adults may invalidate conclusions about the health needs of the wider population.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
