INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_47_4', 'en-c1-47', 'The mayor welcomed visitors outside the new civic centre', 'Thị trưởng đã chào đón khách tham quan bên ngoài trung tâm hành chính mới của thành phố.', 'civic /ˈsɪvɪk/', '["outside","centre","the","civic","The","new","visitors","mayor","welcomed"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_47_5', 'en-c1-47', 'The rental rules stipulate that pets must stay downstairs', 'Nội quy cho thuê nhà quy định rõ ràng rằng thú cưng phải ở dưới tầng trệt.', 'stipulate /ˈstɪpjəleɪt/', '["that","downstairs","rental","rules","The","must","stipulate","stay","pets"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
