INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_47_7', 'en-c1-47', 'Our class watched the senate debate on television today', 'Lớp chúng tôi đã xem buổi tranh luận của thượng viện trên truyền hình hôm nay.', 'senate /ˈsenət/', '["television","on","debate","watched","today","the","class","Our","senate"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
