INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_1', 'en-c1-47', NULL, 'comprehensive_test', 'listening', 'accord', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự suy giảm; sự xuống cấp; sự hư hỏng","hiệp định; hiệp ước","ủng hộ; bảo vệ; duy trì","tội phản quốc"]'::jsonb, 1, 'accord (/əˈkɔːrd/) → hiệp định; hiệp ước; sự hòa hợp; sự thống nhất; ban tặng; trao cho', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_2', 'en-c1-47', NULL, 'comprehensive_test', 'listening', 'Opening the device yourself may invalidate its warranty.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hai câu lạc bộ đã đạt được thỏa thuận về việc dùng chung thiết bị.","Xin hãy sửa đổi lại phần đặt phòng để thêm một khách đi cùng.","Việc bạn tự mở thiết bị có thể làm mất hiệu lực bảo hành của nó.","Sắc lệnh mới có nghĩa là con phố của chúng ta sẽ tiếp tục bị đóng cửa vào tối nay."]'::jsonb, 2, 'Opening the device yourself may invalidate its warranty. → Việc bạn tự mở thiết bị có thể làm mất hiệu lực bảo hành của nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_3', 'en-c1-47', NULL, 'comprehensive_test', 'listening', 'tyranny', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chế độ bạo ngược; nền chuyên chế","rõ ràng; thẳng thắn; dứt khoát","có tính chất di cư; thích di trú","thảo nguyên Bắc Mỹ"]'::jsonb, 0, 'tyranny (/ˈtɪrəni/) → chế độ bạo ngược; nền chuyên chế; sự áp bức; sự kìm kẹp tàn bạo', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_4', 'en-c1-47', NULL, 'comprehensive_test', 'listening', 'The mayor welcomed visitors outside the new civic centre.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hai câu lạc bộ đã đạt được thỏa thuận về việc dùng chung thiết bị.","Loại thuốc này bắt buộc phải được bảo quản lạnh.","Tiền thuế giúp chi trả cho các trường học và con đường ở địa phương chúng ta.","Thị trưởng đã chào đón khách tham quan bên ngoài trung tâm hành chính mới của thành phố."]'::jsonb, 3, 'The mayor welcomed visitors outside the new civic centre. → Thị trưởng đã chào đón khách tham quan bên ngoài trung tâm hành chính mới của thành phố.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_5', 'en-c1-47', NULL, 'comprehensive_test', 'listening', 'stipulate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hình thành ý tưởng; tưởng tượng","nhiều sự kiện; đầy biến động; nhiều chuyện","quy định rõ ràng; thỏa thuận cụ thể một điều kiện như một phần của hợp đồng","sự khởi đầu; sự bắt đầu (thường là điều không dễ chịu)"]'::jsonb, 2, 'stipulate (/ˈstɪpjəleɪt/) → quy định rõ ràng; thỏa thuận cụ thể một điều kiện như một phần của hợp đồng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_6', 'en-c1-47', NULL, 'comprehensive_test', 'listening', 'His suppression of laughter failed when the puppy sneezed.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Các thành viên câu lạc bộ đã bỏ phiếu phế truất vị chủ tịch kém được lòng người.","Thị trưởng đã chào đón khách tham quan bên ngoài trung tâm hành chính mới của thành phố.","Anh ấy không thể kìm được tiếng cười khi chú cún con hắt xì.","Việc bạn tự mở thiết bị có thể làm mất hiệu lực bảo hành của nó."]'::jsonb, 2, 'His suppression of laughter failed when the puppy sneezed. → Anh ấy không thể kìm được tiếng cười khi chú cún con hắt xì.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_7', 'en-c1-47', NULL, 'comprehensive_test', 'listening', 'senate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mũi đất; hải vạn","gitu điềm gở; báo hiệu điều chẳng lành; đe dọa","thượng viện","sự khởi đầu; sự bắt đầu (thường là điều không dễ chịu)"]'::jsonb, 2, 'senate (/ˈsenət/) → thượng viện; viện nguyên lão', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_8', 'en-c1-47', NULL, 'comprehensive_test', 'listening', 'Please amend the booking to include one extra guest.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin hãy sửa đổi lại phần đặt phòng để thêm một khách đi cùng.","Các thành viên câu lạc bộ đã bỏ phiếu phế truất vị chủ tịch kém được lòng người.","Loại thuốc này bắt buộc phải được bảo quản lạnh.","Hai câu lạc bộ đã đạt được thỏa thuận về việc dùng chung thiết bị."]'::jsonb, 0, 'Please amend the booking to include one extra guest. → Xin hãy sửa đổi lại phần đặt phòng để thêm một khách đi cùng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
