INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_18', 'en-c1-47', NULL, 'comprehensive_test', 'reading', NULL, 'An international accord on emissions could encourage countries to adopt cleaner technologies and protect vulnerable ecosystems.', 'Dựa vào câu trên, từ “accord” có nghĩa phù hợp nhất là gì?', '["gửi, phái (ai hoặc cái gì đi đến một địa điểm cụ thể)","hiệp định; hiệp ước","bình xịt; chất khí dung (bình nén phun chất lỏng thành tia mịn)","vặt vãnh; nhỏ nhặt"]'::jsonb, 1, 'accord: hiệp định; hiệp ước; sự hòa hợp; sự thống nhất; ban tặng; trao cho. Dịch cả câu: Một hiệp định quốc tế về khí thải có thể khuyến khích các quốc gia áp dụng công nghệ sạch hơn và bảo vệ các hệ sinh thái mỏng manh.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_19', 'en-c1-47', NULL, 'comprehensive_test', 'reading', NULL, 'A sample that excludes older adults may invalidate conclusions about the health needs of the wider population.', 'Dựa vào câu trên, từ “invalidate” có nghĩa phù hợp nhất là gì?', '["ca ngợi hết lời; tán dương nhiệt liệt","đa năng; linh hoạt, nhiều công dụng","phát triển mạnh; hưng thịnh","làm mất hiệu lực; làm cho vô hiệu"]'::jsonb, 3, 'invalidate: làm mất hiệu lực; làm cho vô hiệu; làm cho không còn đúng; bác bỏ. Dịch cả câu: Một mẫu nghiên cứu loại trừ người cao tuổi có thể làm mất giá trị các kết luận về nhu cầu chăm sóc sức khỏe của toàn bộ dân số rộng lớn hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_20', 'en-c1-47', NULL, 'comprehensive_test', 'reading', NULL, 'Independent courts and a free press can help prevent tyranny by holding political leaders accountable.', 'Dựa vào câu trên, từ “tyranny” có nghĩa phù hợp nhất là gì?', '["cuộc bỏ phiếu kín; sự biểu quyết","khơi dậy; gây ra; kích thích","giành chiến thắng; thắng lợi","chế độ bạo ngược; nền chuyên chế"]'::jsonb, 3, 'tyranny: chế độ bạo ngược; nền chuyên chế; sự áp bức; sự kìm kẹp tàn bạo. Dịch cả câu: Các tòa án độc lập và báo chí tự do có thể giúp ngăn chặn tình trạng chuyên chế bằng cách bắt các nhà lãnh đạo chính trị chịu trách nhiệm.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_21', 'en-c1-47', NULL, 'comprehensive_test', 'reading', NULL, 'Schools can strengthen civic responsibility by encouraging students to participate in projects that benefit their local communities.', 'Dựa vào câu trên, từ “civic” có nghĩa phù hợp nhất là gì?', '["vũ trụ (được xem như một hệ thống có trật tự, hoàn chỉnh)","kín đáo; ít nói; không muốn bộc lộ","sự loại bỏ; sự tiêu diệt","thuộc về thành phố; thuộc về đô thị hoặc hành chính đô thị"]'::jsonb, 3, 'civic: thuộc về thành phố; thuộc về đô thị hoặc hành chính đô thị; thuộc về công dân; liên quan đến trách nhiệm công dân trong cộng đồng. Dịch cả câu: Các trường học có thể nâng cao trách nhiệm công dân bằng cách khuyến khích học sinh tham gia vào các dự án mang lại lợi ích cho cộng đồng địa phương.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_22', 'en-c1-47', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “công chứng viên”', '["regretful","outset","hoist","notary"]'::jsonb, 3, 'công chứng viên → notary (/ˈnoʊtəri/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_23', 'en-c1-47', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “quân đoàn; binh chủng”', '["corps","initiate","fellowship","hydraulic"]'::jsonb, 0, 'quân đoàn; binh chủng → corps (/kɔːr/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_47_24', 'en-c1-47', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cơ quan; sở; ban; văn phòng”', '["bureau","paralyse","imperative","propagate"]'::jsonb, 0, 'cơ quan; sở; ban; văn phòng → bureau (/ˈbjʊroʊ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-48', 'en', 'Bài 48: Lịch sử & Văn hóa (1) - CEFR C1', 'CEFR C1', 'C1 · Lịch sử', '24 từ vựng Tiếng Anh CEFR C1 chủ đề lịch sử & văn hóa kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5048, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dagger', 'en-c1-48', 'dagger', '/ˈdæɡər/', 'C1', 'dao găm; đoản kiếm', 'n.', NULL, NULL, 'look daggers at someone là một thành ngữ, có nghĩa là nhìn ai đó với vẻ tức giận.', 'An ancient dagger lay inside the museum''s glass case.', NULL, 'Một cây dao găm cổ nằm bên trong tủ kính của bảo hiểm.', '{"wordId":"dagger","ukIpa":"/ˈdæɡə/","usIpa":"/ˈdæɡər/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"A short pointed knife, usually with two sharp edges.","vi":"dao găm; đoản kiếm"}],"examples":[{"en":"An ancient dagger lay inside the museum''s glass case.","vi":"Một cây dao găm cổ nằm bên trong tủ kính của bảo hiểm.","audioKind":"ex"},{"en":"The discovery of a decorated dagger provides evidence of advanced metalworking skills in this ancient settlement.","vi":"Việc phát hiện ra một cây dao găm có chạm trổ cung cấp bằng chứng về kỹ năng gia công kim loại tiên tiến tại khu định cư cổ đại này.","audioKind":"ex2"}],"collocations":[{"en":"a ceremonial dagger","vi":"dao găm dùng trong nghi lễ"},{"en":"a sheathed dagger","vi":"dao găm nằm trong bao"},{"en":"look daggers at someone","vi":"nhìn ai đó với ánh mắt tức giận"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"look daggers at someone là một thành ngữ, có nghĩa là nhìn ai đó với vẻ tức giận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_descendant', 'en-c1-48', 'descendant', '/dɪˈsendənt/', 'C1', 'hậu duệ; con cháu; vật phái sinh; hình thức kế thừa', 'n.', 'descend (v.), descent (n.)', 'Trái nghĩa: ancestor', 'descendant là hậu duệ; ancestor là tổ tiên.', 'Her descendants still live in the old family farmhouse.', NULL, 'Con cháu của bà ấy vẫn sống trong ngôi nhà nông trại cổ của gia đình.', '{"wordId":"descendant","ukIpa":"/dɪˈsendənt/","usIpa":"/dɪˈsendənt/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"Someone related to a person who lived in an earlier generation.","vi":"hậu duệ; con cháu"},{"pos":"n.","en":"Something developed from an earlier form of something similar.","vi":"vật phái sinh; hình thức kế thừa"}],"examples":[{"en":"Her descendants still live in the old family farmhouse.","vi":"Con cháu của bà ấy vẫn sống trong ngôi nhà nông trại cổ của gia đình.","audioKind":"ex"},{"en":"Preserving traditional crafts allows descendants of local communities to maintain meaningful connections with their cultural heritage.","vi":"Việc bảo tồn các nghề thủ công truyền thống giúp thế hệ con cháu của cộng đồng địa phương duy trì mối liên hệ ý nghĩa với di sản văn hóa của họ.","audioKind":"ex2"}],"collocations":[{"en":"direct descendant","vi":"hậu duệ trực hệ"},{"en":"descendant of","vi":"con cháu của"},{"en":"descendants of immigrants","vi":"con cháu của những người nhập cư"}],"wordFamily":["descend (v.)","descent (n.)"],"synonyms":[],"antonyms":["ancestor"],"tipVi":"descendant là hậu duệ; ancestor là tổ tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imperialism', 'en-c1-48', 'imperialism', '/ɪmˈpɪriəlɪzəm/', 'C1', 'chủ nghĩa đế quốc; chính sách bành trướng đế quốc', 'n.', 'imperial (adj.), imperialist (n.), imperialistic (adj.)', NULL, 'Thường là danh từ không đếm được; nhấn mạnh việc một quốc gia mở rộng quyền thống trị hoặc ảnh hưởng ra bên ngoài.', 'We discussed imperialism after visiting the history museum yesterday.', NULL, 'Chúng tôi đã thảo luận về chủ nghĩa đế quốc sau khi tham quan bảo tàng lịch sử ngày hôm qua.', '{"wordId":"imperialism","ukIpa":"/ɪmˈpɪəriəlɪzəm/","usIpa":"/ɪmˈpɪriəlɪzəm/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"A policy of extending a country''s power over other countries.","vi":"chủ nghĩa đế quốc; chính sách bành trướng đế quốc"}],"examples":[{"en":"We discussed imperialism after visiting the history museum yesterday.","vi":"Chúng tôi đã thảo luận về chủ nghĩa đế quốc sau khi tham quan bảo tàng lịch sử ngày hôm qua.","audioKind":"ex"},{"en":"The legacy of imperialism continues to influence economic relationships and debates about cultural identity in many societies.","vi":"Di sản của chủ nghĩa đế quốc vẫn tiếp tục chi phối các mối quan hệ kinh tế và các cuộc tranh luận về bản sắc văn hóa ở nhiều xã hội.","audioKind":"ex2"}],"collocations":[{"en":"cultural imperialism","vi":"chủ nghĩa đế quốc văn hóa"},{"en":"economic imperialism","vi":"chủ nghĩa đế quốc kinh tế"},{"en":"the legacy of imperialism","vi":"di sản của chủ nghĩa đế quốc"}],"wordFamily":["imperial (adj.)","imperialist (n.)","imperialistic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; nhấn mạnh việc một quốc gia mở rộng quyền thống trị hoặc ảnh hưởng ra bên ngoài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_holocaust', 'en-c1-48', 'holocaust', '/ˈhɑːləkɔːst/', 'C1', 'sự tàn phá quy mô lớn; thảm họa diệt chủng; cuộc thảm sát người Do Thái của Đức Quốc Xã trong Thế chiến thứ hai', 'n.', NULL, NULL, 'Trặc chỉ nạn nhân thảm sát người Do Thái thì dùng the Holocaust, viết hoa chữ cái đầu.', 'The film follows a family escaping a nuclear holocaust.', NULL, 'Bộ phim xoay quanh một gia đình đang trốn chạy khỏi một thảm họa hạt nhân.', '{"wordId":"holocaust","ukIpa":"/ˈhɒləkɔːst/","usIpa":"/ˈhɑːləkɔːst/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"Destruction or killing on a very large scale.","vi":"sự tàn phá quy mô lớn; thảm họa diệt chủng"},{"pos":"n.","en":"The Nazi murder of six million Jews during World War Two.","vi":"cuộc thảm sát người Do Thái của Đức Quốc Xã trong Thế chiến thứ hai"}],"examples":[{"en":"The film follows a family escaping a nuclear holocaust.","vi":"Bộ phim xoay quanh một gia đình đang trốn chạy khỏi một thảm họa hạt nhân.","audioKind":"ex"},{"en":"Teaching students about the Holocaust can encourage critical reflection on prejudice, discrimination, and human rights.","vi":"Việc dạy học sinh về cuộc thảm sát Holocaust có thể thúc đẩy tư duy phản biện về định kiến, sự kỳ thị và nhân quyền.","audioKind":"ex2"}],"collocations":[{"en":"nuclear holocaust","vi":"thảm họa hạt nhân"},{"en":"Holocaust survivors","vi":"những người sống sót sau thảm sát Holocaust"},{"en":"Holocaust remembrance","vi":"lễ tưởng niệm nạn nhân thảm sát Holocaust"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trặc chỉ nạn nhân thảm sát người Do Thái thì dùng the Holocaust, viết hoa chữ cái đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aristocracy', 'en-c1-48', 'aristocracy', '/ˌærɪˈstɑːkrəsi/', 'C1', 'tầng lớp quý tộc (giai cấp xã hội cao nhất, có tước vị và đặc quyền thế tập); chế độ quý tộc trị (hình thức chính quyền do tầng lớp quý tộc nắm quyền)', 'n.', 'aristocrat (n.), aristocratic (adj.)', 'Đồng nghĩa: nobility', 'Khi chỉ tầng lớp quý tộc nói chung, thường dùng mạo từ the aristocracy.', 'This grand house once belonged to the local aristocracy.', NULL, 'Ngôi biệt thự tráng lệ này từng thuộc về giới quý tộc địa phương.', '{"wordId":"aristocracy","ukIpa":"/ˌærɪˈstɒkrəsi/","usIpa":"/ˌærɪˈstɑːkrəsi/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"the highest social class, traditionally holding inherited titles and privileges","vi":"tầng lớp quý tộc (giai cấp xã hội cao nhất, có tước vị và đặc quyền thế tập)"},{"pos":"n.","en":"government by people belonging to a privileged hereditary class","vi":"chế độ quý tộc trị (hình thức chính quyền do tầng lớp quý tộc nắm quyền)"}],"examples":[{"en":"This grand house once belonged to the local aristocracy.","vi":"Ngôi biệt thự tráng lệ này từng thuộc về giới quý tộc địa phương.","audioKind":"ex"},{"en":"Land ownership historically allowed the aristocracy to exercise considerable influence over political decisions and rural employment.","vi":"Trong lịch sử, quyền sở hữu đất đai đã cho phép tầng lớp quý tộc gây ảnh hưởng lớn đến các quyết định chính trị và việc làm ở nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"the landed aristocracy","vi":"tầng lớp địa chủ quý tộc"},{"en":"the hereditary aristocracy","vi":"giới quý tộc thế tập"},{"en":"a member of the aristocracy","vi":"thành viên thuộc giới quý tộc"}],"wordFamily":["aristocrat (n.)","aristocratic (adj.)"],"synonyms":["nobility"],"antonyms":[],"tipVi":"Khi chỉ tầng lớp quý tộc nói chung, thường dùng mạo từ the aristocracy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remnant', 'en-c1-48', 'remnant', '/ˈremnənt/', 'C1', 'phần còn lại; di tích; vải vụn; mảnh vải thừa', 'n.', NULL, 'Đồng nghĩa: remainder, vestige', 'Thường dùng a remnant of; dạng số nhiều remnants nhấn mạnh các phần còn sót lại.', 'Only a remnant of the old wall still stands.', NULL, 'Chỉ còn lại một đoạn ngắn của bức tường cũ vẫn đứng vững.', '{"wordId":"remnant","ukIpa":"/ˈremnənt/","usIpa":"/ˈremnənt/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"a small part remaining after most has disappeared or been removed","vi":"phần còn lại; di tích"},{"pos":"n.","en":"a small piece of cloth left from a larger length","vi":"vải vụn; mảnh vải thừa"}],"examples":[{"en":"Only a remnant of the old wall still stands.","vi":"Chỉ còn lại một đoạn ngắn của bức tường cũ vẫn đứng vững.","audioKind":"ex"},{"en":"Protecting remnants of ancient woodland can preserve habitats that support rare species and maintain local biodiversity.","vi":"Việc bảo vệ các phần còn lại của khu rừng cổ có thể bảo tồn môi trường sống cho các loài quý hiếm và duy trì đa dạng sinh học địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a remnant of the past","vi":"tàn tích của quá khứ"},{"en":"forest remnants","vi":"vùng rừng sót lại"},{"en":"fabric remnants","vi":"vải vụn"}],"wordFamily":[],"synonyms":["remainder","vestige"],"antonyms":[],"tipVi":"Thường dùng a remnant of; dạng số nhiều remnants nhấn mạnh các phần còn sót lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monumental', 'en-c1-48', 'monumental', '/ˌmɑːnjəˈmentəl/', 'C1', 'to lớn; vĩ đại; vô cùng quan trọng; thuộc về đài tưởng niệm', 'adj.', 'monument (n.), monumentally (adv.)', 'Đồng nghĩa: enormous, immense · Trái nghĩa: insignificant', 'Thường bổ nghĩa cho task, effort, nhấn mạnh quy mô hoặc độ khó cực kỳ lớn.', 'Moving all these boxes will be a monumental task.', NULL, 'Việc di chuyển tất cả các thùng hàng này sẽ là một nhiệm vụ vô cùng nặng nhọc.', '{"wordId":"monumental","ukIpa":"/ˌmɒnjʊˈmentəl/","usIpa":"/ˌmɑːnjəˈmentəl/","cefr":"C1","topic":"history","senses":[{"pos":"adj.","en":"Extremely large, impressive, or important.","vi":"to lớn; vĩ đại; vô cùng quan trọng"},{"pos":"adj.","en":"Relating to monuments or serving as a lasting memorial.","vi":"thuộc về đài tưởng niệm"}],"examples":[{"en":"Moving all these boxes will be a monumental task.","vi":"Việc di chuyển tất cả các thùng hàng này sẽ là một nhiệm vụ vô cùng nặng nhọc.","audioKind":"ex"},{"en":"Replacing outdated urban infrastructure requires monumental effort and sustained investment from both governments and private businesses.","vi":"Việc thay thế cơ sở hạ tầng đô thị lỗi thời đòi hỏi nỗ lực to lớn và nguồn đầu tư bền vững từ cả chính phủ lẫn các doanh nghiệp tư nhân.","audioKind":"ex2"}],"collocations":[{"en":"monumental task","vi":"nhiệm vụ gian nan"},{"en":"monumental achievement","vi":"thành tựu vĩ đại"},{"en":"monumental architecture","vi":"kiến trúc mang tính tượng đài"}],"wordFamily":["monument (n.)","monumentally (adv.)"],"synonyms":["enormous","immense"],"antonyms":["insignificant"],"tipVi":"Thường bổ nghĩa cho task, effort, nhấn mạnh quy mô hoặc độ khó cực kỳ lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assassination', 'en-c1-48', 'assassination', '/əˌsæsɪˈneɪʃən/', 'C1', 'vụ ám sát; hành động thủ tiêu', 'n.', 'assassinate (v.), assassin (n.)', NULL, 'Thường dùng để chỉ hành vi mưu sát nhằm vào nhân vật quan trọng vì động cơ chính trị.', 'The museum guide explained how the assassination changed history.', NULL, 'Hướng dẫn viên bảo tàng giải thích vụ ám sát đó đã thay đổi lịch sử như thế nào.', '{"wordId":"assassination","ukIpa":"/əˌsæsɪˈneɪʃən/","usIpa":"/əˌsæsɪˈneɪʃən/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"the deliberate murder of an important person, often for political reasons","vi":"vụ ám sát; hành động thủ tiêu"}],"examples":[{"en":"The museum guide explained how the assassination changed history.","vi":"Hướng dẫn viên bảo tàng giải thích vụ ám sát đó đã thay đổi lịch sử như thế nào.","audioKind":"ex"},{"en":"The assassination of a political leader can trigger widespread instability and undermine public confidence in government.","vi":"Vụ ám sát một nhà lãnh đạo chính trị có thể châm ngòi cho sự bất ổn diện rộng và làm xói mòn lòng tin của công chúng vào chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"political assassination","vi":"ám sát chính trị"},{"en":"assassination attempt","vi":"mưu sát; ý đồ ám sát"},{"en":"assassination plot","vi":"âm mưu ám sát"}],"wordFamily":["assassinate (v.)","assassin (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng để chỉ hành vi mưu sát nhằm vào nhân vật quan trọng vì động cơ chính trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_divine', 'en-c1-48', 'divine', '/dɪˈvaɪn/', 'C1', 'thuộc về thần thánh; thiêng liêng; tuyệt vời; vô cùng dễ chịu; đoán trước; tiên tri bằng trực giác', 'adj.', 'divinity (n.), divinely (adv.), divination (n.)', 'Đồng nghĩa: godly, heavenly · Trái nghĩa: earthly', 'Khi mang nghĩa "tuyệt vời", từ này thường được dùng trong văn phong khen ngợi không trang trọng.', 'The painting shows divine light surrounding a heavenly figure.', NULL, 'Bức tranh miêu tả ánh sáng thiêng liêng bao quanh một nhân vật thuộc về thiên giới.', '{"wordId":"divine","ukIpa":"/dɪˈvaɪn/","usIpa":"/dɪˈvaɪn/","cefr":"C1","topic":"history","senses":[{"pos":"adj.","en":"Connected with a god or coming from a god","vi":"thuộc về thần thánh; thiêng liêng"},{"pos":"adj.","en":"Extremely pleasant or wonderful","vi":"tuyệt vời; vô cùng dễ chịu"},{"pos":"v.","en":"Discover through intuition or supposed supernatural powers","vi":"đoán trước; tiên tri bằng trực giác"}],"examples":[{"en":"The painting shows divine light surrounding a heavenly figure.","vi":"Bức tranh miêu tả ánh sáng thiêng liêng bao quanh một nhân vật thuộc về thiên giới.","audioKind":"ex"},{"en":"Many ancient societies believed that rulers received divine authority, which helped strengthen their political power.","vi":"Nhiều xã hội cổ đại tin rằng các nhà lãnh đạo nhận được quyền lực thần thánh, điều này giúp củng cố sức mạnh chính trị của họ.","audioKind":"ex2"}],"collocations":[{"en":"divine intervention","vi":"sự can thiệp của thần linh"},{"en":"divine power","vi":"thần lực"},{"en":"taste divine","vi":"có hương vị tuyệt vời"}],"wordFamily":["divinity (n.)","divinely (adv.)","divination (n.)"],"synonyms":["godly","heavenly"],"antonyms":["earthly"],"tipVi":"Khi mang nghĩa \"tuyệt vời\", từ này thường được dùng trong văn phong khen ngợi không trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_genocide', 'en-c1-48', 'genocide', '/ˈdʒenəsaɪd/', 'C1', 'tội ác diệt chủng; nạn diệt chủng', 'n.', 'genocidal (adj.)', NULL, 'Không dùng để chỉ các vụ thảm sát quy mô lớn nói chung, cốt lõi là hành vi cố ý hủy diệt một nhóm người cụ thể.', 'We visited a memorial to the victims of genocide.', NULL, 'Chúng tôi đã đến thăm một đài tưởng niệm các nạn nhân của nạn diệt chủng.', '{"wordId":"genocide","ukIpa":"/ˈdʒenəsaɪd/","usIpa":"/ˈdʒenəsaɪd/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"Acts intended to destroy a national, ethnic, racial, or religious group.","vi":"tội ác diệt chủng; nạn diệt chủng"}],"examples":[{"en":"We visited a memorial to the victims of genocide.","vi":"Chúng tôi đã đến thăm một đài tưởng niệm các nạn nhân của nạn diệt chủng.","audioKind":"ex"},{"en":"Education about past acts of genocide can help societies recognise prejudice and strengthen their commitment to human rights.","vi":"Giáo dục về các hành vi diệt chủng trong quá khứ có thể giúp các xã hội nhận diện định kiến và củng cố cam kết đối với nhân quyền.","audioKind":"ex2"}],"collocations":[{"en":"commit genocide","vi":"thực hiện hành vi diệt chủng"},{"en":"prevent genocide","vi":"ngăn chặn diệt chủng"},{"en":"victims of genocide","vi":"nạn nhân của nạn diệt chủng"}],"wordFamily":["genocidal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Không dùng để chỉ các vụ thảm sát quy mô lớn nói chung, cốt lõi là hành vi cố ý hủy diệt một nhóm người cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prophecy', 'en-c1-48', 'prophecy', '/ˈprɑːfəsi/', 'C1', 'lời tiên tri; lời dự ngôn; khả năng tiên tri', 'n.', 'prophesy (v.), prophet (n.), prophetic (adj.)', 'Đồng nghĩa: prediction, foretelling', 'prophecy là danh từ; động từ prophesy có âm cuối đọc là /saɪ/.', 'In the story, an ancient prophecy finally came true.', NULL, 'Trong câu chuyện, một lời tiên tri cổ xưa cuối cùng đã trở thành sự thật.', '{"wordId":"prophecy","ukIpa":"/ˈprɒfəsi/","usIpa":"/ˈprɑːfəsi/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"a statement about the future, often claiming supernatural knowledge","vi":"lời tiên tri; lời dự ngôn"},{"pos":"n.","en":"the supposed ability to know and describe future events","vi":"khả năng tiên tri"}],"examples":[{"en":"In the story, an ancient prophecy finally came true.","vi":"Trong câu chuyện, một lời tiên tri cổ xưa cuối cùng đã trở thành sự thật.","audioKind":"ex"},{"en":"Low expectations can become a self-fulfilling prophecy when students receive less encouragement and fewer opportunities to improve.","vi":"Kỳ vọng thấp có thể trở thành một lời tiên tri tự ứng nghiệm khi học sinh nhận được ít sự khích lệ và ít cơ hội cải thiện hơn.","audioKind":"ex2"}],"collocations":[{"en":"a self-fulfilling prophecy","vi":"lời tiên tri tự ứng nghiệm"},{"en":"fulfil a prophecy","vi":"ứng nghiệm lời tiên tri"},{"en":"the gift of prophecy","vi":"tài tiên tri; thiên phú tiên tri"}],"wordFamily":["prophesy (v.)","prophet (n.)","prophetic (adj.)"],"synonyms":["prediction","foretelling"],"antonyms":[],"tipVi":"prophecy là danh từ; động từ prophesy có âm cuối đọc là /saɪ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_colonialism', 'en-c1-48', 'colonialism', '/kəˈloʊniəlɪzəm/', 'C1', 'chủ nghĩa thực dân; chế độ thực dân', 'n.', 'colony (n.), colonial (adj.), colonise (v.), colonisation (n.)', NULL, 'Thường là danh từ không đếm được; colony nghĩa là thuộc địa, không phải chủ nghĩa thực dân.', 'The museum explores how colonialism changed life on the island.', NULL, 'Bảo tàng khám phá cách chế độ thực dân đã thay đổi cuộc sống trên hòn đảo này.', '{"wordId":"colonialism","ukIpa":"/kəˈləʊniəlɪzəm/","usIpa":"/kəˈloʊniəlɪzəm/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"Control of another territory and its people by a country","vi":"chủ nghĩa thực dân; chế độ thực dân"}],"examples":[{"en":"The museum explores how colonialism changed life on the island.","vi":"Bảo tàng khám phá cách chế độ thực dân đã thay đổi cuộc sống trên hòn đảo này.","audioKind":"ex"},{"en":"The legacy of colonialism continues to influence language, economic structures, and political institutions in many countries.","vi":"Di sản của chủ nghĩa thực dân vẫn tiếp tục tác động đến ngôn ngữ, cấu trúc kinh tế và các thể chế chính trị ở nhiều quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"the legacy of colonialism","vi":"di sản của chủ nghĩa thực dân"},{"en":"resistance to colonialism","vi":"sự kháng cự chống lại chủ nghĩa thực dân"},{"en":"the end of colonialism","vi":"sự chấm dứt chế độ thực dân"}],"wordFamily":["colony (n.)","colonial (adj.)","colonise (v.)","colonisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; colony nghĩa là thuộc địa, không phải chủ nghĩa thực dân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gramophone', 'en-c1-48', 'gramophone', '/ˈɡræməfoʊn/', 'C1', 'lưu thanh cơ; máy hát đĩa cổ', 'n.', NULL, 'Đồng nghĩa: phonograph', 'Chỉ máy phát đĩa hát cổ; tiếng Anh-Mỹ thường gọi là "phonograph".', 'My grandfather played an old record on his gramophone.', NULL, 'Ông tôi đã bật một đĩa hát cũ trên chiếc máy hát của mình.', '{"wordId":"gramophone","ukIpa":"/ˈɡræməfəʊn/","usIpa":"/ˈɡræməfoʊn/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"an old machine that plays sound from flat records","vi":"lưu thanh cơ; máy hát đĩa cổ"}],"examples":[{"en":"My grandfather played an old record on his gramophone.","vi":"Ông tôi đã bật một đĩa hát cũ trên chiếc máy hát của mình.","audioKind":"ex"},{"en":"The gramophone transformed home entertainment by allowing families to enjoy recorded music without attending live performances.","vi":"Chiếc máy hát đã làm thay đổi hình thức giải trí tại gia khi cho phép các gia đình thưởng thức âm nhạc được ghi âm mà không cần phải đến xem các buổi biểu diễn trực tiếp.","audioKind":"ex2"}],"collocations":[{"en":"a wind-up gramophone","vi":"máy hát lên dây cót"},{"en":"a gramophone record","vi":"đĩa hát"},{"en":"play a gramophone","vi":"chơi máy hát"}],"wordFamily":[],"synonyms":["phonograph"],"antonyms":[],"tipVi":"Chỉ máy phát đĩa hát cổ; tiếng Anh-Mỹ thường gọi là \"phonograph\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_biographer', 'en-c1-48', 'biographer', '/baɪˈɑːɡrəfər/', 'C1', 'nhà viết tiểu sử', 'n.', 'biography (n.), biographical (adj.), autobiography (n.)', NULL, 'Biographer viết tiểu sử về người khác; tự truyện là autobiography.', 'The biographer interviewed my grandmother about her childhood friend.', NULL, 'Nhà viết tiểu sử đã phỏng vấn bà tôi về người bạn thời thơ ấu của bà.', '{"wordId":"biographer","ukIpa":"/baɪˈɒɡrəfə/","usIpa":"/baɪˈɑːɡrəfər/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"Someone who writes an account of another person''s life.","vi":"nhà viết tiểu sử"}],"examples":[{"en":"The biographer interviewed my grandmother about her childhood friend.","vi":"Nhà viết tiểu sử đã phỏng vấn bà tôi về người bạn thời thơ ấu của bà.","audioKind":"ex"},{"en":"A responsible biographer compares multiple sources before drawing conclusions about a historical figure''s personal motivations.","vi":"Một nhà viết tiểu sử có trách nhiệm sẽ so sánh nhiều nguồn tài liệu trước khi đưa ra kết luận về động lực cá nhân của một nhân vật lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"an official biographer","vi":"nhà viết tiểu sử chính thức"},{"en":"a royal biographer","vi":"nhà viết tiểu sử hoàng gia"},{"en":"a renowned biographer","vi":"nhà viết tiểu sử nổi tiếng"}],"wordFamily":["biography (n.)","biographical (adj.)","autobiography (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Biographer viết tiểu sử về người khác; tự truyện là autobiography.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exile', 'en-c1-48', 'exile', '/ˈeksaɪl/', 'C1', 'sự lưu vong, sự bị đày ải khỏi quê hương, thường vì lý do chính trị; người lưu vong, người bị bắt buộc phải sống xa quê hương; lưu đày, đày ải, ép buộc ai đó phải rời khỏi đất nước của họ', 'n.', 'exiled (adj.)', 'Đồng nghĩa: banishment', 'Cụm in exile diễn tả trạng thái đang lưu vong, thường không đi kèm mạo từ.', 'After years in exile, she finally returned home.', NULL, 'Sau nhiều năm sống lưu vong, cuối cùng cô ấy cũng được trở về quê hương.', '{"wordId":"exile","ukIpa":"/ˈeksaɪl/","usIpa":"/ˈeksaɪl/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"Forced absence from one''s own country, often for political reasons","vi":"sự lưu vong, sự bị đày ải khỏi quê hương, thường vì lý do chính trị"},{"pos":"n.","en":"A person forced to live away from their own country","vi":"người lưu vong, người bị bắt buộc phải sống xa quê hương"},{"pos":"v.","en":"To force someone to leave their own country","vi":"lưu đày, đày ải, ép buộc ai đó phải rời khỏi đất nước của họ"}],"examples":[{"en":"After years in exile, she finally returned home.","vi":"Sau nhiều năm sống lưu vong, cuối cùng cô ấy cũng được trở về quê hương.","audioKind":"ex"},{"en":"Many writers living in exile use literature to preserve cultural traditions and describe their experiences of displacement.","vi":"Nhiều nhà văn sống cảnh lưu vong sử dụng văn học để gìn giữ các truyền thống văn hóa và miêu tả trải nghiệm phải tha hương cầu thực của họ.","audioKind":"ex2"}],"collocations":[{"en":"in exile","vi":"sống lưu vong"},{"en":"political exile","vi":"người lưu vong chính trị"},{"en":"force someone into exile","vi":"buộc ai đó phải đi lưu vong"},{"en":"exile someone from","vi":"trục xuất ai khỏi"}],"wordFamily":["exiled (adj.)"],"synonyms":["banishment"],"antonyms":[],"tipVi":"Cụm in exile diễn tả trạng thái đang lưu vong, thường không đi kèm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imperial', 'en-c1-48', 'imperial', '/ɪmˈpɪriəl/', 'C1', 'thuộc về đế quốc; thuộc về hoàng gia; theo hệ đo lường Anh', 'adj.', 'empire (n.), emperor (n.), imperialism (n.), imperialist (n.)', NULL, 'Imperial units chỉ các đơn vị đo lường hệ Anh, đối lập với metric units (hệ mét).', 'We admired the golden roof of the imperial palace.', NULL, 'Chúng tôi trầm trồ trước mái ngói vàng rực của cung điện hoàng gia.', '{"wordId":"imperial","ukIpa":"/ɪmˈpɪəriəl/","usIpa":"/ɪmˈpɪriəl/","cefr":"C1","topic":"history","senses":[{"pos":"adj.","en":"relating to an empire or its ruler","vi":"thuộc về đế quốc; thuộc về hoàng gia"},{"pos":"adj.","en":"using measurement units such as inches, pounds, and gallons","vi":"theo hệ đo lường Anh"}],"examples":[{"en":"We admired the golden roof of the imperial palace.","vi":"Chúng tôi trầm trồ trước mái ngói vàng rực của cung điện hoàng gia.","audioKind":"ex"},{"en":"Former imperial capitals often preserve architectural features that reflect their historical wealth and political influence.","vi":"Các kinh đô cũ của đế quốc thường bảo lưu những nét kiến trúc phản ánh sự thịnh vượng trong lịch sử và tầm ảnh hưởng chính trị của chúng.","audioKind":"ex2"}],"collocations":[{"en":"imperial palace","vi":"cung điện hoàng gia"},{"en":"imperial power","vi":"thế lực đế quốc"},{"en":"imperial rule","vi":"sự thống trị của đế quốc"},{"en":"imperial units","vi":"đơn vị đo lường theo hệ Anh"}],"wordFamily":["empire (n.)","emperor (n.)","imperialism (n.)","imperialist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Imperial units chỉ các đơn vị đo lường hệ Anh, đối lập với metric units (hệ mét).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_massacre', 'en-c1-48', 'massacre', '/ˈmæsəkər/', 'C1', 'cuộc tàn sát; vụ thảm sát; tàn sát; thảm sát', 'n.', NULL, 'Đồng nghĩa: slaughter', 'Chỉ hành động tàn sát quy mô lớn, sắc thái biểu đạt rất nặng nề; tránh dùng cho các vụ tai nạn thương vong thông thường.', 'We visited a memorial to victims of the massacre.', NULL, 'Chúng tôi đã đến thăm đài tưởng niệm các nạn nhân trong vụ thảm sát.', '{"wordId":"massacre","ukIpa":"/ˈmæsəkə/","usIpa":"/ˈmæsəkər/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"The deliberate killing of many people, especially those unable to defend themselves.","vi":"cuộc tàn sát; vụ thảm sát"},{"pos":"v.","en":"To deliberately kill many people, especially those unable to defend themselves.","vi":"tàn sát; thảm sát"}],"examples":[{"en":"We visited a memorial to victims of the massacre.","vi":"Chúng tôi đã đến thăm đài tưởng niệm các nạn nhân trong vụ thảm sát.","audioKind":"ex"},{"en":"Teaching about a historical massacre requires sensitivity, reliable evidence, and respect for victims and their communities.","vi":"Việc giảng dạy về một cuộc thảm sát trong lịch sử đòi hỏi sự tế nhị, bằng chứng đáng tin cậy và lòng tôn kính đối với các nạn nhân cũng như cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"a brutal massacre","vi":"một vụ thảm sát đẫm máu"},{"en":"massacre victims","vi":"nạn nhân của vụ thảm sát"},{"en":"commemorate a massacre","vi":"tưởng niệm một cuộc thảm sát"}],"wordFamily":[],"synonyms":["slaughter"],"antonyms":[],"tipVi":"Chỉ hành động tàn sát quy mô lớn, sắc thái biểu đạt rất nặng nề; tránh dùng cho các vụ tai nạn thương vong thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_originate', 'en-c1-48', 'originate', '/əˈrɪdʒəneɪt/', 'C1', 'bắt nguồn; xuất phát; sáng tạo ra; khởi xướng', 'v.', 'origin (n.), original (adj.), originally (adv.), originator (n.)', NULL, 'Diễn đạt sự khởi nguồn thường đi với giới từ in hoặc from; tránh nhầm lẫn với việc khởi hành đi biển.', 'This recipe originated in a small coastal village.', NULL, 'Công thức món ăn này bắt nguồn từ một ngôi làng ven biển nhỏ.', '{"wordId":"originate","ukIpa":"/əˈrɪdʒɪneɪt/","usIpa":"/əˈrɪdʒəneɪt/","cefr":"C1","topic":"history","senses":[{"pos":"v.","en":"to begin or come from a particular place or situation","vi":"bắt nguồn; xuất phát"},{"pos":"v.","en":"to create or introduce something new","vi":"sáng tạo ra; khởi xướng"}],"examples":[{"en":"This recipe originated in a small coastal village.","vi":"Công thức món ăn này bắt nguồn từ một ngôi làng ven biển nhỏ.","audioKind":"ex"},{"en":"Many environmental problems originate from patterns of consumption rather than a lack of available technology.","vi":"Nhiều vấn đề môi trường bắt nguồn từ mô hình tiêu dùng chứ không phải do thiếu công nghệ khả dụng.","audioKind":"ex2"}],"collocations":[{"en":"originate in","vi":"bắt nguồn ở"},{"en":"originate from","vi":"bắt nguồn từ"},{"en":"originate with","vi":"do ai khởi xướng"}],"wordFamily":["origin (n.)","original (adj.)","originally (adv.)","originator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt sự khởi nguồn thường đi với giới từ in hoặc from; tránh nhầm lẫn với việc khởi hành đi biển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conqueror', 'en-c1-48', 'conqueror', '/ˈkɑːŋkərər/', 'C1', 'kẻ chinh phục; nhà chinh phạt', 'n.', 'conquer (v.), conquest (n.), unconquered (adj.)', NULL, 'Chỉ người dùng vũ lực để chinh phục, không dùng chung cho người thắng cuộc thi đấu.', 'The museum displayed a conqueror''s helmet beside his sword.', NULL, 'Viện bảo tàng trưng bày chiếc mũ của nhà chinh phục bên cạnh thanh kiếm của ông ấy.', '{"wordId":"conqueror","ukIpa":"/ˈkɒŋkərə/","usIpa":"/ˈkɑːŋkərər/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"someone who takes control of a place through military force","vi":"kẻ chinh phục; nhà chinh phạt"}],"examples":[{"en":"The museum displayed a conqueror''s helmet beside his sword.","vi":"Viện bảo tàng trưng bày chiếc mũ của nhà chinh phục bên cạnh thanh kiếm của ông ấy.","audioKind":"ex"},{"en":"A conqueror may impose new laws and customs, profoundly changing the cultural identity of local communities.","vi":"Một nhà chinh phục có thể áp đặt các luật lệ và phong tục mới, làm thay đổi sâu sắc bản sắc văn hóa của các cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a foreign conqueror","vi":"kẻ chinh phục ngoại quốc"},{"en":"a military conqueror","vi":"nhà chinh phạt quân sự"}],"wordFamily":["conquer (v.)","conquest (n.)","unconquered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ người dùng vũ lực để chinh phục, không dùng chung cho người thắng cuộc thi đấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manor', 'en-c1-48', 'manor', '/ˈmænər/', 'C1', 'dinh cơ; biệt thự nhà vườn lớn; đất đai của lãnh chúa; trang viên', 'n.', 'manorial (adj.)', NULL, 'Nhấn mạnh bối cảnh dinh thự ở vùng nông thôn; manor house dùng để chỉ khu nhà chính trong trang viên.', 'We visited an old manor surrounded by apple trees.', NULL, 'Chúng tôi đã tham quan một trang viên cổ kính được bao quanh bởi những hàng cây táo.', '{"wordId":"manor","ukIpa":"/ˈmænə/","usIpa":"/ˈmænər/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"A large country house traditionally belonging to a wealthy landowner.","vi":"dinh cơ; biệt thự nhà vườn lớn"},{"pos":"n.","en":"An estate historically controlled by a lord.","vi":"đất đai của lãnh chúa; trang viên"}],"examples":[{"en":"We visited an old manor surrounded by apple trees.","vi":"Chúng tôi đã tham quan một trang viên cổ kính được bao quanh bởi những hàng cây táo.","audioKind":"ex"},{"en":"Restoring a historic manor can attract visitors and create employment opportunities in rural communities.","vi":"Việc trùng tu một dinh cơ lịch sử có thể thu hút khách du lịch và tạo ra cơ hội việc làm cho các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"a manor house","vi":"dinh thự trang viên"},{"en":"lord of the manor","vi":"lãnh chúa trang viên"},{"en":"a medieval manor","vi":"một trang viên thời trung cổ"}],"wordFamily":["manorial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh bối cảnh dinh thự ở vùng nông thôn; manor house dùng để chỉ khu nhà chính trong trang viên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feudalism', 'en-c1-48', 'feudalism', '/ˈfjuːdəlɪzəm/', 'C1', 'chế độ phong kiến', 'n.', 'feudal (adj.), feudalist (n.)', NULL, 'Là danh từ không đếm được; thường dùng khi thảo luận về quan hệ ruộng đất và lòng trung thành thời Trung cổ ở châu Âu.', 'Our guide explained feudalism as we explored the castle.', NULL, 'Hướng dẫn viên đã giải thích về chế độ phong kiến khi chúng tôi tham quan lâu đài.', '{"wordId":"feudalism","ukIpa":"/ˈfjuːdəlɪzəm/","usIpa":"/ˈfjuːdəlɪzəm/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"A system exchanging land rights for service and loyalty to lords.","vi":"chế độ phong kiến"}],"examples":[{"en":"Our guide explained feudalism as we explored the castle.","vi":"Hướng dẫn viên đã giải thích về chế độ phong kiến khi chúng tôi tham quan lâu đài.","audioKind":"ex"},{"en":"Under feudalism, access to land shaped social relationships and reinforced the power of hereditary ruling groups.","vi":"Dưới thời phong kiến, quyền sở hữu đất đai đã định hình các mối quan hệ xã hội và củng cố quyền lực của các tầng lớp thống trị thế tập.","audioKind":"ex2"}],"collocations":[{"en":"under feudalism","vi":"dưới chế độ phong kiến"},{"en":"the decline of feudalism","vi":"sự suy tàn của chế độ phong kiến"},{"en":"European feudalism","vi":"chế độ phong kiến châu Âu"}],"wordFamily":["feudal (adj.)","feudalist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; thường dùng khi thảo luận về quan hệ ruộng đất và lòng trung thành thời Trung cổ ở châu Âu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dungeon', 'en-c1-48', 'dungeon', '/ˈdʌndʒən/', 'C1', 'hầm ngục; nhà giam dưới lòng đất', 'n.', NULL, NULL, 'Thường chỉ phòng giam tối tăm dưới lòng đất của lâu đài, không phải tầng hầm thông thường.', 'We explored the castle''s cold dungeon with a guide.', NULL, 'Chúng tôi đã cùng hướng dẫn viên khám phá căn hầm ngục lạnh lẽo của lâu đài.', '{"wordId":"dungeon","ukIpa":"/ˈdʌndʒən/","usIpa":"/ˈdʌndʒən/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"a dark underground prison, especially beneath a castle","vi":"hầm ngục; nhà giam dưới lòng đất"}],"examples":[{"en":"We explored the castle''s cold dungeon with a guide.","vi":"Chúng tôi đã cùng hướng dẫn viên khám phá căn hầm ngục lạnh lẽo của lâu đài.","audioKind":"ex"},{"en":"Preserving a medieval dungeon can help museums illustrate how imprisonment and justice have changed over time.","vi":"Việc bảo tồn một hầm ngục thời trung cổ có thể giúp các bảo tàng minh họa cách thức giam giữ và hệ thống tư pháp đã thay đổi như thế nào theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"castle dungeon","vi":"hầm ngục lâu đài"},{"en":"dark dungeon","vi":"hầm ngục tối tăm"},{"en":"escape from a dungeon","vi":"trốn thoát khỏi hầm ngục"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ phòng giam tối tăm dưới lòng đất của lâu đài, không phải tầng hầm thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_epoch', 'en-c1-48', 'epoch', '/ˈepək/', 'C1', 'thời đại; kỷ nguyên; thế (đơn vị thời gian địa chất)', 'n.', 'epochal (adj.)', 'Đồng nghĩa: era, age', 'Mang tính trang trọng và nhấn mạnh đặc điểm thời đại rõ rệt hơn từ period; trong địa chất học, từ này được dịch là thế.', 'These old photographs capture an epoch of rapid change.', NULL, 'Những bức ảnh cũ này đã ghi lại một thời đại thay đổi chóng mặt.', '{"wordId":"epoch","ukIpa":"/ˈiːpɒk/","usIpa":"/ˈepək/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"a period of history marked by distinctive events or changes","vi":"thời đại; kỷ nguyên"},{"pos":"n.","en":"a division of geological time within a period","vi":"thế (đơn vị thời gian địa chất)"}],"examples":[{"en":"These old photographs capture an epoch of rapid change.","vi":"Những bức ảnh cũ này đã ghi lại một thời đại thay đổi chóng mặt.","audioKind":"ex"},{"en":"The development of agriculture marked a new epoch in human history, transforming settlement patterns and social organisation.","vi":"Sự phát triển của nông nghiệp đã đánh dấu một kỷ nguyên mới trong lịch sử loài người, làm thay đổi các hình thức định cư và tổ chức xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a new epoch","vi":"một thời đại mới"},{"en":"a historical epoch","vi":"thời kỳ lịch sử"},{"en":"mark an epoch","vi":"đánh dấu một bước ngoặt thời đại"}],"wordFamily":["epochal (adj.)"],"synonyms":["era","age"],"antonyms":[],"tipVi":"Mang tính trang trọng và nhấn mạnh đặc điểm thời đại rõ rệt hơn từ period; trong địa chất học, từ này được dịch là thế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imperialist', 'en-c1-48', 'imperialist', '/ɪmˈpɪriəlɪst/', 'C1', 'kẻ theo chủ nghĩa đế quốc; mang tính chất đế quốc chủ nghĩa', 'n.', 'imperialism (n.), imperial (adj.), empire (n.)', 'Trái nghĩa: anti-imperialist', 'Có thể đóng vai trò là danh từ chỉ người hoặc tính từ bổ nghĩa cho chính sách hoặc quốc gia.', 'The novel portrays the governor as an ambitious imperialist.', NULL, 'Cuốn tiểu thuyết miêu tả viên tổng đốc là một kẻ theo chủ nghĩa đế quốc đầy tham vọng.', '{"wordId":"imperialist","ukIpa":"/ɪmˈpɪəriəlɪst/","usIpa":"/ɪmˈpɪriəlɪst/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"Someone who supports extending a country''s power over other countries.","vi":"kẻ theo chủ nghĩa đế quốc"},{"pos":"adj.","en":"Supporting or involving a country''s control over other countries.","vi":"mang tính chất đế quốc chủ nghĩa"}],"examples":[{"en":"The novel portrays the governor as an ambitious imperialist.","vi":"Cuốn tiểu thuyết miêu tả viên tổng đốc là một kẻ theo chủ nghĩa đế quốc đầy tham vọng.","audioKind":"ex"},{"en":"Historians examine how imperialist policies reshaped local economies and weakened political independence in colonised regions.","vi":"Các nhà sử học nghiên cứu cách thức mà các chính sách đế quốc chủ nghĩa đã tái định hình nền kinh tế địa phương và làm suy yếu nền độc lập chính trị tại các vùng bị đô hộ.","audioKind":"ex2"}],"collocations":[{"en":"imperialist expansion","vi":"sự bành trướng đế quốc"},{"en":"imperialist policies","vi":"chính sách đế quốc"},{"en":"an imperialist power","vi":"cường quốc đế quốc"}],"wordFamily":["imperialism (n.)","imperial (adj.)","empire (n.)"],"synonyms":[],"antonyms":["anti-imperialist"],"tipVi":"Có thể đóng vai trò là danh từ chỉ người hoặc tính từ bổ nghĩa cho chính sách hoặc quốc gia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_48_1', 'en-c1-48', 'Cách dùng “massacre” (n.) — cuộc tàn sát; vụ thảm sát', 'a brutal massacre  ·  massacre victims  ·  commemorate a massacre', 'Chỉ hành động tàn sát quy mô lớn, sắc thái biểu đạt rất nặng nề; tránh dùng cho các vụ tai nạn thương vong thông thường.', 'Đồng nghĩa: slaughter', '[{"hanzi":"We visited a memorial to victims of the massacre.","pinyin":"","meaning":"Chúng tôi đã đến thăm đài tưởng niệm các nạn nhân trong vụ thảm sát."},{"hanzi":"Teaching about a historical massacre requires sensitivity, reliable evidence, and respect for victims and their communities.","pinyin":"","meaning":"Việc giảng dạy về một cuộc thảm sát trong lịch sử đòi hỏi sự tế nhị, bằng chứng đáng tin cậy và lòng tôn kính đối với các nạn nhân cũng như cộng đồng của họ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_48_2', 'en-c1-48', 'Cách dùng “epoch” (n.) — thời đại; kỷ nguyên', 'a new epoch  ·  a historical epoch  ·  mark an epoch', 'Mang tính trang trọng và nhấn mạnh đặc điểm thời đại rõ rệt hơn từ period; trong địa chất học, từ này được dịch là thế.', 'Họ từ (Word Family): epochal (adj.) | Đồng nghĩa: era, age', '[{"hanzi":"These old photographs capture an epoch of rapid change.","pinyin":"","meaning":"Những bức ảnh cũ này đã ghi lại một thời đại thay đổi chóng mặt."},{"hanzi":"The development of agriculture marked a new epoch in human history, transforming settlement patterns and social organisation.","pinyin":"","meaning":"Sự phát triển của nông nghiệp đã đánh dấu một kỷ nguyên mới trong lịch sử loài người, làm thay đổi các hình thức định cư và tổ chức xã hội."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_48_3', 'en-c1-48', 'Cách dùng “feudalism” (n.) — chế độ phong kiến', 'under feudalism  ·  the decline of feudalism  ·  European feudalism', 'Là danh từ không đếm được; thường dùng khi thảo luận về quan hệ ruộng đất và lòng trung thành thời Trung cổ ở châu Âu.', 'Họ từ (Word Family): feudal (adj.), feudalist (n.)', '[{"hanzi":"Our guide explained feudalism as we explored the castle.","pinyin":"","meaning":"Hướng dẫn viên đã giải thích về chế độ phong kiến khi chúng tôi tham quan lâu đài."},{"hanzi":"Under feudalism, access to land shaped social relationships and reinforced the power of hereditary ruling groups.","pinyin":"","meaning":"Dưới thời phong kiến, quyền sở hữu đất đai đã định hình các mối quan hệ xã hội và củng cố quyền lực của các tầng lớp thống trị thế tập."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_48_4', 'en-c1-48', 'Cách dùng “imperialism” (n.) — chủ nghĩa đế quốc; chính sách bành trướng đế quốc', 'cultural imperialism  ·  economic imperialism  ·  the legacy of imperialism', 'Thường là danh từ không đếm được; nhấn mạnh việc một quốc gia mở rộng quyền thống trị hoặc ảnh hưởng ra bên ngoài.', 'Họ từ (Word Family): imperial (adj.), imperialist (n.), imperialistic (adj.)', '[{"hanzi":"We discussed imperialism after visiting the history museum yesterday.","pinyin":"","meaning":"Chúng tôi đã thảo luận về chủ nghĩa đế quốc sau khi tham quan bảo tàng lịch sử ngày hôm qua."},{"hanzi":"The legacy of imperialism continues to influence economic relationships and debates about cultural identity in many societies.","pinyin":"","meaning":"Di sản của chủ nghĩa đế quốc vẫn tiếp tục chi phối các mối quan hệ kinh tế và các cuộc tranh luận về bản sắc văn hóa ở nhiều xã hội."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_48_1', 'en-c1-48', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
