INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_1_2', 'ten_c1_48_1', 'descendant', 'Her descendants still live in the old family farmhouse.', 'Her descendants still live in the old family farmhouse.', '/dɪˈsendənt/', 'Con cháu của bà ấy vẫn sống trong ngôi nhà nông trại cổ của gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_1_3', 'ten_c1_48_1', 'imperialism', 'We discussed imperialism after visiting the history museum yesterday.', 'We discussed imperialism after visiting the history museum yesterday.', '/ɪmˈpɪriəlɪzəm/', 'Chúng tôi đã thảo luận về chủ nghĩa đế quốc sau khi tham quan bảo tàng lịch sử ngày hôm qua.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_1_4', 'ten_c1_48_1', 'holocaust', 'The film follows a family escaping a nuclear holocaust.', 'The film follows a family escaping a nuclear holocaust.', '/ˈhɑːləkɔːst/', 'Bộ phim xoay quanh một gia đình đang trốn chạy khỏi một thảm họa hạt nhân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_1_5', 'ten_c1_48_1', 'aristocracy', 'This grand house once belonged to the local aristocracy.', 'This grand house once belonged to the local aristocracy.', '/ˌærɪˈstɑːkrəsi/', 'Ngôi biệt thự tráng lệ này từng thuộc về giới quý tộc địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_1_6', 'ten_c1_48_1', 'remnant', 'Only a remnant of the old wall still stands.', 'Only a remnant of the old wall still stands.', '/ˈremnənt/', 'Chỉ còn lại một đoạn ngắn của bức tường cũ vẫn đứng vững.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_1_7', 'ten_c1_48_1', 'monumental', 'Moving all these boxes will be a monumental task.', 'Moving all these boxes will be a monumental task.', '/ˌmɑːnjəˈmentəl/', 'Việc di chuyển tất cả các thùng hàng này sẽ là một nhiệm vụ vô cùng nặng nhọc.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_1_8', 'ten_c1_48_1', 'assassination', 'The museum guide explained how the assassination changed history.', 'The museum guide explained how the assassination changed history.', '/əˌsæsɪˈneɪʃən/', 'Hướng dẫn viên bảo tàng giải thích vụ ám sát đó đã thay đổi lịch sử như thế nào.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_48_1_1', 'en-c1-48', 'ten_c1_48_1', 'listening', 'listening', 'An ancient dagger lay inside the museum''s glass case.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã đến thăm đài tưởng niệm các nạn nhân trong vụ thảm sát.","Công thức món ăn này bắt nguồn từ một ngôi làng ven biển nhỏ.","Bức tranh miêu tả ánh sáng thiêng liêng bao quanh một nhân vật thuộc về thiên giới.","Một cây dao găm cổ nằm bên trong tủ kính của bảo hiểm."]'::jsonb, 3, 'An ancient dagger lay inside the museum''s glass case. → Một cây dao găm cổ nằm bên trong tủ kính của bảo hiểm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_48_1_2', 'en-c1-48', 'ten_c1_48_1', 'listening', 'listening', 'Her descendants still live in the old family farmhouse.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con cháu của bà ấy vẫn sống trong ngôi nhà nông trại cổ của gia đình.","Chúng tôi đã cùng hướng dẫn viên khám phá căn hầm ngục lạnh lẽo của lâu đài.","Viện bảo tàng trưng bày chiếc mũ của nhà chinh phục bên cạnh thanh kiếm của ông ấy.","Chúng tôi đã thảo luận về chủ nghĩa đế quốc sau khi tham quan bảo tàng lịch sử ngày hôm qua."]'::jsonb, 0, 'Her descendants still live in the old family farmhouse. → Con cháu của bà ấy vẫn sống trong ngôi nhà nông trại cổ của gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_48_1_3', 'en-c1-48', 'ten_c1_48_1', 'listening', 'listening', 'We discussed imperialism after visiting the history museum yesterday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bức tranh miêu tả ánh sáng thiêng liêng bao quanh một nhân vật thuộc về thiên giới.","Chúng tôi trầm trồ trước mái ngói vàng rực của cung điện hoàng gia.","Chúng tôi đã đến thăm đài tưởng niệm các nạn nhân trong vụ thảm sát.","Chúng tôi đã thảo luận về chủ nghĩa đế quốc sau khi tham quan bảo tàng lịch sử ngày hôm qua."]'::jsonb, 3, 'We discussed imperialism after visiting the history museum yesterday. → Chúng tôi đã thảo luận về chủ nghĩa đế quốc sau khi tham quan bảo tàng lịch sử ngày hôm qua.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_48_2', 'en-c1-48', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_2_1', 'ten_c1_48_2', 'dagger', 'The discovery of a decorated dagger provides evidence of advanced metalworking skills in this ancient settlement.', 'The discovery of a decorated dagger provides evidence of advanced metalworking skills in this ancient settlement.', '/ˈdæɡər/', 'Việc phát hiện ra một cây dao găm có chạm trổ cung cấp bằng chứng về kỹ năng gia công kim loại tiên tiến tại khu định cư cổ đại này.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_2_2', 'ten_c1_48_2', 'descendant', 'Preserving traditional crafts allows descendants of local communities to maintain meaningful connections with their cultural heritage.', 'Preserving traditional crafts allows descendants of local communities to maintain meaningful connections with their cultural heritage.', '/dɪˈsendənt/', 'Việc bảo tồn các nghề thủ công truyền thống giúp thế hệ con cháu của cộng đồng địa phương duy trì mối liên hệ ý nghĩa với di sản văn hóa của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_2_3', 'ten_c1_48_2', 'imperialism', 'The legacy of imperialism continues to influence economic relationships and debates about cultural identity in many societies.', 'The legacy of imperialism continues to influence economic relationships and debates about cultural identity in many societies.', '/ɪmˈpɪriəlɪzəm/', 'Di sản của chủ nghĩa đế quốc vẫn tiếp tục chi phối các mối quan hệ kinh tế và các cuộc tranh luận về bản sắc văn hóa ở nhiều xã hội.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_2_4', 'ten_c1_48_2', 'holocaust', 'Teaching students about the Holocaust can encourage critical reflection on prejudice, discrimination, and human rights.', 'Teaching students about the Holocaust can encourage critical reflection on prejudice, discrimination, and human rights.', '/ˈhɑːləkɔːst/', 'Việc dạy học sinh về cuộc thảm sát Holocaust có thể thúc đẩy tư duy phản biện về định kiến, sự kỳ thị và nhân quyền.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_2_5', 'ten_c1_48_2', 'aristocracy', 'Land ownership historically allowed the aristocracy to exercise considerable influence over political decisions and rural employment.', 'Land ownership historically allowed the aristocracy to exercise considerable influence over political decisions and rural employment.', '/ˌærɪˈstɑːkrəsi/', 'Trong lịch sử, quyền sở hữu đất đai đã cho phép tầng lớp quý tộc gây ảnh hưởng lớn đến các quyết định chính trị và việc làm ở nông thôn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_48_2_6', 'ten_c1_48_2', 'remnant', 'Protecting remnants of ancient woodland can preserve habitats that support rare species and maintain local biodiversity.', 'Protecting remnants of ancient woodland can preserve habitats that support rare species and maintain local biodiversity.', '/ˈremnənt/', 'Việc bảo vệ các phần còn lại của khu rừng cổ có thể bảo tồn môi trường sống cho các loài quý hiếm và duy trì đa dạng sinh học địa phương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_48_2_1', 'en-c1-48', 'ten_c1_48_2', 'listening', 'listening', 'The discovery of a decorated dagger provides evidence of advanced metalworking skills in this ancient settlement.', NULL, 'Trong câu vừa nghe, từ “dagger” mang nghĩa nào sau đây?', '["sự xác minh; sự kiểm chứng","dao găm; đoản kiếm","chăm chỉ học hành; hiếu học","tổn hại; bất lợi"]'::jsonb, 1, '“dagger” (/ˈdæɡər/): dao găm; đoản kiếm. Câu đầy đủ: The discovery of a decorated dagger provides evidence of advanced metalworking skills in this ancient settlement.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_48_2_2', 'en-c1-48', 'ten_c1_48_2', 'listening', 'listening', 'Preserving traditional crafts allows descendants of local communities to maintain meaningful connections with their cultural heritage.', NULL, 'Trong câu vừa nghe, từ “descendant” mang nghĩa nào sau đây?', '["bắt chước; mô phỏng","mang cảm xúc trái chiều; mâu thuẫn; lưỡng lự","sắp xảy ra; cận kề trong tương lai rất gần","hậu duệ; con cháu"]'::jsonb, 3, '“descendant” (/dɪˈsendənt/): hậu duệ; con cháu. Câu đầy đủ: Preserving traditional crafts allows descendants of local communities to maintain meaningful connections with their cultural heritage.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
