INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_1', 'en-c1-48', NULL, 'comprehensive_test', 'listening', 'dagger', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mũi đất; hải vạn","dao găm; đoản kiếm","vui mừng; hoan hỉ; ăn mừng","xa hoa; phung phí; đắt đỏ"]'::jsonb, 1, 'dagger (/ˈdæɡər/) → dao găm; đoản kiếm', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_2', 'en-c1-48', NULL, 'comprehensive_test', 'listening', 'Her descendants still live in the old family farmhouse.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bức tranh miêu tả ánh sáng thiêng liêng bao quanh một nhân vật thuộc về thiên giới.","Công thức món ăn này bắt nguồn từ một ngôi làng ven biển nhỏ.","Con cháu của bà ấy vẫn sống trong ngôi nhà nông trại cổ của gia đình.","Chúng tôi đã đến thăm một đài tưởng niệm các nạn nhân của nạn diệt chủng."]'::jsonb, 2, 'Her descendants still live in the old family farmhouse. → Con cháu của bà ấy vẫn sống trong ngôi nhà nông trại cổ của gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_3', 'en-c1-48', NULL, 'comprehensive_test', 'listening', 'imperialism', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người cuồng nhiệt; tín đồ (của một hoạt động, sở thích)","thịnh hành; phổ biến","chủ nghĩa đế quốc; chính sách bành trướng đế quốc","người hoặc vật tương đương, có cùng vai trò ở một bối cảnh khác"]'::jsonb, 2, 'imperialism (/ɪmˈpɪriəlɪzəm/) → chủ nghĩa đế quốc; chính sách bành trướng đế quốc', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_4', 'en-c1-48', NULL, 'comprehensive_test', 'listening', 'The film follows a family escaping a nuclear holocaust.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc di chuyển tất cả các thùng hàng này sẽ là một nhiệm vụ vô cùng nặng nhọc.","Bộ phim xoay quanh một gia đình đang trốn chạy khỏi một thảm họa hạt nhân.","Hướng dẫn viên đã giải thích về chế độ phong kiến khi chúng tôi tham quan lâu đài.","Chúng tôi đã cùng hướng dẫn viên khám phá căn hầm ngục lạnh lẽo của lâu đài."]'::jsonb, 1, 'The film follows a family escaping a nuclear holocaust. → Bộ phim xoay quanh một gia đình đang trốn chạy khỏi một thảm họa hạt nhân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_5', 'en-c1-48', NULL, 'comprehensive_test', 'listening', 'aristocracy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bài luận; cuộc thảo luận trang trọng; bài thuyết trình","vĩnh cửu; đời đời; kéo dài mãi mãi","có khả năng xảy ra, dễ bị (đặc biệt là điều bất lợi)","tầng lớp quý tộc (giai cấp xã hội cao nhất, có tước vị và đặc quyền thế tập)"]'::jsonb, 3, 'aristocracy (/ˌærɪˈstɑːkrəsi/) → tầng lớp quý tộc (giai cấp xã hội cao nhất, có tước vị và đặc quyền thế tập); chế độ quý tộc trị (hình thức chính quyền do tầng lớp quý tộc nắm quyền)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_6', 'en-c1-48', NULL, 'comprehensive_test', 'listening', 'Only a remnant of the old wall still stands.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã thảo luận về chủ nghĩa đế quốc sau khi tham quan bảo tàng lịch sử ngày hôm qua.","Chỉ còn lại một đoạn ngắn của bức tường cũ vẫn đứng vững.","Cuốn tiểu thuyết miêu tả viên tổng đốc là một kẻ theo chủ nghĩa đế quốc đầy tham vọng.","Nhà viết tiểu sử đã phỏng vấn bà tôi về người bạn thời thơ ấu của bà."]'::jsonb, 1, 'Only a remnant of the old wall still stands. → Chỉ còn lại một đoạn ngắn của bức tường cũ vẫn đứng vững.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_7', 'en-c1-48', NULL, 'comprehensive_test', 'listening', 'monumental', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chim sơn ca; chimềnmện","chứng hoang tưởng; sự đa nghi; cảm giác bị hại","công việc vất vả, nhàm chán và lặp đi lặp lại","to lớn; vĩ đại; vô cùng quan trọng"]'::jsonb, 3, 'monumental (/ˌmɑːnjəˈmentəl/) → to lớn; vĩ đại; vô cùng quan trọng; thuộc về đài tưởng niệm', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_8', 'en-c1-48', NULL, 'comprehensive_test', 'listening', 'The museum guide explained how the assassination changed history.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bức tranh miêu tả ánh sáng thiêng liêng bao quanh một nhân vật thuộc về thiên giới.","Công thức món ăn này bắt nguồn từ một ngôi làng ven biển nhỏ.","Hướng dẫn viên bảo tàng giải thích vụ ám sát đó đã thay đổi lịch sử như thế nào.","Chúng tôi đã đến thăm đài tưởng niệm các nạn nhân trong vụ thảm sát."]'::jsonb, 2, 'The museum guide explained how the assassination changed history. → Hướng dẫn viên bảo tàng giải thích vụ ám sát đó đã thay đổi lịch sử như thế nào.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_9', 'en-c1-48', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the highest social class, traditionally holding inherited titles and privileges”?', '["descendant","aristocracy","imperialist","imperial"]'::jsonb, 1, 'aristocracy (/ˌærɪˈstɑːkrəsi/) → tầng lớp quý tộc (giai cấp xã hội cao nhất, có tước vị và đặc quyền thế tập)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_10', 'en-c1-48', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a small part remaining after most has disappeared or been removed”?', '["dagger","holocaust","genocide","remnant"]'::jsonb, 3, 'remnant (/ˈremnənt/) → phần còn lại; di tích', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_11', 'en-c1-48', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Extremely large, impressive, or important.”?', '["prophecy","monumental","genocide","gramophone"]'::jsonb, 1, 'monumental (/ˌmɑːnjəˈmentəl/) → to lớn; vĩ đại; vô cùng quan trọng', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_12', 'en-c1-48', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the deliberate murder of an important person, often for political reasons”?', '["aristocracy","conqueror","assassination","divine"]'::jsonb, 2, 'assassination (/əˌsæsɪˈneɪʃən/) → vụ ám sát; hành động thủ tiêu', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_13', 'en-c1-48', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Connected with a god or coming from a god”?', '["epoch","colonialism","divine","imperialism"]'::jsonb, 2, 'divine (/dɪˈvaɪn/) → thuộc về thần thánh; thiêng liêng', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
