INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_18', 'en-c1-48', NULL, 'comprehensive_test', 'reading', NULL, 'The discovery of a decorated dagger provides evidence of advanced metalworking skills in this ancient settlement.', 'Dựa vào câu trên, từ “dagger” có nghĩa phù hợp nhất là gì?', '["người trong cuộc; người nội bộ","dao găm; đoản kiếm","cái mỏ lết; cờ-lê","hang động lớn; động lớn tự nhiên"]'::jsonb, 1, 'dagger: dao găm; đoản kiếm. Dịch cả câu: Việc phát hiện ra một cây dao găm có chạm trổ cung cấp bằng chứng về kỹ năng gia công kim loại tiên tiến tại khu định cư cổ đại này.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_19', 'en-c1-48', NULL, 'comprehensive_test', 'reading', NULL, 'Preserving traditional crafts allows descendants of local communities to maintain meaningful connections with their cultural heritage.', 'Dựa vào câu trên, từ “descendant” có nghĩa phù hợp nhất là gì?', '["sự cấp giấy chứng nhận; chứng chỉ, văn bằng công nhận","hậu duệ; con cháu","khẳng định; quả quyết","ra vẻ ta đây; phô trương; khoe khoang; ra điều cao siêu"]'::jsonb, 1, 'descendant: hậu duệ; con cháu; vật phái sinh; hình thức kế thừa. Dịch cả câu: Việc bảo tồn các nghề thủ công truyền thống giúp thế hệ con cháu của cộng đồng địa phương duy trì mối liên hệ ý nghĩa với di sản văn hóa của họ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_20', 'en-c1-48', NULL, 'comprehensive_test', 'reading', NULL, 'The legacy of imperialism continues to influence economic relationships and debates about cultural identity in many societies.', 'Dựa vào câu trên, từ “imperialism” có nghĩa phù hợp nhất là gì?', '["lời mở đầu; khúc dạo đầu; bước đệm (sự việc xảy ra trước và dẫn dắt cho một sự kiện quan trọng hơn)","tính nhút nhát; sự thiếu tự tin","chủ nghĩa đế quốc; chính sách bành trướng đế quốc","làm ăn mòn; bị ăn mòn (hóa học)"]'::jsonb, 2, 'imperialism: chủ nghĩa đế quốc; chính sách bành trướng đế quốc. Dịch cả câu: Di sản của chủ nghĩa đế quốc vẫn tiếp tục chi phối các mối quan hệ kinh tế và các cuộc tranh luận về bản sắc văn hóa ở nhiều xã hội.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_21', 'en-c1-48', NULL, 'comprehensive_test', 'reading', NULL, 'Teaching students about the Holocaust can encourage critical reflection on prejudice, discrimination, and human rights.', 'Dựa vào câu trên, từ “holocaust” có nghĩa phù hợp nhất là gì?', '["chứng nhận; cấp giấy chứng nhận; xác nhận chính thức","sự tàn phá quy mô lớn; thảm họa diệt chủng","hoài nghi (động cơ của người khác); yếm thế","đòi hỏi; kéo theo; bao hàm"]'::jsonb, 1, 'holocaust: sự tàn phá quy mô lớn; thảm họa diệt chủng; cuộc thảm sát người Do Thái của Đức Quốc Xã trong Thế chiến thứ hai. Dịch cả câu: Việc dạy học sinh về cuộc thảm sát Holocaust có thể thúc đẩy tư duy phản biện về định kiến, sự kỳ thị và nhân quyền.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_22', 'en-c1-48', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hầm ngục; nhà giam dưới lòng đất”', '["dungeon","noted","lament","constraint"]'::jsonb, 0, 'hầm ngục; nhà giam dưới lòng đất → dungeon (/ˈdʌndʒən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_23', 'en-c1-48', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thời đại; kỷ nguyên”', '["sprawl","handicap","permissible","epoch"]'::jsonb, 3, 'thời đại; kỷ nguyên → epoch (/ˈepək/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_48_24', 'en-c1-48', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kẻ theo chủ nghĩa đế quốc”', '["lash","imperialist","posture","genocide"]'::jsonb, 1, 'kẻ theo chủ nghĩa đế quốc → imperialist (/ɪmˈpɪriəlɪst/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-49', 'en', 'Bài 49: Lịch sử & Văn hóa (2) - CEFR C1', 'CEFR C1', 'C1 · Lịch sử', '23 từ vựng Tiếng Anh CEFR C1 chủ đề lịch sử & văn hóa kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5049, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thereafter', 'en-c1-49', 'thereafter', '/ˌðerˈæftər/', 'C1', 'sau đó; từ đó trở đi', 'adv.', NULL, 'Đồng nghĩa: afterwards, subsequently · Trái nghĩa: beforehand', 'Là từ trang trọng chỉ thời gian sau thời điểm vừa nhắc đến; văn phong hàng ngày thường dùng after that.', 'The shop opened in spring and closed shortly thereafter.', NULL, 'Cửa hàng mở cửa vào mùa xuân và đóng cửa ngay sau đó.', '{"wordId":"thereafter","ukIpa":"/ˌðeərˈɑːftə/","usIpa":"/ˌðerˈæftər/","cefr":"C1","topic":"history","senses":[{"pos":"adv.","en":"After the time or event just mentioned","vi":"sau đó; từ đó trở đi"}],"examples":[{"en":"The shop opened in spring and closed shortly thereafter.","vi":"Cửa hàng mở cửa vào mùa xuân và đóng cửa ngay sau đó.","audioKind":"ex"},{"en":"The city introduced stricter vehicle standards, and air quality improved steadily in the years thereafter.","vi":"Thành phố đã áp dụng các tiêu chuẩn xe cộ nghiêm ngặt hơn, và chất lượng không khí đã cải thiện đều đặn trong những năm sau đó.","audioKind":"ex2"}],"collocations":[{"en":"shortly thereafter","vi":"ngay sau đó"},{"en":"soon thereafter","vi":"chẳng bao lâu sau"},{"en":"for years thereafter","vi":"trong nhiều năm sau đó"}],"wordFamily":[],"synonyms":["afterwards","subsequently"],"antonyms":["beforehand"],"tipVi":"Là từ trang trọng chỉ thời gian sau thời điểm vừa nhắc đến; văn phong hàng ngày thường dùng after that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commemorate', 'en-c1-49', 'commemorate', '/kəˈmeməreɪt/', 'C1', 'tưởng niệm; kỷ niệm', 'v.', 'commemoration (n.), commemorative (adj.)', 'Đồng nghĩa: honour, memorialize', 'Kết hợp trực tiếp với đối tượng được tưởng niệm; không nhất thiết mang ý nghĩa vui mừng ăn mừng.', 'We planted a tree to commemorate our grandfather''s life.', NULL, 'Chúng tôi đã trồng một cái cây để kỷ niệm cuộc đời của ông nội.', '{"wordId":"commemorate","ukIpa":"/kəˈmeməreɪt/","usIpa":"/kəˈmeməreɪt/","cefr":"C1","topic":"history","senses":[{"pos":"v.","en":"To honour a person or event by remembering them publicly","vi":"tưởng niệm; kỷ niệm"}],"examples":[{"en":"We planted a tree to commemorate our grandfather''s life.","vi":"Chúng tôi đã trồng một cái cây để kỷ niệm cuộc đời của ông nội.","audioKind":"ex"},{"en":"Public ceremonies commemorate historical events and help younger generations understand the experiences that shaped their communities.","vi":"Các buổi lễ tưởng niệm công khai nhằm tôn vinh các sự kiện lịch sử và giúp thế hệ trẻ thấu hiểu những trải nghiệm đã định hình nên cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"commemorate an event","vi":"kỷ niệm một sự kiện"},{"en":"commemorate an anniversary","vi":"kỷ niệm ngày lễ lớn"},{"en":"commemorate the victims","vi":"tưởng niệm các nạn nhân"}],"wordFamily":["commemoration (n.)","commemorative (adj.)"],"synonyms":["honour","memorialize"],"antonyms":[],"tipVi":"Kết hợp trực tiếp với đối tượng được tưởng niệm; không nhất thiết mang ý nghĩa vui mừng ăn mừng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_torpedo', 'en-c1-49', 'torpedo', '/tɔːrˈpiːdoʊ/', 'C1', 'ngư lôi (vũ khí dưới nước tự hành); phá hoại; làm thất bại (kế hoạch, thỏa thuận)', 'n.', NULL, NULL, 'Ngư lôi là torpedo; thủy lôi là mine. Dạng số nhiều là torpedoes.', 'We saw an old torpedo at the maritime museum.', NULL, 'Chúng tôi đã nhìn thấy một quả ngư lôi cũ tại bảo tàng hàng hải.', '{"wordId":"torpedo","ukIpa":"/tɔːˈpiːdəʊ/","usIpa":"/tɔːrˈpiːdoʊ/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"an underwater weapon that propels itself towards a target","vi":"ngư lôi (vũ khí dưới nước tự hành)"},{"pos":"v.","en":"to deliberately cause a plan or agreement to fail","vi":"phá hoại; làm thất bại (kế hoạch, thỏa thuận)"}],"examples":[{"en":"We saw an old torpedo at the maritime museum.","vi":"Chúng tôi đã nhìn thấy một quả ngư lôi cũ tại bảo tàng hàng hải.","audioKind":"ex"},{"en":"Unexpected funding cuts could torpedo plans to expand public transport in rapidly growing urban areas.","vi":"Việc cắt giảm ngân sách bất ngờ có thể làm phá sản các kế hoạch mở rộng giao thông công cộng tại các khu đô thị đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"launch a torpedo","vi":"bắn ngư lôi"},{"en":"torpedo tube","vi":"ống phóng ngư lôi"},{"en":"torpedo a plan","vi":"phá hoại một kế hoạch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ngư lôi là torpedo; thủy lôi là mine. Dạng số nhiều là torpedoes.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_baron', 'en-c1-49', 'baron', '/ˈbærən/', 'C1', 'nam tước; ông trùm công nghiệp; đại gia', 'n.', 'baroness (n.), barony (n.), baronial (adj.)', NULL, 'Nghĩa gốc là nam tước; khi kết hợp với danh từ chỉ ngành nghề, ''baron'' dùng để chỉ ông trùm trong lĩnh vực đó.', 'The baron welcomed his guests into the castle courtyard.', NULL, 'Vị nam tước chào đón các vị khách bước vào sân lâu đài.', '{"wordId":"baron","ukIpa":"/ˈbærən/","usIpa":"/ˈbærən/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"A man holding a low-ranking title of nobility.","vi":"nam tước"},{"pos":"n.","en":"A wealthy person with great power in a particular industry.","vi":"ông trùm công nghiệp; đại gia"}],"examples":[{"en":"The baron welcomed his guests into the castle courtyard.","vi":"Vị nam tước chào đón các vị khách bước vào sân lâu đài.","audioKind":"ex"},{"en":"Media barons can influence public debate through their ownership of major newspapers and television networks.","vi":"Các ông trùm truyền thông có thể chi phối các cuộc tranh luận công khai thông qua việc nắm giữ các tờ báo và đài truyền hình lớn.","audioKind":"ex2"}],"collocations":[{"en":"a media baron","vi":"ông trùm truyền thông"},{"en":"a press baron","vi":"ông trùm báo chí"},{"en":"an oil baron","vi":"ông trùm dầu mỏ"}],"wordFamily":["baroness (n.)","barony (n.)","baronial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa gốc là nam tước; khi kết hợp với danh từ chỉ ngành nghề, ''baron'' dùng để chỉ ông trùm trong lĩnh vực đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_missionary', 'en-c1-49', 'missionary', '/ˈmɪʃəneri/', 'C1', 'nhà truyền giáo; thuộc về truyền giáo; liên quan đến hoạt động truyền giáo', 'n.', 'mission (n.)', NULL, 'Có thể làm danh từ hoặc tính từ; dạng số nhiều là missionaries.', 'The missionary discussed her faith with interested local families.', NULL, 'Nữ nhà truyền giáo đã thảo luận về đức tin của mình với các gia đình địa phương quan tâm.', '{"wordId":"missionary","ukIpa":"/ˈmɪʃənəri/","usIpa":"/ˈmɪʃəneri/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"someone sent to teach a religion, often in another country","vi":"nhà truyền giáo"},{"pos":"adj.","en":"relating to people or activities that spread a religion","vi":"thuộc về truyền giáo; liên quan đến hoạt động truyền giáo"}],"examples":[{"en":"The missionary discussed her faith with interested local families.","vi":"Nữ nhà truyền giáo đã thảo luận về đức tin của mình với các gia đình địa phương quan tâm.","audioKind":"ex"},{"en":"Historians examine how missionary schools influenced education and cultural traditions in different regions during the nineteenth century.","vi":"Các nhà sử học nghiên cứu cách thức các trường học truyền giáo đã ảnh hưởng đến giáo dục và truyền thống văn hóa ở các vùng miền khác nhau trong thế kỷ XIX.","audioKind":"ex2"}],"collocations":[{"en":"missionary work","vi":"công tác truyền giáo"},{"en":"a missionary school","vi":"trường học truyền giáo"},{"en":"missionary activity","vi":"hoạt động truyền giáo"}],"wordFamily":["mission (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể làm danh từ hoặc tính từ; dạng số nhiều là missionaries.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prophet', 'en-c1-49', 'prophet', '/ˈprɑːfɪt/', 'C1', 'tiên tri; nhà tiên tri; người dự báo tương lai', 'n.', 'prophecy (n.), prophesy (v.), prophetic (adj.)', 'Đồng nghĩa: seer', 'Từ này phát âm giống với profit (lợi nhuận); động từ tương ứng là prophesy.', 'The old painting shows a prophet addressing a crowd.', NULL, 'Bức tranh cổ vẽ cảnh một nhà tiên tri đang thuyết giảng trước đám đông.', '{"wordId":"prophet","ukIpa":"/ˈprɒfɪt/","usIpa":"/ˈprɑːfɪt/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"Someone believed to communicate messages from a god.","vi":"tiên tri; nhà tiên tri"},{"pos":"n.","en":"Someone who predicts future events or developments.","vi":"người dự báo tương lai"}],"examples":[{"en":"The old painting shows a prophet addressing a crowd.","vi":"Bức tranh cổ vẽ cảnh một nhà tiên tri đang thuyết giảng trước đám đông.","audioKind":"ex"},{"en":"Throughout history, religious communities have preserved the teachings of prophets through oral traditions and written accounts.","vi":"Xung quanh lịch sử, các cộng đồng tôn giáo đã bảo tồn những lời dạy của các nhà tiên tri thông qua truyền miệng và văn bản ghi chép.","audioKind":"ex2"}],"collocations":[{"en":"a religious prophet","vi":"nhà tiên tri tôn giáo"},{"en":"a prophet of doom","vi":"kẻ bi quan dự báo điềm gở"},{"en":"the teachings of a prophet","vi":"lời dạy của nhà tiên tri"}],"wordFamily":["prophecy (n.)","prophesy (v.)","prophetic (adj.)"],"synonyms":["seer"],"antonyms":[],"tipVi":"Từ này phát âm giống với profit (lợi nhuận); động từ tương ứng là prophesy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chronological', 'en-c1-49', 'chronological', '/ˌkrɑːnəˈlɑːdʒɪkəl/', 'C1', 'theo thứ tự thời gian', 'adj.', 'chronology (n.), chronologically (adv.)', NULL, 'Nhấn mạnh vào thứ tự trước sau của sự kiện, không phải tầm quan trọng hay trật tự logic.', 'We arranged the family photographs in chronological order.', NULL, 'Chúng tôi đã sắp xếp những bức ảnh gia đình theo thứ tự thời gian.', '{"wordId":"chronological","ukIpa":"/ˌkrɒnəˈlɒdʒɪkəl/","usIpa":"/ˌkrɑːnəˈlɑːdʒɪkəl/","cefr":"C1","topic":"history","senses":[{"pos":"adj.","en":"Arranged in the order in which events happened.","vi":"theo thứ tự thời gian"}],"examples":[{"en":"We arranged the family photographs in chronological order.","vi":"Chúng tôi đã sắp xếp những bức ảnh gia đình theo thứ tự thời gian.","audioKind":"ex"},{"en":"Presenting historical events in chronological order helps students understand how earlier developments influenced later social changes.","vi":"Việc trình bày các sự kiện lịch sử theo trình tự thời gian giúp học sinh hiểu được các sự phát triển ở giai đoạn trước đã chi phối các biến đổi xã hội sau này ra sao.","audioKind":"ex2"}],"collocations":[{"en":"chronological order","vi":"thứ tự thời gian"},{"en":"chronological account","vi":"tường thuật theo trình tự thời gian"},{"en":"chronological sequence","vi":"trình tự thời gian"}],"wordFamily":["chronology (n.)","chronologically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh vào thứ tự trước sau của sự kiện, không phải tầm quan trọng hay trật tự logic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conquest', 'en-c1-49', 'conquest', '/ˈkɑːŋkwest/', 'C1', 'sự chinh phục; sự chiếm đóng; vùng đất bị chinh phục', 'n.', 'conquer (v.), conqueror (n.)', NULL, 'Biểu thị hành vi chinh phục có thể đếm được hoặc không; khi chỉ vùng đất bị chinh phục thì đây là danh từ đếm được.', 'The castle fell after months of fighting and conquest.', NULL, 'Lâu đài đã thất thủ sau nhiều tháng giao tranh và chinh phạt.', '{"wordId":"conquest","ukIpa":"/ˈkɒŋkwest/","usIpa":"/ˈkɑːŋkwest/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"the act of taking control of a country by force","vi":"sự chinh phục; sự chiếm đóng"},{"pos":"n.","en":"a place brought under control through military force","vi":"vùng đất bị chinh phục"}],"examples":[{"en":"The castle fell after months of fighting and conquest.","vi":"Lâu đài đã thất thủ sau nhiều tháng giao tranh và chinh phạt.","audioKind":"ex"},{"en":"Military conquest often reshaped trade networks and introduced new languages to regions under foreign rule.","vi":"Các cuộc chinh phạt quân sự thường làm định hình lại các mạng lưới thương mại và mang đến ngôn ngữ mới cho những vùng lãnh thổ chịu sự cai trị của ngoại bang.","audioKind":"ex2"}],"collocations":[{"en":"military conquest","vi":"chinh phạt quân sự"},{"en":"territorial conquest","vi":"chinh phục lãnh thổ"},{"en":"wars of conquest","vi":"chiến tranh chinh phục"}],"wordFamily":["conquer (v.)","conqueror (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Biểu thị hành vi chinh phục có thể đếm được hoặc không; khi chỉ vùng đất bị chinh phục thì đây là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gunpowder', 'en-c1-49', 'gunpowder', '/ˈɡʌnˌpaʊdər/', 'C1', 'huyết dược; thuốc súng', 'n.', NULL, 'Đồng nghĩa: black powder', 'Là danh từ không đếm được; một thùng thuốc súng dùng a barrel of gunpowder.', 'The museum guide showed us an old gunpowder barrel.', NULL, 'Hướng dẫn viên bảo tàng cho chúng tôi xem một thùng thuốc súng cũ.', '{"wordId":"gunpowder","ukIpa":"/ˈɡʌnˌpaʊdə/","usIpa":"/ˈɡʌnˌpaʊdər/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"An explosive powder historically used in guns and still in fireworks.","vi":"huyết dược; thuốc súng"}],"examples":[{"en":"The museum guide showed us an old gunpowder barrel.","vi":"Hướng dẫn viên bảo tàng cho chúng tôi xem một thùng thuốc súng cũ.","audioKind":"ex"},{"en":"The introduction of gunpowder changed military technology and influenced the design of defensive structures in many regions.","vi":"Sự xuất hiện của thuốc súng đã thay đổi công nghệ quân sự và ảnh hưởng đến thiết kế của các công trình phòng thủ ở nhiều vùng.","audioKind":"ex2"}],"collocations":[{"en":"the invention of gunpowder","vi":"sự phát minh ra thuốc súng"},{"en":"a barrel of gunpowder","vi":"một thùng thuốc súng"},{"en":"gunpowder storage","vi":"kho chứa thuốc súng"}],"wordFamily":[],"synonyms":["black powder"],"antonyms":[],"tipVi":"Là danh từ không đếm được; một thùng thuốc súng dùng a barrel of gunpowder.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gaol', 'en-c1-49', 'gaol', '/dʒeɪl/', 'C1', 'nhà tù; tống giam; bỏ tù', 'n.', 'gaoler (n.)', 'Đồng nghĩa: jail, prison', 'gaol là cách viết tiếng Anh-Anh cổ của jail, phát âm giống nhau.', 'We visited the old gaol during our walking tour.', NULL, 'Chúng tôi đã tham quan nhà tù cũ trong chuyến đi bộ tham quan.', '{"wordId":"gaol","ukIpa":"/dʒeɪl/","usIpa":"/dʒeɪl/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"An older British spelling of jail, a place holding prisoners.","vi":"nhà tù"},{"pos":"v.","en":"To put someone in prison; an older spelling of jail.","vi":"tống giam; bỏ tù"}],"examples":[{"en":"We visited the old gaol during our walking tour.","vi":"Chúng tôi đã tham quan nhà tù cũ trong chuyến đi bộ tham quan.","audioKind":"ex"},{"en":"The former gaol now serves as a museum exploring changes in punishment and prison conditions.","vi":"Nhà tù cũ nay đã trở thành bảo tàng trưng bày sự biến đổi về hình phạt và điều kiện giam giữ.","audioKind":"ex2"}],"collocations":[{"en":"old gaol","vi":"nhà tù cũ"},{"en":"gaol sentence","vi":"bản án tù"},{"en":"gaol cell","vi":"phòng giam"}],"wordFamily":["gaoler (n.)"],"synonyms":["jail","prison"],"antonyms":[],"tipVi":"gaol là cách viết tiếng Anh-Anh cổ của jail, phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_opium', 'en-c1-49', 'opium', '/ˈoʊpiəm/', 'C1', 'thuốc phiện', 'n.', NULL, NULL, 'Đây là danh từ không đếm được, dùng chỉ riêng thuốc phiện, không dùng để chỉ chung tất cả các loại thuốc giảm đau hay chất gây tê.', 'The museum guide explained how opium affected trade.', NULL, 'Hướng dẫn viên bảo tàng đã giải thích thuốc phiện đã ảnh hưởng đến thương mại như thế nào.', '{"wordId":"opium","ukIpa":"/ˈəʊpiəm/","usIpa":"/ˈoʊpiəm/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"An addictive substance from poppies, used to produce certain painkillers","vi":"thuốc phiện"}],"examples":[{"en":"The museum guide explained how opium affected trade.","vi":"Hướng dẫn viên bảo tàng đã giải thích thuốc phiện đã ảnh hưởng đến thương mại như thế nào.","audioKind":"ex"},{"en":"Historical research shows that the opium trade had lasting economic and social consequences for several countries.","vi":"Nghiên cứu lịch sử cho thấy nạn buôn bán thuốc phiện đã để lại hậu quả kinh tế và xã hội lâu dài đối với một số quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"opium poppy","vi":"cây thuốc phiện"},{"en":"opium trade","vi":"buôn bán thuốc phiện"},{"en":"opium addiction","vi":"nghiện thuốc phiện"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đây là danh từ không đếm được, dùng chỉ riêng thuốc phiện, không dùng để chỉ chung tất cả các loại thuốc giảm đau hay chất gây tê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feudal', 'en-c1-49', 'feudal', '/ˈfjuːdl/', 'C1', 'thuộc về phong kiến', 'adj.', 'feudalism (n.)', NULL, 'Chủ yếu mô tả hệ thống lịch sử dùng đất đai để đổi lấy sự trung thành và lao dịch.', 'The guide explained how feudal lords controlled this valley.', NULL, 'Hướng dẫn viên giải thích cách các lãnh chúa phong kiến kiểm soát thung lũng này.', '{"wordId":"feudal","ukIpa":"/ˈfjuːdl/","usIpa":"/ˈfjuːdl/","cefr":"C1","topic":"history","senses":[{"pos":"adj.","en":"Relating to a system exchanging land for service and loyalty.","vi":"thuộc về phong kiến"}],"examples":[{"en":"The guide explained how feudal lords controlled this valley.","vi":"Hướng dẫn viên giải thích cách các lãnh chúa phong kiến kiểm soát thung lũng này.","audioKind":"ex"},{"en":"Under the feudal system, access to land largely determined a person''s social position and economic security.","vi":"Dưới chế độ phong kiến, quyền sở hữu đất đai phần lớn quyết định địa vị xã hội và sự đảm bảo kinh tế của một người.","audioKind":"ex2"}],"collocations":[{"en":"the feudal system","vi":"hệ thống phong kiến"},{"en":"a feudal lord","vi":"lãnh chúa phong kiến"},{"en":"feudal society","vi":"xã hội phong kiến"}],"wordFamily":["feudalism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu mô tả hệ thống lịch sử dùng đất đai để đổi lấy sự trung thành và lao dịch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peasant', 'en-c1-49', 'peasant', '/ˈpezənt/', 'C1', 'nông dân nghèo; tá điền', 'n.', 'peasantry (n.)', NULL, 'Thường dùng trong bối cảnh lịch sử hoặc nông nghiệp truyền thống; gọi người khác có thể mang sắc thái miệt thị.', 'The painting shows a peasant carrying vegetables home.', NULL, 'Bức tranh vẽ cảnh một người nông dân đang gánh rau củ đi về nhà.', '{"wordId":"peasant","ukIpa":"/ˈpezənt/","usIpa":"/ˈpezənt/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"a poor farmer working a small plot of land","vi":"nông dân nghèo; tá điền"}],"examples":[{"en":"The painting shows a peasant carrying vegetables home.","vi":"Bức tranh vẽ cảnh một người nông dân đang gánh rau củ đi về nhà.","audioKind":"ex"},{"en":"Historically, peasant families often depended on a single harvest, making them particularly vulnerable to drought.","vi":"Trong lịch sử, các gia đình nông dân thường chỉ phụ thuộc vào một mùa vụ duy nhất, điều này khiến họ trở nên cực kỳ dễ bị tổn thương trước hạn hán.","audioKind":"ex2"}],"collocations":[{"en":"peasant farmer","vi":"nông dân tiểu điền"},{"en":"peasant family","vi":"gia đình nông dân"},{"en":"peasant uprising","vi":"cuộc nổi dậy của nông dân"}],"wordFamily":["peasantry (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng trong bối cảnh lịch sử hoặc nông nghiệp truyền thống; gọi người khác có thể mang sắc thái miệt thị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_excavate', 'en-c1-49', 'excavate', '/ˈekskəveɪt/', 'C1', 'đào, khoét, khai đào; khai quật', 'v.', 'excavation (n.), excavator (n.)', 'Đồng nghĩa: dig, unearth', 'Excavate có thể dùng trong đào đất công trình hoặc khai quật khảo cổ.', 'Workers excavated a deep hole for our new pool.', NULL, 'Công nhân đã đào một cái hố sâu cho hồ bơi mới của chúng tôi.', '{"wordId":"excavate","ukIpa":"/ˈekskəveɪt/","usIpa":"/ˈekskəveɪt/","cefr":"C1","topic":"history","senses":[{"pos":"v.","en":"to dig into ground and remove earth","vi":"đào, khoét, khai đào"},{"pos":"v.","en":"to uncover ancient objects or buildings by carefully removing earth","vi":"khai quật"}],"examples":[{"en":"Workers excavated a deep hole for our new pool.","vi":"Công nhân đã đào một cái hố sâu cho hồ bơi mới của chúng tôi.","audioKind":"ex"},{"en":"Archaeologists excavate ancient settlements to discover how earlier communities adapted to environmental changes and developed farming techniques.","vi":"Các nhà khảo cổ học khai quật các khu định cư cổ đại để tìm hiểu cách các cộng đồng thời xưa thích ứng với sự biến đổi môi trường và phát triển kỹ thuật canh tác.","audioKind":"ex2"}],"collocations":[{"en":"excavate a site","vi":"khai quật một di tích"},{"en":"excavate a trench","vi":"đào một con hào"},{"en":"excavate ancient remains","vi":"khai quật các di vật cổ"}],"wordFamily":["excavation (n.)","excavator (n.)"],"synonyms":["dig","unearth"],"antonyms":[],"tipVi":"Excavate có thể dùng trong đào đất công trình hoặc khai quật khảo cổ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warfare', 'en-c1-49', 'warfare', '/ˈwɔːrfer/', 'C1', 'chiến tranh, chiến đấu, phương thức tác chiến', 'n.', 'war (n.), warrior (n.)', NULL, 'Không đếm được, nhấn mạnh hoạt động hoặc phương thức chiến đấu; war có thể chỉ một cuộc chiến tranh cụ thể.', 'The museum shows how warfare changed over centuries.', NULL, 'Viện bảo tàng trưng bày cách thức chiến tranh thay đổi qua các thế kỷ.', '{"wordId":"warfare","ukIpa":"/ˈwɔːfeə/","usIpa":"/ˈwɔːrfer/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"The activity of fighting wars, including methods and weapons used.","vi":"chiến tranh, chiến đấu, phương thức tác chiến"}],"examples":[{"en":"The museum shows how warfare changed over centuries.","vi":"Viện bảo tàng trưng bày cách thức chiến tranh thay đổi qua các thế kỷ.","audioKind":"ex"},{"en":"Modern warfare can damage essential infrastructure, leaving communities without reliable access to water and electricity.","vi":"Chiến tranh hiện đại có thể tàn phá các cơ sở hạ tầng thiết yếu, khiến các cộng đồng mất đi nguồn cung cấp nước và điện ổn định.","audioKind":"ex2"}],"collocations":[{"en":"modern warfare","vi":"chiến tranh hiện đại"},{"en":"chemical warfare","vi":"chiến tranh hóa học"},{"en":"guerrilla warfare","vi":"chiến tranh du kích"}],"wordFamily":["war (n.)","warrior (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Không đếm được, nhấn mạnh hoạt động hoặc phương thức chiến đấu; war có thể chỉ một cuộc chiến tranh cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disuse', 'en-c1-49', 'disuse', '/dɪsˈjuːs/', 'C1', 'sự bỏ hoang; tình trạng không còn dùng đến', 'n.', 'disused (adj.), use (v.)', 'Đồng nghĩa: non-use · Trái nghĩa: use', 'Thường đóng vai trò là danh từ không đếm được, phần đuôi phát âm là /s/ chứ không phải /z/.', 'The old garden tools had become rusty through disuse.', NULL, 'Những dụng cụ làm vườn cũ đã bị gỉ sét do lâu ngày không được sử dụng.', '{"wordId":"disuse","ukIpa":"/dɪsˈjuːs/","usIpa":"/dɪsˈjuːs/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"the state of no longer being used","vi":"sự bỏ hoang; tình trạng không còn dùng đến"}],"examples":[{"en":"The old garden tools had become rusty through disuse.","vi":"Những dụng cụ làm vườn cũ đã bị gỉ sét do lâu ngày không được sử dụng.","audioKind":"ex"},{"en":"Historic buildings often fall into disuse when maintenance costs exceed the resources available to local communities.","vi":"Các công trình lịch sử thường rơi vào tình trạng bỏ hoang khi chi phí bảo trì vượt quá nguồn lực của cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"fall into disuse","vi":"rơi vào quên lãng; không còn được dùng đến"},{"en":"through disuse","vi":"do không sử dụng"},{"en":"years of disuse","vi":"nhiều năm bỏ hoang"}],"wordFamily":["disused (adj.)","use (v.)"],"synonyms":["non-use"],"antonyms":["use"],"tipVi":"Thường đóng vai trò là danh từ không đếm được, phần đuôi phát âm là /s/ chứ không phải /z/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_martial', 'en-c1-49', 'martial', '/ˈmɑːrʃəl/', 'C1', 'thuộc quân đội; mang tính quân sự; chiến trận', 'adj.', NULL, 'Đồng nghĩa: military', 'Martial mang nghĩa quân sự, khác với từ marital có nghĩa là hôn nhân, tránh nhầm lẫn.', 'The band played martial music as soldiers marched past.', NULL, 'Ban nhạc đã tấu lên những bản quân nhạc hùng tráng khi đoàn quân tiến bước qua.', '{"wordId":"martial","ukIpa":"/ˈmɑːʃəl/","usIpa":"/ˈmɑːrʃəl/","cefr":"C1","topic":"history","senses":[{"pos":"adj.","en":"Related to war, soldiers, or military life.","vi":"thuộc quân đội; mang tính quân sự; chiến trận"}],"examples":[{"en":"The band played martial music as soldiers marched past.","vi":"Ban nhạc đã tấu lên những bản quân nhạc hùng tráng khi đoàn quân tiến bước qua.","audioKind":"ex"},{"en":"Although martial arts originated as fighting techniques, many people now practise them for fitness and self-discipline.","vi":"Mặc dù võ thuật ban đầu vốn là các kỹ năng chiến đấu, ngày nay nhiều người luyện tập chúng để rèn luyện sức khỏe và tính kỷ luật bản thân.","audioKind":"ex2"}],"collocations":[{"en":"martial arts","vi":"võ thuật"},{"en":"martial law","vi":"lệnh thiết quân luật"},{"en":"martial music","vi":"quân nhạc"}],"wordFamily":[],"synonyms":["military"],"antonyms":[],"tipVi":"Martial mang nghĩa quân sự, khác với từ marital có nghĩa là hôn nhân, tránh nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_colonial', 'en-c1-49', 'colonial', '/kəˈloʊniəl/', 'C1', 'thuộc địa; thuộc thời kỳ thực dân', 'adj.', 'colony (n.), colonialism (n.), colonize (v.), colonization (n.)', NULL, 'colony là thuộc địa; colonial là tính từ tương ứng.', 'Our guide showed us several buildings from the colonial period.', NULL, 'Hướng dẫn viên đã dẫn chúng tôi tham quan một số tòa nhà từ thời kỳ thuộc địa.', '{"wordId":"colonial","ukIpa":"/kəˈləʊniəl/","usIpa":"/kəˈloʊniəl/","cefr":"C1","topic":"history","senses":[{"pos":"adj.","en":"relating to a territory controlled by a foreign country","vi":"thuộc địa; thuộc thời kỳ thực dân"}],"examples":[{"en":"Our guide showed us several buildings from the colonial period.","vi":"Hướng dẫn viên đã dẫn chúng tôi tham quan một số tòa nhà từ thời kỳ thuộc địa.","audioKind":"ex"},{"en":"Colonial rule often reshaped local economies by directing agricultural production towards the needs of distant markets.","vi":"Sự thống trị của thực dân thường định hình lại nền kinh tế địa phương bằng cách hướng sản xuất nông nghiệp phục vụ cho nhu cầu của các thị trường xa xôi.","audioKind":"ex2"}],"collocations":[{"en":"colonial rule","vi":"chính sách thuộc địa"},{"en":"colonial period","vi":"thời kỳ thực dân"},{"en":"colonial powers","vi":"các cường quốc thực dân"},{"en":"colonial legacy","vi":"di sản thời kỳ thuộc địa"}],"wordFamily":["colony (n.)","colonialism (n.)","colonize (v.)","colonization (n.)"],"synonyms":[],"antonyms":[],"tipVi":"colony là thuộc địa; colonial là tính từ tương ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chronology', 'en-c1-49', 'chronology', '/krəˈnɑːlədʒi/', 'C1', 'niên đại; thứ tự thời gian; bảng niên biểu; niên đại học', 'n.', 'chronological (adj.), chronologically (adv.)', NULL, 'chronology là danh từ; để chỉ việc sắp xếp theo thứ tự thời gian, hãy dùng phó từ chronologically.', 'These family photos helped us establish the chronology.', NULL, 'Những bức ảnh gia đình này đã giúp chúng tôi xác định được thứ tự thời gian.', '{"wordId":"chronology","ukIpa":"/krəˈnɒlədʒi/","usIpa":"/krəˈnɑːlədʒi/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"The order of events in time, or a record showing it.","vi":"niên đại; thứ tự thời gian; bảng niên biểu"},{"pos":"n.","en":"The study of when past events happened.","vi":"niên đại học"}],"examples":[{"en":"These family photos helped us establish the chronology.","vi":"Những bức ảnh gia đình này đã giúp chúng tôi xác định được thứ tự thời gian.","audioKind":"ex"},{"en":"Establishing an accurate chronology allows historians to examine how environmental changes influenced the development of early settlements.","vi":"Việc thiết lập một chuỗi thời gian chính xác cho phép các nhà sử học nghiên cứu cách các biến đổi môi trường tác động đến sự phát triển của các khu dân cư thời kỳ đầu.","audioKind":"ex2"}],"collocations":[{"en":"establish a chronology","vi":"xác định thứ tự thời gian"},{"en":"a chronology of events","vi":"niên biểu sự kiện"},{"en":"an accurate chronology","vi":"chuỗi thời gian chính xác"}],"wordFamily":["chronological (adj.)","chronologically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"chronology là danh từ; để chỉ việc sắp xếp theo thứ tự thời gian, hãy dùng phó từ chronologically.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_telegraph', 'en-c1-49', 'telegraph', '/ˈtelɪɡræf/', 'C1', 'hệ thống điện báo; máy điện báo; gửi điện báo; vô tình bộc lộ; để lộ (ý định, cảm xúc)', 'n.', 'telegraphic (adj.), telegraphy (n.)', NULL, 'telegraph chỉ hệ thống hoặc thiết bị thông tin; telegram chỉ bản tin điện báo.', 'The museum guide demonstrated how the old telegraph worked.', NULL, 'Hướng dẫn viên bảo tàng đã minh họa cách hoạt động của chiếc máy điện báo cổ.', '{"wordId":"telegraph","ukIpa":"/ˈtelɪɡrɑːf/","usIpa":"/ˈtelɪɡræf/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"A system or device sending messages electrically along wires.","vi":"hệ thống điện báo; máy điện báo"},{"pos":"v.","en":"To send a message using a telegraph.","vi":"gửi điện báo"},{"pos":"v.","en":"To reveal intentions or feelings, often without meaning to.","vi":"vô tình bộc lộ; để lộ (ý định, cảm xúc)"}],"examples":[{"en":"The museum guide demonstrated how the old telegraph worked.","vi":"Hướng dẫn viên bảo tàng đã minh họa cách hoạt động của chiếc máy điện báo cổ.","audioKind":"ex"},{"en":"The telegraph transformed international communication by allowing information to travel much faster than physical mail.","vi":"Điện báo đã cách mạng hóa ngành thông tin liên lạc quốc tế bằng cách cho phép thông tin di chuyển nhanh hơn rất nhiều so với thư tín thông thường.","audioKind":"ex2"}],"collocations":[{"en":"telegraph operator","vi":"nhân viên điện báo"},{"en":"telegraph wire","vi":"dây điện báo"},{"en":"telegraph your intentions","vi":"để lộ ý định"}],"wordFamily":["telegraphic (adj.)","telegraphy (n.)"],"synonyms":[],"antonyms":[],"tipVi":"telegraph chỉ hệ thống hoặc thiết bị thông tin; telegram chỉ bản tin điện báo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forerunner', 'en-c1-49', 'forerunner', '/ˈfɔːrʌnər/', 'C1', 'tiền thân; người đi trước; tiền triệu; điềm báo', 'n.', NULL, 'Đồng nghĩa: precursor, predecessor · Trái nghĩa: successor', 'Thường dùng a forerunner of; không dùng để chỉ người dẫn đầu trong cuộc đua.', 'This bulky machine was a forerunner of today''s laptops.', NULL, 'Chiếc máy cồng kềnh này là tiền thân của dòng máy tính xách tay ngày nay.', '{"wordId":"forerunner","ukIpa":"/ˈfɔːrʌnə/","usIpa":"/ˈfɔːrʌnər/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"Someone or something that comes before and influences a later development.","vi":"tiền thân; người đi trước"},{"pos":"n.","en":"Something that signals the arrival of a later event.","vi":"tiền triệu; điềm báo"}],"examples":[{"en":"This bulky machine was a forerunner of today''s laptops.","vi":"Chiếc máy cồng kềnh này là tiền thân của dòng máy tính xách tay ngày nay.","audioKind":"ex"},{"en":"Early public libraries were forerunners of modern community centres, offering shared spaces for learning and discussion.","vi":"Các thư viện công cộng thời kỳ đầu chính là tiền thân của các trung tâm cộng đồng hiện đại, cung cấp không gian chung cho việc học tập và thảo luận.","audioKind":"ex2"}],"collocations":[{"en":"a forerunner of","vi":"tiền thân của"},{"en":"a forerunner to","vi":"người đi đầu trong"},{"en":"an early forerunner","vi":"tiền bối thời kỳ đầu"}],"wordFamily":[],"synonyms":["precursor","predecessor"],"antonyms":["successor"],"tipVi":"Thường dùng a forerunner of; không dùng để chỉ người dẫn đầu trong cuộc đua.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_millennium', 'en-c1-49', 'millennium', '/mɪˈleniəm/', 'C1', 'thiên niên kỷ; thời điểm chuyển giao thiên niên kỷ; thiên niên kỷ mới', 'n.', 'millennial (adj.)', NULL, 'Lưu ý viết đôi chữ l và n; dạng số nhiều thường dùng là millennia.', 'This ancient tree has survived for over a millennium.', NULL, 'Cây cổ thụ này đã tồn tại qua hơn một thiên niên kỷ.', '{"wordId":"millennium","ukIpa":"/mɪˈleniəm/","usIpa":"/mɪˈleniəm/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"A period of one thousand years.","vi":"thiên niên kỷ"},{"pos":"n.","en":"The point when one thousand-year period ends and another begins.","vi":"thời điểm chuyển giao thiên niên kỷ; thiên niên kỷ mới"}],"examples":[{"en":"This ancient tree has survived for over a millennium.","vi":"Cây cổ thụ này đã tồn tại qua hơn một thiên niên kỷ.","audioKind":"ex"},{"en":"Over the past millennium, advances in agriculture have transformed how societies produce food and support growing populations.","vi":"Trong thiên niên kỷ qua, những tiến bộ trong nông nghiệp đã thay đổi cách các xã hội sản xuất thực phẩm và nuôi sống dân số ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"the past millennium","vi":"thiên niên kỷ qua"},{"en":"the turn of the millennium","vi":"thời điểm chuyển giao thiên niên kỷ"},{"en":"millennium celebrations","vi":"lễ kỷ niệm thiên niên kỷ"}],"wordFamily":["millennial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Lưu ý viết đôi chữ l và n; dạng số nhiều thường dùng là millennia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uprising', 'en-c1-49', 'uprising', '/ˈʌpraɪzɪŋ/', 'C1', 'cuộc khởi nghĩa; cuộc nổi dậy', 'n.', 'uprise (v.)', 'Đồng nghĩa: revolt, rebellion', 'Thường dùng để chỉ hành động nổi dậy chống lại nhà cầm quyền, không dùng cho nghĩa thức dậy hay vươn lên thông thường.', 'The museum displays objects from a local uprising.', NULL, 'Bảo tàng trưng bày nhiều hiện vật từ một cuộc khởi nghĩa tại địa phương.', '{"wordId":"uprising","ukIpa":"/ˈʌpraɪzɪŋ/","usIpa":"/ˈʌpraɪzɪŋ/","cefr":"C1","topic":"history","senses":[{"pos":"n.","en":"An organised attempt by a population to resist those in power.","vi":"cuộc khởi nghĩa; cuộc nổi dậy"}],"examples":[{"en":"The museum displays objects from a local uprising.","vi":"Bảo tàng trưng bày nhiều hiện vật từ một cuộc khởi nghĩa tại địa phương.","audioKind":"ex"},{"en":"Historians argue that food shortages and political exclusion contributed to the uprising against the ruling authorities.","vi":"Các sử gia lập luận rằng tình trạng thiếu lương thực và sự gạt bỏ chính trị đã góp phần châm ngòi cho cuộc nổi dậy chống lại giới cầm quyền.","audioKind":"ex2"}],"collocations":[{"en":"a popular uprising","vi":"cuộc nổi dậy của quần chúng"},{"en":"an armed uprising","vi":"cuộc khởi nghĩa vũ trang"},{"en":"suppress an uprising","vi":"trấn áp một cuộc nổi dậy"}],"wordFamily":["uprise (v.)"],"synonyms":["revolt","rebellion"],"antonyms":[],"tipVi":"Thường dùng để chỉ hành động nổi dậy chống lại nhà cầm quyền, không dùng cho nghĩa thức dậy hay vươn lên thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_49_1', 'en-c1-49', 'Cách dùng “opium” (n.) — thuốc phiện', 'opium poppy  ·  opium trade  ·  opium addiction', 'Đây là danh từ không đếm được, dùng chỉ riêng thuốc phiện, không dùng để chỉ chung tất cả các loại thuốc giảm đau hay chất gây tê.', NULL, '[{"hanzi":"The museum guide explained how opium affected trade.","pinyin":"","meaning":"Hướng dẫn viên bảo tàng đã giải thích thuốc phiện đã ảnh hưởng đến thương mại như thế nào."},{"hanzi":"Historical research shows that the opium trade had lasting economic and social consequences for several countries.","pinyin":"","meaning":"Nghiên cứu lịch sử cho thấy nạn buôn bán thuốc phiện đã để lại hậu quả kinh tế và xã hội lâu dài đối với một số quốc gia."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_49_2', 'en-c1-49', 'Cách dùng “uprising” (n.) — cuộc khởi nghĩa; cuộc nổi dậy', 'a popular uprising  ·  an armed uprising  ·  suppress an uprising', 'Thường dùng để chỉ hành động nổi dậy chống lại nhà cầm quyền, không dùng cho nghĩa thức dậy hay vươn lên thông thường.', 'Họ từ (Word Family): uprise (v.) | Đồng nghĩa: revolt, rebellion', '[{"hanzi":"The museum displays objects from a local uprising.","pinyin":"","meaning":"Bảo tàng trưng bày nhiều hiện vật từ một cuộc khởi nghĩa tại địa phương."},{"hanzi":"Historians argue that food shortages and political exclusion contributed to the uprising against the ruling authorities.","pinyin":"","meaning":"Các sử gia lập luận rằng tình trạng thiếu lương thực và sự gạt bỏ chính trị đã góp phần châm ngòi cho cuộc nổi dậy chống lại giới cầm quyền."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_49_3', 'en-c1-49', 'Cách dùng “conquest” (n.) — sự chinh phục; sự chiếm đóng', 'military conquest  ·  territorial conquest  ·  wars of conquest', 'Biểu thị hành vi chinh phục có thể đếm được hoặc không; khi chỉ vùng đất bị chinh phục thì đây là danh từ đếm được.', 'Họ từ (Word Family): conquer (v.), conqueror (n.)', '[{"hanzi":"The castle fell after months of fighting and conquest.","pinyin":"","meaning":"Lâu đài đã thất thủ sau nhiều tháng giao tranh và chinh phạt."},{"hanzi":"Military conquest often reshaped trade networks and introduced new languages to regions under foreign rule.","pinyin":"","meaning":"Các cuộc chinh phạt quân sự thường làm định hình lại các mạng lưới thương mại và mang đến ngôn ngữ mới cho những vùng lãnh thổ chịu sự cai trị của ngoại bang."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_49_4', 'en-c1-49', 'Cách dùng “peasant” (n.) — nông dân nghèo; tá điền', 'peasant farmer  ·  peasant family  ·  peasant uprising', 'Thường dùng trong bối cảnh lịch sử hoặc nông nghiệp truyền thống; gọi người khác có thể mang sắc thái miệt thị.', 'Họ từ (Word Family): peasantry (n.)', '[{"hanzi":"The painting shows a peasant carrying vegetables home.","pinyin":"","meaning":"Bức tranh vẽ cảnh một người nông dân đang gánh rau củ đi về nhà."},{"hanzi":"Historically, peasant families often depended on a single harvest, making them particularly vulnerable to drought.","pinyin":"","meaning":"Trong lịch sử, các gia đình nông dân thường chỉ phụ thuộc vào một mùa vụ duy nhất, điều này khiến họ trở nên cực kỳ dễ bị tổn thương trước hạn hán."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_49_1', 'en-c1-49', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_1_1', 'ten_c1_49_1', 'thereafter', 'The shop opened in spring and closed shortly thereafter.', 'The shop opened in spring and closed shortly thereafter.', '/ˌðerˈæftər/', 'Cửa hàng mở cửa vào mùa xuân và đóng cửa ngay sau đó.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_1_2', 'ten_c1_49_1', 'commemorate', 'We planted a tree to commemorate our grandfather''s life.', 'We planted a tree to commemorate our grandfather''s life.', '/kəˈmeməreɪt/', 'Chúng tôi đã trồng một cái cây để kỷ niệm cuộc đời của ông nội.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_1_3', 'ten_c1_49_1', 'torpedo', 'We saw an old torpedo at the maritime museum.', 'We saw an old torpedo at the maritime museum.', '/tɔːrˈpiːdoʊ/', 'Chúng tôi đã nhìn thấy một quả ngư lôi cũ tại bảo tàng hàng hải.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_1_4', 'ten_c1_49_1', 'baron', 'The baron welcomed his guests into the castle courtyard.', 'The baron welcomed his guests into the castle courtyard.', '/ˈbærən/', 'Vị nam tước chào đón các vị khách bước vào sân lâu đài.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_1_5', 'ten_c1_49_1', 'missionary', 'The missionary discussed her faith with interested local families.', 'The missionary discussed her faith with interested local families.', '/ˈmɪʃəneri/', 'Nữ nhà truyền giáo đã thảo luận về đức tin của mình với các gia đình địa phương quan tâm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_1_6', 'ten_c1_49_1', 'prophet', 'The old painting shows a prophet addressing a crowd.', 'The old painting shows a prophet addressing a crowd.', '/ˈprɑːfɪt/', 'Bức tranh cổ vẽ cảnh một nhà tiên tri đang thuyết giảng trước đám đông.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_1_7', 'ten_c1_49_1', 'chronological', 'We arranged the family photographs in chronological order.', 'We arranged the family photographs in chronological order.', '/ˌkrɑːnəˈlɑːdʒɪkəl/', 'Chúng tôi đã sắp xếp những bức ảnh gia đình theo thứ tự thời gian.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_1_8', 'ten_c1_49_1', 'conquest', 'The castle fell after months of fighting and conquest.', 'The castle fell after months of fighting and conquest.', '/ˈkɑːŋkwest/', 'Lâu đài đã thất thủ sau nhiều tháng giao tranh và chinh phạt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_49_1_1', 'en-c1-49', 'ten_c1_49_1', 'listening', 'listening', 'The shop opened in spring and closed shortly thereafter.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cửa hàng mở cửa vào mùa xuân và đóng cửa ngay sau đó.","Những bức ảnh gia đình này đã giúp chúng tôi xác định được thứ tự thời gian.","Hướng dẫn viên bảo tàng đã minh họa cách hoạt động của chiếc máy điện báo cổ.","Hướng dẫn viên bảo tàng cho chúng tôi xem một thùng thuốc súng cũ."]'::jsonb, 0, 'The shop opened in spring and closed shortly thereafter. → Cửa hàng mở cửa vào mùa xuân và đóng cửa ngay sau đó.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_49_1_2', 'en-c1-49', 'ten_c1_49_1', 'listening', 'listening', 'We planted a tree to commemorate our grandfather''s life.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bức tranh vẽ cảnh một người nông dân đang gánh rau củ đi về nhà.","Chiếc máy cồng kềnh này là tiền thân của dòng máy tính xách tay ngày nay.","Chúng tôi đã trồng một cái cây để kỷ niệm cuộc đời của ông nội.","Những dụng cụ làm vườn cũ đã bị gỉ sét do lâu ngày không được sử dụng."]'::jsonb, 2, 'We planted a tree to commemorate our grandfather''s life. → Chúng tôi đã trồng một cái cây để kỷ niệm cuộc đời của ông nội.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_49_1_3', 'en-c1-49', 'ten_c1_49_1', 'listening', 'listening', 'We saw an old torpedo at the maritime museum.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lâu đài đã thất thủ sau nhiều tháng giao tranh và chinh phạt.","Những dụng cụ làm vườn cũ đã bị gỉ sét do lâu ngày không được sử dụng.","Chúng tôi đã nhìn thấy một quả ngư lôi cũ tại bảo tàng hàng hải.","Công nhân đã đào một cái hố sâu cho hồ bơi mới của chúng tôi."]'::jsonb, 2, 'We saw an old torpedo at the maritime museum. → Chúng tôi đã nhìn thấy một quả ngư lôi cũ tại bảo tàng hàng hải.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_49_2', 'en-c1-49', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_2_1', 'ten_c1_49_2', 'thereafter', 'The city introduced stricter vehicle standards, and air quality improved steadily in the years thereafter.', 'The city introduced stricter vehicle standards, and air quality improved steadily in the years thereafter.', '/ˌðerˈæftər/', 'Thành phố đã áp dụng các tiêu chuẩn xe cộ nghiêm ngặt hơn, và chất lượng không khí đã cải thiện đều đặn trong những năm sau đó.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_2_2', 'ten_c1_49_2', 'commemorate', 'Public ceremonies commemorate historical events and help younger generations understand the experiences that shaped their communities.', 'Public ceremonies commemorate historical events and help younger generations understand the experiences that shaped their communities.', '/kəˈmeməreɪt/', 'Các buổi lễ tưởng niệm công khai nhằm tôn vinh các sự kiện lịch sử và giúp thế hệ trẻ thấu hiểu những trải nghiệm đã định hình nên cộng đồng của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_2_3', 'ten_c1_49_2', 'torpedo', 'Unexpected funding cuts could torpedo plans to expand public transport in rapidly growing urban areas.', 'Unexpected funding cuts could torpedo plans to expand public transport in rapidly growing urban areas.', '/tɔːrˈpiːdoʊ/', 'Việc cắt giảm ngân sách bất ngờ có thể làm phá sản các kế hoạch mở rộng giao thông công cộng tại các khu đô thị đang phát triển nhanh chóng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_2_4', 'ten_c1_49_2', 'baron', 'Media barons can influence public debate through their ownership of major newspapers and television networks.', 'Media barons can influence public debate through their ownership of major newspapers and television networks.', '/ˈbærən/', 'Các ông trùm truyền thông có thể chi phối các cuộc tranh luận công khai thông qua việc nắm giữ các tờ báo và đài truyền hình lớn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_2_5', 'ten_c1_49_2', 'missionary', 'Historians examine how missionary schools influenced education and cultural traditions in different regions during the nineteenth century.', 'Historians examine how missionary schools influenced education and cultural traditions in different regions during the nineteenth century.', '/ˈmɪʃəneri/', 'Các nhà sử học nghiên cứu cách thức các trường học truyền giáo đã ảnh hưởng đến giáo dục và truyền thống văn hóa ở các vùng miền khác nhau trong thế kỷ XIX.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_49_2_6', 'ten_c1_49_2', 'prophet', 'Throughout history, religious communities have preserved the teachings of prophets through oral traditions and written accounts.', 'Throughout history, religious communities have preserved the teachings of prophets through oral traditions and written accounts.', '/ˈprɑːfɪt/', 'Xung quanh lịch sử, các cộng đồng tôn giáo đã bảo tồn những lời dạy của các nhà tiên tri thông qua truyền miệng và văn bản ghi chép.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_49_2_1', 'en-c1-49', 'ten_c1_49_2', 'listening', 'listening', 'The city introduced stricter vehicle standards, and air quality improved steadily in the years thereafter.', NULL, 'Trong câu vừa nghe, từ “thereafter” mang nghĩa nào sau đây?', '["sự ngưng chiến; thỏa thuận tạm đình chiến","vặt vãnh; nhỏ nhặt","sự phục hồi; sự tái thiết; sự đổi mới đô thị","sau đó; từ đó trở đi"]'::jsonb, 3, '“thereafter” (/ˌðerˈæftər/): sau đó; từ đó trở đi. Câu đầy đủ: The city introduced stricter vehicle standards, and air quality improved steadily in the years thereafter.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_49_2_2', 'en-c1-49', 'ten_c1_49_2', 'listening', 'listening', 'Public ceremonies commemorate historical events and help younger generations understand the experiences that shaped their communities.', NULL, 'Trong câu vừa nghe, từ “commemorate” mang nghĩa nào sau đây?', '["gian khổ; gian nan; đòi hỏi nhiều nỗ lực","tưởng niệm; kỷ niệm","trong chừng mực mà; theo như","phát hiện bất ngờ; sự thật được phơi bày"]'::jsonb, 1, '“commemorate” (/kəˈmeməreɪt/): tưởng niệm; kỷ niệm. Câu đầy đủ: Public ceremonies commemorate historical events and help younger generations understand the experiences that shaped their communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
