INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_2', 'en-c1-49', NULL, 'comprehensive_test', 'listening', 'We planted a tree to commemorate our grandfather''s life.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã sắp xếp những bức ảnh gia đình theo thứ tự thời gian.","Hướng dẫn viên bảo tàng cho chúng tôi xem một thùng thuốc súng cũ.","Chúng tôi đã trồng một cái cây để kỷ niệm cuộc đời của ông nội.","Chiếc máy cồng kềnh này là tiền thân của dòng máy tính xách tay ngày nay."]'::jsonb, 2, 'We planted a tree to commemorate our grandfather''s life. → Chúng tôi đã trồng một cái cây để kỷ niệm cuộc đời của ông nội.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_3', 'en-c1-49', NULL, 'comprehensive_test', 'listening', 'torpedo', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự thờ ơ; tính lãnh đạm; sự không quan tâm","ngư lôi (vũ khí dưới nước tự hành)","tinh xảo; tuyệt mỹ","đồ vật được làm từ một vật liệu cụ thể hoặc dùng cho một mục đích cụ thể; đồ gốm"]'::jsonb, 1, 'torpedo (/tɔːrˈpiːdoʊ/) → ngư lôi (vũ khí dưới nước tự hành); phá hoại; làm thất bại (kế hoạch, thỏa thuận)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_4', 'en-c1-49', NULL, 'comprehensive_test', 'listening', 'The baron welcomed his guests into the castle courtyard.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã trồng một cái cây để kỷ niệm cuộc đời của ông nội.","Hướng dẫn viên bảo tàng đã giải thích thuốc phiện đã ảnh hưởng đến thương mại như thế nào.","Vị nam tước chào đón các vị khách bước vào sân lâu đài.","Ban nhạc đã tấu lên những bản quân nhạc hùng tráng khi đoàn quân tiến bước qua."]'::jsonb, 2, 'The baron welcomed his guests into the castle courtyard. → Vị nam tước chào đón các vị khách bước vào sân lâu đài.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_5', 'en-c1-49', NULL, 'comprehensive_test', 'listening', 'missionary', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chùng; lỏng; không căng","tiên đoán; báo trước","nhà truyền giáo","nhàm chán; tẻ nhạt; đơn điệu"]'::jsonb, 2, 'missionary (/ˈmɪʃəneri/) → nhà truyền giáo; thuộc về truyền giáo; liên quan đến hoạt động truyền giáo', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_6', 'en-c1-49', NULL, 'comprehensive_test', 'listening', 'The old painting shows a prophet addressing a crowd.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bức tranh cổ vẽ cảnh một nhà tiên tri đang thuyết giảng trước đám đông.","Chúng tôi đã tham quan nhà tù cũ trong chuyến đi bộ tham quan.","Chúng tôi đã trồng một cái cây để kỷ niệm cuộc đời của ông nội.","Cửa hàng mở cửa vào mùa xuân và đóng cửa ngay sau đó."]'::jsonb, 0, 'The old painting shows a prophet addressing a crowd. → Bức tranh cổ vẽ cảnh một nhà tiên tri đang thuyết giảng trước đám đông.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_7', 'en-c1-49', NULL, 'comprehensive_test', 'listening', 'chronological', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đối thủ, kẻ địch","tăng dần; dâng lên; leo lên","theo thứ tự thời gian","sự đại diện; quyền đại diện"]'::jsonb, 2, 'chronological (/ˌkrɑːnəˈlɑːdʒɪkəl/) → theo thứ tự thời gian', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_8', 'en-c1-49', NULL, 'comprehensive_test', 'listening', 'The castle fell after months of fighting and conquest.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lâu đài đã thất thủ sau nhiều tháng giao tranh và chinh phạt.","Bảo tàng trưng bày nhiều hiện vật từ một cuộc khởi nghĩa tại địa phương.","Những dụng cụ làm vườn cũ đã bị gỉ sét do lâu ngày không được sử dụng.","Vị nam tước chào đón các vị khách bước vào sân lâu đài."]'::jsonb, 0, 'The castle fell after months of fighting and conquest. → Lâu đài đã thất thủ sau nhiều tháng giao tranh và chinh phạt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_9', 'en-c1-49', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “someone sent to teach a religion, often in another country”?', '["conquest","baron","thereafter","missionary"]'::jsonb, 3, 'missionary (/ˈmɪʃəneri/) → nhà truyền giáo', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
