INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_18', 'en-c1-49', NULL, 'comprehensive_test', 'reading', NULL, 'The city introduced stricter vehicle standards, and air quality improved steadily in the years thereafter.', 'Dựa vào câu trên, từ “thereafter” có nghĩa phù hợp nhất là gì?', '["sự rõ ràng; dễ hiểu","sắc lệnh; nghị định; quyết định chính thức","sau đó; từ đó trở đi","cây đước; cây mắm; rừng ngập mặn"]'::jsonb, 2, 'thereafter: sau đó; từ đó trở đi. Dịch cả câu: Thành phố đã áp dụng các tiêu chuẩn xe cộ nghiêm ngặt hơn, và chất lượng không khí đã cải thiện đều đặn trong những năm sau đó.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_19', 'en-c1-49', NULL, 'comprehensive_test', 'reading', NULL, 'Public ceremonies commemorate historical events and help younger generations understand the experiences that shaped their communities.', 'Dựa vào câu trên, từ “commemorate” có nghĩa phù hợp nhất là gì?', '["tưởng niệm; kỷ niệm","siết chặt; mím chặt","thọc; nhét mạnh; đẩy","thuộc tia tử ngoại; cực tím"]'::jsonb, 0, 'commemorate: tưởng niệm; kỷ niệm. Dịch cả câu: Các buổi lễ tưởng niệm công khai nhằm tôn vinh các sự kiện lịch sử và giúp thế hệ trẻ thấu hiểu những trải nghiệm đã định hình nên cộng đồng của họ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_20', 'en-c1-49', NULL, 'comprehensive_test', 'reading', NULL, 'Unexpected funding cuts could torpedo plans to expand public transport in rapidly growing urban areas.', 'Dựa vào câu trên, từ “torpedo” có nghĩa phù hợp nhất là gì?', '["làm triệt tiêu; vô hiệu hóa","ngữ âm học","ngư lôi (vũ khí dưới nước tự hành)","độc thoại"]'::jsonb, 2, 'torpedo: ngư lôi (vũ khí dưới nước tự hành); phá hoại; làm thất bại (kế hoạch, thỏa thuận). Dịch cả câu: Việc cắt giảm ngân sách bất ngờ có thể làm phá sản các kế hoạch mở rộng giao thông công cộng tại các khu đô thị đang phát triển nhanh chóng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_21', 'en-c1-49', NULL, 'comprehensive_test', 'reading', NULL, 'Media barons can influence public debate through their ownership of major newspapers and television networks.', 'Dựa vào câu trên, từ “baron” có nghĩa phù hợp nhất là gì?', '["nam tước","sự ca ngợi; tiếngvang","tiếng ồn ào; tiếng náo động kéo dài khó chịu","làm hết khát; thỏa mãn (khát khao, mong ước)"]'::jsonb, 0, 'baron: nam tước; ông trùm công nghiệp; đại gia. Dịch cả câu: Các ông trùm truyền thông có thể chi phối các cuộc tranh luận công khai thông qua việc nắm giữ các tờ báo và đài truyền hình lớn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_22', 'en-c1-49', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiền thân; người đi trước”', '["solidify","placard","forerunner","resonance"]'::jsonb, 2, 'tiền thân; người đi trước → forerunner (/ˈfɔːrʌnər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_23', 'en-c1-49', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thiên niên kỷ”', '["millennium","contrive","palatable","meddle"]'::jsonb, 0, 'thiên niên kỷ → millennium (/mɪˈleniəm/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_49_24', 'en-c1-49', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cuộc khởi nghĩa; cuộc nổi dậy”', '["consignment","proxy","narcotic","uprising"]'::jsonb, 3, 'cuộc khởi nghĩa; cuộc nổi dậy → uprising (/ˈʌpraɪzɪŋ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-50', 'en', 'Bài 50: Đô thị & Kiến trúc - CEFR C1', 'CEFR C1', 'C1 · Đô thị', '27 từ vựng Tiếng Anh CEFR C1 chủ đề đô thị & kiến trúc kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5050, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_waterfront', 'en-c1-50', 'waterfront', '/ˈwɔːtərfrʌnt/', 'C1', 'vùng ven sông hồ; khu vực giáp nước', 'n.', NULL, NULL, 'Chỉ vùng đất giáp mặt nước ở khu vực đô thị, không nhất thiết phải là bãi biển hay vùng duyên hải.', 'We walked along the waterfront after an early dinner.', NULL, 'Chúng tôi đi dạo dọc theo khu vực bờ sông sau bữa tối sớm.', '{"wordId":"waterfront","ukIpa":"/ˈwɔːtəfrʌnt/","usIpa":"/ˈwɔːtərfrʌnt/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"An area beside a sea, lake, or river, especially in towns.","vi":"vùng ven sông hồ; khu vực giáp nước"}],"examples":[{"en":"We walked along the waterfront after an early dinner.","vi":"Chúng tôi đi dạo dọc theo khu vực bờ sông sau bữa tối sớm.","audioKind":"ex"},{"en":"Redeveloping the waterfront can create attractive public spaces, provided that existing residents are not forced to leave.","vi":"Việc tái phát triển khu vực ven sông có thể tạo ra các không gian công cộng hấp dẫn, với điều kiện là cư dân hiện tại không bị buộc phải di dời.","audioKind":"ex2"}],"collocations":[{"en":"along the waterfront","vi":"dọc theo bờ nước"},{"en":"waterfront development","vi":"phát triển khu ven sông"},{"en":"a waterfront restaurant","vi":"nhà hàng ven sông"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ vùng đất giáp mặt nước ở khu vực đô thị, không nhất thiết phải là bãi biển hay vùng duyên hải.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overrun', 'en-c1-50', 'overrun', '/ˌoʊvərˈrʌn/', 'C1', 'tràn ngập; chiếm đóng với số lượng lớn; vượt quá (thời gian hoặc chi phí); khoảng thời gian hoặc chi phí vượt mức', 'v.', NULL, NULL, 'Chia ở dạng quá khứ là overran và phân từ hai là overrun; danh từ có trọng âm rơi vào âm tiết đầu.', 'Weeds have overrun the garden since our neighbours moved away.', NULL, 'Khu vườn đã mọc đầy cỏ dại từ khi nhà hàng xóm chuyển đi nơi khác.', '{"wordId":"overrun","ukIpa":"/ˌəʊvəˈrʌn/","usIpa":"/ˌoʊvərˈrʌn/","cefr":"C1","topic":"city","senses":[{"pos":"v.","en":"To spread through or occupy a place in unwanted numbers.","vi":"tràn ngập; chiếm đóng với số lượng lớn"},{"pos":"v.","en":"To continue beyond an agreed time or cost limit.","vi":"vượt quá (thời gian hoặc chi phí)"},{"pos":"n.","en":"An amount by which planned time or costs are exceeded.","vi":"khoảng thời gian hoặc chi phí vượt mức"}],"examples":[{"en":"Weeds have overrun the garden since our neighbours moved away.","vi":"Khu vườn đã mọc đầy cỏ dại từ khi nhà hàng xóm chuyển đi nơi khác.","audioKind":"ex"},{"en":"Major infrastructure projects often overrun their budgets when planners underestimate material costs and construction delays.","vi":"Các dự án cơ sở hạ tầng lớn thường bị vượt ngân sách khi các nhà quy hoạch đánh giá thấp chi phí vật liệu và sự chậm trễ trong thi công.","audioKind":"ex2"}],"collocations":[{"en":"be overrun with weeds","vi":"bị cỏ dại tràn ngập"},{"en":"overrun the budget","vi":"vượt quá ngân sách"},{"en":"cost overrun","vi":"chi phí vượt mức"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chia ở dạng quá khứ là overran và phân từ hai là overrun; danh từ có trọng âm rơi vào âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_occupant', 'en-c1-50', 'occupant', '/ˈɑːkjəpənt/', 'C1', 'người cư ngụ; người sử dụng; hành khách (trên xe)', 'n.', 'occupy (v.), occupied (adj.), occupancy (n.), occupation (n.)', NULL, 'Nhấn mạnh việc sinh sống hoặc sử dụng thực tế, không nhất thiết phải là chủ sở hữu (owner).', 'The previous occupant left some curtains in the flat.', NULL, 'Người thuê nhà trước đã để lại một số tấm rèm trong căn hộ.', '{"wordId":"occupant","ukIpa":"/ˈɒkjəpənt/","usIpa":"/ˈɑːkjəpənt/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"Someone who lives in or uses a room, building, or vehicle.","vi":"người cư ngụ; người sử dụng; hành khách (trên xe)"}],"examples":[{"en":"The previous occupant left some curtains in the flat.","vi":"Người thuê nhà trước đã để lại một số tấm rèm trong căn hộ.","audioKind":"ex"},{"en":"Building regulations should ensure that every occupant can leave safely in the event of a fire.","vi":"Các quy định xây dựng phải đảm bảo rằng mọi người ở trong tòa nhà có thể sơ tán an toàn trong trường hợp xảy ra hỏa hoạn.","audioKind":"ex2"}],"collocations":[{"en":"previous occupant","vi":"người ở trước đó"},{"en":"building occupants","vi":"người trong tòa nhà"},{"en":"vehicle occupants","vi":"hành khách trên xe"}],"wordFamily":["occupy (v.)","occupied (adj.)","occupancy (n.)","occupation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh việc sinh sống hoặc sử dụng thực tế, không nhất thiết phải là chủ sở hữu (owner).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_erect', 'en-c1-50', 'erect', '/ɪˈrekt/', 'C1', 'xây dựng; dựng lên; thẳng đứng; đứng thẳng', 'v.', 'erection (n.)', NULL, 'Động từ build mang tính chính thức hơn build; tính từ thường gặp trong cụm stand erect.', 'We erected our tent beside the lake before sunset.', NULL, 'Chúng tôi đã dựng lều bên hồ trước khi mặt trời lặn.', '{"wordId":"erect","ukIpa":"/ɪˈrekt/","usIpa":"/ɪˈrekt/","cefr":"C1","topic":"city","senses":[{"pos":"v.","en":"to build something or put it in an upright position","vi":"xây dựng; dựng lên"},{"pos":"adj.","en":"standing straight up rather than bending or lying down","vi":"thẳng đứng; đứng thẳng"}],"examples":[{"en":"We erected our tent beside the lake before sunset.","vi":"Chúng tôi đã dựng lều bên hồ trước khi mặt trời lặn.","audioKind":"ex"},{"en":"Local authorities plan to erect temporary shelters for families whose homes were damaged by severe flooding.","vi":"Chính quyền địa phương dự định dựng các khu nhà tạm cho các gia đình có nhà cửa bị tàn phá bởi trận lũ lụt nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"erect a tent","vi":"dựng lều"},{"en":"erect a monument","vi":"dựng tượng đài"},{"en":"stand erect","vi":"đứng thẳng"}],"wordFamily":["erection (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ build mang tính chính thức hơn build; tính từ thường gặp trong cụm stand erect.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dwarf', 'en-c1-50', 'dwarf', '/dwɔːrf/', 'C1', 'làm cho lu mờ; làm cho nhỏ bé hẳn đi; sinh vật lợn cợn nhỏ bé; người lùn trong thần thoại; giống lùn; kích thước nhỏ hơn bình thường', 'v.', 'dwarfish (adj.), dwarfism (n.)', 'Đồng nghĩa: overshadow', 'Động từ thường biểu thị sự chênh lệch lớn về quy mô; danh từ chỉ con người có thể gây tổn thương nên cần dùng thận trọng.', 'The new tower dwarfs every house on our street.', NULL, 'Tòa tháp mới xây khiến mọi ngôi nhà trên phố nhà chúng tôi đều trở nên nhỏ bé.', '{"wordId":"dwarf","ukIpa":"/dwɔːf/","usIpa":"/dwɔːrf/","cefr":"C1","topic":"city","senses":[{"pos":"v.","en":"To make something seem small by comparison.","vi":"làm cho lu mờ; làm cho nhỏ bé hẳn đi"},{"pos":"n.","en":"An unusually small organism, or a small humanlike fantasy creature.","vi":"sinh vật lợn cợn nhỏ bé; người lùn trong thần thoại"},{"pos":"adj.","en":"Much smaller than the usual size of its kind.","vi":"giống lùn; kích thước nhỏ hơn bình thường"}],"examples":[{"en":"The new tower dwarfs every house on our street.","vi":"Tòa tháp mới xây khiến mọi ngôi nhà trên phố nhà chúng tôi đều trở nên nhỏ bé.","audioKind":"ex"},{"en":"The long-term costs of environmental damage may dwarf the immediate profits generated by industrial expansion.","vi":"Chi phí dài hạn của việc tàn phá môi trường có thể làm lu mờ hoàn toàn lợi nhuận trước mắt do sự bành trướng công nghiệp mang lại.","audioKind":"ex2"}],"collocations":[{"en":"be dwarfed by","vi":"trở nên nhỏ bé trước"},{"en":"dwarf tree","vi":"cây lùn"},{"en":"dwarf planet","vi":"hành tinh lùn"}],"wordFamily":["dwarfish (adj.)","dwarfism (n.)"],"synonyms":["overshadow"],"antonyms":[],"tipVi":"Động từ thường biểu thị sự chênh lệch lớn về quy mô; danh từ chỉ con người có thể gây tổn thương nên cần dùng thận trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dwelling', 'en-c1-50', 'dwelling', '/ˈdwelɪŋ/', 'C1', 'nơi ở; chốn ở; nhà cửa', 'n.', 'dwell (v.), dweller (n.)', 'Đồng nghĩa: residence, home', 'Danh từ đếm được mang tính trang trọng; trong giao tiếp hàng ngày về nhà của mình thường dùng home.', 'Their small dwelling overlooks a quiet stretch of river.', NULL, 'Ngôi nhà nhỏ của họ hướng ra một khúc sông êm đềm.', '{"wordId":"dwelling","ukIpa":"/ˈdwelɪŋ/","usIpa":"/ˈdwelɪŋ/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"A house, flat, or other place where someone lives","vi":"nơi ở; chốn ở; nhà cửa"}],"examples":[{"en":"Their small dwelling overlooks a quiet stretch of river.","vi":"Ngôi nhà nhỏ của họ hướng ra một khúc sông êm đềm.","audioKind":"ex"},{"en":"Every new dwelling should meet energy efficiency standards to reduce household costs and environmental damage.","vi":"Mỗi ngôi nhà mới xây đều phải đáp ứng các tiêu chuẩn về hiệu quả năng lượng nhằm giảm chi phí sinh hoạt cho gia đình và hạn chế tác động đến môi trường.","audioKind":"ex2"}],"collocations":[{"en":"private dwelling","vi":"nhà ở tư nhân"},{"en":"permanent dwelling","vi":"nơi ở cố định"},{"en":"dwelling place","vi":"nơi cư trú"}],"wordFamily":["dwell (v.)","dweller (n.)"],"synonyms":["residence","home"],"antonyms":[],"tipVi":"Danh từ đếm được mang tính trang trọng; trong giao tiếp hàng ngày về nhà của mình thường dùng home.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sewer', 'en-c1-50', 'sewer', '/ˈsuːər/', 'C1', 'cống ngầm; đường ống thoát nước', 'n.', 'sewerage (n.)', NULL, 'Sewer là đường ống, sewage là nước thải, còn sewerage là hệ thống thoát nước.', 'Workers cleared the blocked sewer beneath our street.', NULL, 'Các công nhân đã thông cống ngầm bị tắc bên dưới con đường của chúng tôi.', '{"wordId":"sewer","ukIpa":"/ˈsuːə/","usIpa":"/ˈsuːər/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"An underground pipe that carries away sewage and wastewater","vi":"cống ngầm; đường ống thoát nước"}],"examples":[{"en":"Workers cleared the blocked sewer beneath our street.","vi":"Các công nhân đã thông cống ngầm bị tắc bên dưới con đường của chúng tôi.","audioKind":"ex"},{"en":"Investment in modern sewer systems can reduce water pollution and improve public health in rapidly growing cities.","vi":"Việc đầu tư vào hệ thống cống ngầm hiện đại có thể làm giảm ô nhiễm nguồn nước và cải thiện sức khỏe cộng đồng ở các thành phố đang phát triển nhanh.","audioKind":"ex2"}],"collocations":[{"en":"sewer system","vi":"hệ thống cống ngầm"},{"en":"blocked sewer","vi":"cống ngầm bị tắc"},{"en":"sewer pipe","vi":"đường ống thoát nước"}],"wordFamily":["sewerage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Sewer là đường ống, sewage là nước thải, còn sewerage là hệ thống thoát nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_din', 'en-c1-50', 'din', '/dɪn/', 'C1', 'tiếng ồn ào; tiếng náo động kéo dài khó chịu', 'n.', NULL, 'Đồng nghĩa: racket, clamour', 'Thường dùng ở dạng danh từ số ít, nhấn mạnh thứ âm thanh kéo dài và gây khó chịu.', 'We could barely hear each other above the din.', NULL, 'Chúng tôi hầu như không thể nghe thấy nhau nói gì giữa tiếng ồn ào đó.', '{"wordId":"din","ukIpa":"/dɪn/","usIpa":"/dɪn/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"A loud, unpleasant mixture of continuing noises.","vi":"tiếng ồn ào; tiếng náo động kéo dài khó chịu"}],"examples":[{"en":"We could barely hear each other above the din.","vi":"Chúng tôi hầu như không thể nghe thấy nhau nói gì giữa tiếng ồn ào đó.","audioKind":"ex"},{"en":"The constant din of traffic can reduce residents'' quality of life and disturb their sleep.","vi":"Tiếng ồn giao thông liên tục có thể làm giảm chất lượng sống của cư dân và làm gián đoạn giấc ngủ của họ.","audioKind":"ex2"}],"collocations":[{"en":"above the din","vi":"vượt lên trên tiếng ồn ào"},{"en":"a deafening din","vi":"tiếng ồn điếc tai"},{"en":"the din of traffic","vi":"tiếng ồn ào từ xe cộ"}],"wordFamily":[],"synonyms":["racket","clamour"],"antonyms":[],"tipVi":"Thường dùng ở dạng danh từ số ít, nhấn mạnh thứ âm thanh kéo dài và gây khó chịu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tenancy', 'en-c1-50', 'tenancy', '/ˈtenənsi/', 'C1', 'quyền thuê nhà; thỏa thuận thuê tài sản; thời hạn thuê (nhà, đất)', 'n.', 'tenant (n.)', NULL, 'tenant chỉ người thuê nhà; tenancy chỉ mối quan hệ thuê mướn, quyền thuê hoặc thời hạn thuê.', 'Our tenancy ends next month, so we are packing.', NULL, 'Hợp đồng thuê nhà của chúng tôi sẽ kết thúc vào tháng tới, nên chúng tôi đang dọn đồ đạc.', '{"wordId":"tenancy","ukIpa":"/ˈtenənsi/","usIpa":"/ˈtenənsi/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"The legal right or arrangement to occupy rented property.","vi":"quyền thuê nhà; thỏa thuận thuê tài sản"},{"pos":"n.","en":"The period during which someone rents a property.","vi":"thời hạn thuê (nhà, đất)"}],"examples":[{"en":"Our tenancy ends next month, so we are packing.","vi":"Hợp đồng thuê nhà của chúng tôi sẽ kết thúc vào tháng tới, nên chúng tôi đang dọn đồ đạc.","audioKind":"ex"},{"en":"Clear tenancy agreements can protect both landlords and tenants by defining their respective rights and responsibilities.","vi":"Các thỏa thuận thuê nhà rõ ràng có thể bảo vệ cả chủ nhà và người thuê bằng cách xác định rõ quyền lợi và trách nhiệm của từng bên.","audioKind":"ex2"}],"collocations":[{"en":"a tenancy agreement","vi":"hợp đồng thuê nhà"},{"en":"a fixed-term tenancy","vi":"thời hạn thuê cố định"},{"en":"terminate a tenancy","vi":"chấm dứt hợp đồng thuê"},{"en":"security of tenancy","vi":"sự bảo đảm quyền thuê nhà"}],"wordFamily":["tenant (n.)"],"synonyms":[],"antonyms":[],"tipVi":"tenant chỉ người thuê nhà; tenancy chỉ mối quan hệ thuê mướn, quyền thuê hoặc thời hạn thuê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trench', 'en-c1-50', 'trench', '/trentʃ/', 'C1', 'hào; rãnh; chiến hào; hải rãnh; vực sâu đại dương', 'n.', NULL, 'Đồng nghĩa: ditch', 'Từ trench trên mặt đất nghĩa là mương hào hoặc chiến hào, còn dưới đáy biển nghĩa là hải rãnh.', 'Workers dug a trench to repair the broken pipe.', NULL, 'Công nhân đã đào một con rãnh để sửa chữa đường ống bị vỡ.', '{"wordId":"trench","ukIpa":"/trentʃ/","usIpa":"/trentʃ/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"A long, narrow ditch dug in the ground.","vi":"hào; rãnh; chiến hào"},{"pos":"n.","en":"A long, narrow, very deep valley on the ocean floor.","vi":"hải rãnh; vực sâu đại dương"}],"examples":[{"en":"Workers dug a trench to repair the broken pipe.","vi":"Công nhân đã đào một con rãnh để sửa chữa đường ống bị vỡ.","audioKind":"ex"},{"en":"Before laying underground cables, engineers must ensure that each trench is stable and safe for workers.","vi":"Trước khi đặt cáp ngầm, các kỹ sư phải đảm bảo rằng mỗi rãnh đào đều ổn định và an toàn cho người lao động.","audioKind":"ex2"}],"collocations":[{"en":"dig a trench","vi":"đào hào"},{"en":"deep trench","vi":"hào sâu"},{"en":"ocean trench","vi":"hải rãnh đại dương"},{"en":"trench warfare","vi":"chiến tranh chiến hào"}],"wordFamily":[],"synonyms":["ditch"],"antonyms":[],"tipVi":"Từ trench trên mặt đất nghĩa là mương hào hoặc chiến hào, còn dưới đáy biển nghĩa là hải rãnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_upkeep', 'en-c1-50', 'upkeep', '/ˈʌpkiːp/', 'C1', 'sự bảo dưỡng; việc duy trì; chi phí bảo trì', 'n.', NULL, 'Đồng nghĩa: maintenance', 'Là danh từ không đếm được, dùng để chỉ cả công việc bảo dưỡng lẫn chi phí cần thiết cho việc đó.', 'This old house needs regular upkeep throughout the year.', NULL, 'Ngôi nhà cổ này cần được bảo dưỡng định kỳ trong suốt cả năm.', '{"wordId":"upkeep","ukIpa":"/ˈʌpkiːp/","usIpa":"/ˈʌpkiːp/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"work or money needed to keep something in good condition","vi":"sự bảo dưỡng; việc duy trì; chi phí bảo trì"}],"examples":[{"en":"This old house needs regular upkeep throughout the year.","vi":"Ngôi nhà cổ này cần được bảo dưỡng định kỳ trong suốt cả năm.","audioKind":"ex"},{"en":"Local authorities must budget for the upkeep of public parks to ensure they remain safe and accessible.","vi":"Chính quyền địa phương phải bố trí ngân sách cho việc bảo trì các công viên công cộng để đảm bảo chúng luôn an toàn và thuận tiện cho người dân sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"regular upkeep","vi":"bảo dưỡng thường xuyên"},{"en":"cost of upkeep","vi":"chi phí bảo trì"},{"en":"property upkeep","vi":"bảo trì bất động sản"}],"wordFamily":[],"synonyms":["maintenance"],"antonyms":[],"tipVi":"Là danh từ không đếm được, dùng để chỉ cả công việc bảo dưỡng lẫn chi phí cần thiết cho việc đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_erection', 'en-c1-50', 'erection', '/ɪˈrekʃən/', 'C1', 'sự xây dựng; sự dựng lên; sự cương cứng', 'n.', 'erect (v.), erect (adj.)', 'Đồng nghĩa: construction · Trái nghĩa: demolition', 'Nghĩa xây dựng mang tính trang trọng, thường đi với giới từ of; từ này còn có nghĩa sinh lý học tùy theo ngữ cảnh.', 'The erection of our garden shed took all afternoon.', NULL, 'Việc dựng nhà kho ở khu vườn của chúng tôi mất toi cả buổi chiều.', '{"wordId":"erection","ukIpa":"/ɪˈrekʃən/","usIpa":"/ɪˈrekʃən/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"the act of building or putting a structure upright","vi":"sự xây dựng; sự dựng lên"},{"pos":"n.","en":"a state in which the penis becomes firm and enlarged","vi":"sự cương cứng"}],"examples":[{"en":"The erection of our garden shed took all afternoon.","vi":"Việc dựng nhà kho ở khu vườn của chúng tôi mất toi cả buổi chiều.","audioKind":"ex"},{"en":"The erection of temporary flood barriers can protect vulnerable homes while permanent defences are being constructed.","vi":"Việc dựng lên các hàng rào chống lũ tạm thời có thể bảo vệ các ngôi nhà dễ bị tổn thương trong khi các công trình kiên cố đang được thi công.","audioKind":"ex2"}],"collocations":[{"en":"erection of scaffolding","vi":"việc dựng giàn giáo"},{"en":"erection of a monument","vi":"việc dựng tượng đài"},{"en":"steel erection","vi":"lắp dựng kết cấu thép"}],"wordFamily":["erect (v.)","erect (adj.)"],"synonyms":["construction"],"antonyms":["demolition"],"tipVi":"Nghĩa xây dựng mang tính trang trọng, thường đi với giới từ of; từ này còn có nghĩa sinh lý học tùy theo ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diversion', 'en-c1-50', 'diversion', '/daɪˈvɝːʒən/', 'C1', 'sự đổi hướng đường đi hoặc sự thay đổi mục đích sử dụng của cái gì đó; điều làm sao lãng sự chú ý khỏi một hoạt động hoặc mối bận tâm khác; hoạt động giải trí thú vị giúp giải tỏa khỏi guồng quay thường ngày', 'n.', 'divert (v.), diverting (adj.)', NULL, 'Trong tiếng Anh-Anh có thể chỉ việc đường sá đổi hướng; tiếng Anh-Mỹ thường dùng detour.', 'The road diversion took us past a beautiful lake.', NULL, 'Việc đổi hướng giao thông đã dẫn chúng tôi đi qua một hồ nước đẹp.', '{"wordId":"diversion","ukIpa":"/daɪˈvɜːʃən/","usIpa":"/daɪˈvɝːʒən/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"A change in the route or use of something.","vi":"sự đổi hướng đường đi hoặc sự thay đổi mục đích sử dụng của cái gì đó"},{"pos":"n.","en":"Something that draws attention away from another activity or concern.","vi":"điều làm sao lãng sự chú ý khỏi một hoạt động hoặc mối bận tâm khác"},{"pos":"n.","en":"An enjoyable activity that provides a break from routine.","vi":"hoạt động giải trí thú vị giúp giải tỏa khỏi guồng quay thường ngày"}],"examples":[{"en":"The road diversion took us past a beautiful lake.","vi":"Việc đổi hướng giao thông đã dẫn chúng tôi đi qua một hồ nước đẹp.","audioKind":"ex"},{"en":"The diversion of public funds away from education could limit opportunities for children in disadvantaged communities.","vi":"Việc chuyển hướng quỹ công khỏi lĩnh vực giáo dục có thể hạn chế cơ hội của trẻ em ở các cộng đồng có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"a traffic diversion","vi":"sự chuyển hướng giao thông"},{"en":"the diversion of funds","vi":"sự chuyển dịch nguồn quỹ"},{"en":"create a diversion","vi":"tạo sự đánh lạc hướng"},{"en":"a welcome diversion","vi":"một trò tiêu khiển đáng hoan nghênh"}],"wordFamily":["divert (v.)","diverting (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh có thể chỉ việc đường sá đổi hướng; tiếng Anh-Mỹ thường dùng detour.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_standstill', 'en-c1-50', 'standstill', '/ˈstændstɪl/', 'C1', 'sự đình trệ; sự ngưng trệ; tình trạng tê liệt', 'n.', NULL, 'Đồng nghĩa: halt, stop', 'Thường đi với cụm come to a standstill, lưu ý có mạo từ a.', 'Traffic came to a standstill outside the station.', NULL, 'Giao thông bên ngoài nhà ga hoàn toàn tê liệt.', '{"wordId":"standstill","ukIpa":"/ˈstændstɪl/","usIpa":"/ˈstændstɪl/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"A state in which all movement or activity has stopped.","vi":"sự đình trệ; sự ngưng trệ; tình trạng tê liệt"}],"examples":[{"en":"Traffic came to a standstill outside the station.","vi":"Giao thông bên ngoài nhà ga hoàn toàn tê liệt.","audioKind":"ex"},{"en":"Severe flooding brought construction to a standstill, delaying urgently needed housing projects across the region.","vi":"Tình trạng ngập lụt nghiêm trọng đã làm cho việc xây dựng bị đình trệ hoàn toàn, làm chậm trễ các dự án nhà ở đang rất cần thiết trong khu vực.","audioKind":"ex2"}],"collocations":[{"en":"come to a standstill","vi":"rơi vào tình trạng đình trệ"},{"en":"bring something to a standstill","vi":"làm cho việc gì đó bị ngưng trệ"},{"en":"at a standstill","vi":"đang ở trạng thái ngưng trệ"}],"wordFamily":[],"synonyms":["halt","stop"],"antonyms":[],"tipVi":"Thường đi với cụm come to a standstill, lưu ý có mạo từ a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adjacent', 'en-c1-50', 'adjacent', '/əˈdʒeɪsənt/', 'C1', 'liền kề; sát cạnh; gần kề', 'adj.', 'adjacency (n.)', 'Đồng nghĩa: neighbouring, adjoining', 'Cấu trúc ''adjacent to'' dùng để diễn tả vị trí nằm sát hoặc ngay cạnh cái gì.', 'We booked adjacent rooms so the children could stay nearby.', NULL, 'Chúng tôi đã đặt các phòng liền kề để lũ trẻ có thể ở gần nhau.', '{"wordId":"adjacent","ukIpa":"/əˈdʒeɪsənt/","usIpa":"/əˈdʒeɪsənt/","cefr":"C1","topic":"city","senses":[{"pos":"adj.","en":"next to or very near something","vi":"liền kề; sát cạnh; gần kề"}],"examples":[{"en":"We booked adjacent rooms so the children could stay nearby.","vi":"Chúng tôi đã đặt các phòng liền kề để lũ trẻ có thể ở gần nhau.","audioKind":"ex"},{"en":"Residents in areas adjacent to the airport often experience high levels of noise pollution.","vi":"Cư dân sống ở các khu vực giáp sân bay thường xuyên phải chịu đựng tình trạng ô nhiễm tiếng ồn nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"adjacent to","vi":"tiếp giáp với"},{"en":"adjacent rooms","vi":"các phòng liền kề"},{"en":"adjacent buildings","vi":"các tòa nhà sát nhau"}],"wordFamily":["adjacency (n.)"],"synonyms":["neighbouring","adjoining"],"antonyms":[],"tipVi":"Cấu trúc ''adjacent to'' dùng để diễn tả vị trí nằm sát hoặc ngay cạnh cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proximity', 'en-c1-50', 'proximity', '/prɑːkˈsɪməti/', 'C1', 'sự ở gần; sự giáp ranh', 'n.', 'proximate (adj.)', 'Đồng nghĩa: nearness, closeness · Trái nghĩa: remoteness', 'Thường đi với proximity to; ở đây to là giới từ, theo sau là danh từ.', 'We chose this flat for its proximity to the park.', NULL, 'Chúng tôi chọn căn hộ này vì nó nằm gần công viên.', '{"wordId":"proximity","ukIpa":"/prɒkˈsɪməti/","usIpa":"/prɑːkˈsɪməti/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"The state of being near something in distance or time.","vi":"sự ở gần; sự giáp ranh"}],"examples":[{"en":"We chose this flat for its proximity to the park.","vi":"Chúng tôi chọn căn hộ này vì nó nằm gần công viên.","audioKind":"ex"},{"en":"Living in close proximity to busy roads may increase residents'' exposure to noise and air pollution.","vi":"Sống ở khu vực sát các tuyến đường đông đúc có thể khiến cư dân tiếp xúc nhiều hơn với tiếng ồn và ô nhiễm không khí.","audioKind":"ex2"}],"collocations":[{"en":"proximity to","vi":"sự gần gũi với"},{"en":"in close proximity to","vi":"nằm sát gần; ở ngay cạnh"},{"en":"geographical proximity","vi":"sự gần gũi về mặt địa lý"}],"wordFamily":["proximate (adj.)"],"synonyms":["nearness","closeness"],"antonyms":["remoteness"],"tipVi":"Thường đi với proximity to; ở đây to là giới từ, theo sau là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_partition', 'en-c1-50', 'partition', '/pɑːrˈtɪʃən/', 'C1', 'vách ngăn; tấm bình phong; sự chia cắt; sự phân chia (lãnh thổ, quốc gia); ngăn ra; phân chia', 'n.', NULL, 'Đồng nghĩa: divider, divide', 'partition off chỉ hành động ngăn ra một không gian riêng, như ngăn ra một văn phòng nhỏ.', 'A wooden partition separates our kitchen from the dining area.', NULL, 'Một bức vách bằng gỗ ngăn cách nhà bếp của chúng tôi với khu vực ăn uống.', '{"wordId":"partition","ukIpa":"/pɑːˈtɪʃən/","usIpa":"/pɑːrˈtɪʃən/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"A wall or screen that divides a space into sections.","vi":"vách ngăn; tấm bình phong"},{"pos":"n.","en":"The division of a country or area into separate parts.","vi":"sự chia cắt; sự phân chia (lãnh thổ, quốc gia)"},{"pos":"v.","en":"To divide a space or area into separate sections.","vi":"ngăn ra; phân chia"}],"examples":[{"en":"A wooden partition separates our kitchen from the dining area.","vi":"Một bức vách bằng gỗ ngăn cách nhà bếp của chúng tôi với khu vực ăn uống.","audioKind":"ex"},{"en":"Movable partitions allow schools to adapt classroom spaces for group discussions, independent study, and larger community events.","vi":"Các vách ngăn di động giúp các trường học linh hoạt điều chỉnh không gian lớp học để phục vụ cho các buổi thảo luận nhóm, tự học và các hoạt động cộng đồng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"a glass partition","vi":"vách kính"},{"en":"a partition wall","vi":"tường ngăn phòng"},{"en":"partition off","vi":"ngăn vách ra"},{"en":"the partition of a country","vi":"sự chia cắt đất nước"}],"wordFamily":[],"synonyms":["divider","divide"],"antonyms":[],"tipVi":"partition off chỉ hành động ngăn ra một không gian riêng, như ngăn ra một văn phòng nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manhole', 'en-c1-50', 'manhole', '/ˈmænhoʊl/', 'C1', 'miệng cống; hố ga; cửa kiểm tra kỹ thuật', 'n.', NULL, NULL, 'Cụm từ hay gặp là manhole cover, chỉ nắp đậy trên mặt đường.', 'The worker lifted the heavy cover from the manhole.', NULL, 'Người công nhân đã nhấc nắp nặng ra khỏi miệng cống.', '{"wordId":"manhole","ukIpa":"/ˈmænhəʊl/","usIpa":"/ˈmænhoʊl/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"An opening allowing workers to reach underground pipes or equipment.","vi":"miệng cống; hố ga; cửa kiểm tra kỹ thuật"}],"examples":[{"en":"The worker lifted the heavy cover from the manhole.","vi":"Người công nhân đã nhấc nắp nặng ra khỏi miệng cống.","audioKind":"ex"},{"en":"Regular inspections through manholes help engineers identify damage to urban drainage systems before serious flooding occurs.","vi":"Việc kiểm tra định kỳ qua các hố ga giúp kỹ sư phát hiện hư hỏng của hệ thống thoát nước đô thị trước khi ngập lụt nghiêm trọng xảy ra.","audioKind":"ex2"}],"collocations":[{"en":"manhole cover","vi":"nắp hố ga"},{"en":"open manhole","vi":"miệng cống mở"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ hay gặp là manhole cover, chỉ nắp đậy trên mặt đường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_metropolitan', 'en-c1-50', 'metropolitan', '/ˌmetrəˈpɑːlɪtən/', 'C1', 'thuộc đô thị lớn; thuộc vùng đô thị', 'adj.', 'metropolis (n.)', 'Đồng nghĩa: urban · Trái nghĩa: rural', 'Không chỉ riêng thủ đô; metropolitan area thường bao gồm cả khu vực thành thị và vùng ngoại ô xung quanh.', 'Our metropolitan rail network connects the suburbs to downtown.', NULL, 'Mạng lưới đường sắt đô thị của chúng tôi kết nối các vùng ngoại ô với trung tâm thành phố.', '{"wordId":"metropolitan","ukIpa":"/ˌmetrəˈpɒlɪtən/","usIpa":"/ˌmetrəˈpɑːlɪtən/","cefr":"C1","topic":"city","senses":[{"pos":"adj.","en":"relating to a large city and its surrounding communities","vi":"thuộc đô thị lớn; thuộc vùng đô thị"}],"examples":[{"en":"Our metropolitan rail network connects the suburbs to downtown.","vi":"Mạng lưới đường sắt đô thị của chúng tôi kết nối các vùng ngoại ô với trung tâm thành phố.","audioKind":"ex"},{"en":"Efficient public transport across metropolitan areas can reduce traffic congestion and improve access to employment opportunities.","vi":"Hệ thống giao thông công cộng hiệu quả trên khắp các vùng đô thị lớn có thể giảm thiểu tình trạng tắc nghẽn giao thông và cải thiện khả năng tiếp cận cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"metropolitan area","vi":"vùng đô thị"},{"en":"metropolitan region","vi":"vùng đại đô thị"},{"en":"metropolitan population","vi":"dân số đô thị"}],"wordFamily":["metropolis (n.)"],"synonyms":["urban"],"antonyms":["rural"],"tipVi":"Không chỉ riêng thủ đô; metropolitan area thường bao gồm cả khu vực thành thị và vùng ngoại ô xung quanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vicinity', 'en-c1-50', 'vicinity', '/vɪˈsɪnəti/', 'C1', 'vùng lân cận; vùng quanh đây', 'n.', NULL, 'Đồng nghĩa: surroundings, neighbourhood', 'Thường dùng trong cấu trúc in the vicinity of, mang tính trang trọng hơn near.', 'There are several quiet cafés in the vicinity.', NULL, 'Có vài quán cà phê yên tĩnh ở ngay khu vực lân cận.', '{"wordId":"vicinity","ukIpa":"/vɪˈsɪnəti/","usIpa":"/vɪˈsɪnəti/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"The area near a particular place.","vi":"vùng lân cận; vùng quanh đây"}],"examples":[{"en":"There are several quiet cafés in the vicinity.","vi":"Có vài quán cà phê yên tĩnh ở ngay khu vực lân cận.","audioKind":"ex"},{"en":"Building new housing in the vicinity of railway stations can reduce car dependence and shorten daily commutes.","vi":"Xây dựng nhà ở mới ở vùng lân cận các nhà ga xe lửa có thể giảm sự phụ thuộc vào ô tô và rút ngắn thời gian đi lại hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"in the vicinity of","vi":"ở vùng lân cận của"},{"en":"the immediate vicinity","vi":"vùng ngay sát cạnh"}],"wordFamily":[],"synonyms":["surroundings","neighbourhood"],"antonyms":[],"tipVi":"Thường dùng trong cấu trúc in the vicinity of, mang tính trang trọng hơn near.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sprawl', 'en-c1-50', 'sprawl', '/sprɔːl/', 'C1', 'nằm hoặc ngồi duỗi dài chân tay; lan rộng không theo quy hoạch; mọc ra vô tổ chức; vùng đô thị mở rộng tự phát; sự lan rộng vô trật tự', 'v.', 'sprawling (adj.)', NULL, 'Khi dùng với chủ ngữ chỉ người thường mang nghĩa nằm hoặc ngồi thoải mái; urban sprawl chỉ sự mở rộng thành phố tràn lan.', 'After the hike, we sprawled on the soft grass.', NULL, 'Sau chuyến đi bộ đường dài, chúng tôi nằm duỗi dài trên bãi cỏ mềm mại.', '{"wordId":"sprawl","ukIpa":"/sprɔːl/","usIpa":"/sprɔːl/","cefr":"C1","topic":"city","senses":[{"pos":"v.","en":"Sit or lie with your arms and legs spread out.","vi":"nằm hoặc ngồi duỗi dài chân tay"},{"pos":"v.","en":"Spread over a large area in an unplanned way.","vi":"lan rộng không theo quy hoạch; mọc ra vô tổ chức"},{"pos":"n.","en":"A large area of buildings spreading out without clear planning.","vi":"vùng đô thị mở rộng tự phát; sự lan rộng vô trật tự"}],"examples":[{"en":"After the hike, we sprawled on the soft grass.","vi":"Sau chuyến đi bộ đường dài, chúng tôi nằm duỗi dài trên bãi cỏ mềm mại.","audioKind":"ex"},{"en":"Urban sprawl can increase dependence on private cars and put pressure on surrounding farmland.","vi":"Sự mở rộng đô thị tự phát có thể làm tăng sự phụ thuộc vào xe hơi cá nhân và gây áp lực lên các vùng đất nông nghiệp xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"sprawl on the sofa","vi":"nằm dài trên sofa"},{"en":"sprawl out","vi":"duỗi thẳng chân tay"},{"en":"urban sprawl","vi":"sự mở rộng đô thị tự phát"},{"en":"a sprawling city","vi":"một thành phố mở rộng ngổn ngang"}],"wordFamily":["sprawling (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng với chủ ngữ chỉ người thường mang nghĩa nằm hoặc ngồi thoải mái; urban sprawl chỉ sự mở rộng thành phố tràn lan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embankment', 'en-c1-50', 'embankment', '/ɪmˈbæŋkmənt/', 'C1', 'đê; kè; đường đắp cao', 'n.', 'embank (v.)', 'Đồng nghĩa: bank, levee', 'Có thể chỉ bờ đê ngăn nước hoặc nền đường đắp cao nâng đỡ các tuyến giao thông đường bộ hay đường sắt.', 'We walked along the embankment beside the swollen river.', NULL, 'Chúng tôi đi bộ dọc theo con đê bên dòng sông đang dâng nước.', '{"wordId":"embankment","ukIpa":"/ɪmˈbæŋkmənt/","usIpa":"/ɪmˈbæŋkmənt/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"a raised bank supporting transport routes or holding back water","vi":"đê; kè; đường đắp cao"}],"examples":[{"en":"We walked along the embankment beside the swollen river.","vi":"Chúng tôi đi bộ dọc theo con đê bên dòng sông đang dâng nước.","audioKind":"ex"},{"en":"Strengthening the river embankment could protect nearby homes from flooding as extreme rainfall becomes more frequent.","vi":"Việc gia cố đê sông có thể bảo vệ các khu dân cư gần đó khỏi lũ lụt khi những trận mưa cực đoan ngày càng trở nên thường xuyên hơn.","audioKind":"ex2"}],"collocations":[{"en":"river embankment","vi":"đê sông"},{"en":"railway embankment","vi":"nền đường sắt"},{"en":"build an embankment","vi":"xây dựng đê điều"}],"wordFamily":["embank (v.)"],"synonyms":["bank","levee"],"antonyms":[],"tipVi":"Có thể chỉ bờ đê ngăn nước hoặc nền đường đắp cao nâng đỡ các tuyến giao thông đường bộ hay đường sắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obstruction', 'en-c1-50', 'obstruction', '/əbˈstrʌkʃən/', 'C1', 'vật cản, sự tắc nghẽn; sự cản trở, sự gây khó dễ', 'n.', 'obstruct (v.), obstructive (adj.)', 'Đồng nghĩa: blockage, hindrance', 'Vật cản cụ thể thường đếm được; hành động cản trở thường không đếm được.', 'A fallen branch caused an obstruction on the narrow path.', NULL, 'Một cành cây gãy gây ra vật cản trên con đường nhỏ hẹp.', '{"wordId":"obstruction","ukIpa":"/əbˈstrʌkʃən/","usIpa":"/əbˈstrʌkʃən/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"Something that blocks movement or passage.","vi":"vật cản, sự tắc nghẽn"},{"pos":"n.","en":"The act of deliberately preventing progress or action.","vi":"sự cản trở, sự gây khó dễ"}],"examples":[{"en":"A fallen branch caused an obstruction on the narrow path.","vi":"Một cành cây gãy gây ra vật cản trên con đường nhỏ hẹp.","audioKind":"ex"},{"en":"Removing unnecessary administrative procedures can reduce obstruction to the development of small businesses in rural areas.","vi":"Việc loại bỏ các thủ tục hành chính không cần thiết có thể làm giảm bớt cản trở đối với sự phát triển của các doanh nghiệp nhỏ ở vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"cause an obstruction","vi":"gây ra sự tắc nghẽn"},{"en":"remove an obstruction","vi":"dọn dẹp vật cản"},{"en":"obstruction of justice","vi":"cản trở thi hành công lý"}],"wordFamily":["obstruct (v.)","obstructive (adj.)"],"synonyms":["blockage","hindrance"],"antonyms":[],"tipVi":"Vật cản cụ thể thường đếm được; hành động cản trở thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regeneration', 'en-c1-50', 'regeneration', '/rɪˌdʒenəˈreɪʃən/', 'C1', 'sự phục hồi; sự tái thiết; sự đổi mới đô thị; sự tái sinh; quá trình mọc lại mô mới', 'n.', 'regenerate (v.), regenerative (adj.)', 'Đồng nghĩa: renewal, revival', 'Trong chủ đề đô thị, từ này chỉ sự cải tạo và nâng cấp; trong sinh học, nó chỉ sự tái sinh mô.', 'The neighbourhood''s regeneration brought new shops to our street.', NULL, 'Công cuộc cải tạo khu phố đã mang đến những cửa hàng mới cho con phố của chúng tôi.', '{"wordId":"regeneration","ukIpa":"/rɪˌdʒenəˈreɪʃən/","usIpa":"/rɪˌdʒenəˈreɪʃən/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"the process of improving a place or system in decline","vi":"sự phục hồi; sự tái thiết; sự đổi mới đô thị"},{"pos":"n.","en":"the process of growing new tissue to replace damaged parts","vi":"sự tái sinh; quá trình mọc lại mô mới"}],"examples":[{"en":"The neighbourhood''s regeneration brought new shops to our street.","vi":"Công cuộc cải tạo khu phố đã mang đến những cửa hàng mới cho con phố của chúng tôi.","audioKind":"ex"},{"en":"Urban regeneration can create employment, but rising rents may force existing residents to leave their neighbourhoods.","vi":"Sự tái thiết đô thị có thể tạo ra việc làm, nhưng giá thuê nhà tăng cao có thể buộc cư dân hiện tại phải rời khỏi khu phố của họ.","audioKind":"ex2"}],"collocations":[{"en":"urban regeneration","vi":"tái thiết đô thị"},{"en":"economic regeneration","vi":"phục hồi kinh tế"},{"en":"tissue regeneration","vi":"tái tạo mô"}],"wordFamily":["regenerate (v.)","regenerative (adj.)"],"synonyms":["renewal","revival"],"antonyms":[],"tipVi":"Trong chủ đề đô thị, từ này chỉ sự cải tạo và nâng cấp; trong sinh học, nó chỉ sự tái sinh mô.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_precinct', 'en-c1-50', 'precinct', '/ˈpriːsɪŋkt/', 'C1', 'khu phố đi bộ mua sắm; địa hạt cảnh sát; khu vực bầu cử; vùng xung quanh (đặc biệt là công trình tôn giáo)', 'n.', NULL, NULL, 'Khi chỉ vùng xung quanh công trình, từ này thường ở dạng số nhiều precincts.', 'We met outside the bakery in the shopping precinct.', NULL, 'Chúng tôi gặp nhau bên ngoài tiệm bánh ở khu phố đi bộ mua sắm.', '{"wordId":"precinct","ukIpa":"/ˈpriːsɪŋkt/","usIpa":"/ˈpriːsɪŋkt/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"A shopping area where vehicles are usually not allowed.","vi":"khu phố đi bộ mua sắm"},{"pos":"n.","en":"A district used for policing or elections.","vi":"địa hạt cảnh sát; khu vực bầu cử"},{"pos":"n.","en":"The grounds surrounding a building, especially a religious building.","vi":"vùng xung quanh (đặc biệt là công trình tôn giáo)"}],"examples":[{"en":"We met outside the bakery in the shopping precinct.","vi":"Chúng tôi gặp nhau bên ngoài tiệm bánh ở khu phố đi bộ mua sắm.","audioKind":"ex"},{"en":"Creating a pedestrian precinct can encourage local shopping while reducing traffic pollution in city centres.","vi":"Việc thiết lập khu vực đi bộ có thể thúc đẩy mua sắm tại địa phương đồng thời giảm ô nhiễm do giao thông ở trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"shopping precinct","vi":"khu phố mua sắm"},{"en":"pedestrian precinct","vi":"khu vực dành cho người đi bộ"},{"en":"police precinct","vi":"đồn cảnh sát; khu vực cảnh sát"},{"en":"cathedral precincts","vi":"khu vực quanh nhà thờ lớn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ vùng xung quanh công trình, từ này thường ở dạng số nhiều precincts.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adjoin', 'en-c1-50', 'adjoin', '/əˈdʒɔɪn/', 'C1', 'giáp ranh; liền kề; nối liền', 'v.', 'adjoining (adj.)', 'Đồng nghĩa: border, abut', 'Động từ adjoin đi trực tiếp với địa điểm, không dùng giới từ to; nhấn mạnh sự tiếp giáp trực tiếp.', 'Our garden adjoins a quiet park with tall oak trees.', NULL, 'Khu vườn của chúng tôi giáp với một công viên yên tĩnh có những cây sồi cao lớn.', '{"wordId":"adjoin","ukIpa":"/əˈdʒɔɪn/","usIpa":"/əˈdʒɔɪn/","cefr":"C1","topic":"city","senses":[{"pos":"v.","en":"to be directly next to or share a boundary with something","vi":"giáp ranh; liền kề; nối liền"}],"examples":[{"en":"Our garden adjoins a quiet park with tall oak trees.","vi":"Khu vườn của chúng tôi giáp với một công viên yên tĩnh có những cây sồi cao lớn.","audioKind":"ex"},{"en":"Residential areas that adjoin industrial sites may require additional measures to protect residents from noise and pollution.","vi":"Các khu dân cư liền kề với các khu công nghiệp có thể cần thêm các biện pháp để bảo vệ cư dân khỏi tiếng ồn và ô nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"adjoin a park","vi":"giáp công viên"},{"en":"adjoining rooms","vi":"các phòng liền kề"},{"en":"adjoining properties","vi":"các bất động sản liền kề"}],"wordFamily":["adjoining (adj.)"],"synonyms":["border","abut"],"antonyms":[],"tipVi":"Động từ adjoin đi trực tiếp với địa điểm, không dùng giới từ to; nhấn mạnh sự tiếp giáp trực tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bedsit', 'en-c1-50', 'bedsit', '/ˈbedsɪt/', 'C1', 'phòng trọ kiêm phòng ngủ và phòng khách', 'n.', NULL, NULL, 'Thuật ngữ tiếng Anh-Anh, chỉ phòng ở vừa làm phòng ngủ vừa làm phòng khách, thường dùng chung nhà vệ sinh.', 'He rented a small bedsit close to the station.', NULL, 'Anh ấy đã thuê một phòng trọ nhỏ gần ga tàu.', '{"wordId":"bedsit","ukIpa":"/ˈbedsɪt/","usIpa":"/ˈbedsɪt/","cefr":"C1","topic":"city","senses":[{"pos":"n.","en":"A rented room used for both living and sleeping.","vi":"phòng trọ kiêm phòng ngủ và phòng khách"}],"examples":[{"en":"He rented a small bedsit close to the station.","vi":"Anh ấy đã thuê một phòng trọ nhỏ gần ga tàu.","audioKind":"ex"},{"en":"For students with limited budgets, a bedsit may provide affordable accommodation near a university campus.","vi":"Đối với sinh viên có ngân sách hạn hẹp, một phòng trọ đơn có thể là chỗ ở giá rẻ gần khuôn viên trường đại học.","audioKind":"ex2"}],"collocations":[{"en":"rent a bedsit","vi":"thuê phòng trọ đơn"},{"en":"a furnished bedsit","vi":"phòng trọ có sẵn đồ đạc"},{"en":"a cramped bedsit","vi":"phòng trọ chật chội"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thuật ngữ tiếng Anh-Anh, chỉ phòng ở vừa làm phòng ngủ vừa làm phòng khách, thường dùng chung nhà vệ sinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_50_1', 'en-c1-50', 'Cách dùng “dwarf” (v.) — làm cho lu mờ; làm cho nhỏ bé hẳn đi', 'be dwarfed by  ·  dwarf tree  ·  dwarf planet', 'Động từ thường biểu thị sự chênh lệch lớn về quy mô; danh từ chỉ con người có thể gây tổn thương nên cần dùng thận trọng.', 'Họ từ (Word Family): dwarfish (adj.), dwarfism (n.) | Đồng nghĩa: overshadow', '[{"hanzi":"The new tower dwarfs every house on our street.","pinyin":"","meaning":"Tòa tháp mới xây khiến mọi ngôi nhà trên phố nhà chúng tôi đều trở nên nhỏ bé."},{"hanzi":"The long-term costs of environmental damage may dwarf the immediate profits generated by industrial expansion.","pinyin":"","meaning":"Chi phí dài hạn của việc tàn phá môi trường có thể làm lu mờ hoàn toàn lợi nhuận trước mắt do sự bành trướng công nghiệp mang lại."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_50_2', 'en-c1-50', 'Cách dùng “sprawl” (v.) — nằm hoặc ngồi duỗi dài chân tay', 'sprawl on the sofa  ·  sprawl out  ·  urban sprawl', 'Khi dùng với chủ ngữ chỉ người thường mang nghĩa nằm hoặc ngồi thoải mái; urban sprawl chỉ sự mở rộng thành phố tràn lan.', 'Họ từ (Word Family): sprawling (adj.)', '[{"hanzi":"After the hike, we sprawled on the soft grass.","pinyin":"","meaning":"Sau chuyến đi bộ đường dài, chúng tôi nằm duỗi dài trên bãi cỏ mềm mại."},{"hanzi":"Urban sprawl can increase dependence on private cars and put pressure on surrounding farmland.","pinyin":"","meaning":"Sự mở rộng đô thị tự phát có thể làm tăng sự phụ thuộc vào xe hơi cá nhân và gây áp lực lên các vùng đất nông nghiệp xung quanh."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_50_3', 'en-c1-50', 'Cách dùng “erection” (n.) — sự xây dựng; sự dựng lên', 'erection of scaffolding  ·  erection of a monument  ·  steel erection', 'Nghĩa xây dựng mang tính trang trọng, thường đi với giới từ of; từ này còn có nghĩa sinh lý học tùy theo ngữ cảnh.', 'Họ từ (Word Family): erect (v.), erect (adj.) | Đồng nghĩa: construction · Trái nghĩa: demolition', '[{"hanzi":"The erection of our garden shed took all afternoon.","pinyin":"","meaning":"Việc dựng nhà kho ở khu vườn của chúng tôi mất toi cả buổi chiều."},{"hanzi":"The erection of temporary flood barriers can protect vulnerable homes while permanent defences are being constructed.","pinyin":"","meaning":"Việc dựng lên các hàng rào chống lũ tạm thời có thể bảo vệ các ngôi nhà dễ bị tổn thương trong khi các công trình kiên cố đang được thi công."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_50_4', 'en-c1-50', 'Cách dùng “bedsit” (n.) — phòng trọ kiêm phòng ngủ và phòng khách', 'rent a bedsit  ·  a furnished bedsit  ·  a cramped bedsit', 'Thuật ngữ tiếng Anh-Anh, chỉ phòng ở vừa làm phòng ngủ vừa làm phòng khách, thường dùng chung nhà vệ sinh.', NULL, '[{"hanzi":"He rented a small bedsit close to the station.","pinyin":"","meaning":"Anh ấy đã thuê một phòng trọ nhỏ gần ga tàu."},{"hanzi":"For students with limited budgets, a bedsit may provide affordable accommodation near a university campus.","pinyin":"","meaning":"Đối với sinh viên có ngân sách hạn hẹp, một phòng trọ đơn có thể là chỗ ở giá rẻ gần khuôn viên trường đại học."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_50_1', 'en-c1-50', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_1_1', 'ten_c1_50_1', 'waterfront', 'We walked along the waterfront after an early dinner.', 'We walked along the waterfront after an early dinner.', '/ˈwɔːtərfrʌnt/', 'Chúng tôi đi dạo dọc theo khu vực bờ sông sau bữa tối sớm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_1_2', 'ten_c1_50_1', 'overrun', 'Weeds have overrun the garden since our neighbours moved away.', 'Weeds have overrun the garden since our neighbours moved away.', '/ˌoʊvərˈrʌn/', 'Khu vườn đã mọc đầy cỏ dại từ khi nhà hàng xóm chuyển đi nơi khác.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_1_3', 'ten_c1_50_1', 'occupant', 'The previous occupant left some curtains in the flat.', 'The previous occupant left some curtains in the flat.', '/ˈɑːkjəpənt/', 'Người thuê nhà trước đã để lại một số tấm rèm trong căn hộ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_1_4', 'ten_c1_50_1', 'erect', 'We erected our tent beside the lake before sunset.', 'We erected our tent beside the lake before sunset.', '/ɪˈrekt/', 'Chúng tôi đã dựng lều bên hồ trước khi mặt trời lặn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_1_5', 'ten_c1_50_1', 'dwarf', 'The new tower dwarfs every house on our street.', 'The new tower dwarfs every house on our street.', '/dwɔːrf/', 'Tòa tháp mới xây khiến mọi ngôi nhà trên phố nhà chúng tôi đều trở nên nhỏ bé.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_1_6', 'ten_c1_50_1', 'dwelling', 'Their small dwelling overlooks a quiet stretch of river.', 'Their small dwelling overlooks a quiet stretch of river.', '/ˈdwelɪŋ/', 'Ngôi nhà nhỏ của họ hướng ra một khúc sông êm đềm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_1_7', 'ten_c1_50_1', 'sewer', 'Workers cleared the blocked sewer beneath our street.', 'Workers cleared the blocked sewer beneath our street.', '/ˈsuːər/', 'Các công nhân đã thông cống ngầm bị tắc bên dưới con đường của chúng tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_1_8', 'ten_c1_50_1', 'din', 'We could barely hear each other above the din.', 'We could barely hear each other above the din.', '/dɪn/', 'Chúng tôi hầu như không thể nghe thấy nhau nói gì giữa tiếng ồn ào đó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_50_1_1', 'en-c1-50', 'ten_c1_50_1', 'listening', 'listening', 'We walked along the waterfront after an early dinner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Khu vườn của chúng tôi giáp với một công viên yên tĩnh có những cây sồi cao lớn.","Chúng tôi đi dạo dọc theo khu vực bờ sông sau bữa tối sớm.","Chúng tôi đi bộ dọc theo con đê bên dòng sông đang dâng nước.","Có vài quán cà phê yên tĩnh ở ngay khu vực lân cận."]'::jsonb, 1, 'We walked along the waterfront after an early dinner. → Chúng tôi đi dạo dọc theo khu vực bờ sông sau bữa tối sớm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_50_1_2', 'en-c1-50', 'ten_c1_50_1', 'listening', 'listening', 'Weeds have overrun the garden since our neighbours moved away.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tòa tháp mới xây khiến mọi ngôi nhà trên phố nhà chúng tôi đều trở nên nhỏ bé.","Chúng tôi đi bộ dọc theo con đê bên dòng sông đang dâng nước.","Chúng tôi chọn căn hộ này vì nó nằm gần công viên.","Khu vườn đã mọc đầy cỏ dại từ khi nhà hàng xóm chuyển đi nơi khác."]'::jsonb, 3, 'Weeds have overrun the garden since our neighbours moved away. → Khu vườn đã mọc đầy cỏ dại từ khi nhà hàng xóm chuyển đi nơi khác.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_50_1_3', 'en-c1-50', 'ten_c1_50_1', 'listening', 'listening', 'The previous occupant left some curtains in the flat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người thuê nhà trước đã để lại một số tấm rèm trong căn hộ.","Việc đổi hướng giao thông đã dẫn chúng tôi đi qua một hồ nước đẹp.","Chúng tôi gặp nhau bên ngoài tiệm bánh ở khu phố đi bộ mua sắm.","Chúng tôi chọn căn hộ này vì nó nằm gần công viên."]'::jsonb, 0, 'The previous occupant left some curtains in the flat. → Người thuê nhà trước đã để lại một số tấm rèm trong căn hộ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_50_2', 'en-c1-50', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_2_1', 'ten_c1_50_2', 'waterfront', 'Redeveloping the waterfront can create attractive public spaces, provided that existing residents are not forced to leave.', 'Redeveloping the waterfront can create attractive public spaces, provided that existing residents are not forced to leave.', '/ˈwɔːtərfrʌnt/', 'Việc tái phát triển khu vực ven sông có thể tạo ra các không gian công cộng hấp dẫn, với điều kiện là cư dân hiện tại không bị buộc phải di dời.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_2_2', 'ten_c1_50_2', 'overrun', 'Major infrastructure projects often overrun their budgets when planners underestimate material costs and construction delays.', 'Major infrastructure projects often overrun their budgets when planners underestimate material costs and construction delays.', '/ˌoʊvərˈrʌn/', 'Các dự án cơ sở hạ tầng lớn thường bị vượt ngân sách khi các nhà quy hoạch đánh giá thấp chi phí vật liệu và sự chậm trễ trong thi công.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_2_3', 'ten_c1_50_2', 'occupant', 'Building regulations should ensure that every occupant can leave safely in the event of a fire.', 'Building regulations should ensure that every occupant can leave safely in the event of a fire.', '/ˈɑːkjəpənt/', 'Các quy định xây dựng phải đảm bảo rằng mọi người ở trong tòa nhà có thể sơ tán an toàn trong trường hợp xảy ra hỏa hoạn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_2_4', 'ten_c1_50_2', 'erect', 'Local authorities plan to erect temporary shelters for families whose homes were damaged by severe flooding.', 'Local authorities plan to erect temporary shelters for families whose homes were damaged by severe flooding.', '/ɪˈrekt/', 'Chính quyền địa phương dự định dựng các khu nhà tạm cho các gia đình có nhà cửa bị tàn phá bởi trận lũ lụt nghiêm trọng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_2_5', 'ten_c1_50_2', 'dwarf', 'The long-term costs of environmental damage may dwarf the immediate profits generated by industrial expansion.', 'The long-term costs of environmental damage may dwarf the immediate profits generated by industrial expansion.', '/dwɔːrf/', 'Chi phí dài hạn của việc tàn phá môi trường có thể làm lu mờ hoàn toàn lợi nhuận trước mắt do sự bành trướng công nghiệp mang lại.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_50_2_6', 'ten_c1_50_2', 'dwelling', 'Every new dwelling should meet energy efficiency standards to reduce household costs and environmental damage.', 'Every new dwelling should meet energy efficiency standards to reduce household costs and environmental damage.', '/ˈdwelɪŋ/', 'Mỗi ngôi nhà mới xây đều phải đáp ứng các tiêu chuẩn về hiệu quả năng lượng nhằm giảm chi phí sinh hoạt cho gia đình và hạn chế tác động đến môi trường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_50_2_1', 'en-c1-50', 'ten_c1_50_2', 'listening', 'listening', 'Redeveloping the waterfront can create attractive public spaces, provided that existing residents are not forced to leave.', NULL, 'Trong câu vừa nghe, từ “waterfront” mang nghĩa nào sau đây?', '["nạn buôn lậu; hành vi vận chuyển trái phép (hàng hóa hoặc người qua biên giới)","sự giải thích chi tiết; sự bổ sung chi tiết","bịa đặt; ngụy tạo","vùng ven sông hồ; khu vực giáp nước"]'::jsonb, 3, '“waterfront” (/ˈwɔːtərfrʌnt/): vùng ven sông hồ; khu vực giáp nước. Câu đầy đủ: Redeveloping the waterfront can create attractive public spaces, provided that existing residents are not forced to leave.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_50_2_2', 'en-c1-50', 'ten_c1_50_2', 'listening', 'listening', 'Major infrastructure projects often overrun their budgets when planners underestimate material costs and construction delays.', NULL, 'Trong câu vừa nghe, từ “overrun” mang nghĩa nào sau đây?', '["tràn ngập; chiếm đóng với số lượng lớn","cố tình tránh xa; xa lánh","sự suy luận; kết luận suy ra","gắng sức; lấy hết (can đảm, sức mạnh)"]'::jsonb, 0, '“overrun” (/ˌoʊvərˈrʌn/): tràn ngập; chiếm đóng với số lượng lớn. Câu đầy đủ: Major infrastructure projects often overrun their budgets when planners underestimate material costs and construction delays.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_50_1', 'en-c1-50', 'We walked along the waterfront after an early dinner', 'Chúng tôi đi dạo dọc theo khu vực bờ sông sau bữa tối sớm.', 'waterfront /ˈwɔːtərfrʌnt/', '["early","along","dinner","We","the","after","waterfront","walked","an"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_50_2', 'en-c1-50', 'Weeds have overrun the garden since our neighbours moved away', 'Khu vườn đã mọc đầy cỏ dại từ khi nhà hàng xóm chuyển đi nơi khác.', 'overrun /ˌoʊvərˈrʌn/', '["the","overrun","Weeds","away","have","our","neighbours","since","moved","garden"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_50_3', 'en-c1-50', 'The previous occupant left some curtains in the flat', 'Người thuê nhà trước đã để lại một số tấm rèm trong căn hộ.', 'occupant /ˈɑːkjəpənt/', '["occupant","left","curtains","in","The","some","flat","previous","the"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_50_4', 'en-c1-50', 'We erected our tent beside the lake before sunset', 'Chúng tôi đã dựng lều bên hồ trước khi mặt trời lặn.', 'erect /ɪˈrekt/', '["our","lake","tent","sunset","erected","before","We","beside","the"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_50_5', 'en-c1-50', 'The new tower dwarfs every house on our street', 'Tòa tháp mới xây khiến mọi ngôi nhà trên phố nhà chúng tôi đều trở nên nhỏ bé.', 'dwarf /dwɔːrf/', '["on","tower","every","dwarfs","The","new","house","street","our"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_50_6', 'en-c1-50', 'Their small dwelling overlooks a quiet stretch of river', 'Ngôi nhà nhỏ của họ hướng ra một khúc sông êm đềm.', 'dwelling /ˈdwelɪŋ/', '["river","overlooks","dwelling","of","a","Their","small","stretch","quiet"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_50_7', 'en-c1-50', 'Workers cleared the blocked sewer beneath our street', 'Các công nhân đã thông cống ngầm bị tắc bên dưới con đường của chúng tôi.', 'sewer /ˈsuːər/', '["cleared","the","sewer","blocked","street","our","Workers","beneath"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_50_8', 'en-c1-50', 'We could barely hear each other above the din', 'Chúng tôi hầu như không thể nghe thấy nhau nói gì giữa tiếng ồn ào đó.', 'din /dɪn/', '["barely","could","the","each","We","other","above","hear","din"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_50_9', 'en-c1-50', 'Our tenancy ends next month, so we are packing', 'Hợp đồng thuê nhà của chúng tôi sẽ kết thúc vào tháng tới, nên chúng tôi đang dọn đồ đạc.', 'tenancy /ˈtenənsi/', '["so","are","ends","Our","month","tenancy","next","packing","we"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_50_10', 'en-c1-50', 'Workers dug a trench to repair the broken pipe', 'Công nhân đã đào một con rãnh để sửa chữa đường ống bị vỡ.', 'trench /trentʃ/', '["dug","broken","trench","a","the","repair","pipe","Workers","to"]'::jsonb, NULL, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
