INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_50_13', 'en-c1-50', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “diversion” (/daɪˈvɝːʒən/) có nghĩa là gì?', '["tràn ngập; chiếm đóng với số lượng lớn","sự phục hồi; sự tái thiết; sự đổi mới đô thị","liền kề; sát cạnh; gần kề","sự đổi hướng đường đi hoặc sự thay đổi mục đích sử dụng của cái gì đó"]'::jsonb, 3, '“diversion” (n.): sự đổi hướng đường đi hoặc sự thay đổi mục đích sử dụng của cái gì đó; điều làm sao lãng sự chú ý khỏi một hoạt động hoặc mối bận tâm khác; hoạt động giải trí thú vị giúp giải tỏa khỏi guồng quay thường ngày.', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
