INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_1', 'en-c1-50', NULL, 'comprehensive_test', 'listening', 'waterfront', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự vội vàng; sự hấp tấp","vùng ven sông hồ; khu vực giáp nước","sẵn sàng và có thể hoạt động hoặc sử dụng được","bước đi dũng mãnh; sải bước"]'::jsonb, 1, 'waterfront (/ˈwɔːtərfrʌnt/) → vùng ven sông hồ; khu vực giáp nước', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_2', 'en-c1-50', NULL, 'comprehensive_test', 'listening', 'Weeds have overrun the garden since our neighbours moved away.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một cành cây gãy gây ra vật cản trên con đường nhỏ hẹp.","Khu vườn đã mọc đầy cỏ dại từ khi nhà hàng xóm chuyển đi nơi khác.","Ngôi nhà cổ này cần được bảo dưỡng định kỳ trong suốt cả năm.","Anh ấy đã thuê một phòng trọ nhỏ gần ga tàu."]'::jsonb, 1, 'Weeds have overrun the garden since our neighbours moved away. → Khu vườn đã mọc đầy cỏ dại từ khi nhà hàng xóm chuyển đi nơi khác.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_3', 'en-c1-50', NULL, 'comprehensive_test', 'listening', 'occupant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người cư ngụ; người sử dụng; hành khách (trên xe)","gợn sóng; sóng lăn tăn","xọc mạch; tọc mạch; dòm ngó chuyện riêng tư","chính trực; đúng đắn về mặt đạo đức"]'::jsonb, 0, 'occupant (/ˈɑːkjəpənt/) → người cư ngụ; người sử dụng; hành khách (trên xe)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_4', 'en-c1-50', NULL, 'comprehensive_test', 'listening', 'We erected our tent beside the lake before sunset.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã dựng lều bên hồ trước khi mặt trời lặn.","Việc đổi hướng giao thông đã dẫn chúng tôi đi qua một hồ nước đẹp.","Giao thông bên ngoài nhà ga hoàn toàn tê liệt.","Mạng lưới đường sắt đô thị của chúng tôi kết nối các vùng ngoại ô với trung tâm thành phố."]'::jsonb, 0, 'We erected our tent beside the lake before sunset. → Chúng tôi đã dựng lều bên hồ trước khi mặt trời lặn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_5', 'en-c1-50', NULL, 'comprehensive_test', 'listening', 'dwarf', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhỏ hơn, ít hơn, kém quan trọng hơn","làm cho lu mờ; làm cho nhỏ bé hẳn đi","khuếch đại âm thanh hoặc tín hiệu điện","ngay lập tức; tức thời"]'::jsonb, 1, 'dwarf (/dwɔːrf/) → làm cho lu mờ; làm cho nhỏ bé hẳn đi; sinh vật lợn cợn nhỏ bé; người lùn trong thần thoại; giống lùn; kích thước nhỏ hơn bình thường', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_6', 'en-c1-50', NULL, 'comprehensive_test', 'listening', 'Their small dwelling overlooks a quiet stretch of river.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hợp đồng thuê nhà của chúng tôi sẽ kết thúc vào tháng tới, nên chúng tôi đang dọn đồ đạc.","Một cành cây gãy gây ra vật cản trên con đường nhỏ hẹp.","Ngôi nhà nhỏ của họ hướng ra một khúc sông êm đềm.","Sau chuyến đi bộ đường dài, chúng tôi nằm duỗi dài trên bãi cỏ mềm mại."]'::jsonb, 2, 'Their small dwelling overlooks a quiet stretch of river. → Ngôi nhà nhỏ của họ hướng ra một khúc sông êm đềm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_7', 'en-c1-50', NULL, 'comprehensive_test', 'listening', 'sewer', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cống ngầm; đường ống thoát nước","khó hoặc không thể tiếp cận, tới gần hoặc bước vào","hình thành ý tưởng; tưởng tượng","tuân thủ; tôn trọng"]'::jsonb, 0, 'sewer (/ˈsuːər/) → cống ngầm; đường ống thoát nước', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_8', 'en-c1-50', NULL, 'comprehensive_test', 'listening', 'We could barely hear each other above the din.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Các công nhân đã thông cống ngầm bị tắc bên dưới con đường của chúng tôi.","Chúng tôi đi bộ dọc theo con đê bên dòng sông đang dâng nước.","Chúng tôi hầu như không thể nghe thấy nhau nói gì giữa tiếng ồn ào đó.","Công nhân đã đào một con rãnh để sửa chữa đường ống bị vỡ."]'::jsonb, 2, 'We could barely hear each other above the din. → Chúng tôi hầu như không thể nghe thấy nhau nói gì giữa tiếng ồn ào đó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_9', 'en-c1-50', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To make something seem small by comparison.”?', '["waterfront","dwarf","adjacent","dwelling"]'::jsonb, 1, 'dwarf (/dwɔːrf/) → làm cho lu mờ; làm cho nhỏ bé hẳn đi', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_10', 'en-c1-50', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A house, flat, or other place where someone lives”?', '["standstill","diversion","dwelling","embankment"]'::jsonb, 2, 'dwelling (/ˈdwelɪŋ/) → nơi ở; chốn ở; nhà cửa', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_11', 'en-c1-50', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An underground pipe that carries away sewage and wastewater”?', '["sewer","overrun","metropolitan","dwarf"]'::jsonb, 0, 'sewer (/ˈsuːər/) → cống ngầm; đường ống thoát nước', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_12', 'en-c1-50', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A loud, unpleasant mixture of continuing noises.”?', '["diversion","occupant","regeneration","din"]'::jsonb, 3, 'din (/dɪn/) → tiếng ồn ào; tiếng náo động kéo dài khó chịu', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_13', 'en-c1-50', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The legal right or arrangement to occupy rented property.”?', '["overrun","metropolitan","tenancy","waterfront"]'::jsonb, 2, 'tenancy (/ˈtenənsi/) → quyền thuê nhà; thỏa thuận thuê tài sản', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
