INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_18', 'en-c1-50', NULL, 'comprehensive_test', 'reading', NULL, 'Redeveloping the waterfront can create attractive public spaces, provided that existing residents are not forced to leave.', 'Dựa vào câu trên, từ “waterfront” có nghĩa phù hợp nhất là gì?', '["dầu hỏa; dầu hôi","không đối xứng","trung úy (lục quân); đại úy (hải quân); sĩ quan cấp dưới","vùng ven sông hồ; khu vực giáp nước"]'::jsonb, 3, 'waterfront: vùng ven sông hồ; khu vực giáp nước. Dịch cả câu: Việc tái phát triển khu vực ven sông có thể tạo ra các không gian công cộng hấp dẫn, với điều kiện là cư dân hiện tại không bị buộc phải di dời.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_19', 'en-c1-50', NULL, 'comprehensive_test', 'reading', NULL, 'Major infrastructure projects often overrun their budgets when planners underestimate material costs and construction delays.', 'Dựa vào câu trên, từ “overrun” có nghĩa phù hợp nhất là gì?', '["vĩnh cửu; đời đời; kéo dài mãi mãi","hòa quyện; trộn lẫn","tác nhân thúc đẩy; người hoặc vật gây ra thay đổi","tràn ngập; chiếm đóng với số lượng lớn"]'::jsonb, 3, 'overrun: tràn ngập; chiếm đóng với số lượng lớn; vượt quá (thời gian hoặc chi phí); khoảng thời gian hoặc chi phí vượt mức. Dịch cả câu: Các dự án cơ sở hạ tầng lớn thường bị vượt ngân sách khi các nhà quy hoạch đánh giá thấp chi phí vật liệu và sự chậm trễ trong thi công.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_20', 'en-c1-50', NULL, 'comprehensive_test', 'reading', NULL, 'Building regulations should ensure that every occupant can leave safely in the event of a fire.', 'Dựa vào câu trên, từ “occupant” có nghĩa phù hợp nhất là gì?', '["làm cho phổ biến; truyền bá; phổ biến","thao túng; lôi kéo trục lợi","chiếc nôi; cái nôi em bé","người cư ngụ; người sử dụng; hành khách (trên xe)"]'::jsonb, 3, 'occupant: người cư ngụ; người sử dụng; hành khách (trên xe). Dịch cả câu: Các quy định xây dựng phải đảm bảo rằng mọi người ở trong tòa nhà có thể sơ tán an toàn trong trường hợp xảy ra hỏa hoạn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_21', 'en-c1-50', NULL, 'comprehensive_test', 'reading', NULL, 'Local authorities plan to erect temporary shelters for families whose homes were damaged by severe flooding.', 'Dựa vào câu trên, từ “erect” có nghĩa phù hợp nhất là gì?', '["sự phân hạch; sự tách hạt nhân nguyên tử","xây dựng; dựng lên","chuyển động lặp đi lặp lại qua lại; dao động","đồ vật được làm từ một vật liệu cụ thể hoặc dùng cho một mục đích cụ thể; đồ gốm"]'::jsonb, 1, 'erect: xây dựng; dựng lên; thẳng đứng; đứng thẳng. Dịch cả câu: Chính quyền địa phương dự định dựng các khu nhà tạm cho các gia đình có nhà cửa bị tàn phá bởi trận lũ lụt nghiêm trọng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_22', 'en-c1-50', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khu phố đi bộ mua sắm”', '["fanatic","truant","flourish","precinct"]'::jsonb, 3, 'khu phố đi bộ mua sắm → precinct (/ˈpriːsɪŋkt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_23', 'en-c1-50', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giáp ranh; liền kề; nối liền”', '["clearance","plasma","adjoin","outcast"]'::jsonb, 2, 'giáp ranh; liền kề; nối liền → adjoin (/əˈdʒɔɪn/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_50_24', 'en-c1-50', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phòng trọ kiêm phòng ngủ và phòng khách”', '["quay","allude","bedsit","truant"]'::jsonb, 2, 'phòng trọ kiêm phòng ngủ và phòng khách → bedsit (/ˈbedsɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-51', 'en', 'Bài 51: Công nghệ & Kỹ thuật (1) - CEFR C1', 'CEFR C1', 'C1 · Công nghệ', '21 từ vựng Tiếng Anh CEFR C1 chủ đề công nghệ & kỹ thuật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5051, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_specification', 'en-c1-51', 'specification', '/ˌspesɪfɪˈkeɪʃən/', 'C1', 'bản thông số kỹ thuật; quy cách kỹ thuật', 'n.', 'specify (v.), specific (adj.), specifically (adv.)', NULL, 'Khi nói về các thông số của sản phẩm, thường dùng dạng số nhiều specifications, có thể viết tắt là specs.', 'Check the specifications before buying a new laptop.', NULL, 'Hãy kiểm tra các thông số kỹ thuật trước khi mua một chiếc máy tính xách tay mới.', '{"wordId":"specification","ukIpa":"/ˌspesɪfɪˈkeɪʃən/","usIpa":"/ˌspesɪfɪˈkeɪʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"A detailed description of how something must be designed or made.","vi":"bản thông số kỹ thuật; quy cách kỹ thuật"}],"examples":[{"en":"Check the specifications before buying a new laptop.","vi":"Hãy kiểm tra các thông số kỹ thuật trước khi mua một chiếc máy tính xách tay mới.","audioKind":"ex"},{"en":"Clear building specifications help ensure that new housing meets safety standards and uses energy efficiently.","vi":"Các yêu cầu kỹ thuật xây dựng rõ ràng giúp đảm bảo nhà ở mới đáp ứng các tiêu chuẩn an toàn và sử dụng năng lượng hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"technical specifications","vi":"thông số kỹ thuật"},{"en":"meet specifications","vi":"đáp ứng các thông số kỹ thuật"},{"en":"design specification","vi":"yêu cầu thiết kế"},{"en":"to specification","vi":"đúng theo quy cách"}],"wordFamily":["specify (v.)","specific (adj.)","specifically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về các thông số của sản phẩm, thường dùng dạng số nhiều specifications, có thể viết tắt là specs.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alignment', 'en-c1-51', 'alignment', '/əˈlaɪnmənt/', 'C1', 'sự sắp thẳng hàng; sự căn chỉnh đúng vị trí; sự thống nhất (giữa các ý tưởng, mục tiêu hoặc hành động); sự liên minh, khối liên kết (giữa các nhóm có chung mục tiêu hoặc lợi ích chính trị)', 'n.', 'align (v.), aligned (adj.), misalignment (n.)', NULL, '"In alignment with" có thể chỉ vị trí thẳng hàng hoặc sự thống nhất về mục tiêu.', 'The mechanic checked the alignment of my front wheels.', NULL, 'Thợ máy đã kiểm tra độ chụm của các bánh trước xe của tôi.', '{"wordId":"alignment","ukIpa":"/əˈlaɪnmənt/","usIpa":"/əˈlaɪnmənt/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"The arrangement of objects in a straight line or correct position.","vi":"sự sắp thẳng hàng; sự căn chỉnh đúng vị trí"},{"pos":"n.","en":"Agreement between ideas, aims, or actions.","vi":"sự thống nhất (giữa các ý tưởng, mục tiêu hoặc hành động)"},{"pos":"n.","en":"An association between groups sharing political aims or interests.","vi":"sự liên minh, khối liên kết (giữa các nhóm có chung mục tiêu hoặc lợi ích chính trị)"}],"examples":[{"en":"The mechanic checked the alignment of my front wheels.","vi":"Thợ máy đã kiểm tra độ chụm của các bánh trước xe của tôi.","audioKind":"ex"},{"en":"Closer alignment between school curricula and workplace needs could improve employment prospects for young graduates.","vi":"Sự đồng bộ chặt chẽ hơn giữa chương trình giảng dạy ở trường và nhu cầu của thị trường lao động có thể cải thiện triển vọng việc làm cho các cử nhân trẻ.","audioKind":"ex2"}],"collocations":[{"en":"wheel alignment","vi":"cân chỉnh bánh xe"},{"en":"in alignment with","vi":"phù hợp với; thống nhất với"},{"en":"political alignment","vi":"liên minh chính trị"}],"wordFamily":["align (v.)","aligned (adj.)","misalignment (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"In alignment with\" có thể chỉ vị trí thẳng hàng hoặc sự thống nhất về mục tiêu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instantaneous', 'en-c1-51', 'instantaneous', '/ˌɪnstənˈteɪniəs/', 'C1', 'ngay lập tức; tức thời', 'adj.', 'instantaneously (adv.), instant (n.), instantly (adv.)', 'Đồng nghĩa: immediate, instant · Trái nghĩa: delayed, gradual', 'Nhấn mạnh hầu như không có khoảng thời gian trễ, không đồng nghĩa với việc xảy ra đồng thời.', 'The relief was almost instantaneous when I removed my shoes.', NULL, 'Cảm giác nhẹ nhõm đến gần như ngay lập tức khi tôi cởi giày ra.', '{"wordId":"instantaneous","ukIpa":"/ˌɪnstənˈteɪniəs/","usIpa":"/ˌɪnstənˈteɪniəs/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"Happening immediately, with no noticeable delay.","vi":"ngay lập tức; tức thời"}],"examples":[{"en":"The relief was almost instantaneous when I removed my shoes.","vi":"Cảm giác nhẹ nhõm đến gần như ngay lập tức khi tôi cởi giày ra.","audioKind":"ex"},{"en":"Modern communication networks allow almost instantaneous exchanges of information between researchers working on different continents.","vi":"Các mạng lưới truyền thông hiện đại cho phép các nhà nghiên cứu làm việc ở các châu lục khác nhau trao đổi thông tin gần như tức thời.","audioKind":"ex2"}],"collocations":[{"en":"an instantaneous response","vi":"phản ứng tức thời"},{"en":"instantaneous communication","vi":"truyền thông tức thời"},{"en":"almost instantaneous","vi":"gần như ngay lập tức"}],"wordFamily":["instantaneously (adv.)","instant (n.)","instantly (adv.)"],"synonyms":["immediate","instant"],"antonyms":["delayed","gradual"],"tipVi":"Nhấn mạnh hầu như không có khoảng thời gian trễ, không đồng nghĩa với việc xảy ra đồng thời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_auxiliary', 'en-c1-51', 'auxiliary', '/ɔːɡˈzɪljəri/', 'C1', 'phụ; dự phòng; bổ trợ; thừa nhận', 'adj.', NULL, 'Đồng nghĩa: supplementary, additional · Trái nghĩa: primary', 'Trong ngữ pháp, auxiliary verb chỉ trợ động từ, như be, have, do.', 'The boat has an auxiliary engine for emergencies.', NULL, 'Con thuyền được trang bị một động cơ dự phòng để dùng trong các trường hợp khẩn cấp.', '{"wordId":"auxiliary","ukIpa":"/ɔːɡˈzɪliəri/","usIpa":"/ɔːɡˈzɪljəri/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"providing extra help or support when needed","vi":"phụ; dự phòng; bổ trợ"},{"pos":"n.","en":"a verb used with another verb to form grammatical structures","vi":"thừa nhận"}],"examples":[{"en":"The boat has an auxiliary engine for emergencies.","vi":"Con thuyền được trang bị một động cơ dự phòng để dùng trong các trường hợp khẩn cấp.","audioKind":"ex"},{"en":"Hospitals require auxiliary power systems to maintain essential medical services during unexpected electricity failures.","vi":"Các bệnh viện yêu cầu hệ thống cung cấp điện dự phòng để duy trì các dịch vụ y tế thiết yếu trong trường hợp mất điện bất ngờ.","audioKind":"ex2"}],"collocations":[{"en":"auxiliary power","vi":"nguồn điện dự phòng"},{"en":"auxiliary engine","vi":"động cơ dự phòng"},{"en":"auxiliary verb","vi":"trợ động từ"}],"wordFamily":[],"synonyms":["supplementary","additional"],"antonyms":["primary"],"tipVi":"Trong ngữ pháp, auxiliary verb chỉ trợ động từ, như be, have, do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_semiconductor', 'en-c1-51', 'semiconductor', '/ˌsemikənˈdʌktər/', 'C1', 'vật liệu bán dẫn', 'n.', 'semiconducting (adj.), semiconduction (n.)', NULL, 'Tiền tố semi- có nghĩa là một nửa; chất bán dẫn có độ dẫn điện nằm giữa chất dẫn điện và chất cách điện.', 'My sister works at a factory making semiconductor chips.', NULL, 'Chị gái tôi làm việc tại một nhà máy sản xuất chip bán dẫn.', '{"wordId":"semiconductor","ukIpa":"/ˌsemikənˈdʌktə/","usIpa":"/ˌsemikənˈdʌktər/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"A material that conducts electricity less easily than most metals.","vi":"vật liệu bán dẫn"}],"examples":[{"en":"My sister works at a factory making semiconductor chips.","vi":"Chị gái tôi làm việc tại một nhà máy sản xuất chip bán dẫn.","audioKind":"ex"},{"en":"Investment in semiconductor manufacturing is essential for developing reliable supplies of components used in modern electronic devices.","vi":"Đầu tư vào ngành sản xuất chất bán dẫn là điều cốt yếu để đảm bảo nguồn cung ổn định các linh kiện dùng trong các thiết bị điện tử hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"semiconductor chips","vi":"chip bán dẫn"},{"en":"semiconductor manufacturing","vi":"sản xuất chất bán dẫn"},{"en":"the semiconductor industry","vi":"ngành công nghiệp bán dẫn"}],"wordFamily":["semiconducting (adj.)","semiconduction (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiền tố semi- có nghĩa là một nửa; chất bán dẫn có độ dẫn điện nằm giữa chất dẫn điện và chất cách điện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_array', 'en-c1-51', 'array', '/əˈreɪ/', 'C1', 'một loạt; một mảng lớn (nhiều thứ khác nhau); dãy; mảng (sự sắp xếp trật tự của các đối tượng hoặc dữ liệu); sắp xếp; trưng bày (theo một trật tự hoặc hình mẫu nhất định)', 'n.', NULL, 'Đồng nghĩa: range, assortment', 'Thường gặp cụm a wide array of, nhấn mạnh số lượng lớn và phong phú.', 'The bakery displayed a colourful array of cakes.', NULL, 'Tiệm bánh trưng bày rất nhiều loại bánh ngọt rực rỡ sắc màu.', '{"wordId":"array","ukIpa":"/əˈreɪ/","usIpa":"/əˈreɪ/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"a large collection of different things","vi":"một loạt; một mảng lớn (nhiều thứ khác nhau)"},{"pos":"n.","en":"an ordered arrangement of objects or data","vi":"dãy; mảng (sự sắp xếp trật tự của các đối tượng hoặc dữ liệu)"},{"pos":"v.","en":"to arrange things in a particular order or pattern","vi":"sắp xếp; trưng bày (theo một trật tự hoặc hình mẫu nhất định)"}],"examples":[{"en":"The bakery displayed a colourful array of cakes.","vi":"Tiệm bánh trưng bày rất nhiều loại bánh ngọt rực rỡ sắc màu.","audioKind":"ex"},{"en":"Modern universities offer a wide array of courses to meet the demands of a changing labour market.","vi":"Các trường đại học hiện đại cung cấp vô số các khóa học đa dạng nhằm đáp ứng nhu cầu của thị trường lao động đang đổi thay.","audioKind":"ex2"}],"collocations":[{"en":"a wide array of","vi":"nhiều loại đa dạng"},{"en":"an impressive array of","vi":"một loạt ấn tượng"},{"en":"a solar array","vi":"dãy pin mặt trời"},{"en":"a data array","vi":"mảng dữ liệu"}],"wordFamily":[],"synonyms":["range","assortment"],"antonyms":[],"tipVi":"Thường gặp cụm a wide array of, nhấn mạnh số lượng lớn và phong phú.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compute', 'en-c1-51', 'compute', '/kəmˈpjuːt/', 'C1', 'tính toán', 'v.', 'computer (n.), computation (n.), computational (adj.), computing (n.)', 'Đồng nghĩa: calculate', 'Trang trọng hơn từ calculate, thường dùng trong ngữ cảnh khoa học máy tính hoặc toán học.', 'This app computes the cost of our weekly shopping.', NULL, 'Ứng dụng này tính toán chi phí mua sắm hằng tuần của chúng tôi.', '{"wordId":"compute","ukIpa":"/kəmˈpjuːt/","usIpa":"/kəmˈpjuːt/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"To calculate an amount or result, often using a computer.","vi":"tính toán"}],"examples":[{"en":"This app computes the cost of our weekly shopping.","vi":"Ứng dụng này tính toán chi phí mua sắm hằng tuần của chúng tôi.","audioKind":"ex"},{"en":"Researchers compute average temperatures from satellite data to assess long-term changes in the global climate.","vi":"Các nhà nghiên cứu tính toán nhiệt độ trung bình từ dữ liệu vệ tinh để đánh giá những biến đổi dài hạn của khí hậu toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"compute the cost","vi":"tính chi phí"},{"en":"compute an average","vi":"tính giá trị trung bình"},{"en":"compute a value","vi":"tính toán một giá trị"}],"wordFamily":["computer (n.)","computation (n.)","computational (adj.)","computing (n.)"],"synonyms":["calculate"],"antonyms":[],"tipVi":"Trang trọng hơn từ calculate, thường dùng trong ngữ cảnh khoa học máy tính hoặc toán học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dimensional', 'en-c1-51', 'dimensional', '/daɪˈmenʃənəl/', 'C1', 'thuộc về kích thước; thuộc chiều không gian', 'adj.', 'dimension (n.), dimensionally (adv.)', NULL, 'Thường gặp trong từ ghép three-dimensional, có nghĩa là ba chiều.', 'The carpenter checked the dimensional accuracy of each shelf.', NULL, 'Thợ mộc đã kiểm tra độ chính xác về kích thước của từng chiếc kệ.', '{"wordId":"dimensional","ukIpa":"/daɪˈmenʃənəl/","usIpa":"/daɪˈmenʃənəl/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"relating to measurements or dimensions of space","vi":"thuộc về kích thước; thuộc chiều không gian"}],"examples":[{"en":"The carpenter checked the dimensional accuracy of each shelf.","vi":"Thợ mộc đã kiểm tra độ chính xác về kích thước của từng chiếc kệ.","audioKind":"ex"},{"en":"Dimensional accuracy is essential when manufacturing components that must fit together safely in complex machines.","vi":"Độ chính xác về kích thước là yếu tố cốt lõi khi sản xuất các bộ phận phải lắp ráp khít với nhau một cách an toàn trong các cỗ máy phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"dimensional accuracy","vi":"độ chính xác về kích thước"},{"en":"dimensional stability","vi":"độ ổn định kích thước"},{"en":"three-dimensional model","vi":"mô hình ba chiều"}],"wordFamily":["dimension (n.)","dimensionally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường gặp trong từ ghép three-dimensional, có nghĩa là ba chiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_telecommunication', 'en-c1-51', 'telecommunication', '/ˌtelikəˌmjuːnɪˈkeɪʃən/', 'C1', 'viễn thông; thông tin liên lạc từ xa', 'n.', 'telecommunications (n.)', NULL, 'Khi nói về ngành nghề hoặc kỹ thuật viễn thông, người ta thường dùng số nhiều telecommunications.', 'Telecommunication keeps our family connected despite the ocean between us.', NULL, 'Công nghệ viễn thông giúp gia đình chúng tôi gắn kết dù cách trở đại dương.', '{"wordId":"telecommunication","ukIpa":"/ˌtelikəˌmjuːnɪˈkeɪʃən/","usIpa":"/ˌtelikəˌmjuːnɪˈkeɪʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"Communication over a distance using electronic signals.","vi":"viễn thông; thông tin liên lạc từ xa"}],"examples":[{"en":"Telecommunication keeps our family connected despite the ocean between us.","vi":"Công nghệ viễn thông giúp gia đình chúng tôi gắn kết dù cách trở đại dương.","audioKind":"ex"},{"en":"Investment in telecommunication infrastructure can improve rural access to education, healthcare, and employment opportunities.","vi":"Việc đầu tư vào cơ sở hạ tầng viễn thông có thể cải thiện khả năng tiếp cận giáo dục, y tế và cơ hội việc làm ở các vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"telecommunication networks","vi":"mạng lưới viễn thông"},{"en":"telecommunication infrastructure","vi":"cơ sở hạ tầng viễn thông"},{"en":"telecommunication services","vi":"dịch vụ viễn thông"}],"wordFamily":["telecommunications (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về ngành nghề hoặc kỹ thuật viễn thông, người ta thường dùng số nhiều telecommunications.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transmission', 'en-c1-51', 'transmission', '/trænzˈmɪʃən/', 'C1', 'sự truyền tải; sự lan truyền; sự phát sóng (radio hoặc truyền hình); hệ thống truyền động (của xe ô tô)', 'n.', 'transmit (v.), transmitter (n.), transmissible (adj.)', NULL, 'Động từ tương ứng là "transmit"; dạng quá khứ "transmitted" được gấp đôi chữ t.', 'The mechanic checked the transmission before our long drive.', NULL, 'Thợ máy đã kiểm tra hệ thống truyền động trước chuyến đi dài của chúng tôi.', '{"wordId":"transmission","ukIpa":"/trænzˈmɪʃən/","usIpa":"/trænzˈmɪʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"The process of passing something from one place to another.","vi":"sự truyền tải; sự lan truyền"},{"pos":"n.","en":"The broadcasting of radio or television signals or programmes.","vi":"sự phát sóng (radio hoặc truyền hình)"},{"pos":"n.","en":"The system transferring engine power to a vehicle''s wheels.","vi":"hệ thống truyền động (của xe ô tô)"}],"examples":[{"en":"The mechanic checked the transmission before our long drive.","vi":"Thợ máy đã kiểm tra hệ thống truyền động trước chuyến đi dài của chúng tôi.","audioKind":"ex"},{"en":"Improved ventilation in public buildings can reduce the transmission of certain infections and protect vulnerable people.","vi":"Hệ thống thông gió được cải thiện ở các tòa nhà công cộng có thể làm giảm sự lây truyền của một số bệnh truyền nhiễm và bảo vệ những nhóm người dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"data transmission","vi":"truyền dữ liệu"},{"en":"disease transmission","vi":"sự lây truyền dịch bệnh"},{"en":"live transmission","vi":"phát sóng trực tiếp"},{"en":"automatic transmission","vi":"hộp số tự động"}],"wordFamily":["transmit (v.)","transmitter (n.)","transmissible (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ tương ứng là \"transmit\"; dạng quá khứ \"transmitted\" được gấp đôi chữ t.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compile', 'en-c1-51', 'compile', '/kəmˈpaɪl/', 'C1', 'thu thập và tổng hợp thông tin từ nhiều nguồn khác nhau; biên soạn; biên dịch mã máy tính', 'v.', 'compilation (n.), compiler (n.)', 'Đồng nghĩa: collect, assemble', 'Nhấn mạnh việc thu thập thông tin từ các nguồn khác nhau rồi sắp xếp lại, không chỉ đơn thuần là viết.', 'We compiled a playlist for our long train journey.', NULL, 'Chúng tôi đã lập một danh sách bài hát cho chuyến đi tàu dài ngày.', '{"wordId":"compile","ukIpa":"/kəmˈpaɪl/","usIpa":"/kəmˈpaɪl/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"Collect information from different sources and arrange it together.","vi":"thu thập và tổng hợp thông tin từ nhiều nguồn khác nhau; biên soạn"},{"pos":"v.","en":"Convert computer code into a form a computer can run.","vi":"biên dịch mã máy tính"}],"examples":[{"en":"We compiled a playlist for our long train journey.","vi":"Chúng tôi đã lập một danh sách bài hát cho chuyến đi tàu dài ngày.","audioKind":"ex"},{"en":"Researchers compiled data from several hospitals to examine the relationship between air pollution and childhood asthma.","vi":"Các nhà nghiên cứu đã tổng hợp dữ liệu từ nhiều bệnh viện để khảo sát mối liên hệ giữa ô nhiễm không khí và bệnh hen suyễn ở trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"compile a report","vi":"soạn thảo báo cáo"},{"en":"compile data","vi":"tổng hợp dữ liệu"},{"en":"compile a list","vi":"lập danh sách"},{"en":"compile code","vi":"biên dịch mã nguồn"}],"wordFamily":["compilation (n.)","compiler (n.)"],"synonyms":["collect","assemble"],"antonyms":[],"tipVi":"Nhấn mạnh việc thu thập thông tin từ các nguồn khác nhau rồi sắp xếp lại, không chỉ đơn thuần là viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_render', 'en-c1-51', 'render', '/ˈrendər/', 'C1', 'làm cho ai/cái gì rơi vào trạng thái nào đó; cung cấp, đem lại (sự giúp đỡ, dịch vụ); thể hiện, miêu tả dưới hình thức nghệ thuật', 'v.', 'rendering (n.)', NULL, 'Biểu đạt nghĩa "làm cho..." thường dùng render + tân ngữ + tính từ, văn phong trang trọng.', 'A cracked screen rendered my old phone unusable.', NULL, 'Màn hình nứt vỡ khiến chiếc điện thoại cũ của tôi không thể dùng được nữa.', '{"wordId":"render","ukIpa":"/ˈrendə/","usIpa":"/ˈrendər/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"to cause someone or something to enter a particular state","vi":"làm cho ai/cái gì rơi vào trạng thái nào đó"},{"pos":"v.","en":"to provide help, a service, or something needed","vi":"cung cấp, đem lại (sự giúp đỡ, dịch vụ)"},{"pos":"v.","en":"to represent something in artistic or visual form","vi":"thể hiện, miêu tả dưới hình thức nghệ thuật"}],"examples":[{"en":"A cracked screen rendered my old phone unusable.","vi":"Màn hình nứt vỡ khiến chiếc điện thoại cũ của tôi không thể dùng được nữa.","audioKind":"ex"},{"en":"Rising sea levels could render some coastal settlements uninhabitable unless governments invest in effective flood protection.","vi":"Mực nước biển dâng cao có thể khiến một số khu dân cư ven biển không thể sinh sống được nữa trừ khi chính phủ đầu tư vào các biện pháp chống lụt hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"render something useless","vi":"làm cho cái gì mất tác dụng"},{"en":"render assistance","vi":"cung cấp sự hỗ trợ"},{"en":"render services","vi":"cung cấp dịch vụ"},{"en":"render an image","vi":"kết xuất hình ảnh"}],"wordFamily":["rendering (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Biểu đạt nghĩa \"làm cho...\" thường dùng render + tân ngữ + tính từ, văn phong trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_simulate', 'en-c1-51', 'simulate', '/ˈsɪmjəleɪt/', 'C1', 'mô phỏng; giả vờ; ra vẻ', 'v.', 'simulation (n.), simulator (n.), simulated (adj.)', 'Đồng nghĩa: imitate, replicate', 'Dùng simulate khi nói về việc mô phỏng môi trường hoặc tình huống; dùng stimulate khi nói về việc kích thích sự phát triển.', 'This driving game simulates icy roads surprisingly well.', NULL, 'Trò chơi lái xe này mô phỏng những con đường đóng băng một cách chân thực đến bất ngờ.', '{"wordId":"simulate","ukIpa":"/ˈsɪmjuleɪt/","usIpa":"/ˈsɪmjəleɪt/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"To reproduce conditions or processes for testing, training, or study.","vi":"mô phỏng"},{"pos":"v.","en":"To pretend to have a feeling or condition.","vi":"giả vờ; ra vẻ"}],"examples":[{"en":"This driving game simulates icy roads surprisingly well.","vi":"Trò chơi lái xe này mô phỏng những con đường đóng băng một cách chân thực đến bất ngờ.","audioKind":"ex"},{"en":"Researchers simulate extreme weather conditions to assess how new building materials perform under environmental stress.","vi":"Các nhà nghiên cứu mô phỏng các điều kiện thời tiết khắc nghiệt để đánh giá hiệu suất của vật liệu xây dựng mới dưới áp lực môi trường.","audioKind":"ex2"}],"collocations":[{"en":"simulate conditions","vi":"mô phỏng các điều kiện"},{"en":"simulate an emergency","vi":"mô phỏng tình huống khẩn cấp"},{"en":"simulate the effects of","vi":"mô phỏng hiệu ứng của"}],"wordFamily":["simulation (n.)","simulator (n.)","simulated (adj.)"],"synonyms":["imitate","replicate"],"antonyms":[],"tipVi":"Dùng simulate khi nói về việc mô phỏng môi trường hoặc tình huống; dùng stimulate khi nói về việc kích thích sự phát triển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amplification', 'en-c1-51', 'amplification', '/ˌæmplɪfɪˈkeɪʃən/', 'C1', 'sự khuếch đại (âm thanh hoặc tín hiệu); sự phóng đại; sự làm tăng thêm (về mức độ hoặc hiệu ứng)', 'n.', 'amplify (v.), amplifier (n.)', NULL, 'Thường dùng để chỉ việc tăng cường âm thanh, tín hiệu, hoặc cũng có thể dùng cho việc làm gia tăng sức ảnh hưởng.', 'Without amplification, nobody could hear the singer outside.', NULL, 'Nếu không có thiết bị khuếch đại, không ai có thể nghe thấy giọng ca sĩ ở bên ngoài.', '{"wordId":"amplification","ukIpa":"/ˌæmplɪfɪˈkeɪʃən/","usIpa":"/ˌæmplɪfɪˈkeɪʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"the process of making a sound or signal stronger","vi":"sự khuếch đại (âm thanh hoặc tín hiệu)"},{"pos":"n.","en":"an increase in the strength or effect of something","vi":"sự phóng đại; sự làm tăng thêm (về mức độ hoặc hiệu ứng)"}],"examples":[{"en":"Without amplification, nobody could hear the singer outside.","vi":"Nếu không có thiết bị khuếch đại, không ai có thể nghe thấy giọng ca sĩ ở bên ngoài.","audioKind":"ex"},{"en":"The amplification of misleading claims through social media can undermine public trust in scientific research.","vi":"Việc khuếch đại các thông tin sai lệch qua mạng xã hội có thể làm suy yếu niềm tin của công chúng vào nghiên cứu khoa học.","audioKind":"ex2"}],"collocations":[{"en":"sound amplification","vi":"khuếch đại âm thanh"},{"en":"signal amplification","vi":"khuếch đại tín hiệu"},{"en":"amplification equipment","vi":"thiết bị khuếch đại âm thanh"}],"wordFamily":["amplify (v.)","amplifier (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng để chỉ việc tăng cường âm thanh, tín hiệu, hoặc cũng có thể dùng cho việc làm gia tăng sức ảnh hưởng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supersede', 'en-c1-51', 'supersede', '/ˌsuːpɚˈsiːd/', 'C1', 'thay thế; thế chỗ', 'v.', NULL, 'Đồng nghĩa: replace, supplant, displace', 'Chú ý phần đuôi viết là -sede, không phải -cede; thường dùng ở thể bị động.', 'This new timetable supersedes the one on our fridge.', NULL, 'Thời biểu mới này thay thế cho bản dán trên tủ lạnh nhà chúng ta.', '{"wordId":"supersede","ukIpa":"/ˌsuːpəˈsiːd/","usIpa":"/ˌsuːpɚˈsiːd/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"To replace something older or no longer useful.","vi":"thay thế; thế chỗ"}],"examples":[{"en":"This new timetable supersedes the one on our fridge.","vi":"Thời biểu mới này thay thế cho bản dán trên tủ lạnh nhà chúng ta.","audioKind":"ex"},{"en":"Digital payment systems may eventually supersede cash in many settings, although accessibility concerns must first be addressed.","vi":"Hệ thống thanh toán kỹ thuật số cuối cùng có thể thay thế tiền mặt trong nhiều trường hợp, mặc dù trước tiên cần giải quyết các vấn đề về khả năng tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"supersede existing rules","vi":"thay thế các quy tắc hiện hành"},{"en":"be superseded by","vi":"bị thay thế bởi"},{"en":"supersede earlier versions","vi":"thay thế các phiên bản trước"}],"wordFamily":[],"synonyms":["replace","supplant","displace"],"antonyms":[],"tipVi":"Chú ý phần đuôi viết là -sede, không phải -cede; thường dùng ở thể bị động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_propulsion', 'en-c1-51', 'propulsion', '/prəˈpʌlʃən/', 'C1', 'lực đẩy; hệ thống đẩy', 'n.', 'propel (v.), propeller (n.), propulsive (adj.)', NULL, 'Thường là danh từ không đếm được, hay dùng cho tàu thuyền, máy bay và tàu vũ trụ.', 'This small boat relies on electric propulsion to move quietly.', NULL, 'Chiếc thuyền nhỏ này dựa vào hệ thống đẩy điện để di chuyển một cách êm ái.', '{"wordId":"propulsion","ukIpa":"/prəˈpʌlʃən/","usIpa":"/prəˈpʌlʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"The force or process that moves something forward","vi":"lực đẩy; hệ thống đẩy"}],"examples":[{"en":"This small boat relies on electric propulsion to move quietly.","vi":"Chiếc thuyền nhỏ này dựa vào hệ thống đẩy điện để di chuyển một cách êm ái.","audioKind":"ex"},{"en":"Advances in electric propulsion could reduce both noise pollution and fuel consumption in coastal shipping.","vi":"Những tiến bộ trong công nghệ đẩy điện có thể giúp giảm cả ô nhiễm tiếng ồn lẫn lượng tiêu thụ nhiên liệu trong ngành vận tải biển ven bờ.","audioKind":"ex2"}],"collocations":[{"en":"propulsion system","vi":"hệ thống đẩy"},{"en":"electric propulsion","vi":"hệ thống đẩy điện"},{"en":"jet propulsion","vi":"lực đẩy phản lực"}],"wordFamily":["propel (v.)","propeller (n.)","propulsive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được, hay dùng cho tàu thuyền, máy bay và tàu vũ trụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rig', 'en-c1-51', 'rig', '/rɪɡ/', 'C1', 'giàn khoan; thiết bị khoan; thao túng; gian lận; lắp ráp; trang bị', 'n.', 'rigging (n.), rigged (adj.)', NULL, 'Rig khi là động từ có thể chỉ việc lắp ráp hoặc gian lận thao túng; cần chú ý ngữ cảnh.', 'We could see an oil rig from the beach.', NULL, 'Chúng tôi có thể nhìn thấy một giàn khoan dầu từ bãi biển.', '{"wordId":"rig","ukIpa":"/rɪɡ/","usIpa":"/rɪɡ/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"a large structure or machine used for drilling","vi":"giàn khoan; thiết bị khoan"},{"pos":"v.","en":"to dishonestly arrange a process to obtain a desired result","vi":"thao túng; gian lận"},{"pos":"v.","en":"to fit equipment into place for use","vi":"lắp ráp; trang bị"}],"examples":[{"en":"We could see an oil rig from the beach.","vi":"Chúng tôi có thể nhìn thấy một giàn khoan dầu từ bãi biển.","audioKind":"ex"},{"en":"Independent observers can help prevent powerful groups from attempting to rig elections in their favour.","vi":"Các quan sát viên độc lập có thể giúp ngăn chặn các nhóm có thế lực mưu toan thao túng bầu cử theo hướng có lợi cho họ.","audioKind":"ex2"}],"collocations":[{"en":"an oil rig","vi":"giàn khoan dầu"},{"en":"a drilling rig","vi":"thiết bị khoan"},{"en":"rig an election","vi":"thao túng cuộc bầu cử"},{"en":"rig up equipment","vi":"lắp đặt thiết bị tạm thời"}],"wordFamily":["rigging (n.)","rigged (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Rig khi là động từ có thể chỉ việc lắp ráp hoặc gian lận thao túng; cần chú ý ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advent', 'en-c1-51', 'advent', '/ˈædvent/', 'C1', 'sự xuất hiện; sự ra đời', 'n.', NULL, 'Đồng nghĩa: arrival, emergence', 'Thường dùng the advent of để chỉ sự xuất hiện của những phát minh hoặc sự kiện quan trọng mới.', 'The advent of smartphones changed how we take photos.', NULL, 'Sự xuất hiện của điện thoại thông minh đã thay đổi cách chúng ta chụp ảnh.', '{"wordId":"advent","ukIpa":"/ˈædvent/","usIpa":"/ˈædvent/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"The arrival of an important new invention, event, or period","vi":"sự xuất hiện; sự ra đời"}],"examples":[{"en":"The advent of smartphones changed how we take photos.","vi":"Sự xuất hiện của điện thoại thông minh đã thay đổi cách chúng ta chụp ảnh.","audioKind":"ex"},{"en":"The advent of affordable renewable energy has encouraged governments to reconsider their dependence on fossil fuels.","vi":"Sự ra đời của năng lượng tái tạo giá cả phải chăng đã khuyến khích các chính phủ xem xét lại sự phụ thuộc của họ vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"the advent of","vi":"sự xuất hiện của"},{"en":"with the advent of","vi":"với sự ra đời của"},{"en":"since the advent of","vi":"kể từ khi xuất hiện"}],"wordFamily":[],"synonyms":["arrival","emergence"],"antonyms":[],"tipVi":"Thường dùng the advent of để chỉ sự xuất hiện của những phát minh hoặc sự kiện quan trọng mới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_verification', 'en-c1-51', 'verification', '/ˌverɪfɪˈkeɪʃən/', 'C1', 'sự xác minh; sự kiểm chứng', 'n.', 'verify (v.), verifiable (adj.)', 'Đồng nghĩa: confirmation, validation', 'Thường dùng với verification of, dùng để chỉ việc xác thực danh tính, sự thật hoặc kết quả.', 'The website requires identity verification before I can withdraw money.', NULL, 'Trang web yêu cầu xác minh danh tính trước khi tôi có thể rút tiền.', '{"wordId":"verification","ukIpa":"/ˌverɪfɪˈkeɪʃən/","usIpa":"/ˌverɪfɪˈkeɪʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"The process of checking that something is true or accurate.","vi":"sự xác minh; sự kiểm chứng"}],"examples":[{"en":"The website requires identity verification before I can withdraw money.","vi":"Trang web yêu cầu xác minh danh tính trước khi tôi có thể rút tiền.","audioKind":"ex"},{"en":"Independent verification of research findings is essential for maintaining public confidence in scientific advice.","vi":"Việc kiểm chứng độc lập các kết quả nghiên cứu là điều cần thiết để duy trì lòng tin của công chúng đối với các khuyến nghị khoa học.","audioKind":"ex2"}],"collocations":[{"en":"identity verification","vi":"xác minh danh tính"},{"en":"independent verification","vi":"kiểm chứng độc lập"},{"en":"verification process","vi":"quy trình xác minh"}],"wordFamily":["verify (v.)","verifiable (adj.)"],"synonyms":["confirmation","validation"],"antonyms":[],"tipVi":"Thường dùng với verification of, dùng để chỉ việc xác thực danh tính, sự thật hoặc kết quả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_patent', 'en-c1-51', 'patent', '/ˈpætənt/', 'C1', 'bằng độc quyền sáng chế; quyền sáng chế; đăng ký bằng sáng chế; cấp bằng sáng chế; rõ ràng; rành rành', 'n.', 'patented (adj.), patentable (adj.), patentee (n.)', NULL, 'Bằng sáng chế là patent; bản quyền là copyright, hai từ này khác nhau.', 'Her uncle holds a patent for a folding bicycle.', NULL, 'Chú của cô ấy nắm giữ bằng sáng chế cho một thiết kế xe đạp gập.', '{"wordId":"patent","ukIpa":"/ˈpeɪtənt/","usIpa":"/ˈpætənt/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"a legal right to control an invention''s production and sale","vi":"bằng độc quyền sáng chế; quyền sáng chế"},{"pos":"v.","en":"to obtain legal protection for an invention","vi":"đăng ký bằng sáng chế; cấp bằng sáng chế"},{"pos":"adj.","en":"very clear and easy to recognize","vi":"rõ ràng; rành rành"}],"examples":[{"en":"Her uncle holds a patent for a folding bicycle.","vi":"Chú của cô ấy nắm giữ bằng sáng chế cho một thiết kế xe đạp gập.","audioKind":"ex"},{"en":"Patent protection can encourage innovation by allowing inventors to recover the costs of developing new technologies.","vi":"Quyền bảo hộ sáng chế có thể thúc đẩy đổi mới bằng cách cho phép các nhà phát minh thu hồi chi phí phát triển công nghệ mới.","audioKind":"ex2"}],"collocations":[{"en":"apply for a patent","vi":"nộp đơn xin cấp bằng sáng chế"},{"en":"hold a patent","vi":"nắm giữ bằng sáng chế"},{"en":"patent protection","vi":"bảo hộ sáng chế"},{"en":"patent an invention","vi":"đăng ký sáng chế"}],"wordFamily":["patented (adj.)","patentable (adj.)","patentee (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Bằng sáng chế là patent; bản quyền là copyright, hai từ này khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_microfilm', 'en-c1-51', 'microfilm', '/ˈmaɪkroʊfɪlm/', 'C1', 'cuộn vi phim; phim thu nhỏ; chụp thu nhỏ lên vi phim', 'n.', 'microfilming (n.)', NULL, 'Diễn tả việc lưu trữ dưới dạng vi phim, dùng on microfilm.', 'The librarian showed me how to view the microfilm.', NULL, 'Người thủ thư đã chỉ cho tôi cách xem cuộn vi phim.', '{"wordId":"microfilm","ukIpa":"/ˈmaɪkrəʊfɪlm/","usIpa":"/ˈmaɪkroʊfɪlm/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"Film storing very small photographic copies of documents.","vi":"cuộn vi phim; phim thu nhỏ"},{"pos":"v.","en":"To photograph documents at a greatly reduced size on film.","vi":"chụp thu nhỏ lên vi phim"}],"examples":[{"en":"The librarian showed me how to view the microfilm.","vi":"Người thủ thư đã chỉ cho tôi cách xem cuộn vi phim.","audioKind":"ex"},{"en":"Before digital archives became common, libraries used microfilm to preserve newspapers while saving valuable storage space.","vi":"Trước khi lưu trữ kỹ thuật số trở nên phổ biến, các thư viện sử dụng vi phim để bảo quản báo chí đồng thời tiết kiệm không gian lưu trữ quý giá.","audioKind":"ex2"}],"collocations":[{"en":"on microfilm","vi":"dưới dạng vi phim"},{"en":"a microfilm reader","vi":"máy đọc vi phim"},{"en":"microfilm archives","vi":"kho lưu trữ vi phim"}],"wordFamily":["microfilming (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn tả việc lưu trữ dưới dạng vi phim, dùng on microfilm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_51_1', 'en-c1-51', 'Cách dùng “simulate” (v.) — mô phỏng', 'simulate conditions  ·  simulate an emergency  ·  simulate the effects of', 'Dùng simulate khi nói về việc mô phỏng môi trường hoặc tình huống; dùng stimulate khi nói về việc kích thích sự phát triển.', 'Họ từ (Word Family): simulation (n.), simulator (n.), simulated (adj.) | Đồng nghĩa: imitate, replicate', '[{"hanzi":"This driving game simulates icy roads surprisingly well.","pinyin":"","meaning":"Trò chơi lái xe này mô phỏng những con đường đóng băng một cách chân thực đến bất ngờ."},{"hanzi":"Researchers simulate extreme weather conditions to assess how new building materials perform under environmental stress.","pinyin":"","meaning":"Các nhà nghiên cứu mô phỏng các điều kiện thời tiết khắc nghiệt để đánh giá hiệu suất của vật liệu xây dựng mới dưới áp lực môi trường."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_51_2', 'en-c1-51', 'Cách dùng “amplification” (n.) — sự khuếch đại (âm thanh hoặc tín hiệu)', 'sound amplification  ·  signal amplification  ·  amplification equipment', 'Thường dùng để chỉ việc tăng cường âm thanh, tín hiệu, hoặc cũng có thể dùng cho việc làm gia tăng sức ảnh hưởng.', 'Họ từ (Word Family): amplify (v.), amplifier (n.)', '[{"hanzi":"Without amplification, nobody could hear the singer outside.","pinyin":"","meaning":"Nếu không có thiết bị khuếch đại, không ai có thể nghe thấy giọng ca sĩ ở bên ngoài."},{"hanzi":"The amplification of misleading claims through social media can undermine public trust in scientific research.","pinyin":"","meaning":"Việc khuếch đại các thông tin sai lệch qua mạng xã hội có thể làm suy yếu niềm tin của công chúng vào nghiên cứu khoa học."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_51_3', 'en-c1-51', 'Cách dùng “specification” (n.) — bản thông số kỹ thuật; quy cách kỹ thuật', 'technical specifications  ·  meet specifications  ·  design specification', 'Khi nói về các thông số của sản phẩm, thường dùng dạng số nhiều specifications, có thể viết tắt là specs.', 'Họ từ (Word Family): specify (v.), specific (adj.), specifically (adv.)', '[{"hanzi":"Check the specifications before buying a new laptop.","pinyin":"","meaning":"Hãy kiểm tra các thông số kỹ thuật trước khi mua một chiếc máy tính xách tay mới."},{"hanzi":"Clear building specifications help ensure that new housing meets safety standards and uses energy efficiently.","pinyin":"","meaning":"Các yêu cầu kỹ thuật xây dựng rõ ràng giúp đảm bảo nhà ở mới đáp ứng các tiêu chuẩn an toàn và sử dụng năng lượng hiệu quả."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_51_4', 'en-c1-51', 'Cách dùng “semiconductor” (n.) — vật liệu bán dẫn', 'semiconductor chips  ·  semiconductor manufacturing  ·  the semiconductor industry', 'Tiền tố semi- có nghĩa là một nửa; chất bán dẫn có độ dẫn điện nằm giữa chất dẫn điện và chất cách điện.', 'Họ từ (Word Family): semiconducting (adj.), semiconduction (n.)', '[{"hanzi":"My sister works at a factory making semiconductor chips.","pinyin":"","meaning":"Chị gái tôi làm việc tại một nhà máy sản xuất chip bán dẫn."},{"hanzi":"Investment in semiconductor manufacturing is essential for developing reliable supplies of components used in modern electronic devices.","pinyin":"","meaning":"Đầu tư vào ngành sản xuất chất bán dẫn là điều cốt yếu để đảm bảo nguồn cung ổn định các linh kiện dùng trong các thiết bị điện tử hiện đại."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_51_1', 'en-c1-51', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_1_1', 'ten_c1_51_1', 'specification', 'Check the specifications before buying a new laptop.', 'Check the specifications before buying a new laptop.', '/ˌspesɪfɪˈkeɪʃən/', 'Hãy kiểm tra các thông số kỹ thuật trước khi mua một chiếc máy tính xách tay mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_1_2', 'ten_c1_51_1', 'alignment', 'The mechanic checked the alignment of my front wheels.', 'The mechanic checked the alignment of my front wheels.', '/əˈlaɪnmənt/', 'Thợ máy đã kiểm tra độ chụm của các bánh trước xe của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_1_3', 'ten_c1_51_1', 'instantaneous', 'The relief was almost instantaneous when I removed my shoes.', 'The relief was almost instantaneous when I removed my shoes.', '/ˌɪnstənˈteɪniəs/', 'Cảm giác nhẹ nhõm đến gần như ngay lập tức khi tôi cởi giày ra.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_1_4', 'ten_c1_51_1', 'auxiliary', 'The boat has an auxiliary engine for emergencies.', 'The boat has an auxiliary engine for emergencies.', '/ɔːɡˈzɪljəri/', 'Con thuyền được trang bị một động cơ dự phòng để dùng trong các trường hợp khẩn cấp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_1_5', 'ten_c1_51_1', 'semiconductor', 'My sister works at a factory making semiconductor chips.', 'My sister works at a factory making semiconductor chips.', '/ˌsemikənˈdʌktər/', 'Chị gái tôi làm việc tại một nhà máy sản xuất chip bán dẫn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_1_6', 'ten_c1_51_1', 'array', 'The bakery displayed a colourful array of cakes.', 'The bakery displayed a colourful array of cakes.', '/əˈreɪ/', 'Tiệm bánh trưng bày rất nhiều loại bánh ngọt rực rỡ sắc màu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_1_7', 'ten_c1_51_1', 'compute', 'This app computes the cost of our weekly shopping.', 'This app computes the cost of our weekly shopping.', '/kəmˈpjuːt/', 'Ứng dụng này tính toán chi phí mua sắm hằng tuần của chúng tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_1_8', 'ten_c1_51_1', 'dimensional', 'The carpenter checked the dimensional accuracy of each shelf.', 'The carpenter checked the dimensional accuracy of each shelf.', '/daɪˈmenʃənəl/', 'Thợ mộc đã kiểm tra độ chính xác về kích thước của từng chiếc kệ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_51_1_1', 'en-c1-51', 'ten_c1_51_1', 'listening', 'listening', 'Check the specifications before buying a new laptop.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Trò chơi lái xe này mô phỏng những con đường đóng băng một cách chân thực đến bất ngờ.","Ứng dụng này tính toán chi phí mua sắm hằng tuần của chúng tôi.","Hãy kiểm tra các thông số kỹ thuật trước khi mua một chiếc máy tính xách tay mới.","Thời biểu mới này thay thế cho bản dán trên tủ lạnh nhà chúng ta."]'::jsonb, 2, 'Check the specifications before buying a new laptop. → Hãy kiểm tra các thông số kỹ thuật trước khi mua một chiếc máy tính xách tay mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_51_1_2', 'en-c1-51', 'ten_c1_51_1', 'listening', 'listening', 'The mechanic checked the alignment of my front wheels.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thợ máy đã kiểm tra độ chụm của các bánh trước xe của tôi.","Người thủ thư đã chỉ cho tôi cách xem cuộn vi phim.","Trang web yêu cầu xác minh danh tính trước khi tôi có thể rút tiền.","Trò chơi lái xe này mô phỏng những con đường đóng băng một cách chân thực đến bất ngờ."]'::jsonb, 0, 'The mechanic checked the alignment of my front wheels. → Thợ máy đã kiểm tra độ chụm của các bánh trước xe của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_51_1_3', 'en-c1-51', 'ten_c1_51_1', 'listening', 'listening', 'The relief was almost instantaneous when I removed my shoes.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cảm giác nhẹ nhõm đến gần như ngay lập tức khi tôi cởi giày ra.","Chúng tôi có thể nhìn thấy một giàn khoan dầu từ bãi biển.","Thợ máy đã kiểm tra hệ thống truyền động trước chuyến đi dài của chúng tôi.","Chiếc thuyền nhỏ này dựa vào hệ thống đẩy điện để di chuyển một cách êm ái."]'::jsonb, 0, 'The relief was almost instantaneous when I removed my shoes. → Cảm giác nhẹ nhõm đến gần như ngay lập tức khi tôi cởi giày ra.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_51_2', 'en-c1-51', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_2_1', 'ten_c1_51_2', 'specification', 'Clear building specifications help ensure that new housing meets safety standards and uses energy efficiently.', 'Clear building specifications help ensure that new housing meets safety standards and uses energy efficiently.', '/ˌspesɪfɪˈkeɪʃən/', 'Các yêu cầu kỹ thuật xây dựng rõ ràng giúp đảm bảo nhà ở mới đáp ứng các tiêu chuẩn an toàn và sử dụng năng lượng hiệu quả.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_2_2', 'ten_c1_51_2', 'alignment', 'Closer alignment between school curricula and workplace needs could improve employment prospects for young graduates.', 'Closer alignment between school curricula and workplace needs could improve employment prospects for young graduates.', '/əˈlaɪnmənt/', 'Sự đồng bộ chặt chẽ hơn giữa chương trình giảng dạy ở trường và nhu cầu của thị trường lao động có thể cải thiện triển vọng việc làm cho các cử nhân trẻ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_2_3', 'ten_c1_51_2', 'instantaneous', 'Modern communication networks allow almost instantaneous exchanges of information between researchers working on different continents.', 'Modern communication networks allow almost instantaneous exchanges of information between researchers working on different continents.', '/ˌɪnstənˈteɪniəs/', 'Các mạng lưới truyền thông hiện đại cho phép các nhà nghiên cứu làm việc ở các châu lục khác nhau trao đổi thông tin gần như tức thời.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_2_4', 'ten_c1_51_2', 'auxiliary', 'Hospitals require auxiliary power systems to maintain essential medical services during unexpected electricity failures.', 'Hospitals require auxiliary power systems to maintain essential medical services during unexpected electricity failures.', '/ɔːɡˈzɪljəri/', 'Các bệnh viện yêu cầu hệ thống cung cấp điện dự phòng để duy trì các dịch vụ y tế thiết yếu trong trường hợp mất điện bất ngờ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_2_5', 'ten_c1_51_2', 'semiconductor', 'Investment in semiconductor manufacturing is essential for developing reliable supplies of components used in modern electronic devices.', 'Investment in semiconductor manufacturing is essential for developing reliable supplies of components used in modern electronic devices.', '/ˌsemikənˈdʌktər/', 'Đầu tư vào ngành sản xuất chất bán dẫn là điều cốt yếu để đảm bảo nguồn cung ổn định các linh kiện dùng trong các thiết bị điện tử hiện đại.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_51_2_6', 'ten_c1_51_2', 'array', 'Modern universities offer a wide array of courses to meet the demands of a changing labour market.', 'Modern universities offer a wide array of courses to meet the demands of a changing labour market.', '/əˈreɪ/', 'Các trường đại học hiện đại cung cấp vô số các khóa học đa dạng nhằm đáp ứng nhu cầu của thị trường lao động đang đổi thay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_51_2_1', 'en-c1-51', 'ten_c1_51_2', 'listening', 'listening', 'Clear building specifications help ensure that new housing meets safety standards and uses energy efficiently.', NULL, 'Trong câu vừa nghe, từ “specification” mang nghĩa nào sau đây?', '["bản thông số kỹ thuật; quy cách kỹ thuật","can thiệp; can dự","giàn khoan; thiết bị khoan","gợi lên; gợi nhớ; đánh thức"]'::jsonb, 0, '“specification” (/ˌspesɪfɪˈkeɪʃən/): bản thông số kỹ thuật; quy cách kỹ thuật. Câu đầy đủ: Clear building specifications help ensure that new housing meets safety standards and uses energy efficiently.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_51_2_2', 'en-c1-51', 'ten_c1_51_2', 'listening', 'listening', 'Closer alignment between school curricula and workplace needs could improve employment prospects for young graduates.', NULL, 'Trong câu vừa nghe, từ “alignment” mang nghĩa nào sau đây?', '["quá mức kỹ tính; khó chiều; kén chọn","sự sắp thẳng hàng; sự căn chỉnh đúng vị trí","sự giải thích chi tiết; sự bổ sung chi tiết","phân biệt; nhận biết sự khác nhau"]'::jsonb, 1, '“alignment” (/əˈlaɪnmənt/): sự sắp thẳng hàng; sự căn chỉnh đúng vị trí. Câu đầy đủ: Closer alignment between school curricula and workplace needs could improve employment prospects for young graduates.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
