INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_1', 'en-c1-51', NULL, 'comprehensive_test', 'listening', 'specification', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bản thông số kỹ thuật; quy cách kỹ thuật","hậu duệ; con cháu","tận dụng; sử dụng hiệu quả","phân biệt đối xử; thực hiện phân biệt chủng tộc"]'::jsonb, 0, 'specification (/ˌspesɪfɪˈkeɪʃən/) → bản thông số kỹ thuật; quy cách kỹ thuật', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_2', 'en-c1-51', NULL, 'comprehensive_test', 'listening', 'The mechanic checked the alignment of my front wheels.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ứng dụng này tính toán chi phí mua sắm hằng tuần của chúng tôi.","Tiệm bánh trưng bày rất nhiều loại bánh ngọt rực rỡ sắc màu.","Con thuyền được trang bị một động cơ dự phòng để dùng trong các trường hợp khẩn cấp.","Thợ máy đã kiểm tra độ chụm của các bánh trước xe của tôi."]'::jsonb, 3, 'The mechanic checked the alignment of my front wheels. → Thợ máy đã kiểm tra độ chụm của các bánh trước xe của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_3', 'en-c1-51', NULL, 'comprehensive_test', 'listening', 'instantaneous', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiềm ẩn; ẩn giấu; tiềm tàng","xấu xí; gớm ghiếc","quân tốt (trong cờ vua)","ngay lập tức; tức thời"]'::jsonb, 3, 'instantaneous (/ˌɪnstənˈteɪniəs/) → ngay lập tức; tức thời', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_4', 'en-c1-51', NULL, 'comprehensive_test', 'listening', 'The boat has an auxiliary engine for emergencies.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con thuyền được trang bị một động cơ dự phòng để dùng trong các trường hợp khẩn cấp.","Công nghệ viễn thông giúp gia đình chúng tôi gắn kết dù cách trở đại dương.","Chiếc thuyền nhỏ này dựa vào hệ thống đẩy điện để di chuyển một cách êm ái.","Sự xuất hiện của điện thoại thông minh đã thay đổi cách chúng ta chụp ảnh."]'::jsonb, 0, 'The boat has an auxiliary engine for emergencies. → Con thuyền được trang bị một động cơ dự phòng để dùng trong các trường hợp khẩn cấp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_5', 'en-c1-51', NULL, 'comprehensive_test', 'listening', 'semiconductor', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người giảng đạo; nhà truyền giáo","đầu tiên; chuyến xuất phát đầu tiên","vật liệu bán dẫn","nán lại; chần chừ không muốn rời đi"]'::jsonb, 2, 'semiconductor (/ˌsemikənˈdʌktər/) → vật liệu bán dẫn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_6', 'en-c1-51', NULL, 'comprehensive_test', 'listening', 'The bakery displayed a colourful array of cakes.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thợ máy đã kiểm tra độ chụm của các bánh trước xe của tôi.","Thợ máy đã kiểm tra hệ thống truyền động trước chuyến đi dài của chúng tôi.","Tiệm bánh trưng bày rất nhiều loại bánh ngọt rực rỡ sắc màu.","Hãy kiểm tra các thông số kỹ thuật trước khi mua một chiếc máy tính xách tay mới."]'::jsonb, 2, 'The bakery displayed a colourful array of cakes. → Tiệm bánh trưng bày rất nhiều loại bánh ngọt rực rỡ sắc màu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
