INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_18', 'en-c1-51', NULL, 'comprehensive_test', 'reading', NULL, 'Clear building specifications help ensure that new housing meets safety standards and uses energy efficiently.', 'Dựa vào câu trên, từ “specification” có nghĩa phù hợp nhất là gì?', '["huyết tương","hùng mạnh; to lớn","sự truy tố; quá trình khởi tố hình sự","bản thông số kỹ thuật; quy cách kỹ thuật"]'::jsonb, 3, 'specification: bản thông số kỹ thuật; quy cách kỹ thuật. Dịch cả câu: Các yêu cầu kỹ thuật xây dựng rõ ràng giúp đảm bảo nhà ở mới đáp ứng các tiêu chuẩn an toàn và sử dụng năng lượng hiệu quả.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_19', 'en-c1-51', NULL, 'comprehensive_test', 'reading', NULL, 'Closer alignment between school curricula and workplace needs could improve employment prospects for young graduates.', 'Dựa vào câu trên, từ “alignment” có nghĩa phù hợp nhất là gì?', '["cấp dưới, phụ, thứ yếu","uy tín; danh vọng; tiếng tăm","sự sắp thẳng hàng; sự căn chỉnh đúng vị trí","tuân thủ; tuân theo"]'::jsonb, 2, 'alignment: sự sắp thẳng hàng; sự căn chỉnh đúng vị trí; sự thống nhất (giữa các ý tưởng, mục tiêu hoặc hành động); sự liên minh, khối liên kết (giữa các nhóm có chung mục tiêu hoặc lợi ích chính trị). Dịch cả câu: Sự đồng bộ chặt chẽ hơn giữa chương trình giảng dạy ở trường và nhu cầu của thị trường lao động có thể cải thiện triển vọng việc làm cho các cử nhân trẻ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_20', 'en-c1-51', NULL, 'comprehensive_test', 'reading', NULL, 'Modern communication networks allow almost instantaneous exchanges of information between researchers working on different continents.', 'Dựa vào câu trên, từ “instantaneous” có nghĩa phù hợp nhất là gì?', '["ranh mãnh, quỷ quyệt, lén lút (thường nhằm vụ lợi)","sự lưu vong, sự bị đày ải khỏi quê hương, thường vì lý do chính trị","ngay lập tức; tức thời","tràn ngập; chiếm đóng với số lượng lớn"]'::jsonb, 2, 'instantaneous: ngay lập tức; tức thời. Dịch cả câu: Các mạng lưới truyền thông hiện đại cho phép các nhà nghiên cứu làm việc ở các châu lục khác nhau trao đổi thông tin gần như tức thời.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_21', 'en-c1-51', NULL, 'comprehensive_test', 'reading', NULL, 'Hospitals require auxiliary power systems to maintain essential medical services during unexpected electricity failures.', 'Dựa vào câu trên, từ “auxiliary” có nghĩa phù hợp nhất là gì?', '["phụ; dự phòng; bổ trợ","cõng; sự cõng trên lưng","dành sẵn; định sẵn cho tương lai","làm cho phát bực; chọc tức; làm bực mình"]'::jsonb, 0, 'auxiliary: phụ; dự phòng; bổ trợ; thừa nhận. Dịch cả câu: Các bệnh viện yêu cầu hệ thống cung cấp điện dự phòng để duy trì các dịch vụ y tế thiết yếu trong trường hợp mất điện bất ngờ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_22', 'en-c1-51', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự xác minh; sự kiểm chứng”', '["climactic","truant","verification","defraud"]'::jsonb, 2, 'sự xác minh; sự kiểm chứng → verification (/ˌverɪfɪˈkeɪʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_23', 'en-c1-51', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bằng độc quyền sáng chế; quyền sáng chế”', '["patent","enlighten","conformity","mishandle"]'::jsonb, 0, 'bằng độc quyền sáng chế; quyền sáng chế → patent (/ˈpætənt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_51_24', 'en-c1-51', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cuộn vi phim; phim thu nhỏ”', '["cruiser","consulate","prevailing","microfilm"]'::jsonb, 3, 'cuộn vi phim; phim thu nhỏ → microfilm (/ˈmaɪkroʊfɪlm/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-52', 'en', 'Bài 52: Công nghệ & Kỹ thuật (2) - CEFR C1', 'CEFR C1', 'C1 · Công nghệ', '21 từ vựng Tiếng Anh CEFR C1 chủ đề công nghệ & kỹ thuật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5052, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preset', 'en-c1-52', 'preset', '/ˌpriːˈset/', 'C1', 'cài đặt sẵn; thiết lập trước; được cài đặt sẵn; được định trước; chế độ cài đặt sẵn; tùy chọn được lưu trước', 'v.', NULL, 'Đồng nghĩa: preconfigure', 'Dạng quá khứ và phân từ hai của preset đều là preset; dạng phân từ hiện đại là presetting.', 'I preset the oven timer before preparing the vegetables.', NULL, 'Tôi đã cài đặt sẵn thời gian trên lò nướng trước khi sơ chế rau củ.', '{"wordId":"preset","ukIpa":"/ˌpriːˈset/","usIpa":"/ˌpriːˈset/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"To set a device or control before it is used.","vi":"cài đặt sẵn; thiết lập trước"},{"pos":"adj.","en":"Set or fixed before use.","vi":"được cài đặt sẵn; được định trước"},{"pos":"n.","en":"A saved setting available for immediate use.","vi":"chế độ cài đặt sẵn; tùy chọn được lưu trước"}],"examples":[{"en":"I preset the oven timer before preparing the vegetables.","vi":"Tôi đã cài đặt sẵn thời gian trên lò nướng trước khi sơ chế rau củ.","audioKind":"ex"},{"en":"Smart heating systems can be preset to reduce energy consumption during periods when buildings are unoccupied.","vi":"Các hệ thống sưởi thông minh có thể được lập trình sẵn để giảm mức tiêu thụ năng lượng trong những khoảng thời gian tòa nhà không có người sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"preset the timer","vi":"cài đặt bộ hẹn giờ"},{"en":"preset temperature","vi":"nhiệt độ được cài đặt sẵn"},{"en":"factory presets","vi":"chế độ mặc định từ nhà sản xuất"}],"wordFamily":[],"synonyms":["preconfigure"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai của preset đều là preset; dạng phân từ hiện đại là presetting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ingenious', 'en-c1-52', 'ingenious', '/ɪnˈdʒiːniəs/', 'C1', 'khéo léo; tài tình; cósự sáng tạo độc đáo', 'adj.', 'ingenuity (n.), ingeniously (adv.)', 'Đồng nghĩa: inventive, clever · Trái nghĩa: unimaginative', 'Tránh nhầm lẫn: ingenious mang nghĩa khéo léo, tài tình, trong khi ingenuous mang nghĩa ngây thơ, chân thật.', 'He built an ingenious watering system from old bottles.', NULL, 'Anh ấy đã chế tạo một hệ thống tưới cây vô cùng tài tình từ những chiếc chai cũ.', '{"wordId":"ingenious","ukIpa":"/ɪnˈdʒiːniəs/","usIpa":"/ɪnˈdʒiːniəs/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"Using clever, original ideas to solve problems or make things.","vi":"khéo léo; tài tình; cósự sáng tạo độc đáo"}],"examples":[{"en":"He built an ingenious watering system from old bottles.","vi":"Anh ấy đã chế tạo một hệ thống tưới cây vô cùng tài tình từ những chiếc chai cũ.","audioKind":"ex"},{"en":"Ingenious designs can help architects create comfortable homes on small plots without sacrificing natural light.","vi":"Thiết kế khéo léo có thể giúp các kiến trúc sư tạo ra những ngôi nhà thoải mái trên những mảnh đất nhỏ mà vẫn đảm bảo ánh sáng tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"an ingenious solution","vi":"một giải pháp thông minh"},{"en":"an ingenious device","vi":"một thiết bị tinh xảo"},{"en":"an ingenious design","vi":"một thiết kế tài tình"}],"wordFamily":["ingenuity (n.)","ingeniously (adv.)"],"synonyms":["inventive","clever"],"antonyms":["unimaginative"],"tipVi":"Tránh nhầm lẫn: ingenious mang nghĩa khéo léo, tài tình, trong khi ingenuous mang nghĩa ngây thơ, chân thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_operational', 'en-c1-52', 'operational', '/ˌɑːpəˈreɪʃənəl/', 'C1', 'sẵn sàng và có thể hoạt động hoặc sử dụng được; thuộc về cách thức vận hành của một tổ chức hay hệ thống', 'adj.', 'operate (v.), operation (n.), operator (n.), operationally (adv.)', 'Đồng nghĩa: functioning', 'Có thể chỉ thiết bị đã sẵn sàng sử dụng hoặc chỉ hoạt động thường nhật của một cơ quan.', 'The lift is operational again after yesterday''s repairs.', NULL, 'Chiếc thang máy đã hoạt động trở lại sau buổi sửa chữa ngày hôm qua.', '{"wordId":"operational","ukIpa":"/ˌɒpəˈreɪʃənəl/","usIpa":"/ˌɑːpəˈreɪʃənəl/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"ready and able to work or be used","vi":"sẵn sàng và có thể hoạt động hoặc sử dụng được"},{"pos":"adj.","en":"relating to how an organization or system runs","vi":"thuộc về cách thức vận hành của một tổ chức hay hệ thống"}],"examples":[{"en":"The lift is operational again after yesterday''s repairs.","vi":"Chiếc thang máy đã hoạt động trở lại sau buổi sửa chữa ngày hôm qua.","audioKind":"ex"},{"en":"Although renewable energy projects require substantial investment, their operational costs can remain relatively low.","vi":"Mặc dù các dự án năng lượng tái tạo đòi hỏi khoản đầu tư lớn, chi phí vận hành của chúng vẫn có thể duy trì ở mức tương đối thấp.","audioKind":"ex2"}],"collocations":[{"en":"fully operational","vi":"hoạt động hoàn toàn"},{"en":"become operational","vi":"bắt đầu đi vào hoạt động"},{"en":"operational costs","vi":"chi phí vận hành"},{"en":"operational efficiency","vi":"hiệu quả hoạt động"}],"wordFamily":["operate (v.)","operation (n.)","operator (n.)","operationally (adv.)"],"synonyms":["functioning"],"antonyms":[],"tipVi":"Có thể chỉ thiết bị đã sẵn sàng sử dụng hoặc chỉ hoạt động thường nhật của một cơ quan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prototype', 'en-c1-52', 'prototype', '/ˈproʊtətaɪp/', 'C1', 'mẫu thử nghiệm; bản mẫu; làm mẫu thử; chế tạo nguyên mẫu', 'n.', 'prototyping (n.), prototypical (adj.)', NULL, 'Thường chỉ dùng cho mô hình đời đầu nhằm kiểm tra và cải tiến, không phải là sản phẩm hoàn chỉnh cuối cùng.', 'The designer showed us a prototype of her folding chair.', NULL, 'Nhà thiết kế đã cho chúng tôi xem một mẫu thử chiếc ghế gấp của cô ấy.', '{"wordId":"prototype","ukIpa":"/ˈprəʊtətaɪp/","usIpa":"/ˈproʊtətaɪp/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"An early model used to test and develop a product.","vi":"mẫu thử nghiệm; bản mẫu"},{"pos":"v.","en":"To create an early model for testing and improvement.","vi":"làm mẫu thử; chế tạo nguyên mẫu"}],"examples":[{"en":"The designer showed us a prototype of her folding chair.","vi":"Nhà thiết kế đã cho chúng tôi xem một mẫu thử chiếc ghế gấp của cô ấy.","audioKind":"ex"},{"en":"Testing a prototype allows engineers to identify design weaknesses before a product enters mass production.","vi":"Việc thử nghiệm mẫu thử giúp các kỹ sư phát hiện ra các điểm yếu trong thiết kế trước khi sản phẩm bước vào giai đoạn sản xuất hàng loạt.","audioKind":"ex2"}],"collocations":[{"en":"build a prototype","vi":"chế tạo nguyên mẫu"},{"en":"test a prototype","vi":"thử nghiệm mẫu thử"},{"en":"a working prototype","vi":"mẫu thử có thể hoạt động"}],"wordFamily":["prototyping (n.)","prototypical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ dùng cho mô hình đời đầu nhằm kiểm tra và cải tiến, không phải là sản phẩm hoàn chỉnh cuối cùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aero', 'en-c1-52', 'aero', '/ˈeroʊ/', 'C1', 'thuộc về hàng không; thuộc về máy bay', 'adj.', 'aeronautics (n.), aeronautical (adj.)', NULL, 'Thường dùng trước danh từ; aero- cũng thường được dùng làm tiền tố liên quan đến hàng không.', 'We saw an old aero engine at the museum.', NULL, 'Chúng tôi đã nhìn thấy một động cơ hàng không cổ trong bảo tàng.', '{"wordId":"aero","ukIpa":"/ˈeərəʊ/","usIpa":"/ˈeroʊ/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"relating to aircraft or aviation","vi":"thuộc về hàng không; thuộc về máy bay"}],"examples":[{"en":"We saw an old aero engine at the museum.","vi":"Chúng tôi đã nhìn thấy một động cơ hàng không cổ trong bảo tàng.","audioKind":"ex"},{"en":"Improvements in aero engine design can reduce fuel consumption and emissions from commercial aircraft.","vi":"Những cải tiến trong thiết kế động cơ hàng không có thể làm giảm lượng tiêu thụ nhiên liệu và khí thải từ các máy bay thương mại.","audioKind":"ex2"}],"collocations":[{"en":"aero engine","vi":"động cơ hàng không"},{"en":"aero industry","vi":"ngành công nghiệp hàng không"}],"wordFamily":["aeronautics (n.)","aeronautical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng trước danh từ; aero- cũng thường được dùng làm tiền tố liên quan đến hàng không.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_computerization', 'en-c1-52', 'computerization', '/kəmˌpjuːtərəˈzeɪʃən/', 'C1', 'sự máy tính hóa; sự tin học hóa', 'n.', 'computerize (v.), computerized (adj.), computer (n.)', NULL, 'Trong tiếng Anh-Anh thường viết là computerisation; thường là danh từ không đếm được.', 'Computerization means we no longer sort these files by hand.', NULL, 'Việc tin học hóa có nghĩa là chúng ta không còn phải phân loại các tài liệu này bằng tay nữa.', '{"wordId":"computerization","ukIpa":"/kəmˌpjuːtəraɪˈzeɪʃən/","usIpa":"/kəmˌpjuːtərəˈzeɪʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"the introduction of computers to perform tasks or manage information","vi":"sự máy tính hóa; sự tin học hóa"}],"examples":[{"en":"Computerization means we no longer sort these files by hand.","vi":"Việc tin học hóa có nghĩa là chúng ta không còn phải phân loại các tài liệu này bằng tay nữa.","audioKind":"ex"},{"en":"The computerization of hospital records can improve efficiency, but it also requires strong safeguards for patient privacy.","vi":"Việc tin học hóa hồ sơ bệnh án tại các bệnh viện có thể nâng cao hiệu quả, nhưng đồng thời cũng đòi hỏi các biện pháp bảo vệ nghiêm ngặt đối với quyền riêng tư của bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"computerization of records","vi":"tin học hóa hồ sơ"},{"en":"office computerization","vi":"tin học hóa văn phòng"},{"en":"large-scale computerization","vi":"tin học hóa quy mô lớn"}],"wordFamily":["computerize (v.)","computerized (adj.)","computer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh thường viết là computerisation; thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_analogue', 'en-c1-52', 'analogue', '/ˈænəlɔːɡ/', 'C1', 'vật tương tự; vật đối ứng; mô phỏng; tương tự (không dùng kỹ thuật số)', 'n.', 'analogous (adj.), analogy (n.)', 'Đồng nghĩa: counterpart, equivalent', 'Danh từ chỉ vật tương tự; tính từ chỉ dạng mô phỏng, phân biệt với digital.', 'This wooden model is an analogue of the bridge.', NULL, 'Mô hình bằng gỗ này là một vật mô phỏng của cây cầu.', '{"wordId":"analogue","ukIpa":"/ˈænəlɒɡ/","usIpa":"/ˈænəlɔːɡ/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"something similar to another thing in function or structure","vi":"vật tương tự; vật đối ứng"},{"pos":"adj.","en":"using continuously varying signals rather than digital information","vi":"mô phỏng; tương tự (không dùng kỹ thuật số)"}],"examples":[{"en":"This wooden model is an analogue of the bridge.","vi":"Mô hình bằng gỗ này là một vật mô phỏng của cây cầu.","audioKind":"ex"},{"en":"Researchers use a mechanical analogue of the human heart to investigate how blood flows through damaged valves.","vi":"Các nhà nghiên cứu sử dụng một thiết bị cơ học mô phỏng trái tim con người để khảo sát cách máu chảy qua các van bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"analogue of something","vi":"vật tương tự của cái gì"},{"en":"analogue signal","vi":"tín hiệu tương tự"},{"en":"analogue clock","vi":"đồng hồ kim"}],"wordFamily":["analogous (adj.)","analogy (n.)"],"synonyms":["counterpart","equivalent"],"antonyms":[],"tipVi":"Danh từ chỉ vật tương tự; tính từ chỉ dạng mô phỏng, phân biệt với digital.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mechanically', 'en-c1-52', 'mechanically', '/məˈkænɪkli/', 'C1', 'bằng máy móc; theo phương thức cơ khí; một cách máy móc; không suy nghĩ', 'adv.', 'mechanical (adj.), mechanic (n.), mechanism (n.)', 'Đồng nghĩa: automatically', 'Có thể chỉ phương thức cơ học hoặc hành động thiếu tư duy.', 'The apples are sorted mechanically before workers pack them.', NULL, 'Những quả táo được phân loại bằng máy móc trước khi công nhân đóng gói chúng.', '{"wordId":"mechanically","ukIpa":"/məˈkænɪkli/","usIpa":"/məˈkænɪkli/","cefr":"C1","topic":"technology","senses":[{"pos":"adv.","en":"Using machinery, or relating to how a machine works","vi":"bằng máy móc; theo phương thức cơ khí"},{"pos":"adv.","en":"Without conscious thought, interest, or feeling","vi":"một cách máy móc; không suy nghĩ"}],"examples":[{"en":"The apples are sorted mechanically before workers pack them.","vi":"Những quả táo được phân loại bằng máy móc trước khi công nhân đóng gói chúng.","audioKind":"ex"},{"en":"Students who repeat information mechanically may struggle to apply their knowledge to unfamiliar situations.","vi":"Những học sinh lặp lại thông tin một cách máy móc có thể sẽ gặp khó khăn trong việc vận dụng kiến thức của mình vào các tình huống lạ.","audioKind":"ex2"}],"collocations":[{"en":"mechanically operated","vi":"được vận hành bằng cơ khí"},{"en":"mechanically sound","vi":"tình trạng cơ khí tốt"},{"en":"repeat mechanically","vi":"lặp lại máy móc"}],"wordFamily":["mechanical (adj.)","mechanic (n.)","mechanism (n.)"],"synonyms":["automatically"],"antonyms":[],"tipVi":"Có thể chỉ phương thức cơ học hoặc hành động thiếu tư duy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_innovate', 'en-c1-52', 'innovate', '/ˈɪnəveɪt/', 'C1', 'đổi mới; sáng tạo', 'v.', 'innovation (n.), innovative (adj.), innovator (n.), innovatively (adv.)', NULL, 'Thường dùng làm nội động từ; innovate in đi kèm với lĩnh vực cần đổi mới.', 'Our bakery continues to innovate with unusual bread flavours.', NULL, 'Tiệm bánh của chúng tôi tiếp tục đổi mới với các hương vị bánh mì độc đáo.', '{"wordId":"innovate","ukIpa":"/ˈɪnəveɪt/","usIpa":"/ˈɪnəveɪt/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"To introduce new ideas, methods, or products","vi":"đổi mới; sáng tạo"}],"examples":[{"en":"Our bakery continues to innovate with unusual bread flavours.","vi":"Tiệm bánh của chúng tôi tiếp tục đổi mới với các hương vị bánh mì độc đáo.","audioKind":"ex"},{"en":"Companies that innovate successfully can improve productivity while responding more effectively to changing consumer needs.","vi":"Các doanh nghiệp đổi mới thành công có thể nâng cao năng suất đồng thời đáp ứng hiệu quả hơn nhu cầu ngày càng thay đổi của người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"continue to innovate","vi":"tiếp tục đổi mới"},{"en":"innovate in healthcare","vi":"đổi mới trong lĩnh vực y tế"},{"en":"ability to innovate","vi":"năng lực đổi mới"}],"wordFamily":["innovation (n.)","innovative (adj.)","innovator (n.)","innovatively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng làm nội động từ; innovate in đi kèm với lĩnh vực cần đổi mới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compress', 'en-c1-52', 'compress', '/kəmˈpres/', 'C1', 'nén lại; ép chặt; cô đọng; tinh giản', 'v.', 'compression (n.), compressed (adj.), compressible (adj.), compressor (n.)', 'Đồng nghĩa: squeeze, condense · Trái nghĩa: expand', 'Động từ có trọng âm rơi vào âm tiết phía sau; danh từ chỉ miếng gạc có trọng âm rơi vào âm tiết đầu.', 'She compressed the blankets into a small storage bag.', NULL, 'Cô ấy đã nén những chiếc chăn vào một chiếc túi đựng đồ nhỏ gọn.', '{"wordId":"compress","ukIpa":"/kəmˈpres/","usIpa":"/kəmˈpres/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"Press something into a smaller space or reduce its size","vi":"nén lại; ép chặt"},{"pos":"v.","en":"Make information shorter while keeping its main content","vi":"cô đọng; tinh giản"}],"examples":[{"en":"She compressed the blankets into a small storage bag.","vi":"Cô ấy đã nén những chiếc chăn vào một chiếc túi đựng đồ nhỏ gọn.","audioKind":"ex"},{"en":"Digital tools can compress large files, allowing students with limited internet access to download educational materials more easily.","vi":"Các công cụ kỹ thuật số có thể nén các tệp tin lớn, giúp học sinh có đường truyền internet hạn chế tải xuống tài liệu học tập dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"compress a file","vi":"nén tệp tin"},{"en":"compress air","vi":"nén khí"},{"en":"compress into","vi":"nén thành"}],"wordFamily":["compression (n.)","compressed (adj.)","compressible (adj.)","compressor (n.)"],"synonyms":["squeeze","condense"],"antonyms":["expand"],"tipVi":"Động từ có trọng âm rơi vào âm tiết phía sau; danh từ chỉ miếng gạc có trọng âm rơi vào âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_furnace', 'en-c1-52', 'furnace', '/ˈfɝːnɪs/', 'C1', 'lò luyện; lò công nghiệp; lò sưởi', 'n.', NULL, NULL, 'Trong ngữ cảnh công nghiệp, từ này chỉ lò luyện kim; trong ngữ cảnh nhà ở kiểu Mỹ, nó thường chỉ hệ thống lò sưởi.', 'We watched molten metal pour from the glowing furnace.', NULL, 'Chúng tôi đứng xem kim loại nóng chảy tuôn ra từ chiếc lò luyện đang rực sáng.', '{"wordId":"furnace","ukIpa":"/ˈfɜːnɪs/","usIpa":"/ˈfɝːnɪs/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"An enclosed structure producing intense heat for industrial processes.","vi":"lò luyện; lò công nghiệp"},{"pos":"n.","en":"A device that heats air or water to warm a building.","vi":"lò sưởi"}],"examples":[{"en":"We watched molten metal pour from the glowing furnace.","vi":"Chúng tôi đứng xem kim loại nóng chảy tuôn ra từ chiếc lò luyện đang rực sáng.","audioKind":"ex"},{"en":"Replacing an inefficient furnace can reduce household energy consumption and lower heating costs during winter.","vi":"Việc thay thế một chiếc lò sưởi kém hiệu quả có thể giảm mức tiêu thụ năng lượng của gia đình và cắt giảm chi phí sưởi ấm vào mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"a blast furnace","vi":"lò cao"},{"en":"an electric furnace","vi":"lò điện"},{"en":"a gas furnace","vi":"lò sưởi gas"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh công nghiệp, từ này chỉ lò luyện kim; trong ngữ cảnh nhà ở kiểu Mỹ, nó thường chỉ hệ thống lò sưởi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_defective', 'en-c1-52', 'defective', '/dɪˈfektɪv/', 'C1', 'có khiếm khuyết; có lỗi kỹ thuật; hỏng hóc', 'adj.', 'defect (n.), defectively (adv.)', 'Đồng nghĩa: faulty, flawed', 'Thường dùng để mô tả sản phẩm, linh kiện hoặc hệ thống gặp trục trặc và không hoạt động bình thường.', 'The shop replaced my defective kettle without any fuss.', NULL, 'Cửa hàng đã đổi cho tôi chiếc ấm đun nước bị lỗi mà không hề phàn nàn gì.', '{"wordId":"defective","ukIpa":"/dɪˈfektɪv/","usIpa":"/dɪˈfektɪv/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"Having a fault that prevents something from working properly.","vi":"có khiếm khuyết; có lỗi kỹ thuật; hỏng hóc"}],"examples":[{"en":"The shop replaced my defective kettle without any fuss.","vi":"Cửa hàng đã đổi cho tôi chiếc ấm đun nước bị lỗi mà không hề phàn nàn gì.","audioKind":"ex"},{"en":"Manufacturers should recall defective products promptly to protect consumers and maintain public confidence in safety standards.","vi":"Các nhà sản xuất nên nhanh chóng thu hồi các sản phẩm bị lỗi để bảo vệ người tiêu dùng và duy trì niềm tin của công chúng vào các tiêu chuẩn an toàn.","audioKind":"ex2"}],"collocations":[{"en":"defective product","vi":"sản phẩm lỗi"},{"en":"defective equipment","vi":"thiết bị hỏng"},{"en":"defective wiring","vi":"hệ thống dây điện bị lỗi"}],"wordFamily":["defect (n.)","defectively (adv.)"],"synonyms":["faulty","flawed"],"antonyms":[],"tipVi":"Thường dùng để mô tả sản phẩm, linh kiện hoặc hệ thống gặp trục trặc và không hoạt động bình thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hydraulic', 'en-c1-52', 'hydraulic', '/haɪˈdrɔːlɪk/', 'C1', 'thuộc về thủy lực; chạy bằng sức nước', 'adj.', 'hydraulics (n.), hydraulically (adv.)', NULL, 'Hệ thống hydraulic sử dụng áp suất chất lỏng để truyền lực; hệ thống pneumatic sử dụng áp suất khí nén.', 'The mechanic used a hydraulic lift to raise our car.', NULL, 'Thợ máy đã dùng một chiếc kích thủy lực để nâng chiếc xe của chúng tôi lên.', '{"wordId":"hydraulic","ukIpa":"/haɪˈdrɒlɪk/","usIpa":"/haɪˈdrɔːlɪk/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"Using liquid pressure to produce movement or power.","vi":"thuộc về thủy lực; chạy bằng sức nước"}],"examples":[{"en":"The mechanic used a hydraulic lift to raise our car.","vi":"Thợ máy đã dùng một chiếc kích thủy lực để nâng chiếc xe của chúng tôi lên.","audioKind":"ex"},{"en":"Hydraulic systems allow construction equipment to lift heavy loads with greater precision and less manual effort.","vi":"Hệ thống thủy lực giúp các thiết bị xây dựng nâng các vật nặng với độ chính xác cao hơn và tốn ít sức lực thủ công hơn.","audioKind":"ex2"}],"collocations":[{"en":"hydraulic pressure","vi":"áp suất thủy lực"},{"en":"hydraulic brakes","vi":"phanh thủy lực"},{"en":"hydraulic lift","vi":"cần cẩu thủy lực"},{"en":"hydraulic system","vi":"hệ thống thủy lực"}],"wordFamily":["hydraulics (n.)","hydraulically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Hệ thống hydraulic sử dụng áp suất chất lỏng để truyền lực; hệ thống pneumatic sử dụng áp suất khí nén.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lubricate', 'en-c1-52', 'lubricate', '/ˈluːbrɪkeɪt/', 'C1', 'tra dầu mỡ; làm trơn', 'v.', 'lubrication (n.), lubricant (n.)', 'Đồng nghĩa: oil, grease', 'Là ngoại động từ, đi thẳng tới đối tượng cần làm trơn; dùng với giới từ with khi muốn chỉ chất bôi trơn.', 'I lubricated the door hinges to stop that annoying squeak.', NULL, 'Tôi đã tra dầu vào bản lề cửa để dừng tiếng kêu có kẽo kẹt khó chịu đó lại.', '{"wordId":"lubricate","ukIpa":"/ˈluːbrɪkeɪt/","usIpa":"/ˈluːbrɪkeɪt/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"Apply oil or another substance to reduce friction between surfaces.","vi":"tra dầu mỡ; làm trơn"}],"examples":[{"en":"I lubricated the door hinges to stop that annoying squeak.","vi":"Tôi đã tra dầu vào bản lề cửa để dừng tiếng kêu có kẽo kẹt khó chịu đó lại.","audioKind":"ex"},{"en":"Regularly lubricating industrial machinery reduces friction, improves energy efficiency, and extends the working life of essential equipment.","vi":"Việc tra dầu mỡ thường xuyên cho máy móc công nghiệp giúp giảm ma sát, nâng cao hiệu suất năng lượng và kéo dài tuổi thọ của các thiết bị thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"lubricate moving parts","vi":"làm trơn các bộ phận chuyển động"},{"en":"lubricate machinery","vi":"tra dầu máy móc"},{"en":"lubricate with oil","vi":"bôi trơn bằng dầu"}],"wordFamily":["lubrication (n.)","lubricant (n.)"],"synonyms":["oil","grease"],"antonyms":[],"tipVi":"Là ngoại động từ, đi thẳng tới đối tượng cần làm trơn; dùng với giới từ with khi muốn chỉ chất bôi trơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aggregation', 'en-c1-52', 'aggregation', '/ˌæɡrɪˈɡeɪʃən/', 'C1', 'sự tổng hợp; sự gom lại; tập hợp; khối kết tụ', 'n.', 'aggregate (v.), aggregate (n.), aggregated (adj.)', NULL, 'Nhấn mạnh việc gom các mục rời rạc thành một thể thống nhất; rất phổ biến trong xử lý dữ liệu.', 'Automatic aggregation brings all my spending into one monthly report.', NULL, 'Tính năng tự động tổng hợp giúp gom tất cả các khoản chi tiêu của tôi thành một báo cáo hàng tháng duy nhất.', '{"wordId":"aggregation","ukIpa":"/ˌæɡrɪˈɡeɪʃən/","usIpa":"/ˌæɡrɪˈɡeɪʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"the process of combining separate items into a larger whole","vi":"sự tổng hợp; sự gom lại"},{"pos":"n.","en":"a group or collection of things brought together","vi":"tập hợp; khối kết tụ"}],"examples":[{"en":"Automatic aggregation brings all my spending into one monthly report.","vi":"Tính năng tự động tổng hợp giúp gom tất cả các khoản chi tiêu của tôi thành một báo cáo hàng tháng duy nhất.","audioKind":"ex"},{"en":"The aggregation of regional climate data allows researchers to identify broader patterns that individual observations may miss.","vi":"Việc tổng hợp dữ liệu khí hậu khu vực cho phép các nhà nghiên cứu nhận ra các xu hướng vĩ mô mà các quan sát đơn lẻ có thể bỏ sót.","audioKind":"ex2"}],"collocations":[{"en":"data aggregation","vi":"tổng hợp dữ liệu"},{"en":"aggregation of results","vi":"tổng hợp kết quả"},{"en":"content aggregation","vi":"tổng hợp nội dung"}],"wordFamily":["aggregate (v.)","aggregate (n.)","aggregated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh việc gom các mục rời rạc thành một thể thống nhất; rất phổ biến trong xử lý dữ liệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pipeline', 'en-c1-52', 'pipeline', '/ˈpaɪplaɪn/', 'C1', 'đường ống dẫn; kênh cung cấp; quy trình phát triển', 'n.', NULL, NULL, 'Cụm từ ''in the pipeline'' thường ám chỉ các dự án đang được chuẩn bị hoặc tiến hành.', 'Workers repaired the water pipeline beneath our street today.', NULL, 'Các công nhân đã sửa chữa đường ống dẫn nước dưới lòng đường của chúng ta hôm nay.', '{"wordId":"pipeline","ukIpa":"/ˈpaɪplaɪn/","usIpa":"/ˈpaɪplaɪn/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"A long pipe carrying liquids or gas between places.","vi":"đường ống dẫn"},{"pos":"n.","en":"A system through which things are supplied or developed.","vi":"kênh cung cấp; quy trình phát triển"}],"examples":[{"en":"Workers repaired the water pipeline beneath our street today.","vi":"Các công nhân đã sửa chữa đường ống dẫn nước dưới lòng đường của chúng ta hôm nay.","audioKind":"ex"},{"en":"A new gas pipeline could improve energy security, but its construction may damage sensitive wildlife habitats.","vi":"Một đường ống dẫn khí đốt mới có thể nâng cao an ninh năng lượng, nhưng việc xây dựng nó có thể làm tổn hại đến môi trường sống nhạy cảm của động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"a gas pipeline","vi":"đường ống dẫn khí đốt"},{"en":"an oil pipeline","vi":"đường ống dẫn dầu"},{"en":"in the pipeline","vi":"đang trong quá trình chuẩn bị"},{"en":"a development pipeline","vi":"quy trình phát triển"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ ''in the pipeline'' thường ám chỉ các dự án đang được chuẩn bị hoặc tiến hành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lubrication', 'en-c1-52', 'lubrication', '/ˌluːbrɪˈkeɪʃən/', 'C1', 'sự bôi trơn; chất bôi trơn', 'n.', 'lubricate (v.), lubricant (n.)', NULL, 'Lubrication chỉ quá trình bôi trơn; lubricant chỉ chất bôi trơn.', 'The bicycle chain needs lubrication after all that rain.', NULL, 'Sên xe đạp cần được tra dầu bôi trơn sau trận mưa tầm tã đó.', '{"wordId":"lubrication","ukIpa":"/ˌluːbrɪˈkeɪʃən/","usIpa":"/ˌluːbrɪˈkeɪʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"The use of oil or similar substances to reduce friction","vi":"sự bôi trơn; chất bôi trơn"}],"examples":[{"en":"The bicycle chain needs lubrication after all that rain.","vi":"Sên xe đạp cần được tra dầu bôi trơn sau trận mưa tầm tã đó.","audioKind":"ex"},{"en":"Regular lubrication reduces friction in industrial machinery, improving energy efficiency and extending the lifespan of moving components.","vi":"Việc bôi trơn định kỳ giúp giảm ma sát trong máy móc công nghiệp, nâng cao hiệu suất năng lượng và kéo dài tuổi thọ của các bộ phận chuyển động.","audioKind":"ex2"}],"collocations":[{"en":"regular lubrication","vi":"bôi trơn định kỳ"},{"en":"adequate lubrication","vi":"bôi trơn đầy đủ"},{"en":"lubrication system","vi":"hệ thống bôi trơn"},{"en":"lack of lubrication","vi":"thiếu chất bôi trơn"}],"wordFamily":["lubricate (v.)","lubricant (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Lubrication chỉ quá trình bôi trơn; lubricant chỉ chất bôi trơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clamp', 'en-c1-52', 'clamp', '/klæmp/', 'C1', 'cái kẹp; mỏ kẹp; ê-tô; kẹp chặt; giữ chặt', 'n.', NULL, NULL, 'Cụm động từ clamp down on mang nghĩa trừng trị nghiêm khắc hoặc siết chặt quản lý.', 'Use a clamp to hold the wood while gluing.', NULL, 'Dùng kẹp để giữ cố định các thanh gỗ trong lúc bôi keo.', '{"wordId":"clamp","ukIpa":"/klæmp/","usIpa":"/klæmp/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"A device that holds objects tightly together or in place.","vi":"cái kẹp; mỏ kẹp; ê-tô"},{"pos":"v.","en":"To hold something firmly, often using a gripping device.","vi":"kẹp chặt; giữ chặt"}],"examples":[{"en":"Use a clamp to hold the wood while gluing.","vi":"Dùng kẹp để giữ cố định các thanh gỗ trong lúc bôi keo.","audioKind":"ex"},{"en":"During laboratory tests, researchers clamp each sample securely to prevent movement from affecting the accuracy of measurements.","vi":"Trong các bài kiểm tra thí nghiệm, các nhà nghiên cứu kẹp chặt từng mẫu vật để ngăn sự dịch chuyển làm ảnh hưởng đến độ chính xác của kết quả đo.","audioKind":"ex2"}],"collocations":[{"en":"a metal clamp","vi":"kẹp kim loại"},{"en":"clamp something in place","vi":"kẹp chặt vật gì vào đúng vị trí"},{"en":"clamp down on","vi":"trấn áp; hạn chế nghiêm ngặt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm động từ clamp down on mang nghĩa trừng trị nghiêm khắc hoặc siết chặt quản lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fibreglass', 'en-c1-52', 'fibreglass', '/ˈfaɪbərɡlæs/', 'C1', 'sợi thủy tinh; nhựa gia cố sợi thủy tinh', 'n.', NULL, NULL, 'Cách viết theo Anh-Anh là fibreglass, còn Anh-Mỹ là fiberglass.', 'Our small fibreglass boat is easy to carry ashore.', NULL, 'Chiếc thuyền nhựa sợi thủy tinh nhỏ của chúng tôi rất dễ kéo lên bờ.', '{"wordId":"fibreglass","ukIpa":"/ˈfaɪbəɡlɑːs/","usIpa":"/ˈfaɪbərɡlæs/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"fine glass fibres, or plastic strengthened with these fibres","vi":"sợi thủy tinh; nhựa gia cố sợi thủy tinh"}],"examples":[{"en":"Our small fibreglass boat is easy to carry ashore.","vi":"Chiếc thuyền nhựa sợi thủy tinh nhỏ của chúng tôi rất dễ kéo lên bờ.","audioKind":"ex"},{"en":"Fibreglass is widely used in construction because it combines low weight with considerable strength and durability.","vi":"Sợi thủy tinh được sử dụng rộng rãi trong xây dựng vì nó kết hợp được trọng lượng nhẹ với độ bền và sức chịu lực đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"fibreglass insulation","vi":"vật liệu cách nhiệt bằng sợi thủy tinh"},{"en":"a fibreglass boat","vi":"một chiếc thuyền sợi thủy tinh"},{"en":"fibreglass panels","vi":"tấm nhựa sợi thủy tinh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cách viết theo Anh-Anh là fibreglass, còn Anh-Mỹ là fiberglass.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pivot', 'en-c1-52', 'pivot', '/ˈpɪvət/', 'C1', 'trục xoay; điểm tựa; xoay quanh trục; quay người; thay đổi định hướng; chuyển đổi chiến lược', 'n.', 'pivotal (adj.)', NULL, 'pivotal có nghĩa là quan trọng cốt lõi; pivot khi làm động từ còn chỉ sự chuyển đổi chiến lược.', 'The seesaw turned smoothly on its central pivot.', NULL, 'Chiếc bập bênh xoay mượt mà trên trục tựa chính giữa của nó.', '{"wordId":"pivot","ukIpa":"/ˈpɪvət/","usIpa":"/ˈpɪvət/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"A fixed point around which something turns.","vi":"trục xoay; điểm tựa"},{"pos":"v.","en":"To turn around a fixed point or on one foot.","vi":"xoay quanh trục; quay người"},{"pos":"v.","en":"To change direction, strategy, or focus.","vi":"thay đổi định hướng; chuyển đổi chiến lược"}],"examples":[{"en":"The seesaw turned smoothly on its central pivot.","vi":"Chiếc bập bênh xoay mượt mà trên trục tựa chính giữa của nó.","audioKind":"ex"},{"en":"Small companies may need to pivot towards online services as consumer habits change and operating costs rise.","vi":"Các công ty nhỏ có thể cần phải chuyển hướng sang các dịch vụ trực tuyến khi thói quen của người tiêu dùng thay đổi và chi phí vận hành tăng lên.","audioKind":"ex2"}],"collocations":[{"en":"a central pivot","vi":"trục quay trung tâm"},{"en":"pivot on one foot","vi":"xoay bằng một chân"},{"en":"pivot towards online services","vi":"chuyển hướng sang dịch vụ trực tuyến"}],"wordFamily":["pivotal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"pivotal có nghĩa là quan trọng cốt lõi; pivot khi làm động từ còn chỉ sự chuyển đổi chiến lược.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_computation', 'en-c1-52', 'computation', '/ˌkɑːmpjuˈteɪʃən/', 'C1', 'sự tính toán; phép tính', 'n.', 'compute (v.), computer (n.), computational (adj.)', 'Đồng nghĩa: calculation', 'Trang trọng hơn calculation, thường dùng trong toán học và khoa học máy tính.', 'A quick computation showed we could afford the sofa.', NULL, 'Một phép tính nhanh cho thấy chúng tôi đủ khả năng mua chiếc ghế sofa đó.', '{"wordId":"computation","ukIpa":"/ˌkɒmpjuˈteɪʃən/","usIpa":"/ˌkɑːmpjuˈteɪʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"The process of finding an answer using mathematics or computers.","vi":"sự tính toán; phép tính"}],"examples":[{"en":"A quick computation showed we could afford the sofa.","vi":"Một phép tính nhanh cho thấy chúng tôi đủ khả năng mua chiếc ghế sofa đó.","audioKind":"ex"},{"en":"Advances in computation allow researchers to analyse climate data and produce increasingly accurate weather forecasts.","vi":"Những tiến bộ trong công nghệ tính toán cho phép các nhà nghiên cứu phân tích dữ liệu khí hậu và đưa ra các dự báo thời tiết ngày càng chính xác.","audioKind":"ex2"}],"collocations":[{"en":"complex computation","vi":"phép tính phức tạp"},{"en":"numerical computation","vi":"tính toán số"},{"en":"parallel computation","vi":"tính toán song song"},{"en":"computation time","vi":"thời gian tính toán"}],"wordFamily":["compute (v.)","computer (n.)","computational (adj.)"],"synonyms":["calculation"],"antonyms":[],"tipVi":"Trang trọng hơn calculation, thường dùng trong toán học và khoa học máy tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_52_1', 'en-c1-52', 'Cách dùng “furnace” (n.) — lò luyện; lò công nghiệp', 'a blast furnace  ·  an electric furnace  ·  a gas furnace', 'Trong ngữ cảnh công nghiệp, từ này chỉ lò luyện kim; trong ngữ cảnh nhà ở kiểu Mỹ, nó thường chỉ hệ thống lò sưởi.', NULL, '[{"hanzi":"We watched molten metal pour from the glowing furnace.","pinyin":"","meaning":"Chúng tôi đứng xem kim loại nóng chảy tuôn ra từ chiếc lò luyện đang rực sáng."},{"hanzi":"Replacing an inefficient furnace can reduce household energy consumption and lower heating costs during winter.","pinyin":"","meaning":"Việc thay thế một chiếc lò sưởi kém hiệu quả có thể giảm mức tiêu thụ năng lượng của gia đình và cắt giảm chi phí sưởi ấm vào mùa đông."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_52_2', 'en-c1-52', 'Cách dùng “ingenious” (adj.) — khéo léo; tài tình; cósự sáng tạo độc đáo', 'an ingenious solution  ·  an ingenious device  ·  an ingenious design', 'Tránh nhầm lẫn: ingenious mang nghĩa khéo léo, tài tình, trong khi ingenuous mang nghĩa ngây thơ, chân thật.', 'Họ từ (Word Family): ingenuity (n.), ingeniously (adv.) | Đồng nghĩa: inventive, clever · Trái nghĩa: unimaginative', '[{"hanzi":"He built an ingenious watering system from old bottles.","pinyin":"","meaning":"Anh ấy đã chế tạo một hệ thống tưới cây vô cùng tài tình từ những chiếc chai cũ."},{"hanzi":"Ingenious designs can help architects create comfortable homes on small plots without sacrificing natural light.","pinyin":"","meaning":"Thiết kế khéo léo có thể giúp các kiến trúc sư tạo ra những ngôi nhà thoải mái trên những mảnh đất nhỏ mà vẫn đảm bảo ánh sáng tự nhiên."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_52_3', 'en-c1-52', 'Cách dùng “prototype” (n.) — mẫu thử nghiệm; bản mẫu', 'build a prototype  ·  test a prototype  ·  a working prototype', 'Thường chỉ dùng cho mô hình đời đầu nhằm kiểm tra và cải tiến, không phải là sản phẩm hoàn chỉnh cuối cùng.', 'Họ từ (Word Family): prototyping (n.), prototypical (adj.)', '[{"hanzi":"The designer showed us a prototype of her folding chair.","pinyin":"","meaning":"Nhà thiết kế đã cho chúng tôi xem một mẫu thử chiếc ghế gấp của cô ấy."},{"hanzi":"Testing a prototype allows engineers to identify design weaknesses before a product enters mass production.","pinyin":"","meaning":"Việc thử nghiệm mẫu thử giúp các kỹ sư phát hiện ra các điểm yếu trong thiết kế trước khi sản phẩm bước vào giai đoạn sản xuất hàng loạt."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_52_4', 'en-c1-52', 'Cách dùng “lubricate” (v.) — tra dầu mỡ; làm trơn', 'lubricate moving parts  ·  lubricate machinery  ·  lubricate with oil', 'Là ngoại động từ, đi thẳng tới đối tượng cần làm trơn; dùng với giới từ with khi muốn chỉ chất bôi trơn.', 'Họ từ (Word Family): lubrication (n.), lubricant (n.) | Đồng nghĩa: oil, grease', '[{"hanzi":"I lubricated the door hinges to stop that annoying squeak.","pinyin":"","meaning":"Tôi đã tra dầu vào bản lề cửa để dừng tiếng kêu có kẽo kẹt khó chịu đó lại."},{"hanzi":"Regularly lubricating industrial machinery reduces friction, improves energy efficiency, and extends the working life of essential equipment.","pinyin":"","meaning":"Việc tra dầu mỡ thường xuyên cho máy móc công nghiệp giúp giảm ma sát, nâng cao hiệu suất năng lượng và kéo dài tuổi thọ của các thiết bị thiết yếu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_52_1', 'en-c1-52', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_1_1', 'ten_c1_52_1', 'preset', 'I preset the oven timer before preparing the vegetables.', 'I preset the oven timer before preparing the vegetables.', '/ˌpriːˈset/', 'Tôi đã cài đặt sẵn thời gian trên lò nướng trước khi sơ chế rau củ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_1_2', 'ten_c1_52_1', 'ingenious', 'He built an ingenious watering system from old bottles.', 'He built an ingenious watering system from old bottles.', '/ɪnˈdʒiːniəs/', 'Anh ấy đã chế tạo một hệ thống tưới cây vô cùng tài tình từ những chiếc chai cũ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_1_3', 'ten_c1_52_1', 'operational', 'The lift is operational again after yesterday''s repairs.', 'The lift is operational again after yesterday''s repairs.', '/ˌɑːpəˈreɪʃənəl/', 'Chiếc thang máy đã hoạt động trở lại sau buổi sửa chữa ngày hôm qua.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_1_4', 'ten_c1_52_1', 'prototype', 'The designer showed us a prototype of her folding chair.', 'The designer showed us a prototype of her folding chair.', '/ˈproʊtətaɪp/', 'Nhà thiết kế đã cho chúng tôi xem một mẫu thử chiếc ghế gấp của cô ấy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_1_5', 'ten_c1_52_1', 'aero', 'We saw an old aero engine at the museum.', 'We saw an old aero engine at the museum.', '/ˈeroʊ/', 'Chúng tôi đã nhìn thấy một động cơ hàng không cổ trong bảo tàng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_1_6', 'ten_c1_52_1', 'computerization', 'Computerization means we no longer sort these files by hand.', 'Computerization means we no longer sort these files by hand.', '/kəmˌpjuːtərəˈzeɪʃən/', 'Việc tin học hóa có nghĩa là chúng ta không còn phải phân loại các tài liệu này bằng tay nữa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_1_7', 'ten_c1_52_1', 'analogue', 'This wooden model is an analogue of the bridge.', 'This wooden model is an analogue of the bridge.', '/ˈænəlɔːɡ/', 'Mô hình bằng gỗ này là một vật mô phỏng của cây cầu.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_1_8', 'ten_c1_52_1', 'mechanically', 'The apples are sorted mechanically before workers pack them.', 'The apples are sorted mechanically before workers pack them.', '/məˈkænɪkli/', 'Những quả táo được phân loại bằng máy móc trước khi công nhân đóng gói chúng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_52_1_1', 'en-c1-52', 'ten_c1_52_1', 'listening', 'listening', 'I preset the oven timer before preparing the vegetables.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc bập bênh xoay mượt mà trên trục tựa chính giữa của nó.","Thợ máy đã dùng một chiếc kích thủy lực để nâng chiếc xe của chúng tôi lên.","Tôi đã cài đặt sẵn thời gian trên lò nướng trước khi sơ chế rau củ.","Chiếc thang máy đã hoạt động trở lại sau buổi sửa chữa ngày hôm qua."]'::jsonb, 2, 'I preset the oven timer before preparing the vegetables. → Tôi đã cài đặt sẵn thời gian trên lò nướng trước khi sơ chế rau củ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_52_1_2', 'en-c1-52', 'ten_c1_52_1', 'listening', 'listening', 'He built an ingenious watering system from old bottles.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy đã chế tạo một hệ thống tưới cây vô cùng tài tình từ những chiếc chai cũ.","Mô hình bằng gỗ này là một vật mô phỏng của cây cầu.","Tôi đã tra dầu vào bản lề cửa để dừng tiếng kêu có kẽo kẹt khó chịu đó lại.","Một phép tính nhanh cho thấy chúng tôi đủ khả năng mua chiếc ghế sofa đó."]'::jsonb, 0, 'He built an ingenious watering system from old bottles. → Anh ấy đã chế tạo một hệ thống tưới cây vô cùng tài tình từ những chiếc chai cũ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_52_1_3', 'en-c1-52', 'ten_c1_52_1', 'listening', 'listening', 'The lift is operational again after yesterday''s repairs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã tra dầu vào bản lề cửa để dừng tiếng kêu có kẽo kẹt khó chịu đó lại.","Cô ấy đã nén những chiếc chăn vào một chiếc túi đựng đồ nhỏ gọn.","Chiếc thang máy đã hoạt động trở lại sau buổi sửa chữa ngày hôm qua.","Chiếc thuyền nhựa sợi thủy tinh nhỏ của chúng tôi rất dễ kéo lên bờ."]'::jsonb, 2, 'The lift is operational again after yesterday''s repairs. → Chiếc thang máy đã hoạt động trở lại sau buổi sửa chữa ngày hôm qua.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_52_2', 'en-c1-52', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_2_1', 'ten_c1_52_2', 'preset', 'Smart heating systems can be preset to reduce energy consumption during periods when buildings are unoccupied.', 'Smart heating systems can be preset to reduce energy consumption during periods when buildings are unoccupied.', '/ˌpriːˈset/', 'Các hệ thống sưởi thông minh có thể được lập trình sẵn để giảm mức tiêu thụ năng lượng trong những khoảng thời gian tòa nhà không có người sử dụng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_2_2', 'ten_c1_52_2', 'ingenious', 'Ingenious designs can help architects create comfortable homes on small plots without sacrificing natural light.', 'Ingenious designs can help architects create comfortable homes on small plots without sacrificing natural light.', '/ɪnˈdʒiːniəs/', 'Thiết kế khéo léo có thể giúp các kiến trúc sư tạo ra những ngôi nhà thoải mái trên những mảnh đất nhỏ mà vẫn đảm bảo ánh sáng tự nhiên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_2_3', 'ten_c1_52_2', 'operational', 'Although renewable energy projects require substantial investment, their operational costs can remain relatively low.', 'Although renewable energy projects require substantial investment, their operational costs can remain relatively low.', '/ˌɑːpəˈreɪʃənəl/', 'Mặc dù các dự án năng lượng tái tạo đòi hỏi khoản đầu tư lớn, chi phí vận hành của chúng vẫn có thể duy trì ở mức tương đối thấp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_2_4', 'ten_c1_52_2', 'prototype', 'Testing a prototype allows engineers to identify design weaknesses before a product enters mass production.', 'Testing a prototype allows engineers to identify design weaknesses before a product enters mass production.', '/ˈproʊtətaɪp/', 'Việc thử nghiệm mẫu thử giúp các kỹ sư phát hiện ra các điểm yếu trong thiết kế trước khi sản phẩm bước vào giai đoạn sản xuất hàng loạt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_2_5', 'ten_c1_52_2', 'aero', 'Improvements in aero engine design can reduce fuel consumption and emissions from commercial aircraft.', 'Improvements in aero engine design can reduce fuel consumption and emissions from commercial aircraft.', '/ˈeroʊ/', 'Những cải tiến trong thiết kế động cơ hàng không có thể làm giảm lượng tiêu thụ nhiên liệu và khí thải từ các máy bay thương mại.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_52_2_6', 'ten_c1_52_2', 'computerization', 'The computerization of hospital records can improve efficiency, but it also requires strong safeguards for patient privacy.', 'The computerization of hospital records can improve efficiency, but it also requires strong safeguards for patient privacy.', '/kəmˌpjuːtərəˈzeɪʃən/', 'Việc tin học hóa hồ sơ bệnh án tại các bệnh viện có thể nâng cao hiệu quả, nhưng đồng thời cũng đòi hỏi các biện pháp bảo vệ nghiêm ngặt đối với quyền riêng tư của bệnh nhân.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_52_2_1', 'en-c1-52', 'ten_c1_52_2', 'listening', 'listening', 'Smart heating systems can be preset to reduce energy consumption during periods when buildings are unoccupied.', NULL, 'Trong câu vừa nghe, từ “preset” mang nghĩa nào sau đây?', '["cài đặt sẵn; thiết lập trước","quá mức kỹ tính; khó chiều; kén chọn","thanh bình; yên ả","răng bánh xe; bánh răng"]'::jsonb, 0, '“preset” (/ˌpriːˈset/): cài đặt sẵn; thiết lập trước. Câu đầy đủ: Smart heating systems can be preset to reduce energy consumption during periods when buildings are unoccupied.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_52_2_2', 'en-c1-52', 'ten_c1_52_2', 'listening', 'listening', 'Ingenious designs can help architects create comfortable homes on small plots without sacrificing natural light.', NULL, 'Trong câu vừa nghe, từ “ingenious” mang nghĩa nào sau đây?', '["sự ẩn náu; sự bảo vệ (khỏi nguy hiểm, rắc rối, thời tiết xấu)","khéo léo; tài tình; cósự sáng tạo độc đáo","khẩu hiệu hô vang; tiếng hô nhịp nhàng","chiếm lĩnh tâm trí; làm bận tâm; chi phối suy nghĩ"]'::jsonb, 1, '“ingenious” (/ɪnˈdʒiːniəs/): khéo léo; tài tình; cósự sáng tạo độc đáo. Câu đầy đủ: Ingenious designs can help architects create comfortable homes on small plots without sacrificing natural light.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
