INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_1', 'en-c1-52', NULL, 'comprehensive_test', 'listening', 'preset', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cài đặt sẵn; thiết lập trước","lời chào hỏi; lời chào đầu thư","lật ngược; đảo chiều; đảo trật tự","sương; giọt sương"]'::jsonb, 0, 'preset (/ˌpriːˈset/) → cài đặt sẵn; thiết lập trước; được cài đặt sẵn; được định trước; chế độ cài đặt sẵn; tùy chọn được lưu trước', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_2', 'en-c1-52', NULL, 'comprehensive_test', 'listening', 'He built an ingenious watering system from old bottles.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy đã chế tạo một hệ thống tưới cây vô cùng tài tình từ những chiếc chai cũ.","Những quả táo được phân loại bằng máy móc trước khi công nhân đóng gói chúng.","Chiếc thuyền nhựa sợi thủy tinh nhỏ của chúng tôi rất dễ kéo lên bờ.","Chúng tôi đứng xem kim loại nóng chảy tuôn ra từ chiếc lò luyện đang rực sáng."]'::jsonb, 0, 'He built an ingenious watering system from old bottles. → Anh ấy đã chế tạo một hệ thống tưới cây vô cùng tài tình từ những chiếc chai cũ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_3', 'en-c1-52', NULL, 'comprehensive_test', 'listening', 'operational', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bản thông số kỹ thuật; quy cách kỹ thuật","làm tê liệt; tàn phá năng lực hoạt động","cuộn vi phim; phim thu nhỏ","sẵn sàng và có thể hoạt động hoặc sử dụng được"]'::jsonb, 3, 'operational (/ˌɑːpəˈreɪʃənəl/) → sẵn sàng và có thể hoạt động hoặc sử dụng được; thuộc về cách thức vận hành của một tổ chức hay hệ thống', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_4', 'en-c1-52', NULL, 'comprehensive_test', 'listening', 'The designer showed us a prototype of her folding chair.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà thiết kế đã cho chúng tôi xem một mẫu thử chiếc ghế gấp của cô ấy.","Cửa hàng đã đổi cho tôi chiếc ấm đun nước bị lỗi mà không hề phàn nàn gì.","Những quả táo được phân loại bằng máy móc trước khi công nhân đóng gói chúng.","Việc tin học hóa có nghĩa là chúng ta không còn phải phân loại các tài liệu này bằng tay nữa."]'::jsonb, 0, 'The designer showed us a prototype of her folding chair. → Nhà thiết kế đã cho chúng tôi xem một mẫu thử chiếc ghế gấp của cô ấy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_5', 'en-c1-52', NULL, 'comprehensive_test', 'listening', 'aero', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về hàng không; thuộc về máy bay","sự mâu thuẫn; sự trái ngược","nằm hoặc ngồi duỗi dài chân tay","lang thang; đi lang thang; thả bộ"]'::jsonb, 0, 'aero (/ˈeroʊ/) → thuộc về hàng không; thuộc về máy bay', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_6', 'en-c1-52', NULL, 'comprehensive_test', 'listening', 'Computerization means we no longer sort these files by hand.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc tin học hóa có nghĩa là chúng ta không còn phải phân loại các tài liệu này bằng tay nữa.","Sên xe đạp cần được tra dầu bôi trơn sau trận mưa tầm tã đó.","Tôi đã cài đặt sẵn thời gian trên lò nướng trước khi sơ chế rau củ.","Nhà thiết kế đã cho chúng tôi xem một mẫu thử chiếc ghế gấp của cô ấy."]'::jsonb, 0, 'Computerization means we no longer sort these files by hand. → Việc tin học hóa có nghĩa là chúng ta không còn phải phân loại các tài liệu này bằng tay nữa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_7', 'en-c1-52', NULL, 'comprehensive_test', 'listening', 'analogue', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vật tương tự; vật đối ứng","hất cẳng; lật đổ; truất ngôi","tích lũy dần; thu về dần theo thời gian","khía cạnh; mặt"]'::jsonb, 0, 'analogue (/ˈænəlɔːɡ/) → vật tương tự; vật đối ứng; mô phỏng; tương tự (không dùng kỹ thuật số)', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_8', 'en-c1-52', NULL, 'comprehensive_test', 'listening', 'The apples are sorted mechanically before workers pack them.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiệm bánh của chúng tôi tiếp tục đổi mới với các hương vị bánh mì độc đáo.","Các công nhân đã sửa chữa đường ống dẫn nước dưới lòng đường của chúng ta hôm nay.","Những quả táo được phân loại bằng máy móc trước khi công nhân đóng gói chúng.","Một phép tính nhanh cho thấy chúng tôi đủ khả năng mua chiếc ghế sofa đó."]'::jsonb, 2, 'The apples are sorted mechanically before workers pack them. → Những quả táo được phân loại bằng máy móc trước khi công nhân đóng gói chúng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
