INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_18', 'en-c1-52', NULL, 'comprehensive_test', 'reading', NULL, 'Smart heating systems can be preset to reduce energy consumption during periods when buildings are unoccupied.', 'Dựa vào câu trên, từ “preset” có nghĩa phù hợp nhất là gì?', '["khơi gợi sự tò mò; làm thích thú","cài đặt sẵn; thiết lập trước","khổ sở; khốn khổ; bất hạnh","chủ doanh nghiệp; chủ tiệm (chủ sở hữu của một cơ sở kinh doanh như cửa hàng hoặc khách sạn)"]'::jsonb, 1, 'preset: cài đặt sẵn; thiết lập trước; được cài đặt sẵn; được định trước; chế độ cài đặt sẵn; tùy chọn được lưu trước. Dịch cả câu: Các hệ thống sưởi thông minh có thể được lập trình sẵn để giảm mức tiêu thụ năng lượng trong những khoảng thời gian tòa nhà không có người sử dụng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_19', 'en-c1-52', NULL, 'comprehensive_test', 'reading', NULL, 'Ingenious designs can help architects create comfortable homes on small plots without sacrificing natural light.', 'Dựa vào câu trên, từ “ingenious” có nghĩa phù hợp nhất là gì?', '["hợp chất oxit","nhẫn tâm; tàn nhẫn; quyết liệt (bất chấp gây tổn thương cho người khác)","chuyến đi hành hương","khéo léo; tài tình; cósự sáng tạo độc đáo"]'::jsonb, 3, 'ingenious: khéo léo; tài tình; cósự sáng tạo độc đáo. Dịch cả câu: Thiết kế khéo léo có thể giúp các kiến trúc sư tạo ra những ngôi nhà thoải mái trên những mảnh đất nhỏ mà vẫn đảm bảo ánh sáng tự nhiên.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_20', 'en-c1-52', NULL, 'comprehensive_test', 'reading', NULL, 'Although renewable energy projects require substantial investment, their operational costs can remain relatively low.', 'Dựa vào câu trên, từ “operational” có nghĩa phù hợp nhất là gì?', '["sự sụt giảm; mức giảm","sẵn sàng và có thể hoạt động hoặc sử dụng được","mưa đá (những hạt băng nhỏ rơi từ mây xuống)","đột ngột; bất ngờ"]'::jsonb, 1, 'operational: sẵn sàng và có thể hoạt động hoặc sử dụng được; thuộc về cách thức vận hành của một tổ chức hay hệ thống. Dịch cả câu: Mặc dù các dự án năng lượng tái tạo đòi hỏi khoản đầu tư lớn, chi phí vận hành của chúng vẫn có thể duy trì ở mức tương đối thấp.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_21', 'en-c1-52', NULL, 'comprehensive_test', 'reading', NULL, 'Testing a prototype allows engineers to identify design weaknesses before a product enters mass production.', 'Dựa vào câu trên, từ “prototype” có nghĩa phù hợp nhất là gì?', '["kìm nén; nén; ngăn chặn","nằm hoặc ngồi duỗi dài chân tay","mẫu thử nghiệm; bản mẫu","huyết tương"]'::jsonb, 2, 'prototype: mẫu thử nghiệm; bản mẫu; làm mẫu thử; chế tạo nguyên mẫu. Dịch cả câu: Việc thử nghiệm mẫu thử giúp các kỹ sư phát hiện ra các điểm yếu trong thiết kế trước khi sản phẩm bước vào giai đoạn sản xuất hàng loạt.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_22', 'en-c1-52', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sợi thủy tinh; nhựa gia cố sợi thủy tinh”', '["ramification","mania","fibreglass","pasture"]'::jsonb, 2, 'sợi thủy tinh; nhựa gia cố sợi thủy tinh → fibreglass (/ˈfaɪbərɡlæs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_23', 'en-c1-52', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trục xoay; điểm tựa”', '["aggregation","pivot","mobilize","revelation"]'::jsonb, 1, 'trục xoay; điểm tựa → pivot (/ˈpɪvət/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_52_24', 'en-c1-52', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự tính toán; phép tính”', '["hierarchy","simulate","computation","viable"]'::jsonb, 2, 'sự tính toán; phép tính → computation (/ˌkɑːmpjuˈteɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-53', 'en', 'Bài 53: Công nghệ & Kỹ thuật (3) - CEFR C1', 'CEFR C1', 'C1 · Công nghệ', '20 từ vựng Tiếng Anh CEFR C1 chủ đề công nghệ & kỹ thuật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5053, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cartridge', 'en-c1-53', 'cartridge', '/ˈkɑːrtrɪdʒ/', 'C1', 'hộp mực; ống mực (thay thế được cho máy móc); viên đạn; vỏ đạn', 'n.', NULL, NULL, 'Nét nghĩa cốt lõi là ống hoặc hộp có thể lắp vào thiết bị; trong ngữ cảnh máy in thường chỉ hộp mực.', 'I replaced the empty cartridge before printing my homework.', NULL, 'Tôi đã thay hộp mực đã hết trước khi in bài tập về nhà.', '{"wordId":"cartridge","ukIpa":"/ˈkɑːtrɪdʒ/","usIpa":"/ˈkɑːrtrɪdʒ/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"a replaceable container holding material needed by a machine","vi":"hộp mực; ống mực (thay thế được cho máy móc)"},{"pos":"n.","en":"a case containing an explosive charge and usually a bullet","vi":"viên đạn; vỏ đạn"}],"examples":[{"en":"I replaced the empty cartridge before printing my homework.","vi":"Tôi đã thay hộp mực đã hết trước khi in bài tập về nhà.","audioKind":"ex"},{"en":"Recycling printer cartridges can reduce plastic waste and recover materials that would otherwise enter landfill sites.","vi":"Việc tái chế hộp mực máy in có thể làm giảm rác thải nhựa và thu hồi các vật liệu vốn dĩ sẽ bị chôn lấp ở các bãi rác.","audioKind":"ex2"}],"collocations":[{"en":"ink cartridge","vi":"hộp mực in"},{"en":"toner cartridge","vi":"ống mực; hộp mực laser"},{"en":"replace a cartridge","vi":"thay hộp mực"},{"en":"spent cartridge","vi":"vỏ đạn đã bắn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nét nghĩa cốt lõi là ống hoặc hộp có thể lắp vào thiết bị; trong ngữ cảnh máy in thường chỉ hộp mực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rotary', 'en-c1-53', 'rotary', '/ˈroʊtəri/', 'C1', 'quay; chuyển động theo vòng tròn; chạy bằng cơ chế quay; nút giao thông hình vòng xuyến', 'adj.', 'rotate (v.), rotation (n.), rotational (adj.)', NULL, 'Thường dùng để mô tả máy móc có chuyển động quay; không đồng nghĩa với từ rotating chỉ tính chất luân phiên.', 'Dad uses a rotary mower to cut the grass.', NULL, 'Bố dùng máy cắt cỏ quay để cắt cỏ trên sân.', '{"wordId":"rotary","ukIpa":"/ˈrəʊtəri/","usIpa":"/ˈroʊtəri/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"Moving in circles, or operating through circular movement.","vi":"quay; chuyển động theo vòng tròn; chạy bằng cơ chế quay"},{"pos":"n.","en":"A circular road junction, called a roundabout in British English.","vi":"nút giao thông hình vòng xuyến"}],"examples":[{"en":"Dad uses a rotary mower to cut the grass.","vi":"Bố dùng máy cắt cỏ quay để cắt cỏ trên sân.","audioKind":"ex"},{"en":"Rotary motion is widely used in industrial machinery because it allows continuous and efficient operation.","vi":"Chuyển động quay được ứng dụng rộng rãi trong máy móc công nghiệp vì nó cho phép vận hành liên tục và hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"rotary motion","vi":"chuyển động quay"},{"en":"rotary engine","vi":"động cơ rô-to"},{"en":"rotary mower","vi":"máy cắt cỏ quay"}],"wordFamily":["rotate (v.)","rotation (n.)","rotational (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng để mô tả máy móc có chuyển động quay; không đồng nghĩa với từ rotating chỉ tính chất luân phiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refinement', 'en-c1-53', 'refinement', '/rɪˈfaɪnmənt/', 'C1', 'sự cải tiến; sự tinh chỉnh nhỏ để hoàn thiện hơn; sự tinh chế; quá trình loại bỏ tạp chất khỏi vật liệu; sự tao nhã; phong thái lịch sự và có gu thẩm mỹ', 'n.', 'refine (v.), refined (adj.), refinery (n.)', 'Đồng nghĩa: improvement, polish', 'Các sự cải tiến cụ thể có thể đếm được; trong khi quá trình cải tiến, tinh chế hay sự tao nhã thường là danh từ không đếm được.', 'One small refinement made the chair much more comfortable.', NULL, 'Chỉ một cải tiến nhỏ đã làm cho chiếc ghế trở nên thoải mái hơn rất nhiều.', '{"wordId":"refinement","ukIpa":"/rɪˈfaɪnmənt/","usIpa":"/rɪˈfaɪnmənt/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"A small change that makes something better or more effective.","vi":"sự cải tiến; sự tinh chỉnh nhỏ để hoàn thiện hơn"},{"pos":"n.","en":"The process of removing unwanted substances from a material.","vi":"sự tinh chế; quá trình loại bỏ tạp chất khỏi vật liệu"},{"pos":"n.","en":"Polite behaviour and good taste in social or cultural matters.","vi":"sự tao nhã; phong thái lịch sự và có gu thẩm mỹ"}],"examples":[{"en":"One small refinement made the chair much more comfortable.","vi":"Chỉ một cải tiến nhỏ đã làm cho chiếc ghế trở nên thoải mái hơn rất nhiều.","audioKind":"ex"},{"en":"Continued refinement of water treatment methods can improve public health while reducing the cost of supplying clean water.","vi":"Việc tiếp tục cải tiến các phương pháp xử lý nước có thể nâng cao sức khỏe cộng đồng đồng thời giảm chi phí cung cấp nước sạch.","audioKind":"ex2"}],"collocations":[{"en":"further refinement","vi":"sự hoàn thiện thêm"},{"en":"a refinement to the design","vi":"một điểm cải tiến trong thiết kế"},{"en":"the refinement of raw materials","vi":"quá trình tinh chế nguyên liệu thô"}],"wordFamily":["refine (v.)","refined (adj.)","refinery (n.)"],"synonyms":["improvement","polish"],"antonyms":[],"tipVi":"Các sự cải tiến cụ thể có thể đếm được; trong khi quá trình cải tiến, tinh chế hay sự tao nhã thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transistor', 'en-c1-53', 'transistor', '/trænˈzɪstər/', 'C1', 'bóng bán dẫn; tranzito', 'n.', NULL, NULL, 'Chỉ linh kiện điện tử; transistor radio mới là đài bán dẫn.', 'She carefully replaced the damaged transistor inside the old radio.', NULL, 'Cô ấy cẩn thận thay thế chiếc bóng bán dẫn bị hỏng bên trong chiếc đài cũ.', '{"wordId":"transistor","ukIpa":"/trænˈzɪstə/","usIpa":"/trænˈzɪstər/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"An electronic component that amplifies signals or switches electrical current.","vi":"bóng bán dẫn; tranzito"}],"examples":[{"en":"She carefully replaced the damaged transistor inside the old radio.","vi":"Cô ấy cẩn thận thay thế chiếc bóng bán dẫn bị hỏng bên trong chiếc đài cũ.","audioKind":"ex"},{"en":"The development of smaller transistors has enabled computers to process information faster while consuming less power.","vi":"Sự phát triển của các bóng bán dẫn nhỏ hơn đã giúp máy tính xử lý thông tin nhanh hơn mà lại tiêu thụ ít năng lượng hơn.","audioKind":"ex2"}],"collocations":[{"en":"transistor radio","vi":"máy thu thanh bán dẫn"},{"en":"silicon transistor","vi":"bóng bán dẫn silicon"},{"en":"transistor circuit","vi":"mạch bán dẫn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ linh kiện điện tử; transistor radio mới là đài bán dẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incompatible', 'en-c1-53', 'incompatible', '/ˌɪnkəmˈpætəbl/', 'C1', 'không tương thích; không tương hợp; không hợp nhau; không thể hòa hợp', 'adj.', 'compatible (adj.), compatibility (n.), incompatibility (n.)', 'Đồng nghĩa: conflicting · Trái nghĩa: compatible', 'Luôn đi kèm giới từ compatible với cấu trúc incompatible with, không dùng incompatible to.', 'These headphones are incompatible with my old phone.', NULL, 'Chiếc tai nghe này không tương thích với chiếc điện thoại cũ của tôi.', '{"wordId":"incompatible","ukIpa":"/ˌɪnkəmˈpætəbl/","usIpa":"/ˌɪnkəmˈpætəbl/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"unable to work or exist together successfully","vi":"không tương thích; không tương hợp"},{"pos":"adj.","en":"too different in character to have a good relationship","vi":"không hợp nhau; không thể hòa hợp"}],"examples":[{"en":"These headphones are incompatible with my old phone.","vi":"Chiếc tai nghe này không tương thích với chiếc điện thoại cũ của tôi.","audioKind":"ex"},{"en":"Rapid industrial expansion is often incompatible with efforts to protect fragile ecosystems without effective regulation.","vi":"Sự bành trướng công nghiệp nhanh chóng thường mâu thuẫn với các nỗ lực bảo vệ hệ sinh thái mong manh nếu thiếu đi các quy định quản lý hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"incompatible with","vi":"không tương thích với"},{"en":"mutually incompatible","vi":"không thể dung thứ cho nhau"},{"en":"incompatible goals","vi":"các mục tiêu mâu thuẫn nhau"}],"wordFamily":["compatible (adj.)","compatibility (n.)","incompatibility (n.)"],"synonyms":["conflicting"],"antonyms":["compatible"],"tipVi":"Luôn đi kèm giới từ compatible với cấu trúc incompatible with, không dùng incompatible to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_piston', 'en-c1-53', 'piston', '/ˈpɪstən/', 'C1', 'pít-tông; tr Pít-tông', 'n.', NULL, NULL, 'Pít-tông chuyển động tịnh tiến bên trong cylinder (xi-lanh).', 'The mechanic removed a damaged piston from the engine.', NULL, 'Thợ máy đã tháo một pít-tông bị hỏng ra khỏi động cơ.', '{"wordId":"piston","ukIpa":"/ˈpɪstən/","usIpa":"/ˈpɪstən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"a part that moves inside a cylinder in engines or pumps","vi":"pít-tông; tr Pít-tông"}],"examples":[{"en":"The mechanic removed a damaged piston from the engine.","vi":"Thợ máy đã tháo một pít-tông bị hỏng ra khỏi động cơ.","audioKind":"ex"},{"en":"In a conventional engine, expanding gases push each piston, converting energy from fuel into mechanical motion.","vi":"Trong một động cơ thông thường, khí giãn nở đẩy từng pít-tông, chuyển hóa năng lượng từ nhiên liệu thành chuyển động cơ học.","audioKind":"ex2"}],"collocations":[{"en":"piston ring","vi":"xéc-măng pít-tông"},{"en":"piston engine","vi":"động cơ pít-tông"},{"en":"piston rod","vi":"thanh pít-tông"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Pít-tông chuyển động tịnh tiến bên trong cylinder (xi-lanh).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supersonic', 'en-c1-53', 'supersonic', '/ˌsuːpɚˈsɑːnɪk/', 'C1', 'siêu thanh, vượt tốc độ âm thanh', 'adj.', 'sonic (adj.), subsonic (adj.)', 'Trái nghĩa: subsonic', 'Chỉ tốc độ vượt qua tốc độ âm thanh; "siêu âm" (trong y học/vật lý) thường dùng ultrasonic.', 'We heard a loud boom as the supersonic aircraft passed.', NULL, 'Chúng tôi nghe thấy một tiếng nổ lớn khi chiếc máy bay siêu thanh bay qua.', '{"wordId":"supersonic","ukIpa":"/ˌsuːpəˈsɒnɪk/","usIpa":"/ˌsuːpɚˈsɑːnɪk/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"Travelling faster than sound, or involving such speeds.","vi":"siêu thanh, vượt tốc độ âm thanh"}],"examples":[{"en":"We heard a loud boom as the supersonic aircraft passed.","vi":"Chúng tôi nghe thấy một tiếng nổ lớn khi chiếc máy bay siêu thanh bay qua.","audioKind":"ex"},{"en":"Supersonic passenger aircraft could shorten international journeys, but their noise and fuel consumption remain major concerns.","vi":"Máy bay chở khách siêu thanh có thể rút ngắn thời gian di chuyển quốc tế, nhưng tiếng ồn và mức tiêu thụ nhiên liệu của chúng vẫn là những vấn đề lớn.","audioKind":"ex2"}],"collocations":[{"en":"supersonic speed","vi":"tốc độ siêu thanh"},{"en":"supersonic aircraft","vi":"máy bay siêu thanh"},{"en":"supersonic flight","vi":"chuyến bay siêu thanh"}],"wordFamily":["sonic (adj.)","subsonic (adj.)"],"synonyms":[],"antonyms":["subsonic"],"tipVi":"Chỉ tốc độ vượt qua tốc độ âm thanh; \"siêu âm\" (trong y học/vật lý) thường dùng ultrasonic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amplifier', 'en-c1-53', 'amplifier', '/ˈæmplɪfaɪər/', 'C1', 'bộ khuếch đại, máy tăng âm, loa phóng thanh', 'n.', 'amplify (v.), amplification (n.)', 'Đồng nghĩa: amp', 'amplifier dùng để khuếch đại tín hiệu điện/âm thanh; speaker chuyển đổi tín hiệu đó thành âm thanh phát ra ngoài.', 'He connected his guitar to a small amplifier.', NULL, 'Anh ấy cắm cây đàn guitar của mình vào một chiếc amply nhỏ.', '{"wordId":"amplifier","ukIpa":"/ˈæmplɪfaɪə/","usIpa":"/ˈæmplɪfaɪər/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"a device that increases the strength of sound or electrical signals","vi":"bộ khuếch đại, máy tăng âm, loa phóng thanh"}],"examples":[{"en":"He connected his guitar to a small amplifier.","vi":"Anh ấy cắm cây đàn guitar của mình vào một chiếc amply nhỏ.","audioKind":"ex"},{"en":"An amplifier can make a speaker''s voice clearly audible throughout a large lecture hall.","vi":"Bộ khuếch đại có thể giúp giọng nói của diễn giả nghe rõ mồn một trong toàn bộ hội trường lớn.","audioKind":"ex2"}],"collocations":[{"en":"a guitar amplifier","vi":"amply guitar"},{"en":"a power amplifier","vi":"bộ khuếch đại công suất"},{"en":"a signal amplifier","vi":"bộ khuếch đại tín hiệu"}],"wordFamily":["amplify (v.)","amplification (n.)"],"synonyms":["amp"],"antonyms":[],"tipVi":"amplifier dùng để khuếch đại tín hiệu điện/âm thanh; speaker chuyển đổi tín hiệu đó thành âm thanh phát ra ngoài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embed', 'en-c1-53', 'embed', '/ɪmˈbed/', 'C1', 'gắn chặt vào; làm chìm sâu vào; nhúng nội dung số vào trang web hoặc tài liệu; làm cho thấm nhuần; ghi sâu vào hệ thống hoặc văn hóa', 'v.', 'embedded (adj.), embedding (n.)', 'Đồng nghĩa: implant, insert', 'Dạng quá khứ embedded và phân từ embedding đều được gấp đôi chữ cái d.', 'The artist embedded small shells in the wet clay.', NULL, 'Người nghệ sĩ đã gắn những chiếc vỏ sò nhỏ vào lớp đất sét còn ẩm.', '{"wordId":"embed","ukIpa":"/ɪmˈbed/","usIpa":"/ɪmˈbed/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"to fix something firmly inside a surrounding material","vi":"gắn chặt vào; làm chìm sâu vào"},{"pos":"v.","en":"to place digital content within a webpage or document","vi":"nhúng nội dung số vào trang web hoặc tài liệu"},{"pos":"v.","en":"to make something an established part of a system or culture","vi":"làm cho thấm nhuần; ghi sâu vào hệ thống hoặc văn hóa"}],"examples":[{"en":"The artist embedded small shells in the wet clay.","vi":"Người nghệ sĩ đã gắn những chiếc vỏ sò nhỏ vào lớp đất sét còn ẩm.","audioKind":"ex"},{"en":"Schools should embed environmental awareness in everyday lessons rather than discuss sustainability only on special occasions.","vi":"Các trường học nên lồng ghép ý thức bảo vệ môi trường vào các bài học hàng ngày thay vì chỉ bàn về phát triển bền vững trong những dịp đặc biệt.","audioKind":"ex2"}],"collocations":[{"en":"be embedded in","vi":"được gắn vào; bắt nguồn sâu xa trong"},{"en":"embed a video","vi":"nhúng một video"},{"en":"deeply embedded","vi":"được ghi sâu vào"}],"wordFamily":["embedded (adj.)","embedding (n.)"],"synonyms":["implant","insert"],"antonyms":[],"tipVi":"Dạng quá khứ embedded và phân từ embedding đều được gấp đôi chữ cái d.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cog', 'en-c1-53', 'cog', '/kɑːɡ/', 'C1', 'răng bánh xe; bánh răng; mắt xích nhỏ; người đóng vai trò nhỏ trong một tổ chức lớn', 'n.', NULL, NULL, 'Cụm a cog in the machine dùng để ẩn chỉ một nhân vật nhỏ bé, mờ nhạt trong một tổ chức cồng kềnh.', 'A broken cog stopped the old clock from working.', NULL, 'Một chiếc bánh răng bị gãy đã làm cho chiếc đồng hồ cổ ngừng hoạt động.', '{"wordId":"cog","ukIpa":"/kɒɡ/","usIpa":"/kɑːɡ/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"A tooth on a gear, or the gear itself","vi":"răng bánh xe; bánh răng"},{"pos":"n.","en":"Someone with a small role in a large organisation","vi":"mắt xích nhỏ; người đóng vai trò nhỏ trong một tổ chức lớn"}],"examples":[{"en":"A broken cog stopped the old clock from working.","vi":"Một chiếc bánh răng bị gãy đã làm cho chiếc đồng hồ cổ ngừng hoạt động.","audioKind":"ex"},{"en":"Employees may lose motivation if they feel like a cog in a machine rather than valued contributors.","vi":"Nhân viên có thể mất đi động lực nếu họ cảm thấy mình chỉ là một mắt xích nhỏ trong cỗ máy hơn là những người đóng góp có giá trị.","audioKind":"ex2"}],"collocations":[{"en":"cog wheel","vi":"bánh răng"},{"en":"a cog in the machine","vi":"một mắt xích nhỏ trong cỗ máy"},{"en":"broken cog","vi":"răng cưa bị gãy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm a cog in the machine dùng để ẩn chỉ một nhân vật nhỏ bé, mờ nhạt trong một tổ chức cồng kềnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_turbine', 'en-c1-53', 'turbine', '/ˈtɝːbaɪn/', 'C1', 'tuabin; máy phát điện chạy bằng sức gió/nước/hơi nước', 'n.', NULL, NULL, 'Trọng âm rơi vào âm tiết đầu tiên; wind turbine chỉ tuabin gió.', 'We watched the wind turbine turning slowly above the fields.', NULL, 'Chúng tôi ngắm nhìn chiếc tuabin gió quay chậm rãi phía trên cánh đồng.', '{"wordId":"turbine","ukIpa":"/ˈtɜːbaɪn/","usIpa":"/ˈtɝːbaɪn/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"A machine whose blades turn when pushed by moving fluid.","vi":"tuabin; máy phát điện chạy bằng sức gió/nước/hơi nước"}],"examples":[{"en":"We watched the wind turbine turning slowly above the fields.","vi":"Chúng tôi ngắm nhìn chiếc tuabin gió quay chậm rãi phía trên cánh đồng.","audioKind":"ex"},{"en":"Installing offshore wind turbines can increase renewable electricity generation, although potential impacts on marine ecosystems require careful assessment.","vi":"Việc lắp đặt các tuabin gió ngoài khơi có thể gia tăng sản lượng điện tái tạo, dù những tác động tiềm ẩn đối với hệ sinh thái biển vẫn cần được đánh giá cẩn trọng.","audioKind":"ex2"}],"collocations":[{"en":"wind turbine","vi":"tuabin gió"},{"en":"steam turbine","vi":"tuabin hơi nước"},{"en":"gas turbine","vi":"tuabin khí"},{"en":"turbine blade","vi":"cánh tuabin"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trọng âm rơi vào âm tiết đầu tiên; wind turbine chỉ tuabin gió.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_propeller', 'en-c1-53', 'propeller', '/prəˈpelər/', 'C1', 'chân vịt; cánh quạt (tàu thuyền hoặc máy bay)', 'n.', 'propel (v.), propulsion (n.)', NULL, 'Propel là thúc đẩy; propeller là bộ phận tạo ra lực đẩy tức là chân vịt hoặc cánh quạt.', 'The boat''s propeller churned the water into white foam.', NULL, 'Chân vịt của con thuyền khuấy tung dòng nước thành bọt trắng.', '{"wordId":"propeller","ukIpa":"/prəˈpelə/","usIpa":"/prəˈpelər/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"a rotating device with blades that drives boats or aircraft","vi":"chân vịt; cánh quạt (tàu thuyền hoặc máy bay)"}],"examples":[{"en":"The boat''s propeller churned the water into white foam.","vi":"Chân vịt của con thuyền khuấy tung dòng nước thành bọt trắng.","audioKind":"ex"},{"en":"Engineers are developing quieter propeller designs to reduce the impact of shipping noise on marine wildlife.","vi":"Các kỹ sư đang phát triển thiết kế chân vịt êm hơn nhằm giảm tác động của tiếng ồn hàng hải đối với động vật hoang dã dưới nước.","audioKind":"ex2"}],"collocations":[{"en":"aircraft propeller","vi":"cánh quạt máy bay"},{"en":"ship''s propeller","vi":"chân vịt tàu thủy"},{"en":"propeller blade","vi":"cánh chân vịt"}],"wordFamily":["propel (v.)","propulsion (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Propel là thúc đẩy; propeller là bộ phận tạo ra lực đẩy tức là chân vịt hoặc cánh quạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_horsepower', 'en-c1-53', 'horsepower', '/ˈhɔːrspaʊər/', 'C1', 'mã lực (đơn vị đo công suất động cơ)', 'n.', NULL, NULL, 'Sau số từ, horsepower không thêm s; nó đo công suất chứ không đo tốc độ.', 'This tractor has enough horsepower to pull the heavy trailer.', NULL, 'Chiếc máy kéo này có đủ mã lực để kéo chiếc rơ-moóc nặng nề.', '{"wordId":"horsepower","ukIpa":"/ˈhɔːspaʊə/","usIpa":"/ˈhɔːrspaʊər/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"A unit used to measure the power of an engine.","vi":"mã lực (đơn vị đo công suất động cơ)"}],"examples":[{"en":"This tractor has enough horsepower to pull the heavy trailer.","vi":"Chiếc máy kéo này có đủ mã lực để kéo chiếc rơ-moóc nặng nề.","audioKind":"ex"},{"en":"Although greater horsepower can improve vehicle performance, fuel efficiency remains a major consideration for many consumers.","vi":"Mặc dù mã lực lớn hơn có thể cải thiện hiệu suất xe, hiệu quả nhiên liệu vẫn là cân nhắc quan trọng đối với nhiều người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"engine horsepower","vi":"mã lực động cơ"},{"en":"brake horsepower","vi":"mã lực phanh"},{"en":"high horsepower","vi":"mã lực lớn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Sau số từ, horsepower không thêm s; nó đo công suất chứ không đo tốc độ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shaft', 'en-c1-53', 'shaft', '/ʃæft/', 'C1', 'giếng (thang máy, thông gió); đường hầm thẳng đứng; cán; trục; tay cầm; luồng (sáng); tia (nắng)', 'n.', NULL, NULL, 'Giếng dùng shaft; tiếng Anh-Anh lift shaft tương đương tiếng Anh-Mỹ elevator shaft.', 'The lift stopped halfway up the narrow shaft.', NULL, 'Chiếc thang máy dừng lại ở lưng chừng giếng thang hẹp.', '{"wordId":"shaft","ukIpa":"/ʃɑːft/","usIpa":"/ʃæft/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"A vertical passage through a building or into the ground.","vi":"giếng (thang máy, thông gió); đường hầm thẳng đứng"},{"pos":"n.","en":"A long narrow part of a tool or machine.","vi":"cán; trục; tay cầm"},{"pos":"n.","en":"A narrow beam of light.","vi":"luồng (sáng); tia (nắng)"}],"examples":[{"en":"The lift stopped halfway up the narrow shaft.","vi":"Chiếc thang máy dừng lại ở lưng chừng giếng thang hẹp.","audioKind":"ex"},{"en":"Engineers installed a ventilation shaft to improve air quality throughout the underground transport station.","vi":"Các kỹ sư đã lắp đặt một giếng thông gió để cải thiện chất lượng không khí trong toàn bộ trạm giao thông ngầm.","audioKind":"ex2"}],"collocations":[{"en":"lift shaft","vi":"giếng thang máy"},{"en":"ventilation shaft","vi":"giếng thông gió"},{"en":"drive shaft","vi":"trục truyền động"},{"en":"a shaft of sunlight","vi":"một tia nắng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Giếng dùng shaft; tiếng Anh-Anh lift shaft tương đương tiếng Anh-Mỹ elevator shaft.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compatible', 'en-c1-53', 'compatible', '/kəmˈpætəbl/', 'C1', 'tương thích; có thể dùng chung; hợp nhau; tâm đầu ý hợp', 'adj.', 'compatibility (n.), incompatible (adj.), incompatibility (n.)', 'Trái nghĩa: incompatible', 'Cụm từ cố định là compatible with, không dùng compatible to.', 'This charger is compatible with both of our tablets.', NULL, 'Cục sạc này tương thích với cả hai chiếc máy tính bảng của chúng ta.', '{"wordId":"compatible","ukIpa":"/kəmˈpætəbl/","usIpa":"/kəmˈpætəbl/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"Able to work or exist together without problems","vi":"tương thích; có thể dùng chung"},{"pos":"adj.","en":"Having personalities or interests that allow a good relationship","vi":"hợp nhau; tâm đầu ý hợp"}],"examples":[{"en":"This charger is compatible with both of our tablets.","vi":"Cục sạc này tương thích với cả hai chiếc máy tính bảng của chúng ta.","audioKind":"ex"},{"en":"Economic growth can be compatible with environmental protection if governments encourage cleaner production and responsible resource use.","vi":"Tăng trưởng kinh tế hoàn toàn có thể song hành với bảo vệ môi trường nếu chính phủ khuyến khích sản xuất sạch hơn và sử dụng tài nguyên có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"compatible with","vi":"tương thích với"},{"en":"fully compatible","vi":"tương thích hoàn toàn"},{"en":"compatible software","vi":"phần mềm tương thích"}],"wordFamily":["compatibility (n.)","incompatible (adj.)","incompatibility (n.)"],"synonyms":[],"antonyms":["incompatible"],"tipVi":"Cụm từ cố định là compatible with, không dùng compatible to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refine', 'en-c1-53', 'refine', '/rɪˈfaɪn/', 'C1', 'cải tiến; trau chuốt; hoàn thiện; lọc; tinh chế; luyện', 'v.', 'refinement (n.), refined (adj.), refinery (n.)', 'Đồng nghĩa: improve, purify', 'Có thể dùng để chỉ việc hoàn thiện phương pháp hoặc tinh chế nguyên liệu thô.', 'I refined my recipe by adding less sugar.', NULL, 'Tôi đã cải tiến công thức nấu ăn của mình bằng cách cho ít đường hơn.', '{"wordId":"refine","ukIpa":"/rɪˈfaɪn/","usIpa":"/rɪˈfaɪn/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"Improve something by making small, careful changes","vi":"cải tiến; trau chuốt; hoàn thiện"},{"pos":"v.","en":"Remove unwanted substances from a raw material","vi":"lọc; tinh chế; luyện"}],"examples":[{"en":"I refined my recipe by adding less sugar.","vi":"Tôi đã cải tiến công thức nấu ăn của mình bằng cách cho ít đường hơn.","audioKind":"ex"},{"en":"Schools can refine their teaching methods by collecting regular feedback from students with different learning needs.","vi":"Các trường học có thể cải thiện phương pháp giảng dạy bằng cách thường xuyên thu thập phản hồi từ học sinh có nhu cầu học tập khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"refine a technique","vi":"cải tiến kỹ thuật"},{"en":"refine a proposal","vi":"hoàn thiện đề xuất"},{"en":"refine crude oil","vi":"lọc dầu thô"}],"wordFamily":["refinement (n.)","refined (adj.)","refinery (n.)"],"synonyms":["improve","purify"],"antonyms":[],"tipVi":"Có thể dùng để chỉ việc hoàn thiện phương pháp hoặc tinh chế nguyên liệu thô.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_antiquated', 'en-c1-53', 'antiquated', '/ˈæntɪkweɪtɪd/', 'C1', 'lỗi thời; cổ lỗ sĩ; cũ kỹ', 'adj.', NULL, 'Đồng nghĩa: outdated, obsolete, outmoded · Trái nghĩa: modern, up-to-date', 'Mang sắc thái chê bai, nhấn mạnh việc quá cũ không còn phù hợp; antique có thể chỉ đồ cổ có giá trị.', 'The office still relies on an antiquated heating system.', NULL, 'Văn phòng vẫn phải phụ thuộc vào một hệ thống sưởi ấm đã quá cũ kỹ.', '{"wordId":"antiquated","ukIpa":"/ˈæntɪkweɪtɪd/","usIpa":"/ˈæntɪkweɪtɪd/","cefr":"C1","topic":"technology","senses":[{"pos":"adj.","en":"too old or outdated to be suitable for modern use","vi":"lỗi thời; cổ lỗ sĩ; cũ kỹ"}],"examples":[{"en":"The office still relies on an antiquated heating system.","vi":"Văn phòng vẫn phải phụ thuộc vào một hệ thống sưởi ấm đã quá cũ kỹ.","audioKind":"ex"},{"en":"Replacing antiquated railway infrastructure could improve passenger safety and reduce delays across the national transport network.","vi":"Việc thay thế cơ sở hạ tầng đường sắt lỗi thời có thể nâng cao sự an toàn cho hành khách và giảm thiểu tình trạng chậm chuyến trên toàn mạng lưới giao thông quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"antiquated equipment","vi":"thiết bị lỗi thời"},{"en":"antiquated system","vi":"hệ thống cổ lỗ sĩ"},{"en":"antiquated laws","vi":"luật lệ lỗi thời"}],"wordFamily":[],"synonyms":["outdated","obsolete","outmoded"],"antonyms":["modern","up-to-date"],"tipVi":"Mang sắc thái chê bai, nhấn mạnh việc quá cũ không còn phù hợp; antique có thể chỉ đồ cổ có giá trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_valve', 'en-c1-53', 'valve', '/vælv/', 'C1', 'van; van khóa; bản van; van tim', 'n.', NULL, NULL, 'Trong kỹ thuật chỉ van, trong cơ thể người có thể chỉ các bộ phận như van tim.', 'Turn this valve to stop water entering the tank.', NULL, 'Hãy vặn chiếc van này để ngăn nước chảy vào bình chứa.', '{"wordId":"valve","ukIpa":"/vælv/","usIpa":"/vælv/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"a device controlling the flow of liquid or gas","vi":"van; van khóa"},{"pos":"n.","en":"a body structure keeping fluid moving in one direction","vi":"bản van; van tim"}],"examples":[{"en":"Turn this valve to stop water entering the tank.","vi":"Hãy vặn chiếc van này để ngăn nước chảy vào bình chứa.","audioKind":"ex"},{"en":"Replacing damaged heart valves can improve patients'' quality of life and reduce the risk of serious complications.","vi":"Việc thay thế các van tim bị tổn thương có thể cải thiện chất lượng cuộc sống của bệnh nhân và giảm nguy cơ biến chứng nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"open a valve","vi":"mở van"},{"en":"a safety valve","vi":"van an toàn"},{"en":"a heart valve","vi":"van tim"},{"en":"a pressure relief valve","vi":"van giảm áp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong kỹ thuật chỉ van, trong cơ thể người có thể chỉ các bộ phận như van tim.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amplify', 'en-c1-53', 'amplify', '/ˈæmplɪfaɪ/', 'C1', 'khuếch đại âm thanh hoặc tín hiệu điện; tăng cường; khuếch đại ảnh hưởng; làm rõ thêm; thuyết minh chi tiết', 'v.', 'amplification (n.), amplifier (n.)', 'Đồng nghĩa: boost, intensify · Trái nghĩa: reduce, diminish', 'Có thể dùng cho cả việc khuếch đại âm thanh vật lý lẫn gia tăng ảnh hưởng hoặc cảm xúc.', 'This small speaker amplifies music from my phone.', NULL, 'Loa nhỏ này giúp khuếch đại âm nhạc từ điện thoại của tôi.', '{"wordId":"amplify","ukIpa":"/ˈæmplɪfaɪ/","usIpa":"/ˈæmplɪfaɪ/","cefr":"C1","topic":"technology","senses":[{"pos":"v.","en":"to make a sound or electrical signal stronger","vi":"khuếch đại âm thanh hoặc tín hiệu điện"},{"pos":"v.","en":"to increase the strength or effect of something","vi":"tăng cường; khuếch đại ảnh hưởng"},{"pos":"v.","en":"to explain something further by adding details","vi":"làm rõ thêm; thuyết minh chi tiết"}],"examples":[{"en":"This small speaker amplifies music from my phone.","vi":"Loa nhỏ này giúp khuếch đại âm nhạc từ điện thoại của tôi.","audioKind":"ex"},{"en":"Social media can amplify public concerns about pollution, encouraging local authorities to respond more quickly.","vi":"Mạng xã hội có thể làm gia tăng những lo ngại của công chúng về ô nhiễm môi trường, từ đó thúc đẩy chính quyền địa phương phản hồi nhanh chóng hơn.","audioKind":"ex2"}],"collocations":[{"en":"amplify sound","vi":"khuếch đại âm thanh"},{"en":"amplify a signal","vi":"khuếch đại tín hiệu"},{"en":"amplify the effect","vi":"nâng cao hiệu quả"}],"wordFamily":["amplification (n.)","amplifier (n.)"],"synonyms":["boost","intensify"],"antonyms":["reduce","diminish"],"tipVi":"Có thể dùng cho cả việc khuếch đại âm thanh vật lý lẫn gia tăng ảnh hưởng hoặc cảm xúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sophistication', 'en-c1-53', 'sophistication', '/səˌfɪstɪˈkeɪʃən/', 'C1', 'tính tinh vi; mức độ phức tạp, hiện đại; sự sành sỏi; sự từng trải; nét tao nhã', 'n.', 'sophisticated (adj.), unsophisticated (adj.)', NULL, 'Là danh từ không đếm được; có thể chỉ sự tiên tiến trong công nghệ hoặc sự từng trải trong ứng xử.', 'I was surprised by the sophistication of her camera.', NULL, 'Tôi rất bất ngờ trước độ tinh xảo của chiếc máy ảnh mà cô ấy sử dụng.', '{"wordId":"sophistication","ukIpa":"/səˌfɪstɪˈkeɪʃən/","usIpa":"/səˌfɪstɪˈkeɪʃən/","cefr":"C1","topic":"technology","senses":[{"pos":"n.","en":"the quality of being advanced or carefully developed","vi":"tính tinh vi; mức độ phức tạp, hiện đại"},{"pos":"n.","en":"knowledge of social situations, culture, and fashionable tastes","vi":"sự sành sỏi; sự từng trải; nét tao nhã"}],"examples":[{"en":"I was surprised by the sophistication of her camera.","vi":"Tôi rất bất ngờ trước độ tinh xảo của chiếc máy ảnh mà cô ấy sử dụng.","audioKind":"ex"},{"en":"The growing sophistication of medical equipment allows doctors to identify certain diseases at an earlier stage.","vi":"Sự cải tiến ngày càng tinh vi của các thiết bị y tế giúp bác sĩ phát hiện một số bệnh từ giai đoạn sớm hơn.","audioKind":"ex2"}],"collocations":[{"en":"technological sophistication","vi":"trình độ công nghệ cao"},{"en":"a high degree of sophistication","vi":"độ phức tạp cao"},{"en":"social sophistication","vi":"sự tinh tế trong giao tiếp xã hội"}],"wordFamily":["sophisticated (adj.)","unsophisticated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; có thể chỉ sự tiên tiến trong công nghệ hoặc sự từng trải trong ứng xử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_53_1', 'en-c1-53', 'Cách dùng “refinement” (n.) — sự cải tiến; sự tinh chỉnh nhỏ để hoàn thiện hơn', 'further refinement  ·  a refinement to the design  ·  the refinement of raw materials', 'Các sự cải tiến cụ thể có thể đếm được; trong khi quá trình cải tiến, tinh chế hay sự tao nhã thường là danh từ không đếm được.', 'Họ từ (Word Family): refine (v.), refined (adj.), refinery (n.) | Đồng nghĩa: improvement, polish', '[{"hanzi":"One small refinement made the chair much more comfortable.","pinyin":"","meaning":"Chỉ một cải tiến nhỏ đã làm cho chiếc ghế trở nên thoải mái hơn rất nhiều."},{"hanzi":"Continued refinement of water treatment methods can improve public health while reducing the cost of supplying clean water.","pinyin":"","meaning":"Việc tiếp tục cải tiến các phương pháp xử lý nước có thể nâng cao sức khỏe cộng đồng đồng thời giảm chi phí cung cấp nước sạch."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_53_2', 'en-c1-53', 'Cách dùng “amplifier” (n.) — bộ khuếch đại, máy tăng âm, loa phóng thanh', 'a guitar amplifier  ·  a power amplifier  ·  a signal amplifier', 'amplifier dùng để khuếch đại tín hiệu điện/âm thanh; speaker chuyển đổi tín hiệu đó thành âm thanh phát ra ngoài.', 'Họ từ (Word Family): amplify (v.), amplification (n.) | Đồng nghĩa: amp', '[{"hanzi":"He connected his guitar to a small amplifier.","pinyin":"","meaning":"Anh ấy cắm cây đàn guitar của mình vào một chiếc amply nhỏ."},{"hanzi":"An amplifier can make a speaker''s voice clearly audible throughout a large lecture hall.","pinyin":"","meaning":"Bộ khuếch đại có thể giúp giọng nói của diễn giả nghe rõ mồn một trong toàn bộ hội trường lớn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_53_3', 'en-c1-53', 'Cách dùng “rotary” (adj.) — quay; chuyển động theo vòng tròn; chạy bằng cơ chế quay', 'rotary motion  ·  rotary engine  ·  rotary mower', 'Thường dùng để mô tả máy móc có chuyển động quay; không đồng nghĩa với từ rotating chỉ tính chất luân phiên.', 'Họ từ (Word Family): rotate (v.), rotation (n.), rotational (adj.)', '[{"hanzi":"Dad uses a rotary mower to cut the grass.","pinyin":"","meaning":"Bố dùng máy cắt cỏ quay để cắt cỏ trên sân."},{"hanzi":"Rotary motion is widely used in industrial machinery because it allows continuous and efficient operation.","pinyin":"","meaning":"Chuyển động quay được ứng dụng rộng rãi trong máy móc công nghiệp vì nó cho phép vận hành liên tục và hiệu quả."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_53_4', 'en-c1-53', 'Cách dùng “cartridge” (n.) — hộp mực; ống mực (thay thế được cho máy móc)', 'ink cartridge  ·  toner cartridge  ·  replace a cartridge', 'Nét nghĩa cốt lõi là ống hoặc hộp có thể lắp vào thiết bị; trong ngữ cảnh máy in thường chỉ hộp mực.', NULL, '[{"hanzi":"I replaced the empty cartridge before printing my homework.","pinyin":"","meaning":"Tôi đã thay hộp mực đã hết trước khi in bài tập về nhà."},{"hanzi":"Recycling printer cartridges can reduce plastic waste and recover materials that would otherwise enter landfill sites.","pinyin":"","meaning":"Việc tái chế hộp mực máy in có thể làm giảm rác thải nhựa và thu hồi các vật liệu vốn dĩ sẽ bị chôn lấp ở các bãi rác."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_53_1', 'en-c1-53', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_1_1', 'ten_c1_53_1', 'cartridge', 'I replaced the empty cartridge before printing my homework.', 'I replaced the empty cartridge before printing my homework.', '/ˈkɑːrtrɪdʒ/', 'Tôi đã thay hộp mực đã hết trước khi in bài tập về nhà.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_1_2', 'ten_c1_53_1', 'rotary', 'Dad uses a rotary mower to cut the grass.', 'Dad uses a rotary mower to cut the grass.', '/ˈroʊtəri/', 'Bố dùng máy cắt cỏ quay để cắt cỏ trên sân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_1_3', 'ten_c1_53_1', 'refinement', 'One small refinement made the chair much more comfortable.', 'One small refinement made the chair much more comfortable.', '/rɪˈfaɪnmənt/', 'Chỉ một cải tiến nhỏ đã làm cho chiếc ghế trở nên thoải mái hơn rất nhiều.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_1_4', 'ten_c1_53_1', 'transistor', 'She carefully replaced the damaged transistor inside the old radio.', 'She carefully replaced the damaged transistor inside the old radio.', '/trænˈzɪstər/', 'Cô ấy cẩn thận thay thế chiếc bóng bán dẫn bị hỏng bên trong chiếc đài cũ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_1_5', 'ten_c1_53_1', 'incompatible', 'These headphones are incompatible with my old phone.', 'These headphones are incompatible with my old phone.', '/ˌɪnkəmˈpætəbl/', 'Chiếc tai nghe này không tương thích với chiếc điện thoại cũ của tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_1_6', 'ten_c1_53_1', 'piston', 'The mechanic removed a damaged piston from the engine.', 'The mechanic removed a damaged piston from the engine.', '/ˈpɪstən/', 'Thợ máy đã tháo một pít-tông bị hỏng ra khỏi động cơ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_1_7', 'ten_c1_53_1', 'supersonic', 'We heard a loud boom as the supersonic aircraft passed.', 'We heard a loud boom as the supersonic aircraft passed.', '/ˌsuːpɚˈsɑːnɪk/', 'Chúng tôi nghe thấy một tiếng nổ lớn khi chiếc máy bay siêu thanh bay qua.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_1_8', 'ten_c1_53_1', 'amplifier', 'He connected his guitar to a small amplifier.', 'He connected his guitar to a small amplifier.', '/ˈæmplɪfaɪər/', 'Anh ấy cắm cây đàn guitar của mình vào một chiếc amply nhỏ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_53_1_1', 'en-c1-53', 'ten_c1_53_1', 'listening', 'listening', 'I replaced the empty cartridge before printing my homework.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã thay hộp mực đã hết trước khi in bài tập về nhà.","Chúng tôi ngắm nhìn chiếc tuabin gió quay chậm rãi phía trên cánh đồng.","Chỉ một cải tiến nhỏ đã làm cho chiếc ghế trở nên thoải mái hơn rất nhiều.","Thợ máy đã tháo một pít-tông bị hỏng ra khỏi động cơ."]'::jsonb, 0, 'I replaced the empty cartridge before printing my homework. → Tôi đã thay hộp mực đã hết trước khi in bài tập về nhà.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_53_1_2', 'en-c1-53', 'ten_c1_53_1', 'listening', 'listening', 'Dad uses a rotary mower to cut the grass.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bố dùng máy cắt cỏ quay để cắt cỏ trên sân.","Loa nhỏ này giúp khuếch đại âm nhạc từ điện thoại của tôi.","Chân vịt của con thuyền khuấy tung dòng nước thành bọt trắng.","Người nghệ sĩ đã gắn những chiếc vỏ sò nhỏ vào lớp đất sét còn ẩm."]'::jsonb, 0, 'Dad uses a rotary mower to cut the grass. → Bố dùng máy cắt cỏ quay để cắt cỏ trên sân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_53_1_3', 'en-c1-53', 'ten_c1_53_1', 'listening', 'listening', 'One small refinement made the chair much more comfortable.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cục sạc này tương thích với cả hai chiếc máy tính bảng của chúng ta.","Anh ấy cắm cây đàn guitar của mình vào một chiếc amply nhỏ.","Chỉ một cải tiến nhỏ đã làm cho chiếc ghế trở nên thoải mái hơn rất nhiều.","Tôi đã thay hộp mực đã hết trước khi in bài tập về nhà."]'::jsonb, 2, 'One small refinement made the chair much more comfortable. → Chỉ một cải tiến nhỏ đã làm cho chiếc ghế trở nên thoải mái hơn rất nhiều.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_53_2', 'en-c1-53', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_2_1', 'ten_c1_53_2', 'cartridge', 'Recycling printer cartridges can reduce plastic waste and recover materials that would otherwise enter landfill sites.', 'Recycling printer cartridges can reduce plastic waste and recover materials that would otherwise enter landfill sites.', '/ˈkɑːrtrɪdʒ/', 'Việc tái chế hộp mực máy in có thể làm giảm rác thải nhựa và thu hồi các vật liệu vốn dĩ sẽ bị chôn lấp ở các bãi rác.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_2_2', 'ten_c1_53_2', 'rotary', 'Rotary motion is widely used in industrial machinery because it allows continuous and efficient operation.', 'Rotary motion is widely used in industrial machinery because it allows continuous and efficient operation.', '/ˈroʊtəri/', 'Chuyển động quay được ứng dụng rộng rãi trong máy móc công nghiệp vì nó cho phép vận hành liên tục và hiệu quả.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_2_3', 'ten_c1_53_2', 'refinement', 'Continued refinement of water treatment methods can improve public health while reducing the cost of supplying clean water.', 'Continued refinement of water treatment methods can improve public health while reducing the cost of supplying clean water.', '/rɪˈfaɪnmənt/', 'Việc tiếp tục cải tiến các phương pháp xử lý nước có thể nâng cao sức khỏe cộng đồng đồng thời giảm chi phí cung cấp nước sạch.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_2_4', 'ten_c1_53_2', 'transistor', 'The development of smaller transistors has enabled computers to process information faster while consuming less power.', 'The development of smaller transistors has enabled computers to process information faster while consuming less power.', '/trænˈzɪstər/', 'Sự phát triển của các bóng bán dẫn nhỏ hơn đã giúp máy tính xử lý thông tin nhanh hơn mà lại tiêu thụ ít năng lượng hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_2_5', 'ten_c1_53_2', 'incompatible', 'Rapid industrial expansion is often incompatible with efforts to protect fragile ecosystems without effective regulation.', 'Rapid industrial expansion is often incompatible with efforts to protect fragile ecosystems without effective regulation.', '/ˌɪnkəmˈpætəbl/', 'Sự bành trướng công nghiệp nhanh chóng thường mâu thuẫn với các nỗ lực bảo vệ hệ sinh thái mong manh nếu thiếu đi các quy định quản lý hiệu quả.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_53_2_6', 'ten_c1_53_2', 'piston', 'In a conventional engine, expanding gases push each piston, converting energy from fuel into mechanical motion.', 'In a conventional engine, expanding gases push each piston, converting energy from fuel into mechanical motion.', '/ˈpɪstən/', 'Trong một động cơ thông thường, khí giãn nở đẩy từng pít-tông, chuyển hóa năng lượng từ nhiên liệu thành chuyển động cơ học.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_53_2_1', 'en-c1-53', 'ten_c1_53_2', 'listening', 'listening', 'Recycling printer cartridges can reduce plastic waste and recover materials that would otherwise enter landfill sites.', NULL, 'Trong câu vừa nghe, từ “cartridge” mang nghĩa nào sau đây?', '["lông vũ lớn; lông trang trí","hộp mực; ống mực (thay thế được cho máy móc)","quyền thuê nhà; thỏa thuận thuê tài sản","sự cẩu thả, sự lơ đễnh, sự thiếu trách nhiệm, lỗi bất cẩn"]'::jsonb, 1, '“cartridge” (/ˈkɑːrtrɪdʒ/): hộp mực; ống mực (thay thế được cho máy móc). Câu đầy đủ: Recycling printer cartridges can reduce plastic waste and recover materials that would otherwise enter landfill sites.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_53_2_2', 'en-c1-53', 'ten_c1_53_2', 'listening', 'listening', 'Rotary motion is widely used in industrial machinery because it allows continuous and efficient operation.', NULL, 'Trong câu vừa nghe, từ “rotary” mang nghĩa nào sau đây?', '["mang tính tiên phong; mang tính khai phá; có tính chất mở đường","quay; chuyển động theo vòng tròn; chạy bằng cơ chế quay","dự án kinh doanh rủi ro; công ty liên doanh","hội nghị chuyên đề; hội thảo"]'::jsonb, 1, '“rotary” (/ˈroʊtəri/): quay; chuyển động theo vòng tròn; chạy bằng cơ chế quay. Câu đầy đủ: Rotary motion is widely used in industrial machinery because it allows continuous and efficient operation.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
