INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_1', 'en-c1-53', NULL, 'comprehensive_test', 'listening', 'cartridge', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nguyên vẹn, không bị hư hại, không bị thay đổi","hộp mực; ống mực (thay thế được cho máy móc)","hệ thống phân cấp; thứ bậc","thân thiện; hòa nhã; dễ gần"]'::jsonb, 1, 'cartridge (/ˈkɑːrtrɪdʒ/) → hộp mực; ống mực (thay thế được cho máy móc); viên đạn; vỏ đạn', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_2', 'en-c1-53', NULL, 'comprehensive_test', 'listening', 'Dad uses a rotary mower to cut the grass.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi rất bất ngờ trước độ tinh xảo của chiếc máy ảnh mà cô ấy sử dụng.","Một chiếc bánh răng bị gãy đã làm cho chiếc đồng hồ cổ ngừng hoạt động.","Bố dùng máy cắt cỏ quay để cắt cỏ trên sân.","Cô ấy cẩn thận thay thế chiếc bóng bán dẫn bị hỏng bên trong chiếc đài cũ."]'::jsonb, 2, 'Dad uses a rotary mower to cut the grass. → Bố dùng máy cắt cỏ quay để cắt cỏ trên sân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_3', 'en-c1-53', NULL, 'comprehensive_test', 'listening', 'refinement', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hệ thống điện báo; máy điện báo","nhân viên đăng ký; thư ký quản lý hồ sơ","vô cơ","sự cải tiến; sự tinh chỉnh nhỏ để hoàn thiện hơn"]'::jsonb, 3, 'refinement (/rɪˈfaɪnmənt/) → sự cải tiến; sự tinh chỉnh nhỏ để hoàn thiện hơn; sự tinh chế; quá trình loại bỏ tạp chất khỏi vật liệu; sự tao nhã; phong thái lịch sự và có gu thẩm mỹ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_4', 'en-c1-53', NULL, 'comprehensive_test', 'listening', 'She carefully replaced the damaged transistor inside the old radio.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy cắm cây đàn guitar của mình vào một chiếc amply nhỏ.","Loa nhỏ này giúp khuếch đại âm nhạc từ điện thoại của tôi.","Chỉ một cải tiến nhỏ đã làm cho chiếc ghế trở nên thoải mái hơn rất nhiều.","Cô ấy cẩn thận thay thế chiếc bóng bán dẫn bị hỏng bên trong chiếc đài cũ."]'::jsonb, 3, 'She carefully replaced the damaged transistor inside the old radio. → Cô ấy cẩn thận thay thế chiếc bóng bán dẫn bị hỏng bên trong chiếc đài cũ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_5', 'en-c1-53', NULL, 'comprehensive_test', 'listening', 'incompatible', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["không tương thích; không tương hợp","nhang; trầm hương; hương","mưa đá (những hạt băng nhỏ rơi từ mây xuống)","sửa chữa; khắc phục; chỉnh đốn"]'::jsonb, 0, 'incompatible (/ˌɪnkəmˈpætəbl/) → không tương thích; không tương hợp; không hợp nhau; không thể hòa hợp', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_6', 'en-c1-53', NULL, 'comprehensive_test', 'listening', 'The mechanic removed a damaged piston from the engine.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chỉ một cải tiến nhỏ đã làm cho chiếc ghế trở nên thoải mái hơn rất nhiều.","Hãy vặn chiếc van này để ngăn nước chảy vào bình chứa.","Chúng tôi ngắm nhìn chiếc tuabin gió quay chậm rãi phía trên cánh đồng.","Thợ máy đã tháo một pít-tông bị hỏng ra khỏi động cơ."]'::jsonb, 3, 'The mechanic removed a damaged piston from the engine. → Thợ máy đã tháo một pít-tông bị hỏng ra khỏi động cơ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_7', 'en-c1-53', NULL, 'comprehensive_test', 'listening', 'supersonic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chưa từng có; chưa từng tồn tại trước đây","cằn cỗi; không màu mỡ","quả quyết, khẳng định, khẳng định chắc nịch rằng điều gì là đúng","siêu thanh, vượt tốc độ âm thanh"]'::jsonb, 3, 'supersonic (/ˌsuːpɚˈsɑːnɪk/) → siêu thanh, vượt tốc độ âm thanh', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_8', 'en-c1-53', NULL, 'comprehensive_test', 'listening', 'He connected his guitar to a small amplifier.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Văn phòng vẫn phải phụ thuộc vào một hệ thống sưởi ấm đã quá cũ kỹ.","Chiếc máy kéo này có đủ mã lực để kéo chiếc rơ-moóc nặng nề.","Chúng tôi nghe thấy một tiếng nổ lớn khi chiếc máy bay siêu thanh bay qua.","Anh ấy cắm cây đàn guitar của mình vào một chiếc amply nhỏ."]'::jsonb, 3, 'He connected his guitar to a small amplifier. → Anh ấy cắm cây đàn guitar của mình vào một chiếc amply nhỏ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
