INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_18', 'en-c1-53', NULL, 'comprehensive_test', 'reading', NULL, 'Recycling printer cartridges can reduce plastic waste and recover materials that would otherwise enter landfill sites.', 'Dựa vào câu trên, từ “cartridge” có nghĩa phù hợp nhất là gì?', '["hộp mực; ống mực (thay thế được cho máy móc)","dễ cháy; dễ bắt lửa","thuộc về dược phẩm; thuộc ngành chế tạo thuốc","liên kết; sáp nhập; gia nhập vào tổ chức lớn"]'::jsonb, 0, 'cartridge: hộp mực; ống mực (thay thế được cho máy móc); viên đạn; vỏ đạn. Dịch cả câu: Việc tái chế hộp mực máy in có thể làm giảm rác thải nhựa và thu hồi các vật liệu vốn dĩ sẽ bị chôn lấp ở các bãi rác.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_19', 'en-c1-53', NULL, 'comprehensive_test', 'reading', NULL, 'Rotary motion is widely used in industrial machinery because it allows continuous and efficient operation.', 'Dựa vào câu trên, từ “rotary” có nghĩa phù hợp nhất là gì?', '["bản tuyên ngôn; cương lĩnh","quay; chuyển động theo vòng tròn; chạy bằng cơ chế quay","sai lệch; đi chệch; chệch hướng","truyền bá; tuyên truyền"]'::jsonb, 1, 'rotary: quay; chuyển động theo vòng tròn; chạy bằng cơ chế quay; nút giao thông hình vòng xuyến. Dịch cả câu: Chuyển động quay được ứng dụng rộng rãi trong máy móc công nghiệp vì nó cho phép vận hành liên tục và hiệu quả.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_20', 'en-c1-53', NULL, 'comprehensive_test', 'reading', NULL, 'Continued refinement of water treatment methods can improve public health while reducing the cost of supplying clean water.', 'Dựa vào câu trên, từ “refinement” có nghĩa phù hợp nhất là gì?', '["hình cầu; có dạng hình cầu","truyền bá; tuyên truyền","sự cải tiến; sự tinh chỉnh nhỏ để hoàn thiện hơn","chiến tranh, chiến đấu, phương thức tác chiến"]'::jsonb, 2, 'refinement: sự cải tiến; sự tinh chỉnh nhỏ để hoàn thiện hơn; sự tinh chế; quá trình loại bỏ tạp chất khỏi vật liệu; sự tao nhã; phong thái lịch sự và có gu thẩm mỹ. Dịch cả câu: Việc tiếp tục cải tiến các phương pháp xử lý nước có thể nâng cao sức khỏe cộng đồng đồng thời giảm chi phí cung cấp nước sạch.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_21', 'en-c1-53', NULL, 'comprehensive_test', 'reading', NULL, 'The development of smaller transistors has enabled computers to process information faster while consuming less power.', 'Dựa vào câu trên, từ “transistor” có nghĩa phù hợp nhất là gì?', '["thét lên; kêu rít lên","bóng bán dẫn; tranzito","nhờ đó; vì thế; do đó","đề nghị ngược lại; giá trả lại; sự phản đề xuất"]'::jsonb, 1, 'transistor: bóng bán dẫn; tranzito. Dịch cả câu: Sự phát triển của các bóng bán dẫn nhỏ hơn đã giúp máy tính xử lý thông tin nhanh hơn mà lại tiêu thụ ít năng lượng hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_22', 'en-c1-53', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “van; van khóa”', '["disentangle","transferable","soluble","valve"]'::jsonb, 3, 'van; van khóa → valve (/vælv/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_23', 'en-c1-53', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khuếch đại âm thanh hoặc tín hiệu điện”', '["equivalence","boldness","amplify","resonance"]'::jsonb, 2, 'khuếch đại âm thanh hoặc tín hiệu điện → amplify (/ˈæmplɪfaɪ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_53_24', 'en-c1-53', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tính tinh vi; mức độ phức tạp, hiện đại”', '["spur","sophistication","witty","din"]'::jsonb, 1, 'tính tinh vi; mức độ phức tạp, hiện đại → sophistication (/səˌfɪstɪˈkeɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-54', 'en', 'Bài 54: Khoa học & Nghiên cứu (1) - CEFR C1', 'CEFR C1', 'C1 · Khoa học', '26 từ vựng Tiếng Anh CEFR C1 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5054, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_threshold', 'en-c1-54', 'threshold', '/ˈθreʃhoʊld/', 'C1', 'ngưỡng; mức giới hạn; ngưỡng cửa; bước ngoặt', 'n.', NULL, 'Đồng nghĩa: limit, boundary', 'Cụm on the threshold of dùng để diễn tả việc sắp sửa bước vào một giai đoạn mới.', 'My brother has a much higher pain threshold than me.', NULL, 'Em trai tôi có khả năng chịu đau cao hơn tôi rất nhiều.', '{"wordId":"threshold","ukIpa":"/ˈθreʃhəʊld/","usIpa":"/ˈθreʃhoʊld/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"the level at which something starts happening or changes","vi":"ngưỡng; mức giới hạn"},{"pos":"n.","en":"the bottom edge of a doorway","vi":"ngưỡng cửa"},{"pos":"n.","en":"the point just before a new experience or period begins","vi":"ngưỡng cửa; bước ngoặt"}],"examples":[{"en":"My brother has a much higher pain threshold than me.","vi":"Em trai tôi có khả năng chịu đau cao hơn tôi rất nhiều.","audioKind":"ex"},{"en":"Raising the income threshold for financial assistance would allow more low-paid workers to receive support.","vi":"Việc nâng ngưỡng thu nhập để được hỗ trợ tài chính sẽ giúp nhiều lao động thu nhập thấp nhận được sự trợ giúp hơn.","audioKind":"ex2"}],"collocations":[{"en":"pain threshold","vi":"ngưỡng chịu đau"},{"en":"income threshold","vi":"ngưỡng thu nhập"},{"en":"cross the threshold","vi":"bước qua ngưỡng cửa"},{"en":"on the threshold of","vi":"trước thềm..."}],"wordFamily":[],"synonyms":["limit","boundary"],"antonyms":[],"tipVi":"Cụm on the threshold of dùng để diễn tả việc sắp sửa bước vào một giai đoạn mới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_empirical', 'en-c1-54', 'empirical', '/ɪmˈpɪrɪkəl/', 'C1', 'dựa trên thực nghiệm; thực tế; theo kinh nghiệm', 'adj.', 'empirically (adv.), empiricism (n.), empiricist (n.)', 'Trái nghĩa: theoretical', 'Nhấn mạnh vào cơ sở quan sát hoặc thí nghiệm, khác với những lời đồn đoán hay kinh nghiệm chủ quan đơn thuần.', 'Our garden trial provided empirical evidence that compost helps plants.', NULL, 'Thí nghiệm trồng cây ở vườn nhà đã cung cấp bằng chứng thực tế cho thấy phân hữu ích cho cây cối.', '{"wordId":"empirical","ukIpa":"/ɪmˈpɪrɪkəl/","usIpa":"/ɪmˈpɪrɪkəl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"based on observation or experiments rather than theory alone","vi":"dựa trên thực nghiệm; thực tế; theo kinh nghiệm"}],"examples":[{"en":"Our garden trial provided empirical evidence that compost helps plants.","vi":"Thí nghiệm trồng cây ở vườn nhà đã cung cấp bằng chứng thực tế cho thấy phân hữu ích cho cây cối.","audioKind":"ex"},{"en":"Education policies should be supported by empirical research rather than assumptions about how children learn.","vi":"Các chính sách giáo dục nên được hỗ trợ bằng nghiên cứu thực nghiệm thay vì dựa trên những giả định về cách trẻ em học tập.","audioKind":"ex2"}],"collocations":[{"en":"empirical evidence","vi":"bằng chứng thực nghiệm"},{"en":"empirical research","vi":"nghiên cứu thực nghiệm"},{"en":"empirical data","vi":"dữ liệu thực nghiệm"}],"wordFamily":["empirically (adv.)","empiricism (n.)","empiricist (n.)"],"synonyms":[],"antonyms":["theoretical"],"tipVi":"Nhấn mạnh vào cơ sở quan sát hoặc thí nghiệm, khác với những lời đồn đoán hay kinh nghiệm chủ quan đơn thuần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spherical', 'en-c1-54', 'spherical', '/ˈsfɪrɪkəl/', 'C1', 'hình cầu; có dạng hình cầu', 'adj.', 'sphere (n.), spherically (adv.)', 'Đồng nghĩa: ball-shaped', 'spherical chỉ hình cầu dạng 3D; trong khi circular chỉ hình tròn phẳng 2D.', 'A spherical lamp hung above the dining table.', NULL, 'Một chiếc đèn hình cầu được treo phía trên bàn ăn.', '{"wordId":"spherical","ukIpa":"/ˈsferɪkəl/","usIpa":"/ˈsfɪrɪkəl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"shaped like a ball","vi":"hình cầu; có dạng hình cầu"}],"examples":[{"en":"A spherical lamp hung above the dining table.","vi":"Một chiếc đèn hình cầu được treo phía trên bàn ăn.","audioKind":"ex"},{"en":"Researchers use spherical particles of different sizes to investigate how pollutants move through water filtration systems.","vi":"Các nhà nghiên cứu sử dụng các hạt hình cầu có kích thước khác nhau để tìm hiểu cách các chất ô nhiễm di chuyển qua hệ thống lọc nước.","audioKind":"ex2"}],"collocations":[{"en":"spherical shape","vi":"hình dạng hình cầu"},{"en":"spherical particles","vi":"hạt hình cầu"},{"en":"spherical surface","vi":"bề mặt hình cầu"}],"wordFamily":["sphere (n.)","spherically (adv.)"],"synonyms":["ball-shaped"],"antonyms":[],"tipVi":"spherical chỉ hình cầu dạng 3D; trong khi circular chỉ hình tròn phẳng 2D.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cosmos', 'en-c1-54', 'cosmos', '/ˈkɑːzmoʊs/', 'C1', 'vũ trụ (được xem như một hệ thống có trật tự, hoàn chỉnh)', 'n.', 'cosmic (adj.), cosmology (n.), cosmologist (n.)', 'Đồng nghĩa: universe', 'Biểu thị vũ trụ khi dùng thường đi với the cosmos.', 'Looking through the telescope made me curious about the cosmos.', NULL, 'Nhìn qua kính thiên văn khiến tôi cảm thấy tò mò về vũ trụ.', '{"wordId":"cosmos","ukIpa":"/ˈkɒzmɒs/","usIpa":"/ˈkɑːzmoʊs/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The universe considered as a complete, ordered system.","vi":"vũ trụ (được xem như một hệ thống có trật tự, hoàn chỉnh)"}],"examples":[{"en":"Looking through the telescope made me curious about the cosmos.","vi":"Nhìn qua kính thiên văn khiến tôi cảm thấy tò mò về vũ trụ.","audioKind":"ex"},{"en":"Studying the cosmos helps scientists investigate how galaxies formed and how the universe has changed over time.","vi":"Nghiên cứu vũ trụ giúp các nhà khoa học tìm hiểu các thiên hà hình thành như thế nào và vũ trụ đã thay đổi ra sao theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"explore the cosmos","vi":"khám phá vũ trụ"},{"en":"the origins of the cosmos","vi":"nguồn gốc của vũ trụ"},{"en":"the vastness of the cosmos","vi":"sự bao la của vũ trụ"}],"wordFamily":["cosmic (adj.)","cosmology (n.)","cosmologist (n.)"],"synonyms":["universe"],"antonyms":[],"tipVi":"Biểu thị vũ trụ khi dùng thường đi với the cosmos.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eclipse', 'en-c1-54', 'eclipse', '/ɪˈklɪps/', 'C1', 'nhật thực; nguyệt thực; làm lu mờ; vượt trội hơn', 'n.', NULL, 'Đồng nghĩa: overshadow, outshine', 'Nhật thực dùng solar eclipse, nguyệt thực dùng lunar eclipse.', 'We watched the lunar eclipse from our garden last night.', NULL, 'Chúng tôi đã ngắm hiện tượng nguyệt thực từ khu vườn của mình vào tối qua.', '{"wordId":"eclipse","ukIpa":"/ɪˈklɪps/","usIpa":"/ɪˈklɪps/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"an event when one celestial body blocks another''s light","vi":"nhật thực; nguyệt thực"},{"pos":"v.","en":"make something seem less important or impressive by comparison","vi":"làm lu mờ; vượt trội hơn"}],"examples":[{"en":"We watched the lunar eclipse from our garden last night.","vi":"Chúng tôi đã ngắm hiện tượng nguyệt thực từ khu vườn của mình vào tối qua.","audioKind":"ex"},{"en":"Investment in digital services may eclipse spending on traditional infrastructure as economies become increasingly dependent on technology.","vi":"Khoản đầu tư vào các dịch vụ số có thể làm lu mờ chi phí dành cho cơ sở hạ tầng truyền thống khi nền kinh tế ngày càng phụ thuộc vào công nghệ.","audioKind":"ex2"}],"collocations":[{"en":"solar eclipse","vi":"nhật thực"},{"en":"lunar eclipse","vi":"nguyệt thực"},{"en":"total eclipse","vi":"nhật/nguyệt thực toàn phần"},{"en":"eclipse previous achievements","vi":"làm lu mờ các thành tựu trước đó"}],"wordFamily":[],"synonyms":["overshadow","outshine"],"antonyms":[],"tipVi":"Nhật thực dùng solar eclipse, nguyệt thực dùng lunar eclipse.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infinity', 'en-c1-54', 'infinity', '/ɪnˈfɪnəti/', 'C1', 'vô cực; vô tận; đại lượng vô hạn', 'n.', 'infinite (adj.), infinitely (adv.), infinitude (n.)', 'Đồng nghĩa: endlessness, boundlessness', 'Không phải là "số lượng lớn" thông thường; trong toán học thường dùng với ý nghĩa tiến tới vô cực.', 'The desert seemed to stretch away into infinity.', NULL, 'Sa mạc dường như trải dài đến tận cõi vô tận.', '{"wordId":"infinity","ukIpa":"/ɪnˈfɪnəti/","usIpa":"/ɪnˈfɪnəti/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The state of having no end or limit.","vi":"vô cực; vô tận"},{"pos":"n.","en":"A mathematical concept greater than any finite quantity.","vi":"đại lượng vô hạn"}],"examples":[{"en":"The desert seemed to stretch away into infinity.","vi":"Sa mạc dường như trải dài đến tận cõi vô tận.","audioKind":"ex"},{"en":"The concept of infinity allows mathematicians to explore quantities beyond the limits of ordinary measurement.","vi":"Khái niệm vô cực cho phép các nhà toán học khám phá những đại lượng vượt ngoài giới hạn của các phép đo thông thường.","audioKind":"ex2"}],"collocations":[{"en":"stretch into infinity","vi":"trải dài đến vô tận"},{"en":"approach infinity","vi":"tiệm cận vô cực"},{"en":"an infinity of possibilities","vi":"vô vàn khả năng"}],"wordFamily":["infinite (adj.)","infinitely (adv.)","infinitude (n.)"],"synonyms":["endlessness","boundlessness"],"antonyms":[],"tipVi":"Không phải là \"số lượng lớn\" thông thường; trong toán học thường dùng với ý nghĩa tiến tới vô cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_zoology', 'en-c1-54', 'zoology', '/zoʊˈɑːlədʒi/', 'C1', 'động vật học', 'n.', 'zoologist (n.), zoological (adj.)', NULL, 'Thường là danh từ không đếm được; ngành học nghiên cứu về thực vật là botany.', 'My cousin studies zoology and spends weekends watching birds.', NULL, 'Em họ tôi học ngành động vật học và dành các ngày cuối tuần để quan sát chim chóc.', '{"wordId":"zoology","ukIpa":"/zuˈɒlədʒi/","usIpa":"/zoʊˈɑːlədʒi/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"the scientific study of animals","vi":"động vật học"}],"examples":[{"en":"My cousin studies zoology and spends weekends watching birds.","vi":"Em họ tôi học ngành động vật học và dành các ngày cuối tuần để quan sát chim chóc.","audioKind":"ex"},{"en":"Research in zoology helps scientists understand animal behaviour and design more effective strategies for protecting endangered species.","vi":"Nghiên cứu về động vật học giúp các nhà khoa học hiểu rõ hơn về tập tính của động vật và thiết kế các chiến lược bảo vệ các loài có nguy cơ tuyệt chủng hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"study zoology","vi":"học ngành động vật học"},{"en":"a degree in zoology","vi":"bằng cử nhân động vật học"},{"en":"a zoology department","vi":"khoa động vật học"}],"wordFamily":["zoologist (n.)","zoological (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; ngành học nghiên cứu về thực vật là botany.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_variant', 'en-c1-54', 'variant', '/ˈveriənt/', 'C1', 'biến thể; biến chủng; có biến đổi; khác biệt một chút', 'n.', 'vary (v.), variation (n.), variable (adj.), variety (n.)', 'Đồng nghĩa: version, variation', 'Danh từ thường đi với a variant of; tính từ có thể bổ nghĩa cho các từ như spelling.', 'This local variant of the soup includes fresh beans.', NULL, 'Món súp phiên bản địa phương này có cho thêm đậu tươi.', '{"wordId":"variant","ukIpa":"/ˈveəriənt/","usIpa":"/ˈveriənt/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A form that differs slightly from other related forms.","vi":"biến thể; biến chủng"},{"pos":"adj.","en":"Differing in some way from the usual or related form.","vi":"có biến đổi; khác biệt một chút"}],"examples":[{"en":"This local variant of the soup includes fresh beans.","vi":"Món súp phiên bản địa phương này có cho thêm đậu tươi.","audioKind":"ex"},{"en":"A genetic variant may affect how individuals respond to certain medicines, making personalised treatment increasingly important.","vi":"Một biến thể di truyền có thể ảnh hưởng đến cách cá nhân phản ứng với một số loại thuốc nhất định, khiến cho y học cá thể hóa trở nên ngày càng quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"a variant of","vi":"một biến thể của"},{"en":"genetic variant","vi":"biến thể di truyền"},{"en":"regional variant","vi":"biến thể theo vùng miền"},{"en":"variant spelling","vi":"cách viết biến thể"}],"wordFamily":["vary (v.)","variation (n.)","variable (adj.)","variety (n.)"],"synonyms":["version","variation"],"antonyms":[],"tipVi":"Danh từ thường đi với a variant of; tính từ có thể bổ nghĩa cho các từ như spelling.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inhibit', 'en-c1-54', 'inhibit', '/ɪnˈhɪbɪt/', 'C1', 'ức chế; cản trở; làm cho rụt rè; khiến không dám tự do thể hiện', 'v.', 'inhibition (n.), inhibitor (n.), inhibitory (adj.), inhibited (adj.)', 'Đồng nghĩa: hinder, restrain, suppress · Trái nghĩa: encourage, stimulate', 'inhibit nhấn mạnh việc ức chế hoặc cản trở; prohibit mang nghĩa cấm đoán rõ ràng.', 'Cold weather can inhibit the growth of these plants.', NULL, 'Thời tiết lạnh có thể ức chế sự sinh trưởng của các loài cây này.', '{"wordId":"inhibit","ukIpa":"/ɪnˈhɪbɪt/","usIpa":"/ɪnˈhɪbɪt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To slow down or prevent a process or activity.","vi":"ức chế; cản trở"},{"pos":"v.","en":"To make someone feel unable to act or speak freely.","vi":"làm cho rụt rè; khiến không dám tự do thể hiện"}],"examples":[{"en":"Cold weather can inhibit the growth of these plants.","vi":"Thời tiết lạnh có thể ức chế sự sinh trưởng của các loài cây này.","audioKind":"ex"},{"en":"Fear of making mistakes can inhibit students from participating actively in classroom discussions and collaborative tasks.","vi":"Nỗi sợ mắc lỗi có thể khiến học sinh không dám tích cực tham gia vào các cuộc thảo luận trên lớp và nhiệm vụ hợp tác.","audioKind":"ex2"}],"collocations":[{"en":"inhibit growth","vi":"ức chế sự tăng trưởng"},{"en":"inhibit development","vi":"cản trở sự phát triển"},{"en":"inhibit enzyme activity","vi":"ức chế hoạt động của enzyme"}],"wordFamily":["inhibition (n.)","inhibitor (n.)","inhibitory (adj.)","inhibited (adj.)"],"synonyms":["hinder","restrain","suppress"],"antonyms":["encourage","stimulate"],"tipVi":"inhibit nhấn mạnh việc ức chế hoặc cản trở; prohibit mang nghĩa cấm đoán rõ ràng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plasma', 'en-c1-54', 'plasma', '/ˈplæz.mə/', 'C1', 'huyết tương; thể plasma; chất khí ion hóa', 'n.', NULL, NULL, 'Thường không đếm được; trong y học chỉ huyết tương, trong vật lý chỉ thể plasma.', 'My cousin donates plasma at the local clinic.', NULL, 'Em họ tôi hiến huyết tương tại phòng khám địa phương.', '{"wordId":"plasma","ukIpa":"/ˈplæz.mə/","usIpa":"/ˈplæz.mə/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The liquid part of blood in which blood cells float","vi":"huyết tương"},{"pos":"n.","en":"An ionised gas containing free electrons and charged particles","vi":"thể plasma; chất khí ion hóa"}],"examples":[{"en":"My cousin donates plasma at the local clinic.","vi":"Em họ tôi hiến huyết tương tại phòng khám địa phương.","audioKind":"ex"},{"en":"Donated plasma contains proteins that can be used to produce treatments for certain immune system disorders.","vi":"Huyết tương được hiến tặng chứa các loại protein có thể dùng để sản xuất thuốc điều trị một số rối loạn hệ miễn dịch.","audioKind":"ex2"}],"collocations":[{"en":"blood plasma","vi":"huyết tương máu"},{"en":"donate plasma","vi":"hiến huyết tương"},{"en":"plasma proteins","vi":"protein huyết tương"},{"en":"plasma physics","vi":"vật lý plasma"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường không đếm được; trong y học chỉ huyết tương, trong vật lý chỉ thể plasma.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_atmospheric', 'en-c1-54', 'atmospheric', '/ˌætməsˈferɪk/', 'C1', 'thuộc khí quyển; tạo không khí; giàu cảm xúc', 'adj.', 'atmosphere (n.), atmospherically (adv.)', NULL, 'Khi bổ nghĩa cho pressure, từ này chỉ áp suất khí quyển; khi bổ nghĩa cho không gian/địa điểm, từ này thường chỉ khung cảnh giàu cảm xúc.', 'We found an atmospheric café tucked behind the old theatre.', NULL, 'Chúng tôi đã tìm thấy một quán cà phê mang đậm không khí ấm cúng nằm ẩn mình phía sau nhà hát cũ.', '{"wordId":"atmospheric","ukIpa":"/ˌætməsˈferɪk/","usIpa":"/ˌætməsˈferɪk/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Relating to the gases surrounding Earth or another planet.","vi":"thuộc khí quyển"},{"pos":"adj.","en":"Creating a strong and distinctive mood or feeling.","vi":"tạo không khí; giàu cảm xúc"}],"examples":[{"en":"We found an atmospheric café tucked behind the old theatre.","vi":"Chúng tôi đã tìm thấy một quán cà phê mang đậm không khí ấm cúng nằm ẩn mình phía sau nhà hát cũ.","audioKind":"ex"},{"en":"Changes in atmospheric conditions can affect agricultural production and increase the frequency of extreme weather events.","vi":"Sự biến đổi của các điều kiện khí quyển có thể ảnh hưởng đến sản xuất nông nghiệp và làm gia tăng tần suất xuất hiện của các hiện tượng thời tiết cực đoan.","audioKind":"ex2"}],"collocations":[{"en":"atmospheric pressure","vi":"áp suất khí quyển"},{"en":"atmospheric conditions","vi":"điều kiện khí quyển"},{"en":"atmospheric pollution","vi":"ô nhiễm không khí"},{"en":"an atmospheric setting","vi":"một khung cảnh đầy tính nghệ thuật"}],"wordFamily":["atmosphere (n.)","atmospherically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi bổ nghĩa cho pressure, từ này chỉ áp suất khí quyển; khi bổ nghĩa cho không gian/địa điểm, từ này thường chỉ khung cảnh giàu cảm xúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_symmetry', 'en-c1-54', 'symmetry', '/ˈsɪmətri/', 'C1', 'sự đối xứng; tính đối xứng', 'n.', 'symmetrical (adj.), symmetrically (adv.), asymmetry (n.), asymmetrical (adj.)', 'Trái nghĩa: asymmetry', 'Thường là danh từ không đếm được; dạng tính từ tương ứng là symmetrical.', 'The butterfly''s open wings show beautiful symmetry in the sunlight.', NULL, 'Đôi cánh đang giương rộng của chú bướm thể hiện một vẻ đẹp đối xứng tuyệt mỹ dưới ánh mặt trời.', '{"wordId":"symmetry","ukIpa":"/ˈsɪmətri/","usIpa":"/ˈsɪmətri/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The matching arrangement of parts on opposite sides.","vi":"sự đối xứng; tính đối xứng"}],"examples":[{"en":"The butterfly''s open wings show beautiful symmetry in the sunlight.","vi":"Đôi cánh đang giương rộng của chú bướm thể hiện một vẻ đẹp đối xứng tuyệt mỹ dưới ánh mặt trời.","audioKind":"ex"},{"en":"Architects often use symmetry to create buildings that appear balanced and visually pleasing to visitors.","vi":"Các kiến trúc sư thường tận dụng tính đối xứng để tạo nên những công trình mang lại cảm giác cân bằng và đẹp mắt cho người tham quan.","audioKind":"ex2"}],"collocations":[{"en":"perfect symmetry","vi":"sự đối xứng hoàn hảo"},{"en":"bilateral symmetry","vi":"tính đối xứng hai bên"},{"en":"radial symmetry","vi":"tính đối xứng tỏa tròn"}],"wordFamily":["symmetrical (adj.)","symmetrically (adv.)","asymmetry (n.)","asymmetrical (adj.)"],"synonyms":[],"antonyms":["asymmetry"],"tipVi":"Thường là danh từ không đếm được; dạng tính từ tương ứng là symmetrical.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resistant', 'en-c1-54', 'resistant', '/rɪˈzɪstənt/', 'C1', 'chống chịu; kháng (không dễ bị hư hại hoặc tác động); kháng cự; chống đối (không muốn chấp nhận hoặc thay đổi)', 'adj.', 'resist (v.), resistance (n.)', 'Trái nghĩa: susceptible', 'Thường đi với giới từ to; mức độ chống nước của water-resistant kém hơn so với waterproof.', 'These boots are resistant to water and easy to clean.', NULL, 'Đôi bốt này có khả năng chống thấm nước và rất dễ lau chùi.', '{"wordId":"resistant","ukIpa":"/rɪˈzɪstənt/","usIpa":"/rɪˈzɪstənt/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Not easily damaged or affected by something.","vi":"chống chịu; kháng (không dễ bị hư hại hoặc tác động)"},{"pos":"adj.","en":"Unwilling to accept something or agree to a change.","vi":"kháng cự; chống đối (không muốn chấp nhận hoặc thay đổi)"}],"examples":[{"en":"These boots are resistant to water and easy to clean.","vi":"Đôi bốt này có khả năng chống thấm nước và rất dễ lau chùi.","audioKind":"ex"},{"en":"Some bacteria have become resistant to common antibiotics, making infections more difficult to treat.","vi":"Một số loại vi khuẩn đã trở nên kháng lại các loại thuốc kháng sinh thông thường, khiến cho việc điều trị các bệnh nhiễm trùng trở nên khó khăn hơn.","audioKind":"ex2"}],"collocations":[{"en":"resistant to change","vi":"kháng thay đổi"},{"en":"antibiotic-resistant bacteria","vi":"vi khuẩn kháng kháng sinh"},{"en":"water-resistant clothing","vi":"quần áo chống thấm nước"}],"wordFamily":["resist (v.)","resistance (n.)"],"synonyms":[],"antonyms":["susceptible"],"tipVi":"Thường đi với giới từ to; mức độ chống nước của water-resistant kém hơn so với waterproof.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nucleus', 'en-c1-54', 'nucleus', '/ˈnuːkliəs/', 'C1', 'tế bào nhân; nhân tế bào; hạt nhân nguyên tử; hạt nhân; trung tâm; cốt lõi', 'n.', 'nuclear (adj.)', 'Đồng nghĩa: core, centre', 'Dạng số nhiều là nuclei; có thể chỉ nhân tế bào hoặc hạt nhân nguyên tử.', 'The cell''s nucleus looked purple under our classroom microscope.', NULL, 'Nhân của tế bào trông có màu tím dưới kính hiển vi ở lớp học của chúng tôi.', '{"wordId":"nucleus","ukIpa":"/ˈnjuːkliəs/","usIpa":"/ˈnuːkliəs/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The part of a cell containing most of its genetic material.","vi":"tế bào nhân; nhân tế bào"},{"pos":"n.","en":"The central part of an atom, containing protons and usually neutrons.","vi":"hạt nhân nguyên tử"},{"pos":"n.","en":"The central group or part around which something develops.","vi":"hạt nhân; trung tâm; cốt lõi"}],"examples":[{"en":"The cell''s nucleus looked purple under our classroom microscope.","vi":"Nhân của tế bào trông có màu tím dưới kính hiển vi ở lớp học của chúng tôi.","audioKind":"ex"},{"en":"Damage to genetic material in the nucleus can affect how a cell functions and divides.","vi":"Tổn thương vật chất di truyền trong nhân tế bào có thể ảnh hưởng đến cách hoạt động và phân chia của tế bào.","audioKind":"ex2"}],"collocations":[{"en":"cell nucleus","vi":"nhân tế bào"},{"en":"atomic nucleus","vi":"hạt nhân nguyên tử"},{"en":"form the nucleus of","vi":"tạo thành cốt lõi của"}],"wordFamily":["nuclear (adj.)"],"synonyms":["core","centre"],"antonyms":[],"tipVi":"Dạng số nhiều là nuclei; có thể chỉ nhân tế bào hoặc hạt nhân nguyên tử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ignite', 'en-c1-54', 'ignite', '/ɪɡˈnaɪt/', 'C1', 'làm bốc cháy; đốt cháy; khơi nguồn; kích thích', 'v.', 'ignition (n.)', 'Đồng nghĩa: light, kindle · Trái nghĩa: extinguish', 'Có thể dùng theo cả nghĩa ngoại động từ và nội động từ; ngoài ra còn dùng theo nghĩa bóng để chỉ việc khơi dậy sự quan tâm hoặc tranh luận.', 'A tiny spark ignited the dry wood in the fireplace.', NULL, 'Một tia lửa nhỏ đã bén vào đống củi khô trong lò sưởi.', '{"wordId":"ignite","ukIpa":"/ɪɡˈnaɪt/","usIpa":"/ɪɡˈnaɪt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To start burning or cause something to burn.","vi":"làm bốc cháy; đốt cháy"},{"pos":"v.","en":"To cause a strong feeling or situation to begin.","vi":"khơi nguồn; kích thích"}],"examples":[{"en":"A tiny spark ignited the dry wood in the fireplace.","vi":"Một tia lửa nhỏ đã bén vào đống củi khô trong lò sưởi.","audioKind":"ex"},{"en":"Practical science lessons can ignite students'' curiosity and encourage them to explore unfamiliar ideas independently.","vi":"Các tiết học khoa học thực tế có thể khơi gợi trí tò mò của học sinh và khuyến khích các em tự mình khám phá những ý tưởng lạ lẫm.","audioKind":"ex2"}],"collocations":[{"en":"ignite a fire","vi":"đốt lửa"},{"en":"ignite interest","vi":"khơi gợi hứng thú"},{"en":"ignite a debate","vi":"châm ngòi tranh luận"}],"wordFamily":["ignition (n.)"],"synonyms":["light","kindle"],"antonyms":["extinguish"],"tipVi":"Có thể dùng theo cả nghĩa ngoại động từ và nội động từ; ngoài ra còn dùng theo nghĩa bóng để chỉ việc khơi dậy sự quan tâm hoặc tranh luận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_barometer', 'en-c1-54', 'barometer', '/bəˈrɑːmɪtər/', 'C1', 'áp kế; khí áp kế; thước đo; chỉ số phản ánh thay đổi', 'n.', 'barometric (adj.)', NULL, 'Khi dùng theo nghĩa ẩn dụ là chỉ số của một trạng thái nào đó, thường dùng a barometer of.', 'We checked the barometer before sailing across the bay.', NULL, 'Chúng tôi đã kiểm tra khí áp kế trước khi chèo thuyền vượt vịnh.', '{"wordId":"barometer","ukIpa":"/bəˈrɒmɪtə/","usIpa":"/bəˈrɑːmɪtər/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"an instrument that measures air pressure","vi":"áp kế; khí áp kế"},{"pos":"n.","en":"something that indicates changes in a situation or condition","vi":"thước đo; chỉ số phản ánh thay đổi"}],"examples":[{"en":"We checked the barometer before sailing across the bay.","vi":"Chúng tôi đã kiểm tra khí áp kế trước khi chèo thuyền vượt vịnh.","audioKind":"ex"},{"en":"Consumer confidence is often regarded as a useful barometer of a country''s overall economic health.","vi":"Niềm tin của người tiêu dùng thường được xem là một thước đo hữu ích về sức khỏe kinh tế tổng thể của một quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"air pressure barometer","vi":"khí áp kế đo áp suất không khí"},{"en":"a barometer of public opinion","vi":"thước đo dư luận xã hội"},{"en":"economic barometer","vi":"thước đo kinh tế"}],"wordFamily":["barometric (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng theo nghĩa ẩn dụ là chỉ số của một trạng thái nào đó, thường dùng a barometer of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inverse', 'en-c1-54', 'inverse', '/ˌɪnˈvɝːs/', 'C1', 'ngược lại; trái ngược; tỉ lệ nghịch; điều ngược lại; phép nghịch đảo', 'adj.', 'inversely (adv.), inversion (n.), invert (v.)', 'Đồng nghĩa: reverse, opposite', 'Mối quan hệ nghịch đảo (inverse relationship) có nghĩa là khi một bên tăng lên thì bên kia giảm xuống.', 'Our free time and workload have an inverse relationship.', NULL, 'Thời gian rảnh và khối lượng công việc của chúng tôi có mối quan hệ nghịch đảo với nhau.', '{"wordId":"inverse","ukIpa":"/ˌɪnˈvɜːs/","usIpa":"/ˌɪnˈvɝːs/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Opposite in direction, order, or effect","vi":"ngược lại; trái ngược; tỉ lệ nghịch"},{"pos":"n.","en":"The opposite of something, or an operation reversing another","vi":"điều ngược lại; phép nghịch đảo"}],"examples":[{"en":"Our free time and workload have an inverse relationship.","vi":"Thời gian rảnh và khối lượng công việc của chúng tôi có mối quan hệ nghịch đảo với nhau.","audioKind":"ex"},{"en":"The study found an inverse relationship between regular physical activity and reported stress levels among office workers.","vi":"Nghiên cứu phát hiện ra mối quan hệ nghịch đảo giữa mức độ vận động thể chất đều đặn và mức độ căng thẳng được ghi nhận ở nhân viên văn phòng.","audioKind":"ex2"}],"collocations":[{"en":"inverse relationship","vi":"mối quan hệ nghịch đảo"},{"en":"inverse proportion","vi":"tỉ lệ nghịch"},{"en":"the inverse of","vi":"điều trái ngược của"},{"en":"inverse operation","vi":"phép tính ngược"}],"wordFamily":["inversely (adv.)","inversion (n.)","invert (v.)"],"synonyms":["reverse","opposite"],"antonyms":[],"tipVi":"Mối quan hệ nghịch đảo (inverse relationship) có nghĩa là khi một bên tăng lên thì bên kia giảm xuống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mutation', 'en-c1-54', 'mutation', '/mjuːˈteɪʃən/', 'C1', 'sự đột biến gen', 'n.', 'mutate (v.), mutant (n.)', NULL, 'Chỉ sự thay đổi trong vật liệu di truyền, không nhất thiết lúc nào cũng có hại.', 'A mutation gave this flower its unusual white petals.', NULL, 'Một đột biến gen đã tạo cho bông hoa này những cánh hoa màu trắng bất thường.', '{"wordId":"mutation","ukIpa":"/mjuːˈteɪʃən/","usIpa":"/mjuːˈteɪʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A change in the genetic material of an organism.","vi":"sự đột biến gen"}],"examples":[{"en":"A mutation gave this flower its unusual white petals.","vi":"Một đột biến gen đã tạo cho bông hoa này những cánh hoa màu trắng bất thường.","audioKind":"ex"},{"en":"A genetic mutation may increase disease risk, although environmental factors also influence whether symptoms eventually develop.","vi":"Đột biến gen có thể làm tăng nguy cơ mắc bệnh, mặc dù các yếu tố môi trường cũng ảnh hưởng đến việc các triệu chứng có cuối cùng xuất hiện hay không.","audioKind":"ex2"}],"collocations":[{"en":"genetic mutation","vi":"đột biến gen"},{"en":"spontaneous mutation","vi":"đột biến tự phát"},{"en":"mutation rate","vi":"tỷ lệ đột biến"}],"wordFamily":["mutate (v.)","mutant (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ sự thay đổi trong vật liệu di truyền, không nhất thiết lúc nào cũng có hại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embryo', 'en-c1-54', 'embryo', '/ˈembrioʊ/', 'C1', 'phôi; phôi thai (ở giai đoạn phát triển rất sớm của động vật hoặc thực vật)', 'n.', 'embryonic (adj.), embryology (n.)', NULL, 'Embryo là danh từ; khi muốn dùng dạng tính từ, ta dùng embryonic.', 'We could see the chick embryo inside the egg.', NULL, 'Chúng tôi có thể nhìn thấy phôi gà nằm bên trong quả trứng.', '{"wordId":"embryo","ukIpa":"/ˈembriəʊ/","usIpa":"/ˈembrioʊ/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"An animal or plant at a very early developmental stage","vi":"phôi; phôi thai (ở giai đoạn phát triển rất sớm của động vật hoặc thực vật)"}],"examples":[{"en":"We could see the chick embryo inside the egg.","vi":"Chúng tôi có thể nhìn thấy phôi gà nằm bên trong quả trứng.","audioKind":"ex"},{"en":"Researchers study how environmental conditions affect embryo development to improve the breeding of endangered species.","vi":"Các nhà nghiên cứu nghiên cứu cách các điều kiện môi trường ảnh hưởng đến quá trình phát triển của phôi nhằm cải thiện công tác bảo tồn giống loài có nguy cơ tuyệt chủng.","audioKind":"ex2"}],"collocations":[{"en":"embryo development","vi":"quá trình phát triển phôi"},{"en":"human embryo","vi":"phôi người"},{"en":"plant embryo","vi":"phôi thực vật"},{"en":"in embryo","vi":"ở giai đoạn trứng nước; trong thời kỳ phôi thai"}],"wordFamily":["embryonic (adj.)","embryology (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Embryo là danh từ; khi muốn dùng dạng tính từ, ta dùng embryonic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oxidize', 'en-c1-54', 'oxidize', '/ˈɑːksɪdaɪz/', 'C1', 'oxi hóa', 'v.', 'oxidation (n.), oxide (n.), oxidizing (adj.)', 'Trái nghĩa: reduce', 'Trong tiếng Anh Anh còn được viết là oxidise; quá trình oxi hóa không nhất thiết phải liên quan đến khí oxy.', 'The cut apple began to oxidize and turn brown.', NULL, 'Miếng táo cắt ra bắt đầu bị oxi hóa và chuyển sang màu nâu.', '{"wordId":"oxidize","ukIpa":"/ˈɒksɪdaɪz/","usIpa":"/ˈɑːksɪdaɪz/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To react with oxygen, or lose electrons in a chemical reaction.","vi":"oxi hóa"}],"examples":[{"en":"The cut apple began to oxidize and turn brown.","vi":"Miếng táo cắt ra bắt đầu bị oxi hóa và chuyển sang màu nâu.","audioKind":"ex"},{"en":"When exposed to air and moisture, iron can oxidize, weakening structures unless protective coatings are applied.","vi":"Khi tiếp xúc với không khí và độ ẩm, sắt có thể bị oxi hóa, làm suy yếu cấu trúc trừ khi được phủ lớp bảo vệ.","audioKind":"ex2"}],"collocations":[{"en":"oxidize rapidly","vi":"oxi hóa nhanh chóng"},{"en":"oxidize in air","vi":"oxi hóa trong không khí"},{"en":"readily oxidize","vi":"dễ bị oxi hóa"}],"wordFamily":["oxidation (n.)","oxide (n.)","oxidizing (adj.)"],"synonyms":[],"antonyms":["reduce"],"tipVi":"Trong tiếng Anh Anh còn được viết là oxidise; quá trình oxi hóa không nhất thiết phải liên quan đến khí oxy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_equilibrium', 'en-c1-54', 'equilibrium', '/ˌiːkwɪˈlɪbriəm/', 'C1', 'sự cân bằng; trạng thái cân bằng; sự bình tĩnh; sự cân bằng tâm lý', 'n.', NULL, 'Đồng nghĩa: balance · Trái nghĩa: imbalance, disequilibrium', 'Thường là danh từ không đếm được; hay được dùng trong kinh tế học, sinh thái học hoặc vật lý để chỉ sự cân bằng.', 'The hanging mobile regained equilibrium when I moved one ornament.', NULL, 'Chiếc đồ trang trí treo đã lấy lại được sự cân bằng khi tôi di chuyển một vật trang trí.', '{"wordId":"equilibrium","ukIpa":"/ˌiːkwɪˈlɪbriəm/","usIpa":"/ˌiːkwɪˈlɪbriəm/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A stable state in which opposing forces or influences balance.","vi":"sự cân bằng; trạng thái cân bằng"},{"pos":"n.","en":"A calm and emotionally stable state.","vi":"sự bình tĩnh; sự cân bằng tâm lý"}],"examples":[{"en":"The hanging mobile regained equilibrium when I moved one ornament.","vi":"Chiếc đồ trang trí treo đã lấy lại được sự cân bằng khi tôi di chuyển một vật trang trí.","audioKind":"ex"},{"en":"Removing a major predator can disturb the equilibrium of an ecosystem and cause unexpected changes in animal populations.","vi":"Việc loại bỏ một loài săn mồi quan trọng có thể làm rối loạn cân bằng sinh thái và gây ra những thay đổi bất ngờ trong số lượng quần thể động vật.","audioKind":"ex2"}],"collocations":[{"en":"maintain equilibrium","vi":"duy trì sự cân bằng"},{"en":"restore equilibrium","vi":"khôi phục sự cân bằng"},{"en":"market equilibrium","vi":"cân bằng thị trường"},{"en":"dynamic equilibrium","vi":"cân bằng động"}],"wordFamily":[],"synonyms":["balance"],"antonyms":["imbalance","disequilibrium"],"tipVi":"Thường là danh từ không đếm được; hay được dùng trong kinh tế học, sinh thái học hoặc vật lý để chỉ sự cân bằng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deflection', 'en-c1-54', 'deflection', '/dɪˈflekʃən/', 'C1', 'sự lệch hướng, đổi hướng do va chạm hoặc lực tác động khác; hành động chuyển hướng chú ý hoặc chỉ trích khỏi một việc gì đó', 'n.', 'deflect (v.)', 'Đồng nghĩa: deviation', 'Nhấn mạnh việc thay đổi hướng đi sau khi chịu lực; trong kỹ thuật còn chỉ hiện tượng uốn võng của cấu kiện.', 'A slight deflection sent the ball past the goalkeeper.', NULL, 'Một pha đổi hướng nhẹ đã đưa bóng bay qua người thủ môn.', '{"wordId":"deflection","ukIpa":"/dɪˈflekʃən/","usIpa":"/dɪˈflekʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A change in direction caused by contact or another force","vi":"sự lệch hướng, đổi hướng do va chạm hoặc lực tác động khác"},{"pos":"n.","en":"The act of directing attention or criticism away from something","vi":"hành động chuyển hướng chú ý hoặc chỉ trích khỏi một việc gì đó"}],"examples":[{"en":"A slight deflection sent the ball past the goalkeeper.","vi":"Một pha đổi hướng nhẹ đã đưa bóng bay qua người thủ môn.","audioKind":"ex"},{"en":"Engineers measure the deflection of structural beams to assess whether a bridge can safely support heavy traffic.","vi":"Các kỹ sư đo độ võng của các dầm kết cấu để đánh giá xem cây cầu có thể chịu được lưu lượng giao thông nặng an toàn hay không.","audioKind":"ex2"}],"collocations":[{"en":"deflection of light","vi":"sự lệch hướng của ánh sáng"},{"en":"beam deflection","vi":"độ võng của dầm"},{"en":"deflection of criticism","vi":"sự chuyển hướng chỉ trích"}],"wordFamily":["deflect (v.)"],"synonyms":["deviation"],"antonyms":[],"tipVi":"Nhấn mạnh việc thay đổi hướng đi sau khi chịu lực; trong kỹ thuật còn chỉ hiện tượng uốn võng của cấu kiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oscillate', 'en-c1-54', 'oscillate', '/ˈɑːsɪleɪt/', 'C1', 'chuyển động lặp đi lặp lại qua lại; dao động; liên tục thay đổi giữa các cảm xúc, quan điểm hoặc mức độ khác nhau', 'v.', 'oscillation (n.), oscillator (n.), oscillatory (adj.)', 'Đồng nghĩa: swing, fluctuate', 'Diễn tả sự dao động qua lại giữa hai trạng thái, thường dùng cấu trúc oscillate between A and B.', 'The fan oscillates slowly, cooling both sides of the room.', NULL, 'Quạt máy quay chậm rãi qua lại, thổi gió mát cho cả hai phía của căn phòng.', '{"wordId":"oscillate","ukIpa":"/ˈɒsɪleɪt/","usIpa":"/ˈɑːsɪleɪt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To move repeatedly backwards and forwards.","vi":"chuyển động lặp đi lặp lại qua lại; dao động"},{"pos":"v.","en":"To keep changing between different feelings, opinions, or levels.","vi":"liên tục thay đổi giữa các cảm xúc, quan điểm hoặc mức độ khác nhau"}],"examples":[{"en":"The fan oscillates slowly, cooling both sides of the room.","vi":"Quạt máy quay chậm rãi qua lại, thổi gió mát cho cả hai phía của căn phòng.","audioKind":"ex"},{"en":"Public opinion can oscillate between support and opposition as new information about environmental policies emerges.","vi":"Dư luận có thể dao động giữa sự ủng hộ và phản đối khi những thông tin mới về chính sách môi trường xuất hiện.","audioKind":"ex2"}],"collocations":[{"en":"oscillate between extremes","vi":"dao động giữa hai cực đoan"},{"en":"oscillate rapidly","vi":"dao động nhanh chóng"},{"en":"oscillating fan","vi":"quạt đảo gió"}],"wordFamily":["oscillation (n.)","oscillator (n.)","oscillatory (adj.)"],"synonyms":["swing","fluctuate"],"antonyms":[],"tipVi":"Diễn tả sự dao động qua lại giữa hai trạng thái, thường dùng cấu trúc oscillate between A and B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fluorescent', 'en-c1-54', 'fluorescent', '/flʊˈresənt/', 'C1', 'phát huỳnh quang; huỳnh quang; sáng rực; có màu chói (như màu huỳnh quang)', 'adj.', 'fluorescence (n.), fluoresce (v.)', NULL, 'Chú ý cách viết là fluorescent, thường đi kèm với lamp hoặc tube.', 'The fluorescent lamp flickered above the kitchen sink.', NULL, 'Đèn huỳnh quang nhấp nháy ở phía trên bồn rửa chén trong bếp.', '{"wordId":"fluorescent","ukIpa":"/flɔːˈresənt/","usIpa":"/flʊˈresənt/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Emitting light through fluorescence, or using this effect for lighting.","vi":"phát huỳnh quang; huỳnh quang"},{"pos":"adj.","en":"Having an extremely bright, noticeable colour.","vi":"sáng rực; có màu chói (như màu huỳnh quang)"}],"examples":[{"en":"The fluorescent lamp flickered above the kitchen sink.","vi":"Đèn huỳnh quang nhấp nháy ở phía trên bồn rửa chén trong bếp.","audioKind":"ex"},{"en":"Replacing fluorescent lighting with more efficient alternatives can lower electricity consumption in schools and offices.","vi":"Việc thay thế hệ thống chiếu sáng huỳnh quang bằng các giải pháp thay thế hiệu quả hơn có thể làm giảm lượng điện tiêu thụ ở trường học và văn phòng.","audioKind":"ex2"}],"collocations":[{"en":"fluorescent lighting","vi":"hệ thống chiếu sáng huỳnh quang"},{"en":"fluorescent tube","vi":"ống đèn huỳnh quang"},{"en":"fluorescent yellow","vi":"màu vàng huỳnh quang"}],"wordFamily":["fluorescence (n.)","fluoresce (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Chú ý cách viết là fluorescent, thường đi kèm với lamp hoặc tube.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_microbe', 'en-c1-54', 'microbe', '/ˈmaɪkroʊb/', 'C1', 'vi sinh vật', 'n.', 'microbial (adj.), microbiology (n.), microbiologist (n.)', 'Đồng nghĩa: microorganism', 'Không chỉ chỉ vi khuẩn, cũng không nhất thiết là có hại; germ thường chỉ mầm bệnh.', 'Some microbes help turn fresh milk into thick yoghurt.', NULL, 'Một số vi sinh vật giúp biến sữa tươi thành sữa chua đặc.', '{"wordId":"microbe","ukIpa":"/ˈmaɪkrəʊb/","usIpa":"/ˈmaɪkroʊb/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A living organism too small to see without a microscope","vi":"vi sinh vật"}],"examples":[{"en":"Some microbes help turn fresh milk into thick yoghurt.","vi":"Một số vi sinh vật giúp biến sữa tươi thành sữa chua đặc.","audioKind":"ex"},{"en":"Soil microbes play an essential role in recycling nutrients and maintaining the fertility of agricultural land.","vi":"Vi sinh vật trong đất đóng vai trò thiết yếu trong việc tuần hoàn chất dinh dưỡng và duy trì độ phì nhiêu của đất nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"soil microbes","vi":"vi sinh vật trong đất"},{"en":"harmful microbes","vi":"vi sinh vật có hại"},{"en":"beneficial microbes","vi":"vi sinh vật có lợi"}],"wordFamily":["microbial (adj.)","microbiology (n.)","microbiologist (n.)"],"synonyms":["microorganism"],"antonyms":[],"tipVi":"Không chỉ chỉ vi khuẩn, cũng không nhất thiết là có hại; germ thường chỉ mầm bệnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_capillary', 'en-c1-54', 'capillary', '/ˈkæpəleri/', 'C1', 'mạch máu nhỏ; ống mao dẫn; thuộc mao mạch; thuộc hiện tượng mao dẫn', 'n.', NULL, NULL, 'Danh từ số nhiều là capillaries; phát âm trọng âm có sự khác biệt giữa tiếng Anh-Anh và Anh-Mỹ.', 'The diagram shows a capillary beside several skin cells.', NULL, 'Sơ đồ minh họa một mao mạch nằm cạnh một số tế bào da.', '{"wordId":"capillary","ukIpa":"/kəˈpɪləri/","usIpa":"/ˈkæpəleri/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"a tiny blood vessel or an extremely narrow tube","vi":"mạch máu nhỏ; ống mao dẫn"},{"pos":"adj.","en":"relating to tiny blood vessels or liquid movement through narrow spaces","vi":"thuộc mao mạch; thuộc hiện tượng mao dẫn"}],"examples":[{"en":"The diagram shows a capillary beside several skin cells.","vi":"Sơ đồ minh họa một mao mạch nằm cạnh một số tế bào da.","audioKind":"ex"},{"en":"Capillary action allows water to move through narrow spaces in soil, helping moisture reach plant roots.","vi":"Hiện tượng mao dẫn cho phép nước di chuyển qua các khe hở nhỏ trong đất, giúp độ ẩm đi đến tận rễ cây.","audioKind":"ex2"}],"collocations":[{"en":"capillary action","vi":"hiện tượng mao dẫn"},{"en":"capillary blood","vi":"máu mao mạch"},{"en":"capillary tube","vi":"ống mao dẫn"},{"en":"capillary network","vi":"mạng lưới mao mạch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ số nhiều là capillaries; phát âm trọng âm có sự khác biệt giữa tiếng Anh-Anh và Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_54_1', 'en-c1-54', 'Cách dùng “ignite” (v.) — làm bốc cháy; đốt cháy', 'ignite a fire  ·  ignite interest  ·  ignite a debate', 'Có thể dùng theo cả nghĩa ngoại động từ và nội động từ; ngoài ra còn dùng theo nghĩa bóng để chỉ việc khơi dậy sự quan tâm hoặc tranh luận.', 'Họ từ (Word Family): ignition (n.) | Đồng nghĩa: light, kindle · Trái nghĩa: extinguish', '[{"hanzi":"A tiny spark ignited the dry wood in the fireplace.","pinyin":"","meaning":"Một tia lửa nhỏ đã bén vào đống củi khô trong lò sưởi."},{"hanzi":"Practical science lessons can ignite students'' curiosity and encourage them to explore unfamiliar ideas independently.","pinyin":"","meaning":"Các tiết học khoa học thực tế có thể khơi gợi trí tò mò của học sinh và khuyến khích các em tự mình khám phá những ý tưởng lạ lẫm."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_54_2', 'en-c1-54', 'Cách dùng “atmospheric” (adj.) — thuộc khí quyển', 'atmospheric pressure  ·  atmospheric conditions  ·  atmospheric pollution', 'Khi bổ nghĩa cho pressure, từ này chỉ áp suất khí quyển; khi bổ nghĩa cho không gian/địa điểm, từ này thường chỉ khung cảnh giàu cảm xúc.', 'Họ từ (Word Family): atmosphere (n.), atmospherically (adv.)', '[{"hanzi":"We found an atmospheric café tucked behind the old theatre.","pinyin":"","meaning":"Chúng tôi đã tìm thấy một quán cà phê mang đậm không khí ấm cúng nằm ẩn mình phía sau nhà hát cũ."},{"hanzi":"Changes in atmospheric conditions can affect agricultural production and increase the frequency of extreme weather events.","pinyin":"","meaning":"Sự biến đổi của các điều kiện khí quyển có thể ảnh hưởng đến sản xuất nông nghiệp và làm gia tăng tần suất xuất hiện của các hiện tượng thời tiết cực đoan."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_54_3', 'en-c1-54', 'Cách dùng “equilibrium” (n.) — sự cân bằng; trạng thái cân bằng', 'maintain equilibrium  ·  restore equilibrium  ·  market equilibrium', 'Thường là danh từ không đếm được; hay được dùng trong kinh tế học, sinh thái học hoặc vật lý để chỉ sự cân bằng.', 'Đồng nghĩa: balance · Trái nghĩa: imbalance, disequilibrium', '[{"hanzi":"The hanging mobile regained equilibrium when I moved one ornament.","pinyin":"","meaning":"Chiếc đồ trang trí treo đã lấy lại được sự cân bằng khi tôi di chuyển một vật trang trí."},{"hanzi":"Removing a major predator can disturb the equilibrium of an ecosystem and cause unexpected changes in animal populations.","pinyin":"","meaning":"Việc loại bỏ một loài săn mồi quan trọng có thể làm rối loạn cân bằng sinh thái và gây ra những thay đổi bất ngờ trong số lượng quần thể động vật."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_54_4', 'en-c1-54', 'Cách dùng “empirical” (adj.) — dựa trên thực nghiệm; thực tế; theo kinh nghiệm', 'empirical evidence  ·  empirical research  ·  empirical data', 'Nhấn mạnh vào cơ sở quan sát hoặc thí nghiệm, khác với những lời đồn đoán hay kinh nghiệm chủ quan đơn thuần.', 'Họ từ (Word Family): empirically (adv.), empiricism (n.), empiricist (n.) | Trái nghĩa: theoretical', '[{"hanzi":"Our garden trial provided empirical evidence that compost helps plants.","pinyin":"","meaning":"Thí nghiệm trồng cây ở vườn nhà đã cung cấp bằng chứng thực tế cho thấy phân hữu ích cho cây cối."},{"hanzi":"Education policies should be supported by empirical research rather than assumptions about how children learn.","pinyin":"","meaning":"Các chính sách giáo dục nên được hỗ trợ bằng nghiên cứu thực nghiệm thay vì dựa trên những giả định về cách trẻ em học tập."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_54_1', 'en-c1-54', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_1_1', 'ten_c1_54_1', 'threshold', 'My brother has a much higher pain threshold than me.', 'My brother has a much higher pain threshold than me.', '/ˈθreʃhoʊld/', 'Em trai tôi có khả năng chịu đau cao hơn tôi rất nhiều.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_1_2', 'ten_c1_54_1', 'empirical', 'Our garden trial provided empirical evidence that compost helps plants.', 'Our garden trial provided empirical evidence that compost helps plants.', '/ɪmˈpɪrɪkəl/', 'Thí nghiệm trồng cây ở vườn nhà đã cung cấp bằng chứng thực tế cho thấy phân hữu ích cho cây cối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_1_3', 'ten_c1_54_1', 'spherical', 'A spherical lamp hung above the dining table.', 'A spherical lamp hung above the dining table.', '/ˈsfɪrɪkəl/', 'Một chiếc đèn hình cầu được treo phía trên bàn ăn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_1_4', 'ten_c1_54_1', 'cosmos', 'Looking through the telescope made me curious about the cosmos.', 'Looking through the telescope made me curious about the cosmos.', '/ˈkɑːzmoʊs/', 'Nhìn qua kính thiên văn khiến tôi cảm thấy tò mò về vũ trụ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_1_5', 'ten_c1_54_1', 'eclipse', 'We watched the lunar eclipse from our garden last night.', 'We watched the lunar eclipse from our garden last night.', '/ɪˈklɪps/', 'Chúng tôi đã ngắm hiện tượng nguyệt thực từ khu vườn của mình vào tối qua.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_1_6', 'ten_c1_54_1', 'infinity', 'The desert seemed to stretch away into infinity.', 'The desert seemed to stretch away into infinity.', '/ɪnˈfɪnəti/', 'Sa mạc dường như trải dài đến tận cõi vô tận.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_1_7', 'ten_c1_54_1', 'zoology', 'My cousin studies zoology and spends weekends watching birds.', 'My cousin studies zoology and spends weekends watching birds.', '/zoʊˈɑːlədʒi/', 'Em họ tôi học ngành động vật học và dành các ngày cuối tuần để quan sát chim chóc.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_1_8', 'ten_c1_54_1', 'variant', 'This local variant of the soup includes fresh beans.', 'This local variant of the soup includes fresh beans.', '/ˈveriənt/', 'Món súp phiên bản địa phương này có cho thêm đậu tươi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_54_1_1', 'en-c1-54', 'ten_c1_54_1', 'listening', 'listening', 'My brother has a much higher pain threshold than me.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thời gian rảnh và khối lượng công việc của chúng tôi có mối quan hệ nghịch đảo với nhau.","Em trai tôi có khả năng chịu đau cao hơn tôi rất nhiều.","Quạt máy quay chậm rãi qua lại, thổi gió mát cho cả hai phía của căn phòng.","Chúng tôi đã tìm thấy một quán cà phê mang đậm không khí ấm cúng nằm ẩn mình phía sau nhà hát cũ."]'::jsonb, 1, 'My brother has a much higher pain threshold than me. → Em trai tôi có khả năng chịu đau cao hơn tôi rất nhiều.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_54_1_2', 'en-c1-54', 'ten_c1_54_1', 'listening', 'listening', 'Our garden trial provided empirical evidence that compost helps plants.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Em trai tôi có khả năng chịu đau cao hơn tôi rất nhiều.","Đèn huỳnh quang nhấp nháy ở phía trên bồn rửa chén trong bếp.","Nhìn qua kính thiên văn khiến tôi cảm thấy tò mò về vũ trụ.","Thí nghiệm trồng cây ở vườn nhà đã cung cấp bằng chứng thực tế cho thấy phân hữu ích cho cây cối."]'::jsonb, 3, 'Our garden trial provided empirical evidence that compost helps plants. → Thí nghiệm trồng cây ở vườn nhà đã cung cấp bằng chứng thực tế cho thấy phân hữu ích cho cây cối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_54_1_3', 'en-c1-54', 'ten_c1_54_1', 'listening', 'listening', 'A spherical lamp hung above the dining table.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc đồ trang trí treo đã lấy lại được sự cân bằng khi tôi di chuyển một vật trang trí.","Một chiếc đèn hình cầu được treo phía trên bàn ăn.","Thí nghiệm trồng cây ở vườn nhà đã cung cấp bằng chứng thực tế cho thấy phân hữu ích cho cây cối.","Một đột biến gen đã tạo cho bông hoa này những cánh hoa màu trắng bất thường."]'::jsonb, 1, 'A spherical lamp hung above the dining table. → Một chiếc đèn hình cầu được treo phía trên bàn ăn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_54_2', 'en-c1-54', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_2_1', 'ten_c1_54_2', 'threshold', 'Raising the income threshold for financial assistance would allow more low-paid workers to receive support.', 'Raising the income threshold for financial assistance would allow more low-paid workers to receive support.', '/ˈθreʃhoʊld/', 'Việc nâng ngưỡng thu nhập để được hỗ trợ tài chính sẽ giúp nhiều lao động thu nhập thấp nhận được sự trợ giúp hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_2_2', 'ten_c1_54_2', 'empirical', 'Education policies should be supported by empirical research rather than assumptions about how children learn.', 'Education policies should be supported by empirical research rather than assumptions about how children learn.', '/ɪmˈpɪrɪkəl/', 'Các chính sách giáo dục nên được hỗ trợ bằng nghiên cứu thực nghiệm thay vì dựa trên những giả định về cách trẻ em học tập.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_2_3', 'ten_c1_54_2', 'spherical', 'Researchers use spherical particles of different sizes to investigate how pollutants move through water filtration systems.', 'Researchers use spherical particles of different sizes to investigate how pollutants move through water filtration systems.', '/ˈsfɪrɪkəl/', 'Các nhà nghiên cứu sử dụng các hạt hình cầu có kích thước khác nhau để tìm hiểu cách các chất ô nhiễm di chuyển qua hệ thống lọc nước.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_2_4', 'ten_c1_54_2', 'cosmos', 'Studying the cosmos helps scientists investigate how galaxies formed and how the universe has changed over time.', 'Studying the cosmos helps scientists investigate how galaxies formed and how the universe has changed over time.', '/ˈkɑːzmoʊs/', 'Nghiên cứu vũ trụ giúp các nhà khoa học tìm hiểu các thiên hà hình thành như thế nào và vũ trụ đã thay đổi ra sao theo thời gian.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_2_5', 'ten_c1_54_2', 'eclipse', 'Investment in digital services may eclipse spending on traditional infrastructure as economies become increasingly dependent on technology.', 'Investment in digital services may eclipse spending on traditional infrastructure as economies become increasingly dependent on technology.', '/ɪˈklɪps/', 'Khoản đầu tư vào các dịch vụ số có thể làm lu mờ chi phí dành cho cơ sở hạ tầng truyền thống khi nền kinh tế ngày càng phụ thuộc vào công nghệ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_54_2_6', 'ten_c1_54_2', 'infinity', 'The concept of infinity allows mathematicians to explore quantities beyond the limits of ordinary measurement.', 'The concept of infinity allows mathematicians to explore quantities beyond the limits of ordinary measurement.', '/ɪnˈfɪnəti/', 'Khái niệm vô cực cho phép các nhà toán học khám phá những đại lượng vượt ngoài giới hạn của các phép đo thông thường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_54_2_1', 'en-c1-54', 'ten_c1_54_2', 'listening', 'listening', 'Raising the income threshold for financial assistance would allow more low-paid workers to receive support.', NULL, 'Trong câu vừa nghe, từ “threshold” mang nghĩa nào sau đây?', '["ngưỡng; mức giới hạn","hình cầu; quả cầu","sự biến dạng; sự biến hình","vô ích; không thành công"]'::jsonb, 0, '“threshold” (/ˈθreʃhoʊld/): ngưỡng; mức giới hạn. Câu đầy đủ: Raising the income threshold for financial assistance would allow more low-paid workers to receive support.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_54_2_2', 'en-c1-54', 'ten_c1_54_2', 'listening', 'listening', 'Education policies should be supported by empirical research rather than assumptions about how children learn.', NULL, 'Trong câu vừa nghe, từ “empirical” mang nghĩa nào sau đây?', '["sai lệch; đi chệch; chệch hướng","chuột túi vằn; wallaby (loài thú có túi giống kangaroo nhưng nhỏ hơn)","tiền đề; giả định","dựa trên thực nghiệm; thực tế; theo kinh nghiệm"]'::jsonb, 3, '“empirical” (/ɪmˈpɪrɪkəl/): dựa trên thực nghiệm; thực tế; theo kinh nghiệm. Câu đầy đủ: Education policies should be supported by empirical research rather than assumptions about how children learn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
