INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_54_2', 'en-c1-54', 'Our garden trial provided empirical evidence that compost helps plants', 'Thí nghiệm trồng cây ở vườn nhà đã cung cấp bằng chứng thực tế cho thấy phân hữu ích cho cây cối.', 'empirical /ɪmˈpɪrɪkəl/', '["evidence","plants","helps","trial","empirical","garden","Our","compost","that","provided"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
