INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_54_4', 'en-c1-54', 'Looking through the telescope made me curious about the cosmos', 'Nhìn qua kính thiên văn khiến tôi cảm thấy tò mò về vũ trụ.', 'cosmos /ˈkɑːzmoʊs/', '["curious","made","through","about","the","cosmos","telescope","the","me","Looking"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_54_5', 'en-c1-54', 'We watched the lunar eclipse from our garden last night', 'Chúng tôi đã ngắm hiện tượng nguyệt thực từ khu vườn của mình vào tối qua.', 'eclipse /ɪˈklɪps/', '["last","from","We","garden","our","lunar","eclipse","night","watched","the"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_54_6', 'en-c1-54', 'The desert seemed to stretch away into infinity', 'Sa mạc dường như trải dài đến tận cõi vô tận.', 'infinity /ɪnˈfɪnəti/', '["to","stretch","The","into","infinity","desert","away","seemed"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_54_7', 'en-c1-54', 'My cousin studies zoology and spends weekends watching birds', 'Em họ tôi học ngành động vật học và dành các ngày cuối tuần để quan sát chim chóc.', 'zoology /zoʊˈɑːlədʒi/', '["and","zoology","weekends","birds","My","spends","studies","cousin","watching"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
