INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_54_14', 'en-c1-54', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “The part of a cell containing most of its genetic material.”', '["deflection","inhibit","oxidize","nucleus"]'::jsonb, 3, '“nucleus” (/ˈnuːkliəs/) nghĩa là: tế bào nhân; nhân tế bào.', 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_54_15', 'en-c1-54', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “ignite” (/ɪɡˈnaɪt/) có nghĩa là gì?', '["áp kế; khí áp kế","chuyển động lặp đi lặp lại qua lại; dao động","làm bốc cháy; đốt cháy","biến thể; biến chủng"]'::jsonb, 2, '“ignite” (v.): làm bốc cháy; đốt cháy; khơi nguồn; kích thích.', 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_1', 'en-c1-54', NULL, 'comprehensive_test', 'listening', 'threshold', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tưởng niệm; kỷ niệm","thu thập và tổng hợp thông tin từ nhiều nguồn khác nhau; biên soạn","khả thi; có thể thực hiện được","ngưỡng; mức giới hạn"]'::jsonb, 3, 'threshold (/ˈθreʃhoʊld/) → ngưỡng; mức giới hạn; ngưỡng cửa; bước ngoặt', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_2', 'en-c1-54', NULL, 'comprehensive_test', 'listening', 'Our garden trial provided empirical evidence that compost helps plants.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thí nghiệm trồng cây ở vườn nhà đã cung cấp bằng chứng thực tế cho thấy phân hữu ích cho cây cối.","Chiếc đồ trang trí treo đã lấy lại được sự cân bằng khi tôi di chuyển một vật trang trí.","Một số vi sinh vật giúp biến sữa tươi thành sữa chua đặc.","Nhân của tế bào trông có màu tím dưới kính hiển vi ở lớp học của chúng tôi."]'::jsonb, 0, 'Our garden trial provided empirical evidence that compost helps plants. → Thí nghiệm trồng cây ở vườn nhà đã cung cấp bằng chứng thực tế cho thấy phân hữu ích cho cây cối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_3', 'en-c1-54', NULL, 'comprehensive_test', 'listening', 'spherical', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hình cầu; có dạng hình cầu","an ủi; vỗ về ai đó đang buồn bã hoặc thất vọng","xấu xí; gớm ghiếc","người trong cuộc; người nội bộ"]'::jsonb, 0, 'spherical (/ˈsfɪrɪkəl/) → hình cầu; có dạng hình cầu', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_4', 'en-c1-54', NULL, 'comprehensive_test', 'listening', 'Looking through the telescope made me curious about the cosmos.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đôi bốt này có khả năng chống thấm nước và rất dễ lau chùi.","Nhìn qua kính thiên văn khiến tôi cảm thấy tò mò về vũ trụ.","Món súp phiên bản địa phương này có cho thêm đậu tươi.","Em trai tôi có khả năng chịu đau cao hơn tôi rất nhiều."]'::jsonb, 1, 'Looking through the telescope made me curious about the cosmos. → Nhìn qua kính thiên văn khiến tôi cảm thấy tò mò về vũ trụ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_5', 'en-c1-54', NULL, 'comprehensive_test', 'listening', 'eclipse', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có khả năng tính toán; giỏi tính toán","giáp ranh; liền kề; nối liền","phạm vi; chuỗi (ý tưởng, phẩm chất, khả năng)","nhật thực; nguyệt thực"]'::jsonb, 3, 'eclipse (/ɪˈklɪps/) → nhật thực; nguyệt thực; làm lu mờ; vượt trội hơn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_6', 'en-c1-54', NULL, 'comprehensive_test', 'listening', 'The desert seemed to stretch away into infinity.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một số vi sinh vật giúp biến sữa tươi thành sữa chua đặc.","Em họ tôi hiến huyết tương tại phòng khám địa phương.","Sa mạc dường như trải dài đến tận cõi vô tận.","Chúng tôi đã kiểm tra khí áp kế trước khi chèo thuyền vượt vịnh."]'::jsonb, 2, 'The desert seemed to stretch away into infinity. → Sa mạc dường như trải dài đến tận cõi vô tận.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_7', 'en-c1-54', NULL, 'comprehensive_test', 'listening', 'zoology', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự bất hòa; sự chia rẽ; mối bất đồng","động vật học","tưởng niệm; kỷ niệm","lỗi thời; cổ lỗ sĩ; cũ kỹ"]'::jsonb, 1, 'zoology (/zoʊˈɑːlədʒi/) → động vật học', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_8', 'en-c1-54', NULL, 'comprehensive_test', 'listening', 'This local variant of the soup includes fresh beans.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thời tiết lạnh có thể ức chế sự sinh trưởng của các loài cây này.","Món súp phiên bản địa phương này có cho thêm đậu tươi.","Em trai tôi có khả năng chịu đau cao hơn tôi rất nhiều.","Một tia lửa nhỏ đã bén vào đống củi khô trong lò sưởi."]'::jsonb, 1, 'This local variant of the soup includes fresh beans. → Món súp phiên bản địa phương này có cho thêm đậu tươi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_9', 'en-c1-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “an event when one celestial body blocks another''s light”?', '["symmetry","inhibit","eclipse","inverse"]'::jsonb, 2, 'eclipse (/ɪˈklɪps/) → nhật thực; nguyệt thực', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_10', 'en-c1-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The state of having no end or limit.”?', '["symmetry","fluorescent","infinity","variant"]'::jsonb, 2, 'infinity (/ɪnˈfɪnəti/) → vô cực; vô tận', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_11', 'en-c1-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the scientific study of animals”?', '["oscillate","inhibit","zoology","oxidize"]'::jsonb, 2, 'zoology (/zoʊˈɑːlədʒi/) → động vật học', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_12', 'en-c1-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A form that differs slightly from other related forms.”?', '["deflection","zoology","variant","cosmos"]'::jsonb, 2, 'variant (/ˈveriənt/) → biến thể; biến chủng', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
