INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_18', 'en-c1-54', NULL, 'comprehensive_test', 'reading', NULL, 'Raising the income threshold for financial assistance would allow more low-paid workers to receive support.', 'Dựa vào câu trên, từ “threshold” có nghĩa phù hợp nhất là gì?', '["sự mâu thuẫn; sự bất nhất","héc-ta; công-ta (đơn vị diện tích bằng 10.000 mét vuông)","mang tính quốc tế, giao thoa văn hóa từ nhiều quốc gia khác nhau","ngưỡng; mức giới hạn"]'::jsonb, 3, 'threshold: ngưỡng; mức giới hạn; ngưỡng cửa; bước ngoặt. Dịch cả câu: Việc nâng ngưỡng thu nhập để được hỗ trợ tài chính sẽ giúp nhiều lao động thu nhập thấp nhận được sự trợ giúp hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_19', 'en-c1-54', NULL, 'comprehensive_test', 'reading', NULL, 'Education policies should be supported by empirical research rather than assumptions about how children learn.', 'Dựa vào câu trên, từ “empirical” có nghĩa phù hợp nhất là gì?', '["giả mạo; giả tạo","ngữ âm học","dựa trên thực nghiệm; thực tế; theo kinh nghiệm","có thể quy cho; do... gây ra"]'::jsonb, 2, 'empirical: dựa trên thực nghiệm; thực tế; theo kinh nghiệm. Dịch cả câu: Các chính sách giáo dục nên được hỗ trợ bằng nghiên cứu thực nghiệm thay vì dựa trên những giả định về cách trẻ em học tập.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_20', 'en-c1-54', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers use spherical particles of different sizes to investigate how pollutants move through water filtration systems.', 'Dựa vào câu trên, từ “spherical” có nghĩa phù hợp nhất là gì?', '["có tính giáo dục; mang lại nhiều bài học bổ ích","hải dương học","thật thà; thẳng thắn; bộc trực","hình cầu; có dạng hình cầu"]'::jsonb, 3, 'spherical: hình cầu; có dạng hình cầu. Dịch cả câu: Các nhà nghiên cứu sử dụng các hạt hình cầu có kích thước khác nhau để tìm hiểu cách các chất ô nhiễm di chuyển qua hệ thống lọc nước.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_21', 'en-c1-54', NULL, 'comprehensive_test', 'reading', NULL, 'Studying the cosmos helps scientists investigate how galaxies formed and how the universe has changed over time.', 'Dựa vào câu trên, từ “cosmos” có nghĩa phù hợp nhất là gì?', '["thuế quan; thuế xuất nhập khẩu hàng hóa","gian khổ; tốn nhiều thời gian và công sức","vũ trụ (được xem như một hệ thống có trật tự, hoàn chỉnh)","bờ vực; nguy cơ cận kề"]'::jsonb, 2, 'cosmos: vũ trụ (được xem như một hệ thống có trật tự, hoàn chỉnh). Dịch cả câu: Nghiên cứu vũ trụ giúp các nhà khoa học tìm hiểu các thiên hà hình thành như thế nào và vũ trụ đã thay đổi ra sao theo thời gian.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_22', 'en-c1-54', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phát huỳnh quang; huỳnh quang”', '["aggregation","fluorescent","lubrication","restraint"]'::jsonb, 1, 'phát huỳnh quang; huỳnh quang → fluorescent (/flʊˈresənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_23', 'en-c1-54', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vi sinh vật”', '["hallmark","refuge","microbe","stipulate"]'::jsonb, 2, 'vi sinh vật → microbe (/ˈmaɪkroʊb/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_54_24', 'en-c1-54', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mạch máu nhỏ; ống mao dẫn”', '["parasite","capillary","ultimatum","decree"]'::jsonb, 1, 'mạch máu nhỏ; ống mao dẫn → capillary (/ˈkæpəleri/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-55', 'en', 'Bài 55: Khoa học & Nghiên cứu (2) - CEFR C1', 'CEFR C1', 'C1 · Khoa học', '26 từ vựng Tiếng Anh CEFR C1 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5055, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fission', 'en-c1-55', 'fission', '/ˈfɪʃən/', 'C1', 'sự phân hạch; sự tách hạt nhân nguyên tử; sự phân rẽ; sự sinh sản bằng cách phân chia', 'n.', 'fissile (adj.)', 'Trái nghĩa: fusion', 'Trong vật lý hạt nhân, fission là phân hạch, còn fusion là nhiệt hạch.', 'We watched an animation showing fission at the science museum.', NULL, 'Chúng tôi đã xem một đoạn phim hoạt hình mô tả hiện tượng phân hạch tại bảo tàng khoa học.', '{"wordId":"fission","ukIpa":"/ˈfɪʃən/","usIpa":"/ˈfɪʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The splitting of an atomic nucleus, usually releasing energy.","vi":"sự phân hạch; sự tách hạt nhân nguyên tử"},{"pos":"n.","en":"Reproduction in which one organism divides into separate organisms.","vi":"sự phân rẽ; sự sinh sản bằng cách phân chia"}],"examples":[{"en":"We watched an animation showing fission at the science museum.","vi":"Chúng tôi đã xem một đoạn phim hoạt hình mô tả hiện tượng phân hạch tại bảo tàng khoa học.","audioKind":"ex"},{"en":"Nuclear fission generates electricity without direct carbon emissions, but managing radioactive waste remains a major challenge.","vi":"Phản ứng phân hạch hạt nhân tạo ra điện năng mà không thải ra trực tiếp khí carbon, nhưng việc quản lý chất thải phóng xạ vẫn là một thử thách lớn.","audioKind":"ex2"}],"collocations":[{"en":"nuclear fission","vi":"phân hạch hạt nhân"},{"en":"binary fission","vi":"phân đôi"},{"en":"a fission reaction","vi":"phản ứng phân hạch"}],"wordFamily":["fissile (adj.)"],"synonyms":[],"antonyms":["fusion"],"tipVi":"Trong vật lý hạt nhân, fission là phân hạch, còn fusion là nhiệt hạch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quartz', 'en-c1-55', 'quartz', '/kwɔːrts/', 'C1', 'thạch anh', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; khi chỉ một khối thạch anh, dùng a piece of quartz.', 'She found a piece of quartz beside the stream.', NULL, 'Cô ấy tìm thấy một mảnh thạch anh bên bờ suối.', '{"wordId":"quartz","ukIpa":"/kwɔːts/","usIpa":"/kwɔːrts/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"a hard mineral common in rocks and used in electronics","vi":"thạch anh"}],"examples":[{"en":"She found a piece of quartz beside the stream.","vi":"Cô ấy tìm thấy một mảnh thạch anh bên bờ suối.","audioKind":"ex"},{"en":"Quartz crystals are used in electronic devices because their regular vibrations enable highly accurate time measurement.","vi":"Tinh thể thạch anh được sử dụng trong các thiết bị điện tử vì độ dao động ổn định của chúng cho phép đo thời gian cực kỳ chính xác.","audioKind":"ex2"}],"collocations":[{"en":"quartz crystal","vi":"tinh thể thạch anh"},{"en":"quartz watch","vi":"đồng hồ thạch anh"},{"en":"rose quartz","vi":"thạch anh hồng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; khi chỉ một khối thạch anh, dùng a piece of quartz.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_periodic', 'en-c1-55', 'periodic', '/ˌpɪriˈɑːdɪk/', 'C1', 'mang tính chu kỳ; định kỳ; có thời hạn', 'adj.', 'period (n.), periodically (adv.), periodicity (n.)', 'Đồng nghĩa: recurring', 'periodic là tính từ, không phải danh từ; phó từ là periodically.', 'The old boiler needs periodic checks to keep working safely.', NULL, 'Lò hơi cũ cần được kiểm tra định kỳ để vận hành an toàn.', '{"wordId":"periodic","ukIpa":"/ˌpɪəriˈɒdɪk/","usIpa":"/ˌpɪriˈɑːdɪk/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"happening repeatedly, often at regular intervals","vi":"mang tính chu kỳ; định kỳ; có thời hạn"}],"examples":[{"en":"The old boiler needs periodic checks to keep working safely.","vi":"Lò hơi cũ cần được kiểm tra định kỳ để vận hành an toàn.","audioKind":"ex"},{"en":"Periodic assessments allow teachers to identify learning difficulties before students fall significantly behind their classmates.","vi":"Các bài đánh giá định kỳ giúp giáo viên phát hiện khó khăn học tập của học sinh trước khi các em bị tụt lại quá xa so với bạn cùng lớp.","audioKind":"ex2"}],"collocations":[{"en":"periodic checks","vi":"kiểm tra định kỳ"},{"en":"periodic review","vi":"đánh giá định kỳ"},{"en":"periodic table","vi":"bảng tuần hoàn"}],"wordFamily":["period (n.)","periodically (adv.)","periodicity (n.)"],"synonyms":["recurring"],"antonyms":[],"tipVi":"periodic là tính từ, không phải danh từ; phó từ là periodically.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deviation', 'en-c1-55', 'deviation', '/ˌdiːviˈeɪʃən/', 'C1', 'sự sai lệch; sự đi chệch; độ lệch; độ sai số', 'n.', 'deviate (v.)', 'Đồng nghĩa: departure, divergence', 'Thường kết hợp với giới từ from thành deviation from; cụm standard deviation có nghĩa là "độ lệch chuẩn".', 'A small deviation from our route revealed a quiet beach.', NULL, 'Một sự lệch hướng nhỏ khỏi lộ trình ban đầu đã đưa chúng tôi đến một bãi biển yên tĩnh.', '{"wordId":"deviation","ukIpa":"/ˌdiːviˈeɪʃən/","usIpa":"/ˌdiːviˈeɪʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"a departure from an expected route, rule, or behaviour","vi":"sự sai lệch; sự đi chệch"},{"pos":"n.","en":"the difference between a measurement and a reference value","vi":"độ lệch; độ sai số"}],"examples":[{"en":"A small deviation from our route revealed a quiet beach.","vi":"Một sự lệch hướng nhỏ khỏi lộ trình ban đầu đã đưa chúng tôi đến một bãi biển yên tĩnh.","audioKind":"ex"},{"en":"Any significant deviation from established safety procedures should be investigated to prevent accidents in the workplace.","vi":"Mọi sự sai lệch đáng kể so với các quy trình an toàn đã được thiết lập cần phải được điều tra để ngăn ngừa tai nạn tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"deviation from the norm","vi":"sự lệch khỏi tiêu chuẩn"},{"en":"standard deviation","vi":"độ lệch chuẩn"},{"en":"significant deviation","vi":"sự sai lệch đáng kể"}],"wordFamily":["deviate (v.)"],"synonyms":["departure","divergence"],"antonyms":[],"tipVi":"Thường kết hợp với giới từ from thành deviation from; cụm standard deviation có nghĩa là \"độ lệch chuẩn\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_optics', 'en-c1-55', 'optics', '/ˈɑːptɪks/', 'C1', 'quang học', 'n.', 'optical (adj.), optically (adv.)', NULL, 'Khi chỉ môn học quang học, dù tận cùng bằng chữ s nhưng vẫn đi với động từ số ít.', 'We explored optics by shining a torch through a prism.', NULL, 'Chúng tôi đã khám phá quang học bằng cách chiếu đèn pin qua một lăng kính.', '{"wordId":"optics","ukIpa":"/ˈɒptɪks/","usIpa":"/ˈɑːptɪks/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The scientific study of light and how it behaves","vi":"quang học"}],"examples":[{"en":"We explored optics by shining a torch through a prism.","vi":"Chúng tôi đã khám phá quang học bằng cách chiếu đèn pin qua một lăng kính.","audioKind":"ex"},{"en":"Advances in optics have improved medical imaging, allowing doctors to examine internal structures in greater detail.","vi":"Sự tiến bộ của quang học đã cải thiện hình ảnh y tế, cho phép các bác sĩ kiểm tra các cấu trúc bên trong chi tiết hơn.","audioKind":"ex2"}],"collocations":[{"en":"geometrical optics","vi":"quang học hình học"},{"en":"physical optics","vi":"quang học vật lý"},{"en":"fibre optics","vi":"công nghệ cáp quang"}],"wordFamily":["optical (adj.)","optically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ môn học quang học, dù tận cùng bằng chữ s nhưng vẫn đi với động từ số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_temporal', 'en-c1-55', 'temporal', '/ˈtempərəl/', 'C1', 'thuộc về thời gian; theo thứ tự thời gian; thuộc về trần tục; thế tục; thuộc về thái dương (vùng đầu)', 'adj.', 'temporally (adv.), temporality (n.)', NULL, 'temporal chỉ thời gian; temporary mới có nghĩa là tạm thời.', 'We arranged the family photos in temporal order.', NULL, 'Chúng tôi đã sắp xếp các bức ảnh gia đình theo thứ tự thời gian.', '{"wordId":"temporal","ukIpa":"/ˈtempərəl/","usIpa":"/ˈtempərəl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Relating to time or the order of events.","vi":"thuộc về thời gian; theo thứ tự thời gian"},{"pos":"adj.","en":"Relating to worldly affairs rather than spiritual matters.","vi":"thuộc về trần tục; thế tục"},{"pos":"adj.","en":"Relating to the sides of the head near the temples.","vi":"thuộc về thái dương (vùng đầu)"}],"examples":[{"en":"We arranged the family photos in temporal order.","vi":"Chúng tôi đã sắp xếp các bức ảnh gia đình theo thứ tự thời gian.","audioKind":"ex"},{"en":"Understanding temporal patterns in electricity demand can help cities manage their energy supplies more efficiently.","vi":"Việc thấu hiểu các quy luật thay đổi theo thời gian trong nhu cầu điện năng có thể giúp các quản lý nguồn năng lượng của thành phố hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"temporal order","vi":"thứ tự thời gian"},{"en":"temporal variation","vi":"sự biến đổi theo thời gian"},{"en":"temporal power","vi":"quyền lực thế tục"},{"en":"temporal lobe","vi":"thùy thái dương"}],"wordFamily":["temporally (adv.)","temporality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"temporal chỉ thời gian; temporary mới có nghĩa là tạm thời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_purity', 'en-c1-55', 'purity', '/ˈpjʊrəti/', 'C1', 'độ tinh khiết; sự tinh sạch; sự trong sáng; tính thuần khiết', 'n.', 'pure (adj.), purely (adv.), purify (v.), purification (n.)', 'Trái nghĩa: impurity', 'Danh từ không đếm được; chỉ độ tinh khiết cụ thể thường dùng the purity of.', 'The jeweller checked the purity of my gold ring.', NULL, 'Thợ kim hoàn đã kiểm tra độ tinh khiết của chiếc nhẫn vàng của tôi.', '{"wordId":"purity","ukIpa":"/ˈpjʊərəti/","usIpa":"/ˈpjʊrəti/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"the state of containing no unwanted or harmful substances","vi":"độ tinh khiết; sự tinh sạch"},{"pos":"n.","en":"the quality of being morally good or unmixed in character","vi":"sự trong sáng; tính thuần khiết"}],"examples":[{"en":"The jeweller checked the purity of my gold ring.","vi":"Thợ kim hoàn đã kiểm tra độ tinh khiết của chiếc nhẫn vàng của tôi.","audioKind":"ex"},{"en":"Regular monitoring of water purity is essential for preventing disease and maintaining public confidence in local supplies.","vi":"Việc thường xuyên giám sát độ tinh sạch của nguồn nước là vô cùng quan trọng để phòng ngừa bệnh tật và duy trì niềm tin của công chúng đối với nguồn nước sinh hoạt địa phương.","audioKind":"ex2"}],"collocations":[{"en":"water purity","vi":"độ tinh khiết của nước"},{"en":"high purity","vi":"độ tinh khiết cao"},{"en":"purity of gold","vi":"độ tuổi vàng; độ tinh khiết của vàng"}],"wordFamily":["pure (adj.)","purely (adv.)","purify (v.)","purification (n.)"],"synonyms":[],"antonyms":["impurity"],"tipVi":"Danh từ không đếm được; chỉ độ tinh khiết cụ thể thường dùng the purity of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_polymer', 'en-c1-55', 'polymer', '/ˈpɑːlɪmər/', 'C1', 'chất polymer; hợp chất cao phân tử', 'n.', 'polymeric (adj.), polymerise (v.), polymerisation (n.)', NULL, 'Polymer không chỉ bao gồm nhựa mà còn gồm các chất tự nhiên như tinh bột.', 'This flexible polymer keeps my phone case light and durable.', NULL, 'Chất polymer dẻo dai này giúp cho ốp điện thoại của tôi vừa nhẹ vừa bền.', '{"wordId":"polymer","ukIpa":"/ˈpɒlɪmə/","usIpa":"/ˈpɑːlɪmər/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A substance made of large molecules containing repeated smaller units.","vi":"chất polymer; hợp chất cao phân tử"}],"examples":[{"en":"This flexible polymer keeps my phone case light and durable.","vi":"Chất polymer dẻo dai này giúp cho ốp điện thoại của tôi vừa nhẹ vừa bền.","audioKind":"ex"},{"en":"Researchers are developing biodegradable polymers to reduce the environmental impact of packaging and other disposable products.","vi":"Các nhà nghiên cứu đang phát triển các loại polymer có khả năng phân hủy sinh học nhằm giảm thiểu tác động môi trường từ bao bì và các sản phẩm dùng một lần khác.","audioKind":"ex2"}],"collocations":[{"en":"synthetic polymer","vi":"polymer tổng hợp"},{"en":"biodegradable polymer","vi":"polymer phân hủy sinh học"},{"en":"polymer chain","vi":"chuỗi polymer"}],"wordFamily":["polymeric (adj.)","polymerise (v.)","polymerisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Polymer không chỉ bao gồm nhựa mà còn gồm các chất tự nhiên như tinh bột.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nickel', 'en-c1-55', 'nickel', '/ˈnɪkəl/', 'C1', 'niken; đồng năm xu (Mỹ hoặc Canada)', 'n.', 'nickel-plated (adj.)', NULL, 'Là danh từ không đếm được khi chỉ kim loại; là danh từ đếm được khi chỉ đồng năm xu.', 'My skin reacts badly to jewellery containing nickel.', NULL, 'Da tôi bị dị ứng nặng với đồ trang sức có chứa niken.', '{"wordId":"nickel","ukIpa":"/ˈnɪkəl/","usIpa":"/ˈnɪkəl/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A hard, silvery metal used in alloys and batteries.","vi":"niken"},{"pos":"n.","en":"A coin worth five cents in the US or Canada.","vi":"đồng năm xu (Mỹ hoặc Canada)"}],"examples":[{"en":"My skin reacts badly to jewellery containing nickel.","vi":"Da tôi bị dị ứng nặng với đồ trang sức có chứa niken.","audioKind":"ex"},{"en":"Growing demand for electric vehicles has increased interest in nickel mining, raising concerns about environmental damage.","vi":"Nhu cầu gia tăng đối với xe điện đã làm tăng sự quan tâm đến hoạt động khai thác nikel, đồng thời dấy lên lo ngại về tình trạng hủy hoại môi trường.","audioKind":"ex2"}],"collocations":[{"en":"nickel mining","vi":"khai thác nikel"},{"en":"nickel alloy","vi":"hợp kim nikel"},{"en":"nickel allergy","vi":"dị ứng nikel"}],"wordFamily":["nickel-plated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được khi chỉ kim loại; là danh từ đếm được khi chỉ đồng năm xu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_optimal', 'en-c1-55', 'optimal', '/ˈɑːptɪməl/', 'C1', 'tối ưu; tốt nhất; thuận lợi nhất', 'adj.', 'optimally (adv.), optimise (v.), optimisation (n.), optimum (adj.)', 'Đồng nghĩa: ideal, best · Trái nghĩa: suboptimal', 'Bản thân từ này đã mang nghĩa "tối ưu/tốt nhất", do đó thông thường không đi kèm với từ most phía trước.', 'This sunny windowsill provides optimal conditions for my herbs.', NULL, 'Bệ cửa sổ đầy nắng này tạo ra điều kiện lý tưởng nhất cho các loại thảo mộc của tôi.', '{"wordId":"optimal","ukIpa":"/ˈɒptɪməl/","usIpa":"/ˈɑːptɪməl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Best or most effective for a particular purpose.","vi":"tối ưu; tốt nhất; thuận lợi nhất"}],"examples":[{"en":"This sunny windowsill provides optimal conditions for my herbs.","vi":"Bệ cửa sổ đầy nắng này tạo ra điều kiện lý tưởng nhất cho các loại thảo mộc của tôi.","audioKind":"ex"},{"en":"Urban planners must balance housing density and green space to achieve optimal living conditions for residents.","vi":"Các nhà quy hoạch đô thị phải cân bằng giữa mật độ nhà ở và không gian xanh để đạt được điều kiện sống tốt nhất cho người dân.","audioKind":"ex2"}],"collocations":[{"en":"optimal conditions","vi":"điều kiện tối ưu"},{"en":"optimal performance","vi":"hiệu suất tối ưu"},{"en":"optimal solution","vi":"giải pháp tối ưu"}],"wordFamily":["optimally (adv.)","optimise (v.)","optimisation (n.)","optimum (adj.)"],"synonyms":["ideal","best"],"antonyms":["suboptimal"],"tipVi":"Bản thân từ này đã mang nghĩa \"tối ưu/tốt nhất\", do đó thông thường không đi kèm với từ most phía trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lunar', 'en-c1-55', 'lunar', '/ˈluːnər/', 'C1', 'thuộc mặt trăng; theo âm lịch; tính theo chu kỳ mặt trăng', 'adj.', NULL, NULL, 'lunar liên quan đến mặt trăng; solar liên quan đến mặt trời.', 'We watched the lunar eclipse from our garden.', NULL, 'Chúng tôi đã quan sát hiện tượng nguyệt thực từ khu vườn của mình.', '{"wordId":"lunar","ukIpa":"/ˈluːnə/","usIpa":"/ˈluːnər/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Relating to the moon.","vi":"thuộc mặt trăng"},{"pos":"adj.","en":"Based on the changing phases of the moon.","vi":"theo âm lịch; tính theo chu kỳ mặt trăng"}],"examples":[{"en":"We watched the lunar eclipse from our garden.","vi":"Chúng tôi đã quan sát hiện tượng nguyệt thực từ khu vườn của mình.","audioKind":"ex"},{"en":"Research on lunar rocks helps scientists understand how the moon and the early solar system developed.","vi":"Nghiên cứu các mẫu đá mặt trăng giúp các nhà khoa học hiểu được quá trình hình thành và phát triển của mặt trăng cũng như hệ mặt trời thời kỳ đầu.","audioKind":"ex2"}],"collocations":[{"en":"lunar eclipse","vi":"nguyệt thực"},{"en":"lunar surface","vi":"bề mặt mặt trăng"},{"en":"lunar calendar","vi":"âm lịch"},{"en":"lunar mission","vi":"sứ mệnh thám hiểm mặt trăng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"lunar liên quan đến mặt trăng; solar liên quan đến mặt trời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_combustion', 'en-c1-55', 'combustion', '/kəmˈbʌstʃən/', 'C1', 'sự cháy; sự đốt cháy', 'n.', 'combustible (adj.), combust (v.)', 'Đồng nghĩa: burning', 'Thường là danh từ không đếm được, là cách diễn đạt mang tính khoa học thay cho từ burning.', 'The stove needs enough air for efficient combustion.', NULL, 'Cái bếp cần đủ không khí để quá trình đốt cháy diễn ra hiệu quả.', '{"wordId":"combustion","ukIpa":"/kəmˈbʌstʃən/","usIpa":"/kəmˈbʌstʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The chemical process of burning, which releases heat.","vi":"sự cháy; sự đốt cháy"}],"examples":[{"en":"The stove needs enough air for efficient combustion.","vi":"Cái bếp cần đủ không khí để quá trình đốt cháy diễn ra hiệu quả.","audioKind":"ex"},{"en":"The combustion of fossil fuels releases carbon dioxide, contributing significantly to the rise in global temperatures.","vi":"Sự đốt cháy nhiên liệu hóa thạch giải phóng khí carbon dioxide, góp phần đáng kể làm tăng nhiệt độ toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"fuel combustion","vi":"đốt cháy nhiên liệu"},{"en":"complete combustion","vi":"sự cháy hoàn toàn"},{"en":"internal combustion engine","vi":"động cơ đốt trong"},{"en":"spontaneous combustion","vi":"tự bốc cháy"}],"wordFamily":["combustible (adj.)","combust (v.)"],"synonyms":["burning"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được, là cách diễn đạt mang tính khoa học thay cho từ burning.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thermal', 'en-c1-55', 'thermal', '/ˈθɝːməl/', 'C1', 'thuộc về nhiệt; nhiệt; giữ nhiệt; cách nhiệt; dòng khí nóng bốc lên', 'adj.', 'thermally (adv.)', NULL, 'thermal có thể chỉ các yếu tố liên quan đến nhiệt, hoặc chỉ quần áo có tính năng giữ ấm.', 'Our thermal camera shows where heat escapes the house.', NULL, 'Máy ảnh nhiệt của chúng tôi cho thấy nhiệt lượng thoát ra khỏi ngôi nhà ở những khu vực nào.', '{"wordId":"thermal","ukIpa":"/ˈθɜːməl/","usIpa":"/ˈθɝːməl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Relating to heat","vi":"thuộc về nhiệt; nhiệt"},{"pos":"adj.","en":"Designed to keep heat from escaping","vi":"giữ nhiệt; cách nhiệt"},{"pos":"n.","en":"A rising current of warm air","vi":"dòng khí nóng bốc lên"}],"examples":[{"en":"Our thermal camera shows where heat escapes the house.","vi":"Máy ảnh nhiệt của chúng tôi cho thấy nhiệt lượng thoát ra khỏi ngôi nhà ở những khu vực nào.","audioKind":"ex"},{"en":"Improving thermal insulation in older buildings can reduce energy consumption and make homes more comfortable during winter.","vi":"Việc cải thiện khả năng cách nhiệt ở các tòa nhà cũ có thể làm giảm tiêu thụ năng lượng và giúp nhà ở ấm cúng hơn vào mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"thermal energy","vi":"nhiệt năng"},{"en":"thermal insulation","vi":"sự cách nhiệt; sự giữ nhiệt"},{"en":"thermal imaging","vi":"ảnh nhiệt"},{"en":"thermal underwear","vi":"quần áo giữ nhiệt; đồ lót giữ nhiệt"}],"wordFamily":["thermally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"thermal có thể chỉ các yếu tố liên quan đến nhiệt, hoặc chỉ quần áo có tính năng giữ ấm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_homogeneous', 'en-c1-55', 'homogeneous', '/ˌhoʊməˈdʒiːniəs/', 'C1', 'đồng nhất; thuần nhất; đồng chất', 'adj.', 'homogeneity (n.), homogeneously (adv.)', 'Đồng nghĩa: uniform · Trái nghĩa: heterogeneous', 'Nhấn mạnh các thành phần cấu tạo giống nhau hoặc đồng đều, từ trái nghĩa là heterogeneous.', 'Stir the sauce until the mixture is completely homogeneous.', NULL, 'Khuấy đều nước sốt cho đến khi hỗn hợp hoàn toàn đồng nhất.', '{"wordId":"homogeneous","ukIpa":"/ˌhɒməˈdʒiːniəs/","usIpa":"/ˌhoʊməˈdʒiːniəs/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Consisting of parts or people that are all similar","vi":"đồng nhất; thuần nhất; đồng chất"}],"examples":[{"en":"Stir the sauce until the mixture is completely homogeneous.","vi":"Khuấy đều nước sốt cho đến khi hỗn hợp hoàn toàn đồng nhất.","audioKind":"ex"},{"en":"Treating urban populations as homogeneous can lead planners to overlook important differences in residents'' needs.","vi":"Việc coi dân số đô thị là một khối đồng nhất có thể khiến các nhà quy hoạch bỏLỡ những khác biệt quan trọng trong nhu cầu của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"homogeneous mixture","vi":"hỗn hợp đồng nhất"},{"en":"homogeneous group","vi":"nhóm đồng nhất; nhóm thuần nhất"},{"en":"relatively homogeneous","vi":"tương đối đồng nhất"}],"wordFamily":["homogeneity (n.)","homogeneously (adv.)"],"synonyms":["uniform"],"antonyms":["heterogeneous"],"tipVi":"Nhấn mạnh các thành phần cấu tạo giống nhau hoặc đồng đều, từ trái nghĩa là heterogeneous.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ammonia', 'en-c1-55', 'ammonia', '/əˈmoʊniə/', 'C1', 'am-mô-ni-ắc; khí amoniac; dung dịch amoniac', 'n.', NULL, NULL, 'Là danh từ không đếm được; có thể chỉ cả chất khí amoniac lẫn dung dịch amoniac.', 'This cleaning liquid contains ammonia, so keep the window open.', NULL, 'Dung dịch tẩy rửa này chứa amoniac, vì vậy hãy mở cửa sổ ra.', '{"wordId":"ammonia","ukIpa":"/əˈməʊniə/","usIpa":"/əˈmoʊniə/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A strong-smelling gas also dissolved in water for cleaning.","vi":"am-mô-ni-ắc; khí amoniac; dung dịch amoniac"}],"examples":[{"en":"This cleaning liquid contains ammonia, so keep the window open.","vi":"Dung dịch tẩy rửa này chứa amoniac, vì vậy hãy mở cửa sổ ra.","audioKind":"ex"},{"en":"Ammonia emissions from agriculture can contribute to air pollution and damage sensitive natural habitats.","vi":"Lượng khí thải amoniac từ ngành nông nghiệp có thể làm gia tăng ô nhiễm không khí và tàn phá các sinh cảnh tự nhiên mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"ammonia solution","vi":"dung dịch amoniac"},{"en":"ammonia emissions","vi":"lượng khí thải amoniac"},{"en":"ammonia production","vi":"quá trình sản xuất amoniac"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; có thể chỉ cả chất khí amoniac lẫn dung dịch amoniac.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pioneering', 'en-c1-55', 'pioneering', '/ˌpaɪəˈnɪrɪŋ/', 'C1', 'mang tính tiên phong; mang tính khai phá; có tính chất mở đường', 'adj.', 'pioneer (n.), pioneer (v.)', 'Đồng nghĩa: groundbreaking, innovative, trailblazing', 'Thường đóng vai trò là tính từ; để chỉ người tiên phong, hãy dùng danh từ pioneer.', 'Her pioneering design lets wheelchair users reach every shelf.', NULL, 'Thiết kế tiên phong của cô ấy giúp những người ngồi xe lăn có thể với tới mọi kệ tủ.', '{"wordId":"pioneering","ukIpa":"/ˌpaɪəˈnɪərɪŋ/","usIpa":"/ˌpaɪəˈnɪrɪŋ/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Introducing important new ideas or methods before others.","vi":"mang tính tiên phong; mang tính khai phá; có tính chất mở đường"}],"examples":[{"en":"Her pioneering design lets wheelchair users reach every shelf.","vi":"Thiết kế tiên phong của cô ấy giúp những người ngồi xe lăn có thể với tới mọi kệ tủ.","audioKind":"ex"},{"en":"Pioneering research into energy storage could make renewable electricity more reliable and reduce dependence on fossil fuels.","vi":"Nghiên cứu tiên phong về lưu trữ năng lượng có thể giúp điện tái tạo trở nên đáng tin cậy hơn và giảm bớt sự phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"pioneering research","vi":"nghiên cứu tiên phong"},{"en":"pioneering work","vi":"công trình khai phá"},{"en":"pioneering approach","vi":"phương pháp tiếp cận đổi mới"}],"wordFamily":["pioneer (n.)","pioneer (v.)"],"synonyms":["groundbreaking","innovative","trailblazing"],"antonyms":[],"tipVi":"Thường đóng vai trò là tính từ; để chỉ người tiên phong, hãy dùng danh từ pioneer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_neutralize', 'en-c1-55', 'neutralize', '/ˈnuːtrəlaɪz/', 'C1', 'làm mất tác dụng; vô hiệu hóa; trung hòa; làm trung hòa (axit hoặc kiềm)', 'v.', 'neutral (adj.), neutralization (n.), neutrality (n.)', 'Đồng nghĩa: counteract, cancel out', 'Cách viết Anh-Anh là neutralise; nhấn mạnh tác dụng triệt tiêu, không nhất thiết phải di dời vật thể.', 'This spray helps neutralize unpleasant smells in the kitchen.', NULL, 'Bình xịt này giúp khử mùi hôi khó chịu trong nhà bếp.', '{"wordId":"neutralize","ukIpa":"/ˈnjuːtrəlaɪz/","usIpa":"/ˈnuːtrəlaɪz/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"to stop something from having an effect","vi":"làm mất tác dụng; vô hiệu hóa; trung hòa"},{"pos":"v.","en":"to make an acid or alkali chemically neutral","vi":"làm trung hòa (axit hoặc kiềm)"}],"examples":[{"en":"This spray helps neutralize unpleasant smells in the kitchen.","vi":"Bình xịt này giúp khử mùi hôi khó chịu trong nhà bếp.","audioKind":"ex"},{"en":"Farmers sometimes add lime to acidic soil to neutralize excess acidity and improve conditions for crop growth.","vi":"Nông dân đôi khi bón vôi vào đất chua để trung hòa lượng axit dư thừa và cải thiện điều kiện sinh trưởng cho cây trồng.","audioKind":"ex2"}],"collocations":[{"en":"neutralize an acid","vi":"trung hòa axit"},{"en":"neutralize a threat","vi":"vô hiệu hóa mối đe dọa"},{"en":"neutralize the effects","vi":"triệt tiêu ảnh hưởng"},{"en":"neutralize odours","vi":"khử mùi"}],"wordFamily":["neutral (adj.)","neutralization (n.)","neutrality (n.)"],"synonyms":["counteract","cancel out"],"antonyms":[],"tipVi":"Cách viết Anh-Anh là neutralise; nhấn mạnh tác dụng triệt tiêu, không nhất thiết phải di dời vật thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oxide', 'en-c1-55', 'oxide', '/ˈɑːksaɪd/', 'C1', 'hợp chất oxit', 'n.', 'oxidise (v.), oxidation (n.)', NULL, 'Oxide là thuật ngữ chung chỉ oxit, trong khi dioxide chỉ đioxit.', 'This sunscreen contains zinc oxide to protect your skin.', NULL, 'Kem chống nắng này chứa kẽm oxit để bảo vệ làn da của bạn.', '{"wordId":"oxide","ukIpa":"/ˈɒksaɪd/","usIpa":"/ˈɑːksaɪd/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A compound consisting of oxygen and another chemical element.","vi":"hợp chất oxit"}],"examples":[{"en":"This sunscreen contains zinc oxide to protect your skin.","vi":"Kem chống nắng này chứa kẽm oxit để bảo vệ làn da của bạn.","audioKind":"ex"},{"en":"Nitrogen oxides released by vehicle engines contribute to air pollution and can damage human health.","vi":"Các loại oxit nitơ thải ra từ động cơ xe hơi góp phần gây ô nhiễm không khí và có thể tổn hại đến sức khỏe con người.","audioKind":"ex2"}],"collocations":[{"en":"zinc oxide","vi":"kẽm oxit"},{"en":"iron oxide","vi":"sắt oxit"},{"en":"nitrogen oxides","vi":"các oxit nitơ"}],"wordFamily":["oxidise (v.)","oxidation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Oxide là thuật ngữ chung chỉ oxit, trong khi dioxide chỉ đioxit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_robust', 'en-c1-55', 'robust', '/roʊˈbʌst/', 'C1', 'tráng kiện; vững chắc; khỏe mạnh; vững vàng; mạnh mẽ; đáng tin cậy', 'adj.', 'robustness (n.), robustly (adv.)', 'Đồng nghĩa: strong, sturdy · Trái nghĩa: weak, fragile', 'Dùng để miêu tả cả thể chất/đồ vật bền chắc lẫn bằng chứng, hệ thống có độ tin cậy cao.', 'These robust boots survived years of muddy country walks.', NULL, 'Đôi bốt chắc chắn này đã bền bỉ qua nhiều năm đi dạo trên những con đường làng lầy lội.', '{"wordId":"robust","ukIpa":"/rəʊˈbʌst/","usIpa":"/roʊˈbʌst/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"strong, healthy, and unlikely to break or become weak","vi":"tráng kiện; vững chắc; khỏe mạnh"},{"pos":"adj.","en":"effective and reliable even under difficult conditions","vi":"vững vàng; mạnh mẽ; đáng tin cậy"}],"examples":[{"en":"These robust boots survived years of muddy country walks.","vi":"Đôi bốt chắc chắn này đã bền bỉ qua nhiều năm đi dạo trên những con đường làng lầy lội.","audioKind":"ex"},{"en":"Governments need robust evidence before introducing policies that could significantly affect public health and household spending.","vi":"Các chính phủ cần có những bằng chứng xác thực trước khi ban hành các chính sách có khả năng tác động lớn đến sức khỏe cộng đồng và chi tiêu hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"robust health","vi":"thể trạng cường tráng"},{"en":"robust evidence","vi":"bằng chứng xác thực"},{"en":"robust system","vi":"hệ thống vững chắc"},{"en":"robust economy","vi":"nền kinh tế vững mạnh"}],"wordFamily":["robustness (n.)","robustly (adv.)"],"synonyms":["strong","sturdy"],"antonyms":["weak","fragile"],"tipVi":"Dùng để miêu tả cả thể chất/đồ vật bền chắc lẫn bằng chứng, hệ thống có độ tin cậy cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solidify', 'en-c1-55', 'solidify', '/səˈlɪdəfaɪ/', 'C1', 'đông đặc; làm đông lại; củng cố; tăng cường', 'v.', 'solid (adj.), solidification (n.)', 'Đồng nghĩa: harden, strengthen · Trái nghĩa: liquefy, weaken', 'Có thể dùng để chỉ chất lỏng đông đặc, hoặc mối quan hệ và địa vị được củng cố.', 'Leave the melted chocolate to solidify before adding decorations.', NULL, 'Hãy để sô-cô-la tan chảy đông đặc lại trước khi trang trí.', '{"wordId":"solidify","ukIpa":"/səˈlɪdɪfaɪ/","usIpa":"/səˈlɪdəfaɪ/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To become solid, or make something become solid.","vi":"đông đặc; làm đông lại"},{"pos":"v.","en":"To make an agreement, relationship, or position stronger and more secure.","vi":"củng cố; tăng cường"}],"examples":[{"en":"Leave the melted chocolate to solidify before adding decorations.","vi":"Hãy để sô-cô-la tan chảy đông đặc lại trước khi trang trí.","audioKind":"ex"},{"en":"Joint research projects can solidify partnerships between universities and encourage the exchange of specialist knowledge.","vi":"Các dự án nghiên cứu chung có thể củng cố mối quan hệ đối tác giữa các trường đại học và thúc đẩy việc trao đổi kiến thức chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"solidify into a mass","vi":"đông đặc thành khối"},{"en":"solidify an alliance","vi":"củng cố liên minh"},{"en":"solidify support","vi":"củng cố sự ủng hộ"}],"wordFamily":["solid (adj.)","solidification (n.)"],"synonyms":["harden","strengthen"],"antonyms":["liquefy","weaken"],"tipVi":"Có thể dùng để chỉ chất lỏng đông đặc, hoặc mối quan hệ và địa vị được củng cố.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ultraviolet', 'en-c1-55', 'ultraviolet', '/ˌʌltrəˈvaɪələt/', 'C1', 'thuộc tia tử ngoại; cực tím; tia tử ngoại; tia cực tím', 'adj.', NULL, NULL, 'Thường viết tắt là UV; bản thân tia tử ngoại mắt thường không nhìn thấy được.', 'These sunglasses protect your eyes from harmful ultraviolet rays.', NULL, 'Những chiếc kính râm này bảo vệ mắt bạn khỏi tia tử ngoại có hại.', '{"wordId":"ultraviolet","ukIpa":"/ˌʌltrəˈvaɪələt/","usIpa":"/ˌʌltrəˈvaɪələt/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Describing invisible radiation with wavelengths shorter than visible violet light.","vi":"thuộc tia tử ngoại; cực tím"},{"pos":"n.","en":"Invisible radiation beyond violet in the light spectrum.","vi":"tia tử ngoại; tia cực tím"}],"examples":[{"en":"These sunglasses protect your eyes from harmful ultraviolet rays.","vi":"Những chiếc kính râm này bảo vệ mắt bạn khỏi tia tử ngoại có hại.","audioKind":"ex"},{"en":"Excessive exposure to ultraviolet radiation increases the risk of skin damage, making sun protection essential.","vi":"Việc tiếp xúc quá mức với bức xạ cực tím làm tăng nguy cơ tổn thương da, khiến việc chống nắng trở nên cực kỳ quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"ultraviolet radiation","vi":"bức xạ cực tím"},{"en":"ultraviolet rays","vi":"tia tử ngoại"},{"en":"ultraviolet light","vi":"ánh sáng cực tím"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường viết tắt là UV; bản thân tia tử ngoại mắt thường không nhìn thấy được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parasite', 'en-c1-55', 'parasite', '/ˈpærəsaɪt/', 'C1', 'ký sinh trùng; sinh vật ký sinh; kẻ sống bám; kẻ ăn bám xã hội', 'n.', 'parasitic (adj.), parasitism (n.)', NULL, 'Khi chỉ người, từ này mang sắc thái chê bai mạnh mẽ; sinh vật mang ký sinh gọi là host.', 'The vet found a parasite in our dog''s fur.', NULL, 'Bác sĩ thú y đã tìm thấy một con ký sinh trùng trong bộ lông của chú chó nhà chúng ta.', '{"wordId":"parasite","ukIpa":"/ˈpærəsaɪt/","usIpa":"/ˈpærəsaɪt/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"an organism living on or inside another and taking nutrients","vi":"ký sinh trùng; sinh vật ký sinh"},{"pos":"n.","en":"someone who takes from others without contributing anything","vi":"kẻ sống bám; kẻ ăn bám xã hội"}],"examples":[{"en":"The vet found a parasite in our dog''s fur.","vi":"Bác sĩ thú y đã tìm thấy một con ký sinh trùng trong bộ lông của chú chó nhà chúng ta.","audioKind":"ex"},{"en":"Warmer temperatures may allow certain parasites to spread into regions where they previously could not survive.","vi":"Nhiệt độ ấm lên có thể tạo điều kiện cho một số loài ký sinh lây lan sang các vùng mà trước đây chúng không thể sinh sống.","audioKind":"ex2"}],"collocations":[{"en":"intestinal parasite","vi":"ký sinh trùng đường ruột"},{"en":"host organism","vi":"sinh vật chủ"},{"en":"parasitic infection","vi":"nhiễm ký sinh trùng"}],"wordFamily":["parasitic (adj.)","parasitism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ người, từ này mang sắc thái chê bai mạnh mẽ; sinh vật mang ký sinh gọi là host.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meteorologist', 'en-c1-55', 'meteorologist', '/ˌmiːtiəˈrɑːlədʒɪst/', 'C1', 'nhà khí tượng học; chuyên gia khí tượng', 'n.', 'meteorology (n.), meteorological (adj.)', NULL, 'Chuyên nghiên cứu về thời tiết và tầng khí quyển, không phải nhà thiên văn học nghiên cứu về sao băng.', 'The meteorologist warned us that heavy snow was approaching.', NULL, 'Nhà khí tượng học đã cảnh báo chúng tôi rằng một đợt tuyết lớn đang tiến đến.', '{"wordId":"meteorologist","ukIpa":"/ˌmiːtiəˈrɒlədʒɪst/","usIpa":"/ˌmiːtiəˈrɑːlədʒɪst/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A scientist who studies weather and atmospheric conditions.","vi":"nhà khí tượng học; chuyên gia khí tượng"}],"examples":[{"en":"The meteorologist warned us that heavy snow was approaching.","vi":"Nhà khí tượng học đã cảnh báo chúng tôi rằng một đợt tuyết lớn đang tiến đến.","audioKind":"ex"},{"en":"Meteorologists analyse atmospheric data to forecast extreme weather and help communities prepare for potentially dangerous conditions.","vi":"Các chuyên gia khí tượng phân tích dữ liệu khí quyển để dự báo thời tiết cực đoan và giúp cộng đồng chuẩn bị ứng phó với những điều kiện thời tiết có nguy cơ gây nguy hiểm.","audioKind":"ex2"}],"collocations":[{"en":"a trained meteorologist","vi":"nhà khí tượng học được đào tạo bài bản"},{"en":"a team of meteorologists","vi":"đội ngũ chuyên gia khí tượng"},{"en":"meteorologists predict","vi":"các nhà khí tượng học dự báo"}],"wordFamily":["meteorology (n.)","meteorological (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chuyên nghiên cứu về thời tiết và tầng khí quyển, không phải nhà thiên văn học nghiên cứu về sao băng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_filament', 'en-c1-55', 'filament', '/ˈfɪləmənt/', 'C1', 'sợi mảnh; cấu trúc dạng sợi; đây là sợi dây tóc (trong bóng đèn)', 'n.', 'filamentous (adj.)', 'Đồng nghĩa: thread, strand', 'Vừa chỉ sợi mảnh nói chung, vừa chỉ dây tóc phát sáng bằng điện trong bóng đèn.', 'A delicate filament stretched between the spider and the branch.', NULL, 'Một sợi tơ mong manh giăng giữa con nhện và cành cây.', '{"wordId":"filament","ukIpa":"/ˈfɪləmənt/","usIpa":"/ˈfɪləmənt/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A very thin thread or thread-like structure.","vi":"sợi mảnh; cấu trúc dạng sợi"},{"pos":"n.","en":"A thin wire that produces light when heated by electricity.","vi":"đây là sợi dây tóc (trong bóng đèn)"}],"examples":[{"en":"A delicate filament stretched between the spider and the branch.","vi":"Một sợi tơ mong manh giăng giữa con nhện và cành cây.","audioKind":"ex"},{"en":"Researchers are developing stronger filaments for use in lightweight materials that could reduce fuel consumption in transport.","vi":"Các nhà nghiên cứu đang phát triển các sợi siêu mảnh có độ bền cao hơn dùng cho vật liệu nhẹ, giúp giảm lượng tiêu thụ nhiên liệu trong giao thông vận tải.","audioKind":"ex2"}],"collocations":[{"en":"fine filament","vi":"sợi tơ mảnh"},{"en":"tungsten filament","vi":"dây tóc bóng đèn vonfram"},{"en":"filament bulb","vi":"bóng đèn dây tóc"}],"wordFamily":["filamentous (adj.)"],"synonyms":["thread","strand"],"antonyms":[],"tipVi":"Vừa chỉ sợi mảnh nói chung, vừa chỉ dây tóc phát sáng bằng điện trong bóng đèn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_methodology', 'en-c1-55', 'methodology', '/ˌmeθəˈdɑːlədʒi/', 'C1', 'phương pháp nghiên cứu; hệ thống phương pháp', 'n.', 'method (n.), methodological (adj.), methodologically (adv.)', NULL, 'method chỉ phương pháp cụ thể; còn methodology nhấn mạnh toàn bộ hệ thống phương pháp và nguyên lý.', 'Our tutor explained the methodology before we began our project.', NULL, 'Giáo hướng dẫn của chúng tôi đã giải thích hệ thống phương pháp trước khi chúng tôi bắt đầu dự án.', '{"wordId":"methodology","ukIpa":"/ˌmeθəˈdɒlədʒi/","usIpa":"/ˌmeθəˈdɑːlədʒi/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"a system of methods and principles used in research","vi":"phương pháp nghiên cứu; hệ thống phương pháp"}],"examples":[{"en":"Our tutor explained the methodology before we began our project.","vi":"Giáo hướng dẫn của chúng tôi đã giải thích hệ thống phương pháp trước khi chúng tôi bắt đầu dự án.","audioKind":"ex"},{"en":"Researchers must describe their methodology clearly so that others can evaluate the reliability of their findings.","vi":"Các nhà nghiên cứu phải trình bày rõ ràng phương pháp nghiên cứu của mình để những người khác có thể đánh giá độ tin cậy của kết quả.","audioKind":"ex2"}],"collocations":[{"en":"research methodology","vi":"phương pháp nghiên cứu khoa học"},{"en":"develop a methodology","vi":"xây dựng phương pháp nghiên cứu"},{"en":"rigorous methodology","vi":"hệ thống phương pháp chặt chẽ"}],"wordFamily":["method (n.)","methodological (adj.)","methodologically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"method chỉ phương pháp cụ thể; còn methodology nhấn mạnh toàn bộ hệ thống phương pháp và nguyên lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pore', 'en-c1-55', 'pore', '/pɔːr/', 'C1', 'lỗ chân lông; lỗ nhỏ (trên bề mặt); suy ngẫm; nghiên cứu kỹ lưỡng', 'n.', 'porous (adj.), porosity (n.)', NULL, 'Động từ thường dùng pore over, đừng nhầm lẫn với pour over.', 'Tiny drops of sweat appeared around his skin pores.', NULL, 'Những giọt mồ hôi li ti xuất hiện quanh các lỗ chân lông trên da anh ấy.', '{"wordId":"pore","ukIpa":"/pɔː/","usIpa":"/pɔːr/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"a tiny opening in skin or another surface","vi":"lỗ chân lông; lỗ nhỏ (trên bề mặt)"},{"pos":"v.","en":"to read or examine something with great attention","vi":"suy ngẫm; nghiên cứu kỹ lưỡng"}],"examples":[{"en":"Tiny drops of sweat appeared around his skin pores.","vi":"Những giọt mồ hôi li ti xuất hiện quanh các lỗ chân lông trên da anh ấy.","audioKind":"ex"},{"en":"Researchers pore over historical records to understand how earlier societies responded to periods of severe drought.","vi":"Các nhà nghiên cứu nghiên cứu kỹ lưỡng các tài liệu lịch sử để hiểu cách các xã hội trước đây đối phó với những thời kỳ hạn hán khốc liệt.","audioKind":"ex2"}],"collocations":[{"en":"clogged pores","vi":"lỗ chân lông bị tắc"},{"en":"open pores","vi":"lỗ chân lông mở"},{"en":"pore over documents","vi":"nghiên cứu kỹ tài liệu"}],"wordFamily":["porous (adj.)","porosity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường dùng pore over, đừng nhầm lẫn với pour over.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_55_1', 'en-c1-55', 'Cách dùng “deviation” (n.) — sự sai lệch; sự đi chệch', 'deviation from the norm  ·  standard deviation  ·  significant deviation', 'Thường kết hợp với giới từ from thành deviation from; cụm standard deviation có nghĩa là "độ lệch chuẩn".', 'Họ từ (Word Family): deviate (v.) | Đồng nghĩa: departure, divergence', '[{"hanzi":"A small deviation from our route revealed a quiet beach.","pinyin":"","meaning":"Một sự lệch hướng nhỏ khỏi lộ trình ban đầu đã đưa chúng tôi đến một bãi biển yên tĩnh."},{"hanzi":"Any significant deviation from established safety procedures should be investigated to prevent accidents in the workplace.","pinyin":"","meaning":"Mọi sự sai lệch đáng kể so với các quy trình an toàn đã được thiết lập cần phải được điều tra để ngăn ngừa tai nạn tại nơi làm việc."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_55_2', 'en-c1-55', 'Cách dùng “optimal” (adj.) — tối ưu; tốt nhất; thuận lợi nhất', 'optimal conditions  ·  optimal performance  ·  optimal solution', 'Bản thân từ này đã mang nghĩa "tối ưu/tốt nhất", do đó thông thường không đi kèm với từ most phía trước.', 'Họ từ (Word Family): optimally (adv.), optimise (v.), optimisation (n.), optimum (adj.) | Đồng nghĩa: ideal, best · Trái nghĩa: suboptimal', '[{"hanzi":"This sunny windowsill provides optimal conditions for my herbs.","pinyin":"","meaning":"Bệ cửa sổ đầy nắng này tạo ra điều kiện lý tưởng nhất cho các loại thảo mộc của tôi."},{"hanzi":"Urban planners must balance housing density and green space to achieve optimal living conditions for residents.","pinyin":"","meaning":"Các nhà quy hoạch đô thị phải cân bằng giữa mật độ nhà ở và không gian xanh để đạt được điều kiện sống tốt nhất cho người dân."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_55_3', 'en-c1-55', 'Cách dùng “meteorologist” (n.) — nhà khí tượng học; chuyên gia khí tượng', 'a trained meteorologist  ·  a team of meteorologists  ·  meteorologists predict', 'Chuyên nghiên cứu về thời tiết và tầng khí quyển, không phải nhà thiên văn học nghiên cứu về sao băng.', 'Họ từ (Word Family): meteorology (n.), meteorological (adj.)', '[{"hanzi":"The meteorologist warned us that heavy snow was approaching.","pinyin":"","meaning":"Nhà khí tượng học đã cảnh báo chúng tôi rằng một đợt tuyết lớn đang tiến đến."},{"hanzi":"Meteorologists analyse atmospheric data to forecast extreme weather and help communities prepare for potentially dangerous conditions.","pinyin":"","meaning":"Các chuyên gia khí tượng phân tích dữ liệu khí quyển để dự báo thời tiết cực đoan và giúp cộng đồng chuẩn bị ứng phó với những điều kiện thời tiết có nguy cơ gây nguy hiểm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_55_4', 'en-c1-55', 'Cách dùng “neutralize” (v.) — làm mất tác dụng; vô hiệu hóa; trung hòa', 'neutralize an acid  ·  neutralize a threat  ·  neutralize the effects', 'Cách viết Anh-Anh là neutralise; nhấn mạnh tác dụng triệt tiêu, không nhất thiết phải di dời vật thể.', 'Họ từ (Word Family): neutral (adj.), neutralization (n.), neutrality (n.) | Đồng nghĩa: counteract, cancel out', '[{"hanzi":"This spray helps neutralize unpleasant smells in the kitchen.","pinyin":"","meaning":"Bình xịt này giúp khử mùi hôi khó chịu trong nhà bếp."},{"hanzi":"Farmers sometimes add lime to acidic soil to neutralize excess acidity and improve conditions for crop growth.","pinyin":"","meaning":"Nông dân đôi khi bón vôi vào đất chua để trung hòa lượng axit dư thừa và cải thiện điều kiện sinh trưởng cho cây trồng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_55_1', 'en-c1-55', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
