INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_1_4', 'ten_c1_55_1', 'deviation', 'A small deviation from our route revealed a quiet beach.', 'A small deviation from our route revealed a quiet beach.', '/ˌdiːviˈeɪʃən/', 'Một sự lệch hướng nhỏ khỏi lộ trình ban đầu đã đưa chúng tôi đến một bãi biển yên tĩnh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_1_5', 'ten_c1_55_1', 'optics', 'We explored optics by shining a torch through a prism.', 'We explored optics by shining a torch through a prism.', '/ˈɑːptɪks/', 'Chúng tôi đã khám phá quang học bằng cách chiếu đèn pin qua một lăng kính.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_1_6', 'ten_c1_55_1', 'temporal', 'We arranged the family photos in temporal order.', 'We arranged the family photos in temporal order.', '/ˈtempərəl/', 'Chúng tôi đã sắp xếp các bức ảnh gia đình theo thứ tự thời gian.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_1_7', 'ten_c1_55_1', 'purity', 'The jeweller checked the purity of my gold ring.', 'The jeweller checked the purity of my gold ring.', '/ˈpjʊrəti/', 'Thợ kim hoàn đã kiểm tra độ tinh khiết của chiếc nhẫn vàng của tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_1_8', 'ten_c1_55_1', 'polymer', 'This flexible polymer keeps my phone case light and durable.', 'This flexible polymer keeps my phone case light and durable.', '/ˈpɑːlɪmər/', 'Chất polymer dẻo dai này giúp cho ốp điện thoại của tôi vừa nhẹ vừa bền.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_55_1_1', 'en-c1-55', 'ten_c1_55_1', 'listening', 'listening', 'We watched an animation showing fission at the science museum.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã xem một đoạn phim hoạt hình mô tả hiện tượng phân hạch tại bảo tàng khoa học.","Bình xịt này giúp khử mùi hôi khó chịu trong nhà bếp.","Giáo hướng dẫn của chúng tôi đã giải thích hệ thống phương pháp trước khi chúng tôi bắt đầu dự án.","Đôi bốt chắc chắn này đã bền bỉ qua nhiều năm đi dạo trên những con đường làng lầy lội."]'::jsonb, 0, 'We watched an animation showing fission at the science museum. → Chúng tôi đã xem một đoạn phim hoạt hình mô tả hiện tượng phân hạch tại bảo tàng khoa học.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_55_1_2', 'en-c1-55', 'ten_c1_55_1', 'listening', 'listening', 'She found a piece of quartz beside the stream.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giáo hướng dẫn của chúng tôi đã giải thích hệ thống phương pháp trước khi chúng tôi bắt đầu dự án.","Cô ấy tìm thấy một mảnh thạch anh bên bờ suối.","Những giọt mồ hôi li ti xuất hiện quanh các lỗ chân lông trên da anh ấy.","Hãy để sô-cô-la tan chảy đông đặc lại trước khi trang trí."]'::jsonb, 1, 'She found a piece of quartz beside the stream. → Cô ấy tìm thấy một mảnh thạch anh bên bờ suối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_55_1_3', 'en-c1-55', 'ten_c1_55_1', 'listening', 'listening', 'The old boiler needs periodic checks to keep working safely.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thợ kim hoàn đã kiểm tra độ tinh khiết của chiếc nhẫn vàng của tôi.","Những giọt mồ hôi li ti xuất hiện quanh các lỗ chân lông trên da anh ấy.","Một sự lệch hướng nhỏ khỏi lộ trình ban đầu đã đưa chúng tôi đến một bãi biển yên tĩnh.","Lò hơi cũ cần được kiểm tra định kỳ để vận hành an toàn."]'::jsonb, 3, 'The old boiler needs periodic checks to keep working safely. → Lò hơi cũ cần được kiểm tra định kỳ để vận hành an toàn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_55_2', 'en-c1-55', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_2_1', 'ten_c1_55_2', 'fission', 'Nuclear fission generates electricity without direct carbon emissions, but managing radioactive waste remains a major challenge.', 'Nuclear fission generates electricity without direct carbon emissions, but managing radioactive waste remains a major challenge.', '/ˈfɪʃən/', 'Phản ứng phân hạch hạt nhân tạo ra điện năng mà không thải ra trực tiếp khí carbon, nhưng việc quản lý chất thải phóng xạ vẫn là một thử thách lớn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_2_2', 'ten_c1_55_2', 'quartz', 'Quartz crystals are used in electronic devices because their regular vibrations enable highly accurate time measurement.', 'Quartz crystals are used in electronic devices because their regular vibrations enable highly accurate time measurement.', '/kwɔːrts/', 'Tinh thể thạch anh được sử dụng trong các thiết bị điện tử vì độ dao động ổn định của chúng cho phép đo thời gian cực kỳ chính xác.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_2_3', 'ten_c1_55_2', 'periodic', 'Periodic assessments allow teachers to identify learning difficulties before students fall significantly behind their classmates.', 'Periodic assessments allow teachers to identify learning difficulties before students fall significantly behind their classmates.', '/ˌpɪriˈɑːdɪk/', 'Các bài đánh giá định kỳ giúp giáo viên phát hiện khó khăn học tập của học sinh trước khi các em bị tụt lại quá xa so với bạn cùng lớp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_2_4', 'ten_c1_55_2', 'deviation', 'Any significant deviation from established safety procedures should be investigated to prevent accidents in the workplace.', 'Any significant deviation from established safety procedures should be investigated to prevent accidents in the workplace.', '/ˌdiːviˈeɪʃən/', 'Mọi sự sai lệch đáng kể so với các quy trình an toàn đã được thiết lập cần phải được điều tra để ngăn ngừa tai nạn tại nơi làm việc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_2_5', 'ten_c1_55_2', 'optics', 'Advances in optics have improved medical imaging, allowing doctors to examine internal structures in greater detail.', 'Advances in optics have improved medical imaging, allowing doctors to examine internal structures in greater detail.', '/ˈɑːptɪks/', 'Sự tiến bộ của quang học đã cải thiện hình ảnh y tế, cho phép các bác sĩ kiểm tra các cấu trúc bên trong chi tiết hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_55_2_6', 'ten_c1_55_2', 'temporal', 'Understanding temporal patterns in electricity demand can help cities manage their energy supplies more efficiently.', 'Understanding temporal patterns in electricity demand can help cities manage their energy supplies more efficiently.', '/ˈtempərəl/', 'Việc thấu hiểu các quy luật thay đổi theo thời gian trong nhu cầu điện năng có thể giúp các quản lý nguồn năng lượng của thành phố hiệu quả hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_55_2_1', 'en-c1-55', 'ten_c1_55_2', 'listening', 'listening', 'Nuclear fission generates electricity without direct carbon emissions, but managing radioactive waste remains a major challenge.', NULL, 'Trong câu vừa nghe, từ “fission” mang nghĩa nào sau đây?', '["sự giả định; sự phỏng đoán; điều giả định","do cái gì đó gây ra; hậu quả là","sự phân hạch; sự tách hạt nhân nguyên tử","chiều chuộng; cưng nựng; nuông chiều"]'::jsonb, 2, '“fission” (/ˈfɪʃən/): sự phân hạch; sự tách hạt nhân nguyên tử. Câu đầy đủ: Nuclear fission generates electricity without direct carbon emissions, but managing radioactive waste remains a major challenge.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_55_2_2', 'en-c1-55', 'ten_c1_55_2', 'listening', 'listening', 'Quartz crystals are used in electronic devices because their regular vibrations enable highly accurate time measurement.', NULL, 'Trong câu vừa nghe, từ “quartz” mang nghĩa nào sau đây?', '["thạch anh","tác giả viết tản văn; nhà văn chuyên viết tiểu luận","sự tổng hợp; sự kết hợp","âm ấm; hơi ấm"]'::jsonb, 0, '“quartz” (/kwɔːrts/): thạch anh. Câu đầy đủ: Quartz crystals are used in electronic devices because their regular vibrations enable highly accurate time measurement.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
