INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_2', 'en-c1-55', NULL, 'comprehensive_test', 'listening', 'She found a piece of quartz beside the stream.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cái bếp cần đủ không khí để quá trình đốt cháy diễn ra hiệu quả.","Chúng tôi đã xem một đoạn phim hoạt hình mô tả hiện tượng phân hạch tại bảo tàng khoa học.","Nhà khí tượng học đã cảnh báo chúng tôi rằng một đợt tuyết lớn đang tiến đến.","Cô ấy tìm thấy một mảnh thạch anh bên bờ suối."]'::jsonb, 3, 'She found a piece of quartz beside the stream. → Cô ấy tìm thấy một mảnh thạch anh bên bờ suối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_3', 'en-c1-55', NULL, 'comprehensive_test', 'listening', 'periodic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cây đước; cây mắm; rừng ngập mặn","dựa trên thực nghiệm; thực tế; theo kinh nghiệm","bảo đảm; bảo lãnh; xác nhận","mang tính chu kỳ; định kỳ; có thời hạn"]'::jsonb, 3, 'periodic (/ˌpɪriˈɑːdɪk/) → mang tính chu kỳ; định kỳ; có thời hạn', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_4', 'en-c1-55', NULL, 'comprehensive_test', 'listening', 'A small deviation from our route revealed a quiet beach.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Khuấy đều nước sốt cho đến khi hỗn hợp hoàn toàn đồng nhất.","Bác sĩ thú y đã tìm thấy một con ký sinh trùng trong bộ lông của chú chó nhà chúng ta.","Một sự lệch hướng nhỏ khỏi lộ trình ban đầu đã đưa chúng tôi đến một bãi biển yên tĩnh.","Chúng tôi đã khám phá quang học bằng cách chiếu đèn pin qua một lăng kính."]'::jsonb, 2, 'A small deviation from our route revealed a quiet beach. → Một sự lệch hướng nhỏ khỏi lộ trình ban đầu đã đưa chúng tôi đến một bãi biển yên tĩnh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_5', 'en-c1-55', NULL, 'comprehensive_test', 'listening', 'optics', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trong chừng mực mà; theo như","chiến tranh, chiến đấu, phương thức tác chiến","có dạng hạt; sần","quang học"]'::jsonb, 3, 'optics (/ˈɑːptɪks/) → quang học', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_6', 'en-c1-55', NULL, 'comprehensive_test', 'listening', 'We arranged the family photos in temporal order.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Máy ảnh nhiệt của chúng tôi cho thấy nhiệt lượng thoát ra khỏi ngôi nhà ở những khu vực nào.","Một sợi tơ mong manh giăng giữa con nhện và cành cây.","Chúng tôi đã quan sát hiện tượng nguyệt thực từ khu vườn của mình.","Chúng tôi đã sắp xếp các bức ảnh gia đình theo thứ tự thời gian."]'::jsonb, 3, 'We arranged the family photos in temporal order. → Chúng tôi đã sắp xếp các bức ảnh gia đình theo thứ tự thời gian.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_7', 'en-c1-55', NULL, 'comprehensive_test', 'listening', 'purity', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["niên đại; thứ tự thời gian; bảng niên biểu","mệt mỏi; kiệt sức","giáo dục nam nữ chung trường; nền giáo dục hỗn hợp nam nữ (việc giáo dục nam và nữ cùng nhau trong một cơ sở giáo dục)","độ tinh khiết; sự tinh sạch"]'::jsonb, 3, 'purity (/ˈpjʊrəti/) → độ tinh khiết; sự tinh sạch; sự trong sáng; tính thuần khiết', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_8', 'en-c1-55', NULL, 'comprehensive_test', 'listening', 'This flexible polymer keeps my phone case light and durable.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã xem một đoạn phim hoạt hình mô tả hiện tượng phân hạch tại bảo tàng khoa học.","Thợ kim hoàn đã kiểm tra độ tinh khiết của chiếc nhẫn vàng của tôi.","Những chiếc kính râm này bảo vệ mắt bạn khỏi tia tử ngoại có hại.","Chất polymer dẻo dai này giúp cho ốp điện thoại của tôi vừa nhẹ vừa bền."]'::jsonb, 3, 'This flexible polymer keeps my phone case light and durable. → Chất polymer dẻo dai này giúp cho ốp điện thoại của tôi vừa nhẹ vừa bền.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_9', 'en-c1-55', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The scientific study of light and how it behaves”?', '["polymer","optics","pioneering","homogeneous"]'::jsonb, 1, 'optics (/ˈɑːptɪks/) → quang học', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
