INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_18', 'en-c1-55', NULL, 'comprehensive_test', 'reading', NULL, 'Nuclear fission generates electricity without direct carbon emissions, but managing radioactive waste remains a major challenge.', 'Dựa vào câu trên, từ “fission” có nghĩa phù hợp nhất là gì?', '["sự phân hạch; sự tách hạt nhân nguyên tử","giải mã; nhận diện; đọc hiểu","ý kiến đề xuất; ý kiến bàn","có khả năng tính toán; giỏi tính toán"]'::jsonb, 0, 'fission: sự phân hạch; sự tách hạt nhân nguyên tử; sự phân rẽ; sự sinh sản bằng cách phân chia. Dịch cả câu: Phản ứng phân hạch hạt nhân tạo ra điện năng mà không thải ra trực tiếp khí carbon, nhưng việc quản lý chất thải phóng xạ vẫn là một thử thách lớn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_19', 'en-c1-55', NULL, 'comprehensive_test', 'reading', NULL, 'Quartz crystals are used in electronic devices because their regular vibrations enable highly accurate time measurement.', 'Dựa vào câu trên, từ “quartz” có nghĩa phù hợp nhất là gì?', '["thạch anh","hóm hỉnh; sắc sảo","sự bực bội; sự cáu giận; sự ngán ngẩm","thích đáng; liên quan; sát với vấn đề"]'::jsonb, 0, 'quartz: thạch anh. Dịch cả câu: Tinh thể thạch anh được sử dụng trong các thiết bị điện tử vì độ dao động ổn định của chúng cho phép đo thời gian cực kỳ chính xác.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_20', 'en-c1-55', NULL, 'comprehensive_test', 'reading', NULL, 'Periodic assessments allow teachers to identify learning difficulties before students fall significantly behind their classmates.', 'Dựa vào câu trên, từ “periodic” có nghĩa phù hợp nhất là gì?', '["chiếu sáng; rọi sáng","mang tính chu kỳ; định kỳ; có thời hạn","tuân theo một quy tắc, thỏa thuận hoặc quyết định","có thể nhận thức được; có thể cảm nhận rõ; có thể thấy rõ"]'::jsonb, 1, 'periodic: mang tính chu kỳ; định kỳ; có thời hạn. Dịch cả câu: Các bài đánh giá định kỳ giúp giáo viên phát hiện khó khăn học tập của học sinh trước khi các em bị tụt lại quá xa so với bạn cùng lớp.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_21', 'en-c1-55', NULL, 'comprehensive_test', 'reading', NULL, 'Any significant deviation from established safety procedures should be investigated to prevent accidents in the workplace.', 'Dựa vào câu trên, từ “deviation” có nghĩa phù hợp nhất là gì?', '["hổ cái; con cọp cái","giữa; trong số","sự sai lệch; sự đi chệch","nuôi dưỡng; cung cấp chất dinh dưỡng"]'::jsonb, 2, 'deviation: sự sai lệch; sự đi chệch; độ lệch; độ sai số. Dịch cả câu: Mọi sự sai lệch đáng kể so với các quy trình an toàn đã được thiết lập cần phải được điều tra để ngăn ngừa tai nạn tại nơi làm việc.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_22', 'en-c1-55', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sợi mảnh; cấu trúc dạng sợi”', '["filament","surpass","indicative","magnify"]'::jsonb, 0, 'sợi mảnh; cấu trúc dạng sợi → filament (/ˈfɪləmənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_23', 'en-c1-55', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phương pháp nghiên cứu; hệ thống phương pháp”', '["methodology","nomination","rave","ragged"]'::jsonb, 0, 'phương pháp nghiên cứu; hệ thống phương pháp → methodology (/ˌmeθəˈdɑːlədʒi/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_55_24', 'en-c1-55', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lỗ chân lông; lỗ nhỏ (trên bề mặt)”', '["mirage","pore","specification","feasible"]'::jsonb, 1, 'lỗ chân lông; lỗ nhỏ (trên bề mặt) → pore (/pɔːr/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-56', 'en', 'Bài 56: Khoa học & Nghiên cứu (3) - CEFR C1', 'CEFR C1', 'C1 · Khoa học', '26 từ vựng Tiếng Anh CEFR C1 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5056, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_magnitude', 'en-c1-56', 'magnitude', '/ˈmæɡnɪtuːd/', 'C1', 'tầm vóc; quy mô lớn; tầm quan trọng; độ lớn (của trận động đất)', 'n.', NULL, 'Đồng nghĩa: scale, extent', 'Khi nói về quy mô thường dùng the magnitude of; cấp độ động đất cũng dùng từ này.', 'We only realised the magnitude of the damage at sunrise.', NULL, 'Chúng tôi chỉ nhận ra mức độ nghiêm trọng của thiệt hại khi trời sáng.', '{"wordId":"magnitude","ukIpa":"/ˈmæɡnɪtjuːd/","usIpa":"/ˈmæɡnɪtuːd/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The size, extent, or importance of something.","vi":"tầm vóc; quy mô lớn; tầm quan trọng"},{"pos":"n.","en":"A measure of the energy released by an earthquake.","vi":"độ lớn (của trận động đất)"}],"examples":[{"en":"We only realised the magnitude of the damage at sunrise.","vi":"Chúng tôi chỉ nhận ra mức độ nghiêm trọng của thiệt hại khi trời sáng.","audioKind":"ex"},{"en":"The magnitude of global food waste highlights the need for better storage systems and more responsible consumption.","vi":"Quy mô lớn của tình trạng lãng phí thực phẩm toàn cầu làm nổi bật sự cần thiết của các hệ thống bảo quản tốt hơn và tiêu dùng có trách nhiệm hơn.","audioKind":"ex2"}],"collocations":[{"en":"the magnitude of the problem","vi":"mức độ nghiêm trọng của vấn đề"},{"en":"an earthquake of magnitude six","vi":"trận động đất sáu độ rích-te"},{"en":"an order of magnitude","vi":"một bậc đại lượng"}],"wordFamily":[],"synonyms":["scale","extent"],"antonyms":[],"tipVi":"Khi nói về quy mô thường dùng the magnitude of; cấp độ động đất cũng dùng từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_latitude', 'en-c1-56', 'latitude', '/ˈlætɪtuːd/', 'C1', 'vĩ độ; sự tự do hành động; quyền tự quyết', 'n.', NULL, NULL, 'Latitude là vĩ độ, còn longitude là kinh độ.', 'Our geography teacher showed us latitude on a globe.', NULL, 'Giáo viên địa lý đã chỉ cho chúng tôi xem vĩ độ trên quả địa cầu.', '{"wordId":"latitude","ukIpa":"/ˈlætɪtjuːd/","usIpa":"/ˈlætɪtuːd/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"Distance north or south of the equator, measured in degrees.","vi":"vĩ độ"},{"pos":"n.","en":"Freedom to choose how to act or decide.","vi":"sự tự do hành động; quyền tự quyết"}],"examples":[{"en":"Our geography teacher showed us latitude on a globe.","vi":"Giáo viên địa lý đã chỉ cho chúng tôi xem vĩ độ trên quả địa cầu.","audioKind":"ex"},{"en":"Regions at higher latitudes generally experience greater seasonal variations in daylight than those near the equator.","vi":"Các vùng ở vĩ độ cao thường trải qua sự biến động theo mùa về thời gian ban ngày lớn hơn so với những vùng gần xích đạo.","audioKind":"ex2"}],"collocations":[{"en":"high latitudes","vi":"các vùng vĩ độ cao"},{"en":"low latitudes","vi":"các vùng vĩ độ thấp"},{"en":"give someone latitude","vi":"cho ai đó quyền tự chủ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Latitude là vĩ độ, còn longitude là kinh độ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spatial', 'en-c1-56', 'spatial', '/ˈspeɪʃəl/', 'C1', 'thuộc về không gian', 'adj.', 'space (n.), spatially (adv.)', NULL, 'spatial chỉ mối quan hệ không gian; spacious chỉ không gian rộng rãi.', 'Building with blocks helps children develop their spatial awareness.', NULL, 'Việc chơi xếp hình giúp trẻ em phát triển nhận thức không gian.', '{"wordId":"spatial","ukIpa":"/ˈspeɪʃəl/","usIpa":"/ˈspeɪʃəl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"relating to space and the positions of objects within it","vi":"thuộc về không gian"}],"examples":[{"en":"Building with blocks helps children develop their spatial awareness.","vi":"Việc chơi xếp hình giúp trẻ em phát triển nhận thức không gian.","audioKind":"ex"},{"en":"Urban planners examine the spatial distribution of housing to ensure residents can access essential services.","vi":"Các nhà quy hoạch đô thị nghiên cứu sự phân bố không gian của nhà ở để đảm bảo cư dân có thể tiếp cận các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"spatial awareness","vi":"nhận thức không gian"},{"en":"spatial distribution","vi":"phân bố không gian"},{"en":"spatial reasoning","vi":"tư duy không gian"}],"wordFamily":["space (n.)","spatially (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"spatial chỉ mối quan hệ không gian; spacious chỉ không gian rộng rãi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_composite', 'en-c1-56', 'composite', '/kəmˈpɑːzɪt/', 'C1', 'phức hợp; tổng hợp; vật liệu tổng hợp; vật liệu composite', 'adj.', 'composition (n.), compose (v.)', NULL, 'Nhấn mạnh việc được kết hợp từ nhiều phần khác nhau, thường bổ nghĩa cho material hoặc image.', 'Our new garden bench is made from composite material.', NULL, 'Ghế dài trong vườn của chúng tôi được làm bằng vật liệu composite.', '{"wordId":"composite","ukIpa":"/ˈkɒmpəzɪt/","usIpa":"/kəmˈpɑːzɪt/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"made by combining different parts or materials","vi":"phức hợp; tổng hợp"},{"pos":"n.","en":"something made from several different parts or materials","vi":"vật liệu tổng hợp; vật liệu composite"}],"examples":[{"en":"Our new garden bench is made from composite material.","vi":"Ghế dài trong vườn của chúng tôi được làm bằng vật liệu composite.","audioKind":"ex"},{"en":"Lightweight composite materials can reduce fuel consumption by making aircraft lighter without significantly compromising their strength.","vi":"Vật liệu composite trọng lượng nhẹ có thể giúp giảm tiêu thụ nhiên liệu bằng cách làm cho máy bay nhẹ hơn mà không làm giảm đáng kể độ bền của chúng.","audioKind":"ex2"}],"collocations":[{"en":"composite material","vi":"vật liệu composite"},{"en":"composite image","vi":"hình ảnh tổng hợp"},{"en":"composite index","vi":"chỉ số tổng hợp"}],"wordFamily":["composition (n.)","compose (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh việc được kết hợp từ nhiều phần khác nhau, thường bổ nghĩa cho material hoặc image.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_metallic', 'en-c1-56', 'metallic', '/məˈtælɪk/', 'C1', 'bằng kim loại; chứa kim loại; có tính chất kim loại; có ánh, âm thanh hoặc vị như kim loại', 'adj.', 'metal (n.), non-metallic (adj.)', 'Trái nghĩa: non-metallic', 'Metallic vừa có thể chỉ chứa kim loại, vừa có thể miêu tả vẻ ngoài hoặc âm thanh giống kim loại.', 'The metallic frame makes this chair surprisingly heavy.', NULL, 'Khung kim loại làm cho chiếc ghế này nặng một cách đáng ngạc nhiên.', '{"wordId":"metallic","ukIpa":"/məˈtælɪk/","usIpa":"/məˈtælɪk/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Made of or containing metal.","vi":"bằng kim loại; chứa kim loại"},{"pos":"adj.","en":"Resembling metal in appearance, sound, or taste.","vi":"có tính chất kim loại; có ánh, âm thanh hoặc vị như kim loại"}],"examples":[{"en":"The metallic frame makes this chair surprisingly heavy.","vi":"Khung kim loại làm cho chiếc ghế này nặng một cách đáng ngạc nhiên.","audioKind":"ex"},{"en":"Metallic components can often be recovered from discarded electronics, reducing the need to extract new raw materials.","vi":"Các linh kiện kim loại thường có thể được thu hồi từ đồ điện tử bị vứt bỏ, làm giảm nhu cầu khai thác nguyên liệu thô mới.","audioKind":"ex2"}],"collocations":[{"en":"metallic components","vi":"các linh kiện kim loại"},{"en":"a metallic taste","vi":"vị kim loại"},{"en":"a metallic sound","vi":"âm thanh như kim loại"},{"en":"a metallic finish","vi":"lớp sơn ánh kim"}],"wordFamily":["metal (n.)","non-metallic (adj.)"],"synonyms":[],"antonyms":["non-metallic"],"tipVi":"Metallic vừa có thể chỉ chứa kim loại, vừa có thể miêu tả vẻ ngoài hoặc âm thanh giống kim loại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spiral', 'en-c1-56', 'spiral', '/ˈspaɪrəl/', 'C1', 'hình xoắn ốc; đường xoắn ốc; cuốn theo hình xoắn ốc; tăng hoặc giảm tệ đi nhanh chóng', 'n.', 'spirally (adv.)', NULL, 'Cách viết quá khứ: tiếng Anh-Anh là spiralled; tiếng Anh-Mỹ là spiraled, quy tắc gấp đôi phụ âm khác nhau.', 'The orange peel fell in a spiral onto the plate.', NULL, 'Vỏ quả cam rơi xuống đĩa theo hình xoắn ốc.', '{"wordId":"spiral","ukIpa":"/ˈspaɪrəl/","usIpa":"/ˈspaɪrəl/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A curve winding around a centre or axis.","vi":"hình xoắn ốc; đường xoắn ốc"},{"pos":"adj.","en":"Curving around a centre or axis.","vi":"hình xoắn ốc"},{"pos":"v.","en":"To move in curves, or increase or worsen rapidly.","vi":"cuốn theo hình xoắn ốc; tăng hoặc giảm tệ đi nhanh chóng"}],"examples":[{"en":"The orange peel fell in a spiral onto the plate.","vi":"Vỏ quả cam rơi xuống đĩa theo hình xoắn ốc.","audioKind":"ex"},{"en":"Without adequate housing policies, rental costs may spiral beyond the reach of many low-income families.","vi":"Nếu thiếu các chính sách nhà ở thích hợp, chi phí thuê nhà có thể tăng vọt vượt quá tầm với của nhiều gia đình thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"spiral staircase","vi":"cầu thang xoắn ốc"},{"en":"downward spiral","vi":"vòng xoáy đi xuống"},{"en":"spiral out of control","vi":"trượt dốc không phanh"},{"en":"spiralling costs","vi":"chi phí leo thang"}],"wordFamily":["spirally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết quá khứ: tiếng Anh-Anh là spiralled; tiếng Anh-Mỹ là spiraled, quy tắc gấp đôi phụ âm khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diffuse', 'en-c1-56', 'diffuse', '/dɪˈfjuːz/', 'C1', 'khuếch tán; lan tỏa; làm tán xạ; tản mác; lan rộng; dài dòng; lan man', 'v.', 'diffusion (n.)', 'Đồng nghĩa: spread, disperse · Trái nghĩa: concentrate', 'Động từ phát âm đuôi /z/, tính từ phát âm đuôi /s/; tránh nhầm lẫn với từ defuse (hóa giải).', 'The scent of fresh bread diffused through the kitchen.', NULL, 'Hương thơm của bánh mì mới nướng lan tỏa khắp căn bếp.', '{"wordId":"diffuse","ukIpa":"/dɪˈfjuːz/","usIpa":"/dɪˈfjuːz/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To spread widely, or make light scatter in many directions.","vi":"khuếch tán; lan tỏa; làm tán xạ"},{"pos":"adj.","en":"Spread over a wide area rather than concentrated.","vi":"tản mác; lan rộng"},{"pos":"adj.","en":"Using too many words without a clear focus.","vi":"dài dòng; lan man"}],"examples":[{"en":"The scent of fresh bread diffused through the kitchen.","vi":"Hương thơm của bánh mì mới nướng lan tỏa khắp căn bếp.","audioKind":"ex"},{"en":"Public libraries help diffuse knowledge throughout society by providing free access to reliable information and educational resources.","vi":"Các thư viện công cộng giúp truyền bá kiến thức ra toàn xã hội bằng cách cung cấp quyền truy cập miễn phí vào các nguồn tài nguyên giáo dục và thông tin đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"diffuse light","vi":"làm ánh sáng tán xạ"},{"en":"diffuse knowledge","vi":"truyền bá kiến thức"},{"en":"diffuse through","vi":"khuếch tán vào..."}],"wordFamily":["diffusion (n.)"],"synonyms":["spread","disperse"],"antonyms":["concentrate"],"tipVi":"Động từ phát âm đuôi /z/, tính từ phát âm đuôi /s/; tránh nhầm lẫn với từ defuse (hóa giải).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cellular', 'en-c1-56', 'cellular', '/ˈseljələr/', 'C1', 'thuộc về tế bào (của sinh vật sống); dùng mạng di động (chia thành các vùng phủ sóng nhỏ)', 'adj.', 'cell (n.), unicellular (adj.), multicellular (adj.)', NULL, 'Trong sinh học mang nghĩa thuộc về tế bào; trong truyền thông mang nghĩa mạng di động.', 'Our teacher showed us cellular structures through a microscope.', NULL, 'Giáo viên của chúng tôi cho chúng tôi xem các cấu trúc tế bào qua kính hiển vi.', '{"wordId":"cellular","ukIpa":"/ˈseljələ/","usIpa":"/ˈseljələr/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Relating to the cells of living organisms.","vi":"thuộc về tế bào (của sinh vật sống)"},{"pos":"adj.","en":"Using a mobile network divided into local coverage areas.","vi":"dùng mạng di động (chia thành các vùng phủ sóng nhỏ)"}],"examples":[{"en":"Our teacher showed us cellular structures through a microscope.","vi":"Giáo viên của chúng tôi cho chúng tôi xem các cấu trúc tế bào qua kính hiển vi.","audioKind":"ex"},{"en":"Research into cellular damage may help scientists develop treatments for diseases associated with ageing.","vi":"Nghiên cứu về tổn thương tế bào có thể giúp các nhà khoa học phát triển phương pháp điều trị các bệnh liên quan đến tuổi tác.","audioKind":"ex2"}],"collocations":[{"en":"cellular structure","vi":"cấu trúc tế bào"},{"en":"cellular respiration","vi":"hô hấp tế bào"},{"en":"cellular damage","vi":"tổn thương tế bào"},{"en":"cellular network","vi":"mạng di động"}],"wordFamily":["cell (n.)","unicellular (adj.)","multicellular (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong sinh học mang nghĩa thuộc về tế bào; trong truyền thông mang nghĩa mạng di động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_synthesis', 'en-c1-56', 'synthesis', '/ˈsɪnθəsɪs/', 'C1', 'sự tổng hợp; sự kết hợp; sự tổng hợp hóa học', 'n.', 'synthesise (v.), synthetic (adj.)', NULL, 'Dạng số nhiều là syntheses; thường dùng cụm a synthesis of.', 'Her room is a synthesis of old and modern styles.', NULL, 'Phòng của cô ấy là sự hòa quyện giữa phong cách cổ điển và hiện đại.', '{"wordId":"synthesis","ukIpa":"/ˈsɪnθəsɪs/","usIpa":"/ˈsɪnθəsɪs/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The combination of different ideas or elements into a whole.","vi":"sự tổng hợp; sự kết hợp"},{"pos":"n.","en":"The production of a substance by combining simpler substances.","vi":"sự tổng hợp hóa học"}],"examples":[{"en":"Her room is a synthesis of old and modern styles.","vi":"Phòng của cô ấy là sự hòa quyện giữa phong cách cổ điển và hiện đại.","audioKind":"ex"},{"en":"A synthesis of findings from several studies provides stronger evidence for the benefits of regular exercise.","vi":"Việc tổng hợp các phát hiện từ nhiều nghiên cứu mang lại bằng chứng vững chắc hơn về lợi ích của việc tập thể dục thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"a synthesis of ideas","vi":"sự tổng hợp các ý tưởng"},{"en":"chemical synthesis","vi":"tổng hợp hóa học"},{"en":"protein synthesis","vi":"tổng hợp protein"}],"wordFamily":["synthesise (v.)","synthetic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là syntheses; thường dùng cụm a synthesis of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conclusive', 'en-c1-56', 'conclusive', '/kənˈkluːsɪv/', 'C1', 'xác thực; có tính quyết định; thuyết phục', 'adj.', 'conclude (v.), conclusion (n.), conclusively (adv.), inconclusive (adj.)', 'Đồng nghĩa: decisive, definitive · Trái nghĩa: inconclusive', 'Thường bổ nghĩa cho các danh từ như evidence hoặc proof, và không đồng nghĩa với "cuối cùng" (final).', 'The camera footage provided conclusive proof of what happened.', NULL, 'Đoạn phim từ camera đã cung cấp bằng chứng xác thực về những gì đã xảy ra.', '{"wordId":"conclusive","ukIpa":"/kənˈkluːsɪv/","usIpa":"/kənˈkluːsɪv/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"proving something clearly and leaving no reasonable doubt","vi":"xác thực; có tính quyết định; thuyết phục"}],"examples":[{"en":"The camera footage provided conclusive proof of what happened.","vi":"Đoạn phim từ camera đã cung cấp bằng chứng xác thực về những gì đã xảy ra.","audioKind":"ex"},{"en":"Researchers need conclusive evidence before recommending major changes to national policies on childhood nutrition.","vi":"Các nhà nghiên cứu cần có bằng chứng xác thực trước khi đưa ra khuyến nghị thay đổi lớn đối với các chính sách quốc gia về dinh dưỡng trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"conclusive evidence","vi":"bằng chứng xác thực"},{"en":"conclusive proof","vi":"chứng cứ thuyết phục"},{"en":"conclusive results","vi":"kết quả mang tính quyết định"}],"wordFamily":["conclude (v.)","conclusion (n.)","conclusively (adv.)","inconclusive (adj.)"],"synonyms":["decisive","definitive"],"antonyms":["inconclusive"],"tipVi":"Thường bổ nghĩa cho các danh từ như evidence hoặc proof, và không đồng nghĩa với \"cuối cùng\" (final).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aerosol', 'en-c1-56', 'aerosol', '/ˈerəsɔːl/', 'C1', 'bình xịt; chất khí dung (bình nén phun chất lỏng thành tia mịn); khí dung (hạt rắn hoặc giọt lỏng cực nhỏ lơ lửng trong khí)', 'n.', NULL, NULL, 'Trong đời sống thường ngày chỉ bình xịt; trong bối cảnh khoa học chỉ các hạt lơ lửng trong không khí.', 'She used an aerosol to spray the dusty leaves.', NULL, 'Cô ấy dùng bình xịt để xịt lên những chiếc lá đầy bụi.', '{"wordId":"aerosol","ukIpa":"/ˈeərəsɒl/","usIpa":"/ˈerəsɔːl/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A pressurised container that releases liquid as a fine spray.","vi":"bình xịt; chất khí dung (bình nén phun chất lỏng thành tia mịn)"},{"pos":"n.","en":"Tiny solid particles or liquid droplets suspended in a gas.","vi":"khí dung (hạt rắn hoặc giọt lỏng cực nhỏ lơ lửng trong khí)"}],"examples":[{"en":"She used an aerosol to spray the dusty leaves.","vi":"Cô ấy dùng bình xịt để xịt lên những chiếc lá đầy bụi.","audioKind":"ex"},{"en":"Atmospheric aerosols can influence the climate by scattering sunlight and altering the formation of clouds.","vi":"Khí dung trong khí quyển có thể ảnh hưởng đến khí hậu bằng cách tán xạ ánh sáng mặt trời và làm thay đổi sự hình thành mây.","audioKind":"ex2"}],"collocations":[{"en":"an aerosol can","vi":"bình xịt"},{"en":"an aerosol spray","vi":"bình phun khí dung"},{"en":"atmospheric aerosols","vi":"khí dung khí quyển"},{"en":"aerosol particles","vi":"hạt khí dung"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong đời sống thường ngày chỉ bình xịt; trong bối cảnh khoa học chỉ các hạt lơ lửng trong không khí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rigorous', 'en-c1-56', 'rigorous', '/ˈrɪɡərəs/', 'C1', 'nghiêm ngặt; kỹ lưỡng; chặt chẽ; đòi hỏi sự tuân thủ nghiêm ngặt hoặc kỷ luật cao', 'adj.', 'rigorously (adv.), rigour (n.)', 'Đồng nghĩa: thorough, strict, exacting · Trái nghĩa: lax', 'Trong nghiên cứu hoặc thử nghiệm, từ này nhấn mạnh tính khắt khe và kỹ lưỡng; khi áp dụng cho huấn luyện hoặc tiêu chuẩn, nó nhấn mạnh sự nghiêm ngặt.', 'The mechanic gave our car a rigorous safety check.', NULL, 'Thợ máy đã tiến hành kiểm tra an toàn kỹ lưỡng cho chiếc xe của chúng tôi.', '{"wordId":"rigorous","ukIpa":"/ˈrɪɡərəs/","usIpa":"/ˈrɪɡərəs/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"extremely careful and thorough","vi":"nghiêm ngặt; kỹ lưỡng; chặt chẽ"},{"pos":"adj.","en":"demanding strict effort or obedience to rules","vi":"đòi hỏi sự tuân thủ nghiêm ngặt hoặc kỷ luật cao"}],"examples":[{"en":"The mechanic gave our car a rigorous safety check.","vi":"Thợ máy đã tiến hành kiểm tra an toàn kỹ lưỡng cho chiếc xe của chúng tôi.","audioKind":"ex"},{"en":"New medical treatments require rigorous testing before they can be widely used in public healthcare.","vi":"Các phương pháp điều trị y tế mới đòi hỏi phải được kiểm định nghiêm ngặt trước khi có thể áp dụng rộng rãi trong y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"rigorous testing","vi":"kiểm tra nghiêm ngặt"},{"en":"rigorous analysis","vi":"phân tích chặt chẽ"},{"en":"rigorous training","vi":"huấn luyện khắt khe"}],"wordFamily":["rigorously (adv.)","rigour (n.)"],"synonyms":["thorough","strict","exacting"],"antonyms":["lax"],"tipVi":"Trong nghiên cứu hoặc thử nghiệm, từ này nhấn mạnh tính khắt khe và kỹ lưỡng; khi áp dụng cho huấn luyện hoặc tiêu chuẩn, nó nhấn mạnh sự nghiêm ngặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_zinc', 'en-c1-56', 'zinc', '/zɪŋk/', 'C1', 'kẽm', 'n.', NULL, NULL, 'Kẽm là một nguyên tố hóa học, ký hiệu Zn; khi chỉ chất khoáng, từ này thường không đếm được.', 'These pumpkin seeds contain zinc and make a tasty snack.', NULL, 'Những hạt bí ngô này chứa kẽm và là một món ăn vặt ngon miệng.', '{"wordId":"zinc","ukIpa":"/zɪŋk/","usIpa":"/zɪŋk/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A bluish-white metal also needed in small amounts for health.","vi":"kẽm"}],"examples":[{"en":"These pumpkin seeds contain zinc and make a tasty snack.","vi":"Những hạt bí ngô này chứa kẽm và là một món ăn vặt ngon miệng.","audioKind":"ex"},{"en":"Zinc coatings protect steel from corrosion, extending the lifespan of structures exposed to rain and moisture.","vi":"Lớp mạ kẽm giúp bảo vệ thép khỏi bị ăn mòn, kéo dài tuổi thọ của các công trình tiếp xúc với mưa và độ ẩm.","audioKind":"ex2"}],"collocations":[{"en":"zinc deficiency","vi":"tình trạng thiếu kẽm"},{"en":"zinc supplements","vi":"thực phẩm bổ sung kẽm"},{"en":"zinc coating","vi":"lớp mạ kẽm"},{"en":"zinc oxide","vi":"oxit kẽm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Kẽm là một nguyên tố hóa học, ký hiệu Zn; khi chỉ chất khoáng, từ này thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_propagate', 'en-c1-56', 'propagate', '/ˈprɑːpəɡeɪt/', 'C1', 'truyền bá; tuyên truyền; nhân giống; làm cho sinh sôi', 'v.', 'propagation (n.), propagator (n.)', 'Đồng nghĩa: spread, disseminate', 'Có thể dùng để chỉ việc lan truyền ý tưởng hoặc nhân giống cây cối; văn phong khá trang trọng.', 'Unverified stories propagate quickly when people share them online.', NULL, 'Những câu chuyện chưa được kiểm chứng lan truyền rất nhanh khi mọi người chia sẻ chúng trên mạng.', '{"wordId":"propagate","ukIpa":"/ˈprɒpəɡeɪt/","usIpa":"/ˈprɑːpəɡeɪt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To spread ideas, beliefs, or information among people.","vi":"truyền bá; tuyên truyền"},{"pos":"v.","en":"To produce new plants or organisms from existing ones.","vi":"nhân giống; làm cho sinh sôi"}],"examples":[{"en":"Unverified stories propagate quickly when people share them online.","vi":"Những câu chuyện chưa được kiểm chứng lan truyền rất nhanh khi mọi người chia sẻ chúng trên mạng.","audioKind":"ex"},{"en":"Community nurseries can propagate native plants from cuttings, supporting habitat restoration without removing specimens from the wild.","vi":"Các vườn ươm cộng đồng có thể nhân giống cây bản địa từ cành giâm, hỗ trợ phục hồi môi trường sống mà không cần khai thác cây từ tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"propagate ideas","vi":"truyền bá tư tưởng"},{"en":"propagate misinformation","vi":"lan truyền thông tin sai lệch"},{"en":"propagate plants","vi":"nhân giống cây trồng"},{"en":"propagate from cuttings","vi":"nhân giống bằng phương pháp giâm cành"}],"wordFamily":["propagation (n.)","propagator (n.)"],"synonyms":["spread","disseminate"],"antonyms":[],"tipVi":"Có thể dùng để chỉ việc lan truyền ý tưởng hoặc nhân giống cây cối; văn phong khá trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quantitative', 'en-c1-56', 'quantitative', '/ˈkwɑːntəteɪtɪv/', 'C1', 'định lượng; thuộc về số lượng', 'adj.', 'quantity (n.), quantify (v.), quantification (n.), quantitatively (adv.)', 'Trái nghĩa: qualitative', 'Quantitative tập trung vào đo lường số lượng; trong khi qualitative tập trung vào mô tả tính chất.', 'Our coach uses quantitative data to track our progress.', NULL, 'Huấn luyện viên của chúng tôi sử dụng dữ liệu định lượng để theo dõi sự tiến bộ của chúng tôi.', '{"wordId":"quantitative","ukIpa":"/ˈkwɒntɪtətɪv/","usIpa":"/ˈkwɑːntəteɪtɪv/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"relating to amounts that can be measured or counted","vi":"định lượng; thuộc về số lượng"}],"examples":[{"en":"Our coach uses quantitative data to track our progress.","vi":"Huấn luyện viên của chúng tôi sử dụng dữ liệu định lượng để theo dõi sự tiến bộ của chúng tôi.","audioKind":"ex"},{"en":"Quantitative research allows policymakers to compare employment trends across regions using consistent statistical measures.","vi":"Nghiên cứu định lượng cho phép các nhà hoạch định chính sách so sánh các xu hướng việc làm giữa các khu vực bằng cách sử dụng các chỉ số thống kê nhất quán.","audioKind":"ex2"}],"collocations":[{"en":"quantitative research","vi":"nghiên cứu định lượng"},{"en":"quantitative analysis","vi":"phân tích định lượng"},{"en":"quantitative data","vi":"dữ liệu định lượng"}],"wordFamily":["quantity (n.)","quantify (v.)","quantification (n.)","quantitatively (adv.)"],"synonyms":[],"antonyms":["qualitative"],"tipVi":"Quantitative tập trung vào đo lường số lượng; trong khi qualitative tập trung vào mô tả tính chất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reactor', 'en-c1-56', 'reactor', '/riˈæktər/', 'C1', 'lò phản ứng hạt nhân; bình phản ứng hóa học', 'n.', 'react (v.), reaction (n.), reactive (adj.)', NULL, 'Trong chủ đề năng lượng thường chỉ lò phản ứng hạt nhân; trong công nghiệp hóa chất cũng dùng để chỉ thiết bị phản ứng.', 'Our guide showed us a model of a nuclear reactor.', NULL, 'Hướng dẫn viên cho chúng tôi xem mô hình của một lò phản ứng hạt nhân.', '{"wordId":"reactor","ukIpa":"/riˈæktə/","usIpa":"/riˈæktər/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"a device that controls nuclear reactions to produce energy","vi":"lò phản ứng hạt nhân"},{"pos":"n.","en":"a container in which controlled chemical reactions take place","vi":"bình phản ứng hóa học"}],"examples":[{"en":"Our guide showed us a model of a nuclear reactor.","vi":"Hướng dẫn viên cho chúng tôi xem mô hình của một lò phản ứng hạt nhân.","audioKind":"ex"},{"en":"Modern reactor designs aim to improve safety while supplying reliable electricity with low carbon emissions.","vi":"Các thiết kế lò phản ứng hiện đại nhằm mục đích nâng cao độ an toàn đồng thời cung cấp điện năng ổn định với mức phát thải carbon thấp.","audioKind":"ex2"}],"collocations":[{"en":"nuclear reactor","vi":"lò phản ứng hạt nhân"},{"en":"reactor core","vi":"lõi lò phản ứng"},{"en":"chemical reactor","vi":"bình phản ứng hóa học"}],"wordFamily":["react (v.)","reaction (n.)","reactive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong chủ đề năng lượng thường chỉ lò phản ứng hạt nhân; trong công nghiệp hóa chất cũng dùng để chỉ thiết bị phản ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mimic', 'en-c1-56', 'mimic', '/ˈmɪmɪk/', 'C1', 'bắt chước; mô phỏng; người giỏi bắt chước', 'v.', 'mimicry (n.), mimetic (adj.)', 'Đồng nghĩa: imitate, copy', 'Dạng quá khứ là mimicked và dạng tiếp diễn là mimicking, cả hai đều thêm chữ k.', 'Our parrot mimics the sound of the doorbell perfectly.', NULL, 'Con vẹt nhà chúng tôi bắt chước âm thanh tiếng chuông cửa cực kỳ giống.', '{"wordId":"mimic","ukIpa":"/ˈmɪmɪk/","usIpa":"/ˈmɪmɪk/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"to copy someone''s behaviour or reproduce something''s features","vi":"bắt chước; mô phỏng"},{"pos":"n.","en":"a person skilled at copying other people''s voices or behaviour","vi":"người giỏi bắt chước"}],"examples":[{"en":"Our parrot mimics the sound of the doorbell perfectly.","vi":"Con vẹt nhà chúng tôi bắt chước âm thanh tiếng chuông cửa cực kỳ giống.","audioKind":"ex"},{"en":"Engineers increasingly mimic natural structures to develop lighter materials that require less energy to manufacture.","vi":"Các kỹ sư ngày càng mô phỏng các cấu trúc tự nhiên để phát triển các loại vật liệu nhẹ hơn đòi hỏi ít năng lượng hơn trong quá trình sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"mimic someone''s voice","vi":"bắt chước giọng của ai đó"},{"en":"mimic natural processes","vi":"mô phỏng các quá trình tự nhiên"},{"en":"a talented mimic","vi":"một người có tài bắt chước"}],"wordFamily":["mimicry (n.)","mimetic (adj.)"],"synonyms":["imitate","copy"],"antonyms":[],"tipVi":"Dạng quá khứ là mimicked và dạng tiếp diễn là mimicking, cả hai đều thêm chữ k.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mechanics', 'en-c1-56', 'mechanics', '/məˈkænɪks/', 'C1', 'cơ học; cách thức vận hành; kỹ thuật chi tiết', 'n.', 'mechanical (adj.), mechanically (adv.), mechanism (n.), mechanic (n.)', NULL, 'Khi chỉ ngành lực học dùng động từ số ít; khi chỉ chi tiết thao tác thường đi với nghĩa rộng.', 'We explored mechanics by building a small wooden catapult.', NULL, 'Chúng tôi đã tìm hiểu về cơ học bằng cách tự chế tạo một chiếc máy bắn đá nhỏ bằng gỗ.', '{"wordId":"mechanics","ukIpa":"/məˈkænɪks/","usIpa":"/məˈkænɪks/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The study of forces and how objects move","vi":"cơ học"},{"pos":"n.","en":"The practical details of how something works or is done","vi":"cách thức vận hành; kỹ thuật chi tiết"}],"examples":[{"en":"We explored mechanics by building a small wooden catapult.","vi":"Chúng tôi đã tìm hiểu về cơ học bằng cách tự chế tạo một chiếc máy bắn đá nhỏ bằng gỗ.","audioKind":"ex"},{"en":"Understanding the mechanics of online learning helps teachers design courses that students can navigate easily.","vi":"Việc nắm rõ cơ chế học trực tuyến giúp giáo viên thiết kế các khóa học mà học sinh có thể dễ dàng tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"classical mechanics","vi":"cơ học cổ điển"},{"en":"fluid mechanics","vi":"cơ học chất lưu"},{"en":"the mechanics of voting","vi":"cách thức tiến hành bỏ phiếu"}],"wordFamily":["mechanical (adj.)","mechanically (adv.)","mechanism (n.)","mechanic (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ ngành lực học dùng động từ số ít; khi chỉ chi tiết thao tác thường đi với nghĩa rộng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repel', 'en-c1-56', 'repel', '/rɪˈpel/', 'C1', 'xua đuổi; đẩy lùi (buộc ai đó hoặc cái gì đó phải di chuyển ra xa); chống lại; không thấm (đẩy lùi thứ gì đó hoặc ngăn không cho nó hấp thụ); làm ghê tởm; làm kinh hãi (khiến ai đó cảm thấy vô cùng khó chịu hoặc chán ghét)', 'v.', 'repellent (adj.), repulsion (n.), repulsive (adj.)', 'Đồng nghĩa: repulse, drive away · Trái nghĩa: attract', 'Thể quá khứ là repelled, danh động từ là repelling, được gấp đôi phụ âm l.', 'This spray helps repel mosquitoes when we eat outside.', NULL, 'Loại xịt này giúp xua đuổi muỗi khi chúng tôi ăn uống ngoài trời.', '{"wordId":"repel","ukIpa":"/rɪˈpel/","usIpa":"/rɪˈpel/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"Force someone or something to move away.","vi":"xua đuổi; đẩy lùi (buộc ai đó hoặc cái gì đó phải di chuyển ra xa)"},{"pos":"v.","en":"Push something away or prevent it from being absorbed.","vi":"chống lại; không thấm (đẩy lùi thứ gì đó hoặc ngăn không cho nó hấp thụ)"},{"pos":"v.","en":"Make someone feel strong dislike or disgust.","vi":"làm ghê tởm; làm kinh hãi (khiến ai đó cảm thấy vô cùng khó chịu hoặc chán ghét)"}],"examples":[{"en":"This spray helps repel mosquitoes when we eat outside.","vi":"Loại xịt này giúp xua đuổi muỗi khi chúng tôi ăn uống ngoài trời.","audioKind":"ex"},{"en":"Modern outdoor clothing uses specially treated fabrics that repel water while allowing moisture to escape.","vi":"Trang phục ngoài trời hiện đại sử dụng các loại vải được xử lý đặc biệt có khả năng chống thấm nước đồng thời cho phép hơi ẩm thoát ra ngoài.","audioKind":"ex2"}],"collocations":[{"en":"repel insects","vi":"xua đuổi côn trùng"},{"en":"repel an attack","vi":"đẩy lùi một cuộc tấn công"},{"en":"repel water","vi":"chống thấm nước"},{"en":"repel each other","vi":"đẩy lùi lẫn nhau"}],"wordFamily":["repellent (adj.)","repulsion (n.)","repulsive (adj.)"],"synonyms":["repulse","drive away"],"antonyms":["attract"],"tipVi":"Thể quá khứ là repelled, danh động từ là repelling, được gấp đôi phụ âm l.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_granular', 'en-c1-56', 'granular', '/ˈɡrænjələr/', 'C1', 'có dạng hạt; sần; chi tiết; cụ thể; tỉ mỉ', 'adj.', 'granule (n.), granularity (n.)', NULL, 'Vừa mang nghĩa vật lý là có dạng hạt, vừa chỉ mức độ phân tích dữ liệu vô cùng chi tiết.', 'The granular sugar crunched softly between my teeth.', NULL, 'Những hạt đường nhỏ kêu lạo xạo dưới hàm răng tôi.', '{"wordId":"granular","ukIpa":"/ˈɡrænjələ/","usIpa":"/ˈɡrænjələr/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"consisting of small grains or particles","vi":"có dạng hạt; sần"},{"pos":"adj.","en":"including many small, specific details","vi":"chi tiết; cụ thể; tỉ mỉ"}],"examples":[{"en":"The granular sugar crunched softly between my teeth.","vi":"Những hạt đường nhỏ kêu lạo xạo dưới hàm răng tôi.","audioKind":"ex"},{"en":"More granular data would help researchers identify differences in educational outcomes between individual neighbourhoods.","vi":"Dữ liệu chi tiết hơn sẽ giúp các nghiên cứu sinh nhận diện sự khác biệt về kết quả học tập giữa các khu124 vực lân cận.","audioKind":"ex2"}],"collocations":[{"en":"granular material","vi":"vật liệu dạng hạt"},{"en":"granular data","vi":"dữ liệu chi tiết"},{"en":"granular detail","vi":"chi tiết tỉ mỉ"}],"wordFamily":["granule (n.)","granularity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa mang nghĩa vật lý là có dạng hạt, vừa chỉ mức độ phân tích dữ liệu vô cùng chi tiết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distil', 'en-c1-56', 'distil', '/dɪˈstɪl/', 'C1', 'chưng cất; tịch thu; đúc kết; cô đọng', 'v.', 'distillation (n.), distilled (adj.), distiller (n.)', NULL, 'Cách viết Anh-Anh là ''distil'', Anh-Mỹ là ''distill''; dạng quá khứ đều là ''distilled''.', 'This small device distils seawater into clean drinking water.', NULL, 'Thiết bị nhỏ gọn này chưng cất nước biển thành nước uống sạch.', '{"wordId":"distil","ukIpa":"/dɪˈstɪl/","usIpa":"/dɪˈstɪl/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"Purify a liquid by heating it and cooling its vapour.","vi":"chưng cất"},{"pos":"v.","en":"Extract the most important ideas from something complex.","vi":"tịch thu; đúc kết; cô đọng"}],"examples":[{"en":"This small device distils seawater into clean drinking water.","vi":"Thiết bị nhỏ gọn này chưng cất nước biển thành nước uống sạch.","audioKind":"ex"},{"en":"Researchers must distil complex findings into clear recommendations that policymakers can readily understand and apply.","vi":"Các nhà nghiên cứu phải đúc kết các kết quả phức tạp thành những khuyến nghị rõ ràng để các nhà hoạch định chính sách có thể dễ dàng hiểu và áp dụng.","audioKind":"ex2"}],"collocations":[{"en":"distil water","vi":"chưng cất nước"},{"en":"distil information","vi":"đúc kết thông tin"},{"en":"distil something into","vi":"chắt lọc cái gì thành"}],"wordFamily":["distillation (n.)","distilled (adj.)","distiller (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết Anh-Anh là ''distil'', Anh-Mỹ là ''distill''; dạng quá khứ đều là ''distilled''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oceanography', 'en-c1-56', 'oceanography', '/ˌoʊʃəˈnɑːɡrəfi/', 'C1', 'hải dương học', 'n.', 'ocean (n.), oceanographer (n.), oceanographic (adj.), oceanic (adj.)', NULL, 'Đây là tên môn học, thường không đếm được; nhà hải dương học là oceanographer.', 'My cousin studies oceanography and collects seawater samples.', NULL, 'Anh họ tôi học ngành hải dương học và đi thu thập các mẫu nước biển.', '{"wordId":"oceanography","ukIpa":"/ˌəʊʃəˈnɒɡrəfi/","usIpa":"/ˌoʊʃəˈnɑːɡrəfi/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The scientific study of oceans and their physical and biological processes.","vi":"hải dương học"}],"examples":[{"en":"My cousin studies oceanography and collects seawater samples.","vi":"Anh họ tôi học ngành hải dương học và đi thu thập các mẫu nước biển.","audioKind":"ex"},{"en":"Research in oceanography helps scientists understand how ocean currents influence global temperatures and regional weather patterns.","vi":"Nghiên cứu hải dương học giúp các nhà khoa học hiểu được dòng hải lưu tác động thế nào đến nhiệt độ toàn cầu và các hình thái thời tiết khu vực.","audioKind":"ex2"}],"collocations":[{"en":"physical oceanography","vi":"hải dương học vật lý"},{"en":"biological oceanography","vi":"hải dương học sinh học"},{"en":"study oceanography","vi":"nghiên cứu hải dương học"}],"wordFamily":["ocean (n.)","oceanographer (n.)","oceanographic (adj.)","oceanic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đây là tên môn học, thường không đếm được; nhà hải dương học là oceanographer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gauge', 'en-c1-56', 'gauge', '/ɡeɪdʒ/', 'C1', 'đánh giá; phỏng đoán; đo lường; dụng cụ đo; máy đo; khổ (đường ray); khoảng rộng tiêu chuẩn', 'v.', NULL, 'Đồng nghĩa: assess, estimate, measure', 'Cách phát âm tương tự từ gage; có thể dùng để chỉ thiết bị đo vật lý hoặc đánh giá thông tin trừu tượng.', 'I dipped a toe in to gauge the water temperature.', NULL, 'Tôi nhúng một ngón chân xuống để thử nhiệt độ nước.', '{"wordId":"gauge","ukIpa":"/ɡeɪdʒ/","usIpa":"/ɡeɪdʒ/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To judge or measure the amount, level, or nature of something","vi":"đánh giá; phỏng đoán; đo lường"},{"pos":"n.","en":"An instrument that measures an amount, level, or pressure","vi":"dụng cụ đo; máy đo"},{"pos":"n.","en":"A standard width or thickness, especially between railway rails","vi":"khổ (đường ray); khoảng rộng tiêu chuẩn"}],"examples":[{"en":"I dipped a toe in to gauge the water temperature.","vi":"Tôi nhúng một ngón chân xuống để thử nhiệt độ nước.","audioKind":"ex"},{"en":"Governments often use household surveys to gauge public satisfaction with healthcare, education, and other essential services.","vi":"Chính phủ thường dùng các cuộc khảo sát hộ gia đình để đánh giá mức độ hài lòng của công chúng đối với dịch vụ y tế, giáo dục và các dịch vụ thiết yếu khác.","audioKind":"ex2"}],"collocations":[{"en":"gauge public opinion","vi":"đo lường dư luận"},{"en":"gauge the impact","vi":"đánh giá tác động"},{"en":"a pressure gauge","vi":"đồng hồ đo áp suất"},{"en":"a fuel gauge","vi":"thước đo nhiên liệu"}],"wordFamily":[],"synonyms":["assess","estimate","measure"],"antonyms":[],"tipVi":"Cách phát âm tương tự từ gage; có thể dùng để chỉ thiết bị đo vật lý hoặc đánh giá thông tin trừu tượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_permeate', 'en-c1-56', 'permeate', '/ˈpɝːmieɪt/', 'C1', 'lan tỏa; thấm đượm; thấm qua; len lỏi', 'v.', 'permeation (n.), permeable (adj.), impermeable (adj.), permeability (n.)', 'Đồng nghĩa: pervade, penetrate', 'Có thể kết hợp trực tiếp với tân ngữ; mùi hương lan tỏa trong phòng không cần dùng thêm giới từ.', 'The smell of fresh bread permeated the entire house.', NULL, 'Hương thơm của bánh mì mới nướng lan tỏa khắp ngôi nhà.', '{"wordId":"permeate","ukIpa":"/ˈpɜːmieɪt/","usIpa":"/ˈpɝːmieɪt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"Spread throughout a place, group, or situation.","vi":"lan tỏa; thấm đượm"},{"pos":"v.","en":"Pass into or through the tiny spaces in a material.","vi":"thấm qua; len lỏi"}],"examples":[{"en":"The smell of fresh bread permeated the entire house.","vi":"Hương thơm của bánh mì mới nướng lan tỏa khắp ngôi nhà.","audioKind":"ex"},{"en":"Digital technology now permeates almost every aspect of education, changing how students access information and collaborate with others.","vi":"Công nghệ số giờ đây đã thấm sâu vào mọi ngõ ngách của giáo dục, làm thay đổi cách học sinh tiếp cận tri thức và tương tác với những người khác.","audioKind":"ex2"}],"collocations":[{"en":"permeate society","vi":"lan tỏa khắp xã hội"},{"en":"permeate every aspect of","vi":"thấm đượm mọi khía cạnh của"},{"en":"permeate through","vi":"thấm qua"}],"wordFamily":["permeation (n.)","permeable (adj.)","impermeable (adj.)","permeability (n.)"],"synonyms":["pervade","penetrate"],"antonyms":[],"tipVi":"Có thể kết hợp trực tiếp với tân ngữ; mùi hương lan tỏa trong phòng không cần dùng thêm giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uniformly', 'en-c1-56', 'uniformly', '/ˈjuːnɪfɔːrmli/', 'C1', 'đồng đều; đều đặn; đồng nhất; một cách toàn diện; không ngoại lệ', 'adv.', 'uniform (adj.), uniformity (n.)', 'Đồng nghĩa: evenly, consistently · Trái nghĩa: unevenly, inconsistently', 'Nhấn mạnh tính đồng nhất ở mọi vị trí hoặc mọi trường hợp, không chỉ đơn thuần là sự thường xuyên theo thời gian.', 'Spread the butter uniformly across the warm bread.', NULL, 'Phết bơ đều khắp lên miếng bánh mì còn ấm.', '{"wordId":"uniformly","ukIpa":"/ˈjuːnɪfɔːmli/","usIpa":"/ˈjuːnɪfɔːrmli/","cefr":"C1","topic":"science","senses":[{"pos":"adv.","en":"equally or in the same way throughout","vi":"đồng đều; đều đặn"},{"pos":"adv.","en":"in every case, without any exceptions","vi":"đồng nhất; một cách toàn diện; không ngoại lệ"}],"examples":[{"en":"Spread the butter uniformly across the warm bread.","vi":"Phết bơ đều khắp lên miếng bánh mì còn ấm.","audioKind":"ex"},{"en":"Environmental regulations must be applied uniformly to all companies to ensure fair competition.","vi":"Các quy định về môi trường phải được áp dụng đồng nhất cho mọi doanh nghiệp để đảm bảo cạnh tranh công bằng.","audioKind":"ex2"}],"collocations":[{"en":"uniformly distributed","vi":"được phân bổ đồng đều"},{"en":"apply uniformly","vi":"áp dụng đồng nhất"},{"en":"uniformly high","vi":"cao đồng đều"}],"wordFamily":["uniform (adj.)","uniformity (n.)"],"synonyms":["evenly","consistently"],"antonyms":["unevenly","inconsistently"],"tipVi":"Nhấn mạnh tính đồng nhất ở mọi vị trí hoặc mọi trường hợp, không chỉ đơn thuần là sự thường xuyên theo thời gian.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reproduction', 'en-c1-56', 'reproduction', '/ˌriːprəˈdʌkʃən/', 'C1', 'sự sinh sản; sự nhân giống; sự sao chép; sự tái tạo (âm thanh, hình ảnh); bản sao; bản in lại', 'n.', 'reproduce (v.), reproductive (adj.)', NULL, 'Khi chỉ quá trình sinh sản hoặc sao chép thì không đếm được; khi chỉ một vật phẩm sao chép cụ thể thì đếm được.', 'We watched a documentary about reproduction in sea turtles.', NULL, 'Chúng tôi đã xem một bộ phim tài liệu về quá trình sinh sản của loài rùa biển.', '{"wordId":"reproduction","ukIpa":"/ˌriːprəˈdʌkʃən/","usIpa":"/ˌriːprəˈdʌkʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The process by which living things produce young.","vi":"sự sinh sản; sự nhân giống"},{"pos":"n.","en":"The process of copying an image, sound, or other material.","vi":"sự sao chép; sự tái tạo (âm thanh, hình ảnh)"},{"pos":"n.","en":"A copy of an original object or artwork.","vi":"bản sao; bản in lại"}],"examples":[{"en":"We watched a documentary about reproduction in sea turtles.","vi":"Chúng tôi đã xem một bộ phim tài liệu về quá trình sinh sản của loài rùa biển.","audioKind":"ex"},{"en":"Rising ocean temperatures may disrupt reproduction in marine species, threatening the long-term stability of coastal ecosystems.","vi":"Nhiệt độ nước biển tăng cao có thể phá vỡ quá trình sinh sản của các loài sinh vật biển, đe dọa sự ổn định lâu dài của các hệ sinh thái ven bờ.","audioKind":"ex2"}],"collocations":[{"en":"sexual reproduction","vi":"sinh sản hữu tính"},{"en":"asexual reproduction","vi":"sinh sản vô tính"},{"en":"sound reproduction","vi":"sự tái tạo âm thanh"},{"en":"a reproduction of a painting","vi":"một bản sao của bức tranh"}],"wordFamily":["reproduce (v.)","reproductive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ quá trình sinh sản hoặc sao chép thì không đếm được; khi chỉ một vật phẩm sao chép cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_56_1', 'en-c1-56', 'Cách dùng “rigorous” (adj.) — nghiêm ngặt; kỹ lưỡng; chặt chẽ', 'rigorous testing  ·  rigorous analysis  ·  rigorous training', 'Trong nghiên cứu hoặc thử nghiệm, từ này nhấn mạnh tính khắt khe và kỹ lưỡng; khi áp dụng cho huấn luyện hoặc tiêu chuẩn, nó nhấn mạnh sự nghiêm ngặt.', 'Họ từ (Word Family): rigorously (adv.), rigour (n.) | Đồng nghĩa: thorough, strict, exacting · Trái nghĩa: lax', '[{"hanzi":"The mechanic gave our car a rigorous safety check.","pinyin":"","meaning":"Thợ máy đã tiến hành kiểm tra an toàn kỹ lưỡng cho chiếc xe của chúng tôi."},{"hanzi":"New medical treatments require rigorous testing before they can be widely used in public healthcare.","pinyin":"","meaning":"Các phương pháp điều trị y tế mới đòi hỏi phải được kiểm định nghiêm ngặt trước khi có thể áp dụng rộng rãi trong y tế công cộng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_56_2', 'en-c1-56', 'Cách dùng “reactor” (n.) — lò phản ứng hạt nhân', 'nuclear reactor  ·  reactor core  ·  chemical reactor', 'Trong chủ đề năng lượng thường chỉ lò phản ứng hạt nhân; trong công nghiệp hóa chất cũng dùng để chỉ thiết bị phản ứng.', 'Họ từ (Word Family): react (v.), reaction (n.), reactive (adj.)', '[{"hanzi":"Our guide showed us a model of a nuclear reactor.","pinyin":"","meaning":"Hướng dẫn viên cho chúng tôi xem mô hình của một lò phản ứng hạt nhân."},{"hanzi":"Modern reactor designs aim to improve safety while supplying reliable electricity with low carbon emissions.","pinyin":"","meaning":"Các thiết kế lò phản ứng hiện đại nhằm mục đích nâng cao độ an toàn đồng thời cung cấp điện năng ổn định với mức phát thải carbon thấp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_56_3', 'en-c1-56', 'Cách dùng “uniformly” (adv.) — đồng đều; đều đặn', 'uniformly distributed  ·  apply uniformly  ·  uniformly high', 'Nhấn mạnh tính đồng nhất ở mọi vị trí hoặc mọi trường hợp, không chỉ đơn thuần là sự thường xuyên theo thời gian.', 'Họ từ (Word Family): uniform (adj.), uniformity (n.) | Đồng nghĩa: evenly, consistently · Trái nghĩa: unevenly, inconsistently', '[{"hanzi":"Spread the butter uniformly across the warm bread.","pinyin":"","meaning":"Phết bơ đều khắp lên miếng bánh mì còn ấm."},{"hanzi":"Environmental regulations must be applied uniformly to all companies to ensure fair competition.","pinyin":"","meaning":"Các quy định về môi trường phải được áp dụng đồng nhất cho mọi doanh nghiệp để đảm bảo cạnh tranh công bằng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_56_4', 'en-c1-56', 'Cách dùng “reproduction” (n.) — sự sinh sản; sự nhân giống', 'sexual reproduction  ·  asexual reproduction  ·  sound reproduction', 'Khi chỉ quá trình sinh sản hoặc sao chép thì không đếm được; khi chỉ một vật phẩm sao chép cụ thể thì đếm được.', 'Họ từ (Word Family): reproduce (v.), reproductive (adj.)', '[{"hanzi":"We watched a documentary about reproduction in sea turtles.","pinyin":"","meaning":"Chúng tôi đã xem một bộ phim tài liệu về quá trình sinh sản của loài rùa biển."},{"hanzi":"Rising ocean temperatures may disrupt reproduction in marine species, threatening the long-term stability of coastal ecosystems.","pinyin":"","meaning":"Nhiệt độ nước biển tăng cao có thể phá vỡ quá trình sinh sản của các loài sinh vật biển, đe dọa sự ổn định lâu dài của các hệ sinh thái ven bờ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_56_1', 'en-c1-56', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_1_1', 'ten_c1_56_1', 'magnitude', 'We only realised the magnitude of the damage at sunrise.', 'We only realised the magnitude of the damage at sunrise.', '/ˈmæɡnɪtuːd/', 'Chúng tôi chỉ nhận ra mức độ nghiêm trọng của thiệt hại khi trời sáng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_1_2', 'ten_c1_56_1', 'latitude', 'Our geography teacher showed us latitude on a globe.', 'Our geography teacher showed us latitude on a globe.', '/ˈlætɪtuːd/', 'Giáo viên địa lý đã chỉ cho chúng tôi xem vĩ độ trên quả địa cầu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_1_3', 'ten_c1_56_1', 'spatial', 'Building with blocks helps children develop their spatial awareness.', 'Building with blocks helps children develop their spatial awareness.', '/ˈspeɪʃəl/', 'Việc chơi xếp hình giúp trẻ em phát triển nhận thức không gian.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_1_4', 'ten_c1_56_1', 'composite', 'Our new garden bench is made from composite material.', 'Our new garden bench is made from composite material.', '/kəmˈpɑːzɪt/', 'Ghế dài trong vườn của chúng tôi được làm bằng vật liệu composite.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_1_5', 'ten_c1_56_1', 'metallic', 'The metallic frame makes this chair surprisingly heavy.', 'The metallic frame makes this chair surprisingly heavy.', '/məˈtælɪk/', 'Khung kim loại làm cho chiếc ghế này nặng một cách đáng ngạc nhiên.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_1_6', 'ten_c1_56_1', 'spiral', 'The orange peel fell in a spiral onto the plate.', 'The orange peel fell in a spiral onto the plate.', '/ˈspaɪrəl/', 'Vỏ quả cam rơi xuống đĩa theo hình xoắn ốc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_1_7', 'ten_c1_56_1', 'diffuse', 'The scent of fresh bread diffused through the kitchen.', 'The scent of fresh bread diffused through the kitchen.', '/dɪˈfjuːz/', 'Hương thơm của bánh mì mới nướng lan tỏa khắp căn bếp.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_1_8', 'ten_c1_56_1', 'cellular', 'Our teacher showed us cellular structures through a microscope.', 'Our teacher showed us cellular structures through a microscope.', '/ˈseljələr/', 'Giáo viên của chúng tôi cho chúng tôi xem các cấu trúc tế bào qua kính hiển vi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_56_1_1', 'en-c1-56', 'ten_c1_56_1', 'listening', 'listening', 'We only realised the magnitude of the damage at sunrise.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi chỉ nhận ra mức độ nghiêm trọng của thiệt hại khi trời sáng.","Chúng tôi đã xem một bộ phim tài liệu về quá trình sinh sản của loài rùa biển.","Giáo viên địa lý đã chỉ cho chúng tôi xem vĩ độ trên quả địa cầu.","Huấn luyện viên của chúng tôi sử dụng dữ liệu định lượng để theo dõi sự tiến bộ của chúng tôi."]'::jsonb, 0, 'We only realised the magnitude of the damage at sunrise. → Chúng tôi chỉ nhận ra mức độ nghiêm trọng của thiệt hại khi trời sáng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_56_1_2', 'en-c1-56', 'ten_c1_56_1', 'listening', 'listening', 'Our geography teacher showed us latitude on a globe.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi nhúng một ngón chân xuống để thử nhiệt độ nước.","Anh họ tôi học ngành hải dương học và đi thu thập các mẫu nước biển.","Ghế dài trong vườn của chúng tôi được làm bằng vật liệu composite.","Giáo viên địa lý đã chỉ cho chúng tôi xem vĩ độ trên quả địa cầu."]'::jsonb, 3, 'Our geography teacher showed us latitude on a globe. → Giáo viên địa lý đã chỉ cho chúng tôi xem vĩ độ trên quả địa cầu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_56_1_3', 'en-c1-56', 'ten_c1_56_1', 'listening', 'listening', 'Building with blocks helps children develop their spatial awareness.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đoạn phim từ camera đã cung cấp bằng chứng xác thực về những gì đã xảy ra.","Huấn luyện viên của chúng tôi sử dụng dữ liệu định lượng để theo dõi sự tiến bộ của chúng tôi.","Những hạt bí ngô này chứa kẽm và là một món ăn vặt ngon miệng.","Việc chơi xếp hình giúp trẻ em phát triển nhận thức không gian."]'::jsonb, 3, 'Building with blocks helps children develop their spatial awareness. → Việc chơi xếp hình giúp trẻ em phát triển nhận thức không gian.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_56_2', 'en-c1-56', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_2_1', 'ten_c1_56_2', 'magnitude', 'The magnitude of global food waste highlights the need for better storage systems and more responsible consumption.', 'The magnitude of global food waste highlights the need for better storage systems and more responsible consumption.', '/ˈmæɡnɪtuːd/', 'Quy mô lớn của tình trạng lãng phí thực phẩm toàn cầu làm nổi bật sự cần thiết của các hệ thống bảo quản tốt hơn và tiêu dùng có trách nhiệm hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_2_2', 'ten_c1_56_2', 'latitude', 'Regions at higher latitudes generally experience greater seasonal variations in daylight than those near the equator.', 'Regions at higher latitudes generally experience greater seasonal variations in daylight than those near the equator.', '/ˈlætɪtuːd/', 'Các vùng ở vĩ độ cao thường trải qua sự biến động theo mùa về thời gian ban ngày lớn hơn so với những vùng gần xích đạo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_2_3', 'ten_c1_56_2', 'spatial', 'Urban planners examine the spatial distribution of housing to ensure residents can access essential services.', 'Urban planners examine the spatial distribution of housing to ensure residents can access essential services.', '/ˈspeɪʃəl/', 'Các nhà quy hoạch đô thị nghiên cứu sự phân bố không gian của nhà ở để đảm bảo cư dân có thể tiếp cận các dịch vụ thiết yếu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_2_4', 'ten_c1_56_2', 'composite', 'Lightweight composite materials can reduce fuel consumption by making aircraft lighter without significantly compromising their strength.', 'Lightweight composite materials can reduce fuel consumption by making aircraft lighter without significantly compromising their strength.', '/kəmˈpɑːzɪt/', 'Vật liệu composite trọng lượng nhẹ có thể giúp giảm tiêu thụ nhiên liệu bằng cách làm cho máy bay nhẹ hơn mà không làm giảm đáng kể độ bền của chúng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_2_5', 'ten_c1_56_2', 'metallic', 'Metallic components can often be recovered from discarded electronics, reducing the need to extract new raw materials.', 'Metallic components can often be recovered from discarded electronics, reducing the need to extract new raw materials.', '/məˈtælɪk/', 'Các linh kiện kim loại thường có thể được thu hồi từ đồ điện tử bị vứt bỏ, làm giảm nhu cầu khai thác nguyên liệu thô mới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_56_2_6', 'ten_c1_56_2', 'spiral', 'Without adequate housing policies, rental costs may spiral beyond the reach of many low-income families.', 'Without adequate housing policies, rental costs may spiral beyond the reach of many low-income families.', '/ˈspaɪrəl/', 'Nếu thiếu các chính sách nhà ở thích hợp, chi phí thuê nhà có thể tăng vọt vượt quá tầm với của nhiều gia đình thu nhập thấp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_56_2_1', 'en-c1-56', 'ten_c1_56_2', 'listening', 'listening', 'The magnitude of global food waste highlights the need for better storage systems and more responsible consumption.', NULL, 'Trong câu vừa nghe, từ “magnitude” mang nghĩa nào sau đây?', '["sự hạn chế; yếu tố hạn chế","con ngêu; con sò; con trai","tầm vóc; quy mô lớn; tầm quan trọng","giáo dục nhà học đường; việc học tập tại trường"]'::jsonb, 2, '“magnitude” (/ˈmæɡnɪtuːd/): tầm vóc; quy mô lớn; tầm quan trọng. Câu đầy đủ: The magnitude of global food waste highlights the need for better storage systems and more responsible consumption.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_56_2_2', 'en-c1-56', 'ten_c1_56_2', 'listening', 'listening', 'Regions at higher latitudes generally experience greater seasonal variations in daylight than those near the equator.', NULL, 'Trong câu vừa nghe, từ “latitude” mang nghĩa nào sau đây?', '["nam tước","vuông góc; tạo với một đường thẳng hoặc bề mặt khác một góc vuông","người cuồng nhiệt; tín đồ (của một hoạt động, sở thích)","vĩ độ"]'::jsonb, 3, '“latitude” (/ˈlætɪtuːd/): vĩ độ. Câu đầy đủ: Regions at higher latitudes generally experience greater seasonal variations in daylight than those near the equator.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
