INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_2', 'en-c1-56', NULL, 'comprehensive_test', 'listening', 'Our geography teacher showed us latitude on a globe.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giáo viên địa lý đã chỉ cho chúng tôi xem vĩ độ trên quả địa cầu.","Giáo viên của chúng tôi cho chúng tôi xem các cấu trúc tế bào qua kính hiển vi.","Hướng dẫn viên cho chúng tôi xem mô hình của một lò phản ứng hạt nhân.","Việc chơi xếp hình giúp trẻ em phát triển nhận thức không gian."]'::jsonb, 0, 'Our geography teacher showed us latitude on a globe. → Giáo viên địa lý đã chỉ cho chúng tôi xem vĩ độ trên quả địa cầu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_3', 'en-c1-56', NULL, 'comprehensive_test', 'listening', 'spatial', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tính dễ bị tổn thương; tính dễ bị tác động","thuộc về không gian","nhà khí tượng học; chuyên gia khí tượng","hung dữ; dữ tợn"]'::jsonb, 1, 'spatial (/ˈspeɪʃəl/) → thuộc về không gian', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_4', 'en-c1-56', NULL, 'comprehensive_test', 'listening', 'Our new garden bench is made from composite material.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ghế dài trong vườn của chúng tôi được làm bằng vật liệu composite.","Giáo viên của chúng tôi cho chúng tôi xem các cấu trúc tế bào qua kính hiển vi.","Huấn luyện viên của chúng tôi sử dụng dữ liệu định lượng để theo dõi sự tiến bộ của chúng tôi.","Vỏ quả cam rơi xuống đĩa theo hình xoắn ốc."]'::jsonb, 0, 'Our new garden bench is made from composite material. → Ghế dài trong vườn của chúng tôi được làm bằng vật liệu composite.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_5', 'en-c1-56', NULL, 'comprehensive_test', 'listening', 'metallic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["gây nguy hiểm; làm tổn hại","bằng kim loại; chứa kim loại","chấm dứt; kết thúc","làm cho sinh động; làm cho sôi nổi"]'::jsonb, 1, 'metallic (/məˈtælɪk/) → bằng kim loại; chứa kim loại; có tính chất kim loại; có ánh, âm thanh hoặc vị như kim loại', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_6', 'en-c1-56', NULL, 'comprehensive_test', 'listening', 'The orange peel fell in a spiral onto the plate.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những câu chuyện chưa được kiểm chứng lan truyền rất nhanh khi mọi người chia sẻ chúng trên mạng.","Những hạt bí ngô này chứa kẽm và là một món ăn vặt ngon miệng.","Những hạt đường nhỏ kêu lạo xạo dưới hàm răng tôi.","Vỏ quả cam rơi xuống đĩa theo hình xoắn ốc."]'::jsonb, 3, 'The orange peel fell in a spiral onto the plate. → Vỏ quả cam rơi xuống đĩa theo hình xoắn ốc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_7', 'en-c1-56', NULL, 'comprehensive_test', 'listening', 'diffuse', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khuếch tán; lan tỏa; làm tán xạ","kiếm được; thu được; mua sắm","phấn khởi; vui sướng tột độ","ám ảnh; bận tâm quá mức; khó dứt ra được"]'::jsonb, 0, 'diffuse (/dɪˈfjuːz/) → khuếch tán; lan tỏa; làm tán xạ; tản mác; lan rộng; dài dòng; lan man', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_8', 'en-c1-56', NULL, 'comprehensive_test', 'listening', 'Our teacher showed us cellular structures through a microscope.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giáo viên của chúng tôi cho chúng tôi xem các cấu trúc tế bào qua kính hiển vi.","Những hạt bí ngô này chứa kẽm và là một món ăn vặt ngon miệng.","Anh họ tôi học ngành hải dương học và đi thu thập các mẫu nước biển.","Thợ máy đã tiến hành kiểm tra an toàn kỹ lưỡng cho chiếc xe của chúng tôi."]'::jsonb, 0, 'Our teacher showed us cellular structures through a microscope. → Giáo viên của chúng tôi cho chúng tôi xem các cấu trúc tế bào qua kính hiển vi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
