INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_18', 'en-c1-56', NULL, 'comprehensive_test', 'reading', NULL, 'The magnitude of global food waste highlights the need for better storage systems and more responsible consumption.', 'Dựa vào câu trên, từ “magnitude” có nghĩa phù hợp nhất là gì?', '["tầm vóc; quy mô lớn; tầm quan trọng","quay vòng; xoay tít","rạng rỡ; dung mạo ngời ngời hạnh phúc","hàng hóa; vận chuyển hàng hóa"]'::jsonb, 0, 'magnitude: tầm vóc; quy mô lớn; tầm quan trọng; độ lớn (của trận động đất). Dịch cả câu: Quy mô lớn của tình trạng lãng phí thực phẩm toàn cầu làm nổi bật sự cần thiết của các hệ thống bảo quản tốt hơn và tiêu dùng có trách nhiệm hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_19', 'en-c1-56', NULL, 'comprehensive_test', 'reading', NULL, 'Regions at higher latitudes generally experience greater seasonal variations in daylight than those near the equator.', 'Dựa vào câu trên, từ “latitude” có nghĩa phù hợp nhất là gì?', '["vĩ độ","cân nhắc kỹ lưỡng; suy ngẫm; trầm ngâm","dễ bị ảnh hưởng, dễ bị tổn thương, dễ mắc bệnh","nổi giận đùng đùng; bực tức"]'::jsonb, 0, 'latitude: vĩ độ; sự tự do hành động; quyền tự quyết. Dịch cả câu: Các vùng ở vĩ độ cao thường trải qua sự biến động theo mùa về thời gian ban ngày lớn hơn so với những vùng gần xích đạo.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_20', 'en-c1-56', NULL, 'comprehensive_test', 'reading', NULL, 'Urban planners examine the spatial distribution of housing to ensure residents can access essential services.', 'Dựa vào câu trên, từ “spatial” có nghĩa phù hợp nhất là gì?', '["thuộc về không gian","làm cho phát bực; chọc tức; làm bực mình","quá lo lắng; hoảng loạn; không thể giữ được bình tĩnh","tiềm ẩn; ẩn giấu; tiềm tàng"]'::jsonb, 0, 'spatial: thuộc về không gian. Dịch cả câu: Các nhà quy hoạch đô thị nghiên cứu sự phân bố không gian của nhà ở để đảm bảo cư dân có thể tiếp cận các dịch vụ thiết yếu.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_21', 'en-c1-56', NULL, 'comprehensive_test', 'reading', NULL, 'Lightweight composite materials can reduce fuel consumption by making aircraft lighter without significantly compromising their strength.', 'Dựa vào câu trên, từ “composite” có nghĩa phù hợp nhất là gì?', '["hẻm núi sâu và hẹp","phức hợp; tổng hợp","người cư ngụ; người sử dụng; hành khách (trên xe)","lưu thanh cơ; máy hát đĩa cổ"]'::jsonb, 1, 'composite: phức hợp; tổng hợp; vật liệu tổng hợp; vật liệu composite. Dịch cả câu: Vật liệu composite trọng lượng nhẹ có thể giúp giảm tiêu thụ nhiên liệu bằng cách làm cho máy bay nhẹ hơn mà không làm giảm đáng kể độ bền của chúng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
