INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_56_24', 'en-c1-56', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự sinh sản; sự nhân giống”', '["registrar","reproduction","contradiction","reproach"]'::jsonb, 1, 'sự sinh sản; sự nhân giống → reproduction (/ˌriːprəˈdʌkʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-57', 'en', 'Bài 57: Khoa học & Nghiên cứu (4) - CEFR C1', 'CEFR C1', 'C1 · Khoa học', '26 từ vựng Tiếng Anh CEFR C1 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5057, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acceleration', 'en-c1-57', 'acceleration', '/əkˌseləˈreɪʃən/', 'C1', 'sự tăng tốc; sự đẩy nhanh; gia tốc', 'n.', 'accelerate (v.), accelerator (n.), deceleration (n.)', 'Trái nghĩa: deceleration', 'Trong vật lý, từ này chỉ tốc độ biến thiên của vận tốc, sự đổi hướng chuyển động cũng tạo ra gia tốc.', 'The car''s sudden acceleration pushed me against my seat.', NULL, 'Sự tăng tốc đột ngột của chiếc xe đẩy tôi ép sát vào lưng ghế.', '{"wordId":"acceleration","ukIpa":"/əkˌseləˈreɪʃən/","usIpa":"/əkˌseləˈreɪʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"the process of moving faster or happening more quickly","vi":"sự tăng tốc; sự đẩy nhanh"},{"pos":"n.","en":"the rate at which velocity changes over time","vi":"gia tốc"}],"examples":[{"en":"The car''s sudden acceleration pushed me against my seat.","vi":"Sự tăng tốc đột ngột của chiếc xe đẩy tôi ép sát vào lưng ghế.","audioKind":"ex"},{"en":"The acceleration of urban growth has increased demand for affordable housing and reliable public transport.","vi":"Sự gia tăng tốc độ phát triển đô thị đã làm tăng nhu cầu về nhà ở giá rẻ và phương tiện giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"rapid acceleration","vi":"tăng tốc nhanh"},{"en":"acceleration of growth","vi":"sự gia tốc của tăng trưởng"},{"en":"constant acceleration","vi":"gia tốc không đổi"}],"wordFamily":["accelerate (v.)","accelerator (n.)","deceleration (n.)"],"synonyms":[],"antonyms":["deceleration"],"tipVi":"Trong vật lý, từ này chỉ tốc độ biến thiên của vận tốc, sự đổi hướng chuyển động cũng tạo ra gia tốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extraction', 'en-c1-57', 'extraction', '/ɪkˈstrækʃən/', 'C1', 'sự chiết xuất; sự khai thác; sự nhổ (răng)', 'n.', 'extract (v.), extractor (n.)', 'Đồng nghĩa: removal', 'Extract là động từ; extraction chỉ quá trình tách hoặc rút ra, không mang nghĩa là bản tóm tắt.', 'The dentist explained why a tooth extraction was necessary.', NULL, 'Nha sĩ giải thích lý do tại sao việc nhổ răng là cần thiết.', '{"wordId":"extraction","ukIpa":"/ɪkˈstrækʃən/","usIpa":"/ɪkˈstrækʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The process of taking something out of something else.","vi":"sự chiết xuất; sự khai thác; sự nhổ (răng)"}],"examples":[{"en":"The dentist explained why a tooth extraction was necessary.","vi":"Nha sĩ giải thích lý do tại sao việc nhổ răng là cần thiết.","audioKind":"ex"},{"en":"The extraction of minerals can damage local ecosystems unless strict environmental safeguards are enforced.","vi":"Việc khai thác khoáng sản có thể tàn phá các hệ sinh thái địa phương trừ khi các biện pháp bảo vệ môi trường nghiêm ngặt được thực thi.","audioKind":"ex2"}],"collocations":[{"en":"mineral extraction","vi":"khai thác khoáng sản"},{"en":"tooth extraction","vi":"thủ thuật nhổ răng"},{"en":"oil extraction","vi":"khai thác dầu mỏ"},{"en":"data extraction","vi":"trích xuất dữ liệu"}],"wordFamily":["extract (v.)","extractor (n.)"],"synonyms":["removal"],"antonyms":[],"tipVi":"Extract là động từ; extraction chỉ quá trình tách hoặc rút ra, không mang nghĩa là bản tóm tắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_residue', 'en-c1-57', 'residue', '/ˈrezɪduː/', 'C1', 'chất cặn; phần dư; thặng dư', 'n.', 'residual (adj.)', 'Đồng nghĩa: remains, remnants', 'Thường chỉ chất còn sót lại sau một quá trình; có thể dùng dạng số nhiều cho các loại khác nhau.', 'The sticker left a sticky residue on the jar.', NULL, 'Miếng dán đã để lại một lớp cặn dính trên chiếc lọ.', '{"wordId":"residue","ukIpa":"/ˈrezɪdjuː/","usIpa":"/ˈrezɪduː/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A substance left behind after a process or removal.","vi":"chất cặn; phần dư; thặng dư"}],"examples":[{"en":"The sticker left a sticky residue on the jar.","vi":"Miếng dán đã để lại một lớp cặn dính trên chiếc lọ.","audioKind":"ex"},{"en":"Industrial processes can leave toxic residue in soil, creating long-term risks for nearby ecosystems and communities.","vi":"Các quy trình công nghiệp có thể để lại chất cặn độc hại trong đất, gây ra những rủi ro lâu dài cho các hệ sinh thái và cộng đồng xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"sticky residue","vi":"chất cặn dính"},{"en":"chemical residue","vi":"dư lượng hóa chất"},{"en":"pesticide residues","vi":"dư lượng thuốc trừ sâu"},{"en":"leave a residue","vi":"để lại cặn"}],"wordFamily":["residual (adj.)"],"synonyms":["remains","remnants"],"antonyms":[],"tipVi":"Thường chỉ chất còn sót lại sau một quá trình; có thể dùng dạng số nhiều cho các loại khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aerodynamics', 'en-c1-57', 'aerodynamics', '/ˌeroʊdaɪˈnæmɪks/', 'C1', 'khí động học; đặc tính khí động học', 'n.', 'aerodynamic (adj.), aerodynamically (adv.)', NULL, 'Khi chỉ một môn học, dù có tận cùng bằng s, nó thường đi với động từ số ít.', 'We explored aerodynamics by testing paper planes in the garden.', NULL, 'Chúng tôi đã tìm hiểu về khí động học bằng cách thử nghiệm máy bay giấy trong vườn.', '{"wordId":"aerodynamics","ukIpa":"/ˌeərəʊdaɪˈnæmɪks/","usIpa":"/ˌeroʊdaɪˈnæmɪks/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The study of air movement and its effects on objects.","vi":"khí động học"},{"pos":"n.","en":"The qualities affecting how efficiently an object moves through air.","vi":"đặc tính khí động học"}],"examples":[{"en":"We explored aerodynamics by testing paper planes in the garden.","vi":"Chúng tôi đã tìm hiểu về khí động học bằng cách thử nghiệm máy bay giấy trong vườn.","audioKind":"ex"},{"en":"Advances in aerodynamics allow aircraft manufacturers to reduce fuel consumption without significantly compromising passenger capacity or flight speed.","vi":"Những tiến bộ trong khí động học giúp các nhà sản xuất máy bay giảm mức tiêu thụ nhiên liệu mà không làm giảm đáng kể sức chứa hành khách hoặc tốc độ bay.","audioKind":"ex2"}],"collocations":[{"en":"the principles of aerodynamics","vi":"các nguyên lý khí động học"},{"en":"improve aerodynamics","vi":"cải thiện đặc tính khí động học"},{"en":"vehicle aerodynamics","vi":"khí động học của phương tiện"}],"wordFamily":["aerodynamic (adj.)","aerodynamically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ một môn học, dù có tận cùng bằng s, nó thường đi với động từ số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_denote', 'en-c1-57', 'denote', '/dɪˈnoʊt/', 'C1', 'biểu thị; chỉ rõ', 'v.', 'denotation (n.), denotative (adj.)', 'Đồng nghĩa: indicate, signify, represent', 'Thường được dùng cho các ký hiệu, màu sắc hoặc từ ngữ đại diện cho một ý nghĩa nào đó.', 'On this map, blue lines denote rivers and streams.', NULL, 'Trên bản đồ này, các đường màu xanh lam biểu thị sông và suối.', '{"wordId":"denote","ukIpa":"/dɪˈnəʊt/","usIpa":"/dɪˈnoʊt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To represent or indicate something.","vi":"biểu thị; chỉ rõ"}],"examples":[{"en":"On this map, blue lines denote rivers and streams.","vi":"Trên bản đồ này, các đường màu xanh lam biểu thị sông và suối.","audioKind":"ex"},{"en":"In scientific diagrams, different colours often denote distinct materials, allowing readers to interpret complex structures more easily.","vi":"Trong các sơ đồ khoa học, các màu sắc khác nhau thường biểu thị các vật liệu khác nhau, giúp người đọc diễn giải các cấu trúc phức tạp dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"denote a category","vi":"biểu thị một danh mục"},{"en":"denote a change","vi":"biểu thị sự thay đổi"},{"en":"be denoted by","vi":"được biểu thị bởi"}],"wordFamily":["denotation (n.)","denotative (adj.)"],"synonyms":["indicate","signify","represent"],"antonyms":[],"tipVi":"Thường được dùng cho các ký hiệu, màu sắc hoặc từ ngữ đại diện cho một ý nghĩa nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_corrode', 'en-c1-57', 'corrode', '/kəˈroʊd/', 'C1', 'làm ăn mòn; bị ăn mòn (hóa học); làm suy yếu dần; gặm nhấm (niềm tin, sự tin tưởng)', 'v.', 'corrosion (n.), corrosive (adj.)', 'Đồng nghĩa: eat away, erode', 'Có thể dùng như ngoại động từ hoặc nội động từ; rust chủ yếu dùng cho sắt bị gỉ sét.', 'Salt water has corroded the metal hinges on our gate.', NULL, 'Nước muối đã làm ăn mòn các bản lề kim loại trên cánh cổng nhà chúng tôi.', '{"wordId":"corrode","ukIpa":"/kəˈrəʊd/","usIpa":"/kəˈroʊd/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To gradually damage material chemically, or become damaged this way.","vi":"làm ăn mòn; bị ăn mòn (hóa học)"},{"pos":"v.","en":"To gradually weaken something such as trust or confidence.","vi":"làm suy yếu dần; gặm nhấm (niềm tin, sự tin tưởng)"}],"examples":[{"en":"Salt water has corroded the metal hinges on our gate.","vi":"Nước muối đã làm ăn mòn các bản lề kim loại trên cánh cổng nhà chúng tôi.","audioKind":"ex"},{"en":"A lack of transparency can corrode public trust in institutions and reduce participation in democratic processes.","vi":"Sự thiếu minh bạch có thể gặm nhấm niềm tin của công chúng vào các tổ chức và làm giảm tỷ lệ tham gia vào các tiến trình dân chủ.","audioKind":"ex2"}],"collocations":[{"en":"corrode metal","vi":"ăn mòn kim loại"},{"en":"corrode trust","vi":"gặm nhấm niềm tin"},{"en":"badly corroded pipes","vi":"đường ống bị ăn mòn nặng"}],"wordFamily":["corrosion (n.)","corrosive (adj.)"],"synonyms":["eat away","erode"],"antonyms":[],"tipVi":"Có thể dùng như ngoại động từ hoặc nội động từ; rust chủ yếu dùng cho sắt bị gỉ sét.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alloy', 'en-c1-57', 'alloy', '/ˈælɔɪ/', 'C1', 'hợp kim; làm thành hợp kim; pha hợp kim', 'n.', NULL, NULL, 'Danh từ nhấn trọng âm ở âm tiết đầu; động từ thường đọc là /əˈlɔɪ/.', 'This bicycle frame is made from a lightweight alloy.', NULL, 'Khung chiếc xe đạp này được làm từ một loại hợp kim nhẹ.', '{"wordId":"alloy","ukIpa":"/ˈælɔɪ/","usIpa":"/ˈælɔɪ/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A metal made by combining metals or adding other elements.","vi":"hợp kim"},{"pos":"v.","en":"To combine a metal with another element.","vi":"làm thành hợp kim; pha hợp kim"}],"examples":[{"en":"This bicycle frame is made from a lightweight alloy.","vi":"Khung chiếc xe đạp này được làm từ một loại hợp kim nhẹ.","audioKind":"ex"},{"en":"Engineers are developing stronger alloys to reduce vehicle weight and improve fuel efficiency.","vi":"Các kỹ sư đang phát triển các loại hợp kim bền hơn để giảm trọng lượng xe và nâng cao hiệu quả sử dụng nhiên liệu.","audioKind":"ex2"}],"collocations":[{"en":"aluminium alloy","vi":"hợp kim nhôm"},{"en":"lightweight alloy","vi":"hợp kim nhẹ"},{"en":"alloy steel","vi":"thép hợp kim"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ nhấn trọng âm ở âm tiết đầu; động từ thường đọc là /əˈlɔɪ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deformation', 'en-c1-57', 'deformation', '/ˌdiːfɔːrˈmeɪʃən/', 'C1', 'sự biến dạng; sự biến hình', 'n.', 'deform (v.), deformed (adj.), deformable (adj.)', 'Đồng nghĩa: distortion', 'Nhấn mạnh sự thay đổi hình dạng, không đồng nghĩa với hư hỏng chung chung như damage.', 'The heat caused visible deformation of the plastic lid.', NULL, 'Sức nóng đã làm cho chiếc nắp nhựa bị biến dạng rõ rệt.', '{"wordId":"deformation","ukIpa":"/ˌdiːfɔːˈmeɪʃən/","usIpa":"/ˌdiːfɔːrˈmeɪʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"a change in shape caused by pressure or other forces","vi":"sự biến dạng; sự biến hình"}],"examples":[{"en":"The heat caused visible deformation of the plastic lid.","vi":"Sức nóng đã làm cho chiếc nắp nhựa bị biến dạng rõ rệt.","audioKind":"ex"},{"en":"Engineers test building materials to assess their resistance to deformation under heavy loads and extreme temperatures.","vi":"Các kỹ sư kiểm tra vật liệu xây dựng để đánh giá khả năng chống biến dạng của chúng dưới tải trọng nặng và nhiệt độ khắc nghiệt.","audioKind":"ex2"}],"collocations":[{"en":"plastic deformation","vi":"biến dạng dẻo"},{"en":"elastic deformation","vi":"biến dạng đàn hồi"},{"en":"resistance to deformation","vi":"khả năng chống biến dạng"}],"wordFamily":["deform (v.)","deformed (adj.)","deformable (adj.)"],"synonyms":["distortion"],"antonyms":[],"tipVi":"Nhấn mạnh sự thay đổi hình dạng, không đồng nghĩa với hư hỏng chung chung như damage.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_penetration', 'en-c1-57', 'penetration', '/ˌpenɪˈtreɪʃən/', 'C1', 'sự xuyên qua; sự thâm nhập; mức độ thâm nhập thị trường; tỷ lệ phổ cập', 'n.', 'penetrate (v.), penetrating (adj.), penetrable (adj.), impenetrable (adj.)', NULL, 'Được phái sinh từ penetrate; thường dùng với giới từ of hoặc into.', 'These thick curtains reduce the penetration of sunlight.', NULL, 'Những chiếc rèm dày này làm giảm bớt ánh nắng chiếu vào.', '{"wordId":"penetration","ukIpa":"/ˌpenɪˈtreɪʃən/","usIpa":"/ˌpenɪˈtreɪʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The process of entering or passing through something.","vi":"sự xuyên qua; sự thâm nhập"},{"pos":"n.","en":"The extent to which a product reaches a market.","vi":"mức độ thâm nhập thị trường; tỷ lệ phổ cập"}],"examples":[{"en":"These thick curtains reduce the penetration of sunlight.","vi":"Những chiếc rèm dày này làm giảm bớt ánh nắng chiếu vào.","audioKind":"ex"},{"en":"Greater internet penetration in rural areas can improve access to education and support the growth of small businesses.","vi":"Tỷ lệ phổ cập internet cao hơn ở các vùng nông thôn có thể cải thiện khả năng tiếp cận giáo dục và hỗ trợ sự phát triển của các doanh nghiệp nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"water penetration","vi":"sự thấm nước"},{"en":"market penetration","vi":"độ thâm nhập thị trường"},{"en":"internet penetration","vi":"tỷ lệ phổ cập internet"}],"wordFamily":["penetrate (v.)","penetrating (adj.)","penetrable (adj.)","impenetrable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Được phái sinh từ penetrate; thường dùng với giới từ of hoặc into.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_magnify', 'en-c1-57', 'magnify', '/ˈmæɡnəfaɪ/', 'C1', 'làm phóng đại; phóng to; làm trầm trọng thêm; thổi phồng', 'v.', 'magnification (n.), magnifier (n.)', 'Đồng nghĩa: enlarge, exaggerate · Trái nghĩa: reduce', 'Có thể dùng để chỉ việc phóng đại hình ảnh qua thấu kính, hoặc phóng đại quy mô, mức độ nghiêm trọng của một vấn đề.', 'This lens magnifies tiny insects so we can examine them.', NULL, 'Thấu kính này giúp phóng to những con côn trùng nhỏ để chúng ta có thể quan sát chúng.', '{"wordId":"magnify","ukIpa":"/ˈmæɡnɪfaɪ/","usIpa":"/ˈmæɡnəfaɪ/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To make something appear larger, especially through a lens.","vi":"làm phóng đại; phóng to"},{"pos":"v.","en":"To make something seem more important or become more serious.","vi":"làm trầm trọng thêm; thổi phồng"}],"examples":[{"en":"This lens magnifies tiny insects so we can examine them.","vi":"Thấu kính này giúp phóng to những con côn trùng nhỏ để chúng ta có thể quan sát chúng.","audioKind":"ex"},{"en":"Social media can magnify public concerns by repeatedly exposing users to dramatic accounts of rare events.","vi":"Mạng xã hội có thể làm trầm trọng thêm mối lo ngại của công chúng bằng cách liên tục cho người dùng tiếp cận những bài viết giật gân về các sự kiện hiếm gặp.","audioKind":"ex2"}],"collocations":[{"en":"magnify an image","vi":"phóng đại một hình ảnh"},{"en":"magnify a problem","vi":"làm trầm trọng thêm một vấn đề"},{"en":"magnifying glass","vi":"kính lúp"}],"wordFamily":["magnification (n.)","magnifier (n.)"],"synonyms":["enlarge","exaggerate"],"antonyms":["reduce"],"tipVi":"Có thể dùng để chỉ việc phóng đại hình ảnh qua thấu kính, hoặc phóng đại quy mô, mức độ nghiêm trọng của một vấn đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_propagation', 'en-c1-57', 'propagation', '/ˌprɑːpəˈɡeɪʃən/', 'C1', 'sự nhân giống; sự sinh sản; sự truyền bá; sự lan truyền; sự truyền sóng; sự lan truyền tín hiệu', 'n.', 'propagate (v.), propagator (n.)', NULL, 'Thường là danh từ không đếm được; có thể dùng trong sinh học (nhân giống cây), truyền thông (thông tin) và vật lý (sóng).', 'Plant propagation is easier with healthy cuttings and clean tools.', NULL, 'Việc nhân giống cây trồng sẽ dễ dàng hơn nếu sử dụng các cành giâm khỏe mạnh và dụng cụ sạch sẽ.', '{"wordId":"propagation","ukIpa":"/ˌprɒpəˈɡeɪʃən/","usIpa":"/ˌprɑːpəˈɡeɪʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The production of new plants or other living organisms.","vi":"sự nhân giống; sự sinh sản"},{"pos":"n.","en":"The spreading of ideas, information, or beliefs.","vi":"sự truyền bá; sự lan truyền"},{"pos":"n.","en":"The movement of waves or signals through a medium.","vi":"sự truyền sóng; sự lan truyền tín hiệu"}],"examples":[{"en":"Plant propagation is easier with healthy cuttings and clean tools.","vi":"Việc nhân giống cây trồng sẽ dễ dàng hơn nếu sử dụng các cành giâm khỏe mạnh và dụng cụ sạch sẽ.","audioKind":"ex"},{"en":"The rapid propagation of misleading information online can undermine public trust in reliable scientific evidence.","vi":"Sự lan truyền nhanh chóng của thông tin sai lệch trên mạng có thể làm suy giảm niềm tin của công chúng vào các bằng chứng khoa học đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"plant propagation","vi":"nhân giống cây trồng"},{"en":"propagation by cuttings","vi":"nhân giống bằng cách giâm cành"},{"en":"wave propagation","vi":"sự truyền sóng"},{"en":"propagation of ideas","vi":"sự truyền bá tư tưởng"}],"wordFamily":["propagate (v.)","propagator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; có thể dùng trong sinh học (nhân giống cây), truyền thông (thông tin) và vật lý (sóng).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invert', 'en-c1-57', 'invert', '/ɪnˈvɜːrt/', 'C1', 'lật ngược; đảo chiều; đảo trật tự', 'v.', 'inversion (n.), inverted (adj.), inverter (n.)', 'Đồng nghĩa: reverse, overturn', 'Thường là ngoại động từ; tính từ chỉ trạng thái đảo ngược là inverted.', 'Invert the bowl carefully to release the jelly.', NULL, 'Cẩn thận lật ngược chiếc bát lại để lấy phần thạch ra.', '{"wordId":"invert","ukIpa":"/ɪnˈvɜːt/","usIpa":"/ɪnˈvɜːrt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To turn something upside down or reverse its order.","vi":"lật ngược; đảo chiều; đảo trật tự"}],"examples":[{"en":"Invert the bowl carefully to release the jelly.","vi":"Cẩn thận lật ngược chiếc bát lại để lấy phần thạch ra.","audioKind":"ex"},{"en":"Researchers can invert the usual teaching sequence by asking students to explore problems before receiving formal explanations.","vi":"Các nhà nghiên cứu có thể đảo ngược trình tự giảng dạy thông thường bằng cách yêu cầu học sinh khám phá các vấn đề trước khi nghe giải thích chính thức.","audioKind":"ex2"}],"collocations":[{"en":"invert a container","vi":"lật ngược vật chứa"},{"en":"invert the order","vi":"đảo ngược thứ tự"},{"en":"invert an image","vi":"lật ngược hình ảnh"}],"wordFamily":["inversion (n.)","inverted (adj.)","inverter (n.)"],"synonyms":["reverse","overturn"],"antonyms":[],"tipVi":"Thường là ngoại động từ; tính từ chỉ trạng thái đảo ngược là inverted.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_precipitate', 'en-c1-57', 'precipitate', '/prɪˈsɪpɪteɪt/', 'C1', 'làm cho xảy ra đột ngột; thúc đẩy; chất kết tủa; vội vã; thiếu suy nghĩ; hấp tấp', 'v.', 'precipitation (n.), precipitant (n.)', 'Đồng nghĩa: trigger, hasten', 'Động từ phát âm là /teɪt/, danh từ và tính từ phát âm là /tət/.', 'A broken pipe precipitated an emergency visit from the plumber.', NULL, 'Đường ống nước bị hỏng đã khiến thợ sửa ống nước phải đến khẩn cấp.', '{"wordId":"precipitate","ukIpa":"/prɪˈsɪpɪteɪt/","usIpa":"/prɪˈsɪpɪteɪt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To cause something to happen suddenly or sooner than expected.","vi":"làm cho xảy ra đột ngột; thúc đẩy"},{"pos":"n.","en":"A solid that forms in a liquid during a chemical reaction.","vi":"chất kết tủa"},{"pos":"adj.","en":"Done too quickly and without enough thought.","vi":"vội vã; thiếu suy nghĩ; hấp tấp"}],"examples":[{"en":"A broken pipe precipitated an emergency visit from the plumber.","vi":"Đường ống nước bị hỏng đã khiến thợ sửa ống nước phải đến khẩn cấp.","audioKind":"ex"},{"en":"A sharp increase in food prices could precipitate a wider economic crisis in vulnerable regions.","vi":"Sự gia tăng mạnh mẽ về giá lương thực có thể châm ngòi cho một cuộc khủng hoảng kinh tế lớn hơn ở các khu vực dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"precipitate a crisis","vi":"gây ra khủng hoảng"},{"en":"precipitate change","vi":"thúc đẩy sự thay đổi"},{"en":"form a precipitate","vi":"tạo ra kết tủa"},{"en":"precipitate action","vi":"hành động hấp tấp"}],"wordFamily":["precipitation (n.)","precipitant (n.)"],"synonyms":["trigger","hasten"],"antonyms":[],"tipVi":"Động từ phát âm là /teɪt/, danh từ và tính từ phát âm là /tət/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anatomy', 'en-c1-57', 'anatomy', '/əˈnætəmi/', 'C1', 'giải phẫu học; cấu trúc cơ thể', 'n.', 'anatomical (adj.), anatomically (adv.), anatomist (n.)', NULL, 'anatomy thiên về cấu trúc cơ thể, trong khi physiology thiên về chức năng sinh lý.', 'We studied anatomy using a plastic model of the heart.', NULL, 'Chúng tôi học môn giải phẫu học bằng một mô hình trái tim bằng nhựa.', '{"wordId":"anatomy","ukIpa":"/əˈnætəmi/","usIpa":"/əˈnætəmi/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"the scientific study of the structure of living bodies","vi":"giải phẫu học"},{"pos":"n.","en":"the physical structure of a human, animal, or plant","vi":"cấu trúc cơ thể"}],"examples":[{"en":"We studied anatomy using a plastic model of the heart.","vi":"Chúng tôi học môn giải phẫu học bằng một mô hình trái tim bằng nhựa.","audioKind":"ex"},{"en":"A thorough knowledge of human anatomy helps medical students understand how injuries affect movement.","vi":"Hiểu biết thấu đáo về giải phẫu cơ thể người giúp sinh viên y khoa hiểu được các tổn thương ảnh hưởng như thế nào đến khả năng vận động.","audioKind":"ex2"}],"collocations":[{"en":"human anatomy","vi":"giải phẫu học cơ thể người"},{"en":"study anatomy","vi":"nghiên cứu giải phẫu"},{"en":"comparative anatomy","vi":"giải phẫu học so sánh"}],"wordFamily":["anatomical (adj.)","anatomically (adv.)","anatomist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"anatomy thiên về cấu trúc cơ thể, trong khi physiology thiên về chức năng sinh lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_probe', 'en-c1-57', 'probe', '/proʊb/', 'C1', 'dò tìm; khảo sát; điều tra sâu; cuộc điều tra chi tiết; cây dò; đầu dò; tàu thăm dò', 'v.', 'probing (adj.)', 'Đồng nghĩa: investigate, examine, explore', 'Động từ có thể đi thẳng với đối tượng điều tra hoặc dùng với probe into.', 'The electrician probed behind the wall for damaged wires.', NULL, 'Thợ điện đã dò tìm phía sau bức tường để tìm những sợi dây điện bị hỏng.', '{"wordId":"probe","ukIpa":"/prəʊb/","usIpa":"/proʊb/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To examine something closely to discover hidden information.","vi":"dò tìm; khảo sát; điều tra sâu"},{"pos":"n.","en":"A detailed investigation into a problem or suspected wrongdoing.","vi":"cuộc điều tra chi tiết"},{"pos":"n.","en":"An instrument or spacecraft used to examine or explore something.","vi":"cây dò; đầu dò; tàu thăm dò"}],"examples":[{"en":"The electrician probed behind the wall for damaged wires.","vi":"Thợ điện đã dò tìm phía sau bức tường để tìm những sợi dây điện bị hỏng.","audioKind":"ex"},{"en":"Independent investigators should probe the causes of industrial accidents to prevent similar incidents in the future.","vi":"Các điều tra viên độc lập nên tiến hành điều tra sâu các nguyên nhân dẫn đến tai nạn công nghiệp nhằm ngăn ngừa những sự cố tương tự trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"probe into","vi":"điều tra sâu về"},{"en":"launch a probe","vi":"mở cuộc điều tra"},{"en":"space probe","vi":"tên lửa thăm dò không gian"},{"en":"a medical probe","vi":"đầu dò y tế"}],"wordFamily":["probing (adj.)"],"synonyms":["investigate","examine","explore"],"antonyms":[],"tipVi":"Động từ có thể đi thẳng với đối tượng điều tra hoặc dùng với probe into.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proportional', 'en-c1-57', 'proportional', '/prəˈpɔːrʃənəl/', 'C1', 'tương ứng; có tỉ lệ thuận; cân đối; thích hợp', 'adj.', 'proportion (n.), proportionally (adv.), disproportionate (adj.), proportionality (n.)', 'Đồng nghĩa: proportionate · Trái nghĩa: disproportionate', 'Thường đi với giới từ to; cụm "tỷ lệ thuận" dùng là directly proportional to.', 'The delivery fee is proportional to the parcel''s weight.', NULL, 'Phí giao hàng sẽ tương ứng với trọng lượng của bưu kiện.', '{"wordId":"proportional","ukIpa":"/prəˈpɔːʃənəl/","usIpa":"/prəˈpɔːrʃənəl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"changing in a constant ratio to another quantity","vi":"tương ứng; có tỉ lệ thuận"},{"pos":"adj.","en":"appropriate in size or degree compared with something else","vi":"cân đối; thích hợp"}],"examples":[{"en":"The delivery fee is proportional to the parcel''s weight.","vi":"Phí giao hàng sẽ tương ứng với trọng lượng của bưu kiện.","audioKind":"ex"},{"en":"Environmental taxes should be proportional to the damage caused, encouraging businesses to adopt cleaner production methods.","vi":"Thuế môi trường cần phải tương xứng với mức độ tổn hại gây ra, qua đó khuyến khích các doanh nghiệp áp dụng các phương thức sản xuất sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"directly proportional to","vi":"tỷ lệ thuận với"},{"en":"inversely proportional to","vi":"tỷ lệ nghịch với"},{"en":"proportional representation","vi":"chế độ đại diện theo tỷ lệ"}],"wordFamily":["proportion (n.)","proportionally (adv.)","disproportionate (adj.)","proportionality (n.)"],"synonyms":["proportionate"],"antonyms":["disproportionate"],"tipVi":"Thường đi với giới từ to; cụm \"tỷ lệ thuận\" dùng là directly proportional to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inorganic', 'en-c1-57', 'inorganic', '/ˌɪnɔːrˈɡænɪk/', 'C1', 'vô cơ', 'adj.', 'organic (adj.), inorganically (adv.)', 'Trái nghĩa: organic', 'Chất vô cơ không có nghĩa là hoàn toàn không chứa carbon, ví dụ khí CO2 cũng là chất vô cơ.', 'Today we examined inorganic compounds, including salt, in science class.', NULL, 'Hôm nay chúng tôi đã nghiên cứu các hợp chất vô cơ, bao gồm cả muối, trong giờ học khoa học.', '{"wordId":"inorganic","ukIpa":"/ˌɪnɔːˈɡænɪk/","usIpa":"/ˌɪnɔːrˈɡænɪk/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"relating to substances generally without carbon bonded to hydrogen","vi":"vô cơ"}],"examples":[{"en":"Today we examined inorganic compounds, including salt, in science class.","vi":"Hôm nay chúng tôi đã nghiên cứu các hợp chất vô cơ, bao gồm cả muối, trong giờ học khoa học.","audioKind":"ex"},{"en":"Excessive use of inorganic fertilisers can damage soil quality and contribute to pollution in nearby rivers.","vi":"Việc lạm dụng phân bón vô cơ có thể làm giảm chất lượng đất và gây ô nhiễm các dòng sông gần đó.","audioKind":"ex2"}],"collocations":[{"en":"inorganic chemistry","vi":"hóa học vô cơ"},{"en":"inorganic compounds","vi":"hợp chất vô cơ"},{"en":"inorganic fertilisers","vi":"phân bón vô cơ"},{"en":"inorganic matter","vi":"chất vô cơ"}],"wordFamily":["organic (adj.)","inorganically (adv.)"],"synonyms":[],"antonyms":["organic"],"tipVi":"Chất vô cơ không có nghĩa là hoàn toàn không chứa carbon, ví dụ khí CO2 cũng là chất vô cơ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forensic', 'en-c1-57', 'forensic', '/fəˈrensɪk/', 'C1', 'thuộc về pháp y; thuộc về giám định tư pháp; xem xét chi tiết với độ chính xác và cẩn trọng cao', 'adj.', 'forensically (adv.), forensics (n.)', NULL, 'forensic thường đóng vai trò tính từ; danh từ chỉ môn học thường dùng forensics.', 'The forensic team carefully examined fingerprints on the window.', NULL, 'Đội ngũ giám định pháp y đã kiểm tra kỹ lưỡng các dấu vân tay trên cửa sổ.', '{"wordId":"forensic","ukIpa":"/fəˈrensɪk/","usIpa":"/fəˈrensɪk/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"relating to scientific methods used to investigate crime","vi":"thuộc về pháp y; thuộc về giám định tư pháp"},{"pos":"adj.","en":"examining details with great care and precision","vi":"xem xét chi tiết với độ chính xác và cẩn trọng cao"}],"examples":[{"en":"The forensic team carefully examined fingerprints on the window.","vi":"Đội ngũ giám định pháp y đã kiểm tra kỹ lưỡng các dấu vân tay trên cửa sổ.","audioKind":"ex"},{"en":"Advances in forensic science can help courts assess evidence more accurately and reduce wrongful convictions.","vi":"Những tiến bộ trong khoa học pháp y có thể giúp tòa án đánh giá chứng cứ chính xác hơn và giảm thiểu các bản án oan sai.","audioKind":"ex2"}],"collocations":[{"en":"forensic science","vi":"khoa học pháp y"},{"en":"forensic evidence","vi":"chứng cứ giám định tư pháp"},{"en":"forensic analysis","vi":"phân tích pháp y"},{"en":"forensic examination","vi":"kiểm tra giám định chi tiết"}],"wordFamily":["forensically (adv.)","forensics (n.)"],"synonyms":[],"antonyms":[],"tipVi":"forensic thường đóng vai trò tính từ; danh từ chỉ môn học thường dùng forensics.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_potent', 'en-c1-57', 'potent', '/ˈpoʊtnt/', 'C1', 'có hiệu lực mạnh; có sức ảnh hưởng lớn', 'adj.', 'potency (n.), impotent (adj.)', 'Đồng nghĩa: powerful, strong · Trái nghĩa: weak, ineffective', 'Nhấn mạnh hiệu lực hoặc sức ảnh hưởng mạnh mẽ, không nhầm lẫn với từ potential có nghĩa là "tiềm năng".', 'This potent medicine relieved my cough within an hour.', NULL, 'Loại thuốc hiệu lực mạnh này đã làm giảm cơn ho của tôi chỉ trong vòng một giờ.', '{"wordId":"potent","ukIpa":"/ˈpəʊtnt/","usIpa":"/ˈpoʊtnt/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"having a strong effect or powerful influence","vi":"có hiệu lực mạnh; có sức ảnh hưởng lớn"}],"examples":[{"en":"This potent medicine relieved my cough within an hour.","vi":"Loại thuốc hiệu lực mạnh này đã làm giảm cơn ho của tôi chỉ trong vòng một giờ.","audioKind":"ex"},{"en":"Public education can be a potent tool for reducing waste and encouraging more sustainable consumption.","vi":"Giáo dục cộng đồng có thể là một công cụ đắc lực giúp giảm thiểu rác thải và thúc đẩy lối tiêu dùng bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"potent drug","vi":"thuốc đặc trị mạnh"},{"en":"potent symbol","vi":"biểu tượng có sức ảnh hưởng mạnh mẽ"},{"en":"potent force","vi":"lực lượng hùng mạnh"},{"en":"potent reminder","vi":"lời nhắc nhở sâu sắc"}],"wordFamily":["potency (n.)","impotent (adj.)"],"synonyms":["powerful","strong"],"antonyms":["weak","ineffective"],"tipVi":"Nhấn mạnh hiệu lực hoặc sức ảnh hưởng mạnh mẽ, không nhầm lẫn với từ potential có nghĩa là \"tiềm năng\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_substantiate', 'en-c1-57', 'substantiate', '/səbˈstænʃieɪt/', 'C1', 'chứng minh; củng cố bằng chứng; làm sáng tỏ', 'v.', 'substantiation (n.), unsubstantiated (adj.)', 'Đồng nghĩa: verify, corroborate, confirm · Trái nghĩa: disprove, refute', 'Là động từ chỉ hành động trang trọng; thường đi với các từ như "claim", nhấn mạnh việc đưa ra bằng chứng.', 'She kept the receipts to substantiate her insurance claim.', NULL, 'Cô ấy giữ lại các hóa đơn để chứng minh cho yêu cầu bồi thường bảo hiểm của mình.', '{"wordId":"substantiate","ukIpa":"/səbˈstænʃieɪt/","usIpa":"/səbˈstænʃieɪt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"to provide evidence showing that something is true","vi":"chứng minh; củng cố bằng chứng; làm sáng tỏ"}],"examples":[{"en":"She kept the receipts to substantiate her insurance claim.","vi":"Cô ấy giữ lại các hóa đơn để chứng minh cho yêu cầu bồi thường bảo hiểm của mình.","audioKind":"ex"},{"en":"Researchers must substantiate claims about new treatments with reliable evidence from carefully designed clinical trials.","vi":"Các nhà nghiên cứu phải chứng minh các tuyên bố về phương pháp điều trị mới bằng những bằng chứng đáng tin cậy từ các thử nghiệm lâm sàng được thiết kế cẩn thận.","audioKind":"ex2"}],"collocations":[{"en":"substantiate a claim","vi":"chứng minh một Tuyên bố"},{"en":"substantiate an allegation","vi":"chứng minh một cáo buộc"},{"en":"substantiate with evidence","vi":"chứng minh bằng bằng chứng"}],"wordFamily":["substantiation (n.)","unsubstantiated (adj.)"],"synonyms":["verify","corroborate","confirm"],"antonyms":["disprove","refute"],"tipVi":"Là động từ chỉ hành động trang trọng; thường đi với các từ như \"claim\", nhấn mạnh việc đưa ra bằng chứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parameter', 'en-c1-57', 'parameter', '/pəˈræmɪtər/', 'C1', 'thông số; tham số; giới hạn; khuôn khổ; điều kiện giới hạn', 'n.', 'parametric (adj.)', NULL, 'Khi mang nghĩa giới hạn, từ này thường dùng ở số nhiều; tránh nhầm lẫn với perimeter (chu vi).', 'You can adjust this parameter to sharpen the image.', NULL, 'Bạn có thể điều chỉnh thông số này để làm cho hình ảnh sắc nét hơn.', '{"wordId":"parameter","ukIpa":"/pəˈræmɪtə/","usIpa":"/pəˈræmɪtər/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A measurable factor used to describe a system or calculation.","vi":"thông số; tham số"},{"pos":"n.","en":"A limit or condition controlling how something can be done.","vi":"giới hạn; khuôn khổ; điều kiện giới hạn"}],"examples":[{"en":"You can adjust this parameter to sharpen the image.","vi":"Bạn có thể điều chỉnh thông số này để làm cho hình ảnh sắc nét hơn.","audioKind":"ex"},{"en":"Researchers must identify the key parameters affecting energy consumption before developing reliable models of urban demand.","vi":"Các nhà nghiên cứu phải xác định các thông số chính ảnh hưởng đến mức tiêu thụ năng lượng trước khi xây dựng các mô hình đáng tin cậy về nhu cầu đô thị.","audioKind":"ex2"}],"collocations":[{"en":"key parameter","vi":"thông số quan trọng"},{"en":"set parameters","vi":"thiết lập thông số"},{"en":"within the parameters","vi":"trong giới hạn cho phép"}],"wordFamily":["parametric (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa giới hạn, từ này thường dùng ở số nhiều; tránh nhầm lẫn với perimeter (chu vi).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sampling', 'en-c1-57', 'sampling', '/ˈsæmplɪŋ/', 'C1', 'sự lấy mẫu; việc rút mẫu để nghiên cứu tổng thể; sự nếm thử; việc trải nghiệm một lượng nhỏ để biết hương vị', 'n.', 'sample (n.), sample (v.), sampler (n.)', NULL, 'Quá trình lấy mẫu gọi là sampling; còn phần mẫu được lấy ra gọi là sample.', 'Sampling the soup helped me choose my lunch.', NULL, 'Việc nếm thử món súp giúp tôi chọn được món ăn trưa cho mình.', '{"wordId":"sampling","ukIpa":"/ˈsɑːmplɪŋ/","usIpa":"/ˈsæmplɪŋ/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"Selecting a small part of something to study the whole.","vi":"sự lấy mẫu; việc rút mẫu để nghiên cứu tổng thể"},{"pos":"n.","en":"Trying small amounts of something to discover what it is like.","vi":"sự nếm thử; việc trải nghiệm một lượng nhỏ để biết hương vị"}],"examples":[{"en":"Sampling the soup helped me choose my lunch.","vi":"Việc nếm thử món súp giúp tôi chọn được món ăn trưa cho mình.","audioKind":"ex"},{"en":"Random sampling helps researchers obtain representative data without interviewing every individual in a large population.","vi":"Phương pháp lấy mẫu ngẫu nhiên giúp các nhà nghiên cứu thu thập dữ liệu mang tính đại diện mà không cần phải phỏng vấn từng cá nhân trong một tổng thể lớn.","audioKind":"ex2"}],"collocations":[{"en":"random sampling","vi":"lấy mẫu ngẫu nhiên"},{"en":"sampling method","vi":"phương pháp lấy mẫu"},{"en":"sampling error","vi":"sai số lấy mẫu"},{"en":"water sampling","vi":"lấy mẫu nước"}],"wordFamily":["sample (n.)","sample (v.)","sampler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá trình lấy mẫu gọi là sampling; còn phần mẫu được lấy ra gọi là sample.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nitrate', 'en-c1-57', 'nitrate', '/ˈnaɪtreɪt/', 'C1', 'muối nitrat; nitrat', 'n.', 'nitration (n.)', NULL, 'Nitrate là muối nitrat, trong khi nitrite là muối nitrit.', 'The gardener added a nitrate fertiliser to the soil.', NULL, 'Người làm vườn đã bón phân nitrat vào đất.', '{"wordId":"nitrate","ukIpa":"/ˈnaɪtreɪt/","usIpa":"/ˈnaɪtreɪt/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A salt of nitric acid, often used in fertilisers","vi":"muối nitrat; nitrat"}],"examples":[{"en":"The gardener added a nitrate fertiliser to the soil.","vi":"Người làm vườn đã bón phân nitrat vào đất.","audioKind":"ex"},{"en":"Excessive nitrate levels in rivers can encourage algal growth and threaten the survival of aquatic species.","vi":"Hàm lượng nitrat quá mức trong các dòng sông có thể thúc đẩy sự phát triển của tảo và đe dọa sự sinh tồn của các loài thủy sinh.","audioKind":"ex2"}],"collocations":[{"en":"nitrate levels","vi":"nồng độ nitrat"},{"en":"nitrate pollution","vi":"ô nhiễm nitrat"},{"en":"potassium nitrate","vi":"kali nitrat"},{"en":"nitrate fertiliser","vi":"phân bón nitrat"}],"wordFamily":["nitration (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nitrate là muối nitrat, trong khi nitrite là muối nitrit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_translucent', 'en-c1-57', 'translucent', '/trænzˈluːsənt/', 'C1', 'bán trong suốt; cho ánh sáng xuyên qua nhưng không nhìn rõ vật bên trong', 'adj.', 'translucence (n.), translucency (n.)', 'Đồng nghĩa: semitransparent · Trái nghĩa: opaque', 'Khác với transparent (trong suốt): loại này cho ánh sáng qua nhưng không thể nhìn rõ vật phía sau.', 'Soft sunlight came through the translucent bathroom window.', NULL, 'Ánh nắng dịu dàng chiếu qua khung cửa sổ phòng tắm làm bằng kính mờ.', '{"wordId":"translucent","ukIpa":"/trænzˈluːsənt/","usIpa":"/trænzˈluːsənt/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Allowing light through, but not a clear view of objects.","vi":"bán trong suốt; cho ánh sáng xuyên qua nhưng không nhìn rõ vật bên trong"}],"examples":[{"en":"Soft sunlight came through the translucent bathroom window.","vi":"Ánh nắng dịu dàng chiếu qua khung cửa sổ phòng tắm làm bằng kính mờ.","audioKind":"ex"},{"en":"Translucent panels allow natural light into offices while maintaining privacy for people working inside.","vi":"Các tấm kính bán trong suốt cho phép ánh sáng tự nhiên chiếu vào văn phòng trong khi vẫn đảm bảo sự riêng tư cho những người làm việc bên trong.","audioKind":"ex2"}],"collocations":[{"en":"translucent glass","vi":"kính bán trong suốt"},{"en":"translucent material","vi":"chất liệu bán trong suốt"},{"en":"translucent panels","vi":"tấm vách mờ"}],"wordFamily":["translucence (n.)","translucency (n.)"],"synonyms":["semitransparent"],"antonyms":["opaque"],"tipVi":"Khác với transparent (trong suốt): loại này cho ánh sáng qua nhưng không thể nhìn rõ vật phía sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perpendicular', 'en-c1-57', 'perpendicular', '/ˌpɝːpənˈdɪkjələr/', 'C1', 'vuông góc; tạo với một đường thẳng hoặc bề mặt khác một góc vuông; thẳng đứng; đứng thẳng lên trên thay vì nghiêng dốc; đường vuông góc; đường thẳng tạo góc vuông với một đường khác', 'adj.', 'perpendicularly (adv.), perpendicularity (n.)', 'Trái nghĩa: parallel', 'Khi nói vuông góc với vật gì, dùng "perpendicular to", không dùng "with".', 'Keep the drill perpendicular to the wooden board.', NULL, 'Hãy giữ cho mũi khoan vuông góc với mặt ván gỗ.', '{"wordId":"perpendicular","ukIpa":"/ˌpɜːpənˈdɪkjələ/","usIpa":"/ˌpɝːpənˈdɪkjələr/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Meeting another line or surface at a right angle","vi":"vuông góc; tạo với một đường thẳng hoặc bề mặt khác một góc vuông"},{"pos":"adj.","en":"Rising straight up rather than sloping","vi":"thẳng đứng; đứng thẳng lên trên thay vì nghiêng dốc"},{"pos":"n.","en":"A line forming a right angle with another","vi":"đường vuông góc; đường thẳng tạo góc vuông với một đường khác"}],"examples":[{"en":"Keep the drill perpendicular to the wooden board.","vi":"Hãy giữ cho mũi khoan vuông góc với mặt ván gỗ.","audioKind":"ex"},{"en":"The proposed cycle path runs perpendicular to the main road, creating a crossing that requires careful safety planning.","vi":"Đường dành cho xe đạp được đề xuất nằm vuông góc với trục đường chính, tạo ra một giao lộ đòi hỏi phải lập kế hoạch an toàn cẩn thận.","audioKind":"ex2"}],"collocations":[{"en":"perpendicular to","vi":"vuông góc với"},{"en":"perpendicular lines","vi":"các đường vuông góc"},{"en":"a perpendicular cliff","vi":"vách đá dựng đứng"}],"wordFamily":["perpendicularly (adv.)","perpendicularity (n.)"],"synonyms":[],"antonyms":["parallel"],"tipVi":"Khi nói vuông góc với vật gì, dùng \"perpendicular to\", không dùng \"with\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_saline', 'en-c1-57', 'saline', '/ˈseɪliːn/', 'C1', 'chứa muối; có tính muối; dung dịch muối; đặc biệt là dung dịch dùng trong y tế', 'adj.', 'salinity (n.)', 'Đồng nghĩa: salty', 'Trong y học, "saline" thường chỉ nước muối sinh lý chứ không chỉ hồ nước mặn.', 'The nurse gently cleaned the wound with saline.', NULL, 'Y tá nhẹ nhàng rửa vết thương bằng nước muối sinh lý.', '{"wordId":"saline","ukIpa":"/ˈseɪlaɪn/","usIpa":"/ˈseɪliːn/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"containing salt or relating to salt","vi":"chứa muối; có tính muối"},{"pos":"n.","en":"a salt solution, especially one used in medical treatment","vi":"dung dịch muối; đặc biệt là dung dịch dùng trong y tế"}],"examples":[{"en":"The nurse gently cleaned the wound with saline.","vi":"Y tá nhẹ nhàng rửa vết thương bằng nước muối sinh lý.","audioKind":"ex"},{"en":"Rising sea levels can make coastal groundwater more saline, reducing its suitability for drinking and irrigation.","vi":"Mực nước biển dâng cao có thể làm cho nước ngầm ven biển nhiễm mặn nhiều hơn, làm giảm độ thích hợp cho việc uống và tưới tiêu.","audioKind":"ex2"}],"collocations":[{"en":"saline solution","vi":"dung dịch muối"},{"en":"saline water","vi":"nước muối"},{"en":"saline soil","vi":"đất nhiễm mặn"}],"wordFamily":["salinity (n.)"],"synonyms":["salty"],"antonyms":[],"tipVi":"Trong y học, \"saline\" thường chỉ nước muối sinh lý chứ không chỉ hồ nước mặn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_57_1', 'en-c1-57', 'Cách dùng “propagation” (n.) — sự nhân giống; sự sinh sản', 'plant propagation  ·  propagation by cuttings  ·  wave propagation', 'Thường là danh từ không đếm được; có thể dùng trong sinh học (nhân giống cây), truyền thông (thông tin) và vật lý (sóng).', 'Họ từ (Word Family): propagate (v.), propagator (n.)', '[{"hanzi":"Plant propagation is easier with healthy cuttings and clean tools.","pinyin":"","meaning":"Việc nhân giống cây trồng sẽ dễ dàng hơn nếu sử dụng các cành giâm khỏe mạnh và dụng cụ sạch sẽ."},{"hanzi":"The rapid propagation of misleading information online can undermine public trust in reliable scientific evidence.","pinyin":"","meaning":"Sự lan truyền nhanh chóng của thông tin sai lệch trên mạng có thể làm suy giảm niềm tin của công chúng vào các bằng chứng khoa học đáng tin cậy."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_57_2', 'en-c1-57', 'Cách dùng “magnify” (v.) — làm phóng đại; phóng to', 'magnify an image  ·  magnify a problem  ·  magnifying glass', 'Có thể dùng để chỉ việc phóng đại hình ảnh qua thấu kính, hoặc phóng đại quy mô, mức độ nghiêm trọng của một vấn đề.', 'Họ từ (Word Family): magnification (n.), magnifier (n.) | Đồng nghĩa: enlarge, exaggerate · Trái nghĩa: reduce', '[{"hanzi":"This lens magnifies tiny insects so we can examine them.","pinyin":"","meaning":"Thấu kính này giúp phóng to những con côn trùng nhỏ để chúng ta có thể quan sát chúng."},{"hanzi":"Social media can magnify public concerns by repeatedly exposing users to dramatic accounts of rare events.","pinyin":"","meaning":"Mạng xã hội có thể làm trầm trọng thêm mối lo ngại của công chúng bằng cách liên tục cho người dùng tiếp cận những bài viết giật gân về các sự kiện hiếm gặp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_57_3', 'en-c1-57', 'Cách dùng “substantiate” (v.) — chứng minh; củng cố bằng chứng; làm sáng tỏ', 'substantiate a claim  ·  substantiate an allegation  ·  substantiate with evidence', 'Là động từ chỉ hành động trang trọng; thường đi với các từ như "claim", nhấn mạnh việc đưa ra bằng chứng.', 'Họ từ (Word Family): substantiation (n.), unsubstantiated (adj.) | Đồng nghĩa: verify, corroborate, confirm · Trái nghĩa: disprove, refute', '[{"hanzi":"She kept the receipts to substantiate her insurance claim.","pinyin":"","meaning":"Cô ấy giữ lại các hóa đơn để chứng minh cho yêu cầu bồi thường bảo hiểm của mình."},{"hanzi":"Researchers must substantiate claims about new treatments with reliable evidence from carefully designed clinical trials.","pinyin":"","meaning":"Các nhà nghiên cứu phải chứng minh các tuyên bố về phương pháp điều trị mới bằng những bằng chứng đáng tin cậy từ các thử nghiệm lâm sàng được thiết kế cẩn thận."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_57_4', 'en-c1-57', 'Cách dùng “potent” (adj.) — có hiệu lực mạnh; có sức ảnh hưởng lớn', 'potent drug  ·  potent symbol  ·  potent force', 'Nhấn mạnh hiệu lực hoặc sức ảnh hưởng mạnh mẽ, không nhầm lẫn với từ potential có nghĩa là "tiềm năng".', 'Họ từ (Word Family): potency (n.), impotent (adj.) | Đồng nghĩa: powerful, strong · Trái nghĩa: weak, ineffective', '[{"hanzi":"This potent medicine relieved my cough within an hour.","pinyin":"","meaning":"Loại thuốc hiệu lực mạnh này đã làm giảm cơn ho của tôi chỉ trong vòng một giờ."},{"hanzi":"Public education can be a potent tool for reducing waste and encouraging more sustainable consumption.","pinyin":"","meaning":"Giáo dục cộng đồng có thể là một công cụ đắc lực giúp giảm thiểu rác thải và thúc đẩy lối tiêu dùng bền vững hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_57_1', 'en-c1-57', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
