INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_1_2', 'ten_c1_57_1', 'extraction', 'The dentist explained why a tooth extraction was necessary.', 'The dentist explained why a tooth extraction was necessary.', '/ɪkˈstrækʃən/', 'Nha sĩ giải thích lý do tại sao việc nhổ răng là cần thiết.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
