INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_1_4', 'ten_c1_57_1', 'aerodynamics', 'We explored aerodynamics by testing paper planes in the garden.', 'We explored aerodynamics by testing paper planes in the garden.', '/ˌeroʊdaɪˈnæmɪks/', 'Chúng tôi đã tìm hiểu về khí động học bằng cách thử nghiệm máy bay giấy trong vườn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_1_5', 'ten_c1_57_1', 'denote', 'On this map, blue lines denote rivers and streams.', 'On this map, blue lines denote rivers and streams.', '/dɪˈnoʊt/', 'Trên bản đồ này, các đường màu xanh lam biểu thị sông và suối.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_1_6', 'ten_c1_57_1', 'corrode', 'Salt water has corroded the metal hinges on our gate.', 'Salt water has corroded the metal hinges on our gate.', '/kəˈroʊd/', 'Nước muối đã làm ăn mòn các bản lề kim loại trên cánh cổng nhà chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_1_7', 'ten_c1_57_1', 'alloy', 'This bicycle frame is made from a lightweight alloy.', 'This bicycle frame is made from a lightweight alloy.', '/ˈælɔɪ/', 'Khung chiếc xe đạp này được làm từ một loại hợp kim nhẹ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_1_8', 'ten_c1_57_1', 'deformation', 'The heat caused visible deformation of the plastic lid.', 'The heat caused visible deformation of the plastic lid.', '/ˌdiːfɔːrˈmeɪʃən/', 'Sức nóng đã làm cho chiếc nắp nhựa bị biến dạng rõ rệt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_57_1_1', 'en-c1-57', 'ten_c1_57_1', 'listening', 'listening', 'The car''s sudden acceleration pushed me against my seat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sự tăng tốc đột ngột của chiếc xe đẩy tôi ép sát vào lưng ghế.","Phí giao hàng sẽ tương ứng với trọng lượng của bưu kiện.","Bạn có thể điều chỉnh thông số này để làm cho hình ảnh sắc nét hơn.","Cẩn thận lật ngược chiếc bát lại để lấy phần thạch ra."]'::jsonb, 0, 'The car''s sudden acceleration pushed me against my seat. → Sự tăng tốc đột ngột của chiếc xe đẩy tôi ép sát vào lưng ghế.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_57_1_2', 'en-c1-57', 'ten_c1_57_1', 'listening', 'listening', 'The dentist explained why a tooth extraction was necessary.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc nếm thử món súp giúp tôi chọn được món ăn trưa cho mình.","Khung chiếc xe đạp này được làm từ một loại hợp kim nhẹ.","Nha sĩ giải thích lý do tại sao việc nhổ răng là cần thiết.","Chúng tôi học môn giải phẫu học bằng một mô hình trái tim bằng nhựa."]'::jsonb, 2, 'The dentist explained why a tooth extraction was necessary. → Nha sĩ giải thích lý do tại sao việc nhổ răng là cần thiết.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_57_1_3', 'en-c1-57', 'ten_c1_57_1', 'listening', 'listening', 'The sticker left a sticky residue on the jar.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sức nóng đã làm cho chiếc nắp nhựa bị biến dạng rõ rệt.","Trên bản đồ này, các đường màu xanh lam biểu thị sông và suối.","Nước muối đã làm ăn mòn các bản lề kim loại trên cánh cổng nhà chúng tôi.","Miếng dán đã để lại một lớp cặn dính trên chiếc lọ."]'::jsonb, 3, 'The sticker left a sticky residue on the jar. → Miếng dán đã để lại một lớp cặn dính trên chiếc lọ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_57_2', 'en-c1-57', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_2_1', 'ten_c1_57_2', 'acceleration', 'The acceleration of urban growth has increased demand for affordable housing and reliable public transport.', 'The acceleration of urban growth has increased demand for affordable housing and reliable public transport.', '/əkˌseləˈreɪʃən/', 'Sự gia tăng tốc độ phát triển đô thị đã làm tăng nhu cầu về nhà ở giá rẻ và phương tiện giao thông công cộng đáng tin cậy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_2_2', 'ten_c1_57_2', 'extraction', 'The extraction of minerals can damage local ecosystems unless strict environmental safeguards are enforced.', 'The extraction of minerals can damage local ecosystems unless strict environmental safeguards are enforced.', '/ɪkˈstrækʃən/', 'Việc khai thác khoáng sản có thể tàn phá các hệ sinh thái địa phương trừ khi các biện pháp bảo vệ môi trường nghiêm ngặt được thực thi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_2_3', 'ten_c1_57_2', 'residue', 'Industrial processes can leave toxic residue in soil, creating long-term risks for nearby ecosystems and communities.', 'Industrial processes can leave toxic residue in soil, creating long-term risks for nearby ecosystems and communities.', '/ˈrezɪduː/', 'Các quy trình công nghiệp có thể để lại chất cặn độc hại trong đất, gây ra những rủi ro lâu dài cho các hệ sinh thái và cộng đồng xung quanh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_2_4', 'ten_c1_57_2', 'aerodynamics', 'Advances in aerodynamics allow aircraft manufacturers to reduce fuel consumption without significantly compromising passenger capacity or flight speed.', 'Advances in aerodynamics allow aircraft manufacturers to reduce fuel consumption without significantly compromising passenger capacity or flight speed.', '/ˌeroʊdaɪˈnæmɪks/', 'Những tiến bộ trong khí động học giúp các nhà sản xuất máy bay giảm mức tiêu thụ nhiên liệu mà không làm giảm đáng kể sức chứa hành khách hoặc tốc độ bay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_2_5', 'ten_c1_57_2', 'denote', 'In scientific diagrams, different colours often denote distinct materials, allowing readers to interpret complex structures more easily.', 'In scientific diagrams, different colours often denote distinct materials, allowing readers to interpret complex structures more easily.', '/dɪˈnoʊt/', 'Trong các sơ đồ khoa học, các màu sắc khác nhau thường biểu thị các vật liệu khác nhau, giúp người đọc diễn giải các cấu trúc phức tạp dễ dàng hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_57_2_6', 'ten_c1_57_2', 'corrode', 'A lack of transparency can corrode public trust in institutions and reduce participation in democratic processes.', 'A lack of transparency can corrode public trust in institutions and reduce participation in democratic processes.', '/kəˈroʊd/', 'Sự thiếu minh bạch có thể gặm nhấm niềm tin của công chúng vào các tổ chức và làm giảm tỷ lệ tham gia vào các tiến trình dân chủ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_57_2_1', 'en-c1-57', 'ten_c1_57_2', 'listening', 'listening', 'The acceleration of urban growth has increased demand for affordable housing and reliable public transport.', NULL, 'Trong câu vừa nghe, từ “acceleration” mang nghĩa nào sau đây?', '["tinh xảo; phức tạp; công phu","ép buộc; bắt buộc","đồ thủy tinh (đặc biệt là đồ uống hoặc thiết bị thí nghiệm)","sự tăng tốc; sự đẩy nhanh"]'::jsonb, 3, '“acceleration” (/əkˌseləˈreɪʃən/): sự tăng tốc; sự đẩy nhanh. Câu đầy đủ: The acceleration of urban growth has increased demand for affordable housing and reliable public transport.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_57_2_2', 'en-c1-57', 'ten_c1_57_2', 'listening', 'listening', 'The extraction of minerals can damage local ecosystems unless strict environmental safeguards are enforced.', NULL, 'Trong câu vừa nghe, từ “extraction” mang nghĩa nào sau đây?', '["cắt cổ, đắt cắt cổ; quá mức, cao vô lý","sự thiếu hụt; không đủ","giảng đạo; thuyết giáo","sự chiết xuất; sự khai thác; sự nhổ (răng)"]'::jsonb, 3, '“extraction” (/ɪkˈstrækʃən/): sự chiết xuất; sự khai thác; sự nhổ (răng). Câu đầy đủ: The extraction of minerals can damage local ecosystems unless strict environmental safeguards are enforced.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
