INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_2', 'en-c1-57', NULL, 'comprehensive_test', 'listening', 'The dentist explained why a tooth extraction was necessary.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã tìm hiểu về khí động học bằng cách thử nghiệm máy bay giấy trong vườn.","Hãy giữ cho mũi khoan vuông góc với mặt ván gỗ.","Nha sĩ giải thích lý do tại sao việc nhổ răng là cần thiết.","Nước muối đã làm ăn mòn các bản lề kim loại trên cánh cổng nhà chúng tôi."]'::jsonb, 2, 'The dentist explained why a tooth extraction was necessary. → Nha sĩ giải thích lý do tại sao việc nhổ răng là cần thiết.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
