INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_4', 'en-c1-57', NULL, 'comprehensive_test', 'listening', 'We explored aerodynamics by testing paper planes in the garden.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã tìm hiểu về khí động học bằng cách thử nghiệm máy bay giấy trong vườn.","Chúng tôi học môn giải phẫu học bằng một mô hình trái tim bằng nhựa.","Đường ống nước bị hỏng đã khiến thợ sửa ống nước phải đến khẩn cấp.","Loại thuốc hiệu lực mạnh này đã làm giảm cơn ho của tôi chỉ trong vòng một giờ."]'::jsonb, 0, 'We explored aerodynamics by testing paper planes in the garden. → Chúng tôi đã tìm hiểu về khí động học bằng cách thử nghiệm máy bay giấy trong vườn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_5', 'en-c1-57', NULL, 'comprehensive_test', 'listening', 'denote', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khổ sở; khốn khổ; bất hạnh","sự leo trèo, sự đi lên phía trên","biểu thị; chỉ rõ","đánh lừa; lừa dối; khiến ai đó ảo tưởng"]'::jsonb, 2, 'denote (/dɪˈnoʊt/) → biểu thị; chỉ rõ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_6', 'en-c1-57', NULL, 'comprehensive_test', 'listening', 'Salt water has corroded the metal hinges on our gate.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Miếng dán đã để lại một lớp cặn dính trên chiếc lọ.","Trên bản đồ này, các đường màu xanh lam biểu thị sông và suối.","Đường ống nước bị hỏng đã khiến thợ sửa ống nước phải đến khẩn cấp.","Nước muối đã làm ăn mòn các bản lề kim loại trên cánh cổng nhà chúng tôi."]'::jsonb, 3, 'Salt water has corroded the metal hinges on our gate. → Nước muối đã làm ăn mòn các bản lề kim loại trên cánh cổng nhà chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_7', 'en-c1-57', NULL, 'comprehensive_test', 'listening', 'alloy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lớp phủ; tầng phủ (tuyết, sương,...)","thi hành; thực thi; bắt tuân theo","hợp kim","sự đình trệ; sự ngưng trệ; tình trạng tê liệt"]'::jsonb, 2, 'alloy (/ˈælɔɪ/) → hợp kim; làm thành hợp kim; pha hợp kim', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_8', 'en-c1-57', NULL, 'comprehensive_test', 'listening', 'The heat caused visible deformation of the plastic lid.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy giữ lại các hóa đơn để chứng minh cho yêu cầu bồi thường bảo hiểm của mình.","Sức nóng đã làm cho chiếc nắp nhựa bị biến dạng rõ rệt.","Thấu kính này giúp phóng to những con côn trùng nhỏ để chúng ta có thể quan sát chúng.","Chúng tôi đã tìm hiểu về khí động học bằng cách thử nghiệm máy bay giấy trong vườn."]'::jsonb, 1, 'The heat caused visible deformation of the plastic lid. → Sức nóng đã làm cho chiếc nắp nhựa bị biến dạng rõ rệt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_9', 'en-c1-57', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To represent or indicate something.”?', '["magnify","denote","residue","alloy"]'::jsonb, 1, 'denote (/dɪˈnoʊt/) → biểu thị; chỉ rõ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_10', 'en-c1-57', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To gradually damage material chemically, or become damaged this way.”?', '["magnify","corrode","invert","perpendicular"]'::jsonb, 1, 'corrode (/kəˈroʊd/) → làm ăn mòn; bị ăn mòn (hóa học)', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_11', 'en-c1-57', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A metal made by combining metals or adding other elements.”?', '["saline","forensic","residue","alloy"]'::jsonb, 3, 'alloy (/ˈælɔɪ/) → hợp kim', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_12', 'en-c1-57', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a change in shape caused by pressure or other forces”?', '["parameter","forensic","deformation","substantiate"]'::jsonb, 2, 'deformation (/ˌdiːfɔːrˈmeɪʃən/) → sự biến dạng; sự biến hình', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_13', 'en-c1-57', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The process of entering or passing through something.”?', '["forensic","residue","perpendicular","penetration"]'::jsonb, 3, 'penetration (/ˌpenɪˈtreɪʃən/) → sự xuyên qua; sự thâm nhập', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
