INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_18', 'en-c1-57', NULL, 'comprehensive_test', 'reading', NULL, 'The acceleration of urban growth has increased demand for affordable housing and reliable public transport.', 'Dựa vào câu trên, từ “acceleration” có nghĩa phù hợp nhất là gì?', '["tùy tiện; ngẫu nhiên (không dựa trên lý do hay cơ sở rõ ràng)","suy ngẫm kỹ lưỡng về điều gì đó trong một khoảng thời gian dài","sự tăng tốc; sự đẩy nhanh","gác lại; tạm hoãn"]'::jsonb, 2, 'acceleration: sự tăng tốc; sự đẩy nhanh; gia tốc. Dịch cả câu: Sự gia tăng tốc độ phát triển đô thị đã làm tăng nhu cầu về nhà ở giá rẻ và phương tiện giao thông công cộng đáng tin cậy.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_19', 'en-c1-57', NULL, 'comprehensive_test', 'reading', NULL, 'The extraction of minerals can damage local ecosystems unless strict environmental safeguards are enforced.', 'Dựa vào câu trên, từ “extraction” có nghĩa phù hợp nhất là gì?', '["loài gặm nhấm","sự rõ ràng; dễ hiểu","bao gồm; gồm có","sự chiết xuất; sự khai thác; sự nhổ (răng)"]'::jsonb, 3, 'extraction: sự chiết xuất; sự khai thác; sự nhổ (răng). Dịch cả câu: Việc khai thác khoáng sản có thể tàn phá các hệ sinh thái địa phương trừ khi các biện pháp bảo vệ môi trường nghiêm ngặt được thực thi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_20', 'en-c1-57', NULL, 'comprehensive_test', 'reading', NULL, 'Industrial processes can leave toxic residue in soil, creating long-term risks for nearby ecosystems and communities.', 'Dựa vào câu trên, từ “residue” có nghĩa phù hợp nhất là gì?', '["nguồn gốc từ; từ nguyên","làm ăn mòn; bị ăn mòn (hóa học)","bằng độc quyền sáng chế; quyền sáng chế","chất cặn; phần dư; thặng dư"]'::jsonb, 3, 'residue: chất cặn; phần dư; thặng dư. Dịch cả câu: Các quy trình công nghiệp có thể để lại chất cặn độc hại trong đất, gây ra những rủi ro lâu dài cho các hệ sinh thái và cộng đồng xung quanh.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_21', 'en-c1-57', NULL, 'comprehensive_test', 'reading', NULL, 'Advances in aerodynamics allow aircraft manufacturers to reduce fuel consumption without significantly compromising passenger capacity or flight speed.', 'Dựa vào câu trên, từ “aerodynamics” có nghĩa phù hợp nhất là gì?', '["làm nhục; làm bẽ mặt; sỉ nhục","khí động học","bờm (ngựa, sư tử, v.v.)","lao đi; phóng vụt qua"]'::jsonb, 1, 'aerodynamics: khí động học; đặc tính khí động học. Dịch cả câu: Những tiến bộ trong khí động học giúp các nhà sản xuất máy bay giảm mức tiêu thụ nhiên liệu mà không làm giảm đáng kể sức chứa hành khách hoặc tốc độ bay.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_22', 'en-c1-57', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bán trong suốt; cho ánh sáng xuyên qua nhưng không nhìn rõ vật bên trong”', '["translucent","indicative","humanities","assimilate"]'::jsonb, 0, 'bán trong suốt; cho ánh sáng xuyên qua nhưng không nhìn rõ vật bên trong → translucent (/trænzˈluːsənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_23', 'en-c1-57', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vuông góc; tạo với một đường thẳng hoặc bề mặt khác một góc vuông”', '["perpendicular","gramophone","cynical","trivial"]'::jsonb, 0, 'vuông góc; tạo với một đường thẳng hoặc bề mặt khác một góc vuông → perpendicular (/ˌpɝːpənˈdɪkjələr/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_57_24', 'en-c1-57', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chứa muối; có tính muối”', '["virtue","saline","twinkle","integrity"]'::jsonb, 1, 'chứa muối; có tính muối → saline (/ˈseɪliːn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-58', 'en', 'Bài 58: Khoa học & Nghiên cứu (5) - CEFR C1', 'CEFR C1', 'C1 · Khoa học', '25 từ vựng Tiếng Anh CEFR C1 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5058, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soluble', 'en-c1-58', 'soluble', '/ˈsɑːljəbl/', 'C1', 'có thể hòa tan trong chất lỏng; có thể giải quyết được', 'adj.', 'solubility (n.), insoluble (adj.)', 'Trái nghĩa: insoluble', 'Thường dùng cấu trúc be soluble in; tính từ ghép water-soluble dùng để chỉ tính tan trong nước.', 'These soluble tablets disappear quickly in a glass of water.', NULL, 'Những viên thuốc sủi bọt này tan rất nhanh trong một cốc nước.', '{"wordId":"soluble","ukIpa":"/ˈsɒljəbl/","usIpa":"/ˈsɑːljəbl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Able to dissolve in a liquid.","vi":"có thể hòa tan trong chất lỏng"},{"pos":"adj.","en":"Possible to solve, especially through thought or effort.","vi":"có thể giải quyết được"}],"examples":[{"en":"These soluble tablets disappear quickly in a glass of water.","vi":"Những viên thuốc sủi bọt này tan rất nhanh trong một cốc nước.","audioKind":"ex"},{"en":"Water-soluble pollutants can spread through rivers, making contamination difficult to contain once it enters the water supply.","vi":"Các chất ô nhiễm tan trong nước có thể lan truyền qua các dòng sông, khiến cho tình trạng ô nhiễm trở nên khó kiểm soát một khi đã xâm nhập vào nguồn nước.","audioKind":"ex2"}],"collocations":[{"en":"soluble in water","vi":"hòa tan trong nước"},{"en":"water-soluble vitamins","vi":"vitamin tan trong nước"},{"en":"highly soluble","vi":"dễ tan; độ hòa tan cao"}],"wordFamily":["solubility (n.)","insoluble (adj.)"],"synonyms":[],"antonyms":["insoluble"],"tipVi":"Thường dùng cấu trúc be soluble in; tính từ ghép water-soluble dùng để chỉ tính tan trong nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_catalyst', 'en-c1-58', 'catalyst', '/ˈkætəlɪst/', 'C1', 'tác nhân thúc đẩy; người hoặc vật gây ra thay đổi; chất xúc tác', 'n.', 'catalytic (adj.), catalyse (v.), catalysis (n.)', 'Đồng nghĩa: trigger', 'Khi dùng theo nghĩa bóng để chỉ yếu tố thúc đẩy sự thay đổi, thường dùng cấu trúc a catalyst for.', 'That conversation became the catalyst for our neighbourhood cleanup.', NULL, 'Cuộc trò chuyện hôm đó đã trở thành động lực thúc đẩy chiến dịch dọn dẹp khu phố của chúng tôi.', '{"wordId":"catalyst","ukIpa":"/ˈkætəlɪst/","usIpa":"/ˈkætəlɪst/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A person or thing that triggers or accelerates change.","vi":"tác nhân thúc đẩy; người hoặc vật gây ra thay đổi"},{"pos":"n.","en":"A substance that speeds up a reaction without being consumed.","vi":"chất xúc tác"}],"examples":[{"en":"That conversation became the catalyst for our neighbourhood cleanup.","vi":"Cuộc trò chuyện hôm đó đã trở thành động lực thúc đẩy chiến dịch dọn dẹp khu phố của chúng tôi.","audioKind":"ex"},{"en":"Investment in public transport can act as a catalyst for wider economic growth in disadvantaged regions.","vi":"Đầu tư vào giao thông công cộng có thể đóng vai trò là động lực thúc đẩy tăng trưởng kinh tế rộng lớn hơn ở các vùng còn nhiều khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"a catalyst for change","vi":"tác nhân thay đổi"},{"en":"act as a catalyst","vi":"đóng vai trò là chất xúc tác"},{"en":"a chemical catalyst","vi":"chất xúc tác hóa học"}],"wordFamily":["catalytic (adj.)","catalyse (v.)","catalysis (n.)"],"synonyms":["trigger"],"antonyms":[],"tipVi":"Khi dùng theo nghĩa bóng để chỉ yếu tố thúc đẩy sự thay đổi, thường dùng cấu trúc a catalyst for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_velocity', 'en-c1-58', 'velocity', '/vəˈlɑːsəti/', 'C1', 'vận tốc; tốc độ', 'n.', NULL, 'Đồng nghĩa: speed', 'Trong vật lý, velocity bao gồm cả hướng, trong khi speed chỉ biểu thị mức độ nhanh chậm.', 'The ball gained velocity as it rolled downhill.', NULL, 'Quả bóng tăng dần vận tốc khi lăn xuống dốc.', '{"wordId":"velocity","ukIpa":"/vəˈlɒsəti/","usIpa":"/vəˈlɑːsəti/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"Speed of movement, including direction in physics.","vi":"vận tốc; tốc độ"}],"examples":[{"en":"The ball gained velocity as it rolled downhill.","vi":"Quả bóng tăng dần vận tốc khi lăn xuống dốc.","audioKind":"ex"},{"en":"Engineers measure the velocity of flowing water to determine whether a site is suitable for generating electricity.","vi":"Các kỹ sư đo vận tốc của dòng nước chảy để xác định xem một địa điểm có phù hợp để phát điện hay không.","audioKind":"ex2"}],"collocations":[{"en":"high velocity","vi":"tốc độ cao"},{"en":"constant velocity","vi":"vận tốc không đổi"},{"en":"terminal velocity","vi":"vận tốc giới hạn"}],"wordFamily":[],"synonyms":["speed"],"antonyms":[],"tipVi":"Trong vật lý, velocity bao gồm cả hướng, trong khi speed chỉ biểu thị mức độ nhanh chậm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ampere', 'en-c1-58', 'ampere', '/ˈæmpɪr/', 'C1', 'an-pe', 'n.', NULL, 'Đồng nghĩa: amp', 'Ký hiệu là A; trong văn nói thường gọi tắt là "amp", số nhiều thêm s.', 'This small lamp draws less than one ampere.', NULL, 'Chiếc đèn nhỏ này tiêu thụ chưa đến một an-pe.', '{"wordId":"ampere","ukIpa":"/ˈæmpeə/","usIpa":"/ˈæmpɪr/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"a unit used to measure electric current","vi":"an-pe"}],"examples":[{"en":"This small lamp draws less than one ampere.","vi":"Chiếc đèn nhỏ này tiêu thụ chưa đến một an-pe.","audioKind":"ex"},{"en":"Students measured the current in amperes to compare the electrical requirements of different household appliances.","vi":"Học sinh đo cường độ dòng điện bằng đơn vị an-pe để so sánh mức độ tiêu thụ điện của các thiết bị gia dụng khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"electric current in amperes","vi":"cường độ dòng điện tính bằng an-pe"},{"en":"one ampere of current","vi":"một an-pe dòng điện"}],"wordFamily":[],"synonyms":["amp"],"antonyms":[],"tipVi":"Ký hiệu là A; trong văn nói thường gọi tắt là \"amp\", số nhiều thêm s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spectrum', 'en-c1-58', 'spectrum', '/ˈspektrəm/', 'C1', 'phạm vi; chuỗi (ý tưởng, phẩm chất, khả năng); quang phổ; phổ (màu sắc hoặc sóng)', 'n.', 'spectral (adj.)', 'Đồng nghĩa: range', 'Dạng số nhiều có thể dùng spectra hoặc spectrums.', 'Our book club welcomes a wide spectrum of opinions.', NULL, 'Câu lạc bộ sách của chúng tôi hoan nghênh một phạm vi ý kiến rất rộng rãi.', '{"wordId":"spectrum","ukIpa":"/ˈspektrəm/","usIpa":"/ˈspektrəm/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A range of related ideas, qualities, or possibilities","vi":"phạm vi; chuỗi (ý tưởng, phẩm chất, khả năng)"},{"pos":"n.","en":"A range of colours or waves arranged by wavelength or frequency","vi":"quang phổ; phổ (màu sắc hoặc sóng)"}],"examples":[{"en":"Our book club welcomes a wide spectrum of opinions.","vi":"Câu lạc bộ sách của chúng tôi hoan nghênh một phạm vi ý kiến rất rộng rãi.","audioKind":"ex"},{"en":"Universities should provide support for students across the entire spectrum of academic abilities and social backgrounds.","vi":"Các trường đại học nên cung cấp sự hỗ trợ cho sinh viên ở mọi năng lực học tập và hoàn cảnh xã hội khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a broad spectrum of","vi":"một loạt các..."},{"en":"across the spectrum","vi":"trên toàn bộ phổ"},{"en":"the visible spectrum","vi":"quang phổ khả kiến"},{"en":"the political spectrum","vi":"phổ chính trị"}],"wordFamily":["spectral (adj.)"],"synonyms":["range"],"antonyms":[],"tipVi":"Dạng số nhiều có thể dùng spectra hoặc spectrums.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disprove', 'en-c1-58', 'disprove', '/dɪsˈpruːv/', 'C1', 'chứng minh là sai, bác bỏ, phản bác', 'v.', 'prove (v.), proof (n.), disproof (n.)', 'Đồng nghĩa: refute · Trái nghĩa: prove, confirm', 'Không chỉ thể hiện sự phản đối, mà là dùng bằng chứng để chứng minh lời nói là sai.', 'The clear photograph disproved his claim about the damage.', NULL, 'Bức ảnh rõ nét đã bác bỏ tuyên bố của anh ấy về thiệt hại.', '{"wordId":"disprove","ukIpa":"/dɪsˈpruːv/","usIpa":"/dɪsˈpruːv/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"to show through evidence that something is not true","vi":"chứng minh là sai, bác bỏ, phản bác"}],"examples":[{"en":"The clear photograph disproved his claim about the damage.","vi":"Bức ảnh rõ nét đã bác bỏ tuyên bố của anh ấy về thiệt hại.","audioKind":"ex"},{"en":"Researchers need reliable evidence to disprove the assumption that smaller classes always lead to better academic results.","vi":"Các nhà nghiên cứu cần bằng chứng đáng tin cậy để bác bỏ giả định rằng các lớp học quy mô nhỏ hơn luôn mang lại kết quả học tập tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"disprove a theory","vi":"bác bỏ một lý thuyết"},{"en":"disprove a claim","vi":"bác bỏ một tuyên bố"},{"en":"disprove a hypothesis","vi":"bác bỏ một giả thuyết"}],"wordFamily":["prove (v.)","proof (n.)","disproof (n.)"],"synonyms":["refute"],"antonyms":["prove","confirm"],"tipVi":"Không chỉ thể hiện sự phản đối, mà là dùng bằng chứng để chứng minh lời nói là sai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inflammable', 'en-c1-58', 'inflammable', '/ɪnˈflæməbəl/', 'C1', 'dễ cháy; dễ bắt lửa', 'adj.', 'inflammability (n.)', 'Đồng nghĩa: flammable, combustible · Trái nghĩa: non-flammable', 'inflammable là dễ cháy; không cháy dùng non-flammable.', 'Keep inflammable liquids well away from the kitchen stove.', NULL, 'Hãy để các chất lỏng dễ cháy cách xa bếp nấu trong nhà bếp.', '{"wordId":"inflammable","ukIpa":"/ɪnˈflæməbəl/","usIpa":"/ɪnˈflæməbəl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Able to catch fire easily.","vi":"dễ cháy; dễ bắt lửa"}],"examples":[{"en":"Keep inflammable liquids well away from the kitchen stove.","vi":"Hãy để các chất lỏng dễ cháy cách xa bếp nấu trong nhà bếp.","audioKind":"ex"},{"en":"Factories must store inflammable materials safely to reduce fire risks and protect both workers and nearby communities.","vi":"Các nhà máy phải lưu trữ vật liệu dễ cháy một cách an toàn để giảm thiểu rủi ro hỏa hoạn và bảo vệ cả công nhân lẫn cộng đồng xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"inflammable materials","vi":"vật liệu dễ cháy"},{"en":"inflammable liquids","vi":"chất lỏng dễ cháy"},{"en":"highly inflammable","vi":"dễ bắt lửa mạnh"}],"wordFamily":["inflammability (n.)"],"synonyms":["flammable","combustible"],"antonyms":["non-flammable"],"tipVi":"inflammable là dễ cháy; không cháy dùng non-flammable.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_withstand', 'en-c1-58', 'withstand', '/wɪðˈstænd/', 'C1', 'chịu đựng; chống lại; trụ vững', 'v.', NULL, 'Đồng nghĩa: resist, endure', 'Dạng quá khứ và quá khứ phân từ là withstood; theo sau trực tiếp bởi tân ngữ.', 'These boots can withstand rain, mud, and rough paths.', NULL, 'Đôi bốt này có thể chống chịu được mưa, bùn và những con đường gập ghềnh.', '{"wordId":"withstand","ukIpa":"/wɪðˈstænd/","usIpa":"/wɪðˈstænd/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To resist damage or remain strong under pressure","vi":"chịu đựng; chống lại; trụ vững"}],"examples":[{"en":"These boots can withstand rain, mud, and rough paths.","vi":"Đôi bốt này có thể chống chịu được mưa, bùn và những con đường gập ghềnh.","audioKind":"ex"},{"en":"Coastal infrastructure must be designed to withstand stronger storms as climate change increases the frequency of extreme weather.","vi":"Hợp tác hạ tầng ven biển phải được thiết kế để chống chọi với những cơn bão mạnh hơn khi biến đổi khí hậu làm tăng tần suất thời tiết cực đoan.","audioKind":"ex2"}],"collocations":[{"en":"withstand pressure","vi":"chịu đựng áp lực"},{"en":"withstand extreme temperatures","vi":"chịu được nhiệt độ khắc nghiệt"},{"en":"withstand strong winds","vi":"chống chọi gió lớn"}],"wordFamily":[],"synonyms":["resist","endure"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ là withstood; theo sau trực tiếp bởi tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meteorology', 'en-c1-58', 'meteorology', '/ˌmiːtiəˈrɑːlədʒi/', 'C1', 'khí tượng học', 'n.', 'meteorologist (n.), meteorological (adj.)', NULL, 'Thường là danh từ không đếm được; chuyên nghiên cứu về thời tiết, không phải nghiên cứu sao băng.', 'My sister studies meteorology and loves watching storm clouds.', NULL, 'Chị gái tôi học ngành khí tượng học và rất thích ngắm nhìn những đám mây giông.', '{"wordId":"meteorology","ukIpa":"/ˌmiːtiəˈrɒlədʒi/","usIpa":"/ˌmiːtiəˈrɑːlədʒi/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"The scientific study of weather and the atmosphere.","vi":"khí tượng học"}],"examples":[{"en":"My sister studies meteorology and loves watching storm clouds.","vi":"Chị gái tôi học ngành khí tượng học và rất thích ngắm nhìn những đám mây giông.","audioKind":"ex"},{"en":"Advances in meteorology allow coastal communities to prepare more effectively for severe storms and flooding.","vi":"Những tiến bộ trong ngành khí tượng học giúp các cộng đồng ven biển chuẩn bị tốt hơn để đối phó với bão lớn và lũ lụt.","audioKind":"ex2"}],"collocations":[{"en":"study meteorology","vi":"nghiên cứu khí tượng học"},{"en":"a degree in meteorology","vi":"bằng cử nhân khí tượng học"},{"en":"advances in meteorology","vi":"những tiến bộ trong khí tượng học"}],"wordFamily":["meteorologist (n.)","meteorological (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; chuyên nghiên cứu về thời tiết, không phải nghiên cứu sao băng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_specimen', 'en-c1-58', 'specimen', '/ˈspesəmən/', 'C1', 'vật mẫu; tiêu bản (động vật, thực vật, vật thể phục vụ nghiên cứu); mẫu bệnh phẩm; mẫu xét nghiệm y tế', 'n.', NULL, 'Đồng nghĩa: sample', 'specimen thường chỉ mẫu vật phục vụ nghiên cứu hoặc kiểm tra y tế, không dùng để chỉ chung chung các ví dụ.', 'The museum keeps this butterfly specimen behind glass.', NULL, 'Bảo tàng giữ mẫu bướm này đằng sau lớp kính.', '{"wordId":"specimen","ukIpa":"/ˈspesɪmən/","usIpa":"/ˈspesəmən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"An individual animal, plant, or object collected for scientific study.","vi":"vật mẫu; tiêu bản (động vật, thực vật, vật thể phục vụ nghiên cứu)"},{"pos":"n.","en":"A small amount of bodily material taken for medical testing.","vi":"mẫu bệnh phẩm; mẫu xét nghiệm y tế"}],"examples":[{"en":"The museum keeps this butterfly specimen behind glass.","vi":"Bảo tàng giữ mẫu bướm này đằng sau lớp kính.","audioKind":"ex"},{"en":"Researchers examined each plant specimen to assess how prolonged drought had affected its growth.","vi":"Các nhà nghiên cứu đã kiểm tra từng mẫu thực vật để đánh giá mức độ ảnh hưởng của đợt hạn hán kéo dài đến sự phát triển của chúng.","audioKind":"ex2"}],"collocations":[{"en":"collect a specimen","vi":"thu thập mẫu vật"},{"en":"a plant specimen","vi":"mẫu thực vật"},{"en":"a urine specimen","vi":"mẫu nước tiểu"}],"wordFamily":[],"synonyms":["sample"],"antonyms":[],"tipVi":"specimen thường chỉ mẫu vật phục vụ nghiên cứu hoặc kiểm tra y tế, không dùng để chỉ chung chung các ví dụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dissipate', 'en-c1-58', 'dissipate', '/ˈdɪsɪpeɪt/', 'C1', 'tan biến; làm tản mác; lãng phí; phung phí', 'v.', 'dissipation (n.)', 'Đồng nghĩa: disperse, dispel · Trái nghĩa: accumulate', 'Có thể dùng theo cả ngoại động từ và nội động từ: sương mù tự tan biến hoặc gió làm sương mù tản đi.', 'The morning mist began to dissipate as sunlight warmed the valley.', NULL, 'Sương mù buổi sáng bắt đầu tan biến khi ánh nắng sưởi ấm thung lũng.', '{"wordId":"dissipate","ukIpa":"/ˈdɪsɪpeɪt/","usIpa":"/ˈdɪsɪpeɪt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To gradually disappear or cause something to spread and disappear.","vi":"tan biến; làm tản mác"},{"pos":"v.","en":"To waste money, energy, or resources through careless use.","vi":"lãng phí; phung phí"}],"examples":[{"en":"The morning mist began to dissipate as sunlight warmed the valley.","vi":"Sương mù buổi sáng bắt đầu tan biến khi ánh nắng sưởi ấm thung lũng.","audioKind":"ex"},{"en":"Urban green spaces help dissipate heat, reducing the discomfort caused by high temperatures in densely populated areas.","vi":"Các mảng xanh đô thị giúp tản nhiệt, làm giảm cảm giác khó chịu do nhiệt độ cao gây ra ở những khu vực đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"dissipate heat","vi":"tản nhiệt"},{"en":"tension dissipates","vi":"khí căng thẳng tan biến"},{"en":"dissipate energy","vi":"tiêu hao năng lượng"}],"wordFamily":["dissipation (n.)"],"synonyms":["disperse","dispel"],"antonyms":["accumulate"],"tipVi":"Có thể dùng theo cả ngoại động từ và nội động từ: sương mù tự tan biến hoặc gió làm sương mù tản đi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_optimum', 'en-c1-58', 'optimum', '/ˈɑːptɪməm/', 'C1', 'tối ưu; thuận lợi nhất; trạng thái tối ưu; điều kiện tối ưu', 'adj.', 'optimal (adj.), optimise (v.), optimisation (n.)', 'Đồng nghĩa: ideal, optimal · Trái nghĩa: worst', 'Nhấn mạnh mức độ phù hợp nhất với mục tiêu chứ không có nghĩa là "càng nhiều càng tốt"; thường không đi kèm với trạng từ most.', 'This sunny windowsill provides optimum conditions for my herbs.', NULL, 'Bệ cửa sổ đầy nắng này cung cấp điều kiện hoàn hảo nhất cho các loại rau thơm của tôi.', '{"wordId":"optimum","ukIpa":"/ˈɒptɪməm/","usIpa":"/ˈɑːptɪməm/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"best suited to achieving a particular result","vi":"tối ưu; thuận lợi nhất"},{"pos":"n.","en":"the most favourable level or condition for a particular purpose","vi":"trạng thái tối ưu; điều kiện tối ưu"}],"examples":[{"en":"This sunny windowsill provides optimum conditions for my herbs.","vi":"Bệ cửa sổ đầy nắng này cung cấp điều kiện hoàn hảo nhất cho các loại rau thơm của tôi.","audioKind":"ex"},{"en":"Maintaining the optimum classroom temperature can help students concentrate and reduce the energy required for heating.","vi":"Duy trì nhiệt độ phòng tối ưu có thể giúp học sinh tập trung và giảm năng lượng cần thiết cho việc sưởi ấm.","audioKind":"ex2"}],"collocations":[{"en":"optimum conditions","vi":"điều kiện tối ưu"},{"en":"optimum temperature","vi":"nhiệt độ tối ưu"},{"en":"optimum performance","vi":"hiệu suất tối ưu"}],"wordFamily":["optimal (adj.)","optimise (v.)","optimisation (n.)"],"synonyms":["ideal","optimal"],"antonyms":["worst"],"tipVi":"Nhấn mạnh mức độ phù hợp nhất với mục tiêu chứ không có nghĩa là \"càng nhiều càng tốt\"; thường không đi kèm với trạng từ most.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_residual', 'en-c1-58', 'residual', '/rɪˈzɪdʒuəl/', 'C1', 'còn sót lại; dư thừa', 'adj.', 'residue (n.)', 'Đồng nghĩa: remaining, leftover', 'Thường dùng trong ngữ cảnh kỹ thuật hoặc khoa học, nhấn mạnh phần còn lại sau khi xử lý.', 'Residual heat kept the kitchen warm after dinner.', NULL, 'Hơi ấm còn sót lại giúp căn phòng giữ được sự ấm áp sau bữa tối.', '{"wordId":"residual","ukIpa":"/rɪˈzɪdʒuəl/","usIpa":"/rɪˈzɪdʒuəl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"remaining after most of something has gone or been removed","vi":"còn sót lại; dư thừa"}],"examples":[{"en":"Residual heat kept the kitchen warm after dinner.","vi":"Hơi ấm còn sót lại giúp căn phòng giữ được sự ấm áp sau bữa tối.","audioKind":"ex"},{"en":"Residual chemicals in agricultural soil may affect water quality long after farmers stop using them.","vi":"Hóa chất tồn dư trong đất nông nghiệp có thể ảnh hưởng đến chất lượng nguồn nước lâu dài sau khi nông dân đã ngưng sử dụng chúng.","audioKind":"ex2"}],"collocations":[{"en":"residual heat","vi":"nhiệt dư"},{"en":"residual chemicals","vi":"hóa chất tồn dư"},{"en":"residual effects","vi":"tác dụng phụ còn lại"},{"en":"residual income","vi":"thu nhập thụ động"}],"wordFamily":["residue (n.)"],"synonyms":["remaining","leftover"],"antonyms":[],"tipVi":"Thường dùng trong ngữ cảnh kỹ thuật hoặc khoa học, nhấn mạnh phần còn lại sau khi xử lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hypothesis', 'en-c1-58', 'hypothesis', '/haɪˈpɑːθəsɪs/', 'C1', 'giả thuyết; giả định', 'n.', 'hypothetical (adj.), hypothetically (adv.), hypothesise (v.)', NULL, 'Dạng số nhiều là hypotheses; giả thuyết cần phải được kiểm chứng qua thực tế.', 'Our experiment tested the hypothesis that plants prefer sunlight.', NULL, 'Thí nghiệm của chúng tôi đã kiểm tra giả thuyết rằng thực vật thích ánh sáng mặt trời.', '{"wordId":"hypothesis","ukIpa":"/haɪˈpɒθəsɪs/","usIpa":"/haɪˈpɑːθəsɪs/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A proposed explanation that can be tested through research","vi":"giả thuyết; giả định"}],"examples":[{"en":"Our experiment tested the hypothesis that plants prefer sunlight.","vi":"Thí nghiệm của chúng tôi đã kiểm tra giả thuyết rằng thực vật thích ánh sáng mặt trời.","audioKind":"ex"},{"en":"Researchers tested the hypothesis that regular physical activity improves concentration among children in primary education.","vi":"Các nhà nghiên cứu đã kiểm tra giả thuyết rằng hoạt động thể chất thường xuyên giúp cải thiện khả năng tập trung ở học sinh tiểu học.","audioKind":"ex2"}],"collocations":[{"en":"test a hypothesis","vi":"kiểm tra giả thuyết"},{"en":"formulate a hypothesis","vi":"đưa ra giả thuyết"},{"en":"support a hypothesis","vi":"ủng hộ giả thuyết"},{"en":"reject a hypothesis","vi":"bác bỏ giả thuyết"}],"wordFamily":["hypothetical (adj.)","hypothetically (adv.)","hypothesise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là hypotheses; giả thuyết cần phải được kiểm chứng qua thực tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sphere', 'en-c1-58', 'sphere', '/sfɪr/', 'C1', 'hình cầu; quả cầu; lĩnh vực; phạm vi hoạt động', 'n.', 'spherical (adj.)', NULL, 'Dùng sphere cho hình khối không gian 3 chiều, còn circle dùng cho hình tròn trên mặt phẳng.', 'She rolled the clay into a smooth sphere.', NULL, 'Cô ấy nhào nặn khối đất sét thành một hình cầu mịn màng.', '{"wordId":"sphere","ukIpa":"/sfɪə/","usIpa":"/sfɪr/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A perfectly round solid shape, like a ball.","vi":"hình cầu; quả cầu"},{"pos":"n.","en":"An area of activity, knowledge, or influence.","vi":"lĩnh vực; phạm vi hoạt động"}],"examples":[{"en":"She rolled the clay into a smooth sphere.","vi":"Cô ấy nhào nặn khối đất sét thành một hình cầu mịn màng.","audioKind":"ex"},{"en":"Digital technology has expanded the sphere of education beyond classrooms, allowing students to learn almost anywhere.","vi":"Công nghệ số đã mở rộng lĩnh vực giáo dục ra ngoài khuôn khổ lớp học, cho phép học sinh học tập ở hầu như bất cứ đâu.","audioKind":"ex2"}],"collocations":[{"en":"a perfect sphere","vi":"hình cầu hoàn hảo"},{"en":"sphere of influence","vi":"vùng ảnh hưởng; phạm vi ảnh hưởng"},{"en":"the public sphere","vi":"lĩnh vực công cộng"}],"wordFamily":["spherical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng sphere cho hình khối không gian 3 chiều, còn circle dùng cho hình tròn trên mặt phẳng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mercury', 'en-c1-58', 'mercury', '/ˈmɝːkjəri/', 'C1', 'thủy ngân', 'n.', NULL, 'Đồng nghĩa: quicksilver', 'Mercury ở dạng thường chỉ kim loại thủy ngân (không đếm được); khi viết hoa Mercury có thể chỉ hành tinh Thủy Tinh.', 'This old thermometer contains mercury, so handle it carefully.', NULL, 'Chiếc nhiệt kế cũ này có chứa thủy ngân, vì vậy hãy cầm nắm thật cẩn thận.', '{"wordId":"mercury","ukIpa":"/ˈmɜːkjəri/","usIpa":"/ˈmɝːkjəri/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"A poisonous, silver-coloured metal that is liquid at room temperature.","vi":"thủy ngân"}],"examples":[{"en":"This old thermometer contains mercury, so handle it carefully.","vi":"Chiếc nhiệt kế cũ này có chứa thủy ngân, vì vậy hãy cầm nắm thật cẩn thận.","audioKind":"ex"},{"en":"Industrial mercury pollution can accumulate in fish and pose serious risks to human health.","vi":"Ô nhiễm thủy ngân từ công nghiệp có thể tích tụ trong cơ thể cá và gây ra những rủi ro nghiêm trọng cho sức khỏe con người.","audioKind":"ex2"}],"collocations":[{"en":"mercury poisoning","vi":"ngộ độc thủy ngân"},{"en":"mercury pollution","vi":"ô nhiễm thủy ngân"},{"en":"mercury thermometer","vi":"nhiệt kế thủy ngân"}],"wordFamily":[],"synonyms":["quicksilver"],"antonyms":[],"tipVi":"Mercury ở dạng thường chỉ kim loại thủy ngân (không đếm được); khi viết hoa Mercury có thể chỉ hành tinh Thủy Tinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_latent', 'en-c1-58', 'latent', '/ˈleɪtənt/', 'C1', 'tiềm ẩn; ẩn giấu; tiềm tàng', 'adj.', 'latency (n.)', 'Đồng nghĩa: dormant, hidden · Trái nghĩa: manifest', 'Chỉ những thứ đã tồn tại nhưng chưa bộc lộ ra hoặc chưa phát huy tác dụng rõ rệt.', 'Her first pottery class revealed a latent artistic talent.', NULL, 'Buổi học làm gốm đầu tiên đã khơi dậy năng khiếu nghệ thuật còn tiềm ẩn trong cô ấy.', '{"wordId":"latent","ukIpa":"/ˈleɪtənt/","usIpa":"/ˈleɪtənt/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Present but not yet active, visible, or fully developed.","vi":"tiềm ẩn; ẩn giấu; tiềm tàng"}],"examples":[{"en":"Her first pottery class revealed a latent artistic talent.","vi":"Buổi học làm gốm đầu tiên đã khơi dậy năng khiếu nghệ thuật còn tiềm ẩn trong cô ấy.","audioKind":"ex"},{"en":"Supportive teaching can help students develop latent abilities that conventional examinations may fail to identify.","vi":"Phương pháp giảng dạy mang tính hỗ trợ có thể giúp học sinh phát triển các năng lực tiềm ẩn mà những kỳ thi truyền thống có thể không phát hiện ra.","audioKind":"ex2"}],"collocations":[{"en":"latent talent","vi":"tài năng tiềm ẩn"},{"en":"latent potential","vi":"tiềm năng ẩn giấu"},{"en":"latent infection","vi":"nhiễm trùng tiềm ẩn"},{"en":"latent demand","vi":"nhu cầu tiềm năng"}],"wordFamily":["latency (n.)"],"synonyms":["dormant","hidden"],"antonyms":["manifest"],"tipVi":"Chỉ những thứ đã tồn tại nhưng chưa bộc lộ ra hoặc chưa phát huy tác dụng rõ rệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quantify', 'en-c1-58', 'quantify', '/ˈkwɑːntɪfaɪ/', 'C1', 'đo lường hoặc biểu thị số lượng của cái gì; định lượng', 'v.', 'quantity (n.), quantification (n.), quantifiable (adj.), quantitative (adj.)', 'Đồng nghĩa: measure', 'Là ngoại động từ, đi thẳng với tân ngữ: quantify the impact.', 'This app helps me quantify how much water I drink.', NULL, 'Ứng dụng này giúp tôi định lượng lượng nước mình uống mỗi ngày.', '{"wordId":"quantify","ukIpa":"/ˈkwɒntɪfaɪ/","usIpa":"/ˈkwɑːntɪfaɪ/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"to measure or express the amount of something","vi":"đo lường hoặc biểu thị số lượng của cái gì; định lượng"}],"examples":[{"en":"This app helps me quantify how much water I drink.","vi":"Ứng dụng này giúp tôi định lượng lượng nước mình uống mỗi ngày.","audioKind":"ex"},{"en":"Researchers find it difficult to quantify the long-term social benefits of investing in public libraries.","vi":"Các nhà nghiên cứu thấy khó có thể định lượng được những lợi ích xã hội lâu dài từ việc đầu tư vào các thư viện công cộng.","audioKind":"ex2"}],"collocations":[{"en":"quantify the impact","vi":"định lượng tác động"},{"en":"quantify the benefits","vi":"định lượng lợi ích"},{"en":"difficult to quantify","vi":"khó định lượng"}],"wordFamily":["quantity (n.)","quantification (n.)","quantifiable (adj.)","quantitative (adj.)"],"synonyms":["measure"],"antonyms":[],"tipVi":"Là ngoại động từ, đi thẳng với tân ngữ: quantify the impact.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discrete', 'en-c1-58', 'discrete', '/dɪˈskriːt/', 'C1', 'riêng biệt; độc lập; rời rạc', 'adj.', 'discretely (adv.), discreteness (n.)', 'Đồng nghĩa: separate, distinct · Trái nghĩa: continuous', 'Tránh nhầm lẫn với discreet (kín đáo, thận trọng); hai từ này có phát âm giống nhau.', 'We divided the project into three discrete tasks.', NULL, 'Chúng tôi chia dự án thành ba nhiệm vụ độc lập.', '{"wordId":"discrete","ukIpa":"/dɪˈskriːt/","usIpa":"/dɪˈskriːt/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Separate and distinct rather than joined or continuous.","vi":"riêng biệt; độc lập; rời rạc"}],"examples":[{"en":"We divided the project into three discrete tasks.","vi":"Chúng tôi chia dự án thành ba nhiệm vụ độc lập.","audioKind":"ex"},{"en":"Researchers classified participants into discrete groups to compare the effects of different teaching methods.","vi":"Các nhà nghiên cứu đã phân loại những người tham gia thành các nhóm riêng biệt để so sánh hiệu quả của các phương pháp giảng dạy khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"discrete categories","vi":"các danh mục riêng biệt"},{"en":"discrete units","vi":"các đơn vị độc lập"},{"en":"discrete data","vi":"dữ liệu rời rạc"}],"wordFamily":["discretely (adv.)","discreteness (n.)"],"synonyms":["separate","distinct"],"antonyms":["continuous"],"tipVi":"Tránh nhầm lẫn với discreet (kín đáo, thận trọng); hai từ này có phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fusion', 'en-c1-58', 'fusion', '/ˈfjuːʒən/', 'C1', 'sự hòa quyện; sự kết hợp thành một thể thống nhất; phản ứng hạt nhân; sự tổng hợp hạt nhân giải phóng năng lượng', 'n.', 'fuse (v.)', 'Đồng nghĩa: merging, combination · Trái nghĩa: separation', 'Phản ứng tổng hợp hạt nhân dùng fusion; phản ứng phân hạch dùng fission, cần chú ý phân biệt.', 'Her cooking is a fusion of different regional styles.', NULL, 'Cách nấu ăn của cô ấy là sự hòa quyện giữa các phong cách vùng miền khác nhau.', '{"wordId":"fusion","ukIpa":"/ˈfjuːʒən/","usIpa":"/ˈfjuːʒən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"the joining of different things into a single whole","vi":"sự hòa quyện; sự kết hợp thành một thể thống nhất"},{"pos":"n.","en":"the joining of light atomic nuclei, releasing energy","vi":"phản ứng hạt nhân; sự tổng hợp hạt nhân giải phóng năng lượng"}],"examples":[{"en":"Her cooking is a fusion of different regional styles.","vi":"Cách nấu ăn của cô ấy là sự hòa quyện giữa các phong cách vùng miền khác nhau.","audioKind":"ex"},{"en":"Scientists are investigating nuclear fusion as a potential source of abundant energy with low carbon emissions.","vi":"Các nhà khoa học đang nghiên cứu phản ứng hạt nhân như một nguồn năng lượng tiềm năng dồi dào với lượng khí thải carbon thấp.","audioKind":"ex2"}],"collocations":[{"en":"a fusion of styles","vi":"sự kết hợp các phong cách"},{"en":"fusion cuisine","vi":"ẩm thực dung hợp"},{"en":"nuclear fusion","vi":"phản ứng tổng hợp hạt nhân"}],"wordFamily":["fuse (v.)"],"synonyms":["merging","combination"],"antonyms":["separation"],"tipVi":"Phản ứng tổng hợp hạt nhân dùng fusion; phản ứng phân hạch dùng fission, cần chú ý phân biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dilute', 'en-c1-58', 'dilute', '/daɪˈluːt/', 'C1', 'làm loãng; pha loãng bằng nước hoặc chất lỏng khác; làm suy yếu; làm giảm sức mạnh, chất lượng hoặc ảnh hưởng; loãng; có nồng độ chất tan thấp', 'v.', 'dilution (n.), undiluted (adj.)', 'Đồng nghĩa: weaken · Trái nghĩa: concentrate', 'Cấu trúc dilute A with B có nghĩa là dùng chất lỏng B để pha loãng A.', 'Dilute the juice with water before giving it to children.', NULL, 'Hãy pha loãng nước trái cây với nước trước khi cho trẻ uống.', '{"wordId":"dilute","ukIpa":"/daɪˈluːt/","usIpa":"/daɪˈluːt/","cefr":"C1","topic":"science","senses":[{"pos":"v.","en":"To make a liquid weaker by adding water or another liquid.","vi":"làm loãng; pha loãng bằng nước hoặc chất lỏng khác"},{"pos":"v.","en":"To reduce the strength, quality, or influence of something.","vi":"làm suy yếu; làm giảm sức mạnh, chất lượng hoặc ảnh hưởng"},{"pos":"adj.","en":"Containing a relatively small amount of a substance in liquid.","vi":"loãng; có nồng độ chất tan thấp"}],"examples":[{"en":"Dilute the juice with water before giving it to children.","vi":"Hãy pha loãng nước trái cây với nước trước khi cho trẻ uống.","audioKind":"ex"},{"en":"Excessive commercial involvement may dilute the educational value of programmes designed for young television viewers.","vi":"Sự tham gia thương mại quá mức có thể làm suy yếu giá trị giáo dục của các chương trình truyền hình dành cho khán giả trẻ tuổi.","audioKind":"ex2"}],"collocations":[{"en":"dilute with water","vi":"pha loãng bằng nước"},{"en":"a dilute solution","vi":"dung dịch loãng"},{"en":"dilute the impact","vi":"làm giảm tác động"}],"wordFamily":["dilution (n.)","undiluted (adj.)"],"synonyms":["weaken"],"antonyms":["concentrate"],"tipVi":"Cấu trúc dilute A with B có nghĩa là dùng chất lỏng B để pha loãng A.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fermentation', 'en-c1-58', 'fermentation', '/ˌfɝːmenˈteɪʃən/', 'C1', 'sự lên men', 'n.', 'ferment (v.), fermented (adj.)', NULL, 'Thường là danh từ không đếm được; dạng động từ của nó là ferment.', 'Tiny bubbles appeared in the jar as fermentation began.', NULL, 'Những bọt khí nhỏ bắt đầu xuất hiện trong hũ khi quá trình lên men khởi động.', '{"wordId":"fermentation","ukIpa":"/ˌfɜːmenˈteɪʃən/","usIpa":"/ˌfɝːmenˈteɪʃən/","cefr":"C1","topic":"science","senses":[{"pos":"n.","en":"Microbial breakdown of sugars into substances such as acids or alcohol.","vi":"sự lên men"}],"examples":[{"en":"Tiny bubbles appeared in the jar as fermentation began.","vi":"Những bọt khí nhỏ bắt đầu xuất hiện trong hũ khi quá trình lên men khởi động.","audioKind":"ex"},{"en":"Fermentation can extend the shelf life of certain foods while also changing their flavour and texture.","vi":"Quá trình lên men có thể kéo dài thời hạn bảo quản của một số loại thực phẩm đồng thời làm thay đổi hương vị và kết cấu của chúng.","audioKind":"ex2"}],"collocations":[{"en":"the fermentation process","vi":"quá trình lên men"},{"en":"lactic acid fermentation","vi":"lên men axit lactic"},{"en":"controlled fermentation","vi":"lên men được kiểm soát"}],"wordFamily":["ferment (v.)","fermented (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; dạng động từ của nó là ferment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resultant', 'en-c1-58', 'resultant', '/rɪˈzʌltənt/', 'C1', 'do cái gì đó gây ra; hậu quả là; hợp lực; hợp vectơ', 'adj.', 'result (n.), result (v.), resulting (adj.)', 'Đồng nghĩa: resulting, consequent', 'Từ này mang tính trang trọng, thường đứng trước danh từ; trong văn phong đời thường, từ resulting được dùng phổ biến hơn.', 'A pipe burst, and the resultant flood ruined our carpet.', NULL, 'Một ống nước bị vỡ, và dòng nước tràn ra do sự cố đó đã làm hỏng tấm thảm của chúng tôi.', '{"wordId":"resultant","ukIpa":"/rɪˈzʌltənt/","usIpa":"/rɪˈzʌltənt/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Happening or existing as a result of something else.","vi":"do cái gì đó gây ra; hậu quả là"},{"pos":"n.","en":"A single vector equivalent to two or more combined vectors.","vi":"hợp lực; hợp vectơ"}],"examples":[{"en":"A pipe burst, and the resultant flood ruined our carpet.","vi":"Một ống nước bị vỡ, và dòng nước tràn ra do sự cố đó đã làm hỏng tấm thảm của chúng tôi.","audioKind":"ex"},{"en":"Rapid urban growth and the resultant demand for housing have placed considerable pressure on local infrastructure.","vi":"Sự bùng nổ đô thị nhanh chóng cùng với nhu cầu nhà ở phát sinh từ đó đã đặt ra áp lực đáng kể lên cơ sở hạ tầng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"the resultant damage","vi":"thiệt hại gây ra"},{"en":"the resultant increase","vi":"sự gia tăng do hậu quả đó"},{"en":"resultant force","vi":"hợp lực"}],"wordFamily":["result (n.)","result (v.)","resulting (adj.)"],"synonyms":["resulting","consequent"],"antonyms":[],"tipVi":"Từ này mang tính trang trọng, thường đứng trước danh từ; trong văn phong đời thường, từ resulting được dùng phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_structural', 'en-c1-58', 'structural', '/ˈstrʌktʃərəl/', 'C1', 'thuộc về cấu trúc; mang tính kết cấu', 'adj.', 'structure (n.), structure (v.), structurally (adv.), restructure (v.)', NULL, 'Có thể dùng để chỉ cấu trúc công trình kiến trúc, hoặc cấu trúc của nền kinh tế, hệ thống.', 'The builder found structural damage beneath the kitchen floor.', NULL, 'Người thợ xây đã phát hiện ra các hư hỏng kết cấu bên dưới sàn nhà bếp.', '{"wordId":"structural","ukIpa":"/ˈstrʌktʃərəl/","usIpa":"/ˈstrʌktʃərəl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Relating to how something is built or its parts are arranged.","vi":"thuộc về cấu trúc; mang tính kết cấu"}],"examples":[{"en":"The builder found structural damage beneath the kitchen floor.","vi":"Người thợ xây đã phát hiện ra các hư hỏng kết cấu bên dưới sàn nhà bếp.","audioKind":"ex"},{"en":"Reducing long-term unemployment requires structural changes to the economy rather than temporary financial support alone.","vi":"Việc giảm thất nghiệp dài hạn đòi hỏi phải có những thay đổi mang tính cấu trúc đối với nền kinh tế chứ không chỉ dựa vào sự hỗ trợ tài chính tạm thời.","audioKind":"ex2"}],"collocations":[{"en":"structural damage","vi":"hư hỏng kết cấu"},{"en":"structural change","vi":"thay đổi mang tính cấu trúc"},{"en":"structural engineering","vi":"kỹ thuật xây dựng kết cấu"},{"en":"structural reform","vi":"cải cách cơ cấu"}],"wordFamily":["structure (n.)","structure (v.)","structurally (adv.)","restructure (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng để chỉ cấu trúc công trình kiến trúc, hoặc cấu trúc của nền kinh tế, hệ thống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_radial', 'en-c1-58', 'radial', '/ˈreɪdiəl/', 'C1', 'bố trí theo hình nan hoa; tỏa ra từ tâm', 'adj.', 'radially (adv.), radius (n.)', NULL, 'Nhấn mạnh ý nghĩa lan tỏa từ tâm ra ngoài, không dùng để chỉ ánh sáng chung chung.', 'The wheel''s radial spokes gleamed in the afternoon sun.', NULL, 'Các nan hoa hình nan hoa của chiếc xe đạp lấp lánh dưới ánh nắng buổi chiều.', '{"wordId":"radial","ukIpa":"/ˈreɪdiəl/","usIpa":"/ˈreɪdiəl/","cefr":"C1","topic":"science","senses":[{"pos":"adj.","en":"Arranged along lines spreading out from a central point.","vi":"bố trí theo hình nan hoa; tỏa ra từ tâm"}],"examples":[{"en":"The wheel''s radial spokes gleamed in the afternoon sun.","vi":"Các nan hoa hình nan hoa của chiếc xe đạp lấp lánh dưới ánh nắng buổi chiều.","audioKind":"ex"},{"en":"A radial road network connects outer residential districts directly to the city centre.","vi":"Mạng lưới đường giao thông hình nan hoa kết nối trực tiếp các khu dân cư ngoại vi với trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"radial pattern","vi":"họa tiết tỏa tròn"},{"en":"radial symmetry","vi":"đối xứng tâm"},{"en":"radial road network","vi":"mạng lưới đường giao thông hướng tâm"}],"wordFamily":["radially (adv.)","radius (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh ý nghĩa lan tỏa từ tâm ra ngoài, không dùng để chỉ ánh sáng chung chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_58_1', 'en-c1-58', 'Cách dùng “optimum” (adj.) — tối ưu; thuận lợi nhất', 'optimum conditions  ·  optimum temperature  ·  optimum performance', 'Nhấn mạnh mức độ phù hợp nhất với mục tiêu chứ không có nghĩa là "càng nhiều càng tốt"; thường không đi kèm với trạng từ most.', 'Họ từ (Word Family): optimal (adj.), optimise (v.), optimisation (n.) | Đồng nghĩa: ideal, optimal · Trái nghĩa: worst', '[{"hanzi":"This sunny windowsill provides optimum conditions for my herbs.","pinyin":"","meaning":"Bệ cửa sổ đầy nắng này cung cấp điều kiện hoàn hảo nhất cho các loại rau thơm của tôi."},{"hanzi":"Maintaining the optimum classroom temperature can help students concentrate and reduce the energy required for heating.","pinyin":"","meaning":"Duy trì nhiệt độ phòng tối ưu có thể giúp học sinh tập trung và giảm năng lượng cần thiết cho việc sưởi ấm."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_58_2', 'en-c1-58', 'Cách dùng “resultant” (adj.) — do cái gì đó gây ra; hậu quả là', 'the resultant damage  ·  the resultant increase  ·  resultant force', 'Từ này mang tính trang trọng, thường đứng trước danh từ; trong văn phong đời thường, từ resulting được dùng phổ biến hơn.', 'Họ từ (Word Family): result (n.), result (v.), resulting (adj.) | Đồng nghĩa: resulting, consequent', '[{"hanzi":"A pipe burst, and the resultant flood ruined our carpet.","pinyin":"","meaning":"Một ống nước bị vỡ, và dòng nước tràn ra do sự cố đó đã làm hỏng tấm thảm của chúng tôi."},{"hanzi":"Rapid urban growth and the resultant demand for housing have placed considerable pressure on local infrastructure.","pinyin":"","meaning":"Sự bùng nổ đô thị nhanh chóng cùng với nhu cầu nhà ở phát sinh từ đó đã đặt ra áp lực đáng kể lên cơ sở hạ tầng địa phương."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_58_3', 'en-c1-58', 'Cách dùng “mercury” (n.) — thủy ngân', 'mercury poisoning  ·  mercury pollution  ·  mercury thermometer', 'Mercury ở dạng thường chỉ kim loại thủy ngân (không đếm được); khi viết hoa Mercury có thể chỉ hành tinh Thủy Tinh.', 'Đồng nghĩa: quicksilver', '[{"hanzi":"This old thermometer contains mercury, so handle it carefully.","pinyin":"","meaning":"Chiếc nhiệt kế cũ này có chứa thủy ngân, vì vậy hãy cầm nắm thật cẩn thận."},{"hanzi":"Industrial mercury pollution can accumulate in fish and pose serious risks to human health.","pinyin":"","meaning":"Ô nhiễm thủy ngân từ công nghiệp có thể tích tụ trong cơ thể cá và gây ra những rủi ro nghiêm trọng cho sức khỏe con người."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_58_4', 'en-c1-58', 'Cách dùng “specimen” (n.) — vật mẫu; tiêu bản (động vật, thực vật, vật thể phục vụ nghiên cứu)', 'collect a specimen  ·  a plant specimen  ·  a urine specimen', 'specimen thường chỉ mẫu vật phục vụ nghiên cứu hoặc kiểm tra y tế, không dùng để chỉ chung chung các ví dụ.', 'Đồng nghĩa: sample', '[{"hanzi":"The museum keeps this butterfly specimen behind glass.","pinyin":"","meaning":"Bảo tàng giữ mẫu bướm này đằng sau lớp kính."},{"hanzi":"Researchers examined each plant specimen to assess how prolonged drought had affected its growth.","pinyin":"","meaning":"Các nhà nghiên cứu đã kiểm tra từng mẫu thực vật để đánh giá mức độ ảnh hưởng của đợt hạn hán kéo dài đến sự phát triển của chúng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_58_1', 'en-c1-58', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_1_1', 'ten_c1_58_1', 'soluble', 'These soluble tablets disappear quickly in a glass of water.', 'These soluble tablets disappear quickly in a glass of water.', '/ˈsɑːljəbl/', 'Những viên thuốc sủi bọt này tan rất nhanh trong một cốc nước.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_1_2', 'ten_c1_58_1', 'catalyst', 'That conversation became the catalyst for our neighbourhood cleanup.', 'That conversation became the catalyst for our neighbourhood cleanup.', '/ˈkætəlɪst/', 'Cuộc trò chuyện hôm đó đã trở thành động lực thúc đẩy chiến dịch dọn dẹp khu phố của chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_1_3', 'ten_c1_58_1', 'velocity', 'The ball gained velocity as it rolled downhill.', 'The ball gained velocity as it rolled downhill.', '/vəˈlɑːsəti/', 'Quả bóng tăng dần vận tốc khi lăn xuống dốc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_1_4', 'ten_c1_58_1', 'ampere', 'This small lamp draws less than one ampere.', 'This small lamp draws less than one ampere.', '/ˈæmpɪr/', 'Chiếc đèn nhỏ này tiêu thụ chưa đến một an-pe.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_1_5', 'ten_c1_58_1', 'spectrum', 'Our book club welcomes a wide spectrum of opinions.', 'Our book club welcomes a wide spectrum of opinions.', '/ˈspektrəm/', 'Câu lạc bộ sách của chúng tôi hoan nghênh một phạm vi ý kiến rất rộng rãi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_1_6', 'ten_c1_58_1', 'disprove', 'The clear photograph disproved his claim about the damage.', 'The clear photograph disproved his claim about the damage.', '/dɪsˈpruːv/', 'Bức ảnh rõ nét đã bác bỏ tuyên bố của anh ấy về thiệt hại.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_1_7', 'ten_c1_58_1', 'inflammable', 'Keep inflammable liquids well away from the kitchen stove.', 'Keep inflammable liquids well away from the kitchen stove.', '/ɪnˈflæməbəl/', 'Hãy để các chất lỏng dễ cháy cách xa bếp nấu trong nhà bếp.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_1_8', 'ten_c1_58_1', 'withstand', 'These boots can withstand rain, mud, and rough paths.', 'These boots can withstand rain, mud, and rough paths.', '/wɪðˈstænd/', 'Đôi bốt này có thể chống chịu được mưa, bùn và những con đường gập ghềnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_58_1_1', 'en-c1-58', 'ten_c1_58_1', 'listening', 'listening', 'These soluble tablets disappear quickly in a glass of water.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc đèn nhỏ này tiêu thụ chưa đến một an-pe.","Những viên thuốc sủi bọt này tan rất nhanh trong một cốc nước.","Câu lạc bộ sách của chúng tôi hoan nghênh một phạm vi ý kiến rất rộng rãi.","Những bọt khí nhỏ bắt đầu xuất hiện trong hũ khi quá trình lên men khởi động."]'::jsonb, 1, 'These soluble tablets disappear quickly in a glass of water. → Những viên thuốc sủi bọt này tan rất nhanh trong một cốc nước.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_58_1_2', 'en-c1-58', 'ten_c1_58_1', 'listening', 'listening', 'That conversation became the catalyst for our neighbourhood cleanup.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy để các chất lỏng dễ cháy cách xa bếp nấu trong nhà bếp.","Các nan hoa hình nan hoa của chiếc xe đạp lấp lánh dưới ánh nắng buổi chiều.","Hơi ấm còn sót lại giúp căn phòng giữ được sự ấm áp sau bữa tối.","Cuộc trò chuyện hôm đó đã trở thành động lực thúc đẩy chiến dịch dọn dẹp khu phố của chúng tôi."]'::jsonb, 3, 'That conversation became the catalyst for our neighbourhood cleanup. → Cuộc trò chuyện hôm đó đã trở thành động lực thúc đẩy chiến dịch dọn dẹp khu phố của chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_58_1_3', 'en-c1-58', 'ten_c1_58_1', 'listening', 'listening', 'The ball gained velocity as it rolled downhill.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Quả bóng tăng dần vận tốc khi lăn xuống dốc.","Người thợ xây đã phát hiện ra các hư hỏng kết cấu bên dưới sàn nhà bếp.","Cô ấy nhào nặn khối đất sét thành một hình cầu mịn màng.","Những bọt khí nhỏ bắt đầu xuất hiện trong hũ khi quá trình lên men khởi động."]'::jsonb, 0, 'The ball gained velocity as it rolled downhill. → Quả bóng tăng dần vận tốc khi lăn xuống dốc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_58_2', 'en-c1-58', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_2_1', 'ten_c1_58_2', 'soluble', 'Water-soluble pollutants can spread through rivers, making contamination difficult to contain once it enters the water supply.', 'Water-soluble pollutants can spread through rivers, making contamination difficult to contain once it enters the water supply.', '/ˈsɑːljəbl/', 'Các chất ô nhiễm tan trong nước có thể lan truyền qua các dòng sông, khiến cho tình trạng ô nhiễm trở nên khó kiểm soát một khi đã xâm nhập vào nguồn nước.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_2_2', 'ten_c1_58_2', 'catalyst', 'Investment in public transport can act as a catalyst for wider economic growth in disadvantaged regions.', 'Investment in public transport can act as a catalyst for wider economic growth in disadvantaged regions.', '/ˈkætəlɪst/', 'Đầu tư vào giao thông công cộng có thể đóng vai trò là động lực thúc đẩy tăng trưởng kinh tế rộng lớn hơn ở các vùng còn nhiều khó khăn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_2_3', 'ten_c1_58_2', 'velocity', 'Engineers measure the velocity of flowing water to determine whether a site is suitable for generating electricity.', 'Engineers measure the velocity of flowing water to determine whether a site is suitable for generating electricity.', '/vəˈlɑːsəti/', 'Các kỹ sư đo vận tốc của dòng nước chảy để xác định xem một địa điểm có phù hợp để phát điện hay không.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_2_4', 'ten_c1_58_2', 'ampere', 'Students measured the current in amperes to compare the electrical requirements of different household appliances.', 'Students measured the current in amperes to compare the electrical requirements of different household appliances.', '/ˈæmpɪr/', 'Học sinh đo cường độ dòng điện bằng đơn vị an-pe để so sánh mức độ tiêu thụ điện của các thiết bị gia dụng khác nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_2_5', 'ten_c1_58_2', 'spectrum', 'Universities should provide support for students across the entire spectrum of academic abilities and social backgrounds.', 'Universities should provide support for students across the entire spectrum of academic abilities and social backgrounds.', '/ˈspektrəm/', 'Các trường đại học nên cung cấp sự hỗ trợ cho sinh viên ở mọi năng lực học tập và hoàn cảnh xã hội khác nhau.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_58_2_6', 'ten_c1_58_2', 'disprove', 'Researchers need reliable evidence to disprove the assumption that smaller classes always lead to better academic results.', 'Researchers need reliable evidence to disprove the assumption that smaller classes always lead to better academic results.', '/dɪsˈpruːv/', 'Các nhà nghiên cứu cần bằng chứng đáng tin cậy để bác bỏ giả định rằng các lớp học quy mô nhỏ hơn luôn mang lại kết quả học tập tốt hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_58_2_1', 'en-c1-58', 'ten_c1_58_2', 'listening', 'listening', 'Water-soluble pollutants can spread through rivers, making contamination difficult to contain once it enters the water supply.', NULL, 'Trong câu vừa nghe, từ “soluble” mang nghĩa nào sau đây?', '["công chứng viên","gợn sóng; sóng lăn tăn","chiến thắng; kiêu hãnh","có thể hòa tan trong chất lỏng"]'::jsonb, 3, '“soluble” (/ˈsɑːljəbl/): có thể hòa tan trong chất lỏng. Câu đầy đủ: Water-soluble pollutants can spread through rivers, making contamination difficult to contain once it enters the water supply.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_58_2_2', 'en-c1-58', 'ten_c1_58_2', 'listening', 'listening', 'Investment in public transport can act as a catalyst for wider economic growth in disadvantaged regions.', NULL, 'Trong câu vừa nghe, từ “catalyst” mang nghĩa nào sau đây?', '["song tính; lưỡng tính","lưu thanh cơ; máy hát đĩa cổ","có khiếm khuyết; có lỗi kỹ thuật; hỏng hóc","tác nhân thúc đẩy; người hoặc vật gây ra thay đổi"]'::jsonb, 3, '“catalyst” (/ˈkætəlɪst/): tác nhân thúc đẩy; người hoặc vật gây ra thay đổi. Câu đầy đủ: Investment in public transport can act as a catalyst for wider economic growth in disadvantaged regions.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
