INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_1', 'en-c1-58', NULL, 'comprehensive_test', 'listening', 'soluble', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có thể hòa tan trong chất lỏng","vững chắc; cường tráng; bền bỉ","khoa tâm thần; ngành tâm thần học","quyền phủ quyết; sự phủ quyết"]'::jsonb, 0, 'soluble (/ˈsɑːljəbl/) → có thể hòa tan trong chất lỏng; có thể giải quyết được', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_2', 'en-c1-58', NULL, 'comprehensive_test', 'listening', 'That conversation became the catalyst for our neighbourhood cleanup.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu lạc bộ sách của chúng tôi hoan nghênh một phạm vi ý kiến rất rộng rãi.","Đôi bốt này có thể chống chịu được mưa, bùn và những con đường gập ghềnh.","Chiếc nhiệt kế cũ này có chứa thủy ngân, vì vậy hãy cầm nắm thật cẩn thận.","Cuộc trò chuyện hôm đó đã trở thành động lực thúc đẩy chiến dịch dọn dẹp khu phố của chúng tôi."]'::jsonb, 3, 'That conversation became the catalyst for our neighbourhood cleanup. → Cuộc trò chuyện hôm đó đã trở thành động lực thúc đẩy chiến dịch dọn dẹp khu phố của chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_3', 'en-c1-58', NULL, 'comprehensive_test', 'listening', 'velocity', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bản ghi chép lời thoại; bản thảo","tạm thời; chưa chính thức","vận tốc; tốc độ","chia nhỏ; phân nhỏ"]'::jsonb, 2, 'velocity (/vəˈlɑːsəti/) → vận tốc; tốc độ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_4', 'en-c1-58', NULL, 'comprehensive_test', 'listening', 'This small lamp draws less than one ampere.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu lạc bộ sách của chúng tôi hoan nghênh một phạm vi ý kiến rất rộng rãi.","Chiếc đèn nhỏ này tiêu thụ chưa đến một an-pe.","Cuộc trò chuyện hôm đó đã trở thành động lực thúc đẩy chiến dịch dọn dẹp khu phố của chúng tôi.","Cách nấu ăn của cô ấy là sự hòa quyện giữa các phong cách vùng miền khác nhau."]'::jsonb, 1, 'This small lamp draws less than one ampere. → Chiếc đèn nhỏ này tiêu thụ chưa đến một an-pe.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_5', 'en-c1-58', NULL, 'comprehensive_test', 'listening', 'spectrum', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phạm vi; chuỗi (ý tưởng, phẩm chất, khả năng)","khoe khoang; phô trương","nhà máy bia","con chim ưng; con ưng"]'::jsonb, 0, 'spectrum (/ˈspektrəm/) → phạm vi; chuỗi (ý tưởng, phẩm chất, khả năng); quang phổ; phổ (màu sắc hoặc sóng)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_6', 'en-c1-58', NULL, 'comprehensive_test', 'listening', 'The clear photograph disproved his claim about the damage.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ứng dụng này giúp tôi định lượng lượng nước mình uống mỗi ngày.","Bức ảnh rõ nét đã bác bỏ tuyên bố của anh ấy về thiệt hại.","Hãy pha loãng nước trái cây với nước trước khi cho trẻ uống.","Người thợ xây đã phát hiện ra các hư hỏng kết cấu bên dưới sàn nhà bếp."]'::jsonb, 1, 'The clear photograph disproved his claim about the damage. → Bức ảnh rõ nét đã bác bỏ tuyên bố của anh ấy về thiệt hại.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_7', 'en-c1-58', NULL, 'comprehensive_test', 'listening', 'inflammable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trong chừng mực mà; theo như","du thuyền có khoang ngủ","thượng viện","dễ cháy; dễ bắt lửa"]'::jsonb, 3, 'inflammable (/ɪnˈflæməbəl/) → dễ cháy; dễ bắt lửa', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_8', 'en-c1-58', NULL, 'comprehensive_test', 'listening', 'These boots can withstand rain, mud, and rough paths.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những bọt khí nhỏ bắt đầu xuất hiện trong hũ khi quá trình lên men khởi động.","Đôi bốt này có thể chống chịu được mưa, bùn và những con đường gập ghềnh.","Chiếc nhiệt kế cũ này có chứa thủy ngân, vì vậy hãy cầm nắm thật cẩn thận.","Các nan hoa hình nan hoa của chiếc xe đạp lấp lánh dưới ánh nắng buổi chiều."]'::jsonb, 1, 'These boots can withstand rain, mud, and rough paths. → Đôi bốt này có thể chống chịu được mưa, bùn và những con đường gập ghềnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
