INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_17', 'en-c1-58', NULL, 'comprehensive_test', 'fill_blank', NULL, NULL, 'Điền từ thích hợp vào chỗ trống:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_18', 'en-c1-58', NULL, 'comprehensive_test', 'reading', NULL, 'Water-soluble pollutants can spread through rivers, making contamination difficult to contain once it enters the water supply.', 'Dựa vào câu trên, từ “soluble” có nghĩa phù hợp nhất là gì?', '["có thể hòa tan trong chất lỏng","thâm niên; niên hạn phục vụ","nghệ thuật thêu thùa; nghề thêu","sự thịnh vượng; sự phát đạt, sự giàu có"]'::jsonb, 0, 'soluble: có thể hòa tan trong chất lỏng; có thể giải quyết được. Dịch cả câu: Các chất ô nhiễm tan trong nước có thể lan truyền qua các dòng sông, khiến cho tình trạng ô nhiễm trở nên khó kiểm soát một khi đã xâm nhập vào nguồn nước.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_19', 'en-c1-58', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in public transport can act as a catalyst for wider economic growth in disadvantaged regions.', 'Dựa vào câu trên, từ “catalyst” có nghĩa phù hợp nhất là gì?', '["tác nhân thúc đẩy; người hoặc vật gây ra thay đổi","vòng chí tuyến","thân thiện; nồng hậu; chân tình","vật trang trí; đồ trang sức"]'::jsonb, 0, 'catalyst: tác nhân thúc đẩy; người hoặc vật gây ra thay đổi; chất xúc tác. Dịch cả câu: Đầu tư vào giao thông công cộng có thể đóng vai trò là động lực thúc đẩy tăng trưởng kinh tế rộng lớn hơn ở các vùng còn nhiều khó khăn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_20', 'en-c1-58', NULL, 'comprehensive_test', 'reading', NULL, 'Engineers measure the velocity of flowing water to determine whether a site is suitable for generating electricity.', 'Dựa vào câu trên, từ “velocity” có nghĩa phù hợp nhất là gì?', '["đánh lừa; lừa dối; khiến ai đó ảo tưởng","vận tốc; tốc độ","sự sai lệch; sự không nhất quán; sự khác biệt","ám ảnh; làm cho bận tâm lo nghĩ"]'::jsonb, 1, 'velocity: vận tốc; tốc độ. Dịch cả câu: Các kỹ sư đo vận tốc của dòng nước chảy để xác định xem một địa điểm có phù hợp để phát điện hay không.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_21', 'en-c1-58', NULL, 'comprehensive_test', 'reading', NULL, 'Students measured the current in amperes to compare the electrical requirements of different household appliances.', 'Dựa vào câu trên, từ “ampere” có nghĩa phù hợp nhất là gì?', '["an-pe","cầu cảng; bến tàu","bảng kiểm kê tài sản; danh mục hàng hóa","sự lo lắng; sự e sợ"]'::jsonb, 0, 'ampere: an-pe. Dịch cả câu: Học sinh đo cường độ dòng điện bằng đơn vị an-pe để so sánh mức độ tiêu thụ điện của các thiết bị gia dụng khác nhau.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_22', 'en-c1-58', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “do cái gì đó gây ra; hậu quả là”', '["truce","resultant","indifferent","discrete"]'::jsonb, 1, 'do cái gì đó gây ra; hậu quả là → resultant (/rɪˈzʌltənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_23', 'en-c1-58', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về cấu trúc; mang tính kết cấu”', '["structural","lubrication","notwithstanding","depict"]'::jsonb, 0, 'thuộc về cấu trúc; mang tính kết cấu → structural (/ˈstrʌktʃərəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_58_24', 'en-c1-58', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bố trí theo hình nan hoa; tỏa ra từ tâm”', '["radial","anthropology","sarcastic","civilize"]'::jsonb, 0, 'bố trí theo hình nan hoa; tỏa ra từ tâm → radial (/ˈreɪdiəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-59', 'en', 'Bài 59: Truyền thông & Tin tức - CEFR C1', 'CEFR C1', 'C1 · Truyền thông', '16 từ vựng Tiếng Anh CEFR C1 chủ đề truyền thông & tin tức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5059, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_narrate', 'en-c1-59', 'narrate', '/ˈnæreɪt/', 'C1', 'kể lại; thuật lại; thuyết minh; lồng tiếng', 'v.', 'narration (n.), narrator (n.), narrative (n.)', 'Đồng nghĩa: recount, relate', 'Là ngoại động từ, theo sau trực tiếp là câu chuyện hoặc sự kiện, không cần dùng giới từ about.', 'My grandfather loves to narrate stories from his childhood.', NULL, 'Ông tôi rất thích kể lại những câu chuyện từ thời thơ ấu của ông.', '{"wordId":"narrate","ukIpa":"/nəˈreɪt/","usIpa":"/ˈnæreɪt/","cefr":"C1","topic":"media","senses":[{"pos":"v.","en":"To tell a story or describe a series of events.","vi":"kể lại; thuật lại"},{"pos":"v.","en":"To provide spoken commentary for a film or programme.","vi":"thuyết minh; lồng tiếng"}],"examples":[{"en":"My grandfather loves to narrate stories from his childhood.","vi":"Ông tôi rất thích kể lại những câu chuyện từ thời thơ ấu của ông.","audioKind":"ex"},{"en":"Local residents narrate their experiences in the documentary, offering valuable insights into urban change.","vi":"Người dân địa phương kể lại những trải nghiệm thực tế trong bộ phim tài liệu, mang lại những góc nhìn quý giá về sự biến đổi đô thị.","audioKind":"ex2"}],"collocations":[{"en":"narrate a story","vi":"kể một câu chuyện"},{"en":"narrate a documentary","vi":"thuyết minh phim tài liệu"},{"en":"narrate events","vi":"thuật lại các sự kiện"}],"wordFamily":["narration (n.)","narrator (n.)","narrative (n.)"],"synonyms":["recount","relate"],"antonyms":[],"tipVi":"Là ngoại động từ, theo sau trực tiếp là câu chuyện hoặc sự kiện, không cần dùng giới từ about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dub', 'en-c1-59', 'dub', '/dʌb/', 'C1', 'lồng tiếng (cho phim); gọi là; mệnh danh là', 'v.', 'dubbing (n.)', 'Đồng nghĩa: nickname', 'Dạng quá khứ là dubbed; cấu trúc dub A B nghĩa là ''gọi A là B''.', 'They dubbed the cartoon into Spanish for younger viewers.', NULL, 'Họ đã lồng tiếng Tây Ban Nha cho bộ phim hoạt hình để khán giả nhỏ tuổi dễ xem hơn.', '{"wordId":"dub","ukIpa":"/dʌb/","usIpa":"/dʌb/","cefr":"C1","topic":"media","senses":[{"pos":"v.","en":"To replace a film''s original speech with another language.","vi":"lồng tiếng (cho phim)"},{"pos":"v.","en":"To give someone or something a particular name or description.","vi":"gọi là; mệnh danh là"}],"examples":[{"en":"They dubbed the cartoon into Spanish for younger viewers.","vi":"Họ đã lồng tiếng Tây Ban Nha cho bộ phim hoạt hình để khán giả nhỏ tuổi dễ xem hơn.","audioKind":"ex"},{"en":"Journalists have dubbed the new railway a lifeline for rural communities previously isolated from major employment centres.","vi":"Các nhà báo đã gọi tuyến đường sắt mới này là ''cánh tay nối dài'' cứu sinh cho các cộng đồng nông thôn vốn trước đây bị cô lập với các trung tâm việc làm lớn.","audioKind":"ex2"}],"collocations":[{"en":"dub a film","vi":"lồng tiếng phim"},{"en":"dub into English","vi":"lồng tiếng sang tiếng Anh"},{"en":"dubbed version","vi":"bản lồng tiếng"}],"wordFamily":["dubbing (n.)"],"synonyms":["nickname"],"antonyms":[],"tipVi":"Dạng quá khứ là dubbed; cấu trúc dub A B nghĩa là ''gọi A là B''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_misrepresent', 'en-c1-59', 'misrepresent', '/ˌmɪsreprɪˈzent/', 'C1', 'bóp méo; xuyên tạc; mô tả sai lệch', 'v.', 'misrepresentation (n.), represent (v.), representation (n.)', 'Đồng nghĩa: distort', 'Đây là một ngoại động từ, có thể đi thẳng với tân ngữ là sự thật, quan điểm hoặc con người.', 'That photograph misrepresents the size of our tiny kitchen.', NULL, 'Bức ảnh đó đã làm sai lệch kích thước thực tế của căn bếp nhỏ bé nhà chúng tôi.', '{"wordId":"misrepresent","ukIpa":"/ˌmɪsreprɪˈzent/","usIpa":"/ˌmɪsreprɪˈzent/","cefr":"C1","topic":"media","senses":[{"pos":"v.","en":"Describe someone or something in a false or misleading way","vi":"bóp méo; xuyên tạc; mô tả sai lệch"}],"examples":[{"en":"That photograph misrepresents the size of our tiny kitchen.","vi":"Bức ảnh đó đã làm sai lệch kích thước thực tế của căn bếp nhỏ bé nhà chúng tôi.","audioKind":"ex"},{"en":"Advertisements can misrepresent the environmental benefits of products, making it harder for consumers to make informed decisions.","vi":"Các quảng cáo có thể bóp méo những lợi ích môi trường của sản phẩm, khiến người tiêu dùng gặp khó khăn hơn trong việc đưa ra quyết định sáng suốt.","audioKind":"ex2"}],"collocations":[{"en":"misrepresent the facts","vi":"bóp méo sự thật"},{"en":"misrepresent someone''s views","vi":"xuyên tạc quan điểm của ai đó"},{"en":"misrepresent something as","vi":"gán ghép sai lệch điều gì thành"}],"wordFamily":["misrepresentation (n.)","represent (v.)","representation (n.)"],"synonyms":["distort"],"antonyms":[],"tipVi":"Đây là một ngoại động từ, có thể đi thẳng với tân ngữ là sự thật, quan điểm hoặc con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reiterate', 'en-c1-59', 'reiterate', '/riˈɪtəreɪt/', 'C1', 'nhắc lại; nhấn mạnh lại; tái khẳng định', 'v.', 'reiteration (n.)', 'Đồng nghĩa: repeat, restate', 'Là động từ, không phải tính từ; có thể đi với danh từ hoặc mệnh đề that.', 'Before we left, Dad reiterated the importance of staying together.', NULL, 'Trước khi chúng tôi rời đi, bố đã nhắc lại tầm quan trọng của việc ở bên nhau.', '{"wordId":"reiterate","ukIpa":"/riˈɪtəreɪt/","usIpa":"/riˈɪtəreɪt/","cefr":"C1","topic":"media","senses":[{"pos":"v.","en":"to say something again to make it clear or emphasise it","vi":"nhắc lại; nhấn mạnh lại; tái khẳng định"}],"examples":[{"en":"Before we left, Dad reiterated the importance of staying together.","vi":"Trước khi chúng tôi rời đi, bố đã nhắc lại tầm quan trọng của việc ở bên nhau.","audioKind":"ex"},{"en":"The report reiterates that investment in public transport is essential for reducing urban air pollution.","vi":"Báo cáo tái khẳng định rằng đầu tư vào giao thông công cộng là điều cốt yếu để giảm thiểu ô nhiễm không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"reiterate a point","vi":"nhắc lại một quan điểm"},{"en":"reiterate a commitment","vi":"tái khẳng định một cam kết"},{"en":"reiterate that","vi":"nhắc lại rằng"}],"wordFamily":["reiteration (n.)"],"synonyms":["repeat","restate"],"antonyms":[],"tipVi":"Là động từ, không phải tính từ; có thể đi với danh từ hoặc mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fabricate', 'en-c1-59', 'fabricate', '/ˈfæbrɪkeɪt/', 'C1', 'bịa đặt; ngụy tạo; chế tạo; lắp ráp', 'v.', 'fabrication (n.), fabricated (adj.), fabricator (n.)', 'Đồng nghĩa: invent, manufacture', 'Vừa có nghĩa là bịa đặt thông tin, vừa có nghĩa là sản xuất công nghiệp, cần dựa vào ngữ cảnh của tân ngữ.', 'He fabricated an excuse for missing the family dinner.', NULL, 'Anh ấy đã bịa ra một cái cớ để trốn buổi tối họp mặt gia đình.', '{"wordId":"fabricate","ukIpa":"/ˈfæbrɪkeɪt/","usIpa":"/ˈfæbrɪkeɪt/","cefr":"C1","topic":"media","senses":[{"pos":"v.","en":"To invent false information in order to deceive","vi":"bịa đặt; ngụy tạo"},{"pos":"v.","en":"To make a product or structure from separate materials","vi":"chế tạo; lắp ráp"}],"examples":[{"en":"He fabricated an excuse for missing the family dinner.","vi":"Anh ấy đã bịa ra một cái cớ để trốn buổi tối họp mặt gia đình.","audioKind":"ex"},{"en":"Researchers who fabricate evidence undermine public trust in science and may influence important policy decisions.","vi":"Những nhà nghiên cứu ngụy tạo chứng cứ sẽ làm suy yếu lòng tin của công chúng đối với khoa học và có thể ảnh hưởng đến các quyết định chính sách quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"fabricate evidence","vi":"ngụy tạo chứng cứ"},{"en":"fabricate a story","vi":"bịa đặt câu chuyện"},{"en":"fabricate an excuse","vi":"bịa đặt cái cớ"},{"en":"fabricate components","vi":"chế tạo linh kiện"}],"wordFamily":["fabrication (n.)","fabricated (adj.)","fabricator (n.)"],"synonyms":["invent","manufacture"],"antonyms":[],"tipVi":"Vừa có nghĩa là bịa đặt thông tin, vừa có nghĩa là sản xuất công nghiệp, cần dựa vào ngữ cảnh của tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ironical', 'en-c1-59', 'ironical', '/aɪˈrɑːnɪkəl/', 'C1', 'mang tính châm biếm; nói mỉa mai; đầy tính mỉa mai trớ trêu', 'adj.', 'irony (n.), ironic (adj.), ironically (adv.)', 'Đồng nghĩa: ironic', 'Đồng nghĩa cơ bản với ironic, nhưng ironic phổ biến hơn; không nhất thiết mang ý ác ý.', 'His ironical praise made it clear he disliked dinner.', NULL, 'Lời khen châm biếm của anh ấy làm rõ rằng anh ấy không thích bữa tối.', '{"wordId":"ironical","ukIpa":"/aɪˈrɒnɪkəl/","usIpa":"/aɪˈrɑːnɪkəl/","cefr":"C1","topic":"media","senses":[{"pos":"adj.","en":"expressing a meaning opposite to the words used","vi":"mang tính châm biếm; nói mỉa mai"},{"pos":"adj.","en":"strangely opposite to what would normally be expected","vi":"đầy tính mỉa mai trớ trêu"}],"examples":[{"en":"His ironical praise made it clear he disliked dinner.","vi":"Lời khen châm biếm của anh ấy làm rõ rằng anh ấy không thích bữa tối.","audioKind":"ex"},{"en":"It is ironical that technologies designed to save time can leave workers feeling busier than ever.","vi":"Thật trớ trêu khi những công nghệ được thiết kế để tiết kiệm thời gian lại có thể khiến người lao động cảm thấy bận rộn hơn bao giờ hết.","audioKind":"ex2"}],"collocations":[{"en":"an ironical remark","vi":"lời châm biếm"},{"en":"an ironical tone","vi":"giọng điệu mỉa mai"},{"en":"an ironical twist","vi":"bước ngoặt trớ trêu"}],"wordFamily":["irony (n.)","ironic (adj.)","ironically (adv.)"],"synonyms":["ironic"],"antonyms":[],"tipVi":"Đồng nghĩa cơ bản với ironic, nhưng ironic phổ biến hơn; không nhất thiết mang ý ác ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rhetoric', 'en-c1-59', 'rhetoric', '/ˈretərɪk/', 'C1', 'lời lẽ hoa mỹ; văn phong sáo rỗng; lời nói suông; thuật hùng biện; nghệ thuật tu từ', 'n.', 'rhetorical (adj.), rhetorically (adv.), rhetorician (n.)', NULL, 'Là danh từ; tính từ là rhetorical, có thể mang sắc thái chê bai.', 'We need real help, not more rhetoric about teamwork.', NULL, 'Chúng ta cần sự giúp đỡ thực sự, chứ không phải những lời nói suông về tinh thần đồng đội.', '{"wordId":"rhetoric","ukIpa":"/ˈretərɪk/","usIpa":"/ˈretərɪk/","cefr":"C1","topic":"media","senses":[{"pos":"n.","en":"Impressive language that may lack sincerity or practical substance.","vi":"lời lẽ hoa mỹ; văn phong sáo rỗng; lời nói suông"},{"pos":"n.","en":"The skill or study of using language to persuade.","vi":"thuật hùng biện; nghệ thuật tu từ"}],"examples":[{"en":"We need real help, not more rhetoric about teamwork.","vi":"Chúng ta cần sự giúp đỡ thực sự, chứ không phải những lời nói suông về tinh thần đồng đội.","audioKind":"ex"},{"en":"Governments must move beyond environmental rhetoric and introduce measurable policies to reduce industrial pollution.","vi":"Các chính phủ phải vượt qua những lời bàn suông về môi trường và đưa ra các chính sách có thể đo lường được để giảm ô nhiễm công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"empty rhetoric","vi":"lời nói sáo rỗng"},{"en":"political rhetoric","vi":"hùng biện chính trị"},{"en":"the art of rhetoric","vi":"nghệ thuật tu từ"}],"wordFamily":["rhetorical (adj.)","rhetorically (adv.)","rhetorician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ; tính từ là rhetorical, có thể mang sắc thái chê bai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_popularize', 'en-c1-59', 'popularize', '/ˈpɑːpjələraɪz/', 'C1', 'làm cho phổ biến; truyền bá; phổ biến; làm cho dễ hiểu; phổ thông hóa', 'v.', 'popular (adj.), popularity (n.), popularization (n.)', 'Đồng nghĩa: promote', 'Tiếng Anh-Anh thường viết là popularise; không chỉ mang nghĩa tuyên truyền đơn thuần.', 'Her cooking videos helped popularize this simple bean soup.', NULL, 'Các video nấu ăn của cô ấy đã giúp món súp đậu giản dị này trở nên phổ biến.', '{"wordId":"popularize","ukIpa":"/ˈpɒpjələraɪz/","usIpa":"/ˈpɑːpjələraɪz/","cefr":"C1","topic":"media","senses":[{"pos":"v.","en":"To make something widely known, liked, or used.","vi":"làm cho phổ biến; truyền bá; phổ biến"},{"pos":"v.","en":"To explain specialist knowledge so ordinary people can understand it.","vi":"làm cho dễ hiểu; phổ thông hóa"}],"examples":[{"en":"Her cooking videos helped popularize this simple bean soup.","vi":"Các video nấu ăn của cô ấy đã giúp món súp đậu giản dị này trở nên phổ biến.","audioKind":"ex"},{"en":"Public broadcasters can popularize scientific knowledge by explaining complex discoveries through accessible documentaries and practical demonstrations.","vi":"Các cơ quan phát thanh truyền hình công cộng có thể phổ biến kiến thức khoa học bằng cách giải thích các khám phá phức tạp thông qua các bộ phim tài liệu dễ tiếp cận và các phần minh họa thực tế.","audioKind":"ex2"}],"collocations":[{"en":"popularize science","vi":"phổ biến khoa học"},{"en":"popularize an idea","vi":"phổ biến một ý tưởng"},{"en":"help popularize","vi":"góp phần phổ biến"}],"wordFamily":["popular (adj.)","popularity (n.)","popularization (n.)"],"synonyms":["promote"],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường viết là popularise; không chỉ mang nghĩa tuyên truyền đơn thuần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_herald', 'en-c1-59', 'herald', '/ˈherəld/', 'C1', 'báo hiệu; báo trước; dấu hiệu; sứ giả', 'v.', NULL, 'Đồng nghĩa: signal, announce', 'Không phải là phó từ; cụm từ be heralded as có nghĩa là "được ca ngợi như là".', 'The first blossoms herald the arrival of spring.', NULL, 'Những bông hoa nở sớm đầu tiên báo hiệu mùa xuân đang đến.', '{"wordId":"herald","ukIpa":"/ˈherəld/","usIpa":"/ˈherəld/","cefr":"C1","topic":"media","senses":[{"pos":"v.","en":"To signal that something new or important is coming.","vi":"báo hiệu; báo trước"},{"pos":"n.","en":"A sign of something approaching, or an official messenger.","vi":"dấu hiệu; sứ giả"}],"examples":[{"en":"The first blossoms herald the arrival of spring.","vi":"Những bông hoa nở sớm đầu tiên báo hiệu mùa xuân đang đến.","audioKind":"ex"},{"en":"Advances in affordable energy storage could herald a new era of reliable renewable electricity for remote communities.","vi":"Sự tiến bộ của công nghệ lưu trữ năng lượng giá rẻ có thể báo trước một kỷ nguyên mới về điện năng tái tạo ổn định cho các cộng đồng vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"herald a new era","vi":"mở ra một kỷ nguyên mới"},{"en":"herald the arrival of","vi":"báo hiệu sự đến của"},{"en":"be heralded as a breakthrough","vi":"được ca ngợi như một bước đột phá"}],"wordFamily":[],"synonyms":["signal","announce"],"antonyms":[],"tipVi":"Không phải là phó từ; cụm từ be heralded as có nghĩa là \"được ca ngợi như là\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_allude', 'en-c1-59', 'allude', '/əˈluːd/', 'C1', 'ám chỉ; nói bóng gió; nhắc đến một cách gián tiếp', 'v.', 'allusion (n.), allusive (adj.)', 'Đồng nghĩa: hint', 'Luôn đi kèm giới từ allude to, không cộng trực tiếp với tân ngữ; cần tránh nhầm lẫn với elude.', 'He alluded to a surprise but gave no details.', NULL, 'Anh ấy ám chỉ sẽ có một bất ngờ nhưng không tiết lộ chi tiết nào.', '{"wordId":"allude","ukIpa":"/əˈluːd/","usIpa":"/əˈluːd/","cefr":"C1","topic":"media","senses":[{"pos":"v.","en":"to refer to something without mentioning it directly","vi":"ám chỉ; nói bóng gió; nhắc đến một cách gián tiếp"}],"examples":[{"en":"He alluded to a surprise but gave no details.","vi":"Anh ấy ám chỉ sẽ có một bất ngờ nhưng không tiết lộ chi tiết nào.","audioKind":"ex"},{"en":"The report alludes to funding difficulties without explaining how they might affect the proposed transport improvements.","vi":"Báo cáo có nhắc đến các khó khăn về tài chính mà không giải thích chúng có thể ảnh hưởng thế nào đến dự án cải thiện giao thông được đề xuất.","audioKind":"ex2"}],"collocations":[{"en":"allude to a problem","vi":"ám chỉ một vấn đề"},{"en":"allude to the past","vi":"nhắc bóng gió về quá khứ"}],"wordFamily":["allusion (n.)","allusive (adj.)"],"synonyms":["hint"],"antonyms":[],"tipVi":"Luôn đi kèm giới từ allude to, không cộng trực tiếp với tân ngữ; cần tránh nhầm lẫn với elude.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_periodical', 'en-c1-59', 'periodical', '/ˌpɪriˈɑːdɪkəl/', 'C1', 'tập san; tạp chí định kỳ; định kỳ; theo chu kỳ', 'n.', 'period (n.), periodic (adj.), periodically (adv.)', 'Đồng nghĩa: journal, magazine', 'Danh từ chỉ tạp chí; khi nói về việc xảy ra định kỳ thì dùng tính từ periodic phổ biến hơn.', 'The library keeps that periodical beside the newspapers.', NULL, 'Thư viện để tập san đó ngay cạnh khu vực báo chí.', '{"wordId":"periodical","ukIpa":"/ˌpɪəriˈɒdɪkəl/","usIpa":"/ˌpɪriˈɑːdɪkəl/","cefr":"C1","topic":"media","senses":[{"pos":"n.","en":"A publication released regularly, containing articles on particular subjects.","vi":"tập san; tạp chí định kỳ"},{"pos":"adj.","en":"Happening or appearing repeatedly at intervals.","vi":"định kỳ; theo chu kỳ"}],"examples":[{"en":"The library keeps that periodical beside the newspapers.","vi":"Thư viện để tập san đó ngay cạnh khu vực báo chí.","audioKind":"ex"},{"en":"Academic periodicals allow researchers to share findings, although subscription costs can limit access for smaller institutions.","vi":"Các tạp chí học thuật giúp các nhà nghiên cứu chia sẻ phát hiện, mặc dù chi phí đặt mua có thể hạn chế khả năng tiếp cận của các cơ quan quy mô nhỏ hơn.","audioKind":"ex2"}],"collocations":[{"en":"academic periodical","vi":"tạp chí học thuật"},{"en":"monthly periodical","vi":"tập san hàng tháng"},{"en":"periodical publication","vi":"ấn phẩm định kỳ"}],"wordFamily":["period (n.)","periodic (adj.)","periodically (adv.)"],"synonyms":["journal","magazine"],"antonyms":[],"tipVi":"Danh từ chỉ tạp chí; khi nói về việc xảy ra định kỳ thì dùng tính từ periodic phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distortion', 'en-c1-59', 'distortion', '/dɪˈstɔːrʃən/', 'C1', 'sự bóp méo; sự xuyên tạc; sự biến dạng; sự méo mó', 'n.', 'distort (v.), distorted (adj.)', 'Đồng nghĩa: misrepresentation', 'distortion of the facts chỉ sự bóp méo sự thật.', 'His version of our conversation was a complete distortion.', NULL, 'Cách anh ta kể lại cuộc trò chuyện của chúng tôi hoàn toàn là một sự xuyên tạc.', '{"wordId":"distortion","ukIpa":"/dɪˈstɔːʃən/","usIpa":"/dɪˈstɔːrʃən/","cefr":"C1","topic":"media","senses":[{"pos":"n.","en":"A misleading change in how facts or ideas are presented.","vi":"sự bóp méo; sự xuyên tạc"},{"pos":"n.","en":"An unwanted change in shape, sound, or appearance.","vi":"sự biến dạng; sự méo mó"}],"examples":[{"en":"His version of our conversation was a complete distortion.","vi":"Cách anh ta kể lại cuộc trò chuyện của chúng tôi hoàn toàn là một sự xuyên tạc.","audioKind":"ex"},{"en":"The distortion of scientific findings in news reports can undermine public understanding of health risks.","vi":"Việc bóp méo các kết quả nghiên cứu khoa học trong các bản tin có thể làm xói mòn sự hiểu biết của công chúng về các rủi ro sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"a distortion of the facts","vi":"sự bóp méo sự thật"},{"en":"image distortion","vi":"sự méo hình"},{"en":"sound distortion","vi":"sự méo âm"}],"wordFamily":["distort (v.)","distorted (adj.)"],"synonyms":["misrepresentation"],"antonyms":[],"tipVi":"distortion of the facts chỉ sự bóp méo sự thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eloquent', 'en-c1-59', 'eloquent', '/ˈeləkwənt/', 'C1', 'hùng biện; có sức thuyết phục cao; thể hiện rõ ràng ý nghĩa hoặc cảm xúc (không cần dùng lời)', 'adj.', 'eloquence (n.), eloquently (adv.)', 'Đồng nghĩa: articulate, expressive · Trái nghĩa: inarticulate', 'Không chỉ dùng để mô tả tài ăn nói, mà còn có thể diễn tả ánh mắt hoặc sự im lặng mang nhiều ý nghĩa sâu sắc.', 'Her eloquent speech moved everyone in the room.', NULL, 'Bài phát biểu đầy sức thuyết phục của cô ấy đã làm rung động tất cả mọi người trong phòng.', '{"wordId":"eloquent","ukIpa":"/ˈeləkwənt/","usIpa":"/ˈeləkwənt/","cefr":"C1","topic":"media","senses":[{"pos":"adj.","en":"Expressing ideas clearly, powerfully, and beautifully.","vi":"hùng biện; có sức thuyết phục cao"},{"pos":"adj.","en":"Clearly expressing a feeling or meaning without words.","vi":"thể hiện rõ ràng ý nghĩa hoặc cảm xúc (không cần dùng lời)"}],"examples":[{"en":"Her eloquent speech moved everyone in the room.","vi":"Bài phát biểu đầy sức thuyết phục của cô ấy đã làm rung động tất cả mọi người trong phòng.","audioKind":"ex"},{"en":"The speaker offered an eloquent defence of public libraries as essential spaces for lifelong learning.","vi":"Diễn giả đã có một bài biện hộ vô cùng thuyết phục về các thư viện công cộng như những không gian thiết yếu cho việc học tập suốt đời.","audioKind":"ex2"}],"collocations":[{"en":"an eloquent speaker","vi":"một diễn giả tài năng hùng biện"},{"en":"an eloquent defence","vi":"một lời biện hộ đanh thép"},{"en":"an eloquent silence","vi":"sự im lặng đầy ý nghĩa"}],"wordFamily":["eloquence (n.)","eloquently (adv.)"],"synonyms":["articulate","expressive"],"antonyms":["inarticulate"],"tipVi":"Không chỉ dùng để mô tả tài ăn nói, mà còn có thể diễn tả ánh mắt hoặc sự im lặng mang nhiều ý nghĩa sâu sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distort', 'en-c1-59', 'distort', '/dɪˈstɔːrt/', 'C1', 'bóp méo; xuyên tạc; làm biến dạng; làm mất âm', 'v.', 'distortion (n.), distorted (adj.)', 'Đồng nghĩa: misrepresent, twist', 'Có thể chỉ sự bóp méo sự thật, cũng có thể chỉ hình ảnh hoặc âm thanh bị mất âm, biến dạng.', 'That edited clip distorts what I actually said.', NULL, 'Đoạn video được cắt ghép đó đã bóp méo những gì tôi thực sự đã nói.', '{"wordId":"distort","ukIpa":"/dɪˈstɔːt/","usIpa":"/dɪˈstɔːrt/","cefr":"C1","topic":"media","senses":[{"pos":"v.","en":"to present information in a misleading or inaccurate way","vi":"bóp méo; xuyên tạc"},{"pos":"v.","en":"to change the natural shape, appearance, or sound of something","vi":"làm biến dạng; làm mất âm"}],"examples":[{"en":"That edited clip distorts what I actually said.","vi":"Đoạn video được cắt ghép đó đã bóp méo những gì tôi thực sự đã nói.","audioKind":"ex"},{"en":"Selective reporting can distort public understanding of environmental issues and weaken support for necessary reforms.","vi":"Việc đưa tin chọn lọc có thể bóp méo nhận thức của công chúng về các vấn đề môi trường và làm suy yếu sự ủng hộ đối với các cải cách cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"distort the truth","vi":"bóp méo sự thật"},{"en":"distort an image","vi":"làm biến dạng hình ảnh"},{"en":"distort public perception","vi":"làm lệch lạc nhận thức công chúng"}],"wordFamily":["distortion (n.)","distorted (adj.)"],"synonyms":["misrepresent","twist"],"antonyms":[],"tipVi":"Có thể chỉ sự bóp méo sự thật, cũng có thể chỉ hình ảnh hoặc âm thanh bị mất âm, biến dạng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obscene', 'en-c1-59', 'obscene', '/əbˈsiːn/', 'C1', 'khiêu dâm; đồi trụy; tục tĩu; cao đến mức vô lý; nhiều đến mức bất công gây phẫn nộ', 'adj.', 'obscenity (n.), obscenely (adv.)', 'Đồng nghĩa: indecent, lewd · Trái nghĩa: decent', 'Có mức độ mạnh hơn rude; cũng dùng để chỉ tiền bạc hoặc số lượng nhiều quá mức gây phẫn nộ.', 'The moderator removed an obscene comment from the chat.', NULL, 'Người kiểm duyệt đã xóa một bình luận mang tính tục tĩu khỏi khung chat.', '{"wordId":"obscene","ukIpa":"/əbˈsiːn/","usIpa":"/əbˈsiːn/","cefr":"C1","topic":"media","senses":[{"pos":"adj.","en":"offensively sexual in a way considered unacceptable","vi":"khiêu dâm; đồi trụy; tục tĩu"},{"pos":"adj.","en":"so excessive or unfair that it causes moral outrage","vi":"cao đến mức vô lý; nhiều đến mức bất công gây phẫn nộ"}],"examples":[{"en":"The moderator removed an obscene comment from the chat.","vi":"Người kiểm duyệt đã xóa một bình luận mang tính tục tĩu khỏi khung chat.","audioKind":"ex"},{"en":"Critics argue that obscene executive bonuses are difficult to justify when ordinary workers face wage cuts.","vi":"Các nhà phê bình cho rằng các khoản tiền thưởng cao ngất ngưởng của giới lãnh đạo là rất khó biện minh khi những người lao động bình thường phải đối mặt với việc bị cắt giảm lương.","audioKind":"ex2"}],"collocations":[{"en":"obscene language","vi":"ngôn từ tục tĩu"},{"en":"obscene material","vi":"tài liệu đồi trụy"},{"en":"an obscene amount of money","vi":"một số tiền lớn đến mức vô lý"}],"wordFamily":["obscenity (n.)","obscenely (adv.)"],"synonyms":["indecent","lewd"],"antonyms":["decent"],"tipVi":"Có mức độ mạnh hơn rude; cũng dùng để chỉ tiền bạc hoặc số lượng nhiều quá mức gây phẫn nộ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_revelation', 'en-c1-59', 'revelation', '/ˌrevəˈleɪʃn/', 'C1', 'phát hiện bất ngờ; sự thật được phơi bày; sự tiết lộ; sự phơi bày', 'n.', 'reveal (v.), revealing (adj.)', 'Đồng nghĩa: disclosure', 'Đếm được khi chỉ một phát hiện mới cụ thể; thường không đếm được khi chỉ hành động tiết lộ.', 'His revelation about the hidden garden surprised us all.', NULL, 'Việc anh ấy tiết lộ về khu vườn bí mật đã khiến tất cả chúng tôi ngạc nhiên.', '{"wordId":"revelation","ukIpa":"/ˌrevəˈleɪʃn/","usIpa":"/ˌrevəˈleɪʃn/","cefr":"C1","topic":"media","senses":[{"pos":"n.","en":"A surprising fact that becomes known.","vi":"phát hiện bất ngờ; sự thật được phơi bày"},{"pos":"n.","en":"The act of making previously hidden information known.","vi":"sự tiết lộ; sự phơi bày"}],"examples":[{"en":"His revelation about the hidden garden surprised us all.","vi":"Việc anh ấy tiết lộ về khu vườn bí mật đã khiến tất cả chúng tôi ngạc nhiên.","audioKind":"ex"},{"en":"Recent revelations about industrial pollution have increased public pressure for stricter environmental regulations and greater corporate transparency.","vi":"Những tiết lộ gần đây về tình trạng ô nhiễm công nghiệp đã làm gia tăng áp lực từ công chúng đòi hỏi các quy định môi trường nghiêm ngặt hơn và sự minh bạch lớn hơn từ doanh nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"a startling revelation","vi":"một phát hiện gây sửng sốt"},{"en":"revelations about","vi":"những tiết lộ về"},{"en":"come as a revelation","vi":"mang lại sự giác ngộ bất ngờ"}],"wordFamily":["reveal (v.)","revealing (adj.)"],"synonyms":["disclosure"],"antonyms":[],"tipVi":"Đếm được khi chỉ một phát hiện mới cụ thể; thường không đếm được khi chỉ hành động tiết lộ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_59_1', 'en-c1-59', 'Cách dùng “eloquent” (adj.) — hùng biện; có sức thuyết phục cao', 'an eloquent speaker  ·  an eloquent defence  ·  an eloquent silence', 'Không chỉ dùng để mô tả tài ăn nói, mà còn có thể diễn tả ánh mắt hoặc sự im lặng mang nhiều ý nghĩa sâu sắc.', 'Họ từ (Word Family): eloquence (n.), eloquently (adv.) | Đồng nghĩa: articulate, expressive · Trái nghĩa: inarticulate', '[{"hanzi":"Her eloquent speech moved everyone in the room.","pinyin":"","meaning":"Bài phát biểu đầy sức thuyết phục của cô ấy đã làm rung động tất cả mọi người trong phòng."},{"hanzi":"The speaker offered an eloquent defence of public libraries as essential spaces for lifelong learning.","pinyin":"","meaning":"Diễn giả đã có một bài biện hộ vô cùng thuyết phục về các thư viện công cộng như những không gian thiết yếu cho việc học tập suốt đời."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_59_2', 'en-c1-59', 'Cách dùng “fabricate” (v.) — bịa đặt; ngụy tạo', 'fabricate evidence  ·  fabricate a story  ·  fabricate an excuse', 'Vừa có nghĩa là bịa đặt thông tin, vừa có nghĩa là sản xuất công nghiệp, cần dựa vào ngữ cảnh của tân ngữ.', 'Họ từ (Word Family): fabrication (n.), fabricated (adj.), fabricator (n.) | Đồng nghĩa: invent, manufacture', '[{"hanzi":"He fabricated an excuse for missing the family dinner.","pinyin":"","meaning":"Anh ấy đã bịa ra một cái cớ để trốn buổi tối họp mặt gia đình."},{"hanzi":"Researchers who fabricate evidence undermine public trust in science and may influence important policy decisions.","pinyin":"","meaning":"Những nhà nghiên cứu ngụy tạo chứng cứ sẽ làm suy yếu lòng tin của công chúng đối với khoa học và có thể ảnh hưởng đến các quyết định chính sách quan trọng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_59_3', 'en-c1-59', 'Cách dùng “narrate” (v.) — kể lại; thuật lại', 'narrate a story  ·  narrate a documentary  ·  narrate events', 'Là ngoại động từ, theo sau trực tiếp là câu chuyện hoặc sự kiện, không cần dùng giới từ about.', 'Họ từ (Word Family): narration (n.), narrator (n.), narrative (n.) | Đồng nghĩa: recount, relate', '[{"hanzi":"My grandfather loves to narrate stories from his childhood.","pinyin":"","meaning":"Ông tôi rất thích kể lại những câu chuyện từ thời thơ ấu của ông."},{"hanzi":"Local residents narrate their experiences in the documentary, offering valuable insights into urban change.","pinyin":"","meaning":"Người dân địa phương kể lại những trải nghiệm thực tế trong bộ phim tài liệu, mang lại những góc nhìn quý giá về sự biến đổi đô thị."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_59_4', 'en-c1-59', 'Cách dùng “allude” (v.) — ám chỉ; nói bóng gió; nhắc đến một cách gián tiếp', 'allude to a problem  ·  allude to the past', 'Luôn đi kèm giới từ allude to, không cộng trực tiếp với tân ngữ; cần tránh nhầm lẫn với elude.', 'Họ từ (Word Family): allusion (n.), allusive (adj.) | Đồng nghĩa: hint', '[{"hanzi":"He alluded to a surprise but gave no details.","pinyin":"","meaning":"Anh ấy ám chỉ sẽ có một bất ngờ nhưng không tiết lộ chi tiết nào."},{"hanzi":"The report alludes to funding difficulties without explaining how they might affect the proposed transport improvements.","pinyin":"","meaning":"Báo cáo có nhắc đến các khó khăn về tài chính mà không giải thích chúng có thể ảnh hưởng thế nào đến dự án cải thiện giao thông được đề xuất."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_59_1', 'en-c1-59', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
