INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_1_2', 'ten_c1_59_1', 'dub', 'They dubbed the cartoon into Spanish for younger viewers.', 'They dubbed the cartoon into Spanish for younger viewers.', '/dʌb/', 'Họ đã lồng tiếng Tây Ban Nha cho bộ phim hoạt hình để khán giả nhỏ tuổi dễ xem hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_1_3', 'ten_c1_59_1', 'misrepresent', 'That photograph misrepresents the size of our tiny kitchen.', 'That photograph misrepresents the size of our tiny kitchen.', '/ˌmɪsreprɪˈzent/', 'Bức ảnh đó đã làm sai lệch kích thước thực tế của căn bếp nhỏ bé nhà chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_1_4', 'ten_c1_59_1', 'reiterate', 'Before we left, Dad reiterated the importance of staying together.', 'Before we left, Dad reiterated the importance of staying together.', '/riˈɪtəreɪt/', 'Trước khi chúng tôi rời đi, bố đã nhắc lại tầm quan trọng của việc ở bên nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_1_5', 'ten_c1_59_1', 'fabricate', 'He fabricated an excuse for missing the family dinner.', 'He fabricated an excuse for missing the family dinner.', '/ˈfæbrɪkeɪt/', 'Anh ấy đã bịa ra một cái cớ để trốn buổi tối họp mặt gia đình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_1_6', 'ten_c1_59_1', 'ironical', 'His ironical praise made it clear he disliked dinner.', 'His ironical praise made it clear he disliked dinner.', '/aɪˈrɑːnɪkəl/', 'Lời khen châm biếm của anh ấy làm rõ rằng anh ấy không thích bữa tối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_1_7', 'ten_c1_59_1', 'rhetoric', 'We need real help, not more rhetoric about teamwork.', 'We need real help, not more rhetoric about teamwork.', '/ˈretərɪk/', 'Chúng ta cần sự giúp đỡ thực sự, chứ không phải những lời nói suông về tinh thần đồng đội.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_1_8', 'ten_c1_59_1', 'popularize', 'Her cooking videos helped popularize this simple bean soup.', 'Her cooking videos helped popularize this simple bean soup.', '/ˈpɑːpjələraɪz/', 'Các video nấu ăn của cô ấy đã giúp món súp đậu giản dị này trở nên phổ biến.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_59_1_1', 'en-c1-59', 'ten_c1_59_1', 'listening', 'listening', 'My grandfather loves to narrate stories from his childhood.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người kiểm duyệt đã xóa một bình luận mang tính tục tĩu khỏi khung chat.","Lời khen châm biếm của anh ấy làm rõ rằng anh ấy không thích bữa tối.","Bài phát biểu đầy sức thuyết phục của cô ấy đã làm rung động tất cả mọi người trong phòng.","Ông tôi rất thích kể lại những câu chuyện từ thời thơ ấu của ông."]'::jsonb, 3, 'My grandfather loves to narrate stories from his childhood. → Ông tôi rất thích kể lại những câu chuyện từ thời thơ ấu của ông.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_59_1_2', 'en-c1-59', 'ten_c1_59_1', 'listening', 'listening', 'They dubbed the cartoon into Spanish for younger viewers.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thư viện để tập san đó ngay cạnh khu vực báo chí.","Bài phát biểu đầy sức thuyết phục của cô ấy đã làm rung động tất cả mọi người trong phòng.","Cách anh ta kể lại cuộc trò chuyện của chúng tôi hoàn toàn là một sự xuyên tạc.","Họ đã lồng tiếng Tây Ban Nha cho bộ phim hoạt hình để khán giả nhỏ tuổi dễ xem hơn."]'::jsonb, 3, 'They dubbed the cartoon into Spanish for younger viewers. → Họ đã lồng tiếng Tây Ban Nha cho bộ phim hoạt hình để khán giả nhỏ tuổi dễ xem hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_59_1_3', 'en-c1-59', 'ten_c1_59_1', 'listening', 'listening', 'That photograph misrepresents the size of our tiny kitchen.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy ám chỉ sẽ có một bất ngờ nhưng không tiết lộ chi tiết nào.","Trước khi chúng tôi rời đi, bố đã nhắc lại tầm quan trọng của việc ở bên nhau.","Cách anh ta kể lại cuộc trò chuyện của chúng tôi hoàn toàn là một sự xuyên tạc.","Bức ảnh đó đã làm sai lệch kích thước thực tế của căn bếp nhỏ bé nhà chúng tôi."]'::jsonb, 3, 'That photograph misrepresents the size of our tiny kitchen. → Bức ảnh đó đã làm sai lệch kích thước thực tế của căn bếp nhỏ bé nhà chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_59_2', 'en-c1-59', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_2_1', 'ten_c1_59_2', 'narrate', 'Local residents narrate their experiences in the documentary, offering valuable insights into urban change.', 'Local residents narrate their experiences in the documentary, offering valuable insights into urban change.', '/ˈnæreɪt/', 'Người dân địa phương kể lại những trải nghiệm thực tế trong bộ phim tài liệu, mang lại những góc nhìn quý giá về sự biến đổi đô thị.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_2_2', 'ten_c1_59_2', 'dub', 'Journalists have dubbed the new railway a lifeline for rural communities previously isolated from major employment centres.', 'Journalists have dubbed the new railway a lifeline for rural communities previously isolated from major employment centres.', '/dʌb/', 'Các nhà báo đã gọi tuyến đường sắt mới này là ''cánh tay nối dài'' cứu sinh cho các cộng đồng nông thôn vốn trước đây bị cô lập với các trung tâm việc làm lớn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_2_3', 'ten_c1_59_2', 'misrepresent', 'Advertisements can misrepresent the environmental benefits of products, making it harder for consumers to make informed decisions.', 'Advertisements can misrepresent the environmental benefits of products, making it harder for consumers to make informed decisions.', '/ˌmɪsreprɪˈzent/', 'Các quảng cáo có thể bóp méo những lợi ích môi trường của sản phẩm, khiến người tiêu dùng gặp khó khăn hơn trong việc đưa ra quyết định sáng suốt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_2_4', 'ten_c1_59_2', 'reiterate', 'The report reiterates that investment in public transport is essential for reducing urban air pollution.', 'The report reiterates that investment in public transport is essential for reducing urban air pollution.', '/riˈɪtəreɪt/', 'Báo cáo tái khẳng định rằng đầu tư vào giao thông công cộng là điều cốt yếu để giảm thiểu ô nhiễm không khí đô thị.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_2_5', 'ten_c1_59_2', 'fabricate', 'Researchers who fabricate evidence undermine public trust in science and may influence important policy decisions.', 'Researchers who fabricate evidence undermine public trust in science and may influence important policy decisions.', '/ˈfæbrɪkeɪt/', 'Những nhà nghiên cứu ngụy tạo chứng cứ sẽ làm suy yếu lòng tin của công chúng đối với khoa học và có thể ảnh hưởng đến các quyết định chính sách quan trọng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_59_2_6', 'ten_c1_59_2', 'ironical', 'It is ironical that technologies designed to save time can leave workers feeling busier than ever.', 'It is ironical that technologies designed to save time can leave workers feeling busier than ever.', '/aɪˈrɑːnɪkəl/', 'Thật trớ trêu khi những công nghệ được thiết kế để tiết kiệm thời gian lại có thể khiến người lao động cảm thấy bận rộn hơn bao giờ hết.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_59_2_1', 'en-c1-59', 'ten_c1_59_2', 'listening', 'listening', 'Local residents narrate their experiences in the documentary, offering valuable insights into urban change.', NULL, 'Trong câu vừa nghe, từ “narrate” mang nghĩa nào sau đây?', '["chịu đựng; chống lại; trụ vững","kể lại; thuật lại","sứ mệnh; công việc phù hợp với tâm huyết bản thân","khổ sở; khốn khổ; bất hạnh"]'::jsonb, 1, '“narrate” (/ˈnæreɪt/): kể lại; thuật lại. Câu đầy đủ: Local residents narrate their experiences in the documentary, offering valuable insights into urban change.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_59_2_2', 'en-c1-59', 'ten_c1_59_2', 'listening', 'listening', 'Journalists have dubbed the new railway a lifeline for rural communities previously isolated from major employment centres.', NULL, 'Trong câu vừa nghe, từ “dub” mang nghĩa nào sau đây?', '["sự cuồng nhiệt; niềm đam mê lớn","biểu thị; chỉ rõ","sự thành lập; sự thiết lập","lồng tiếng (cho phim)"]'::jsonb, 3, '“dub” (/dʌb/): lồng tiếng (cho phim). Câu đầy đủ: Journalists have dubbed the new railway a lifeline for rural communities previously isolated from major employment centres.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
