INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_2', 'en-c1-59', NULL, 'comprehensive_test', 'listening', 'They dubbed the cartoon into Spanish for younger viewers.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông tôi rất thích kể lại những câu chuyện từ thời thơ ấu của ông.","Bài phát biểu đầy sức thuyết phục của cô ấy đã làm rung động tất cả mọi người trong phòng.","Anh ấy ám chỉ sẽ có một bất ngờ nhưng không tiết lộ chi tiết nào.","Họ đã lồng tiếng Tây Ban Nha cho bộ phim hoạt hình để khán giả nhỏ tuổi dễ xem hơn."]'::jsonb, 3, 'They dubbed the cartoon into Spanish for younger viewers. → Họ đã lồng tiếng Tây Ban Nha cho bộ phim hoạt hình để khán giả nhỏ tuổi dễ xem hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_3', 'en-c1-59', NULL, 'comprehensive_test', 'listening', 'misrepresent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bóp méo; xuyên tạc; mô tả sai lệch","sự cạn kiệt; sự suy giảm","làm mất hiệu lực pháp lý (hợp đồng, thỏa thuận, quyết định)","lỗi thời; cổ lỗ sĩ; cũ kỹ"]'::jsonb, 0, 'misrepresent (/ˌmɪsreprɪˈzent/) → bóp méo; xuyên tạc; mô tả sai lệch', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_4', 'en-c1-59', NULL, 'comprehensive_test', 'listening', 'Before we left, Dad reiterated the importance of staying together.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đoạn video được cắt ghép đó đã bóp méo những gì tôi thực sự đã nói.","Các video nấu ăn của cô ấy đã giúp món súp đậu giản dị này trở nên phổ biến.","Trước khi chúng tôi rời đi, bố đã nhắc lại tầm quan trọng của việc ở bên nhau.","Lời khen châm biếm của anh ấy làm rõ rằng anh ấy không thích bữa tối."]'::jsonb, 2, 'Before we left, Dad reiterated the importance of staying together. → Trước khi chúng tôi rời đi, bố đã nhắc lại tầm quan trọng của việc ở bên nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_5', 'en-c1-59', NULL, 'comprehensive_test', 'listening', 'fabricate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trụ cột gia đình; người kiếm tiền nuôi gia đình","nâng lên; đưa lên cao","tận dụng; sử dụng hiệu quả","bịa đặt; ngụy tạo"]'::jsonb, 3, 'fabricate (/ˈfæbrɪkeɪt/) → bịa đặt; ngụy tạo; chế tạo; lắp ráp', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_6', 'en-c1-59', NULL, 'comprehensive_test', 'listening', 'His ironical praise made it clear he disliked dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lời khen châm biếm của anh ấy làm rõ rằng anh ấy không thích bữa tối.","Những bông hoa nở sớm đầu tiên báo hiệu mùa xuân đang đến.","Người kiểm duyệt đã xóa một bình luận mang tính tục tĩu khỏi khung chat.","Anh ấy ám chỉ sẽ có một bất ngờ nhưng không tiết lộ chi tiết nào."]'::jsonb, 0, 'His ironical praise made it clear he disliked dinner. → Lời khen châm biếm của anh ấy làm rõ rằng anh ấy không thích bữa tối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_7', 'en-c1-59', NULL, 'comprehensive_test', 'listening', 'rhetoric', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm hài lòng; làm thỏa mãn","chia nhỏ; phân nhỏ","lời lẽ hoa mỹ; văn phong sáo rỗng; lời nói suông","hình thành ý tưởng; tưởng tượng"]'::jsonb, 2, 'rhetoric (/ˈretərɪk/) → lời lẽ hoa mỹ; văn phong sáo rỗng; lời nói suông; thuật hùng biện; nghệ thuật tu từ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_8', 'en-c1-59', NULL, 'comprehensive_test', 'listening', 'Her cooking videos helped popularize this simple bean soup.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng ta cần sự giúp đỡ thực sự, chứ không phải những lời nói suông về tinh thần đồng đội.","Bài phát biểu đầy sức thuyết phục của cô ấy đã làm rung động tất cả mọi người trong phòng.","Các video nấu ăn của cô ấy đã giúp món súp đậu giản dị này trở nên phổ biến.","Bức ảnh đó đã làm sai lệch kích thước thực tế của căn bếp nhỏ bé nhà chúng tôi."]'::jsonb, 2, 'Her cooking videos helped popularize this simple bean soup. → Các video nấu ăn của cô ấy đã giúp món súp đậu giản dị này trở nên phổ biến.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_9', 'en-c1-59', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To invent false information in order to deceive”?', '["distort","popularize","rhetoric","fabricate"]'::jsonb, 3, 'fabricate (/ˈfæbrɪkeɪt/) → bịa đặt; ngụy tạo', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_10', 'en-c1-59', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “expressing a meaning opposite to the words used”?', '["herald","rhetoric","ironical","obscene"]'::jsonb, 2, 'ironical (/aɪˈrɑːnɪkəl/) → mang tính châm biếm; nói mỉa mai', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_11', 'en-c1-59', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Impressive language that may lack sincerity or practical substance.”?', '["revelation","rhetoric","dub","distortion"]'::jsonb, 1, 'rhetoric (/ˈretərɪk/) → lời lẽ hoa mỹ; văn phong sáo rỗng; lời nói suông', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_12', 'en-c1-59', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To make something widely known, liked, or used.”?', '["herald","fabricate","popularize","dub"]'::jsonb, 2, 'popularize (/ˈpɑːpjələraɪz/) → làm cho phổ biến; truyền bá; phổ biến', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_13', 'en-c1-59', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To signal that something new or important is coming.”?', '["herald","revelation","ironical","obscene"]'::jsonb, 0, 'herald (/ˈherəld/) → báo hiệu; báo trước', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
