INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_18', 'en-c1-59', NULL, 'comprehensive_test', 'reading', NULL, 'Local residents narrate their experiences in the documentary, offering valuable insights into urban change.', 'Dựa vào câu trên, từ “narrate” có nghĩa phù hợp nhất là gì?', '["hàn (nối các chi tiết kim loại bằng cách nung nóng cho đến khi chúng chảy dính vào nhau)","nồi hấp; xửng hấp","chi phí; khoản chi; vốn đầu tư ban đầu","kể lại; thuật lại"]'::jsonb, 3, 'narrate: kể lại; thuật lại; thuyết minh; lồng tiếng. Dịch cả câu: Người dân địa phương kể lại những trải nghiệm thực tế trong bộ phim tài liệu, mang lại những góc nhìn quý giá về sự biến đổi đô thị.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_19', 'en-c1-59', NULL, 'comprehensive_test', 'reading', NULL, 'Journalists have dubbed the new railway a lifeline for rural communities previously isolated from major employment centres.', 'Dựa vào câu trên, từ “dub” có nghĩa phù hợp nhất là gì?', '["nổi giận đùng đùng; bực tức","công tâm; vô tư; không thiên vị","ám chỉ; nói bóng gió; nhắc đến một cách gián tiếp","lồng tiếng (cho phim)"]'::jsonb, 3, 'dub: lồng tiếng (cho phim); gọi là; mệnh danh là. Dịch cả câu: Các nhà báo đã gọi tuyến đường sắt mới này là ''cánh tay nối dài'' cứu sinh cho các cộng đồng nông thôn vốn trước đây bị cô lập với các trung tâm việc làm lớn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_20', 'en-c1-59', NULL, 'comprehensive_test', 'reading', NULL, 'Advertisements can misrepresent the environmental benefits of products, making it harder for consumers to make informed decisions.', 'Dựa vào câu trên, từ “misrepresent” có nghĩa phù hợp nhất là gì?', '["bóp méo; xuyên tạc; mô tả sai lệch","bắt buộc; làm cho phải tuân theo","liên tiếp; nối tiếp nhau không ngừng","hối hả; vội vã; thúc giục"]'::jsonb, 0, 'misrepresent: bóp méo; xuyên tạc; mô tả sai lệch. Dịch cả câu: Các quảng cáo có thể bóp méo những lợi ích môi trường của sản phẩm, khiến người tiêu dùng gặp khó khăn hơn trong việc đưa ra quyết định sáng suốt.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_59_21', 'en-c1-59', NULL, 'comprehensive_test', 'reading', NULL, 'The report reiterates that investment in public transport is essential for reducing urban air pollution.', 'Dựa vào câu trên, từ “reiterate” có nghĩa phù hợp nhất là gì?', '["sửa đổi; điều chỉnh (tài liệu, quy tắc, kế hoạch)","nhắc lại; nhấn mạnh lại; tái khẳng định","dựa dẫm; phụ thuộc; nhờ vào","bàn bạc; hội ý; thảo luận"]'::jsonb, 1, 'reiterate: nhắc lại; nhấn mạnh lại; tái khẳng định. Dịch cả câu: Báo cáo tái khẳng định rằng đầu tư vào giao thông công cộng là điều cốt yếu để giảm thiểu ô nhiễm không khí đô thị.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
