INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-60', 'en', 'Bài 60: Đời sống hằng ngày (1) - CEFR C1', 'CEFR C1', 'C1 · Đời sống', '27 từ vựng Tiếng Anh CEFR C1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5060, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incense', 'en-c1-60', 'incense', '/ˈɪnsens/', 'C1', 'nhang; trầm hương; hương', 'n.', NULL, NULL, 'Danh từ được nhấn trọng âm ở âm tiết đầu; động từ đồng hình có trọng âm ở âm tiết sau, mang nghĩa là làm cho tức giận.', 'A thin trail of smoke rose from the incense.', NULL, 'Một làn khói mỏng bay lên từ nén nhang.', '{"wordId":"incense","ukIpa":"/ˈɪnsens/","usIpa":"/ˈɪnsens/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"a substance burned to produce a pleasant smell","vi":"nhang; trầm hương; hương"}],"examples":[{"en":"A thin trail of smoke rose from the incense.","vi":"Một làn khói mỏng bay lên từ nén nhang.","audioKind":"ex"},{"en":"Burning incense indoors can affect air quality, particularly in small rooms with inadequate ventilation.","vi":"Đốt nhang trong nhà có thể làm ảnh hưởng đến chất lượng không khí, đặc biệt là trong các căn phòng nhỏ kém thông thoáng.","audioKind":"ex2"}],"collocations":[{"en":"burn incense","vi":"đốt nhang"},{"en":"incense sticks","vi":"nhang cây"},{"en":"incense burner","vi":"lư hương"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ được nhấn trọng âm ở âm tiết đầu; động từ đồng hình có trọng âm ở âm tiết sau, mang nghĩa là làm cho tức giận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_freak', 'en-c1-60', 'freak', '/friːk/', 'C1', 'bất thường; kỳ lạ; đột biến; người cuồng cái gì; tín đồ cuồng nhiệt; hoảng sợ; làm cho hoảng sợ', 'adj.', 'freaky (adj.)', 'Đồng nghĩa: unusual, abnormal', 'Tính từ thường đứng trước danh từ; động từ thường đi trong cụm freak out.', 'A freak hailstorm covered our garden in white ice.', NULL, 'Một trận mưa đá bất thường đã phủ trắng khu vườn của chúng tôi bằng một lớp băng.', '{"wordId":"freak","ukIpa":"/friːk/","usIpa":"/friːk/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Very unusual and unexpected","vi":"bất thường; kỳ lạ; đột biến"},{"pos":"n.","en":"Someone extremely interested in a particular activity or subject","vi":"người cuồng cái gì; tín đồ cuồng nhiệt"},{"pos":"v.","en":"To become very frightened or upset, or make someone so","vi":"hoảng sợ; làm cho hoảng sợ"}],"examples":[{"en":"A freak hailstorm covered our garden in white ice.","vi":"Một trận mưa đá bất thường đã phủ trắng khu vườn của chúng tôi bằng một lớp băng.","audioKind":"ex"},{"en":"A freak weather event can expose weaknesses in urban infrastructure and disrupt essential public services.","vi":"Một hiện tượng thời tiết bất thường có thể làm lộ ra những điểm yếu trong cơ sở hạ tầng đô thị và làm gián đoạn các dịch vụ công cộng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"a freak accident","vi":"tai nạn hy hữu"},{"en":"a freak storm","vi":"cơn bão bất thường"},{"en":"a fitness freak","vi":"tín đồ tập thể hình"},{"en":"freak out","vi":"hoảng loạn"}],"wordFamily":["freaky (adj.)"],"synonyms":["unusual","abnormal"],"antonyms":[],"tipVi":"Tính từ thường đứng trước danh từ; động từ thường đi trong cụm freak out.","noteVi":"Khi dùng làm danh từ để chỉ người có ngoại hình hoặc hành vi khác thường, từ này mang sắc thái miệt thị, xúc phạm.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brim', 'en-c1-60', 'brim', '/brɪm/', 'C1', 'miệng (cốc, bát, hoặc vật chứa khác); vành mũ; tràn ngập; đầy ắp (chất lỏng hoặc cảm xúc mạnh)', 'n.', 'brimmed (adj.), brimless (adj.)', NULL, 'Đầy đến miệng cốc dùng "to the brim"; tràn đầy dùng "brim with".', 'She filled my cup to the brim with tea.', NULL, 'Cô ấy rót trà đầy đến tận miệng cốc của tôi.', '{"wordId":"brim","ukIpa":"/brɪm/","usIpa":"/brɪm/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"the upper edge of a cup, bowl, or other container","vi":"miệng (cốc, bát, hoặc vật chứa khác)"},{"pos":"n.","en":"the part of a hat extending outward around its base","vi":"vành mũ"},{"pos":"v.","en":"to be full of liquid or a strong feeling","vi":"tràn ngập; đầy ắp (chất lỏng hoặc cảm xúc mạnh)"}],"examples":[{"en":"She filled my cup to the brim with tea.","vi":"Cô ấy rót trà đầy đến tận miệng cốc của tôi.","audioKind":"ex"},{"en":"Community centres brimming with activity can strengthen social connections and reduce isolation among older residents.","vi":"Các trung tâm cộng đồng tràn ngập các hoạt động có thể thắt chặt mốiσ liên kết xã hội và giảm bớt tình trạng cô lập ở cư dân cao tuổi.","audioKind":"ex2"}],"collocations":[{"en":"to the brim","vi":"đầy đến miệng"},{"en":"a wide brim","vi":"vành mũ rộng"},{"en":"brim with confidence","vi":"tràn ngập sự tự tin"}],"wordFamily":["brimmed (adj.)","brimless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đầy đến miệng cốc dùng \"to the brim\"; tràn đầy dùng \"brim with\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suspension', 'en-c1-60', 'suspension', '/səˈspenʃən/', 'C1', 'sự tạm dừng; sự đình chỉ; sự tạm hoãn; hệ thống giảm xóc; dung dịch huyền phù; trạng thái lơ lửng', 'n.', 'suspend (v.), suspended (adj.)', NULL, 'Chỉ sự tạm ngưng hoạt động; trong ngữ cảnh xe cộ thì chỉ hệ thống treo, giảm xóc.', 'The storm caused the suspension of all ferry services.', NULL, 'Cơn bão đã khiến toàn bộ các chuyến phà phải tạm ngừng hoạt động.', '{"wordId":"suspension","ukIpa":"/səˈspenʃən/","usIpa":"/səˈspenʃən/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A temporary stop to an activity or someone''s participation","vi":"sự tạm dừng; sự đình chỉ; sự tạm hoãn"},{"pos":"n.","en":"Vehicle parts that reduce shaking on uneven roads","vi":"hệ thống giảm xóc"},{"pos":"n.","en":"A liquid containing undissolved particles, or their state within it","vi":"dung dịch huyền phù; trạng thái lơ lửng"}],"examples":[{"en":"The storm caused the suspension of all ferry services.","vi":"Cơn bão đã khiến toàn bộ các chuyến phà phải tạm ngừng hoạt động.","audioKind":"ex"},{"en":"The temporary suspension of construction work allowed researchers to assess the project''s impact on local wildlife.","vi":"Việc tạm dừng thi công công trình đã giúp các nhà nghiên cứu có cơ hội đánh giá tác động của dự án đối với động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"suspension of services","vi":"sự tạm ngừng dịch vụ"},{"en":"school suspension","vi":"kỷ luật đình chỉ học"},{"en":"suspension system","vi":"hệ thống giảm xóc"},{"en":"in suspension","vi":"ở trạng thái lơ lửng"}],"wordFamily":["suspend (v.)","suspended (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ sự tạm ngưng hoạt động; trong ngữ cảnh xe cộ thì chỉ hệ thống treo, giảm xóc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lull', 'en-c1-60', 'lull', '/lʌl/', 'C1', 'khoảng thời gian yên ắng tạm thời; khoảng lặng; làm dịu đi; ru ngủ; làm cho mất cảnh giác', 'n.', NULL, NULL, 'lull diễn tả sự tĩnh lặng mang tính tạm thời, không hàm ý chấm dứt hoàn toàn.', 'We stepped outside during a lull in the rain.', NULL, 'Chúng tôi bước ra ngoài trong lúc trời ngớt mưa tạm thời.', '{"wordId":"lull","ukIpa":"/lʌl/","usIpa":"/lʌl/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A short period when activity or noise becomes less intense.","vi":"khoảng thời gian yên ắng tạm thời; khoảng lặng"},{"pos":"v.","en":"To calm someone or gently help them fall asleep.","vi":"làm dịu đi; ru ngủ"},{"pos":"v.","en":"To make someone feel safe when danger may still exist.","vi":"làm cho mất cảnh giác"}],"examples":[{"en":"We stepped outside during a lull in the rain.","vi":"Chúng tôi bước ra ngoài trong lúc trời ngớt mưa tạm thời.","audioKind":"ex"},{"en":"A temporary lull in economic activity may give businesses time to review their long-term strategies.","vi":"Sự chững lại tạm thời trong hoạt động kinh tế có thể mang lại thời gian cho các doanh nghiệp nhìn nhận lại chiến lược dài hạn của mình.","audioKind":"ex2"}],"collocations":[{"en":"a lull in activity","vi":"khoảng lắng trong hoạt động"},{"en":"lull someone to sleep","vi":"ru ai đó ngủ"},{"en":"lull someone into a false sense of security","vi":"làm ai đó mất cảnh giác với cảm giác an toàn ảo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"lull diễn tả sự tĩnh lặng mang tính tạm thời, không hàm ý chấm dứt hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_haste', 'en-c1-60', 'haste', '/heɪst/', 'C1', 'sự vội vàng; sự hấp tấp', 'n.', 'hasty (adj.), hastily (adv.), hasten (v.)', 'Đồng nghĩa: hurry, rush · Trái nghĩa: slowness', 'Thường là danh từ không đếm được; in haste có nghĩa là một cách vội vàng.', 'In my haste, I left my keys on the table.', NULL, 'Vì vội vàng nên tôi đã để quên chìa khóa trên bàn.', '{"wordId":"haste","ukIpa":"/heɪst/","usIpa":"/heɪst/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"Speed in acting, often without enough care or thought.","vi":"sự vội vàng; sự hấp tấp"}],"examples":[{"en":"In my haste, I left my keys on the table.","vi":"Vì vội vàng nên tôi đã để quên chìa khóa trên bàn.","audioKind":"ex"},{"en":"Policies developed in haste may overlook the needs of vulnerable groups and create additional social problems.","vi":"Các chính sách được xây dựng một cách vội vàng có thể bỏ qua nhu cầu của các nhóm dễ bị tổn thương và gây ra thêm nhiều vấn đề xã hội.","audioKind":"ex2"}],"collocations":[{"en":"in haste","vi":"vội vàng"},{"en":"undue haste","vi":"sự vội vã thái quá"},{"en":"make haste","vi":"nhanh chóng lên"}],"wordFamily":["hasty (adj.)","hastily (adv.)","hasten (v.)"],"synonyms":["hurry","rush"],"antonyms":["slowness"],"tipVi":"Thường là danh từ không đếm được; in haste có nghĩa là một cách vội vàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_midst', 'en-c1-60', 'midst', '/mɪdst/', 'C1', 'giữa; trong số', 'n.', NULL, NULL, 'Thường đi trong cụm in the midst of, diễn tả việc đang ở giữa một nơi hoặc một tình huống nào đó.', 'We found a quiet garden in the midst of town.', NULL, 'Chúng tôi tìm thấy một khu vườn yên tĩnh nằm ngay giữa thị trấn.', '{"wordId":"midst","ukIpa":"/mɪdst/","usIpa":"/mɪdst/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"The middle of a place, group, activity, or situation.","vi":"giữa; trong số"}],"examples":[{"en":"We found a quiet garden in the midst of town.","vi":"Chúng tôi tìm thấy một khu vườn yên tĩnh nằm ngay giữa thị trấn.","audioKind":"ex"},{"en":"In the midst of rapid urban growth, planners must preserve accessible green spaces for residents.","vi":"Giữa lúc đô thị hóa diễn ra nhanh chóng, các nhà quy hoạch phải bảo tồn các không gian xanh dễ tiếp cận cho người dân.","audioKind":"ex2"}],"collocations":[{"en":"in the midst of","vi":"giữa lúc"},{"en":"in our midst","vi":"ở trong chúng ta"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường đi trong cụm in the midst of, diễn tả việc đang ở giữa một nơi hoặc một tình huống nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lurk', 'en-c1-60', 'lurk', '/lɝːk/', 'C1', 'núp; ẩn nấp; trốn; ẩn chứa; tiềm ẩn (chờ cơ hội gây rắc rối)', 'v.', NULL, 'Đồng nghĩa: hide, skulk', 'Thường đóng vai trò là động từ không có tân ngữ; có thể dùng các sự vật trừu tượng như nguy hiểm làm chủ ngữ.', 'A cat lurked behind the sofa, watching my shoelaces.', NULL, 'Một con mèo nấp sau ghế sofa, chăm chú nhìn dây giày của tôi.', '{"wordId":"lurk","ukIpa":"/lɜːk/","usIpa":"/lɝːk/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"stay hidden, often waiting to do something","vi":"núp; ẩn nấp; trốn"},{"pos":"v.","en":"exist unnoticed and potentially cause trouble","vi":"ẩn chứa; tiềm ẩn (chờ cơ hội gây rắc rối)"}],"examples":[{"en":"A cat lurked behind the sofa, watching my shoelaces.","vi":"Một con mèo nấp sau ghế sofa, chăm chú nhìn dây giày của tôi.","audioKind":"ex"},{"en":"Security risks may lurk in outdated software, making regular system updates essential for protecting personal information.","vi":"Các rủi ro bảo mật có thể tiềm ẩn trong các phần mềm cũ, khiến việc cập nhật hệ thống thường xuyên trở nên rất quan trọng để bảo vệ thông tin cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"lurk in the shadows","vi":"nấp trong bóng tối"},{"en":"lurk behind","vi":"ẩn chứa đằng sau"},{"en":"danger lurks","vi":"mối nguy hiểm tiềm ẩn"}],"wordFamily":[],"synonyms":["hide","skulk"],"antonyms":[],"tipVi":"Thường đóng vai trò là động từ không có tân ngữ; có thể dùng các sự vật trừu tượng như nguy hiểm làm chủ ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ordinarily', 'en-c1-60', 'ordinarily', '/ˌɔːrdəˈnerəli/', 'C1', 'thường; thông thường; ở điều kiện bình thường', 'adv.', 'ordinary (adj.)', 'Đồng nghĩa: usually, normally · Trái nghĩa: exceptionally', 'Chỉ tính thông thường, không mang ý nghĩa phỏng đoán kiểu như "có lẽ".', 'We ordinarily eat outside, but today it is raining.', NULL, 'Chúng tôi thường ăn ở ngoài trời, nhưng hôm nay trời mưa.', '{"wordId":"ordinarily","ukIpa":"/ˈɔːdənrəli/","usIpa":"/ˌɔːrdəˈnerəli/","cefr":"C1","topic":"daily","senses":[{"pos":"adv.","en":"Usually, or when conditions are normal.","vi":"thường; thông thường; ở điều kiện bình thường"}],"examples":[{"en":"We ordinarily eat outside, but today it is raining.","vi":"Chúng tôi thường ăn ở ngoài trời, nhưng hôm nay trời mưa.","audioKind":"ex"},{"en":"Public libraries ordinarily provide free internet access, helping residents who cannot afford a connection at home.","vi":"Các thư viện công cộng thường cung cấp quyền truy cập internet miễn phí, giúp đỡ những cư dân không đủ khả năng chi trả phí kết nối tại nhà.","audioKind":"ex2"}],"collocations":[{"en":"would ordinarily","vi":"thông thường sẽ"},{"en":"ordinarily available","vi":"thường có sẵn"},{"en":"ordinarily resident","vi":"thường trú"}],"wordFamily":["ordinary (adj.)"],"synonyms":["usually","normally"],"antonyms":["exceptionally"],"tipVi":"Chỉ tính thông thường, không mang ý nghĩa phỏng đoán kiểu như \"có lẽ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stride', 'en-c1-60', 'stride', '/straɪd/', 'C1', 'bước đi dũng mãnh; sải bước; bước dài; sải chân; bước tiến lớn; sự tiến bộ rõ rệt', 'v.', NULL, NULL, 'Dạng quá khứ là strode, phân từ hai là stridden; từ tiến bộ thường ở dạng số nhiều strides.', 'Leila strode across the platform to catch her train.', NULL, 'Leila sải bước qua sân ga để kịp chuyến tàu của mình.', '{"wordId":"stride","ukIpa":"/straɪd/","usIpa":"/straɪd/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"Walk with long, confident steps.","vi":"bước đi dũng mãnh; sải bước"},{"pos":"n.","en":"A long step taken while walking or running.","vi":"bước dài; sải chân"},{"pos":"n.","en":"Important progress towards a goal, usually expressed in the plural.","vi":"bước tiến lớn; sự tiến bộ rõ rệt"}],"examples":[{"en":"Leila strode across the platform to catch her train.","vi":"Leila sải bước qua sân ga để kịp chuyến tàu của mình.","audioKind":"ex"},{"en":"Many countries have made significant strides in improving access to primary education over recent decades.","vi":"Nhiều quốc gia đã đạt được những bước tiến đáng kể trong việc cải thiện khả năng tiếp cận giáo dục tiểu học trong những thập kỷ gần đây.","audioKind":"ex2"}],"collocations":[{"en":"stride across a room","vi":"sải bước qua phòng"},{"en":"make great strides","vi":"đạt được bước tiến lớn"},{"en":"take something in your stride","vi":"bình tĩnh đối phó với việc gì"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ là strode, phân từ hai là stridden; từ tiến bộ thường ở dạng số nhiều strides.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_henceforth', 'en-c1-60', 'henceforth', '/ˌhensˈfɔːrθ/', 'C1', 'từ nay về sau; kể từ đó', 'adv.', NULL, 'Đồng nghĩa: from now on, henceforward', 'Là từ trang trọng; trong giao tiếp hàng ngày thường dùng from now on.', 'Henceforth, we will keep spare keys in this drawer.', NULL, 'Từ nay về sau, chúng ta sẽ để chìa khóa dự phòng trong ngăn kéo này.', '{"wordId":"henceforth","ukIpa":"/ˌhensˈfɔːθ/","usIpa":"/ˌhensˈfɔːrθ/","cefr":"C1","topic":"daily","senses":[{"pos":"adv.","en":"from this time onwards","vi":"từ nay về sau; kể từ đó"}],"examples":[{"en":"Henceforth, we will keep spare keys in this drawer.","vi":"Từ nay về sau, chúng ta sẽ để chìa khóa dự phòng trong ngăn kéo này.","audioKind":"ex"},{"en":"The university announced that all new buildings would henceforth meet stricter environmental standards.","vi":"Trường đại học thông báo rằng tất cả các tòa nhà mới kể từ nay sẽ đáp ứng các tiêu chuẩn môi trường nghiêm ngặt hơn.","audioKind":"ex2"}],"collocations":[{"en":"shall henceforth","vi":"sẽ từ nay về sau"},{"en":"be henceforth known as","vi":"từ đây được gọi là"}],"wordFamily":[],"synonyms":["from now on","henceforward"],"antonyms":[],"tipVi":"Là từ trang trọng; trong giao tiếp hàng ngày thường dùng from now on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slack', 'en-c1-60', 'slack', '/slæk/', 'C1', 'chùng; lỏng; không căng; trì trệ; ế ẩm; lơi lỏng; đoạn chùng (của dây); công suất dư thừa', 'adj.', 'slacken (v.), slackness (n.)', 'Đồng nghĩa: loose · Trái nghĩa: taut, tight', 'slack chỉ sự chùng hoặc lơi lỏng; slacks là quần dài rộng.', 'The tent rope was slack after the heavy rain.', NULL, 'Dây chằng lều bị chùng xuống sau trận mưa lớn.', '{"wordId":"slack","ukIpa":"/slæk/","usIpa":"/slæk/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"loose rather than tightly stretched","vi":"chùng; lỏng; không căng"},{"pos":"adj.","en":"less busy, active, or careful than expected","vi":"trì trệ; ế ẩm; lơi lỏng"},{"pos":"n.","en":"looseness in a rope, or unused capacity","vi":"đoạn chùng (của dây); công suất dư thừa"}],"examples":[{"en":"The tent rope was slack after the heavy rain.","vi":"Dây chằng lều bị chùng xuống sau trận mưa lớn.","audioKind":"ex"},{"en":"When demand is slack, manufacturers may reduce working hours rather than dismiss experienced employees immediately.","vi":"Khi nhu cầu thị trường ế ẩm, các nhà sản xuất có thể giảm giờ làm việc thay vì sa thải ngay lập tức những nhân viên có kinh nghiệm.","audioKind":"ex2"}],"collocations":[{"en":"slack rope","vi":"dây chùng"},{"en":"slack demand","vi":"nhu cầu ế ẩm"},{"en":"take up the slack","vi":"tận dụng phần dư thừa; bù đắp chỗ trống"},{"en":"slack off","vi":"chểnh mảng; lười biếng"}],"wordFamily":["slacken (v.)","slackness (n.)"],"synonyms":["loose"],"antonyms":["taut","tight"],"tipVi":"slack chỉ sự chùng hoặc lơi lỏng; slacks là quần dài rộng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_persistent', 'en-c1-60', 'persistent', '/pərˈsɪstənt/', 'C1', 'kéo dài; dai dẳng; kiên trì; bền bỉ', 'adj.', 'persist (v.), persistence (n.), persistently (adv.)', 'Đồng nghĩa: continuing, relentless · Trái nghĩa: intermittent', 'Khi bổ nghĩa cho vấn đề thường mang hàm ý tiêu cực; khi bổ nghĩa cho người thể hiện sự kiên trì.', 'A persistent cough kept me awake throughout the night.', NULL, 'Cơn ho dai dẳng khiến tôi thức trắng cả đêm.', '{"wordId":"persistent","ukIpa":"/pəˈsɪstənt/","usIpa":"/pərˈsɪstənt/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"continuing for a long time or happening repeatedly","vi":"kéo dài; dai dẳng"},{"pos":"adj.","en":"continuing to try despite difficulty or opposition","vi":"kiên trì; bền bỉ"}],"examples":[{"en":"A persistent cough kept me awake throughout the night.","vi":"Cơn ho dai dẳng khiến tôi thức trắng cả đêm.","audioKind":"ex"},{"en":"Persistent shortages of affordable housing can force young adults to delay leaving their family homes.","vi":"Tình trạng thiếu hụt nhà ở giá rẻ kéo dài có thể buộc người trẻ phải hoãn kế hoạch dọn ra khỏi nhà bố mẹ.","audioKind":"ex2"}],"collocations":[{"en":"a persistent cough","vi":"cơn ho dai dẳng"},{"en":"a persistent problem","vi":"vấn đề nan giải"},{"en":"persistent efforts","vi":"nỗ lực bền bỉ"},{"en":"persistent shortages","vi":"tình trạng thiếu hụt kéo dài"}],"wordFamily":["persist (v.)","persistence (n.)","persistently (adv.)"],"synonyms":["continuing","relentless"],"antonyms":["intermittent"],"tipVi":"Khi bổ nghĩa cho vấn đề thường mang hàm ý tiêu cực; khi bổ nghĩa cho người thể hiện sự kiên trì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_groove', 'en-c1-60', 'groove', '/ɡruːv/', 'C1', 'rãnh; đường xẻ; nhịp điệu cuốn hút; tạo rãnh; xẻ rãnh', 'n.', 'grooved (adj.)', NULL, 'Chỉ rãnh lõm dài trên bề mặt; trong âm nhạc có thể chỉ nhịp điệu rõ nét.', 'Dust had collected in every groove of the wooden door.', NULL, 'Bụi đã bám đầy vào từng đường rãnh của cánh cửa gỗ.', '{"wordId":"groove","ukIpa":"/ɡruːv/","usIpa":"/ɡruːv/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A long, narrow cut or hollow in a surface.","vi":"rãnh; đường xẻ"},{"pos":"n.","en":"A strong, steady rhythm that makes music feel engaging.","vi":"nhịp điệu cuốn hút"},{"pos":"v.","en":"To cut long, narrow hollows into a surface.","vi":"tạo rãnh; xẻ rãnh"}],"examples":[{"en":"Dust had collected in every groove of the wooden door.","vi":"Bụi đã bám đầy vào từng đường rãnh của cánh cửa gỗ.","audioKind":"ex"},{"en":"The grooves in vehicle tyres channel water away, improving grip and reducing accident risks on wet roads.","vi":"Các rãnh trên lốp xe giúp thoát nước, tăng độ bám đường và giảm nguy cơ tai nạn trên mặt đường trơn trượt.","audioKind":"ex2"}],"collocations":[{"en":"cut a groove","vi":"cắt một đường rãnh"},{"en":"a deep groove","vi":"rãnh sâu"},{"en":"tyre grooves","vi":"rãnh lốp xe"},{"en":"get into a groove","vi":"bắt nhịp; vào guồng"}],"wordFamily":["grooved (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ rãnh lõm dài trên bề mặt; trong âm nhạc có thể chỉ nhịp điệu rõ nét.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plank', 'en-c1-60', 'plank', '/plæŋk/', 'C1', 'tấm ván dày; chủ trương; cốt lõi chính sách; bài tập chống đẩy tĩnh (plank)', 'n.', NULL, NULL, 'Cụm từ a central plank of dùng để ẩn dụ cho cốt lõi của một chính sách.', 'We laid a plank across the muddy ditch.', NULL, 'Chúng tôi đặt một tấm ván bắt ngang qua con mương lầy lội.', '{"wordId":"plank","ukIpa":"/plæŋk/","usIpa":"/plæŋk/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A long, flat, thick piece of wood.","vi":"tấm ván dày"},{"pos":"n.","en":"An important principle or proposal in a political programme.","vi":"chủ trương; cốt lõi chính sách"},{"pos":"n.","en":"An exercise holding the body straight above the floor.","vi":"bài tập chống đẩy tĩnh (plank)"}],"examples":[{"en":"We laid a plank across the muddy ditch.","vi":"Chúng tôi đặt một tấm ván bắt ngang qua con mương lầy lội.","audioKind":"ex"},{"en":"Investment in affordable housing should be a central plank of any strategy to reduce urban inequality.","vi":"Đầu tư vào nhà ở giá rẻ nên là cốt lõi trong bất kỳ chiến lược nào nhằm giảm thiểu bất bình đẳng đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a wooden plank","vi":"một tấm ván gỗ"},{"en":"a central plank of policy","vi":"điểm cốt lõi của chính sách"},{"en":"hold a plank","vi":"giữ tư thế plank"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ a central plank of dùng để ẩn dụ cho cốt lõi của một chính sách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pawn', 'en-c1-60', 'pawn', '/pɔːn/', 'C1', 'quân tốt (trong cờ vua); quân cờ trong tay kẻ khác; người bị lợi dụng; cầm đồ; đem thế chấp', 'n.', 'pawnbroker (n.), pawnshop (n.)', NULL, 'Cầm đồ là đổi tài sản lấy khoản vay có thể chuộc lại, khác với việc bán đứt.', 'She moved a pawn forward and studied the chessboard.', NULL, 'Cô ấy đi một nước tốt rồi chăm chú quan sát bàn cờ.', '{"wordId":"pawn","ukIpa":"/pɔːn/","usIpa":"/pɔːn/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A chess piece of the smallest size and lowest value.","vi":"quân tốt (trong cờ vua)"},{"pos":"n.","en":"A person controlled by others for their own purposes.","vi":"quân cờ trong tay kẻ khác; người bị lợi dụng"},{"pos":"v.","en":"To leave something valuable with a pawnbroker for a loan.","vi":"cầm đồ; đem thế chấp"}],"examples":[{"en":"She moved a pawn forward and studied the chessboard.","vi":"Cô ấy đi một nước tốt rồi chăm chú quan sát bàn cờ.","audioKind":"ex"},{"en":"Workers should not become pawns in disputes between powerful companies competing for control of essential services.","vi":"Người lao động không nên trở thành con tốt trong các tranh chấp giữa các tập đoàn lớn đang tranh giành quyền kiểm soát các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"move a pawn","vi":"đi một nước cờ tốt"},{"en":"a pawn in a power struggle","vi":"quân cờ trong cuộc tranh giành quyền lực"},{"en":"pawn jewellery","vi":"cầm cố trang sức"}],"wordFamily":["pawnbroker (n.)","pawnshop (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cầm đồ là đổi tài sản lấy khoản vay có thể chuộc lại, khác với việc bán đứt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_needless', 'en-c1-60', 'needless', '/ˈniːdləs/', 'C1', 'không cần thiết; thừa thãi', 'adj.', 'need (n.), need (v.), needlessly (adv.)', 'Đồng nghĩa: unnecessary, avoidable · Trái nghĩa: necessary, essential', 'needless to say có nghĩa là "khỏi phải nói", thường dùng làm thành phần chêm.', 'Calling ahead saved us a needless trip across town.', NULL, 'Việc gọi điện trước đã giúp chúng tôi không phải mất công đi vòng qua thành phố một cách vô ích.', '{"wordId":"needless","ukIpa":"/ˈniːdləs/","usIpa":"/ˈniːdləs/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"not necessary and therefore best avoided","vi":"không cần thiết; thừa thãi"}],"examples":[{"en":"Calling ahead saved us a needless trip across town.","vi":"Việc gọi điện trước đã giúp chúng tôi không phải mất công đi vòng qua thành phố một cách vô ích.","audioKind":"ex"},{"en":"Clear guidance on public services can prevent needless confusion and help residents access essential support.","vi":"Hướng dẫn rõ ràng về các dịch vụ công có thể tránh được những sự nhầm lẫn không cần thiết và giúp người dân tiếp cận sự hỗ trợ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"needless worry","vi":"lo lắng vô ích"},{"en":"needless expense","vi":"chi phí không cần thiết"},{"en":"needless to say","vi":"đương nhiên là; khỏi phải nói"}],"wordFamily":["need (n.)","need (v.)","needlessly (adv.)"],"synonyms":["unnecessary","avoidable"],"antonyms":["necessary","essential"],"tipVi":"needless to say có nghĩa là \"khỏi phải nói\", thường dùng làm thành phần chêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glassware', 'en-c1-60', 'glassware', '/ˈɡlæswer/', 'C1', 'đồ thủy tinh (đặc biệt là đồ uống hoặc thiết bị thí nghiệm)', 'n.', 'glass (n.), glassy (adj.)', NULL, 'Danh từ không đếm được; một món đồ thủy tinh dùng a piece of glassware.', 'Please wrap the glassware carefully before packing the box.', NULL, 'Xin hãy gói đồ thủy tinh thật cẩn thận trước khi đóng hộp.', '{"wordId":"glassware","ukIpa":"/ˈɡlɑːsweə/","usIpa":"/ˈɡlæswer/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"objects made of glass, especially drinking vessels or laboratory equipment","vi":"đồ thủy tinh (đặc biệt là đồ uống hoặc thiết bị thí nghiệm)"}],"examples":[{"en":"Please wrap the glassware carefully before packing the box.","vi":"Xin hãy gói đồ thủy tinh thật cẩn thận trước khi đóng hộp.","audioKind":"ex"},{"en":"Reusable glassware can reduce waste in laboratories, provided that appropriate cleaning and safety procedures are followed.","vi":"Đồ thủy tinh có thể tái sử dụng có thể giúp giảm chất thải trong các phòng thí nghiệm, miễn là tuân thủ các quy trình vệ sinh và an toàn thích hợp.","audioKind":"ex2"}],"collocations":[{"en":"laboratory glassware","vi":"dụng cụ thủy tinh trong phòng thí nghiệm"},{"en":"delicate glassware","vi":"đồ thủy tinh dễ vỡ"},{"en":"wash glassware","vi":"rửa đồ thủy tinh"}],"wordFamily":["glass (n.)","glassy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ không đếm được; một món đồ thủy tinh dùng a piece of glassware.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inward', 'en-c1-60', 'inward', '/ˈɪnwɚd/', 'C1', 'hướng vào trong; đi về phía trung tâm; nội tâm; thầm kín (cảm nhận bên trong thay vì biểu hiện ra ngoài); về phía bên trong; hướng vào tâm', 'adj.', 'inwardly (adv.), inwards (adv.)', 'Đồng nghĩa: inner · Trái nghĩa: outward', 'Dùng inward làm tính từ; trong tiếng Anh - Anh, trạng từ này cũng thường được viết là inwards.', 'An inward push was enough to open the gate.', NULL, 'Chỉ cần đẩy nhẹ vào phía trong là có thể mở được cửa cổng.', '{"wordId":"inward","ukIpa":"/ˈɪnwəd/","usIpa":"/ˈɪnwɚd/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"moving or directed towards the inside or centre","vi":"hướng vào trong; đi về phía trung tâm"},{"pos":"adj.","en":"felt privately in the mind rather than shown openly","vi":"nội tâm; thầm kín (cảm nhận bên trong thay vì biểu hiện ra ngoài)"},{"pos":"adv.","en":"towards the inside or centre of something","vi":"về phía bên trong; hướng vào tâm"}],"examples":[{"en":"An inward push was enough to open the gate.","vi":"Chỉ cần đẩy nhẹ vào phía trong là có thể mở được cửa cổng.","audioKind":"ex"},{"en":"An inward flow of investment can help developing economies improve infrastructure and create employment opportunities.","vi":"Dòng vốn đầu tư nước ngoài chảy vào có thể giúp các nền kinh tế đang phát triển cải thiện cơ sở hạ tầng và tạo ra nhiều cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"inward investment","vi":"đầu tư vào trong nước"},{"en":"inward movement","vi":"sự di chuyển hướng vào"},{"en":"inward feelings","vi":"cảm xúc nội tâm"},{"en":"turn inward","vi":"hướng về nội tâm"}],"wordFamily":["inwardly (adv.)","inwards (adv.)"],"synonyms":["inner"],"antonyms":["outward"],"tipVi":"Dùng inward làm tính từ; trong tiếng Anh - Anh, trạng từ này cũng thường được viết là inwards.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stagger', 'en-c1-60', 'stagger', '/ˈstæɡɚ/', 'C1', 'lạng choạng; đi lảo đảo như sắp ngã; sắp xếp lệch giờ; bố trí thời gian xen kẽ; làm choáng váng; gây bất ngờ lớn', 'v.', 'staggering (adj.), staggeringly (adv.)', NULL, 'stagger dùng làm động từ; staggering thường được dùng để chỉ mức độ kinh ngạc lớn.', 'He staggered backwards as the heavy suitcase swung towards him.', NULL, 'Anh ấy lạng choạng lùi về phía sau khi chiếc vali nặng trĩu văng về phía mình.', '{"wordId":"stagger","ukIpa":"/ˈstæɡə/","usIpa":"/ˈstæɡɚ/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to walk unsteadily, as if about to fall","vi":"lạng choạng; đi lảo đảo như sắp ngã"},{"pos":"v.","en":"to arrange events or activities at different times","vi":"sắp xếp lệch giờ; bố trí thời gian xen kẽ"},{"pos":"v.","en":"to surprise someone greatly","vi":"làm choáng váng; gây bất ngờ lớn"}],"examples":[{"en":"He staggered backwards as the heavy suitcase swung towards him.","vi":"Anh ấy lạng choạng lùi về phía sau khi chiếc vali nặng trĩu văng về phía mình.","audioKind":"ex"},{"en":"Employers could stagger working hours to ease congestion and reduce pressure on public transport.","vi":"Các nhà tuyển dụng có thể bố trí thời gian làm việc lệch nhau để giảm thiểu ùn tắc và giảm áp lực cho giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"stagger backwards","vi":"lạng choạng lùi về phía sau"},{"en":"stagger to one''s feet","vi":"lảo đảo đứng dậy"},{"en":"stagger working hours","vi":"bố trí thời gian làm việc lệch nhau"},{"en":"be staggered by","vi":"bị choáng váng bởi"}],"wordFamily":["staggering (adj.)","staggeringly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"stagger dùng làm động từ; staggering thường được dùng để chỉ mức độ kinh ngạc lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regularity', 'en-c1-60', 'regularity', '/ˌreɡjəˈlærəti/', 'C1', 'tính đều đặn; tính quy luật; sự định kỳ', 'n.', 'regular (adj.), regularly (adv.), irregular (adj.), irregularity (n.)', 'Trái nghĩa: irregularity', 'Cụm từ with regularity mang nghĩa có quy luật, hoặc chỉ việc xảy ra thường xuyên.', 'The regularity of her morning walks helps her sleep better.', NULL, 'Tính đều đặn trong những buổi đi dạo buổi sáng giúp cô ấy ngủ ngon hơn.', '{"wordId":"regularity","ukIpa":"/ˌreɡjəˈlærəti/","usIpa":"/ˌreɡjəˈlærəti/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"The quality of happening at consistent intervals or following a pattern.","vi":"tính đều đặn; tính quy luật; sự định kỳ"}],"examples":[{"en":"The regularity of her morning walks helps her sleep better.","vi":"Tính đều đặn trong những buổi đi dạo buổi sáng giúp cô ấy ngủ ngon hơn.","audioKind":"ex"},{"en":"The regularity of public transport services strongly influences whether commuters choose buses over private cars.","vi":"Tính đều đặn của các dịch vụ giao thông công cộng ảnh hưởng mạnh mẽ đến việc liệu những người đi làm có chọn xe buýt thay vì ô tô cá nhân hay không.","audioKind":"ex2"}],"collocations":[{"en":"with remarkable regularity","vi":"với tần suất đều đặn đáng chú ý"},{"en":"with increasing regularity","vi":"với mức độ ngày càng thường xuyên"},{"en":"regularity of rainfall","vi":"tính đều đặn của lượng mưa"}],"wordFamily":["regular (adj.)","regularly (adv.)","irregular (adj.)","irregularity (n.)"],"synonyms":[],"antonyms":["irregularity"],"tipVi":"Cụm từ with regularity mang nghĩa có quy luật, hoặc chỉ việc xảy ra thường xuyên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_semblance', 'en-c1-60', 'semblance', '/ˈsembləns/', 'C1', 'vẻ bề ngoài; hình thái; sự giống phần nào', 'n.', NULL, 'Đồng nghĩa: appearance', 'Thường dùng a semblance of, thể hiện một trạng thái mang tính bề ngoài hoặc một phần nhỏ.', 'I tidied the cushions to restore some semblance of order.', NULL, 'Tôi đã dọn dẹp lại những chiếc gối để căn phòng trông có vẻ ngăn nắp trở lại.', '{"wordId":"semblance","ukIpa":"/ˈsembləns/","usIpa":"/ˈsembləns/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"An outward appearance or slight degree of a particular quality","vi":"vẻ bề ngoài; hình thái; sự giống phần nào"}],"examples":[{"en":"I tidied the cushions to restore some semblance of order.","vi":"Tôi đã dọn dẹp lại những chiếc gối để căn phòng trông có vẻ ngăn nắp trở lại.","audioKind":"ex"},{"en":"After severe flooding, reopening schools can help communities regain a semblance of normality while essential infrastructure is repaired.","vi":"Sau trận lụt nghiêm trọng, việc mở cửa lại trường học có thể giúp cộng đồng lấy lại vẻ bình thường trong khi cơ sở hạ tầng thiết yếu đang được sửa chữa.","audioKind":"ex2"}],"collocations":[{"en":"a semblance of normality","vi":"vẻ bình thường"},{"en":"a semblance of order","vi":"vẻ trật tự"},{"en":"maintain a semblance of","vi":"duy trì vẻ bề ngoài"}],"wordFamily":[],"synonyms":["appearance"],"antonyms":[],"tipVi":"Thường dùng a semblance of, thể hiện một trạng thái mang tính bề ngoài hoặc một phần nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coarse', 'en-c1-60', 'coarse', '/kɔːrs/', 'C1', 'thô; nhám; thô ráp; thô tục; thô lỗ', 'adj.', 'coarsely (adv.), coarseness (n.), coarsen (v.)', 'Đồng nghĩa: rough, crude · Trái nghĩa: fine, smooth', 'Phát âm giống course; coarse dùng để miêu tả bề mặt thô ráp hoặc lời lẽ thô tục.', 'The coarse wool scratched my neck all afternoon.', NULL, 'Chiếc áo len bằng vải thô đã cọ xát làm cổ tôi ngứa rát suốt cả buổi chiều.', '{"wordId":"coarse","ukIpa":"/kɔːs/","usIpa":"/kɔːrs/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Having a rough texture or consisting of large particles","vi":"thô; nhám; thô ráp"},{"pos":"adj.","en":"Rude or offensive in speech or behaviour","vi":"thô tục; thô lỗ"}],"examples":[{"en":"The coarse wool scratched my neck all afternoon.","vi":"Chiếc áo len bằng vải thô đã cọ xát làm cổ tôi ngứa rát suốt cả buổi chiều.","audioKind":"ex"},{"en":"Coarse particles in urban air can irritate the lungs and worsen existing respiratory conditions among vulnerable residents.","vi":"Các hạt bụi thô trong không khí đô thị có thể gây kích ứng phổi và làm trầm trọng thêm các bệnh về đường hô hấp ở những cư dân có sức khỏe nhạy cảm.","audioKind":"ex2"}],"collocations":[{"en":"coarse sand","vi":"cát thô"},{"en":"coarse fabric","vi":"vải thô"},{"en":"coarse particles","vi":"hạt thô"},{"en":"coarse language","vi":"ngôn từ thô tục"}],"wordFamily":["coarsely (adv.)","coarseness (n.)","coarsen (v.)"],"synonyms":["rough","crude"],"antonyms":["fine","smooth"],"tipVi":"Phát âm giống course; coarse dùng để miêu tả bề mặt thô ráp hoặc lời lẽ thô tục.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_finicky', 'en-c1-60', 'finicky', '/ˈfɪnɪki/', 'C1', 'quá mức kỹ tính; khó chiều; kén chọn; đòi hỏi sự tỉ mỉ; dễ bị hỏng hoặc khó thao tác', 'adj.', 'finickiness (n.)', 'Đồng nghĩa: fussy, picky · Trái nghĩa: easy-going', 'Mang sắc thái thông tục và thường mang ý chê bai; cấu trúc finicky about dùng để chỉ việc kén chọn điều gì.', 'Our finicky cat refuses food unless it is warm.', NULL, 'Con mèo kén chọn của chúng tôi nhất quyết không chịu ăn trừ khi thức ăn được làm nóng.', '{"wordId":"finicky","ukIpa":"/ˈfɪnɪki/","usIpa":"/ˈfɪnɪki/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"very particular about small details and difficult to please","vi":"quá mức kỹ tính; khó chiều; kén chọn"},{"pos":"adj.","en":"requiring careful attention and easily disturbed or damaged","vi":"đòi hỏi sự tỉ mỉ; dễ bị hỏng hoặc khó thao tác"}],"examples":[{"en":"Our finicky cat refuses food unless it is warm.","vi":"Con mèo kén chọn của chúng tôi nhất quyết không chịu ăn trừ khi thức ăn được làm nóng.","audioKind":"ex"},{"en":"Consumers can be finicky about appearance, leading supermarkets to reject perfectly edible fruit with minor imperfections.","vi":"Người tiêu dùng có thể rất khắt khe về mặt ngoại hình, khiến các loại siêu thị từ chối những quả trái cây hoàn toàn ăn được nhưng có khuyết điểm nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"a finicky eater","vi":"một kẻ kén ăn"},{"en":"finicky about food","vi":"kén chọn trong việc ăn uống"},{"en":"finicky equipment","vi":"thiết bị đòi hỏi sự vận hành tỉ mỉ"}],"wordFamily":["finickiness (n.)"],"synonyms":["fussy","picky"],"antonyms":["easy-going"],"tipVi":"Mang sắc thái thông tục và thường mang ý chê bai; cấu trúc finicky about dùng để chỉ việc kén chọn điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flick', 'en-c1-60', 'flick', '/flɪk/', 'C1', 'búng; gạt nhanh; phủi nhanh; cú búng; cái hất nhẹ; chuyển động nhanh nhẹ; phim ảnh (từ dùng trong văn phong không trang trọng)', 'v.', NULL, NULL, 'Cụm từ flick through dùng để chỉ việc đọc lướt nhanh, không mang hàm ý đọc kỹ lưỡng.', 'He flicked a crumb off his sleeve before leaving.', NULL, 'Anh ấy phủi nhanh một mẩu vụn bánh mì khỏi tay áo trước khi rời đi.', '{"wordId":"flick","ukIpa":"/flɪk/","usIpa":"/flɪk/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"Move or remove something with a quick, light movement.","vi":"búng; gạt nhanh; phủi nhanh"},{"pos":"n.","en":"A quick, light movement of a finger, hand, or object.","vi":"cú búng; cái hất nhẹ; chuyển động nhanh nhẹ"},{"pos":"n.","en":"A film, in informal language.","vi":"phim ảnh (từ dùng trong văn phong không trang trọng)"}],"examples":[{"en":"He flicked a crumb off his sleeve before leaving.","vi":"Anh ấy phủi nhanh một mẩu vụn bánh mì khỏi tay áo trước khi rời đi.","audioKind":"ex"},{"en":"Digital interfaces allow readers to flick through articles quickly, but this convenience may encourage superficial reading habits.","vi":"Giao diện kỹ thuật số cho phép người đọc lướt qua các bài viết một cách nhanh chóng, nhưng sự tiện lợi này có thể vô tình tạo ra thói quen đọc lướt qua loa.","audioKind":"ex2"}],"collocations":[{"en":"flick through a magazine","vi":"lướt nhanh qua một cuốn tạp chí"},{"en":"flick a switch","vi":"bật/tắt công tắc nhanh"},{"en":"a flick of the wrist","vi":"một cái búng cổ tay"},{"en":"a comedy flick","vi":"một bộ phim hài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ flick through dùng để chỉ việc đọc lướt nhanh, không mang hàm ý đọc kỹ lưỡng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_watertight', 'en-c1-60', 'watertight', '/ˈwɔːtərtaɪt/', 'C1', 'không thấm nước; chống nước; kín nước; vô khuyết; không có kẽ hở; chặt chẽ (lập luận hoặc thỏa thuận)', 'adj.', 'watertightness (n.)', 'Trái nghĩa: leaky', 'Vừa có nghĩa đen là chống thấm nước, vừa dùng theo nghĩa bóng để miêu tả một lập luận hoặc thỏa thuận cực kỳ chặt chẽ.', 'This watertight box keeps my camera dry during boat trips.', NULL, 'Chiếc hộp chống nước này giúp máy ảnh của tôi luôn khô ráo trong các chuyến đi thuyền.', '{"wordId":"watertight","ukIpa":"/ˈwɔːtətaɪt/","usIpa":"/ˈwɔːtərtaɪt/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Made so that water cannot enter or escape","vi":"không thấm nước; chống nước; kín nước"},{"pos":"adj.","en":"Having no weaknesses that allow doubt or challenge","vi":"vô khuyết; không có kẽ hở; chặt chẽ (lập luận hoặc thỏa thuận)"}],"examples":[{"en":"This watertight box keeps my camera dry during boat trips.","vi":"Chiếc hộp chống nước này giúp máy ảnh của tôi luôn khô ráo trong các chuyến đi thuyền.","audioKind":"ex"},{"en":"Governments need watertight regulations to prevent companies from avoiding responsibility for environmental damage caused by their operations.","vi":"Chính phủ cần ban hành các quy định chặt chẽ để ngăn chặn các doanh nghiệp trốn tránh trách nhiệm về những tổn hại môi trường do hoạt động của họ gây ra.","audioKind":"ex2"}],"collocations":[{"en":"a watertight container","vi":"hộp đựng chống nước"},{"en":"a watertight argument","vi":"một lập luận kín kẽ"},{"en":"a watertight agreement","vi":"một thỏa thuận chặt chẽ"}],"wordFamily":["watertightness (n.)"],"synonyms":[],"antonyms":["leaky"],"tipVi":"Vừa có nghĩa đen là chống thấm nước, vừa dùng theo nghĩa bóng để miêu tả một lập luận hoặc thỏa thuận cực kỳ chặt chẽ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blunder', 'en-c1-60', 'blunder', '/ˈblʌndər/', 'C1', 'một sai lầm nghiêm trọng do bất cẩn hoặc thiếu phán đoán chuẩn xác; mắc sai lầm nghiêm trọng hoặc bất cẩn; đi lại loạng choạng, bước đi vụng về hoặc không định trước được phương hướng', 'n.', 'blundering (adj.), blunderer (n.)', 'Đồng nghĩa: mistake, error', 'Có sắc thái nặng hơn từ mistake, nhấn mạnh việc gây ra lỗi do sơ suất hoặc phán đoán kém.', 'I made a blunder and booked the wrong date.', NULL, 'Tôi đã phạm một sai lầm ngớ ngẩn khi đặt nhầm ngày tháng.', '{"wordId":"blunder","ukIpa":"/ˈblʌndə/","usIpa":"/ˈblʌndər/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A serious mistake caused by carelessness or poor judgment.","vi":"một sai lầm nghiêm trọng do bất cẩn hoặc thiếu phán đoán chuẩn xác"},{"pos":"v.","en":"To make a serious or careless mistake.","vi":"mắc sai lầm nghiêm trọng hoặc bất cẩn"},{"pos":"v.","en":"To move clumsily or without knowing where you are going.","vi":"đi lại loạng choạng, bước đi vụng về hoặc không định trước được phương hướng"}],"examples":[{"en":"I made a blunder and booked the wrong date.","vi":"Tôi đã phạm một sai lầm ngớ ngẩn khi đặt nhầm ngày tháng.","audioKind":"ex"},{"en":"A major planning blunder can leave communities without adequate transport links for many years.","vi":"Một lỗi lầm lớn trong khâu quy hoạch có thể khiến các cộng đồng dân cư thiếu vắng kết nối giao thông đầy đủ trong nhiều năm.","audioKind":"ex2"}],"collocations":[{"en":"make a blunder","vi":"mắc sai lầm lớn"},{"en":"major blunder","vi":"sai lầm nghiêm trọng"},{"en":"blunder into","vi":"vô tình bước vào"},{"en":"blunder through","vi":"đi lang thang qua"}],"wordFamily":["blundering (adj.)","blunderer (n.)"],"synonyms":["mistake","error"],"antonyms":[],"tipVi":"Có sắc thái nặng hơn từ mistake, nhấn mạnh việc gây ra lỗi do sơ suất hoặc phán đoán kém.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_60_1', 'en-c1-60', 'Cách dùng “incense” (n.) — nhang; trầm hương; hương', 'burn incense  ·  incense sticks  ·  incense burner', 'Danh từ được nhấn trọng âm ở âm tiết đầu; động từ đồng hình có trọng âm ở âm tiết sau, mang nghĩa là làm cho tức giận.', NULL, '[{"hanzi":"A thin trail of smoke rose from the incense.","pinyin":"","meaning":"Một làn khói mỏng bay lên từ nén nhang."},{"hanzi":"Burning incense indoors can affect air quality, particularly in small rooms with inadequate ventilation.","pinyin":"","meaning":"Đốt nhang trong nhà có thể làm ảnh hưởng đến chất lượng không khí, đặc biệt là trong các căn phòng nhỏ kém thông thoáng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_60_2', 'en-c1-60', 'Cách dùng “watertight” (adj.) — không thấm nước; chống nước; kín nước', 'a watertight container  ·  a watertight argument  ·  a watertight agreement', 'Vừa có nghĩa đen là chống thấm nước, vừa dùng theo nghĩa bóng để miêu tả một lập luận hoặc thỏa thuận cực kỳ chặt chẽ.', 'Họ từ (Word Family): watertightness (n.) | Trái nghĩa: leaky', '[{"hanzi":"This watertight box keeps my camera dry during boat trips.","pinyin":"","meaning":"Chiếc hộp chống nước này giúp máy ảnh của tôi luôn khô ráo trong các chuyến đi thuyền."},{"hanzi":"Governments need watertight regulations to prevent companies from avoiding responsibility for environmental damage caused by their operations.","pinyin":"","meaning":"Chính phủ cần ban hành các quy định chặt chẽ để ngăn chặn các doanh nghiệp trốn tránh trách nhiệm về những tổn hại môi trường do hoạt động của họ gây ra."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_60_3', 'en-c1-60', 'Cách dùng “lurk” (v.) — núp; ẩn nấp; trốn', 'lurk in the shadows  ·  lurk behind  ·  danger lurks', 'Thường đóng vai trò là động từ không có tân ngữ; có thể dùng các sự vật trừu tượng như nguy hiểm làm chủ ngữ.', 'Đồng nghĩa: hide, skulk', '[{"hanzi":"A cat lurked behind the sofa, watching my shoelaces.","pinyin":"","meaning":"Một con mèo nấp sau ghế sofa, chăm chú nhìn dây giày của tôi."},{"hanzi":"Security risks may lurk in outdated software, making regular system updates essential for protecting personal information.","pinyin":"","meaning":"Các rủi ro bảo mật có thể tiềm ẩn trong các phần mềm cũ, khiến việc cập nhật hệ thống thường xuyên trở nên rất quan trọng để bảo vệ thông tin cá nhân."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_60_4', 'en-c1-60', 'Cách dùng “finicky” (adj.) — quá mức kỹ tính; khó chiều; kén chọn', 'a finicky eater  ·  finicky about food  ·  finicky equipment', 'Mang sắc thái thông tục và thường mang ý chê bai; cấu trúc finicky about dùng để chỉ việc kén chọn điều gì.', 'Họ từ (Word Family): finickiness (n.) | Đồng nghĩa: fussy, picky · Trái nghĩa: easy-going', '[{"hanzi":"Our finicky cat refuses food unless it is warm.","pinyin":"","meaning":"Con mèo kén chọn của chúng tôi nhất quyết không chịu ăn trừ khi thức ăn được làm nóng."},{"hanzi":"Consumers can be finicky about appearance, leading supermarkets to reject perfectly edible fruit with minor imperfections.","pinyin":"","meaning":"Người tiêu dùng có thể rất khắt khe về mặt ngoại hình, khiến các loại siêu thị từ chối những quả trái cây hoàn toàn ăn được nhưng có khuyết điểm nhỏ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_60_1', 'en-c1-60', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
