INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_1_2', 'ten_c1_60_1', 'freak', 'A freak hailstorm covered our garden in white ice.', 'A freak hailstorm covered our garden in white ice.', '/friːk/', 'Một trận mưa đá bất thường đã phủ trắng khu vườn của chúng tôi bằng một lớp băng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
