INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_1_4', 'ten_c1_60_1', 'suspension', 'The storm caused the suspension of all ferry services.', 'The storm caused the suspension of all ferry services.', '/səˈspenʃən/', 'Cơn bão đã khiến toàn bộ các chuyến phà phải tạm ngừng hoạt động.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_1_5', 'ten_c1_60_1', 'lull', 'We stepped outside during a lull in the rain.', 'We stepped outside during a lull in the rain.', '/lʌl/', 'Chúng tôi bước ra ngoài trong lúc trời ngớt mưa tạm thời.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_1_6', 'ten_c1_60_1', 'haste', 'In my haste, I left my keys on the table.', 'In my haste, I left my keys on the table.', '/heɪst/', 'Vì vội vàng nên tôi đã để quên chìa khóa trên bàn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_1_7', 'ten_c1_60_1', 'midst', 'We found a quiet garden in the midst of town.', 'We found a quiet garden in the midst of town.', '/mɪdst/', 'Chúng tôi tìm thấy một khu vườn yên tĩnh nằm ngay giữa thị trấn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_1_8', 'ten_c1_60_1', 'lurk', 'A cat lurked behind the sofa, watching my shoelaces.', 'A cat lurked behind the sofa, watching my shoelaces.', '/lɝːk/', 'Một con mèo nấp sau ghế sofa, chăm chú nhìn dây giày của tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_60_1_1', 'en-c1-60', 'ten_c1_60_1', 'listening', 'listening', 'A thin trail of smoke rose from the incense.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một làn khói mỏng bay lên từ nén nhang.","Anh ấy lạng choạng lùi về phía sau khi chiếc vali nặng trĩu văng về phía mình.","Tôi đã dọn dẹp lại những chiếc gối để căn phòng trông có vẻ ngăn nắp trở lại.","Chúng tôi tìm thấy một khu vườn yên tĩnh nằm ngay giữa thị trấn."]'::jsonb, 0, 'A thin trail of smoke rose from the incense. → Một làn khói mỏng bay lên từ nén nhang.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_60_1_2', 'en-c1-60', 'ten_c1_60_1', 'listening', 'listening', 'A freak hailstorm covered our garden in white ice.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một trận mưa đá bất thường đã phủ trắng khu vườn của chúng tôi bằng một lớp băng.","Chúng tôi tìm thấy một khu vườn yên tĩnh nằm ngay giữa thị trấn.","Việc gọi điện trước đã giúp chúng tôi không phải mất công đi vòng qua thành phố một cách vô ích.","Anh ấy phủi nhanh một mẩu vụn bánh mì khỏi tay áo trước khi rời đi."]'::jsonb, 0, 'A freak hailstorm covered our garden in white ice. → Một trận mưa đá bất thường đã phủ trắng khu vườn của chúng tôi bằng một lớp băng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_60_1_3', 'en-c1-60', 'ten_c1_60_1', 'listening', 'listening', 'She filled my cup to the brim with tea.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tính đều đặn trong những buổi đi dạo buổi sáng giúp cô ấy ngủ ngon hơn.","Một làn khói mỏng bay lên từ nén nhang.","Cô ấy rót trà đầy đến tận miệng cốc của tôi.","Tôi đã phạm một sai lầm ngớ ngẩn khi đặt nhầm ngày tháng."]'::jsonb, 2, 'She filled my cup to the brim with tea. → Cô ấy rót trà đầy đến tận miệng cốc của tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_60_2', 'en-c1-60', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_2_1', 'ten_c1_60_2', 'incense', 'Burning incense indoors can affect air quality, particularly in small rooms with inadequate ventilation.', 'Burning incense indoors can affect air quality, particularly in small rooms with inadequate ventilation.', '/ˈɪnsens/', 'Đốt nhang trong nhà có thể làm ảnh hưởng đến chất lượng không khí, đặc biệt là trong các căn phòng nhỏ kém thông thoáng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_2_2', 'ten_c1_60_2', 'freak', 'A freak weather event can expose weaknesses in urban infrastructure and disrupt essential public services.', 'A freak weather event can expose weaknesses in urban infrastructure and disrupt essential public services.', '/friːk/', 'Một hiện tượng thời tiết bất thường có thể làm lộ ra những điểm yếu trong cơ sở hạ tầng đô thị và làm gián đoạn các dịch vụ công cộng thiết yếu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_2_3', 'ten_c1_60_2', 'brim', 'Community centres brimming with activity can strengthen social connections and reduce isolation among older residents.', 'Community centres brimming with activity can strengthen social connections and reduce isolation among older residents.', '/brɪm/', 'Các trung tâm cộng đồng tràn ngập các hoạt động có thể thắt chặt mốiσ liên kết xã hội và giảm bớt tình trạng cô lập ở cư dân cao tuổi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_2_4', 'ten_c1_60_2', 'suspension', 'The temporary suspension of construction work allowed researchers to assess the project''s impact on local wildlife.', 'The temporary suspension of construction work allowed researchers to assess the project''s impact on local wildlife.', '/səˈspenʃən/', 'Việc tạm dừng thi công công trình đã giúp các nhà nghiên cứu có cơ hội đánh giá tác động của dự án đối với động vật hoang dã địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_2_5', 'ten_c1_60_2', 'lull', 'A temporary lull in economic activity may give businesses time to review their long-term strategies.', 'A temporary lull in economic activity may give businesses time to review their long-term strategies.', '/lʌl/', 'Sự chững lại tạm thời trong hoạt động kinh tế có thể mang lại thời gian cho các doanh nghiệp nhìn nhận lại chiến lược dài hạn của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_60_2_6', 'ten_c1_60_2', 'haste', 'Policies developed in haste may overlook the needs of vulnerable groups and create additional social problems.', 'Policies developed in haste may overlook the needs of vulnerable groups and create additional social problems.', '/heɪst/', 'Các chính sách được xây dựng một cách vội vàng có thể bỏ qua nhu cầu của các nhóm dễ bị tổn thương và gây ra thêm nhiều vấn đề xã hội.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_60_2_1', 'en-c1-60', 'ten_c1_60_2', 'listening', 'listening', 'Burning incense indoors can affect air quality, particularly in small rooms with inadequate ventilation.', NULL, 'Trong câu vừa nghe, từ “incense” mang nghĩa nào sau đây?', '["nghiêm trọng; ảm đạm; ít mang lại hy vọng","khéo léo; tài tình; cósự sáng tạo độc đáo","nhang; trầm hương; hương","con giun đất"]'::jsonb, 2, '“incense” (/ˈɪnsens/): nhang; trầm hương; hương. Câu đầy đủ: Burning incense indoors can affect air quality, particularly in small rooms with inadequate ventilation.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_60_2_2', 'en-c1-60', 'ten_c1_60_2', 'listening', 'listening', 'A freak weather event can expose weaknesses in urban infrastructure and disrupt essential public services.', NULL, 'Trong câu vừa nghe, từ “freak” mang nghĩa nào sau đây?', '["sửa đổi; điều chỉnh (tài liệu, quy tắc, kế hoạch)","nhồi nhét; nhét đầy vào không gian chật hẹp","vĩ độ","bất thường; kỳ lạ; đột biến"]'::jsonb, 3, '“freak” (/friːk/): bất thường; kỳ lạ; đột biến. Câu đầy đủ: A freak weather event can expose weaknesses in urban infrastructure and disrupt essential public services.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
