INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_2', 'en-c1-60', NULL, 'comprehensive_test', 'listening', 'A freak hailstorm covered our garden in white ice.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Leila sải bước qua sân ga để kịp chuyến tàu của mình.","Một trận mưa đá bất thường đã phủ trắng khu vườn của chúng tôi bằng một lớp băng.","Từ nay về sau, chúng ta sẽ để chìa khóa dự phòng trong ngăn kéo này.","Một làn khói mỏng bay lên từ nén nhang."]'::jsonb, 1, 'A freak hailstorm covered our garden in white ice. → Một trận mưa đá bất thường đã phủ trắng khu vườn của chúng tôi bằng một lớp băng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_3', 'en-c1-60', NULL, 'comprehensive_test', 'listening', 'brim', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hình thành ý tưởng; tưởng tượng","người cư ngụ; người sử dụng; hành khách (trên xe)","hình dung; tưởng tượng; mường tượng","miệng (cốc, bát, hoặc vật chứa khác)"]'::jsonb, 3, 'brim (/brɪm/) → miệng (cốc, bát, hoặc vật chứa khác); vành mũ; tràn ngập; đầy ắp (chất lỏng hoặc cảm xúc mạnh)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_4', 'en-c1-60', NULL, 'comprehensive_test', 'listening', 'The storm caused the suspension of all ferry services.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cơn bão đã khiến toàn bộ các chuyến phà phải tạm ngừng hoạt động.","Dây chằng lều bị chùng xuống sau trận mưa lớn.","Bụi đã bám đầy vào từng đường rãnh của cánh cửa gỗ.","Tôi đã dọn dẹp lại những chiếc gối để căn phòng trông có vẻ ngăn nắp trở lại."]'::jsonb, 0, 'The storm caused the suspension of all ferry services. → Cơn bão đã khiến toàn bộ các chuyến phà phải tạm ngừng hoạt động.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_5', 'en-c1-60', NULL, 'comprehensive_test', 'listening', 'lull', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["du thuyền có khoang ngủ","thuộc địa; thuộc thời kỳ thực dân","nổi tiếng và được ngưỡng mộ rộng rãi nhờ một phẩm chất hoặc thành tựu cụ thể","khoảng thời gian yên ắng tạm thời; khoảng lặng"]'::jsonb, 3, 'lull (/lʌl/) → khoảng thời gian yên ắng tạm thời; khoảng lặng; làm dịu đi; ru ngủ; làm cho mất cảnh giác', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_6', 'en-c1-60', NULL, 'comprehensive_test', 'listening', 'In my haste, I left my keys on the table.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Từ nay về sau, chúng ta sẽ để chìa khóa dự phòng trong ngăn kéo này.","Vì vội vàng nên tôi đã để quên chìa khóa trên bàn.","Xin hãy gói đồ thủy tinh thật cẩn thận trước khi đóng hộp.","Cô ấy đi một nước tốt rồi chăm chú quan sát bàn cờ."]'::jsonb, 1, 'In my haste, I left my keys on the table. → Vì vội vàng nên tôi đã để quên chìa khóa trên bàn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_7', 'en-c1-60', NULL, 'comprehensive_test', 'listening', 'midst', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giữa; trong số","vua hoặc nữ hoàng đóng vai trò là nguyên thủ quốc gia","quyền độc quyền; quyền phân phối hoặc sử dụng độc quyền","bản địa; thuộc về người bản xứ"]'::jsonb, 0, 'midst (/mɪdst/) → giữa; trong số', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_8', 'en-c1-60', NULL, 'comprehensive_test', 'listening', 'A cat lurked behind the sofa, watching my shoelaces.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi bước ra ngoài trong lúc trời ngớt mưa tạm thời.","Một trận mưa đá bất thường đã phủ trắng khu vườn của chúng tôi bằng một lớp băng.","Một con mèo nấp sau ghế sofa, chăm chú nhìn dây giày của tôi.","Cơn bão đã khiến toàn bộ các chuyến phà phải tạm ngừng hoạt động."]'::jsonb, 2, 'A cat lurked behind the sofa, watching my shoelaces. → Một con mèo nấp sau ghế sofa, chăm chú nhìn dây giày của tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_9', 'en-c1-60', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A short period when activity or noise becomes less intense.”?', '["needless","stagger","lull","incense"]'::jsonb, 2, 'lull (/lʌl/) → khoảng thời gian yên ắng tạm thời; khoảng lặng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
