INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_18', 'en-c1-60', NULL, 'comprehensive_test', 'reading', NULL, 'Burning incense indoors can affect air quality, particularly in small rooms with inadequate ventilation.', 'Dựa vào câu trên, từ “incense” có nghĩa phù hợp nhất là gì?', '["nhang; trầm hương; hương","riêng biệt; độc lập; rời rạc","phôi; phôi thai (ở giai đoạn phát triển rất sớm của động vật hoặc thực vật)","quay; chuyển động theo vòng tròn; chạy bằng cơ chế quay"]'::jsonb, 0, 'incense: nhang; trầm hương; hương. Dịch cả câu: Đốt nhang trong nhà có thể làm ảnh hưởng đến chất lượng không khí, đặc biệt là trong các căn phòng nhỏ kém thông thoáng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_19', 'en-c1-60', NULL, 'comprehensive_test', 'reading', NULL, 'A freak weather event can expose weaknesses in urban infrastructure and disrupt essential public services.', 'Dựa vào câu trên, từ “freak” có nghĩa phù hợp nhất là gì?', '["bất thường; kỳ lạ; đột biến","nhỏ; không đáng kể; không quan trọng","sự hạn chế; yếu tố hạn chế","thạch anh"]'::jsonb, 0, 'freak: bất thường; kỳ lạ; đột biến; người cuồng cái gì; tín đồ cuồng nhiệt; hoảng sợ; làm cho hoảng sợ. Dịch cả câu: Một hiện tượng thời tiết bất thường có thể làm lộ ra những điểm yếu trong cơ sở hạ tầng đô thị và làm gián đoạn các dịch vụ công cộng thiết yếu.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_20', 'en-c1-60', NULL, 'comprehensive_test', 'reading', NULL, 'Community centres brimming with activity can strengthen social connections and reduce isolation among older residents.', 'Dựa vào câu trên, từ “brim” có nghĩa phù hợp nhất là gì?', '["cá chép","tự phụ; tự mãn; khoa trương","miệng (cốc, bát, hoặc vật chứa khác)","sự biện minh; lý do chính đáng; căn cứ hợp lý"]'::jsonb, 2, 'brim: miệng (cốc, bát, hoặc vật chứa khác); vành mũ; tràn ngập; đầy ắp (chất lỏng hoặc cảm xúc mạnh). Dịch cả câu: Các trung tâm cộng đồng tràn ngập các hoạt động có thể thắt chặt mốiσ liên kết xã hội và giảm bớt tình trạng cô lập ở cư dân cao tuổi.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_21', 'en-c1-60', NULL, 'comprehensive_test', 'reading', NULL, 'The temporary suspension of construction work allowed researchers to assess the project''s impact on local wildlife.', 'Dựa vào câu trên, từ “suspension” có nghĩa phù hợp nhất là gì?', '["ý định; mục đích","vật mẫu; tiêu bản (động vật, thực vật, vật thể phục vụ nghiên cứu)","sự tạm dừng; sự đình chỉ; sự tạm hoãn","đổ mồ hôi; ra mồ hôi"]'::jsonb, 2, 'suspension: sự tạm dừng; sự đình chỉ; sự tạm hoãn; hệ thống giảm xóc; dung dịch huyền phù; trạng thái lơ lửng. Dịch cả câu: Việc tạm dừng thi công công trình đã giúp các nhà nghiên cứu có cơ hội đánh giá tác động của dự án đối với động vật hoang dã địa phương.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_22', 'en-c1-60', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “búng; gạt nhanh; phủi nhanh”', '["soluble","redistribute","prone","flick"]'::jsonb, 3, 'búng; gạt nhanh; phủi nhanh → flick (/flɪk/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_23', 'en-c1-60', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “không thấm nước; chống nước; kín nước”', '["insofar","malice","watertight","gush"]'::jsonb, 2, 'không thấm nước; chống nước; kín nước → watertight (/ˈwɔːtərtaɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_60_24', 'en-c1-60', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “một sai lầm nghiêm trọng do bất cẩn hoặc thiếu phán đoán chuẩn xác”', '["doubtless","blunder","hydroelectric","capitalism"]'::jsonb, 1, 'một sai lầm nghiêm trọng do bất cẩn hoặc thiếu phán đoán chuẩn xác → blunder (/ˈblʌndər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-61', 'en', 'Bài 61: Đời sống hằng ngày (2) - CEFR C1', 'CEFR C1', 'C1 · Đời sống', '27 từ vựng Tiếng Anh CEFR C1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5061, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snag', 'en-c1-61', 'snag', '/snæɡ/', 'C1', 'trở ngại bất ngờ; khó khăn nhỏ; làm rách; vướng phải vật sắc nhọn', 'n.', NULL, 'Đồng nghĩa: obstacle, hitch', 'Cụm hit a snag có nghĩa là gặp phải trở ngại; động từ thường đi với on để chỉ việc bị vướng vào vật gì.', 'My sweater snagged on a nail by the door.', NULL, 'Chiếc áo len của tôi bị vướng vào một chiếc đinh ở cạnh cửa.', '{"wordId":"snag","ukIpa":"/snæɡ/","usIpa":"/snæɡ/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"An unexpected difficulty that delays or prevents progress.","vi":"trở ngại bất ngờ; khó khăn nhỏ"},{"pos":"v.","en":"To catch or tear something on a sharp or rough object.","vi":"làm rách; vướng phải vật sắc nhọn"}],"examples":[{"en":"My sweater snagged on a nail by the door.","vi":"Chiếc áo len của tôi bị vướng vào một chiếc đinh ở cạnh cửa.","audioKind":"ex"},{"en":"The housing project hit a snag when engineers discovered unstable ground beneath the proposed site.","vi":"Dự án nhà ở gặp trở ngại khi các kỹ sư phát hiện nền đất không ổn định bên dưới khu vực dự kiến xây dựng.","audioKind":"ex2"}],"collocations":[{"en":"hit a snag","vi":"gặp trở ngại"},{"en":"a minor snag","vi":"một khó khăn nhỏ"},{"en":"snag on a nail","vi":"bị móc vào đinh"}],"wordFamily":[],"synonyms":["obstacle","hitch"],"antonyms":[],"tipVi":"Cụm hit a snag có nghĩa là gặp phải trở ngại; động từ thường đi với on để chỉ việc bị vướng vào vật gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rosy', 'en-c1-61', 'rosy', '/ˈroʊzi/', 'C1', 'hồng hào; đỏ hồng; lạc quan; tươi sáng', 'adj.', 'rosiness (n.), rose (n.)', 'Đồng nghĩa: pink, optimistic · Trái nghĩa: pale, bleak', 'Cụm paint a rosy picture có nghĩa là vẽ ra viễn cảnh màu hồng, đôi khi mang hàm ý tô hồng quá mức thực tế.', 'Her cheeks were rosy after walking in the cold.', NULL, 'Má cô ấy trở nên hồng hào sau khi đi dạo trong thời tiết lạnh.', '{"wordId":"rosy","ukIpa":"/ˈrəʊzi/","usIpa":"/ˈroʊzi/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"pink or reddish, especially in a healthy-looking way","vi":"hồng hào; đỏ hồng"},{"pos":"adj.","en":"giving hope of success or happiness, sometimes unrealistically","vi":"lạc quan; tươi sáng"}],"examples":[{"en":"Her cheeks were rosy after walking in the cold.","vi":"Má cô ấy trở nên hồng hào sau khi đi dạo trong thời tiết lạnh.","audioKind":"ex"},{"en":"Although official forecasts paint a rosy picture, rising energy costs could slow the country''s economic recovery.","vi":"Mặc dù các dự báo chính thức vẽ nên một bức tranh tươi sáng, chi phí năng lượng tăng cao có thể làm chậm quá trình phục hồi kinh tế của đất nước.","audioKind":"ex2"}],"collocations":[{"en":"rosy cheeks","vi":"má hồng hào"},{"en":"a rosy future","vi":"tương lai tươi sáng"},{"en":"paint a rosy picture","vi":"vẽ nên bức tranh màu hồng"}],"wordFamily":["rosiness (n.)","rose (n.)"],"synonyms":["pink","optimistic"],"antonyms":["pale","bleak"],"tipVi":"Cụm paint a rosy picture có nghĩa là vẽ ra viễn cảnh màu hồng, đôi khi mang hàm ý tô hồng quá mức thực tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solitary', 'en-c1-61', 'solitary', '/ˈsɑːləteri/', 'C1', 'cô độc; đơn độc; thích sống một mình; duy nhất; đơn lẻ', 'adj.', 'solitude (n.)', 'Đồng nghĩa: alone, lone · Trái nghĩa: sociable', 'solitary nhấn mạnh tính một mình, không nhất thiết mang cảm giác buồn tủi như lonely.', 'A solitary walker followed the quiet path through the woods.', NULL, 'Một người đi bộ đơn độc bước đi dọc theo con đường yên tĩnh xuyên qua khu rừng.', '{"wordId":"solitary","ukIpa":"/ˈsɒlətri/","usIpa":"/ˈsɑːləteri/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Alone, or preferring to live or spend time alone.","vi":"cô độc; đơn độc; thích sống một mình"},{"pos":"adj.","en":"Being the only person or thing present.","vi":"duy nhất; đơn lẻ"}],"examples":[{"en":"A solitary walker followed the quiet path through the woods.","vi":"Một người đi bộ đơn độc bước đi dọc theo con đường yên tĩnh xuyên qua khu rừng.","audioKind":"ex"},{"en":"While solitary study allows deep concentration, collaborative learning helps students develop communication skills and consider alternative perspectives.","vi":"Trong khi việc học một mình giúp tập trung sâu, học tập hợp tác giúp học sinh phát triển kỹ năng giao tiếp và cân nhắc các góc nhìn khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a solitary life","vi":"cuộc sống đơn độc"},{"en":"a solitary figure","vi":"một bóng dáng cô độc"},{"en":"solitary activities","vi":"các hoạt động một mình"},{"en":"a solitary tree","vi":"một cái cây đơn lẻ"}],"wordFamily":["solitude (n.)"],"synonyms":["alone","lone"],"antonyms":["sociable"],"tipVi":"solitary nhấn mạnh tính một mình, không nhất thiết mang cảm giác buồn tủi như lonely.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ample', 'en-c1-61', 'ample', '/ˈæmpəl/', 'C1', 'đầy đủ; dồi dào; thừa thãi; rộng rãi; thênh thang', 'adj.', 'amply (adv.)', 'Đồng nghĩa: plentiful, abundant · Trái nghĩa: insufficient, inadequate', 'ample nhấn mạnh sự đủ hoặc thậm chí dư dả, thường bổ nghĩa cho time, space, evidence.', 'We have ample time for breakfast before the train leaves.', NULL, 'Chúng tôi có thừa thời gian để ăn sáng trước khi tàu chạy.', '{"wordId":"ample","ukIpa":"/ˈæmpəl/","usIpa":"/ˈæmpəl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Enough or more than enough for a particular purpose","vi":"đầy đủ; dồi dào; thừa thãi"},{"pos":"adj.","en":"Large enough to provide plenty of room","vi":"rộng rãi; thênh thang"}],"examples":[{"en":"We have ample time for breakfast before the train leaves.","vi":"Chúng tôi có thừa thời gian để ăn sáng trước khi tàu chạy.","audioKind":"ex"},{"en":"Providing ample green space in residential areas can improve public health and encourage more active lifestyles.","vi":"Việc cung cấp không gian xanh rộng rãi trong các khu dân cư có thể cải thiện sức khỏe công cộng và khuyến khích lối sống năng động hơn.","audioKind":"ex2"}],"collocations":[{"en":"ample time","vi":"thời gian dồi dào"},{"en":"ample evidence","vi":"bằng chứng đầy đủ"},{"en":"ample space","vi":"không gian rộng rãi"},{"en":"ample opportunity","vi":"cơ hội dồi dào"}],"wordFamily":["amply (adv.)"],"synonyms":["plentiful","abundant"],"antonyms":["insufficient","inadequate"],"tipVi":"ample nhấn mạnh sự đủ hoặc thậm chí dư dả, thường bổ nghĩa cho time, space, evidence.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_steamer', 'en-c1-61', 'steamer', '/ˈstiːmər/', 'C1', 'nồi hấp; xửng hấp; tàu thủy chạy bằng hơi nước', 'n.', 'steam (n.), steam (v.), steamed (adj.), steamy (adj.)', NULL, 'Có thể chỉ dụng cụ hấp thức ăn, hoặc tàu chạy bằng động cơ hơi nước.', 'Put the dumplings in the steamer for ten minutes.', NULL, 'Cho bánh bao vào xửng hấp trong mười phút.', '{"wordId":"steamer","ukIpa":"/ˈstiːmə/","usIpa":"/ˈstiːmər/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A container or appliance that cooks food using steam.","vi":"nồi hấp; xửng hấp"},{"pos":"n.","en":"A boat or ship powered by steam.","vi":"tàu thủy chạy bằng hơi nước"}],"examples":[{"en":"Put the dumplings in the steamer for ten minutes.","vi":"Cho bánh bao vào xửng hấp trong mười phút.","audioKind":"ex"},{"en":"The arrival of the steamer transformed river trade by allowing goods to travel more reliably over long distances.","vi":"Sự ra đời của tàu thủy chạy bằng hơi nước đã làm thay đổi thương mại đường sông bằng cách cho phép hàng hóa di chuyển đáng tin cậy hơn trên các chặng đường dài.","audioKind":"ex2"}],"collocations":[{"en":"bamboo steamer","vi":"xửng hấp bằng tre"},{"en":"vegetable steamer","vi":"nồi hấp rau củ"},{"en":"paddle steamer","vi":"tàu thủy chạy bằng bánh guồng"}],"wordFamily":["steam (n.)","steam (v.)","steamed (adj.)","steamy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ dụng cụ hấp thức ăn, hoặc tàu chạy bằng động cơ hơi nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_funnel', 'en-c1-61', 'funnel', '/ˈfʌnəl/', 'C1', 'cái phễu; dẫn hướng; truyền qua; dồn vào; ống khói tàu', 'n.', NULL, NULL, 'Cấu trúc động từ thường dùng là funnel A into B, nghĩa là chuyển hướng hoặc đưa A vào B.', 'Use a funnel to pour oil into the bottle.', NULL, 'Dùng phễu để rót dầu vào chai.', '{"wordId":"funnel","ukIpa":"/ˈfʌnəl/","usIpa":"/ˈfʌnəl/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A wide topped tool with a narrow tube for pouring","vi":"cái phễu"},{"pos":"v.","en":"To direct something through a narrow space or particular route","vi":"dẫn hướng; truyền qua; dồn vào"},{"pos":"n.","en":"A large pipe carrying smoke away from a ship''s engine","vi":"ống khói tàu"}],"examples":[{"en":"Use a funnel to pour oil into the bottle.","vi":"Dùng phễu để rót dầu vào chai.","audioKind":"ex"},{"en":"Well-designed drainage systems funnel rainwater into storage tanks, reducing the risk of urban flooding.","vi":"Hệ thống thoát nước được thiết kế tốt giúp dẫn nước mưa vào các bể chứa, làm giảm nguy cơ ngập lụt đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a plastic funnel","vi":"phễu nhựa"},{"en":"funnel water into","vi":"dẫn nước vào"},{"en":"a ship''s funnel","vi":"ống khói tàu thủy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc động từ thường dùng là funnel A into B, nghĩa là chuyển hướng hoặc đưa A vào B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_illuminate', 'en-c1-61', 'illuminate', '/ɪˈluːməneɪt/', 'C1', 'chiếu sáng; rọi sáng; làm sáng tỏ; giải thích', 'v.', 'illumination (n.), illuminating (adj.)', 'Đồng nghĩa: light up, clarify · Trái nghĩa: darken, obscure', 'Có thể dùng với nghĩa đen là thắp sáng hoặc nghĩa bóng là làm sáng tỏ vấn đề.', 'Small lamps illuminate the garden path after sunset.', NULL, 'Những chiếc đèn nhỏ chiếu sáng lối đi trong vườn sau khi mặt trời lặn.', '{"wordId":"illuminate","ukIpa":"/ɪˈluːmɪneɪt/","usIpa":"/ɪˈluːməneɪt/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To shine light on something so it becomes visible","vi":"chiếu sáng; rọi sáng"},{"pos":"v.","en":"To make a subject or problem easier to understand","vi":"làm sáng tỏ; giải thích"}],"examples":[{"en":"Small lamps illuminate the garden path after sunset.","vi":"Những chiếc đèn nhỏ chiếu sáng lối đi trong vườn sau khi mặt trời lặn.","audioKind":"ex"},{"en":"Comparing different education systems can illuminate the factors that influence student achievement across diverse social backgrounds.","vi":"Việc so sánh các hệ thống giáo dục khác nhau có thể làm sáng tỏ các yếu tố ảnh hưởng đến thành tích học tập của học sinh từ các hoàn cảnh xã hội đa dạng.","audioKind":"ex2"}],"collocations":[{"en":"illuminate a room","vi":"chiếu sáng căn phòng"},{"en":"illuminate an issue","vi":"làm sáng tỏ một vấn đề"},{"en":"brightly illuminated","vi":"được chiếu sáng rực rỡ"}],"wordFamily":["illumination (n.)","illuminating (adj.)"],"synonyms":["light up","clarify"],"antonyms":["darken","obscure"],"tipVi":"Có thể dùng với nghĩa đen là thắp sáng hoặc nghĩa bóng là làm sáng tỏ vấn đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pester', 'en-c1-61', 'pester', '/ˈpestɚ/', 'C1', 'quấy rầy; làm phiền; đeo bám', 'v.', NULL, 'Đồng nghĩa: bother, harass', 'Thường dùng cấu trúc pester sb for sth hoặc to do sth, nhấn mạnh hành động quấy rầy, đòi hỏi liên tục.', 'The children pestered their uncle for another bedtime story.', NULL, 'Lũ trẻ cứ nài nỉ chú kể thêm một câu chuyện trước khi đi ngủ.', '{"wordId":"pester","ukIpa":"/ˈpestə/","usIpa":"/ˈpestɚ/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"annoy someone by repeatedly asking for something or demanding attention","vi":"quấy rầy; làm phiền; đeo bám"}],"examples":[{"en":"The children pestered their uncle for another bedtime story.","vi":"Lũ trẻ cứ nài nỉ chú kể thêm một câu chuyện trước khi đi ngủ.","audioKind":"ex"},{"en":"Some online advertisements pester users with repeated requests, potentially reducing trust in digital services.","vi":"Một số quảng cáo trực tuyến liên tục quấy rầy người dùng bằng các yêu cầu lặp đi lặp lại, có khả năng làm giảm lòng tin đối với các dịch vụ kỹ thuật số.","audioKind":"ex2"}],"collocations":[{"en":"pester someone for something","vi":"đeo bám ai để xin cái gì"},{"en":"pester someone to do something","vi":"quấy rầy ai làm việc gì"},{"en":"pester someone with questions","vi":"làm phiền ai bằng những câu hỏi"}],"wordFamily":[],"synonyms":["bother","harass"],"antonyms":[],"tipVi":"Thường dùng cấu trúc pester sb for sth hoặc to do sth, nhấn mạnh hành động quấy rầy, đòi hỏi liên tục.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ragged', 'en-c1-61', 'ragged', '/ˈræɡɪd/', 'C1', 'rách rưới, tả tơi; mặc quần áo rách rưới; có viền, đường nét hoặc hoa văn gồ ghề, không đều', 'adj.', 'rag (n.), raggedly (adv.), raggedness (n.)', 'Đồng nghĩa: tattered, shabby', 'Tính từ ragged phát âm thành hai âm tiết, kết thúc bằng âm /ɪd/.', 'He patched the ragged sleeves of his old coat.', NULL, 'Anh ấy vá lại phần tay áo rách rưới của chiếc áo khoác cũ.', '{"wordId":"ragged","ukIpa":"/ˈræɡɪd/","usIpa":"/ˈræɡɪd/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"torn and worn, or wearing clothes in this condition","vi":"rách rưới, tả tơi; mặc quần áo rách rưới"},{"pos":"adj.","en":"having an uneven edge, outline, or pattern","vi":"có viền, đường nét hoặc hoa văn gồ ghề, không đều"}],"examples":[{"en":"He patched the ragged sleeves of his old coat.","vi":"Anh ấy vá lại phần tay áo rách rưới của chiếc áo khoác cũ.","audioKind":"ex"},{"en":"Discarded clothing, including ragged garments, can be recycled into insulation rather than sent to landfill.","vi":"Quần áo bỏ đi, bao gồm cả trang phục rách rưới, có thể được tái chế thành vật liệu cách nhiệt thay vì đem chôn lấp.","audioKind":"ex2"}],"collocations":[{"en":"ragged clothes","vi":"quần áo rách rưới"},{"en":"ragged edges","vi":"cạnh sắc gồ ghề"},{"en":"ragged breathing","vi":"hơi thở đứt quãng"}],"wordFamily":["rag (n.)","raggedly (adv.)","raggedness (n.)"],"synonyms":["tattered","shabby"],"antonyms":[],"tipVi":"Tính từ ragged phát âm thành hai âm tiết, kết thúc bằng âm /ɪd/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aimless', 'en-c1-61', 'aimless', '/ˈeɪmləs/', 'C1', 'không có mục đích, kế hoạch hoặc phương hướng rõ ràng', 'adj.', 'aim (n.), aim (v.), aimlessly (adv.), aimlessness (n.)', 'Đồng nghĩa: purposeless, directionless · Trái nghĩa: purposeful', 'Aimless là tính từ; để bổ nghĩa cho các động từ như wander thì dùng trạng từ aimlessly.', 'We spent the afternoon on an aimless walk.', NULL, 'Chúng tôi dành cả buổi chiều để đi dạo không mục đích.', '{"wordId":"aimless","ukIpa":"/ˈeɪmləs/","usIpa":"/ˈeɪmləs/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"having no clear purpose, plan, or direction","vi":"không có mục đích, kế hoạch hoặc phương hướng rõ ràng"}],"examples":[{"en":"We spent the afternoon on an aimless walk.","vi":"Chúng tôi dành cả buổi chiều để đi dạo không mục đích.","audioKind":"ex"},{"en":"Without clear learning goals, students may engage in aimless online browsing rather than developing useful research skills.","vi":"Nếu không có mục tiêu học tập rõ ràng, học sinh có thể lướt web vô định thay vì trau dồi các kỹ năng nghiên cứu hữu ích.","audioKind":"ex2"}],"collocations":[{"en":"aimless wandering","vi":"đi lang thang không mục đích"},{"en":"aimless browsing","vi":"lướt web vô định"},{"en":"an aimless existence","vi":"một cuộc sống không mục đích"}],"wordFamily":["aim (n.)","aim (v.)","aimlessly (adv.)","aimlessness (n.)"],"synonyms":["purposeless","directionless"],"antonyms":["purposeful"],"tipVi":"Aimless là tính từ; để bổ nghĩa cho các động từ như wander thì dùng trạng từ aimlessly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jingle', 'en-c1-61', 'jingle', '/ˈdʒɪŋɡəl/', 'C1', 'kêu lanh canh; làm kêu lanh canh; tiếng lanh canh; nhạc hiệu quảng cáo ngắn', 'v.', NULL, NULL, 'Có thể chỉ âm thanh kim loại va chạm hoặc giai điệu quảng cáo ngắn gọn, bắt tai.', 'The keys jingled as she unlocked the front door.', NULL, 'Chùm chìa khóa kêu lanh canh khi cô ấy mở cửa trước.', '{"wordId":"jingle","ukIpa":"/ˈdʒɪŋɡəl/","usIpa":"/ˈdʒɪŋɡəl/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To make small metal objects produce light ringing sounds.","vi":"kêu lanh canh; làm kêu lanh canh"},{"pos":"n.","en":"A light ringing sound, or a short advertising song.","vi":"tiếng lanh canh; nhạc hiệu quảng cáo ngắn"}],"examples":[{"en":"The keys jingled as she unlocked the front door.","vi":"Chùm chìa khóa kêu lanh canh khi cô ấy mở cửa trước.","audioKind":"ex"},{"en":"A memorable advertising jingle can influence consumer choices long after a campaign has ended.","vi":"Một giai điệu quảng cáo dễ nhớ có thể ảnh hưởng đến lựa chọn của người tiêu dùng lâu sau khi chiến dịch kết thúc.","audioKind":"ex2"}],"collocations":[{"en":"jingle your keys","vi":"làm chìa khóa kêu lanh canh"},{"en":"advertising jingle","vi":"nhạc hiệu quảng cáo"},{"en":"the jingle of bells","vi":"tiếng chuông kêu lanh canh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ âm thanh kim loại va chạm hoặc giai điệu quảng cáo ngắn gọn, bắt tai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stoop', 'en-c1-61', 'stoop', '/stuːp/', 'C1', 'cúi xuống; khom lưng; hạ mình làm chuyện hèn hạ; tự hạ thấp phẩm giá; dáng đi còng lưng; tư thế gù lưng', 'v.', NULL, NULL, 'stoop to doing biểu thị việc không ngần ngại làm chuyện hèn hạ, trong đó to là giới từ.', 'She stooped to pick up the fallen orange.', NULL, 'Cô ấy cúi xuống để nhặt quả cam bị rơi lên.', '{"wordId":"stoop","ukIpa":"/stuːp/","usIpa":"/stuːp/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to bend your upper body forward and downward","vi":"cúi xuống; khom lưng"},{"pos":"v.","en":"to do something dishonest or morally wrong","vi":"hạ mình làm chuyện hèn hạ; tự hạ thấp phẩm giá"},{"pos":"n.","en":"a posture with the shoulders and upper back bent forward","vi":"dáng đi còng lưng; tư thế gù lưng"}],"examples":[{"en":"She stooped to pick up the fallen orange.","vi":"Cô ấy cúi xuống để nhặt quả cam bị rơi lên.","audioKind":"ex"},{"en":"Companies should not stoop to misleading advertising merely to increase sales in an increasingly competitive market.","vi":"Các công ty không nên hạ mình sử dụng quảng cáo gây hiểu lầm chỉ để tăng doanh số trong một thị trường ngày càng cạnh tranh.","audioKind":"ex2"}],"collocations":[{"en":"stoop to pick something up","vi":"cúi xuống nhặt vật gì"},{"en":"stoop to deception","vi":"hạ mình lừa dối"},{"en":"walk with a stoop","vi":"dáng đi còng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"stoop to doing biểu thị việc không ngần ngại làm chuyện hèn hạ, trong đó to là giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kerosene', 'en-c1-61', 'kerosene', '/ˈkerəsiːn/', 'C1', 'dầu hỏa; dầu hôi', 'n.', NULL, 'Đồng nghĩa: paraffin', 'Là danh từ không đếm được; trong tiếng Anh Anh đời thường còn gọi là paraffin.', 'We bought kerosene for the old lamp at the cabin.', NULL, 'Chúng tôi đã mua dầu hỏa cho chiếc đèn cũ trong nhà gỗ.', '{"wordId":"kerosene","ukIpa":"/ˈkerəsiːn/","usIpa":"/ˈkerəsiːn/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"An oil used as fuel for lamps, heaters, and aircraft.","vi":"dầu hỏa; dầu hôi"}],"examples":[{"en":"We bought kerosene for the old lamp at the cabin.","vi":"Chúng tôi đã mua dầu hỏa cho chiếc đèn cũ trong nhà gỗ.","audioKind":"ex"},{"en":"Replacing kerosene lamps with solar lighting can reduce indoor air pollution in communities without reliable electricity.","vi":"Việc thay thế đèn dầu hỏa bằng hệ thống chiếu sáng năng lượng mặt trời có thể giảm ô nhiễm không khí trong nhà ở các cộng đồng chưa có điện ổn định.","audioKind":"ex2"}],"collocations":[{"en":"kerosene lamp","vi":"đèn dầu hỏa"},{"en":"kerosene heater","vi":"lò sưởi dầu hỏa"},{"en":"aviation kerosene","vi":"dầu hỏa hàng không"}],"wordFamily":[],"synonyms":["paraffin"],"antonyms":[],"tipVi":"Là danh từ không đếm được; trong tiếng Anh Anh đời thường còn gọi là paraffin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oblong', 'en-c1-61', 'oblong', '/ˈɑːblɔːŋ/', 'C1', 'có hình chữ nhật (với các cạnh kề không bằng nhau); hình chữ nhật', 'adj.', NULL, 'Đồng nghĩa: rectangular', 'Nhấn mạnh hình chữ nhật có chiều dài và chiều rộng khác nhau; không chỉ hình vuông.', 'She served the sandwiches on an oblong wooden plate.', NULL, 'Cô ấy bày bánh mì kẹp trên một chiếc đĩa gỗ hình chữ nhật.', '{"wordId":"oblong","ukIpa":"/ˈɒblɒŋ/","usIpa":"/ˈɑːblɔːŋ/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"having a rectangular shape with unequal adjacent sides","vi":"có hình chữ nhật (với các cạnh kề không bằng nhau)"},{"pos":"n.","en":"a rectangle with two sides longer than the other two","vi":"hình chữ nhật"}],"examples":[{"en":"She served the sandwiches on an oblong wooden plate.","vi":"Cô ấy bày bánh mì kẹp trên một chiếc đĩa gỗ hình chữ nhật.","audioKind":"ex"},{"en":"The architect chose an oblong layout to maximise usable space within the small community centre.","vi":"Kiến trúc sư đã chọn bố cục hình chữ nhật để tối đa hóa không gian sử dụng bên trong trung tâm cộng đồng nhỏ này.","audioKind":"ex2"}],"collocations":[{"en":"oblong table","vi":"bàn hình chữ nhật"},{"en":"oblong shape","vi":"hình chữ nhật"},{"en":"oblong tray","vi":"khay hình chữ nhật"}],"wordFamily":[],"synonyms":["rectangular"],"antonyms":[],"tipVi":"Nhấn mạnh hình chữ nhật có chiều dài và chiều rộng khác nhau; không chỉ hình vuông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outward', 'en-c1-61', 'outward', '/ˈaʊtwɚd/', 'C1', 'bề ngoài; vẻ bề ngoài; hướng ra ngoài; hướng về phía ngoài', 'adj.', 'outwardly (adv.), outwards (adv.)', 'Đồng nghĩa: external · Trái nghĩa: inward', 'Khi đóng vai trò phó từ, tiếng Anh-Anh thường dùng outwards.', 'Despite her outward confidence, Leila felt nervous inside.', NULL, 'Bất chấp vẻ bề ngoài tự tin, Leila cảm thấy căng thẳng ở bên trong.', '{"wordId":"outward","ukIpa":"/ˈaʊtwəd/","usIpa":"/ˈaʊtwɚd/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"visible on the outside rather than reflecting inner feelings","vi":"bề ngoài; vẻ bề ngoài"},{"pos":"adj.","en":"moving or directed away from the centre or starting point","vi":"hướng ra ngoài"},{"pos":"adv.","en":"towards the outside or away from the centre","vi":"hướng về phía ngoài"}],"examples":[{"en":"Despite her outward confidence, Leila felt nervous inside.","vi":"Bất chấp vẻ bề ngoài tự tin, Leila cảm thấy căng thẳng ở bên trong.","audioKind":"ex"},{"en":"A city''s outward appearance may improve through redevelopment, while underlying social inequalities remain largely unchanged.","vi":"Vẻ bề ngoài của một thành phố có thể được cải thiện thông qua việc tái phát triển, trong khi những bất bình đẳng xã hội tiềm ẩn vẫn hầu như không thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"outward appearance","vi":"vẻ bề ngoài"},{"en":"outward signs","vi":"dấu hiệu bên ngoài"},{"en":"outward journey","vi":"hành trình đi"},{"en":"outward movement","vi":"chuyển động hướng ra ngoài"}],"wordFamily":["outwardly (adv.)","outwards (adv.)"],"synonyms":["external"],"antonyms":["inward"],"tipVi":"Khi đóng vai trò phó từ, tiếng Anh-Anh thường dùng outwards.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_generic', 'en-c1-61', 'generic', '/dʒəˈnerɪk/', 'C1', 'chung chung; không cụ thể; không có thương hiệu; không đăng ký nhãn hiệu độc quyền', 'adj.', 'generically (adv.)', 'Đồng nghĩa: general, non-specific · Trái nghĩa: specific', 'Generic nhấn mạnh tính không cụ thể; generic medicine thường chỉ thuốc generic (thuốc không có thương hiệu độc quyền).', 'The website sent me a generic reply about delivery.', NULL, 'Trang web đã gửi cho tôi một phản hồi chung chung về việc giao hàng.', '{"wordId":"generic","ukIpa":"/dʒəˈnerɪk/","usIpa":"/dʒəˈnerɪk/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Relating to a whole group rather than one particular example.","vi":"chung chung; không cụ thể"},{"pos":"adj.","en":"Sold without a brand name or no longer protected by patent.","vi":"không có thương hiệu; không đăng ký nhãn hiệu độc quyền"}],"examples":[{"en":"The website sent me a generic reply about delivery.","vi":"Trang web đã gửi cho tôi một phản hồi chung chung về việc giao hàng.","audioKind":"ex"},{"en":"Generic medicines can reduce healthcare costs while providing the same active ingredients as their branded equivalents.","vi":"Thuốc không có thương hiệu có thể làm giảm chi phí y tế trong khi vẫn cung cấp các hoạt chất giống hệt như các loại thuốc mang nhãn hiệu tương đương.","audioKind":"ex2"}],"collocations":[{"en":"generic term","vi":"thuật ngữ chung"},{"en":"generic advice","vi":"lời khuyên chung chung"},{"en":"generic medicine","vi":"thuốc không nhãn hiệu"},{"en":"generic version","vi":"phiên bản không thương hiệu"}],"wordFamily":["generically (adv.)"],"synonyms":["general","non-specific"],"antonyms":["specific"],"tipVi":"Generic nhấn mạnh tính không cụ thể; generic medicine thường chỉ thuốc generic (thuốc không có thương hiệu độc quyền).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_verge', 'en-c1-61', 'verge', '/vɝːdʒ/', 'C1', 'bờ vực; ranh giới; thời điểm ngay trước khi điều gì xảy ra; dải cỏ bên đường; suýt; gần như; tiệm cận', 'n.', NULL, 'Đồng nghĩa: brink, edge', 'Cấu trúc on the verge of đi kèm với danh từ hoặc danh động từ; động từ verge thường đi với giới từ on.', 'She was on the verge of tears after losing her ring.', NULL, 'Cô ấy suýt khóc sau khi đánh mất chiếc nhẫn của mình.', '{"wordId":"verge","ukIpa":"/vɜːdʒ/","usIpa":"/vɝːdʒ/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"The point just before something happens.","vi":"bờ vực; ranh giới; thời điểm ngay trước khi điều gì xảy ra"},{"pos":"n.","en":"A strip of grass beside a road.","vi":"dải cỏ bên đường"},{"pos":"v.","en":"To come close to a particular state or quality.","vi":"suýt; gần như; tiệm cận"}],"examples":[{"en":"She was on the verge of tears after losing her ring.","vi":"Cô ấy suýt khóc sau khi đánh mất chiếc nhẫn của mình.","audioKind":"ex"},{"en":"Several native species are on the verge of extinction because their habitats have been severely damaged.","vi":"Một số loài bảnđịa đang đứng trước bờ vực tuyệt chủng vì môi trường sống của chúng bị tàn phá nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"on the verge of extinction","vi":"bờ vực tuyệt chủng"},{"en":"on the verge of doing something","vi":"sắp sửa làm gì đó"},{"en":"a grass verge","vi":"dải cỏ lề đường"},{"en":"verge on the absurd","vi":"gần như vô lý"}],"wordFamily":[],"synonyms":["brink","edge"],"antonyms":[],"tipVi":"Cấu trúc on the verge of đi kèm với danh từ hoặc danh động từ; động từ verge thường đi với giới từ on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swift', 'en-c1-61', 'swift', '/swɪft/', 'C1', 'nhanh chóng; nhanh nhẹn; chim nhạn', 'adj.', 'swiftly (adv.), swiftness (n.)', 'Đồng nghĩa: quick, rapid, speedy · Trái nghĩa: slow', 'Thường bổ nghĩa cho action, response; trạng từ tương ứng là swiftly.', 'Her swift reaction stopped the glass from falling.', NULL, 'Phản ứng nhanh nhẹn của cô ấy đã ngăn chiếc ly rơi xuống.', '{"wordId":"swift","ukIpa":"/swɪft/","usIpa":"/swɪft/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Moving quickly or happening after very little delay.","vi":"nhanh chóng; nhanh nhẹn"},{"pos":"n.","en":"A small bird with long curved wings that flies fast.","vi":"chim nhạn"}],"examples":[{"en":"Her swift reaction stopped the glass from falling.","vi":"Phản ứng nhanh nhẹn của cô ấy đã ngăn chiếc ly rơi xuống.","audioKind":"ex"},{"en":"A swift response to disease outbreaks can reduce pressure on hospitals and protect vulnerable communities.","vi":"Phản ứng nhanh chóng đối với các đợt bùng phát dịch bệnh có thể giảm bớt áp lực cho các bệnh viện và bảo vệ các cộng đồng dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"swift action","vi":"hành động nhanh chóng"},{"en":"swift response","vi":"phản hồi nhanh chóng"},{"en":"swift recovery","vi":"phục hồi nhanh chóng"}],"wordFamily":["swiftly (adv.)","swiftness (n.)"],"synonyms":["quick","rapid","speedy"],"antonyms":["slow"],"tipVi":"Thường bổ nghĩa cho action, response; trạng từ tương ứng là swiftly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elevate', 'en-c1-61', 'elevate', '/ˈeləveɪt/', 'C1', 'nâng lên; đưa lên cao; nâng cao; cải thiện; làm phấn chấn; làm vui lên', 'v.', 'elevation (n.), elevated (adj.), elevator (n.)', 'Đồng nghĩa: raise, lift · Trái nghĩa: lower', 'Động từ chỉ trạng thái/hành động; cấu trúc elevate A to B có thể biểu thị việc nâng A lên mức B.', 'The nurse used a pillow to elevate my ankle.', NULL, 'Y tá dùng một chiếc gối để kê cao mắt cá chân của tôi.', '{"wordId":"elevate","ukIpa":"/ˈelɪveɪt/","usIpa":"/ˈeləveɪt/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To move something to a higher physical position","vi":"nâng lên; đưa lên cao"},{"pos":"v.","en":"To raise someone''s status or improve the quality of something","vi":"nâng cao; cải thiện"},{"pos":"v.","en":"To make someone feel happier or more hopeful","vi":"làm phấn chấn; làm vui lên"}],"examples":[{"en":"The nurse used a pillow to elevate my ankle.","vi":"Y tá dùng một chiếc gối để kê cao mắt cá chân của tôi.","audioKind":"ex"},{"en":"Access to advanced training can elevate professional standards and improve the quality of public services.","vi":"Việc tiếp cận đào tạo nâng cao có thể nâng tầm tiêu chuẩn nghề nghiệp và cải thiện chất lượng dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"elevate a limb","vi":"nâng chi"},{"en":"elevate standards","vi":"nâng cao tiêu chuẩn"},{"en":"elevate someone to a position","vi":"thăng chức cho ai lên vị trí nào"},{"en":"elevate mood","vi":"cải thiện tâm trạng"}],"wordFamily":["elevation (n.)","elevated (adj.)","elevator (n.)"],"synonyms":["raise","lift"],"antonyms":["lower"],"tipVi":"Động từ chỉ trạng thái/hành động; cấu trúc elevate A to B có thể biểu thị việc nâng A lên mức B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deft', 'en-c1-61', 'deft', '/deft/', 'C1', 'khéo léo; nhanh nhẹn và chuẩn xác', 'adj.', 'deftly (adv.), deftness (n.)', 'Đồng nghĩa: skilful, dexterous, adroit · Trái nghĩa: clumsy', 'Có thể dùng để miêu tả cả sự khéo léo của đôi tay lẫn sự khôn khéo trong việc giải quyết vấn đề.', 'With a deft movement, she caught the falling cup.', NULL, 'Với một động tác nhanh gọn, cô ấy đã đỡ được chiếc cốc đang rơi.', '{"wordId":"deft","ukIpa":"/deft/","usIpa":"/deft/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Skilful, quick, and controlled in movement or action.","vi":"khéo léo; nhanh nhẹn và chuẩn xác"}],"examples":[{"en":"With a deft movement, she caught the falling cup.","vi":"Với một động tác nhanh gọn, cô ấy đã đỡ được chiếc cốc đang rơi.","audioKind":"ex"},{"en":"Effective classroom management requires deft handling of disagreements between students from different backgrounds.","vi":"Công tác quản lý lớp học hiệu quả đòi hỏi sự xử lý khéo léo đối với những bất đồng giữa các học sinh đến từ những hoàn cảnh khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"deft touch","vi":"thao tác khéo léo"},{"en":"deft handling","vi":"cách xử lý khéo léo"},{"en":"deft movement","vi":"động tác linh hoạt"}],"wordFamily":["deftly (adv.)","deftness (n.)"],"synonyms":["skilful","dexterous","adroit"],"antonyms":["clumsy"],"tipVi":"Có thể dùng để miêu tả cả sự khéo léo của đôi tay lẫn sự khôn khéo trong việc giải quyết vấn đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_culminate', 'en-c1-61', 'culminate', '/ˈkʌlmɪneɪt/', 'C1', 'lên đến đỉnh điểm; kết thúc bằng', 'v.', 'culmination (n.)', NULL, 'Thường dùng cấu trúc culminate in + kết quả, nhấn mạnh điểm kết thúc hoặc cao trào sau một quá trình phát triển.', 'Weeks of rehearsals culminated in a wonderful evening performance.', NULL, 'Nhiều tuần tập luyện đã khép lại bằng một buổi biểu diễn tối tuyệt vời.', '{"wordId":"culminate","ukIpa":"/ˈkʌlmɪneɪt/","usIpa":"/ˈkʌlmɪneɪt/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To reach a final result or highest point after gradual development","vi":"lên đến đỉnh điểm; kết thúc bằng"}],"examples":[{"en":"Weeks of rehearsals culminated in a wonderful evening performance.","vi":"Nhiều tuần tập luyện đã khép lại bằng một buổi biểu diễn tối tuyệt vời.","audioKind":"ex"},{"en":"Years of public consultation culminated in a comprehensive transport plan designed to reduce congestion and improve accessibility.","vi":"Nhiều năm tham vấn công khai đã kết thúc bằng một kế hoạch giao thông toàn diện nhằm giảm ùn tắc và cải thiện khả năng tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"culminate in success","vi":"kết thúc bằng thành công"},{"en":"culminate in an agreement","vi":"đi đến một thỏa thuận"},{"en":"culminate in a celebration","vi":"kết thúc bằng một buổi lễ ăn mừng"}],"wordFamily":["culmination (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc culminate in + kết quả, nhấn mạnh điểm kết thúc hoặc cao trào sau một quá trình phát triển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sluggish', 'en-c1-61', 'sluggish', '/ˈslʌɡɪʃ/', 'C1', 'chậm chạp; uể oải; lờ đờ; chậm phát triển; đình trệ; kém sôi động', 'adj.', 'sluggishly (adv.), sluggishness (n.)', 'Đồng nghĩa: slow, lethargic · Trái nghĩa: energetic, brisk', 'Vừa dùng để mô tả trạng thái thiếu năng lượng ở con người, vừa dùng để chỉ tốc độ phát triển chậm của nền kinh tế hoặc hệ thống.', 'I felt sluggish after eating such a large lunch.', NULL, 'Tôi cảm thấy uể oải sau khi ăn một bữa trưa quá thịnh soạn.', '{"wordId":"sluggish","ukIpa":"/ˈslʌɡɪʃ/","usIpa":"/ˈslʌɡɪʃ/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"moving or responding slowly, often from lack of energy","vi":"chậm chạp; uể oải; lờ đờ"},{"pos":"adj.","en":"growing or operating more slowly than expected","vi":"chậm phát triển; đình trệ; kém sôi động"}],"examples":[{"en":"I felt sluggish after eating such a large lunch.","vi":"Tôi cảm thấy uể oải sau khi ăn một bữa trưa quá thịnh soạn.","audioKind":"ex"},{"en":"Sluggish economic growth can discourage investment and limit employment opportunities for recent university graduates.","vi":"Tăng trưởng kinh tế trì trệ có thể làm nản lòng các nhà đầu tư và hạn chế cơ hội việc làm cho sinh viên mới tốt nghiệp đại học.","audioKind":"ex2"}],"collocations":[{"en":"feel sluggish","vi":"cảm thấy uể oải; cảm thấy lờ đờ"},{"en":"sluggish growth","vi":"tăng trưởng chậm chạp; tăng trưởng trì trệ"},{"en":"sluggish response","vi":"phản ứng chậm chạp"}],"wordFamily":["sluggishly (adv.)","sluggishness (n.)"],"synonyms":["slow","lethargic"],"antonyms":["energetic","brisk"],"tipVi":"Vừa dùng để mô tả trạng thái thiếu năng lượng ở con người, vừa dùng để chỉ tốc độ phát triển chậm của nền kinh tế hoặc hệ thống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uncap', 'en-c1-61', 'uncap', '/ʌnˈkæp/', 'C1', 'mở nắp; tháo nắp', 'v.', 'cap (n.), cap (v.), recap (v.)', 'Trái nghĩa: cap', 'Chỉ đặc thù hành động mở/tháo nắp; dạng quá khứ là uncapped, dạng phân từ là uncapping.', 'She uncapped the bottle and poured everyone some juice.', NULL, 'Cô ấy mở nắp chai và rót nước trái cây cho mọi người.', '{"wordId":"uncap","ukIpa":"/ʌnˈkæp/","usIpa":"/ʌnˈkæp/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To remove the cap from a container or pen.","vi":"mở nắp; tháo nắp"}],"examples":[{"en":"She uncapped the bottle and poured everyone some juice.","vi":"Cô ấy mở nắp chai và rót nước trái cây cho mọi người.","audioKind":"ex"},{"en":"Laboratory staff should uncap sample containers carefully to prevent contamination and maintain reliable research results.","vi":"Nhân viên phòng thí nghiệm nên cẩn thận tháo nắp các vật chứa mẫu để phòng tránh ô nhiễm và đảm bảo kết quả nghiên cứu đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"uncap a bottle","vi":"mở nắp chai"},{"en":"uncap a pen","vi":"mở nắp bút"},{"en":"uncap a container","vi":"tháo nắp vật chứa"}],"wordFamily":["cap (n.)","cap (v.)","recap (v.)"],"synonyms":[],"antonyms":["cap"],"tipVi":"Chỉ đặc thù hành động mở/tháo nắp; dạng quá khứ là uncapped, dạng phân từ là uncapping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hideous', 'en-c1-61', 'hideous', '/ˈhɪdiəs/', 'C1', 'xấu xí; gớm ghiếc; kinh hoàng; khủng khiếp', 'adj.', 'hideously (adv.), hideousness (n.)', 'Đồng nghĩa: ugly, ghastly, horrible · Trái nghĩa: beautiful', 'Sắc thái nghĩa mạnh, thường dùng để tả vẻ bề ngoài cực kỳ xấu hoặc sự việc khủng khiếp.', 'That hideous carpet clashes with everything in the room.', NULL, 'Tấm thảm xấu xí đó chẳng hề hòa hợp với bất cứ thứ gì trong phòng.', '{"wordId":"hideous","ukIpa":"/ˈhɪdiəs/","usIpa":"/ˈhɪdiəs/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"extremely ugly or unpleasant","vi":"xấu xí; gớm ghiếc"},{"pos":"adj.","en":"extremely shocking or terrible","vi":"kinh hoàng; khủng khiếp"}],"examples":[{"en":"That hideous carpet clashes with everything in the room.","vi":"Tấm thảm xấu xí đó chẳng hề hòa hợp với bất cứ thứ gì trong phòng.","audioKind":"ex"},{"en":"Poorly planned developments can create hideous buildings that damage the visual character of historic neighbourhoods.","vi":"Các dự án phát triển được quy hoạch kém có thể tạo ra những công trình kiến trúc vô cùng xấu xí, làm tổn hại đến bộ mặt thẩm mỹ của các khu phố lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"a hideous building","vi":"một tòa nhà xấu xí"},{"en":"a hideous mistake","vi":"một sai lầm kinh hoàng"},{"en":"hideous noise","vi":"tiếng ồn khó chịu"}],"wordFamily":["hideously (adv.)","hideousness (n.)"],"synonyms":["ugly","ghastly","horrible"],"antonyms":["beautiful"],"tipVi":"Sắc thái nghĩa mạnh, thường dùng để tả vẻ bề ngoài cực kỳ xấu hoặc sự việc khủng khiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outlandish', 'en-c1-61', 'outlandish', '/aʊtˈlændɪʃ/', 'C1', 'kỳ lạ; quái dị; ho đường', 'adj.', 'outlandishly (adv.), outlandishness (n.)', 'Đồng nghĩa: bizarre, eccentric, unconventional · Trái nghĩa: ordinary, conventional', 'Nhấn mạnh sự khác thường, thường mang sắc thái ngạc nhiên hoặc không tán thành.', 'He arrived wearing an outlandish hat shaped like a pineapple.', NULL, 'Anh ấy đến với một chiếc mũ kỳ dị hình quả dứa.', '{"wordId":"outlandish","ukIpa":"/aʊtˈlændɪʃ/","usIpa":"/aʊtˈlændɪʃ/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"extremely unusual or strange, often seeming unreasonable","vi":"kỳ lạ; quái dị; ho đường"}],"examples":[{"en":"He arrived wearing an outlandish hat shaped like a pineapple.","vi":"Anh ấy đến với một chiếc mũ kỳ dị hình quả dứa.","audioKind":"ex"},{"en":"Although some environmental proposals initially seem outlandish, they may eventually inspire practical solutions to urban pollution.","vi":"Mặc dù một số đề xuất về môi trường thoạt đầu có vẻ ho đường, nhưng cuối cùng chúng có thể truyền cảm hứng cho các giải pháp thực tế đối với ô nhiễm đô thị.","audioKind":"ex2"}],"collocations":[{"en":"an outlandish idea","vi":"một ý tưởng kỳ quái"},{"en":"outlandish clothes","vi":"trang phục quái dị"},{"en":"an outlandish claim","vi":"một tuyên bố vô lý"}],"wordFamily":["outlandishly (adv.)","outlandishness (n.)"],"synonyms":["bizarre","eccentric","unconventional"],"antonyms":["ordinary","conventional"],"tipVi":"Nhấn mạnh sự khác thường, thường mang sắc thái ngạc nhiên hoặc không tán thành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expiration', 'en-c1-61', 'expiration', '/ˌekspəˈreɪʃən/', 'C1', 'sự hết hạn; sự mãn hạn', 'n.', 'expire (v.)', 'Đồng nghĩa: expiry', 'Khi chỉ sự hết hạn, tiếng Anh-Mỹ thường dùng expiration, trong khi tiếng Anh-Anh thường dùng expiry.', 'Check the expiration date before you buy the yoghurt.', NULL, 'Hãy kiểm tra hạn sử dụng trước khi bạn mua sữa chua.', '{"wordId":"expiration","ukIpa":"/ˌekspəˈreɪʃən/","usIpa":"/ˌekspəˈreɪʃən/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"the end of the period when something remains valid","vi":"sự hết hạn; sự mãn hạn"}],"examples":[{"en":"Check the expiration date before you buy the yoghurt.","vi":"Hãy kiểm tra hạn sử dụng trước khi bạn mua sữa chua.","audioKind":"ex"},{"en":"The expiration of temporary work permits can create uncertainty for both employees and local businesses.","vi":"Giấy phép lao động tạm thời hết hạn có thể gây ra sự bất ổn cho cả người lao động lẫn các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"expiration date","vi":"ngày hết hạn"},{"en":"expiration of a contract","vi":"hết hạn hợp đồng"},{"en":"before expiration","vi":"trước khi hết hạn"}],"wordFamily":["expire (v.)"],"synonyms":["expiry"],"antonyms":[],"tipVi":"Khi chỉ sự hết hạn, tiếng Anh-Mỹ thường dùng expiration, trong khi tiếng Anh-Anh thường dùng expiry.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_simultaneous', 'en-c1-61', 'simultaneous', '/ˌsaɪməlˈteɪniəs/', 'C1', 'đồng thời; xảy ra cùng một lúc', 'adj.', 'simultaneously (adv.)', 'Đồng nghĩa: concurrent · Trái nghĩa: sequential', 'Nhấn mạnh thời gian trùng khớp; phó từ simultaneously chỉ hành động đồng thời.', 'Simultaneous cheers erupted from both sides of the street.', NULL, 'Tiếng hò reo đồng loạt bùng lên từ cả hai phía của con đường.', '{"wordId":"simultaneous","ukIpa":"/ˌsɪməlˈteɪniəs/","usIpa":"/ˌsaɪməlˈteɪniəs/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"happening or existing at exactly the same time","vi":"đồng thời; xảy ra cùng một lúc"}],"examples":[{"en":"Simultaneous cheers erupted from both sides of the street.","vi":"Tiếng hò reo đồng loạt bùng lên từ cả hai phía của con đường.","audioKind":"ex"},{"en":"Simultaneous investment in public transport and cycling infrastructure can reduce congestion more effectively than isolated measures.","vi":"Việc đầu tư đồng thời vào giao thông công cộng và cơ sở hạ tầng cho xe đạp có thể giảm ùn tắc hiệu quả hơn so với các biện pháp đơn lẻ.","audioKind":"ex2"}],"collocations":[{"en":"simultaneous events","vi":"các sự kiện đồng thời"},{"en":"simultaneous interpretation","vi":"phiên dịch đồng thời"},{"en":"simultaneous access","vi":"truy cập đồng thời"}],"wordFamily":["simultaneously (adv.)"],"synonyms":["concurrent"],"antonyms":["sequential"],"tipVi":"Nhấn mạnh thời gian trùng khớp; phó từ simultaneously chỉ hành động đồng thời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_61_1', 'en-c1-61', 'Cách dùng “sluggish” (adj.) — chậm chạp; uể oải; lờ đờ', 'feel sluggish  ·  sluggish growth  ·  sluggish response', 'Vừa dùng để mô tả trạng thái thiếu năng lượng ở con người, vừa dùng để chỉ tốc độ phát triển chậm của nền kinh tế hoặc hệ thống.', 'Họ từ (Word Family): sluggishly (adv.), sluggishness (n.) | Đồng nghĩa: slow, lethargic · Trái nghĩa: energetic, brisk', '[{"hanzi":"I felt sluggish after eating such a large lunch.","pinyin":"","meaning":"Tôi cảm thấy uể oải sau khi ăn một bữa trưa quá thịnh soạn."},{"hanzi":"Sluggish economic growth can discourage investment and limit employment opportunities for recent university graduates.","pinyin":"","meaning":"Tăng trưởng kinh tế trì trệ có thể làm nản lòng các nhà đầu tư và hạn chế cơ hội việc làm cho sinh viên mới tốt nghiệp đại học."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_61_2', 'en-c1-61', 'Cách dùng “generic” (adj.) — chung chung; không cụ thể', 'generic term  ·  generic advice  ·  generic medicine', 'Generic nhấn mạnh tính không cụ thể; generic medicine thường chỉ thuốc generic (thuốc không có thương hiệu độc quyền).', 'Họ từ (Word Family): generically (adv.) | Đồng nghĩa: general, non-specific · Trái nghĩa: specific', '[{"hanzi":"The website sent me a generic reply about delivery.","pinyin":"","meaning":"Trang web đã gửi cho tôi một phản hồi chung chung về việc giao hàng."},{"hanzi":"Generic medicines can reduce healthcare costs while providing the same active ingredients as their branded equivalents.","pinyin":"","meaning":"Thuốc không có thương hiệu có thể làm giảm chi phí y tế trong khi vẫn cung cấp các hoạt chất giống hệt như các loại thuốc mang nhãn hiệu tương đương."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_61_3', 'en-c1-61', 'Cách dùng “culminate” (v.) — lên đến đỉnh điểm; kết thúc bằng', 'culminate in success  ·  culminate in an agreement  ·  culminate in a celebration', 'Thường dùng cấu trúc culminate in + kết quả, nhấn mạnh điểm kết thúc hoặc cao trào sau một quá trình phát triển.', 'Họ từ (Word Family): culmination (n.)', '[{"hanzi":"Weeks of rehearsals culminated in a wonderful evening performance.","pinyin":"","meaning":"Nhiều tuần tập luyện đã khép lại bằng một buổi biểu diễn tối tuyệt vời."},{"hanzi":"Years of public consultation culminated in a comprehensive transport plan designed to reduce congestion and improve accessibility.","pinyin":"","meaning":"Nhiều năm tham vấn công khai đã kết thúc bằng một kế hoạch giao thông toàn diện nhằm giảm ùn tắc và cải thiện khả năng tiếp cận."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_61_4', 'en-c1-61', 'Cách dùng “rosy” (adj.) — hồng hào; đỏ hồng', 'rosy cheeks  ·  a rosy future  ·  paint a rosy picture', 'Cụm paint a rosy picture có nghĩa là vẽ ra viễn cảnh màu hồng, đôi khi mang hàm ý tô hồng quá mức thực tế.', 'Họ từ (Word Family): rosiness (n.), rose (n.) | Đồng nghĩa: pink, optimistic · Trái nghĩa: pale, bleak', '[{"hanzi":"Her cheeks were rosy after walking in the cold.","pinyin":"","meaning":"Má cô ấy trở nên hồng hào sau khi đi dạo trong thời tiết lạnh."},{"hanzi":"Although official forecasts paint a rosy picture, rising energy costs could slow the country''s economic recovery.","pinyin":"","meaning":"Mặc dù các dự báo chính thức vẽ nên một bức tranh tươi sáng, chi phí năng lượng tăng cao có thể làm chậm quá trình phục hồi kinh tế của đất nước."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_61_1', 'en-c1-61', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_1_1', 'ten_c1_61_1', 'snag', 'My sweater snagged on a nail by the door.', 'My sweater snagged on a nail by the door.', '/snæɡ/', 'Chiếc áo len của tôi bị vướng vào một chiếc đinh ở cạnh cửa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_1_2', 'ten_c1_61_1', 'rosy', 'Her cheeks were rosy after walking in the cold.', 'Her cheeks were rosy after walking in the cold.', '/ˈroʊzi/', 'Má cô ấy trở nên hồng hào sau khi đi dạo trong thời tiết lạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_1_3', 'ten_c1_61_1', 'solitary', 'A solitary walker followed the quiet path through the woods.', 'A solitary walker followed the quiet path through the woods.', '/ˈsɑːləteri/', 'Một người đi bộ đơn độc bước đi dọc theo con đường yên tĩnh xuyên qua khu rừng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_1_4', 'ten_c1_61_1', 'ample', 'We have ample time for breakfast before the train leaves.', 'We have ample time for breakfast before the train leaves.', '/ˈæmpəl/', 'Chúng tôi có thừa thời gian để ăn sáng trước khi tàu chạy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_1_5', 'ten_c1_61_1', 'steamer', 'Put the dumplings in the steamer for ten minutes.', 'Put the dumplings in the steamer for ten minutes.', '/ˈstiːmər/', 'Cho bánh bao vào xửng hấp trong mười phút.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_1_6', 'ten_c1_61_1', 'funnel', 'Use a funnel to pour oil into the bottle.', 'Use a funnel to pour oil into the bottle.', '/ˈfʌnəl/', 'Dùng phễu để rót dầu vào chai.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_1_7', 'ten_c1_61_1', 'illuminate', 'Small lamps illuminate the garden path after sunset.', 'Small lamps illuminate the garden path after sunset.', '/ɪˈluːməneɪt/', 'Những chiếc đèn nhỏ chiếu sáng lối đi trong vườn sau khi mặt trời lặn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_1_8', 'ten_c1_61_1', 'pester', 'The children pestered their uncle for another bedtime story.', 'The children pestered their uncle for another bedtime story.', '/ˈpestɚ/', 'Lũ trẻ cứ nài nỉ chú kể thêm một câu chuyện trước khi đi ngủ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_61_1_1', 'en-c1-61', 'ten_c1_61_1', 'listening', 'listening', 'My sweater snagged on a nail by the door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lũ trẻ cứ nài nỉ chú kể thêm một câu chuyện trước khi đi ngủ.","Cô ấy mở nắp chai và rót nước trái cây cho mọi người.","Y tá dùng một chiếc gối để kê cao mắt cá chân của tôi.","Chiếc áo len của tôi bị vướng vào một chiếc đinh ở cạnh cửa."]'::jsonb, 3, 'My sweater snagged on a nail by the door. → Chiếc áo len của tôi bị vướng vào một chiếc đinh ở cạnh cửa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_61_1_2', 'en-c1-61', 'ten_c1_61_1', 'listening', 'listening', 'Her cheeks were rosy after walking in the cold.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi dành cả buổi chiều để đi dạo không mục đích.","Bất chấp vẻ bề ngoài tự tin, Leila cảm thấy căng thẳng ở bên trong.","Má cô ấy trở nên hồng hào sau khi đi dạo trong thời tiết lạnh.","Nhiều tuần tập luyện đã khép lại bằng một buổi biểu diễn tối tuyệt vời."]'::jsonb, 2, 'Her cheeks were rosy after walking in the cold. → Má cô ấy trở nên hồng hào sau khi đi dạo trong thời tiết lạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_61_1_3', 'en-c1-61', 'ten_c1_61_1', 'listening', 'listening', 'A solitary walker followed the quiet path through the woods.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một người đi bộ đơn độc bước đi dọc theo con đường yên tĩnh xuyên qua khu rừng.","Phản ứng nhanh nhẹn của cô ấy đã ngăn chiếc ly rơi xuống.","Tiếng hò reo đồng loạt bùng lên từ cả hai phía của con đường.","Chiếc áo len của tôi bị vướng vào một chiếc đinh ở cạnh cửa."]'::jsonb, 0, 'A solitary walker followed the quiet path through the woods. → Một người đi bộ đơn độc bước đi dọc theo con đường yên tĩnh xuyên qua khu rừng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_61_2', 'en-c1-61', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_2_1', 'ten_c1_61_2', 'snag', 'The housing project hit a snag when engineers discovered unstable ground beneath the proposed site.', 'The housing project hit a snag when engineers discovered unstable ground beneath the proposed site.', '/snæɡ/', 'Dự án nhà ở gặp trở ngại khi các kỹ sư phát hiện nền đất không ổn định bên dưới khu vực dự kiến xây dựng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_2_2', 'ten_c1_61_2', 'rosy', 'Although official forecasts paint a rosy picture, rising energy costs could slow the country''s economic recovery.', 'Although official forecasts paint a rosy picture, rising energy costs could slow the country''s economic recovery.', '/ˈroʊzi/', 'Mặc dù các dự báo chính thức vẽ nên một bức tranh tươi sáng, chi phí năng lượng tăng cao có thể làm chậm quá trình phục hồi kinh tế của đất nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_2_3', 'ten_c1_61_2', 'solitary', 'While solitary study allows deep concentration, collaborative learning helps students develop communication skills and consider alternative perspectives.', 'While solitary study allows deep concentration, collaborative learning helps students develop communication skills and consider alternative perspectives.', '/ˈsɑːləteri/', 'Trong khi việc học một mình giúp tập trung sâu, học tập hợp tác giúp học sinh phát triển kỹ năng giao tiếp và cân nhắc các góc nhìn khác nhau.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_2_4', 'ten_c1_61_2', 'ample', 'Providing ample green space in residential areas can improve public health and encourage more active lifestyles.', 'Providing ample green space in residential areas can improve public health and encourage more active lifestyles.', '/ˈæmpəl/', 'Việc cung cấp không gian xanh rộng rãi trong các khu dân cư có thể cải thiện sức khỏe công cộng và khuyến khích lối sống năng động hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_2_5', 'ten_c1_61_2', 'steamer', 'The arrival of the steamer transformed river trade by allowing goods to travel more reliably over long distances.', 'The arrival of the steamer transformed river trade by allowing goods to travel more reliably over long distances.', '/ˈstiːmər/', 'Sự ra đời của tàu thủy chạy bằng hơi nước đã làm thay đổi thương mại đường sông bằng cách cho phép hàng hóa di chuyển đáng tin cậy hơn trên các chặng đường dài.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_61_2_6', 'ten_c1_61_2', 'funnel', 'Well-designed drainage systems funnel rainwater into storage tanks, reducing the risk of urban flooding.', 'Well-designed drainage systems funnel rainwater into storage tanks, reducing the risk of urban flooding.', '/ˈfʌnəl/', 'Hệ thống thoát nước được thiết kế tốt giúp dẫn nước mưa vào các bể chứa, làm giảm nguy cơ ngập lụt đô thị.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_61_2_1', 'en-c1-61', 'ten_c1_61_2', 'listening', 'listening', 'The housing project hit a snag when engineers discovered unstable ground beneath the proposed site.', NULL, 'Trong câu vừa nghe, từ “snag” mang nghĩa nào sau đây?', '["trở ngại bất ngờ; khó khăn nhỏ","bản song ca; khúc hát/khúc nhạc đôi cho hai người biểu diễn","hạn chế; giới hạn (trong một phạm vi nhất định)","nằm hoặc ngồi duỗi dài chân tay"]'::jsonb, 0, '“snag” (/snæɡ/): trở ngại bất ngờ; khó khăn nhỏ. Câu đầy đủ: The housing project hit a snag when engineers discovered unstable ground beneath the proposed site.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_61_2_2', 'en-c1-61', 'ten_c1_61_2', 'listening', 'listening', 'Although official forecasts paint a rosy picture, rising energy costs could slow the country''s economic recovery.', NULL, 'Trong câu vừa nghe, từ “rosy” mang nghĩa nào sau đây?', '["sự xuyên qua; sự thâm nhập","sự mạch lạc; tính liên kết; tính logic","hồng hào; đỏ hồng","sự sụp đổ; sự suy sụp (về quyền lực, thành công hoặc địa vị xã hội)"]'::jsonb, 2, '“rosy” (/ˈroʊzi/): hồng hào; đỏ hồng. Câu đầy đủ: Although official forecasts paint a rosy picture, rising energy costs could slow the country''s economic recovery.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
