INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_2', 'en-c1-61', NULL, 'comprehensive_test', 'listening', 'Her cheeks were rosy after walking in the cold.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiếng hò reo đồng loạt bùng lên từ cả hai phía của con đường.","Má cô ấy trở nên hồng hào sau khi đi dạo trong thời tiết lạnh.","Bất chấp vẻ bề ngoài tự tin, Leila cảm thấy căng thẳng ở bên trong.","Cho bánh bao vào xửng hấp trong mười phút."]'::jsonb, 1, 'Her cheeks were rosy after walking in the cold. → Má cô ấy trở nên hồng hào sau khi đi dạo trong thời tiết lạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_3', 'en-c1-61', NULL, 'comprehensive_test', 'listening', 'solitary', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cô độc; đơn độc; thích sống một mình","chế độ bạo ngược; nền chuyên chế","liên tiếp; nối tiếp nhau không ngừng","mang tính châm biếm; nói mỉa mai"]'::jsonb, 0, 'solitary (/ˈsɑːləteri/) → cô độc; đơn độc; thích sống một mình; duy nhất; đơn lẻ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_4', 'en-c1-61', NULL, 'comprehensive_test', 'listening', 'We have ample time for breakfast before the train leaves.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Với một động tác nhanh gọn, cô ấy đã đỡ được chiếc cốc đang rơi.","Một người đi bộ đơn độc bước đi dọc theo con đường yên tĩnh xuyên qua khu rừng.","Nhiều tuần tập luyện đã khép lại bằng một buổi biểu diễn tối tuyệt vời.","Chúng tôi có thừa thời gian để ăn sáng trước khi tàu chạy."]'::jsonb, 3, 'We have ample time for breakfast before the train leaves. → Chúng tôi có thừa thời gian để ăn sáng trước khi tàu chạy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_5', 'en-c1-61', NULL, 'comprehensive_test', 'listening', 'steamer', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["biết ơn; mang ơn","thuộc về tư pháp; thuộc tòa án hoặc việc thực thi công lý","sẵn sàng và có thể hoạt động hoặc sử dụng được","nồi hấp; xửng hấp"]'::jsonb, 3, 'steamer (/ˈstiːmər/) → nồi hấp; xửng hấp; tàu thủy chạy bằng hơi nước', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_6', 'en-c1-61', NULL, 'comprehensive_test', 'listening', 'Use a funnel to pour oil into the bottle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một người đi bộ đơn độc bước đi dọc theo con đường yên tĩnh xuyên qua khu rừng.","Tiếng hò reo đồng loạt bùng lên từ cả hai phía của con đường.","Phản ứng nhanh nhẹn của cô ấy đã ngăn chiếc ly rơi xuống.","Dùng phễu để rót dầu vào chai."]'::jsonb, 3, 'Use a funnel to pour oil into the bottle. → Dùng phễu để rót dầu vào chai.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_7', 'en-c1-61', NULL, 'comprehensive_test', 'listening', 'illuminate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cửa sông; cửa sông đổ ra biển","giếng (thang máy, thông gió); đường hầm thẳng đứng","bản sao; bản phụ","chiếu sáng; rọi sáng"]'::jsonb, 3, 'illuminate (/ɪˈluːməneɪt/) → chiếu sáng; rọi sáng; làm sáng tỏ; giải thích', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_8', 'en-c1-61', NULL, 'comprehensive_test', 'listening', 'The children pestered their uncle for another bedtime story.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lũ trẻ cứ nài nỉ chú kể thêm một câu chuyện trước khi đi ngủ.","Chúng tôi có thừa thời gian để ăn sáng trước khi tàu chạy.","Những chiếc đèn nhỏ chiếu sáng lối đi trong vườn sau khi mặt trời lặn.","Một người đi bộ đơn độc bước đi dọc theo con đường yên tĩnh xuyên qua khu rừng."]'::jsonb, 0, 'The children pestered their uncle for another bedtime story. → Lũ trẻ cứ nài nỉ chú kể thêm một câu chuyện trước khi đi ngủ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
