INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_18', 'en-c1-61', NULL, 'comprehensive_test', 'reading', NULL, 'The housing project hit a snag when engineers discovered unstable ground beneath the proposed site.', 'Dựa vào câu trên, từ “snag” có nghĩa phù hợp nhất là gì?', '["thuộc về thủy lực; chạy bằng sức nước","điều trớ trêu; nghịch lý","lao đi; phóng vụt qua","trở ngại bất ngờ; khó khăn nhỏ"]'::jsonb, 3, 'snag: trở ngại bất ngờ; khó khăn nhỏ; làm rách; vướng phải vật sắc nhọn. Dịch cả câu: Dự án nhà ở gặp trở ngại khi các kỹ sư phát hiện nền đất không ổn định bên dưới khu vực dự kiến xây dựng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_19', 'en-c1-61', NULL, 'comprehensive_test', 'reading', NULL, 'Although official forecasts paint a rosy picture, rising energy costs could slow the country''s economic recovery.', 'Dựa vào câu trên, từ “rosy” có nghĩa phù hợp nhất là gì?', '["cây đước; cây mắm; rừng ngập mặn","hồng hào; đỏ hồng","liệt kê; kể ra; nêu rõ từng mục","đánh giá; định giá chất lượng, tình trạng hoặc hiệu suất"]'::jsonb, 1, 'rosy: hồng hào; đỏ hồng; lạc quan; tươi sáng. Dịch cả câu: Mặc dù các dự báo chính thức vẽ nên một bức tranh tươi sáng, chi phí năng lượng tăng cao có thể làm chậm quá trình phục hồi kinh tế của đất nước.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_20', 'en-c1-61', NULL, 'comprehensive_test', 'reading', NULL, 'While solitary study allows deep concentration, collaborative learning helps students develop communication skills and consider alternative perspectives.', 'Dựa vào câu trên, từ “solitary” có nghĩa phù hợp nhất là gì?', '["khả năng cạnh tranh","cô độc; đơn độc; thích sống một mình","ảo ảnh; hiện tượng ảo ảnh quang học","phát ra tiếng kêu rít; khì khì"]'::jsonb, 1, 'solitary: cô độc; đơn độc; thích sống một mình; duy nhất; đơn lẻ. Dịch cả câu: Trong khi việc học một mình giúp tập trung sâu, học tập hợp tác giúp học sinh phát triển kỹ năng giao tiếp và cân nhắc các góc nhìn khác nhau.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_21', 'en-c1-61', NULL, 'comprehensive_test', 'reading', NULL, 'Providing ample green space in residential areas can improve public health and encourage more active lifestyles.', 'Dựa vào câu trên, từ “ample” có nghĩa phù hợp nhất là gì?', '["đầy đủ; dồi dào; thừa thãi","vựa lúa; kho chứa ngũ cốc; nhà kho lúa","hiểu; giải thích; suy diễn","đồng tình; tán thành; có cùng ý kiến"]'::jsonb, 0, 'ample: đầy đủ; dồi dào; thừa thãi; rộng rãi; thênh thang. Dịch cả câu: Việc cung cấp không gian xanh rộng rãi trong các khu dân cư có thể cải thiện sức khỏe công cộng và khuyến khích lối sống năng động hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_22', 'en-c1-61', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kỳ lạ; quái dị; ho đường”', '["outlandish","enchant","trench","violate"]'::jsonb, 0, 'kỳ lạ; quái dị; ho đường → outlandish (/aʊtˈlændɪʃ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
