INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_61_24', 'en-c1-61', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đồng thời; xảy ra cùng một lúc”', '["mingle","quota","simultaneous","commence"]'::jsonb, 2, 'đồng thời; xảy ra cùng một lúc → simultaneous (/ˌsaɪməlˈteɪniəs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-62', 'en', 'Bài 62: Đời sống hằng ngày (3) - CEFR C1', 'CEFR C1', 'C1 · Đời sống', '27 từ vựng Tiếng Anh CEFR C1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5062, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elapse', 'en-c1-62', 'elapse', '/ɪˈlæps/', 'C1', 'trôi qua (dùng cho thời gian)', 'v.', NULL, 'Đồng nghĩa: pass', 'Là động từ nội động từ lấy thời gian làm chủ ngữ, không đi kèm tân ngữ trực tiếp phía sau.', 'Several minutes elapsed before the bus finally arrived.', NULL, 'Vài phút trôi qua trước khi chiếc xe buýt cuối cùng cũng đến.', '{"wordId":"elapse","ukIpa":"/ɪˈlæps/","usIpa":"/ɪˈlæps/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"for a period of time to pass","vi":"trôi qua (dùng cho thời gian)"}],"examples":[{"en":"Several minutes elapsed before the bus finally arrived.","vi":"Vài phút trôi qua trước khi chiếc xe buýt cuối cùng cũng đến.","audioKind":"ex"},{"en":"Several years may elapse before environmental policies produce measurable improvements in urban air quality.","vi":"Có thể mất vài năm trôi qua trước khi các chính sách môi trường mang lại những cải thiện có thể đo lường được về chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"time elapses","vi":"thời gian trôi qua"},{"en":"years elapse","vi":"nhiều năm trôi qua"},{"en":"elapsed time","vi":"thời gian đã trôi qua"}],"wordFamily":[],"synonyms":["pass"],"antonyms":[],"tipVi":"Là động từ nội động từ lấy thời gian làm chủ ngữ, không đi kèm tân ngữ trực tiếp phía sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tack', 'en-c1-62', 'tack', '/tæk/', 'C1', 'đinh ghim ngắn đầu to và dẹt; cố định cái gì bằng đinh ngắn; một phương pháp hoặc cách tiếp cận cụ thể để giải quyết một tình huống', 'n.', NULL, 'Đồng nghĩa: nail, approach', 'Phương pháp dùng tack; đi đúng hướng dùng on track, tránh nhầm lẫn.', 'I used a tack to secure the loose fabric.', NULL, 'Tôi dùng một chiếc đinh ghim ngắn để cố định mảnh vải bị lỏng.', '{"wordId":"tack","ukIpa":"/tæk/","usIpa":"/tæk/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A short nail with a broad, flat head.","vi":"đinh ghim ngắn đầu to và dẹt"},{"pos":"v.","en":"To fasten something using small nails.","vi":"cố định cái gì bằng đinh ngắn"},{"pos":"n.","en":"A particular approach to dealing with a situation.","vi":"một phương pháp hoặc cách tiếp cận cụ thể để giải quyết một tình huống"}],"examples":[{"en":"I used a tack to secure the loose fabric.","vi":"Tôi dùng một chiếc đinh ghim ngắn để cố định mảnh vải bị lỏng.","audioKind":"ex"},{"en":"When public campaigns fail to change behaviour, policymakers may need to take a different tack.","vi":"Khi các chiến dịch công cộng không thay đổi được hành vi, các nhà hoạch định chính sách có thể cần áp dụng một phương pháp khác.","audioKind":"ex2"}],"collocations":[{"en":"hammer in a tack","vi":"đóng đinh ghim ngắn"},{"en":"tack something down","vi":"ghim chặt vật gì xuống"},{"en":"take a different tack","vi":"áp dụng phương pháp khác"},{"en":"change tack","vi":"đổi chiến lược"}],"wordFamily":[],"synonyms":["nail","approach"],"antonyms":[],"tipVi":"Phương pháp dùng tack; đi đúng hướng dùng on track, tránh nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relentless', 'en-c1-62', 'relentless', '/rɪˈlentləs/', 'C1', 'không ngừng nghỉ; liên tục không giảm; nhẫn tâm; không khoan nhượng', 'adj.', 'relent (v.), relentlessly (adv.), relentlessness (n.)', 'Đồng nghĩa: unrelenting, unceasing · Trái nghĩa: intermittent', 'Không chỉ giới hạn ở nghĩa "vô tình", từ này còn hay dùng để mô tả mưa, áp lực,... kéo dài không giảm.', 'The relentless rain kept us indoors all weekend.', NULL, 'Cơn mưa dầm dề không ngớt đã giữ chân chúng tôi ở trong nhà suốt cả cuối tuần.', '{"wordId":"relentless","ukIpa":"/rɪˈlentləs/","usIpa":"/rɪˈlentləs/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"continuing strongly without stopping or becoming less intense","vi":"không ngừng nghỉ; liên tục không giảm"},{"pos":"adj.","en":"showing no sympathy or willingness to become less harsh","vi":"nhẫn tâm; không khoan nhượng"}],"examples":[{"en":"The relentless rain kept us indoors all weekend.","vi":"Cơn mưa dầm dề không ngớt đã giữ chân chúng tôi ở trong nhà suốt cả cuối tuần.","audioKind":"ex"},{"en":"Relentless pressure to achieve high grades can undermine students'' confidence and damage their mental health.","vi":"Áp lực không ngừng nghỉ để đạt được điểm số cao có thể làm suy yếu sự tự tin của học sinh và tổn hại đến sức khỏe tinh thần của các em.","audioKind":"ex2"}],"collocations":[{"en":"relentless pressure","vi":"áp lực liên tục"},{"en":"relentless pursuit","vi":"sự theo đuổi không ngừng"},{"en":"relentless criticism","vi":"sự chỉ trích không khoan nhượng"}],"wordFamily":["relent (v.)","relentlessly (adv.)","relentlessness (n.)"],"synonyms":["unrelenting","unceasing"],"antonyms":["intermittent"],"tipVi":"Không chỉ giới hạn ở nghĩa \"vô tình\", từ này còn hay dùng để mô tả mưa, áp lực,... kéo dài không giảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sway', 'en-c1-62', 'sway', '/sweɪ/', 'C1', 'lắc lư; đu đưa; ảnh hưởng; chi phối; sự chi phối', 'v.', NULL, NULL, 'sway vừa có thể chỉ chuyển động lắc lư của cơ thể, vừa có thể chỉ việc tác động đến quan điểm hoặc quyết định.', 'The branches swayed gently as we ate outside.', NULL, 'Những cành cây nhẹ nhàng đu đưa khi chúng tôi ăn uống ngoài trời.', '{"wordId":"sway","ukIpa":"/sweɪ/","usIpa":"/sweɪ/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To move slowly from side to side, or cause this movement.","vi":"lắc lư; đu đưa"},{"pos":"v.","en":"To influence someone''s opinion, choice, or decision.","vi":"ảnh hưởng; chi phối"},{"pos":"n.","en":"Power or influence over people or decisions.","vi":"sự chi phối; ảnh hưởng"}],"examples":[{"en":"The branches swayed gently as we ate outside.","vi":"Những cành cây nhẹ nhàng đu đưa khi chúng tôi ăn uống ngoài trời.","audioKind":"ex"},{"en":"Emotional advertising can sway consumers'' decisions even when competing products offer better value for money.","vi":"Quảng cáo mang tính cảm xúc có thể chi phối quyết định của người tiêu dùng ngay cả khi các sản phẩm cạnh tranh mang lại giá trị kinh tế tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"sway gently","vi":"đu đưa nhẹ nhàng"},{"en":"sway public opinion","vi":"chi phối dư luận"},{"en":"hold sway","vi":"chi phối; chiếm ưu thế"},{"en":"under the sway of","vi":"chịu sự chi phối của"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"sway vừa có thể chỉ chuyển động lắc lư của cơ thể, vừa có thể chỉ việc tác động đến quan điểm hoặc quyết định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_habitual', 'en-c1-62', 'habitual', '/həˈbɪtʃuəl/', 'C1', 'thường xuyên; theo thói quen', 'adj.', 'habit (n.), habitually (adv.)', 'Đồng nghĩa: customary, usual, routine · Trái nghĩa: occasional', 'Dùng để mô tả hành vi lặp đi lặp lại, hoặc bổ nghĩa cho người hay làm một việc gì đó.', 'His habitual lateness meant we often missed the bus.', NULL, 'Việc đi học muộn thành thói quen khiến chúng tôi thường xuyên lỡ chuyến xe buýt.', '{"wordId":"habitual","ukIpa":"/həˈbɪtʃuəl/","usIpa":"/həˈbɪtʃuəl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"done regularly or repeatedly as a habit","vi":"thường xuyên; theo thói quen"}],"examples":[{"en":"His habitual lateness meant we often missed the bus.","vi":"Việc đi học muộn thành thói quen khiến chúng tôi thường xuyên lỡ chuyến xe buýt.","audioKind":"ex"},{"en":"Habitual use of private cars can increase urban congestion and discourage investment in public transport.","vi":"Việc thường xuyên sử dụng xe hơi cá nhân có thể làm tăng tình trạng tắc nghẽn đô thị và làm giảm động lực đầu tư vào giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"habitual behaviour","vi":"hành vi theo thói quen"},{"en":"habitual lateness","vi":"tật hay đi muộn"},{"en":"a habitual user","vi":"người thường xuyên sử dụng"}],"wordFamily":["habit (n.)","habitually (adv.)"],"synonyms":["customary","usual","routine"],"antonyms":["occasional"],"tipVi":"Dùng để mô tả hành vi lặp đi lặp lại, hoặc bổ nghĩa cho người hay làm một việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dual', 'en-c1-62', 'dual', '/ˈduːəl/', 'C1', 'hai mặt; kép; song song', 'adj.', 'duality (n.)', 'Đồng nghĩa: twofold · Trái nghĩa: single', 'dual nhấn mạnh hai phần hoặc chức năng kép; đừng nhầm lẫn với duel (quyết đấu).', 'This sofa has a dual purpose: sitting and sleeping.', NULL, 'Chiếc ghế sofa này có hai công dụng: dùng để ngồi và để ngủ.', '{"wordId":"dual","ukIpa":"/ˈdjuːəl/","usIpa":"/ˈduːəl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Having two parts, purposes, or aspects.","vi":"hai mặt; kép; song song"}],"examples":[{"en":"This sofa has a dual purpose: sitting and sleeping.","vi":"Chiếc ghế sofa này có hai công dụng: dùng để ngồi và để ngủ.","audioKind":"ex"},{"en":"Many working parents face the dual challenge of earning an income and caring for young children.","vi":"Nhiều bậc cha mẹ đi làm phải đối mặt với thử thách kép là vừa kiếm thu nhập vừa chăm sóc con nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"dual purpose","vi":"mục đích kép"},{"en":"dual role","vi":"vai trò kép"},{"en":"dual citizenship","vi":"hai quốc tịch"},{"en":"dual function","vi":"chức năng kép"}],"wordFamily":["duality (n.)"],"synonyms":["twofold"],"antonyms":["single"],"tipVi":"dual nhấn mạnh hai phần hoặc chức năng kép; đừng nhầm lẫn với duel (quyết đấu).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commotion', 'en-c1-62', 'commotion', '/kəˈmoʊʃən/', 'C1', 'sự náo động; cảnh ồn ào hỗn loạn', 'n.', NULL, 'Đồng nghĩa: disturbance, uproar · Trái nghĩa: calm', 'Thường chỉ sự ồn ào hoặc náo loạn trong chốc lát, không nhất thiết liên quan đến bạo lực hay bạo loạn.', 'A loose puppy caused a commotion in the café.', NULL, 'Một chú chó con xổng chuồng đã gây ra một phen náo động trong quán cà phê.', '{"wordId":"commotion","ukIpa":"/kəˈməʊʃən/","usIpa":"/kəˈmoʊʃən/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"Noisy activity and confusion caused by excitement or disturbance","vi":"sự náo động; cảnh ồn ào hỗn loạn"}],"examples":[{"en":"A loose puppy caused a commotion in the café.","vi":"Một chú chó con xổng chuồng đã gây ra một phen náo động trong quán cà phê.","audioKind":"ex"},{"en":"The sudden commotion at the station highlighted the need for clearer procedures during unexpected service disruptions.","vi":"Sự náo động bất ngờ tại nhà ga nhấn mạnh sự cần thiết phải có các quy trình rõ ràng hơn trong các tình huống gián đoạn dịch vụ bất ngờ.","audioKind":"ex2"}],"collocations":[{"en":"cause a commotion","vi":"gây ra sự náo động"},{"en":"a sudden commotion","vi":"sự ồn ào bất ngờ"},{"en":"in the commotion","vi":"trong khung cảnh hỗn loạn"}],"wordFamily":[],"synonyms":["disturbance","uproar"],"antonyms":["calm"],"tipVi":"Thường chỉ sự ồn ào hoặc náo loạn trong chốc lát, không nhất thiết liên quan đến bạo lực hay bạo loạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whirl', 'en-c1-62', 'whirl', '/wɝːl/', 'C1', 'quay vòng; xoay tít; sự quay; guồng quay bận rộn', 'v.', 'whirling (adj.)', 'Đồng nghĩa: spin, swirl', 'Cụm từ give it a whirl thuộc phong cách khẩu ngữ, mang nghĩa là "thử một phen".', 'Dry leaves whirled around us in the wind.', NULL, 'Lá khô bay vòng quanh chúng tôi trong gió.', '{"wordId":"whirl","ukIpa":"/wɜːl/","usIpa":"/wɝːl/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To spin or move around very quickly.","vi":"quay vòng; xoay tít"},{"pos":"n.","en":"A spinning movement or a confusing rush of activity.","vi":"sự quay; guồng quay bận rộn"}],"examples":[{"en":"Dry leaves whirled around us in the wind.","vi":"Lá khô bay vòng quanh chúng tôi trong gió.","audioKind":"ex"},{"en":"As urban life accelerates, many workers become caught in a whirl of meetings and deadlines.","vi":"Khi nhịp sống đô thị tăng tốc, nhiều người lao động bị cuốn vào guồng quay bận rộn của các cuộc họp và hạn chót công việc.","audioKind":"ex2"}],"collocations":[{"en":"whirl around","vi":"quay cuồng xung quanh"},{"en":"a whirl of activity","vi":"guồng quay hoạt động bận rộn"},{"en":"give it a whirl","vi":"thử một phen"}],"wordFamily":["whirling (adj.)"],"synonyms":["spin","swirl"],"antonyms":[],"tipVi":"Cụm từ give it a whirl thuộc phong cách khẩu ngữ, mang nghĩa là \"thử một phen\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_footing', 'en-c1-62', 'footing', '/ˈfʊtɪŋ/', 'C1', 'chỗ đặt chân vững chắc; thế đứng; cơ sở; địa vị; nền tảng', 'n.', 'foot (n.)', NULL, 'Cụm từ on an equal footing diễn tả trạng thái có địa vị hoặc điều kiện bình đẳng.', 'I lost my footing on the wet steps.', NULL, 'Tôi đã bị trượt chân trên bậc thang ướt.', '{"wordId":"footing","ukIpa":"/ˈfʊtɪŋ/","usIpa":"/ˈfʊtɪŋ/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A secure position for your feet on a surface.","vi":"chỗ đặt chân vững chắc; thế đứng"},{"pos":"n.","en":"The basis or status on which something operates.","vi":"cơ sở; địa vị; nền tảng"}],"examples":[{"en":"I lost my footing on the wet steps.","vi":"Tôi đã bị trượt chân trên bậc thang ướt.","audioKind":"ex"},{"en":"Public funding can help place rural schools on an equal footing with their urban counterparts.","vi":"Nguồn vốn công có thể giúp đưa các trường học nông thôn lên vị thế bình đẳng so với các trường học ở thành phố.","audioKind":"ex2"}],"collocations":[{"en":"lose your footing","vi":"mất thăng bằng"},{"en":"regain your footing","vi":"lấy lại thế đứng"},{"en":"on an equal footing","vi":"ở vị thế bình đẳng"},{"en":"on a sound footing","vi":"trên nền tảng vững chắc"}],"wordFamily":["foot (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ on an equal footing diễn tả trạng thái có địa vị hoặc điều kiện bình đẳng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lavish', 'en-c1-62', 'lavish', '/ˈlævɪʃ/', 'C1', 'xa hoa, hào phóng; thịnh soạn, đắt đỏ; tươi tặng hào phóng; đổ dồn, dành cho rất nhiều', 'adj.', 'lavishly (adv.), lavishness (n.)', 'Đồng nghĩa: extravagant, sumptuous · Trái nghĩa: restrained', 'Động từ thường dùng lavish sth on sb, diễn tả việc cho đi hoặc dành tặng rất nhiều.', 'They prepared a lavish feast for the whole family.', NULL, 'Họ đã chuẩn bị một bữa tiệc thịnh soạn cho cả gia đình.', '{"wordId":"lavish","ukIpa":"/ˈlævɪʃ/","usIpa":"/ˈlævɪʃ/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Very generous, elaborate, or expensive","vi":"xa hoa, hào phóng; thịnh soạn, đắt đỏ"},{"pos":"v.","en":"To give something generously or in large quantities","vi":"tươi tặng hào phóng; đổ dồn, dành cho rất nhiều"}],"examples":[{"en":"They prepared a lavish feast for the whole family.","vi":"Họ đã chuẩn bị một bữa tiệc thịnh soạn cho cả gia đình.","audioKind":"ex"},{"en":"Critics argue that lavish spending on official ceremonies diverts public funds from essential services such as healthcare.","vi":"Các nhà phê bình cho rằng việc chi tiêu xa hoa cho các buổi lễ chính thức làm chuyển hướng quỹ công khỏi các dịch vụ thiết yếu như y tế.","audioKind":"ex2"}],"collocations":[{"en":"a lavish lifestyle","vi":"lối sống xa hoa"},{"en":"a lavish banquet","vi":"bữa yến tiệc thịnh soạn"},{"en":"lavish praise on someone","vi":"ca ngợi ai đó hết lời"},{"en":"lavish attention on someone","vi":"dành sự quan tâm lớn cho ai đó"}],"wordFamily":["lavishly (adv.)","lavishness (n.)"],"synonyms":["extravagant","sumptuous"],"antonyms":["restrained"],"tipVi":"Động từ thường dùng lavish sth on sb, diễn tả việc cho đi hoặc dành tặng rất nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_awaken', 'en-c1-62', 'awaken', '/əˈweɪkən/', 'C1', 'thức giấc; đánh thức; làm nảy sinh, đánh thức, khơi gợi (cảm xúc, sự quan tâm)', 'v.', 'awake (adj.), awakening (n.)', 'Đồng nghĩa: wake, rouse', 'Awaken là động từ; để chỉ trạng thái "thức", dùng awake.', 'Birdsong awakened me just as sunlight reached the curtains.', NULL, 'Tiếng chim hót đánh thức tôi ngay khi ánh nắng rọi đến rèm cửa.', '{"wordId":"awaken","ukIpa":"/əˈweɪkən/","usIpa":"/əˈweɪkən/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To stop sleeping, or cause someone to stop sleeping.","vi":"thức giấc; đánh thức"},{"pos":"v.","en":"To cause a feeling, interest, or awareness to develop.","vi":"làm nảy sinh, đánh thức, khơi gợi (cảm xúc, sự quan tâm)"}],"examples":[{"en":"Birdsong awakened me just as sunlight reached the curtains.","vi":"Tiếng chim hót đánh thức tôi ngay khi ánh nắng rọi đến rèm cửa.","audioKind":"ex"},{"en":"Visits to science museums can awaken children''s curiosity and encourage them to explore unfamiliar subjects.","vi":"Những chuyến tham quan bảo tàng khoa học có thể khơi gợi trí tò mò của trẻ em và khuyến khích các em khám phá những môn học mới lạ.","audioKind":"ex2"}],"collocations":[{"en":"awaken from sleep","vi":"thức dậy từ giấc ngủ"},{"en":"awaken curiosity","vi":"khơi gợi trí tò mò"},{"en":"awaken to the dangers","vi":"nhận thức được các mối nguy hiểm"}],"wordFamily":["awake (adj.)","awakening (n.)"],"synonyms":["wake","rouse"],"antonyms":[],"tipVi":"Awaken là động từ; để chỉ trạng thái \"thức\", dùng awake.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abrupt', 'en-c1-62', 'abrupt', '/əˈbrʌpt/', 'C1', 'đột ngột; bất ngờ; cộc lốc; thô lỗ; cộc cằn', 'adj.', 'abruptly (adv.), abruptness (n.)', 'Đồng nghĩa: sudden, unexpected · Trái nghĩa: gradual', 'Khi mô tả sự thay đổi có nghĩa là "đột ngột"; khi mô tả giọng điệu hoặc thái độ có nghĩa là "cộc lốc".', 'The bus came to an abrupt stop outside our house.', NULL, 'Xe buýt dừng lại một cách đột ngột ngay bên ngoài nhà chúng tôi.', '{"wordId":"abrupt","ukIpa":"/əˈbrʌpt/","usIpa":"/əˈbrʌpt/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Happening suddenly, often without warning.","vi":"đột ngột; bất ngờ"},{"pos":"adj.","en":"Speaking or behaving briefly in a way that seems rude.","vi":"cộc lốc; thô lỗ; cộc cằn"}],"examples":[{"en":"The bus came to an abrupt stop outside our house.","vi":"Xe buýt dừng lại một cách đột ngột ngay bên ngoài nhà chúng tôi.","audioKind":"ex"},{"en":"Abrupt changes in government policy can create uncertainty for businesses and discourage long-term investment.","vi":"Những thay đổi đột ngột trong chính sách của chính phủ có thể tạo ra sự bất ổn cho các doanh nghiệp và làm nản lòng các nhà đầu tư dài hạn.","audioKind":"ex2"}],"collocations":[{"en":"an abrupt change","vi":"một sự thay đổi đột ngột"},{"en":"an abrupt end","vi":"một kết thúc đột ngột"},{"en":"an abrupt manner","vi":"thái độ cộc lốc"}],"wordFamily":["abruptly (adv.)","abruptness (n.)"],"synonyms":["sudden","unexpected"],"antonyms":["gradual"],"tipVi":"Khi mô tả sự thay đổi có nghĩa là \"đột ngột\"; khi mô tả giọng điệu hoặc thái độ có nghĩa là \"cộc lốc\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grit', 'en-c1-62', 'grit', '/ɡrɪt/', 'C1', 'sỏi mịn; cát sạn; sự kiên trì; nghị lực; bản lĩnh; rắc sỏi (lên đường)', 'n.', 'gritty (adj.), grittiness (n.)', 'Đồng nghĩa: determination, resolve', 'Cả nghĩa sỏi mịn và nghị lực đều là danh từ không đếm được; grit không mang nghĩa là sự mài mòn theo cách thông thường.', 'I shook the grit out of my walking boots.', NULL, 'Tôi giũ sạch những hạt cát sỏi ở trong đôi giày đi bộ đường dài của mình.', '{"wordId":"grit","ukIpa":"/ɡrɪt/","usIpa":"/ɡrɪt/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"very small pieces of stone or sand","vi":"sỏi mịn; cát sạn"},{"pos":"n.","en":"determination to keep trying despite difficulties","vi":"sự kiên trì; nghị lực; bản lĩnh"},{"pos":"v.","en":"to spread grit on roads to make them less slippery","vi":"rắc sỏi (lên đường)"}],"examples":[{"en":"I shook the grit out of my walking boots.","vi":"Tôi giũ sạch những hạt cát sỏi ở trong đôi giày đi bộ đường dài của mình.","audioKind":"ex"},{"en":"Although talent matters, students often need grit and consistent support to overcome persistent learning difficulties.","vi":"Mặc dù tài liệu năng khiếu rất quan trọng, nhưng học sinh thường cần có nghị lực và sự hỗ trợ bền bỉ để vượt qua các khó khăn học tập lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"grit your teeth","vi":"cắn răng chịu đựng"},{"en":"grit the roads","vi":"rắc sỏi đường đi"},{"en":"show grit","vi":"thể hiện bản lĩnh"},{"en":"grit and determination","vi":"nghị lực và quyết tâm"}],"wordFamily":["gritty (adj.)","grittiness (n.)"],"synonyms":["determination","resolve"],"antonyms":[],"tipVi":"Cả nghĩa sỏi mịn và nghị lực đều là danh từ không đếm được; grit không mang nghĩa là sự mài mòn theo cách thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_offhand', 'en-c1-62', 'offhand', '/ˌɔːfˈhænd/', 'C1', 'ngay lập tức; không cần suy nghĩ; không tra cứu; hời hợt; qua loa; thiếu quan tâm', 'adv.', 'offhandedly (adv.), offhanded (adj.)', 'Đồng nghĩa: casual, curt', 'Phó từ thường đi kèm câu phủ định, thể hiện việc không thể trả lời ngay nếu không tra cứu trước.', 'I can''t remember the address offhand, but I''ll check.', NULL, 'Tôi không nhớ ngay địa chỉ lúc này đâu, nhưng tôi sẽ kiểm tra lại.', '{"wordId":"offhand","ukIpa":"/ˌɒfˈhænd/","usIpa":"/ˌɔːfˈhænd/","cefr":"C1","topic":"daily","senses":[{"pos":"adv.","en":"Without checking information or preparing an answer first.","vi":"ngay lập tức; không cần suy nghĩ; không tra cứu"},{"pos":"adj.","en":"Showing little care or interest, sometimes seeming rude.","vi":"hời hợt; qua loa; thiếu quan tâm"}],"examples":[{"en":"I can''t remember the address offhand, but I''ll check.","vi":"Tôi không nhớ ngay địa chỉ lúc này đâu, nhưng tôi sẽ kiểm tra lại.","audioKind":"ex"},{"en":"An offhand response to a patient''s concerns may undermine trust, even when the medical advice is accurate.","vi":"Một thái độ hời hợt trước những lo lắng của bệnh nhân có thể làm suy giảm lòng tin, ngay cả khi lời khuyên y tế là hoàn toàn chính xác.","audioKind":"ex2"}],"collocations":[{"en":"know offhand","vi":"nhớ ngay không cần tra"},{"en":"remember offhand","vi":"nhớ ra ngay lập tức"},{"en":"an offhand remark","vi":"một lời nhận xét bâng quơ"},{"en":"an offhand manner","vi":"một thái độ dửng dưng"}],"wordFamily":["offhandedly (adv.)","offhanded (adj.)"],"synonyms":["casual","curt"],"antonyms":[],"tipVi":"Phó từ thường đi kèm câu phủ định, thể hiện việc không thể trả lời ngay nếu không tra cứu trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_potluck', 'en-c1-62', 'potluck', '/ˌpɑːtˈlʌk/', 'C1', 'bữa ăn chung mỗi người góp một món; bữa ăn đạm bạc có gì ăn nấy; sự may rủi', 'n.', NULL, NULL, 'Trong tiếng Mỹ thường chỉ bữa tiệc mà mỗi khách tự mang theo một món ăn đóng góp, không phải bữa cơm gia đình thông thường.', 'I brought a vegetable pie to our neighbourhood potluck.', NULL, 'Tôi đã mang một chiếc bánh rau củ đến bữa tiệc góp món của khu phố.', '{"wordId":"potluck","ukIpa":"/ˌpɒtˈlʌk/","usIpa":"/ˌpɑːtˈlʌk/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A shared meal to which each guest brings food","vi":"bữa ăn chung mỗi người góp một món"},{"pos":"n.","en":"Whatever food or other things happen to be available","vi":"bữa ăn đạm bạc có gì ăn nấy; sự may rủi"}],"examples":[{"en":"I brought a vegetable pie to our neighbourhood potluck.","vi":"Tôi đã mang một chiếc bánh rau củ đến bữa tiệc góp món của khu phố.","audioKind":"ex"},{"en":"Community potluck dinners can strengthen social connections by encouraging residents to share food and cultural traditions.","vi":"Những bữa ăn chung góp món ở cộng đồng giúp gắn kết các mối quan hệ xã hội bằng cách khuyến khích cư dân chia sẻ thực phẩm và truyền thống văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"potluck dinner","vi":"bữa tiệc góp món chung"},{"en":"bring something to a potluck","vi":"mang món ăn gì đến bữa tiệc góp món"},{"en":"take potluck","vi":"tùy nghi ăn uống; phó mặc may rủi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Mỹ thường chỉ bữa tiệc mà mỗi khách tự mang theo một món ăn đóng góp, không phải bữa cơm gia đình thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obtainable', 'en-c1-62', 'obtainable', '/əbˈteɪnəbəl/', 'C1', 'có thể đạt được; có thể kiếm được; có thể mua được', 'adj.', 'obtain (v.), unobtainable (adj.)', 'Đồng nghĩa: available · Trái nghĩa: unobtainable, unavailable', 'Tính từ obtainable nhấn mạnh khả năng thu nhận được; nguồn cung cấp thường đi kèm với giới từ from.', 'Replacement parts are easily obtainable from the local shop.', NULL, 'Các linh kiện thay thế có thể dễ dàng tìm mua được ở cửa hàng địa phương.', '{"wordId":"obtainable","ukIpa":"/əbˈteɪnəbəl/","usIpa":"/əbˈteɪnəbəl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"possible to get or acquire","vi":"có thể đạt được; có thể kiếm được; có thể mua được"}],"examples":[{"en":"Replacement parts are easily obtainable from the local shop.","vi":"Các linh kiện thay thế có thể dễ dàng tìm mua được ở cửa hàng địa phương.","audioKind":"ex"},{"en":"Reliable information about public health services should be readily obtainable by all members of society.","vi":"Mọi thành viên trong xã hội đều nên dễ dàng tiếp cận được các thông tin đáng tin cậy về dịch vụ y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"readily obtainable","vi":"có thể dễ dàng mua/kiếm được"},{"en":"obtainable from","vi":"có thể lấy từ"},{"en":"widely obtainable","vi":"phổ biến, có thể mua ở nhiều nơi"}],"wordFamily":["obtain (v.)","unobtainable (adj.)"],"synonyms":["available"],"antonyms":["unobtainable","unavailable"],"tipVi":"Tính từ obtainable nhấn mạnh khả năng thu nhận được; nguồn cung cấp thường đi kèm với giới từ from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dwell', 'en-c1-62', 'dwell', '/dwel/', 'C1', 'sinh sống; trú ngụ; suy nghĩ hoài; trằn trọc; gặm nhấm (quá khứ, nỗi buồn)', 'v.', 'dweller (n.), dwelling (n.)', 'Đồng nghĩa: reside, inhabit', 'Nghĩa "sinh sống" mang tính trang trọng; cụm dwell on dùng để chỉ hành động suy nghĩ dai dẳng hoặc miêu tả chi tiết về một vấn đề nào đó.', 'Small creatures dwell beneath the stones in our garden.', NULL, 'Những sinh vật nhỏ bé sống ẩn náu dưới các viên đá trong khu vườn của chúng tôi.', '{"wordId":"dwell","ukIpa":"/dwel/","usIpa":"/dwel/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To live in a particular place.","vi":"sinh sống; trú ngụ"},{"pos":"v.","en":"To think or talk about something for a long time.","vi":"suy nghĩ hoài; trằn trọc; gặm nhấm (quá khứ, nỗi buồn)"}],"examples":[{"en":"Small creatures dwell beneath the stones in our garden.","vi":"Những sinh vật nhỏ bé sống ẩn náu dưới các viên đá trong khu vườn của chúng tôi.","audioKind":"ex"},{"en":"Rather than dwell on past failures, schools should help students develop practical strategies for future improvement.","vi":"Thay vì mãi day dứt về những thất bại trong quá khứ, nhà trường nên giúp học sinh xây dựng các chiến lược thiết thực để cải thiện trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"dwell in","vi":"sinh sống tại"},{"en":"dwell on the past","vi":"chìm đắm trong quá khứ"},{"en":"dwell on a problem","vi":"nghĩ hoài về một vấn đề"}],"wordFamily":["dweller (n.)","dwelling (n.)"],"synonyms":["reside","inhabit"],"antonyms":[],"tipVi":"Nghĩa \"sinh sống\" mang tính trang trọng; cụm dwell on dùng để chỉ hành động suy nghĩ dai dẳng hoặc miêu tả chi tiết về một vấn đề nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_palatable', 'en-c1-62', 'palatable', '/ˈpælətəbl/', 'C1', 'vừa miệng; hợp khẩu vị; có thể chấp nhận được; thỏa đáng', 'adj.', 'palatability (n.), unpalatable (adj.)', 'Đồng nghĩa: acceptable, appetising · Trái nghĩa: unpalatable', 'Không nhất thiết chỉ "mục đích ngon tuyệt vời"; cũng có thể dùng để mô tả một phương án, kế hoạch có thể chấp nhận được.', 'A little lemon juice made the soup more palatable.', NULL, 'Một chút nước chanh đã giúp món súp trở nên vừa miệng hơn.', '{"wordId":"palatable","ukIpa":"/ˈpælətəbl/","usIpa":"/ˈpælətəbl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"pleasant enough to eat or drink","vi":"vừa miệng; hợp khẩu vị"},{"pos":"adj.","en":"acceptable or satisfactory, even if not entirely welcome","vi":"có thể chấp nhận được; thỏa đáng"}],"examples":[{"en":"A little lemon juice made the soup more palatable.","vi":"Một chút nước chanh đã giúp món súp trở nên vừa miệng hơn.","audioKind":"ex"},{"en":"Gradual increases in public transport fares may be more palatable to passengers than sudden price rises.","vi":"Việc tăng dần giá vé phương tiện công cộng có thể dễ được hành khách chấp nhận hơn so với việc tăng giá đột ngột.","audioKind":"ex2"}],"collocations":[{"en":"palatable food","vi":"thức ăn ngon miệng"},{"en":"make something palatable","vi":"làm cho cái gì đó dễ chấp nhận"},{"en":"politically palatable","vi":"có thể chấp nhận được về mặt chính trị"}],"wordFamily":["palatability (n.)","unpalatable (adj.)"],"synonyms":["acceptable","appetising"],"antonyms":["unpalatable"],"tipVi":"Không nhất thiết chỉ \"mục đích ngon tuyệt vời\"; cũng có thể dùng để mô tả một phương án, kế hoạch có thể chấp nhận được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pulp', 'en-c1-62', 'pulp', '/pʌlp/', 'C1', 'phần thịt quả mọng nước bên trong trái cây; bột giấy được làm từ hỗn hợp sợi ẩm để sản xuất giấy; nghiền nhuyễn thành một khối ẩm mềm', 'n.', 'pulpy (adj.)', NULL, 'Khi mang nghĩa quả hoặc bột giấy, pulp thường là danh từ không đếm được.', 'I prefer orange juice with plenty of pulp.', NULL, 'Tôi thích nước cam có nhiều phần thịt quả.', '{"wordId":"pulp","ukIpa":"/pʌlp/","usIpa":"/pʌlp/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"The soft, fleshy part inside a fruit.","vi":"phần thịt quả mọng nước bên trong trái cây"},{"pos":"n.","en":"A wet mixture of fibres used to make paper.","vi":"bột giấy được làm từ hỗn hợp sợi ẩm để sản xuất giấy"},{"pos":"v.","en":"To crush something into a soft, wet mass.","vi":"nghiền nhuyễn thành một khối ẩm mềm"}],"examples":[{"en":"I prefer orange juice with plenty of pulp.","vi":"Tôi thích nước cam có nhiều phần thịt quả.","audioKind":"ex"},{"en":"Recycling facilities turn used paper into pulp, reducing the demand for fresh wood fibres.","vi":"Các cơ sở tái chế biến giấy đã qua sử dụng thành bột giấy, qua đó giảm bớt nhu cầu khai thác sợi gỗ mới.","audioKind":"ex2"}],"collocations":[{"en":"fruit pulp","vi":"thịt quả"},{"en":"wood pulp","vi":"bột gỗ"},{"en":"paper pulp","vi":"bột giấy"},{"en":"pulp and paper industry","vi":"ngành công nghiệp giấy và bột giấy"}],"wordFamily":["pulpy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa quả hoặc bột giấy, pulp thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fluff', 'en-c1-62', 'fluff', '/flʌf/', 'C1', 'tơ; lông tơ; xơ vải; làm cho phồng lên; vỗ cho tơi; nội dung sáo rỗng; thứ vô bổ', 'n.', 'fluffy (adj.), fluffiness (n.)', NULL, 'Danh từ thường là không đếm được; fluff up dùng để chỉ hành động vỗ hoặc xốc cho đồ vật phồng tơi lên.', 'I brushed some fluff off my dark coat.', NULL, 'Tôi phủi một ít xơ vải trên chiếc áo khoác tối màu của mình.', '{"wordId":"fluff","ukIpa":"/flʌf/","usIpa":"/flʌf/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"Small, soft, loose fibres from fabric or other materials.","vi":"tơ; lông tơ; xơ vải"},{"pos":"v.","en":"To shake or move something to make it soft and full.","vi":"làm cho phồng lên; vỗ cho tơi"},{"pos":"n.","en":"Content that is entertaining but lacks substance or importance.","vi":"nội dung sáo rỗng; thứ vô bổ"}],"examples":[{"en":"I brushed some fluff off my dark coat.","vi":"Tôi phủi một ít xơ vải trên chiếc áo khoác tối màu của mình.","audioKind":"ex"},{"en":"Educational programmes should offer reliable information rather than superficial fluff that contributes little to public understanding.","vi":"Các chương trình giáo dục nên cung cấp thông tin đáng tin cậy thay vì nội dung sáo rỗng hời hợt đóng góp rất ít cho sự hiểu biết của công chúng.","audioKind":"ex2"}],"collocations":[{"en":"a ball of fluff","vi":"một cục bông tơ"},{"en":"fluff up a pillow","vi":"vỗ phồng gối"},{"en":"pockets full of fluff","vi":"túi đầy xơ vải"}],"wordFamily":["fluffy (adj.)","fluffiness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ thường là không đếm được; fluff up dùng để chỉ hành động vỗ hoặc xốc cho đồ vật phồng tơi lên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stern', 'en-c1-62', 'stern', '/stɝːn/', 'C1', 'nghiêm khắc; khắt khe; cứng rắn; đuôi tàu', 'adj.', 'sternly (adv.), sternness (n.)', 'Đồng nghĩa: strict, severe · Trái nghĩa: lenient', 'Tính từ chỉ thái độ nghiêm khắc; khi là danh từ, nó chỉ phần đuôi tàu, trái nghĩa với bow (mũi tàu).', 'Dad gave us a stern look across the table.', NULL, 'Bố ném cho chúng tôi một ánh nhìn nghiêm khắc từ bên kia bàn.', '{"wordId":"stern","ukIpa":"/stɜːn/","usIpa":"/stɝːn/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Serious and firm in demanding acceptable behaviour.","vi":"nghiêm khắc; khắt khe; cứng rắn"},{"pos":"n.","en":"The back part of a boat or ship.","vi":"đuôi tàu"}],"examples":[{"en":"Dad gave us a stern look across the table.","vi":"Bố ném cho chúng tôi một ánh nhìn nghiêm khắc từ bên kia bàn.","audioKind":"ex"},{"en":"Schools should combine stern warnings about bullying with practical support for students who experience it.","vi":"Nhà trường nên kết hợp các biện pháp cảnh cáo nghiêm khắc đối với hành vi bắt nạt với sự hỗ trợ thiết thực cho những học sinh từng trải qua tình trạng đó.","audioKind":"ex2"}],"collocations":[{"en":"a stern warning","vi":"lời cảnh cáo nghiêm khắc"},{"en":"a stern expression","vi":"vẻ mặt nghiêm nghị"},{"en":"at the stern","vi":"ở phần đuôi tàu"}],"wordFamily":["sternly (adv.)","sternness (n.)"],"synonyms":["strict","severe"],"antonyms":["lenient"],"tipVi":"Tính từ chỉ thái độ nghiêm khắc; khi là danh từ, nó chỉ phần đuôi tàu, trái nghĩa với bow (mũi tàu).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_screech', 'en-c1-62', 'screech', '/skriːtʃ/', 'C1', 'thét lên; phát ra tiếng kêu chói tai; tiếng thét; tiếng rít chói tai', 'v.', NULL, 'Đồng nghĩa: squeal, shriek', 'Có thể dùng cho tiếng thét của con người, động vật hoặc âm thanh chói tai từ phanh xe, máy móc.', 'The old gate screeched as I pushed it open.', NULL, 'Cánh cửa cũ phát ra tiếng rít chói tai khi tôi đẩy mở.', '{"wordId":"screech","ukIpa":"/skriːtʃ/","usIpa":"/skriːtʃ/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To make a loud, high, unpleasant sound","vi":"thét lên; phát ra tiếng kêu chói tai"},{"pos":"n.","en":"A loud, high, unpleasant sound","vi":"tiếng thét; tiếng rít chói tai"}],"examples":[{"en":"The old gate screeched as I pushed it open.","vi":"Cánh cửa cũ phát ra tiếng rít chói tai khi tôi đẩy mở.","audioKind":"ex"},{"en":"Trains that screech around tight bends can contribute significantly to noise pollution in nearby residential areas.","vi":"Những đoàn tàu rít lên khi ôm cua gấp có thể làm gia tăng đáng kể ô nhiễm tiếng ồn ở các khu dân cư lân cận.","audioKind":"ex2"}],"collocations":[{"en":"screech to a halt","vi":"dừng lại kít một tiếng"},{"en":"a loud screech","vi":"một tiếng thét lớn"},{"en":"screeching brakes","vi":"tiếng phanh rít két"}],"wordFamily":[],"synonyms":["squeal","shriek"],"antonyms":[],"tipVi":"Có thể dùng cho tiếng thét của con người, động vật hoặc âm thanh chói tai từ phanh xe, máy móc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flare', 'en-c1-62', 'flare', '/fler/', 'C1', 'bùng lên; bùng phát (cháy sáng đột ngột hoặc trở nên dữ dội hơn ngay lập tức); tia sáng chói; pháo hiệu (một ánh sáng chói lọi bất ngờ hoặc thiết bị tạo ra ánh sáng cảnh báo); loe ra (trở nên rộng hơn về phía một đầu)', 'v.', 'flared (adj.)', NULL, 'flare up có thể chỉ ngọn lửa bùng lên, hoặc chỉ sự bất hòa hay bệnh tật bùng phát.', 'The flames flared as he added another dry branch.', NULL, 'Ngọn lửa bùng lên dữ dội khi anh ấy ném thêm một cành củi khô vào.', '{"wordId":"flare","ukIpa":"/fleə/","usIpa":"/fler/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To burn suddenly brighter or become suddenly stronger.","vi":"bùng lên; bùng phát (cháy sáng đột ngột hoặc trở nên dữ dội hơn ngay lập tức)"},{"pos":"n.","en":"A sudden bright light or a device producing a warning light.","vi":"tia sáng chói; pháo hiệu (một ánh sáng chói lọi bất ngờ hoặc thiết bị tạo ra ánh sáng cảnh báo)"},{"pos":"v.","en":"To become wider towards one end.","vi":"loe ra (trở nên rộng hơn về phía một đầu)"}],"examples":[{"en":"The flames flared as he added another dry branch.","vi":"Ngọn lửa bùng lên dữ dội khi anh ấy ném thêm một cành củi khô vào.","audioKind":"ex"},{"en":"Tensions can flare when urban development projects fail to address the concerns of local residents.","vi":"Căng thẳng có thể bùng phát khi các dự án phát triển đô thị không giải quyết thỏa đáng những mối quan tâm của cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"flare up","vi":"bùng phát"},{"en":"a distress flare","vi":"pháo hiệu cứu nạn"},{"en":"flare out","vi":"loe ra"}],"wordFamily":["flared (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"flare up có thể chỉ ngọn lửa bùng lên, hoặc chỉ sự bất hòa hay bệnh tật bùng phát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sturdy', 'en-c1-62', 'sturdy', '/ˈstɝːdi/', 'C1', 'vững chắc; cường tráng; bền bỉ', 'adj.', 'sturdily (adv.), sturdiness (n.)', 'Đồng nghĩa: strong, robust, solid · Trái nghĩa: flimsy, fragile', 'Thường dùng để mô tả giày dép, đồ đạc, công trình kiến trúc kiên cố, hoặc thể hình vạm vỡ của con người.', 'These sturdy boots keep my feet dry on muddy walks.', NULL, 'Đôi giày bốt chắc chắn này giữ chân tôi khô ráo khi đi trên đường lầy lội.', '{"wordId":"sturdy","ukIpa":"/ˈstɜːdi/","usIpa":"/ˈstɝːdi/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Strongly built and not easily damaged or weakened.","vi":"vững chắc; cường tráng; bền bỉ"}],"examples":[{"en":"These sturdy boots keep my feet dry on muddy walks.","vi":"Đôi giày bốt chắc chắn này giữ chân tôi khô ráo khi đi trên đường lầy lội.","audioKind":"ex"},{"en":"Schools in earthquake-prone regions need sturdy buildings that can protect students during periods of intense shaking.","vi":"Các trường học ở những vùng thường xuyên xảy ra động đất cần có các tòa nhà vững chắc có thể bảo vệ học sinh trong thời gian rung lắc mạnh.","audioKind":"ex2"}],"collocations":[{"en":"sturdy shoes","vi":"giày bền chắc"},{"en":"sturdy construction","vi":"kết cấu vững chắc"},{"en":"a sturdy frame","vi":"khung sườn vững chãi"}],"wordFamily":["sturdily (adv.)","sturdiness (n.)"],"synonyms":["strong","robust","solid"],"antonyms":["flimsy","fragile"],"tipVi":"Thường dùng để mô tả giày dép, đồ đạc, công trình kiến trúc kiên cố, hoặc thể hình vạm vỡ của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dazzling', 'en-c1-62', 'dazzling', '/ˈdæzlɪŋ/', 'C1', 'chói lọi; chói mắt; rực rỡ; tuyệt vời; gây ấn tượng mạnh mẽ', 'adj.', 'dazzle (v.), dazzled (adj.), dazzlingly (adv.)', 'Đồng nghĩa: brilliant, impressive · Trái nghĩa: dull', 'Có thể dùng để mô tả ánh sáng gây chói mắt hoặc dùng để miêu tả một màn trình diễn, tài năng vô cùng xuất sắc.', 'We shielded our eyes from the dazzling afternoon sun.', NULL, 'Chúng tôi phải đưa tay che mắt để tránh ánh nắng buổi chiều chói chang.', '{"wordId":"dazzling","ukIpa":"/ˈdæzlɪŋ/","usIpa":"/ˈdæzlɪŋ/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"so bright that it is difficult to see","vi":"chói lọi; chói mắt"},{"pos":"adj.","en":"extremely impressive because of beauty, skill, or quality","vi":"rực rỡ; tuyệt vời; gây ấn tượng mạnh mẽ"}],"examples":[{"en":"We shielded our eyes from the dazzling afternoon sun.","vi":"Chúng tôi phải đưa tay che mắt để tránh ánh nắng buổi chiều chói chang.","audioKind":"ex"},{"en":"Although dazzling performances attract visitors, sustained investment in local arts education is equally important.","vi":"Mặc dù những màn trình diễn rực rỡ thu hút du khách, nhưng việc đầu tư lâu dài cho giáo dục nghệ thuật địa phương cũng quan trọng không kém.","audioKind":"ex2"}],"collocations":[{"en":"dazzling sunlight","vi":"ánh nắng chói chang"},{"en":"dazzling display","vi":"màn trưng bày rực rỡ"},{"en":"dazzling performance","vi":"màn biểu diễn xuất sắc"}],"wordFamily":["dazzle (v.)","dazzled (adj.)","dazzlingly (adv.)"],"synonyms":["brilliant","impressive"],"antonyms":["dull"],"tipVi":"Có thể dùng để mô tả ánh sáng gây chói mắt hoặc dùng để miêu tả một màn trình diễn, tài năng vô cùng xuất sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_occurrence', 'en-c1-62', 'occurrence', '/əˈkɝːəns/', 'C1', 'sự việc; sự cố; sự xảy ra; sự xuất hiện', 'n.', 'occur (v.)', 'Đồng nghĩa: event, incident', 'Nghĩa sự kiện là danh từ đếm được; nghĩa sự xảy ra là danh từ không đếm được; cần chú ý viết nhân đôi hai chữ rr.', 'Power cuts are a rare occurrence in our village.', NULL, 'Mất điện là chuyện hiếm khi xảy ra ở làng chúng tôi.', '{"wordId":"occurrence","ukIpa":"/əˈkʌrəns/","usIpa":"/əˈkɝːəns/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"something that happens, especially something noticeable","vi":"sự việc; sự cố"},{"pos":"n.","en":"the fact of something happening or being present","vi":"sự xảy ra; sự xuất hiện"}],"examples":[{"en":"Power cuts are a rare occurrence in our village.","vi":"Mất điện là chuyện hiếm khi xảy ra ở làng chúng tôi.","audioKind":"ex"},{"en":"Improved drainage systems can reduce the occurrence of flooding in densely populated urban areas.","vi":"Hệ thống thoát nước được cải thiện có thể làm giảm tần suất ngập lụt ở các đô thị đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"a common occurrence","vi":"một việc thường gặp"},{"en":"a rare occurrence","vi":"một sự việc hiếm hoi"},{"en":"a frequent occurrence","vi":"một việc xảy ra thường xuyên"},{"en":"the occurrence of disease","vi":"sự bùng phát của dịch bệnh"}],"wordFamily":["occur (v.)"],"synonyms":["event","incident"],"antonyms":[],"tipVi":"Nghĩa sự kiện là danh từ đếm được; nghĩa sự xảy ra là danh từ không đếm được; cần chú ý viết nhân đôi hai chữ rr.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tinge', 'en-c1-62', 'tinge', '/tɪndʒ/', 'C1', 'vết màu phớt; chút ít (màu sắc, cảm xúc); làm phớt màu; pha lẫn chút cảm xúc', 'n.', NULL, 'Đồng nghĩa: hint, trace', 'a tinge of dùng để chỉ lượng rất nhỏ; be tinged with diễn tả sự pha tạp, phảng phất.', 'The clouds had a pink tinge after sunset.', NULL, 'Những đám mây mang một sắc hồng nhạt sau khi mặt trời lặn.', '{"wordId":"tinge","ukIpa":"/tɪndʒ/","usIpa":"/tɪndʒ/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A slight amount of colour, feeling, or another quality","vi":"vết màu phớt; chút ít (màu sắc, cảm xúc)"},{"pos":"v.","en":"To give something a slight colour or emotional quality","vi":"làm phớt màu; pha lẫn chút cảm xúc"}],"examples":[{"en":"The clouds had a pink tinge after sunset.","vi":"Những đám mây mang một sắc hồng nhạt sau khi mặt trời lặn.","audioKind":"ex"},{"en":"For many graduates, the excitement of entering employment is tinged with anxiety about financial independence.","vi":"Đối với nhiều sinh viên mới tốt nghiệp, sự phấn khích khi bước chân vào thị trường lao động lại phảng phất chút lo âu về sự độc lập tài chính.","audioKind":"ex2"}],"collocations":[{"en":"a tinge of sadness","vi":"một chút nỗi buồn"},{"en":"a pink tinge","vi":"sắc hồng phớt"},{"en":"be tinged with regret","vi":"mang chút ít sự hối tiếc"}],"wordFamily":[],"synonyms":["hint","trace"],"antonyms":[],"tipVi":"a tinge of dùng để chỉ lượng rất nhỏ; be tinged with diễn tả sự pha tạp, phảng phất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_62_1', 'en-c1-62', 'Cách dùng “dwell” (v.) — sinh sống; trú ngụ', 'dwell in  ·  dwell on the past  ·  dwell on a problem', 'Nghĩa "sinh sống" mang tính trang trọng; cụm dwell on dùng để chỉ hành động suy nghĩ dai dẳng hoặc miêu tả chi tiết về một vấn đề nào đó.', 'Họ từ (Word Family): dweller (n.), dwelling (n.) | Đồng nghĩa: reside, inhabit', '[{"hanzi":"Small creatures dwell beneath the stones in our garden.","pinyin":"","meaning":"Những sinh vật nhỏ bé sống ẩn náu dưới các viên đá trong khu vườn của chúng tôi."},{"hanzi":"Rather than dwell on past failures, schools should help students develop practical strategies for future improvement.","pinyin":"","meaning":"Thay vì mãi day dứt về những thất bại trong quá khứ, nhà trường nên giúp học sinh xây dựng các chiến lược thiết thực để cải thiện trong tương lai."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_62_2', 'en-c1-62', 'Cách dùng “potluck” (n.) — bữa ăn chung mỗi người góp một món', 'potluck dinner  ·  bring something to a potluck  ·  take potluck', 'Trong tiếng Mỹ thường chỉ bữa tiệc mà mỗi khách tự mang theo một món ăn đóng góp, không phải bữa cơm gia đình thông thường.', NULL, '[{"hanzi":"I brought a vegetable pie to our neighbourhood potluck.","pinyin":"","meaning":"Tôi đã mang một chiếc bánh rau củ đến bữa tiệc góp món của khu phố."},{"hanzi":"Community potluck dinners can strengthen social connections by encouraging residents to share food and cultural traditions.","pinyin":"","meaning":"Những bữa ăn chung góp món ở cộng đồng giúp gắn kết các mối quan hệ xã hội bằng cách khuyến khích cư dân chia sẻ thực phẩm và truyền thống văn hóa."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_62_3', 'en-c1-62', 'Cách dùng “palatable” (adj.) — vừa miệng; hợp khẩu vị', 'palatable food  ·  make something palatable  ·  politically palatable', 'Không nhất thiết chỉ "mục đích ngon tuyệt vời"; cũng có thể dùng để mô tả một phương án, kế hoạch có thể chấp nhận được.', 'Họ từ (Word Family): palatability (n.), unpalatable (adj.) | Đồng nghĩa: acceptable, appetising · Trái nghĩa: unpalatable', '[{"hanzi":"A little lemon juice made the soup more palatable.","pinyin":"","meaning":"Một chút nước chanh đã giúp món súp trở nên vừa miệng hơn."},{"hanzi":"Gradual increases in public transport fares may be more palatable to passengers than sudden price rises.","pinyin":"","meaning":"Việc tăng dần giá vé phương tiện công cộng có thể dễ được hành khách chấp nhận hơn so với việc tăng giá đột ngột."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_62_4', 'en-c1-62', 'Cách dùng “grit” (n.) — sỏi mịn; cát sạn', 'grit your teeth  ·  grit the roads  ·  show grit', 'Cả nghĩa sỏi mịn và nghị lực đều là danh từ không đếm được; grit không mang nghĩa là sự mài mòn theo cách thông thường.', 'Họ từ (Word Family): gritty (adj.), grittiness (n.) | Đồng nghĩa: determination, resolve', '[{"hanzi":"I shook the grit out of my walking boots.","pinyin":"","meaning":"Tôi giũ sạch những hạt cát sỏi ở trong đôi giày đi bộ đường dài của mình."},{"hanzi":"Although talent matters, students often need grit and consistent support to overcome persistent learning difficulties.","pinyin":"","meaning":"Mặc dù tài liệu năng khiếu rất quan trọng, nhưng học sinh thường cần có nghị lực và sự hỗ trợ bền bỉ để vượt qua các khó khăn học tập lâu dài."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_62_1', 'en-c1-62', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_1_1', 'ten_c1_62_1', 'elapse', 'Several minutes elapsed before the bus finally arrived.', 'Several minutes elapsed before the bus finally arrived.', '/ɪˈlæps/', 'Vài phút trôi qua trước khi chiếc xe buýt cuối cùng cũng đến.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_1_2', 'ten_c1_62_1', 'tack', 'I used a tack to secure the loose fabric.', 'I used a tack to secure the loose fabric.', '/tæk/', 'Tôi dùng một chiếc đinh ghim ngắn để cố định mảnh vải bị lỏng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_1_3', 'ten_c1_62_1', 'relentless', 'The relentless rain kept us indoors all weekend.', 'The relentless rain kept us indoors all weekend.', '/rɪˈlentləs/', 'Cơn mưa dầm dề không ngớt đã giữ chân chúng tôi ở trong nhà suốt cả cuối tuần.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_1_4', 'ten_c1_62_1', 'sway', 'The branches swayed gently as we ate outside.', 'The branches swayed gently as we ate outside.', '/sweɪ/', 'Những cành cây nhẹ nhàng đu đưa khi chúng tôi ăn uống ngoài trời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_1_5', 'ten_c1_62_1', 'habitual', 'His habitual lateness meant we often missed the bus.', 'His habitual lateness meant we often missed the bus.', '/həˈbɪtʃuəl/', 'Việc đi học muộn thành thói quen khiến chúng tôi thường xuyên lỡ chuyến xe buýt.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_1_6', 'ten_c1_62_1', 'dual', 'This sofa has a dual purpose: sitting and sleeping.', 'This sofa has a dual purpose: sitting and sleeping.', '/ˈduːəl/', 'Chiếc ghế sofa này có hai công dụng: dùng để ngồi và để ngủ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_1_7', 'ten_c1_62_1', 'commotion', 'A loose puppy caused a commotion in the café.', 'A loose puppy caused a commotion in the café.', '/kəˈmoʊʃən/', 'Một chú chó con xổng chuồng đã gây ra một phen náo động trong quán cà phê.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_1_8', 'ten_c1_62_1', 'whirl', 'Dry leaves whirled around us in the wind.', 'Dry leaves whirled around us in the wind.', '/wɝːl/', 'Lá khô bay vòng quanh chúng tôi trong gió.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_62_1_1', 'en-c1-62', 'ten_c1_62_1', 'listening', 'listening', 'Several minutes elapsed before the bus finally arrived.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vài phút trôi qua trước khi chiếc xe buýt cuối cùng cũng đến.","Mất điện là chuyện hiếm khi xảy ra ở làng chúng tôi.","Tôi giũ sạch những hạt cát sỏi ở trong đôi giày đi bộ đường dài của mình.","Một chút nước chanh đã giúp món súp trở nên vừa miệng hơn."]'::jsonb, 0, 'Several minutes elapsed before the bus finally arrived. → Vài phút trôi qua trước khi chiếc xe buýt cuối cùng cũng đến.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_62_1_2', 'en-c1-62', 'ten_c1_62_1', 'listening', 'listening', 'I used a tack to secure the loose fabric.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi dùng một chiếc đinh ghim ngắn để cố định mảnh vải bị lỏng.","Ngọn lửa bùng lên dữ dội khi anh ấy ném thêm một cành củi khô vào.","Các linh kiện thay thế có thể dễ dàng tìm mua được ở cửa hàng địa phương.","Tôi không nhớ ngay địa chỉ lúc này đâu, nhưng tôi sẽ kiểm tra lại."]'::jsonb, 0, 'I used a tack to secure the loose fabric. → Tôi dùng một chiếc đinh ghim ngắn để cố định mảnh vải bị lỏng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_62_1_3', 'en-c1-62', 'ten_c1_62_1', 'listening', 'listening', 'The relentless rain kept us indoors all weekend.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi không nhớ ngay địa chỉ lúc này đâu, nhưng tôi sẽ kiểm tra lại.","Tôi giũ sạch những hạt cát sỏi ở trong đôi giày đi bộ đường dài của mình.","Một chú chó con xổng chuồng đã gây ra một phen náo động trong quán cà phê.","Cơn mưa dầm dề không ngớt đã giữ chân chúng tôi ở trong nhà suốt cả cuối tuần."]'::jsonb, 3, 'The relentless rain kept us indoors all weekend. → Cơn mưa dầm dề không ngớt đã giữ chân chúng tôi ở trong nhà suốt cả cuối tuần.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_62_2', 'en-c1-62', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_2_1', 'ten_c1_62_2', 'elapse', 'Several years may elapse before environmental policies produce measurable improvements in urban air quality.', 'Several years may elapse before environmental policies produce measurable improvements in urban air quality.', '/ɪˈlæps/', 'Có thể mất vài năm trôi qua trước khi các chính sách môi trường mang lại những cải thiện có thể đo lường được về chất lượng không khí đô thị.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_2_2', 'ten_c1_62_2', 'tack', 'When public campaigns fail to change behaviour, policymakers may need to take a different tack.', 'When public campaigns fail to change behaviour, policymakers may need to take a different tack.', '/tæk/', 'Khi các chiến dịch công cộng không thay đổi được hành vi, các nhà hoạch định chính sách có thể cần áp dụng một phương pháp khác.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_2_3', 'ten_c1_62_2', 'relentless', 'Relentless pressure to achieve high grades can undermine students'' confidence and damage their mental health.', 'Relentless pressure to achieve high grades can undermine students'' confidence and damage their mental health.', '/rɪˈlentləs/', 'Áp lực không ngừng nghỉ để đạt được điểm số cao có thể làm suy yếu sự tự tin của học sinh và tổn hại đến sức khỏe tinh thần của các em.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_2_4', 'ten_c1_62_2', 'sway', 'Emotional advertising can sway consumers'' decisions even when competing products offer better value for money.', 'Emotional advertising can sway consumers'' decisions even when competing products offer better value for money.', '/sweɪ/', 'Quảng cáo mang tính cảm xúc có thể chi phối quyết định của người tiêu dùng ngay cả khi các sản phẩm cạnh tranh mang lại giá trị kinh tế tốt hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_2_5', 'ten_c1_62_2', 'habitual', 'Habitual use of private cars can increase urban congestion and discourage investment in public transport.', 'Habitual use of private cars can increase urban congestion and discourage investment in public transport.', '/həˈbɪtʃuəl/', 'Việc thường xuyên sử dụng xe hơi cá nhân có thể làm tăng tình trạng tắc nghẽn đô thị và làm giảm động lực đầu tư vào giao thông công cộng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_62_2_6', 'ten_c1_62_2', 'dual', 'Many working parents face the dual challenge of earning an income and caring for young children.', 'Many working parents face the dual challenge of earning an income and caring for young children.', '/ˈduːəl/', 'Nhiều bậc cha mẹ đi làm phải đối mặt với thử thách kép là vừa kiếm thu nhập vừa chăm sóc con nhỏ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_62_2_1', 'en-c1-62', 'ten_c1_62_2', 'listening', 'listening', 'Several years may elapse before environmental policies produce measurable improvements in urban air quality.', NULL, 'Trong câu vừa nghe, từ “elapse” mang nghĩa nào sau đây?', '["trôi qua (dùng cho thời gian)","mất dáng; không có hình thù rõ ràng; thùng thình","tác nhân thúc đẩy; người hoặc vật gây ra thay đổi","sự quy nguyên nhân; sự quy kết trách nhiệm"]'::jsonb, 0, '“elapse” (/ɪˈlæps/): trôi qua (dùng cho thời gian). Câu đầy đủ: Several years may elapse before environmental policies produce measurable improvements in urban air quality.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_62_2_2', 'en-c1-62', 'ten_c1_62_2', 'listening', 'listening', 'When public campaigns fail to change behaviour, policymakers may need to take a different tack.', NULL, 'Trong câu vừa nghe, từ “tack” mang nghĩa nào sau đây?', '["mạch máu nhỏ; ống mao dẫn","đinh ghim ngắn đầu to và dẹt","cắt cổ, đắt cắt cổ; quá mức, cao vô lý","sự vô lý; sự lố bịch; tính chất hoang đường"]'::jsonb, 1, '“tack” (/tæk/): đinh ghim ngắn đầu to và dẹt. Câu đầy đủ: When public campaigns fail to change behaviour, policymakers may need to take a different tack.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
