INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_1', 'en-c1-62', NULL, 'comprehensive_test', 'listening', 'elapse', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tầm vóc; quy mô lớn; tầm quan trọng","trôi qua (dùng cho thời gian)","tiên đoán; báo trước","nghệ thuật thêu thùa; nghề thêu"]'::jsonb, 1, 'elapse (/ɪˈlæps/) → trôi qua (dùng cho thời gian)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_2', 'en-c1-62', NULL, 'comprehensive_test', 'listening', 'I used a tack to secure the loose fabric.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những sinh vật nhỏ bé sống ẩn náu dưới các viên đá trong khu vườn của chúng tôi.","Tôi đã mang một chiếc bánh rau củ đến bữa tiệc góp món của khu phố.","Việc đi học muộn thành thói quen khiến chúng tôi thường xuyên lỡ chuyến xe buýt.","Tôi dùng một chiếc đinh ghim ngắn để cố định mảnh vải bị lỏng."]'::jsonb, 3, 'I used a tack to secure the loose fabric. → Tôi dùng một chiếc đinh ghim ngắn để cố định mảnh vải bị lỏng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_3', 'en-c1-62', NULL, 'comprehensive_test', 'listening', 'relentless', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thủ tướng; thủ hiến; người đứng đầu chính phủ cấp vùng","tan biến; làm tản mác","không ngừng nghỉ; liên tục không giảm","miệng cống; hố ga; cửa kiểm tra kỹ thuật"]'::jsonb, 2, 'relentless (/rɪˈlentləs/) → không ngừng nghỉ; liên tục không giảm; nhẫn tâm; không khoan nhượng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_4', 'en-c1-62', NULL, 'comprehensive_test', 'listening', 'The branches swayed gently as we ate outside.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vài phút trôi qua trước khi chiếc xe buýt cuối cùng cũng đến.","Những cành cây nhẹ nhàng đu đưa khi chúng tôi ăn uống ngoài trời.","Chúng tôi phải đưa tay che mắt để tránh ánh nắng buổi chiều chói chang.","Đôi giày bốt chắc chắn này giữ chân tôi khô ráo khi đi trên đường lầy lội."]'::jsonb, 1, 'The branches swayed gently as we ate outside. → Những cành cây nhẹ nhàng đu đưa khi chúng tôi ăn uống ngoài trời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_5', 'en-c1-62', NULL, 'comprehensive_test', 'listening', 'habitual', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thường xuyên; theo thói quen","mang tính hủy diệt; tàn phá nặng nề","làm tê liệt; làm mất khả năng vận động","lao dốc; sụt giảm mạnh"]'::jsonb, 0, 'habitual (/həˈbɪtʃuəl/) → thường xuyên; theo thói quen', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_6', 'en-c1-62', NULL, 'comprehensive_test', 'listening', 'This sofa has a dual purpose: sitting and sleeping.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một chút nước chanh đã giúp món súp trở nên vừa miệng hơn.","Một chú chó con xổng chuồng đã gây ra một phen náo động trong quán cà phê.","Những đám mây mang một sắc hồng nhạt sau khi mặt trời lặn.","Chiếc ghế sofa này có hai công dụng: dùng để ngồi và để ngủ."]'::jsonb, 3, 'This sofa has a dual purpose: sitting and sleeping. → Chiếc ghế sofa này có hai công dụng: dùng để ngồi và để ngủ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_7', 'en-c1-62', NULL, 'comprehensive_test', 'listening', 'commotion', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tầng lớp quý tộc (giai cấp xã hội cao nhất, có tước vị và đặc quyền thế tập)","sự náo động; cảnh ồn ào hỗn loạn","viên nhỏ; hạt nén","thuộc về phong kiến"]'::jsonb, 1, 'commotion (/kəˈmoʊʃən/) → sự náo động; cảnh ồn ào hỗn loạn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_8', 'en-c1-62', NULL, 'comprehensive_test', 'listening', 'Dry leaves whirled around us in the wind.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lá khô bay vòng quanh chúng tôi trong gió.","Một chút nước chanh đã giúp món súp trở nên vừa miệng hơn.","Các linh kiện thay thế có thể dễ dàng tìm mua được ở cửa hàng địa phương.","Đôi giày bốt chắc chắn này giữ chân tôi khô ráo khi đi trên đường lầy lội."]'::jsonb, 0, 'Dry leaves whirled around us in the wind. → Lá khô bay vòng quanh chúng tôi trong gió.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_9', 'en-c1-62', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “done regularly or repeatedly as a habit”?', '["flare","habitual","screech","grit"]'::jsonb, 1, 'habitual (/həˈbɪtʃuəl/) → thường xuyên; theo thói quen', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_10', 'en-c1-62', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Having two parts, purposes, or aspects.”?', '["palatable","dwell","dual","offhand"]'::jsonb, 2, 'dual (/ˈduːəl/) → hai mặt; kép; song song', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_11', 'en-c1-62', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Noisy activity and confusion caused by excitement or disturbance”?', '["commotion","footing","offhand","sway"]'::jsonb, 0, 'commotion (/kəˈmoʊʃən/) → sự náo động; cảnh ồn ào hỗn loạn', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_12', 'en-c1-62', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To spin or move around very quickly.”?', '["flare","potluck","whirl","footing"]'::jsonb, 2, 'whirl (/wɝːl/) → quay vòng; xoay tít', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_13', 'en-c1-62', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A secure position for your feet on a surface.”?', '["pulp","footing","occurrence","dual"]'::jsonb, 1, 'footing (/ˈfʊtɪŋ/) → chỗ đặt chân vững chắc; thế đứng', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
