INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_18', 'en-c1-62', NULL, 'comprehensive_test', 'reading', NULL, 'Several years may elapse before environmental policies produce measurable improvements in urban air quality.', 'Dựa vào câu trên, từ “elapse” có nghĩa phù hợp nhất là gì?', '["vò đầu bứt tai; băn khoăn lo lắng; trăn trở khổ sở","phát triển mạnh mẽ; phát đạt","trôi qua (dùng cho thời gian)","nghiêm khắc; khắt khe; cứng rắn"]'::jsonb, 2, 'elapse: trôi qua (dùng cho thời gian). Dịch cả câu: Có thể mất vài năm trôi qua trước khi các chính sách môi trường mang lại những cải thiện có thể đo lường được về chất lượng không khí đô thị.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_19', 'en-c1-62', NULL, 'comprehensive_test', 'reading', NULL, 'When public campaigns fail to change behaviour, policymakers may need to take a different tack.', 'Dựa vào câu trên, từ “tack” có nghĩa phù hợp nhất là gì?', '["vô giá; cực kỳ quý giá; vô cùng hữu ích","đinh ghim ngắn đầu to và dẹt","thợ thủ công; thợ lành nghề","búi; cụm; đám; nhóm"]'::jsonb, 1, 'tack: đinh ghim ngắn đầu to và dẹt; cố định cái gì bằng đinh ngắn; một phương pháp hoặc cách tiếp cận cụ thể để giải quyết một tình huống. Dịch cả câu: Khi các chiến dịch công cộng không thay đổi được hành vi, các nhà hoạch định chính sách có thể cần áp dụng một phương pháp khác.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_20', 'en-c1-62', NULL, 'comprehensive_test', 'reading', NULL, 'Relentless pressure to achieve high grades can undermine students'' confidence and damage their mental health.', 'Dựa vào câu trên, từ “relentless” có nghĩa phù hợp nhất là gì?', '["không ngừng nghỉ; liên tục không giảm","dập tắt; làm tắt","học sinh trốn học; kẻ trốn học","vùng lân cận; vùng quanh đây"]'::jsonb, 0, 'relentless: không ngừng nghỉ; liên tục không giảm; nhẫn tâm; không khoan nhượng. Dịch cả câu: Áp lực không ngừng nghỉ để đạt được điểm số cao có thể làm suy yếu sự tự tin của học sinh và tổn hại đến sức khỏe tinh thần của các em.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_21', 'en-c1-62', NULL, 'comprehensive_test', 'reading', NULL, 'Emotional advertising can sway consumers'' decisions even when competing products offer better value for money.', 'Dựa vào câu trên, từ “sway” có nghĩa phù hợp nhất là gì?', '["sự xác minh; sự kiểm chứng","dao găm; đoản kiếm","đánh lừa; lừa dối; khiến ai đó ảo tưởng","lắc lư; đu đưa"]'::jsonb, 3, 'sway: lắc lư; đu đưa; ảnh hưởng; chi phối; sự chi phối. Dịch cả câu: Quảng cáo mang tính cảm xúc có thể chi phối quyết định của người tiêu dùng ngay cả khi các sản phẩm cạnh tranh mang lại giá trị kinh tế tốt hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_22', 'en-c1-62', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chói lọi; chói mắt”', '["lofty","dazzling","symmetry","tactful"]'::jsonb, 1, 'chói lọi; chói mắt → dazzling (/ˈdæzlɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
