INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_62_24', 'en-c1-62', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vết màu phớt; chút ít (màu sắc, cảm xúc)”', '["polymer","prestige","exile","tinge"]'::jsonb, 3, 'vết màu phớt; chút ít (màu sắc, cảm xúc) → tinge (/tɪndʒ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-63', 'en', 'Bài 63: Đời sống hằng ngày (4) - CEFR C1', 'CEFR C1', 'C1 · Đời sống', '27 từ vựng Tiếng Anh CEFR C1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5063, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_waken', 'en-c1-63', 'waken', '/ˈweɪkən/', 'C1', 'thức giấc; đánh thức', 'v.', 'wake (v.), awake (adj.), awakening (n.)', 'Đồng nghĩa: wake, awaken', 'Từ này ít phổ biến và mang tính văn phong trang trọng hơn so với wake; dạng quá khứ và quá khứ phân từ đều là wakened.', 'Birdsong wakened me before the sun came up.', NULL, 'Tiếng chim hót đã đánh thức tôi dậy trước khi mặt trời mọc.', '{"wordId":"waken","ukIpa":"/ˈweɪkən/","usIpa":"/ˈweɪkən/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to stop sleeping or cause someone to stop sleeping","vi":"thức giấc; đánh thức"}],"examples":[{"en":"Birdsong wakened me before the sun came up.","vi":"Tiếng chim hót đã đánh thức tôi dậy trước khi mặt trời mọc.","audioKind":"ex"},{"en":"Residents living near airports may be wakened repeatedly by aircraft noise, which can affect their overall health.","vi":"Những cư dân sống gần sân bay có thể bị tiếng ồn máy bay làm cho thức giấc nhiều lần, điều này có thể ảnh hưởng đến sức khỏe tổng thể của họ.","audioKind":"ex2"}],"collocations":[{"en":"waken someone from sleep","vi":"đánh thức ai khỏi giấc ngủ"},{"en":"waken at dawn","vi":"thức giấc lúc bình minh"},{"en":"waken to birdsong","vi":"thức dậy trong tiếng chim hót"}],"wordFamily":["wake (v.)","awake (adj.)","awakening (n.)"],"synonyms":["wake","awaken"],"antonyms":[],"tipVi":"Từ này ít phổ biến và mang tính văn phong trang trọng hơn so với wake; dạng quá khứ và quá khứ phân từ đều là wakened.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reel', 'en-c1-63', 'reel', '/riːl/', 'C1', 'cuộn; ống cuộn; lảo đảo; choáng váng; điêu đứng', 'n.', NULL, 'Đồng nghĩa: spool, stagger', 'Cụm reel from dùng để chỉ việc chịu ảnh hưởng nặng nề, trong khi reel off có nghĩa là đọc hoặc liệt kê một mạch không ngừng.', 'She wound the loose fishing line onto the reel.', NULL, 'Cô ấy quấn đoạn dây câu bị chùng vào ống cuộn.', '{"wordId":"reel","ukIpa":"/riːl/","usIpa":"/riːl/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"a round holder for winding thread, wire, or film","vi":"cuộn; ống cuộn"},{"pos":"v.","en":"to stagger or feel overwhelmed by something shocking","vi":"lảo đảo; choáng váng; điêu đứng"}],"examples":[{"en":"She wound the loose fishing line onto the reel.","vi":"Cô ấy quấn đoạn dây câu bị chùng vào ống cuộn.","audioKind":"ex"},{"en":"Local businesses continued to reel from the sudden closure of the region''s largest factory.","vi":"Các doanh nghiệp địa phương vẫn tiếp tục điêu đứng trước việc đóng cửa đột ngột của nhà máy lớn nhất vùng.","audioKind":"ex2"}],"collocations":[{"en":"a reel of film","vi":"một cuộn phim"},{"en":"a fishing reel","vi":"guồng câu cá"},{"en":"reel from the shock","vi":"choáng váng vì cú sốc"},{"en":"reel off a list","vi":"liên tiếp tuôn ra một danh sách"}],"wordFamily":[],"synonyms":["spool","stagger"],"antonyms":[],"tipVi":"Cụm reel from dùng để chỉ việc chịu ảnh hưởng nặng nề, trong khi reel off có nghĩa là đọc hoặc liệt kê một mạch không ngừng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flicker', 'en-c1-63', 'flicker', '/ˈflɪkər/', 'C1', 'nhấp nháy; bập bùng; ánh sáng nhấp nháy; đốm sáng; vẻ lóe lên; một thoáng (cảm xúc)', 'v.', 'flickering (adj.)', NULL, 'Cụm a flicker of có thể đi với hope v.v., biểu thị một cảm xúc diễn ra trong chốc lát.', 'The candle flickered when she opened the kitchen door.', NULL, 'Ngọn nến bập bùng khi cô ấy mở cửa nhà bếp.', '{"wordId":"flicker","ukIpa":"/ˈflɪkə/","usIpa":"/ˈflɪkər/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to shine unsteadily, becoming brighter and dimmer repeatedly","vi":"nhấp nháy; bập bùng"},{"pos":"n.","en":"a brief or unsteady movement of light","vi":"ánh sáng nhấp nháy; đốm sáng"},{"pos":"n.","en":"a slight feeling or expression that appears briefly","vi":"vẻ lóe lên; một thoáng (cảm xúc)"}],"examples":[{"en":"The candle flickered when she opened the kitchen door.","vi":"Ngọn nến bập bùng khi cô ấy mở cửa nhà bếp.","audioKind":"ex"},{"en":"When streetlights flicker or fail, pedestrians may feel less secure in urban public spaces.","vi":"Khi đèn đường nhấp nháy hoặc hỏng, người đi bộ có thể cảm thấy kém an toàn hơn ở các không gian công cộng đô thị.","audioKind":"ex2"}],"collocations":[{"en":"flickering light","vi":"ánh sáng nhấp nháy"},{"en":"a flicker of hope","vi":"một tia hy vọng"},{"en":"a flicker of recognition","vi":"một thoáng nhận ra"}],"wordFamily":["flickering (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm a flicker of có thể đi với hope v.v., biểu thị một cảm xúc diễn ra trong chốc lát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wrench', 'en-c1-63', 'wrench', '/rentʃ/', 'C1', 'cái mỏ lết; cờ-lê; vặn mạnh; giật mạnh; làm trẹo; nỗi buồn chia ly; sự giật mạnh', 'n.', NULL, 'Đồng nghĩa: spanner, yank, twist', 'Cờ-lê/mỏ lết trong tiếng Anh-Anh thường gọi là spanner; wrench cũng có thể đóng vai trò là động từ.', 'She tightened the loose bolt with a wrench.', NULL, 'Cô ấy dùng cờ-lê để siết chặt con bu-lông bị lỏng.', '{"wordId":"wrench","ukIpa":"/rentʃ/","usIpa":"/rentʃ/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A tool used to grip and turn nuts or bolts","vi":"cái mỏ lết; cờ-lê"},{"pos":"v.","en":"Pull or twist forcefully, sometimes causing injury","vi":"vặn mạnh; giật mạnh; làm trẹo"},{"pos":"n.","en":"Sadness at leaving someone or something; a sudden forceful twist","vi":"nỗi buồn chia ly; sự giật mạnh"}],"examples":[{"en":"She tightened the loose bolt with a wrench.","vi":"Cô ấy dùng cờ-lê để siết chặt con bu-lông bị lỏng.","audioKind":"ex"},{"en":"Leaving a close community can be a real wrench for students who move abroad for university.","vi":"Việc rời xa một cộng đồng gắn bó có thể là một nỗi buồn mất mát lớn đối với các sinh viên ra nước ngoài du học.","audioKind":"ex2"}],"collocations":[{"en":"an adjustable wrench","vi":"mỏ lết điều chỉnh được"},{"en":"wrench something open","vi":"cạy mạnh vật gì ra"},{"en":"wrench your shoulder","vi":"làm trẹo vai"},{"en":"a real wrench","vi":"nỗi đau khó rời xa"}],"wordFamily":[],"synonyms":["spanner","yank","twist"],"antonyms":[],"tipVi":"Cờ-lê/mỏ lết trong tiếng Anh-Anh thường gọi là spanner; wrench cũng có thể đóng vai trò là động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sly', 'en-c1-63', 'sly', '/slaɪ/', 'C1', 'ranh mãnh, quỷ quyệt, lén lút (thường nhằm vụ lợi); láu lỉnh, có ý cười thầm hoặc biểu lộ sự hiểu ý', 'adj.', 'slyly (adv.), slyness (n.)', 'Đồng nghĩa: cunning, crafty · Trái nghĩa: straightforward', 'on the sly là cụm từ cố định, mang ý nghĩa là lén lút.', 'The sly cat stole a biscuit while I turned away.', NULL, 'Con mèo ranh mãnh đã chớp thời cơ nẫng mất một chiếc bánh quy lúc tôi quay đi.', '{"wordId":"sly","ukIpa":"/slaɪ/","usIpa":"/slaɪ/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Secretive and clever, often to gain an unfair advantage.","vi":"ranh mãnh, quỷ quyệt, lén lút (thường nhằm vụ lợi)"},{"pos":"adj.","en":"Showing secret amusement or knowledge.","vi":"láu lỉnh, có ý cười thầm hoặc biểu lộ sự hiểu ý"}],"examples":[{"en":"The sly cat stole a biscuit while I turned away.","vi":"Con mèo ranh mãnh đã chớp thời cơ nẫng mất một chiếc bánh quy lúc tôi quay đi.","audioKind":"ex"},{"en":"Sly attempts to hide additional charges can damage consumer trust and harm a company''s reputation.","vi":"Những nỗ lực lén lút nhằm che giấu các khoản phí phát sinh có thể làm xói mòn lòng tin của người tiêu dùng và tổn hại đến uy tín công ty.","audioKind":"ex2"}],"collocations":[{"en":"sly smile","vi":"nụ cười tủm tỉm"},{"en":"sly glance","vi":"cái liếc mắt đưa tình"},{"en":"on the sly","vi":"lén lút, vụ trộm"}],"wordFamily":["slyly (adv.)","slyness (n.)"],"synonyms":["cunning","crafty"],"antonyms":["straightforward"],"tipVi":"on the sly là cụm từ cố định, mang ý nghĩa là lén lút.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_youthful', 'en-c1-63', 'youthful', '/ˈjuːθfəl/', 'C1', 'trẻ trung, có nét trẻ con hoặc mang năng lượng, đặc trưng của tuổi trẻ', 'adj.', 'youth (n.), youthfully (adv.), youthfulness (n.)', 'Đồng nghĩa: young · Trái nghĩa: aged', 'youthful thường mang hàm ý trẻ trung hoặc tràn trề sức sống, không nhất thiết chỉ độ tuổi thực tế còn nhỏ.', 'My grandfather still has a youthful smile and boundless energy.', NULL, 'Ông tôi vẫn giữ được nụ cười trẻ trung cùng nguồn năng lượng dồi dào.', '{"wordId":"youthful","ukIpa":"/ˈjuːθfəl/","usIpa":"/ˈjuːθfəl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Looking young or showing the energy and qualities of youth.","vi":"trẻ trung, có nét trẻ con hoặc mang năng lượng, đặc trưng của tuổi trẻ"}],"examples":[{"en":"My grandfather still has a youthful smile and boundless energy.","vi":"Ông tôi vẫn giữ được nụ cười trẻ trung cùng nguồn năng lượng dồi dào.","audioKind":"ex"},{"en":"A youthful workforce can bring fresh ideas, while experienced employees contribute valuable practical knowledge.","vi":"Lực lượng lao động trẻ trung có thể mang đến những ý tưởng mới mẻ, trong khi các nhân viên giàu kinh nghiệm đóng góp những kiến thức thực tế vô giá.","audioKind":"ex2"}],"collocations":[{"en":"youthful appearance","vi":"vẻ bề ngoài trẻ trung"},{"en":"youthful energy","vi":"năng lượng tuổi trẻ"},{"en":"youthful enthusiasm","vi":"sự nhiệt huyết tuổi trẻ"}],"wordFamily":["youth (n.)","youthfully (adv.)","youthfulness (n.)"],"synonyms":["young"],"antonyms":["aged"],"tipVi":"youthful thường mang hàm ý trẻ trung hoặc tràn trề sức sống, không nhất thiết chỉ độ tuổi thực tế còn nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quicken', 'en-c1-63', 'quicken', '/ˈkwɪkən/', 'C1', 'làm cho nhanh hơn, tăng tốc độ', 'v.', 'quick (adj.), quickly (adv.), quickness (n.)', 'Đồng nghĩa: accelerate, speed up · Trái nghĩa: decelerate, slow down', 'Có thể là ngoại động từ hoặc nội động từ, thường đi kèm với các từ như pace hoặc pulse.', 'I quickened my pace when the rain started.', NULL, 'Tôi bước nhanh hơn khi trời bắt đầu đổ mưa.', '{"wordId":"quicken","ukIpa":"/ˈkwɪkən/","usIpa":"/ˈkwɪkən/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"Become faster, or make something happen faster.","vi":"làm cho nhanh hơn, tăng tốc độ"}],"examples":[{"en":"I quickened my pace when the rain started.","vi":"Tôi bước nhanh hơn khi trời bắt đầu đổ mưa.","audioKind":"ex"},{"en":"Improved transport links can quicken the pace of economic development by connecting rural producers with urban markets.","vi":"Việc cải thiện kết nối giao thông có thể đẩy nhanh tốc độ phát triển kinh tế bằng cách kết nối các nhà sản xuất nông thôn với thị trường đô thị.","audioKind":"ex2"}],"collocations":[{"en":"quicken your pace","vi":"tăng tốc độ bước đi"},{"en":"quicken the pulse","vi":"làm tim đập nhanh hơn"},{"en":"quicken the process","vi":"đẩy nhanh tiến trình"}],"wordFamily":["quick (adj.)","quickly (adv.)","quickness (n.)"],"synonyms":["accelerate","speed up"],"antonyms":["decelerate","slow down"],"tipVi":"Có thể là ngoại động từ hoặc nội động từ, thường đi kèm với các từ như pace hoặc pulse.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_firmness', 'en-c1-63', 'firmness', '/ˈfɜːrmnəs/', 'C1', 'độ cứng; độ chắc; sự kiên định; sự quả quyết', 'n.', 'firm (adj.), firmly (adv.)', 'Đồng nghĩa: solidity, resolve · Trái nghĩa: softness, indecision', 'Là danh từ không đếm được; có thể chỉ độ cứng chắc của vật thể hoặc ý chí kiên định.', 'Press the mattress gently to check its firmness.', NULL, 'Hãy ấn nhẹ vào đệm để kiểm tra độ cứng của nó.', '{"wordId":"firmness","ukIpa":"/ˈfɜːmnəs/","usIpa":"/ˈfɜːrmnəs/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"the quality of resisting pressure rather than being soft","vi":"độ cứng; độ chắc"},{"pos":"n.","en":"the quality of staying determined and not easily changing decisions","vi":"sự kiên định; sự quả quyết"}],"examples":[{"en":"Press the mattress gently to check its firmness.","vi":"Hãy ấn nhẹ vào đệm để kiểm tra độ cứng của nó.","audioKind":"ex"},{"en":"Teachers can maintain classroom discipline through calm firmness without discouraging students from expressing their opinions openly.","vi":"Giáo viên có thể duy trì kỷ luật lớp học thông qua thái độ bình tĩnh nhưng kiên định mà không làm học sinh nhụt chí trong việc cởi mở bày tỏ ý kiến.","audioKind":"ex2"}],"collocations":[{"en":"mattress firmness","vi":"độ cứng của đệm"},{"en":"firmness of purpose","vi":"sự kiên định trong mục tiêu"},{"en":"show firmness","vi":"thể hiện thái độ kiên quyết"}],"wordFamily":["firm (adj.)","firmly (adv.)"],"synonyms":["solidity","resolve"],"antonyms":["softness","indecision"],"tipVi":"Là danh từ không đếm được; có thể chỉ độ cứng chắc của vật thể hoặc ý chí kiên định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clothe', 'en-c1-63', 'clothe', '/kloʊð/', 'C1', 'mặc quần áo cho ai; cung cấp quần áo', 'v.', 'clothes (n.), clothing (n.), clothed (adj.)', 'Đồng nghĩa: dress · Trái nghĩa: undress', 'Thuộc văn phong trang trọng; dạng quá khứ và phân từ hai thường là clothed.', 'The charity helps feed and clothe families during winter.', NULL, 'Tổ chức từ thiện giúp cung cấp thức ăn và quần áo cho các gia đình trong mùa đông.', '{"wordId":"clothe","ukIpa":"/kləʊð/","usIpa":"/kloʊð/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To dress someone or provide them with clothes","vi":"mặc quần áo cho ai; cung cấp quần áo"}],"examples":[{"en":"The charity helps feed and clothe families during winter.","vi":"Tổ chức từ thiện giúp cung cấp thức ăn và quần áo cho các gia đình trong mùa đông.","audioKind":"ex"},{"en":"Low wages can make it difficult for parents to feed and clothe their children adequately.","vi":"Mức lương thấp có thể khiến các bậc cha mẹ gặp khó khăn trong việc lo cho con cái đủ ăn đủ mặc.","audioKind":"ex2"}],"collocations":[{"en":"feed and clothe","vi":"nuôi ăn và mặc"},{"en":"clothe someone in wool","vi":"mặc đồ bằng len cho ai"}],"wordFamily":["clothes (n.)","clothing (n.)","clothed (adj.)"],"synonyms":["dress"],"antonyms":["undress"],"tipVi":"Thuộc văn phong trang trọng; dạng quá khứ và phân từ hai thường là clothed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shapeless', 'en-c1-63', 'shapeless', '/ˈʃeɪpləs/', 'C1', 'mất dáng; không có hình thù rõ ràng; thùng thình', 'adj.', 'shape (n.), shape (v.), shapely (adj.)', 'Đồng nghĩa: formless', 'Khi miêu tả trang phục, từ này thường chỉ quần áo rộng thênh thang, không có đường cắt may rõ nét.', 'My old sweater became shapeless after too many washes.', NULL, 'Chiếc áo len cũ của tôi đã trở nên mất form sau quá nhiều lần giặt.', '{"wordId":"shapeless","ukIpa":"/ˈʃeɪpləs/","usIpa":"/ˈʃeɪpləs/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Having no clear or definite shape","vi":"mất dáng; không có hình thù rõ ràng; thùng thình"}],"examples":[{"en":"My old sweater became shapeless after too many washes.","vi":"Chiếc áo len cũ của tôi đã trở nên mất form sau quá nhiều lần giặt.","audioKind":"ex"},{"en":"Without careful planning, expanding cities can become shapeless areas lacking distinct neighbourhoods and accessible public spaces.","vi":"Nếu thiếu quy hoạch cẩn thận, các thành phố đang mở rộng có thể trở nên lộn xộn, thiếu vắng các khu phố đặc trưng và không gian công cộng tiện lợi.","audioKind":"ex2"}],"collocations":[{"en":"a shapeless mass","vi":"một khối hỗn độn không rõ hình thù"},{"en":"a shapeless dress","vi":"chiếc đầm suông rộng không rõ đường nét"},{"en":"become shapeless","vi":"trở nên mất dáng"}],"wordFamily":["shape (n.)","shape (v.)","shapely (adj.)"],"synonyms":["formless"],"antonyms":[],"tipVi":"Khi miêu tả trang phục, từ này thường chỉ quần áo rộng thênh thang, không có đường cắt may rõ nét.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appreciably', 'en-c1-63', 'appreciably', '/əˈpriːʃəbli/', 'C1', 'đáng kể; rõ rệt', 'adv.', 'appreciable (adj.)', 'Đồng nghĩa: noticeably, significantly · Trái nghĩa: imperceptibly', 'Biểu thị mức độ thay đổi lớn đến mức có thể nhận thấy rõ, không mang nghĩa là "biết ơn".', 'The room felt appreciably warmer after we closed the window.', NULL, 'Căn phòng bỗng ấm lên đáng kể sau khi chúng tôi đóng cửa sổ lại.', '{"wordId":"appreciably","ukIpa":"/əˈpriːʃəbli/","usIpa":"/əˈpriːʃəbli/","cefr":"C1","topic":"daily","senses":[{"pos":"adv.","en":"by an amount that is large enough to notice","vi":"đáng kể; rõ rệt"}],"examples":[{"en":"The room felt appreciably warmer after we closed the window.","vi":"Căn phòng bỗng ấm lên đáng kể sau khi chúng tôi đóng cửa sổ lại.","audioKind":"ex"},{"en":"Expanding reliable public transport could appreciably reduce traffic congestion and improve air quality in urban areas.","vi":"Việc mở rộng mạng lưới giao thông công cộng đáng tin cậy có thể làm giảm đáng kể tình trạng tắc nghẽn giao thông và cải thiện chất lượng không khí ở các khu đô thị.","audioKind":"ex2"}],"collocations":[{"en":"appreciably higher","vi":"cao hơn đáng kể"},{"en":"appreciably reduce","vi":"giảm đáng kể"},{"en":"differ appreciably","vi":"khác biệt đáng kể"}],"wordFamily":["appreciable (adj.)"],"synonyms":["noticeably","significantly"],"antonyms":["imperceptibly"],"tipVi":"Biểu thị mức độ thay đổi lớn đến mức có thể nhận thấy rõ, không mang nghĩa là \"biết ơn\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dangle', 'en-c1-63', 'dangle', '/ˈdæŋɡəl/', 'C1', 'lủng lẳng; treo lơ lửng; dùng lợi ích để dụ dỗ; đưa ra mồi nhử', 'v.', 'dangling (adj.)', 'Đồng nghĩa: hang', 'Ý nghĩa cốt lõi là treo lơ lửng, có thể đi kèm chuyển động lắc lư; không phải mọi hành động lúc lắc đều dùng từ này.', 'Her feet dangled above the floor from the high chair.', NULL, 'Đôi chân của cô bé lủng lẳng ở chiếc ghế cao phía trên mặt sàn.', '{"wordId":"dangle","ukIpa":"/ˈdæŋɡəl/","usIpa":"/ˈdæŋɡəl/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to hang loosely, or make something hang loosely","vi":"lủng lẳng; treo lơ lửng"},{"pos":"v.","en":"to offer something attractive to persuade someone to act","vi":"dùng lợi ích để dụ dỗ; đưa ra mồi nhử"}],"examples":[{"en":"Her feet dangled above the floor from the high chair.","vi":"Đôi chân của cô bé lủng lẳng ở chiếc ghế cao phía trên mặt sàn.","audioKind":"ex"},{"en":"Some employers dangle generous bonuses before applicants while offering limited opportunities for long-term career development.","vi":"Một số nhà tuyển dụng đưa ra những khoản tiền thưởng hậu hĩnh để dụ dỗ ứng viên trong khi lại cung cấp rất ít cơ hội phát triển sự nghiệp lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"dangle from","vi":"treo lủng lẳng từ"},{"en":"dangle your feet","vi":"lắc lư đôi chân"},{"en":"dangle a carrot","vi":"dụ dỗ bằng lợi ích"}],"wordFamily":["dangling (adj.)"],"synonyms":["hang"],"antonyms":[],"tipVi":"Ý nghĩa cốt lõi là treo lơ lửng, có thể đi kèm chuyển động lắc lư; không phải mọi hành động lúc lắc đều dùng từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recapture', 'en-c1-63', 'recapture', '/ˌriːˈkæptʃər/', 'C1', 'bắt lại; chiếm lại; lấy lại; lấy lại cảm xúc; tái hiện lại trải nghiệm; hành động bắt lại; sự chiếm lại', 'v.', 'capture (v.), capture (n.)', 'Đồng nghĩa: retake, regain', 'Có thể dùng để chỉ việc bắt giữ lại, hoặc gợi nhắc lại cảm xúc, nét đặc trưng trong quá khứ.', 'The farmer recaptured the goat beside our garden gate.', NULL, 'Người nông dân đã bắt lại con dê ở cạnh cổng vườn của chúng tôi.', '{"wordId":"recapture","ukIpa":"/ˌriːˈkæptʃə/","usIpa":"/ˌriːˈkæptʃər/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To catch again or regain control of something","vi":"bắt lại; chiếm lại; lấy lại"},{"pos":"v.","en":"To experience or produce a past feeling or quality again","vi":"lấy lại cảm xúc; tái hiện lại trải nghiệm"},{"pos":"n.","en":"The act of catching something or taking control again","vi":"hành động bắt lại; sự chiếm lại"}],"examples":[{"en":"The farmer recaptured the goat beside our garden gate.","vi":"Người nông dân đã bắt lại con dê ở cạnh cổng vườn của chúng tôi.","audioKind":"ex"},{"en":"Restoring historic buildings can help cities recapture their distinctive character while creating new opportunities for tourism.","vi":"Việc phục hồi các tòa nhà lịch sử có thể giúp các thành phố tái hiện lại nét đặc trưng riêng biệt của mình đồng thời tạo ra những cơ hội mới cho ngành du lịch.","audioKind":"ex2"}],"collocations":[{"en":"recapture an escaped animal","vi":"bắt lại con vật sổng chuồng"},{"en":"recapture the excitement","vi":"lấy lại sự hào hứng"},{"en":"recapture the atmosphere","vi":"tái hiện lại bầu không khí"},{"en":"recapture market share","vi":"giành lại thị phần"}],"wordFamily":["capture (v.)","capture (n.)"],"synonyms":["retake","regain"],"antonyms":[],"tipVi":"Có thể dùng để chỉ việc bắt giữ lại, hoặc gợi nhắc lại cảm xúc, nét đặc trưng trong quá khứ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brandy', 'en-c1-63', 'brandy', '/ˈbrændi/', 'C1', 'rượu mạnh branti; rượu brandy', 'n.', NULL, NULL, 'Thông thường đây là danh từ không đếm được; tuy nhiên, "a brandy" có thể dùng để chỉ một ly rượu brandy.', 'The recipe includes a little brandy in the fruit cake.', NULL, 'Công thức món bánh trái cây có cho thêm một chút rượu brandy.', '{"wordId":"brandy","ukIpa":"/ˈbrændi/","usIpa":"/ˈbrændi/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A strong alcoholic drink distilled from wine or fermented fruit juice.","vi":"rượu mạnh branti; rượu brandy"}],"examples":[{"en":"The recipe includes a little brandy in the fruit cake.","vi":"Công thức món bánh trái cây có cho thêm một chút rượu brandy.","audioKind":"ex"},{"en":"Traditional brandy production can support rural employment by creating demand for locally grown grapes and specialist skills.","vi":"Sản xuất rượu brandy truyền thống có thể hỗ trợ việc làm ở vùng nông thôn bằng cách tạo ra nhu cầu đối với nho trồng tại địa phương và các kỹ năng chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"a glass of brandy","vi":"một ly rượu brandy"},{"en":"aged brandy","vi":"rượu brandy lâu năm"},{"en":"brandy production","vi":"sản xuất rượu brandy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thông thường đây là danh từ không đếm được; tuy nhiên, \"a brandy\" có thể dùng để chỉ một ly rượu brandy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_living-quarter', 'en-c1-63', 'living quarters', '/ˈlɪvɪŋ ˌkwɔːrtərz/', 'C1', 'chỗ ở; nơi sinh sống; khu gia binh/khu tập thể', 'n.', NULL, 'Đồng nghĩa: accommodation', 'Khi chỉ chỗ ở, luôn dùng dạng số nhiều living quarters và động từ đi kèm cũng ở số nhiều.', 'Our living quarters were small but warm and comfortable.', NULL, 'Chỗ ở của chúng tôi tuy nhỏ nhưng ấm cúng và thoải mái.', '{"wordId":"living-quarter","ukIpa":"/ˈlɪvɪŋ ˌkwɔːtəz/","usIpa":"/ˈlɪvɪŋ ˌkwɔːrtərz/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"Rooms or buildings where people live","vi":"chỗ ở; nơi sinh sống; khu gia binh/khu tập thể"}],"examples":[{"en":"Our living quarters were small but warm and comfortable.","vi":"Chỗ ở của chúng tôi tuy nhỏ nhưng ấm cúng và thoải mái.","audioKind":"ex"},{"en":"Employers should provide safe living quarters for seasonal workers, particularly in remote agricultural regions with limited housing.","vi":"Người sử dụng lao động nên cung cấp chỗ ở an toàn cho lao động thời vụ, đặc biệt là ở những vùng nông nghiệp hẻo lánh có nhà ở hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"cramped living quarters","vi":"chỗ ở chật chội"},{"en":"staff living quarters","vi":"ký túc xá nhân viên"},{"en":"shared living quarters","vi":"nơi ở chung"}],"wordFamily":[],"synonyms":["accommodation"],"antonyms":[],"tipVi":"Khi chỉ chỗ ở, luôn dùng dạng số nhiều living quarters và động từ đi kèm cũng ở số nhiều.","noteVi":"Đã chuyển từ living quarter sang dạng thông dụng living quarters.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_redeem', 'en-c1-63', 'redeem', '/rɪˈdiːm/', 'C1', 'đổi (phiếu, điểm thưởng) lấy hàng hóa, dịch vụ hoặc tiền; bù đắp cho thất bại; lấy lại/phục hồi uy tín; chuộc lại (đồ cầm cố)', 'v.', 'redemption (n.), redeemable (adj.), redeeming (adj.)', NULL, 'Cấu trúc redeem A for B có nghĩa là dùng A (như phiếu hoặc điểm) để đổi lấy B.', 'You can redeem this voucher for a free lunch.', NULL, 'Bạn có thể dùng phiếu giảm giá này để đổi lấy một bữa trưa miễn phí.', '{"wordId":"redeem","ukIpa":"/rɪˈdiːm/","usIpa":"/rɪˈdiːm/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"exchange a voucher or points for goods, services, or money","vi":"đổi (phiếu, điểm thưởng) lấy hàng hóa, dịch vụ hoặc tiền"},{"pos":"v.","en":"make up for a failure or restore a good reputation","vi":"bù đắp cho thất bại; lấy lại/phục hồi uy tín"},{"pos":"v.","en":"recover something by paying the money owed on it","vi":"chuộc lại (đồ cầm cố)"}],"examples":[{"en":"You can redeem this voucher for a free lunch.","vi":"Bạn có thể dùng phiếu giảm giá này để đổi lấy một bữa trưa miễn phí.","audioKind":"ex"},{"en":"Retailers increasingly allow customers to redeem loyalty points for products made from recycled materials.","vi":"Các nhà bán lẻ ngày càng tạo điều kiện cho khách hàng dùng điểm tích lũy thành viên để đổi lấy các sản phẩm làm từ vật liệu tái chế.","audioKind":"ex2"}],"collocations":[{"en":"redeem a voucher","vi":"đổi phiếu mua hàng"},{"en":"redeem points","vi":"đổi điểm thưởng"},{"en":"redeem yourself","vi":"tự chuộc lỗi / lấy lại danh dự"},{"en":"redeeming feature","vi":"điểm sáng đáng khen"}],"wordFamily":["redemption (n.)","redeemable (adj.)","redeeming (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc redeem A for B có nghĩa là dùng A (như phiếu hoặc điểm) để đổi lấy B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disarray', 'en-c1-63', 'disarray', '/ˌdɪsəˈreɪ/', 'C1', 'tình trạng hỗn loạn; sự bừa bộn', 'n.', NULL, 'Đồng nghĩa: disorder, confusion, chaos · Trái nghĩa: order', 'Thường dùng làm danh từ không đếm được, cụm từ ''in disarray'' có nghĩa là đang ở trong tình trạng hỗn loạn.', 'The kitchen was in disarray after our baking afternoon.', NULL, 'Căn bếp trở nên bừa bộn sau buổi chiều chúng tôi làm bánh.', '{"wordId":"disarray","ukIpa":"/ˌdɪsəˈreɪ/","usIpa":"/ˌdɪsəˈreɪ/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A state of disorder or lack of organisation.","vi":"tình trạng hỗn loạn; sự bừa bộn"}],"examples":[{"en":"The kitchen was in disarray after our baking afternoon.","vi":"Căn bếp trở nên bừa bộn sau buổi chiều chúng tôi làm bánh.","audioKind":"ex"},{"en":"Without clear leadership, emergency planning can fall into disarray, leaving communities poorly prepared for extreme weather.","vi":"Nếu thiếu sự lãnh đạo rõ ràng, kế hoạch ứng phó khẩn cấp có thể rơi vào tình trạng hỗn loạn, khiến cộng đồng không chuẩn bị chu đáo để đối phó với thời tiết cực đoan.","audioKind":"ex2"}],"collocations":[{"en":"in disarray","vi":"ở trong tình trạng hỗn loạn"},{"en":"throw into disarray","vi":"làm cho hỗn loạn"},{"en":"complete disarray","vi":"sự hỗn loạn hoàn toàn"}],"wordFamily":[],"synonyms":["disorder","confusion","chaos"],"antonyms":["order"],"tipVi":"Thường dùng làm danh từ không đếm được, cụm từ ''in disarray'' có nghĩa là đang ở trong tình trạng hỗn loạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lukewarm', 'en-c1-63', 'lukewarm', '/ˌluːkˈwɔːrm/', 'C1', 'âm ấm; hơi ấm; lạnh nhạt; không nhiệt tình', 'adj.', 'lukewarmness (n.)', 'Đồng nghĩa: tepid · Trái nghĩa: hot, enthusiastic', 'Có thể dùng để chỉ nhiệt độ hơi ấm, hoặc dùng theo nghĩa bóng để chỉ thái độ lạnh nhạt.', 'My soup was lukewarm by the time I sat down.', NULL, 'Món súp của tôi đã nguội ngắt khi tôi ngồi xuống bàn.', '{"wordId":"lukewarm","ukIpa":"/ˌluːkˈwɔːm/","usIpa":"/ˌluːkˈwɔːrm/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Only slightly warm, sometimes cooler than desired.","vi":"âm ấm; hơi ấm"},{"pos":"adj.","en":"Showing little enthusiasm or support.","vi":"lạnh nhạt; không nhiệt tình"}],"examples":[{"en":"My soup was lukewarm by the time I sat down.","vi":"Món súp của tôi đã nguội ngắt khi tôi ngồi xuống bàn.","audioKind":"ex"},{"en":"The proposal received a lukewarm response from residents, who doubted whether it would improve public transport.","vi":"Đề xuất này nhận được sự hưởng ứng lạnh nhạt từ cư dân, những người hoài nghi về việc liệu nó có cải thiện được giao thông công cộng hay không.","audioKind":"ex2"}],"collocations":[{"en":"lukewarm water","vi":"nước ấm"},{"en":"lukewarm response","vi":"phản ứng lạnh nhạt"},{"en":"lukewarm support","vi":"sự ủng hộ hời hợt"}],"wordFamily":["lukewarmness (n.)"],"synonyms":["tepid"],"antonyms":["hot","enthusiastic"],"tipVi":"Có thể dùng để chỉ nhiệt độ hơi ấm, hoặc dùng theo nghĩa bóng để chỉ thái độ lạnh nhạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pellet', 'en-c1-63', 'pellet', '/ˈpelɪt/', 'C1', 'viên nhỏ; hạt nén', 'n.', NULL, 'Đồng nghĩa: granule', 'Chỉ các vật thể nhỏ được nén thành viên, thường thấy ở thức ăn chăn nuôi hoặc chất đốt.', 'Each rabbit received a few food pellets with fresh vegetables.', NULL, 'Mỗi chú thỏ được nhận một ít thức ăn dạng viên cùng với rau tươi.', '{"wordId":"pellet","ukIpa":"/ˈpelɪt/","usIpa":"/ˈpelɪt/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A small, rounded or cylindrical piece of compressed material.","vi":"viên nhỏ; hạt nén"}],"examples":[{"en":"Each rabbit received a few food pellets with fresh vegetables.","vi":"Mỗi chú thỏ được nhận một ít thức ăn dạng viên cùng với rau tươi.","audioKind":"ex"},{"en":"Heating systems that burn wood pellets can reduce reliance on fossil fuels when the wood is sustainably sourced.","vi":"Các hệ thống sưởi ấm đốt viên gỗ có thể làm giảm sự phụ thuộc vào nhiên liệu hóa thạch khi nguồn gỗ được khai thác một cách bền vững.","audioKind":"ex2"}],"collocations":[{"en":"wood pellets","vi":"viên gỗ đốt"},{"en":"food pellets","vi":"thức ăn dạng hạt"},{"en":"plastic pellets","vi":"hạt nhựa"}],"wordFamily":[],"synonyms":["granule"],"antonyms":[],"tipVi":"Chỉ các vật thể nhỏ được nén thành viên, thường thấy ở thức ăn chăn nuôi hoặc chất đốt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bulky', 'en-c1-63', 'bulky', '/ˈbʌlki/', 'C1', 'cồng kềnh; to lớn vướng víu', 'adj.', 'bulk (n.), bulkiness (n.)', 'Đồng nghĩa: unwieldy · Trái nghĩa: compact', 'bulky nhấn mạnh thể tích lớn, tốn diện tích, chứ không nhất thiết phải quá nặng.', 'This bulky suitcase barely fits inside the small cupboard.', NULL, 'Chiếc vali cồng kềnh này hầu như không thể nhét vừa vào chiếc tủ nhỏ.', '{"wordId":"bulky","ukIpa":"/ˈbʌlki/","usIpa":"/ˈbʌlki/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Large and awkward to carry, move, or store.","vi":"cồng kềnh; to lớn vướng víu"}],"examples":[{"en":"This bulky suitcase barely fits inside the small cupboard.","vi":"Chiếc vali cồng kềnh này hầu như không thể nhét vừa vào chiếc tủ nhỏ.","audioKind":"ex"},{"en":"Compact furniture is increasingly popular because bulky items can make small urban apartments feel overcrowded.","vi":"Nội thất gọn nhẹ ngày càng phổ biến vì những món đồ cồng kềnh có thể khiến các căn hộ đô thị nhỏ trở nên chật chội.","audioKind":"ex2"}],"collocations":[{"en":"bulky furniture","vi":"đồ nội thất cồng kềnh"},{"en":"bulky items","vi":"hàng hóa cồng kềnh"},{"en":"bulky equipment","vi":"thiết bị cồng kềnh"}],"wordFamily":["bulk (n.)","bulkiness (n.)"],"synonyms":["unwieldy"],"antonyms":["compact"],"tipVi":"bulky nhấn mạnh thể tích lớn, tốn diện tích, chứ không nhất thiết phải quá nặng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_troublesome', 'en-c1-63', 'troublesome', '/ˈtrʌblsəm/', 'C1', 'gây phiền toái; rắc rối; khó chịu', 'adj.', 'trouble (n.), troubled (adj.)', 'Đồng nghĩa: problematic, bothersome', 'Troublesome dùng để chỉ sự việc gây ra rắc rối; trong khi troubled dùng để chỉ bản thân ai đó đang gặp rắc rối, ưu tư.', 'This troublesome lock jams whenever the weather turns cold.', NULL, 'Ổ khóa phiền phức này cứ hễ thời tiết trở lạnh là lại bị kẹt cứng.', '{"wordId":"troublesome","ukIpa":"/ˈtrʌblsəm/","usIpa":"/ˈtrʌblsəm/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"causing problems, difficulty, or annoyance","vi":"gây phiền toái; rắc rối; khó chịu"}],"examples":[{"en":"This troublesome lock jams whenever the weather turns cold.","vi":"Ổ khóa phiền phức này cứ hễ thời tiết trở lạnh là lại bị kẹt cứng.","audioKind":"ex"},{"en":"Unreliable public transport is particularly troublesome for workers who depend on buses to reach jobs outside city centres.","vi":"Hệ thống giao thông công cộng kém tin cậy là điều vô cùng phiền toái đối với những người lao động phụ thuộc vào xe buýt để đến nơi làm việc ngoài khu vực trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"a troublesome issue","vi":"một vấn đề nan giải"},{"en":"a troublesome cough","vi":"cơn ho dai dẳng khó chịu"},{"en":"particularly troublesome","vi":"đặc biệt phiền toái"}],"wordFamily":["trouble (n.)","troubled (adj.)"],"synonyms":["problematic","bothersome"],"antonyms":[],"tipVi":"Troublesome dùng để chỉ sự việc gây ra rắc rối; trong khi troubled dùng để chỉ bản thân ai đó đang gặp rắc rối, ưu tư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intermittent', 'en-c1-63', 'intermittent', '/ˌɪntərˈmɪtənt/', 'C1', 'ngắt quãng; gián đoạn; lúc có lúc không', 'adj.', 'intermittently (adv.), intermittency (n.)', 'Đồng nghĩa: sporadic · Trái nghĩa: continuous, constant', 'Nhấn mạnh tính chất lúc dừng lúc chạy, không nhất thiết phải theo một chu kỳ thời gian cố định.', 'Intermittent rain kept us running indoors throughout the afternoon.', NULL, 'Những trận mưa lúc tạnh lúc rơi cứ kéo dài suốt cả buổi chiều khiến chúng tôi phải chạy liên tục vào nhà.', '{"wordId":"intermittent","ukIpa":"/ˌɪntəˈmɪtənt/","usIpa":"/ˌɪntərˈmɪtənt/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Stopping and starting repeatedly rather than continuing without a break.","vi":"ngắt quãng; gián đoạn; lúc có lúc không"}],"examples":[{"en":"Intermittent rain kept us running indoors throughout the afternoon.","vi":"Những trận mưa lúc tạnh lúc rơi cứ kéo dài suốt cả buổi chiều khiến chúng tôi phải chạy liên tục vào nhà.","audioKind":"ex"},{"en":"Intermittent internet access can prevent rural students from participating fully in online learning programmes.","vi":"Đường truyền internet chập chờn, ngắt quãng có thể cản trở học sinh vùng nông thôn tham gia đầy đủ vào các chương trình học trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"intermittent rain","vi":"mưa rào ngắt quãng"},{"en":"intermittent supply","vi":"nguồn cung cấp chập chờn"},{"en":"intermittent noise","vi":"tiếng ồn gián đoạn"}],"wordFamily":["intermittently (adv.)","intermittency (n.)"],"synonyms":["sporadic"],"antonyms":["continuous","constant"],"tipVi":"Nhấn mạnh tính chất lúc dừng lúc chạy, không nhất thiết phải theo một chu kỳ thời gian cố định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amidst', 'en-c1-63', 'amidst', '/əˈmɪdst/', 'C1', 'ở giữa; giữa (trong một hoàn cảnh nào đó)', 'prep.', NULL, 'Đồng nghĩa: amid, among', 'Đồng nghĩa với amid, có văn phong trang trọng hơn; theo sau là danh từ hoặc cụm danh từ.', 'We found a quiet bench amidst the flowering trees.', NULL, 'Chúng tôi tìm thấy một chiếc ghế băng yên tĩnh nằm giữa những tán cây đang nở hoa.', '{"wordId":"amidst","ukIpa":"/əˈmɪdst/","usIpa":"/əˈmɪdst/","cefr":"C1","topic":"daily","senses":[{"pos":"prep.","en":"Surrounded by something, or during a particular situation","vi":"ở giữa; giữa (trong một hoàn cảnh nào đó)"}],"examples":[{"en":"We found a quiet bench amidst the flowering trees.","vi":"Chúng tôi tìm thấy một chiếc ghế băng yên tĩnh nằm giữa những tán cây đang nở hoa.","audioKind":"ex"},{"en":"Amidst growing concerns about air quality, several cities have expanded their networks of protected cycle lanes.","vi":"Giữa lúc những lo ngại ngày càng tăng về chất lượng không khí, một số thành phố đã mở rộng mạng lưới làn đường dành riêng cho xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"amidst uncertainty","vi":"giữa sự bất định"},{"en":"amidst growing concerns","vi":"giữa những lo ngại ngày càng tăng"},{"en":"amidst the chaos","vi":"giữa vòng hỗn loạn"}],"wordFamily":[],"synonyms":["amid","among"],"antonyms":[],"tipVi":"Đồng nghĩa với amid, có văn phong trang trọng hơn; theo sau là danh từ hoặc cụm danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scant', 'en-c1-63', 'scant', '/skænt/', 'C1', 'ít ỏi; thiếu thốn', 'adj.', 'scanty (adj.), scantily (adv.)', 'Đồng nghĩa: meagre, insufficient · Trái nghĩa: ample, abundant', 'Nhấn mạnh số lượng quá ít không đủ dùng, thường đứng trước danh từ như scant evidence.', 'We had scant time to pack before the taxi arrived.', NULL, 'Chúng tôi có rất ít thời gian để sắp xếp hành lý trước khi taxi đến.', '{"wordId":"scant","ukIpa":"/skænt/","usIpa":"/skænt/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"barely enough, or less than is needed","vi":"ít ỏi; thiếu thốn"}],"examples":[{"en":"We had scant time to pack before the taxi arrived.","vi":"Chúng tôi có rất ít thời gian để sắp xếp hành lý trước khi taxi đến.","audioKind":"ex"},{"en":"There is scant evidence that longer working hours consistently lead to higher productivity across different industries.","vi":"Có rất ít bằng chứng cho thấy việc kéo dài thời gian làm việc liên tục mang lại năng suất cao hơn ở các ngành nghề khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"scant evidence","vi":"bằng chứng ít ỏi"},{"en":"scant attention","vi":"sự quan tâm ít ỏi"},{"en":"scant regard for","vi":"sự phớt lờ đối với"}],"wordFamily":["scanty (adj.)","scantily (adv.)"],"synonyms":["meagre","insufficient"],"antonyms":["ample","abundant"],"tipVi":"Nhấn mạnh số lượng quá ít không đủ dùng, thường đứng trước danh từ như scant evidence.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hasten', 'en-c1-63', 'hasten', '/ˈheɪsən/', 'C1', 'làm nhanh hơn; đẩy nhanh; thúc đẩy; vội vã; khẩn trương hành động', 'v.', 'haste (n.), hasty (adj.), hastily (adv.)', 'Đồng nghĩa: accelerate, hurry · Trái nghĩa: delay', 'Chữ t không phát âm; cụm hasten to do diễn tả việc nhanh chóng làm điều gì đó.', 'The warm sunshine hastened the melting of the snow.', NULL, 'Ánh nắng ấm áp đã làm tuyết tan nhanh hơn.', '{"wordId":"hasten","ukIpa":"/ˈheɪsən/","usIpa":"/ˈheɪsən/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To make something happen sooner or develop more quickly.","vi":"làm nhanh hơn; đẩy nhanh; thúc đẩy"},{"pos":"v.","en":"To move or act quickly, often because something is urgent.","vi":"vội vã; khẩn trương hành động"}],"examples":[{"en":"The warm sunshine hastened the melting of the snow.","vi":"Ánh nắng ấm áp đã làm tuyết tan nhanh hơn.","audioKind":"ex"},{"en":"Investment in renewable energy could hasten the transition towards a more sustainable and resilient economy.","vi":"Việc đầu tư vào năng lượng tái tạo có thể đẩy nhanh quá trình chuyển đổi sang một nền kinh tế bền vững và có khả năng chống chịu tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"hasten recovery","vi":"đẩy nhanh sự hồi phục"},{"en":"hasten the process","vi":"đẩy nhanh tiến trình"},{"en":"hasten to add","vi":"vội vã bổ sung rằng"}],"wordFamily":["haste (n.)","hasty (adj.)","hastily (adv.)"],"synonyms":["accelerate","hurry"],"antonyms":["delay"],"tipVi":"Chữ t không phát âm; cụm hasten to do diễn tả việc nhanh chóng làm điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slit', 'en-c1-63', 'slit', '/slɪt/', 'C1', 'khe hở; đường rạch hẹp; cắt khe hở; rạch một đường hẹp', 'n.', NULL, NULL, 'Dạng quá khứ và quá khứ phân từ đều là slit; hiện phân từ là slitting.', 'Sunlight came through a narrow slit in the curtains.', NULL, 'Ánh sáng chiếu qua khe hở nhỏ giữa các lớp rèm cửa.', '{"wordId":"slit","ukIpa":"/slɪt/","usIpa":"/slɪt/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"a long, narrow cut or opening","vi":"khe hở; đường rạch hẹp"},{"pos":"v.","en":"to make a long, narrow cut in something","vi":"cắt khe hở; rạch một đường hẹp"}],"examples":[{"en":"Sunlight came through a narrow slit in the curtains.","vi":"Ánh sáng chiếu qua khe hở nhỏ giữa các lớp rèm cửa.","audioKind":"ex"},{"en":"A narrow slit in the laboratory screen allows researchers to observe how light behaves when passing through small openings.","vi":"Một khe hở hẹp trên màn chắn trong phòng thí nghiệm giúp các nhà nghiên cứu quan sát hiện tượng ánh sáng chuyển động khi đi qua các lỗ nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"a narrow slit","vi":"một khe hở hẹp"},{"en":"slit open an envelope","vi":"rạch mở một phong bì"},{"en":"a slit in the fabric","vi":"đường rạch trên vải"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là slit; hiện phân từ là slitting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thrust', 'en-c1-63', 'thrust', '/θrʌst/', 'C1', 'thọc; nhét mạnh; đẩy; lực đẩy; trọng tâm; ý chính', 'v.', NULL, 'Đồng nghĩa: push, shove', 'Dạng quá khứ và phân từ hai của thrust đều giữ nguyên là thrust; trọng tâm của một việc thường dùng the thrust of.', 'He thrust his hands deep into his coat pockets.', NULL, 'Anh ấy thọc sâu hai tay vào túi áo khoác.', '{"wordId":"thrust","ukIpa":"/θrʌst/","usIpa":"/θrʌst/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to push something suddenly and forcefully","vi":"thọc; nhét mạnh; đẩy"},{"pos":"n.","en":"a strong push or force that moves something forward","vi":"lực đẩy"},{"pos":"n.","en":"the main idea or purpose of an argument or activity","vi":"trọng tâm; ý chính"}],"examples":[{"en":"He thrust his hands deep into his coat pockets.","vi":"Anh ấy thọc sâu hai tay vào túi áo khoác.","audioKind":"ex"},{"en":"The main thrust of the proposal is to improve public transport rather than build additional roads.","vi":"Trọng tâm chính của bản đề xuất là cải thiện giao thông công cộng thay vì xây thêm đường xá.","audioKind":"ex2"}],"collocations":[{"en":"thrust something into","vi":"nhét cái gì vào đâu"},{"en":"engine thrust","vi":"lực đẩy của động cơ"},{"en":"the main thrust of","vi":"trọng tâm chính của"}],"wordFamily":[],"synonyms":["push","shove"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai của thrust đều giữ nguyên là thrust; trọng tâm của một việc thường dùng the thrust of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_63_1', 'en-c1-63', 'Cách dùng “reel” (n.) — cuộn; ống cuộn', 'a reel of film  ·  a fishing reel  ·  reel from the shock', 'Cụm reel from dùng để chỉ việc chịu ảnh hưởng nặng nề, trong khi reel off có nghĩa là đọc hoặc liệt kê một mạch không ngừng.', 'Đồng nghĩa: spool, stagger', '[{"hanzi":"She wound the loose fishing line onto the reel.","pinyin":"","meaning":"Cô ấy quấn đoạn dây câu bị chùng vào ống cuộn."},{"hanzi":"Local businesses continued to reel from the sudden closure of the region''s largest factory.","pinyin":"","meaning":"Các doanh nghiệp địa phương vẫn tiếp tục điêu đứng trước việc đóng cửa đột ngột của nhà máy lớn nhất vùng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_63_2', 'en-c1-63', 'Cách dùng “waken” (v.) — thức giấc; đánh thức', 'waken someone from sleep  ·  waken at dawn  ·  waken to birdsong', 'Từ này ít phổ biến và mang tính văn phong trang trọng hơn so với wake; dạng quá khứ và quá khứ phân từ đều là wakened.', 'Họ từ (Word Family): wake (v.), awake (adj.), awakening (n.) | Đồng nghĩa: wake, awaken', '[{"hanzi":"Birdsong wakened me before the sun came up.","pinyin":"","meaning":"Tiếng chim hót đã đánh thức tôi dậy trước khi mặt trời mọc."},{"hanzi":"Residents living near airports may be wakened repeatedly by aircraft noise, which can affect their overall health.","pinyin":"","meaning":"Những cư dân sống gần sân bay có thể bị tiếng ồn máy bay làm cho thức giấc nhiều lần, điều này có thể ảnh hưởng đến sức khỏe tổng thể của họ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_63_3', 'en-c1-63', 'Cách dùng “troublesome” (adj.) — gây phiền toái; rắc rối; khó chịu', 'a troublesome issue  ·  a troublesome cough  ·  particularly troublesome', 'Troublesome dùng để chỉ sự việc gây ra rắc rối; trong khi troubled dùng để chỉ bản thân ai đó đang gặp rắc rối, ưu tư.', 'Họ từ (Word Family): trouble (n.), troubled (adj.) | Đồng nghĩa: problematic, bothersome', '[{"hanzi":"This troublesome lock jams whenever the weather turns cold.","pinyin":"","meaning":"Ổ khóa phiền phức này cứ hễ thời tiết trở lạnh là lại bị kẹt cứng."},{"hanzi":"Unreliable public transport is particularly troublesome for workers who depend on buses to reach jobs outside city centres.","pinyin":"","meaning":"Hệ thống giao thông công cộng kém tin cậy là điều vô cùng phiền toái đối với những người lao động phụ thuộc vào xe buýt để đến nơi làm việc ngoài khu vực trung tâm thành phố."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_63_4', 'en-c1-63', 'Cách dùng “dangle” (v.) — lủng lẳng; treo lơ lửng', 'dangle from  ·  dangle your feet  ·  dangle a carrot', 'Ý nghĩa cốt lõi là treo lơ lửng, có thể đi kèm chuyển động lắc lư; không phải mọi hành động lúc lắc đều dùng từ này.', 'Họ từ (Word Family): dangling (adj.) | Đồng nghĩa: hang', '[{"hanzi":"Her feet dangled above the floor from the high chair.","pinyin":"","meaning":"Đôi chân của cô bé lủng lẳng ở chiếc ghế cao phía trên mặt sàn."},{"hanzi":"Some employers dangle generous bonuses before applicants while offering limited opportunities for long-term career development.","pinyin":"","meaning":"Một số nhà tuyển dụng đưa ra những khoản tiền thưởng hậu hĩnh để dụ dỗ ứng viên trong khi lại cung cấp rất ít cơ hội phát triển sự nghiệp lâu dài."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_63_1', 'en-c1-63', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
