INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_1_3', 'ten_c1_63_1', 'flicker', 'The candle flickered when she opened the kitchen door.', 'The candle flickered when she opened the kitchen door.', '/ˈflɪkər/', 'Ngọn nến bập bùng khi cô ấy mở cửa nhà bếp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_1_4', 'ten_c1_63_1', 'wrench', 'She tightened the loose bolt with a wrench.', 'She tightened the loose bolt with a wrench.', '/rentʃ/', 'Cô ấy dùng cờ-lê để siết chặt con bu-lông bị lỏng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_1_5', 'ten_c1_63_1', 'sly', 'The sly cat stole a biscuit while I turned away.', 'The sly cat stole a biscuit while I turned away.', '/slaɪ/', 'Con mèo ranh mãnh đã chớp thời cơ nẫng mất một chiếc bánh quy lúc tôi quay đi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_1_6', 'ten_c1_63_1', 'youthful', 'My grandfather still has a youthful smile and boundless energy.', 'My grandfather still has a youthful smile and boundless energy.', '/ˈjuːθfəl/', 'Ông tôi vẫn giữ được nụ cười trẻ trung cùng nguồn năng lượng dồi dào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_1_7', 'ten_c1_63_1', 'quicken', 'I quickened my pace when the rain started.', 'I quickened my pace when the rain started.', '/ˈkwɪkən/', 'Tôi bước nhanh hơn khi trời bắt đầu đổ mưa.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_1_8', 'ten_c1_63_1', 'firmness', 'Press the mattress gently to check its firmness.', 'Press the mattress gently to check its firmness.', '/ˈfɜːrmnəs/', 'Hãy ấn nhẹ vào đệm để kiểm tra độ cứng của nó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_63_1_1', 'en-c1-63', 'ten_c1_63_1', 'listening', 'listening', 'Birdsong wakened me before the sun came up.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ông tôi vẫn giữ được nụ cười trẻ trung cùng nguồn năng lượng dồi dào.","Món súp của tôi đã nguội ngắt khi tôi ngồi xuống bàn.","Tiếng chim hót đã đánh thức tôi dậy trước khi mặt trời mọc.","Cô ấy dùng cờ-lê để siết chặt con bu-lông bị lỏng."]'::jsonb, 2, 'Birdsong wakened me before the sun came up. → Tiếng chim hót đã đánh thức tôi dậy trước khi mặt trời mọc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_63_1_2', 'en-c1-63', 'ten_c1_63_1', 'listening', 'listening', 'She wound the loose fishing line onto the reel.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đôi chân của cô bé lủng lẳng ở chiếc ghế cao phía trên mặt sàn.","Ổ khóa phiền phức này cứ hễ thời tiết trở lạnh là lại bị kẹt cứng.","Cô ấy quấn đoạn dây câu bị chùng vào ống cuộn.","Những trận mưa lúc tạnh lúc rơi cứ kéo dài suốt cả buổi chiều khiến chúng tôi phải chạy liên tục vào nhà."]'::jsonb, 2, 'She wound the loose fishing line onto the reel. → Cô ấy quấn đoạn dây câu bị chùng vào ống cuộn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_63_1_3', 'en-c1-63', 'ten_c1_63_1', 'listening', 'listening', 'The candle flickered when she opened the kitchen door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn có thể dùng phiếu giảm giá này để đổi lấy một bữa trưa miễn phí.","Chúng tôi tìm thấy một chiếc ghế băng yên tĩnh nằm giữa những tán cây đang nở hoa.","Những trận mưa lúc tạnh lúc rơi cứ kéo dài suốt cả buổi chiều khiến chúng tôi phải chạy liên tục vào nhà.","Ngọn nến bập bùng khi cô ấy mở cửa nhà bếp."]'::jsonb, 3, 'The candle flickered when she opened the kitchen door. → Ngọn nến bập bùng khi cô ấy mở cửa nhà bếp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_63_2', 'en-c1-63', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_2_1', 'ten_c1_63_2', 'waken', 'Residents living near airports may be wakened repeatedly by aircraft noise, which can affect their overall health.', 'Residents living near airports may be wakened repeatedly by aircraft noise, which can affect their overall health.', '/ˈweɪkən/', 'Những cư dân sống gần sân bay có thể bị tiếng ồn máy bay làm cho thức giấc nhiều lần, điều này có thể ảnh hưởng đến sức khỏe tổng thể của họ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_2_2', 'ten_c1_63_2', 'reel', 'Local businesses continued to reel from the sudden closure of the region''s largest factory.', 'Local businesses continued to reel from the sudden closure of the region''s largest factory.', '/riːl/', 'Các doanh nghiệp địa phương vẫn tiếp tục điêu đứng trước việc đóng cửa đột ngột của nhà máy lớn nhất vùng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_2_3', 'ten_c1_63_2', 'flicker', 'When streetlights flicker or fail, pedestrians may feel less secure in urban public spaces.', 'When streetlights flicker or fail, pedestrians may feel less secure in urban public spaces.', '/ˈflɪkər/', 'Khi đèn đường nhấp nháy hoặc hỏng, người đi bộ có thể cảm thấy kém an toàn hơn ở các không gian công cộng đô thị.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_2_4', 'ten_c1_63_2', 'wrench', 'Leaving a close community can be a real wrench for students who move abroad for university.', 'Leaving a close community can be a real wrench for students who move abroad for university.', '/rentʃ/', 'Việc rời xa một cộng đồng gắn bó có thể là một nỗi buồn mất mát lớn đối với các sinh viên ra nước ngoài du học.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_2_5', 'ten_c1_63_2', 'sly', 'Sly attempts to hide additional charges can damage consumer trust and harm a company''s reputation.', 'Sly attempts to hide additional charges can damage consumer trust and harm a company''s reputation.', '/slaɪ/', 'Những nỗ lực lén lút nhằm che giấu các khoản phí phát sinh có thể làm xói mòn lòng tin của người tiêu dùng và tổn hại đến uy tín công ty.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_63_2_6', 'ten_c1_63_2', 'youthful', 'A youthful workforce can bring fresh ideas, while experienced employees contribute valuable practical knowledge.', 'A youthful workforce can bring fresh ideas, while experienced employees contribute valuable practical knowledge.', '/ˈjuːθfəl/', 'Lực lượng lao động trẻ trung có thể mang đến những ý tưởng mới mẻ, trong khi các nhân viên giàu kinh nghiệm đóng góp những kiến thức thực tế vô giá.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_63_2_1', 'en-c1-63', 'ten_c1_63_2', 'listening', 'listening', 'Residents living near airports may be wakened repeatedly by aircraft noise, which can affect their overall health.', NULL, 'Trong câu vừa nghe, từ “waken” mang nghĩa nào sau đây?', '["sự an ủi; niềm khuây khỏa","lên án; chỉ trích mạnh mẽ ai đó hoặc cái gì","khoản chi tiêu; chi phí","thức giấc; đánh thức"]'::jsonb, 3, '“waken” (/ˈweɪkən/): thức giấc; đánh thức. Câu đầy đủ: Residents living near airports may be wakened repeatedly by aircraft noise, which can affect their overall health.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_63_2_2', 'en-c1-63', 'ten_c1_63_2', 'listening', 'listening', 'Local businesses continued to reel from the sudden closure of the region''s largest factory.', NULL, 'Trong câu vừa nghe, từ “reel” mang nghĩa nào sau đây?', '["khoảng thời gian yên ắng tạm thời; khoảng lặng","vườn cây nhỏ; một khu rừng nhỏ thường được trồng tập trung","thuộc về nguyên thủy; bản địa; thổ dân","cuộn; ống cuộn"]'::jsonb, 3, '“reel” (/riːl/): cuộn; ống cuộn. Câu đầy đủ: Local businesses continued to reel from the sudden closure of the region''s largest factory.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
