INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_2', 'en-c1-63', NULL, 'comprehensive_test', 'listening', 'She wound the loose fishing line onto the reel.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con mèo ranh mãnh đã chớp thời cơ nẫng mất một chiếc bánh quy lúc tôi quay đi.","Ánh nắng ấm áp đã làm tuyết tan nhanh hơn.","Món súp của tôi đã nguội ngắt khi tôi ngồi xuống bàn.","Cô ấy quấn đoạn dây câu bị chùng vào ống cuộn."]'::jsonb, 3, 'She wound the loose fishing line onto the reel. → Cô ấy quấn đoạn dây câu bị chùng vào ống cuộn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_3', 'en-c1-63', NULL, 'comprehensive_test', 'listening', 'flicker', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["động vật lưỡng cư","có thể nhận thức được; có thể cảm nhận rõ; có thể thấy rõ","nhấp nháy; bập bùng","có thể đạt được; có thể kiếm được; có thể mua được"]'::jsonb, 2, 'flicker (/ˈflɪkər/) → nhấp nháy; bập bùng; ánh sáng nhấp nháy; đốm sáng; vẻ lóe lên; một thoáng (cảm xúc)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_4', 'en-c1-63', NULL, 'comprehensive_test', 'listening', 'She tightened the loose bolt with a wrench.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người nông dân đã bắt lại con dê ở cạnh cổng vườn của chúng tôi.","Cô ấy dùng cờ-lê để siết chặt con bu-lông bị lỏng.","Tiếng chim hót đã đánh thức tôi dậy trước khi mặt trời mọc.","Chiếc áo len cũ của tôi đã trở nên mất form sau quá nhiều lần giặt."]'::jsonb, 1, 'She tightened the loose bolt with a wrench. → Cô ấy dùng cờ-lê để siết chặt con bu-lông bị lỏng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_5', 'en-c1-63', NULL, 'comprehensive_test', 'listening', 'sly', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ranh mãnh, quỷ quyệt, lén lút (thường nhằm vụ lợi)","đo lường hoặc biểu thị số lượng của cái gì; định lượng","kẽm","nằm hoặc ngồi duỗi dài chân tay"]'::jsonb, 0, 'sly (/slaɪ/) → ranh mãnh, quỷ quyệt, lén lút (thường nhằm vụ lợi); láu lỉnh, có ý cười thầm hoặc biểu lộ sự hiểu ý', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_6', 'en-c1-63', NULL, 'comprehensive_test', 'listening', 'My grandfather still has a youthful smile and boundless energy.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông tôi vẫn giữ được nụ cười trẻ trung cùng nguồn năng lượng dồi dào.","Tôi bước nhanh hơn khi trời bắt đầu đổ mưa.","Chỗ ở của chúng tôi tuy nhỏ nhưng ấm cúng và thoải mái.","Những trận mưa lúc tạnh lúc rơi cứ kéo dài suốt cả buổi chiều khiến chúng tôi phải chạy liên tục vào nhà."]'::jsonb, 0, 'My grandfather still has a youthful smile and boundless energy. → Ông tôi vẫn giữ được nụ cười trẻ trung cùng nguồn năng lượng dồi dào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_7', 'en-c1-63', NULL, 'comprehensive_test', 'listening', 'quicken', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự chính trực; tính trung thực và tuân thủ các nguyên tắc đạo đức vững chắc","sự nổi bật; tầm quan trọng; sự nổi tiếng","sự dối trá; hành vi lừa gạt","làm cho nhanh hơn, tăng tốc độ"]'::jsonb, 3, 'quicken (/ˈkwɪkən/) → làm cho nhanh hơn, tăng tốc độ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_8', 'en-c1-63', NULL, 'comprehensive_test', 'listening', 'Press the mattress gently to check its firmness.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mỗi chú thỏ được nhận một ít thức ăn dạng viên cùng với rau tươi.","Anh ấy thọc sâu hai tay vào túi áo khoác.","Hãy ấn nhẹ vào đệm để kiểm tra độ cứng của nó.","Ngọn nến bập bùng khi cô ấy mở cửa nhà bếp."]'::jsonb, 2, 'Press the mattress gently to check its firmness. → Hãy ấn nhẹ vào đệm để kiểm tra độ cứng của nó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_9', 'en-c1-63', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Secretive and clever, often to gain an unfair advantage.”?', '["wrench","youthful","troublesome","sly"]'::jsonb, 3, 'sly (/slaɪ/) → ranh mãnh, quỷ quyệt, lén lút (thường nhằm vụ lợi)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_10', 'en-c1-63', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Looking young or showing the energy and qualities of youth.”?', '["living quarters","youthful","troublesome","dangle"]'::jsonb, 1, 'youthful (/ˈjuːθfəl/) → trẻ trung, có nét trẻ con hoặc mang năng lượng, đặc trưng của tuổi trẻ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_11', 'en-c1-63', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Become faster, or make something happen faster.”?', '["quicken","sly","scant","waken"]'::jsonb, 0, 'quicken (/ˈkwɪkən/) → làm cho nhanh hơn, tăng tốc độ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_12', 'en-c1-63', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the quality of resisting pressure rather than being soft”?', '["lukewarm","firmness","brandy","amidst"]'::jsonb, 1, 'firmness (/ˈfɜːrmnəs/) → độ cứng; độ chắc', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
