INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_18', 'en-c1-63', NULL, 'comprehensive_test', 'reading', NULL, 'Residents living near airports may be wakened repeatedly by aircraft noise, which can affect their overall health.', 'Dựa vào câu trên, từ “waken” có nghĩa phù hợp nhất là gì?', '["sự sai lệch; sự đi chệch","thật; chân thực; đích thực","giao dịch; tiến hành kinh doanh; giải quyết công việc","thức giấc; đánh thức"]'::jsonb, 3, 'waken: thức giấc; đánh thức. Dịch cả câu: Những cư dân sống gần sân bay có thể bị tiếng ồn máy bay làm cho thức giấc nhiều lần, điều này có thể ảnh hưởng đến sức khỏe tổng thể của họ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_19', 'en-c1-63', NULL, 'comprehensive_test', 'reading', NULL, 'Local businesses continued to reel from the sudden closure of the region''s largest factory.', 'Dựa vào câu trên, từ “reel” có nghĩa phù hợp nhất là gì?', '["cuộn; ống cuộn","người cư ngụ; người sử dụng; hành khách (trên xe)","đáng xấu hổ; không quang minh chính đại","giáp ranh; liền kề; nối liền"]'::jsonb, 0, 'reel: cuộn; ống cuộn; lảo đảo; choáng váng; điêu đứng. Dịch cả câu: Các doanh nghiệp địa phương vẫn tiếp tục điêu đứng trước việc đóng cửa đột ngột của nhà máy lớn nhất vùng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_20', 'en-c1-63', NULL, 'comprehensive_test', 'reading', NULL, 'When streetlights flicker or fail, pedestrians may feel less secure in urban public spaces.', 'Dựa vào câu trên, từ “flicker” có nghĩa phù hợp nhất là gì?', '["sự lơ đễnh; sai sót nhỏ","nhấp nháy; bập bùng","hay giúp đỡ; nhiệt tình; sẵn lòng giúp đỡ","khao khát; hoài bão; chí hướng"]'::jsonb, 1, 'flicker: nhấp nháy; bập bùng; ánh sáng nhấp nháy; đốm sáng; vẻ lóe lên; một thoáng (cảm xúc). Dịch cả câu: Khi đèn đường nhấp nháy hoặc hỏng, người đi bộ có thể cảm thấy kém an toàn hơn ở các không gian công cộng đô thị.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_21', 'en-c1-63', NULL, 'comprehensive_test', 'reading', NULL, 'Leaving a close community can be a real wrench for students who move abroad for university.', 'Dựa vào câu trên, từ “wrench” có nghĩa phù hợp nhất là gì?', '["cái mỏ lết; cờ-lê","bố trí theo hình nan hoa; tỏa ra từ tâm","bác sĩ hành nghề; người hành nghề chuyên môn","sự đại diện; quyền đại diện"]'::jsonb, 0, 'wrench: cái mỏ lết; cờ-lê; vặn mạnh; giật mạnh; làm trẹo; nỗi buồn chia ly; sự giật mạnh. Dịch cả câu: Việc rời xa một cộng đồng gắn bó có thể là một nỗi buồn mất mát lớn đối với các sinh viên ra nước ngoài du học.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_22', 'en-c1-63', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “làm nhanh hơn; đẩy nhanh; thúc đẩy”', '["construe","optics","hasten","aristocracy"]'::jsonb, 2, 'làm nhanh hơn; đẩy nhanh; thúc đẩy → hasten (/ˈheɪsən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_23', 'en-c1-63', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khe hở; đường rạch hẹp”', '["estuary","detest","slit","certification"]'::jsonb, 2, 'khe hở; đường rạch hẹp → slit (/slɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_63_24', 'en-c1-63', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thọc; nhét mạnh; đẩy”', '["profound","thrust","redeem","conversant"]'::jsonb, 1, 'thọc; nhét mạnh; đẩy → thrust (/θrʌst/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-64', 'en', 'Bài 64: Đời sống hằng ngày (5) - CEFR C1', 'CEFR C1', 'C1 · Đời sống', '27 từ vựng Tiếng Anh CEFR C1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5064, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fitting', 'en-c1-64', 'fitting', '/ˈfɪtɪŋ/', 'C1', 'thích hợp; phải phép; xứng đáng; phụ kiện; thiết bị lắp đặt; buổi thử quần áo', 'adj.', 'fit (v.), fitted (adj.)', 'Đồng nghĩa: appropriate, suitable · Trái nghĩa: inappropriate, unsuitable', 'Tính từ fitting nhấn mạnh sự thích hợp về mặt hoàn cảnh; còn quần áo mặc vừa vặn thường dùng fit.', 'Flowers seemed a fitting gift for our gardening teacher.', NULL, 'Những bông hoa có vẻ là món quà rất thích hợp dành cho giáo viên dạy môn làm vườn của chúng tôi.', '{"wordId":"fitting","ukIpa":"/ˈfɪtɪŋ/","usIpa":"/ˈfɪtɪŋ/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"suitable for a particular occasion, purpose, or person","vi":"thích hợp; phải phép; xứng đáng"},{"pos":"n.","en":"a small part attached to furniture, equipment, or a building","vi":"phụ kiện; thiết bị lắp đặt"},{"pos":"n.","en":"an appointment to check and adjust how clothes fit","vi":"buổi thử quần áo"}],"examples":[{"en":"Flowers seemed a fitting gift for our gardening teacher.","vi":"Những bông hoa có vẻ là món quà rất thích hợp dành cho giáo viên dạy môn làm vườn của chúng tôi.","audioKind":"ex"},{"en":"A public library would be a fitting memorial to someone who dedicated their life to education.","vi":"Một thư viện công cộng sẽ là sự tưởng niệm xứng đáng cho một người đã cống hiến cả cuộc đời mình cho giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"a fitting tribute","vi":"một sự tri ân thích đáng"},{"en":"a fitting conclusion","vi":"một cái kết trọn vẹn"},{"en":"light fittings","vi":"phụ kiện đèn"},{"en":"a dress fitting","vi":"buổi thử váy"}],"wordFamily":["fit (v.)","fitted (adj.)"],"synonyms":["appropriate","suitable"],"antonyms":["inappropriate","unsuitable"],"tipVi":"Tính từ fitting nhấn mạnh sự thích hợp về mặt hoàn cảnh; còn quần áo mặc vừa vặn thường dùng fit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slender', 'en-c1-64', 'slender', '/ˈslendər/', 'C1', 'mảnh mai, thon thả (theo cách thu hút hoặc thanh nhã); nhỏ bé, ít ỏi, mong manh (về số lượng hoặc cơ hội)', 'adj.', 'slenderness (n.)', 'Đồng nghĩa: slim, thin · Trái nghĩa: thick', 'Khi miêu tả vóc dáng mang hàm ý khen ngợi; từ này cũng dùng để chỉ cơ hội hoặc lợi thế rất nhỏ.', 'A slender branch bent under the bird''s weight.', NULL, 'Một nhành cây mảnh mai trĩu xuống dưới sức nặng của chú chim.', '{"wordId":"slender","ukIpa":"/ˈslendə/","usIpa":"/ˈslendər/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Thin in an attractive or delicate way.","vi":"mảnh mai, thon thả (theo cách thu hút hoặc thanh nhã)"},{"pos":"adj.","en":"Small in amount or unlikely to be enough.","vi":"nhỏ bé, ít ỏi, mong manh (về số lượng hoặc cơ hội)"}],"examples":[{"en":"A slender branch bent under the bird''s weight.","vi":"Một nhành cây mảnh mai trĩu xuống dưới sức nặng của chú chim.","audioKind":"ex"},{"en":"Small businesses often operate with slender profit margins, making them particularly vulnerable to rising energy costs.","vi":"Các doanh nghiệp nhỏ thường hoạt động với biên lợi nhuận rất mỏng, khiến họ đặc biệt dễ bị tổn thương trước tình trạng chi phí năng lượng tăng cao.","audioKind":"ex2"}],"collocations":[{"en":"a slender figure","vi":"vóc dáng mảnh mai"},{"en":"slender fingers","vi":"những ngón tay thon thả"},{"en":"a slender chance","vi":"cơ hội mong manh"},{"en":"a slender majority","vi":"đa số sít sao"}],"wordFamily":["slenderness (n.)"],"synonyms":["slim","thin"],"antonyms":["thick"],"tipVi":"Khi miêu tả vóc dáng mang hàm ý khen ngợi; từ này cũng dùng để chỉ cơ hội hoặc lợi thế rất nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_piggyback', 'en-c1-64', 'piggyback', '/ˈpɪɡibæk/', 'C1', 'cõng; sự cõng trên lưng; cõng trên lưng; tận dụng; nhờ vào', 'n.', NULL, NULL, 'Chỉ việc ngồi trên lưng thay vì trên vai; động từ thường đi với on.', 'My uncle gave me a piggyback across the muddy path.', NULL, 'Chú tôi cõng tôi đi qua con đường lầy lội.', '{"wordId":"piggyback","ukIpa":"/ˈpɪɡibæk/","usIpa":"/ˈpɪɡibæk/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"a ride on someone''s back, with legs around their waist","vi":"cõng; sự cõng trên lưng"},{"pos":"adv.","en":"on someone''s back with legs around their waist","vi":"cõng trên lưng"},{"pos":"v.","en":"to use something already established to achieve your own aim","vi":"tận dụng; nhờ vào"}],"examples":[{"en":"My uncle gave me a piggyback across the muddy path.","vi":"Chú tôi cõng tôi đi qua con đường lầy lội.","audioKind":"ex"},{"en":"Small businesses can piggyback on existing delivery networks to reach distant customers without investing in their own vehicles.","vi":"Các doanh nghiệp nhỏ có thể tận dụng mạng lưới giao hàng sẵn có để tiếp cận khách hàng ở xa mà không cần đầu tư phương tiện riêng.","audioKind":"ex2"}],"collocations":[{"en":"give someone a piggyback","vi":"cõng ai đó trên lưng"},{"en":"a piggyback ride","vi":"cái cõng trên lưng"},{"en":"piggyback on existing systems","vi":"tận dụng hệ thống sẵn có"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ việc ngồi trên lưng thay vì trên vai; động từ thường đi với on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exceedingly', 'en-c1-64', 'exceedingly', '/ɪkˈsiːdɪŋli/', 'C1', 'cực kỳ; vô cùng', 'adv.', 'exceed (v.)', 'Đồng nghĩa: extremely, exceptionally, very', 'Trang trọng hơn very, thường bổ nghĩa cho tính từ hoặc trạng từ.', 'The little bakery was exceedingly busy on Saturday morning.', NULL, 'Tiệm bánh nhỏ bận rộn đến mức tất bật vào sáng thứ Bảy.', '{"wordId":"exceedingly","ukIpa":"/ɪkˈsiːdɪŋli/","usIpa":"/ɪkˈsiːdɪŋli/","cefr":"C1","topic":"daily","senses":[{"pos":"adv.","en":"To a very great degree.","vi":"cực kỳ; vô cùng"}],"examples":[{"en":"The little bakery was exceedingly busy on Saturday morning.","vi":"Tiệm bánh nhỏ bận rộn đến mức tất bật vào sáng thứ Bảy.","audioKind":"ex"},{"en":"Providing reliable public transport in sparsely populated areas can be exceedingly expensive for local authorities.","vi":"Đối với các cơ quan địa phương, việc cung cấp hệ thống giao thông công cộng đáng tin cậy ở những vùng thưa dân cư có thể cực kỳ tốn kém.","audioKind":"ex2"}],"collocations":[{"en":"exceedingly difficult","vi":"vô cùng khó khăn"},{"en":"exceedingly rare","vi":"vô cùng hiếm hoi"},{"en":"exceedingly expensive","vi":"cực kỳ đắt đỏ"}],"wordFamily":["exceed (v.)"],"synonyms":["extremely","exceptionally","very"],"antonyms":[],"tipVi":"Trang trọng hơn very, thường bổ nghĩa cho tính từ hoặc trạng từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frugal', 'en-c1-64', 'frugal', '/ˈfruːɡəl/', 'C1', 'tiết kiệm; giản dị', 'adj.', 'frugality (n.), frugally (adv.)', 'Đồng nghĩa: thrifty, economical · Trái nghĩa: extravagant, wasteful', 'Thường mang nghĩa tích cực, nhấn mạnh việc không lãng phí; không đồng nghĩa với từ keo kiệt stingy.', 'My frugal neighbour repairs his clothes instead of replacing them.', NULL, 'Người hàng xóm tiết kiệm của tôi thường tự vá quần áo cũ thay vì mua đồ mới.', '{"wordId":"frugal","ukIpa":"/ˈfruːɡəl/","usIpa":"/ˈfruːɡəl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Careful with money or resources, avoiding unnecessary spending or waste.","vi":"tiết kiệm; giản dị"}],"examples":[{"en":"My frugal neighbour repairs his clothes instead of replacing them.","vi":"Người hàng xóm tiết kiệm của tôi thường tự vá quần áo cũ thay vì mua đồ mới.","audioKind":"ex"},{"en":"A frugal lifestyle can reduce household waste without necessarily lowering a family''s quality of life.","vi":"Lối sống tiết kiệm có thể giúp giảm thiểu rác thải sinh hoạt mà không nhất thiết làm giảm chất lượng cuộc sống của gia đình.","audioKind":"ex2"}],"collocations":[{"en":"frugal lifestyle","vi":"lối sống tiết kiệm"},{"en":"frugal habits","vi":"thói quen tiết kiệm"},{"en":"frugal meal","vi":"bữa ăn đạm bạc"}],"wordFamily":["frugality (n.)","frugally (adv.)"],"synonyms":["thrifty","economical"],"antonyms":["extravagant","wasteful"],"tipVi":"Thường mang nghĩa tích cực, nhấn mạnh việc không lãng phí; không đồng nghĩa với từ keo kiệt stingy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blindfold', 'en-c1-64', 'blindfold', '/ˈblaɪndfoʊld/', 'C1', 'khăn bịt mắt; đồ bịt mắt; bịt mắt', 'n.', 'blindfolded (adj.)', NULL, 'Chủ yếu đóng vai trò danh từ hoặc động từ; không phải là tên gọi của loại mặt nạ ngủ thông thường.', 'He wore a blindfold and guessed each fruit by taste.', NULL, 'Anh ấy đeo khăn bịt mắt và đoán từng loại trái cây bằng vị giác.', '{"wordId":"blindfold","ukIpa":"/ˈblaɪndfəʊld/","usIpa":"/ˈblaɪndfoʊld/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A cloth covering the eyes to prevent someone from seeing.","vi":"khăn bịt mắt; đồ bịt mắt"},{"pos":"v.","en":"To cover someone''s eyes so they cannot see.","vi":"bịt mắt"}],"examples":[{"en":"He wore a blindfold and guessed each fruit by taste.","vi":"Anh ấy đeo khăn bịt mắt và đoán từng loại trái cây bằng vị giác.","audioKind":"ex"},{"en":"Researchers blindfolded the volunteers to investigate how effectively they could identify everyday objects through touch alone.","vi":"Các nhà nghiên cứu đã bịt mắt các tình nguyện viên để khảo sát khả năng nhận diện các vật dụng hàng ngày chỉ bằng xúc giác của họ một cách hiệu quả ra sao.","audioKind":"ex2"}],"collocations":[{"en":"wear a blindfold","vi":"đeo khăn bịt mắt"},{"en":"put on a blindfold","vi":"đeo bịt mắt"},{"en":"blindfold a participant","vi":"bịt mắt người tham gia"}],"wordFamily":["blindfolded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu đóng vai trò danh từ hoặc động từ; không phải là tên gọi của loại mặt nạ ngủ thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pamper', 'en-c1-64', 'pamper', '/ˈpæmpər/', 'C1', 'chiều chuộng; cưng nựng; nuông chiều', 'v.', 'pampering (n.), pampered (adj.)', 'Đồng nghĩa: indulge, spoil · Trái nghĩa: neglect', 'Không nhất định chứa sắc thái tiêu cực; pamper yourself thường chỉ hành động tự thưởng cho bản thân.', 'I pamper myself with a warm bath on Sundays.', NULL, 'Tôi tự thưởng cho mình một bồn nước ấm vào các ngày Chủ nhật.', '{"wordId":"pamper","ukIpa":"/ˈpæmpə/","usIpa":"/ˈpæmpər/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To give someone special care, comfort, or excessive attention","vi":"chiều chuộng; cưng nựng; nuông chiều"}],"examples":[{"en":"I pamper myself with a warm bath on Sundays.","vi":"Tôi tự thưởng cho mình một bồn nước ấm vào các ngày Chủ nhật.","audioKind":"ex"},{"en":"Parents who constantly pamper their children may unintentionally limit opportunities for them to develop independence.","vi":"Những bậc cha mẹ luôn chiều chuộng con cái có thể vô tình hạn chế cơ hội phát triển tính tự lập của chúng.","audioKind":"ex2"}],"collocations":[{"en":"pamper yourself","vi":"tự thưởng cho bản thân"},{"en":"pamper a child","vi":"nuông chiều trẻ nhỏ"},{"en":"pamper someone with gifts","vi":"chiều chuộng ai bằng quà cáp"}],"wordFamily":["pampering (n.)","pampered (adj.)"],"synonyms":["indulge","spoil"],"antonyms":["neglect"],"tipVi":"Không nhất định chứa sắc thái tiêu cực; pamper yourself thường chỉ hành động tự thưởng cho bản thân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_devour', 'en-c1-64', 'devour', '/dɪˈvaʊər/', 'C1', 'ăn ngấu nghiến; ăn vội vàng; đọc ngấu nghiến; đọc say mê; tiêu thụ nhanh chóng; tàn phá; nuốt chửng', 'v.', NULL, 'Đồng nghĩa: gobble, consume', 'Có cường độ mạnh hơn eat; cũng có thể dùng theo nghĩa bóng để chỉ việc đọc sách hoặc tiêu thụ tài nguyên.', 'After swimming, we devoured the warm bread within minutes.', NULL, 'Sau khi bơi lội, chúng tôi đã ăn sạch ổ bánh mì ấm nóng chỉ trong vòng vài phút.', '{"wordId":"devour","ukIpa":"/dɪˈvaʊə/","usIpa":"/dɪˈvaʊər/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To eat something quickly and eagerly.","vi":"ăn ngấu nghiến; ăn vội vàng"},{"pos":"v.","en":"To read something with great enthusiasm.","vi":"đọc ngấu nghiến; đọc say mê"},{"pos":"v.","en":"To consume or destroy large amounts of something.","vi":"tiêu thụ nhanh chóng; tàn phá; nuốt chửng"}],"examples":[{"en":"After swimming, we devoured the warm bread within minutes.","vi":"Sau khi bơi lội, chúng tôi đã ăn sạch ổ bánh mì ấm nóng chỉ trong vòng vài phút.","audioKind":"ex"},{"en":"Large infrastructure projects can devour public funds unless spending is carefully monitored throughout construction.","vi":"Các dự án cơ sở hạ tầng lớn có thể ngốn lượng lớn quỹ công trừ khi chi phí được giám sát chặt chẽ trong suốt quá trình thi công.","audioKind":"ex2"}],"collocations":[{"en":"devour a meal","vi":"ăn ngấu nghiến một bữa ăn"},{"en":"devour books","vi":"đọc sách ngấu nghiến"},{"en":"devour resources","vi":"tiêu thụ tài nguyên cạn kiệt"}],"wordFamily":[],"synonyms":["gobble","consume"],"antonyms":[],"tipVi":"Có cường độ mạnh hơn eat; cũng có thể dùng theo nghĩa bóng để chỉ việc đọc sách hoặc tiêu thụ tài nguyên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dodge', 'en-c1-64', 'dodge', '/dɑːdʒ/', 'C1', 'né tránh; lảng tránh (để không bị va chạm); trốn tránh; né tránh (nhiệm vụ, câu hỏi); thủ đoạn; mánh khóe né tránh', 'v.', 'dodger (n.)', 'Đồng nghĩa: evade, avoid · Trái nghĩa: confront', 'Có thể kết hợp trực tiếp với tân ngữ: dodge a question có nghĩa là né tránh câu hỏi.', 'I dodged a puddle and nearly dropped my shopping.', NULL, 'Tôi né một vũng nước và suýt làm rơi đồ mua sắm.', '{"wordId":"dodge","ukIpa":"/dɒdʒ/","usIpa":"/dɑːdʒ/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To move quickly out of the way of something.","vi":"né tránh; lảng tránh (để không bị va chạm)"},{"pos":"v.","en":"To avoid a duty, question, or difficult situation.","vi":"trốn tránh; né tránh (nhiệm vụ, câu hỏi)"},{"pos":"n.","en":"A clever trick used to avoid something unpleasant.","vi":"thủ đoạn; mánh khóe né tránh"}],"examples":[{"en":"I dodged a puddle and nearly dropped my shopping.","vi":"Tôi né một vũng nước và suýt làm rơi đồ mua sắm.","audioKind":"ex"},{"en":"Public officials who dodge difficult questions may weaken citizens'' trust in the institutions they represent.","vi":"Các quan chức công quyền né tránh những câu hỏi hóc búa có thể làm suy giảm niềm tin của công dân vào các cơ quan mà họ đại diện.","audioKind":"ex2"}],"collocations":[{"en":"dodge a ball","vi":"né quả bóng"},{"en":"dodge a question","vi":"tránh né câu hỏi"},{"en":"dodge responsibility","vi":"trốn tránh trách nhiệm"}],"wordFamily":["dodger (n.)"],"synonyms":["evade","avoid"],"antonyms":["confront"],"tipVi":"Có thể kết hợp trực tiếp với tân ngữ: dodge a question có nghĩa là né tránh câu hỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coincide', 'en-c1-64', 'coincide', '/ˌkoʊɪnˈsaɪd/', 'C1', 'trùng; xảy ra đồng thời; trùng khớp; đồng quan điểm; ăn khớp', 'v.', 'coincidence (n.), coincidental (adj.), coincidentally (adv.)', NULL, 'Là nội động từ, khi đi với đối tượng phải dùng giới từ with, không đi trực tiếp với tân ngữ.', 'My days off rarely coincide with my sister''s.', NULL, 'Những ngày nghỉ của tôi hiếm khi trùng với ngày nghỉ của chị gái.', '{"wordId":"coincide","ukIpa":"/ˌkəʊɪnˈsaɪd/","usIpa":"/ˌkoʊɪnˈsaɪd/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to happen at the same time","vi":"trùng; xảy ra đồng thời"},{"pos":"v.","en":"to be the same or agree with something","vi":"trùng khớp; đồng quan điểm; ăn khớp"}],"examples":[{"en":"My days off rarely coincide with my sister''s.","vi":"Những ngày nghỉ của tôi hiếm khi trùng với ngày nghỉ của chị gái.","audioKind":"ex"},{"en":"Government investment should coincide with local priorities to ensure that public funds address genuine community needs.","vi":"Khoản đầu tư của chính phủ nên đồng điệu với các ưu tiên của địa phương nhằm đảm bảo nguồn quỹ công đáp ứng đúng nhu cầu thực tế của cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"coincide with","vi":"trùng với; xảy ra đồng thời với"},{"en":"coincide exactly","vi":"trùng khớp hoàn toàn"},{"en":"views coincide","vi":"quan điểm trùng hợp"}],"wordFamily":["coincidence (n.)","coincidental (adj.)","coincidentally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Là nội động từ, khi đi với đối tượng phải dùng giới từ with, không đi trực tiếp với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_linger', 'en-c1-64', 'linger', '/ˈlɪŋɡɚ/', 'C1', 'nán lại; chần chừ không muốn rời đi; kéo dài; duy trì hoặc tồn tại lâu dài', 'v.', 'lingering (adj.)', 'Đồng nghĩa: remain, stay', 'Là nội động từ; "linger over" diễn tả việc thong thả thưởng thức hoặc ngắm nhìn cái gì đó.', 'We lingered outside the cinema, chatting about the film.', NULL, 'Chúng tôi nán lại bên ngoài rạp chiếu phim để trò chuyện về bộ phim vừa xem.', '{"wordId":"linger","ukIpa":"/ˈlɪŋɡə/","usIpa":"/ˈlɪŋɡɚ/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To stay somewhere longer than expected or necessary.","vi":"nán lại; chần chừ không muốn rời đi"},{"pos":"v.","en":"To remain present or noticeable for a long time.","vi":"kéo dài; duy trì hoặc tồn tại lâu dài"}],"examples":[{"en":"We lingered outside the cinema, chatting about the film.","vi":"Chúng tôi nán lại bên ngoài rạp chiếu phim để trò chuyện về bộ phim vừa xem.","audioKind":"ex"},{"en":"The effects of prolonged unemployment can linger even after individuals return to stable work.","vi":"Hậu quả của tình trạng thất nghiệp kéo dài vẫn có thể tồn tại ngay cả sau khi mọi người đã trở lại làm việc ổn định.","audioKind":"ex2"}],"collocations":[{"en":"linger over a meal","vi":"thong thả dùng bữa"},{"en":"linger in the air","vi":"vương vấn trong không khí"},{"en":"linger on","vi":"kéo dài không dứt"}],"wordFamily":["lingering (adj.)"],"synonyms":["remain","stay"],"antonyms":[],"tipVi":"Là nội động từ; \"linger over\" diễn tả việc thong thả thưởng thức hoặc ngắm nhìn cái gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indispensable', 'en-c1-64', 'indispensable', '/ˌɪndɪˈspensəbəl/', 'C1', 'không thể thiếu, vô cùng quan trọng, thiết yếu', 'adj.', 'dispensable (adj.), indispensability (n.)', 'Đồng nghĩa: essential, vital, necessary · Trái nghĩa: dispensable, unnecessary', 'Thường đi kèm với giới từ to hoặc for; mức độ nhấn mạnh mạnh hơn từ useful, diễn tả thứ không có không được.', 'My bicycle is indispensable for getting to work.', NULL, 'Chiếc xe đạp là phương tiện không thể thiếu đối với tôi để đi làm.', '{"wordId":"indispensable","ukIpa":"/ˌɪndɪˈspensəbəl/","usIpa":"/ˌɪndɪˈspensəbəl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"So important or useful that it cannot be done without","vi":"không thể thiếu, vô cùng quan trọng, thiết yếu"}],"examples":[{"en":"My bicycle is indispensable for getting to work.","vi":"Chiếc xe đạp là phương tiện không thể thiếu đối với tôi để đi làm.","audioKind":"ex"},{"en":"Reliable internet access has become indispensable for students who depend on digital platforms to complete their coursework.","vi":"Quyền truy cập internet đáng tin cậy đã trở nên không thể thiếu đối với các sinh viên phụ thuộc vào nền tảng kỹ thuật số để hoàn thành bài tập khóa học.","audioKind":"ex2"}],"collocations":[{"en":"indispensable to","vi":"không thể thiếu đối với"},{"en":"indispensable for","vi":"cần thiết cho"},{"en":"an indispensable tool","vi":"một công cụ thiết yếu"},{"en":"play an indispensable role","vi":"đóng một vai trò không thể thiếu"}],"wordFamily":["dispensable (adj.)","indispensability (n.)"],"synonyms":["essential","vital","necessary"],"antonyms":["dispensable","unnecessary"],"tipVi":"Thường đi kèm với giới từ to hoặc for; mức độ nhấn mạnh mạnh hơn từ useful, diễn tả thứ không có không được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_headlong', 'en-c1-64', 'headlong', '/ˈhedlɔːŋ/', 'C1', 'cắm đầu về phía trước, lao đầu xuống; với tốc độ rất nhanh; một cách liều lĩnh, vội vã, không suy tính trước các nguy hiểm hay hậu quả; mang tính hấp tấp, thiếu cẩn trọng và suy nghĩ', 'adv.', NULL, 'Đồng nghĩa: headfirst, rashly · Trái nghĩa: cautiously', 'Vừa có thể chỉ hướng chuyển động cắm đầu phía trước, vừa dùng theo nghĩa bóng là hành động bất chấp hậu quả.', 'He tripped over the cushion and fell headlong onto the sofa.', NULL, 'Anh ấy vấp phải chiếc đệm và ngã chúi đầu xuống ghế sofa.', '{"wordId":"headlong","ukIpa":"/ˈhedlɒŋ/","usIpa":"/ˈhedlɔːŋ/","cefr":"C1","topic":"daily","senses":[{"pos":"adv.","en":"With the head first, or with great speed.","vi":"cắm đầu về phía trước, lao đầu xuống; với tốc độ rất nhanh"},{"pos":"adv.","en":"Without enough thought about possible dangers or consequences.","vi":"một cách liều lĩnh, vội vã, không suy tính trước các nguy hiểm hay hậu quả"},{"pos":"adj.","en":"Done very quickly without enough care or thought.","vi":"mang tính hấp tấp, thiếu cẩn trọng và suy nghĩ"}],"examples":[{"en":"He tripped over the cushion and fell headlong onto the sofa.","vi":"Anh ấy vấp phải chiếc đệm và ngã chúi đầu xuống ghế sofa.","audioKind":"ex"},{"en":"Governments should avoid rushing headlong into major infrastructure projects without first assessing their environmental impact.","vi":"Chính phủ nên tránh lao vào các dự án cơ sở hạ tầng lớn một cách vội vã mà không đánh giá trước tác động môi trường của chúng.","audioKind":"ex2"}],"collocations":[{"en":"fall headlong","vi":"ngã chúi đầu"},{"en":"rush headlong into","vi":"lao đầu vào"},{"en":"a headlong rush","vi":"một cuộc lao vội bất chấp hậu quả"}],"wordFamily":[],"synonyms":["headfirst","rashly"],"antonyms":["cautiously"],"tipVi":"Vừa có thể chỉ hướng chuyển động cắm đầu phía trước, vừa dùng theo nghĩa bóng là hành động bất chấp hậu quả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hustle', 'en-c1-64', 'hustle', '/ˈhʌsəl/', 'C1', 'hối hả; vội vã; thúc giục; sự bận rộn huyên náo; nhịp sống hối hả; lừa bịp; gạ gẫm bán hàng', 'v.', 'hustler (n.)', NULL, 'Cụm từ hustle and bustle là thành ngữ cố định chỉ sự bận rộn, nhộn nhịp.', 'We hustled through the station to catch the last train.', NULL, 'Chúng tôi vội vã chạy qua nhà ga để kịp chuyến tàu cuối cùng.', '{"wordId":"hustle","ukIpa":"/ˈhʌsəl/","usIpa":"/ˈhʌsəl/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To move quickly or make someone move quickly, sometimes roughly.","vi":"hối hả; vội vã; thúc giục"},{"pos":"n.","en":"Busy, energetic activity involving many people.","vi":"sự bận rộn huyên náo; nhịp sống hối hả"},{"pos":"v.","en":"To sell aggressively or obtain something through dishonest persuasion.","vi":"lừa bịp; gạ gẫm bán hàng"}],"examples":[{"en":"We hustled through the station to catch the last train.","vi":"Chúng tôi vội vã chạy qua nhà ga để kịp chuyến tàu cuối cùng.","audioKind":"ex"},{"en":"Some residents leave major cities because the daily hustle makes it difficult to maintain a balanced lifestyle.","vi":"Một số cư dân rời bỏ các thành phố lớn bởi nhịp sống hối hả hàng ngày khiến họ khó duy trì một lối sống cân bằng.","audioKind":"ex2"}],"collocations":[{"en":"hustle and bustle","vi":"sự huyên náo và nhịp sống hối hả"},{"en":"hustle someone out","vi":"giục ai đó ra ngoài"},{"en":"hustle through the crowd","vi":"chen chúc qua đám đông"}],"wordFamily":["hustler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ hustle and bustle là thành ngữ cố định chỉ sự bận rộn, nhộn nhịp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quench', 'en-c1-64', 'quench', '/kwentʃ/', 'C1', 'làm hết khát; thỏa mãn (khát khao, mong ước); dập tắt (lửa)', 'v.', 'unquenchable (adj.)', 'Đồng nghĩa: satisfy, extinguish', 'Cụm từ phổ biến nhất là quench one''s thirst, dùng để chỉ hành động giải khát.', 'Cold water quenched my thirst after the long walk.', NULL, 'Nước lạnh đã làm dịu cơn khát của tôi sau quãng đường đi bộ dài.', '{"wordId":"quench","ukIpa":"/kwentʃ/","usIpa":"/kwentʃ/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To satisfy thirst or a strong desire.","vi":"làm hết khát; thỏa mãn (khát khao, mong ước)"},{"pos":"v.","en":"To put out a fire or stop flames burning.","vi":"dập tắt (lửa)"}],"examples":[{"en":"Cold water quenched my thirst after the long walk.","vi":"Nước lạnh đã làm dịu cơn khát của tôi sau quãng đường đi bộ dài.","audioKind":"ex"},{"en":"Public drinking fountains allow residents to quench their thirst without buying bottled water, reducing plastic waste.","vi":"Các đài phun nước công cộng giúp cư dân giải khát mà không cần mua nước đóng chai, qua đó giảm thiểu rác thải nhựa.","audioKind":"ex2"}],"collocations":[{"en":"quench your thirst","vi":"làm dịu cơn khát"},{"en":"quench a thirst for knowledge","vi":"thỏa mãn khao khát học hỏi"},{"en":"quench the flames","vi":"dập tắt ngọn lửa"}],"wordFamily":["unquenchable (adj.)"],"synonyms":["satisfy","extinguish"],"antonyms":[],"tipVi":"Cụm từ phổ biến nhất là quench one''s thirst, dùng để chỉ hành động giải khát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fob', 'en-c1-64', 'fob', '/fɑːb/', 'C1', 'móc khóa điện tử; thiết bị điều khiển từ xa nhỏ gọn; dùng lý do thoái thác để tống khứ ai đó', 'n.', NULL, NULL, 'Thuật ngữ giá giao hàng trên bo tàu trong thương mại thường viết là FOB, cần phân biệt với từ fob viết thường.', 'I pressed the fob to unlock the car.', NULL, 'Tôi bấm vào chiếc chìa khóa điện tử để mở cửa xe.', '{"wordId":"fob","ukIpa":"/fɒb/","usIpa":"/fɑːb/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A small object attached to keys, sometimes controlling electronic locks.","vi":"móc khóa điện tử; thiết bị điều khiển từ xa nhỏ gọn"},{"pos":"v.","en":"With off, to dismiss someone using excuses or inadequate answers.","vi":"dùng lý do thoái thác để tống khứ ai đó"}],"examples":[{"en":"I pressed the fob to unlock the car.","vi":"Tôi bấm vào chiếc chìa khóa điện tử để mở cửa xe.","audioKind":"ex"},{"en":"Housing providers increasingly issue residents an electronic fob to control access to shared buildings.","vi":"Các đơn vị cung cấp nhà ở ngày càng cấp cho cư dân thẻ từ điện tử để kiểm soát việc ra vào các tòa nhà chung.","audioKind":"ex2"}],"collocations":[{"en":"key fob","vi":"móc khóa"},{"en":"electronic fob","vi":"thẻ từ cửa ra vào"},{"en":"fob someone off","vi":"thoái thác ai đó"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thuật ngữ giá giao hàng trên bo tàu trong thương mại thường viết là FOB, cần phân biệt với từ fob viết thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_precede', 'en-c1-64', 'precede', '/prɪˈsiːd/', 'C1', 'xảy ra trước; tồn tại trước một sự việc hoặc vật khác; đi trước; đi ở phía trước ai đó hoặc cái gì đó', 'v.', 'preceding (adj.), precedence (n.)', 'Đồng nghĩa: come before · Trái nghĩa: follow', '"precede" có nghĩa là đi trước/xảy ra trước; còn "proceed" có nghĩa là tiếp tục tiến hành.', 'A short welcome speech will precede the evening meal.', NULL, 'Một bài phát biểu chào mừng ngắn sẽ diễn ra trước bữa ăn tối.', '{"wordId":"precede","ukIpa":"/prɪˈsiːd/","usIpa":"/prɪˈsiːd/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to happen or exist before something else","vi":"xảy ra trước; tồn tại trước một sự việc hoặc vật khác"},{"pos":"v.","en":"to go in front of someone or something","vi":"đi trước; đi ở phía trước ai đó hoặc cái gì đó"}],"examples":[{"en":"A short welcome speech will precede the evening meal.","vi":"Một bài phát biểu chào mừng ngắn sẽ diễn ra trước bữa ăn tối.","audioKind":"ex"},{"en":"Thorough environmental assessments should precede major construction projects to identify potential risks to local ecosystems.","vi":"Các đánh giá tác động môi trường toàn diện nên được tiến hành trước các dự án xây dựng lớn để nhận diện các rủi ro tiềm ẩn đối với hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"immediately precede","vi":"ngay trước"},{"en":"precede the introduction of","vi":"đi trước việc giới thiệu cái gì"},{"en":"be preceded by","vi":"được đi trước bởi"}],"wordFamily":["preceding (adj.)","precedence (n.)"],"synonyms":["come before"],"antonyms":["follow"],"tipVi":"\"precede\" có nghĩa là đi trước/xảy ra trước; còn \"proceed\" có nghĩa là tiếp tục tiến hành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_petite', 'en-c1-64', 'petite', '/pəˈtiːt/', 'C1', 'nhỏ nhắn; thon thả (dành cho phụ nữ); (quần áo) thiết kế riêng cho phụ nữ vóc dáng nhỏ', 'adj.', NULL, NULL, 'Thường dùng để miêu tả phụ nữ trưởng thành có thân hình nhỏ nhắn, không đồng nghĩa với việc chỉ đơn thuần là gầy.', 'My sister is petite and often needs shorter trousers.', NULL, 'Chị tôi có vóc dáng nhỏ nhắn nên thường phải mặc quần có ống ngắn hơn.', '{"wordId":"petite","ukIpa":"/pəˈtiːt/","usIpa":"/pəˈtiːt/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"describing a woman who is short and has a small build","vi":"nhỏ nhắn; thon thả (dành cho phụ nữ)"},{"pos":"adj.","en":"describing clothes designed to fit shorter women","vi":"(quần áo) thiết kế riêng cho phụ nữ vóc dáng nhỏ"}],"examples":[{"en":"My sister is petite and often needs shorter trousers.","vi":"Chị tôi có vóc dáng nhỏ nhắn nên thường phải mặc quần có ống ngắn hơn.","audioKind":"ex"},{"en":"Clothing retailers can serve a wider range of customers by offering petite sizes alongside their standard collections.","vi":"Các nhà bán lẻ thời trang có thể phục vụ lượng khách hàng lớn hơn bằng cách cung cấp các kích cỡ nhỏ nhắn bên cạnh các dòng sản phẩm tiêu chuẩn của họ.","audioKind":"ex2"}],"collocations":[{"en":"petite woman","vi":"phụ nữ vóc dáng nhỏ nhắn"},{"en":"petite frame","vi":"vóc dáng nhỏ nhắn"},{"en":"petite sizes","vi":"cỡ quần áo nhỏ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng để miêu tả phụ nữ trưởng thành có thân hình nhỏ nhắn, không đồng nghĩa với việc chỉ đơn thuần là gầy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refined', 'en-c1-64', 'refined', '/rɪˈfaɪnd/', 'C1', 'tinh chế; đã qua tinh lọc; thanh lịch; có học thức; tao nhã; được cải tiến; tinh tế hơn', 'adj.', 'refine (v.), refinement (n.), refinery (n.), unrefined (adj.)', 'Đồng nghĩa: purified, cultured · Trái nghĩa: unrefined, crude', 'Khi dùng cho chất liệu, từ này chỉ sự tinh chế; khi dùng cho con người hoặc hành vi, nó chỉ sự thanh lịch, nhã nhặn.', 'This recipe uses honey instead of refined white sugar.', NULL, 'Công thức này dùng mật ong thay cho đường trắng tinh chế.', '{"wordId":"refined","ukIpa":"/rɪˈfaɪnd/","usIpa":"/rɪˈfaɪnd/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Processed to remove unwanted substances.","vi":"tinh chế; đã qua tinh lọc"},{"pos":"adj.","en":"Showing polite manners, good taste, and cultural awareness.","vi":"thanh lịch; có học thức; tao nhã"},{"pos":"adj.","en":"Improved through careful changes to details.","vi":"được cải tiến; tinh tế hơn"}],"examples":[{"en":"This recipe uses honey instead of refined white sugar.","vi":"Công thức này dùng mật ong thay cho đường trắng tinh chế.","audioKind":"ex"},{"en":"Public health campaigns often encourage people to reduce their consumption of foods containing large amounts of refined sugar.","vi":"Các chiến dịch y tế cộng đồng thường khuyến khích người dân giảm lượng tiêu thụ thực phẩm chứa nhiều đường tinh luyện.","audioKind":"ex2"}],"collocations":[{"en":"refined sugar","vi":"đường tinh luyện"},{"en":"refined oil","vi":"dầu tinh luyện"},{"en":"refined manners","vi":"phong thái tao nhã"},{"en":"a refined technique","vi":"kỹ thuật cải tiến"}],"wordFamily":["refine (v.)","refinement (n.)","refinery (n.)","unrefined (adj.)"],"synonyms":["purified","cultured"],"antonyms":["unrefined","crude"],"tipVi":"Khi dùng cho chất liệu, từ này chỉ sự tinh chế; khi dùng cho con người hoặc hành vi, nó chỉ sự thanh lịch, nhã nhặn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_happening', 'en-c1-64', 'happening', '/ˈhæpənɪŋ/', 'C1', 'sự việc; điều xảy ra', 'n.', 'happen (v.)', 'Đồng nghĩa: event, occurrence', 'Danh từ này thường dùng ở số nhiều là happenings; đối với các sự kiện chính thức, từ event thường được ưu tiên sử dụng hơn.', 'My uncle entertains us with stories of strange happenings.', NULL, 'Chú tôi giải trí cho chúng tôi bằng những câu chuyện về các hiện tượng kỳ lạ.', '{"wordId":"happening","ukIpa":"/ˈhæpənɪŋ/","usIpa":"/ˈhæpənɪŋ/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"Something that occurs, especially an unusual or interesting event.","vi":"sự việc; điều xảy ra"}],"examples":[{"en":"My uncle entertains us with stories of strange happenings.","vi":"Chú tôi giải trí cho chúng tôi bằng những câu chuyện về các hiện tượng kỳ lạ.","audioKind":"ex"},{"en":"Local newspapers record everyday happenings that help future researchers understand how communities lived and changed.","vi":"Các tờ báo địa phương ghi lại những sự kiện thường ngày, giúp các nhà nghiên cứu tương lai hiểu được cách cộng đồng sinh sống và thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"strange happenings","vi":"những sự việc kỳ lạ"},{"en":"local happenings","vi":"sự việc diễn ra ở địa phương"},{"en":"everyday happenings","vi":"những chuyện thường ngày"}],"wordFamily":["happen (v.)"],"synonyms":["event","occurrence"],"antonyms":[],"tipVi":"Danh từ này thường dùng ở số nhiều là happenings; đối với các sự kiện chính thức, từ event thường được ưu tiên sử dụng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gush', 'en-c1-64', 'gush', '/ɡʌʃ/', 'C1', 'phun trào; tuôn trào; bày tỏ sự nhiệt tình hoặc ca ngợi quá mức; dòng chảy mạnh và bất ngờ', 'v.', 'gushing (adj.)', 'Đồng nghĩa: spurt, pour · Trái nghĩa: trickle', 'Khi nói về con người, cụm gush about thường ngụ ý sự khen ngợi có phần quá đà hoặc quá nhiệt tình.', 'Water gushed from the broken pipe beneath the sink.', NULL, 'Nước phun ra từ ống nước bị vỡ bên dưới bồn rửa chén.', '{"wordId":"gush","ukIpa":"/ɡʌʃ/","usIpa":"/ɡʌʃ/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To flow out suddenly in large amounts.","vi":"phun trào; tuôn trào"},{"pos":"v.","en":"To express enthusiasm or praise in an excessive way.","vi":"bày tỏ sự nhiệt tình hoặc ca ngợi quá mức"},{"pos":"n.","en":"A sudden, strong flow of liquid.","vi":"dòng chảy mạnh và bất ngờ"}],"examples":[{"en":"Water gushed from the broken pipe beneath the sink.","vi":"Nước phun ra từ ống nước bị vỡ bên dưới bồn rửa chén.","audioKind":"ex"},{"en":"When ageing pipes burst, clean water can gush into streets, wasting resources and disrupting local transport.","vi":"Khi các đường ống cũ kỹ bị vỡ, nước sạch có thể tuôn ra đường phố, làm lãng phí tài nguyên và làm gián đoạn giao thông địa phương.","audioKind":"ex2"}],"collocations":[{"en":"gush out","vi":"phun trào ra"},{"en":"gush from a pipe","vi":"phun ra từ đường ống"},{"en":"gush about something","vi":"ca ngợi hết lời về điều gì đó"},{"en":"a gush of water","vi":"một dòng nước tuôn trào"}],"wordFamily":["gushing (adj.)"],"synonyms":["spurt","pour"],"antonyms":["trickle"],"tipVi":"Khi nói về con người, cụm gush about thường ngụ ý sự khen ngợi có phần quá đà hoặc quá nhiệt tình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ramble', 'en-c1-64', 'ramble', '/ˈræmbəl/', 'C1', 'đi dạo nhàn nhã; lang thang; nói lan man; nói dài dòng không có trọng tâm; chuyến đi dạo dài (đặc biệt là ở vùng quê)', 'v.', 'rambler (n.), rambling (adj.)', 'Đồng nghĩa: wander', 'ramble on thường chỉ việc nói năng dài dòng, lủng củng và mang sắc thái tỏ ý thiếu kiên nhẫn.', 'We rambled through the woods until it started raining.', NULL, 'Chúng tôi đi dạo lang thang qua các tán rừng cho đến khi trời bắt đầu mưa.', '{"wordId":"ramble","ukIpa":"/ˈræmbəl/","usIpa":"/ˈræmbəl/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to walk for pleasure without following a fixed route","vi":"đi dạo nhàn nhã; lang thang"},{"pos":"v.","en":"to talk at length without a clear focus","vi":"nói lan man; nói dài dòng không có trọng tâm"},{"pos":"n.","en":"a long walk for pleasure, especially in the countryside","vi":"chuyến đi dạo dài (đặc biệt là ở vùng quê)"}],"examples":[{"en":"We rambled through the woods until it started raining.","vi":"Chúng tôi đi dạo lang thang qua các tán rừng cho đến khi trời bắt đầu mưa.","audioKind":"ex"},{"en":"Speakers who ramble during presentations may struggle to communicate their main arguments clearly to an audience.","vi":"Những diễn giả nói lan man trong các buổi thuyết trình có thể gặp khó khăn trong việc truyền đạt rõ ràng các lập luận chính của mình tới khán giả.","audioKind":"ex2"}],"collocations":[{"en":"ramble through the countryside","vi":"đi dạo ở vùng quê"},{"en":"ramble on about something","vi":"nói lan man về điều gì đó"},{"en":"go for a ramble","vi":"đi dạo chơi"}],"wordFamily":["rambler (n.)","rambling (adj.)"],"synonyms":["wander"],"antonyms":[],"tipVi":"ramble on thường chỉ việc nói năng dài dòng, lủng củng và mang sắc thái tỏ ý thiếu kiên nhẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extinguish', 'en-c1-64', 'extinguish', '/ɪkˈstɪŋɡwɪʃ/', 'C1', 'dập tắt; làm tắt; làm tiêu tan; làm lụi tàn (hy vọng, cảm xúc)', 'v.', 'extinguisher (n.)', 'Đồng nghĩa: put out · Trái nghĩa: ignite, light', 'Là ngoại động từ; trong văn phong hàng ngày, từ put out cũng thường được dùng với nghĩa dập tắt.', 'We extinguished the campfire before getting into our tents.', NULL, 'Chúng tôi đã dập tắt lửa trại trước khi bước vào lều.', '{"wordId":"extinguish","ukIpa":"/ɪkˈstɪŋɡwɪʃ/","usIpa":"/ɪkˈstɪŋɡwɪʃ/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to stop a fire or flame from burning","vi":"dập tắt; làm tắt"},{"pos":"v.","en":"to bring a feeling, hope, or idea to an end","vi":"làm tiêu tan; làm lụi tàn (hy vọng, cảm xúc)"}],"examples":[{"en":"We extinguished the campfire before getting into our tents.","vi":"Chúng tôi đã dập tắt lửa trại trước khi bước vào lều.","audioKind":"ex"},{"en":"Prolonged unemployment can extinguish young people''s hopes of achieving financial independence and securing stable housing.","vi":"Tình trạng thất nghiệp kéo dài có thể làm tiêu tan hy vọng đạt được sự độc lập tài chính và có được nhà ở ổn định của giới trẻ.","audioKind":"ex2"}],"collocations":[{"en":"extinguish a fire","vi":"dập tắt đám cháy"},{"en":"extinguish a flame","vi":"làm tắt ngọn lửa"},{"en":"extinguish hope","vi":"dập tắt hy vọng"}],"wordFamily":["extinguisher (n.)"],"synonyms":["put out"],"antonyms":["ignite","light"],"tipVi":"Là ngoại động từ; trong văn phong hàng ngày, từ put out cũng thường được dùng với nghĩa dập tắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invariably', 'en-c1-64', 'invariably', '/ɪnˈveriəbli/', 'C1', 'luôn luôn; lúc nào cũng', 'adv.', 'invariable (adj.), variable (adj.), variation (n.)', 'Đồng nghĩa: always, consistently · Trái nghĩa: never', 'Mang sắc thái mạnh hơn "usually", diễn tả sự việc xảy ra trong mọi trường hợp, không chỉ là thông thường.', 'My brother invariably falls asleep during long train journeys.', NULL, 'Anh trai tôi lần nào đi tàu chuyến dài cũng ngủ gật.', '{"wordId":"invariably","ukIpa":"/ɪnˈveəriəbli/","usIpa":"/ɪnˈveriəbli/","cefr":"C1","topic":"daily","senses":[{"pos":"adv.","en":"Always, or on every occasion.","vi":"luôn luôn; lúc nào cũng"}],"examples":[{"en":"My brother invariably falls asleep during long train journeys.","vi":"Anh trai tôi lần nào đi tàu chuyến dài cũng ngủ gật.","audioKind":"ex"},{"en":"In this study, participants with longer commuting times invariably reported having less time for leisure activities.","vi":"Trong nghiên cứu này, những người tham gia có thời gian đi lại dài hơn đều không ngoại lệ khi báo cáo rằng họ có ít thời gian hơn cho các hoạt động giải trí.","audioKind":"ex2"}],"collocations":[{"en":"almost invariably","vi":"hầu như luôn luôn"},{"en":"invariably lead to","vi":"luôn dẫn đến"},{"en":"invariably find","vi":"luôn tìm thấy"}],"wordFamily":["invariable (adj.)","variable (adj.)","variation (n.)"],"synonyms":["always","consistently"],"antonyms":["never"],"tipVi":"Mang sắc thái mạnh hơn \"usually\", diễn tả sự việc xảy ra trong mọi trường hợp, không chỉ là thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pantry', 'en-c1-64', 'pantry', '/ˈpæntri/', 'C1', 'phòng chứa thức ăn; tủ đựng thực phẩm', 'n.', NULL, 'Đồng nghĩa: larder', 'Chủ yếu dùng để lưu trữ thực phẩm; không đồng nghĩa với căn bếp (kitchen) nơi nấu nướng.', 'There is another bag of rice in the pantry.', NULL, 'Vẫn còn một bao gạo nữa ở trong phòng chứa thức ăn.', '{"wordId":"pantry","ukIpa":"/ˈpæntri/","usIpa":"/ˈpæntri/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"a small room or cupboard for storing food","vi":"phòng chứa thức ăn; tủ đựng thực phẩm"}],"examples":[{"en":"There is another bag of rice in the pantry.","vi":"Vẫn còn một bao gạo nữa ở trong phòng chứa thức ăn.","audioKind":"ex"},{"en":"Keeping a well-organised pantry can help households reduce food waste and manage their grocery budgets.","vi":"Việc duy trì một phòng chứa thực phẩm gọn gàng, ngăn nắp có thể giúp các gia đình giảm thiểu lãng phí thực phẩm và quản lý tốt ngân sách đi chợ.","audioKind":"ex2"}],"collocations":[{"en":"a well-stocked pantry","vi":"phòng chứa thực phẩm trữ đầy đồ"},{"en":"pantry shelves","vi":"các kệ đựng thức ăn trong phòng trữ"},{"en":"pantry staples","vi":"thực phẩm thiết yếu dự trữ"}],"wordFamily":[],"synonyms":["larder"],"antonyms":[],"tipVi":"Chủ yếu dùng để lưu trữ thực phẩm; không đồng nghĩa với căn bếp (kitchen) nơi nấu nướng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tiresome', 'en-c1-64', 'tiresome', '/ˈtaɪərsəm/', 'C1', 'gây phiền toái; mệt mỏi; nhàm chán', 'adj.', 'tire (v.), tired (adj.), tiring (adj.), tirelessly (adv.)', 'Đồng nghĩa: annoying, tedious, irritating · Trái nghĩa: enjoyable, engaging', 'Tiresome mang nghĩa phiền toái, bực mình; còn tiring mang nghĩa làm mệt mỏi về thể xác.', 'Sorting these tiny screws is such a tiresome job.', NULL, 'Việc phân loại mấy con ốc vít nhỏ này đúng là một công việc phiền phức.', '{"wordId":"tiresome","ukIpa":"/ˈtaɪəsəm/","usIpa":"/ˈtaɪərsəm/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Annoying or boring, especially because something continues too long.","vi":"gây phiền toái; mệt mỏi; nhàm chán"}],"examples":[{"en":"Sorting these tiny screws is such a tiresome job.","vi":"Việc phân loại mấy con ốc vít nhỏ này đúng là một công việc phiền phức.","audioKind":"ex"},{"en":"Repeated administrative checks can become tiresome for teachers and reduce the time available for lesson preparation.","vi":"Các đợt kiểm tra hành chính lặp đi lặp lại có thể trở nên phiền toái đối với giáo viên và làm giảm thời gian dành cho việc chuẩn bị bài dạy.","audioKind":"ex2"}],"collocations":[{"en":"a tiresome task","vi":"một nhiệm vụ phiền toái"},{"en":"become tiresome","vi":"trở nên phiền phức"},{"en":"tiresome repetition","vi":"sự lặp lại nhàm chán"}],"wordFamily":["tire (v.)","tired (adj.)","tiring (adj.)","tirelessly (adv.)"],"synonyms":["annoying","tedious","irritating"],"antonyms":["enjoyable","engaging"],"tipVi":"Tiresome mang nghĩa phiền toái, bực mình; còn tiring mang nghĩa làm mệt mỏi về thể xác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forthcoming', 'en-c1-64', 'forthcoming', '/ˌfɔːrθˈkʌmɪŋ/', 'C1', 'sắp tới; sắp diễn ra; sẵn sàng chia sẻ thông tin; cởi mở; có sẵn; sẵn sàng cung cấp', 'adj.', NULL, 'Đồng nghĩa: upcoming, approaching', 'Không chỉ biểu thị "sắp tới", mà còn có thể chỉ sự sẵn sàng tiết lộ thông tin.', 'We bought new walking boots for our forthcoming trip.', NULL, 'Chúng tôi đã mua giày đi bộ đường dài mới cho chuyến đi sắp tới của mình.', '{"wordId":"forthcoming","ukIpa":"/ˌfɔːθˈkʌmɪŋ/","usIpa":"/ˌfɔːrθˈkʌmɪŋ/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Planned or expected to happen or appear soon.","vi":"sắp tới; sắp diễn ra"},{"pos":"adj.","en":"Willing to give information or discuss something openly.","vi":"sẵn sàng chia sẻ thông tin; cởi mở"},{"pos":"adj.","en":"Available or provided when wanted or needed.","vi":"có sẵn; sẵn sàng cung cấp"}],"examples":[{"en":"We bought new walking boots for our forthcoming trip.","vi":"Chúng tôi đã mua giày đi bộ đường dài mới cho chuyến đi sắp tới của mình.","audioKind":"ex"},{"en":"The forthcoming report will assess whether investment in public transport has reduced urban air pollution.","vi":"Báo cáo sắp được công bố sẽ đánh giá xem các khoản đầu tư vào giao thông công cộng có làm giảm ô nhiễm không khí đô thị hay không.","audioKind":"ex2"}],"collocations":[{"en":"a forthcoming report","vi":"một báo cáo sắp tới"},{"en":"forthcoming elections","vi":"các cuộc bầu cử sắp tới"},{"en":"forthcoming about something","vi":"sẵn sàng nói về điều gì đó"},{"en":"no help was forthcoming","vi":"không có sự giúp đỡ nào được đưa ra"}],"wordFamily":[],"synonyms":["upcoming","approaching"],"antonyms":[],"tipVi":"Không chỉ biểu thị \"sắp tới\", mà còn có thể chỉ sự sẵn sàng tiết lộ thông tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_64_1', 'en-c1-64', 'Cách dùng “happening” (n.) — sự việc; điều xảy ra', 'strange happenings  ·  local happenings  ·  everyday happenings', 'Danh từ này thường dùng ở số nhiều là happenings; đối với các sự kiện chính thức, từ event thường được ưu tiên sử dụng hơn.', 'Họ từ (Word Family): happen (v.) | Đồng nghĩa: event, occurrence', '[{"hanzi":"My uncle entertains us with stories of strange happenings.","pinyin":"","meaning":"Chú tôi giải trí cho chúng tôi bằng những câu chuyện về các hiện tượng kỳ lạ."},{"hanzi":"Local newspapers record everyday happenings that help future researchers understand how communities lived and changed.","pinyin":"","meaning":"Các tờ báo địa phương ghi lại những sự kiện thường ngày, giúp các nhà nghiên cứu tương lai hiểu được cách cộng đồng sinh sống và thay đổi."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_64_2', 'en-c1-64', 'Cách dùng “refined” (adj.) — tinh chế; đã qua tinh lọc', 'refined sugar  ·  refined oil  ·  refined manners', 'Khi dùng cho chất liệu, từ này chỉ sự tinh chế; khi dùng cho con người hoặc hành vi, nó chỉ sự thanh lịch, nhã nhặn.', 'Họ từ (Word Family): refine (v.), refinement (n.), refinery (n.), unrefined (adj.) | Đồng nghĩa: purified, cultured · Trái nghĩa: unrefined, crude', '[{"hanzi":"This recipe uses honey instead of refined white sugar.","pinyin":"","meaning":"Công thức này dùng mật ong thay cho đường trắng tinh chế."},{"hanzi":"Public health campaigns often encourage people to reduce their consumption of foods containing large amounts of refined sugar.","pinyin":"","meaning":"Các chiến dịch y tế cộng đồng thường khuyến khích người dân giảm lượng tiêu thụ thực phẩm chứa nhiều đường tinh luyện."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_64_3', 'en-c1-64', 'Cách dùng “petite” (adj.) — nhỏ nhắn; thon thả (dành cho phụ nữ)', 'petite woman  ·  petite frame  ·  petite sizes', 'Thường dùng để miêu tả phụ nữ trưởng thành có thân hình nhỏ nhắn, không đồng nghĩa với việc chỉ đơn thuần là gầy.', NULL, '[{"hanzi":"My sister is petite and often needs shorter trousers.","pinyin":"","meaning":"Chị tôi có vóc dáng nhỏ nhắn nên thường phải mặc quần có ống ngắn hơn."},{"hanzi":"Clothing retailers can serve a wider range of customers by offering petite sizes alongside their standard collections.","pinyin":"","meaning":"Các nhà bán lẻ thời trang có thể phục vụ lượng khách hàng lớn hơn bằng cách cung cấp các kích cỡ nhỏ nhắn bên cạnh các dòng sản phẩm tiêu chuẩn của họ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_64_4', 'en-c1-64', 'Cách dùng “fob” (n.) — móc khóa điện tử; thiết bị điều khiển từ xa nhỏ gọn', 'key fob  ·  electronic fob  ·  fob someone off', 'Thuật ngữ giá giao hàng trên bo tàu trong thương mại thường viết là FOB, cần phân biệt với từ fob viết thường.', NULL, '[{"hanzi":"I pressed the fob to unlock the car.","pinyin":"","meaning":"Tôi bấm vào chiếc chìa khóa điện tử để mở cửa xe."},{"hanzi":"Housing providers increasingly issue residents an electronic fob to control access to shared buildings.","pinyin":"","meaning":"Các đơn vị cung cấp nhà ở ngày càng cấp cho cư dân thẻ từ điện tử để kiểm soát việc ra vào các tòa nhà chung."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_64_1', 'en-c1-64', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_1_1', 'ten_c1_64_1', 'fitting', 'Flowers seemed a fitting gift for our gardening teacher.', 'Flowers seemed a fitting gift for our gardening teacher.', '/ˈfɪtɪŋ/', 'Những bông hoa có vẻ là món quà rất thích hợp dành cho giáo viên dạy môn làm vườn của chúng tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_1_2', 'ten_c1_64_1', 'slender', 'A slender branch bent under the bird''s weight.', 'A slender branch bent under the bird''s weight.', '/ˈslendər/', 'Một nhành cây mảnh mai trĩu xuống dưới sức nặng của chú chim.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_1_3', 'ten_c1_64_1', 'piggyback', 'My uncle gave me a piggyback across the muddy path.', 'My uncle gave me a piggyback across the muddy path.', '/ˈpɪɡibæk/', 'Chú tôi cõng tôi đi qua con đường lầy lội.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_1_4', 'ten_c1_64_1', 'exceedingly', 'The little bakery was exceedingly busy on Saturday morning.', 'The little bakery was exceedingly busy on Saturday morning.', '/ɪkˈsiːdɪŋli/', 'Tiệm bánh nhỏ bận rộn đến mức tất bật vào sáng thứ Bảy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_1_5', 'ten_c1_64_1', 'frugal', 'My frugal neighbour repairs his clothes instead of replacing them.', 'My frugal neighbour repairs his clothes instead of replacing them.', '/ˈfruːɡəl/', 'Người hàng xóm tiết kiệm của tôi thường tự vá quần áo cũ thay vì mua đồ mới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_1_6', 'ten_c1_64_1', 'blindfold', 'He wore a blindfold and guessed each fruit by taste.', 'He wore a blindfold and guessed each fruit by taste.', '/ˈblaɪndfoʊld/', 'Anh ấy đeo khăn bịt mắt và đoán từng loại trái cây bằng vị giác.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_1_7', 'ten_c1_64_1', 'pamper', 'I pamper myself with a warm bath on Sundays.', 'I pamper myself with a warm bath on Sundays.', '/ˈpæmpər/', 'Tôi tự thưởng cho mình một bồn nước ấm vào các ngày Chủ nhật.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_1_8', 'ten_c1_64_1', 'devour', 'After swimming, we devoured the warm bread within minutes.', 'After swimming, we devoured the warm bread within minutes.', '/dɪˈvaʊər/', 'Sau khi bơi lội, chúng tôi đã ăn sạch ổ bánh mì ấm nóng chỉ trong vòng vài phút.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_64_1_1', 'en-c1-64', 'ten_c1_64_1', 'listening', 'listening', 'Flowers seemed a fitting gift for our gardening teacher.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã mua giày đi bộ đường dài mới cho chuyến đi sắp tới của mình.","Vẫn còn một bao gạo nữa ở trong phòng chứa thức ăn.","Chị tôi có vóc dáng nhỏ nhắn nên thường phải mặc quần có ống ngắn hơn.","Những bông hoa có vẻ là món quà rất thích hợp dành cho giáo viên dạy môn làm vườn của chúng tôi."]'::jsonb, 3, 'Flowers seemed a fitting gift for our gardening teacher. → Những bông hoa có vẻ là món quà rất thích hợp dành cho giáo viên dạy môn làm vườn của chúng tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_64_1_2', 'en-c1-64', 'ten_c1_64_1', 'listening', 'listening', 'A slender branch bent under the bird''s weight.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nước phun ra từ ống nước bị vỡ bên dưới bồn rửa chén.","Một nhành cây mảnh mai trĩu xuống dưới sức nặng của chú chim.","Vẫn còn một bao gạo nữa ở trong phòng chứa thức ăn.","Tôi tự thưởng cho mình một bồn nước ấm vào các ngày Chủ nhật."]'::jsonb, 1, 'A slender branch bent under the bird''s weight. → Một nhành cây mảnh mai trĩu xuống dưới sức nặng của chú chim.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_64_1_3', 'en-c1-64', 'ten_c1_64_1', 'listening', 'listening', 'My uncle gave me a piggyback across the muddy path.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi tự thưởng cho mình một bồn nước ấm vào các ngày Chủ nhật.","Chúng tôi vội vã chạy qua nhà ga để kịp chuyến tàu cuối cùng.","Anh ấy vấp phải chiếc đệm và ngã chúi đầu xuống ghế sofa.","Chú tôi cõng tôi đi qua con đường lầy lội."]'::jsonb, 3, 'My uncle gave me a piggyback across the muddy path. → Chú tôi cõng tôi đi qua con đường lầy lội.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_64_2', 'en-c1-64', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_2_1', 'ten_c1_64_2', 'fitting', 'A public library would be a fitting memorial to someone who dedicated their life to education.', 'A public library would be a fitting memorial to someone who dedicated their life to education.', '/ˈfɪtɪŋ/', 'Một thư viện công cộng sẽ là sự tưởng niệm xứng đáng cho một người đã cống hiến cả cuộc đời mình cho giáo dục.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_2_2', 'ten_c1_64_2', 'slender', 'Small businesses often operate with slender profit margins, making them particularly vulnerable to rising energy costs.', 'Small businesses often operate with slender profit margins, making them particularly vulnerable to rising energy costs.', '/ˈslendər/', 'Các doanh nghiệp nhỏ thường hoạt động với biên lợi nhuận rất mỏng, khiến họ đặc biệt dễ bị tổn thương trước tình trạng chi phí năng lượng tăng cao.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_2_3', 'ten_c1_64_2', 'piggyback', 'Small businesses can piggyback on existing delivery networks to reach distant customers without investing in their own vehicles.', 'Small businesses can piggyback on existing delivery networks to reach distant customers without investing in their own vehicles.', '/ˈpɪɡibæk/', 'Các doanh nghiệp nhỏ có thể tận dụng mạng lưới giao hàng sẵn có để tiếp cận khách hàng ở xa mà không cần đầu tư phương tiện riêng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_2_4', 'ten_c1_64_2', 'exceedingly', 'Providing reliable public transport in sparsely populated areas can be exceedingly expensive for local authorities.', 'Providing reliable public transport in sparsely populated areas can be exceedingly expensive for local authorities.', '/ɪkˈsiːdɪŋli/', 'Đối với các cơ quan địa phương, việc cung cấp hệ thống giao thông công cộng đáng tin cậy ở những vùng thưa dân cư có thể cực kỳ tốn kém.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_2_5', 'ten_c1_64_2', 'frugal', 'A frugal lifestyle can reduce household waste without necessarily lowering a family''s quality of life.', 'A frugal lifestyle can reduce household waste without necessarily lowering a family''s quality of life.', '/ˈfruːɡəl/', 'Lối sống tiết kiệm có thể giúp giảm thiểu rác thải sinh hoạt mà không nhất thiết làm giảm chất lượng cuộc sống của gia đình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_64_2_6', 'ten_c1_64_2', 'blindfold', 'Researchers blindfolded the volunteers to investigate how effectively they could identify everyday objects through touch alone.', 'Researchers blindfolded the volunteers to investigate how effectively they could identify everyday objects through touch alone.', '/ˈblaɪndfoʊld/', 'Các nhà nghiên cứu đã bịt mắt các tình nguyện viên để khảo sát khả năng nhận diện các vật dụng hàng ngày chỉ bằng xúc giác của họ một cách hiệu quả ra sao.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_64_2_1', 'en-c1-64', 'ten_c1_64_2', 'listening', 'listening', 'A public library would be a fitting memorial to someone who dedicated their life to education.', NULL, 'Trong câu vừa nghe, từ “fitting” mang nghĩa nào sau đây?', '["cải tiến; trau chuốt; hoàn thiện","thích hợp; phải phép; xứng đáng","lời khẩn cầu; lời thỉnh cầu thiết tha","có khả năng xảy ra, dễ bị (đặc biệt là điều bất lợi)"]'::jsonb, 1, '“fitting” (/ˈfɪtɪŋ/): thích hợp; phải phép; xứng đáng. Câu đầy đủ: A public library would be a fitting memorial to someone who dedicated their life to education.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_64_2_2', 'en-c1-64', 'ten_c1_64_2', 'listening', 'listening', 'Small businesses often operate with slender profit margins, making them particularly vulnerable to rising energy costs.', NULL, 'Trong câu vừa nghe, từ “slender” mang nghĩa nào sau đây?', '["căn bệnh nhẹ; sự khó chịu","liên kết; sáp nhập; gia nhập vào tổ chức lớn","mảnh mai, thon thả (theo cách thu hút hoặc thanh nhã)","héc-ta; công-ta (đơn vị diện tích bằng 10.000 mét vuông)"]'::jsonb, 2, '“slender” (/ˈslendər/): mảnh mai, thon thả (theo cách thu hút hoặc thanh nhã). Câu đầy đủ: Small businesses often operate with slender profit margins, making them particularly vulnerable to rising energy costs.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
