INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_64_2', 'en-c1-64', 'A slender branch bent under the bird''s weight', 'Một nhành cây mảnh mai trĩu xuống dưới sức nặng của chú chim.', 'slender /ˈslendər/', '["branch","bent","bird''s","the","weight","A","under","slender"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_64_3', 'en-c1-64', 'My uncle gave me a piggyback across the muddy path', 'Chú tôi cõng tôi đi qua con đường lầy lội.', 'piggyback /ˈpɪɡibæk/', '["path","My","muddy","uncle","piggyback","me","a","across","the","gave"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_64_4', 'en-c1-64', 'The little bakery was exceedingly busy on Saturday morning', 'Tiệm bánh nhỏ bận rộn đến mức tất bật vào sáng thứ Bảy.', 'exceedingly /ɪkˈsiːdɪŋli/', '["bakery","morning","exceedingly","busy","Saturday","on","was","little","The"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_64_5', 'en-c1-64', 'My frugal neighbour repairs his clothes instead of replacing them', 'Người hàng xóm tiết kiệm của tôi thường tự vá quần áo cũ thay vì mua đồ mới.', 'frugal /ˈfruːɡəl/', '["frugal","instead","clothes","replacing","neighbour","them","of","his","My","repairs"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
