INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_64_7', 'en-c1-64', 'I pamper myself with a warm bath on Sundays', 'Tôi tự thưởng cho mình một bồn nước ấm vào các ngày Chủ nhật.', 'pamper /ˈpæmpər/', '["pamper","Sundays","a","with","warm","I","on","myself","bath"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_64_8', 'en-c1-64', 'After swimming, we devoured the warm bread within minutes', 'Sau khi bơi lội, chúng tôi đã ăn sạch ổ bánh mì ấm nóng chỉ trong vòng vài phút.', 'devour /dɪˈvaʊər/', '["the","After","we","minutes","bread","devoured","warm","swimming","within"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
