INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_64_13', 'en-c1-64', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “headlong” (/ˈhedlɔːŋ/) có nghĩa là gì?', '["né tránh; lảng tránh (để không bị va chạm)","đi dạo nhàn nhã; lang thang","cắm đầu về phía trước, lao đầu xuống; với tốc độ rất nhanh","nán lại; chần chừ không muốn rời đi"]'::jsonb, 2, '“headlong” (adv.): cắm đầu về phía trước, lao đầu xuống; với tốc độ rất nhanh; một cách liều lĩnh, vội vã, không suy tính trước các nguy hiểm hay hậu quả; mang tính hấp tấp, thiếu cẩn trọng và suy nghĩ.', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_64_14', 'en-c1-64', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “To move quickly or make someone move quickly, sometimes roughly.”', '["ramble","fitting","fob","hustle"]'::jsonb, 3, '“hustle” (/ˈhʌsəl/) nghĩa là: hối hả; vội vã; thúc giục.', 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
