INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_1', 'en-c1-64', NULL, 'comprehensive_test', 'listening', 'fitting', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự cộng hưởng (cảm xúc); sức gợi cảm; khả năng lay động","thích hợp; phải phép; xứng đáng","chất cô-cain; thuốc phiện cô-cain","ý định; mục đích"]'::jsonb, 1, 'fitting (/ˈfɪtɪŋ/) → thích hợp; phải phép; xứng đáng; phụ kiện; thiết bị lắp đặt; buổi thử quần áo', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_2', 'en-c1-64', NULL, 'comprehensive_test', 'listening', 'A slender branch bent under the bird''s weight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc phân loại mấy con ốc vít nhỏ này đúng là một công việc phiền phức.","Chú tôi cõng tôi đi qua con đường lầy lội.","Tiệm bánh nhỏ bận rộn đến mức tất bật vào sáng thứ Bảy.","Một nhành cây mảnh mai trĩu xuống dưới sức nặng của chú chim."]'::jsonb, 3, 'A slender branch bent under the bird''s weight. → Một nhành cây mảnh mai trĩu xuống dưới sức nặng của chú chim.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_3', 'en-c1-64', NULL, 'comprehensive_test', 'listening', 'piggyback', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cõng; sự cõng trên lưng","thuộc bậc đại học; thuộc giáo dục đại học","hầm ngục; nhà giam dưới lòng đất","gợi ra; khai thác; dẫn dụ"]'::jsonb, 0, 'piggyback (/ˈpɪɡibæk/) → cõng; sự cõng trên lưng; cõng trên lưng; tận dụng; nhờ vào', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_4', 'en-c1-64', NULL, 'comprehensive_test', 'listening', 'The little bakery was exceedingly busy on Saturday morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một nhành cây mảnh mai trĩu xuống dưới sức nặng của chú chim.","Tiệm bánh nhỏ bận rộn đến mức tất bật vào sáng thứ Bảy.","Một bài phát biểu chào mừng ngắn sẽ diễn ra trước bữa ăn tối.","Vẫn còn một bao gạo nữa ở trong phòng chứa thức ăn."]'::jsonb, 1, 'The little bakery was exceedingly busy on Saturday morning. → Tiệm bánh nhỏ bận rộn đến mức tất bật vào sáng thứ Bảy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_5', 'en-c1-64', NULL, 'comprehensive_test', 'listening', 'frugal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nạn mù chữ; tình trạng không biết đọc biết viết","thợ chuyển nhà; công ty chuyển đồ","tiết kiệm; giản dị","hiện lên lờ mờ, xuất hiện với hình thù to lớn và có vẻ đe dọa"]'::jsonb, 2, 'frugal (/ˈfruːɡəl/) → tiết kiệm; giản dị', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_6', 'en-c1-64', NULL, 'comprehensive_test', 'listening', 'He wore a blindfold and guessed each fruit by taste.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy vấp phải chiếc đệm và ngã chúi đầu xuống ghế sofa.","Anh ấy đeo khăn bịt mắt và đoán từng loại trái cây bằng vị giác.","Tiệm bánh nhỏ bận rộn đến mức tất bật vào sáng thứ Bảy.","Chúng tôi vội vã chạy qua nhà ga để kịp chuyến tàu cuối cùng."]'::jsonb, 1, 'He wore a blindfold and guessed each fruit by taste. → Anh ấy đeo khăn bịt mắt và đoán từng loại trái cây bằng vị giác.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_7', 'en-c1-64', NULL, 'comprehensive_test', 'listening', 'pamper', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phổ biến; thông thường; quen thuộc","thợ thủ công; thợ lành nghề","hổ cái; con cọp cái","chiều chuộng; cưng nựng; nuông chiều"]'::jsonb, 3, 'pamper (/ˈpæmpər/) → chiều chuộng; cưng nựng; nuông chiều', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_8', 'en-c1-64', NULL, 'comprehensive_test', 'listening', 'After swimming, we devoured the warm bread within minutes.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi nán lại bên ngoài rạp chiếu phim để trò chuyện về bộ phim vừa xem.","Sau khi bơi lội, chúng tôi đã ăn sạch ổ bánh mì ấm nóng chỉ trong vòng vài phút.","Tôi né một vũng nước và suýt làm rơi đồ mua sắm.","Anh trai tôi lần nào đi tàu chuyến dài cũng ngủ gật."]'::jsonb, 1, 'After swimming, we devoured the warm bread within minutes. → Sau khi bơi lội, chúng tôi đã ăn sạch ổ bánh mì ấm nóng chỉ trong vòng vài phút.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_9', 'en-c1-64', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Careful with money or resources, avoiding unnecessary spending or waste.”?', '["blindfold","coincide","fob","frugal"]'::jsonb, 3, 'frugal (/ˈfruːɡəl/) → tiết kiệm; giản dị', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_10', 'en-c1-64', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A cloth covering the eyes to prevent someone from seeing.”?', '["petite","fob","blindfold","forthcoming"]'::jsonb, 2, 'blindfold (/ˈblaɪndfoʊld/) → khăn bịt mắt; đồ bịt mắt', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_11', 'en-c1-64', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To give someone special care, comfort, or excessive attention”?', '["slender","pamper","happening","indispensable"]'::jsonb, 1, 'pamper (/ˈpæmpər/) → chiều chuộng; cưng nựng; nuông chiều', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_12', 'en-c1-64', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To eat something quickly and eagerly.”?', '["pamper","hustle","pantry","devour"]'::jsonb, 3, 'devour (/dɪˈvaʊər/) → ăn ngấu nghiến; ăn vội vàng', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_13', 'en-c1-64', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To move quickly out of the way of something.”?', '["dodge","forthcoming","happening","pamper"]'::jsonb, 0, 'dodge (/dɑːdʒ/) → né tránh; lảng tránh (để không bị va chạm)', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
