INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_18', 'en-c1-64', NULL, 'comprehensive_test', 'reading', NULL, 'A public library would be a fitting memorial to someone who dedicated their life to education.', 'Dựa vào câu trên, từ “fitting” có nghĩa phù hợp nhất là gì?', '["dễ cháy; dễ bắt lửa","bản song ca; khúc hát/khúc nhạc đôi cho hai người biểu diễn","thích hợp; phải phép; xứng đáng","thú mỏ vịt"]'::jsonb, 2, 'fitting: thích hợp; phải phép; xứng đáng; phụ kiện; thiết bị lắp đặt; buổi thử quần áo. Dịch cả câu: Một thư viện công cộng sẽ là sự tưởng niệm xứng đáng cho một người đã cống hiến cả cuộc đời mình cho giáo dục.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_19', 'en-c1-64', NULL, 'comprehensive_test', 'reading', NULL, 'Small businesses often operate with slender profit margins, making them particularly vulnerable to rising energy costs.', 'Dựa vào câu trên, từ “slender” có nghĩa phù hợp nhất là gì?', '["chắc là; hầu như chắc chắn; có lẽ là","làm đau đớn; gây phiền muộn; hành hạ","vòng hoa; vòng lá","mảnh mai, thon thả (theo cách thu hút hoặc thanh nhã)"]'::jsonb, 3, 'slender: mảnh mai, thon thả (theo cách thu hút hoặc thanh nhã); nhỏ bé, ít ỏi, mong manh (về số lượng hoặc cơ hội). Dịch cả câu: Các doanh nghiệp nhỏ thường hoạt động với biên lợi nhuận rất mỏng, khiến họ đặc biệt dễ bị tổn thương trước tình trạng chi phí năng lượng tăng cao.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_20', 'en-c1-64', NULL, 'comprehensive_test', 'reading', NULL, 'Small businesses can piggyback on existing delivery networks to reach distant customers without investing in their own vehicles.', 'Dựa vào câu trên, từ “piggyback” có nghĩa phù hợp nhất là gì?', '["sức bền; sự chịu đựng; độ dẻo dai","xảy ra sau đó; tiếp theo","cõng; sự cõng trên lưng","lao dốc; sụt giảm mạnh"]'::jsonb, 2, 'piggyback: cõng; sự cõng trên lưng; cõng trên lưng; tận dụng; nhờ vào. Dịch cả câu: Các doanh nghiệp nhỏ có thể tận dụng mạng lưới giao hàng sẵn có để tiếp cận khách hàng ở xa mà không cần đầu tư phương tiện riêng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_21', 'en-c1-64', NULL, 'comprehensive_test', 'reading', NULL, 'Providing reliable public transport in sparsely populated areas can be exceedingly expensive for local authorities.', 'Dựa vào câu trên, từ “exceedingly” có nghĩa phù hợp nhất là gì?', '["cực kỳ; vô cùng","niken","áp kế; khí áp kế","sự đánh giá lại; sự xem xét lại"]'::jsonb, 0, 'exceedingly: cực kỳ; vô cùng. Dịch cả câu: Đối với các cơ quan địa phương, việc cung cấp hệ thống giao thông công cộng đáng tin cậy ở những vùng thưa dân cư có thể cực kỳ tốn kém.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_22', 'en-c1-64', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phòng chứa thức ăn; tủ đựng thực phẩm”', '["nuance","patron","strategic","pantry"]'::jsonb, 3, 'phòng chứa thức ăn; tủ đựng thực phẩm → pantry (/ˈpæntri/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_23', 'en-c1-64', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gây phiền toái; mệt mỏi; nhàm chán”', '["diffuse","financier","accompaniment","tiresome"]'::jsonb, 3, 'gây phiền toái; mệt mỏi; nhàm chán → tiresome (/ˈtaɪərsəm/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_64_24', 'en-c1-64', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sắp tới; sắp diễn ra”', '["commissioner","ultraviolet","radiant","forthcoming"]'::jsonb, 3, 'sắp tới; sắp diễn ra → forthcoming (/ˌfɔːrθˈkʌmɪŋ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-65', 'en', 'Bài 65: Đời sống hằng ngày (6) - CEFR C1', 'CEFR C1', 'C1 · Đời sống', '27 từ vựng Tiếng Anh CEFR C1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5065, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consecutive', 'en-c1-65', 'consecutive', '/kənˈsekjətɪv/', 'C1', 'liên tiếp; liên tục không ngắt quãng', 'adj.', 'consecutively (adv.)', 'Đồng nghĩa: successive · Trái nghĩa: non-consecutive', 'Nhấn mạnh tính liên tục nối tiếp nhau không gián đoạn, thường bổ nghĩa cho số ngày hoặc số lần.', 'It has rained for five consecutive days this week.', NULL, 'Trời đã mưa suốt năm ngày liên tiếp trong tuần này.', '{"wordId":"consecutive","ukIpa":"/kənˈsekjətɪv/","usIpa":"/kənˈsekjətɪv/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"following one after another without any interruption","vi":"liên tiếp; liên tục không ngắt quãng"}],"examples":[{"en":"It has rained for five consecutive days this week.","vi":"Trời đã mưa suốt năm ngày liên tiếp trong tuần này.","audioKind":"ex"},{"en":"Several consecutive years of low rainfall have reduced agricultural output and increased pressure on regional water supplies.","vi":"Nhiều năm có lượng mưa thấp liên tiếp đã làm giảm sản lượng nông nghiệp và gia tăng áp lực lên nguồn nước trong vùng.","audioKind":"ex2"}],"collocations":[{"en":"consecutive days","vi":"những ngày liên tiếp"},{"en":"consecutive victories","vi":"chuỗi trận thắng liên tiếp"},{"en":"for three consecutive years","vi":"trong ba năm liên tiếp"}],"wordFamily":["consecutively (adv.)"],"synonyms":["successive"],"antonyms":["non-consecutive"],"tipVi":"Nhấn mạnh tính liên tục nối tiếp nhau không gián đoạn, thường bổ nghĩa cho số ngày hoặc số lần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tolerable', 'en-c1-65', 'tolerable', '/ˈtɑːlərəbl/', 'C1', 'có thể chịu đựng được; tạm được; kha khá; chấp nhận được', 'adj.', 'tolerate (v.), tolerably (adv.), intolerable (adj.), toleration (n.)', 'Đồng nghĩa: bearable, endurable, acceptable · Trái nghĩa: intolerable, unbearable', 'Từ tolerable mang nghĩa có thể chịu đựng được; trong khi tolerant chỉ một người có thái độ bao dung, khoan dung.', 'The heat became tolerable once we opened the windows.', NULL, 'Cái nóng trở nên dễ chịu hơn ngay khi chúng tôi mở các cửa sổ ra.', '{"wordId":"tolerable","ukIpa":"/ˈtɒlərəbl/","usIpa":"/ˈtɑːlərəbl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"unpleasant but possible to endure","vi":"có thể chịu đựng được"},{"pos":"adj.","en":"acceptable in quality, though not particularly good","vi":"tạm được; kha khá; chấp nhận được"}],"examples":[{"en":"The heat became tolerable once we opened the windows.","vi":"Cái nóng trở nên dễ chịu hơn ngay khi chúng tôi mở các cửa sổ ra.","audioKind":"ex"},{"en":"Improved ventilation can keep classroom temperatures at tolerable levels without relying entirely on air conditioning.","vi":"Hệ thống thông gió được cải thiện có thể duy trì nhiệt độ lớp học ở mức có thể chịu đựng được mà không phải phụ thuộc hoàn toàn vào điều hòa.","audioKind":"ex2"}],"collocations":[{"en":"tolerable pain","vi":"cơn đau có thể chịu đựng được"},{"en":"tolerable level","vi":"mức độ có thể chấp nhận"},{"en":"barely tolerable","vi":"hầu như không thể chịu nổi"}],"wordFamily":["tolerate (v.)","tolerably (adv.)","intolerable (adj.)","toleration (n.)"],"synonyms":["bearable","endurable","acceptable"],"antonyms":["intolerable","unbearable"],"tipVi":"Từ tolerable mang nghĩa có thể chịu đựng được; trong khi tolerant chỉ một người có thái độ bao dung, khoan dung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_filth', 'en-c1-65', 'filth', '/fɪlθ/', 'C1', 'rác rưởi; chất dơ bẩn; vết nhơ; tài liệu đồi trụy; ngôn từ tục tĩu', 'n.', 'filthy (adj.), filthiness (n.)', 'Đồng nghĩa: grime, dirt · Trái nghĩa: cleanliness', 'Đây là danh từ không đếm được, mang sắc thái nặng nề và mạnh hơn từ dirt, thường thể hiện cảm giác ghê tởm.', 'My boots were covered in filth after the walk.', NULL, 'Đôi bốt của tôi dính đầy chất bẩn sau buổi đi dạo.', '{"wordId":"filth","ukIpa":"/fɪlθ/","usIpa":"/fɪlθ/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"thick or disgusting dirt","vi":"rác rưởi; chất dơ bẩn; vết nhơ"},{"pos":"n.","en":"sexual material or language considered extremely offensive","vi":"tài liệu đồi trụy; ngôn từ tục tĩu"}],"examples":[{"en":"My boots were covered in filth after the walk.","vi":"Đôi bốt của tôi dính đầy chất bẩn sau buổi đi dạo.","audioKind":"ex"},{"en":"Without regular waste collection, filth can accumulate in residential areas and create serious public health risks.","vi":"Nếu không có dịch vụ thu gom rác thải thường xuyên, chất bẩn có thể tích tụ tại các khu dân cư và gây ra những rủi ro nghiêm trọng cho sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"covered in filth","vi":"dính đầy chất bẩn"},{"en":"live in filth","vi":"sống trong môi trường nhơ nhớp"},{"en":"accumulated filth","vi":"chất bẩn tích tụ"}],"wordFamily":["filthy (adj.)","filthiness (n.)"],"synonyms":["grime","dirt"],"antonyms":["cleanliness"],"tipVi":"Đây là danh từ không đếm được, mang sắc thái nặng nề và mạnh hơn từ dirt, thường thể hiện cảm giác ghê tởm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coil', 'en-c1-65', 'coil', '/kɔɪl/', 'C1', 'cuộn lại; xoắn lại thành vòng; cuộn; ống xoắn; vòng dây', 'v.', 'coiled (adj.), uncoil (v.)', 'Đồng nghĩa: wind, curl · Trái nghĩa: uncoil', 'Dùng làm động từ ngoại động từ hoặc nội động từ, nhấn mạnh hành động uốn thành vòng tròn hoặc hình xoắn ốc.', 'Please coil the rope before putting it away.', NULL, 'Vui lòng cuộn tròn sợi dây thừng lại trước khi cất đi.', '{"wordId":"coil","ukIpa":"/kɔɪl/","usIpa":"/kɔɪl/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to wind into a series of circles or rings","vi":"cuộn lại; xoắn lại thành vòng"},{"pos":"n.","en":"a series of connected loops in wire, rope, or tubing","vi":"cuộn; ống xoắn; vòng dây"}],"examples":[{"en":"Please coil the rope before putting it away.","vi":"Vui lòng cuộn tròn sợi dây thừng lại trước khi cất đi.","audioKind":"ex"},{"en":"Engineers coil long pipes beneath buildings so that heat can be transferred efficiently from the ground.","vi":"Các kỹ sư bố trí những đường ống dài uốn lượn bên dưới các tòa nhà để nhiệt có thể được truyền từ lòng đất lên một cách hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"coil a rope","vi":"cuộn dây thừng"},{"en":"a coil of wire","vi":"một cuộn dây điện"},{"en":"a heating coil","vi":"cuộn dây sưởi"},{"en":"coil around","vi":"quấn quanh"}],"wordFamily":["coiled (adj.)","uncoil (v.)"],"synonyms":["wind","curl"],"antonyms":["uncoil"],"tipVi":"Dùng làm động từ ngoại động từ hoặc nội động từ, nhấn mạnh hành động uốn thành vòng tròn hoặc hình xoắn ốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sectional', 'en-c1-65', 'sectional', '/ˈsekʃənəl/', 'C1', 'thuộc dạng lắp ghép; cấu thành từ nhiều phần; cục bộ; thuộc về một nhóm hoặc bộ phận riêng lẻ thay vì toàn thể', 'adj.', 'section (n.), section (v.)', NULL, 'Trong nội thất dùng để chỉ dạng ghép nối; sectional interests chỉ lợi ích của một nhóm cụ thể.', 'We rearranged our sectional sofa to face the window.', NULL, 'Chúng tôi đã sắp xếp lại chiếc ghế sofa lắp ghép của mình để quay về hướng cửa sổ.', '{"wordId":"sectional","ukIpa":"/ˈsekʃənəl/","usIpa":"/ˈsekʃənəl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Made of separate sections that can be joined together","vi":"thuộc dạng lắp ghép; cấu thành từ nhiều phần"},{"pos":"adj.","en":"Relating to one group or part rather than the whole","vi":"cục bộ; thuộc về một nhóm hoặc bộ phận riêng lẻ thay vì toàn thể"}],"examples":[{"en":"We rearranged our sectional sofa to face the window.","vi":"Chúng tôi đã sắp xếp lại chiếc ghế sofa lắp ghép của mình để quay về hướng cửa sổ.","audioKind":"ex"},{"en":"Governments should balance sectional interests with the broader needs of society when designing public policies.","vi":"Chính phủ nên cân bằng lợi ích cục bộ với các nhu cầu rộng lớn hơn của xã hội khi thiết kế các chính sách công.","audioKind":"ex2"}],"collocations":[{"en":"sectional sofa","vi":"ghế sofa lắp ghép"},{"en":"sectional furniture","vi":"đồ nội thất lắp ghép"},{"en":"sectional interests","vi":"lợi ích cục bộ"},{"en":"sectional view","vi":"hình chiếu cắt"}],"wordFamily":["section (n.)","section (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong nội thất dùng để chỉ dạng ghép nối; sectional interests chỉ lợi ích của một nhóm cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fumble', 'en-c1-65', 'fumble', '/ˈfʌmbl/', 'C1', 'lục lọi vụng về; sờ soạng tìm kiếm; lóng ngóng làm rơi; xử lý vụng về', 'v.', 'fumbling (adj.)', NULL, 'Cụm từ fumble for dùng để chỉ việc dò dẫm tìm kiếm; trong khi fumble with diễn tả sự lóng ngóng khi tương tác, cầm nắm.', 'I fumbled for my keys in the dark hallway.', NULL, 'Tôi loay hoay tìm chìa khóa trong hành lang tối tăm.', '{"wordId":"fumble","ukIpa":"/ˈfʌmbl/","usIpa":"/ˈfʌmbl/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To search for or handle something with awkward hand movements.","vi":"lục lọi vụng về; sờ soạng tìm kiếm"},{"pos":"v.","en":"To fail to hold something or deal with something smoothly.","vi":"lóng ngóng làm rơi; xử lý vụng về"}],"examples":[{"en":"I fumbled for my keys in the dark hallway.","vi":"Tôi loay hoay tìm chìa khóa trong hành lang tối tăm.","audioKind":"ex"},{"en":"Users often fumble with unfamiliar controls, highlighting the importance of intuitive design in public transport systems.","vi":"Người dùng thường lóng ngóng khi thao tác với các nút điều khiển lạ lẫm, qua đó làm nổi bật tầm quan trọng của thiết kế trực quan trong các hệ thống giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"fumble for keys","vi":"lục tìm chìa khóa"},{"en":"fumble with a lock","vi":"loay hoay với ổ khóa"},{"en":"fumble the ball","vi":"làm rơi bóng"}],"wordFamily":["fumbling (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ fumble for dùng để chỉ việc dò dẫm tìm kiếm; trong khi fumble with diễn tả sự lóng ngóng khi tương tác, cầm nắm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eventful', 'en-c1-65', 'eventful', '/ɪˈventfəl/', 'C1', 'nhiều sự kiện; đầy biến động; nhiều chuyện', 'adj.', 'event (n.), uneventful (adj.)', 'Trái nghĩa: uneventful', 'Chỉ sự việc xảy ra nhiều điều đáng chú ý, không nhất thiết là chuyện xấu.', 'After an eventful morning, we finally sat down for lunch.', NULL, 'Sau một buổi sáng đầy biến động, cuối cùng chúng tôi cũng ngồi xuống ăn trưa.', '{"wordId":"eventful","ukIpa":"/ɪˈventfəl/","usIpa":"/ɪˈventfəl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Full of important, interesting, or unexpected events.","vi":"nhiều sự kiện; đầy biến động; nhiều chuyện"}],"examples":[{"en":"After an eventful morning, we finally sat down for lunch.","vi":"Sau một buổi sáng đầy biến động, cuối cùng chúng tôi cũng ngồi xuống ăn trưa.","audioKind":"ex"},{"en":"An eventful period of political reform transformed the country''s education system and expanded access to schooling.","vi":"Một giai đoạn cải cách chính trị đầy sóng gió đã làm thay đổi hệ thống giáo dục của đất nước và mở rộng khả năng tiếp cận trường học.","audioKind":"ex2"}],"collocations":[{"en":"an eventful day","vi":"một ngày bận rộn nhiều sự kiện"},{"en":"an eventful journey","vi":"một chuyến đi nhiều trải nghiệm"},{"en":"an eventful life","vi":"một cuộc đời phong phú"}],"wordFamily":["event (n.)","uneventful (adj.)"],"synonyms":[],"antonyms":["uneventful"],"tipVi":"Chỉ sự việc xảy ra nhiều điều đáng chú ý, không nhất thiết là chuyện xấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accustom', 'en-c1-65', 'accustom', '/əˈkʌstəm/', 'C1', 'làm cho quen với', 'v.', 'accustomed (adj.), unaccustomed (adj.)', 'Đồng nghĩa: habituate', 'Trong cấu trúc accustom oneself to, từ to là một giới từ, theo sau là danh từ hoặc danh động từ.', 'I slowly accustomed myself to sleeping with the window open.', NULL, 'Tôi từ từ tập cho bản thân quen với việc ngủ mở cửa sổ.', '{"wordId":"accustom","ukIpa":"/əˈkʌstəm/","usIpa":"/əˈkʌstəm/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To make someone familiar or comfortable with something through experience.","vi":"làm cho quen với"}],"examples":[{"en":"I slowly accustomed myself to sleeping with the window open.","vi":"Tôi từ từ tập cho bản thân quen với việc ngủ mở cửa sổ.","audioKind":"ex"},{"en":"Schools can accustom students to collaborative work by regularly assigning tasks that require shared responsibility.","vi":"Các trường học có thể giúp học sinh quen với công việc cộng tác bằng cách thường xuyên giao các nhiệm vụ đòi hỏi trách nhiệm chung.","audioKind":"ex2"}],"collocations":[{"en":"accustom yourself to","vi":"tập cho bản thân quen với"},{"en":"become accustomed to","vi":"trở nên quen thuộc với"},{"en":"be accustomed to","vi":"đã quen với"}],"wordFamily":["accustomed (adj.)","unaccustomed (adj.)"],"synonyms":["habituate"],"antonyms":[],"tipVi":"Trong cấu trúc accustom oneself to, từ to là một giới từ, theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sift', 'en-c1-65', 'sift', '/sɪft/', 'C1', 'rây (bột, cát); sàng; sàng lọc; tra cứu kỹ lưỡng; xem xét tỉ mỉ', 'v.', 'sifter (n.)', 'Đồng nghĩa: sieve, screen', 'Cụm sift through diễn tả hành động xem xét rất kỹ lưỡng để tìm kiếm thông tin hữu ích.', 'Sift the flour before adding it to the bowl.', NULL, 'Hãy rây bột thật kỹ trước khi cho vào tô.', '{"wordId":"sift","ukIpa":"/sɪft/","usIpa":"/sɪft/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To pass material through a sieve to separate its parts.","vi":"rây (bột, cát); sàng"},{"pos":"v.","en":"To examine material carefully to find what is useful.","vi":"sàng lọc; tra cứu kỹ lưỡng; xem xét tỉ mỉ"}],"examples":[{"en":"Sift the flour before adding it to the bowl.","vi":"Hãy rây bột thật kỹ trước khi cho vào tô.","audioKind":"ex"},{"en":"Researchers must sift through large amounts of evidence before drawing reliable conclusions about the causes of unemployment.","vi":"Các nhà nghiên cứu phải sàng lọc qua rất nhiều bằng chứng trước khi rút ra những kết luận đáng tin cậy về nguyên nhân gây ra tình trạng thất nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"sift flour","vi":"rây bột"},{"en":"sift through evidence","vi":"sàng lọc bằng chứng"},{"en":"sift out","vi":"sàng lọc ra; loại bỏ"}],"wordFamily":["sifter (n.)"],"synonyms":["sieve","screen"],"antonyms":[],"tipVi":"Cụm sift through diễn tả hành động xem xét rất kỹ lưỡng để tìm kiếm thông tin hữu ích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_squirt', 'en-c1-65', 'squirt', '/skwɝːt/', 'C1', 'bơm; xịt; phun; tia nước; dòng chất lỏng nhỏ', 'v.', NULL, 'Đồng nghĩa: spray, spurt', 'Thường dùng squirt chất lỏng onto/into nơi nào đó, nhấn mạnh tia chất lỏng phun ra hẹp.', 'She squirted some lemon juice over the grilled fish.', NULL, 'Cô ấy vắt một ít nước chanh lên con cá nướng.', '{"wordId":"squirt","ukIpa":"/skwɜːt/","usIpa":"/skwɝːt/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"Force liquid out through a small opening in a narrow stream.","vi":"bơm; xịt; phun"},{"pos":"n.","en":"A small amount of liquid released in a narrow stream.","vi":"tia nước; dòng chất lỏng nhỏ"}],"examples":[{"en":"She squirted some lemon juice over the grilled fish.","vi":"Cô ấy vắt một ít nước chanh lên con cá nướng.","audioKind":"ex"},{"en":"Water-saving irrigation systems squirt small amounts of water directly onto roots, reducing waste in dry regions.","vi":"Hệ thống tưới tiết kiệm nước phun một lượng nước nhỏ trực tiếp vào gốc cây, giúp giảm lãng phí ở các vùng khô hạn.","audioKind":"ex2"}],"collocations":[{"en":"squirt water","vi":"phun nước"},{"en":"squirt juice over something","vi":"vắt nước cốt lên món gì đó"},{"en":"a squirt of sauce","vi":"một ít nước sốt xịt ra"}],"wordFamily":[],"synonyms":["spray","spurt"],"antonyms":[],"tipVi":"Thường dùng squirt chất lỏng onto/into nơi nào đó, nhấn mạnh tia chất lỏng phun ra hẹp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intact', 'en-c1-65', 'intact', '/ɪnˈtækt/', 'C1', 'nguyên vẹn, không bị hư hại, không bị thay đổi', 'adj.', NULL, 'Đồng nghĩa: undamaged, whole, unbroken · Trái nghĩa: damaged, broken', 'Thường dùng sau remain hoặc leave, nhấn mạnh sự hoàn thiện và không bị tổn hại.', 'The box was crushed, but the cups remained intact.', NULL, 'Cái hộp bị bẹp dúm, nhưng những chiếc cốc vẫn còn nguyên vẹn.', '{"wordId":"intact","ukIpa":"/ɪnˈtækt/","usIpa":"/ɪnˈtækt/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Complete and not damaged, altered, or missing any parts","vi":"nguyên vẹn, không bị hư hại, không bị thay đổi"}],"examples":[{"en":"The box was crushed, but the cups remained intact.","vi":"Cái hộp bị bẹp dúm, nhưng những chiếc cốc vẫn còn nguyên vẹn.","audioKind":"ex"},{"en":"Careful restoration allows historic buildings to remain intact while meeting the safety requirements of modern urban life.","vi":"Việc trùng tu cẩn thận giúp các tòa nhà lịch sử giữ được vẻ nguyên vẹn trong khi vẫn đáp ứng các yêu cầu an toàn của đời sống đô thị hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"remain intact","vi":"giữ nguyên vẹn"},{"en":"leave intact","vi":"để nguyên trạng"},{"en":"fully intact","vi":"hoàn toàn nguyên vẹn"}],"wordFamily":[],"synonyms":["undamaged","whole","unbroken"],"antonyms":["damaged","broken"],"tipVi":"Thường dùng sau remain hoặc leave, nhấn mạnh sự hoàn thiện và không bị tổn hại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_continual', 'en-c1-65', 'continual', '/kənˈtɪnjuəl/', 'C1', 'lặp đi lặp lại; dồn dập; liên miên không dứt', 'adj.', 'continually (adv.), continue (v.), continuation (n.), continuous (adj.)', 'Đồng nghĩa: repeated, persistent · Trái nghĩa: occasional', 'Continual thường chỉ việc lặp đi lặp lại; continuous nhấn mạnh tính liên tục không ngắt quãng.', 'The continual interruptions made it hard to finish cooking.', NULL, 'Những tiếng gián đoạn liên hồi khiến việc nấu ăn trở nên khó khăn.', '{"wordId":"continual","ukIpa":"/kənˈtɪnjuəl/","usIpa":"/kənˈtɪnjuəl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Happening repeatedly, often with short breaks.","vi":"lặp đi lặp lại; dồn dập"},{"pos":"adj.","en":"Continuing over a period without stopping.","vi":"liên miên không dứt"}],"examples":[{"en":"The continual interruptions made it hard to finish cooking.","vi":"Những tiếng gián đoạn liên hồi khiến việc nấu ăn trở nên khó khăn.","audioKind":"ex"},{"en":"Continual changes in education policy can prevent teachers from developing effective long-term approaches to classroom learning.","vi":"Sự thay đổi liên tục trong chính sách giáo dục có thể cản trở giáo viên xây dựng các phương pháp giảng dạy lâu dài và hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"continual interruptions","vi":"sự quấy rầy liên tục"},{"en":"continual improvement","vi":"sự cải tiến liên tục"},{"en":"continual changes","vi":"những thay đổi liên miên"}],"wordFamily":["continually (adv.)","continue (v.)","continuation (n.)","continuous (adj.)"],"synonyms":["repeated","persistent"],"antonyms":["occasional"],"tipVi":"Continual thường chỉ việc lặp đi lặp lại; continuous nhấn mạnh tính liên tục không ngắt quãng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_token', 'en-c1-65', 'token', '/ˈtoʊkən/', 'C1', 'đồng xu giả định; thẻ cào; phiếu quà tặng; vật kỷ niệm; biểu hiện; mang tính hình thức; tượng trưng', 'n.', NULL, NULL, 'Cụm từ a token of đi kèm với danh từ chỉ cảm xúc để diễn tả một thành ý hoặc sự tri ân.', 'I dropped a token into the machine and played.', NULL, 'Tôi thả một đồng xu vào máy và bắt đầu chơi.', '{"wordId":"token","ukIpa":"/ˈtəʊkən/","usIpa":"/ˈtoʊkən/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A special disc or voucher used instead of money.","vi":"đồng xu giả định; thẻ cào; phiếu quà tặng"},{"pos":"n.","en":"Something given or done to express a feeling.","vi":"vật kỷ niệm; biểu hiện"},{"pos":"adj.","en":"Done merely to appear helpful or compliant, with little effect.","vi":"mang tính hình thức; tượng trưng"}],"examples":[{"en":"I dropped a token into the machine and played.","vi":"Tôi thả một đồng xu vào máy và bắt đầu chơi.","audioKind":"ex"},{"en":"Critics argue that token environmental measures cannot address the scale of pollution in rapidly expanding cities.","vi":"Các nhà phê bình cho rằng những biện pháp bảo vệ môi trường mang tính hình thức không thể giải quyết được mức độ ô nhiễm tại các thành phố đang mở rộng nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"a token of appreciation","vi":"một món quà bày tỏ lòng biết ơn"},{"en":"a token gesture","vi":"một cử chỉ mang tính hình thức"},{"en":"a token payment","vi":"một khoản thanh toán tượng trưng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ a token of đi kèm với danh từ chỉ cảm xúc để diễn tả một thành ý hoặc sự tri ân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hiss', 'en-c1-65', 'hiss', '/hɪs/', 'C1', 'phát ra tiếng kêu rít; khì khì; tiếng rít; tiếng xì xì', 'v.', 'hissing (n.)', NULL, 'Cụm hiss at có thể dùng để chỉ việc rít lên đe dọa hoặc phát ra tiếng la ó phản đối.', 'The cat hissed when the puppy came too close.', NULL, 'Con mèo phát ra tiếng khì khì khi chú chó con tiến lại quá gần.', '{"wordId":"hiss","ukIpa":"/hɪs/","usIpa":"/hɪs/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To make a long, sharp sound like escaping steam.","vi":"phát ra tiếng kêu rít; khì khì"},{"pos":"n.","en":"A long, sharp sound made by escaping air or steam.","vi":"tiếng rít; tiếng xì xì"}],"examples":[{"en":"The cat hissed when the puppy came too close.","vi":"Con mèo phát ra tiếng khì khì khi chú chó con tiến lại quá gần.","audioKind":"ex"},{"en":"Engineers investigated a persistent hiss from the heating system to identify possible leaks and prevent energy waste.","vi":"Các kỹ sư đã kiểm tra tiếng rít liên tục phát ra từ hệ thống sưởi để xác định vị trí rò rỉ có thể xảy ra và ngăn ngừa lãng phí năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"hiss at someone","vi":"phát tiếng kêu rít với ai đó"},{"en":"a faint hiss","vi":"tiếng rít nhỏ"},{"en":"a hiss of steam","vi":"tiếng hơi nước xì xì"}],"wordFamily":["hissing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm hiss at có thể dùng để chỉ việc rít lên đe dọa hoặc phát ra tiếng la ó phản đối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fling', 'en-c1-65', 'fling', '/flɪŋ/', 'C1', 'ném mạnh; quăng quật; quãng thời gian ngắn vui chơi thỏa thích', 'v.', NULL, 'Đồng nghĩa: hurl, throw', 'Dạng quá khứ và quá khứ phân từ đều là flung, nhấn mạnh hành động mạnh mẽ, dứt khoát.', 'He flung his muddy boots into the empty bucket.', NULL, 'Anh ấy vứt đôi bốt dính bùn của mình vào cái xô trống không.', '{"wordId":"fling","ukIpa":"/flɪŋ/","usIpa":"/flɪŋ/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"To throw or move something suddenly and forcefully.","vi":"ném mạnh; quăng quật"},{"pos":"n.","en":"A short period of freely enjoying an activity.","vi":"quãng thời gian ngắn vui chơi thỏa thích"}],"examples":[{"en":"He flung his muddy boots into the empty bucket.","vi":"Anh ấy vứt đôi bốt dính bùn của mình vào cái xô trống không.","audioKind":"ex"},{"en":"During severe storms, powerful winds can fling loose debris across roads, creating serious hazards for drivers and pedestrians.","vi":"Trong những trận bão lớn, gió mạnh có thể hất văng các mảnh vụn rải rác khắp đường đi, gây nguy hiểm nghiêm trọng cho tài xế và người đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"fling open a door","vi":"mở toang cửa"},{"en":"fling your arms around someone","vi":"vòng tay ôm chầm lấy ai đó"},{"en":"fling yourself into something","vi":"lao mình vào việc gì đó"},{"en":"a final fling","vi":"cuộc vui chơi thỏa thích cuối cùng"}],"wordFamily":[],"synonyms":["hurl","throw"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là flung, nhấn mạnh hành động mạnh mẽ, dứt khoát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_illegible', 'en-c1-65', 'illegible', '/ɪˈledʒəbl/', 'C1', 'khó đọc; không đọc được; không thể đọc nổi (do chữ viết không rõ)', 'adj.', 'legible (adj.), legibility (n.), illegibly (adv.)', 'Đồng nghĩa: unreadable, indecipherable · Trái nghĩa: legible', 'illegible chỉ chữ viết nhìn không rõ, không phải là nội dung bài viết khó hiểu.', 'Rain had made the address on the envelope illegible.', NULL, 'Mưa đã làm cho địa chỉ trên phong bì trở nên không thể đọc được.', '{"wordId":"illegible","ukIpa":"/ɪˈledʒəbl/","usIpa":"/ɪˈledʒəbl/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"impossible or very difficult to read because of unclear writing","vi":"khó đọc; không đọc được; không thể đọc nổi (do chữ viết không rõ)"}],"examples":[{"en":"Rain had made the address on the envelope illegible.","vi":"Mưa đã làm cho địa chỉ trên phong bì trở nên không thể đọc được.","audioKind":"ex"},{"en":"Illegible handwriting on medical forms can cause errors that put patient safety at risk.","vi":"Chữ viết tay khó đọc trên các mẫu đơn y tế có thể gây ra sai sót, đe dọa sự an toàn của bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"illegible handwriting","vi":"chữ viết tay khó đọc"},{"en":"almost illegible","vi":"gần như không thể đọc được"},{"en":"render something illegible","vi":"làm cho cái gì trở nên không thể đọc nổi"}],"wordFamily":["legible (adj.)","legibility (n.)","illegibly (adv.)"],"synonyms":["unreadable","indecipherable"],"antonyms":["legible"],"tipVi":"illegible chỉ chữ viết nhìn không rõ, không phải là nội dung bài viết khó hiểu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_granary', 'en-c1-65', 'granary', '/ˈɡreɪnəri/', 'C1', 'vựa lúa; kho chứa ngũ cốc; nhà kho lúa', 'n.', NULL, NULL, 'chỉ công trình chuyên chứa ngũ cốc; barn có phạm vi rộng hơn, có thể dùng để chứa vật nuôi.', 'The farmer carried another sack of wheat into the granary.', NULL, 'Người nông dân vác thêm một bao lúa mì nữa vào trong vựa lúa.', '{"wordId":"granary","ukIpa":"/ˈɡrænəri/","usIpa":"/ˈɡreɪnəri/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A building where harvested grain is stored.","vi":"vựa lúa; kho chứa ngũ cốc; nhà kho lúa"}],"examples":[{"en":"The farmer carried another sack of wheat into the granary.","vi":"Người nông dân vác thêm một bao lúa mì nữa vào trong vựa lúa.","audioKind":"ex"},{"en":"A well-maintained granary can protect harvested crops from moisture and reduce food losses in rural communities.","vi":"Một nhà kho lúa được bảo quản tốt có thể bảo vệ hoa màu thu hoạch khỏi bị ẩm mốc và giảm thiểu thất thoát lương thực ở các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"store grain in a granary","vi":"trữ ngũ cốc trong kho"},{"en":"wooden granary","vi":"kho lúa bằng gỗ"},{"en":"communal granary","vi":"vựa lúa chung"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"chỉ công trình chuyên chứa ngũ cốc; barn có phạm vi rộng hơn, có thể dùng để chứa vật nuôi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_innocuous', 'en-c1-65', 'innocuous', '/ɪˈnɑːkjuəs/', 'C1', 'vô hại; không có hại; không xúc phạm ai', 'adj.', 'innocuously (adv.), innocuousness (n.)', 'Đồng nghĩa: harmless, inoffensive · Trái nghĩa: harmful, offensive', 'Có thể dùng để chỉ vật chất không gây hại, hoặc lời nói không làm người khác khó chịu, xúc phạm.', 'Her question seemed innocuous, so I answered without hesitation.', NULL, 'Câu hỏi của cô ấy có vẻ vô hại, thế nên tôi đã trả lời mà không chút do dự.', '{"wordId":"innocuous","ukIpa":"/ɪˈnɒkjuəs/","usIpa":"/ɪˈnɑːkjuəs/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Not likely to cause harm or offend anyone.","vi":"vô hại; không có hại; không xúc phạm ai"}],"examples":[{"en":"Her question seemed innocuous, so I answered without hesitation.","vi":"Câu hỏi của cô ấy có vẻ vô hại, thế nên tôi đã trả lời mà không chút do dự.","audioKind":"ex"},{"en":"Seemingly innocuous household products can damage aquatic ecosystems when large quantities enter rivers through wastewater.","vi":"Những sản phẩm gia dụng thoạt nhìn có vẻ vô hại vẫn có thể tàn phá các hệ sinh thái dưới nước khi lượng lớn thải vào sông ngòi qua nước thải.","audioKind":"ex2"}],"collocations":[{"en":"innocuous remark","vi":"lời nói vô hại"},{"en":"seemingly innocuous","vi":"có vẻ vô hại"},{"en":"innocuous substance","vi":"chất vô hại"}],"wordFamily":["innocuously (adv.)","innocuousness (n.)"],"synonyms":["harmless","inoffensive"],"antonyms":["harmful","offensive"],"tipVi":"Có thể dùng để chỉ vật chất không gây hại, hoặc lời nói không làm người khác khó chịu, xúc phạm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alight', 'en-c1-65', 'alight', '/əˈlaɪt/', 'C1', 'đang cháy; sáng rực; xuống xe; đáp xuống', 'adj.', NULL, 'Đồng nghĩa: burning, disembark', 'Tính từ thường làm vị ngữ; khi xuống phương tiện giao thông dùng cấu trúc alight from.', 'The candles were still alight when we arrived.', NULL, 'Những cây nến vẫn đang cháy rực khi chúng tôi đến nơi.', '{"wordId":"alight","ukIpa":"/əˈlaɪt/","usIpa":"/əˈlaɪt/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"Burning or shining brightly.","vi":"đang cháy; sáng rực"},{"pos":"v.","en":"To get off a vehicle or land on a surface.","vi":"xuống xe; đáp xuống"}],"examples":[{"en":"The candles were still alight when we arrived.","vi":"Những cây nến vẫn đang cháy rực khi chúng tôi đến nơi.","audioKind":"ex"},{"en":"Passengers should wait until the bus has stopped completely before they alight from the vehicle.","vi":"Hành khách nên đợi cho đến khi xe buýt dừng hẳn rồi mới bước xuống xe.","audioKind":"ex2"}],"collocations":[{"en":"set something alight","vi":"làm cho bốc cháy; châm lửa đốt"},{"en":"alight from a train","vi":"xuống tàu"},{"en":"alight on a branch","vi":"đậu trên cành cây"}],"wordFamily":[],"synonyms":["burning","disembark"],"antonyms":[],"tipVi":"Tính từ thường làm vị ngữ; khi xuống phương tiện giao thông dùng cấu trúc alight from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quirk', 'en-c1-65', 'quirk', '/kwɝːk/', 'C1', 'một thói quen hoặc đặc điểm khác thường; tật nhỏ, nét kỳ quặc; một sự kiện kỳ lạ do tình cờ; sự ngẫu nhiên ngộ nghĩnh', 'n.', 'quirky (adj.), quirkiness (n.)', 'Đồng nghĩa: peculiarity, oddity', 'Thường chỉ thói quen nhỏ hoặc đặc điểm vô hại, không nhất thiết mang nghĩa tiêu cực.', 'One of her quirks is sorting socks by colour.', NULL, 'Một trong những tật nhỏ của cô ấy là phân loại tất theo màu sắc.', '{"wordId":"quirk","ukIpa":"/kwɜːk/","usIpa":"/kwɝːk/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"an unusual habit or feature of someone or something","vi":"một thói quen hoặc đặc điểm khác thường; tật nhỏ, nét kỳ quặc"},{"pos":"n.","en":"a strange event caused by chance","vi":"một sự kiện kỳ lạ do tình cờ; sự ngẫu nhiên ngộ nghĩnh"}],"examples":[{"en":"One of her quirks is sorting socks by colour.","vi":"Một trong những tật nhỏ của cô ấy là phân loại tất theo màu sắc.","audioKind":"ex"},{"en":"A quirk of the housing market has left some coastal villages cheaper than nearby inland towns.","vi":"Một sự ngẫu nhiên của thị trường nhà ở đã khiến một số ngôi làng ven biển có giá rẻ hơn các thị trấn nội địa lân cận.","audioKind":"ex2"}],"collocations":[{"en":"a personality quirk","vi":"một nét tính cách kỳ quặc"},{"en":"a quirk of fate","vi":"sự trớ trêu của số phận"},{"en":"individual quirks","vi":"những nét độc đáo cá nhân"}],"wordFamily":["quirky (adj.)","quirkiness (n.)"],"synonyms":["peculiarity","oddity"],"antonyms":[],"tipVi":"Thường chỉ thói quen nhỏ hoặc đặc điểm vô hại, không nhất thiết mang nghĩa tiêu cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cradle', 'en-c1-65', 'cradle', '/ˈkreɪdəl/', 'C1', 'chiếc nôi; cái nôi em bé; cái nôi; vùng đất phát tích; ôm ấp; nâng niu', 'n.', NULL, NULL, 'Cụm từ the cradle of thường được dùng theo nghĩa ẩn dụ chỉ nguồn gốc khai sinh của một nền văn minh hoặc hoạt động nào đó.', 'The baby slept peacefully in a wooden cradle.', NULL, 'Đứa bé đang ngủ say sưa trong một chiếc nôi bằng gỗ.', '{"wordId":"cradle","ukIpa":"/ˈkreɪdəl/","usIpa":"/ˈkreɪdəl/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"A small bed for a baby that can rock.","vi":"chiếc nôi; cái nôi em bé"},{"pos":"n.","en":"The place where something important first developed.","vi":"cái nôi; vùng đất phát tích"},{"pos":"v.","en":"Hold someone or something gently and protectively.","vi":"ôm ấp; nâng niu"}],"examples":[{"en":"The baby slept peacefully in a wooden cradle.","vi":"Đứa bé đang ngủ say sưa trong một chiếc nôi bằng gỗ.","audioKind":"ex"},{"en":"The region is often described as a cradle of agriculture because of its early farming settlements.","vi":"Vùng đất này thường được miêu tả là cái nôi của nền nông nghiệp do sự tồn tại của các khu định cư canh tác sớm tại đây.","audioKind":"ex2"}],"collocations":[{"en":"rock a cradle","vi":"ru nôi"},{"en":"the cradle of civilisation","vi":"cái nôi của nền văn minh"},{"en":"cradle a baby","vi":"ôm nâng niu một đứa trẻ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ the cradle of thường được dùng theo nghĩa ẩn dụ chỉ nguồn gốc khai sinh của một nền văn minh hoặc hoạt động nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_squeal', 'en-c1-65', 'squeal', '/skwiːl/', 'C1', 'kêu chít chít; thét lên; phát ra tiếng rít; tiếng thét; tiếng kêu chít chít; tiếng rít; tố giác; khai ra; chỉ điểm', 'v.', NULL, 'Đồng nghĩa: shriek, screech', 'Biểu đạt "tố giác" (squeal on sb) thuộc văn phong không trang trọng.', 'The children squealed with delight as the puppy appeared.', NULL, 'Bọn trẻ reo lên thích thú khi chú cún con xuất hiện.', '{"wordId":"squeal","ukIpa":"/skwiːl/","usIpa":"/skwiːl/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"to make a long, high, sharp sound","vi":"kêu chít chít; thét lên; phát ra tiếng rít"},{"pos":"n.","en":"a long, high, sharp cry or noise","vi":"tiếng thét; tiếng kêu chít chít; tiếng rít"},{"pos":"v.","en":"to tell an authority about someone else''s wrongdoing","vi":"tố giác; khai ra; chỉ điểm"}],"examples":[{"en":"The children squealed with delight as the puppy appeared.","vi":"Bọn trẻ reo lên thích thú khi chú cún con xuất hiện.","audioKind":"ex"},{"en":"Residents reported that train wheels often squeal on sharp bends, causing noise disturbance in nearby homes.","vi":"Cư dân phản ánh rằng bánh xe lửa thường phát ra tiếng rít gay gắt ở các khúc cua gấp, gây ô nhiễm tiếng tiếng ồn cho các hộ gia đình gần đó.","audioKind":"ex2"}],"collocations":[{"en":"squeal with delight","vi":"vui mừng hét lên"},{"en":"a squeal of excitement","vi":"tiếng hét phấn khích"},{"en":"squeal on someone","vi":"tố giác ai đó"}],"wordFamily":[],"synonyms":["shriek","screech"],"antonyms":[],"tipVi":"Biểu đạt \"tố giác\" (squeal on sb) thuộc văn phong không trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hover', 'en-c1-65', 'hover', '/ˈhʌvər/', 'C1', 'lơ lửng trên không; bay treo; quanh quẩn ở gần; chần chừ quanh đó; dao động ở một mức độ hoặc con số nhất định', 'v.', 'hovering (adj.)', NULL, 'Ý nghĩa cốt lõi là ở lỳ một chỗ không đi, không giống với soar (vút bay/bay cao).', 'A small helicopter hovered above the empty field.', NULL, 'Một chiếc trực thăng nhỏ lơ lửng phía trên cánh đồng trống.', '{"wordId":"hover","ukIpa":"/ˈhɒvə/","usIpa":"/ˈhʌvər/","cefr":"C1","topic":"daily","senses":[{"pos":"v.","en":"Stay in one place in the air.","vi":"lơ lửng trên không; bay treo"},{"pos":"v.","en":"Stay nearby, often waiting or watching.","vi":"quanh quẩn ở gần; chần chừ quanh đó"},{"pos":"v.","en":"Remain close to a particular level or amount.","vi":"dao động ở một mức độ hoặc con số nhất định"}],"examples":[{"en":"A small helicopter hovered above the empty field.","vi":"Một chiếc trực thăng nhỏ lơ lửng phía trên cánh đồng trống.","audioKind":"ex"},{"en":"When unemployment rates hover around current levels, governments may need to invest more in vocational training.","vi":"Khi tỷ lệ thất nghiệp dao động quanh mức hiện tại, chính phủ có thể cần đầu tư nhiều hơn vào đào tạo nghề.","audioKind":"ex2"}],"collocations":[{"en":"hover overhead","vi":"lơ lửng trên đầu"},{"en":"hover nearby","vi":"quanh quẩn ở gần"},{"en":"hover around a level","vi":"dao động quanh một mức"}],"wordFamily":["hovering (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Ý nghĩa cốt lõi là ở lỳ một chỗ không đi, không giống với soar (vút bay/bay cao).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wedge', 'en-c1-65', 'wedge', '/wedʒ/', 'C1', 'cái nêm; vật hình nêm; nêm; chèn; nhét chặt', 'n.', NULL, NULL, 'Cụm từ drive a wedge between mang nghĩa bóng là khơi mào chia rẽ hoặc làm rạn nứt quan hệ.', 'He slid a wooden wedge under the heavy door.', NULL, 'Anh ấy luồn một cái nêm gỗ vào dưới cánh cửa nặng.', '{"wordId":"wedge","ukIpa":"/wedʒ/","usIpa":"/wedʒ/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"An object thick at one end and thin at the other.","vi":"cái nêm; vật hình nêm"},{"pos":"v.","en":"To push something tightly into a narrow space.","vi":"nêm; chèn; nhét chặt"}],"examples":[{"en":"He slid a wooden wedge under the heavy door.","vi":"Anh ấy luồn một cái nêm gỗ vào dưới cánh cửa nặng.","audioKind":"ex"},{"en":"Disagreements over resource allocation can drive a wedge between neighbouring communities and weaken regional cooperation.","vi":"Những bất đồng về việc phân bổ nguồn lực có thể tạo ra rạn nứt giữa các cộng đồng láng giềng và làm suy yếu hợp tác khu vực.","audioKind":"ex2"}],"collocations":[{"en":"a wooden wedge","vi":"miếng nêm gỗ"},{"en":"a wedge of cheese","vi":"một miếng phô mai hình nêm"},{"en":"wedge the door open","vi":"chèn cửa cho mở"},{"en":"drive a wedge between","vi":"gây rạn nứt giữa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ drive a wedge between mang nghĩa bóng là khơi mào chia rẽ hoặc làm rạn nứt quan hệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hinge', 'en-c1-65', 'hinge', '/hɪndʒ/', 'C1', 'bản lề; khớp nối; phụ thuộc vào', 'n.', 'hinged (adj.)', NULL, 'hinge on đi sau bởi danh từ hoặc mệnh đề, diễn tả ý nghĩa "phụ thuộc vào".', 'The rusty hinge squeaks whenever I open the cupboard.', NULL, 'Cái bản lề bị rỉ sét phát ra tiếng kêu cót cét mỗi khi tôi mở tủ.', '{"wordId":"hinge","ukIpa":"/hɪndʒ/","usIpa":"/hɪndʒ/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"a joint that allows a door or lid to swing","vi":"bản lề; khớp nối"},{"pos":"v.","en":"to depend entirely on something, used with on or upon","vi":"phụ thuộc vào"}],"examples":[{"en":"The rusty hinge squeaks whenever I open the cupboard.","vi":"Cái bản lề bị rỉ sét phát ra tiếng kêu cót cét mỗi khi tôi mở tủ.","audioKind":"ex"},{"en":"The success of public transport reforms may hinge on reliable funding and sustained support from local residents.","vi":"Sự thành công của các cải cách giao thông công cộng có thể phụ thuộc vào nguồn tài chính ổn định và sự hỗ trợ lâu dài từ người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"door hinge","vi":"bản lề cửa"},{"en":"rusty hinge","vi":"bản lề rỉ sét"},{"en":"hinge on","vi":"phụ thuộc vào"}],"wordFamily":["hinged (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"hinge on đi sau bởi danh từ hoặc mệnh đề, diễn tả ý nghĩa \"phụ thuộc vào\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clearance', 'en-c1-65', 'clearance', '/ˈklɪrəns/', 'C1', 'dọn dẹp; thanh thải; sự cho phép chính thức; giấy phép; bán hàng hạ giá; xả kho', 'n.', 'clear (v.), clear (adj.)', NULL, 'clearance sale là chương trình giảm giá xả kho; thủ tục thông quan dùng customs clearance.', 'The garden clearance took us most of Saturday.', NULL, 'Việc dọn dẹp khu vườn đã ngốn gần hết ngày thứ Bảy của chúng tôi.', '{"wordId":"clearance","ukIpa":"/ˈklɪərəns/","usIpa":"/ˈklɪrəns/","cefr":"C1","topic":"daily","senses":[{"pos":"n.","en":"The removal of unwanted objects or material from a place","vi":"dọn dẹp; thanh thải"},{"pos":"n.","en":"Official permission to do something or enter a place","vi":"sự cho phép chính thức; giấy phép"},{"pos":"n.","en":"The sale of remaining goods at reduced prices","vi":"bán hàng hạ giá; xả kho"}],"examples":[{"en":"The garden clearance took us most of Saturday.","vi":"Việc dọn dẹp khu vườn đã ngốn gần hết ngày thứ Bảy của chúng tôi.","audioKind":"ex"},{"en":"Large-scale forest clearance can destroy wildlife habitats and increase the risk of soil erosion.","vi":"Việc dọn dẹp rừng quy mô lớn có thể phá hủy môi trường sống của động vật hoang dã và làm tăng nguy cơ xói mòn đất.","audioKind":"ex2"}],"collocations":[{"en":"forest clearance","vi":"phát quang rừng"},{"en":"security clearance","vi":"thẩm định an ninh"},{"en":"customs clearance","vi":"thủ tục thông quan"},{"en":"clearance sale","vi":"bán hàng xả kho"}],"wordFamily":["clear (v.)","clear (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"clearance sale là chương trình giảm giá xả kho; thủ tục thông quan dùng customs clearance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_homely', 'en-c1-65', 'homely', '/ˈhoʊmli/', 'C1', 'ấm cúng; giản dị như ở nhà; không có vẻ ngoài bắt mắt; kém sắc (thường dùng trong tiếng Anh-Mỹ)', 'adj.', 'home (n.), homeliness (n.)', 'Đồng nghĩa: cosy, plain', 'Tiếng Anh-Anh thường mang nghĩa ấm cúng; tiếng Anh-Mỹ thường mang nghĩa kém sắc, nên cẩn trọng khi miêu tả ngoại hình.', 'The little café felt homely, with cushions on every chair.', NULL, 'Quán cà phê nhỏ mang lại cảm giác rất ấm cúng với những chiếc gối tựa trên từng chiếc ghế.', '{"wordId":"homely","ukIpa":"/ˈhəʊmli/","usIpa":"/ˈhoʊmli/","cefr":"C1","topic":"daily","senses":[{"pos":"adj.","en":"simple and comfortable in a way that feels like home","vi":"ấm cúng; giản dị như ở nhà"},{"pos":"adj.","en":"not physically attractive, especially in American English","vi":"không có vẻ ngoài bắt mắt; kém sắc (thường dùng trong tiếng Anh-Mỹ)"}],"examples":[{"en":"The little café felt homely, with cushions on every chair.","vi":"Quán cà phê nhỏ mang lại cảm giác rất ấm cúng với những chiếc gối tựa trên từng chiếc ghế.","audioKind":"ex"},{"en":"A homely atmosphere in residential care facilities may help older people feel more comfortable and secure.","vi":"Không gian ấm cúng tại các cơ sở chăm sóc người cao tuổi có thể giúp người lớn tuổi cảm thấy thoải mái và an tâm hơn.","audioKind":"ex2"}],"collocations":[{"en":"homely atmosphere","vi":"không khí ấm cúng"},{"en":"homely surroundings","vi":"môi trường thân thuộc như ở nhà"},{"en":"homely face","vi":"giao diện giản dị"}],"wordFamily":["home (n.)","homeliness (n.)"],"synonyms":["cosy","plain"],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường mang nghĩa ấm cúng; tiếng Anh-Mỹ thường mang nghĩa kém sắc, nên cẩn trọng khi miêu tả ngoại hình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_65_1', 'en-c1-65', 'Cách dùng “cradle” (n.) — chiếc nôi; cái nôi em bé', 'rock a cradle  ·  the cradle of civilisation  ·  cradle a baby', 'Cụm từ the cradle of thường được dùng theo nghĩa ẩn dụ chỉ nguồn gốc khai sinh của một nền văn minh hoặc hoạt động nào đó.', NULL, '[{"hanzi":"The baby slept peacefully in a wooden cradle.","pinyin":"","meaning":"Đứa bé đang ngủ say sưa trong một chiếc nôi bằng gỗ."},{"hanzi":"The region is often described as a cradle of agriculture because of its early farming settlements.","pinyin":"","meaning":"Vùng đất này thường được miêu tả là cái nôi của nền nông nghiệp do sự tồn tại của các khu định cư canh tác sớm tại đây."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_65_2', 'en-c1-65', 'Cách dùng “fumble” (v.) — lục lọi vụng về; sờ soạng tìm kiếm', 'fumble for keys  ·  fumble with a lock  ·  fumble the ball', 'Cụm từ fumble for dùng để chỉ việc dò dẫm tìm kiếm; trong khi fumble with diễn tả sự lóng ngóng khi tương tác, cầm nắm.', 'Họ từ (Word Family): fumbling (adj.)', '[{"hanzi":"I fumbled for my keys in the dark hallway.","pinyin":"","meaning":"Tôi loay hoay tìm chìa khóa trong hành lang tối tăm."},{"hanzi":"Users often fumble with unfamiliar controls, highlighting the importance of intuitive design in public transport systems.","pinyin":"","meaning":"Người dùng thường lóng ngóng khi thao tác với các nút điều khiển lạ lẫm, qua đó làm nổi bật tầm quan trọng của thiết kế trực quan trong các hệ thống giao thông công cộng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_65_3', 'en-c1-65', 'Cách dùng “homely” (adj.) — ấm cúng; giản dị như ở nhà', 'homely atmosphere  ·  homely surroundings  ·  homely face', 'Tiếng Anh-Anh thường mang nghĩa ấm cúng; tiếng Anh-Mỹ thường mang nghĩa kém sắc, nên cẩn trọng khi miêu tả ngoại hình.', 'Họ từ (Word Family): home (n.), homeliness (n.) | Đồng nghĩa: cosy, plain', '[{"hanzi":"The little café felt homely, with cushions on every chair.","pinyin":"","meaning":"Quán cà phê nhỏ mang lại cảm giác rất ấm cúng với những chiếc gối tựa trên từng chiếc ghế."},{"hanzi":"A homely atmosphere in residential care facilities may help older people feel more comfortable and secure.","pinyin":"","meaning":"Không gian ấm cúng tại các cơ sở chăm sóc người cao tuổi có thể giúp người lớn tuổi cảm thấy thoải mái và an tâm hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_65_4', 'en-c1-65', 'Cách dùng “tolerable” (adj.) — có thể chịu đựng được', 'tolerable pain  ·  tolerable level  ·  barely tolerable', 'Từ tolerable mang nghĩa có thể chịu đựng được; trong khi tolerant chỉ một người có thái độ bao dung, khoan dung.', 'Họ từ (Word Family): tolerate (v.), tolerably (adv.), intolerable (adj.), toleration (n.) | Đồng nghĩa: bearable, endurable, acceptable · Trái nghĩa: intolerable, unbearable', '[{"hanzi":"The heat became tolerable once we opened the windows.","pinyin":"","meaning":"Cái nóng trở nên dễ chịu hơn ngay khi chúng tôi mở các cửa sổ ra."},{"hanzi":"Improved ventilation can keep classroom temperatures at tolerable levels without relying entirely on air conditioning.","pinyin":"","meaning":"Hệ thống thông gió được cải thiện có thể duy trì nhiệt độ lớp học ở mức có thể chịu đựng được mà không phải phụ thuộc hoàn toàn vào điều hòa."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_65_1', 'en-c1-65', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_1_1', 'ten_c1_65_1', 'consecutive', 'It has rained for five consecutive days this week.', 'It has rained for five consecutive days this week.', '/kənˈsekjətɪv/', 'Trời đã mưa suốt năm ngày liên tiếp trong tuần này.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_1_2', 'ten_c1_65_1', 'tolerable', 'The heat became tolerable once we opened the windows.', 'The heat became tolerable once we opened the windows.', '/ˈtɑːlərəbl/', 'Cái nóng trở nên dễ chịu hơn ngay khi chúng tôi mở các cửa sổ ra.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_1_3', 'ten_c1_65_1', 'filth', 'My boots were covered in filth after the walk.', 'My boots were covered in filth after the walk.', '/fɪlθ/', 'Đôi bốt của tôi dính đầy chất bẩn sau buổi đi dạo.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_1_4', 'ten_c1_65_1', 'coil', 'Please coil the rope before putting it away.', 'Please coil the rope before putting it away.', '/kɔɪl/', 'Vui lòng cuộn tròn sợi dây thừng lại trước khi cất đi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_1_5', 'ten_c1_65_1', 'sectional', 'We rearranged our sectional sofa to face the window.', 'We rearranged our sectional sofa to face the window.', '/ˈsekʃənəl/', 'Chúng tôi đã sắp xếp lại chiếc ghế sofa lắp ghép của mình để quay về hướng cửa sổ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_1_6', 'ten_c1_65_1', 'fumble', 'I fumbled for my keys in the dark hallway.', 'I fumbled for my keys in the dark hallway.', '/ˈfʌmbl/', 'Tôi loay hoay tìm chìa khóa trong hành lang tối tăm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_1_7', 'ten_c1_65_1', 'eventful', 'After an eventful morning, we finally sat down for lunch.', 'After an eventful morning, we finally sat down for lunch.', '/ɪˈventfəl/', 'Sau một buổi sáng đầy biến động, cuối cùng chúng tôi cũng ngồi xuống ăn trưa.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_1_8', 'ten_c1_65_1', 'accustom', 'I slowly accustomed myself to sleeping with the window open.', 'I slowly accustomed myself to sleeping with the window open.', '/əˈkʌstəm/', 'Tôi từ từ tập cho bản thân quen với việc ngủ mở cửa sổ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_65_1_1', 'en-c1-65', 'ten_c1_65_1', 'listening', 'listening', 'It has rained for five consecutive days this week.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy vắt một ít nước chanh lên con cá nướng.","Mưa đã làm cho địa chỉ trên phong bì trở nên không thể đọc được.","Trời đã mưa suốt năm ngày liên tiếp trong tuần này.","Bọn trẻ reo lên thích thú khi chú cún con xuất hiện."]'::jsonb, 2, 'It has rained for five consecutive days this week. → Trời đã mưa suốt năm ngày liên tiếp trong tuần này.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_65_1_2', 'en-c1-65', 'ten_c1_65_1', 'listening', 'listening', 'The heat became tolerable once we opened the windows.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một chiếc trực thăng nhỏ lơ lửng phía trên cánh đồng trống.","Mưa đã làm cho địa chỉ trên phong bì trở nên không thể đọc được.","Cái nóng trở nên dễ chịu hơn ngay khi chúng tôi mở các cửa sổ ra.","Chúng tôi đã sắp xếp lại chiếc ghế sofa lắp ghép của mình để quay về hướng cửa sổ."]'::jsonb, 2, 'The heat became tolerable once we opened the windows. → Cái nóng trở nên dễ chịu hơn ngay khi chúng tôi mở các cửa sổ ra.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_65_1_3', 'en-c1-65', 'ten_c1_65_1', 'listening', 'listening', 'My boots were covered in filth after the walk.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bọn trẻ reo lên thích thú khi chú cún con xuất hiện.","Cô ấy vắt một ít nước chanh lên con cá nướng.","Đôi bốt của tôi dính đầy chất bẩn sau buổi đi dạo.","Con mèo phát ra tiếng khì khì khi chú chó con tiến lại quá gần."]'::jsonb, 2, 'My boots were covered in filth after the walk. → Đôi bốt của tôi dính đầy chất bẩn sau buổi đi dạo.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_65_2', 'en-c1-65', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_2_1', 'ten_c1_65_2', 'consecutive', 'Several consecutive years of low rainfall have reduced agricultural output and increased pressure on regional water supplies.', 'Several consecutive years of low rainfall have reduced agricultural output and increased pressure on regional water supplies.', '/kənˈsekjətɪv/', 'Nhiều năm có lượng mưa thấp liên tiếp đã làm giảm sản lượng nông nghiệp và gia tăng áp lực lên nguồn nước trong vùng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_2_2', 'ten_c1_65_2', 'tolerable', 'Improved ventilation can keep classroom temperatures at tolerable levels without relying entirely on air conditioning.', 'Improved ventilation can keep classroom temperatures at tolerable levels without relying entirely on air conditioning.', '/ˈtɑːlərəbl/', 'Hệ thống thông gió được cải thiện có thể duy trì nhiệt độ lớp học ở mức có thể chịu đựng được mà không phải phụ thuộc hoàn toàn vào điều hòa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_2_3', 'ten_c1_65_2', 'filth', 'Without regular waste collection, filth can accumulate in residential areas and create serious public health risks.', 'Without regular waste collection, filth can accumulate in residential areas and create serious public health risks.', '/fɪlθ/', 'Nếu không có dịch vụ thu gom rác thải thường xuyên, chất bẩn có thể tích tụ tại các khu dân cư và gây ra những rủi ro nghiêm trọng cho sức khỏe cộng đồng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_2_4', 'ten_c1_65_2', 'coil', 'Engineers coil long pipes beneath buildings so that heat can be transferred efficiently from the ground.', 'Engineers coil long pipes beneath buildings so that heat can be transferred efficiently from the ground.', '/kɔɪl/', 'Các kỹ sư bố trí những đường ống dài uốn lượn bên dưới các tòa nhà để nhiệt có thể được truyền từ lòng đất lên một cách hiệu quả.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_2_5', 'ten_c1_65_2', 'sectional', 'Governments should balance sectional interests with the broader needs of society when designing public policies.', 'Governments should balance sectional interests with the broader needs of society when designing public policies.', '/ˈsekʃənəl/', 'Chính phủ nên cân bằng lợi ích cục bộ với các nhu cầu rộng lớn hơn của xã hội khi thiết kế các chính sách công.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_65_2_6', 'ten_c1_65_2', 'fumble', 'Users often fumble with unfamiliar controls, highlighting the importance of intuitive design in public transport systems.', 'Users often fumble with unfamiliar controls, highlighting the importance of intuitive design in public transport systems.', '/ˈfʌmbl/', 'Người dùng thường lóng ngóng khi thao tác với các nút điều khiển lạ lẫm, qua đó làm nổi bật tầm quan trọng của thiết kế trực quan trong các hệ thống giao thông công cộng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_65_2_1', 'en-c1-65', 'ten_c1_65_2', 'listening', 'listening', 'Several consecutive years of low rainfall have reduced agricultural output and increased pressure on regional water supplies.', NULL, 'Trong câu vừa nghe, từ “consecutive” mang nghĩa nào sau đây?', '["có lợi; thuận lợi; hữu ích","hệ thống điện báo; máy điện báo","bằng độc quyền sáng chế; quyền sáng chế","liên tiếp; liên tục không ngắt quãng"]'::jsonb, 3, '“consecutive” (/kənˈsekjətɪv/): liên tiếp; liên tục không ngắt quãng. Câu đầy đủ: Several consecutive years of low rainfall have reduced agricultural output and increased pressure on regional water supplies.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_65_2_2', 'en-c1-65', 'ten_c1_65_2', 'listening', 'listening', 'Improved ventilation can keep classroom temperatures at tolerable levels without relying entirely on air conditioning.', NULL, 'Trong câu vừa nghe, từ “tolerable” mang nghĩa nào sau đây?', '["mõm (động vật)","có thể chịu đựng được","tích lũy dần; thu về dần theo thời gian","răng bánh xe; bánh răng"]'::jsonb, 1, '“tolerable” (/ˈtɑːlərəbl/): có thể chịu đựng được. Câu đầy đủ: Improved ventilation can keep classroom temperatures at tolerable levels without relying entirely on air conditioning.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
