INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_65_2', 'en-c1-65', 'The heat became tolerable once we opened the windows', 'Cái nóng trở nên dễ chịu hơn ngay khi chúng tôi mở các cửa sổ ra.', 'tolerable /ˈtɑːlərəbl/', '["the","once","became","heat","tolerable","opened","The","windows","we"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
