INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_65_4', 'en-c1-65', 'Please coil the rope before putting it away', 'Vui lòng cuộn tròn sợi dây thừng lại trước khi cất đi.', 'coil /kɔɪl/', '["coil","the","it","before","rope","away","Please","putting"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_65_5', 'en-c1-65', 'We rearranged our sectional sofa to face the window', 'Chúng tôi đã sắp xếp lại chiếc ghế sofa lắp ghép của mình để quay về hướng cửa sổ.', 'sectional /ˈsekʃənəl/', '["sofa","window","the","our","sectional","to","We","rearranged","face"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_65_6', 'en-c1-65', 'I fumbled for my keys in the dark hallway', 'Tôi loay hoay tìm chìa khóa trong hành lang tối tăm.', 'fumble /ˈfʌmbl/', '["my","I","in","for","keys","fumbled","hallway","the","dark"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_c1_65_7', 'en-c1-65', 'After an eventful morning, we finally sat down for lunch', 'Sau một buổi sáng đầy biến động, cuối cùng chúng tôi cũng ngồi xuống ăn trưa.', 'eventful /ɪˈventfəl/', '["we","finally","morning","eventful","an","lunch","for","down","After","sat"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
