INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_1', 'en-c1-65', NULL, 'comprehensive_test', 'listening', 'consecutive', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về tế bào (của sinh vật sống)","tối cao; cao nhất về cấp bậc, quyền hạn hoặc tầm quan trọng","liên tiếp; liên tục không ngắt quãng","lang thang; đi lang thang; thả bộ"]'::jsonb, 2, 'consecutive (/kənˈsekjətɪv/) → liên tiếp; liên tục không ngắt quãng', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_2', 'en-c1-65', NULL, 'comprehensive_test', 'listening', 'The heat became tolerable once we opened the windows.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi từ từ tập cho bản thân quen với việc ngủ mở cửa sổ.","Cái bản lề bị rỉ sét phát ra tiếng kêu cót cét mỗi khi tôi mở tủ.","Cái nóng trở nên dễ chịu hơn ngay khi chúng tôi mở các cửa sổ ra.","Mưa đã làm cho địa chỉ trên phong bì trở nên không thể đọc được."]'::jsonb, 2, 'The heat became tolerable once we opened the windows. → Cái nóng trở nên dễ chịu hơn ngay khi chúng tôi mở các cửa sổ ra.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_3', 'en-c1-65', NULL, 'comprehensive_test', 'listening', 'filth', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thợ chuyển nhà; công ty chuyển đồ","đánh giá; phỏng đoán; đo lường","phân biệt đối xử; thực hiện phân biệt chủng tộc","rác rưởi; chất dơ bẩn; vết nhơ"]'::jsonb, 3, 'filth (/fɪlθ/) → rác rưởi; chất dơ bẩn; vết nhơ; tài liệu đồi trụy; ngôn từ tục tĩu', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_4', 'en-c1-65', NULL, 'comprehensive_test', 'listening', 'Please coil the rope before putting it away.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vui lòng cuộn tròn sợi dây thừng lại trước khi cất đi.","Đứa bé đang ngủ say sưa trong một chiếc nôi bằng gỗ.","Tôi loay hoay tìm chìa khóa trong hành lang tối tăm.","Mưa đã làm cho địa chỉ trên phong bì trở nên không thể đọc được."]'::jsonb, 0, 'Please coil the rope before putting it away. → Vui lòng cuộn tròn sợi dây thừng lại trước khi cất đi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_5', 'en-c1-65', NULL, 'comprehensive_test', 'listening', 'sectional', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phụ; dự phòng; bổ trợ","thuộc dạng lắp ghép; cấu thành từ nhiều phần","sẵn sàng và có thể hoạt động hoặc sử dụng được","không tương thích; không tương hợp"]'::jsonb, 1, 'sectional (/ˈsekʃənəl/) → thuộc dạng lắp ghép; cấu thành từ nhiều phần; cục bộ; thuộc về một nhóm hoặc bộ phận riêng lẻ thay vì toàn thể', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_6', 'en-c1-65', NULL, 'comprehensive_test', 'listening', 'I fumbled for my keys in the dark hallway.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con mèo phát ra tiếng khì khì khi chú chó con tiến lại quá gần.","Trời đã mưa suốt năm ngày liên tiếp trong tuần này.","Tôi loay hoay tìm chìa khóa trong hành lang tối tăm.","Việc dọn dẹp khu vườn đã ngốn gần hết ngày thứ Bảy của chúng tôi."]'::jsonb, 2, 'I fumbled for my keys in the dark hallway. → Tôi loay hoay tìm chìa khóa trong hành lang tối tăm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_7', 'en-c1-65', NULL, 'comprehensive_test', 'listening', 'eventful', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà khí tượng học; chuyên gia khí tượng","lời chào hỏi; lời chào đầu thư","nhiều sự kiện; đầy biến động; nhiều chuyện","phân phối lại; bố trí lại"]'::jsonb, 2, 'eventful (/ɪˈventfəl/) → nhiều sự kiện; đầy biến động; nhiều chuyện', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_8', 'en-c1-65', NULL, 'comprehensive_test', 'listening', 'I slowly accustomed myself to sleeping with the window open.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi từ từ tập cho bản thân quen với việc ngủ mở cửa sổ.","Cô ấy vắt một ít nước chanh lên con cá nướng.","Đứa bé đang ngủ say sưa trong một chiếc nôi bằng gỗ.","Vui lòng cuộn tròn sợi dây thừng lại trước khi cất đi."]'::jsonb, 0, 'I slowly accustomed myself to sleeping with the window open. → Tôi từ từ tập cho bản thân quen với việc ngủ mở cửa sổ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_9', 'en-c1-65', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Made of separate sections that can be joined together”?', '["sectional","cradle","filth","accustom"]'::jsonb, 0, 'sectional (/ˈsekʃənəl/) → thuộc dạng lắp ghép; cấu thành từ nhiều phần', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
