INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_18', 'en-c1-65', NULL, 'comprehensive_test', 'reading', NULL, 'Several consecutive years of low rainfall have reduced agricultural output and increased pressure on regional water supplies.', 'Dựa vào câu trên, từ “consecutive” có nghĩa phù hợp nhất là gì?', '["vẻ bề ngoài; hình thái; sự giống phần nào","liên tiếp; liên tục không ngắt quãng","mang tính giải thích; mang tính minh họa","chủ quyền; quyền lực tối cao"]'::jsonb, 1, 'consecutive: liên tiếp; liên tục không ngắt quãng. Dịch cả câu: Nhiều năm có lượng mưa thấp liên tiếp đã làm giảm sản lượng nông nghiệp và gia tăng áp lực lên nguồn nước trong vùng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_19', 'en-c1-65', NULL, 'comprehensive_test', 'reading', NULL, 'Improved ventilation can keep classroom temperatures at tolerable levels without relying entirely on air conditioning.', 'Dựa vào câu trên, từ “tolerable” có nghĩa phù hợp nhất là gì?', '["có thể chịu đựng được","tiên đoán; báo trước","thư từ; sự trao đổi thư tín","tinh bột (chất có trong các loại thực phẩm như khoai tây, gạo và bánh mì)"]'::jsonb, 0, 'tolerable: có thể chịu đựng được; tạm được; kha khá; chấp nhận được. Dịch cả câu: Hệ thống thông gió được cải thiện có thể duy trì nhiệt độ lớp học ở mức có thể chịu đựng được mà không phải phụ thuộc hoàn toàn vào điều hòa.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_20', 'en-c1-65', NULL, 'comprehensive_test', 'reading', NULL, 'Without regular waste collection, filth can accumulate in residential areas and create serious public health risks.', 'Dựa vào câu trên, từ “filth” có nghĩa phù hợp nhất là gì?', '["truyền đạt; truyền thụ kiến thức, thông tin hoặc kỹ năng","buổi định hướng, tuần lễ sinh hoạt đầu khóa (giúp người mới thích nghi với môi trường mới)","rác rưởi; chất dơ bẩn; vết nhơ","làm cứng lại; trở nên cứng đờ, kém linh hoạt"]'::jsonb, 2, 'filth: rác rưởi; chất dơ bẩn; vết nhơ; tài liệu đồi trụy; ngôn từ tục tĩu. Dịch cả câu: Nếu không có dịch vụ thu gom rác thải thường xuyên, chất bẩn có thể tích tụ tại các khu dân cư và gây ra những rủi ro nghiêm trọng cho sức khỏe cộng đồng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_21', 'en-c1-65', NULL, 'comprehensive_test', 'reading', NULL, 'Engineers coil long pipes beneath buildings so that heat can be transferred efficiently from the ground.', 'Dựa vào câu trên, từ “coil” có nghĩa phù hợp nhất là gì?', '["tinh xảo; phức tạp; công phu","riêng biệt; độc lập; rời rạc","cuộn lại; xoắn lại thành vòng","vô hại; không có hại; không xúc phạm ai"]'::jsonb, 2, 'coil: cuộn lại; xoắn lại thành vòng; cuộn; ống xoắn; vòng dây. Dịch cả câu: Các kỹ sư bố trí những đường ống dài uốn lượn bên dưới các tòa nhà để nhiệt có thể được truyền từ lòng đất lên một cách hiệu quả.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_22', 'en-c1-65', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bản lề; khớp nối”', '["excavate","hinge","oceanography","shelve"]'::jsonb, 1, 'bản lề; khớp nối → hinge (/hɪndʒ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_23', 'en-c1-65', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dọn dẹp; thanh thải”', '["filth","inherent","uniformly","clearance"]'::jsonb, 3, 'dọn dẹp; thanh thải → clearance (/ˈklɪrəns/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_65_24', 'en-c1-65', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ấm cúng; giản dị như ở nhà”', '["screech","utterance","prosecutor","homely"]'::jsonb, 3, 'ấm cúng; giản dị như ở nhà → homely (/ˈhoʊmli/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-c1-66', 'en', 'Bài 66: Từ vựng Tổng hợp - CEFR C1', 'CEFR C1', 'C1 · Tổng hợp', '6 từ vựng Tiếng Anh CEFR C1 chủ đề tổng hợp đa chủ đề kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 5066, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sportsmanship', 'en-c1-66', 'sportsmanship', '/ˈspɔːrtsmənʃɪp/', 'C1', 'tinh thần thể thao; tác phong thể thao', 'n.', 'sportsman (n.), sportswoman (n.), sportsmanlike (adj.), unsportsmanlike (adj.)', 'Đồng nghĩa: fair play', 'Là danh từ không đếm được, nhấn mạnh thái độ công bằng và sự tôn trọng thay vì chỉ kỹ năng thi đấu.', 'Helping her opponent up showed real sportsmanship.', NULL, 'Hành động đỡ đối thủ đứng dậy cho thấy tinh thần thể thao cao thượng thực sự.', '{"wordId":"sportsmanship","ukIpa":"/ˈspɔːtsmənʃɪp/","usIpa":"/ˈspɔːrtsmənʃɪp/","cefr":"C1","topic":"sport","senses":[{"pos":"n.","en":"Fair and respectful behaviour towards opponents in sport","vi":"tinh thần thể thao; tác phong thể thao"}],"examples":[{"en":"Helping her opponent up showed real sportsmanship.","vi":"Hành động đỡ đối thủ đứng dậy cho thấy tinh thần thể thao cao thượng thực sự.","audioKind":"ex"},{"en":"School competitions should reward sportsmanship as well as achievement to encourage respect and cooperation among students.","vi":"Các giải đấu học đường nên tôn vinh cả tinh thần thể thao lẫn thành tích để khuyến khích sự tôn trọng và hợp tác giữa các học sinh.","audioKind":"ex2"}],"collocations":[{"en":"good sportsmanship","vi":"tinh thần thể thao cao thượng"},{"en":"show sportsmanship","vi":"thể hiện tinh thần thể thao"},{"en":"poor sportsmanship","vi":"thiếu tinh thần thể thao"}],"wordFamily":["sportsman (n.)","sportswoman (n.)","sportsmanlike (adj.)","unsportsmanlike (adj.)"],"synonyms":["fair play"],"antonyms":[],"tipVi":"Là danh từ không đếm được, nhấn mạnh thái độ công bằng và sự tôn trọng thay vì chỉ kỹ năng thi đấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feat', 'en-c1-66', 'feat', '/fiːt/', 'C1', 'kỳ tích, chiến công, hành động đòi hỏi kỹ năng, sức mạnh hoặc sự dũng cảm phi thường', 'n.', NULL, 'Đồng nghĩa: achievement, accomplishment', 'Phát âm giống từ feet; cụm từ no mean feat có nghĩa là một thành tựu rất đáng nể.', 'Carrying that huge sofa upstairs was quite a feat.', NULL, 'Việc khiêng chiếc ghế sofa khổng lồ đó lên lầu thực sự là một kỳ tích.', '{"wordId":"feat","ukIpa":"/fiːt/","usIpa":"/fiːt/","cefr":"C1","topic":"sport","senses":[{"pos":"n.","en":"An achievement requiring great skill, strength, or courage.","vi":"kỳ tích, chiến công, hành động đòi hỏi kỹ năng, sức mạnh hoặc sự dũng cảm phi thường"}],"examples":[{"en":"Carrying that huge sofa upstairs was quite a feat.","vi":"Việc khiêng chiếc ghế sofa khổng lồ đó lên lầu thực sự là một kỳ tích.","audioKind":"ex"},{"en":"Building a railway across mountainous terrain remains an impressive feat of engineering, even with modern technology.","vi":"Việc xây dựng một tuyến đường sắt băng qua địa hình núi non hiểm trở vẫn là một kỳ tích kỹ thuật đầy ấn tượng, ngay cả với công nghệ hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"an impressive feat","vi":"một kỳ tích ấn tượng"},{"en":"a feat of engineering","vi":"một công trình kỳ tích"},{"en":"no mean feat","vi":"một thành tựu lớn"}],"wordFamily":[],"synonyms":["achievement","accomplishment"],"antonyms":[],"tipVi":"Phát âm giống từ feet; cụm từ no mean feat có nghĩa là một thành tựu rất đáng nể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_volley', 'en-c1-66', 'volley', '/ˈvɑːli/', 'C1', 'cú đánh bóng trước khi chạm đất; cú volley; đánh bóng trước khi chạm đất; vô-lê; loạt đạn bắn loạt; tràng (lời nói, câu hỏi) dồn dập', 'n.', NULL, NULL, 'Trong thể thao, từ này chỉ việc đánh bóng khi bóng chưa chạm đất; cấu trúc a volley of còn có thể dùng để chỉ một chuỗi hành động hoặc lời nói dồn dập.', 'She won the tennis match with a sharp volley.', NULL, 'Cô ấy đã giành chiến thắng trong trận đấu quần vợt nhờ một cú vô-lê sắc bén.', '{"wordId":"volley","ukIpa":"/ˈvɒli/","usIpa":"/ˈvɑːli/","cefr":"C1","topic":"sport","senses":[{"pos":"n.","en":"a hit or kick before the ball touches the ground","vi":"cú đánh bóng trước khi chạm đất; cú volley"},{"pos":"v.","en":"to hit or kick a ball before it touches the ground","vi":"đánh bóng trước khi chạm đất; vô-lê"},{"pos":"n.","en":"a simultaneous firing of weapons or rapid series of remarks","vi":"loạt đạn bắn loạt; tràng (lời nói, câu hỏi) dồn dập"}],"examples":[{"en":"She won the tennis match with a sharp volley.","vi":"Cô ấy đã giành chiến thắng trong trận đấu quần vợt nhờ một cú vô-lê sắc bén.","audioKind":"ex"},{"en":"Learning to volley effectively helps young tennis players develop coordination and respond quickly under pressure.","vi":"Việc rèn luyện kỹ năng volley hiệu quả giúp các vận động viên quần vợt trẻ phát triển khả năng phối hợp và phản ứng nhanh nhạy dưới áp lực.","audioKind":"ex2"}],"collocations":[{"en":"a backhand volley","vi":"cú trái tay vô-lê"},{"en":"volley the ball","vi":"đánh bóng trên không"},{"en":"a volley of shots","vi":"một loạt phát súng"},{"en":"a volley of questions","vi":"một tràng câu hỏi dồn dập"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong thể thao, từ này chỉ việc đánh bóng khi bóng chưa chạm đất; cấu trúc a volley of còn có thể dùng để chỉ một chuỗi hành động hoặc lời nói dồn dập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_victorious', 'en-c1-66', 'victorious', '/vɪkˈtɔːriəs/', 'C1', 'giành chiến thắng; thắng lợi', 'adj.', 'victory (n.), victor (n.), victoriously (adv.)', 'Đồng nghĩa: triumphant · Trái nghĩa: defeated', 'victorious là tính từ; victory là danh từ chỉ sự chiến thắng.', 'The victorious team lifted the trophy above their heads.', NULL, 'Đội chiến thắng đã nâng cao chiếc cúp lên đỉnh đầu.', '{"wordId":"victorious","ukIpa":"/vɪkˈtɔːriəs/","usIpa":"/vɪkˈtɔːriəs/","cefr":"C1","topic":"sport","senses":[{"pos":"adj.","en":"Having won a competition, battle, or struggle.","vi":"giành chiến thắng; thắng lợi"}],"examples":[{"en":"The victorious team lifted the trophy above their heads.","vi":"Đội chiến thắng đã nâng cao chiếc cúp lên đỉnh đầu.","audioKind":"ex"},{"en":"Athletes who emerge victorious in international competitions often inspire younger generations to participate in sport.","vi":"Các vận động viên giành chiến thắng trong các giải đấu quốc tế thường truyền cảm hứng cho thế hệ trẻ tham gia thể thao.","audioKind":"ex2"}],"collocations":[{"en":"a victorious team","vi":"đội chiến thắng"},{"en":"emerge victorious","vi":"giành chiến thắng cuối cùng"},{"en":"a victorious campaign","vi":"một chiến dịch tranh cử thành công"}],"wordFamily":["victory (n.)","victor (n.)","victoriously (adv.)"],"synonyms":["triumphant"],"antonyms":["defeated"],"tipVi":"victorious là tính từ; victory là danh từ chỉ sự chiến thắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_endurance', 'en-c1-66', 'endurance', '/ɪnˈdʊrəns/', 'C1', 'sức bền; sự chịu đựng; độ dẻo dai', 'n.', 'endure (v.), endurable (adj.)', 'Đồng nghĩa: stamina', 'Thường là danh từ không đếm được, nhấn mạnh khả năng tiếp tục kiên trì bất chấp mệt mỏi hay khó khăn.', 'Swimming every morning has really improved my endurance.', NULL, 'Việc bơi lội mỗi buổi sáng thực sự đã cải thiện sức bền của tôi.', '{"wordId":"endurance","ukIpa":"/ɪnˈdjʊərəns/","usIpa":"/ɪnˈdʊrəns/","cefr":"C1","topic":"sport","senses":[{"pos":"n.","en":"The ability to continue despite tiredness, pain, or difficulty.","vi":"sức bền; sự chịu đựng; độ dẻo dai"}],"examples":[{"en":"Swimming every morning has really improved my endurance.","vi":"Việc bơi lội mỗi buổi sáng thực sự đã cải thiện sức bền của tôi.","audioKind":"ex"},{"en":"Regular physical activity builds endurance and helps people manage the demands of an increasingly sedentary lifestyle.","vi":"Hoạt động thể chất đều đặn giúp xây dựng sức bền và hỗ trợ con người đối phó với những đòi hỏi từ lối sống ít vận động ngày càng phổ biến.","audioKind":"ex2"}],"collocations":[{"en":"build endurance","vi":"xây dựng sức bền"},{"en":"physical endurance","vi":"sức chịu đựng thể chất"},{"en":"endurance training","vi":"huấn luyện sức bền"},{"en":"a test of endurance","vi":"thử thách sức bền"}],"wordFamily":["endure (v.)","endurable (adj.)"],"synonyms":["stamina"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được, nhấn mạnh khả năng tiếp tục kiên trì bất chấp mệt mỏi hay khó khăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rein', 'en-c1-66', 'rein', '/reɪn/', 'C1', 'dây cương ngựa; kiểm soát; kìm hãm', 'n.', NULL, NULL, 'Từ chỉ dây cương thường dùng ở dạng số nhiều reins; cấu trúc rein in có nghĩa là kiểm soát hoặc kìm hãm.', 'The rider gently pulled the reins to stop the horse.', NULL, 'Người nài ngựa nhẹ nhàng kéo dây cương để dừng con ngựa lại.', '{"wordId":"rein","ukIpa":"/reɪn/","usIpa":"/reɪn/","cefr":"C1","topic":"sport","senses":[{"pos":"n.","en":"A strap used by a rider to guide a horse.","vi":"dây cương ngựa"},{"pos":"v.","en":"To limit or control something, usually with in.","vi":"kiểm soát; kìm hãm"}],"examples":[{"en":"The rider gently pulled the reins to stop the horse.","vi":"Người nài ngựa nhẹ nhàng kéo dây cương để dừng con ngựa lại.","audioKind":"ex"},{"en":"Governments may need to rein in excessive spending while protecting essential services such as education and healthcare.","vi":"Các chính phủ có thể cần phải kiمل kiểm soát chi tiêu quá mức trong khi vẫn phải bảo vệ các dịch vụ thiết yếu như giáo dục và y tế.","audioKind":"ex2"}],"collocations":[{"en":"pull on the reins","vi":"kéo dây cương"},{"en":"rein in spending","vi":"kiểm soát chi tiêu"},{"en":"give someone free rein","vi":"cho phép ai đó tự do hành động"},{"en":"take the reins","vi":"tiếp quản quyền lực"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ chỉ dây cương thường dùng ở dạng số nhiều reins; cấu trúc rein in có nghĩa là kiểm soát hoặc kìm hãm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_66_1', 'en-c1-66', 'Cách dùng “volley” (n.) — cú đánh bóng trước khi chạm đất; cú volley', 'a backhand volley  ·  volley the ball  ·  a volley of shots', 'Trong thể thao, từ này chỉ việc đánh bóng khi bóng chưa chạm đất; cấu trúc a volley of còn có thể dùng để chỉ một chuỗi hành động hoặc lời nói dồn dập.', NULL, '[{"hanzi":"She won the tennis match with a sharp volley.","pinyin":"","meaning":"Cô ấy đã giành chiến thắng trong trận đấu quần vợt nhờ một cú vô-lê sắc bén."},{"hanzi":"Learning to volley effectively helps young tennis players develop coordination and respond quickly under pressure.","pinyin":"","meaning":"Việc rèn luyện kỹ năng volley hiệu quả giúp các vận động viên quần vợt trẻ phát triển khả năng phối hợp và phản ứng nhanh nhạy dưới áp lực."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_66_2', 'en-c1-66', 'Cách dùng “rein” (n.) — dây cương ngựa', 'pull on the reins  ·  rein in spending  ·  give someone free rein', 'Từ chỉ dây cương thường dùng ở dạng số nhiều reins; cấu trúc rein in có nghĩa là kiểm soát hoặc kìm hãm.', NULL, '[{"hanzi":"The rider gently pulled the reins to stop the horse.","pinyin":"","meaning":"Người nài ngựa nhẹ nhàng kéo dây cương để dừng con ngựa lại."},{"hanzi":"Governments may need to rein in excessive spending while protecting essential services such as education and healthcare.","pinyin":"","meaning":"Các chính phủ có thể cần phải kiمل kiểm soát chi tiêu quá mức trong khi vẫn phải bảo vệ các dịch vụ thiết yếu như giáo dục và y tế."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_66_3', 'en-c1-66', 'Cách dùng “endurance” (n.) — sức bền; sự chịu đựng; độ dẻo dai', 'build endurance  ·  physical endurance  ·  endurance training', 'Thường là danh từ không đếm được, nhấn mạnh khả năng tiếp tục kiên trì bất chấp mệt mỏi hay khó khăn.', 'Họ từ (Word Family): endure (v.), endurable (adj.) | Đồng nghĩa: stamina', '[{"hanzi":"Swimming every morning has really improved my endurance.","pinyin":"","meaning":"Việc bơi lội mỗi buổi sáng thực sự đã cải thiện sức bền của tôi."},{"hanzi":"Regular physical activity builds endurance and helps people manage the demands of an increasingly sedentary lifestyle.","pinyin":"","meaning":"Hoạt động thể chất đều đặn giúp xây dựng sức bền và hỗ trợ con người đối phó với những đòi hỏi từ lối sống ít vận động ngày càng phổ biến."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_c1_66_4', 'en-c1-66', 'Cách dùng “sportsmanship” (n.) — tinh thần thể thao; tác phong thể thao', 'good sportsmanship  ·  show sportsmanship  ·  poor sportsmanship', 'Là danh từ không đếm được, nhấn mạnh thái độ công bằng và sự tôn trọng thay vì chỉ kỹ năng thi đấu.', 'Họ từ (Word Family): sportsman (n.), sportswoman (n.), sportsmanlike (adj.), unsportsmanlike (adj.) | Đồng nghĩa: fair play', '[{"hanzi":"Helping her opponent up showed real sportsmanship.","pinyin":"","meaning":"Hành động đỡ đối thủ đứng dậy cho thấy tinh thần thể thao cao thượng thực sự."},{"hanzi":"School competitions should reward sportsmanship as well as achievement to encourage respect and cooperation among students.","pinyin":"","meaning":"Các giải đấu học đường nên tôn vinh cả tinh thần thể thao lẫn thành tích để khuyến khích sự tôn trọng và hợp tác giữa các học sinh."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_66_1', 'en-c1-66', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_1_1', 'ten_c1_66_1', 'sportsmanship', 'Helping her opponent up showed real sportsmanship.', 'Helping her opponent up showed real sportsmanship.', '/ˈspɔːrtsmənʃɪp/', 'Hành động đỡ đối thủ đứng dậy cho thấy tinh thần thể thao cao thượng thực sự.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_1_2', 'ten_c1_66_1', 'feat', 'Carrying that huge sofa upstairs was quite a feat.', 'Carrying that huge sofa upstairs was quite a feat.', '/fiːt/', 'Việc khiêng chiếc ghế sofa khổng lồ đó lên lầu thực sự là một kỳ tích.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_1_3', 'ten_c1_66_1', 'volley', 'She won the tennis match with a sharp volley.', 'She won the tennis match with a sharp volley.', '/ˈvɑːli/', 'Cô ấy đã giành chiến thắng trong trận đấu quần vợt nhờ một cú vô-lê sắc bén.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_1_4', 'ten_c1_66_1', 'victorious', 'The victorious team lifted the trophy above their heads.', 'The victorious team lifted the trophy above their heads.', '/vɪkˈtɔːriəs/', 'Đội chiến thắng đã nâng cao chiếc cúp lên đỉnh đầu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_1_5', 'ten_c1_66_1', 'endurance', 'Swimming every morning has really improved my endurance.', 'Swimming every morning has really improved my endurance.', '/ɪnˈdʊrəns/', 'Việc bơi lội mỗi buổi sáng thực sự đã cải thiện sức bền của tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_1_6', 'ten_c1_66_1', 'rein', 'The rider gently pulled the reins to stop the horse.', 'The rider gently pulled the reins to stop the horse.', '/reɪn/', 'Người nài ngựa nhẹ nhàng kéo dây cương để dừng con ngựa lại.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_66_1_1', 'en-c1-66', 'ten_c1_66_1', 'listening', 'listening', 'Helping her opponent up showed real sportsmanship.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc khiêng chiếc ghế sofa khổng lồ đó lên lầu thực sự là một kỳ tích.","Cô ấy đã giành chiến thắng trong trận đấu quần vợt nhờ một cú vô-lê sắc bén.","Người nài ngựa nhẹ nhàng kéo dây cương để dừng con ngựa lại.","Hành động đỡ đối thủ đứng dậy cho thấy tinh thần thể thao cao thượng thực sự."]'::jsonb, 3, 'Helping her opponent up showed real sportsmanship. → Hành động đỡ đối thủ đứng dậy cho thấy tinh thần thể thao cao thượng thực sự.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_66_1_2', 'en-c1-66', 'ten_c1_66_1', 'listening', 'listening', 'Carrying that huge sofa upstairs was quite a feat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đội chiến thắng đã nâng cao chiếc cúp lên đỉnh đầu.","Việc khiêng chiếc ghế sofa khổng lồ đó lên lầu thực sự là một kỳ tích.","Việc bơi lội mỗi buổi sáng thực sự đã cải thiện sức bền của tôi.","Người nài ngựa nhẹ nhàng kéo dây cương để dừng con ngựa lại."]'::jsonb, 1, 'Carrying that huge sofa upstairs was quite a feat. → Việc khiêng chiếc ghế sofa khổng lồ đó lên lầu thực sự là một kỳ tích.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_66_1_3', 'en-c1-66', 'ten_c1_66_1', 'listening', 'listening', 'She won the tennis match with a sharp volley.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc khiêng chiếc ghế sofa khổng lồ đó lên lầu thực sự là một kỳ tích.","Đội chiến thắng đã nâng cao chiếc cúp lên đỉnh đầu.","Cô ấy đã giành chiến thắng trong trận đấu quần vợt nhờ một cú vô-lê sắc bén.","Hành động đỡ đối thủ đứng dậy cho thấy tinh thần thể thao cao thượng thực sự."]'::jsonb, 2, 'She won the tennis match with a sharp volley. → Cô ấy đã giành chiến thắng trong trận đấu quần vợt nhờ một cú vô-lê sắc bén.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_c1_66_2', 'en-c1-66', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng C1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_2_1', 'ten_c1_66_2', 'sportsmanship', 'School competitions should reward sportsmanship as well as achievement to encourage respect and cooperation among students.', 'School competitions should reward sportsmanship as well as achievement to encourage respect and cooperation among students.', '/ˈspɔːrtsmənʃɪp/', 'Các giải đấu học đường nên tôn vinh cả tinh thần thể thao lẫn thành tích để khuyến khích sự tôn trọng và hợp tác giữa các học sinh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_2_2', 'ten_c1_66_2', 'feat', 'Building a railway across mountainous terrain remains an impressive feat of engineering, even with modern technology.', 'Building a railway across mountainous terrain remains an impressive feat of engineering, even with modern technology.', '/fiːt/', 'Việc xây dựng một tuyến đường sắt băng qua địa hình núi non hiểm trở vẫn là một kỳ tích kỹ thuật đầy ấn tượng, ngay cả với công nghệ hiện đại.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_2_3', 'ten_c1_66_2', 'volley', 'Learning to volley effectively helps young tennis players develop coordination and respond quickly under pressure.', 'Learning to volley effectively helps young tennis players develop coordination and respond quickly under pressure.', '/ˈvɑːli/', 'Việc rèn luyện kỹ năng volley hiệu quả giúp các vận động viên quần vợt trẻ phát triển khả năng phối hợp và phản ứng nhanh nhạy dưới áp lực.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_2_4', 'ten_c1_66_2', 'victorious', 'Athletes who emerge victorious in international competitions often inspire younger generations to participate in sport.', 'Athletes who emerge victorious in international competitions often inspire younger generations to participate in sport.', '/vɪkˈtɔːriəs/', 'Các vận động viên giành chiến thắng trong các giải đấu quốc tế thường truyền cảm hứng cho thế hệ trẻ tham gia thể thao.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_2_5', 'ten_c1_66_2', 'endurance', 'Regular physical activity builds endurance and helps people manage the demands of an increasingly sedentary lifestyle.', 'Regular physical activity builds endurance and helps people manage the demands of an increasingly sedentary lifestyle.', '/ɪnˈdʊrəns/', 'Hoạt động thể chất đều đặn giúp xây dựng sức bền và hỗ trợ con người đối phó với những đòi hỏi từ lối sống ít vận động ngày càng phổ biến.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_c1_66_2_6', 'ten_c1_66_2', 'rein', 'Governments may need to rein in excessive spending while protecting essential services such as education and healthcare.', 'Governments may need to rein in excessive spending while protecting essential services such as education and healthcare.', '/reɪn/', 'Các chính phủ có thể cần phải kiمل kiểm soát chi tiêu quá mức trong khi vẫn phải bảo vệ các dịch vụ thiết yếu như giáo dục và y tế.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_66_2_1', 'en-c1-66', 'ten_c1_66_2', 'listening', 'listening', 'School competitions should reward sportsmanship as well as achievement to encourage respect and cooperation among students.', NULL, 'Trong câu vừa nghe, từ “sportsmanship” mang nghĩa nào sau đây?', '["mang tính hủy diệt; tàn phá nặng nề","tạm thời; lâm thời","chủ nghĩa bảo hộ mậu dịch; chính sách bảo hộ","tinh thần thể thao; tác phong thể thao"]'::jsonb, 3, '“sportsmanship” (/ˈspɔːrtsmənʃɪp/): tinh thần thể thao; tác phong thể thao. Câu đầy đủ: School competitions should reward sportsmanship as well as achievement to encourage respect and cooperation among students.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_c1_66_2_2', 'en-c1-66', 'ten_c1_66_2', 'listening', 'listening', 'Building a railway across mountainous terrain remains an impressive feat of engineering, even with modern technology.', NULL, 'Trong câu vừa nghe, từ “feat” mang nghĩa nào sau đây?', '["thu thập và tổng hợp thông tin từ nhiều nguồn khác nhau; biên soạn","kỳ tích, chiến công, hành động đòi hỏi kỹ năng, sức mạnh hoặc sự dũng cảm phi thường","tán thành; ủng hộ; chủ trương","mức tiêu chuẩn; mức bình thường"]'::jsonb, 1, '“feat” (/fiːt/): kỳ tích, chiến công, hành động đòi hỏi kỹ năng, sức mạnh hoặc sự dũng cảm phi thường. Câu đầy đủ: Building a railway across mountainous terrain remains an impressive feat of engineering, even with modern technology.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
