INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_66_1', 'en-c1-66', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “sportsmanship” (/ˈspɔːrtsmənʃɪp/) có nghĩa là gì?', '["kỳ tích, chiến công, hành động đòi hỏi kỹ năng, sức mạnh hoặc sự dũng cảm phi thường","giành chiến thắng; thắng lợi","sức bền; sự chịu đựng; độ dẻo dai","tinh thần thể thao; tác phong thể thao"]'::jsonb, 3, '“sportsmanship” (n.): tinh thần thể thao; tác phong thể thao.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
