INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_66_4', 'en-c1-66', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “victorious” (/vɪkˈtɔːriəs/) có nghĩa là gì?', '["cú đánh bóng trước khi chạm đất; cú volley","sức bền; sự chịu đựng; độ dẻo dai","giành chiến thắng; thắng lợi","tinh thần thể thao; tác phong thể thao"]'::jsonb, 2, '“victorious” (adj.): giành chiến thắng; thắng lợi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_c1_66_5', 'en-c1-66', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “The ability to continue despite tiredness, pain, or difficulty.”', '["rein","sportsmanship","feat","endurance"]'::jsonb, 3, '“endurance” (/ɪnˈdʊrəns/) nghĩa là: sức bền; sự chịu đựng; độ dẻo dai.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
