INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_1', 'en-c1-66', NULL, 'comprehensive_test', 'listening', 'sportsmanship', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm cho lu mờ; làm cho nhỏ bé hẳn đi","thuộc về vùng núi cao; thuộc dãy An-pơ","tinh thần thể thao; tác phong thể thao","bờ vực; ranh giới; thời điểm ngay trước khi điều gì xảy ra"]'::jsonb, 2, 'sportsmanship (/ˈspɔːrtsmənʃɪp/) → tinh thần thể thao; tác phong thể thao', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_2', 'en-c1-66', NULL, 'comprehensive_test', 'listening', 'Carrying that huge sofa upstairs was quite a feat.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hành động đỡ đối thủ đứng dậy cho thấy tinh thần thể thao cao thượng thực sự.","Cô ấy đã giành chiến thắng trong trận đấu quần vợt nhờ một cú vô-lê sắc bén.","Việc khiêng chiếc ghế sofa khổng lồ đó lên lầu thực sự là một kỳ tích.","Người nài ngựa nhẹ nhàng kéo dây cương để dừng con ngựa lại."]'::jsonb, 2, 'Carrying that huge sofa upstairs was quite a feat. → Việc khiêng chiếc ghế sofa khổng lồ đó lên lầu thực sự là một kỳ tích.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_3', 'en-c1-66', NULL, 'comprehensive_test', 'listening', 'volley', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhắc lại; nhấn mạnh lại; tái khẳng định","cởi mở; khoáng đạt; tôn trọng sự khác biệt","cú đánh bóng trước khi chạm đất; cú volley","khó đọc; không đọc được; không thể đọc nổi (do chữ viết không rõ)"]'::jsonb, 2, 'volley (/ˈvɑːli/) → cú đánh bóng trước khi chạm đất; cú volley; đánh bóng trước khi chạm đất; vô-lê; loạt đạn bắn loạt; tràng (lời nói, câu hỏi) dồn dập', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
