INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_5', 'en-c1-66', NULL, 'comprehensive_test', 'listening', 'endurance', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm suy yếu dần; hủy hoại (lòng tin, quyền lực, hiệu quả)","tạm thời; lâm thời","trung úy (lục quân); đại úy (hải quân); sĩ quan cấp dưới","sức bền; sự chịu đựng; độ dẻo dai"]'::jsonb, 3, 'endurance (/ɪnˈdʊrəns/) → sức bền; sự chịu đựng; độ dẻo dai', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
