INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_13', 'en-c1-66', NULL, 'comprehensive_test', 'reading', NULL, 'School competitions should reward sportsmanship as well as achievement to encourage respect and cooperation among students.', 'Dựa vào câu trên, từ “sportsmanship” có nghĩa phù hợp nhất là gì?', '["khởi đầu; phát động; khởi xướng","quá mức kỹ tính; khó chiều; kén chọn","khả năng phục hồi, tính kiên cường, sức chống chịu","tinh thần thể thao; tác phong thể thao"]'::jsonb, 3, 'sportsmanship: tinh thần thể thao; tác phong thể thao. Dịch cả câu: Các giải đấu học đường nên tôn vinh cả tinh thần thể thao lẫn thành tích để khuyến khích sự tôn trọng và hợp tác giữa các học sinh.', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_14', 'en-c1-66', NULL, 'comprehensive_test', 'reading', NULL, 'Building a railway across mountainous terrain remains an impressive feat of engineering, even with modern technology.', 'Dựa vào câu trên, từ “feat” có nghĩa phù hợp nhất là gì?', '["tính tiết kiệm; sự chi tiêu tằn tiện","thuộc về cấu trúc; mang tính kết cấu","sự xa hoa; sự phung phí; tính vung tay quá trán","kỳ tích, chiến công, hành động đòi hỏi kỹ năng, sức mạnh hoặc sự dũng cảm phi thường"]'::jsonb, 3, 'feat: kỳ tích, chiến công, hành động đòi hỏi kỹ năng, sức mạnh hoặc sự dũng cảm phi thường. Dịch cả câu: Việc xây dựng một tuyến đường sắt băng qua địa hình núi non hiểm trở vẫn là một kỳ tích kỹ thuật đầy ấn tượng, ngay cả với công nghệ hiện đại.', 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_15', 'en-c1-66', NULL, 'comprehensive_test', 'reading', NULL, 'Learning to volley effectively helps young tennis players develop coordination and respond quickly under pressure.', 'Dựa vào câu trên, từ “volley” có nghĩa phù hợp nhất là gì?', '["người ngoại đạo; người không chuyên môn","cú đánh bóng trước khi chạm đất; cú volley","thuộc về nhận thức","hài hòa hóa; làm cho tương thích"]'::jsonb, 1, 'volley: cú đánh bóng trước khi chạm đất; cú volley; đánh bóng trước khi chạm đất; vô-lê; loạt đạn bắn loạt; tràng (lời nói, câu hỏi) dồn dập. Dịch cả câu: Việc rèn luyện kỹ năng volley hiệu quả giúp các vận động viên quần vợt trẻ phát triển khả năng phối hợp và phản ứng nhanh nhạy dưới áp lực.', 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_16', 'en-c1-66', NULL, 'comprehensive_test', 'reading', NULL, 'Athletes who emerge victorious in international competitions often inspire younger generations to participate in sport.', 'Dựa vào câu trên, từ “victorious” có nghĩa phù hợp nhất là gì?', '["hạn ngạch; chỉ tiêu; định mức","giành chiến thắng; thắng lợi","củng cố; làm vững chắc","giàn khoan; thiết bị khoan"]'::jsonb, 1, 'victorious: giành chiến thắng; thắng lợi. Dịch cả câu: Các vận động viên giành chiến thắng trong các giải đấu quốc tế thường truyền cảm hứng cho thế hệ trẻ tham gia thể thao.', 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_17', 'en-c1-66', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giành chiến thắng; thắng lợi”', '["plea","reel","victorious","purity"]'::jsonb, 2, 'giành chiến thắng; thắng lợi → victorious (/vɪkˈtɔːriəs/)', 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_18', 'en-c1-66', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sức bền; sự chịu đựng; độ dẻo dai”', '["outward","endurance","treble","volley"]'::jsonb, 1, 'sức bền; sự chịu đựng; độ dẻo dai → endurance (/ɪnˈdʊrəns/)', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_c1_66_19', 'en-c1-66', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dây cương ngựa”', '["reactor","rein","weld","youthful"]'::jsonb, 1, 'dây cương ngựa → rein (/reɪn/)', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
